INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2, '沙普塔隆的爪子', '强大的角鹰兽沙普塔隆已经被你杀死了，它的爪子将成为你胜利的象征。碎木哨岗的塞娜尼·雷心一定会对你的战利品感兴趣的。', '将沙普塔隆的爪子交给灰谷碎木哨岗的塞娜尼·雷心。', '真不错，$N……沙普塔隆的爪子可不是那么容易可以得到的!看来你的灰谷狩猎之行很顺利啊!$B$B伐木场的工人总是会受到沙普塔隆的袭击。毫无疑问的，当这头猛兽被你杀死的消息传出去之后，很多歌颂你英勇事迹的歌谣肯定会在灰谷营地及伐木场流传开来的!', '哦，强大的$C，我知道你会来的。你是要告诉我你在狩猎行动中的进展吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5, '饥肠辘辘的基特斯', '我已经困在这个鬼镇里好几个星期了，除了虫子和野草之外什么吃的都没有！我想吃点正常的食物，即使要多花点钱也无所谓。$B$B给我找点美食来，我就给你大笔的奖赏。$B$B听说夜色镇血鸦旅店的厨师格鲁奥做的黑蟹蛋糕很不错……', '和厨师格鲁奥谈一谈。', '你想要黑螃蟹蛋糕?也许我可以做一点给你……', '哦？有我兄弟的东西？爽！幸运之光今天可算照到我身上了！', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6, '加瑞克·帕德弗特的赏金', '加瑞克·帕德弗特，这个恶棍几周以来一直让我们的农民和商人心惊胆战，前几天有人在农场附近的小屋里看到了他的身影，大概在就是修道院东边过了桥以后的那片地方。带他的头颅回来见我，然后领取赏金吧！$B$B不过你要小心一点，$N。加瑞克身边总是有一帮暴徒，他可不是那么容易搞定的家伙。', '杀死加瑞克·帕德弗特，带着他的头颅到北郡修道院去找维里副队长。', '哈，你干掉他了!你为艾尔文森林做了一件好事，当然罗，你也获得了赏金。', '你找到加瑞克.帕德福特了吗?我们终于可以摆脱这个恶棍了吗?', '', '去艾尔文森林找北郡山谷的维里副队长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7, '剿灭狗头人', '你的第一个任务是清剿工作，$N。一个狗头人部族占据了北边的森林。到那儿去，把你能看到的狗头人歹徒都杀掉。尽量减少他们的数量，好让我们有一天能把他们从北郡彻底赶出去。', '杀死8只狗头人歹徒，然后向治安官玛克布莱德复命。', '干得好，$N那些狗头人不过是些小贼和懦夫，不过如果他们数量太多的话，还是会对我们构成威胁。而且，暴风城要面临的威胁已经足够多了。$B$B我为你成功的清剿行动表示我的敬意。', '你的猎杀行动进展如何，$N?你清剿那些狗头人恶党了吗?', '', '去艾尔文森林找北郡修道院的治安官玛克布莱德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8, '盗贼的交易', '嘿，伙计！帮我一个忙如何？大堆僵尸和蜘蛛实在让我应接不暇。$B$B现在我手里有一封要送到布瑞尔的信……送给一个名叫瑞尼的还是别的什么的旅店老板，别管她姓什么啦。$B$B总之，那里是一个舒适而温暖的小地方，里面都是些希望重返真实自我的瘟疫受害者，当然那里也是你休息的好去处。你应该自己去看看……如果你愿意跑一趟，我会给你不错的报酬的。', '把笔迹潦草的信件送给布瑞尔的旅店老板瑞尼。', '哦?有我的信?真是太好了!我一直在期待丧钟镇里亲爱的老母亲音信，她是那么的崇高与圣洁……我想知道她近况如何。$B$B什么?你觉得太开心?你不相信这是真的?$B$B啊，那你快滚吧，这封信是谁写给我的，跟你无关。走吧!快滚!$B$B等你有钱的时候再来吧!没出息的东西!$B$B用不了多久啊，你一定又经过什么冒险啊!什么类似愚蠢的事情，想回来休息。', '来啦来啦!是谁呀?$B$B这些可怜人的胃口还真是不小。请随便些……就像在家里一样。我叫芮妮，如果你有什么需要，我愿意效劳。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9, '清理荒野', '看看这片土地上都发生了些什么吧！这片土地曾为一群善良老实的农民们所有。但如今，一群该死的小贼把农民们全部赶走了。当然，除了老子我！但有些看守傀儡一直霸占着我的田地。$b$b如果你觉着自己能够胜任这份工作的话，我希望你能帮忙清除掉20台傀儡。完成了任务之后，记得回来拿酬劳。如果你把我这片田地上的傀儡清光了的话，就去清除旁边田上的傀儡吧。', '农夫萨丁要求你破坏掉20台看守傀儡。', '干得漂亮，哥们。你为自己挣到了不菲的酬劳呀。谁知道呢，或许有一天西部荒野又会富饶如初吧。', '啊，你回来了!你已经把那几片田上的看守傀儡清理干净了吗?二十台吗?', '', '去西部荒野找萨丁农场的农夫萨丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10, '谢申克的救赎', '啊，这真是太糟糕了！我派我手下最得力的助手，初级勘探员谢申克去沙漠东南面的那个叫做大裂口的地方进行探查。但是现在他失踪了，而他最后一份报告中显示大裂口到处都充斥着那些怪异的虫子。我现在已经派不出足够的人力来同时探查这片沙漠上的两大块重要的地区了。$B$B我想派你去大裂口找谢申克，求求你了！也许他已经……但至少请帮我拿回他的勘探设备来。我恐怕那是可怜的谢申克最后的遗产了。', '寻找初级勘探员谢申克的下落，把他或者他的勘探设备交给加基森的高级勘探员菲兹杜瑟。', '年轻的谢申克是个好哥林布。希望他没有白白牺牲，他的勘探设备中应该记录了一些有用的东西。$B$B看来我们一定要着手处理这些虫子了。它们是如此的贪婪和狡猾，从现在的情况来看，它们可能是被某个更强大的力量所控制着!如果真是这样，不仅是加基森，整个沙漠都要遭殃了!', '嗯，有什么消息吗?你看起来像是经过一场大战……谢申克是不是还活着呢?', '', '去塔纳利斯找加基森的高级勘探员菲兹杜瑟。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11, '悬赏河爪豺狼人', '有人在艾尔文森林的边界处看见了豺狼人，这些野蛮的动物在这儿肯定不会干什么好事。在了望塔南边的树林里有一大群豺狼人到处游荡，凭我们自己的兵力很难应付他们。$B$B任何帮忙清除这些豺狼人的勇士都会受到暴风城军方的嘉奖。把他们的彩色豺狼人臂章带给我以证明你杀了他们。', '给兵营的瑞尼尔副队长带去8个彩色豺狼人臂章。', '我知道你肯定忙了好一阵子!谢谢你，$N。', '你好，$N。你去杀豺狼人了吗……?', '', '去艾尔文森林找林边空地的瑞尼尔副队长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12, '西部荒野人民军', '人民军只一个目标：保护西部荒野的安宁，并将和平带回到这片土地上来。不幸的是，和平总是以鲜血的代价来换取的。$b$b我手下的一个斥候报告说，有一群迪菲亚捕兽者正在附近到处流窜并大肆破坏。最新的报告说他们出现在了西北方的詹戈洛德矿洞中，如果你想加入我们人民军的话，那么就先杀死15名迪菲亚捕兽者和15名迪菲亚走私者，然后回来向我复命。', '哨兵岭的格里安·斯托曼要求你杀死15名迪菲亚捕兽者和15名迪菲亚走私者，然后回去向他报告。', '做得好，$N。我的斥候见证了你英勇的行为。你也出色地证明了自己的实力。', '或许是我没说清楚吧，抱歉。为了证明你的能力足以效忠人民军和圣光，你必须杀死15名迪菲亚陷捕者和15名迪菲亚走私者，完成之后再回来找我吧。', '', '去西部荒野找哨兵岭的格里安·斯托曼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13, '西部荒野人民军', '有人看见一群凶残的迪菲亚抢劫者洗劫了金海岸矿洞和月溪镇，我们人民军绝不能对这样的事袖手旁观。马上就出发吧，$n，让圣光重新照耀西部荒野。$b$b金海岸矿洞就在哨塔西边的海岸附近，作为训练的第二部分，我希望你能杀死15名迪菲亚抢劫者和15名迪菲亚强夺者。', '哨兵岭的格里安·斯托曼要求你杀死15名迪菲亚抢劫者和15名迪菲亚强夺者，然后回去向他报告。', '因你这次勇敢的行动，我们已经确信你对人民军有着重要的价值。', '我们可没时间聊天了，$N。迪菲亚掠取者在正威胁着西部荒野人民的生命与财产的安全。你必须至少干掉15名迪菲亚掠取者和15名迪菲亚强夺者，这样我们也可以给他们传达一个明确的信息:这里不容任何邪恶势力入侵。', '', '去西部荒野找哨兵岭的格里安·斯托曼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14, '西部荒野人民军', '一些迪菲亚路霸最近一直在避开我们，到处作恶。根据我手下最可靠的探子们的线报，这些迪菲亚路霸通常沿着从这里到西部荒野南部的道路打家劫舍。我们觉得他们现在应该就躲在南部的山丘那边，计划着下一步的行动。以人民军的名义，去杀死那些家伙。', '哨兵岭的格里安·斯托曼要求你杀死15个迪菲亚路霸、5个迪菲亚巡路者和5个迪菲亚拳匪，然后回去向他报告。', '在离开洛丹伦那片受污染的土地之后，我回到了这里，回到了我的故乡，被迫要面对一种这样严酷的形势。但西部荒野仍然还有希望，你在战斗中的英勇与无畏告诉我，你正背负着无上的荣光与我们并肩作战，帮助我们完成伟大的事业。人民军中能有你这样的$C，让我感到无比自豪。愿圣光永远照耀着你。', '$N，现在可不是发呆闲聊的时候。如果你还想向人民军证明你的实力的话，就得去杀死我之前说的那些迪菲亚盗贼。完成任务之后在就回来向我汇报。', '', '去西部荒野找哨兵岭的格里安·斯托曼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (15, '回音山调查行动', '$N，我的探子告诉我说，狗头人群落的规模远远大于我们的估计，一群狗头人劳工刚刚入侵了北边的回音山矿洞。$B$B到矿洞里去，把他们都除掉。那里至少有8个狗头人劳工，杀光他们，如果你发现他们的数量远不止这么多的话，就赶快回报给我。', '杀死8只狗头人劳工，然后向治安官玛克布莱德复命。', '我真不想听到这些占据了我们圹坑狗头人的事情?真糟糕!他们是干不出什么好事来的。来，这是你的酬劳。另外，补给完毕以后再来找我一下。我希望你可以再去矿坑一次……$B', '你去过矿坑了吗?情况如何?', '', '去艾尔文森林找北郡修道院的治安官玛克布莱德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (16, '葛拉德的饮料', '', '', '谢谢，$N!如果你还想再交换的话就回来找我吧 !', '在田地里工作很容易让人口渴，我一直想要喝点清凉的泉水。$B$B如果你有的话，我愿意和你做个交换。', '', '去找暮色森林的葛拉德·提勒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (17, '奥达曼的蘑菇', '$N，我听说有一种紫色蘑菇刚刚被发现，它们似乎只在奥达曼挖掘场里生长。我需要十二个这样的蘑菇来进行炼金术的研究。$B$B你要多加小心，这种蘑菇会喷射出有毒的孢子。$B$B帮我这个忙吧，我会给你丰厚的报酬，另外还可以让你尝尝我收藏多年的好酒！', '收集12颗紫色蘑菇，把它们交给塞尔萨玛的加克。', '做得好，$N，你再一次证明了自己的价值!研究这种蘑菇肯定会非常有趣!$B$B根据我的承诺，来尝尝我收藏多年的陈年好酒吧!$B$B如果你是个有经验的炼金师，那我们还可以进行其它的合作。不管怎么样，我要再次感谢你对我的帮助。', '你拿到我需要的紫色蘑菇了吗?找不到我要的东西，我可不会付给你报酬的!', '', '去洛克莫丹找塞尔萨玛的加克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (18, '盗贼兄弟会', '最近, 一伙新来的流寇停留在北郡一带，为祸四方。他们自称为迪菲亚兄弟会，向东过了河之后就能找到他们。$B$B我不知道他们聚在一起到底想要干什么，但我确信他们不是什么好东西。给我带回一些他们的红色粗麻面罩，我就送你一把武器作为奖励。', '给北郡的维里副队长带回8个红色粗麻面罩。', '你带回着头巾回来了，干得好。暴风城军方感谢你的帮助。', '你已经收集到足够的头巾了吗?', '', '去艾尔文森林找北郡山谷的维里副队长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (19, '萨瑞尔祖恩', '黑石前锋和黑石叛节者经常在这里和石堡要塞之间伏击我们，这群前锋的指挥官是个名叫萨瑞尔祖恩的兽人。把他的徽记给我带来。', '将萨瑞尔祖恩的徽记带给湖畔镇的治安官马瑞斯。', '萨瑞尔祖恩是个卑鄙狡猾的兽人。你做得很好―我敢说你一定花了不少工夫才把他撂倒的。这是你的酬劳，$N。', '黑石氏族的兽人仍然在压制着我们。你干掉萨瑞尔祖恩了吗?', '', '去赤脊山找湖畔镇的治安官马瑞斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (20, '黑石氏族的威胁', '黑石氏族穿越了燃烧平原并攻下了北方的石堡要塞。他们以那座要塞为据点，劫掠湖畔镇北边的人们，吓得全镇的居民都不敢外出，只能躲在镇子里瑟瑟发抖。$B$B帮湖畔镇解决掉这个威胁吧。杀死黑石氏族的兽人，并带回来十把他们所用的破斧作为证明。$B$B尽管黑石氏族是在北方威胁着我们，但我们也收到了他们在赤脊山脉东南部出现的报告。你可以在那里找到他们，然后猎杀他们。', '给湖畔镇的治安官马瑞斯带回10把破斧。', '这下兽人的数量少太多了，我们也就不必太担心了，谢谢你。', '你杀掉多少兽人了，$N?有的话让我看看啊!', '', '去赤脊山找湖畔镇的治安官马瑞斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (21, '回音山清剿行动', '你上次的调查证实，回音山矿洞需要一次清剿行动。回到矿洞那边，帮我们清除那里所有的狗头人吧。$B$B抓紧时间，$N。狗头人无所顾忌地盘踞在矿洞里的时间越长，它们在北郡的据点也就越稳固。', '杀死8只狗头人苦力，然后向北郡修道院里的治安官玛克布莱德复命。', '我再次对你表示敬意，暴风城军方也感谢你。或许矿坑里还会有残余的狗头人活动，但我将会派遣其他人去解决他们。我们另有更重要的任务派给你。$B', '我知道这是场血战，$N，但清除狗头人对北郡的安全非常重要，你做得如何了?', '', '去艾尔文森林找北郡修道院的治安官玛克布莱德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (22, '猪肝馅饼', '削两个洋葱，剥一个大蒜，烤三片面包，剁半两香菜，切几块萝卜，熬一锅肉酱。现在……我还需要8个猪肝来完成我的绝世美味馅饼！', '萨尔玛·萨丁需要8片血牙野猪的肝来烹制猪肝馅饼。', '这些猪肝真新鲜，$N!太感谢你了。萨丁和我今天晚上就能吃一顿美味馅饼啦。这是给你的，感谢你帮我们找到猪肝。我可不能让你这样可爱的小$C给饿着了，对吧?', '猪肝馅饼怎么可以没猪肝!快去找猪肝，记得要八片!', '', '去西部荒野找萨丁农场的萨尔玛·萨丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (23, '乌萨苟斯的爪子', '强大的熊怪乌萨苟斯被你杀死了，它的爪子是你灰谷狩猎之行的战利品。爪上有一小块新月形的印记，这个印记的意义对你来说还是一个谜。$B$B你应该把这只爪子交给碎木哨岗的塞娜尼·雷心，以此证明你已经杀死了这只强大的猛兽。', '将乌萨苟斯的爪子交给灰谷碎木哨岗的塞娜尼·雷心。', '啊，乌萨苟斯的爪子!你的身手真是令人印象深刻，$C。死在它爪下的生命不计其数，这块新月形毫无疑问的证明它曾被那些隐藏在灰谷中的夜向导训练过。乌萨苟斯……曾经是这片本地最强大的野兽之一。能杀死这样的野兽表示你的意志和技艺都是无以伦比的。$B$B你的祖先会为你感到骄傲的!', '啊，$N―我正想着你呢!你的狩猎行动怎么样了?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24, '萨杜布拉的徽记', '敏捷而强大的萨杜布拉静静地躺在地上，你取得了最后的胜利。它的徽记是一件非常合适的战利品，碎木哨岗的塞娜尼·雷心肯定会想要看看这件战利品，然后对你在灰谷狩猎中取得的成绩予以嘉奖。', '将萨杜布拉的徽记交给灰谷碎木哨岗的塞娜尼·雷心。', '这是$N，在灰谷狩猎中又一次的胜利!做得好!毫无疑问地，萨杜布拉的头颅是件绝佳的战利品。$B$B萨杜布拉的残暴令它恶名昭彰，任何往西边去的旅行者，特别是那些徒步转至佐拉姆海岸的旅行者，总是会因为这头猛兽的存在而胆战心惊。谢谢你，现在这个危险已经被消除了。', '再次欢迎你，$N!你是来向我展示你完成狩猎的证明的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (25, '石爪山的困境', '如果你想做个有用的$c，那为什么不帮我们解决石爪山那边的困境呢？$B$B灰谷和石爪山脉之间的交通中断了，因为湖水中的生物突然开始攻击任何过路的旅行者……一个都不放过。你要做的并不仅仅是杀死那些水元素，你还要到密斯特拉湖中的眺望台上去一趟——在那里可以看到联盟前哨站的情况。$B$B你准备好了吗？', '清除位于碎木哨岗西南和石爪小径正东的密斯特拉湖一带的12个污浊的水元素。$B$B在密斯特拉湖上的眺望台中侦查联盟的前哨站。$B$B返回灰谷慰藉之林的碎木哨岗，向马斯托克·维尔西斯报告。', '啊，我听说有个$C像贫瘠之地的风暴一样席卷了整个湖泊。也许我们可以在那儿设立一个岗哨，密切注视我们的联盟朋友们。嗯，我们必须保持低调……$B$B你似乎相当能干，这里和石爪山之间的交通又恢复畅通了。拿着─这是你应得的。$B', '你回来了?那儿的情况怎么样─已经搞定了吗?', '在密斯特拉湖上的眺望台中侦查联盟的前哨站。', '去灰谷找碎木哨岗的马斯托克·维尔西斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (30, '海狮试炼', '第二个试炼是要寻找组成海狮坠饰的两个部分。其中的一半蕴含着海狮的敏捷天性，另一半蕴含着海狮那令人难以置信的耐力。德鲁伊汲取这两种特性，将它们运用到自己的水栖形态中。$B$B与月光林地中的居民谈一谈，找到这两个部分，并将它们合并起来。最后把合并好的坠饰交给德迪利特·星焰。', '寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。$B$B在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。$B$B将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。', '你合并了海狮坠饰，$N，恭喜你。$B$B寻找坠饰的每项任务都告诉我们，敏捷和耐力的协调一致在水下是非常必要的。两者不能独存，而如果你不利用海狮的形态，那幺这两者均不能实现。$B$B好好记着我说的话，一旦你掌握了水栖形态的知识，就得依赖它所代表的这两种特性了。$B', '你带来合并好的坠饰了吗，$N?如果你在寻找它们时遇到了麻烦，就跟这里的居民交谈以获取信息。这不仅能帮助你找到坠饰，还能帮助你探索这片神圣的土地。', '', '去月光林地找永夜港的德迪利特·星焰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (31, '水栖形态', '你已经学完了掌握水栖形态所必须具备的所有知识，现在回到雷霆崖的图拉克·符文图腾那儿去吧。把坠饰拿给他看看，以此证明你已准备好接受新的知识。他会让你掌握变化为水栖形态的诀窍，让你在水中灵活自如。$B$B再见，年轻的德鲁伊。我们会再见面的。', '回到雷霆崖，让图拉克·符文图腾看看你的海狮坠饰。', '很好，$N。你的祖先看到你有如此的成就，一定会非常高兴的!你已经做好学习水栖形态的准备了，我很高兴能将这项技能传授给你。$B$B此外，为了对你在这两次试炼中取得的成就表示赞许，我把这个给你。希望它能在你保持自然平衡的过程中对你有所帮助。', '你回到雷霆崖的消息早已传遍了这里，但是在我向传授你水栖形态的知识之前，我必须检验你在月光林地所学的成果。$B$B你把海狮坠饰拿来了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (32, '异种蝎的威胁', '这是我要你去递送的报告，马上把它送到能够对其内容有深入了解的那些人的手中。$B$B我知道一个名叫基尔兹宾·鼓眼的巨魔学者，他致力于研究卡利姆多大陆上的那些与艾泽拉斯生态格格不入的生物形态；他简直是一本活的生物书！如果你想要知道我们面临的是怎样的威胁，以及如何解决这个威胁，那就把这份报告交给他吧，我们现在需要一切可以得到的帮助。$B$B基尔兹宾应该住在奥格瑞玛暗巷区的第二层。', '把报告带给奥格瑞玛的基尔兹宾·鼓眼。', '这份报告……我以前确实对付过其中提到过的野兽。菲兹杜瑟很明智地让你把这份报告送到我这里来。$B$B这些生物会迅速吞噬塔纳利斯的沙漠，它们将会是我们有史以来所要面临的最大威胁。$N，记住这个名字:异种蝎。报告里提到的这些昆虫就是异种蝎，它们对部落和联盟来说都是一个巨大的威胁。$B$B除非我们能够早点意识到它的危害程度，否则后果不堪设想。', '很抱歉，我不认识你……但是看来你似乎对我已经有所了解了。我能帮你什么忙吗?或者你有什么东西要交给我?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (33, '林中的群狼', '影响那些狼的邪恶东西还没有消失。每天都有更多的狼受到感染。杀害自然的野兽让我感到痛苦，但我们必须消灭那些受到污染的幼狼，否则更大的灾祸就会接踵而至。$B$B消灭山谷中那些受到感染的幼狼，把它们的皮给我带回来，作为你行动的证据。', '给北郡修道院外的伊根·派特斯金纳带回8块病狼的皮毛。', '真是太辛苦你了!我已经等不及要去煮狼肉了……\r\n\r\n我这里有些东西你也许用得着……选一件吧!', '嘿，$N。我有些饿了……你拿到硬狼肉了吗?', '', '去艾尔文森林找北郡山谷的伊根·派特斯金纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (34, '不速之客', '前几天我的花园又被搞得一塌糊涂，不过现在我已经知道是哪个混蛋干的了。就是那只被治安官马瑞斯先生称作“贝利格拉布”的野猪。$b$b你瞧，我在下一季来临之前都没法种我的水仙花了。全毁了！一切都被那只混蛋野猪给毁了！把那祸害给我干掉！把它的獠牙给我带回来，我会付给你酬劳的。它一般就在湖畔镇西南的田边闲逛，但有时候也会跑进我的花园里来。', '湖畔镇的玛蒂·詹罗斯要求你杀死贝利格拉布，并带回它的獠牙作为证明。', '哈哈，终于把这个祸害除掉了。多谢你，$N，你做了一件好事。今年花园里的花一定会开得很茂盛!', '贝利格拉布还活着吗?还是你已经永远的替湖畔镇把这个祸害除掉了?', '', '去赤脊山找湖畔镇的玛蒂·詹罗斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (36, '杂味炖肉', '我从来没有想过有一天会被迫离开我的农庄。但是现在，那些满是小贼和强盗的田地对我们来说已经是太过危险了。等法布隆修好他的车之后，我们就要逃离这里了。$b$b或许你能帮我一个小忙？先让我把我的独家绝活杂味炖肉的食谱给抄下来，然后你帮我把它交给萨尔玛·萨丁。萨丁农场就在路口的另一边。', '弗娜·法布隆要求你将她的杂味炖肉食谱交给萨尔玛·萨丁。', '弗娜总是这么可爱。我们这些留在西部荒野的人一定会非常想念她的，她是个典型的都市女孩，一定会很快就能适应暴风城的生活方式的。好啦，就聊这么多啦!现在我们得开始做西部荒野炖肉啦!', '我还真是很想念弗娜.法布隆呀。我想，你在过来的路上应该是碰到她了吧?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (38, '杂味炖肉', '来帮我完成这道最华丽的西部荒野杂味炖肉吧！拜托啦，帮我找到以下这些材料：$b$b3块秃鹫肉条$b3只血牙野猪的头$b3只鱼人的眼睛$b3棵秋葵', '萨尔玛·萨丁需要3块秃鹫肉条、3只血牙野猪的头、3颗鱼人的眼睛和3棵秋葵。', '放入秋葵会使肉汤变得非常浓郁芳香!现在我们再放入秃鹰肉，一点鱼人的眼睛和美味的野猪鼻子，大功告成啦!为了答谢你的帮助，$N，来，我要请你先品尝一下今天的第一锅西部荒野炖肉!', '帮我找到这些材料:$B$B3块秃鹰肉', '', '去西部荒野找萨丁农场的萨尔玛·萨丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (46, '悬赏鱼人', '暴风城军队悬赏清除那些艾尔文森林内的鱼人潜伏者和鱼人强盗。杀了它们，把它们破损的鱼人鳞片给我带回来，暴风城军队会奖励你的。$B$B鱼人在北面的石碑湖附近建造了一座村庄，另外在南面的溪流分叉处还有一座村庄。', '给艾尔文森林东部的桥边的卫兵托马斯带去8个破损的鱼人鳞片。', '你拿到鱼鳍了?太好了!治安官杜汉对艾尔文森林东部日益猖獗的鱼人感到很担忧，现在看来形势已经在我们的控制之中了。$B$B你帮了我们的大忙，谢谢你。', '你的狩猎行动如何了，$N?', '', '去找艾尔文森林的卫兵托马斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (47, '金砂交易', '这一带的狗头人有时会带着金砂出来活动。我真的很需要这些金砂……给我找一些来，我会以镇子里最高的收购价格买下来——最高的价格！', '为闪金镇的雷米收集10袋金砂，这种东西可以从艾尔文森林的狗头人身上找到。', '谢谢你的金砂，$N。这是该给你的钱，还有……这是我的一个合伙人给我的，也许会对你有用。', '喂!你找到金砂了吗?', '', '去艾尔文森林找闪金镇的雷米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (49, '琥珀酒', '琥珀的颜色是我毕生之爱$b就像西山夕阳下的云彩$b为了它的诞生呀，勇敢的少年我召唤你$b我要黑麦、大麦和玉米！$b$bAmber is the hue of my life\'s longest love$bLike the last embers of dusk in the sky above$bRetrieve for me so that my love shall be born$bOne sack of each: barley, rye and corn!', '葛瑞姆·雷酒需要大麦、黑麦和玉米各一袋。', '嗝……!哈哈!', '再说一遍?当然没问题!$B$B琥珀的颜色是我毕生之爱$B就像天边夕阳下的云彩$B为了它的诞生呀，勇敢的少年我召唤你$B我要一袋黑麦、大麦和玉米!', '', '去西部荒野找匕首岭的葛瑞姆·雷酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (50, '琥珀酒', '我捣！我搅！我捣！我搅！$b少了玩意就没法搞好$b我要一种够硬的金属来当罐儿$b给我弄些真银来，我就唱完歌儿！ $b$bI\'ll mix and mix till we have a mash$bFor this will be our own private stash$bA still must be fashioned of metal strong$bBring me some Truesilver so I can finish this song!', '葛瑞姆·雷酒需要一些真银。', '嗝……!哈哈!', '你要我再给你唱一遍?当然行了，朋友!$B$B我捣!我搅!我捣!我搅!$B因为这是我们的私人珍宝$B我需要一种够硬的金属来做酒罐儿$B给我弄些真银来，好让我可以唱完这首歌!', '', '去西部荒野找匕首岭的葛瑞姆·雷酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (51, '琥珀酒', '还没过滤但是刚刚蒸馏$b就像是新皮甲还没上油$b然后得烧它七八斤炭呀$b我说你赶紧动身去办呀！$b$bNot yet filtered but freshly distilled$bLike unseeded land waiting there tilled.$bNext I will fashion our pile of charcoal$bDeliver a sycamore branch, that is your next goal', '带给葛瑞姆·雷酒一枝枫树枝。', '嗝……!哈哈!', '还想听一遍?你想怎么着都行!$B$B还没过滤但是刚刚蒸馏$B就像是新皮甲还没上油$B然后得烧它七八斤炭呀$B我说你赶紧动身去办呀!', '', '去西部荒野找匕首岭的葛瑞姆·雷酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (52, '保卫边境', '你好，$N。我们离开闪金镇越远，在森林里遇到的野生动物就越凶猛。东谷伐木场几乎每天都要受到狼和熊的攻击！$B$B我们需要你的帮助。', '杀掉8只觅食的灰狼和5只森林熊幼崽，然后回到艾尔文森林东部的桥边去见卫兵托马斯。', '非常感谢你的帮助，$N。森林里一定有什么东西让这些动物变得这么疯狂。$B$B不管那是什么，我希望它不要再搞出什么新名堂来了。', '你杀掉那些狼和熊了吗?', '', '去找艾尔文森林的卫兵托马斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (53, '琥珀酒', '甜美的液体清澈如婴儿泪$b百年的陈酿色深如琥珀$b但在把它放进地窖存着前$b造个橡木大桶来盛着先！$b$bMellifluous liquid clear as a baby\'s tears$bTurns a lovely deep amber over the years$bBut before we proceed to get lit to the hilt$bA barrel of charred oak must be built', '给葛瑞姆·雷酒带去一捆烧焦的橡木。', '酿造于老桶，过滤于煤渣', '当然，我可以为你再唱一遍!$B$B甜美的液体清澈如婴儿的眼泪', '', '去西部荒野找匕首岭的葛瑞姆·雷酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (54, '去闪金镇报到', '$N，如今你已经被证实是一位非常关心北郡的安全的$c了。现在我要派遣你去保卫艾尔文森林的周边地区。$B$B如果你接下了这个任务，就把这些文件送到闪金镇的治安官杜汉手里。沿着向南的大道走，穿过北郡的关卡就能看到闪金镇了。', '将治安官玛克布莱德的文件带给闪金镇的治安官杜汉。', '哦，信上说你被暴风城的元帅授予执行副队长的军衔，恭喜!$B$B另外，祝你好运，保卫艾尔文森林可不是在野餐……天知道这么多士兵忙来忙去都干了些什么，天知道他们都在为谁卖命!$B$B在这样黑暗的日子里，要站对立场都很困难啊……', '你有治安官玛克布莱德的信?和艾尔文森林相比，北郡就像是个花园，但我现在更关心治安官玛克布莱德有什么消息给我。$B$B来，让我看看他的信……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (55, '摩本特·费尔', '摩本特·费尔的老巢就在一个可以俯视乌鸦岭墓地的山顶上。他的日子就快要到头了……$B$B杀掉他，让我们不被他的邪恶所侵害。为我复仇吧，也为了夜色镇的人民！', '对摩本特·费尔使用摩本特的克星，杀掉他，然后把摩本特的克星交给斯温。', '摩本特.费尔被打败了。虽然黑骑兵还没被彻底消灭，但是我又看到了本已消逝的希望。$B$B你完成了一个几乎不可能完成的任务，你的事迹会永远被夜色镇的人民传颂。$B$B走吧，$N。也许有一天，命运还会把你带回我这里……', '你必须消灭摩本特.费尔!', '', '去暮色森林找寂静河岸的斯温·约根。', '杀死摩本特·费尔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (56, '守夜人', '作为守夜人的指挥官，我发过誓要保卫夜色镇人民的安全。暴风城已经把他们驻守在这里的部队撤了回去，现在我们只能依靠自己了。$b$b如果你觉得可以胜任，就请帮助我们吧！到夜色镇南部的静谧花园去，杀掉8个骷髅战士和6个骷髅法师。我们必须尽量减轻亡灵所能够带来的压力！', '夜色镇的指挥官指挥官阿尔泰娅·埃伯洛克要你去杀掉8个骷髅战士和6个骷髅法师。', '好极了，$N!我一定要表扬你为夜色镇所做的贡献!', '你怎么回来了，$N?如果你想要证明自己能对夜色镇有所帮助，就请帮我杀掉8个骷髅战士和6个骷髅法师。', '', '去暮色森林找夜色镇的指挥官阿尔泰娅·埃伯洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (57, '守夜人', '$N，我收到报告说有亡灵在森林里出没！如果你能应付的话，就到乌鸦岭的大墓地去杀15个骸骨魔和15个恐怖骸骨。另外，在夜色镇南部的静谧花园一带也都发现有骷髅在出没。我们一定要把这些亡灵驱逐出暮色森林！', '指挥官阿尔泰娅·埃伯洛克要你去杀掉15个骸骨魔和15个恐怖骸骨。', '夜色镇的人民感谢你的帮助，$N。你用行动证明了你是我们守夜人忠实的盟友。', '杀死15个骷髅魔和15个恐怖骷髅以后再回来见我，$N。', '', '去暮色森林找夜色镇的指挥官阿尔泰娅·埃伯洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (58, '守夜人', '乌鸦岭的形势仍然十分严峻，$N。但是我们没有足够的人手来保卫夜色镇的安全，对于乌鸦岭更是一筹莫展。你必须迅速赶到乌鸦岭去，在东部的陵墓里除掉20个瘟疫食尸鬼。', '夜色镇的指挥官阿尔泰娅·埃伯洛克要你到乌鸦岭的东部陵墓去杀20个瘟疫食尸鬼。', '作为守夜人的指挥官以及夜色镇人民的代表，我对你的英勇及贡献表示感谢，$N。愿圣光与你同在。', '我需要你的帮助，$N。到西北方的墓园去杀掉20个瘟疫食尸鬼。$B$B完成任务之后就回来告诉我。', '', '去暮色森林找夜色镇的指挥官阿尔泰娅·埃伯洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (59, '布甲和皮甲', '为了表彰你的智慧和勇敢，我把这个标记给你，用在护甲上应该很不错。你把它交给东谷伐木场的萨拉·迪博雷恩，她会为你做件合适的护甲。这件护甲在你为保卫艾尔文森林作战时应该用得到。$B$B东谷伐木场就在卫兵托马斯所在的哨所的东面。', '把暴风城护甲标记交给萨拉·迪博雷恩。', '啊，谢谢你拿来的标记，自己挑件护甲吧。$B$B祝你好运，勇敢的$C。希望这件护甲能对你有用。', '暴风城军队委托我给他们的士兵制作布甲和皮甲。$B$B如果你有标记给我的话，我很乐意给你也做一件。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (60, '狗头人的蜡烛', '你好，$g亲爱的先生:尊贵的女士;！你有时间吗？$B$B我和我兄弟在暴风城开了个药店，而我现在正要在这一带找些大蜡烛，以便提取其中的蜡。你能帮助我吗？$B$B你可以在狗头人身上找到大蜡烛，我听说在艾尔文森林的矿洞一带有很多狗头人……在南边的法戈第矿洞和东边的玉石矿洞里都有不少。我推荐你去这两个矿洞里看看。', '为闪金镇的威廉·匹斯特收集8支大蜡烛。', '找到这么多蜡烛很不容易吧?谢谢你拿来的蜡烛，$N，这是你的报酬……', '你收集到足够的蜡烛了吗?', '', '去艾尔文森林找闪金镇的威廉·匹斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (61, '送往暴风城的货物', '我兄弟莫根正在暴风城等我送蜡烛过去，但我自己实在忙得抽不开身。如果你愿意把这批货物送过去的话，他会重金酬谢你的。$B$B我已经把蜡烛装好了，莫根在我们的店里——匹斯特的药剂店，就在暴风城的贸易区。', '把威廉的货物交给暴风城贸易区的摩根·匹斯特。', '这是你的报酬……既然你都来了，就四处看看吧!说不定你会看上什么药剂或其它的小东西。', '哦，我兄弟让你送来的货?太棒了!我今天运气真好!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (62, '法戈第矿洞', '出问题的还不止北郡的矿洞！我接到报告说艾尔文森林的法戈第矿洞已经成了狗头人的天堂。$B$B去那里查看一下这些报告是否属实，然后回来告诉我。法戈第矿洞就在闪金镇的正南方，斯通菲尔德农场和马科伦农场之间。', '调查法戈第矿洞，然后回到闪金镇去见治安官杜汉。', '真是个坏消息。后面还会有什么?龙吗?我们必须在矿坑附近加派巡逻队。谢谢你的努力，$N。请等一下……我还有个任务给你。', '你有什么要报告的吗，$N?你去过法戈第矿坑了吗?', '侦察法戈第矿洞', '去艾尔文森林找闪金镇的治安官杜汉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (63, '水之召唤', '沿着银松森林海岸前行，在瑟伯切尔的西边有一处被瘟疫玷污过的神殿。那里的水灵不再和我们交谈，你的任务就是消灭那个污染源并净化那个水池。$B$B将元素护腕和剩馀的泉水放置在火盆上，就可以进行召唤水灵的仪式了。$\r\nB$B把能够证明你完成了任务的证据带回来给我，然后我就会给你图腾。', '击败堕落的水之魂，把堕落水之魂的护腕和剩馀的最纯净的水放在银松森林的圣泉火盆上。', '你把护腕放在火盆上，然后将馀下的泉水洒向跳动的火苗。水滴穿过火焰，发出劈劈啪啪的响声。你开始吟诵伊斯伦教你的咒语……', '火盆折射着周围的光芒，当你靠近时，火焰微微地扑动。$B$B山间的堕落气息似乎对此相当敬畏，看起来火盆已经可以进行召唤净化的水之灵体的仪式了。', '', '去银松森林找北流海岸的圣泉火盆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (64, '遗失的怀表', '太可怕了呀！弗娜一听到田里的骚动就把我叫醒了。你猜怎么着，田里全是小流氓。我们只能连夜逃出来，结果我就把我的怀表给忘在家里了。那块怀表是弗娜的爸爸在我们结婚的那天送给我的，我可不想让它落在那些盗贼手里。我应该是把那块表放在小农舍的衣柜里了，就在西边的那片南瓜田边上——你应该不会错过的。如果你能把它拿回来给我的话，我肯定会对你感激不尽的！', '农夫法布隆希望你能帮他找回他的怀表。怀表在西边南瓜田旁边的农舍的衣柜里。', '我的表!太感谢你啦，善良的$g先生:女士;!$B$B虽然我们只是一群失去了土地的穷苦农民，但仍请你收下这份酬劳，以表达我们对你的感谢。', '你找到我的怀表了没?', '', '去西部荒野找贾森农场的农夫法布隆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (68, '斯塔文的传说', '你在旧提箱里找到了一封复满灰尘的信。', '把复满灰尘的信交给书记员达尔塔。', '真有意思。这么说那个家伙确实是在月溪镇待了一段日子。奇怪的是这封信为什么没有寄出去?不管怎样，我得把档案更新一下。', '啊，我记得你。你是在打听那个斯塔文下落的人。你找到你想要的东西了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (70, '斯塔文的传说', '斯塔文的名字让我想起点什么…哦，想起来了！$b$b很多年前的一个雷雨交加的夜晚，有个信差到这儿来过夜避雨。快到午夜12点的时候，他一边尖叫着一边从楼上跑下来，苍白的脸上满是惶恐的神色，最后他穿着睡衣逃进了瓢泼的大雨中。$b$b由于走得太匆忙，他忘了拿走楼上箱子里的信，不过后来也没有再回来取过。喏，这一封是写给斯塔文的一个住在暴风城运河区的朋友的，你自己拿去看吧。', '从箱子中拿出斯塔文的未寄出的信，把它送到暴风城的运河区。', '敢把这东西拿过来，你还真有点胆量。', '你找到什么了?让我来瞧瞧……', '', '去找暴风城的管理员弗索姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (71, '回复托马斯', '把你找到的两块铭牌交给桥边的卫兵托马斯，让他知道两个卫兵的死讯。', '把罗尔夫和马拉凯的铭牌交给艾尔文森林东部桥边的卫兵托马斯。', '你证实了我所担心的，$N。我们不能再对鱼人的威胁视而不见了。', '你好，$N。你找到罗尔夫和马拉凯的下落了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (74, '斯塔文的传说', '你在箱子里找到了几样东西：一些有霉味的、看上去像是传家宝的东西，一副家庭肖像画，一些打猎所得的战利品和几本旧书。在箱子底部的一个花瓶下面，你找到了一张被撕破的日记书页。', '你找到的这张被撕破的日记书页给你提供了又一个线索。', '我看不清信上都写了些什么，不过这种书写方式让我想起了一些以前看到过的东西，那时候我的眼睛还没这么糟啊。', '你找到什么了?我的视力很差，根本看不清楚。把它放到我手上来，让我仔细瞧瞧。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (75, '斯塔文的传说', '我刚刚搬进来住的时候发现楼上的箱子里有一捆羊皮纸，我想看看那些羊皮纸上写了什么，但是迷雾却让我根本看不清楚。$b$b给我这个快瞎了的老人帮个忙吧，去检查一下楼上箱子里的东西，看看有没有什么有关斯塔文的信息。我记得有一张褪色的日记书页，你肯定会对它感兴趣的。把它拿过来，我会尽力帮助你的。', '治安官哈迦德要你从楼上的箱子里找出一张褪色的日记书页。', '你找到它了!', '你找到我所说的那页日记了吗，$N?', '', '去艾尔文森林找东谷伐木场的治安官哈迦德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (76, '玉石矿洞', '多亏了你，我们才知道法戈第矿洞里出现了很多狗头人。现在我们还需要一个人去更远处的玉石矿洞侦察。$B$B去查看一下玉石矿洞，确定那里是否有狗头人。向东沿着大路走，一直走到阿祖拉之塔，然后往北走就会看到山脚下的矿洞。', '查看玉石矿洞，然后回到闪金镇去向治安官杜汉报告。', '你是说玉石矿坑也有狗头人?该死!情况越来越糟了!$B$B谢谢你的报告，$N。不过我真希望你带来的是个好消息。', '你好，$N。你有什么要报告的吗?去玉石矿坑显示过了吗?', '侦察玉石矿洞', '去艾尔文森林找闪金镇的治安官杜汉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (77, '收集蜜糖', '我这里有德兰·杜佛斯需要的包装材料。我会帮助你为玛尔顿那烦人的老爸包装他要的蜜糖……不过你得给我多带几瓶蜜糖回来。它们就在靠近隐匿石一带，在那座荒废掉的部落村庄的箱子里，可恶的泥浆怪和软泥怪霸占了那块地方，有传言说它们是由一些大型软泥怪领导着的。但不管怎么样，你必须找到蜜糖并把它们带回来让我进行包装。', '从隐匿石一带被部落废弃的基地中的箱子里找到10瓶辛特兰蜜糖。', '你做得很好，$N。我很高兴你如此迅速地找到了我们需要的蜜酒。把这样的佳酿留在那里真是暴殄天物。$B$B我需要点魔法来让这些珍贵的货品改头换面，其实也不是什么魔法啦，只是，我这里正好有些空的辛特兰蜜酒包装。经过我的加工，它们马上就会变成极品的陈年老酒了。$B$B为了我们的成功，来干杯吧!', '我相信你回来一定是拿到任务需要的十瓶蜜酒了，是吧?', '', '去辛特兰找拉普索迪营地的基沃拉丁·猎日者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (78, '斯塔文的传说', '我知道有人可以帮你。我以前领导暴风城卫队的时候，经常去夜色镇的血鸦旅店喝酒。那儿的老板斯密茨对当地的情况了如指掌。把这张东西给他，看看他对此有什么说法。', '把褪色的日记书页带给暮色森林中夜色镇的旅店老板斯密茨。', '圣光在上!我当然认得这个笔迹。$B', '治安官哈迦德派你来的？怎么不早说？$B$B哈，狡猾的哈迦德。可怜的小伙子再过不久眼睛就会彻底瞎了。不说那些了，让我看看你带来的是什么。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (79, '斯塔文的传说', '多年来我一直在追寻这个斯塔文的消息。几年前那些来访的贵族被杀之后，我曾和哈迦德一起去调查。我发现了这些沾满泥污的纸，但是一直没有都想到把这上面的笔迹和树林里的那个疯子联系在一起。你提供的线索证明了他的罪行。赶快把这个交给指挥官阿尔泰娅·埃伯洛克，告诉她你所发现的一切。', '把沾满泥污的日记书页交给指挥官阿尔泰娅·埃伯洛克。', '天哪，你还真是块当探子的料，$C。', '你最好是真的有急事找我，$C。让我看看你带来的东西，再说说你的故事。以圣光之名，请你快一点。我的首要职责是保卫夜色镇，而不是把时间都浪费在毫无意义的事情上。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (80, '斯塔文的传说', '有一段时间我一直注意着斯塔文这个讨厌的家伙。如果这些东西都是他写的，那就足以给他定罪了。$b$b书记员达尔塔多年以来一直负责着镇里的档案，他很擅长辨认笔迹。把这张纸给他，看看是否和档案里面斯塔文的签名笔迹相吻合。', '把染血的日记书页交给书记员达尔塔。', '哦，没错!这张纸上的笔迹和档案里签名的笔迹完全一致。', '$N，你又回来了?这次你找到什么了?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (81, '送回蜜酒', '我在德兰要的东西上花了好大的工夫，因为除了额定装进桶里的蜜酒之外，他还要求额外再加几瓶！虽然我对德兰这个家伙的评价并不是很高，但是这世上没有比往酒桶里死命塞瓶子更糟的事情了……你来得正是时候。$B$B现在把这个桶送到德兰·杜佛斯那里去，他在奥格瑞玛那里自己开了一家店。顺便代我向玛尔顿问好，我很希望能有机会再和他畅饮几杯。', '把桶交给奥格瑞玛的德兰·杜佛斯。', '好吧，让我们看看桶里是什么!$B$B没错，我要的都在这里了。这是给你的报酬，干得好。我可以马上以五倍的价格把它卖给酒馆了!哈哈!$B$B至于这多出来的几瓶辛特兰蜜酒……我会把它们留在特殊的场合再喝。我想到时候会和香槟混合起来，我会把它叫做―无双蜜酒!', '如果你不是来买东西或是有东西要交给我的话，那你就是在浪费我的时间!你最好已经把蜜酒弄来了!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (82, '腐化之巢', '好吧，你的报告中提到了虫子……我们现在知道的是……它们正使得原本是腐化之巢所在区域的水池变得干涸，其它方面我们一无所知。$B$B首先我们要搞清楚敌人到底是谁！你得去腐化之巢那里，把那些虫子的肢体带回来给炼金师匹斯特苏格研究，这样我们就可以确定到底是谁在那里搞鬼了！', '从腐化之巢找5个森提帕尔昆虫肢体，把它们交给加基森的炼金师匹斯特苏格。', '漂亮―我现在就开始分析这些东西!虽然还没有经过仔细研究，但是我敢肯定的是，我以前从来没有看见过像这样的昆虫，它们显然被某种外力改变了身体的结构。$B$B你现在应该马上去找菲兹杜瑟，很显然地，他将会需要你来帮忙处理这个紧急情况!虽然我还不能很肯定，但是看来整个塔纳利斯沙漠都有大麻烦了!', '你是初级勘查员$N?快点行动吧，现在情况很紧急!你拿到菲兹杜瑟要你去取的那些昆虫肢体了吗?', '', '去塔纳利斯找加基森的炼金师匹斯特苏格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (83, '红色亚麻布', '北郡的迪菲亚盗贼戴粗麻布面罩，而艾尔文森林的迪菲亚盗贼戴的是亚麻布的，我可以用这些好的亚麻布做些东西。$B$B给我找些亚麻布面罩，我可以用来给你做点什么。$B$B有人在西南部的布莱克威尔南瓜田外看见过迪菲亚盗贼出没。', '给东谷伐木场的萨拉·迪博雷恩带去6块红色亚麻布面罩。', '啊，这些头巾很不错，就是还有点劣质……$B$B这是给你的!$B', '我的亚麻布不够了，$N。你能帮我找点来吗?', '', '去艾尔文森林找东谷伐木场的萨拉·迪博雷恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (84, '比利的馅饼', '这是你要的馅饼。把这东西交给那个比利的时候，别忘了告诉他我希望他吃了噎死！', '把猪肉馅饼带给马科伦农场的比利·马科伦。', '嗯，真好吃!这个馅饼太棒了!$B$B我好像想起些什么来了……', '呃……我快饿死了!你拿来我要的馅饼了吗，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (86, '比利的馅饼', '给我吃点馅饼，也许我就能想起来是谁拿着项链了。我知道另一个农场里的波尼斯老太太做的猪肉馅饼很棒……$B$B我们的农场周围有野猪，如果你能给她找几块野猪肉，她就应该会给你烤一块馅饼。', '给斯通菲尔德农场的波尼斯·斯通菲尔德带去4块野猪肉。', '这些野猪肉有些粗糙，所以要煮很长时间才能用来做成美味的馅饼!', '我怎么能给那个偷了我项炼的小孩子做吃的?不过如果只有这样才能把我的项炼找回来，那也只好这么做了!$B$B你有野猪肉吗?', '', '去艾尔文森林找斯通菲尔德农场的波尼斯·斯通菲尔德姑妈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (87, '金牙', '我在法戈第矿洞旁边玩的时候，不小心掉了那根，呃……我是说我看见了那个老太太的项链。别问我它怎么会在那儿……和我没有关系！$B$B不管怎样，我看到一个很壮实的镶着金牙的狗头人……他把项链捡起来跑到矿洞里了。你去找那个狗头人吧，我发誓，你肯定能在他身上找到项链的！', '把波尼斯的项链带给斯通菲尔德农场的波尼斯·斯通菲尔德。', '啊，你找到它了!谢谢，谢谢你，亲爱的$N!$B$B请拿着这个。这是我丈夫的遗物，他总是说这个能带来幸运。如果他最后一次作战的时候没有忘记带上它就好了!*鸣鸣*$B$B', '你好，$N。你找到我的项炼了吗?', '', '去艾尔文森林找斯通菲尔德农场的波尼斯·斯通菲尔德姑妈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (88, '公主必须死！', '布拉克威尔一家有一头得过奖的猪，它名叫“公主”。这头母猪巨大无比，还经常偷偷溜到我的农场里偷吃我的蔬菜！$B$B在它再次糟蹋了我的农场之前……必须把它给宰了！把它的项圈带回来证明你杀了它，我会给你一些奖赏的！$B$B公主一般在布莱克威尔南瓜田出没，那个南瓜田就在东边，比马科伦农场还要往东。在它肚子饿了之前杀死她，然后再回来告诉我！', '杀掉公主，把它的项圈带给斯通菲尔德农场的斯通菲尔德妈妈。', '感谢老天爷!那头猪那么胖，简直可以吃掉我们所有的庄稼!谢谢，$N。$B$B这儿有什么你想要的吗?', '你看到它了吗?干掉它了吗?', '', '去艾尔文森林的斯通菲尔德农场找斯通菲尔德妈妈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (89, '止水湖上的桥', '上次兽人入侵的时候，我们被迫把所有能找到的铁都熔了来制造子弹、刀剑和盔甲。万不得已，我们向暴风城请求援助，让他们运一船金属材料过来。谁料一群赤脊山豺狼人劫持了运送金属的船只，并逃进了湖畔镇后的山中。$b$b这样一来，我们这座桥的重修工程马上就要面临缺少材料的困境了。如果你能给我带回5根铁矛和5个铁铆钉，我一定会奖励你的。$b$b快点去吧！', '给湖畔镇的工头奥斯洛带回5根铁矛和5个铁铆钉。', '做的好，$N。这些材料一到，我们就能好好地大干一场了!现在就开工吧!', '这桥可不会自己把自己造出来!铁矛和铁铆钉在哪儿呢?', '', '去赤脊山找湖畔镇的工头奥斯洛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (90, '干烤狼肉串', '干烤狼肉串是有口皆碑的美食！你想吃吗？我当然可以为你做一些，不过得先给我找点材料。给我找些暴风城特产调料外加10块狼肋排来就可以了。这儿的森林里遍地都是狼，想找点肋排肯定不是问题。至于调料，你得到暴风城运河区的花店里去找菲利希亚·加姆。', '收集10块狼肋排和1份暴风城特产调料，再回夜色镇去找厨师格鲁奥。', '做得好，$N!尝尝美味的烤狼肉串吧!', '你找到10块狼肋排了吗?那暴风城菲利希亚的调味料呢?', '', '去暮色森林找夜色镇的厨师格鲁奥。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (91, '所罗门的律法', '暴风城的一群死敌在赤脊山的东侧的山脚下创建起一片营地，这些邪恶的暴徒一直在我们的小镇中传播着恐惧。莫甘斯是这群恶徒的头领。$b$b他已经控制了暗皮豺狼人氏族，让那些邪恶的野兽为他卖力。根据湖畔镇的法律规定，协犯最高可以被判处死刑。$b$b这些肮脏的豺狼人一定要被处死！$b$b给我带回10个暗皮坠饰来，你就可以得到我们的奖励。', '给湖畔镇大厅的拜里弗·科纳彻尔带回10个暗皮坠饰。', '湖畔镇的法庭认可你对正义所做出的贡献，$N。你执行王国的法律，维护了正义的尊严。', '交回10个影皮坠饰给我，你就可以得到我们的奖励。', '', '去赤脊山找湖畔镇的拜里弗·科纳彻尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (92, '赤脊山炖肉', '没什么能比烹制赤脊山炖肉更让我高兴的事了，但是现在有个小问题。自从兽人们出现之后，我就得没日没夜地忙着给暴风城军队的整整一个旅供应食物，我的食品柜早已是空空如也了。如果你能给我找来一些材料的话，我很乐意给你做点好吃的。$b$b只要给我带来5块硬秃鹫肉，5个巨型血牙野猪头和5份香脆蜘蛛肉就行了。', '湖畔镇的厨师布雷纳想要5块硬秃鹫肉，5个巨型血牙野猪头和5份香脆蜘蛛肉。', '太好了，$N。多好的材料呀!来，这就是你期待已久的赤脊山炖肉!', '我还需要5块硬兀鹰肉，5个巨型血牙野猪头和5份香脆蜘蛛肉。', '', '去赤脊山找湖畔镇的厨师布雷纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (93, '黑蟹蛋糕', '我可以告诉你个秘密——黑“蟹”蛋糕实际上是用蜘蛛腿做的！听起来是有点恶心，不过这种蛋糕的味道绝对一流！给我找点粘糊的蜘蛛腿来，我很快就能给你做好。$B$B听说结网毒蜘蛛身上很容易拿到这种东西——它们的巢穴就在东北部的丘陵和\r\n小河之间，暮色森林里的其它蜘蛛身上也有这东西。', '收集6条粘糊的蜘蛛腿，把它们交给夜色镇的厨师格鲁奥。', '嗯，这些蜘蛛腿还挺不错的嘛!让我再加点我的调味秘方(不许看!)，然后再煮上一会儿……$B$B这种黑蟹蛋糕是我的拿手绝活，所以配方必须要保密，不过我可以给你另外一种美食的食谱。', '你好啊，$N。找到粘糊的蜘蛛腿了吗?', '', '去暮色森林找夜色镇的厨师格鲁奥。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (94, '法师的眼线', '我的对手莫甘斯是个强大而邪恶的法师，他就住在赤脊山的伊尔加拉之塔里。我已经找到了一种监视他的方法，只要通过阿祖拉之眼，就可以在很远的地方看到他的一举一动。$B$B不过要研究他的思想……我还需要进一步的帮助。$B$B如果你愿意的话，就带着这个铭文饰品到伊尔加拉之塔去，把它放置在塔旁边的狮子雕像身上。$B$B完成之后，阿祖拉的铭文饰品就会告诉我们，莫甘斯又在准备什么邪恶的计划。', '把阿祖拉的铭文饰品放置到赤脊山伊尔加拉之塔旁边的狮子雕像身上。', '你把阿祖拉雕纹放在石头上，它很快自己贴了上去……你听见饰品中传出塞欧克瑞图斯的声音:$B$B我很感激你，年轻的$N。你现在可以通过这个雕纹和我交流，等我查明了他的计画之后……也许我还有别的任务会交给你。', '这个狮子雕像已有几十年的历史了，它一直孤孤单单地看守着声名狼籍的伊尔加拉之塔。$B$B雕像的底部有一处凹陷，那里正好可以放置一块宝石或者雕纹……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (96, '水之召唤', '拿着碎片，拿着碎片……赋予生命。$B$B赋予生命……理解生命，理解水就是生命本身……而堕落则会扼杀生命。$B$B你保护了生命，并将水的力量赋予了生命……', '把水灵碎片交给贫瘠之地提度斯阶梯的水之先知伊斯伦。', '这就是我要的证明，你做的得好，$N!$B$B我很高兴能够成为第一个向你祝贺的人，拿着这个……属于你的水之图腾。$B$B好好地利用它，祝你好运。$B$B离你的下一次试炼还有很长的时间，所以接下来你要好好地回顾你所学到的东西。纯洁的水不仅能让那些受伤的人恢复活力，也能产生更多其它的效果。如果你有时间的话，我建议你去找一个萨满训练师，他们或许能教你些别的咒语。$B', '你回来了，太好了!$B$B你的银松森林之旅怎幺样?花了不少时间吧?$B$B我很难判断你是否在那里获得了成功，因为已经有如此多的地方彻底堕落了。你所做的一切在邪恶的力量面前还是显得微不足道，但是即便是微小的胜利，有时都会和重大的胜利一样重要。净化那里的水对于你和所有的萨满都很重要。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (97, '斯塔文的传说', '$N，你赶快去告诉指挥官阿尔泰娅·埃伯洛克，这两个笔迹完全符合！她的怀疑是正确的！', '把这个消息告诉指挥官阿尔泰娅·埃伯洛克。', '我就知道会是这样!做得好，$N!', '嗯，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (98, '斯塔文的传说', '斯塔文·密斯特曼托是个恶贯满盈的罪犯，很多无辜的人都死在他手中。毫无疑问，他犯下了无数宗罪案，给夜色镇带来了又一个威胁。天知道这个恶棍又在策划什么邪恶的行动。斯塔文的家就在小镇北边，$C，你去把他就地处死吧。$b$b完事以后把他的系列戒指带给伊瓦夫人作为证明，毕竟是她的预感导致我们揭露了这个可怕的凶手，她为夜色镇立了一功。', '干掉斯塔文·密斯特曼托，把他的系列戒指带给伊瓦夫人看看。', '我知道，$N!斯塔文死了，我能感觉到希望正在这片受污染的森林里重生。暮色森林终于可以摆脱他的威胁了。不过高兴之馀，我还是为那些死在这个杀人狂手里的无辜者们感到悲伤。不管怎么说，你的确是一个勇敢而机智的$C。', '嗯，$N?', '', '去暮色森林找夜色镇的伊瓦夫人。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (99, '阿鲁高的愚行', '在我对阿鲁高的魔法的越来越了解的同时，我对这个蠢货的鄙视与轻蔑也日益加深。我基本上完成了我对他所谓“拯救”的研究。$b$b在我了解到是什么样的巫术导致了焚木村的奇怪现象之后，我也就算是了解透彻了。白天，那些农夫们都是好端端的人。但太阳一落山，他们就变成了月怒狼人。$b$b我需要从阿鲁高给他们戴上的镣铐提取出一些能量来。带给我6副焚木镣铐，$N。', '给瑟伯切尔的达拉尔·道恩维沃尔带回6副焚木镣铐。', '你的努力值得表扬。根据你帮助我收集到的资讯，阿鲁高一定会被击败，他不计后果的魔法也一定会被恢复原状的。恭喜你，$N。', '你拿到焚木镣铐了吗，$N?', '', '去银松森林找瑟伯切尔的达拉尔·道恩维沃尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (101, '惩罚图腾', '有一股神秘而邪恶的势力在森林里蔓延，我们必须更加小心地保护自己，$N。林中的夜风悄声告诉我，你很快就会遭遇巨大的危机。$b$b尊贵的$c，如果你想保护自己，就请给我找来10颗食尸鬼的牙齿、10根骷髅的手指和5瓶蜘蛛毒液。我会为你制作一个惩罚图腾，让那些企图伤害你的敌人自食其果。', '收集10颗食尸鬼的牙齿、10根骷髅的手指和5瓶蜘蛛毒液，把它们交给夜色镇的伊瓦夫人。', '你很明智，$N。这个惩罚图腾可以保护你，使你不致被潜伏于整个艾泽拉斯的邪恶势力所影响。当你发现有危险时，握住这个图腾，并安心的待在魔力光环内吧。勇敢点，尊贵的$C。我看到你的未来将会发生很多艰困和挫折，你必须鼓起全部地勇气来面对它们。$B', '找10颗食尸鬼的牙齿、10根骷髅的手指和5瓶蜘蛛毒液来给我，我会为你制作一个惩罚图腾，让那些企图伤害你的敌人自食其果。', '', '去暮色森林找夜色镇的伊瓦夫人。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (102, '西部荒野的豺狼人', '暴风城已经把我们给遗弃了。一股腐朽与堕落的狂风正肆虐在西部荒野的平原之上。这里是我的故乡，我绝对不会背叛那些和我一样坚持留在这里的民众们。我们这些农夫必须站出来，为自己赢得生存的空间。$b$b若你愿意接受我们派给你的任务，就去巡视西部荒野的草原吧。找到那些可恶的豺狼人，把它们干掉，似乎这些家伙与死亡矿井里的小贼们有些联系。给我带回八只豺狼人的爪子来，我会奖励你的英勇行为的。', '给哨兵岭的丹努文队长带回8只豺狼人的爪子。', '干得好，$N。有你这样的冒险者与我们人民军一起英勇地战斗，西部荒野终有一天会再次成为富饶的粮仓。请收下这件礼物，把它作为我们对你努力不懈的认可吧。', '你从那些阴险的豺狼人身上拿到8只爪子了吗?', '', '去西部荒野找哨兵岭的丹努文队长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (103, '长明的灯塔', '灯塔管理员一家被杀的那一个晚上实在是太可怕啦！我就那样无助地看着老瞎眼带着那群鱼人毁了他们全家。但过去的事就让它过去吧，我现在关心的是无尽之海中那些正把船只驶近暗礁的水手们的生命。如今，维持着灯塔上火炬不至熄灭的任务就落在我一个人身上了。$b$b从那些收割机器人身上找来5瓶灯油吧，这样我才能保住火炬上的火种。', '给西部荒野灯塔中的葛瑞森船长带回5瓶灯油。', '我赞美你，勇敢的$C。由于你的努力，西部荒野海岸旁的礁石将会被照亮。长明的灯火会拯救许多人的生命。$B$B我就是因为船只撞进了那片礁石才死去的，我绝对不会再让任何人步上我的后尘了。', '灯油用完之后火炬马上就会熄掉了，$N。', '', '去西部荒野找西部荒野灯塔的葛瑞森船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (104, '海岸上的威胁', '当我的生命终结在了那片岩石上之后，我根本不知道死后的世界会是怎样的。那天晚上的灯塔一片漆黑，因为老瞎眼吓跑了管理员全家。他们本已经逃跑了，但那天晚上他们又回来想要点亮灯塔，结果老瞎眼带着一群野蛮的鱼人突袭了灯塔。这一次，管理员的全家都在我面前无助地死去了……$b$b如果你在海岸边看到老瞎眼的话，就杀死它，把它的鳞片给我带回来，我会奖励你的。', '将老瞎眼的鳞片交给西部荒野灯塔旁的葛瑞森船长。', '老瞎眼这个邪恶而卑鄙的家伙终于死了。干得好，$N。虽然有一条生命死在你的手上，但更多的生命会因此而获救。无尽之海虽然还是暗藏着数不清的危险，但在你英勇地斩杀了老瞎眼家伙之后，今夜它似乎又安全了许多。', '你已经消除了老瞎眼的威胁了吗?有人看见它今天早上在西部荒野的海岸线上闲逛。$B$B把这只邪恶的野兽干掉以后再回来找我。', '', '去西部荒野找西部荒野灯塔的葛瑞森船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (105, '啊，安多哈尔！', '啊，进攻安多哈尔并彻底击败那个巫妖的时刻终于来临了！$B$B召唤者阿拉基就盘踞在安多哈尔的废墟中，他的贴身卫队无时无刻不在他的身边保护着他。你需要召集强大的盟友才能击败他。$B$B消灭巫妖，$N，从它的护符匣里拿出一块碎片来，作为你获胜的证据！', '把阿拉基的护符匣碎片交给西瘟疫之地亡灵壁垒的高级执行官德灵顿。', '你成功了!巫妖阿拉基终于被打败了!$B$B你今天为部落做出了巨大的贡献，$N。你的勇气和毅力是成为真正的英雄所必须具备的素质。请接受这个荣耀的象征，让所有看到它的人都知道你为部落赢得了辉煌的胜利!', '你已经接到我指派的任务了，$N。你拿到巫妖的骨匣裂片以作为完成任务的证明了吗?', '', '去提瑞斯法林地找亡灵壁垒的高级执行官德灵顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (106, '年轻的恋人', '天哪，我太痛苦了！我爱上了托米·乔·斯通菲尔德，但我们两家却有着不共戴天的仇恨。所以我不能去见他，可我无时无刻不在怀念那张英俊的面庞啊！$B$B请你把这封信带给托米·乔，他一般会在斯通菲尔德农场西边的河流附近，他们的农场就在这里的正西方。', '把梅贝尔的情书带给托米·乔·斯通菲尔德。', '啊!我受不了这相思之苦，我一定要去见她!!', '你带来了她的信?梅贝尔是我枯燥无味生活中的一盏明灯。快点，快让我看看她的信!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (107, '给威廉·匹斯特的信', '威廉·匹斯特肯定有能让这两个年轻人见面的办法！$B$B把这个便笺拿去交给威廉，他现在正住在闪金镇的狮王之傲旅店。', '把斯通菲尔德老奶奶的便笺交给威廉·匹斯特。', '我很同情这对可怜的恋人，梅贝尔跟汤米.乔，我自己也年轻过，也轰轰烈烈地爱过一次。$B$B我一定得为他们做些什么!让我想想……', '斯通菲尔德的字条?我有好几年没有见到她了!不知道她到底有什么事……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (109, '向格里安·斯托曼报到', '看上去你参加过不少战斗，$c。如果你还没有去格里安·斯托曼那里报到的话，就赶快去吧。他是人民军的领袖，这是个专门负责保卫西部荒野的民兵组织，我敢说你是能帮他一些忙的。一般来说，你可以在哨兵岭的石塔周围找到他，那地方就在西部荒野中部的路边上。', '去和格里安·斯托曼谈一谈，他一般就在哨兵岭的石塔旁，这座石塔位于西部荒野中部地区的路边。', '啊，我的朋友让你来报到的?太棒了。$B$B暴风城已经抛弃了我们，现在只有人民军可以保护这片土地了。如果你愿意与我们并肩作战，我代表西部荒野的人民对你表示欢迎。$B', '你真应该去格里安·斯托曼那儿报到。他是人民军的领袖，这是个专门负责保卫西部荒野的人民军组织，我敢说你是能帮他一些忙的。一般来说，你可以在哨兵岭的石塔周围找到他，那地方就在西部荒野中部的路边上。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (111, '托米的祖母', '求求你，$N，去和我的奶奶谈一谈吧。如果有人能想办法让我和梅贝尔在一起的话，那个人一定是奶奶。$B$B她就在我们家的屋子里。', '和斯通菲尔德农场的米斯通菲尔德老奶奶谈一谈。', '我们两家是世仇，汤米和梅贝尔恐怕不会有什么结果，不过…也许我们可以想办法让他们聚一会儿。$B$B嗯，让我想想看能做些什么……', '我都等不及去看朋友们的反应了！$B$B他们肯定猜不到！', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (112, '收集海藻', '我可以为梅贝尔配制一种隐形水，这样她就可以悄悄溜出马科伦农场去见托米·乔。不过我需要一些水晶海藻来配制这种药水。$B$B水晶海藻一般生长在海里……不过有时候鱼人会收集它们。去看看水晶湖附近的鱼人身上有没有海藻，水晶湖就在闪金镇的东边。', '收集4片水晶藻叶，把它们带给闪金镇的威廉·匹斯特。', '你拿到海藻叶了，做得好!你得稍等一会儿好让我调制药水……', '你找到水晶海藻叶了吗?我敢说梅贝尔一定很想快点见到她的爱人……', '', '去艾尔文森林找闪金镇的威廉·匹斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (113, '昆虫研究', '高级勘探员菲兹杜瑟必须尽快看到这份报告。实际上……每个人应该知道这件事的重要性：我们正面临着一个巨大的威胁，这个威胁不仅仅涉及到塔纳利斯和加基森，如果不及时控制的话，整个卡利姆多大陆的南部地区都会有麻烦！而且这个威胁显然已经迫在眉睫了。$B$B让菲兹杜瑟把这份报告给你复制几份，然后你去把它广为传播。一定要让所有人都知道这个威胁的存在！', '把这份报告带给加基森的高级勘探员菲兹杜瑟，让他按照炼金师匹斯特苏格的要求为你复制一份报告。', '感谢你送这份报告给我，初级勘查员$N;这是加基森水公司为你辛勤的努力所给予的报酬。$B$B对于那些能够出的起好价钱的人，我通常不会吝啬把有价值的情报供给他们的。我认识匹斯特苏格很多年了，如果他说要让所有人都知道这份报告，那他肯定有充足的理由。请稍等一会，我这就去帮你复制一份。', '你好，初级勘查员$N，匹斯特苏格的报告完成了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (114, '梅贝尔的隐形水', '把隐形水带给梅贝尔·马科伦。它的隐形效果应该可以持续到她见到托米·乔的时候。', '把隐形水带给梅贝尔·马科伦。', '哦……天啊!要欺骗我的家人让我很有罪恶感，但我对汤米.乔的情感却强烈的无法忽视。$B$B谢谢你，$N。只要一有适当的时机，我就会喝下这瓶药水，然后悄悄地去见我的爱人。$B$B请你拿着这个，这是我的一点心意。', '你把我的信带给汤米.乔了吗?他有说什么吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (115, '暗影魔法', '黑石氏族的兽人在赤脊山脉的侵略行动得到了暗影法师的支持，他们带来了一种具有强大黑暗力量的器具——午夜宝珠。这些宝珠给赤脊山脉的保卫者们造成了巨大的伤亡，并迫使我们放弃所有在战斗中被这种宝珠污染了的器物,因为它们已经沾染了恶魔的力量。$B$B猎杀这些黑石暗影法师，并给我带回他们的午夜宝珠来。我将会把这些东西妥善地处理掉，还这世界一片清净！', '给湖畔镇的治安官马瑞斯带回3颗午夜宝珠。', '谢谢你，$N。我马上就把它们拿去销毁。', '你和暗影施法者的交手战况如何?有找到午夜宝珠了吗?', '', '去赤脊山找湖畔镇的治安官马瑞斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (116, '旱季', '我最近真是感觉有点没劲，$N。这些酒瓶子都快空了，运酒的船也很久没来了，这都怪那些该死的兽人。$b$b也许你帮我一个小忙？$b$b我希望你能从住在西部荒野的葛瑞姆·雷酒那里搞一桶雷霆啤酒，从暴风城搞一桶葡萄酒，从夜色镇搞一瓶月光酒，还有还有，再从闪金镇搞一袋蜂蜜酒来。把这些好酒都给我弄来，我会重重谢你的。', '湖畔镇的酒吧老板丹尼尔需要一桶雷霆啤酒，一桶葡萄酒，一瓶月光酒，还有一袋蜂蜜酒。', '你做得很好，$N!我知道你要找来这些好酒得走多少路。这下我的主顾们又要开心了!$B$B我妻子是个不错的裁缝，这件披风是她专门做了回报你的，请收下。', '我希望你能从住在西部荒野的葛林布兹.雷酒那里搞一桶雷霆啤酒，从暴风城搞一桶葡萄酒，从夜色镇搞一瓶月光酒，还有还有，再从闪金镇搞一袋蜂蜜酒来。把这些好酒都给我弄来，我会重重谢你的。', '', '去赤脊山找湖畔镇的酒吧老板丹尼尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (117, '雷霆啤酒', '快点，朋友，动作要快$b要酿更多的酒来卖$b有人要酒呀没人要菜 $b一捆蛇麻草，就够酿酒来', '给葛瑞姆·雷酒带去5捆蛇麻草以完成他的特酿。', '蛇麻草和酵母，小麦芽和大麦', '快点，朋友，动作要快', '', '去西部荒野找匕首岭的葛瑞姆·雷酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (118, '马掌', '我把所有的铁都用来打造暴风城卫兵的装备，结果没有剩馀的铁来打马掌了！$B$B把这封信带给闪金镇的铁匠阿古斯，信上说明了我现在的情况并要求他运一批马掌过来。', '把弗纳的便笺交给艾尔文森林中闪金镇的铁匠阿古斯。', '嘿，所以老弗纳需要一批马蹄铁，是不是?', '嗯，你说是弗纳派你来的?好，把他的信给我，说说看他到底要什么吧!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (119, '回复弗纳', '好的，我会给他送去50套马掌……$B$B就是这些，你看，全部都打包好了，随时可以出发！告诉弗纳，我很高兴和他做生意，哦，对了，提醒他看清楚箱子上的标签！', '回去找赤脊山湖畔镇的弗纳·奥斯古，把铁匠阿古斯的一箱马掌交给他。', '太谢谢你了，这真帮了我的大忙。$B$B不过，这是什么?阿格斯在木箱上附了张字条??这家伙居然要我付帐?算了!$B$B无论如何，$N，谢谢你的帮忙。', '好极了，你回来了!你拿到马蹄铁了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (120, '送往暴风城的信', '这真是段难熬的日子呀，$c。兽人的攻势没完没了，如果援军还不来的话，湖畔镇就要保不住了！我现在委托给你的这封信是非常重要的。立刻将这份报告送给暴风城的马库斯·乔纳森将军。你把信送到了那边之后，就马上带着那边回复的消息回来，无论是好消息还是坏消息，我都要尽快知道。$b$b现在就出发吧，快去快回！', '所罗门镇长要求你给暴风城的马库斯·乔纳森将军送一封信，并且在完成任务之后尽快回报。', '放松点，$C。$B$B所罗门镇长是一位高贵的领袖。我对他的意见是很尊重的。我会去找陛下的皇家顾问并把情况告诉他的。所罗门镇长肯定能够得到暴风城军方的援助，增援部队将在国王陛下批准后立即开拔。', '有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (121, '送往暴风城的信', '在我等待着国王陛下的回应时，希望你能把这封信交给所罗门镇长。$b$b快去吧，$c！', '将暴风城的马库斯·乔纳森将军的回信带给湖畔镇的所罗门镇长。', '感谢你的帮助，$C。这些钱是奖励你为湖畔镇和暴风城做事的酬劳。$B$B恕我直言，我发现了一些神秘的巧合。王国内部有些不对劲的地方，我害怕这只是一场残酷斗争的开始，而不是结束。', '将军有什么消息给我吗?援军已经上路了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (122, '雏龙的鳞片', '我需要一些黑龙雏龙腹部的鳞片来支付从阿古斯那里买马掌的钱。如果你能帮我搞到6块鳞片的话，在付给阿古斯一些以后……我还能用剩下的给你做点好装备。$B$B黑龙雏龙经常在湖畔镇南方游荡，猎杀它们的时候要多加小心。', '从黑龙雏龙身上收集6片雏龙的腹鳞，把它们交给赤脊山的弗纳·奥斯古。', '多谢!这些应该够我付清欠阿格斯的钱了吧……', '若我没能及时把鳞片给他送过去的话，贪婪的阿格斯一定会自己派人去找的。你拿到足够的鳞片了吗?', '', '去赤脊山找湖畔镇的弗纳·奥斯古。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (123, '收货人', '这是一张日程表，记录了某个人被称作“收货人”的人在某天某时会收到从艾尔文森林的矿洞运来的一车黄金。$B$B根据日程表所述，这个收货人好像就住在艾尔文森林东部的布莱克威尔南瓜田附近。$B$B这件事非常重要，你必须向闪金镇的治安官杜汉报告。', '去闪金镇找治安官杜汉，把收货人的交易日程表交给他。', '嗯……我听说过这个“收货人”，不过不知道他到底在为谁干活。谢谢你把这个日程表送来，它会帮助我们解开这个谜团。', '什幺?!我们的人已经有好几个月都没在艾尔文森林的矿坑里工作了!$B$B让我看看你拿来的那张记录……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (124, '豺狼人的乱吠', '似乎有这些整天攻城的兽人还不够乱！我发现最近老有一些混蛋豺狼人鬼鬼祟祟地沿着山脊在我的马场北面游荡，而且还偷我的马……$B$B如果你能把这些豺狼人都干掉的话，我，还有我的马都会感谢你的。', '杀掉10只赤脊山蛮兵和8只赤脊山秘法师，然后向弗纳·奥斯古复命。', '谢谢你的帮助，$N。', '我的马似乎还是一直受到惊吓，在夜里我也还是会听见那该死的狼嚎。拜托你，$N，把那些豺狼人都干掉!', '', '去赤脊山找湖畔镇的弗纳·奥斯古。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (125, '丢失的工具', '我本来可以在这儿大干一场的，$N。可是，我的工具还没到货，由于镇子被包围了，我们很难得到外面来的补给。我本来托人从闪金镇把工具用马车运过来，可是桥被砸断了，他们只好改用船运，结果那船又被兽人的投石车给打沉了。不过，算是不幸中的万幸吧，我的工具箱没坏，它只是沉进了湖底。$b$b帮我把工具箱找回来吧，$N，我会付给你不错的酬劳的。', '湖畔镇的工头奥斯洛希望你帮他找回沉入止水湖底的工具箱。', '做得太好了，$N!我还以为我再也看不见这些工具了呢。', '你找到我的工具了吗?', '', '去赤脊山找湖畔镇的工头奥斯洛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (126, '群山中的嚎叫', '$N，那些豺狼人居然还没死绝！我还能听见他们在湖畔镇周围的山区里打猎时发出的嚎叫声。其中有一个声音喊得最响——那是犹勒，他们的头儿。$B$B干掉犹勒，把他的手下都给轰走！把这个混蛋的爪子给我带回来。$B$B不过你得小心点，这家伙能当上他们的头儿自然是有两把刷子的。犹勒可不是个低能的混血豺狼人，他是纯种的……', '将犹勒的爪子带回给湖畔镇的弗纳·奥斯古。', '再次感谢你的帮忙。暴风城的军队正忙着对付兽人，他们根本派不出人到赤脊山来维持治安和清剿豺狼人。', '犹勒可是个危险的家伙，$N。你要是没准备好的话，就别急着去，我能理解。', '', '去赤脊山找湖畔镇的弗纳·奥斯古。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (127, '卖鱼', '止水湖的斑点太阳鱼是天下闻名的美味。它们总是供不应求……可我这里的存货已经不够了！$B$B给我带回10条鱼来，我会好好酬谢你的。哦，如果你不会捕鱼的话……可以从鱼人那里抢来！', '给湖畔镇的码头管理员巴伦带去10条斑点太阳鱼。', '跟你做生意真愉快，伙计!', '你有鱼要给我吗?', '', '去赤脊山找湖畔镇的码头管理员巴伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (128, '悬赏：黑石氏族', '我们一定得清剿黑石氏族。这群强盗入侵了我们的国家，占据了本应属于暴风王国的群山。根据线报说，在他们的氏族中，每支分队的领袖都被称为“勇士”，你很容易就能找到他们。他们的营地大致在北方，就在通向燃烧平原的道路西边。$b$b所罗门镇长希望有人能把这群卑鄙邪恶的家伙都消灭光。如果你有意帮助我们的话，杀死15名黑石勇士，然后向我复命。', '杀死15名黑石勇士，并向湖畔镇的卫兵豪维复命。', '我看得出来你和黑石氏族大战了一场，$C。你帮了湖畔镇一个大忙。', '杀掉15个黑石勇士再回来吧。', '', '去赤脊山找湖畔镇的卫兵豪维。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (129, '免费的午餐', '你能帮我一个小忙吗？我给卫兵帕克准备好了午饭，可他正在值勤……他是一个又高又壮的暴风城卫兵。他在外面是能自己保护自己的，可我们这样的寻常市民可不行，所以我没法去给他送饭……$B$B所以呢，如果你能帮我把他的午餐带给他的话，我也会给你提供一份免费的午餐！帕克就在通往暮色森林的路上巡逻。', '将卫兵帕克的午餐带给他，他就在通向夜色镇的路上巡逻。', '多谢，我吃饱了。保卫湖畔镇不受兽人和豺狼人的侵犯可真是件艰苦的工作呀!', '这是达希为我做的午饭?她真是个善良的姑娘。那么……我们开饭吧!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (131, '水仙诉衷情', '这是你要的花。我为你选了水仙，这是我最喜欢的花儿！', '将水仙花送给达希。', '噢，多美的花儿啊!我得赶紧把它们安置好!$B$B但是……这是玛蒂最喜欢的花。派克没让你对那唠叨的女人明说是他要花吧?你也没告诉她花是送给谁的吧?否则，就算你说这花被她下了毒我也不会感到惊讶。$B$B哦，不过这也不是你的错。谢谢你，这是你的午饭。', '你好啊，$N。派克吃到我做的午餐了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (132, '迪菲亚兄弟会', '我现在可是冒着生命危险在和你说话。迪菲亚那帮人也是听命于某个神秘人士的，我上次听说他们与许多种族都有过合作，豺狼人，狗头人，甚至还有地精。$b$b把这张便笺交给斯托曼。上面写着我所知道的关于迪菲亚兄弟会的一切。', '将威利的便笺交给西部荒野的格里安·斯托曼。', '嘿!我当年真应该好好修理修理那个混小子!但这个消息确实很重要，干得好。', '看见你回来真好，$N。威利都说了些什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (133, '食尸鬼假人', '我住得离镇子太远了，根本得不到保护。那些食尸鬼和行尸走肉还没有把我吃掉简直是个奇迹！其实昨天还有一群噬骨者来敲击我房子四周的墙！$B$B我得做个假人，一个用来吓唬食尸鬼的“稻草人”。我需要食尸鬼的肋骨来制作这个假人。你可以从食腐者、噬骨者、食脑者、腐烂者和瘟疫食尸鬼身上拿到这东西。$B$B给我带足够的肋骨来，我就会给你一些奖赏。', '收集7个食尸鬼的肋骨，然后把它们交给亚伯克隆比。', '啊，谢谢。这样就可以了!', '我听到有一群食尸鬼在屋后面跑动―我得赶紧把假人立起来!你找到食尸鬼的肋骨了吗?', '', '去暮色森林找乌鸦岭墓地的亚伯克隆比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (134, '食人魔盗贼', '几个星期前，我离开家去远处采草药，有一群食人魔袭击了我！我落荒而逃的时候丢了一箱工具和草药。$B$B这些食人魔在把我赶跑之后大摇大摆地回到了暮色森林南边的食人魔山上，我的箱子肯定就在那一带。$B$B请帮帮我吧，$N，我很需要这个箱子，请你一定要帮我拿回来。', '把亚伯克隆比的箱子拿回来交给他。', '感谢亡―呃，我是说，谢谢你，$N，你干得太棒了!$B$B啊哈!太高兴了!今晚真是太高兴了!', '你找到我的木箱了吗?如果找到的话，请赶快把它给我!', '', '去暮色森林找乌鸦岭墓地的亚伯克隆比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (135, '迪菲亚兄弟会', '我现在很想知道威利所提到的“石匠”是个什么意思，或许这只是一个口误？石匠公会跟迪菲亚真的有联系吗？或许暴风城军情七处的首领马迪亚斯·肖尔会知道真相。把威利的便笺拿给他，看看他对这个越来越大的谜团有什么想法吧。他就在旧城区的兵营里。', '将威利的便笺交给暴风城的马迪亚斯·肖尔。', '这件事情恐怕比斯托曼料想的还要复杂许多。', '你找我有事吗?我可是很忙的……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (141, '迪菲亚兄弟会', '过去的石匠公会是由一个名叫艾德温·范克里夫的人运营着的。第一次兽人战争结束后，范克里夫承接下了在兽人们留下的废墟上重建暴风城的重任。很显然，范克里夫对国王陛下在重建工程完成之后给予他们的待遇非常不满意。总之，解释这一大堆具体的事情要花些时间。$b$b我这里有一份详细的说明，让你拿到西部荒野去交给你的雇主。你得马上把这个给他带去！', '将肖尔的报告交给西部荒野的格里安·斯托曼。', '艾德温.范克里夫……我对这个名字很熟。想到这么一位技术绝佳的天才工匠竟然变成了一群恶棍的头子，实在是令我感到气馁。我需要更多的证据才能相信这件事。', '肖尔有提到任何线索吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (142, '迪菲亚兄弟会', '我们必须得找到迪菲亚兄弟会藏身的地方。$N，我的探子报告说，迪菲亚帮的信使们经常出现在月溪镇、金海岸矿洞和詹戈洛德矿洞之间的路上。我希望你能抓住一个信使，要是他试图反抗，就干脆把他干掉，然后把他身上所有的东西带回来。', '追捕西部荒野的迪菲亚信使，并将他身上携带着的信件交给斯托曼。', '这正是个可以证明范克里夫掌管着迪菲亚兄弟会的决定性证据。现在我们唯一要知道的就是:迪菲亚帮到底在什么鬼地方。$B$B当你去抓信差的时候，我们碰巧遇上一个很幸运的意外事件。一个小贼想从萨丁的货车上偷东西，结果被我们当场给抓住了。他允诺说可以带领我们到他们帮会的老巢去，以此来换取他的一条狗命。我希望你能护送这个叛徒去找到他们的藏身处。等你确认了那处地点后，马上回来向我报告。', '$N，你收集到什么情报没有?找到那个信差了吗?', '', '去西部荒野找哨兵岭的格里安·斯托曼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (143, '送往西部荒野的信', '暴风城的军队似乎遇到了些麻烦事，他们早就该到这里增援了，但直到现在还连个人影都没有。我们没多少时间可供浪费了！我不能再这样坐视人民继续无谓地牺牲而不去要求更多的增援。我听说西部荒野组建了一支民兵部队。$b$b把这封信带给他们的领袖格里安·斯托曼。或许斯托曼的人在国王陛下的部队到达之前能来帮忙抵挡上一阵。', '所罗门镇长要求你给西部荒野的格里安·斯托曼送一封信。', '优秀的信差，你完成了你主人交付给你的使命。', '你好，$C。请问你找人民军有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (144, '送往西部荒野的信', '所罗门镇长的信让我感到心痛。但显然他并不知道西部荒野的战事也很吃紧——或者他知道，但不得不抱着一丝希望来寻求我们的帮助。如果不是暴风城对西部荒野的人民不闻不问的话，我们也不会需要创建民兵组织的。$b$b将这封回信带给你在赤脊山的主人吧，$c。请转告他，我的心情也因为那么多勇士的牺牲而变得十分沉重。', '将格里安·斯托曼的回信带给所罗门镇长。', '我得说，这样的情况实在是太不妙了，我确实不知道那边的情况也是如同湖畔镇一样糟糕。到底是什么原因导致暴风城的军队无暇顾及他们的人民呢?唉，我不该大声谈论这种事的。$B$B拿着，信差。你为湖畔镇做了这么多事，请收下这些钱吧。我可能还会需要你的帮助。', '人民军团能派来援军来吗?斯托曼大人是怎么说的?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (145, '送往夜色镇的信', '看来我又得有事麻烦你了。我写一了封信给艾尔罗·埃伯洛克公爵，请求他从他的精锐部队——暮色森林守夜人——中抽出一些人来协助湖畔镇的防务。这封信必须马上呈送给他，而且你在旅途中要多加小心。埃伯洛克公爵是夜色镇的行政官，那座小镇就在暮色森林中，小心不要迷路了。', '所罗门镇长要求你给夜色镇的艾尔罗·埃伯洛克公爵送一封信。', '感谢你不远千里送信过来。这确实是个非常重要的消息。', '看来你是千里迢迢赶到这里来的，$C。你到夜色镇来有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (146, '送往夜色镇的信', '如果我不是和所罗门镇长私交甚密的话，我一定会以为他是个疯子的。因为暴风城拒绝出兵援助，就让我们把守夜人部队派去湖畔镇？守夜人部队就是因为这里被邪恶的魔法所影响才创建起来的。如果我把他们派离这里的话，恐怕还没等到他们走出森林，这里就会被邪恶的势力彻底吞没。$b$b把这封回信带给你在湖畔镇的主人吧。', '将埃伯洛克公爵的回信带给所罗门镇长。', '圣光啊!暴风城的军队已经从西部荒野撤离了，现在他们竟然也放弃了夜色镇?这简直是背信忘义的举动!他们怎么能这么做?$B$B哦，我忘记了该给你的酬劳，$C。拿着这些钱吧，恕我失陪。暴风城里一定发生了什么事，我一定要把这一切弄清楚!', '啊，很高兴看到你回来，信差。我是不是该通知我的治安官说，守夜人部队已经上路向这边来了?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (147, '猎杀收货人', '如果这个“收货人”是私自从我们的矿洞里开采黄金的话，那么他就是在偷窃王国的金库！把他就地正法，然后把他的交易日程表上提到的戒指带给我。也许这枚戒指能告诉我们这个“收货人”是在为谁工作……$B$B那张交易日程表上说“收货人”就藏在布莱克威尔南瓜田里，你应该到那儿去找他。', '找到“收货人”并将他杀掉，然后带着收货人的戒指回来见治安官杜汉。', '你找到他了?干得好，$N。从此他再也不能偷盗王国的黄金了!$B$B你找到的这枚戒指挺有意思……这是暴风城石匠行业协会的会员戒指。这么一个卑贱的小偷怎么会有工匠协会的戒指?迪菲亚盗贼为什么要从我们的矿坑里偷黄金?$B$B真是一团乱麻，希望有一天我们能找到答案。', '你找到收货人了吗?查出他为谁工作了吗?', '', '去艾尔文森林找闪金镇的治安官杜汉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (149, '幽灵的发丝', '有个可怜的亡魂叫盲眼玛丽，她总是在夜色镇南部小山上的农宅里出没。$B$B拿着这把鬼梳，让盲眼玛丽用它梳头。然后再把梳子拿回来，我可以从上面收集到需要的幽灵的头发。$B$B小心点，那个屋子里潜伏着一些可怕的东西……', '把鬼梳带给盲眼玛丽。', '这是什么?梳子?太可爱了!它滑过我的头发，好像它们不再那么僵硬可怕了。$B$B唉，要是有面镜子该多好……', '<哭泣>哦，不要，不要看着我!我自己把眼睛挖掉了，但是我还是能感觉到你在看我!$B$B我长得很丑陋!\r\n很丑陋!求求你，把脸转过去吧!!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (150, '鱼人偷猎者', '鱼人们如今也成了一个问题。大群的鱼人渔民在止水湖沿岸下锚撒网，都快把湖里的鱼捞光了！我们得在他们把湖里的鱼都吃光之前把他们赶走！$B$B去猎杀那些鱼人！给我带回8片鱼人的鳍来，我会奖励你的。', '给湖畔镇的码头管理员巴伦带回8片鱼人的鳍。', '做得好，$N。我希望这些鱼人没给你造成太大的麻烦。$B$B他们大老远的从海里跑到赤脊山来真是让人纳闷。我在想他们是不是在躲避什么……', '把鳍带来了没?动作快点，我们一定得把这群鱼人赶出湖去!', '', '去赤脊山找湖畔镇的码头管理员巴伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (151, '老马布兰契', '可怜的老马布兰契呀！我们让它干的活儿实在是太多了，看来它已经要累垮了。虽然我在离开农场以前就喂过了它，可谁会料到马车会在半路上坏掉呢？如果你能从田里替它取来几捧燕麦的话，我会对你感激不尽的。我想，你可以在田边找到足够的燕麦，不过你首先要将周围那些可怕的机器人先干掉。', '西部荒野的弗娜·法布隆要求你带给她8捧燕麦。', '太感谢你了，$N!可怜的老布兰契一定会非常高兴的!', '老布兰契已经快累死了。你找到给它吃的燕麦了吗?', '', '去找西部荒野的贾森农场的弗娜·法布隆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (152, '清理海岸', '你或许已经注意到了，海岸线上有许多船只的残骸。无尽之海确实是非常凶险，我们必须确保西部荒野海岸线上没有那些该死的鱼人到处徘徊，只有这样水手们才能安全地找到靠港的路线。$b$b去杀死7只鱼人潮行者、7只鱼人战士、7只鱼人智者，还有7只鱼人滩行者，完成任务之后到我这里来领取奖赏。', '杀死7只鱼人潮行者、7只鱼人战士、7只鱼人智者，还有7只鱼人滩行者，然后向西部荒野灯塔中的葛瑞森船长复命。', '做得好，$N。你的战斗能力非常不错。由于你的努力，西部荒野的海岸变的更安全了。', '去杀死7名鱼人猎潮者、7名鱼人战士、7名鱼人神谕者，还有7名鱼人滩行者，完成任务之后到我这里来领取你的报酬。', '', '去西部荒野找西部荒野灯塔的葛瑞森船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (153, '红色皮质面罩', '我们与迪菲亚兄弟会的战局总是瞬息万变。最近我一直在监视着他们的活动，根据长期观察的结果，我发现他们的成员都戴着一种特殊的红色皮质面罩。$b$b给我带15条这种面罩回来吧，我会给你奖励的。', '给哨兵岭的哨兵加里安带回15条红色皮质面罩。', '做得漂亮，$r。请挑选一件物品做为报酬吧，这是你应得的。', '帮我拿15条红色皮头巾来，我就付给你可观的酬劳。', '', '去西部荒野找哨兵岭的哨兵加里安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (154, '归还梳子', '不！！！！！$B$B快把这个梳子拿走！$B$B我是个怪物，不会再有人说我好看了！', '把幽灵的梳子拿回去交给夜色镇的伊瓦夫人。', '我可以用这些做一个鬼魂发丝的线轴给你，还能剩下几个备用。这些就当做跟你买这些线的费用吧。', '我想你已经见过盲眼玛丽了，你拿到梳子了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (155, '迪菲亚兄弟会', '这么说，斯托曼就派了你这么一个芦柴棒一样的家伙来保护我？希望你能行，当然如果你再叫上几个朋友帮忙就好了。$b$b你知道你要做些什么吧？我会把你带到迪菲亚盗贼的巢穴去，而你呢，就得保护好我。当然，你最好离我近点，越近越好。现在全迪菲亚兄弟会的人都想要我的脑袋呢。要是他们看见我和你在一起，一定会来把咱们都宰了的。$b$b等你和你的朋友准备好之后，就来跟我说一声吧。', '护送迪菲亚叛徒转至迪菲亚兄弟会的秘密藏身处。迪菲亚叛徒把你带到范克里夫和他的手下的巢穴之后，尽快回去向格里安·斯托曼汇报相关信息。', '非常好，$N!即然知道他藏在那里，范克里夫就跟落入我们手中没两样了!', '有事吗?', '护送迪菲亚叛徒，以发现范克里夫的藏身之所。', '去西部荒野找哨兵岭的格里安·斯托曼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (156, '收集腐败之花', '如果你能给我找些腐败之花来，我就可以酿造很多僵尸酒。$B$B这种花很难找到，听说在恐怖骸骨和骸骨魔的头骨里可以找到这种花……不过至今我还没有亲眼见过！$B$B乌鸦岭墓地和静谧花园里都有很多这样的骷髅，你可以在寻找腐败之花的时候顺便把他们干掉，夜色镇的人民会感激你的。', '收集8个腐败之花，交给夜色镇的旅店店主斯密茨。', '很好，你拿到腐败之花了。我会告诉守夜人奥瑟.埃伯洛克你杀了不少骷髅。$B$B守夜人的职责就是保卫夜色镇人民的安全，他们会很高兴知道还有其它人在帮他们打击暮色森林里的邪恶势力。', '你好，$N。你帮我找到腐败之花了吗?', '', '去暮色森林找夜色镇的旅店老板斯密茨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (157, '幽灵的发丝', '这是你要的线，$N。它有很多种用途，比如用来束缚邪恶的亡魂，或者给没有生命的东西注入生命。', '把幽灵的发丝交给亚伯克隆比，他住在乌鸦岭墓地北边的房子里。', '真令人高兴!这对我太有用了……$B$B请拿着这个，$N，做为我对你可敬的帮助的报酬。', '我要把鬼魂的发丝挂在门窗上，来阻绝那些该死的亡魂。你替我拿来发丝了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (159, '僵尸酒', '这是你要的僵尸酒……$B$B不过要小心一点，这酒烈得足以把死人给呛活过来。', '把僵尸酒交给乌鸦岭墓地北方小屋里的亚伯克隆比。', '真是太感谢你了，$N。你用你的愚蠢—我是说……你的善良―温暖了一个老人的心!$B$B拿着，这代表我的感激之情。', '我需要喝些僵尸汁在寒冷的夜里保持暖和。你替我拿僵尸汁来了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (160, '给镇长的信', '请把这封信交给夜色镇的艾尔罗·埃伯洛克镇长。$B$B我和他是老朋友了……我敢说，当他读完信，并且知道了你为我做的事情……他一定会和我一样高兴的！哈哈哈哈！', '把亚伯克隆比的信交给夜色镇的艾尔罗·埃伯洛克镇长。', '<艾罗看着信……>$B$B这信上写的是什么?看起来是种古老的语言……我看不懂。', '亚伯克隆比……?我不认识这个人。你是说这个人有封信给我?$B$B哦，那我就收下好了……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (161, '水坝危机', '如果我的猜测没错的话，这是某种火药粉末。应该找个爆破专家来分析一下这到底是什么东西。阿什兰·暗石就在丹莫德和萨多尔大桥一带负责那里的警戒工作，我需要你尽快去找他，这是一段重要而危险的旅程，$N。$b$b走过奥加兹大门，沿着穿过湿地的大路一直到丹莫德去找爆破专家阿什兰·暗石。留心我的建议：沿着大路走，不要停留！', '主工程师辛德维尔七世要你把怪味粉末交给湿地中丹莫德的炸药专家阿什兰·暗石。', '嗯，老辛德尔的担心是有道理的。$B', 'NULL', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (162, '异种蝎的威胁', '我希望你尽快把这份报告送到对处理此类事件有经验的人手里。$B$B我知道有一位名叫格拉希娜·灵风的暗夜精灵学者，她致力于研究卡利姆多大陆上那些与艾泽拉斯的普通生物截然不同的生物形态，她简直就是一本活的生物书！如果你想要知道我们面临的是怎样的威胁，以及如何解决这个威胁，那就把这份报告交给她吧，我们现在急需她的帮助。$B$B我听说她住在达纳苏斯的月亮神庙里。', '把报告带给达纳苏斯的格拉希娜·灵风。', '这个报告……我们夜精灵已经知道里面提到的威胁了。菲兹杜瑟让你把这份报告送到我这里来是很明智的。$B$B这些生物会迅速吞噬塔纳利斯的沙漠，它们将是我们所要面对的有史以来最大的威胁。$N，请记住它们的名字:异种蝎。报告里提到的这些昆虫就是异种蝎，它们对于部落和联盟来说都是一个威胁。$B$B除非我们能够早点意识到它的危害程度，否则后果不堪设想。', '你好，陌生的$C，愿安宁和平与你同在。你找我有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (163, '乌鸦岭', '乌鸦岭出了点问题，$n。卡洛尔说那边的房子里有什么人——或者怪物——出没。有两个晚上，他发现有个身影在活动，第三天晚上，某扇窗户里还射出了灯光。$b$b你如果真的关心暮色森林的安危，就去查一查，看看是什么样的怪物在乌鸦岭出没。', '查出是什么东西在乌鸦岭神出鬼没。', '不要!请不要杀我!是我…基特斯……它们到处都是，我躲也躲不了!乌鸦岭有怪物?不，不…不可能。只有不会伤人的基特斯……', '啊，$N！回来的这么快？你肯定又被野兽追了吧？别在意你经历的那些周折，终究它们会让你更强大！$B$B……至少，你也没变得更差', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (164, '斯温的货物', '你认识斯温吗？谢天谢地，终于有人能帮我了！斯温和他的同伴在暮色森林的西北边有个营地。$b$b不幸的是，他们的人手太少了，少到派不出人回镇里来取一些必需的补给品。你能把这些物资带给斯温吗？', '把补给物资带给斯温。', '这些物资很有用，我们对克尔文系列的帮助感激不尽。这是给你的一点小报酬。', '你看起来挺健壮的，$C。你是来帮我们战斗的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (166, '迪菲亚兄弟会', '这里恐怕还有最后一个任务需要你来完成。我们必须派人去除掉艾德温·范克里夫。说实话，就这样对一个活生生的人宣判死刑，这实在令我非常痛心，但为了西部荒野人民的利益，我不得不让范克里夫永远安息。把范克里夫干掉之后，提他的头来见我。', '杀死艾德温·范克里夫，把他的头交给格里安·斯托曼。', '$N，你的英雄壮举将长存于我们的心中。人民军将会对你为西部荒野人民所做的一切感激不尽。范克里夫一死，迪菲亚兄弟会的命运也开始走向灭亡。希望在不久之后的某一天，和平会重新降临到这片美丽的土地上。$B$B我向你致敬，$g先生:女士;!', '猎杀艾德温.范克里夫的事情进展如何了?', '', '去西部荒野找哨兵岭的格里安·斯托曼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (167, '我的兄弟……', '那时我们正在一个大矿洞中工作，就是那个隐藏在西部荒野月溪镇中的谷仓下面的矿洞……没人知道当时到底是怎么回事，总之矿道突然坍塌了，我逃了出来……可其它人就没那么好运了……我是说，从那以后我就再没听到过其它人的消息了。$b$b看上去你的运气可能会比我们好一点。如果你能帮我找到弟弟的话，我会非常感谢你的。他总是戴着一块探险者协会徽章，所以如果你找不到他的话，至少那块徽章能给我带来一些安慰……', '将工头希斯耐特的探险者协会徽章交给暴风城的维尔德·蓟草。', '看来我的猜测没错。我可怜的弟弟……好吧，谢谢你让我知道了结果，尽管这结果令我非常难过。', '你找到有关我弟弟的线索了吗?经过这么久的时间还有任何希望吗?', '', '去找暴风城的维尔德·蓟草。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (168, '收集记忆', '在那个可怕的日子，我的许多朋友都被埋在了矿洞里。如果你在冒险中正好路过月溪镇的那处矿洞的话，请帮忙留意一下有没有什么可以辨认他们身份的标志物品。如果你能找到他们的矿业工会会员卡的话，请一定要带给我，我好知道他们的结局，并与他们的家人谈谈如何为这次恐怖的事故善后。', '给暴风城的维尔德·蓟草带回4张矿业工会会员卡。', '感谢你找回这些东西，$N。你的努力一定能使这些不幸死于事故的矿工们得到安息。我会马上通知他们的家人。', '你找回我那些老同事们的矿业工会会员卡了吗?', '', '去找暴风城的维尔德·蓟草。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (169, '通缉：加塞尔佐格', '悬赏！加塞尔佐格是黑石氏族袭击石堡和多次劫掠湖畔镇等行动的领导者。$b$b他是个十分危险的家伙。根据线报，他最近就躲藏在刚刚被他们攻陷的要塞中，谋划着黑石氏族的下一次劫掠行动。我们必须不惜一切代价把这些在我们的国土上横行的兽人镇压下去。如果谁能把加塞尔佐格的徽记带到所罗门镇长面前的话，他将会得到重赏。', '杀死加塞尔佐格并取下他的徽记，向湖畔镇的所罗门镇长复命。', '这实在是太棒了，$N!加塞尔佐格带着那帮畜牲为祸四方，杀了不少无辜的人。正义终究还是获胜了，这也是为暴风王国夺回要塞的第一步!', '有什么事吗，$C?', '', '去赤脊山找湖畔镇的所罗门镇长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (170, '新的威胁', '我希望你能帮我们一把，$c。在上一次穴居人袭击之后，我们的人手就明显不够了。$b$b我听说他们现在已经遍布我们的国土，看来寒脊山谷也不能避免。东南部的山区和湖畔已经到处都是穴居人的身影了。$b$b糟糕的事情还不仅仅是这些，几天前，他们袭击并占领了我们西边的营地！$b$b我们这儿有些人手不足，$g孩子:姑娘;，我们需要强大的军队帮助我们赶走这些家伙。', '巴尔林·霜锤让你去杀死6个石腭穴居人和6个壮实的石腭穴居人。', '如果我们的土地上到处都是我们遇到的这些讨厌的家伙，以麦格尼胡须的名义，那我们就有大麻烦了!我只能盼望国王和参议院能尽快着手解决石腭怪带来的问题。', '这些穴居人真是烦人啊!', '', '去丹莫罗找寒脊山谷的巴尔林·霜锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (171, '联盟孤儿的看护者', '你对我真好，$N。我从来没有想过会在儿童周得到如此多的乐趣，谢谢你。我不会因为我的悲惨遭遇而感到悲伤——我的爸爸妈妈总是告诉我，在面对困境的时候要保持坚强。我会成为一个英雄的……就像你一样。$B$B不过现在，我该回家了。让我们一起回去吧，我会告诉院长，你是一个多么出色的$r$c！', '回到暴风城的教堂区，把人类孤儿哨交还给孤儿院的孤儿监护员奈丁加尔。', '愿上天保佑你，$N。你已经为兰迪斯做了太多别人想不到的事情。感谢你―你是照耀着联盟的一颗璀璨的星星。$B$B如果你有时间的话，请再回来看看我们。我知道兰迪斯会期待着你的到来，我也会欢迎你。$B$B兰迪斯和你相处的很愉快，$N。他想给你一只他最爱的宠物让你时时想着他。', '很高兴再见到你，$N。你有没有在儿童周中完成自己的义务?', '', '去找暴风城的孤儿监护员奈丁加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (173, '森林里的狼人', '黑暗的势力正在笼罩暮色森林，而卡尔文主人正在努力驱除邪恶，保护夜色镇人民的安全是我们的职责。$b$b你觉得自己有能力加入我们吗？$b$b我以前也跟你想的一样，因为对哨所的安逸悠闲感到绝望，我投靠了卡尔文主人。如果你想要证明自己的实力，不是只靠嘴皮子说说就可以的。$b$b去找夜行织影狼人较量较量吧，他们经常在阳光树林——阳光，哈！——和烂果园出没。', '为夜色镇的卡洛尔杀掉6个夜行织影狼人。', '很不错，$N。看来你完全有能力应付他们，也许还可以做得更好。$B$B真的很奇怪……狼人们似乎都是凭空冒出来的，随后又有许多其它奇怪的东西进入了我们的土地，想必狼人也只不过是众多麻烦中的一个罢了。', '$N，你干得如何了?', '', '去暮色森林找夜色镇的卡洛尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (174, '仰望星空', '我的侏儒朋友考格说过要帮我制造一个可以用来观察星空的装置。我相信除了魔法之外，还有别的理由可以解释发生在这片森林中的奇怪变化。$b$b根据考格的设计图，首先要去找一个手艺高超的技师，让他帮忙造一根青铜管。', '夜色镇的维克托·安特拉斯要你给他找一根青铜管。', '太完美了，$N。第一步已经完成了!$B', '你找到可以制造青铜管的工程师了吗?', '', '去暮色森林找夜色镇的维克托·安特拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (176, '通缉：霍格', '通缉：霍格$B$B巨型豺狼人霍格，现正在艾尔文森林西南部的树林里游荡。他成功地对抗了当前为止所有追捕他的行动。$B$B暴风城已经为除去这只豺狼人设下了酬金，想得到酬金的猎手必须向闪金镇的治安官杜汉提供杀死霍格的证据。', '杀死豺狼人霍格，把他那巨大的豺狼人爪带给治安官杜汉。', '哈!干得好!我还以为没人能干掉那个怪物呢!$B$B拿着这个，$N。谢谢你―这只豺狼人给我带来的麻烦足有黑石塔那么大!', '没错，霍格一直让我们倍感头疼。你有关于他的消息?', '', '去艾尔文森林找闪金镇的治安官杜汉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (177, '仰望星空', '那副眼镜是我最珍贵的宝物，不过在发生了一件事情之后……我就把它丢在谷仓后面了。有个疯狂的食尸鬼曾经在那一带徘徊，可能是它把东西给捡走了。有人说那个邪恶的家伙住在静谧花园墓场出现。', '从疯狂的食尸鬼那里拿回盲眼玛丽的眼镜，把它交给夜色镇的维克托。', '太棒了!这面反光镜很有用，非常感谢你!$B', '考格看过我们的观星机器的雏形之后非常满意。你找到合适的反光镜了吗?', '', '去暮色森林找夜色镇的维克托·安特拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (178, '塞欧克瑞图斯的坠饰', '<你听到了某种飘渺的声音>$B$B可别被吓着。我是塞欧克瑞图斯，艾尔文森林的阿祖拉之塔里的高阶法师。你手上拿着的饰物是暗皮豺狼人和他们的主子莫甘斯用来联络的工具。$B\r\n$B根据这几个月的研究，我也已经掌握了使用这些饰物进行通信的方法。如果你能听到我所说的话，就证明我的法术成功了。$B$B把这个饰物带给我，我会给你酬劳的。', '将不再发光的暗皮坠饰带给艾尔文森林中阿祖拉之塔的法师塞欧克瑞图斯。', '太感谢你了，$N。几周前我也曾尝试过对影皮坠饰送出同样的讯息，但是没有收到任何回应。不过这个法术似乎对某些坠子还是能够发挥效果，虽然延迟了非常久。$B$B接下来我要研究怎样通过这些饰物进行攻击，来麻痹所有把带着这东西的豺狼人。$B$B不过要完成这件事情，我恐怕得花很长的时间来研究它。', '你说我透过一个队子和你说话?快给我，我好研究研究它。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (179, '矮人的交易', '嘿，你是新来的吧？看来你需要些暖手的东西，对吗？$b$b我想你应该想要一副保暖的手套。我是个热心肠，很愿意给你一副手套，不过我有个条件。$b$b你帮我弄些狼肉来，我保证你不会被冻掉手指头。你觉得怎么样？', '斯登·粗臂想要8块硬狼肉。', '啊，太棒了!狼肉一定不错。哦，别着急，$N。我没有忘记当初的承诺，你看中了哪件就拿哪件吧。', '那些狼好对付吗?它们的狂牙利爪没有伤到你吧?', '', '去丹莫罗找寒脊山谷的斯登·粗臂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (180, '通缉：范高雷中尉', '悬赏：范高雷$b$b恶行累累的豺狼人头目范高雷在湖畔镇及王国的敌人莫甘斯的指使下，带着暗皮豺狼人氏族到处为非作歹。镇长所罗门下了命令，悬赏杀死这个万恶的东西。将他的手掌割下来拿给镇长，以此证明他的死亡。', '杀死范高雷并将他的手掌割下，向湖畔镇的所罗门镇长复命。', '邪恶的范高雷中尉终于死了?对这个歹毒的家伙来说，这也算是个解脱吧。你很勇敢，$C。我代表湖畔镇的人民对你的帮助表示感谢。', '你有什么事吗?', '', '去赤脊山找湖畔镇的所罗门镇长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (181, '仰望星空', '根据考格的设计图，现在我们还需要一种透镜来完成整个装置。我知道什么地方有合适的透镜，不过很难拿到。$b$b有个叫扎克乌尔的食人魔住在暮色森林南部的土丘上，如果可以的话，你去把他的单片眼镜拿来吧，我可以用它做透镜。', '在暮色森林南部的食人魔土丘上找到扎克乌尔，把他的单片眼镜带回夜色镇交给维克托。', '观星工具终于完成了!谢谢你，$N。现在我可以继续我的研究了……', '你有没有说服札克乌尔把他的单片眼镜借给我们做实验?', '', '去暮色森林找夜色镇的维克托·安特拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (182, '巨魔洞穴', '我和我的兄弟森内尔被派来调查丹莫罗各个地区的巨魔活动情况。参议院正在忙着对付那些不知道从哪里冒出来的穴居人，已经没工夫再关心巨魔了。$b$b据我所知，在寒脊山谷南部山洞里生活的巨魔们日子并不好过，所以我觉得派大批军队去围剿它们是杀鸡用牛刀，只要一两支训练有素的小分队就已经绰绰有馀了。$b$b你也许能给我们提供些帮助吧？当然，我会对你的帮助给予一定的报酬。', '格瑞林·白须要你去杀掉10个霜鬃巨魔幼崽。', '啊!那些天杀的巨魔!$B$B<他深吸了几口气，似乎想平静下来……>$B$B一伙巨魔趁着夜色溜了进来，把我的日记给偷走了!我就知道我那没用的学……', '据我所知，这些巨魔来自于霜鬃氏族。$N，恐怕我没有什么其他的资讯可以告诉你了。', '', '去找丹莫罗的格瑞林·白须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (183, '猎杀野猪', '没什么能比得上用一整天的时间去打野猪更让人愉快的了，对吧？不过，寒脊山谷里的野猪太多了，你几乎已经不可能在那里再感受到狩猎的乐趣。你根本不需要去激怒它们，因为它们早就是怒气冲天，随时准备用獠牙把你拱上天了！事实上，这些过剩的野猪已经对我的日常狩猎形成了威胁。$b$b长话短说吧，如果你能帮我杀掉些野猪，我真的会非常感激你的。', '塔林·锐眼让你去杀掉8只规模峭壁野猪。', '太好了!我现在又能回到当初那从容而快乐的狩猎生活了。谢谢你，$N。', '捕猎进行得如何啦?', '', '去丹莫罗找寒脊山谷的塔林·锐眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (184, '法布隆的地契', '这是西部荒野一片农田的地契，由西奥多·法布隆和他的妻子弗娜·法布隆联名签署。地契背面还有潦草的字样：$B$B“我们到法布隆家里走了一遭，弄到了他的地契。我们觉得你可以很轻易地照着这张样本给自己也造出几份地契来。$B$B法布隆家的人不会找我们的麻烦，我最后一次看到他们的时候，他们的四轮货车坏在了路上。”$B$B你认为法布隆夫妻俩可能正在到处找这张地契……', '把法布隆的地契交给农夫法布隆。', '太感谢你了，$N。如同我所说的，这一带已经不再适合老实人住了，不过当情况好转的时候，我们就可以用这张地契来收回我们的土地。$B$B我没什么东西可以给你，但请收下这个。', '你有我的农场的地契??真是太好了!几天前有几个恶棍把它给偷走了……我还以为再也找不回来了!$B$B请把它还给我吧。我们正要离开西部荒野，短期内不会回来了，不过万一日后我们又要再回来的话，我们就会需要这些文件。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (185, '猎虎', '当我还只是个小女孩的时候，我的父亲就开始训练我捕猎老虎。$b$b一般来说，你会发现虎崽是非常容易追踪和猎杀的。因此，要猎杀它们根本不是什么麻烦的事情，你在探险队的营地附近很容易就能找到虎崽。$b$b让我们来测试一下你的追踪技巧，看看你是否能猎杀这些野兽。', '奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只荆棘谷猛虎幼崽。', '干得不错，$N。你已经可以进行下一步了。', '在你证明你有足够的技巧来猎杀小猛虎前，我并没有信心能将你训练得更好。', '', '去荆棘谷找奈辛瓦里远征队营地的艾耶克·罗欧克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (186, '猎虎', '你学得很快，$c。让我们来测试一下你是否能杀死成年的猛虎，这次你的任务是去杀死十只荆棘谷猛虎。', '奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只荆棘谷猛虎。', '你让我印象很深刻，$C。你进展的非常顺利。', '如果你想要接受更大的挑战，就必须要先完成我交付给你的任务来证明你的实力。杀死10只荆棘谷猛虎后再回来找我。', '', '去荆棘谷找奈辛瓦里远征队营地的艾耶克·罗欧克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (187, '猎虎', '现在我要教你些更高深的东西，然后测试一下你的技巧。去杀死十只老年荆棘谷猛虎以证明你的能力吧。如果你能做到这些的话，你就可以去面对最后的挑战了，最终，我会在奈辛瓦里大人的面前授予你猎虎大师的称号。$b$b老年荆棘谷猛虎不但非常难找，而且也是最难以对付的。', '奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只老年荆棘谷猛虎。', '你给我留下了深刻的印象，我相信你已经准备好面对最后的挑战了。', '在面对最后的挑战之前，你必须先杀死10只老年荆棘谷猛虎，否则你是没资格成为一位真正的猎虎大师的。', '', '去荆棘谷找奈辛瓦里远征队营地的艾耶克·罗欧克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (188, '猎虎', '现在你要面对的将是最后的挑战。我们这几周来一直在追踪一只神秘的老虎，我们称它为辛达尔。现在让我们来看看你能不能做到一件以前从来没有任何$r可以做到的事吧：去猎杀辛达尔，把它的爪子带回来以证明你完成了任务。$b$b追踪它可不是一件简单的任务。', '奈辛瓦里远征队的艾耶克·罗欧克要求你杀死辛达尔并带回它的爪子。', '我得说，你真是太出色了!你现在是一位真正的猎虎大师了，$N!', '猎杀辛达尔的事情进行得如何啦?', '', '去荆棘谷找奈辛瓦里远征队营地的艾耶克·罗欧克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (189, '血顶巨魔的耳朵', '该死的巨魔！他们杀死了我们派到丛林里去的人！我已经在和他们的冲突中损失太多优秀的护卫了。血债必须血来偿！这让我怎么向大财主里维加兹解释呀？$b$b是该做决定的时候了……想想看，科博克……你可不是被派到这里来整日无所事事的……啊，有啦！你……你就是$n，是不是？你是来帮助我的，是不是？这份工作的奖励可是很丰厚的哦！$b$b嗯嗯，给我带15只血顶巨魔的耳朵来，我就重重地酬谢你，如何？', '给藏宝海湾的科博克带回15只血顶巨魔的耳朵。', '喔，太棒了，实在是太棒了。这一阵子情况至少会好一点点……$B$B<他的声音变轻了，嘟囔着花费和报酬……>$B$B什么?你怎么还在这儿?报酬?噢，对……当然，拿着吧……绝对是只多不少的。', '你成功了吗?这里遍地都是巨魔，这群丑陋的魔鬼。$B$B哦，对了，这倒提醒了我，记得把这件事告诉你的同伴，好吗?我们还需要更多的帮手!', '', '去荆棘谷找藏宝海湾的科博克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (190, '猎豹', '如果你也想加入这个由赫米特先生组建的最强狩猎队，就必须先证明自己是一个能干的猎豹高手。放心，一开始不会太难的，千万别轻言放弃。你先去猎杀10只猎豹幼崽热热身吧。$b$b当然，这只是让你热热身而已……', '奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只猎豹幼崽。', '这是个不错的开始，$N!', '一名真正的猎豹高手应该在荒野中搜寻猎物。尽力去完成你的目标，$C，然后再回来。', '', '去荆棘谷找奈辛瓦里远征队营地的埃尔加丁爵士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (191, '猎豹', '现在你已经可以更进一步了。如果你想继续证明自己有资格和我们这些优秀的狩猎能手合作的话，就去猎杀十只黑豹。$b$b这些大家伙们都很强壮，它们可不比之前的猎豹幼崽那么好杀。', '奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只黑豹。', '你做得太完美了，$N!', '去猎杀十只黑豹!给我们看看你的战利品!', '', '去荆棘谷找奈辛瓦里远征队营地的埃尔加丁爵士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (192, '猎豹', '接下来的部分可就比较困难了。一个真正的猎豹能手必须要有能力杀死深喉猎豹这种荆棘谷中最危险的生物。去杀死十只深喉猎豹，向我们证明你的猎豹能力吧！$b$b如果你很难找到它们的踪迹的话，就埋伏起来等它们出现……', '奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只深喉猎豹。', '你做得很好，$N!', '你还在这里做什么呢，$N?你应该正在丛林里试着猎杀十只深喉猎豹才对。难道你不想成为一名伟大的猎人了吗?', '', '去荆棘谷找奈辛瓦里远征队营地的埃尔加丁爵士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (193, '猎豹', '你几乎已经证明自己是一位优秀的猎豹能手了。有一只名叫巴尔瑟拉的豹子当前正潜伏在这片森林里，我们一直都没能找到它。去试试猎杀巴尔瑟拉吧，记得用上你所掌握的全部技巧。$b$b将巴尔瑟拉的牙齿带回来给我，如果你成功了，你就将赢得我的尊敬！', '奈辛瓦里远征队的埃尔加丁爵士要求你杀死巴尔瑟拉，并带回它的牙。', '你杀死了巴尔瑟拉!恭喜你，$N。你果然是一位优秀的$C!', '巴尔瑟拉是这片丛林里最狡猾的野兽，你捕猎到它了吗?', '', '去荆棘谷找奈辛瓦里远征队营地的埃尔加丁爵士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (194, '猎龙', '你觉得你的狩猎技术是最顶尖的？我马上就检验一下，看看你是不是在骗人。到丛林里去杀几只荆棘谷迅猛龙，这样一来我们就知道你是不是所谓的王牌猎人了。$b$b当然，我是绝对不会告诉你在哪里才能找到它们的！追踪野兽本身就是挑战的一部分。', '赫米特·奈辛瓦里二世要求你杀死10只荆棘谷迅猛龙。', '干得漂亮，$g哥们:小姐;!', '我从没见过猎人站在营火旁边也能打到猎物的 - 呃，除了我父亲。你是打算杀死荆棘谷迅猛龙还是等那些猎物老死?', '', '去荆棘谷找奈辛瓦里远征队的赫米特·奈辛瓦里二世。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (195, '猎龙', '现在让我们来看看你能不能应付更大的挑战吧。杀进丛林里去，给我干掉十只残暴的鞭尾迅猛龙。可别说你不行啊！', '赫米特·奈辛瓦里二世要求你杀死10只鞭尾迅猛龙。', '现在你可以在家里的壁炉上挂上一两只恐龙脑袋当战利品啦!做得好，$N!', '一位真正的猎人脑中总是想着他的猎物。而你呢，我的朋友，你似乎更喜欢在营火旁边谈天说地。好了，快离开这里，你最好赶在我把这些鞭尾迅猛龙全部杀光前猎杀10只回来。', '', '去荆棘谷找奈辛瓦里远征队的赫米特·奈辛瓦里二世。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (196, '猎龙', '让我们来看看你能不能对付下一个挑战吧。这附近栖息着一种非常狡猾的迅猛龙，我们叫它丛林捕猎者。它们远比你之前捕猎的目标更难追踪和猎杀。猎杀十只丛林捕猎者，然后我就会告诉你这里最惹眼的目标是什么。', '赫米特·奈辛瓦里二世要求你杀死10只丛林捕猎者。', '呵呵!!这下我们这儿有个真正的恐龙杀手啦!干得漂亮，$g小伙子:小姑娘;!', '喂!你还在这儿闲晃什么，$N?真正的王牌猎人绝对不会把他的猎物彻底抛到脑后去，而且那些丛林潜猎者可不会自己跳进这堆营火去自杀的，笨$g小子:丫头;!', '', '去荆棘谷找奈辛瓦里远征队的赫米特·奈辛瓦里二世。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (197, '猎龙', '你已经证明了自己在这片丛林里的每次捕猎都不会空手而归，总能带回我们要求的猎物，因此我决定告诉你有关那只我从来也没能猎到的、最凶暴最残忍的迅猛龙的事情，艾耶克把那只迅猛龙叫作泰希斯。$b$b如果你想证明自己真的是个捕猎专家的话，就把泰希斯杀掉，把它的爪子给我带回来，这可是其它王牌猎人都从没完成过的壮举。', '赫米特·奈辛瓦里二世要求你杀死荆棘谷中最危险最狡猾的迅猛龙泰希斯。', '$G大师:女主人;$N，恐龙杀手!$B$B听起来很不错吧?', '猎杀泰希斯的事进行得怎么样了?你找到它的老窝了吗?', '', '去荆棘谷找奈辛瓦里远征队的赫米特·奈辛瓦里二世。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (198, '列兵索尔森的补给物资', '嗯。没错，我这里确实有些适合你做的事。当前部署在荆棘谷北部的多伦上尉和他的部下需要我们的定期补给。$b$b不过由于巨魔的伏击，他们一直没能得到补给，所以我得找人来帮我处理这件事。多伦的营地就在从暮色森林进入荆棘谷的道路的西北方，你只要把补给品交给列兵索尔森就行了，相信他会处理好的。$b$b你要记住，如果你失败了的话，就得赔偿我们的损失。$b$b当然，你也可能会死在路上……', '将杂七杂八的地精补给物资带给列兵索尔森。', '这些地雷可以用来帮助我们抵抗库森和他的部下的进攻。谢谢你将它们送过来，要是你还想找些别的工作的话，我想我可以找些事让你做。对了，你应该不需要和那群哥布尔打交道吧，嗯?', '是的?有什么事吗?哦，哥布尔送来的补给品。他们居然会让一个$r送过来，还真是奇怪，一般都是他们自己送来的。不管了……你没碰过里面的东西吧?很好，很好……我可不希望我们的地雷突然爆炸，绝对不想。', '', '去找荆棘谷的列兵索尔森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (199, '水坝危机', '你取了些怪味粉末的样品。', '回去见主工程师辛德维尔七世，把你找到的线索交给他。', '这绝对是一个令人担忧的发现!', '你找到什么线索了吗，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (201, '调查营地', '我收到一条报告说，有一群猎人在风险投资公司营地所在的纳菲瑞提湖的上游创建了一片营地。通常我根本不会在意这件事，但当我听说赫米特·奈辛瓦里二世也是那群猎人中的一员时，我改变了想法。那家伙可是个名声显赫的人物，如果你了解我的意思的话，就会不像现在这样无动于衷了。$b$b你为什么不去那片营地里侦察一下呢，$n？去看看他们到底想干点什么吧。', '找到猎人营地并向藏宝海湾的克拉兹克报告这个营地的位置。', '嗯，看来我这次的情报是正确的，一如往常。真有趣。嗯，我并不认为他们会对我们的运作构成任何干扰的威胁，但或许他们需要我们所生产的出色产品。嗯……', '如何?你找到那个营地了吗?', '找到猎人的营地', '去荆棘谷找藏宝海湾的克拉兹克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (202, '库尔森上校', '你一次又一次地证明了自己的能力，而你的足智多谋略似乎甚至能与库尔森媲美。如果……如果你愿意彻底投身到与库尔森斗争的事业中去的话……也许你将成为我们反抗军的救星！$B$B他就躲在那个名叫“储藏室”的洞穴深处发号施令。你必须进入那个洞穴，干掉他身边的保镖，最终把库尔森和他的副官们都给除掉。$B$B出发吧，$N。我们的生命与希望，如今都已经全部掌握在你的手中了。', '杀掉6名库尔森精英和4名库尔森副首领，并将库尔森的徽记交给反抗军营地里的多伦上尉。', '我几乎有点不敢相信了，但你给我们带回了确实的证据……库尔森和他的副手们都已经被消灭了!你拯救了我们!$B$B这片丛林中有着无数隐藏着的威胁，但只有库尔森才是真正集残酷、邪恶和智慧于一身的敌人。现在他死了，我们都可以松一口气了。', '你能将库尔森和他的保镖们都杀死么，$N?', '', '去荆棘谷找反抗军营地的多伦上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (203, '以彼之道还施彼身', '我们正在与库尔森进行一场艰难的战斗。他是个非常优秀的战术大师，而且他的手下士兵的数量是我们的十倍！如果我们想要胜利的话，就必须使用他擅长的战术来对付他。$B$B到他在东边设立的营地里去，杀掉他的士兵，越多越好，然后在增援赶来之前撤退。', '杀死15名库尔森丛林战士，然后向反抗军营地的尤瓦中士复命。', '干得好!丛林战士的减员会帮我们减轻一些负担。$B$B不过，现在你也了解到那些与我们为敌的军队有多可怕了吧?你还想与我们并肩战斗到底吗?', '我希望你能在这次行动中获得成功，$N。要是没有你的帮助，我们真的没可能跟他抗衡这么久。', '', '去找荆棘谷反抗军营地的尤瓦中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (204, '库尔森的药物', '要想和库尔森搏上一搏，我们就必须削弱他们的医疗队伍。他在那里聚集了大批医疗人员，他们能用密林药剂治疗自己的部队，并用毒草汁液对我们的人下毒。$B$B我们要用这些药物来治疗我们自己的战士，同时我们也需要一份毒液的样本来研制解药。到库尔森的营地去把这两样东西找来吧，药品应该就在那些医疗人员和战士的身上，而毒草汁液大概是保存在营地中的一些物资箱里的。', '给反抗军营地里的尤瓦中士带回7份密林药剂和1份毒草汁液。', '干得好，$N。这些药物会极大地提高我们在战场上的生存能力与战斗能力，而这些毒液将会帮助我们尽快制出解药。', '我等着你取回那些药物与毒液，$N。', '', '去找荆棘谷反抗军营地的尤瓦中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (205, '巨魔巫术', '在我研究这些巨魔传说的时候，我希望你能帮我收集一些巨魔们施展邪恶魔法时必备的法器。到南边的那个劈颅巨魔部族的地盘上去，从他们的巫医和秘法师那里弄一些劈颅巨魔的神像回来吧。', '给反抗军营地的尼麦兹修士带回4只劈颅巨魔的神像。', '谢谢你。我现在就开始研究这些神像，看看这里面是否隐藏着库尔森堕落的秘密。', '你拿到神像了吗?那些东西里或许藏着库尔森堕落的秘密……我必须得搞清楚!', '', '去荆棘谷找反抗军营地的尼麦兹修士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (206, '麦佐斯', '库尔森的确是该死，不过……到底是谁将他带上了这条邪恶的道路呢？通过研究，我已经找到了真相：是一个名叫麦佐斯的食人魔法师干的。他住在荆棘谷东部的食人魔山中，据说他擅长心灵控制魔法，我也确信正是他使得库尔森上校堕落的。$B$B如果麦佐斯继续活在这世上，他的邪恶法术就有可能影响到更多人，或许又会出现另一个库尔森上校。$B$B杀死他，把他的心灵之眼带回来，这正是他用来诱惑他人堕落的物品。', '将心灵之眼交给反抗军营地里的尼麦兹修士。', '哈哈!你做到了!你真厉害呀，$N，愿你的力量永在!$B$B我会好好研究这只心灵之眼，看看它是否能为光明所用。如果不能的话……那我就必须毁了它。', '祝你成功，$N。麦佐斯非常邪恶，也非常强大。', '', '去荆棘谷找反抗军营地的尼麦兹修士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (207, '库尔森的秘密', '库尔森上校曾是个伟大而高贵的人，我必须得找到让他堕落至此的原因！他一定是被巨魔的魔法给控制了。要想搞清楚这一点的话，我们就得先研究一下巨魔的传说故事。$B$B据说荆棘谷中的巨魔遗迹中隐藏着四块石板，我必须得看看这些石板上到底记述了些什么东西！你去给我拓一份这些石板上的文字来，把拓片都交给我。$B$B第一块石板在巴拉尔废墟里，第二块石板在暗礁海的海底，第三块和第四块应该都在祖昆达废墟里。', '找到4块石板并将上面的内容带回去交给尼麦兹修士。', '谢谢你，$N。我会仔细研究这些巨魔传说，找出巨魔到底是用什么样的邪恶魔法控制了库尔森上校!', '$N!你找到这些巨魔的传说了吗?我必须得了解他们的秘密!', '', '去荆棘谷找反抗军营地的尼麦兹修士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (208, '王牌猎人', '$N，你现在已经成为了一位够格进入我们狩猎队的猎手了。无论是洛丹伦的战场还是危机四伏的丛林，我在哪里都没有见过有谁能像你这样拥有如此强大的战斗能力。$b$b你成功地杀死了凶残的辛达尔，狡猾的巴尔瑟拉和强悍的泰希斯。但对于这片丛林中的猎人们来说，虎王邦加拉什的头才代表着至高无上的荣耀。这只白虎正是我来这里的原因，我注意它已经很久了。如果你能杀死虎王邦加拉什，那么你无疑是这里最优秀的猎人。', '赫米特·奈辛瓦里二世要求你将虎王邦加拉什的头带回来给他。', '做得好啊!真是太出色了!恭喜你，$N，你终于做到了其它人从来都没能做到的事情。$B$B我很荣幸地欢迎你成为我们这支伟大的狩猎队的一员。再没有人会怀疑你优秀的狩猎和追踪技巧了!$B$B恭喜你!', '我等着你回来，$g小伙子:姑娘;。虎王邦加拉西有好几次都让我狼狈地爬回营地，它的确是块难啃的骨头。', '', '去荆棘谷找奈辛瓦里远征队的赫米特·奈辛瓦里二世。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (209, '劈颅巨魔的獠牙', '靠不停地猎杀老虎来保证对南海岛屿的虎牙出口实在是苦差事，不仅难度高，而且花费也也高。幸亏我们找到了一种替换品，就是这些劈颅部族的巨魔的獠牙。$b$b嘿，只要你不说，买家就不会知道，对吧？给我搞一批巨魔獠牙来吧，这样我们就能应付每月一次的供货啦！', '给藏宝海湾的科博克带回18根劈颅巨魔的獠牙。', '啊，漂亮，漂亮!嗯嗯，虽然你可以做得更好，完全把这些家伙清―算了，没关系，算了!我非常感谢你，$N，由于你的帮助，我们的产量和出口量都会有所提高的!好极了，现在，我还有点其它事情……', '他们确实是帮挺难对付的家伙。那么，你的运气怎么样?请原谅我的急躁，不过我的确是太牵挂这件事了!到底怎样?', '', '去荆棘谷找藏宝海湾的科博克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (210, '克拉兹克的烹调锅', '在营地里，我是专门负责伙食的。过去的活真的很多，让我每天都要忙到死，直到我从藏宝海湾的地精商人那里买了台多功能机械烹调锅才有所改观。这锅实在是太棒了！它节省了我许多的时间……我是说，在它坏掉之前！$B$B你能帮我把这锅带到那个地精商人那里去，让他给我修理一下吗？他的名字叫克拉兹克。', '把克拉兹克的烹调锅带给藏宝海湾的地精克拉兹克。', '噢，我看看，这不是我的烹调锅嘛!多么精致的杰作呀，但现在却变成了一堆破铜烂铁。让我看看到底是出了些什么毛病呢……$B$B啊哈!看来是蒸汽泵锈掉了，垫圈也破了，齿轮也磨坏了。天啊，那哥们难道整天拿这可爱的小锅煮大象么?$B$B你问我能不能修好它?鱼儿会游么?鸟儿会飞么?当然!$B$B但是我可不白修，嗯嗯，总是要互惠互利的嘛……', '你好!你找我有事?', '', '去荆棘谷找藏宝海湾的克拉兹克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (211, '啊，安多哈尔！', '啊，进攻安多哈尔并彻底击败那个巫妖的时刻终于来临了！$B$B召唤者阿拉基就盘踞在安多哈尔的废墟中，他的贴身卫队无时无刻不在他的身边保护着他。你需要召集强大的盟友才能击败他。$B$B消灭巫妖，$N，从它的护符匣里拿出一块碎片来，作为你获胜的证据！', '把阿拉基的护符匣碎片交给西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特。', '你成功了!巫妖阿拉基终于被打败了!$B$B你今天为联盟做出了巨大的贡献，$N。你的勇气和毅力是成为真正的英雄所必须具备的素质。请接受这个作为荣耀的象征，让所有看到它的人都知道你为联盟赢得了辉煌的胜利!', '你已经接到我指派的任务了，$N。你拿到那个巫妖的骨匣裂片作为完成任务的证明了吗?', '', '去西瘟疫之地找冰风岗的指挥官阿什拉姆·瓦罗菲斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (212, '冷餐会', '我的拿手菜之一就是橙味冻蜥肉，但现在的问题是……这种肉很容易变质，而且我今天晚上必须得在一位贵族的生日晚宴上做这道菜！$B$B救场如救火，如果你能马上从刚被宰掉的冷眼蜥蜴身上割块冷蜥蜴肉给我的话，我就给你做顿堪比国宴的美味尝尝！$B$B冷眼蜥蜴一般会在荆棘谷西北海岸的沙滩上晒太阳，离这里有点远，不是么？所以你得赶紧行动啦！', '杀死一只冷眼蜥蜴，取一块冷蜥蜴肉并把它带给“蓝色隐士”旅店里的安古斯·斯特恩。', '啊，好肉好肉!实在是……太感谢了!$B$B不好意思，我现在必须得先把这冷眼蜥蜴的肉先给切成肉排，然后用酱汁淹上，最后再给宴会准备点配菜。', '$N!拿到冷眼蜥蜴的肉了吗?我必须开始作准备了，否则晚上的宴会可就完了!', '', '去艾尔文森林找明镜湖的安古斯·斯特恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (213, '恶性竞争', '太猖狂了！吉尔里兹把贸易亲王们指定的要员们都从这里赶了出去，这件事已经够糟的了，现在他居然还和那些声名狼籍的海盗们往来！$b$b里维加兹不会坐视不理的，他允许我按自己的方式来解决这些问题。$b$b我的方式是什么？偷！最近，风险投资公司的地质学家们正在研究他们从矿里挖出的一种奇怪的蓝色水晶，从那群地质学家手里搞些样本回来给我，当然，我不关心你用怎样的手段去搞。', '给藏宝海湾的科博克带回8块打磨过的水晶。', '太美了。这些水晶都是被打磨过的，这只能证明，他们准备将这些水晶作为某种燃料或是催化剂来使用。我对这方面了解得不多。看来我得给首席化学家基格弗特送一份样本过去，让他研究一下。', '我急需那些石头，$N。无论如何都要给我搞到!快去干吧，细节问题与我无关!$B$B我只要结果，$N，别的什么都不要。', '', '去荆棘谷找藏宝海湾的科博克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (214, '红色丝质面罩', '迪菲亚兄弟会的人都会戴着一种红色的面罩，这显然已经是个尽人皆知的秘密了。但我们又了解到，这个面罩的材料是他们的成员在帮会内部地位的象征。$b$b既然如此，那么我希望你出马杀死一些兄弟会的高阶成员。他们的最高阶成员无疑都躲在范克里夫的秘密藏身处附近。作为证据，你要给我带回10条红色丝质面罩来，这样我才能给你奖励。祝你好运，$N。', '给哨兵岭哨塔的哨兵瑞尔带回10条红色丝质面罩。', '干得好，$N!我以人民军的名义对你为西部荒野所做的一切表示崇高的敬意。有你这样勇敢的$C帮助我们，总有一天我们会让这片土地重新回到自己手中的。', '怎么样，你把迪菲亚强占的土地都夺回来了没有?如果你完成了这个任务，就拿出10条红色丝质头巾来作为证据。', '', '去找西部荒野的哨兵瑞尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (216, '蓟皮熊怪的麻烦', '蓟皮熊怪在威胁我们的扩张！我们东面的蓟皮村挡住了从这里通往碎木哨岗的道路，这是一条可以包围阿斯特兰纳的道路，没有它，我们就会让联盟得到一条额外的扩张路线。$B$B$N我们决不允许有这样的缺口存在！$B$B进入蓟皮村，尽量减少那些熊怪的数量。你会为这项任务得到补偿的，但更重要的是，你会为部落尽到你的职责！', '杀死8个蓟皮复仇者和8个蓟皮萨满祭司。他们大部分都位于佐拉姆海岸东部的蓟皮村里。任务完成后回到灰谷佐拉姆加前哨站的卡拉恩·阿玛卡那里复命。', '干得好，$C，干得好!我会继续派军队来消灭熊怪，但我至少能指望联盟不再打这条路的主意了。部落对灰谷的征服行动就要全面开始了!$B$B你赢得了你的报酬，英雄。我向你致敬!', '你参加对蓟皮熊怪的战斗了吗?只要我们两座基地之间的道路畅通无阻，我们占领整个灰谷的机会就可以大大增加。', '', '去灰谷找佐拉姆加前哨站的卡拉恩·阿玛卡。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (217, '保卫国王的领土', '$N，我的侦察兵已经找到了最近一段时间来频频组织穴居人对我们发动袭击的首领。这帮洛克莫丹的怪物好象是由一个叫格劳姆格的酋长领导的，不过格劳姆格身边守卫森严，有两个精英护卫纳什尔和布劳勒尔从不离他左右。$b$b如果你想证明自己的价值的话，$N，我希望你能接下杀掉格劳姆格和他那两个手下的任务。一旦穴居人失去了领导，我们就有机会把这些怪物重新赶回地下。', '杀掉穴居人首领格劳姆格及他的两个护卫，纳什尔和布劳勒尔。然后回到南部警戒塔向拉格弗斯上尉报告。', '干得很出色，$N!你为洛克莫丹带来了希望。格劳姆格一死，我们就更有希望把穴居人从这片土地上彻底消灭掉。', '格劳姆格和他的两个护卫纳什尔及布劳勒尔还活着。他们这三个家伙不死，你的任务就不能算是完成了。矮人王国需要你的帮助，$N。', '', '去洛克莫丹找国王谷的拉格弗斯上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (218, '被窃取的日记', '我的日记！那帮巨魔把它拿到洞穴里去了。拿着日记的那个家伙……他是一个皮肤和面颊上都涂着奇特印记的青面獠牙的家伙，我打从娘胎里出来后还没见过像他那样丑的。$b$b你应该能对付那些巨魔，帮我把我的日记拿回来怎么样？', '格瑞林·白须要你去杀掉冷酷的格瑞克尼尔，并取回他的日记。', '太棒了，$N!谢谢你帮我取必日记。啊呀，看来寒脊山谷的巨魔完全在控制之中了，我也没什么好担心的了。$B$B等我写完报告后，得有人帮我把它送给我的兄弟森内尔。', '$N!日记拿回来了吗?', '', '去找丹莫罗的格瑞林·白须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (219, '失踪人员', '终于…有人来了……来自联盟的朋友！$b$b救救我…求你了…$b$b我只记得…一群邪恶的兽人让我们团全军复没……大多数人都被杀了，我的头被狠狠地打了一下，眼前一黑就倒下去了。现在我被关在这个洞里，奄奄一息……$b$b我必须得回到镇上去…拜托了…你是我最后的希望了……', '保护基沙恩下士回到赤脊。', '你为王国做出了杰出的贡献，$C。感谢你帮助基沙恩下士从黑石兽人那里逃回来。你的英勇行为理应受到奖励。', '嗯?', '保护基沙恩下士回到赤脊山。', '去赤脊山找湖畔镇的治安官马瑞斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (220, '水之召唤', '在给你图腾之前，伊斯伦还会有一个任务让你去完成。我给你的那瓶水在任何情况下都会很有用。$B$B去吧，去找伊斯伦。我们会再见的。', '把一瓶最纯净的水交给贫瘠之地提度斯阶梯的水之先知伊斯伦。', '啊，布瑞恩制造和赐福的泉水，而且制造这泉水的原料是你收集的。$B$B这只小瓶里的液体是我为你制作灵契的关键，不过，它在另一项任务中也有用处。$B$B通过我为你制作的灵契，你就可以看到水之灵，这些水之灵在幽暗城南方银松森林的神殿中。而其余的泉水的作用……我会在你准备好的时候告诉你的。$B$B你准备好再跑一趟了吗，$N?', '又见面了，$N。你看起来不错。$B$B怎么这么快就回来了?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (221, '森林里的狼人', '你可能已经注意到了，在树林周围有些个头较大的狼人和那些夜行织影狼人一起游荡。据我们所知，大多数狼人都是这类夜行黑暗狼人。$b$b我还发现在小镇西南的烂果园里已经到处都是他们的身影了，这些狼人比你之前遇到的那些更难对付。$b$b小心点。', '为夜色镇的卡洛尔杀掉12个夜行黑暗狼人。', '你在和夜行黑暗狼人的战斗中表现得非常出色，$N。不过他们似乎是杀不尽的。每次我们占了一点优势，他们就会补充更多的兵力。$B$B到底是什么邪恶的力量把他们送到这里来的?他们为什么要来侵占我们这个不幸的国度……$B$B我相信卡尔文主人一定会查出问题的根源。', '这么快就回来了，$N?你不是跑来告诉我你已经放弃了吧?', '', '去暮色森林找夜色镇的卡洛尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (222, '森林里的狼人', '你之前的功绩使我确信，你已经可以去对付森林里最凶猛的狼人了。$b$b在这一带所有的狼人中，夜行邪齿狼人和夜行堕落狼人是最危险的。他们就住在南边的洞穴和矿井里。$b$b你甚至能从很远的地方看见他们的篝火。', '为夜色镇的卡洛尔杀掉8个夜行邪齿狼人和8个夜行堕落狼人。', '$N，实话说吧，我没想到你能做得这么好，你显然是个出类拔萃的$C。嗯，如果你想正式加入卡尔文主人的队伍，我很乐意为你写一封推荐信。', '他们很危险吧?不过不要害怕，$N，为光明而战的人决不会失败!', '', '去暮色森林找夜色镇的卡洛尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (223, '森林里的狼人', '拿着这个，$n。把这个带给卡尔文主人。$b$b<他取出一张褪色的羊皮纸交给你>$b$b如果再多些像你这样的力量加入，我们就能让守夜人相形见拙！也许到那个时候，我们就能够彻底解决这些现在令我们疲惫不堪的危机。', '把卡洛尔的便笺交给乔纳森·卡尔文。', '对不起，我刚才冷落你了，$N，不过你肯定能看出我非常忙。你已经得到了卡洛尔的赞许，他还特意为你写了推荐信―我可以肯定地说，你所做的决不仅仅是鸡毛蒜皮的小事。$B$B我们现在的处境相当危险，$N，任何人的帮助对我们都很宝贵。我们要抗击恶魔、不死生物，以及所有与他们为伍的人。你要非常小心谨慎地行事，不要相信任何不愿向我们伸出援手的人。$B$B为了圣光的荣耀，我们一定要战斗到底。', '嗯，有什么事吗?请快一点，我还有紧急的事情要处理。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (224, '保卫国王的领土', '我们要保卫洛克莫丹，$N！国王的士兵都在遥远的战场上英勇作战，但我们的家园却危机丛生。每个裂缝里都有穴居人在不断冒出来！四处横行的穴居人已经成了铁炉堡最大的威胁，我们一定要消灭这些恶心的怪物！$b$b我们需要像你这样勇敢的冒险家来帮忙消除穴居人的威胁。杀掉10个碎石穴居人和10个碎石怪斥候，然后回来向我汇报。', '南部警戒塔的巡山人库伯弗林特要你杀掉10个碎石穴居人和10个碎石怪斥候。', '干得好，$N!你以战斗证明了你有着不可思议的勇气。有了像你这样的$r的努力，我们一定能打败穴居人。你为国王陛下立了大功!$B$B如果你还想帮忙的话，我建议你和巡山人格拉维戈谈一谈。队长派他去完成一些艰难的巡逻任务，我想他一定会需要你的帮助。格拉维戈就在塔里。$B', '洛克莫丹正在四面受敌，$N!我们需要联盟里每一个有能力的成员帮助我们。你干掉10个碎石穴居人和10个碎石怪斥候了吗?', '', '去丹莫罗找南部警戒塔的巡山人库伯弗林特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (226, '恶狼成群', '我和斯温的处境越发危险了，这儿就我们俩，要吃饭就得打猎捕鱼。但是每次我们带着肉和鱼回营地的时候，那些从森林跑出来的恐狼都好像要扑上来咬一口似的。别提有多危险了！$B$B如果你能替我们除掉这些狼，也许我们就能过得轻松些。它们经常在北边和东边的小河周围出没。', '杀掉12只饥饿的恐狼和8只疯狂的恐狼，然后到斯温的营地中向拉尔斯交差。', '很好。你已经除掉了不少狼，没有它们跟在身后，我们就可以一门心思地对付摩本特.费尔了。$B$B拿着这些火弹。这是镇里的人做的，他们送了很多这种东西来帮助斯温。', '你还在捕猎那些狼吧?', '', '去暮色森林找寂静河岸的拉尔斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (228, '摩拉迪姆', '我的探子说摩拉迪姆沿着一条穿过墓地的弯曲怪异的小路，在暮色森林中四处游荡。我们曾把他的尸体埋在山上那座小屋的后面，你知道在哪儿吧？$b$b除了祝你好运之外，我没什么能帮你的了。', '杀掉摩拉迪姆，把他的头骨交给夜色镇的指挥官阿尔泰娅·埃伯洛克。', '你把他干掉了?这可不是件容易的事，$N!我代表夜色镇的人民和所有守夜人感谢你!$B$B啊……对了，还有一件小事……', '就算你对付不了摩拉迪姆，我也不会责怪你的，$N。我们有很多最棒的守夜人都死在他手下。', '', '去暮色森林找夜色镇的指挥官阿尔泰娅·埃伯洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (230, '斯温的营地', '挖开土堆之后，你发现了一本不大的书，上面沾满了泥土。$B$B书上没有写标题，不过……书里写着一些斯温想要知道的东西。', '把你从斯温的农场找到的书交给他。', '<斯温翻开书看了看，然后猛地阖上了书。>$B$B我看见的那个模糊人影目睹了我的家人被杀!我想问他一些问题……如果我知道他是谁该有多好!', '你找到什么了吗??请让我看看……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (231, '女儿的爱', '拿着这个，请把这个放到他的坟墓上。也许…也许这样他就可以知道我现在过得很好，而且我们也不会因为他所做的事责怪他。$b$b<她含着眼泪，把戴在右手上的一只戒指摘下放在你手里>$b$b还有……谢谢你，$n。', '把莎拉·拉迪莫尔的戒指拿到摩根·拉迪莫尔的坟墓上去。', '<一个虚无缥缈的声音在风中响起……>$B$B这是……萨拉?她还活着吗?现在我肩上的重担终于可以卸下了……$B$B$N。拿走我的剑…拿走阿契厄斯吧……我再也不需要它了，因为我的灵魂终于可以安息了。我努力想要做一个好人，可是我不配再拿着这把剑，你可以继续带着这把光明的圣剑。$B$B莉丝，我的挚爱……', '让我安息吧……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (232, '金格的货物', '皇家药剂师学会需要你的帮助。仔细听好了，这个行动对你我都有好处。$B$B隔壁的药剂师基佛看上去有些……疯疯癫癫的，但如果他的研究项目能早点找到一个有眼光的买家的话，早就已经得到丰厚的成果了。幸运的是，现在我已经把这个研究项目买了过来。我要你把这份订货单交给蓝月杂货店的店主奥雷萨多·卢卡那里，他会给你一只实验工具包。当你拿到工具包之后就尽快回来向我报告，我会告诉你下一步任务的详细情况。', '把订货单交给幽暗城的奥雷萨多·卢卡。', '啊，金格需要一个实验工具包?这家伙居然不自己来，这真让我有点伤心。$B$B好吧，我现在就动手帮你准备实验包。', '你好，我能为你做些什么?你是为了皇家药剂师学会的事情而来，还是仅仅来这里随便逛逛?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (233, '寒脊山谷的送信任务', '嗯，$g小子:姑娘;，我想也许你不会帮我这个忙的。今天从隧道那边来了一大堆信，我想我没时间把它们都给发出去了。$b$b这些信都是寄给塔林·锐眼的。沿着这条路向西走就能找到他，就在结冰的湖泊附近。$b$b你能帮我这个忙么？', '把这一摞信件送给寒脊山谷的塔林·锐眼。', '谢谢，这段时间我一直在等这些信……$B$B但是这批信并不都是给我的。喏，这封是给格瑞林·白须的，他就住在附近，如果方便的话，请你把这封信交给他。', '嗯?你有东西交给我?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (234, '寒脊山谷的送信任务', '如果我没记错的话，格瑞林的营地就在这条路的尽头，沿着路往东南方走就是了，他一定正在等着这封信呢。', '把这封信送给寒脊山谷的格瑞林·白须。', '啊，太棒了。我终于收到来自铁炉堡的消息了。', '有什么我可以帮忙的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (236, '战车的燃料', '$n！你总算来了。虽然上一场战斗已经告一段落了，但我们还是应该为下一场战斗做好准备！到冬拥湖东南方的烈焰之坑去，弄一些永恒灰烬回来。$B$B这种灰烬里含有煤炭，可以充当攻城车辆的燃料。$B$B哦，对了，如果你在烈焰之坑遇到部落的渣滓，尽管杀了他们，把他们手里的灰烬抢过来。绝对不能让他们在下一次战斗中有丝毫的优势。', '冬拥堡垒的攻城大师斯托汉德要你转至烈焰之坑，收集10份永恒灰烬。', '非常好!这将有助我们，在不日即来的战斗中，燃起熊熊的战争烈焰。', '嗯哼?你是不是被部落打败，馀烬被抢走了，只能蹲在路边哭?', '', '去找冬拥湖的攻城大师斯托汉德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (237, '保卫国王的领土', '巡山人库伯弗林特总是在我面前称赞你，$c。因此现在我要交给你一个极其重要的任务，你必须不断给那些入侵的穴居人施加压力，直到我们的兄弟们从联盟前线回来。$b$b到南部的丘陵去，杀掉10个碎石怪击颅者和10个碎石怪先知。你的行动可以为我们赢得一点时间，完成任务后就回来向我报告。', '南部警戒塔的巡山人格拉维戈要你杀掉10个碎石怪击颅者和10个碎石怪先知，然后回去向他汇报。', '你很出色地完成了任务，$C。国王会为你骄傲的。$B$B不过，铁炉堡给我们许诺的增援一直没有来。很明显，战争前线一定洒满了我们同胞的鲜血……前方不断传来的人员伤亡消息让我很不好受。我们不能让他们白白牺牲。在这个艰难的时期，我们必须团结在一起，让联盟恢复荣耀。$B$B你去和巡山人沃尔班谈一谈关于重新分配任务的事吧，现在我们比任何时候都更加需要你的帮助。$B', '我们需要更多的时间，$N。你的任务是杀掉10个碎石怪击颅者和10个碎石怪先知。在我们得到增援之前，必须不断给敌人施加压力。现在可不是闲着的时候。', '', '去洛克莫丹找国王谷的巡山人格拉维戈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (238, '金格的货物', '东西都准备好了，$n。毫无疑问，药剂师金格正在等着这批货。马上把这些东西送到她那里去，告诉她我已经把价钱记在学会的帐上了。另外，请代我向她致以最高的敬意。$B$B好了，不要再站在这里了，快点出发吧！', '把采样工具包交给幽暗城的药剂师金格。', '太好了―我很高兴能和你这种不浪费时间的$C合作。$B$B在我调整了这个工具之后，你就可以出发去搜寻一些重要的资料材料了。$B$B我只需要一点点时间就可以完成调整。在这段时间里，你可以考虑一下要带些什么东西去沙漠。$B$B没错，我说的是沙漠。', '嗯，我想卢卡和你都忙得不可开交了。不管怎么样―请快把采样工具包交给我吧。我要对它进行一些调整，以便搜寻合适的基础性材料。$B$B你身上是带着采样工具包的，对吧?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (240, '基特斯的美餐', '完成了——格鲁奥烹制的黑“蟹”蛋糕！', '把黑蟹蛋糕拿回去交给基特斯。', '啊哈!谢谢你，$N。这蛋糕真是太好吃了!$B$B请收下这些吧，这是我给你的报酬!', '$N，你回来了!拿到我想要的食物了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (245, '蜘蛛的威胁', '你好啊，$c。你有没有看到过在西边出没的那些蜘蛛？这些八条腿的东西实在是太多了，多到我们没法应付，指挥官又没有多馀的人力可以从夜色镇派来协助我们。$b$b我实在是不好意思向你开口，不过……看样子你好像能对付它们。我不能承诺给你什么贵重的宝贝，不过如果你帮助我们除掉这些肮脏的臭虫，我肯定会奖赏你的。$b$b哦，对了，给你个忠告：尽量别碰到它们的毒液。', '守夜人道茨要你杀15只规模结网毒蜘蛛。', '啊!你回来了!看起来还不错嘛。当然了，$N，守夜人对你的贡献非常感激，我说过要给你奖赏的，拿着吧。$B', '对付蜘蛛的时候你得小心点，我们已经有不少人被它们杀掉了。要知道，看见蜘蛛用毒液把人放倒以后再把他们倒挂在蜘蛛网上并不是什么有趣的事情。$B$B我可不想让某只蜘蛛把你当午饭给吃了。', '', '去找暮色森林的守夜人道茨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (246, '审时度势', '我们实在是没有多馀的人手了，但我们也不能对你报告中提到的那些豺狼人不闻不问。$B$B侦察南赤脊山附近豺狼人的动向,并尽可能地杀掉足够多的豺狼人,然后向我回报他们的数量，好让我们对他们的威胁尺寸有个正确的认识。$B$B暴风城军方需要你的帮助，$N，你会得到奖赏的。', '杀死10个混血赤脊山豺狼人和6个赤脊山偷猎者，然后向湖畔镇的菲尔顿副队长复命。', '<菲尔顿副队长听取了你的报告……>$B$B这些豺狼人还真不少，再加上你又告诉我他们都是些强壮的家伙，事情可就棘手了。你这次的工作一定非常艰难。$B$B给，这是你应得的酬劳，$N。我们非常感谢你的帮助。$B$B另外，如果你暂时不打算离开这里的话，就去跟湖畔镇里的所罗门镇长和治安官马瑞斯谈谈吧。我们的情形越来越让人绝望了―我敢说他们两人一定需要你的帮助。', '请原谅，$N，我们有太多的事情要处理。如果你没什么事情要报告的话，我就去忙其它的事了。', '', '去赤脊山找湖畔镇的菲尔顿副队长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (248, '监视', '我监视伊尔加拉之塔已经很久了，并且我发现，莫甘斯与占据了石堡要塞的兽人之间起了矛盾。我不知道他们之前产生纷争的原因是什么，但你可以帮我揭开谜底。$B$B带上阿祖拉的铭文饰品，然后到那个能监视石堡要塞的岗哨顶部去。$B$B找一个合适的地方，把铭文饰品放进去，一个盒子或者罐子之类的东西都可以，只要铭文饰品不会被注意到就行，那样我的目的就达到了。', '爬上赤脊山石堡要塞一旁的哨塔。$B$B为阿祖拉的铭文饰品找一个合适的容器。', '把阿祖拉雕纹放在这里再合适不过了，它能让塞欧克瑞图斯将石望要塞里所有的一切都看个明明白白。', '这只罐子以前是用来装劣质烈酒的，但现在却被丢在一堆木桶旁边。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (249, '莫甘斯', '在长期的侦察监视之后，我终于发现了莫甘斯的计划。$B$B他正在寻找月神镰刀……而且，他甚至可能已经找到了。如果他有了那东西，整个赤脊山脉地区，甚至是整个暴风王国都会被他的黑暗力量所征服。$B$B我还没有想到对付莫甘斯的办法，但我怕如果现在不行动的话，也许以后就没有机会了。所以我希望你能杀进伊尔加拉之塔与莫甘斯交战。$B$B战胜他，然后把他的暗影坠饰带回来给我。如果你成功了的话，整个王国都将以你为傲。', '击败莫甘斯。$B$B将他的阴影坠饰带给塞欧克瑞图斯，他就在艾尔文森林内的阿祖拉之塔中。', '干得好，$N。战胜了莫甘斯，你等于是把暴风王国从坟墓前拉了回来。$B$B这件小礼物送给你，希望你能笑纳。如果这是和平年代的话，我还会给你放一段假，让你过过平静的日子。$B$B可惜情况不允许这样，我只能祝你今后好运，祝你下次也能凯旋而归。', '快一点，$N，在莫甘斯伸出他的魔爪之前解决掉他!', '', '去艾尔文森林找阿祖拉之塔的塞欧克瑞图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (251, '翻译亚伯克隆比的信', '请把你给我的这封信拿给希拉·沃宁迪看看。他对语言和古代艺术很有研究——我看也只有他能翻译这封信了。', '把写给艾尔罗的信拿给希拉·沃宁迪。', '<希拉开始翻译信件……>', '亚伯克隆比写给镇长的信?我不认识这个人，但是如果他确实住在墓地那边，我看他的脑子一定是坏掉了!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (252, '翻译好的信件', '天哪！如果信上所写的内容都是真的，那亚伯克隆比所做的事情……太可怕了！$B$B你最好还是把翻好的信拿回去给艾尔罗看看。$B$B快一点，我感觉到这座小镇的末日就要到了……', '把翻好的信带给艾尔罗·埃伯洛克公爵。', '<艾尔罗读着信，他的脸色突然变得苍白起来。他抬头看着你……>$B$B你是出于好意帮助亚伯克隆比的，不过你的行为却给我们的小镇带来了一场劫难。$B$B<艾尔罗开始若有所思……>', '啊，信翻译好了?请让我看看……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (253, '藏尸者的妻子', '藏尸者是个我们经常用来吓唬孩子的故事里的人物。他曾是个善良的炼金师，但因为妻子伊莉莎的死而变得疯狂。为了让妻子复活，藏尸者用黑暗的魔法将自己的精华放入了亡妻的胸膛里。$B$B伊莉莎复活了……不过她也受到了诅咒，开始疯狂地攻击人类，藏尸者不得不将他的妻子埋了起来。$B$B他的精华就是他全部的力量，找到他妻子的坟墓，把他的精华拿回来，就可以打破他的力量。', '找到伊莉莎的坟墓，从她的身上取回藏尸者的精华，把它交给艾尔罗·埃伯洛克。', '干得好!藏尸者的心脏中的魔法可以用来抵抗他的邪恶力量，同时也是保护夜色镇的利器。$B$B你为我们做了件大事，$N。你的名字将永远留在我们的史册里。', '你找到伊莉莎的坟墓了吗?找到藏尸者的心脏了吗?', '', '去暮色森林找夜色镇的艾尔罗·埃伯洛克公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (255, '雇佣兵', '我等了两个月才得到了从铁炉堡传来的消息，说是会有少量士兵来帮助我们防守塞尔萨玛，不过他们还得再等两个月才能到这儿来！我们的镇子没人守卫已经够糟了，但是我们的挖掘场和水坝——这些地方都随时面临着被袭击的危险！$b$b看来我已经没有选择了，必须临时征召一点士兵才行。$b$b你怎么样？你看上去挺合适的，$c。有一群食人魔在洛克湖的东北方安营扎寨，你能不能帮忙再召集点人，去把那些家伙赶走？', '塞尔萨玛的镇长埃罗恩·钝鼻雇你去杀掉4个莫格罗什食人魔、4个莫格罗什蛮兵和4个莫格罗什执行者。', '啊，真是个好消息!我和塞尔萨玛的居民们都非常感激你的帮助。解决了巨魔的问题之后，我们就可以把注意力转向那些该死的穴居人了。', '你做得怎么样了?', '', '去找洛克莫丹的镇长埃罗恩·钝鼻。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (256, '通缉令：卓克苏尔', '以塞尔萨玛镇长之令：$b$b卓克苏尔，袭击塞尔萨玛镇、巨石水坝及挖掘场的食人魔的领导者和组织者。现要求不惜采用一切手段杀死卓克苏尔。$b$b若有人呈上杀死卓克苏尔的证明，镇长将给予巨额奖金。$b$b卓克苏尔最后一次出现是在洛克莫丹东北部的食人魔营地里。', '杀了卓克苏尔，把他的徽记带给塞尔萨玛的镇长埃罗恩·钝鼻。', '呦!这是什么?你为什么拿着这个……$B$B这不是―天哪!这不是那个巨魔的脑袋吗?这就是我们正在通缉的恶棍!这是给你的奖赏，我代表塞尔萨玛镇感谢你。', '嗯?你有什么事吗?', '', '去找洛克莫丹的镇长埃罗恩·钝鼻。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (257, '自豪的猎人', '你觉得自己可以和勇敢的达瑞尔相提并论？我可不这么认为，当然咯，如果你不服气的话，完全可以试试看。我会让你去做一件非常困难的事情，困难到以你的能力恐怕根本没法摆平，所以就算你完成不了也用不着气馁。$b$b有一群秃鹰在这一带筑巢，你去试试能不能把它们解决掉？告诉你吧，如果你能在十五分钟里完成这个任务，我就把我的弓剑或是火枪送给你。<他轻蔑地上下打量着你>$b$b看上去你也没什么可以输掉的东西。', '杀死6只山鹫，然后回到旅行者营地见年轻的达瑞尔，时限为15分钟。', '什么?你成功了?$B$B相信我，$N，不要把我的话放在心上。我的意思是，就算是一个没经验的年轻家伙，只要他手里有弓箭就能杀了这样的……小东西。你没有杀太多秃鹫吧?我们可不想让它们就此灭绝了。$B$B好吧，呃……我当然会守信用的。', '运气不佳?别太难过了，$N……$B$B并不是每个人都像我这么厉害的。', '', '去洛克莫丹找旅行者营地的年轻的达瑞尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (258, '猎人的挑战', '你叫$n，对吧？看得出来，完成第一个考验之后，你已经被骄傲冲昏了头脑，不是吗？我跟你说过的，那没什么了不起。$b$b你应该再试试去捕杀野猪。相信我，这和捕杀寒脊山谷里那些野猪可不一样，所以你最好当心点。这次我只给你十二分钟。$b$b失败了也别难过。不过如果你成功了，我就把我的衬衣脱下来给你！$b$b我有没有跟你说过我这个着名的伤疤是怎么来的？没有？好吧，两年前的一天……', '杀掉5只老山猪，然后回到旅行者营地去见年轻的达瑞尔，时限为12分钟。', '你看起来可不怎么样，是不是山猪给你带来不少麻烦?别担心，你的事我会保密的，我可以想象得到，别人要是知道了你这么差劲，肯定会在背后嘲笑你。$B$B啊?!你杀掉那些山猪了?我…呃…我是说…我一点也不感到奇怪!任何人都能―赌注?$B$B什么赌注?', '被一个你不认识的人嘲笑确实会让你羞得无地自容，不过你也别太难过了，$N。$B$B嗯?我没记错你的名字吧?', '', '去洛克莫丹找旅行者营地的年轻的达瑞尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (261, '血色之路', '坦率地说，我们现在正在与天灾军团交战。他们是一群致力于腐化我们的人民、污染我们的土地的恶魔。我们一定要在他们将我们最后的堡垒彻底血洗、将我们的世界彻底拖入黑暗之前阻止他们。我们血色十字军发誓要奉献出全部身心，与天灾军团斗争到底。$B$B如果你也如此宣誓了的话，鼓起你的勇气并证明你的忠诚——去与凄凉之地的亡灵劫掠者们作战吧，它们都聚集在那个地区南部的白骨之谷里。$B$B只有这样，十字军才会接纳你。', '杀掉30个亡灵劫掠者，然后向尼耶尔前哨站的安东修士复命。', '你证明了你的决心，血色十字军也将接纳你。$B$B如果你不会畏惧为正义而进行的杀戮，那么或许你未来的道路就是我们血色十字军的道路……', '天灾军团每天都在不断壮大。如果你真的想阻止他们，就证明给我看。', '', '去凄凉之地找尼耶尔前哨站的安东修士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (262, '模糊的人影', '我一定要搞清楚那个躲在暗处目睹我全家被杀的人到底是谁！$B$B求求你了，$N，你已经表现出了你的足智多谋，请你帮我找出那个模糊的人影到底是谁，我一定要知道他到底是谁！$B$B我没法再给你提供更多线索了，不过……拿着这本你在农场里找到的书，也许镇上有人能够帮助我们找到它的主人。', '带着你从斯温的农场找到的书，把它拿给夜色镇上的人看看。', '嗯……最近有人动过这本书，而且这个人身负仇恨。不过他没有在书上留下太多痕迹，至少这本书原来的主人没有留下什么痕迹。$B$B但是我可以肯定，这本书原来的主人不是夜色镇的人。', '如果你找到了什么和那个模糊的人影有关的东西，别忘了让我看看。也许我能从中找出些和它的主人有关的蛛丝马迹来。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (263, '保卫国王的领土', '巡山人告诉我你很勇敢也很能干，$N。我们这儿就需要像你这样的$r。穴居人的问题一点也没有好转，预备军都被派到前线去了，我们在这儿孤立无援。不过现在我们有你这样一个经验丰富的$c，事情就好办一些了。$b$b去杀掉10个碎石怪萨满祭司和10个碎石怪断骨者，让我们瞧瞧你是不是名副其实的穴居人杀手。', '南部警戒塔的巡山人沃尔班要你杀掉10个碎石怪萨满祭司和10个碎石怪断骨者。', '看到你的第一眼我就知道你会让铁炉堡以你为傲，$N。你为国王陛下立了大功，而且你已经证明了自己对王国的忠诚，现在你可以去和队长谈一谈，看他是否有更重要的任务交给你。$B$B向你致敬，$N!', '这么快就回来了?也许我还没说清楚，我要你去杀掉10个碎石怪萨满和10个碎石怪断骨者，$N。现在出发吧，穴居人杀手!', '', '去丹莫罗找国王谷的巡山人沃尔班。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (264, '至死方休', '太过分了！他因为那该死的十字军离开了我，说什么“圣光是我们用来与亡灵抗争的最重要的东西。”$B$B那么，他的孩子呢？我呢？我日复一日地等他……一直在默默地支持着他那该死的职责！$B$B看看“公正”带给你的一切，$N！他已经死了，而我却成了他曾经想要消灭的东西！$B$B把这个垃圾放到他那修在瑟伯切尔的坟墓上吧。我不想再跟他有任何联系了！', '把克拉莉斯的坠饰放在银松森林尤瑞夫的坟墓上。', '你把这个毫无价值的坠饰放在坟墓上，坠饰上的宝石似乎明显的暗淡了下去。$B$B当你起身要离开之时，你低头看了看这个坠饰，它死气沉沉地躺在棺材顶部的浮雕的手中。你的思绪被一阵穿过瑟伯切尔的阴风打断了。一时间，你周围的一切都重新归于寂静。', '这块石头摸上去冰凉刺骨，但是显然没有人照看。这里遍地都是垃圾，棺材顶上的雕刻布满了又深又长的缺口，周围的植物长得比坟墓还高。$B$B没人关心是谁被埋在这儿。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (265, '继续搜寻', '拿回你的书吧，$N，祝你好运。你可以去问问镇上的其它人，他们也许还能给你提供更多的线索。$B$B对了，我还有个线索可以提供给你——这本书的作者不是夜色镇的人，不过书却是在镇里买来的。', '看看其它的镇民有没有关于模糊的人影的线索。', '啊，我想起来了!我一个月前把这本书卖给了一个很可疑的人。他没有说自己的名字，不过我看得出他是个神经过敏、紧张兮兮的家伙，总是不停地东张西望。$B$B我希望这些能对你有所帮助……', '有时我会把空白的书卖给学者、法师，或是任何想要\r\n写日记的人。$B$B对于过去几个月来买书的每一个人，我都记得很清楚……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (266, '调查旅店', '这是你的书，祝你好运。$B$B你不妨去旅店里查查看，如果你要找的那个人在镇上待过的话，那么很可能有人在旅店里见过他。', '到旅店去查一查关于模糊人影的线索。', '哦，没错，我记得这本书。这书的主人租了几天房间，每晚都趴在吧台上写东西。$B$B他离开镇子的时候显得很匆忙，嘀咕着说有什么东西正在追杀他……我最后一次见他的时候，他正在往镇子西边走，想要去找个新的藏身之地。$B$B往西边走的话，他能找到的第一个藏身之地就是乌鸦岭……', '血鸦旅店的生意已经大不如以前了，不过还是时常有旅人从这儿经过。$B$B如果你能描述一下你要找的那个人的特征，我可能会想起些什么来。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (267, '穴居人的威胁', '$C，你可能不知道矮人的领地正在面临着穴居人的威胁。铁炉堡的预备部队已经被派到联盟前线去了，只有很少一部分被留下来负责保卫这里的安全。我的部队负责看守这里的大门，提防随时可能到来的攻击，我们绝不能因为害怕而离开这里。$b$b不过我们得给山里的那些穴居人施加点压力。如果你能胜任这个工作，就去干掉这些穴居人，然后带8颗穴居人的石牙回来作为胜利的证明。', '给南部警戒塔的拉格弗斯上尉带去8颗穴居人的石牙。', '我很满意，$N。你保卫了我们矮人的领土，给我们帮了大忙。国王麦格尼·铜须陛下会为你骄傲的!', '你给我拿来8颗穴居人的石牙了吗?没有的话，就快去完成你的任务吧，$N。', '', '去丹莫罗找南部警戒塔的拉格弗斯上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (268, '回复斯温', '你找到的那本书……我还没有写完。我从斯文的农场里逃走的时候，不得不把书留在那儿……$B$B拿着这个，把这本完整的日记带给斯温。这一本对在他的农场上所发生的事情描述得更完整。$B$B这几个星期以来，我一直把这本日记放在身边，不过如果把它交出来之后我就不用面对斯温和他的愤怒的话，我宁愿把这东西交给他。', '把基特斯的日记交给斯温。', '这本日记解开了许多谜团，也让我走上和黑骑兵斗争的道路!我在夜色镇上见过这些骑兵，还看见他们和荒弃鬼屋里的巫师摩本特.费尔说话。', '你发现那个模糊的人影是谁了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (269, '寻求指引', '到暴风城去找光明大教堂的主教法席恩，把基特斯的日记给他看一看，告诉他你决心要和摩本特·费尔进行面对面的较量。$B$B虽然暴风城抛弃了夜色镇，但是法席恩主教是个善良而又睿智的人，也许他能给你一些帮助。$B$B你的使命非常危险，不过请动作快点，$N。笼罩夜色镇的黑暗力量无时无刻不在变得更加强大。', '把基特斯的日记交给暴风城的主教法席恩。', '<在主教阅读了日记并聆听了你的来意之后…>$B$B又一股邪恶势力在危机四伏的暮色森林立足了。感谢圣光赐予我们一位像你这样的英雄。$B$B对于将要面对的挑战，你必须做好充分的准备……摩本特.费尔这个死灵法师有着超强的实力，他能够施法使自己免受物理攻击。如果你想要打败他的话，就必须要找到能够打破这种防护的东西。', '休息一会儿吧，$g兄弟:姐妹;。我看得出你走了很远的路，身上还承担着重任。你能告诉我是什么样的阴影笼罩着你吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (271, '维林的报复', '你没被达瑞尔气得昏头昏脑吧？虽然我不愿意承认，但达瑞尔还是有点能耐的。$b$b一年前，整个旅行者营地里的猎人都在捕猎一只巨熊，不过没有一个人能解决掉它。后来，达瑞尔也去试了试，结果他的脸上就留下一道了丑陋的伤疤。$b$b如果你能杀了那只熊，就算是达瑞尔也会哑口无言的。$b$b那只名叫奥尔苏迪的熊就住在塞尔萨玛附近的山上。', '杀掉奥尔苏迪，把它的首级带给旅行者营地里的达瑞尔。', '呃……这是什么?看起来是一只熊头。$B$B<他下意识地用手指摸了摸脸上的伤疤>$B$B好吧，你能杀了这只熊是挺有意思的，但它应该不是以前那只熊吧……$B$B<他的声音渐渐变小，并且有些发颤>$B$B啊，把这个东西拿走，快拿走!把这个恐怖的东西拿走!$B', '啊，$N!这么快就回来了?你一定又去打猎了?遇到挫折也别担心，从长远来看，挫折可以让你变得更加成熟!$B$B(反正你已经够糟的了……)', '', '去洛克莫丹找旅行者营地的年轻的达瑞尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (272, '海狮试炼', '第二个试炼是要寻找组成海狮坠饰的两个部分。其中的一半蕴含着海狮的敏捷天性，另一半蕴含着海狮那令人难以置信的耐力。德鲁伊汲取这两种特性，将它们运用到自己的水栖形态中。$B$B与月光林地中的居民谈一谈，找到这两个部分，并将它们合并起来。最后把合并好的坠饰交给德迪利特·星焰。', '寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。$B$B在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。$B$B将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。', '你完成了海狮的试炼，$N，恭禧你。$B$B搜寻坠饰的每项任务都显示出，敏捷和耐力的协调一致性在水底下非常必要的。两者不能独存，而如果你不利用海狮的形态，那么这两者均无法实现。$B$B好好记着这些内容，一旦你学会了水栖形态，就好好的重用他吧。', '你带来合并好的坠饰了吗，$N?如果你在寻找它们时遇到了麻烦，可以试着跟这里的居民交谈以获取资讯。这不仅能帮助你找到坠饰，还能帮助你探索这片神圣的土地。', '', '去月光林地找永夜港的德迪利特·星焰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (274, '水坝危机', '这不是一般的炸药粉末。看看这些银色的小晶体。还有这股特别的味道！不用说这就是爆盐粉末了！爆盐本身没什么危害，不过一旦它沾上水，那威力，啧啧！足够把整个铁炉堡给炸上天！$b$b要想阻止这种东西爆炸就需要四种东西：潜伏者的毒液，莫格罗什水晶，一滴鳄鱼的眼泪和一些拆弹胶质。现在你得赶紧把我的话告诉辛德维尔，否则就来不及了！', '阿什兰·暗石要你回去见洛克莫丹的主工程师辛德维尔七世，把有关这种炸药的新发现告诉他。', '拆弹胶质?爆盐炸弹?我的天啊!', '阿胥兰说什么了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (275, '大地上的脓疱', '我不知道是怎么回事，但是堕落正在湿地上蔓延。沼泽爬行者出现了，他们就像是腐烂而危险的脓疱。要制止这些脓疱，就必须把他们驱散开，把它们赶回沼泽。$B$B这些沼泽爬行者一般都在湿地的水道里活动。', '杀死8只沼泽爬行者，然后向湿地的绿色守卫者雷希耶尔复命。', '在你的努力下，这片土地恢复了往日的平静，请拿着这个，这是我对你的奖励。', '湿地依然在哭泣，沼地蠕行者依然在肆意横行。快去完成任务吧，$C。', '', '去湿地找绿带草地的绿色守卫者雷希耶尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (276, '践踏之爪', '藓皮豺狼人在湿地平静地生活了许多年，但如今他们的数量却膨胀了不少。他们的脚正践踏着沼泽地中的灌木与花朵，他们污浊的斧子也砍伐了太多的树木。$B$B他们已经令这里的自然失去了平衡。为了湿地的安宁，必须削减这些豺狼人的数量。$B$B去杀死15名藓皮豺狼人和10名混血藓皮豺狼人，他们就在南边的奥加兹大门附近活动。完成任务之后再回来向我复命。', '杀死15名藓皮豺狼人和10名混血藓皮豺狼人，然后向湿地的绿色守卫者雷希耶尔复命。', '通过削减豺狼人的数量，你有效地维持了湿地的自然平衡。尽管我的信仰曾经被你们的族人指责，但我们的关系似乎正在缓和。', '你还有重任在身，年轻的$C。', '', '去湿地找绿带草地的绿色守卫者雷希耶尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (277, '火焰管制', '藓皮豺狼人们正在大量地砍伐湿地的树木，用树干和树枝当柴火来烧。我不能再容忍这样的行为了！$B$B把藓皮豺狼人生火用的打火石都给我抢过来。除了年幼的藓皮豺狼人和混血藓皮豺狼人以外，其它所有的藓皮豺狼人身上都会带着打火石。', '给绿色守卫者雷希耶尔带回9块粗制打火石。', '……谢谢。我会马上把这些打火石都给碾碎，然后都扔进海里去，让它们永远无法再被用来焚烧森林。', '你把那些豺狼人的生火工具都夺过来了吗?', '', '去湿地找绿带草地的绿色守卫者雷希耶尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (278, '水坝危机', '你必须立刻去收集拆弹用的原料，$N。潜伏者的毒液在洛克莫丹的蜘蛛身上可以找到，鳄鱼的眼泪在洛克湖一带的鳄鱼身上也有。不过莫格罗什水晶很难找到。东北边矿井里的食人魔开采这种水晶，不过即使在那里，莫格罗什水晶也不常见。$b$b我们必须要作好准备才能粉碎黑铁矮人的计划！你找齐了这些材料之后就立刻回来找我，我会把它们做成拆弹剂。', '主工程师辛德维尔七世要你收集一份潜伏者的毒液，一块莫格罗什水晶和一滴鳄鱼的眼泪。', '太及时了，$N!', '你找到我们需要的东西了吗?我们必须争分夺秒!', '', '去洛克莫丹找巨石水坝的主工程师辛德维尔七世。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (279, '海中的鱼人', '可恶的鱼人正在从深海里源源不断地爬出来，它们沿着海岸线创建自己的村庄和定居点。这些家伙给我们的渔民和商人带来了极大的困扰，我们必须要阻止这种行为。$B$B它们当中有一个叫高布勒尔的头目最近一直带着一群蓝腮鱼人埋伏在道路旁，抢劫过往的商旅，得手之后又马上撤回它们的村子。现在我们的通商道路非常危险，所以我们想要通过悬赏来解决这个问题。$B$B高布勒尔和它的跟班们就躲在北边的河口附近。找到它，把它干掉，然后把它的徽记给我带回来。', '杀掉12个蓝腮鱼人。$B$B杀掉高布勒尔并砍下它的头。$B$B将高布勒尔的徽记交给米奈希尔港的卡尔·波兰。', '啊，干得好，$N。$B$B请收下由商会提供的这份奖金，以作为你成功完成任务的酬劳。', '高布勒尔和它的鱼人爪牙们不死，我们的商人就得不到安宁。', '', '去湿地找米奈希尔港的卡尔·波兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (280, '水坝危机', '今天早些时候我发现有一些黑铁矮人背着一只大木桶向水坝游去，糟糕的是那一带没有巡山人可以拦住他们！我怀疑他们已经把爆盐炸药放到了水坝下面，随时都有可能爆炸！我马上就把这些成分混合在一起制成拆弹剂。$b$b完成了！现在我要你把这个混合剂拿去，和木桶里的炸药搅拌在一起！快一点！我们没时间了！', '主工程师辛德维尔七世要你游到水坝底部，找到装着炸药的木桶，然后把拆弹剂放进去，阻止将要发生的爆炸。', '你把拆弹剂放进去之后，桶里发出了嘶嘶的声音。', '你慢慢地拧开了木桶的盖子。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (282, '森内尔的观察站', '我原打算让我的学徒帮我把报告带给我的兄弟森内尔。但是，你看他那德性……我想如果有一个更可靠的人替我去送的话就更好了。如果你不介意的话，可以去一趟吗？$b$b嗯……你要穿越隧道，一路走到卡拉诺斯。$b$b在穿越隧道前，别忘了去和巡山人萨鲁斯聊聊，那里的穴居人简直成灾了。$b$b顺着这条路回到安威玛尔，然后向东就能到隧道了，萨鲁斯就在附近。', '和巡山人萨鲁斯谈一谈。', '嗯，好吧，如果白须要你去丹莫洛办急事，我也不能阻拦你的，对吧?$B$B不过至少先让我给你些忠告和指点吧。', '欢迎你，$N，要多加小心，通往丹莫洛的隧道里满是穴居人，你八成得杀出条血路才能过去。$B$B如果你在丹莫洛没有什么紧急的事情要办的话，我就得请你待在安威玛，直到隧道比较安全为止。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (286, '归还雕像', '你把这个木桶从垃圾里拖了出来，刚一打开它，一尊精心包裹在稻草中的银制小雕像就掉了出来。这是一个头发很长的年轻圣骑士高举战锤的样子。$B$B这一定就是米奈希尔雕像了！你必须马上把它交还给米奈希尔港的卡尔·波兰。', '将米奈希尔雕像还给湿地米奈希尔港的卡尔·波兰。', '盲眼公主号的船长听到这件重要的货物失而复得的消息一定会非常高兴的!这是你的劳动所得，请收下吧。$B$B有你这样值得信赖的$r为我们排难解忧可真好，尤其是在遇到这种麻烦事的时候。', '你拿到雕像了没有?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (287, '霜鬃巨魔要塞', '我快要来不及提交报告了，你能帮我一下吗，$n？我只想知道这些巨魔躲在什么地方，不过我看见这么多的巨魔就怕得不敢进去了。$b$b你要做的是……进到山洞里，在里面到处走走，干掉一些巨魔，然后再回来。$b$b顺着向北的路离开卡拉诺斯，当你走到一座桥前的时候，再沿着冰冻的河流向西一直走到涌冰湖。你会发现烈酒村就在湖的西岸，而巨魔要塞就在村庄的西南边。', '侦查霜鬃巨魔要塞，替卡拉诺斯的森内尔·白须杀掉5个霜鬃猎头者。', '啊，$N!我就知道你肯定找得到那个地方，我的方向说明是很清晰的，这你是知道的……$B$B让我完成我的报告吧。$B$B<他拿出了一叠纸，立刻在上面写起了报告。>$B$B给你!怎么样，哈哈，我想这一定很有趣，$N，你不会介意再帮我一个忙吧?', '你找不到要塞?我的方位说明可是非常清晰的!我们没多少时间了，你必须快点!找不到那个洞穴就别回来。', '对霜鬃巨魔要塞进行详细的侦查', '去丹莫罗找闪光岭的森内尔·白须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (288, '第三舰队', '我曾经是浪花女神号上的大副——浪花女神是库尔提拉斯第三舰队的主力战舰。这是一支多灾多难的舰队，说它多灾多难是因为……它在最后一次出航中遇到了红龙的袭击。这些龙是被兽人控制的！$B$B红龙喷出的火焰对我们的战舰来说简直是毁灭性的……我们的舰队在这片海域被烧得一干二净，全军复没。我是那次灾难的唯一幸存者……$B$B……哦，我的头疼得像鼓槌在敲！我需要一些让我头脑清醒的东西，好让我继续讲述我的故事。', '为大副菲兹莫斯买一份壶装蜜酒。', '啊!那正是我要的东西，我干裂的唇舌终于好受一些了。谢谢你，伙计!', '哦，我非常口渴!你不愿意为我这样一个穷困潦倒的可怜虫买点喝的吗?', '', '去湿地找米奈希尔港的大副菲兹莫斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (289, '被诅咒的船员', '<缓过气来的菲兹莫斯继续讲述他的故事……>$B$B我是这支倒霉的库尔提拉斯第三舰队中唯一的幸存者，整支舰队都在北方的海岸附近复灭了。不过，虽然我是舰队中唯一活着的人，却不是唯一一个依然在这里出现的人！因为，在一条已经沉没的船里，藏有巨大的、可怕的宝藏，它所拥有的可怕魔力将我的弟兄们的灵魂束缚在被海水侵蚀的船体里。$B$B如果你能超度我的那些被诅咒的弟兄们，也许你就能破除那个诅咒。', '杀死13个被诅咒的水手、5个被诅咒的水兵和大副斯涅利格。把斯涅利格的鼻烟盒交给米奈希尔的大副菲兹莫斯。', '感谢你，$N。我那些被诅咒的弟兄们同样感谢你。', '在梦里，我时常听见弟兄们悲惨的呻吟!求求你，好心的$g先生:女士;，帮助他们从囚禁和痛苦中解脱出来，平息他们的哭嚎吧。', '', '去湿地找米奈希尔港的大副菲兹莫斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (290, '解除诅咒', '为了破除诅咒，解救我所有的兄弟，就必须要把装在我船上的那个鬼东西拿回来进行净化！我不知道它是什么，但我知道它被存放在船上的保险箱里，而保险箱的钥匙一向是由哈林多尔船长保管的。$B$B我的老船长仍时常出现我的梦里，在我的那艘已毁灭了的无畏号的甲板上走来走去……去找到钥匙，用它打开无畏号上的保险箱。$B$B然后，在你获得那件被诅咒的东西以后，把它交给镇上的牧师，戈罗林·钢眉。', '从哈林多尔船长那里拿到无畏号的保险箱钥匙。$B$B用钥匙打开无畏号上的保险箱。', '钥匙已经生锈了，不过它与锁孔吻合得非常好。', '这个箱子被牢牢地锁着。', '', '去湿地找无畏号的保险箱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (291, '森内尔的报告', '好极了！把我的报告交给参议员巴林·红石。他是个酸溜溜的家伙，你可别在意。他在铁炉堡，麦格尼陛下的宫殿里。$b$b你不知道去铁炉堡的路？顺着这条路向北走出卡拉诺斯，穿过一座桥，然后沿着路向东走——在路边山上应该有个很大的路标。$b$b顺便说一句，你最好不要提及你是如何帮助我的，不要让他们以为我在这里没有好好工作，好吗？', '把森内尔的报告交给铁炉堡的参议员巴林·红石。', '<他很快地看了一下这份报告。>$B$B国王授权的?!麦格尼已经完全丧失判断力了!那个该死的白须……他控制了整个事态，难道不是吗?参议院一定会对此很恼怒的，而且不是一点点!$B$B怎么，你还在这里?快滚，不然我要喊卫兵了!', '嗯……看来我的卫兵都是些饭桶，什么人都放了进来。好吧，有什么事?快点说吧。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (292, '帕雷斯之眼', '打开箱子之后，你看到了一颗发黑的宝珠，它还在闪烁着可怕的光芒。这就是菲兹莫斯所说的宝藏：一颗被诅咒的帕雷斯之眼。$B$B把被诅咒的帕雷斯之眼交给住在米奈希尔港的矮人牧师戈罗林·钢眉，请他驱除附着在它上面的诅咒。', '把被诅咒的帕雷斯之眼交给湿地米奈希尔港的戈罗林·钢眉。', '帕雷斯之眼?不可思议!嗯……这件东西有点问题。你是从那堆船骸中找到的?哦，那就对了!不过……我不知道第三舰队居然有这样一件东西……$B$B难怪菲兹莫斯如此惊慌失措。被诅咒的帕雷斯之眼可不是一件让人高兴的东西。', '那个酒鬼菲兹莫斯派你来找我?好吧，你告诉他我可没有多馀的麦芽酒。他最好去向别的人乞讨吧!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (293, '净化帕雷斯之眼', '我无法驱散帕雷斯之眼上的诅咒。它是由人类牧师手工制造的，所以你最好去暴风城寻找帮助。去和大主教本尼迪塔斯谈谈吧，他是暴风城光明大教堂的领导者，他能帮你解决问题。$B$B我希望如此。', '把被诅咒的帕雷斯之眼交给大主教本尼迪塔斯，他就在暴风城的光明大教堂里。', '帕雷斯之眼。不过这一只眼睛看见过太多的哀伤……它一定目睹过一场极其可怕的悲剧。$B$B让我来净化它，制造帕雷斯之眼是为了圣光服务的，如果它受污染成这个样子，那么它的魔力就会变得非常危险。', '你手上拿的那个球是什么?它看起来……似乎被污染了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (294, '奥莫尔的复仇', '当前我们所面临的形势十分严峻，这已经是众所周知的事了。我们刚挖出这些骨头，它们就招来了一大群迅猛龙。这些凶残的野兽杀光了我的弟兄们，并把我、麦琳和可怜的勘察员困在了这上面。$b$b帮我把湿地里的这些迅猛龙都给杀光，$N。杂斑迅猛龙和杂斑尖啸龙就在山崖的西边，要是你有能力对付它们的话，每种都给我杀上十只。$b$b这只不过是我对它们的复仇计划的开始而已！', '维尔加挖掘场的奥莫尔·铁衣要求你杀死10只杂斑迅猛龙和10只杂斑尖啸龙。', '我知道替别人当杀手算是件肮脏的营生，但你干得确实不错，$N。要不是我必须在这里陪着勘察员和麦琳，我一定会和你一起去悬崖那边大开杀戒的!', '杀死10只杂斑迅猛龙和10只杂斑尖啸龙，$N。我那些弟兄们的血债一定要用血来偿还。', '', '去湿地找维尔加挖掘场的奥莫尔·铁衣。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (295, '奥莫尔的复仇', '现在是时候让这些该死的迅猛龙为它们的嗜血而后悔了。在悬崖下面还有一些杂斑刺喉龙和杂斑锯齿龙，每种都给我杀10只，它们要为自己的所作所为付出代价！', '奥莫尔·铁衣要求你杀死10只杂斑刺喉龙和10只杂斑锯齿龙，然后回到维尔加挖掘场向他复命。', '就猎杀迅猛龙这件工作来说，你做得实在是太棒了，$N!', '我一定要让这些杂斑刺喉龙和杂斑锯齿龙为它们以前所做过的一切付出代价。每种你都杀死了10只了吗?', '', '去湿地找维尔加挖掘场的奥莫尔·铁衣。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (296, '奥莫尔的复仇', '在你下到悬崖底部的时候，我碰巧发现了有一只很特别的迅猛龙在那边站着休息。它比一般的迅猛龙的体形要大得多，看上去也特别凶猛。我敢打赌它就是那群迅猛龙的首领，就是它带着手下来这里毁了整个挖掘场。$b$b我现在交给你最后一个任务，$N。以正义的名义，审判萨尔图斯！当然，考虑到它所犯下的重罪，它唯一能得到的判决就是死刑！把它的一只爪子给我带回来作为它已死的证据。', '维尔加挖掘场的奥莫尔·铁衣要求你杀死萨尔图斯，并在任务完成之后带着它的一只爪子向他复命。', '太感谢你了，$N。我们不会忘记你所做出的贡献。许多辛勤工作的矮人无辜地死在了这座挖掘场里。你对那些邪恶生物的无情打击将会使它们不敢再如此倡狂地骚扰麦格尼陛下的臣民。', '萨尔图斯已经死了吗?你是否为逝者报仇雪恨了?', '', '去湿地找维尔加挖掘场的奥莫尔·铁衣。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (297, '收集石像', '不久前，就在那些穴居人像雨后的蜗牛一样冒出来之前，我们发现了一大批奇特的小石像。但是还等我们开始着手研究它们，穴居人就把我们从废墟里赶了出来！这些石像有种奇特的效力，它可以让那些穴居人变得更加疯狂！$B$B给我拿几个石像回来——我想研究研究，所以你得把它们从穴居人手上给我抢过来！你可以在挖掘场里到处都是的穴居人身上拿到这些石像。', '收集8个小石像，把它们交给麦格玛尔·落斧。', '你拿到了!干得好，$N!$B$B这个任务对你来说似乎并不困难，周围这么多疯狂的穴居人都没能把你怎么样。我会关注你的……你看起来挺有前途的。', '你拿到那些塑像了吗?我们得研究它们，并把结果报告给铁炉堡!', '', '去洛克莫丹找铁环挖掘场的麦格玛尔·落斧。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (298, '挖掘进度报告', '我这里有一份报告要赶快送到塞尔萨玛去——这是一份挖掘进度报告，还有一份再次重申我们需要更多的火药粉的报告！你把它带给吉恩·角盔，他是我们在塞尔萨玛的联系人。$B$B这个任务没什么麻烦的，但你一定要完成它。', '把铁环挖掘场的进度报告带给塞尔萨玛的吉恩·角盔。', '哦!铁环挖掘场也遇到穴居人的麻烦了。不知道他要的炸药粉是用来帮助挖掘还是用来对付穴居人的……$B$B反正用在哪儿都值!$B$B奇怪的是，我几个星期前就给他送去足够的炸药粉了，难道他没收到吗……', '哦，挖掘场送来的进度报告?很好!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (299, '发现历史', '在迅猛龙大举入侵之前，我找到了一块名叫戈奥兹之石的巨大石碑。我翻译好的文字被分成了四部分，散落在挖掘场中的四个不同的地方。这些文字描述的是一个“神圣的计划”和一个“注定的命运”。$b$b我们应该马上把它们都收集起来，而不是继续在这里浪费时间。但是我已经很老了，恐怕没办法再杀出去跟那些凶猛的野兽作战了。但是你不同，你年轻而强壮。$b$b到挖掘场里去搜索这四片失落的石板：阿度斯石板、莫德尔石板、高尔姆石板和奈尔鲁石板。它们应该被藏在某些古董器物里，另外你也得留意土壤松动的地方。把它们拿回来给我，这样我才能揭开这个秘密！', '勘察员维尔加要求你在挖掘场中搜索4块石板的碎片，它们是阿度斯碎片、莫德尔碎片、高尔姆碎片和奈尔鲁碎片。', '啊，戈奥兹之石终于完成了!干得太好啦，$N。现在我终于可以继续翻译这份泰坦留下的手稿了。我可以从里面解读出许多新的内容!嗯……这里写着，“上古诸神…被禁锢于大地下的深渊中。”这一定是某段史诗的开头部分。', '你找到那些石板碎片了吗，$N?它们是阿度斯碎片、莫德尔碎片、高尔姆碎片和奈尔鲁碎片……', '', '去湿地找维尔加挖掘场的勘察员维尔加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (301, '向铁炉堡报告', '我们必须得到上级的批准才能给铁环挖掘场送去更多的火药粉。把他的报告带到铁炉堡的探险者协会总部去，交给勘察员塔伯斯·雷矛。他可是个急性子的家伙，如果听说铁环挖掘场的进展如此缓慢，他一定会暴跳如雷的。$B$B你可以在探险者大厅里找到他。', '把铁环挖掘场的进度报告交给勘察员塔伯斯·雷矛。', '该死的家伙!几个星期前我给他送去了足够把塞尔萨玛炸上天的火药粉，这个报告里却连一个字都没提!$B$B那么……火药粉都上哪儿去了?!', '我们雷矛部族的人不喜欢被小事情烦扰，$C。我希望你带来的是值得我关注的消息。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (303, '黑铁战争', '战火席卷了整个世界。当许多精锐的矮人士兵们为了联盟而牺牲在前线时，我们自己的土地却沦为了这群邪恶的黑铁矮人觊觎的目标。他们已经攻陷了萨多尔大桥，丹莫德也岌岌可危。$b$b我们要你去聚集起一股力量，并将战线推回去。如果你能杀死十名黑铁矮人、五名黑铁隧道工、五名黑铁破坏者和五名黑铁爆破手的话，就能为我们组织反击争取到宝贵的时间。$b$b兵贵神速，快出发吧！', '丹莫德的莫特雷·加玛森要求你杀死10名黑铁矮人、5名黑铁隧道工、5名黑铁破坏者和5名黑铁爆破手。', '你出色地完成了任务，$C。你已经向麦格尼陛下证明了你的忠诚与勇敢，为此，我向你致敬!你对黑铁矮人进行了沉重的打击，如今我们终于有机会将他们彻底赶出我们的国土了……希望这群家伙不再耍什么花样……', '罗戈没能联络到更多的援军，但我们必须要保持对黑铁矮人营地的压力，$C。快去，为麦格尼陛下而战!', '', '去湿地找丹莫德的莫特雷·加玛森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (304, '艰巨的任务', '我手下的大部分士兵都在丹莫德的战役中死去了，我的亲兄弟也在萨多尔峡谷上的西桥被毁的时候不幸牺牲。唉，黑铁矮人真是个像恶魔一般邪恶的族群。根据罗戈收集到的情报，这群在湿地四处肆虐的暴徒的领袖是一个名叫巴尔加拉斯的术士。他是个十分胆小谨慎的家伙，在把手下的士兵送上战场执行命令的时候，他自己往往却躲藏在某个不为人知的地方，躲避着任何可能面临的危险。$b$b如果你能找到这个懦夫，杀了他，把他的耳环拿来给我，我会给你支付可观的酬劳的，$c。', '杀死邪恶的巴尔加拉斯，把他的耳环带给丹莫德外的布莱德·长须。', '邪恶的巴尔加拉斯终于死了。他的死无助于挽回那些死在他手中的无辜矮人们，但这至少能安抚那些幸存者们的灵魂。另外，巴尔加拉斯一死，那些苟延残喘的黑铁矮人喽罗们就好对付多了。现在，我们必须在他们找到一位新的领导者之前把他们扫荡干净。$B$B你干得非常出色，$C。', '你找到邪恶的巴尔加拉斯了吗，$C?他躲躲藏藏已经有一段日子了。', '', '去找湿地的布莱德·长须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (306, '寻找挖掘队', '这太恐怖啦！我们刚刚发现了一些十分稀有的古物，而且正在把这些巨大的骸骨挖掘出来，这个时候，可怕的事就发生了，在我们反应过来之前，多到数不清的杂斑迅猛龙冲进了挖掘场，咬死了许多人！$b$b勇敢非凡的奥莫尔救下了我和勘察员，并一直把我们护送到了一处藏身之所。现在我们被彻底困在这里了，逃也逃不出去，我们努力工作的成果也全毁了。$b$b给，把这封信带回去交给我亲爱的塔雷尔，我已经在信里把事情跟他解释清楚了。', '把麦琳的信件交给湿地米奈希尔港的塔雷尔·石纹复命。', '这真是太糟了!不过至少他们三个还活着。但是这种危险的情况什么时候才能结束啊?我真希望以后麦格尼陛下的臣民能不再被这种危险的事情所困扰了。', '你找到麦琳了吗?她有没有让你捎口信过来?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (307, '肮脏的爪子', '东边的银泉矿洞很久以前就枯竭了。矿工联盟把它改造成了储藏库，不过现在狗头人占据了那里，把他们肮脏的爪子放在了我们矮人制造的工具上！$B$B我们很快就能把这些害人虫赶走，但是矿工联盟要求我们在冲进去大开杀戒之前，先把洞里的矿工装备拿出来。这是个艰难的任务——你也许需要几个帮手。$B$B他们的装备就在矿工联盟的储物箱里，祝你好运。', '到银泉矿洞去收集4套矿工装备，然后向巡山人卡尔·雷矛复命。', '洞里是不是有很多狗头人?我真想快点收到把他们清除出矿坑的命令。一想到他们肮脏的爪子在我们的矿坑里抓来抓去，我就浑身不自在!', '你拿到矿工装备了吗，$N?', '', '去洛克莫丹找奥加兹岗哨的巡山人卡尔·雷矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (308, '加文的爱好', '', '', '这是给我的?你是个真正的英雄，$N!', '啊!这么多好酒!不过我必须严格遵守命令，谁也不许碰它们一下。要是我能喝一口雷霆麦芽酒该有多好啊……那样会让我变得更加聪明，不骗你!', '', '去找丹莫罗的加文·雷酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (310, '针锋相对', '我不得不承认，雷酒系列的那帮家伙酿酒水平还真不赖。但是他们应该知道他们的酒并不是世界上最好的！也许你能帮我让他们了解这一点……$B$B给，带上这桶热麦酒，想办法潜入卡拉诺斯的雷酒酿造厂的酒窖，把他们的雷霆啤酒和我们的换一下。然后，我们就等着看好戏吧，顾客们肯定会更喜欢我的酒！$B$B如果有人看着酒桶的话，你就得想办法转移他的视线……', '到卡拉诺斯的雷酒酿造厂酒窖里去，把一桶雷霆啤酒换成热麦酒。', '你迅速把马莱斯的热麦酒混入到一大堆装着雷霆啤酒的酒桶之中。', '从这桶酒的酿造日期来看，它马上就可以被开封了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (311, '向马莱斯回报', '把一桶马莱斯的热酒放进了卡拉诺斯酿酒间的地窖里之后，你取回一桶雷霆麦酒作为行动成功的证明。', '把雷霆麦酒交给烈酒村的马莱斯·麦酒。', '干得还不错，$N!你没有被那个看守发现吧?$B$B没关系―非常感谢，如果你想要畅饮好酒的话，别忘了来找我们!', '你把酒调换了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (312, '马克格拉恩的干肉', '我原本储备了一个月的干腌肉准备过冬，为了防止野熊把肉衔走，我把它们锁在了储藏柜里。但是在我外出打猎的时候，一个叫做冰须的野兽偷走了我的储藏柜！可笑的是那个蠢货撬不开这只用瑟银铸成的柜子。$B$B但是如果拿不回这些肉，我就会饿死的。你的身手看来不错，也许你能帮我取回储藏柜？你瞧我拖着这条废腿也没办法把那只柜子抢回来……', '从冰须的洞穴里拿回装有马克格拉恩的干肉的储藏柜。', '你真是个好心的$C，$N!多亏了你的勇敢无畏，不然我整个冬天就都要忍饥挨饿了。', '你找到我的储藏柜了吗，$N?', '', '去丹莫罗找烈酒村的图德拉·马克格拉恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (313, '灰色洞穴', '不是每个人都能驾驶攻城坦克的，你必须要有强壮的身体和钢铁般的神经……幸运的是，这两个条件我都有！你呢？你有足够的勇气吗？想不想证明给我看？$B$B啊……我想把我的“巨魔碾压者”号坦克改造得更舒适些，你去帮我在卡拉诺斯西边的灰色洞穴里弄一堆雪怪的鬃毛来吧，我要用那些鬃毛做一张大毯子来装饰我那“巨魔碾压者”的驾驶舱。', '收集8束雪怪的鬃毛，把它们交给驾驶员迪恩·石轮。', '啊，不错，这些鬃毛真棒!你显示出了非凡的勇气，我敢打赌，你将来一定能做出一番大事业来。', '嘿，$N。你去过灰色洞穴了吗?那些雪怪可是非常凶猛的。', '', '去丹莫罗找钢架补给站的驾驶员迪恩·石轮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (314, '保护牲畜', '午夜的时候，我们听到了吵闹的声音。今天早上我才发现羊圈里少了两只羊，那头名叫瓦加什的野兽袭击了我们的牲畜。由于国王麦格尼的军队大都在遥远的战场上与联盟其它的种族并肩作战，所以没有人能对付得了瓦加什。$b$b也许你有勇气找到这只猛兽并杀了它。把它的一颗牙齿交给我作为证明，我会奖赏你的。瓦加什就躲在这里的农场附近，小心点，它非常凶残。', '山羊农场的鲁德拉·冻石要你杀了瓦加什，并且把它的牙齿给她带回去。', '干得很好!维隆知道这样的好消息一定会很高兴的，能干掉瓦加什真是很不容易。我想，总有一天，你会和麦格尼陛下的战士们在联盟前线并肩作战。', '瓦加什仍然让这里的羊群感到恐惧!帮我们杀了这个卑鄙的野兽吧!', '', '去找丹莫罗的鲁德拉·冻石。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (315, '完美烈酒', '我正在寻求可以酿制出完美的酒的方法。我知道我能酿造出来，我缺的只是一份正确的酿酒配方……$B$B霜鬃巨魔在东边的山坡上种植了一种叫做微光草的植物，他们通常在奇怪的部族仪式上用到它。我们矮人还没有发现这种草有什么用途，不过它的口味非常特别……我要把这种植物用在我的酒里！$B$B从霜鬃先知那里给我弄一些微光草来，或者你也可以从巨魔用来装微光草的篮子里偷一些。', '收集6束微光草，把它们交给烈酒村的雷杰德·麦酒。', '太好了!让我赶快把它发酵一下，我一定可以酿出一种口味独特的酒来……', '你弄到微光草了吗?我有大量的酒需要酿制，要赶快把这种植物也加进去。', '', '去丹莫罗找寒风峡谷的雷杰德·麦酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (317, '贝尔丁的补给', '我正在准备为攻城坦克旅执行一项任务。这次任务会持续很长时间，所以我得预先收集能够维持一个月的物资。贝尔丁正忙着\r\n修理我的坦克，你能帮我去弄一些东西来吗？$B$B我需要一些毛皮来做床垫，还要一些野猪肉作为食品储备。猪肉当然是从野猪身上割下来的，最好的毛皮是熊皮……在灰色洞穴南部的雪地上到处都是这两种动物的踪迹。', '收集4大块野猪肉和2张厚熊皮，把它们交给钢架补给站的驾驶员贝隆·风箱。', '以麦格尼胡须的名义，你肯定猎杀了很多动物才收集到这些东西!谢谢你，$N。', '准备工作进展顺利，你的捕猎行动进展如何呢?', '', '去丹莫罗找冻土岭的驾驶员贝隆·风箱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (319, '艾沃沙酒', '我有一桶酿制好的艾沃沙酒，不过……你能帮我个忙吗？烈酒村急需人手去对付在村子附近溜达的野兽。有时它们离我们非常近，那真是太危险了。$B$B我们并不害怕这些熊啊，豹啊，野猪啊——任何一个有自尊的矮人都不会害怕——不过，如果你能替我把它们搞定的话，我就能腾出更多的时间来酿酒了。', '杀掉6头冰爪熊、8只老峭壁野猪和8只雪豹，然后回到烈酒村的雷杰德·麦酒那里。', '谢谢你，$N。我们再也不用听着野兽的咆哮声干活，这真是太好了。', '你干掉那些野兽了吗?', '', '去丹莫罗找寒风峡谷的雷杰德·麦酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (320, '艾沃沙酒', '这是你要的艾沃沙酒，$N。再次感谢你给予我们的帮助。', '把这桶艾沃沙酒交给钢架补给站的驾驶员贝隆·风箱。', '嗯，很好。我想马上打开一瓶来好好品尝一下……', '你拿到酒了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (322, '格瑞曼德·艾尔默', '暴风城矮人区有一个名叫格瑞曼德·艾尔默的矮人武器匠会用这种光铸铁来打造武器。$B$B我已经把你找到的这些铁锭用木箱装好了。把这个箱子交给格瑞曼德，再把你的事情告诉他。我敢打赌他一定会义愤填膺地马上着手为你打造武器的，嘿嘿，那肯定是把就连摩本特·费尔看到了也会心惊胆颤的武器！', '将这箱光铸铁锭交给格瑞曼德·艾尔默。', '这么说，你的来头可还真不小呀。嗯……这竟然是光铸铁!我可真是好多年都没用这种金属打造过东西了。能再用它打造点什么可真是荣幸啊。你把那个什么死灵法师给干掉了以后一定要回来把过程都讲给我听。$B$B不过，首先，我们先来打造这把用来对付摩本特.费尔的武器……', '我能帮你什么忙吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (323, '证明你的实力', '摩本特·费尔是个亡灵巫师，也是黑暗强盗的帮凶。我希望你能去除掉摩本特·费尔，不过在了解你真正的实力之前，我还不能贸然拿你的生命开玩笑。$B$B你已经证明了你的勇气，不过如果你想要面对面地和这个巫师作战，首先得证明你能应付得了他的爪牙。', '杀掉15个骷髅袭击者、3个骷髅医师和3个骷髅看守，然后回来见斯温。', '看来我不应该怀疑你的实力，$N。你的决心也许能帮我们最终消灭摩本特.费尔!', '勇敢一些，$N。不要绝望，因为你的绝望就是敌人最强的武器。', '', '去暮色森林找寂静河岸的斯温·约根。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (324, '丢失的铁锭', '你好不容易把那块光铸铁锭从泡在水里的箱子中拿了出来，显然，是鱼人偷走了其馀的铁锭。猎杀飞翔鱼鹰号残骸周围的鱼人，拿到它们身上带着的光铸铁锭。', '收集5块光铸铁锭，把它们交给湿地的戈罗林·钢眉。', '啊，找全了!我们现在就来用这些上好的光铸铁打造些有用的东西吧，怎么样?', '你找到足够的光铸铁锭了吗?', '', '去湿地找米奈希尔港的戈罗林·钢眉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (325, '整装待发', '你已经准备好了吗，$N？祝你好运！我期待着你凯旋归来！', '现在你已经得到了强大的武器，去向暮色森林的斯温复命吧。', '你去得有点太久了，但我在你的眼中看见了从未有过的斗志。$B$B看来你已经准备好了，摩本特.费尔一定会被彻底消灭的。', '你好，$N。你并没有离开多久，但我却从你的眼中看到了以前没有看到过的火焰。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (328, '隐藏的钥匙', '尽管在这些档案文件里都没有提到列兵索尔森，但你发现在赫罗德的一本帐薄后面绑着一只小小的黄铜钥匙。$B$B你还在研究他的其它笔记时发现了其中有一小部分提到，在一个“安全的保险箱”中装有大量的文件。这个保险箱应该在库尔森营地后山的某处洞穴之中，他们管那里叫“储藏室”。$B$B如果你能找到这个保险箱并用这把黄铜钥匙打开它的话，或许里面的文件有助于找到导致索尔森身份暴露的内鬼。', '使用黄铜钥匙打开书呆子赫罗德的保险箱。', '打开了这个保险箱之后，你发现这里面装着赫洛德的钱与其它的一些贵重物品。', '保险箱是用青铜制造的，非常坚固，而且非常重。', '', '去找荆棘谷书呆子赫罗德的保险箱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (329, '找出内鬼！', '在箱子里的这些贵重物品之中，还有一张满是灰尘且写得十分潦草的便笺。尽管几乎已经没法辨认了，但你能看出来这便笺上面似乎描述了列兵索尔森所走的路线。这应该是他的巡逻路线，以及反抗军方面与他接头的人员与时间。签名只有一个字母：M。$B$B毫无疑问，这应该是索尔森身边的人写下的便笺，而且这个人就是反抗军营地中的卧底。', '将沾泥的便笺交给叛军营地里的多伦上尉。', '谢谢你，$N。这条便笺显然是我们揪出这该死的内鬼的重要线索。', '你发现还有谁知道托尔森的秘密了吗?谁是我们当中的内鬼?', '', '去荆棘谷找反抗军营地的多伦上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (332, '酒店的广告', '无论你跟任何人谈起酒，大家都会告诉你加林纳家卖的酒是全暴风城最好的。而且那里离我们这儿并不远，就在贸易区中，运河的边上。$B$B给，拿着这张酒票。把这个拿到店里去，交给我的姐姐苏泽塔，她会送你一瓶我们酿造的最有名的黑葡萄酒。你绝对不会后悔的！', '到加林纳酒店去, 将酒票交给苏泽塔·加林纳以换一瓶免费的酒。', '啊，你见过雷纳多?来，给你，$g先生:女士;，这是我们特制的黑葡萄酒。在艾泽拉斯这可是独此一家别无分店哦!', '你好，欢迎光临，$g先生:小姐;。要品尝一下我们的好酒吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (333, '哈兰需要供货', '我们过几天肯定会有大单的生意。现在似乎每个人都在购买盔甲和结实的衣服，好象他们都以为明天就会变得天寒地冻一样……$B$B但那是以后的事了。我现在最担心的是我已经卖完了全部库存的针织布，需要一次大批量的供货。$B$B如果你能把我的这个要求带给运河裁缝店的雷玛·施涅德的话，我会非常感谢你的。', '找到运河裁缝店，并将哈兰·巴格雷的布料订单带给雷玛·施涅德。', '据说哈兰最近的生意很旺啊。这是个好消息，但我想知道人们为什么会那么热衷于购买盔甲。我没听说过最近要打仗呀……难道贵族们对我们隐瞒了些什么?$B$B不管了，谢谢你把他的信带来，这是给你的酬劳，还有，我马上就安排伙计给哈兰送货过去。', '你带来了巴格雷先生的信?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (334, '萨尔曼的针线包', '我的儿子萨尔曼在法师区的拉尔森服装店里当学徒。他今天早上走得太着急了，忘了他的剪子和针线。我知道你这样伟大的$C一般都会有些重要的事要做，可要是没了工具的话，萨尔曼可没办法做他的工作呀！$B$B拜托了，$N。你能帮我把他的针线包拿去给他吗？拉尔森服装店是法师区里的两家裁缝店之一，在比较靠里面的地方，也就是靠近法师塔的地方。', '到暴风城法师区的拉尔森服装店去，将针线包带给萨尔曼·斯涅德。', '哦，天啊!我还以为没带针线包就可以偷懒不干活了呢。现在，恐怕我得帮拉尔森缝布去了……$B$B唉，算了，我想我总有一天会感到干这活儿有趣的……', '要买衣服吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (335, '名酿', '维沙克公爵最近正在贵族议会中兴风作浪，他似乎知道一些我们的事情，而且还游说其它议员们，要他们通过他提出的对这里进行一次全面调查的提案。我有一个计划，能让维沙克迷上些别的什么东西……但我需要你的帮助。$b$b在夜色镇郊区的斯塔文的花园里生长着一种名叫蒂罗亚之泪的白色小花，去给我弄一朵来。另外我还需要一些麝鼠根，那种东西只生长在湿地，就在巨石水坝下的瀑布底部。', '黑爪加尔德斯要求你从夜色镇给他摘1朵蒂罗亚之泪，再从湿地给他采一块麝鼠根。', '好极了!这些真的是很好的样品!', '维沙克马上就能说服足够多的议员支持他了，那样我们将会非常被动。你找到蒂罗亚之泪和麝鼠根了吗?', '', '去找暴风城的黑爪加尔德斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (336, '名酿', '维沙克公爵与所有人一样有自己的弱点，他对酒的爱好胜过一切。更可恶的是，这个蠢货整天想着把我们这个小小的酒馆给弄关门了，而他自己却呆在楼上整夜整夜地喝个不停，至于那些像滚雪球一样越攒越多的账单，他是肯定不会付的。好吧，让我们看看维沙克会有多喜欢我们给他准备的这种特制佳酿：黑爪烈酒。这一定会很有意思的，$n。$b$b把这个带给他，看看他的反应如何，我觉得这傻瓜可能会在祈愿厅里当场开喝。', '将黑爪烈酒带给祈愿厅里的维沙克公爵。', '啊，多谢你给我带来这么好的酒!这是你的小费。现在你可以离开了，让我一个人喝个痛快!', '你没看见我正忙着吗?你听不懂我说的话吗?我对王国的未来十分重要!$B$B噢……你说你要找我干什么来着?为什么这玩意看起来像是一种很提神的饮料……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (337, '一本破旧的历史书', '这本书的封面已经有被刮坏的痕迹，还沾上了泥污，但是书脊上“暴风城的历史”的字样仍然清晰可见。打开书的第一页，可以看到上面盖着暴风城图书馆的印章。$B$B看起来似乎有人从图书馆借出了这本书却从来没有归还……', '把《暴风城的历史》这本书还给暴风城图书馆。', '天哪!早在暴风城重建之前，这本书就丢失了。现在它终于被找回来了，虽然看起来这本书已经很破旧，不过我还是很荣幸能把它放入我们的珍贵藏书中。$g先生:女士;，请收下这个作为你归还这本书的报酬。', '哦!你拿的那本是什么书啊?能让我看看吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (338, '荆棘谷的青山', '如果奈辛瓦里知道了这一切，他一定会很生气的！$b$b出于对我的信任，他让我来校对他的小说《荆棘谷的青山》的手稿。一开始事情进行得非常顺利，但昨天一阵大风吹过了营地，结果把手稿吹得满天都是！$b$b我已经很努力地找回了大部分的书页，但还是有几页被吹进了丛林中。请你帮我把这四章里的掉落的那几页书都给收集起来吧。$b$b等这四章手稿都搜集齐了以后，把它们还给我。', '收集《荆棘谷的青山》的手稿中丢失的页面。在集齐四章书之后，将它们还给巴尼尔·石罐。', '你解决了我的大问题，$N!我真是对你感激不尽。我想我们不久之后就能在全世界各地的图书馆里看到奈辛瓦里的书啦!', '你已经把这几章书都给收集齐了吗，$N?', '', '去荆棘谷找奈辛瓦里远征队营地的巴尼尔·石罐。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (339, '荆棘谷的青山 - 第一章', '第一章实在是太精彩了，令人欲罢不能！奈辛瓦里设定了小说的后台，而且在小说里提到了他的同伴们，甚至包括我！$b$b不过，糟糕的是……有几页好象弄丢了。似乎第1页，第4页，第6页和第8页落在丛林中的什么地方了！', '将奈辛瓦里的小说《荆棘谷的青山》的第1页，第4页，第6页和第8页带给巴尼尔·石罐以凑齐第一章。', '终于!凑齐第一章了!', '你能找到第1页，第4页，第6页和第8页吗?没这四页，我们就没办法凑齐第一章。', '', '去荆棘谷找奈辛瓦里远征队营地的巴尼尔·石罐。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (340, '荆棘谷的青山 - 第二章', '第二章是整个激动人心的狩猎故事的楔子。可里面也有几页找不到了，我真想踢自己几脚！$b$b看来我必须得找到第10页，第11页，第14页和第16页才能凑出完整的第二章。', '将奈辛瓦里的小说《荆棘谷的青山》的第10页，第11页，第14页和第16页带给巴尼尔·石罐以凑齐第二章。', '第二章也终于凑齐了!干得好!', '我们仍然需要第10页，第11页，第14页和第16页才能完成第二章，$N。', '', '去荆棘谷找奈辛瓦里远征队营地的巴尼尔·石罐。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (341, '荆棘谷的青山 - 第三章', '第三章是我最喜爱的部分。里面详细讲述了埃尔加丁爵士和罗欧克女士使用矮人步枪完成的第一次狩猎。而且第三章的结尾也写得极好，为什么？因为实在是太扣人心弦了！$b$b不过，让我看看，似乎我们仍然要需要找回第18页，第20页，第21页和第24页来凑齐这一章。这些书页不知被风吹到哪里去了……', '将奈辛瓦里的小说《荆棘谷的青山》的第18页，第20页，第21页和第24页带给巴尼尔·石罐以凑齐第三章。', '哟!干得漂亮，$N。第三章现在也终于齐了!', '你找到第18页，第20页，第21页和第24页了吗?只有找到了这些我们才能凑出完整的第三章。', '', '去荆棘谷找奈辛瓦里远征队营地的巴尼尔·石罐。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (342, '荆棘谷的青山 - 第四章', '啊，第四章，大结局！多么精彩的结局啊！$b$b第四章里我们只丢了3页，也就是第25页，第26页和第27页。', '将奈辛瓦里的小说《荆棘谷的青山》的第25页，第26页和第27页带给巴尼尔·石罐以凑齐第四章。', '好极了!我们现在有了完整的第四章了!', '我们只需要三页就能完成完整的第四章，$N。你找到第25页，第26页和第27页了吗?', '', '去荆棘谷找奈辛瓦里远征队营地的巴尼尔·石罐。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (346, '克里斯托弗的书', '现在我已经把这本书抄完了，这里是《金属的延展性》的原本。感谢你的耐心，还有，如果你见到米尔顿的话，请替我向他道歉，我拖了那么长时间真有些不好意思。', '回到教堂广场，将《金属的延展性》交给克里斯托弗修士。', '就是这本，谢谢你，$N。愿你的肉体与灵魂永远沐浴在圣光的照耀之中!', '你找到书了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (347, '瑞斯班矿石', '瑞斯班矿石是根据第一个发现他的人——巴尔特·瑞斯班——的名字来命名的。这种矿石在冶炼之后虽然没有铁那么坚硬，但它有一种纯正的黑色，许多抄写员都用它来制作墨水或染料。在北边的瑞斯班矿洞里就可以找到这种矿石。$B$B我们通常会有一些存货，但最近大家都忙于抵抗兽人的进攻，没空去采集这种矿石。此外……这段时间以来，赤脊豺狼人占据了瑞斯班矿洞，而且他们的苦工也正在采集这些矿石。$B$B所以如果你需要的话，就得自己去那里找了。', '收集5袋瑞斯班矿石，把它们带给北郡图书馆的帕克斯顿修士。', '哦，太好啦!我可以用这些矿石配制墨水了，这样一来我很快就可以抄完《金属的延展性》。$B$B谢谢你，$N!', '你找到瑞斯班矿石了吗?', '', '去艾尔文森林找北郡山谷的帕克斯顿修士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (348, '荆棘谷热疫', '我病了…病得……非常厉害……$b$b我…染上了…荆棘谷热疫…致死的疾…疾病……$b$b……只…只有吃下…野人莫…莫…莫克…的精华…才…才有救…那…是…一只残忍而…狡猾的…野兽。$b$b……巫医安巴格瓦巫师…是…唯一会…召唤…它…的人……$b$b找到…住在南边…海岬…洞穴…里的安巴格瓦……$b$b……快点…我就要死了…就要死了……', '找到巫医安巴格瓦并要求他召唤出野人莫克，然后将野人莫克的精华交给芬·菲兹拉克。', '……感觉好点了……$B$B这是哪里?藏宝海湾?啊，天啊!我做了个奇怪的梦……$B$B……我现在还是很虚弱……', '……妈妈?$B$B好冷……$B$B……像是要掉进扭曲虚空了…抱…抱紧我，妈妈……', '', '去荆棘谷找藏宝海湾的芬·菲兹拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (349, '荆棘谷热疫', '', '', '巫医安巴格瓦最喜欢猩猩牙啦!我会为你和那些灵魂对话并召唤野人莫克过来的。$B$B你得保护好巫医安巴格瓦不受其它猩猩的伤害，否则就没有什么莫克给你啦!', '巫医安巴格瓦当然知道野人莫克是什么。是的，是的!$B$B我与他的灵魂对话并把他召唤过来，我可以。$B$B但其它的猩猩也很喜欢精神交谈。这样吧，你保护好巫医安巴格瓦，我把它召唤到你面前。$B$B巫医安巴格瓦想先要点东西。你带一颗猩猩牙来，我就会马上开始召唤它!', '', '去找荆棘谷的巫医安巴格瓦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (351, '寻找OOX-17/TN！', '你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然打开了，变成了一个看起来像是由侏儒创造的那种机器装置！一个噼里啪啦的声音从这个蛋形机器装置中传了出来。$B$B“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它的话，我会奖励你的！请把这个定向器带到我的母体机器人那里。我现在已经为你勘探出了它的所在地！它现在就在塔纳利斯的大裂口那里！”', '把定位器带到奥格索普的母体机器人那里。', '你把蛋形机器人给你的定位器放到小鸡机器人体内。$B$B里面传出了一阵叽哩咕噜的声音，然后小鸡机器人慢慢地站了起来。当这个机器能够移动之后，奥格索普的声音再次传了出来:$B$B“OOX-17/TN现在可以勉强运作了，但它需要一次大修!不过对你来说它太重了，你是背不动的……但是我想到个好办法。你能不能再帮我看着它一小会?”$B$B', '发现目标!你赫然看到石头上躺着一只……机器小鸡?!从机器小鸡中传出了声音:$B$B“太好了，你干得不错!这确实是我的母体，根据我的检测判断，它需要进行一定的启动动作才能够重新飞回藏宝海湾进行修理。请把定向器放到母体机器人里，剩下的它自己会去搞定!”', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (353, '雷矛的包裹', '雷矛部族是一个倍受尊敬的矮人部族，他们向来以独具慧眼着称——所以远在铁炉堡的巡山人才会托人不远千里地让人传信，委托我给他们打制一把武器，哈哈！$B$B这把武器已经完成了，但是巡山人卡尔·雷矛住在洛克莫丹，离这里实在是太远了。如果你正好要到那边去的话，就替我把这个包裹带给他吧。$B$B巡山人卡尔·雷矛最后一次和我联络的时候，他说他在洛克莫丹北部的哨塔里。', '把给卡尔·雷矛的包裹交给洛克莫丹北部哨塔里的巡山人卡尔·雷矛。', '啊哈!看来格瑞曼德最后还是给我造了把好斧头!我已经等不急要拿穴居人和狗头人来试试斧头啦!$B$B多谢你啦，$N。从暴风城送这东西过来一定很辛苦吧。给，这些钱是你应得的酬劳。', '你这家伙是从暴风城过来的?我听说人类那边是越来越乱了，盗匪和兽人满地跑，嗯，那真是个让你这样的$C大显身手的好地方!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (354, '阿加曼德系列', '阿加曼德系列曾是提瑞斯法林地中最富有的系列。我过去曾在他们的磨坊里工作……当然，我是说在瘟疫降临之前。$B$B天灾军团入侵的时候，阿加曼德系列的人们加固了他们的庄园，并说服了在他们家做工的人留下来帮助他们抵抗天灾军团。我们实在是太蠢了，但我们至少是愚蠢而忠诚。$B$B而阿加曼德系列用荣耀之类的幌子让我们去送死，结果现在他们倒成了天灾军团的走狗！$B$B为了被遗忘者，你必须去剿灭堕落于瘟疫之中的阿加曼德系列！把表明他们身份的标记带回来给我。', '把格里高的标记、妮萨的标记和萨尔曼的标记交给布瑞尔的库勒曼·法席恩。', '复仇的感觉是多么甜蜜呀，你说呢?当你将阿加曼德一家人消灭的时候，你有感觉到他们的躯体中有丝毫的自由意志吗?我希望有。我希望他们在湮灭之前能感觉到恐怖。$B$B我知道这想法是有点傻，不过我还是这么希望……', '你把阿加曼德一家人的尸体带来了吗?这群该死的野兽被彻底消灭了吗?', '', '去提瑞斯法林地找布瑞尔的库勒曼·法席恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (356, '巡查后方', '亡灵壁垒上的卫兵们时刻都在提防着从瘟疫之地潜入提瑞斯法的敌人，但仍有些天灾军团的士兵能躲过这样的警戒线。$B$B如果想要成功地维持我们对这一带的控制，就必须进行一次清查行动——我们绝对不能腹背受敌。如果补给线被切断了的话，那后果就将是灾难性的。$B$B去协助亡灵壁垒的卫兵进行防御吧。往东边一路巡逻过去，如果你发现任何天灾军团的爪牙，就直截了当地把他们干掉。特别注意一下东边的巴尼尔农场，那里已经到处都是天灾军团的散兵了。', '杀死8个可怕的血僵尸和8个游荡的幽灵，然后向亡灵卫兵林奈汇报。', '好极了。你对抵御天灾军团的行动做出了不少贡献。我会向执行官塞加德撰写一份报告，让他对你进行表彰。', '你的巡逻报告呢?', '', '去找提瑞斯法林地的亡灵卫兵林奈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (357, '巫妖的身份', '北边澈水湖中的一个小岛上住着一个巫妖。虽然他是个独立的亡灵，不过他认为其它所有的亡灵都是天灾军团的奴隶，他的爪牙会袭击任何靠近他的人。$B$B他是个无主之人，所以黑暗女王想要招降他。如果他确实精通于巫术的话，那么他的知识会对我们很有帮助。$B$B不过我得先看过他的法术书才能了解他的身份和学问。潜入他的营地，把书拿回来见我。', '把巫妖的法术书带给幽暗城的比索·埃斯沙德。', '很好，$N。我会研究这本书，确定这个巫妖的身份。你为女王立了一大功。$B$B<比索打开书，认真地读着微微发光的书页……>$B$B太让人震惊了!这本书的主人不是别人，正是冈瑟尔.阿坎努斯!$B$B冈瑟尔被杀前是个强大的死灵法师，在大瘟疫之前我们不仅是战友，还是亲密无间的好朋友。从他的书可以看出，死亡给了他更大的力量。$B$B他将会对我们很有用。', '$N，你拿到那本书了吗?', '', '去找提瑞斯法林地的比索·埃斯沙德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (358, '盗墓贼', '北边的加伦鬼屋你去过吗？那个地区的西南角是一大片乱坟岗，里面葬着提瑞斯法一带的大量因瘟疫而死的人。$B$B那边坟墓里的尸体大多没能变亡灵，但最近天灾军团派出了一群腐皮豺狼人到那里去收集尸体，以此来壮大他们的军队。我们不能允许这样的事情发生！$B$B你的任务有两个：杀光躲在乱坟岗和加伦鬼屋里的腐皮豺狼人，并把他们身上的防腐剂抢回来，正是这种防腐剂使他们活过来的。', '杀死腐皮盗墓贼和混血腐皮豺狼人。$B$B给布瑞尔的执政官塞弗伦带回8瓶防腐剂。', '干得很好，$N。天灾军团若以为他们可以利用这些尸体来对付我们，那就大错特错了。至于你从那些腐皮豺狼人奴隶身上收集到的液体，我们将马上送到药剂师那里进行研究。这里面一定有些什么我们也可以利用的秘密。$B$B正如我之前说的，干得好。但我们仍然需要继续抗争，你要充分抓住每一个建功立业的机会向被遗忘者证明你的价值。', '你的任务完成了吗?把那些狗一样的废物都给干掉了吗?拿到他们身上的防腐剂没?', '', '去提瑞斯法林地找布瑞尔的执政官塞弗伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (361, '未寄出的信件', '这封信的作者是格里高·阿加曼德的长子萨尔曼。收件人则是一位名为伊维特·法席恩的女士，尽管现在看来这封信显然是没寄到她手上……', '找到伊维特·法席恩，将萨尔曼·阿加曼德的信交给她。', '啊……我可怜的萨尔曼!我求过他好几次了，希望他能和我与我的父亲一起离开阿加曼德磨坊，但他对他的系列实在是太忠诚了!我就知道会是这样!我诅咒这该死的瘟疫，诅咒这该死的天灾军团!$B$B<伊维特的情绪逐渐稳定了下来……>$B$B但只有弱者才会后悔。身为一个被遗忘者，我已经有了新的目标，但我不再会去爱恋任何人了。感谢你把这封信送到我这里，让我知道我的旧爱究竟发生了些什么事。$B$B但那样的生活已经结束了，永远结束了。', '嗯?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (362, '闹鬼的磨坊', '代弗林·阿加曼德是阿加曼德家的两个男孩中最小的一个，但这两个男孩子却完全不像是兄弟。萨尔曼身材高大而且待人彬彬有礼，而他的弟弟代弗林却身体虚弱，而且嘴巴很刻薄恶毒。$B$B当阿加曼德磨坊遭遇瘟疫的时候，他是第一个被感染的。现在，只要你靠近通向阿加曼德磨坊的道路，就仍能听见他那喋喋不休的呓语。$B$B我正在收集阿加曼德系列所有人的遗骸，首先，我想弄到可怜的代弗林的尸骨。找到并摧毁他，然后把他的遗骨带回来给我。', '杀死代弗林·阿加曼德，然后将代弗林的遗骸交给布瑞尔的库勒曼·法席恩。', '谢谢你。我会把代弗林的遗骨“安葬”在我的壁炉里。他系列的其它成员随后也将被一一“安葬”。$B$B如今只有将阿加曼德系列彻底消灭，才能让我冰冷的心略略感到温暖。瘟疫到来时，他们曾背叛了我和我的系列，现在我发誓，就算掘地三尺也要把他们挖出来鞭尸!', '你找到代弗林了吗?', '', '去提瑞斯法林地找布瑞尔的库勒曼·法席恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (364, '无脑的僵尸', '我们被遗忘者正在与巫妖王的天灾军团作战，那支军队包括用亡灵法术唤起的亡灵军队，大陆北方的那些愚蠢的野兽，还有那些永远遭受折磨的鬼魂。$b$b在这个村庄的北部有大量的无脑僵尸到处横行，我们必须消灭他们。消灭他们，即使他们以前可能是我们的兄弟姐妹也不要手软，那些行尸走肉如今只不过是巫妖王的奴隶罢了。', '暗影牧师萨维斯让你杀掉5个无脑的僵尸和5个丑陋的僵尸。', '很不幸，天灾军团是无法说服的，他们庞大的军队本来可以在战场上大显神威。$B$B不过，既然他们不会帮助我们，那么我们除了消灭他们以外也别无选择了。', '如果你连最弱小的僵尸都干不掉的话，你的新生之路只可能早早结束，$N。没有完成任务，就别回来见我。', '', '去提瑞斯法林地找丧钟镇的暗影牧师萨维斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (365, '悲伤之地', '看看谁来了？你看上去是个菜鸟$c吧。如果你想向黑暗女王陛下证明自己的实力，就得先学会我们被遗忘者行事的几条基本原则。$b$b这里的西边有个农场，那块地上的人呀，就跟腐烂尸体上的苍蝇一样多。更糟糕的是，血色十字军从他们的哨塔里跑出来巡逻的时候，也可能会经过那里。给这些渣滓们好好地上一课吧，把他们的宝贝南瓜给我偷10颗来。$b$b偷到10颗南瓜以后，就把它们交给布瑞尔的药剂师乔汉。', '从位于布瑞尔西边、丧钟镇北边的农场中偷10颗南瓜来，把它们交给布瑞尔的药剂师乔汉。', '你很好地完成了任务，年轻的$C。你已经证明你的存在对黑暗女王陛下的军队而言是有意义的。', '亡灵卫兵希米尔带了信过来，说你会提供给我一些我急需的炼金材料。你收集到10颗南瓜了吗，$N?', '', '去提瑞斯法林地找布瑞尔的药剂师乔汉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (366, '归还书籍', '很久以前，冈瑟尔和我，还有现在隶属于天灾军团的图勒·鸦爪，我们三人是很好的朋友，我们曾一起在肯瑞托学习魔法。$B$B冈瑟尔和我都是大瘟疫的牺牲品，冈瑟尔后来成为了巫妖王的手下。现在我得知他脱离了巫妖王的魔爪，这真是个好消息。$B$B我们一定要找到他。我给他的书上施放了一个魔咒，当他看到这本书的时候就会知道我也已经摆脱了巫妖王的控制，希望他在知道这一点以后会加入我们。', '到冈瑟尔居住的小岛去归还他的法术书。', '我的书?!你就是偷我书的小偷!$B$B不过……是谁给这本书附上了魔法……比索?他在洛丹伦?$B$B他还活着，那么他应该也逃脱了巫妖王的魔爪……', '你的主人把你派来实在是愚蠢之极，我再也不会做天灾军团的奴隶了!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (367, '致麻药剂', '希尔瓦娜斯大人最近交给了我们皇家药剂师学会一项很有挑战性的命令。黑暗女王相信我们的知识与新发明的魔法将会是她击败阿尔萨斯的有力武器，她要求我们研制出一种新的药剂，这种药剂要比以前出现在艾泽拉斯大陆上的任何一种都要更加猛烈，它会把阿尔萨斯和他的天灾军团彻底毁灭。$b$b我的研究结果表明，野兽的血液也许是一种重要的药引。给我带回五瓶黑暗犬的血液来，我要验证一下自己的理论。', '布瑞尔镇里的药剂师乔汉要求你收集5瓶黑暗犬的血液。', '你干得不错，$N，我对你的帮助非常感激。', '你收集到5瓶黑暗犬的血液了吗，$N?时间紧迫!', '', '去提瑞斯法林地找布瑞尔的药剂师乔汉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (368, '致麻药剂', '在你帮我收集样本的同时，我的实验报告也出来了。看来我还需要更多的材料来进行进一步的研究，适当加强这种致麻药剂的威力。我要确保它们对天灾军团有效，在最短的时间内让它们失去狂暴的战力。根据我多年药理学的研究所得，药性即物性，那些麻木不仁的邪鳍鱼人与我将要配制的药剂不谋而合。$b$b我需要5片邪鳍鱼人身上的鳞片，在北边或者西边的海滩上应该就能找到那些鱼人。', '布瑞尔镇里的药剂师乔汉要求你收集5片提瑞斯法林地的邪鳍鱼人的鳞片。', '这些鳞片非常完美，$N。完全符合我的要求。', '$N，你有能力从那些鱼人身上取得5片邪鳍鱼人的鳞片吗?', '', '去提瑞斯法林地找布瑞尔的药剂师乔汉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (369, '致麻药剂', '在你出去收集鳞片的时候，我已经在我的藏书中找到了一些古老而有趣的文章。夜行蜘蛛分泌的毒液既是毒素又是良药，若能找到两者之间的临界点，就能提取出世界上威力最强的致麻药素。你该知道，天灾兵团是很难对付的敌人，不费点脑子可不行。$b$b给我带些夜行蜘蛛的毒液回来，让我完成这个实验。我想知道毒液中的感染性元素是否能和我最新研制出来的病原体共存。据说这种蜘蛛一般在提瑞斯法林地的东部出没。', '布瑞尔镇里的药剂师乔汉要你去收集4份邪恶的夜行蜘蛛的毒液样本。', '啊，很好，$N。所有其它的东西都已经加入溶液里混合好了。只差最后一步，这种最新式的致命瘟疫就要完成了!', '你找到那种夜行蜘蛛的毒液了吗，$N?这是我的实验所必需的最后一种成分了。', '', '去提瑞斯法林地找布瑞尔的药剂师乔汉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (370, '与血色十字军的战争', '执行官阿伦的文件中对如何清除这群在我们的土地上肆虐的人类的问题作了详细的部署。情报表明，血色十字军派遣了派瑞恩队长以及足有一个整编旅的部队进驻了布瑞尔西南方的废塔。$b$b去杀掉派瑞恩队长、3名血色十字军狂热者和3名血色十字军传教士，然后向我回报。', '布瑞尔的执行官塞加德要求你杀掉派瑞恩队长、3名血色狂热者和3名血色传教士。', '派瑞恩队长的死毫无疑问会令黑暗女王陛下\r\n高兴。你干得非常漂亮，$C。', '年轻的$C，你不应该在你的同胞们需要你为他们的生存而战时躲在布瑞尔这里浪费时间。现在就动身吧，带上你的武器，到西南方的废塔那里去干掉派瑞恩队长、3名血色十字军狂热者和3名血色十字军传教士。我们得把血色十字军像牲口一样赶在一起，然后一网打尽。', '', '去提瑞斯法林地找布瑞尔的执行官塞加德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (371, '与血色十字军的战争', '我们仍然处于战争状态中，而且血色十字军正在逐渐壮大。执行官阿伦给我的报告中提到，在瓦松队长的指挥下，血色十字军正以提瑞斯法东南部巴尼尔农场附近的那座废塔为据点肆意劫掠。$b$b去杀掉瓦松和5名血色十字军苦行修士，这对十字军来说将是一次沉重的打击！', '布瑞尔的执行官塞加德要求你杀掉瓦松队长和5名血色苦行修士。', '瓦松队长的死一定会在很大程度上影响血色十字军在提瑞斯法林地的战略部署和推进计画，但现在我们还面临着其它的威胁。', '你的任务还没有完成，你怎么就回来了?或许你一点也没把这群正在搅乱黑暗女王陛下计画的愚蠢人类放在眼里?如果不是的话，你就应该听从使命的召唤，去杀死瓦松队长和他手下的血色十字军苦行修士!', '', '去提瑞斯法林地找布瑞尔的执行官塞加德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (372, '与血色十字军的战争', '血色十字军已经从提瑞斯法林地北部的废塔出发，穿过了法奥之墓。根据当前我们所掌握的情报，一个名叫麦拉其的军官指挥着这支邪恶的部队，他是个非常残忍的家伙。$b$b我相信你能完成这个非常重要而又危险的任务。以黑暗女王陛下的名义，杀死麦拉其和他的两名保镖！', '布瑞尔的执行官塞加德要求你刺杀麦拉其队长及他的两名保镖。', '你干得实在是太棒了，$C。有你这样的勇士在被遗忘者的旗帜之下为黑暗女王而战，我们离战胜阿尔萨斯又近了一步。我对你的感觉不错，$C。', '你还没有去履行你的职责，$C。只要血色十字军继续牵制着我们的士兵，我们就根本没办法指望黑暗女王陛下的计画能够得到良好的执行。杀了他们，向希尔瓦娜斯大人证明你的价值!', '', '去提瑞斯法林地找布瑞尔的执行官塞加德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (373, '未寄出的信', '搜查艾德温·范克里夫的尸体时，你从一堆杂乱的物品中找到了一封还未来得及发出的信。地址一栏上写着巴隆斯·阿历克斯顿，暴风城石工协会，城市大厅，教堂广场。$B$B这显然是最近刚刚写好并封上的。', '将艾德温·范克里夫的信交给巴隆斯·阿历克斯顿。', '艾德温.范克里夫?我宁可收到一封我死去的祖母寄来的信……这么说，你已经把他给杀了?请原谅我这样说，但我确实非常吃惊。他年轻的时候是个无人能敌的强大战士。那么，让我看看，这么多年不见，他都给写了些什么呢。$B$B<他拆开了信封。>$B$B艾德温……这么多年了……你真的一点都没有变呀……还是那么一个理想主义者，浪漫主义者……他一点都不关心他伤害了谁，$N。复仇已经彻底充斥了他的身心。但是，我想，我还是不能怪罪他。', '嗯?我能帮你做些什么吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (374, '死亡证明', '执行官塞加德告诉我说你最近和血色十字军干上了，提瑞斯法林地里现在到处都是这帮讨厌的家伙。$b$b黑暗女王麾下的瓦里玛萨斯大人计划将人类这种艾泽拉斯大陆上的渣滓与垃圾彻底清除掉。但当前的状况是，人类当中最麻烦的一群家伙——血色十字军——已经杀入了提瑞斯法林地，我们必须得面对他们的挑衅。$b$b去吧，去给这群该死的血色十字军一点颜色看看，$c。给我带回10枚血色十字军徽记之戒，以此证明你对伟大的黑暗女王陛下与瓦里玛萨斯大人的忠诚。', '给布瑞尔的亡灵卫兵伯吉斯带回10枚血色十字军徽记之戒。', '瓦里玛萨斯大人会为你感到骄傲的。你干得很不错，$C。', '你收集到10枚血色十字军徽记之戒了吗，$C?', '', '去提瑞斯法林地找布瑞尔的亡灵卫兵伯吉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (375, '死亡之寒', '好冷啊……可怕的瘟疫正如冰冷的毒蛇一般在我的血管中逡巡，也许很快我就会彻底失去意志，但这世上没有任何东西能够阻止我为我们伟大的黑暗女王效命。一接到命令，我就开始为希尔瓦娜斯大人军队中那些死去的战士缝制尸袋。$b$b但现在我的手却因为寒冷而颤栗不已。如果你能给我带回五张夜行蝙蝠的毛皮和一些粗线的话，我就可以给自己缝条毯子了。帮帮我，$N，这样我就可以继续为黑暗女王陛下的事业效力了。', '给布瑞尔的格雷森·戴德马带回5张夜行蝙蝠的毛皮和一些粗线。', '太感谢你了，$N。但愿某一天，希尔瓦娜斯大人会认识到你的勇敢……', '你找到五张夜行蝙蝠的毛皮和粗线了吗，$N?', '', '去提瑞斯法林地找布瑞尔的格莉丝·戴玛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (376, '被诅咒者', '我的任务包括照料受伤的士兵，缝制铠甲和衣服，还有为暗影牧师萨维斯提供任何他可能需要的支持。$b$b看起来，你也即将加入到为他效力的队伍中……我猜是要猎杀那些没脑子的家伙。好吧，如果你还想留着你的小命的话——我想你一定是的——也许我能帮助你。我这里没有足够的狼爪子和蝙蝠翅膀了，如果你能帮我弄一些来的话，我会帮你找几件铠甲。在这里的西北方可以找到大群的狼和蝙蝠。', '新兵艾尔雷斯需要6只食腐狼的爪子和6只夜行蝙蝠翼。', '谢谢你，$N。这件铠甲应该对你有用。$B$B但愿比起前一个穿着它的人，你能活得更久一些……', '在我给你铠甲之前，千万别不小心挂掉了。', '', '去提瑞斯法林地找丧钟镇的新兵艾尔雷斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (377, '罪与罚', '贵族议会好象嫌他们对暮色森林的漠不关心还不够过分，现在他们居然无视夜色镇议会的存在，决定把迪克斯特·瓦德囚禁在暴风城，而不是按照埃伯洛克公爵大人的判决将这个恶棍斩首！$b$b迪克斯特·瓦德是在把墓地里的尸体卖给摩本特·费尔时被抓住的，这理应是死罪。可是暴风城却认为他们才拥有对他的处决权！$b$b去暴风城的监狱把瓦德杀掉，把他的手给我带回来作为证明，我会奖赏你的。', '夜色镇的米尔斯迪普议员要你杀死迪克斯特·瓦德，并把他的手带回来作为证明。', '这么说，迪克斯特.瓦德已经为他的罪行付出代价了?这是他罪有应得。为你干杯，我的朋友!你不仅把安宁带给了死者的家人，还给贵族议会的腐败官僚们发出了警告。暴风城必须顺应暮色森林人民的意愿，否则我们就脱离它的暴政去追寻自由。', '让迪克斯特.瓦德这样骚扰死者的恶棍活下来，就等于背叛正义。你去执行埃伯洛克大人的判决，杀掉瓦德之后再回到我这儿。我们可以还给被盗墓的死者的家属一个公正的结果，而且还可以把这个消息传达给暴风城的贵族议会，让他们好好颜面扫地一次。', '', '去暮色森林找夜色镇的议员米尔斯迪普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (378, '卡姆·深怒', '你已经向我们展示出了你对麦格尼陛下的忠诚，$c。而且我也深刻地感受到了你对那些黑铁矮人的仇恨。$b$b我必须要坚守岗位，因此，我不得不把一个本应由我亲自去完成的重要任务交给你。根据罗戈收集到的情报显示，卡姆·深怒正是袭击萨多尔大桥的元凶。由于֦ɀ布下的邪恶计划，长须才失去了他的亲人。$b$b这个刽子手由于某些政治原因被扣押在了暴风城的监狱里。我要他死，$N。为了长须！杀死卡姆·深怒，把他的徽记给我带回来！', '丹莫德的莫特雷·加玛森要求你把卡姆·深怒的徽记交给他。', '这么说来，卡姆.深怒这家伙自己也终于尝到死亡是怎样的滋味啦?很好。这正是那些懦弱的黑铁矮人应得的下场。你做得非常好，$C。萨多尔大桥惨案的牺牲者们终于可以安息了，他们的家人在听到了卡姆.深怒被正法的消息之后也会释然许多。长须的丧兄之仇终于得报了。', '我可不想让那群愚蠢的人类官僚介入到我们矮人的内部事务里来，$N。卡姆.深怒是萨多尔大桥惨案的同谋者，证据确凿。麦格尼国王的许多善良臣民都因他而死，人类也许早就把这件事给忘了，让那个刽子手在监狱里安度晚年，但我一想到这个混蛋还活着，就寝食难安!', '', '去湿地找丹莫德的莫特雷·加玛森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (379, '口渴的比格维兹', '你需要能量源，我可以帮你。但是你知道我要什么吗？我要喝的！给我弄五只废土水袋来，然后我就会把4711-FTZ交给你。$B$B现在……你想知道在什么地方可以找到废土水袋，对吗？去这里的东边找废土游牧民吧，他们身上会带着这种水袋。', '给加基森的首席工程师沙克斯·比格维兹带去五只废土水袋。', '很好，4711-FTZ是你的了。现在，它还不够完善，所以你要抓紧时间收集资料，否则它随时都有可能罢工!$B$B当你得到你要的东西之后，记得把4711-FTZ带给我，然后我就可以把它安全地关闭了。你最多有两个小时的时间来使用它。$B$B如果这点时间还不够你完成任务的话，我会再卖给你一个能量源。但请记住那绝对不会是免费的!', '怎么样，那些游牧民有没有“自愿”把废土水袋交给你呢?', '', '去塔纳利斯找加基森的首席工程师沙克斯·比格维兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (380, '夜行蜘蛛洞穴', '我们的一项最重要的任务就是获取赖以生存的自然资源。即使在当年联盟最鼎盛的时候，黄金资源也是非常缺乏的。$b$b这里的西北面有一处金矿，我们需要矿洞里的资源，但是那里蜘蛛横行，我们根本无法进去采掘金矿。我手上没有人可以去完成这项任务，所以我们只有一步一步慢慢地来。去那里看看吧，也许你能做些什么……', '执行官阿伦要你去杀掉8只小夜行蜘蛛和5只夜行蜘蛛。', '嗯，很好，这是一个良好的开端。我们可能需要几周或者几个月的时间来清除这里的虫害。然后就可以一把火烧掉那些该死的蜘蛛网。$B$B你干得很好，$N，我想你应该还能帮我做些其它的事情。', '小心蜘蛛的毒液，$N。如果你感到有强烈的灼烧感，就要看看自己身上是不是已经被蚀出个洞来了。', '', '去提瑞斯法林地找丧钟镇的执行官阿伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (381, '血色十字军', '得知我们在金矿的进展非常顺利，你一定很开心吧？得益于你的帮助，我们终于可以把注意力放到别的事情上了。$b$b我的斥候报告说，一支血色十字军的小分队在东南方创建了营地。血色十字军是一个卑鄙的组织，他们视我们为死敌，只要有一个亡灵——无论是巫妖王的爪牙还是我们被遗忘者——还活着，他们就不会停止追杀我们的行动。所以我们必须先发制人！$b$b你要多加小心，这些邪恶而狂妄的十字军是一群非常危险的家伙。', '从血色信徒和血色新兵身上收集12枚血色十字军臂章，把它们交给执行官阿伦。', '只要他们愿意讲道理，也许我们可以和他们坐下来谈判，对不对，$N?哈哈!$B$B一群不长眼睛的蠢货。', '那些笨蛋……他们只会自掘坟墓，却从来都乐此不疲。', '', '去提瑞斯法林地找丧钟镇的执行官阿伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (382, '十字军信使', '布瑞尔那边的上级给我发来的文件显示，有一个从血色修道院出发的血色十字军斥候已经潜入了丧钟镇。有报告说这个人携带着非常重要的情报。至于更多的细节，我不得而知。但不管怎么样，我们必须得到这份情报！$b$b你是我眼下能调动的最合适的人选，$n。找到那个信使，带回你能弄到的任何情报。', '到十字军营地去杀掉信使迈文·考加尔，将你发现的情报交给执行官阿伦。', '嗯……让我们看看你都带回了些什么……$B$B<他开始迫不及待地阅读你带回的文件。>$B$B一些前线的消息……没意思。侦察报告……新的指示“继续在废墟附近创建营地……”这些事情我们都知道……啊，这是什么?一张有关他们的战场指挥官和斥候的部署图!这对我们很有用。', '你的任务完成了吗，$N?', '', '去提瑞斯法林地找丧钟镇的执行官阿伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (383, '重要情报', '我必须将这些东西交给我的上级——执行官塞加德，他就在布瑞尔。有了这份详尽的情报，我们就能给血色十字军以沉重的打击。你在丧钟镇对我们做出了很大的贡献，现在我要你去把这份情报及时交给塞加德，我想他能帮你找到更多能让你大展身手的工作。$b$b沿着这条路向北走出丧钟镇，在进入提瑞斯法林地以后，你很快就会来到一个十字路口，这时向东走，然后一直向前就可以到布瑞尔了，路上有一座炉灰庄园可以帮你确认自己的方向。', '把血色十字军文件交给布瑞尔的执行官塞加德。', '干得漂亮!这是一份很重要的情报，$N。嗯……是提瑞斯法林地的十字军军官名册……$B$B如果我们发动突袭，一举干掉这些十字军的军官，就能给那些该死的狂热者来一个当头棒喝。', '你有什么事?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (384, '啤酒烤猪排', '啤酒烤猪排是我的老主顾们最喜欢的大餐！问题是，为我提供猪排的猎手被国王征募去打仗了。$b$b也许你能帮帮我？如果你可以给我弄六块峭壁野猪肋排，外加一杯酒店里卖的狂想麦酒的话，我就把祖传的啤酒烤猪排的烹饪方法教给你，而且我还可以让你免费品尝我做出来的美食！秘密就在麦酒里！', '卡拉诺斯的拉格纳·雷酒需要6块峭壁野猪肋排和1杯狂想麦酒。', '喷香的麦酒已经酿好', '我需要6块峭壁野猪肋排和1杯狂想麦酒。', '', '去丹莫罗找闪光岭的拉格纳·雷酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (385, '捕猎鳄鱼', '很多猎人到洛克莫丹来都是为了捕猎这里的鳄鱼。总有一些商人专门寻找这种鳄鱼皮，用它们来制作衣物或是护甲，还有些人则喜欢品尝鳄鱼肉。$b$b我们一直在进行这种贸易，但交易量并不是很大，因为鳄鱼很凶猛，而且它们一般都盘踞在洛克湖中的小岛上。嘿，别被我的话给吓倒了，和鳄鱼较量一番对你来说也是一种历练。$b$b你看能不能……', '收集5块鳄鱼肉和6张鳄鱼皮，把它们交给旅行者营地里的马雷克·铁心。', '你收集的这些东西的成色还真不错，$N。当然，好东西一定有好价格。', '我有没有跟你说过有一次我差点被鳄鱼咬死的事情?那个恶心的东西，牙齿象刀一样锋利。不过我很幸运……我把刀子插进了它的嘴里。现在我还总是随身带着那把刀……', '', '去找洛克莫丹的马雷克·铁心。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (386, '伸张正义', '可怕的塔格尔是加塞尔佐格手下的一个高级杀手。他杀人的手法十分残忍，即使以兽人的标准来看也是残暴无比。那些为了保卫国家而奋勇作战的战士们落在他手里都会被他折磨致死。这个恶棍现在被关在暴风城的监狱里，被判处了死刑。不过，这件事情好象出了点小差错，一个官僚习气十足的贵族推迟了处死他的日期。我敢打赌这里面一定有鬼。$b$b处死塔格尔吧，$N。到暴风城的监狱里去，在他玩出什么把戏之前把他干掉。', '把塔格尔的徽记带给湖畔镇的卫兵伯尔顿。', '塔高尔终于伏法了。俗话说恶有恶报，听到这个消息我真的很高兴。你干得很好，$N。有些时候，真正的正义只有摆脱了法庭的桎梏和政治的腐败才能得到伸张。', '你到暴风城监狱里去了吗?我怕万一塔高尔耍了什么手段而侥幸逃生，早晚他会被放出来。他被判处了死刑，$N，现在他只是因为某个贵族的小算盘而暂时保全性命。', '', '去赤脊山找湖畔镇的卫兵伯尔顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (387, '镇压暴动', '我们必须把暴动给镇压下去！我需要你的帮助。如果外面的人知道监狱里面已经失去了控制，我一定会丢了饭碗的！这是我所见过的最无聊的闹剧了。现在最重要的是逼迫这些囚犯投降，这样才能保证暴风城的安全。$b$b叛乱的代价就是死亡。去杀掉一些囚犯，这样叛乱才能得到控制！', '暴风城的典狱官塞尔沃特要求你杀死监狱中的10名迪菲亚囚徒、8名迪菲亚罪犯和8名迪菲亚叛军。', '你在监狱事件中的表现堪称英勇，$N。显然这个问题对我们来说都不是什么小麻烦。但你干得很出色，我对你非常感激。', '监狱里的叛乱依然没有平息!我们得让这群迪菲亚老鼠知道，我们是绝不会容忍他们的行为的。现在，快去让他们见识见识我们的实力!', '', '去找暴风城的典狱官塞尔沃特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (388, '鲜血的颜色', '痛苦如同冰冷的河水一样从我的血管中流过。我的孙子麦克是个多好的孩子呀，他只有14岁。当暴风城的军队被派往前线的时候，麦克也拿起了武器去守卫城市。他是监狱的守卫，那座监狱里关押着许多迪菲亚兄弟会的成员。有一些囚徒们把他们的羊毛毯改织成他们组织的头巾，麦克把这件事情上报了，结果他遭到了报复，被人从后面刺了一刀。$b$b我要报仇。给我带回10条迪菲亚盗贼们的羊毛面罩，像鲜血一样殷红的那种。', '暴风城的尼科瓦·拉斯克要你取得10条红色毛纺面罩。', '就是这些头巾，这些堕落的标志，就是这些让我的麦克为此送命的吗?太不值了……$B$B哎，时光不能倒流。不过，$N，你用你的行动替我的系列讨回了公道。', '你回来了，$C。你从监狱里的那些迪菲亚人渣身上取得10条红色毛纺头巾了吗?', '', '去暴风城找旧城区的尼科瓦·拉斯克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (391, '监狱暴动', '让我们把话挑明了说吧，$n：我不信任你。但是，现在的情况紧急，我也管不了那么多了。$b$b你到下面去干掉那个该死的斯瑞德，把他的徽记带给我。$b$b还有，如果你胆敢跟他合计什么把戏，或者你不上来了的话……只要被我抓到你，就准备跟那群蛆死在一块吧。', '杀死巴基尔·斯瑞德，把他的徽记带给监狱的典狱官塞尔沃特。', '没有了斯瑞德的领导，这次暴动也许就能得到控制了……$B$B你看，我得说，在一开始的几分钟里，我真的没料到你有这么厉害，显然那是我判断失误了。$B$B我想你没能从这些家伙身上搞来什么有用的消息吧?但我这倒有一两条你可能会感兴趣的消息，是关于斯瑞德的某些活动的消息。', '要么你把斯瑞德的头拿来，要么我把你的头拿走，明白了吗?', '', '去找暴风城的典狱官塞尔沃特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (392, '好奇的访客', '在斯瑞德刑期的第一年里，从来从没有人探视过他。我猜当时迪菲亚兄弟会认为他已经彻底没用了，所以准备任他自生自灭。$b$b然而几个月前，一切都变了。有人开始定期探视他……每周一到两次。那是个奇怪的男人，沉默寡言。我有点疑心，但他的证件是真实且合法的。$b$b他的名字叫麦里克，这是他的一些资料。我觉得他可能不会再来探视斯瑞德了。', '将神秘访客的资料交给暴风城的巴隆斯·阿历克斯顿。', '嗯，麦里克?我不清楚，我从来没有听过这个名字。但这有可能是个假名!或许是以前的石匠，或者是迪菲亚兄弟会的人……如果塞尔沃特所形容的没有错的话，那或许有人能认得出他。让我想想……', '你找我吗，$N?你有什么发现?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (393, '往日的阴影', '我确实没什么线索，$n。但或许另外有人能帮上你的忙，而且他还欠了我一个人情——好了，现在不是说那个的时候。暴风城兵营中的军情七处首领马迪亚斯·肖尔或许能轻松搞定这类事。$b$b如果说有谁知道这事的话，一定就是他，他此刻就在旧城区。', '与旧城区的马迪亚斯·肖尔谈一谈。', '你说的事我有点印象……$B$B啊，对，当然!你猜的没错，麦里克不是他的真名。刺客们总会有着许多名字和许多面具，没用的时候会毫不犹豫地把它丢掉。$B$B我们都习惯叫他沉默之刃马尔松，不过这八成也不是他的真名。名字无关紧要，他的确是个不错的刺客，我对他的事情知道得也不少。$B$B马尔松现在受葛瑞格.莱斯科瓦大人所雇用，就是那个声名狼籍的领主，没错，据说是暴风城中最堕落的贵族。', '你好，我能为你做些什么吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (396, '觐见国王', '我准备了一份报告呈递给国王陛下。当我听说了你最近的事迹之后，我认为你是递送这份报告的最佳人选。别担心，国王陛下一定会嘉奖你的。$b$b你的觐见已经被列入了陛下的日程表，所以你最好快点到暴风要塞里去等待召见。', '将有关迪菲亚兄弟会的报告送给暴风要塞里的国王瓦里安·乌瑞恩。', '你替暴风城所做出的贡献应该得到表扬，$N。如果范克里夫成功地实行了他的计画，无疑将会给王国带来巨大的灾难，我们必须避免这种事发生。$B$B收下这个吧，$C，它代表了我的谢意。', '$N，对吗?巴洛斯.艾力克斯顿已经告诉我你会前来。我得说，我对你要说的话非常有兴趣。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (398, '悬赏：蛆眼', '悬赏：蛆眼！$b$b这只名叫蛆眼的豺狼人臭名昭着，即使是在它的同类眼中都显得非常邪恶而污秽，它因为对被遗忘者们犯下了不可饶恕的罪名而被判处了死刑，这只卑鄙的野兽为巫妖王的军队偷盗了无数的尸体。上次有人看到蛆眼作恶是在布瑞尔北边的加伦鬼屋。$b$b布瑞尔镇将为执行这项判决的勇敢者提供一份高额的奖金。完成任务之后，请将这只野兽的爪子交给执行官塞加德。$b$b只有弱者才会有怜悯之心。', '杀死蛆眼，并将他的爪子交给布瑞尔的执行官塞加德以换取酬劳。', '蛆眼的恶行终于使它得到了应有的下场。或许你英勇的行动会给那些想要伤害我们的家伙一个最明确的警告。我代表布瑞尔镇感谢你的帮助，$N。', '嗯?', '', '去提瑞斯法林地找布瑞尔的执行官塞加德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (399, '童年的记忆', '许多年前，我还只是个在西部荒野的农场里干活的小男孩，不过现在看来，这段回忆只能封存起来了。俗话说时光一去不复返，这句话在我身上得到了印证，我家的房子已经被烧毁，现在又给一群盗贼占领了。$b$b我曾向父亲询问过我的一些物品的下落——包括我的第一个指南针，他说他没办法把那些东西拿回来。但是他又说……它们应该就藏在农场外面的什么地方。$b$b你可以在哨兵岭的西边找到阿历克斯顿农场。你能帮我把那些东西找回来吗？', '到巴隆斯·阿历克斯顿在西部荒野的房子里去找到他的指南针，并将它带回暴风城的教堂广场交给他。', '啊，谢谢你，$N!这对我来说虽然没有什么实质的用处，但我对它的感情……谢谢你把它找回来……真是太麻烦你了，光是去西部荒野跑一趟就得花掉你不少时间吧。我对你感激不尽，拿着这个吧，再次真诚地感谢你。', '$N!你的运气如何?', '', '去找暴风城的巴隆斯·阿历克斯顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (400, '贝尔丁的工具', '贝尔丁·钢架是本地最好的坦克机械师！不过他从来不爱护他的工具，他弄坏扳手的速度远远大于我们的供货速度！$B$B我们刚刚才赶出他最近订的一批货。如果你能把这些东西交给他，我想他一定会让你感到不虚此行的。$B$B他开的钢架补给站就在卡拉诺斯的东北边。老牌的攻城坦克驾驶员们经常在那里碰头，所以你到了那里之后要睁大眼睛，说不定能找到好些活儿。', '把贝尔丁的工具交给贝尔丁·钢架。', '你带来了我的工具?干得不错，$g小子:小姑娘;，干得不错!一个小时前，我刚弄坏了最后一个扳手，现在正愁没有工具来修好驾驶员迪恩.石轮的攻城机具。$N，你可真是帮了我的大忙!请接受这点小小的谢意吧!', '嗯?要成为一个攻城机具的驾驶员，恐怕你还太年轻了。不过没关系……你需要修理什么东西吗?$B$B到后面慢慢排队去吧。我正忙着修理两部攻城机具，这几天恐怕都没工夫。$B$B哦，你不会是有别的事情吧……?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (404, '腐烂的爪子', '有一小撮天灾军团的士兵已经渗入了提瑞斯法林地，在布瑞尔以西一带的旧桥附近活动。$B$B去那边去增援我们的部队，杀光所有你见到的腐烂的死者和破碎的尸体。把他们都给我拆成骨头架子，然后把他们那腐烂的爪子给我带回来，我会奖励你的。', '给布瑞尔的亡灵卫兵迪林格尔带回7只腐烂的爪子。', '干得好。我真后悔没能亲眼看见你把那群该死的家伙给捣成烂浆糊!', '你完成了我委托给你的任务了吗?拿到那些腐烂的爪子了吗?', '', '去提瑞斯法林地找布瑞尔的亡灵卫兵迪林格尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (405, '流浪的巫妖', '幽暗城里的一位法力强大的高阶法师比索·埃斯沙德给了我一个任务，让我去为他找一个与天灾军团有着丰富斗争经验的勇士。你，$N，显然就是他要找的人。$B$B现在立刻去向比索报到，他会给你指派新的任务。我也不清楚任务的细节，但大致上好象是要招安一名独居的巫妖之类的。这份工作可能会很危险。$B$B去做好准备吧，$C。你绝对不能失败。$B$B比索就在幽暗城的魔法区里。', '将塞弗伦的命令交给幽暗城的比索·埃斯沙德。', '啊，你就是执政官塞弗伦派来的人呀。是的，我有件重要的事要托付给你。$B$B我相信塞弗伦一定找了最合适的人来替我完成这件任务……但我们还是眼见为实吧。', '你好。你要么不知道我是谁，要么就是你找我确实有急事，对吧?$B$B如果这两者都不是的话，你就太蠢了，竟然敢打扰我……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (407, '悲伤之地', '看上去这南瓜没有什么不正常吧？如果我们想要阻止阿尔萨斯的军队在北方继续推进外加人类势力在南方的肆虐横行，那么我们必须从现在开始就意识到自己身为亡灵的优势。$b$b只要稍微耍点小把戏，一个简单的南瓜就能让任何人成为黑暗女王的优秀探子。我最新培育的这种南瓜就可以做到这一点。$b$b现在据说又有个血色十字军狂热者被俘虏了，他被关在恐惧之末旅店的某个房间里。把这个南瓜拿去给那个蠢货，让他吃了。', '将斑纹南瓜带给被关在恐惧之末旅店地下室中的血色十字军俘虏。', '圣光保佑!总算有得吃了!这南瓜可真甜……', '离我远点，你们这群愚蠢而邪恶的东西!愿圣光保佑我!我们伟大的血色十字军一定会把你们……这群垃圾清出艾泽拉斯……$B$B……噢，等等。那是要给我吃的东西吗?我真的好饿好饿……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (408, '系列墓穴', '如今阿加曼德磨坊已经成了天灾军团的一处重要据点，其中防守最为坚固的地方就是阿加曼德的系列墓穴了。天灾军团的一个兵团就驻守在那里，他们由一个名叫达高尔队长的骷髅领导着。他们还利用某种通灵术复活了阿加曼德系列的死者们，并打算利用它们来对付我们。$B$B我们绝对不能允许这种事情发生，你必须阻止它。到阿加曼德系列墓穴去，战胜那些还魂的阿加曼德系列的死尸们。$B$B还有，把达高尔队长的徽记也给我带回来。', '杀死8个哀嚎的鬼魂和8个腐烂的古尸。$B$B消灭达高尔队长，并将他的徽记交给布瑞尔的执政官塞弗伦。', '你的行动对天灾军团来说无疑是次沉重的打击。你的胜利绝对不会被忽视的―无论是对我们被遗忘者还是对天灾军团来说都是这样。$B$B继续尽我们的一切努力来与天灾军团抗争吧，$N，总有那么一天，我们会把巫妖王给赶出艾泽拉斯的!', '时间紧迫，$N。天灾军团在提瑞斯法林地的势力分分秒秒都在不断壮大。', '', '去提瑞斯法林地找布瑞尔的执政官塞弗伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (409, '证明忠诚', '你说你没有被巫妖王控制住自己的思想，这一点已经由比索在我书上灌入的魔法证实了。但是，你仍然得先证明自己是天灾军团的敌人，这样我才会彻底信任你。$B$B在这座岛屿南边的小岛上有一处古老而血腥的祭坛，那里当前被一个强大的天灾军团斥候莉莉丝·奈法拉所占据着。$B$B从我身边的这个木箱里拿出一根诱灵蜡烛，然后将其点燃并放到祭坛上，莉莉丝会很快醒来。消灭莉莉丝，这样一来，我就会相信你确实是巫妖王的敌人了。', '拿上一根诱灵蜡烛。$B$B召唤出莉莉丝·奈法拉并杀死她。$B$B然后向岛上的冈瑟尔回报。', '你打败了莉莉丝.奈法拉，这充分证明了你确实是天灾军团的敌人，真是令人难以置信呀。$B$B我一直以为我是最后一个拥有独立思想的不死族了，但你已经向我证明了这世上还有其它摆脱了巫妖王统治的不死族。', '我期待着你向我证明你的忠诚，$C。', '', '去提瑞斯法林地找十字军前哨的冈瑟尔·阿坎努斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (410, '潜伏的阴影', '', '', '你将诱灵蜡烛放在桌上，然后点燃了它……', '这是一张古老、结实、满是血迹的桌子。', '', '去找西瘟疫之地的莉莉丝的餐桌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (411, '巫妖归顺', '拜托你，请将这块虚空宝石带给我的老朋友比索。这样我就能和他交流了……我有好多事想和他说呢。', '将虚空宝石交给幽暗城的比索·埃斯沙德。', '你说服他加入我们了!你真是为我们被遗忘者立了大功呀，$N。黑暗女王陛下的力量又被加强了。', '把书还给冈瑟尔了吗?他说了些什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (412, '自动净化装置', '通过对诺莫瑞根现状的进一步分析，我们发现不但那些该死的穴居人没有被消灭，反而有更多的侏儒变成了丧心病狂的、邪恶的怪物。$b$b我和奥齐希望用我们的最新发明——自动净化装置——来扭转这种局面。这台机器即将大功告成，不过我们急需一些多档齿轮和自适应齿轮才能搞定最后的部分，请从诺莫瑞根的麻疯侏儒那里弄些过来吧。', '收集8个多档齿轮和8个自适应齿轮，把它们交给卡拉诺斯的拉兹·滑链。', '这些多档齿轮和自适应齿轮与奥齐的自动净化装置设计图上的规格完全吻合。现在，只要我往内燃机活塞里加一些液态润滑剂，调整好齿轮的档位，增加电凝胶的粘性，地精们就将重新回到正常的状态……$B', '只要有充足的多档齿轮和自适应齿轮，自动净化器就能很快运转起来。', '', '去找丹莫罗的拉兹·滑链。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (413, '微光酒', '我希望我兄弟维拉特能够品尝一下我最新酿制的微光酒。他是一个在南面的警戒塔里执勤的巡山人，就是靠近洛克莫丹边界的那两座哨塔里的一座。$B$B他不是酿酒师，但是他非常喜欢喝酒，而且我相信他一定喜欢这种酒的。$B$B你能替我把这桶微光酒交给他吗？', '把这一大桶微光酒交给巡山人维拉特·麦酒。', '<巡山人维拉特.麦酒品尝着微光酒……>$B$B嗯，太棒了!这东西让我的眼睛放射出别样的光彩，我感觉自己即使在黑夜中也能够看清一切!', '你好，$C!是哪阵风把你吹来啦?$B$B我希望你给我带来的是一些令人振奋的东西。我已经很久没有好好战斗了，而且这桶麦芽酒也都快要干了……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (414, '卡德雷尔的酒', '我兄弟酿造的微光酒真是极品！我想让我的一个朋友也品尝一下，他叫卡德雷尔，经常在塞尔萨玛附近的路上巡逻。$B$B要去塞尔萨玛的话，就往东南方穿越隧道，然后在岔路口向东北方走，最后沿着大路一直走就能到塞尔萨玛了。$B$B把这桶微光酒交给巡山人卡德雷尔尝尝，看看他是不是也赞不绝口！', '把这桶微光酒带给洛克莫丹的巡山人卡德雷尔。', '让我尝尝……$B$B麦格尼的胡须啊!我觉得天旋地转啦!我的四肢也变得轻飘飘的。$B$B我有一种要飘起来的感觉!', '你好，$C，欢迎来到塞尔萨玛!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (416, '狗头人的耳朵', '我们在西边遇到了点麻烦。坑道鼠狗头人在那里的丘陵地带建起了巢穴，把我们的地盘弄得乌烟瘴气！$B$B我们必须把他们给消灭掉。去捕杀那些坑道鼠狗头人，把他们的耳朵拿回来给我，我就给你赏金。$B$B坑道鼠狗头人的巢穴就在塞尔萨玛北边的山脚下。', '收集12只坑道鼠的耳朵，把它们带给塞尔萨玛的巡山人卡德雷尔。', '呃!没想到这些坑道鼠的耳朵这么难闻!$B$B这是给你的报酬，$N。做得好。$B', '你好啊，$N。进行得怎么样了?', '', '去洛克莫丹找灰爪山的巡山人卡德雷尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (417, '驾驶员的复仇', '莫里·铁钻在他的日记中写道，他受到了一头名叫癞爪的巨型冰爪熊的袭击。他赶走了这只野兽，不过自己也已遍体鳞伤。$B$B从莫里尸体上的伤痕判断，癞爪一定又折回来杀死了他。$B$B然而，莫里在他的日记中写下了他最后的遗愿：$B$B杀死癞爪，为我复仇。', '杀死癞爪。$B$B把它的肮脏的爪子和莫里·铁钻的日记交给驾驶员塞克·锤足。', '这真是个让人伤心的消息，莫里是我最好的朋友……我真希望你杀死那头叫作癞爪的野兽时我也在场!$B$B谢谢你，$N。铁炉堡攻城坦克旅的驾驶员会永远感谢你的。', '你好，$N。你有我朋友莫里.铁钻的消息吗?', '', '去丹莫罗找北门哨岗的驾驶员塞克·锤足。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (418, '塞尔萨玛血肠', '塞尔萨玛这儿饥肠辘辘的人可真不少，有跑进跑出的孩子，也有在挖掘场忙了一整天的工人。我们这儿有一道出名的菜色——血肠，你大概还没尝过吧？$b$b没有？在这儿要吃饭就得干活，别以为你是个出色的$c就可以例外。$b$b我需要熊肉、做肠衣用的猪大肠，还有做调料用的蜘蛛的毒液。把这些东西找来，剩下的就交给我维德拉好了！', '收集3块熊肉、3根猪大肠和3份蜘蛛的毒液，把它们交给塞尔萨玛的维德拉·壁炉。', '相信我，这东西比看起来要硬些，不过……$B$B哦，我从来没听说有谁对做血肠有兴趣，不过我还是把这道菜的食谱交给你吧。拿着吧，对了，一定要记得趁着新鲜的时候把它吃了!', '我已经准备好要做血肠了，你把原料拿来了吗?', '', '去洛克莫丹找灰爪山的维德拉·壁炉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (420, '森内尔的观察站', '隧道里的穴居人非常具有攻击性，它们会毫不犹豫地对隧道中的过客发动袭击。不过你看起来挺结实的，应该不会有什么危险。$b$b方向？如果你要找森内尔，就到卡拉诺斯去吧。$b$b一直穿过隧道，出去之后沿着大路向前走，没几步就到卡拉诺斯了。', '把格瑞林的报告交给卡拉诺斯的森内尔·白须。', '这是什么?哦，我兄弟的报告。嗯……$B$B我让他不要动辄就“以国王的名义”，可他就是不听。参议院中肯定会有些家伙对此不满的，不过我想应该没什么大问题，反正他们也从来没有对什么东西满意过，哈哈!$B$B不管怎样，我想我也应该给铁炉堡提交一份报告，不过我承认也许现在有些迟了。这该死的冷天。$B$B如果你有兴趣的话，我有些工作要交给你去做。', '你好啊，要喝一杯吗?这大冷的天，除了喝酒还能干什么呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (421, '证明你的价值', '希尔瓦娜斯主人已经授命瓦里玛萨斯大人全权负责征服南方的人类和矮人的领土。$b$b但阿鲁高那个蠢货——过去他是达拉然的大骗子，现在他是影牙城堡里一只中了诅咒的困兽——他那不计后果的魔法给银松森林里那座极具战略意义的要塞带来了一场大浩劫。$b$b我需要一些拥有优秀战斗技巧的人帮我把阿鲁高\r\n留下的烂摊子给收拾掉。杀死5只月怒白头狼人以证明你的实力吧，这些野兽一般都在山脚下的道路两旁游荡。', '瑟伯切尔的达拉尔·道恩维沃尔要求你杀死5只月怒白头狼人。', '你干得很好，$C。显然在将来的某一天，在我准备消除阿鲁高强加给银松森林的诅咒时，你会提供很大的帮助。', '如果你想向我证明自己的能力，就必须先杀死5只月怒白头狼人。完成这件任务之后，我将视你的能力来为你指派下一步的任务。', '', '去银松森林找瑟伯切尔的达拉尔·道恩维沃尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (422, '阿鲁高的愚行', '阿鲁高这样一个施法能力比一张纸还要浅薄的家伙居然能够得到肯瑞托的承认，这让我实在难以想象。$b$b现在最重要的是，搞清楚阿鲁高究竟使用了什么魔法，这样一来我才能对付他，并为黑暗女士平定银松森林。$b$b阿鲁高曾经住在桥北的麦田旁，一名亡灵哨兵回报说，他发现了阿鲁高拥有的几本法术书，但无法偷取它们。把其中一本名叫《阿鲁高的拯救》的法术书从其它书里找出来，并带回来给我。', '为瑟伯切尔的达拉尔·道恩维沃尔找回《阿鲁高的拯救》。', '这正是我正要找的法术，$C。如果你在以后为黑暗女王效力的过程中仍能像现在这样干净俐落的话，你无疑会在被遗忘者中拥有一个美好的未来。', '在我知道我们在跟什么样的敌人作战之前，$C，我得先得研究一下《阿鲁高的拯救》。把它给我带回来，不然我就只好找个更能干的手下了。', '', '去银松森林找瑟伯切尔的达拉尔·道恩维沃尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (423, '阿鲁高的愚行', '在我研究过阿鲁高的书以后，我最坏的设想不幸被证实了。肯瑞托竟在那个连给达拉然的法师们扫屋子都不配的家伙干出那种愚昧行径的时候完全不闻不问，一群蠢货！$b$b阿鲁高使用了附有魔法的物品来加强他薄弱的施法能力。我需要尽快研究一下这些物品。去杀掉一些月怒暴食者和月怒魔魂狼人，收集他们身上带着的魔法镣铐供我研究之用。这些污秽的生物在北边和东边到处都是。', '给瑟伯切尔的达拉尔·道恩维沃尔带回6副暴食者镣铐和3副魔魂镣铐。', '我希望能从这少量的样本中汲取到足够的能量，也许我本应让你多搞些镣铐来的。$B$B无论如何，你在收集这些物品的过程中证明了自己的实力，$C。', '在我了解当前的形势并策划出一个用以对付阿鲁高的最终解决方案之前，我先得需要一些暴食者镣铐和黑暗之魂镣铐以作研究之用。赶快去执行你的任务，杀掉月怒暴食者和月怒黑暗之魂狼人，直到你收集齐了我要的东西为止。', '', '去银松森林找瑟伯切尔的达拉尔·道恩维沃尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (424, '阿鲁高的愚行', '看来想揭开隐藏在阿鲁高所用的巫术中的黑暗秘密并不简单，这比我想象中要花掉的时间多出很多。$b$b但与此同时，我需要你来帮忙处理一下我们的亡灵哨兵发现的一个小问题。似乎阿鲁高的魔法已经控制了东南方山中的埃利姆矿洞。$b$b这座矿洞对瓦里玛萨斯大人的推进有着非常重要的意义。$b$b我希望你能干掉矿洞里的工头，白毛狼人格瑞姆森。只要他一死，矿洞就是我们的了。', '杀死白毛狼人格瑞姆森，把他的头带给瑟伯切尔的达拉尔·道恩维沃尔。', '非常好。在我们的军队攻占银松森林乃至进军艾泽拉斯的过程中，那座矿坑中将为他们提供大量的资源。', '你干掉苍白的格瑞姆森了吗?如果我们没有完成瓦里玛萨斯大人下达的命令，他一定会不高兴的。', '', '去银松森林找瑟伯切尔的达拉尔·道恩维沃尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (425, '邪恶的伊瓦', '我正在和哥哥奎恩执行侦察银松森林的任务，并准备向最高执行官哈德瑞克复命。但我们进行得不太顺利——我们穿过这座农庄的时候，被食尸鬼伊瓦袭击了。$B$B我们从伊瓦那里逃了出来，但他还是重创了奎恩。喝了你给他的药水以后，哥哥正逐渐痊愈，但这段时间里伊瓦仍可能会过来。$B$B杀死伊瓦，以保证奎恩有足够的时间复原吧。伊瓦一般都躲在谷仓那里，在我放松警戒的时候它就会开始行动。', '杀死邪恶的伊瓦，并将伊瓦的徽记带给伊瓦农庄的兰妮·尤瑞克。', '啊，多谢。我对你真是感激不禁，$N。$B$B我会在给上级的报告中提到你的。', '你杀掉邪恶的伊瓦了吗?如果你不愿意为我和我哥哥做这件事，就为被遗忘者做这件事吧。', '', '去找银松森林的兰妮·尤瑞克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (426, '磨坊告急', '天灾军团正试图在阿加曼德磨坊那边创建起一座前哨基地。如果他们得逞了，那么他们在提瑞斯法的军事行动将得到有利的支持。$B$B上头已经发话下来了，必须将磨坊那边的天灾军团势力全部清除干净。$B$B到磨坊那边去，从断骨士兵和碎颅士兵身上收集锯齿肋骨，再从暗眼骷髅法师身上收集焦黑的徽记。$B$B你只需沿着道路一直向西走，过桥以后在第一个岔路口转向北就行了。当你看到风车的时候，战斗随时都会开始。', '收集5根锯齿肋骨和3个焦黑的徽记，然后向布瑞尔的亡灵卫兵迪林格尔回报。', '你为战争尽了自己的一份力，这一点我们已经感觉到了，$N。我不会因为你尽了自己的义务而感谢你，但所有提里斯法的亡灵卫兵都会记住你的名字。', '与天灾军团的全面战争已经开始了，$N。尽你所能将那群巫妖王的傀儡全部赶回瘟疫之地去!', '', '去提瑞斯法林地找布瑞尔的亡灵卫兵迪林格尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (427, '与血色十字军的战争', '执行官阿伦大人提供给我们的文件中指出，我们将无法避免与那些卑劣的血色十字军进行一场战争。我们已经知道了他们穿越提瑞斯法林地所走的那条小径的确切位置。$b$b但亡灵卫兵还有其它艰巨的任务，巫妖王的军队正在夜色中逐渐壮大起来。我们需要一些像你这样的志愿者来把那群血色十字军送进坟墓。$b$b顺着镇外的道路向西走，穿过索利丹农场到废塔那里去，杀死10名血色十字军战士。以此来证明你有足够的能力为黑暗女王陛下服务。', '布瑞尔的执行官塞加德要求你杀掉10名血色战士。', '非常优秀，$C。不可否认的，你有着非常优秀的战斗技巧。', '如果你想在黑暗女王面前证明自己，就去杀掉10名血色十字军战士，$C。', '', '去提瑞斯法林地找布瑞尔的执行官塞加德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (429, '荒野之心', '我的哥哥奎恩被食尸鬼伊瓦打成了重伤，我不知道在没有魔法帮助的情况下，他是否还能痊愈。尽管我不是一个药剂师，但我知道我们的药剂师能用变色的狼心制作治疗药水。$B$B帮我收集一些心脏并带给南边坟场的药剂师伦弗利尔，然后把做好的药水带回来。$B$B这附近和东边的玛尔丁果园之间有不少座狼在到处游荡。', '收集6颗变色的狼心，把它们交给瑟伯切尔的药剂师伦弗利尔。', '<伦弗利尔拿起这些心脏。>$B$B听说我们的亡灵哨兵没能完成他们的任务，这真让人困扰。$B$B希望不要再出现这样的失败。$B$B我马上就可以把药水给你，不过，这是配方―如果那些亡灵哨兵需要更多的药水，或许你自己就能帮他们调制了。', '我的时间紧迫，$C，黑暗女王交给了我一件极其重要的任务。', '', '去银松森林找瑟伯切尔的药剂师伦弗利尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (430, '回到奎恩身旁', '这就是那种能帮助奎恩·尤瑞克复原的药水。$B$B现在，如果你没什么事的话，我就先失陪了。我还有重要的工作要继续……', '将奎恩的药水带给瑟伯切尔北方伊瓦农场的奎恩·尤瑞克。', '<奎恩接过药水并一饮而尽。>$B$B啊，我感觉到它的效力了。我想我很快就可以动弹了。$B$B你帮了我一个大忙，$N。', '我妹妹说你是来帮助我们的。这是真的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (432, '该死的穴居人！', '那些该死的穴居人，它们把我的工作地点变成了一片废墟！看那里，又一个火药桶！$b$b啊啊啊啊啊，我真想钻到地底下去扭断它们那豆芽一样的脖子！我要把它们赶尽杀绝！$b$b即使这样也无法消除我的愤怒……它们留给了我什么？什么也没有！$b$b我要亲手杀了它们，不过我的胳膊已经不再那么有力了！到采石场去，干掉那帮该死的家伙！我会奖赏你的！只要你去干掉它们！', '在古博拉采掘场里替工头乔尼·石眉杀死6个石腭击颅者。', '嗯，你终于让我感觉好些了……$B$B但是，只要它们还有一个活着，我就高兴不起来!它们全都得去死!', 'It makes me so mad! Grrr...', '', '去找丹莫罗的工头乔尼·石眉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (433, '公众之仆', '作为参议院与探险者协会的成员，我已经开始过问这个地区穴居人泛滥的事情了。$b$b它们把古博拉采掘场搞了个天翻地复，而且它们的这种行为看起来毫无理由。当我们在矿井中挖掘矿石的时候，它们突然出现，毁坏了我们的设备，赶走了我们的矿工。我们别无选择，只有杀光他们，之后我们才能重建工地并继续工作。$b$b如果你愿意帮助我解决掉那些穴居人的话，我会很乐意报答你的。', '在古博拉采掘场里替参议员梅尔·圣石杀死10个石腭断骨者。', '这只是个开始。希望我们能利用这段时间，赶紧去找一些巡山人来保护这个地区。然后我们就可以开始重建基础设施，让矿工们回来工作。$B$B谢谢你的帮助，$N。', '如果我们能把古博拉采掘场里的石腭怪赶走，这将会是，我们完全解决这个威胁所需探取的诸多步骤中的第一步。', '', '去找丹莫罗的参议员梅尔·圣石。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (434, '伏击！', '等我做好间谍机器人的伪装，他会进去和莱斯科瓦谈话。守卫会让他进去的。$B$B在你帮我准备材料的同时，我会暗示马尔松，让他再次和莱斯科瓦会面，我甚至会给他一点假消息，好让他对此深信不疑。$B$B接下来，莱斯科瓦就会让他的卫兵解散，然后在花园里等马尔松。等你听到他们谈起迪菲亚兄弟会的时候就采取行动。你要把他们两个都干掉。听懂了吗？$B$B当你完成任务之后，尽快向提亚斯回报。', '等待葛瑞格·莱斯科瓦公爵和沉默之刃马尔松在花园里的对话结束，杀死他们两个，之后向暴风城的提亚斯回报。', '任务完成了?很好。非常感谢你，$N。你已经完全证明了自己的价值。我会时刻关注你的进步。$B$B以后你行事最好也像这次一样干净俐落。', '怎么样了，$N?泰里恩那边一切顺利吧?他赞扬了我对形势的正确把握，另外我已经帮他把马尔松骗到了皇宫里。$B$B暴风城里的很多人都讨厌马尔松，而且这些人中的大部分都是我的好友。没有人敢惹我的朋友……除非他不想活了。$B$B可惜的是，肖尔和军情七处会因此得到不少好处，不过并不是每个计画都能做到十全十美的。', '窃听莱斯科瓦和马尔松的对话', '去找暴风城的埃林·提亚斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (437, '亡者农场', '我们在银松森林的探子回报说，腐皮豺狼人在北边的一处名叫亡者农场的地方创建了一个基地。我们已经派遣了小股突袭部队去对付他们，但每次他们都能得到女妖奈塔拉什的增援，每次都是她的魔法击溃了我们的部队。$B$B我们必须杀掉奈塔拉什。$B$B到亡者农场去杀掉那里的腐皮豺狼人。如果没有看到奈塔拉什的话，就继续屠杀腐皮豺狼人直到她出现为止，然后击败她。$B$B她的灵魂将会变成尘土。把这些尘土带回来，作为你杀死了她的证明。', '清剿亡者农场的腐皮豺狼人。$B$B当奈塔拉什出现时，把她也杀掉。$B$B将奈塔拉什的灵魂带给瑟伯切尔的高级执行官哈德瑞克。', '我听说你成功地消灭了腐皮豺狼人，$N，这些尘土证明了奈塔拉什的死。$B$B天灾军团今天可是损失惨重，你为被遗忘者做出了重要的贡献。', '你击败了奈塔拉什了吗，$N?我们若要成功地击败腐皮豺狼人，就必须先干掉这个女妖。', '进入亡者农场。', '去银松森林找瑟伯切尔的高级执行官哈德瑞克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (439, '线索', '在一大堆尸体中间，有一只裸露的手。这是一只女人的手，虽因瘟疫而导致皮肤上布满红痘，但仍然十分白皙。$B$B她的手上戴着一只戒指。你从尸体的手上取下这只戒指，看到戒指内环中有一道铭文：$B$B“赠予黛丽娅”', '将黛丽娅的戒指带给瑟伯切尔的高级执行官哈德瑞克。', '你说这个戒指是在一个可能是刚被杀的女人身上找到的。$B$B那附近唯一可能有尸体的地方只能是提里斯法的公墓了。腐皮豺狼人一定是将尸体拖到芬里斯岛去了!', '$N，你回来了。你的调查有结果了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (440, '黛丽娅的戒指', '如果你想找到黛丽娅的丈夫或情人，也就是送给她戒指的那个人的话……去找布瑞尔的执政官塞弗伦谈谈吧。他或许拥有最近的死亡记录，当然，如果你走运的话，还能发现谁是黛丽娅。$B$B但我也不抱希望。无论给她戒指的人是谁，现在恐怕也已经死了。如果他成了亡灵，也就不会再关心黛丽娅了。', '将黛丽娅的戒指带给布瑞尔的执政官塞弗伦。', '不久前这里是住过一个叫黛丽娅的。她应该被葬在公墓里，不过，如果你说的是真的，她的尸体或许已经被腐皮豺狼人偷走带去银松森林了。$B$B那群腐皮豺狼人跟天灾军团一样，一定要被彻底消灭。我相信你所做的事情会帮我们最终实现这个目标。', '你好，$N。来布瑞尔有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (441, '拉林夫与幽暗城', '黛丽娅有个丈夫叫拉林夫，他现在居住在幽暗城。如果居住在布瑞尔的这位黛丽娅就是这只戒指的主人，想必他应该知道。$B$B拉林夫就在幽暗城的贸易区。', '把黛丽娅的戒指交给拉林夫。', '是的，这正是我妻子的戒指。她的命运，和那些所有没能忍耐着度过这段艰难时世的人一样。我对她的死没有什么想法，她的尸体失踪了又怎样。$B$B我早就丧失了这些多馀的情感了。但复仇的欲望却仍在我已死的心中燃烧着，$N。', '我认识你吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (442, '突袭芬里斯岛', '现在是把天灾军团彻底赶出银松森林的时候了。$B$B你必须再去一次那个岛，杀死图勒·鸦爪，把他的徽记提来见我！$B$B这个任务非常危险，但是你也应该知道它的重要性，$N。所以你只能成功，不能失败。', '将图勒的徽记带回给瑟伯切尔的高级执行官哈德瑞克。', '图勒.鸦爪的死可不是件小事，$N。药剂师伦弗利尔告诉我，在你杀死图勒的时候，芬里斯堡中所释放出的魔法能量就连远在瑟伯切尔的他都能感应到。$B$B你的行动无疑提高了被遗忘者的地位。对我们而言，你也更加重要了。', '我们不能容忍天灾军团的势力占据银松森林的任何一寸土地，$N。杀死图勒后再回来找我。', '', '去银松森林找瑟伯切尔的高级执行官哈德瑞克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (443, '腐皮豺狼人的脓液', '在我们对芬里斯岛展开一次突袭行动之前，我们必须得弄清楚谁是腐皮豺狼人背后的真正主人，我们的药剂师们相信它们的体内发生了某种神秘的变化。$B$B到破旧渡口东边的芬里斯岛去，收集一些腐皮豺狼人身上流出的脓血，然后把脓液交给瑟伯切尔外的药剂师伦弗利尔。', '给瑟伯切尔的药剂师伦弗利尔带去8瓶腐皮豺狼人的脓液。', '好的很。这些脓液会帮助我们了解腐皮豺狼人的自然特性，并帮助我们找出它们的弱点……$B$B……如果他们有弱点的话……', '你搞到腐皮豺狼人的脓液了吗，$N?', '', '去银松森林找瑟伯切尔的药剂师伦弗利尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (444, '腐皮豺狼人的产生', '我还原了你带给我的脓液，并把它们分离成了一些基本成分。我的发现还不是结论性的，但我可以肯定恶魔法术和死灵法术在这脓液的产生过程中起了极其重要的作用。$B$B在我继续研究脓液的同时，我希望你能给幽暗城的比索·埃斯沙德带些样本过去。比索虽然不是一名药剂师，但他在魔法方面的学识将会帮助我们揭开这些腐皮豺狼人的秘密。$B$B快去吧，比索就住在幽暗城的法师区。', '将脓液样本交给幽暗城的比索·埃斯沙德。', '这种物质是由某种连我也很久都没有见过的强力法术所制成的……$B$B等等―我得施展一个预言法术来看看。', '我得完全集中精力才能进行研究。所以你最好别为些琐碎的事情打扰我。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (445, '给银松森林送信', '如今，对我们这些希尔瓦娜斯女士的仆从来说，时间就是一切。显然现在你也非常清楚这一点。$b$b身为皇家药剂师学会的一员，我必须将我的研究成果与同事们分享，只有依靠所有会员的共同努力，我们才能向黑暗女王陛下提供她最期望的新瘟疫。$b$b将这些报告带给住在银松森林瑟伯切尔里的药剂师伦弗利尔，从布瑞尔向南走，到了幽暗城再转往西南就可以了。', '将药剂师乔汉的研究成果带给银松森林的药剂师伦弗利尔。', '啊，乔汉送来了他的报告，太好了。由于银松森林这边发生的事情实在是太多了，我几乎把洛丹伦和提瑞斯法林地那边来的报告都全丢在了一边。这倒提醒了我，我得把这些来自各地的样本赶紧送到亡域去。$B$B但你恐怕得先在这里待一段时间，替我做点跑腿打杂的事。好好在银松森林里见识见识吧，$N。我们这儿用得着\r\n像你这样能干的$C。', '找我有什么事吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (446, '图勒·鸦爪', '这种脓液是我以前的一个同僚图勒·鸦爪制成的。在大战之前，他是一个有着大好前途的年轻法师，但在巫妖王的势力崛起之后，他背叛了他的朋友与兄弟，加入了天灾军团。$B$B我没料到他还活着，更没有想到的是，原来是他在领导腐皮豺狼人与我们对抗。$B$B我对他的许多法术都有所了解，应该能帮忙调制出一种能击败他们的药剂。把这个卷轴交给药剂师伦弗利尔，卷轴上面写着调制药水所需要的咒语。', '把比索的卷轴交给银松森林中的药剂师伦弗利尔。', '这卷轴中蕴涵着强大的魔法。我从来没有在制造药剂时使用如此巨大的能量……这将是一瓶可怕的药剂，它应该会在你刺杀躲在芬里斯岛上要塞中的图勒时起到重要的作用。', '你好，$N。比索说了些什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (447, '奇妙的配方', '天灾军团的威胁越来越严重。不过，只要我的药剂成功，我们就可以一劳永逸地消灭这些邪恶的存在。$b$b我的研究已经证明，将灰熊心脏中提取出的药素和蜘蛛血混合在一起，就可以制成一种让天灾军团丧失邪恶力量的药剂。从西北方的粘丝洞中的蜘蛛身上和银松森林中游荡着的熊身上采集一些样本回来，然后把它们送给幽暗城皇家药剂师学会里的大药剂师法拉尼尔。', '收集6个灰熊的心脏和6份粘稠的血液样本，并将这些东西送给幽暗城的大药剂师法拉尼尔。', '伦弗利尔派你来找我真是找对人了，$N。这些样本对完成药剂将有很大的帮助，我会立刻开始研究它们所带的毒性和传染性。$B', '你好，$C。你来拜访皇家药剂师学会有什么事吗?', '', '去找幽暗城炼金房的大药剂师法拉尼尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (449, '亡灵哨兵的报告', '尽管奎恩的伤基本已经好了，但我仍想尽可能快地把报告呈送给高级执行官哈德瑞克。这里面的情报对被遗忘者来说十分重要，它将关系到我们在整个银松森林的统治地位。', '将亡灵哨兵的报告的报告交给瑟伯切尔的高级执行官哈德瑞克。', '我还没有对天灾军团在银松森林的影响以及亡灵哨兵侦察过程中所碰到的麻烦进行过统计。$B$B感谢你帮助我们的亡灵哨兵，$N。你将受到表彰。', '你找到那两个亡灵哨兵了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (450, '奇妙的配方', '其实你还能为皇家药剂师学会再做一些事情，$N。$b$b当初阿鲁高在整个森林中施展了他那可恶的魔法时，我们当中一位最有前途的成员——药剂师伯纳德，也被他诅咒了。现在伯纳德已经变成了一个忠于阿鲁高的傀儡。即使这样伯纳德的研究成果可能对我们非常有用，因为他在多年以前曾经研究过一种遏制天灾军团的药剂。$b$b将伯纳德的日记从他在焚木村旅店中的研究室里找出来，然后把日记交给药剂师伦弗利尔。', '从焚木村的旅店中找到伯纳德的日记，把它交给瑟伯切尔的药剂师伦弗利尔。', '伯纳德的日记!你真是太勇敢了，$N。现在让我看看伯纳德在疯掉之前都做了些什么……', '你回来了，$N。', '', '去银松森林找瑟伯切尔的药剂师伦弗利尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (451, '奇妙的配方', '根据博拉尔德的研究日记，采自湖岸爬行者和潜藏者身上的苔藓会对我们制造出这种药剂大有助益。这些野兽就栖息于东边的洛丹米尔湖中的群岛上。$b$b他还提到曾在一只邪鳍鱼人身上发现了一种非常稀有的硬瘤，显然这种瘤很难得到，博拉尔德也只找到了一个。$b$b收集一些苔藓和那种稀有的瘤，把它们带给幽暗城的大药剂师法拉尼尔。', '收集6份湖岸爬行者苔藓的样本、6份湖岸潜藏者苔藓的样本和1块硬瘤，把它们交给幽暗城的大药剂师法拉尼尔。', '皇家药剂师学会失去了博拉尔德实在是太可惜了。但通过你的努力，还有药剂师伦弗利尔对博拉尔德留下的东西的详细研究，我们仍然能为黑暗女王帮忙。$B$B我们正在做一件伟大的事业，$N。如果你不是那么擅长作战就好了，那样的话，我一定会举荐你进入学会的。', '来幽暗城有什么事，$N?', '', '去找幽暗城炼金房的大药剂师法拉尼尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (453, '搜寻乌鸦岭', '祝你好运，$N。我希望你能找到这个家伙，也希望他还活着。$B$B外面可没有夜色镇这么安全，他可能早就成了野兽的猎物。', '找到那个模糊的人影。你的线索：$B$B他不是夜色镇的本地人。$B$B他是个紧张而敏感的人。$B$B他离开夜色镇往西边去了。', '<基特斯叹了口气…>$B$B是的，我就是那本书的作者。你终于找到我了么……$B$B如果你读了那本日记的话…你只了解到了事实的一半!', '你是谁??别过来!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (455, '丹奥加兹告急', '龙喉氏族的兽人在湿地有了一处巢穴，现在他们的势力已经快扩展到丹奥加斯了！我们可绝不能让他们在这里立足，不然，我们在湿地唯一的港口与要塞——米奈希尔港与洛克莫丹的联系将会被切断。$B$B穿越丹奥加兹到湿地那边去，向米奈希尔港的瓦斯塔格·铁腭报到，路上顺便杀它几个兽人玩玩！$B$B米奈希尔就在丹奥加兹的另一边，只要先顺着路向北，然后在岔路口转向西边就是。$B$B我们寄希望于你，$N。可别让我们失望。', '翻越丹奥加兹。$B$B杀死8个龙喉斥候和6个龙喉步兵。$B$B向米奈希尔港的瓦斯塔格·铁腭报到。', '你的报告里怎么全都是些坏消息!$B$B我觉得那些龙喉兽人们一定是想向奥加兹推进。过去龙喉氏族一直是躲在深山里，从不与外界接触。到底是什么迫使他们要进入奥加兹，这就不得而知了……$B$B谢谢你，$N。我们可能还会需要你来帮忙对付那些兽人。', '你是从洛克莫丹来的?奥加兹隘口那边的兽人有什么动向?', '翻越丹奥加兹', '去湿地找米奈希尔港的瓦斯塔格·铁腭。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (456, '自然的平衡', '你好，$N。我是管理员伊尔萨莱恩。我的职责是维护幽影谷一带的自然平衡。$b$b今年的春雨似乎比往年来得都要连绵不绝，这导致了森林中某些动物的过度繁殖，而其它动物就遭了殃。$b$b其中，夜刃豹和草刺野猪的族群已经过于庞大了，幽影谷无法为它们提供更多的食物。去吧，年轻的$c，去减少野猪和夜刃豹的数量，以保证自然的和谐。', '杀死4只夜刃豹幼崽和4只草刺野猪幼崽，然后向管理员伊尔萨莱恩复命。', '你很好的履行了职责，$N。', '还有活儿没干完呢，$N。等你削减了夜刃猎豹和草刺野猪的数量后再回来找我。', '', '去泰达希尔找幽影谷的管理员伊尔萨莱恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (457, '自然的平衡', '削减幽影谷地中生物幼兽的数量是一个很好的开始，$N，但这还远远不够。$b$b如果问题不能得到根本解决的话，森林中的资源还是很快就会被耗尽的。杀死某些生物对于生长在这片土地上的所有生物来说都是有益的。为了自然的平衡，到森林里去清除一些癞皮夜刃豹和一些草刺野猪吧。', '管理员伊尔萨莱恩要求你杀死5只癞皮夜刃豹和5只草刺野猪。', '你很好的诠释了对大自然的贡献，$N。像你这样年轻的$C定能前程似锦。', '你的活儿没干完呢，$N。等你杀掉了7头癞皮夜刃豹和草刺野猪后再来找我。', '', '去泰达希尔找幽影谷的管理员伊尔萨莱恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (459, '森林守护者', '一些邪恶的事物正在泰达希尔的森林中滋生着。看看那些原先性情温和的熊怪们居住的地方吧。他们放弃了自己的家园，聚集在了所谓的脊骨部落的名下。$b$b一定是那些腐朽毒恶的魔苔的瘴气造成了这种变异。小劣魔和劣魔也在幽影谷滋生开来，惊扰着这里的居民。$b$b去和这些小劣魔和劣魔战斗吧，$N，观察一下他们是否真的是受了魔苔的影响。', '收集8块魔苔，把它们交给塔琳德拉。', '你为幽影谷中的生灵所做的一切都值得嘉奖，$N.$B$B尽管如此，我还是高兴不起来，因为你证实了我所担忧的事。如果劣魔是因为被魔苔影响而变成这样的话，熊怪们会变成什么样子也是可以想象的了。$B$B你必须到多兰纳尔去，能干的$C，你得去找知识渊博的德鲁伊阿斯瑞达斯·熊皮。他和我们一样关心森林的安宁。', '为了证明我的怀疑，$N，请交给我8块魔苔。', '', '去泰达希尔找幽影谷的塔琳德拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (460, '支离破碎', '你看上去跟那帮腐皮豺狼人不一样，这真好。我都快绝望了……$B$B我叫奥拉瑞克，过去曾是图勒的大管家兼保镖。他用他的魔法“保护”了我，使我免受“亡灵疫病”的影响，但他的魔法也让我变成了这个半死不活的样子。而且，自从图勒创造了那群该死的腐皮豺狼人之后，他竟然拿走了我的徽记……还把它给那群豺狼人当球踢！$B$B拜托，把我带到芬里斯城堡的马厩旁……', '将奥拉瑞克的徽记带到他的坟墓旁。', '多谢，$N。我刚才还在担心豺狼人们也许会把我的尸体给肢解了，还好他们没这么干。', '这坟看起来像是随便挖的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (461, '密室', '我知道在这城堡中有间密室，密室里藏着一件对图勒和他的同伙们来说很宝贵的东西，也许那里面也有些对你很有用的东西。把我带到那里去！$B$B这密室就在城堡西南的塔里，在一处满是灰尘的柜子后面。$B$B带上我的身子，但是不要靴子…这靴子就没合适过……', '将奥拉瑞克带到密室去。', '就是这儿，门还开着。把我留在这里。我在这座城堡里度过了我一生中最美好的时节，在这里安息自然也是最好的。$B$B把这密室关好―我不想让那帮腐皮豺狼人找到我。$B$B对了，拿着这个吧。这是你应得的。', '就是这儿!没错!让我靠近点!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (464, '龙喉战旗', '按理说，龙喉氏族的兽人应该已经在第二次兽人战争中全部被消灭干净了呀。那时，他们失去了对红龙的控制，而被奴役了许久的红龙对兽人极度仇恨，所以就到处猎杀他们。只有一小部分龙喉兽人从格瑞姆巴托逃了出来，躲进了维尔加挖掘场东边的山里。$B$B现在他们的族群似乎又恢复了兴盛，有线报说他们在米奈希尔的东北方创建了一座营地。$B$B我们要你去进攻那座营地，并带回一些战旗作为功勋评定的证据。', '给斯托菲队长带回8面龙喉战旗。', '干得漂亮，$N。龙喉兽人比起当初还有红龙助阵的时候可要差劲多了，但他们仍然是一群非常棘手的敌人。$B$B龙喉兽人的领袖名叫纳克罗什，他是前酋长耐克鲁斯的儿子。耐克鲁斯当初使用某种强大的魔法控制了许多红龙，然而有一天魔法失效了……那些龙自然不是很高兴……于是……$B$B耐克鲁斯被红龙生吞了，而他的儿子则发誓一定要猎杀当初夺走了他父亲性命的那几条龙，以求复仇。', '你与龙喉兽人交战过了吗?', '', '去湿地找米奈希尔港的斯托菲队长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (465, '纳克罗什的优势', '当你在和那些龙喉氏族的兽人作战时，我们又获得了更多有关他们的作战计划的情报。$B$B首先是一个坏消息，纳克罗什正在大量地建造投石车，计划一举攻陷米奈希尔！还有一个好消息，经过在丹奥加兹一带的艰苦奋战，我们已经把他们的援军彻底挡了回去！$B$B现在你所要做的就是毁掉那些投石车，它们当前仍被停放在龙喉氏族的营地里。$B$B给，带上这些火绒。你得先在营地里杀出一条血路，找到那些投石车，然后再用这些火绒烧了它们。$B$B完成这一切之后，就去找纳克罗什，把他给干掉。我们必须彻底地将这些龙喉氏族的兽人消灭掉！', '摧毁所有的龙喉投石车。', '你将一些火绒放在了一辆投石车上，然后马上用火石打着了火。$B$B火苗迅速蔓延开来，吞没了整辆投石车。', '那些投石车正等你呢，把它们烧成灰烬!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (466, '火岩矿石', '我听说最近在湿地一带发现了一种特别稀有的矿石，大家管它叫火岩，那矿洞就在奥加兹大门西北方的一处洞穴里。火岩矿石非常不稳定，它很容易爆炸，但我敢说，如果加工方法正确的话，它就可以用来制作威力强大的炮弹！$B$B给我搞一些火岩矿石的样本来，我可以去找个够胆的家伙来对它进行实验。$B$B哦，要想采集到这些矿石的话，你可得懂点采矿技术才行。如果你完全不懂的话，那么……就找个懂行的朋友一起去吧！', '给丹莫罗的驾驶员迪恩·石轮带回6份火岩矿石。', '你搞到矿石了!非常好，$N!我会找个合适的人以正确的方法处理它的。真希望他别把自己给炸飞了!', '矿石在哪儿，$N?!', '', '去丹莫罗找钢架补给站的驾驶员迪恩·石轮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (469, '日常供货', '你好，旅行者！$b$b你是不是要去米奈希尔港？如果不是的话，我建议你就留在这里吧，你要是想买点东西啊，喝一杯啊，或者放松放松神经什么的话，这里就再合适不过啦。$b$b如果你确实是要去米奈希尔的话，那么……我想……你应该不会介意把这捆鳄鱼皮捎给皮匠詹姆斯·哈洛兰吧？$b$b我本来是想自己亲自走一趟的，但我那个在城里的老婆最近正发脾气呢，我实在不想马上就见到她，能拖多久就拖多久。', '将这捆鳄鱼皮带给米奈希尔港的皮匠詹姆斯·哈洛兰。', '嗯，这是埃纳尔让你送来的吗?他已经一个多礼拜没有亲自给我送皮过来了。肯定是跟他老婆又闹别扭了!$B$B或许我这两天得让我老婆去和塞达谈谈，给他们调解调解才行……', '欢迎光临，$C。你想要点什么?一双合脚的靴子，还是一些上好的皮革?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (470, '搜寻软泥怪', '我每周都要对西北方山脚下的铁须之墓进行例行的拜访。然而，上次过去的时候，我竟然遭到了那些可怖的软泥怪的攻击，我当时自然是吓坏了。$b$b我身上也没带武器，只好抓起背包丢它们，不过那完全没有用！软泥怪很轻松地把我的背包给吞掉了……不过，幸运的是，这也为我争取到了逃跑的时间。$b$b但是我现在很需要包里的东西！$b$b我已经忘记把包扔进哪只软泥怪里了，它们看起来都是一模一样的！所以呢，你恐怕得多杀个几只才能找到我的包。铁须之墓就在东北方，丹奥加斯附近。多谢你啦！', '铁须之墓中的某只软泥怪身上有塞达的背包，夺回背包，把它送还给米奈希尔港的塞达。', '啊，太感谢你啦，$N!我还以为我再也拿不回这些东西了!$B$B<她连沾满背包的泥浆都没去掉，就迅速地打开了它，并把里面的东西都倒在了地上。>$B$B嗯，我不会再用这个包了，把它洗洗，也许你能用得到。', '你找到我的包了吗?', '', '去湿地找米奈希尔港的塞达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (471, '学徒的职责', '我把我的学徒派到了沼泽那边去，希望他能给我搞到一些着名的巨型鳄鱼的皮回来。然而他一直都没回来，我只好亲自去找他……怎么说呢，反正我当时看到了一些比较惨的场面。$b$b医生说他很快就会恢复健康的，但现在，我仍然急需鳄鱼皮！$b$b……要是你能帮我杀几条这种凶猛残忍的大鳄鱼，从它们身上给我剥几张皮下来，我会非常高兴的。沿着海岸北上，走过了那些鱼人搭建的简陋小屋之后就能找到鳄鱼了。', '为米奈希尔港的詹姆斯·哈洛兰带回6张巨型鳄鱼的皮。', '嗯……如果你有兴趣当我的学徒的话，就跟着我混吧，如何?$B$B哈!别怕别怕，开个小玩笑么。你来当我的学徒的话，年纪大了点。不过，你打来的这些皮不错，我会好好利用的。', '那可怜的小家伙对我来说就跟亲儿子一样。他只剩一条腿了，这让他以后可怎么活呀。$B$B啊，$N，事情怎么样啦?搞到那些皮了没?', '', '去湿地找米奈希尔港的詹姆斯·哈洛兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (474, '击败纳克罗什', '现在所有的投石车都被烧掉了，找到纳克罗什酋长，把他干掉。', '杀掉纳克罗什酋长。$B$B将纳克罗什的徽记交给斯托菲队长。', '你办事真俐落，$N。龙喉氏族的兽人们这回又遭受了一次沉重的打击，他们可能会就此一蹶不振。而且，那些投石车一毁，米奈希尔港也安全了。$B$B你实在是一位非常优秀的$C，铁炉堡王国一定会为你的忠心而支付给你公道的酬劳。', '你杀掉纳克罗什了吗?', '', '去湿地找米奈希尔港的斯托菲队长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (478, '地图与符记', '<你迅速从箱子里中拿起了坠饰并将箱子重新盖好。>', '将这个奇怪的坠饰交给瑟伯切尔的暗影牧师奥利斯特。', '地图和这个……坠饰，就这些吗?真有趣。$B$B显然达拉然的巫师们一直待在安伯米尔是有些原因的，但是现在我还是不知道他们到底要做些什么。$B$B或许达拉尔知道些什么。', '你有什么发现吗，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (479, '调查安伯米尔', '达拉尔正在尝试着定位出达拉然法师们施法时的能量流向。现在，我们必须要尽我们一切努力来暂缓他们的进程……$b$b那些咒术师、法师和保卫者恐怕会拼死保护坠饰。你必须清除掉这些阻碍，并把饰物抢到手。$b$b沿着大路向南走，在岔路口转向东边就可以到安伯米尔了。', '为瑟伯切尔的暗影牧师奥利斯特抢到8个达拉然坠饰。', '尽管已经失败了好几次，但达拉尔还是发现了一个位于很远处的地方有着强大的魔法波动。$B$B某个强大的巫师正在那里引导着魔法能量，我们必须马上阻止他。', '我们必须迅速行动，彻底破坏掉他们的计画，否则，我们将失去整个银松森林的控制权。', '', '去银松森林找瑟伯切尔的暗影牧师奥利斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (480, '法师的头领', '一位具有强大法力的大法师正在监管着启动节点的行动。在当前的形势下，我们只有杀死那个大法师才有可能阻止他们了。这将是个艰巨的任务，无疑会有许多法师与守卫层层护卫着他。$b$b你必须出发了，尽快结果掉他。大法师死了以后，把他的法杖带回来给我。现在就去，快！', '杀死达拉然大法师，并把他的法杖交给瑟伯切尔的暗影牧师奥利斯特。', '巫师们的魔法被驱散了，节点也回到了休眠状态。并且我们也给了达拉然那些专横的巫师们以沉重的打击。干得漂亮，$N。$B$B但我们仍然要保持警惕，无论如何，这能量节点的位置离我们实在太近……我们必须得为以后好好打算打算。', '动作快一点，$N!我们没多少时间了!', '', '去银松森林找瑟伯切尔的暗影牧师奥利斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (481, '达拉尔的推理', '把这个饰物交给达拉尔·道恩维沃尔，或许他能从中发现一些蛛丝马迹。', '把刻有符文的坠饰交给瑟伯切尔的达拉尔·道恩维沃尔。', '有趣，看来这又是个肯瑞托的诡计。这是一件很强力的魔法物品，肯瑞托中的高阶巫师们一般用它来引导魔法能量。$B$B既然他们已经将这么多的这种东西送去了安伯米尔，这一定意味着他们正在执行着某个庞大的计画。$B$B我看看能不能再进一步了解到他们计画的具体内容。', '怎么，$C?这是什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (483, '唤醒圣物', '瘤背部族的熊怪正在西边的班奈希尔兽穴里肆虐。$b$b除非我们伸出援手，否则那些正在沉睡的德鲁伊将永久地陷于翡翠梦境中，对即将降临的噩运浑然不觉。只有拿到所有的唤醒圣物，我们才能将休眠仪式打断。$b$b到兽穴里去帮我找回鸦爪神符、黑色羽毛、天蓝之石和筑巢符文。德鲁伊们把这些圣物藏在神圣的盒子里，把它们带给我，我要准备进行唤醒仪式。', '找回四件唤醒圣物，把它们交给多兰纳尔的阿斯瑞达斯·熊皮。', '你成功了，年轻的$C!干得好!', '如果我们不能从西边的班奈希尔兽穴寻回唤醒圣物，$N，那么猛禽德鲁伊们就将永远困在翡翠梦境中。$B$B我们每耽搁一分钟，他们就更多一分危险。', '', '去找泰达希尔的阿斯瑞达斯·熊皮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (484, '小鳄鱼皮', '我是皮匠詹姆斯·哈洛兰。我用鳄鱼皮做东西的手艺可是艾泽拉斯第一流的，每天都有大船把我的产品一箱一箱地运到世界各地的港口去。$b$b你见过埃纳尔了吧？他也是专门为我提供新鲜鳄鱼皮的诸多猎人之一。$b$b最近我这里的小鳄鱼皮供应量在直线下降，鉴于当前我真的很缺货，如果你能帮我弄些小鳄鱼皮回来，我会给你开出一个非常不错的价码。你可以在镇外的沼泽里找到那种小鳄鱼。', '为米奈希尔港口的詹姆斯·哈洛兰带回4张小鳄鱼皮。', '你干得非常好，$N。这些皮的品质都是最上乘的。我得马上把它们给风干，越快越好。哦，不过，在我完成这项工作之前，恐怕还得请你为我做另一件事。', '$N，怎么样啦?带回鳄鱼皮了没?', '', '去湿地找米奈希尔港的詹姆斯·哈洛兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (485, '找到OOX-09/HL！', '你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然自动打开了，变成了一个看来是由侏儒制造的机器装置！一个奇怪的声音从这个蛋形机器装置中传了出来。$B$B“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它，我就会奖励你的！请把这个定向器带到那个母体机器人那里。别担心，我现在已经检测到了它的所在地！它现在就位于隐匿石那一带的河水源头附近！”', '把定位器带到奥格索普的母体机器人那里去。$B$B奥格索普的母体机器人位于辛特兰的河水源头，就在隐匿石的附近。', '你把蛋形机器人交给你的定位器放到机器小鸡体内。$B$B里面传出了叽哩咕噜的声音，然后小鸡机器人慢慢地站了起来。当这个机器人能够移动之后，奥格索普的声音再次传了出来:$B$B“OOX-09/HL现在可以勉强运作了，但是它需要一次大检修!对你来说它太重了……但是我想到个好办法。你能不能再帮我看着它一会儿?”$B$B', '发现目标!你赫然看到石头上躺着一只……机器小鸡?!从机器小鸡中传出了声音:$B$B“太好了，你干得不错!这确实是我的母体，根据我的检测判断，它需要进行一定的启动动作才能够重新飞回藏宝海湾进行修理。请把定向器放到母体机器人里，剩下的它自己会去搞定!”', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (486, '大槌乌萨尔', '现在我们必须去解救猛禽德鲁伊了。如果我们现在失败了，他们就将永远迷失于睡梦中。$b$b我将为苏醒仪式做好准备，不过为了进行这个仪式，就必须杀死造成现在这种混乱局面的罪魁祸首。只有到那时，仪式才能正常进行和完成。$b$b大槌乌萨尔把一切都搞得一团糟，现在只有让它为此付出代价，猛禽德鲁伊才能重获自由。到西南边的脊骨堡去杀了它！', '杀掉大槌乌萨尔，然后回到多兰纳尔的阿斯瑞达斯·熊皮那里。', '$N，你证明了自己的价值。像你这样勇敢的$r一定可以获得巨大的荣耀。$B$B无论你走到哪儿，森林之灵都会永远保佑你。', '如果我们不杀死『大槌』乌萨尔，那么我们的同胞就永远无法醒来。', '', '去找泰达希尔的阿斯瑞达斯·熊皮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (487, '达纳苏斯之路', '我们必须保证通往达纳苏斯的道路的安全。有报告说，从多兰纳尔去达纳苏斯的旅行者经常会受到来自瘤背熊怪的残忍袭击。$b$b每天都有无数重要的信息在这条路上进行传递，因此我们绝对不能容忍这帮堕落的熊怪整日恐吓无辜的旅者。$b$b以神圣森林的名义拿起武器，$c。熊怪们的巢穴就在这个高地下面的某个地方。去杀死6个瘤背伏击者，然后再回来向我报告。', '杀掉6个瘤背伏击者，然后向多兰纳尔城外的哨兵阿玛拉·夜行者报告。', '你为多兰纳尔和达纳苏斯做出了巨大的贡献，勇敢的$C。作为泰达希尔哨兵部队的一员，我向你致敬。', '道路仍然很不安全，$C。去杀掉6个瘤背伏击者，然后再回来向我报告。', '', '去找泰达希尔的哨兵阿玛拉·夜行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (488, '赛恩的要求', '我知道你渴望工作，对你来说今天是个幸运的日子，因为我今天只能靠你这个乳臭未干的$c来帮忙了。$b$b你知道，$N，我可以使你非常幸福，我可以让你拥有你从未想过的好东西。但是首先，你必须给我带些东西来。$b$b我在森林里的工作需要一些材料……给我拿来三颗夜刃豹的牙齿、三根巨翼枭的羽毛和三份树林蜘蛛丝。', '给多兰纳尔外面的赛恩·腐蹄带去3颗夜刃豹的牙齿、3根巨翼枭的羽毛和3份树林蜘蛛丝。', '哈哈!确实干得漂亮。$B$B谁能想到会有个$r来帮助我―赛恩.腐蹄?但这事确实有了……我们的这个世界充满了惊奇。$B$B让我们为这位天真与轻信的$r再三欢呼!', '你有没有像小蜜蜂一样忙碌，$N?我一直在等你拿来我需要的东西。', '', '去找泰达希尔的赛恩·腐蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (489, '寻求救赎！', '森林议会听说你帮助了赛恩·腐蹄，这个险恶的萨特是森林的敌人。作为一个$r，你应该更清楚我们不能杀害自然的生物，玷污圣洁的森林。$b$b如果你希望继续做泰达希尔的朋友的话，你就必须在众人的关注下挽回这个过错。$b$b给赛恩·腐蹄一个教训，你就可以得到原谅。魔锥果是从树上掉落的腐坏的种子，一般都冒着绿色的烟气。$b$b给赛恩带去3个魔锥果，他会以为那些只是无害的点心。', '收集3个魔锥果，把它们给在多兰纳尔外面的赛恩·腐蹄。', '啊，多么可口啊!我就知道你是个好心的$r!', '你给我带什么来啦，$N?我猜是份可口的点心?', '', '去找泰达希尔的赛恩·腐蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (491, '给比索的魔杖', '图勒曾经告诉过我，很久以前，他和两名同僚利用各自手中的魔杖混合造出了一根新的魔杖。这根魔杖是友谊的象征。不过图勒虽然珍视他的友谊，但他却更珍视这件物品，并且不会允许自己与别人共同拥有这样一件宝物。所以他偷走了这支魔杖，将它藏在了芬里斯城堡。$B$B就是这个。将这个魔杖送给比索·埃斯沙德，许多年前他曾是图勒的好朋友。我相信他会需要的。', '将狼人魔杖带给幽暗城法师区的比索·埃斯沙德。', '……这是什么?图勒拿着我们的魔杖?我一直以为这件象征着我们友谊的东西被巫妖王给毁掉了!$B$B他一定没有使用过这把魔杖，否则我会感应到。真幸运他没有用它……$B$B这是一个令人兴奋的发现。我对你感激不尽，$N，我要好好地酬谢你。', '$N，你战胜图勒.鸦爪了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (492, '致麻药剂', '亡灵卫兵们说，他们又抓住了一个愚蠢的矮人巡山人。在对这个俘虏问话之前，卫兵们似乎打算把他先关在恐惧之末旅店的地下室里。$b$b为了帮助卫兵们撬开这个死硬巡山人牢实的嘴，我给他们提供了一种特制的神奇饮料。那些家伙到底有没有让他喝下去？不如你帮我跑一趟，去看看这位俘虏有没有因为喝了我的可口饮料而开口招出点什么。', '将乔汉的神奇饮料交给被俘虏的巡山人。', '啊，终于可以喝点东西了。虽然这不是我最喜欢的麦酒，不过都这会儿了，只要是酒我就喝!', '要是我手里拿着我那杆步枪，你们就都得去死，$C。我们的蒸汽坦克旅马上就要来救我啦!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (493, '转至希尔斯布莱德丘陵', '为了给黑暗女士研究出一种新的瘟疫，皇家药剂师学会最近正承受着巨大的压力。当然，我们一直在努力工作并取得了突破性的进展。我们坚信，如果我们学会的成员彼此分享研究成果的话，进展将会更快。$b$b因此我要求你将这些我的最新发现送到塔伦米尔的药剂师林度恩那里去。塔伦米尔是一座位于希尔斯布莱德丘陵地带的小镇，这趟路程可能会很远。$b$b顺路一直向南走，记得看路标！', '将伦弗利尔的研究成果交给希尔斯布莱德山脚下塔伦米尔的药剂师林度恩。', '啊，好极了。伦弗利尔送来了我最想要的东西。我已经迫不及待地想看看他都有些什么成果了。', '你有东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (496, '沉醉之药', '唉，又在塔伦米尔度过了倒霉的一天。这里的新鲜空气让我浑身都不舒服，$N。$b$b要不是在这儿能很容易找到对付天灾军团的必要材料，我才不待在这鬼地方。朋友，请帮我早点结束这样的灰暗日子吧，尽快帮我收集到这些东西：10个灰熊的舌头，还有非常稀少罕见的食苔蛛的毒液。塔伦米尔周围到处都是熊和食苔蛛。', '塔伦米尔的药剂师林度恩要你去收集10个灰熊的舌头和一些食苔蛛的毒液。', '这些东西很不错，$N。现在我可以找些乐子打发时间了，感谢你的帮助。', '你回来了，希望你已经找到了我要的药剂。要是再不弄死些什么人，我就会闷到发狂的。', '', '去希尔斯布莱德丘陵找塔伦米尔的药剂师林度恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (498, '拯救行动', '酋长派我和其它一些战士从敦霍尔德拿回一件东西，并调查这个所谓的辛迪加。$b$b我们到敦霍尔德去转了一圈，很惊讶地在那里看到了很多人类。我们勇敢地和他们战斗，不过他们在人数上占有绝对的优势。我们当中有些同伴被俘虏了，不过我逃了出来。$b$b敦霍尔德就在这里的东南部，过了河就是。德鲁尔和托格萨还被囚禁在那里，你得去把他们救回来。', '塔伦米尔的克鲁斯克要你把德鲁尔和托格萨从敦霍尔德城堡救出来。', '人类想要把我们的战士变成奴隶，不是吗?我们得给他们点颜色看看!$B$B看起来他们好像把我们的首领高迪尔转移到别的地方去了。我们必须把他救出来!不过现在我们还不知道他被关押在什么地方……$B$B一旦有了线索，我们一定会在第一时间告诉你的，$N。$B', '你得快点行动，$C。一想起人类会对德卢尔和托格萨做些什么，我就浑身发抖。', '', '去希尔斯布莱德丘陵找塔伦米尔的克鲁斯克。', '救出德鲁尔', '救出托格萨', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (499, '沉醉之药', '我得花一会儿时间把这些成分混合在一起，做成受难药剂。$b$b成功了！啊，还有什么能比给天灾军团带来点灾难更让人愉快的呢？$b$b让我的助手乌比瞧瞧黑暗女王为天灾军团准备了什么样的礼物。', '把受难药剂交给乌比。', '呱!', '呱呱!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (500, '破碎岭食人魔', '破碎岭食人魔在奥特兰克城废墟附近的山上挖了一座小丘。我的侦察兵告诉我，他们现在还占领了那片遗迹。$B$B我们可不能让他们在那儿享福，一旦他们觉得在那儿生活很安全，下一步就会转移到丘陵地带，然后就是我们南海镇了！$B$B到北方的奥特兰克山去猎杀几个食人魔。把他们那肮脏的指节骨带回来，我会给你奖赏的。', '从奥特兰克山的破碎岭食人魔身上收集9个肮脏的指节骨，把它们带给南海镇的治安官雷德帕斯。', '很好，$N。你一定是砍了不少巨魔才收集到这么多指节骨。$B$B这样他们就没法再烦我们了─至少这一阵子不会。', '$N，你还在猎杀巨魔吗?找到我要的指节骨了吗?', '', '去希尔斯布莱德丘陵找南海镇的治安官雷德帕斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (501, '镇魂之药', '哦，$N……希尔斯布莱德的花都开了，空气这么清新，让我不得不沉湎在这种痛苦之中。我从肮脏的窗子里望出去，渴望着那一天早点到来，让我立即脱离这鸟语花香的痛苦环境。$b$b我喜欢整天坐在这里思考，消灭天灾军团的使命正在召唤我，请你帮帮我吧。我的研究表明，暴烈的山地狮的血液能让天灾兵团失魂落魄，请给我找一点来，让我们做点有趣的事吧。', '收集10瓶山地狮的血液，把它们交给塔伦米尔的药剂师林度恩。', '干得好，$N。', '我记得你，$N。你就是那个准备帮我配制药剂的$r。要想给希尔斯布莱德居民带去我亲自制造的特别礼物，就得先弄到那些血。', '', '去希尔斯布莱德丘陵找塔伦米尔的药剂师林度恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (502, '镇魂之药', '啊，我最喜欢的就是在这丘陵地区弥漫的鲜血的气味！$b$b现在我们加点这个再加点那个，然后最有趣的事情就要发生了！我想把这瓶用血制成的药剂叫做痛苦药剂。如果我的计算正确的话，这个药剂肯定能给希尔瓦娜斯殿下带来不少好处。不过我们还需要做个实验才能确认这一点。$b$b把这瓶药剂拿到西南方的希尔斯布莱德农场，然后到那个地区北部的农庄里去，让我们看看农夫雷恩的小狗斯坦雷喜不喜欢这份“礼物”。', '把痛苦药剂喂给小狗斯坦雷。', '你将一点痛苦药剂倒在自己手中，然后把手伸到斯坦利面前。$B', '汪汪?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (503, '高迪尔', '从你拿到的文件来看，高迪尔被关在北边的一个辛迪加基地里，很有可能就在奥特兰克山。他已经被关押太久了，你必须尽快把他救出来。', '救出高迪尔，然后回到塔伦米尔去见克鲁斯克。', '谢谢你，$N。我遵照酋长的命令从杜隆塔尔远征来到这里，不过你也看到了，我们的计划有点失败。他们把我关在这个镇子里，逼我干活，搬运重物，挖掘泥土……$B$B不过我受了什么罪并不重要，重要的是你必须帮我把一个消息带给现在远征队的首领。$B', '把钥匙给我，$C，让我自己来开锁。', '找出关押高迪尔的地方', '去奥特兰克山脉找高地的高迪尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (504, '破碎岭好战者', '你已经和破碎岭食人魔打过交道了，现在我要你去好好教训教训他们……$B$B到奥特兰克遗迹去猎杀那些破碎岭好战者。我希望你多干掉一些——只有这样才能让这帮畜生离联盟的领土远一点。', '杀死10个破碎岭好战者，然后回南海镇向治安官雷德帕斯报告。', '很好，这是给你的奖赏。\r\n\r\n你猎杀那些好战者的时候有没有注意一下奥特兰克城?我想那里看起来一定很糟吧，因为巨魔一向以来都以邋遢而出名。\r\n\r\n非常感谢，你的努力帮助我们把这些家伙赶出了南海镇。', '你还得杀更多的好战者，$N。你得爬到山上完成任务，而不是收着武器站在山下。', '', '去希尔斯布莱德丘陵找南海镇的治安官雷德帕斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (505, '辛迪加刺客', '我是南海镇的新镇长，前一任镇长被刺杀之后，我刚刚上任。那些刺客一直都没有找到，不过据我们调查，几乎可以肯定他们是由辛迪加雇佣的——辛迪加是一个由邪恶的贵族掌管着的盗贼组织，而那些贵族则是已经陷落的奥特兰克王国的遗老遗少。$B$B根据我们最新的消息，辛迪加在由部落占据的小镇塔伦米尔的北方设有好几座营地，到那儿去杀掉那里的辛迪加成员。', '杀死12个辛迪加劫匪和8个辛迪加盗贼，然后回到南海镇向赫尼·马雷布镇长报到。', '谢谢你，$N。虽然辛迪加还有些残余力量留在那里，不过希望你所杀掉的那些盗贼和劫匪就是刺杀前任镇长的凶手。即便他们不是，辛迪加也是这片土地的敌人，也是我们人类的敌人。$B$B他们的死对于南海镇来说是好消息。$B', '你已经杀掉那些辛迪加暴徒了吧?', '', '去希尔斯布莱德丘陵找南海镇的赫尼·马雷布镇长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (507, '奥里登·匹瑞诺德', '匹瑞诺德一定要被除掉，这个卑鄙的家伙绝不能继续在这世上逍遥了。他的领地就在北边的洛丹米尔湖岸上。去完成这个任务，$n，别忘了把酋长想要的项链也拿到手，然后再回到这里来。', '杀了奥里登·匹瑞诺德领主，并从他的情人艾丽萨身上拿回塔蕾莎的项链。', '不，不要伤害我!我从来没对你们有什么恶意，是他强迫我和他在一起的!求求你……饶了我吧!', '你……想要什么?', '', '去奥特兰克山脉找在高地的艾丽萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (508, '塔蕾莎的礼物', '项链吗？当然可以给你……拿走它吧！我不想再跟他有什么瓜葛了……求求你，别杀我……', '把塔蕾莎的项链交还给希尔斯布莱德丘陵中塔伦米尔的克鲁斯克。', '酋长在这件小东西上面投入了这么大的精力，这真让我莫名其妙。我不敢说已经很了解他了，但是我会追随他，听从他所有的命令。你做得很好，$N。毫无疑问，酋长会为你成功完成这个任务而感到高兴的。$B', '$N，你回来了?任务完成了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (509, '破除天灾', '又是新的一天，又有一种新的药剂要配制。要我说，我宁愿让那些可怜的家伙去和天灾军团互相拼命，反正他们就喜欢互相残杀。$b$b既然黑暗女王要加速这个过程，不如在这段恐怖的日子里再给这片土地加点料怎么样？$b$b我有个计划，$N，你现在到奈杉德哨岗去，那地方在塔伦米尔的南边，南海镇的东边。给我找6朵泥头花来让我配制药剂。', '收集6朵泥头花，把它们交给塔伦米尔的药剂师林度恩。', '啊，臭气熏天的泥头花。这些肮脏的豺狼人至少还是有点用的嘛。', '在奈杉德岗哨的进展还顺利吗?', '', '去希尔斯布莱德丘陵找塔伦米尔的药剂师林度恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (510, '预备行动计划', '这些文件当中有一份物资清单，清单里包括各种日常物品（食物、武器、衣服）和其它工具（面具、油、毒药）。$B$B不过其中提到最重要的就是：尽高速缓冲得清单中的物资，为文件里所说的“针对南海镇的重要使命”进行准备。', '把预备行动计划带给南海镇的赫尼·马雷布镇长。', '<马雷布读了文件。>$B$B这可有些麻烦了，$N。根据这些文件里的消息以及辛迪加以往的行动，我们认为已经有一群暴徒准备向南海镇进攻了。', '$N，你看起来很焦急。有什么要告诉我的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (511, '密文信件', '桌上有一封用密文写成的信，你根本没法读懂。', '把密码信交给南海镇的博学者迪布斯。', '这是什么?等一下……让我仔细看看。$B$B……$B$B嗯，我以前从来没见过这种密文，我得承认我在这方面的知识还远远不够。', '你好，$g先生:女士;。你找我有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (512, '贵族之死', '我担心辛迪加的幕后首脑想要毁灭南海镇，因此我们必须在他们的计划得以实现之前干掉这些头目。$B$B你去北边奥特兰克山里的斯坦恩布莱德废墟调查一下，我们觉得那里是辛迪加的指挥部。$B$B我们知道这帮刺客是以前的奥特兰克贵族指使的，贵族们可能会打扮成普通辛迪加密探的样子，不过通过他们手上戴着的徽记之戒就能很容易地判断他们是不是贵族了。$B$B把他们的徽记之戒给我拿来。', '为南海镇的赫尼·马雷布镇长收集7个奥特兰克徽记之戒。', '除掉了奥特兰克的贵族，就可以让辛迪加失去组织性，让他们变成一帮有勇无谋的暴徒。$B$B你为联盟作出了杰出的贡献，$N。', '你一直在追捕辛迪加吗?拿到戒指了吗?', '', '去希尔斯布莱德丘陵找南海镇的赫尼·马雷布镇长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (513, '破除天灾', '就在我觉得这一天又要无趣地打发掉的时候，你给我带来了这些泥头花。$b$b等我把它们混合在一起。我们还需要幽暗城的大药剂师法拉尼尔给药剂里加上他的腐蚀胶体，然后就等着看好戏吧！$b$b把这个泥头花药拿去交给大药剂师法拉尼尔，$N，现在就去。', '把泥头花药交给幽暗城的大药剂师法拉尼尔。', '药剂师林度恩叫你来的?哎呀，你为什么不早说?$B$B虽然林度恩性格阴郁，不过他是我们当中最忠诚也是技术最熟练的一员。$B$B这家伙派你送来了泥头花药!我现在知道他要在希尔斯布莱德干什么了，我喜欢他的想法。黑暗女王一定会对他制造新瘟疫的进展非常满意的。$B', '你看不见我正忙着吗，$C?黑暗女王坚持要在诺森德来的天灾军团压倒我们之前再制造一场瘟疫。南方的人类越来越有威胁，时间对我们来说是最宝贵的东西。你最好不是要拿什么鸡毛蒜皮的事情来烦我!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (514, '铁炉堡的译码者', '我在铁炉堡有个同僚也许可以帮忙破译这封信。到铁炉堡的探险者联盟去找勘察员塔伯斯·雷矛谈一谈，告诉他是我让你去的，把这封信给他看。黑石塔以北如果还有人能读懂这封信的话，那一定就是他了。', '把密码信带给铁炉堡的勘察员塔伯斯·雷矛。', '啊，密码!这可是我的专长。让我看看……', '是南海镇的迪布斯让你来的?那个老书呆子现在怎么样了?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (515, '破除天灾', '泥头花药？太棒了！我怎么就没想到过这个呢？$b$b让我给这种药剂里面加入我研制的性能胶体。$b$b如果要激活泥头花水里的活力成分，林度恩就得先弄到强力巨魔之血药水，还有南海岸的刺脊纳迦的鳞片和碎鳍鱼人的眼球。你去找到这些试剂，林度恩会知道怎么处理它们的。天哪，我真想早点知道他的实验进行得怎么样了！', '把泥头花水、1瓶强力巨魔之血药水、5块刺脊纳迦的鳞片和5颗碎鳍鱼人的眼球交给塔伦米尔的药剂师林度恩。', '这个让人激动的实验都让我头晕眼花了!你帮了我的大忙，$N。这下子我们可以一起在这片土地上传播死亡和疾病了。', '很高兴看见你回来，$N。我在这儿快闷死了。连一丁点有意思的事情都没有，每天都是制造毒药，把毒药喂给乌比，然后复活它……不断地重复再重复……$B$B你的幽暗城之旅怎么样?一路上有没有杀几个人类解闷啊?', '', '去希尔斯布莱德丘陵找塔伦米尔的药剂师林度恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (516, '博伦的巢穴', '我收到报告说，一群天灾军团的亡灵正在附近集结，准备对我们进行一次袭击。既然得到了这样的情报，我们就本应该先下手攻击他们，把他们的计划粉碎在襁褓中才对。$b$b但不幸的是，我的情报十分有限，只知道他们在一个名为博伦的巢穴的山洞里集结。确切的位置我也不清楚，但应该在安伯米尔附近的山区中。$b$b我相信以你的能力和才智，一定可以找到他们，干掉他们。', '找到博伦的巢穴，杀死6名鸦爪苦工和6名鸦爪守护者，然后向瑟伯切尔的暗影牧师奥利斯特汇报。', '如果我们的斥候和线人总是能搞到这样有价值的资讯的话，我们早就把巫妖王的天灾军团从这片土地上抹除了。', '你找到他们的巢穴了吗，$N?时间紧迫!', '', '去银松森林找瑟伯切尔的暗影牧师奥利斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (517, '破除天灾', '新药剂终于进入了实验阶段，不过呆在阴冷的屋子里这么多天，我的脑筋都快打结了，让我们以“破除天灾”之名找点乐子吧。$b$b到丹加洛克去，你知道，就是到那些肮脏的小矮人出没的军营里去，给我偷一桶矿工烈酒出来，有了它，你我就可以畅饮美酒狂欢了，$N。', '将一桶矿工烈酒交给塔伦米尔的药剂师林度恩。', '我们终于准备好了!', '在塔伦米尔这儿待久了，我常常会感到厌烦，总是忍不住想要打开装满酒精的瓶子，让这股芳香在空气里飘荡，虽然这气味让乌比有点紧张。$B$B你能从矮人那儿弄一瓶酒回来吗?如果无法让什么人喝下这瓶完美无缺的致命毒药的话，我肯定会疯掉的。', '', '去希尔斯布莱德丘陵找塔伦米尔的药剂师林度恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (518, '意志之冠', '玛格索尔和他的破碎岭食人魔在奥特兰克废墟已经泛滥成灾了。不减少食人魔的数量的话，我们就很难去对付玛格索尔。$b$b等他们的实力被削弱以后，我们就能继续前进了。$b$b懂了吗？好的。去吧。', '塔伦米尔的梅里萨拉要你去杀掉10个破碎岭虐待者。', '巨魔的血把白雪都染红了，不过在破碎岭的巨魔和他们的精神被完全压制并埋在大雪中之前，我们还不能停下来。', '你的任务还没有完成，$N。我要不要把你不称职的表现报告给沙琳德拉呢?', '', '去希尔斯布莱德丘陵找塔伦米尔的梅里萨拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (519, '意志之冠', '塔尔格、玛克拉克和戈洛姆斯都是玛格索尔的下属。我们不知道食人魔的忠心来源于什么，不过他们对玛格索尔可是死心塌地。$b$b把他们的徽记给我带回来，$n，接下来就是干掉玛格索尔，彻底瓦解那些食人魔。', '干掉塔尔格、玛克拉克和戈洛姆斯，把他们的徽记带给塔伦米尔的梅里萨拉。', '……我觉得巨魔真是蠢得要死。$B$B等你把玛格索尔的头给我带回来，我就把他们的四颗肥脑袋插在长矛上，放在奥特兰克示众。这就是违抗黑暗女王意志的下场。', '提他们的头来见我，$N，否则就提你自己的。', '', '去希尔斯布莱德丘陵找塔伦米尔的梅里萨拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (520, '意志之冠', '玛格索尔的下属都死了，剩下的就是杀掉玛格索尔，取回意志之冠。他当然不想失去那顶王冠，所以我想你最好……首先将他周围的障碍都干掉。$b$b找到玛格索尔，把他的徽记和王冠一起带回来。破碎岭的抵抗就到此为止了。', '杀了玛格索尔，带着他的徽记和意志之冠去塔伦米尔见梅里萨拉。', '你的任务完成得不错，$N。玛格索尔的脑袋可以用来装饰奥特兰克废墟的最高点，我们的亡灵卫兵会把破碎岭的残余势力消灭得一干二净。', '我已经拿到三颗脑袋了，还需要第四颗。要么是玛格索尔的脑袋，要么就是你的，$N。我说到做到。', '', '去希尔斯布莱德丘陵找塔伦米尔的梅里萨拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (521, '意志之冠', '剩下的任务就是把意志之冠交给幽暗城的沙琳德拉。她会派人送去给希尔瓦娜斯大人。我得警告你，别想把它留着自己用，玛格索尔的死就是最好的例子。', '把意志之冠交给幽暗城的沙琳德拉。', '那么，这就是巨魔用来违抗黑暗女王的意志的东西了?$B$B很奇怪这么简单的东西竟能发挥出那么大的力量，还落入了那种拙劣的生物手里。干得好，$N，我会把王冠送去给希尔瓦娜斯大人，顺便把你的成绩汇报给她。', '什么?你有什么要报告的?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (522, '刺客的契约', '这是一份刺杀赫尼·马雷布镇长的契约。合约已经封好，并用一个特殊的徽记之戒在红蜡上做了标记。', '把刺客的契约带给南海镇的赫尼·马雷布镇长。', '<马雷布查看了合约。>$B$B这份契约终于让最近频频发生在南海镇的袭击事件有了眉目。辛迪加一定是针对我，就像他们针对前一任镇长那样!', '你怎么气喘吁吁的，有什么要报告的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (523, '男爵之死', '你找到的契约是瓦杜斯男爵签署的，他是以前的奥特兰克王国的贵族，并且一向以冷酷和残暴而着称。这件事的背后由瓦杜斯这样的人主使，我对此一点也不感到奇怪。$B$B去找到他，让他受到正义的制裁。他一定在辛迪加经常出没的地方活动，也许在斯坦恩布莱德的废墟，也许在废墟北面的山谷里。', '把瓦杜斯男爵的徽记带给南海镇的赫尼·马雷布镇长。', '谢谢你，$N。既然这个恶棍已经罪有应得，我绷紧的神经也可以放松一下了。', '瓦杜斯男爵派刺客来对付我们南海镇，但是他别指望能逃过正义的惩罚。把他的脑袋提来见我!', '', '去希尔斯布莱德丘陵找南海镇的赫尼·马雷布镇长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (524, '破除天灾', '隔壁的亡灵卫兵看守着几个被俘的人类农夫。真没想到，和安静的亡灵相比，这些人类太吵了。他们并不知道我在干什么；如果知道我正在为破除天灾努力，他们的喧哗叫嚷又打扰了我的思考，恐怕就不会这么吵闹。$b$b让他们安静下来最直接的办法，就是过去让他们闭嘴。可是我真不想就这点看起来鸡毛蒜皮的琐事跟他们废话。这样，你把这只装满烈酒的酒桶放在他们房间的地毯上，我想只要再忍受一会儿，他们就会安静下来，至少，我的思绪能延续到明早。', '把装满烈酒的酒桶放在被俘农夫房间的地毯上。', '你把受污染的酒桶放在布满灰尘的地毯上。', '地毯上传来一股发霉的味道。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (525, '更大的谜团', '我已经译出了这封信，不过还是不知道它是什么意思。你是在奥特兰克丘陵的盗贼身上找到这封信的吗？真奇怪……$B$B你应该把它拿去给南海镇的镇长看看。虽然这封信的含义不甚明了，但是南海镇离奥特兰克最近，如果有什么威胁正在临近的话，我想应该先告诉他。', '把被破译的信件交给南海镇的赫尼·马雷布镇长。', '<马雷布读着信。>$B$B这是根据你在辛迪加营地找的那封信翻译过来的?这封信不是小偷写的，也不是奥特兰克的贵族写的。$B$B看来辛迪加还和别的势力有所联系，我不敢想象是和谁有关。', '$N。你又去长途旅行过了吗?带回什么消息了?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (526, '光铸铁锭', '你可能已经在那箱子里找到了一块光铸铁锭，但如果要打造些什么东西的话，这么一点铁是绝对不够的！$B$B你得再回去看看，没准在船只残骸附近的鱼人身上会有更多的光铸铁锭。', '收集5块光铸铁锭，把它们交给湿地的戈罗林·钢眉。', '啊，找全了!我们现在就来用这些上好的光铸铁打造些有用的东西吧，怎么样?', '你找到足够的光铸铁锭了吗?', '', '去湿地找米奈希尔港的戈罗林·钢眉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (527, '希尔斯布莱德之战', '和我说话的时候要立正，$c。$b$b我受瓦里玛萨斯的直接领导。在我们的药剂师研制出新型瘟疫之前，我们必须要压制住人类的攻势。$b$b有消息表明，希尔斯布莱德镇是个防守很薄弱的小镇。你的第一个任务是扰乱敌人的食品供给和基础设施建设。$b$b从这里往西边方向进发，你的目标是希尔斯布莱德平原最北边的农场，在那里大开杀戒的同时，别忘了把当地的农场主——农夫雷恩和农夫盖兹也给干掉。', '杀掉6个希尔斯布莱德雇农和6个希尔斯布莱德农夫，还有农夫雷恩和农夫盖兹，然后返回塔伦米尔向达萨利亚报告。', '放松点，$C。你从战场上回来了。我的情报人员告诉我说，你在希尔斯布莱德前线的表现相当不错。', '我是塔伦米尔的高阶执行官，受瓦里玛萨斯和黑暗女王的直接领导。你必须听从我的命令。$B$B你有没有任何帮助联盟的举动?如果有的话，我会把你就地正法。如果没有，那就往西边去到希尔斯布莱德镇，按照我的命令向人类作战。$B$B你可以退下了。', '', '去希尔斯布莱德丘陵找塔伦米尔的高级执行官达萨利亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (528, '希尔斯布莱德之战', '北方农场被袭击的消息让人类的村民们惊慌失措，你干得很出色。$b$b我们的哨兵报告说有农民向希尔斯布莱德南部逃散——这些傻瓜以为他们可以藏在果园里逃过一死。$b$b去结果他们吧，$N。回到希尔斯布莱德农场去，把这些东躲西藏的农民找出来，以黑暗女王的名义杀了他们。$b$b解散！', '杀死15个希尔斯布莱德农民，然后回到塔伦米尔向达萨利亚汇报。', '希尔斯布莱德镇的末日就快到了，我们的作战计划进展不错。', '你有要务在身，$C，不要像无头苍蝇一样在塔伦米尔闲逛，其他地方还有很多事情等着你去做呢。', '', '去希尔斯布莱德丘陵找塔伦米尔的高级执行官达萨利亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (529, '希尔斯布莱德之战', '希尔斯布莱德的人类进行了顽强的抵抗，这实在有点出乎我的意料。问题的关键在于，有几个铁匠在为那些镇民提供武器，我们得切断他们的所有供给线。$b$b你的任务是干掉铁匠维林坦，还有他的那些学徒也得杀了。还有，把他们库存的铁也给抢回来。等我们征服了希尔斯布莱德并开始准备进攻南海镇的时候，这些物资就显得非常重要了。', '杀掉铁匠维林坦和4个希尔斯布莱德见习铁匠，并从那里抢回一箱铁材，然后向塔伦米尔的达萨利亚汇报。', '任务完成，$C。你干得非常好。', '你完成了我的命令没有，$C?你除掉铁匠维林坦和他的助手了吗?还有，我要的铁在哪儿呢?', '', '去希尔斯布莱德丘陵找塔伦米尔的高级执行官达萨利亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (530, '丈夫的复仇', '瓦德雷曾经是我的好朋友，但他也是杀害我妻子的凶手。虽然我已经不知道悲伤为何物了，但我复仇的念头却一直没有改变。去帮我杀了瓦德雷，把他那双邪恶的手带给我，我会奖赏你的。$B$B我最后一次听到他的消息时，他正准备从银松森林南部的格雷迈恩之墙逃往吉尔尼斯王国。', '杀掉瓦德雷·莫莱。$B$B把他的双手带给幽暗城的拉林夫·安迪恩。', '哦，很好。就是这双手杀了我的妻子黛丽娅。我唯一的希望就是为她复仇，而你替我完成了这个心愿。$B$B你之前拿回的这个戒指就送给你吧，黛丽娅已经离开我很久，这个戒指我也不想保留了。我宁愿留着这双手，让我永远记住一个朋友曾经背叛过我。', '你砍下他的手了吗，$N?', '', '去找洛丹伦废墟的拉林夫·安迪恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (531, '维林的报复', '天哪！别把这种东西带到营地里来……它太肮脏，太可怕…太…太肮脏了！$b$b你把它拿出去行不行？没有人想看到你这件血淋淋的战利品！真的！', '把奥尔苏迪的徽记交给旅行者营地的维林·疾风。', '谢谢你帮助我完成这个小计画，$N。几个月了，我一直想报复那个傲慢自大的家伙，这次我们做得还不错!拿着这个，这是给你的奖励。', '干得好，$N!这家伙被吓坏了!把这颗头给我吧，我来处理。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (532, '希尔斯布莱德之战', '希尔斯布莱德镇现在一片混乱，我们相信它很快就要被攻陷了。但是，我们必须继续坚持对敌人不断地发动攻击，直到把所有的人类渣滓都完全从这里赶出去为止。$b$b虽然人类损失惨重，但他们仍然团结在领袖的周围继续抵抗。我们得除掉他们的首领波恩塞德镇长，当然还有镇议会的成员。最后别忘了毁掉他们的政治文件《希尔斯布莱德宣言》，顺便把镇里的文档也都偷过来。', '杀掉波恩塞德镇长和4个希尔斯布莱德议员，摧毁《希尔斯布莱德宣言》，偷取希尔斯布莱德城镇文档，然后回到塔伦米尔向达萨利亚汇报。', '关于你的辉煌事迹已经传遍希尔斯布莱德了。干得漂亮， $C。', '你干得怎么样了?', '', '去希尔斯布莱德丘陵找塔伦米尔的高级执行官达萨利亚。', '', '', '《希尔斯布莱德宣言》已经被毁', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (533, '秘密潜入', '我们终于得到了关于高迪尔的线索。人类不停地到处转移他，但是我们已经缩小了搜索范围，现在我们的注意力主要集中在北边的那个辛迪加营地里。$b$b到那儿去打探一下，然后回来向我报告。', '把关于高迪尔下落的消息带回来给塔伦米尔的克鲁斯克。', '终于知道高迪尔被关在哪里了。我们怀疑关押他的营地离这儿不远，而且这次他们很有可能不像上次抓我们时准备得那么充分。', '你找到什么了吗?我担心高迪尔的处境会一天比一天糟……', '', '去希尔斯布莱德丘陵找塔伦米尔的克鲁斯克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (535, '仆从瓦里克', '呃……重病、濒死，而且还要与敌人作战。$b$b毫无疑问，你会杀了我，但如果你可以带给我些南海镇烈酒的话，我会告诉你所有你想知道的——我想你们$r平时也喜欢喝点什么吧，不是吗?', '给辛迪加营地里的瓦里克带去一杯南海镇烈酒。', '我就要死了，不过我敢说这是我喝过的最好的酒……拿着这个，我死掉以后就用不到它了。$B$B嗯，快走吧!', '你是来给我送些喝的呢，还是回来结果我的?', '', '去奥特兰克山找索菲亚高地的仆从瓦里克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (536, '清理海岸', '我从暴风城守卫被调到这个鸟不生蛋的南海镇来做守卫，这镇子简直是一无是处……整日整夜都是一股鱼腥味。$b$b更别提治安官雷德帕斯了……他还想要我去对付那帮鱼人，哈！$b$b我很难打起精神去跟西部海岸上的那群奇形怪状的鱼人作战。如果你愿意替我去干掉它们，我会很感激你的。', '南海镇的法尔林·奥里涅尔中尉要你去杀掉10个碎鳍潮行鱼人和10个碎鳍智者。', '我希望这样就可以让雷德帕斯完全相信我已经─哈哈─完成了他的命令，为南海镇除去了可怕的鱼人!没有什么比那些畸形的大鱼更邪恶的了!$B', '再给我来瓶麦芽酒，刚才那瓶跟没喝似的!$B$B圣光啊，我还得困在这儿多久?$B$B哦，是你呀，$N。你杀掉那些鱼人了吗?', '', '去希尔斯布莱德丘陵找南海镇的法尔林·奥里涅尔中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (537, '黑暗议会', '你拿来的信是一个自称为纳伽兹的人写的，他是“阿古斯复苏”的一员。我不知道这个“阿古斯复苏”是个什么样的组织，不过如果他们和辛迪加是一伙的话，就是我们的威胁。$B$B我要你去查查这封信上提到的纳伽兹和暗影大法师。找到他们，把他们干掉。$B$B去高地看看，那里是辛迪加的势力范围，就在斯坦恩布莱德的北面。$B$B如果运气够好的话，你就能在那儿找到这些“阿古斯复苏”的特使。', '杀死4个暗影大法师。$B$B把纳伽兹的徽记带给南海镇的马雷布镇长。', '干得好，$N。阿古斯觉醒听起来好像不是掌管辛迪加的组织。$B$B虽然你已经干掉了他们在这里委派的领袖，不过可能还有别的幕后黑手控制着这一切。这个组织在艾泽拉斯大陆可能有着很大的影响力。$B$B……他们甚至在整个世界上都有着可怕的影响力。$B', '你找到阿古斯觉醒的特使了吗?', '', '去希尔斯布莱德丘陵找南海镇的赫尼·马雷布镇长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (539, '希尔斯布莱德之战', '希尔斯布莱德城镇文档里的记录表明，碧玉矿洞已经处于联盟的控制之下——这个矿洞是联盟兵工厂运转所需的铁矿石的主要来源。$b$b虽然我们已经对希尔斯布莱德镇进行了致命的打击，但是联盟还是积极地支持和保护着碧玉矿洞。$b$b这个矿洞就在希尔斯布莱德的正南方。到那里去杀了他们的工头，一个名叫邦德斯的人类，顺便把那里的矿工也干掉。这样的行动可以给联盟传达一个足够清楚的讯息。', '杀死工头邦德斯和10个希尔斯布莱德矿工，然后回到塔伦米尔向达萨利亚汇报。', '又有一个矿坑可以为我们提供源源不断的武器了，黑暗女王要是知道的话一定会很高兴的。', '你已经接到了攻击碧玉矿坑的命令。现在你最好为你在塔伦米尔整日闲逛找出合适的理由，否则我就以叛国罪将你斩首。', '', '去希尔斯布莱德丘陵找塔伦米尔的高级执行官达萨利亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (540, '保全书籍', '那些野蛮的食人魔现在就驻扎在奥特兰克废墟，一想起他们会把那里的书籍怎么样，我就感到毛骨悚然。你一定要尽力去完成我给你的任务！$B$B进入奥特兰克废墟，找到食人魔夺走的书籍。把你找到的所有东西都带给我，特别是这本书：《格里雷克之臂》。这本书里写着巨魔的古老学说，我一定要学。奥特兰克是完整保存这本书的唯一地方。', '把5本失而复得的书籍和包含《格里雷克之臂》的破旧的皮书带给南海镇的博学者迪布斯。', '哦，你拿到它了!太棒了，我现在就开始研究《格里雷克之臂》!', '我也想自己到奥特兰克废墟去，不过我这把老骨头恐怕已经不能爬山了。你寻找书籍的进展如何，$N?', '', '去希尔斯布莱德丘陵找南海镇的博学者迪布斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (541, '希尔斯布莱德之战', '矮人正在协助人类？这帮肮脏的小东西。$b$b我们得看看这所谓的联盟的实力到底如何。等这些矮子知道我们的厉害之后，看他们还愿不愿意继续给人类卖命！$b$b我们知道这些矮人的据点在哪里，他们在希尔斯布莱德东南部沿着索拉丁之墙的地方创建了一个被称作丹加洛克的军营。你的最终目标是攻占丹加洛克，$c。他们的首领达伦·铁山上尉必须得死。', '到丹加洛克去杀掉8个巡山人、4个火枪手、2个牧师，还有达伦·铁山上尉，然后回到塔伦米尔向达萨利亚汇报。', '你在战场上的表现足以得到最高的肯定。', '丹加洛克对你而言应该是个很棘手的要塞吧，$C?我认为你在希尔斯布莱德的英勇表现已经很值得认可了。$B$B如果你不能胜任我交给你的任务，我就会去找个能完成任务的人。至于你嘛，我想黑暗女王在提瑞斯法林地那边还需要更多的掘墓工。', '', '去希尔斯布莱德丘陵找塔伦米尔的高级执行官达萨利亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (542, '向米尔顿回复', '我得花点时间来研究你带回来的《格里雷克之臂》，不过我敢说米尔顿已经等不急要把你找回来的另一些书放到暴风城的图书馆里去了。$B$B这些就是你从奥特兰克废墟带回来的书，我已经按照目录分类整理过了。把它们带给暴风城的米尔顿·西弗，他一定会很感激你的。', '把奥特兰克的书籍带给暴风城的米尔顿·西弗。', '哦，我的天!瞧瞧这些!奥特兰克都毁了，但这些书竟然还能留下来，简直令人难以相信!$B$B谢谢，$N，太感谢你了!你帮助我们保存了人类的知识和文明，还让暴风城的皇家图书馆更加辉煌。', '$N，你回来了!在奥特兰克的进展如何?找到什么东西了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (543, '匹瑞诺德王冠', '匹瑞诺德王冠据说是奥特兰克王国被毁灭之前的“名门望族”匹瑞诺德系列的传家之宝，有人说它是由铁炉堡的珠宝大师们用最美丽的翡翠制成的。$B$B当奥特兰克系列被毁灭的时候，王冠也随之遗失了。但有传闻说有一个食人魔法师——叫什么守财奴格雷尔伯格的家伙——得到了它，那家伙现在还在奥特兰克遗迹附近游荡，想要找到更多的财宝。$B$B我们希望你能为我们取回王冠。', '将匹瑞诺德王冠带给暴风城的雷明顿·瑞治维尔。', '啊，这太棒了。这是一项非常严峻的挑战，但你确实超越了自我，$N。我会让人处理一下冠冕并尽快把它放进我们的收藏室里去。$B$B我们对你的感谢正如同这件收藏品一样值得珍重，我确信你也很赞同这一点，对吗?', '你好，$N。小心别踩在我的外套的下摆上，这身套装可是刚做的。', '', '去艾尔文森林找北郡山谷的雷明顿·瑞治维尔伯爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (544, '誓死追赃', '我本来是到塔伦米尔来做研究的，不过现在我手头上有个麻烦一定要尽快解决掉。你知道，几个月前曾有四个被遗忘者从幽暗城逃了出来。他们抛弃了自己的同伴，这没什么，但问题是……他们偷了黑暗女王的东西。$B$B这些小偷闯入了一间秘密的地窖，偷走了四件供药剂师研究用的神器。黑暗女王命令我们把这四件神器找回来。$B$B小偷从幽暗城逃到了达拉然，而那些巫师则把他们收留在洛丹米尔收容所里。', '找到被遗忘者的叛徒，取回他们偷走的神器，然后回到塔伦米尔去见大法师沃迪恩·伍德格莱尔。', '你为被遗忘者立了大功，$N。我们很需要拿回这些神器。$B$B而且，听到克甘和其他几个叛徒已经受到了制裁，这让我们感到更加高兴了。', '你找到那些小偷了吗?你拿回他们偷走的东西了吗?', '', '去希尔斯布莱德丘陵找塔伦米尔的大法师沃迪恩·伍德格莱尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (545, '达拉然巡逻队', '达拉然的巫师在他们的城市中心建起一个巨大的魔法护罩。有人认为那是为了防止城市遭到攻击，还有人认为他们只是想有个安静的地方供他们进行魔法研究。$B$B不管那到底是什么原因，我关心的是在那个护罩之外的郊区废墟里是否藏着有用的魔法物品。$B$B不过那里有许多巫师和他们的元素奴仆在到处巡逻。$B$B去杀了他们，杀到你手软之后再回来吧。', '杀掉6个达拉然召唤师和12个元素奴仆，然后回到塔伦米尔去见大法师沃迪恩·伍德格莱尔。', '很好。现在我们可以去那片废墟进行搜索了，只要小心一点的话，应该就不会有危险。$B$B谢谢你，$N。', '你去消灭达尔然遗迹周围的巡逻队了吗?', '', '去希尔斯布莱德丘陵找塔伦米尔的大法师沃迪恩·伍德格莱尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (546, '死亡的纪念品', '听说达萨利亚让你和希尔斯布莱德的人类作战，我很嫉妒你……$b$b你在外面享受屠杀人类、掠夺城镇、恐吓无辜者的快乐，而我却像木头一样待在塔伦米尔做守卫。$b$b你能可怜可怜像我这样的老亡灵卫兵吗？你知道我在收集人类的徽记，正好你还要和人类战斗一段时间。那么，能不能在你作战的这段时间里顺便给我收集30个徽记来？我会让你的努力物有所值的。', '塔伦米尔的亡灵卫兵沙穆萨想要30个希尔斯布莱德人类徽记。', '宝贵的颅骨!太美了!请接受我的谢意，$N!', '幸运的$N凯旋而回了?你今天干掉了多少个人类?我猜有几百个吧!$B$B有没有给我收集颅骨?', '', '去希尔斯布莱德丘陵找塔伦米尔的亡灵卫兵沙穆萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (547, '亨伯特的长剑', '高级执行官达萨利亚派我从远处监视丹加洛克。我在一个隐蔽的角落里扎了营，但是那天早上我在烧水的时候离开了一会儿去找柴火……$b$b等我回来时，发现放在营地里的装备已经不见了。$b$b一定是那些丹加洛克的矮人侦察兵从这儿经过的时候把东西拿走了。我必须得拿回我的剑！如果你能帮我拿回来的话，我会很感激你的。但是那儿的矮人真是太多了……也许你很难在他们当中找出那个小偷。', '从丹加洛克拿回亡灵卫兵亨伯特的长剑，然后回到塔伦米尔把剑还给他。', '你找到我的剑了!$B$B啊，我最宝贵的剑能重回手中，真是太好了。非常感谢你!', '你拿回我的剑了吗，$N?如果高阶执行官达萨利亚知道我这么蠢，一定会把我吊死的。', '', '去希尔斯布莱德丘陵找塔伦米尔的亡灵卫兵亨伯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (549, '通缉：辛迪加成员', '经由黑暗女王希尔瓦娜斯授权，辛迪加组织的全部成员都将被处死！那些已经被羁押和俘虏的辛迪加成员必须立刻处决。残馀的辛迪加成员当前在塔伦米尔东南部的敦霍尔德城堡废墟聚集。$b$b任何向高级执行官达萨利亚证明自己完成了这个任务的人都会受到重赏。', '杀死10个辛迪加盗贼和10个辛迪加哨兵，然后回到塔伦米尔向高级执行官达萨利亚报告。', '很好，$C.按照这样的形势，在这片土地上到处流窜的辛迪加很快就能被消灭。', '除了在这儿站着，你就没什么别的可以做的了，$C?作为一个高阶执行官，我还有很多重要的事要做，没闲工夫对着你这张坑坑洼洼的脸打发时间!', '', '去希尔斯布莱德丘陵找塔伦米尔的高级执行官达萨利亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (550, '希尔斯布莱德之战', '由于你在希尔斯布莱德战役中的英勇表现，我已经向上级写了这封褒奖状以表扬你。$b$b把这密封的奖状带给幽暗城的布拉贡·血拳，你可以满怀骄傲地去见他，$c。', '把达萨利亚的奖状交给幽暗城的布拉贡·血拳。', '你就是那个在希尔斯布莱德丘陵对联盟进行了致命打击的$C?你的英勇事迹早已传到幽暗城来了。$B$B只要你跟随着黑暗女王，继续在战斗中表现你的领导才能和长处，那么一定会前途无量的。$B$B虽然我们的主要威胁─巫妖王的天灾军团在北部的势力已经被不断削弱，但我们的战斗计划还在不断受到这些人类的阻挠。不过，你的表现已经说明我们能够打败人类，我们也必将打败人类和所有被遗忘者的敌人。', '是什么事让一个$C大老远地从战场上跑到幽暗城里来?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (551, '附有魔法的羊皮纸', '这张羊皮纸上被施加了某种咒语，使其无法被破译。但是，卷首的一个词却很容易辨认：$B$B$B      纳伽兹$B$B', '将这张附有魔法的羊皮纸带给希尔斯布莱德丘陵中南海镇的博学者迪布斯。', '又是个加密档?$B$B我希望我有能力解开这些在奥特兰克找到的奇怪符号……然而，恐怕我在这方面的知识还不够。', '哦，你应该有些要给我看的东西，对吧?是不是从山上找来的文献?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (552, '赫尔库拉的复仇', '正在赫尔库拉大人即将完成他的巫妖仪式的紧要关头，一群人类暴徒发现了他在山上进行仪式的位置，把他残忍地杀害了。更糟的是，他们把他的遗骨埋在了南海镇的墓地里。$b$b这种不尊重伟大的巫师的行径绝对是无法让人接受的。作为他的学徒，我一定要让复仇降临在南海镇。$b$b首先我们得找到赫尔库拉的魔棒，前不久，一群雪怪侵袭了赫尔库拉的巢穴。毫无疑问是他们当中的一个拿走了赫尔库拉的魔棒。', '从雪怪手上拿回赫尔库拉的魔棒，把它交给塔伦米尔的学徒塞万德。', '你找到它了!干得好，$N!', '你找到赫尔库拉的魔棒了吗?这一带有很多雪人，很难找出是他们中的哪一个拿了魔棒。不过不管怎么样，我们必须把赫尔库拉的魔棒拿回来才能继续。', '', '去希尔斯布莱德丘陵找塔伦米尔的学徒塞万德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (553, '赫尔库拉的复仇', '拿着赫尔库拉的魔棒，你会用得着它的。$b$b赫尔库拉用3个火葬柴堆来构筑他最强大的法术：埃希尔之焰和沃拉兹之焰在丘陵地带的洞穴里，尤基尔之焰在丘陵洞穴上面的另一个洞穴，在山的更北边。$b$b赫尔库拉的魔棒必须经过这三堆火焰的洗礼才能发挥作用。在仪式完成之后，把魔棒带到赫尔库拉的墓地去，那座墓地就在由人类重兵把守的南海镇。让赫尔库拉的复仇降临在愚蠢的人类头上吧！', '将埃希尔之焰、沃拉兹之焰和尤基尔之焰的力量注入赫尔库拉的魔棒。$b$b把经过仪式洗礼之后的魔棒带到南海镇的赫尔库拉墓地。', '地上发出了隆隆的巨响。', '赫尔库拉的墓地中充满着神秘的能量。', '', '去希尔斯布莱德丘陵的南海镇坟场找赫尔库拉的墓地。', '埃希尔之焰的力量已经注入', '沃拉兹之焰的力量已经注入', '尤基尔之焰的力量已经注入', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (554, '解码高手', '勘察员塔伯斯·雷矛是解码和译码的高手。把你找到的羊皮纸交给他，运气好的话，他说不定能弄清楚这里面写着什么。塔伯斯·雷矛现在正在铁炉堡的勘矿指挥部进修。$B$B见到他的话，就说你已经跟我谈过了，好像我最近给他添了不少的麻烦……', '把附有魔法的羊皮纸带给铁炉堡的勘察员塔伯斯·雷矛。', '这个羊皮纸上隐藏着一道精心设计的复杂法术。当然，我能解开它，不过需要点时间。$B$B时间对我而言是很宝贵的。', '还有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (555, '海龟汤', '关于南海镇，你最需要了解的是我们这儿有暴风城以北地区最好的美食！$b$b比如说我的秘密食谱：海龟汤。我听说曾有人远从夜色镇赶来这里，只为品尝一碗海龟汤！不过我最近一直都没做过这种美食。我曾经从达拉然一直走到洛丹米尔湖去捕猎钳嘴龟，不过眼下实在不是外出冒险的时候。如果你从北边那条河里弄点钳嘴龟身上的海龟肉来给我，我就能很快做出点海龟汤来让你大饱口福。', '给南海镇的厨师杰森带去10块海龟肉。', '每个人都会很高兴的，因为他们又可以尝到杰森的海龟汤了!', '找到原料了吗?告诉你吧，这里已经不象原来那么平安了。哎，如果这些动荡从来没有出现过该多好……', '', '去希尔斯布莱德丘陵找南海镇的厨师杰森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (556, '石雕', '达拉然巫师的一项举世闻名的能力就是他们可以操纵如元素生物这样的从其它空间来的强大生物，他们使用魔法石雕作为控制这些元素生物的工具，现在大法师伍德格莱尔想找些石雕来研究。$B$B进入达拉然巫师的领地，去给我找些用旧的石雕回来。$B$B你可以在任何一个达拉然市民的身上找到这种石雕，不过我建议你还是去收容所一带找找，那里可比达拉然安全多了。', '收集10个用旧的石雕，把它们带给塔伦米尔的看守者贝尔杜加。', '这些足够了。虽然看起来它的魔力已经消退了，不过用这种没有活力的样本来开始实验对于魔导师来说是再好不过的了。$B$B谢谢你，$N。', '找到石雕了吗，$N?魔导师很想揭开其中的奥秘。', '', '去希尔斯布莱德丘陵找塔伦米尔的看守者贝瓦里尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (557, '地缚护腕', '大法师会对你带回来的石雕进行研究，不过我知道他会需要一些和石雕配合的东西，也就是地缚护腕。法师们将这些护腕带在元素生物的手腕上，以此来束缚他们。$B$B去干掉几个在达拉然废墟里游荡的元素生物，把它们的地缚护腕拿回来，大法师一定会很满意的。', '为塔伦米尔的看守者贝瓦里尔收集4个地缚护腕。', '你找到护腕了。我相信被你拿走护腕的那些元素都很顺从吧?$B$B嗯……谢谢你，$N。你为魔导师作出了贡献，也就是为黑暗女王作出了贡献。', '你好啊，$N。元素生物是很难对付，不过我知道你肯定可以胜任这个任务。你拿到地缚护腕了吗?', '', '去希尔斯布莱德丘陵找塔伦米尔的看守者贝瓦里尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (558, '吉安娜的签名', '他们说塞拉摩的吉安娜·普罗德摩尔是联盟最伟大的英雄之一。当我长大之后，我也要成为联盟的英雄！$B$B你认识吉安娜吗，$N？你可不可以帮我个忙，帮我弄到她的签名？我不知道怎么向她开口，也许她很忙而无暇顾及我……但是你可以！你是和她一样伟大的冒险者！我打赌她会给你签名的！$B$B求求你了！', '到塞拉摩去，为你看护的孩子拿到一份吉安娜·普罗德摩尔的亲笔签名。', '哦哦!你弄到吉安娜女士的签名了!非常感谢!她还亲笔在这里写了一则短讯息―是给我的!她真是太酷了，我终于拿到她的签名了!也许有一天我会去亲自感谢她……就在我成为联盟英雄的那一天!$B$B你是最棒的，$N。谢谢!', '有一天我要成为吉安娜.普罗德摩尔一样的英雄……好吧，一个男生英雄好了。', '', '去找人类孤儿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (559, '法尔林的证据', '你相信吗，$n？雷德帕斯对咱们杀了那么多鱼人还是不满意——哦，别谦虚了，你在这方面还挺有本事。现在他又要我证明我真的杀过鱼人，他要我把那些冰凉的、粘糊糊的鱼人徽记带去让他过目，这样我才能得到他的肯定。', '南海镇的法尔林·奥里涅尔中尉要你从西部海岸的鱼人身上收集10颗鱼人的徽记。', '哦，以圣光的名义……这些东西还在滴水哪。$B$B让我摸这些东西?呃，我可受不了。鱼是好东西，不过要是它们长出腿还站起来到处行走的话……实话跟你说吧，我已经有几个星期都没吃鱼了。你知道，在南海镇，不吃鱼就等于没有什么可吃的了。', '你为我拿到那些鱼人的头了吗，$N?', '', '去希尔斯布莱德丘陵找南海镇的法尔林·奥里涅尔中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (560, '法尔林的证据', '你知道，$n，我真的不想碰这些鱼人的徽记……既然是你解决了它们，那你能不能再帮我把它们送去给雷德帕斯？', '把一袋鱼人的徽记交给南海镇的治安官雷德帕斯。', '你是为法尔林干活的吗，$g小伙子:小姑娘;?$B$B如果是你帮助法尔林拿到这些鱼人的头的话，那么我对你表示感谢。南海镇的安全需要大家齐心协力来保证。', '欢迎你，$C。你是来帮助我们保卫南海镇的安全的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (562, '升官之道', '我以前在暴风城的导师发来消息告诉我联盟的高级将领已经开始关注纳迦带来的威胁了。根据他打听来的消息，任何人在这方面有所表现的话，都很有可能得到提拔，或者至少是调动工作岗位。$b$b不过有一个小问题……我对付不了纳迦，$n。哦，当然，我能阻止酒吧里的醉汉互相争吵，也能拖走好斗的乞丐，不过纳迦对我来说就太难对付了。你一定得帮我这个忙，$n。', '南海镇的法尔林·奥里涅尔中尉要你去杀掉10个刺脊滩行者和10个刺脊海妖。', '镇压了南海镇的纳迦，这回我就有机会调走了。我终于可以再一次看到暴风城……离开这个被圣光遗弃的海港了!', '我有一封信要交给暴风城的山缪森少校，但首先我得有战功。', '', '去希尔斯布莱德丘陵找南海镇的法尔林·奥里涅尔中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (563, '人事调动', '我的这份报告看来应该是没什么问题了。新的守卫长官萨缪尔森少校曾是我的导师。有了这份报告，他就完全有理由把我调回暴风城了。我需要你帮忙把报告交给他，不过……你可别让雷德帕斯拿到它。', '把法尔林的报告交给暴风要塞里的萨缪尔森少校。', '这是什么?啊……我的学生在对付南海镇的纳迦的战斗中表现出色!谢谢你把这个带来。下个月处理人事调动的时候，我会把这个报告考虑在内的。', '你好，$C。有什么我能为你效劳的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (564, '损失惨重', '没有什么事比失去这些骏马更让我烦心了。相信我，就是那些讨厌的亡灵、可恶的辛迪加恶匪和其它害人的东西在这一带到处游逛，杀了我们不少的马匹。$b$b不过我可以对着我爷爷的墓碑发誓，对这些马匹威胁最大的还是奥特兰克上的山地狮。它们总是从山上跑下来给我捣乱！$b$b你觉得自己是个英雄？那就去做点什么来证明吧！', '南海镇的达伦·玛尔维要你杀掉8只山地狮和10只巨型山地狮。', '真是好消息!我早就该找一个像你这样的英雄来帮我看马厩!你父亲会为你骄傲的，$N。', '山地狮隔三岔五地捕食我们的马，而你只管站在这儿聊天吹牛。$B$B要想证明自己是个真正的英雄，你就少说些废话多做些实事吧。', '', '去希尔斯布莱德丘陵找南海镇的达伦·玛尔维。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (565, '巴图罗的雪人毛皮披风', '我，伟大的巴图罗，将为你做一件闻名世界、全联盟皆知的雪人毛皮披风！$b$b不信你就到处跑跑看，能不能再找件更棒的。每个人都会说：“巴图罗，没有比这更好的披风了！”当然，当然没有。$b$b巴图罗需要一个毛布卷，一件由技艺高超的制皮匠缝制的山地披风，一股细线，当然还要有雪人的毛皮！把这些东西带给我，我就让你看看我的本事！', '给南海镇的巴图罗·吉塞提找一个毛布卷、一件山地披风、一股细线和10块雪人的毛皮。', '现在，伟大的巴图罗要施展他的魔法了!我不需要巫师的法杖或是法师的魔棒。我是伟大的巴图罗，只要针线就可以施展华丽的魔法!', '你回来见伟大的巴图罗了。是不是已经找齐了做雪人毛皮披风所需的材料?要不然就是你专门来称赞我巴图罗的伟大?', '', '去希尔斯布莱德丘陵的南海镇找巴图罗·吉塞提。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (566, '通缉：瓦杜斯男爵', '高级执行官达萨利亚发出命令，通缉名叫瓦杜斯男爵的人类，此人对被遗忘者犯下了重罪。瓦杜斯是辛迪加组织的高级人物。$b$b最后一次有人见到他是在塔伦米尔北部的奥特兰克山高地上。$b$b杀死他，然后带着他的徽记去见高级执行官达萨利亚换取报酬。', '杀了瓦杜斯男爵，把他的徽记带给塔伦米尔的高级执行官达萨利亚。', '做得好，$N.瓦杜斯男爵一死，辛迪加的领导人就又少了一个。他们的抵抗也坚持不了多久了。', '啊，$N。你是不是杀掉了瓦杜斯男爵来拿赏金的?', '', '去希尔斯布莱德丘陵找塔伦米尔的高级执行官达萨利亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (567, '危险！', '危险！$b$b以下这个希尔斯布莱德人是危险人物，已被高级执行官达萨利亚悬赏捉拿：$b$b通缉犯书记员赫拉斯·怀特斯蒂德杀害了亡灵卫兵托马。$b$b通缉犯平民维尔克斯杀害了药剂师埃利。$b$b通缉犯矿工哈克特杀害了亡灵卫兵弗雷。$b$b通缉犯农夫卡拉巴伏击运往幽暗城的物资。$b$b这些敌人都躲藏起来了，很难找到，杀掉他们有重赏。', '塔伦米尔的高级执行官达萨利亚悬赏通缉书记员赫拉斯·怀特斯蒂德、平民维尔克斯、矿工哈克特和农夫卡拉巴。', '你是个出色的赏金猎手，$C。干得好。', '嗯?', '', '去希尔斯布莱德丘陵找塔伦米尔的高级执行官达萨利亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (568, '格罗姆高保卫战', '向你致敬，$c！$b$b你来得真是时候。身为酋长委派到这个丛林基地中的指挥官，我肩负着保卫所有部落成员安全的光荣使命，我们在此的任务是保证对斯通纳德的供应线不被此地的怪物所侵扰。$b$b因此，我将委任你来负责减轻格罗姆高附近的迅猛龙给我们带来的威胁。当你取得了显着的进展后，就向我复命吧。', '格罗姆高营地的指挥官阿格罗戈什要求你杀死15只鞭尾迅猛龙。', '你光荣地完成了你的任务，$C。', '我们的补给线仍然经常受到这些凶猛的迅猛龙的攻击，$C。', '', '去荆棘谷找格罗姆高营地的指挥官阿格罗戈什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (569, '格罗姆高保卫战', '在第一次进入这片丛林中的时候，我们根本就没想和当地的土着部落发生任何冲突。我们任务中最重要的部分就是保持对斯通纳德的供应线的畅通。但当前的情况很复杂，附近的一群食人魔占领了格罗姆高东南方的米扎废墟。他们从来就没把我们的警告放在眼里，频繁地伏击我们的补给车队。$b$b我授命你去解决掉这群冥顽不化的食人魔。$b$b到米扎遗迹去吧，就算不能把他们驱逐出这片地区，至少也得让他们好好尝尝苦头。', '格罗姆高营地的指挥官阿格罗戈什要求你杀死10个食人魔蛮兵和5个食人魔巫医。', '干得好，你光荣地为大酋长完成了任务。', '你有没有到米札废墟去收拾那些巨魔啊，$C?', '', '去荆棘谷找格罗姆高营地的指挥官阿格罗戈什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (570, '摩克萨尔丁的魔法', '部落必须意识到丛林中蕴含着的无尽的魔法力量，并尽快学会利用它来为自己服务。到当前为止，我的仪式都是很成功的，现在我已经能够施放很强大的魔法了。勇敢的$c，我决定为你制作一件特殊的魔法物品。$b$b给我找一些深喉猎豹的爪子和一颗雌虎的牙齿来，不过你要注意，并不是任何牙都可以用的。你必须找到品质最纯正的牙齿才行。$b$b这种野兽一般都潜藏在丛林中，但你在附近也能找到，只要从米扎废墟那边渡过河流，然后向东南方走就行了。', '格罗姆高营地的先知摩克萨尔丁要求你给他带回8只深喉猎豹的爪子和一颗雌虎的牙齿。', '你对丛林的了解已经非常透彻了，$N。这些材料都很完美。森林之灵竟愿意为部落的事业而牺牲如此优秀的野兽，我会感谢它们的。', '有什么好消息吗?', '', '去荆棘谷找格罗姆高营地的先知摩克萨尔丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (571, '摩克萨尔丁的魔法', '现在我要你去寻找一件非常难以得到的物品。$b$b为了将这些羽毛、爪子和牙齿中的魔法力量连接在一起，我必须要创建一个魔法阵，而这魔法阵只有用成年猩猩的肌腱才能做成。$b$b具体说来，老迈的薄雾谷猩猩身上的肌腱就很合适。他们一般栖息在藏宝海湾的东面。$b$b你必须找到足够新鲜健康的肌腱才行，这就是说，你有可能要杀死很多大猩猩才能找出一条合我心意的肌腱来\r\n。', '给格罗姆高营地的先知摩克萨尔丁带回1根成年大猩猩的肌腱。', '这是条非常合适的肌腱，$N。你的努力马上就要见成果啦。', '运气怎么样啊，$N?找到合适的肌腱了吗?', '', '去荆棘谷找格罗姆高营地的先知摩克萨尔丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (572, '摩克萨尔丁的魔法', '你刚才从那些野兽身上收集到的这些材料只是制造那件强力魔法物品的第一步。在我使用萨满仪式将这些物品合成之后，你就会得到一件极为有用的工具，它可以帮你更好地为酋长和部落效力。$b$b但你先得帮我收集一些丛林捕猎者的羽毛来，据说迅猛龙将这些羽毛当作它们的臂章。在格罗姆高的南边，离大竞技场不远的地方就有一个迅猛龙部族，你可以到那里去看看。', '给格罗姆高营地的先知摩克萨尔丁带回10根丛林捕猎者的羽毛。', '太好了，我马上就开始处理这些东西。', '你收集到足够的材料了吗?', '', '去荆棘谷找格罗姆高营地的先知摩克萨尔丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (573, '摩克萨尔丁的魔法', '现在我们只差最后一种材料就可以完成这个魔法了。$b$b向南走到一处面对西侧海岸的高崖之上，你会发现一处圣泉。这处圣泉是许多学者争论的焦点，艾泽拉斯上的所有种族都认为这泉中的水乃是神为他们的子民所创造的。$b$b给我带一瓶圣泉的水回来，这是我给你的最后一个任务啦。不过，你得小心点。有一群纳迦卫兵正守在圣泉的附近，你得先对付他们才能取到泉水。', '格罗姆高营地的先知摩克萨尔丁要你去取回一瓶圣泉之水，同时还要求你杀死10名纳迦探险者。', '有了圣泉之水，魔法仪式便可以开始了。$B$B以自豪的心情戴上它吧，$N，以大酋长之名，为部落而战!', '我差不多已经准备好了，你达成我的要求了吗?', '', '去荆棘谷找格罗姆高营地的先知摩克萨尔丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (574, '特种部队', '如今我们已经在很大程度上削弱了他的正规部队，但这就意味着你得直接去面对他手下的精锐部队。如果那些家伙没有被派出去袭击我们落单的士兵的话，他们就应该驻扎在库尔森营地后山上一处名为“储藏室”的洞穴里。$B$B我私下里认识许多库尔森的手下，他们都是身经百战的老兵，对库尔森忠心耿耿，而且最要命的是，他们对敌人毫不手软。这对你来说恐怕不是个简单的任务，$N。多加小心。$B$B你战胜了他们以后，就去向我的长官多伦上尉复命吧。', '杀掉10名库尔森特种兵和6名库尔森精神医师。$B$B然后向反抗军营地的多伦上尉复命。', '$N。尤瓦中士充分信任你的能力，而我则充分信任她。你能击败库森的特种部队实在是让我们喜出望外，我一直害怕我们只能孤军奋战，只能被上校优秀的战术和士兵彻底压制。$B$B现在看来，我们生存的希望又增加了一些。', '尤瓦中士告诉我你非常勇敢，而且很有作战经验，$C。你有什么要向我报告的吗?', '', '去荆棘谷找反抗军营地的多伦上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (575, '供与求', '“前无古人，后无来者，南海一带最好的也是世界最好的皮匠。”他们就是这么叫我的。我！崔斯里克！最好的皮……呃，好吧。$b$b我的皮货以质量优质而远近闻名，都是鉴赏家们的首选之物！$b$b我最近收到了来自工匠行会的雷德沃克斯主管的订单，他需要十二双刨花皮靴。啊，就是那种由我制作的、非常抢手的靴子。$b$b不过要想做那种靴子的话，我需要一些鳄鱼皮才行。在荆棘谷北边的河边有很多鳄鱼，你看能不能……', '收集2张淡水鳄的皮，把它们交给藏宝海湾的崔斯里克。', '这些皮我看应该够了。既然是用来做靴子里的鞋垫，那它们的品质就不是非常重要的啦，但至少要足够舒适才行。$B$B不过这皮看来有点硬，我得用些老虎的血来把它们弄得柔软一些。无奸不商，无商不奸，你懂吗?', '其它的东西我早就准备好了，$N，就差那些皮啦。我们可不能让雷德沃克斯等太久，对吧?$B$B要是让这位技工协会的首席发明家等得不耐烦了，我可要吃不了兜着走啊。', '', '去荆棘谷找藏宝海湾的崔斯里克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (576, '海盗的眼睛', '站住！谁在那边？$b$b啊，如果没有那只特制的魔法眼，我就是个废人了。当初在一次战斗中，我失去了我的眼睛！但幸运的是，我们的船停靠在米奈希尔港时，一位旅行法师送给了我一只特制的玻璃眼，这样我才又能看见东西了。$b$b不过昨天晚上我参加了袭击血帆海盗的行动，在跳出船的时候玻璃眼睛不小心给弄丢了。一定是那帮血帆海盗拿走了我的眼睛！看来他们这群混蛋已经找到了到藏宝海湾来的路。$b$b你能不能帮帮我这个老海盗，把我的眼睛给找回来？', '藏宝海湾的独眼迪兹要求你从血帆海盗那里找回他的眼睛。', '太令我吃惊了，太令我吃惊了!你找到我那美丽的眼睛了!让我看看她还合适不合适。$B$B哈哈!我又能看见东西啦!!', '喂，哥们!虽然我看不见，但你这个小子一进港口我就闻出你的味道来啦。$B$B我的眼睛还能找回来吗?船长知道我的眼睛落在那帮肮脏的血帆海盗手里以后大骂了我一顿。$B$B对我这样的了望员来说，没眼睛的日子可真是太悲惨了!我现在都已经习惯了住在了望台上……要是以后我再也看不见了，非得被发配去洗船舱不可。', '', '去荆棘谷找藏宝海湾的独眼迪兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (577, '收集鳄鱼皮', '嗯，这些靴子已经基本定型，接下来就要开始打磨表面了。但你带来的皮似乎少了点，做不出足够的鞋垫来。$b$b“那现在我们得干什么呢，崔斯里克？”你肯定会马上问这种问题，哈哈，你跟崔斯里克说话可真不幸啊，因为我马上就要给你派活干啦！$b$b没人会去观察鞋垫的，所以我们只要找点又厚又便宜的鳄鱼皮就行了。纳菲瑞提湖旁边的那种钳嘴鳄鱼就不错。', '给藏宝海湾的崔斯里克带回5张钳嘴鳄鱼的皮。', '我的靴子……就跟香肠一样好，$N。多么漂亮的外形，多么舒适的感觉。我跟你说啊，就像是用最好的材料和最好的肉做成的香肠那样，尝试一次，终身难忘呀!$B$B穿它走路很安全，也非常舒适，你得相信我，另外别问我这里面到底用的是什么材料。', '崔斯里克的刨花皮靴，最好的做工，百分之百海鳄皮。没什么比这更好的啦!$B$B简直找不出合适的形容词来形容它，不是吗?$B$B还是说，你把那些皮带来给我了吗?', '', '去荆棘谷找藏宝海湾的崔斯里克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (578, '海潮之石', '如果个岛上确实有水元素和地精法师的鬼魂的话，也就是意味着在那里可以采到海潮之石！$b$b我希望你能找到这座闹鬼的岛屿，去看看上面到底是怎么回事。哦，如果你想知道更多的有关海潮之石的信息的话，可以带着这张凭证去暴风城图书馆，他们会帮你找到我最初读过的那本传说的手抄本。$b$b真的是加兹班首先发现那种石头的吗……?', '为藏宝海湾的大财主里维加兹找到闹鬼的岛屿。', '这么说这个故事是真的啦!真是难以置信!$B$B不过，如果我们想要得到它，还得想办法破除海潮之石上所附加的诅咒。这诅咒是由魔法施加上的，所以我们需要一些巫师来帮我们将它破除掉。', '巨魔确实拥有一些十分神奇的魔法物品，$N。现在，没准我也有机会将这其中的一两件纳入到我那令人称羡的收藏品之中。你找到这条传闻的源头了吗?', '找到闹鬼的岛屿', '去荆棘谷找藏宝海湾的大财主里维加兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (579, '暴风城图书馆', '', '', '这些书名里有你感兴趣的吗，$N?', '瓦里安王十分重视教育，他投入了很大一笔资金用于各种书籍卷册的抄录，并允许平民们自行抄录。很简单，你只需向我出示图书馆的阅览证，我就可以给你一本允许借阅的书的手抄本。', '', '去找艾尔文森林的丹亚·托瓦尔德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (580, '威士忌斯利姆的酒', '我们那天喝醉了，结果从很远的辛特兰那边掉下了船，活活地漂到了望海崖这里来，险些喂了鱼。$b$b而且我斯利姆从小就没怕过水！我们船长从一艘去暴风城的私掠船上抢来了一箱紫葡萄酒。$b$b我们在辛特兰被风暴袭击的时候，我东倒西歪地撞碎了那个箱子，结果那里面的酒在大风大浪里全都掉进海里了。我要是不把它们给找回来的话，船长见了我非拿我喂猫不可！帮帮我吧！', '藏宝海湾的威士忌斯利姆想要你帮他找回弄丢的紫葡萄酒。', '太令我惊讶了!你找到了船长的酒!$B$B我太崇拜你啦，朋友。$B$B看来外面快要起一场大风暴了，或许我应该先喝上一瓶暖暖身子……', '淹死我吧!我快要在这里醉死啦!船长要起锚，老斯利姆就得被丢在塔纳利斯沙漠里变成人干了呀。他要是发现他的酒没了……啊呀!', '', '去荆棘谷找藏宝海湾的威士忌斯利姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (581, '耶尼库的下落', '厄运！厄运降临在我们酋长的小儿子耶尼库身上……按照部族里的习俗，他被过继给了祖尔格拉布的巨魔，但我们暗矛部族随后便决定跟随兽人酋长萨尔离开家乡，可怜的耶尼库就此与我们失去了联系。我是从奥格瑞玛回到荆棘谷来的，我回来寻找我们酋长的孩子。$B$B我相信是血顶部族抓住了他。$B$B如果你愿意帮助我的话，就去干掉血顶部族的那帮家伙吧，他们就在北边。把他们的獠牙给我带来。', '给格罗姆高营地的尼姆布亚带回9根血顶巨魔的獠牙。', '这些獠牙的品质证明你杀的都是健康强壮的家伙，$N。通过对血顶部族的猎杀，你已经证明了自己的能力。$B$B这很好，因为你还要为我们继续做些别的事。', '$C。给我血顶部族的獠牙，以此来证明你确实猎杀了他们。$B$B快把你的战利品给我看看。', '', '去荆棘谷找格罗姆高营地的尼姆布亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (582, '狩猎行动', '我们必须弄清楚耶尼库是否还活着。$B$B杀掉一些血顶部落的猎头者，并把他们身上挂着的皱缩的徽记给我取回来。你必须要收集尽可能多的首级回来，这样我才能检查一下耶尼库的头在不在其中。$B$B如果耶尼库真的被血顶氏族给杀了，他们的酋长，那个名叫甘祖拉恩的家伙，就一定会遭受长达600年的恶毒诅咒！$B$B去吧，$N。沿海岸北上，在祖丹亚废墟和祖昆达废墟那里就有很多血顶猎头者在活动。', '给格罗姆高营地的尼姆布亚带去20个皱缩的徽记。', '谢谢你，$N。我会仔细检查这些首级，希望可怜的耶尼库没有被那帮猎头者杀害。', '$N。我一直在担心着我们酋长的儿子。你收集了多少个皱缩头颅供我检查?', '', '去荆棘谷找格罗姆高营地的尼姆布亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (584, '血顶徽记', '感谢蛇神，耶尼库的徽记并不在当中。但我们仍不清楚他的状况……$B$B我们必须知道真相，不过，恐怕只有血顶氏族的酋长和巫医才知道这些事，而他们又是我们暗矛部族的敌人，所以他们是绝对不会老老实实地告诉我们真相的，恐怕他们只有在死了以后才会愿意和我们谈谈！$B$B把甘祖拉恩和奈兹里奥克的徽记给我带回来，然后放进这个锅里去。$B$B他们就躲在祖昆达废墟里的深处。只要有他们的徽记……我们就能和他们好好谈谈了。', '将甘祖拉恩的徽记和奈兹里奥克的徽记带回格罗姆高营地，放入冒泡的大锅中。', '你将甘祖拉恩和奈兹里奥克的头放入了这口大锅中……', '冒泡的大锅中装着满满一锅绿色的肉汤。', '', '去荆棘谷找格罗姆高营地的冒泡的大锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (585, '奈兹里奥克', '<奈兹里奥克的头说话了>$B$B没错，我知道那个暗矛部落的孩子被带到什么地方去了。虽然你杀害了我，而且把我的灵魂也束缚了起来，但要是你们不给我点好处的话，我还是什么都不会说的！$B$B血顶部族正在与劈颅部族交战，要想让我帮忙，就从劈颅部族那里偷来3颗徽记来，放在这里陪着我，这样我在扭曲虚空之中也就有三个奴隶啦。这三个徽记必须分别从他们在巴里亚曼废墟、赞塔加废墟和祖玛维废墟的徽记堆中拿来。', '带回巴里亚曼战利品、赞塔加战利品和祖玛维战利品各一个，把它们放入格罗姆高营地里中的冒泡的大锅里。', '很好，他们可以成为绝佳的奴仆……等我的灵魂被你们释放了之后，我就会和这三个奴仆一起去扭曲虚空!$B$B你对你的$r氏族来说一定是个值得信赖的成员，并且，你也确实待我不薄。', '我等着你拿来那些头颅……', '', '去荆棘谷找格罗姆高营地的冒泡的大锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (586, '甘祖拉恩', '<甘祖拉恩的徽记开始发出声音>$B$B我要诅咒你！诅咒你的祖先！$B$B只有鲜血和复仇才能平息我的愤怒，如果这是你的意愿的话，那么……这么办吧：$B$B到东边的劈颅部族的老窝去，要是你够强的话……就干掉他们的酋长，野蛮的安纳希克。嘿嘿，把他的盔甲碎片拿来给我看，不过我很怀疑你的能力！$B$B他肯定会把你打得落花流水的，哈哈哈！', '杀死8名劈颅猎人、6名劈颅猎头者和4名劈颅狂战士。$B$B将安纳希克的盔甲碎片放入格罗姆高营地中的冒泡的大锅里。', '我真是不敢相信你居然完成了这任务，但是我不会食言。既然连安纳希克也被你打败了，我也就没那么愤怒了。$B$B你强大的实力将会把你推向一个伟大的巅峰，$N。不过总有那么一天……我会在扭曲虚空之中再碰见你，那时我们定要再比试比试。$B$B我会等着你的。', '虽然我的眼睛鼻子耳朵全都给煮没了，但我还是能感觉到你在害怕。$B$B哈哈!你就是死也不可能完成这个任务……', '', '去荆棘谷找格罗姆高营地的冒泡的大锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (587, '鼻烟', '啊，海上的生活。我不想说这种生活有多美好，但这就是我的生活。$b$b当我每次入港的时候，我都会找个地方好好喝上一杯，再找点高品质的鼻烟抽抽。坏习惯吧，但海盗们怎么能没有坏习惯呢，对吧？$b$b所以你可以想象一下，当我发现镇上的药草师卖完了他的全部鼻烟并且已经离开了这座小镇的时候，我会有多沮丧有多伤心了！据说给他运货的那条船让那些该死的血帆海盗给抢劫了。$b$b我相信像你这样勇敢的$c，一定能说服他们交还船上的货物，对吧？', '藏宝海湾的迪格要求你带给他15份鼻烟。', '好极了，$N!正好我马上就要出海了!真是不知道该对你说些什么好，哥们。', '运气如何?找到那些东西了吗，伙计?', '', '去荆棘谷找藏宝海湾的迪格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (589, '歌唱水晶', '传说荆棘谷的中心地带深藏着一块宝石，这块宝石的名字叫心灵之眼，其中蕴涵着巨大的力量。如果你得到了这块宝石，也许我们就能用它将失落于黑暗之中的耶尼库拯救出来。$B$B我会与丛林之灵们商谈，向他们询问心灵之眼的位置。与此同时，你要去一趟东南方的水晶矿洞，从那里的铁腭蜥蜴身上收集一些蓝色波光碎片。这些水晶非常稀有，但我们需要利用其中的魔法能量来控制心灵之眼。', '给格罗姆高营地的肯维雷带回3块蓝色波光碎片。', '你干得很不错，$N。这些水晶的品质非常好，我甚至可以听见它们在对我唱歌。$B$B在你离开的时候，我已经与丛林之灵谈过了。我已经知道了心灵之眼在什么地方……$B$B……还有谁在守卫着它。', '你弄到水晶了没有，$N?我们得到心灵之眼后要举行一个仪式，这些水晶是仪式必需的材料。', '', '去荆棘谷找格罗姆高营地的肯维雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (591, '心灵之眼', '心灵之眼当前落在了一个食人魔法师的手里，他就住在东边的莫什奥格食人魔山的深处，他的名字是麦佐斯。我自暗矛部落还在荆棘谷定居的时候就知道他了，他是一个邪恶的家伙，而且法力非常强大。$B$B如果确实是他拿着心灵之眼的话，他的魔法就会具有极大的威力。$B$B你必须从这个麦佐斯的手中抢到心灵之眼。这确实是件危险的工作，但这也是我们拯救耶尼库的唯一希望了。', '将心灵之眼交给格罗姆高营地里的肯维雷。', '你真的拿到它了!你将成为传说中的英雄，$N!$B$B你一定是战胜了麦佐斯并把他送入了扭曲虚空才得到心灵之眼的吧，难怪丛林之灵们再也不提及他了。$B$B他离开了我们所存在的实体世界，却又进入了灵魂的国度……恐怕他又会在那里兴风作浪……$B$B但这不是我们现在应该担心的了。现在，我必须马上进行仪式，让心灵之眼的力量可以为我们所用……', '你好，$N。自我将你决定去对付麦佐斯的事情告诉了丛林之灵后，他们一直在歌颂着你的英勇与无畏。$B$B你拿到心灵之眼了吗?', '', '去荆棘谷找格罗姆高营地的肯维雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (592, '拯救耶尼库', '我已经将心灵之眼重塑为一颗灵魂宝石。你必须先用它震慑住耶尼库，成功之后，就立刻把宝石放在他的额头上，这样才能抽取出他的灵魂。$B$B接下来把宝石交给尼姆布亚就可以了。$B$B耶尼库和流亡者赞吉尔一起住在阿博拉兹废墟，只要沿着水晶海岸走到荆棘谷的海角那边就能找到了。', '将装满的灵魂宝石交给尼姆布亚。', '你成功了!你将耶尼库从赞吉尔的控制之下解救了出来，并完成了一个在我看来是如此凶险的任务。$B$B我们部族会将你的名字写入战歌之中，$N，我们会将你的传说刻入石头上，永世流传。', '$N。肯维雷告诉我你已经出发去对付耶尼库了。$B$B这是真的吗?你抓到他了吗?', '', '去荆棘谷找格罗姆高营地的尼姆布亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (593, '灵魂宝石', '', '', '你将灵魂宝石放在了耶尼库的额头上。当他的灵魂被抽离他的躯体而进入宝石的时候，他空虚的躯壳开始不停地发颤。', '耶尼库呆若木鸡地站在你的面前，他的意志仿\r\n佛在另一个世界里漂游……', '', '去找荆棘谷的耶尼库。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (596, '染血的白骨项链', '我是被派来格罗姆高帮助尼姆布亚完成他的任务的，但……我发现这里还有些更有意义的事要做。$B$B血顶部族是我们的敌人。将敌人的战利品抢过来将极大地鼓舞我们的士气，同时也能给对方以沉重的打击。也许你可以帮我们部族猎杀血顶部族的成员……$B$B他们就居住在北边，干掉那些血顶巨魔，把染上它们鲜血的白骨项链给我拿回来。你拿回来越多项链，我们就会越尊敬你。', '给格罗姆高营地的肯维雷带回25串染血的白骨项链。', '啊，很好。我会先这些项炼给煮了，然后再蒸了它们，最后把它们碾成粉末，这样项炼主人的精神就会变得虚弱无比!$B$B给你，$N。这是你应得的酬劳，这样我们就两清了。', '血顶部族总有一天会被我们暗矛部族彻底粉碎!你把他们的项炼拿回来了吗?', '', '去荆棘谷找格罗姆高营地的肯维雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (598, '裂骨项链', '你已经收集了足够多的血顶氏族的战利品，现在我要交给你一项新的任务。劈颅部族居住在东南方，以前我们一直和他们互无往来。虽然暗矛部落已经不住在荆棘谷了，但现在我们却卷入了与他们的冲突之中。$B$B所以，我要你去猎杀他们，把他们的裂骨项链带回来给我。如果你在我们这场战争中帮助了我们暗矛部族，就一定会赢得我们的友谊。', '给格罗姆高营地的肯维雷带回25串裂骨项链。', '果然，你拥有强大的力量，$N。劈颅部族碰上你，就像小树苗碰上巨大的蜥蜴一样，被一脚踏平了!$B$B你帮了我们一个大忙。', '劈颅部族将我们拖入了战争中，他们定会遭到诅咒!你完成任务了吗?', '', '去荆棘谷找格罗姆高营地的肯维雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (600, '风险投资公司', '最近，风险投资公司在荆棘谷一带展开了一系列的行动，这让我们这些诚实努力的地精们，你看，比如我，根本没办法在这里讨生活了！拜托，你一定要帮帮我！$B$B风险投资公司打算在北边的水晶矿洞那里采矿，可是由于那边的石化蜥蜴到处肆虐，他们根本没办法进入矿洞，只能在周围的山上开采歌唱水晶。$B$B去把他们的水晶都抢来，让他们知道他们不该在这片丛林里如此嚣张。$B$B还有……嗯嗯……把那些水晶给我带回来当证据！', '给藏宝海湾的克兰克·菲兹巴布带回10块蓝色歌唱水晶。', '太伟大了!太神奇了!我竟然搞到了这么多的水晶!!$B$B风险投资公司实在是找错了采矿的地方，对不对?要是他们走了，我们就能过得更好点了。$B$B谢谢你，$N。你今天干得确实漂亮。', '你弄到多少水晶啦??我需要它们!!$B$B呃，其实我的意思是……我必须要确切地知道那邪恶的风险投资公司已经失去了在荆棘谷立足的根基。因为，你知道，我们这些老实人也得养家糊口啊!', '', '去荆棘谷找藏宝海湾的克兰克·菲兹巴布。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (601, '水元素', '这些水元素无疑是传说中发现了海潮之石的地精法师加兹班召唤的。也许你知道，海潮之石会诅咒任何挪动它的人，就是说，会让那个倒霉的家伙从这个世界上彻底消失。$b$b应该有什么办法可以破除这个该死的诅咒，我们可以请一位达拉然的法师来帮我们分析一下水元素胳膊上戴着的护腕里的魔法。你能不能回到那岛上帮我收集一些进行魔力分析所需的样本？', '为藏宝海湾的大财主里维加兹收集6个水元素护腕。', '唔，我可不是法师，也不懂该怎么检查出哪些护腕是符合研究要求的，但我想这里面肯定至少有一个是能用的吧。把他们带到达拉然去，请一位法师好好地研究研究它们。$B$B毕竟，我是无法离开藏宝海湾去和那群喋喋不休的老法师们聊天的。$B$B我并不是担心在我离开的时候会有人想要抢了我的生意。事实上，在这儿，胆敢违抗我里维加兹的家伙都活不了多久。', '进度如何了，$N?', '', '去荆棘谷找藏宝海湾的大财主里维加兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (602, '魔法分析', '据我所知，达拉然的法师们已经成功地将那座魔法城市整个搬到了诺森德，原址那里只剩下一座大坑了。不过仍然有一些法师留了下来，你应该能找到一个愿意帮我们检查护腕的法师。根据我对那些法师的了解，他们是绝对不会拒绝任何与魔法有关的谜题的。$b$b将这包水元素的护腕拿给他们，让他们看看能不能找到解除石头上的诅咒的方法。你去找大法师安斯雷姆·鲁因就好了。我以前跟他打过交道，他的学识非常渊博。', '将水元素护腕交给达拉然巨坑的大法师安斯雷姆·鲁因。', '海潮之石?太有趣了!你知道我曾在几年前写了一本关于古拉巴什帝国传说的书吗?我确实对这块石头有所研究。$B$B啊，这其中至少有一个护腕里残留着可供我分析的魔法。$B$B让我看看……', '我现在很忙，你有什么事吗?', '', '去奥特兰克山脉找达拉然巨坑的大法师安斯雷姆·鲁因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (604, '血帆海盗', '克拉兹高度赞扬了你为黑水海盗做出的重要贡献。我信任你，因此我要赋予你一个对于舰队来说至关重要的任务。$b$b我们要求你渗透进血帆海盗创建在蛮荒海岸的南方指挥部。偷袭他们的营地，将他们的海图与计划书都给我带回来，我们必须要搞清楚这群渣滓到底想干点什么。', '藏宝海岸的舰队指挥官卡拉·海角要求你杀死10名血帆流氓并将血帆海图和血帆计划书带回去。', '干得漂亮，$N。现在我们已经了解他们的计画了，粉碎这计画应该也只是时间问题。$B$B既然这帮蠢货就停泊在海岬附近……', '啊哈，$N。你从南边的血帆营地那里带回什么消息啦?', '', '去荆棘谷找藏宝海湾的舰队指挥官卡拉·海角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (605, '歌唱水晶碎片', '歌唱水晶是荆棘谷的一种特产，它对某些人来说有着非常重要的价值。我本想运一些歌唱水晶到别的地方去卖，可那该死的风险投资公司想要独占它，所以，像我这样诚实的商人看来就无法亲自去收集水晶了！$B$B我决定雇佣你。$B$B荆棘谷中的蜥蜴都有吞食这种水晶的习性，这可以使它们的皮肤变得更硬。因此，我们可以从它们身上收获到一些高品质的水晶。$B$B随便哪只蜥蜴身上都会有水晶，但最容易对付的是在北边的海岸附近活动的那些蜥蜴。', '为克兰克·菲兹巴布收集10块歌唱水晶碎片。', '啊哈!这些碎片非常合适，$N。嗯，品质非常好!$B$B这是你应得的报酬，还有……跟你合作非常愉快。', '你拿到那些水晶裂片了吗?我会给你一笔丰厚的报酬的!', '', '去荆棘谷找藏宝海湾的克兰克·菲兹巴布。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (606, '吓唬病鬼', '你知道这里最让我受不了的是什么吗？这儿的人都有死也不还赌债的毛病！现在已经有一大群家伙欠着我的钱了。你能帮我催一下债吗？$B$B第一个要催的就是住在港口那边的“病鬼”菲利普。他上个礼拜欠得实在是太多了，我一定要把这笔钱给要回来！但是要想拿到它，我们就得好好吓唬吓唬他。$B$B到镇子外边去猎杀一些老迈的薄雾谷猩猩，然后从它们身上搞点内脏杂碎什么的，把这些玩意丢给那病鬼。最好别让他想到那是动物内脏，让他想点更糟的。', '给藏宝海湾的“病鬼”菲利普带回5块薄雾谷猩猩的内脏。', '哎呀!你从哪儿搞到这些的?不不，不要告诉我了。我不想知道!$B$B是谁派你来的?海狼?', '嘿，你看我干什么啊，$g小子:小姑娘;!', '', '去荆棘谷找藏宝海湾的“病鬼”菲利普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (607, '向马克基雷回报', '给，把这个布袋给海狼。告诉他，我是想还他钱的！我发誓！！$B$B我只是喝多了点，迷路了而已，还有……总之是一团糟了。他会理解我的——你可别乱说啊！', '将菲利浦的还款交给“海狼”马克基雷。', '嘿嘿，太好啦!对了，你给病鬼看那些东西的时候，他的表情怎么样呀?$B$B哈!他实在是蠢了，跟他玩牌想输比想赢还要难上一万倍呀!$B$B太感谢你的帮助了，$N。给，这是你应得的……', '你好啊，$N。拿到那病鬼的钱没?', '', '去荆棘谷的藏宝海湾找“海狼”马克基雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (608, '血帆海盗', '打击一下菲尔拉伦的脆弱神经吧！他连划着小船穿越水晶湖都做不到，更别说独自率领整支舰队来和我们对抗了。$b$b血帆海盗一定会为他们的粗心大意而付出代价的。现在我们已经掌握了他们的攻击计划，完全可以在他们什么还都不知道的时候抢先下手。$b$b我们并不需要派出全部的舰队，只要一支勇敢的冒险者队伍就能轻易完成这任务。$n，带上你最优秀的同伴守在菲尔拉伦的登陆点，杀掉血帆的指挥官。这样他们的舰队不用多久就可以去喂鱼了……', '藏宝海湾的舰队指挥官卡拉·海角要求你杀死血帆海盗的斯蒂沃特船长，尼哈鲁船长和舰队指挥官菲尔拉伦。', '啊，今天对我们黑水强盗来说真是伟大的一天!恭喜你，$N!', '有什么问题吗，$N?我们得在血帆海盗发起进攻前先下手!', '', '去荆棘谷找藏宝海湾的舰队指挥官卡拉·海角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (609, '讨债行动', '我这儿的白条已经少了许多啦，但还是有许多没信誉的家伙欠着我的钱。$B$B接下来，我们得对付“畸形足”玛雷·维尔金斯、火柴棍乔乔，还有拇指苏克。$B$B这帮家伙的债欠了好久，我看他们是不想还了！后来，我听说他们被什么人给骗到丛林里去了。我当然不关心他们到底会怎么样——我要的是我的钱！$B$B他们应该就在东北方的阿博拉兹废墟和朱布瓦尔废墟里。找到他们，把我的钱拿回来。', '给藏宝海湾的“海狼”马克基雷带回玛雷的畸形足、乔乔的金色望远镜和苏克的巨型戒指。', '太好啦!把这些东西卖掉之后，我就可以狠赚一笔了，特别是玛雷的这条木脚里的东西，值钱得很!非常感谢你，$N!$B$B我希望这下他们三个能学会“欠债还钱，天经地义”这个理儿。$B$B还有，虽然听起来有些马后炮，但我还是要说，这帮家伙也该戒赌了。', '$N，你找到那三条狗没?把他们身上值钱的玩意都抢过来没?', '', '去荆棘谷找藏宝海湾的“海狼”马克基雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (610, '帅小伙子邓肯', '我老爸派你来的？我还以为那怪老头已经早就放弃掉我了呢。$b$b我之所以离家出走确实不是他的错，他只是不应该为我安排好一条乏味的人生道路，并希望我欣然接受它。我怎么能忍受整天读着那些发霉的书本，整天和那帮灰头发加驼背的乏味老头法师们在一起！$b$b如果你需要我的匕首，你可能得从一个叫“帅小伙子”邓肯的血帆海盗那里夺回来。我想你只要教训教训他，他就会屈服的。', '从“帅小伙子”邓肯那里夺回凯特琳的匕首。', '你击败了邓肯?我第一眼看到你的时候还以为你很嫩呢。$B$B看来我暂时还不应该挑战你!', '我以前从没有被打败过，你知道吗，$N?我的确被砍到了，斗刀的时候受点小伤是难免的，但他突然打了我一拳，正好敲在了我脑袋上，一下就把我给打晕了。等我醒来的时候我的匕首已经没了。$B$B正如我的绰号一样，我仍然需要一把匕首才能参加以后的战斗，而且，对我来说，那把匕首无疑是最好的。', '', '去荆棘谷找藏宝海湾的利刃凯特琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (611, '海潮的诅咒', '这么说你正在寻找某个祭坛喽？好吧，虽然我不像我老爸那样是个研究巨魔遗迹的专家，但我对你正在寻找的岛屿也略知一二，在岛的附近有一座沉没在水底的巨魔城市，我想你应该到那里去碰碰运气。$b$b既然是你帮我找回了我的匕首，借去用用当然没有任何问题……但我希望你用完以后能还给我！', '用凯特琳的匕首摧毁海潮祭坛，然后杀死加兹班，将海潮之石带给大财主里维加兹。', '太令人惊讶了!海潮之石!它一定会成为我所有的古代巨魔器物收藏中最为耀眼的一个。你看这表面，就像是一道巨浪被禁锢在上面。太漂亮了!', '你为我拿到海潮之石了吗，$N?我已经在我的收藏室里腾出了一块不错的地方准备用来摆放它了。', '', '去荆棘谷找藏宝海湾的大财主里维加兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (613, '玛雷的腿', '该死！那见鬼的玛雷居然在他的假腿上安了一个锁，我还死活都打不开！他的宝贝，还有他欠我的钱，都藏在那条假腿里！$B$B我们得想办法找到钥匙才行。玛雷这家伙过去因为喜欢和住在东北边食人魔山上的莫什奥格食人魔赌博而出名，而且他告诉过我——我是说当他还活着的时候——他每次赢了一票大的之后都会去一趟那里，所以，或许那边的食人魔会有他的钥匙。$B$B要真是如此的话，你八成得大开杀戒才能搞到钥匙……', '把玛雷的钥匙带给藏宝海湾的“海狼”马克基雷。', '你找到它了!万分感谢，$N。你帮了我一个大忙!$B$B这是你的应得的，拿着吧!', '啊哈，$N!你找到玛雷的钥匙了吗?', '', '去荆棘谷找藏宝海湾的“海狼”马克基雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (614, '船长的箱子', '我过去在一条专跑从这里到卡利姆多的棘齿城的航线上干过。我是个很优秀也很有名望的船长。$B$B直到……$B$B那些该死的海巨人毁了我的生活！他们打沉了我的船，杀光了我的水手，把我丢在一条救生艇上，让我漂回了藏宝海湾。还有，其中一个名叫高拉什的巨人还把我的箱子给偷走了，他说要拿这东西当鼻烟盒，简直是神经病！$B$B我听说有人看见高拉什最近在东边的海岸一带闲逛。找到他，把我的箱子给抢回来！快去，你会得到一位船长的敬意的。', '将斯莫特的箱子交给藏宝海湾的海克拜瑞·斯莫特。', '你找到它啦!啊，今天我太高兴啦!谢谢你，$N。得到这个箱子之后，我内心里的愤懑也就平息了。$B$B但我还是要复仇……', '你好啊，$N!你找到高拉什了吗?那箱子是我最喜欢的，里面有个小夹层，我最值钱的宝贝都藏在里面!', '', '去荆棘谷找藏宝海湾的海克拜瑞·斯莫特船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (617, '一捆海蛇草', '听说你正在找活做，$N？要是你够胆的话，我这儿倒是有件不错的活正要找人呢。$B$B你听说过最近有许多人都在找一处泉水么？是的，有一群纳迦也在找。我有个叫格罗伊的朋友吧，他最近出了一大笔钱，想买一些纳迦称之为海蛇草的东西。我也不清楚那到底是什么，只知道是一种很值钱的海草。他也没说要那玩意干什么，不过他确实出了一个好价钱，大概需要一捆吧。$B$B你帮我搞来10根这种什么草，那我们就可以跟他做笔交易啦。不久前有人看见这里北边的海滩上出现了不少纳迦。', '给藏宝海湾的海盗布劳兹带回10根海蛇草。', '干得好，$N。收集10根海蛇草其实也没什么难度，对吧?咱们倒也不是和纳迦有仇，嘿嘿，不过，咱们也得讨生活呀。', '要是你不想和我进行交易，那就请便吧，$N。', '', '去荆棘谷找藏宝海湾的海盗布劳兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (618, '挑战奈古拉什', '奈古拉什总是一副随时准备把一切都吞下去充饥的样子。$B$B那些巨人袭击我们的船的时候，奈古拉什直接冲向了我的厨房，不过他可不像其它巨人那样喜欢吃人。奈古拉什要的是酒……还有我秘制的烧烤秃鹰翅膀。嘿，这可都是我的拿手菜，我当年可是跑到荒芜之地才弄到这食谱的！$B$B如果你想把奈古拉什给引出来，只要用点酒再加上一碟烤翅就行啦。把这些东西放进我们当初丢在东南边海岸上的救生艇里，然后你就等着奈古拉什闻到食物的味儿乖乖上钩吧！', '将10块烧烤秃鹰翅膀和5瓶密林葡萄酒带到斯莫特船长的救生艇上去。$B$B然后杀死奈古拉什，将斯莫特的弯刀交给荆棘谷的斯莫特船长。', '你把我的弯剑从奈古拉什那儿抢回来啦!我简直不敢相信这是真的，$N!自从见到你之后，我似乎就时来运转了呀，没错，肯定是这样的!$B$B谢谢你!以后，要是我能再搞到一条新船的话，你要出海就尽管来找我，我让你随便坐，你永远都是我最欢迎的客人!', '把我的弯剑抢回来没有，$N?', '', '去荆棘谷找藏宝海湾的海克拜瑞·斯莫特船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (619, '引诱奈古拉什', '', '', '你把食物和酒放在了救生艇里……', '这是一条已经被遗弃了很久的救生艇。小艇的两舷上布满了划痕，油漆的字迹已经显得很斑驳了:$B$B“斯莫特的复仇”', '', '去找荆棘谷的破损的救生艇。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (621, '赞吉尔的秘密', '流亡者赞吉尔和他的追随者们住在藏宝海湾东北方的朱布瓦尔废墟和阿博拉兹废墟里，这个家伙已经被他的部族放逐了。为什么？这个……$B$B据说是因为赞吉尔掌握了某种可以将自己的心灵与他人连接在一起的方法，而他所属部族的领袖就因此非常害怕他。他让他的追随者们喝下了一种从植物中萃取出来的液体，用它来压抑他们的自我意识并加强他们的力量。$B$B他的这种药剂对那些试图控制别人的家伙来说有非常大的价值。$B$B给我弄些这种药剂的样本来，我要研究一下……', '收集12份赞吉尔的药剂，把它们交给藏宝海湾的克兰克·菲兹巴布。', '啊，太好了!这是你的报酬。$B$B为了表彰你优秀的表现，我还有些额外的小奖励给你……', '你拿到了赞吉尔的药剂了吗?', '', '去荆棘谷找蛮荒海岸的克兰克·菲兹巴布。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (622, '向卡雷布下士回报', '在你离开的这段时间里我已经把这锅替你修好啦。我甚至还免费加装了一个特制的蒸汽哨，看，华丽吧！这下面还装了一个新的自动菜刀，专门用来切蹄膀的！$B$B没错，克拉兹克的烹调锅将为你带来百分之百的烹调乐趣，我敢打赌它的主人会非常满意的！', '将修理过的烹调锅交给叛军营地的卡雷布下士。', '哈，修好啦!真棒，现在我马上就可以开始准备晚饭啦!太感谢你了，$N。$B$B我希望你在藏宝海湾过得太平。这地方可是越来越糟糕啦，还有……我听说现在哥布尔们会把街上那些喝得烂醉的水手们绑到他们的奴隶船里去……$B$B……没人知道他们会被抓到什么地方去，也没人会知道他们被抓去干什么。', '你好，$N。你去过藏宝海湾了吗?克拉兹克把我的锅修好了吗?', '', '去荆棘谷找反抗军营地的卡雷布下士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (623, '一捆海蛇草', '$N，你不在的时候，格罗伊托人给我捎了一个信儿过来。他说他很满意我们上次送去的货，现在又有一位新的顾客也想要一些那种海草。$B$B我可不想花上整整一个礼拜去一趟塞拉摩，如果你愿意替我去一趟的话，那就再好不过了。$B$B很有挑战性吧？你知道那边的尘泥沼泽吧？你可得小心点，塞拉摩可不是个普通人能去的地方。', '给塞拉摩的海盗格罗伊带去一束海蛇草。', '什么?!老子有很多事情要干，随便干点什么也比跟你这种笨蛋说废话强，$C。有事快说，没事就滚。$B$B啥?布劳兹派你来的?真的?好吧，你给我带什么来啦?$B$B<私掠者格罗伊仔细地检查了草束。>$B$B不错，确实不错，我的顾客一定会很高兴的。$B$B我想你的第二个任务应该是把钱给拿回去，是吧，$C?当然啦!$B$B给，拿好这些钱，然后我给你一句忠告:赶紧从我的码头上滚出去。', '啥?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (627, '克拉兹克的要求', '在阿拉希高地北部的枯须峡谷中有一处山洞，那里有一种十分稀有的矿石：血石。那个山洞里的血石虽然不是品质最佳的，但即使是低等级的血石也是很有价值的……当然这只是对那些懂得如何使用它们的人来说。$B$B我需要一些这种血石。$B$B我会在这里修补你的锅子，不过，当我修锅的时候……你去给我弄些血石来吧。对，多带点回来，我当然会给你报酬的。$B$B嗯嗯，要是你连这点事都搞不定，就去找个能搞定的人帮你！', '给藏宝海岸的克拉兹克带去4块次级血石矿。', '啊，漂亮!你帮了我的大忙了。$B$B这是你的报酬……', '你好啊，$N。你找到那些血石了吗?', '', '去荆棘谷找藏宝海湾的克拉兹克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (628, '刨花皮靴', '既然里面的东西都已经做完了，那么就只剩下外面的表层部分了。表层一定要用质量最好的老鳄鱼的皮。这种皮甚至比帆布还要结实，用它就可以完成我的完美设计。$b$b虽然要找到完美的皮很难，但这种老海鳄的皮是唯一能配得上我的设计的材料了。老海鳄只会在其它鳄鱼被攻击的时候才会出来保护族群，所以恐怕你得先杀些普通鳄鱼引它们出来。', '给藏宝海湾的崔斯里克带回1张老鳄鱼的皮。', '好极了!谢谢你的帮忙，我现在可以完成这笔订单，然后在下次运货的时候把它寄给地下矿坑的主管雷德沃克斯。甚至还可以提早给他!$B$B为了对你的帮助表示感谢，我特别为你多做了一双，拿着吧。是我崔斯里克送你的。$B$B记住，没什么靴子比崔斯里克的雕花皮靴更完美了!', '我听说老海鳄正濒临灭绝……这对我来说真不是什么好消息，不是吗?$B$B尽管如此，我还是希望你能带张老海鳄的皮给我!', '', '去荆棘谷找藏宝海湾的崔斯里克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (629, '暗礁海', '很久以前，有一座古老的巨魔城市因为大地震沉入了西北方的野人海岸水下。现在那里被一群鱼人所占据着，任何接近的人都会遭到他们的攻击，我们把那处地方叫作暗礁海。$B$B在那片废墟之中有一块古老的石板，上面记录着一位名叫格里雷克的巨魔英雄的传说。那块石板对于我们暗矛部落来说具有神圣的意义，尽管它太大，没办法全部运走，但我仍希望有人能从上面敲下一块碎片，让我们带到奥格瑞玛的新家去供奉起来。', '给格罗姆高营地里的肯维雷带回一块石板碎片。', '很好。回到奥格瑞玛后，我会把这块裂片供奉在一处神圣的地方。它将永远提醒我们……格里雷克有多么强大，他曾获得过怎样的荣光。$B$B谢谢你，$N。你得到了我们暗矛部族的尊重与友谊。', '我正等着你带石板裂片回来呢，$N。', '', '去荆棘谷找格罗姆高营地的肯维雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (630, '瓶中信', '$N，我的一切都全靠你了！是蓝鬃猩猩之王穆克拉把我抓进来的，它统治着这岛上所有的野兽，它们不顾我的反抗，用这些铁链把我给锁在这儿。如果你能杀了它，从它身上找到能够打开这套镣铐的钥匙的话，我会好好报答你的。$B$B它通常在这座岛的北边活动，但你一定得小心，它绝对是一个很难对付的家伙。', '杀死穆克拉并带着钥匙回去救出普巴尔公主。', '$N，你将我从巨大的耻辱中解救了出来。如果我现在是在自己的部族里，一定会赏个高级的职位给你。但现在，我能用来奖赏你的勇气的也就只有这个东西了。', '感谢祖先的英灵，终于有人来帮助我了。你拿到钥匙了吗?', '', '去荆棘谷找哈圭罗岛的普巴尔公主。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (632, '萨多尔大桥', '很显然，可怜的老伊本瑟遭遇到了黑铁矮人的伏击，已经战死了。但你突然注意到了他紧握着的拳头中似乎有一张皱皱的羊皮纸。$b$b将这条令人沮丧的消息告诉拉格·加玛森，并把你的发现报告给他。', '向湿地中丹莫德的拉格·加玛森回报，并将你在伊本瑟尸体上找到的羊皮纸交给他看看。', '啊，天哪……这消息太令人伤心了……', '有老伊本瑟的信儿了吗，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (633, '萨多尔大桥', '天呀！不！可怜的伊本瑟，这实在是一个悲剧。$b$b我们绝对不能让他就这样白白牺牲了。你发现的这张羊皮纸上写道，是卡姆·深怒在背后组织了这次进攻，并且，他还在萨多尔峡谷的阿拉希高地那一侧囤积了不少炸药。$b$b如果他们用这些炸药摧毁了桥梁的话，那么我们的通向北边的主要补给线就会被彻底切断！必须摧毁这些炸药，$n！完成了这个任务后立刻回来向我复命。$b$b你是我们最后的希望了。', '摧毁堆积的炸药。', '这座桥终于守住了!你又为麦格尼陛下与卡兹莫丹的人民做出了巨大的贡献。$B$B现在就看我们是否能撑到援军到来的那一刻了……', '必须摧毁所有的爆裂物!', '', '去湿地找丹莫德的拉格·加玛森。', '摧毁炸药桶', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (637, '苏利·巴鲁的信', '你手中的这封信湿淋淋的，已经面目全非了，只有几页像是得到了精心保护的信纸上的字迹还能辨认。$b$b这封信是写给铁炉堡的萨拉·巴鲁女士的，开头写着，“亲爱的萨拉……”', '把苏利·巴鲁的信交给铁炉堡的萨拉·巴鲁。', '你说你看见我的苏利被钉在寒冷的水下?不!这不可能!$B$B赶快把他的信给我……', '$C，你看起来好像走了一段很长的旅程，而且并不平坦。这段时间里我们的灵魂都备受煎熬。你带来了什么消息?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (639, '激流堡符印', '在古代，巨魔曾与阿拉索帝国以及我们最强大的对手——被称为“激流堡的伊格纳乌斯”的托尔贝恩作战。托尔贝恩总是挥舞着托卡拉尔剑进行作战。在古代语中，托卡拉尔是“巨魔杀手”的意思。$b$b然而，现在托尔贝恩子孙的势力已大不如前了，他们的要塞也已经变成了废墟。$b$b托卡拉尔剑是由几块符印保护的，这些符印现在都在激流堡的幸存者手中，我们必须获得它们。$b$b辛迪加组织拥有第一块——这一块应该就在他们驻扎于激流堡的那群人中的某个人手里。', '帮落锤村的森古拿回激流堡符印。', '太好了。这是一个良好的开端―我们会不断收集我们需要的符印，将托卡拉尔从托尔贝恩的墓室中拿出来。', '你找到第一块符印没有?它最有可能在激流堡城内的某个辛迪加成员身上。', '', '去阿拉希高地找落锤镇的森古。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (640, '破碎的符印', '索拉斯·托尔贝恩的墓室由三块符印护卫，这其中的第一块你已经从辛迪加手中得到了。另外两块更难得到，因为它们被牢牢地控制在激流堡的民兵手里。$b$b索拉丁符印被索拉斯的儿子加林分成了五块，分别由一个激流堡守卫者掌握。取回这些符印，把它们交给巨魔祭司托尔甘，他能够将它们合成一块完整的符印。', '从激流堡的守卫者那里取回5块符印碎片，把它们交给落锤村的托尔甘。', '啊，你要让我重铸这块符印?这应该不是很难……所有的碎片似乎都在这儿了，应该会很轻松。$B$B我建议你先闭上你的眼睛。', '(兽人语)你好，$C。森古告诉我你需要我的帮助。', '', '去阿拉希高地的落锤镇找托尔甘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (641, '索拉丁符印', '复原得完美无缺。现在，这块完整的符印可以被用于打开托尔贝恩墓穴上的封印了。把它交给森古吧，他一定还有别的任务要你完成。', '把修复的索拉丁符印交给落锤村的森古。', '将托卡拉尔从托尔贝恩的墓室里拿出来的工作可以说进行到一半了。我们并不清楚第三块符印在哪里，它的拥有者似乎在阿拉希高地附近游荡，我相信你能找到它。', '$N!你拿到第二块符印了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (642, '被困的公主', '我叫密斯莱尔，我是大地的公主。巨人们俘获了我，把我拘禁在阿拉希高地的地下深处。这些水晶碎块是我和外界交流的唯一途径。$B$B帮帮我。这些巨人的盟友——枯须狗头人——就在东边的枯须峡谷里活动，那里有一块类似水晶碎块。要激活那块水晶，你必须从狗头人那里收集到密斯莱尔之尘，然后把它们放在水晶上。$B$B求求你了，$N，帮帮我吧！', '收集密斯莱尔之尘。$B$B把它们放在枯须峡谷中的虹光水晶碎块上。', '啊!你启动了这些水晶裂片。我感觉自己已经恢复不少了!$B$B可是，唉，我离自由还很遥远……', '这簇水晶裂片很像密斯赖尔水晶裂片，但是却没有那种安全感。', '', '去阿拉希高地找枯须峡谷的虹光水晶碎块。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (643, '阿拉索符印', '尽管他们还没有控制激流堡，更不要说整个阿拉希高地，但那人类王子却率领着剩馀的骑士在乡间疾驰。我不能理解他为什么这么做，谁又能理解人类的思维方式呢？$b$b且不管他到底是怎么想的，最重要的是他把一块符印交给了瓦罗卡尔中尉，也就是那群骑士的首领。找到这个人，把他的符印带回来交给我。', '取回阿拉索符印，把它交给落锤村的森古。', '对于激流堡的防卫者来说，失去骑士领袖无疑是一个沉重的打击。然而，这也意味着我们距离得到托卡拉尔只有一步之遥了。', '$N，瓦罗卡尔不是那么容易就能找到的。他骑在马上，来去如风。不论如何，我们一定要得到他的符印。', '', '去阿拉希高地找落锤镇的森古。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (644, '托尔贝恩符印', '打开索拉斯·托尔贝恩墓室所需的最后一块符印掌握在他儿子手中。他深居在激流堡的一座由民兵控制的教堂里。加林王子的保卫措施非常严密，他本人也是一名强大的勇士，所以这次你的任务会是非常艰巨的。', '杀掉加林·托尔贝恩王子，把托尔贝恩符印带给落锤村的森古。', '多么具有纪念意义的一天呀，$C。托尔贝恩的子嗣不再困扰我们的同胞，获取托卡拉尔剑所需要的符印也全都掌握在我的手中。很快，我们就可以对祖尔格拉布的那些可恶的巨魔们发起进攻了。', '$N，你回来了。托尔贝恩的防线崩溃了吗?', '', '去阿拉希高地找落锤镇的森古。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (645, '托卡拉尔', '将四块符印放在一起，它们就能互相结合形成一块完整的符印。毫无疑问，这块符印能够击破托尔贝恩地墓室里的防护魔法。$b$b托尔贝恩的遗体就埋葬在激流堡教堂后的密室中。去取回托卡拉尔。', '从激流堡的托尔贝恩墓室中取回托卡拉尔剑。', '随着你将伊格纳乌斯符印放置在墓石上……一束光芒熔化了符印，而传说中的宝剑托卡拉尔就从原本紧抓着它的石爪上掉落了下来。', '托尔贝恩墓室正面的墓碑上的雕刻与伊格纳乌斯符印表面闪闪发亮的线条完全吻合……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (646, '托卡拉尔', '光芒慢慢地褪去，石鞘中的托卡拉尔剑已经松动了。', '把托卡拉尔剑交给落锤村的森古。', '几个世代以来，激流堡和阿拉索一直是巨魔一族的心头大患。现在，他们最厉害的武器已经落在我们的手里，我们在祖尔格拉布潮湿的森林中艰难度日的时代已经成为过去。$B$B你为我们做出了巨大的贡献，$N，暗矛巨魔会感激你的。$B$B这把剑将被送到格罗姆高的尼姆布亚那里。', '$N!你拿到剑了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (647, '马克里尔的月光酒', '昨晚我喝了很多月光酒！要是布莱德知道我在当差的时候溜出去准会要了我的命。$b$b我喝得有些太多了，就感觉到头顶上有一整支蒸汽坦克部队呼啸而过，满耳都是隆隆的响声。$b$b哦，瞧这时间！我答应南海镇的布鲁米·比格尔要送他一些月光酒来抵债的。$b$b但是离我交货的最后期限只有15分钟了！请你把这些带给他，好么？要快！', '把马克里尔的月光酒交给南海镇的布鲁米·比格尔。', '啊，再没有什么能像醉鬼麦克里尔的月光酒那样能使人精神振奋了!我还在想这个家伙是不是又要来不及还帐了。谢谢你，朋友!真的非常感谢!', '有什么好消息吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (651, '禁锢之石', '在阿拉希高地上散布着4块禁锢之石，这些石头将我牢牢地钉在地下。$B$B要想解除它们，你就必须解除最坚固的那块：内禁锢之石。首先，你必须搜集到其它三块石头的钥匙。$B$B这些石头都有守护者在看守，但是如果你足够聪明或者足够幸运的话，就能找到消灭这些守卫的办法。', '从西禁锢之石、东禁锢之石和外禁锢之石中搜集烈焰钥匙、海浪钥匙和雷霆钥匙。$B$B把它们带到内禁锢之石处。', '<密斯赖尔通过石头与你说话。>$B$B你做到了!你打开了禁锢之石!我感到束缚着我的枷锁已经慢慢松开，自由正在逐渐向我走来。$B$B你是一个高尚的$C，$N。我的救星!', '这里是内禁锢之石，它是所有禁锢之石中最坚固的一块，必须先于其它三块解开。', '', '去阿拉希高地找内禁锢法阵的内禁锢之石。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (652, '打开钥匙之石', '禁锢之石的开启基本解开了这些束缚着我的东西，可还有一把牢不可破的锁让我无法动弹。你看到这圈石头中的那块钥匙之石了吗？开锁的钥匙在弗兹鲁克手中，他是囚禁我的巨人之一，也是这石锁的看护人。$B$B你必须从弗兹鲁克那里获得一把名叫“秩序魔棒”的钥匙来打开钥匙之石。$B$B你已经为我做了这么多，$n，只是再帮个微不足道的小忙……我会对你更加感激不尽的！', '找到并杀死弗兹鲁克，然后把秩序魔棒带到阿拉希高地的钥匙之石旁。', '你把魔棒放入钥匙之石，随即感受到了地面开始震动……', '钥匙之石充满了巨大的能量。', '', '去阿拉希高地找内禁锢法阵的钥匙之石。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (654, '塔纳利斯的样本', '启动能量源之后，野外实验工具包开始闪光和震动，看来它开始按照预定的程序工作了。$B$B我会立刻将它送走。$B$B根据首席工程师比格维兹所说的，你现在还有一些时间在塔纳利斯沙漠收集你所需的数据。$B$B当你完成任务之后就尽快回到他那里。', '收集8份蜥蜴样本、8份土狼样本和8份蝎子样本，然后在能量源耗尽之前把野外实验工具包还给加基森的首席工程师比格维兹。', '好吧，给我一点时间把能量源弄下来。然后随便你怎么处理它也不用再担心会遗失资料了。', '怎么样，你得到你要的东西了吗?如果你在能量耗尽之前没有完成的话，里面存储的所有东西都会消失，你就不得不重新来过。$B$B嘿，不要老是可怜巴巴地看着我。我的职责就是为加基森水业公司创造利润，我的目标就是不断把能量源卖给你，直到我们能够负担得起把丹莫洛的冰水引到塔纳利斯沙漠的工程为止!就这样吧!', '', '去塔纳利斯找加基森的首席工程师沙克斯·比格维兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (656, '召唤大地公主', '你必须在密斯莱尔恢复力量之前打败她。否则，一旦等到她聚集到足够的能量，密斯莱尔就会向追捕她的人发起挑战！有一些人自信能控制住她，但是如果她真能被控制住，巨人们有必要先发制人把她囚禁起来吗？$B$B这是个疯狂的逻辑，难道不是吗？$B$B你必须在第一次和她接触的密斯莱尔水晶碎块那里将她召唤出来，然后打败她。在打败她之后搜出她身上的怪异镣铐，然后与密斯莱尔水晶碎块缚在一起。$B$B只有这样做才能再次将密斯莱尔囚禁起来。', '到密斯莱尔水晶碎块去召唤她，然后打败她。$B$B搜出她身上的怪异镣铐，将其和密斯莱尔水晶碎块缚在一起。', '你把怪异镣铐放置在水晶裂片周围。从地下很深的地方传来可怕的尖叫声，紧接着传来的是一声怒吼。$B$B密斯赖尔水晶裂片再也没有那种曾经有过的温暖安适的感觉了。现在，它们越来越猛烈地震动着……就像是有一种潜藏在地下的怨怒即将冲破地表一样。', '现在，密斯赖尔水晶裂片出奇地安静。', '', '去找辛特兰的密斯莱尔水晶碎块。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (658, '新的瘟疫？', '是费恩让你来找我们的吧？我一点都不吃惊，那家伙总是担心这个担心那个的。$B$B我们监视这个农场已经有些时候了，基恩洛说她不久前看见有一个信使从那间小房子里走出来，往南边去了。$B$B她平时话有些多，不过在这种危险的地方，我总是相信她的直觉。$B$B嗯……你的追踪能力怎么样？我们认为那个信使可能是带着信去塔伦米尔了。如果你能弄到那些文件，就有可能帮助我们搞清楚在希尔斯布莱德所发生的那些怪事。', '找到被遗忘者信使，把她的密封的信件交给格沙克农场里的奎艾。', '好极了!$B$B看看我们都发现了些什么……', '感谢你帮我们找到了那个信差，$N。$B$B你走了以后，基恩洛看见有一个药剂师走出那间房子朝南边去了。我确信他们不会是在做什么好事―但是我可不想草率行动，所以首先，我们得有一些确切的证据。$B$B怎么样，你要不要帮忙?', '', '去找阿拉希高地的奎艾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (662, '深海打捞', '奥布里领船进入海湾，我们确信能在这里发现宝藏。先驱号安全靠岸，但是当处女号和银松之魂号靠近港口的时候，退潮开始了。此时发生了怪事！$b$b那两艘船撞上了什么东西……似乎是暗礁中的什么庙宇……它们很快就沉没了，这真是一场灾难。$b$b我们必须要在离开以前去取回他们的日志和航海图，这些有价值的信息绝对不能留给任何其它人！', '大副尼兹利克斯让你从处女号和银松之魂号中取回航海图和航海日志。', '太好了，这些宝贵的资讯安然无恙。藏宝海湾里的舰队指挥官看来可以放心了。干得不错，$N。', '你的打捞工作进行得如何了，$N?我们必须从处女号和银松之灵号里取回那些航海图和日志。$B$B如果那些宝贵的资讯落入敌人手里，舰队指挥官绝对会让我们吃不了兜着走的。$B$B更确切的说，这关系到我们能否从现在的糟糕处境中摆脱出来。', '', '去阿拉希高地找法迪尔海湾的大副尼兹利克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (664, '船长的复仇', '啊，多么可怕的生活！我本以为我再也不能像现在这样坐在火堆旁呼吸着新鲜的空气了！$b$b船员们为了拯救我那美丽漂亮的处女号尽了全力。愿神保佑他们，保佑他们的心灵。$b$b奥布里船长的船安全地进了港，可我们就没那么幸运了，大浪弄沉了我们的船。$b$b前一秒钟我们还漂浮在海上，转眼间就又被海浪吞没。而那些该死的纳迦还杀死了所有的幸存者！我逃到这里来，算是勉强保住了性命。$b$b我要让那些野兽去死！', '法迪尔海湾的斯迪加特船长要你去杀掉10个刺脊袭击者和3个刺脊巫师。', '干得漂亮，$N。那些混帐东西罪有应得。既然我的船和我的水手们已经不在了，那么就让这些纳迦的死给我带来一些安慰吧。', '呀，也许我应该亲自去手刃那些该死的纳迦!显然，你是不会去做这个的。$B$B也许我该给你找些针线活，让你不至于太清闲。', '', '去阿拉希高地找法迪尔海湾的斯迪加特船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (665, '水下宝藏', '既然我们已经整装待发，那么帮助奥布里先生寻找丢失的精灵宝藏就是当务之急了！$b$b在黑暗的海底，如果没有任何辅助手段的话，要想找到那些宝藏几乎是不可能的。博士做的潜水镜可以派上大用场，不过他要从山上的洞穴里弄些魔石来，好给他的潜水镜附上魔法。$b$b但是那座洞穴已经被诅咒了！只要我们靠近洞穴就会遭到伏击。你得掩护我，让我控制魔石的能量，将它注入到潜水镜里。', '护送菲兹索普教授到洞穴里去并平安返回。', '现在潜水镜可以正常工作了!好样的，$N。', '没时间细说了!潜水镜需要注入魔石的力量才能工作!', '保护菲兹索普教授', '去阿拉希高地找法迪尔海湾的德拉克里格博士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (666, '水下宝藏', '宝藏在海床上放了那么长时间，早已经被岩石包裹起来了。但是借助潜水镜中的魔法力量，你可以轻而易举地锁定这些宝藏。$b$b侏儒的创造能力实在是让人惊叹！$b$b那么你去把寻宝潜水镜借来用用，$n，看你能不能帮奥布里船长找回些丢失的宝藏。$b$b我可以潜游到那儿，可是……嗯……在这片安全而干燥的土地上，我有些重要的科学研究要做……嗯，是这样的。', '法迪尔海湾的德拉克里格博士要你去收集10块精灵宝石并在完成任务后归还寻宝潜水镜。', '好极了，$N!船长一定会很高兴的!现在就等着舰队指挥官卡拉.海角的消息吧。', '潜水镜用得如何?运转还算正常吧?如果需要的话，我可以对它们做一些调整。$B$B哦，如果你用完了，就把潜水镜还给我。我想奥布里船长很快就要用到它了。', '', '去阿拉希高地找法迪尔海湾的德拉克里格博士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (668, '水下宝藏', '我们不要让奥布里船长等了。他急着想看到这些宝藏呢。这不正是我们在这儿的原因吗？$b$b和这些海盗们打了几个星期的交道以后，我和教授都意识到，手里拿着海盗的宝藏永远是不安全的。$b$b拿着这些，$n，把它们交给奥布里。', '把精灵宝石交给阿拉希高地中法迪尔海湾的奥布里船长。', '这些小地精毕竟体现了他们的价值，对吧?它们确实有很大的利用价值!', '嘿，$C。是哪阵风把你吹到这里来的?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (669, '水下宝藏', '舰队指挥官卡拉·海角一定想马上知道我们找到了什么。$b$b你也看到了，我们还不能离开这儿。不单单是因为潮水太低的缘故，还因为那些被我们惊动的可恶家伙正密切地注视着我们的一举一动。$b$b假如你能把口信带给藏宝海湾的舰队指挥官卡拉·海角，并告诉他我们已经发现宝藏的话，你可就帮了我们黑水海盗的大忙了。把这件东西交给舰队指挥官卡拉·海角，这样他就会确信你说的是真的了。', '把精灵宝石样本交给荆棘谷藏宝海湾的舰队指挥官卡拉·海角。', '啊，可爱的老沙克斯·奥布里!我就知道他是这次最合适执行这次任务的船长!', '是哪阵风把你吹到藏宝海湾来了，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (670, '水下宝藏', '嘿，$n，看来你是个喜欢冒险的$r。在我们重新进货之前，我的船队会一直停泊在藏宝海湾。$b$b这里即将发生一些大事，我得找人把相关的绝密信息通报给在阿拉希海岸上的沙克斯·奥布里。$b$b你可以确保将口信安全而保密地送达吗？', '把海角船长的密信送给阿拉希高地中法迪尔海湾的沙克斯·奥布里。', '感谢你完成了一段如此漫长而艰险的旅途，黑水强盗向你致敬。', '海角给你留下的印象不错吧?我跟你打赌，他一笑起来，那张嘴能从藏宝海湾一直咧到棘齿城去!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (671, '邪恶的魔法', '我感觉空气中弥散着一种奇怪的东西……这种感觉在我的血液中不断升腾。对此我感到很奇怪，于是便着手去寻找给我造成这种不安的原因，然后我就在西边的诺斯弗德农场找到了一些邪恶的召唤法术留下的痕迹。当我慢慢地靠近时，我的热血开始沸腾，胸中的怒气不断上升。$b$b我在地上发现了一枚血石护符，那是用在恶魔召唤仪式中的东西。可是，我找到的这枚血石护符的能量已经被耗尽了。现在我需要再弄一些来研究，可我不敢回农场去了。你能帮我找一些来吗？', '帮落锤村的托尔甘找10枚血石护符。', '看来我们得花一番工夫才能确定辛迪加的真实意图。但是他们与黑暗和恶魔之间显而易见的联系让我感到十分担忧。一旦有更多资讯的话，我马上会告诉你的。', '我们曾经为恶魔的诅咒付出了极大的代价，$N。如果有人……或者有什么东西又在召唤恶魔的话，我们就一定要阻止它。', '', '去阿拉希高地的落锤镇找托尔甘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (672, '振奋精神', '我们把他安顿下来，不断地鼓舞他，向他讲述我们在卡利姆多创建伟大的奥格瑞玛城的故事，但所有的这些都无法打动他。$b$b关于我们年轻的酋长的故事，拥有奥格瑞姆的战甲和战锤的萨尔酋长……也许吧……也许吧！我们新发现的萨满魔法或许会带给他新的希望。这值得一试！$b$b我们可以给他一件小东西，对……给我带些迅猛龙的眼睛，我要看看我们能做些什么。', '从高地阔步龙和高地长尾龙身上取得10个高地迅猛龙的眼球，把它们交给落锤村的托尔甘。', '很好。这些眼睛上的迅猛龙之魂会给予这块护符的拥有者强大的力量。', '我要打造一枚护符，它能给戈莫尔带来一些迅猛龙的力量。也许那样能够唤醒他体内的火焰……', '', '去阿拉希高地的落锤镇找托尔甘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (673, '邪恶的魔法', '我确信有一个强大的术士居住在激流堡城内。这个术士经常通过一种魔法物品来召唤大量的恶魔。我们必须毁掉他的能量源泉。$b$b找到这个术士，杀掉他。把所有你在他身上发现的物品都拿来给我，我会设法销毁它的。我们绝对不能让这片大地再被玷污了！', '取回玛雷兹·考尔的血石宝珠，把它交给落锤村的托尔甘。', '摧毁了这颗宝珠之后，我终于能从那一个个不眠之夜中摆脱出来，安安稳稳地睡几个好觉了。谢谢你，$N。这颗宝珠让我想起了兽人被恶魔的黑暗力量所统治的那段时间，最终还是格罗姆.地狱咆哮让我们从诅咒中解脱了。', '我血液中的灼烧感与日俱增……我们必须阻止这个术士。', '', '去阿拉希高地的落锤镇找托尔甘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (674, '振奋精神', '把这枚护符交给戈穆尔，看看迅猛龙的力量能否唤醒这位勇士的血管中曾经燃烧过的火焰。', '把迅猛龙利爪护符交给阿拉希高地落锤镇的戈穆尔。', '这是什么?打磨过的骨头?我拿着它有什么用?这小东西能恢复部落曾经的荣耀?', '如果连一个懦夫也能杀死英雄中的英雄，希望在哪里?我问你，希望在哪里?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (676, '落锤之战', '软弱的家伙……他们全都是懦夫……你，$c，你在看什么？你觉得自己有什么特殊的么？怎么不去证明一下？$B$B阿拉希的落锤村哨所正受到攻击。再不增派援兵的话，他们就会全军复灭的。$B$B不过在你去那里之前，是不是应该先试试看自己够不够格？阿拉希的激流堡东北部有个食人魔的营地，石拳部族的食人魔就住在那里。等你搞定了那里的食人魔和执行者之后，再去向落锤村的杜拉姆法尔报告吧。', '杀掉8个石拳食人魔和10个石拳执行者，然后去阿拉希高地的落锤村哨所找杜拉姆法尔。', '所以，你觉得自己有能力帮助落锤村?那就这样吧。$B$B塔隆之所以派你去那个巨魔营地，要不是希望你死在那儿，要不他就是觉得你有足够的能力帮助我们。不管怎样，你现在已经来了，我也急需更多像你这样的士兵，来对抗敌人持续不断的攻击。$B$B如果你打算待在落锤村的话，就先去休息一会儿，准备好了再来找我。未来的战斗还多着呢。', '我连斧头都没时间磨，更别说离开哨所去杀那些整日与部落为敌的野兽了。$B$B你看起来连最基本的作战经验都没有，更别说是个学有所成的$C了，你来找我干嘛?', '', '去阿拉希高地找落锤镇的杜拉姆法尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (677, '短兵相接', '枯木巨魔和阿拉希的石拳食人魔联合起来，要把我们赶出这片土地，但我们决不会把命运交给他们掌控！我们要除掉他们，让他们知道谁是这儿真正的主宰。$B$B巨魔背弃了我们，食人魔想要把我们当作美味的食物——我们决不能允许这种事情发生。$B$B现在，让我们从南边的枯木巨魔开始吧。去杀掉他们，让他们血流成河！', '杀死10名枯木掷斧者、10名枯木猎头者和8个枯木巫医，然后回到落锤村哨所的杜拉姆法尔那里。', '你的眉角边滴淌着汗水，你的脸上弥漫着杀气。好样的，你干得很棒。', '如果你还没有完成我交给你的任务，那你也许是个懦夫加菜鸟。', '', '去阿拉希高地找落锤镇的杜拉姆法尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (678, '短兵相接', '$N，你的强大已经是有目共睹的了。现在让我们看看你如何去面对一个真正的敌人。$B$B从这里往西南走，在通往矮人修建的那座大桥的途中，有一个石拳食人魔的老巢。如果我没搞错的话，那儿的虐待者和法师对你来说应该是个难度不小的挑战——至少到现在为止对于我们来说是这样的。$B$B尽可能多地杀死他们，无论最终是胜利还是失败，无论回来见我的是你自己还是你的灵魂，我都会赞赏你在战斗表现出的坚韧精神。', '杀死10个石拳蛮兵和4个石拳法师，然后向落锤村哨所的杜拉姆法尔复命。', '你和科多兽一样强壮，你对战斗的渴望会令你的同胞为你感到骄傲。', '你在犹豫，为什么?$N，你已展示了强大的力量，不要让我失望。', '', '去阿拉希高地找落锤镇的杜拉姆法尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (679, '短兵相接', '$N，现在是时候和这些家伙算总账了……很明显你完全有能力帮我们完成这最后的一击。这些与我们为敌的蠢货的领导者已经在激流堡废墟里创建了巢穴。激流堡的废墟……那是人类软弱无能的最好证明！$B$B找到那些石拳领主和他们的萨满祭司，把他们全都杀掉，这些妄图将我们赶离家园的蠢货们活不了多久了！', '杀死7个石拳萨满祭司和3个石拳领主，然后向落锤村哨所的杜拉姆法尔复命。', '$N，你的同胞会为你感到骄傲的。我们面临的威胁已经大大地被削弱了，我坚信部落往日的繁荣定将在这片高地上重现。', '我看你的勇气最终还是消退了。我的直觉似乎是对的:你一直都是在虚张声势而不具备真正的实力。$B$B要嘛带着野兽的头颅回来见我，要嘛就永远都别回来。', '', '去阿拉希高地找落锤镇的杜拉姆法尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (680, '真正的威胁', '你帮我丈夫干得不错，$c，可他并不知道为什么落锤村会遭受攻击。$B$B奥卡拉尔是玛格索尔派到激流堡去的走狗，他非常害怕我的丈夫。很多年前，我的丈夫打败了他，他巴不得我的丈夫早点死去。$B$B我占卜到奥卡拉尔给我的丈夫设下了陷阱，并且感觉到了那些食人魔正在伺机害他……$B$B如果他知道那些食人魔在哪里的话，一定会不顾三七二十一地杀过去。所以……请你帮我杀死奥卡拉尔吧。', '杀死奥卡拉尔，将他的徽记带给落锤村哨所的科林法尔。', '$N，你可帮了我大忙了。你保护了我的丈夫和整个落锤村的安全。请接受这个做为你的英勇行动的回报吧。', '奥卡拉尔就在阿拉索之塔附近出没。杀掉他就能阻止巨魔对落锤村的袭击，也能保住我丈夫的生命。$B$B你的眼睛告诉我，在你的心中已经认定我是个软弱甚至不光彩的懦弱者，因为我过于沉默。但是总有一天，你会理解我所做的一切的。也许到那时，你就会理解一种不同于以往的力量与荣耀。$B$B请按我说的去做，杀了奥卡拉尔。', '', '去阿拉希高地找落锤镇的科林法尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (681, '诺斯弗德农场', '我们正在为激流堡而战，然而我们却逐渐落入下风。我们、食人魔以及辛迪加分别控制着这座城市的一部分，现在我们这三方势力陷入了整日互相征战却毫无突破的僵局。$B$B然而，当敌人们力量开始逐渐增强的时候，我们却在慢慢地变弱。$B$B我们需要南海镇的援助，但是辛迪加控制了我们和南海镇之间的领地，因此那边的补给很难运到这里来。$B$B到辛迪加在诺斯弗德农场的基地去干掉他们，也许这样做能让我们补给线上的压力大大减轻，然后才能有更多的物资平安运抵这里。', '杀掉6个辛迪加雇佣兵和10个辛迪加路霸，然后回到避难谷地去向尼艾丝队长复命。', '你干得很好，$N。干掉那些辛迪加的成员会使我们更容易获得南海镇的补给物资。$B$B也许我们又有希望夺回激流堡了……', '$N，我们对于激流堡的控制力正在迅速下降。你必须加快行动速度，否则我们的城市必定会陷落。', '', '去阿拉希高地找避难谷地的尼艾丝队长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (682, '激流堡徽章', '我们的民兵分队正在和控制着激流堡的辛迪加成员激战。为了刺激他们那群乌合之众与我们作战，辛迪加的头目们使出了重金悬赏的手段，只要有人能杀死我们的民兵，并从他们身上缴获激流堡徽章，辛迪加都会给予奖励。$B$B我们必须夺回那些徽章——决不能让刽子手们用我们的战士的性命来换取金钱！$B$B到激流堡城内的辛迪加控制区去杀掉那些歹徒，取回我们的徽章。', '把7枚激流堡徽章交给位于避难谷地的尼艾丝队长。', '谢谢你，$N。我们会将这些战士的死讯通知他们的家属。$B$B这是很残酷的消息，但总比不能确定心爱的人是死是活要好得多。', '$N，你取回了激流堡徽章了吗?要让辛迪加明白，他们绝对没法从我们阵亡的士兵那里得到任何好处。', '', '去阿拉希高地找避难谷地的尼艾丝队长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (683, '萨拉·巴鲁的请求', '$n，我对你有个小小的请求。$b$b这张便笺是我写给铁炉堡的国王麦格尼·铜须的。对于你这种曾为联盟的事业英勇作战的$r来说，这个任务再容易不过了。$b$b以我在现在这种状态去觐见国王陛下是很不合适的，我相信你应该可以理解。', '把萨拉·巴鲁的便笺交给铁炉堡的国王麦格尼·铜须。', '我得花点时间来读这封信……', '你是$C$N?你对联盟作出的贡献已经众所皆知了，你知道吗?$B$B你今天来找我有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (684, '通缉：玛雷兹·考尔', '重金悬赏玛雷兹·考尔。这个兽人是辛迪加组织的高级顾问和技工，人们最后一次看见她是在激流堡内的辛迪加控制区。$B$B赏金请到尼艾丝队长处领取。$B$B请注意：玛雷兹是一个强大而狡猾的术士，她和恶魔有着非常密切的联系。追杀她时务必非常小心。', '把玛雷兹的徽记交给避难谷地的尼艾丝队长。', '你杀死了玛雷兹.考尔?干得漂亮，$N。真是干得漂亮。玛雷兹对激流堡的守军构成了极大的威胁，据说她是辛迪加与某些更黑暗的势力之间进行沟通的使节。除掉她无疑是给我们免去了一个心头大患。', '你好，$C。有什么要报告的吗?', '', '去阿拉希高地找避难谷地的尼艾丝队长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (685, '通缉：奥图和法库雷斯特', '激流堡民兵团重金悬赏法库雷斯特公爵和他的保镖奥图的徽记。法库雷斯特是辛迪加在阿拉希地区的主要领导者，他的死将使该组织在这一地区的活动陷入瘫痪。$B$B他的保镖奥图不是我们的战略目标，但他生性凶残，已经杀死了许多激流堡的士兵。$B$B赏金请到尼艾丝队长处领取。', '把法库雷斯特和奥图的徽记交给避难谷地的尼艾丝队长。', '法库雷斯特和奥图?太好了!$B$B这是对你的奖赏，$N。我代表激流堡民兵团感谢你。', '你好。有什么事要报告吗?', '', '去阿拉希高地找避难谷地的尼艾丝队长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (689, '国王的礼物', '我们的国王要建一座纪念碑向一个叫苏利·巴鲁的士兵致敬？你是说那个可怜的士兵是在萨多尔大桥的悲剧中死的？$b$b唉，艾泽拉斯还会有和平吗？$b$b不管怎样，国王下达的任务就是第一要务。我要用最好的石头来建这座纪念碑，你到希尔斯布莱德的丘陵洞穴为我找一些奥特兰克花岗岩来吧。', '铁炉堡的大石匠玛布勒斯坦要5块奥特兰克花岗岩。', '很好!比我想象得还要好!$B$B你知道，我的想象力是很丰富的……', '$N，$N，$N!你有没有拿到足够的奥特兰克花岗岩让我为苏利.巴鲁建纪念碑?', '', '去找丹莫罗的大石匠玛布勒斯坦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (691, '证明实力', '$N，别怕斯奎尔图。他是因为事情太多才变得这么暴躁。在我们等他完成侦察任务的时候，为什么不做些更有意义的事情呢？马林派我到这里来为他收集一些试剂，对于如何收集这些物品，我感到很困惑。不过现在你来了，我想我的问题也解决了。$B$B我需要这些东西：枯木巨魔的獠牙，枯木巨魔的医药包和一把暗影猎手的小刀。$B$B你能帮我找到这些吗？枯木巨魔一般都在阿拉希高地的东南一带出没。', '帮避难谷地中的学徒克里汀收集10个枯木巨魔的獠牙，4只枯木巨魔的医药包和1把暗影猎手的小刀。', '难以置信!我总算明白为什么马林让你来找我们了―干得漂亮!照这个速度，我和斯奎尔图不久后就能回暴风城去了。$B$B我想我的矮人同伴应该从石拳大厅侦察回来了。如果你准备好了，就和他谈谈。$B$B看来他和巨魔进行了一场恶战。不过，别跟他说这件事，他对任何批评他侦察能力的话都特别敏感。', '$N，你弄到我要的东西了吗?$B$B<克里汀一边念念有词，一边在他的日记本上作了些笔记。>$B$B如果我的研究工作是正确的话，那么你可以在枯木巨魔身上找到獠牙，在枯木巫医身上找到医药包，而最强大的枯木暗影猎手应该随身带着小刀。不过，只有当你和他们战斗之后，才能知道哪个暗影猎手拥有一把小刀。', '', '去阿拉希高地找避难谷地的学徒克里汀。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (692, '遗失的卷轴碎片', '密……密斯莱尔卷轴？！你要那东西干什么？它强大的魔法力量可以把密斯莱尔召唤到地面上来，那时候我们就有大麻烦了！$B$B也许……也许已经太迟了，也许她已经自由了。密斯莱尔可能正在为报复我们而聚集力量。如果是这样，那你就必须掌握着这至关重要的卷轴！$B$B……太糟了，它被毁掉了。愤怒的元素生物偷走了卷轴，并将它撕成了碎片。现在它们又在为这些碎片争斗不休。$B$B如果你能搜集那些碎片的话，也许我们还有希望将它修复成原来的样子……', '把破损的卷轴碎片、弄皱的卷轴碎片和烧焦的卷轴碎片带给迷失者塞尔杜林。', '啊，你找到它们了!干得不错，$N!这些碎块是我们打败邪恶的密斯赖尔的唯一机会!$B$B让我来看看能不能重新粘合这些碎块……', '你找到那些卷轴的碎片没有?!如果你想重新禁锢她的话，就早点去找吧，否则就太迟了!', '', '去找荒芜之地的迷失者塞尔杜林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (693, '特雷莱恩的符咒魔杖', '你好啊，$N，很抱歉我以前对你那么凶……我可以断定特雷莱恩的第一件宝物的所在：它在石拳大厅的考格雷什手里。顺便说一句，他已经可以使用冰爆术来教训不听话的手下，看来离他完全掌握魔杖力量的日子也已经不远了。$B$B石拳大厅就在这里的南边，萨多尔大桥的东边。从那个食人魔手里把那根魔杖拿回来吧。$B$B\r\n在你回来之前，我要想想我们要怎样解决激流堡的问题。', '帮避难谷地的斯奎尔图找到特雷莱恩的符咒魔杖，并把它带回来。', '你是个天才，$N。你已经找到了一件物品，这样在我的名单上就还有三件要找了……其馀三件物品都在激流堡里。$B$B休息一下，恢复你的力量―我下一阶段的计画需要更多的时间和努力。饱餐一顿，稍作休息，然后来找我。', '我们的目标是魔杖，$N。你要想尽一切办法把它拿回来。', '', '去阿拉希高地找避难谷地的斯奎尔图。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (694, '特雷莱恩的防御', '休息好了吗？$B$B我们的下一步计划和激流堡的阿拉索之塔周围的食人魔有关。我们必须首先开启这座塔的防御系统，当然，前提是你能活着到达存放那些物品的地方。为此，首先我们需要一些石拳萨满祭司经常携带着的宝石。他们把宝石从塔里带了出来，但他们没有什么机会占有这些宝石了。$B$B从他们那里弄一块宝石，把它送去给克里汀——他能够给宝石附魔，这样一来，宝石就可以当钥匙用了。', '找到一块碧蓝玛瑙石，把它交给避难谷地处的学徒克里汀。', '你太让我吃惊了，$N。好样的!$B$B给我些时间，让我给这块宝石施加魔咒，然后你就可以带着它出发了。', '$N，你好呀，又见面了。你找到苍蓝玛瑙石了吗?', '', '去阿拉希高地找避难谷地的学徒克里汀。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (696, '进攻高塔', '以下是你要找的东西：特雷莱恩的护符匣、特雷莱恩的宝珠和特雷莱恩的黑玛瑙。$B$B所有这三样东西应该都在塔中的箱子里，你打开这些箱子应该不会有什么问题，只是要当心那些食人魔就成。$B$B阿拉索之塔的防御不会作用于那些食人魔，因此你必须时刻准备战斗。如果那些食人魔发现你在偷他们的东西，你就少不了一场恶战。$B$B多加小心，祝你好运。', '找到特雷莱恩的护符匣、特雷莱恩的宝珠和特雷莱恩的黑玛瑙，把它们交给避难谷地的斯奎尔图。', '$N，你是马林派来帮助我们的人里最能干的一个啦，你干得太出色了!$B$B他一定会很高兴看到任务成功完成的。', '干得好!马林一定会为你感到高兴的。', '', '去阿拉希高地找避难谷地的斯奎尔图。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (697, '马林的要求', '把这封信送到暴风城去，让马林知道我和克里汀很快就可以回家了。对于你给我们的帮助，马林一定会好好回报你的，$N，对于这一点我深信不疑。$B$B祝你旅途顺利。', '将给大法师马林的信交给暴风城法师区里的大法师马林。', '<大法师马林打开信读了起来，他的眼睛睁得很大。>$B$B以圣光之名，你真的做到了!太好了。特雷莱恩一定会很高兴的，而且我敢说此刻正在归途中的克里汀和斯奎尔图的心情也和我一样兴奋。$B$B谢谢你，$N。请拿着这个，也许它会在你的旅途中给你提供一些帮助。', '嗯?你看起来有些面熟。抱歉，我们是不是见过?我太忙了，所以有些健忘。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (698, '缺乏补给', '我正努力为我们在东边海滩那里的哨所收集一些补给品，托克卡尔已经尽了他的全力。但他又要值勤，又要为他的士兵们做饭，一天这么下来就没什么时间了。$B$B他们很喜欢吃盐齿鳄鱼的肉，但我没时间为他们再送去一批补给了。你能帮我这个忙吗？$B$B盐齿鳄鱼幼崽的肉不如成年鳄鱼的口感好，所以你别猎杀小鳄鱼，等它们长大了再吃它们也不迟。', '给悲伤沼泽的托克卡尔带去8块新鲜的盐齿鳄鱼肉。', '啊!好极了。今天晚上有肉吃啦。多谢你，$N。$B$B你的帮忙让我们接下来几天好过多了。火烧得正旺，今天晚上一定要饱餐一顿。$B$B你给我们带来这么多东西实在是个大惊喜;达这个家伙在我们大家眼里都不是个最有魅力的兽人，但至少他认真负责，他办事情不会像他身上的臭味一样让人烦恼。', '你好啊，$C。在沼泽地里旅行可不是什么轻松的事情呀，你能到这里来就足以说明你非常勇敢了。', '', '去悲伤沼泽找芦苇哨岗的托克卡尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (699, '缺乏补给', '我们之所以被部署在这里，是为了警戒在这片海岸附近出没的鱼人，以防它们——或者任何其它什么东西——威胁到斯通纳德，当然，要是他们太嚣张了点的话，我们也会去给它们一些颜色看看。这工作可不轻松，我们几乎很少有自由的时间，所以只好拜托你来帮忙了，当然，我是说如果你愿意的话。$B$B加工得当的盐齿钳嘴鳄的爪子可以用来制作精良的武器，给我带些它们的爪子回来，我就会送你一件精致的武器作为酬谢。', '给悲伤沼泽的托克卡尔带去6只盐齿钳嘴鳄的爪子。', '见到你能活着回来真是太好啦，$N。$B$B这些爪子非常合适，我们在遭到攻击之前有越多的武器，就越不容易被打败。$B$B我马上就把你的武器准备好。做这玩意我已经很熟啦，只需一小贬就能搞定。', '上好的蜂蜜酒，温暖的营火，一队兽人战士和一库武器……这就是我们在这片海滩上最需要的东西了。尽管我一点都不后悔为了保卫斯通纳德而来到这里，但要是有个地堡或是哨塔该有多好呀。', '', '去悲伤沼泽找芦苇哨岗的托克卡尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (701, '迅猛龙的狡诈', '只要借助一些特别的物品，我就能创造出一件注入了迅猛龙的狡诈力量的东西！这样就应该能让戈穆尔了解到我们新的能量，并重新找回潜藏着的勇士的力量！$b$b我需要迅猛龙的心脏来完成这件物品和法书。', '从高地猎兽龙身上获取12颗迅猛龙的心脏，把它们交给托尔甘。', '很好，这些足以发挥作用了。我将会把它们的能量和迅猛龙的亡魂转移到这颗宝珠上，它会把强大的力量和迅猛龙的智慧注入戈莫尔的体内。', '我的准备工作已经完成，现在只缺迅猛龙的心脏就可以开工了。', '', '去阿拉希高地的落锤镇找托尔甘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (702, '迅猛龙的狡诈', '拿着这颗宝珠，用它的能量来给戈穆尔灌入迅猛龙力量的精髓。这一定会让他的精神备受鼓舞，并给予他新的生活目标。当他恢复正常之后，我们就可以向他说明部落现在的状况，在我们永无止境的战斗中，这位伟大的战士也将帮上大忙。', '把托尔甘的宝珠交给阿拉希高地落锤镇的戈穆尔。', '至少，这次你带来了让我感兴趣的东西。它有一种奇怪的能量……', '你又回来啦?的确，除了托尔甘的怜悯之外，我也不能再期望得到其他的什么了。$B$B你这次为我带来了什么?也许是一条颜色鲜艳的细绳?或者一条可以结束我悲惨命运的绳索……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (703, '烧烤秃鹰翅膀', '哦，当然，烧烤秃鹰翅膀是我的最爱！酱汁浓郁，肉香扑鼻，香味能把数公里外饥饿的野兽都给吸引过来！$B$B我有能做一顿美味佳肴的一切原料，呃……还差点秃鹫翅膀！$B$B如果你想尝尝我的手艺，就去帮我弄些秃鹫翅膀来。尽量多弄点，没准我一高兴就把烹饪方法一并教给你！', '给里格弗兹带去4只秃鹫的翅膀。', '啊，我现在就来处理这些秃鹫的翅膀。我几乎可以闻到它们的美味了!$B$B烹饪方法在这儿，如果你愿意自己亲自烹饪它们的话，就拿去吧。', '嘿，$N。你带回秃鹫的翅膀了吗?', '', '去荒芜之地找巨牙谷的里格弗兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (704, '阿戈莫德的命运', '阿戈莫德送来的最后一份报告让我感到十分困惑，现在他死了，我就更难受了！他提到挖掘队在奥达曼附近的挖掘场找到了一些“远古的石罐”。我担心是他找到的罐子影响了穴居人，就像这里发现的小石像一样。$B$B我要你去找到那些罐子，把它们拿回来以供研究。到奥达曼挖掘场去收集那些罐子吧，完成之后再回到我这里来。', '收集4个雕纹石罐，把它们交给洛克莫丹的勘察员基恩萨·铁环。', '做得不错!只要有些许运气，再加上足够的努力，我们会发现石腭怪与这些古物的联系。$B$B你为勘察队做出了巨大的贡献，$N。我们不会忘记你的功劳。埃格蒙德也不会。', '你找到那些罐子了吗，$N?我们必须找出它们与这些石腭怪之间的联系!', '', '去洛克莫丹找铁环挖掘场的勘察员基恩萨·铁环。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (705, '潜水采珍珠', '荒芜之地是一个无比荒凉的地方，是凶残的捕食者和食腐动物的乐园。这里的一切都令人感到恐慌，尤其是对于我这样的小个子地精来说。为了生存，我不得不机灵些！$B$B我知道闪光弹的制作方法，也常用它来吓走野兽。不过，作为原料之一的蓝珍珠粉快要用完了。你能不能帮我找些蓝珍珠回来？当然我会给你足够的报酬。$B$B呵呵，这个东西并不是那么好找的，恐怕你得走不少的路了。我所需要的蓝珍珠可以在暗礁海的牡蛎身上找到。$B$B对，就是位于荆棘谷的那个暗礁海。', '收集9枚蓝珍珠，把它们交给荒芜之地的里格弗兹。', '这些一定会派上大用场!我只要把它们碾碎……然后混合上一点点这个，还有这个。$B$B小心，有野兽朝这边来了!准备点燃闪光弹!', '你找到我需要的珍珠了吗?闪光弹快要用完了!', '', '去荒芜之地找巨牙谷的里格弗兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (706, '黑龙之火', '作为费拉诺·钢趾的学徒，我从他那里学会了赋予武器强力魔法的特殊技能。我最后一次听到他的消息时，他正和从洛丹伦过来的狩猎小队合伙工作。$b$b我不能告诉你关于这种技术的太多细节，但可以告诉你必须要用黑龙血来完成这个附魔过程， 而且一定要是从黑色幼龙那仍在跳动的心脏中涌出的血液。我现在除了等待铁炉堡的消息以外无事可做，所以如果你能从莱瑟罗峡谷帮我带一颗黑色幼龙之心回来，我就向你展示一下我的技术！', '为西格鲁·铁斧拿到一颗黑色幼龙之心。', '啊，不错，这真是太好了。这将使你的武器上燃烧着足以摧毁一切的烈焰!', '你的狩猎行动进展如何了，$C?', '', '去找荒芜之地的西格鲁·铁斧。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (709, '化解灾难', '天哪……天哪！厄运就要降临了。它已经朝我而来了！厄运就要降临了！$B$B不，我不能说……不能说出他们的名字，否则会被他们听到的！但是，如果我们……如果我们对他们有更多了解的话……也许我们就可以知道如何击败他们！$B$B也许……$B$B到奥达曼去。不！我说过！你必须找到……找到雷乌纳石板……对，找到它！别让我再提到那个名字！$B$B它深藏在那里，就在一个古代的箱子里……这个箱子甚至比矮人族群的年代还要久远……', '把雷乌纳石板带给迷失者塞尔杜林。', '啊，幸运与我们同在!谢谢你!我们也许可以获救了!', '你找到石板了吗?它一定包含了什么秘密!可以拯救我们的秘密!', '', '去荒芜之地找阿戈莫德的营地的迷失者塞尔杜林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (710, '研究石元素', '在荒芜之地，我停下了所有手头的事情来专注于我的最新项目：元素禁锢镣铐。$B$B这些镣铐一旦完成，就可以让法师们在更广的范围内召集更加强大的元素生物。首先，我需要些小石头碎块，来检验我最新的攻击性咒语和小发明。$B$B你可以从西面那里的次级石元素身上收集到这些碎片，能给我弄一些来吗？', '收集10块小石头碎块，把它们交给荒芜之地的鲁特维尔·沃拉图斯。', '这些应该足够了，$N。嗯，沙子的用量似乎多了一点，还需要调整一下摩擦系数。不，等等……由于冰霜之油的作用，摩擦系数应该可以忽略。$B$B<鲁特维尔喃喃自语着，目不转睛地盯着合拢的双手，陷入了沉思。>', '这个地区对于―你能拿着这些东西在这里站一会吗?对，就像那样，面向那边。嗯，我说到哪儿啦……哦，对，这个地区对于测试我的新项目来说实在是太完美啦。充足的原材料，开阔的空地……对于一个充满智慧和灵感的发明家来说已经是很棒了。', '', '去荒芜之地找漫尘盆地的鲁特维尔·沃拉图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (711, '研究石元素', '$N，你的能力超过了我所有学徒的总和。$B$B我所需的下一个部分需要花些功夫。只要你稍加留心，就能在石元素身上找到一些大石片。他们的身体更加庞大，因而会有足够大的碎片来供我试验。你可以在西边远一点的地方或者东南方的山地边缘找到它们。$B$B不用太着急，测试你带来的小石头碎块还需要花些时间。', '收集3块大石片，把它们交给荒芜之地的鲁特维尔·沃拉图斯。', '$N，简直难以置信!我本以为需要半打牛头人才能帮我搞到这些材料的。', '我真是太高兴了，$N。我的咒语对小石头碎块的作用效果和我期待的一致。如果这个实验如预期一样成功的话，我将能控制的元素生物会使任何在此之前召唤出来的任何元素生物都相形见绌。', '', '去荒芜之地找漫尘盆地的鲁特维尔·沃拉图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (712, '研究石元素', '$N，我还需要从荒芜之地的元素生物身上弄一些东西：巨型石元素身上的护腕。据我估测，那些护腕完全可以检验出我的镣铐所具有的力量。$B$B我的占卜显示，在西南边有一批巨型石元素。我想起来了，那附近好像还有一些食人魔。$B$B给我带5个护腕来，我想5个就足够了。阿布总是放错我的试剂和实验品，这方面它的名声可不太好。', '收集5个石缚护腕，把它们交给荒芜之地的鲁特维尔·沃拉图斯。', '$N，你考虑过要当我的研究助理吗?没有?如果没有你的协助，我都不知道能做些什么了。智慧，好奇心和力量―你拥有这所有的一切。', '你找来的石片简直太完美了，$N。在我们完成现在的任务之后，卢希恩会将剩馀的石片带到卡拉诺斯去。它们应该还能在那里发挥一些作用。$B$B比方说，在我配制高爆爆裂物的时候，那些石片可是制作掩体的最佳材料……$B$B<鲁特维尔的声音越来越小，他又投入到了实验中。>', '', '去荒芜之地找漫尘盆地的鲁特维尔·沃拉图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (713, '至关重要的冷却剂', '让我来告诉你些有关冰霜之油的事情吧：没有别的什么东西能够像它一样防止发动机或者齿轮过热。$B$B它的冷却性能和润滑效果无与伦比。不仅如此，它还有助于保存附着在魔法物品上的魔力。$B$B我需要一小瓶冰霜之油以加强镣铐的魔力，好让它们足够强大，不然我可没法阻止那些被召唤来的“朋友们”对我们大开杀戒。$B$B我在奥特兰克有一个名叫布洛金的地精朋友，他能教你制取冰霜之油的方法。', '找到冰霜之油，把它交给荒芜之地的鲁特维尔·沃拉图斯。', '太伟大了!这应该是配合我的新护腕的最佳冷却剂。假如这上面的魔力不能持续一百年，那我甘愿把所有的财产都交给阿布。$B$B在我完成这件工作以后，学会里的所有法师都会对我敬畏万分的，$N。等着瞧吧。', '你找到我需要的冰霜之油了吗?那东西对我的研究很有帮助。', '', '去荒芜之地找漫尘盆地的鲁特维尔·沃拉图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (714, '发条式什么什么仪', '$N，你所做的一切都是超一流的。$B$B<鲁特维尔的注意力显然从工作中移开了>$B$B如果我们曾在卡拉诺斯见过，你随时都可以来申请工作。$B$B哎呦！快抓住……对，那个。谢谢。$B$B我现在还需要一件东西。虽然是件小东西，但是也非常关键的东西，它就是精密的发条式同步协调陀螺仪。$B$B如果你能帮我找一个的话，我就能完成工作啦。', '给荒芜之地的鲁特维尔·沃拉图斯带去一个发条式同步协调陀螺仪。', '哈!$B$B<鲁特维尔从你那里夺过发条式同步协调陀螺仪。>$B$B好极了……就快要完成了。哦，事实上，我已经差不多完成了。这项工作是我……这段时间的首要任务。让我把这个安上去，然后你就能看到你究竟帮我完成了一桩怎样的壮举。', '好，好，好，请等一下。$B$B<鲁特维尔又继续和他的小装置打交道去了。>', '', '去荒芜之地找漫尘盆地的鲁特维尔·沃拉图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (715, '卢希恩的药水', '我想你为鲁特维尔找的那些东西会不会给我们带来什么麻烦，$N。另一方面，你已经在帮助鲁特维尔神圣的科学研究的过程中体现了超凡的才能，那么帮帮我如何？$B$B我需要一瓶隐形药水和一瓶治疗药水。如果他的进展一切顺利，这两件东西都必须及时到位。$B$B作为报酬，我会给你这个配方，它是我向鲁特维尔求学时，在鲁特维尔长期以来在荒芜之地的研究成果的基础上开发出来的。', '为荒芜之地的卢希恩·枪穗找到一瓶次级隐形药水和一瓶治疗药水。', '太好了!$B$B我的意思是，谢谢你，$N。这些东西在穿越荒芜之地时会很有用处。', '他差不多接近完成了。你这边进展得如何?', '', '去荒芜之地找漫尘盆地的卢希恩·枪穗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (716, '有备无患', '我知道鲁特维尔疯狂起来会有多么危险，你最好让我给你制作一些装备以防万一。也许它能保护你免受鲁特维尔新发明的折磨。$B$B我一直都在研究那些你给他找来的石头，所以我想我能造出一些不错的护腕来供你使用。嗯，它们当然都是附有魔法的。$B$B我只需要一些铁匠打造的青铜花纹护腕就可以帮你造出附魔的护腕了。', '给荒芜之地的卢希恩·枪穗带去一些青铜花纹护腕。', '拿去吧，$N，赶快戴上这些东西。', '$N，我不会为那个护腕而等待太长时间。$B$B天知道接下来会发生什么……', '', '去荒芜之地找漫尘盆地的卢希恩·枪穗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (717, '大地的震颤', '显然，我们不能保证黑龙布莱克拉什和赫玛图斯仍能被囚禁在莱瑟罗峡谷里。大批黑龙盘踞在那里的现状以及食人魔试图偷走大地印章的事实说明后面将会有更可怕的事情发生。$b$b黑龙的监狱由三块符石维持着，只有使用大地印章才能得到它们，而那些符石就是打破封印的关键。$b$b$n……我们要确保那些黑龙的梦想永远无法成真。', '用大地印章激活钻石柱、玛瑙石柱和紫水晶石柱并拿到三颗符石。$b$b把符石放在大地封印上，释放黑龙布莱克拉什和赫玛图斯。$b$b杀了这两条黑龙，把布莱克拉什的锁链、赫玛图斯的锁链和大地印章交给加瑞克。', '肯瑞托不用再为莱瑟罗峡谷里的囚犯们担忧了。我将把这个好消息报告给我的主人。克拉苏斯无疑会很高兴的。', '虽然很久以来黑龙的监狱一直被强大的魔法力量所保护着，但我们还是不能让布莱克拉席和赫玛图斯有任何逃脱的机会。', '', '去荒芜之地找铁趾挖掘场的加瑞克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (718, '饥肠辘辘', '在匆忙撤出奥达曼挖掘场的途中，我们不得不丢弃了很多补给物资，那些柯什营地里的食人魔像兀鹫看见了腐烂的尸体一样疯狂地掠夺我们扔掉的物资，呃，那些家伙闻起来也和晒了好几天的尸体没什么区别……$b$b不管怎么说，他们抢走了我们装着武器的马车，而且现在……现在的状况实在是只能用窘迫两个字来形容了——我们现在几乎什么吃的都找不到了。$b$b就连腌菜也要吃光了，你看……能不能帮我们弄点什么吃的来？', '帮西格鲁·铁斧找回补给箱。', '多谢，$N。你走了以后，我……嗯……我吞了一把沙子，那滋味真是……$B$B算了，不提那些了，我们今晚就出去弄点吃的，美美地吃它一顿!', '在沙漠里挨饿真是糟糕透顶，我的朋友，我跟你说……你知道那有多糟么?$B$B嘿……那是什么东西……', '', '去找荒芜之地的西格鲁·铁斧。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (719, '矮人的工具', '你好，$c。千万要小心四周。这里到处都是黑铁矮人，似乎都是属于暗炉部族的。$B$B他们刚刚袭击了我们的挖掘场……杀死了那里几乎所有的人，包括我的老板铁趾格雷兹，只有我侥幸逃了出来。$B$B挖掘场在这里的北面，我想找回我们的一些物资，尤其是我的好运锄。$B$B你能帮帮我吗？如果找不到其它的，至少帮我找回我的锄头吧。', '找到雷杜尔的好运锄，把它交给铁趾挖掘场南边的勘察员雷杜尔。', '你真是我的救星啊，$C。很高兴看到有人能教训一下这帮暗炉矮人，谢谢你的帮助。', '我不清楚暗炉矮人在找什么，但他们肯定有什么特殊的目的。', '', '去找荒芜之地的勘察员雷杜尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (722, '铁趾的护符', '你很勇敢……<咳嗽>……为了我来到奥达曼，$c。$B$B如果你真要帮助我……那么……<咳嗽>……你就必须找到……帮我找到我的护符。$B$B它在……马格雷甘·深影的手里。他就在这附近……肯定在这片废墟上。如果你不能阻止他的话，那枚护符将会引导他……<咳嗽>……找到卷轴。$N，就看你的了。$B$B请……拿到那枚护符。$B$B卷轴一旦落入黑铁矮人的手里……一切就都太晚了……', '找到铁趾的护符，把它交给奥达曼的铁趾。', '哈!<猛烈的咳嗽>$B$B我就知道你会找到这个护符的，$N。$B$B<哮喘>干得不错，$N。<咳嗽>', '暗炉氏族……<咳嗽>非常危险，多加小心。<咳嗽>你必须尽快找到护符。', '', '去找奥达曼的铁趾格雷兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (723, '铁趾的遗愿', '<铁趾捂着伤口，老半天才缓过劲来，他接着说道>$B$B找到雷杜恩，$N……把护符交给他。<猛烈的咳嗽>他……<咳嗽>知道该怎么办。雷杜恩知道我一直在寻找我们种族的起源，他也……<咳嗽>知道阻止暗炉部族是我的使命。不能让他们找到卷轴……<咳嗽>', '把铁趾的护符交给荒芜之地的勘察员雷杜恩。', '铁趾的护符?亲耳听到他已经去世的消息远比只在心里清楚这一点要让我难过得多……这枚护符是他的毕生之作，我是不会让他就这样白白死去的。', '我不得不说这是糟糕透顶的一天，不过在这糟糕透顶的地方，你还能指望有什么不糟糕的事情么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (724, '铁趾的遗愿', '好吧……谁知道下一步该做些什么？$B$B史学家卡尼克！没错！$B$B他就在铁炉堡里。我想我们可以从他那里寻求一些帮助。铁趾和他曾经共同在奥达曼挖掘古代神器，估计暗炉矮人已经对他们的底细了如指掌了。$B$B去把铁趾的不幸遭遇告诉卡尼克，然后把护符交给他——他会告诉你该怎么办。', '把铁趾的护符交给铁炉堡的史学家卡尼克。', '哦!这件事可不属于无聊的问题之列。你可能还没有意识到这件事的严重性，对吗?$B$B我对铁趾的去世感到很痛心，不过既然他让你拿来护符，就说明他了解事情有多么的危急。$B$B我们现在没有时间对铁趾进行哀悼了。$B$B让我告诉你这枚护符的价值所在吧。', '啊，你好。又是一个来向我谘询的旅人。$B$B不过$g先生:小姐;，真是对不起，我现在没时间来回答一些无聊的问题。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (725, '亡者的警告', '$N，你赶快去找顾问贝尔格拉姆，把你看到的一切都告诉他，问问他我们下一步该怎么做。这封信会让他了解的消息。$B$B与此同时，我会和铁趾的亡灵交谈，也许他所知道的事情能够帮助我们解决那帮暗炉部族的家伙带来的麻烦。让我们祈祷吧。', '找到顾问贝尔格拉姆，把便笺交给他。', '啊，是历史学家卡尼克捎来的消息。好极了。$B$B我愿意为他效劳。$B$B<顾问贝尔格拉姆拆开信仔细地阅读了起来。>', '嗯?有什么事吗，$C?', '', '去找铁炉堡的顾问贝尔格拉姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (727, '远赴铁炉堡', '石板说明了不少问题，但这还不够，远远不够！$B$B有这么一本书，它是雅格因在若干年前写的笔记，上面记载着一些……我想方设法要避开的人……他们在世界各地都珍藏着这本书的复制本。而他们中最有学问的人也一直在研究它，因为它包含着极其丰富的知识……可以让我们免遭灾难的知识！$B$B到铁炉堡去找葛利·硬骨，把徽章拿给他看看，他就会相信你是他们中的一员。向他要到雅格因的笔记……然后马上把它交给我！', '把战锤印章交给铁炉堡的葛利·硬骨。', '哦，你好，我的$g兄弟:姐妹;。', '你好。欢迎到我的商店来，不过当心不要到处乱翻。$B$B有时候，知识也会是致命的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (728, '远赴幽暗城', '石板说明了不少问题，但这还不够，远远不够！$B$B有这么一本书，它是雅格因在若干年前写的笔记，上面记载着一些……我想方设法要避开的人……他们在世界各地都珍藏着这本书的复制本。而他们中最有学问的人也一直在研究它，因为它包含着极其丰富的知识……可以让我们免遭灾难的知识！$B$B到幽暗城去找看守者贝尔杜加，把徽章拿给他看看，他就会相信你是他们中的一员。向他要到雅格因的笔记……然后马上把它交给我！', '把战锤印章交给幽暗城的看守者贝尔杜加。', '小心别太招摇，$C。总有那么一些家伙不相信我们的誓言。$B$B总有那么一些人希望我们失败。$B$B我们必须时刻小心，时刻警惕，时刻保持耐心。', '啊，有一个$C急急忙忙地跑过来了，你到这里来是为了向我学点什么吗?很好!$B$B不过请注意:知识能给强者力量，也会让弱者变得癫狂。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (731, '健忘的勘察员', '好吧，那么，霍莉……哦，不对，你不是霍莉。霍莉去哪儿啦？$b$b不说这个了，那不是我们要讨论的话题。我们必须找到那把石刷……我是说神秘的化石！我们必须找到化石。达纳苏斯的探险者协会希望能看到我的工作进展情况。$b$b如果你准备好了，就和我说一声，我们去寻找那把刷子……我是说化石！我们要找到一些能让协会满意的东西。$b$b你准备好了吗？', '在勘察员雷姆塔维尔搜寻神秘化石的时候保护他，然后回到奥伯丁的考古学家霍莉那里。', '谢天谢地，勘察员雷姆塔维尔安然无恙!我告诉过你他总是心不在焉。我真不敢相信他居然执意要待在那个有可怕怪物出没的地方。', '勘察员雷姆塔维尔还活着吗?', '护送勘察员雷姆塔维尔', '去黑海岸找奥伯丁的考古学家霍莉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (732, '大地的震颤', '我听西格鲁说，你在过去几天帮了他的大忙。现在我也需要你的帮助。我的主人，肯瑞托的大法师克拉苏斯派我来结束莱瑟罗峡谷的混乱局面。$b$b我不能透露这次任务的确切性质以及我要完成的使命，但是这个任务真的非常重要。$b$b有一伙四处游荡的食人魔偷走了一件名叫大地印章的东西，我必须要把它拿回来。如果你能帮我找到它，我就让你知道更多的消息。', '帮加瑞克取回大地印章。', '你取回了大地印章，$N，这真是个好消息。大地印章是由苦痛堡垒的黑铁矮人制造出来的，它的作用是束缚死亡之翼麾下的两个凶残的副官，黑龙布莱克拉席和赫玛图斯。', '这伙流浪的巨魔穿梭于荒芜之地的几个营地之间，这里到处肆虐的热浪和旋风让追踪他们的行动变得非常困难。', '', '去荒芜之地找铁趾挖掘场的加瑞克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (733, '搜集行动', '如果不能弄到一些物资来建构防御工事和其它的必要设施，我们在这里的处境就会非常糟糕。我发现这个地区的食人魔居然有许多金属碎片，也许传说在荒芜之地有攻城坦克失踪的事情并非杜撰……$b$b无论如何，勘察员对我们营地的状况非常担忧，所以我要尽早开工。$b$b食人魔的主营地就在火山洞穴，从这里往西一直走就能找到。', '帮西格鲁收集7块金属碎片。', '这只是一个开始，$N，在接到铁炉堡或者探险者协会的指示之前，我们只能这样。$B$B现在，我得去给我那淬火桶弄些盐来……', '嗯，我已经尽力做了我可以做到的，不过……这还不够。你找到更多的物资了吗?', '', '去找荒芜之地的西格鲁·铁斧。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (735, '星，手，心', '雅格因的笔记？你要它干什么？没关系，我不该问这个。$B$B我会帮你的，因为我这里还有一本。我们得互相帮助，对不对？这样我们才能各自获利。$B$B我需要三件宝物，把它们给我拿来，我就给你那本笔记。$B$B我不会说出它们的名字，因为可能有人正在偷听，不过我可以把这几个名字写下来。', '找齐葛利·硬骨的便笺上列出的东西，然后把它们交给铁炉堡的葛利·硬骨。', '你很机敏，$N。如果真的由你来负责为我们的组织谋取更大的利益，我相信你一定能做得很好。', '你拿到我要的东西了吗?', '', '去铁炉堡的荒弃的洞穴找葛利·硬骨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (736, '星，手，心', '你需要雅格因的笔记？一整本？当然……当然我会帮助你，我的$g兄弟:姐妹;。$B$B但你也得帮我。$B$B我需要三件威力强大的物品，把这些物品给我找来，笔记就是你的了。$B$B我不能把它们的名字说出来，不过我可以给你写下来。$B$B把这个单子上的东西找来，如果你能完成这个任务，那么你就有能力接到更重要的工作。', '把贝尔杜加的便笺上列出的东西带给幽暗城的看守者贝尔杜加。', '我很满意!能找到这些东西说明你很有能力……或者是运气很好。不管怎么样，你对我们都很重要。', '你的任务完成得怎么样了，$N?', '', '去找幽暗城的看守者贝尔杜加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (737, '禁断的知识', '$n，我这里有你想要的笔记，我想不需要我再提醒你要保管好它了吧？特别是绝对不要让它落入敌人之手。$B$B这本书里记录了很多真相……$B$B……可以毁灭你的真相。', '把雅格因的笔记交给塞尔杜林。', '你拿到它了!我们又有希望啦!$B$B你所做的一切也许能拯救我们，$N。他们应该为你筑一座纪念碑!他们应该为你建一座神殿!你的名字将名垂千古!$B$B除非……那些家伙获得了自由，重新回到了地面。如果是那样的话，就别想着什么千古啦。$B$B如果它们自由了，我们都会万劫不复!', '有些日子没见你了，拿到笔记了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (739, '莫达洛克', '阿戈莫德留下的足迹表明他是从西边走过来的。从沙石上的斑斑血迹不难看出，矮人阿戈莫德爬行了好一段距离。$B$B爬到这里的时候，他终于被死神带走了。$B$B经过仔细显示，你在旁边的沙石中发现了几个潦草写下的字迹：“莫达洛克”。$B$B字迹就在阿戈莫德的手边。', '干掉杀害阿戈莫德的凶手：莫达洛克。$B$B顺便杀掉12个石窟断骨者。$B$B然后向洛克莫丹的勘察员基恩萨·铁环报告。', '这真是令人震惊的消息，$N。埃格蒙德是个强壮勇敢、久经沙场的矮人，而且他生来就是个出色的战士!尽管他最终还是被那帮该死的石腭怪杀害了，但我确信他肯定在战死之前干掉了一大票石腭怪。', '你有关于埃格蒙德的消息吗?你找到他了吗?', '', '去洛克莫丹找铁环挖掘场的勘察员基恩萨·铁环。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (741, '健忘的勘察员', '勘察员雷姆塔维尔要把神秘的化石送给达纳苏斯的探险者协会？可是我不太想把他一个人留在这里。$b$b给你，$n，把这块神秘的化石交给达纳苏斯的首席考古学家杜瑟·灰须。', '把神秘的化石交给达纳苏斯的首席考古学家杜瑟·灰须。', '哦，天哪!把这个发现留给勘察员雷姆塔维尔吧!', '$C，有什么我可以帮你的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (743, '风怒鹰身人', '谢谢你抽时间来和我谈话，$N。我是鲁尔，既是一个战士，也是一个导师。$B$B如果你想在莫高雷之外经历更多冒险的话，现在正是让你接受更多考验的时候了。$B$B如果你想测试自己的能力，就去东南方找风怒鹰身人作战吧。他们驻扎在山边远离大路的地方。$B$B鹰身人是我们的天敌，对你来说，和他们战斗会是个不错的考验。', '给血蹄村的卢尔·鹰爪带回8只风怒鹰身人的爪子。', '你干得很好，$N。看来你已经准备好继续前进了。希望你一路顺风。', '风怒鹰身人是我们的死敌，这些家伙顽强的作战能力和它们对新鲜血肉的强烈嗜好一样名声在外。', '', '去莫高雷找血蹄村的卢尔·鹰爪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (744, '准备典礼', '$N，我的兄弟很快就要去面见血蹄酋长了，我要为他做一个头饰，这对我来说是一种荣耀。$B$B在我处理这些皮革的时候，你能不能帮我一个忙？我没有时间去收集足够的羽毛，不知道你能否帮助我去收集一些呢？$B$B你应该可以在雷霆崖北面和西北面的鹰身人身上找到尺寸合适的羽毛。我需要6片碧蓝色的和6片古铜色的羽毛来完成我的头饰。', '收集6根碧蓝色的羽毛和6根古铜色的羽毛，把它们交给雷霆崖的伊恩·鹰爪。', '非常感谢你的帮助。$B$B我兄弟典礼上面该由我承担的那部分职责已经几乎完成，现在我只要去把头饰交给他，然后参加他的典礼就可以了。', '这个头饰无疑是给我兄弟的最好的礼物。', '', '去找雷霆崖\r\n的伊恩·鹰爪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (745, '土地之争', '这片土地上有很多纷争，$N。我希望你不会象我一样经历那么多的战争，不过我还是希望你去做一件事，让你可以了解到，一个看似不值一提的小小威胁如果不加制止的话，会对我们的领土带来多大的危害。$B$B白鬃豺狼人已经在西边的一个洞穴中和血蹄村的南边扎了营。我们曾试图和他们交流，却被他们无理地拒绝了，而且他们还大肆屠杀莫高雷的野生动物。$B$B现在语言已经不能解决问题了，我们必须有所行动。', '杀死10个白鬃制革工、8个白鬃剥皮工和5个白鬃偷猎者，然后回到血蹄村向贝恩·血蹄复命。', '$N，你认真地完成了我交给你的任务，这让我感到很欣慰。尊重这片土地和生活在这片土地上的生命，这一点很重要。死亡和生命是一个轮回……这是无法避免的。任何生命都要经历这种轮回。好好思考我说的话，希望你永远都不要忘记。', '如果白鬃豺狼人尊重这片土地和这里的居民的话，这场冲突就不会发生了。', '', '去莫高雷找血蹄村的贝恩·血蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (746, '矮人的挖掘场', '西北部有些矮人正在准备修建一座挖掘场。他们认为地下埋藏着某些秘密，事实也的确如此，不过挖掘和污染大地并不是获得这些秘密的正确途径。$B$B收集矮人的挖掘工具，把它们全都毁掉，然后把这些被损坏的工具带给我。$B$B要毁掉这些工具的话，你必须得找到一块铁砧才行。在雷霆崖就有一处铁匠铺，不过任何铁砧——包括矮人营地里的——都可以用来毁掉工具。', '收集5个勘察员的锄头。$B$B在铁匠铺砸碎这些勘察员的锄头。$B$B把5件损坏的工具交给血蹄村的贝恩·血蹄。', '谢谢你，$N。这下莫高雷的野生动物都可以安心了。而且如众灵所愿，这样也可以教教那些矮人，挖掘土地不是获得知识的好方法。', '你好，$N。你带来损坏的工具了吗?矮人的挖掘行动会激怒莫高雷的科多兽，我们必须阻止他们这种玷污大地的行为!', '', '去莫高雷找血蹄村的贝恩·血蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (747, '开始狩猎', '欢迎来到纳拉其营地，$n。你来到这里的消息很快就传遍了部族。或许很快有一天你会被迎去雷霆崖上的大城市里，但首先，你必须先向我们证明你的能力。$b$b我们这些生活在红云台地上的牛头人无疑对自己优秀的狩猎技术最为自豪，当然，牛头人只为生存需要和竞技而狩猎。我们库存的肉已经不多了，另外我们还需要羽毛来做衣服。现在去猎杀附近的平原陆行鸟来给村庄提供补给吧，同时你也可以借此证明自己的能力。', '纳拉其营地的格鲁尔·鹰风要求你带给他7片平原陆行鸟的羽毛和7块平原陆行鸟肉。', '纳拉其的牛头人感谢你，$N。你前途无量。', '为部族带回肉和羽毛是你在酋长面前证明自己的第一步。', '', '去莫高雷找纳拉其营地的格鲁尔·鹰风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (748, '毒水', '那些地精和他们的爪牙污染了我们神圣的水井！我们必须制止他们！$B$B要想净化所有的水井，我得先制造出相应的净化图腾，然后你把图腾拿到水井那儿去完成净化的仪式。$B$B首先，我们给冰蹄之井制作一个净化图腾，这需要大地的帮助。去猎捕一些草原狼和成年平原陆行鸟，把它们的爪子带回来给我，它们就在西南方活动。', '收集6只草原狼的爪子和4只平原陆行鸟的爪子，把它们交给血蹄村的穆尔·雷角。', '你干得很好，$N。我会把它们的力量用于净化图腾上。', '你拿到那些爪子了吗，$N?', '', '去莫高雷找血蹄村的穆尔·雷角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (750, '继续狩猎', '善于狩猎的牛头人从不仅仅将他的猎物看作战利品，这些生活在平原上的野兽对我们的生存有着极为重要的意义。如果你能带回一些珍贵的山狮皮的话，就会令部族里的长老们对你刮目相看。你可以在南边的山区找到它们。$b$b我们的孩子需要衣服，部族里的帐篷也需要维修了。', '纳拉其营地的格鲁尔·鹰风要求你带给他10张山狮皮。', '纳拉其的牛头人感谢你找到这些补给，$N。以你的狩猎能力，你的赫赫声名早晚会传到雷霆崖。', '如果你能给部族带回这些皮毛的话，我会把你的功绩告诉我的父亲，鹰风酋长。', '', '去莫高雷找纳拉其营地的格鲁尔·鹰风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (751, '被破坏的货车', '撬开盖子之后，你发现了堆得满满的矿石，这又一次证明了风险投资公司确实在莫高雷地区有采矿活动。在矿石的最上面有一捆文件。$b$b你可以依稀听见东部丘陵的顶部传来丁丁当当的声音，还可以看见从一大堆篝火上升起的浓烟。', '把风险投资公司文件交给血蹄村附近的摩林·云行者。', '看来风险投资公司真的是企图掠夺我们的自然资源。那么，我们就必须得采取一些行动了。', '你好，$N。你知道风险投资公司准备在我们的土地上做些什么吗?$B$B如果他们像对待别的土地那样来开采这片土地上的资源，我们就一定要阻止他们。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (753, '一件琐事', '我这一生也算是经历了不少磨难，走了不少路，现在我这一把老骨头也没什么力气啦。我仍然在为部族尽力，但有些时候，我还真感觉有些力不从心。$b$b不过，你这$c似乎是正想找点什么事情做做呀。正好，让我来看看你的体力如何吧。把水井旁的这个水罐交给我儿子，他就在纳拉其营地里。$b$b记住，即使是最琐碎的小事，只要你做得够好，也能获得长老们的首肯。', '在井边拿一只水罐。$b$b把它带给纳拉其营地里的鹰风酋长。', '你按她的吩咐把水罐带回来了。$B$B你乐于帮助纳拉其营地的牛头人，这种精神让我相信你总有一天会在雷霆崖为部族争得荣誉的。', '看来你是刚从平原那边回来的吧。你带我母亲的口信来了吗?', '', '去莫高雷找纳拉其营地的鹰风酋长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (754, '净化冰蹄之井', '我已经做好了可以净化冰蹄之井的图腾。现在你就把它拿到那儿去完成净化仪式。冰蹄之井就在东南边，有许多地精把守着那里！$B$B这不是个简单的任务，不过如果我们想要重新使用那里的水，就必须得这么做。$B$B祝你好运，$N。', '用冰蹄之井净化图腾为冰蹄之井完成净化，然后回来见穆尔·雷角。', '我刚听说你完成了任务―水井附近的野生动物已经开始迫不及待地喝水了。$B$B你为我们这片土地上的生灵做了一件好事，$N，你也为牛头人做了件好事。', '不要耽误时间，$N。冬蹄之井的污染一定要尽快清除!', '净化冰蹄之井', '去莫高雷找血蹄村的穆尔·雷角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (756, '雷角图腾', '要制作雷角之井净化图腾，你必须先去收集莫高雷平原上的肉食动物的爪子。去捕猎草原捕食者和平原狮，然后把它们的爪子带回来见我。$B$B它们就在这里的东边和西边活动。', '收集6个草原捕食者的爪子和6个平原狮的爪子，把它们带给穆尔·雷角。', '谢谢你，$N。这些动物做出的牺牲会让在雷角之井旁繁衍生息的所有动物都受益匪浅。$B$B哥布尔永远无法理解与大地抗衡和与之和谐相处的区别。', '$N，你找到我要的爪子了吗?雷角之井的污染已经越来越严重了!', '', '去莫高雷找血蹄村的穆尔·雷角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (757, '力量仪祭', '大地之母仪祭对于每一个想要在雷霆崖得到尊重的年轻牛头人来说都是非常重要的。$b$b但在那之前，你必须先通过力量仪祭的试炼。在这个试炼中，你必须通过杀死部族的敌人来证明你的勇猛。$b$b生活在东边的刺刃峡谷中的刺背野猪人侵占了我们部族不少的土地，他们偷袭我们的狩猎小队，还在晚上到村子里来偷东西。$b$b杀死他们，展示出你的英勇无畏吧。拿着它们的腰带去见纳拉其营地的酋长，他将证明你通过了试炼。', '杀掉刺刃峡谷的刺背野猪人并带回8条刺背腰带，把它们交给纳拉其营地的鹰风酋长。', '你通过了大地之母祭仪的第一个试炼，部族将会以你为荣。', '你完成力量祭仪了吗，$N?我要求你通过杀死部族之敌―刺背野猪人来证明你的英勇。', '', '去莫高雷找纳拉其营地的鹰风酋长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (759, '蛮鬃图腾', '还剩下一口井需要净化，它是以蛮鬃部族的名字命名的。要想净化这口井，你必须从大地上寻找一种凶猛的肉食动物的牙齿，那就是草原狼前锋的牙齿。去北边寻找草原狼前锋，拿到我要的东西之后再回来。$B$B这些草原狼前锋经常在雷霆崖的山脚下游荡。', '收集8颗草原狼前锋的牙齿，把它们交给血蹄村的穆尔·雷角。', '很好，$N。我可以感受到大地做出的牺牲，这让我既骄傲又悲伤。', '你找到我要的牙齿了吗，$N?', '', '去莫高雷找血蹄村的穆尔·雷角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (761, '猎捕猛鹫', '猛鹫是一种狡猾无比、很难猎捕的鸟。收集猛鹫的羽毛可以证明一个猎手的智慧和决心。$B$B如果你想接受这个任务，就去平原上猎捕猛鹫吧。$B$B把它们的羽毛带给我，为你的部族赢得荣誉。$B$B猛鹫在莫高雷的任何地方都能找到，不过要发现它们，你得有锐利的眼睛；要捕捉它们，你得有灵活的手脚。', '收集8根猛鹫的羽毛，把它们带给血蹄村的哈肯·风之图腾。', '我知道收集这些羽毛不是简单的事，$N。你已经证明了你是一个优秀的$C。', '你找到猛鹫了吗，$N?拿到它们的羽毛了?', '', '去莫高雷找血蹄村的哈肯·风之图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (762, '邪恶的使者', '拉格纳罗斯派因弗努斯大使到苦痛堡垒去监督暗炉矮人在奥达曼挖掘神器的工作。$B$B我们的同胞已经遭受了惨重的伤亡，然而这样的情况仍然在继续。我不愿去猜测他们会找到多少强大的神器并用它们来对付铁炉堡。$B$B我们的目的很简单，$c。回到荒芜之地去，干掉因弗努斯大使。在除掉了这个威胁之后，把你完成任务的证据交给顾问贝尔格拉姆。$B$B现在马上出发吧。', '杀死苦痛堡垒中的因弗努斯大使，把证明他已死亡的信物交给铁炉堡的顾问贝尔格拉姆。', '$N，你对铁炉堡做出了巨大的贡献，感谢你给我们提供的帮助。$B$B我会捎口信给历史学家卡尼克，告诉他你凯旋而归的消息，我也会尽快为荒芜之地的挖掘场提供物资补给。再次感谢你。$B$B在你走之前，我还有一件事情希望你去做。', '时间紧迫，$N。拉格纳罗斯不会给我们时间来准备的。', '', '去找铁炉堡的顾问贝尔格拉姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (763, '大地之母仪祭', '要想继续大地之母仪式，你必须先通过两个小试炼。现在也正好是你去积累积累经验的时候了，$n。$b$b到血蹄村去找那里的酋长，凯恩之子贝恩·血蹄吧。你可以在那儿继续你的冒险历程并得到雷霆崖的长老们的承认。$b$b把这个图腾带给贝恩。他会读懂我刻在上面的符号，并帮助你继续修行。$b$b顺着这条从纳拉其营地通向外面的路快点出发吧，千万别迷路了。', '顺着离开纳拉其营地的路将鹰风图腾带给血蹄村的贝恩·血蹄。', '我的好友鹰风酋长写给我的信!啊，我能从这些符号中看出他对你的关心。', '欢迎来到我的村庄，$C。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (764, '风险投资公司', '这就解释了为什么风险投资公司在不断往莫高雷地区增派职员和设备。这些地精……他们的公司扩张得太快了。就像他们自己所说的那样，只要给地精一点甜头，你就能听到他们打算盘的声音。$b$b这些小东西实在是太贪婪了。不过我们牛头人决不会让他们在我们的领土上为所欲为。到他们的矿洞去，给他们点颜色看看，那个矿洞就在被破坏的货车的东北方。', '血蹄村的摩林·云行者要你去杀死14个风险投资公司工人和6个风险投资公司主官。', '他们应该不会误解或是忽视我们发出的信号，对不对?风险投资公司很快就会知道牛头人是不可轻视的，他们也不能如此傲慢地以为我们会对他们这种大肆掠夺的行为不闻不问。', '我们已经剥夺了风险投资公司在莫高雷的采矿权，不过看来他们根本不在意我们做了些什么。牛头人向来不喜欢拐弯抹角，我们有自己的方法来让他们了解我们的意图。', '', '去找莫高雷的摩林·云行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (765, '菲兹普罗克主管', '根据你从箱子里拿来的文件可以看出，风险投资公司已经制定了很多把我们从这儿赶走的计划，然后他们就能随心所欲地掠夺我们的土地了。$b$b他们为了利润居然可以堕落到这种程度，这简直让我感到厌恶和惊骇。我们要除掉这个阴谋的策划者，他就是菲兹普罗克主管。你可以在被破坏的货车以东的风险投资公司矿洞里找到他，把他的笔记板带给我，让我们看看有没有什么有价值的东西。', '杀掉菲兹普罗克主管，把他的笔记板带给血蹄村的摩林·云行者。', '听到菲兹普罗克主管死了的消息，我的怒气平息了一些。我可以从他的笔记板里找找看风险投资公司都有些什么更长远的计画。谢谢你的帮助，$N。', '风险投资公司居然为了利益就准备对我们采取这些行动，这让我非常恼火。', '', '去找莫高雷的摩林·云行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (766, '马兹拉纳其', '我祖父曾讲述过他和一只叫马兹拉纳其的陆行鸟战斗的故事，说起过它那邪恶的红眼睛，剃刀般锋利的爪子，只要被它咬一口，你就会身中剧毒。$b$b在我穿越平原的时候，正巧遭遇了它，肩膀被它咬了一口。它比我祖父所说的还可怕！我需要一些东西来帮我解毒：一颗狼心，狮子的腿骨，平原陆行鸟的鳞片和猛鹫的胃。$b$b快点，我快要不行了。', '收集草原狼的心脏、平原狮的腿骨、平原陆行鸟的鳞片和猛鹫的胃各一份，把它们交给血蹄村的茂尔·祈雨。', '啊，谢谢你，$N。用你拿来的这些东西做成的解药可以制止毒素的扩散，最终令伤口痊愈。谢谢你，是你救了我一命。$B$B不过我永远无法忘记马兹拉纳其向我扑过来的时候……它发出的那种刺耳的叫声和它那利刃一样的爪子……$B$B你碰到它的时候也要多加小心啊。', '我发烧发得越来越严重了，而且脑子也开始神志不清，不断做梦魇……我早该知道，我祖父对付不了的野兽我也肯定对付不了……$B$B你找到解毒药了吗?如果再不清洗染毒的伤口，我就死定了。', '', '去莫高雷找血蹄村的茂尔·祈雨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (768, '收集皮革', '你好，年轻的$r。我从你的眼中看到了你重回原野捕猎的渴望。希望你能为你的部族带来荣耀！$B$B我擅于利用各种兽皮来为雷霆崖的居民制作护甲和衣物。$B$B如果你能帮我搞到一些兽皮的话，那我就可以用它们来为你制作一些你需要的东西。', '收集12块轻皮，把它们交给雷霆崖的维尔伦·陆行者。', '啊，这些皮革真不错。用它们一定能做出上好的皮质装备来。$B$B给你，$N，这是你应得的报酬……', '你好。你的狩猎行动怎么样了?你拿到我需要的兽皮了吗?', '', '去找雷霆崖的维尔伦·陆行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (769, '科多兽皮包', '莫高雷的科多兽强壮而凶猛，它们的这些特质备受我们尊敬。如果你善于皮革加工，而且希望获得制作科多兽皮包的知识，那就给我弄点材料来吧。$B$B弄些材料来，我就会把我的手艺传授给你。', '给雷霆崖的维尔伦·陆行者带去4块轻皮和4份粗线。', '啊，很好。谢谢你，$N。看到一个年轻的$C能对皮革制作这么感兴趣，我的心里很是欣慰。', '你弄到我需要的材料了吗，$N?', '', '去找雷霆崖的维尔伦·陆行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (771, '幻象仪祭', '要想通过幻象仪祭，你必须先找到制作先知之水的试剂。$b$b我需要一些水井石，你可以在莫高雷一带的水井附近找到它们。另外，你还得在这周围的大树下面找到一些琥珀颗粒。$b$b这两种东西都具有强大的元素力量，把它们结合起来，用部族之火点燃之后，你可以看到一个幻象。追随它，它就会引领你进入这个神圣使命的下一个阶段。', '收集2块水井石和2个琥珀颗粒，把它们带给血蹄村的扎尔曼·双月。', '看得出来，你已经知道如何从我们神圣的土地上寻找圣物了，$N。给我点时间，让我来准备先知之水。', '等你收集到水井周围的水井石和大树下的琥珀颗粒之后，我就可以为你准备先知之水了。', '', '去莫高雷找血蹄村的扎尔曼·双月。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (776, '大地之母仪祭', '你已经通过了大地之母仪祭，在雷霆崖赢得了你自己的一席之地。$b$b不过要维持你现在获得的荣誉，你还必须不断证明你自己的价值。$b$b我们生来就是猎手，$n。在莫高雷城下有一只非常强大的科多兽，我们称它为阿兰其亚。把它的角带来，向我证明你追踪和捕猎的能力。', '雷霆崖的凯恩·血蹄要你将阿兰其亚的角带给他。', '干得好!真是一次完美的狩猎!$B$B我会派人把那具尸体拉回来，这可以给我们提供充足的兽皮和肉食。$B$B你为你的族人立了一大功，$N。', '你找到阿兰其亚了吗?', '', '去莫高雷找雷霆崖的凯恩·血蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (777, '不祥的感觉', '好吧，拿去吧。$B$B我现在要去找个掩体……$B$B你要不要一起来？', '把5号齿轮交给鲁特维尔·沃拉图斯。', '啊，完美。退后，我要创造历史!$B$B<鲁特维尔继续兴奋地工作着。>', '<鲁特维尔并没有从他对镣铐的研究中抬起头来，他只是伸出一只手，不耐烦地晃动着指头。>$B$B把齿轮给我，$N，齿轮!', '', '去找荒芜之地的鲁特维尔·沃拉图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (778, '不祥的感觉', '哈哈！完成啦！镣铐完成啦！$B$B记住这个时刻，卢希恩,记住这个时刻，阿布！你准备好了吗？你将亲眼看见炼金术、工程学和魔法的完美结合。$B$B我将召集一个强大的元素生物。今天，对于我们来说，是具有里程碑意义的一天！', '击败法姆雷托守护者，并将鲁特维尔的元素禁锢镣铐交还给鲁特维尔。', '谢谢你，$N。这是一场严酷的考验，对吧?$B$B我不清楚是在什么环节出了错误。不过幸好，我的魔法还在，还能把这家伙送回老家。$B$B为了表示对你辛勤工作的感谢，请拿着这个……', '这跟我预期的结果有些偏差……你能取回我的镣铐吗?', '', '去荒芜之地找漫尘盆地的鲁特维尔·沃拉图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (779, '大地封印', '', '', '你把符石放进对应的凹槽之中，大地随即猛烈地震动起来，发出了巨大的轰鸣声，与此同时封印也破碎了。', '大地封印就在这儿，三个凹陷的壁龛分别对应着紫水晶符石、蛋白符石和星钻符石。', '', '去找荒芜之地的大地封印。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (780, '斗猪', '生活在东边的刺刃峡谷中的斗猪已经侵占了我们部族的狩猎场。正在与我们交战的刺背野猪人把这些野猪训练成了凶暴而富有攻击性的生物。$b$b去把这些可恶的家伙杀掉，再带些猪头和肋排回来，我们可以炖肉给孩子们吃。', '纳拉其营地的格鲁尔·鹰风要求你去干掉斗猪，并带给他8块斗猪头和8块斗猪肋排。', '太棒了!这些东西足够够我们开一次宴会，被杀的野猪也够让那些邪恶的刺背野猪人收敛一些了。', '斗猪的数量正在不断增加。你有没有教训过它们?有没有带回猪头和肋排来?', '', '去莫高雷找纳拉其营地的格鲁尔·鹰风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (781, '纳拉其营地的危机', '在仔细查看了地图之后，你意识到刺背野猪人的酋长正计划着对纳拉其营地展开进一步攻击。$b$b鹰风酋长必须马上得知这个消息。', '将刺背野猪人的进攻计划交给纳拉其营地的鹰风酋长。', '这太让人吃惊了!但是现在既然我们已经知道了这个消息，就可以请求血蹄村的同胞与我们一起抵御这次攻击。你挽救了许多牛头人的生命，$N。', '你看起来脸色不太好，$N。你带来了什么消息?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (782, '破碎的联盟', '在第二次兽人战争期间，部落与死亡之翼之间曾有过盟约，我们也因此得知死亡之翼的两个副手——黑龙布莱克拉什和赫玛图斯——现在正被囚禁在莱瑟罗峡谷里。$b$b如今我们要让堕落的昔日盟友们“安静”一点，我们要恢复部落的荣耀。我们雇佣了索格伦和他的食人魔雇佣兵团帮我们夺回大地印章，也就是那把可以打开黑龙监狱的钥匙。$b$b然而，索格伦背叛了我们，他打败了我们，将大地印章占为己有。', '杀掉索格伦，把大地印章交给卡加斯的高恩。', '索葛兰死了，他的尸骨在沙漠狂风的侵蚀和秃鹫的蚕食下已经无处寻找。那些失去了领袖的巨魔很快就将陷入混乱。虽然这只是一次小小的胜利，但是它却预示着更大的胜利即将到来。大地印章在我们的手里，我们就能打开莱瑟罗峡谷中的黑龙监狱，放出那两个原本应该被永久囚禁的家伙，把它们彻底干掉!', '索葛兰的背叛……你对于巨魔已经脱离部落的事实还有什么疑问么?如果他死了，我想我会很高兴的，那样的话我们就能重新夺回大地印章了。', '', '去找荒芜之地的高恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (784, '背信弃义的人类', '库尔提拉斯的人类曾在普罗德摩尔将军的率领下大举进攻杜隆塔尔，彻底破坏了在共同抵抗阿克蒙德和他的恶魔大军时由酋长和吉安娜·普罗德摩尔定下的互不侵犯协议。$b$b我们击退了人类的进攻，并攻下了提拉加德城堡。但最近，由本尼迪克上尉率领的后备军又重新占领了提拉加德城堡，对我们的家园构成了新的威胁，这些人类从不遵守外交协议。$b$b到南方的提拉加德城堡去消灭那些人类侵略者，证明你的勇气和荣誉。', '杀死10个库尔提拉斯水手和8个库尔提拉斯水兵，再把本尼迪克上尉干掉，然后回剃刀岭向加索克复命。', '你的英勇已经尽人皆知，$C。你在提拉加德城堡所获得的胜利将在奥格瑞玛广为传诵。', '你已经接到命令了，$N。杜隆塔尔正处于危机之中。完成你的任务，否则就在羞耻中悬梁自尽吧。$B$B证明你的荣誉和勇气，击败提拉加德城堡的人类。', '', '去找杜隆塔尔的加索克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (786, '科卡尔半人马的进攻', '小声点，$c。科卡尔半人马就在西边科卡尔峭壁的山脊上。$b$b昨天晚上，我潜入了他们的村庄，发现这些肮脏的野兽准备同时向杜隆塔尔的巨魔和兽人发动三波攻势。$b$b我们决不能让他们的入侵计划得逞！你可以召集一些兵力，潜入科卡尔峭壁并粉碎他们的进攻计划。$b$b他们已经把进攻计划分别交给了三个首领，准备由他们率领三股部队同时行动。', '在森金村外面的拉尔·猎齿要求你粉碎科卡尔峭壁内的三份进攻计划。', '即使科卡尔半人马进攻，我们的部落也一定会赢得胜利，但是那样的话势必会让我们的战士有不必要的伤亡。$B$B在度过这个艰难的阶段之前，我们有时不得不为了保卫自己的国家而流血。$B$B你已经尽了你应尽的义务，$C。', '半人马一直都是部落的心头大患，我们决不能让他们的进攻计画得逞!', '', '去杜隆塔尔找森金村的拉尔·猎齿。', '试炼谷进攻计划已经被摧毁', '森金村进攻计划已经被摧毁', '奥格瑞玛进攻计划已经被摧毁', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (788, '小试身手', '第一项任务将在力量方面对你进行考验。我本来可以把你派去贫瘠之地猎杀科多兽，不过呢，照实说，你活着比死了对我们来说更有用。$b$b我相信你更合适和那些杂斑野猪斗一斗，往北边走就可以找到它们。', '杀掉8只杂斑野猪，然后向大兽穴里的高内克报告。', '嗯，不错啊，$N。但你可别因此就洋洋自得起来……你总有一天会遇到比这些野猪更强的敌手。$B$B尽管如此，你还是证明了自己的价值，在下一个试炼之中，你会遇到一些更危险的对手，所以你应该会需要一些新的护具。', '我希望你在完成任务之前先不要回来找我，$N，好吗?不不，当然我并不怀疑你的能力。我对你还是抱有很大希望的。', '', '去杜隆塔尔找试炼谷的高内克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (789, '工蝎的尾巴', '无论是强大的战士还是笨拙的新手，都有可能会倒在蝎尾上的毒针之下。在这里的西北方有大量蝎子在活动，给我带8条蝎尾回来，以此来证明你的战斗能力吧。$b$b事实上，它们尾巴上的毒针正是制作解毒剂的重要材料，解毒剂便是从毒针中提取的。我们需要长期备有大量的解毒剂，以防止像你这样的新手被蝎毒所害……$b$b但我肯定你是不会需要这种玩意的，对吧？', '给大兽穴中的高内克带回8根工蝎的尾巴。', '在与这些蝎子战斗的过程中，你会学到重要的一课。无论是看起来多么不起眼的对手，都可能会让你陷入恐惧之中。在激烈的战斗中，任何东西都将可能会把你击倒，这一点你千万要小心，以后不要在阴沟里翻船。$B$B我已经没什么可教给你的了，$N。你表现得非常不错，但我以后仍然会关注你的成长。', '对于一名有着坚定决心的战士来说，蝎子坚硬的表壳其实就像纸一样脆弱。不要犹豫，给那些蝎子以最沉重的打击吧，你会发现它们真的非常脆弱。', '', '去杜隆塔尔找试炼谷的高内克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (790, '萨科斯', '$C！我差点就神不知鬼不觉地死在这鬼地方了！我在谷里捕猎蝎子的时候，突然看到一只看上去特别凶恶的蝎子。当时我就决定以它为猎物，打算在它那硕大的钳子钳住我的腿以前，先重重地给它来上那么一下子。$b$b但我忘记了它还有根毒刺，毒刺猛扎了下来，一下子就刺进我的胸口。拜托，你一定得替我报仇！只有这样才能留存我的名誉！我是在南边的高地上碰上它的。', '杀死萨科斯并将它的爪子带回去交给哈纳祖。', '我的实力还不足以杀死它，但看着我能给它造成了这么严重的伤害，我还是有那么一点点自豪的。如果我死了，这点自豪就是我可以用来慰藉自己的全部了，我一生中所完成的事实在是太少了，这实在令我愤懑不已。', '啊……父亲经常说，我不会太出众，看来，他是对的，现在的我就只能这样躺在树下慢慢等死……$B$B但至少，我希望在我死之前能得知我的最后一个敌人也已经被干掉了……', '', '去找杜隆塔尔的哈纳祖。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (791, '新的背包', '我太老了，已经没法上战场拼杀了。所以我开始用别的途径为部落出力，实现我的价值。$b$b我在这里监视周围的情况，我们的力量越来越强大，我吹起号角的机会也越来越少。$b$b为了打发时间，我经常给那些保卫家园的年轻战士们做些有用的东西。$b$b我可以给你做一个用来放置财物的包袱，但是你得先给我找些帆布脚料来，人类和半人马经常使用这种布料。', '剃刀岭了望塔中的弗恩·凝眉想要8块帆布脚料。', '太棒了，$N。你肯定会对这个包袱大加赞叹的!$B$B我向你致敬，为你无穷的精力和你为部落效忠的信念!', '在我们刚刚开始探索这片大陆的时候，我曾和大酋长肩并肩地奋勇作战，战争在我身上留下了累累疤痕。$B$B在击败阿克蒙德的战斗中，我以斧头和勇气维护了部落的荣誉，那时由于形势所迫，我们不得不和人类、夜精灵结成了联盟。$B$B不过现在我可以尽我所能地为部落效劳，这让我又找到了新的价值。', '', '去杜隆塔尔找剃刀岭的弗恩·凝眉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (792, '邪灵劣魔', '我相信你会在试炼谷学到很多东西，年轻的$c。$B$B我本是被派到这处谷地里来指引和教育你们的，但我却在这里发现了一些不洁之物……$B$B一群自称为火刃氏族的兽人潜入了试炼谷，他们躲进了东北方的一处洞穴里，而他们的邪灵劣魔则肆虐着周边的一大片地区。$B$B作为你对抗火刃氏族的第一个任务，我命令你消灭这些劣魔。尽可能地多杀一些，如果杀完了它们之后你还活着的话，就回来向我复命。', '杀死8只邪灵劣魔，然后向大兽穴外的祖雷萨复命。', '你干得很好，$N。$B$B尽管这些邪灵劣魔仅仅是火刃氏族的宠物而已，但你成功的行动向他们预示着，我们将采取更进一步的大规模行动。', '要想证明你的确选择了与火刃氏族为敌，那么你首先必须杀死那些邪灵劣魔。完成了这个任务之后再回来向我复命。', '', '去杜隆塔尔找试炼谷的祖雷萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (793, '破碎的联盟', '大地印章由三块符石控制，它们分别被放置在莱瑟罗峡谷的钻石柱、玛瑙石柱和紫水晶石柱中。用大地印章就可以取下符石并打开大地封印。$b$b当心点，$n，黑龙布莱克拉什和赫玛图斯是很难对付的。杀掉它们，把它们身上的锁链交给我。', '用大地印章激活钻石柱、玛瑙石柱和紫水晶石柱并拿到三颗符石。$b$b把符石放在大地封印上，释放黑龙布莱克拉什和赫玛图斯。$b$b杀了这两条黑龙，把黑龙布莱克拉什的锁链、赫玛图斯的锁链和大地印章交给高恩。', '黑龙军团仍是背叛了部落的黑石氏族的同盟，他们死罪难逃。既然布莱克拉席和赫玛图斯都已经死了，我们就可以把注意力转向西边，转向黑石塔。', '很少有敌人像龙那样可怕，也很少有龙像布莱克拉席和赫玛图斯那样残忍。', '', '去荒芜之地找卡加斯的高恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (794, '火刃奖章', '我通过预言术发现在火刃集会所的深处藏有一件蕴涵着强大力量的物品，它被一些猛兽和黑暗的魔法守卫着。$B$B那件物品叫作火刃奖章，你的下一个任务就是找到它，把它从集会所里偷出来。$B$B不过你可得小心，因为奖章的属主可能是一个火刃部落中的强者，他也许要比你以前对付过的那些家伙要强上许多倍。$B$B现在就出发吧，$N，那个洞穴就在这里的西北方。', '给大兽穴外的祖雷萨带回火刃奖章。', '你找到它了!干得好!$B$B你在燃刃集会所中所做出的努力无疑正是将这群家伙赶出试炼谷的关键一步。但我真正担心的是，他们也许对我们的土地有着更可怕的打算。$B$B当前我们还无法彻底看清他们下一步要干什么。', '你完成任务了吗，$N?你把燃刃勋章带回来没有?', '', '去杜隆塔尔找试炼谷的祖雷萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (795, '大地封印', '', '', '你把符石放进对应的凹槽之中，大地随即猛烈地震动起来，发出了巨大的轰鸣声，与此同时封印也破碎了。', '大地封印就在这儿，三个凹陷的壁龛分别对应着紫水晶符石、蛋白符石和星钻符石。', '', '去找荒芜之地的大地封印。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (806, '黑暗风暴', '$N，我有个不妙的消息。对火刃氏族的调查表明，杜隆塔尔境内还有不少这个氏族的势力。这是我们绝对不能允许的！在他们站稳脚跟、滋生邪恶之前，我们必须把他们消灭掉。$B$B有个名叫费索·暗雷的地精术士就居住在西北部的雷霆山里，他和他的那群爪牙就在那里制造混乱。$B$B去干掉他，再把他的爪子带回来给我！', '把费索的爪子带给剃刀岭的奥戈尼尔·魂痕。', '啊哈!你打败他了!$B$B你的氏族会以你为傲，$N。多亏有你，杜隆塔尔境内的邪恶力量又少了一支。', '$N，你找到费索了吗?我们必须把费索和其它燃刃氏族的馀孽从我们的领土上清除掉!', '', '去找杜隆塔尔的奥戈尼尔·魂痕。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (808, '明希纳的徽记', '我在梦中听到了我兄弟明希纳的呼唤。$B$B回音群岛上的术士扎拉赞恩抓走了他，折磨着他，最后残忍地害死了他。$B$B但即使是死亡也没能让我的兄弟得到安宁，因为扎拉赞恩用邪恶的魔法把明希纳的灵魂困在了他的徽记中。我在梦中看见…我兄弟的徽记和其它人的徽记一起被堆在回音群岛中最大的那座岛上的法阵中。只要他的徽记还在那儿，他的灵魂就无法得到自由。$B$B请你帮助他吧，$N。找到那个邪恶的法阵，把明希纳的徽记带回来给我，让他的灵魂获得自由吧！', '到回音群岛上去，将岛上法阵中的明希纳的徽记带回来，交给森金村的加德林大师。', '谢谢你，$N。你拯救了明希纳，你解放了他的灵魂!', '你找到我兄弟的颅骨了吗，$N?他的灵魂自由了吗?', '', '去杜隆塔尔找森金村的加德林大师。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (812, '救命如救火', '$N……你来得真是时候，快救救我……$B$B我在毒尾蝎战斗的时候一不小心被蛰伤了，毒液正在不断侵蚀我的血液。看样子…我最多再撑一个小时就得玩完了，我想请你帮个忙…$B$B奥格瑞玛的考格汉知道怎么做解毒剂，快去找他…$N，我…我支持不了多久了……', '找到毒尾蝎的解毒剂，把它交给杜隆塔尔西北边境的林纳格。', '$N，谢谢你救了我一命。$B$B请收下这个，即使它一文不值，我也希望它能对你有所帮助。看样子我近期应该是用不上它了。在我重新证明自己之前，考格汉只会让我去做些例行的公事，比如杀杀野猪、找找蝎尾什么的……<叹息>', '我现在这个模样……不能回森金村去也许对我是好事……别人铁定会拿我这又蠢又弱的样子寻开心。', '', '去贫瘠之地找怒水河的林纳格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (813, '寻找解毒剂', '林纳格不随身带着解毒剂就去抓毒尾蝎是很不明智的行为，不过现在说这些也于事无补。$B$B赶快到奥格瑞玛城的城门外，在那一带的毒尾蝎身上给我找4个毒囊回来，这样我才能给他做解毒剂。$B$B动作快点，$N。我们自己的同胞命在旦夕！', '收集4个毒尾蝎的毒囊，把它们交给奥格瑞玛的考格汉。', '这是解毒剂，$N。赶快给林纳格送去，路上要小心点。', '记住，无论你要狩猎的是什么生物，研究他们的习性都是必需，有时候，了解这些就有可能救自己一命。', '', '去找奥格瑞玛的考格汉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (815, '恐龙蛋大餐', '啊呀！我差点忘了还得做早饭！$B$B$N，快去给我找点鞭尾龙的蛋来，至少得要三个蛋才够明天做饭用。$B$B血爪鞭尾龙非常凶猛，而且会拼命地保护自己的蛋。有时它们会把蛋深深地埋在地下让你找不到，不过在森金村东南方的回音群岛上，这些鞭尾龙的蛋满地都是。', '收集3个鞭尾龙的蛋，并把它们带给剃刀岭的厨师托尔卡。', '你也许不是很强壮，不过还好不蠢，$N。$B$B拿着这个赶快闪开，我还得做饭呢。', '早饭、中饭、晚饭!谁管到底是哪顿饭?反正最后都得有人来做吧?那还不就是我吗?!', '', '去找杜隆塔尔的厨师托尔卡。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (816, '丢失的孩子', '$N，请帮帮我吧！我的儿子克鲁恩几天前到西边的怒水河畔捕猎鳄鱼，却一直没有回来，我现在觉得不妙了。$B$B尽管他十分强壮，但他的固执和自尊常常让自己陷入麻烦。我警告过他，鳄鱼是强大而凶猛的动物，可他一听就火了，掉头就走。$B$B如果你找不到他，至少也请给我带来一些关于他的消息，不管是好的还是坏的……就算把怒水河畔每只鳄鱼的肚子剖开也要找到点什么。', '把关于克鲁恩的消息告诉剃刀岭西北部农场中的米莎·托克伦。', '我的儿子……我亲生的孩子啊!$B$B当我还不知道他究竟遭遇了什么的时候，我还一直在折磨着自己。现在我已经知道发生了什么，我可以开始为他哀悼了。$B$B谢谢你，$N。请你收下这个。我原来打算等克鲁恩平安归来的时候就交给他的，但是我的儿子不在了，我也不忍再看它一眼。', '我日夜不停地企盼着克鲁恩回到我的身边，不过我几乎已经知道他遭遇了怎样的不幸……', '', '去杜隆塔尔找托克雷农场的米莎·托克伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (817, '生活所需的虎皮', '我们的兽皮大多取自生活在杜隆塔尔地区的老虎身上，$N。我们捕猎这些野兽的原因很多，比如毯子、护甲，还有帐篷什么的；同样，还有许多原因让我们允许它们继续繁衍生息。$B$B但是现在，我们有必要再杀掉一些老虎了。我们的人数在增加，而库存的兽皮也已经开始供不应求了，因此我需要更多兽皮来为他们制作各种生活用品。$B$B给我找四张杜隆塔尔猛虎的毛皮来，我会给你一些奖赏的。', '收集四张杜隆塔尔虎皮，并把它们交给森金村的维尔林·长牙。', '我很高兴，$N。你找到的虎皮可以为我们的同胞制成护甲，也可以让他们在寒冷的时候御寒。$B$B谢谢你。', '我还记得我第一次去捕猎老虎时的情形，$N。我来到了回音群岛中最大的一个岛，在树丛中的阴暗处静静地等了一天，等待着……观察着……$B$B我的肌肉绷得紧紧的，随时都准备出击。当那只老虎终于咬上诱饵的时候，那是我最棒的胜利之一。', '', '去杜隆塔尔找森金村的维尔林·长牙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (818, '沃纳尔大师', '虽然我的视力不断衰退，但我还是可以看得足够清楚。我曾经可以很轻易地施放强力的魔法，而现在我更多时候必须依靠炼金术的帮助才行。不过我不收学徒，因为我从来没有看到过任何够格的巨魔或兽人。$B$B你是合适的人选吗？当然，你当然是……你当然以为自己合适。$B$B我需要一点东西，你能帮我拿来吗？$B$B我要一些龙虾人的眼睛和几瓶蟹胶，你可以在杜隆塔尔的海蟹或龙虾人身上找到这些东西，找齐了之后再来见我。', '把4个龙虾人的眼睛和8小瓶蟹胶带到森金村，交给沃纳尔大师。', '干得好……年轻人，干得非常好!', '时间是对个人力量和意志的最佳检验。如果丧失耐心或向软弱屈服，你就无疑是个失败者。', '', '去杜隆塔尔找森金村的沃纳尔大师。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (819, '老陈的空酒桶', '张贴在酒桶一角的纸条上写着：“老陈 - $B$B祝汝精神得提升，祝汝精神永提升。”', '找到对老陈的空酒桶有所了解的人。', '嗯，没错……$B$B这是老陈留下的空酒桶，他和雷克萨离开很久了。我有很久很久都没有见过他，也没有听到关于他的任何消息了。感谢你把这个带来给我，$N。', '嗯?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (821, '老陈的空酒桶', '你想尝尝老陈的雷霆佳酿吗？哈哈，这东西可是很带劲的哦。老陈把酿酒术教给了我师傅，我师傅又传给了我。去帮我找一些酿酒的材料，然后你就会得到物有所值的回报！$B$B帮我带5颗草原狮的獠牙、5个平原陆行鸟的肾脏和1根雷霆蜥蜴的角回来，然后我就可以酿酒了。$B$B这些东西都可以在贫瘠之地找到。', '收集5颗草原狮的獠牙、5个平原陆行鸟的肾脏和1根雷霆蜥蜴的角，把它们交给棘齿城的酿酒师德罗恩。', '哈哈……我想这些原料足够了。$B$B你让我想起了以前的好时光，$N……记得那一次，我喝了太多的洞穴麦芽酒之后酩酊大醉，这段回忆总是让我感觉很温暖。', '找到我要的东西了吗?', '', '去找贫瘠之地的酿酒师德罗恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (822, '老陈的空酒桶', '雷霆佳酿的味道不错吧？$B$B我从老陈那里还学到了另一种酿酒术，你有兴趣吗？酿造这种酒不需要花太多的时间，如果你愿意冒险弄到些原料就成了。$B$B帮我弄五个雷鳞蜥蜴的闪电腺、一个巨型雷鹰的唾液腺和一个居住在贫瘠之地上的科多兽的肝脏来。$B$B我说过，这种酒很正点，就是我和你提到过的洞穴麦酒。', '收集5个闪电腺、1个雷鹰的唾液腺和1个科多兽的肝脏，把它们交给棘齿城里的酿酒师德罗恩。', '哈哈!我就知道你无法抵挡这种酒的诱惑。$N，欢迎你随时过来品尝我的美酒，不过要记得帮我多带一些原料哦。', '你找到那些原料了吗，$N?', '', '去贫瘠之地找棘齿城的酿酒师德罗恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (824, '大地之环的耶努萨克雷', '大地之环是个萨满祭司的团体，他们致力于研究和保护自然界中的元素。他们忘掉的关于上古之神的知识可能比大多数学者知道的还要多。$B$B你很幸运，我认识灰谷的大地之环的成员。到佐拉姆海岸边上的佐拉姆加前哨站去，向耶努萨克雷展示你找到的这个东西。如果有谁对这颗水球的重要性有所了解的话，那么非他莫属了。', '将被污染的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。', '这个水球……其中的能量混乱无比。许多强大的元素生物从这样的东西里面吸取能量。找到如此完美无缺的东西是很困难的，要找到一个受污染的就更难了!$B$B我会让大地之环好好研究一下这东西的。也许我们可以终结元素生物的堕落。请你收下这个作为大地之环的报酬。', '啊，你好。我花了大量时间来研究水，以及所有的元素―有时候我甚至对周围的事物浑然不觉。$B$B我能帮你什么忙吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (825, '海底沉船', '我得到消息说普罗德摩尔舰队的残骸仍在杜隆塔尔的近海，就在提拉加德城堡的东边。$b$b与人类结盟的侏儒是一群粗俗的小东西，但是他们掌握着先进的机械技术。我们必须对任何潜在的敌人都了如指掌，同时我们的族人也可以从这些新知识中受益。$b$b$n，潜到那些沉船中，给我拿来联盟使用的工具。', '剃刀岭的加索克要你从海岸边的舰队残骸中打捞出3件侏儒的工具。', '你取回工具的任务完成得十分出色，$C。我会让下一支商队将这些工具送到奥格瑞玛去。$B$B干得好!', '只要我们能搞懂人类是如何使用那些奇特的机器的，我们将来就更有希望在战场上击败他们。$B$B这些新的知识会让部落变得更加强大。', '', '去找杜隆塔尔的加索克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (826, '扎拉赞恩', '巫医扎拉赞恩就住在东边的回音群岛上，那些岛屿曾经是我们的家园。$B$B扎拉赞恩从那里不断派出他的爪牙来到这边的大陆上，用妖术控制我们的同胞，将他们也变成扎拉赞恩的傀儡。$B$B我们必须阻止他。$B$B打败扎拉赞恩和他的爪牙——那些曾经是我们的朋友和亲人的暗矛巨魔。把扎拉赞恩的徽记给我带回来，作为你已经斩杀了这个恶魔的证明。', '打败扎拉赞恩。$B$B杀死8个巫毒巨魔和8个妖术巨魔。$B$B把扎拉赞恩的徽记带给加德林大师。', '谢谢你，$N。札拉赞恩完蛋了，我们部族从此可以安心地生活了。', '你打败札拉赞恩了吗，$N?', '', '去杜隆塔尔找森金村的加德林大师。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (827, '骷髅石', '$N。火刃氏族就躲在奥格瑞玛东部的骷髅石山洞里。他们在洞中进行邪恶的仪式，用灼热项圈去燃烧自己的身体。$B$B我相信他们戴上这些项圈之后便会获得恶魔的力量，不过如果要确定这一点，我还得收集一些项圈来做研究。$B$B到骷髅石去，从那些火刃祭司身上找些灼热项圈给我，让我来揭开他们的秘密。', '在骷髅石中的火刃祭司身上收集灼热项圈，$B$B然后交给玛高兹。', '很好。这些项圈中隐藏着燃刃氏族背后的秘密，而我即将揭开这个秘密……', '你进入骷髅石洞了吗，$N?你拿到灼热项圈了吗?', '', '去找杜隆塔尔的玛高兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (829, '尼尔鲁·火刃', '你带回来的灼热项圈是充满恶魔力量的强大器物工具。它们的来源恐怕已经不是我这样的萨满祭司所能探究的了。我们必须找个专精于此的术士来研究它们。$B$B把这个项圈带给尼尔鲁·火刃。他是个技艺高超的术士，但他却擅长使用自己所掌握的恶魔力量来对抗恶魔，还声称他对恶魔的研究都是有益于部落的。不管这些话是真是假，如果我们要对付那些信仰恶魔的家伙，就需要他的帮助。$B$B你可以在奥格瑞玛的暗影裂口找到尼尔鲁。', '给奥格瑞玛的尼尔鲁·火刃带去一个项圈样本。', '啊，你从哪儿找来这东西的?剃刀岭的玛高兹让你来找我的吗?$B$B好吧，让我仔细瞧瞧……', '向您致以我最谦卑的致意，$C。我能帮您什么忙吗，我的$r$g兄弟:姐妹;?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (830, '将军的命令', '你打开了陈旧褪色的信封，发现了一份看上去很正式的文件，上面盖着普罗德摩尔将军的徽记。$b$b这封信看上去很重要，剃刀岭的指挥官加索克应该会对它感兴趣。', '把普罗德摩尔将军的命令带给剃刀岭的加索克。', '这不是什么好兆头。你把这个消息告诉我是个很明智的选择。', '你好像在担心什么事请，$C。你发现什么异常状况了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (831, '将军的命令', '人类是不可信的。我们和他们并肩作战、疲惫不堪，但我们很明白，总有一天这帮家伙会背叛我们。$b$b普罗德摩尔将军死了，但这并没有终止他的计划，这个混蛋在他玩完之前就把一切都安排好了。$b$b本尼迪克上尉不会是最后一个威胁，天知道什么时候普罗德摩尔的人会又一次从我们的海岸上登陆。我们要尽快让奥格瑞玛的沃金得知这些信息！快去吧，你应该能在萨尔的大厅里找到他。', '把普罗德摩尔将军的命令交给奥格瑞玛城中的沃金，他就在萨尔的大厅里。', '我多次提醒大酋长不要相信人类，但个人的骄傲现在似乎不太重要。$B$B年轻的$C，你对部落的效忠是令人尊敬的。$B$B不过请你原谅我，我必须立刻就这个问题向萨尔提出忠告……', '你没看到我正忙着吗?没什么要紧的事情就别来打扰我……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (832, '燃影之眼', '<你感受到饰物中传来一个神秘的声音>$B$B加祖兹？$B$B加祖兹？……快回答！$B$B我们已经听说你在骷髅石发现了那个东西，你必须立刻发动攻击！$B$B加祖兹，我命令你赶快回答！否则我就把你的位置告诉尼尔鲁·火刃，他会用最残忍的手段来对付你！$B$B别拿你的小命开玩笑！…$B$B加祖兹，你在那里吗……？', '把这颗燃影之眼带给奥格瑞玛的尼尔鲁·火刃。', '<他仔细地检查着燃影之眼。>$B$B有意思。你听到的那个声音提到我的名字?我为大酋长和部落猎杀敌人的事情是众所周知的，不过奇怪的是……他为什么会特别提到我。此外持有这个饰物的燃刃祭司的名字怎么和我的名字如此相像?$B$B我得研究一下这个饰物，看看它到底隐藏着什么秘密。$B$B谢谢你把这个东西交给我，$N。你为我们的同胞作出了巨大的贡献。', '你有很重要的事情要向我报告，我可以从你的眼中看得出来。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (833, '神圣的墓地', '赤色石是我们牛头人最神圣的墓地，只有最勇敢的牛头人才能得到在这里安息的殊荣。这是给予那些帮助保卫雷霆崖和为部族的利益而付出生命的伟大战士的无上荣誉。$b$b不过这段时间以来，有种邪恶的威胁正在接近我们的神圣领土。有一群刺背干涉者正在破坏我们的墓地，我的年纪太大了，无力把他们赶走。$b$b你一定要把他们驱逐出去，$n。', '博学者诺拉·暴雨图腾要你在赤色石杀掉8个刺背干涉者。', '干得好，你已经给了那些愚蠢的刺背野猪人一个深刻的教训。要是他们再敢到我们的圣地来捣乱，就让他们有来无回。', '你必须把那些刺背干涉者驱逐出我们的神圣墓地，$N。', '', '去莫高雷找赤色石的博学者诺拉·暴雨图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (834, '沙漠之风', '我叫雷兹拉克，是加兹鲁维的手下。他派我来这里跟杜隆塔尔的兽人作生意……除了那些商队以外，一切都进行得很顺利，商队的安全根本没法保证！你知道吗，这给我添了不少麻烦！$b$b上次发出的一批货物——还说肯定能平安送达呢——结果被一票鹰身人从半道上给劫了去……它们好像是从那什么烈风峡谷来的……$b$b反正，拿不到那批货我就死定了！帮帮忙吧……沿着大峡谷向南走，你就会看到直接切入山壁东西两面的沟壑。', '为奥格瑞玛城外的雷兹拉克取回5个装满货物的袋子。', '嘿，干得好!你不是把物资给我们拿回来了嘛!太好了!等我找人把这些东西拖走，就可以回去干活了。', '我当然能出色地完成我的工作，但是问题不在于我，这整件事情太可笑了!你想让我怎么办?坐在这里玩办家家吗?', '', '去找杜隆塔尔的雷兹拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (835, '保卫商路', '加兹鲁维跟我说过：“雷兹拉克呀，有一件事情你必须铭记，那就是如果你想把事情做好，就得亲力而为。”$b$b我不能让那些商队全都有来无回，所以我得自己解决这\r\n件事才行。枯水谷在烈风峡谷的东边，那里的鹰身人多到数不胜数，只要把它们全都给做了，那条路就彻底安全了。$b$b当然，加兹鲁维还教过我另一点，那就是“有钱能使磨推鬼”。那么，你愿意帮我的忙吗，$n？', '为奥格瑞玛附近的雷兹拉克杀掉12个尘风暴徒和8个尘风雷巫。', '我想我终于可以歇口气了，鹰身人再也没法袭击我们的商队了，至少短时间内如此。听说下一批货物中还有些有趣的玩意!$B$B你干得很好，$N，你可以去棘齿城找我的老板 加兹鲁维。我敢说他会给你找点事做的。$B$B哦，别担心，我不会忘了付你报酬的。', '你不会想到我的头儿加兹鲁维这样的人也会说这样的话，不过他总是高瞻远瞩。他说:“不要害怕采取行动。”$B$B如果我们不有所动作的话，鹰身人还会继续给我们制造麻烦，而商队还会不断受到袭击，对吧?', '', '去找杜隆塔尔的雷兹拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (837, '野猪人的进犯', '我们刚来这里的时候，钢鬃野猪人还占据了大片的土地，让我们头疼不已。经过不懈的努力，我们已经将大部分野猪人都驱逐了出去，不过在某些地方还残留着不少野猪人。$b$b这样的情形已经持续太久了。我们要保护自己，决不能让钢鬃野猪人占据我们的领土。野猪人的营地就在西边，去找到这些恼人的东西并除掉它们吧。今天，我们把钢鬃野猪人赶出杜隆塔尔，明天，我们就能把他们驱逐出整个卡利姆多。', '为剃刀岭的加索克杀掉4个钢鬃野猪人，4个钢鬃斥候，4个钢鬃传令兵和4个钢鬃卫兵。', '我会让大家都知道野猪人已经被赶出他们的老巢，他们的结构会出现大乱。从杜隆塔尔赶走了钢鬃野猪人之后，我们的边境就更加安全了。', '他们的确是有点头脑、有点组织，不过让我惊讶的是他们竟然能在卡利姆多占领这么多的领土。也许他们比我想象中的更狡猾……', '', '去找杜隆塔尔的加索克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (840, '部落的新兵', '嗯，你看上去很强壮。$B$B是这样的，我的好朋友卡加尔正在为贫瘠之地招募新兵。我知道你想为部落做点有用的事，这次你的机会来了。$B$B把这封募兵信交给卡加尔，看看他会不会签字。', '沿着剃刀岭西部的小路一直前进，过桥之后就可以进入贫瘠之地。$B$B在桥对面的兽人前哨找到卡加尔·战痕，将你的募兵信交给他。', '哦，是塔克林让你来的?他是个出色的斥候，没他我还真不知道该怎么办呢。$B$B我会在你的募兵信上签字，不过真正需要人手的地方是十字路口，不是我这里。', '你想干什么，小子?如果不是来应征入伍的话，我可没时间和你应酬。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (841, '另一个能量源？', '让我猜猜——你没有及时完成你所谓的什么惊天动地的任务。不，等等……是不是你把它掉在了流沙里找不回来了？！好吧，不管是什么理由，我这里还有个能量源可以卖给你。这次，我要你用十个废土水袋来换！$B$B这年头大家都不好混，$n，能量源当然不会是长在树上随手可得的！呃，也许它们真的可以长在树上……我们绝对应该试试看能不能制造这样一棵能量源树……', '用10个废土水袋来和加基森的总工程师比格维兹换取另外一个能量源。', '很好，这是你要的能量源。我强烈建议你这次要珍惜它那有限的使用时间，当然，除非你愿意花时间再去找十个水袋来给我。', '怎么样，你弄到十个水袋了吗?', '', '去塔纳利斯找加基森的首席工程师沙克斯·比格维兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (842, '十字路口征兵', '把我签过字的募兵信拿到十字路口去。$B$B那里由瑟格拉·黑棘掌管，她是个恶心的萨满祭司，总喜欢在吩咐你去做正事之前跟你胡说一通，把你搞得头晕脑胀。萨尔觉得她是个人才，但我可不这么看。$B$B小子，接下来的事情还是你自己去解决吧……', '从卡加尔的前沿哨所往西走。$B$B在丁字路口往左拐，然后朝南走。$B$B在十字路口的道路交汇处找到瑟格拉·黑棘。', '好吧，$N。你想证明你对部落的价值?这里有一大堆事情可以让你做，仔细听好然后按照我说的去做。$B$B$g我知道你在想什么，别以为我会容忍你的傲慢。就连萨尔大人都说过，部落的女性和你们男性的地位是平等的。你若是再敢对我有一丁点的不敬，我就让你吃不完兜着走。:很高兴见到你，如果萨尔知道有越来越多像你我一样出色的女性正在为建设贫瘠之地出力，他一定会很高兴的。;$B$B', '哎呀，看看谁来了?卡加尔又帮我召募了个新兵吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (843, '加恩的报复', '我一直在这里孤独地徘徊着。$b$b巴尔莫丹的矮人对我们的领土从来都没有半点尊重。烈性的炸药在地面上炸出了一个又一个深深的钻孔，嘈杂的机器切开了山丘和平原，曾经属于我们部族的美好家园现在成了那些破坏成性的矮人们的领地。$b$b我们曾希望通过外交途径与他们和解，但是一切努力最终都以失败告终。现在是做出决断的时候了。$b$b用武力将这些矮人从巴尔莫丹的挖掘场赶走，把他们的头儿勘察员卡兹戈姆的日记带来交给我。', '加恩·石塔让你杀死15个巴尔丹挖掘者和5个巴尔丹工头。$b$b把卡兹戈姆的日记交给加恩·石塔。', '卡兹戈姆罪有应得，我对这个白痴的下场不会有丝毫的同情。他根本不属于这片土地。$B$B希望他的死能警告所有那些对我们的生活构成威胁的人。$B$B现在，让我来研究一下这个矮人的日记……', '巴尔莫丹矮人的到来让很多无辜的牛头人失去了生命，或者被迫离开了他们世代生活的家园。我们必须夺回自己的领地!', '', '去贫瘠之地找南黄金之路的加恩·石塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (844, '平原陆行鸟的威胁', '你的第一个任务是非常简单的。$B$B东边的平原陆行鸟总是对我们的食物补给心怀鬼胎，它们已经成了十字路口的一大祸害。$B$B杀掉那些平原陆行鸟，把它们的鸟喙给我带回来。', '收集7个陆行鸟的喙，把它们交给十字路口的瑟格拉·黑棘。', '干得很好，$N。没了这些可恶的陆行鸟，我们的食物补给线的压力就可以减轻不少了。希望你从这次猎杀行动中学到了足够的技巧，因为你的下一个目标可远比陆行鸟强大多了……', '你收集到陆行鸟的喙了吗?你让它们血染贫瘠之地了吗?', '', '去贫瘠之地找十字路口的瑟格拉·黑棘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (845, '斑马的威胁', '斑马虽然并非贫瘠之地上最凶猛的野兽，但也比平原陆行鸟强悍了许多。不要担心，我们总有一天会派你去挑战比斑马更强大的敌人，但现在你最好用它们练练手。$B$B去猎杀北边和南边的斑马，并且收集它们的蹄子。完成这个任务之后，也许你就可以去见识见识真正的猛兽了。', '杀死快步斑马并收集4只斑马蹄，把它们交给十字路口的瑟格拉·黑棘。', '干得不错，$N。斑马的蹄子是非常危险的武器，只需一下就可以把一个健壮的牛头人给踢成重伤!$B$B你的能力似乎也很强，准备好接受真正的挑战了吗?', '你杀掉多少角斑马了?', '', '去贫瘠之地找十字路口的瑟格拉·黑棘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (846, '加恩的报复', '很显然，矮人们依靠炸药和那些吵闹的机械来进行挖掘，而且不久后他们肯定会再派一个新的工头来接手这里。$b$b我要让这些矮人自食其果。按照这日记上面写着的配方，只要把硝化甘油、木浆和硝酸钠混合起来，就能制造出一种强力的炸药。据我们所知，城堡中的火枪手、战士和军官都拥有这些物资。$b$b为我收集这些物资，我要制造出一种让矮人们永远都不会忘记的炸药！', '加恩·石塔要你将6瓶硝化甘油、6份木浆和6份硝酸钠交给他。', '你做得很好，$C。$B$B毫无疑问地，我们很快就能给那些矮人一个恰当的惊喜了。', '你回来了，$N。$B$B卡兹戈姆的死也许会暂缓他们对这片土地的挖掘进程，但依然无法完全制止他们。$B$B为了保护挖掘场的安全，矮人军队也在不断进驻巴尔莫丹城堡，这已经对我们构成了严重的威胁。$B$B如果你找到了我需要的原料，我就能制造出威力强大的炸药来，让那些草率的矮人重新考虑一下他们在贫瘠之地的行动。', '', '去贫瘠之地找南黄金之路的加恩·石塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (848, '菌类孢子', '贫瘠之地的绿洲里隐藏着一个谜。生命的能量从绿洲之水中涌出，给那些汲取水分的动植物带来了勃勃生机。$B$B与此同时，这种能量也在慢慢地改变这些动植物。$B$B在绿洲附近生长着一种蘑菇，我们这些洛丹伦的药剂师都认为这种蘑菇的孢子中包含有一些特殊的物质，它对我们非常有用。$B$B帮我带一些孢子回来，我们会非常感谢你的。', '收集4个菌类孢子，把它们交给十字路口的药剂师赫布瑞姆。', '啊，你找到的东西很不错。$B$B我们被遗忘者历来都是信守合约的。这是你的报酬，$N。', '$N，你找到这些孢子了吗?我必须制造一种药剂送给雷霆崖的同事，而这种药剂正需要这种孢子来配制……', '', '去找贫瘠之地的药剂师赫布瑞姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (849, '加恩的报复', '按照卡兹戈姆的日记上所述的方法制造出来的炸药应该不会有问题。$b$b那么，我们开始吧。$b$b首先我有一项特殊的任务要交给你完成。拿上这只爆破筒，去炸掉巴尔莫丹的飞行器。$b$b这个飞行器不仅是巴尔莫丹军事设施的关键部分，也是一架可怕的杀戮机器。更重要的是，它是权力的象征，而它对我们的部族来说则代表着一段耻辱的回忆。$b$b我会为你的成功感到自豪，你也将得到丰厚的奖励。', '摧毁巴尔莫丹的飞行器，然后向加恩·石塔回复。', '$N，你干得很好!雷霆崖的人们会视你为牛头人圣地的防卫者和部族的勇士。', '矮人的飞行器被摧毁之后，我感到了一种极其甜美的复仇的快感。', '', '去贫瘠之地找南黄金之路的加恩·石塔。', '贝尔莫丹飞行器已经被摧毁', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (850, '科卡尔首领', '半人马的问题困扰着牛头人已经很多年了，最近，贫瘠之地的科卡尔半人马开始形成真正的威胁。通常他们散居在这片土地上，不过他们当中已经产生了新的首领，他把一盘散沙的半人马集合在一起。$B$B为了保护我们的家园，这些半人马领袖就必须要除掉。$B$B帮我带回巴拉克·科多班恩的徽记，他在北方的遗忘之池附近驻营。$B$B除掉他，然后再回到我这里。', '把巴拉克的徽记交给十字路口的雷戈萨·死门。', '做得好，$N。虽然半人马是群粗俗而且野蛮的家伙，却也不乏充满智慧和远见的领袖。他们才是最危险的。$B$B巴拉克就是这样一个半人马，还好他已经被干掉了。', '你好，$N。你带巴拉克的头颅回来了吗?', '', '去找贫瘠之地的雷戈萨·死门。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (851, '狂热的维罗戈', '有一个被称作狂热的维罗戈的半人马在贫瘠之地四处游荡，通常很难找到他，不过他的营地就在东南方的死水绿洲附近，你应该可以在那里把他给引诱出来。$B$B到死水绿洲附近的半人马营地去，斩杀那里的半人马。虽然这会让你处于很危险的境地，不过如果你能杀死足够多的半人马，他们就会发出警报，之后维罗戈就会现身。$B$B把他的徽记带给我，我要把它和巴拉克·科多班恩的徽记放在一起。', '把维罗戈的徽记交给十字路口的雷戈萨·死门。', '很好。你一定激怒了那些半人马―我们的守卫注意到死水绿洲附近的动静，那应该就是你干的了。$B$B你应该为你所做的一切而感到自豪，$N。你是个非常勇敢的$r。', '$N，你找到维罗戈了吗?', '', '去找贫瘠之地的雷戈萨·死门。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (852, '赫兹鲁尔·血印', '赫兹鲁尔·血印是贫瘠之地的科卡尔半人马的首领。他凶猛、残忍，诡计多端。消灭他就可以瓦解半人马部落，从而极大地削弱他们对我们的威胁。$B$B去杀了他。就像对付巴拉克和维罗戈那样，带回赫兹鲁尔的徽记。$B$B他和他的手下驻扎就在西南方的甜水绿洲一带。', '把赫兹鲁尔的徽记交给十字路口的雷戈萨·死门。', '恭喜你，$N。这些半人马毫无组织性，不可能像兽人们一样团结起来，不过他们仍然凶猛无比。你已经通过击败他们而证明你的英勇。', '$N，你打败赫兹卢尔了吗?', '', '去找贫瘠之地的雷戈萨·死门。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (853, '药剂师扎玛', '我用你给我的孢子制成了药剂。现在我必须把它送给我的同事，药剂师扎玛。如果你愿意帮忙把这个带给她，她会拿一些我们存储下来的炼金术用品奖励你的。$B$B她就在预见之池里，那是一个位于雷霆崖下面的洞穴。通向洞穴的小路非常隐蔽，不过你可以在灵魂高地下面找到这条小路。$B$B快点出发吧，这种药剂的效力只能持续很短的一段时间，在这段时间里必须要送到扎玛那里。', '在药剂的效力消失之前，把提炼过的孢子交给雷霆崖的药剂师扎玛。', '啊，是赫布瑞姆从贫瘠之地收集的孢子。他让你送过来的?很好。$B$B药剂仍然有效，看来你在路上没有耽搁时间。干得不错，$C。', '你从药剂师赫布瑞姆那里给我带来了一些东西?快让我看看。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (855, '半人马护腕', '在与科卡尔半人马的战斗中，你已经证明了自己。不过，他们仍然是个威胁。这些半人马的首领的死对我们来说是非常好的消息，不过你必须继续削减他们军队的人数。$B$B为此我会交给你一项赏金任务。$B$B到科卡尔半人马的领地去，干掉他们的士兵，收集他们的半人马护腕。当你能带回足够多的护腕的时候，部落会奖赏你的。', '收集15个半人马护腕，把他们交给十字路口的雷戈萨·死门。', '干得漂亮。我想你已经让那些苟活的半人马感受到了恐惧，$N。如果他们还有些理智的话，现在就应该冷静下来，停止他们的行动。$B$B但我恐怕他们不会那么做，真糟糕。$B$B这个糟糕……是对他们而言的。', '$N，你的任务完成了吗?', '', '去找贫瘠之地的雷戈萨·死门。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (857, '众月之泪', '那是我的宝贝！我的！我要把它夺回来！夺回来！$b$b那些肮脏的挖掘者发现了它……它是如此美丽，众月之泪是我们在巴尔莫丹的第一个重大发现。$b$b它本就该是我的！对，我的！我的宝贝！$b$b塔文布莱德将军嫉妒众月之泪带给我的力量，居然就把它锁在了城堡里。他说那是一个诅咒！这个蠢货！$b$b其它人想要夺走它，他们是不会得逞的！那个叫塔文布莱德的杂种把我赶了出来。$b$b我要夺回来！夺回我的宝贝！', '被流放的费格雷要你取回他的众月之泪。', '我的宝贝终于还是回来了!它是我的!我的!', '众月之泪在哪儿?我需要它!很需要!', '', '去贫瘠之地找巴尔莫丹的被流放的费格雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (858, '打火钥匙', '你该不会是斯布特瓦夫派来的吧？我被困在这儿了。我在不知道需要钥匙才能启动伐木机的情况下就贸然跳了进来。更蠢的是，当另一台伐木机的操作员问我是否一切正常的时候，我居然慌了神！我没有告诉他我手里没钥匙，而只是说机器有些问题。$b$b我们要赶紧离开这里！到起重机上的控制室去，那里的管理员应该有这台伐木机的钥匙。$b$b帮我离开这儿！', '取得打火钥匙，把它交给维兹克兰克。', '啊，好像就是这把钥匙!让我想想该怎么用……$B$B嗯……旋转控制……这是调节速度和稳定性的……手感不错。看看这个!我真不敢相信风险投资公司能造出比我们还先进的设备来。我要把这个带回棘齿城!', '快点，我们得在他们生疑之前逃出这里!', '', '去贫瘠之地找淤泥沼泽的维兹克兰克的伐木机。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (861, '猎人之道', '我看得出来，你是个渴望探索的$c。我也渴望到处漫游，至少曾经是这样……$B$B漫游，狩猎。狩猎是牛头人最高的荣誉。$B$B如果你真想走猎人这条路的话，梅洛·石蹄可以给你一些指引，他就在雷霆崖的猎人高地上。$B$B要向他证明你的能力和决心，你就必须把莫高雷一带的平原徘徊者的爪子带给他看。平原徘徊者非常凶猛、狡猾——对于一个想要成为猎手的年轻$c来说再合适不过了。', '收集4只平原徘徊者的爪子，把它们带给雷霆崖的梅洛·石蹄。', '斯考恩.白云是个睿智的牛头人。他做了多年的猎人，虽然他的身体已经老了，可是他还是保持着旺盛的战斗精神。我们为他感到骄傲。$B$B既然斯考恩让你来找我，那你一定也具有猎人的精神。你还收集了这些爪子，来证明你快速增进的技能。$B$B也许你已经准备好要走这条路了。', '你好，找我有事吗?', '', '去雷霆崖找猎人高地的梅洛·石蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (862, '掘地鼠炖肉', '像你样一个$c在贫瘠之地肯定会饿得前心贴后背，你看我，我就已经饿了整整一天了。$b$b我跟你说吧，我可以为你做一道大餐，不过得要先弄一些掘地鼠来。$b$b那些可恶的巴尔莫丹矮人几乎把这里的掘地鼠都给吃光了！你到\r\n南边的巴尔莫丹去给我带一些掘地鼠回来吧。$b$b如果你连这都搞不定的话，就不要再自称是经验丰富的冒险家了！', '给十字路口的格拉布弄到8只掘地鼠。', '一般来说我不喜欢吃这些啮齿动物，我是说在它们还这么……这么新鲜的时候。要让它们先腐烂几周之后再吃，才能真正地享受到那独到的美味，不过你看起来好像是等不及了。$B$B我给你做些掘地鼠炖肉吧，现在就开始。$B$B做好了!尝尝吧!', '$N，找到足够多的掘地鼠了吗?', '', '去找贫瘠之地的格拉布。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (863, '逃跑', '我想我要好好学学才行……应该不会很难。就这些按钮，一个操纵杆和两个……对了，你准备好要出发了吗？', '保护维兹克兰克以及他偷来的地精伐木机返回棘齿城的斯布特瓦夫那里。', '希望我们能从这被毁坏的伐木机雏形中找到一些有价值的东西……我的时间很有限!我要赶紧派一支抢修队到维兹克兰克那里去。$B$B哦，让我也为你提供些必要的帮助。', '我能帮你吗?', '护送维兹克兰克离开风险投资公司钻井工地', '去贫瘠之地找棘齿城的斯布特瓦夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (864, '向药剂师金格回报', '“搞定了，现在能量源已经被安全卸载，而你的数据也被完全保留下来了。好了，接下来就只有祝你一路顺风了，希望你的科学实验一切顺利。”$B$B那个地精转身开始继续做加基森水业公司的事情。你小心翼翼地把封好的实验工具包收起来，然后准备把它带回幽暗城。药剂师金格正在那里等着你向他进行回报。', '把实验工具包带给幽暗城的药剂师金格。', '我会马上着手分析这些资料，也许基佛的神经错乱反而能够证明我的天才。$B$B你对我来说……还是很有用的，我会奖励像你这样有用的$C。收下这个东西，还有这些钱，还有我们对你的感谢。$B$B经常回来看看―我相信我们在这个项目上的合作还没有完结。', '欢迎回来。至少，如果你带回了我要的实验资料的话，我欢迎你回来。否则，我可不会浪费宝贵的时间来和你废话，你要做的就是尽快去完成我交给你的任务。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (865, '迅猛龙角', '贫瘠之地的迅猛龙比其它地区的更加聪明狡猾，我想它们的智慧就来自它们的角！如果是这样的话，我可以将它们的角磨成粉末，制成“智慧饮料”，然后就能卖个大价钱！！！$B$B我想你应该能帮我的忙……从赤鳞镰爪龙身上弄一些完整的迅猛龙角来，它们就栖息在贫瘠之地的南部以及靠近灰谷森林边界的贫瘠之地北部。', '从赤鳞镰爪龙身上收集5根完整的迅猛龙角，把它们交给棘齿城的米希瑞克斯。', '好极了，就是它们!现在，我只需把它们磨成粉末，加一点点酒，然后……', '$N，你弄到赤鳞镰爪龙的角了吗?那些角会让我大赚一笔!', '', '去找贫瘠之地的麦伯克·米希瑞克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (866, '根须样本', '贫瘠之地的草药似乎和其它地方的不大一样。它们的属性几乎相同，不过这里的绿洲之水却令它们发生了一些改变，使它们变得有那么一点点特别了。$B$B我想找出这些草药到底有什么特别之处……然后看看它们有没有利用价值！$B$B如果你精通草药的话，就帮我在贫瘠之地收集一些这种草药的根须样本吧。把这些样本交给我，这样一来，我就能比较一下它们与其它地区的草药之间的差异了。', '把根须样本交给棘齿城的麦伯克·米希瑞克斯。', '没错没错，就是这个!我会用这些草药的根来培育一些草药样品，然后对它们进行研究。我希望从中能够发现一些新的属性，一些隐性的、但是很有价值的属性……$B$B别担心―只要成功了，我会第一个告诉你的，因为我需要一个能帮我收集更多草根的人!', '你好，$N。找到那些草药的根须样本了吗?', '', '去找贫瘠之地的麦伯克·米希瑞克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (867, '鹰身强盗', '这些该死的鹰身人长期以来不停地攻击和掠夺我们的补给商队。现在我们要给她们一点颜色看看了：我们要割断她们的喉咙，削减她们的数量。$B$B我一直在她们的巢穴附近细心观察，而且已经确定了谁是她们的领导者。我们应该首先以削弱她们的基础作战力量为目标，这样才能彻底击败她们。$B$B慢慢来，先去干掉那些在西北方出没的巫翼鹰身人和巫翼游荡者，然后给我带8只巫翼鹰身人的爪子回来吧。这应该是一个不错的开始……', '收集8只巫翼鹰身人的爪子。$B$B把它们交给十字路口的达索克·快刀。', '哦，不错……真的很不错。$N，干得好。我期望未来能看到你做出更多的大事来。', '杀了足够多的鹰身人了吗?如果没有的话就继续和她们战斗，我要你给我带回来8只巫翼鹰身人的爪子。', '', '去找贫瘠之地的达索克·快刀。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (868, '蝎卵', '嘿，$N，奥格瑞玛城里的主人派我到十字路口来观察这片土地并记录这里所发生的一切。$B$B我的目标之一是在巨人旷野南方出现的昆虫状生物。我们对这种生物知之甚少，所以我把它作为我的主要研究课题，希望能发现点什么。它们似乎有超出一般生物的智能。$B$B拿着这个掘地铲，从土丘里收集一些它们的卵。不过你要当心，这些生物一旦收到同伴的警报，就会立刻蜂拥而至。', '把12枚异种蝎卵和掘地爪交给十字路口的科兰。', '感谢你的帮助，$N。这正是我需要的卵。$B$B这是给你的奖赏……', '小心不要弄碎了你找到的卵，$N。如果它们破了的话就没用了。', '', '去贫瘠之地找十字路口的科兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (869, '偷钱的迅猛龙', '不久前，我们警戒塔中的一箱银币被偷走了。那是十字路口警卫的薪水，当然我们必须找回这箱银币。$B$B奇怪的是……被窃那天，我们逮住了那群小偷中的一个。它……它居然是一只迅猛龙！简直难以置信！$B$B我不知道迅猛龙要这些银币做什么，不过我也不关心这个——我只关心能不能取回我的银币。杀掉那些迅猛龙，这样它们就不会再偷我们的东西了！$B$B在贫瘠之地猎杀这些迅猛龙，把它们的头颅给我拿回来。', '收集12颗迅猛龙的头颅，把它们交给十字路口的加兹罗格。', '你干掉了那些迅猛龙!$B$B谢谢你，$N，你真是个优秀的$C。', '$N，你拿到那些迅猛龙的头了吗?', '', '去贫瘠之地找十字路口的加兹罗格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (870, '遗忘之池', '很久以前，贫瘠之地曾是个郁郁葱葱、生机盎然的地方。但是战争与灾难接二连三地降临在这片土地上，最后就剩下了这一片干燥荒芜的不毛之地。事实就是这样，真让我伤心。$B$B不过，在过去的几年里，贫瘠之地出现了新的绿洲，生机又在这片土地上重现。我们德鲁伊感觉到了在很深的地下有一股试图冲出地面的力量。$B$B我们必须找到这股力量的源泉，请到十字路口西北边的遗忘之池去一趟，在那里的湖水中搜寻力量的源泉，然后回到这里来。', '向图加·符文图腾报告你的发现。', '你找到一处地缝，气体从缝隙中喷涌而出?真奇怪。这也许是问题的答案，但我们现在还不能肯定。$B$B不过这是个很重要的线索，感谢你的努力。', '$N，你去过遗忘之池吗?有没有发现什么?', '探索遗忘之池', '去找贫瘠之地的图加·符文图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (871, '野猪人的袭击', '所有的野猪人都是我们的敌人，而其中有些家伙特别让人讨厌。$B$B对我们而言，当前最大的麻烦就是钢鬃野猪人部族不停地对我们与杜隆塔尔之间的补给线发起攻击。我的探子一直在寻找这些袭击事件的指挥者，但是在找到真正的幕后主使之前，我们总得想些办法来对那些可恶的野猪人进行打击才行。$B$B从这里的东北方向开始搜寻，你应该很容易就能找到他们的巢穴，野猪人的巢穴都好像是破土而出的带刺藤蔓一样的建筑物。去找到他们，把这些肮脏的家伙彻底干掉。', '在钢鬃野猪人的营地里杀掉8个寻水者、8个织棘者和3个猎手，然后向十字路口的索克复命。', '做得不错，$N。那些傲慢的野猪人应该终于知道部落的权威是不容触犯的。', '野猪人的袭击行动越得不到遏制，我们就越难获得足够的补给。', '', '去找贫瘠之地的索克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (872, '野猪人的头目', '$N，我的探子目击了一次针对杜隆塔尔商队的袭击，又是那群该死的钢鬃野猪人干的。其中有一个家伙是这次袭击事件的策划者和组织者：克里尼格·糟鼻。有人在这里的东北方见到过他，就在通往杜隆塔尔的大路的正南方。如果我们要结束这一切威胁，就必须杀了克里尼格·糟鼻。$B$B我们一定要终止这没完没了的袭击，要让他们吃吃苦头。完成任务之后，带上克里尼格·糟鼻的獠牙回来见我。', '杀掉8个钢鬃地卜师、8个钢鬃防御者和他们的头目克里尼格·糟鼻。$B$B把克里尼格·糟鼻的獠牙交给十字路口的索克。', '好样的，$N!克里尼格一死，野猪人对我们商队的威胁就大大减少了。$B$B你的同胞会为你感到骄傲的。', '只要杀了那些野猪人的头儿，他们就会立刻陷入混乱之中，$N。好好学着吧，这些手段对你的将来会大有帮助的。$B$B这些野猪人会像无头苍蝇一样到处乱撞，而那时我们就能趁机夺回贫瘠之地。', '', '去找贫瘠之地的索克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (873, '依沙瓦克', '依沙瓦克是这片水域的主宰，它力大无穷、威武庄严。海岸上的人类都怕它，因为已经有太多的人类被它杀死。$B$B但我不怕，因为它对我来说是一次很有价值的挑战，一个值得尊敬的猎物。$B$B如果你准备好了，那么就到海里去寻找海中的巨兽依沙瓦克吧。$B$B它的灵魂包容在他的心中，听着它跳动的声音，你就将看到自己的命运。', '把依沙瓦克的心脏交给玛伦·星眼。', '你现在已经和依沙瓦克融为一体了，$N。它的灵魂与你同在。我可以从你的双瞳中感觉到它的存在……$B$B总有一天，这双眼睛会让你看到一切的。', '不要对大海有所畏惧，$r。', '', '去贫瘠之地找提度斯阶梯的玛伦·星眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (875, '鹰身人首领', '哈哈哈，$n，你还想接下一单任务？好呀，我真是太高兴了。$B$B这次的任务是剿灭无水岭的鹰身人首领。只有巫翼杀戮者才能成为鹰身人首领，这一点你可以从她们携带的戒指上判断出来。她们其实就是一伙乌合之众，在无水岭一带应该就有不少。只要杀死6个首领就足以对她们的这个母系氏族造成毁灭性的打击了。$B$B$n，你一定要让她们死得很惨，我要让那些下贱的鹰身人知道和部落作对是多么愚蠢的事。', '从巫翼杀戮者那里收集6枚鹰身人首领之戒，把它们交给十字路口的达索克·快刀。', '做得很好，我的朋友。我相信你一定会飞黄腾达的。', '你收集到6枚鹰身人首副官之戒了吗?她们频频袭击部落的恶行必须受到审判!', '', '去找贫瘠之地的达索克·快刀。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (876, '塞瑞娜·血羽', '你在上次与鹰身人首领的战斗中表现得十分出色，所以我希望由你来帮我做最后一件事。$B$B塞瑞娜·血羽是很久前被雷克萨杀死的鹰身人族长的妹妹。显然，这些针对部落商队的袭击是她对我们采取的报复行为。$B$B你的任务就是干掉她，把她的徽记带给我。我将会把她的徽记挂在下一次发出的商队的车顶上……让那些鹰身人好好看看跟部落作对的下场。', '杀掉塞瑞娜·血羽，把她的徽记交给十字路口的达索克·快刀。', '哈!干得不错，$N!干得漂亮……当初我怀疑你是否胜任这项任务，不过你已经用行动证明了一切。谢谢你帮我们战胜了这些该死的鹰身人，这是你的奖赏。', '除非我看到塞瑞娜的脑袋，不然你什么也得不到。', '', '去找贫瘠之地的达索克·快刀。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (877, '死水绿洲', '你在遗忘之池找到的地缝也许在贫瘠之地的其它绿洲中也存在。如果是这样的话，那么这些地缝就有可能是绿洲的生命之源。$B$B我们应该验证一下。$B$B带上这些种子，它们已经失去生命的活力。把它们带到东南方的死水绿洲去，如果那里有地缝的话，就把这些种子放在里面……然后仔细地观察一下。', '调查死水绿洲，然后返回十字路口向图加·符文图腾报告。', '你的发现真是让我惊讶!我给你的种子原本是已经干瘪而且没有任何生命的活力了。显然，绿洲下潜藏的神秘力量能够创造生命!$B$B我们应该再仔细地研究一下……', '你去过死水绿洲了吗?在死水绿洲的湖水下有地缝吗?', '', '去找贫瘠之地的图加·符文图腾。', '试验干枯的种子', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (878, '野猪人的内战', '你必须杀了我的敌人。<猪哼声>你必须帮助碎牙，帮助钢鬃野猪人。我们的部族都非常依赖自己的精神领袖——他们可以召唤大地的力量，<猪哼声>使他们让野猪人的部族变得强大……<猪哼声>$B$B如果你想要知道是谁频繁对部落<猪哼声>发动袭击，那你就应该帮助碎牙！你去杀了刺背野猪人的精神领袖，削弱他们，这样钢鬃野猪人就可以打败他们，统治贫瘠之地了！', '杀掉6个刺背寻水者、12个刺背织棘者和12个刺背地卜师，然后到陶拉祖营地的碎牙那里复命。', '很好……那帮刺背部族的家伙们终于<哼哼>品尝到了我们的痛苦，$r。我本应对此感到高兴，但是<哼哼>事实并不是这样。$B$B你帮助你的同胞，他们会尊敬你。碎牙帮助他的同胞，他们又会干什么?他们对我不闻不问，任由我在这笼子里腐烂!$B$B我被困在这里的时候仍然在想办法帮助他们，但他们根本就没打算来救我!', '先去<猪哼声>杀了刺背部族中的那些精神领袖，然后我才会告诉你更多内幕，$r。<猪哼声>', '', '去贫瘠之地找陶拉祖营地的碎牙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (879, '内奸', '有三个来自剃刀沼泽的部族参与了对部落的袭击。<猪哼声>他们非常狡诈而无情，如果你打败了他们，不仅仅是十字路口，整个贫瘠之地都将迎来和平……<猪哼声>至少野猪人不会再对你们构成威胁了。<猪哼声>$B$B你要找的是纳克、卡兹和洛克·奥克班恩，他们就在贫瘠之地的最南边活动。他们中的一个是施法者，另一个是追踪者，他们的首领是个战士。<猪哼声>$B$B杀了他们，杀了这帮背叛我的家伙。', '杀掉纳克、卡兹和洛克·奥克班恩，把它们的徽记交给陶拉祖营地的碎牙。', '没有比这更好的结局啦。他们本应该<猪哼声>确认一下我是不是已经死了，而不是把我留在<猪哼声>这个被人遗忘的囚笼中。$B$B我还有最后一个任务要交给你，$r。', '$r，你的猎杀进行得如何了?<猪哼声>$B$B索克自以为他知道是谁领导了那些袭击行动，<猪哼声>但是你的成功会让他明白他是大错特错了。$B$B我的死亡是无可挽回的，但是你对我的敌人造成了巨大的创伤，所以我也就没什么可后悔的了。<猪哼声>', '', '去贫瘠之地找陶拉祖营地的碎牙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (880, '变异的生物', '$N，你的发现真让人难以置信。这些绿洲拥有一些特殊的力量，谁也不知道这些力量是怎样来的。$B$B我想知道这几片绿洲是如何影响那些饮用过绿洲里的水的动物的。$B$B去捕获一些在甜水绿洲和死亡绿洲活动的绿洲钳嘴龟，把它们的龟壳给我带过来，我得好好研究一下。', '收集8块变异的钳嘴龟壳，把它们交给十字路口的图加。', '谢谢你，$N。研究一个地区的兽类能够更好地了解这个地区本身的特性。让我们来看看这些龟壳能告诉我们些什么。$B$B请接受我对你所提供的帮助的感谢……也许这些银币对你有用，我想我并不需要它们。', '你拿到龟壳了吗?', '', '去找贫瘠之地的图加·符文图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (881, '埃其亚基', '白雾，也就是我们所说的埃其亚基，是草原狮的首领。它在捕食猎物时悄无声息地行动，就像大地上浮起的一层薄薄的白雾。它的每次出击都是一击毙命，它的猎物甚至来不及恐惧和痛苦就已魂飞魄散。$B$B你会体会到的，因为我要让你去猎杀埃其亚基。它的巢穴就在十字路口的东北边，在那些巨大的科多兽骨附近。$B$B去吧，当你走到它的巢穴附近时，就吹响这个号角，它正在等着你呢。', '把埃其亚基的皮交给十字路口的瑟格拉·黑棘。', '你击败了埃其亚基。虽然它不能再捕猎了，但它的灵魂会一直伴随着你。它会让你了解到什么是柔弱中的刚强，仁慈中的尊严。$B$B你的路还很长，年轻的$C。大步向前走吧。', '那只狮王在召唤你，$N。', '', '去贫瘠之地找十字路口的瑟格拉·黑棘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (882, '伊沙姆哈尔', '伊沙姆哈尔是贫瘠之地最凶猛残忍的赤鳞龙，它狩猎并不是为了健身或是食物，而是因为狩猎是它最大的爱好，伊沙姆哈尔天生就是个杀手。$B$B$N，你会了解到它的天性的，因为你很快就要动身去追踪这条赤鳞龙了。$B$B开始这次猎杀行动吧。先去杀死一只它最喜欢捕猎的动物——斑马，然后把斑马肉挂在棘齿城西北边的枯树上。当伊沙姆哈尔闻到肉味的时候，它就会出现的。$B$B那时，你可要做好准备。', '把伊沙姆哈尔的牙齿交给陶拉祖营地的乔恩。', '这颗牙很小，不过它代表的东西可并不简单。$B$B你拥有了伊沙姆哈尔的力量，$N。愿你能适当地使用这种力量。它是你的重负，也是你的荣誉。', '$N，你战胜伊沙姆哈尔了吗?', '', '去贫瘠之地找陶拉祖营地的乔恩·星眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (883, '拉克塔曼尼', '拉克塔曼尼的蹄子是科多兽力量的象征。', '把拉克塔曼尼的蹄子交给陶拉祖营地的乔恩。', '拉克塔曼尼在我们的语言里被称为“震地者”，它的步伐就像雷声一样铿锵有力。现在，它与你合二为一，它的勇气和稳健将与你同在。现在没什么你应付不了的局面了。$B$B大胆地向前走吧，$N。大胆地向前走吧，震地者。', '$N，从你的步伐中我看到了一种新的力量。告诉我，你的灵魂有没有与伟大的拉克塔曼尼进行碰撞?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (884, '奥瓦坦卡', '只要一被触及，奥瓦坦卡的尾刺就会闪烁起火花。', '把奥瓦坦卡的尾刺交给陶拉祖营地的乔恩。', '雷霆蜥蜴奥瓦坦卡被牛头人尊称为“蓝色霹雳”，因为它拥有令人惊讶的速度。据说很久以前，蓝色霹雳受到电击，天空的狂暴给予这头巨兽无限的力量。$B$B让它的能量流遍你的身体吧，$N。现在的你已经拥有足以匹敌奥瓦坦卡的力量了。', '$N，从你的目光中我看到了一种新的力量!你一定见过伟大的奥瓦坦卡了吧?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (885, '瓦希塔帕恩', '仅仅是轻轻触碰一下瓦希塔帕恩的羽毛，你都会感到相当刺痛。', '把瓦希塔帕恩的羽毛交给陶拉祖营地的乔恩·星眼。', '雷鹰是贫瘠之地上的一种罕见动物，它的死预示着巨大的幸运或是不幸。$B$B不过，瓦希塔帕恩，也就是牛头人所说的灵魂之刺，要么什么都不会带来……要么什么都带来。$B$B你在猎杀灵魂之刺时所感受到的巨大痛苦，是每一个为了获取成功而付出了巨大代价的人都将感受到的。你感受到的刺痛是一种悔恨之痛，你要学会将这种悔恨转化为智慧，在痛苦中获取力量。$B$B通过这个任务，你应该学到了很多东西，$N。', '你有一种新的决心，$N。一种来源于痛苦的决心……$B$B你承受着瓦希塔帕恩之死的痛苦吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (887, '南海海盗', '我当然希望格雷兹里克中将能够保护我们在这片海域上来来往往的商船。贸易巨头们向商船舰队里砸了这么多的金子进来，而这些海盗却在胡作非为，袭击我的船只，还偷走了我的货物！$b$b我听说南海海盗就在南方的海岸边扎营，他们可以说是我的眼中钉肉中刺，假如格雷兹里克搞不定他们，也许你能帮我除掉他们。', '帮棘齿城的加兹鲁维杀死12个南海歹徒和6个南海炮兵。', '孩子，你干得不错。多一点像你那么能干的$r，我就可以少去一些烦恼。希望这些臭海盗能意识到他们该挪挪窝了。$B$B另外，我还得把他们偷走的货物给找回来!', '我甚至不愿去核算我到底在历次的海贼袭击中损失了多少，现在他们居然敢在我的家门口扎营?形势有点失控，安德曼必须得采取一些行动了。', '', '去找贫瘠之地的加兹鲁维。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (888, '被窃的货物', '我希望取回所有丢失的货物，但我想那不太可能。不过，有些货物是我必须要取回的！$b$b正如你所见的，我的天文台马上就要建好了，现在只差两块镜片中较小的一块。第一块已由杜隆塔尔的商队运到，第二块运上了船，但现在还没有到。对了，我还没有收到藏宝海湾的崔斯里克给我发来的靴子！$b$b到海盗营地去一趟，看看能不能找到这些货物吧。', '帮棘齿城的加兹鲁维取回一箱靴子以及一块望远镜片。', '能找回这些东西，对我来说好歹也是个安慰。$N，谢谢你的帮助。我愿意雇用你这样的$r来帮助我完成工作。如果你需要工作，那就回来找我吧，我是不会亏待你的!', '你找到我要的东西了吗?', '', '去找贫瘠之地的加兹鲁维。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (889, '风之魂', '', '', '很好，很好。阿迦玛甘之魂会指引着你，$C。如果你想要更多阿迦玛甘的魔法，就会来找我吧。', '给碎牙带10块血岩裂片回来，你就可以获得无人能敌的迅捷。你将像角斑马一样疾驰，就连风都会嫉妒你的速度。$B$B虽然这种效果的持续时间不会很长，但它也足以让你穿越广袤的贫瘠之地。', '', '去找莫高雷的碎牙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (890, '丢失的货物', '我一直在等从藏宝海湾发来的最后一批货物！我确信是海盗偷走了它们，不过为了保险一点，我还是希望你能去一趟码头，帮我问问迪兹维格……问问我的货物是否已经入库。$b$b把我的帐本交给迪兹维格，让他赶紧把我的存货记录和他的出货单校对一下。', '把加兹鲁维的账本交给棘齿城的码头管理员迪兹维格。', '啊，是加兹鲁维派你来的?稍等一下，让我看看我的出货单，确定我有没有把加兹鲁维的货物发错地方。$B$B他一定正等着崔斯里克的靴子……', '$N，你有什么要托运的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (891, '北方城堡的火炮', '我又有一艘船被北方城堡里的那些狂热的人类给击沉了！$b$b到了该和那帮混蛋算账的时候了。他们的偏执让他们变成了一群疯子。为了取乐，这些不计后果的呆瓜向每一个进入他们视野的目标开火。$b$b从这里向南走，沿着商旅海岸就可以抵达北方城堡，干掉他们的人，然后把他们士兵的徽章给我拿回来作为证明。为了我心爱的舰队，你必须杀了法莫斯队长和她那些疯狂的炮兵！', '棘齿城中的沙罗萨斯船长要你收集10枚塞拉摩徽章并干掉法莫斯队长、炮兵维桑恩和炮兵斯密瑟。', '干得漂亮，$N。那些混帐东西罪有应得。既然我的船和我的水手们已经不在了，那么就让这些纳迦的死给我带来一些安慰吧。', '呀，也许我应该亲自去手刃那些该死的纳迦!显然，你是不会去做这个的。$B$B也许我该给你找些针线活，让你不至于太清闲。', '', '去找贫瘠之地的沙罗萨斯船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (892, '丢失的货物', '我这边的出货记录似乎没什么问题，$n。回去告诉加兹鲁维，他似乎不太走运。不出意料的话，应该是有海盗偷走了他的货物。$b$b很遗憾我不能为他做些什么了。呃……不过你可以告诉他，我从安德麦弄了些东西给他，什么时候他有空的话就过来拿一下吧。', '把加兹鲁维的账本交还给棘齿城的加兹鲁维。', '真是走背运!我想一定是那些海盗……迪兹维格是个不错的家伙，我想他还不至于骗我。毕竟他是吃这碗饭的。$B$B看来我要必须要想办法拿回我的货物了，$N。你说呢?', '那么，迪兹维格怎么说?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (893, '野猪人的武器', '在巨人旷野以南的地区，生活着大群的钢鬃野猪人。据我所知，他们曾是一群无能的铁匠，不过有人告诉我说，野猪人们现在已经逐渐开始改良他们的那些破烂武器了。我想要从他们那里弄些武器样品来进行研究。$B$B如果你能帮我带回来几件武器的话，部落会以你为荣的。帮我带回一把捕猎者用的匕首，一根先知用的魔杖，和一面战士用的盾牌。', '给陶拉祖营地的塔特纳克·钢炉带去一把钢鬃背刺匕首、一根烧焦的钢鬃魔杖和一面钢鬃大盾。', '精湛……真是精湛的武器。$B$B野猪人的技术比我想象中的要先进太多了。$B$B$C，拿着这个，然后请自便。我现在要赶快仔细研究研究这些武器。我们也许低估了这些敌人，那将是一个我们无法承担的致命错误。', '我不相信落后的野猪人能发展出什么高超的锻造技术。不过，我会按大酋长的要求去做，向钢鬃部族学习任何可以学到的东西。$B$B我有很多需要劳力工作的工作经验，只要是对兽人有帮助的，我都非常乐意也很愿意。', '', '去贫瘠之地找陶拉祖营地的塔特纳克·钢炉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (895, '通缉：巴隆·朗绍尔', '通缉令！$b$b巴隆·朗绍尔，破浪号的船长$b$b吉尔尼斯的朗绍尔船长统领南海海盗横行海上，现因海盗罪名指控被通缉。领取奖赏者必须提供足以证明自己杀掉了巴隆·郎绍尔的证据！$b$b——加兹鲁维', '把巴隆·朗绍尔的徽记交给棘齿城的加兹鲁维。', '啊，原来是这件事。你知道，我曾经在公海上看见过破浪号。那是一艘可怕的船，或者说是小艇……那些水手太特别了!$B$B不管怎么说，她划过水面的景象真是漂亮。我很高兴得知她那声名狼藉的船长不会再骚扰我的船只了。', '有什么事吗?我能帮你什么吗?有需要托运的货物吗?', '', '去找贫瘠之地的加兹鲁维。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (896, '矿工的宝贝', '作为像棘齿城这么繁忙的码头的管理器，我始终关注着每一条有利可图的消息。我知道这里与藏宝海湾的所有物品和货币的交易情况。$b$b最近我听到了一些消息，是关于风险投资公司在淤泥沼泽东北的石矿洞的。有个矿工挖出了一枚足有拳头尺寸的翡翠石。我知道有一些买主肯掏钱买那么大的一块宝石，如果你帮我搞到那块宝石的话，那么我愿意和你五五分成，你看怎么样？', '从风险投资公司的某个监督或者执行者那里夺取猫眼翡翠，然后把它交给棘齿城的码头管理员迪兹维格。', '$N，看看这块大宝石!我们就要成富翁了!根据我对幽坑城的各种宝石的估价，我来算算你应该分到多少，怎么样?$B$B让我想想……我觉得这个价格应该没什么问题。$N，很高兴与你做生意。', '只要我们知道是哪个矿工找到了翡翠，那么得到它就是轻而易举的事情了……', '', '去贫瘠之地找棘齿城的码头管理员迪兹维格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (897, '收割者', '这种奇特的昆虫状生物看起来仿佛不是贫瘠之地的生物，而更像是个天外来物。', '把收割者的徽记交给乔恩·星眼。', '我无法判断这是什么生物，因为它的灵魂已经消散。不过，正如你猜测的那样，它并不属于贫瘠之地。我担心它可能会为我们的同胞带来灾难……$B$B现在，做好准备，让我们一起期待揭开这种生物的谜团的那一天吧。', '你看起来好像有什么麻烦，$N。你在贫瘠之地的修行进行得如何了?有什么事情在困扰着你吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (898, '逃离监牢', '终于有人来救我了！$b$b你居然能躲过那些守卫，这简直是太不可思议了。这帮塞拉摩的狂热分子已经毫无理智可言了。他们击沉了我们的船只，俘虏了我这个唯一的幸存者，还称我为联盟的敌人和威胁。$b$b你看我像是要威胁谁的样子吗？我不过是在棘齿城和藏宝海湾之间来回奔波的下等水手而已。$b$b一下子说了这么多，你愿意帮我返回棘齿城吗？等你准备好了，我们就马上越狱。', '护送基尔萨瑞斯·火枝安全地返回棘齿城的沙罗萨斯船长那里。', '嗯，我们以为火枝早就死了!$B$B你的英雄事迹为你赢得了萨罗丹船队的尊重，$N。', '嗯?', '护送基尔萨瑞斯·火枝安全地返回棘齿城。', '去找贫瘠之地的沙罗萨斯船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (899, '复仇的怒火', '我的全家都被刺背野猪人杀害了，$c。也许你能体会这种失去亲人的伤痛，也许你不能……每天我都等在这里，从日出到日落，寻找这些罪无可赦的恶魔。$B$B从那天起，除了关在那边的俘虏之外，我见一个野猪人就杀一个。但这依然远远无法平息我复仇的欲望。$B$B我想你这个$c能够帮助我。$B$B去杀掉那些野猪人，能杀多少就杀多少。带回它们的獠牙，让我们一起为它们的死亡而庆贺吧。', '收集60根刺背野猪人的獠牙，把它们交给十字路口的曼科里克。', '$C，感谢你帮我杀了这些该死的东西。$B$B尽管复仇的火焰仍在心中燃烧，但是看到野猪人遭受这么大的痛苦还是让我感到了些许安慰。', '我又想起了家人的残肢断臂，想起了那熊熊燃烧的家园……我的家园。$B$B我要让那些野猪人血债血还!', '', '去找贫瘠之地的曼科里克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (900, '什么什么平衡器', '三个控制阀门都处于打开状态。根据控制面板上的指示说明，在拆卸零件之前必须要把这三个阀门关闭。', '关闭燃油控制阀、调节阀和主控制阀，然后再使用控制台。', '关闭了三个控制阀之后，绿色指示灯慢慢变为黄色，阀门已经关闭，现在你可以使用这套设备的控制开关了。', '控制台上闪烁的指示灯显示，主控制阀还没有关闭。', '', '去找贫瘠之地的控制台。', '关闭主控制阀', '关闭燃油控制阀', '关闭调节阀', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (901, '什么什么平衡器', '关闭设备后就可以开启控制面板，从控制台中移出主动式负载平衡器。一切准备就绪，现在你需要做的就是取得可以打开控制台的钥匙。', '从工匠斯尼格斯那里拿到能打开控制台的钥匙。', '你把钥匙插入锁中，打开了控制台。控制台上方的红灯熄灭了，终端的所有能源全都被切断了。', '控制灯熄灭了，各种仪表都指向了零刻度，整台设备顿时停了下来。', '', '去找贫瘠之地的控制台。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (902, '什么什么平衡器', '揭开控制台的盖子之后，你看见了密密麻麻缠绕在一起的电线、管子和其它各种奇形怪状的机械装备——其中大多数看起来没有什么实际用途。你把它们拨向一边，在控制台的最里边找到了主动式负载平衡器。一只机械臂把它从机架上拽了出来。', '把主动式负载平衡器交给棘齿城的斯布特瓦夫。', '这个……嗯……有趣的东西……没错，我要马上把它送到安德麦的技工协会总部去。我确信，在经过仔细的检查和研究之后，他们能弄清楚这个东西到底是干什么用的。', '哦，你回来了，$N!你找到主动式负载平衡器了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (903, '草原上的徘徊者', '现在是该让你迎接一些真正的挑战了。贫瘠之地的徘徊者是一种很强悍的动物，而且非常致命。你可以在草丛里找到这些野兽，它们一般都在十字路口的西南边。$B$B猎杀它们的时候要多加小心，$N，不然的话，你很快就会发现自己的角色不再是捕猎者，而是猎物。', '帮十字路口的瑟格拉·黑棘收集7只徘徊者的爪子。', '啊，我看到你忙于捕猎那些徘徊者了。现在，你做好挑战它们当中最强大的首领的准备了吗?', '你的狩猎行动进行得怎么样了，$N?找到徘徊者了吗?', '', '去贫瘠之地找十字路口的瑟格拉·黑棘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (905, '狂暴的镰爪龙', '$n，你要做的下一步事情是打败你的猎物，并找到它们的巢穴。$B$B去猎杀南边的赤鳞迅猛龙，然后拿走它们戴着的羽毛。把羽毛放在死水绿洲西南边的赤镰龙巢穴里，让它们知道你无所畏惧！', '杀死赤鳞迅猛龙并收集它们的羽毛，把这些羽毛放在3个赤鳞镰爪龙的巢穴里，然后返回十字路口的瑟格拉·黑棘那里。', '那么，你已经完成了任务，这需要有足够的勇气，而你无疑证明了自己的实力。$B$B你有没有感觉到自己更加强大了，$N?现在你已经比刚来这里的时候强大很多了，这一点我能看出来。贫瘠之地确实锻炼了你。', '找到它们的巢穴了吗，$N?', '', '去贫瘠之地找十字路口的瑟格拉·黑棘。', '', '检查蓝色迅猛龙巢穴', '检查黄色迅猛龙巢穴', '检查红色迅猛龙巢穴');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (906, '内奸', '$r，带上洛克·奥克班恩的徽记去见索克吧。*猪哼的声音*他应该知道我的部族发生过什么事。哈，他不知道我也参与了*猪哼的声音*这些事情，但我敢肯定他会对你的所作所为给予奖励的。*猪哼的声音*$B$B我们不会再见面了。*猪哼的声音*', '把洛克·奥克班恩的徽记交给十字路口的索克。', '$N，你找到了钢鬃野猪人的头儿并亲自干掉了他?难以置信。$B$B我无法用言语表达我现在的心情，十字路口的人民会对你的勇气致以敬意。$B$B我必须承认的是，我曾一度认为袭击我们补给线的是另一帮野猪人。再次谢谢你，$N。', '怎么啦?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (907, '被激怒的雷霆蜥蜴', '现在，$n，你必须面对强大的雷霆蜥蜴。这些野兽的体型非常巨大，连大地也会随着它们的行进而震颤。与它们作战时一定要多加小心，一次小小的失误就会让你丢了性命。$B$B你可以在南贫瘠之地找到雷霆蜥蜴，当你击败它们之后再回来见我。', '收集3瓶雷霆蜥蜴的血液，把它们交给陶拉祖营地的乔恩·星眼。', '很高兴能看到你凯旋而归，而且你看起来未损分毫。', '你打败雷霆蜥蜴了吗?', '', '去贫瘠之地找陶拉祖营地的乔恩·星眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (908, '废墟之间', '暮光之锤已经进入了黑暗深渊中的月光神殿废墟里去了，他们的目标肯定是要强迫元素生物来对付我们。如果我们不及早采取对策的话，这个地区就将永远被他们控制。$B$B到黑暗深渊去找到废墟中的深渊之石，它应该在靠近水边的地方。深渊之石里面是深渊之核——那里面记载了所有元素生物的历史。如果我拥有了它，我和大地之环就能阻止他们了！', '把深渊之核交给灰谷佐拉姆加前哨站里的耶努萨克雷。', '这正是我需要的东西!深渊之核是个非常完美的资讯源，我可以从中获取许多资讯。不管暮光之锤在干什么―反正肯定不会是什么好事情―我和我的同事都会努力找出真相。$B$B你干得很好，大地之环非常感谢你对我们的帮助。同时，你也帮助了整个部落，因此你应该感到光荣。', '你找到深渊之核了吗?没有它的话，我们就无法得知暮光之锤究竟在那里做什么。', '', '去找灰谷的耶努萨克雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (909, '阿奎尼斯男爵', '被击败的水元素留下了一个奇怪的水球，你猜想这东西可能是为水元素提供能量的。一股看起来就很恶心的水流在球体内翻腾喷溅，而球体本身似乎不受任何自然力的影响。$B$B如果说有人能对这个东西有所了解，那就只能是大地之环的耶努萨克雷了。他就在灰谷的佐拉姆加前哨站里。', '把奇怪的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。', '这……这真是一个大发现，$N。$B$B你说你是从黑暗深渊的阿奎尼斯男爵那里得到这东西的?阿奎尼斯男爵一直以来都被认为是腐败的元素生物，这个球体将证明到底是什么腐蚀了它。如果最终证明是暮光之锤搞的鬼，那么我一点也不会感到吃惊，但是我们的研究还是可以搞清楚他们是怎么做的。$B$B感谢你把这个球体交给我，请接受大地之环最诚挚的敬意。', '啊，又见面了，$N。我正在像往常一样观察海洋的波涛。什么风把你吹到这里来了?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (910, '降帆靠港', '我听过很多有关棘齿城和藏宝海湾的航海故事！我一直都梦想着能在海洋上航行并参加大型海战，我长大后一定要成为伟大的部落水手！那一定很棒！$B$B你愿意带我去棘齿城的码头上看看吗？我保证不会掉到水里或者制造任何麻烦——我只是想看看大帆船，闻闻那带着咸味的海风！', '带着你看护的孤儿去贫瘠之地的棘齿城码头。', '哇，海洋真是太广阔了!你看那些海鸥和码头上的旅客―和我想象中的一样熙熙攘攘。附近还有海贼，这真是太棒了!$B$B感谢你把我带到棘齿城来，$N!这真是太棒了!', '我们到了吗?', '参观贫瘠之地的棘齿城码头。', '去找兽人孤儿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (911, '前线之门', '大家都说灰谷是新的前线战场，而且我听说贫瘠之地的摩尔沙农场是通往那里的必经之处。想想看，部落的前锋部队在一片陌生的森林中为部落争取荣耀，多酷啊！他们说那里将会是联盟和部落竞争最激烈的战场，我要到那里去，$N！$B$B你能不能带我去摩尔沙农场，让我看看新的前线是什么样子的？求求你了！我想要看看部落是怎么把那些讨厌的暗夜精灵赶出去的！', '带着你看护的孤儿去贫瘠之地北部的摩尔沙农场，它就在靠近灰谷入口的地方。', '哇哦，灰谷是个真正充满冒险的地方!你有没有在灰谷战斗过，$N?当我长大并成为部落的英雄后，我就会去灰谷，为了部落的荣耀而战!$B$B感谢你把我带到前线来，$N。你是最棒的!', '我们到了吗?', '参观贫瘠之地北部的摩尔沙农场。', '去找兽人孤儿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (913, '雷鹰的嘶鸣', '雷鹰是一种凶猛的野兽，$n。现在你应该去挑战它们了，把它们的翅膀给我带回来，作为你获胜的证明。$B$B完成这个任务，你就差不多可以结束在我这里的训练了。', '找到一只雷鹰，杀掉它，然后把它的翅膀交给陶拉祖营地的乔恩·星眼。', '你就像雷鹰一样顽强而勇敢，并已经打败了许多强大的敌人，你应该为此感到自豪。$B$B但是你成长的脚步还不能停下，$N。事实上，你会了解到真正的猎人是永远不会安于自己的成绩而疏于长进的。$B$B现在，你可以继续前进了。', '任务完成了吗?你杀掉雷鹰了吗?', '', '去贫瘠之地找陶拉祖营地的乔恩·星眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (914, '尖牙德鲁伊', '哀嚎洞穴中的那些尖牙德鲁伊，曾经是一些高尚的德鲁伊，他们的目标是治愈贫瘠之地的创伤。然而，现在他们却想把这片土地据为己有——曾经高贵的理想变成了扭曲的妄想，我们决不能让他们得逞。$B$B尖牙德鲁伊组织共有四个首领，我在梦中见过他们，即便是现在，他们的面孔仍然萦绕在我的脑海中。打败他们，把他们的宝石给我拿来。$B$B去吧，$N。他们就潜伏在哀嚎洞穴的深处。', '将考布莱恩宝石、安娜科德拉宝石、皮萨斯宝石和瑟芬迪斯宝石交给雷霆崖的纳拉·蛮鬃。', '$N，你成功了!你干掉了尖牙德鲁伊的四首领，我的梦中再也不会出现他们邪恶的面孔，而你也把贫瘠之地从厄运中拯救了出来。$B$B谢谢你，$N。我代表雷霆崖的德鲁伊，也代表贫瘠之地，对你表示衷心的谢意。', '尖牙德鲁伊的狰狞面容仍然在我的梦魇中萦绕，$N。你拿到他们的宝石了吗?', '', '去莫高雷找雷霆崖的纳拉·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (915, '草莓冰激凌', '冰激凌！哦，求你了求你了，帮我买些冰激凌来吧？！我最喜欢草莓味的，而世界上没有比提古勒和弗洛尔的草莓冰激凌更棒的冰激凌了！这是我最最喜欢的冰激凌！$B$B上次我在闪光平原的赛车场尝到过它，不过现在我听说他们开始在城里出售冰激凌了！求求你了，我实在是太想尝尝提古勒和弗洛尔的草莓冰激凌了！', '为你看护的孩子买一些草莓冰激凌。这个孩子似乎最喜欢“提古勒和弗洛尔”牌的草莓冰激凌。', '嗯!我喜欢草莓冰淇淋!提古勒和弗洛尔的草莓冰淇淋是最棒的!$B$B非常感谢你，$N―这是我所得到的最好的礼物!', '我希望他们除了草莓冰淇淋之外还能做出更多口味的冰淇淋，但是还好我最喜欢的就是草莓口味!', '', '去找兽人孤儿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (916, '树林蜘蛛的毒囊', '我是为了观察居住在黑丝洞的树林蜘蛛才来到幽影谷的。这些森林蜘蛛是另一种体型更小的蜘蛛的近亲；我相信世界之树在它们身上产生某些特殊的影响，我需要一些样本来研究它们以证实这一点。$B$B首先，我需要一些它们的毒液，帮我从这些蜘蛛身上收集一些树林蜘蛛的毒囊吧，它们就在北方的黑丝洞一带活动。有了毒囊，我就可以研究一下这种毒与它们的近亲体内的剧毒有何相似之处。', '给奥达希尔的基尔沙兰·风行者带回10个树林蜘蛛的毒囊。', '感谢你，$N。我一回到达纳苏斯就会开始比较这些毒囊中的毒液与其他蜘蛛毒囊中的毒液。我坚信这其中的奥妙肯定与我们新的世界之树最近的成长有关。', '你收集到毒囊了吗，$N?', '', '去泰达希尔找幽影谷的基尔沙兰·风行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (917, '树林蜘蛛的卵', '现在我已经得到蜘蛛的毒液，不过我还需要一些活体样本以便更好地进行研究。不幸的是，抓来一只活的巨型蜘蛛对你来说也许太困难了，年轻的$c。而且，我也没办法处理一只巨型蜘蛛！$B$B但如果你能找到一枚还未孵化的蜘蛛卵的话，从卵里提取样本作为研究材料就变得容易多了，而且我也能对付卵中未孵化的蜘蛛。$B$B在黑丝洞的深处一定有蜘蛛的巢穴。拜托了，帮我到那里去找一枚蜘蛛卵吧。', '给奥达希尔的基尔莎兰带回1枚树林蜘蛛的卵。', '啊，非常好。我要把这枚蜘蛛卵和先前收集到的毒液运送到达纳苏斯，等我在这里的研究一结束后，我也要回去那里了。我期待着从这些材料中找出一些震撼性的资料。', '你去过影丝洞了吗，$N?你找到蜘蛛卵了吗?', '', '去泰达希尔找幽影谷的基尔沙兰·风行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (918, '林精的种子', '泰达希尔的林精是代表自然的元素生物，它们以某种方式反映了我们这里的自然生态的情况。$B$B所以看到林精变得如此愤怒真让人感到担忧。$B$B我相信这与土壤有关。我一直在用不同的方法种植植物，可以用林精的种子来试验一下。我请求你，能在奥拉密斯湖周围的林精那儿收集一些种子给我吗？', '给奥拉密斯湖边的德纳兰带去8粒林精的种子。', '你弄到种子啦，太好了!$B$B我会把它们种在我已经准备好了的特殊土壤中，我相信这些种子将会发芽并成长成为性格温顺的树精。也许你很快就能看到结果啦!', '你弄到种子了吗?我急切地想要种下它们。', '', '去找泰达希尔的德纳兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (919, '林精的新芽', '小林精在奥拉密斯湖周围和涌泉湖以西迅速成长。我害怕它们会的数量会多到无法控制——我们应该在它们惹出乱子之前把它们从土地上清除。$B$B你在湖边行走的时候，如果看到任何林精的新芽长出来，就顺便除掉它。让我们的土地免受污染！', '给奥拉密斯湖边的德纳兰带去12个林精的新芽。', '这么多!恐怕它们正在以惊人的速度蔓延，我希望我能找到它们被污染的真正原因。$B$B感谢你的帮助，$N。这片土地因你的努力而免受更多的污染。', '你好，$N。湖水周围有新芽吗?', '', '去找泰达希尔的德纳兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (921, '大地之冠', '是该出发去追寻并探索你的自己的命运了，$n。但是在你走出我们美丽的森林之前，你应该首先好好了解我们近代的历史。$b$b自海加尔山战役之后，我们的族人改变了许多。因为消耗了全部的力量来击败阿克蒙德并赶走燃烧军团，诺达希尔再度被暗淡的阴影笼罩……$b$b有一个你必须去完成的任务，到奥达希尔北边的月亮井里装一瓶水，然后把它拿回来给我。', '装满水晶瓶并将其带回给奥达希尔顶部的特纳隆·雷拳。', '那么，你应该已经知道了海加尔山战役结局的第一部分了吧。你需要知道的还有很多，你会在穿越泰达希尔前往达纳苏斯的旅程之中逐渐了解到任务的其他部分。', '月井里的水源自永恒之井，这个蕴涵着强大的魔法能量的古代源泉曾给我们的世界带来的巨大的恐慌。$B$B德鲁伊们充分利用月井的特性来修行，而哨兵们则将它视为月神艾露恩的祭坛，但是无论是谁，都不许再使用魔法。', '', '去泰达希尔找幽影谷的特纳隆·雷拳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (922, '雷利亚·绿树', '$N，你能给我的朋友雷利亚·绿树带去一粒种子吗？他是个住在达纳苏斯的德鲁伊，我们上次谈话时，他对我的林精研究工作很感兴趣。他有自己的想法，如果有粒可以用来作试验的种子的话，他一定会非常感激的。$B$B谢谢你，$N。你帮了我一个大忙。希望有一天你能看到我的劳动成果。$B$B雷利亚一般会在塞纳里奥区的路上闲逛。', '给达纳苏斯的雷利亚·绿树带去一粒林精的种子。', '啊，树精的种子?我正好想要一粒这样的种子来帮助德纳兰进行研究。$B$B但是我担心有许多树精已经开始堕落了，而来自于树精的种子必定遗传这种特性，我无法制止它们的堕落。$B$B德纳兰善于应对这样的事情，他会为未来的树精找到治疗这种堕落的方法的，也许……他是它们唯一的希望。', '你好……$B$B请问你有事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (923, '青苔之瘤', '一种邪恶的力量正在森林中滋生。我们到处寻找邪恶之源，但当我们找到的时候……为了泰达希尔的安全，我们必须消灭掉那些已经无法挽救的林精。生长在泰达希尔北部的涌泉湖的林精所受的污染最为严重，你必须消灭它们！$B$B消灭在那里发现的林精，收集生长在它们身上的青苔之瘤，然后把那些瘤交给我，让我烧掉它们。', '收集5个青苔之瘤，然后把它们交给达纳苏斯的雷利亚·绿树。', '干得不错!这些充满了毒素的瘤是树精的疾病症状，必须从我们的土地上清除掉!$B$B我要赶快处理掉这些瘤。谢谢你，$N。', '$N，你去过涌泉湖了吗?你干掉那些树精了吗?', '', '去达纳苏斯找贸易区的雷利亚·绿树。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (924, '恶魔之种', '恶魔之种是燃烧军团使用的一种强大工具，它生长在鬼雾峰洞穴里的恶魔火坛上。$B$B我已经准备好了能量石，只要把它放在恶魔之种附近，就可以切断它与燃烧军团的联系。$B$B从石台上取一块能量石，把它带到鬼雾峰上的火焰祭坛去。从这里一直往西走，然后在交叉路口向北转，鬼雾峰就在你的左边。从鬼雾峰北坡爬上去应该是最安全的路线。$B$B动作快点——石头的魔力在很短的时间内就会耗尽。', '取一块有瑕疵的能量石。在能量石失去魔法之前把它带到火焰祭坛去，然后向雅克塞罗斯复命。', '你的任务完成了。你按照尼尔鲁的要求摧毁了恶魔之种，不过这一切并没有结束……$B$B恶魔之种毁灭的时候，一股极其强大的能量波横扫了整个世界。我感觉到了，我想它们也都感受到了，那些恶魔肯定想要知道是谁以何种方式破坏了它们的小玩具……$B$B不过，不管今后会有怎样的麻烦，我这里有件东西要交给你。尼尔鲁说这是你应得的报酬，他让我谢谢你。$B$B感谢你的努力。', '恶魔之种仍然存在，我能感受到它的魔力……', '', '去找贫瘠之地的雅克塞罗斯。', '摧毁恶魔之种', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (925, '凯恩的蹄印', '他们说凯恩·血蹄是部落有史以来最伟大的英雄之一。当我长大之后，我也要成为部落的英雄！$B$B你认识凯恩吗，$N？你可不可以帮我个忙呢？你能不能帮我搞到他的蹄印？我不知道怎么向他开口，他也许一直很忙而没有时间理我……但是你可以！你是和他一样伟大的冒险者！我打赌他会很乐意把蹄印给你的！$B$B求求你了！', '到雷霆崖去，为你看护的孩子拿到一份凯恩·血蹄的蹄印。', '哦哦!你弄到了凯恩.血蹄的蹄印!非常感谢你!啊，太棒了……他还亲笔在这里写了一封信―是给我的!他真是太酷了，我终于拿到他的签名了!也许有一天我会去亲自感谢他……就在我成为部落英雄的那一天!$B$B你是最棒的，$N。谢谢!', '当兽人孤独地与命运抗争时，牛头人与他们同甘共苦而不图回报。这就是荣耀，$N。', '', '去找兽人孤儿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (927, '布满苔藓的心脏', '恶臭的黑苔兽的心脏上长满了又黑又油腻的苔藓。事实上，如果它没有那缓慢而有节奏的心跳，也许你根本就看不出这是颗心脏来。$B$B也许德纳兰会想要研究一下这颗心脏。', '将布满苔藓的心脏交给奥拉密斯湖畔的德纳兰。', '……这是什么?一个树精的心脏??长满了恶臭的苔藓!$B$B感谢你把它带给我，$N。我会仔细地检查这颗心脏，如果运气够好的话，我应该能搞清楚这种苔藓到底是什么东西。', '$N!你有东西给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (928, '大地之冠', '关于月亮井和泰达希尔的点点滴滴实在是太多了，我无法一一告知给你，这需要你自己去探索。科瑞萨斯·月怒正在等着你。我已经把你所带回来的水倒入了这个容器中，把它送到科瑞萨斯那里去吧。$b$b出发吧，科瑞萨斯就在多兰纳尔的月亮井旁。你只需要沿着奥达希尔南边的小路走出幽影谷，沿着鹅卵石铺成的小路一直走，然后向西转就行了。$b$b注意，你要一直沿着路走，$n。最近路旁的森林里出现了许多危险的野兽。', '将装着半瓶水的瓶子交给多兰纳尔的科瑞萨斯·月怒。', '啊，我明白了。你是被特纳隆派来的。好吧，那么，我们看来得有很多事情需要开始着手去做的，而且似乎没有多少时间留给我们了。$B$B我想，我们最好现在就开始', '你好，$C。是什么事让我们能在此愉快地会面呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (929, '大地之冠', '首先，让我告诉你必须要完成的任务的其它一些细节。达纳苏斯的德鲁伊需要使用泰达希尔的月亮井的水，所以月亮井的水需要不断地补充。使用这种特制的瓶子，你可以收集起月井之水。$b$b带着这个瓶子去东边的星风村，装满村外的月井里的水，再带回来给我。你完成任务之后，我将继续讲述台纳隆的故事……', '用月亮井的水装满翡翠瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。', '海加尔大战之后，我们一度迷失了方向。诺达希尔尚未摆脱战火的威胁，而我们不朽的生命--我们族类的泉源!--也已不复存在。$B$B这时背叛者从监狱里逃出来为非作歹，而怒风尊师也消失无踪。一切进入黑暗时期。', '你好，$N。完成你的任务了吗?', '', '去泰达希尔找多兰纳尔的科瑞萨斯·月怒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (930, '发光的水果', '一颗又大又圆的果实挂在叶下。$B$B你觉得德纳兰一定会想要研究一下这东西。', '把这颗发光的水果交给奥拉密斯湖的德纳兰。', '你在泰达希尔发现了这个?很有趣……这颗果实非常奇怪。也许它的种子是从很远的地方带来的，甚至可能是艾泽拉斯……因为它对泰达希尔的土壤有奇怪的反应。$B$B谢谢你，$N。现在我要开始研究了……', '$N，你看起来像是有事要告诉我。是关于树精的新消息吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (931, '发光的树叶', '植物上的叶子泛着微弱的光，产生了一种不断变化的光晕。$B$B你觉得德纳兰可能会想要研究这种东西。', '给奥拉密斯湖畔的德纳兰带去1片发光的树叶。', '你从哪儿弄到这个的?几十年前我去悲伤沼泽的时候曾看见过这样的植物，能在泰达希尔看到它真是令人惊异!而且你看，它居然长得如此之大!$B$B感谢你，$N。请原谅我只能说这么多，我得抓紧时间研究研究了……', '你有东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (932, '扭曲的仇恨', '$n，你必须提高警惕，我们不能对这件事袖手旁观。萨特就够我们头疼的了，而眼前的这件事更是火烧眉毛。$B$B有个名叫迈雷纳斯的恶棍就住在附近的地狱石洞穴里，他在那儿聚集了一大批骁勇的战士为自己卖命，他的心如无月的夜晚一般黑暗，他当前正在密谋着一些极端邪恶的勾当。$B$B到这里北边的洞穴去找他，带他的徽记来见我。', '杀掉迈雷纳斯，带他的徽记去见多兰纳尔的塔隆凯·捷根。', '迈雷纳斯领主终于死了，我也终于可以去做些别的事情了。感谢你，$N。', '你杀掉迈雷纳斯领主了吗?去干净俐落地把他干掉，$N。否则他就会一直是我们的心腹大患。', '', '去泰达希尔找奥拉密斯湖的塔隆凯·捷根。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (933, '大地之冠', '在达纳苏斯城门的东南方还有一口月亮井，就在阿里斯瑞恩之池的岸边。由于瘤骨熊怪的数量无节制地增长，以及他们对于这个地区的疯狂攻击，哨兵们根本无法有效地控制这一地区。$b$b在寻找月亮井的时候小心点，一定要时刻握紧你的武器。', '用月亮井的水装满红玉瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。', '怒风大师从未回来过，德鲁伊们已经陷入了混乱，至今我们仍不知他到底发生了什么事。玛法里奥失踪，大德鲁伊范达尔·鹿盔接过了德鲁伊的领导权，他使黑海岸的古树议会相信现在是重建辉煌和重获不朽的时候了。$B$B经议会的批准，范达尔和那些最强大的德鲁伊们在泰达希尔种下了新的世界之树。', '起初关于疯狂熊怪的袭击的报告都被忽略了。谁又能想到那么热爱和平的熊怪们会变得如此狂暴?这又成了困扰我们新家园的一大问题。', '', '去泰达希尔找多兰纳尔的科瑞萨斯·月怒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (934, '大地之冠', '然而泰达希尔并不是一切都尽如人意。范达尔·鹿盔对于世界之树的计划正如他自己所希望的那样一步步展开了，但是还有一个小问题，这个问题或许会给泰达希尔带来一些麻烦。$b$b不过我不打算介入此事。你得去一趟最后一口月亮井，就在这里西北面的神谕林地里，就在神谕之树的树干下面，那是我们的第一口也是最强大的一口月亮井。在那里灌一瓶水，然后回来向我报告。', '用月亮井的水装满紫水晶瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。', '在神谕之树面前……你会感觉到自己几乎能把智慧抓在手里。让我继续说下去……$B$B随着泰达希尔的成长，大德鲁伊去祈求巨龙的祝福，因为在古代，那些巨龙的地位远在诺达希尔之上。但是时间之王诺兹多姆拒绝祝福泰达希尔，反而斥责德鲁伊的傲慢。和诺兹多姆一样，阿莱克丝塔萨也拒绝了德鲁伊们的要求，但是没有她的祝福，泰达希尔的成长就会受到不良的影响，后果难以预料……', '神谕之树、大德鲁伊和德鲁伊们一起密切关注着泰达希尔的成长。但是虽然我们有了一个新家，但我们还没有重新得到不朽的生命。', '', '去泰达希尔找多兰纳尔的科瑞萨斯·月怒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (935, '大地之冠', '没有生命的赋予者阿莱克斯塔萨和时间之王诺兹多姆的祝福，泰达希尔的成长就很难一帆风顺。我不断收到有奇怪的猛兽出现的报告，而疯狂的熊怪也开始不断地袭击路人。$b$b我只能希望大德鲁伊们能尽快找到解决的方法。我会将把你带来的所有月亮井水都灌入这个瓶中，然后让你把它带到达纳苏斯去。$b$b把这只瓶子交给范达尔·鹿盔，你可以在德鲁伊之林里找到他。', '将装满月亮井水的瓶子带给在达纳苏斯的大德鲁伊范达尔·鹿盔。', '啊，对，这正是我需要的水。特纳隆巴科瑞萨斯一定花了不少时间来找这些水……但是似乎没能找到一个最可靠的信差……嗯。$B$B不管怎么样，我终于能继续我的工作了。泰达希尔所面临的诸多问题全都压在我的肩上，我希望能尽快把它们都解决掉。$B$B拿着这个，它应该会对你有些用处的。', '我并没有召唤你来，所以我想知道为什么你会来到这里。$B$B无论是什么原因，请快点说明你的来意。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (937, '神谕林地', '我和一个哨兵小组被派到这里来保护神谕之树免受鹰身人的威胁。它们已经在沼泽周围建造了很多巢穴，我们正在试着把它们赶回去。$b$b神谕之树曾派信使到达纳苏斯去通报这一情况，但一群鹰身人在中途杀死了那个信使。$b$b如果你认为你能胜任这项任务的话，就到它们的巢穴里去，杀死它们，把它们的腰带拿回来作为证明。', '收集6条血羽腰带，把它们交给神谕林地里的哨兵阿瑞尼亚·碎云。', '我对你在如此短的时间内完成任务感到非常惊讶，$N。或许我该请求你留下来帮助我……但是我知道接下来还有更艰巨的任务在等着你。$B$B我注意到神谕之树已经脱落了一层树皮，看来又有任务需要你去完成了，你得去和它谈谈。', '以你的一己之力来对抗它们的利嘴钢爪会很困难，$N，但是我坚信你能完成这个任务。', '', '去泰达希尔找涌泉湖的哨兵阿瑞尼亚·碎云。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (938, '密斯特', '这只猎豹的毛皮是很特别的暗灰色，与四周的森林几乎融为一体。她静静地躺在地上，你发现她伤得很重，背部和腹部都有很深的伤口。$b$b她抬起头盯着你，蓝色的双眼闪着智慧的光芒。她似乎希望跟随你。', '护送密斯特去神谕之树附近的月亮井旁找哨兵阿瑞尼亚·碎云。', '啊，感谢你，$N!我一直在担心……我怕再也见不到密斯特了，甚至以为她已经死了，我怕我永远不能再和我这位忠诚的伙伴相聚……我欠你的东西太多了，$N，我会永远感激你的。', '密斯特……是我的错!那些家伙趁我不备……我没有保护好你……', '把密斯特领到哨兵阿瑞尼亚·碎云身边', '去泰达希尔找神谕林地的哨兵阿瑞尼亚·碎云。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (939, '萨瓦里克长笛', '打败萨瓦里克之后，你仔细看着从他的尸体上拿到的木制长笛。$B$B这根带节的木棍摸起来很结实，但是当你把它拿在手中翻看时，笛子表面的纹理似乎突然开始旋转了起来。你猛然间感觉到了一丝恐惧……$B$B你摇了摇头，感到这可能是你的感觉在和你开玩笑。$B$B可能其它的萨特身上有关于你所发现的东西的线索。将你发现的线索交给费伍德森林南部的德鲁伊，艾瑞丹·蓝风。', '将萨瓦里克长笛和5个碧火魔符交给费伍德森林南部的艾瑞丹·蓝风。', '我能感受到古树所受的痛苦，$N……$B$B这些东西几乎令我难以忍受……', '这是什么，$C?你看来对它很感兴趣。', '', '去费伍德森林找翡翠圣地的艾瑞丹·蓝风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (940, '泰达希尔', '你的事迹在森林里传扬，$n。鹰身人已经被赶走，森林恢复了平静，这里的生物再次感受到了安全和宁静。我几乎已经不敢派信使去大德鲁伊那里了，但我知道你会帮我把信息安全送达的。$b$b把消息传递给他，我知道森林将保佑你安全地将信息送达目的地。', '把神谕之树的报告交给达纳苏斯的大德鲁伊范达尔·鹿盔。', '我曾疑惑为什么神谕之树这么久都没和我联系……似乎在一些问题减少的同时，另一些问题需要引起更多关注了。$B$B我担心我们在泰达希尔的工作永远完成不了，我们的不朽体质永远都无法恢复。$B$B无论如何，你在神谕之树那里做得很好，你的勤奋应该受到奖励。', '嗯……森林之灵充满你的全身，$C。你找我这个卡多雷的大德鲁伊有什么事呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (941, '培养精华', '我已经除去了苔藓，但它早已经被污染了……$B$B把它放到我的培养槽里，营养丰富的土壤也许能净化并治愈它。', '把被污染的精华放到德纳兰的培养槽里。', '你把心脏放进了培养槽里，它很快就自己钻进了土壤中!$B$B几秒钟后它又扭动着钻出来了，看起来非常纯净。心脏微微地跳动着……像是在急切地等待你去拿。', '培养槽里装满了由德纳兰精心准备的土壤。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (942, '健忘的勘察员', '这块化石和我在铁炉堡看到的一块化石非常的相似。一个名叫弗拉冈特的考古学家把它带到了我们一年一度的冒险者年会上。他坚信那块化石中蕴藏着奇特的魔力，而且那种魔力是可以被提取出来的。$b$b上一次我听到弗拉冈特的名字时，他还住在米奈希尔港的深水旅店里，正在等着被护送到维尔加挖掘场去。把雷姆塔维尔的化石交给他，也许他能揭开化石中蕴含着的秘密。$b$b去米奈希尔的船都是从暴风城出发的。', '把神秘的化石交给米奈希尔港的考古学家弗拉冈特。', '哦，天哪!你说这块化石来自遥远的卡利姆多?$B$B难以置信!简直难以置信!', '你要给我什么呀，朋友?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (943, '健忘的勘察员', '嗯，我在那里会议之后把原始样品交给了勘察员维尔。最近，我在洛克莫丹发现了雷鲁之石，我认为它就是解开神秘化石的钥匙。$b$b当我准备赶往维尔加挖掘场的时候，遭到了迅猛龙的攻击，雷鲁之石也给弄丢了。$b$b我不知道是哪只迅猛龙吞掉了这块石头，但如果你能找回它，我应该就可以释放这些化石中的魔力了。当然，我们也需要最初从维尔加挖掘场取回的那枚化石。', '米奈希尔港的考古学家弗拉冈特要你把雷鲁之石带给他。', '太好了，$N!$B$B现在让我看看，能不能用这块石头释放出化石里的魔力。', '$N，有了雷鲁之石，无论是我找到的化石还是雷姆塔维尔在黑海岸那里找到的化石，对我来说就都没有什么秘密可言啦。', '', '去湿地找米奈希尔港的考古学家弗拉冈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (944, '主宰之剑', '我很奇怪纳迦为什么会出现在这里，在黑海岸。但更奇怪的是……暮光之锤。那些信\r\n徒崇拜非常非常古老的大地之神，一个很久以前就被打败的神。$B$B主宰之剑就是那个古神被打败的地方。$B$B去那里找到更多暮光之锤的信徒。$B$B带上这瓶占卜之水。等你到了主宰之剑之后，就用它制造一个占卜之碗，通过那个碗，你可以直接和我通话。', '收集信息，然后使用占卜之水创造出一个占卜之碗，并利用这个碗和安努通话。', '暮光之锤果然在主宰之剑一带活动?$B$B太糟糕了。$B$B很久很久以前，上古之神丧命于利剑之下，但那并不意味着他的力量也随之消失了。$B$B暮光之锤必定是在寻找他的力量。', '主宰之剑，$N。$B$B到那里去，然后和我交谈。', '进入主宰之剑。', '去找占卜之碗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (947, '洞中的蘑菇', '我正在研制一种药剂，需要一种生长在特定洞穴里的稀有蘑菇才能配制。这个洞穴位于壁泉河瀑布的后面，在东边稍稍偏北的地方。$B$B我本来准备自己去，不过古树之林建议我不要靠近那个地方。我们尊贵的盟友觉得那个洞穴是黑海岸新出现的邪恶势力的藏身之处。$B$B$N，请你帮我收集那些蘑菇。与此同时，请显示一下那处洞穴以便确认古树所担心的事情。', '收集5个粗柄蘑菇和1个毒帽蘑菇，把它们交给奥伯丁的巴瑞萨斯·月影。', '非常感谢你，$N。这些蘑菇真是不错!$B$B当你在壁泉河瀑布一带活动的时候，有没有找到什么可以证明古树之林的担忧的证据?$B$B古树之林是非常睿智的，不过我希望这次是他们错了。', '$N，你拿到了我要的蘑菇了吗?你去过那处洞穴了吗?', '', '去黑海岸找奥伯丁的巴瑞萨斯·月影。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (950, '向安努回复', '仔细阅读暮光之书会让人发疯。只要盯上一小会儿，书上的字就开始游动乱舞，原本美妙的插图和花边也扭曲得变了形。$B$B为了不至于让神志陷入混乱之中，你只好赶快撕下了一张写着这些可怕的文字的书页。', '把令人发狂的书页交给安努。', '一种混乱而原始的魔法环绕在这些潦草的文字间。我能感受到上古之神的力量。$B$B希望它能揭开暮光之锤在黑海岸一带活动的目的。', '$N。你回来了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (951, '玛塞斯特拉遗物', '你在主宰之剑找到的那页书来自于一本古籍……一本精灵撰写的古籍。但它已经被暮光之锤诅咒和玷污了，看来暮光之锤的信徒是希望用古代精灵的魔法将他们古老的主人重新召回我们的世界。$B$B到东北边的玛塞斯特拉废墟去看看，找到那些古代的遗物。如果我能研究一下它们的话，也许能搞清楚暮光之锤打算如何使用那些精灵的魔法。', '收集6个黑暗深渊遗物，把它们交给古树之林的安努。', '谢谢你。这些圣物来自玛塞斯特拉最辉煌的时代……曾经宏伟的精灵城市已经衰落，只有这些魔法的裂片残留了下来。希望我们能赶在敌人之前解开藏在那片土地中的秘密……$B$B你要保持警惕，$N。要准备随时返回玛塞斯特拉废墟的深处，终有一天，命运会带你回到那里。', '$N，你在玛塞斯特拉废墟找到什么了吗?', '', '去黑海岸找暮光谷的安努。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (952, '古树之林', '如果你有时间为神谕之树跑跑腿的话，我想让你帮我送一封信到黑海岸的古树之林去。$b$b你大概只有乘角鹰兽才能到黑海岸，不过我相信你绝对可以完成这个任务。把这个交给知识古树安努，他正等着我的消息，就像我曾焦急地等待来自神谕林地的消息一样。', '把范达尔的信交给黑海岸古树之林里的安努。', '啊，谢谢你，$N。真奇怪，那些大德鲁伊总是有些神经过敏。森林之魂知道，该发生的事情总会发生，怒风尊师也很清楚这一点。', '啊，$C。我能为你做什么吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (953, '亚米萨兰的毁灭', '到东边去就可以发现亚米萨兰废墟。现在，那些未曾安息的暗夜精灵贵族的亡灵如同生前一般盘踞在那里，那里也曾经是艾萨拉的仆人练习他们强大魔法的地方。$b$b我在奉命探索那片废墟的时候偶然发现有两块巨大的石碑，上面是潦草写下的亚米萨兰的故事，还有这座城市被毁灭的历史。在我阅读碑上的刻文的时候,突然有亡灵出现和我说话，吓得我赶紧逃了回来。$b$b如果你够胆量的话就去一趟那片废墟，替我破译一下石碑上的刻文。', '研究刻有亚米萨兰的故事及其被毁经过的石碑，然后回到黑海岸的哨兵坦莎·月刃那里。', '我有一些关于先祖之战的记录，尤其是关于永恒之井大爆炸前后的记录。这样看来，亚米萨兰的毁灭并不令人感到奇怪。$B$B谢谢你，$N。在你的帮助下，我在这里的工作终于算是完成了，我现在就开始准备向议会递交一份全面的报告。', '如果你研究过石碑刻文，并了解了亚米萨兰的沦落史，我想把你知道的资讯报告给奥伯丁的上古议会。', '', '去黑海岸找亚米萨兰的哨兵坦莎·月刃。', '阅读亚米萨兰的衰落', '阅读亚米萨兰的毁灭', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (955, '巴莎兰', '如果要我把一生的故事都讲出来，恐怕你会失去耐心。简单地说，我的一生漫长而痛苦，而现在这种鬼魅般的生活更是对我最痛苦的折磨。$b$b我被魔法囚禁在这里。也许我说的话有些夸张，但我可以向你发誓，如果你能帮我找到从这里逃脱的办法，我一定会对你感激不尽的。现在我被施加了封印，如果你能帮我拿些萨特和劣魔的耳环，我也许能找到一些线索。', '帮巴莎兰的阿斯特利安收集8只劣魔耳环。', '啊……巴莎兰的劣魔没有我想要的东西……但是，他们最近和它曾有过联系。最近……我是用你的时间来估计的，而不是我的时间。最近这个词对我来说已经是很久以前的某个时间了，几乎是另一个年代……', '一旦得到那些耳环，我就可以施展魔法来找出囚禁我的封印。几个世纪以来，我一直期望着能摧毁这个封印，给我带来真正的自由……在这几个世纪里我也曾想过可能再也无法重获自由……', '', '去黑海岸找薄雾海的阿斯特利安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (956, '巴莎兰', '如果劣魔开始与施加在我身上的封印频频联系的话，我想我已经猜到原因了。毫无疑问，这枚封印已经落入指挥他们的萨特的手中。$b$b我强烈地感觉到了这一点，$n。某个萨特得到了那个封印。如果你能得到它，或许就可以帮我冲破这牢笼，我将对你不胜感激。', '获取远古月亮石封印，把它交给巴莎兰的阿斯特利安。', '这……这真让我难以置信，我现在拿着的竟是束缚了我那么长时间的东西。我们不要浪费时间了，$N。当封印被摧毁以后，我又可以自由自在地在林间漫步了。', '这个神殿的柱子对我来说就是牢不可破的枷锁，$N。我没有力气打破它们，也没有魔法摧毁它们……$B$B一千多年来，我注视着它们，思考着这样的问题:究竟要等到什么时候，我才能获得自由?而到那时，是否又会有另一层无形的枷锁束缚着我……', '', '去黑海岸找薄雾海的阿斯特利安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (957, '巴莎兰', '某位非常强大的贵族制造了这个用来囚禁我的封印。在南方的亚米萨兰有一处与这里相似的废墟，那里至今仍燃烧着远古的火焰，那蓝色的火焰可以摧毁这个封印。$b$b不过在那片废墟里，你千万要当心，$n……', '用亚米萨兰废墟中的远古火焰摧毁远古月亮石封印，然后回到巴莎兰的阿斯特利安那里。', '我自由了，$N，自由!我终于可以亲眼目睹世界上的万事万物了……之前我很少能知道关于外面世界的东西。在我被囚禁之前，永恒之井还存在着，精灵贵族们侍奉着我们无比敬爱的女王艾萨拉。$B$B我能感受到囚禁我的人，也就是我以前的主人，埃瑟里克斯，他依然活着……我内心的绝望早已化成复仇的信念!', '实话说，$N，我有些担心……担心你的到来―以及这所有的一切―仅仅是一种幻觉。你知道那有多痛苦吗?我……求求你，你必须尽快行动。', '', '去黑海岸找薄雾海的阿斯特利安。', '摧毁远古火焰处的封印', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (958, '上层精灵的工具', '$C，我有一项任务交给你。$b$b你去过亚米萨兰废墟吗？如果还没有，你可以在通向南方的大路东侧找找看。亚米萨兰废墟曾经是众多暗夜精灵贵族的家园，而如今那里却成为他们滥用魔法的见证。$b$b据哨兵的报告，那些贵族的亡灵依然在使用古代的魔法武器进行抵抗。我们必须获得那些遗物，只有这样我们才有可能真正摧毁那些亡灵。', '帮奥伯丁的桑迪斯·织风取回7个上层精灵的遗物。', '尽管这可能只是我自己的臆想，但我仍能感觉到贵族魔法的污迹附着在上面。我要销毁这些东西，或许这样就可以让那些邪恶再也无法被唤醒了。', '如果高等精灵们的那些魔法物品在那场摧毁了一切的大灾难中也同样被毁灭就好了……不过现在的当务之急是，我们必须尽全力确保过去的悲剧不再重演。', '', '去黑海岸找奥伯丁的桑迪斯·织风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (959, '港口的麻烦', '啊呀！$b$b你也看到了，最近有点背运！早间从藏宝海湾过来了一支大型的运货船队，我是说大型的！我从没有见过那么多的箱子。我想加快点速度，所以卸货卸得稍微快了点。$b$b结果呢，还没等我弄清楚是怎么回事儿，我看到那个可恶的家伙——疯狂的马格利什——手拿一瓶99年波尔多陈酿跑了出来。我一路追他到了哀嚎洞穴，但是我可不想进到那个可怕的地方去。$b$b嗯……你够不够胆量去把他给我找出来？', '棘齿城的起重机操作员比戈弗兹让你从疯狂的马格利什那儿取回一瓶99年波尔多陈酿，疯狂的马格利什就藏在哀嚎洞穴里。', '好极啦!刚才我差点连饭碗都要丢了!我马上就把这件礼物给加兹鲁维送去。$B$B谢谢你，$N。你干得很出色!', '自从疯狂的马格利什偷了那瓶99年波尔多陈酿逃走之后，码头主管就天天找我的麻烦。我想那瓶酒一定是大财主里维加兹私底下送给加兹鲁维的礼物。$B$B如果你有足够的胆量和耐心找到疯狂的马格利什，并且帮我取回那瓶波尔多酒的话，我一定会重重酬谢你的。', '', '去贫瘠之地找棘齿城的起重机操作员比戈弗兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (962, '毒蛇花', '幽暗城的皇家药剂师学会派我来这儿完成一个特殊的任务，$n。我想你会愿意帮助我的，因为黑暗女王领导下的被遗忘者将会通过我的任务得到进一步的加强。$b$b近来我在研究一种罕见的植物，它的名字叫毒蛇花，我相信这种药草有着巨大的能量。$b$b不幸的是，它只生长在哀嚎洞穴的最深处，那是贫瘠之地最危险的洞穴之一。', '为雷霆崖的药剂师扎玛收集10朵毒蛇花。', '啊，这正是我要的东西。你干得很出色，$N。', '我很想知道你是否能从哀嚎洞穴收集到足够的毒蛇花。我已经派去了很多人，但没一个回来的。', '', '去找莫高雷的药剂师扎玛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (963, '永志不渝', '永恒之井的战斗结束以后，亚米萨兰被毁灭了，全城的暗夜精灵都成为了这座城市的陪葬，其中就有我的至爱安娜雅。$b$b我也没有想到，在那次灾难过去了数千年之后，对安娜雅的回忆依然萦绕在我的梦中。有一次，当我恍恍惚惚地在黑海岸的森林里游荡的时候，我发现自己正置身于亚米萨兰的废墟之中……我居然看见了我的至爱——她那饱受折磨的亡魂。$b$b她必须得到自由，但我没有勇气去做，因为让她得到自由，就必须先摧毁她的亡灵。', '释放安娜雅·晨路的灵魂，把她的坠饰交给奥伯丁的塞瑞利恩·白爪。', '谢谢你，$N。或许如果由我亲自来做的话会更好一些……不过，即使是经过了几千年，我也不忍心对我的至爱痛下杀手。$B$B请让我安静一会儿，让我一个人来体味这悲伤……', '怀着满心的悲痛，我随着怒风尊师进入了休眠状态，把哀伤深深地埋藏在梦中，这一睡就是数千年。', '', '去黑海岸找薄雾海的塞瑞利恩·白爪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (964, '骸骨碎片', '通灵学院大门的钥匙名叫骷髅钥匙，它一定是由某具骸骨制造而成——事实上是若干具骸骨——并在适当的模具中使用最坚硬的金属进行加固。天生就能打开通灵学院大门的人拥有一种特殊的力量，这种力量能让钥匙发挥作用。$B$B重要的事情要优先处理掉，$N。我们需要一些骸骨碎片来制造钥匙。安多哈尔内的骸骨应该符合我们的要求，但是安多哈尔城外的那些骸骨也许同样有效。', '将15块骸骨碎片交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。', '很好，$N!现在轮到我了―我将对这些骸骨进行适当的回火，使它们不至于在锻造过程中断裂。$B$B下一步就是获得钥匙的模具了，在塔纳利斯有个哥布尔铁匠，他曾经制作过类似的模具。跟其它的哥布尔一样，他也会为那些出价最高的人效劳的。', '尽可能多地杀戮吧，$C―我们需要大量合适的骷髅碎片来制造钥匙的外壳。你要知道，骷髅钥匙这个名字可不是白来的。', '', '去提瑞斯法林地找亡灵壁垒的药剂师迪瑟斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (966, '奥萨拉克斯之塔', '一群术士在这座塔的里里外外住了下来。我本应该早些回去向艾莉萨报告，但我想如果我亲自去报告的话也许会错过些什么。$b$b德尔格伦怀疑这伙人聚集在塔周围是要密谋什么坏事，但我们对此知之甚少。$b$b我手里有一些术士的羊皮卷轴碎片，但我还需要更多的碎片才能解开这个谜。对了，我必须警告你，千万不要冒险进入塔中，因为塔里的术士非常可怕！', '在奥萨拉克斯之塔附近帮巴苏尔·影击收集4块破旧的羊皮纸。', '非常感谢你，$N。这应该能为解开术士聚集之谜提供一些帮助……$B$B嗯~~……暗滩教派?我以前从没听说过这伙人。由于对他们几乎一无所知，我自然也就不可能了解他们的计划。$B$B时间紧迫，你必须尽快把警报传给德尔葛兰。', '你找到卷轴碎片了吗?如果你找到足够的碎片，我应该可以从中找出什么线索来。', '', '去找黑海岸的巴苏尔·影击。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (967, '奥萨拉克斯之塔', '我的主人，净化者德尔格伦，是一位伟大的圣骑士。为了保护森林不受恶魔和亡灵的袭扰，德尔格伦一直在尽全力帮助我们。他向我传授了圣光术和各种其它的战斗技巧。$b$b你必须尽快把这个教派的消息告诉德尔格伦。$b$b他就驻扎在南方的灰谷森林里的迈斯特拉岗哨。请快一点，我非常担心这个暗滩教派带来的威胁会越来越大。', '把巴苏尔的信送给灰谷森林中的净化者德尔格伦。', '如果你不介意的话，我得说你的装备如此精良，不像是个普通的信差，对吧?我猜巴苏尔是想要确保他的信能交到了我的手上。让我看看他想说些什么……$B$B这真是让人心烦的消息。你要知道，当发现了不死生物或者恶魔的势力时，我会帮助夜精灵的哨兵部队消灭他们。$B$B刚开始的时候我不习惯夜精灵的行为方式，不过现在，我已经对这些盟友非常尊敬了。', '$C，你找我有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (968, '深渊之神', '尽管这本书又旧又破，但你依然能看清封面的标题：$B$B深渊中的力量$B$B在这本皱巴巴的书里是一串不知如何发音的名字的列表，这些名字后面都注有令人感到不安的头衔称谓、祭祀的方式以及首选的祭品等等……其中很多祭品是活的人型生物。$B$B在封面的内侧有这样的文字：“葛利·硬骨的符文和厄运，铁炉堡……经营者：葛利·硬骨。”$B$B如果葛利·硬骨卖的是这样的书，那么也许他会把这本书买回去。', '把《深渊之神》交给铁炉堡的葛利·硬骨。', '啊，一本《深渊之神》的复制本。这是一本有趣的书。也许有人会觉得它很有用……$B$B但这本书实在是太破了。哦!你看看这里!几乎在每一页的空白处都有笔记!$B$B嗯……我记得这本书，去年我把它卖给了宝卡尔。你是他的朋友吗?嗯，没错，我想你应该是的。在你的目光里有着与他相同的激情!$B$B嗯，一般来说，宝卡尔的朋友就是我的朋友。而人都是会照顾自己的朋友，对吧?', '你好，$g先生:女士;。$B$B你对我的书感兴趣吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (969, '祝你好运', '啊，我一看见你就知道——你想要一个幸运符咒。玛艾里无所不知！$B$B在冬泉谷的南部有一道峡谷，那里的巨人身上有时候带有一种具有强大能量的冰块，当然你也可以自己从峡谷中收集冰块碎片。$B$B带给我四片霜槌碎片回来，然后我的幸运符咒就是你的了。', '收集4块霜槌碎片，把它们交给永望镇的巫医玛艾里。', '啊，就是这些碎片……我这就开始给你制作符咒。稍等片刻!', '带回我要的裂片，然后我就会告诉你更多东西!', '', '去冬泉谷找永望镇的巫医玛艾里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (970, '奥萨拉克斯之塔', '巴苏尔的这封信里的消息真是可怕。这个暗滩教派对我们而言始终是一个很大的威胁，必须尽快清除才行。我和东北方的奥迪拉兰城中的暗滩教派打过交道，他们中的一个人持有一枚灵魂宝石，其中蕴藏着有关这个教派的魔法的秘密。$b$b把它交给我，我应该有办法从中找出一些信息来。', '搜集一枚发光的灵魂宝石，并把它交给迈斯特拉岗哨的净化者德尔格伦。', '嗯，这块灵魂宝石已经被附上了某种黑暗魔法。让我们看看里面藏着些什么东西，好吗?', '你得到那枚灵魂宝石了吗?', '', '去灰谷找迈斯特拉岗哨的净化者德尔格伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (971, '深渊中的知识', '你也许知道，我喜欢收集各种知识：古老的知识，有用的知识，可以打开神秘通路的知识，可以唤醒沉睡之人的知识。$B$B据说有本古老的书卷叫做洛迦里斯手稿，它被藏在黑海岸的黑暗深渊底部。那里是往日死去的精灵安息的地方。那些精灵在他们的城市被毁灭之前都有着广博的知识。$B$B到黑暗深渊去找手稿吧，我不会忘记你为我做的事，即使到世界毁灭的那一天……', '把洛迦里斯手稿带给铁炉堡的葛利·硬骨。', '你找到手稿了!今天我真是太高兴了!我会复制这份手稿，然后把它分发给我的兄弟姐妹们，让大家都能了解这古老的手稿中所记载的洛迦里斯知识!$B$B你为我们做出了巨大的贡献，$N。我希望这个礼物可以表达我们对你的无限感激。', '去灰谷的路途很遥远，你的任务也不简单。不过如果你能拿到手稿，$N……你将得到可观的报酬。', '', '去找丹莫罗的葛利·硬骨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (973, '奥萨拉克斯之塔', '伊克鲁德·玛格苏尔，没错，我了解他。他可是一个强大的兽人术士，就住在火痕神殿里，那是一个位于灰谷西南的极端邪恶的地方。$b$b至今他并没有给我们造成太大的麻烦，而我也没工夫去对付他，不过现在看起来……他的死期到了。', '把伊克鲁德·玛格苏尔之书交给迈斯特拉岗哨的净化者德尔格伦。', '今天你做了一件伟大的事，$N。你应该为打败了一个如此强大的术士而感到自豪。$B$B现在，让我们看看能从伊克鲁德的笔记中找到些什么。', '你看起来有点不舒服，$N。你还好吗?', '', '去灰谷找迈斯特拉岗哨的净化者德尔格伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (974, '究根问底', '对我来说，这里的温泉简直就是个不解之谜，这些热量究竟是哪里来的？$B$B这些水池离火羽山那么近，我真的想知道火山和温泉之间到底有没有关系。我制作了一个测温计来读取火山的温度，我想要找到温度最高的地方。它是按照我独创的计量单位进行测量的！$B$B拿着这个温度计，当你经过某个炎热的地方，就顺便读取一下那里的温度！', '安戈洛尔环形山的克拉兰克要你去找到火羽山中温度最高的地方。$B$B当你找到一个看上去很热的地方时，就右键点击温度计来测量当地的温度。不断尝试，直到你找到温度最高的地方。', '是的，显然火山的温度和温泉之间有千丝万缕的联系。我会对这些资料进行复查以确保其准确性，但是热量的传播距离和速度有点……嗯……', '我想过要自己去找，但是……我害怕那里的火元素!', '', '去安戈洛环形山找葛拉卡温泉的克拉兰克。', '找到火羽山上最热的地方', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (976, '奥伯丁的补给品', '德尔格伦让我给奥伯丁的哨兵艾莉萨·星风捎信，顺便给她提供一定的补给，但是我讨厌一个人上路。密林深处到处危险的敌人，我可不想让这些物资和信息落到他们的手里。$b$b如果你或者其它人能担当我的护卫，我们现在就可以出发了。有你的帮助，我坚信这些物资一定能平安运抵奥伯丁。', '护送费罗·艾隆汉安全地穿越灰谷森林，然后和迈斯特拉岗哨的净化者德尔格伦谈一谈。', '今天你表现得非常不错，$C。德尔葛兰送来的物资将被用于对付那些威胁着森林的黑暗势力。$B$B请接受这些东西和我衷心的感谢。', '我们急需把物资送去增援在黑海岸的哨兵部队。', '护送费罗·艾隆汉', '去灰谷找迈斯特拉岗哨的净化者德尔格伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (977, '雪怪计划！', '现在我已经有了遮盖机体的东西，然后只需再有一件东西就成了。好吧，实际上是两件。两支角！$B$B冰蓟雪人王和冰蓟雪人女王身上都有这样的角，它们就住在东南边的洞穴里。那里的雪人数量众多，我想你不会找不到它们的。$B$B记住，我只要外观最好的角——绝对不要有伤痕的或者破碎的角！', '为永望镇的乌米收集2支完美的雪人角。', '我等不及要给我的朋友展示这个机械雪人了!现在，稍等片刻，我这就把它们安上去……$B$B太完美了!', '$N，我已经快要完成皮毛的粘贴工作了，请你快点帮我找到角。', '', '去冬泉谷找永望镇的乌米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (978, '月光羽毛', '从辛特兰收集到的枭兽羽毛中包含着魔法能量的痕迹。这些能量……看来并不是枭兽能够运用的，它们只是简单地蕴含在这些生物体内——而带有这种能量的都是最强悍的枭兽。$B$B在研究这个问题的过程中，我听说在白雪皑皑的冬泉谷那有很多的枭兽。那些生物是否携带着相同的能量呢？请帮我找到这个问题的答案，$N。到冬泉谷去收集它们的羽毛，然后把它们交给我。', '从冬泉谷收集10片月光羽毛，然后将它们带给鲁瑟兰村的艾瑞拉斯·琥珀。', '现在我可以比较这些羽毛了……让我仔细看看……', '这些能量到底是从什么地方来的?我想我们正在沿着正确的道路找寻答案，$N。', '', '去泰达希尔找鲁瑟兰村的艾瑞拉斯·琥珀。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (982, '深不可测的海洋', '从我们现在所在位置沿着海岸一直往北可以看到两艘沉船——银色清晨号和迷雾之纱号。这两艘船在穿越茫茫大海，最终将要达到奥伯丁的时候遇到了那些可恶的鱼人，它们现在只能躺在海底作为那些恶棍的战利品了。$B$B这两艘船的船长都没有能幸免于难，他们的日志以及其它有价值的东西还锁在船里的箱子中。我希望你能帮我找到这些东西，这对于那些生还的船员也是颇有意义的。', '找到银色清晨号的保险箱和迷雾之纱号的保险箱，把它们交给奥伯丁的高尔博德·钢手。你可以在村庄北部遇难的船只里找到这两只箱子。', '你为奥伯丁做出了杰出的贡献，$g小伙子:小姑娘;。我们会好好保管他们的东西的。$B$B至于你，请拿着这个。这份薄礼代表了我对你的谢意。', '这两艘船的船长都是好人，他们不应该遭受这样的厄运。也许把他们的东西从鱼人手中夺回来是安慰他们灵魂的最好方法。', '', '去黑海岸找奥伯丁的高尔博德·钢手。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (983, '传声盒827号', '嘿！看看我这划时代的最新发明：传声盒！通过它，你可以和很远的人进行交谈！$B$B也许你已经见过它们了，嗯，就是那些上面有操纵杆的盒子。不过传声盒有一个毛病，就是它们需要经常性的维护。$B$B而且每一个盒子的问题都不一样，不过我在这个问题上做得就很巧妙！你看，我把每一个盒子都放在那些能给它提供最合适的修理零件的生物附近。现在传声盒827号出了点故障，它就在奥伯丁的南边，需要6只蟹腿来进行修理。我会奖赏你的……', '收集6只蟹腿，把它们放进传声盒827号。', '当你把蟹腿放进机器中，就听见齿轮开始磨合了。从传声盒里发出的巨大响声来判断，蟹腿应该是已经放在了正确的位置上。不一会儿，机器就开始发出嗡嗡的声音，还伴随着微弱的语音。$B$B“喂?喂喂?嗯……喂!你修好它了。我是维兹班恩!非常感谢你……嘿，你想不想再修修另一个传声盒?”$B$B', '传声盒827号静静地站在那里，只有一束闪光显示需要把6只蟹腿放进它的储物盒里。', '', '去黑海岸找奥伯丁的传声盒827号。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (984, '熊怪的威胁', '$N，我来这里是想看看魔苔的影响有多么厉害。我的一些同胞险些被泰达希尔的一个堕落的熊怪杀死，而我发誓不会让类似的情况再次出现……更别提更糟糕的情况了。$B$B在黑海岸，我已经看见了一系列有关各种生灵堕落的线索，但我需要找到这种堕落是否有蔓延的迹象。我想我们仍然应该通过熊怪来进行调查，你可以帮我找到一个熊怪的营地吗？如果你发现了任何情况，就马上回来报告我。', '在黑海岸找到一处堕落熊怪的营地，然后向奥伯丁的特伦希斯报告。', '$N，这真是个糟糕的消息。$B$B熊怪离奥伯丁这么近，我们必须时刻做好准备，以防不测。$B$B谢谢你，$N。', '你的搜索行动进展如何了，$N?', '找到一处堕落的熊怪营地。', '去黑海岸找奥伯丁的特伦希斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (985, '熊怪的威胁', '$N，在侦察敌人方面，你已经展示了足够的才能。但你与他们作战的技能如何呢？$B$B并不是所有的冒险者都喜欢面对面的遭遇战，我是某些冒险者更喜欢潜行之类的隐秘行动。$B$B如果你觉得自己能行，就到奥伯丁南边的那个熊怪营地吧，那里的熊怪对我们构成了极大的威胁。在那一带活动的都是黑木部族的熊怪，去杀掉8个黑木探路者和5个黑木风语者，然后回来向我报告。', '杀掉8个黑木探路者和5个黑木风语者，然后回到奥伯丁向特伦希斯汇报。', '洗去你外衣上的鲜血吧，$N，请不要为你做的一切伤感;相反，你应该感到庆幸。你减轻了熊怪对奥伯丁的威胁，虽然黑海岸仍然处于魔苔的阴霾之下，但我们终于可以暂时松口气了。', '别缩手缩脚的，孩子。我知道杀害森林中的生物有些让你难于接受，但在现在的情况下，这是迫不得已的。当前我们还没有发现任何能让森林不再堕落的方法，因此只有尽我们的所能去延缓这个堕落的进程，直到我们找到了有效的方法为止。', '', '去黑海岸找奥伯丁的特伦希斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (986, '失踪的主人', '$N，你帮了我很多忙，我能不能再请求你帮助一下锐爪和他的主人沃科尔？我可以帮你精心制作一件有魔力的斗篷，它能够让你在寻找沃科尔时畅通无阻，免受黑海岸上任何猛兽的阻挠。$B$B不过要制作这件斗篷，我需要从月夜雄虎或者月夜雌虎身上获取几张上等毛皮。你可以在急弯河以南找到那些月夜猛虎。', '收集5张优质月夜猛虎毛皮，把它们交给奥伯丁的特伦希斯。', '这些虎皮真的很不错，$N。我马上就给你缝制披风。$B$B过一会儿再来找我。$B$B哦，还有一件事:在你使用了披风上的魔法以后，你与别人的交流将受到限制，除了和别人交谈什么也不要做。否则，魔法效果就会消失。', '在为你做好那件披风之前，我是不会让你冒险去找沃科尔的。', '', '去黑海岸找奥伯丁的特伦希斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (992, '加基森水业公司', '如果你感兴趣的话，我们现在正在为加基森水业公司招聘兼职初级勘探员。$B$B那些游牧民不断地侵占我们的水井，这迫使我们不得不去勘探更多的水源！沙漠中到处都可能有水的存在，但是只有聪明人才能找到它们。$B$B拿着这个瓶子，到流沙岗哨旁的水池那里帮我采集一些水样回来。那个水池旁边有些巨魔在看守着，小心点，完成任务之后尽快把水样送到我这里来。', '用未使用的寻水器在流沙岗哨旁边的池中采集水样。一旦你收集到水样，就尽快将其交给加基森的高级勘探员菲兹杜瑟。', '什么?你遭到了一群大虫子的袭击?啊，这对加基森水业来说可不是个好消息，简直是糟透了……$B$B我想我应该告诉你，已经有报告说在这片沙漠上出现了很多疯狂的虫子，它们正在不断地夺取这里宝贵的水资源。一开始我还以为这只是个谣传，那些游牧民已经给我们带来太多的麻烦了，我曾经以为所谓疯狂的虫子只是游牧民的恶作剧而已。好吧，现在我们至少了解了事情的真相!', '欢迎回来，初级勘探员$N!你完成我交给你的任务了吗?', '', '去塔纳利斯找加基森的高级勘探员菲兹杜瑟。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (995, '偷偷溜走', '好吧。我们走。$B$B记住，在你逃脱以后，到奥伯丁去找特伦希斯。我会自己赶去那里的。', '离开熊怪洞穴，然后去见奥伯丁的特伦希斯。', '$N!很高兴看见你能安全返回。你对沃科尔提供的帮助使我相信，我们最终可以战胜在黑海岸或是其它任何地方所遇到的一切挑战。', '嗯，$N?', '帮助沃科尔逃离洞穴', '去黑海岸找奥伯丁的特伦希斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (996, '被腐化的迎风花', '', '', '你将两份塞纳里奥植物药膏涂在了这株迎风花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的迎风花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (997, '德纳兰的泥土', '你在往南方旅行吗？你要去奥拉密斯湖吗？如果是这样的话，我有个任务想请你帮忙……$B$B我的同伴德纳兰在湖的东岸有个营地，他在那儿对泰达希尔的植被进行研究和试验。他想要一包达纳苏斯的稀土，但送货的在路上耽搁了，我这两天才刚刚收到稀土。$B$B你能把这包稀土带给他吗？', '把稀土交给奥拉密斯湖畔的德纳兰。', '啊，是它!我等这包稀土已经等得太久了。我希望它还是新鲜的……$B$B感谢你把它带给我，$N。你真是个好心的$C。', '你有东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (998, '被腐化的迎风花', '', '', '你将两份塞纳里奥植物药膏涂在了这株迎风花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的迎风花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1001, '传声盒411号', '细小的声音噼里啪啦地从机器内部传出来。$B$B“这里是维兹班恩！下一个传声盒在奥伯丁北部海岸上的某个地方。我的记性有时候不太好，不好意思！$B$B那台传声盒的编号是411，需要3颗蛇颈龙的眼球来修理。你可能得跳进漆黑冰冷的大海深处去寻找黑海岸鱼龙……真抱歉……$B$B就像上次一样，只要你给传声盒带去维修所需的物资，它就会给你吐出报酬的。*打嗝*……什么？没事，我很好！”', '从位于传声盒411号附近的深海中收集3颗黑海岸蛇颈龙的眼球。', '当你把蛇颈龙的眼球放进去之后，传声盒发出一阵噪音，然后再次被启动了。短暂的沉默以后，你听见一个熟悉的声音。$B$B“螃蟹酒是最棒的……”*打嗝*$B$B“什么?哦，你修好了传声盒?哇塞，你太厉害了。你愿意修理另一个传声盒吗?”$B$B你听到了液体倒入杯中的声音，然后是咕咚咕咚的喝水声。', '机器的舱口开着，似乎在满怀希望地等待有人把3颗蛇颈龙的眼球放进去。', '', '去黑海岸找薄雾海的传声盒411号。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1002, '传声盒323号', '传声盒突然静了下来，然后你听见维兹班恩又开始说话。$B$B“下一个传声盒的编号是323。它在奥伯丁北部，不过……我的麦酒哪儿去了？什么？哦，在路上，小桥边，你不会找不到它的。”$B$B维兹班恩咕哝咕哝地说了一些不连贯的话，然后你听见大口喝酒的声音。$B$B“这个传声盒需要月夜猛虎的牙齿来维修……需要6颗。”', '收集6颗月夜猛虎的牙齿，把它们放进传声盒323号。', '传声盒突然开始工作，你能听见清晰的磨牙声从里面传出来。$B$B“啊，你成功了!真是好消息……那么……你为什么不继续下去呢?哦!除非你还想再接下一个任务!”$B$B', '当你把6颗月夜猛虎的牙齿放进机器里之后，你听见里面传出了语无伦次的话语。难道已经有别的什么人把机器修好了?', '', '去黑海岸找壁泉河的传声盒323号。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1003, '传声盒525号', '在一阵什么东西沸腾和油滴四溅的奇怪声音之后，你听见维兹班恩颤抖的声音从机器中传出。$B$B“顺着这条路，在遥远的南方就能找到下一个传僧盒。里应该不难发现它……就在路边上……在栅栏附近。我想我把它藏在矮……矮树丛里了。呵呵呵……没错，传声盒525号得有从那些灰斑蓟熊身上扒下来的灰色头皮才能维修。对，灰色的……呵呵呵……”$B$B当机器停止下来的时候，你听到更多类似吞咽的声音。然后，突然之间，它又启动了。$B$B“4块！”', '收集4块灰色头皮，然后把它们放在传声盒525号中。', '“里把灰斑蓟熊的头皮放进去啦?蜡真是太好了……什么?哦，系的，我想里已经注意到，即使没有机器里的蜡些物品，我也能和里缩话。但是我说它们坏了可系一点也不假!$B$B里看，在作为通讯工具的同时，传僧盒也能亮造美酒，这就是它们最有用的地方了!不好意思骗了你，不过夜精灵们不喜欢我这卖酒的商人。这个盒子里还有些东西，权当是我对里的感谢。感谢里!”$B$B', '你听见从传声盒525号中传出了歌声。$B$B“尽管，螃蟹酒甜美，蛇颈龙麦芽酒清醇，月夜猛虎酒的品质优良，但系，没有什么，能比得上灰斑蓟熊啤酒来得，珍贵。我马上就能品…品尝!”$B$B机器的舱口是开着的，伴随着一遍又一遍的歌声，等待4块灰色头皮的到来。', '', '去黑海岸找暮光海岸的传声盒525号。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1007, '远古雕像', '我有一项任务交给你，$N。$B$B当我坐船经过被淹没的佐拉姆废墟的时候，受到了纳迦的攻击。这些家伙突然从水里冒出来，他们的利爪差点就把我撕个粉碎！我想尽办法带上所有可以带走的物资逃了出来，然后在这里搭建了一个简易的营地。$B$B但是，当我逃上岸的时候……我最重要的宝贝不见了。$B$B求求你，$N，找到我遇袭的地方，帮我寻找一尊古代雕像。正是为了它，我才会鼓起勇气闯入佐拉姆海岸这么危险的地方。', '把远古雕像交给塔尔伦，他的营地就在佐拉姆海岸附近。', '你找到它啦!谢谢你，$N!$B$B左拉姆古城中隐藏着很多秘密，这尊雕像是揭开其中的许多谜团的关键。', '你找到雕像了吗，$N?', '', '去找灰谷的塔尔伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1008, '佐拉姆海岸', '在我们的西北海岸，也就是佐拉姆海岸一带，潜伏着一股邪恶的势力。$B$B佐拉姆海岸是已经被毁灭的佐拉姆城残存的部分，佐拉姆主城在大爆炸中被摧毁，沉到了海底，这些很久以前发生的事情已经快要被暗夜精灵忘却了。$B$B现在，纳迦又回来了。至于他们为什么会回来，谁也不知道。但是这些并不重要，我们必须杀了这些魔鬼，把他们送回地狱！$B$B完成任务之后，就立刻回来向我报告。', '收集20颗怒尾纳迦的徽记，把它们交给阿斯特兰纳的辛德瑞尔。', '干得好，$N。你在佐拉姆海岸与纳迦战斗的事迹值得称赞。$B$B我知道你的胜利得来不易，因为我们都清楚纳迦不但力量强大而且诡计多端。我们知道这些，因为我们曾经和他们有过一段共同的历史。$B$B这是一段我不愿回忆的历史。', '决不能让纳迦侵犯我们的海岸，$N。你必须到佐拉姆海岸去完成你的任务。', '', '去灰谷找阿斯特兰纳的辛德瑞尔·速火。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1009, '卢泽尔', '除非你能找到可以打开雕像上的那只锁的钥匙，否则雕像的秘密将永远无法解开。$B$B那把钥匙其实是一枚戒指——佐拉姆之戒。在这座城市被很久以前那场大爆炸所掀起的波涛淹没之前，佐拉姆之戒曾经属于这座城市的统治者。$B$B这枚戒指已经丢失很多年了，不过纳迦最近找到了它。$B$B他们的领导者卢泽尔就住在佐拉姆北部边缘的一个小岛上。请帮我取回这枚戒指吧，$N。', '找到佐拉姆之戒，把它交给佐拉姆海岸边的塔尔伦。', '你找到戒指啦!谢谢你，$N。拿上这个作为报酬吧，我会永远记住你今天为我所做的一切。', '据说佐拉姆之戒能打开那座城市中的任何一把锁。$N，你找到它了吗?', '', '去找灰谷的塔尔伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1010, '巴斯兰的头发', '在北边那座巴斯兰鬼屋的废墟上，曾经生长着一种叫做巴斯兰的头发的植物，它能够让人的灵魂安宁下来。$B$B在村庄里有个患病的孩子，我想他的病痛不仅仅是肉体上的。你愿意帮我到巴斯兰鬼屋去寻找一些巴斯兰的头发吗？我需要用它来医治这个孩子。$B$B巴斯兰鬼屋就在迈斯特拉岗哨以北，灰谷和黑海岸交界的地方。', '收集5份巴斯兰的头发，把它们带给灰谷的奥雷迪尔·阔叶。', '啊，你找到巴斯兰的头发啦!我要马上做药来治疗这个孩子，希望我的混合药剂能有效。$B$B什么……被遗忘者在巴斯兰鬼屋活动?这下麻烦了，麻烦大了……', '你收集到巴斯兰的头发了吗，$N?这孩子的情况越来越糟糕了……', '', '去灰谷找迈斯特拉岗哨的奥雷迪尔·阔叶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1011, '被遗忘者的病菌', '被遗忘者——部落中的亡灵势力——已经潜入了灰谷，现在就潜伏在我们的废墟和洞穴之中。我们认为他们的目标是在暗夜精灵的领地上散播疾病。这一点必须尽快得到确认！$B$B被遗忘者在南边有一个营地，就在朵丹尼尔兽穴附近，那是他们制造和封装毒物的地方。攻入那个营地，给我偷取一瓶病毒，我得研究一下这些毒药，这样才能搞清他们真正的意图。', '找到一瓶病毒，把它交给林歌神殿中的凯尼斯·静风。', '太好了，$N。现在……只要测试出这瓶中的病菌的成分，被遗忘者的计画便可以真相大白了!', '你找到营地了吗，$N?有没有拿到病菌?', '', '去灰谷找林歌神殿的凯尼斯·静风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1012, '疯狂的德鲁伊', '在我和被遗忘者的毒物抗争的时候，曾经在恍惚之中产生了一段幻觉，我看到朵丹尼尔兽穴中的德鲁伊被亡灵下毒害死了！他们现在是游荡的幽灵，他们的灵魂离开了身体，并且变得越来越疯狂。$B$B为了让德鲁伊的灵魂早日安息，你必须进入朵丹尼尔墓穴，杀死那些昔日的德鲁伊领袖：坦尼尔·黑木、尤希尔·唤月和玛沃里斯·裂云。$B$B赶快去吧。', '杀死这些德鲁伊：坦尼尔·黑木、尤希尔·唤月和玛沃里斯·裂云，然后向慰藉之林中的凯尼斯·静风复命。', '我感到朵丹尼尔的德鲁伊们不再痛苦了，这说明你已经完成了任务。$B$B你完成了一件很艰巨的任务，$N。你除掉的并不是所有被那些被遗忘者扭曲的灵魂，但是随着这一小部分灵魂的毁灭，希望其它的灵魂可以得到安息。', '朵丹尼尔的德鲁伊在我的梦里哀嚎，$N。你必须杀了他们的领袖!', '', '去灰谷找林歌神殿的凯尼斯·静风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1013, '乌尔之书', '$N，在影牙城堡里有一本书，它被称作乌尔之书，我很想得到它。乌尔在天灾军团到来之前曾是达拉然的一位伟大的法师，他对其它世界的研究对……被遗忘者中的某些团体……很有价值。$B$B到影牙城堡去找到这本书，把它交给我，我会向黑暗女王汇报你的贡献。', '把乌尔之书交给幽暗城炼金区里的看守者贝尔杜加。', '很好。我收藏的乌尔之着作现在又多了一本。他的知识很渊博，不过他的善良却使他无法掌握真正的力量。所以当天灾军团来了之后，他没能通过考验。$B$B如果我们被遗忘者想要生存下去，就不能存有这种弱点……$B$B……假如我们想要征服敌人的话。', '你找到那本书了吗，$N?', '', '去找幽暗城的看守者贝尔杜加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1014, '除掉阿鲁高', '现在我已经对整个诅咒有了一个全面的了解，并开始着手研究如何补救了。$b$b但阿鲁高依然好好地住在影牙城堡中。在干掉阿鲁高之前，我们还不能宣称银松森林已经是黑暗女士的地盘。$b$b但是，我得去搞明白怎样才能根除他的魔法影响，$n。所以我只能把除掉阿鲁高的任务交给你了。$b$b到影牙城堡去，永远地结束阿鲁高的肮脏法术。把他的徽记给我带来！影牙城堡去，永远地结束阿鲁高的肮脏法术。把他的徽记给我带来！', '杀死阿鲁高，把他的徽记带给瑟伯切尔的达拉尔·道恩维沃尔。', '银松森林终于从阿鲁高的控制中解脱出来了。你为黑暗女王完成了一件很重要的任务，$N。你的毅力应该得到奖赏。', '只要阿鲁高一死，我们就能进一步巩固黑暗女王在洛丹伦大陆上的势力。', '', '去银松森林找瑟伯切尔的达拉尔·道恩维沃尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1016, '元素护腕', '拿着这张占卜卷轴——它可以侦测出那些水元素是谁召唤出来的。但是你必须从水元素身上拿到一些东西才能查到真相。$B$B只需几个完整的元素护腕就可以完成占卜过程，其它类型的护腕对我们没什么用，但是也许会有商人想要收购那些东西。当你拿到了完整的元素护腕之后，就对它使用占卜卷轴，得出结果之后回到我这里来，让我们看看下一步该怎么办。', '收集5个完整的元素护腕，并对它们使用占卜卷轴。然后把使用过的占卜卷轴带给银风避难所的哨兵维尔莉妮·星坠。', '干得不错，这些资讯足够让我找到那个该死的混蛋了。嗯，接下来就去干掉那个在我们的湖里召唤了那么多水元素的法师吧，你觉得怎么样?他做出腐化灰谷还有其他的一些恶劣行为令我反胃-只要一想到有个巫师在外面进一步的使情况恶化就使我想吐。我们一定要叫他付出代价。', '你必须摧毁护腕才能干掉那些水元素，所以你可能不太容易找齐那些具有特定资讯的护腕。如果你还没有收集到所有护腕的话，可以用自己找到的护腕与别人交换来集齐你所需的护腕。', '', '去找灰谷银风避难所的哨兵维尔莉妮·星坠。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1017, '召唤者', '这世上只有一个法师——就是那个躲在贫瘠之地的亡灵法师——才能够召唤出那么多的水元素来。也只有他这样白痴的家伙才会想要这么做。现在这个名叫萨瑞鲁斯·法伯尼的蠢货恐怕正坐在鬼雾峰顶嘲笑我呢。$B$B$n，你必须深入敌人的领地，干掉这个卑鄙的家伙。关于这家伙的白痴行为我已经听说得够多了。我们要让他知道挑衅我们哨兵部队会有什么样的下场。$B$B杀了他，带他的人头回来见我。不过你得当心，部落那边可是危机四伏的。', '干掉萨瑞鲁斯·法伯尼，把他的徽记交给银风避难所的哨兵维尔莉妮·星坠。', '现在，我再也不用看到他那经年挂在脸上的、让人作呕的假笑了。你做得很好，$N。拿着这个，艾露恩之光，当你在战斗中将要落败甚至快死的时候，就喝下它，艾露恩会挽救你的生命。', '完成了吗?萨瑞鲁斯.法伯尼死了吗?', '', '去找灰谷银风避难所的哨兵维尔莉妮·星坠。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1020, '奥雷迪尔的药剂', '$N，我合成了一种药剂，相信它能帮助这个饱受折磨的孩子。把药带到阿斯特兰纳去，交给这孩子的父亲皮尔图拉斯·怀特姆恩。$B$B顺着这条路向南走，然后向东转，就能看到阿斯特兰纳了。', '把奥雷迪尔的药剂交给阿斯特兰纳的皮尔图拉斯·怀特姆恩。', '奥雷迪尔送来的?$B$B他对草药和医疗相当精通，这副药剂在我快要绝望的时候给我带来了一线希望，谢谢你……', '很抱歉，我实在没有时间再和你聊天了。我的孩子蕾拉就快要病死了!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1022, '狼嚎谷', '尽管我们投入了大量的物资和人力想要将剩馀的恶魔赶出北方的费伍德森林，但是看来似乎并没有什么效果。我们只能把大部分的恶魔御于灰谷之外。$b$b在北方的费伍德森林附近，有一群神秘的狼人占据了麦尔莎迪丝神殿的废墟。他们令人心颤的嗥叫使得那个地区得了个“狼嚎谷”的名字。保存在神殿中的麦尔莎迪丝之书也许能让我们知道这些狼人出现在这里的原因。', '到狼嚎谷去，研究一下麦尔莎迪丝之书，然后向林歌神殿的哨兵梅丽瑞亚·霜影复命。', '麦尔莎迪丝之书非常奇怪，它所记录的那些事件，它所展现的那些事件……没有人能真正理解究竟为什么会是那样……$B$B不过有一点非常清楚的是，女祭司维琳德.星歌收到的东西-也就是这个月神镰刀-需要进行更多的研究。', '麦尔莎迪丝之书是件神秘的物品，它已经不是传统意义上的书了。这本书的每一页都受到了麦尔莎迪丝本人的佑护，书中记载着重大的事件。$B$B我很难具体解释，等你到了神殿之后自然就会了解了。', '', '去灰谷找林歌神殿的哨兵梅丽瑞亚·霜影。', '查阅麦尔莎迪丝之书', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1023, '莱恩的净化', '在检查泰洛尼斯的遗物时，你发现了一本完好无损的日记。$B$B你收起日记之后就离开了泰洛尼斯的尸体。$B$B接下来你唯一要做的事情就是找到泰洛尼斯一直在寻找的那颗宝石。莱恩曾经提到过宝石就在这个地区，也许在鱼人的手里……', '找到发光的宝石，连同泰洛尼斯的日记一起交给阿斯特兰纳的莱恩·狼行者。', '太糟了，$N。泰洛尼斯死了?!我们要为他哀悼，但现在我们必须集中全力做完应该做的事情，我会尽快派一些哨兵去找回泰洛尼斯的遗体的。$B$B你拿着泰洛尼斯的日记和他一直在寻找的宝石，那么你认为自己能够继续他的任务吗?不要让他白白地牺牲。', '啊，欢迎回来，$N。', '', '去灰谷找阿斯特兰纳的莱恩·狼行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1024, '莱恩的净化', '你得自己去进行研究，但是从泰洛尼斯的记录来看，你下一阶段的工作将是去寻找达图尔所造的魔棒的其它部分。我建议你从伊瑞斯湖东部的月亮井开始。如果你准备好了，就沿着这条路越过环绕着伊瑞斯湖的群山，然后向北走。$B$B一个名叫莎尔蒂恩的树妖会在那里为你提供向导。记得带上宝石，如果莎尔蒂恩愿意帮你重造魔棒，她肯定会需要这块宝石的。', '在东北方的月亮井旁找到莎尔蒂恩。', '哦，莱恩派你来的?问题一定很严重吧。我能帮你些什么呢?', '嗨，你好吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1025, '先发制人', '在你出发去月亮井之前，如果你愿意测试一下自己能力的话，我还有另外一项可以造福灰谷的任务交给你。$B$B沿着这条路一直向东走，在靠近弗伦河的地方有一些熊怪频频攻击过路的旅客。他们扭曲的灵魂只有在给别人带来恐惧时才能得到抚慰，他们疯狂的心智只有在啜饮无辜者的鲜血时才能得到满足。$B$B帮助哨兵部队守护我们的领地，去对付那些熊怪吧，以血还血，以牙还牙。$B$B我认为他们的营地应该在这条路的南方……你要多加小心。', '杀掉污林部族里的1个污林卫兵、2个污林巨熊、10个污林萨满祭司和12个污林战士，然后回到阿斯特兰纳向莱恩·狼行者复命。', '你做得很好，$N。谢谢!', '熊怪并非一直是我们的敌人，$N。可是时代不同了，在这片黑暗的森林里，和平早已不复存在。', '', '去灰谷找阿斯特兰纳的莱恩·狼行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1026, '莱恩的净化', '情况越来越糟糕了。$B$B莱恩的猜测是对的，我很了解达图尔的发明以及这个地区的树人——至少我曾经了解。树人们现在开始堕落了，他们的灵魂变得扭曲。$B$B如果你想要找到魔棒的下一块碎片的话，就必须先找到一把木制钥匙，用它来打开锁住这块碎片的箱子。$B$B这把木制钥匙就在东北方的费伍德森林附近的一个树人手里。得到了钥匙之后，你就可以顺着这条路向西走，在靠近费伍德森林的边界地区寻找一小块林间空地……箱子就藏在那里的某个地方。', '找到木制钥匙和一段达图尔的魔棒，然后回到月亮井的莎尔蒂恩那里。', '很高兴见到你回来，$N。', '树人的堕落让我感到十分不安，真希望我能为他们做些什么。', '', '去找灰谷的莎尔蒂恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1027, '莱恩的净化', '魔棒的最后一段是由朵丹尼尔的德鲁伊保管的，但是我不清楚他们把它藏到了什么地方。很抱歉，恐怕我只能帮你这么多了。$B$B我所能告诉你的就是：顺着这条通向贫瘠之地的路一直走下去，这群德鲁伊隐居在路的东边，可是他们也没法帮助你，因为他们最近被杀死了……那是一段我不愿再回忆的过去。$B$B如果你找到了最后一段魔棒，就把它带回来交给我，我会帮你修复魔棒的。', '找到达图尔的魔棒的最后一段，然后回到月亮井旁的莎尔蒂恩那里。', '你找到最后一段啦?你太棒了……莱恩也会很高兴的。$B$B我想我们该看看如何修复它了，不是吗?', '$N，你找到魔棒的最后一段了吗?', '', '去找灰谷的莎尔蒂恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1028, '莱恩的净化', '这是完整的魔棒，$N。修复它并不难……难的是找到神殿，并再次赋予它能量。$B$B对于像你这样已经完成了这么多艰巨工作的人来说，只要稍加留意和努力，这个任务也不会太难。$B$B从这儿向东南方走——那里人迹罕至，所以要多加小心——路上记得留意正北方。神殿就隐藏在围绕着那片林地的山峦中。$B$B到了那儿之后，把魔棒放在神殿中……剩下的就交给魔法去完成吧，祝你好运。', '找到隐藏的神殿并给达图尔的魔棒重新注入魔力。', '光芒退去以后，你看到那根已经恢复了魔力的魔棒躺在神殿的水池中。', '你能感受到一种微妙而又强大的力量在神殿和周围的森林中荡漾。$B$B当你把魔棒放入神殿之后，轻柔的低鸣声萦绕于耳，神殿开始泛出亮光……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1031, '塞纳留斯的树枝', '安妮莉亚把手放在你的肩头上，慢慢地把你拉近她的身边。她艰难地喘着气，抬手指向北方的拱门。在她的气息渐渐变得微弱，眼睛慢慢地闭上之前，安妮莉亚留下了最后一句话：“被他夺走了……加萨里斯……”她临终时还在想着要让塞纳留斯的树枝回到树妖的手中。', '杀掉加萨里斯，把塞纳留斯的树枝交给林歌神殿的伊莉亚娜。', '安妮莉亚死了?不……那是不可能的!就在前几天，我们还在林中奔跑嬉戏。$B$B我想那些日子不会再有了……', '你找到她们了吗?安妮莉亚有没有说什么?她现在在哪儿?', '', '去灰谷找林歌神殿的伊莉亚娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1032, '猎杀萨特！', '我不敢相信安妮莉亚居然离我而去了……我们以前天天都在森林里一起游玩。我感觉很……难过。$B$B也许有一个办法可以让我感觉好一点。请你去杀了那些从我身边夺走安妮莉亚的萨特！请你把它们的角拿给我作为证明，我会永远感谢你的。', '收集16支萨特的角，把它们交给林歌神殿的伊莉亚娜。', '谢谢你，亲爱的$r。你所做的这些应该会让她的灵魂感到欣慰的。', '请帮我为安妮莉亚复仇!', '', '去灰谷找林歌神殿的伊莉亚娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1033, '月神之泪', '我曾把挽救蕾拉的生命的希望寄托于奥雷迪尔的医术上，可让我担心的是，那只能延缓疾病在我孩子体内的蔓延而不能让她彻底痊愈。我们一定要找到更有效的药物！感谢奥雷迪尔，他告诉我如果第一种治疗方法不能起作用的话，还有下一步的治疗方法。$B$B有一种名叫月神之泪的特殊的石头，只有在阿斯特兰纳东部的伊瑞斯湖中心的小岛上才能找到它。奥雷迪尔说这块石头能治疗一切疾病……求求你，$N，帮我找来月神之泪，祈求它能结束我孩子的痛苦。', '找到月神之泪，把它交给阿斯特兰纳的皮尔图拉斯·怀特姆恩。', '哦，你找到它啦!我要马上让孩子服下月神之泪，希望它能治好我的孩子。$B$B谢谢你!谢谢你，$N!', '$N，你找到伊瑞斯湖了吗?你拿到月神之泪了吗?', '', '去灰谷找阿斯特兰纳的皮尔图拉斯·怀特姆恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1034, '星尘废墟', '月神之泪减轻了我女儿的一些病痛，感谢艾露恩，她发恶梦的次数也大大减少了。可是……她仍发着高烧。$B$B奥雷迪尔告诉我，在南方的星尘废墟中可以找到一种结晶的星尘，或许它能缓解蕾拉的高烧。请你帮我收集一些星尘吧。$B$B愿艾露恩保佑你速去速回。', '收集5份星尘，把它们交给灰谷的皮尔图拉斯·怀特姆恩。', '你找到星尘了!我要马上把它们制成药，给蕾拉降烧。$B$B再次感谢你，$N。没有你的帮助，我真的无法想象我的孩子会怎样。', '你得到星尘了吗，$N?', '', '去灰谷找阿斯特兰纳的皮尔图拉斯·怀特姆恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1035, '坠星湖', '蕾拉的高烧退了，但她还是很虚弱。我想她很难靠自己的力量康复，我们可能要借助月亮石的魔力才能让她痊愈。$B$B过去我们常在东南部的坠星湖搜集月亮石……但是沼泽兽来了之后就不行了。$B$B这群野兽的领袖是一个沼泽兽智者，它成堆成堆地收集所有从天上掉下来的月亮石。现在，你得从沼泽兽智者那里取回一枚月亮石。$B$B要达到这一目的，恐怕你必须先杀了那个沼泽兽智者。', '从沼泽兽智者那里取回一枚陨落的月亮石，并把它带给阿斯特兰纳的皮尔图拉斯·怀特姆恩。', '太谢谢你了，$N，你救了我的女儿!我就知道月亮石的魔力能帮助我女儿痊愈!$B$B我真不知道该怎么感谢你，不过……请拿着这个，这是除了蕾拉之外，我身边最宝贵的财产了。', '你干掉沼泽兽神谕者了吗，$N?如果是的话，请把陨落的月亮石给我。蕾拉已经奄奄一息了!', '', '去灰谷找阿斯特兰纳的皮尔图拉斯·怀特姆恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1038, '维琳德的日记', '你是由麦尔萨迪斯之书中得知这一切的？我认为你应该去检查一下她的所有物品，虽然那样做可能不太妥当。用这把钥匙可以打开她放在哨兵小屋里的储物箱。她把平时的工作都记录了下来，因此你从她的日记中应该可以了解到很多事情。$b$b我应该告诉你，哨兵们认为她是因为某些特殊的原因而离开的，她随时都有可能再回来。女祭司过去做过很多让我们对她倍加信赖的事情。', '在维琳德的箱子里搜寻她的日记，把日记连同钥匙一起交给达纳苏斯的塞恩提尔·刃纹。', '看来维琳德的失踪越来越麻烦了。直到现在，我也无法相信她会遭遇不测。$B$B$N，既然你对这件事有兴趣，那么我希望能得到你的帮助。', '你找到了什么?', '', '去达纳苏斯找战士区的塞恩提尔·刃纹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1043, '月神的镰刀', '你的故事听上去不像是假的……我不能完全理解你的动机，不过如果你想要除掉暮色森林的狼人，我就不需要了解这些。$b$b在南方有一座矿山，很多狼人在那里出没……天知道他们是从哪里冒出来的，不过据我们所知，他们最早就是在那里出现的。$b$b去忙你的吧，不过如果你有什么重要消息，请一定要告诉我。我们需要所有能帮我们对抗邪恶的信息。', '去找关于月神镰刀的消息，然后回到夜色镇见乔纳森·卡尔文。', '真是个有趣的故事，$N。虽然卡尔文系列还没法找出这一切麻烦的根源并将其彻底铲除，不过我们会尽力遏制暮色森林的狼人势力。$B$B我已经吩咐卡洛尔把这个当作首要任务了。', '不做好准备就贸然闯进森林是很危险的。紧紧握住你的武器，时刻保持高度警惕，否则你一旦进入这片充满邪恶的森林，就可能永远出不来了。', '', '去暮色森林找夜色镇的乔纳森·卡尔文。', '寻找月神镰刀的下落', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1045, '莱恩的净化', '暗夜精灵是个历史悠久的种族，但是他们的傲慢毁灭了他们的世界。现在，这样的傲慢也毁掉了我们的生活，一切都失控了……$B$B我把许多灾难归咎于那些精灵们，但是我们也应该为自己的行为承担责任。即使在堕落之前，我们也具有非常邪恶的一面。$B$B兰恩·血牙就是这种邪恶面的体现。对权力的渴望，无尽的物欲……现在的堕落只会让他更加强大。我的心中燃烧着对这些精灵的怒火，但我对他们的后代并无恶意，我们也必须管教好自己的儿女，让他们不再重蹈我们的复辙……', '杀死兰恩·血牙和4个血牙保镖，并拿到兰恩·血牙的徽记，然后向密斯特拉湖附近的克罗尔格复命。', '你干得很好，我的朋友。$B$B森林仍然受污染着，但至少我们向着恢复它往日荣耀的目标迈出了一小步。如果你愿意再回来找我的话，我会非常乐意和你在一起的。$B$B多多保重。也许我们的部族将在和平时期再次聚会。', '你杀掉兰恩了吗，我的朋友?$B$B他甚至没有资格去憎恨夜精灵。他的仇恨比我更加强烈，但他的思想已不再受他自己的控制。对于森林中的所有生物而言，他都是一个巨大的威胁。', '', '去灰谷找密斯特拉湖的克罗尔格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1046, '莱恩的净化', '回到你自己的部族去吧，让他们知道你在这里取得的胜利。$B$B向他们展示你的战利品，并享受胜利的荣耀吧……', '把兰恩·血牙的徽记交给阿斯特兰纳的莱恩·狼行者。', '那么，这是灰谷里最凶猛的熊怪的颅骨?$B$B我对你的才能真的感到很满意，$N。哨兵部队怎样感谢你都是不够的。希望以后你能够继续保护我们的人民。$B$B我将会将这块颅骨和达图尔的魔棒放起来供人瞻仰。$B$B泰洛尼斯会为此感到自豪的。再次感谢你。', '哨兵部队在灰谷竭尽全力地战斗着，但是多亏了像你一样的$r，我们才保住了这片原本就属于我们的土地。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1048, '深入血色修道院', '当黑暗女王陛下将主要精力放在对付北方的天灾军团时，我更关心那些身边的问题。$b$b毫无疑问，有一群自称为血色十字军的人类渣滓正在威胁着我们的领土。提瑞斯法林地当前正被这群红蚂蚁逐渐侵蚀和占据。$b$b到修道院里去干掉大检察官怀特迈恩与她手下的那些军官，$c。', '杀掉大检察官怀特迈恩、血色十字军指挥官莫格莱尼、血色十字军勇士赫洛德和驯犬者洛克希，然后向幽暗城的瓦里玛萨斯回报。', '你为黑暗女王作出了卓越的贡献，$C。我给你的任务可不是一件鸡毛蒜皮的小事。$B$B我们将永远铭记你对被遗忘者的绝对忠诚和你在战斗中表现出来的坚毅不拔。', '或许我没有把命令说清楚，$C。我要你去干掉高阶审判官怀特迈恩，把她那张厚脸皮也给我剥下来。$B$B再去杀掉血色十字军指挥官莫格莱尼，那个该死的狂热者。还要杀掉血色十字军勇士赫洛德。最后，别忘记也要送驯犬者洛克希上路，顺便把他的那些蠢狗都给我剁成肉酱。$B$B现在就去吧!', '', '去幽暗城找皇家区的瓦里玛萨斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1049, '堕落者纲要', '大地之环对那些被遗忘者开诚布公，但是谁又知道那些亡灵们对我们到底有什么意图？$b$b虽然被遗忘者与我们结了盟，但他们从来就以精于欺诈而闻名。我们的这个盟约实在是太草率了，也许凯恩会睿智地留意到来自奥格瑞玛的警告。$b$b在血色修道院深处，那些疯狂的人类狂热者们守卫着《堕落者纲要》。虽然这帮家伙是如此的疯狂和顽固，但他们的研究也许会对我们有些用处。', '从血色修道院里找到《堕落者纲要》，把它交给雷霆崖的圣者图希克。', '《堕落者纲要》!我都快要开始怀疑这本书到底是否真的存在了!$B$B你为雷霆崖的牛头人做出了杰出的贡献，$N。我们永远不会忘记你的奉献。', '凯恩是一个勇敢而高贵的领袖，我会终生遵循他的领导，但是我对这里的整个高层并不是很信任。$B$B一旦我有机会收集所有可以利用的知识，就能为酋长创建一个成熟的议会。$B$B你去过提瑞斯法林地了吗?进过血色修道院了吗?《堕落者纲要》只是这错综复杂的谜团中的一小部分罢了……', '', '去找雷霆崖的圣者图希克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1050, '泰坦神话', '未来是已经命中注定了的！我们的命运就像雨点落入大海一样无可改变。$b$b不过研究过去也许可以让我们预见未来，并提前做好一些准备。$b$b在灾难降临在洛丹伦之前，提瑞斯法林地中有一处藏有许多书籍的地方——老修道院的图书馆，据说有一本《泰坦神话》就收藏在哪里。$b$b把它给我拿回来，也许我们可以一起揭开过去的秘密。', '从修道院拿回《泰坦神话》，把它交给铁炉堡的图书馆员麦伊·苍尘。', '你挽救了这本圣书!$B$B想必你为了拿到这本书吃了不少苦头吧，但你的成功会让铁炉堡的矮人受益匪浅。$B$B我代表探险者协会谢谢你，$N。', '修道院过去曾是训练圣骑士的学院。它曾经是光明的要塞，但现在却落到了血色十字军的狂热分子手上。$B$B十字军自以为有一个崇高的目标，他们要清除不死生\r\n物的瘟疫，净化洛丹伦的土地，但是现在他们脑子里只有疯狂的臆想，成了所有人的敌人。$B$B把《泰坦神话》给我带回来，这样我就可以研究它并把它收藏在铁炉堡里了。$B$B修道院的图书馆已经被废弃，不再适合摆放这样的珍宝了。', '', '去铁炉堡找探险者大厅的图书馆员麦伊·苍尘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1051, '沃瑞尔的复仇', '虽然我现在是个独立的亡灵，但我恐怕无法再为黑暗女王效力，因为我觉得支撑我生命的力量都被毁了。$b$b这一切都是那个审讯员韦沙斯造成的！他折磨了我好几个星期，还拿走我的结婚戒指送给了他的妻子。那个混蛋！$b$b复仇……我要复仇！$b$b那个自负的笨蛋总是吹嘘他的宝贝老婆南茜多么多么娇艳，她就住在洛丹米尔湖一带，去杀了她，把我的结婚戒指还给我那在塔伦米尔生活的妻子莫尼卡。$b$b请帮助我完成这最后的愿望……', '把沃瑞尔·森加斯的结婚戒指还给塔伦米尔的莫尼卡·森古特斯。', '沃瑞尔真悲惨，他是个很好的丈夫……$B$B那些可恶的人类!$B$B沃瑞尔走了，再也不能享受永生不死的权利。但现在至少你替他报了仇，我也可以从中得到些许安慰。谢谢你。$B$B现在请让我哀悼吧……', '你有什么事吗，陌生人?', '', '去希尔斯布莱德丘陵找塔伦米尔的莫尼卡·森古特斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1052, '血色之路', '我们血色十字军拥有着从壁炉谷到提瑞斯法林地一线的许多要塞。这些要塞构筑了保护洛丹伦大陆的主要防线，我们为此感到十分自豪。$b$b你在南艾泽拉斯对抗亡灵的行动已经证明了你的价值。但真正的威胁仍然来自正在洛丹伦北部蔓延的瘟疫。$b$b到一处叫做南海镇的城镇去，在那里找到一个名叫莱雷恩的十字军战士，把这封由我亲自密封的表彰信交给他，他将会护送你转至充满荣耀的血色修道院。', '将安东修士的表彰信带给南海镇的虔诚的莱雷恩。', '安东修士还在暴风城里为血色十字军歌功颂德?天哪……', '你是谁?你有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1053, '以圣光之名', '我曾怀着荣耀、忠诚、自豪的心情加入了血色十字军。我曾坚信他们有着将艾泽拉斯的所有亡灵生物都消灭干净的崇高理想。$b$b但自从我在提瑞斯法林地的修道院里待了一阵之后，我意识到他们现在已经几近疯狂了。他们认为除了那些穿着十字军制服的人之外的所有人都已经感染了瘟疫，而任何被怀疑感染上瘟疫的无辜者都要遭到他们无情的拷打。$b$b以圣光的名义，血色十字军必须被铲除掉。你，$n，必须消灭这个疯狂的组织。', '杀死大检察官怀特迈恩，血色十字军指挥官莫格莱尼，十字军的勇士赫洛德和驯犬者洛克希并向南海镇的莱雷恩复命。', '追随圣光的人从不畏惧死亡，我们必须接受这个现实，为了王国与这个世界的未来，这样的牺牲是不可避免的。$B$B你在修道院中所做的一切将会拯救更多的无辜性命，$N。我向你的坚毅和勇敢致敬!', '除非那些高层官员被铲除，否则修道院中的堕落就不会停止。$B$B以圣光的名义，去杀掉高阶审判官怀特迈恩，血色十字军指挥官莫格莱尼，十字军的勇士赫洛德和驯犬者洛克希。一旦除掉了他们，也许十字军将会重新回归他们神圣的创立宗旨。那时十字军才会成为一支无坚不摧的正义力量。$B$B从南海镇出发吧，去完成你的使命!', '', '去希尔斯布莱德丘陵的南海镇找虔诚的莱雷恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1054, '解除威胁', '从阿斯特兰纳出发，一直向北走，你能看到许多蓟皮熊怪。我的侦察兵向我报告说，熊怪的数量在最近几个月里成倍地增加。如果它们的数量变得足够多的话，就可能会直接向阿斯特兰纳发起攻击。$B$B你能杀掉多少熊怪就杀多少，但你要把他们酋长的徽记给我带回来作为证明……$B$B我会留在阿斯特兰纳等你的消息，愿艾露恩与你同在。', '把达尔·血爪的徽记交给阿斯特兰纳的莱恩·狼行者。', '好样的，$N。$B$B长期以来，我们一直在受到熊怪的威胁。希望这次的打击可以让它们收敛一些。', '熊怪的堕落让灰谷已经很难重现往日的荣耀了。', '', '去灰谷找阿斯特兰纳的莱恩·狼行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1057, '夺回焦炭谷', '你应该能猜出来，身为森林之灵的守护者的我为什么会如此愤怒。$b$b你翻越了无数山岭来到这里，一路上你应该已经看到在这片土地上都发生了些什么。贪婪正在将这神圣的山脉引向毁灭的深渊。$b$b南方的焦炭谷正在遭受那群贪得无厌的机械化工业大军的荼毒。更糟的是，那里的鹰身人竟然拒绝让我们进入那里抚慰大地受到的创伤。$b$b把这群肮脏的鹰身人给我赶出去，$n！', '石爪峰的守护者奥巴格姆要求你杀死7个血怒鹰身人、7个血怒伏击者、7个血怒杀戮者和7个血怒游荡者。', '现在血怒氏族算是遭到了毁灭性的打击，我们也终于可以开始工作了……', '想要让焦炭谷恢复成过去那样的茂盛的森林，我们就得付出非常大的努力。$B$B把谷中的那些肮脏的鹰身人都清除掉，$N!只有这样，我们才能让焦炭谷重归自然的怀抱。', '', '去石爪山脉找石爪峰的守护者奥巴格姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1058, '金吉尔的森林魔法', '我实在是太兴奋了！$b$b笼子里的三个小精灵！但我们该对我们这些整天都要抱着树的小朋友们做些什么呢？有了！让他们尝尝那个……他们是怎么叫它来着……“森林魔法”的滋味吧！$b$b我首先需要一些苔藓分泌出来的石爪苔液，然后你再从那些凶悍的夜行虎身上给我搞点胡须来。啊，对了，还要许多的巨角鹿眼珠子。还有还有，差点忘记了，还要一块灵龙的鳞片！$b$b这些东西都能在石爪峰上找到，动作快点，$n，我要准备施展这森林魔法了！', '玛拉卡金的巫医金吉尔需要5瓶石爪苔液、5根夜行虎须、30颗巨角鹿的眼球和1块灵龙的鳞片。', '哈哈，你说这帮小妖精将会有多开心啊!靠这个特殊的东西，我们就可以让他们以为自己还在家里呢。', '看看我们这群可怜的精灵朋友，他们都被关在这里，没法在森林里玩耍啦!$B$B我要的那些苔液呢?夜行虎的胡须呢?灵龙的鳞片呢?$B$B当然，我还需要很多眼球!没足够的眼球是无法施展强大的森林魔法的!', '', '去石爪山脉找玛拉卡金的巫医金吉尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1060, '写给金吉尔的信', '$n，你能活到现在就足以证明你是个幸运的家伙，我这里有些东西要让你看看。$B$B鹰身人的老家离贫瘠之地并不远，她们都来自一个叫做石爪山的地方，从这里往西北方向走很远才能到达那里。虽然那很可能是片危险的地方，但我还是要你帮我把这封信带给一个住在那儿的老朋友，一个叫做金吉尔的巫医。$B$B如果他听说塞瑞娜·血羽已经死了的话一定会很开心的，而且，我想你会慢慢发现石爪山其实是个有趣的地方。', '把达索克的亲笔信交给金吉尔，他住在石爪山的洞穴中。', '啊，达索克的亲笔信!这么多年都没有收到他的来信了。$B$B如此说来，塞瑞娜·血羽也死了?这真是个好消息，我还记得我的朋友洛克汉和那个疯疯癫癫的摩克纳萨尔跑去杀她姐姐时的情景。啊，这似乎让我又回到了年轻的时候，我像你一样年轻的时候啊，那可真是……', '你看起来是个不太面善。找我有什么事?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1062, '地精侵略者', '由地精运营的风险投资公司进入了石爪山西部，开始无节制地砍伐树木、焚烧森林。森林中的山灵们已经几乎要被地精带来的痛苦与愤怒逼疯了。我们必须阻止风险投资公司的恶行！$B$B向西进入巨木谷，你可以在那里找到正在工作的地精和他们的仆从——告诉他们，部落决不会允许他们把石爪山弄得一团糟。用他们最容易理解的语言——暴力——来和他们沟通……', '杀死15个风险投资公司樵夫，然后向石爪山与贫瘠之地交界处的希雷斯·碎石复命。', '真是大获全胜，$N。$B$B我们可能最终还是会需要牛头人长老们的智慧来安抚石爪山中的精灵，但……$B$B除掉风险投资公司的那些人的确是个好的开始。', '巨木谷就在西北边，$N。去吧。把恐惧深深地烙入这群破坏大地的哥布尔心里吧!', '', '去石爪山脉和贫瘠之地的交界处找希雷斯·碎石。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1065, '塔伦米尔之旅', '为了把风险投资公司赶出石爪山，我们就必须采取极端的措施。极端的，但是不用流血。$B$B我的一个同事可能有我们需要的工具，他叫林度恩，就住在希尔斯布莱德丘陵的塔伦米尔镇，那地方在遥远的洛丹伦地区。$B$B要去希尔斯布莱德的话，就要先乘飞艇到我们的首都幽暗城，然后往北到提瑞斯法林地，再往西南进入银松森林，最后再转向东南才能到希尔斯布莱德丘陵。$B$B找到林度恩，把这封信带给他，里面详细叙述了我们需要什么样的帮助。', '把扎玛的信带给塔伦米尔的林度恩。', '札玛的信?她的要求一定很紧急，所以才会要你不远千里来找我。让我们看看是怎么回事吧……$B$B啊，真棒!我知道该怎么做了!', '你好啊，有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1066, '无辜者之血', '我要制造一种毒药，给风险投资公司的那些暴力分子一点教训，让他们不再那么嚣张。这样就能解决部落在石爪山的问题了，不是吗？$B$B不过要制造毒素的话，我还需要一些无辜者之血，这种东西很难找。$B$B幸运的是，这个地区的人类强盗组织——辛迪加组织雇佣了一些暗影法师……这些法师为了自己的邪恶目的专门收集无辜者之血。$B$B到东南方的敦霍尔德城堡去，你可以在那里找到不少辛迪加暗影法师。', '为塔伦米尔的药剂师林度恩收集5瓶无辜者之血。', '很好!我想辛迪加对你来说应该是小菜一碟吧。$B$B我说过，无辜者之血是不容易拿到手的。我们很走运，辛迪加的暗影法师已经为我们完成了这个困难的工作。$B$B等一会儿，让我来配制药剂……', '你找到辛迪加暗影法师了吗?从他们那儿收集到血液了吗?', '', '去希尔斯布莱德丘陵找塔伦米尔的药剂师林度恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1067, '返回雷霆崖', '毒药做好了。用它来对付风险投资公司的话，一定能让我们无往而不利，甚至可能还会有一些意想不到的效果。我得说，看见我的研究成果能在战场上发挥作用真是太令人兴奋了！$B$B不过在使用之前，你得先把它拿去给药剂师扎玛。她会想出让毒药发挥最大效果的方法。', '把林度恩的毒药交给雷霆崖的药剂师扎玛。', '药剂师林度恩的毒药?很好。我了解林度恩，他的毒药对风险投资公司一定会有效果……', '你回来了，$N。你从药剂师林度恩那儿给我带了东西来?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1068, '伐木机', '萨满祭司的灵魂魔法与德鲁依的自然魔法之间有着一些共性，因此，我们萨满祭司也能聆听到石爪山山灵的哭诉。它们的大部分话语我已经不记得了，但有一件事……一个景象，却一直清晰地出现在我脑海之中……$B$B我记得我看到两台人型的巨大机械在巨木谷西北的狂风峭壁之中以飞快的速度砍伐着树木，你必须去阻止这些金属怪兽的疯狂行径！$B$B在我脑海中的景象里，那两台机器上分别标有这样两个奇怪的标志：$B$BXT:4和XT:9。', '杀死伐木机XT:4和XT:9，然后向石爪山与贫瘠之地交界处的希雷斯·碎石复命。', '你摧毁了XT:4与XT:9，安抚了石爪山的许多山灵，$N。我想遭受了重大损失的风险投资公司应该会因此从石爪山撤离。$B$B但是如果他们仍然要继续作恶的话，恐怕这个地区将彻底变成一片不毛之地。', '树灵们正因为它们的同胞被无情屠戮而恸哭，$N。你必须马上把伐木机XT:4和XT:9毁掉，否则，恐怕石爪山将永远不得安宁。', '', '去石爪山脉和贫瘠之地的交界处找希雷斯·碎石。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1069, '深苔蜘蛛的卵', '煎蜘蛛卵是藏宝海湾的时尚菜肴。问题是……藏宝海湾的蜘蛛卵已经断货了。$B$B我发誓这绝对是个赚钱的好机会！$B$B在风剪峭壁——就是石爪山的西北地区——那里有一种深苔蜘蛛，如果你能帮我弄来一些深苔蜘蛛的卵的话，我一定会付给你一大笔钱！$B$B这些蜘蛛最喜欢在树荫下爬行……但可恶的风险投资公司砍掉了它们赖以生存的大树！$B$B不过，你还是到风剪峭壁去找找深苔蜘蛛吧，它们的卵在有树的地方还是很多的。', '收集15颗深苔蜘蛛的卵，把它们交给棘齿城的麦伯克·米希瑞克斯。', '搞定!谢谢!$B$B我会把这些蜘蛛卵交付给迪兹维格，然后用船运到棘齿城去。我已经嗅到钱的味道了!$B$B$N，这是你的分成。没有你的帮助，我肯定做不成这笔买卖。', '$N，你找到蜘蛛卵了吗?我已经跟码头管理员迪兹维格签了送货合同了。', '', '去贫瘠之地找棘齿城的麦伯克·米希瑞克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1071, '侏儒学者', '你看，$N，我也是伟大的魔法、化学和工程学研究会的成员，我的目标……嗯嗯，我的使命，便是好好教导这帮暗夜精灵们，让他们知道魔法、化学和工程学的融合便可拯救他们的森林！$B$B但这是一场艰苦的战斗，地精们的繁殖速度简直就像兔子一样。我甚至没有时间去搞新的发明！$B$B我需要些时间来进行计划和组织。但这需要你的帮助，去帮我把东边狂风峭壁那里的绿皮玩意们干掉一些。', '杀掉10名风险投资公司樵夫和10名风险投资公司砍树工，然后向石爪山的加克希姆·尘链复命。', '感谢你的帮助，$N。你回来的正是时候。$B$B我刚刚想出来一个完美的计画……大爆炸。不，这不是全部计画，这只是一部分。$B$B你看，我要用这高爆爆裂物来好好吓唬吓唬那群哥布尔―不用担心，这东西不是常人所想的那么危险。我只要在沿着山边的几个关键点放上爆裂物就能起到很好的作用，然而，我已经好几天没有得到补给了……', '你已经完成任务了，$N?', '', '去石爪山脉找蛛网小径的加克希姆·尘链。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1073, '失职+药剂=快乐', '哈哈哈……你来搞硝酸甘油炸药是为了阻止地精们破坏森林？！$B$B我现在不关心你和加克希姆到底熟不熟了……我可以把这玩意给你，谁管最后是你还是他们被炸成碎片！$B$B但是还有一个小问题，我现在身边没有成品。$B$B只要你把我需要的材料带给我，我就可以马上给你做一些。$B$B但在这之前，至少你得证明你在炼金术方面不是个白痴。', '给铁炉堡的洛玛克·链带拿去4瓶初级法力药水和2瓶初级坚韧药剂。', '干得好。$B$B要不是我事先已经知道了你的身份，陌生人，我一定会以为你是个炼金师。好，好……这世界，并不只是由剑与魔法组成的，你明白吗?', '我没这些药水便配不出一丁点硝酸甘油炸药来……这些原料在制作中是十分关键的。', '', '去找铁炉堡的洛玛克·链带。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1074, '失职+药剂=快乐', '去吧，陌生人。小心点……这玩意很容易被引爆的。$B$B如果你真是加克希姆的朋友，别忘了替我跟他问个好。如果不是的话，那么就祝你被炸飞吧。', '将硝酸甘油炸药带回石爪山，交给加克希姆·尘链。', '你的任务完成得完美无缺，$N。$B$BNG-5在我的设计里是引爆火药车的必备品。$B$B什么?对，火药……火药车，就是一车火药的意思。这是最好的诱饵，我跟你说……你就等着看吧。', '啊，很好，你回来啦。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1076, '西部荒野中的恶魔', '啊，有了。一个传信法术……我相信你需要的就是这种效果。$B$B我会为你做一张抄写有这道法术的卷轴，不过要完成它，我得先弄些尘魔的残骸来。$B$B在我找到其它的材料之前，你能到西部荒野去给我抓一只这种邪恶的生物回来吗？它们的确很危险，但我肯定，如果你想为加克希姆的实验做点什么贡献的话，没什么是你不能搞定的。$B$B我会在这里等你回来。', '将尘魔的残骸带回给暴风城的科林·玛林。', '给我点时间，我马上就会把卷轴给你抄写完成。', '你好，$N。你找到我所需要的材料了吗?', '', '去找暴风城的科林·玛伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1077, '给加克希姆的特快专递', '拿着这个吧，$N。这张卷轴会满足你的要求的。$B$B当你再见到加克希姆的时候，记得替我向他问好。我正等着听到你们凯旋的消息呢。$B$B再见。', '将通讯卷轴交给石爪山的加克希姆·尘链。', '太完美了，$N!干得好呀!$B$B只消将这道法术和NG-5配合使用，便能进行远端引爆了!$B$B现在我们就可以分布他们的注意力，让你能偷偷潜入到他们那里去，给我们偷来风险投资公司的函件和工程计画。$B$B这肯定会打乱他们的森林砍伐的。', '哈哈!你回来了!拿到了吗?拿到那法术了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1078, '完鳞归玛伦', '旅行者们一直在问我有关石爪山的事情，看来那里已经成为一个公认的最佳冒险场所了——当然前提是你没有在寻找双足飞龙、元素生物，也没有跟风险投资公司扯上关系。$B$B在石爪山脉深处的焦炭谷中还居住着一群披着厚重鳞片的蜥蜴。把那些鳞片磨成灰就是我施放一些法术所必需的原料。$B$B如果这些蜥蜴还活着的话，你能不能帮我搞一些它们的鳞片来？$B$B注意点时间，不用太着急，而且我会付给你不错的酬劳。', '给暴风城的科林·玛伦带回8片水晶鳞片。', '干得好，$N。非常感谢你。$B$B也许在未来的某一天，你也会需要我的帮助。', '很高兴再次见到你，$N。$B$B你从石爪山的谷地里带回我需要的鳞片了吗?', '', '去找暴风城的科林·玛伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1079, '隐秘行动：A', '就是这样啦，$N。仔细看着，装置已然准备就绪了。$B$B拿着这几张纸——上面已经把引爆和爆炸的具体情况全写明白了呀，当然，包括你该把这些炸药放在哪儿。$B$B记住，任务的成功与否并不取决于你炸毁了多少东西，A计划的成功取决于你是否从峭壁湖南部的伐木场里带回了风险投资公司的计划书。', '将风险投资公司工程计划书从峭壁湖的伐木场中偷出来。', '太令人吃惊了呀!这对风险投资公司来说绝对是个巨大的损失!$B$B这样一来我们便可找出他们机器中的弱点，而也可以用他们的设计来强化我们自己的发明。这一天真是无与伦比的完美!', '搞到计画书了吗，$N?', '', '去石爪山脉找蛛网小径的加克希姆·尘链。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1080, '隐秘行动：B', 'B计划跟A计划差不多，$N。$B$B我们分布他们的注意力，然后将重要的信函都给偷出来。$B$B关键是要弄到他们的信件……记住这一点。$B$B我给你的纸上已然写明白了你该把炸药放在哪里。去吧，活着把那些信带回来……', '将风险投资公司函件从峭壁湖最东面的风剪矿洞中偷出来。', '不可思议，$N!凯拉和哨兵部队一定会非常高兴的。有你的战斗力和我的发明，我们就可以所向无敌了!', '行动进行得怎么样了，$N?', '', '去石爪山脉找蛛网小径的加克希姆·尘链。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1083, '怒灵', '我不敢肯定风险投资公司对这座山谷做了些什么，不过显然他们刚来的时候根本没有能力和这里的生物抗衡。$B$B于是他们只好在这里放了一把大火，然后用他们那强大的机器在山谷里四处屠杀。$B$B而且，这些无知的家伙还释放出了一些乱七八糟的元素生物，把山谷搞得一团糟。$B$B这些生物在谷中随意游荡，连艾露恩都不再眷顾这片土地了。$B$B干掉那些元素生物，把它们身上的闷烧馀烬带给我，以此来作为你曾奋力拼杀的证明。', '从焦炭谷中的任意火元素身上收集8个闷烧馀烬，把它们交给石爪山的凯拉·影矛。', '你帮助了我们，$N。谢谢你。', '第一次看见焦炭谷里的景象时，我几乎要哭了，$N。', '', '去石爪山脉找蛛网小径的凯拉·影矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1084, '受伤的古树', '显然，那些一直以来都守卫着山谷的树人们也已开始了驱逐风险投资公司的行动。不幸的是，甚至是这些最伟大的守卫者们也开始逐渐堕落。$B$B加克希姆认为他们的堕落与地精们撤退时所使用的某种武器有关。$B$B我告诉他，我打算从某个受伤的树人那里收集一份样本，这样他就可以通过对这份样本的研究来确定这个推断是否属实。$B$B给我带回一些弹片来，好让那个侏儒来研究它……', '给石爪山的凯拉·影矛带回一块被腐蚀的弹片。', '感谢你，$N。$B$B这些足够让加克希姆搞清楚树人究竟是如何堕落的问题了，我马上就把这个送到他手上。', '我觉得加克希姆应该能从弹片中找出些关于风险投资公司如何使用这种武器的线索。', '', '去石爪山脉找蛛网小径的凯拉·影矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1086, '地精空港', '毒药已经准备好，接下来就是如何下毒的问题了。$N，你来负责这个工作。$B$B风险投资公司的指挥部和石爪山的基地之间肯定有一条快速传送消息和规模货物的运输线。我想那应该是一个规模空港，它对地精飞艇来说可能还不够大，不过应付一般的飞行器应该是绰绰有馀了。到风险投资公司控制下的石爪山地区查查看，如果确实有这样的空港存在的话，就把毒药放在那里。$B$B放下毒药就赶快回来。', '把剧毒粮草带到风险投资公司的空港去，然后向药剂师扎玛复命。', '找到空港了?干得好，$N!这些哥布林一定会对你送去的东西大吃一惊!希望这个毒药能够流入他们的总指挥部。$B$B你为你的人民作出了贡献。我建议你还是忘掉给风险投资公司下毒所带来的负罪感，他们绝对是罪有应得。$B$B如果被遗忘者让它的同盟领悟了一些事情，那就是:$B$B不要在黑暗之路面前退缩……只要这条最终通向的是成功。', '如果风险投资公司在那里确实有一座空港的话，你就必须找到它，$N。', '投放剧毒粮草。', '去找雷霆崖的药剂师扎玛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1087, '塞纳留斯的遗产', '你根本无法想象到我是多么地憎恶这片污浊的土地。石爪峰那里有一小撮可怜兮兮的塞纳留斯族类和暗夜精灵的德鲁依们聚集起来，妄图彻底抑制住魔法的传播……甚至还妄想着夺回他们深深眷恋着的极南之地的森林。$b$b尽管我很乐意回到加德纳尔去享受传授魔法的快乐，但在我的工作完成之前，主人恐怕是不会让我回去的。$b$b我确信你和我一样，对暗夜精灵一族及他们盟友都没有任何好感。所以，请帮助我吧，这样一来，我们都能得到令自己满意的结果。', '为石爪峰附近的布莱林·火拳杀死4名塞纳留斯的儿子，4名塞纳留斯的女儿以及4名塞纳里奥植物学家。', '我已经能感觉到它了……对……令人陶醉的力量……令人血脉沸腾。卡多雷们竟然想将神赋予我们的最好礼物―魔法―从这世界上抹去，想将如血液一般流淌在我们精灵血脉之中的精华―魔法―从这世界上抹去，这实在是太愚蠢了!$B$B若没了这种永恒的悸动，我们的生命将是多么苍白可笑啊!', '看，在这里想要引导魔法就像是用竹篮打水一样。', '', '去石爪山脉找烈日石居的布莱林·火拳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1088, '奥达努斯', '他们自以为能够阻止魔法的传播，但他们无疑大错特错了！他们自以为能藏得住奥达努斯，但我一定要他死！$b$b魔法赋予了我真知……没错，我能看到他。一处岔路……就在灰谷森林中的一棵巨树的顶部。这棵巨树的名字叫作……瑞恩伍德。它是森林之神最初的几位子嗣之一。当初，在我找到奥达努斯之前，他就从石爪峰离开了，但现在，他的生命即将结束！$b$b把他的徽记带回来给我，我将送给你一件强力的魔法物品作为礼物。', '将奥达努斯的徽记带给石爪峰的布莱林·火拳。', '我很久以前见过奥达努斯一次。他身上有着一种独特的自傲，即便是面对着精灵贵族，他也不忘保持着一种俯视的姿态。$B$B他的头现在可没办法抬得那么高了，对不对，$N?$B$B我说过要给你一份奖励的，你现在可以拿到它了。', '当我的主人吩咐我来石爪峰的时候，我一直希望能消灭那些夜精灵……那些占据了我们古老而神圣的艾萨拉圣殿遗迹并玷污了它的蠢货……可是奥达努斯居然从我手里溜走了。', '', '去石爪山脉找烈日石居的布莱林·火拳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1089, '大兽穴', '德鲁依们在石爪城堡中建造了一个石爪猛禽洞穴，在那里面保存着一些威力强大的物品。$b$b他们制订了一整套详细的防范方案来避免这些物品落入他人之手。$b$b幸运的是，我想尽一切办法从他们当中的某个人口里套出了一些有用的细节。$b$b只要你找到那个洞穴入口处的一只小灯笼，就可以拿到守门人的钥匙。用这把钥匙就可以打开隐藏在洞穴中各处的暗格，而暗格里就藏有能打开中央大仓库的工具。', '到石爪峰上的洞穴中去，使用守门人的钥匙拿到能打开石爪峰顶的猛禽洞穴储藏室的物品。', '将三把钥匙分别插入对应的锁孔中之后，在一片亮光中出现了许多物品。', '在石头上有三个钥匙孔。', '', '去石爪山脉的猛禽洞穴找到猛禽洞穴储藏室。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1091, '向凯拉回报', '$N，把这些信拿去交给凯拉。我确定她会对里面的内容有兴趣，至少哨兵部队会感兴趣。$B$B记得告诉她，我们的行动是有多么的成功，哦，还有，别忘了强调一下，如果不用点魔法的话，我们是不可能成功的。', '将风险投资公司函件带给石爪山脉的凯拉·影矛。', '这确实很有趣。$B$B你和加克希姆干得非常漂亮，$N。谢谢。', '你好，$N。有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1092, '格雷苏的要求', '我想我也应该赶紧跑路了。这件事情马上就会传到上头人的耳朵里，而且他们肯定不会给我好果子吃。$b$b我得从这里偷偷逃出去，然后去见菲兹克斯。如果他能给我找到一份新工作就再好不过了！$b$b我得先把这里给打扫打扫，不能留下什么痕迹，而你最好现在就动身，马上把矿石的样本给菲兹克斯送去。他说他就在狂风峭壁西边建了一片营地，祝你走运！', '将未经化验的矿石送到石爪山的菲兹克斯那里。', '啊~~~我就知道，让匹兹尼克待在那里面打探消息是再正确不过了。我敢打赌幽坑城那边的工程师们一定会对这东西感兴趣的……$B$B当然我会给自己留下一小块，这对他们应该没有什么影响，对吧?', '找我有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1093, '超级收割机6000', '风险投资公司到底在搞什么鬼啊，嗯？他们到底在想些什么呀？地精的公司里竟然雇佣了一个侏儒！$b$b好在斯布特瓦夫是个识货的家伙，知道我是个天才，他在我被公司炒了以后马上就雇佣了我！$b$b据说公司正在制造一种新型的大型伐木机，斯布要把我这东西的设计书偷来给他。不过格雷苏——那个满手是血的侏儒——他一看见我就想把我给干掉……或许你能替我去把设计书给偷来？你应该可以在他们的操作员身上找到它。', '为石爪山的菲兹克斯偷来超级收割机6000型的设计图。', '嘿，这就是我想要的东西?好极了!$B$B来，让我看看。唔……我该对这东西说什么好呢……地精的想法已经不是我们可以理解的了。他们那喜欢研究飞行器的怪癖暂且不提，但是他们制造的这种轮子实在让我很吃惊。', '你找到设计书了吗?我要用这东西给我的新老板露上一手。当然，我希望他知道我对他是有多么的死心塌地以后―嘿，别打岔，我对他当然是死心塌地的……你了解哥布尔的忠诚么?―那么以后我就可以在这儿如鱼得水地大干一场了!', '', '去石抓山脉找狂风峭壁的菲兹克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1094, '新的指示', '这信封里有我被撵走之后风险投资公司方面的全部情报……公司内部文件，一些操作手册，技术设备……嗯嗯，当然还有超级收割机6000型的蓝图。$b$b斯布特瓦夫就在贫瘠之地的棘齿城，你应该很容易找到他的……特征？太明显了，他的皮肤是绿色的。', '将密封的信封交给贫瘠之地棘齿城的斯布特瓦夫。', '是菲兹克斯?我的确不是很信任他，但这些情报看来非常有用，我们可以借此加强自身的竞争力。$B$B他们看来确实搞出了一些不错的新设备……不可否认，他们的机械设计方案让我们受益颇多。', '你好!有什么可以帮忙的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1096, '格雷苏', '我只见过格雷苏一次，但我得告诉你，那家伙一眼看上去就知道他不好对付。他的一部分身体似乎已经残废了，于是他给自己装上了一些金属部件和装备，这样他的部分肢体就机械化了。$b$b格雷苏就在西北方峭壁湖的湖岸边上监视着整个地区的工作进展。我想我是没办法去那里了……但你看起来也许有能力对付他。$b$b如果你能为我干掉他的话，我会付给你不错的酬劳的。', '将格雷苏的机械臂带给石爪山脉的菲兹克斯。', '啧啧，你看看你看看……地精们就是喜欢这种东西。我真是搞不懂，一个人怎么能把自己的胳膊砍下来，然后安上这东西来代替它?你完全可以把两条胳膊都留下，然后安上第三条嘛!$B$B我跟你说啊……这就是地精……$B$B至少现在格雷苏已经被除掉了。希望靠这个能向斯布特瓦夫证明我有足够的能力，让他愿意把我推荐到加基森甚至是幽坑城的技工协会去……', '斯布特瓦夫显然需要能证明格雷苏已死的证据，我想他的机械臂就很合适。', '', '去石抓山脉找狂风峭壁的菲兹克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1100, '亨里格的日记', '你慢慢打开亨里格·独眉的这本破旧的日记……', '阅读亨里格·独眉的日记。', '你说你在一个死去的矮人身上找到了这本日记?给我点时间仔细读一下……', '从你凝重的脸色中，我看出……有什么东西出了问题……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1101, '卡尔加·刺肋', '可怜的赫尔拉斯！还有这个矮人……他是多么的勇敢。$b$b我们不能让他们白白牺牲。卡尔加·刺肋……必须受到制裁。$b$b当然，深入剃刀沼泽是非常危险的，但现在已经没有时间通知达纳苏斯了。$n，组织一支队伍去杀掉卡尔加·刺肋。$b$b把她的徽章交给我，作为她已死的证明。', '把卡尔加·刺肋的徽章交给萨兰纳尔的法芬德尔。', '这个老太婆已经死了。这是个令人难以置信的消息，$N。$B$B在这个危险的时刻，它能重新让你看见自己的勇气。$B$B要小心卡尔加.刺肋的手下，我们的研究在这个区域才得以继续进行。或许现在我们可以获得更进一步阿迦玛甘发生在休息之地日趋腐败的正确消息。$B$B然而，我害怕这问题的答案也同样背判我们 …', '只要卡尔加.刺肋在剃刀沼泽召集军队，这片土地将陷入巨大的危险之中。', '', '去千针石林找萨兰纳尔的法芬德尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1102, '奥尔德的报复', '凯恩是个高贵而睿智的领导者，是他带我们在雷霆崖创建了新的家园。$b$b但我绝对不会原谅那些将我们从世代相传的土地上赶走的家伙。我们在贫瘠之地的南部生活了数十年，这片土地对我们来说是神圣的。但我们却被为数众多的敌人赶了出去。$b$b我要对卡尔加·刺肋这个恶棍进行报复，就是他在剃刀沼泽纠集了大批邪恶的部队，让我们背井离乡。$b$b把他的精华给我带来，这样我才能安息，$N。', '把卡尔加·刺肋的精华交给雷霆崖的奥尔德·石塔。', '剃刀沼泽里的邪恶部族现在终于可以感受我们曾感受过的痛苦了，这对他们来说是罪有应得。$B$B把我们从圣地赶走的恶棍理应遭到最严厉的报复。$B$B谢谢你，$N，谢谢你帮助了我。', '只有当我得知剃刀沼泽的邪恶野兽被赶出他们那个肮脏的窝时，我才能松一口气，因为那样才能说明我的报复行动已经完成了。$B$B你将野猪人从剃刀沼泽里赶走了吗?你干掉卡尔加了吗?', '', '去找雷霆崖的奥尔德·石塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1103, '水之召唤', '你好，我的$g兄弟:姐妹;！你是来净化这里的水并展示从伊斯伦那里学到的东西的吗？$B$B我刚刚打败了堕落的水灵，正准备把护腕和馀下的水放在火盆上。$B$B那是什么？啊……只要有什么地方出了问题，提夫总能洞察一切。如果你想再次见到纯洁的水灵，提夫应该能帮你。$B$B从伊斯伦那里拿一瓶水之灵契来证明你已准备就绪，然后接下来的事情就交给我吧。', '如果你没能与水之魂交谈，就给银松森林的提夫·摩杜恩再拿去一瓶水之灵契。', '啊……看来你准备好了……$B$B我会把需要的东西放在火盆上，这样你也能和水灵交谈了。$B$B不要惧怕与精神世界的灵魂对话……提夫知道一两个关于如何使用灵契的诀窍。$B$B来吧，和我一起到神殿去和那些水灵谈谈，我的$g兄弟:姐妹;。', '你有灵契吗，我的$g兄弟:姐妹;?$B$B我知道另一个人在打败那个堕落的水灵之后有了麻烦―似乎他等得太久，最后因为不耐烦而离开了。我不希望看见这样的事情再次发生，为此我决定继续等在这里，直到确信没有人再需要我的帮助为止。', '', '去找银松森林的提夫·摩杜恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1104, '含盐的蝎毒', '我有很多关于改进火箭车的计划！很多很多！我必须一一尝试！！！$B$B我在研究一种新燃料，一种燃烧起来非常非常热的燃料！！但是我还没有将配方制作到尽善尽美，我想我知道还缺什么东西……$B$B在闪光平原上游荡的蝎子体内有一种含有很多盐分的毒液，这种毒液非常特别！那正是我想要的！$B$B带些毒液给我，相信我——有了这些毒液，我们的赛车就可以快到飞起！！', '为闪光平原的菲兹尔·铜栓带去6份含盐的蝎毒。', '好的!这个毒液会派上大用场!谢谢你，$N!$B$B现在我只要把它熬一下，用一些这个，加一些那个，再……见鬼!我的笔记本哪儿去了?', '喂!你找到毒液了吗??', '', '去千针石林找沙漠赛道的菲兹尔·铜栓。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1105, '硬化龟壳', '我的兄弟正在为他的火箭车研究一种新燃料。他很聪明，真的，他真是太聪明了……我想他设计的新燃料一定非常强悍，甚至可以蚀穿车子的底盘！$B$B为了防止这种情况的出现，我想应该要加固一下燃料箱。$B$B这片平原上的乌龟有很硬的壳，我想用它们来制造火箭车的新燃料箱，这样就可以装载我兄弟的新燃料了。$B$B你看起来很可靠，愿意去给我弄一些这样的壳吗？', '收集9块硬化龟壳，把它们交给闪光平原的维兹尔·铜栓。', '你拿到龟壳啦!谢谢你，$N!$B$B哇，这些壳比我想象中的还要硬!嘿嘿，要用它们来做燃料箱的话，肯定会弄坏一整箱的工具!', '我兄弟的新燃料设计进度很快，这让我感到十分焦急。我要尽快开始制造龟壳油箱的工作了。$B$B$N，你弄到龟壳了吗?', '', '去千针石林找沙漠赛道的维兹尔·铜栓。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1106, '流放者马特克', '我正在研制一种新的发动机，它可以让赛车开得更快！快到飞起来！我只要有一个能承受重压的活塞就能够完成这个发动机了，但是之前所有的活塞样品试验都失败了，就因为活塞的质地不够硬！$B$B我想有人知道怎么解决这个问题。$B$B他叫流放者马特克，是个伟大的铁匠，他比任何人都更加了解金属的特性。把这封信交给他，我知道他能帮我！$B$B但他在很远的地方，在艾泽拉斯大陆上的荒芜之地，和一个地精同住在一个营地里！$B$B去找到他吧！', '把菲兹尔·铜栓的信带给荒芜之地的流放者马特克。', '菲兹尔派你来的?你早说不就结了嘛!我当然会帮你。菲兹尔和他的兄弟是少数几个不会想置我于死地的人!$B$B所以菲兹尔想要活塞?要坚固到足以承受他预计的任何压力?以我对菲兹尔的了解，他的这部新车肯定会跟火箭一样快。', '啊，你找到我了。很好。$B$B你来是为了我替加塞尔佐格所铸造的那把斧头的事情吗?还是为了夺回杜切斯.帕麦尔的荣耀?$B$B实际上，我根本不在乎是哪个原因。如果你是来打架的，那就放马过来吧……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1107, '坚硬的尾鳍', '我们的火箭车是平原上速度最快的！不过有点太快了……我担心高速行驶中的摩擦力会把它给撕开！$B$B为以防万一，我要配制一种合成剂来给车子的转动部件涂上。它必须坚固、耐冲击、能抵抗盐分的侵蚀，并且不易老化。$B$B你听说过暗礁海吗，$N？它就在荆棘谷地区的海岸边。盐鳞鱼人在那一带活动，它们的尾鳍正是我所需要的重要原料！', '给闪光平原上的瑞兹尔·铜栓带去10片坚硬的尾鳍。', '谢谢你，$N!我马上就拿这些东西去制作合成剂，这样我们的车就足够坚固啦!$B$B当然，我是说在不撞到什么东西的情况下……', '你弄到尾鳍了吗?如果我们的赛车有在急速行驶中解体的危险，那我就不能指望它跑完全程啦!', '', '去千针石林找沙漠赛道的维兹尔·铜栓。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1108, '精铁碎片', '我大老远地跑到这儿来并不是为了躲开什么人。$N，如果你有足够的勇气，那么荒芜之地的矿藏绝对可以让你大发横财。$B$B有一种被称作精铁的矿石，据说它具有很强的耐压和耐热性，这也许会对菲兹尔的车有所帮助。$B$B但是我们需要进一步地确定。去帮我找些精铁的样品来测试它的特性吧。$B$B真正的精铁矿石深藏在奥达曼，但荒芜之地的石窟穴居人身上常常带着一些矿石碎片，给我找一些这种矿石碎片来。', '收集10块精铁碎片，把它们交给荒芜之地的流放者马特克。', '啊，没错，这些就足够了。现在我们来给它们加热，看看它们有什么反应……', '$N，你找到精铁碎片了吗?我已经一切就绪，就准备进行测试了。', '', '去荒芜之地找漫尘盆地的流放者马特克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1109, '蝙蝠的粪便', '就如你所见到的一样，$n，我们正要在皇家药剂师学会进行一个非常…嗯…有趣的实验。$B$B作为这里的领导者，我的职责就是监管所有最具潜质的化学实验。所以说我总是梦想太多，时间太少！$B$B你看上去是个擅长跑腿的$c，也许你可以帮我的忙。$B$B我需要一种稀有的原料，这种原料只有在产于剃刀沼泽的一种罕见的蝙蝠身上才能找到。去剃刀沼泽帮我带回一些沼泽蝙蝠的粪便来，然后我们就可以开工了……', '帮幽暗城的大药剂师法拉尼尔带回一堆沼泽蝙蝠的粪便。', '太好了!这正是我们所需要的东西，$N。', '啊，你回来了。你得到沼泽蝙蝠的粪便了吗?', '', '去找幽暗城炼金房的大药剂师法拉尼尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1110, '火箭车零件', '咳咳，所有的赛车跑起来都像飞一样，出一些小事故也就不足为奇了。如果你在闪光平原四周转转的话，就会看到过去撞车事故的遗物——火箭车的碎片散落得到处都是！$B$B这些零件对侏儒和地精来说非常值钱，它们一直都想为它们的赛车装上更多的设备。$B$B所以你可以去给我搜集这些零件，我会给你巨额报酬的。', '收集30个火箭车零件，把它们交给闪光平原的克拉维尔·浓须。', '哈，看看这个!在这些垃圾里有不少好东西呢，我敢说这次肯定可以赚不少!$B$B还有……这两片金属中间夹着的是什么?压烂的耳朵?哦!我可不想跟那个驾驶员一样!$B$B谢谢你，$N。这是你应得的报酬。此外我还有些忠告给你，当然是免费的……$B$B如果你有足够强悍的话，你总能在事故中多多少少地获利。', '$N，你在闪光平原上到处搜过了吗?弄到足够的零件了吗?', '', '去千针石林找沙漠赛道的克拉维尔·浓须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1111, '码头管理员迪兹维格', '满足人们的需要就是我的工作，现在那边的侏儒弟兄们需要一些零件。一星期前那些零件就已经运到棘齿城了，但我一直都没有时间去取货。$B$B所以……你愿意替我跑一趟吗？到棘齿城去，将这张零件订单交给码头管理员迪兹维格——他很可能就在码头上忙活。$B$B我的朋友，这些工作的报酬可是非常诱人的哦……', '把克拉维尔的零件订单交给贫瘠之地棘齿城的码头管理员迪兹维格。', '哦，对，确实有给克拉维尔的零件。我很高兴你来到这里，这些零件放在这里有一些日子了，我都担心它们快要生锈了!', '大声点儿!你是来取货的还是托运的?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1112, '给克拉维尔的零件', '$N，这是克拉维尔要的货。你把货交给他的时候记得转告他……如果他想要更多的特别订货，就必须得付更多的钱！', '把克拉维尔的零件交给千针石林中闪光平原的克拉维尔·浓须。', '太好了!你拿到货了!现在我们要把这些东西交给地精们。不过，首先……$B$B让我们从里面拿出一个小小的零件……', '你去过棘齿城了吗?取回零件了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1113, '狂热之链', '你也许会问我们为什么需要这种粪便，嗯，在这个实验中，我想要看看两种性质截然相反的物质相互作用会产生怎样的效果，特别是当这两种物质都与最具能量的物质相混合之后，它们将产生……非常惊人的结果。$B$B在提瑞斯法林地的东北面有一座血色修道院。那里是疯狂的血色十字军信徒出没的地方。干掉他们，把他们贴身佩戴浸满汗水的狂热之链给我拿回来。$B$B我们制作的混合物将是世上毒性最强的！', '幽暗城的大药剂师法拉尼尔需要20根狂热之链。', '我的天啊，你给我带来的原料真是太棒了，$N!你得表现太出色了!', '你从血色修道院回来了? 为了这个令人愉悦的实验，我需要许多心脏来作为原料!$B$B毫无疑问，瓦里玛萨斯和黑暗女王也会因为血色十字军那些渣滓被干掉而感到高兴的。', '', '去找幽暗城炼金房的大药剂师法拉尼尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1114, '侏儒的货物', '既然手续齐备，那你就把这些零件带给菲兹尔·铜栓吧。他为此已经等待很久了——我相信他不会在意我从他那些零件中拿了点小东西……$B$B当然我也不会和他提这件事情，这对于他来说只是九牛一毛而已，没什么意义。$B$B相信我。', '把精密赛车零件交给菲兹尔·铜栓。', '就是这些东西!我要的水棘齿和中继器插梢!它们一定能派上大用场。谢谢你!', '你有东西要给我?太好了!让我看看!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1116, '沼泽中的梦境粉尘', '你打听到的有关纳兹的消息真是帮了我一个大忙，$N，确实帮了我一个大忙。既然你已经特意大老远地从闪光平原赶来……那么你是否愿意再多走些路呢？$B$B在我想办法打听相关信息的时候，你何不去帮我收集一些东西呢？$B$B嗯……怎么样？帮我找一些梦境粉尘吧，你可以在悲伤沼泽的幼龙和龙族的身上找到梦境粉尘。我很喜欢在鼻烟袋里放一点梦境粉尘！$B$B给我弄些梦境粉尘来，$N，我会用你需要的信息和你进行交换。', '为藏宝海湾的克拉兹克收集10份梦境粉尘。', '哦，不错不错，你找到幻梦之尘了!$B$B你觉得那个沼泽如何，$N?那里可不是个度假的好去处，对吧?', '这么快就回来了?你拿到我要的幻梦之尘了吗?', '', '去荆棘谷找蛮荒海岸的克拉兹克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1117, '地精的谣言', '看来我要好好对待自己了，把那瓶稀有的精灵葡萄酒送掉，然后开始减肥！但是我找到了一些你正在寻找的信息。$B$B拿着这个，我写了一封信，其中包含了一些关于我们的朋友纳兹的有趣的事情。你可以随便怎么处理它——我自己去传播的话会很危险。$B$B记住不要告诉任何人你是从哪里得到它的！', '把地精的谣言带给千针石林中闪光平原的克拉维尔·浓须。', '很好很好!这很有趣―非常有趣。呵呵，也许下次我看到那个矮人飞行员的时候应该向他鞠躬。$B$B$N，这些资讯绝对足够了。我确信纳兹会为了保留这个秘密而付出一小笔钱的。', '你找到有关纳兹的资讯了吗?有没有什么事情是他不想让人家知道的?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1118, '返回藏宝海湾', '$N，我想你是一个值得信赖的$c，既能把任务做好，又能严守口风。$B$B我在酝酿一个新的计划。这个计划非常危险，但只要成功，我们就能大赚一笔！我想你正是做这件事的最佳人选。$B$B首先，你得回藏宝海湾一趟。我很抱歉，好心的$N，我知道上一个任务也把你派到那儿去，但是这次，还得请你去和克兰克·菲兹巴布谈谈。$B$B把这封信带给他，如果他需要帮助，尽你所能去帮他。你的努力会得到应有的回报的。', '把克拉维尔的计划书交给荆棘谷藏宝海湾的克兰克·菲兹巴布。', '我懂了。克拉维尔有一个很大的计画。他够残忍，我喜欢!$B$B你需要一些东西，对吗?……某些强大的东西……$B$B我不知道那些赞吉尔用来喂食他那些疆尸的药剂是否有用……', '您好!是什么让您这么一个高贵的$R来到了藏宝海湾?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1119, '赞吉尔的药剂和蠢人酒', '我已经搞清楚怎样用赞吉尔的药剂和烈性酒来合成更强力的饮料了，我称它为蠢人酒。我知道这东西正是克拉维尔所需要的，但回头你别忘了告诉我它的效果到底如何。$B$B还有，$N，别把这东西放太久，赞吉尔的药剂对酒中的酵母有一种超乎寻常的影响，能让它迅速爆发出惊人的活力来，因此你也就无法长时间保持蠢人酒的新鲜了。', '把蠢人酒交给千针石林中闪光平原的克拉维尔。', '太好了!菲兹巴布成功啦!下次见到他我一定要好好谢谢他。$B$B多谢你，$N。你做了一件了不起的事，我们一起来靠这东西赚大钱吧……', '你好，$N。菲兹巴布可以帮我们吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1120, '灌醉侏儒', '我们要用蠢人酒在那些车队的工作人员身上做试验。如果你想在侏儒身上试试的话，那么就拿去吧——把酒交给侏儒车队的老板。$B$B不要拖得太久，这种酒会慢慢变质的。', '把蠢人酒带给千针石林中沙漠赛道的侏儒车队老板。', '酒?你真是考虑周全!谢谢你!$B$B比赛就要开始了，所以我们最好不要喝酒……不过……也许可以稍微来那么一点儿。嗯，这酒不太烈吧?', '嗨!你有东西要给我?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1121, '灌醉地精', '我们要用蠢人酒在那些车队员工身上做做试验。如果你想在地精身上试验的话，那就拿去吧，把酒交给地精车队的老板。$B$B不要拖得太久，这种酒会慢慢变质的。', '把蠢人酒交给千针石林中沙漠赛道的地精车队老板。', '哦哦!好香啊!$B$B好吧，我并不介意喝上一小口……', '你在看什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1122, '向菲兹巴布报告', '蠢人酒的效果太妙啦！我打赌下一场比赛我们必胜，而且……我很想看看喝了那些酒的家伙们出丑！$B$B眼下我只有一个任务交给你了——把这封信带给藏宝海湾的克兰克·菲兹巴布，他一定会很想知道这项试验是不是成功了。$B$B而且我们希望以后能够得到更多的蠢人酒！', '把蠢人酒试验报告交给石爪山脉藏宝海湾的克兰克·菲兹巴布。', '信上说蠢人酒的试验获得成功了。这真是个好消息!$B$B如果你想要更多酒的话，尽管告诉我，我会让你去收集更多赞吉尔的药剂。', '你好，$N。那种酒的效果如何?味道很烈吧?哈哈哈!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1124, '废土', '在安戈洛环形山以西，穿过西北部的山脊，是一片荒芜的土地——希利苏斯。很少有人知道，暗夜精灵曾在那里与一个邪恶而诡异的种族进行过一场恶战。邪恶最终被封印了，但是我怀疑它们正在蠢蠢欲动，想要让恐惧卷土重来……$B$B去寻找我们派往希利苏斯的一名使者，莱耶·星击。他就在勇士之墓，那儿是在战争中牺牲的勇士们安息的地方。把这封信交给他，他就会信任你。', '在希利苏斯的勇士之墓附近找莱耶·星击谈谈，把拉比恩的信交给他。', '拉比恩让你来的，是吗?哦，欢迎你来到这儿……虽然这是片人烟稀少的荒地。$B$B虽然我并没有亲眼见到过那场上古的战争，但是这里的残垣断壁仍然可以向你展示那些被遗忘的过去。在你的帮助下，塞纳里奥议会也许能清除这股很久以前就应该被消灭掉的邪恶势力。', '这儿危机四伏，$C。是什么让你来到希利苏斯这片荒原的?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1125, '南风村的灵魂', '在我们的西南方有个悲惨的地方——南风村的遗迹。我们就从那里开始吧，$N。$B$B根据我所掌握的情报，那座村庄曾经是暗夜精灵在希利苏斯的基地。很久以前异种蝎群攻陷那里，并将其夷为一片废墟。我简直不敢去想象南风村被虫群吞没的恐怖景象……$B$B那些饱受痛苦的德鲁伊和哨兵的亡魂在那座遗迹中漫无目标地游荡。探索那个地区，并释放那些悲惨的灵魂。', '在南风村释放8个被折磨的德鲁伊和8个被折磨的哨兵的灵魂，然后向希利苏斯勇士之墓的莱耶·星击复命。', '我曾认为或许是村庄废墟附近的大量异种蝎令希利苏斯了无生气。现在看来，我的看法是对的;它们会对我们产生极大的威胁。$B$B感谢你释放了死者的灵魂，我知道这不是件容易的事。但是，如果你愿意的话，我还想再请你帮个忙……', '部落或者联盟，这都没有关系―这个世界上没有谁的灵魂活该被折磨。释放这些灵魂\r\n，让他们获得解脱，$N。', '', '去找希利苏斯的莱耶·星击。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1126, '塔中之巢', '我们必须找到南风村的异种蝎巢穴，而我知道有一个方法可以找到它。以我的经验来看，它们对于周围的环境很敏感，这也就解释了为什么它们会在听到灵魂的死亡嚎叫之后发起攻击。$B$B塔里的异种蝎群最为强大——就是那座有很多飞虫围绕着的塔。爬上那座塔，然后骚扰虫巢。向我汇报你所发现的东西！如果你找到了什么有价值的东西，就把它带回来给我。', '爬上南风村的塔，找寻激活异种蝎群的方法。把任何你认为不寻常的东西交给希利苏斯勇士之墓的莱耶·星击。', '这……这是什么?$B$B它的样子……像个盒子，对吗?这里面有一些有趣的东西。等等，有一部份是打开着的……怎么会有一本书?$B$B我想你发现的还是很有用的，$N……好吧，至少我希望如此。也许它是一本被封在这个外壳里面的古代日记。$B$B我想我有办法知道它究竟是什么。', '好吧，你干得怎么样了?看来你没有缺胳膊少腿，这是个好消息。你找到什么了吗?', '', '去找希利苏斯的莱耶·星击。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1127, '蠢人酒', '你想要一些蠢人酒？是用在赛车比赛上么……$B$B好吧，给我弄些赞吉尔的药剂来，我就给你调制更多的酒。', '收集12份赞吉尔的药剂，把它们交给藏宝海湾的克兰克·菲兹巴布。', '嗯，这些是给你的蠢人酒。现在你到闪光平原去把它交给地精或哥布尔的车队老板吧，记得要赶快，因为这东西没法长时间保持新鲜。$B$B如果什么时候你还想要更多酒的话……就来这里找我吧!', '你搞到赞吉尔的药剂了吗，$N?', '', '去荆棘谷找藏宝海湾的克兰克·菲兹巴布。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1131, '钢齿土狼', '有时我们为了食物而狩猎，有时我们为了荣耀而狩猎，而有时我们为了得到大地母亲的教诲而狩猎。$B$B但是这次我让你去捕猎的却是一个例外中的例外，我要你去杀死一个不被大地母亲所祝福的生物。$B$B这个名叫钢齿土狼的生物游走于贫瘠之地南面的千针石林，它是个残暴的统治者，它率领着其它的土狼，给原本平静的兽群带来恐惧和无谓的伤亡。$B$B找到钢齿土狼，$N，找到它，打败他。', '把钢齿土狼的肋骨带给雷霆崖的梅洛。', '你打败了钢齿土狼，清除了千针石林中一个可怕的影响。$B$B希望你能从中领悟到一些东西，$N。', '你打败邪恶的钢齿土狼了吗，$N?', '', '去雷霆崖找猎人高地的梅洛·石蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1134, '石爪山的双足飞龙', '尽管我们还没有跟部落全面开战，但是这来之不易的和平却已经处于崩溃的边缘了，最近他们愈加频繁地展开针对我方的秘密行动。$B$B我们安插在塞拉摩的密探向我们报告说，在石爪峰南面的暗色湖一带有许多巨翼双足飞龙在活动，而兽人正在该地收集它们的毒液，然后兽人的刺客就会使用这些毒液来悄无声息地对联盟发动致命的突袭！$B$B如果他所说的都是真的，那么我们就必须阻止他们，$N。我们必须切断他们的毒液来源！', '收集12个巨翼双足飞龙的毒囊，并把它们交给阿斯特兰纳的辛德瑞尔·速火。', '谢谢你，$N。杀戮那些并非兽人帮凶的可怜生物令我感到悲伤，但这是我的职责所在。$B$B我的朋友，也许你会为那些被你杀死的双足翼龙而流泪，但你的盟友可以因此免受巨翼毒液的伤害，希望这可以让你的心灵得到些许的慰藉。', '$N，你拿到巨翼双足翼龙的毒囊了吗?我们不能让兽人用这些野兽的毒液来对付我们!', '', '去灰谷找阿斯特兰纳的辛德瑞尔·速火。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1135, '风巢双足飞龙的毒囊', '你也许知道，兽人们通常会驯化双足飞龙以供骑乘之用。但很少有人知道，从某种角度来说，双足飞龙的毒液比它们本身更有价值。如果你不介意狩猎双足飞龙的话，那么……我有一项工作交给你。$B$B在千针石林的西边有一个叫风巢的地方，生活在那里的双足飞龙的毒液不但毒性非常强烈，而且价值极高。', '收集10个风巢双足飞龙的毒囊，把它们带给塞拉摩的菲欧拉·长耳。', '啊，这些毒囊几乎个个新鲜饱满，$N。通常这些毒液只有在幼年或者雌性的双足翼龙身上才能找到。我猜你一定在风巢干掉了不少双足翼龙!', '$N，你找到风巢了吗?那些双足翼龙还好对付吗?', '', '去黑海岸找薄雾海的菲欧拉·长耳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1136, '霜喉雪人', '$N，你现在得去跑一趟远路，而且我想你应该已经准备好了。$B$B你的任务是去猎捕霜喉雪人，它是奥特兰克山里的一个雪人。霜喉雪人可不是那么容易就能被抓到的，因为它白色的毛皮与山中的皑皑白雪融合在了一起，很难分辨，而且它极少暴露自己。$B$B不过现在我要教教你如何把像它这样的家伙给引诱出来。拿着这个卷轴，我已经在上面写好了诱捕霜喉雪人的方法。$B$B现在就动身吧，$N。你的旅途漫长而充满挑战。只有当你拿回霜喉雪人的鬃毛的时候，你的任务才算是完成了。', '把霜喉雪人的鬃毛带给雷霆崖的梅洛·石蹄。', '$N，能打败霜喉雪人就证明你有着过人的力量和机智。$B$B现在你已经去过了千针石林大峡谷和奥特兰克山，将来你一定会走遍世界，因为这是一条属于猎人的命运之路。', '$N，你去过奥特兰克山了吗?你遇见那形影不定的霜喉雪人吗?', '', '去雷霆崖找猎人高地的梅洛·石蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1138, '海中的水果', '我爱螃蟹，螃蟹就好像是海中的水果！你可以把它烤了吃、煮了吃、炖了吃、炸了吃、炒了吃、煎了吃；你可以把螃蟹做成螃蟹色拉、螃蟹汤、螃蟹炖肉、黑胡椒螃蟹、柠檬汁炖螃蟹、清蒸螃蟹和铁炉堡特级螃蟹——这就是螃蟹存在的意义！$B$B我现在要留在这里钓鱼，所以没有办法自己去找到上好的螃蟹肉。你可以从暗礁蟹和硬壳潮行蟹身上得到品质上乘的螃蟹肉，然后把它们烤了吃、煮了吃……', '收集6块优质蟹肉，把它们交给奥伯丁的古博·布拉普。', '啧啧，这些螃蟹肉正是我要的。谢谢你，$N!我在钓鱼的时候发现了这个，它对我来说没有什么用，也许它对你来说还有点用处，当然你没法用它做出螃蟹大餐来。$B$B我已经把所有关于螃蟹的东西都告诉你了，是不是?', '……柠檬汁炖螃蟹、清蒸螃蟹和铁炉堡特级螃蟹，这就是螃蟹存在的意义。$B$B哦，你好，$N。你拿到我要的优质蟹肉了吗?', '', '去黑海岸找奥伯丁的古博·布拉普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1139, '意志石板', '通过切断暗炉部族与黑石塔的联系，我们已经成功减缓了他们的行动。不过，铁趾的遗愿仍未完成，他不能就这么白白死去。他的梦想是要找到意志石板，那是一块注入了魔法能量的石头碎片。利用这种魔法，泰坦赋予那些由他们创造出来的物体以鲜活的生命，甚至将思想和意志赐予这些生命。$B$B我们必须赶在暗炉部族之前找到意志石板。$B$B返回奥达曼去找到石板，然后立刻回到这里。', '找到意志石板，把它们交给铁炉堡的顾问贝尔格拉姆。', '<当你把石头裂片交给顾问贝尔格拉姆时，他不住地摇头，似乎还不太相信。>$B$B$N，真是不可思议。我将马上把这个交给国王的法师们。他们想仔细研究一下，从而确定传说的真伪。不过那不是我们现在该讨论的问题……你对我们的帮助已经远远超出了我的期望，谢谢你。', '$N，我们必须完成铁趾的遗愿，我欠他太多了。$B$B你要尽快返回奥达曼，这不仅有助于实现我们的计画，也有助于保护所有矮人的安全。如果石板落入黑铁矮人的手中，天知道他们能造出多少强大的作战魔像来。', '', '去找铁炉堡的顾问贝尔格拉姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1140, '奥萨拉克斯之塔', '兽人们写起字来比小孩子的涂鸦好不到哪里去。当我决定去学习他们的语言时，我的许多部下都曾经取笑过我，但我想这样做还是有助于进一步了解我们的敌人。$b$b从伊克鲁德的乱七八糟的文字中，我们可以知道埃瑟里克斯仍掌握着两颗灵魂宝石，它们分别在灰谷东北部的夜道谷和萨提纳尔，这两个地方都是被萨特控制的地区。$b$b千万小心点，$n，面对那些被萨特之血浸透了地面的神殿，即使是像你这样经验丰富的$c也会心神不宁的。', '在夜道谷和萨提纳尔找到被禁锢的上层精灵的灵魂，释放它们，然后回到迈斯特拉岗哨的净化者德尔格伦那里。', '也许萨特们已经在这片森林中生存得够久了。我下次去奥伯丁时会和艾丽莎谈谈这件事。$B$B不过，灵魂宝石已经被毁，埃瑟里克斯的法力也会大不如前，我们应该把握这个机会来消灭他和他的信徒。', '我曾听人私下里说过，萨特的历史与夜精灵有着某种联系，但我尊敬的夜精灵主人们对这件事却是讳莫如深。', '', '去灰谷找迈斯特拉岗哨的净化者德尔格伦。', '释放夜道谷的上层精灵的灵魂', '释放萨提纳尔的上层精灵的灵魂', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1141, '钓鱼世家', '布拉普系列一向以酷爱钓鱼而闻名。我的名字叫古博·布拉普，我在钓鱼。$B$B在这个地区我最希望钓到的鱼是黑海岸石斑鱼。以前我会坐船出海专门钓这些石斑鱼，但是由于那些该死的鱼人的出现，我已经很久没有出海钓鱼了。我打赌那些鱼人早把这里的石斑鱼给吃光了。$B$B那么说来，你愿意帮我抓一些黑海岸石斑鱼回来？如果你愿意的话，我可以给你一把货真价实的布拉普系列鱼竿！这根鱼竿可是钓鱼时的乘手工具啊！', '为奥伯丁的古博·布拉普抓6条黑海岸石斑鱼。', '这些石斑鱼真新鲜，$N!谢谢你的帮助!$B$B你至少和我的兄弟，格劳恩.布拉普一样优秀了。他也和我一样长着浓密的大胡子，而且看起来很风趣，这些都不妨碍他成为一个钓鱼高手。我相信你现在已经拥有使用布拉普系列鱼竿的能力了。', '用黑海岸石斑鱼可以做出很多美味佳肴来。它们味道非常鲜美，但是我更加喜欢钓鱼的过程。$B$B你钓到黑海岸石斑鱼了吗?', '', '去黑海岸找奥伯丁的古博·布拉普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1142, '临终遗言', '我现在很虚弱……没…没多久可活了。$b$b……那个勇…勇敢的矮人，亨里格·独眉，已经被派去警…警告法芬德尔了……$b$b但…我死…死之前……$b$b……我的妻子，塔莎拉……我们两人定情的坠饰…被…那群卑鄙的入侵者…偷走了……$b$b拜……拜托你，找到它……把它还给在达纳苏斯的塔莎拉……$b$b……还有……告诉她……我爱她……', '将塔莎拉的坠饰带给达纳苏斯的塔莎拉·静水。', '不!$B$B这绝对不可能!啊，这个残忍而无情的世界!$B$B我必须要挺过这阵悲痛，赫尔拉斯的事业还要继续下去。$B$B感谢你从那样危险的地方来找我，$N。但现在就让我一个人待会吧。$B$B我想要独自去哀悼我所爱的逝者。', '你来找我有何贵干，$C?', '', '去达纳苏斯找塞纳里奥区的塔莎拉·静水。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1143, '奥萨拉克斯之塔', '我知道了。如果你所说的是真的，那么我们必须马上发起进攻。我认为埃瑟里克斯就住在塔上。不过你要当心，在他的周围有很多强大的术士，比你以前所见到过的任何术士都还要可怕。', '杀掉埃瑟里克斯·纳拉辛，把他的徽记交给奥萨拉克斯之塔附近的巴苏尔·影击。', '我希望埃瑟里克斯的死能够帮助我们击退这个地区的恶魔势力。毫无疑问，他们还会重新集结然后卷土重来，不过到那个时候，我们就会有更加充分的准备。', '埃瑟里克斯·纳拉辛是一个古代的强大术士，也许我们应该等德尔葛兰来帮我们。不过既然他派你只身前来，那么想必他对你非常有信心。', '', '去找黑海岸的巴苏尔·影击。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1145, '疯狂的虫群', '许多路过十字路口的旅行者都曾帮助过我从巨人旷野收集虫卵，他们大都知道那里的生物有多么可怕。我们现在有足够的证据说明，那里的昆虫远远比我主人想象中的还要可怕。$B$B我需要有一个信使到奥格瑞玛去找贝尔戈洛姆·石槌。这个任务并不简单，你必须要严肃地对待这个任务。$B$B贝尔戈洛姆一般就在战士公会外面。', '把科兰的密信交给奥格瑞玛的贝尔戈洛姆·石槌。', '啊，科兰的信。他一直以来都是个忠实的仆人，我刚才还在想着他在十字路口干得怎么样了呢。', '$C，我嫉妒你，因为看起来你已经在奥格瑞玛城外的世界中游历很久了。$B$B如果萨尔不需要我的才能，我就会像你一样四处旅行。但是萨尔是个优秀的领导者，我相信他的判断力―只要他需要我，我就会继续留在这儿。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1146, '疯狂的虫群', '这么说，科兰对这些昆虫得出和我相同的结论了——它们的威胁确实比我预想的要大。$B$B几天前有一个从千针石林回到我这儿的猎人受了重伤，现在情况非常危急。他是和一个突击队一起被派去执行任务的，本来他们要将一个矮人挖掘队从闪光平原驱逐出去，但是在行动中，许多这种昆虫从挖掘场的一个岩洞里倾巢而出，几乎使突击队全军复没。$B$B突击队是由摩克塔·克林率领的，现在他们正在闪光平原的边境上寻求庇护。把我的这封信交给他吧。', '把贝尔戈洛姆的密信交给千针石林的摩克塔·克林。', '别在意那些隆隆作响的声音，平原上的那些哥布尔和地精开着他们设计的奇怪机器比赛，这就是他们所说的科学。在千针石林这里还有许多更大的威胁，其中一个威胁使我的队伍差点全军复没。$B$B但是在得到奥格瑞玛的贝尔戈洛姆的命令之前，我们要留在这里坚守阵地，日夜保持警惕。', '$C，战争把我的队伍带到了闪光平原上，那么是什么把你带到这儿来的呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1147, '疯狂的虫群', '嗯，看来贝尔戈洛姆确实开始重视这些怪物了，他想把它们打回老巢去。$B$B在我看来，我们这次的任务不光是赶走探险者协会派来的矮人，接下来还要用剩下的队伍去进行另外一次战斗。仅凭我们自己是无法赢得这样的战斗的，至少在当前的情况下是这样。挖掘场就在这里的南边，那里应该没有什么该死的矮人了。那么，你能帮我们去清除那些可恶的虫子吗？', '杀掉5只异种搜寻者、5只异种筑巢蝎和5只异种侵略者，然后向千针石林的摩克塔·克林复命。', '哈!$N，溅到你身上的那些脓液让你变得更好看啦!那些该死的虫子让你现在浑身都散发着臭气，别靠科多兽太近，你会吓得它们四散狂奔，或者直接把它们给惹火了。$B$B从你身上的气味就可以知道你已经完成了任务，感谢你，$N。', '有很多旅人会去观看那些赛车比赛，我相信我们可以说服足够多的探险者去帮助我们击退这些昆虫。我的队伍在接到命令之前是绝对不会离开这里的。', '', '去千针石林找铁石营地的摩克塔·克林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1148, '虫群的样本', '你仔细观察着这个壳。当你把它拿在手中翻来复去观察的时候发现它的构造很复杂，这让它变得异常坚固。这个壳不同于你所见过的任何东西。你进一步检查尸体，发现这些生物非常有力，而且进化程度也很高。$B$B再看看这个壳，你想科兰应该会有兴趣进一步研究这些生物。这可以帮他搞清楚它们到底是什么，以及它们是从哪儿来的。', '收集1颗异种蝎的心脏、5只异种蝎的爪子和3个完整的异种蝎壳，把它们和你手中的这个破碎的异种蝎壳一起交给十字路口的科兰。', '啊，你最近见过摩克塔?他总是很照顾我。很遗憾听说他不得不把时间都花在他的小队身上，而不能亲历千军万马的战场，但是对他来说，只要能有机会干掉那么几个探险联盟的成员就足够开心了。$B$B谢谢你把这些昆虫带给我，$N。结合在巨人旷野发现的虫卵，我们应该可以对这些昆虫究竟是什么以及它们抱有怎样的目的有一个大概的了解。', '啊，$N，很久不见了，我能为你做些什么吗?看来你最近经过了不少战斗的洗礼。你经历的战斗越多，你的经验就越丰富，你也会变得越发强大。', '', '去贫瘠之地找十字路口的科兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1149, '信仰的试炼', '你已经找到我了——或者是命运把你带到了我这儿，不管怎么样，现在你来到了这里，一段新的旅程即将开始。$B$B生命是由多种要素构成的：精神，身体，思想。某些要素可以由它所属的文化传统来衡量，而某些要素……我们就只能期望是自己与生俱来的特质了。如果你同意的话，我将要求你进行针对这些要素的试炼。$B$B如果你通过了这些试炼，你将变得更为强大。如果你没通过，你也许会感受扭曲虚空的黑暗。$B$B第一个试炼就是信仰的试炼。', '如果你有坚定的信仰，就从那个可以俯瞰千针石林的木板跳下去。', '我们只有在面临不可预见的灾祸时才能发现自己的精神到底能有多么强大。在不知道自己是否能够存活的情况下，你为了信仰纵身一跳。你的思想已经得到了升华，你的精神已准备就绪。$B$B如果你愿意，那就准备迎接你的第二个试炼吧。', '信仰，它比某些人想象得更为重要。$B$B有时你信仰的是什么并不重要，重要的是你要有自己的信仰。', '', '去千针石林找风裂峡谷的多恩·平原行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1150, '耐力的试炼', '我很高兴看到你的勇气依然不减。既然你的信念已经不可动摇，那么现在就让我们来对你的体能进行试炼吧。$B$B首先是耐力的试炼。到乱风岗西边的飞羽洞穴去一趟，进入那些鹰身人的巢穴最深处，毁掉它们的粮食储备\r\n。那样肯定会让它们勃然大怒，如果你能够在鹰身人的围攻之中生存足够长的时间，那么格林卡·血啸就会亲自出来对付你——杀了她，把她的爪子带给我，以此来证明你完成了试炼。', '把格林卡的爪子交给千针石林的多恩·平原行者。', '即使按照$r的标准来看，格林卡也是相当强大的。你应该为你今天的成就感到骄傲。$B$B你已经在信念的试炼中经展示了你的精神力量，现在又在对抗飞羽鹰身人的战斗中显示了你的耐力，但是新的试炼将继续进行。', '你必须在精神上、身体上和意志上都做好充足的准备，才能去迎接未来的挑战。$B$B我们经常未经准备就草率行事，并为此付出惨痛的代价。当年轻的冒险者准备离开他们圣洁的家园外出闯荡时，我会帮他们为可能面临的危险做好准备，我视这种职责为己任，不论他们属于哪个部族。', '', '去千针石林找风裂峡谷的多恩·平原行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1151, '力量的试炼', '在远古之神的时代，元素生物主宰着世界。他们崇拜远古之神，这些神灵用他们的力量将元素生物和世界紧密地结合了起来。当远古之神消失时，元素生物便从我们的世界上消失了，现在只有非常强大的法师才能将它们召唤回来。$B$B当然万事皆有例外，有些元素生物很强大，足以凭自己的力量在这个世界上生存，其中一个就是罗卡里姆。$B$B为了通过力量试炼，你必须在千针石林里找到罗卡里姆，然后杀了它。', '把罗卡里姆的碎片交给千针石林的多恩·平原行者。', '力量试炼完成了。你显示了你的力量和勇气，看来你已经为最后的试炼做好了准备。', '罗卡里姆被千针石林的半人马部族称作重锤，原因是他的拳头会击碎一切胆敢挡住他去路的生物。', '', '去千针石林找风裂峡谷的多恩·平原行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1153, '新的矿石样本', '$C，你过去帮我做了不少事情。酋长对我所完成的工作非常满意，并且要求我继续负责这里的一系列任务。我在酋长面前对你的作为大加赞赏，现在我要再次请求你的帮助。$B$B近来有一批旅行者从南方过来，他们在一个被称为千针石林的地方杀死了一个狗头人，从它身上得到了一块非同寻常的矿石，但这些旅行者不想卖掉它。我想要弄到一个那样的矿石样本来进行研究。', '从砂齿掘地工或砂齿勘探员那里找一块未精炼的矿石样本，把它交给陶拉祖营地的塔特纳克·钢炉。', '$N，这是一块很好的样本，确实很好。$B$B那些旅人们发现的矿石对我来说已经没有意义了。$B$B我要立即开始着手工作了。如果能够证明它确实很强大的话，我将用这个为大酋长铸造一把武器，以此来证明我们的成功。$B$B我永远不会忘记你的帮助，$C。', '我又见到那些旅人了―他们连一块矿石也不卖给我。我唾弃他们，因为他们不愿为大酋长效力。$B$B这些旅人会像懦夫一样在战场上死去，而不会像所有部落的勇士一般在战场上奋勇作战。', '', '去贫瘠之地找陶拉祖营地的塔特纳克·钢炉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1154, '知识试炼', '你已经通过了多恩的试炼，现在你想通过下一个试炼了。非常好。但是到当前为止，你面对过的挑战还都是小儿科。锻炼你的身体很容易，但锻炼你的思想就完全是另外一回事了。$B$B让我来简单地解释一下：找到我说的那本书，研究它，然后回答我提出的关于其内容的问题。$B$B你一定会问是哪本书？是《巨龙的遗产》。它在灰谷南部的朵丹尼尔的底部，被死去的德鲁伊和杀害他们的凶手保护着。', '找到《巨龙的遗产》，把它还给位于灰谷和石爪山之间的石爪小径里的布劳格·幽魂。', '这就是我提到的书。希望你能正确回答我的问题……除非你忘了研究它的内容。$B$B准备好之后就来找我，我将向你提出一个问题。', '你研究完这本书之后就把它给我拿来，在你归还书之后，我才会向你发问。', '', '去石爪山脉找石爪小径入口附近的布劳格·幽魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1160, '知识试炼', '我会告诉你必须去寻找的东西，我还会向你提出我的问题，但我做这些并不是因为你想证明你自己。知识远比力量重要，即使别人在能力上超越了你，你对世界的认知也会让你更胜一筹。$B$B到提瑞斯法林地北部的修道院去一趟，在那儿的图书馆里有一本名叫《亡灵的起源》的书，它曾被那些现在已经堕落了的圣骑士用来对抗我们。$B$B把这本书给我拿来。', '找到《亡灵的起源》，把它交给幽暗城的帕科瓦·芬塔拉斯。', '这就是我派你去找的书。$B$B<帕科瓦注视着这本书，用手掌轻轻地抚摸着封面。>$B$B现在你希望能有个问题来证明你的思想和你的身体与精神一样强大。如果你对这本书进行了足够长时间的研究的话，我就向你提出问题，你也就能完成这些试炼了!', '我希望你在偷走血色十字军的书之前让他们好好吃些苦头。$B$B我对他们那类人的评价并不是没有根据的。十字军也许曾是圣光的追随者，但是现在他们却想要消灭任何与他们的信仰不相符合的生物。他们相信所有的不死生物―无论是被遗忘者还是天灾军团―都必须被清除，甚至连曾经踏上不死生物的土地都是可以招致杀身之祸的理由。他们简直就是白痴。', '', '去找幽暗城的帕科瓦·芬塔拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1164, '科娜塔一家', '贱人！猪头！科娜塔竟然还活着！我在这里受苦受难，她居然全家和睦健康，人丁兴旺的。我被她抛弃了！$B$B我已经没有家了，他们都被天灾带走了。我的财产也都在战争中被抢光烧光了。这些也就算了，然而就是她和她的那些野种们，竟然厚着脸皮趁我不在的时候偷走了我家最后一件值钱的东西。$B$B我倒是不再关心那些被偷的东西了。现在我要的是他们的徽记！$B$B到阿拉希高地去，避难谷地的东北方有一个达比雷农场，去那里把他们都干掉！', '将科娜塔、法迪尔和马塞尔的徽记交给幽暗城的吉纳维·卡隆。', '你是代表着复仇信念的$C，我要对你鞠躬以表示感谢。$B$B既然那母牛已经死了，她的野种也不会再在艾泽拉斯大陆上出现了，这样我就可以把我的全部精力投入到一些对自己更有利的事情中。你把她们都给结果了以后没忘记搜搜那个农场吧?', '杀光他们，把他们的头拿来!', '', '去银松森林找幽暗城的吉纳维·卡隆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1166, '莫格穆洛克的任务', '向莫格穆洛克大王鞠躬致敬吧！$b$b是雷克萨让我做了石槌氏族的领袖！$b$b我是个好领袖，是我保卫氏族安全。$b$b大龙来了，烧了我们的家园，是我这么个有头脑的食人魔在这儿给氏族找了个新家。$b$b离开原来的家的时候太匆忙，我忘了点东西。小$r，去把我的东西拿来。往南走，去拿回我的烈酒、鼻烟和保险箱。你做好了我就会喜欢你。', '蕨墙村的莫格穆洛克大王要你从石槌废墟拿回他的烈酒、鼻烟和保险箱。', '你是个好$r，我一直想着这些东西。我现在很喜欢你。', '我想喝酒，想要我的鼻烟，还有保险箱!你去为莫格穆洛克主宰把东西拿回来。$B$B去南边，我们以前的家。我太忙了，没法带着巨魔去拿。', '', '去尘泥沼泽找蕨墙村的莫格穆洛克大王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1168, '黑龙军团', '雷克萨让莫格穆洛克做大王。莫格穆洛克只知道权力，很少关心食人魔。$b$b黑龙杀了很多食人魔，还杀了萨尔格的妻子。莫格穆洛克叫我们逃跑，让我们到这儿来。$b$b食人魔应该战斗。食人魔不逃跑。莫格穆洛克只关心他自己。$b$b我只把石槌村叫做家。我喜欢南边。$b$b帮食人魔打黑龙军团。我们要复仇。我们要回家。', '蕨墙村的萨尔格要你去杀掉10个火鬃斥候，10个火鬃灰尾龙人和5个火鬃守卫。', '你消灭了不少黑龙，你是个勇敢的$r。$B$B我很高兴。', '莫格穆洛克让所有巨魔留在这里，保卫这里的安全。我觉得巨魔应该去消灭黑龙，把原来的家夺回来。$B$B你来帮巨魔夺回原来的家。帮巨魔复仇。', '', '去泥尘沼泽找蕨墙村的萨尔格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1169, '群龙之首', '莫格穆洛克那个懦弱的傻瓜只知道权力，他整日和萨尔格争夺着氏族的领导权，大概只有我才在想着要找出袭击我们以前家园的邪恶势力的源头。$b$b干嘛用这种疑惑眼神看我，$n？你以为我会像个粗俗的混蛋那样说话吗？就因为我是个食人魔？$b$b说正事吧，从那些大尺寸小的黑龙身上弄些心脏和舌头回来给我，也许我可以找出这邪恶的源头。', '蕨墙村的德拉兹辛比要你给他收集7条灼热之舌和7颗灼热之心。', '收集这些心脏和舌头确实是件危险的事。我会深入研究这个秘密，找出袭击我们以前家园的罪魁祸首。', '只要有了黑龙的舌头和心脏，我就可以找出是什么样的卑鄙野兽把它们带到了我们的家园里。我们对这些侵略者的了解越深，就越有可能找到除掉它们的办法，收复已毁灭的石槌村。$B$B当然，要说服莫格穆洛克挪动他那肥胖臃肿的身体离开这个鬼地方根本是不可能的任务……', '', '去尘泥沼泽找蕨墙村的德拉兹辛比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1172, '奥妮克希亚的血脉', '黑龙谷到处都是奥妮克希亚的子嗣，决不能让它们继续繁殖下去了！$b$b赶紧到尘泥沼泽南部的巨龙沼泽去，那儿肯定是奥妮克希亚的巢穴。找到那里的龙蛋，把它们给毁了。$b$b如果他们还在不断滋生，我们就别想夺回石槌村。$b$b至于莫格穆洛克这个家伙……我自有办法。', '蕨墙村的德拉兹辛比要你去毁掉5枚奥妮克希亚的蛋。', '太出色了!奥妮克希亚还得再等一段时间才能产出更多卵来。$B$B我代表我的族人感谢你，$N。$B$B我已经要求你做了太多，不过你还可以为石槌氏族做最后一件事。$B$B莫格穆洛克不适合领导我们，而萨尔格却是个出色的领袖，只不过因为年纪和伤痛而无法胜任。用武力把莫格穆洛克从这儿赶出去吧，只有这样我们才能选出一个新领袖，带领我们重返南方的家园。', '你必须尽快赶到黑龙谷去，$N。如果再不对巨龙泥沼里那些奥妮克希亚的卵采取行动的话，我们就要面对铺天盖地的敌人了。$B$B毁了她的卵!不要让黑龙肆虐我们的家园。', '', '去尘泥沼泽找蕨墙村的德拉兹辛比。', '摧毁奥妮克希亚的蛋', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1173, '挑战莫格穆洛克', '你竟敢挑战莫格穆洛克？$b$b啊啊啊啊啊啊啊！$b$b我来踩扁你这个小$r！$b$b什么时候准备好挨揍就告诉我。', '打败莫格穆洛克，再把消息带给蕨墙村的德拉兹辛比。', '那个懦弱又臃肿的莫格穆洛克像个受惊的小阿一样逃跑了。你做得很好，$N。$B$B现在我们要选一个新领袖来帮助我们重新夺回我们的家园。', '我以为你准备把莫格穆洛克赶出村子，你却跑来要和我聊天?', '把莫格穆洛克赶出蕨墙村。', '去尘泥沼泽找蕨墙村的德拉兹辛比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1175, '安全隐患', '自从地精的红雷赛车和一只大蜥蜴撞了个满怀之后，科鲁克莱德就雇了我去看守赛道。我不知道平原上的这些动物都是吃什么的，居然长得这么大，但我们必须多加小心，免得它们在比赛时突然跑进赛道里。$b$b我跟你说啊，如果你想打点零工的话，那就去把这些蜥蜴赶走吧。', '为闪光平原的赛道管理员泽尔林杀死10条盐石蜥蜴、10条盐石水晶蜥蜴和6条盐石凝视者。', '我希望你没有把那些跑进赛道的蜥蜴给干掉!它们的尸体在太阳下需要很长时间才能腐烂，到时候还要我一铲一铲地清理干净。', '整日清理赛车事故中遗留下来的残骸让我头痛不已。', '', '去千针石林找沙漠赛道的赛道管理员泽尔林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1176, '减轻负重', '说到赛车，每一点都很重要！不论是动力输出的调整，压力线圈的松紧，或者是对于整部机车重量的控制，每一项都很关键，所以你必须考虑所有的东西。$b$b我们用秃鹫的骨头对赛车进行了改造，这样就提供了力量与重量的完美平衡，真棒。更棒的是，我们可以很容易地得到更多的秃鹫骨头，因为这一带到处都是秃鹫。$b$b去帮我找一些秃鹫骨头来，我会给你个好价钱的。', '给闪光平原的普兹克找10根空心秃鹫骨。', '太好了!这些部件终于让我可以开始工作了。$N，谢谢你!', '你找到秃鹫骨头吗?我正准备着手改造驾驶模组，但是在拿到我需要的部件之前，我还不想把机身拆开。', '', '去千针石林找沙漠赛道的普兹克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1177, '饿！', '马德是大食人魔。$b$b我饿了。$b$b去抓点鱼来。给马德找吃的。$b$b你喂饱马德，不然马德就吃你。', '尘泥沼泽北部的马德克拉什要你去抓8条泥鳍小鱼。', '我喜欢吃鱼头!$B$B吃鱼头，不吃你。', '给我吃的，不然我就吃你。', '', '去找尘泥沼泽的马德克拉什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1179, '防撞头盔', '你听说过闪光平原吗？这是一片位于卡利姆多大陆上的盐碱地，就在千针林大峡谷的南面。这是块绝佳的竞速场地，因为……它实在是太平坦了！$B$B有一对侏儒兄弟，嗯，他们是我的朋友，就在那儿试验他们新近研制的火箭车，我听说这玩意跑得还挺快，快到频频撞车的地步，把驾驶员都给撞出脑震荡来了。$B$B所以这两个家伙让我帮他们弄几顶蒸汽坦克驾驶员的头盔。可是我这边还有别的任务，根本抽不出身来！$B$B你能替我跑个腿吗？', '给千针石林闪光平原上的维兹尔·铜栓捎去一箱防撞头盔。', '啊!满满一箱的盔帽!万岁!$B$B也许现在我们就能说服某个驾驶员来开我们的车了……', '注意你前进的方向!要高度集中!你看，这是个非常精密的装置，如果我们想要获胜，一切都得运转得完美自如才行!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1182, '地精赞助商', '瞧，纳菲瑞提湖那边的地精风险投资公司的伐木机上都装备了最新型号的燃料调节器。我觉得，普兹克要是能拿到调节器的详细设计图，一定可以善加利用它。糟糕的是，那边的工头比我预计的要精明得多，要取得设计图似乎并不容易。$b$b你看起来应该有能力去拿到那张设计图。据我所知，他把那些东西都锁在了屋子里。', '将燃料调节器的蓝图交给藏宝海湾的大财主里维加兹。', '嗯，先让我把这些蓝图复制一份，然后你就可以直接把它们送到普兹克那里去了。别让他觉得我这个赞助商把他给忘记了。', '尽管我颇不愿意承认这一点，但这群地精的发明确实很不错。我们的伙计需要他们搞出来的这些新发明。', '', '去荆棘谷找藏宝海湾的大财主里维加兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1183, '地精赞助商', '你现在就赶快出发吧。替我向普兹克问好，顺便告诉他，如果他需要什么东西，就尽管跟我说。我期待着他能马上打破记录！', '把燃料调节器的蓝图带给闪光平原的普兹克。', '我真希望你搞来的这些设计图是完整的，不过显然这些东西就已经足够改进我们的机械设计了。谢谢你，$N。有了这些，我就能画出改良的设计图，并很快将它应用到我的赛车上了。', '$N!你拿到新的燃料调节器了吗?', '', '去千针石林找闪光平原的普兹克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1187, '拉泽瑞克的调整', '我知道，普兹克是个伟大的机械师，但是他不敢加大油门赶超别人。但我不像他那么胆小。$b$b在普兹克赛车的设计完成后，我花了点时间做了一些小小的修改。把控制器松一松，改造某些结构，增加更多的润滑剂，诸如此类。$b$b我从加基森的史瑞夫那里订了一个爆盐增压器，但是那运货的飞艇却一头栽进了尘泥沼泽！$n，帮我去把东西取回来吧！', '为闪光平原的拉泽瑞克取回爆盐增压器。', '看看这个美妙的东西吧!强大的爆盐动力，足足有十五磅!一旦我把它装到赛车的侧身上，我就能在赛道上飞速驰骋了，那些地精将被我轻松击败!', '我是怎么做到在赛道上风光无限而又毫不出错的呢?我跟你说吧，这就是我与生俱来的天赋。', '', '去千针石林找沙漠赛道的拉泽瑞克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1188, '安全第一', '等等，这是怎么回事？史瑞夫打开了保险装置？这样会限制推进器的输出功率的。我说过那个装置要关掉！对我来说开着那东西一点好处也没有！$b$b你必须把这个拿到塔纳利斯沙漠中的加基森去，让史瑞夫把那该死的保险装置给我拆了。', '把塔纳利斯爆盐增压器交给加基森的史瑞夫。', '只有拉泽瑞克才会注意到这个，然后他就非要我给这个推进器装个安全锁不可。这个推进器完全是使用爆盐动力驱动的。我已经对它的结构进行了特别的修改，保证它能够输出更多的动力，但是除非把动力调到十一节，否则拉泽瑞克这个速度狂是绝不会满意的!', '你肯定知道，基兹莫瑞配件店能够满足所有技工的要求!有什么我可以帮你的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1189, '安全第一', '看，我已经按照拉泽瑞克的要求去做了。我跟他说过，在关闭安全装置时要当心点，否则即使是最小的错误也会酿成大错，轻则让整辆赛车无法移动，重则把他直接在车里烧成灰。$b$b如果真的那样的话可就太丢人了，我们到哪里去找第十九个愿意入伙的赛车手呢？', '将改进型爆盐增压器还给千针石林闪光平原的拉泽瑞克。', '现在才有点像样了!我真希望看看那帮地精瞧见我装上这东西之后的表情。$B$B唉，我又要忙着创造新的世界纪录了!', '你能相信普兹克居然在赛车里加了一桶沙吗?我车座下面放着一桶沙还怎么挂到最高档?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1192, '精铁矿石', '', '', '太好了!我会让弟兄们马上开始干活，为下一场比赛所需的部件做准备!', '我想将这些精铁应用于我们赛车的每个部件中，但我需要大量的原始精铁矿石来制造这些部件。$B$B渡过无尽之海，到卡兹莫丹南面的荒芜之地去，在那一带的奥达曼挖掘场里应该能找到不少精铁矿石。$B$B地精已经有了他们自己的供货管道，所以我们一定要找到我们的供货管道来赶上地精的开发进度。', '', '去找千针石林的普兹克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1193, '破碎的陷阱', '', '', '你将瑟银零件嵌入陷阱上的相应位置，并将冰霜之油灌了进去。当最后一滴油流入了陷阱的机关之后，陷阱恢复了正常状态。$B$B现在就等着某个心不在焉的巨魔上钩啦!', '你面前摆着一个巨大的陷阱，它已经坏掉了。看起来那些巨魔似乎尝试过修理它，但是没成功。一张匆匆写成的便笺摆在陷阱旁边，令你惊讶的是，便笺上面居然写明了修理陷阱所需要的材料:一个瑟银零件，外加一些冰霜之油。如果你能修复陷阱，那么当某个巨魔踏过它的时候就会被困住。$B$B幸运的是，似乎没有几个巨魔能读懂这张便笺上面的字。$B$B你真是幸运到家了。', '', '去找奥特兰克山脉的损坏的陷阱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1195, '神圣之火', '千针石林的加拉克半人马一直在保护着一件神器，它的历史可以追溯到半人马刚刚在这片土地上出现的时候。$b$b我们要得到它，但我们必须得有一瓶来自于暗夜精灵月亮井的水。$b$b要取水还必须找一个特殊的瓶子，在灰谷森林中心地带靠近林中树居一带出没的树妖或许就有这种瓶子。在靠近弗伦河西岸的大路南面有一口月亮井，你可以在那里装满水，然后把它带回来给我。', '把装满水的蚀刻瓶交给雷霆崖的赞金·石蹄。', '非常好。劳恩会对此十分满意的。你能把这个带给他吗?你也许会喜欢上千针石林的。', '我们得到那瓶水之后就要尽快把它送给我在千针石林的朋友，劳恩。他需要这瓶水，也比我们更了解它的用处。', '', '去莫高雷找雷霆崖的赞金·石蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1196, '神圣之火', '把这装满水的蚀刻瓶给乱风岗的劳恩·峭壁行者带去吧。你可以搭乘贫瘠之地南部边境的升降梯去千针石林。', '把装满水的蚀刻瓶交给乱风岗的劳恩·峭壁行者。', '嗯，是的，这瓶水对于我们完成目标很有帮助。因为和林精和半人马有共同的祖先，因此月井的水一定能帮助我们解开环绕半人马遗迹的永恒火焰的保护。', '你是赞金派来的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1197, '神圣之火', '你找来的水可以暂时浸湿守护半人马遗物的火焰，但是效果不会持续很久，所以你必须行动迅速。$b$b半人马的要塞——加拉克峭壁——就在这里的北边，火焰就保存在那座重兵把守的要塞中。$b$b小心点，加拉克半人马的数量众多，他们决不会轻易放弃如此珍贵的东西。', '拿到裂开的蹄子，把它交给乱风岗的劳恩·峭壁行者。', '我感觉到这只蹄子中有股奇怪的能量……我们肯定可以从中找出一些有关半人马的新情报。$B$B谢谢你，$N。现在我必须开始研究这东西了。', '我在等你拿来裂开的蹄子―你拿到它了吗?', '', '去千针石林找乱风岗的劳恩·峭壁行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1199, '暮光之锤的末日', '通过祭祀上古之神的古代仪式，暮光之锤的成员获得了强大而混乱的力量，这些信徒正在试图唤回他们黑暗的主人，在这个世界上继续传播死亡与恐惧。$b$b现在我们可以确信，暮光之锤已经和纳迦结成了联盟，集结在灰谷海岸边的黑暗深渊中。$b$b我们必须阻止他们在那座古代神殿的深处所筹划的险恶计划。$b$b向暮光之锤发起攻击，然后带回你的战利品，我们会重重酬谢你所做的一切。', '收集10个暮光坠饰，把它们交给达纳苏斯的银月守卫玛纳杜斯。', '你无疑是个英勇而高贵的$r，银色黎明感谢你为抵抗邪恶势力而做出的贡献。', '黑暗深渊曾经是古代夜精灵的神殿，里面有一眼充满强大魔力的月井。谁也不知道暮光之锤到底在那里酝酿着怎样的阴谋。$B$B你的行动进展如何了?', '', '去达纳苏斯找工匠区的银月守卫玛纳杜斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1200, '黑暗深渊中的恶魔', '力量在我身上逐渐流失，我需要你的帮助！$b$b很久以前，这里曾是雄伟的月神之殿。然而，不幸却降临了这里，上古之神的堕落势力从地下突现，玷污了神圣的月亮井，最终使得这里成为了一片废墟。$b$b阿库麦尔，上古之神的仆人，从水中突然出现。$b$b暮光之锤的信徒与纳迦联合在一起，占领了这片土地。梦游者克尔里斯领导着他们为阿库麦尔而战，以许多无辜的生命来换取邪恶的力量。$b$b你一定要阻止这些恶魔！杀了克尔里斯，把他的徽记交给达纳苏斯的塞尔高姆！', '把梦游者克尔里斯的徽记交给达纳苏斯的哨兵塞尔高姆。', '克尔里斯一直都在躲避我们的追捕。$B$B看起来只要有邪恶势力出现的地方，就一定会有克尔里斯的影子。有一段日子我们一直以为他死了或者是失踪了。$B$B你所做的这件事是有完美的意义的，你结束了他的统治，挽救了许多无辜的生命。$B$B以圣光之名，为了个人的利益而牺牲无辜的人是天理不容的!$B$B你完成了一件伟大的事情，$N。我代表银色黎明向你致敬。', '时间是很宝贵的东西啊，$C。$B$B我在达纳苏斯的责任是确保银色黎明的兴盛和消灭那些盘踞在卡利姆多的邪恶势力。$B$B有事快说，不然就走吧!', '', '去找达纳苏斯的哨兵塞尔高姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1201, '塞拉摩间谍', '部落和联盟正处于某种令人不安的休战期。两大阵营之间的小规模的冲突和暗杀活动时有发生，而我们的职责就是确保部落始终占据上风！$B$B现在正是行动的时候。$B$B联盟派了一些间谍驻扎在蕨墙村的东部，他们监视着村子，把我们的动向报给告塞拉摩，决不能让他们继续下去。$B$B去追踪那些间谍，把他们干掉。让他们的头儿知道我们决不会允许他们的间谍在我们面前晃来晃去！', '杀掉9个塞拉摩间谍，然后回到蕨墙村去见纳泽尔·血矛。', '做得好。他们的间谍经验丰富，不过他们始终逃不出部落警惕的眼睛。', '你找到间谍了吗，$N?', '', '去尘泥沼泽找蕨墙村的纳泽尔·血矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1202, '塞拉摩码头', '$N，我们派了两个间谍到一艘停泊在塞拉摩码头的船上偷文件。他们找到了文件，不过却被人发现了行踪，只好把文件丢进海里。$B$B有一个间谍后来逃脱了，但是他却两手空空地回来，向我报告了他们失败的行动。现在我把这个任务交给你。$B$B文件就装在一只小提箱里，而那提箱已经沉在塞拉摩码头下面的海水里了。找到那些文件，把它们交给我。', '把指挥官的文件交给蕨墙村的纳泽尔·血矛。', '你做得很好，$N。这不是个容易完成的任务。但是我们的上级对你找到的文件有很高的评价。', '你拿到文件了吗，$N?这些文件对联盟的稳定十分重要，因此也对部落的安全十分重要。', '', '去尘泥沼泽找蕨墙村的纳泽尔·血矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1203, '加尔的剑', '我要切点东西，呃……我不能告诉你我要切什么，不过……反正我需要把剑。一种特殊的剑……$B$B我叫它快剑。$B$B你能帮帮我吗？那些鱼人，你知道，像鱼的人，像人的鱼，它们之中有一个名叫刺脊的，手里有一把巨剑，它就在这里北边的海滩附近。$B$B不过，不要等到明天再去找。我切的东西可不能放太久……', '将刺脊的剑交给尘泥沼泽的“沼泽之眼”加尔。', '这真是把好剑，用起来很顺手，锋利无比!谢谢你。谢谢你谢谢你谢谢你!!!现在让我来试试……$B$B嗯，我还是等会儿再试吧。不过正如我所说的，谢谢你。', '你找到我要的剑了??', '', '去尘泥沼泽找水光庄园的“沼泽之眼”加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1204, '泥石龟蟹汤', '我正在研究一道叫作“泥石龟蟹汤”的菜，现在我还需要一些原料……唉，我觉得我真是不适合在尘泥沼泽里长途跋涉！$B$B那么，$N，你能帮我去打猎吗？首先，我需要泥石龟的舌头，这些海龟经常在海岸附近出没。$B$B不过我要的还不是一般的舌头！听说有些泥石龟的舌头是分叉的……$B$B他们说那样的舌头吃起来味道特别好，而且我也很喜欢给我的菜里加点特别的风味……', '给塞拉摩的摩根·斯特恩收集8个分叉的泥石龟舌。', '这些就可以了!谢谢你，$N!$B$B现在我要使出我精湛的烹饪技巧，把这些舌头的味道都给它做出来。$B$B我一定可以做出一道足以让全暴风城的人都赞不绝口的菜!', '你找到分叉的舌头了吗?', '', '去尘泥沼泽找塞拉摩岛的摩根·斯特恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1205, '死沼巨鳄', '死沼巨鳄是一只栖息在尘泥沼泽里的远古鳄鱼，现在是时候让它获得解脱了。$B$B当它挪动着庞大的身躯游过沼泽的时候，那衰老的骨骼饱受碾磨之苦。尽管它依旧有着可怕的力量和年轻时的速度，但老化的躯体却折磨着它内心强大的精神——那是一种激情不减的精神。$B$B然而现在它长期生活在巨大的痛苦中，这种痛苦折磨得它几近疯狂。$N，现在你必须去结束它的生命，把死沼巨鳄引向安宁的天国。', '把死沼巨鳄的牙齿带给雷霆崖的梅洛。', '很好，$N。$B$B我知道这次猎杀并不容易，然而我很高兴得知死沼巨鳄的痛苦已经结束了。', '你拿到死沼巨鳄的牙齿了吗，$N?你结束它的痛苦了吗?', '', '去雷霆崖找猎人高地的梅洛·石蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1206, '加尔和蜘蛛眼', '用眼睛制成饮料的味道非常好，可惜很多生物都只有两只眼睛。$B$B不过蜘蛛有很多眼睛，很多很多。黑雾蛛眼汁很好喝，醇美而味咸！真是没有比那更好的饮料了……$B$B黑雾蜘蛛就在西边的黑雾洞穴里活动。你说这些蜘蛛的名字是来自这个洞的名字呢，还是有别的什么说法？', '收集20颗黑雾蜘蛛的眼球，把它们交给水光庄园的“沼泽之眼”加尔。', '你找到眼睛了!美味无比的蜘蛛眼!$B$B有些眼睛……你瞪着它看，它也会瞪着你看，这种眼睛就要等到最后再吃，在这沼泽地里，只有它们可以和你做伴……$B$B你好啊，小蜘蛛眼!你吃起来就像鸡肉一样，粘粘的，咸咸的鸡肉!$B$B啧啧，太美味了……', '我要的眼睛在哪儿?', '', '去尘泥沼泽找水光庄园的“沼泽之眼”加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1218, '沼泽蛙的腿', '我喜欢烧菜，喜欢沼泽地里特产的美食，比如油炸绿青蛙腿之类的。$B$B不过青蛙腿都用完了。不过庄园附近到处都是青蛙。肥肥的沼泽青蛙。你觉得你能帮我弄些青蛙腿吗？很简单，只需要殴打它们的脑袋，帮我带回蛙腿就可以了。$B$B然后我就可以做出好吃的东西来，好好地饱餐一顿，还能给你一些。$B$B你想尝尝吗？', '为尘泥沼泽的“沼泽之眼”加尔收集10条沼泽蛙的腿。', '啊，就是这个!你马上就可以吃到沼泽炖肉了!', '啊，调味料!给我们的生活来那么一丁点调味料是大有好处的……你说是吧?', '', '去尘泥沼泽找女巫岭的“沼泽之眼”加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1219, '兽人的报告', '你可以在松土里看到一只紧紧握起来的兽人的手，手里抓着一根用骨头刻出来的管子，里面塞着一张粘着泥土的羊皮纸。$B$B羊皮纸上的文字都是兽人的文字……这看上去很重要。', '把间谍的报告交给塞拉摩的艾登中尉。', '嗯……我看不太懂兽人的文字，不过这个好像是一份报告……一个兽人间谍写的报告!', '你有什么要报告的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1220, '维米斯队长', '应该让维米斯队长看看你找到的这份报告，$N，他的兽人语不错。我们得让他知道塞拉摩附近有部落的间谍！$B$B队长眼下正在塞拉摩岛东北面的兵营里。', '把间谍的报告交给盖兰·维米斯队长。', '兽人间谍的报告?!你怎么找到的?不管这个了—先看看上面写了些什么……', '你有东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1221, '蓝叶薯', '蓝叶薯是美味绝顶的佳肴！但是这种东西很罕见，非常非常罕见。它们只生长在贫瘠之地，在剃刀沼泽的地下深处。$B$B不过知道这一点也没什么用，因为如果你不知道它们的确切位置，那么就算近在咫尺你也不一定找得到它们。这就是我训练这些地鼠去寻找蓝叶薯的原因——它们有很灵敏的嗅觉，在五十步以外就能嗅到蓝叶薯块茎的气味。$B$B这差事并不轻松，但是如果你帮我弄来一些蓝叶薯的话，我会付给你一笔可观的报酬。', '找到一个开孔的箱子。$B找到一根地鼠指挥棒。$B找到并阅读《地鼠指挥手册》。$B$B在剃刀沼泽里用开孔的箱子召唤一只地鼠，然后用指挥棒驱使它去搜寻蓝叶薯。$B$B把地鼠指挥棒、开孔的箱子和6块蓝叶薯交给棘齿城的麦伯克·米希瑞克斯。', '太好了，你找到它们了!我可以把这些东西卖个大价钱!$B$B多谢你的努力工作，$N!你真是个出色的合作伙伴。', '$N，你拿到蓝叶薯了吗?', '', '去找贫瘠之地的麦伯克·米希瑞克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1222, '伊格纳兹的逃亡', '太好了，总算碰到一个不是要来吃了我的人了！$B$B我正愁没人来帮我对付这儿的怪物哪，$g兄弟:小姐;，你看来就挺合适。$B$B那个叫摩根·斯特恩的厨子在研究一套新食谱，他让我来这儿采集一点睡菜叶。那家伙可能觉得睡菜叶挺好吃吧。$B$B就在我找睡菜的时候……我发现我被包围了！你能帮我从这儿逃出去吗？哦，对了，顺便在我找睡菜的时候替我断后。', '护送伊格纳兹，然后和塞拉摩的摩根·斯特恩谈一谈。', '伊格纳兹先生刚才带着睡菜叶回来了，他告诉我你帮他摆脱了一个大麻烦。\r\n\r\n谢谢你，$N.下次你去暴风城的蓝色隐士旅店的时候，我会让我叔叔请你吃顿大餐的。', '你看见伊格纳兹先生了吗?我前些日子要他到沼泽地去找些东西，不过他到现在还没回来!', '帮伊格纳兹找睡菜叶', '去尘泥沼泽找塞拉摩的摩根·斯特恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1238, '遗失的报告', '你可以在松土里看到一只紧紧握起来的兽人的手，手里抓着一根用骨头刻出来的管子，里面塞着一张粘着泥土的羊皮纸。$B$B羊皮纸上是一个在塞拉摩侦察了好几个星期的兽人写的报告。$B$B浏览过羊皮纸之后，你决定立刻把它送给蕨墙村的兽人情报官。', '把间谍的报告交给蕨墙村的纳泽尔·血矛。', '做得好，$N。我们的密探玛格.夜眼就在塞拉摩周边活动，他奉命监视塞拉摩城里的动静。$B$B这是他最近的一份报告，也可能是他最后一次报告—根据你所描述的情况，我担心玛格已经死在沼泽地了……', '你有东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1239, '被取下的徽记', '继续挖掘了一番之后，你找到了一颗男性兽人的徽记，上面还有参差不齐的划痕。', '把兽人的徽记交给蕨墙村的纳泽尔·血矛。', '这是玛格.夜眼的头!和我担心的一样，他真的死了。$B$B看他脖子上的伤口!是某种武器留下这样不整齐的割痕，还是某种野兽杀了我们的密探?$B$B我们一定要解开这个谜，$N。我们必须查出玛格是不是死在联盟的手上!', '你还有别的事要报告，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1240, '巨魔巫医', '我们必须弄清楚玛格究竟是怎么死的！唯一的方法就是使用巨魔的巫术。把玛格的徽记拿给肯维雷，他就在荆棘谷的格罗姆高营地里。$B$B肯维雷是暗矛巨魔里最强的巫医，能和玛格·夜眼的灵魂说话的人也只有他了。', '把兽人的徽记带到荆棘谷的格罗姆高营地里，交给肯维雷。', '啊，我看见了。这个兽人的灵魂还在我们的世界游荡，他因为一个未完成的任务而充满了怨念。$B$B好吧，让我们和这个愤怒的兽人说几句话吧……', '你身上跟着一个愤怒的灵魂，我的$g兄弟:姐妹;。你来找肯维雷有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1241, '失踪的使节', '最近我们派出了一名外交使节转至塞拉摩与吉安娜·普罗德摩尔女士会晤，但那位使节没能抵达目的地。$B$B我坚信是迪菲亚兄弟会密谋了这个事件，但我并不清楚具体的过程。使节失踪的消息对外严密封锁，但这件事情迟早要被曝光。$B$B国王的密探已经行动起来，在全城范围内寻找线索，但我打算私底下再找一些人来解决此事。$B$B我的一个老朋友乔贞现在就在英雄谷中。将这封便笺带给他，然后听他的命令行事。', '在暴风城的英雄谷找到乔贞。', '嗯……<乔贞斜着眼睛打量了你一番。>$B$B好吧。我会帮助你的，不过这可不是我自愿的，只是责任使然而已。$B$B有件事情我们得先说清楚:你知道太多你不应该知道的事情了。让这些事情当做我们之间的小秘密吧!别把你知道的事情在酒馆里大声嚷嚷，明白了吗?', '嗯，你最好有个能打扰我钓鱼的好理由。否则，我就让你吃不完兜着走。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1242, '失踪的使节', '把这张便笺带给埃林·提亚斯，除此以外不要和他说任何话。你只需要礼貌地等着他的回答就是了。不用担心，他一定会回答你的。$B$B我必须再跟你清清楚楚地说一遍，$N：把这件事看得认真点，在任何人面前都要管好你的嘴。$B$B你可以在他的奶酪店“提亚斯奶酪坊”里找到他，就在贸易区。祝你好运。', '将乔贞的密信带给暴风城贸易区的埃林·提亚斯。', '什么，有我的信?好吧，我看看……成天到晚工作的人并不是经常能收到木箱或木桶之外的货物的，让我看看上面写了什么。$B$B<伊林一边打开信，一边打量着你。>$B$B你看起来有点紧张，你没事吧，$N?', '你好，$N。我能为你做些什么吗?想不想尝尝我们特制的提亚斯切达干酪?或者来块达纳苏斯乳酪?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1243, '失踪的使节', '乔贞，你这老小子……那么，事情就是这样了，是吧？$B$B好吧，我会处理的。我倒是希望他早点死了呢！$B$B这么着，$N。我会开始派出我在这里的线人，不过你得帮我跑跑腿，好给我省点钱。$B$B到暮色森林的夜色镇去找守夜人巴库斯——他总是在镇子北边的路上巡逻。告诉他你正在为我调查迪菲亚兄弟会的活动，他会把他知道事情一股脑儿都告诉你的。', '将密信带给暮色森林的守夜人巴库斯。', '哦，是提亚斯派你来的，对吗?那就有点不一样了。$B$B看来你根本不害怕潜伏在这一带的怪物。如果你跟他周遭那些人是同一类的话，我敢肯定你能轻松解决那些东西。$B$B那么，我的老朋友要我做些什么呢?', '在这片森林里旅行可不太安全，$N。小心为上，如果你看到任何可疑或者危险的东西，请立刻向守夜人报告。不要试图自己去解决问题，否则出了什么事情我们可无法负责。$B$B不过你我都知道你根本不会在意我的话，而且会不择手段与黑暗中的怪物搏斗，不是吗?哈哈，是呀，你们这些冒险者都是一样的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1244, '失踪的使节', '迪菲亚兄弟会的活动？好吧，他们总是在活动。就算他们按兵不动，我们也仍然视之为威胁。$B$B但现在我认为，最近事情变得有点奇怪。大概是在两三周前吧，他们的许多密探都在腐草农场附近频繁出没。由此看来，那里一定是发生了什么重要的事情。$B$B你为什么不先去那里调查调查呢？记得把你调查到的结果拿给我看看。$B$B那座农场就在由西部荒野进入暮色森林的大路南边。', '找到迪菲亚记事本，把它带回给暮色森林的守夜人巴库斯。', '你毫发无伤地回来啦!真是太棒了。$B$B现在，让我们来看看你找到了些什么吧。这份档案看起来相当正式，与我见过的任何迪亚菲兄弟会的档案都相去甚远，但这也极有可能只是个让你白费心思的把戏而已。', '小心点，$N。我知道提亚斯派来的人个个身手不凡，但这并不意味着这片森林里潜伏着的东西就不会给你造成任何麻烦……特别是在你调查迪菲亚兄弟会的时候。', '', '去暮色森林找夜色镇的守夜人巴库斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1245, '失踪的使节', '哎呀，如果这只是个用来干扰你的视线的幌子，那他们也未免搞得太复杂了，我也不太清楚这东西到底是什么。把它交给提亚斯吧——他一定能弄明白其中的意义。千万小心，别让任何人把它抢走。我们都知道，这事可比我的命还重要，甚至比他的命还要重要。$B$B最后，拜托你一件事，$N，别对任何人说起我帮助过你。我的上司如果知道我对这件事有所了解而又没有向他们汇报的话，没准会绞死我的。', '将迪菲亚记事本带给暴风城的埃林·提亚斯。', '好得很!这东西倒是蛮有趣的。乔贞和德拉维拉上我确实是选对人了。$B$B看来迪菲亚兄弟会正在很卖力地完成他们的计画。嗯……这是什么?“拳”? 这名字有点耳熟呀。', '啊，你回来了，而且看起来没有缺胳膊少腿。你我都知道我们不是来这里做乳酪买卖的，所以就别废话了吧。巴库斯帮上什么忙了吗?还是说，你根本就没去过暮色森林呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1249, '失踪的使节', '你说是埃林派你来的？好吧，现在我要拿出十倍的热情来招待你。想要什么尽管说，我会竭尽全力来帮助你的。$B$B嗯，你说的是干柴？似乎是没听说过的名字，但我一定会注意他的。$B$B别抬头，$N，壁炉旁边的那家伙正往我们这边看呢。这家伙似乎有点太专心地听我们的对话了，你明白我的意思吗？如果我是你，我就会趁他溜走之前好好教训教训他。', '在塔伯克·贾恩逃跑前制服他，然后回米奈希尔港旅店去找米克哈尔。', '抓住他了吗?做得好!我很意外他竟然就是『瘦子』。$B$B说老实话，我从没有想到过我会这么喜欢这种秘密活动带来给我的刺激，我看我的老毛病是改不掉的了。不过千万别跟伊林说这个—他要是听到我怀念这样的工作，八成会想办法把我弄回暴风城去工作。$B$B我很高兴能在米奈希尔给你帮些小忙。如果你还需要别的东西，请尽管开口。', '你没让他跑了吧?那小子注视我们时的样子有点诡异。', '击败塔伯克·贾恩', '去米奈希尔港找深水旅店的米克哈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1251, '黑色盾牌', '有一面被烧毁旅店的大火熏黑了的铁盾牌和倒塌的烟囱连在一起，这根烟囱是树荫旅店烧毁之后留下的几段残砖断瓦中的一部分。$b$b这面铁盾牌可以从烟囱的砖上拿下来。', '把被熏黑的铁盾牌带给蕨墙村的克罗格。', '虽然人类的装饰品味很奇怪，不过我觉得他们不会把一面铁盾挂在壁炉上方做装饰。可能是放火烧旅馆的人放在那儿的。$B$B这是个警告?或者是个威胁?', '你手里拿着什么，$N?是从树荫旅店的废墟里找到的东西吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1252, '帕瓦尔·雷瑟上尉', '地上闪过的一道光芒把你的视线引到碎石的下面。你拨开了碎石，发现灰尘下有一枚白色的徽章，表面上印有金色的船锚，那是塞拉摩的标记。$b$b锚的下面刻着“帕瓦尔·雷瑟上尉”的字样。', '把雷瑟的徽章拿给塞拉摩的盖兰·维米斯队长。', '找到这个守卫的徽章对我来说可不是什么好消息。 $B$B有时候这就意味这有人死在战场上，而我还得把悲伤的消息带给他们的家人，有时我们永远不知道他们发生了什么，还有些时候，事情可能比你想象中的更糟糕。', '你在树荫旅店找到什么有用的东西了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1253, '黑色盾牌', '有一面被烧毁旅店的大火熏黑了的铁盾牌和倒塌的烟囱连在一起，这根烟囱是树荫旅店烧毁之后留下的几段残砖断瓦中的一部分。$b$b这面铁盾牌可以从烟囱的砖上拿下来。', '把被熏黑的铁盾牌交给塞拉摩的盖兰·维米斯队长。', '嗯，我可不是制造武器和护甲的专家。我知道它们的用途，可是不懂如何制造。$B$B这个盾牌和一般盾牌没什么区别，只是旅馆的大火在上面留下了些痕迹。', '你在树荫旅店的废墟里找到什么证据了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1258, '还有螃蟹！', '新菜谱里还需要一种大螃蟹的腿，不过尘泥沼泽的污壳螃蟹可不行！唯一合适的螃蟹在悲伤沼泽里，离这儿很远。$B$B螃蟹腿的壳是构成这道菜的外观的一大要素，所以我必须要新鲜而且没有任何疤痕的蟹腿。一只成熟螃蟹大概只有一条或两条这样的腿，而我却需要大量的螃蟹腿来试验菜谱。$B$B那么，$N……你愿意跑一趟吗？', '给塞拉摩的摩根·斯特恩收集12根新鲜的螃蟹腿。', '这些螃蟹脚真是好材料，$N!蟹壳完整无损，肉也非常鲜嫩。我敢说，你一定是个天生的厨子!', '我对泥石龟舌的研究进展很不错，我相信你找螃蟹脚也还顺利吧?', '', '去尘泥沼泽找塞拉摩岛的摩根·斯特恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1261, '玛尔格的嘱托', '可恶的龙虾人！我是不会束手待毙的！啊…但是…我已经死了，看来它的确是把我杀掉了……$B$B但是我的使命，我的使命啊！$N，你必须替我完成它。$B$B我曾在塞拉摩附近监视一队在海滩上露营的联盟士兵，其中一个士兵身上配戴着一件饰品，是那种镶嵌着很多宝石，再有钱的士兵也买不起的饰品！$B$B那天晚上，我溜进他们的营地，偷走了那件饰品，但是在我返回基地的途中，一个污壳龙虾人杀死了我！$B$B$N，你必须找到那只该死的龙虾人，并夺回那件饰品。', '把宝石坠饰带给蕨墙村的纳泽尔·血矛。', '这个坠子是一名暴风城的士兵所配戴的?$B$B谢谢你，$N。你找出了玛格的死因。但是这个坠子是一个新的谜团，一个可能会对联盟和部落都产生可怕影响的谜团。', '$N，你发现玛格的下落了吗?', '', '去尘泥沼泽找蕨墙村的纳泽尔·血矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1262, '向佐尔报告', '很奇怪的是，玛尔格偷取的这件饰品居然是一个普通士兵的东西。它的主人也许掩饰了自己真正的身份，或者那个士兵本身就是个窃贼！$B$B不管事实是怎样的，总之这是一件贵族的饰品。如果我们想要揭开这个谜团，就必须找出它真正的主人。$B$B带着饰品去奥格瑞玛找佐尔·孤树吧。他对联盟那边的事情颇有了解，应该会知道这件饰品是否和暴风城的贵族们有关系。', '把镶宝石饰品带给奥格瑞玛的佐尔·孤树。', '这件饰品的工艺非常精湛，$N。兽人不会对这种东西感兴趣……$B$B但是许多人类都会的。$B$B让我们看看这件饰品，看看它是否隐藏着什么秘密……一些能够让它主人的身世之谜水落石出的东西。', '你是从尘泥沼泽的蕨墙村过来的?纳泽尔过得如何?他在那里的生意又如何?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1265, '失踪的使节', '亨德尔？是的，我知道这个人。不过你找我的士兵有什么事呢？$B$B埃林派你来找他？嗯，好吧，我感觉有些不妙了。你肯定遇到了麻烦，因此埃林才让你来先找我的。我理解你可能不愿告诉我详情，但请明白这一点：我有责任保护好这片土地。如果你是来制造麻烦的话，最好能先得到我的允许。$B$B据我所知，亨德尔就驻守在塞拉摩外的第一座哨塔上。请自己多加小心！', '在警戒哨岗中打探亨德尔下士的消息。', '你正在找的那个叫亨德尔的人已经不在这儿了，你所掌握的消息，也已经从别的管道传到了普罗德摩尔女士那里。她派我来找你，并帮助你完成任务。如果你不反对的话，我来告诉你在哪里可以找到士兵亨德尔，这样我们就可以把他抓住并送上法庭。', '嗯，$N?', '探索警戒哨岗', '去找尘泥沼泽的大法师特沃什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1269, '帕瓦尔·雷瑟上尉', '地上闪过的一道光芒把你的视线引到碎石的下面。你拨开了碎石，发现灰尘下有一枚白色的徽章，表面上印有金色的船锚，那是塞拉摩的标记。$b$b锚的下面刻着“帕瓦尔·雷瑟上尉”的字样。', '把雷瑟的徽章带给蕨墙村的克罗格。', '我认识这个叫帕瓦尔·雷瑟的人。他是个可怜的家伙……他抛弃了同伴，一个人躲在树林里。$B$B我派了奥格隆去追踪他，还有人怀疑雷瑟偷了我们的物资装备。我想奥格隆是向东南方向去了。', '你找到关于树荫旅店的线索了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1273, '盘问雷瑟', '我花了很长时间终于找到雷瑟了。他躲藏得很好。$b$b奥格隆担心他在沼泽地里待了这么久可能已经疯了，你跟我来，咱们一起去从他那里套出一些我们需要的答案。', '和奥格隆一起去和雷瑟谈一谈，然后回到蕨墙村见克罗格。', '嗯!雷瑟不用再鬼鬼祟祟躲在沼泽地里了，这真是太好了。不过人类都这么虚弱，连这点小小的箭伤都恢复不了，真够丢脸的。\r\n\r\n这条线索似乎是没有进展了，我们得再找其他线索。', '你找到雷瑟了吗?', '和奥格隆一起盘问雷瑟', '去找尘泥沼泽的克罗格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1275, '研究堕落', '愚蠢的血精灵们已经彻底陷入了对魔法的狂热之中了，难道他们没有见到卡利姆多大陆上的萨特与纳迦们身上发生了些什么吗？$b$b我总觉得血精灵们也将会踏上这样一条不归之路，但是艾泽拉斯已经无法再承受多一种被魔法扭曲了心智的怪物了。$b$b我希望能够研究一下萨特和纳迦的脑干组织，这样也许就能了解那些精灵们的命运将会走向何方。在灰谷海岸边的黑暗深渊中有许多萨特和纳迦，你去那里找一找吧。$b$b这将会是一段漫长的旅程，一路小心，$n。', '奥伯丁的戈沙拉·夜语需要8块堕落者的脑干。', '你经历了漫长而危险的旅程，但你的这次行动清晰地表明了你的无私精神。你帮助我进行研究工作，无疑也对艾泽拉斯做出了巨大的贡献。非常感谢你，$N，感谢你为我做的一切。$B$B现在，如果你没有别的什么事，我要开始我的工作了……', '只要我有了足够的样本，就可以开始真正的研究了。有了这些从黑暗深渊里找到的萨特和纳迦的脑干，我就能找出这两种被魔法扭曲了心智的生物之间的联系。$B$B或许……如果我们对这些东西能有足够的了解，我们就能阻止血精灵步他们的后尘，走向堕落的深渊。', '', '去黑海岸找奥伯丁的戈沙拉·夜语。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1276, '黑色盾牌', '啊，我想起来了！莫萨恩是个，嗯，他是雷霆崖的一个受人尊敬的铁匠。我就知道以前肯定在哪儿听过他的名字。$b$b大地之环为了感谢我，送了我一套莫萨恩打造的护甲，他的手艺很不错。$b$b关于莫萨恩打造的盾牌，他自己也许可以告诉你更多。$b$b这不是什么重要线索，不过既然帕瓦尔·雷瑟还什么都没有说，这就是我们所了解的全部了。', '把被熏黑的铁盾牌拿给雷霆崖的莫萨恩看一看。', '是的，你的确是对的，这的确是我做的盾牌。$B$B不过我恐怕也没有太多有用的消息可以告诉你，$N。我打造了很多不同的盾牌和护甲，不可能知道每一个东西的去处。', '你好啊，$C。我能帮你什么忙吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1319, '黑色盾牌', '我很抱歉帮不了忙，$n，不过可以给你介绍个能帮忙的人。卡兹·双链是我们最好的铁匠，他就在铁匠铺给人打铁器。$b$b把盾牌拿给他，看看他能告诉你什么。', '把被熏黑的铁盾牌拿给塞拉摩的卡兹·双链看一看。', '嗯……这东西有点意思。肯定不是塞拉摩这边的铁匠做的，当然更不可能是我做的。', '有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1321, '黑色盾牌', '嗯……我看不出这个盾牌有什么特别之处。我们应该把它拿给铁匠杜高尔，看看他有什么说法。不过我也不抱太大希望……', '把被熏黑的铁盾牌拿给蕨墙村的杜高尔看一看。', '这个盾牌很不错，又重又坚硬。不过杜高尔不需要，我自己做盾牌，不买盾牌，$N。$B$B你应该知道。', '你找我，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1322, '黑色盾牌', '嗯，在盾牌的边上这儿刻着字，可惜烧过了读不出来。$b$b要用些酸液洗干净，用沼泽地里的暗牙蜘蛛的毒液就可以了。那些蜘蛛盘踞在一座旧矿洞里，现在那里被称为黑雾洞穴。给我找点它们的毒囊来，我可以把盾牌清洗一下以便辨认。', '为蕨墙村的杜高尔收集5个酸性毒囊。', '我讨厌蜘蛛，因为它们太大我不能坐上去就把它直接压扁。$B$B多谢你帮我收集它们，$N。现在我就把它们撕开让毒汁倒在盾上……', '你找到蜘蛛的毒囊了吗?', '', '去尘泥沼泽找蕨墙村的杜高尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1324, '失踪的使节', '什么？！你到这里来就是为了指控我和迪菲亚兄弟会有染？！我无法容许你这么侮辱我！看来我非得好好教训教训你才行。', '击败尘泥沼泽的亨德尔下士。', '我向你保证，我们最近都被这一连串的突发事件搞得有点心烦意乱，但请允许我们先把他带回塞拉摩好好审问一番，我们保证一定会找到国王陛下的。$B$B我相信普罗德摩尔女士会乐于答谢你的帮助，如果你有空的话，就去找她谈谈吧。', '又见面了，$N。我希望你不会介意我提供的这点小帮助，但我们绝不能让亨德尔给跑了，或者更糟的让他被灭口。', '打败亨德尔下士', '去找尘泥沼泽的大法师特沃什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1338, '卡尔·雷矛的订单', '有一个名叫弗伦·长须的矮人铸甲匠，我很欣赏他做的东西，那手艺简直是无人能敌。我需要一面新盾牌，而且一定要他亲手做出来的盾牌！$B$B问题是……弗伦住在遥远的南方，在暴风城的矮人区里。他竟然住在人类的领地里！我没法想象他怎么会住在离铁炉堡这么远的地方，那帮人类一定出了足够收买国王的大价钱把他给留在那儿！$B$B如果你正好要去那里旅行一趟，又想顺便挣点钱的话，能不能去弗伦那儿让他给我做一面盾牌？', '把卡尔·雷矛的订单交给暴风城的弗伦·长须。', '哦，是雷矛氏族的成员下的订单啊，那可是一个令人骄傲的氏族，有许多精干的矮人都是那个氏族出来的，而且他们还都是有钱人。$B$B谢谢你，$N。天快黑的时候我就可以开始帮巡山人雷矛打造盾牌了。', '从洛克莫丹那边带来的信?不知道会是谁找我……$B$B请让我看看是怎样的订单吧。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1358, '给赫布瑞姆的样本', '我有一位名叫赫布瑞姆的药剂师同事当前正在卡利姆多大陆工作。他正在研究洛丹伦大陆上的毒物在卡利姆多大陆生物身上所造成的影响。为了帮赫布瑞姆的忙，我收集了提瑞斯法和银松森林一带各种蜘蛛的蛛毒，现在需要找人帮我把这些毒液给他带去。$B$B他就在贫瘠之地的一处名为十字路口的镇子上。要找到他，你必须先搭飞艇到兽人的首都奥格瑞玛去，然后步行向南去杜隆塔尔，最后向西进入贫瘠之地，这样很快就可以到达十字路口了。', '把一箱蜘蛛毒带给贫瘠之地的药剂师赫布瑞姆。', '啊，太好啦。如果起初的那些报告是正确的话，那么这些从心脏里提取的毒液，就能让我对于毒素的知识更进一步。$B$B你来得非常好，$N。这是给你的报酬。', '你有个包裹要给我?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1359, '给金格的货物', '你拿来我的狼心具有与众不同的特质。从中提炼出的特殊毒素甚至可以毒死长着这种心脏的狼！$B$B这让我感到非常惊讶，所以我们必须对此进行深入的研究。把这几份心脏样本送到我的同事药剂师金格那里。你应该可以在幽暗城的炼金房里找到她。', '将狼心样本交给幽暗城的药剂师金格。', '啊，原来是伦弗利尔提到的心脏样品。我真是等不及用它们来进行实验了……皇家药剂师学会对于新型毒药永远都是充满兴趣的。', '你有东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1360, '失而复得', '我本来有个不错的工作，就是在荒芜之地的奥达曼挖掘场干活……直到那些该死的穴居人出现之后。我险些就没能活着跑出来，而且还什么也没来得及拿。在一片慌乱之中，我弄丢了我最重要的财产。我那箱子很难撬开是没错，不过你知道么，那里满地都是穴居人！$B$B你去帮我拿回箱子来，我就好好谢你！那个写着我名字的箱子就在北部大厅的尽头，你得一路杀进去才行。', '到奥达曼的北部大厅去找到克罗姆·粗臂的箱子，从里面拿出他的宝贵财产，然后回到铁炉堡把东西交给他。', '哦，终于找回我的东西了……谢谢你。$B$B有些矮人可能喜欢亮闪闪的金属或是华丽的宝石……不过没有这只杯子，我就什么都没有啦!', '好吧，你有没有去和那帮穴居人杀个天昏地暗，有没有找到我的箱子，有没有拿到我的宝贝?', '', '去找丹莫罗的克罗姆·粗臂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1361, '雷戈萨·死门', '有一个名叫雷戈萨·死门的部落战士正在招募愿意转至凄凉之地执行任务的人。如果你愿意的话，就去和他谈谈吧。雷戈萨·死门就在贫瘠之地的十字路口西边的工事中。$B$B准备好你的武器，凄凉之地是一片危机四伏的土地。', '和贫瘠之地的雷戈萨·死门谈一谈。', '对，我正在招募新兵。这次的任务是深入到凄凉之地，与那里的半人马部族作战。我会简单地交待任务内容，然后你就要尽快出发了。', '我发现你的活儿没干完啊，$N。难道要我告诉Sharlindra你很蠢吗？', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1364, '马森的请求', '马森大人的指示再简单不过了：将这篇重要的文章递交给守望堡的看守者马哈尔巴。$b$b但我从来没有去过诅咒之地！这段路程太可怕了！$b$b我在悲伤沼泽那边迷了路，被一大群像是植物一样的沼泽生物给包围了。它们在我身边徘徊着，似乎是想要攻击我，所以我就飞也似的逃了回来……结果我在慌乱中把文章给弄丢了。我敢肯定是有只怪物把它给捡跑了。$b$b你能帮我找回文章并把它送给马哈尔巴吗？', '夺回《卡德加的空间收敛研究笔记》，将它送给守望堡的看守者马哈尔巴。', '啊，好极了!$B$B之前我还害怕学院的马森大人把我借阅《卡德加的空间收敛研究笔记》的请求给忘了。$B$B他一定是因为每天都要处理太多奇怪的事才没能马上回复我吧。$B$B现在，如果你没什么事了的话，我想马上开始阅读这本书。能读到伟大的卡德加的作品实在是让我兴奋极了!', '来守望堡有什么事吗，$r?', '', '去诅咒之地找守望堡的看守者马哈尔巴。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1365, '戴兹帕可汗', '科卡尔并不是凄凉之地唯一的半人马部族。许多半人马部族都游弋在这片干燥的平原上，他们相互残杀，纷争不断。他们的窝里斗对我们来说不是件坏事，因为半人马强壮而且残忍，如果这些半人马联合起来对付我们的话，那将是极其可怕的力量。$B$B在他们联合起来之前，我们必须将他们各个击破。$B$B你的第一个任务是让科卡尔部族出现内乱，只要干掉他们的首领戴兹帕可汗就可以了。$B$B科卡尔村就在东北方。去吧，祝你好运。', '把戴兹帕可汗的徽记交给凄凉之地的费古尔·双刃。', '干得不错。你行动迅速地干掉了科卡尔氏族的首领，这充分地展示了我们的力量，而强大的力量则是半人马最畏惧的。$B$B科卡尔氏族首领的死不仅会让他们出现内乱，也会让其它的氏族暂时收敛一些。', '$N，你杀死戴兹帕可汗了吗?', '', '去凄凉之地找幽灵岗哨的费古尔·双刃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1366, '悬赏半人马', '既然你已经震慑了半人马部族，那么现在该让他们出点血了。开始在凄凉之地猎杀半人马吧，我不关心你去猎杀哪一个部族，收集半人马耳朵就是了。$B$B减少他们的数量也就等于削弱他们的野心，打消他们不断扩张的念头。$B$B祝你狩猎愉快，$N。', '收集15只半人马的耳朵，把它们交给凄凉之地的费古尔·双刃。', '现在，半人马们一定都知道你的名字了，他们会知道这个名字，尊敬这个名字，同时对这个名字感到非常畏惧。当他们知道你，他们就会知道你所代表的力量。\r\n\r\n部落的力量。', '你收集了多少半人马的耳朵啦，$N?', '', '去凄凉之地找幽灵岗哨的费古尔·双刃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1367, '玛格拉姆部族', '要想打败半人马，我们就必须让他们自相残杀。首先我们要笼络一支半人马部族，利用它们打败所有的半人马。$B$B如果你准备和玛格拉姆部族结盟，那么就去杀掉他们的敌人——吉尔吉斯部族的半人马，这会使你在玛格拉姆部族中赢得尊重。当你得到足够的尊重之后，就可以去会见玛格拉姆部族的首领瓦鲁格，他就在凄凉之地东南部的玛格拉姆村外。', '和玛格拉姆部族创建良好的关系，然后和瓦鲁格谈一谈。', '$N，吉尔吉斯族的半人马一听到你的名字就会大哭起来。他们害怕你，也讨厌你。他们讨厌你就像他们讨厌玛格拉姆人一样!$B$B也许你像玛格拉姆人一样强大，我们会知道的……', '滚!玛格拉姆不和弱者交谈!我们只会杀了他们!$B$B如果你想和我谈话，就先让我看看你有多强大!去杀更多的吉尔吉斯人，然后再回来!', '', '去凄凉之地找玛格拉姆村的瓦鲁格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1368, '吉尔吉斯部族', '要想打败半人马，我们就必须以毒攻毒。我们要先笼络一支半人马部族，利用他们打败其它的半人马。$B$B如果你准备和吉尔吉斯结盟，那么就去攻击他们最憎恨的对手——玛格拉姆部族。在你赢得了吉尔吉斯部族足够的尊重以后，就可以去\r\n见他们的萨满祭司，智者乌泰克，他就住在凄凉之地西南的吉尔吉斯村外面。', '和吉尔吉斯部族创建良好的关系，然后和智者乌泰克谈一谈。', '大地告诉我……你杀死了很多玛格拉姆人。很好!$B$B如果你是吉尔吉斯人的朋友，那么听好，我有更多的任务要交给你。', '离吉尔吉斯人的土地远一点，这里不欢迎你!$B$B证明你对吉尔吉斯人的善意吧，去杀掉那些该死的玛格拉姆人。当你让玛格拉姆族血流成河的时候再回来吧!', '', '去凄凉之地找吉尔吉斯村的智者乌泰克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1369, '破碎之泪', '吉尔吉斯以为半人马之母瑟拉达丝在护佑着我们，他们都是蠢货！没有人在护佑半人马，玛格拉姆部族不需要护佑！我们是最强的！$B$B让吉尔吉斯半人马知道他们有多蠢——到他们村庄附近的洞穴里去一趟，他们把那种名叫瑟拉达丝之泪的水晶石藏在了洞里。毁掉那些水晶，把碎片交给我！', '继续和玛格拉姆部族保持良好的关系，把3块破碎之泪交给玛格拉姆村庄的瓦鲁格。', '你拿到了破碎之泪!现在吉尔吉斯半人马该知道瑟莱达丝不会帮助他们了。我们碾碎这些水晶的时候，她吭都不敢吭一声!玛格拉姆半人马注定要一统天下!$B$B你站在我们这边是个很明智的选择，$N，因为我们是最强大的!', '如果你是我的朋友，就按照我的要求去做!', '', '去凄凉之地找玛格拉姆村的瓦鲁格。', '摧毁眼泪', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1370, '偷取物资', '在作战之馀，我们为了食物而打猎。肉可以为我们补充力量，吃饱喝足之后作战会更加勇敢。$B$B玛格拉姆部族的半人马和我们一样，他们贮藏多馀的肉食，这样他们就能进行更持久的战斗。如果你能去袭击他们在东部的村庄，并且偷走他们贮藏的肉，他们的力量就会衰竭。', '把6包粗制干肉交给吉尔吉斯村的智者乌泰克。', '很好。我在很远的地方就能听到玛格拉姆半人马的肚皮咕咕作响!$B$B我会把肉分给吉尔吉斯半人马，这样我们就可以连续作战很长时间了。$B$B你为吉尔吉斯半人马做了件好事，$N。', '向吉尔吉斯半人马证明了你的价值以后再回来!', '', '去凄凉之地找吉尔吉斯村的智者乌泰克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1371, '瓦鲁格的玩具', '很久以前，有一个小侏儒来到凄凉之地。他是乘着马车来的，车上装着奇怪而有趣、燃烧后会放出五彩缤纷的焰火的东西，还有一些没有生命、但是居然可以自己移动的东西。我杀了这个小侏儒，不过在那之前……他让我乐坏了。$B$B我从他的马车上拿走了我最喜欢的东西，那是个木头做的人偶，在我把它砸得粉碎之前，它总是在那里向我招手。$B$B现在我想要一个新的，帮我弄一个来！', '继续和玛格拉姆部族保持良好的关系，给玛格拉姆村的瓦鲁格找到一个高级假人。', '嗯!这就是我要的东西!我让它再动起来，它就能让我发笑!', '如果你是我的朋友，就按照我的要求去做!', '', '去凄凉之地找玛格拉姆村的瓦鲁格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1373, '盎格库尔', '你还需要更多的行动来证明自己，我要你去很远的地方完成一个任务，所以从现在开始，吉尔吉斯部族就要独自和玛格拉姆部族作战了。$B$B大地把很多的秘密告诉了聆听它声音的人，我听到的秘密是关于一种红色水晶的。这种被称作德莱尼水晶的东西最近才出现在这片大陆上，它来自一个遥远的地方，那里的山脉在天空中悬浮，恶魔掌控着那里的一切。$B$B给我带一片德莱尼水晶碎片来，它能让我的魔法变得强大无比！这片德莱尼水晶碎片应该就在悲伤沼泽的失落者盎格库尔手里。', '继续和吉尔吉斯部族保持良好的关系，并把德莱尼水晶碎片交给凄凉之地吉尔吉斯村的智者乌泰克。', '没错，这就是大地向我提及的水晶裂片，我可以感受它蕴含着强大的魔法!我会用这种魔法来对抗吉尔吉斯族的敌人。$B$B你又为我们完成了一项重要的任务，$N。也许不久以后，我们就可以称你为朋友了。', '$N，你得向我证明你是吉尔吉斯族的朋友。', '', '去凄凉之地找吉尔吉斯村的智者乌泰克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1374, '杰恩可汗', '大地告诉我说，玛格拉姆部族变得越来越衰弱了。现在是干掉他们的可汗的时候了！$B$B把玛格拉姆部族的杰恩可汗的徽记给我取来！', '把杰恩可汗的徽记交给凄凉之地吉尔吉斯村的智者乌泰克。', '杰恩可汗虽然强大，却很愚蠢。他自以为他的力量无人能及，但他并没有发现大地的魔法正在加强。失去首领的玛格拉姆半人马将会和他们的领袖落得一样的下场，吉尔吉斯半人马总有一天会一统天下!', '$N，你要向我证明你是吉尔吉斯部族的朋友。', '', '去凄凉之地找吉尔吉斯村的智者乌泰克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1375, '沙卡可汗', '你帮助了玛格拉姆部族，我喜欢你。现在去杀了吉尔吉斯的可汗！他叫沙卡，我要他的徽记！', '继续和玛格拉姆部族保持良好的关系，把沙卡可汗的徽记交给凄凉之地玛格拉姆村的瓦鲁格。', '沙卡可汗死了!我要把他的头挂在长枪上，让沙卡看看我们玛格拉姆的力量!', '为玛格拉姆完成任务，那么我就会帮助你。', '', '去凄凉之地找玛格拉姆村的瓦鲁格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1380, '赫鲁萨可汗', '$N，你帮助我们战胜了玛格拉姆部族。现在，请再帮助我们打败玛洛迪部族吧！干掉他们的首领赫鲁萨可汗！$B$B要挑战他，先要吹响玛洛迪号角，这把号角就在长矛谷中的一处高耸的峭壁上。$B$B而要吹响号角，你必须得到一只哨嘴。这种东西很少见，只有萨鲁赫可汗的心腹们才有资格携带。$B$B号角一响，玛洛迪半人马就会蜂拥而至。放手屠杀他们，直到赫兰萨出现。$B$B赫兰萨可汗手里有一把……一把钥匙。把这把钥匙交给我，我就会告诉你有关它的秘密。', '继续和吉尔吉斯部族保持良好的关系，把玛洛迪钥匙碎片交给吉尔吉斯村的智者乌泰克。', '他死了!赫兰萨可汗死了!现在玛洛迪完蛋了!当吉尔吉斯彻底占领这片土地的时候，$N，我们会铭记你的。$B$B现在，让我告诉你这把钥匙的来历……', '赫兰萨可汗死了吗?你找到钥匙的碎片了吗?', '', '去凄凉之地找吉尔吉斯村的智者乌泰克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1381, '赫鲁萨可汗', '吉尔吉斯可汗已经被干掉，现在轮到玛洛迪了！干掉他们的首领赫鲁萨可汗！$B$B要挑战他，先要吹响玛洛迪号角，这把号角就在长矛谷中的一处高耸的峭壁上。$B$B而要吹响号角，你必须得到一只哨嘴。这种东西很少见，只有萨鲁赫可汗的心腹们才有资格携带。$B$B号角一响，玛洛迪半人马就会蜂拥而至。放手屠杀他们，直到赫兰萨出现。$B$B赫兰萨可汗手里有一把……一把钥匙。把这把钥匙交给我，我就会告诉你有关它的秘密。', '和玛格拉姆保持良好的关系，把玛洛迪钥匙碎片交给凄凉之地玛格拉姆村的瓦鲁格。', '赫兰萨可汗死了!现在玛格拉姆人是最强大的半人马部族了!我们要消灭其它的半人马部族，一统凄凉之地!$B$B我们会记得你的，$N，当其它人被我们践踏在蹄下时，我们会宽恕你的。', '照我说的去做。让我确信你是玛格拉姆人的朋友!', '', '去凄凉之地找玛格拉姆村的瓦鲁格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1382, '奇怪的联盟', '我们的确很幸运，半人马氏族之间正在同室操戈。如果他们拧成一股绳，那将会是一股无法阻挡的力量。没错，我们很幸运，所以我们应该紧紧抓住现在的这种优势。$B$B众多半人马部族中的一支——吉尔吉斯，正在与玛格拉姆部族激烈地战斗。我希望在我们进攻玛格拉姆的同时，吉尔吉斯部族也能同时发动攻击。$B$B去和智者乌泰克谈谈吧，他就在凄凉之地西南的吉尔吉斯营地外面。也许我们可以通过他来和吉尔吉斯结成联盟，同时对玛格拉姆发起致命的攻击！', '和吉尔吉斯部族创建良好的关系，然后和智者乌泰克谈一谈。', '你的名字在吉尔吉斯部族中广为传颂，因为你的手上沾满了玛格拉姆部族的鲜血。$B$B现在我们可以来谈一谈了。说说你能为吉尔吉斯做些什么，我们又能为你做些什么吧。', '走开!吉尔吉斯不想在这里看见你!!$B$B干掉更多玛格拉姆部族的家伙以后再回来，那时候我才会和你好好谈谈。', '', '去凄凉之地找吉尔吉斯村的智者乌泰克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1383, '真言药水', '我脑中已经想到了合适的药剂配方，可以让口风最紧的人喝下之后也知无不言。$b$b要制成这种药水，我需要几颗沼泽地中的暗影黑豹的心脏，另外还需要住在那儿的泥沼之王的蘑菇。$n，像你这么能干的人一定可以说服他给你一个蘑菇的。$b$b最后一味药是绿龙的血液，比如伊萨里奥斯的洞穴外面的那些。$b$b事不宜迟，你赶快出发吧！', '乞丐鬼屋的药剂师法奥斯丁需要5颗暗影黑豹的心脏、1颗泥沼之王的蘑菇和一些绿色雏龙之血。', '太棒了，$N!你来得还真巧。据莱度斯说，那个间谍的伤已经好了，现在就可以接受兽人的盘问。$B$B给我点时间来分配毒―我是说分配真言药水。', '被关在斯通纳德的间谍肯定会开口的……只要他喝了我特制的药水，哈哈!$B$B不过要得到配制药水所必需的各种成分并不简单。暗影黑豹在沼泽地很常见，但是收集足够多的心脏还是颇困难的。另外，泥沼之王也是个难应付的家伙。', '', '去暮色森林找密斯特曼托庄园的药剂师法奥斯丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1384, '突袭科卡尔', '科卡尔半人马认为他们的魔法很强大，其实他们根本就不知道魔法是什么东西！即使是把魔法扔在他们脸上，他们也不会知道的！$B$B你去让他们知道他们的魔法有多么脆弱吧。去杀了科卡尔部族的蠢货们，把他们的咒符带回来，我要把它们丢进火坑里，然后放声大笑！', '和吉尔吉斯部族保持良好的关系，把10个粗制咒符交给凄凉之地吉尔吉斯村的智者乌泰克。', '你为吉尔吉斯做了件好事。科卡尔部族很弱小，他们很快就会灭亡。他们的魔法是那么地不值一提，完全无法拯救他们。你已经向他们展示了这一点，而他们对你的恐惧会使他们变得更加脆弱!$B$B在我们的领地上，弱者是无法生存的。', '你拿到符咒了吗?你让科卡尔部族知道他们的魔法有多么脆弱了吗?', '', '去凄凉之地找吉尔吉斯村的智者乌泰克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1385, '野蛮外交', '凄凉之地是一片杀戮场。半人马部族之间互相残杀，我们担心最后的胜利者会不断扩张领土，并最终威胁到我们的要塞。我们决不能允许这种情况出现。$B$B我们必须学会如何打败半人马部族，为了打败他们……我们就必须和诸多半人马部族中的一支结盟。玛格拉姆部族与吉尔吉斯部族正在互相征伐，如果你去攻打吉尔吉斯部族，那么玛格拉姆部族就会视你为盟友。$B$B想办法得到玛格拉姆部族的信任，然后去和瓦鲁格谈谈，他就在凄凉之地东南的玛格拉姆村里。', '和玛格拉姆部族创建良好的关系，然后和瓦鲁格谈一谈。', '许多吉尔吉斯半人马倒在你的脚下，我喜欢!也许你能做更多让我高兴的事情，也许你和玛格拉姆半人马能成为朋友。', '赶快滚，不然玛格拉姆部族就把你揍扁!要想成为我们的朋友，你就必须去杀更多的吉尔吉斯半人马。', '', '去吉尔吉斯找玛格拉姆村的瓦鲁格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1386, '突袭科卡尔部族', '科卡尔部族认为他们很强大，但我们对他们嗤之以鼻！我们杀这些杂碎根本不费吹灰之力！你也可以杀了他们。让我看看你也是否也能像我们一样杀死科卡尔半人马。', '继续保持和玛格拉姆部族的良好关系，杀掉12个科卡尔半人马，12个科卡尔斥候和6个科卡尔虐待者，然后回到凄凉之地向玛格拉姆部族的瓦鲁格报告。', '科卡尔半人马现在很惧怕你!我希望你在杀他们的时候放声大笑。在你杀戮的时候最好大笑，这样敌人就会知道他是多么地弱小!', '你难道害怕科卡尔部族了吗?为什么不去杀了他们?也许你已经忘了该如何杀人了。赶快去给我杀了他们!', '', '去凄凉之地找玛格拉姆村的瓦鲁格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1387, '悬赏半人马', '半人马的社会是由多个部族组成的，每一个部族都有各自的领袖和纲领。所有的半人马部族只有一点是相同的：残忍。$B$B如果我们要寻求和平，就必须先消灭这些半人马。你的任务就是消灭他们。$B$B在凄凉之地猎杀半人马，割下他们的耳朵。给我尽可能多带些半人马的耳朵回来。$B$B为了联盟，请一定要这么做，$N，只有这样，和平才会降临这片土地。', '收集15个半人马耳朵，把它们交给尼耶尔前哨站的麦尔金斯下士。', '啊，半人马的耳朵。做得不错。$B$B你对联盟的贡献是毫无疑问的，$N。你在凄凉之地的行动，无疑地可以挽救无数人的生命。', '有什么要报告的吗，$N?', '', '去凄凉之地找尼耶尔前哨站的麦尔金斯下士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1388, '真言药水', '一切都在按照计划进行，$n。把真言药水交给莱度斯，他会告诉你怎样使用它……$b$b哈哈！', '把法奥斯丁的真言药水交给乞丐鬼屋的亡灵哨兵莱度斯。', '我就知道老法奥斯丁会搞出点名堂来!你真是帮了大忙了。$B$B现在我们继续做正事吧，好吗?', '药剂师法奥斯丁，我希望你的药水对我们亲爱的朋友有所帮助。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1389, '德莱尼水晶', '农田避难所里的那些失落者和我们是同族，但他们已经是疯狂的怪物了……在我们来到艾泽拉斯的那段残酷的征途把他们活活逼疯了！他们现在就住在东边的农田避难所里，任何在附近徘徊的人都有可能被他们抓住或杀掉……$B$B他们还偷走了我们的圣物——德莱尼水晶。$B$B我们没有足够的力量进入农田避难所去夺回那些被他们扔在小屋和营火附近的水晶，但是失去了那些水晶……我们就会迷失自己的方向。', '给悲伤沼泽避难营地里的玛格图尔带去6块德莱尼水晶。', '谢谢你，$N。我们会铭记你的恩德。', '你夺回德莱尼水晶了吗?', '', '去找悲伤沼泽的玛格图尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1391, '真言药水', '要办成这事，我们还得想点办法。毕竟你不可能大摇大摆地走进去，然后说服那个傻瓜喝下法奥斯丁配制的药水，对吧？$b$b不过有一样东西是这些人类肯定不会拒绝的，那就是酒。我会把法奥斯丁的药水和这瓶麦酒混合在一起，那个可怜的傻瓜肯定会毫不犹豫地一饮而尽。$b$b赶紧去悲伤沼泽的斯通纳德要塞，$n。什么都不要告诉别人……', '把莱度斯的酒带给斯通纳德的间谍玛克森。', '请我喝酒?你真是太好了!他们很多天都没给我酒喝了。等我把这酒喝完就把我所知道的一切都告诉你……', '可怜可怜我吧!我有一些超出联盟范畴的机密消息。虽然我不是部落的支持者，但是有些正在进行中的政治阴谋一定要被揭露出来!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1392, '木棒诺博鲁', '避难营里的德莱尼人已经被诺博鲁虐待了好几个月了，他的棒子对于这些失落者来说是一种残忍和暴力的象征。', '把诺博鲁的木棒交到悲伤沼泽中的避难营领导人手中。', '你拿到可怕的诺博鲁的武器了吗?那他死了吗?$B$B对避难营来说这真是高兴的一天。诺博鲁和他的手下对我们是个恐惧，他们在沼泽游荡，并杀害所有路过的德莱尼人，他是我们生存的直接威胁，我们一直没有力量可以对付他。$B$B我们很幸运能有你这样的朋友，$N。', '你好，欢迎来到避难营。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1395, '守望堡的物资', '这一箱能量石要送去位于诅咒之地的守望堡。它们不能长久保持魔法的效力，因此我们恐怕不能等到下一支商队出发时让他们捎去了。$B$B你必须带上它们，迅速赶往守望堡，动作一定要快。$B$B把它们交给城堡里的军需官朗格尔斯。要想到达那里的话，你就必须向东穿越逆风小径，再向东穿越悲伤沼泽，然后向南穿越诅咒之地。$B$B你要小心，$N。你要连续穿越好几个危险地带，但是绝对不能失败。', '在能量石的魔法效果消失以前，将它们交给守望堡的军需官朗格尔斯。', '啊，能量石!法师们看到这些一定会很高兴的。$B$B太谢谢你了，$N。我知道你从夜色镇赶到这里并不容易。', '嗨!别在意这些骚动，这在守望堡简直就是家常便饭。$B$B你有什么东西要给我的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1396, '逼近的野兽', '我的车队本来是要去守望堡的，但我们没能到达目的地。食人魔攻击了我们，他们杀死了护卫，然后将所有的货物全都给抢走了，那帮该死的家伙逃进了逆风小径。$B$B只有我一个人逃过了他们的袭击。我曾发誓要保护好那些货物，发誓要把它们安全送到守望堡！$B$B但这一带的野兽太多了。拜托，不要让那群野兽侵入我们的营地！', '杀死8只小盐齿鳄鱼、10只沼泽纺丝蛛和10只沼泽虎，然后向悲伤沼泽的卫兵比格斯报告。', '动物的咆哮声现在似乎减弱下去了，大概是远离了吧。谢谢你，$N。但愿它们不会再回来!', '沼泽里的怪物正在逼近，$N。拜托，你一定要守住营地!', '', '去找悲伤沼泽的卫兵比格斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1398, '晒干的流木', '我对你实在是感激不尽，$N。你有一颗充满荣耀的心。现在，我想我仍需要谦卑地请您帮我完成另一个任务。$B$B如果我还想到守望堡去的话，就一定得修好这辆马车。因此……我需要一些木材，我要的是结实的干木，而不是从那些沼泽中的树上砍下的像海绵一样松软的木头。$B$B$N，请到东边的海滩上去找些已经被太阳晒干的流木，把它们给我拿来。', '给悲伤沼泽的卫兵比格斯带回8块晒干的流木。', '这木头很轻，但也很结实。感谢你，$N。', '找到流木了吗，$N?', '', '去找悲伤沼泽的卫兵比格斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1419, '捕猎山狗', '$c，你在荒芜之地呆了很长时间吗？你感觉到那里的炎热了吗？你是否跟那些在尘土飞扬的平原上到处游荡的野兽打过交道？如果还没有的话，现在是时候了。$B$B峭壁山狗是一种让人头疼的猛兽，这些强壮而凶猛的家伙总喜欢潜入卡加斯，偷走我们的食物补给。帮我们的前哨基地解决掉这些小偷吧！$B$B捕杀这些峭壁山狗，把它们的颚骨拿来见我。带给我足够多的颚骨，那样也许我才会相信你真的了解荒芜之地。', '带30块山狗的颚骨去见卡加斯的尼卡·血痕。', '干得不错，$N!现在那些山狗再也不会把我们的补给品给搞得一团糟了。$B$B荒芜之地的山狗是很难对付的野兽，你的行动向我展示了你有足够的能力在这里生存。', '你拿到足够的腭骨了吗?', '', '去荒芜之地找卡加斯的尼卡·血痕。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1420, '向赫格拉姆报到', '我刚写了一份要交给斯通纳德的赫格拉姆的报告，请你帮我带去给他。$B$B千万别在途中迷了路，也别让这份报告落到敌人的手中。', '把尼卡的报告交给斯通纳德的赫格拉姆。', '谢谢你，$N。看过尼卡的报告之后，我发现联盟还没有解决他们自己的问题。而且我们双方可能还拥有共同的敌人。', '你回来了，你带来了一份报告?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1421, '丢失的货物', '那些失落者们攻过来的时候，我一下子就被吓呆了。等我回过神来，就看见一只受惊的马拖着车一路狂奔出去，窜入了北边的失落者村庄里。$B$B那辆车上运的是非常贵重的施法材料，都是守望堡的巫师们急需的。找到我们的材料，$N，帮我把它们带回来。', '在农田避难所中找到商队的货物，并拿到巫师的材料，把它交给卫兵比格斯。', '啊，你找到它们了!有了这些，守望堡的巫师们就可以继续他们的工作了。虽然我不知道他们在做些什么，但似乎这与诅咒之地里的黑暗之门有关，这对联盟的安全来说非常重要。', '你找到那些原料了吗，$N?', '', '去找悲伤沼泽的卫兵比格斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1423, '遗失的补给品', '这只木桶不大，但非常坚固。木板的接缝处和桶盖边上都用一种味道刺鼻的黄色封蜡封了起来。桶底的标签上写着两行大字：$B$B军需官朗格尔斯$B$B守望堡', '把遗失的货物交给军需官朗格尔斯。', '啊，太感谢你了，$N!许多货物在从夜色镇运过来的路上都弄丢了，能找回一部分实在是太好了。', '你有东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1424, '泪水之池', '酋长大人派我们去调查阿塔哈卡神庙中发生的奇怪现象。$b$b阿塔莱巨魔是由一群使用黑暗法术的施法者组成的部族，以惯于运用禁断的魔法而着称。你可以想象一下，当我们到达那里，却发现整座庙已经沉入了水中时，我们会有多么惊讶。$b$b现在那里被一群自称是艾泽拉斯保卫者的绿龙占据着。$b$b我们得弄清楚那里到底发生了些什么事。去探索一下泪水之池周围，收集一些阿塔莱神器。有了这些信息，我就可以开始把这个谜一点一点地给解开了。', '斯通纳德的费泽鲁尔要求你收集5件阿塔莱神器。', '你收集来了这么多的阿塔莱神器，值得嘉奖，$C。', '没人知道阿塔哈卡神庙内现在潜伏着何种黑暗邪恶的力量，但我们都能感觉到那里聚集了强大的魔法能量。$B$B我们必须尽可能多地了解这种魔法，或许阿塔莱的法术对我们部落是有用处的。$B$B一旦你在泪水之池收集到了足够的阿塔莱神器，我就能了解到那群巨魔究竟施放了怎样的法术，以及那里到底发生了多么恐怖的事情。', '', '去找悲伤沼泽的费泽鲁尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1425, '运送货物', '$N，在我修车的时候，我另外还有一件工作要交给你。$B$B我已经把从食人魔那里抢救回来的最重要的几件货物都放在了包裹里，你把它们都带到守望堡里去吧。这座城堡就在诅咒之地北方的丘陵地带中，时刻监视着黑暗之门里的动静。$B$B你只要顺着这条路一直向东走，在第一个岔路口向南进入诅咒之地，然后再在第二个岔路口向左转，就可以到达守望堡了。记住，要一直顺着路走，$N，多加小心。', '把货物交给守望堡的军需官朗格尔斯。', '什么?毕格斯让你捎来的包裹?我们一直在等着它呢，我还以为毕格斯出事了。$B$B谢谢你，$N。这些包裹里应该有我们最需要的法术材料─阿祖拉水晶。我们这里的库存已经不多了……', '找我有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1426, '海中的威胁', '我一点都不喜欢大海，更不喜欢那些从深海里游上来的生物。他们都是些强大野蛮而又盲目的蠢货。要是我有足够的气力，我就会去成百上千地屠杀鱼人。不过现在我还没那么凶悍，所以就只好退而求其次，只要能看见这群鱼人死在任何遵从着部落意愿的勇士手里，我也就满足了。$B$B你怎么样呢，$c？你能杀死多少鱼人？你愿意和鱼人当中最强的一群较量较量吗？', '杀掉10个沼泽鱼人、10个沼泽喷墨鱼人和10个沼泽食腐鱼人，然后向悲伤沼泽的卡塔尔回报。', '大海看起来是辽阔而无情的，但你已经用她的子民的血液浸染了她的身躯。鱼人知道什么是痛苦，但它们早晚会好了伤疤忘了痛，它们仍会从这次你给他们造成的灾难中恢复过来，然后继续肆无忌惮地扩张。$B$B让他们凄苦的惨叫在夜空中遮盖过大海的咆哮吧。每倒下一个鱼人，我都会微笑一次。$B$B如果你愿意再杀些鱼人的话，一定要来找我，我会再次奖励你的。', '我很有耐心，我的耐心就如同德拉诺的坎克石一般不可动摇。绝对不能让任何一个鱼人跨越过我们的边境─只要我还在，就不能。假如有一支完全听从我的命令的军队，我就要彻底把这种该死的动物从这个世界上清除掉。就算只是提到它们，我也感觉到我的仇恨随时都要爆发。', '', '去找悲伤沼泽的卡塔尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1428, '海中的威胁', '看着你对鱼人的憎恶也如同我一般地与日俱增，我非常高兴。$B$B沿着海滩巡逻，你就可以找到更多的鱼人，去杀吧。当你觉得自己杀得够多了以后就回来找我，我会好好奖励你一下的。', '杀掉10名沼泽喷墨鱼人、10名沼泽食腐鱼人和10名沼泽鱼人智者，然后向悲伤沼泽的卡塔尔回报。', '干得好，$C。所有的鱼人都给我去死吧!', '只有大海与她所有的孩子都回归寂静之后，我才会高兴……尤其是那些恶心的鱼人。', '', '去找悲伤沼泽的卡塔尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1429, '阿塔莱流放者', '当你勇敢地在泪水之池周围冒险的时候，我的斥候带回了一张用血写成的卷轴。那看起来像是对阿塔莱部族中的某位祭司的审判书。$b$b这位祭司被判处了阿塔莱部族中的极刑，他的命运将比死亡还要更可怕。$b$b他被放逐到了极北的辛特兰，被迫与一群枯木巨魔住在一起。$B$B我会帮你把这些物品包好的，请你带着它们去找到这位流放者，或许你能从他那里得知他们的部族到底使用了怎样的魔法。任务完成之后，请立刻向我回报。', '将一捆阿塔莱神器交给辛特兰的阿塔莱流放者。', '你带来了阿塔莱的召唤法器?$B$B我倒要好好看看“预言者”迦玛兰是怎样领导着鲜血之厅的信徒与他们的宿命抗争的。我想知道，哈卡回到神庙里了吗?他们的命运之轮已经开始转动了吗?', '你竟然能来到这里，真是太勇敢了。嗯，到底是勇敢还是愚蠢呢……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1430, '新鲜的螃蟹腿', '最近我的顾客总是会来买鲜嫩多汁的螃蟹肉，特别是那些巨型淤泥蟹的肉。$B$B如果你最近要去海边转转的话，最好能帮我带一些螃蟹腿到奥格瑞玛去，我会付你可观的报酬的。$B$B海岸就在这里的东边，那里遍地都是螃蟹，很容易就可以弄到螃蟹腿。', '给悲伤沼泽的达尔带去10条巨大的螃蟹腿。', '啊，太完美了。我等不及要把这些肉好好烤烤，然后大吃一顿了!你应该带一些在路上吃，它确实是美味至极。', '我为你准备了一桶酒，准备给你开个庆功会，$N。在我把这些肉送到顾客那边之前，我们一定要先尝个鲜。', '', '去悲伤沼泽找斯通纳德的达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1434, '萨特的威胁', '恶魔是绝对不会凭空就出现的——他们需要一些空隙使邪恶得以立足。$B$B这空隙或许会产生自孱弱的精神，或许是对权力的无谓欲望，或许是对复仇的渴求，或许是要求最终审判的控诉。当我们被痛苦所困扰时，邪恶就会利用我们——例如萨特这样的邪恶力量。$B$B火刃氏族与它们之间显然有很紧密的联系，因此萨尔认为他们必须被清剿干净。到东北方向去寻找的它们的踪影，在将他们驱赶出这一带后回来向我报告。', '杀死7只怨怒盗贼、7只怨怒魔仆、7只怨怒背叛者和7只怨怒唤魔者，然后向凄凉之地的塔卡塔·钢刃复命。', '干得好，$C。你向大家展示了你的荣耀和奉献精神。$B$B当我们在凄凉之地的任务告一段落时，大酋长将会知道是你在这里帮助我们完成了任务，是你帮助他实现了他的计画。$B$B感谢你。', '有一个牛头人同伴警告我说，萨特的内心世界可能与它们的外表截然不同。他相信它们并不是表面上看起来的那么简单，也许是邪恶扭曲了它们的本性，但我是看不见这些事情的。$B$B我只是看见了它们无情地屠戮弱小，不惜一切地追寻黑暗的力量。$B$B我将继续履行歼灭它们的职责，直到大酋长给我新的指示。在那之前，我不会对它们有丝毫的同情。', '', '去凄凉之地找幽灵岗哨的塔卡塔·钢刃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1435, '灵魂的燃烧', '对那些为了某些自私的理由而背叛了自己首领的卑劣生物们而言，死亡是他们最合适的归宿。但对于那些将自己的全部身心奉献给黑暗的家伙们来说，死亡还远远不够。$B$B拿着这块宝石，当你附近有火刃氏族的爪牙死去时，就启动宝石上面的魔法。这个法术会拯救堕落的灵魂，将它们拉出黑暗的深渊，灌注到宝石里。$B$B在这些宝石中灌入了灵魂之后，把它们带回来交给我，我会妥善处置它们。$B$B现在就出发吧，多加小心。', '将15块燃烧宝石转变为灌入灵魂的燃烧宝石，然后把它们交给凄凉之地的玛乌林·碎骨。', '啊，你平安归来了，这很好。给我宝石，我要把它们放到安全的地方去。$B$B我给你的任务你已经全都完成了，$C。你休整好了以后记得和塔卡塔谈一下，他或许还有其它的任务给你，或者会安排你回奥格瑞玛去将我们在凄凉之地的工作进程通报给科尔丹。', '我自己也尝试过尽可能将魔法弄得简单些。从受伤的躯体中抽取灵魂实在是易如反掌，但你不能完全依赖宝石的力量去杀敌。你必须在他们濒死的时候才能启动宝石，否则宝石就不能发挥它的功效。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1439, '寻找泰拉尼斯', '兽人杀掉了我们所有的护卫和仆从，然后把我们带到了这里。天啊，那真是太可怕了！我以为他们肯定也会杀了我们，不过显然它们有别的计划。$B$B泰拉尼斯试图和他们交涉，我想他试图用对奥术的了解来博得他们的好感……我不知道他为什么要那么做。$B$B没有找到哥哥的下落，我就不离开这里。找到他，然后再回来救我吧。', '去凄凉之地找到泰拉尼斯·玛雷姆。', '真是太可怕了!但我想这是有必要的。即使你不这么做，我的同胞也会这么做的。我应该谢谢你―如果我看起来不够诚恳的话，还请你原谅，我没有冒犯你的意思。$B$B既然已经知道哥哥的下落，那么我似乎应该逃离这里了。如果你愿意的话，我可以在你的帮助下离开这个恐怖的地方。$B$B等你准备好了之后，我们就一起离开。', '我担心泰拉尼斯是为了获取燃刃氏族的秘密而不惜加入他们的阵营―他对魔法已经着迷了。$B$B我不知道自己是否忍心把泰拉尼斯沉迷魔法的事情告诉家乡的同胞，让我做这样的事情简直就是犯罪!但是为了保护我们自己不再遭受巨大的灾难，这样做也是可以理解的。', '', '去找凄凉之地的黛琳达·玛雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1442, '寻找科尔宝石', '你好，$N。我能为你这位追寻神圣之道的人做点什么呢？$B$B哦，铁匠斯迪威尔……很久以前的事了，不过我还记得他，有一段时间没听到他的消息了。$B$B我知道他决不是那种卑鄙的人，他想要一块科尔宝石一定也是为了某种高尚的目的。$B$B如果你真想要科尔宝石，就到灰谷的西北方去。你会在古老的废墟里看到黑暗深渊，而那些仍然在使用科尔宝石纳迦就聚集在那里。你一定要小心，不要单独行动。', '给黑海岸的桑迪斯·织风带去一块科尔宝石。', '这正是史蒂威尔想要的宝石，不过在我让你拿给他之前，必须先去除其中的腐败成分—纳迦为科尔宝石灌输了强大的魔法，不过那是邪恶的魔法。$B$B告诉史蒂威尔，科尔宝石中的魔法能量都是纯正圣洁的，无论他想用它完成什么仪式都没有问题。$B$B我希望你知道自己在做什么，$C，你手里拿的可不是个简单的东西。', '对于一个向我要科尔宝石的人，我会怀疑他是不是真的追寻神圣的道路。不过我相信你胜于相信我的某些同类，更不会因为你们之中某人的堕落而怀疑你们所有的人。', '', '去黑海岸找奥伯丁的桑迪斯·织风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1445, '阿塔哈卡神庙', '他提到了迦玛兰的预言？$b$b这位阿塔莱部族的精神领袖相信，只要哈卡从扭曲虚空回到艾泽拉斯，这位神祗就将赐予阿塔莱部族的每一个成员以永恒的生命。$b$b若你问我怎么看，我会说这实在是一个只会带来灾难的愚蠢行为。$b$b你说那个流亡者提到了魔法神像？这令我十分担心。如果这种东西确实是那个阿塔莱召唤仪式中的必需品，那我们就必须弄清楚这东西中蕴藏着怎样的力量。$b$b到那个神庙里去一趟，把这些神像都给我带回来！', '收集20个哈卡神像，把它们带给斯通纳德的费泽鲁尔。', '勇敢的$C，你充分证明了你的实力，你是部落的英雄。$B$B现在，我们必须马上开始处理你收集到的哈卡神像!', '如果阿塔莱的神像中蕴藏着能召唤出哈卡并实现迦玛兰预言的力量，那么我们就必须拿到它们。部落必须了解并掌握这种力量。', '', '去找悲伤沼泽的费泽鲁尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1446, '预言者迦玛兰', '我的枯木同伴们对贸然闯入他们领地的陌生人不太和善。$b$b我吗？我连家都没有了。我原本属于悲伤沼泽的阿塔莱部族，不过现在却被我的同胞流放到这里来了。$b$b我们的精神领袖迦玛兰曾有过一个“预言”，他声称召唤哈卡会带给阿塔莱部族永恒的生命。$b$b但是我觉得有些不对劲的地方，如果这个预言仅仅是为了操纵我们，那我们该怎么办？$b$b我要为他们流放我的举动\r\n复仇，给我把迦玛兰的徽记带回来，也许这样我的同胞就可以重获自由。', '辛特兰的阿塔莱流放者要你给他带回迦玛兰的徽记。', '迦玛兰那可怕的错误信仰把我的同胞引上了绝路……$B$B谢谢你，$C，谢谢你为我被流放的事情复仇。我为我的同胞哀悼，我已经无家可归了。', '只要除掉迦玛兰，我就有机会回到我的同胞身边。$B$B如果迦玛兰继续蒙蔽他们的理智，那么阿塔莱必将遭受灭族之祸。', '', '去辛特兰找沙德拉洛的阿塔莱流放者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1447, '失踪的使节', '没错，你显然不是到暴风城里来的最聪明的$c，但如果你现在不赶快给我消失的话，你就是最笨的那个了！$B$B嘿，你还不走？那就跟我的朋友过过招吧！', '击败暴风城的达舍尔·石拳。', '那么，你来找我到底有什么事?', '这一切其实都是个误会，我从来没有说你是一个愚蠢的$C。我们是朋友，对吧?别那么严肃吧?', '击败达舍尔·石拳', '去找暴风城的达舍尔·石拳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1448, '调查神庙', '我年轻的时候，也是像你这样活力充沛，有一股冲劲的。$b$b但现在我老了，也不能像当初那样在这片大陆上到处冒险了。啊，真是怀念那段日子啊！$b$b但我过去的冒险生涯中却里还有一个未解之迷。在我的最后一次任务中，探险者协会派我去调查阿塔哈卡神庙，据说那座庙宇就在悲伤沼泽里。$b$b但当时我却感到害怕，只是坐在狮鹫上飞过了这片地方，自然，我并没有找到神庙。$b$b你愿意满足一个老矮人最后的愿望吗？或许你走路过去的话就可以找到神庙……', '暴风城的布罗哈恩·铁桶要求你去找到阿塔哈卡神庙。', '阿塔哈卡神庙已经沉没在泪水之池底了?而且被绿龙军团给围了起来?!$B$B真是个了不起的发现呀，$C，不过显然有什么地方不对劲……', '我曾到过艾泽拉斯的森林深处，也到过卡兹莫丹的雪峰峰顶。$B$B以前我从来没有在冒险的时候要求过别人的帮助，可现在我已经是一把老骨头啦。$B$B没什么事能比完成探险者协会赋予我的最后一个任务更能让我心满意足的了。$B$B如果你能帮我找到阿塔哈卡神庙的话，$C，我将对你感激不尽。$B$B希望你能仔细搜索悲伤沼泽，然后向我回报你的成果。', '搜索阿塔哈卡神庙', '去找暴风城的布罗哈恩·铁桶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1452, '拉普索迪的卡利姆多鸡尾酒', '嗝儿！$b$b你是那疯子加蠢蛋布罗哈恩派来的啊？我们倒是一起经历过一次大……大冒险……嗝儿！$b$b如果你想要知道我那时候掉进沼泽里的时候看到了什么，行，不过我得先喝上一杯好的。要知道那底下可不是什么美景……嗝儿！$b$b要不这么着吧……如果你给我弄些原料来配制卡利姆多鸡尾酒，我就告诉你。$b$b至于原材料，先去塔纳利斯搞点大鹏的砂囊……然后，然后……我看看……再去菲拉斯弄点格罗多克猩猩和铁鬃熊的肝脏来……$b$b这便是唯一能打开我的话匣子的东西，美味的卡利姆多鸡尾酒呀！', '辛特兰的拉普索迪·铁铲要求你带给他3块大鹏的砂囊、3块格罗多克猩猩的肝脏和3块铁鬃熊的肝脏。', '我就知道你一定能搞定的!卡利姆多那地方可确实有些远。$B$B要是我亲自出马，一下子就能把这些杂七杂八的东西全都搞定。嗝儿!$B$B好吧，现在就让我来调制出一杯美酒，只要一口下肚，你想知道什么我就说什么。$B$B嗝儿!$B$B哎，一想到那沼泽的事我就要发抖。$B$B嗝儿!$B$B先让我喝上一杯壮壮胆。', '你喝过我酿的酒吗?要我说啊，这可是史上最好喝的酒!嗝儿!$B$B如果要我从那次差点要了我命的……嗝儿……沼泽飞行事故中缓过神来，你就得给我弄点东西来。嗝儿!$B$B你不想知道我把那些砂囊和肝加到卡利姆多鸡尾酒里是个什么味儿么?$B$B嗝儿!', '', '去找辛特兰的拉普索迪·铁铲。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1456, '卡尼托的海难', '真有趣。$B$B其实，我们也不是一点希望都没有。$B$B在那个海岸更靠北的大海深处，有一片暗夜精灵的废墟。一个纳迦部落把那里当成了他们的家，他们管那地方叫什么来着……滑刺……不，是滑刃部族！我想我们可以去那里碰碰运气。$B$B如果有什么人能够深入到那么远的南部，那他们一定非常强大。如果你要去找卡尼托的东西，那么就准备对付更加强大的纳迦——滑刃潮行者或者滑刃海巫吧。', '找到卡尼托的背包，把它交给凄凉之地的克雷迪格·安戈尔。', '$N，这太好了!你找到了卡尼托的东西!$B$B那些该死的纳迦总是在制造麻烦。我宁可一生都和部落作战，也不愿意和他们交手。你这次真的帮了寻物公司的大忙!', '无论尼耶尔是谁，我都无意冒犯他，不过这个营地并不是我过夜的最佳场所，$N，希望你明白我的意思。', '', '去凄凉之地找尼耶尔前哨站的克雷迪格·安戈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1457, '卡尼托的背包', '去把卡尼托的东西交给铁炉堡的罗顿吧，他会付你报酬的。$B$B哈哈，我敢跟你打赌，他一定会盛情邀请你加入我们的。$B$B再一次感谢你，$n，你干得很好。$B$B回去的时候要多加小心，别耽误太多的时间——卡尼托不是那种很有耐心的人，但是毫无疑问，他是非常慷慨的。', '把卡尼托的背包交给铁炉堡的罗顿·石锤。', '啊，是卡尼托掉在凄凉之地的东西。太好了!$B$B所以，箱子已经被毁了，不过东西都还在，是吗?好，我会让他来认领这些东西的。我最喜欢做这种生意的一大原因就是就算顾客不满意，他们也拿我没办法!他们得靠我们才能找到他们的东西……我们并不能保证他们拿回这些东西的时候都还是完好如初的。$B$B做得不错，$N。我来付给你报酬吧。', '$N，我的生意非常繁忙，所以没有很多时间来回答问题。如果你和寻物公司有生意往来的话，我洗耳恭听。否则，我只好请你去找我的手下谈谈，他们应该就可以处理你的问题了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1458, '寻物公司的委托', '我到这里来的一个主要任务就是帮莱弗维奇收集材料，莱弗维奇是卡拉诺斯城中的一个侏儒法师。罗顿总觉得这件事对我们来说轻而易举，却对我们这里人手短缺的现状视而不见。$B$B他列出的清单上的前几件物品应该很容易找到，如果你帮我找到它们的话，就可以获得丰厚的报酬。$B$B首先你得从东边的怨怒萨特身上弄一些角和爪子回来，然后我们再来寻找清单上列出的其它物品。', '收集10只怨怒萨特的爪子和10根怨怒萨特的角，把它们交给凄凉之地的克雷迪格·安戈尔。', '很好，很好，$N。不知道这些东西品质如何，但应该可以满足莱弗维奇的需要了，除非他要的是十分罕见的品种。嗯，当然，如果他想要特殊品种的话，应该会事先有所说明的。$B$B他的清单上的下一件物品是怎么说的?', '萨特是一种卑劣的畜牲，传说他们曾和夜精灵有一种说不清道不明的关系，不过我不是很相信那些说法。$B$B我想这样的说法大概源于很多年前，曾有个夜精灵让萨特卷入了战争中吧。这个世界真是越来越危险了……', '', '去凄凉之地找尼耶尔前哨站的克雷迪格·安戈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1459, '寻物公司的委托', '莱弗维奇货单上的下一条……我看看……哦，在这里。$B$B非常简单，而且说明也写得非常清楚。他需要荒土蝎的毒液和科多兽的毛皮。清单上写得很清楚：这两件东西分别来自两个特定的物种：毒液来自于荒土鞭尾蝎，而毛皮则来自老迈的科多兽，注意，既不是濒死的科多兽也不是远古科多兽。$B$B法师……他们总是要一些稀奇古怪的东西……', '收集7瓶鞭尾蝎的毒液和3块老迈科多兽的毛皮，把它们交给凄凉之地的克雷迪格·安戈尔。', '这是给你的酬劳，$N。你让我在凄凉之地节约了至少一半的时间。在你的帮助下，我应该可以早一些回到铁炉堡去，用热水好好泡泡脚了。$B$B我们收集完清单上的所有物品以后，我就可以回去了。到时候别忘了多来到我家来玩玩，我一定会买些上等的麦芽酒来招待你。$B$B不过，我们先得把这清单上剩下的材料都给收集到。', '抱歉，我无法告诉你要到哪里去寻找科多兽或者荒土蝎。我不熟悉这片地区，而且也没有时间来进行调查。', '', '去凄凉之地找尼耶尔前哨站的克雷迪格·安戈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1464, '火焰灵契', '', '向泰尔夫·祖拉姆再要一个 火焰灵契。', '愿火焰在你的心中燃烧，$N。$B$B火焰元素在等着你。', '如果你在战斗中输给了火焰之魂，告诉我，我会再给你一个火焰灵契，让你能够看到山顶那座圣殿中的火焰之魂。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1466, '寻物公司的委托', '这是物品列表上的最后一些东西了，我不会撒谎，撒谎可不是件光彩的事情。恐怕你得花更多的时间去寻找这些……$B$B我已经说了这么多了，言归正传。莱弗维奇的要求是：从噬法魔犬，法师猎手或者灵能猎犬那里收集大脑；从地狱魔女、地狱巫女或地狱修女那里收集魔女之翼；还有……从末日看守队长或者末日看守领主那里收集末日看守之血。$B$B是不是很简单啊？呵呵……如果你不想接这项任务的话，我也能理解。', '收集10个地狱犬的脑子、10对魔女之翼和10瓶末日看守之血，把它们交给凄凉之地的克雷迪格·安戈尔。', '你完成任务了?太让我吃惊了，$N，你真是太强悍了!你居然以一己之力对抗恶魔，而且还能全身而退!精彩至极!$B$B在我返回铁炉堡以后，我会亲自把你介绍给罗顿的。', '我还没有意识到这些恶魔居然会出现在凄凉之地。我记得曾经从什么地方读到过……很多年前，夜精灵离开了这里，而半人马则接踵而至。$B$B我想知道恶魔们为什么会在这里出现，他们又是怎么来的。', '', '去凄凉之地找尼耶尔前哨站的克雷迪格·安戈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1467, '寻物公司的委托', '要想得到报酬，你就得去一趟铁炉堡，亲自和罗顿谈谈。他会非常乐意收到莱弗维奇的包裹的。把这个交给他，然后你应该就能收到报酬了。$B$B别担心，我回去以后会替你美言几句的，从理论上讲我应该不会在这个鬼地方呆太久的。', '把莱弗维奇的包裹交给铁炉堡的罗顿·石锤。', '啊，是从凄凉之地送来给莱弗维奇的包裹，太好了。我很感激你的认真工作及守时守信的态度，$C。很高兴能与你合作。$B$B这是你的报酬。让大家都知道寻物公司一直都坚持对辛勤的工作者们给予丰厚的报酬的!', '很高兴见到你，$N。铁炉堡到处是一片生意兴隆的景象，铁锤敲击砧板的声音响彻全城，鼓风机扇起的火苗直冲半空，而且老婆还给我制作了一块派作为餐后点心—还有什么样的生活能比这更惬意呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1469, '拉普索迪的故事', '在出发前，我喝了整整一桶的烈酒。嗝儿！$b$b那是怎样的一次飞行呀！布罗哈恩跟着我飞了几圈，还是没看见庙。嗝儿！$b$b我喝得有点醉了，结果没抓稳就从坐骑上掉了下去。我一头栽进了水里，而且沉到了底儿，这个时候我竟然看见了那座庙。不过很快就从不知道哪里冒出了一大群巨魔把我给围了起来，废话，当然得快溜了！不过我还是从那些巨魔手中搞了点纪念品回来。给，把这个带给布罗哈恩，告诉他神庙确实就在那下面。嗝儿！', '将阿塔莱石板碎片交给暴风城的布罗哈恩·铁桶。', '拉普索迪.铁铲!对，就是他，就是他……我怎么能忘了这名字呢?$B$B这么说他一直就知道那神庙沉在水底啦?你一定跑了不少路。$B$B看看这阿塔莱神器!哈哈，这可真是个大发现呀!', '你总算回来了，$N。好久没见了，我还以为你已经把我的事视l悀F呢。$B$B你找到那个狮鹫兽骑士了吗?他有没有告诉你些什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1470, '控制小鬼', '你好，孩子。以一个术士的标准来看，你还太年轻了些，因为你还无法掌控那些力量。我能感受到你渴望学习的热切心情。$b$b你也一定能学会的。$b$b无知就没有力量，知识就是我们最好的武器。运用知识，我们就能控制无序的魔法和虚空之中的生物，让它们臣服于我们的意志。$b$b我会教你如何让一个奴仆服从你的意志，但首先你要带三个断骨骷髅的徽记给我，你可以在废弃的铁匠铺附近找到它们。', '收集3个断骨骷髅的徽记，把它们交给温雅·玛山德。', '尽管你经验不足，也没有经过足够的训练，但你还是证明自己拥有足以召唤和控制小鬼的能力。不要被小鬼的身形所迷惑，尽管它的力气不值一提，但它却拥有强大的魔法，而且机灵无比，它对你会很有用处。$B$B仔细听好我所说的一切，$N，我要把这套魔法教给你，而且我不会重复说第二遍。', '你现在的力量实在是太弱小了，但是我觉得你能够感受到即将发生的事情。$B$B拥有这种力量之后，即使是死去的人也能感受到生命的气息。', '', '去提瑞斯法林地找丧钟镇的温雅·玛山德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1471, '誓缚', '你应该见过下边的那个召唤法阵了吧？只有站在那上面，你才能召唤出虚空行者来。$b$b用这些符文就可以进行召唤了，但在那之后，无论是用武器还是魔法，你必须击败它才能够对它进行操控。$b$b等虚空行者被你征服之后，它就会与你订下契约。契约签定完成之后就过来找我，我会向你说明召唤法术的使用方法，以便你以后随时召唤它。', '召唤并征服一只虚空行者，然后将召唤符文还给诅咒神庙中的凯伦丁·哈加尔。', '你干得非常好，$N。现在，我要开始教你如何召唤虚无行者了。$B$B它的力量以后将由你来控制，小心地使用它吧。', '我期望着听到你的好消息，$N。至少别让我失望，不过，你应该不会失败的。', '', '去找提瑞斯法林地的凯伦丁·哈加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1473, '虚空中的生物', '看来大家一致认为你已经可以学习如何召唤虚空行者了。$b$b虚空行者是一种由虚空中的混乱力量所构成的实体，如果你召唤出虚空行者但却不能控制住它的话，你就会被它撕成碎片。$b$b世上第一个虚空行者是埃加林召唤出来的，而在他的魔典中也详细地写明了整个召唤过程。$b$b不幸的是，这本书被血色十字军的一个成员给偷走了，他把书藏在十字军在西边占据的一座塔中。把它给我拿回来，然后我就可以把召唤虚空行者的方法传授给你了。', '夺回埃加林的魔典，把它交给诅咒神庙中的凯伦丁·哈加尔。', '啊，太棒了。看起来派瑞恩队长完全忽视了这本书中所蕴涵着的真正力量，亏他还专门把它从我们这里偷了过去。$B$B我们绝对不会再次把它给弄丢了。看着，$N，这就是施法的方式，你必须按这样的方法来引导魔法力量。', '埃加林是我的老师，他曾教我召唤虚无行者的方法。他很伟大，他只需要用一个眼神就可以操控他召唤出来的虚无行者。$B$B而当轮到我来进行召唤的时候，我过分的自信给我带来了不幸。不要轻视你还不能完全控制的这种力量，$N，即使你保持着警惕，它们还是随时有可能将你吞噬。', '', '去找提瑞斯法林地的凯伦丁·哈加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1474, '誓缚', '在召唤法阵上，以这些精华为材料施展一个法术，就可以为魅魔打开一个通向这个世界的通道。尽管你现在的力量已经很强了，但你还是得竭尽全力才能战胜魅魔。$b$b小心她的魅惑能力，$n，有很多意志坚强的人都被她诱惑，屈从了她的意志。如果你战胜了魅魔，她将会回到虚空中去，然后我将教你如何召唤这个魅魔，让她听你调遣。', '召唤并征服一只魅魔，然后将纯洁的精华还给诅咒神庙里的凯伦丁·哈加尔。', '你又一次漂亮地完成了任务，$N。我真的已经有很长时间没有看见像你这样有潜力有天赋的年轻术士了。我肯定会继续关注你的发展，并在你未来的试炼中帮助你。$B$B现在，让我来教你怎样召唤那个已经被你控制的魅魔。', '魅魔拥有能穿越虚无的强大力量，是最危险的生物之一，她经常将弱者们玩弄于股掌之间。$B$B从现在开始，你得永远记住这一点。', '', '去找提瑞斯法林地的凯伦丁·哈加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1475, '进入阿塔哈卡神庙', '根据传说，阿塔哈卡神庙是供奉着古代神祗“夺魂者阿塔哈卡”的神圣祭坛，有一个名叫阿塔莱的巨魔部族世世代代守护着这座庙宇，据说从来也没人能进到庙中去一窥究竟。$b$b潜到泪水之池底部并从庙中取出古代的神器是件很困难的事，但这却正是我要你去做的，$n。$b$b帮我收集一些完整的阿塔莱石板，把它们带回来给我，这样一来我就能以英雄的身份回到探险者协会去了。我会和你一起分享这份荣耀。', '为暴风城的布罗哈恩·铁桶收集10块阿塔莱石板。', '阿塔莱石板!太感谢你了，$N!$B$B我马上就将这个送去探险者协会，我们的名字将一起被载入史册。你帮助我这个老矮人完成了一生中的最后一件心愿。为此我将永远对你心存感激!', '我已经不能再胜任一个冒险者的工作了，所以我希望你能帮忙，$N，帮我为探险者协会完成这最后的任务吧。如果我这身老骨头还有力气闯入悲伤沼泽、潜进神庙里的话，我肯定会和你并肩作战的。$B$B尽管我的自尊让我很难开口来要求你的帮助，但我的年纪让我不得不这么做。$B$B拜托你了，$N。我想在完成了探险者协会交给我的最后一个任务之后就光荣退休。', '', '去找暴风城的布罗哈恩·铁桶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1476, '纯洁者精华', '有荣誉感与善良的人？这种人到底存在过吗？$b$b在进行了多年的研究并翻阅了无数的典籍与传说之后，我终于找到了两个符合我们标准的人。$b$b第一个叫达林·弗治维特，他将自己的全部身心都投入到了拯救那些被遗弃在格雷迈恩之墙外的洛丹伦难民的事业中。$b$b另一个叫科马·韦拉德。此人对他失踪了的爱人忠贞不渝，一直以来都在湿地中寻找着他的爱人的下落。$b$b把他们的精华交给凯伦丁，不过首先，让我先告诉你到哪里去找。', '将达林和科马的精华交给诅咒神殿里的凯伦丁·哈加尔。', '从表面上看的话，所谓善良人的心脏似乎看起来也跟别的心脏没什么区别，你觉得呢?$B$B好吧，或许下次我们应该弄些能跟别的东西区分开的东西……啊，这些足够用了。魅魔无疑会被这些心脏所吸引的。', '我对你当前的进展速度非常满意，$N。若能马上把心脏拿来，我对你将更满意。', '', '去找提瑞斯法林地的凯伦丁·哈加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1479, '永恒之树', '我听说过一个故事，故事里面说暗夜精灵的银行是建在一棵树里面的，那棵树看上去像一头熊！真是太酷了！暗夜精灵非常注重保护自然的和谐，但是熊熊听上去就很震撼！$B$B带我去看看那棵“熊树”吧？求求你了！有一条船会带我们去那里，一点都不远。求你了求你了求你了！', '带着你看护的孤儿去达纳苏斯的银行。银行就坐落在一棵中空的树里，它被称为永恒之树。', '哇，这比我想象中的还要酷―永恒之树!我没有想到它居然那么大，但是它真的有那么大!你看到树顶的小鸟了没有?!我不知道它们怎么能到那么高的地方去!$B$B谢谢你把我带到达纳苏斯来，$N。你真好!', '我们到了吗?', '参观达纳苏斯的银行。', '去找人类孤儿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1480, '堕落者', '这片被裁下来的皮子很臭，似乎已经有点腐烂了, 值得注意的是，这块看上去干燥而松脆的东西却异常柔软。$B$B在摊开它之后，你可以清楚地看见其中一面上有着用某种语言写成的红色标记文字。在皮子的底端有一个十分清晰的符号，你认为这是个签名。$B$B也许玛乌林能告诉你些什么？', '把恶魔之皮拿给凄凉之地的玛乌林·碎骨看看。', '嗯，这些符文确实是某种语言，$N，某种古老的语言。它们似乎与艾瑞达语有点类似，但仍然与其相去甚远。如果我没有看错的话，这是某种契约……你看这里，没错……这个符文正是一个恶魔的签名:阿兹雷索克领主。', '燃刃族开始意识到他们有多么的渺小了。他们的魔法是肤浅的，他们的力量是薄弱的。$B$B他们唯一可以依靠的力量来自他们所侍奉的主人，而不是来自于对于力量与知识的真正理解和掌握。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1481, '堕落者', '我可以在拥有适当材料的情况下找到这个恶魔领主。$B$B如果他确实如我推测的一般强大，那我就得先准备一些只有从非常危险的生物身上才能收集到的物品。既然你是为酋长做事的，那么我想你应该会接受我交付给你的任务吧。$B$B首先，我需要破坏他的反侦测结界。去给我找一块萨特的头皮来，不过并不是任何萨特的头皮都可以的，只有怨怒巡影者的头皮才能用。$B$B从凄凉之地东北部的古代遗迹附近开始找起吧。', '给凄凉之地的玛乌林·碎骨带回一张巡影者的头皮。', '很显然的巡影者没办法对付你，$C。真是令人印象深刻……非常深刻。$B$B这块头皮很适合我的法术。你不在的时候，我也已经准备好了其他的法术材料。$B$B我差不多都准备好了，我现在只需要集中精神施展这个法术—它就会把那个恶魔领主的影像和他的行踪展示给我们。', '别带错的头皮给我，$C。如果用错材料的话，可是会要我们的命的。这个恶魔领主的身上可能有很多法术可以用来杀死那些想侦测他的人。$B$B命运已经让我品尝过那样的苦楚了。', '', '去凄凉之地找幽灵岗哨的玛乌林·碎骨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1482, '堕落者', '如果有一块神谕水晶就好了。这种东西一般都是由纳迦制造出来用于预言的。$B$B从这里向西北方向走，一直沿着海岸线前进，你会看到一个巨大的珊瑚礁，纳迦们通常在那一带活动。你可以在那里找到神谕水晶。滑刃纳迦并非善类，而且他们也不会对你的闯入表示欢迎，所以你要小心点，动作快点。$B$B等你回来以后，我们就可以开始寻找魔王阿兹雷索克了。', '给凄凉之地的玛乌林·碎骨带回一块神谕水晶。', '就是这个，珍贵的神谕水晶……完美无暇……美丽动人。$B$B我们马上开始吧。找到恶魔领主将是我们的首要任务，而刺杀他则需要我们全心投入去行动。$B$B退后点，$C，让我们看这恶魔究竟是什么样子，还有他现在躲在哪儿。', '我已经都准备好，就等神谕水晶了，$C。找到并除掉阿兹雷索克领主将为大酋长带来一个巨大的好处。我们得好好合作，尽快完成这件事，这样无论对我们还是酋长都有好处。', '', '去凄凉之地找幽灵岗哨的玛乌林·碎骨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1485, '邪灵劣魔', '我们之前的术士，在这里得到的只有部落的不信任，虽然我们现在得到了一些容忍，但是部落仍然对我们没有丝毫敬爱。$b$b这令我们术士们更加团结在一起，当然，也有一些人选择了隐居的生活，独自研究着他们的魔法。我不会强迫或引导你选择其中的任何一条道路，只会帮助你变得更加成熟。$b$b在我教会你召唤恶魔的方法之前，先给我带六颗邪灵劣魔的徽记回来，在东北方的山洞里就能找到这种生物。', '给鲁赞带回6颗邪灵劣魔的徽记。', '通过接受术士魔法的训练，你将会学习到召唤各类生物的方法。虽然这些召唤出来的东西看起来都很贫弱，但它们都是很有用的工具。$B$B别被小鬼瘦小的身躯给欺骗了。正如你所注意到的一样，其实它也是一个很难对付的敌手。', '控制住你用魔法召唤出来的生物是非常重要的一件事情。你得弄清楚，学习术士的魔法与行事之道并非是什么有趣的事情，若是在你做好准备之前，就教导你过于高深的知识是会让你丢掉性命的。', '', '去杜隆塔尔找试炼谷的鲁赞。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1486, '变异皮革', '由于纳拉雷克斯彻底陷入了他的恶梦之中，有一种此前没有见过的野兽突然侵入了哀嚎洞穴。$b$b这些邪恶的生物有着某种奇怪的、不属于这个世界的特性。在我看来，虽然它们本性邪恶，但它们的存在对卡利姆多的居民也并不是完全没有价值的。我相信它们的皮革在制皮业中可能会非常有用。$b$b如果你愿意接下这个任务的话，那就到洞穴深处去，想办法帮我找一些变异皮革吧。', '哀嚎洞穴的纳尔帕克想要20张变异皮革。', '你收集了这么多的皮，我是不会忘记你的功绩的，$N。$B$B非常感谢你!', '我对这些生活在洞穴中的变异生物身上的皮非常感兴趣。你弄到足够的皮了吗，$C?', '', '去找贫瘠之地的纳尔帕克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1487, '清除变异者', '纳拉雷克斯有着一个崇高的目标。$b$b我们这位伟大的领袖一直想要进入翡翠梦境，将那片如今已经变得一片荒芜的土地变回过去那样茂密的森林，但似乎有一些可怕的事发生了。$b$b纳拉雷克斯的梦境不知为什么突然转化成了一场恶梦，同时，大量的堕落生物出现在了洞穴之中。$b$b一些纳拉雷克斯的信徒正在想办法来唤醒我们的领袖，而我此时的职责就是清除洞穴中的那些邪恶生物。$b$b去吧，$n，勇敢地把那些变异的生物都清除干净。', '哀嚎洞穴的厄布鲁要求你杀掉7只变异破坏者、7只剧毒飞蛇、7只变异蹒跚者和7只变异尖牙风蛇。', '身为纳拉雷克斯的信徒，我对你的英勇与无畏表示赞赏，$N。$B$B清理干净这些洞穴将是我们重建贫瘠之地大计的第一步。$B$B感谢你，祝好运与你同在。', '$N，我们这些纳拉雷克斯的信徒需要你的帮助。我们的人数随着领袖陷入了他扭曲的梦魇而不断地减少。因此，我们已经没有足够的力量去对付那些占据了洞穴的堕落生物了。$B$B我请求你，$C，进入那些洞穴，把那些该死的变异生物都杀光吧!', '', '去找贫瘠之地的厄布鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1488, '堕落者', '虽然我对这个魔王阿兹雷索克一无所知，但我同意玛乌林的观点：我们一定要尽快消灭掉这个恶魔，尤其是他正在逐渐控制火刃氏族为他的邪恶目的服务。$B$B到了你实现自己的诺言，为酋长和部落而战的时候了，我也相信你有能力召集一只小队去刺杀这个恶魔领主和他的爪牙。$B$B如果你准备好了，就直接向南方出发，消灭了这个威胁之后就回来向我复命。', '杀掉魔王阿兹雷索克和祖格卡，然后向凄凉之地的塔卡塔·钢刃复命。', '这对我们所有人来说都是一次重大的胜利，$N。让我们为你的成功而欣喜吧!我相信我们的未来不会再像我当初所想象的那样苍白了。$B$B恶魔们都将被消灭干净，火刃氏族也将不得不接受早已注定了的失败命运，而我们终究会再度得到一片我们可以称之为“家”的宁静土地。', '荣耀归于部落，而死亡归于吾敌，$N!$B$B凄凉之地的恶魔领主比以前更具威胁性了，我希望以后去觐见大酋长的时候，每次都能向他报告好消息，而不是像现在这样……$B$B有些时候，我真希望只有半人马需要对付。', '', '去凄凉之地找幽灵岗哨的塔卡塔·钢刃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1489, '哈缪尔·符文图腾', '你带来的兽皮有一种奇怪的斑点，一种我从来没有见过的斑点。我确信绿洲里的水是造成这些斑点的原因，我甚至能够感受到它们给这片土地带来的混乱，这片土地现在死气沉沉的，就好像是长眠不醒了一样。$B$B哀嚎洞穴一定就是这一切问题的源头。但是，在你去那里调查以前，先去找德鲁伊长老哈缪尔·符文图腾谈谈吧。我托人给他捎了信，把关于在贫瘠之地所发生的一切都转告给他了。这位博学的长者应该能给你很多忠告。$B$B他就在雷霆崖的长者高地上。', '和哈缪尔·符文图腾谈一谈。', '$N，你好。欢迎你来到这里，我建议你做好充分的准备，因为接下来我将交给你一个艰巨的任务。', '你师傅们把你派到这里实在太蠢，因为我再也不是天灾的奴隶了！', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1491, '智慧饮料', '好吧，这些角似乎不太有用。不过没关系——万事开头难嘛！我想我已经找到另一种原料，可以让我制造出更好的智慧饮料！$B$B有一种叫做哀嚎香精的物质，我想这种东西就是造成贫瘠之地出现各种奇特动植物的原因。帮我找到这种物质，我要把它加入我的饮料里试试看！$B$B我听说这种物质可以在西边的哀嚎洞穴里的那些怪物身上找到，去猎捕这种生物，帮我收集哀嚎香精吧。', '收集6份哀嚎香精，把它们交给棘齿城的麦伯克·米希瑞克斯。', '好样的，你找到这东西了!我已经等不及要试试它了。我就知道我会赚一笔大钱的!$B$B谢谢你，$N。请接受这个作为报酬吧。我发誓，等我赚到了钱，就会给你更多报酬!', '我要的哀嚎香精在哪里?', '', '去找贫瘠之地的麦伯克·米希瑞克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1492, '码头管理员迪兹维格', '我需要把一只装有药品、材料和其它物品的箱子送给我在卡利姆多的合伙人。我没时间把它送到棘齿城的码头上去，况且最后一支商队也早已经起航了。$b$b如果你方便的话，请把这只箱子交给码头管理员迪兹维格，他会把这只箱子放在下一班开往黑水湾的船上。', '把保险箱交给棘齿城的码头管理员迪兹维格。', '这么小的木箱。嗯，我应该能在船上找一个放木箱的地方。船会在下一次涨潮的时候出发，可以吗?好极了。让我把它记入货物帐目里去。$B$B好了，一切搞定!再见，$C。', '你是想搭下一班船呢，还是你有什么东西要送?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1498, '防御之道', '作为一个战士，你最重要的任务是……保护。我们是部落的护盾和壁垒，我们要保护比我们弱小的同胞的安全。如果你要加入我们，那你就必须先证明自己与我们一样拥有着无比的勇气。$B$B到杜隆塔尔的雷霆山去，那里有不少闪电蜥蜴和雷霆蜥蜴。去猎捕那些蜥蜴，向我证明你比它们更加强大！在它们的攻击面前要毫不畏缩，把它们的鳞片给我带回来作为证明。$B$B快点出发吧，完成这个任务之后，我将继续让你进行训练课程。', '给贫瘠之地前沿哨所的犹塞克带回5块烧焦的鳞片。', '啊。看来你已经击败雷霆蜥蜴了，这证明你具有足够坚韧的意志。现在我将告诉你如何将坚实的肌肉和精良的技巧结合，以形成一堵坚不可摧的防御长城。$B$B好好学习这一课吧，$N。', '你拿到鳞片了吗，$N?除非你可以承受那些雷霆蜥蜴的猛烈攻击，否则我不会给你任何好处的。', '', '去找贫瘠之地的犹塞克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1501, '虚空中的生物', '很少有术士能活得够久的……我们冒着巨大的风险来研究恶魔，风险越大，回报越大。你必须尽快成熟起来，这样才会成为对酋长和部落有用的人。$b$b现在是该让你去学习新的召唤法术了。$b$b首先，你必须夺回维尔加石板，那个东西被火刃氏族的术士偷走了，现在石板被保存在他们的巢穴里，那个巢穴就在奥格瑞玛城东的骷髅石。有了石板之后，我会教你如何召唤虚空行者。', '为奥格瑞玛的甘鲁尔·血眼找回维尔加石板。', '做得好。我想你在取回这东西的时候，还顺便让燃刃氏族吃了些苦头吧?$B$B他们实在是大酋长的心头大患，也是我们术士中的败类。', '你找到维尔加石板了吗，$N?没有它的话，我是不会和你说任何事的。', '', '去找奥格瑞玛的甘鲁尔·血眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1503, '锻造好的钢锭', '$N，我会给你一柄武器，但首先我需要你的帮助。几天前的一个晚上，西北边的那些钢鬃部落的家伙摸进了我的营地，他们不敢和我正面交战，但是他们知道我眼睛不好使，所以就想办法用响声把我引出来，然后派几个同伙溜进去偷了我的东西！$B$B他们偷走了一只铁箱子，里面是一些铸造好的钢锭。如果你能够找到它们的话，我就会给你一件你用得到的武器。$B$B你应该可以在钢鬃野猪人的营地里找到那只铁箱子，把那些钢锭给我拿回来。', '把锻造好的钢锭带给贫瘠之地的索恩格瑞姆·火眼。', '你找到它们了!所有的钢锭都在这里，我早就知道凭钢鬃野猪人的智商是不知道怎么使用这些钢锭的。$B$B谢谢你，$N。这是给你的奖励，希望它能在你将来的战斗中发挥应有的作用。', '你找到我的那些钢锭了吗?', '', '去贫瘠之地找荆棘岭的索恩格瑞姆·火眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1504, '誓缚', '现在，看着这块维尔加石板，这上面雕刻着的文字会告诉你怎样进行召唤仪式。把它拿到洞穴另一边，放在尼尔鲁·火刃帐篷里的法阵上，然后你就可以开始召唤虚空行者了。$b$b无论用格斗也好，用魔法也好，你必须仅凭自己的力量独立战胜它。在这一切都完成之后，带着石板回来找我，我将为你和这个强大的恶魔制定永恒的盟约。', '召唤并征服一只虚空行者，然后带着召唤铭文向奥格瑞玛的甘鲁尔·血眼回报。', '干得好，$N。研究一下这份古卷，它将告诉你如何将你刚才击败了的虚无行者再次召唤出来。$B$B你应该知道我对你抱有很高的期望，而你也从没有辜负过我，至少到当前为止是这样的。$B$B不过，无论是什么事情都不要看得太重，你必须以平常心来看待这些事，就像每天早上起床洗漱一样简单而自然地做好它们。', '虚无行者是一种强大的生物。我现在还清晰地记得当年我与它战斗时的情景，$N。经过了这么多年，我的虚无行者已经很少与我发生冲突了，我想这也许是它想让我放松警惕的缘故吧。$B$B牢牢记住这一点，$N。', '', '去找奥格瑞玛的甘鲁尔·血眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1511, '肯兹格拉的伤药', '我得告诉你们，可能还会有其它人来向我讨伤药，所以我得在这里随时做好准备。$b$b快回去吧，$n。你得注意，一开始只能给他一半伤药！这一半足以让他在活动的时候不再出血，免得失血过多而死。等过了一个晚上之后再给他另一半。$b$b总之，你得把它带给陶拉祖营地里的劳格玛。根据他派来的上一个信使所说的，他应该已经知道多格兰被关在哪儿了。', '将肯兹格拉的伤药交给陶拉祖营地的步兵劳格玛。', '太好了!多格兰恐怕已经奄奄一息，就等着这东西救命了!$B$B我们得赶紧把这个送到他那里，可是这儿几乎所有的蛮兵都出去寻找补给物资了……', '怎么啦?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1512, '爱的礼物', '赞卡沙年轻而美丽，却得跟一个残废过上一辈子……我可不能让她受这种苦。$b$b别管我了，$n。谢谢你。我将会在战斗中光荣地结束我的生命，而不是拖着这破碎的躯壳白白度过后半辈子。$b$b拜托，别把这些告诉我的老婆……我可不想让她在良心上受谴责。', '把沾满泥土的坠饰带给奥格瑞玛的甘鲁尔·血眼。', '既然你告诉我这个东西确实达到了要求，那我就相信你，$N。容我把它弄弄干净……质朴而闪光，这对魅魔来说可的确是个好媒质。', '你回来了。准备好挑战魅魔了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1513, '誓缚', '把这个放进尼尔鲁帐篷里的召唤法阵，召唤出那邪恶的魅魔，并将她纳入你的掌握。我相信你的魔法能力已经足够强大了。不过你也要和平常一样小心，因为骄傲和过分的自信曾经毁灭过不少前途无量的术士。$b$b在你战胜魅魔以后，把那个坠饰拿给我，我好把消息告诉给赞卡沙。', '召唤并征服一只魅魔，然后将多格兰的坠饰还给奥格瑞玛的甘鲁尔·血眼。', '成功了!我想你确实达到了我的期望。$B$B你已经证明了自己的价值，我对能把召唤和征服魅魔的方法传授给你而感到十分高兴。去吧，你还有很多东西要学，当我下次再见到你的时候，希望你能真正地掌握和操控你的魅魔。$B$B别再去想那些关于多格兰与赞卡沙的悲伤故事了，这种事情在我们漫长的生命中还会遇到很多，但你要永远记住它，并且将其用于保护自己，以免心智反被你所学的黑暗力量侵蚀。', '一看到魅魔，我的心脏就开始咆哮……但与此同时，我能感觉到我的灵魂正在迅速消逝，如海潮退却一般地衰减。$B$B你要多加小心，我的朋友。', '', '去找奥格瑞玛的甘鲁尔·血眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1514, '被腐化的迎风花', '', '', '你将两份塞纳里奥植物药膏涂在了这株迎风花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的迎风花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1515, '多格兰之囚', '你为这件事儿出了很多力，所以你如果愿意帮忙帮到底的话，我当然不会阻止你。但我没办法派给你更多的人了，所以你恐怕只能一个人去救多格兰……$b$b多格兰被关在北边的一处野猪人营地里。注意那里的两座小屋子，如果他还没被杀掉或者因为伤口恶化而死掉的话，那群野猪人应该会严密看守他的。$b$b祝你好运。', '把肯兹格拉的伤药带给贫瘠之地的多格兰。', '这药可真够难喝的……$B$B我感觉我现在又有劲了，能爬着走了……但我的腿，我怕以后得落下个终身残疾了。我的胳膊也不行了。', '啊啊啊……有人来救我了吗……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1516, '大地的召唤', '是时候了，年轻的$c。你的肉体已经足够强壮，而你的精神也已如大地一般坚韧。你选择了遵循萨满之道，这代表着你拥有无可置疑的睿智。$B$b让大地来指引你的命运，让它成为你的一部分吧。但你必须自己去面对大地的力量，如果你已经准备妥当，你就会看见一些只有萨满祭司才能理解的事物。$B$B去北边去搜寻那些地狱捕猎者，给我带一对它们的蹄子回来，然后我们再来好谈谈你的未来。', '给试炼谷的坎纳甘·地鸣带去2只地狱捕猎者的蹄子。', '很好。你的成功代表着你已经准备好进入下一个步骤了。$B$B在所有的元素之中，大地元素代表着世间的所有事物得以存在的基石。它就是你的力量，你的韧性，以及你的耐心。大地会保护你，但首先你必须对它随时抱持着适当的尊敬。如同其它元素一样，大地也是变换无常的。它是生命的根本，通过观察它运行的规则，你将会学到许多东西。永远不要忘记它与你分享的秘密。$B$B我现在就要开始做你的灵契了，得到它之后，你将踏上新的萨满之道。', '坚韧是大地最伟大的美德。大地见证着万物归环的道理:巍峨的高山或许会变为平坦的沙漠，宽阔的河流或许会变为狭窄的溪谷。大地的元素是所有元素之中最亘古不变且最为睿智的，它不会容忍任何急躁的行为。$B$B时间就要到了，大地将会召唤你。当你在成功后再度回到我这里来的时候，你就会对它有更深的了解。$B$B无知者会因你的睿智而嫉妒你，因他们的渺小而憎恨你。', '', '去杜隆塔尔找试炼谷的坎纳甘·地鸣。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1518, '大地的召唤', '把这块粗石英交给坎纳甘·地鸣，以此证实我们会过面了。他将会为你制造一根图腾，而这块小圆石则会是图腾的核心。可能它看上去小了点，不过你马上就会知道，尺寸并不重要，即使是最小的石子也可能比山川还要恒久。$B$B耐心一点，$N。继续保持强健的体魄，并努力追寻智慧吧。这是大地对你的要求。最终，你也将融入大地中，尊重它，它也会尊重你。', '把粗石英交给试炼谷的坎纳甘·地鸣。', '太棒了!$B$B我将要刻给你的图腾不仅仅是你萨满身份的标志―它的力量远远超乎你的想象。图腾的用途之一就是集中法术的能量，那些法术多是与大地联系在一起的，随着你的成长，你也就可以逐渐领会更多大地的精髓。$B$B遍及卡利姆多大陆各处的训练师将会在适当的时候教会你更多的知识，当你觉得该学习一些新知识的时候，就去寻找他们吧。$B$B现在，拿着你的图腾，还有这个能教会你第一项基本能力的卷轴。', '希望我是第一个欢迎你踏上萨满之道的人。$B$B如果你已经拥有了大地赐予你的石头，那么我就会按约定把图腾交给你。$B$B但如果你还没得到，那么就继续去追寻吧。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1519, '大地的召唤', '是时候了，年轻的$c。你的身体已经够强壮，你的精神如大地一般坚韧，这正是你已经成熟的标志。$B$B大地引领并教导着我们的族人，以后你也将得到它的指引。但在那之前，你必须先通过试炼。在你完成了试炼之后，就会看到那些只有我们才能看到的东西。$B$B往东边去，找到刺背野猪人的萨满祭司，把他们在仪式中使用的药膏拿回来一些。在你得到了足够的药膏之后再回来向我复命。', '给纳拉其营地的鸦羽先知带回2份仪式药膏。', '很好，$N。你的归来代表着你已经准备好进行下一个步骤了。$B$B在所有的元素之中，土元素代表着世间所有事物存在的基石。它是你的力量，你的体质，以及你的耐心。大地之母会保护你，但首先你必须对她有着适当的尊敬。她是生命的根本，通过了解她的法则，你将会学到许多知识―永远不要忘记她教给你的东西。$B$B我现在要开始为你制作灵契了，得到它之后，你将踏上一条新的道路。', '大地是宽容的，她将等到你完全准备好接受挑战为止，因为她知道，随着时间的流逝，事物会腐朽入土，也会获得新生。这是万物的轮回。巍峨的高山会变为平坦的沙漠，宽阔的河流会变为狭窄的溪谷，而大地是所有自然的元素之中最恒久睿智的。$B$B你也必须要拥有这样凌驾于一切之上的宽容与韧性。大地之所以对你发出了感召，是因为她认为你已经准备好了。将这次的仪式作为你重生的祭典吧，从此你将告别野蛮和无知。', '', '去莫高雷找红云台地的鸦羽先知。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1521, '大地的召唤', '把这块粗石英交给鸦羽先知，这是我们会过面的证明。她将会为你制造一根图腾柱，而这块小圆石则是那根柱子的核心。它可能看上去小了点，不过你马上就会知道，尺寸并不重要，即使是最小的石子也可能比整座山岭还要恒久。$B$B耐心一些，$N。在保持着力量的同时追寻智慧吧，这是大地对你的要求。最终你将会成为大地的一份子，尊重它，它也会尊重你。', '将粗石英带给纳拉其营地的鸦羽先知。', '很好。$B$B我将要为你制作的图腾柱不仅仅是一个标志―它还拥有强大的力量。图腾柱的一大用途是集中法术的能量。那些法术都是与大地联系在一起的，在你获得了更大的智慧之后，更多与大地相关的能力也会为你所用。遍及卡利姆多大陆各处的训练师将会在适当的时候教会你更多的知识，当你认为自己已经准备好了的时候，就去找他们吧。$B$B现在，拿着你的图腾柱，还有这个能教会你使用第一个大地法术的卷轴。', '你好，$N。如果你没有完成你的任务，你就不用再回来找我了。愿我能成为第一个欢迎你踏上你萨满道路的人。$B$B如果你已经拥有了土元素交给你的石头，我将会按照约定把图腾柱给你。如果你没得到，那么很可惜。只有当你将自身完全奉献给元素时，拥有它才会值得你自豪，也只有那样，拥有它才会有意义。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1524, '火焰的召唤', '你已经有足够的力量来运用火焰图腾了，不过这并不意味着你已作好了充分的准备。$B$B沿着杜隆塔尔的怒水河前进，在河水流入无尽之海的地方，有一条隐蔽的小路，它通向这片大陆上最高的山峰之一。沿着这条小路走到最高处，你就会看到一处由泰尔夫·祖拉姆看守的圣殿，那就是眠炎圣殿。$B$B把这个火炬交给泰尔夫·祖拉姆，它是你试图驯服火焰力量的证明。用圣殿里的火盆点燃火炬并把它带回来，我就会将火焰图腾交给你。', '把眠炎火炬带给杜隆塔尔的泰尔夫·祖拉姆。', '啊，是我的错，我不知道你带着火炬，$N，请接受我最真诚的歉意，很高兴认识你。$B$B很多人冒着艰险找到这里，只为寻找失落的财宝或是捕杀神秘的生物，最后却看到这里似乎空无一物，便只能悻悻而归。只有我们知道这里的秘密，对吗，$N?$B$B这座圣殿中隐藏着一个巨大的秘密，对于绝大多数部落的成员来说，他们一生都不会对此有丝毫的了解。对我们而言，这里是极为神圣的。', '恭喜你，$N。你已经来到来眠炎圣殿，只有那些通晓萨满之道的人才能发现这里的秘密，以及蕴藏在这里的巨大能量。但是很抱歉，你长途跋涉来到这里，现在有必须原路返回。这一路的确危机四伏，但是作为圣殿的守护人，我不能让任何人在这里游荡。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1525, '火焰的召唤', '你该不是到这儿来上历史课的吧？你是要得到永恒之火和你的火焰图腾。$B$B首先，你要制造一个灵契，并将你和它连接起来。$B$B只要你给我找来两样东西，我就可以为你制造火焰灵契。第一件是火焰焦油，这个相对而言比较简单，钢鬃野猪人的施法者通常会带着这种东西。$B$B另一件则比较危险：从火刃氏族的祭司身上找一个试剂袋。你可以在奥格瑞玛东部找到他们。', '找到1个火焰焦油和1个试剂袋，把它们交给杜隆塔尔的泰尔夫·祖拉姆。', '这些就可以了，$N。$B$B火焰并不只是混乱和毁灭的力量―你一定要牢牢记住这一点。它也是一种生命和创造的力量，因为世间万物都有着千丝万缕的联系。它们彼此之间互相排斥，但任何一种失去了对立面的力量都无法独存;它们要消灭对立的力量，但只有在这种抗衡中才能体现出它们存在的意义，正如光与影，火与冰。永远不要忘了这一点。$B$B运用不同的、甚至是对立的魔法所需要的不仅仅是精湛的技艺，还有超群的智慧。', '只要你能找来试剂袋和火焰焦油，我就可以给你制作火焰灵契。燃刃祭司的试剂袋里通常都装着制作火焰灵契所需的所有材料，而且数量也很充足。$B$B只有用与某种元素属性相同的材料才能制成那种元素的灵契，这也让我们的工作轻松了不少，只要去找那些成天和火焰打交道的术士就行了。', '', '去杜隆塔尔找眠炎圣殿的泰尔夫·祖拉姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1526, '火焰的召唤', '火焰灵契已经做好了，现在你必须面对火焰元素的灵魂。在圣殿中使用灵契，然后去挑战山顶上的火焰之魂。他不会在你没有准备好的时候就攻击你，不过他知道你能看见他。$B$B你必须迅速打倒他，$N，拖得越久他的力量就会越强大。在击败他之后，将他的馀烬放在火盆里，然后点燃火炬。', '击败火焰之魂，将馀烬放在恒焰圣殿屋顶的火盆里。', '当你将馀烬投入碗里之后，一团白色火焰随即燃起。你能感受到灵契的神奇力量在你体中流过，也能看到火光在你面前舞动。$B$B你将火炬的前端伸进盆里，它立刻就被点燃了。', '火盆只有你的三分之一高，看起来没什么特别，只是在光滑的金属围栏上刻有文字。整座火盆都没有任何风化侵蚀的痕迹，摆在顶端的小碗摸上去十分冰凉。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1527, '火焰的召唤', '你手中紧握着火炬离开火盆，望向远处的杜隆塔尔，神圣的火焰随风狂舞，令你感到心中充满了激动和兴奋。$B$B你沿着小路回到贫瘠之地去找卡纳尔·菲斯。', '将恒焰火炬交给贫瘠之地的卡纳尔·菲斯。', '你的意志燃烧得比我见过的任何火炬都要更加明亮，$N，你应该为此感到骄傲。$B$B继续沿着萨满之道走下去，你终将获得驾驭元素的力量，我们的同胞也将向你寻求指引和智慧。恭喜你得到这宝贵的图腾。', '嗯，这不是$N吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1534, '水之召唤', '现在，你必须带上这个水囊，深入到那片被暗夜精灵称为灰谷的茂密森林中，那地方就在贫瘠之地的北方。$B$B进入森林之后向西走，顺着隔断石爪山与灰谷的山脉前进，你会在密斯特拉湖的尽头发现一处圣地：星尘废墟。在那里的湖中央有一眼小喷泉。$B$B取回一些喷泉水，那是制作灵契所需的最后一种水样，然后我就可以把你送回伊斯伦那里了。', '到灰谷的星尘废墟去，将空的蓝色水囊盛满泉水，然后把它交给贫瘠之地的布瑞恩。', '干得漂亮，$N。有了这三种泉水的样品，我就能为你制造出一小瓶所有生命都在寻找的最纯洁的水。它将被用于你下一步的祭仪之中。$B$B$N，我很高兴你能加入到我们的行列。你是所有萨满的骄傲，我期待着你将来创建一番丰功伟绩。', '你找到泉水了吗，$N?传说有强大的生物保卫着那片废墟，它们不惧怕任何不速之客。不过，那可能只是夜精灵用来吓唬敌人的伎俩而已。$B$B不管怎么样，你要多加小心。', '', '去贫瘠之地找黑棘山的布瑞恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1535, '水之召唤', '要得到我的信任并从我这里取得灵契，你就必须找到最纯洁的水。在你寻找这种水样时，别忘了注意周围的动静。要小心那些依赖这种水生存并守护着它的生物，要注意这种水是如何影响森林和荒漠的。看看这种维持生命的特殊物质是如何强迫这些生物进行杀戮的。$B$B让我们先从一个简单的任务开始吧：在我的小屋下面有一小池这种珍贵的液体，装满这个水囊后再回来找我。', '到野猪人的水池去，用井中的水装满空的棕色水囊，然后把水囊交给贫瘠之地的布瑞恩。', '如果你去那个池塘取水，那么流血冲突肯定是不可避免的。很遗憾，野猪人没有意识到所有的生物都是相互依存的，他们的贪婪只会无休止地延续他们自己的伤痛与苦难。如果他们能停止内乱，将所有的野猪人氏族都联合起来，那么现在的状况肯定会大不一样。$B$B这确实是一个遗憾，不过这对于贫瘠之地的其它种群来说，也不失为一种恩赐。', '我正在准备交给你下一项任务。你装满水囊了吗?$B$B我知道这些野猪人会拼命保护他们的水源，即便是一滴水对他们来说也是一笔巨大的财富。偶然降临贫瘠之地的毛毛细雨对他们而言也不啻为一场盛筵。他们将水视为神圣之物，因为它是如此稀少。你明白了吗?', '', '去贫瘠之地找黑棘山的布瑞恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1536, '水之召唤', '很久以前，我和一些同伴一起去过希尔斯布莱德丘陵。我们为了保护自己而和那里的人类作战，后来发现自己正置身于一个由被遗忘者控制的小镇：塔伦米尔。$B$B在那里，我有一个特别的发现：小镇中心有一口清泉小井。我不清楚镇中那些被感染的居民是否清楚它的价值——那口井是那片被亵渎的土地上唯一一块未受亵渎的神圣之地。$B$B用这只水囊帮我带回一些那口井里的水。', '用塔伦米尔的井水装满空的红色水囊，然后把它交给贫瘠之地的布瑞恩。', '很好，$N。你的不懈努力终于使你完成了这个任务，同时也证明了你的能力。$B$B我还需要一份水样就能凑齐制作灵契所需的材料了，伊斯伦也会为你高兴的。', '$N，镇中那口井依然保持纯洁，这让我想起年轻时曾听到过的故事。即使是在最痛苦和最悲伤的时候，你也能找到一丝微弱的希望和重新振作的可能。兽人眼中的萨尔就是这样一种象征，他从绝境中站立起来，用他的力量和精神指引着他的人民。$B$B我想不会有哪个兽人和他一样经历过如此多的磨难，当然，也不会有谁像他那样强大。', '', '去贫瘠之地找黑棘山的布瑞恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1558, '巨石水坝', '铁炉堡是矮人和侏儒的聚居地。在这附近有个地方叫做洛克莫丹，矮人在那里建造了一座巨大的水坝。他们说那是世界上最壮观的建筑！$B$B你能不能把我带到洛克莫丹去看看那座水坝呢？我想那座水坝叫巨砖……嗯……巨墙？巨石水坝？它很大——绝对大得让你吃惊。我想要去看看那里的巨大瀑布……我保证我绝对会紧紧跟着你的！', '带着你看护的孤儿去洛克莫丹的巨石水坝。你应该带他去水坝的中间，然后让他俯瞰巨大的瀑布。', '哇―这座水坝比我想象中的还要宏伟!轰鸣的瀑布声几乎让我无法听到自己说话的声音!嘿，你认为这里的水会不会流光?你说如果这座水坝破了会怎么样!啊，那真是太恐怖了!$B$B感谢你带我来看这座水坝，你真好。我说过我不会跑得太远的!', '我们到了吗?', '参观洛克莫丹的巨石水坝。', '去找人类孤儿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1578, '前线的补给', '洛克莫丹的巡山人正在和穴居人战斗，可真是忙得不可开交呢！要对付那些穴居人，就必须给我们的部队不断提供盔甲和武器。$B$B这就是索瓦尔德待在那里的原因，他在为巡山人筹集足够的物资好让他们保持强大的战斗力。如果你能打造一些铜斧和铜质链甲腰带并把它们交给索瓦尔德的话，他一定会感激你的，没准他还会跟你分享他的知识和经验。$B$B索瓦尔德就在洛克莫丹的南部警戒塔。', '给洛克莫丹南部警戒塔的索瓦尔德带去6把铜斧和6条铜质链甲腰带。', '哦，对不起!我没想到你是来给我提供装备的。这些东西会给我们很大帮助!$B$B这里是一些盔甲的设计图，希望能对你有用。', '我没时间闲聊。你有事找我吗?', '', '去丹莫罗找南部警戒塔的索瓦尔德·深炉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1579, '小齿轮', '我到奥伯丁来仅仅是因为这里相当的安静。我喜欢在安静的地方进行发明创造，因为在一夜痛饮之后，铁炉堡的喧嚣足以让我发疯！$B$B因此我乘船来了奥伯丁，路上喝了不少酒，结果我一不小心就把一盒小齿轮掉在了船上！$B$B我不能确定把它们掉在什么地方了，但如果你愿意到大海里钓钓看的话，也许……', '收集8个小齿轮，把它们交给奥伯丁的维兹班恩·曲针。', '我简直不敢相信，你找到它们了!你一定是卡利姆多最幸运的$r!', '$N，你找到我的小齿轮了吗?没有小齿轮，我这个伟大的发明家就什么都干不了!', '', '去找奥伯丁的维兹班恩·曲针。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1580, '导电器', '我们知道你是个幸运星，不过……你到底有多少幸运呢，$N？$B$B有一天晚上，我沿着黑海岸的小路散步，想要找一条河或一片湖来试验我新发明的自行驱动火爆式诱鸭器，但那时我可能有点醉了……所以我一不留神就睡了过去，几个小时后醒来的时候已经在奥伯丁了。我的头发烧焦了，导电器也都不见了！我一定是把它们丢在水里了！$B$B也许你能在黑海岸附近的湖泊或是溪流中钓到它们……', '收集12个导电器，把它们交给奥伯丁的维兹班恩·曲针。', '难以置信!你居然找到了它们!你是我见过的最好的渔夫!$B$B谢谢你，$N。请接受这些吧。你是个优秀的$C，也许并不需要它们，不过也许你在钓鱼的时候用得到!', '你找到导电器了吗?我得有这些东西才能继续研制诱鸭器。', '', '去找奥伯丁的维兹班恩·曲针。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1581, '刃叶的药剂', '我们的药草和炼金原料店发展势头很快，但我的丈夫将太多的时间花在混合药剂上了，我们从来都没有时间留给彼此。$B$B如果你能弄来一些已经做好了的药剂，我可以拿一些珍贵的药草来和你交换，你看怎么样？', '给在多兰纳尔的塞拉尔·刃叶带去6瓶狮王之力药剂和2瓶初级防御药剂。', '这些药剂配制得很不错。$N，看得出你做生意很下工夫，这对一个炼金师来说是非常重要的。$B$B这些药草是刚刚收集来的，拿着吧。希望你好好利用它们。', '你好，$N。你弄到我要的药剂了吗?', '', '去找泰达希尔的塞拉尔·刃叶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1582, '月光外衣', '达纳苏斯的居民，尤其是像我这样的手工艺者，都是相当繁忙的。年轻的冒险家们很想在旷野里试试他们的身手，当然这就需要相应的装备来做保障。$B$B如果你能帮我搞到足够多的皮革制品的话，我也许会教你一些高级的制皮技术。', '把1双雕花皮手套、5双雕花皮靴和5件雕花皮质披风交给达纳苏斯的洛瑟里亚斯。', '啊，真是上等的皮货。你有灵巧的双手和善于捕捉细节的双眼。你将是个前途无量的制皮师。$B$B拿着这个，$N，这是制作月光外衣的图样。', '你好，$N。', '', '去找达纳苏斯的洛瑟里亚斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1598, '失窃的典籍', '嘿，说你哪！你叫$n，没错吧？$b$b我希望你确实想要成为一名术士，如果你不能执着于自己的信念的话，那你就可能会彻底迷失自我。$b$b我会给你指引，但我首先得确定你是否够格。$b$b不久前有一个在修道院中修行的学徒逃了出去，加入了迪菲亚兄弟会。为什么我会对这个如此介意呢？是这样的，他偷走了一些重要的典籍。$b$b其中有一本正好还是我很想要的，书名叫《虚空灵能》。你去把它给我偷回来，盗贼们应该把这些书藏在了他们农场中的帐篷里。', '为杜希拉·拉萨雷找回《虚空灵能》。', '好极了……过去我从来没有办法接近这本书，它被小心翼翼地保存在图书馆里，只要我试图接近它，其它人就会怀疑我。$B$B很好，你做的不错，我现在可以确信你有能力操纵你的小鬼了，那么就让我教你如何召唤小鬼吧。', '要我自己去把书从图书馆里偷来实在是太丢人现眼了，他们那帮蠢货可真是帮我大忙了。', '', '去艾尔文森林找北郡山谷的杜希拉·拉萨雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1599, '开端', '你就是那个每个人都说起的新术士吧。他们一定很喜欢你，不然他们就不会叫我抽出做研究的时间来培训你了。$b$b你要学的最简单的一种召唤咒语是召唤小鬼，不过在我把这种咒语传授给你之前，你必须要证明自己有控制小鬼所必需的魔法技能和身体素质。$b$b从西南洞穴里的霜鬃巨魔新兵那里给我拿三个羽毛咒符回来再说。', '给安威玛尔的阿拉玛尔·格里姆带回3个羽毛咒符。', '很好，很好!你干得很好，$N。不管怎样，人们对你那么感兴趣看来确实有些道理。$B$B至于以后他们对你还会不会继续感兴趣就是另一回事了，但首先你不能被自己召唤出来的小鬼给搞得焦头烂额。当前，我认为你有足够的能力作为术士好好地活上几个月。$B$B至于小鬼，$N，以我这个地精的经验来说，千万别被它的矮小所迷惑，它的魔法可是相当危险的。', '那些新兵们带着的羽毛符咒使他们拥有了一些魔法力量，研究它们是件有趣的事情，但是这些蠢货也只有这么点魔法能力了。', '', '去丹莫罗找寒脊山小径的阿拉玛尔·格里姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1618, '赤脊山的补给', '并不是只有我们矮人在战斗，事实上，我们的人类盟友也忙得不可开交！$B$B赤脊山不断受到黑石兽人的袭击，装备和物资也一直跟不上。如果你能提供一些帮助的话，他们的铁匠弗纳·奥斯古应该会教你一两招独家绝活。', '托姆斯·深炉要你给赤脊山的弗纳·奥斯古带去4条铜质符文腰带和4把铜质大锤。', '谢谢你，$N。这可以给我们提供很大的帮助。除了不断从石望要塞向这里发起攻击的黑石兽人之外，还有潜伏在北方丘陵地带的赤脊山豺狼人，我一直忙着为我们的军队修理盔甲及制造新武器。$B$B你带来的装备给了我片刻的安宁，让我利用时间教你点什么吧……', '我希望你从铁炉堡带来的是好消息，我这儿已经快要应付不过来了!', '', '去赤脊山找湖畔镇的弗纳·奥斯古。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1644, '圣洁之书', '愿圣光护佑那些孩子，他们大多因为几年前那次亡灵天灾的袭击而失去了家庭。$B$B我丈夫约翰为我收集给孩子们做衣服裤子的布料，不过我没时间做，因为我得成天忙着照顾他们的饮食起居。$B$B什么？你愿意帮忙？赞美圣光，也感谢你，好心的$N。$B$B如果你能给我找点亚麻布来的话,我就能给孩子做衣服了，那可真是帮了我的大忙。', '给暴风城的斯蒂芬妮·特纳收集10块亚麻布。', '谢谢你，$N，太感谢了!$B$B孩子们会很高兴的，你为我节省了很多时间。现在我可以把精力集中在满足他们的其它需要上了，但愿我的约翰能早日回来。$B$B再次感谢你，$N。我知道会有你这样的好心人来帮我的。愿圣光与你同在。', '但愿我丈夫约翰在铁炉堡能有更好的运气。他并不想把我和孩子们留下，自己一个人跑去那儿，不过他知道必须这么做，他真是太善良了。$B$B前些年的生活还不错，不过现在的日子越来越难过了。我们都能感觉到好像会有重大的变化发生，不过又有谁知道呢?', '', '去找暴风城的斯蒂芬妮·特纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1648, '圣洁之书', '我和我的妻子在暴风城管理着一家孤儿院，帮助在过去几年里因为亡灵天灾的袭击而失去双亲的孩子们。我差不多每个月都要来铁炉堡收集这里的居民捐赠的物资，而且我也会和不同的团体商谈，尽可能地寻求他们的帮助。$B$B这样的旅程往往让人苦恼，因为它很费时间而且收效甚微。$B$B如果能找到些亚麻布来让我妻子给那些孤儿做些衣服的话，我想我就可以寄些东西回家了。', '收集10块亚麻布，把它们交给铁炉堡的约翰·特纳。', '$N，您真是太好了，再次感谢您。$B$B您是一个高尚善良的$G绅士:女士;。像您这样的$r选择追随圣光让人感到很高兴。我希望能够报答您为我们所做的一切……什么?这不算什么?真的吗?我必须要说，$N，您真的是太高尚了。$B$B愿圣光护佑您一路平安。', '就算是这里和整个艾泽拉斯的商人都愿意帮忙，我们也无法得到足够的材料为孤儿院的所有孩子们制作衣裳。请帮我收集一些亚麻布，好让我的妻子力所能及地帮助孩子们。谢谢您，$N。$B$B如果走运的话，不久之后我就能回家见到我的妻子了。', '', '去找丹莫罗的约翰·特纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1654, '正义试炼', '如果你愿意接受奖赏的话，我会给你奖赏的。请不要误会，我的慷慨取决于你能给我多少帮助，不过这样的同盟关系对你我都有好处。$B$B我可以为你制作一把配得上你的成就的武器，一把象征着圣骑士的精神和圣光的武器，不过首先，你要给我找到制作这把武器所需的材料。我已经列出了所需的材料，现在得有一个勇敢能干的人去找到它们。你愿意去完成这个任务吗，$n？', '按照乔丹的武器材料单上的说明去寻找一些白石橡木、精炼矿石、乔丹的铁锤和一块科尔宝石，然后回到铁炉堡去见乔丹·斯迪威尔。', '太好了!你拿到这些东西了。$B$B有了这些我就可以铸造强大的武器了。其实我早有计画来做，不过一直都没有机会去收集这些材料。谢谢你，$N。$B$B再次握住我父亲的铁锤的感觉真好……还有这块科尔宝石，我可从来没想过自己能亲眼见到这个。', '这些材料很难找到，不过我可以向你保证，我为你制造的武器绝对值得你这么做。$B$B这将是我当前为止最出色的作品，是送给你当作回报的。', '', '去丹莫罗找铁炉堡大门的乔丹·斯迪威尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1655, '白洛尔的矿石', '啊！你吓了我一跳，$G先生:小姐;！你没看到我在思考吗？$B$B那是什么？乔丹的矿石…送去铁炉堡的……啊，这样啊，我知道你说的是什么了。那群莫格罗什食人魔抢走了我朋友的矿石，商队从这里转至湿地的路上遭到了埋伏。唯一从袭击中逃出的守卫也在前几天死掉了——医师没能及时赶到。$B$B你想找到那些矿石，就往东北方向去，在洛克湖的另一边。矿石一定就在那里的某个地方。', '把乔丹的矿石带给洛克莫丹的白洛尔·石手。', '是的是的，就是这些。哈哈!早知道你真的能去那儿和巨魔斗斗，我就该让你多让做点事情。不过，你来这儿不是帮我做事的，对吧?$B$B一桩归一桩，乔丹想要我把他的货拿回来，那他就一定能拿到。$B$B代我向他问好，路上多加小心，$C。', '运气怎么样?哈哈，那些巨魔打不过你，对不对?', '', '去找洛克莫丹的白洛尔·石手。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1656, '未完的任务', '拜托，$N，求求你了，帮我一个忙吧！我正在完成我的力量仪祭，但父亲又要求我将这些皮毛送到血蹄村的旅店。$B$B我实在分不开身去同时完成仪祭和父亲交付给我的任务。你……能不能替我跑一趟？$B$B在长途旅行之后，旅店可是个休息的好地方。我敢说你到了那里之后也会同意的。', '将一捆毛皮带给血蹄村的旅店老板考乌斯。', '啊，这正是我在等着送来的皮毛，谢谢你啦。$B$B比我预期的到货时间还要早一些。我会把它们编成毯子，给住在这里歇息的旅客使用。$B$B把这里当成自己的家吧，一切请随意。我的旅店从不关门，我们的同胞在这里总是受欢迎的。还有，千万别不注意休息，好好睡一晚会让你第二天的旅途大为不同。', '你好，年轻人，我能为你做点什么吗?$B$B从台地走到这里对某些人来说可实在是极大的负担，不过对另一些人则是开阔眼界的好机会。我想知道你是这两种人里的哪一种?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1657, '臭气熏天的南海镇', '我们这次万圣节的庆祝要换个方式……我们要给南海镇的敌人带去痛苦！$B$B拿着这些特殊的臭气弹。其中包含了任何人类——或者较弱的野兽——都无法忍受的味道。你需要把这些臭气弹丢在南海镇的中心，然后使它生效，准备和联盟好好干一仗吧！$B$B当你完成任务之后……完成这个象征我们自由的标志之后，回到我这里来！', '将三颗亡灵臭气弹放置在希尔斯布莱德丘陵的南海镇中心，完成任务之后回到提瑞斯法林地的黑暗召唤者雅恩卡那里。', '啊，做的好!希望联盟会被我们给的恶臭礼物给呛死，就像我们被迫遭天灾军团奴役而被枷锁窒息一样!$B$B你的万鬼节消息是真的，$N，为此我向你致敬。作为额外的奖励，我要分你一些万鬼节糖果。我想你一定会觉得它们是有趣的消遣!', '你把我们的“礼物”送给南海镇的居民了吗?$B$B<黑暗召唤者雅恩卡邪恶地笑了起来。>', '', '去提瑞斯法林地找洛丹伦废墟的黑暗召唤者雅恩卡。', '向南海镇投掷臭气弹', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1665, '巴特莱比的酒杯', '好吧，这是我的酒杯。等等！让我先把酒喝光……给你。', '把巴特莱比的酒杯交给伯加德。', '就是它了!他的确不希望失去这个酒杯，不过，你很有说服力。干得不错。$B$B现在，我们来继续你的课程吧……', '看来你和巴托比打了一架。真是不错!你拿到酒杯了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1667, '蛀牙杰克', '是伯加德派你来的吗？是的，我这里的确有一些剩馀的武器，不过首先有一项任务交给你……$B$B不久以前，一个被称作蛀牙杰克的迪菲亚混蛋捉弄了我。天很黑，他穿着一件暴风城卫兵的衣服，我还以为他是治安官杜汉呢。他说他要我那个旧的暴风城治安官徽章，我就把徽章给了他……然后他便大笑起来，在我反应过来之前就跑掉了！$B$B帮我取回我的勋章！蛀牙杰克应该是把徽章放在南边的迪菲亚盗贼营地里了。', '从蛀牙杰克的营地里取回治安官哈迦德的徽章，把它交给治安官哈迦德。', '太好了，你找到它了!我担心迪菲亚的人会用它来冒充暴风城的军官，还好这样的事情现在不会发生了，谢谢你。$B$B这是我当治安官时用过的武器，我把它们保养得很好―你随便挑一件吧。', '你找到我的勋章了吗?我可不希望蛀牙杰克用它去作恶。', '', '去艾尔文森林找石碑湖的治安官哈迦德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1678, '维吉雷克', '如果你想提高自己在战士中的地位，那么你就必须变得更加坚韧一些。我可以教你一些新的技能，不过在此之前，你要向我证明你能够对付真正的敌人。$B$B维吉雷克是这一地区最强大的巨魔，也是你即将挑战的对手。他住在霜鬃要塞南方山脚下的棚屋里。$B$B把维吉雷克的徽记交给我，让我看看你的勇气和力量。', '将维吉雷克的徽记交给铁炉堡的穆伦·雷矛。', '维吉雷克一定是个丑陋的家伙，对吧?干得很好，$N!你做了应该做的事，现在让我们开始你的课程吧……$B$B也许你不知道，严密的防守对于一个战士来说是与凌厉的进攻同样重要的。防守能够让一个战士抵御凶残的敌人，这种能力也是你的伙伴所需要的。', '你去过维吉雷克的棚屋了吗，$N?', '', '去找丹莫罗的穆伦·雷矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1679, '穆伦·雷矛', '你好，战士！你有很大的潜力，不过你还要学习更多的技巧才行，穆伦·雷矛是最合适向你传授这些技巧的矮人。$B$B你可以在铁炉堡军事区的军事大厅里找到穆伦。当你准备要成为一名真正的勇士的时候，就去和他谈谈吧。', '和穆伦·雷矛谈一谈。', '啊，$N。我听说丹莫洛的战士们到处赞颂你。希望你不要整天躺在功劳簿上睡大觉!', '可有什么收获吗？', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1681, '铁环营地', '我的导师，斯塔基·铁环，原本在丹莫罗东部的盔枕湖南边有一处独家小院。他在那里向别人传授铁匠的技能，他绝对是最棒的。$B$B不过，有一天，他的一个学生带给他一块奇特的矿石。铁环把它叫做暗影矿石，他很希望能用它做点什么，可是，之后不久……一伙黑铁矮人袭击了他的小院。他们杀死了所有的人！$B$B到铁环的小院去，$N，为我的导师复仇，然后把那块暗影矿石给我带回来。', '把暗影矿石交给铁炉堡的托姆斯·深炉。', '你找到它了!干得不错!$B$B我希望你在搜索的时候把那伙黑铁矮人全都给干掉了。恐怕铁环的小院不会是我们唯一可以找得到他们的地方。$B$B不过，还是谢谢你带回了矿石，$N。我很希望马上能够使用它，看看它有什么样的特性。', '你去过铁环的小院了吗?你找到阴影矿石了吗?', '', '去找丹莫罗的托姆斯·深炉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1683, '沃鲁斯·邪蹄', '在我向你传授知识之前，你必须显示出决心。$B$B有一个名叫沃鲁斯·邪蹄的萨特找到了我们的一口月亮井，就在班奈希尔兽穴的东南方。他正在井中戏耍，用他邪恶的身躯污染纯洁的井水。$B$B到月亮井那里去找到沃鲁斯，把他干掉。把他的角给我带回来，然后我就会向你传授更高级的战士技能。$B$B去月亮井的路不太好找，但是如果你细心一点的话，应该不会迷路的。', '将沃鲁斯的角交给达纳苏斯的艾兰娜瑞。', '干得不错，$N。很高兴得知你打败了沃鲁斯的消息，你让我们的月井恢复了纯净，像你这样年轻的战士们为保护我们心爱的泰达希尔不受堕落的影响而战斗，这让我很欣慰。$B$B现在开始训练吧……', '你拿到角了吗，$N?玷污月井的恶魔沃鲁斯死了吗?', '', '去达纳苏斯找战士区的艾兰娜瑞。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1686, '艾鲁拉的阴影', '你已经学会很多东西了，$N。现在我们将为你制作一件精良的武器，一件属于战士的武器。$B$B要完成这一使命，你必须去一趟黑海岸。$B$B很久以前，有一条船在奥伯丁灯塔附近触礁，许多装有月神矿石的箱子沉入了海底。$B$B首先，你必须打败守护那些矿石的亡魂——艾鲁拉的阴影。作为一船之长，她对自己施加了诅咒，变成了一个在海洋深处巡游的亡魂，时时刻刻保护着船上的货物。打败她，摘下她的徽章，然后收集丢失的月神矿石。', '将艾鲁拉的徽章和8块月神矿石交给达纳苏斯的艾兰娜瑞。', '你真是太勇敢了，$N。$B$B你让艾鲁拉的阴影得到了安息。我们会用这些矿石为你打造一件精巧的武器。', '你打败艾鲁拉的阴影了吗，$N?你找到丢失的月神矿石了吗?', '', '去达纳苏斯找战士区的艾兰娜瑞。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1687, '幽灵灯塔', '有时候，我们孤儿院的院长会在晚上给我们讲一些鬼故事。真是太恐怖了！其中有一个故事说在西部荒野的灯塔那里有一个游荡的幽灵。他们说那是一个海盗船长，他的船被别的海盗给抢了。这真是太刺激了！$B$B你能不能把我带到西部荒野的灯塔那里去？我想要看看那个幽灵船长是不是真的在那里！我保证会一直跟着你，而且绝对不会跑开或者惹些什么麻烦！', '带着你看护的孤儿去西部荒野海岸边的灯塔。', '哇，一个真正的鬼魂!这真是太棒了―我要马上把这个告诉孤儿院里的其它人。葛瑞森船长……他打扮得十足像个海贼!当我长大之后，我也要做个鬼魂船长!$B$B感谢你把我带到西部荒野来，$N。我知道在西部荒野这里还有很多恐怖的事情，也希望我没有让你感到麻烦，你真是太棒了!', '我们到了吗?', '参观西部荒野海岸边的灯塔。', '去找人类孤儿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1688, '苏伦娜·凯尔东', '我曾有一个名叫苏伦娜·凯尔东的学生。她过去和现在的你一样，一心渴求学习到强大的术士魔法，而且她也拥有着十分了得的天赋。更难能可贵的是，她很年轻，而且很漂亮。我最近又看见她了，那个背叛了我的女人！$b$b那时候她和迪菲亚兄弟会里的一个小贼埃尔兰·杜德摩尔私奔了。她走掉其实倒也没什么，但我曾送给她一条血石项圈，我必须把它拿回来。$b$b现在她的性命对我来说一点都不重要了。你应该可以在布莱克威尔南瓜田找到她，到那儿去把我的东西给夺回来！', '为暴风城的黑暗缚灵者加科因夺回苏伦娜的项圈。', '苏伦娜很有天赋，但仅靠这个就想掌握更多的术士魔法还远远不够。看着她的大好天赋被白白浪费掉确实很让人遗憾，但有时候这是必要的。$B$B我希望我在你身上倾注的心血会产生不同于此的结果。', '即使是睿智的长者有时也会被年轻貌美的女人迷惑，$N。你得牢牢记住这个忠告。', '', '去找暴风城的黑暗缚灵者加科因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1689, '誓缚', '你找回了我的颈环并击败了苏伦娜，这证明你有着至少与她势均力敌的力量。$b$b虽然这么说，但我还是认为你需要进一步的训练。你现在已经能够控制魔法的流动了，这很好，但如果你要想要成为一位优秀的术士，这还远远不够。$b$b我会教你如何控制虚空行者，不过在我教你之前，你得先在召唤法阵上召唤它出来并制服它，无论你用什么武器都好——剑或者魔法——随你自己乐意吧。在下面的召唤法阵上使用这个颈环里的魔法，然后击败从虚空中出现的恶魔。', '召唤并制服一个虚空行者，然后将血石颈环还给暴风城的黑暗缚灵者加科因。', '你做得比我想象中的要好，$N，不过也没怎么超出我的预期。现在，你可以学习如何操控这个只屈服于你的虚无行者了。你会发现在今后面临考验的时候，它将会坚定地站在你身前保护你。$B$B现在我已经没什么可以教你的了，但你的修行之路还远没有结束，$N。', '在你制服虚无行者之前，我没办法教你怎么控制它。', '', '去找暴风城的黑暗缚灵者加科因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1690, '废土的公正', '你！是你出马帮助加基森水业公司的时候了！$B$B那些废土游牧民几乎占据了塔纳利斯沙漠上所有的水井！如果得不到这些水井的控制权，那我们的水源供应很快就会出现问题。如果你想帮助我们的话，就去解决那些该死的游牧民吧！$B$B从这里往东走，去干掉10个废土窃贼和10个废土强盗，然后立即向我报告。你一定要为我们这些人……呃……地精们伸张正义啊，不管怎么样，快点行动吧！', '去加基森的东面杀掉10个废土窃贼和10个废土强盗，然后向总工程师比格维兹复命。', '你做事真是效率惊人啊!你帮我削弱了他们的势力，这样我们就可以开始考虑如何夺回属于我们的水井了。$B$B加基森水业公司感谢你的帮助，但是我们和那些愚蠢的游牧民之间的斗争还远没有结束。听好了―这是我交给你的下一个任务……', '那么快就回来了?我希望你已经按照我的要求，以哥布尔的方式为我们伸张了正义!', '', '去塔纳利斯找加基森的首席工程师沙克斯·比格维兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1691, '废土的公正', '现在我们需要你去对付那些更强大的废土游牧民。到现在为止你都表现得相当出色，但是如果我们想要夺回水井的话，那么就必须要干掉更多的游牧民！$B$B这次，我要你去杀死他们的游荡者和刺客，还有暗法师。你可以在这里的东南面找到这些家伙。$B$B说实话，他们都很棘手。但是请你一定要帮忙，我们要取回属于自己的东西！', '杀死10个废土暗法师、8个废土游荡者和6个废土刺客，然后向加基森的总工程师比格维兹报告。', '干得太棒了，$N……实在是太棒了!你成功地削弱了他们的势力，我们终于可以和他们进行一定程度上的对抗了!$B$B去和旁边的操作员鲁葛兰克谈谈吧，他正在悬赏那些游牧民身上的水袋!我相信你一定可以帮我们夺回那些水井的。', '怎么样，你杀死那些游牧民了吗?加基森水业公司需要你的成功来开展进一步的行动!不要让我们失望，现在就去……', '', '去塔纳利斯找加基森的首席工程师沙克斯·比格维兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1692, '铁匠玛希尔', '我把你收集到的月神矿石装进了一只箱子。把它交给铁匠玛希尔，他会帮你打造一件月神武器。$B$B玛希尔住在靠南的地方，就在这座建筑物的另一侧。', '把这箱月神矿石交给铁匠玛希尔。', '啊，是月神矿石。这是一种很有用的金属材料，因为女神艾露恩赐予它祝福。用它来铸造武器是一种荣耀。$B$B请等一下，我现在就开始工作……', '你好，年轻的战士。有什么我能为你效劳的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1700, '格瑞曼德·艾尔默', '帮你铸造铠甲的时候，我记下了一些心得体会。我要找个人帮我把这份笔记交给格瑞曼德·艾尔默，他在矮人区的武器店里。把笔记交给他的时候要显得低调一点，他对自己的技术有近乎狂妄的自信，根本不愿从我这里学点什么……', '把弗伦的笔记交给格瑞曼德·艾尔默。', '这是弗伦写的?真可笑?你知道吗，他的那点本事都是我教给他的!让他来指点我?这样的事情真是让人难以忍受!不可容忍!$B$B嗯……不过在他的笔记中的确有些有价值的东西，我来看看……', '你好，很高兴见到你。我能帮你什么忙吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1701, '弗伦的铠甲', '我已经给了你一面精致的盾牌，不过我们的合作决不会就此结束。我知道如何铸造异常坚固的铠甲，但是铸造起来并不容易，我需要一些稀有的材料，只要你愿意跑跑腿，我保证会为你打造一件。$B$B你觉得怎么样，$N？如果你愿意接受挑战的话，我会给你一份列表，上面记载着我需要的材料和到可以找到这些材料的地点。', '收集必需的材料，将它们交给暴风城的弗伦·长须。', '你找到了全部的材料?难以置信!我还以为那些奇美拉把你吞进肚子里了!$B$B好吧，我们开始打造铠甲吧……', '你的任务完成得怎么样了，$N?拿到材料了吗?', '', '去找艾尔文森林的弗伦·长须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1702, '铸盾师', '$N，当你完成挑战时，我就看出你是个厉害的家伙啦。当然，我说话算话，我会按照承诺给你奖励……$B$B不过，这件礼物在暴风城。$B$B去跟我的朋友弗伦·长须谈谈吧，他在暴风城的矮人区里。我敢说他是你见过的最棒的铸盾师，他欠我一份人情。$B$B给，把这桶热麦酒交给弗伦，让他为你制造一副盾牌。那品质绝对让你满意！', '将这桶热酒交给弗伦·长须。', '啊，犹鲁斯的酒!这些可是上好的饮料!那么你已经见过他了?$B$B我可以为你铸造一块新的盾牌，没错，$g先生:女士;!你不可能找到比它更好的了，真的!', '你好!今天真是个无聊的日子，你不觉得吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1703, '玛希尔', '在帮你铸造铠甲的同时，我记下了自己的心得体会。现在我得找个人帮我把笔记交给铁匠玛希尔，他住在遥远的达纳苏斯，但我相信他一定非常希望看看我记录的这些东西。', '把弗伦的笔记交给玛希尔。', '这些笔记真有趣，真的非常有趣。看来我的这位矮人同事有了一个重大的发现!$B$B谢谢你，$N。能把他的新技术用于我的制造工艺，这对于我来说是一种荣耀。', '你好，勇敢的战士。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1704, '科罗莫特·钢尺', '在帮你铸造铠甲的时候，我顺手记下了我学到的技术。现在我得找个人帮我把笔记交给科罗莫特·钢尺。他是铁炉堡的侏儒铁匠，当他知道我学到的技术以后……我敢打赌，他一定会兴奋地拔掉胡子的！', '把弗伦的笔记交给科罗莫特·钢尺。', '哦，天哪!这些笔记真是让人吃惊!还有……真是难以置信，太惊人了，我的腿都开始发抖了!$B$B弗伦在锻造技术领域有了一次突破!真正的突破!我已经等不及要试一下他的新技术了!', '你好啊，我也不知道该说“早安”还是“晚安”。因为在这里我分不清是白天还是夜晚。你找我有什么事?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1705, '燃烧之血', '我很不愿意相信弗伦可能发现了什么新奇的东西。不过，为了确认这一点，我要把他的技术应用到这副新的铠甲上。如果你能帮我找来这些原料，$N，你就能拥有这样的一件铠甲。$B$B要制造这件铠甲的话，我需要一些燃烧之血和一块燃烧之石。$B$B我知道唯一能找到它们的地方是暮色森林，那些在罗兰德末日矿洞里出没的夜行狼人拥有燃烧之血，而他们的首领加特斯比尔则拥有燃烧之石。$B$B愿好运永远与你同在，$N.', '把20瓶燃烧之血和1块燃烧之石交给暴风城的格瑞曼德·艾尔默。', '干得漂亮!如果你不介意的话，我要开始工作了……', '$N，你拿到燃烧之血和燃烧之石了吗?我需要用它们来完成这件铠甲。', '', '去找艾尔文森林的格瑞曼德·艾尔默。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1707, '收集水袋', '你好啊，$N！我叫鲁格伦克，如果你想要找些事情干，我们这里现在就有一件重要的工作给你！$B$B没有什么能比帮我带回一些废土水袋来更能令我这个老家伙开心的了。那可都是我们的水——就是那些混蛋把它们偷走了！你每给我带回五只废土水袋来，加基森水业公司就会奖励给你一个可以用来碰运气的小包裹。更重要的是，我们会永远记住你所提供的帮助！', '收集5只废土水袋，把它们交给加基森的鲁格伦克。', '干得好!收集到越多水袋，我们就可以越早脱离这场灾难!继续干，你每给我带回五个水袋，我就会给你相应的奖励。', '拿到我要的五个废土水袋了吗?如果你能帮我们找到五个废土水袋的话，加基森水业公司的103-XB型护理袋就是你的了!', '', '去塔纳利斯找加基森的操作员鲁格伦克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1708, '铁珊瑚', '我希望在我自己的铠甲上应用弗伦·长须的新技术。因为你帮了弗伦的忙，而他又帮了我的忙，所以当我做好铠甲以后，你可以第一个试用它！$B$B要打造铠甲的话，我就得弄到一种特别的珊瑚，灼热珊瑚。它只生长在一个地方——湿地的米奈希尔港南边的海岸地带。$B$B只要你给我带来我足够多的灼热珊瑚，我就可以马上开始铸造铠甲啦。快点，$N，我恨不得现在就开始工作！', '收集20块灼热珊瑚，把它们交给铁炉堡的科罗莫特·钢尺。', '这正是我要的东西!干得不错!我要把它煅烧并锤打成形，然后将弗伦的技术融入我的锻造技术里，让我们看看会发生什么!$B$B哦，天哪，天哪!我就知道这样打造出来的铠甲会非常非常非常坚固的!', '你好你好，$N!你搞到灼热珊瑚了吗?我恨不得马上就开始工作!', '', '去找丹莫罗的科罗莫特·钢尺。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1710, '晒焦的蛋壳', '我很想测试一下弗伦·长须的最新发现，希望能将它用于我正在研究的新式铠甲上，我认为弗伦的技术一定能产生最好的结果。$B$B你愿意帮助我吗？如果你愿意帮我收集制造铠甲所需的原料，我就会帮你也做一件。$B$B我需要晒焦的巨翼双足飞龙蛋壳，这种飞龙大都栖息在千针石\r\n林的风巢中。在它们的巢下可以找到我要的蛋壳，当你收集了足够数量的蛋壳之后就赶快回来找我。', '把20个晒焦的蛋壳交给达纳苏斯的玛希尔。', '啊，谢谢你。这些应该足够了!$B$B我要马上开始着手进行制作锁甲的最后一道工序……', '你找到蛋壳了吗，$N?我可以把它们碾碎并制成强力的护甲漆，然后就可以用它来加固我新制作的锁甲了。', '', '去达纳苏斯找战士区的玛希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1712, '塞克隆尼亚', '我几十年来都在关注着这个地方。我关注着，希望有一天能看到强大的塞克隆尼亚被人击败。但迄今为止，我还没有找到一个能打败风之王的勇士。$B$B也许你就是那个勇士。$B$B证明给我看吧，给我找来召唤塞克隆尼亚所需的东西，这样你就能证明自己是一个伟大的勇士。也许你能打败他并夺得他的旋风之心。$B$B这样的话，我将把这颗心的力量注入一把武器里，供你在今后的冒险旅程中使用。$B$B这张羊皮纸上写着我需要的东西。', '把巴斯拉的羊皮纸上列出的东西交给奥特兰克的捕风者巴斯拉。', '你找到了我需要的东西，也证明了你的实力和智慧，但我们的下一个任务更加危险。$B$B希望你的力量不会就此终结。', '你找到那些东西了吗，$N?找到这些东西，这样你才能证明自己有力量面对塞克隆尼亚。', '', '去奥特兰克山脉找冰风岗的捕风者巴斯拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1713, '召唤', '我已经准备好仪式要召唤塞克隆尼亚了。当他被召唤出来时，你必须打败他，然后得到他的旋风之心。我将用它来把塞克隆尼亚的力量注入到一件武器中。$B$B$N，你准备好面对风之王了吗？', '将旋风之心带给捕风者巴斯拉。', '你成功了!你打败了塞克隆尼亚，得到了旋风之心!', '$N，我必须得到旋风之心!', '', '去奥特兰克山脉找冰风岗的捕风者巴斯拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1714, '流放精华', '', '', '符咒缓缓渗入了这口大锅的深处……$B$B一个很大的泡沫漂到液体的表面上来，随即破裂了……$B$B……一块翻滚着的熔岩浮了上来。', '锅里翻腾着泡沫，弥漫的蒸汽在召唤着……', '', '去找奥特兰克山脉巴斯拉的大锅炉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1738, '同心树', '为了你的到来，我拨开时间的迷雾，搜寻了整个世界，终于找到了你在寻找的东西。$b$b在上古战争的一场战斗中，有一对恋人一起倒下了。在他们死去的地方，一棵同心树茁壮地生长了起来，那是他们至死不渝的爱情的象征。$b$b那棵树应该足以用来引诱魅魔，你可以在灰谷森林西北的奥迪拉兰废墟里找到它。', '从灰谷取回同心树，把它交给暴风城法师区里的黑暗缚灵者加科因。', '嗯，这个就可以了，你稍等一会儿……$B$B塔卡尔确实是一个足智多谋的家伙，难道不是吗?当然如果我能说服他回到文明社会就再好不过了。', '你找到同心树了吗，$N?', '', '去找暴风城的黑暗缚灵者加科因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1739, '誓缚', '你可以使用同心树之核在下面墓穴里的召唤法阵中施展一个法术，以此打开一个供魅魔通行的传送门。$b$b小心点，$n，即使是意志最坚定的人，也会被魅魔轻易控制。$b$b一旦你成功地击败了她并把她投回无尽虚空之后，就回来找我，我会告诉你如何召唤并控制她。', '召唤并制服一个魅魔，然后将同心树之核还给已宰的羔羊旅店的黑暗缚灵者加科因。', '好极了，好极了，$N。你确实是个天生的术士，你的表现没有让我们失望。$B$B我会毫无保留地将控制魅魔的方法教给你。仔细看好了!', '有的时候我会想，苏伦娜是不是一个伪装之后跑来扭曲和破坏我的意志的魅魔……哈!我想我的确给她带来了太多的麻烦。', '', '去找暴风城的黑暗缚灵者加科因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1740, '索兰鲁克宝珠', '当燃烧军团中的某个恶魔失宠以后，他们的灵魂就会被囚禁在宝珠中，供他们的法师或者术士差遣。$b$b很多宝珠被赐给了艾泽拉斯的恶魔之仆。即使是一颗破碎的宝珠，仍然可以蕴含着强大的恶魔力量。$b$b索兰鲁克宝珠碎成了两块，其中的一块又被砸成碎片，分发给黑暗深渊中的暮光之锤侍僧使用。另一块比较大的碎片在影牙城堡的一个巫师的手中。把它们找来给我，我可以用这些碎片重塑宝珠。', '找到3块索兰鲁克宝珠的碎片和1块索兰鲁克宝珠的大碎片，把它们交给贫瘠之地的杜安·卡汉。', '嗯……宝珠的破损不算太严重，几乎每一块碎片都在这儿。把它们粘合在一起，就可以重塑一个完整的索兰鲁克宝珠。$B$B我将毕生的精力投入对燃烧军团的宝珠的研究中。谢谢你帮我收集这些碎片让我研究，我会把拼凑好完整的一片都还给你，照你的意思重塑。', '我用了很多年的时间来收集札盖恩宝珠的碎片，对我而言，它很好使，我想对你也一样。', '', '去贫瘠之地找南贫瘠之地的杜安·卡汉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1784, '圣洁之书', '在我陷入苦战以前，我和穆里顿在那座小房子附近几乎干掉了一个黑铁间谍。我们亲眼看见他们的头儿给他一条手令，于是我们就想把他干掉，然后抢到那条手令。$B$B铁炉堡议会里的一些家伙还不相信丹莫罗有黑铁矮人的存在。只要能得到那条手令，我们不仅能证实他们的确在这个地区活动，还能知道他们到底想要做什么。$B$B去拿到那份手令，然后把它交给穆里顿，$N。', '从盔枕湖附近的黑铁矮人那里取回一份黑铁手稿，把它交给铁炉堡的穆里顿·热炉。', '哈哈!你成功了!你救了纳姆，你找到了黑铁矮人在丹莫洛活动的证据，我的妻子可以把它交给议会。你是圣光的使者……当然我的妻子也是。$B$B谢谢你，$N。', '你回来了!我很高兴你能回来，$N。我的伤已经好了，只要我能够说服我的妻子不要再多担心我，就可以准备回到盔枕湖去了。', '', '去找丹莫罗的穆里顿·热炉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1787, '圣洁之书', '我们以后再来谈生命符记的事情吧，现在最重要的是把那份迪菲亚盗贼阅读过的文件拿回来。如果能得手的话，我们就能证明迪菲亚盗贼混入艾尔文森林了，甚至还有可能了解到他们的计划是什么。$B$B你觉得你有能力把这些文件从这座小岛上的迪菲亚盗贼手里拿过来吗？$B$B如果你拿到文件的话，就把它交给贾森，顺便告诉他我现在没事了。', '从石碑湖小岛上的迪菲亚巫师手中拿到迪菲亚手稿，把它交给暴风城的贾森·坦诺姆。', '干得好!你救了亨兹的命。圣光与你同在，$N!', '亨兹还好吗，$N?你成功了吗?$B$B以你的战斗技巧，再加上光明的力量，我想英雄岗哨不会再受到迪菲亚盗贼的威胁了，不过那是国王和他的顾问应该关心的事情。', '', '去找暴风城的贾森·坦诺姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1795, '誓缚', '如果你已经做好了充足的准备，那么我们就开始吧。首先让我来解释一下整个过程。$b$b第一步是创造出基本的召唤法阵，然后，我的助手将使用导能魔棒来将其强化成为更加强大的法阵。$b$b当以上这些工作都完成之后，由你来诵读阴谋之书上的咒语，召唤地狱猎犬。$n，你要当心。地狱猎犬可是非常强大的生物，我希望你能保护好自己。', '召唤地狱猎犬并打败它，然后把阴谋之书交给棘齿城的斯坦哈德·法尔杉。', '$N，我必须说……你真的给我留下了很深刻的印象。我当年面对恶魔猎犬的时候，险些被它撕成碎片，至今想起来还有些心有馀悸。我觉得你有潜力成为这个时代最伟大的术士之一。', '每个术士都应该想办法控制一只恶魔猎犬。虽然这些家伙很难驯服，但是它们的强大力量绝对值得让你为之努力。', '', '去找贫瘠之地的斯坦哈德·法尔杉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1796, '魔化金线血袍', '我要帮你制作的第一件装备就是长袍，你要负责为我收集若干材料，然后我会把它们组合到一起。这样你就将拥有有首件能使你变得更加强大的装备。$B$B首先，你必须给我拿来一件奥法之袍。你可以去找个裁缝帮忙制作，也可以从其它冒险者手中购买——当然如果你能自己制作的话就更好了。但是无论如何，你要先把奥法之袍交给我，然后我们才能开始。', '将奥法之袍交给贫瘠之地的梅纳拉·沃伦德。', '干得不错，$N。$B$B所有的魔法装备都要在一件高品质的装备的基础上才能制造出来。你在这件装备上耗费的精力越多，它的魔法力量也就越强。稀有而昂贵的材料能更好地维系魔法的能量，当你得到我制作的袍子时，就会知道它有多么物超所值了。', '你搜寻长袍的进展如何，$N?你是准备亲自制作长袍吗?如果你自己动手的话，就会有很大的成就感。不过如果你准备走捷径找人为你制作的话，我也可以理解你想要迅速强大起来的―怎么说呢……雄心壮志。', '', '去找贫瘠之地的梅纳拉·沃伦德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1799, '宝珠碎片', '很好，那么我们开始吧。$B$B首先，你必须到里面去跟我的助手们谈谈，然后决定自己要走哪条路——他们会给你更详细的解释。$B$B然后，你必须到凄凉之地的玛诺洛克集会所去，从那里的某个术士身上找到一颗地狱火珠。你要净化这颗宝珠，隐居在尘泥沼泽南部的一个名叫塔贝萨的法师会帮你完成净化。她肯定会帮助你，因为我们曾有共同的过去。$B$B我再强调一次，这些任务没完成之前，你就别回来见我。', '在棘齿城外的塔里与梅纳拉的侍僧们谈话，选择自己修行的方式。$B$B然后给尘泥沼泽的塔贝萨带去一颗地狱火珠。', '嗯，梅纳拉派你来的?那么……看来我真的把你当成客人好好招待了。不过你似乎有什么急事要办―也许你是来寻找失去的力量?也许我搞错了，也许堕落离你并不是那么遥远……', '一看就知道你不是个法师，我不知道自己能不能相信你。我可以嗅到你身上的魔法的味道，但是却没有什么堕落的气息混杂在其中。$B$B没错，一个$C……一个来寻求我帮助的$C。$B$B好吧，我可以为你做点什么呢，$N?', '', '去尘泥沼泽找塔贝萨的农场的塔贝萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1800, '洛丹伦的王座', '在我们很听话的时候，孤儿院院长就会给我们讲述许多伟大的故事，其中的一个就是关于洛丹伦的陷落，以及邪恶的阿尔萨斯是如何杀死自己的父亲来夺取政权的。$B$B他这样做真是太无耻了，$N！等我成长为强大的部落战士之后，我将为荣誉而战——而不是为了邪恶的权力！$B$B你愿不愿意带我去洛丹伦的王座看看呢？王座就在你进入幽暗城之前的那个大厅里。', '带着你看护的孤儿去幽暗城电梯外的王座大厅。', '王座厅真的好雄伟啊，$N!虽然这里是空的，但是我感觉到似乎有很邪恶的事情曾在这里发生过。我感觉到了疯狂……但是我也感到很难过。我知道为什么院长要告诉我们这个故事了。我永远也不会像阿尔萨斯那样背叛我的同胞!$B$B感谢你带我到王座厅来，$N。我学到了很多东西。', '我们到了吗?', '参观幽暗城电梯外的王座大厅。', '去找兽人孤儿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1802, '阴谋之书', '它是丢了，不过我知道一些可以帮你找到它的线索。$b$b这本书的复制品只有一本，而且它也已经被损坏了，很大一部分的书页全都被撕了下来，现在听说它们落入了千针石林的半人马手里。$b$b其馀的部分在南海镇的西岸丢失了，原本这些书页是要用船送往米奈希尔港的，不过却从来也没能送到。$b$b你看，我告诉了你这么多消息，好歹你也得在找回东西以后拿来给我看看吧？', '为铁炉堡的克罗姆·粗臂找回发霉的书籍和破损的手稿。', '太棒了!现在我终于有机会成为少数几个阅读过这本书的人之一了。$B$B我简直等不及要快点读读这本书了!今天真是个好日子，$N!你走之前再让我看它一眼吧，我敢说斯坦哈德肯定愿意给我抄写一本!', '事情进行得怎么样了，$N?', '', '去找丹莫罗的克罗姆·粗臂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1803, '阴谋之书', '啊！你果然是个品位与我相当的术士呀。事实上，能得到阴谋之书一直是我的一大心愿。你知道那本书一度曾被保存在洛丹伦城里吗？然而，那本书如今已经被摧毁了，大部分的书页都不见了。到底是哪个白痴干出这样可憎的事？$b$b据说，失落的那一半当前在千针石林中的一群半人马手里。$b$b剩下的另一半本来是要被转移到铁炉堡去的，不过在押运过程中丢失在了南海镇西部的海滩上。', '给幽暗城的约拉·安尼森带回发霉的书籍和破损的手稿。', '好，很好，非常好!看看我们找到了些什么?$B$B这实在是太令人吃惊了，$N。我几乎已经不奢望还能看见它了，没想到它现在就在我的手里，全本的阴谋之书!$B$B来，在你离开之前，让我先翻上几页吧。', '也许你所追寻的东西只是一团空气，$N，但真相往往就隐藏在最夸张的谣言之中。', '', '去找提瑞斯法林地的约拉·安尼森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1804, '阴谋之书', '唉……我真是恨不得一辈子都抱着这本书。不过既然这是你找到的，而且你还要用它做更重要的事，我还是把它还给你吧……不过，请你一定要告诉斯坦哈德帮我抄写一本。$b$b对了，你去找书的时候，他托人带了个消息过来，让我告诉你说他的助手要协助进行召唤，不过你必须帮他找到3根导能魔棒。$b$b斯坦哈德可能不知道要到哪里去找导能魔棒，不过我碰巧知道！龙喉氏族的兽人法师们手上应该还有一些这种魔棒。', '将翻修过的书籍和3根导能魔棒交给棘齿城的斯坦哈德·法尔杉。', '干得好!阴谋之书和三根完整的―呃，只有轻微损伤的导能魔棒。$B$B真有趣，我记得已经很久没有一个像你这样年轻的术士可以召唤恶魔猎犬了。', '$N，还有什么事吗?我还能为你做些什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1805, '阴谋之书', '这书上写的东西是我这几年中看过的文章里最有趣的。这边的书很少，选择也很少——大多数的书都是地理方面的——而且，我都把它们翻来复去地读了好些遍了。我真希望斯坦哈德能抽空给我也送一本这样的书来。$b$b去和他谈谈吧，他在你离开的时候托人给我带来了口信，说是要交给你一个任务，要求你找回三根召唤魔棒。$b$b当然，为了答谢你允许我继续看这本书，我告诉你一个小秘密：你可以在湿地的兽人龙喉氏族那里找到你要的东西。', '将翻修过的书籍和3根导能魔棒交给棘齿城的斯坦哈德·法尔杉。', '干得好!阴谋之书和三根完整的―呃，只有轻微损伤的导能魔棒。$B$B真有趣，我记得已经很久没有一个像你这样年轻的术士可以召唤恶魔猎犬了。', '$N，还有什么事吗?我还能为你做些什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1819, '切割者奥拉格', '当亡灵天灾席卷提瑞斯法林地的时候，我们曾经抓住他们中的一员进行研究。他具有自己的意志，并自称为切割者奥拉格。但是，虽然他的意志是自由的，但他仍然只是一个被巫妖王掌控和奴役着的傀儡。$B$B我们希望能够让他脱离巫妖王的控制，但是失败了。现在，我看是时候让他彻底地“解脱”了。$B$B让他解脱，杀了他。$B$B激活北部陵墓那里的颅骨石机关，解除奥拉格身上的魔法封印。$B$B然后……做好准备，$N。', '杀死切割者奥拉格，然后和亡灵卫兵迪林格尔谈一谈。', '做得好，$N。奥拉格对于天灾军团来说很重要。你已经向黑暗女王证明了你具备一个战士应有的技巧和决心，因此你理应得到更多的教导。', '你的任务还没有完成，$N。作为一个战士不应该表现出恐惧……', '', '去提瑞斯法林地找布瑞尔的亡灵卫兵迪林格尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1821, '阿加曼德家传武器', '在我活着的时候，阿加曼德系列是我的主人，但他们也是让我死去的罪魁祸首！现在他们得到了应有的报复，阿加曼德系列已经成为了巫妖王手下的行尸走肉。$B$B现在我要剥夺他们最后的荣耀。到他们系列的墓地里去，帮我抢来他们的传家之宝：一把剑，一柄斧，一柄匕首，还有一把钉锤。将这些东西全都给我拿来！$B$B阿加曼德系列墓穴就在阿加曼德磨坊的最北端，那里有许多亡灵天灾的部队和死去的阿加曼德族人守卫着。', '把阿加曼德家传长剑、阿加曼德家传战斧、阿加曼德家传钉锤和阿加曼德家传匕首交给库勒曼·法席恩。', '啊!你找到它们了!现在，阿加曼德系列最后的荣耀和记忆已经从这片被诅咒的土地上彻底消失了!现在，这个系列已经永远被人遗忘了!', '你找到阿加曼德系列的祖传武器了吗?', '', '去提瑞斯法林地找布瑞尔的库勒曼·法席恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1824, '巨人旷野的试炼', '要通过试炼，你必须一直向南到巨人旷野去，在那里有一大群叫做异种蝎的昆虫生物。我以前从未在贫瘠之地看到过这种生物，也不知道它们的到来究竟预兆着什么。$B$B把它们的触角交给我，$N，要刚刚割下来、还再抽搐的那种。不要浪费时间，因为一旦你把触角割下来，它们很快就会彻底失去活力。在规定的时间内把触角带给我，这样你就通过了考验。', '收集5根颤抖的触角，把它们带给贫瘠之地陶拉祖营地的鲁迦。', '干得好，$N!你通过了在巨人旷野的考验，在战士的道路上又前进了一步。', '你得到触角了吗?如果是的话，那就快把那些触角交给我，它们很快就会失去活力……', '', '去贫瘠之地找陶拉祖营地的鲁迦·狂暴图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1838, '野蛮护甲', '我听说了关于你的英勇事迹，所以希望能为你制作一套护甲，这能够帮助你去为部落作出更多更伟大的贡献。$B$B但是制作这样一件护甲需要你的帮助，$N，如果你能帮助我，那你也就帮助了部落里所有的铁匠。$B$B拿着这个卷轴，这是我经过无数不眠之夜，强睁着我半瞎的眼睛写下的，上面记载着制作护甲所需要的材料。把卷轴上所列出的材料帮我找来，我会为你制作一套护甲。', '为索恩格瑞姆收集15根烟雾铁锭、10份蓝铜粉、10块铁锭和1瓶燃素。', '你为我收集了所有需要的材料。现在，该我开工了……', '$N，你找到我列在卷轴上的材料了吗?', '', '去贫瘠之地找荆棘岭的索恩格瑞姆·火眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1842, '萨特之蹄', '我可以为你铸造一副具有很强魔法力量的野蛮手套。但是首先，你必须先替我去收集这样的魔法力量。$B$B为了获取这片森林的力量，许多萨特聚集在灰谷的东北面，它们在那里贪婪地吸取和破坏着森林的力量。你可以从它们肿胀的蹄子上判断出到底是哪些萨特在吸取灰谷的魔力。$B$B这些蹄子都有不小的魔法力量，把它们给我带来，这样我就可以给你铸造野蛮手套了。', '收集7只完整的萨特之蹄，把它们交给杜隆塔尔森金村的尤拉莱克。', '啊，你得到它们了!现在，就像它们当初吸取灰谷的力量一样，我将吸取这些蹄子中的力量，然后把它注入我要铸造的野蛮手套中……', '你得到它们的蹄子了吗，$N?那些蹄子里面蕴含着强大的力量。', '', '去杜隆塔尔找森金村的尤拉莱克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1844, '奇美拉之角', '我会帮你铸造头盔，但是你必须向我证明你值得我这么做。$B$B石爪山的西南面是一个名叫焦炭谷的山谷，那里曾经是一片郁郁葱葱的森林，但是现在已经被完全被污染，那里剩下的生物也都被痛苦和绝望逼疯了。$B$B现在我就要派你去那里，$N。$B$B你必须去焦炭谷找到雌奇美拉，杀死她，让她从苦痛中得到解脱，把她那光滑的奇美拉角带给我作为你完成任务的证据，然后我就会为你铸造头盔。', '把光滑的奇美拉角交给雷霆崖的奥姆·石蹄。', '你完成了任务，$N。你向我证明了你的价值和决心。这个头盔是你的了……', '你得到角了吗?她最终得到解脱了吗?', '', '去找雷霆崖的奥姆·石蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1846, '龙喉胫骨', '要铸造野蛮腿甲，我就需要一些结实的胫骨。湿地里的龙喉兽人就有非常合适的胫骨，我就需要那样的。$B$B但是你一定要确保胫骨是绝对牢固的，在你收集它们的时候记得要试一下它们是不是足够牢固：如果你能徒手把它们弄碎，那么它们肯定不符合我的要求。', '给幽暗城的维罗拉·奈特雷带去8根结实的龙喉胫骨。', '干得好!这些看起来很结实，肯定可以做一件很棒的野蛮腿甲。那些兽人不介意你把他们的胫骨拿走吧，$N?有没有很多抱怨?$B$B开玩笑啦，而且你没有笑。$B$B看来我这些天来都不太擅长搞笑……', '我正等着你给我带来那些胫骨，$N。我要用它们来制作野蛮腿甲的框架，那些东西应该是最好的材料。', '', '去提瑞斯法林地找 幽暗城的维罗拉·奈特雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1858, '碎手氏族', '你得去想办法把塔赞的包给弄开，这样咱们才能把里面的东西拿出来。这锁的结构还真挺复杂的，所以你想要弄开它的话就只能靠钥匙了。$b$b如果你没有在塔赞的尸体上找到钥匙，那他就一定把钥匙放到某个安全的地方去了……啊，对了！他有一个助手叫加摩尔，是个彻头彻尾的大酒鬼，你八成能在酒馆里找到这家伙。我建议你“安静地”把钥匙从他手里搞来。', '偷来塔赞的钥匙，用它打开他的背包，然后将里面的物品交给奥格瑞玛暗影裂口的瑟祖克。', '嗯，现在可好玩了。你通过这件事情充分证明了自己的能力，$N。我对你的印象非常深刻，现在把你自己当成是破碎之手氏族的一员吧。还有，拿着这个，我觉得这东西以后绝对能帮上你的大忙。', '这世上没什么比看得到吃不到的东西更烦人的了。', '', '去找奥格瑞玛的瑟祖克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1861, '明镜湖', '大规模的魔法战争已经使得原本稳定的魔法流开始出现异常的波动。我们正在努力调查这种波动究竟会造成怎样的影响，而有些人已经做好了最糟糕的打算！$B$B但是现在还不能轻易下结论，我们们要派你去收集更多的信息。$B$B拿着这个水袋，到艾尔文森林明镜湖瀑布的底部收集那里的水样，然后把水样给我带回来，这样我就可以用它来进行魔法污染情况的研究了。', '把一份明镜湖水的样本交给暴风城的詹妮亚·坎农。', '谢谢你，$N。我会对这份水样进行魔法特性实验的。希望我不会从中检测出什么有害的东西，否则的话，那些饮用明镜湖水的人和野兽都会受到影响。$B$B过来，$N。从宝珠和法杖中选择一样东西吧，希望它对你有用。', '你拿到样品了吗，$N?暴风城和艾尔文森林的魔法流被改变了，我必须知道这种改变是否已经影响到了水的本质。', '', '去找暴风城的詹妮亚·坎农。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1878, '收集水袋', '', '', '干得好!收集到越多水袋，我们就可以越早脱离这场灾难!继续干，你每给我带回五个水袋，我就会给你相应的奖励。', '又回来了，$N?如果你又找到5个废土水袋，那我就再给你一个医疗包裹!', '', '去找塔纳利斯的操作员鲁格伦克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1880, '法师文档存储器', '我们法师能做的事情可不仅仅是弹动一下手指变出美丽的火花那么简单！我们控制着魔法，控制着构建这个世界的源泉！当然，这需要极大的决心和极强的能力，还有知识……足够多的知识！$B$B我发明的一台设备——法师文档存储器——里面存储着无数的知识。不过问题是，我把它弄丢了！当我们逃离诺莫瑞根的时候，我把它留在城外一座小屋的箱子里，现在那地方麻疯侏儒横行！$B$B$N，请帮我取回我的法师文档存储器！', '帮彬克找回她的法师文档存储器。', '啊，这真是辉煌的一天!当我发明法师文档记忆体的时候，可从来没有意识到我竟会如此依赖它。现在我又可以重新开始我的研究了!$B$B谢谢你，$N!这里是我以前用过的第一批装备。它们有些旧了，不过还是非常好使的。随便挑一样吧!', '你找到法师文档记忆体了吗?我必须在它的能量耗尽之前找到它!', '', '去找丹莫罗的彬克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1882, '巴尼尔农场', '东边的瘟疫之地处于混乱的状态。巫妖王控制下的天灾军团将邪恶的魔法灌入土地之中，腐化并杀死那里的一切生灵。虽然瘟疫具有强大的破坏力量，但是我们——被遗忘者的法师——相信它必定可以被清除掉。$B$B首先，我们必须判断出它在提瑞斯法到底散播到了怎样的程度。到提瑞斯法东部的巴尼尔农场去，在那里的花园中收集一些金鱼草，然后再回来。', '将巴尼尔金鱼草交给幽暗城法师区的安娜斯塔西娅·哈特威尔。', '啊，不错的样本。我会把它送给我们的药剂师去进行研究的。$B$B你干得很好，$N。对于你所做的贡献，我给你两种奖励让你挑选:一枚宝珠或者一根法杖。无论选择哪一个，你都会发现它对你很有用。', '你拿到金鱼草了吗?这种花非常能适应魔法能量，研究瘟疫之地附近的金鱼草就能够让我们了解瘟疫是否已进入了提瑞斯法林地。', '', '去找提瑞斯法林地的安娜斯塔西娅·哈特威尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1884, '魂能骨堆', '回音群岛的术士扎拉赞恩扰乱了杜隆塔尔的魔法流。他那些邪恶的魂能骨堆就是造成这一切的罪魁祸首，他把那些骨堆放在回音群岛的主岛上。$B$B骨堆破坏了我们的生活，还让在黑暗角落里隐藏着的术士和恶魔获得源源不断的力量。$B$B你必须在魔法流被彻底改变之前摧毁那些魂能骨堆，$N。', '摧毁4个魂能骨堆，然后向森金村的安苏瓦汇报。', '我感觉札拉赞恩的魂能骨堆都已经被摧毁了。如果我们运气不错的话，杜隆塔尔的魔法流会慢慢恢复正常的。$B$B你为你的同胞做了一件很了不起的事，$N。你也向我们部落的法师们证明了你的价值。', '你必须快点，$N。摧毁那些魂能骨堆!', '', '去杜隆塔尔找森金村的安苏瓦。', '摧毁魂能骨堆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1886, '亡灵哨兵', '想加入瓦里玛萨斯大人的精英卫队——亡灵哨兵的话，你首先必须证明自己的价值。$b$b坦城地说吧，$n，你很可能在这种证明自己价值的任务中丧命，所以我劝你最好三思而行。$b$b现在，我有一个任务要你去完成。有一位来往于银松森林与幽暗城之间的信使，他叫阿斯托·哈德恩，由于特殊的公务需要，我必须得到他身上的一些私人物品。至于采用怎样的策略去得到这些物品，那是你的事情，不要问我。$b$b如果你的好奇心能小一点，不那么关心这些物品的用途的话，你会过得更自在一些。完成这个任务之后，我会再和你谈的。', '得到阿斯托的介绍信，并将其交给盗贼区的米奈特·卡加德。', '干得不赖，$N。考试的第一步你算是及格了。希望安德隆没有发现你的行动，这样一来，我们就可以把你打扮成那个他正“热切”期待着的信差先生了。', 'NULL', '', '去提瑞斯法林地找幽暗城的米奈特·卡加德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1898, '亡灵哨兵', '这封介绍信足以使安德隆认为你就是他正在等的那位信使。我之前已经见过安德隆了，估计以他那点脑子是根本不会怀疑你的。$b$b瓦里玛萨斯大人怀疑安德隆正在为某些其它的组织提供援助。他想知道那是个什么组织，而且你要收集到充分的证据。$b$b我要求你在与安德隆的谈话中把这些信息都给套出来，他的店就在炼金房旁边。', '与幽暗城的安德隆·甘特交谈。', '啊，对对对，我正等着你呢。不知道那位咱们俩共同的老朋友对我截止到当前提供给他的资讯还满意吗?$B$B啊，真是的，突然想起，问你也没用，他们根本没必要把这么重要的事情告诉你。有什么必要这么信任一位信差呢，是吧?', '你好。我能帮上你什么忙吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1899, '亡灵哨兵', '你在我背后的书架上就可以找到记有你的主子最需要的信息的账本。把它交给他们，记得代我问他们好。哦，还有，告诉他们，如果他们觉得与我合作确实不错，并且还打算按日程继续合作下去的话，他们最好还是派你来。', '将阿斯托的账本交给幽暗城盗贼区的米奈特·卡加德。', '很好，这比我预计中能从安德隆那里搞出来的情报多得多。给我点时间，在我给你委派下一个任务之前，让我好好地读上一遍。', '你成功了吗，$N?', '', '去提瑞斯法林地找幽暗城的米奈特·卡加德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1918, '被污染的水元素', '被毁灭的水元素留下了一颗水球，它令你感到极端的厌恶，仿佛污染密斯特拉湖的所有物质都包含在这颗水球中一样。$B$B你不清楚谁会对这个感兴趣，不过碎木哨岗的马斯托克·维尔西斯——那个最初派你来这里的家伙——也许对此有所了解。', '将被污染的水球交给灰谷碎木哨岗的马斯托克·维尔西斯。', '你找到了一个令人厌恶的水球，并决定把它交给我?难道我是大地之环的成员吗?$B$B事实上，我突然有了一个想法……也许你确实需要大地之环的帮助。我的意思是，如果它有助于清除湖水中的污秽，我就帮你一次吧。$B$B你知道大地之环是什么吧，$N?', '哦，你需要什么吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1920, '调查蓝色隐士', '有报告称，法师区的蓝色隐士旅店里出现了异常的魔法波动。一些隐形的奇怪生物徘徊在旅店里，我担心那里已经有了一道魔法裂隙。$B$B我希望你去调查一下旅店，捕获那些生物。用旅店中的显形卷轴让它们现出原形，然后用封灵箱抓住它们。当你抓到足够数量的隐形生物之后，就带上装满了的封灵箱和显形卷轴回到我这里来。', '从詹妮亚·坎农身后拿取一根显形卷轴以及一盒封灵箱。将3个装满的封灵箱交给巫师圣殿里的詹妮亚·坎农。', '干得好!我要对这些生物进行一番研究，如果走运的话，我就能搞清楚它们是如何进入我们的世界来的!$B$B你对法师界越来越有价值了，$N。', '你调查过了么?有什么收获呢?', '', '去找暴风城的詹妮亚·坎农。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1921, '收集原料', '你帮了你的法师同行们很多忙，现在是为你制作巫师长袍的时候了。维恩·拉尔森可以帮你这个忙，不过你必须把必需的原料交给她。$B$B制袍用的亚麻布很容易找到，不过你还必须得到充能裂隙宝石，唯一出产这些宝石的地方是在洛克莫丹的银泉矿洞，它们大多被密封在矮人矿工协会的箱子里。$B$B收集好亚麻布和宝石之后，把它们交给法师区拉尔森服装店里的维恩·拉尔森。', '把10匹亚麻布和6颗充能裂隙宝石交给暴风城的维恩·拉尔森。', '嗯，这些真是很不错的亚麻布，我可以做出一件漂亮的长袍来。在我把裂隙宝石点缀在袍子上以后，你就会看见一件非常适合法师的衣裳!', '你好，$N。詹妮亚告诉我你要来。你找到我要的东西了吗?', '', '去找暴风城的维恩·拉尔森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1938, '乌尔的暗影魔法研究论文', '很久以前，三个法师在暴风城里一起学习法术，直到其中的一个开始研究黑暗魔法。他原本并不想深入其中，但是却发现自己在不经意间越陷越深。最终，他被放逐出了暴风城。$B$B这个被放逐的法师就住在赤脊山的伊尔加拉之塔中，他手中有一本强大的魔法书——《乌尔的暗影魔法研究论文》。$B$B我们这些暴风城的法师希望能把那本书拿回来。你要做的就是溜进伊尔加拉之塔，帮我们取回那本书。', '将《乌尔的暗影魔法研究论文》交给暴风城的高阶巫师安多玛斯。', '我曾担心莫甘斯把书藏在了别的什么地方，或者他已经看过了那本书……$B$B幸运的是，他并没有蠢到迈出这一步。我们给《乌尔的暗影魔法研究论文》贴上的封条仍然完好无损。', '你找到那本书了吗，$N?书里的秘密不是为毫无经验的新手准备的，贸然研究它有可能将你引向厄运与毁灭……', '', '去找暴风城的高阶巫师安多玛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1940, '新鲜的蜘蛛丝', '你一直在帮助我们，$N。我想，也许你应该换一件好点的长袍了，一件更适合资深法师地位的长袍。如果你能收集到必需的原料，我们就帮你做一件新的长袍。$B$B你必须进入暮色森林，猎捕那里的食腐独行蛛。抽出它们的丝，但只有最好的、最纯的丝才行。你得到足够的蛛丝后，就把它们交给维恩·拉尔森来帮你缝制长袍，她就在法师区的拉尔森服装店里。', '找到8束新鲜的蜘蛛丝，把它们交给暴风城的维恩·拉尔森。', '这真是上等的蛛丝，我马上就开始工作!', '啊，没错，大法师们已经告诉我你会来和我谈谈了。你拿到我要的蛛丝了吗?', '', '去找暴风城的维恩·拉尔森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1944, '克萨维亚之水', '传说中的克萨维亚城位于灰谷的东部，据说在那里可以找到所有智者都渴望获得的古代知识，而克萨维\r\n亚之水也具有超强的魔法力量。$B$B我需要一些克萨维亚之水——要从水源直接取得的那种。$B$B拿着这只瓶子，去寻找传说中的克萨维亚城吧。从那里最高的瀑布底部收集水样，然后把它交给我。在那里你要步步小心，萨特占领了整个遗迹，它们一定不会喜欢让多事的法师侵入它们的领地。', '将克萨维亚水样交给奥格瑞玛的迪诺。', '啊，非常好。看来克萨维亚城的萨特并没有给你带来什么麻烦。$B$B谢谢你，$N。我会马上投入对水样的研究工作中。', '$N，我很高兴看到你毫发无损地回来了。你得到水样了吗?我急切地需要用它来进行研究。', '', '去找奥格瑞玛的迪诺。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1945, '欢笑的姐妹', '我已经把为你制作新袍子的事情安排妥当了，就等你来提供一些材料……$B$B我需要一些头发来制作你的法袍，你应该可以在灰谷的树妖身上弄到符合条件的头发，那些树妖们都聚集在林中树居那里。$B$B当你找到足够的材料之后，就把它们交给贫瘠之地十字路口的基尔哈拉，他是一个巨魔裁缝。他正等着为你制作最新款的法袍。', '给十字路口的基尔哈拉带去12缕欢笑姐妹的头发。', '啊，$N，这些头发足以编制一件最好的法师袍。真遗憾那些树妖必须为此付出生命的代价，不过她们肯定是不会心甘情愿地把头发交出来的。$B$B有点惋惜，但只是一点点而已。', '你好，$N。迪诺说过你会给我带来欢笑姐妹的头发。那么，头发呢?', '', '去贫瘠之地找十字路口的基尔哈拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1948, '强大的物品', '铸造一根法师的魔杖并不容易。我们需要一些珍贵的材料，而且必须制作一个能储存大量魔法能量的容器——这些事情就交给你了。$B$B我已经把要你去找的东西写在这张羊皮纸上了，把上面列着的东西交给我，另外你一定要按照羊皮纸上的指示行事。如果你不听从我的指示擅自决断的话，我们铸造魔杖时就可能会有……大麻烦。', '将电能草莓和1颗翡翠交给尘泥沼泽的塔贝萨。', '啊，干得好!$B$B我看见的烟是从你耳朵里冒出来的吗?也许是闪电击中图腾时你靠得太近了，但也不用担心。能被闪电击中也是因为你人品好!', '你好，$N。你拿到我要的东西了吗?', '', '去尘泥沼泽找塔贝萨的农场的塔贝萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1950, '解封咒语', '我可以给你书，但你得先帮助我！$B$B你要找的书被锁在我的魔法箱里了。必须念出一些咒语才能打开它，但是我忘记这些咒语了！通常都是我的助手帮我记这些事情，但现在他也不知道跑哪里去了。$B$B如果你想要我的书，那就得先找到我的学徒！到赛车道周围去问问——如果幸运的话，会有人知道他在哪里的。要么把他给我带回来，要么从他那儿问到咒语，不然就别想打开我的箱子！', '找到提尔斯保险箱的解封咒语，然后向提尔斯复命。', '啊，我记起来了……$B$B我已经忘记了对约翰森所下的小小诅咒，也不记得我当时为什么要这么做了，但我确信我这么做是对的，这个忘恩负义的东西!', '你在等什么?赶紧去找回我的开箱咒语!', '获得秘密咒语', '去千针石林找沙漠赛道的大法师提尔斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1951, '能量仪祭', '嗯……我想起来了，我的书已经没有了！你要知道，我欠了一屁股的债，不得不把最后一册《能量仪祭》卖掉来还债，我把它卖给了一个牧师……$B$B他是血色十字军的成员。他一定把那本书带到了他们的根据地——提瑞斯法林地里的血色修道院图书馆去了！$B$B如果你想要那本书的话，就得去一趟修道院。很抱歉给你带来这么多麻烦，这些天我已经有些头昏脑涨了……', '将《能量仪祭》交给尘泥沼泽的塔贝萨。', '就是它了!它正是铸造魔杖的仪式必需的东西!我希望你寻找它的时候没有遇上太大的麻烦……', '你好，$N。你找到我要的书了吗?', '', '去尘泥沼泽找塔贝萨的农场的塔贝萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1954, '地狱火宝珠', '首先，我们必须弄到一颗有魔力的宝珠。火刃氏族的术士有高质量的宝珠……糟糕的是，他们将恶魔收入了宝珠里！当然我们可以解决这个问题，对……我们可以。$B$B到凄凉之地去，从火刃召唤师那里夺取一颗地狱火宝珠。那帮家伙通常在玛诺洛克集会所活动。$B$B拿到宝珠之后就尽快返回我这儿来。', '将一颗地狱火宝珠交给尘泥沼泽的塔贝萨。', '啊，这颗宝珠真不错!不，我所说的“不错”当然不是像夏天喝一杯冰镇饮料那样的“不错”。$B$B实际上，我觉得它现在还算不上不错。我不是说饮料，我说的是宝珠!$B$B集中精力，$N!如果你还想完成接下来的事情，就要集中精力!', '你拿到炼狱火宝珠了吗?', '', '去尘泥沼泽找塔贝萨的农场的塔贝萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1955, '驱除魔鬼', '既然我们已经得到了召唤师的宝珠，现在就让我们来把恶魔从里面驱赶出来。我能做到，这部分相当容易。$B$B我有个艰巨的任务给你，你必须在恶魔出现的时候杀死它。$B$B而且动作要够快。如果你耗时过久的话，或许它就会再跳进去，那我们又得重来一次了！$B$B所以你得准备好最强的技能和所有的物品，如果你有朋友的话，也一起叫上。这件事情不会很轻松的。', '杀死宝珠之魔，然后与塔贝萨谈一谈。', '干得好，$N!你给了那个恶魔一个令它很难遗忘的教训。$B$B下次当它再想把那个丑陋的头探入这个世界的时候，它一定会再三考虑的。也许它会叫上它的朋友一起来，那些巨大而丑恶的家伙，那些只想把你撕成碎片的家伙……$B$B我没有吓着你吧……$N?', '你必须杀了那个恶魔，将宝珠彻底净化，$N。', '杀死宝珠之魔', '去尘泥沼泽找塔贝萨的农场的塔贝萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1956, '奥达曼的能量源', '既然恶魔已经被消灭了，接下来我们就得去找一个能量源。不幸的是，最合适的能量源往往非常古老而且极难获得。有的时候，命运就喜欢这样捉弄你，难道不是吗？$B$B所以，为了得到能量源，你必须到奥达曼去打败那里的黑曜石守卫。他体型巨大而且很难对付，但是你可以从他身上得到我们所需要的能量源！$B$B祝你好运，$N。如果你运气不好的话，那么……很高兴认识你。', '找到一个黑曜石能量源，将其交给尘泥沼泽的塔贝萨。', '你完成任务了?干得好!$B$B我刚刚正在跟几个同事谈话，然后他们正好提到了你，他们说:“你知道吗，$N总是能够在巨大的压力下出色地完成任务!”$B$B但当我告诉他们我把你派去奥达曼对付黑曜石守卫的时候，他们都说我疯了!他们说:“塔贝萨，你真的疯了!$N是绝对不可能战胜黑曜石守卫的!”$B$B我就跟他们说:“是吗?咱们走着瞧……”$B$B现在这帮家伙肯定要脸上无光了，哈哈!', '你去过奥达曼了吗，$N?把那个黑曜石守卫干掉了吗?', '', '去尘泥沼泽找塔贝萨的农场的塔贝萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1957, '法力怒灵', '我们几乎已经要大功告成了，但是最后一步也是最危险的，$N。$B$B我有一颗空的召唤宝珠，准备给它注入力量。我们将通过一道魔法裂缝来完成这个步骤，首先，我会念一段咒语来打开裂缝，此时特殊的生物——法力怒灵将大量涌出来。你必须打败这些生物以释放它们的能量，我会及时用宝珠收集这些能量。$B$B在裂缝关闭之前杀死足够多的法力怒灵，我会把所有收集起来的能量注入你的宝珠。', '在限定时间内杀死12只法力怒灵。', '你成功了!我丝毫没有怀疑过你的能力!好吧，也许曾经有一秒或两秒钟的怀疑……但基本上我并没有太多的怀疑。$B$B真的，我不骗你。', '$N，你还没有杀死足够数量的法力怒灵。', '', '去尘泥沼泽找塔贝萨的农场的塔贝萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1960, '调查炼金店', '在炼金房的奥格诺恩炼金店里有一股奇怪的魔法波动。由魔法能量构成的隐形生物在商店里四处游荡，这其中一定有什么原因，我们必须找到它！$B$B我希望你去调查一下，捕获那些生物。用我身后的显形卷轴让它们现出原形，然后用封灵箱抓住它们。当你抓到足够数量的隐形生物之后，就带上装满了的封灵箱和显形卷轴回到我这里来。', '从安娜斯塔西娅·哈特威尔身后拿取一根显形卷轴以及一盒封灵箱。将3个装满的封灵箱交给幽暗城的安娜斯塔西娅·哈特威尔。', '很好，$N。我会把这些生物拿去给在这方面有丰富经验的同事研究，搞清楚它们出现在这里的原因。$B$B如果它们是从自然形成的魔法裂隙中跑出来的，那我们就必须搞清楚那种裂隙是否随机出现的。如果不是的话……我们就得做好防范的准备了。', '你调查过了魔法波动的成因了么?你抓住那些生物了么?', '', '去找提瑞斯法林地的安娜斯塔西娅·哈特威尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1961, '收集原料', '$N，是时候为你制作你的第一件法师袍了。那会是你地位的标志，同时也是对你的一次考验。$B$B你必须从银松森林的达拉然法师身上获得制作法袍所必需的法力宝石。那些法师和我们拥有相似的信仰，所以杀掉他们会是一件让人感到不快的事情，但是既然他们不具备抵御我们的力量，那他们也就没有继续存活下去的价值了。$B$B把宝石和亚麻布交给法师区裁缝店里的乔瑟夫·格里高利，他会为你制作你的第一件法师袍。', '把10块亚麻布和6块达拉然法力宝石带给乔瑟夫·格里高利。', '这些都是非常好的材料，虽然以我的资质还无法判断这些法力宝石的材质如何，但不久之后我们就能知道它们是否蕴含制作魔焰长袍所需的力量了……', '安娜斯塔西娅已经告诉我你会来这里找我，而我也已经准备好要为你制作法师袍了。你弄到足够的宝石和亚麻布了吗?', '', '去找提瑞斯法林地的乔瑟夫·格里高利。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1963, '碎手氏族', '酋长行事的方法实在是有些太谨慎了。他总是很小心地不让部落显得过于锋芒毕露。一旦我们足够强大了，我们的力量将能征服一切。部落必须重现往日的荣耀和尊严，而现在看来能做到这一点的就只有我们碎手氏族了。$b$b我们必须在暗中积蓄力量，再突然向敌人发起致命的打击，神不知鬼不觉地将敌人除掉。如果你想加入我们，就必须先为我完成一个任务，以此来证明你自己的价值。$b$b有个名叫塔赞的巨魔在棘齿城附近和海盗们做交易，而他那里有我感兴趣的消息。杀了他，把他的背包拿来给我。', '杀死塔赞，把他的背包带给奥格瑞玛暗影裂口的瑟祖克。', '嗯，听说塔赞已经挂了，这事可真让我高兴，不过这锁着的背袋就有些麻烦了。我们想要的资讯都在这里面。$B$B对于想要加入我们破碎之手氏族的人来说，这就算是第二个考验吧。', '只有笨蛋才会相信握着斧头从正面冲锋比用匕首偷袭更加有效。', '', '去找奥格瑞玛的瑟祖克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1978, '亡灵哨兵', '辛迪加？我竟然从来都没有想到是他们，看来奥特兰克的那些贵族们自从背叛联盟以后真是愈加堕落了。$b$b瓦里玛萨斯大人知道了这些一定会非常高兴，另外，既然你在这次侦查行动中表现得这么出色，那么，就由你把我们的调查结果给他送过去吧。$b$b啊，我怎么可能忘了说这个呢！$b$b欢迎加入亡灵哨兵的行列。', '将安德隆的账本交给幽暗城黑暗女王大厅里的瓦里玛萨斯。', '嗯，这很有趣。在追查这件事的过程中，亡灵哨兵们无疑是优秀地完成了他们的职责。$B$B据我所知，你也因为你的卓越表现而得到了表扬。我希望你以后也能一直有这样卓越的表现，$N，我手下的亡灵哨兵部队总能将最优秀的人才罗致麾下。', '嗯?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1998, '芬维克·萨托斯', '瓦里玛萨斯大人刚刚给我下达了一道命令，要求我派人去把一个对我们构成巨大威胁的家伙立刻铲除掉。他的名字是芬维克·萨托斯，瓦里玛萨斯大人认为他是一群在银松森林中肆虐的亡灵的领袖。$b$b一接到这个任务，我马上就想到了你，$n。我坚信，以你的能力一定可以将这个任务轻松完成。$b$b我们派遣到银松森林的亡灵哨兵们发回的最新报告中指出，萨托斯就躲藏在洛丹米尔湖岸边的一处废弃码头上。', '杀掉芬维克·萨托斯，把他的徽记交给幽暗城盗贼区的米奈特·卡加德。', '你做得非常好，$N。我已经看到你为亡灵哨兵完成过许路复用了，这充分证明了你的价值，也许我们应该传授你一些更高深的技艺了……', '我对你抱有充分的信心，你一定能为瓦里玛萨斯大人完成这个任务。', '', '去提瑞斯法林地找幽暗城的米奈特·卡加德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1999, '交易工具', '安伯米尔的肯瑞托法师那里保存着大量关于达拉然现状的文档，这些情报是我们从一个囚犯的口中拷问出来的。瓦里玛萨斯大人已经下令，要求我们必须把这些文件弄到手。$b$b于是这个任务就落到了你的肩上，$n。你需要一些装备，更重要的是得学会开锁的技术。去跟我们的工具商艾斯特蕾·根德瑞谈谈，在你出发前向她要一套开锁工具吧。', '找到达拉然形势报告，把它交给幽暗城盗贼区的米奈特·卡加德。', '很好，$N!你竟然这么快就领会了开锁的技术，比我预计的还要快。$B$B现在我可以确信你是个可靠的$C了。相信我，$g小伙子:姑娘;，我预感到你将来会成就一番大事业。', '你找到那些文件了吗，$N?', '', '去提瑞斯法林地找幽暗城的米奈特·卡加德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2038, '宾格斯的补给品', '好象在洛克湖坠机还不够倒霉似的，湖心小岛上来的穴居人还袭击了我，抢走了我的工具和气压炸弹。没有旋翼机没有炸药，我什么都干不了！$B$B去帮我找回工具和气压炸弹，$N。为了诺莫瑞根！', '找回宾格斯的装备：$B$宾格斯的气压炸弹、宾格斯的扳手、宾格斯的榔头和宾格斯的螺丝起子。', '你为这个行动作出了巨大贡献，$N。诺姆瑞根的穴居人和麻疯地精很快就会感受到地精空袭的可怕力量!', '$N!我的东西在哪儿?!', '', '去洛克莫丹找洛克湖的宾格斯·雷管。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2040, '地底突袭', '诺莫瑞根已经被那群卑鄙懦弱的穴居人们完全占据了！情况很紧急，或许你能帮上我们的忙，$N。$B$B在死亡矿井深处有一台功能强大的地精伐木机，找到这台伐木机并带回它的能源供应机件。有了这台伐木机的能源供应机件，我们就能给高速钻孔挖掘机供应足够的能量，用它来钻透这里与诺莫瑞根之间的岩石。钻开一条路，给他们来一次侏儒式的突袭！', '从死亡矿井中带回规模高能发动机，将其带给暴风城矮人区中的沉默的舒尼。', '干得好，$N。谢谢你，我们很快就能解放诺姆瑞根啦!', '你找到规模高能发动机了吗，$N?', '', '去暴风城的矮人区找沉默的舒尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2078, '基尔卡克的报复', '旱鸭子，你得帮忙找到我的大副。$B$B带上这把钥匙，把它插入我的大副身上的钥匙孔里，然后把他给我带回来。$B$B那些鱼人们马上就要吃不了兜着走了，因为我的大副就要回来啦！', '找到基尔卡克的大副——机械打手4100型，把他带到基尔卡克那里。', '呀……你还真有两下子啊，旱鸭子。$B$B如果你能一直有这样的表现，船长大人我也许会开恩晋升你为甲板水手。', '我的大副呢，$N?如果你再不快点的话，我就把你和鲨鱼拴在一起!', '', '去黑海岸找薄雾海的基尔卡克·旋杆。', '基尔卡克的大副', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2098, '基尔卡克的钥匙', '想要当一个出色的海盗可不简单呀，你这个旱鸭子是不会理解的。我们的生活并不仅仅只是掠夺和痛饮！唉，我的船在海岸附近被那些可恶的鱼龙给弄沉了。$B$B我希望我的大副能够重新回来工作！$B$B当我被冲到海岸的时候，大副的钥匙在岩石上折断了，接着又被黑海岸那一带的怪物给偷走了，我只记得隐约看见一些狂暴暗礁蟹、凶猛的森林陆行鸟和几个鱼人正在搜寻船的残骸……', '找到基尔卡可钥匙的3段碎片，把它们交给基尔卡克·旋杆。', '等等，小子!你找到钥匙啦?我的大副很快就能回来工作，那些畜牲就会知道我的厉害啦!$B$B嗯，你看见我的大副了吗?', '旱鸭子，你找到我的断钥匙了吗?', '', '去黑海岸找薄雾海的基尔卡克·旋杆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2118, '瘟疫蔓延', '一种疾病正在黑海岸蔓延，它能够控制一切与它接触的灵魂和肉体。$B$B这种瘟疫对蓟熊的影响最大，使得这种曾经高贵的动物现在几乎变成了毁灭和杀戮的机器——它们变得狂暴，完全失去了理智。我有一种方法应该可以治疗这种病。$B$B把这个陷阱放到森林的空地上。任何狂暴蓟熊经过时，都会在短时间内变得驯服。一旦蓟熊安静下来了，就上前安抚它，减轻它的痛苦（使用/soothe命令），然后它就会跟你走。把它带到这里来，$N。', '活捉一只狂暴蓟熊，把它带到萨纳瑞恩那里。', '$N，我们的工作才刚刚开始。你准备好迎接下一项任务了吗?', '你带回染病的蓟熊了吗?$B$B万一陷阱失败了也不用着急―萨纳瑞恩的希望是永远不会破灭的。如果你需要一个新的陷阱，请先放弃你的任务，然后再回来向我报告。', '', '去黑海岸找奥伯丁的萨纳瑞恩·绿树。', '捕获狂暴蓟熊', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2138, '清除疫病', '正如我所担心的，这种疗法没有起到效果。$B$B对我来说，任何野生动物的死都是一件令我难过的事情，但是我们必须杀掉这些感染了瘟疫的狂暴蓟熊。$B$B$N，回到森林里去，杀掉20只狂暴蓟熊。这虽然无法驱散瘟疫，但可以在短期内降低狂暴蓟熊对这片森林和森林里的居民们带来的破坏。', '到森林里去杀掉20头狂暴蓟熊。', '你为奥伯丁做了件伟大的事，$N，不过你的任务并没有完成。$B$B休息一下，然后再到我这里来。$B$B……$N，你必须做好准备迎接更残酷的挑战。', '你完成任务了吗?', '', '去黑海岸找奥伯丁的萨纳瑞恩·绿树。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2139, '萨纳瑞恩的希望', '$N，我们用惨痛的代价换取了黑海岸和奥伯丁的平安。$B$B你杀了很多早已病入膏肓的动物，减轻了森林的痛苦，也解脱了这些动物的灵魂。尽管这种状况只能持续一小会儿，但是奥伯丁的人民感谢你。$B$B我要交给你最后一项任务，请注意，这将是又一次的杀戮任务。我希望这是最后一次让你去做这样的事情，$N。$B$B有一只雌蓟熊住在东北方的一个靠近巴莎兰的洞穴里，杀了她。', '找到雌蓟熊，然后杀掉它。', '感谢你英勇地为奥伯丁而战，$N。在我们这片饱经战火的土地上，死亡与绝望随处可见。很多人不愿意面对生活的挑战，而是选择了躲避在他们的安乐小窝里，或者干脆逃向更安全的地方。$B$B谢谢你，$N。也许有一天，我们会再次并肩作战，一起对付又一个给森林和我们的同胞带来危险的敌人。', '感染了瘟疫的雌蓟熊一死，这一带的狂暴蓟熊的数量将会大大减少。快点去吧，$N。', '', '去黑海岸找奥伯丁的萨纳瑞恩·绿树。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2159, '多兰纳尔的货物', '你好，年轻的$c。你能帮我一个忙吗？我有一包药草必须送到多兰纳尔去，但是现在我还要忙于处理幽影谷德鲁伊的事情，所以走不开。$B$B你能帮我把这包药带去吗？把它送到多兰纳尔旅店的老板凯达米尔那里，那座旅店就在南方的路边上。', '把药草送到旅店老板凯达米尔手中。', '啊，原来是从幽影谷送来的药草。真遗憾伯萨努斯不能亲自把它送来，我还有很多事情想和他商量呢。尽管如此，我还是很高兴得到药草，也对你的到来感到高兴。$B$B你就在这儿休息休息吧，英雄们必须让他们的身体和精神都保持最佳状态，而且也必须及时得到足够的休息。休息不充分必定会导致你在冒险的旅途中遭遇失败。$B$B所以……快去休息休息吧。', '有什么我能为你效劳的吗，年轻的$C?你要住旅店吗?你需要炉石吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2160, '塔诺克的补给品', '嘿！我一看就知道你是个精力充沛的冒险家。如果你要继续前进的话，能不能帮我带个包裹到卡拉诺斯的旅馆去？$b$b你应该已经计划在那个旅店里稍作休息了，对吧？我敢说只要你到了旅店，就肯定会想在那里歇一下脚。$b$b无论如何，请把这包裹带给旅馆主人的助手塔诺克·霜锤。我自己是没法活着穿越那危险的通道了，巡山人卫队还得过些天才会经过这儿，所以我只能靠你了。', '给卡拉诺斯的塔诺克·霜锤带去一箱旅店补给品。', '啊哈，我的补给品终于到了!我最近一直很担心，自从巨魔开始频频活动之后，我们得到的有关安威玛的消息就少得可怜。$B$B谢谢你把这个带给我，$N。好好休息一下吧。这次旅途一定让你疲惫不堪了。', '嘿，伙计!快进来，坐在火堆边来上一大杯好麦芽酒暖暖身子吧!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2161, '苦工的重担', '对不起，你能帮帮我吗？$B$B我这儿有一车食物，一路上我遭遇了蝎子、蜘蛛，还有其它更可怕的东西！我把这些食物送到了试炼谷，因为我觉得他们可能会需要这个，同时我又很乐意帮助他们。$B$B但是他们居然根本就不需要食物！现在我还得把这些东西带回剃刀岭，可是我害怕路上的那些野兽……$B$B你能不能帮我送回去呢？我只是个苦工，可你是个大英雄，你一定什么都不怕！$B$B请把东西交给剃刀岭旅馆的老板格罗斯克。', '把乌克尔的货物交给剃刀岭的旅店老板格罗斯克。', '啊，这些是乌克尔送到试炼谷去的食物。他们不需要吗?我猜他们是想把你们这些训练中的英雄都饿死吧，他们会说这是为了锻炼你们的意志!$B$B谢谢你把食物都送回来，我要把它们都放回架子上……等一下，我给你拿些点心来吧!$B$B别忘了在旅馆里休息一会儿。你是个很勇敢的$C，随时准备外出冒险，但是过度消耗体力对你自己和我们的部落都不是什么好事。', '你好，$C。欢迎来到剃刀岭!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2178, '炖陆行鸟', '你闻到扑鼻的香气了吗？那可是用我的秘方精心烹制的、新鲜出炉的炖陆行鸟，口感超绝，美味无比！$B$B你对我的食谱很感兴趣吧？$B$B在我告诉你食谱之前，你得证明你能对付那些动物。$B$B我可并不是要求你简单地跑出去驯服一只陆行鸟，然后骑回来见我。你得去捕杀一些陆行鸟，把它们那些多汁的肉脯带回来给我。只有这样我才会把炖陆行鸟的秘方教给你。', '给急弯河的奥兰达利亚·夜歌带回5块陆行鸟肉。', '妙极了!尝尝看，你觉得味道如何，$N?', '锅里一直都空着，我都快饿死了。你怎么去了那么久?', '', '去黑海岸找奥伯丁的奥兰达利亚·夜歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2198, '破碎的项链', '你找到了一条破碎的项链，但是破旧不堪的外表并不能掩饰它高超的制作工艺。项链已经破碎，原本应该镶在项链上的三块宝石不见了。在项链的内侧印有铁炉堡的徽记，旁边还刻着三个小字：“TdK”。$B$B如果你想要了解这条项链背后的故事，你就必须找到它的主人。也许那个徽记和小字就是线索……', '找到破碎的项链的来源，从而了解其潜在的价值。', '对……我就是制造这条项炼的珠宝匠，不过我可没义务免费为你提供谘询服务，听着，伙计，世上没有免费的午餐。如果你想让我帮你的忙，你就得先帮我的忙。', '你找错人了!我什么都没干过!你没有证据!$B$B等等……你是谁?这个……你在哪里找到这条项炼的?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2199, '昂贵的知识', '我在铁炉堡可是鼎鼎有名的珠宝匠！好吧，我承认那是以前的我……因为一个竞争对手的污蔑让我变成现在这个样子！名声不好在这行里就根本混不下去。结果，你看，我现在就变得穷困潦倒。$B$B现在，我要你给我搞五块银锭来，这样我才能完成我手头上的这份订单——看来这是我唯一的一份订单了。$B$B你给我五块银锭之后，我就会回答你所有关于这条项链的问题。', '给铁炉堡的塔瓦斯德·基瑟尔带去五块银锭。', '你真是太好了，我高兴得都要哭了……说真的，真是太感谢你了，我的朋友。$B$B现在，我可以告诉你，你手里的项炼是我最得意的作品之一，但是用于禁锢其中魔法力量的三块宝石已经不见了。很久以前，我为一位圣骑士打造了这条项炼，当时他正要去清除荒芜之地一个名叫奥达曼的挖掘场里的“邪恶势力”。$B$B但是……那个圣骑士死在了奥达曼，这只是我噩梦的开始。', '你搞到我要的五块银锭了吗?我会告诉你关于你手里拿着的那条项炼的悲惨故事……但一定要等你搞到我要的五块银锭之后!请帮帮我这个可怜的地精吧!', '', '去找湿地的塔瓦斯德·基瑟尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2201, '寻找宝石', '从这个圣骑士的日记上看，只有奥达曼才有可能是项链上的那三块宝石的所在地。如果日记的描述还算准确的话，在奥达曼里有大量的暗炉矮人和穴居人在活动。$B$B知道了这些信息之后，对宝石的搜索行动就可以开始了。当你收集到所有的宝石之后，通过塔瓦斯德的占卜之瓶和他联系来获取下一步的指示。', '在奥达曼寻找红宝石、蓝宝石和黄宝石的下落。找到它们之后，通过塔瓦斯德给你的占卜之瓶和他进行联系。', '没错，就是这三块宝石。干得好!不过你的工作还没有完成。$B$B不，你的任务并不那么简单，愚蠢的$C。我需要的是具有魔法的宝石―顶级的宝石!你需要强力的能量源来为它们注入能量。但是现在项炼本身已经无法再为宝石注入能量了。', '塔瓦斯德的影像慢慢地在占卜碗的水面上浮现了出来。$B$B“啧啧，你还活着!你找到那些宝石了吗?我可把你当作我的救世主啊!希望你不是随随便便就浪费了一次占卜之瓶的使用机会;时下什么东西都不便宜!为了这东西，我已经陷入了严重的经济危机了!”', '', '去找塔瓦斯德的占卜之碗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2202, '奥达曼的蘑菇', '$N，我听说有一种紫色蘑菇刚刚被发现，它们似乎只在奥达曼挖掘场里生长。我需要十二个这样的蘑菇来进行炼金术的研究。$B$B你要多加小心，这种蘑菇会喷射出有毒的孢子。$B$B帮我这个忙吧，我会给你丰厚的报酬，另外还可以让你尝尝我收藏多年的好酒！', '收集12颗紫色蘑菇，把它们交给卡加斯的加卡尔。', '干得好，$N，你再一次证明了自己的价值!这种蘑菇是研究炼金术的上好材料!$B$B现在……来尝尝我收藏多年的陈年好酒吧!$B$B如果你是个有经验的炼金师，那我们还可以继续进行合作。不管怎么样，我要再次感谢你对我的帮助。', '你拿到我需要的紫色蘑菇了吗?找不到我要的东西，我可不会付给你报酬的!', '', '去荒芜之地找卡加斯的加卡尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2203, '荒芜之地的试剂 II', '$c，你帮我了大忙了。我愿意与你分享你曾经品尝过的那种佳酿的配方……但我还要你去完成一项相当危险的任务。仔细听好我的要求。$B$B这只有锁的箱子里面装着三个空的魔瓶，它们被赋予了一种能够汲干烈焰守护者血液的魔法能量，用魔瓶收集烈焰守护者的血液是非常危险的，所以请多加小心。当你装满了三个瓶子之后，就把它们交给我。$B$B快去吧，你离那个配方只有一步之遥了。', '用空的魔瓶吸收荒芜之地的烈焰守护者的血液。装满所有瓶子之后，把它们交给卡加斯的加卡尔。', '我以一个炼金师的身份向你致敬。拿着这个配方吧，它会对你大有帮助的。愿它带给你的成功与回报像它这些年来带给我的一样多。', '你用瓶子取回我想要的龙血了吗?没错，我知道那是一项非常危险的任务……不过你可以得到我的秘方，有风险就会有回报，我的朋友……有风险就会有回报……', '', '去荒芜之地找卡加斯的加卡尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2204, '修复项链', '你现在需要去为项链找到它的“精神”力量，奥达曼无疑最适合的地方。据说那里有很多的石人跑来跑去，对吗？那么，杀死他们当中最强大、最邪恶的那个石人，然后把他身上的能量源夺过来！我敢保证可以把那能量源里的能量重新注入到项链之中。$B$B如果没有那样的能量源，想要修复项链根本是不可能的。取得能量源之后尽快回到铁炉堡来找我，然后我们就能把项链完全恢复到原来的状态啦！', '从奥达曼最强大的石人身上获得能量源，然后将其交给铁炉堡的塔瓦斯德。', '很好―我很高兴看到你和能量源都安然无恙地回来了。我要花点时间来把能量源的力量注入到已经镶好宝石的项炼上。一旦我完成了这个工作，项炼就是你的了!$B$B你很兴奋，不是吗?满怀期待?那就让我赶快开始工作吧……', '看得出你是马不停蹄地从奥达曼赶回来的。你回到这里应该不只是为了抱怨那个地城的气味有多让人讨厌吧?好了，希望你给我带回来的是好消息。$B$B你找到修复项炼所需的能量源了吗?', '', '去找湿地的塔瓦斯德·基瑟尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2205, '军情七处', '徽章？哦，没什么，你应付不了的。看你的样子，我敢说马迪亚斯·肖尔一定会把你当成送奶酪的$g男孩:女孩;而不是个真正的盗贼。不管怎样，我被指派了一个任务，而且我曾保证要完成这个任务。$B$B对了，说到这个，你去把这个包裹带给马迪亚斯吧，他可能会交代你去做些事情。$B$B快去吧。', '把科瑞恩·塞尔留斯的包裹带给暴风城兵营的马迪亚斯·肖尔。', '你找到我了―看你这个样子，我就知道接下来将要交给你的任务对你来说会很有压力，无论是精神上还是肉体上。$B$B那么，你是想让雷吉克指给你去旅店的路呢，还是准备要做些正事了?', '有事吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2206, '连偷带抢', '我们派在外面的探子回报说，迪菲亚兄弟会在闪金镇南部的活动相当频繁。报告中还说道，迪菲亚兄弟会控制了杰罗德码头，并利用它将大量的违禁品从赤脊山走私到西部荒野去。$B$B我要你想办法到码头旁的屋子里去一趟，把里面的船运时间表给我偷出来，那东西应该就在码头主管的衣服口袋里。$B$B……还有，$N，如果你的行动被发现了的话，暴风城军情七处将不会承认你的存在。', '找到迪菲亚码头主管，从他那里为马迪亚斯·肖尔拿到迪菲亚船运时间表。', '我相当惊讶……科瑞恩竟然给我物色到了这样一个训练有素又称职的盗贼。拿着这把匕首吧，$N。总有一天暴风城军情七处会再度需要你的。别让你的技术给荒废了，你要永远睁大警惕的眼睛，永远将你的匕首磨得无比锋利。$B$B你可能看不见我们，但时候一到，我们自然会联络你……', '你准备在兵营里无所事事地晃上一辈子么，$N?', '', '去暴风城找军情七处的马迪亚斯·肖尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2239, '奥宁的报告', '你是说采石场？是的，我几乎天天都能看见那些庞大的蒸汽坦克从营地边经过。$B$B我在东边布下的线人告诉我，这些机车是从铁炉堡出发的，在古博拉矿场稍作停留之后，在卡拉诺斯补给燃料，由于某些该死的原因，他们用了很长的时间才经过诺莫瑞根，最后在铁炉堡卸下了货物。$B$B情况全都写在这份报告里了，$c。把它交给霍夫丹，让他好好计划下一步的行动。', '把奥宁的报告交给铁炉堡的霍夫丹。', '你走了很远的路程吧?以我自己胡子的名义!$B$B你干得不错，$N。请带上这把匕首。当我们开始执行第三步以后，议会就会召唤你。$B$B第三步是什么?第三步就是第二步后面的那一步―到时候你就知道啦。$B$B有兴趣吗?', '你有没有喜欢闻那些麻疯地精的恶臭?我随便问问而已，因为我看见你脸上露出了疯狂的笑容。$B$B你从奥宁那里带回了什么消息?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2240, '密室', '现在我手头有个任务。$B$B我们要找到一间被称作卡兹穆尔大厅的密室。问题是这个房间在一扇巨大的门后面，而那扇门被锁住了！幸运的是，我知道如何打开它。$B$B我把所有东西都写在我的日记里了，就在这个台子上。我的队伍现在被困在这里……所以呢，$n，你必须为我们找到卡兹穆尔大厅！$B$B阅读我的日记，探索那间密室，然后向铁炉堡探险者协会的勘察员塔伯斯·雷矛汇报。', '阅读巴尔洛戈的日记，探索密室，然后向铁炉堡的勘察员塔伯斯·雷矛汇报。', '你找到卡兹莫尔大厅了?真是太惊人了!巴尔洛戈认为它确实存在，但是我承认我当初并不是十分相信他。$B$B谢谢你，$N。你的发现将会促使我们的领袖重新考虑夺回奥达曼的计画。如果铁炉堡重新控制奥达曼的话，那卡兹莫尔大厅的秘密就是我们的了!', '你有什么要报告的吗?', '探索密室', '去找丹莫罗的勘察员塔伯斯·雷矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2241, '詹诺克的花', '他们说我已经“陷入爱的深渊”，管它是什么意思呢。$B$B当然啦，我清醒的每一刻都在想念着塞尤娜，我的家里也挂满了她的画像。当然，我会经常不吃不喝也不睡地度过一整天，深陷于我们曾经拥有的美好爱情的回忆之中。这难道有错吗？$B$B现在她不会再见我了！我想要给她传递消息，但她不愿和任何人说话，除非那人是个盗贼。$B$B你能替我把这些花带给她吗？别忘了告诉她这些花是詹诺克送的。', '把詹诺克的玫瑰带给达纳苏斯的塞尤娜。', '如果我把詹诺克那个傻瓜送来的每一朵花都存下的话，开个花店都不用愁了。不管怎样，看来詹诺克派来的最后一个送信人还是有点用的。$B$B你有兴趣找些事情干吗，$C?', '啊，这难道不是很美妙吗?你已经为你的葬礼买好了鲜花。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2242, '命运的召唤', '我们相信有一个萨特可以帮助我们搞清泰达希尔的森林中究竟发生了什么。但不幸的是，他可不会老老实实地跟我们合作。$B$B他的藏身之处就在神谕林地外围的一棵树上，但是与他接触的人——无论是使用武力还是试图交涉——都被他杀死了。也许只有偷偷摸摸地行动才是唯一可行的方案，$N。$B$B去看看塞希尔的包裹里有些什么，然后回来向我报告。', '找到远古的塞希尔，带回任何你可能发现的线索。', '这是个悲惨的消息，$N。蔓延于黑海岸一带的森林与河流的疾病似乎已经开始侵袭我们的家园了。$B$B你做得很好，但这儿已经没有什么你能做的事情了。拿着这把匕首吧，这是你为泰达希尔效力所得到的报酬。', '你有关于塞希尔的事情要报告吗，$N?', '', '去达纳苏斯找贸易区的塞尤娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2258, '荒芜之地的试剂', '$C，我需要你的帮助。我是个略有名气的炼金术者，现在我想请你去荒芜之地帮我弄些试剂来。$B$B我需要以下物品：5个秃鹫的胃囊，10颗峭壁山狗的牙齿，还有5个石元素的碎片。当然，你可以从那里的野兽身上弄到这些东西，但是假如你不是那么善于战斗的话，就去找一些朋友帮帮忙吧。$B$B帮我找到这些物品，我就会给你些钱作为报酬。愿意试试吗？', '转至荒芜之地取回加卡尔需要的试剂，然后回到卡加斯把试剂交给他。', '啊，干得不错，$C。稍微等我一会儿。这是你应得的报酬。$B$B如果你感兴趣的话，我还需要更多的材料。然而，那些材料只能从奥达曼的挖掘场里找到，而且就算你到了那里也不大可能轻而易举地拿到手。不过如果你能再帮我一次的话，我将会给你丰厚的回报。$B$B这次的回报可不仅仅是一些小钱了，怎么样?', '你找到我需要的东西了吗?除非你帮我弄来那些东西，否则你得不到任何报酬。', '', '去荒芜之地找卡加斯的加卡尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2278, '白金圆盘', '财宝室的中间是四块巨大的白金圆盘，每块圆盘上都刻满了各种各样的未知文字和图案。你的手触摸这些圆盘的时候，你感到了一丝震动。就在你接触圆盘的一瞬间，一个巨大的石头守卫者的形象出现在了你的面前。$B$B“你好。我是知识的守卫者。土灵的创造者所留下的一切有关这个种族的知识都已经存储在了这张诺甘农圆盘上了。”$B$B你发掘到了迄今为止这个世界上最宝贵的知识财富！', '和石头守护者交谈，从他那里了解更多古代的知识。一旦你了解到了所有的内容之后就激活诺甘农圆盘。', '按照石之看守者的指引，你完全了解到了土灵、矮人和石腭怪的起源和历史。一阵轻微的嗡嗡声从圆盘中传出。石之看守者说:$B$B“圆盘已经集成完毕。请再次触摸诺甘农圆盘，获取属于你的资料拷贝。”', '石之看守者的声音如此雄浑，你在聆听他的叙述的时候感到灵魂的震撼:$B$B“你必须首先达成圆盘的输入融合要求。一旦你满足了这个要求，你就可以获得一份可携式的资料存储资料。请先确认你已经完全阅读过该资料库中所存储的资讯。”', '学习石头守护者所看守的知识', '使用诺甘农圆盘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2279, '白金圆盘', '再次触及诺甘农圆盘让你的手感受到了又一次的震颤。这一次从圆盘传出了一种奇怪的研磨声。$B$B你的背包忽然沉了一下。打开背包之后，你发现了一张迷你版的圆盘！$B$B毫无疑问，在任何对艾泽拉斯大陆历史感兴趣的人手中，这张圆盘都绝对是无价之宝。铁炉堡的探险者协会是一个非常有名的探险团体，也许他们能好好利用这张圆盘。', '把迷你版的诺甘农圆盘带到铁炉堡的探险者协会去。', '你拿的是……我的天啊，你在哪里找到它的?$B$B你说的是真的?$B$B你和谁说过这件事了?$B$B从来没有，真的吗?!$B$B我的好$C啊，你的这件东西绝对是今年考古学界最重要的发现!我发誓，这个发现可以作为本世纪最重要的发现!如果这些圆盘中确实包含你所说的东西，那也许它就是我们一直以来所要找的东西!这完全解释了矮人这个种族的起源!', '你好，我能帮你什么忙坏吗?我现在真的很忙。但是如果你有什么重要的新闻，那我愿意洗耳恭听!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2280, '白金圆盘', '再次触及诺甘农圆盘让你的手感受到了又一次的震颤。这一次从圆盘传出了一种奇怪的研磨声。$B$B你的背包忽然沉了一下。打开背包之后，你发现了一张迷你版的圆盘！$B$B毫无疑问，在任何对艾泽拉斯大陆历史感兴趣的人手中，这张圆盘都绝对是无价之宝。雷霆崖的先知们对历史知识的了解程度享誉整个部落，也许他们能好好利用这张圆盘。', '把迷你版的诺甘农圆盘带到雷霆崖的贤者那里。', '这些是什么东西?$B$B太让人惊奇了，年轻的$r!我从这些圆盘中感受到了被深藏许久的秘密。你做了一件明智的事情。', '没错，年轻的$r，我看得出你是带着坚定的决心经过长途跋涉才来到我这里的。你来找我应该是有什么对整个部落来说都很重要的事情吧?或者你是想要从我这里了解一个重大的秘密?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2282, '奥瑟尔伐木场', '多年以来，我们都在这里对盗贼进行训练！毕竟不是每一个盗贼都能像老卢修斯那样机灵和优雅的。$B$B沿着这条路向前走，一直到奥瑟尔伐木场去。我在那里放了一只装着重要物品的箱子。去把箱子里的东西给我拿来，我就给你颁发收集技能认证书！', '打开卢修斯的箱子，拿到收集技能证明物，然后把它归还给湖畔镇的卢修斯。', '你打开箱子了?干得好，$N。$B$B那么，从今往后，即使你死了，我也不会感到内疚，因为那是因为你自己太愚蠢而不是经验不足造成的。', '我没有和你提过那座磨坊附近有兽人吗?$B$B我听说那些兽人就在周围的山上活动。', '', '去赤脊山找湖畔镇的卢修斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2283, '搜寻项链', '我们有工作要交给你做，不过能否完成要看你有没有胆子！$B$B在荒芜之地的深处有一个名叫奥达曼的挖掘场，我们最近听说有个没脑子的圣骑士在里面挂了。我之所以如此关心这个问题是因为那蠢货身上带着一条非常珍贵的项链，项链上有三块大宝石：一块红宝石，一块蓝宝石和一块黄宝石。$B$B现在的问题是，我们需要它，而且我们会付给完成这个任务的人最丰厚的报酬。也许那条项链已经受到了损坏，但是不管怎么样，只要你把它带给我们，就总是会有办法修好它。', '在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。', '嗯，就是它了!在你还没到我这里的时候我就嗅到项炼的味道啦!现在让我来欣赏一下这条举世无双的项炼吧……$B$B嘿，你到底在搞什么鬼?项炼上的宝石都不见了!你当我是瞎子吗?连玛尔顿也看得出宝石不见了。$B$B好吧，也许不是你偷了宝石……但是没有宝石，这条项炼就一文不值!你的任务远没有完成!', '怎么样，拿到项炼了吗?如果你拿不出项炼，那就一个铜板都别想拿到!', '', '去找奥格瑞玛的德兰·杜佛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2338, '翻译日记', '杜佛斯那个蠢货是不可能恢复项链的力量的，不过我可以。现在我要做的就是好好研究一下项链，然后给你制作一条跟它完全一样的复制品。请把项链借给我作为我帮你翻译日记的交换吧，在你出发去找寻宝石的这段时间里，我应该可以完成对项链的研究和对日记的翻译工作。$B$B这个交易很简单明了，而且没有别人可以帮你翻译日记。你看怎么样？', '将项链借给加卡尔。作为交换，他将帮你翻译日记。', '你是个聪明的$C，$N。我只需使用一个法术就可以迅速地将人类的语言翻译成你可以理解的语言。我是一个巨魔;你可以在整个部落里打听打听，有谁不知道我的名字。现在，让我们开始工作吧……', '你应该已经好好琢磨过这桩交易的利弊吧?你是个聪明的$C，如果你接受这桩交易的话，那就皆大欢喜了―你我都可以如愿以偿，而德兰和玛尔顿也会以为他们得到了自己想要的东西。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2339, '寻找宝贝', '日记已经全部翻译完毕了。$B$B其中的关键是红宝石在暗炉矮人手里，黄宝石在穴居人手里，而蓝宝石则在一个名叫格瑞姆洛克的穴居人那里。$B$B你需要一个强力能力源来让项链重新恢复以前的力量，这一点是德兰·杜佛斯所不知道的。我所能想到唯一符合如此要求的能量源应该在奥达曼的最强生物身上，所以你必须深入奥达曼的最底层，杀掉所有看上去最强的生物，这样你就肯定可以获得它。$B$B当你把所有东西找全之后就尽快把它们带回来给我。', '从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。$B$B红宝石被藏在暗影矮人层层设防的地区。$B$B黄宝石藏在穴居人活动地区的一个瓮中。$B$B蓝宝石在格瑞姆洛克手中，他是穴居人的领袖。$B$B能量源可能在奥达曼的某个最强生物的手中。', '干得太漂亮了，$C。现在我们的付出将得到回报。我有足够的信心完全重铸项炼，从而让其恢复力量。$B$B但是首先，在你将宝石和项炼带回奥格瑞玛之前，让我用早已准备好的咒语来对它们进行一番快速分析。我相信这只会花费一点点时间。', '如果你要寻找那些宝石和能让项炼恢复力量的能量源的话，你就得再次回到奥达曼去。$B$B你找回宝石之后，就把它们送到奥格瑞玛的那些呆子手里，而我会把能量源保留下来，因为它是让项炼恢复力量的最关键的东西。', '', '去荒芜之地找卡加斯的加卡尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2340, '交付宝石', '只要采用相同的材料进行制作，任何的项链和宝石的组合都能发挥作用。而这个能量源才是真正给项链提供力量的关键……我希望如此。$B$B只要能量源能够一直保持正常运转，我随时都可以为你制作这么一条项链。$B$B去奥格瑞玛找德兰·杜佛斯完成你们的交易吧。记住不要透露任何关于项链的信息，当你回来的时候，我会给你一个特别的惊喜的。', '把项链和宝石送到奥格瑞玛的德兰·杜佛斯那里。', '嗯，所有的东西都在这了。呃，我可以把这个包裹也留下吗?可以?太感谢了，你真是个好心的$C!$B$B这条项炼对我们来说很重要!不要难过，我确定这条项炼不适合你。$B$B交易就是交易，所以我现在就给你报酬。这样，我们的交易就算完成了，以后你可以再回来看看我们这里有什么工作可以做的。但是现在，你可以走了!', '看看谁来了!看来你过来的一路上还算顺利，我想你来这里不是要浪费我的时间吧!除非你带来我要的东西，否则我是不会给你报酬的。请注意:我们会反复地仔细确认每一件东西!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2342, '寻找宝物', '我简直烦透了用这把破扫帚在这里打扫蝙蝠窝了！我靠这个该死的工作中存了一些钱，而且我愿意用这些钱来雇你帮我做些事情。$B$B加瑞特系列的祖传武器自从我们家到那里去当挖掘工以来就一直被锁在奥达曼的南部大厅中的箱子里。没有它，我就要永远被困在这里——也就是说，我就得永远跟这些该死的蝙蝠在一起！$B$B找到我系列的宝藏，把它给我拿来！帮我找回原本就属于我的东西！', '从奥达曼南部大厅的箱子中找到加勒特的系列宝藏，然后把它交给幽暗城的帕特里克·加瑞特。', '啊―这绝对是一把极品扫帚!我付出的奖金绝对是物有所值!$B$B你们听到了吗，愚蠢的蝙蝠?我现在挥舞的是加勒特系列祖传的武\r\n器!颤抖吧，蝙蝠，颤抖吧!!', '这清扫工作真是没完没了……那些该死的蝙蝠一直以来都在嘲笑我和我的扫帚。快告诉我，你找到了我的系列宝藏没有!我会给你一大堆钱的―难道这还不够吗?!', '', '去银松森林找幽暗城的帕特里克·加瑞特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2358, '奈兹拉之角', '很多年之前，奈兹拉之角被从拉文霍德的领地上偷走了。经过漫长的跋涉和搜寻，我终于得知它一直以来都在那些野兽的手中。$B$B干掉你见到的所有黑石兽人，直到你夺回奈兹拉之角为止，拿到它之后就回来找我。$B$B请为我找回奈兹拉之角吧，你的名字将永远被拉文霍德系列铭记，$N。', '帮助湖畔镇的阿兰提尔找回奈兹拉之角。', '谁胆敢偷窃拉文霍德系列的东西，他就绝不会有好下场。干得好，盗贼。你现在已经有足够的资格傲视拉文霍德系列培养的刺客了。$B$B当我年轻的时候，曾在黑海岸那里发现了一种可以在战斗中补充能量的茶。这些年来它一直对我很有帮助，现在我可以给你尝一尝。当你感觉到疲惫的时候就喝些茶，$N，然后你将再次充满战斗的力量。', '你找到那个恶魔王子的角了吗?', '', '去赤脊山找湖畔镇的混乱之手阿兰提尔', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2359, '克拉文之塔', '我为如何进入这座塔的问题头痛好久了，$N。最近从暮色森林来了一船货物，同时还来了不少守卫。$B$B他们是谁？我也有着和你一样的疑问。我所知道的是——他们不是人类。$B$B不管怎么样，这批货物中有一只特殊的箱子——我想这就是那些亡灵在守护的东西。带着狼牙棒的那个家伙手里有那座塔的钥匙。$B$B拿到钥匙，进入塔里，看看箱子中到底有什么，然后去向马迪亚斯报告。', '偷取迪菲亚塔楼钥匙，进入迪菲亚塔楼，看看暮色森林的箱子里到底有什么东西，然后向暴风城的马迪亚斯·肖尔汇报。', '这可以解释为什么你和吉尔妮在塔外会看到迪菲亚闲工，$N。这也可以解释风险投资公司和迪菲亚兄弟会的关系，以及为什么会有货物从暮色森林运到那里。$B$B根据这本书上的内容，荆棘谷的赞吉尔已经研究出了利用某种药水―或者说是毒药―来制造亡灵的办法。$B$B如果你对毒药一无所知的话，你对军情7处来说就是毫无用处的，$N。这种药水可以让你在弹指之间创造一个听命于你的行尸走肉。', '吉尔妮那边有什么消息?', '', '去暴风城找军情七处的马迪亚斯·肖尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2381, '抢劫海盗', '我并不是要吓唬你，$N，但是前五个派去偷南海宝藏的小偷都是被别人一块块运回来的……$B$B沿着这里南边的海岸走，你会找到海浪剃刀号，那是南海海盗的船。货舱中的东西就是你的目标——南海宝藏。在船舱的二层是海盗的聚集处，那里也是他们训练盗贼的地方。$B$B设法登上那条船，然后把南海宝藏给我偷到手。你可以在那群海盗扎堆的地方试试自己的身手，但是你要非常小心，否则你就会成为第六个！', '把南海宝藏带回给棘齿城的卑鄙的维尼克斯。不要忘了从维尼克斯的机械设备中拿取一份大饼干和盗贼工具，你的任务需要使用这两件东西。$B$B如果你被任何奇怪的鹦鹉攻击，就对它使用大饼干！', '不可思议!这绝不可能!太让人惊奇了!你真是个天才，$N。你真是个幸运星!$B$B这个是我给你的报酬，我相信它对你比对我更有用。', '不管怎么样，你现在看来还是完好无缺的。你找到我要的宝藏了吗?', '', '去贫瘠之地的棘齿城找卑鄙的维尼克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2383, '简易羊皮纸', '啊，刚刚你不在的时候，有人送来了这张羊皮纸，$N。$B$B如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是战士训练师弗朗恩写的，他有事找你。你可以在大兽穴外面的阴凉处找到他。', '阅读简易羊皮纸，然后和试炼谷的弗郎恩谈一谈。', '啊，那是我的羊皮纸。我早就听说你要到这个峡谷里来了，$N。很高兴你真的来了……希望你可以通过将要面临的试炼。$B$B祝你好运，$N，当你准备好接受训练的时候就来找我吧。', '你手里拿的是什么?一张羊皮纸?我希望你不是个学者……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2418, '能量石', '不久之前，我和暗炉矮人打过一段时间的交道。他们把我带到了苦痛堡垒，让我对两种来自于奥达曼的奇怪石头进行研究。我发现这两种石头如果经过正确的处理，就会变成相当理想的能量源。能在那个废旧的挖掘场里发现这样的东西让我感到十分惊奇！$B$B之后，在我告诉他们这个秘密之后，那帮该死的家伙就把我踢出了苦痛堡垒，然后自己在奥达曼挖掘更多的石头。$B$B我要为自己搞一些那种石头！帮我带那两种石头来，我会给你丰厚的报酬的。', '给荒芜之地的里格弗兹带去8块德提亚姆能量石和8块安纳洛姆能量石。', '太好了，你找到它们了!非常感谢你，$N。你是我遇到最可以信赖的$r!$B$B我已经等不及要把这些东西装在我的设备上试用了。我敢打赌，在正确的使用环境下，这些石头会发挥无穷的力量……', '$N，你拿到能量石了吗?我有个机械动物需要这样一个能量源……', '', '去荒芜之地找巨牙谷的里格弗兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2438, '翡翠摄梦符', '班奈希尔兽穴的德鲁伊守护者盖洛拉斯·塔文斯伦曾经给了我一个翡翠摄梦符。这种强大的护符可以吸取翡翠梦境的能量，给拿着它的人带来好运。$B$B不过，我把它放在星风村的衣柜里了，没办法把它取回来……星风村原本是个宁静的小村子，但现在那里受到了熊怪的侵袭。$B$B你能不能帮我拿回摄梦符，$c？', '将翡翠摄梦符交给多兰纳尔的塔隆凯·捷根。', '翡翠摄梦符对我来说非常重要。这样的东西只有少数被选中的人才能得到。谢谢你把它还给我，$N。', '请快点行动吧。我祈求我的翡翠摄梦符没有遭到熊怪的破坏。$B$B你拿到了它了没有，$N?', '', '去泰达希尔找多兰纳尔的塔隆凯·捷根。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2439, '白金圆盘', '这东西真是个惊人的发现。如果这里储存的知识都是正确的话，那么这些圆盘所涉及的古代泰坦——或者说造物之神——肯定和我们的起源有所联系！我们要用尽可能多的时间来研究它。$B$B至于你，英勇的$c，把这个凭证交给大厅里的丁尼塔·石衣，你一定会为你的伟大发现得到应有的报酬！$B$B准备好了之后就回到我这里来，探险者协会还有很多事等着你去做！', '把你的报酬凭证交给铁炉堡银行的丁尼塔·石衣。', '啊，没错，这的确是探险者协会的凭证……我得说，这是个很有价值的凭证。$B$B根据探险者协会赋予我的权利，我允许你直接从他们的储藏室里选择报酬。你先拿着这个，然后请选择5瓶治疗药水或5瓶强效法力药水作为报酬。', '欢迎来到铁炉堡银行，$N。我能为你做些什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2440, '白金圆盘', '我要把精力都集中在这些圆盘上，它们一定会向我展示其真正的作用。$B$B至于你，$N，你的努力也会得到我的回报。把这个证明交给雷霆崖的炼金师本娜·冰蹄，她会给你一样不错的东西作为回报，还会给你一些我私人收藏的药水。$B$B尽快回来见我，我感觉这个发现还会让我有很多事要忙。', '把报酬凭证交给雷霆崖的本娜·冰蹄。', '好吧，$N，你一定是做了让贤者图希克非常高兴的事，他才会把这个给你。你还可以得到他收藏的药水，你可以选择5瓶超强治疗药水或5瓶强效法力药水作为你的报酬。', '你好，$C!你是来接受炼金术训练的，还是为其它什么事?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2459, '噬梦者菲罗斯塔', '翡翠……不见了！我的摄梦符被毁了！$B$B星风村北部有一群瘤背秘法师。我接到报告说他们的领袖——噬梦者菲罗斯塔的脖子上戴着一根在夜间会发出绿光的项链。我觉得就是它偷走了我的翡翠……它决不会想到那颗翡翠对它毫无用处。$B$B去找到丢失的宝石，$N。另外，你在那儿活动的时候，别忘了顺便清除一些堕落的秘法师。', '多兰纳尔的塔隆凯·捷根要你杀掉7个瘤背秘法师，并找到遗失的珠宝。', '现在我可以修复摄梦符了。谢谢你，$N。', '菲罗斯塔和瘤背秘法师必须把我的东西还给我。请取回翡翠，这样我才能修复我的翡翠摄梦符。', '', '去泰达希尔找奥拉密斯湖的塔隆凯·捷根。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2478, '基本不可能的任务', '你必须从工头希里克斯身上偷出塔楼的钥匙，$N。拿到钥匙之后，就把它收好——你也许用得到它。$B$B记住，毒药已经让塔楼里的所有人都变得虚弱不堪。尽你所能给那些家伙制造混乱和破坏——不要手下留情！$B$B等里面所有人都倒下之后，你就可以去打开加里维克斯的箱子，然后拿走赞吉尔的改良药剂。把加里维克斯的徽记和药剂一起交给奥格瑞玛的申苏尔。', '从工头希里克斯那里偷出希里克斯的塔楼钥匙，进入塔楼，然后杀掉两个变异风险投资公司工人、两个风险投资公司巡逻员、两个风险投资公司看守。$B$B杀掉大工头普兹克·加里维克斯，取得他的徽记，然后打开加里维克斯的箱子，拿走赞吉尔的改良药剂。将药剂和加里维克斯的徽记交给奥格瑞玛的申苏尔，等候进一步的指示。', '可怜的费苏勒，他是个出色的探子。唉，这就是我们要付出的代价，$N。做破碎之手氏族的密探是个危险的工作。$B$B你的任务完成得很出色，$C。如果你不能再为我们效力的话，那会是我们的一大损失。', '你有什么要报告的吗，$N?', '', '去找奥格瑞玛的申苏尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2479, '希诺特的帮助', '把这个混合物的样本交给塔伦米尔的瑟尔格·希诺特。$B$B只有瑟尔格能治得了你所中的毒。如果你能活得久一点的话，他还能教你制造并使用这种毒药的方法。', '到希尔斯布莱德丘陵的塔伦米尔去，把赞吉尔的药剂样品交给瑟尔格·希诺特。$B$B要去塔伦米尔，可以搭乘飞艇到幽暗城，然后沿着大路向南穿过银松森林，直到希尔斯布莱德丘陵。跟着路标走！', '你看起来脸色苍白，$C。你身上那股臭味是怎么回事?我必须得知道!', '这是什么???', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2499, '奥肯斯古尔', '在湖南岸的山洞里有一个名叫奥肯斯古尔的林精，它正在使居住在奥拉密斯湖周围的所有生物变得堕落。$B$B我不敢离那里太近，不过即使从远处看去，我也能看得很清楚：奥肯斯古尔已经被一颗我所见过的最大的肿瘤所毒害了……那个肿瘤简直可以被称作庞然大物。$B$B$N，你已经帮了我许多忙，不过我还要请你做一件事。杀掉奥肯斯古尔，拿到它身上的肿瘤，让这个堕落之源永远从我的家园消失。', '奥拉密斯湖的德纳兰要你去拿到奥肯斯古尔身上的巨大的瘤。', '我就知道你的能力不只是足以将那个可怕的野兽赶出湖区这么简单。$B$B这真是个棘手的局面，奥肯斯古尔曾经是一个伟大的树精领袖，但是堕落是不分平民和贵族的。$B$B这个肿瘤如此巨大，让我感到十分费解，不过我一定要对它做进一步的研究才能更多地了解这种疾病。$B$B谢谢你，$N。', '你找到奥肯斯古尔了吗，$C?', '', '去找泰达希尔的德纳兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2500, '荒芜之地的材料', '$C，我需要你的帮助。我是个小有名气的炼金师，我需要你去荒芜之地帮我找一些原材料。$B$B我需要这些东西补充我的库存：五个秃鹫的胃囊、十颗峭壁山狗的牙齿和五块岩石元素碎片。当然你可以从这些动物身上拿到这些东西，不过如果你不擅长打仗的话，可以找些擅长的朋友。$B$B找到这些东西给我，作为交换你可以得到一些钱币。$B$B好吧，你觉得怎么样？', '从荒芜之地拿到加克所需的材料，然后回到塞尔萨玛去见他。', '哦，干得好，$N!这些够我用一阵子的了。这是我许诺给你的报酬。$B$B如果你有兴趣的话，我还需要些别的材料，不过这些材料只能在奥达曼挖掘场的深处找到，而且比较困难。如果你有兴趣再帮助我的话，我会给你更多报酬的。$B$B也许我会给你一些比明晃晃的钱币更有价值的东西，你觉得怎么样?', '你找到我需要的东西了吗?除非你帮我弄来那些东西，否则你得不到任何报酬。', '', '去洛克莫丹找灰爪山的加克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2501, '荒芜之地的材料 II', '你对我的帮助很大，$N。我可以把以前我给你的那种酒的配方作为报酬送给你，不过还得让你先帮我个忙才行——这次的事比较危险。$B$B这只上锁的箱子里装着三个空的魔瓶，里面有一种可以吸取火龙血液的魔法能量。用这些容器去对付火龙会把它们激怒，所以你得小心点。把三个容器都盛满了，再把它们拿回来给我。$B$B完成这个任务之后，配方就是你的了。', '在荒芜之地的守护火龙身上使用空的魔瓶。将这些容器都盛满之后，把它们交给塞尔萨玛的加克。', '我以一个炼金师的身份向你这个同行致敬。拿着这个配方，它是属于你的了。希望它能给你带来成功和回报，就像它这么多年给我带来的那样!', '你取回我想要的龙血了吗?没错，我知道那是一项非常危险的任务……不过你可以得到我的秘方，有风险就会有回报，我的朋友……有风险就会有回报……', '', '去洛克莫丹找塞尔玛的加克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2518, '月神的泪水', '萨丝拉曾经受到月神的宠爱，这只优雅而纯洁的蜘蛛在月光下的迷雾中编织着银线，用以收集银色的露水，并将这种有治疗功效的露水存放在这个大殿里。$B$B不过最近萨丝拉却突然变得疯狂起来，她的后代也受到了威胁。$B$B找到萨丝拉，$N，结束她的痛苦。她住在泰达希尔的北部边界。找到她的银色丝囊，把它们交给我。', '达纳苏斯月神殿的女祭司艾茉拉让你把萨丝拉的银色丝囊交给她。', '整个森林都在为萨丝拉女士哀悼，不过那是我们不得不做的事情。$B$B谢谢你，$N。', '我很遗憾不得不交给你这个任务，不过萨丝拉已经没有挽救的希望了。$B$B我们希望能把这些丝囊作为祭品献给艾露恩。有了这个祭品，她就会保佑萨丝拉，让她有可能获得重生，并获得安宁。', '', '去达纳苏斯找神殿花园的女祭司艾茉拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2520, '萨丝拉的祭品', '现在你必须完成交给你的任务。拿上银色丝囊，然后将它作为萨丝拉的祭品献给艾露恩，让这只蜘蛛得以安息。$B$B找到大殿中央的喷泉，在那儿放下祭品。神圣的泉水可以净化并清洗让萨丝拉发疯的堕落力量。$B$B完成任务之后再回来见我。', '女祭司艾茉拉让你将萨丝拉的银色丝囊放在大殿的喷泉处，然后回去见她。', '失去萨丝拉女士是令人悲伤的，不过只有这样她才能以全新的灵魂获得重生。$B$B愿艾露恩能接受你献给她的祭品。', '你把祭品放到喷泉那儿了吗，$N?', '在喷泉处奉上祭品', '去找达纳苏斯的女祭司艾茉拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2521, '为库米沙效力', '$R，你的小脑袋能理解一颗无瑕的德莱尼水晶球有多么珍稀吗？无数德莱尼人终其一生就想要寻找一块这样的水晶，可是却屡遭失败，一直没能达到愿望。$B$B你现在就站在库米沙面前，你知道库米沙想要什么，而且你还愿意帮助我？很好，$r……在你探索者个区域的过程中，只要找到一颗无瑕的德莱尼水晶球，就把它带回来给我，我会以你永远都无法想象的财富回报你。', '在你探索诅咒之地的旅程中，如果碰巧发现了无瑕的德莱尼水晶球，就把它交给收藏家库米沙。$B$B你要知道，这种宝石是整个艾泽拉斯最珍稀的水晶。诅咒之地上的任何一种生物都有可能带着一颗无瑕的德莱尼水晶球。$B$B每找到一颗，你都会得到相应的酬劳。', '我的眼睛在欺骗我吗?不可能!你从哪儿……怎么会……$B$B也许现在我可以找到一个裂隙，让我们返回家园。', '我一生都在寻找无暇的德莱尼水晶球。整整一生，你明白么，$r?', '', '去找诅咒之地的收藏家库米沙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2522, '库米沙的努力', '虽然召唤传送门的魔法失败了，不过我相信下一次一定能成功。$B$B德莱尼人的希望就象你们$r对财宝的渴望一样强烈，回到这块被诅咒的土地中去，再给我拿回一颗无瑕的德莱尼水晶球来。$B$B当然，要不要接受这个任务完全取决于你*咧嘴笑*。', '找到一颗无瑕的德莱尼水晶球，把它交给收藏家库米沙。', '真是太让我吃惊了!我曾经怀疑你是否能再找一块德莱尼水晶球回来，而它现在就在这儿，在我的手中跳动着。$B$B干得好，$N!$B$B如果你还能再找到一颗―我认为这是不太可能的―就把它交给我，我仍然会付给你相应的报酬。', '你找到新的德莱尼水晶球了吗?', '', '去找诅咒之地的收藏家库米沙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2523, '被腐化的轻歌花', '', '', '你将一些塞纳里奥植物药膏涂在了这株轻歌花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的轻歌花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2541, '沉睡的德鲁伊', '这里的瘤背萨满祭司找到了一种可以在德鲁伊休眠时将他的灵魂和肉体分离的方法。熊怪就这样驱使着我的肉身，利用我去袭击那些对班奈希尔兽穴进行侦查的人。现在我沉睡在翡翠梦境里，无法阻止他们。$B$B你一定要帮帮我。瘤背萨满祭司用一种特殊的符咒来完成这种仪式，我希望能研究一下这种咒符。$n，全靠你了。', '将一个萨满巫毒符咒交给班奈希尔兽穴的奥本·怒爪。', '谢谢你，$N。$B$B这真是个奇怪的小符咒……我可以感受到它散发出的可怕能量，这里面包含了一种极为强大的魔法。', '如果我能研究一下那种符咒，也许就能破解瘤背萨满的魔法。你找到符咒了吗?', '', '去找泰达希尔的奥本·怒爪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2561, '利爪德鲁伊', '在研究过这个咒符之后，$N，我知道该做什么了。请拿着它，然后照我说的去做。$B$B你必须到班奈希尔兽穴的深处去，在那里，你会发现我那失去灵魂的躯体……虽然我对将要让你这么做感到很遗憾，但是除此之外我找不到其它可以让我摆脱瘤背熊怪控制的办法了。$B$B你必须杀了我的肉身，然后对我的尸体使用巫毒咒符。完成这个任务之后就请回到我这里来。', '奥本·怒爪要求你去杀掉他那失去灵魂的身体，然后对其尸体使用巫毒咒符。', '我终于摆脱了瘤背熊怪的控制。谢谢你，$N。$B$B我的灵魂现在可以在翡翠梦境永远安息了。$B$B也许有一天我们还可以再见面，年轻的$C。不过现在，请你收下这个，它代表了我对你的感激之情。', '$N，靠近我的身体时要小心点，它已经被赋予了极强的力量。', '释放奥本·怒爪的灵魂', '去找班萨罗兽穴的奥本·怒爪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2581, '弯牙土狼的颚骨', '众所周知，土狼的颚骨具有强大的力量，不过它能折断三英寸厚的瑟银条吗？不可能，决不可能，可是我却亲眼看到了这种事情。$B$B到诅咒之地去给我弄三个弯牙土狼的颚骨回来，路上顺便打一些野猪和蝎子，因为我还需要两片诅咒之地的野猪肺和一个厚甲蝎螯。', '收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。', '感觉怎么样，$N?你浑身都散发着土狼的气味―你的力量已非凡人可敌了!$B$B不过用你给我弄来的这点原料，我最多只能做这么多药剂了。如果你还想要更多的话，就给我多找些原料来。', '你身上真臭，$N，是不是在硫磺地里走过了?我要的东西在哪儿?!', '', '去找诅咒之地的血法师德拉吉亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2582, '远古之怒', '啊，$N，欢迎回来。你好像非常喜欢从土狼的颚骨中提炼出来的药剂所带给你的感觉。但是你要小心，虽然它可以使你拥有泰坦一般的力量，不过它对你的精神和智力也具有长期的负面作用。$B$B我跟你说了这么多之后，你还想要更多这种药剂吗？如果你还要的话，就给我弄三个弯牙土狼的颚骨、两片诅咒之地的野猪肺和一个厚甲蝎螯来。', '收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。', '给你!记住省着点用啊。如果你用完这些还想要的话，就再来找我。', '你找到我要的那些东西了吗?', '', '去找诅咒之地的血法师德拉吉亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2583, '野猪的活力', '这片不毛之地上生活着两种野猪：灰鬃野猪和地狱野猪。$B$B看来这些野兽的耐力十足，这让它们几乎可以不受任何伤害，因此其它动物都无法与之抗衡。$B$B我们要做进一步的研究，$N。你给我弄三片诅咒之地的野猪肺、两个厚甲蝎螯和一颗石化蜥蜴的大脑来，我就可以从中提炼出一种超强的药剂。而你就将成为我的第一个实验对象！', '收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。', '野猪的力量让你更加强大了，$N!你相信自己可以和那些野猪一样强韧吗?', '我要的原料在哪儿，$N?!', '', '去找诅咒之地的血法师德拉吉亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2584, '野猪之魂', '在第一次试用这种药剂的时候，我就知道仅用一两次是无法满足你对它的渴求的。即使是现在，我也还能看见你眼中的渴望。这种药剂会让人上瘾，再有意志力的人也无法抵挡它的诱惑。$B$B好吧！如果你还想要更多的肺片鸡尾酒，就到诅咒之地里去给我弄三片诅咒之地的野猪肺、两个厚甲蝎螯和一颗石化蜥蜴的大脑来。', '收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。', '我必须提醒你，$N，不要想把我的药剂混在一起。你最后使用的药剂的药性总是会替换在这之前所使用的药剂，所以别用了这个又用那个，白白浪费宝贵的药剂。', '我要的原料在哪儿，$N?!', '', '去找诅咒之地的血法师德拉吉亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2585, '决定性的打击', '你见过它们作战吗，$N？我是说那些蝎子。你有没有见过他们优美、敏捷的动作？有没有看到过它们那迅捷的攻击？$B$B如果我们能将它们的敏捷性分离出来并制成药剂，那我们就发达了……我的意思是……那将是我们对科学的一大贡献！$B$B帮帮我吧，$N，我可以送给你一份实验样品。$N我需要三个厚甲蝎螯，两个秃鹫的砂囊和一片诅咒之地的野猪肺。', '收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。', '太棒了!这是我遇到的最难分析的东西。$B$B拿一撮残馀的盐放在舌头下面，你会感到有点兴奋，之后就会发现自己具有惊人的敏捷和速度。', '我要的原料在哪儿，$N?!', '', '去找诅咒之地的血法师德拉吉亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2586, '厚甲蝎盐', '你还活着！这真是个好消息。我猜你回来是想要更多的厚甲蝎盐吧？$B$B很好，$N，那么，你再回到诅咒之地去，帮我弄三个厚甲蝎螯、两个秃鹫的砂囊和一片诅咒之地的野猪肺回来吧。', '收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。', '干得很好，$N。这份是给你试用的样品，剩下的九份我要留着做研究。$B$B如果你需要更多厚甲蝎药粉的话，就回到这儿来跟我交易。', '我要的原料在哪儿，$N?!', '', '去找诅咒之地的血法师德拉吉亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2601, '石化蜥蜴的大脑', '这块荒地上到处都是红石蜥蜴，$N。这些蜥蜴的族群比这里的其它任何生物都要兴旺。$B$B我曾经在远处观察过它们的捕猎和其它日常活动——这些野兽表现出了某种思考过程，它们的智商甚至比某些人型生物还要高。$B$B我得研究一下他们的脑子！$B$B给我找十颗蜥蜴的大脑来，$N。还有，你必须再找两个秃鹫的砂囊，否则我就无法完成药物的配制。', '收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。', '这简直是奇迹，$N!我可以让你欣赏一下红石蜥蜴的内部构造。$B$B如果你对这种药物有兴趣的话，我也可以为你多做一点……当然，不是免费的。', '你弄到我要的那些动物器官了吗?', '', '去找诅咒之地的血法师莱诺雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2602, '清晰的思想', '药效这么快就没了？看来我还有更多的研究要做！$B$B哦，当然，条件不变，$N。回到诅咒之地去，给我弄十颗石化蜥蜴的大脑和两个秃鹫的胃囊来。', '收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。', '好，给我点时间，你就能得到更多的药物了，$N。$B$B拿着……还有，$N，不要在短时间内连续使用这些东西，那样可能会带来灾难性的结果。', '你弄到我要的那些动物器官了吗?', '', '去找诅咒之地的血法师莱诺雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2603, '秃鹫的活力', '死亡在这片被诅咒的土地上长出了翅膀，$c。我曾亲眼目睹那些秃鹫将探险者的尸体狼吞虎咽地吃掉——有时它们甚至会吃下携带着致命疾病的尸体。它们身体内部的系统竟然能够抵御席卷了这片土地的瘟疫，这的确令我感到十分惊奇。$B$B请帮助我进行研究，$N！我需要秃鹫的砂囊，还需要两块弯牙土狼的颚骨作为原料。$B$B我会和你五五分成的。', '收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。', '非常出色!我要立刻开始工作了。也许我能找到一种包治百病的方法!$B$B啊，对了，当然还有你的报酬―如果你想要更多砂囊口香糖的话，就回到我这儿来，继续帮我收集原料，然后我就可以帮你再做几份。', '不要浪费我的时间，$N。我们没什么可以讨论的―除非你已经找到了我要的东西。', '', '去找诅咒之地的血法师莱诺雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2604, '精神矍铄', '我看到你体内的火焰已经渐渐熄灭，那就是说，药效只持续了一个小时？$B$B如果你还需要更多砂囊口香糖，就给我弄更多的砂囊来。在诅咒之地中收集十个砂囊和两块腭骨之后再回来。', '收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。', '也许有一天我可以分离出这种药物中的活性酵素，然后用它制成更有效的药物。不过，现在你只能用我现在做出来的这种东西。如果你需要更多口香糖的话，就回来找我吧。', '不要浪费我的时间，$N。我们没什么可以讨论的―除非你已经找到了我要的东西。', '', '去找诅咒之地的血法师莱诺雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2605, '口渴的地精', '住在大沙漠里真是活受罪！我都要被烤干了。$B$B不过我有个主意。听说有一种被称作露水收集者的生物就在西南方活动……它们有一种特殊腺体，可以用来储藏水分。$B$B如果能得到这种腺体，我就可以畅饮一顿，至少滋润滋润我的嘴唇！你能帮帮我吗，$N？$B$B找到有一大片仙人掌的地方，$N，露水收集者常在那里出没。', '找到1个饱满的露水腺，把它交给加基森的马林·诺格弗格。', '哦，太棒了!快拿来―让我喝一口!', '求求你，快给我把露水腺弄来吧!', '', '去塔纳利斯找加基森的马林·诺格弗格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2606, '好味道', '呸！这个东西真难吃！这个主意也不过如此嘛……$B$B等等，你说什么？哦，我知道，我知道，你认为我不该就这么放弃它。那么，好吧。$B$B对了，我有个主意！一个妙极了的主意！去和我朋友斯普琳科谈谈吧——她是个出色的厨师。告诉她我们想做什么，还有我们想要知道加点什么才能把让人这东西咽下去。$B$B我的意思是，如果它这么难吃的话，总得让它有些让人兴奋的东西才行……可是我现在就是感觉不到。', '马林·诺格弗格让你与加基森的斯普琳科谈一谈。', '马林心眼不错，只是有一点点古怪。$B$B当然，他又一次需要我的帮助了。为什么我要说又呢……', '老马林又需要我的帮助了吗?这玩意是用什么做的?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2608, '赞吉尔之触', '哦，天哪，你看上去就象死人一样。纠正一下——我见过死人，你看上去比死人还要糟，简直像是死了又死！$B$B哈哈！诺拉姆，你听见了吧？把它记下来！$B$B*咳嗽*嗯，好吧。为了帮助你，我得先给你抽点血。别担心，只有前几次抽血会有点疼……大概前五十次吧……准备好了之后就躺下（使用/lay指令），$N。', '用/lay指令躺下，接受道克·米希匹克斯的治疗。如果他找不到病因，就找不到治疗的方法。', '等我和同事们交换一下意见，$N。蒙特高莫医生，诺拉姆先生，让我们来讨论一下吧!', '准备好了之后就躺下(使用/lay指令)，然后让我开始帮你抽血。', '诊断完成', '去找暴风城的道克·米希匹克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2609, '赞吉尔之触', '我们达成了共识，$N，你得的是“伊提斯综合症”。$B$B幸运的是，我这里有医治伊提斯综合症的药方。$B$B我需要些东西：一束普通野花、一只铅瓶，一根青铜管，最后还要一卷淡绿色丝线。奥·艾玛在“最好的线团”那家店里给我留了一卷这样的线，就在运河区沿岸。$B$B赶紧出发吧，$N，记住在你的病痊愈之前不要接触任何人。哦，还有，蒙特高莫医生说你该洗个澡了——他说的，不是我说的。', '给道克·米希匹克斯带去一束普通野花、一只铅瓶，一根青铜管，最后还要一卷淡绿色丝线。伊提斯综合症可不会不治而愈，年轻的$g先生:小姐;。', '我在做什么?我看起来像是在做什么?我当然是在为你的伊提斯综合症研究治疗方法!现在别对我发火，$N!$B$B再等几秒钟。好了!把这个喷上，嗯，喷在你身上味道不错，你会焕然一新的。', '你想治好伊提斯综合症的话，就得更加努力点，$N。我要的各种原料都找到了吗?', '', '去暴风城找英雄谷的道克·米希匹克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2623, '沼泽空谈者', '分队指挥官下达了命令。我们接……接到了命令。在去诅咒之地的路上，被伏击了。$B$B鱼人……很多鱼人……其中一个叫沼泽空谈者的鱼人，从我手上抢走了命令，然后……长矛插入了我的头骨。它应该就在东边……山洞……$B$B<本戈尔昏死了过去。>', '取回酋长的命令，把它们还给部落英雄的灵魂。', '比我想象中的更糟糕。如果我不是那么冲动的话，我手下的十九个兄弟本来可以免受那些痛苦。$B$B你一定要帮帮他们，$N!我已经无能为力了。', '等待命令。', '', '去悲伤沼泽断矛路口找部落英雄的灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2641, '斯普琳科的秘密佐料', '在我还小的时侯，我姐姐包揽了所有烧饭的活，那简直是糟透了！她做的有些东西简直让我无法忍受——直到我发现了一种被我称作“秘密佐料”的东西，只要加上一点……啧啧！味道好极了！$B$B你问那是什么东西？嗯，是一种被称作紫色水生菇的蘑菇。如果你要我把这个尝起来像拖把一样的东西变成可以下咽的食品，那么我建议你去一趟辛特兰，到那里去找一个小湖泊。$B$B哦，记住了，紫色水生菇只有在水下才能找到。', '加基森的斯普琳科要你去给她找到一颗紫色水生菇。', '就是这个，$N!$B$B它看起来很不错，哈哈!', '在湖水下面―只有在那里才能找到紫色水生菇。你找到了没有，$N?', '', '去塔纳利斯找加基森的斯普琳科。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2661, '给马林的粉末', '这是紫色粉末，$N，把它交给马林，告诉他，他欠我一个人情！', '斯普琳科让你把紫色粉末交给加基森的马林·诺格弗格。', '紫色粉末?让我们试试它的效果吧―反正情况不会变得更糟了，这一点可以肯定!', '哦，$N，你终于回来了。你带什么东西回来了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2681, '禁锢我们的石头', '要击败拉瑟莱克和他的手下，只靠你一个是不够的。$B$B召集一队勇士，让我的同伴摆脱永恒的折磨吧！你要打碎十八块石头。$B$B努力战斗吧，$N。', '解救九个拉瑟莱克的仆从、三个瑟温妮的仆从、三个奥利斯塔的仆从和三个戈洛尔的仆从。完成任务后，回到部落英雄的灵魂这里。', '你成功了，$N!那些饱受折磨的可怜灵魂终于可以安息了。$B$B不过我们的工作还没结束，$N。我们还有很多事要讨论，很多事要做。', '这个任务可不简单，$N。不要轻易放弃!', '', '去悲伤沼泽断矛路口找部落英雄的灵魂。', '解放拉瑟莱克的仆从', '解放戈洛尔的仆从', '解放奥利斯塔的仆从', '解放瑟温妮的仆从');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2741, '超级测蛋器', '', '', '你将角鹰兽的蛋放入机器，随后里面传来了一些奇怪的机械声响和嘟嘟声。$B$B似乎测蛋器正在为这颗蛋称重、测量和包装。真是快捷又完善的服务!', '超级测蛋器是克格尔.曲藤的最新成果，看起来真是令人印象深刻。$B$B你刚刚接触到超级测蛋器的控制面板，它就劈啪作响了起来。', '', '去找塔纳利斯的测蛋器。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2742, '林吉被困住了！', '嘿，那边的$r！$B$B请你帮林吉逃出去，我知道像你这样的$r不喜欢林吉，不过林吉求你了！我要逃出去！$B$B如果$r帮林吉逃出这里，$r就可以得到一些好东西……$B$B林吉在望海崖藏了个大秘密。', '护送林吉逃出奎尔丹尼小屋，然后在望海崖找到他藏起来的东西。', '这个巨大的巨魔石板一定就是林吉所说的“秘密”了。$B$B石板上画着奇怪的记号，你根本看不懂。$B$B是奥兰.斯内克威瑟派你到这个地区来的……也许他可以给你提供更多帮助。', '林吉害怕!', '护送林吉到安全地区', '去辛特兰找望海崖的林吉的秘密。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2744, '恶魔猎手', '那三个魔王受到拉瑟莱克的保护。$B$B为了让他们忠诚地为他效力，拉瑟莱克使他们在诅咒之地可以使用几乎无限的力量。他们佩戴的护符和他们的命运联系在一起，并使他们变得不老不死。只要他们待在诅咒之地，你就没法杀了他们，他们的生命力可以维持到世界末日。$B$B我认识一个也许可以帮助你的朋友，$N。到艾萨拉地区的小岛上去找恶魔猎手洛拉姆斯·萨里比迪斯谈谈吧。', '与艾萨拉的洛拉姆斯·萨里比迪斯谈一谈。', '我可以帮你。不过，我觉得你还不清楚你将面对的是什么。', '你在这里做什么?', '与洛拉姆斯会面', '去艾萨拉找风暴海湾的洛拉姆斯·萨里比迪斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2746, '必备物品', '提亚斯要加快实施计划了吗？好吧，我们可以做到，不过我还没准备好。你知道，我要做的是最困难的部分，而你是负责动手的人，明白吗？很好。$B$B我要让你先帮我准备些东西，这样我就可以对间谍机器人进行伪装，让它安全地骗过那些守卫。$B$B给我带回一些丝绸和几只苹果来。丝绸你自己去找，不过城外那个克拉拉的小农场上有非常合适的苹果。', '将3块丝绸和2只克拉拉的新鲜苹果交给暴风城的泰里恩。', '有这些东西就行了，$N。你干得很好。$B$B我的其馀工具都在我的包里……感谢圣光，我还有个裁缝朋友可以帮我做一只丝绸包。我都快要装不下这一大堆东西了!$B$B在继续执行计画之前，我们得把一切细节都安排好，这样你就知道你具体需要做些什么了。', '我已经监视莱斯科瓦好几个星期了。提亚斯一直不相信他，不过我们并不认为他和迪菲亚兄弟会有什么牵连，我们所追踪的线索表明他和暮光之锤有一定的联系。不管怎样，他已经变得越来越危险，越来越难对付，我们应该插手了。$B$B把那些东西找来，我们就可以执行计画了。', '', '去找暴风城的泰里恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2747, '特别的蛋', '', '', '好吧，我给你一个―大惊喜!$B$B希望你能永远记住今天!', '我很少看见从菲拉斯送来的蛋有如此完好的。这些蛋真的十分罕见……', '', '去找塔纳利斯的克格尔·曲藤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2748, '优良的蛋', '', '', '很好，$N。我会把这只蛋送到达纳苏斯去，希望它可以在那里孵化!$B$B这是我对你的小小谢意，请收下它。', '在理想的条件下，一只优良的蛋应该可以丝毫不受戈杜尼巨魔咒语的影响，完全正常地孵化出来。', '', '去找塔纳利斯的克格尔·曲藤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2749, '普通的蛋', '', '', '你找到了一只普通的蛋，$N?请把它交给我……我们只能往好的方面想了。$B$B我没有多少钱，不过请收下你的报酬。如果你再去菲拉斯的话，别忘了帮我带些蛋回来。', '普通的鹰角兽的蛋只有一半的孵化机会。我们尽力培育它们，只要再有点运气，就能成功孵化。', '', '去找塔纳利斯的克格尔·曲藤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2750, '坏掉的蛋', '', '', '我有个坏消息要告诉你，$N。这颗蛋实在是无法满足要求，我可以帮你把它处理掉。$B$B不要灰心，我们总不可能把它们都孵出来。如果你要再去菲拉斯的话，就继续帮我找些蛋回来吧。', '这些蛋没有任何价值―它们永远无法孵化。', '', '去找塔纳利斯的克格尔·曲藤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2751, '野人装甲', '这只铁锤在沃姆什系列中传了二十代，$N。我们熔铸的铁有成千上万吨。不幸的是，这门技艺到了奥罗克手中却传不下去了，这是沃姆什系列的耻辱——我既没有亲属，又无法生育后代。$B$B决不能让沃姆什的祖传技艺和我一起死去！必须有人继承它，不管他是不是沃姆什系列的后裔！$B$B向奥罗克证明你的能力吧，$N。给奥罗克找来这些东西：两副青铜花纹护腕，两把青铜巨剑和两只锋利的爪子。把这些找来，我们再继续。', '将2副青铜花纹护腕、2把青铜巨剑和2只锋利的爪子交给奥格瑞玛的奥罗克·沃姆什。', '沃姆什的血脉就要断了，不过它的传说还将继续!$B$B你已经证明自己是个名副其实的铁匠，$N。对铁匠来说，最好的奖赏就是看到自己所造的武器和护甲沾上敌人的血!$B$B但愿你所铸造的胸甲都能在战场上浸染你的敌人的鲜血!', '青铜，$N!更多的青铜!!', '', '去找奥格瑞玛的奥罗克·沃姆什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2752, '铁肩铠', '奥罗克可以看出你眼中的渴望，$N。你像海绵一样渴望吸收沃姆什的智慧。$B$B我会教你三样东西！$B$B到铁砧那边去，感受熔炉的热量，为奥罗克铸造四把青铜战斧和四把青铜战锤，然后你才能学习制造铁肩铠。', '将4把青铜战斧和4把青铜战锤交给奥格瑞玛的奥罗克·沃姆什。', '你让奥罗克感到十分骄傲，$N。你可以开始学习铸造铁护肩了!', '向我展示你的技艺吧，$r。', '', '去找奥格瑞玛的奥罗克·沃姆什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2753, '踩在脚下', '奥罗克还剩两课要教给你，$N。我知道你的肌肉很疼，不过为了沃姆什系列，你还要继续！$B$B把四顶绿铁头盔、四个绿铁护腕和四个绿铁护腿拿来给奥罗克——你可以学到知识，你的敌人也会更加痛苦！', '将4顶绿铁头盔、4副绿铁护腕和4副绿铁护腿交给奥格瑞玛的奥罗克·沃姆什。', '你让奥罗克想起了爷爷，沃姆什的戈罗克酋长!现在你可以开始学习铸造铁靴了。', '敌人的头骨将碎裂在你的铁靴之下!', '', '去找奥格瑞玛的奥罗克·沃姆什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2754, '疯狂之角', '这是奥罗克教你的最后一课，$N。回到神圣的铁砧和锻炉旁去！将两只结实的铁锤、两双镀银青铜战靴和两副镀银青铜手套交给奥罗克。$B$B你会看到敌人眼中的恐惧！', '将2只结实的铁锤、2双镀银青铜战靴和2副镀银青铜手套交给奥格瑞玛的奥罗克·沃姆什。', '太惊人了!你已经掌握了沃姆什系列所有的技术了，$N!', '让这些铁器知道谁是真正的主宰，$N!', '', '去找奥格瑞玛的奥罗克·沃姆什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2756, '古老的技艺', '很久以前，阿图尔克可以碾碎敌人的徽记，将它们磨成粉做灯丝……很久以前，$r。现在酋长号召各部族和平相处。那些往日的敌人，现在我们只能用厌烦的眼光看着他们！$B$B我知道这很难以接受，不过这就是萨尔的意愿。$B$B实在是让我感到悲哀！你是来学习的，那你就学吧！给我拿四套钢质胸甲和四顶钢质头盔来，你可以在锻造它们的时候尝到战争的滋味！', '将4套钢质胸甲和4顶钢质头盔交给奥格瑞玛的铁砧阿图尔克。', '$N，看来你不过是大酋长手下又一个容易自足的家伙，太让人失望了。$B$B我多么希望能在战场上光荣地死去，可是现在我却得困在这里，听从萨尔的命令去训练新手!仔细看好了，孩子!', '阿图尔克就像时间一样不愿等待!蠢货，你还不快点!', '', '去奥格瑞玛找荣誉谷的铁砧阿图尔克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2757, '藏宝海湾之旅！', '听着，孩子，你在我这儿已经学不到什么东西了。$B$B我认识一个铁匠，他认识另一个优秀的铁匠……听起来有些混乱。你应该到藏宝海湾的铁匠铺去找他，只要你把这枚徽章交给他看看，他就会把有关秘银的知识都传授给你。$B$B怎么样？踏上真正的求知之旅吧，$n。$B$B如果你对此感兴趣的话，就去找马克迦文吧。别忘了给他看看这枚徽章。', '与藏宝海湾的马克迦文谈一谈。', '我们终于找到一个值得秘银会信任的$r了!', '你真是个与众不同的$r，伙计。让我看看那枚徽记。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2758, '锻造的本源', '我像你这么大的时候，在一个名叫加尔文的矮人门下学习了铸造护甲的技术。在他离开这里转至藏宝海湾之前，曾让我向他许诺，要帮助训练所有决心在锻造这门技艺上学有所成的人——于是这么多年来，我一直在这么做。$B$B现在是时候让你学点新东西了。给我打造六套金鳞护腕，你就会知道锻造的本源是什么了，$N。', '将6副金鳞护腕交给暴风城的巨锤汉克。', '很好，$N!用心听着!$B$B锻造的手艺绝不是起源于这里!<巨锤汉克指向他的铁锤。>$B$B锻造的手艺绝不是起源于这里!<巨锤汉克指向他的铁钻。>$B$B锻造的手艺只能起源于这里!<巨锤汉克指向自己的心。>$B$B现在你知道锻造的起源了吧。', '你能成为下一个被加尔文亲自训练的铁匠吗?', '', '去暴风城找矮人区的巨锤汉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2759, '寻找加尔文', '虽然加尔文很多年前就离开了藏宝海湾，但镇子里还有一个秘银会的成员，希望能找到另一个值得加尔文亲自授业的铁匠。$B$B把这个徽章交给藏宝海湾的马克迦文。$B$B我相信，如果你能见到加尔文的话，他一定会非常器重你的！', '与藏宝海湾的马克迦文谈一谈。', '多亏了黑蹄 - 终于，有一个值得加入秘银会的人了!', '你真是个与众不同的$r，朋友。让我看看那枚徽记。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2760, '秘银会', '我们招募的人几乎没有能平安抵达藏宝海湾的，$N。即使是意志最坚定的铁匠也难以抵挡这枚徽章的光芒，他们难免会产生私吞的贪念。他们都是傻瓜，因为与你即将得到的巨大财富相比，这枚徽章只是沧海一粟而已！$B$B去找到加尔文，把徽章交给他。他住在这里的北面，就在祖尔格拉布和莫什奥格食人魔山之间的地方。', '和荆棘谷的加尔文谈一谈。', '啊，很多年都没有看到一个值得秘银会启蒙的人了。我们现在就开始吧!', '嗨!走近点，让加尔文看看你拿的是什么。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2761, '铁匠必修课', '很多铁匠都以为采矿和锻造是两件完全独立的事情，不过锻造能离得开采矿吗？啊哈——那是不可能的！成功的铁匠还必须得是成功的矿工。$B$B让加尔文看看你的能力吧，$N。给我找40块铁锭和40块秘银锭来，然后加尔文就会教你打造精制密银短裤的方法！', '将40块秘银锭和40块铁锭交给荆棘谷的加尔文。', '你的工作态度完美无缺，$N!你已经开始理解加尔文的采矿哲学了!拿着这个，从中尽可能地学习\r\n更多的东西吧。', '采了这么一大堆矿之后，你感到肌肉肿胀，全身疼痛!', '', '去找荆棘谷的加尔文。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2762, '白花花的银子', '据说真银比秘银更坚固耐用，加尔文对这个说法没有什么异议，但是严格说起来，真银并不是真的！秘银比真银更加高贵！哈！不管怎么说，这一次，你要去收集一大堆银子来，$n。$B$B给我弄四十块秘银锭和五块真银锭来，作为交换，我会向你传授打造精制秘银手套的技艺，以及更为重要的，让你知道真银并不是真的！', '将40块秘银锭和5块真银锭交给荆棘谷的加尔文。', '她是个倔强的姑娘，不是吗，$N?当然，我是说真银。没错，加尔文在奥特兰克的山区里待了十多年才学到了这一点。拿着这个，从中学习你所能学到的一切!', '采了这么一大堆矿之后，你感到肌肉肿胀，全身疼痛!', '', '去找荆棘谷的加尔文。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2763, '灌魔工艺', '搜寻珍贵的宝石对我们来说是最重要的，$N。很少有比黄水晶更为珍贵的宝石。有了黄水晶，我们就能将注入各种装备中的魔法特性得到大幅度提升。$B$B这一课，我们要用四块黄水晶加强四十块秘银锭，这将使你更加了解神奇的宝石学，并学会如何制造精制秘银护肩。', '将40块秘银锭和4块黄水晶交给荆棘谷的加尔文。', '很少有人能不被那光芒四射的黄水晶所吸引，$N。没错，黄水晶是种非常华丽的宝石。$B$B好好留意这个发现能带给我们的益处!', '采了这么一大堆矿之后，你感到肌肉肿胀，全身疼痛!', '', '去找荆棘谷的加尔文。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2766, '寻找OOX-22/FE！', '你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然自动打开了，变成了一个看来是由侏儒制造的机器装置！一个奇怪的声音从这个蛋形机器装置中传了出来。$B$B“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它，我就会奖励你的！请把这个定向器带到那个母体机器人那里。别担心，我现在已经检测到了它的所在地！它现在就位于深痕谷中的一个山洞里！”', '把定位器带到深痕谷附近山洞中的奥格索普的导航机器人旁边。', '你把蛋形机器人交给你的定位器放到机器小鸡体内。$B$B里面传出了叽哩咕噜的声音，然后小鸡机器人慢慢地站了起来。当这个机器人能够移动之后，奥格索普的声音再次传了出来:$B$B“OOX-22/FE现在可以勉强运作了，但是它需要一次大检修!对你来说它太重了……但是我想到个好办法。你能不能再帮我看着它一会儿?”$B$B', '发现目标!你赫然看到石头上躺着一只……机器小鸡?!从机器小鸡中传出了声音:$B$B“太好了，你干得不错!这确实是我的母体，根据我的检测判断，它需要进行一定的启动动作才能够重新飞回藏宝海湾进行修理。请把定向器放到母体机器人里，剩下的它自己会去搞定!”', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2767, '拯救OOX-22/FE！', '那个侏儒的声音再次从那个机器人中传了出来：$B$B“我需要你帮忙把OOX-22/FE移动到一个安全的开阔地，这样它才可以启动起飞程序。它自带隐形系统，但是我需要一点时间来远程启动这个系统。请你把这个机器人从现在的位置护送到被遗忘的海岸去！那里是个非常理想的起飞点，有足够的空间作为机器人起飞的跑道！”$B$B“将它护送到那里，然后再到藏宝海湾来找我！奥格索普·奥布诺提斯——完毕！”', '安全护送OOX-22/FE到达目的地，然后向藏宝海湾的奥格索普·奥布诺提斯报告。', '哦，你是OOX-22/FE的伟大救世主!我简直无法用言语来表达对你的感谢!如果让我自己重新构造一个母体机器人的话，无疑要浪费大量的时间，你真是帮了我的大忙，不仅节约了我的时间，同时也节约了我的钱!$B$B请从这些东西中选择一样你中意的吧。再次感谢你无私的帮助，我的机器人和我都欠你的人情!', '没错，我就是奥格索普.奥布诺提斯，世上最强的发明家，随时为您效劳!现在，我能帮您什么忙吗?', '将OOX-22/FE安全护送到目的地。', '去荆棘谷找藏宝海湾的奥格索普·奥布诺提斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2768, '探水棒', '布莱中士偷了我的东西！他说只是借一下，但那混蛋却偷了我宝贵的探水棒！没有这根棒子，我就不知道该在哪里打井找水！$B$B去找到布莱，把我的探水棒拿回来！我听说他带着一帮恶名远扬的冒险者去了西边的祖尔法拉克古城寻宝，你肯定可以在那里找到他。$B$B但愿那里的巨魔已经把他干掉了，因为如果你必须打败他才能拿回探水棒的话，那必将是一场恶仗。', '把探水棒交给加基森的首席工程师沙克斯·比格维兹。', '你找到它了!太棒了，$N!你和他打了一架吗?我真希望你已经狠狠地教训了他和他的同伙一顿!', '你找到布莱中士了吗?找到我的探水棒了吗?', '', '去找塔纳利斯的首席工程师沙克斯·比格维兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2770, '加兹瑞拉', '在塔纳利斯沙漠的巨魔古城祖尔法拉克深处，有一个神圣的池塘。巨魔可以从那个池塘里召唤一头巨大的野兽——加兹瑞拉！它凶猛异常，甚至连它的鳞片都会因为巨大的能量而发出声响。我要用它的能量来给我的赛车增加动力！$B$B把加兹瑞拉的鳞片给我弄来！$B$B不过，召唤加兹瑞拉的方法是巨魔的秘密。如果你想要面对加兹瑞拉的话，首先就要从巨魔那里弄到召唤它的方法。', '把加兹瑞拉的鳞片交给闪光平原的维兹尔·铜栓。', '哇，你拿到鳞片了!谢谢你，$N。我现在就想用它试试!$B$B你看到加兹瑞拉了吗?它是不是像其它人说的那么大?', '你拿到鳞片了吗?我简直等不及要试试不同的驱动方式了!', '', '去千针石林找沙漠赛道的维兹尔·铜栓。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2771, '罩帽和护肩', '看来师傅一开始就计划好了。你学会制造的东西都是我不会的，而我学会的那些你也不会。$B$B师傅很聪明，$N。这样我们就可以互相学习了！$B$B你教我如何制造秘银罩帽和精制密银护肩，然后我再教你制造精制密银头盔，如何？', '将2顶秘银罩帽和1副精制秘银护肩带秘银护肩交给特伦顿·轻锤。', '非常出色!我可以这么说，做工很好。仔细看好了，$N!', '你打造出我要的那些东西了吗，$N?', '', '去找塔纳利斯的特伦顿·轻锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2772, '世界在你脚下', '在去年的全谷铁匠冠军赛里，我在众目睽睽之下被一个来自风险投资公司的卑鄙家伙用扫堂腿放倒在地。但是他们却不知道我为什么还能继续站在那里完成比赛，并取得冠军。答案就是——没错，精制秘银战靴！$B$B如果今年我还想取胜的话，就得学会精制秘银短裤的制作方法，因为这次会有一个风险投资公司的伐木工参加比赛！教我制作短裤，我就教你制作靴子，怎么样？', '将2双秘银重靴和1条精制秘银短裤交秘银短裤交给特伦顿·轻锤。', '整个世界都将在被你踩在脚下，$N!你的靴子将让你傲然挺立，而且再也不会被扫堂腿暗算啦!', '你打造出我要的那些东西了吗，$N?', '', '去找塔纳利斯的特伦顿·轻锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2773, '秘银小子', '我被大家称作秘银小子。我给来自世界各地的冒险者们提供精制秘银装备。$B$B<特伦顿悄悄地说。>$B$B但是没几个人知道我根本不会打造精制秘银手套。嘘！这是你我之间的小秘密。$B$B如果你教我如何打造精制秘银手套的话，我就把从加尔文那里学来的手艺传授给你——精制秘银胸甲的制作方法！', '将2件重型秘银胸甲和1副精制秘银手套带给特秘银手套交给特伦顿·轻锤。', '谢谢你所教我的一切，$N。你很快就能成为华丽秘银装备的大师了。$B$B仔细看着吧!', '你打造出我要的那些东西了吗，$N?', '', '去找塔纳利斯的特伦顿·轻锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2781, '通缉：卡利夫·斯科比斯汀', '通缉：卡利夫·斯科比斯汀！$B$B塔纳利斯的加基森水力公司愿支付高价悬赏废墟歹徒首领卡利夫·斯科比斯汀的徽记。他的罪行包括：$B$B1. 杀害加基森水力公司的雇员！$B2. 偷窃加基森水力公司的资源！$B3. 抢劫加基森水力公司的财产！$B$B将卡利夫·斯科比斯汀的死亡证明交给首席工程师沙克斯·比格维兹，我们将立刻兑现你的奖赏！', '将卡利夫·斯科比斯汀的徽记交给加基森的首席工程师沙克斯·比格维兹。', '正义终于得到了伸张!你重拳打击了可恶的游牧民!斯科比斯汀死了，我们现在只需把那些游牧民赶离加基森的水井就大功告成了!$B$B以加基森水力公司的名义，我很高兴将这笔奖金颁给你。你为我们作出了很大的贡献。', '没错，$C，我是加基森水力公司的官员。我能帮你什么忙吗?', '', '去塔纳利斯找加基森的首席工程师沙克斯·比格维兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2782, '林吉的秘密', '这块石板上布满了枯木巨魔的印记。林吉的秘密真是难以猜测……$B$B或许你手头上的东西非常宝贵。当然，这东西也很有可能一文不值。悲伤中的枯木巨魔为了摆脱困境什么事情都干得出来……', '奥兰·斯内克威瑟是个学者，她对枯木巨魔很有研究，也许她可以帮你看看这块石板。奥兰就住在幽暗城的魔法区里。', '这块石板……很不同寻常……你是在哪里找到它的，$N?', '好吧，这是什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2784, '失落的荣耀', '请听听我的故事，$r。', '聆听部落英雄的灵魂讲述他的故事。', '作为一个灵魂，我非常无力，$N，请帮帮我，让我重新获得我的荣耀。', '请听听我要说的故事。', '悲伤的故事', '去悲伤沼泽断矛路口找部落英雄的灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2801, '悲伤的故事', '请你一定要先听听我的故事。', '聆听部落英雄的灵魂讲述他的故事。', '$N，是行动的时候了。', '仔细听我讲述这段故事，$N。', '悲伤的故事', '去悲伤沼泽断矛路口找部落英雄的灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2821, '质量的保证', '我对于皮革制作的哲学是要做就做最好——没有商量馀地。任何说质量不要紧的人都是想要把丹莫罗的那些水货卖给你！$B$B在寻求高质量材料的过程中，我接触到了厚重的雪人皮。雪人是菲拉斯土生土长的一种生物，大多在深痕谷活动。我需要一些它们的皮，如果你给我十张的话，我可以让你在我的皮货中选一件。如果你觉得听起来还算公平，那我们就成交了吧。', '给羽月要塞的普拉特·马克格鲁比带去10张厚重的雪人皮。', '你有没有检查皮革的质地?处理得好的话，这些皮革会比铁还坚硬。没有几个人知道这种皮革的好处，我知道把它和大量处理液混合后就能制造出真正高品质的装备……当然，我要谢谢你!$B$B现在，请从这些皮货中任选一件吧!', '我说过，如果你给我十张厚重的雪人毛皮，我就让你在我的皮货中选一件。我一向以品质为重，我保证你得到的是好东西!$B$B如果你找不到雪人，那么我可以指点你一二，到被遗忘的海岸那边去，向内陆走，它们就在深痕谷附近。', '', '去菲拉斯找羽月要塞的普拉特·马克格鲁比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2822, '质量的保证', '我为自己制作的皮革作品感到骄傲，它们也值得我骄傲，质量是永不可能妥协的东西。任何说质量不要紧的人都是在信口乱说！$B$B在寻求高质量材料的过程中，我接触到了厚重的雪人皮。雪人是菲拉斯土生土长的一种生物，大多在深痕谷活动。我需要一些它们的皮，如果你给我十张的话，我可以让你在我的皮货中选一件。如果你觉得听起来还算公平，那我们就成交了吧。', '给莫沙彻营地的杉多尔·迅蹄带去十张厚重的雪人皮。', '啊，太好了!这些皮革如果经过特殊的处理就会像钢铁一样强韧!只有经过反复试验才能知道最佳的处理方法是什么，但我相信它们会使我的皮革制品的品质更上一层楼。$B$B至于你，$N……你对我的帮助绝对是无价的。请从我的手艺中随便选一件吧。', '你能弄到十张厚重的雪人毛皮吗?我的皮货是无与伦比的，如果你有这种皮革的话，我就给你制作一件样品。$B$B如果你找不到那些雪人，我可以给你一些指点。从这里往西，它们就在被遗忘的海岸里，靠近深痕谷的地方。', '', '去菲拉斯找莫沙彻营地的杉多尔·迅蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2841, '设备之战', '侏儒的技术——两年前它最普遍的用途是被当作笑话，但是时代确实变了，现在他们建造的新型钻探设备比我们所有伐木机加起来都要精密。我需要它的设计图，$N！$B$B不幸的是，这些设计图被锁在麦克尼尔·瑟玛普拉格身边的一只保险箱里了。更糟的是，保险箱的密码只有麦克尼尔·瑟玛普拉格一人知道。$B$B尽你所能得到那个密码，$N。把设计图给我带回来！', '从诺莫瑞根拿到钻探设备蓝图和麦克尼尔的保险箱密码，把它们交给奥格瑞玛的诺格。', '我知道你可以的，$N!另一方面，索维克也有自己的疑虑。$B$B<诺格清了清嗓子。>$B$B既然现在我们手里有了蓝图，那么我们早晚可以弄明白地精的钻探设备有何革新之处，然后将它们用于我们自己的伐木机。', '我没有看到任何蓝图，你是不是把它放在你身上的某个地方了，或者你根本就是想站在这里烦死我?', '', '去找奥格瑞玛的诺格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2843, '出发！诺莫瑞根！', '只要你有传送器，你所要做的就只是踩上踏板，然后就会被传送到诺莫瑞根！$B$B你可能会有一些不适感，但这些副作用应该都不是永久的……$B$B我几乎忘了最重要的部分——如何回来。当你准备好要回来时，只要在诺莫瑞根踩上传送器的踏板就行了！$B$B现在请把传送器按照你的体型和体重做一些调整。', '等斯库提调整好地精传送器。', '一切就绪!准备好了以后就踩上踏板吧。', '准备就绪!', '地精传送器', '去荆棘谷找藏宝海湾的斯库提。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2845, '迷路的沙恩', '你能带我回到我的朋友罗克比特身边吗？他本来是要照看我的……但我总是不知不觉之间就迷路了。这里有这么多好看的东西，我东看看西看看就不知道该怎么走了。$B$B但是有一样东西可以一直吸引我的注意力。$B$B在这个箱子里有一只对我来说最为珍贵的铃铛，我就喜欢听它的声音。我保证，如果我走失了，只要你摇响铃铛，我就会马上跑回来。', '从箱子里拿取沙恩的铃铛，然后护送沙恩·飘叶回到罗克比特的营地。', '什么?这个铃铛有这种妙用?太好了!$B$B太感谢你了，$N。', '我正在担心你呢!谢谢你带沙恩回来，$N。', '带沙恩·飘叶回到罗克比特的营地', '去菲拉斯找双塔山的罗克比特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2846, '深渊皇冠', '很久以前我曾经拥有一件美丽的珍宝，深渊皇冠。它不仅美丽——而且它对于知道怎么使用它的人来说更是一件拥有巨大力量的宝贝。$B$B所以当水占师维蕾萨听说皇冠的事情之后，她就发誓要得到它。维蕾萨派人在我外出的时候到我家来偷走了皇冠，这些卑鄙的小偷！$B$B我要取回我的皇冠！到位于塔纳利斯沙\r\n漠中的巨魔城市祖尔法拉克去，把皇冠从她手上抢回来。把它还给我，你会得到报酬的。', '将深渊皇冠交给尘泥沼泽的塔贝萨。', '太好了!你找到它了!最为重要的是―维蕾萨不再拥有它!谢谢你，$N。我永远欠你的人情!$B$B如果我过去说话听起来有点……令人不舒服，别放在心上。你会发现我对没有从我这里偷东西的人其实是非常友善的。', '你取得了那个冠冕吗，$N?维蕾萨有没有付出代价?', '', '去尘泥沼泽找塔贝萨的农场的塔贝萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2847, '蛮皮护甲', '$n，你已经是个很熟练的制皮匠了！我知道一些装备的制作方法，你可能会感兴趣……那就是蛮皮护甲！蛮皮中包含了野葡萄的混乱而强大的力量，你可以在这片茂盛的森林中找到这种植物，也可以在森林中的某些动物身上找到。用它制作的装备简直是无以伦比！$B$B我会把制作蛮皮护甲的方法教给你，条件是你要为我做点事情。首先你得给我带十块厚皮来，等你拿来十块厚皮之后我们再详谈。', '给羽月要塞的普拉特·马克格鲁比带去10块厚皮。', '好吧，$N，我很高兴你能当我的学徒。你做出了一个明智的选择。当你掌握制作蛮皮护甲的秘诀之后，那些使用皮质装备的买主就会蜂拥而至。$B$B让我们开始吧―你想从哪部分开始?', '就像我说过的那样，你要想学会制作蛮皮护甲，就得先替我工作。野葡萄是强大而又混乱的，它可以在原本已经非常强大的护甲上加上随机的魔法属性，但是我发现这一点可是花了很长时间的。$B$B这一过程的最初阶段的花费是十块厚皮。$B$B当你得到十块厚皮之后，我们再继续进行下一步工作，给你护甲的图样。', '', '去菲拉斯找羽月要塞的普拉特·马克格鲁比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2848, '蛮皮护肩', '蛮皮护肩能够很好地支撑穿戴者的身形，为其上臂和肩部提供了极好的保护。和所有的蛮皮护甲一样，制作时所使用的野葡萄会使其附带一种强大的随机魔法效果。$B$B如果你想要这种护甲的图样，就给我弄六块厚重护甲片和一株野葡萄来，这对你来说应该不算什么过分的要求。', '给羽月要塞的普拉特·马克格鲁带去6片厚重护甲片和1株野葡萄。', '这些护甲片的品质很不错，$N。无论是对于我自己还是我的雇工，我对品质的要求都很高。$B$B你做得很好，理应获得这个图样，我希望它给你带来荣誉和财富，就像它曾经给我带来的那样。', '你弄到我要的六块厚重护甲片和一株野葡萄了吗?$B$B不要以为制作护甲片是一种简单的体力活儿，当你制作护甲片的时候，你也在不断提高自己在装饰方面的技能，这种训练对于提高制作精细装备的技巧也有很大的帮助。$B$B看到了吧―其实这才是我让你给我带六块护甲片来的真正原因……', '', '去菲拉斯找羽月要塞的普拉特·马克格鲁比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2849, '蛮皮外衣', '蛮皮外衣是蛮皮护甲中最主要的部分，它的结构以及编织于其中的野葡萄能使其在具有很强的保护作用的同时，还附带着强大的魔法力量。$B$BB如果你想要这种护甲的图样，就给我弄两件龟鳞胸甲、两副龟鳞手套和一株野葡萄来。这不是件容易的活儿，但你一定可以完成它。', '给羽月要塞的普拉特·马克格鲁带去2件龟鳞胸甲、2副龟鳞手套和1株野葡萄。', '这几件装备都很不错，$N。你在这些装备上所注入的工艺和耐心让我看到你已经决心选择全身心地投入这个任务之中了。$B$B你已经达到了我的要求，这是给你的奖赏。制作蛮皮外衣的秘诀现在就是你的了!', '你弄到两件龟鳞外衣和两副龟鳞手套了吗?还有别忘了野葡萄!$B$B即使是最基本的图样，其基础造型也可以被转化运用到更多更复杂的装备制作工艺中。通过制作龟鳞外衣，你应该已经掌握了制作蛮皮外衣的基本要领。$B$B还有手套……好了，你要为我带来这些东西。记住，你是在为我工作!', '', '去菲拉斯找羽月要塞的普拉特·马克格鲁比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2850, '蛮皮头盔', '蛮皮头盔可以为你的头部提供极好的保护，与此同时，它也具有相当的舒适性。和所有的蛮皮护甲一样，制作头盔时使用的野葡萄会使它产生一种强大的随机魔法效果。对于穿着皮甲的人来说，这东西可是非常不错的！$B$B想要得到这顶头盔的图样的话，就给我带两件夜色外套、两条夜色头巾和一株野葡萄来。完成这个任务之后，图样就是你的了！', '给羽月要塞的普拉特·马克格鲁比带去2件夜色外套、2条夜色头巾和一株野葡萄。', '你提供的装备完美地符合我的要求，$N。我就是需要像你这样有才干的制皮师。$B$B你靠自己的能力赢得了蛮皮头盔的制作方法。现在我将这个图样送给你，希望你能从中受益。', '我需要那些外套和头罩，另外还需要一株野葡萄，然后我就会把蛮皮盔帽的制作方法告诉你。$B$B防护头部的装备是冒险者们垂涎已久的，无论是简单的头带还是一顶密闭的盔帽，无论其外观如何，制造有价值的头部装备的道理是恒久不变的。', '', '去菲拉斯找羽月要塞的普拉特·马克格鲁比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2851, '蛮皮战靴', '你现在已经学到了很多东西，$n，但你仍有更多的东西要学习。现在我们来谈谈蛮皮战靴，它是这一套装备的基石。$B$B这种靴子舒适合脚，可以让你的双脚在长途跋涉之后仍然轻松自如。柔软的鞋底对于那些喜欢悄悄行动的人来说再合适不过了。$B$B如果你想要得到它的图样，就给我拿两条夜色短裤和两双夜色长靴来。另外我还需要两株野葡萄……只有一株的话可不够。拿到以上这些东西之后，就把它们交给我。', '给羽月要塞的普拉特·马克格鲁带去2条夜色裤、2双夜色靴和2株野葡萄。', '你以专业的水准又一次完成了这个复杂的任务。你理应获得这个图样，还有我对你的感谢。', '在你学习这个图样以前，你必须完成裤子、靴子和野葡萄的订单，$N。你找到这些东西了吗?$B$B从我们学会制作第一双靴子起，我们便开始懂得如何掌握靴子的舒适性与功能性之间的尺度。只有兼顾两样，我们才能够制造出令穿着者忘记疲劳的靴子，我们的靴子绝对会让那些劣质的同类产品无地自容。', '', '去菲拉斯找羽月要塞的普拉特·马克格鲁比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2852, '蛮皮护腿', '基础教程已经完成，你应做好准备掌握更为复杂的制作了，$n。蛮皮护胫是最坚硬和强大的皮制系列装备中的一样。野兽系列皮装备让你的胸部，大腿，小腿和其它致命的部位都被保护起来。再加上野葡萄所起的辅助作用，拥有这种装备的冒险者一定会永远感谢你的。$B$B如果你想要得到这个图样的话，带给我两顶龟鳞头盔，两付龟鳞护腕和两株野葡萄。', '给羽月要塞的普拉特·马克格鲁比带去2顶龟鳞头盔、2副龟鳞护腕和2株野葡萄。', '你又一次完美地完成了我交给你的任务。也许有一天，我会要向你学些什么东西，不是吗，$N?$B$B这是给你的护腿图样，另外我还要对你表示感谢。学会这个图样，让你高超的技艺体现在你制作出的装备中吧!', '你弄到龟鳞头盔和护腕了吗?另外不要忘记我还要两株野葡萄。$B$B现在，你已经开始意识到蛮皮护胫潜在的能量了。一件拥有无穷应用潜力的护甲对于一个皮革匠来说是无价的，唯一的瓶颈是制作这些护甲所需要的原料―而不是成品的品质!', '', '去菲拉斯找羽月要塞的普拉特·马克格鲁比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2853, '蛮皮护甲大师', '好吧，$n，你就是勤奋的楷模。蛮皮护甲只剩下一种式样你还没有学会了。我不会要求你为最后的式样无谓地浪费时间和精力，你可以直接得到它，还有一些……但我不能自己传授给你。我的老师，就是带我进入这一行的人，他会教你怎么做。$B$B把这封信交给泰龙尼斯，他在达纳苏斯教授皮革制作的工艺。给他看这封信，让他像我一样认同你。', '将普拉特的信交给达纳苏斯的制皮大师泰龙尼斯。', '啊，原来是普拉特让你来的。虽然他是人类，但他有时令我想起了夜精灵。他对于制皮业的贡献和才能给我留下了很深刻的印象。他在信中如此称赞你，在我看来这是一种尊重的体现。$B$B我知道他已经教会了你制作蛮皮护甲的方法，接下来就让我把最后一款蛮皮护甲的制作方法传授给你吧。你要好好珍惜你获得的知识，这个世界上没有几个人知道蛮皮披风的秘密。', '你好，$C……我一眼就看出你和我一样是制皮师。你是来向我学手艺的吗?又或者是你想和我做生意?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2854, '蛮皮护甲', '$n，你已经是个很熟练的制皮匠了！我知道一些装备的制作方法，你可能会感兴趣……那就是蛮皮护甲！蛮皮中包含了野葡萄的混乱而强大的力量，你可以在这片茂盛的森林中找到这种植物，也可以在森林中的某些动物身上找到。用它制作的装备简直是无以伦比！$B$B我会把制作蛮皮护甲的方法教给你，条件是你要为我做点事情。首先你得给我带十块厚皮来，等你拿来十块厚皮之后我们再详谈。', '给莫沙彻营地的杉多尔·迅蹄带去10块厚皮。', '好吧，$N，我很高兴你能当我的学徒。你做出了一个明智的选择。当你掌握制作蛮皮护甲的秘诀之后，那些使用皮质装备的买主就会蜂拥而至。$B$B让我们开始吧―你想从哪部分开始?', '就像我说过的那样，你要想学会制作蛮皮护甲，就得做我的学徒。野葡萄是强大而又混乱的，它可以在原本已经非常强大的护甲上加上随机的魔法属性，但是我发现这一点可是花了很长时间的。$B$B这一过程的最初阶段的花费是十块厚皮。$B$B当你得到十块厚皮之后，我们再继续进行下一步工作，给你护甲的图样。', '', '去找菲拉斯的杉多尔·迅蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2855, '蛮皮护肩', '蛮皮护肩能够很好地支撑穿戴者的身形，为其上臂和肩部提供了极好的保护。和所有的蛮皮护甲一样，制作时所使用的野葡萄会使其附带一种强大的随机魔法效果。$B$B如果你想要这种护甲的图样，就给我弄六块厚重护甲片和一株野葡萄来，这对你来说应该不算什么过分的要求。', '给莫沙彻营地的杉多尔·迅蹄带去6块厚重护甲片和1株野葡萄。', '这些护甲片的品质很不错，$N。无论是对于我自己还是我的学徒，我对品质的要求都很高。$B$B你做得很好，理应获得这个图样，我希望它给你带来荣誉和财富，就像它曾经给我带来的那样。', '你弄到我要的六块厚重护甲片和一株野葡萄了吗?$B$B不要以为制作护甲片是一种简单的体力活儿，当你制作护甲片的时候，你也在不断提高自己在装饰方面的技能，这种训练对于提高制作精细装备的技巧也有很大的帮助。$B$B我让你做的每一件事情都是有我的理由的。', '', '去找菲拉斯的杉多尔·迅蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2856, '蛮皮外衣', '蛮皮外衣是蛮皮护甲中最主要的部分，它的结构以及编织于其中的野葡萄能使其在具有很强的保护作用的同时，还附带着强大的魔法力量。$B$BB如果你想要这种护甲的图样，就给我弄两件龟鳞胸甲、两副龟鳞手套和一株野葡萄来。这不是件容易的活儿，但你一定可以完成它。', '给莫沙彻营地的杉多尔·迅蹄带去2件龟鳞胸甲、2副龟鳞手套和1株野葡萄。', '这几件装备都很不错，$N。你在这些装备上所注入的工艺和耐心让我看到你已经决心选择全身心地投入这个任务之中了。$B$B你已经达到了我的要求，这是给你的奖赏。制作蛮皮外衣的秘诀现在就是你的了!', '你弄到两件龟鳞外衣和两副龟鳞手套了吗?还有别忘了野葡萄!$B$B即使是最基本的图样，其基础造型也可以被转化运用到更多更复杂的装备制作工艺中。通过制作龟鳞外衣，你应该已经掌握了制作蛮皮外衣的基本要领。$B$B当你逐渐熟练了之后，你的手艺就会如艺术一般完美。', '', '去找菲拉斯的杉多尔·迅蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2857, '蛮皮头盔', '蛮皮头盔可以为你的头部提供极好的保护，与此同时，它也具有相当的舒适性。和所有的蛮皮护甲一样，制作头盔时使用的野葡萄会使它产生一种强大的随机魔法效果。对于穿着皮甲的人来说，这东西可是非常不错的！$B$B想要得到这顶头盔的图样的话，就给我带两件夜色外套、两条夜色头巾和一株野葡萄来。完成这个任务之后，图样就是你的了！', '给莫沙彻营地的杉多尔·迅蹄带去2件夜色外套、2条夜色头巾和1株野葡萄。', '你提供的装备完美地符合我的要求，$N。我就是需要像你这样有才干的制皮师。$B$B你靠自己的能力赢得了蛮皮盔帽的制作方法。现在我将这个图样送给你，希望你能从中受益。', '我需要那些外套和头罩，另外还需要一株野葡萄，然后我就会把蛮皮盔帽的制作方法告诉你。$B$B防护头部的装备是冒险者们垂涎已久的，无论是简单的头带还是一顶密闭的盔帽，无论其外观如何，制造有价值的头部装备的道理是恒久不变的。', '', '去找菲拉斯的杉多尔·迅蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2858, '蛮皮战靴', '你现在已经学到了很多东西，$n，但你仍有更多的东西要学习。现在我们来谈谈蛮皮战靴，它是这一套装备的基石。$B$B这种靴子舒适合脚，可以让你的双脚在长途跋涉之后仍然轻松自如。柔软的鞋底对于那些喜欢悄悄行动的人来说再合适不过了。$B$B如果你想要得到它的图样，就给我拿两条夜色短裤和两双夜色长靴来。另外我还需要两株野葡萄……只有一株的话可不够。拿到以上这些东西之后，就把它们交给我。', '给莫沙彻营地的杉多尔·迅蹄带去2条夜色短裤、2双夜色长靴和2株野葡萄。', '你以专业的水准又一次完成了这个复杂的任务。你理应获得这个图样，还有我对你的祝贺。', '在你学习这个图样以前，你必须把裤子、靴子和野葡萄给我拿来，$N。你找到这些东西了吗?$B$B从我们学会制作第一双靴子起，我们便开始懂得如何掌握靴子的舒适性与功能性之间的尺度。只有兼顾两样，我们才能够制造出令穿着者忘记疲劳的靴子，我们的靴子绝对会让那些劣质的同类产品无地自容。', '', '去找菲拉斯的杉多尔·迅蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2859, '蛮皮护腿', '看来你已经准备好学习更加复杂的课程了，$N。蛮皮护胫是最坚硬和强大的皮制系列装备中的一样。野兽系列皮装备让你的胸部，大腿，小腿和其它致命的部位都被保护起来。再加上野葡萄所起的辅助作用，拥有这种装备的冒险者一定会永远感谢你的。$B$B如果你想要得到这个图样的话，带给我两顶龟鳞头盔，两付龟鳞护腕和两株野葡萄。', '给莫沙彻营地的杉多尔·迅蹄带去2顶龟鳞头盔、2副龟鳞护腕和2株野葡萄。', '你又一次完美地完成了我交给你的任务。也许有一天，我会要向你学些什么东西，不是吗，$N?$B$B这是给你的护腿图样，另外我还要对你表示感谢。学会这个图样，让你高超的技艺体现在你制作出的装备中吧!', '你弄到龟鳞头盔和护腕了吗?另外不要忘记我还要两株野葡萄。$B$B现在，你已经开始意识到蛮皮护胫潜在的能量了。一件拥有无穷应用潜力的护甲对于一个皮革匠来说是无价的，唯一的瓶颈是制作这些护甲所需要的原料―而不是成品的品质!', '', '去找菲拉斯的杉多尔·迅蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2860, '蛮皮护甲大师', '$n，我能教你的你已经全部都学会了。蛮皮护甲只剩下一种式样你还没有学会了。我不会要求你为最后的式样无谓地浪费时间和精力，你可以直接得到它，还有一些……但我不能自己传授给你。我的老师，就是带我进入这一行的人，她会教你该怎么做的。$B$B带这封信给犹纳；她在雷霆崖教授皮革制作。给她看这封信，让她像我一样地认同你。', '将杉多尔的信交给雷霆崖的制皮大师犹纳。', '啊，好啊，杉多尔派你来的。我很高兴我最好的学徒之一也有自己的学徒了。$B$B他对于皮革的贡献和才能给我留下了很深刻的印象。他在信中如此称赞你，在我看来这是一种尊重的体现。$B$B我知道他已经教会了你制作蛮皮护甲的方法，接下来就让我把最后一款蛮皮护甲的制作方法传授给你吧。你要好好珍惜你获得的知识，这个世界上没有几个人知道蛮皮披风的秘密。', '你好，$C……我一眼就看出你和我一样是制皮师。你是来向我学手艺的吗?又或者是你想和我做生意?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2862, '与豺狼人开战', '豺狼人……它们现在不再只是一个小麻烦了，它们已经对我们形成了巨大的威胁！这些豺狼人是不是菲拉斯的原住民已经不重要了；如果我们无法有效地对抗它们，那我们早晚都会被赶出这个地区的。$B$B豺狼人最近对营地的攻势愈演愈烈，因此我们需要你的帮助来削弱它们的数量。带给我十份豺狼人的鬃毛，我会为你付出的努力而给予优厚的报酬。$B$B赶快出发吧！', '将10份木爪豺狼人的鬃毛交给莫沙彻营地的哈杜肯·迅蹄。', '这象征着一个好的开始，$N。你的士兵技巧值得赞扬。$B$B你并不是我唯一指派这个任务的人。在你之前曾有许多人与他们战斗，一直把它们阻挡在海湾边。但是最近，他们尝试向北突进我们的地区，而且影响已愈演愈烈。他们的攻势也变的更野蛮……几乎是拼了命一样。$B$B不过我有一个计画，$N，也许这个计画能让我们一劳永逸……', '我们把那些豺狼人都击退了，但是它们仍然在坚持进攻!一定是有什么人或什么东西让它们变得如此疯狂……哦，你回来了，任务完成了吗，$N?你拿到我要的鬃毛了吗?', '', '去菲拉斯找莫沙彻营地的哈杜肯·迅蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2863, '突然袭击', '我们计划在很短的时间里拿下豺狼人的领导者——按他们自己的说法是突击队员。如果我们顺利地执行了这个计划……不仅他们的内部会出现混乱，而且这也会向他们愚蠢的脑袋传达一个信息，那就是我们有能力而且必将消灭他们！$B$B我想让你成为传达这个信息的使者，你必须在一小时内消灭五个突击队员，否则我们还会处于这种僵局中。', '在1个小时内杀死5个木爪突击队员，并向哈杜肯·迅蹄汇报。', '你完成了我吩咐的任务，因此我向你表示敬意。拿着这个小奖励吧，$N。$B$B豺狼人的突击队员被杀死了，接下来他们会对突袭营地的计画考虑再三。但这并不意味着我们手头的事情已经结束了……$B$B豺狼人变得如此疯狂，这其中必有蹊跷。我想在他们有机会重新集结之前找到原因。', '时间宝贵，$N!如果你来这里不是要向我报捷的话，那么你就是在浪费时间!', '', '去菲拉斯找莫沙彻营地的哈杜肯·迅蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2865, '圣甲虫的壳', '塔纳利斯这里的圣甲虫的壳都很硬！硬得足可以给好多东西当建筑材料，好多东西！$B$B事实上，因为那些壳都太有用了……圣甲虫已经被猎杀得近乎灭绝了！$B$B我知道哪里有更多的圣甲虫，如果你保证会给我弄些壳来，我就告诉你它们在哪里。你保证吗？$B$B好吧，祖尔法拉克里面有许多圣甲虫，我想巨魔们并不因为想要那些壳而猎杀它们。$B$B但你可以！到祖尔法拉克去给我弄些完好无损的壳回来！', '给加基森的特兰雷克带去5个完整的圣甲虫壳。', '哦，太好了!你拿到壳了!$B$B谢谢你，$N。你真是我的救命恩人!', '你弄到壳了吗?我那藏宝海湾的堂兄在等着我给他寄去一大批壳哪，他已经等得不耐烦了!', '', '去找塔纳利斯的特兰雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2869, '憎世纳迦之战', '我们认为，无论纳迦想要干什么，他们最终的目的无非是完全占据这座岛屿，由此我们制定了相应的行动计划。我们要尽早采取攻击行动来消除这种威胁，否则就可能全盘皆输。$B$B给我带来十块完整的憎世纳迦的鳞片——你应该知道如何获得这东西。这样一来，纳迦在萨尔多岛上的力量就被大大削弱了，这对我们是非常有利的。', '收集10块憎世纳迦的鳞片，把它们交给羽月要塞的拉托尼库斯·月矛。', '嗯，这些鳞片很令人满意。我会把它们直接送给普拉特，让他看看，或许他能用它们制造出一些有用的东西。$B$B至于你，我还想给你指派另一个任务。不过我要先奖励你，你为将军和整个羽月要塞提供的帮助对我们来说是非常有价值的。', '$N，如果你来这里是来核实我交给你的任务，那么，很好―我要的是十块憎世纳迦的鳞片。如果你来这里是为了闲聊，那么现在我没空和你多罗嗦。$B$B要知道，我们夜精灵不是好战分子，我们致力于维护和平与安宁，但这并不代表我们会放弃维护自己的利益。这是我对羽月将军和这座要塞应尽的职责。', '', '去菲拉斯找羽月要塞的拉托尼库斯·月矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2870, '击败沙尔扎鲁', '$n，新的侦查报告让我们对纳迦部队的组成有了一个更清晰的概念。纳迦的皇室成员在他们的部队中具有最高的权威性。$B$B皇室成员中的沙尔扎鲁是个极端残酷的纳迦，侦查报告表明最近他在南部的遗迹中发现了一块奇怪的古代遗物，那个地方就在恐怖之岛那里。$B$B你的任务就是结果他，然后把那块遗物给我带回来进行研究。', '消灭沙尔扎鲁，然后把神秘遗物交给羽月要塞的拉托尼库斯·月矛。', '干得好，$N!沙尔札鲁领主的死能让那些纳迦在短期内变得像无头苍蝇一样，他们现在所能造成的威胁已经基本在我们能控制的范围内了。$B$B这是取自要塞库藏的奖金―这些都是你自己赚来的。你在羽月要塞将永远受到我们的欢迎，我的朋友。$B$B在你离开之前，我还有一件事情想要请你帮忙……', '除掉沙尔札鲁领主必定能让他们的计画拖延至少数个星期。除此之外，那块圣物也让我们非常感兴趣。$B$B$N，你完成任务了吗?', '', '去菲拉斯找羽月要塞的拉托尼库斯·月矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2871, '递送遗物', '如果你能帮我将这个东西送给我的妻子维斯提亚，那我会非常感激的。她不仅是我们这里的女祭司，也会是你所见过的最博学的学者之一。我即使抓破头皮也搞不清楚这个东西到底是什么，可我的妻子不同，如果世界上有人能知道这东西是什么，那无疑就是她了……我们也迫切地需要知道真相！$B$B拜托了，$n。', '将神秘遗物交给羽月要塞的维斯提亚·月矛。', '真有趣……你说这来自索兰萨尔废墟?好，拉托说得对，我得看一下。它不像是属于那个废墟的东西，好像也不是纳迦的设计……太奇怪了。$B$B我要花点时间研究这东西。当我结束对它的研究时，或许你也可以帮忙进行后续的工作。$B$B来，从这些东西里挑一件吧，我希望它们对你有用!', '嗯，我能帮你什么忙吗?$B$B等等，你是协助羽月将军和拉托对付纳迦的$C，对吗?我是维斯提亚，拉托―嗯，或许叫拉托尼库斯更合适些，我是他的妻子。很高兴见到你!$B$B对不起，你是有什么东西要交给我的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2873, '斯杜雷的货物', '我欠藏宝海湾的“海狼”马克基雷一些朗姆酒，那是打赌输的，但我现在一瓶朗姆酒都没有了！科尔戈船长偷了我最后一船货，他把它们藏在南边的那个戒备森严的海盗镇里。$B$B如果你能找到我的那批朗姆酒并把它们给我拿回来的话，那我就可以向马克基雷证明，藏宝海湾的那些酒跟我的朗姆酒比起来只能被称作垃圾！', '将斯杜雷的货物交给热砂港的斯杜雷。', '太好了，谢谢你替我找到了这批货。现在我终于可以偿还麦克基雷的赌注了。', '你有没有找到我的那批朗姆酒，$N?', '', '去塔纳利斯找热砂港的斯杜雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2874, '给马克基雷的货物', '再次感谢你的帮助，$N。这里有一瓶热砂港朗姆酒。把它交给马克基雷，这样他就可以抛弃藏宝海湾烈酒，改喝热砂港朗姆酒了！', '将斯杜雷的瓶子交给藏宝海湾的“海狼”马克基雷。', '嗯，让我尝尝……$B$B真不敢相信!这东西……太妙了!棒极了!$B$B好吧，我想斯杜雷可以留着他欠我的钱了。他对于热砂港朗姆酒的描述一点也不夸张。这东西的口感和沙粒一样厚实，而性子却烈得像岩浆一样!', '斯杜雷有没有交出我要的那瓶酒?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2875, '通缉：安德雷·费尔比德', '可恶的海盗安德雷·费尔比德因对热砂港和加基森所犯的罪行正被通缉。$B$B根据政府讨论所发布的决议，任何阅读这则通缉令的人有权在逮捕安德雷和他的同党过程中采取可能致其死亡的手段。$B$B进一步的决议表明，如在审讯期间，安德雷死了或病了，他的徽记可以作为代替品，将它交给安全主管吉罗姆·比格维兹仍将使这份通缉令生效。', '将安德雷的徽记交给热砂港的安全主管吉罗姆·比格维兹。', '啊，安德雷的脑袋。我早就知道他会被审判的!$B$B非常感谢你，$N。现在，如果你在这里签个字，我就可以为你支付报酬。$B$B别担心字体太小的问题。这里面没有对你不利的条款，而且……我不认为有什么放大镜可以帮助你阅读这些字。', '你看起来有些神情恍惚，是不是刚刚看过我们的法律文件?', '', '去塔纳利斯找热砂港的安全主管吉罗姆·比格维兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2876, '船运时刻表', '这卷轴上面记载着热砂港和藏宝湾之间的船运时刻表，包括过去和未来计划中的船运批次和船名，一些船的旅程旁有个大大的红叉记号，剩下的旁边有类似“华丽的战利品”和“坚固的战舰”之类的字样。$B$B热砂港那里的人一定非常想看看这个文件。', '把船运时刻表交给热砂港的某个官员。', '哦，我的天哪，这好像是所有货船到港和离港的记录，上面有精确的日期、时间和其它一切资讯!如果哪个海贼船长弄到了这个，那他可就发大财了!$B$B呃，你说你是从海贼那里得到这个的?这……$B$B谢谢你，$N。我很高兴你能把这个东西夺过来，也很高兴得知那个海贼现在已经被干掉了!', '你看起来上气不接下气的，有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2877, '清理隐匿石', '比起那些铁炉堡的兄弟们来，我们蛮锤部族对于过去曾发生过的事情有着更加深刻的记忆。如果你想在这里交朋友的话，那么你就要证明给我们看！$B$B部落的蛮子们从隐匿石一带撤了出去，现在那里满地都是淤泥怪。我们想要占领那个地区，不过首先我们要找些人来帮我们清理一下恼人的淤泥怪。$B$B这就是你要做的事情了！到那边去干掉十个绿色淤泥怪和十个玉石软泥怪，然后回到这里来向我报告。快出发吧!', '杀掉10个绿色淤泥怪和10个玉石软泥怪，然后回到鹰巢山向弗拉加尔报告。', '非常好，你为蛮锤部族做出了巨大的贡献!你是一个大有前途的$C，我们尊重你这样的$r。$B$B你的清理任务远比你想象中的要重要，随着软泥怪数量的减少，我们马上就能进一步扩大影响力了。好了，接下来―除了在鹰巢山这里交朋友之外，你暂时没什么事可以做了!', '别想逃避你肩上的任务，$C!如果神灵想要让那些软泥怪去死，他们早就自己动手了，难道不是吗?!', '', '去辛特兰找鹰巢山的弗拉加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2878, '被腐化的轻歌花', '', '', '你将一些塞纳里奥植物药膏涂在了这株轻歌花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的轻歌花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2879, '艾奎尼克斯法杖', '看来这根法杖可能就是艾奎尼克斯法杖了。它事实上是把钥匙，你可以用它打开位于北方废墟中的艾奎尼克斯石碑。$B$B找到仍在那片废墟中燃烧的四团烈火：萨姆哈之焰、拜尔坦之焰、伊姆贝尔之焰和莱哈萨之焰。从这些火焰那里采集它们的精华。然后在艾奎尼克斯石碑旁使用这些精华，把它们的能量注入法杖。如果这真的是艾奎尼克斯法杖的话，你就可以打开石碑，并得到存放在里面的古物。', '给特洛亚斯的法杖注入能量，并找到艾奎尼克斯石碑。', '这把充满能量的法杖几乎让人快握不住了。它的能量流窜于你的体内。$B$B你伸手去触碰艾奎尼克斯石碑的冰冷表面……$B$B一扇小门应声而开，使你得以把法杖带入其中。$B$B艾奎尼克斯石碑周围的区域发出了耀眼的光芒。', '艾奎尼克斯石碑静静地立在废墟中。它到底蕴藏着什么秘密呢?', '', '去菲拉斯找双塔山的艾奎尼克斯石碑。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2880, '巨魔部族项链', '直接说吧，$c——我们不属于联盟！蛮锤部族是独立的，我们依靠自己所做的事情来证明自己的价值，不像那些只会说废话的家伙一样，用闲聊来掩饰自己什么都不想做的态度！$B$B如果你要和我们作朋友，那么首先向我们证明你的价值！那些遍布辛特兰的巨魔有时会带着他们部族的项链。给我带五条项链过来作为友好的证明吧！', '给鹰巢山的弗拉加尔带去5条巨魔部族项链。', '这正是我提到的东西!看―这些项炼证明了你的价值，我们蛮锤部族珍惜我们的朋友。$B$B继续好好干吧，你会受我们的青睐的。', '我想要那些巨魔身上的部族项炼。如果你想得到它的话，那就把你所看到的巨魔都干掉吧!$B$B向蛮锤部族证明你的价值!', '', '去辛特兰找鹰巢山的弗拉加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2881, '巨魔部族项链', '', '', '你又给我带来一套项炼，这说明辛特兰的巨魔数量又少了一些!干得好，$N!', '你已经完成了我交给你的任务，但我们会继续接受你拿来的任何巨魔部族项炼。你把它们交给我，你在蛮锤部族中的地位就会继续提高;如果你愿意为我们战斗，那么我们也愿意为你战斗!$B$B我需要五条巨魔部族项炼，$N。', '', '去找辛特兰的弗拉加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2882, '科尔戈的黄金', '这张地图上画着一条对着南方的海滩，图下面用优雅的字体写着……$B$B$B热砂港南边$B家的南边$B找到骨头，旗子和旗杆$B如果你够胆，就去挖挖看$B挖挖看啊，科尔戈的金子光灿灿！$B开箱需钥匙，钥匙你会看见$B你面对的要用血来做交换。', '找到科尔戈的黄金！', '科尔戈船长的秘密宝藏正在等着你!', '这个箱子被锁上了!', '', '去找海盗的宝藏！。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2903, '作战计划', '既然我们已经发现了豺狼人的作战计划，接下来要做的就是把计划交给莫沙彻营地的哈杜肯·迅蹄。他或者那儿的其它什么人也许可以进一步弄清楚豺狼人到底想要做什么。', '把木爪豺狼人的作战计划交给莫沙彻营地的哈杜肯·迅蹄。', '啊，这正是我们需要的。虽然我还无法完全破译这张地图上涂写的东西，不过年轻的时候我研究过许多作战图，看来豺狼人现在的状况不妙。他们好像正在两线作战，除了作战之外……他们的主要精力似乎都用来对付南边的另一个敌人了。$B$B看来我们现在又多了一些问题，也许是时候去了解一下他们的另一个敌人究竟是谁了。', '欢迎回来，$N―你有没有找到豺狼人的作战计画之类的东西?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2904, '一团混乱', '<克努比呻吟着>发……发生什么事了？$B$B我只记得自己被一队黑铁矮人抓住了，他们暴打了我一顿，把我跟这些丑陋的穴居人扔在一块儿。$B$B快救我出去，$N！$B$B我有个计划：把我带到出口，如果我们能活着走出去的话，你就到藏宝海湾去，告诉斯库提我去了棘齿城，然后警告廷克维斯，黑铁矮人准备制造超强的钻探设备。$B$B让我们开始吧！', '将克努比护送到出口，然后向藏宝海湾的斯库提汇报。', '$N，你把克努比救了出来，当然应该获得奖励。如果你回到诺姆瑞根去，这些东西或许可以帮助你打败那个一无是处的卑鄙家伙，机电师瑟玛普拉格。', '嗯?克努比还活着??', '营救克努比', '去荆棘谷找藏宝海湾的斯库提。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2922, '拯救尖端机器人！', '当我们挚爱的诺莫瑞根城沦陷时，我可怜的发明——尖端机器人——受到了某种致命的打击。它原本包含了很多精巧的设计，并且储存了大量的信息，凭借这些，它无数次地帮助了我和我的同事，但现在它的正电子脑被极化，变成了负电子脑……尖端机器人的行为已经变得完全异常了。它像个疯子似的在诺莫瑞根里咆哮！$B$B也许我们仍然可以挽救它，如果你能找回尖端机器人的存储器核心并把它交给我，那么我就能找到故障的原因，然后把我可怜的尖端机器人修好。$B$B', '将尖端机器人的存储器核心交给铁炉堡的工匠大师欧沃斯巴克。', '哦，太棒了!谢谢你，$N!我马上就开始工作!!$B$B可怜的尖端机器人……别难过了，我们会修好你的。$B$B嗯，我把水压动力旋转扳手的插头搁哪儿了……', '你有没有发现尖端机器人?你有没有找回它的记忆体核心?', '', '去铁炉堡找侏儒区的工匠大师欧沃斯巴克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2924, '基础模组', '有一种通用型的机械部件——基础模组——对于诺莫瑞根的技师和铁匠来说都非常重要，不过在我们大举逃出诺莫瑞根的时候，谁也没想起要把这些东西带上！我手头上的工作需要大量这种部件。$B$B请去诺莫瑞根给我拿一些基础模组回来，它们就装在城市深处的机械储存柜里。$B$B谢谢你，$N，请尽快出发吧！', '收集12个基础模组，把它们交给铁炉堡的科劳莫特·钢尺。', '你成功了!现在我可以开始新的实验了!$B$B无论采用什么方式都不足以表达我的感激之情，$N!你的勇敢和无畏让我们的地精研究计画有了突飞猛进的发展!', '你拿到基础模组了吗?', '', '去铁炉堡找侏儒区的科罗莫特·钢尺。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2926, '诺恩', '事故后，诺恩想的说的都离不开两个主题：如何将穴居人赶出诺莫瑞根，以及如何为席卷诺莫瑞根的瘟疫找到治疗的方法。$B$B幸运的是，拉兹和我已经快要研究出一种治疗方法了——要不然就是一种很强劲的朗姆酒的配方。我们要试过才知道！当然，为了检验我们的理论是否成立，我们需要一些东西，准确地说，是诺莫瑞根城里那些穴居人身上的辐射尘。用这个小瓶子装一些泛着绿光的辐射尘，然后把它带回来！', '用空铅瓶对着辐射入侵者或者辐射抢劫者，从它们身上收集放射尘。瓶子装满之后，把它交给卡拉诺斯的奥齐·电环。', '干得好!是试试我的新配方的时候了。如果这个配方有效的话，不仅那些麻疯地精能被彻底治愈，我也会长出一头浓密的头发!站远点!', '你没看见我们正在这里想办法治疗地精族群所面临的瘟疫吗?!我们需要更多的辐射尘!', '', '去丹\r\n莫罗找卡拉诺斯的奥齐·电环。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2928, '陀螺式挖掘机', '太糟糕了，$N。我们没有足够的零件让我们的陀螺式挖掘机部队进入丹莫罗。$B$B我们需要的是零件，$N，更多的零件。说到寻找零件，难道还有比诺莫瑞根更好的地方吗？我听说那里的机器人像牧区的牛似的到处游荡。$B$B我要你做的就是到诺莫瑞根去，把这些机器人拆开，拿出它们的内部装置。给我弄两打来就够了。', '收集24副机械内胆，把它们交给暴风城的舒尼。', '干得好，$N。一台陀螺式挖掘机完成了，还剩下三百九十八台。', '如果这个任务是场比赛的话，你现在已经失败了。', '', '去暴风城的矮人区找沉默的舒尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2929, '大叛徒', '我以前曾经非常信任麦克尼尔，我从未想过他会背叛我和所有侏儒同胞。他为什么要背叛我们？为了权力？为了金钱？这些东西只要加以时日他都可以拥有。现在我们背井离乡，那个疯子掌握了政权，成了个什么都没有的国王……$B$B我们要夺回诺莫瑞根，$N。在夺回自己的城市之前，我们决不停止努力。如果你想加入我们，就先去完成一个简单的任务：杀了那个叛徒，麦克尼尔·瑟玛普拉格。', '到诺莫瑞根去杀掉麦克尼尔·瑟玛普拉格。完成任务之后向大工匠梅卡托克报告。', '我想，他倒下前所看到的最后一样东西就是你的脚吧，勇敢的$r。麦克尼尔已经死了，我们距离夺回诺姆瑞根的目标又进了一步。', '任务完成了吗?他有没有请求你的宽恕?', '', '去铁炉堡找侏儒区的大工匠梅卡托克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2930, '抢救数据', '在逃离诺莫瑞根的时候，我们留下了太多的数据！非常重要的数据！$B$B我需要一张彩色穿孔卡片，你可以从诺莫瑞根城里的矩阵式打孔计算机3005-D型里找到这种卡片。不过糟糕的是，要得到它的话，你就必须先接近低级安全终端，也就是A型，B型和C型计算机，然后用不同的穿孔卡片开启它们，从白色的卡片开始……而且我们把所有的穿孔卡片都留在城里了。$B$B这真是一场灾难！你能帮忙吗？', '将彩色穿孔卡片交给铁炉堡的大机械师卡斯派普。', '你成功了!你找到了棱彩穿孔卡片和丢失的资料!这些都是生死攸关、无比重要的资料，没有它我一刻也不能活!$B$B你对我们的贡献，我们会铭记于心的，$N。', '你拿到棱彩穿孔卡片了吗?', '', '去铁炉堡找侏儒区的大机械师卡斯派普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2932, '可怕的消息', '枯木巨魔原来是部落的盟友，但他们现在背叛了萨尔……他们要为此受到惩罚！$B$B来，拿起我的长矛，到北面的辛特兰去，那个地方就在塔伦米尔的东北方向。$B$B追捕那里的枯木巨魔，收集他们的头皮，把我的长矛插在他们的某个村庄中，比如西利瓦萨或者祖瓦沙。$B$B让他们知道，背叛部落，迟早要还的！', '在辛特兰收集枯木巨魔的头皮，把它们串在尼姆布亚之矛上。将尼姆布亚的长矛插在辛特兰的某个枯木巨魔村庄中，然后回到荆棘谷的尼姆布亚那里。', '我已经听说了你的所做所为。这听起来很可怕，但这是为了荣誉。让我们希望枯木部族明白你所要表达的意思。', '你还没有完成我交给你的任务，$N。', '传达可怕的信息。', '去荆棘谷找格罗姆高营地的尼姆布亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2933, '毒液瓶', '这些瓶子里装有绿色的毒液。$B$B由村庄中这种瓶子的数量来看，枯木巨魔一定很重视这些东西。或许塔伦米尔的药剂师会对这些毒液的样本感兴趣。', '将毒药瓶交给塔伦米尔的某个药剂师。', '啊，这是什么?好像是毒液……我认为这是来自蜘蛛之类的动物，你从哪里弄来的?', '你好啊，$C。整整一天了，没有一次实验是成功的……我希望你带给我的是好消息。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2934, '完好无损的毒囊', '我必须要有一个你带来的那种毒液的新鲜样本才能进行研究。生产毒液的蜘蛛一定生活在辛特兰一带——猎捕这些蜘蛛，直到你找到一个完好无损的毒囊，把它给我带来。巨魔们的沙德拉洛城附近有许多蜘蛛，到那里去找找吧。$B$B别耽搁了，毒囊一定要非常新鲜才行。', '将完好无损的毒囊交给塔伦米尔的药剂师林度恩。', '哦，太棒了!毒液很新鲜，我敢说它具有致命的毒性。谢谢你!', '你拿到完好无损的毒囊了吗，$N?我渴望用新鲜的毒液做实验，而且已经定购了一大批蹦蹦跳跳的小动物作准备!', '', '去希尔斯布莱德丘陵找塔伦米尔的药剂师林度恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2936, '蜘蛛之神', '枯木巨魔崇拜蜘蛛之神，他们从她那里收集极具威力的毒液。如果你想要毒液，就必须召唤他们的蜘蛛之神！$B$B要召唤她的话，你就必须知道她真正的名字，刻有这个名字的石板被埋藏在一座墓穴中，那墓穴就在塔纳利斯沙漠中的巨魔城市祖尔法拉克，由殉教者塞卡守卫着墓穴的入口。$B$B击败塞卡，阅读那块石板，找到蜘蛛之神的名字。知道了她的名字之后就回到我这里来。', '阅读塞卡石板，了解枯木巨魔的蜘蛛之神的名字，然后回到加德林大师那里。', '啊，艾罗萨-诺-莎德拉……小声地念诵这个名字，因为它在灵魂的世界里充满了威力。$B$B我会把它写进羊皮纸，为你创造召唤的咒语……', '你知道蜘蛛之神的名字了吗?', '找到蜘蛛之神的名字', '去杜隆塔尔找森金村的加德林大师。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2937, '召唤沙德拉', '拿着这张羊皮纸，在辛特兰的沙德拉洛祭坛上念诵羊皮纸上的咒文。这样就可以召唤蜘蛛之神沙德拉。', '在沙德拉洛祭坛上击败沙德拉，把它的毒液交给塔伦米尔的药剂师林度恩。', '太棒了，你成功了!', '你拿到毒液了没有?', '', '去希尔斯布莱德丘陵找塔伦米尔的药剂师林度恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2938, '送往幽暗城的毒药', '你在枯木巨魔的蜘蛛之神身上采集的毒液真是一个重大的发现！只消一小滴，我就可以杀死足足二十只兔子。当然，有些兔子很幼小，小得足以放在手掌上，它们对毒药的抵抗力非常低，但你也不能否认这种毒药极具威力！$B$B我想要给我的上级——幽暗城炼金房的大药剂师法拉尼尔——送去一些样本，我敢说他也会对此很感兴趣的。', '将法拉尼尔的包裹交给幽暗城的大药剂师法拉尼尔。', '啊，太好了。林度恩说包裹里的毒药是他见过的最有威力的毒药，他正在忙着将它引入实用领域。$B$B幸运的话，我们会发现它的各种用处。$B$B谢谢你，$N。你对皇家药剂师学会的贡献是不可否认的。', '有消息说你要来，$N。你有包裹给我?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2941, '海龟照片', '我一生中研究了许多课题，最近我迷上了遍布辛特兰海滩地区的钳嘴龟。我特别想看到一只名叫加莫里塔的大型钳嘴龟，本来呢，我想要自己去一趟，但繁重的研究工作让我不得不留在这里。如果能搞到一张它的画像就好了。$B$B把这封信交给塔纳利斯的克格尔·曲藤。她为我发明了一种可以快速获取图像的装置，我想她把那个东西叫做“快照”……', '把信交给塔纳利斯的克格尔·曲藤。', '你也是达蕾恩的学生?她是一位学识渊博的历史学家，$N。你能在她门下学习，应该心存感激!$B$B给，这是超级摄影器FX。你一定会喜欢它的!', '给我的信?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2942, '晨光石', '石碑中的东西被你拿出来的一瞬间，你突然感到艾奎尼克斯法杖的力量开始衰竭。', '将闪光的石头和艾奎尼克斯法杖交给羽月要塞的特洛亚斯·月风。', '你走之后我一直在研究相关资料，$N。你发现的石头叫做晨光石。虽然我不太清楚它是用来做什么的，但可以肯定的是，这件东西意义重大，所以它才会被藏进石碑中。$B$B我会继续对它进行研究，希望将来可以再次倚靠你，$N。谢谢你的帮助。', '我很高兴你回来了，$N。你有什么新的发现吗?', '', '去菲拉斯找羽月要塞的特洛亚斯·月风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2943, '向特洛亚斯回复', '给你，$N。请小心保管我的书。$B$B现在快点出发吧，特洛亚斯正在翘首企盼你的回归呢！', '把书交给羽月要塞的特洛亚斯·月风。', '你把书带来了，太好了!', '你好，$N。你去过达纳苏斯了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2944, '超级摄影器FX', '先来看看我的发明吧，$N。你所要做的只是将它对准任何一个你想要拍摄的物品，然后按下这个按钮。$B$B你说的辛特兰的生物是什么？加莫里塔？好吧，祝你好运，希望你能找到它。我坚信达蕾恩会对你给她的照片很满意的。$B$B不说那么多了，这是给你的超级摄影器。玩得开心点！', '用超级摄影器FX给加莫里塔拍张照片，然后把它交给鲁瑟兰村的达蕾恩·轻风。', '太棒了!克格尔的发明没有辜负我的期望。$B$B不要得意忘形，但我对你的工作确实很满意，$N。$B$B现在，我把书放在哪里了……', '嗯，你终于回来了，$N。你还带来了克格尔为我制造的装置―真是太好了。', '', '去泰达希尔找鲁瑟兰村的达蕾恩·轻风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2945, '脏兮兮的戒指', '你在一个黑铁矮人的尸体上发现了一枚戒指。但要辨认戒指的细节却很困难，泥土和坚硬的污垢将它整个包裹了起来，你根本没法戴上它。你觉得它是用某种珍贵的金属制成的，似乎还镶着宝石。$B$B如果你想好好看看这枚戒指的话，就得找些东西把戒指表面的污垢清理掉。', '想方法把脏兮兮的戒指弄干净。', '你将戒指放入超级清洁器5200型，然后投入了银币。$B$B机器猛烈地震动了起来，发出难听的金属摩擦声。你根本不知道戒指在那台机器里面受到了怎样的待遇……$B$B突然之间，机器“叮”地一声停了下来，它的盖子砰然打开，露出了一只缀有红色蝴蝶结的小盒子。看来超级清洁器5200型也可以用于包装礼物!', '你面前的地精装置上面钉着一张金属铭牌，上面写着“超级清洁器5200型”。阅读了铭牌上的说明之后，你发现这台机器是用来清洗污垢的，它是一个投币装置，将想要清洁的物体放入其中，然后投三枚银币，机器就会启动。$B$B你前不久发现的那枚脏兮兮的戒指正好可以用来试试看!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2946, '拭目以待', '我希望你把这张圆盘拿到奥丹姆的封印之门去。我们……我们不能肯定这样做会带来什么后果。$B$B当然，这听上去确实很危险，但也有可能什么都不会发生。也许你要将圆盘放在什么东西上，也许你只要带着圆盘，大门就会自己打开。总之，不试一试是不会知道真相的。$B$B等你完成这项任务之后就回到铁炉堡来，我们还有很多事需要讨论。', '将迷你白金圆盘拿到塔纳利斯的奥丹姆大门去，找出两者之间的联系。', '当你触摸底座的时候，奥达曼的迷你白金圆盘在背包里嗡嗡作响，闪闪发光。一种熟悉的刺痛感涌过双手，另一个石之看守者的形像在奥丹姆大门前出现了。$B$B“您好，我是入口的护卫者。您的圆盘缺少了正确的登录圆盘，奥丹姆圆盘。请将所需的圆盘和你手中的圆盘合在一起，然后重新进入。谢谢。”$B$B', '这个看起来很眼熟的底座从滚烫的沙子里突了出来。这其中一定有什么原因……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2947, '戒指归来', '打开由超级清洁器5200型制作的盒子之后，你看到了一枚闪闪发光的戒指！你戴上了戒指，立刻感觉身体中涌动着神奇的力量。$B$B戒指的内侧有一个很小的铁炉堡徽记，旁边刻着三个字母：“TdK”。$B$B这可能是它以前的主人或是制作者的姓名缩写。是将这枚戒指留着自己用，还是把它物归原主，这要由你自己来决定……', '你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。', '戒指?让我看看……没错，这是我制作的。$B$B早在诺姆瑞根出事之前，我在那里有家小店，或许这是我逃跑的时候留下的……这东西的设计很简单，我做了许多类似的戒指。或许它是某个没有逃出来的可怜虫的遗物。$B$B黑铁矮人拿着这枚戒指?好吧，事情变得复杂起来了。或许铁炉堡的高层对此更感兴趣，我这号珠宝商对此是没什么兴趣的。$B$B现在，让我们回到这枚戒指的话题上……', '嘿，朋友，放轻松点―我是个有头有脸的商人!肯定是邮差忘了把帐单给我送来……等等……你不是我的房东。$B$B好吧，你当然不是来耍我的!你是来寻找铁炉堡最好的珠宝商的吧，我可绝对不会制作被诅咒的珠宝哦!绝对不会!$B$B嗯……你需要什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2948, '侏儒的手艺', '听着，$n，这戒指当然是你的……但是我可以给你做一枚更好的！就像我说的一样，那种设计实在太简单了。现在我的技术更加娴熟了，只要你付我三十个银币的费用，我就可以帮你制作一枚新戒指！好吧，事实上还要再加一点点……$B$B我现在手头很紧，我的所有存货都用完了。如果你给我一块银锭和一块绿玛瑙，我就可以让戒指看起来更加闪亮华贵！$B$B相信我！', '将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给铁炉堡的塔瓦斯德·基瑟尔。', '啊，这正是我需要的!如果有一天我能摆脱现在的尴尬处境，我会为你，为所有人，制作出全艾泽拉斯最好的饰品来!谢谢你帮我找到这些材料，要制作这样的一枚戒指，我通常都会收取五倍的价格……$B$B说到戒指，这是你的新戒指!', '你拿到我需要的材料了吗?要不是我运气实在不好，我也不会问你要……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2949, '戒指归来', '打开由超级清洁器5200型制作的盒子之后，你看到了一枚闪闪发光的戒指！你戴上了戒指，立刻感觉身体中涌动着神奇的力量。$B$B戒指的内侧有一个很小的奥格瑞玛徽记。徽记旁刻着一行字母，但即使是经过清理之后也只能看清三个：“NOG……”$B$B这可能是它以前的主人或是制作者的姓名缩写。是将这枚戒指留着自己用，还是把它物归原主，这要由你自己来决定……', '你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。', '从诺姆瑞根拿来的戒指?让我看看……不，这不是我的。$B$B诺姆瑞根的东西―除了那帮蠢货还有谁会搞出这种事情来?这么多年了，他们存在的唯一价值就是被我们拿来开玩笑。难道一夜之间他们的钻探设备就比我们的更好了吗?$B$B你是从黑铁矮人那里弄到这枚戒指的?真有趣!你知道，也许那些地精偷了黑铁矮人疯狂的魔像制造计画，并对其进行了改造，因此那些黑铁矮人就要报复他们。这值得我们好好调查一番。$B$B当然，关于那枚戒指……', '我们一定要找到一种方法来击败那些丑陋的小地精，我甚至敢跟你打赌，他们从我们这里偷走钻探设备只是一个开始!呸，那些肮脏的小滑头……嗯，什么?你需要什么东西吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2950, '诺格的手艺', '不，不，不——我当然不是突然就说这枚戒指是我的。嗯，我通常不这样做，但你提供的关于黑铁矮人的情报很有用，所以我会破例为你改造你的戒指，我的手艺绝对比制作这个小东西的家伙要高超得多。嗯，八成是个侏儒做的……$B$B如果你给我拿来一块银锭、一块绿玛瑙和三十枚银币作为加工费的话，我就可以在戒指中加入白银和玛瑙的精华来加强其魔力。怎么样，感兴趣吗？', '将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给奥格瑞玛的诺格。', '这是你的戒指，它比以前更好了。再次感谢你提供的关于黑铁矮人的情报，这也解释了那些矮子为什么突然具有了哥布尔般的灵感。', '你拿到我需要的材料吗?没有那些东西，我可没办法对戒指进行改造。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2951, '超级清洁器5200型！', '这个装置屹立于那些竭力保护房间的侏儒中，装置上有一块小金属牌，上面写着“超级清洁器5200型”，还有一段文字：$B$B：“污垢和残渣让你的东西看起来污秽不堪？超级清洁器5200型会使它重现光芒！将你想要清理的物品放入清洁器中，然后向槽里投入三枚银币。稍候片刻，你的珍宝就会重新变得洁净而耀眼！”', '将脏兮兮的东西放入超级清洁器5200型，记得要用三枚银币来启动机器。', '将你找到的脏兮兮的东西和三枚银币放入超级清洁器5200型里面后，机器仿佛重获生命一般，疯狂地清理着那东西表面上的污垢，并发出响亮而剧烈的搅动声。它的金属外壳吱吱作响，发出吱吱呀呀的声音……', '似乎这个装置需要某种脏兮兮的东西和三枚银币才能运行。既然两样都有了，超级清洁器5200型应该开始运转了……', '', '去找银松森林的超级清洁器5200型。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2953, '再次使用超级清洁器', '', '', '超级清洁器5200型动了起来，它剧烈地晃动着。在机器里面，复盖在物品表面的污垢正在被清洁工具研成粉末!$B$B超级清洁器5200型停止了运转，熟悉的“叮”的声音过后，机器的盖子猛地打开了，里面摆着一只精心包装过的，扎着蝴蝶结的小盒子。', '超级清洁器5200型等待着清理脏兮兮的东西，它需要三枚银币才能启动!', '', '去找希尔斯布莱德丘陵的超级清洁器5200型。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2954, '石头卫士', '“向你致意——我是把守入口的守护者。除非你拥有完整的奥丹姆圆盘，否则我不会让你进入奥丹姆城。”$B$B这个石头卫士一定就是派你来这里的人希望能在这里找到的东西。看来你必须在继续探索之前找出石头卫士背后隐藏的故事。', '询问诺甘农的石头卫士，搞清楚它要让你干什么，然后再次点击它脚下的奥丹姆石座。', '充满了力量和权威的声音从石之看守者的口中发出:$B$B“当你再次接触底座的时候，你的圆盘将回到你手中。你必须先得到奥丹姆圆盘，把它们与已有的圆盘组合起来，然后你才能进入奥丹姆城。”', '在进一步发展之前，你必须知道石之看守者要让你干什么……', '了解诺甘农的石头卫士要让你干什么。', '去塔纳利斯使用奥丹姆石座。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2962, '更多的辐射尘！', '你的样本不仅数量不够，而且纯度也不够。$B$B我们需要更多的辐射尘。很显然，穴居怪身上的辐射剂量根本无法满足我们的需要。你必须重返诺莫瑞根，直接从辐射源头取回一些辐射尘。我指的是那些受到辐射的泥浆怪、潜伏者和水元素。小心一点，收集这种辐射尘并不容易。也许你得试好几次才能找到一个合适的样本。', '到诺莫瑞根去收集高强度辐射尘。要多加小心，这种辐射尘非常不稳定，很快就会分解。$B$B奥齐要求你把沉重的铅瓶也交给他。', '<奥齐仔细打量着你。>真棒，你还能完整无缺地回来!现在让我们来看看这个东西到底能做些什么!', '嗯，你没有发光，这是个好兆头。', '', '去丹莫罗找卡拉诺斯的奥齐·电环。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2966, '拭目以待', '圣者图希克和我希望你把这张圆盘拿到奥丹姆的封印之门去。我们……我们不能肯定这样做会带来什么后果。$B$B当然，这听上去确实很危险，但也有可能什么都不会发生。也许你要将圆盘放在什么东西上，也许你只要带着圆盘，大门就会自己打开。总之，不试一试是不会知道真相的。$B$B等你完成这项任务之后就回到我这里来，我们还有很多事需要讨论。', '将迷你白金圆盘拿到塔纳利斯的奥丹姆大门去，找出两者之间的联系。', '当你触摸底座的时候，奥达曼的迷你白金圆盘在背包里嗡嗡作响，闪闪发光。一种熟悉的刺痛感涌过双手，另一个石之看守者的形像在奥丹姆大门前出现了。$B$B“您好，我是入口的护卫者。您的圆盘缺少了正确的登录圆盘，奥丹姆圆盘。请将所需的圆盘和你手中的圆盘合在一起，然后重新进入。谢谢。”$B$B', '这个看起来很眼熟的底座从滚烫的沙子里突了出来。这其中一定有什么原因……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2967, '返回雷霆崖', '你打开了底座，白金圆盘又一次突然出现在你的背包里。$B$B你从石头守卫那里获取了许多信息，而且白金原盘又回到了你的手中，现在你应该回雷霆崖向纳拉·蛮鬃汇报这个大发现了。', '与雷霆崖的纳拉·蛮鬃谈一谈。', '还缺一些圆盘?这真是太有趣了，似乎诺甘农圆盘只是整套圆盘中的一部分―就好像一串钥匙中的几只。$B$B如果我们能发现奥丹姆圆盘，那我们就可以进入奥丹姆地下城了。想想看吧，在创世之神工作过的地方探险，而且还不用带个大铲子挖来挖去!$B$B嗯，我不是说铲子有什么问题……也不是说挖来挖去有什么问题……', '欢迎回来，$N。那张圆盘对你有用吗?或者它根本就是个没用的东西?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2970, '菲拉斯的正义', '辛达尔已经跟你说过了，我们准备去和恐怖图腾部族作战。干掉几个牛头人对我们两个来说不是什么问题，但如果你愿意帮忙的话，我们还是很欢迎的。$B$B看到下面那个营地了吗？东边有更多这样的营地。运用你的战术，尽可能让那些牛头人多吃些苦头。当他们被你和辛达尔打得落花流水之后，我们再回到这里来碰头。', '杀掉12个恐怖图腾博学者、10个恐怖图腾袭击者和6个恐怖图腾萨满祭司，然后向菲拉斯的耶尔卡·月纹汇报。', '辛达尔说得对，$N―你确实很出色。作为一个冒险者，你比我们更有经验，谢谢你。$B$B恐怖图腾氏族比大多数牛头人更具有攻击性……我怀疑其它牛头人也会对这些家伙感到厌恶。你可能已经注意到了，艾泽拉斯的许多种族都有那么一部分害群之马。$B$B但这个问题我们还是以后再讨论吧。', '辛达尔需要花些时间准备，但我们已经杀掉许多敌人了。恐怖图腾氏族对我们深恶痛绝，他们就像毒蛇一样到处追捕我们。$B$B你要当心一点，$N……你插手了，他们也会来抓你。', '', '去找菲拉斯的耶尔卡·月纹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2972, '菲拉斯的正义', '在这片蛮荒的土地上，辛达尔和我有无数的方法来报答你，但我们想让你有更多的成就感。把我的戒指拿去吧，如果你哪一天到了泰达希尔，就去一趟达纳苏斯城里的月神殿。你可以在那里找到高阶祭司泰兰德·语风。她看到这枚戒指就会知道我们在这里一切安好，并相信你所说的一切。$B$B$N，我们都很感谢你。', '将耶尔卡的徽记之戒交给达纳苏斯的高阶女祭司泰兰德·语风。', '这个故事令我感到非常惊讶，$N。你帮助了龙族和我们的女祭司，谢谢你。耶尔卡派你来找我是个正确的决定，我会派人把戒指送回她手中的―我的斥候将立刻向菲拉斯进发，详细调查这件事情。$B$B再次感谢你，请别拘束，把这里当成自己的家吧。', '你好，孩子。我们为越来越多强大的冒险者来到神殿感到由衷的高兴。如果你有时间的话，能和其它年轻的冒险者们分享一下你的故事吗?我相信这样对他们会有很大的帮助。$B$B对不起，请原谅我的鲁莽。你应该是到神殿里来寻求帮助的，我失礼了。请你原谅。我能为你做些什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2973, '新斗篷的光辉', '你好，$c。我和我的伙伴们正准备去菲拉斯执行任务。$B$B我的妻子科琳很喜欢新衣服，所以我想为她做一件用小精龙的翅膀装饰的新披风。你能帮帮我吗？长着美丽翅膀的小精龙在莫沙彻营地的西边。', '给莫沙彻营地的克鲁伊格·碎颅带去10个闪光的小精灵翅膀。', '太好了，$C!这些再合适不过了，足够让科琳做一件披风，也许还要更多!谢谢你。$B$B你没碰到什么危险吧?菲拉斯地区可不是个安全的地方，不过你显然应付得过来。$B$B再次感谢你，$C。', '被激怒的小精龙是非常危险的，和它们打交道要多加小心，$C。这个地区的夜精灵比它们还危险，那些烦人的蠢货也会在森林里出没。$B$B当你拿到足够多的翅膀之后就告诉我，我一定会好好奖励你的!', '', '去菲拉斯找莫沙沏营地的克鲁伊格·碎颅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2974, '可怕的发现', '什么？！你在这一地区碰到牛头人了？你开玩笑吧！他们长什么样？！$B$B恐怖图腾氏族！你看到他们了？贝尔戈洛姆对他们这种生物很有兴趣……甚至出重金悬赏他们。$B$B你必须得回去，$c。回去给我带些他们的角回来……如果可以的话，尽可能多弄一些。你可别低估了恐怖图腾氏族，回去杀了他们，让菲拉斯的河流被他们的鲜血染红。', '收集20支恐怖图腾之角，把它们交给莫沙彻营地的克鲁伊格·碎颅。', '这些都是品质很好的角，$C。干得不错。当我们回到奥格瑞玛时，我会把这件事情告诉贝尔戈洛姆的。你已经帮了我两次，为此，我会永远记住你的。也许在将来的某一天我也可以帮你的忙!祝你好运。', '认真听我说，$C，恐怖图腾氏族都是恶魔。如果你在附近看到他们，那你就应该尽快决定是否要迎头痛击他们……否则他们就会闯入我们的领地，夷平我们的村庄，玷污我们的土地。', '', '去菲拉斯找莫沙沏营地的克鲁伊格·碎颅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2975, '菲拉斯的食人魔', '戈杜尼食人魔在这一地区的影响已经不容忽视了。$N，你可以清楚地看到这一点，他们的存在污染了这片土地。在他们进一步扩张之前，我们一定要把他们赶回去。$B$B沿着河向北走，你会找到他们的前哨营地。去杀掉他们，$N。我们必须告诉这些食人魔：他们在这里不受欢迎。', '莫沙彻营地的洛卡·奥赫要你杀掉10个戈杜尼食人魔、10个戈杜尼食人魔法师和5个戈杜尼蛮兵。', '太好了，$N。总有一天，这块土地会被治愈。我们不能放弃希望。', '行动迅速点，$N。难道是这个任务对你来说太难了?', '', '去菲拉斯找莫沙彻营地的洛卡·奥赫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2976, '可怕的发现', '什么？！$B$B啊，我确实提到过奖赏，对吗？好吧，我知道了$B$B你完成了任务，我觉得你应该得到最高的奖赏。把这些角拿去，我会帮你把它们放到箱子里。到荣誉谷去找贝尔戈洛姆·石槌，向他汇报你所见的一切，他会表彰你的。$B$B祝你一路平安，$c，再次感谢你。', '将一箱恐怖图腾之角交给奥格瑞玛的贝尔戈洛姆·石槌。', '恐怖图腾氏族?!真有趣。你说你是在菲拉斯打猎时发现他们的?真的吗?$B$B我的族人很想听你的故事，$C。告诉我更多细节，我会给你相应的报酬的。$B$B另外，在你走之前，我希望让你知道，我很感谢你今天给我带来的情报。', '快一点，$C，我今天有很多事要做。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2977, '返回铁炉堡', '你打开了底座，白金圆盘又一次突然出现在你的背包里。$B$B你从石头守卫那里获取了许多信息，而且白金原盘又回到了你的手中，现在你应该回铁炉堡向探险者协会汇报这个大发现了。', '与铁炉堡的史学家卡尼克谈一谈。', '还缺一些圆盘?这真是太有趣了，似乎诺甘农圆盘只是整套圆盘中的一部分―就好像一串钥匙中的几只。$B$B如果我们能发现奥丹姆圆盘，那我们就可以进入奥丹姆地下城了。想想看吧，在创世之神工作过的地方探险，而且还不用带个大铲子挖来挖去!$B$B嗯，我不是说铲子有什么问题……也不是说挖来挖去有什么问题……', '欢迎回来，$N。那张圆盘对你有用吗?或者它根本就是个没用的东西?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2978, '戈杜尼卷轴', '你捡起了这个沾满泥土的卷轴，发现上面写着某种集会或仪式的内容。洛卡·奥赫应该会对这个卷轴以及它对戈杜尼食人魔的意义感兴趣。', '将戈杜尼卷轴交给莫沙彻营地的洛克·奥汉。', '这个卷轴……你是在戈杜尼前哨站发现的?', '这是什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2979, '黑暗仪式', '这些好像是某种黑暗仪式的计划，$N。根据我所了解的情况，这种仪式是由戈杜尼食人魔中的大法师进行的。$B$B从某个戈杜尼大法师身上给我弄一颗宝珠来。$B$B法师的宝珠蕴含了巨大的力量，它可以帮我们搞清楚更多关于这种仪式的细节。', '莫沙彻营地的洛卡·奥赫希望你找到一颗戈杜尼之宝珠。', '这颗宝珠可以为我们提供更多关于戈杜尼巨魔的资讯……我们会利用这些情报来击败他们，$N。', '我们必须找到更多资讯，才能知道戈杜尼巨魔出现在这里的原因，$N。', '', '去菲拉斯找莫沙彻营地的洛卡·奥赫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2980, '菲拉斯的食人魔', '现在你已经证明了自己是一个真正的勇士，我相信你具备足够的勇气继续完成下一个任务。$B$B到这里西南边的高原荒野去，在那块原本属于暗夜精灵的土地上还残存着一些被遗弃和毁坏的建筑物。搜索那些废墟，当你看到枯萎的树木和满目疮痍的大地时，你就会看到那些戈杜尼食人魔。把他们都干掉。$B$B这些食人魔比你曾面对的任何敌人都要强大，$N。你一定要小心行事。', '莫沙彻营地的洛卡·奥赫要你去杀掉十个戈杜尼萨满祭司、10个戈杜尼术士和5个戈杜尼虐待者。', '你已经证明自己的确是个可以信赖的朋友，$N。', '你找到那片废墟了吗，$N?', '', '去菲拉斯找 莫沙彻营地的洛卡·奥赫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2982, '高原荒野', '虽然菲拉斯森林的废墟中隐藏着巨大的危险，但特洛亚斯和我一直以来都在调查这个地区。$B$B最近特洛亚斯老是独自一人去高原荒野，这很让\r\n我担心。戈杜尼食人魔已经占领了那里，他们不会对任何进入他们领地的冒险者手下留情的。$B$B我希望你能到菲拉斯南部去一趟，消灭一些食人魔。让我的特洛亚斯安全一点，我会十分感激你的。', '安吉拉斯·月风要求你杀死8个戈杜尼术士、8个戈杜尼萨满祭司和8个戈杜尼蛮兵。', '我很感激你为我所做的事。$B$B不过，请不要和特洛亚斯谈起此事……', '$N，你要小心那些戈杜尼巨魔。他们的魔法似乎已经在他们所占领的土地上造成了一场大灾难。', '', '去菲拉斯找羽月要塞的安吉拉斯·月风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2987, '戈杜尼钴矿石', '我刚刚到达菲拉斯时，曾听说这里的戈杜尼食人魔有一些有趣的矿石。天知道食人魔用矿石来干什么，但他们确实在很小心地保护那种东西！他们有意隐藏这些矿石，以免我们接触到它。$B$B如果你愿意的话，我会把我的铲子给你。到北面的戈杜尼前哨站去，给我挖些戈杜尼钴矿回来。注意找那些泛着蓝光的矿石，然后就挖！', '莫沙彻营地的奥尔文·吉兹米克需要12块戈杜尼钴矿石的样本。', '太好了!我会在继续旅行的时候带着它们的，$N。我敢说会有人为这些矿石出个好价钱的。$B$B拿着这个，你应得的报酬。', '赶快去挖!$B$B我还要去很多地方，见很多人―时间就是金钱!', '', '去菲拉斯找莫沙彻营地的奥尔文·吉兹米克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2988, '枯木巨魔的牢笼', '我们最强大的狮鹫的儿子失踪了！几天前，沙普比克和它的父母外出打猎时失踪了，我们认为是巨魔抓走了它。$B$B你必须帮帮我们！到枯木巨魔的两个村子里去搜一搜那里的笼子，看看沙普比克是不是被关在里面。', '检查两个枯木巨魔村落里的笼子，然后向狮鹫管理员沙拉克·鹰斧回复。', '沙普比克不在村子里?嗯……这是个可怕的消息。那头狮鹫兽命中注定是下一代狮鹫兽的领袖。如果它失踪了，我们的狮鹫兽军团也会因此遭受重创。', '你有没有搜查过笼子，$N?我们必须得找到沙普比克!', '', '去辛特兰找鹰巢山的狮鹫管理员沙拉克·鹰斧。', '检查第一只笼子', '检查第二只笼子', '检查第三只笼子', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2989, '祖尔祭坛', '沙普比克没有和枯木巨魔在一起，那么或许是邪枝巨魔带走了他……到邪枝巨魔控制地区的西部边缘去，在那里的祖尔祭坛上找一找吧。', '检查祖尔祭坛的顶部，然后向狮鹫管理员沙拉克·鹰斧报告。', '沙普比克不在那里?真是个坏消息，不过也是个好消息……$B$B幸好他不在祖尔祭坛上，那些邪枝巨魔是以供奉活祭出名的。$B$B感谢你的帮助，不过恐怕我还有更艰巨的任务要你去完成。', '赶快，$N!邪枝巨魔抓到了沙普比克，谁知道他们会对他干些什么!', '搜索祖尔祭坛', '去辛特兰找鹰巢山的狮鹫管理员沙拉克·鹰斧。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2990, '萨迪斯·格希德', '把这根羽毛交给占卜师萨迪斯·格希德。几年前，他离开鹰巢山去寻求黑暗的知识，但他内心深处仍是一个不折不扣的蛮锤矮人！$B$B也许他的智慧能帮助我们找到沙普比克。$B$B这根羽毛是从它的巢穴里拿出来的，如果你把它交给萨迪斯，那么他也许就可以用占卜法术找到沙普比克。$B$B祝你好运，$N。你可以在诅咒之地找到萨迪斯，他就在守望堡的法师塔上。', '将沙普比克的羽毛交给诅咒之地的萨迪斯·格希德。', '啊，是这样。这根羽毛属于一头优秀的狮鹫兽。它命中注定要做大事……如果它可以安然无恙地活到成年的话。$B$B你想找到它?附耳过来，勇敢的$C……', '$N，你给我带来了什么礼物?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2991, '耐克鲁姆的徽章', '我会帮你找出那头狮鹫的下落，但你得先为我做点事情。巨魔城市祖尔法拉克里面有一个名叫耐克鲁姆的巨魔，他拥有一枚徽章，我很想研究一下那东西。把徽章交给我，我就帮你找到沙普比克。$B$B祖尔法拉克在塔纳利斯的沙漠中。', '将耐克鲁姆的徽章交给诅咒之地的萨迪斯·格希德。', '啊，耐克鲁姆的勋章。据说这枚勋章使那个巨魔变得长生不老，但这种奖励是有代价的。我希望找到一种获得勋章力量的方法，同时避免它的……讨厌的负面效应。$B$B你帮了我一个大忙，$N。我会遵守我的承诺。', '你拿到耐克鲁姆的勋章了吗，$N?我急切地等待着发现勋章中隐藏的力量。', '', '去诅咒之地找守望堡的萨迪斯·格希德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2994, '拯救沙普比克', '你必须得救出沙普比克！$B$B杀进邪枝巨魔那座城市——辛萨罗的山顶，从邪恶祭司海克斯那里拿到沙普比克笼子的钥匙，找到沙普比克，把它救出来！', '到辛萨罗山顶去，杀掉邪恶祭司海克斯，找到沙普比克笼子的钥匙，然后救出沙普比克。', '刚才沙普比克和它的父母一起回来了，它们对孩子唠唠叨叨的，就好像刚当上父母亲一样。看到它们重新团聚，这让我这个老矮人的眼睛也湿湿的……$B$B我们不知该如何感谢你，$N。鹰巢山的狮鹫兽和他们的骑手会一直传颂你的名字。', '救出沙普比克!', '', '去辛特兰找鹰巢山的狮鹫管理员沙拉克·鹰斧。', '', '打开沙普比克的笼子', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2995, '联络中心', '奎尔丹尼小屋是高等精灵在辛特兰的联络中心。他们的使者正在试图与其它种族创建联系，他们会与这些种族分享与辛特兰南部的枯木巨魔的情报。所有联络其它种族所需的文件都被保存在了小屋中。$B$B我们不希望那些精灵与其它种族创建联盟关系，$N。$B$B去摧毁他们的文件，或者说，我们要毁掉他们的联络中心……', '幽暗城的奥兰·斯内克威瑟让你到辛特兰去烧毁高原精灵记录、高原精灵报告和高原精灵信件。', '太好了，$N。在高原精灵试图恢复他们丢失的联络资讯的同时，我们就可以将封锁线进一步推进……', '将高原精灵孤立起来是一切的关键……你找到小屋了没有?', '', '去找提瑞斯法林地的奥兰·斯内克威瑟。', '烧毁高原精灵记录', '烧毁高原精灵信件', '烧毁高原精灵报告', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3002, '戈杜尼宝珠', '虽然我很熟悉我的敌人，但我只是一个战士，$N。我不知道这颗宝珠是用来干什么的。$B$B我认识一个住在奥格瑞玛的法师，他可以告诉你更多关于宝珠的信息。把它拿到他那里去吧。', '将戈杜尼宝珠交给奥格瑞玛暗木小屋里的尤塞尔奈。', '这可真迷人，$N……$B$B这颗宝珠具有非常强大的力量，但也十分危险。', '你给我带什么来了，$r?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3022, '小心运送', '$N，显然你很想帮我进行崇高的事业。嗯，当然，你可以为我做一些事情！$B$B请把这箱蛋送给艾瑞拉斯·琥珀。他是一个很重视这些蛋的德鲁伊，而且一直在帮助孵化这些蛋，以及训练幼小的角鹰兽。你可以在泰达希尔南边的一个名叫鲁瑟兰村的村庄里找到他。', '把仔细包装过的箱子交给鲁瑟兰村的艾瑞拉斯·琥珀。', '谢谢你，$N。如果没有我们的帮助，角鹰兽的数量不会增长得如此之快。啊，我相信你也很了解这个问题，你只身转至菲拉斯，亲眼目睹了戈杜尼巨魔的残暴和破坏性。$B$B好吧，你也看到了，我在这里有许多事情要做，所以就这样吧。$B$B再次感谢你，$N。', '我猜又是从克格尔那儿来的货吧?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3042, '巨魔调和剂', '祖尔法拉克的沙怒巨魔用砂石制造巨魔调和剂，我可以用它来加强我铸造的东西！有眼光的行家会出高价购买经过这样处理的装备，所以，如果你能给我提供足够的调和剂，那我一定会重重奖赏你的。$B$B祖尔法拉克在加基森的西北边。祝你好运。', '收集20瓶巨魔调和剂，把它们交给加基森的特伦顿·轻锤。', '啊，成色很好，数量也充足!看来我得好好工作几天才能把它们全都用光!$B$B谢谢你，$N。请收下这个作为报酬。', '你拿来我要的调和剂了吗，$N?', '', '去找塔纳利斯的特伦顿·轻锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3062, '黑暗之心', '艾丹娜·邪爪是居住在西面废墟里的北泉鹰身人的皇后。她是个彻头彻尾的恶魔，我听说她的心是水晶做的。除了对别人的仇恨之外，她没有一丝其它的情感。你必须干掉艾丹娜，把她的黑心交给我。$B$B我听说鹰身人有一种号角——在废墟北部的邪爪石那里吹响号角就可以召来她。$B$B当她发现召唤她的是死亡的命运而不是她的同族时，她会有多么惊讶啊！', '莫沙彻营地的塔罗·刺蹄要你给他拿去艾丹娜·邪爪的黑心。', '现在艾丹娜真的死了，而这颗心―我会把它收好，用它来时刻提醒自己，它曾经给我们带来了什么。谢谢你，$N。', '不能让艾丹娜继续在这片土地上继续为非做歹了。', '', '去菲拉斯找莫沙彻营地的塔罗·刺蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3063, '对鹰身人的复仇', '年轻时，我曾是个经验丰富的猎手，没有什么野兽会让我感到害怕，直到……$B$B有一次在树林里，我在一场恶战之后正在打磨自己的武器，这时我遭到了伏击。鹰身人包围了我，好不容易我才脱了身。$B$B直到现在，我还能听见它们的嚎叫在耳边回荡……$B$B现在我已经不再年轻了，不过仇恨还在我的心中燃烧——这么多年了，我一定要报仇。$B$B北泉鹰身人就在西边，$N，去为我复仇。', '塔罗·刺蹄让你杀掉4个北泉鹰身人、4个北泉游荡者、4个北泉唤风者和4个北泉杀戮者。', '谢谢，$N。你让一个年老的牛头人得到了心灵的慰籍。', '北泉鹰身人的翅膀象夜一样黑;不要让它们从你的视线中消失，否则黑夜会掩盖它们的行踪。', '', '去菲拉斯找莫沙彻营地的塔罗·刺蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3065, '普通石板', '啊，刚刚你不在的时候，有人送来了这块石版，$N。$B$B如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是战士训练师弗朗恩写的，他有事找你。你可以在大兽穴外面的阴凉处找到他。', '阅读普通石板，然后和试炼谷的弗朗恩谈一谈。', '如果你继续按照战士的方式训练，你会发现这块地方很适合你。如果你有什么问题，随便问问周围的同伴，准备好了之后就来找我训练。我所掌握的技能超过了试炼谷里所有的战士，我可以把知识传授给你……当然那是有代价的。', '又一个加入我们队伍的$r，很好!$B$B或许要你举起像斧头这样的好武器会有些困难，但长矛或其它什么武器也一样好用。$B$B欢迎来到试炼谷。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3082, '风蚀石板', '啊，刚刚你不在的时候，有人送来了这块石板，$N。$B$B如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是猎人训练师基沙写的，她有事找你。', '和试炼谷的基沙谈一谈。', '现在我们教他们那些东西，他们教我们别的东西。我们几乎……成了同一个种族。我们成为盟友已经很久了，所以你要记得帮助他们。基沙会记得要帮助你。$B$B基沙教你领悟猎人之道―教你学习好的东西。永远不要忘记，部族很敬重猎人。你在将来的作用会很大……你永远不要忘记。$B$B如果你觉得需要，就来找基沙。如果她觉得你准备好了，她就会将所有知识传授给你。', '基沙看见一个强大而坚定的猎人站在她面前。$B$B猎人之道是我们生活中最古老的传统。部落想在艾泽拉斯生存，于是就来寻求我们的帮助，要我们教导他们，告诉他们许多秘密。他们已经很强壮了，他们是强壮的萨满，强壮的战士\r\n。但是猎人之道并不适合他们……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3083, '密文石板', '啊，刚刚你不在的时候，有人送来了这块石板，$N。$B$B如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这块石板是盗贼训练师鲁瓦格写的，他有事找你。', '阅读密文石板，然后和试炼谷的鲁瓦格谈一谈。', '在你足够成熟之前，还是得由我来负责训练你。一旦你觉得准备好了的时候就来找我，然后我就可以看看你接下来要接受什么样的训练。在此之前，你必须训练你的技能，把它们磨练得像刀刃那样锋利。你永远都不知道自己会靠什么技能活下来，即使是最不起眼的技能也会非常有用。', '欢迎来到试炼谷，$N。如果你没有收到我的石板的话，就不会找到这儿来了，因此让我们单刀直入吧。$B$B我叫鲁瓦格，在试炼谷负责训练盗贼、小偷和刺客。如果你还没有为将来的使命做好准备，我就得对上面负责。但是别担心，上面不会操纵你所做的每件事，可是如果他们需要你这种人才的话，和他们合作才是明智之举。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3084, '符文石板', '啊，刚刚你不在的时候，有人送来了这块石板，$N。$B$B如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这块石板是萨满祭司训练师史克里克写的，她有事找你。', '和试炼谷的史克里克谈一谈。', '你也许知道，元素赐予我们力量。火，土，水，气―这些都是我们的工具。$B$B我们的力量来自于祖先的灵魂，我们引导着我们的同胞。就像萨尔对部落那样，我们对于这些村庄和城镇也肩负着重大的责任。他们需要我们的智慧和保护。为了作好充分的准备，你必须经常接受训练。等你觉得自己变得更加强大时就来找我，我将把我所会的都教给你。', '啊，欢迎，$N。我很高兴你能来这里。我有很多学生要教，日子变得越来越忙碌，不过像你这样的学生的到来将会给我带来很强的成就感―我还记得你们的萨满教导我的那段日子。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3085, '神圣石板', '啊，刚刚你不在的时候，有人送来了这块石板，$N。$B$B如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这块石板是牧师训练师肯杰写的，他有事找你。', '阅读神圣石板，然后和试炼谷大兽穴外的肯杰谈一谈。', '在你对自己进行试炼的时候，会发现对自己灵魂的掌控能力越来越强了―由此你也能做更伟大的事情……这里就需要肯杰我的帮忙了。等你感觉准备好了，就来和肯杰谈谈。如果你的灵魂也准备好了，我们就可以教你更有用的技能……不过一定要你的灵魂也准备好。$B$B现在去吧，和谷里其它人也谈谈。晚些时候再来找我。', '你终于来了……很好，很好!我的灵魂告诉我，你很快就会来见肯杰。我将是试炼谷中第一个来欢迎你的人。这里只是你暂时的家，既然如此，你就该好好珍惜这段时光。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3086, '雕文石板', '啊，刚刚你不在的时候，有人送来了这块石板，$N。$B$B如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这块石板是法师训练师迈安写的，她有事找你。', '阅读雕文石板，然后和试炼谷里大兽穴入口附近的迈安谈一谈。', '你已经成为了这个世界上拥有最强大力量的群体中的一员，$N……这一点无可争议，每个人都了解……非常了解!$B$B不过你一定要小心!你要害怕的不是兽人、夜精灵或矮人……而是那些你见不到的东西。魔法是无比危险的，它会让你做你不愿做的事，它会让你以为自己很强大。你要保持耐心和智慧。$B$B想要接受进一步训练的话，就回到迈安这里，她会在你准备学习的时候给你指导，这是没问题的。', '你看起来已经让迈安很满意了，$N。这样很好，你尊重迈安，迈安也会尊重你。好了，你是来学习魔法，不是来听迈安说话的。$B$B关于魔法，只有一件事是迈安不能教你的，$N，那就是如何防止自己因追求力量而堕落。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3087, '风蚀羊皮纸', '啊，刚刚你不在的时候，有人送来了这张羊皮纸，$N。$B$B如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是猎人训练师基沙写的，她有事找你。', '阅读风蚀羊皮纸，然后和试炼谷的基沙谈一谈。', '我们谈话结束以后，你应该和试炼谷的其它人谈谈。他们要你为他们做点事……这些事将会考验你的技术，让你知道了这块土地有多么危险。$B$B随着你的经验和智慧不断增长，你会来找基沙学习更好的技术。时常回基沙这里看看吧，我会让你知道我可以教你什么的。', '啊，你终于来了，太好了。基沙在这里等你。$B$B许多人认为这条道路很平坦，但基沙告诉你:并不是这样的。控制杜隆塔尔或其它地区的野兽与掌握魔法或是同我们的祖先交流一样需要很多技巧。$B$B对你来说，射箭开枪可能没有施放魔法那样危险，但它对你的敌人来说却是一样危险的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3088, '密文羊皮纸', '啊，刚刚你不在的时候，有人送来了这张羊皮纸，$N。$B$B如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是盗贼训练师鲁瓦格写的，他有事找你。', '阅读密文羊皮纸，然后和试炼谷的鲁瓦格谈一谈。', '既然你知道了我的底细，我就应该让你了解:破碎之手氏族让我留心你。他们要我训练你，告诉你他们需要什么。即使你对帮助他们不感兴趣―如果你不感兴趣就是傻瓜―我也会尽力帮助你……而且收费低廉。无论什么时候，只要你觉得准备好了，就可以来找我，让我们看看你能学些什么。', '嘘，小声点。我对站在那边的纳托克可不信任。对那些在洞中比我“隐藏”得更深的家伙，我们要小心对待。$B$B我相信你在这里不会迷路吧?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3089, '符文羊皮纸', '啊，刚刚你不在的时候，有人送来了这张羊皮纸，$N。$B$B如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是萨满祭司训练师史克里克写的，他有事找你。', '阅读符文羊皮纸，然后和试炼谷的史克里克谈一谈。', '你将成为我们祖先的代言人，你将拥有元素的力量，撕裂敌人对你来说轻而易举，而为盟友疗伤也不在话下。面对挑战的时候你要记住这些，要经常回来见我，我会留在这里，等你准备好的时候，我就会教你新的法术，并引导你走在正确的道路上。', '你来了，我正在想你什么时候会来呢，前一段时间我把羊皮纸送出去之后就没了下文。$B$B说了够多闲话了……我让你来这儿是因为你已经被选中来指引我们同胞的精神生活。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3090, '被污染的羊皮纸', '啊，刚刚你不在的时候，有人送来了这张羊皮纸，$N。$B$B一般来说我是不会去招惹术士的，但是如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是术士训练师纳托克写的，他有事找你。', '阅读被污染的羊皮纸，然后到试炼谷的大兽穴里去和纳托克谈一谈。', '现在你也加入了我们的行列。别误会，$N。你有着令许多人嫉妒的力量，但这不意味着你会被很轻易地接受。萨尔允许我们进入奥格瑞玛是因为我们仍是他的族人―他不能拒绝我们，否则我们会变得像那些曾经奴役过他的人类一样悲惨。我要说的是，你要万事小心。你也许可以变得很强大，但如果你很愚蠢，那么你跟死了没什么两样。$B$B如果你要学习新的法术，那么就来找我吧。', '你终于来了……而且行动隐蔽。很好。$B$B我们的世界中充满了愚蠢的家伙，$N。即使是强大的萨尔也会犯错，他拒绝利用能使这片土地完全为我们所用的强大力量!我们不是那种可以被扭曲虚空的生物操纵利用的弱者，我们掌握着自己的命运，我们很自豪……我们也很强壮。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3091, '简易便笺', '刚才有一个信使来找过你，$n。我相信她是战士训练师哈鲁特派来的。如果这张便笺的确是哈鲁特写的，那么你最好赶快看看上面都说了些什么。', '阅读简易便笺，然后与纳拉其营地的哈鲁特·雷角谈一谈。', '我们都在部族中扮演着自己的角色，我们都需要通过相同的试炼和祭仪来成长。绝对不要骄傲自满。$B$B我在这里训练那些追寻荣誉的年轻战士，当你感到自己准备好了之后就回来找我，让我对你进行进一步的训练。整个部族都将祝福你，$N。', '啊，你终于来了，$r。我们是一个特殊的群体，就好像我们部族的德鲁伊或者萨满一样，我们和他们具有同样重要的作用，而我们的职责就是保卫边疆，猎捕半人马，以及在战争上搏杀。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3092, '风化便笺', '刚才有一个信使来找过你，$n。我相信她是猎人训练师兰卡派来的。如果这张便笺的确是兰卡写的，那么你最好赶快看看上面都说了些什么。', '阅读风化便笺，然后与红云台地的兰卡·远箭谈一谈。', '我的任务是确保你接受这个职业的基本训练―如何驯服你的宠物，如何开枪，以及其它一些必要的技能。$B$B猎人这个职业在我们的传统和历史中占有重要的地位，$N。你会逐渐意识到自己对于部族有多么重要。如果你能为解决我们的同胞遇到的问题而倾尽全力，你就会得到应有的尊重和崇拜。', '欢迎来到纳拉其营地，$N。我已经听说过很多关于你的事情了。你拥有优良的血统，所以许多长者都认为你已经具备了相当的素质，但是你还需要磨练。$B$B莫高雷平原在接下来的一段时间里将成为你的家―你最好在这里认真地学习。终有一天，你会离开这里，踏上陌生的土地去进行更高层次的修炼，你要做好准备。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3093, '符文便笺', '刚才有一个信使来找过你，$n。我相信她是萨满祭司训练师米拉派来的。如果这张便笺的确是米拉写的，那么你最好赶快看看上面都说了些什么。', '阅读符文便笺，然后与纳拉其营地的米拉·晨行者谈一谈。', '以后我们会经常见面的，我希望每次见面的时候你都比上次更加强大，对将来也有更加充分的准备。你的灵魂将像永恒之火一样迸发出光明和热量。$B$B现在就出发吧，$N。开始你的修炼之路吧，我在这里随时恭候你的到来。', '转瞬之间，你就来到了我的面前。我很高兴你的动作如此迅速，这意味着你已经意识到了来这里见我是多么的重要。我并不是一个领袖，但是我懂得作为领袖所必须具备的素质，我还能和我们同胞的灵魂进行沟通。我会把这些都教给你的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3094, '绿色便笺', '刚才有一个信使来找过你，$n。我相信她是德鲁伊训练师加尔特派来的。如果这张便笺的确是加尔特写的，那么你最好赶快看看上面都说了些什么。', '阅读绿色便笺，然后与纳拉其营地的加尔特·迷雾行者谈一谈。', '虽然我们和夜精灵有共同点，但我并不指望夜精灵会热烈欢迎我们。他们的骄傲限制了他们的视野，但这不关我们的事。大地之母的教诲才是你应该关心的，随着你的智慧和知识不断丰富，我也会把我所知道的东西都教给你。$B$B时常到我这儿来看看，$N。你会发现，大地之母只把强大的能力赋予那些最勤奋勇敢的$C。', '你终于来了。太好了。我们祖先的灵魂在莫高雷一带开始变得越来越不平静，但我不知道为什么。学会聆听自然的灵魂，成为它们的化身―这将是你永远的任务。你应该永远记住这一点。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3095, '简易卷轴', '啊，刚刚你跟天灾军团的那些行尸走肉作战的时候，有人送来了这根卷轴。我想这应该不是什么小事，因为卷轴上有战士训练师丹纳尔的印章。如果我是你的话，就会看看这上面说什么。', '阅读简易卷轴，然后和丧钟镇的丹纳尔·斯特恩谈一谈。', '随着你的经验越来越丰富，我会在这里不断对你进行训练……想来找我的话随时欢迎。我收费低廉，但你会发现我教你的每样东西都很值得学习。$B$B出发吧，去试试你的技术。你会学到越来越多的东西，其中有些我不能在这里和你讨论。希尔瓦娜斯需要你这样强大的战士，你将会是我们的支柱和脊骨。永远不要忘记这一点。', '啊，你来了，很好。我听说有一些人也逃脱了“死亡”，并纷纷涌入镇子里。或许我们有一天会重归安宁。$B$B你应该感谢希尔瓦娜斯，她给了你自由……心灵和肉体的自由。虽然你仍遭受着瘟疫的折磨，但你现在至少可以随自己的心愿来去了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3096, '密文卷轴', '啊，刚刚你跟天灾军团的那些行尸走肉作战的时候，有人送来了这根卷轴。我想这应该不是什么小事，因为卷轴上有盗贼训练师大卫·提亚斯的印章。如果我是你的话，就会看看这上面说什么。', '阅读密文卷轴，然后和丧钟镇的大卫·提亚斯谈一谈。', '我花了大部分的时间在旅馆里密切注视每一张新面孔，那些看起来充满了对未来的憧憬的新面孔。我会尽力教你一些东西，你任何时候都可以回来找我，那时我们就可以看看你是否已经为学习新技能做好准备了。', '你终于来了?很好，随着时间的流逝，我们会需要更多的盗贼。当巡影者认为时机合适的时候就会马上会找你，所以不要疏忽，不要做你可能会后悔的事情。他们需要有才能的密探……而不是小贼和蠢货。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3097, '神圣卷轴', '啊，刚刚你跟天灾军团的那些行尸走肉作战的时候，有人送来了这根卷轴。我想这应该不是什么小事，因为卷轴上有牧师训练师杜斯滕的印章。如果我是你的话，就会看看这上面说什么。', '阅读神圣卷轴，然后和丧钟镇教堂的黑暗牧师杜斯滕谈一谈。', '你唯一需要知道的是:我们是依靠毅力存活下来的……是我们对自己所具有的信心使我们与其它种族区分了开来，我们会以我们的力量为艾泽拉斯带来巨大的变化。弱者会依靠你，受歧视的人会崇拜你，无知的人会来寻求你的指引。我的责任是保证你在这种情况来临的时候就已经准备就绪了。你经验的积累到达一定程度后，就来找我。如果你准备好了，我会教你如何控制更为巨大的力量。', '啊，在火灾、瘟疫、暴动和其它更糟糕的灾难中，那些值得“信赖”的东西就成了我的希望。好吧，欢迎你，$C。请允许我花些时间解释一两件事，然后你再决定要在什么时候去寻找你生活的意义:圣光不再眷顾你，你祖先的精神只是一些缥缈的传说，扭曲虚空中的恶魔不再需要你。$B$B你能明白我的意思吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3098, '雕文卷轴', '啊，刚刚你跟天灾军团的那些行尸走肉作战的时候，有人送来了这根卷轴。我想这应该不是什么小事，因为卷轴上有法师训练师伊莎贝拉的印章。如果我是你的话，就会看看这上面说什么。', '阅读雕文卷轴，然后和丧钟镇教堂的伊莎贝拉谈一谈。', '当你成长到能够摧毁那些敢于与我们为敌的蠢货时，就回来找我。$N，魔法的规则会在你的身上产生效果。你会发现堕落的力量会犹如黑夜中的恶狼一般紧紧地跟随着你，你会发现魔法让你感到上瘾，但是这些都可以被控制和克服，因为只有你允许这种事情发生的时候，它们才会发生。$B$B现在就开始修行吧，当你感到自己变得强大的时候再回到我这里。', '$N，我知道你会来的。之所以这么说是并不是因为你无法按照自己的意志前进，而是因为我们具有相似的灵魂，我们都感受到了痛苦。现在我们都拥有了力量，能够把属于我们的土地、生命和命运掌握在自己手里的力量。但是你还要学很多的东西。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3099, '被污染的卷轴', '啊，刚刚你跟天灾军团的那些行尸走肉作战的时候，有人送来了这根卷轴。我想这应该不是什么小事，因为卷轴上有术士训练师马克希米林的印章。如果我是你的话，就会看看这上面说什么。', '阅读被污染的卷轴，然后和丧钟镇的马克希米林谈一谈。', '我说过，不管主人是谁，奴隶始终是奴隶，你还记得吗?我们都知道正是这种控制力―这种力量―驱动着我们。我们寻找可以为自己服务的仆人。我们知道自己是强大的，值得别人给我们更多尊重……所以现在我们要自己去寻得这种尊重。$B$B在这场斗争中，我会做你的盟友―为了我们的自由而斗争，为了能自由地寻找效忠我们的奴仆而斗争。当你感觉准备好了就回来找我，我会将我所知道的都教给你。', '欢迎你的到来，我的$G兄弟:姐妹;。我知道你会来的，只是个时间早晚的问题。$B$B你对我所说的事情感兴趣，对吗?我的话引起了你的共鸣……你的心知道我说的是真的。很好。$B$B不过你要知道，我并不是背叛了希尔瓦娜斯。就算她知道我说了些什么，她也会欣赏我的，因为正是她的信仰让被遗忘者走到了今天。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3100, '简要的信件', '在你跟那群狗头人作战的时候，有人让我把这个交给你。看起来这封信是我们这里的战士训练师莱尼写给你的，你最好先看看上面说了些什么。', '阅读简要的信件，然后与北郡修道院的莱尼·拜舍尔谈一谈。', '在这周围巡查一下，了解一下这块土地的情况吧，无论何时，只要你需要训练的话都可以回来找我。我一直都待在这里。$B$B白银之手骑士团为这块土地的安宁所做的努力相当令人满意，但当你遇到其它人的时候，我想你会发现他们都有些麻烦，需要帮助―你作为一个战士能够提供的帮助。祝你好运。', '啊，你收到我的信了，$N……太好了。$B$B最近有许多战士涌入艾尔文森林―对于暴风城来说，这真是个好消息，但这一地区的豺狼人和迪菲亚盗贼可不会喜欢这个消息。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3101, '圣洁信件', '在你跟那群狗头人作战的时候，有人让我把这个交给你。看起来这封信是我们这里的圣骑士训练师萨缪尔修士写给你的，你最好先看看上面说了些什么。', '阅读圣洁信件，然后和北郡修道院的萨缪尔修士谈一谈。', '现在，你还需要知道一些别的事情。你对于这个大陆上的其它人来说是一种象征―而你必须将之付诸于实践。圣光与你同在，在面对你的盟友和敌人的时候，你可以明显地感觉到它的存在。$B$B另外，随着你的智慧和力量的增长，你就会需要学习新的技能，这就是我待在这里的原因。当你感到自己有所成长之后就回到我这里来，我会教你一些新的东西。祝你好运……$C!', '你终于来了!我们终于见面了，欢迎你来到北郡。在你学习技艺的这段时间里，这里将是你的家。暴风城离这里并不远，不久之后，命运就将指引你到那里去。但是你一定要有耐心，一切都要慢慢来……白银之手骑士团的骑士。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3102, '密文信件', '在你跟那群狗头人作战的时候，有人让我把这个交给你。看起来这封信是我们这里的盗贼训练师乔里克写给你的，你最好先看看上面说了些什么。', '阅读密文信件，然后与北郡修道院的乔里克·克里丹谈一谈。', '你会发现掌握我们的技术有多少好处，$N。冒险家，军情七处……即使是迪菲亚兄弟会也想要在暴风城里安插一两个间谍。但你必须记住，你才是自己的老板。不要让任何人左右你，逼你做你不想做的事情!另外，一切都在我们的掌握中……至少我们可以在别人之前动手，你懂我的意思吗?$B$B无论如何，我只是想介绍一下我自己，让你知道如果你想接受训练的话，来这里找我就对了。任何时间都可以。', '你顺利地来到了这里，好像并没有多少人注意到你。这对我来说很好，因为我不想有很多人注意到我这里……越低调越好，我相信你会理解这一点。$B$B你有什么麻烦吗?我希望没有，不过很快一切都会改变的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3103, '神圣信件', '在你跟那群狗头人作战的时候，有人让我把这个交给你。看起来这封信是我们这里的牧师训练师安妮塔写给你的，你最好先看看上面说了些什么。', '阅读神圣信件，然后与北郡修道院的牧师安妮塔谈一谈。', '当你变得更加成熟之后，别忘了回来找我，我会尽力将我的知识传授于你。你要一直心存怜悯，让智慧指引你的道路。记住，只有通过我们的努力，这个世界才会变得更加美好。', '啊，你终于来了。我知道你会来的。圣光照耀着你，你选择了属于你的道路。这是个艰险的时代―艾泽拉斯大陆上仍有燃烧军团的存在，卡利姆多大陆上的人们在寻找生机，你能提供多少帮助就提供多少吧。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3104, '雕文信件', '在你跟那群狗头人作战的时候，有人让我把这个交给你。看起来这封信是我们这里的法师训练师凯尔东写给你的，你最好先看看上面说了些什么。', '阅读雕文信件，然后与北郡修道院的凯尔东·布雷曼谈一谈。', '哈哈，我知道我的那封信可以顺利地送到你手中。那就是说，你现在准备好了，是吗?准备好接受你的命运了?准备好挑战那些挡在你追求真\r\n知和力量的道路上的东西了?$B$B$N，我不会撒谎，将来，人们将对你倍感恐惧和崇敬。但你也要知道，我将在这里随时等候你来接受训练，我将伴随你不断成长。', '你好，$N。我是凯尔东。有什么我能帮你的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3105, '被污染的信件', '在你跟那群狗头人作战的时候，有人让我把这个交给你。看起来这封信是我们这里的术士训练师杜希拉写给你的，你最好先看看上面说了些什么。', '阅读被污染的信件，然后与北郡修道院旁边的杜希拉·拉萨雷谈一谈。', '随着你的力量不断增强，你会受到诱惑―你必须记住要控制自我。我不会骗人―魔法的腐化作用会影响到所有研究它的人，尤其会影响到那些与扭曲虚空里的生物打交道的人。你要保持耐心、谨慎……不过也不要压抑自己的雄心壮志。$B$B等你变得更强大的时候就回到我这里来，我会向你传授更多的术士技艺。', '啊，你来了，来得正好，$N。刚才有些守卫经过这里，用好奇的眼神看着我……这些可怜的凡人。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3106, '简易符文', '你刚才在外面忙碌的时候，有人让我把这个符文交给你。如果你有时间的话就看一下吧，好像是战士训练师斯兰·库尔曼写给你的，他就在安威玛尔里面。', '阅读简易符文，然后与寒脊山谷的斯兰·库尔曼谈一谈。', '你应该看到了，现在地精开始使用魔法而不是火枪，我们中的有些家伙开始像某些人类一样崇拜圣光，另外还有那些该死的石腭怪，不久之后你就会对他们有深入的了解，但现在你需要明白的是，我在这里是为了帮助你。$B$B我会在这里教导你如何成为一名真正的战士。不管什么时候，只要你想要接受训练，就回来找我，到时我会看看我能做些什么的。', '该死的大冷天，看起来这大雪永远也化不掉了，$N。$B$B你也许已经注意到了，我们的城市中居住着许多地精。这是因为他们自己的家园被占据了。不要到处说这些话，我也不会因为他们和我们住在一起而责备他们―如果黑铁矮人或者别的什么该死的家伙占据了铁炉堡的话，我也会暴跳如雷的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3107, '神圣符文', '你刚才在外面忙碌的时候，有人让我把这个符文交给你。如果你有时间的话就看一下吧，好像是圣骑士训练师布罗莫斯写给你的，他就在安威玛尔里面。', '阅读神圣符文，然后与寒脊山谷的布罗莫斯·格鲁诺尔谈一谈。', '人类的骑士团让我们了解到了很多关于圣光的东西，还让我们了解到保护整个艾泽拉斯的使命对于他们有多么重要。我们对于这种强烈的使命感以及他们的献身精神感到崇敬不已。$B$B我们俩会在一起工作一段时间，当你准备好了之后就来找我，然后看看我能教你点什么。现在还不能让你毫无准备地踏入这个世界，不是吗?', '你终于来了!一点都没有拖延。寒脊山谷中还有很多事要做，我需要你的帮助，你也需要我的帮助!$B$B你现在是白银之手骑士团的骑士了，准备承担你的责任吧。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3108, '风蚀符文', '你刚才在外面忙碌的时候，有人让我把这个符文交给你。如果你有时间的话就看一下吧，好像是猎人训练师索加斯写给你的，他就在安威玛尔里面。', '阅读风蚀符文，然后与寒脊山谷的索加斯·格瑞姆森谈一谈。', '你所要牢记的一件事就是:你要对这个世界保持尊重。帮助你作战的野兽，你武器上闪烁的光芒，沉甸甸的弹药袋，甚至吹过你脸庞的寒风的力度，所有的这些你都必须了若指掌。$B$B我会尽我所能地帮助你，一旦你觉得准备好了，就回来和我谈谈，我会对你进行训练。', '你终于来了!很高兴见到你!你最好不是跟在我身后找到这里来的，哈哈!$B$B我们这个职业拥有优良的传统，$N。你需要学习一些关于这片土地的东西，比如学习如何在山岭中追踪一只熊。即使简单的生存技能也需要投入很多的勇气和智慧才能熟练掌握。你认为你能够胜任吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3109, '密文符文', '你刚才在外面忙碌的时候，有人让我把这个符文交给你。如果你有时间的话就看一下吧，好像是盗贼训练师索姆写给你的，他就在安威玛尔里面。', '阅读密文符文，然后与寒脊山谷的索姆·哈格林谈一谈。', '无论如何，当你在寒脊山谷附近开始冒险时，你会需要接受一些训练。只管找我就行了，我会尽力帮助你学习更多的技巧。你知道，这些技巧可以让你生存下去，还能帮你赚点小钱。$B$B多关心一下我们的地精朋友……诺姆瑞根的陷落让他们处于很不利的位置，他们需要我们的帮助才能度过这个难关。', '你终于来了!太好了!$B$B我们最近会有一系列的行动，所以我很高兴邀请铁炉堡的另一个氏族加入我们。我们中有太多的人因为自己的品味而向往魔法之类的东西，我对于他们和他们的信仰并没有什么要说的，但是只有你手中冰冷的剑和让你避开亮光的阴影才是最好的，你明白我什么意思吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3110, '神圣符文', '你刚才在外面忙碌的时候，有人让我把这个符文交给你。如果你有时间的话就看一下吧，好像是牧师训练师布兰斯托写给你的，他就在安威玛尔里面。', '阅读神圣符文，然后与安威玛尔的布兰斯托·卡尔德谈一谈。', '我可以让你掌握更多的知识，当你准备好了之后就回到我这里来，或许我可以教你一两个新的法术，这样就能保护寒脊山谷免受该死的石腭怪的袭击。$B$B圣光与你同在，所有铁炉堡的同胞都与你同在，$N。', '啊!你终于来了，$N!太好了!$B$B我本想说，我几乎都要失去信心的时候，你就来了……明白吗，失去信心?只是开玩笑啦，$伙计:小姑娘;……啊，别介意。总之你不是来听我说蹩脚笑话的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3112, '简易备忘录', '你刚才在外面忙碌的时候，有人让我把这个备忘录交给你。如果你有时间的话就看一下吧，好像是战士训练师斯兰·库尔曼写给你的，他就在安威玛尔里面。', '阅读简易备忘录，然后与寒脊山谷的斯兰·库尔曼谈一谈。', '好吧，我知道你们的头等大事是什么，我保证我会竭尽全力帮助你和你的同胞们为夺回家园做好准备……这就是我要做的。$B$B无论什么时候，如果你想要接受训练就回来找我，我会很高兴和你分享我的知识。要接受我的训练是要花钱的，但也不会很贵。祝你好运。', '啊，又一个身负重任的地精拿来了备忘录……真有趣。$B$B不，不，小家伙，我不是在嘲笑你，我尊重你的顽强，真的。要是铁炉堡被黑铁矮人占据的话我同样也会感到愤怒，所以不要认为我无法体会你的困境……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3113, '密文备忘录', '你刚才在外面忙碌的时候，有人让我把这个备忘录交给你。如果你有时间的话就看一下吧，好像是盗贼训练师索姆写给你的，他就在安威玛尔里面。', '阅读密文备忘录，然后与寒脊山谷的索姆·哈格林谈一谈。', '我在这里一直非常小心谨慎，免得出什么岔子，但如果你需要什么东西，随便什么时候都可以回来找我。$B$B你和我对此应该达成一个共识。我们知道在这种情况下你只能信赖自己人……我们现在就是这种情况，对吧?不要管诺姆瑞根的那些家伙，不要管有什么东西阻挡我们的道路，我们至少能互相扶持，对吧?', '很高兴看到你带着我的便笺回来。抱歉，我把它伪装成一份高级公函……我并没有恶意，我相信包括我们两个在内的所有盗贼都应该紧密地团结在一起。$B$B许多人都不认为我们这类人聚集在同一个城市里是件好事，但我认为我们合作得很愉快，你说呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3114, '雕文备忘录', '你刚才在外面忙碌的时候，有人让我把这个备忘录交给你。如果你有时间的话就看一下吧，好像是法师训练师玛瑞克写给你的，他就在安威玛尔里面。', '阅读雕文备忘录，然后与寒脊山谷上的安威玛尔镇里的玛瑞克·斯托纳尔谈一谈。', '哦，对!魔法……当然。$B$B以下这几点是你必须知道的，$N:首先，不要惹太多麻烦;其次，记得把钱省下来给我买麦芽酒喝……还有那些你想要学习的法术也不是白送的;还有，记得离诺姆瑞根远一些;最后，好好享受你的每一天吧!如果你想接受训练或者有什么别的事的话，可以随时来这里找我。', '耶，看看这是谁，一个$r?如果你不介意的话，请大点声说话。我喝麦芽酒之后耳朵有点不好使。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3115, '被污染的备忘录', '你刚才在外面忙碌的时候，有人让我把这个备忘录交给你。如果你有时间的话就看一下吧，好像是术士训练师阿拉玛尔写给你的，他就在安威玛尔里面。', '阅读被污染的备忘录，然后寒脊山谷上的安威玛尔镇里的阿拉玛尔·格里姆谈一谈。', '但那些都不重要，重要的是你要有自己的信仰!你要知道力量来自哪里，你要意识到结交盟友需要足够的……谨慎。我们需要特别的盟友，绝对忠诚的盟友，即使丢了性命也不会让我们失望的盟友。$B$B这就是我站在这里的原因，$N。我可以训练你，让你掌握这些特殊的力量。别忘了经常来找我，这样我就可以根据情况来向你传授更多的法术。', '太棒了!你显然收到了我的备忘录。$B$B$N，忽视你周围那些愚蠢的家伙吧。圣光?!剑和盾?!这不是像我们这样意志宽广的强者所应走的路。看看那些“普通”的魔法把我们的家园糟踏成了什么样子。还有那些该死的技工，我们这一族几乎都要灭绝了。现在我们不得不依靠矮人过活，而他们却把时间花在跟那些人类打交道上，而不是帮助我们重建家园。我们看起来就像是二等公民，说真的，你有没有注意过他们打量我们时的那模样?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3116, '简易符记', '我们的战士训练师奥莉希亚派来的信使把这块符记交给了我，看起来奥利希亚有话要跟你说，看看符记上写了些什么，然后把符记给她带去吧。', '阅读简易符记，然后与幽影谷的奥莉希亚谈一谈。', '不久之后，你就会看到很多其它种族的人出现在我们的家园里，世界之树的枝干上―不要因此而报有任何偏见。我们应该欢迎他们，他们会在可能的情况下帮助我们。当然，我不能保证他们都是无私的人，但是我们应该给予他们足够的信任。$B$B不过现在这些都不重要。现在我们需要集中精力来关注你，你究竟能怎样帮助我们的同胞。我将把你训练成一名强壮的战士。别忘了随时回来找我，我会尽我所能地帮助你。', '你终于来了，我很高兴。$B$B在过去的几年中发生了很多事，泰达希尔的创建，各地森林生物的堕落，许多原本我们认为早已不存在的地方被重新发现，比如菲拉斯……太多太多事了，就在这短短的几年中。但是这些只是我们之所以在这里的一部分理由，我们最重要职责是要保护我们的同胞免受邪恶势力的伤害。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3117, '风化符记', '我们的猎人训练师阿亚娜派来的信使把这块符记交给了我，看起来阿亚娜有话要跟你说，看看符记上写了些什么，然后把符记给她带去吧。', '阅读风化符记，然后与奥达希尔里和阿亚娜·远途谈一谈。', '等你在幽影谷得到足够的历练之后再过来找我―我会帮你更好地了解作为猎人的职责，以及你所拥有的能力。$B$B这是个危机四伏的时代，$N，不要掉以轻心，这个世界比你想象中的更危险。让艾露恩指引你前进，我在这里等你。', '你来啦，很快嘛，$N。欢迎来到幽影谷。$B$B我相信我的符记送到你手里的时候，你的精神和身体状况都还好吧?$B$B我曾经说过，我是来训练你当一个好猎人的，猎人的意义在于驯服野兽，让它们在战斗中帮助你;也在于准确无误地使用弓箭;还有尊敬这片我们称之为家的土地，以及比家园更广袤的世界。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3118, '密文符记', '我们的盗贼训练师弗拉胡恩派来的信使把这块符记交给了我，看起来弗拉胡恩有话要跟你说，看看符记上写了些什么，然后把符记给他带去吧。', '阅读密文符记，然后与幽影谷的弗拉胡恩·影语者谈一谈。', '直到那时，我才知道在这个脆弱的年代更需要自己人之间的团结帮助。与其它种族的和平互助可以瞬间化为乌有，很多人都说部落的成员正试图播种更多不信任的种子，你要记住。$B$B如果你感到自己变得更加强大之后就来我这里，我会对你进行一些训练。最重要的是，你要知道如何使用自己最称手的武器，如果最大限度地发挥自己的潜能。', '你好，$N。很高兴你找到了我。我还在想你大概迷路了。$B$B自从我给你符记之后，幽影谷没有发生什么新的事情，但我会让你去收集一些资讯。如果愿意的话，你可以去和奥达希尔的其它居民谈谈。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3119, '神圣符记', '我们的牧师训练师珊达派来的信使把这块符记交给了我，看起来珊达有话要跟你说，看看符记上写了些什么，然后把符记给她带去吧。', '阅读神圣符记，然后与奥达希尔的珊达谈一谈。', '现在不要关心泰达希尔以外的地方了，以后你会有时间去关心那些事情的。去和幽影谷里的其它居民谈谈―他们可以告诉你更多事情。尽你所能地帮助他们，无论何时，如果你觉得自己需要进行更多训练，就回来找我吧，我会尽我所能帮助你的。', '我很高兴你这么快就来了，$N。欢迎你。$B$B或许你已经听说过，整个泰达希尔都充斥着来来往往的旅人，甚至还有一些联盟的成员也被允许攀上泰达希尔的主冠来和那些准备外出冒险的卡多雷会面。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3120, '绿色符记', '我们的德鲁伊训练师玛丹特派来的信使把这块符记交给了我，看起来玛丹特有话要跟你说，看看符记上写了些什么，然后把符记给他带去吧。', '阅读绿色符记，然后与幽影谷中的奥达希尔顶端的玛丹特·硬木谈一谈。', '从现在开始，我将是你的导师。我的职责要求我不仅要教授你如何与精灵进行交流，还要告诉你翡翠梦境的错综复杂和其中所蕴藏的秘密。$B$B随着你的不断成长，你会了解更多关于我们沉睡的秘密。但是在此之前，别忘了经常回来和我谈谈，我会尽力把我们这个职业所需要学习的东西都传授给你。', '啊，年轻的$C。我看得出你非常渴望继续你的历练，这很好。$B$B我想要知道，你是否已经在翡翠梦境中待了很长时间呢?也许你还没有为此作好准备……至少现在没有，我敢肯定。$B$B不管怎么样，在那一天到来之前，我们还有很多其它的事情要讨论。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3121, '奇怪的要求', '在莫沙彻营地北边拉瑞斯小亭的夏拉什·火刃有我所需要的东西！他调配出了一种混合物，我需要用它来……好吧，你以后会知道的。$B$B快点出发，去找夏拉什。拿着这个东西，这是一颗皱缩的徽记，我答应夏拉什用此来交换草药。这是某个可怜侏儒的徽记，我在森林里撞见了他，然后就……我敢说夏拉什会很高兴得到这个东西的。$B$B你可以在暗影裂谷里找到夏拉什。', '将皱缩的徽记交给拉瑞斯小亭的夏拉什·火刃。', '我正在等尤克里送这个过来……$B$B等我给你拿草药，这是我为他的……嗯，实验……准备的……', '有事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3122, '向巫医尤克里回复', '拿着这些草药，$N。把它们交给巫医尤克里。$B$B请告诉他，我对那些皱缩的徽记很满意。', '将尼尔鲁的草药包送给菲拉斯的巫医尤克里。', '这个就是我准备灵魂精华容器所必需的东西，$N。我们马上就可以看到我最新研究的咒语是否具有我所期望的威力了。$B$B请稍等一会儿，我必须举行仪式，然后使用这些草药。', '你见过瑟拉希了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3123, '测试容器', '这是一个测试，对我将要进行的仪式和你的能力来说都是一个测试。拿着这个容器，$N。你可以用它将一个生物的灵魂禁锢起来。$B$B到东边的荒野中去寻找野兽吧。那些铁鬃熊，还有那些长牙奔跑者都是你的目标，$N。杀死它们，在它们的灵魂逃跑之前用灵魂精华容器把它们收起来。', '去杀掉10头铁鬃熊或是长牙奔跑者，然后使用灵魂精华容器捕获它们的灵魂。$B$B将灵魂精华容器和10个野兽灵魂精华交给菲拉斯的巫医尤克里。', '如果一个生物因为暴力而死去，那它的灵魂精华就会逃脱，而且会伺机复仇。按照你所使用的方法，这些生物的灵魂精华就无法逃脱，然后我们就可以随便利用它们了。', '你禁锢那些野兽的灵魂了吗?', '', '去菲拉斯找莫沙彻营地的巫医尤克里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3124, '角鹰兽灵魂精华', '既然你已经证明了自己是个值得信赖的$c，而且还具有使用灵魂精华容器的能力，那么现在我希望你能帮我抓住另一种生物。$B$B角鹰兽多年来一直是暗夜精灵的忠实伙伴，它们的灵魂忠实而又坚定。$B$B去杀掉十只乱羽角鹰兽，动作要快，将它的灵魂关在容器里，这样它的灵魂精华才可以保存下来。你可以在高原荒野一带找到这种角鹰兽，从这里一直向南走就到了。', '杀掉10只任意种类的乱羽角鹰兽，然后用灵魂精华容器捕获它们的灵魂。', '杀掉一只动物之后，如果我们让它的灵魂精华逃跑了，它就会变成一个更强大的生物，它的报复会使我们一直处于危险中。$B$B我交给你的工作非常危险，$N，但是你再一次成功地完成了任务。', '你捕获那些角鹰兽的灵魂了吗?', '', '去菲拉斯找莫沙彻营地的巫医尤克里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3125, '精灵龙灵魂精华', '$N，下一步我必须让你捕获一种看上去可能很脆弱，但却有着我们真正需要的强大精神力量的生物。我所说的就是精灵龙，它们是暗夜精灵的伙伴。我们必须抓一只精灵龙来进行研究，这样部落也可以从这种精神力量中获益。$B$B我们需要它们的灵魂精华，$N。杀掉八只小精龙或精龙，并俘获它们的灵魂。从这里向西就可以找到它们。', '杀掉8只精龙或小精龙，然后用灵魂精华容器捕获它们的灵魂。', '谢谢你，$N。现在精灵龙的灵魂力量可以为我们所用了。$B$B我希望你能再为我完成另一个任务。', '你捕获那些精灵龙的灵魂了吗?', '', '去菲拉斯找莫沙彻营地的巫医尤克里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3126, '树人灵魂精华', '在森林中到处游荡的森林漫游者是我们的下一个目标，$N。暗夜精灵已经和树人结成联盟，共同与部落为敌。它们的行动也许很缓慢，但它们却是强大的卫士。$B$B我们马上就能让这种力量为我们所用。$B$B去找到三个森林漫游者，然后用灵魂精华容器将它们的灵魂捕获。', '杀掉3个森林漫游者，然后用灵魂精华容器捕获它们的灵魂。', '谢谢你，$N。我们的灵魂精华几乎收集全了。', '你捕获那些森林漫游者的灵魂了吗?', '', '去菲拉斯找莫沙彻营地的巫医尤克里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3127, '山岭巨人灵魂精华', '我给你的最后一项任务是到西北边去找到我们最后的敌人。$B$B在燃烧军团入侵的时候，山岭巨人帮助了暗夜精灵。在你穿过他们的领地时，你可以看到他们那庞大的身躯，感受到大地在随着他们的脚步声震动。$B$B我非常想得到如此庞大身躯下所蕴藏的力量，去杀掉七个山岭巨人，然后用灵魂精华容器将他们强大的灵魂给我带回来。', '杀掉7个大地行者或者峭壁巨人，然后用灵魂精华容器捕获它们的灵魂。', '$N，想象一下我们现在拥有了什么吧。有了你帮我收集到的材料，我就能将这些生物的灵魂精华永远囚禁起来。', '你捕获那些山岭巨人的灵魂了吗?', '', '去菲拉斯找莫沙彻营地的巫医尤克里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3128, '天然材料', '我需要一些特定的材料来完成我的工作……你可以把这件事情与我要给你的其它几个任务一起完成了。$B$B我需要菲拉斯树人身上的一段断裂的原木，西边的那些山岭巨人和精灵龙身上的包壳矿石，还有从辛特兰的枭兽或者菲拉斯的角鹰兽身上找到的有弹性的肌腱。最后，我还需要大量的金属碎片，这些碎片可以从我刚才提到过的这些生物身上找到。', '为莫沙彻营地的巫医尤克里收集2根断裂的原木、6颗包壳矿石、20片有弹性的肌腱和40块金属碎片。', '太好了!这些材料和灵魂精华组合起来就应该能达到我们所期望的效果。', '你收集到我需要的材料了吗?', '', '去菲拉斯找莫沙彻营地的巫医尤克里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3141, '洛拉姆斯', '你想和恶魔战斗？听听我的故事会对你有好处。', '听洛拉姆斯·萨里比迪斯讲述他的故事。', '事情就是这样……', '不要打断我，$r。', '洛拉姆斯的故事', '去艾萨拉找风暴海湾的洛拉姆斯·萨里比迪斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3161, '加兹瑞迪安', '$N，我是一个科学家，但是我真正的身份其实是一个赏金猎人！$B$B很久以前，当巨魔还在片土地上横行的时候，他们制作了很多以加兹瑞拉为原型的饰物，并把它作为偶像膜拜。那些装饰物上的形象被称为“加兹瑞迪安”，也就是九头蛇之神的意思。$B$B我自己找到了一些这种饰物，但是我需要更多来进行研究——也许你可以帮我搞到一些？$B$B我甚至发明了一个可以帮助你寻找加兹瑞迪安的装置！把这件头盔拿去，开始寻找吧！', '塔纳利斯的玛尔冯·瑞文斯克要你收集30件加兹瑞迪安饰物。', '太好了，这些装饰物正好可以用在我的研究中。非常感谢你的帮助，$N。$B$B哦，能不能把盔帽也还给我?', '你的搜寻工作进行得怎么样了?$B$B塔纳利斯到处都是加兹瑞迪安饰物，$N，所以请继续搜索吧!', '', '去塔纳利斯找破碎石柱的玛尔冯·瑞文斯克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3181, '玛尔戈的巨角', '这根巨大的角上有许多擦痕和裂缝，还有一块金属物体嵌在粗糙的表面上。$B$B仔细检查了一番之后，你发现这块金属实际上是一把断掉的斧头。金属上刻着一行字：$B$B巡山人贝波蒂的财产。$B$B当你试着把斧头拔出来的时候，它一下子变成了无数的碎片。$B$B真糟糕！', '将玛尔戈的巨角交给巡山人贝波蒂。', '你拿到的是什么啊?那很明显是假的!$B$B我亲眼见过玛尔戈，我知道她的角至少比你手上拿着的那个大了八倍，$N。你八成是从贫瘠之地的某只雷角蜥蜴身上弄到这根角的。不，$g先生:女士;，你骗不了贝波蒂的!', '不，我不会把门打开的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3182, '证明信', '你指望我会相信这样一个故事？真正的角怎么会是这个样子？$B$B听着，把这个明显是赝品的东西拿给铁炉堡的索里奥斯馆长看看。如果他能证明你的话是真的，那么你就能收到一份证明。把那份证明拿回来给我，我就给你一把灼热峡谷的钥匙。$B$B快动身去找索里奥斯馆长！', '把玛尔戈的巨角交给铁炉堡的索里奥斯馆长。', '这是什么?$B$B哦，我的天，我简直不敢相信!你知道你手上拿的是什么吗，$C?这是玛尔戈的角!玛尔戈是所有涉足灼热峡谷的考古学家的噩梦。$B$B你可以把它给我吗?', '你好啊，年轻的$g先生:女士;。你想要参观一下博物馆吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3201, '馆长的证明！', '我真不敢相信贝波蒂居然怀疑这支角的真实性。现在就你和我，我不妨直说，我认为她纯粹是嫉妒！我知道她很想亲手杀了那只野兽，你的“意外的成功”让她的美梦破灭了。$B$B那么，你需要证明是吗？你对博物馆的贡献很大，这不是问题。$B$B<索里奥斯馆长从一大堆文件中翻找东西。>$B$B好了！你可以把它拿去交给贝波蒂。', '把索里奥斯的证明信交给巡山人贝波蒂。', '我不知道像你这么弱的$r是怎么征服玛尔戈的，但是我说话算话。这是钥匙。$B$B如果之后你出了什么事，那就是你自己的问题了。', '我不相信。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3281, '被偷走的银币', '你杀了迅猛龙，很好，但是它们偷走的那些银币必须要找回来！我接到报告说有大量的迅猛龙聚集在棘齿城南面，那里现在被称为迅猛龙平原，它们八成是把银币藏在那里了。$B$B到那个迅猛龙平原去找到被偷走的银币，然后把银币送还到我这里来。', '把被偷走的银币交给十字路口的加兹罗格。', '啊哈!这么说来迅猛龙的确是把银币藏在他们的巢穴里。真难相信这些野兽居然会对银币如此感到兴趣，也许它们真的有一些智商!$B$B谢谢你，$N。请收下这个，这是我们对你的奖励，另外我代表十字路口的守卫感谢你，因为你的辛苦，他们下个月的薪水有着落了。', '你拿到银币了吗?', '', '去找贫瘠之地的加兹罗格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3301, '茉拉·符文图腾', '我的族友茉拉·符文图腾去了银松森林，她去那里是为了帮助我们的亡灵盟友。银松森林状况不佳，那是一片濒死的森林，茉拉希望通过自己的努力给银松森林带来新的活力。也许在贫瘠之地找到的这种奇怪的生命形式能够对她在银松森林的工作有所帮助。$B$B把你收集到的龟壳样品交给她吧，茉拉一般都在瑟伯切尔待着。如果运气够好的话，这些贝壳可以帮她找到治愈那片濒死之地的方法。', '和银松森林瑟伯切尔的茉拉·符文图腾谈一谈。', '啊，这是什么?这个贝壳看起来闪闪发光，似乎还孕育着生命。太神奇了!我必须对它进行一番仔细的研究。$B$B谢谢你，$N。如果运气不错的话，我应该能从中发现治愈银松森林的方法。', '我可以闻到你身上贫瘠之地的尘土味道，$C。你看来是远道而来的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3321, '秘银会的认可', '你为秘银会做了很多事情，$N。像你这样无私而纯粹地奉献并不是人人都能做到的。在我和加尔文的心中，你无疑已经成为我们的一员了。$B$B所以我觉得你应该获得一些小奖励。其实也没什么，也就是一个饰品，我想你应该很清楚它的意义，而且我相信它应该就是你到我们这里来的最初目的。', '等待特伦顿完成他的工作。', '起来吧，$N，你已经正式成为秘银会的铁匠了。', '今天，我们要庆祝你正式加入秘银会。', '等待特伦顿完成工作', '去找塔纳利斯的特伦顿·轻锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3341, '寒冰之王', '在贫瘠之地有一处藤蔓交错的地方，那里被称为剃刀高地。我们很久以前派去的斥候就已经发现那里的情况有些不对劲了，最近的发现表明那里的情况变得更加糟糕了……$B$B剃刀高地的野猪人和亡灵天灾结成了同盟。有个名叫寒冰之王亚门纳尔的巫妖指挥着它们的每一步行动。$B$B亚门纳尔与耐奥祖有着直接的心灵感应联系，我们必须切断这样的联系，$N。我们必须干掉寒冰之王。', '安德鲁·布隆奈尔要你杀了寒冰之王亚门纳尔并将其头骨带回来。', '$N，一个巫妖的忠诚度是毋庸置疑的。让他们知道这样的忠诚只会给他们带来毁灭。', '这件事非常重要，$N。我们必须阻止天灾军团获得其它方面支持的行动。', '', '转至幽暗城，去找魔法区的安德鲁·布隆奈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3361, '逃难者的困境', '我们把穴居人赶出了诺莫瑞根，但是那里变得一团糟！我们的家园现在充满了辐射，我们侏儒也分布在丹莫洛的各个角落。$B$B在逃避辐射的过程中，我丢失了所有的东西，那可都是我的私人财产！是巨魔抢走了我的东西，他们抢走了我的箱子，我的盒子，还有我的一桶螺钉！巨魔抢到东西后就一溜烟跑回他们的营地去了，就在安威玛尔的西南边。$B$B我不是冒险者——你能帮我把东西找回来吗？', '把菲利克斯的盒子、菲利克斯的箱子和菲利克斯的螺钉桶交给安威玛尔的菲利克斯。', '太好了，你找到我的东西了!你真是我的救星!这给你，这些报酬虽然不多，但是它们表达了我对你的谢意!谢谢你!', '天啊，$N，这个城镇并不适合我这种人。这里讨厌的怪物简直和事故之前诺姆瑞根里的一样多!$B$B你拿到我的东西了吗?如果没有，天知道那些该死的巨魔把我的东西怎么了……', '', '去丹莫罗找寒脊山小径的菲利克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3362, '灌木谷', '你有没有去过灌木谷？那是个非常危险的地方，$N。$B$B那里到处都是奇怪的野兽，我根本不会冒险去靠近它们！那些野兽应该是被称作长瘤的灌木兽和灌木塑根者……$B$B不管怎么样，我想要亲自到那个山谷里去看一看，但是那么多的灌木兽在山谷里活动，我可不想去送死。但是现在你来了——如果你能帮我清除一些灌木兽的话，也许我就能去一趟了。$N，我想你应该能帮忙的吧？帮帮我，好不好？', '加基森的特兰雷克要你杀掉8只长瘤的灌木兽和8只灌木塑根者。', '它们有那么大吗?也许我得重新考虑一下我的计画……$B$B但是你确实完成了任务，这是我承诺要给你的。', '我想要仔细观察一下那个山谷里的仙人掌……所以打架的时候别把它们都给砸了，好吗?', '', '去找塔纳利斯的特兰雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3363, '被腐化的轻歌花', '', '', '你将一些塞纳里奥植物药膏涂在了这株轻歌花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的轻歌花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3364, '热酒快递', '嘿！我之前应该把这可口的热酒交给安威玛尔的德南·弗卡特，现在我终于想起来该把东西送过去了！但是我肯定没法在酒变凉之前把酒送给他！$B$B你看起来挺灵敏的，也许你能……这杯热酒只能保温几分钟，而且德南要的可不是冰镇热酒，所以你一定要赶快！安威玛尔就在这里的东北面，那个在山壁上凿出来的大洞里。$B$B不要忘了把我的杯子带回来！', '在热酒冷掉之前把它交给安威玛尔的德南·弗卡特。', '啊，太好了，这东西看起来很不错。请稍等片刻，让我享受这杯热腾腾的热酒吧!', '是的，我是德南.弗卡特。你有东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3365, '归还酒杯', '太正点了！没有什么别的东西能像这杯滚烫的热酒那样，在这个大冬天里温暖你的灵魂了！$B$B拿着这个，$N——帮个忙，把这个空杯子还给诺里斯，现在就去。', '把诺里斯的杯子还给寒脊山谷的诺里斯·激流。', '太棒了，$N!如果你知道我以前碰到过多少个忘记把杯子还给我的快递，那你一定会大吃一惊的。杯子不是从树上长出来的，', '我相信你已经及时地把热腾腾的热酒交给德南了!杯子带回来了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3367, '苏塔拉之石', '<杜里奥斯痛苦地呻吟着。>$B$B我受了重伤，$c。我感觉……头重脚轻……世界在旋转……身体里面在出血。$B$B我必须回到铁炉堡，帮帮我，$N……', '帮助杜里奥斯回到铁炉堡。', '当杜里奥斯遭到枪击的时候，这封信掉了下来。', '我想我到不了铁炉堡了……', '护送杜里奥斯', '去找灼热峡谷的烧焦的信件。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3368, '苏塔拉之石', '我的好兄弟：$B$B如果你读到了这封信，那我已经不在这个世界上了。至于这封信是怎样到你手中的，我就不得而知了。 $B$B关于那些石头：它们确实存在，而且在黑铁矮人手里。他们的领袖，黑衣拉索里克正在使用石头的力量来禁锢我们勘探队的同伴。他们被带到了大熔炉那里。他们的意志已经被扭曲，被迫不分昼夜地干活以完成一个名叫奥比斯顿的东西。$B$B帮帮他们，我的兄弟。这是一个死者最后的希望了。$B$B——杜里奥斯', '把烧焦的信件交给铁炉堡的索里奥斯，他在探险者大厅里。', '<索里奥斯抹干了脸上的泪水。>$B$B以圣光的名义，他的遗愿一定会实现。我发誓。', '<索里奥斯抽泣着。>', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3369, '在噩梦中', '这块碎片中蕴含有巨大的秘密，它是翡翠梦境的精华所在。然而，我从这片碎片中看到的却不是梦境，而是一种噩梦。$B$B我并不是想要警告你什么，$N，但是我希望你尽快把这个碎片送到一位睿智的德鲁伊手里。$B$B到雷霆崖的长者高地去找哈缪尔·符文图腾，我不能再多说了。', '把噩梦碎片交给长者高地的哈缪尔·符文图腾。', '菲拉派你来的?好吧，让我们来看看那块她避而不谈的裂片……$B$B<哈缪尔看了看那块裂片。>$B$B哦……我不能……好吧。$B$B$N，感谢你把这个送到我这里，但我还是建议你不要提到这块裂片，这些事情应该由塞纳里奥的德依鲁们自己来面对的。$B$B这么说吧，翡翠梦境中的东西与我们想象中的并不一样……$B$B也许在未来的某一天，我们的命运会再次交会。', '我能帮你什么忙吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3370, '在噩梦中', '这块碎片中蕴含有巨大的秘密，它是翡翠梦境的精华所在。然而，我从这片碎片中看到的却不是梦境，而是一种噩梦。$B$B我并不是想要警告你什么，$N，但是我希望你尽快把这个碎片送到一位睿智的德鲁伊手里。$B$B到达纳苏斯的塞纳里奥议会去找玛斯雷·驭熊者，我不能再多说了。', '把噩梦碎片交给达纳苏斯的玛斯雷·驭熊者。', '菲拉派你来的?好吧，让我们来看看那块她避而不谈的裂片……$B$B<玛斯雷往那块裂片里看了一眼。>$B$B哦……我不能……好吧。$B$B$N，感谢你把这个送到我这里，但我还是建议你不要提到这块裂片，这些事情应该由塞纳里奥的德依鲁们自己来面对的。$B$B这么说吧，翡翠梦境中的东西与我们想象中的并不一样……$B$B也许在未来的某一天，我们的命运会再次交会。', '我能帮你什么忙吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3372, '释放他们', '释放他们，$c。即使他们的肉体已经不复存在，苏塔拉的力量也会让他们去完成自己的使命。$B$B苏塔拉祭坛是关键。到这里的北边去，在洞穴上面的山顶……暮光之锤守卫着一件古器。拿到它，把它放在苏塔拉祭坛上。$B$B<濒死的考古学家倒下了。>', '到北方去找到被暮光之锤守卫着的神秘的古器，然后把它带到熔渣之池的苏塔纳祭坛上。', '你把神秘的古器放在桑塔拉祭坛上。', '祭坛是空的。', '', '去灼热峡谷找观火岭的苏塔拉祭坛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3373, '伊兰尼库斯精华', '当你接触宝石的时候，一个雄浑的声音回响在你的脑际。$B$B“凡人，请聆听我的请求。我是绿龙军团的伊兰尼库斯，这座被诅咒的神庙的守护者。我的任务是阻止这些巨魔召唤出上古的邪神，但是现在看来，我失败了。我把我的精华力量注入了这块宝石中，我能感到自己对梦境的控制正在陷入混乱。请你帮帮我——把这块宝石放入我的巢穴中，让那里的魔法净化我心智中的污点，那样我才能够安息。”', '把伊兰尼库斯精华放在精华之泉里，精华之泉就在沉没的神庙中，伊兰尼库斯的巢穴里。', '你把宝石放入精华之泉中。$B$B“感谢你，凡人，你已经―不……不，不可能!不!这个可恶的古神的堕落力量已经污染了绿龙军团的精华之泉的圣洁!不，不要，我感到自己的精华正在从我的身上剥离!痛苦!我感到一个永恒的梦魇已经控制了我……”$B$B“凡人，我求求你!去找绿龙族的一员来阻止这一切……帮帮我……我被拴在黑暗之中……永远陷于痛苦……请不要再折磨我了……”$B$B', '当你接近伊兰尼库斯告诉你的精华之泉的时候，他的声音再次出现在你的脑海中。$B$B“是的，凡人，这个精华之泉将会救赎我留在这颗宝石内的心智中未污染的部分。将宝石放在泉水中，然后让绿龙族的魔法净化我身上的堕落和污染元素。只有这样我才能得到真正的解脱，只有这样绿龙军团才能够获得管理阿塔莱的权利。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3374, '伊兰尼库斯精华', '你碰触了一下誓言石，伊萨里奥斯的声音通过这块石头直接和你进行对话。$B$B“一旦你拿起誓言石，就表示你会帮助我，并且准备帮助伊瑟拉的绿龙拯救伊兰尼库斯的灵魂。我们所要做的第一件事情，就是将禁锢着伊兰尼库斯自由心智的宝石交给我。”$B$B“快一点吧，$N，我们要共同努力来拯救一个值得拯救的灵魂。”', '把伊瑟拉巨龙军团的誓言石和被禁锢的伊兰尼库斯精华交给悲伤沼泽的伊萨里奥斯。在那里你可以决定是否要帮助伊瑟拉的绿龙军团。', '你已经做出了选择，我们这就开始吧。你的选择现在在我看来是正确的;你将要采取的行动和所得到的结果将会影响我们是否继续这件事情。', '我们已经到了，$N，到了另一个十字路口。是该作出个选择的时候了。凡人，你的选择是什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3375, '占卜之瓶', '嗯……你还需要一个占卜之瓶？你在开玩笑吗？你用我给你的那瓶水干了些什么？！$c，我们有很多事情要做。那些东西可不是长在树上随手可得的！实际上，我希望它们确实如此，因为那样的话，我只需去随手摘一个就可以摆平这个问题，因为我手里已经没有存货了！！$B$B为了帮你制作新的占卜之瓶，我需要一瓶法力药水、一块煤和一些蜂蜜酒。不要问为什么，把这些东西给我拿来，然后我就可以帮你制作新的占卜之瓶了。', '把一瓶法力药水、一块煤和一瓶蜂蜜酒送到铁炉堡的塔瓦斯德·基瑟尔那里，用以换取塔瓦斯德的占卜之瓶。', '无所不能的冒险者。你做的太好了。哦，对了，我刚说了个谎―我这里还有\r\n一个瓶子。拿去吧。$B$B好吧，你以为我会说什么?!“哦，给你，另外一个瓶子!我是个傻瓜，一天到晚就是为了准备把这些神奇的通讯工具发放给冒险者的!”好吧，不说这个了，你给我的东西足够让我在你又弄丢这瓶药水的时候再做一瓶了。$B$B请证明我是错的，你不会再弄丢这个新的了，好吗?', '要制作另外一个瓶子，我需要一瓶法力药水、一块煤和一些蜂蜜饮料。$B$B另外，还需要很多很多的耐心。', '', '去铁炉堡找秘法区的塔瓦斯德·基瑟尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3376, '刺鬃酋长', '$N，我听说过你的名字，也许你可以帮助我们一个忙。$B$B我们牛头人在这块土地上创建了自己的家园，但是我们也付出了巨大的代价。刺刃峡谷中有一座刺背野猪人的村庄，在他们的首领——刺鬃酋长的带领下，野猪人一直在与我们交战，这让我们的生活变得非常艰难。我要你去取回刺鬃酋长的徽记！$B$B你可以在东边的峡谷中找到他们那简陋的村庄，刺鬃酋长就在村子里面。', '把刺鬃酋长的徽记交给红云台地的卫兵维萨罗·风羽。', '正义因你迅速的行动而得到了伸张，$N。让我们用这一件事来警告那些企图威胁我们家园的敌人吧。$B$B这是你应得的奖励，希望它能在你的旅途中派上用场，年轻的$C。', '只要尖牙刺鬃酋长死了，我们就再也不用忍受他的骚扰了。把他的头颅给我拿来作为你已经干掉他的证据，$N。$B$B我们牛头人生存的意义就在于打猎，而最大的乐趣莫过于猎杀那些有可能反咬我们一口的猎物了。如果你成功地完成这项任务，你就会理解我所说的话。', '', '去莫高雷找纳拉其营地的卫兵维萨罗·风羽。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3377, '艾露恩祷言', '你愿意帮我的忙吗？无论怎样，请先听听我的故事吧。', '听萨麦尔讲述他的故事。', '我可以在这只笼子里听天由命，但祈祷文必须要被发现!', '请允许我讲完我的故事。', '萨麦尔的故事', '去灼热峡谷找观火岭的萨麦尔·月棘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3378, '艾露恩祷言', '你愿意帮我的忙吗？你能找到艾露恩祷言吗？$B$B就如我所说的，祷言被刻在一块金色的石板上，那些崇拜它的恶棍把它占为己有。$B$B如果你能够找回我的祷言，就把它交给达纳苏斯的阿斯塔利·逐星。如此我才能在遭受如此多不幸之后重新恢复信心，而且更加重要的是，我的祈祷能够有人听见，至于我是否能被宽恕，我根本不关心。', '找到艾露恩祷言，然后将其交给达纳苏斯的阿斯塔利·逐星。', '今夜艾露恩会对你微笑，$N。你已经将一个迷失的灵魂还给了她。请收下这个作为我们对你的感谢吧。', '你来月神殿有什么事吗，$N?', '', '去达纳苏斯找月神殿的阿斯塔利·逐星。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3379, '暗影蛛丝', '灼热峡谷的蜘蛛可以为我们提供暗影蛛丝，这使得它们的商业价值倍增。据我所知，暗影蛛丝在我们的交易中有着很大的需求量。$B$B最近有一批偷猎者来到了这里，他们随意地屠杀蜘蛛，根本不关心他们的行为可能造成的长期影响。我给你的第一个任务非常简单：找到他们……然后终结他们。$B$B到北边去开始你的搜索吧。$B$B如果你需要帮助的话，就去和拆毁者谈谈。', '杀死在灼热峡谷游荡的暗影蛛丝偷猎者小队。尼莉丝认为他们共有5名成员，你的任务就是把他们全都干掉。', '干得好，$N。$B$B我相信这件影纹制品你从来都没有见过。', '你带回什么消息了吗?', '', '去找灼热峡谷的尼莉丝·洛克拉夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3381, '会见主人', '啊，一个年轻的$R来到了萨纳斯的面前。多么美妙的一天啊！您的大驾光临令我诚惶诚恐。谢谢您！$B$B啊……请不要傲慢地把这些赞美之词真的当作一种恭维。让我们有话直说了吧：我不喜欢你。但是我们之间的关系如何并不重要——重要的是我的主人怎么看待你。$B$B给我带来一些角鹰兽的羽毛，我就向他引荐你。他曾吩咐我带那些有价值的旅行者去见他。', '如果你想要见到萨纳斯的主人，就把2根完好无损的角鹰兽羽毛交给他。', '两根羽毛，正如我所要求的那样。这要求并不高吧。$B$B准备好了?说出这句话，然后我们就出发。$B$B哦，你还是要小心自己的行为……我的主人不会对白痴客气的，但是他对那些能够取悦他的人会非常的热情。', '我仍然在这里执行主人吩咐的任务。我其实可以随便要求你提供什么东西来做为见到主人的代价，但是现在，我只要求每个旅人提供两根羽毛来完成我精美的箭。$B$B如果你不够小心的话，我可是会提价的。六枚金币听起来怎么样?$B$B就这样了，我现在就要求那么多。小心行事，我会暂时把价格保持在现在的水准。', '', '去找艾萨拉的萨纳斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3382, '危难中的船长', '当时我们正在找一个安全的港口下锚，但是日落还不到一个小时，他们就突然发起了攻击……那些该死的纳迦！$B$B我不知道他们在找什么，但是他们显然是没找到他们要的东西——纳迦们已经回来过一次了。我的侦查兵在山谷的入口守着，以便在他们下次发动攻击的时候及时通报我们。$B$B很抱歉把你卷了进来，$N，但是现在的情况已经不在我的掌控之中了。$B$B你做好战斗的准备了吗？', '帮助瓦妮莎·贝蒂斯船长、她的船员和地平线轻帆号上的乘客抵御纳迦的攻击。瓦妮莎·贝蒂斯船长必须存活。', '你成功了!谢谢你!这显然是我有生以来参加过的最残忍的战斗，要是没有你，我们还真不知道该怎么挺过来。$B$B我希望你可以和那些幸存的水手们谈谈。他们有些人在这边仍然有些事务要处理，如果你愿意的话，也许能帮他们的忙呢。再次感谢你。', '这将是一场艰苦的战斗……', '帮助瓦妮莎·贝蒂斯船长抵御纳迦的攻击', '去找艾萨拉的瓦妮莎·贝蒂斯船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3385, '黑市交易', '他们把自己称为黑市成员，他们都是些贪财如命的杂碎，只要有利可图，他们什么都会倒卖！$B$B现在情况变得更加糟糕了，$N。他们在灼热峡谷创建了一个基地，贸易首领考维克在那里策划着所有的行动，并且和该地区的黑铁矮人保持着密切的关系。$B$B我们必须对这种行为进行严厉打击，给他们一个严厉的警告。去杀掉贸易首领考维克和他的同伙科朗克，把他的商人的背包给我拿回来，你的任务就算完成了。$B$B向大熔炉进发！', '杀了贸易首领考维克和他的同伙科朗克。从他的尸体上拿回商人的背包，把它交给尼莉丝。', '你对暗黑拍卖会进行了一次致命的打击。他们的领袖在派更多人进入灼热峡谷之前一定会考虑再三的。$B$B哦，我在这个商人的背袋里没找到什么有用的东西，你可以随便把它处理掉了。', '那家伙还活着吗?', '', '去找灼热峡谷的尼莉丝·洛克拉夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3441, '神圣的惩戒', '听听我的故事吧，旅行者。', '听卡拉然·温布雷讲述他的故事。', '你听完了吗?你准备行动了吗?', '让我继续说下去……$C。', '卡拉然的故事', '去灼热峡谷的大熔炉找卡拉然·温布雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3442, '无瑕之焰', '你做出了正确的决定，$N。$B$B我们必须对敌人的要害下手，除掉那四座哨塔。$B$B一旦这四座塔都化为灰烬，我们就可以在他们反应之前发动攻击。$B$B你需要合适的工具来点燃防御塔，而制作这样的工具就需要合适的材料。$B$B给我弄四份烈焰之心和四份傀儡之油来，然后我就会给你制作出一把燃烧着无瑕之焰的火炬。$B$B在这片土地上的傀儡和元素生物身上找找吧。', '收集4份烈焰之心和4份傀儡之油，然后把这些东西交给卡拉然·温布雷。', '干得好，$N。我们准备得差不多了。', '你收集到我要的材料了吗?', '', '去灼热峡谷的大熔炉找卡拉然·温布雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3443, '铸造火炬杆', '为了承载无瑕之焰，我们需要一根杆子和一只箱子，你必须首先从杆子入手。$B$B大熔炉的黑铁工头和黑铁奴隶贩子使用附魔过的瑟银作为武器，那是一种很坚硬的合金。如果你可以给我弄八把瑟银匕首来，我就能将它们熔解并铸成一根杆子。', '给卡拉然带去8把瑟银匕首。', '你是个很优秀的苦力，$N。你有没有考虑换个工作?比如当一个侦探?或是收垃圾的?哦，我知道了，有一大堆愚蠢的地精拿着金属探测器，徘徊在艾泽拉斯的海边寻找失落的宝物，嗯，那工作一定很适合你。', '八把，$N。我需要八把匕首!', '', '去灼热峡谷的大熔炉找卡拉然·温布雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3444, '石环', '我曾经进入到沉没的神庙中的那个充满邪恶气息的房间，那里的恶魔会残忍地杀死每个进入房间的冒险者……我在那些满是泥泞的房间里艰难前进，差点就找不到出来的路了。我只记得自己蹒跚地穿过一个圆形的房间，房间里到处都是毒蛇塑像……$B$B最后，我发现了一块圆石，上面印着相同的毒蛇标记，我把它打包运到棘齿城的车间去了。去把它取回来，也许我能让你知道更多的信息。', '到棘齿城去，从玛尔冯·瑞文斯克的车间里取回石环。', '对……就是这块石头。$B$B那些往事又回到我的脑中了，$N……', '棘齿城离这儿不远，$N。花不了你多长时间的。', '', '去塔纳利斯找破碎石柱的玛尔冯·瑞文斯克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3446, '深入神庙', '在神庙里，我发现一间有着六个阳台的圆形房间，每个阳台的边缘都有一尊毒蛇塑像。我感到好奇，就推动了其中的一个，随即发现这是个陷阱！我差点在爆炸中丢了性命。我躺在台阶上往下看去，注意到在房间的底部还有一尊塑像，那好像是是什么神的祭坛……哈卡祭坛？似乎是这个名字。$B$B我认为这祭坛就是秘密所在——你必须把这个东西带到沉没的神庙中的那个祭坛上去……', '在悲伤沼泽沉没的神庙中找到哈卡祭坛。', '你把石环放入凹陷处，只听见“喀哒”一声，它完全密合。$B$B既然石头刚好吻合，那么你可以继续了……但是接下来要怎么做呢?$B$B也许你应该进一步检查这座祭坛……', '在检查雕像时，你注意到边边有一处凹陷，与玛尔冯给你的石环尺寸相同……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3449, '奥术符文', '魔法曾经同艾露恩一样受到某些精灵的尊崇。他们中最厉害的法师发明了文字，并在石板上记录下了魔法的规律和他们对事物的认识，并将这些石板留在公开的场合供人研习。$B$B我非常想要获得这些来自埃达拉斯废墟的文字拓片。我将为你提供工具来帮助你取得拓片，但是你必须自己去寻找它们。多加小心，对埃达拉斯废墟感兴趣的可不仅仅是探险者协会。', '使用绘图工具包获取贝萨玛拉符文、辛耶尔符文、玛科里符文和塞尔哈符文的拓片，然后转至艾萨拉南部半岛外的小岛，把它们交给驾驶员西格斯·熔光。', '很高兴看到你平安归来，$N。希望事情不是太棘手。$B$B我会马上把这些东西交给泰摩尔。他看到这些东西一定会大吃一惊的。$B$B走吧!顺便把信号枪扔了……这对你应该已经没有任何用处了，而且我也得到一把新的了。', '很好，很好，很好，很高兴见到你回来这里，$N。你帮泰摩尔拿到拓印了吗?$B$B尽管跟这里一样都是危机四伏，但是海岸附近却没什么动静。或许是因为水下有纳迦的关系，但是这与我无关……我是在天空巡逻的。', '', '去艾萨拉找拉文凯斯雕像的驾驶员西格斯·熔光。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3452, '烈焰之盒', '我们还需要最后一部分来完成火炬。$B$B在西北方的山脚下，你可以找到暮光之锤的营地。据说他们携带着特殊的徽章和石像，用以表示对神明的崇敬。这些徽章和石像具有强大的魔法能力，足以制成一个魔法容器。将拉格纳罗斯符记交给我，我将试着从里面提取魔法，然后制造一个容器。', '找到一个拉格纳罗斯符记，把它交给卡拉然·温布雷。', '符记散发着邪恶的魔法能量，这正合我的心意。', '如果没有合适的魔法能量来源，惩戒火炬就无法完成。', '', '去灼热峡谷的大熔炉找卡拉然·温布雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3453, '惩戒火炬', '给我一点时间来拼合这些碎片，然后对它进行必要的附魔。', '等待卡拉然·温布雷完成惩戒火炬。', '还有一个最终的任务等着你去完成。', '不要打断我。', '制造火炬', '去灼热峡谷的大熔炉找卡拉然·温布雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3461, '向法师泰摩尔回复', '泰摩尔并没有给我什么可以付你报酬的东西，我建议你回铁炉堡去的时候好好跟他交流一下。我想他还在秘法区，去找他吧，他会付你报酬的。$B$B再次感谢你帮助他摆脱困境，祝你好运。$B$B哦，我不需要绘图工具包啦，你为什么不顺便把它还给泰摩尔呢？', '到铁炉堡去，将法师泰摩尔的绘图工具包还给他。', '很好!我很高兴听到这个消息。$B$B到我的塔里去研究这些拓片一定会是件令人兴奋的事儿。我真羡慕你……能去艾萨拉那样的地方，那里是每个魔法研究者的梦想。$B$B嗯，自从你为探险者协会效力以来，我们还没谈过报酬问题呢，但是你应该得到回报。', '你回来了!太棒了，你把我的绘图工具包拿回来了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3463, '烧掉它们！', '听好了，$N。虽然我们无法摧毁那四座哨塔，但是你可以使用惩戒火炬点燃它们，这种火焰是任何元素或力量都没法熄灭的。$B$B在哨塔燃烧的过程中，没有什么部队可以驻扎在里面，这样他们的第一道防线就失效了。$B$B你必须进入每一个塔楼，用惩戒火炬把它们烧掉。要小心黑铁矮人的精英哨兵，$N。', '使用惩戒火炬点燃北部、南部、东部和西部的哨塔。', '伟大的胜利!这难道不是一个伟大的胜利么?', '你迷路了吗，$N?', '', '去找灼热峡谷的侍卫玛特拉克。', '点燃西部哨塔', '点燃南部哨塔', '点燃东部哨塔', '点燃北部哨塔');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3501, '多多益善', '尽管你可能找不到纯净无瑕的德莱尼水晶，但是在你探索这片土地的过程中，一定可以找到若干有瑕疵的德莱尼水晶碎片。$B$B库米沙是否可以利用这些碎片返回家园，这还很难说，但是这些碎片可以为德莱尼人所用。$B$B把你发现的有瑕疵的德莱尼水晶碎片都交给我，我会给你报酬的。', '将有瑕疵的德莱尼水晶碎片交给库米沙，你就可以得到相应的回报。', '你可真让我感到厌恶，$r。一个成年$g男子:女子;对着一堆垃圾流口水?真可悲!带着你的报酬滚吧。', '你在探险中找到什么好东西了吗?', '', '去找诅咒之地的收藏家库米沙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3502, '德莱尼的垃圾…', '嗯，见识了你的贪婪之后，我感到恶心。$B$B不管怎样，我可不会跟你的贪欲纠缠不清。$B$B你每交给我一块有瑕疵的德莱尼水晶碎片，我就给你更多的垃圾。我的垃圾都被你收走了。在德拉诺，我们称这种情况为“双赢”。', '将有瑕疵的德莱尼水晶碎片交给库米沙。诅咒之地的任何怪物都有可能携带着这样的碎片。', '你可真让我感到厌恶，$r。一个成年$g男子:女子;对着一堆垃圾流口水?真可悲!带着你的报酬滚吧。$B$B听起来很耳熟是吧?我每天都要说一千次呢。$B$B啊，我真厌恶这个世界。', '哦?德莱尼水晶?记得吗?$B$B<库米沙握紧拳头敲打你的脑袋。>$B$B有人在家吗?', '', '去找诅咒之地的收藏家库米沙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3504, '叛徒', '这个毫无诚信可言的女人！她只能配得上这个称呼——罪有应得！$B$B我可能犯下了一个严重的错误，$N。我相信了一个血精灵。更糟糕的是，她还是个女的！$B$B她声称艾萨拉那里埋藏着数不尽的财富……我派了一些战士保护她去那里，满以为我可以有所斩获。但是，到头来我却被耍了——她把他们都杀掉了。$B$B我要报仇，$N，但是我手边已经没有可以派遣的人了。到哈达尔营地北边的瓦罗莫克去找阿格图，他会告诉你更详细的情况。', '把这封给阿格图的密信交给艾萨拉的阿格图·血拳。', '我们已经竭尽全力来对付她和她的手下了，但是他们的确很能打。我们派去的人没一个回来的，我想他们多半都死了，剩下的八成是逃了……那帮懦夫。$B$B现在既然你这个援兵来了，我看我们还是能有所作为的。也许我们可以让她为欺骗和背叛贝尔戈洛姆付出代价。$B$B你愿意入伙吗?', '啊，贝尔戈洛姆果然已经老了，他最终还是派了个外人来帮助我们，对吗?$B$B这个营地里曾驻扎了12个强壮的战士，$N，但是他们都已经死了。那个名叫雷姆托里的法师杀死了他们，她像戏弄猴子一样欺骗了贝尔戈洛姆。不过话说回来，她的确是个相当有诱惑力的女人。这也许是我仍然愿意帮助贝尔戈洛姆的原因―换了是我也会犯同样的错误。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3505, '叛徒', '我的计划是这样的：$B$B我们从艾萨拉的北部半岛开始，沿着悬崖的南部开始进攻她的工人。把他们都干掉，让他们知道当叛徒的后果。$B$B先别管她——她大部分时间都跟她的护卫一起在艾萨拉进行搜寻工作。在杀死她的工人之后，我们在去考虑怎么收拾她比较好。我们应该先仔细侦察一番，也许有一些可以激怒她的东西。', '杀死10个血精灵搜寻者和10个血精灵勘测员，并找到大法师雷姆托里的营地。一旦你发现了营地，就去找到某个对她极为重要的东西，以用于激怒她，让她与你战斗。', '你开始浏览这本书，并翻到了一页用黑色丝巾标出来的书页。$B$B在你试着解译书上文字的时候，你发现在其中一页的底部画着一张地图。你迅速地查看了一下眼前的景物，并很快意识到地上的水晶、石阵，甚至某些东西的位置都跟这张图上所画的东西十分相似。', '黑色的皮革封面上是用金叶镶嵌的书名—卡多雷召唤宝典。当你翻开书时，你发现这本书的年代十分久远，但是保存的十分完好。$B$B你猜测其中的文字是某种古代语言……或许是卡多雷语?$B$B你的直觉告诉自己，你应该在完成对血精灵的报复之后回到这里。', '找到大法师雷姆托里的营地', '去艾萨拉找萨拉斯营地的卡多雷召唤宝典。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3506, '叛徒', '经过思考，你对眼下的情形已经有了大致的了解，你的脸上浮现出一丝笑容：也许摧毁水晶将使那些杀死众多兽人并背叛贝尔戈洛姆的血精灵方寸大乱？$B$B你继续翻译着文字和图片，并了解到其中一块水晶就在这个石阵的制造者身上——其馀的则在更为邪恶的生物手中。$B$B你合上书本，开始考虑要摧毁哪块水晶。', '摧毁大法师雷姆托里携带的奥术聚焦水晶并杀死她。然后把她的徽记交给艾萨拉的阿格图·血拳。', '啊!难以置信!$B$B你做到了!贝尔戈洛姆会很高兴的!无数战士的灵魂终于可以得到安息。谢谢你，$N。', '报复那些血精灵叛徒的事进行的如何了，$N?$B$B有任何的进展吗?我希望你够强壮，可以把那条狗狠扁一顿!她应该为她的所作所为死一百次!', '', '去找艾萨拉的阿格图·血拳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3507, '叛徒', '回到奥格瑞玛的贝尔戈洛姆那儿去，他肯定想要好好看看这个女人的徽记！我们很快就回去。$B$B啊，这真是一个好日子。谢谢你的帮助，$N。', '与奥格瑞玛的贝尔戈洛姆·石槌谈一谈。', '哈哈!看看你自己，可怜的女人!我要向你吐口水!$B$B谢谢你，$N。我衷心地感谢你!今天是个好日子!$B$B要是我有权力的话，我就送你一个王国!但是，也许你会对这件东西感到满意的。$B$B<贝尔戈洛姆低头看着那曾经背叛过他的法师。>$B$B哈哈!愚蠢的血精灵，看看你自己吧……躺在这麻布袋中，身首异处!这就是背叛贝尔戈洛姆的下场!', '我记得你，$C。我曾请求你去艾萨拉杀死那个叛徒!这好像是很久以前的事了。别告诉我阿格图和其他人也死了!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3510, '恶魔之名', '她杀了我的孩子，她称自己为海洋的统治者。她是个虚伪的神。杀死她，把她的所有徽记都带回来。$B$B这样，你就能得知你要寻找的名字，并得到与其同样重要的东西。$B$B她的名字叫做赫塔拉。$B$B<亚考罗克指向西南方。>$B$B去吧！', '杀掉赫塔拉，将染血的赫塔拉徽记、破碎的赫塔拉徽记和淤血的赫塔拉徽记交给亚考罗克。', '终于，有人值得拥有亚考罗克的智慧了!', '<亚考罗克领主弯下腰来看你。>$B$B头颅在哪儿?', '', '去艾萨拉找亚考兰神殿的亚考罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3511, '恶魔之名', '我曾许诺将恶魔之王污染者拉瑟莱克的名字告诉你。不过，我得先为你的旅程准备一些至关重要的东西。$B$B你要铸造的武器必须有调剂才能制成。给我一点时间，让我从这些徽记中弄点血液出来。$B$B<亚考罗克用他那巨大的手掌挤压徽记，压出了血液。>$B$B将调剂交给洛拉姆斯，告诉他，那个恶魔的名字是拉瑟莱克。', '将调剂交给洛拉姆斯·萨里比迪斯。', '调剂将为我们的武器提供必要的成分。接下来，我们还需进行最后一个步骤来完成武器的锻造。', '你回来了!我真惊讶，$r。你知道那个恶魔真正的名字了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3513, '符文卷轴', '这份看起来很正式的卷轴被一条银色丝带紧紧地裹着。你觉得会有什么人对此感兴趣，但是这人是谁呢？$B$B在灰谷边界以北有一处前哨站，如果卷轴上的信息与暗夜精灵有关，那么你就应该把它送到那儿去。', '将符文卷轴带到贫瘠之地的北部警戒塔去。', '嗯……你在哪儿找到的?', '你有什么事?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3514, '部落的示威', '这份卷轴是在石爪峰的树妖琳萨瑞尔那儿得来的，她是猛禽洞穴的头目。$B$B她不会再与带着这份卷轴的信使有任何联系了，哈哈……但是我们必须保持警戒。部落不会允许此地再出现联盟的信使。$B$B$N，到猛禽洞穴去，杀死琳萨瑞尔，然后给他们一个所有人都能看到的信号。带上部落的旗帜，把它插在猛禽洞穴里，这样他们就不会急于派出另一个信使来到我们的地盘上送死了。', '杀死猛禽洞穴的领袖琳萨瑞尔。', '你真勇敢!除掉琳萨瑞尔是个艰巨而重要的任务，$N。他们得过很长时间才能重整旗鼓，这样在贫瘠之地穿梭的联盟信差就会少一些了。他们会再三考虑是否要派出新的信差从这里经过。$B$B谢谢你。', '不能让联盟踏入我们的领地，$N。让他们明白这一点。', '', '去贫瘠之地找摩尔沙农场的卡德拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3517, '搜索知识', '我承认，$N，我大部分时间都呆在艾萨拉。贝尔戈洛姆的惩罚对我也有好处。$B$B在离开这里之前，我进行了一些研究，你知道遍布这一地区废墟中的东西是多么的珍贵吗？$B$B我可以告诉你更多细节，如果你帮我收集一些东西，我甚至会分给你一些利润。$B$B在东边的埃达拉斯废墟里面有我需要的石板，它们都是以上层精灵的大法师命名的。去寻找石板，然后我们再来进一步详谈。', '找到贝萨玛拉石板、辛耶尔石板、玛科里石板和塞尔哈石板，把它们交给艾萨拉的杰迪加。', '棒极了，$N，这些东西完好无损，我们一定能发财的。$B$B别在这儿浪费时间了，我们还得赚钱呢。', '我要你收集的石板能让我们发一笔小财，当你找到它们之后，我会告诉你把它们送往何处的。但是，我可不是蠢货……我只有在确定它们都已送达的情况下才会把你应得的那一份给你。$B$B出发吧―我们的时间不多。我也许得多找些人来帮我。', '', '去找艾萨拉的杰迪加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3518, '玛加萨的石版', '第一块石板要交给一位名叫玛加萨的牛头人。她是雷霆崖的长者之一，也是牛头人和被遗忘者结盟的支持者。她比其它长者中的任何一个都更希望帮助亡灵返回人类的状态。$B$B将贝萨玛拉石板交给她，这块石板或许能帮助被遗忘者……至少她是这么说的。', '将贝萨玛拉石板交给雷霆崖的玛加萨·野性图腾。', '啊，贝萨玛拉石板。我还在想我和杰迪加的合作关系是不是已经破裂了，要不然就是那可怜的兽人已经死在艾萨拉了呢。很高兴她成功了。$B$B贝萨玛拉是精灵贵族中最具影响力的炼金师之一，听说他已经掌握了随意把金属和其它物质互相转化的技能。', '你好，$N。我能为你做什么吗?我还要处理很多事情，请快一点。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3520, '尖啸者的灵魂', '我在寻找菲拉斯的山谷尖啸者的灵魂。它们是某位古老神灵的亲戚，它们的灵魂与那位神灵连在一起。$B$B带上这根魔杖去菲拉斯，在菲拉斯南部和中部区域寻找并杀死山谷尖啸者，对它们的尸体使用我的魔杖。这将使它们的灵魂现出原形，此时你就可以收集灵魂的精华了。$B$B将我的魔杖和尖啸者的灵魂精华交给我，我就会告诉你刚才我所说的那位神灵的详细情况。', '在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。', '你做得很好，$N。或许现在是揭开更多资讯的时候了……$B$B在巨魔中流传着一个古老的预言，死神哈卡，夺魂者，某一天会再回到这片土地上。有些人说哈卡的回归将为巨魔一族带来欢乐和荣耀，而另一些则认为他的复苏将摧毁一切。$B$B我不相信这个神话，但是我知道哈卡的灵魂精华拥有强大的能量，我们绝不能让这个力量落到那些居心叵测的人手里……', '你收集到尖叫者灵魂的灵魂了吗，$N?', '', '去塔纳利斯找热砂港的叶基亚。', '收集尖啸者的灵魂', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3521, '埃沃隆的解药', '我们也许能帮埃沃隆的忙，我知道有种方法能解蛛毒。但是我需要一些成分来制作解药。$B$B首先是紫蓝色蘑菇，它们一般生长在树下，你也可以从南边的劣魔身上找到它，劣魔们很喜欢这种蘑菇。我还需要月牙百合花，它们只生长在水池周围。$B$B最后一种成分也许是最难获得的，你必须从咬伤了埃沃隆的蜘蛛身上获取树林蜘蛛的脓液。', '在幽影谷中为迪兰妮亚·月光收集7朵紫蓝色蘑菇、4朵月牙百合花和一份树林蜘蛛的脓液。', '感谢艾露恩，你这么快就收集到了这些原料!\r\n\r\n稍等一下，我马上就配好解药。\r\n\r\n', '请去收集我所说的那些原料，$N。埃沃隆需要我们的帮助。', '', '去泰达希尔找幽影谷的迪兰妮亚·月光。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3522, '埃沃隆的解药', '解药准备好了，$N。请确保埃沃隆把它喝下去。$B$B你要知道，解药的有效时间只有5分钟。你必须及时地把解药送到他嘴边。$B$B赶快去吧，$N。', '在5分钟内将埃沃隆的解药交给他。你可以北边的洞穴入口外面找到埃沃隆。', '这是什么，$N?$B$B哦，我就知道迪兰妮亚能帮我的!$B$B<埃沃隆喝下解药。>$B$B我总是在惹麻烦，而迪兰妮亚总是会设法帮助我。$B$B我感觉好多了，但是我要在这里休息一会，直到我感觉完全恢复之后再离开。好吧，其实我是希望你帮我从这些可恶的树林蜘蛛中清出一条路来……', '哦……$N，很高兴你回来了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3523, '剃刀高地的亡灵天灾', '太好了！我叫奔尼斯特拉兹，感谢你前来营救我。我已经放弃了求生的欲望……甚至想到自己会被这些亡灵天灾滋生的渣滓给吃了。是的——我说的是亡灵天灾。他们与野猪人达成了协议，你所看到的这些噩梦般的景象就是这个协议的结果。$B$B听着……与其逃跑，我宁愿奋力一搏，为所有的生灵造福。你愿意帮助我吗？这也许很危险，但是你看起来应该可以胜任。', '如果你同意帮助奔尼斯特拉兹，就再跟他谈谈，并将誓言石还给他。', '太棒了，我就觉得你应该是个英雄人物!我并不打算欺骗你，我们的工作有些麻烦$N。如果我们可以专注于手边的任务，我们应该可以名列前茅。$B$B现在，让我们加快脚步吧……', '我并不是搞政治的;我不在意你是为部落还是为联盟效力。我对解决所有种族直接造成影响的重大威胁更感兴趣……现在我们就有一个很大的威胁。$B$B要是你愿意成为真正的人民英雄，就将我作为承诺的黑曜石还给我吧。对我的族人来说这代表着重要的同意契约。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3524, '搁浅的巨兽', '众所周知，巨大的海洋生物常年潜身于黑海岸边缘，它们在此游弋，直至死亡。近来，这些野兽的数量日益增加，并且开始侵袭海岸。我受月神殿的派遣到这里来调查，但是海水中的鱼人使调查变得非常困难。$B$B被邪恶的灰雾鱼人所控制的奥伯丁南部海岸上躺着一头搁浅的巨型生物，你能帮忙去从这头巨兽身上弄点骨头回来以供我研究吗？', '从奥伯丁南面的海岸上收集海洋生物的骨头，然后带着骨头向奥伯丁的温尼斯·布莱葛回复。', '我希望那些该死的鱼人没有在你收集的过程中带来太多的麻烦!我会让下一班飞往达纳苏斯的角鹰兽把这些骨头带过去。月神殿为我提供了一些用来寻求帮助的资金，请收下这些，以及我们的感激之情。$B$B你的成功让我印象深刻，如果你愿意的话，我将为你提供进一步为月神殿效力的机会。', '这些生物是在最近才开始以如此令人震惊的数量在黑海岸登陆，我觉得这是某种不祥的征兆。到南边去弄些这种生物的骨头样本，这将有助于达纳苏斯对事态做出正确的评估!', '', '去黑海岸找奥伯丁的温尼斯·布莱葛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3526, '地精工程学', '高级的工程学有两个分支：侏儒派和地精派，显然，地精工程学是所有明智的技师都会选择的一派，用\r\n华丽的高爆炸药和机械装置统治世界！$B$B好吧，$N，读一下这本手册。如果你想要学习地精工程学，就把这个交给加基森的尼克斯·斯普克斯宾。请记住，一旦你加入某一派，就永远也不能再加入另一派了，所以在你完成他交给你的任务之前要三思。', '如果你想要对地精工程学有更多了解，就把工程学教材交给加基森的尼克斯·斯普克斯宾。', '很好，$N，你选择接受我的指导真是明智之举!随便什么蠢货都可以成为初级工程学的专家—那些哥布尔跟他们那满是辐射的老窝就是最好的证据。要成为出色的哥布尔工程学专家，你必须有坚强的意志和稳固的双手—(我得强调稳固二字)。$B$B竖起你的耳朵，$N，你会学到许多东西的。', '我可以在一里外闻到新技师的气味，就像我可以在一里外闻到炸药的气味一样。你是来揭开炸药的神秘面纱的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3527, '摩沙鲁的预言', '摩沙鲁的古老预言中谈及获取神灵哈卡的灵魂精华的方法。这个方法被写在两块石板上，并被带到加基森西边的巨魔城市祖尔法拉克中。$B$B把摩沙鲁石板交给我！$B$B第一块石板在早已死去的巨魔殉教者塞卡那里。据说杀害他的凶手受到诅咒，都被变成了甲虫，正在他的神庙周围游荡。$B$B第二块石板在加兹瑞拉圣水池的水占师维蕾萨手中。$B$B得到石板之后，把它们交给我。', '将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。', '啊，这太好了。我可以把这些远古石板组合在一起，研究它们隐藏的秘密了。$B$B我欠你的更多了，$N。未来还需要你的帮忙呢。', '你拿到摩沙鲁的预言石板了吗，$N?$B$B等我获得石板后就可以进行研究，然后学习如何控制哈卡的精华!', '', '去塔纳利斯找热砂港的叶基亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3528, '神灵哈卡', '现在是获取哈卡化身的精华的时候了。$B$B把哈卡之卵拿到悲伤沼泽的那座沉没的神庙中，在堕神圣地中使用卵的力量激怒死去的神灵。$B$B他将派出那些被称作“嗜血者”的奴仆对付你，杀掉它们，取出它们的哈卡莱血液，然后用这些血液熄灭包含哈卡灵魂能量的不灭火焰。当你熄灭所有的火焰时，哈卡的化身就可以进入我们的世界了。$B$B打败他，将他的精华封印在哈卡之卵中。', '将装满的哈卡之卵交给塔纳利斯的叶基亚。', '我收集到哈卡的精华了!现在这卵充满着生命!难道哈卡的神话是真的?$B$B这不能让它成真，要是哈卡获得重生，不知道他会做出什么事来呢。我将确保这颗卵的安全，不让它落入坏人之手。$B$B我给你的任务都完成了，$N。你经历了一场传奇，你的作为也许会改变我们的世界。', '你打败了哈卡的化身了吗，$N?他的精华被封入我给你的卵中了吗?', '', '去塔纳利斯找热砂港的叶基亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3541, '杰斯雷蒙的石版', '我在奥格瑞玛有个主顾，他住在暗巷区。如果你不熟悉那里，那么你是很难找到他的，不过如果你到那个区域中最高的那座建筑物里去，就应该能找到他。$B$B不过呢，你可别让全卡利姆多的人都知道他在哪里，他在干什么——这对咱们俩都没好处。$B$B为了这块辛耶尔石板，他会付给咱们一大笔钱的。我不知道他为什么如此在乎这块石板，不过你真该看看他听到这块石板的消息后有多激动。', '将辛耶尔石板交给奥格瑞玛的杰斯雷蒙。', '啊，杰迪加从艾萨拉送来了她的包裹。好极了，我正等着呢。$B$B杰迪加是个很好的女人……但也很危险。还有什么比这更好的?$B$B看看这个……石板保存的十分完好。你真是个好信差，$N。', '你有什么事?我今天有许多事情得处理，我没看到我的行程表里有你的名字。你要是想没事跑来烦我，我会特别为你“安排”的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3542, '安德隆·甘特的石版', '安德隆·甘特是我的下一个主顾。他通常待在幽暗城里……就在炼金房附近。当我们谈到石板的用途时，他就有些藏不住话。显然幽暗城中的某些法师想要学习上层精灵所使用的魔法。他们认为这石板能对他们有所帮助。玛科里曾以善于召唤各种生物——特别是元素生物而闻名。$B$B把玛科里石板给他带过去，然后回到我这儿来取你的报酬吧。', '将玛科里石板交给幽暗城的安德隆·甘特。', '这些钱给你……去给你自己……<嗝>……买些新武器或什么的……$B$B去吧……<嗝>', '嗯……<嗝>……这真是个惊喜啊?一个冒险者……<嗝>!$B$B我能帮你做些什么……<嗝>?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3561, '大法师克希雷姆的石版', '最后这块石板要交给一个非常危险的家伙，$N。听着，比起我先前让你接触的那些人，我对他可以说是非常不信任的。$B$B大法师克希雷姆在艾萨拉的一处山顶上建了座高塔。他是个人类，但是他的行为跟我见过的……或是杀掉的那些人类大不相同。他充满了力量，我可不敢问他为什么想要这块石板。$B$B他来找过我，但是他跟我说，当我准备就绪时，他的侍卫萨纳斯会带我到塔里去。到北边去找萨纳斯吧。', '将塞尔哈石板交给艾萨拉的大法师克希雷姆。', '啊，塞尔哈石板……我是多么渴望能研究它呀。$B$B谢谢你，$N。告诉杰迪加，她做得很好。这东西的价值绝对符合她所要求的报酬啊!', '我能帮上什么忙吗，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3562, '玛加萨的报酬', '把这张便笺交给杰迪加,告诉她当她回来的时候就到这儿来领取报酬。我对她的成绩很满意。$B$B快去吧，$N。告诉你的主人，我在这儿等她。', '将玛加萨的便笺交给艾萨拉的杰迪加。', '啊，好极了。她比我想象中的要通情达理多了……至少是对你来说。我本以为她会因为我的傲慢而惩罚你呢。她一定是非常想要那块石板，真有意思。$B$B下次再考虑这问题好了。', '哦，玛加萨说什么了?那个老太婆……我敢打赌她根本不知道什么是礼貌。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3563, '杰斯雷蒙的报酬', '把这封信交给杰迪加，告诉她，我们的交易很成功，而且我对她很满意。$B$B让她马上返回奥格瑞玛，杰斯雷蒙会确保她的安全。$B$B也许将来我还需要你的帮助，$N。', '将杰斯雷蒙的便笺交给艾萨拉的杰迪加。', '从他的字条看来他是欣喜若狂啊……高兴得有点过了头。$B$B也许有一天我要让他知道我是多么感谢他。哦，至少我们有理由在艾萨拉多停留一段时间了。$B$B这是你应得的那份酬劳。', '你跟杰斯雷蒙谈过了吗?$B$B他跟其它巨魔比起来简直像头猪，但是他的资讯通常都很正确，而且他给的报酬也很丰厚。$B$B如果你能忍受他的态度，那么也许你能从他那赚一大笔钱。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3564, '安德隆的报酬', '拿着……这个……<嗝>交给杰迪加。祝你好运！', '将安德隆的便笺交给艾萨拉的杰迪加。', '太好了……等一下。$B$B哈哈!你把石板交给他的时候跟他说了什么，$N?他给了我们超额的报酬!我当然不是在抱怨，你告诉他这笔交易全额改变了吗?还是他又喝醉了?$B$B没关系……来，多的部份你也有份。', '你见到安德隆了吗?他很少离开幽暗城，我想你应该不难找到他。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3565, '克希雷姆的报酬', '什么？哦，你的报酬。当然。$B$B拿好了，赶快走吧。我想杰迪加正在耐心地等你回去呢。', '将克希雷姆的便笺交给艾萨拉的杰迪加。', '没问题?什么都没有做?好吧……我真希望他显露出几分不情愿来，或者至少是背弃我们的约定。嗯，也许我们可以信任他。$B$B好啦，没有必要细想了。这是你应得的那份，感谢你的帮助。', '嗯，克希雷姆说了些什么?他有没有对你做什么?他对你施法术了吗?或者强迫你为他做事了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3566, '奥比斯顿', '这……这……这是个陷阱。$B$B原谅……我。$B$B杀掉这个该死的混蛋……为我们杀掉他……为了索里奥斯。', '杀死黑衣拉索里克和奥比斯顿，带着黑衣拉索里克的徽记和奥比斯顿的精华回到铁炉堡的索里奥斯那儿。', '<索里奥斯的脸变得惨白。>$B$B这……这不可能。我的兄弟?这一切都是他干的?$B$B<索里奥斯的脸孔因愤怒而扭曲了。>$B$B他背叛了我，背叛了铁炉堡!看来上古诸神在这些地方仍然有着巨大的影响力，令我害怕的是，如果我的兄弟―那个曾经高贵可敬的矮人，也会如此轻易地投靠拉格纳罗斯，那就没有人是安全可靠的了。', '我不相信你!把证据拿出来!', '', '去找铁炉堡的索里奥斯馆长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3568, '堕落之水', '看见我后面的那个看上去随时都可能病倒的牛头人了吗？她前段时间去过艾萨拉。她说自己在经过埃达拉斯废墟时受到纳迦的攻击，而且负了伤。$B$B在击退一些纳迦之后，她在海滩休息了一下，并饮用了海潮之池中的水，现在她感觉有些恶心……$B$B我要找出她饮用的水。拿着这个盒子，我在里面放了一些空瓶子，用它们到各个海潮之池中收集一些水，然后回来。', '在艾萨拉的埃达拉斯废墟旁的海潮之池中收集4瓶水，然后回到药剂师科雷那儿。', '棒极了。你在她死掉之前回来了，很好，很好。$B$B我们现在就开始吧。$B$B我一直在研究她的症状，情况相当不妙。不过令我惊讶的是她还活着。她呕吐过三四次，把这儿搞得一塌糊涂……味道真不好闻。$B$B给我一些时间，让我拿我们的……朋友……做个试验。', '你知道她会怎么样吗，$N?她死定了……一看就知道。现在对她来说，最好的结果就是帮助我们找到治疗这种瘟疫的方法。她饮用的水也许能帮助我们。她早晚要死的―不如在死之前为我们做点贡献。你认为呢?', '', '去找幽暗城的药剂师科雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3569, '堕落之水', '把这个交给瑟尔萨。也许她可以痊愈……也许不能。反正要在她喝下后才能知道结果。', '将科雷的药剂交给幽暗城的瑟尔萨·风歌。', '药剂师科雷对我非常友善……尽管这令我有些不安。如果他说这东西能帮我，那么我别无选择，我没有时间去寻找其它的解决方法了。我已经和牧师及萨满都谈过了，他们都无能为力。$B$B愿大地之母守护我的灵魂。', '我听说幽暗城的炼金师长久以来一直在努力研究如何治愈自己的疾病，所以我来到了这里。据说他们也许能够帮助我。$B$B尽管我在这似乎不受欢迎，但是我别无选择―我受到疾病的煎熬，我急切需要他们的帮助。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3601, '我就是基姆加尔！', '我就是基姆加尔！你知道基姆加尔对血精灵意味着什么吗，$N？我对他们来说不过是一只小老鼠……或者其它类似老鼠的东西，那些该死的欺凌弱小的家伙！$B$B他们雇佣我来帮他们在这里搜寻一些失落的宝物，当然，在他们告诉我要找什么东西以及他们愿意付给我多少钱之后，我就决定单干了。他们马上翻脸，还想干掉我……干掉我！$B$B所以，你看，永远都不要相信血精灵。$B$B问题是，我的一些东西还在他们手里，看样子我自己是拿不回来了。你能帮帮我吗？', '搜索萨拉斯营地，找到基姆加尔的指南针、望远镜、烧鸡和花生，然后把它们交给艾萨拉的基姆加尔。', '哈哈!你给他们好看了，是不是?$B$B太好了!这给那些敢背叛伙伴的血精灵一个教训……特别是背叛像我这样忠诚的哥布尔商人!去死吧，血精灵……$B$B好吧，我唯一能做的就是为你所花费的时间支付报酬……如同我所承诺的。$B$B拿去吧……这应该会对你有所帮助。', '那些讨厌的血精灵。我告诉你，如果我和你一样强壮的话，我会去那里然后亲自好好教训一下他们!但我最好还是付钱给你请你帮我解决他们。', '', '去艾萨拉找雷加什营地的基姆加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3602, '艾萨拉水晶', '艾萨拉南部地区的古代峭壁巨人以吞噬这个地区的岩石和建筑物为生。他们的排泄物具有高度的延展性和极其明显的水晶特性，所以被称作艾萨拉水晶。$B$B这种东西主要在南部地区出现，但是由于那些巨人的暴力倾向，通常你很难得到它们。$B$B你必需到艾萨拉南部去，收集足够多的艾萨拉水晶来制作武器的主体部分。我的地狱犬会帮助你收集水晶的。', '在艾萨拉南部收集20块艾萨拉晶体。你可以使用地狱犬协助寻找一些隐藏的矿脉。$B$B任务完成之后就回到洛拉姆斯那里去。', '你在艾萨拉的任务已经完成了，$r。现在我必须为你的下一步冒险铸造必需的东西。', '邪恶的力量不会停下脚步来等你，蠢货。当你被干掉之后有的是事件来休息。现在，把水晶交给我。', '', '去艾萨拉找风暴海湾的洛拉姆斯·萨里比迪斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3621, '武器的铸造', '下一步就是铸造武器了。你必须把淬火过的艾萨拉水晶交给一个有能力操纵恶魔能量的铁匠。$B$B在荆棘谷就有这样的一个铁匠——他就是加尔文，秘银会的领袖。他会按照你的要求打造武器，到祖尔格拉布和莫什奥格食人魔山之间的区域去寻找他的营地吧。$B$B愿你的决心和信念引领你度过这场考验。如果你失败了，你的神会对你微笑。去吧，$r。', '把货物交给荆棘谷的加尔文。', '我的老天，我简直不敢想象你为了这些原料都经历了什么样的磨难。几乎没有人能进入艾萨拉然后活着回来，更不用说那些挑战半神和巨人的家伙了!', '洛拉姆斯?我上次听到这个名字已经是许多年前的事了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3625, '魔化艾萨拉水晶武器', '$N，制造任何武器都需要花费一些时间。$B$B另外，你每三分钟才可以使用一次恶魔诅咒的力量。它可以削弱污染者和他的爪牙们的力量，但效果持续的时间可能会有差异。因此，你必须在恰当的时候使用恶魔诅咒！$B$B现在请稍等片刻，让我来为你锻造武器吧，$N。', '等待加尔文为你锻造武器。', '<加尔文擦了擦他额头上的汗。>$B$B没有比这更能对付恶魔的武器了，$N。', '如果打断锻造的过程，那么我打造出来的武器就是不完美的。请耐心一些，$N。', '铸造武器', '去找荆棘谷的加尔文。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3627, '收集破碎的护符', '要见到污染者的话，你就必须摧毁他手下的三个头目的力量，然后把他们身上的护符碎片收集起来。当你拿到三块碎片之后再回到我这里来，我会给你进一步的指示。$B$B出发吧，$N！到诅咒之地去！把戈洛尔、瑟温妮、奥利斯塔全部除掉！', '杀掉毁灭者戈洛尔、瑟温妮，以及大法师奥利斯塔。从他们到尸体上拿到戈洛尔的护符、瑟温妮的护符和奥利斯塔的护符。$B$B记住使用你的魔化艾萨拉水晶武器来削弱他们，否则他们是无法被杀死的——你必须小心谨慎地使用你的武器……', '『污染者』拉瑟莱克的护符再次合并了，但是拉瑟莱克已经意识到他手下的爪牙出了问题。他知道你即将去挑战他……', '三位一体，前方的通路已经敞开。', '', '去悲伤沼泽断矛路口找部落英雄的灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3628, '恶魔拉瑟莱克', '拉瑟莱克的巢穴位于诅咒之地最高的山脉的顶端，通往巢穴的唯一途径就是使用山脉附近的传送符文。只要你拥有护身符，就可以轻松到达巢穴。到了那巢穴之后，你必须召唤那个恶魔，护身符就是召唤的关键，$N，你要在污染者祭坛上使用它。$B$B去打败污染者拉瑟莱克，把他的犄角带回来。这将成为我们希望的象征——在这个饱经战火的世界上仍然有英雄存在的证据。', '消灭污染者拉瑟莱克，将污染者之角交给部落英雄的灵魂。另外你还要把污染者防护结界交给他，这样部落英雄的灵魂就可以消灭它，以避免它落入邪恶势力之手。', '今天是一个值得我们铭记的日子，诅咒之地的恶魔霸主终于被击败了!', '没有什么可害怕的了。', '', '去悲伤沼泽断矛路口找部落英雄的灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3629, '地精工程学', '高级的工程学有两个分支：侏儒派和地精派，请注意我提到地精工程学的唯一原因是因为我是个公正的训练师。他们喜欢制造一些会爆炸的东西，而且丝毫不关心有什么东西会被炸到——即使是他们自己。$B$B好吧，$N，读一下这本手册。如果你想要学习把自己炸上天的方法，就把这个交给加基森的尼克斯·斯普克斯宾。请记住，一旦你加入某一派，就永远也不能再加入另一派了，所以在你完成他交给你的任务之前要三思。', '如果你想要对地精工程学有更多了解，就把工程学教材交给加基森的尼克斯·斯普克斯宾。', '好吧，$N，你选择这条道路真是明智之极!随便什么蠢货都可以成为初级工程学的专家―那些地精跟他们那满是辐射的老窝就是铁一样的证据。要成为出色的哥布尔工程学专家，你必须有坚强的意志和稳固的双手―在这里我不得不强调稳固二字。$B$B竖起你的耳朵来好好听着，$N，你会学到许多东西的。', '我可以在一里外闻到新技师的气味，就像我可以在一里外闻到炸药的气味一样。你是来揭开炸药的神秘面纱的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3630, '侏儒工程学', '高级的工程学有两个分支：侏儒派和地精派，虽然我认为提到侏儒简直是浪费时间，但是你还是要对他们的技术保持警惕。他们制造了一大堆号称可以改变世界的小玩意，但是那些东西很少有能用的。$B$B好吧，$N，读一下这本手册。如果你想要学习永远都派不上用场的垃圾，就把这个交给铁炉堡的工匠大师欧沃斯巴克。请记住，一旦你加入某一派，就永远也不能再加入另一派了，所以在你完成他交给你的任务之前要三思。', '如果你想要对侏儒工程学有更多了解，就把工程学教材交给铁炉堡的工匠大师欧沃斯巴克。', '啊，一个追寻工程学真谛的年轻工程师，一个探求地精工程学奥秘的求知者!好吧，我的朋友，请原谅我的敏感和激动。我们现在的情况仍然十分糟糕，但是有你这样对工程学的真知孜孜以求的技师加入我们的行列，这仍然是让我很高兴的!', '嗯嗯，你有什么事要我帮忙吗?很显然，我有的是时间，因为我的家乡现在正笼罩在一片辐射云里，而我却站在这里无所事事。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3632, '侏儒工程学', '高级的工程学有两个分支：侏儒派和地精派，虽然我认为提到侏儒简直是浪费时间，但是你还是要对他们的技术保持警惕。他们制造了一大堆号称可以改变世界的小玩意，但是那些东西很少有能用的。$B$B好吧，$N，读一下这本手册。如果你想要学习永远都派不上用场的垃圾，就把这个交给铁炉堡的工匠大师欧沃斯巴克。请记住，一旦你加入某一派，就永远也不能再加入另一派了，所以在你完成他交给你的任务之前要三思。', '如果你想要对侏儒工程学有更多了解，就把工程学教材交给铁炉堡的工匠大师欧沃斯巴克。', '啊，一个追寻工程学真谛的年轻工程师，一个探\r\n求地精工程学奥秘的求知者!好吧，我的朋友，请原谅我的敏感和激动。我们现在的情况仍然十分糟糕，但是有你这样对工程学的真知孜孜以求的技师加入我们的行列，这仍然是让我很高兴的!', '嗯嗯，你有什么事要我帮忙吗?很显然，我有的是时间，因为我的家乡现在正笼罩在一片辐射云里，而我却站在这里无所事事。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3633, '地精工程学', '高级的工程学有两个分支：侏儒派和地精派，显然，地精工程学是所有明智的技师都会选择的一派，用华丽的高爆炸药和机械装置统治世界！$B$B好吧，$N，读一下这本手册。如果你想要学习地精工程学，就把这个交给加基森的尼克斯·斯普克斯宾。请记住，一旦你加入某一派，就永远也不能再加入另一派了，所以在你完成他交给你的任务之前要三思。', '如果你想要对地精工程学有更多了解，就把工程学教材交给塔纳利斯的加基森的尼克斯·斯普克斯宾。', '好吧，$N，你选择这条道路真是明智之极!随便什么蠢货都可以成为初级工程学的专家─那些地精跟他们那满是辐射的老窝就是铁一样的证据。要成为出色的哥布林工程学专家，你必须有坚强的意志和稳固的双手─在这里我不得不强调稳固二字。$B$B竖起你的耳朵来好好听着，$N，你会学到许多东西的。', '我可以在一里外闻到新技师的气味，就像我可以在一里外闻到炸药的气味一样。你是来揭开炸药的神秘面纱的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3634, '侏儒工程学', '高级的工程学有两个分支：侏儒派和地精派，虽然我认为提到侏儒简直是浪费时间，但是你还是要对他们的技术保持警惕。他们制造了一大堆号称可以改变世界的小玩意，但是那些东西很少有能用的。$B$B好吧，$N，读一下这本手册。如果你想要学习永远都派不上用场的垃圾，就把这个交给铁炉堡的工匠大师欧沃斯巴克。请记住，一旦你加入某一派，就永远也不能再加入另一派了，所以在你完成他交给你的任务之前要三思。', '如果你想要对侏儒工程学有更多了解，就把工程学教材交给铁炉堡的工匠大师欧沃斯巴克。', '啊，一个追寻工程学真谛的年轻工程师，一个探求地精工程学奥秘的求知者!好吧，我的朋友，请原谅我的敏感和激动。我们现在的情况仍然十分糟糕，但是有你这样对工程学的真知孜孜以求的技师加入我们的行列，这仍然是让我很高兴的!', '嗯嗯，你有什么事要我帮忙吗?很显然，我有的是时间，因为我的家乡现在正笼罩在一片辐射云里，而我却站在这里无所事事。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3635, '侏儒工程学', '高级的工程学有两个分支：侏儒派和地精派，虽然我认为提到侏儒简直是浪费时间，但是你还是要对他们的技术保持警惕。他们制造了一大堆号称可以改变世界的小玩意，但是那些东西很少有能用的。$B$B好吧，$N，读一下这本手册。如果你想要学习永远都派不上用场的垃圾，就把这个交给藏宝海湾的奥格索普·奥布诺提斯。请记住，一旦你加入某一派，就永远也不能再加入另一派了，所以在你完成他交给你的任务之前要三思。', '如果你想要对侏儒工程学有更多了解，就把工程学教材交给藏宝海湾的奥格索普·奥布诺提斯。', '你是来学习地精工程学的?好吧，你算是找对地精了。虽然诺姆瑞根当局可以用政治的手段来放逐那些智商比他们高的天才，但是他们也知道，知识是他们无法控制的!$B$B他们和我都很清楚，自从我离开诺姆瑞根之后，他们就失去了一个有史以来最伟大的工程师!如果你是个合格的学生，那么我会将我的知识倾囊相传。', '你好啊!如果你是来跟我说导航机器人坠毁在你家房顶上之类的事情，那么请去找我的律师。如果不是，请问找我有什么事?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3636, '与圣光同在', '亡灵天灾对联盟是一个长期的威胁，我想你应该明白这一点。最近，我们偶然发现了一些罕见的东西，$N。$B$B在贫瘠之地有一片令人恐怖的灌木林，它被称作剃刀高地。虽然那儿曾经是野猪人的家，但是很明显，它已经变成亡灵天灾的地盘，并衍生出了更加可怕的生物……这些生物都被巫妖寒冰之王亚门纳尔统治着。$B$B愿圣光与你同在，$N。终结那里的邪恶吧。', '大主教本尼迪塔斯要你去杀死剃刀高地的寒冰之王亚门纳尔。', '谢谢你，$N。天灾军团在疯狂扩张之前得再三考虑了。$B$B愿圣光保佑你。', '你必须杀死亚门纳尔。快点去吧。', '', '转至暴风城，去找教堂广场的大主教本尼迪塔斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3637, '侏儒工程学', '高级的工程学有两个分支：侏儒派和地精派，虽然我认为提到侏儒简直是浪费时间，但是你还是要对他们的技术保持警惕。他们制造了一大堆号称可以改变世界的小玩意，但是那些东西很少有能用的。$B$B好吧，$N，读一下这本手册。如果你想要学习永远都派不上用场的垃圾，就把这个交给藏宝海湾的奥格索普·奥布诺提斯。请记住，一旦你加入某一派，就永远也不能再加入另一派了，所以在你完成他交给你的任务之前要三思。', '如果你想要对侏儒工程学有更多了解，就把工程学教材交给藏宝海湾的奥格索普·奥布诺提斯。', '你是来学习地精工程学的?好吧，你算是找对地精了。虽然诺姆瑞根当局可以用政治的手段来放逐那些智商比他们高的天才，但是他们也知道，知识是他们无法控制的!$B$B他们和我都很清楚，自从我离开诺姆瑞根之后，他们就失去了一个有史以来最伟大的工程师!如果你是个合格的学生，那么我会将我的知识倾囊相传。', '你好啊!如果你是来跟我说导航机器人坠毁在你家房顶上之类的事情，那么请去找我的律师。如果不是，请问找我有什么事?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3638, '保密协议', '地精工程学追求的是高利润，以及更高的爆破性能！我们可以制作强力的炸弹和无敌的武器，你所阅读的手册中就包含这些知识。$B$B这本手册中还包含了我们古老的保密协议。一旦你成为了地精技师，你就不能转而成为侏儒技师。$B$B如果你愿意成为地精技师的话，请签署这份终生保密文件，然后再次和我说话。请谨慎考虑，$N。', '如果你同意成为一名地精技师，就右键点击保密协议，然后再次和加基森的尼克斯·斯普克斯宾谈一谈。', '欢迎你的加入，哥布尔工程师$N!你将接触到艾泽拉斯大陆上最强大的工程学结构图。$B$B你现在已经踏上追寻真知的道路，让我们来检验你的哥布尔工程学知识吧。我们将为你设计一个能够最大程度地发挥你哥布尔工程学天份的计画!', '如果你签署了这份文件并把它交给我的话，那事情就这么定了。你要知道这是影响你一生的抉择。如果你决心已定，那么欢迎你加入我们!', '', '去找塔纳利斯的尼克斯·斯普克斯宾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3639, '工作成果', '作为你的指导者，我想看看你的工作成果。你是个熟练的技师，这是毫无疑问的，$N。我要对你的工作进行分析，帮助你在地精工程学的光明大道上更快地前进。我需要以下物品：20颗重磅铁制炸弹、20颗实心炸弹和5只自爆绵羊——注意安全第一！$B$B把这些东西交给我，我就可以发给你一张属于你自己的地精工程师协会会员卡，如果你想要拜访世界各地的地精工程学训练师，这张卡是必须的！', '将20颗重磅铁制炸弹、20颗实心炸弹和5只自爆绵羊交给加基森的尼克斯·斯普克斯宾。', '看来你已经准备好接受适当的训练。我现在宣布拟为哥布尔工程师$N!$B$B你将可以参与哥布尔工程师各种残忍的创作。好好玩吧，试着别把自己的脸给炸了。', '一旦我收到你制作的物品并检查完毕之后，我就会教最后一些知识，好让你要加入我们哥布尔工程师这个严格小团体!', '', '去找塔纳利斯的尼克斯·斯普克斯宾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3640, '保密协议', '侏儒工程学是一门可以满足我们日常生活需要的科学！我们设计的图纸让我们研制出可以控制世界的装置，你所阅读的手册中就包含这些知识。$B$B这本手册中还包含了我们古老的保密协议。一旦你成为了侏儒技师，你就不能转而成为地精技师。$B$B如果你愿意成为侏儒技师的话，请签署这份终生保密文件，然后再次和我说话。请谨慎考虑，$N。', '如果你同意成为一名侏儒技师，就右键点击保密协议，然后再次和铁炉堡的工匠大师欧沃斯巴克谈一谈。', '欢迎你的加入，$N!你即将接触到艾泽拉斯大陆上最先进的工程学结构图。$B$B既然你致力于这门科学，那么现在让我们来检验一下你在地精工程学方面的本事，然后帮助你设计一整套发展计画，让你尽可能地发挥你的地精工程学天份!', '如果你签署了这份文件并把它交给我的话，那事情就这么定了。$B$B我接下来要告诉你的是，签署这样一份保密协定是非常严肃的事情。我签了一份，我们的其它成员也都签了。你将要加入这个幸运的团体了，工程师$N!', '', '去找丹莫罗的工匠大师欧沃斯巴克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3641, '工作成果', '如果你已经准备好了要制作一些真正精彩的设备，那么你就来对地方了。看得出来，你是个熟练的技师，的那我还想看到一些你的作品。我要对你的工作进行分析，帮助你在侏儒工程学的光明大道上更快地前进。我需要以下物品：6根秘银管、1只精确瞄准镜和2个高级假人！$B$B把这些东西交给我，你就能成为一名官方认可的侏儒技师，能够使用我们的全部设计图表了！', '将6根秘银管、1只精确瞄准镜和2个高级假人交给铁炉堡的工匠大师欧沃斯巴克。', '今天就是你成为一个真正工程师的日子，$N。别担心那些炸弹和爆裂物，现在该是闪亮刺激一下的时候了!', '一旦我收到你制作的物品并检查完毕之后，你就可以成为受认可的地精工程师，你可以不受限制地拜访世界上任何地方的任何地精工程学训练师。', '', '去找丹莫罗的工匠大师欧沃斯巴克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3642, '保密协议', '侏儒工程学是一门可以满足我们日常生活需要的科学！我们设计的图纸让我们研制出可以控制世界的装置，你所阅读的手册中就包含这些知识。$B$B这本手册中还包含了我们古老的保密协议。一旦你成为了侏儒技师，你就不能转而成为地精技师。$B$B如果你愿意成为侏儒技师的话，请签署这份终生保密文件，然后再次和我说话。请谨慎考虑，$N。', '如果你同意成为一名侏儒技师，就右键点击保密协议，然后再次和藏宝海湾的奥格索普·奥布诺提斯谈一谈。', '欢迎你的加入，$N!你即将接触到艾泽拉斯大陆上最先进的工程学结构图。\r\n\r\n既然你致力于这门科学，那么现在让我们来检验一下你在地精工程学方面的本事，然后帮助你设计一整套发展计划，让你尽可能地发挥你的地精工程学天份!\r\n\r\n', '如果你签署了这份文件并把它交给我的话，那事情就这么定了。$B$B虽然我有时候会因为诺姆瑞根的问题对组织产生异议─特别是对那个愚蠢的技工大师欧沃斯巴克─但是，保密协议高于一切!你必须签署它，然后一生都要遵循它。', '', '去荆棘谷找藏宝海湾的奥格索普·奥布诺提斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3643, '工作成果', '如果你已经准备好了要制作一些真正精彩的设备，那么你就来对地方了。看得出来，你是个熟练的技师，的那我还想看到一些你的作品。我要对你的工作进行分析，帮助你在侏儒工程学的光明大道上更快地前进。我需要以下物品：6根秘银管、1只精确瞄准镜和2个高级假人！$B$B把这些东西交给我，你就能成为一名官方认可的侏儒技师，能够使用我们的全部设计图表了！', '将6根秘银管、1只精确瞄准镜和2个高级假人交给藏宝海湾的奥格索普·奥布诺提斯。', '这是你的第一张地精工程师协会会员卡!$B$B这张卡片中包含14天的费用，两周过后，这张卡就会到期。届时你可以到任何地精工程学训练师那儿缴付一定的费用，换得另一张卡片。如果没有卡片，你的会员身份就会暂时失效，同时你也无法从我们这里学习新的结构图。$B$B这对你已经学会的东西毫无影响，一旦成为地精工程师，你就终身都是地精工程师啦。$B', '在我收到你制作的物品并检查完毕之后，我就会给你发放一张真正的地精工程师协会会员卡!在这张卡片的有效期内，你可以不受限制地拜访世界上任何地方的任何地精工程学训练师。', '', '去荆棘谷找藏宝海湾的奥格索普·奥布诺提斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3644, '会员卡续费', '', '', '既然你是个从业的地精工程师，而且信誉纪录良好，那么我可以收取一定的费用帮你延长会员期。你付费之后就可以得到一张新的会员卡，你可以凭此卡到世界各地的地精工程学训练师那里学习新的结构图。$B$B这张卡的有效期是两周，过期后你必须再次续费才能享受它所带来的好处!', '要想延长你的会员期的话，你就得花些钱来为你的会员卡续费。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3645, '会员卡续费', '', '', '既然你是个从业的地精工程师，而且信誉纪录良好，那么我可以收取一定的费用帮你延长会员期。你付费之后就可以得到一张新的会员卡，你可以凭此卡到世界各地的地精工程学训练师那里学习新的结构图。$B$B这张卡的有效期是两周，过期后你必须再次续费才能享受它所带来的好处!', '要想延长你的会员期的话，你就得花些钱来为你的会员卡续费。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3646, '会员卡续费', '$B', '', '既然你是个从业的地精工程师，而且信誉纪录良好，那么我可以收取一定的费用帮你延长会员期。你付费之后就可以得到一张新的会员卡，你可以凭此卡到世界各地的地精工程学训练师那里学习新的结构图。$B$B这张卡的有效期是两周，过期后你必须再次续费才能享受它所带来的好处!', '要想延长你的会员期的话，你就得花些钱来为你的会员卡续费。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3647, '会员卡续费', '', '', '既然你是个从业的地精工程师，而且信誉纪录良好，那么我可以收取一定的费用帮你延长会员期。你付费之后就可以得到一张新的会员卡，你可以凭此卡到世界各地的地精工程学训练师那里学习新的结构图。$B$B这张卡的有效期是两周，过期后你必须再次续费才能享受它所带来的好处!', '要想延长你的会员期的话，你就得花些钱来为你的会员卡续费。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3661, '月神之兽？', '枭兽是难以预测的生物，$N。它们有着极端温顺的一面，如果它们重视的东西受到威胁，这些生物就会变得非常凶猛。$B$B传说这些野兽是由艾露恩创造的，我对这种说法的真伪很感兴趣。$B$B近来，我听说辛特兰的枭兽数量越来越多——这些凶残、原始、野蛮的家伙在辛特兰的野外四处横行。你能帮我收集一些枭兽的羽毛吗？', '为鲁瑟兰村的艾瑞拉斯·琥珀收集15支枭兽羽毛。', '谢谢你为我带来了这些，$N。$B$B你对枭兽有进一步的了解了吗?$B$B也许这些羽毛包含着我们想要知道的资讯。它们是凶残的怪物，还是被误导的宠物?我想知道真相……$B$B我将继续进行研究―请过一段时间再回来跟我谈谈。', '如果可能的话，尽可能避开那些枭兽，$N。它们也许会以为你要伤害它们……', '', '去泰达希尔找鲁瑟兰村的艾瑞拉斯·琥珀。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3701, '索瑞森废墟', '到燃烧平原的索瑞森废墟中去尽可能多地收集情报。$B$B据说那里散布着许多神秘的上古遗物，也许你可以在那里搜寻一番，$N。小心在那里保护着废墟的索瑞森的刺客们。', '到燃烧平原的索瑞森废墟中去，从索瑞森遗物上搜集信息。当你收集到足够的信息之后，就回到皇家历史学家阿克瑟努斯那里。', '哦，我的天啊!这些资讯解释了很多关于索瑞森的事情。$B$B我们还有很多需要了解的东西!', '你带来什么新的消息没有?', '', '去铁炉堡找王座厅的皇家历史学家阿克瑟努斯。', '收集情报', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3702, '索瑞森废墟', '你愿意听听黑铁矮人的简要历史吗？', '听皇家历史学家阿克瑟努斯讲述索瑞森的历史。', '我们可以继续进行下一步了吗?', '请听我讲完索瑞森的历史。', '索瑞森的故事', '去找丹莫罗的皇家历史学家阿克瑟努斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3741, '希拉里的项链', '我朋友希拉里的项链丢了，我们怎么都找不到。我们一整天都在这儿钓鱼，已经把周围都找遍了。我认为它只可能是落到湖里去了。我们的父母不让我们在湖里游泳……我妈妈说水下有一些可怕的生物，但是你好像不怕那些东西。$B$B你去帮她找到项链，好吗？', '找到希拉里的项链，将其还给湖畔镇的希拉里。', '谢谢你帮我找到项炼，$C$G先生:小姐;……你可真好!我的小猫也感谢你―对吗，喵喵?', '你好。我很想我的项炼!是我爸爸送我的。爸爸说湖水中有怪兽，你打败它们了吗?', '', '去赤脊山找湖畔镇的希拉里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3761, '安戈洛的泥土', '据说安戈洛环形山一带的土壤非常肥沃，而且具有不可思议的魔法能量。塞纳里奥议会需要大量的这种土壤以进行研究，到安戈洛去帮我们收集足够的土壤吧。$B$B有时肥沃的土壤会成堆地聚集在地表，某些野兽也可能带有这样的土壤。把它们都交给格德，它就在这附近的那一堆堆泥土旁。他脾气不错，但是别惹恼他！', '收集20份安戈洛的泥土，把它们交给雷霆崖的格德。', '噢，这就对了，$N，不用帮忙了，我自己会把这些土堆上去的!如果伟大的先祖之灵们想要让这里有一大堆土，那他们会凭空变出一堆来，根本用不着你来动手，现在你看他们像是有这个意思吗?!$B$B大德鲁伊想再跟你谈谈，但是就他的下一个任务而言，你将发现熟练掌握草药学方面的知识是很有必要的。如果你对草药学一窍不通，他也不会让你无事可做。', '放轻松点，如果你拿来了安戈洛的泥土，就赶紧拿出来，不然就该干什么干什么去!', '', '去莫高雷找蛮鬃水井的格德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3764, '安戈洛的泥土', '据说安戈洛环形山一带的土壤非常肥沃，而且具有不可思议的魔法能量。我想要知道这事的真假，到安戈洛去帮我们收集足够的土壤吧。$B$B你可能会认为派你去做收集任务是委屈你了，我和塞纳里奥议会可不喜欢这种态度。将样本交给耶纳尔，他总躲在树后浪费时间，你只要去找那一堆堆的泥土就是了。剩下的事情都交给他办，别来找我。', '收集20份安戈洛的泥土，把它们交给达纳苏斯的耶纳尔。', '高贵的$C，在此卸下你辛苦找来的货物吧。它肯定为你增添了不少负担……就像我那梦想一样沉重的负担。大德鲁伊说你应该得到回报，所以，拿着这个。$B$B大德鲁伊鹿盔想再跟你谈谈，但是就他的下一个任务而言，你将发现熟练掌握草药学方面的知识是很有必要的。如果你对草药学一窍不通，他也不会让你无事可做。', '哦，当然，泥土。大德鲁伊想要20份，所以你就得拿来20份。没有就别废话了!', '', '去达纳苏斯找塞纳里奥区的耶纳尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3781, '晨光麦研究', '有了这件名为常青袋的东西，我们已在来自安戈洛环形山的土壤上种植了萨伦迪斯种子。这些种子繁殖出了大片的草药。其中一种是晨光麦，我们对这种神秘的草药知之甚少，不过我打算揭开其中的奥秘。$B$B把这个交给楼下的玛斯雷，他会给你一些种子，然后你就可以开始了。要是种子用完了的话，你就得从他那儿购买新的种子。', '将大德鲁伊的草种购买券交给达纳苏斯城塞纳里奥区的玛斯雷·驭熊者。', '嗯，这张优惠券值二十份种子。要是你把种子用完了，我们仍可以为你提供更多的种子。不幸的是，大量生产萨伦迪斯种子所需的费用可不小，这正是我们要收取成本费以解决资金问题的原因。$B$B那些带着晨光麦回来的冒险者们会发现大德鲁伊给予的回报要远远大于他们所付出的代价。', '朋友，和平与宁静与你同在。是大德鲁伊派你来的，对吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3782, '晨光麦研究', '有了这件名为常青袋的东西，我们已在来自安戈洛环形山的土壤上种植了萨伦迪斯种子。这些种子繁殖出了大片的草药。其中一种是晨光麦，我们对这种神秘的草药知之甚少，不过我打算揭开其中的奥秘。$B$B把这个交给我的女儿巴珊娜，她会给你一些种子，然后你就可以开始了。要是种子用完了的话，你就得从她那儿购买新的种子。', '将草种购买券交给雷霆崖的巴珊娜·符文图腾。', '嗯，这张优惠券值二十份种子。要是你把种子用完了，我们仍可以为你提供更多的种子。不幸的是，大量生产萨伦迪斯种子所需的费用可不小，这正是我们要收取成本费以解决资金问题的原因。$B$B那些带着晨光麦回来的冒险者们会发现大德鲁伊给予的回报要远远大于他们所付出的代价。', '朋友，和平与宁静与你同在。是大德鲁伊派你来的，对吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3783, '雪怪计划！', '我的朋友总是不断想出天才般的点子来，我感觉我总是比不上他们……直到今天！我想到了一个好主意！如果你答应不告诉别人的话，我就和你分享这个秘密……$B$B我要制作一个机械雪人！我的朋友看到它的时候肯定会被吓一跳，然后就会被我的技术和创意所震撼！$B$B首先，我需要那些冰蓟雪人身上的厚雪人毛皮。你能帮帮我吗？雪人一般都在这里的东南边活动。', '为永望镇的乌米收集10张厚雪人毛皮。', '这些皮毛非常完美，$N。好的开始是成功的一半!', '我有很多准备工作要做，请你尽快把毛皮交给我!', '', '去冬泉谷找永望镇的乌米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3785, '晨光麦研究', '这是你所需的与萨伦迪斯种子一同使用的常青袋，当然，你手中还必须有安戈洛的泥土样本给种子做肥料。这些东西都准备好了之后就使用常青袋，剩下的就交给它了。$B$B当你种出足够的晨光麦之后，将它们交给我就行了。请不要打扰大德鲁伊，他事务繁忙，而且他也没必要为收集晨光麦的事情操心！', '用一个常青袋、一包萨伦迪斯种子以及两份安戈洛的泥土来尝试种植晨光麦。$B$B将10株晨光麦交给达纳苏斯的玛斯雷·驭熊者。', '干得好，$N。当大德鲁伊需要晨光麦时，我会把这些交给他的。同时，请收下这个作为塞纳里奥议会对你的酬谢。$B$B我们对晨光麦的需求量非常大，如果你想要继续帮助我们的话，那么当你种植出更多的晨光麦之后就把它们交给我。', '嗯，$N，你种植出用于大德鲁伊的研究工作的晨光麦了吗?他为塞纳里奥议会进行的研究事关重大，你的帮助必定给你带来丰厚的回报!', '', '去达纳苏斯找塞纳里奥区的玛斯雷·驭熊者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3786, '晨光麦研究', '这是你所需的与萨伦迪斯种子一同使用的常青袋，当然，你手中还必须有安戈洛的泥土样本给种子做肥料。这些东西都准备好了之后就使用常青袋，剩下的就交给它了。$B$B当你种出足够的晨光麦之后，将它们交给我就行了。请不要打扰大德鲁伊，他事务繁忙，而且他也没必要为收集晨光麦的事情操心！', '用一个常青袋、一包萨伦迪斯种子以及两份安戈洛的泥土来尝试种植晨光麦。$B$B将10株晨光麦交给雷霆崖的巴珊娜·符文图腾。', '干得好，$N。当大德鲁伊需要晨光麦时，我会把这些交给他的。同时，请收下这个作为塞纳里奥议会对你的酬谢。$B$B我们对晨光麦的需求量非常大，如果你想要继续帮助我们的话，那么当你种植出更多的晨光麦之后就把它们交给我。', '嗯，$N，你种植出用于大德鲁伊的研究工作的晨光麦了吗?我们对安戈洛环形山神秘构造的了解已经越来越多了，谢谢你为我们提供的帮助。', '', '去雷霆崖的长者高地找巴珊娜·符文图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3791, '晨光麦的秘密', '坦白说吧，$N。我对达纳苏斯的大德鲁伊以塞纳里奥议会的名义、使用 议会的资源来大量生产晨光麦的原因很感兴趣——不，应该说是极度关注。我是一名研究员——研究诅咒是我的专长。我听说晨光麦在一定的条件下可以像其它草药那样用于进行诅咒。$B$B我想了解更多的情况，因此我请求你的帮助。给我带十株晨光麦回来，我会好好报答你的。', '将10株晨光麦交给羽月要塞的奎恩提斯。', '呃，这些晨光麦让我感觉有些……不可思议。大德鲁伊鹿盔会以月神的名义用这些东西做什么?$B$B无论如何，再次感谢你的帮助。拿着这件小东西……你知道的，给你的回报。我对晨光麦的研究还要进行一段时间，因此我需要更多的晨光麦。虽然我精通于此，但我认为我仍需要足够的时间来观察晨光麦是否具有炼金术方面的价值。话说回来，跟这种东西待在一起还真让我感觉不大舒服……', '我要十株晨光麦―要启动我的研究，至少需要这么多。毫无疑问，整个研究过程肯定要消耗不少晨光麦，但这也正是研究的本质。', '', '去菲拉斯找萨尔多岛的奎恩提斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3792, '羽月要塞的晨光麦', '', '', '谢谢你，$N。我会将这些东西存储起来，虽然我无法像大德鲁伊那样对资源具有掌控权，但是我可以尽力为你提供一点东西聊表谢意。总之，如果大德鲁伊持续不断地收集晨光麦，天知道会发生什么事情。记着我说的，这里面必有古怪。$B$B另外，晨光麦对我来说是多多益善，我会以5株为单位购买这些东西。', '你好，我们又见面了，$N。我的研究进展得相当顺利，不果如果你还有5株晨光麦的话，我会很乐意地从你这儿购买的。呃……“乐意”在这里只是一个修饰语罢了，和这些东西相处的时间越长，我就越发感到不太舒服。尽管如此，我的研究任务仍要求我必须认真对待工作，并尽力克服我这奇怪的心理作用。', '', '去找菲拉斯的奎恩提斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3802, '黑铁的遗产', '你可以在律法之环外的工艺之厅里找到弗诺斯·达克维尔。杀掉那个卑鄙的家伙，拿回我的铁胆之锤。$B$B把铁胆之锤拿到索瑞森神殿去，然后把它放在正确的地方——就是我的雕像的手里。$B$B当你把铁胆之锤放上去之后，我存放主宰钥匙的那个小机关将会打开。更重要的是，铁胆之锤将会永远掌握在我的手中。如果有人想要拿走战锤的话，那整座雕像和战锤都会碎裂，永远无法修复。', '杀掉弗诺斯·达克维尔并拿回战锤铁胆。把铁胆之锤拿到索瑞森神殿去，将其放在弗兰克罗恩·铸铁的雕像上。', '战锤慢慢地滑入巨大的黑铁雕像的手中。此时，雕像基座处的一个小隔间被打开，你在里面找到了……', '雕像隐隐约约地矗立在你的面前。', '', '转至黑石深渊，在索瑞森神殿中找到弗兰克罗恩·铸铁的雕像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3803, '达纳苏斯的晨光麦', '', '', '棒极了―毫无疑问，这些晨光麦定能取悦大德鲁伊，不过我必须承认……仅仅是靠近它们就让我感到有些不舒服。可以想象大德鲁伊要忍受这么多的晨光麦是一件多困难的事!$B$B这是给你的，$N。我们感谢你提供的帮助。', '大德鲁伊始终在寻找更多的晨光麦以供塞纳里奥议会研究之用。我们以10株为单位进行收购，而且会奖励给你一包很有用的东西。如果你弄到了10株晨光麦，就来找我，我将奖赏你的。', '', '去找泰达希尔的玛斯雷·驭熊者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3804, '雷霆崖的晨光麦', '', '', '棒极了―毫无疑问，这些晨光麦会在适当时候派上用场。我们知道夜精灵也在进行关于这些草药的研究，但是我们还不清楚如果他们有所发现的话，这些草药将用于何种目的。大德鲁伊认为我们应该继续收购晨光麦，直到我们找出其中的奥秘。$B$B这是给你的，$N。我们感谢你提供的帮助。', '大德鲁伊始终在寻找更多的晨光麦以供塞纳里奥议会研究安戈洛环形山之用。我们以10株为单位进行收购，而且会奖励给你一包很有用的东西。如果你弄到了10株晨光麦，就来找我，我将奖赏你的。', '', '去找凄凉之地的巴珊娜·符文图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3822, '克罗格鲁尔', '$N，我们整支小分队都被抓住了，除了我之外的所有同伴都被杀了。$B$B他们的头领克罗格鲁尔想要把我留下来举行某种仪式。$B$B我被绑在这个祭坛上，被那些野兽用酷刑折磨。不到一个小时，我就被活活折磨致死。那个野兽摘下了我的结婚鼻环，把它戴在了自己的手上。我从来没有见过如此无耻残暴的行为！$B$B找到克罗格鲁尔，杀了他！把我的戒指交给萨特拉克。$B$B另外，$N，告诉他，我们会再次见面的……来世再见……', '从克罗格鲁尔手中拿回沙妮的鼻环，把它还给卡加斯的萨特拉克。搜寻巨槌石的每一处山洞和矿井。', '<萨特拉克一下子崩溃了。>$B$B我们原本准备去辛特兰……她没有告诉过你吗?这原本是她最后的一个任务。$B$B<萨特拉克开始抽泣。>$B$B我不要这个东西，$N。拿走它，丢掉它，随你怎样!它对我来说没有丝毫意义。没有了她……', '你找到沙妮了吗?她还好吗?', '', '去荒芜之地找卡加斯的萨特拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3823, '消灭火腹食人魔', '我们必须先发制人！$B$B我先简单地向你介绍一下现在的状况，士兵。$B$B燃烧平原上的火腹食人魔是黑石兽人的盟友。它们和那些邪恶的兽人一起工作，帮助守卫蕴藏着丰富矿藏的巨槌石，并保证那条补给线一直正常运作。$B$B现在出发吧，$N。削弱他们的力量然后回来向我报告。$B$B<奥拉留斯向空中伸出手，然后作出被掐住脖子的表情。>$B$B我要杀了你，温奇！', '杀掉15个火腹食人魔法师、7个火腹食人魔和7个火腹蛮兵。', '干得好，士兵!兽人和巨魔会因为这次打击而混乱几分钟，也许几个小时!', '你的军服还没有沾上足够的血，士兵!', '', '去燃烧平原找摩根的岗哨的奥拉留斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3824, '蛮王戈泰什', '我告诉你，他们现在已经被搞得晕头转向了！我们的下一步行动将是决定性的。$B$B干掉那个野蛮的食人魔之王戈泰什。更重要的是，你必须把他的徽记带回来，这样我就可以准备对火腹食人魔发动第三次攻击了。$B$B你要留神，士兵，戈泰什并不在巨槌石上，而是在巨槌石西面的某座黑石兽人的建筑物中。$B$B你的任务很简单。找到戈泰什，取走他的徽记。完成任务之后回到我这里来。$B$B闭嘴，温奇！', '取得戈泰什的标记。', '看看这颗脑袋，士兵。真是让人讨厌!当火腹巨魔看到这颗肥大的头挂在长矛上并竖在他们的山头上时，他们一定会变得歇斯底里!$B$B<奥拉留斯肆无忌惮地咯咯笑着。>', '哦，光荣的一天!你带回那个家伙的头了吗?', '', '去燃烧平原找摩根的岗哨的奥拉留斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3825, '示众扬威', '士兵，你还有最后一件事要做。$B$B我已经把戈泰什的徽记挂在了一支长矛上。现在你要做的就是把这支长矛带到巨槌石的山顶去，把它插在地上。这样，你就能看到那些怯懦的食人魔四散逃窜了！当你完成这个任务之后，回到我这里来，我会为你的辛勤工作而奖励你的。$B$B<奥拉留斯看上去有些出神。>', '把戈泰什的徽记放在巨槌石的山顶上。找一块软土堆把串着徽记的长矛插上去就可以了。', '干得太棒了，士兵!太让我惊讶了!我会因此获得勇气勋章的，呃，我的意思是，你会因此而获得丰厚的奖励!', '完成任务了?你有没有把当时的场景画下来?', '', '去燃烧平原找摩根的岗哨的奥拉留斯。', '放置戈泰什的徽记', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3841, '领养孤儿', '噢，你好，$N。很高兴再次见到你。去达纳苏斯的旅途怎么样？$B$B你不在的这段时间里，我们取得了相当大的进展，你会为此感到高兴的。我们甚至保存了一整巢的蛋。不幸的是，我们找到这些蛋的母亲的时候，它已经死掉了。$B$B呃，你要取一只作为宠物吗？它们很快就要孵化了，所以它们会需要一个好$G父亲:母亲;的。你认为呢？$B$B如果你真的感兴趣的话，请带上一颗蛋，到闪光平原的赛车场去找奎恩丁。他会告诉你更多细节的。', '与千针石林的奎恩丁谈一谈。', '啊，一枚精灵龙的蛋!要是我没看错的话，它就快要破壳而出了。能找到这东西已属不易，更不用说是一枚完好无损的蛋了。在菲拉斯那一带，这些日子已经很少见到精灵龙的蛋了。我知道在这片区域有很多偷猎者，他们以种种理由捕杀精灵龙。情况真的相当糟糕……这些小精灵龙成年后将变得极为美丽。$B$B你是怎么找到的呢?', '你好啊，$C。$B$B可别被我所待的地方给糊弄了，我到这儿来可不是为了赛车……不是为了娱乐而来。$B$B我到千针石林是为了调查这片土地到底有多么贫瘠。现在我要让这里的盐硷地变成新鲜肥沃的土壤，使它获得新生!也许我很快就要在这附近发现水源了。$B$B你有没有觉得菲拉斯和千针石林之间的差异之大简直令人感到匪夷所思?一定有什么奇怪的魔法从中作祟……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3842, '即将孵化', '辛达尔和耶尔卡？这可太有意思了。我希望那些小精龙能意识到她们的一片好心。她们俩都相当能干。$B$B这样看来，她们把这颗蛋作为礼物送给你了。呃，好吧，现在你应该对这颗蛋负责了。看起来它马上就要孵化了，但是我们应该确定它是健康的。$B$B我需要两份坚韧药剂，然后用它们来施放一个小小的法术保护这颗蛋。至于其它的材料，我这里就有。', '将2份坚韧药剂交给千针石林的奎恩丁。', '好极了。给我一些时间，让我来混合这些成分，然后看看这颗蛋能不能顺利孵化。', '我在这儿待的时间越长，就越想参与到赛车中去，$N。我可真有些犹豫……$B$B你找到药剂了吗?在我辨别出这颗蛋是否健康之后，我就会把它还给你，你要好好地保护它，直到小精龙孵化为止。$B$B准备好了就告诉我。', '', '去千针石林找沙漠赛道的奎恩丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3843, '新的生命', '很不错，$N。如果它的妈妈活着生下它的话，那它将是一只健康的宠物！$B$B要是你正巧要去辛特兰的鹰巢山，那我建议你去找一个名叫阿格纳的矮人谈谈，他精于训练动物，可以就孵化的最终步骤对你进行指导。$B$B但是你一定要快，$N，这颗蛋很脆弱，要是没有悉心的照料，它可活不了多久。', '带着这枚脆弱的小精龙卵去辛特兰，与阿格纳谈一谈，但是你一定要在它还有生命力的时候赶到，在蛋里的小生命夭折之前，你只有1小时的时间。', '呃……我以前可没见过这种蛋。要是我没判断错的话，这是精灵龙……看起来像是小精龙一类的。很好，这真是棒极了。$B$B要是这个小家伙能破壳而出，而且强壮健康的话，我们该给它找些食物。你最好赶紧帮我找些食物来吧。', '你好，$N。我能帮你什么忙吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3845, '无人知晓的秘密', '你把那只袋子从水中拉上了岸。如果你检查一下袋子中的东西，那么你应该可以知道它是谁的袋子。$B$B在马绍尔营地那里有一些迷路的旅行者，也许你可以在那里发现更多的线索。', '查看袋子里的东西，然后将它们交给物主。', '哦……当然，这些东西看起来很熟悉……事实上，是有些熟悉……', '你好，我以前见过你……是不是啊?', '', '去安戈洛环形山找马绍尔营地的林克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3861, '咕咕嘎！', '“咕咕嘎……咕咕嘎……咕咕！$B$B咕咕嘎……咕咕嘎……咕咕。”$B$B小鸡抬头看着你，然后伸出爪子探到地面上。你认为它是在拼写某个单词，但是又不确定是什么单词。S-A-L-D-E-A-N……是指萨丁农场吗？在你发出询问之前，小鸡转过身子，做它自己的事儿去了。', '找一些特殊的鸡饲料，把它交给友好的小鸡。当你找到小鸡的时候，在喂食它之前对它做出高兴的表情。（使用/cheer命令）', '“咕咕嘎!!”$B$B小鸡开始狼吞虎咽地啄食你丢给它的食物。$B$B不一会儿，小鸡开始注视四周，有些受惊的样子。它来回地跺着步，显得极为不适。难道这只小鸡要下蛋了吗?你认为最好检查一下它的身下。', '小鸡用它那双黑暗而凌厉的眼神盯着你，等着你给它喂食。$B$B“咕咕嘎!$B$B咕咕……咕咕……咕咕。”', '', '去找鸡。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3881, '抢救物资', '我不知道你是怎么到这儿来的，但是你可真是个受欢迎的$r！我是威利德·马绍尔，这支中立探险队的头儿。我们的小队近来遭受了一连串灾难，其中最为严重的就是我们低估了安戈洛环形山的蛮荒程度！$B$B我们在逃离位于环形山西南部和东北部的营地时落下了重要的物资。你似乎是个足够强壮的$r——能帮助我们去取回这些物资吗？', '将食物箱和研究设备交给安戈洛环形山的威利德·马绍尔。', '你取回了我们的食物和研究设备!你不仅拯救了探险队，还拯救了我们的生命。我和我的队员们对你感激万分，我们要好好感谢你。$B$B尽管我们现在的处境有些窘迫，但是你给予了我们无私的帮助，我绝对不会亏待你。谢谢你，$N―你在马绍尔探险队里赢得了一个朋友!', '要是我们还想有活着离开这鬼地方的机会，首先就需要大箱大箱的食物来充饥。此外，尽可能取回研究设备对身陷困境的我们而言也是个福音。', '', '去安戈洛环形山找马绍尔营地的威利德·马绍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3882, '挖骨头', '你也许认为我在马绍尔探险队里当挖掘工是因为我喜欢这活儿，好吧，世上可能的确有比这更糟糕的差事……但是我还真没见过。$B$B我们本应是在恐惧小道那个鬼地方进行剑龙和双帆龙化石的挖掘工作——顺便提一句，那地名可真古怪。呃，那儿也有许多活着的恐龙！威利和霍莱坚持要研究这些东西，所以我们还是得弄些恐龙骨头来。咱们私下里说说，其实你只要从活着的恐龙身上给我取些骨头回来就行了。', '将8根恐龙骨头交给安戈洛环形山的斯巴克·尼米尔。', '真棒，这些应该能骗过他们……现在，如果你允许的话……$B$B<斯巴克提高了音量。>$B$B感谢你帮助我们从地下挖掘出这些骨头，而且丝毫没有伤害此地的野兽。$B$B<他的音量又降了下来。>$B$B你是否伤害了它们，这跟我没啥关系。就这样吧，好吗?拿着这个―或许它能让你从此闭口不谈此事。能活着出去就好!', '你可以对我有看法，但是，他们拿去研究的骨头究竟是来自古代的剑龙和双帆龙还是那些在我们扎营时差点把我们生吞了的恐龙，对他们而言没有什么区别。只要我们能活着离开这儿，我就高兴了……', '', '去安戈洛环形山找马绍尔营地的斯巴克·尼米尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3883, '异型的生态', '我们仅仅遭受到了一点挫折，这并不意味着我们要停止研究！在被迫逃到这里之前，我们曾调查过环形山南部地区的格里什昆虫。它们与安戈洛的生态环境有些格格不入，我们想要查明原因。在它们的巢穴中必然存在幼虫的孵化室，你可以可通过那些悬垂在天花板上的虫卵来判断幼虫孵化室的所在。随便找一个这样的孵化室，刮取一份虫穴内壁的样本，把它装到这个小瓶子里交给我，但是你要多加小心！', '使用采集瓶从安戈洛环形山的某个格里什虫巢的孵化室中收集一份巢穴侧壁的样本，在有悬挂着的虫卵的房间里收集样本。$B$B将虫穴内壁样本交给安戈洛环形山的霍莱伊·马绍尔。', '嗯，不错。你帮了我的大忙……我希望能给你更多的回报，但是我现在被困在这片原始的土地上，很难再给你别的什么。不管怎么说，没有你的帮助，我是不可能在这里进行研究的!', '你弄到格里什虫巢的样本了吗，$N?', '', '去安戈洛环形山找马绍尔营地的霍莱伊·马绍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3884, '威利德的日记', '你找到了一本被撕破的日记，其中的某些部分仍然清晰可辨，目录中有威利德·马绍尔的署名。如果日记上面的记载没错的话，那么你可以在环形山的北部地区找到威利德。根据日记中所说的，他和他的同伴们的营地被袭击了，所以他们不得不寻找更高处的空地扎营，以避开横行在环形山里的凶残野兽。', '将日记还给安戈洛环形山中的威利德·马绍尔。', '我的日记!我以为它和我们带到安戈洛的其它物品一样被弄丢了，谢谢你把它还给我!', '你好!我和我的同伴很高兴能在这里见到一个活生生的$r，而不是那些巨大野蛮的野兽!你来安戈洛环形山干什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3901, '断骨骷髅', '你已经向我们展示了你在正常情况下的潜力，$N——现在让我们来看看你在压力下的表现吧。$B$B断骨骷髅是巫妖王手下的走狗，与你先前干掉的那些僵尸相比，它们更为强韧而凶残。去杀掉它们，再次向被遗忘者证明你的能力吧。别耽搁时间——当你完成任务后，就来找我谈谈。', '杀掉8个断骨骷髅，然后回到丧钟镇的暗影牧师萨维斯那里。', '你完成了我给你的任务，$N―你展示出了非凡的能力，并证明了你是值得拥有自由的。你会因此而面对无数的敌人，但是无论其它人如何看待我们，如何敌视我们，重要的是，我们自由了，不会再被巫妖王的意志束缚了。$B$B带上这些，继续前进吧。你要做的事还很多，$C。', '那些在执行任务时浪费时间的新兵也许会像我们那些不幸的兄弟姐妹一样，漫无目的地在镇子里徘徊。我不希望你再度成为一个毫无思想的僵尸，你说呢?', '', '去提瑞斯法林地找丧钟镇的暗影牧师萨维斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3902, '捡破烂', '嘿，说你呢！要是你想实现自己的价值，那就听好了！$B$B我们要求那些刚刚爬出坟墓的新兵转至丧钟镇，搜寻任何可以为我们所用的装备，这些装备极有可能装在成堆的箱子里。我们希望能立即招募到更多的新兵，因此，除非我们想让他们赤手空拳地上阵，否则我们就得搜寻一切可用之物！$B$B开始工作吧，你这堆可悲的骨头！对那些不努力工作的家伙，我可是不会给予回报的。', '在丧钟镇及临近地区搜寻6件破烂装备，把它们交给亡灵卫兵萨尔坦。', '干得好，$N，我就知道你很能干。拿着这个―从我收集的这堆东西里挑一件较好的装备吧。', '你有没有为我们搜寻到一些有用的装备?重新利用那些被弃置不用的装备并不是件可耻的事情。没人会给我们施舍的―我们被遗忘者必须要自给自足!', '', '去提瑞斯法林地找丧钟镇的亡灵卫兵萨尔坦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3904, '米莉的葡萄', '一伙迪菲亚盗贼趁我收割的时候闯进了北郡农场！我将这件事情报告给了北郡的卫兵，他们向我保证会尽快解决，但是……我担心我的那些葡萄！即使迪菲亚盗贼不去偷盗葡萄，恐怕那些卫兵在剿灭盗贼的过程中也会踩坏它们。$B$B你一定得帮助我！我把大部分的葡萄都装在箱子里了，但是我把它们留在了东南边的农场。$B$B把那些箱子给我拿回来吧！救救我的收成！', '收集8箱米莉的葡萄，把它们交给北郡修道院的米莉·奥斯沃斯。', '哦，谢谢你，$N!你保全了我的劳动成果!我希望你让那些迪菲亚盗贼吃了苦头，让他们明白在这儿闹事的下场。$B$B这些日子以来，我们的卫兵可能有些人手短缺，但是有你这样的英雄保护着我们可真是幸运!', '你拿回我的葡萄了吗，$N?', '', '去艾尔文森林找北郡山谷的米莉·奥斯沃斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3905, '葡萄出货单', '我的作物完好无损，请将这张葡萄出货单交给尼尔斯修士。他在北郡经营一家销售食品和饮料的商店，我敢说当他知道他可以得到一批新鲜葡萄时一定会很高兴的。$B$B你可以在修道院的钟塔上找到尼尔斯修士，他喜欢在那儿饮酒。', '将葡萄出货单交给北郡修道院的尼尔斯修士。', '让我看看……$B$B啊呀!米莉的葡萄保住了!当她告诉我盗匪洗劫了她的农场时，我差不多已经绝望了，但是我对圣光的信仰并未改变!$B$B有了你的帮助，我们就可以用葡萄酿造更多的酒了!愿圣光保佑你，$N，注意安全!', '你看起来精神很好嘛!来!坐下来喝杯酒吧!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3906, '不和谐的烈焰', '部落的长老感觉到元素中的一种扰动。黑铁矮人召唤出了一个肮脏的灵魂，这个灵魂将用冲天的大火完全毁灭这个世界。我们必须调查这种不和谐的火焰的来源。$B$B到黑石山脉去，穿过火焰裂口，进入采石场。你应该可以在那里找到火焰之王——征服者派隆。$B$B解决这个造成扰动的源泉，然后向我回报。', '到黑石山脉的采石场去干掉征服者派隆，然后向桑德哈特回报。', '这不可能……绝对不可能……派隆的毁灭只是个开始，在黑石山脉的深处隐藏着更加邪恶阴险的堕落源泉。', '元素仍然处于混乱之中，$N。', '', '去荒芜之地找卡加斯的桑德哈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3907, '不和谐的火焰', '我可以嗅出空气中的邪恶气息，$N。在黑石山脉的深处依然隐藏着另一个控制着这种邪恶气息的生物。$B$B风和大地都在哭喊着它的名字：伊森迪奥斯……但是有人……有什么东西……控制这这个生物，它只是一个傀儡。$B$B找到它，找到它背后的主使者藏匿的地方。当你收集到这些信息之后就立刻回来向我报告。', '进入黑石深渊并找到伊森迪奥斯。杀掉它，然后把你找到的信息汇报给桑德哈特。', '<桑德哈特抓起库尔尼亚石板。>$B$B拉格纳罗斯……在这里……$B$B部落的长老对黑石山脉散发的堕落气息感到恐惧是有道理的。一个上古诸神的统帅!它在我们的世界中出现了!我们必须重新评估自己在卡加斯的地位了。现在，我们必须决定是要留在这里继续作战，还是因为这个新的发现而怯懦地逃走。$B$B不要再贸然探索黑石山脉了，$N。一个比世界上任何事物都要邪恶的力量就居住在那个火焰燃烧的深渊中。', '整个大陆很快就会被烈焰吞噬，快一点行动，$N!', '', '去荒芜之地找卡加斯的桑德哈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3908, '无人知晓的秘密', '你看，我已经对自己为什么会在这里完全没有概念了。没有人知道——这对所有的人来说都是个秘密！我什么都记不起来了……$B$B不过……你带给我的东西却让我想起了什么……$B$B我的剑！我想起来了，原本我是要去将其加强的，但是我不知道我为什么要那么做。很抱歉我不能告诉你更多的信息，因为我确实什么都记不起来了！$B$B不管怎么样，我知道你应该把剑带到什么地方去——把它交给冬泉谷的多诺瓦·雪山。你可以在温泉旁边找到她，她会用温泉的泉水来给剑中注入力量。', '把林克的剑交给冬泉谷的多诺瓦·雪山。', '嗯，我确实可以加强这把剑。在我工作的同时，你可以告诉我为什么林克花了那么长的时间才把剑送到我这里来。他并不健忘啊……', '我的天啊，林克终于找人把剑送到我这里了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3909, '视灵药剂', '什么，你说什么？林克……失忆了？$B$B哦，我明白了……他失去了自己的记忆……$B$B好吧，这是他的剑。但是它并不完整。我知道有人可以把它变得完整，但是……和他说话也许会很困难。$B$B听着，我知道有人可以帮助你，现在我没法把一切都给你解释清楚，总之你一定要得到视灵药剂。我所知道的唯一一个可以帮你的人就是格雷甘·山酒了。他行踪不定，但是我知道他眼下正在菲拉斯一带活动。', '去菲拉斯找格雷甘·山酒。从他那里问到获取视灵药剂的方法，然后向冬泉谷的多诺瓦·雪山复命。', '我需要一个小瓶子来确认这是我们所需的药剂……太棒了……就是它!', '这么快就回来了?', '', '去找冬泉谷的多诺瓦·雪山。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3911, '最后的元素', '只有那些进入深渊的冒险者才能迎接这个挑战，$N。$B$B黑铁矮人已经掌握了制造强大的作战傀儡的方法。$B$B来自间谍的报告显示，那些矮人使用某种独特的能量源为他们所创造的傀儡提供无与伦比的杀戮能力。$B$B如果我们能得到这种元素精华的话，我们的憎恶怪就可以得到极大的加强！把那座城市翻个底朝天也在所不惜，找不到精华你就别回来！我们给予的报酬值得你去冒这个险。', '到黑石深渊去取得10份元素精华。你应该在那些作战傀儡和傀儡制造者身上找找，另外，薇薇安·拉格雷也提到了一些有关元素生物的话题……', '棒极了!我立刻就派信差把它们送到幽暗城去!$B$B这是我承诺会给你的报酬。拿着吧!', '<薇薇安.拉格雷搓揉着她的双手>$B$B成功了吗?', '', '去荒芜之地找卡加斯的暗法师薇薇安·拉格雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3913, '寻找墓碑', '如果你回到墓地，$N，你会在那里找到一块墓碑……那不是一块普通的墓碑，它非常显眼。秘密就隐藏在其中。$B$B推动墓碑，然后你就可以发现那些秘密……', '复活，然后寻找加里杨让你去找的那块墓碑。', '你用力推动墓碑，它往旁边挪动了一点，露出了一个小凹槽。$B$B把林克的剑放入这个凹槽之后，你发现凹槽的形状和剑的形状正好吻合……', '这一定是加里杨提到的那块墓碑。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3914, '林克的剑', '一阵强光闪过之后，你再次捡起了那把剑。它已经完全变成另一种样子了！', '把林克的强化之剑交给安戈洛尔环形山的林克。', '我的剑……它终于完成了!$B$B现在，如果我能记得我为什么需要它的话……$B$B给你，至少我记得要付报酬给你。', '哦!我记得你!你是……不，别说!让我想想!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3921, '维妮·布特巴克', '我想我可能已经把主动式负载平衡器给弄坏了。这可不太妙，因为我已经对安德麦的一些同伴谈及它了，而且他们对此非常感兴趣。我们必须想办法修好它！$B$B把这个坏掉的主动式负载平衡器交给维妮·布特巴克，她就在贫瘠之地和灰谷之间的部落前哨站里。她非常聪明而且好奇，如果你将主动式负载平衡器给她看的话，我敢打赌她会欣然帮你修理它。', '将损坏的主动式负载平衡器交给维妮·布特巴克。', '哦，这是什么?主动式负载平衡器?啥叫主动式负载平衡器??$B$B呃……这里面有复杂的齿轮传动结构运转时发出的声音。啊，天哪!我要修好它，看看它到底是干什么用的，好吗??', '我正忙着干活哪，$C。除非你有事找我，不然你最好该干什么干什么去……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3922, '高强度齿轮', '我想修好这个主动式负载平衡器，但是，我需要一些材料。我用光了17.5规格的高强度齿轮，而我需要很多这样的东西才能继续工作。$B$B要弄到这种齿轮的话，最近的地方是东面的淤泥沼泽。风险投资公司的家伙们通常会把齿轮放在他们的工具桶里。到淤泥沼泽去，检查一下你在那里找到的工具桶，当你搜集了足够的高强度齿轮后再回到我这里来。', '把15个高强度齿轮交给贫瘠之地的维妮·布特巴克。', '太好了，你搞到齿轮了!我马上就开始工作……', '你拿到高强度齿轮了吗，$N?我一直在盯着这个主动式负载平衡器，而且在急切地盼望着能开始动手修补它。', '', '去找贫瘠之地的维妮·布特巴克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3923, '雷里·格里斯高布', '好吧，我失败了。我在主动式负载平衡器上安装了更多的仪表来测量它的结构完整度，读出来的数据表明现在的完整度很低。我也许需要加些转盘或者一两根杠杆来继续尝试，但是……没准我把它会搞得更糟。$B$B你应该把主动式负载平衡器交给雷里·格里斯高布。他过去是为风险投资公司干活的——如果有人知道该怎么修理这玩意的话，那一定就是雷里了。$B$B你可以在奥格瑞玛荣誉谷中的诺格机械店找到他。', '把破碎的主动式负载平衡器交给奥格瑞玛的雷里·格里斯高布。', '这是什么?哦，一个主动式负载平衡器!你什么地方搞来的?你是不是去过贫瘠之地的风险投资公司了?\r\n\r\n你一定很勇敢，或者很愚蠢。', '小心你的头!最好不要影响我的工作!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3924, '主动式负载平衡器说明书', '我想我可以修复主动式负载平衡器，但首先我需要一本用户手册。当我在风险投资公司干活的时候，我有个名叫考博普拉格的对手……他会把主动式负载平衡器的秘密告诉那些他信任的同党。不过我不是他的亲信……$B$B考博普拉格应该在贫瘠之地东北部的石矿洞里。从他那里把手册拿过来，如果他把其中的一部分给了其它人的话，你也要把它们一起拿来。', '把主动式负载平衡器说明书交给奥格瑞玛的雷里·格里斯高布。', '你成功了!我马上就研习这本说明书的内容，然后找出修复主动式负载平衡器的方法!我和棘齿城的斯布特瓦夫谈过了─他感谢你的帮助，并想要对你进行奖励。$B$B我也想感谢你，如果我能修好它的话，我会通知你的……', '你拿到说明书了吗?', '', '去找奥格瑞玛的雷里·格里斯高布。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3961, '林克的冒险', '真难想象林克来这里居然是为了帮助我们除掉火焰使者……他看上去是那么普通的一个侏儒，但是我确实感觉到他和别的侏儒有些不同，他居然对我的实验或者小装置一点都不感兴趣！他一定拥有一颗真正的战士之心。$B$B把图腾交给他，看看这是否能够帮助唤起他的记忆。', '把亚奎门塔斯的银图腾交给马绍尔营地里的林克。', '科琳帮你什么忙了吗?', '你好，我们又见面了，$N!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3962, '结伴而行', '$N，我终于想起来了……我来这里是要和火焰使者作战的。我经历了一段漫长的旅途，原本最重要的目标就是它。$B$B但是我不再是英雄了……你才是。迄今为止你已经做了那么多——应该由你来完成这个任务，而不是我。$B$B去找到火焰使者并打败它吧。它守护着一个被称作金色火焰的神器，这个神器的力量比我所见过的任何东西都要强大，如果它落在邪恶势力的手中，那会是一件非常危险的事情。$B$B你应该找些同伴一起去完成这个任务——独自行动是很危险的。', '到马绍尔营地南边的火羽山去。$B$B找到火焰使者，并使用图腾除掉它的防护光环。在击败它之后从洞中取得金色火焰。', '谢谢你，$N。$B$B我会把金色火焰带回我的故乡，在那里它将被好好保护起来，永远不会再落入邪恶势力的手中。$B$B你为我做了那么多，希望你能收下这个。如果没有你的话，我至今还不知道自己是谁!', '火焰使者用金色火焰创造了一个保护光环，使它无法被击败。只要使用亚奎门塔斯的银图腾，你就可以消除这个光环。', '', '去安戈洛环形山找马绍尔营地的林克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3982, '出了什么事？', '我受萨尔的差遣来到这里，你真的认为这些小丑可以抓住我吗？我是主动送上门的，这样我才能从他们这里收集情报。$B$B<哥沙克压低了声音。>$B$B黑铁皇帝索瑞森绑架了铁炉堡的公主，她就被关押在这座城市里！我敢打赌，当老麦格尼听到这个消息时，他的心脏大概会停止跳动的。$B$B<哥沙克大笑了起来。>$B$B嘘～～！你听到了吗？卫队来了！准备战斗！', '保护哥沙克。', '真是千钧一发呀。他们已经察觉到你了……会有更多的家伙过来的。', '先保住你自己的命，傻瓜!', '挡住敌人的进攻', '去找黑石深渊的指挥官哥沙克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4001, '出了什么事？', '到当前为止，我与大厅房间中的矮人卡兰之间的交流都很有限。但是我已经努力使他相信我——更准确地说，我们——对他没有恶意。$B$B过去跟他谈谈吧，尽可能多地收集有关公主和绑架他的那些家伙的情报，然后将这些情报反馈给酋长。$B$B萨尔不想让公主受到伤害，而是准备了某个重要的计划，其中包括使公主安全地返回铁炉堡。卡兰已对此了如指掌……快去吧！', '与卡兰·巨锤谈一谈，收集关于绑架公主铁炉堡公主茉艾拉·铜须这一事件的情报。将情报反馈给奥格瑞玛城里的萨尔。$B$B哥沙克提到过卡兰被关在附近的某个牢房中。', '对部落而言，这是一个永远改变这个世界的外交格局的机会。仔细听着，$N。$B$B这次任务绝对不能失败。', '你到这里来干什么?', '从卡兰那里收集情报', '去找奥格瑞玛的萨尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4003, '拯救公主', '这次行动是针对黑铁矮人的，如果我们成功了，那么他们的整个王国都将遭到一次巨大的冲击。$B$B茉艾拉公主正处于索瑞森大帝的控制之下。要想救她的话，你就必须杀了索瑞森。千万小心，你的任务非常危险，因为公主可能会在索瑞森的控制下向你发起攻击。$B$B不要伤害她！', '杀掉达格兰·索瑞森大帝，然后将铁炉堡公主茉艾拉·铜须从他的邪恶诅咒中拯救出来。', '看看你都干了些什么!', '<茉艾拉公主惊恐地蜷缩成一团。>', '', '转至黑石深渊，去找王座附近的公主茉艾拉·铜须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4005, '亚奎门塔斯', '把所有你收集的东西和这本书都带到塔纳利斯去。在落帆海湾寻找一个石头法阵，最东边的半岛应该就是秘密所在……$B$B当你身处石阵之中的时候，诵读阿奎尔之书，你将召唤出一个可以将你所收集的东西转化为一支与火焰使者作战所必需的图腾。$B$B亚奎门塔斯被人唤醒当然不会高兴，但是你要记住，在它转换图腾的这段时间里，你一定要待在石阵里面。', '把阿奎尔之书、银爪和铁树之心带到塔纳利斯去。$B$B使用这本书召唤亚奎门塔斯。$B$B在图腾完成之后，把它交给马绍尔营地的科琳。', '你是说火焰使者……?$B$B是的，我知道在这个环形山中部烧焦的那片土地上有一个强大的元素生物。我们都尽量和它保持距离，从来都没人能击破环绕在它周围的光环。许多想要挑战它的人，都从那条岩石路上被推了下来。', '你回来了?嗯……让我看看那个东西，$N。', '', '去找安戈洛环形山的科琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4021, '人马无双！', '部落对你战胜科卡尔部族的功绩感到非常高兴，但是科卡尔部族却为此发了狂。有报告称科卡尔部族的一支从凄凉之地来到了贫瘠之地，准备进行报复。到当前为止，我得到的最新消息是：他们已经在从西面往这里进发了！$B$B去迎战科卡尔部族的入侵者吧，彻底结束他们对贫瘠之地的威胁！杀死那些该死的半人马，直到他们的首领——督军克罗姆扎出现在你面前，干掉他，把他的旗帜撕下一片作为证据。$B$B我们都指望你了，$N。', '将克罗姆扎军旗的碎片交给十字路口西边的雷戈萨·死门。', '你成功了!你打败了科卡尔部族!$B$B我会把这个消息告诉萨尔的，$N。$B$B你证明了自己的价值，部落为你而骄傲。', '你拿到旌旗了吗?', '', '去找贫瘠之地的雷戈萨·死门。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4022, '烈焰精华', '那些飞龙已经注意到你在灼热峡谷中的所作所为了。$B$B向我展示你的能力，$c。我要的是龙皮，你这个蠢货。', '向塞勒斯·萨雷芬图斯展示你从卡拉然·温布雷那里得到的黑龙皮。', '<塞勒斯查看了一下那块龙皮。>$B$B看来你还不是一文不值的。', '<塞勒斯的双眼变成了两颗燃烧的火球。>', '展示证据', '去燃烧平原的滑石找塞勒斯·萨雷芬图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4023, '烈焰精华', '你找到那些黑龙了？那就向我证明你的价值吧，$c。', '向塞勒斯·萨雷芬图斯证明你的价值。$B$B你感觉到塞勒斯似乎对你不屑一顾。', '<塞勒斯查看了一下那块龙皮。>$B$B看来你还不是一文不值的。', '<塞勒斯的双眼变成了两颗燃烧的火球。>', '', '去燃烧平原找在滑石的塞勒斯·萨雷芬图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4024, '烈焰精华', '我要为火焰之山中的炙热烈焰歌唱，我要让黑石山的熔岩瀑布贯穿我的身体。我所渴求的就是那种精华，那种炙焰的感觉。$B$B在黑石深渊住着一个纯火焰铸成的怪物：贝尔加，他是从拉格纳罗斯的火焰中诞生的。杀掉贝尔加，然后从他燃烧的身体中取出他心中的烈焰。$B$B使用黑龙皮就可以安全地萃取这种烈焰。$B$B大功告成后，你会获得奖励的。', '到黑石深渊去杀掉贝尔加。$B$B你只知道这个巨型怪物住在黑石深渊的最深处。记住你要使用特殊的黑龙皮从贝尔加的尸体上采集烈焰精华。$B$B将你采集到的烈焰精华交给塞勒斯·萨雷芬图斯。', '<塞勒斯从你的手中一把拿过烈焰精华。>$B$B就是它!$B$B拿着你的奖励，然后走开。马上从我眼前消失!', '你干掉那个怪物了吗?', '', '去燃烧平原找在滑石的塞勒斯·萨雷芬图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4041, '视灵药剂', '', '', '这么说来，你轻松搞定了那个米布隆，是吗?', '替我弄一支灵根草来，我就可以帮你制作视灵药剂。$B$B我知道所有关于草药和炼金术的事情……为什么?让我告诉你，那次我把准备拿来当午餐的乳酪变成了金子的故事……喂……你要去哪儿?', '', '去找菲拉斯的格雷甘·山酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4061, '机器的崛起', '在我们最初进攻灼热峡谷的时候就已经见识过了那些机器。在进行了更深入的调查之后，我们发现它们是从燃烧平原运送过来的——当然也可能是从黑石深渊里运出来的。这就是我们需要你帮忙的原因，$N。$B$B你的第一件任务是到燃烧平原去，从那里的石头傀儡身上收集一些元素碎片。一旦你收集到足够数量的碎片之后就回到我这里来，我会鉴定它们的来源。', '到燃烧平原去为塞朵拉·穆瓦丹尼收集10块断裂的元素碎片。$b$b塞朵拉曾经说过，那里的机械傀儡和元素生物是这种碎片的主要来源。', '<塞朵拉把碎片放在她的面前。>$B$B<塞朵拉用一只巨型放大镜检查着那些碎片。>$B$B很有趣。每块碎片上面都刻着……一串字母。', '不要轻视这个任务，$N!', '', '去荒芜之地找卡加斯的塞朵拉·穆瓦丹尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4062, '机器的崛起', 'G.L.A.$B$B那些碎片上刻着这样的文字。在这些大写字母下面有一个军衔标志。你在燃烧平原所摧毁的机器的等级是四，我相信这是个比较低的军衔。$B$B把这块碎片样品交给东边一处营地里的鲁特维尔·沃拉图斯吧，他是个着名的元素学者，应该能对我们的研究有所帮助。', '将元素碎片样本交给鲁特维尔·沃拉图斯。$B$B塞朵拉说鲁特维尔就在东边的一处营地里。', '<鲁特维尔的脸变得煞白。>$B$B我……我知道这些东西代表着什么……', '你有什么要给我的吗，$C?', '', '去找荒芜之地的鲁特维尔·沃拉图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4063, '机器的崛起', '不可能是阿格曼奇！因为阿格曼奇在十年前就被杀掉了。什么？我为什么那么肯定？因为我就是杀死他的人之一。$B$B他是个卑鄙的矮人，为了自己的邪恶计划而逼我为他工作。看来坏蛋总有办法逃脱正义的惩罚。$B$B如果这一切都是阿格曼奇干的，那他就必须死！你去帮我弄些他最近制造的傀儡人的样品来吧，如果有合适的样品，我们也许就可以阻止他了。那些东西在黑石深渊里守护着阿格曼奇。', '找到并杀掉傀儡统帅阿格曼奇，将他的徽记交给鲁特维尔。你还需要从守卫着阿格曼奇的狂怒傀儡和战斗傀儡身上收集10块完整的元素核心。', '这是什么?!这颗头颅不是由血肉构成的。这是黑铁矮人制造的另一种机器人，与阿格曼奇一模一样的机器人!看来即使你杀掉了阿格曼奇也无济于事，不久之后就会有另外一个同样的东西替换它的位置。', '是他吗?他还活着吗?', '', '去找荒芜之地的鲁特维尔·沃拉图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4081, '格杀勿论：黑铁矮人', '根据卡加斯探险队的指挥官高图斯大人的命令：$B$B黑石深渊中所有安格弗将军麾下的部队必须全部消灭。$B$B安格弗的下属都是杀人不眨眼的暴徒，正是他们杀害了卡加斯探险队109分队的成员。遇到这群穷凶极恶的歹徒的时候要特别小心。$B$B任何能消灭黑石深渊安格弗将军麾下部队的勇士都将得到奖励。', '到黑石深渊去消灭那些邪恶的侵略者！$B$B军官高图斯要你去杀死15个铁怒卫士、10个铁怒狱卒和5个铁怒步兵。完成任务之后回去向他复命。', '这次攻击将削弱安格弗的力量。现在去做你的事情吧，士兵。我有很路复用作要做，还要部署我们的部队，还有无数敌人要消灭!$B$B去看看通缉榜上有没有什么新的工作吧。', '你有什么事吗，$r?你难道看不出我有一大堆事要忙吗?', '', '去荒芜之地找卡加斯的军官高图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4082, '格杀勿论：高阶黑铁军官', '根据卡加斯探险队的指挥官高图斯大人的命令：$B$B侦查分队的首领雷克斯洛特带回了关于高阶黑铁军官行踪的情报。他们在戒备森严的城市中心地带训练部队，准备对付我们。到黑石深渊去消灭他们！$B$B完成这个任务将可获得丰厚的奖励。', '到黑石深渊去消灭那些邪恶的侵略者！$B$B高图斯军阀要你杀死10个铁怒医师,、10个铁怒士兵和10个铁怒军官。完成任务之后回去向他复命。', '铁怒矮人无疑已经被激怒了。当你让我第三次刮目相看之后再回来和我谈谈，接下来我们要商讨下一步的行动:刺杀安格弗将军。这个任务可非同小可，在我告诉你行动的具体步骤前，你一定要保证自己已经休息充分了。', '你回来了?你很有毅力，所以我当然要把任务交给你来完成，$N。', '', '去荒芜之地找卡加斯的军官高图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4083, '鬼魂之杯', '', '', '宝石悄无声息地落入杯子的底部……', '鬼灵之杯在空中飘浮着，缓慢地上升和下降……就好像一颗将死的心脏在跳动。', '', '去找奥特兰克山脉的鬼魂之杯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4084, '银爪铁心', '我不知道你说的那个人是谁，$N。$B$B但是请不要担心，如果你的朋友原本打算大老远地来找我的话，我应该可以想象到他需要什么。$B$B在安戈洛尔环形山的中心地带有一个极端邪恶的恶魔，它以一个名叫火焰使者的元素生物的形象出现……它被一层任何人都无法驱散的光环保护着……$B$B没有人可以驱散……除非有足够的力量。我可以教你如何获得这样的力量，$N。$B$B首先按我说的去做，从费伍德森林的生物身上收集11个银爪和1个铁树之心，然后回来找我。', '为费伍德森林的艾瑞丹·蓝风收集11只银爪和1颗铁树之心。', '非常好，$N。我可以看出你是真心想要帮助你的朋友。', '我可以告诉你更多关于击败火焰使者的资讯，但是首先，你必须收集到我要的那些东西。', '', '去费伍德森林找翡翠圣地的艾瑞丹·蓝风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4101, '净化费伍德', '植物给与费伍德森林以生命，然而即使是它们也遭受了腐化和堕落的痛苦。我知道净化它们的方法，但是我不会把这种方法告诉一个我不熟识或者不能信任的$r。向我证明你真的能帮助塞纳里奥议会！$B$B这里的北面有一个铁木山洞，那里的曲木元素已经无法挽救了。我要你帮我从它们身上取得树汁，这些树汁被称作血琥珀。有了它们，我就可以研究拯救其它生命的办法了。', '收集15颗血琥珀，把它们交给费伍德森林的阿拉珊蒂丝·银空。', '血琥珀将被用来研究一种可以对付费伍德森林中的堕落力量的方法，你已经证明了自己愿意为塞纳里奥议会做任何事情。\r\n\r\n也许通过杀掉那些元素生物来证明这一点显得有些奇怪，但我们最终的目标是拯救所有的生灵，到那时一切都会证明我们现在所走的道路是正确的。现在我们可以开始专注于如何救更多的生命了。\r\n\r\n$N.，是时候开始净化费伍德森林了。', '我知道费伍德森林正在被痛苦折磨，$N，因为我自己也在体尝这样的痛苦!但我必须保持自己坚定的意志……如果我所掌握的知识落入了错误的人的手里，那费伍德森林就将遭受一场空前的灾难。$B$B帮我从扭木元素身上抽取血琥珀，然后我就能相信你会帮助我和堕落进行斗争了。', '', '去找费伍德森林的阿拉珊蒂丝·银空。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4102, '净化费伍德', '植物给与费伍德森林以生命，然而即使是它们也遭受了腐化和堕落的痛苦。我知道净化它们的方法，但是我不会把这种方法告诉一个我不熟识或者不能信任的$r。向我证明你真的能帮助塞纳里奥议会！$B$B这里的北面有一个铁木山洞，那里的曲木元素已经无法挽救了。我要你帮我从它们身上取得树汁，这些树汁被称作血琥珀。有了它们，我就可以研究拯救其它生命的办法了。', '收集15颗血琥珀，把它们交给费伍德森林的梅贝丝·河风。', '血琥珀将被用来研究一种可以对付费伍德森林中的堕落力量的方法，你已经证明了自己愿意为塞纳里奥议会做任何事情。\r\n\r\n也许通过杀掉那些元素生物来证明这一点显得有些奇怪，但我们最终的目标是拯救所有的生灵，到那时一切都会证明我们现在所走的道路是正确的。现在我们可以开始专注于如何救更多的生命了。\r\n\r\n$N.，是时候开始净化费伍德森林了。', '我知道费伍德森林正在被痛苦折磨，$N，因为我自己也在体尝这样的痛苦!但我必须保持自己坚定的意志……如果我所掌握的知识落入了错误的人的手里，那费伍德森林就将遭受一场空前的灾难。$B$B帮我从扭木元素身上抽取血琥珀，然后我就能相信你会帮助我和堕落进行斗争了。', '', '去找费伍德森林的梅贝丝·河风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4103, '狩猎换药膏', '', '', '干得好，这是给你的塞纳里奥植物药膏，回到费伍德森林中去，拯救这片堕落的土地吧!', '只要你拿着塞纳里奥信标，你就能从那些堕落的野兽身上找到受污染的灵魂裂片，为了费伍德森林的未来，你一定要拿到那些裂片。我会对裂片进行研磨加工，将其制成塞纳里奥植物药膏。我们可以用这种药膏拯救那些奄奄一息的堕落植物。$B$B如果你能给我弄些裂片来，我就可以给你几份植物药膏。', '', '去找费伍德森林的阿拉珊蒂丝·银空。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4104, '采矿换药膏', '', '', '干得好，这里是一些塞纳里奥植物药膏。如果你能在费伍德森林采矿过程中找到更多的硝酸盐的话，记得一定要把它们交给我!这东西越多，我就能造成越多的药膏来。', '如果你随身带着塞纳里奥信标，那么你在采矿的时候就会看到那些污染了矿脉的硫酸盐。我可以对那些硫酸盐进行净化，然后把它们制成塞纳里奥植物药膏。你可以用这种药膏来拯救堕落的大自然。$B$B给我弄些受污染的硫酸盐来，我就可以给你几份药膏。', '', '去找费伍德森林的阿拉珊蒂丝·银空。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4105, '采集换药膏', '', '', '干得好，$N―这种东西只要经过处理就可以帮助我们净化费伍德森林。拿着这些塞纳里奥植物药膏，然后回到森林中去吧。夺回费伍德森林的任务迫在眉睫，$N!', '训练有素的草药师可以用塞纳里奥信标探测到那些被污染的魔藤―这是费伍德森林被污染后所诞生的产物。我在这里进行了一些研究工作，现在我可以把魔藤转化为一种净化原料……然后就可以用它来制作我们所说的塞纳里奥植物药膏了。$B$B当你在费伍德森林里收集草药的时候，别忘了带着这个信标来寻找魔藤。给我弄些魔藤来，我就给你几份药膏作为交换。', '', '去找费伍德森林的阿拉珊蒂丝·银空。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4106, '剥皮换药膏', '', '', '这正是我所需要的。拿着这些药膏，把它们用于拯救费伍德森林吧。你一定要坚持到底，$N!', '训练有素的剥皮匠可以用塞纳里奥信标从费伍德森林里的生物身上找到受污染的毛皮，我可以把这些皮制作成塞纳里奥植物药膏。$B$B当你在这里采集兽皮的时候，记得带上信标。给我弄些受污染的毛皮来，我就可以给你几份药膏。', '', '去找费伍德森林的阿拉珊蒂丝·银空。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4107, '分解换药膏', '', '', '这里是一些塞纳里奥植物药膏―我只需要一份次级虚空精华就够了，$N。这种精华是我迄今为止碰到过的最具魔法潜能的东西，我可以用它们来拯救这片森林。如果你需要更多的药膏，那就到这里来找我吧!', '分解物品所得到的魔法精华中蕴藏着相当大的能量。我已经研究出一种方法，可以把炼金术所使用的原始精华材料转化为制作塞纳里奥植物药膏所需的材料。你不需要拿着塞纳里奥信标，只要是能够分解出次级虚空精华的物品都适用。$B$B我只需要一个次级虚空精华，作为交换，我可以给你一些塞纳里奥植物药膏。那些精华的能量很强大，所以即使很少的精华就能制作出不少的药膏了。', '', '去找费伍德森林的阿拉珊蒂丝·银空。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4108, '狩猎换药膏', '', '', '干得好，这是给你的塞纳里奥植物药膏，回到费伍德森林中去，拯救这片堕落的土地吧!', '只要你拿着塞纳里奥信标，你就能从那些堕落的野兽身上找到受污染的灵魂裂片，为了费伍德森林的未来，你一定要拿到那些裂片。我会对裂片进行研磨加工，将其制成塞纳里奥植物药膏。我们可以用这种药膏拯救那些奄奄一息的堕落植物。$B$B如果你能给我弄些裂片来，我就可以给你几份植物药膏。', '', '去找费伍德森林的梅贝丝·河风。', '', '', '', '');
