INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4117, '被腐化的鞭根草', '', '', '你将三份塞纳里奥植物药膏涂在了这株鞭根草上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的鞭根草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的鞭根草。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4118, '被腐化的轻歌花', '', '', '你将一些塞纳里奥植物药膏涂在了这株轻歌花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的轻歌花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4119, '被腐化的夜龙草', '', '', '你将四份塞纳里奥植物药膏涂在了这株夜龙草上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的夜龙草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的夜龙草。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4120, '堕落的力量', '作为猎人，我总是努力来模仿我对手的长处。知己知彼，百战不殆，$N$B$B在灰谷北部的费伍德森林中生活的野兽们都被恶魔的能量所感染，熊和狼都已经变得疯狂，而且我相信它们的力量也变得更加强大了。$B$B出发吧，$N。去费伍德森林面对那些野兽。如果你和我想象中的一样强大，就去那里锻炼自己吧。', '菲拉斯莫沙彻营地的塔罗·刺蹄要你去费伍德森林杀掉12头怒爪灰熊和12头魔爪掠夺者。', '从你的描述来看，那些生物都表现出一种歇斯底里的疯狂……$B$B保持警惕，$N。你最好注意更多关于堕落的事情。对你的敌人要多一些了解。', '每个感染恶魔能量的动物都会泛出绿光……我感到了极端邪恶而强大的力量。', '', '去菲拉斯找莫沙彻营地的塔罗·刺蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4121, '押送囚徒', '你真的以为可以把我押出去吗？你难道以为你能穿越戒备森严的黑石要塞，而且还能神不知鬼不觉地带走一个对他们来说如此重要的人吗？$B$B你死定了！', '押送你的囚犯格拉克·洛克鲁布。穿过燃烧平原和黑石山脉，一直走到灼热峡谷。$B$B雷克斯洛特曾经告诉过你，他会让他的人等在黑石山脉的另外一边准备接收格拉克。$B$B另外，你还要把瑟银镣铐一并还给雷克斯洛特。', '你的英雄事迹决不会被忽视，$N。你理应得到这些奖励。另外，上面还有最后一个任务要交给你。', '我会照顾这个叛徒的，$N。', '押送囚徒', '去荒芜之地找卡加斯的雷克斯洛特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4123, '山脉之心', '多年以来，我都在追寻一块特殊的宝石。它的名字是山脉之心，个头大概和你的拳头差不多！黑铁矮人把它锁在他们的一个房间里，虽然我想尽了办法，但他们就是不卖给我。$B$B所以我只好诉诸暴力了。$B$B到黑石深渊底部的宝库里去，击败那里的守卫，把山脉之心给我抢出来。你所要做的就是击败卫兵杜格瑞普，不过只有在你打开房间里所有的保险箱之后他才会出现！$B$B祝你好运。', '把山脉之心交给燃烧平原的麦克斯沃特·尤博格林。', '你拿到山脉之心了!太让我惊讶了!它比我想象中的还要漂亮!$B$B请你请收下这个作为报酬!', '你拿到山脉之心了吗?对我来说，它是无价之宝。', '', '去燃烧平原找烈焰峰的麦克斯沃特·尤博格林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4126, '霍尔雷·黑须', '在万恶的霍尔雷·黑须的带领下，那些黑铁矮人偷了我们的雷霆啤酒的配方，那些混蛋！他们不配得到如此美味的佳酿！$B$B$N，我有个艰巨的任务要交给你。去燃烧平原的黑石深渊，摧毁找到的所有装有雷霆啤酒的桶，然后把雷霆啤酒的配方带回来！$B$B求求你了，你一定要把配方带回来，即使要把黑石深渊翻个底朝天你也一定要找到它。', '把遗失的雷酒秘方带给卡拉诺斯的拉格纳·雷酒。', '你找到它了!干得好!我希望你好好教训了黑铁矮人和霍尔雷.黑须一下!$B$B雷酒系列随时愿意为你效劳，$N。你是英雄中的英雄!', '你找到配方了吗，$N?我绝不能忍受那些黑铁矮人居然能够饮用我系列的酒!', '', '转至丹莫罗，去找卡拉诺斯的拉格纳·雷酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4127, '船只的残骸', '你的手沿着泥浆滑过，手指碰到了一把刀柄。它看起来护理得不错，而且肯定是曾经乘坐过这艘船的人把它给弄丢了。这可能和失踪的信使有关。$B$B你抓住这把刀，想起羽月要塞的基恩诺·火花要你把任何能找到的线索都报告给他。然而，你有一种感觉，在水中并不是只有你一个人……', '回到羽月要塞，给基恩诺·火花看看你找到的这把被丢弃的小刀。', '很有趣……我相信这是拉斯卡尔的刀子。你说你是在水底找到的，他的船也沉了?好吧，仅凭这把刀并不足以把它与拉斯卡尔的失踪联系起来，然而，我们确实还有一个非传统的办法，也许可以让我们得到更多的资讯。$B$B你听说过心灵占卜术吗?', '啊，欢迎回来，$N。我希望你能发现一些关于拉斯卡尔的线索，尽管这可能是个悲剧。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4129, '奎恩提斯的技艺', '要塞里有一个名叫奎恩提斯的德鲁伊，他有一些……非同寻常的技艺，比如心灵占卜术——通过触摸某件物品揭示与其关联的历史。不要问我他是怎么做到的，我认为那是一种我不懂也不愿去弄懂的魔法。然而我确实知道两件事：首先，那把戏的效果确实不错；其次，他还欠着我的债。$B$B把小刀交给小树屋里的奎恩提斯，替我告诉他……如果他把他的本事用在那把刀子上的话，他跟我打牌时欠下的债务就一笔勾销。', '把被丢弃的小刀交给羽月要塞的奎恩提斯。', '谢谢你，$N。$B$B虽说心灵占卜术并不是多么精深的技艺，但我在过去的岁月中一直使用它来发现别人忽略的细节。我想，把它用到这把刀子上会让我们对拉斯卡尔的下落有更多的头绪。$B$B请稍等一会儿，虽然心灵占卜花不了多久，但是这种事情颇为费神。', '基恩诺派你来的?$B$B我的心灵占卜能力让我心力交瘁……我在牌桌上的损失也一样。要塞里的其它人都叫我“厄运之王”。没有牌运……但在掌握自然的秘密方面运气还不错，大概就是如此吧。$B$B好吧，我当然可以帮你。这可能是我们找到拉斯卡尔的关键所在。如果你愿意给我那把刀子，我们就可以开始了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4132, '行动：杀死安格弗将军', '迄今为止你一直表现得很好，$N。现在你应该去完成你的最后一个任务了。$B$B黑铁矮人中的安格弗将军负责策划了对K.E.F.109师的攻击，并残杀我们的无数士兵——正义必须得到伸张！$B$B这无疑是一个极端艰难的任务，但是成功之后，你也会获得丰厚的奖励。', '到黑石深渊去杀掉安格弗将军！当任务完成之后向军官高图斯复命。', '正义终于得到了伸张!你是个不平凡的$r，$N。戴上这枚勋章，这是你为部落和K.E.F.所做出的卓越贡献的象征。', '那个屠夫有没有被正法?', '', '去荒芜之地找卡加斯的军官高图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4134, '遗失的雷酒秘方', '有传言说黑铁矮人霍尔雷·黑须偷到了一种酒的配方。这种被称作雷霆啤酒的饮料会使饮用者获得无穷的力量和勇气。我们希望能研究一下这种饮料。也许我们可以开发它的其它功能……能够帮助我们被遗忘者达成目标的功能。$B$B我说了被遗忘者的目标？我的意思是……整个部落的目标，我当然是这个意思！$B$B到黑石深渊去找到雷霆啤酒的配方，把它给我带回来。', '把遗失的雷酒秘方交给卡加斯的薇薇安·拉格雷。', '非常好。我会把这个配方送到皇家药剂师协会进行研究，只要假以时日，我们必定可以找到其中的秘密。终有一天，那些联盟的矮人会发现我们用他们创造的饮料中的秘密来对付他们!$B$B那真的是太有趣了。这再次证明，死亡不会影响一个人的幽默感……你说呢?', '你找到雷酒配方了吗，$N?', '', '转至荒芜之地，去找卡加斯的暗法师薇薇安·拉格雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4136, '雷布里·斯库比格特', '我的兄弟雷布里就是我们系列的耻辱，他拿走了我们所有的钱，然后挥霍一空。$B$B藏宝海湾的大财主里维加兹刚刚开始悬赏雷布里的徽记，这对他来说可能有些糟糕，但我简直无法形容斯库比格特系列在得知这个消息之后有多高兴了！我们的小雷布里终于有点价值了！$B$B但是现在他躲在黑石深渊的深处。请你帮忙找到他，然后把他带到我这里来！$B$B如果他不愿意来的话，那么也好……至少把他的徽记给我带来。', '把雷布里的徽记交给燃烧平原的尤卡·斯库比格特。', '啊!你找到他了!看来……我的小兄弟不愿来见我。太可惜了。我真希望能当面告诉他我们准备把他交给里维加兹，然后看看他脸上的表情。$B$B谢谢你，$N。你让我的系列感到很高兴。雷布里从来没有像现在这样平静过。', '你抓到雷布里了吗?或者……至少把他身上的一部分交给我。', '', '去找燃烧平原的尤卡·斯库比格特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4141, '穆尔金和拉瑞安', '看见那里的拉瑞安了吗？就是他的错导致我们不得不待在这里！$B$B我告诉过他我们走错路了，但是他会听我的吗？你能相信他居然不和我说话吗？好吧，除非他改变主意，否则我们就准备看场好戏吧。$B$B你注意到周围那些像植物一样的生物了吗？它们确实很麻烦，但是我认为只要经过正确的训练，我就可以让它们听命于我。$B$B首先，我需要一些样品来进行研究。你可不可以帮我收集一些呢？', '收集15朵血瓣花，然后向穆尔金回复。', '我希望它们没有给你带来太多的麻烦，$N。我试图绕过它们―它们真是太疯狂了!$B$B我想要从它们身上跳过去……然后我就遭到了攻击!被植物攻击!', '拉里安在谋划一些东西，肯定是这样的!', '', '去找安戈洛环形山的穆尔金。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4142, '造访格雷甘', '我不能完全确定这是由什么构成的，$N。这些植物……好像具有一些最简单的智能。$B$B虽然我并不是这方面的专家。但是我知道有人一定知道答案！$B$B到菲拉斯去找我的一个名叫格雷甘·山酒的朋友，他是这方面的专家。$B$B我敢肯定格雷甘能帮我们，你应该可以在菲拉斯的野外找到他，他可不是那种喜欢生活在大城市里的家伙。', '把血瓣花交给菲拉斯的格雷甘·山酒。', '血瓣花?嗯……好吧，你最好向我解释整个计画，然后我才能够告诉你我是否能够帮助你。', '我在这片森林中与世无争地生活……$B$B好吧，至少我原认为是这样的。我在这里碰到的来访者比我在铁炉堡的时候还要多!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4143, '邪恶之雾', '我跟你说实话吧，$N，在我的旅途生涯中，我从来没有看见过这样的植物。也许我应该去一下环形山……$B$B不管怎么样，我想我知道穆尔金正在找什么东西——阿塔莱之雾。那是种恐怖的东西，而且非常难找，但是穆尔金需要这种材料来控制那些小怪兽。$B$B你应该去悲伤沼泽里的那座沉没的神庙，那里的潜伏者、黑暗虫和泥浆怪身上都有阿塔莱之雾。祝你好运，$N！', '收集5份阿塔莱之雾的样本，然后向安戈洛环形山的穆尔金复命。', '我承认，对于接触这些材料我有些犹豫，$N!但是如果格雷甘说它们会有效果的话，那我愿意试一下!', '拉里安还是不和我说话!看来他要对我沉默到底了。', '', '去找安戈洛环形山的穆尔金。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4144, '血瓣花苗', '', '', '就是这东西，$N!这些一定会引起拉里安的注意的!', '计画是这样的，$N:去收集一些血瓣花苗―你要知道，现在这种植物还没有开始广泛传播其种子，所以尽快把它们给我弄来，然后我就能看看阿塔莱之雾可以干些什么……$B$B你也许会认为我复仇心很重……事实上，所有人都应该有这样的权利!$B$B事实是这样的，我知道离开这里的路，但是除非拉里安承认我是对的，否则的话我就得永远待在这里!$B$B快点出发吧，找到那些血瓣花苗，然后就准备看好戏吧!', '', '去找安戈洛环形山的穆尔金。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4145, '拉瑞安和穆尔金', '看到那边的穆尔金了吗？就是他的错使我们迷路了！$B$B我知道正确的路，但是他坚持说他知道一条捷径，然后我们就到了这里！$B$B更糟的是，现在他还不断用他那些疯狂的植物来烦我。我很生气，所以我原本打算不和他说话了，但是这些该死的植物实在是太多，我没有足够的能力来清除它们。$B$B那么，首先让我们来减少这些东西的数量吧，去帮我干掉一些血瓣花鞭笞者和血瓣花捕兽者。', '为马绍尔营地里的拉瑞安杀掉5个血瓣花鞭笞者和5个血瓣花捕兽者。', '感谢你的帮助，$N，但是恐怕我这里有些坏消息……', '除非莫尔金向我道歉，否则我绝对不会再和他说话。', '', '去安戈洛环形山找马绍尔营地的拉瑞安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4146, '除草器的燃料', '你运气真不错，$N！在玛尔冯离开之后，我一直都在进行一些实验，其中的一项就是研究一种专杀除草器。只要进行一些调整，它就可以帮助你轻松地除掉那些血瓣花。$B$B我可以给你一部这种除草器的样品，但是你仍然得自行收集所需的燃料。你可以在沉没的神庙找到你要的阿塔莱之雾，那里的潜伏者、黑暗虫和泥浆怪身上都有这种东西。', '收集5份阿塔莱之雾的样本，然后将它们送到马绍尔营地的拉瑞安那里。', '那么说来，你没找到玛尔冯?好吧，不管怎么样，让我看看你拿来什么了。', '累死人了，$N。那些东西搞得我永不得安宁!', '', '去安戈洛环形山找马绍尔营地的拉瑞安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4148, '血瓣花除草器', '', '', '看起来这个血瓣花苗会很有作用，$N。现在记住，如果你在看到任何这种有害物出现的话，马上使用除草器!如果除草器不够用的话，你可以随时回到我这里来进行补充!', '要让除草器开工的话，我们就得有一份目标生物的样品。去环形山里找一个血瓣花苗来，然后我就设法用它启动莫尔金的小朋友……$B$B如果他不是那么固执的话，我们应该已经在回家的路上了……但是在我们能动身回家之前，我要向他证明他的那个小恶作剧并不能妨碍我!', '', '去找安戈洛环形山的拉瑞安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4161, '卡多雷的菜谱', '很久以前，暗夜精灵被称作卡多雷，卡多雷的意思是“众星之子”。了解这些历史对帮助你成为一名真正的$c非常重要，$N，所以好好聆听我告诉你的故事吧。$B$B卡多雷总是以自己和环境之间的和谐关系而感到自豪，这意味着我只向自然索取生活必需的东西，并且要给自然以友善的回报。这种平衡使我们受益良多，$N。$B$B去帮我收集几条小蜘蛛腿，然后回来找我。', '为多兰纳尔的扎瑞恩收集7条小蜘蛛腿。', '永远记住我今天说的话，$N。我们夜精灵努力维护自然的平衡，而你就是这种平衡中的一部分。', '记住这种平衡，$N。我希望你能拥有一颗对这片森林充满理解和宽容的心。', '', '去泰达希尔找多兰纳尔的扎瑞恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4181, '地精工程学', '高级的工程学有两个分支：侏儒派和地精派，请注意我提到地精工程学的唯一原因是因为我是个公正的训练师。他们喜欢制造一些会爆炸的东西，而且丝毫不关心有什么东西会被炸到——即使是他们自己。$B$B好吧，$N，读一下这本手册。如果你想要学习把自己炸上天的方法，就把这个交给加基森的尼克斯·斯普克斯宾。请记住，一旦你加入某一派，就永远也不能再加入另一派了，所以在你完成他交给你的任务之前要三思。', '如果你想要对地精工程学有更多了解，就把工程学教材交给加基森的尼克斯·斯普克斯宾。', '好吧，$N，你选择这条道路真是明智之极!随便什么蠢货都可以成为初级工程学的专家―那些地精跟他们那满是辐射的老窝就是铁一样的证据。要成为出色的哥布尔工程学专家，你必须有坚强的意志和稳固的双手―在这里我不得不强调稳固二字。$B$B竖起你的耳朵来好好听着，$N，你会学到许多东西的。', '我可以在一里外闻到新技师的气味，就像我可以在一里外闻到炸药的气味一样。你是来揭开炸药的神秘面纱的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4182, '黑龙的威胁', '燃烧平原上永远充满了争端。$B$B看看这个地方！我们不知道这些建筑到底是怎么回事，但是我们会永远记住，在大爆炸之前，这些地方原本都是属于赤脊山范围的。$B$B现在的情况真是太糟糕了！我们碰到了一个问题，$N。你也许已经注意到在这道山脊下徘徊的那些龙了。杀了它们，越多越好。去完成这个任务，然后我们再来谈谈别的。', '杀掉15条黑色小龙、10条黑色龙人、4条火鳞龙人和1条黑色幼龙。', '干得好，$N。现在我们知道你能轻松搞定那些龙，那么……来谈谈更棘手的事情吧。', '猎龙行动进行得怎么样了?', '', '去燃烧平原摩根的岗哨找赫林迪斯·河角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4183, '真正的主人', '我们以前总是认为黑石兽人的残忍是与生俱来的。不过我们在这里找到的东西却告诉我们另一个故事。$B$B没错，嗜血和对战斗的饥渴使他们变成了如今的样子，但是这一切的幕后主使却是那些黑龙。我们认为，正是黑龙把愤怒和敌意灌输给了他们。$B$B把这封信交给所罗门镇长，他会知道该做什么的。$b$b<赫林迪斯把一封信交给了你。>', '把赫林迪斯·河角的信交给赤脊山湖畔镇的所罗门镇长。', '<所罗门镇长打开赫林迪斯给他的信，然后读了起来。>', '幸会，$N。我们之前见过吗？你看起来好眼熟啊。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4184, '真正的主人', '这真是个可怕的消息，$N。我们的敌人竟然只是一个更强大的势力的爪牙，这让我感到更加气馁。湖畔镇不可能抵抗黑石兽人和黑龙的联手攻击。如果湖畔镇陷落了，那么下一个就是夜色镇，接下来会是哪里？闪金镇？暴风城？$B$B你必须把这个消息告诉瓦里安·乌瑞恩国王！如果暴风城不施以援手的话，那么一切就都完了。', '到暴风城去把所罗门的求援信交给瓦里安·乌瑞恩国王。$B$B瓦里安·乌瑞恩国王在暴风要塞里。', '龙?不可能!', '是什么风把你吹到暴风要塞里来了?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4185, '真正的主人', '所罗门描绘了一幅恐怖的画面，但是我们不可能把原本就已经捉襟见肘的兵力再分派一部分去湖畔镇。我需要确凿的证据才能采取行动。$B$B和女伯爵卡特拉娜·普瑞斯托谈谈吧，$N。她是个学识渊博的女性，并且对龙类生物很有了解。她应该可以在这件事情上帮助我们。', '与女伯爵卡特拉娜·普瑞斯托谈话，然后再与伯瓦尔·弗塔根公爵谈话。', '<伯瓦尔用手摸着下巴，好像陷入了沉思。>$B$B我尊重普瑞斯托女士的立场，我相信一定有办法可以解决我们面临的难题。', '<伯瓦尔专注地看着你。>', '女伯爵卡特拉娜·普瑞斯托的建议', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4186, '真正的主人', '我现在任命你为暴风城执行代表，$N。$B$B回到湖畔镇的所罗门镇长那里，向他传达这份命令。', '把乌瑞恩的命令交给湖畔镇的所罗门镇长。', '我觉得情况会更加糟糕……$B$B<所罗门镇长看着你。>$B$B看来湖畔镇的命运落在你的肩头上了。$B$B<你注意到所罗门镇长的眼睛湿润了。他开始哭泣。>', '有没有乌瑞恩国王传来的消息?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4201, '爱情药水', '啊，爱情的痛苦！我亲爱的罗克诺特下士对我的魅力不来电，他将我无情地拒绝了！这真是令我发狂！$B$B你必须帮帮我！我们魅魔对于爱情了如指掌，所以我可以配制一种药水，用它来融化包围着罗克诺特心脏的铁墙。不过我需要一些材料才能分配这种药水——一种被称作格罗姆之血的药草，一块从艾萨拉的悬崖巨人那里得到的巨大银矿，还有从安戈洛的温泉中取得的水。你可以把水放在这个小瓶里。$B$B$N，请帮助一个可怜的灵魂追求她的快乐吧！', '将4份格罗姆之血、10块巨型银矿和装满水的娜玛拉之瓶交给黑石深渊的娜玛拉小姐。', '啊，你成功了!现在我可以配制药水并把它用到罗克诺特身上去了。他终于要成为我的爱情魔咒的牺牲品了!$B$B谢谢你，$N。你真是个爱情的斗士!', '你拿到材料了吗?我心中的空虚正在吞噬我!', '', '去黑石深渊找黑铁酒吧的娜玛拉小姐。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4221, '被腐化的迎风花', '', '', '你将两份塞纳里奥植物药膏涂在了这株迎风花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的迎风花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4222, '被腐化的迎风花', '', '', '你将两份塞纳里奥植物药膏涂在了这株迎风花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的迎风花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4224, '真正的主人', '什么？你以为你是第一个被派来这里的？我们到底要损失多少士兵，暴风城才会下决心采取行动？$B$B对于黑石兽人可能造成的威胁，我们已经有了充足的证据，但是在指挥官温德索尔元帅被俘虏之后，我们损失了许多宝贵的情报。$B$B我们需要的是那份文件。去跟约翰谈谈吧，$N。他当时和温德索尔一起遇到了黑石氏族的袭击，现在他正在北边的一个洞穴里休息。', '和狼狈不堪的约翰。', '嗯?有什么好笑的?', '你和约翰谈过了吗?', '约翰的故事', '去燃烧平原摩根的岗哨找麦克斯韦尔元帅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4244, '找回A-Me 01', '你仔细看了看,发现有一块面板被打开了。在配线下面清楚地写着一行字，“更换秘银外壳，关闭电源之后再重新打开。”$B$B更换面板之后，你不禁觉得没理由这么容易就能修好A-Me 01，并让她回到马绍尔营地附近的卡尔纳·雷塔维身边。$B$B只有先试试看了。', '找到一个秘银外壳，然后回到安戈洛环形山的A-Me 01身边。', '你再次从艾米', '用来放置秘银外壳的面板仍处于关闭状态。艾米 01的其它部分没有任何动静。', '', '去找安戈洛环形山的A-Me 01。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4245, '找回A-Me 01', '在看了看周围的情况是否允许你把A-Me 01带回卡尔纳·雷塔维身边之后，你将开关扳到了“关闭”位置。你有看了看周围，确信没有某只猩猩朝你冲过来，然后将开关扳到“打开”。$B$B这是你最后的机会了……你确定要这样做吗？', '将A-Me 01交给安戈洛环形山的卡尔纳·雷塔维。', '哦，你成功了!太棒了!谢谢你，$N。$B$B啊，我可怜的艾米，看看这些牙印!我们只需稍作修理就能让她重新正常运转起来。$B$B再次感谢你，$N。', '你能帮助艾米吗?看来很可能是她的秘银外壳被损坏了，我相信如果你给她换一个秘银外壳，她就能恢复如初，而且可以自己回家。', '护送A-Me 01回到卡尔纳·雷塔维身边', '去安戈洛环形山找拉卡利油沼的卡尔纳·雷塔维。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4262, '征服者派隆', '前五个试图进入黑石深渊的法师几乎个个都灰头土脸地回来了，有的情况还要更糟糕。$B$B<加琳达从地上抓了一把灰尘洒向天空。>$B$B造成这种情况的主要原因是有一个可恶的臭虫——征服者派隆给我们带来了很多麻烦。我们必须干掉这个元素生物，然后才能顺利地进入黑石深渊！$B$B他就守在黑石采矿场的黑石深渊入口处。', '杀掉征服者派隆。$B$B加琳达告诉过你，派隆守在采矿场中，也许你应该去那里找找。', '伊森迪奥斯?我的天啊……', '<加琳达目不转睛地盯着你。>', '', '去燃烧平原摩根的岗哨找加琳达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4263, '伊森迪奥斯！', '你确定派隆临死之前喊出了“伊森迪奥斯”这个词？$B$B<加琳达使劲咽了口唾沫。>$B$B传说伊森迪奥斯是拉格纳罗斯的手下！哦，我的天啊，我的天啊……我们该怎么办啊？$B$B你认为你能再去完成一个任务吗？我现在手头没有足够的人手了，$N！$B$B如果伊森迪奥斯不断复活派隆的话，那我们的队伍永远也不要想进去了。$B$B你必须找到伊森迪奥斯，把他干掉！', '在黑石深渊里找到伊森迪奥斯，然后把他干掉！', '哦，我的天啊!你确定伊森迪奥斯临死之前说“拉格纳罗斯”?$B$B<加琳达递给你一件什么东西，然后拍了拍你的手腕，随即陷入了沉思。>', '那个恶魔死了吗?', '', '去燃烧平原摩根的岗哨找加琳达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4264, '弄皱的便笺', '这份便笺上满是污渍，上面的文字已经模糊不清了，但是还是能看出个大概来：$B$B……甜蜜的讽刺……$B$B……联盟的分崩离析……$B$B……如果不是因为安格弗将军的努力工作，也许我们至今还找不到译码的方法……$B$B……阿格曼奇已经差不多可以完成温德索尔便笺的破译了。$B$B我们的主人将从深渊中归来，摧毁所有剩馀的东西……$B$B- 达格兰·索瑞森大帝。', '温德索尔元帅也许会对你手中的东西感兴趣。毕竟，希望还没有被完全扼杀。', '<温德索尔元帅拿过信开始读起来。>', '<温德索尔元帅盯着你手中的信。>$B$B你手里拿着什么，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4265, '逃离虫巢', '当你触及虫茧时，虫茧裂开了一个小口，里面有一个暗夜精灵，他居然还活着。虽然他处于深度昏迷中，但看起来并没有缺胳膊少腿。当你把他从虫茧中弄出来时，他惊醒了过来。$B$B“感谢艾露恩——你救了我的命，朋友！我……我是拉斯卡尔。我被这些虫子麻痹，并被封在这只虫茧里。你能帮我逃离这儿，然后去羽月要塞报告一下我已经脱险的消息吗？我没事，但我们必须离开这儿，要快！”$B$B看起来你已经找到了失踪的信使！', '将拉斯卡尔安全护送到祖卡什虫巢外。$B$B回到羽月要塞的基恩诺·火花那儿，告诉他拉斯卡尔还活着，且状况良好。', '欢迎回家，$N。拉斯卡尔刚才回来了，他把你的英勇举动都告诉了我。$B$B我……不，整个要塞都感谢你。没有你及时的援助，拉斯卡尔就死定了。你的帮助对我们来说绝不是一点点酬劳就可以报答的。你是真正的英雄，你是基恩诺.燃炉永远的朋友。', '你有事要报告吗，$N?', '解救拉斯卡尔。', '去菲拉斯找羽月要塞的基恩诺·火花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4267, '异种蝎的崛起', '我信任你，所以把这份由拉斯卡尔撰写的关于菲拉斯东南部现状的报告交给你。现在这份报告的原本正在达纳苏斯归档，我要你做的是把这份副件交给最高女祭司的助手，她的名字叫格拉希娜·灵风，是一个住在达纳苏斯月神殿中的女祭司。她对于这些生物有着很深入的了解，把这份报告提交给她对我们大家都有好处。$B$B现在解散，祝你好运，$N。愿艾露恩保佑我们。', '把拉斯卡尔的报告交给达纳苏斯的格拉希娜·灵风。', '我们夜精灵很了解这份报告中所描绘的恐怖的场景。珊蒂斯派你把这份报告送到我这里来，这是个明智的决定。$B$B这些生物很快就吞噬菲拉斯，我们一定要消灭它们。你和其它信差看到的那些昆虫被称作异种蝎，它们是联盟和部落将要面对的共同威胁。$B$B我发誓要在异种蝎毁灭我们之前解决它们。', '欢迎来到月神殿，朋友。我已经事先知晓你会从羽月要塞来这里了。你有没有带来珊蒂斯.羽月所说的那份报告?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4281, '萨兰纳尔的货物', '你在木爪豺狼人营地里发现的这包货物应该是送往菲拉斯东南部的萨兰纳尔驿站的。不管那个失踪的信使命运如何，递送包裹的任务显然是没有完成。$B$B你仔细地检查包裹，发现在外包装上有手写的“法芬德尔”字样，也许这就是包裹接收人的名字。', '将未递送的包裹交给萨兰纳尔驿站的法芬德尔。', '赞美艾露恩，来自羽月要塞的包裹终于到了!$B$B是你送来了包裹，这么说我们的信差拉斯卡尔也许遇到麻烦了。我希望他能安然无恙……我知道，最近木爪豺狼人对它们南边的某种生物产生了强烈的敌对情绪，或许他是落到那些野兽手中了。我会小心的，朋友。$B$B无论如何，再次感谢你。这是递送包裹的报酬。', '欢迎来到萨兰纳尔，$C。你需要什么帮助吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4282, '一丝希望', '<温德索尔元帅激动地抖着手里的信。>$B$B你知道这意味着什么吗，$N？$B$B也许他们还没有得到所有的东西！我可以确定的是，现在有两个黑铁矮人——安格弗将军和傀儡统帅阿格曼奇——正在破解我的那些情报。我相信我们是不大可能很顺利地取回我的那封信的。$B$B希望你已经做好了战斗准备。$B$B去找到那两个恶棍！干掉他们，然后带回我遗失的情报。', '找回温德索尔元帅遗失的情报。$B$B温德索尔元帅确信那些情报在安格弗将军和傀儡统帅阿格曼奇的手里。', '<温德索尔元帅从你的手中一把抓过那两块石板。>$B$B我们要离开这里!', '不久之后，这个大阴谋就要彻底破灭了。', '', '去找黑石深渊的温德索尔元帅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4283, '五十个！', '我要告诉你个小秘密，士兵。走近一些。$B$B我是这里唯一正常的人！$B$B看看我周围的那些家伙！你相信他们都不正常吗？事实上他们都不正常！他们都疯了！疯了！$B$B<奥拉留斯放低了声音。>$B$B这是个秘密，不要告诉别人，只有你，我，还有我的那个军官伙计知道。$B$B<奥拉留斯紧握拳头。>$B$B不管怎么样……我在收集食人魔耳朵的同时也收集徽章，就是那些兽人身上的徽章。给我弄五十枚徽章来，现在就出发！$B$B<奥拉留斯双手拢在嘴边作喇叭状。>$B$B快去拿到那些徽章！', '收集50枚黑石徽章。', '你做到了!你所得到的奖励是:摸摸我的肚子!来啊!快摸摸它!', '<奥拉留斯对着一只又大又脏的巨魔耳朵喃喃自语。>$B$B我们要掌控燃烧平原，掌控它……', '', '去燃烧平原找摩根的岗哨的奥拉留斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4284, '能量水晶', '我确定你一定已经注意过它们了，$N。它们到处都是！$B$B我在说什么？这都不知道，我当然在说水晶！$B$B那些水晶……它们遍布在整个环形山里。大多数人都会忽视它们，但我感觉到那些水晶里一定蕴含着特殊的力量。我一直以来都在用它们进行实验，但似乎总是没有什么成果。好吧，我承认至今为止我一无所获。$B$B这么说吧，我这里的水晶已经不多了——我想你也许能够帮我收集一些水晶回来？', '收集红色能量水晶、蓝色能量水晶、黄色能量水晶和绿色能量水晶各7块，把它们交给马绍尔营地里的科琳。', '现在我可以继续我的实验了!谢谢你，$N。', '$N，我在等着你拿水晶回来呢!', '', '去找安戈洛环形山的科琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4285, '北部水晶塔', '那些到底是什么东西？我脑子里现在只有这个问题！$B$B它都快要把我逼疯了——我相信那些关于水晶塔的传言都是真的。随便你怎么说，但是我一般总是会相信别人告诉我的任何东西。$B$B不管怎么样，我听说有一座水晶塔就在北部很近的地方……请去找到它，$N。我敢肯定它们确实存在。', '在安戈洛尔环形山找到北部水晶塔。', '我就知道那些故事是真的，$N。', '你去过水晶塔了吗，$N?', '找到并查看北部水晶塔', '去找安戈洛环形山的科琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4286, '好东西', '温奇船长跟我说黑暗深渊里的黑铁矮人有很多好东西。对吧，温奇？$B$B<奥拉留斯努力扮演一名海盗。>$B$BB对！$B$B明白我所说的了吧？你到那里去，给我带回一些好东西来。$B$B到那儿去摇你的摇钱树吧！', '收集20个黑铁挎包。', '<奥拉留斯开始在一大堆黑铁挎包里翻东西。>$B$B啊，太棒了!$B$B<奥拉留斯把他的鼻子伸进这堆东西里，深吸了一口气。>$B$B神清气爽!看看这些好东西!$B$B你也拿一个吧，$N。随便拿。', '我现在很忙，$N。我和温奇正在开会。', '', '去燃烧平原找摩根的岗哨的奥拉留斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4287, '东部水晶塔', '这段时间我听说了一些关于神秘的水晶塔的奇怪传言，据说它们就在环形山中，$N。我猜它们的体积非常巨大，而且里面蕴含有珍贵的水晶。$B$B虽然我从来没有见过它们，但我却情不自禁地愿意去相信这些传言是真的——而且那些水晶塔有可能和我们找到的水晶有某种联系。$B$B请帮帮我，满足一下我的好奇心吧。也许在环形山的东部地区有一个水晶塔，你认为你可以找到它吗？', '在安戈洛尔环形山找到东部水晶塔。', '安戈洛是个奇怪的地方，$N。当你进入环形山的时候，你会发现自己好像进入了一个完全不同的世界……', '你去过水晶塔了吗，$N?', '找到并查看东部水晶塔', '去找安戈洛环形山的科琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4288, '西部水晶塔', '我的实验迄今为至没有取得任何实质性的进展，$N。我真希望你能帮我去查看一下传说中的一座水晶塔。$B$B也许我们在那里组合特定颜色的水晶的话……嗯，这我会自己去做的。首先我们得找到那些水晶塔！$B$B$N，去搜索一下环形山的西部区域；据说那里有个水晶塔。', '在安戈洛尔环形山找到西部水晶塔。', '环形山的边缘地带隐藏着很多秘密。如果你不知道该去哪里找的话，就到那些曲折的小道上查看一下，$N。', '你去过水晶塔了吗，$N?', '找到并查看西部水晶塔', '去找安戈洛环形山的科琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4289, '安戈洛的猩猩', '这个环形山中居住着许多奇怪的生物——它们似乎比我家乡那边的生物更加高贵。我无法解释这一点，但是这块地方在呼唤大地之母。每次我看到大地之母创造的某种美丽的生物时，我都会对她肃然起敬。$B$B如果你也希望感觉到见证这伟大功绩的幸福感，就向北方出发吧。你将在那儿遇到巨大的猩猩，这对$r的力量来说是一个挑战。把它们的皮毛交给我……证明你的力量。', '将2块安戈洛猩猩的皮、2块安戈洛大猩猩的皮和2块安戈洛巨猩猩的皮交给安戈洛环形山入口处的托尔瓦·寻路者。', '你证明了自己的力量足以对抗安戈洛的猩猩―这真是好极了。跟拉克维相比，这次挑战算是微不足道，但是我不会否定你所取得的胜利。$B$B这些皮毛可以为我的部族提供优质的衣料。你帮助了我，并证明了自己。$B$B在你接受下一个任务之前，让我们感谢大地之母以及那些死去的猩猩的灵魂吧―它们的死没有白费。', '你已经跟那些生物交过手了吗，$N?$B$B不要轻易认输。即使对一个熟练的猎手来说，追踪并击败安戈洛的猩猩也不是件简单的任务。', '', '去安戈洛环形山找沼泽地的托尔瓦·寻路者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4290, '拉克维的食物', '很久以前，我的一个兄弟从拉克维的猎物身上拿了一些肉。他那时并不知道拉克维就潜伏在丛林中看着他。拉克维跟踪了我的兄弟好几天，毁灭了他碰过的一切。我的兄弟吓坏了，最终他决定从安戈洛逃走，彻底甩开拉克维。$B$B拉克维就在这附近杀死了他。$B$B如果你想激怒拉克维，就去寻找它刚刚杀死的猎物，并从尸体上取一些肉。$B$B做完这些之后，就回到我这儿来。', '找到拉克维刚刚猎杀的动物的尸体，从尸体上偷取一块蛇颈龙肉块，然后回到安戈洛环形山的托尔瓦·寻路者那里。', '很好，$N。看起来拉克维这些天来吃得不错。不过令我感到奇怪的是，它是在哪里找到蛇颈龙的?这真奇怪。$B$B不管怎样，我们还是先把注意力集中在拉克维身上吧。不要担心我的安全―我相信你已经触怒了拉克维，它在品尝你的血肉之前是不会杀死我的。', '不要对我说的话心不在焉，$N。如果你真想面对这头野兽，那你就必须非常小心……而且非常聪明。要想引出拉克维并打败它，你必须拥有超群的力量和观察力。', '', '去安戈洛环形山找沼泽地的托尔瓦·寻路者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4291, '拉克维的气味', '它居然没有来攻击你，这让我感到很惊讶。但是不要紧，我有个计划可以让那头野兽出来。$B$B作为这块区域的领袖，拉克维有权与任何雌性暴掠龙交配——而且它确实这么做了。你可以在这里的西边找到许多暴掠龙蛋，靠近它们，这时就会有雌性暴掠龙跑出来攻击你。这些雌性暴掠龙头上有一种腺体，它所散发出的味道可以告诉雄性暴掠龙：它准备进行交配了。给我带两个这样的腺体回来。', '将2份暴掠龙信息素交给安戈洛尔环形山入口附近的托尔瓦·寻路者。', '啊，很不错，$N。你找到的这两个腺体中的资讯素可以轻松地把拉克维引出来。你很快就要与它正面较量了，拉克维拥有像刀刃一样锋利的爪子，当你看到它的眼睛时，你就会知道什么是死亡。', '小心，$N。靠近任何恐龙蛋的行动都必定会引来它们的母亲……即使你做好了准备也要万分小心。那些雌性暴掠龙和拉克维一样致命，它们会拼死保护自己的蛋。但是，如果你成功了，我们就一定有办法把拉克维从它的藏身之处引出来。', '', '去安戈洛环形山找沼泽地的托尔瓦·寻路者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4292, '拉克维的诱饵', '计划有些复杂，因此这是最困难的部分。沿着山脚向北面走，你可以发现一条很不起眼的小道直通山中。那是我最后一次看到拉克维的地方。那里应该散落着大型野兽的残骸，所以你很容易判断自己的位置是否正确。带上这块肉，把它放在那儿。然后在肉上涂抹我配制的这种液体。如果这还不能使拉克维现身的话，我想也没什么东西能把它引诱出来了。', '使用托尔瓦的麻袋中的东西召唤拉克维并打败它。将拉克维的徽记交给安戈洛环形山入口处的托尔瓦·寻路者。', '大地之母会很高兴的!你成功了!你在公平的较量中战胜了它，$N。你证明了自己是个合格的猎手，你拥有坚强的意志，无与伦比的勇气，以及强大的力量。我敬佩你精湛的技艺。$B$B并不是每个冒险者都能完成这样令人难以置信的壮举，恭喜你。', '不要让恐惧战胜你，$N。恐惧是最大的叛徒……你必须保持意志!$B$B带上这块肉，把它放在小山谷中，然后给肉上涂满资讯素。那时你就要面对死亡的挑战了。', '', '去安戈洛环形山找沼泽地的托尔瓦·寻路者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4293, '软泥怪的样本…', '费伍德是在贫瘠之地北边很远的地方的一片森林，比灰谷还要远。在那里的被恶魔污染的池水中到处都可以看到软\r\n泥怪，天灾军团的地狱火和其它恶魔法术曾经在这个地区肆虐过——软泥怪应该是在这段时间里从地底下冒出来的。$B$B从费伍德森林的软泥怪身上收集一些样本，然后我们就可以用我的测试仪器拿它们和其它样本作一下比较了。', '从费伍德的软泥怪身上收集费伍德软泥怪样本，然后使用幽暗城的化学家弗雷身旁的测试设备来检测你所收集的样本中哪一份被腐化的程度最深。给化学家弗雷带去5个被腐化的费伍德样本。', '啊，太好了，这些样本很合适。感谢你对我的帮助。$B$B当我收集到所有的泥浆怪样品之后，我们就可以搞清楚更多的东西。我觉得希尔瓦娜斯殿下的决定不仅正确，而且相当具有前瞻性。这些样品很有趣，看看它和我的这些材料之间发生的反应……嗯，没错，我们显然需要进行进一步的调查。', '我需要至少5份腐化的样本来进行试验，$N。继续去收集样品，希尔瓦娜斯女王已经下令要得到它了……', '', '去幽暗城找炼金房的化学家弗雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4294, '一大堆软泥怪', '$N，你听说过安戈洛环形山吗？它就在塔纳利斯沙漠附近，那里是个神奇的地方，到处都是郁郁葱葱的大树，还有大量的野生动物。 $B$B你必须到那里去一趟，我听说那块地方至今未至从未受到过外界的污染，探险者们正在逐渐揭开它的秘密。$B$B我想要对那里的软泥怪或者泥浆怪做一下测试，如果它们真的没有受到污染的话，那我真的想要看看这些生物是怎么进化的。', '从安戈洛尔环形山那里任何泥浆怪身上收集安戈洛泥浆怪样本。使用幽暗城的化学家弗雷身旁的测试仪器来检验你所采集到的样本的纯度。把5份纯净的安戈洛样本送到化学家弗雷那里去。', '太不可思议了，$N。安戈洛环形山中蕴藏的秘密比我预想得要多得多。我真想知道随着实验的不断进行，我们还会发现什么新的东西。$B$B太不可思议了……看看这些样品的纯度，嗯……我真想知道这意味着什么。它们看起来好像自然的元素，但是……还有别的东西。它们让我想起……上古诸神。我们在整个艾泽拉斯大陆上都能找到他们的踪迹，现在我想要知道这些生物是否和他们有关联。$B$B我们还要做进一步的研究才行。', '怎么样，$N?你的研究进展如何了?', '', '去幽暗城找炼金房的化学家弗雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4295, '罗克诺特的麦酒', '', '', '这是什么?啊!闻上去就像黑铁麦芽酒!麦芽酒让我的视线变得有些模糊，不过我可以肯定地告诉你，$g先生:女士;，你是一个真正的朋友!', '哦，麦芽酒!为了黑铁麦芽酒，我甚至愿意去杀人!快点，我的酒劲正在消退!我的视线越来越模糊了……你看起来越来越像上个星期我干掉的那个$r了!', '', '去找奥特兰克山脉的罗克诺特下士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4296, '七贤石板', '我追寻七贤的传说来到了燃烧平原，七贤是一群具有丰富知识和强大力量的矮人，你知道，一旦你有了这两样东西，那么财富必将接踵而来。我要的就是财富！$B$B如果我们能对七贤有更多了解，那我们就能一起发财了。据说索瑞森废墟里有一块七贤石板，上面刻有那些古代矮人所掌握的知识。找到那块石板，把上面的碑文拓下来给我，让我们共同揭开其中的秘密！', '取得石板拓文。', '啊，你找到石板了!你拓下来的碑文非常清晰!你真的是一个$C而不是拓文专家吗?$B$B拿着这些钱，$N。这是你应得的报酬。', '你找到七贤石板了吗，$N?你找到石板中隐藏的秘密了吗?', '', '去燃烧平原找烈焰峰的麦克斯沃特·尤博格林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4297, '小精龙的食物', '小精龙是杂食动物——它们既吃肉也吃植物。要是这颗蛋即将孵化的话，我们最好有所准备。信不信由你，这些小家伙最喜欢吃生的新鲜腰肉。我始终不明白为什么，但是这也许和艾露恩的旨意有关……或许它们将成为守护者或是别的什么，谁知道呢。$B$B我会照顾好这颗蛋，而你要负责找到一些银鬃捕猎者的肉，以便在小精龙孵化后喂食。', '将5块银鬃捕猎者的肉交给辛特兰的阿格纳。', '很好，要是我没猜错的话，它就要孵化了。感觉如何?你知道，你就要成为$g爸爸:妈妈;了。哈哈，你还没想到要承担这样的责任吧，对吗?', '找到肉了吗，$N?这颗蛋就快孵化了。要是第一餐不喂饱，没准它连一周都活不了，我可不愿意发生这样的事。$B$B我没骗你，$N。我很是羡慕你能得到这颗蛋呢。别让我后悔这样帮助你。', '', '去找辛特兰的阿格纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4300, '骨刃武器', '嗯，或许你能对碎手氏族有所帮助。没错，杰斯雷蒙肯定需要你的帮助。$B$B在安戈洛环形山生活着许多迅猛龙，它们的利爪是致命的武器。一些迅猛龙的爪子是白色的，还有一些是象征死亡的黑色。我们碎手氏族有些……顾客……他们需要由这些爪子制成的武器。给我带来一些白色的爪子，我会好好回报你的。如果你速度够快的话，也许我可以在其它方面帮助你。', '将8只白色暴掠龙爪交给奥格瑞玛的杰斯雷蒙。', '啊，很好。谢谢你，$N。你带来的爪子超过了他们所需的数量……很好。$B$B或许我们能为你制作这样一件武器。你觉得如何呢?', '我的顾客可没那么多的耐心，$N。你拿到爪子了吗?', '', '去找奥格瑞玛的杰斯雷蒙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4301, '强大的尤尔查', '在你探索安戈洛的时候，我看到了一些像你这样强大的猎手可能会感兴趣的东西。其中之一就是北方的一只巨大的猩猩，它混迹在其它的猩猩中间。你去过那座猩猩洞穴，但这次，我怀疑你是否能在遭遇那只大猩猩之后活下来。$B$B我称他为尤尔查，他是大地母亲最强大的儿子之一，关于这一点你不用怀疑。打败尤尔查，把他的毛皮交给我。如果你能做到这一点，我就会扞卫你称自己为伟大猎手的权利。', '把尤尔查的毛皮交给安戈洛环形山入口处的托尔瓦·寻路者。', '干得好，$N。我很高兴。你今天做了一件伟大的事。$B$B尤尔查是我所见过的最强大的猩猩之一。你战胜它的这一事实本身就证明了你的力量和勇气。$B$B请接受这件礼物以表示我对你的敬意。', '尤尔查……这头野兽非常健壮。巨大的身躯，赤红的外皮，像匕首一样巨大的牙齿。它的胳膊像树干一样粗，动作比我见过的任何猎豹都要快。你能找到这样一个测试你勇气的机会，应该觉得很幸运―我的同胞可能一辈子都看不到这样的生物。', '', '去安戈洛环形山找沼泽地的托尔瓦·寻路者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4322, '冲破牢笼！', '$N，我们要离开这里。帮助我从补给区拿回我的装备，然后再去救我的朋友。如果我们能够活着逃出去的话，那就在麦克斯韦尔元帅的营地里碰面吧。$B$B我们可以在那里想办法来破译这条情报。如果没有我的译码戒指的话，这个工作可就不简单了。$B$B你准备好了吗？', '帮助温德索尔元帅拿回他的装备并救出他的朋友。当你成功之后就回去向麦克斯韦尔元帅复命。', '有趣的消息……你找到了遗失的情报，对吗?$B$B那么……它在哪里呢?$B$B哦，我想你应该获得奖励。<麦克斯韦尔元帅双手拢在嘴边作喇叭状。>$B$B快点做好准备吧!', '$N，你看起来一副精疲力尽的样子。也许你应该在火堆旁找个位子好好休息一下。', '冲破牢笼！', '去燃烧平原摩根的岗哨找麦克斯韦尔元帅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4342, '卡兰的故事', '求求你，请先听我解释！', '听卡兰·巨锤说他的故事。', '就如你所见的那样，我什么都没有做。', '请允许我说完我的故事。', '卡兰的故事', '去找黑石深渊的卡兰·巨锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4343, '被腐化的迎风花', '', '', '你将两份塞纳里奥植物药膏涂在了这株迎风花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的迎风花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4381, '恢复水晶', '', '', '你仔细地排列着水晶阵列，调整着不同颜色水晶的位置。当你把最后一块水晶放上去之后，一阵强光将这些水晶熔为一体。$B$B你得到了一块新的水晶。', '你可以把绿色能量水晶和黄色能量水晶组合在一起。$B$B根据科琳给你的说明书上的记载，这种组合所制造的水晶可以治疗你和你的同伴。', '', '去找安戈洛环形山的北部水晶塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4382, '精神水晶', '', '', '你仔细地排列着水晶阵列，调整着不同颜色水晶的位置。当你把最后一块水晶放上去之后，一阵强光将这些水晶熔为一体。$B$B你得到了一块新的水晶。', '你可以把绿色能量水晶和蓝色能量水晶组合在一起。$B$B根据科琳给你的说明书上的记载，这种组合所制造的水晶可以提高你的精神属性。', '', '去找安戈洛环形山的东部水晶塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4383, '防御水晶', '', '', '你仔细地排列着水晶阵列，调整着不同颜色水晶的位置。当你把最后一块水晶放上去之后，一阵强光将这些水晶熔为一体。$B$B你得到了一块新的水晶。', '你可以把绿色能量水晶和红色能量水晶组合在一起。$B$B根据科琳给你的说明书上的记载，这种组合所制造的水晶可以提高你抵抗物理攻击的能力。', '', '去找希利苏斯的西部水晶塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4384, '破甲水晶', '', '', '你仔细地排列着水晶阵列，调整着不同颜色水晶的位置。当你把最后一块水晶放上去之后，一阵强光将这些水晶熔为一体。$B$B你得到了一块新的水晶。', '你可以把红色能量水晶和蓝色能量水晶组合在一起。$B$B根据科琳给你的说明书上的记载，这种组合所制造的水晶可以削弱敌人的防御能力。', '', '去找希利苏斯的西部水晶塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4385, '爆炸水晶', '', '', '你仔细地排列着水晶阵列，调整着不同颜色水晶的位置。当你把最后一块水晶放上去之后，一阵强光将这些水晶熔为一体。$B$B你得到了一块新的水晶。', '你可以把红色能量水晶和黄色能量水晶组合在一起。$B$B根据科琳给你的说明书上的记载，这种组合所制造的水晶可以猛烈地爆炸，对你的敌人造成伤害。', '', '去找安戈洛环形山的北部水晶塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4386, '尖刺水晶', '', '', '你仔细地排列着水晶阵列，调整着不同颜色水晶的位置。当你把最后一块水晶放上去之后，一阵强光将这些水晶熔为一体。$B$B你得到了一块新的水晶。', '你可以把蓝色能量水晶和黄色能量水晶组合在一起。$B$B根据科琳给你的说明书上的记载，这种组合所制造的水晶可以产生一道能对敌人造成伤害的屏障。', '', '去找安戈洛环形山的东部水晶塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4401, '被腐化的轻歌花', '', '', '你将一些塞纳里奥植物药膏涂在了这株轻歌花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的轻歌花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4402, '戈加尔的清凉果', '试炼谷这里真是热得要死。$B$B<戈加尔擦了擦他的额头。>$B$B如果我有仙人掌果的话，就可以做点清凉果来吃了！没什么能比清凉果更甘甜消暑的。$B$B我跟你说啊，$n，只要你给我弄6个仙人掌果来，我就帮你做一些清凉果。如果你感兴趣的话，就到这附近去找找仙人掌，采集它们的果子。', '收集6个仙人掌果，把它们交给戈加尔。你记得他说可以在仙人掌上收集到这种果子。', '太好了，$N!这是给你的清凉果，还有一些其它的东西。', '你收集到我要的仙人掌果了吗?', '', '去杜隆塔尔找试炼谷的戈加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4403, '被腐化的迎风花', '', '', '你将两份塞纳里奥植物药膏涂在了这株迎风花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的迎风花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4421, '碧火萨特', '很少有$r到这边来……费伍德森林的堕落已经遍布各个角落，而且仍在毫无节制地污染所有事物。$B$B作为翡翠议会的一员，我在努力治愈这片土地，但是仍然有些家伙希望它被腐化堕落。$B$B我所说的就是居住在西南方的克斯特拉斯废墟中的碧火萨特。他们的头目是一个名叫萨瓦瑟拉斯的萨特，这些邪恶的恶魔仍在继续将疾病散布给他们遇到的一切生物。$B$B我们必须保卫这片原本属于我们的土地。击败萨瓦瑟拉斯，消灭他的爪牙。', '杀掉11个碧火魔仆、9个碧火巡影者、9个碧火盗贼和萨瓦瑟拉斯。任务完成之后回到费伍德森林的艾瑞丹·蓝风处复命。', '除掉萨瓦瑟拉斯只是一个长期的斗争过程的第一步。修复这里遭受的破坏将会耗费大量的时间和精力。$B$B我感觉到这里有某种东西比目前的萨特更加强大，但我们只有等时间来揭示真相……', '这里的堕落气息已经让森林中的生灵都发疯了……', '', '去费伍德森林找翡翠圣地的艾瑞丹·蓝风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4441, '被禁锢的古树', '你所发现的长笛是由某个守护古树——忠心守护着暗夜精灵的树人——雕刻而成的。$B$B萨特能使他们接触到的任何东西受到腐蚀，其中也包括那些在费伍德森林安家的古树。他们的灵魂在恶魔能量的作用下受到束缚和折磨，永远无法解脱。你找到的碧火魔符就是禁锢古树的东西。$B$B我们必须净化长笛，$N。为我从达纳苏斯的月神殿取回一瓶祝福之水吧。', '到达纳苏斯去，用艾瑞丹的瓶子收集月神殿中的祝福之水，然后回到艾瑞丹那儿。', '谢谢你，$N。现在，让我们祈祷能抚平那些已经造成的创伤吧。', '这水可以释放古树的灵魂，并使其安息。', '', '去费伍德森林找翡翠圣地的艾瑞丹·蓝风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4443, '被腐化的鞭根草', '', '', '你将三份塞纳里奥植物药膏涂在了这株鞭根草上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的鞭根草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的鞭根草。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4444, '被腐化的鞭根草', '', '', '你将三份塞纳里奥植物药膏涂在了这株鞭根草上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的鞭根草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的鞭根草。', '', '', '', '');
