INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4448, '被腐化的夜龙草', '', '', '你将四份塞纳里奥植物药膏涂在了这株夜龙草上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的夜龙草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的夜龙草。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4449, '被锁起来的矮人', '嘿！嘿，你！过来！$B$B你要帮帮我。我正在逃避黑铁矮人的追击，我藏在这里，满以为他们就找不到我了。但那些可恶的混蛋还有魔法！他们肯定看到我藏了起来，他们很快就把门锁上，说了些什么过一阵子再回来之类的话，然后就离开了。$B$B你要给它们的颜色瞧瞧！给那些黑铁地质学家一个教训！哦……对了，你能不能给我弄几块丝绸来做……做……呃，没什么。', '杀掉8个黑铁地质学家，并将15块丝绸交给灼热峡谷里那个被锁在厕所中的矮人。', '哦，太好了!感觉很不错!$B$B什么?啊，当然……我是说那些地质学家。你给他们颜色了，对吗?我不知道该怎么谢你，$N。我可以有充足的时间在这里面……我的意思是，这让我不必担心他们会很快回来找我了。再次谢谢你。', '我可没有闲工夫在这里待着!给我弄些丝绸来!我是说那些黑铁地质学家，抓住那些地质学家!他们应该尝尝我的，嗯……你的愤怒。', '', '去找荒芜之地的木制厕所。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4450, '塔纳利斯的账本', '哦，你猜怎么着？我想起了一件事情。$B$B我现在仍然被困在这里，那么你可以帮我完成一项我在塔纳利斯接受的任务吗？很简单……嗯，对于你来说是这样的。$B$B加基森的克林科·古德斯迪尔需要一些从灼热峡谷和其它地方收集的东西。也许你可以看一下清单，然后把东西交给他……$B$B如果你感兴趣的话，我会把他的账本从门下递给你。把账本和他需要的那些东西交给他就行了。', '把古德斯迪尔的账本和上面所列的物品交给塔纳利斯的克林科·古德斯迪尔。', '哦，你看来很适合来帮我做事。很好。我还以为你是要我帮你锻造什么东西哪!$B$B这些东西太完美了……而且一应俱全。谢谢你，$C。$B$B我会奖励你一些东西的……嗯，你看看你想要什么吧。', '什么什么?我能为你做什么吗，$C?我非常忙，有很多人排队等着跟我做买卖。也许你可以长话短说让我不至于浪费太多时间，我并不是想要赶你走，我只是没有时间来完成我手头上的这一大堆工作。梦想太多，时间太少!', '', '去塔纳利斯找加基森的克林科·古德斯迪尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4451, '自由的钥匙', '这把小小的黄铜钥匙看起来可真简单……它唯一与众不同的地方是刻在钥匙头部的一句话：$B$B“黑铁厕所——请勿复制。”$B$B你完全不明白这是什么意思，也不明白这钥匙是干什么用的。', '搜寻灼热峡谷并找到一个可以插入这把格里塞特厕所钥匙的锁眼。', '啊，好吧!真丢人!不过你找到钥匙了!我就知道那些该死的黑铁矮人把我锁在这里以后就把钥匙藏起来了!多谢你，$N。你太伟大了$r!现在，转动钥匙，把我放出来吧!', '*咳咳*$B$B你是谁?没看见我很忙吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4461, '被腐化的鞭根草', '', '', '你将三份塞纳里奥植物药膏涂在了这株鞭根草上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的鞭根草。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的鞭根草。', '', '', '', '');
