INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4463, '沉思圣典', '', '', '拿着你的东西，愚蠢的$r。赶快从我面前消失!', '拿出原料来，渺小的$r。$B$B另外我还需要三十枚金币，这是我帮你制作东西的报酬。', '', '去燃烧平原找烈焰峰的玛瑟迪斯·火芒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4464, '被腐化的轻歌花', '', '', '你将一些塞纳里奥植物药膏涂在了这株轻歌花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的轻歌花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的轻歌花。', '', '', '', '');
