INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4466, '被腐化的迎风花', '', '', '你将两份塞纳里奥植物药膏涂在了这株迎风花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的迎风花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4467, '被腐化的迎风花', '', '', '你将两份塞纳里奥植物药膏涂在了这株迎风花上。它立即摆脱了刚才奄奄一息的状态，重新变成了一棵活力十足的健康植物。', '你找到了一株病怏怏的、被腐化了的迎风花。这株植物上面挂着的果实看起来已经腐烂，而且含有剧毒。你得想办法让它恢复到正常状态。', '', '去找费伍德森林的被腐化的迎风花。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4481, '体质圣典', '', '', '这对他简直就是侮辱……一个渺小的$r，比如说你，正在完成他一生都没能完成的工作。$B$B拿着你的东西，离开这里!', '这世上所有的东西都有价格，你所寻找的东西的价格是三十枚金币。$B$B当然，我会留下你收集的大部分材料。但是不用担心，你会得到你想要的东西。', '', '去燃烧平原找烈焰峰的玛瑟迪斯·火芒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4482, '坚韧圣典', '', '', '为了完成你现在所持的圣契，卡里尔花费的时间足够让你活上好几辈子，$r。这都是为了什么?为了让他的信徒可以站在燃烧平原上，贬低他的研究，以满足对魔法永无止境的追求和欲望……诅咒这该死的欲望$B$B我对你的无情和贪得无厌感到恶心，滚开!', '三十枚金币，$r，三十枚金币外加必需的材料。', '', '去燃烧平原找烈焰峰的玛瑟迪斯·火芒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4483, '恢复圣典', '', '', '其馀的圣契都遗失在这个世界上了，掉在你一辈子都不敢进入的地方，掉在你想都不敢想的地方。$B$B我要吸收这些材料的能量，剩下的残渣就是你的了……', '如果你想要的是韧性圣契，那得给我三十枚金币。', '', '去燃烧平原找烈焰峰的玛瑟迪斯·火芒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4484, '贪婪圣典', '', '', '我的头在轰鸣……构成我们宇宙的无尽能量……啊!$B$B<玛瑟迪斯显得非常痛苦。>$B$B拿着你的东西，走开!', '不要浪费我的时间，渺小的$r。我要的是三十枚金币，外加必需的材料。', '', '去燃烧平原找烈焰峰的玛瑟迪斯·火芒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4491, '朋友的帮助', '啊……太热了……$B$B我正在探索这片地域，突然之间，我就热得昏了过去，我一定是中暑了。$B$B求求你，带我回到马绍尔营地的朋友斯普拉格那里去，我想我还可以坚持到走回去……$B$B我感觉有些不对劲，如果我又晕倒了，就用斯普拉格的水壶里给我洒点水。我希望这能有点用……', '把林格带回马绍尔营地的斯普拉格·弗劳克身边。$B$B如果林格晕倒了，就用斯普拉格的水壶让他恢复。', '林格的情况并不好，$N，但我很高兴他能活着回来!$B$B谢谢你找到他。', '我好担心林格……', '把林格带回马绍尔营地的斯普拉格·弗劳克身边', '去安戈洛环形山找马绍尔营地的斯普拉格·弗劳克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4492, '走丢了！', '你必须帮帮我，$N！我的朋友林格前不久离开这里去探索南边的火山了，但他一直没回来。我很为他担心。$B$B你能帮我找找他吗？带着我的水壶，如果你找到了林格，没准他正需要它呢！', '在火羽山找到林格。', '哦……终于有人找到我了……', '什……什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4496, '擒虫先擒王', '我的研究表明异种蝎就像蜜蜂一样，消灭蜂房中的蜂后，其馀的就会乱作一团。我可以制造一种诱饵来让你引出异种蝎的皇后，并且打倒她。$B$B然而在那之前，我们需要一些材料，我可不想让你冒冒失失地进入丛林。到西边安戈洛环形山的异种蝎洞穴里去，从那里的某只虫子身上弄到它的信息素腺。另外我还需要一些安戈洛的土壤样本。', '把一份格里什信息素和5份安戈洛的泥土样本交给加基森的炼金师匹斯特苏格。', '啊，是臭腺。外膜看起来还完整无缺--太好了。还有土壤，是的，这应该可以发挥很好的效果。加上我特殊的添加剂，我应该能把这个研磨成完美的诱饵。$B$B给我一点时间来完成诱饵的制作，$N。一旦做好，我们就可以进行下一步的计画，希望可以在异种蝎蹂躏加基森……以及卡利姆多的其馀地区之前阻止他们。', '找到一个合适的臭腺可能会有一点难度--腺体不能损坏，但是取得腺体的过程似乎不容易得出这种结果。至于土壤，我认为很容易就能找到。$B$B不管怎样，你拿到我制造诱饵所需要的东西了吗?', '', '去塔纳利斯找加基森的炼金师匹斯特苏格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4501, '当心翼手龙', '悬赏：寻找技艺精湛的冒险者来对付安戈洛尔环形山中的翼手龙。它们的数量正在不断增加，已经威胁到了这个地区的旅行者。$B$B请杀掉10只狂怒的翼手龙来削减它们的数量。$B$B在完成任务之后，请向斯普拉格·弗劳克报告并换取奖励。', '杀掉10只狂怒的翼手龙，然后向马绍尔营地的斯普拉格·弗劳克报告。', '我对这里的翼手龙感到恐惧!感谢你减少了它们的数量，$N。我现在终于敢走出马绍尔营地进行冒险了。', '实话跟你说吧，我以前不是很担心那些奇怪生物的数量……直到有一天我看到写在一块大石头上的话:$B$B小心翼手龙$B$B这是谁写的呢?我不知道，但是忽视这句话显然是愚蠢的。', '', '去安戈洛环形山找马绍尔营地的斯普拉格·弗劳克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4502, '火山的活动', '作为玛尔冯·瑞文斯克的学徒，我从他那里学到了很多知识。但是他已离开很长时间了，因此我想自己去学习新的知识。$B$B近来我一直在阅读关于安戈洛环形山里面那些持续而奇怪的火山活动的资料。我想如果能从那儿的火元素身上弄到一些灰烬，就可以了解到很多东西了。$B$B如果你要往那儿去的话，能顺便帮我收集一些吗？', '到安戈洛环形山的火山中去，从那里的元素身上收集9份安戈洛灰烬，把它们交给棘齿城的莉芙·雷兹菲克斯。', '这些样本对我的研究而言简直堪称完美!谢谢你，$N!我承诺，我会把我的研究结果首先告诉你的。', '安戈洛环形山里的火山真的是活火山吗?我相信我可以从火山灰中了解到很多东西，$N。', '', '去找贫瘠之地的莉芙·雷兹菲克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4503, '希兹尔的飞行器', '我正在做一架飞行器！$B$B我被困在了这里，而且不敢轻易出去。如果我走出这里的话，肯定会迷路的，但是如果使用飞行器，我就可以轻松地回到加基森去。$B$B那么，你愿意帮助我吗？我现在只剩下机翼没有完成了，我想翼手龙和双帆龙的鳞片会是非常合适的材料。我自己是不可能去搞到这些鳞片的，但是你看上去好像有两把刷子。为什么你不帮我找找呢？', '为马绍尔营地的希兹尔收集8块精细的双帆龙鳞片和8块精细的翼手龙鳞片。', '太好了，这些鳞片非常合适。我想我一定可以用这些鳞片让我的机器飞起来!$B$B谢谢你!', '每个伟大的交通工具都需要有个名字……我想我会叫它……双翼飞行器!', '', '去安戈洛环形山找马绍尔营地的希兹尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4504, '极度粘稠的沥青', '我总是在寻找快速赚钱的方法，$N。如果你能帮我实现新计划，我可以让你也赚点钱，怎么样？$B$B就这么定了！$B$B到安戈洛尔环形山北部的油沼去，在那里帮我收集一些沥青。并不是所有的沥青都合适，你必须从油沼周围的野兽身上得到它。一般意义上的沥青根本不够黏，但是那些生物的皮肤中包含着叶绿素，和沥青混合在一起之后，它就变得非常具有粘性！', '帮加基森的特兰雷克收集12块极度粘稠的沥青。', '没错，我要的就是这些……$B$B嘿，等等，我的手……看来我没办法把我的双手分开了……$B$B也许这不是个好主意。哦，等等!我真是天才，超级粘合液清除剂!我可以用它来赚钱!', '特兰雷克又要大获成功了―超级粘合剂即将风靡市场!', '', '去塔纳利斯找加基森的特兰雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4505, '腐化之井', '有人可能会说我非常残忍……但事实上，我只不过是迫切地希望以任何可能的方法使部落能够压倒联盟。$B$B我最近对南边的克斯特拉斯废墟中的月亮井很感兴趣，这座月亮井是由碧火萨特守护的，它曾经是那些暗夜精灵新生的象征，但如今它已遭到腐化，被用于制造更多的萨特。$B$B我有个主意，$N，我需要一份井水的样品……给我们的那些“朋友”。', '从碧火萨特的月亮井中收集一份被腐化的水的样本，把它交给血毒哨所的温娜·哈萨德。', '很好。我们必须设法用这种腐化的力量来对付我们的敌人……', '这是至关重要的，赶快出发吧。', '', '去费伍德森林找血毒岗哨的温娜·哈萨德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4506, '被腐蚀的猫', '我们可以利用这些堕落的水，$N。只需少量这种水，我的小猫的体积就会变大，而且看上去会变得非常强壮……$B$B给你，$N。拿着这只猫笼，在克斯特拉斯废墟的月亮井旁边把猫放出来。呵呵……我相信你一定会对结果感到满意的！$B$B把猫给我带回来，我会让你觉得这点时间不是白白浪费掉的。', '把温娜的小猫带到堕落的月亮井旁边，把猫放出来，然后把它还给温娜。$B$B当你回到温娜那里之后，点击猫就可以将它还给温娜。', '太好了!$B$B被遗忘者会寻找一切可以击败联盟的方法!这些腐败的水会在我们将来的行动中很有用处……', '不要告诉我你搞不定这种小事!快去!', '将被腐蚀的猫交给温娜·哈萨德', '去费伍德森林找血毒岗哨的温娜·哈萨德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4507, '捕捉皇后', '拿着这份诱饵。在四通八达的虫巢中一定有一块水晶之类的东西，我想异种蝎就是使用它作为协调设备的。至于水晶在哪里……我建议你到虫巢中的孵化室找找看。$b$b在那里对水晶使用诱饵，这样就可以引出异种蝎的皇后了，但是你要小心——也许会有几个守卫保护着她。干掉皇后，然后拿出她的脑子。虽然这听上去有些恶心，但是我们必须对它进行研究。祝你好运，$N！', '召唤格里什皇后，然后击败她。$B$B把格里什皇后的大脑交给加基森的炼金师匹斯特苏格。', '太好了，$N!我们今天获得了重大的胜利。我们需要花些时间来研究这东西;但是我们一定会好好利用它的，你不用担心。$B$B至于那些异种蝎，我不知道它们是不是就只存在于现有的范围。看来要找到真相还有很多事要做，我不得不那么说。', '我们当务之急是要得到皇后的脑袋作为研究。根据我们所了解的情况，我们相信这些异种蝎可能被一种邪恶的智慧力量所控制。每当我想起能够控制像异种蝎这么邪恶的东西的力量，我都感到浑身发抖，$N。', '', '去塔纳利斯找加基森的炼金师匹斯特苏格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4508, '临危不惧', '我最近的研究结果表明情况相当糟糕，我们必须得通知某个能采取一些实质行动的人，因为我们不可能单独解决这件事情。$B$B把我的最新报告交给达纳苏斯的格拉希娜·灵风吧，她还在月神殿，不是吗？她的许多朋友都是联盟的要人，$N，如果我们能让他们涉及这件事情，那解决问题的希望就大增了。', '把匹斯特苏格的安戈洛报告交给达纳苏斯的格拉希娜·灵风。', '我很高兴你把这个消息带给我，但是我不确定这到底会给我们带来什么好处。联盟忽视了一切部落之外的威胁，即使是我们在达纳苏斯的领导者们也不会关心这个新的威胁。像范达尔.鹿盔这样的蠢才会认为异种蝎并不像我所说的那样可怕，他的无知只有他的自大可以与之相提并论!$B$B你已经亲眼目睹了这个威胁，$N。我们必须继续投入击败异种蝎的行动!', '他们都是笨蛋，$N!他们甚至没有想到在自己的周围潜藏着多么可怕的威胁，他们对部落的仇恨最终会导致我们的毁灭!我不知道除了把他们直接丢到其中一个蝎巢以外，还有什么关于异种蝎威胁的证据可以给他们?$B$B对不起，你有什么消息要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4509, '临危不惧', '我最近的研究结果表明情况相当糟糕，我们必须得通知某个能采取一些实质行动的人，因为我们不可能单独解决这件事情。$B$B把我的最新报告交给奥格瑞玛的基尔兹宾·鼓眼，他还在暗巷区里待着，不是吗？他的许多朋友都是部落的要人，$N，如果我们能让他们涉及这件事情，那解决问题的希望就大增了。', '把匹斯特苏格的安戈洛报告交给奥格瑞玛的基尔兹宾·鼓眼。', '我很高兴你把这个消息带给我，但是我不确定这到底会为我们带来什么好处。部落忽视了一切联盟之外的威胁，如果萨尔看到现在这种严重的事实的话，也许他会采取一些行动，但是他被各种杂务困扰着，根本看不到这些。那些笨蛋认为我们在担心着想象中的威胁，而他们所关心的才是我们真正面临的危机!$B$B你已经亲眼目睹这个威胁，$N。我们必须继续投入击败异种蝎的行动!', '他们都是笨蛋，$N!他们甚至没有想到在自己的周围潜藏着多么可怕的威胁，他们对联盟的仇恨最终会导致我们的毁灭!我不知道除了把他们直接丢到其中一个蝎巢以外，还有什么关于异种蝎威胁的证据可以给他们?$B$B对不起，你有什么消息要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4510, '临危不惧', '$N，你对我们的帮助是无价的。等到时机成熟时，我肯定会再次请求你帮助我们去对付异种蝎。我们必须清晰地解读我们在安戈洛得到的信息，恐怕我原本假设安戈洛是异种蝎发源地的想法是错误的……看来它们还有更大规模的聚居地。$B$B把这封信交给银行的伊迪瑞娜。她会让你从我的仓库中挑选一件东西。感谢你为我们提供的帮助，勇敢的$c。', '把银行赠券交给达纳苏斯银行的伊迪瑞娜。', '这张赠券授权我从格拉希娜.灵风的帐户中取出一件东西送给你。看来我要恭喜你了!', '艾露恩保佑你，$C。我能为你做些什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4511, '临危不惧', '$N，你对我们的帮助是无价的。等到时机成熟时，我肯定会再次请求你帮助我们去对付异种蝎。我们必须清晰地解读我们在安戈洛得到的信息，恐怕我原本假设安戈洛是异种蝎发源地的想法是错误的……看来它们还有更大规模的聚居地。$B$B把这封信交给银行的卡鲁斯。他会让你从我的仓库中挑选一件东西。感谢你为我们提供的帮助，勇敢的$c。', '把银行赠券交给奥格瑞玛银行的卡鲁斯。', '这张赠券授权我从基尔兹宾.鼓眼的帐户中取出一件东西送给你。看来我要恭喜你了!', '啧啧!我能为你做些什么吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4512, '远方的软泥怪', '我研究最多的生物是软泥怪。我知道这听上去很奇怪，但是那种东西已经到处都是了！$B$B不久之前，我帮助米奈希尔港的一位女士找到了她的包——那个包被软泥怪吞掉了。我也看见幽暗城皇家药剂师学会派出了他们的成员去收集软泥怪的样品。我要知道这是为什么！软泥怪究竟是从哪里来的？$B$B我听说在费伍德森林有许多软泥怪，我需要那些软泥怪的样品来进行研究。我会给你一些容器，这样你就可以帮我收集软泥怪了。', '将6瓶被诅咒的软泥怪样本和6瓶被污染的软泥怪样本交给铁炉堡的拉里斯·空轮。', '真是惊人的结果啊，$N!你取得了堕落软泥怪的样品，而且它们看起来毫发无伤!谢谢你。嗯，这些样品会非常合适。我等不及要对它们进行试验了。$B$B如果我成功的话，那我就能成为探险者协会中最伟大的科学家之一了!$B$B这足以向所有的矮人证明，在诺姆瑞根事件之后让我们地精迁入铁炉堡不是个错误。', '我已经完成的一些实验效果很不错。我相信只要再多加把劲，就能找出这些生物的特性，以及它们在艾泽拉斯的生物演化史中扮演了什么样的角色……如果它真的和艾泽拉斯的物种起源有关的话。$B$B我最重要的理论之一似乎并不是很受欢迎―我认为软泥怪和泥浆怪及这个星球上的生物是密切相关的……彷佛它们本身就是这个星球的分泌物。$B$B但是如果没有更多样品的话，我是无法证实或者推翻这一理论的。', '', '去铁炉堡找图书馆的拉里斯·空轮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4513, '远方的软泥怪', '我需要更多的样品，$N。但是——我不知道怎么搞到那些——嗯，纯净的样品，不过什么是纯净的样品呢？我也不知道。你拿来的这些都是已经被腐化的……就好像整个费伍德森林一样。这让我意识到一个重要的问题：看来软泥怪会适应周围的环境。我需要一些未经污染的样品以证实这一点。但是哪里有呢？哪里？！$B$B啊！$N，拿着这些容器，如果你找到未被污染的软泥怪，就把它交给我。', '将10个纯净样本瓶交给铁炉堡的拉里斯·空轮。$B$B如果你无法找到它们的话，不妨到拉里斯那里去再打听一些线索。', '你找到它了?$N，你真是块瑰宝。你的勤奋和乐于助人的精神让我感到非常钦佩。$B$B请你拿着这个当作报酬吧。现在我有些工作要做，但是我敢肯定，如果你以后再来的话，我还会再次需要你的帮助。$B$B谢谢你，非常的感谢你。', '我要考虑许多问题。它意味着什么?它是如何影响艾泽拉斯的种种生物的?', '', '去找丹莫罗的拉里斯·空轮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4521, '冬泉谷的枭兽', '冬泉谷就在费伍德森林的东北面，木候要塞的另一边。你去过那儿吗？$B$B我听说那片区域里到处都是一种被称作枭兽的生物，这些野兽以守护着暗夜精灵的秘密而知名。$B$B我们必须找出可能隐藏在冬泉谷里的东西。$B$B我听说你可在道路的南边找到蓬毛枭兽，而狂怒的枭兽则可在冬泉谷的中心地区找到。清除它们，控制那片土地。', '费伍德森林的特鲁尔·法贝恩要你去冬泉谷猎杀15头狂怒的枭兽和15头蓬毛枭兽。', '这是个很棒的消息，$N。扫除了这些野兽之后，我们就可以深入冬泉谷进行探险了。你准备好了没有?', '完成我给你的任务之后再回来向我报告。', '', '去费伍德森林找血毒岗哨的特鲁尔·法贝恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4542, '给乱风岗的紧急信件', '勇敢的旅行者，半人马已经加强了对这个地区的攻势。乱风岗必须马上得知这个新的麻烦！到东南方的乱风岗去，找到峭壁卫兵图林·长角，把这个十万火急的消息通知给他。$B$B多加小心，避开附近的恐怖图腾氏族……他们最近对我们有一些很奇怪的举动。', '把紧急信件交给乱风岗的峭壁卫兵图林·长角。', '还有更多的坏消息!这些半人马太过分了!他们袭击了我的一个补给车队，一个活口都没留下。这是赤裸裸的暴行，他们一定会受到惩罚的!', '你有什么事，$C?紧急通知?这是给我的?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4561, '杂质检测 - 安戈洛环形山', '', '', '你端起盛有淤泥样本的培养皿。要查看样本是否纯净的唯一方法就是打开培养皿，检查里面的物质成分。在理想状态下，你应该可以找到符合化学家弗雷要求的样本。', '你拿出一份从安戈洛环形山取来的淤泥样本，把它分开放进了桌上的试管和烧杯里。溶液开始沸腾并猛烈地喷溅，淤泥的颜色渐渐发生了改变。当反应渐缓，溶液不再喷溅时，你看见培养皿中有净化过的安戈洛淤泥样本和其它的一些残留物。', '', '去找测试仪器。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4581, '凯尼斯·静风', '德鲁伊凯尼斯·静风让人捎话过来说，他需要一份关于我们这边海岸和阿斯特兰纳附近森林的报告。他担心有一股堕落的力量正在靠近灰谷……也许他是正确的。$B$B给你，拿着我的报告。你可以在林歌神殿里找到他，就在东边的夜歌森林一带。', '把辛德瑞尔的便笺交给林歌神殿里的凯尼斯·静风。', '啊，辛德瑞尔的报告!非常感谢你，$N。辛德瑞尔是个不错的哨兵，她很勇敢，而且也很机敏。我必须要仔细阅读这封信，了解一下那股可能正在靠近灰谷的邪恶力量。', '你有什么要给我的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4601, '超级清洁器5200型！', '这个装置屹立于那些竭力保护房间的侏儒中，装置上有一块小金属牌，上面写着“超级清洁器5200型”，还有一段文字：$B$B：“污垢和残渣让你的东西看起来污秽不堪？超级清洁器5200型会使它重现光芒！将你想要清理的物品放入清洁器中，然后向槽里投入三枚银币。稍候片刻，你的珍宝就会重新变得洁净而耀眼！”', '将脏兮兮的东西放入超级清洁器5200型，记得要用三枚银币来启动机器。', '将你找到的脏兮兮的东西和三枚银币放入超级清洁器5200型里面后，机器仿佛重获生命一般，疯狂地清理着那东西表面上的污垢，并发出响亮而剧烈的搅动声。它的金属外壳吱吱作响，发出吱吱呀呀的声音……', '似乎这个装置需要某种脏兮兮的东西和三枚银币才能运行。既然两样都有了，超级清洁器5200型应该开始运转了……', '', '去找希尔斯布莱德丘陵的超级清洁器5200型。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4602, '超级清洁器5200型！', '这个装置屹立于那些竭力保护房间的侏儒中，装置上有一块小金属牌，上面写着“超级清洁器5200型”，还有一段文字：$B$B：“污垢和残渣让你的东西看起来污秽不堪？超级清洁器5200型会使它重现光芒！将你想要清理的物品放入清洁器中，然后向槽里投入三枚银币。稍候片刻，你的珍宝就会重新变得洁净而耀眼！”', '将脏兮兮的东西放入超级清洁器5200型，记得要用三枚银币来启动机器。', '将你找到的脏兮兮的东西和三枚银币放入超级清洁器5200型里面后，机器仿佛重获生命一般，疯狂地清理着那东西表面上的污垢，并发出响亮而剧烈的搅动声。它的金属外壳吱吱作响，发出吱吱呀呀的声音……', '似乎这个装置需要某种脏兮兮的东西和三枚银币才能运行。既然两样都有了，超级清洁器5200型应该开始运转了……', '', '去找银松森林的超级清洁器5200型。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4603, '再次使用超级清洁器', '', '', '超级清洁器5200型动了起来，它剧烈地晃动着。在机器里面，复盖在物品表面的污垢正在被清洁工具研成粉末!$B$B超级清洁器5200型停止了运转，熟悉的“叮”的声音过后，机器的盖子猛地打开了，里面摆着一只精心包装过的，扎着蝴蝶结的小盒子。', '超级清洁器5200型等待着清理脏兮兮的东西，它需要三枚银币才能启动!', '', '去找希尔斯布莱德丘陵的超级清洁器5200型。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4604, '再次使用超级清洁器', '', '', '超级清洁器5200型动了起来，它剧烈地晃动着。在机器里面，复盖在物品表面的污垢正在被清洁工具研成粉末!$B$B超级清洁器5200型停止了运转，熟悉的“叮”的声音过后，机器的盖子猛地打开了，里面摆着一只精心包装过的，扎着蝴蝶结的小盒子。', '超级清洁器5200型等待着清理脏兮兮的东西，它需要三枚银币才能启动!', '', '去找希尔斯布莱德丘陵的超级清洁器5200型。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4621, '敬礼，舰队司令！', '仔细听着，海狗……藏宝海湾是让我们血帆海盗处处受制的根本原因。如果你杀死舰队指挥官卡拉·海角，我们就永远不会再遇到藏宝海湾的战舰了。如果你杀死大财主里维加兹，我们就永远不用被他们的法律捆住手脚了。$B$B如果你想要成为一个有荣誉感的舰队司令——没错，舰队司令，那么就按照我说的，去杀了他们两个。现在去吧，$g小伙子:姑娘;，当你完成了任务之后就回到我这儿来。', '杀死藏宝海湾的舰队指挥官卡拉·海角和大财主里维加兹，然后回到荆棘谷海边的红雾号上去，向舰队指挥官菲尔拉伦复命。', '向你致敬，舰队司令$N!你是海贼中的海贼，$g小伙子:姑娘;!$B$B戴着这顶帽子吧。你在别的地方都不可能找到同样的帽子，所有看到你的人都会知道你就是血帆海军的舰队司令!', '我看到你回来了，$C!你完成我交给你的任务了吗?如果失败了，你就去走木板吧!', '', '去找荆棘谷的舰队指挥官菲尔拉伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4641, '起点', '你终于长大啦，$N……你可以以部落的名义参加战斗了，为酋长的荣誉而战吧！$B$B嗯……$B$B<卡尔图克打量了你一番。>$B$B你会很出色的。$B$B毫无疑问，你的目标是找到一条巨龙或是一个恶魔，然后赤手空拳地打败它，但是从比较弱的对手开始可能是个比较明智的选择。$B$B<卡尔图克笑了起来。>$B$B去向高内克报告吧，他可以为你这样的年轻$c指派一项适合你的任务。你可以在西边的大兽穴中找到高内克。', '与高内克谈一谈。卡尔图克在你的地图上标出了他的位置，并告诉你高内克居住在西边的大兽穴中。', '卡尔图克派来的又一个新兵，对吗?$B$B如果这就是部落可提供的最佳人选，那我们的处境可就不妙了。没关系，当我们认为你已经整装待发并可以离开峡谷的时候，你就将成为部落引以为傲的战士。', '对于一个强大的战士来说，再厚的蝎壳都不值一提。下手强劲利落，你就会发现那些壳很脆的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4642, '融合软泥怪', '这里有一些你从费伍德森林收集的软泥怪样本。把它拿到安戈洛环形山去，在那里找到一个纯净的软泥怪……最原始的品种就可以了。当你离它够近的时候，倒出容器里的软泥怪，让我们看看这两种软泥怪之间会发生什么事情。$B$B当这个试验完成之后，把剩下来的东西交给我。我会在炼金房这里等你。', '把一块融合的软泥怪样本交给幽暗城的化学家弗雷。', '哦，太好了，$N。这真是太好了。$B$B谁能想到这两样东西会进行这样的相互作用呢……我必须花更多的时间来研究这些生物产生变异的原因。$B$B我马上就开始继续我的研究。我们可能会很快再见面的，保重。', '试验怎么样了，$N?我会继续研究你给我带回来的样本―我开始明白为什么希尔瓦娜斯会对这些生物如此感兴趣了。如果它们真是上古诸神的一部分，那么也许我们可以好好利用这些东西。', '', '去幽暗城找炼金房的化学家弗雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4661, '堕落检测 - 费伍德森林', '', '', '你端起盛有淤泥样本的培养皿。要查看样本是否纯净的唯一方法就是打开培养皿，检查里面的物质成分。在理想状态下，你应该可以找到符合化学家弗雷要求的样本。', '你拿出一份从费伍德森林取来的淤泥样本，把它分开放进了桌上的试管和烧杯里。溶液开始沸腾并猛烈地喷溅，淤泥的颜色渐渐发生了改变。当反应渐缓，溶液不再喷溅时，你看见培养皿中有净化过的安戈洛淤泥样本和其它的一些残留物。', '', '去找测试仪器。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4681, '搁浅的巨兽', '黑海岸地区到处都是这种搁浅在海滩上的生物。它们大多出现在海岸线上，有一些甚至出现在海水中。我想让你调查另一只最近被发现的生物，据说它的尸体躺在奥伯丁西边的海水中，在一艘沉船附近。把你发现的任何有助于研究的信息都反馈给我。$B$B此外，在旅途中，你可能会发现其它搁浅的生物，你一定要把这些新发现也告诉我们！', '在奥伯丁西面海水中的海龟骸骨那里取回海龟残骸，然后与奥伯丁的温尼斯·布莱葛谈一谈。', '今天你为我们提供了很大的帮助，这些生物选择在黑海岸结束生命，现在我们终于有机会解开这一谜团了。他们可能是从泰达希尔附近逃来这里的，这可是件麻烦事。如果你在旅途中见到了其他此类的生物，就请告知我，我们在这里的研究才刚刚开始。$B$B我谨代表月神殿，请你收下它作为回报。谢谢你，$N!', '在你调查了西边那片水域中的生物残骸之后，我就应该能向达纳苏斯的月神殿提交一份较为准确的报告了。然后我们再来研究一下，为什么这些不幸的生物会选择在黑海岸结束它们的生命。', '', '去黑海岸找奥伯丁的温尼斯·布莱葛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4701, '座狼之源', '你一定见过黑石兽人控制的座狼。$B$B有趣的是，不管我们消灭多少座狼，它们的数量总是有增无减。我的探子报告说座狼是在黑石塔里面繁殖并驯养的，那里是黑石兽人的要塞。你必须去黑石塔找到座狼的源头。找到它……然后摧毁它。$B$B祝你好运，$n。愿塞纳留斯保佑你……', '到黑石塔去摧毁那里的座狼源头。当你离开的时候，赫林迪斯喊出了一个名字：哈雷肯。这个词就是兽人语中“座狼”的意思。', '不要一直为她的死感到难过，$N。那头野兽已经堕落了―她是黑暗魔法的产物。你为联盟做出了杰出的贡献，你应该得到奖励。', '你解决座狼的问题了吗?', '', '去燃烧平原摩根的岗哨找赫林迪斯·河角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4721, '冬泉谷的枭兽', '从冬泉谷回来的信使报告说，冬泉谷南部区域有许多洞穴，而且这些洞穴周围似乎都有枭兽出没。如果说它们是在守护某种重要的东西，那么我相信这就是我们要搜查的地区。$B$B这次的任务比上一个任务更富有挑战性，$N。如果这些生物拼尽全力守护的东西被发现的话，它们会变得非常疯狂而暴躁。', '费伍德森林的特鲁尔·法贝恩要你去冬泉谷猎杀10头狂暴枭兽。', '努力工作是我最敬佩的品质，$N。现在我们可以继续进行在冬泉谷的计画了。', '你知道自己该做什么，$N。', '', '去费伍德森林找血毒岗哨的特鲁尔·法贝恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4722, '搁浅的海龟', '你找到一具海龟的尸体，它显然是不久之前搁浅在黑海岸的，而且早已被住在周围的灰雾鱼人吃得一干二净了。不过，剩下的残骸也足够让你取样并送到奥伯丁的温尼斯·布莱葛那里去了。', '把海龟的残骸交给奥伯丁的温尼斯·布莱葛。', '又一个可供我们研究的新发现―干得好，$N!达纳苏斯那边会对这些残骸进行仔细的研究。请收下这个作为你的回报。', '你好，$N，你有没有发现什么被冲到海岸上的尸体?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4723, '搁浅的海洋生物', '一头巨型蛇颈龙的尸体——它比你预想的还要大很多——躺在薄雾海的海岸上。这个生物是怎么到这里的，你无从得知。成群的鱼人正在分食它的尸体，那些鱼人看上去是如此渺小，它们完全是依靠数量才将这头巨兽搞定的。$B$B虽然尸体已经被吃掉了大半，但是剩下的也足够让你取样并送到奥伯丁的温尼斯·布莱葛那里去了。', '把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。', '啊，我相信你发现的是以前被探险者协会检查过的那具尸体。他们来过这里，还提到了在研究一具尸体的时候被一群鱼人追击的事情。看来你成功地完成了我们都没能完成的事情。请你收下这个，月神殿感谢你。', '很高兴再次见到你，$N!是什么风把你吹回奥伯丁的?你来这里是不是有什么新的发现要报告给我们?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4724, '座狼的首领', '有些人说黑石兽人控制的座狼是由超自然的力量创造的。另一些人说其实它们并不是座狼，而是一种恶魔犬，是由一个堕落的深渊领主赐予兽人的。$B$B事实上，真相并没有这样夸张，但是同样很吓人。哈雷肯是一头巨型母座狼。她的配偶？没有人能活着回来描述他的样子。$B$B打击座狼的关键就在于杀掉哈雷肯……另外，$N，时刻小心你的背后。', '杀死血斧座狼的领袖，哈雷肯。', '疯狂的座狼?『奴役者』基兹卢尔?你居然能活着回来告诉我这个故事?!太难以置信了!你将赢得丰厚的奖赏!', '只要那头母狼被干掉，我们就可以削弱黑石塔中的座狼，然后设法进入那座要塞。', '', '去荒芜之地找卡加斯的神射手贾拉玛弗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4725, '搁浅的海龟', '还有更多的海龟尸体躺在海岸线上。这一具尸体的龟壳上还有个废弃的车架。也许这个生物是被某种未知的力量赶到了海岸上，而不是像别的尸体那样自己爬上海岸。强大的灰雾鱼人正聚集在尸体附近并蚕食着它。$B$B你在车架中找到了一只有着奇怪标志的箱子，也许奥伯丁的温尼斯·布莱葛会对它有所了解。', '把有奇怪标记的箱子交给奥伯丁的温尼斯·布莱葛。', '我听说过在海龟背上有车架这种事情。我相信这些都是纳迦的车架，他们用它来为作战服务，以及向陆地上运送物品。你找到的箱子上的标志也是纳迦的，这也许可以解释为什么最近在黑海岸北边会出现大量的纳迦。$B$B我准备把这只箱子和你发现的其它东西都送到达纳苏斯去。这个是给你的―再次感谢你的帮助。', '很高兴再见到你，$N。我们正在努力找寻巨型海洋动物纷纷在黑海岸搁浅的原因，但是似乎只要我们有一点进展，就会陷入更大的谜团中。$B$B你有什么可以对我们的研究有所帮助的新消息吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4726, '雏龙精华', '我几个星期来都在研究燃烧平原的龙类，而且我终于有所突破了！我制作了一个装置——我把它叫做“龙灵采集器900型”，它可以采集雏龙的精华！$B$B好吧，至少我认为它可以实现这个功能。$B$B给你，拿着这个装置，然后到燃烧平原上去采集雏龙精华。首先使用它标记雏龙，然后再杀死被标记的雏龙，这样你就可以采集雏龙精华了。$B$B如果一切正常的话，那就太棒了！把你采集的东西带回来供我进行研究！', '将龙灵采集器900型和8份雏龙精华交给燃烧平原烈焰峰的丁奇·斯迪波尔。', '它起作用了!你拿到精华了!干得好，$N!干得好!$B$B这些精华在我的研究中将起到至关重要的作用。我希望有一天能研究出捕捉活的幼龙或者拿到龙蛋的方法。如果我成功了，我就会成为全世界的龙类学术泰斗!$B$B我的雇主也会很高兴的，就如我以前所说的那样，你最好一直保持他处于高兴状态……', '你拿到小龙精华了吗，$N?我想要尽快开始研究它。$B$B除此之外……别让我的赞助人失望。', '', '去燃烧平原找烈焰峰的丁奇·斯迪波尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4727, '搁浅的海龟', '一只海龟的骸骨躺在黑海岸北部的沙滩上。也许灰雾鱼人没有发现它的尸体，或者由于某些特殊的原因而没有去碰它。不管怎么样，这具尸体上有足够的海龟肉，你可以采集一些作为样本，并把它送到奥伯丁的温尼斯·布莱葛那里，供月神殿进行研究。', '把海龟的残骸交给奥伯丁的温尼斯·布莱葛。', '又一个可供我们研究的新发现―干得好，$N!达纳苏斯那边会对这些残骸进行仔细的研究。请收下这个作为你的回报。', '你好，$N，你有没有发现什么被冲到海岸上的尸体?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4728, '搁浅的海洋生物', '某种海中巨兽的尸体搁浅在了海滩上，一只带着轮子的木桶和其它一些杂七杂八的工具散布在这头巨兽旁边，看来曾经有什么人想要研究它。虽然这具尸体被鱼人吃得差不多只剩骨头了，但是剩下的残骸也足够让你取样并送到奥伯丁的温尼斯·布莱葛那里去。', '把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。', '啊，我相信你发现的是以前被探险者协会检查过的那具尸体。他们来过这里，还提到了在研究一具尸体的时候被一群鱼人追击的事情。看来你成功地完成了我们都没能完成的事情。请你收下这个，月神殿感谢你。', '很高兴再次见到你，$N!是什么风把你吹回奥伯丁的?你来这里是不是有什么新的发现要报告给我们?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4729, '基布雷尔的特殊宠物', '你也许想要知道我在这里干什么。看看这些笼子！难道这还不够明显吗？$B$B我是个动物爱好者，但是首先我是个商人。我为一些富翁和名流寻找珍贵的动物，然后把它们驯化成为温顺的宠物。$B$B也许你现在想要问：“我能为你做什么呢，基布雷尔？”回答很简单：拿着这只笼子，帮我找些座狼小崽子。然后，我会为你驯服一头座狼！', '到黑石塔去找到血斧座狼幼崽。使用笼子来捕捉这些凶猛的小野兽，然后把笼中的座狼幼崽交给基布雷尔。', '你抓到它们的时机真是恰如其分，$N。如果再晚几天的话，它们就不可能被驯服了!给我一分钟，我就可以帮你把这只小座狼驯化好。', '基布雷尔正在和奥普斯激烈地争执着。>', '', '去燃烧平原找烈焰峰的基布雷尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4730, '搁浅的海洋生物', '这具已经被吃掉一半的尸体看来是一头海洋巨兽。尸体躺在海岸上，一群比奥伯丁那里的同类更加强大的鱼人聚在周围大嚼大咽，不过残留的尸体应该足够让你取样并送到奥伯丁的温尼斯·布莱葛那里去了。', '把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。', '啊，我相信你发现的是以前被探险者协会检查过的那具尸体。他们来过这里，还提到了在研究一具尸体的时候被一群鱼人追击的事情。看来你成功地完成了我们都没能完成的事情。请你收下这个，月神殿感谢你。', '很高兴再次见到你，$N!是什么风把你吹回奥伯丁的?你来这里是不是有什么新的发现要报告给我们?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4731, '搁浅的海龟', '又一具海龟的尸体躺在海岸线上，龟壳上还有个废弃的车架。也许这个生物是被某种未知的力量赶到了海岸上，而不是像别的尸体那样自己爬上海岸。强大的灰雾鱼人正聚集在尸体附近并蚕食着它。$B$B你在车架中找到了一只有着奇怪标志的箱子，也许奥伯丁的温尼斯·布莱葛会对它有所了解。', '把有奇怪标记的箱子交给奥伯丁的温尼斯·布莱葛。', '我听说过在海龟背上有车架这种事情。我相信这些都是纳迦的车架，他们用它来为作战服务，以及向陆地上运送物品。你找到的箱子上的标志也是纳迦的，这也许可以解释为什么最近在黑海岸北边会出现大量的纳迦。$B$B我准备把这只箱子和你发现的其它东西都送到达纳苏斯去。这个是给你的―再次感谢你的帮助。', '很高兴再见到你，$N。我们正在努力找寻巨型海洋动物纷纷在黑海岸搁浅的原因，但是似乎只要我们有一点进展，就会陷入更大的谜团中。$B$B你有什么可以对我们的研究有所帮助的新消息吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4732, '搁浅的海龟', '你找到一具海龟的尸体，它显然是不久之前搁浅在黑海岸的，而且早已被住在周围的灰雾鱼人吃得一干二净了。不过，剩下的残骸也足够让你取样并送到奥伯丁的温尼斯·布莱葛那里去了。', '把海龟的残骸交给奥伯丁的温尼斯·布莱葛。', '又一个可供我们研究的新发现―干得好，$N!达纳苏斯那边会对这些残骸进行仔细的研究。请收下这个作为你的回报。', '你好，$N，你有没有发现什么被冲到海岸上的尸体?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4733, '搁浅的海洋生物', '这具巨型蛇颈龙的尸体被冲到了礁石遍布的暮光海岸上。它比你见过的任何鱼龙都要庞大蛇颈龙都要庞大，不管它是从哪里来的，这头巨兽原本显然不是生活在黑海岸的。$B$B虽然这具尸体已经支离破碎了，但是残留的尸体也足够让你取样并送到奥伯丁的温尼斯·布莱葛那里去。', '把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。', '啊，我相信你发现的是以前被探险者协会检查过的那具尸体。他们来过这里，还提到了在研究一具尸体的时候被一群鱼人追击的事情。看来你成功地完成了我们都没能完成的事情。请你收下这个，月神殿感谢你。', '很高兴再次见到你，$N!是什么风把你吹回奥伯丁的?你来这里是不是有什么新的发现要报告给我们?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4734, '冷冻龙蛋', '$n，我一直都在忙着准备我的新装置，龙蛋冷冻器！这个装置可以对黑龙蛋喷出极冷的气流……然后就把蛋冻住了！你能不能帮我测试一下？$B$B我听说在黑石塔的高处，黑龙有个专门的地方来孵化它们的蛋。你可以在那里对它进行测试，然后告诉我效果如何！$B$B不要担心。被冻住的蛋是不会对你造成危害的。你所要担心的只是那些没有被冻住的而已！', '在黑石塔的孵化间对着某颗龙蛋使用龙蛋冷冻器初号机。', '成功了?太好了!我就知道它行的!$B$B在你离开的这段时间里，我制造了一个新的龙蛋冷冻器，它比以前那个版本的射程更远。$B$B拿着吧，如果你再去黑石塔的话会用得到它。', '$N，你测试过龙蛋冷冻器了吗?', '测试龙蛋冷冻器初号机', '去燃烧平原找烈焰峰的丁奇·斯迪波尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4735, '收集龙蛋', '$n，我终于做好采集真正龙蛋的准备了！给你，拿着这个电动采集模块，它可以萃取龙蛋精华并使你可以很方便地运输龙蛋。回到孵化间去，用这个东西来收集龙蛋。$B$B不要忘了把它们先冰冻起来，不然的话，在你开始收集之前龙蛋就会孵化！$B$B当你收集到足够的龙蛋之后，就把它们交给我！', '将电动采集模块和8颗收集到的龙蛋交给燃烧平原烈焰峰的丁奇·斯迪波尔。', '哇，你成功了!电动采集模组成功了!我真是个天才!$B$B谢谢你，$N。我的赞助人会很高兴能拿到这些蛋的……', '你拿到蛋了吗，$N?我的赞助人听说你在帮我收集龙蛋，他很想亲手摸到那些蛋!', '', '去燃烧平原找烈焰峰的丁奇·斯迪波尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4740, '通缉：莫克迪普！', '注意！$B$B杀死名为“莫克迪普”的鱼人就可获得一笔赏金。这只邪恶的野兽至少杀死了一名哨兵，还涉嫌使至少两条货船在黑海岸沉没！$B$B莫克迪普最后一次出现是在是奥伯丁以南的一个有草棚的鱼人营地中，据信它保护着那里的草棚。杀死该鱼人后请到奥伯丁的哨兵戈琳达·纳希恩处领取赏金。$B$B奥伯丁乡村委员会', '找到并杀死名为莫克迪普的鱼人。它守护着位于奥伯丁南部海岸的鱼人营地。$B$B向奥伯丁的哨兵戈琳达·纳希恩报告莫克迪普的死讯。', '嗯，干得好!奥伯丁的人们要是知道今晚终于可以睡个安稳觉的话，肯定会非常欣喜的。$B$B你是正义的伸张者，$N。为此请收下这个作为回报。', '你好，$C―今天哨兵部队能为你提供什么帮助吗?你是来询问\r\n 有关莫克迪普的赏金事宜的吗?', '', '去黑海岸找奥伯丁的哨兵戈琳达·纳希恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4741, '冬泉谷的枭兽', '冬泉谷北部区域的枭兽更加凶残，我们必须在那儿继续采取主动。$B$B猎杀冬泉谷中的月光枭兽，并探察他们居住的区域。$B$B那里是非常危险的地区，但是我知道你可以面对这样的挑战。当你杀死十三头枭兽之后就回到我这里来。', '费伍德森林的特鲁尔·法贝恩要你去冬泉谷猎杀13头月光枭兽。', '我感觉你是在享受任务。并且，我相信我们对此处的事物心中有数。', '别说你害怕了!继续前进!', '', '去费伍德森林找血毒岗哨的特鲁尔·法贝恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4742, '晋升印章', '正如你所见的一样，这个简单的印章有三个洞。每个洞都必须用代表领导力的宝石来填满。最终，下层要塞的领主维姆萨拉克会使用黑龙的火焰来铸造这个印章。$B$B你一定要明白，下层要塞的三个将军并不总是随身带着命令宝石，你必须在执行任务的时候务必保持谨慎。一定要完成这个任务！', '找到三块命令宝石：燃棘宝钻、尖石宝钻和血斧宝钻。把它们和原始晋升印章一起交给维埃兰。$B$B可能携带者三块宝石的将军是：燃棘氏族的指挥官沃恩、尖石氏族的欧莫克大王，以及血斧氏族的维姆萨拉克。', '<维埃兰的影像模糊了一下。>\r\n\r\n<你所收集的东西都消失了。>\r\n\r\n未铸造的晋升徽印已经准备就绪，该进行最后一步了。\r\n\r\n', '勇气和耐心就是一切，$C! ', '', '去找黑石塔的维埃兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4743, '晋升印章', '上层要塞之外的黑龙很少有能力用它们的烈焰铸造印章。维姆萨拉克是其中的一员，但是他的意志是不可动摇的。$B$B到尘泥沼泽中的巨龙沼泽去，在那里，你可以找到一条名叫埃博斯塔夫的上古老龙。你必须击溃他的意志，$N。把他击垮，然后在他虚弱的躯体上使用这颗宝珠。你有很短的一段时间来控制他的意志，然后用他所喷出的烈焰铸造印章。', '到尘泥沼泽中的巨龙沼泽去。找到上古老龙埃博斯塔夫，对他发起无情的攻击，直到他的意志被摧毁。$B$B此时，你必须尽快将未铸造的晋升印章放在这条龙面前，并使用龙力宝珠控制他的躯体，强迫他将黑龙的烈焰喷向未铸造的晋升印章！', '当心，我要施展最后的保护咒语了。$B$B<维埃兰的眼睛变成了两团火球。>$B$B晋升徽印铸造完成了……$B$B你要明白，我给这件神器中加入了一些强大的保护结界。在情况最危急的时候，当一切看来都已经无法挽回的时候，红龙军团的力量将会帮助你。', '不要浪费时间，凡人。奈法利安正在努力将他的邪恶散播到整个世界。', '', '去找黑石塔的维埃兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4762, '壁泉河', '壁泉河的河水正在逐渐变得污浊，这污浊的河水流入薄雾海，我担心奥伯丁也会很快受到影响。我怀疑居住在上游区域的黑木熊怪是造成污染的原因，但是我觉得它们并不是一切问题的真正源头。$B$B带上这支试管，到北面的河口去，在第一个内陆瀑布的水潭中取出一份河水的样本来——在你抬头就可以看到一座桥的那个地方取水就可以了。拿到样本后就回奥伯丁来找我。', '到奥伯丁的北面去，沿着壁泉河到达第一个瀑布处，从瀑布下的水潭中取出一份水样。$B$B将壁泉河水样交给奥伯丁的桑迪斯·织风。', '对于河水受污染的程度，我一点都不感到惊讶。看看吧，河水已经腐化，充满了恶臭!看起来我们要尽快采取措施了，对吧，$N?$B$B我们东面的费伍德森林是这种污染的真正来源，我敢说这份样本可以证明这一点。我们也许能制定一项净化河水的方案，但是我们必须寻求帮助才能执行这个方案。当时机成熟时，$N，我希望你能给我们提供帮助。', '壁泉河的污染为黑海岸拉响了警报。你提供的样本有助于我们制定计画……我猜想我们需要的是一项攻击计画。', '', '去黑海岸找奥伯丁的桑迪斯·织风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4763, '黑木熊怪的堕落', '我们已经知道熊怪的堕落与萨特有很大的关系，他们使用魔法护符控制熊怪。如果我们要尝试拯救熊怪的话，就必须击败引诱熊怪的萨特，取回他的护符！$B$B到我们的月亮井里去，在碗里盛满水，然后从北面的熊怪营帐中取回一些食物。把水和食物混合并放在河水边的营火旁，只要熊怪吃下食物，它就会得到净化，稍等片刻，那个引诱熊怪的萨特就会出现……这时你就要出手杀掉它！', '在空的净化碗里盛满奥伯丁月亮井的井水。$B$B在黑木熊怪的北部营地里收集水果、坚果和谷物各一份。$B$B将水和三种食物混合起来，放置在壁泉河附近的营火边，这样就会召来唤引诱熊怪堕落的萨特。$B$B取回堕落护符，将它交给奥伯丁的桑迪斯·织风。', '从堕落力量的魔掌中夺回森林的战争刚刚开始，但是今天我们已经取得了胜利!$N，奥伯丁的人民对你感激万分，你所提供的帮助是我们永远也无法回报的。请收下这个吧。今天我们所掌握的知识也许能在将来的某一天使我们的熊怪朋友们从痛苦中永久地解脱出来。', '堕落护符是一件邪恶的物品，它唯一的作用就是破坏自然的平衡。当你从萨特手中夺取这件让熊怪堕落的物品时，就把它交给我来处置，这样我们今天就可以说是有所斩获了!', '', '去黑海岸找奥伯丁的桑迪斯·织风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4764, '末日扣环', '黑石塔高处有一座大厅，它曾被称为财富大厅。黑铁矮人将他们的遗物、战利品以及艺术品存放在那里。$B$B那是很久以前的事儿了。据说大厅已经塌陷，现在用于……较为普通的用途。但是我相信里面可能仍藏有一些古代矮人的遗物。$B$B其中一件是末日扣环，那上面镶有罕见的宝石，据说任何矮人看到它都会感动得潸然泪下。$B$B那个扣环，$N，就是你的目标。', '将末日扣环交给燃烧平原的玛亚拉·布莱特文。', '你成功了!看来传言是真的!$B$B谢谢你，$N。我的主顾雷明顿.瑞治维尔伯爵看到这件东西将非常高兴。', '你找到扣环了吗，$N?我的主顾愿意出大价钱买它。', '', '去燃烧平原摩根的岗哨找玛亚拉·布莱特文。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4765, '瑞治维尔的箱子', '我已经把末日扣环放入一只箱子，便于运送到暴风城。$N，你帮了我的大忙，不过我能请你再帮我最后一个忙吗？$B$B把这只箱子交给雷明顿·瑞治维尔伯爵，你可以在暴风城里找到他。我敢说他看到这东西之后会非常高兴的。', '将瑞治维尔的箱子交给暴风城中暴风要塞的雷明顿·瑞治维尔。', '啊，果然是你!谢谢你，$N。呃……如果你还不知道的话……瑞治维尔系列中的一个贵族所能给予你的酬谢，足可以抵得上一个国王所能给予的。', '有人告诉我，一个来自黑石塔的信差给我带来了一件礼物。$B$B你就是那个信差吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4767, '驭风者', '我的任务是为我们的驭风者部队招募更多的双足飞龙。他们的数量在不断增加，我也希望自己有一天可以成为一名驭风者。但是，我们无法训练出足够的双足飞龙来满足需求。也许你可以帮助我，$N。$B$B我想让你到风巢去收集一些双足飞龙的蛋，从这里朝西北方向走，沿着峡谷的山壁到达一处直通风巢的斜坡。你要多加小心，双足飞龙对自己的蛋具有强烈的保护意识，它们对入侵者非常不友善。', '将10颗双足飞龙的蛋交给乱风岗的艾鲁。', '很好!有了这些蛋，我离成为飞龙骑士的目标就更近一步啦。这是我对你的一点谢意，愿你永享狩猎的乐趣，$C。', '$N，你弄到那些双足翼龙的蛋了吗?我简直等不及要进行飞龙骑士的训练了!', '', '去找千针石林的艾鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4768, '黑暗石板', '很久以前就已经去世了的矮人乌赫尔德·黑石将他的着作写在了一块黑暗石板上。虽然他是一个技艺高超的炼金师，但却被同时代的人当成精神病患者，他的研究成果也从未得到重视。$B$B不过他却把那些宝贵的知识刻在了石板上，而且我相信这块石板就在黑石塔中，在一个以前被称作幸运大厅的地方。我不知道现在那里叫什么，因为几乎没人可以进入黑石塔后再活着出来。$B$B不过，如果你愿意勇敢地挑战那里的危险并带回黑暗石板，我保证会给你丰厚的奖赏。', '将黑暗石板交给卡加斯的暗法师薇薇安·拉格雷。', '太棒了。刻在石板上的配方需要花费数天才能研究出来，但我相信这一次我们肯定会收获颇丰。$B$B谢谢你，$N。你对我们的价值真是无法估量。', '你找到石板了吗，$N?我想尽快对它进行研究。', '', '去荒芜之地找卡加斯的暗法师薇薇安·拉格雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4771, '黎明先锋', '我已经将黎明先锋放到你拿来的那个装龙蛋的容器里了。你的任务是把它带到通灵学院去。$B$B亡灵法师维克图斯在那儿向一群天灾军团的学者传授知识……把黎明先锋放在名叫观察室的房间里,它会自动攻击房间里面的亡灵，如果运气好的话，它就能一举毁掉他们！$B$B这样一来，杀死维克图斯就不是问题了。你明白了吗？', '将黎明先锋放在通灵学院的观察室里。打败维克图斯，然后回到贝蒂娜·比格辛克那里去。', '你成功了!维克图斯被打败了!黎明先锋……它有效吗?$B$B嗯……或许我的设备不是我期望的那样有效，但是很高兴你把一切都摆平了。干得好，$N!$B$B银色黎明和艾泽拉斯的人民都会感谢你的。', '你放好黎明先锋了吗?干掉维克图斯了吗?', '放置黎明先锋', '去东瘟疫之地找圣光之愿礼拜堂的贝蒂娜·比格辛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4781, '魔化金线血袍', '你的下一个任务和第一个任务同样简单，但是你必须去寻求他人的帮助。$B$B我的披风需要一些金线作为装饰，但是要获得金线并不容易，很少有人知道如何制作金线。幸运地是，有个忠于我们的地精知道金线的制作工艺，并且愿意帮助那些有前途的$c。$B$B把一块金锭交给藏宝海湾的希兹克·古斯提，他是个高明的裁缝，而且他会很乐意为你纺织金线的。金锭得由经验丰富的矿工熔炼出来，因此你必须寻求某个矿工的帮助。', '将一块金锭交给荆棘谷的希兹克·古斯提。', '棒极了，$N。很高兴你能如此迅速地找到愿意帮忙的矿工，要不然就是你自己动手熔炼金锭?不管怎么说，你做得很好。这块金锭用于纺织金线是再好不过了。$B$B我要花一些时间来干这活儿，所以你得过一阵子再回到我这儿来―事实上，我要让那些被囚禁在高塔中的公主们加班加点地干活了，她们唯一的工作就是纺织金线……不，我是认真的。我说真的……好吧，我开玩笑的。', '金锭，对，没错。给我拿一块金锭来，我就可以帮你纺织出金线。不过呢，我建议你的目标应该是努力使自己变得更强大。最艰难的考验还在前面呢。相信我……无论你认为自己的能力有多强，你都该追求更强。', '', '去荆棘谷找藏宝海湾的希兹克·古斯提。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4783, '魔化金线血袍', '下一件必需的材料只有在石爪山西面的凄凉之地才能找到。$B$B在大灾变之后，这片区域仍处于混乱之中。你的力量和智慧都将在此得到考验——你将面对满怀仇恨的生物，以及可怕的燃烧军团。$B$B到凄凉之地的东北部去寻找怨怒萨特，取回它们的血。然后从玛诺洛克集会所的次级地狱火身上弄到一块次级地狱火石。$B$B我们将在制作披风的过程中用到这两种东西。', '将10瓶怨怒萨特之血和1块次级地狱火石交给贫瘠之地的梅纳拉·沃伦德。', '棒极了，$N。一切进展顺利。在你继续寻找最后两件物品的时候，我将对这些东西做一下处理。准备好了吗?', '凄凉之地可不是个友善的地方。纳迦、巨人、萨特、燃烧军团、好战的半人马部落……所有这些都使得这片区域危机四伏，所以你得加倍小心。$B$B就像我先前所说的一样，这次任务不仅会考验你的力量和智慧，还会考验你的耐性。随时保持警惕，$N。', '', '去找贫瘠之地的梅纳拉·沃伦德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4784, '魔化金线血袍', '现在我只需要三件东西就可以完成你的披风了。$B$B第一件是希兹克正在纺织的优质金线，你要回一趟藏宝海湾，把金线拿回来。$B$B第二件是阿拉希高地的火元素身上的闷烧煤，这东西我要两块，如果我没记错的话，你可以在那个地区西部的索拉丁之墙附近找到它们。$B$B最后一件是由你自己制造的一块灵魂碎片。$B$B当你收集到所有的物品之后，就回到这座塔里来，我将为你完成披风。', '将一些优质金线、2块闷烧煤和一块灵魂碎片交给贫瘠之地的梅纳拉·沃伦德。', '棒极了，$N!所有材料都收集齐了，一切准备就绪。$B$B我相信你会很满意的。', '很快就好了，$N。我向你保证。我制作的披风绝对符合你的要求，它能使你在战斗中占尽上风。', '', '去找贫瘠之地的梅纳拉·沃伦德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4786, '完成金线血袍', '稍等一下，我现在就为你织好披风。这需要一些时间，可别走得太远了。', '等待梅纳拉·沃伦德织好披风，然后跟她谈一谈。', '好了，$N。自豪地穿上它吧。$B$B你干得不错，我看得出你会有远大的前途。记住，要对抗与我们的修行之道共存的堕落力量需要强大的意志和恒心。只要你坚持自己的信念，就能取得成功。', '再等一等，$N……', '等待梅纳拉·沃伦德完工', '去找贫瘠之地的梅纳拉·沃伦德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4787, '远古之卵', '摩沙鲁的预言提到了一枚远古之卵。当巨魔建造的强大帝国还无人能敌时，那枚卵就已经存在了，它具有控制哈卡的灵魂精华的力量。也许它就是能使我们的世界免受邪恶侵扰的唯一希望。$B$B把这枚远古之卵交给我，$N。据说它被深藏在辛特兰地区的巨魔城市辛萨罗，就在城市最顶端的大广场后面的洞穴中。', '将远古之卵交给塔纳利斯的叶基亚。', '啊，你找到它了!我向你的勇敢和力量致以最崇高的敬意，$N。', '你拿到远古之卵了吗?我感到一股强大的力量在蠢蠢欲动，我担心时间已经不多了。', '', '去塔纳利斯找热砂港的叶基亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4788, '最后的石板', '在我研究摩沙鲁的第三块和第四块石板的同时，你必须找到第五块和第六块！这并不容易，因为它们在黑石塔的燃棘巨魔手中。黑石塔位于燃烧平原和灼热峡谷之间，那是一座到处都是岩浆和火焰的黑色山脉。$B$B祝你好运，$N。黑石塔可不是个观光的去处……', '将第五块和第六块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。', '难以置信!你成功了!你真是个英雄，$N!$B$B这可是件好事，我一直在阅读先前你交给我的石板，据我所知……我们需要一个英雄来阻止即将发生的一切……', '你去过黑石塔了吗，$N?你找到第五块和第六块石板了吗?', '', '去塔纳里斯找热砂港的勘查员詹斯·铁靴。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4801, '霜刃魂精', '', '', '玛艾里可以把魂能提取出来，转移给$N……利用玛艾里的容器就可以把这中能量赋予你自己，或者你的盟友。', '在冬泉谷，你会与强大的霜刃豹战斗，这些猛兽拥有令人难以置信的速度和狡诈。如果你希望拥有霜刃豹的速度，就把你从它们身上找到的魂精交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。', '', '去找冬泉谷的巫医玛艾里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4802, '寒水魂精', '', '', '玛艾里可以把魂能提取出来，转移给$N……利用玛艾里的容器就可以把这中能量赋予你自己，或者你的盟友。', '在冬泉谷，你将与被称为冬泉熊怪的堕落生物搏斗，这些怪物拥有令人难以置信的力量。如果你想要获得冬泉熊怪的力量，就把你从它们身上找到的魂精交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。', '', '去找冬泉谷的巫医玛艾里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4803, '碎齿魂精', '', '', '玛艾里可以把魂能提取出来，转移给$N……利用玛艾里的容器就可以把这中能量赋予你自己，或者你的盟友。', '在冬泉谷，你会找到强壮无比的巨熊，这些裂齿熊有着很强的忍耐力。如果你想要获得抵抗火焰的能力，就把你从裂齿熊身上找到的魂精交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。', '', '去找冬泉谷的巫医玛艾里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4804, '冰风魂精', '', '', '玛艾里可以把魂能提取出来，转移给$N……利用玛艾里的容器就可以把这中能量赋予你自己，或者你的盟友。', '在冬泉谷，你会与巨大的冰风奇美拉进行战斗。这些动物有控制冰冻魔法的力量。如果你希望得到抵抗冰冷的能力，就把你从它们身上找到的魂精交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。', '', '去找冬泉谷的巫医玛艾里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4805, '冰草魂精', '', '', '玛艾里可以把魂能提取出来，转移给$N……利用玛艾里的容器就可以把这中能量赋予你自己，或者你的盟友。', '在冬泉谷，你会与巨大的冰蓟雪人战斗。他们的行动非常缓慢，但是厚厚的皮毛可以让他们获得超强的防御力。如果你希望拥有躲避攻击的能力，就把你从他们身上找到的魂精交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。', '', '去找冬泉谷的巫医玛艾里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4806, '霜槌魂精', '', '', '玛艾里可以把魂能提取出来，转移给$N……利用玛艾里的容器就可以把这中能量赋予你自己，或者你的盟友。', '在冬泉谷，你已经跟那些霜槌部族的冰巨人战斗过了，他们拥有巨大的力量。如果你希望拥有霜槌的力量，就从他们身上收集魂精，把它们交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。', '', '去找冬泉谷的巫医玛艾里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4807, '枭兽魂精', '', '', '玛艾里可以把魂能提取出来，转移给$N……利用玛艾里的容器就可以把这中能量赋予你自己，或者你的盟友。', '在冬泉谷，你将与拥有强大的魔法天赋的生物进行搏斗，那些枭兽可以使用强大的魔法。如果你想要提高自己的智力，就把你从枭兽那里得到的魂精交给我。$B$B记住，如果你想搜寻魂精的话，就必须随身带着玛艾里的容器。', '', '去找冬泉谷的巫医玛艾里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4808, '菲诺克', '我还有一件事要请你帮忙。$B$B我对你收集的那些精华进行了研究，结果表明冷冻并运输龙蛋是有可能实现的。我想测试一下这个理论，但是首先我需要一些特别设计的零件。我的同事菲诺克可以制作我需要的东西。$B$B现在，请你把这封信交给菲诺克，上面写着我所需要的东西的技术细节。你可以在冬泉谷的永望镇里找到菲诺克。', '把丁奇的信交给冬泉谷永望镇的菲诺克。', '那不是毯子!但那是什么呢?丁奇写给我的信?我想知道她要说什么……$B$B啊，她正在燃烧平原学习。我明白了-那里有一大票的龙。哦，你看!她说她需要一些零件来建造她的仪器。这就是她派你来找我的原因，对吗?', '这里真冷!你有毯子吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4809, '冰风奇美拉角', '我有丁奇所需的大部分材料，但是唯独缺少一种很重要的零件，那就是冰风奇美拉的角。冰风奇美拉的角是寒冷的源泉，但是只有非常纯粹而完整的角才能用！我需要很多角才能完成丁奇的订单。$B$B给我弄些完整的冰风奇美拉角来，我会为丁奇准备一个包裹。', '收集8支完整的冰风奇美拉角。', '嗯，品质很不错。你瞧，简直比冰还要冷!等我戴上手套，然后把它们与丁奇需要的其它东西一起包好……', '你拿到冰风奇美拉的角了吗，$N?', '', '去冬泉谷找永望镇的菲诺克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4810, '返回丁奇身边', '好，所有的东西都已经打包准备好，只等着送货了！祝你旅途愉快，$n，别忘了告诉丁奇说她欠我一份人情！', '把菲诺克的包裹交给燃烧平原烈焰峰的丁奇·斯迪波尔。', '太棒了!我马上就开始工作!真是太感谢你了，$N!$B$B你帮了我的大忙，我以后可能会需要你去完成更加重要的任务……', '$N!你找菲诺克谈过话了吗?我要的东西呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4811, '红色水晶', '我们东边的区域出现了越来越多的有攻击性的枭兽。过去它们都是很温和的——甚至可以说是神秘的动物。尽管仍然有人对它们非常尊敬，但出于对奥伯丁安全的考虑，我不得不保持更现实一些的观点。$B$B据说这段时间以来，月光枭兽被黑海岸东部山脉上的一块巨大的红色水晶吸引，聚集在它的周围。没有人知道那块水晶是什么，也没有人知道它是否真的存在。我想让你去找到它的位置，并把你所发现的任何东西都报告给我。', '到奥伯丁的东边去，沿着黑海岸东部边界的山脉寻找一颗巨大的红色水晶，然后向奥伯丁的哨兵戈琳达·纳希恩汇报你的发现。', '那么水晶确实存在了，$N?嗯……不管怎么说，你出色地完成了任务，干得漂亮!$B$B这块水晶到底是什么东西?这只是许多问题中的一个。另一个浮现在我脑中的问题是，为什么枭兽会被它吸引?这水晶是自然形成的呢，还是邪恶的产物?$B$B我还有很多问题，但我们还需要仔细研究那块水晶才能得到更多答案。', '关于那块红色水晶，你有什么要汇报的吗?它真的存在吗?', '在黑海岸东部边界的山上找到巨大的红色水晶', '去黑海岸找奥伯丁的哨兵戈琳达·纳希恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4812, '清洗水晶', '用这支小瓶装一些奥伯丁月亮井的水。它潜在的魔法能量可以帮我们弄清这块水晶的成分，你必须把水倒在那块水晶上，剩下的就不用你操心了。$B$B虽然我不觉得你会有什么不测，但我仍然希望你多加小心。我们东边就是费伍德森林，如果这块水晶真的与那个地方有关联，它就可能非常危险。', '在奥伯丁月亮井中把空水瓶装满，然后调查黑海岸东部山脉的红水晶。', '你又来到了这块神秘的水晶旁，并小心翼翼地将月井水倒在了水晶的顶部。随着水流刷洗着水晶，你看到原本混浊的表面开始变得透明了……', '这块水晶伫立在黑海岸繁茂的森林中，与周围的景色格格不入。你似乎听到有非常轻微的嗡嗡声从水晶里面传出来。', '', '去找黑海岸的神秘的红色水晶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4821, '异型卵', '在千针石林流传着一个有关异型卵的传言。那些声称见到它的旅行者都没能靠近它进行详细的观察。毒蛇守卫着那枚卵，就仿佛是在守卫它们自己的卵一样。$B$B我想让你去把那枚异型卵找出来交给我，以便让我进行观察。据说它在某条毒蛇的窝里，但是沿着乱风岗南面与东北面的悬崖基部有好几处蛇窝。', '把异型卵交给乱风岗的哈加尔·雷蹄。', '嗯，终于……这枚神秘的卵终于还是被我拿到了。现在，让我仔细看看这东西……什么……!这是什么……?', '我必须要对这枚神秘的卵有更多了解，天知道它会孵出什么东西来。', '', '去千针石林找乱风岗的哈加尔·雷蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4822, '草莓冰激凌', '冰激凌！哦，求你了求你了，帮我买些冰激凌来吧？！我最喜欢草莓味的，而世界上没有比提古勒和弗洛尔的草莓冰激凌更棒的冰激凌了！这是我最最喜欢的冰激凌！$B$B上次我在闪光平原的赛车场尝到过它，不过现在我听说他们开始在城里出售冰激凌了！求求你了，我实在是太想尝尝提古勒和弗洛尔的草莓冰激凌了！', '为你看护的孩子买一些草莓冰激凌。这个孩子似乎最喜欢“提古勒和弗洛尔”牌的草莓冰激凌。', '嗯!我喜欢草莓冰淇淋!提古勒和弗洛尔的草莓冰淇淋是最棒的!$B$B非常感谢你，$N―这是我所得到的最好的礼物!', '我希望他们除了草莓冰淇淋之外还能做出更多口味的冰淇淋，但是还好我最喜欢的就是草莓口味!', '', '去找人类孤儿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4841, '清除半人马', '$N，现在我委托你去消灭那些半人马，让他们感受我们的怒气。进攻乱风岗北面的半人马营地！让怒火指引你的武器！', '杀掉12个加拉克斥候、10个加拉克争斗者和6个加拉克逐风者，然后向乱风岗的峭壁卫兵图林·长角复命。', '为了表示我的感谢，请拿着这个，$N。', '快一点，$N，我知道你还没有完成我交给你的任务。猎杀那些半人马，然后我就会给你一份奖励以表示感谢。', '', '去千针石林找乱风岗的峭壁卫兵图林·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4842, '奇怪的源头', '老实说，尽管冬泉谷没有火山，但是我相信这些温泉更为危险……$B$B嗯，你应该是想亲自去看看。横跨冬泉谷，然后朝这个地区的最南端前进。当周围的空气变得污浊而闷热，天色也开始变暗时，你就会发现温泉的源头。$B$B去看看吧，我想你回来时会带着许多疑问的。', '根据多诺瓦·雪山的指示行动，然后回到她那里报告。', '没错，暗语峡谷的恶魔……我相信是他们污染了这片土地。我将继续观察温泉，看看是否能通过研究得出更进一步的结论。$B$B如果你准备深入暗语峡谷的话，我建议你在变得更加强大之后再去。', '泉水似乎有些古怪……我还不能确定这意味着什么……', '发现暗语峡谷', '去找冬泉谷的多诺瓦·雪山。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4862, '蜘蛛卵', '信不信由你，有人愿意出钱购买最凶猛的野兽！我将派比修进入黑石塔去收集一些尖塔蜘蛛的卵，但是我已经好几周都没有得到她的消息了。也许你能帮帮我的忙？$B$B我跟你说啊，$N，到黑石塔去为我收集一些尖塔蜘蛛卵，把它们带回来，我不仅会给你一笔现金，甚至还可以帮你驯服一只小蜘蛛！', '到黑石塔去为基布雷尔收集15枚尖塔蜘蛛卵。$B$B听说那些蜘蛛周围有许多这样的卵。', '好重!我的意思是，看这些卵!这些应该能值一大笔钱。$B$B就像我承诺过的一样，你也可以带着一个这样的小东西。别被它咬了!', '你是弄到蜘蛛卵了，还是仅仅跑来跟我打个招呼?', '', '去燃烧平原找烈焰峰的基布雷尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4864, '被激怒的枭兽', '翻了翻箱子里的东西之后，你认为里面的工具和其它一些物品可能对加隆仍然有用，但是你没有发现他所说的护符。$B$B枭兽似乎居住在此地北面和东面的地区，因此你认为接下来最好到它们的聚居地去找一找。', '从雪地中拾起加隆的补给物资，然后寻找盗取加隆所说的护符的枭兽。$B$B将加隆的补给物资和蓝色羽毛护符交给冬泉谷的加隆·石矛。', '啊，小$G伙子:姑娘;，这真是太好了。我以为那些疯狂的野兽毁掉了我所有的财产……$B$B但是你找到了我的工具，更重要的是，你找到了护符!我在想，为什么枭兽会如此认真地守护这件东西……无论如何，下次我可不会随便就到它们那里去了!', '啊……你有什么新消息么?', '', '去冬泉谷找坠星村的加隆·石矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4866, '蛛后的乳汁', '这也许是世界上效力最强的毒药之一，$c！$B$B在我转至黑石塔的旅途中，无意中听到过黑石兽人谈起一种致命的毒药。他们称其为“蛛后的乳汁”，这个名字是根据黑石塔里面那只烟网蛛后的名字得来的。$B$B我需要一份在你体内流淌的“蛛后的乳汁”的样本，毒囊是远远不够的！让她在你体内注入毒汁，然后回到我这儿来！$B$B然后……我就能得到乳汁了！$B$B<他揉搓着双手，充满期待。>', '你可以在黑石塔的中心地带找到烟网蛛后。与她战斗，让她在你体内注入毒汁。如果你有能力的话，就杀死她吧。当你中毒之后，回到狼狈不堪的约翰那儿，他会从你的身体里抽取这些“蛛后的乳汁”。', '这肯定可以酿成最好的麦芽酒!$B$B呃，你以为它是干什么用的?毒药??$B$B孩子，你疯了……', '<狼狈不堪的约翰使劲拧了拧你。>', '挤出毒液', '去燃烧平原的烈焰峰找狼狈不堪的约翰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4867, '乌洛克', '啊！说起来就麻烦了！$B$B拿上这张便笺！把我的蟑螂牵过来！', '阅读瓦罗什的卷轴。将瓦罗什的蟑螂交给他。', '啊!我感觉自己已恢复了力量。我的思维再也不会受到 乌洛克的诅咒了。$B$B谢谢你，$N!谦卑的行径有失我的身份，但是我必须承认你帮了我的大忙。$B$B祝你在前往黑石塔的旅途中一路顺风。你认为自己能到达塔顶，这种想法很傻，不过你的勇气是毋庸置疑的。', '啊!你把我的魔精带来了吗?', '', '去燃烧平原的黑石塔找瓦罗什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4882, '守护秘密', '你不清楚这条从你刚刚杀掉的那头枭兽身上拿到的项链究竟有什么重要的价值。它闪着奇特的光芒，时亮时暗。$B$B特鲁尔·法贝恩也许对此更有了解，因为他对枭兽可谓了如指掌。也许你应该向他咨询一下。', '把蓝羽项链交给血毒岗哨的特鲁尔·法贝恩。', '一项重要的发现?', '你是要汇报另一项任务的进展吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4883, '守护秘密', '我确实比你更了解冬泉谷的枭兽，但是我不太了解它们所使用的魔法。我知道谁可以告诉你有关这条项链的更多信息。$B$B雷霆崖的纳拉·蛮鬃是这方面的专家，去问问她吧。祝你好运，$N。', '把蓝羽项链交给纳拉·蛮鬃。', '这条项炼中所蕴含的能量，$N……我相信它只有一个来源。$B$B<纳拉闭上眼睛，然后沉默了一会儿。>$B$B枭兽以前并不是这样的，它们被误导了，堕落了。它们曾经肩负着神圣的使命―夜精灵的女神艾露恩创造了这种生物，让它们守护她的圣地。$B$B虽然这听起来与现在的局面并没有什么关系，但我希望你看得更深一些。$B$B总有一天，你会理解的。谢谢你把这个交给我，$N。', '我能帮你什么忙吗，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4903, '高图斯的命令', '根据军官高图斯的命令，黑石塔的下列主要首领必须被消灭：$B$B对我们造成巨大威胁的欧莫克大王。$B$B残忍无情的巨魔指挥官沃恩。$B$B监督者维姆萨拉克。$B$B如果你找到何重要的文件，也必须一并上缴。$B$B成功则受人敬仰。$B$B失败则被人遗忘。', '杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。', '<督军高图斯暗绿色的皮肤在一瞬间变得苍白。>', '<督军高图斯向你敬礼。>', '', '去荒芜之地找卡加斯的军官高图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4904, '终获解救', '阿纳克要和我结婚……但是在我拒绝了他的提议之后，他当晚就回来绑架了我。我的兄弟试图阻止他，但是阿纳克太强大了，他……他杀了我的兄弟，然后把我带到了这里。我可怜的兄弟……$B$B$N，你能护送我离开恐怖图腾营地吗？求你了……我要回到萨利亚身边去！她一定非常思念我。', '护送拉克塔·风歌离开恐怖图腾营地，然后与乱风岗的萨利亚谈一谈。', '谢谢你，$N。我知道她会回到我身边的。她把你的英勇事迹以及你帮她逃走的事情都告诉了我。这些东西原本属于她的兄弟，现在她想让你收下它们。', '萨利亚我好想你……', '护送拉克塔·风歌离开黑云峰。', '去千针石林找乱风岗的萨利亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4906, '更深重的堕落', '第二个萨特营地在费伍德森林的北部，他们的头领是萨瓦里克。这个诡计多端的恶魔在不断吸收费伍德森林中的那些堕落生物的力量。$B$B萨瓦瑟拉斯和他的手下只不过是一个宏大计划的一部分，他们要培养出一座堕落的月亮井，然后用它为萨瓦里克提供力量。$b$b现在萨瓦瑟拉斯已经成为历史了，那么，$n，你的任务就是到北部去，打败萨瓦里克。', '费伍德森林的艾瑞丹·蓝风要你去杀掉8个碧火唤魔者、8个碧火背叛者、8个碧火欺诈者和萨瓦里克。任务完成之后回到艾瑞丹那里复命。', '感谢你所做的一切，$N。愿艾露恩保佑你。', '请你快点去结束费伍德森林的生物所遭受的痛苦。', '', '去费伍德森林找翡翠圣地的艾瑞丹·蓝风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4921, '在战斗中失踪', '我们在一个小小的牛头人营地里作战，然后就被冲散了——她独自与三个刺背野猪人交战。形势越来越不妙，我引开了一些敌人，结果她又很快被新赶到的敌人包围了。在狂怒之下，我冲向敌人，但是他们人多势众，很轻松地就把我打倒了。$B$B我醒来的时候，一位牛头人德鲁伊正在照料我的伤口，他是在黄金之路上找到我的。$B$B$c，请你帮我寻找我妻子的音讯。', '找到曼科里克的妻子，然后回到十字路口找他。', '我明白。谢谢你，$C。', '你找到她的线索了吗?我胸中的疼痛告诉我，也许最糟糕的事情已经发生了，但我还心存一点点希望……', '', '去找贫瘠之地的曼科里克。', '找到曼科里克的妻子', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4941, '伊崔格的智慧', '雷德还活着？$B$B不可能！$B$B据说雷德在数十年前就被杀掉了。$B$B去寻求伊崔格的建议吧，$N。没有谁能比他更了解黑石氏族的情况了，如果这上面所写的都是真的，那么你应该通知伊崔格。谁都有复仇的权利。$B$B你可以在奥格瑞玛找到他。$B$B在你跟伊崔格谈过话之后，便去与酋长交流一下，搞清楚他想要如何处理这个问题。', '和奥格瑞玛的伊崔格谈一谈。讨论完毕后，咨询萨尔的意见。$B$B你回忆起曾在萨尔的大厅中见过伊崔格。', '<萨尔听到你带来的消息之后显得有些沮丧。>', '你没看见我很忙吗?', '与伊崔格会面', '去找奥格瑞玛的萨尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4961, '奥拉赫宝珠的净化', '啊，召唤师的宝珠——这肯定是污染的来源。如果你准备使用宝珠的话，我们就必须先驱除里面的恶魔，这对我来说很容易。$B$B不过你的任务就困难一些了。一旦我释放出了恶魔，你就必须杀死他。$B$B而且你的动作必须要快，如果你太慢的话，他就会回到宝珠里面去，那样我们可就白费力气了！$B$B准备好你最强大的法术，把药水放在随手可及的地方，如果你有朋友的话，也叫几个来帮忙，这个任务真的不可掉以轻心。', '杀死宝珠之魔，然后与塔贝萨谈一谈。', '干得好，$N!你让那个恶魔吃了苦头，看来短时间内它是不会忘了你所展现出的强大力量和技巧的，现在你可以带着净化过的宝珠回去找梅纳拉，然后好好地利用这颗宝珠。$B$B祝你好运，$C。也许以后我们还能再见面的。', '你必须杀死那个恶魔，将它永远地从宝珠中驱逐出去，$N。', '', '去尘泥沼泽找塔贝萨的农场的塔贝萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4962, '地狱犬的灵魂', '这么说，你决定去捕获地狱犬的灵魂，这很好。$B$B带着这颗红宝石——你必须带着它才能捕获那种恶魔的灵魂。你应该很熟悉它的使用方法：当地狱犬快要死亡的时候，就使用这颗宝石，它会替你完成剩下的工作。$B$B我建议你到凄凉之地去，在那里收服一头地狱犬。$B$B你成功之后就把捕获到的灵魂和红宝石都交给梅纳拉。', '带上地狱犬红宝石到凄凉之地去，用它捕获一只地狱犬的灵魂。成功之后，将地狱犬红宝石和被禁锢的地狱犬灵魂交给贫瘠之地的梅纳拉·沃伦德。', '啊，恶魔犬的灵魂。干得好，$N。$B$B现在只要你把到灵魂和净化过的宝珠都给我，我就可以将这两者融合起来了。', '嗯，$N?你做出选择了吗?你选择了炼狱火还是恶魔犬?$B$B这取决于你，你的选择将反映出你的优势和弱点。对术士来说，强化自己的优势而不弥补自己的弱点是很常见的。有时候，制服敌人靠的是出色的策略，而不是一个样样兼顾的施法者。', '', '去贫瘠之地找棘齿城的梅纳拉·沃伦德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4963, '地狱火的灵魂', '这么说，你决定去捕获地狱火的灵魂，这很好。$B$B带着这颗绿宝石——你必须带着它才能捕获那种恶魔的灵魂。你应该很熟悉它的使用方法：当地狱火快要死亡的时候，就使用这颗宝石，它会替你完成剩下的工作。$B$B我建议你到凄凉之地去，在那里收服一个地狱火。$B$B你成功之后就把捕获到的灵魂和绿宝石都交给梅纳拉。', '带上地狱火绿宝石到凄凉之地去，用它捕获一个地狱火的灵魂。成功之后，将地狱火绿宝石和被禁锢的地狱火灵魂交给贫瘠之地的梅纳拉·沃伦德。', '啊，炼狱火的灵魂。干得好，$N。$B$B现在只要你把到灵魂和净化过的宝珠都给我，我就可以将这两者融合起来了。', '嗯，$N?你做出选择了吗?你选择了炼狱火还是恶魔犬?$B$B这取决于你，你的选择将反映出你的优势和弱点。对术士来说，强化自己的优势而不弥补自己的弱点是很常见的。有时候，制服敌人靠的是出色的策略，而不是一个样样兼顾的施法者。', '', '去找贫瘠之地的梅纳拉·沃伦德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4970, '霜刃豹的食物', '如果你想要证明自己，可以先从一项简单但很重要的任务开始。$B$B从遍布冬泉谷的奇美拉和碎齿熊身上收集它们的肉。把肉交给我，这样我就可以用它来喂养那些正在接受训练的霜刃豹了。', '收集5块碎齿熊肉和5块冰风奇美拉肉，把它们交给冬泉谷的雷沃·霜翼。', '谢谢你的帮助，$N。我对你的评价随着时间与日俱增啊。', '纪律和决心是你的目标。我会让你完成若干个简单的任务;每次你都必须尽全力。', '', '去冬泉谷找霜刀石的雷沃·霜翼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4971, '时间问题', '一股邪恶的力量——很可能是天灾军团——出现在安多哈尔，扰乱了时间的流动！我可以尝试维持现有的时间进程，并修正它所遭到的破坏，但是我必须在一个安静的环境中才能做这些事情，这就需要你的帮助。$B$B时光寄生虫——以改变的时间流为能源的食腐虫——在安多哈尔的仓库中大量繁殖，扭曲的蓝色脉搏是它们身体唯一可见的部分。它们阻挠了我的施法过程，所以，$N，请你使用时光置换器帮我除掉这些寄生虫。', '在安多哈尔的一处仓库附近使用时光置换器，使时光寄生虫现身。$B$B杀掉10只时光寄生虫，然后将时光置换器还给西瘟疫之地安多哈尔旅店的克罗米。', '时间已经变得容易修复多了，谢谢你，$N。虽然你可能无法完全理解时间线断裂所造成的后果，但是你能理解对抗天灾军团的重要性，这点让我感到非常欣慰。$B$B年轻的$C，我想对你所给予的帮助表示感谢，这并不是什么坏事。你即将面临伟大的命运，这么一件小玩意显然无法改变什么，但是我和巨龙军团都需要你的帮助……', '当时间的进程被打乱时，时光寄生虫就会出现。现在就是这种状况，这可真是件令人烦恼的事儿。$B$B除掉那些时光寄生虫将有助于我控制不断恶化的情况。如果你完成了任务，我应该可以很快感知到。', '', '去西瘟疫之地找安多哈尔废墟的克罗米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4972, '找回时间', '我需要借助你的能力进入这间房间以外的世界，$N。请允许我稍后向你解释。$B$B你发现这间房间与安多哈尔其它地方的不同了吧。我的飞龙以不同的方式在不同的时间线上工作着。要修复安多哈尔的损伤，我要从一个不同的时间线着手，避免过分污染它。要继续进行这项工作的话，我需要一些时间饰品，其中一个是在瘟疫袭击安多哈尔时产生的。在建筑物残骸中寻找时间饰品，这些建筑都是这个曾经繁华的城市的一部分。', '在安多哈尔城中四处散落的保险箱里找到5只安多哈尔怀表，然后把它们交给西瘟疫之地安多哈尔旅店里的克罗米。', '这些正是我需要的，$N。谢谢你。$B$B请允许我用这个表达谢意。你可能不知道要使用这样的装备还需要什么。你甚至不知道这究竟是什么。唉，我不能告诉你，自己去体会它的用场吧;你只需要了解，在将来某个时候，你也许能发现它具有极大的效用。在那之前，无论你是否能一直保存它……，朋友，这都取决于你。', '我寻找的那些计时器都是简单的小装置，当瘟疫侵袭安多哈尔的时候，它们就停止走动了。$B$B时间永远不会停止，而你找到的怀表会自动调整回正确时间……就是说，只要这儿仍在混乱之中。', '', '去西瘟疫之地找安多哈尔废墟的克罗米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4973, '找回时间', '要是你愿意再帮我一次，我就不客气啦。我想要更多的怀表，你也许能在安多哈尔的废墟中找到它们。它们能帮助我们在与扰乱时间线的任何邪恶力量抗衡时保持平衡。$B$B对于交换，我将给你另外一件装备，将来你会发现它的大用处的。', '在安多哈尔城的废墟里找到5只安多哈尔怀表，然后把它们交给西瘟疫之地安多哈尔旅店里的克罗米。', '再次感谢你的帮助。请收下这份礼物。虽然你可能还不知道何时可使用这样的装备，或许将来，时间会揭示出它真正的用意。可以这么说，我已感知到那些即将发生的事情了，$N。', '安多哈尔的怀表，就像城镇大厅废墟上的大钟，所有的指针都停留在三点的位置。这便是瘟疫首次席卷城市时带来的效应，指针停止转动了。$B$B几乎所有人都为那天发生的事情惋惜不已，就如人类感知的那样，时间流形成了。青铜龙军团必须坚持守护时间线!', '', '去西瘟疫之地找安多哈尔废墟的克罗米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4974, '为部落而战！', '雷德受到黑龙的保护，因此他才如此狂妄嚣张。$B$B你，$N，必须寻找一条穿过晋升大厅的道路，找到大酋长雷德·黑手并杀死他——为部落而战！$B$B<萨尔一拳打在王座上。>$B$B高举着他的徽记凯旋吧，将徽记呈献给你的酋长。去吧，你将成为部落的英雄！', '去黑石塔杀死大酋长雷德·黑手，带着他的徽记返回奥格瑞玛。', '你给了黑石氏族致命的一击，$N。他们的大酋长已死，黑石军团将再度陷入混乱之中。$B$B为了表示对你的敬意，卡利姆多的部落成员都将得到奖赏!', '<萨尔低吼着。>', '', '去找奥格瑞玛的萨尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4976, '归还净化过的宝珠', '把净化过的宝珠交给棘齿城的梅纳拉，$N。代我向她问好，一路小心。我真的希望你能应付得了越来越强大的诱惑和腐蚀的力量。$B$B祝你好运。', '将净化过的地狱火宝珠交给贫瘠之地的梅纳拉·沃伦德。', '干得好，$N。这可是个好东西。$B$B你要做的最后一件事情就是决定要在宝珠中禁锢哪个恶魔。有了它，你便获得了新的力量。', '你搜寻塔贝萨和宝珠的事情有没有新的进展，$N?$B$B塔贝萨对魔法的力量可以说是应付自如。我相信如果你能找到她的话，她肯定会帮助你的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4982, '比修的装置', '在夜里，当这个地方守备松懈的时候，我就会在城里偷偷地四处走动，记下我所看到的可能会对K.E.F.有战略价值的任何东西。$B$B然而昨晚事情变得非常糟糕，我被一张网绊到并触动了一个机关，我马上把我的侦察装置藏起来去找藏身之所了！不幸的是，我没法取回那套装置。他们已经把巡逻兵的数量增加了两三倍！所有的情报都丢失了。$B$B把我的东西拿回来，我就可以返回K.E.F.去了。', '找到比修的装置并把它们还给她。你记得她说过她把装置藏在城市的最底层。', '你成功了!只要雷克斯洛特得到这些图纸，他就会忘记他本想对我做的那些可恶的事情。$B$B$N，你是我的英雄!', '找到了吗?', '', '去找黑石塔的比修。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4983, '比修的侦察报告', '把这份报告交给雷克斯洛特。它可以让我恢复好名声，并且肯定会让K.E.F.在对付这些兽人时占据战略上的优势。$B$B跟你一起回去？我有太多的工作要做。快走吧，他们急需这些报告！', '把比修的侦查报告交给卡加斯的雷克斯洛特。', '她又想办法摆脱了另一个困境!这些报告在我们对付黑石兽人时将提供足够的情报。$B$B当然，你也会因你的辛勤工作得到奖赏的。', '那个哥布尔在哪儿?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4984, '大自然的苦楚', '尽管我不可能以一己之力反抗亡灵天灾，但我仍然来到了这里，尽力治愈他们对大自然造成的伤害。这片土地上的生灵遭受着瘟疫所带来的灾难，这瘟疫使大地窒息。我想请你把我在这里未完成的工作继续下去。$B$B对那些正在忍受折磨的动物们来说，除了仁慈地解放它们，没有什么其它的解决办法了。把附近生病的狼找出来，杀死它们。我请求你，$N，结束它们的痛苦吧……这样做也会令我得到安宁。', '消灭8只生病的狼，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。', '我……我感觉到那些被你杀死的狼的灵魂现在已经安息了。它们……和我一样，都感谢你仁慈地解放了它们的灵魂。\r\n\r\n那些狼已经不在这个被诅咒的地方继续忍受痛苦了，$N。但是，我还需要你再次帮助我……', '感染了瘟疫的狼必须被除掉，$N。他们所患的疾病无法治愈。我曾经尝试过……我一直在试图拯救他们，直到我自己也死于瘟疫。', '', '去西瘟疫之地找达隆米尔湖的穆格雷斯·深水。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4985, '大自然的苦楚', '在我们所在地的东方，东瘟疫之地边界的附近，从前骄傲而威严的灰熊在乡村游走。亡灵天灾所释放的瘟疫也已将这些动物趋散。它们在乡村游荡，饱受了肌肉僵硬和皮肉腐烂之苦。$B$B我请求你也去结束它们的痛苦。治疗它们苦难的唯一方法就是让其痛快的死去，这必须由你亲手来完成。', '消灭8只生病的灰熊，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。', '“我感觉到那些灰熊已经被杀死，它们的痛苦已经结束。我……我还有一件事情要求你。我把它写在……写在这根树枝上，因为我感到我将要离开此地了。$B$B确实……我要走了。再次谢谢你，朋友……这块被诅咒的土地上的生灵都安息了……现在该轮到我了。”$B$B这位德鲁伊发出了一声沉重的叹息，然后从他的喉咙中传出一阵咯咯声。他的躯体一动不动地躺在了小屋的地板上。', '我听到你的脚步声了，$N。我的视力已经消退，但我仍然能感觉到周围的事物。你让那些受尽疾病折磨的灰熊安息了吗?', '', '去西瘟疫之地找达隆米尔湖的穆格雷斯·深水。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4986, '雕文橡木枝', '牛头人德鲁伊那毫无生气的手紧紧地抓着一根看上去极为结实的橡木枝，树皮上刻着一些德鲁伊教派的文字。$B$B当你握着这根树枝时，你发现原本应该冰冷的树枝摸上去却非常温暖。巨树泰达希尔的画面清\r\n晰地浮现在你的脑海里，然后是达纳苏斯。“塞纳里奥议会”这几个字也涌到了你的唇边。你现在很清楚要把这根树枝带到哪儿去了。', '根据雕文橡木枝上面所附加的魔法，这个牛头人德鲁伊本来准备把它交给达纳苏斯的塞纳里奥议会。看来你应该到那里去找一个德鲁伊，并寻求他的帮助。', '这……这很奇怪。这位德鲁伊―这位牛头人德鲁伊―给你提供了大量有关天灾军团瘟疫的宝贵资料。一个牛头人会将这种情报提供给一个$r，而且还不求任何回报，这让我十分惊讶，如果你所言属实的话。我们会善加利用这个的，我向你保证。可能牛头人还没有像范达尔所想的那样完全背弃了塞纳留斯……$B$B呃，无论如何，请接受这个作为塞纳里奥议会对你的感谢。', '我代表塞纳里奥议会欢迎你的到来，$C。你找我们有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4987, '雕文橡木枝', '牛头人德鲁伊那毫无生气的手紧紧地抓着一根看上去极为结实的橡木枝，树皮上刻着一些德鲁伊教派的文字。$B$B当你握着这根树枝时，你发现原本应该冰冷的树枝摸上去却非常温暖。莫高雷地区的雷霆崖的画面清晰地浮现在你的脑海里，然后是达纳苏斯。“塞纳里奥议会”这几个字也涌到了你的唇边。你现在很清楚要把这根树枝带到哪儿去了。', '根据雕文橡木枝上面所附加的魔法，这个牛头人德鲁伊本来准备把它交给雷霆崖的塞纳里奥议会。看来你应该到那里去找一个德鲁伊，并寻求他的帮助。', '你说这是从穆格雷斯那里拿来的?我们听说过他想要去帮助那些在瘟疫之地受苦的生物，但我们却没有想到……这太令我伤心了。穆格雷斯是……曾是我的好朋友，我会为他的去世深深哀悼的。$B$B但他的努力没有白费，这都要感谢你的帮助。在这段树枝里保存着更多有关于天灾军团所传播的瘟疫情报，我们会仔细研究它的。至于你，请收下这个吧，这是我们对你的高尚行为所能给予的唯一回报了。', '我代表塞纳里奥议会欢迎你的到来，$C。你找我们有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5001, '比修的装置', '通常我是不会与$r打交道的，但是现在看起来，我前有困境后有巨魔，进退两难。你知道，我在此地的任务对部落来说有极其重要的意义。然而我得到的情报对联盟来说也是有益的。请相信我，我不是联盟的支持者，但黑石氏族不只有一群兽人。$B$B如果你帮我找到我的东西，我就会给你一些对你们也有用的情报。$B$B同意吗？', '找到比修的装置并把它们还给她。祝你好运！', '我说话算话!东西在哪里?', '运气如何?', '', '去找黑石塔的比修。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5002, '给麦克斯韦尔的消息', '我是个说话算话的小地精。现在仔细听着：$B$B这些兽人的主要用途是黑龙的苦工和炮灰！$B$B他们真正的头领不是别人，正是奈法利安，死亡之翼的儿子。我还在这一带侦察到了一些奈法利安的下属所在的位置。$B$B把这张地图交给燃烧平原的麦克斯韦尔元帅，地图上面标记着这些魔王的位置，很容易就可以辨认出来。', '到燃烧平原去，把比修的情报交给麦克斯韦尔元帅。', '这与我们所知的大部分都吻合。不管怎样，这是个既有趣却又非常不幸的消息。$B$B这张地图上的记号在削弱黑石氏族威胁的过程中将会被证明是非常有价值的。', '啊，$N。好久不见了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5022, '迟到总比不到好', '你捡起那只包裹，然后擦掉了积落在上面的一层薄薄的尘土和泥垢。这只包裹上面草草地写着要投寄给暴风城里的一个名叫艾玛·费尔斯通的人，而包裹的递送日期已经是四年之前了。$B$B尽管你并不清楚艾玛·费尔斯通是否还活着，但暴风城的市政厅里应该还保留有城市居民的记录，你应该去找暴风城人口普查处的皇家代理人帮忙。', '与暴风城的皇家代理人巴瑟罗尔协商，查找到艾玛·费尔斯通的下落。通常在市政厅里都有一个人口普查官。', '你说这是给一个名叫艾玛.费尔斯通的人的包裹?收件人的地址是暴风城，四年以前?让我看看……$B$B据我们所知，四年前城里是有一个名叫艾玛.费尔斯通的人。嗯，我应该说可能有这个人—这份人口普查记录是五年前的，但我这里没有关于她离开暴风城的报告，当然这并不意味着她还在这里。$B$B等一下……这只包裹该不是寄给老艾玛的吧?', '欢迎来到暴风城人口普查办公室，如果你需要我们城市居民的资讯，那么我可以帮助你。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5023, '迟到总比不到好', '你捡起那只包裹，然后擦掉了积落在上面的一层薄薄的尘土和泥垢。这只包裹上面草草地写着要投寄给洛丹伦的一个名叫杰雷米亚·费尔斯通的人，而包裹的递送日期已经是四年之前了。$B$B尽管你并不清楚杰雷米亚·费尔斯通是否还活着，但幽暗城——也就是以前的洛丹伦——应该还保留有城市居民的记录，你应该去找幽暗城人口普查处的皇家管理人帮忙。', '与幽暗城的皇家管理人巴哈乌斯协商，查找杰雷米亚·费尔斯通的下落。通常在公会注册处附近会有一个人口普查官。', '给一个叫做杰雷米亚.费尔斯通的人的包裹，收件地址是洛丹伦……让我找找看。$B$B杰雷米亚.费尔斯通在瘟疫来袭之前就在城里。哦，我应该说从前的杰雷米亚.费尔斯通—有些被遗忘者改了他们的姓好跟之前的一切都断绝关系。这个人也不例外，从前的杰雷米亚.费尔斯通现在的名字是杰雷米亚.派森。$B$B等一下……他不就是那个卖蟑螂的吗?', '你到这里来是寻求幽暗城人口普查局的帮助，还是问我某个你认识的人是不是已经死了?每天都有无数人来问我这个问题……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5041, '十字路口的补给品', '那次被野猪人剪了径的商队运载着我们急需的物资。$B$B就你对钢鬃野猪人的作战记录来说，你真的是勇气十足，我希望你再接再厉，不过这一次，我想知道我是否能请你睁大眼睛，帮我们寻找一些丢失的供给物资。你可以在野猪人的营地里四下找找，那些家伙做了那一票之后明显胖了许多。$B$B十字路口的居民欠你的人情。', '找到十字路口的补给箱，把它还给贫瘠之地的索克。', '哈哈!谢谢你，$N!这会对我们有非常大的帮助。你对十字路口和部落来说真是一大福音。如果我能为你做什么的话，请一定要让我知道。', '你找到我们的补给物资了吗?$N?我相信你很容易就把野猪人打败了。', '', '去找贫瘠之地的索克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5042, '阿迦玛甘的力量', '', '', '如果碎牙能亲眼看到你杀掉那些背叛他的蠢货就好了!<哼哼>$B$B谢谢你在收集这些裂片的时候杀掉了更多的刺背野猪人。请你继续消灭他们，我会继续帮助你的。<哼哼>', '如果你想要得到阿迦玛甘的力量，就给我弄四块血岩裂片来，$r。$B$B如果你被赐予了这个祝福，你的敌人就会在你的力量面前退缩。<哼哼>$B$B钢鬃部落中最伟大的战士都拥有这种力量!', '', '去找莫高雷的碎牙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5043, '阿迦玛甘的敏捷', '', '', '愿你百发百中，精准无比，$r。$B$B阿迦玛甘的灵魂与你同在。如果你愿意的话，就再来<哼哼>找我。如果伟大的野猪之神认为我有价值，碎牙就会再次祝福你<哼哼>。', '据说我们部族里最强大的斥候有着无与伦比的准确度，而且任何盗贼<哼哼>在战争中都无法与他们的灵巧和迅捷媲美。$B$B给我弄四块血岩裂片来，我就会让你变得比任何野猪人都更加敏捷。', '', '去找莫高雷的碎牙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5044, '阿迦玛甘的智慧', '', '', '你的敌人比先前更惧怕你，$C。<鼻息声>$B$B下次我们见面时―有生之年，或是来生―别忘了告诉碎牙你的战斗经历。', '野猪人部族的萨满和地卜师<鼻息声>会召唤阿迦玛甘的力量，以帮助他们进行战争和祭祀仪式，$C。$B$B要是你也希望给自己的法术附上拥有阿迦玛甘的祝福，就给我弄四块血岩裂片来，碎牙会帮助你的。<鼻息声>', '', '去找莫高雷的碎牙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5045, '高涨的士气', '', '', '我们最伟大的战士，还有我们最伟大的<哼哼>萨满都会羡慕你的意志力，$r。$B$B打败更多的刺背野猪人去吧，他们绝对不是你的对手!<哼哼>', '各种战士<哼哼>都需要强大的精神力量。当所有希望都不复存在时，只有它能驱使你去完成更伟大的事业。这对<哼哼>钢鬃野猪人来说并不是秘密。我们是一个有着共同信仰的部族―比起我们在战斗中所表现出的威力<哼哼>来说，我们更以能与阿迦玛甘保持精神联系为荣。$B$B给我弄四块血岩裂片来，我就会祝福你，让你在战斗中充满斗志。<哼哼>', '', '去找莫高雷的碎牙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5046, '野猪之皮', '', '', '去战斗吧，$r。', '所有<哼哼>踏入战场的勇士都需要保护。他们的骨骼必须强壮，他们的皮肤必须坚韧。<哼哼>我的部族也知道这点，为了让我们与生俱来的鬃毛和皮肤有更好的防护效果，<哼哼>我们经常在上战场之前请求阿迦玛甘保护我们免受伤害。$B$B给我带来四块血石裂片，<哼哼>我就会赐给你同样的保护。', '', '去找莫高雷的碎牙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5047, '芬克·恩霍尔，为您效劳！', '你可以在永望镇找到玛雷弗斯·暗锤，$c。告诉他“芬克一切都好”，还有衣服很不错。$B$B然后给他这个。$B$B<芬克给了你一块光鲜的肉。>$B$B这是我“度假”时从比斯巨兽的内脏里摘出来的。$B$B我敢打赌，玛雷弗斯对看到这个东西的时候会大吃一惊的！$B$B哦，我猜你不知道永望镇在哪里，是吗？到冬泉谷去，$g小伙子:女士;！', '与永望镇的玛雷弗斯·暗锤谈一谈。', '活着?衣服起作用了?哦!', '什么事?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5048, '善良的艾玛', '她是个奇怪的人，很可能精神不正常……但是记录显示这个艾玛可能确实就是艾玛·费尔斯通。$B$B你也许见过艾玛在城市里到处游逛——她不停地自言自语，通常都是些荒诞而含糊不清的话。但是她没有伤害任何东西或是任何人，因此人们大都不刁难她。$B$B因此，我认为艾玛事实上就是你要找的艾玛·费尔斯通。你可以问问她是不是姓费尔斯通。', '找到暴风城的艾玛并弄清她是否就是艾玛·费尔斯通。如果是的话，那么她可能想要拿到詹妮丝·费尔斯通给她的包裹。', '我的名字确实是艾玛.菲尔斯通--你是这几年来第一个那样叫我的人。谁……你是谁?$B$B你说你认识……我姐姐?!她还活着吗?我在开什么玩笑，她当然不可能还活着。当瘟疫在洛丹伦爆发时，我已经做好了最坏的打算。我很多的家人都死了……或者更糟。现在只有我在这儿，发疯的老艾玛，独自一人。你是什么人，一个盗墓贼还是什么?你在寻找你的下一个目标吗?$B$B什么……你有我姐姐要给我的包裹?', '我本想叫你离开我的草坪，但是如你所见的，我没有草坪。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5049, '杰雷米亚的忧伤', '根据这些证据，我认为你所找的应该就是杰雷米亚·派森，幽暗城的蟑螂商人。$B$B我一直以为能跑去卖蟑螂的一定是个不平凡的人……毫无疑问，您眼下正在谱写一卷史诗，伟大的$c。我会让您继续进行重塑世界的伟大工作。然而，请允许我成为您这一杰作的一部分，并谦卑地向您揭示他的位置。他就在银行的附近，正舒服地趴在某条人行道下面呢。', '在幽暗城找到杰雷米亚·派森并查明他是否就是你要找的杰雷米亚·费尔斯通。如果他是的话，那么他可能会想要拿到詹妮丝·费尔斯通寄给他的包裹。', '我好几年没有用过那个名字了……但是的，在我生命的一个时期--在这个伟大的非生命之前--那是我的姓。$B$B你说曾认识我姐姐……甚至，近来和我姐姐说过话。$B$B她已经死了。$B$B四年了。$B$B你知道，如果不是因为我的骨头已经很脆弱了，我就会踢你的屁股。你真贪婪，不是吗?$B$B什么……你有一个我姐姐给我的包裹?', '每次有人踩到蟑螂，我都会哭。请不要让我哭泣。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5050, '好运护符', '看起来我错怪你了，$N，为此我应向你道歉。我姐姐送给我许多东西，包括看起来很滑稽的费尔斯通农场地契，我想我一时半会是没法收回它了。$B$B如果我姐姐的灵魂还被束缚在农场不能安息，请你帮帮忙……你能把这个还给她吗？这是她的半个护身符，她的丈夫拿着另外一半。$B$B或许当她知道我拿到这些东西之后就可以安息了。', '把半个好运护符还给西瘟疫之地的詹妮丝·费尔斯通。', '你把半个好运符咒还给那个亡魂。她看了看它，然后期待地看着你。$B$B“亲爱的，你把你的半个好运符咒放哪里了?除非我们的两半都放在一起，否则我们是不可能团聚的。亲爱的……你能看到我吗?”$B$B', '约翰，亲爱的……是你吗?我突然觉得好冷……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5051, '两半合一', '这个可怜的灵魂在继续喃喃自语：$B$B“我好冷，约翰，把你的护符给我，这样我们就可以在一起了！快点，约翰，要在瘟疫把我们变成可恶的野兽之前！我看不到你，约翰……但是我知道你就在附近。我能感觉到你在我身旁……”$B$B也许如果你能找到另一半护符并把两半拼凑起来，就能组合成詹妮丝·费尔斯通的灵魂寻求的东西。', '在西瘟疫之地的费尔斯通农场某地找到另外一半好运护符，并把两半护符合并。$B$B把好运护符交给西瘟疫之地费尔斯通农场的詹妮丝·费尔斯通。', '你把组合好的好运符交给珍妮丝.菲尔斯通的鬼魂。当她一抓住它，你观察到她体内即刻发生了变化。她那空气般的形体微微发光，并用明亮但忧伤的眼睛看着你。$B$B“你让我得到了自由……我不再需要这个好运符了。请你收下它，它或许会带给你像我一样的慰籍。”$B$B', '约翰，不要让那些食尸鬼抓到你……不要让这些食尸鬼抓到我……肮脏的食尸鬼……我们的幸运符会让我们安全的。', '', '去西瘟疫之地找费尔斯通农场的詹妮丝·费尔斯通。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5052, '阿迦玛甘的血岩碎片', '和荆棘一样，鲜血也影响了<猪哼声>大地的其它特性：血红的石头与别的矿石掺杂在一起，刺背野猪人挖出这些碎片并把它们带走，在战斗中把它们当作增强<猪哼声>力量和魔法能量的图腾。<猪哼声>$B$B我知道那个魔法的秘密。$B$B把一块血石碎片交给碎牙来表示你明白了。给碎牙拿来许多血牙碎片，他就会用野猪人的魔法保护你——阿迦玛甘的魔法！<猪哼声>', '给陶拉祖营地的碎牙带去一块血岩碎片。$B$B如果你想要他赐予你阿迦玛甘的力量，就搜集更多的血岩碎片。', '啊，你终于明白了。<猪哼声>我对你说的话没有白讲，$r。碎牙被囚禁着，但没有牢笼可以阻止阿迦玛甘的力量!<猪哼声>$B$B触摸裂片的感觉……我已经很久都没有这种感觉了，$r。$B$B你知道这是怎样的感觉吗?把你的力量与你的躯体分开……$B$B但是，那又是另一个时代的故事了。我答应给你情报。我答应给你阿迦玛甘的力量。我的同胞拒绝了碎牙，现在，我要让你去为我复仇。<猪哼声>', '我们的部族聚集在遍及贫瘠之地的荆棘旁，<猪哼声>因为那种地方是神圣的，但它们都不如剃刀沼泽那般神圣。阿迦玛甘的身体构成了剃刀沼泽的全部<猪哼声>，但高地是最关键的，因为那个入口是由他巨大的嘴形成的!<猪哼声>它会吞掉所有不忠于他的人，并把咀嚼后的尸体吐出来!<猪哼声>$B$B阿迦玛甘把肉体留下来保护我们，而且他还献出了他的灵魂，让我们来保护他。<猪哼声>', '', '去贫瘠之地找陶拉祖营地的碎牙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5054, '碎齿熊尤西乌斯', '在冬泉谷那白雪茫茫的山脉里，有一头狩猎技术纯熟精湛的碎齿熊，尤西乌斯。$B$B现在我让你去对付他，尤西乌斯就在永望镇西边的山坡上徘徊。在它发现你的意图之前找到他，击败他。$B$B所有前去猎杀尤西乌斯的猎人都很快发现自己变成了猎物，而尤西乌斯才是猎人。你要多加小心。', '永望镇的斯托姆·影蹄想要你去杀死尤西乌斯。', '这可不是简单的工作，但你却出色地完成了它。不过，不要以为你已经令我折服了，$N。', '动身吧，$C。去找出尤西乌斯。', '', '去冬泉谷找永望镇的斯托姆·影蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5055, '冰风奇美拉布鲁米兰', '布鲁米兰迅捷而又聪明，她悄无声息地在冬泉谷南边的雪地中滑翔。但是不要让她那优雅的外表迷惑了你，所有从她身旁经过的旅行者都受到了猛烈的攻击，而且多半会赔上他们的性命。$B$B从那些冰风奇美拉中找出布鲁米兰，打败它，然后再回来见我。', '永望镇的斯托姆·影蹄想要你去杀死布鲁米兰。', '哦，你回来了。我现在相信你是一个天生的猎手。你挑战了最凶猛的野兽并平安归来，这让我有些惊讶。$B$B现在，你可以去完成我最后的要求了。', '布鲁米兰在呼唤你，$N。', '', '去冬泉谷找永望镇的斯托姆·影蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5056, '希洛塔姆', '在冬泉谷的北方，有一大群凶猛的雪豹聚集在一处被称作霜刀石的地方。这些豹子的首领是希洛塔姆。打败她，你的同伴就会对你充满敬意。$B$B再去一次冬泉谷，一到那里就开始从霜刃豹身上搜集它们的肉。找到希洛塔姆之石，把肉放在那里，这样就可以召来愤怒的希洛塔姆。$B$B迎战狂怒的霜刃豹首领，并打败她。', '永望镇的斯托姆·影蹄想要你去杀死希洛塔姆。', '你已经证明了自己的力量和决心。还有许多挑战在等着你，但我已经尽我所能地指点你了。$B$B祝你好运，$N。', '希洛塔姆勇猛而无情，她会以热情和生命保卫她的同类。', '', '去冬泉谷找永望镇的斯托姆·影蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5059, '被锁起来的农夫', '', '', '从农夫达尔松那已经成为食尸鬼的遗体中拿到的钥匙完全与锁孔吻合。柜子的门转开了，展现在你面前的是数样完整无缺的物品，而且它们看起来都非常珍贵。', '一个极其结实的柜子立在你面前，柜子的门被一个内建的锁牢牢地锁着。柜子的前面有深深的划痕与刻痕，看起来好像是在无数次想要解开其中秘密的粗暴失败尝试所导致的结果。$B$B如果你想要打开这个柜子，就得先找到钥匙。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5060, '被锁起来的农夫', '', '', '从农夫达尔松那已经成为食尸鬼的遗体中拿到的钥匙完全与锁孔吻合。柜子的门转开了，展现在你面前的是数样完整无缺的物品，而且它们看起来都非常珍贵。', '一个极其结实的柜子立在你面前，柜子的门被一个内建的锁牢牢地锁着。柜子的前面有深深的划痕与刻痕，看起来好像是在无数次想要解开其中秘密的粗暴失败尝试所导致的结果。$B$B如果你想要打开这个柜子，就得先找到钥匙。', '', '去找西瘟疫之地的锁住的柜橱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5061, '水栖形态', '你已经学完了掌握水栖形态所必须具备的所有知识，现在回到达纳苏斯的玛斯雷·驭熊者那儿去吧。把坠饰拿给他看看，以此证明你已准备好接受新的知识。他会让你掌握变化为水栖形态的诀窍，让你在水中灵活自如。$B$B再见，年轻的德鲁伊。我们会再见面的。', '回到达纳苏斯，让玛斯雷·驭熊者看看你的海狮坠饰。', '真令人印象深刻，$N。你准备好学习你的水栖形态了，我很高兴能教你。$B$B还有，为了奖励你在两次考验中的成就，我给你这件物品。我希望你会发现它对你而言是一件有用的配件，可以用做自然的保护神和平衡的保卫者。', '你回到达纳苏斯并不是没有预兆的，尽管在教你学习水中形态之前，我需要你在月光林地所学课程的证据。$B$B你得到海狮的坠饰了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5062, '神圣之火', '阿利卡拉是个致命的威胁，我们必须马上将其解决。你必须点燃生命圣火，这样就可以召唤出阿利卡拉了。$B$B现在就去采集稀有的火岩龙舌兰植株。在你采集到了足够的植株后，到雷霆崖的长者高地上去找玛加萨·野性图腾。她是个具有强大力量的萨满祭司，她可以点化火岩龙舌兰来创造一种引燃圣火所需的材料。$B$B到西北面的沸腾之池去收集火岩龙舌兰吧。', '收集10支火岩龙舌兰，然后去找雷霆崖长者高地的玛加萨·野性图腾。', '好的，你收集了足够的火岩龙舌兰。这种能够点燃生命之火的草药只有在千针石林才能找到。$B$B<玛加萨开始炼化火岩龙舌兰。>', '那么说来玛加萨.图腾要对付了阿利卡拉……好吧，这真是个重大的消息。$B$B<玛加萨看了看四周。>$B$B阿利卡拉是一个危险的生物，它的诞生只是为了对那些犯了极度可恶罪行的人寻求报复。$B$B<玛加萨微笑着。>', '', '去找雷霆崖的玛加萨·野性图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5063, '血色学者之帽', '一顶你从未见过的帽子。我们熟练的工匠将使用比斯巨兽的皮制造出最漂亮华美的、每个施法者都梦寐以求的帽子！$B$B另外还需要五十个金币的制作费用和下面列出的制造材料：$B$B*比斯巨兽的皮。$B$B*磨损的憎恶缝合线。$B$B*奥术水晶。$B$B*魔化红线。', '为了制造血色学者之帽，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，5根磨损的憎恶缝合线，8块奥术水晶，5根魔化红线。$B$B另外你还必须支付50金币的制作费用。', '这真令人惊讶!你一定花了好几周时间才收集到这些东西……你是怎么找到比斯巨兽的皮的?$B$B戴上帽子吧，$N!', '除非你收集到了我要的东西，否则你就是在浪费我的时间。', '', '去冬泉谷找永望镇的玛雷弗斯·暗锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5064, '恐怖图腾的密信', '$n，你曾为我们做了不少事情，现在我要交给你一个重要的任务。恐怖图腾氏族正在策划一些神秘的行动。最近几个星期，有三个神秘的访客去过恐怖图腾氏族的营地中。我们发现他们在黑云峰放置了几只分布的箱子，里面就藏着他们的密信。$B$B$N，如果你成功地完成了这个危险的任务，我一定会好好奖励你的。', '在黑云峰拿到三封密信。', '伟大的灵魂图腾啊!这确实是个可怕的消息。我必须开始为可能发生的事情做好准备了。$B$B$N，如同我答应过的，这是给你英勇行为的回报。', '你找到恐怖图腾族到底在做什么了吗?', '', '去千针石林找乱风岗的峭壁卫兵图林·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5065, '失落的摩沙鲁石板', '那个巨魔没有对你说出真相。你为他弄来的那两块石板提到了哈卡精华，但是那个传说的内容应该还有更多才对。我已经研究很久了，而且我发现摩沙鲁石板应该总共有六块，并非两块！是六块！$B$B我恐怕其它人所掌握的那些秘密会对我们不利……$B$B找到第三块和第四块摩沙鲁石板。它们在东瘟疫之地，被居住在那里的烂苔巨魔控制着。找到它们并把它们交给我。', '把第三块和第四块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。', '你找到它们了!太好了!$B$B谢谢你，$N。我会详细地研读这些文字，并搞清楚它们的意思。$B$B然而，我还有另一项任务要交给你……', '你拿到石板了吗?我怕那些石板上所刻的文字会揭示一个对我们世界造成巨大威胁的力量。', '', '去塔纳里斯找热砂港的勘查员詹斯·铁靴。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5067, '阿卡纳护腿', '虽然历史上从来没有成功铸造这件装备的记录，但是只要有合适的环境，铸造它还是有可能的。$B$B如果奥秘的追寻者想要得到这样一件具有强大力量的护腿，他就需要以下这些材料：$B$B*比斯巨兽的皮。$B$B*磨损的憎恶缝合线。$B$B*奥金锭。$B$B*莱斯·霜语的防腐液。', '为了制造阿卡纳护腿，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，5根磨损的憎恶缝合线，5块奥金锭，5份莱斯·霜语的防腐液。$B$B另外你还必须支付50金币的制作费用。', '很少有凡人能完成这样艰巨的任务。感受一下我的手艺吧!拿好你的奖励!', '除非你收集到了我要的东西，否则你就是在浪费我的时间。', '', '去冬泉谷找永望镇的玛雷弗斯·暗锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5068, '嗜血胸甲', '据说嗜血胸甲只有一件，那是为最强的刺客迦罗娜制造的。迄今为止，是否还存在其它的嗜血胸甲仍然是个悬而未决的谜。$B$B但是！我们的工匠只要获得必要的材料就可以将它复制出来：$B$B*比斯巨兽的皮。$B$B*磨损的憎恶缝合线。$B$B*奥金锭。$B$B*暗影之皮。', '为了制造嗜血胸甲，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，10根磨损的憎恶缝合线，5块奥金锭，5块暗影之皮。$B$B另外你还必须支付50金币的制作费用。', '我曾以为我一辈子都看不到这一天。$B$B只有这样的报酬才能嘉奖你的壮举。', '除非你收集到了我要的东西，否则你就是在浪费我的时间。', '', '去冬泉谷找永望镇的玛雷弗斯·暗锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5081, '麦克斯韦尔的任务', '这条消息正好弥补了我们对黑石塔情报的不足。$B$B本次进攻具有决定性的战略意义，$N。$B$B首先，我们要消灭他们的主帅，巨魔沃恩。没有他的战斗计划，黑石兽人将陷入一片混乱之中。$B$B接下来，你必须除掉食人魔之王欧莫克。黑石塔里那些胆小如鼠的食人魔如果没有了他的指挥，就会变成一盘散沙。$B$B最后是黑石塔的核心将领维姆萨拉克。只要维姆萨拉克一死，他们的指挥中枢就会彻底瘫痪。', '到黑石塔去消灭指挥官沃恩、欧莫克大王和维姆萨拉克。', '干得漂亮，$N。至少你为我们争取了更多时间―珍贵的时间。', '情况如何?', '', '去燃烧平原摩根的岗哨找麦克斯韦尔元帅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5082, '冬泉熊怪的威胁', '我是来冬泉谷调查冰火温泉的。我注意到这里的泉水似乎有些……古怪。我暂时还没有找出问题的根源，老实说，我最近遇到一些麻烦，都是那些冬泉熊怪在作祟。$B$B它们跟我一样被吸引到了泉水附近。这些熊怪对水源的保护意识极强，不让我接近北边那两处较大的温泉。$B$B我想继续进行研究，你能帮帮我吗？', '冬泉谷的多诺瓦·雪山要你去杀死8个冬泉探路者、8个冬泉巢穴守卫和8个冬泉图腾师。', '非常感谢你，$N!现在我可以继续研究了。$B$B你在冬泉熊怪的营地里发现什么有趣的东西没有?', '感谢你的帮助!', '', '去找冬泉谷的多诺瓦·雪山。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5083, '冬泉火酒', '你从冬泉熊怪那儿拣来的这只小瓶子是空的，但是里面有一些奇怪的绿色液体，它甚至发出了微微的光芒。$B$B这会是什么重要的东西吗？$B$B多诺瓦·雪山可能会告诉你更多的信息，她在冬泉谷的温泉附近有个营地。', '将空的火酒瓶交给冬泉谷的多诺瓦·雪山。', '你是从冬泉熊怪那里得到这东西的吗?', '那是什么东西?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5085, '神秘的粘液', '锅里沸腾的绿色物质看起来与你在小瓶子中找到的东西一样。这种奇怪的粘液状的物体可能与制造它的熊怪一样，感染了严重的堕落力量……$B$B如果冬泉熊怪在使用它，那么这是否意味着它们很快就会像死木部族一样堕落？$B$B你最好赶快向多诺瓦汇报你的发现，顺便从锅里采集一点液体样本给她。', '将你的发现报告给多诺瓦·雪山。', '你非常的机警，$N。你认为冬泉熊怪到过死木营地吗?', '我希望你有些发现，$N。寒水熊变得越来越咄咄逼人了!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5086, '剧毒之水', '我研究了你取回来的样本，虽然我还无法确定，但是我相信其中包含着有毒的成分。判断这一点的唯一方法是收集其它类似的物质进行比较。$B$B我想死木熊怪也许会从费伍德森林的其它堕落生物那儿收集这些东西，尤其是生活在铁木森林中的那种被称作剧毒之水的元素生物。$B$B为我收集一些样本以进行比较，但是要小心——那里是个非常危险的地方！', '为冬泉谷的多诺瓦·雪山收集3份剧毒水滴。', '我要把这个和你在锅中发现的东西进行比较，然后我们就能获得更多资讯了。', '我想我们就快揭开谜底了，$N。', '', '去找冬泉谷的多诺瓦·雪山。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5087, '冬泉信使', '真有趣，$N……$B$B当这种有毒物质与温泉里的水混合的时候，它的毒性就消失了，对饮用者来说，它只会产生暂时的影响。这必定是冬泉熊怪如此热衷于守护温泉的原因——它们需要这些泉水来净化火酒。$B$B我们必须阻止它们——截断冬泉熊怪与死木熊怪之间的联系。有一队冬泉熊怪的信使往返于它们的村子和费伍德森林之间。找到它们，把它们的货物劫下来。', '找到冬泉信使，阻止他们向冬泉村运送物品。', '<多诺瓦检查木箱内的物品>$B$B我在想，熊怪是不是在喝下了这种东西之后就会变得更具攻击性。它们看起来真的比以前更巨大……', '让我们来看没有火水的冬泉熊怪变成什么样子吧!', '', '去找冬泉谷的多诺瓦·雪山。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5088, '阿利卡拉', '把这些提纯净化的火岩粉拿到千针石林去，并洒在生命圣火之上。那团火焰位于黑云峰的一根用于埋葬死者的石针上。$B$B我注入火岩粉中的魔法会将阿利卡拉召唤到你身旁，$N。$B$B我担心她可能在追踪凯恩·血蹄……牛头人的观念改变得太多了，而我担心这一点激怒了阿利卡拉。在事情变得无法收拾之前赶快行动吧，$c！', '杀死阿利卡拉。把她的遗体和火岩粉交给白沙岗哨的莫特加·火鬃作为证明。', '为什么会这样?为什么阿利卡拉要跟踪凯恩.血蹄?玛加萨不可能犯错，她是我们最强大的萨满。$B$B<莫特加摇了摇头。>$B$B无论如何，你对部落所做出的贡献不应被忽视―请从这些物品中挑选一件作为对你的帮助所给予的回报。', '你杀死邪恶的毒蛇阿利卡拉了吗，$N?', '点燃生命圣火', '去千针石林找白沙岗哨的莫特加·火鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5089, '达基萨斯将军的命令', '你从尸体上发现了一封看上去很重要的信：一封来自于他的上级达基萨斯将军的信，信的内容似乎跟某种协议有关。$B$B你的直觉告诉你，应该把它交给麦克斯韦尔元帅。', '把达基萨斯将军的命令交给燃烧平原的麦克斯韦尔元帅。', '这份东西意义重大……', '你有什么要给我的吗，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5092, '扫清道路', '安多哈尔城西和城北的入口防守非常严密，我正在努力从防御力较弱的东面入口寻找突破点。天灾军团以占据悔恨岭的亡灵部队所组成的第一道防线作为缓冲区，如果我们想要进攻安多哈尔的话，就必须穿过悔恨岭。$B$B你的第一个任务是清除悔恨岭一带的障碍，扫除在这一地区出没的骷髅和食尸鬼，任务完成之后就回来向我汇报！', '杀掉悔恨岭中的10个骷髅剥皮者和10个被奴役的食尸鬼。$B$B然后向西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特复命。', '任务完成了，$N!干得好，干得非常好。$B$B请允许我用暴风城提供的军饷对你表示感谢。建议你用这些钱购入一些必需的物资，这将对你的下一个任务所有帮助……下一次，你将进入安多哈尔的废墟!$B$B准备好了!时刻保持警惕!', '我希望你做好最坏的打算，$N―要深入敌军腹地。我们要完成的可不是简单的任务。在我们集结军队与天灾军团决战之前，你将作为先遣部队的一员对他们发起攻击!你在悔恨岭的任务将是我们通往胜利之路的起点!', '', '去西瘟疫之地找冰风岗的指挥官阿什拉姆·瓦罗菲斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5097, '标记哨塔', '通过使用一种被称作信号火炬的魔法物品，我们可以为军队即将展开的行动标识出目标。我们认\r\n为亡灵天灾正在将安多哈尔的哨塔作为控制军队的手段。$B$B你的任务就是突破安多哈尔的防线，将信标放置在四座哨塔中。你必须将信标放在每座哨塔的门口才行。信号火炬仅可使用五次，可别浪费了！', '使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。$B$B在做完了标记之后，将信号火炬还给西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特。', '我的牧师报告说信号追踪器接收到了来自四座哨塔的强烈信号!那么你肯定是已经成功完成了这项任务!干得好，$N!$B$B哨塔已被做上了标记，进攻的准备工作也一切就绪。与天灾军团的战争就要开始了!', '一旦那几座哨塔被做上了标记，它们就将成为我们在安多哈尔的首要攻击目标。我预计在攻占那些哨塔塔之后就要和安多哈尔城中的主力部队交锋了。那时，我们要进行一场痛快淋漓的战斗，一举夺取城市的控制权!$B$B我希望你凯旋而归，另外别忘了把信号火炬也带回来，我们可不能浪费资源。', '', '去西瘟疫之地找冰风岗的指挥官阿什拉姆·瓦罗菲斯特。', '标记第一座塔', '标记第二座塔', '标记第三座塔', '标记第四座塔');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5098, '标记哨塔', '通过使用一种被称作信号火炬的魔法物品，我们可以为军队即将展开的行动标识出目标。我们认为亡灵天灾正在将安多哈尔的哨塔作为控制军队的手段。$B$B你的任务就是突破安多哈尔的防线，将信标放置在四座哨塔中。你必须将信标放在每座哨塔的门口才行。信号火炬仅可使用五次，可别浪费了！', '使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。$B$B在做完了标记之后，将信号火炬还给西瘟疫之地亡灵壁垒的高级执行官德灵顿。', '我的术士报告说信号追踪器接收到了来自四座哨塔的强烈信号!那么你肯定是已经成功完成了这项任务，并再一次对部落做出了巨大的贡献!!干得好，$N!$B$B哨塔已被做上了标记，进攻的准备工作也一切就绪。与天灾军团的战争就要开始了!', '一旦那几座哨塔被做上了标记，它们就将成为我们在安多哈尔的首要攻击目标。我预计在攻占那些哨塔塔之后就要和安多哈尔城中的主力部队交锋了。那时，我们要进行一场痛快淋漓的战斗，一举夺取城市的控制权!$B$B我希望你凯旋而归，另外别忘了把信号火炬也带回来，我们可不能浪费资源。', '', '去提瑞斯法林地找亡灵壁垒的高级执行官德灵顿。', '标记第一座塔', '标记第二座塔', '标记第三座塔', '标记第四座塔');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5102, '达基萨斯将军之死', '我们和这些怪物正在进行双线作战：在暴风城，我们努力不让它们的魔爪深入城市；在燃烧平原，我们把战火烧到它们门前。我们必须时刻保持着警惕，$N。当它们侵占我们的领地，残害我们家人的时候，我们要把怒火全部倾泻出来。$B$B找到达基萨斯将军，然后干掉它！$B$B这个任务显然不简单，但是完成它所能得到的奖励也是相当丰厚的。', '到黑石塔去杀掉达基萨斯将军。', '当然，我们接下来就要干掉它们的龙领主。做得好，勇敢的联盟战士!做得非常好。', '任务完成了吗?', '', '去燃烧平原摩根的岗哨找麦克斯韦尔元帅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5121, '冬泉酋长', '虽然我们还不太清楚为什么熊怪会吃下这种奇怪的物质，但我们最好尽快阻止它们。$B$B冬泉熊怪并不是一个好战的部族，它们的巨大变化让我认为它们一定是在执行领袖的命令。我们无法挽回它们已经造成的损失，但是我想，如果它们的领袖被除掉的话，事态至少不会进一步恶化。$B$B快去冬泉村吧。', '冬泉谷的多诺瓦·雪山要你去击败冬泉酋长。', '非常感谢你，$N。我希望能不受干扰地继续进行我的研究。请收下这个作为报酬。', '也许你可以在冬泉谷里找到更多的线索，$N。', '', '去找冬泉谷的多诺瓦·雪山。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5122, '信仰奖章', '', '', '你找回勋章了!现在我可以离开这个教堂去继续履行我的职责了。$B$B我的职责就是去杀死那个帮助腐蚀了我和许多兄弟姐妹的野兽，瑞文戴尔男爵!', '这个小教堂给了我抵抗内心中的腐化力量。如果离开这里，我就会变成一个死亡骑士。但是有一枚勋章，信仰勋章，它可以给予我离开这里所需的力量。$B$B$N，请帮我拿回这枚勋章。它被狂热的玛洛尔看守着，他是血色十字军的一员，居住在西斯坦索姆的血色十字军堡垒深处。', '', '去找奥里克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5123, '最后一片', '你在冬泉酋长身上找到的日志看起来内容丰富，但是看完几页之后，你发现自己完全看不懂这本书。上面的符号粗糙而又拙劣——你不禁怀疑是否真的有人能读懂它们。$B$B不过，多诺瓦也许能告诉你这本书上写了些什么……', '把潦草的日志交给冬泉谷的多诺瓦·雪山。', '我在想这些东西代表了什么……我什么都看不出来……', '嗯，这是什么，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5124, '炽热板甲护手', '以索瑞森胡须的名义！$B$B你是在哪儿找到这些东西的？$B$B更重要的是，你愿意出售它们吗？我自然会付给你丰厚的酬劳。$B$B我跟你说啊，$N，要是你把这些没淬火的护手给我，我就教你如何打造自己的装备。你要做的就是为我收集这些东西，这样我就能获得精确的配方了。$B$B你觉得怎么样？$B$B这是一张我需要的东西的列表，你把护手交给我之后，其它的材料我自己搞定。', '将6块魔化瑟银锭、2份火焰精华和4颗红宝石交给玛雷弗斯·暗锤。另外你还得把未淬火的板甲护手也交给他。', '作为承诺，$N，这是你要的配方!为了表示感谢，我还会送你一件小东西，我要这些也没啥用。', '时间就是金钱，$N和我都浪费不起。', '', '去冬泉谷找永望镇的玛雷弗斯·暗锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5127, '恶魔熔炉', '罗拉克斯做生意，但他不与那些无足轻重的凡人打交道。$B$B不过，我要跟你做一笔生意……带上这支矛，它充满着恶魔的强大能量，当你找到古拉鲁克时，杀了他，然后用这支矛刺穿他的心脏。他的灵魂将被吸取，而这灵魂将为我所有。把长矛和他偷走的胸甲给我带回来，然后我就会交给你他想要学习的东西。', '到黑石塔去找到古拉鲁克。杀死他，然后用血污长矛刺入他的尸体。当他的灵魂被吸干后，这支矛就会成为穿魂长矛。$B$B你还必须找到未铸造的符文复饰胸甲。$B$B将穿魂长矛和未铸造的符文复饰胸甲都交给冬泉谷的罗拉克斯。', '你没有破坏我们的协定。我带走了灵魂。我会给你酬劳。', '别让我等得不耐烦……', '', '去冬泉谷找霜语峡谷的罗拉克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5128, '熊怪酋长的话', '冬泉熊怪对我而言已不是个威胁了，但是如果你仍然想要查出是什么驱使熊怪制造并饮用这种奇怪的火酒，那么你应该去寻求科雷克·望天的帮助。$B$B他是翡翠议会的成员，那个组织中的德鲁伊都在致力于净化和治愈费伍德森林的创伤。$B$B科雷克对费伍德森林中的熊怪非常了解，他可以告诉你更多关于这本日志的信息。$B$B再次感谢你，$N。', '将潦草的日志交给费伍德森林南部的科雷克·望天。', '嗯，如果你让我好好研究一下这个，我可能会帮你翻译出来。$B$B<科雷克翻动着书页。>$B$B等我看完它之后，我会通知你的。$B$B谢谢你把它交给我，$N。说实话，我对冬泉熊怪知之甚少。', '翡翠议会对所有的种族都非常友善，$r。我能帮你什么忙吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5141, '龙鳞制皮', '龙鳞制皮可不是件简单的工作，但是收益也非常丰厚。我可以教你如何制造这件精良的锁甲，但你得先同意我的一些条件。$B$B你选择了这条路，就必须承诺永远不会学习元素制皮技术或部族制皮技术，只能沿着这条路走下去。此外，你还必须制造一件蝎壳护甲。最后，我还要看看你是否有能力获得制造护甲所必需的材料：龙类的鳞片。', '将2套硬化蝎壳胸甲、2套硬化蝎壳手套和10片龙鳞交给艾萨拉的彼得·加林。$B$B完成这项任务之后，你就可以学到龙鳞制皮技术了。$B$B同时，你也将永远无法学习元素制皮技术和部族制皮技术，在决定之前先考虑清楚。', '我将向你传授龙鳞制皮技能，你做这样的决定一定是下了极大的勇气吧。我向你保证，掌握这种技能会给你带来丰厚的回报。$B$B要学会龙鳞制皮，你只要跟我交谈，我就会把我所掌握的知识都传授给你。', '如果你决心成为龙鳞制皮师，那么我就收下你这个学生。把我要的东西交给我，我就可以开始向你传授技能了。', '', '去艾萨拉找埃达拉斯废墟的彼得·加林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5143, '部族制皮', '要学习部族制皮技术，你就必须了解大自然最初的状态。我知道你已经掌握了制造蛮皮护甲的技术，我很乐意帮助你完成训练。$B$B要知道，$c，一旦你选择了这条路，就得承诺永远不会学习龙鳞制皮技术和元素制皮技术，你只能沿着自己选定的路走下去。此外，将你所能制造出来的最好的蛮皮护甲给我看看，然后我就可以向你传授技艺了。', '将1件蛮皮外衣和1件蛮皮头盔交给菲拉斯的凯雷希亚·猎月。$B$B完成这项任务之后，你就可以学到部族制皮技术了。$B$B同时，你也将永远无法学习元素制皮技术和龙鳞制皮技术，在决定之前先考虑清楚。', '你带来了最好的贡献，大自然会顺应你的要求。在我向你传授了部族制皮的技艺之后，你的作品将成为自然本身力量的体现。$B$B要学会部族制皮，你只要跟我交谈，我就会把我所掌握的知识都传授给你。', '在你期望学习如何利用大自然提供的材料制作皮甲之前，你必须对它有所贡献。让我看看你为大自然奉献了什么吧，它会回报你的。', '', '去找菲拉斯的凯雷希亚·猎月。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5144, '元素制皮', '我熟知元素制皮的技艺，如果你愿意敞开心扉学习更多的知识，那么我愿意与你分享我所知的一切。$B$B你要明白，$c：一旦你选择了这条道路，就必须承诺永远不学习龙鳞制皮或是部落制皮；你只能学习这三种手艺中的一种。此外，我需要你证明自己与大自然的元素有着融洽的关系，所以，你要将火、水、土和风元素最纯净的精华交给我。', '将2个火焰之心、2个纯水之球、2个大地之核和2个风之气息交给灼热峡谷的萨拉·坦尼。$B$B一旦你完成这项任务，就可以开始学习元素制皮技艺了。$B$B同时，你也就无法再学习龙鳞制皮和部落制皮了，在你决定之前要考虑清楚。', '你已经决定投身这项工作，并得到了元素的认可。在我给你传授元素制皮的技艺之后，你就可以随心所欲地制造出最好的皮甲了。$B$B在你准备好了之后来跟我谈话，然后我就将你想学的知识统统传授给你。', '制造皮甲需要耐心和热情。一旦你投身元素制皮工作，就不能退出了。让我看看你是否能胜任这项工作，然后我们就可以开始了。', '', '去找灼热峡谷制皮匠营地的萨拉·坦尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5145, '龙鳞制皮', '龙鳞制皮可不是件简单的工作，但是收益也非常丰厚。我可以教你如何制造这件精良的锁甲，但你得先同意我的一些条件。$B$B你选择了这条路，就必须承诺永远不会学习元素制皮技术或部族制皮技术，只能沿着这条路走下去。此外，你还必须制造一件蝎壳护甲。最后，我还要看看你是否有能力获得制造护甲所必需的材料：龙类的鳞片。', '将2套硬化蝎壳胸甲、2套硬化蝎壳手套和10片龙鳞交给荒芜之地的索卡夫·龙眼。$B$B完成这项任务之后，你就可以学到龙鳞制皮技术了。$B$B同时，你也将永远无法学习元素制皮技术和部族制皮技术，在决定之前先考虑清楚。', '我将向你传授龙鳞制皮技能，你做这样的决定一定是下了极大的勇气吧。我向你保证，掌握这种技能会给你带来丰厚的回报。$B$B要学会龙鳞制皮，你只要跟我交谈，我就会把我所掌握的知识都传授给你。', '如果你决心成为龙鳞制皮师，那么我就收下你这个学生。把我要的东西交给我，我就可以开始向你传授技能了。', '', '去找荒芜之地的索卡夫·龙眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5146, '元素制皮', '我熟知元素制皮的技艺，如果你愿意敞开心扉学习更多的知识，那么我愿意与你分享我所知的一切。$B$B你要明白，$c：一旦你选择了这条道路，就必须承诺永远不学习龙鳞制皮或是部落制皮；你只能学习这三种手艺中的一种。此外，我需要你证明自己与大自然的元素有着融洽的关系，所以，你要将火、水、土和风元素最纯净的精华交给我。', '将2个火焰之心、2个纯水之球、2个大地之核和2个风之气息交给阿拉希山脉的布鲁姆·白蹄。$B$B一旦你完成这项任务，就可以开始学习元素制皮技艺了。$B$B同时，你也就无法再学习龙鳞制皮和部落制皮了，在你决定之前要考虑清楚。', '你已经决定投身这项工作，并得到了元素的认可。在我给你传授元素制皮的技艺之后，你就可以随心所欲地制造出最好的皮甲了。$B$B在你准备好了之后来跟我谈一谈，然后我就将你想学的知识统统传授给你。', '制造皮甲需要耐心和热情。一旦你投身元素制皮工作，就不能退出了。让我看看你是否能胜任这项工作，然后我们就可以开始了。', '', '去阿拉希高地找博德戈尔的布鲁姆·白蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5147, '通缉：阿纳克·恐怖图腾', '通缉：阿纳克·恐怖图腾$B$B流放者阿纳克因罪大恶极的谋杀和绑架行为而被通缉。那些敢于将这名罪犯绳之以法的勇士将获得丰厚的报酬。$B$B阿纳克最后一次被发现是在黑云峰附近的悬崖上。请向乱风岗的峭壁卫兵图林·长角出示你杀死阿纳克的证明。', '杀死阿纳克·恐怖图腾，并向乱风岗的峭壁卫兵图林·长角出示证据。', '哈哈!这可真是个好消息!我起初还以为他会永远消遥法外呢!$B$B给你，$N……谢谢你。听到阿纳克邪恶的行径，我就不由得热血沸腾!', '你有什么关于阿纳克.恐怖图腾的消息吗?', '', '去千针石林找乱风岗的峭壁卫兵图林·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5148, '部族制皮', '要学习部族制皮技术，你就必须了解大自然最初的状态。我知道你已经掌握了制造蛮皮护甲的技术，我很乐意帮助你完成训练。$B$B要知道，$c，一旦你选择了这条路，就得承诺永远不会学习龙鳞制皮技术和元素制皮技术，你只能沿着自己选定的路走下去。此外，将你所能制造出来的最好的蛮皮护甲给我看看，然后我就可以向你传授技艺了。', '将1件蛮皮外衣和1件蛮皮头盔交给荆棘谷的瑟伊布。$B$B完成这项任务之后，你就可以学到部族制皮技术了。$B$B同时，你也将永远无法学习元素制皮技术和龙鳞制皮技术，在决定之前先考虑清楚。', '你带来了最好的贡献，大自然会顺应你的要求。在我向你传授了部族制皮的技艺之后，你的作品将成为自然本身力量的体现。$B$B要学会部族制皮，你只要跟我交谈，我就会把我所掌握的知识都传授给你。', '在你期望学习如何利用大自然提供的材料制作皮甲之前，你必须对它有所贡献。让我看看你为大自然奉献了什么吧，它会回报你的。', '', '去找荆棘谷的瑟伊布。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5149, '帕米拉的洋娃娃', '玛莱恩姑妈让我留在家里，因为我的爸爸出去作战了。爸爸是世界上最勇敢的人！$B$B但是我在这里等了很长时间，他一直都没有回来。有时候会有坏人来和我说话，我想让爸爸把他们赶走，但是他不在这里！$B$B有时候，天黑了以后，我会和我的洋娃娃玩，但是我把它丢在镇子里了。$B$B你能不能去帮我找到洋娃娃呢？', '找到帕米拉的洋娃娃。', '你找到它了!你找到我的洋娃娃了!哦，谢谢你!', '你找到我的洋娃娃了吗?', '', '去东瘟疫之地找达隆郡的帕米拉·雷德帕斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5150, '达丹加饿了！', '', '', '你把血瓣花苗放在达丹加前面，她看起来很满意。$B$B她推出了一个规模棕色包裹，用它来交换你给她的食品!', '当你走向达丹加的时候，她目不转睛地看着你。她似乎在希望你拿给她什么东西……$B$B她也许是饿了!$B$B也许在环形山里长着一些可以喂给这头大型食草动物的花花草草。达丹加的个头不小，不管你准备给她喂什么，数量肯定少不了!', '', '去找达丹加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5151, '超适应齿轮', '我们的商队被半人马袭击了，而我是唯一的幸存者！但是那头罕见的黑豹守护着我最完美的发明，嗯，就挂在它的脖子上。哈哈！即使是半人马也会在那头凶猛的野兽面前颤抖！$B$B这是那个笼子的钥匙。他们拿走了那里所有的东西，但是把黑豹留在了那里。把那头野兽杀了，然后拿回我的超适应齿轮，我会好好奖励你的。$B$B商队的残骸就在这里的北面。', '杀了那头野兽，把超适应齿轮和钥匙交给维兹罗。', '我的超适应齿轮!在我研究出它的功能前这可要让我忙上好一阵子……', '你拿到我的超适应齿轮了吗?', '', '去千针石林找白沙岗哨的维兹罗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5153, '古怪的历史学家', '我希望约瑟夫重新回到她女儿身边，但是这已经不可能了。他的灵魂已经属于亡灵天灾，他已经变成了一个怪物。唉，他命中注定如此！$B$B但是，也许我们能改变他的命运。$B$B在墓地外围寻找约瑟夫的墓碑。他的躯体不在那里，因为他已经在几年前灰飞烟灭了，但是在墓碑下埋着他的戒指。把戒指交给克罗米……那是个具有强大魔法力量的侏儒。$B$B克罗米在安多哈尔南墙附近的旅馆废墟中。', '把约瑟夫的结婚戒指交给安多哈尔的克罗米。', '这是什么?结婚戒指?让我看看……$B$B啊!这个戒指曾经被一个伟大的战士戴在手上，但是这个人经历了许多灾难。$B$B你来这里是要帮助他吗?现在对他来说有点太晚了\r\n……也许我们能在过去帮助他!', '你来访的时间很有意思……你不是来自未来的吧?', '', '去西瘟疫之地找安多哈尔废墟的克罗米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5154, '达隆郡的历史', '要拯救约瑟夫·雷德帕斯，我们首先得找到他的过去。安多哈尔城镇中心有一本书，名叫《达隆郡的历史》，它可以告诉我们一些重要的事情。$B$B把书拿来给我，然后我们就可以了解约瑟夫的命运，如果运气好的话……我们还能改变它！', '把《达隆郡的历史》交给安多哈尔的克罗米。', '干得好，你找到它了!$B$B你读过这本书了吗?里面提到约瑟夫.雷德帕斯了吗?如果是的话，那我们就可以拯救他!$B$B啊。《达隆镇的历史》讲述了一段令人扼腕叹息的故事。书中说约瑟夫.雷德帕斯在战斗中陷入了堕落，并且变成了天灾军团的一员!他因此而背叛了达隆郡的防卫者们。$B$B这真是个悲惨的命运。如果可能的话，我们一定要改变它，你说对吗?', '你找到书了吗，$N?', '', '去西瘟疫之地找安多哈尔废墟的克罗米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5155, '加德纳尔的势力', '如果要我完全信任你的话，你就必须先证明自己的实力。$B$B我必须确信你可以击败暗影议会。$B$B到费伍德森林的深处去，你可以在路的西边看到一条通往加德纳尔的小径。暗影议会就在那里与燃烧军团密谋着邪恶的计划。$B$B进入被腐化的兽穴，然后杀了他们的成员。当你完成任务之后再回到我这里来。这样我可以相信你是真的想要帮助我们了。', '到加德纳尔去杀掉4个加德纳尔恶犬、4个加德纳尔守护者、6个加德纳尔精兵和6个加德纳尔祭司，然后向费伍德森林的格雷塔·苔蹄复命。', '很好，$N!随着他们数量的减少，我们就可以进一步地压制他们。$B$B你觉得他们实力如何?他们是否如你所想象的那么强大?还是更强?或许他们对你来说不堪一击。你知道这意味着什么吗?$B$B我们可以晚些再讨论你的潜力，现在，我们必须解决其他的一些问题。', '你的战斗进行得怎么样了，$N?我知道把挥洒的鲜血作为荣誉的证明让有些人感到疑惑，但是你必须懂得这么做的原因:它可以让我的任务变得简单一些。另一方面，我们可以因此而互相尊重。$B$B我希望你能懂得这些。', '', '去费伍德森林找翡翠圣地的格雷塔·苔蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5156, '验证腐蚀', '在这里的北面，沿着大路向东看，你可以找到一处被称作碎痕谷的地方，那里是上次战争中燃烧军团的地狱火恶魔们的着陆点——迄今仍有许多地狱火在那里游荡。$B$B我感兴趣的有两件事情。首先，那里是否还有被污染的元素生物？其次，那些凹坑中是否还充满了堕落的恶臭之水？你能帮我去看看吗，$N？小心一些，地狱火可是会攻击它们看到的一切东西的。', '杀掉2个热能野兽和2个热能恐兽，并探索碎痕谷。然后查看凹坑中是否仍然充满了堕落的恶臭之水，完成这些任务之后，向费伍德森林中的塔诺恩·红羽复命。', '很好，你还活着，$N。糟糕的是那些堕落之水还在那里。我原本希望能在费伍德森林找到一片干净的水源，看来我的计划落空了。如果有那样的水源，治愈这片土地的工作就会简单许多。$B$B我现在不得不一边拯救那些可以被拯救的生物，一边消灭那些已经无可救药的生物，它们对于进入这片森林的旅人是一种威胁。', '我希望你的搜索进行得很顺利，$N。我还没有准备启程去森林北部，但是我必须承认，穿越一片到处都是炼狱火的区域让我感到有些害怕。那些生物没有思想，但仍然非常具有威胁性。', '探索碎痕谷', '去费伍德森林找翡翠圣地的塔诺恩·红羽。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5157, '收集堕落之水', '在加德纳尔深处有一座暗影堡，那里是堕落和邪恶的主要源头。$B$B暗影议会使用几座火盆制造防护结界，将他们的巢穴保护了起来。$B$B如果我想要通过占卜来获得更多有关他们的情报，那你首先要想办法熄灭那些火盆，然后我就可以侦测暗影议会并找到究竟是谁在领导他们了。$B$B如果你愿意帮忙的话，拿着这只水壶，用它在加德纳尔中心的月亮井中装满水，然后回到我这里来。', '把空壶拿到加德纳尔中心的月亮井去，装满井水之后再回到费伍德森林的格雷塔·苔蹄那里。', '干得很好，$N。$B$B现在我们要做的就是净化这些水，然后用它熄灭火盆。这并不困难─只需要跑跑路就可以了。$B$B我希望我们可以尽快完成这件事。', '一旦我们有了月井的水，就可以对其进行净化，然后用它来熄灭保护暗影堡的火盆。这样我就有充足的时间来侦测他们的老巢，并搞清楚是谁在领导着他们……$B$B我希望大地之母能与我们同在。', '', '去费伍德森林找翡翠圣地的格雷塔·苔蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5158, '水之魂的帮助', '把腐化的月亮井水拿到贫瘠之地去，$N。棘齿城南面的海岸边上住着我的一个老朋友，水之先知伊斯伦。她是个强大的萨满祭司，并且愿意帮助我们。她和水之魂的关系不错，我们高尚的目标一定可以让她和水之魂出手帮助我们。$B$B你可以在水边的一个小帐篷中找到她。另外，$N，不要管那些海盗……他们对你完全不构成威胁。', '把腐化的月亮井水交给贫瘠之地的水之先知伊斯伦。', '啊，你需要净化这瓶月井里的水。阻止费伍德森林的堕落力量，这听起来很高尚，但是我无法决定是否要净化这瓶水。我会询问水之灵─它们将决定是否对其进行净化。$B$B给我点时间，我会把你的理由告诉它们。我希望它们也像我一样具有同情心。', '我感觉你不是个找路去棘齿城的旅人。过来，在我们的帐篷里休息一下，当你准备好了就和我说说吧。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5159, '净化过的水', '感谢水之魂，$N。它们答应帮助你了。$B$B现在我就把这瓶净化好的水交给你。代我向格雷塔问好，她正在做的事情比我们大多数人所做的事情都要伟大……我确信不久之后她也会发现这一点的。$B$B不要小看暗影议会的力量，$N。记住这一点。$B$B现在就出发吧，把水交给格雷塔。', '把净化过的月亮井水交给费伍德森林的格雷塔·苔蹄。', '这些水足够了。$B$B我很高兴听说伊斯伦愿意帮助我们。她和水之灵的力量非常强大，而且她总是如此睿智，所以水之灵很少否决她的意见。他们都同意我的看法，这让我觉得我们确实做对了。', '啊，你回来了，$N。很好。你在贫瘠之地找到水之先知伊斯伦了吗?如果没有的话，那我们就得另想办法来达成目标了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5160, '监护者', '到卡利姆多去，$r。我们蓝龙军团在寒冷的冬泉谷定居。在你到达冬泉谷之后，就去寻找麦索瑞尔洞穴。$B$B在麦索瑞尔的冰冷的地板上，你将会找到钴蓝色的符文。拿着我的鳞片站在某个符文上，你就会被传送到哈尔琳身边, 她是我们的监护者。$B$B把鳞片交给她，让她用水晶球占卜一下我在这个可怕的地方所看到和感觉到的是什么。', '到冬泉谷去找到哈尔琳，把奥比的鳞片交给她。', '守护巨龙坚持认为我们应该远离凡人的俗事。然而，在这个世界上，这是不太可能的―尤其当我们中的一些成员对这种律令熟视无睹的时候。', '见到你很高兴，$N。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5163, '雪怪计划！', '搞定！$B$B现在，我已经给我的朋友们发信了，说是我有个惊喜要给他们看看。这就是你要做的事情！$B$B我要把机械雪人给你，然后你就去访问我所有的朋友并给他们一个惊喜，启动机械雪人，然后让他们大开眼界！$B$B让永望镇的莱加奇、加基森的斯普琳科，还有马绍尔营地的奎克希尔看看它，然后回来告诉我他们有什么反应！$B$B别忘了把我的雪人也带回来。', '带着乌米的机械雪人去吓唬她的朋友：$B$B永望镇的莱加奇（冬泉谷）、加基森的斯普琳科（塔纳利斯），还有马绍尔营地的奎克希尔（安戈洛环形山）。$B$B当你完成任务之后，把机械雪人还给乌米。', '哈哈!以后他们再想取笑我的主意时，就得先考虑一下了!$B$B感谢你的帮助，$N。如果没有你的帮助，我可找不到那么多乐子!', '真想知道我的朋友会有什么反应!$B$B他们绝对会被吓一大跳的!', '', '去冬泉谷找永望镇的乌米。', '吓唬莱加奇', '吓唬斯普琳科', '吓唬奎克希尔', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5165, '熄灭火焰', '现在，你必须回到加德纳尔去。那些火盆分布在暗影堡中，熄灭它们的火焰，这样保护暗影议会的屏障就会消失一段时间——我正在等待着那个时刻的到来。如果你成功了，我就会仔细查看暗影堡，然后找出他们的头目。然后，我们将决定是否发起正面攻击。', '使用净化过的月亮井水熄灭暗影堡内部的四座火盆的火焰，从而破除其保护效果，然后向翡翠圣地的格雷塔·苔蹄复命。', '在最后一个火盆熄灭的同时，我就看到了你。干得好，$N。$B$B在暗影议会的术士重新施展他们的保护法术之前，我了解到了不少东西，这些情报应该够用了。$B$B至于现在，好好休息一下吧。我很快就会告诉你我看到了什么东西。', '如果我们想要发动一场大战的话，那些火盆就必须被熄灭。毫无准备地闯入暗影堡无异于找死。现在我们所面对的敌人甚至比一条龙还要危险─暗影议会犯下了无数滔天的罪行。如果我们要阻止他们的话，就必须快点行动了。', '', '去费伍德森林找翡翠圣地的格雷塔·苔蹄。', '熄灭痛苦火盆', '熄灭怨意火盆', '熄灭受难火盆', '熄灭仇恨火盆');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5166, '多彩巨龙胸甲', '铸造一件足以抵御彩色巨龙冷酷攻击的胸甲，就必须使用最坚硬的材料。$B$B我们需要把成年彩色巨龙的多彩龙鳞和那些被我们击败的凶残的野兽的外皮缝合在一起。这些东西的存在并不为人所知，愿它们永不存在于这个世界。$B$B另外，最难以得到的东西就是英雄之血。$B$B雕刻者将会为你完成铸造。', '为了铸造多彩巨龙胸甲，你必须把以下材料交给雕刻者耶兹巴：$B$B1块多彩龙鳞。$B$B10块闪亮的彩色龙鳞。$B$B10份英雄之血。$B$B10块磨损的憎恶缝合线。', '你还没有理解吗?这次旅程本身就是你的终点。你感觉不到战争留下的伤痕吗?你所经受的痛苦呢?$B$B你幸存了下来，并且变得更加强大，这件胸甲只是你能力的微不足道的体现。', '你做出了明智的选择，$r。', '', '去西瘟疫之地找安多哈尔废墟的耶兹巴。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5167, '多彩挑战者腿甲', '成年彩色巨龙的外壳是制造护腿的基础。彩色龙鳞将被用于制作镶边，最后在英雄之血中进行洗礼。最后，暗影之皮的力量将被注入护腿中。', '为了铸造多彩挑战者腿甲，你必须把以下材料交给雕刻者耶兹巴：$B$B1块多彩龙鳞。$B$B10块闪亮的彩色龙鳞。$B$B10份英雄之血。$B$B5块暗影之皮。', '他们会在你出现的时候闻到同类的味道，$N。以他们自己的恐惧为武器击溃他们吧!', '这样一件东西以前从未被铸造出来过!', '', '去西瘟疫之地找安多哈尔废墟的耶兹巴。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5168, '达隆郡的英雄', '我永远铭记着达隆郡的英雄，你带给我的这本《达隆镇的历史》中就讲述了他们的故事。$B$B书中提到了圣骑士达维·莱法尔，还提到了血色十字军把他的圣契放在壁炉谷的城镇大厅中。$B$B书中还提到了我的兄弟，雷德帕斯队长。在他叛变之后，他的盾牌被击碎并抛弃了，它就被扔在一个看起来最不可思议的地方——靠近盖罗恩农场的谷仓那里。$B$B收集那些被命运和悲剧笼罩的遗物，$N。', '把达维的圣契和雷德帕斯之盾交给卡林·雷德帕斯。', '你找到盾牌和圣契了!$B$B它们的历史和达隆郡的历史交织在一起，我知道命运会让它们重聚的。', '你找到那些圣物了吗，$N?', '', '去东瘟疫之地找圣光之愿礼拜堂的卡林·雷德帕斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5181, '达隆郡的恶魔', '《达隆郡的历史》讲述了那场战役中的几个天灾军团头目。联盟在这场战役中杀死了食尸鬼之王，掠夺者霍古斯。他的尸体被扔到考林路口西北面的湖泊中，现在他的徽记还在那儿呢。$B$B黑衣玛杜克从未吃过败仗，但是他的剑却被击落，留在了考林路口西面的山谷底部。$B$B去找回徽记和宝剑吧，$N。我不清楚原因，但是我知道它们的命运是跟你有关联的。', '将霍古斯的徽记和马杜克的破碎之剑交给圣光之愿礼拜堂的卡林·雷德帕斯。', '你找到了!干得好，$N!这些圣物拥有我所不熟悉的力量，终有一天你会用到这种力量。$B$B它们也给我带来了黑色的回忆……死亡和背叛，还有达隆郡的最后一夜。', '你找到头颅和宝剑了吗，$N?', '', '去东瘟疫之地找圣光之愿礼拜堂的卡林·雷德帕斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5201, '冬泉熊怪的侵扰', '大多数人都不知道我在这里，$N。但是，在冬泉谷有个许久以来挥之不去的大麻烦：冬泉熊怪。$B$B我可从来没有直接跟熊怪发生过冲突，它们极度癫狂，对面前的一切事物都毫不畏惧。我曾看到熊怪残杀无数生物，而这些不幸的生物惨遭杀戮的原因无非是挡了熊怪的路。$B$B我对它们的胡作非为感到厌烦——请帮帮我，代替月神惩罚它们吧。杀死熊怪，让它们永远也不敢侵入霜刀石！', '雷沃·霜翼要你去杀死5个冬泉萨满祭司和5个冬泉巨熊怪。', '很快，我们就无须再为冬泉熊怪的侵扰而烦恼了。$B$B你有着百折不挠的精神，$N。', '熊怪们似乎患上了妄想症……', '', '去冬泉谷找霜刀石的雷沃·霜翼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5202, '奇怪的红钥匙', '这把红色的小钥匙似乎是由某种骨头制成的。它非常沉重，但是看上去却非常脆弱。为什么暗影议会的成员会拿着这样的东西呢？或许在加德纳尔内部有什么东西可以用这把奇怪的钥匙打开。', '搜寻加德纳尔，找出血红钥匙的用途。', '钥匙，你找到它了!请把它给我，这样我就可以脱身了!', '我不禁开始怀疑我是否能逃离这只牢笼。$B$B他们迟早会把我献祭给他们所崇拜的恶魔。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5203, '逃出加德纳尔', '虽然我承受了很大的痛苦，但是有件事情我们必须先做好：我要找到特雷·莱弗治，然后从暗影堡逃出去，把这里所发生的一切都报告给我们的上司。你能帮我吗，$N？$B$B我的装备就在离这里不远的地方，而且你已经证明了你的实力。$B$B在我们逃脱之后，我会去达纳苏斯，请你到灰谷的边界地带去找到杰希尔。她应该在那里的翡翠议会营地中。$B$B你认为怎么样，$n？你能再帮我一次吗？', '护送亚科纳琳到莱弗治和她的装备所在的地方，然后保护她逃离暗影堡。之后，在费伍德森林找杰希尔·月弓，并告诉她刚才发生的事情。', '你帮助亚科逃了出来?很高兴你找到我了。她不久之前来过我这里，然后就去达纳苏斯了。她之前是和莱弗治在一起，当时都来不及让德鲁伊进行治疗。她说当时情况太紧急了。$B$B但是她确实告诉我你遇到了特雷的灵魂。白银之手的骑士遇到了多么恐怖的命运。她没有具体说那件事情，但是我知道这让她承受了很大的痛苦，因为她失去了她最好的朋友之一。$B', '你看起来气喘吁吁的，$N。你还好吗?', '保护亚科纳琳逃出暗影堡', '去费伍德森林找翡翠圣地的杰希尔·月弓。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5204, '光明的惩戒', '她假装自己没事。她希望我认为她有足够坚强，可以独自承担所有的悲伤，这一点我很清楚。特雷的死和他被折磨时发出的惨叫会让她在很长一段时间里都被痛苦煎熬，我们对此无能为力。但是我们至少可以给她一些安慰！$B$B$N，回到暗影堡去，杀了折磨特雷的混蛋，并找回他的遗体。在亚科纳琳默默承受痛苦的时候，我们可不能留在这里什么事情都不做。', '回到加德纳尔杀了魅魔拉凯雅，然后找到特雷·莱弗治的残骸。', '你小心翼翼地敛起圣骑士的遗体，至少他的灵魂已经得到解脱，不再会感受到他生前所遭受的痛苦和折磨了。$B', '你检查了那具尸体，毫无疑问，这就是白银之手骑士团的特雷·莱弗治的遗体了。你想起了亚科纳琳，并想起了这位圣骑士的死对她所造成的打击。$B$B过了一会儿，你重新收回了思绪。你很清楚，在没有杀死折磨这个圣骑士的恶徒之前，你是无法把他的遗体带回杰希尔那里的。', '', '去费伍德森林找加德纳尔的特雷·莱弗治的残骸。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5206, '达隆郡的掠夺者', '克罗米说你所收集的那些遗物是施放一个强大的法术所必需的材料，此外还需要一样东西：参加达隆郡战役的天灾军团士兵的徽记。$B$B带着这块水晶去猎杀天灾军团的士兵，并拿到他们的徽记。这块水晶已经被施了魔法，如果某个士兵曾参加过那场战斗，那么当你把水晶球放在他的徽记上时，它就会发出共鸣。把那些可以与水晶共鸣的徽记交给我。$B$B快去，$N。你可以在北方的剧毒林地和西方的蘑菇林中找到亡灵天灾的士兵。', '把5个共鸣徽记和神秘水晶交给东瘟疫之地的卡林·雷德帕斯。', '你成功了!太好了!$B$B尽管我不太明白这些东西如何能帮助我们，但我仍可以感觉到它们的力量，而且我能感觉到……它们和我的故乡达隆郡息息相关。', '你拿到头骨了吗?克罗米说那些东西对她的法术至关重要，而那个法术会给我们带来拯救达隆郡的机会。', '', '去东瘟疫之地找圣光之愿礼拜堂的卡林·雷德帕斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5210, '卡林·雷德帕斯', '借助我的魔法，《达隆郡的历史》被增补了，现在它所记述的历史已近包括战争之后的事情了。新增的章节里有一部分讲述了另一个雷德帕斯系列成员的下落，他在约瑟夫叛变后侥幸活了下来。卡林·雷德帕斯在东瘟疫之地的圣光之愿礼拜堂里。$B$B拿着这本书去找他吧。', '将《达隆镇全史》交给东瘟疫之地的卡林·雷德帕斯。', '这是本什么书?达隆镇的历史?那是我的家……直到那场战斗彻底毁灭了它!你为什么把这本书拿来给我?$B$B什么?书中竟然有一部分讲述的是战后的故事!有一章是讲我的!还有一章是讲我兄弟约瑟夫的!这本书所说的事情都是真的吗?$B$B我们必须查明真相!', '你从西边来的?洛丹伦的其它人怎么样了?我知道安多哈尔已经陷落了，但是天灾军团到达美丽的提里斯法了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5211, '达隆郡的保卫者', '许多保卫者在达隆郡的战役中倒下了，而他们中的许多人又变成了天灾军团的爪牙！找到这些可怜的灵魂，结束他们的痛苦！$B$B去猎杀吃人的食尸鬼、喋喋不休的食尸鬼和生病的剥皮者。他们以前都是达隆郡的善良居民，毁灭他们的肉体将会使他们的灵魂得到自由。$B$B你可以在病木林、考林的十字路口，还有东瘟疫之地的其它天灾军团的据点里找到他们。', '释放15个达隆郡居民的灵魂，然后返回卡林·雷德帕斯身边。', '听到你找到那些备受折磨的灵魂并释放了他们，这真是个好消息。我的心可以得到些许安慰，至少我知道一部分达隆郡的防卫者不会再可耻地为天灾军团效力了。', '达隆郡的防卫者们在我的梦中向我哭喊，$N。你必须释放他们!', '', '去东瘟疫之地找圣光之愿礼拜堂的卡林·雷德帕斯。', '解放达隆郡的灵魂', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5212, '血肉不会撒谎', '被遗忘者的药剂师并不是这个世界上唯一接受过科学教育的学者。$B$B我已经研究这场瘟疫好多年了，$c。我们以前曾认为瘟疫的力量正在衰减，但是我在瘟疫之地的研究成果却令人吃惊。瘟疫的力量似乎仍在增长！$B$B我需要进行更多的试验！最有潜质的瘟疫源泉就是那些最近感染瘟疫的躯体。到斯坦索姆去给我带回一些标本来，$N。', '从斯坦索姆找回10个瘟疫肉块，并把它们交给贝蒂娜·比格辛克。你觉得斯坦索姆中的生灵都不大可能长着肉……', '瘟疫中的活性成分发生了某些变化。我们还需要更多的资料。', '有些人说我担心太多了，我对他们说，“是你们太掉以轻心了!”', '', '去东瘟疫之地找圣光之愿礼拜堂的贝蒂娜·比格辛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5213, '活跃的探子', '你必须更加深入斯坦索姆，$N。$B$B穿过第一道门之后，你就可以看到巨大的通灵塔。我们知道亡灵天灾正在源源不断地从这些建筑物中汲取力量。搜索通灵塔，并把你找到的任何有价值的情报带回来。', '到斯坦索姆去探索那里的通灵塔。找到新的天灾军团档案，把它交给贝蒂娜·比格辛克。', '真令人惊讶!我必须花费好几个月的时间来对它进行解剖和分析。银色黎明感谢你所做的努力，$N。$B$B带着我们的祝福，在黎明圣印与黎明符文中做出选择。不管选择哪一个，他们都拥有银色黎明委任徽章搜集天灾石的效果。若你的遗失了，与我交谈就能得到一个新的。', '我们就快要揭开这种新的活性瘟疫的秘密了!', '', '去东瘟疫之地找圣光之愿礼拜堂的贝蒂娜·比格辛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5214, '弗拉斯·希亚比', '可怕的事情……弗拉斯。你知道，城镇被毁灭了，而弗拉斯不想离开他那珍贵的货物。我还记得他说的最后一句话：“我要在他们该死的脏手碰到我的烟叶之前把所有东西都烧光！”$B$B我可能比较贪财，但我不是傻瓜，于是我离开了弗拉斯和他的商店。我觉得他应该是已经被烧死了，但是如果……万一他的名牌烟草还有一部分没有被烧毁……$B$B你怎么说，$N？去帮烟鬼找包烟吧？', '找到弗拉斯·希亚比在斯坦索姆的烟草店，并从中找回一盒希亚比的烟草，把它交给烟鬼拉鲁恩。', '哦，亲爱的香烟，我多么想念你啊……', '我受不了了，$N!你必须帮帮我!我要死了!', '', '去东瘟疫之地找圣光之愿礼拜堂的烟鬼拉鲁恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5216, '目标：费尔斯通农场', '在西瘟疫之地的四口瘟疫之锅中，费尔斯通农场里的那一口可能是最容易进入的了。亡灵天灾在那边驻扎的都是新兵，尽管他们也不是轻易可以击败的对手，但相对来说毕竟容易一些。$B$B到费尔斯通农场去，它就在这里的正东方，安多哈尔的西北方，并与那里的护锅者交战。它身上有一把可以打开瘟疫之锅的钥匙。当你开启那口锅之后，用这个瓶子装满锅里的毒药样品，我们要对它进行研究以制造出一种解药。', '到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。', '你轻松地将从护锅领主拜尔摩那里拿来的钥匙插进控制板里，但是随即它就消失了。尽管如此，你却已经可以不用钥匙就打开控制板了。随着一种未知的浓缩混合剂在瘟疫之锅中翻腾，腐烂的恶臭气息从打开的控制板里散发了出来。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为冰风岗的高阶牧师玛多妮尔带回一份样品。', '瘟疫之锅的控制板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。', '', '去西瘟疫之地的费尔斯通农场解锁天灾之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5217, '返回冰风岗', '你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。$B$B现在你应该带着毒药回到冰风岗的高阶牧师玛多妮尔那里去了。', '把费尔斯通农场的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。', '干得好，$N。炼金师阿尔比顿不用费什么工夫就可以对这东西进行分析，然后制造出可以中和瘟疫的药剂。如果能把足够的解药散播到空气中，我们就有可能削弱这个地区的天灾军团。$B$B毫无疑问，这是一场持久而严酷的考验，我们需要不断的攻击这些瘟疫之锅，把我们的药剂倒入锅中。只要我们能坚持下去，在全面的战争开始的那一天，我们就会对天灾军团占有压倒性的优势!', '欢迎回到相对来说还算安全的冰风营地，$N。你在瘟疫之锅那边有什么进展要汇报吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5218, '费尔斯通农场的瘟疫之锅', '', '', '你把药剂倒入了锅中的混合物中，不断喷涌的水汽的颜色和成分很快就发生了变化。面对大量散入空气中的新物质，即使是那些离锅炉较远的天灾军团爪牙也显出了畏惧之色。', '天灾军团的瘟疫大锅就伫立在你面前，它将大量的毒素喷洒到空气中。在锅炉的巨大平台下，有一条细长的管道。$B$B你已经击败了护锅领主并获得了这口锅的钥匙，可以随心所欲地向锅内添加适当的药剂来抵消瘟疫的效果了。', '', '去找西瘟疫之地的天灾之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5219, '目标：达尔松之泪', '有一口瘟疫之锅被放置在一座早已废弃的农场上，现在这里被称为达尔松之泪。不过现在我们没时间掉眼泪，$c。我们必须打开这口瘟疫之锅！$B$B到安多哈尔正北方的达尔松之泪去，消灭那里的护锅者。像上次一样，护锅者身上应该有一把可以打开瘟疫之锅的钥匙。用这个瓶子从锅里装一份样品拿回来，每口锅所使用的毒素配方都是截然不同的。', '到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带达尔松之泪的空瓶来采集瘟疫之锅中的毒药样本。', '从护锅领主身上找到的钥匙很容易地滑入锁孔并随即消失，而瘟疫之锅的控制板也一下子打开了，粘稠的腐液在瘟疫之锅里涌动沸腾。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为冰风岗的高阶牧师玛多妮尔带回一份样品。', '瘟疫之锅的控制板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。', '', '去找西瘟疫之地的天灾之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5220, '返回冰风岗', '你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。$B$B现在你应该带着毒药回到冰风岗的高阶牧师玛多妮尔那里去了。', '把达尔松之泪的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。', '啊，这些对研究来说已经足够了。干得好，$N!$B$B现在，事态已经在我们的掌握中了。我们需要制造一系列试剂，当这些试剂与瘟疫之锅中已有的物质结合之后，那些原有的毒素就会被中和。$B$B我们只有把解药直接倒进瘟疫之锅里才能达到这种效果。炼金师阿尔比顿对这类事情有更深的了解，所以你最好尽快找他谈话。', '我们知道每一口瘟疫之锅都使用不同的药剂来产生毒素，同样，我们也知道我们必须针对各个瘟疫之锅中的毒素研制出相应的解药。你从达尔松之泪取得的样品是我们解决那里的瘟疫之锅的关键。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5221, '达尔松之泪的瘟疫之锅', '', '', '你把药剂倒入了锅中的混合物中，不断喷涌的水汽的颜色和成分很快就发生了变化。面对大量散入空气中的新物质，即使是那些离锅炉较远的天灾军团爪牙也显出了畏惧之色。', '天灾军团的瘟疫大锅就伫立在你面前，它将大量的毒素喷洒到空气中。在锅炉的巨大平台下，有一条细长的管道。$B$B你已经击败了护锅领主并获得了这口锅的钥匙，可以随心所欲地向锅内添加适当的药剂来抵消瘟疫的效果了。', '', '去找西瘟疫之地的天灾之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5222, '目标：嚎哭鬼屋', '已经有两口瘟疫之锅被成功打开了，虽然并不确定你能否继续前进，但我们仍然想要打开剩下的两口瘟疫之锅。这可以让我们的解药发挥更大的效果！$B$B这次你的目标是嚎哭鬼屋的瘟疫之锅。那个地方在安多哈尔正东边，相对来说比较靠近被毁坏的城墙。和以前一样，消灭那里的护锅者，拿到它的钥匙。用这只瓶子从锅里取得样品。$B$B祝一切顺利，$N！', '到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带嚎哭鬼屋的空瓶来采集瘟疫之锅中的毒药样本。', '护锅领主的钥匙打开了这口锅的控制板，然后就消失了―与前两口瘟疫之锅的钥匙一样。一种带着腐烂气息的物质在锅里剧烈地翻滚着。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为亡灵壁垒的暗影牧师范蒂丝带回一份样品。', '瘟疫之锅的控制板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。', '', '去西瘟疫之地解锁达隆米尔湖的天灾之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5223, '返回冰风岗', '你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。$B$B现在你应该带着毒药回到冰风岗的高阶牧师玛多妮尔那里去了。', '把嚎哭鬼屋的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。', '干得漂亮，$N!我们现在可以用这三口瘟疫之锅来对付天灾军团了。如果克尔苏加德对这些地方的控制力不像现在这样强大的话，我敢说你已经把它们全都关掉了!$B$B炼金师阿尔比顿将对中和这口锅中的毒素的问题进行研究。现在，控制西瘟疫之地的最后一口瘟疫之锅的时机终于到来了!', '一旦我们成功地分析了从苦痛鬼屋的瘟疫之锅里取得的样品，就可以再研制出一种能有效对抗天灾军团的药剂了!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5224, '嚎哭鬼屋的瘟疫之锅', '', '', '你把药剂倒入了锅中的混合物中，不断喷涌的水汽的颜色和成分很快就发生了变化。面对大量散入空气中的新物质，即使是那些离锅炉较远的天灾军团爪牙也显出了畏惧之色。', '天灾军团的瘟疫大锅就伫立在你面前，它将大量的毒素喷洒到空气中。在锅炉的巨大平台下，有一条细长的管道。$B$B你已经击败了护锅领主并获得了这口锅的钥匙，可以随心所欲地向锅内添加适当的药剂来抵消瘟疫的效果了。', '', '去西瘟疫之地找天灾之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5225, '目标：盖罗恩农场', '最后的一口瘟疫之锅在一个被称作盖罗恩农场的地方，由亡灵天灾中较为强大的爪牙守卫着——那里的鬼魂和幽灵尤其危险。你可不能掉以轻心，$N。$B$B盖罗恩农场在这里的东北方向，靠近东瘟疫之地的边界。和以前一样，消灭那里的护锅者以获取他的钥匙。拿着这个空样品瓶，把它装满给我拿回来。愿圣光护佑你平安完成这次危险的任务，$c。', '到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。', '护锅领主索瓦斯的钥匙碰到瘟疫之锅平台底部控制板上的锁之后就消散了。一声轻轻的叮当声过后，控制板打开了，展现在你面前的是瘟疫之锅里沸腾着的毒素。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为亡灵壁垒的暗影牧师范蒂丝带回一份样品。', '瘟疫之锅的控制板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。', '', '检查西瘟疫之地盖罗恩农场的天灾之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5226, '返回冰风岗', '你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。$B$B现在你应该带着毒药回到冰风岗的高阶牧师玛多妮尔那里去了。', '把盖罗恩农场的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。', '恭喜你，$N，你已经为我们打开了最后一口瘟疫之锅!炼金师阿尔比顿将很快找到中和这口锅中的毒素所需的试剂。$B$B至于你，我敢肯定瓦罗菲斯特指挥官会亲自向你表示感谢。没有你，我们反抗天灾军团的斗争决不会有这么大的进展。谢谢你，英雄!', '盖罗恩农场的瘟疫之锅是我们在东部的最后一个目标。只要我们得到锅中的瘟疫样本，我们就可以通过这四口锅把我们的解药散播到空气中!即使有克尔苏加德的支持，天灾军团也很难兼顾四口瘟疫之锅。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5227, '盖罗恩农场的瘟疫之锅', '', '', '你把药剂倒入了锅中的混合物中，不断喷涌的水汽的颜色和成分很快就发生了变化。面对大量散入空气中的新物质，即使是那些离锅炉较远的天灾军团爪牙也显出了畏惧之色。', '天灾军团的瘟疫大锅就伫立在你面前，它将大量的毒素喷洒到空气中。在锅炉的巨大平台下，有一条细长的管道。$B$B你已经击败了护锅领主并获得了这口锅的钥匙，可以随心所欲地向锅内添加适当的药剂来抵消瘟疫的效果了。', '', '去找西瘟疫之地的天灾之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5229, '目标：费尔斯通农场', '在西瘟疫之地的四口瘟疫之锅中，费尔斯通农场里的那一口可能是最容易进入的了。亡灵天灾在那边驻扎的都是新兵，尽管他们也不是轻易可以击败的对手，但相对来说毕竟容易一些。$B$B到费尔斯通农场去，它就在这里的正东方，安多哈尔的西北方，并与那里的护锅者交战。它身上有一把可以打开瘟疫之锅的钥匙。当你开启那口锅之后，用这个瓶子装满锅里的毒药样品，我们要对它进行研究以制造出一种解药。', '到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。', '你轻松地将从护锅领主拜尔摩那里拿来的钥匙插进控制板里，但是随即它就消失了。尽管如此，你却已经可以不用钥匙就打开控制板了。随着一种未知的浓缩混合剂在瘟疫之锅中翻腾，腐烂的恶臭气息从打开的控制板里散发了出来。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为冰风岗的高阶牧师玛多妮尔带回一份样品。', '瘟疫之锅的控制板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。', '', '去西瘟疫之地的费尔斯通农场解锁天灾之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5230, '返回亡灵壁垒', '你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。$B$B现在你应该带着毒药回到亡灵壁垒的暗影牧师范蒂丝那里去了。', '把费尔斯通农场的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。', '干得好，$N。迪瑟斯不用费什么工夫就可以对这东西进行分析，然后制造出可以中和瘟疫的药剂。如果能把足够的解药散播到空气中，我们就有可能削弱这个地区的天灾军团。$B$B毫无疑问，这是一场持久而严酷的考验，我们需要不断的攻击这些瘟疫之锅，把我们的药剂倒入锅中。只要我们能坚持下去，在全面的战争开始的那一天，我们就会对天灾军团占有压倒性的优势!', '欢迎回到相对来说还算安全的亡灵壁垒，$N。你在瘟疫之锅那边有什么进展要汇报吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5231, '目标：达尔松之泪', '有一口瘟疫之锅被放置在一座早已废弃的农场上，现在这里被称为达尔松之泪。不过现在我们没时间掉眼泪，$c。我们必须打开这口瘟疫之锅！$B$B到安多哈尔正北方的达尔松之泪去，消灭那里的护锅者。像上次一样，护锅者身上应该有一把可以打开瘟疫之锅的钥匙。用这个瓶子从锅里装一份样品拿回来，每口锅所使用的毒素配方都是截然不同的。', '到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带达尔松之泪的空瓶来采集瘟疫之锅中的毒药样本。', '从护锅领主身上找到的钥匙很容易地滑入锁孔并随即消失，而瘟疫之锅的控制板也一下子打开了，粘稠的腐液在瘟疫之锅里涌动沸腾。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为冰风岗的高阶牧师玛多妮尔带回一份样品。', '瘟疫之锅的控制板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。', '', '去西瘟疫之地解锁天灾之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5232, '返回亡灵壁垒', '你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。$B$B现在你应该带着毒药回到亡灵壁垒的暗影牧师范蒂丝那里去了。', '把装满的达尔松眼泪之瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。', '啊，这些对研究来说已经足够了。干得好，$N!$B$B现在，事态已经在我们的掌握中了。我们需要制造一系列试剂，当这些试剂与瘟疫之锅中已有的物质结合之后，那些原有的毒素就会被中和。$B$B我们只有把解药直接倒进瘟疫之锅里才能达到这种效果。迪瑟斯对这类事情有更深的了解，所以你最好尽快找他谈一谈。', '我们知道每一口瘟疫之锅都使用不同的药剂来产生毒素，同样，我们也知道我们必须针对各个瘟疫之锅中的毒素研制出相应的解药。你从达尔松之泪取得的样品是我们解决那里的瘟疫之锅的关键。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5233, '目标：嚎哭鬼屋', '已经有两口瘟疫之锅被成功打开了，虽然并不确定你能否继续前进，但我们仍然想要打开剩下的两口瘟疫之锅。这可以让我们的解药发挥更大的效果！$B$B这次你的目标是嚎哭鬼屋的瘟疫之锅。那个地方在安多哈尔正东边，相对来说比较靠近被毁坏的城墙。和以前一样，消灭那里的护锅者，拿到它的钥匙。用这只瓶子从锅里取得样品。$B$B祝一切顺利，$N！', '到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带嚎哭鬼屋的空瓶来采集瘟疫之锅中的毒药样本。', '护锅领主的钥匙打开了这口锅的控制板，然后就消失了―与前两口瘟疫之锅的钥匙一样。一种带着腐烂气息的物质在锅里剧烈地翻滚着。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为亡灵壁垒的暗影牧师范蒂丝带回一份样品。', '瘟疫之锅的控制板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。', '', '去西瘟疫之地解锁达隆米尔湖的天灾之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5234, '返回亡灵壁垒', '你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。$B$B现在你应该带着毒药回到亡灵壁垒的暗影牧师范蒂丝那里去了。', '把嚎哭鬼屋的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。', '又一个完美的任务，$N!我们现在可以用这三口瘟疫之锅来对付天灾军团了。如果克尔苏加德对这些地方的控制力不是像现在这么强大的话，我敢说你已经可以把它们全都结束掉了!$B$B药剂师迪瑟斯将会对如何利用这几个锅子的东西研发瘟疫疫苗的方式提出报告。等到疫苗出来，控制西瘟疫之地的最后一口瘟疫之锅的时机就会到来了!', '只要我们成功的分析从苦痛鬼屋的瘟疫之锅里取得的样品，就可以研制出另一种能够有效对抗瘟疫的解药了!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5235, '目标：盖罗恩农场', '最后的一口瘟疫之锅在一个被称作盖罗恩农场的地方，由亡灵天灾中较为强大的爪牙守卫着——那里的鬼魂和幽灵尤其危险。你可不能掉以轻心，$N。$B$B盖罗恩农场在这里的东北方向，靠近东瘟疫之地的边界。和以前一样，消灭那里的护锅者以获取他的钥匙。拿着这个空样品瓶，把它装满给我拿回来。愿圣光护佑你平安完成这次危险的任务，$c。', '到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。', '护锅领主索瓦斯的钥匙碰到瘟疫之锅平台底部控制板上的锁之后就消散了。一声轻轻的叮当声过后，控制板打开了，展现在你面前的是瘟疫之锅里沸腾着的毒素。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为亡灵壁垒的暗影牧师范蒂丝带回一份样品。', '瘟疫之锅的控制板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。', '', '去西瘟疫之地的盖罗恩农场解锁天灾之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5236, '返回亡灵壁垒', '你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。$B$B现在你应该带着毒药回到亡灵壁垒的暗影牧师范蒂丝那里去了。', '把盖罗恩农场的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。', '恭喜你，$N，你已经为我们打开了最后一口瘟疫之锅!迪瑟斯将很快找到中和这口锅中的毒素所需的试剂。$B$B至于你，我敢肯定高阶执行官德灵顿会亲自向你表示感谢。没有你，我们反抗天灾军团的斗争决不会有这么大的进展。谢谢你，英雄!', '盖罗恩农场的瘟疫之锅是我们在西瘟疫之地的最后一个目标。只要我们得到锅中的瘟疫样本，我们就可以通过这四口锅把我们的解药散播到空气中!即使有克尔苏加德的支持，天灾军团也很难兼顾四口瘟疫之锅。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5242, '最终一击', '不幸的是，我认为唯一可以解决暗影议会的方法就是从正面进攻。没有别的方法进入暗影堡，我也没有办法把你传送进去。通往底部的笔直小径是唯一的通路……而且我也知道你的目标是谁。他的名字是费尔丹……暗影领主费尔丹。他就是暗影堡的头目。杀了他和他的两个魅魔仆从，然后回到我这儿来。费尔丹与燃烧军团定下了盟约，你必须除掉他！', '杀掉米莱恩和萨莉亚，并把暗影领主费尔丹的徽记交给费伍德森林的格雷塔·苔蹄。', '赞美大地之母，$N!谢谢你!这确实是荣耀的一天!$B$B在受到如此沉重的打击之后，暗影议会再要想恢复以前的实力将会困难重重。你今天完成了一件伟大的壮举!$B', '如果没有了费尔丹，暗影议会就很有可能失去重心并开始内讧。他们会各怀鬼胎地相互争夺权力和财宝。那将是毁灭他们的绝佳时机。', '', '去费伍德森林找翡翠圣地的格雷塔·苔蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5243, '神圣之屋', '我把我的非死非生的状态看作一种疾病，$c。一种几乎不需要治疗的疾病。然而，它也是对银色黎明的祝福。还有什么办法比通过亡灵来打击天灾军团更有效呢？$B$B我的同事尊敬我，因为我做出了牺牲，但赞美和荣誉对我毫无意义。$B$B如果你有兴趣帮助银色黎明，那么我可以提供你一项任务。$B$B到斯坦索姆去找回我们剩馀的圣水，在城中的补给箱里找一找吧。', '到北方的斯坦索姆去，寻找散落在城市中的补给箱，并收集5瓶斯坦索姆圣水。当你找到足够的圣水之后就回去向莱尼德·巴萨罗梅复命。', '干得好，$C。你已经证明了在宽容别人的同时，你会勇往直前地消灭克尔苏加德的爪牙。', '你要注意，并不是所有的补给木箱都在城市被毁灭后保存了下来。天灾军团不敢碰触圣水，但圣水并不能阻止害虫的侵袭。', '', '去东瘟疫之地的圣光之愿礼拜堂找莱尼德·巴萨罗梅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5245, '凯斯利尔的怨灵', '那些上层精灵的灵魂是非常悲惨的，他们仍在寻找那件诅咒了他们、使他们被困在凯斯利尔的古代遗物的碎片。$B$B如果你感兴趣的话，拿着我的镐到南方的湖边去，看看你能否从冰里找到它的碎片。$B$B眼下我不能告诉你任何有关这些碎片的事，但我知道谁可以……奥萝拉，她就住在东瘟疫之地北部的北地哨塔附近。', '使用加隆的镐来寻找四块上层精灵遗物的碎片，把它们交给东瘟疫之地的奥萝拉。', '精灵的过去是我所不愿提及的，$N。原谅我，一想到曾经发生的那些事情，我就非常痛苦……而且没有任何办法可以让一切重回正轨。$B', '你为何而来?', '', '去找东瘟疫之地的奥萝拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5246, '历史的残片', '我没有意识到……请原谅我无情的话语，$c。$B$B我并不想回顾祖先犯下的错误，但是如果你的请求是真心的，那么我会帮助你。$B$B<奥萝拉查看了一下这些碎片>$B$B我相信这就是辛玛洛水晶，一种具有强大的魔法力量并可以控制更强大力量的神器。它原本是用来做善事的，但那些偷走它的窃贼的邪恶力量使它破碎了。$B$B到艾萨拉的辛玛洛神殿去吧，希望那本书还放在那里……', '在艾萨拉的辛玛洛神殿里找到神圣的上层精灵笔迹，并将它带给位于东瘟疫之地的北地哨塔附近的奥萝拉。', '这本书已经很久都没有人碰过了……', '只有看过圣书，我才能知道是否可以帮助你……', '', '去找东瘟疫之地的奥萝拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5247, '历史的残片', '如果你真的希望重塑神器，那我就可以帮助你。$B$B为了修复碎片，我需要一些具有强大魔法能量的物品。一块魔化瑟银锭和五块恢复水晶……你还得从一个非常危险的地方搜集一些水……在菲拉斯地区的厄运之槌中，艾德雷斯区有一个厄运之池，用池中的水装满这只小瓶。$B$B在你去收集这些东西的时候，我会尝试从书中找到复原神器所需的知识。', '给东瘟疫之地的奥萝拉带去一块魔化瑟银锭、5块恢复水晶，以及一小瓶恐怖之水。', '凭着这些材料，我就可以把碎片熔合在一起……希望能使它们恢复到从前的样子。', '神器必须放在最值得信任的人手中。它不能再次被盗了……', '', '去找东瘟疫之地的奥萝拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5248, '记忆的折磨', '$N，我为过去所发生的事情哭泣。就像这块水晶一样，精灵这个种族已经破碎了。我不知道这些碎片是否还能被拼成一块，但是能够帮你完成这项小小的任务，这令我的悲痛减轻了许多。$B$B我们决不能忘记过去，$N……$B$B请把辛玛洛水晶带回凯斯利尔湖去，你必须寻找一个意识到这个错误的上层精灵，让他看到我们已经纠正了他们犯下的弥天大错。', '把辛玛洛水晶带回冬泉谷的凯斯利尔湖，在那里寻找一个会与你讲话的上层精灵。', '请……离开我……', '诅咒……永远……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5251, '档案管理员', '所谓物极必反，血色十字军就是这样的典型。你认为他们盲目的狂热会有好结果吗？他们以圣光的名义残害了多少无辜的人？$B$B他们都是该死的恶徒！$B$B我对他们中的一个成员最为关注，那就是斯坦索姆的档案管理员加尔福特，他看管着十字军最宝贵的文件档案。杀了他，然后烧毁那些文档！如果你成功了，就回到我这里来，你会得到奖励的。', '在斯坦索姆城中找到血色十字军的档案管理员加尔福特，杀掉他，然后烧毁血色十字军档案。', '太好了，$N!他们数年积累下来的资料化为灰烬!血色十字军在接下来的几星期里一定会知道这次打击对他们有多么严重。', '记住，$N―我们需要宽容，但是我们也必须坚持自己的信仰!', '', '去东瘟疫之地找圣光之愿礼拜堂的尼古拉斯·瑟伦霍夫公爵。', '', '烧毁文档', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5252, '悔恨的上层精灵', '那块……水晶……$B$B这里的上层精灵被他们的过错折磨着……$B$B我感到很悲伤，但是我意识到了很久之前我们犯下的错误。虽然我们没有办法纠正这个过错，但是你拿回了辛玛洛水晶，现在我终于可以安息了……$B$B你必须归还它……$B$B必须……', '和坠星村的维恩德·夜风谈一谈，了解到辛玛洛水晶所在的位置。', '难道……难道这就是……', '你离开已经很长时间了，$N。这段时间以来，你都遇见了些什么事情?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5253, '辛玛洛水晶', '你给我留下了深刻的印象，$N。$B$B辛玛洛水晶永远都无法重回神殿，你应该知道的，它已经变成了废墟。但是我相信你对抗邪恶力量的努力会得到回报的。$B$B到达纳苏斯去找大德鲁伊范达尔·鹿盔，然后把水晶交给他，$N。这样水晶就不会再次落到居心叵测的人手中了。根据我的观察，只有极其强大的魔法用户才能控制水晶的力量。', '将辛玛洛水晶送到达纳苏斯的大德鲁伊范达尔·鹿盔那里。', '我听说过辛玛洛水晶，它的力量将会使你拥有强大的魔法力量，但是只有真正有能力的人才有资格获得这种力量。你不仅拿回了水晶，还意识到了自己的极限，并且没有尝试使用那块水晶，这令我感到很高兴。$B$B感谢你把它交给我，$N。我们会把它妥善保管的，愿那些原本守护这块破碎水晶的被诅咒的灵魂们得到安息。$B', '怎么了，$r?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5262, '可怕的真相', '当房间中的尘埃逐渐落定的时候，你努力整理着自己的思路。在回忆了一遍刚刚发生的事情之后，你似乎还是无法相信这一切。$B$B血色十字军的头号人物是个恶魔？不仅仅是恶魔，他还是幽暗城中的瓦里玛萨斯的兄弟？$B$B你小心地将恐惧之王的徽记取下，然后装入包中。显然，如果没有证据的话,没有人会相信你所说的。$B$B你必须马上让尼古拉斯·瑟伦霍夫公爵得知这个消息！', '将巴纳扎尔的徽记交给东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。', '这对十字军意味着什么?他们是否已经在恶魔的控制之下了?他们是否已经不知不觉地被一个更加邪恶的力量所利用了?', '你有什么要给我的吗，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5263, '超越', '你很能干，而且你一直遵从我的命令。我很少见到同时具备这两点的$c。现在我相信你可以执行神圣的正义。$B$B<瑟伦霍夫双手合十，并把它们举到面前。>$B$B克尔苏加德的大将驻守在斯坦索姆。向我证明你是一个勇士——我的勇士。除掉瑞文戴尔男爵，把他的徽记给我带回来。', '到斯坦索姆去杀掉瑞文戴尔男爵，把他的徽记交给尼古拉斯·瑟伦霍夫公爵。', '我很久都没有将你这样的勇士迎入我们的行列了。这些年来，你是第一个有幸晋见麦斯威尔.泰罗索斯领主的$C。', '男爵杀的人也许比你一生所看到的都要多。', '', '去东瘟疫之地找圣光之愿礼拜堂的尼古拉斯·瑟伦霍夫公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5282, '永不安息的灵魂', '对亡灵的愤怒是我力量的源泉，也是我继续生存下去的动力。但是，我不是个没大脑的狂热分子。总有些人——比如血色十字军，他们只知道疯狂地摧毁一切亡灵，但从来也没想过要对他们有哪怕一丁点的同情。$B$B所以我发明了这样一件东西：冲击器。它可以解放斯坦索姆城中的那些痛苦的灵魂。$B$B对那些在街道上游荡的鬼魂使用它，让他们的灵魂获得自由吧。', '对斯坦索姆城中的鬼魂使用埃根的冲击器。当那些永不安息的灵魂挣脱他们的外壳时，再次使用埃根的冲击器——他们就可以获得自由了！$B$B解放15个永不安息的灵魂，然后回到埃根那里去。', '<伊根拭去眼眶中的泪水。>$B$B你看见我妈妈了吗，$N?你让她获得安宁了吗?$B$B你是尊严的象征。为了补偿这件事情给你带来的麻烦……', '怜悯是我们与动物的区别所在，$N。记住这一点……', '', '去东瘟疫之地找恐惧谷的埃根。', '已解放灵魂', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5283, '铸造护甲的艺术', '这么说，你做出了明智的决定。$B$B对我来说，铸造护甲就是我的爱好。那些整天打造玩具刀枪的根本不知道什么是锻造。$B$B有了绝佳的防护，才能取得战争的胜利。当战争的优势不在你这边时，任何武器都没法帮你摆脱困境。$B$B好吧，我们开始工作吧。首先你必须证明自己已经学会了一些粗略的手艺。然后，我将把你塑造成一名真正的护甲铸造师。你应该知道如何制造精制秘银护甲，对吧？', '要想成为一名护甲铸造师的话，你必须将下列物品交给格鲁努斯：4顶精制秘银头盔、2双精制秘银战靴和1副精制秘银胸甲。', '很好，$N。你还有最后一次重新选择的机会。如果你想要当个造玩具的，呃，我是说武器锻造师，现在还不算太晚。$B$B我相信你会做出正确的抉择。', '啊，没什么比一双巧手更有价值的了，你只需看看护甲的线脚，就可以知道它是个什么级别的货色。', '', '去找丹莫罗的格鲁努斯·削钢。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5284, '武器铸造师之道', '作为一名武器铸造师，你将发现英雄和冒险者们会经常来向你购买装备。虽然你应该可以承受这繁重的工作量，但是你所得的钱财会有一大部分耗费在治疗肌肉拉伤和肺尘病上。$B$B哦，没错，$N，武器铸造师拥有惊人的财富！$B$B要是你想成为我们当中的一员，就必须证明自己能帮我赚——我的意思是，你必须要证明，当人们需要高质量的武器时，他们会来找你而不是别人。去工作吧！', '要想成为一名武器铸造师的话，你必须将下列物品交给埃隆努斯·冷钢：4把月钢宽剑、4把巨型铁斧、2把秘银重斧和2把巨型黑色锤。', '正是时候!我的顾客正等着要货呢。$B$B把它们放在那儿，小心点。你就要迈出武器锻造师生涯中的第一步了!', '<埃隆努斯正忙于将金币整理成堆。>', '', '去铁炉堡找大锻炉的埃隆努斯·冷钢。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5301, '铸造护甲的艺术', '我很满意。我对自己使用铁锤和铁砧制造出的东西感到满意。每当看到骄傲的部落士兵身穿着由我打造的钢铁铠甲，我就能体会到活着的意义。永不放弃是我不变的信念，$N。$B$B我无法将自己的满足感分给你，我只能引导你前进。尽你的全力，成为护甲铸造师的道路就像一次漫长的旅程。$B$B如果你想要成为技艺精湛的护甲铸造师，就告诉我吧，我将对你进行训练，但在此之前你必须完成一项任务。', '要想成为一名护甲铸造师的话，你必须将下列物品交给奥克索斯：4顶精制秘银头盔、2双精制秘银战靴和1副精制秘银胸甲。', '这是你迈入护甲锻造师行列所需的最后一步了，$N。现在你还有最后一次选择退出的机会。否则，就准备迎接一生的荣耀吧!', '我要用尽全力，把这块铁敲打得坚固无比。', '', '去找奥格瑞玛的奥克索斯·铁怒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5302, '武器铸造师之道', '总有一天，我要制造出一把无以伦比的铁锤，配得上酋长的铁锤！$B$B这是我毕生的工作，$N，也是我的激情所在。我认为你有潜力成为我们中的一份子，成为一名武器铸造师。我可以帮助你发挥自己的潜能。$B$B你只需完成一项简单的任务，让我来看看你够不够资格。', '要想成为一名武器铸造师的话，你必须将下列物品交给伯古什：4把月钢宽剑、4把巨型铁斧、2把秘银重斧和2把巨型黑色锤。', '这是你迈入武器锻造师行列所需的最后一步了，$N。现在你还有最后一次选择退出的机会。否则，就准备接受新的知识吧!', '为部落的荣耀而努力吧!', '', '去找奥格瑞玛的伯古什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5305, '甜美的平静', '平静之剑位于血色堡垒内，红衣铸锤师以生命守护着它。打败他，并将他的围裙交给我。作为报答，我将训练你成为锻造战锤的铁匠。', '到斯坦索姆去杀死红衣铸锤师。将红衣铸锤师的围裙交给莉莉丝。', '希望你的战锤可以打爆许多脑浆，$N!', '他的围裙!在哪儿?', '', '去冬泉谷找永望镇的轻盈的莉莉丝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5306, '沃什加斯的蛇石', '别被她的美貌愚弄了，$c。暗影猎手沃什加斯是个狂暴而致命的猎手。$B$B<基尔拉姆指着自己脸上的伤疤。>$B$B喏，这就是她给我的——她称之为爱的陷阱。$B$B复仇的时刻终于来临了。$B$B你可以在黑石塔中找到沃什加斯。杀死她并将她的蛇石交给我。如果你成功了，我就教你如何打造黎明之刃！。', '到黑石塔去杀死暗影猎手沃什加斯，将沃什加斯的蛇石交给基尔拉姆。', '知识就是力量!', '据说用沃许加斯的菊石打磨过的斧头可以保持锋利达千年之久!', '', '去冬泉谷找永望镇的基尔拉姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5307, '腐蚀', '如果我看起来对你有些无礼，那是有原因的。腐蚀之剑的设计图被黑衣守卫——瑞文戴尔男爵的精英骷髅部队给盗走了。$B$B没错，斯坦索姆的瑞文戴尔男爵。$B$B现在黑衣守卫铸剑师正在以他的生命——呃，姑且这么说吧——守护着设计图。$B$B杀死他，把他的物品拿回来作为凭证，我就会教你如何锻造闪耀轻剑！', '在斯坦索姆找到黑衣守卫铸剑师，然后杀死他。将黑色卫士徽记交给亡灵杀手瑟里尔。', '刀剑永远是你铸造的最好选择。', '你忘记自己的任务了吗，$N?', '', '去冬泉谷找永望镇的亡灵杀手瑟里尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5321, '昏昏欲睡', '我正要赶路去迈斯特拉岗哨见利拉迪斯·月河，但是我决定在这里停下打个盹……自从我被从翡翠梦境中唤醒之后，就总是那么困……$B$B<打哈欠>$B$B你愿意给我带路吗？我知道迈斯特拉岗哨在这里的南边，就沿着灰谷的路走好了。路上可能会有危险，我希望你的朋友也能一起来帮助我。$B$B最后一点，也许我会在半路上睡着，你只要吹响我的号角就可以唤醒我了。号角就在这个箱子里。', '护送克罗尼亚·恒影到灰谷迈斯特拉岗哨的利拉迪斯·月河那里去。', '啊，我很高兴克罗尼亚终于来了!他在路上又睡觉了，是不是?$B$B感谢你带他来\r\n这里，$N。', '克罗尼亚来了没有?', '护送克罗尼亚·恒影到迈斯特拉岗哨去', '去找灰谷的利拉迪斯·月河。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5341, '巴罗夫系列的宝藏', '通灵学院中藏着巴罗夫系列的遗产。我，阿莱克斯·巴罗夫，是这个系列硕果仅存两名后嗣之一。另一个是我的兄弟维尔顿。$B$B那个懦弱的维尔顿，他在战争开始时就逃走了，保住了他的小命。$B$B现在，他正在到处搜寻地契，想要独吞那笔财富。抢在我的兄弟之前取得那些地契，我保证将使你变得非常富有，富有得远远超出你的想象。', '到通灵学院中去取得巴罗夫系列的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到阿莱克斯·巴罗夫那儿去。', '干得好，$r。现在，该收回我的遗产了……', '向我行礼鞠躬，你这低贱的$r。我是身出名门的贵族，而你只不过是个一文不值的农民。', '', '去提瑞斯法林地找亡灵壁垒的阿莱克斯·巴罗夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5342, '巴罗夫的继承人', '既然我的兄弟仍然活着，那么自然就是系列财产的理所应当的继承人。我绝不能让他得到这笔财产。$B$B你这样卑贱的流浪者除了当个冷血杀手之外还能干什么？$B$B这任务很简单，我希望你能胜任。如果你想要得到报酬，就按我说的去做吧。$B$B维尔顿在东边的冰风岗，他在那里受到了联盟的保护。杀死他，把他的徽记给我带回来。$B$B<阿莱克斯打了个哈欠。>$B$B赶快出发吧。', '到冰风岗——联盟的领地——去暗杀维尔顿·巴罗夫。把他的徽记交给阿莱克斯·巴罗夫。$B$B要多加小心，联盟也许对维尔顿实施了严密的保护。', '好极了!现在，我掌握了巴罗夫系列的权力和财富!$B$B<阿莱克斯扔给你一只大口袋。>$B$B你这肮脏的$r，这是你应得的。', '确保我得到这笔财产，你也不会吃亏的。', '', '去提瑞斯法林地找亡灵壁垒的阿莱克斯·巴罗夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5343, '巴罗夫系列的宝藏', '我亲爱的兄弟阿莱克斯……我真不该饶了他的命。我与已经成为亡灵的他四目相视，最终却免了他一死。$B$B<维尔顿啐了一口唾沫。>$B$B现在他正到处寻找属于我的财产！我绝不能让他得逞。$B$B在他肮脏的爪子碰到财宝之前，你必须找到我们巴罗夫系列的地契，我会用无数的珍宝和财富回报你。它们就在通灵学院的废墟中，要快！', '到通灵学院中去取得巴罗夫系列的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到维尔顿·巴罗夫那儿去。', '我还要请求你帮我再做一件事情，$N。', '只要你让我的未来有了保障，我也不会让你空手而归的。', '', '去西瘟疫之地找冰风岗的维尔顿·巴罗夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5344, '巴罗夫的继承人', '地契已经找到了，我们还剩下一件事要做——杀死阿莱克斯。只要他一死，我就用不着再担心那些惟利是图、肆无忌惮的强盗来取我的徽记了。$B$B这任务很简单。阿莱克斯在亡灵壁垒，他在那里受到了部落的保护。$B$B不，只是杀死他还不行，我要你把他的徽记拿回来！至于你怎么做到这一点……呃，那是你的事情。这种行为可不是我这样的贵族会做的。', '去亡灵壁垒——部落的领地——去暗杀阿莱克斯·巴罗夫。把他的徽记交给维尔顿·巴罗夫。$B$B要小心，部落也许对阿莱克斯实施了严密的保护。', '今天是个荣耀的日子!最终，让巴罗夫系列蒙羞的败家子死掉了，我终于继承了系列的财产!$B$B你，拿着这个，赶快从我眼前消失吧。', '你难道不想要报酬吗?', '', '去西瘟疫之地找冰风岗的维尔顿·巴罗夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5361, '兄弟', '我的兄弟纳塔卡驻扎在凄凉之地的幽灵岗哨。我想问你……你能帮我把这份报告交给他吗？距离我上次写报告给他已经过去一年了，最近半人马有些不寻常的举动，我想我应该把这些告诉他。$B$B到十字路口北边的石爪山脉去，然后向西进入焦炭谷，再往南进入凄凉之地，在那儿有一条路通往南边的幽灵岗哨。', '将峭壁卫兵图林·长角的报告交给凄凉之地幽灵岗哨的纳塔卡·长角。', '我不知道你跟我兄弟是什么关系，但是看来他很信任你，$C。$B$B我是纳塔卡.长角，欢迎你来到鬼旅岗哨，我们迫切需要你这样的$C!跟其它弟兄们谈谈吧，也许他们有什么事情需要你的帮助。', '你带来了什么消息，$C?啊—你是说我兄弟托送的消息?好吧，把报告给我吧!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5381, '埃鲁索斯之手', '火刃氏族拥有恶魔之盒，那里面放着强大的埃鲁索斯之手。火刃氏族用它来打开玛诺洛克集会所的恶魔之门。我们必须阻止成群的恶魔涌入这个世界，$n！用这把恶魔之锄去挖掘雷斧堡垒中的红色水晶，拿到恶魔之盒。', '在雷斧堡垒中找到恶魔之盒，把它和恶魔之锄一起交给葬影村的泰迦·慧鬃。', '啊，恶魔之盒。把它给我，$C，我将打开它……并向你展示埃卢梭斯之手。', '$N，你拿到恶魔之盒了吗?', '', '去凄凉之地找葬影村的泰迦·慧鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5382, '瑟尔林·卡斯迪诺夫教授', '卡斯迪诺夫杀死了数千条生命。他必须得到惩罚，正义必须得到伸张。$B$B找到他，让他也尝尝他给那些无辜者带来的痛苦。在他死掉之后烧毁我们的遗体，让它们都化为灰烬，$N。', '在通灵学院中找到瑟尔林·卡斯迪诺夫教授。杀死他，并烧毁艾瓦·萨克霍夫和卢森·萨克霍夫的遗体。任务完成后就回到艾瓦·萨克霍夫那儿。', '我能感觉到自己的灵魂正在康复，$N。你帮了我和我丈夫的大忙，但是事情还没有完。', '我们必须除掉这个屠夫!', '', '去西瘟疫之地找达隆米尔湖的艾瓦·萨克霍夫。', '', '烧毁艾瓦·萨克霍夫的遗骸', '烧毁卢森·萨克霍夫的遗骸', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5384, '传令官基尔图诺斯', '就是这个了，$N。$B$B<艾瓦指着口袋中的小瓶。>$B$B这无辜者之血。最纯净的血，用于取悦卡斯迪诺夫的主人。$B$B也许它可以召唤基尔图诺斯，这样我们就能杀死他了。$B$B把血液带到门廊去，放在火盆下。基尔图诺斯会出现的——他无法抵抗这血液的诱惑。当他出现时，释放出那些愤怒的无辜者的灵魂。$B$B如果你成功的话，你所能得到的不仅仅是我们的感激之情。', '带着无辜者之血回到通灵学院，将它放在门廊的火盆下面，基尔图诺斯会前来吞噬你的灵魂。$B$B勇敢地战斗吧，不要退缩！杀死基尔图诺斯，然后回到艾瓦·萨克霍夫那儿。', '随着基尔图诺斯的死亡，通灵学院的恐怖传说终于快要结束了。但是，我们要做的事情还很多。这儿的其它人都已听说了你勇敢的行为。拿着这个，$N，它可以让你与凯尔达隆的其它迷失的灵魂进行交流。', '小心，基尔图诺斯是个经验丰富的战士。', '', '去西瘟疫之地找达隆米尔湖的艾瓦·萨克霍夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5385, '特雷·莱弗治的残骸', '你小心地拾起袋子，准备返回费伍德森林和灰谷边界处的杰希尔·月弓那儿去。希望在你将圣骑士的遗体交给他的朋友之后，他会被隆重地安葬。', '将特雷·莱弗治的残骸交给费伍德森林的杰希尔·月弓。', '你成功了!赞美艾露恩以及你崇拜的任何神明吧，$N。今天，你完成了一项光荣而高贵的使命。你不仅拯救了亚科纳琳，还为她最好的朋友进行了复仇，我敢肯定她会为此感到高兴的。$B$B我这里没有什么可以给你的，但是，请收下这个吧。$B', '加德纳尔的情况怎么样了，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5386, '食鱼度日', '我在幽灵岗哨这儿好久都没有闻到过鱼肉的香味了。葬影村的巨魔最擅长捕鱼……但是，我要在此负责半人马的事情，因此没有时间去拜访巨魔。嗯……$B$B帮我个忙吧，替我去一趟葬影村。在那里找当地的渔夫吉纳泽林谈谈，给我带点美味可口的血肚鱼回来。沿着南边的道路走，你就可以到达西边的巨魔村庄。', '与葬影村的吉纳泽林谈话，然后将2条血肚鱼交给纳塔卡·长角。', '你可真是个救世主，$N!这些血肚鱼看起来就是生嚼也够味儿。$B$B<纳塔卡开始流口水了。>$B$B作为报酬，你随便选一样东西吧。', '当我想到油炸的血肚鱼时，我的蹄子便开始发痒，口水都快流下来了……你搞到鱼了吗?', '', '去凄凉之地找幽灵岗哨的纳塔卡·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5402, '爪牙的天灾石', '', '', '恭喜你，$N―我很高兴为你颁发这枚勇气勋章!$B$B勇气勋章有两个用途:它可以让你与银色黎明的关系更加亲密，这是对你奋力作战的表彰;你也可以凭这枚勋章再加上一点钱，到我们的军需官那里换取一些宝贵的物品。$B$B无论你决定怎样使用这枚勇气勋章，它都是你用血汗赢得的，干得不错!', '爪牙的天灾石是天灾军团的身份象征，通常是由那些部署在瘟疫之地的、较为弱小的士兵所携带的。我所说的“较为弱小”是个相对的概念，无论天灾军团出现在哪里，他们都是一个不可轻视的威胁。$B$B如果你能拿来二十个这样的天灾石，银色黎明将会给你颁发一枚勇气徽记，以此表彰你在于天灾军团的战争中做出的贡献!', '', '去找奥特兰克山脉的银色黎明军官普尔哈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5403, '侵略者的天灾石', '', '', '恭喜你，$N―我很高兴为你颁发这枚勇气勋章!$B$B我们每向你这样的勇士颁发一枚勇气勋章，就说明我们在这场对抗天灾军团的战争中又取得了一点进展。只要有更多的英雄加入我们的行列，银色黎明终将剿灭这支无比邪恶的势力。我希望你在今天表现出来的过人勇气也能一直持续到胜利时刻的到来!', '侵略者的天灾石是天灾军团精英部队的象征，通常是由那些部署在瘟疫之地的主力部队中的士兵携带的。斩杀这样的敌人对你来说是一个挑战，但是你也会因此得到丰厚的奖赏。$B$B如果你能拿来十块这样的天灾石，银色黎明就将给你颁发一枚勇气徽记。', '', '去找奥特兰克山脉的银色黎明军官普尔哈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5404, '堕落者的天灾石', '', '', '恭喜你，$N―我很高兴为你颁发这枚勇气勋章!$B$B这足以证明你是个甘愿为正义事业献身的英雄。我们会表彰一切与天灾军团抗争的勇士，但是击败他们的领袖才是真正给了他们一个迎头痛击!$B$B为了黎明而战，我的$g兄弟:姐妹;!', '堕落者的天灾石是天灾军团将领的标志。那些统御天灾军团的将领总是会随身携带一块这样的徽记。如果能杀掉如此强大可怕的敌人对银色黎明和我们的正义事业来说都是非常有利的!$B$B如果你能拿来一块这样的天灾石，我会代表银色黎明颁发一枚勇气徽记给你。不过你要小心，$N - 你要面对的绝非一般的敌人。', '', '去找奥特兰克山脉的银色黎明军官普尔哈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5406, '堕落者的天灾石', '', '', '恭喜你，$N―我很高兴为你颁发这枚勇气勋章!$B$B这足以证明你是个甘愿为正义事业献身的英雄。我们会表彰一切与天灾军团抗争的勇士，但是击败他们的领袖才是真正给了他们一个迎头痛击!$B$B为了黎明而战，我的$g兄弟:姐妹;!', '堕落者的天灾石是天灾军团将领的标志。那些统御天灾军团的将领总是会随身携带一块这样的徽记。如果能杀掉如此强大可怕的敌人对银色黎明和我们的正义事业来说都是非常有利的!$B$B如果你能拿来一块这样的天灾石，我会代表银色黎明颁发一枚勇气徽记给你。不过你要小心，$N - 你要面对的绝非一般的敌人。', '', '去找西瘟疫之地的银色黎明军官加鲁什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5407, '侵略者的天灾石', '', '', '恭喜你，$N―我很高兴为你颁发这枚勇气勋章!$B$B我们每向你这样的勇士颁发一枚勇气勋章，就说明我们在这场对抗天灾军团的战争中又取得了一点进展。只要有更多的英雄加入我们的行列，银色黎明终将剿灭这支无比邪恶的势力。我希望你在今天表现出来的过人勇气也能一直持续到胜利时刻的到来!', '侵略者的天灾石是天灾军团精英部队的象征，通常是由那些部署在瘟疫之地的主力部队中的士兵携带的。斩杀这样的敌人对你来说是一个挑战，但是你也会因此得到丰厚的奖赏。$B$B如果你能拿来十块这样的天灾石，银色黎明就将给你颁发一枚勇气徽记。', '', '去找西瘟疫之地的银色黎明军官加鲁什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5408, '爪牙的天灾石', '', '', '恭喜你，$N―我很高兴为你颁发这枚勇气勋章!$B$B勇气勋章有两个用途:它可以让你与银色黎明的关系更加亲密，这是对你奋力作战的表彰;你也可以凭这枚勋章再加上一点钱，到我们的军需官那里换取一些宝贵的物品。$B$B无论你决定怎样使用这枚勇气勋章，它都是你用血汗赢得的，干得不错!', '爪牙的天灾石是天灾军团的身份象征，通常是由那些部署在瘟疫之地的、较为弱小的士兵所携带的。我所说的“较为弱小”是个相对的概念，无论天灾军团出现在哪里，他们都是一个不可轻视的威胁。$B$B如果你能拿来二十个这样的天灾石，银色黎明将会给你颁发一枚勇气徽记，以此表彰你在于天灾军团的战争中做出的贡献!', '', '去找西瘟疫之地的银色黎明军官加鲁什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5421, '坐享其成', '', '', '嗯，没什么比完成工作更美妙的了，特别是其它人帮你完成工作……对吧?', '谁能使我的生活更惬意些，我就报答谁……我喜欢尽可能地少做事，多睡觉!$B$B我在葬影村的码头放了许多捕贝装置，如果你愿意帮我收集贝壳，我也会给你一些好东西……明白我的意思了吗?你每交给我五块贝壳，我就送你一条血肚鱼。', '', '去找凄凉之地的吉纳泽林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5441, '懒惰的苦工', '该死的苦工！我叫他们在山谷里伐木，但他们总是见缝插针地打盹！我需要找个人帮我去叫醒他们。$B$B你看上去挺适合这差事的。给你，拿着这根棍子，看到偷懒睡觉的苦工就打醒他。只要狠狠地敲他们一下就能让他们乖乖回去工作了！别忘了把棍子还给我。$B$B这些该死的懒汉……', '在懒惰的苦工睡觉时，用工头的木棒敲他们。敲醒5个苦工，然后把工头的木棒还给试炼谷的工头塔兹利尔。', '很好，很好，也许他们下次偷懒之前会记起这次的教训!感谢你的帮助!', '偷懒可不好……$B$B嗯?你手里拿的是我的木棒?你抓到偷懒睡觉的苦工没有?', '', '去找杜隆塔尔的工头塔兹利尔。', '敲醒苦工', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5461, '莱斯·霜语', '亡灵对于生命的恐惧就像我们对于死亡的恐惧一样，所以一个亡灵将其生前用过的东西全都毁掉是很正常的事情。$B$B不幸的是，要想创建一件能破除莱斯·霜语不死之身的神器，我们就必须找到他生前拥有的一样东西。$B$B你必须到早已被废弃的激流堡去，那里是莱斯·霜语的家，到那里去寻找这样一件东西。祝你好运，$N。', '到阿拉希高地的激流堡遗迹里面寻找巫妖生前的遗物。如果你能找到这样的东西，就把它交给马杜克镇长。', '我对这样的东西是否存在曾经心存疑问。你找到了它，这给了我们一个非常珍贵的机会―我们决不能浪费这个机会。$B$B准备好，$N，接下来我要你做的事情就是深入通灵学院之中。', '$N，巫妖生前的遗物是很难找到的。', '', '去西瘟疫之地找达隆米尔湖的马杜克镇长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5462, '亡灵莱斯·霜语', '你必须把这件遗物放在被玷污的土地上。$B$B传说弗斯特·维斯帕尔是在斯坦索姆城里屈服于巫妖王的。在那片血迹斑斑的土地上，他心甘情愿地献出了自己的生命和灵魂，变成了亡灵的一员。$B$B你必须找到那片土地。$B$B我知道有一个亡灵天灾的背叛者，他被希尔瓦娜斯解救了出来，但是他现在效力于银色黎明。去找到他，他的名字是莱尼德·巴萨罗梅。他应该对这件事情更了解一些，到圣光之愿礼拜堂去找他吧，$N。', '到东瘟疫之地的圣光之愿礼拜堂去找到莱尼德·巴萨罗梅，给他看看巫妖生前的遗物，并告诉他你收集到的情报。', '<莱尼德看着巫妖生前的遗物。>$B$B你的发现唤醒了我想要永远埋藏的记忆。', '不要问你不需要答案的问题。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5463, '米奈希尔的礼物', '我目睹了那个人类，莱斯·霜语，把他的灵魂献给了巫妖王。他将匕首插入自己的喉咙，然后微笑着横切了下去。他的身体倒在了五芒星阵里，巫妖王站在那个死掉的法师旁边，只用了一个简单的动作，巫妖莱斯·霜语就诞生了。$B$B<莱尼德看着地板，然后抬起头来看着你。>$B$B是的，$R，我记起来了。你要找的地方有个名字——米奈希尔的礼物：那块地方曾被巫妖王赐福，那里是亡灵天灾的圣地。', '到斯坦索姆城里去找到米奈希尔的礼物，把巫妖生前的遗物放在那块邪恶的土地上。', '你把遗物放在了那块被玷污的土地上。', '米奈希尔的礼物周围的区域显得特别寒冷。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5464, '米奈希尔的礼物', '巫妖的灵魂钻入了代表它前身的物品之中，这件物品很快变成了一本禁锢着巫妖灵魂的遗物。你把它拿了起来，放入包中。', '把禁锢灵魂的遗物交给东瘟疫之地的莱尼德·巴萨罗梅。', '既然灵魂已经附在了这件遗物上面，那么这件遗物也已经与莱斯.霜语的肉身联结了起来。', '<莱尼德战栗着。>', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5465, '禁锢灵魂的遗物', '把这件遗物交给马杜克吧，$N。他会告你该怎么使用它的。', '回到凯尔达隆的马杜克镇长那里，把禁锢灵魂的遗物交给他。', '我刚才还在担心你无法活着从那里出来……', '你完成了我交给你的任务了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5466, '巫妖莱斯·霜语', '你还有最后一个任务必须去完成，$N——到巫妖莱斯·霜语的巢穴中去击败他。$B$B使用禁锢灵魂的遗物的力量来对付他——千万不要心存任何怜悯，否则倒下的就会是你！不要因为痛苦而屈服！$B$B当仪式完成之后，他就不再是一个不死之身了。那时你必须尽快杀死他，把他的徽记给我拿回来。', '在通灵学院里找到莱斯·霜语。当你找到他之后，使用禁锢灵魂的遗物破除其亡灵的外壳。如果你成功地破除了他的不死之身，就杀掉他并拿到莱斯·霜语的徽记。把那个徽记交给马杜克镇长。', '上万个\r\n灵魂在齐声尖啸，$N!你对天灾军团和他们的主人进行了致命的一击。', '你肩负着为上万个永不安息的灵魂复仇的责任，$N。', '', '去西瘟疫之地找达隆米尔湖的马杜克镇长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5481, '葛尔多的任务', '主人需要草。我们的手太大，没有办法捡。你可以帮我们，我们不伤害你。我们需要阴暗草。这里有许多这样的草，路边也有。$B$B拿到草之后，把它交给布瑞尔墓地的主人，霍兰德。', '收集3根阴暗草，把它们交给布瑞尔墓地的初级药剂师霍兰德。', '这是什么?阴暗草?!我不需要阴暗草!那堆没脑子的臭肉一边在外面乱转，一边让天知道多少个像你这样的废物也跟着他犯傻。我并不想冒犯你。$B$B好吧，既然你已经来了，那也就这样了……我想我不会浪费时间来跟那堆烂肉说清楚我到底要什么，你去办就行了―我要的是末日草!', '那个没用的憎恶在哪里?要是你还没拿到我要的东西，就赶快给我去找。', '', '去找布瑞尔的初级药剂师霍兰德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5482, '末日草', '你看到我所处的困境的吧，$N？那个蠢货弄来的野草根本不是我要的！如果你能给我弄些末日草来，我会回报你的。$B$B据我所知，那些野草一般生长在布瑞尔墓地北面。快去吧，小心那儿的豺狼人。', '收集10株末日草，把它们交给初级药剂师霍兰德。', '啊，我的末日草，很好!$B$B<初级药剂师霍兰德贪婪地揉搓着双手。>$B$B这会非常有用。你为我，呃，我是说黑暗女王，做了一件大事。这是先前承诺的回报。', '嗯，你收集到我要的末日草了吗?', '', '去提瑞斯法林地找布瑞尔的初级药剂师霍兰德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5501, '集骨者', '我们正坐在一座金矿上，你知道吗，一座金矿！科多兽骨将永远改变这个世界……我的顾客可以用它们来制作家具、乐器，甚至是火药。$B$B有一个车队经常到这儿来，收集一大堆科多兽骨，然后在葬影村把它们卖掉。如果你能去到南边的那座科多墓地去给我弄十根科多兽骨回来，我就付你报酬。怎么样？', '从科多墓地收集10根科多兽骨，把它们交给兽人小屋的比布里·弗斯巴克。', '啊，好极了!科多兽骨!$B$B我仿佛已经看到自己的肖像被印在 《哥布尔周刊》的封面上了。我会成为世界上最富有的哥布尔……我的体育老师当年还曾说我会一事无成哪。', '你弄到科多兽骨吗?车队随时都会来的。我只需要十根科多兽骨就可以达到我事业的巅峰。事业的巅峰，你明白吗?!', '', '去找凄凉之地的比布里·弗斯巴克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5502, '部落孤儿的看护者', '你对我真好，$N。我从来没有想过会在儿童周得到如此多的乐趣，谢谢你。我不会因为我的悲惨遭遇而感到悲伤——我的爸爸妈妈总是告诉我，在面对困境的时候要保持坚强。我会成为一个英雄的……就像你一样。$B$B不过现在，我该回家了。让我们一起回去吧，我会告诉院长，你是一个多么出色的$r$c！', '回到奥格瑞玛，把兽人孤儿哨交还给荣誉谷的孤儿监护员巴特维尔。', '愿灵魂保佑你，$N。你已经为葛兰斯做了太多别人想不到的事情。感谢你―你是部落英雄的象征。$B$B如果你有时间的话，请再回来看看我们。我知道葛兰斯会期待着你的到来，我也会欢迎你。$B$B葛兰斯和你相处的很愉快，$N。他想给你一只他最爱的宠物让你时时想着他。', '很高兴再见到你，$N。你有没有在儿童周中完成自己的义务?', '', '去找奥格瑞玛的孤儿监护员巴特维尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5504, '黎明衬肩', '你对银色黎明所做出的贡献将受到表彰，$N。你在我们的组织中有着很高的声誉，因此我授权你可以购买我们最宝贵的装备——我们的魔法抗性护肩。$B$B只要把它加在你现有的护肩上，你就可以抵抗五种魔法的力量。作为对我们的事业继续做出贡献的标志，我要求你拿至少10枚银色黎明勇气勋章来换取这些护肩。', '把10个银色黎明勇气勋章交给西瘟疫之地亡灵壁垒的银色黎明军需官哈萨娜。', '太好了!你对银色黎明做出的贡献必将永载史册，$N。你完成了我的要求，现在我很高兴能为你提供我们的披肩。只要你一直保持在银色黎明中的声望，你就可以从任何银色黎明军需官那里购买到这些披肩。$B$B我的$g兄弟:姐妹;，为了银色黎明而战!', '啊，高尚的$C!你带来我所要求的银色黎明勇气勋章了吗?只要你把它们交给我，我就可以向你提供各种各样的披肩了。', '', '去提瑞斯法林地找亡灵壁垒的银色黎明军需官哈萨娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5505, '通灵学院的钥匙', '', '', '好了，给你，$n——这就是骷髅钥匙。我很确定它能打开通灵学院的大门。不过只有一个办法能检验它，我说，你就别在我这浪费时间了。', '好了，给你，$n——这就是骷髅钥匙。我很确定它能打开通灵学院的大门。不过只有一个办法能检验它，我说，你就别在我这浪费时间了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5507, '黎明衬肩', '你对银色黎明所做出的贡献将受到表彰，$N。你在我们的组织中有着很高的声誉，因此我授权你可以购买我们最宝贵的装备——我们的魔法抗性护肩。$B$B只要把它加在你现有的护肩上，你就可以抵抗五种魔法的力量。作为对我们的事业继续做出贡献的标志，我要求你拿至少10枚银色黎明勇气勋章来换取这些护肩。', '把10个银色黎明勇气勋章交给西瘟疫之地冰风营地的银色黎明军需官莱斯巴克。', '太好了!你对银色黎明做出的贡献必将永载史册，$N。你完成了我的要求，现在我很高兴能为你提供我们的披肩。只要你一直保持在银色黎明中的声望，你就可以从任何银色黎明军需官那里购买到这些披肩。$B$B我的$g兄弟:姐妹;，为了银色黎明而战!', '啊，高尚的$C!你带来我所要求的银色黎明勇气勋章了吗?只要你把它们交给我，我就可以向你提供各种各样的披肩了。', '', '去西瘟疫之地找冰风岗的银色黎明军需官莱斯巴克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5508, '堕落者的天灾石', '', '', '恭喜你，$N―我很高兴为你颁发这枚勇气勋章!$B$B这足以证明你是个甘愿为正义事业献身的英雄。我们会表彰一切与天灾军团抗争的勇士，但是击败他们的领袖才是真正给了他们一个迎头痛击!$B$B为了黎明而战，我的$g兄弟:姐妹;!', '堕落者的天灾石是天灾军团将领的标志。那些统御天灾军团的将领总是会随身携带一块这样的徽记。如果能杀掉如此强大可怕的敌人对银色黎明和我们的正义事业来说都是非常有利的!$B$B如果你能拿来一块这样的天灾石，我会代表银色黎明颁发一枚勇气徽记给你。不过你要小心，$N - 你要面对的绝非一般的敌人。', '', '去找东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5509, '侵略者的天灾石', '', '', '恭喜你，$N―我很高兴为你颁发这枚勇气勋章!$B$B我们每向你这样的勇士颁发一枚勇气勋章，就说明我们在这场对抗天灾军团的战争中又取得了一点进展。只要有更多的英雄加入我们的行列，银色黎明终将剿灭这支无比邪恶的势力。我希望你在今天表现出来的过人勇气也能一直持续到胜利时刻的到来!', '侵略者的天灾石是天灾军团精英部队的象征，通常是由那些部署在瘟疫之地的主力部队中的士兵携带的。斩杀这样的敌人对你来说是一个挑战，但是你也会因此得到丰厚的奖赏。$B$B如果你能拿来十块这样的天灾石，银色黎明就将给你颁发一枚勇气徽记。', '', '去找东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5510, '爪牙的天灾石', '', '', '恭喜你，$N―我很高兴为你颁发这枚勇气勋章!$B$B勇气勋章有两个用途:它可以让你与银色黎明的关系更加亲密，这是对你奋力作战的表彰;你也可以凭这枚勋章再加上一点钱，到我们的军需官那里换取一些宝贵的物品。$B$B无论你决定怎样使用这枚勇气勋章，它都是你用血汗赢得的，干得不错!', '爪牙的天灾石是天灾军团的身份象征，通常是由那些部署在瘟疫之地的、较为弱小的士兵所携带的。我所说的“较为弱小”是个相对的概念，无论天灾军团出现在哪里，他们都是一个不可轻视的威胁。$B$B如果你能拿来二十个这样的天灾石，银色黎明将会给你颁发一枚勇气徽记，以此表彰你在于天灾军团的战争中做出的贡献!', '', '去找东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5511, '通灵学院的钥匙', '', '', '好了，给你，$n——这就是骷髅钥匙。我很确定它能打开通灵学院的大门。不过只有一个办法能检验它，我说，你就别在我这浪费时间了。', '好了，给你，$n——这就是骷髅钥匙。我很确定它能打开通灵学院的大门。不过只有一个办法能检验它，我说，你就别在我这浪费时间了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5513, '黎明衬肩', '你对银色黎明所做出的贡献将受到表彰，$N。你在我们的组织中有着很高的声誉，因此我授权你可以购买我们最宝贵的装备——我们的魔法抗性护肩。$B$B只要把它加在你现有的护肩上，你就可以抵抗五种魔法的力量。作为对我们的事业继续做出贡献的标志，我要求你拿至少10枚银色黎明勇气勋章来换取这些护肩。', '把10个银色黎明勇气勋章交给东瘟疫之地圣光之愿礼拜堂的军需官米兰达·布利洛克。', '太好了!你对银色黎明做出的贡献必将永载史册，$N。你完成了我的要求，现在我很高兴能为你提供我们的披肩。只要你一直保持在银色黎明中的声望，你就可以从任何银色黎明军需官那里购买到这些披肩。$B$B我的$g兄弟:姐妹;，为了银色黎明而战!', '啊，高尚的$C!你带来我所要求的银色黎明勇气勋章了吗?只要你把它们交给我，我就可以向你提供各种各样的披肩了。', '', '去东瘟疫之地找圣光之愿礼拜堂的军需官米兰达·布利洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5514, '昂贵的模具', '你要找的地精的名字叫做克林科·古德斯迪尔。他在塔纳利斯的加基森镇里生活，为出价最高的顾客效力。看来他是唯一个可以帮我们完成融合工序的铁匠，不过他的标价会非常高，所以你来解决他的工钱。$B$B我是个炼金师，不是个银行家。如果我有一堆金子的话，还待在这里干什么？$B$B我相信我已经把事情说得很直白了，咳咳。$B$B加基森在等待你！祝你好运！', '把灌魔的骸骨碎片和15枚金币交给加基森的克林科·古德斯迪尔。', '阿尔比顿说你会把东西送过来，那就拿出来吧!让我把碎片和模具放在一起。$B$B阿尔比顿已经给它们附过魔法了?很好……否则的话，你就得再跑一趟冰风岗了。', '嗯，我知道你是谁，我也知道你来这里干什么。阿尔比顿在你来之前就跟我说过了。让我们长话短说吧，怎么样?$B$B我确实有可以用来制作骷髅钥匙的模具，但是它非常贵―15个金币，现货，不二价。我会把骷髅碎片放进模具里交给你，我也会教你如何铸造钥匙，即使你连一点锻造的相关知识都没有……这些都是免费的。$B$B谁说商人都是唯利是图的!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5515, '卡斯迪诺夫的恐惧之袋', '$N，你帮我去掉了压在心上的一块大石头，但是你的任务还没有完成。卡斯迪诺夫的主人基尔图诺斯还活着。$B$B在你面对基尔图诺斯之前，必须先找到召唤他的方法。$B$B据说詹迪斯·巴罗夫负责将卡斯迪诺夫收集的无辜者之血交给基尔图诺斯。$B$B到通灵学院中那个沉没的墓穴里去找到她，打败她。把你找到的线索拿回来交给我。', '在通灵学院找到詹迪斯·巴罗夫并打败她。从她的尸体上找到卡斯迪诺夫的恐惧之袋，然后将其交给艾瓦·萨克霍夫。', '是恐惧之袋!', '<艾瓦若隐若现。>', '', '去西瘟疫之地找达隆米尔湖的艾瓦·萨克霍夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5517, '多彩黎明衬肩', '$n，你为银色黎明做出的贡献在这里被广为传颂。作为一种奖励，你将有资格获得我们特殊的多彩黎明衬肩，它可以帮你抵抗各种魔法效果。多彩黎明衬肩只会被授予最强大的英雄！$B$B交给我二十五枚勇气勋章作为你对银色黎明做出贡献的标志，然后我就会把我们最好的衬肩给你。', '把25个银色黎明勇气勋章交给东瘟疫之地圣光之愿礼拜堂的银色黎明军需官米兰达·布利洛克。', '干得好，$N!炫彩黎明披肩是你的了!$B$B只要你能够一直在银色黎明中保持受人崇拜的声望，那么你就可以从银色黎明组织的任何一个军需官那里购买更多的炫彩黎明披肩。', '向你致敬，强大的$C!你有没有带来我要的银色黎明勇气勋章?当你把它们交给我之后，我就会把炫彩黎明披肩给你。', '', '去东瘟疫之地找圣光之愿礼拜堂的军需官米兰达·布利洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5518, '戈多克食人魔装', '如果你想要和那个笨蛋食人魔国王作战，那么首先你必须通过克罗卡斯那一关。好吧，你当然可以杀了他，但实际上你也可以留他一条命。$B$B你问我该怎么做？嗯，你真好运，，我想我知道如何制作一件可以把你伪装成食人魔的服装，用来迷惑那些四肢发达的笨蛋。唯一的问题可能就是稳定性——这种衣服的持续时间最多为10分钟。把我需要的东西给我拿来，然后我就可以帮你做一件。我就等在这里……', '把4份符文布卷、8块硬甲皮、2卷符文线和一份食人魔鞣酸交给诺特·希姆加克。他现在被拴在厄运之槌的戈多克食人魔那边。', '嗯嗯，这些东西就够了。只需要这样，然后再这样……呵呵，太完美了!<被拴住的哥布尔露出粗犷的笑容。>$B$B大功告成，给你吧。记住―这东西并不保险。它的效力最多持续10分钟，然后你就露馅了!在接近他的时候使用它，记住……这套伪装服会让他以为你是他的盟友―只有你，不包括你的队友!', '我制作巨魔装所需要的材料中，巨魔鞣酸也许是最难找到的―我想也许你可以在这里的楼上找到一些?不过很难说，因为我被拴在这里寸步难行……$B$B不管怎样，把我需要的东西给我拿来，我就会帮你制作一件巨魔装，然后你就可以用它来欺骗克罗卡斯，因为他会以为你是自己人。', '', '去找厄运之槌的诺特·希姆加克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5519, '戈多克食人魔装', '', '', '好了，$N―穿上这个，你就变成一个巨魔啦!祝你好运!$B$B哦，对了，如果你碰巧找到可以打开这个镣铐的钥匙，无论如何都要告诉我!!!', '还要一件?好吧，看起来我一时半会也没法出去，那么你就像上次那样把材料给我拿来，我帮你把衣服做好。', '', '去找奥特兰克山脉的诺特·希姆加克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5521, '多彩黎明衬肩', '$n，你为银色黎明做出的贡献在这里被广为传颂。作为一种奖励，你将有资格获得我们特殊的多彩黎明衬肩，它可以帮你抵抗各种魔法效果。多彩黎明衬肩只会被授予最强大的英雄！$B$B交给我二十五枚勇气勋章作为你对银色黎明做出贡献的标志，然后我就会把我们最好的衬肩给你。', '把25个银色黎明勇气勋章交给西瘟疫之地冰风营地的银色黎明军需官莱斯巴克。', '干得好，$N!炫彩黎明披肩是你的了!$B$B只要你能够一直在银色黎明中保持受人崇拜的声望，那么你就可以从银色黎明组织的任何一个军需官那里购买更多的炫彩黎明披肩。', '向你致敬，强大的$C!你有没有带来我要的银色黎明勇气勋章?当你把它们交给我之后，我就会把炫彩黎明披肩给你。', '', '去西瘟疫之地找冰风岗的银色黎明军需官莱斯巴克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5522, '莱尼德·巴萨罗梅', '我从我的主人维克图斯那里收到了一个消息。好吧，其实不是从维克图斯那里来的……是来自于一个名叫莱尼德·巴萨罗梅的人。我不认识他，但是他认识我的主人。你要知道，除非我的主人允许，否则你是根本无从结识他的。$B$B他说维克图斯需要龙蛋，因此它要你把它们送到东瘟疫之地的圣光之愿礼拜堂去。$B$B这真让我恼火！为什么？难道维克图斯不相信我吗？哦，不要介意这些……把蛋交给莱尼德，告诉他我已经完成了主人的命令。', '把冰冻的龙蛋交给东瘟疫之地的莱尼德·巴萨罗梅。', '啊，很好。你根本不知道你在为谁效力，对吗?但是你现在将会知道真相。不要害怕―我不是那个所谓“主人”的仆从。我是莱尼德.巴萨罗梅，银色黎明的高层官员。$B$B我欺骗了丁奇，让她派你来到我这里，并把龙蛋送了过来。看来我的计谋成功了，如果龙蛋落到了它原本应该被送去的地方，一股巨大的力量就将落入邪恶势力的手中。', '你就是那个去过黑石塔的$r，是吗?你弄到我要的东西了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5524, '多彩黎明衬肩', '$n，你为银色黎明做出的贡献在这里被广为传颂。作为一种奖励，你将有资格获得我们特殊的多彩黎明衬肩，它可以帮你抵抗各种魔法效果。多彩黎明衬肩只会被授予最强大的英雄！$B$B交给我二十五枚勇气勋章作为你对银色黎明做出贡献的标志，然后我就会把我们最好的衬肩给你。', '把25个银色黎明勇气勋章交给西瘟疫之地亡灵壁垒的银色黎明军银色黎明军需官哈萨娜。', '干得好，$N!炫彩黎明披肩是你的了!$B$B只要你能够一直在银色黎明中保持受人崇拜的声望，那么你就可以从银色黎明组织的任何一个军需官那里购买更多的炫彩黎明披肩。', '向你致敬，强大的$C!你有没有带来我要的银色黎明勇气勋章?当你把它们交给我之后，我就会把炫彩黎明披肩给你。', '', '去提瑞斯法林地找亡灵壁垒的银色黎明军需官哈萨娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5525, '逃出生天！', '', '', '你真是太厉害了!谢谢你救了我!$B$B我就知道，我命中注定不会成为巨魔的开胃菜!', '我说的是戈多克镣铐钥匙―好吧，那些胖家伙是这么叫它的。任何巨魔都有可能拿着这把钥匙，不过我不清楚到底谁拿着它。没准那些卫兵是负责看管钥匙的……$B$B啊呀，我到底在想什么?你已经拿到钥匙了，对吧?', '', '去找奥特兰克山脉的诺特·希姆加克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5526, '魔藤碎片', '你对于埃雷萨拉斯——厄运之槌——的知识现在要派上用场了，$N。在那座城市的遗迹的东部区域，奥兹恩正在散播着自己的堕落力量。去那里击败所有胆敢挑战你的敌人。$B$B奥兹恩身边应该有一些丰饶之果，它们已经被堕落的力量腐蚀，变成了魔藤。在你干掉他之后，采集一块魔藤的精华，把它装在净化之匣里，然后带回来交给我。$B$B祝你好运，塞纳留斯保佑你快去快回。', '在厄运之槌中找到魔藤，然后从它上面采集一块碎片。只有干掉了奥兹恩之后，你才能进行采集工作。使用净化之匣安全地封印碎片，然后将其交给月光林地永夜港的拉比恩·萨图纳。', '你成功了，勇敢的$C，塞纳里奥议会欠你一个人情。虽然战争离结束还早得很，但是那些想要毁灭我们的家伙已经遭受了一次重大的打击。$B$B请你收下这个作为我们的回报。另外我要说的是，你将因为这一壮举而被塞纳里奥议会当成英雄来看待。谢谢你。', '拿到净化之匣后，我们不仅可以从世界上消除一股堕落的力量，而且可以谨慎理智地对其进行研究。也许我们可以找到与威胁艾泽拉斯的堕落力量抗衡的新方法。$B$B我知道米利会得到它的……', '', '去月光林地找永夜港的拉比恩·萨图纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5527, '净化之匣', '第一步是要找到一个可以容纳堕落物质而不受其影响的容器。我所能想到的只有一件可以容纳魔藤的东西：净化之匣。$B$B在希利苏斯有一处暗夜精灵的南风村，我知道很久很久以前那里曾有一个净化之匣。如果我们想要成功的话，我希望你先去那边的废墟中找到它。', '到希利苏斯的南风村去寻找净化之匣。然后将其交给月光林地永夜港的拉比恩·萨图纳。', '事实上，你确实如传言所说的那样强悍。塞纳里奥议会有你这样的$C帮忙真是太好了。$B$B有了净化之匣之后，我就可以稍微放松一些了。接下来，你将要面对一个强大的恶魔，并且还要带回一件危险的东西……', '净化之匣本身就是一件神器。最初制造出来的净化之匣数量不多，随着时间的推\r\n移，其数量越来越少。$B$B我承认，很早之前我就知道南风村中的那个净化之匣的存在了。老实说，随着希利苏斯不断出现新的混乱状况，我希望你能把这个秘密一直保持下去。过多地泄露这个秘密将会引起敌人更多的怀疑。$B$B啊，看来和平时期又要结束了，尤其是当埃德萨拉斯处于当前这种情况下的时候。', '', '去月光林地找永夜港的拉比恩·萨图纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5529, '瘟疫之龙', '银色黎明得到消息，据说亡灵天灾正在制造它们自己的瘟疫之龙！我们必须阻止他们——如果亡灵天灾得到了龙的力量，那么他们必将横扫艾泽拉斯！$B$B他们的亡灵巫师正在达隆米尔湖中间的通灵学院里繁殖瘟疫之龙。$B$B到通灵学院去，尽可能多地摧毁龙崽……别让它们长大！', '杀掉20只瘟疫龙崽，然后向圣光之愿礼拜堂的贝蒂娜·比格辛克复命。', '干得好，$N!他们再培养下一批龙还需要花费很长时间。$B$B……好吧，至少我希望如此!', '到通灵学院去，$N。一定要在那些染疫幼龙长大之前毁掉它们!', '', '去东瘟疫之地找圣光之愿礼拜堂的贝蒂娜·比格辛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5531, '贝蒂娜·比格辛克', '你带来的那些蛋本要被用于亡灵天灾制造瘟疫飞龙的试验中。这些冰冻的黑龙卵在他们的研究中有巨大的价值，也会毫无疑问地加快他们的时间表。$B$B现在，是我们结束他们研究的时候了。$B$B把这些冰冻的卵带给外面的贝蒂娜·比格辛克。她在科学和炼金术方面造诣很深，而且她还制造了一种我们可以用来对付亡灵天灾的武器。有了你的帮助，我们将会给他们一个沉重的打击。', '将冰冻的龙蛋交给贝蒂娜·比格辛克。', '啊，真是龙蛋!而且还装在这么漂亮的容器里!完美无缺!$B$B我们要把这些蛋放在安全的地方，便于日后研究，但当前我们得让它们保持原样。$B$B我制造了一个具有特殊功能的装置，可以用来消灭通灵学院里的不死生物学者。他们正在对龙类进行研究，想要制造出一支瘟疫之龙军团来，我们必须阻止他们!$B$B我把这一装置叫做黎明先锋，不过……我不敢肯定它是否真的有用!$B$B你能去帮我们试验一下吗?', '你好，$N!我听说你带来一些龙蛋?嗯，快让我看看!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5534, '基姆加尔“丢失”的装备', '什么？！什么？！$B$B你还不满足？你知道那些炸药有多贵吗？它们可以卖到……哦，算了。好吧，你想要赚点钱？做生意应该是这样的：首先你要证明自己是个有价值的雇员，然后你会因为勤奋工作而被奖励。$B$B如果你是个“有价值”的雇员，那么就到埃达拉斯废墟去，帮我把那些血精灵正在寻找的符石给拿回来，显然你得去跟废墟中的纳迦们打交道。', '寻找埃达拉斯废墟中的纳迦携带的那些符石，然后把它们交给艾萨拉的基姆加尔。', '哈哈，太好了!$B$B我一定会发现这里面的秘密，还有魔导师雷姆托里―那头母牛雇佣了我―想要得到这东西的原因。哈哈!我终于比你们抢先一步了，讨厌的血精灵!基姆加尔!哈!我会让他们知道谁才是废物!$B$B干得好，$N。非常感谢。给你，拿着这些钱，然后就走吧―我很忙。', '那么，$N，符石在哪里?你是个好的雇员，不是吗?你来这里是要帮我忙的吧?$B$B不要让我后悔付钱给你。什么?哦，我们之间没有达成任何协定?哦，太好了……那么你慢慢来吧―不过如果你浪费了很多时间的话，那是你的损失，不是我的。', '', '去艾萨拉找雷加什营地的基姆加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5535, '永不安息的灵魂', '很久之前，暗夜精灵中的上层精灵们是最优秀的魔法学徒。他们最终对暗夜精灵社会造成了很大的伤害，并且影响了艾泽拉斯世界的历史……我相信这些你都很清楚。$B$B我向那些哨兵保证要超度那些我遇见的上层精灵之魂。如果你也可以帮忙的话，我保证我会奖励你的。$B$B那些灵魂在这里东北边的影歌神殿附近游荡。', '杀掉6个上层精灵的幻影和6个上层精灵鬼巫，然后向艾萨拉的罗哈图复命。', '干得好，$C。感谢你的帮助，那些灵魂已经平静了，它们对于魔法的渴望被削弱了。$B$B艾泽拉斯大陆上的所有生灵都会感谢你的。', '你搜寻精灵贵族之魂的工作进行得怎么样了，$C?$B$B有很多事情使得整个艾泽拉斯都遭受了巨大的痛苦，但是因为某些原因，这些游魂对所有人来说好像一场瘟疫。也许它们仍然还是渴望着获得魔法的力量―这种渴望最终会引来燃烧军团，我们知道这意味着什么。', '', '去艾萨拉找塔伦迪斯营地的罗哈图。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5536, '充满仇恨的土地', '萨特是暗夜精灵畸形和邪恶的一面，现在他们正在玷污这片塞纳留斯曾经眷顾过的神圣之地。当提及这些恶魔的罪行时，我是不会给暗夜精灵留面子的，但是我已经向大地母亲发誓要帮助暗夜精灵除掉这些祸害。$B$B我相信你可以在净化他们的过程中证明自己的价值。$B$B在这里的东北面就是萨特的哈达尔氏族。与他们作战，然后再回到我这里来。', '杀掉6个哈达尔萨特、2个哈达尔欺诈者和2个哈达尔魔仆，然后向灰谷与艾萨拉交界处的罗哈图复命。', '干得好，$C。你的战斗技巧非常精妙娴熟。与这种邪恶的生物作战，这体现了你对大地之母的忠诚―即使你并不把她当成自己信奉的神灵。她在这个世界上无处不在。她的双目，一暗一明，在天空中不倦地穿行，俯瞰着我们。$B$B请你收下这些钱作为酬劳吧。', '你和萨特的战斗进行得怎么样了，$C?$B$B他们是不是如你想象中的一般强大呢?或者更强?', '', '去艾萨拉找塔伦迪斯营地的罗哈图。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5537, '骸骨碎片', '通灵学院大门的钥匙名叫骷髅钥匙，它一定是由某具骸骨制造而成——事实上是若干具骸骨——并在适当的模具中使用最坚硬的金属进行加固。天生就能打开通灵学院大门的人拥有一种特殊的力量，这种力量能让钥匙发挥作用。$B$B重要的事情要优先处理掉，$N。我们需要一些骸骨碎片来制造钥匙。安多哈尔内的骸骨应该符合我们的要求，但是安多哈尔城外的那些骸骨也许同样有效。', '将15块骷髅碎片交给西瘟疫之地冰风岗的化学家阿尔比顿。', '很好，$N!现在轮到我了―我将对这些骸骨进行适当的回火，使它们不至于在锻造过程中断裂。$B$B下一步就是获得钥匙的模具了，在塔纳利斯有个哥布尔铁匠，他曾经制作过类似的模具。跟其它的哥布尔一样，他也会为那些出价最高的人效劳的。', '虽然这听起来很恶心，但是我们确实需要许多合适的骷髅碎片来制作钥匙的外层部分。你要知道，如果没有这些东西，那它也不叫骷髅钥匙了。', '', '去西瘟疫之地找冰风岗的化学家阿尔比顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5538, '昂贵的模具', '你要找的地精的名字叫做克林科·古德斯迪尔。他在塔纳利斯的加基森镇里生活，为出价最高的顾客效力。看来他是唯一个可以帮我们完成融合工序的铁匠，不过他的标价会非常高，所以你来解决他的工钱。$B$B我是个炼金师，不是个银行家。如果我有一堆金子的话，还待在这里干什么？$B$B我相信我已经把事情说得很直白了，咳咳。$B$B加基森在等待你！祝你好运！', '把灌魔的骸骨碎片和15枚金币交给加基森的克林科·古德斯迪尔。', '阿尔比顿说你会把东西送过来，那就拿出来吧!让我把碎片和模具放在一起。$B$B阿尔比顿已经给它们附过魔法了?很好……否则的话，你就得再跑一趟冰风岗了。', '嗯，我知道你是谁，我也知道你来这里干什么。阿尔比顿在你来之前就跟我说过了。让我们长话短说吧，怎么样?$B$B我确实有可以用来制作骷髅钥匙的模具，但是它非常贵―15个金币，现货，不二价。我会把骷髅碎片放进模具里交给你，我也会教你如何铸造钥匙，即使你连一点锻造的相关知识都没有……这些都是免费的。$B$B谁说商人都是唯利是图的!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5541, '海格纳的弹药', '海格纳·重枪在安威玛尔出售枪支。火枪队和迫击炮小队都会花大量的时间在他的店铺里挑挑拣拣，所以他总是需要充足的新货物。$B$B但是……我送给他的最后一箱弹药在半路上不见了。送货的家伙说他当时在灰色洞穴附近扎营，然后来了几个雪怪把他给赶跑了……那个傻瓜就把海格纳的弹药留在那里了！$B$B$N，你能不能拿到那些弹药然后送到海格纳那里去呢？我敢说他的库存已经不多了。', '把海格纳的弹药交给丹莫罗的海格纳·重枪。', '很好，更多的弹药!罗斯洛的货终于来了!虽然有些晚，但是我爷爷说得好:来得晚总比不来的好!$B$B非常感谢你，$N。准备买弹药的顾客已经要踏平我的小店了!', '我希望你不是来买弹药的，因为我已经没有库存了!', '', 'Return to Hegnar Rumbleshot in Dun Morogh.', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5542, '恶魔之犬', '如果你愿意留在这里，那么我希望你可以做些事情来证明自己的价值。我们有许多麻烦的事情要让你这样训练有素的$c去做。$B$B你可以先从瘟疫犬和它们的幼崽开始。$B$B我无法提供很多报酬，但是如果你成功的话，回来跟我一起饱餐一顿，然后聊聊天也是不错的嘛。', '杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。', '干得好，$N。来，休息一下。让我们吃点东西，然后谈谈以前的事情吧!', '不要同情那些恶魔之犬，$C。它们是令人憎恶的东西!', '', '去西瘟疫之地找索多里尔河的提里奥·弗丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5543, '血染的天空', '踏入瘟疫之地的人真是愚蠢而又悲哀。各种各样邪恶的生物在这里徘徊——狂热的血色十字军会杀死一切不愿与他们同流合污的人，凶恶的天灾军团会不断地扩充亡灵的数量。$B$B即使是普通的野生动物也已经变为了凶残的食人猛兽。我请求你去杀掉那些从空中袭击无辜者的生物，瘟疫蝙蝠。', '杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。', '你是正义的化身，$C!我又一次感觉到了英雄的鲜血在我的血管中流动，这真是久违的感觉。你英勇的行动让我再次振奋了!', '不要低估那些有翅膀的恶魔，$C。瘟疫让它们获得了超自然的能力。', '', '去找西瘟疫之地的提里奥·弗丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5544, '腐肉虫', '我的食品储备已经很少了，$r。我不得不承认，现在我已经没有可以和你分享的食物了。$B$B你能不能帮我这个老人一个小忙？这附近唯一没有被瘟疫感染的生物是食腐虫。虽然它们味道并不好，但是它们的肉可以储存好几个月。我要为即将来临的冬天存储数百磅的肉！', '在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。', '愿圣光永远照耀着你!祝福你，年轻的$r。', '你慢慢就会习惯它的味道的，$N。', '', '去找西瘟疫之地的提里奥·弗丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5545, '木材危机', '我现在真的是碰到棘手问题了。我有一批木材的订单马上就要到期了，但我抽不出时间来解决这事情。北边的狼和熊把我的工人追得满地跑，否则的话他们早就把木材的问题解决了。$B$B我和瑞尼尔副队长谈过，要他帮忙清理那些动物，但是眼下我得找人帮我去收集足够的木材。如果你可以帮我收集八捆木材的话，我就可以按时完成订单了。', '收集8捆木材，把它们交给东谷伐木场的管理员莱琳。', '太好了!这样我就应该可以按时完成订单了。为了表示感谢，请收下这些银币。$B$B谢谢你，再见。', '期限马上就要到了，$C。请马上帮我收集一些木材。', '', '去艾尔文森林找东谷伐木场的管理员莱琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5561, '诱捕科多兽', '比布里认为他是凄凉之地唯一一个懂得赚钱的地精。好吧，唯一一个有胆量闯过这块地方的商队就是我了。因为我懂得利用我的科多兽诱引器控制年老的和濒死的科多兽，所以我和商队的老板——考克和里格尔——进行了合作。$B$B把诱引器拿去，对任何一头年老的或者濒死的科多兽使用，然后那头野兽就会变成驯服的科多兽并跟着你。你每驯服一头科多兽，就把它给我带来。', '将科多兽诱引器和5头被驯服的科多兽交给瑟卡布斯库的营地中的斯米德·瑟卡布斯库。', '<斯米德.瑟卡布斯库开始计算科多兽的数量。>$B$B三，四，五……很好，我要五头科多兽，现在你给我带来了五头……我要发财了……嗯，发大财!我真想知道，如果比布里听说我成功了，他的脸色会难看到什么程度。', '商队就要来了，我要的5头科多兽呢?', '', '去凄凉之地找瑟卡布斯库的营地的斯米德·瑟卡布斯库。', '驯服科多兽', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5581, '燃烧军团的传送门', '看，这就是埃鲁索斯之手。真是恐怖的景象。$B$B你必须使用它才能放逐玛诺洛克集会所的恶魔之门……现在我就要求你去做这件事情。恶魔的威胁正在不断增大，我们必须关闭这些传送门来阻止恶魔进入这个世界。祝你好运，$N……小心那些传送门的守护者。', '放逐6个玛诺洛克集会所的传送门，然后回到葬影村的泰迦·慧鬃那里。', '你应该得到称赞，$N。你的努力对这场与恶魔进行的战斗产生了重大的影响，现在整个艾泽拉斯都因此而变得更加安全了。', '你有没有放逐玛诺洛克集会所里的恶魔传送门?', '', '去凄凉之地找葬影村的泰迦·慧鬃。', '放逐传送门', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5582, '健康的龙鳞', '这是一块被瘟疫感染的龙鳞，但是它不像别的幼龙鳞片那样遍布麻点、柔软无力，这块鳞片的质量很好，而且没有任何损坏。$B$B贝蒂娜·比格辛克需要这样的东西来进行研究。', '把健康的龙鳞交给东瘟疫之地圣光之愿礼拜堂中的贝蒂娜·比格辛克。', '太好了!这可以极大地帮助我对天灾军团的阴谋进行研究。谢谢你，$N，如果你找到更多这样的鳞片的话，请把它们都交给我!', '$N，你有什么东西要给我看的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5621, '月光之衣', '我需要你的帮助，$N。我因为要在这里训练别的学生而无法分身，但是你可以帮我去救助多兰纳尔南边的一位受伤的哨兵。她在小镇附近巡逻的时候受伤了，急切地需要我们的帮助。她的名字叫莎恩雅。$B$B你找到她之后就治疗她的伤口，然后使用你的法术帮助她恢复健康，这至少可以让她轻松一些。如果你完成了这一使命，就回到我这里来。', '找到哨兵莎恩雅并使用次级治疗术（等级 2）来治疗她。然后对她施放真言术：韧，最后向多兰纳尔的劳尔娜·晨光复命。', '你出色地为艾露恩完成了任务，因此我感谢你。$B$B请你收下这件袍子，这是我对你的感谢。它标志了你已经在我们当中赢得了自己的位置。如果你愿意的话，请带着荣耀穿上这件袍子吧。$B$B愿艾露尼与你同在，艾露恩与你同在，$N，再次谢谢你。', '我们的真言术:韧这个法术非常强大，$N。它可以让我们的同伴承受更多的攻击，让他们在任何情况下都能生存得更久。但是我们的治疗更加无与伦比，世界上没有比牧师更加强大的医者了―你要牢记这些。你的力量足以轻易改变一场战斗的走向。', '', '去多兰纳尔找罗兰纳尔的劳尔娜·晨光。', '治疗并强化哨兵莎恩雅', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5624, '圣光之衣', '一般来说，我会给那些圣光的追随者布置一个小小的挑战来测试他们的能力。我要看看他们是否值得穿着他们的第一件圣光之袍——那是$g他:她;他在教会中的地位和身份的标志。$B$B但是这次情况有所不同。闪金镇的一个居民报告说，这里东面的湖边上有一位受伤的守卫，他的名字叫罗伯兹。找到他，治疗他，强化他的身体，然后回到我这里来。如果你能为我做这些的话，我会认为你已经通过了试炼。', '找到卫兵罗伯兹并使用次级治疗术（等级 2）来治疗他。然后对他施放真言术：韧，最后向闪金镇的女牧师洁塞塔复命。', '太好了，$N。多了一个健康的守卫，我们就会更加的安全。我很高兴看见你已经能聪明地使用你的技能，如果你在任何时间觉得自己已经准备好要接受更多训练的话，请回来找我。但是现在，请收下这件长袍，它会让别人知道你是我们的其中一员。如果你不想穿它的话也无所谓。未来还有很多试炼要让你去完成，这件袍子并不是必要的。$B', '就如同你所了解的，在日前这种艰苦的时期中，我们的治疗法术对我们的生存是非常重要的—特别是对于那些使用武器和魔法对抗许多不同威胁的冒险者和英雄们。$B$B牢记这些技能的重要性。使用真言术:韧，你的战友就可以在战斗中活得更久，可以承受更多次的攻击，也能让你表现得很好。$B$B不要让任何人忽视你所掌控的魔法力量。', '', '去找艾尔文森林的女牧师洁塞塔。', '治疗并强化卫兵罗伯兹', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5625, '圣光之衣', '现在是时候看看你的力量是否值得穿着象征教会的长袍了。但是老实说，我现在有更重要的事情要做。卡拉诺斯的居民向我报告说，这里的南边有一位受伤的巡山人——他的名字叫多尔夫。$B$B治疗他，然后给他加上真言术：韧，如果你完成了这些，你就证明了自己的价值。这听上去怎么样？', '找到巡山人多尔夫并使用次级治疗术（等级 2）来治疗他。然后对他施放真言术：韧，最后向卡拉诺斯的马克萨恩·安沃尔复命。', '做得好，$N。圣光的力量与你同在，这一点是肯定的。$B$B拿着这件长袍，它是你为教会效力的证明，还可以表明你的牧师身份―如果愿意的话，你可以马上穿上它。$B$B以后你还会遇到很多的试炼，尽可能地理解你所掌握的技能，在战斗和旅途中锻炼吧。$B$B但是不要畏惧任何敌人……你和他们一样强大。', '你找到多尔夫了吗，$N?$B$B也许你已经知道了这些，但是，我们的治疗技能确实非常有用。我们不仅仅能治疗受伤的人，而且对于那些未来的英雄或者想要打向自己名字的人的生命也非常重要。使用\r\n真言术:韧，我们就可以让自己和伙伴们变得更加耐打，而我们的治疗法术能让他们活得更久，没有什么是我们不能克服的!', '', '去丹莫罗找闪光岭的马克萨恩·安沃尔。', '治疗并强化巡山人多尔夫', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5648, '灵魂之衣', '你准备接受你的第一次试炼了吗，$N？我们的一个步兵因为与普罗德摩尔的旧部战斗时不慎受伤了，她就在剃刀岭南边，现在她的情况似乎比较危险，我们应该帮帮她。找到步兵科雅，治疗她的伤口，然后用我们祖先的祝福强化她的躯体。$B$B如果你做到了这些，那么你就证明了自己的能力和价值。', '找到步兵科雅，用次级治疗术（等级 2）治疗她，然后为她加上真言术：韧，最后向剃刀岭的泰金复命。', '很好，科雅活了下来，她可以继续为抵抗那些邪恶的人类而战斗了。我经常想起以往的战斗，智慧与力量并用的勇士总是可以击败那些只会依仗蛮力的家伙。$B$B你做得很好，$N。现在拿着这件袍子吧。虽然你可能用不到它，但是它也许会对你有用。', '许多人都知道治疗法术非常强大，但是他们并不知道它有多么强大。你可以拯救无数即将消逝的生命，让他们不致过早地在另一个世界见到他们的祖先。治疗法术与真言术:韧的结合是非常强大的，你要牢记这一点。无论是战士、法师，还是其它的职业，都会很需要你的这种能力。', '', '去杜隆塔尔找剃刀岭的泰金。', '治疗并强化步兵科雅', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5650, '黑暗之衣', '我们的力量来自黑暗和阴影，$N，但是那不是你唯一的角色。你已承认了治疗术的价值，这是很明智的。但是如果你要了解黑暗，那么你还必须了解光明。对于这一点，我为你准备了一个试炼。$B$B墓地以北有一个受伤的亡灵卫兵，他名叫科尔。他曾保护我们免受豺狼人的伤害，现在他需要治疗。但是，你还必须在他能重回岗位之前增强他的体力。使用你的法术完成任务，然后回到我这儿来。', '找到亡灵士兵科尔并使用次级治疗术（等级 2）来治疗他。然后对他施放真言术：韧，最后向布瑞尔的黑暗牧师贝里尔复命。', '你已轻松地通过了我的试炼，好极了。$B$B你很快就能承担更多的责任，这将引领你更深刻地了解黑暗的力量―没有其它哪个种族的牧师能掌握这样的力量。$B$B穿上这件象征你身份的长袍吧，它已经是你的了。要是你实在不愿意穿，那你可以随心所欲地处理它。我和其它同伴将始终承认你在我们当中的地位。', '我们的力量使我们足可应对如此多的状况，$N。你很快就会发现，无论情况如何糟糕，疗伤和增强同伴耐力的法术始终都是我们最强大的技能，不过你可别因此觉得自己没什么前途，因为你完全可以在其它方面也大展身手。但是话说回来……如果你真的希望使用魔法的力量来摧毁我们的敌人，或许秘法魔法会更适合你……', '', '去提瑞斯法林地找布瑞尔的黑暗牧师贝里尔。', '治疗并强化亡灵卫兵科尔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5713, '一击必杀', '我本来是带着一封重要的信件往奥伯丁去，但是熊怪玛洛什带着它的爪牙袭击了我。在这次攻击事件中，我不慎中毒了，现在我几乎无法站起来。当然，我可以制作解毒药，但是这需要花些时间。$B$B你能在我制作解毒药的时候保护我吗？我会尽力协助你的。$B$B如果我们活下来的话，我就动身把那封信送到奥伯丁去，而你负责向迈斯特拉岗哨的奥奈雅报告这件事情。', '保护哨兵阿娜莎，然后向灰谷迈斯特拉岗哨的奥奈雅报告。', '这真是个好消息，$C。我很高兴得知阿娜莎还活着，谢谢你。请收下这个作为我对你英勇事迹的奖励。愿艾露恩照耀你的道路。', '你在路上看到哨兵阿娜莎了吗?她正在执行重要的任务，不过直到现在她还没有回来。', '保护阿娜莎', '去找灰谷的哨兵奥奈雅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5721, '达隆郡的战斗', '现在，$N，你将参加达隆郡的战斗，并且拯救约瑟夫·雷德帕斯。$B$B把这个遗物包裹放到达隆郡的广场中，达隆郡居民的灵魂将因此而被唤醒。参加他们的战斗，并确保你完成两件事：在霍古斯死后，达维必须存活；雷德帕斯必须存活，直到他被腐化而堕落，此时再将其击败。$B$B在打败了堕落的雷德帕斯之后，他的灵魂就将得到救赎。同他交谈，然后再去找他的女儿帕米拉。', '将遗物包裹放在达隆郡的广场中。$B$B在霍古斯死亡之前，达维必须存活。$B$B在雷德帕斯队长堕落之前保证他存活。$B$B击败堕落的雷德帕斯。$B$B当约瑟夫·雷德帕斯出现在广场中时，与他的灵魂进行交谈，然后回到帕米拉的家中去找帕米拉。', '战斗结束了!我听见爸爸在跟我说话。他吓跑了所有鬼魂，而且他说他正在回家的途中!我太高兴了!$B$B他还说要是你来到我们家，我就得好好欢迎你，所以我已经沏好了茶!$B$B希望你喜欢喝加了好多好多糖的茶水!', '我想我听到了外面那些鬼魂的声音。他们在低声告诉我一些可怕的事情……', '', '去东瘟疫之地找达隆郡的帕米拉·雷德帕斯。', '接受雷德帕斯的宽恕', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5723, '试探敌人', '在奥格瑞玛城的地下，那些被称为穴居人的生物正在从充满岩浆的管道深处源源不断地涌出来。玛加萨心怀仁爱，试图与这些生物和平相处，但是他们却对她派出的外交官大开杀戒。她绝不允许牛头人受到这样的待遇，现在她将穴居人看作是整个部落的威胁。$B$B她希望你在穴居人毁灭部落之前消灭他们——找到怒焰裂谷，把他们全都杀掉。', '在奥格瑞玛找到怒焰裂谷，杀掉8个怒焰穴居人和8个怒焰萨满祭司，然后向雷霆崖的拉哈罗复命。', '很高兴看到你能如此认真地执行玛加萨的任务。谢谢你，$N。我想随着穴居人数量的锐减，他们将更难于在地表上站住脚。$B$B或许将来我们可以搞清楚这种生物来自何方，他们想要干什么。', '搜寻怒焰裂谷的工作进行得怎么样了?穴居人呢?$B$B我们绝不允许它们的威胁继续存在―这只会伤害到我们的兽人同胞。', '', '去雷霆崖找长者高地的拉哈罗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5724, '归还背包', '你在牛头人的尸体上发现了一个小包。他的手臂紧紧地夹着它，似乎在被穴居人攻击时还试图保护这个小包。$B$B你从他那钳子般紧握的手臂中取出小包，装入你自己的行囊，准备离开隧道返回雷霆崖的拉哈罗那里去。', '将恐怖图腾背包交给雷霆崖的拉哈罗。', '棒极了，$N。谢谢你。$B$B玛加萨告诉我说，如果你成功地找到了她的族人，就把这个交给你。请收下它吧，这代表着我们的谢意。', '你找到什么东西了吗，$N?我想知道为什么她的族人要做出无谓的牺牲，任何有关的线索都会对我们很有帮助的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5725, '毁灭之力', '你知道，燃烧军团的许多追随者都得到过它们的主子赐予的礼物。黑暗女王认为，某些有价值的东西与其被那些鼠目寸光的渣滓拿着，倒不如为自己所用。$B$B暗影议会的一支势力隐藏在奥格瑞玛地下的洞穴中，他们被称为燃刃氏族。黑暗女王告诉我，燃刃氏族的成员拥有两本强大的法术书——她想“借”来看一看。你去取回这些书吧。', '将《暗影法术研究》和《扭曲虚空的魔法》这两本书交给幽暗城的瓦里玛萨斯。', '好极了，$C。你在为黑暗女王效力的过程中表现得很出色。你的坚定不移和雄心壮志将极大地帮助黑暗女王实现她的目标。下次再来我这儿吧，也许我会布置其它的任务给你，帮助黑暗女王取代巫妖王，并彻底瓦解天灾军团。', '我还有好几百个任务要执行，$C。你取到书了吗?', '', '去幽暗城找皇家区的瓦里玛萨斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5726, '隐藏的敌人', '如果说有什么是我绝对不能容忍的，那就是我们当中的背叛者。但是我过早地插手这件事，真有些愚蠢——这不仅不能有效地清除那些堕落者，反而使得叛徒越来越多。$B$B但是，你，年轻的冒险者，你可以进入那些我的密探所不能到达的地方……你能发现真相……你能找出那些叛徒的幕后主使。$B$B如果你足够勇敢的话，就去奥格瑞玛东边的骷髅石，找到火刃氏族军官的徽章，然后回到我这儿来。', '将军官的徽章交给奥格瑞玛的萨尔。', '好极了，$N!我们的士气得到了鼓舞，也许你正是那个可以帮我除掉心头大患的勇士!你迅速成长并支持着我们的事业，有谁会怀疑像你这样勇敢而年轻的$r?你让我想起了自己年轻的时候。如果我们在即将来临的风暴之后仍然屹立不倒，那么我保证你会得到应有的回报。$B$B但是，赞扬的话留到以后再说吧。与你即将面临的威胁相比，你还没有做成什么大事呢……不过这是一个好的开端。', '你拿到了徽记吗，$N?$B$B它将是你渗透到火刃氏族中去的重要工具，我认为他们是部落的最大威胁，也是我们刚刚得到的和平的最大威胁。$B$B你会发现，当人类或是兽人受到贪欲和权力驱使时，他们会干出多么可怕的事情来。那些阴暗的勾当和隐藏的敌人终将露出真面目来。你将发现自己置身于一场你从未想象过的战争中。', '', '去找奥格瑞玛的萨尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5727, '隐藏的敌人', '让我们看看你找到的徽章是否有价值。$B$B城中有一个术士，他认为自己已经得到了我的信任，但是他并不知道我很了解他真正效忠的主人是谁。他实际上是火刃氏族的领袖。先别急着跟他开战，因为他还有用处，我们可以利用他来对付我们的敌人。$B$B去奥格瑞玛的暗影裂口找他，把这枚徽章交给他，跟他谈谈，看他是否相信你是他的同伙，然后回到我这儿来。', '将军官的徽章交给尼尔鲁·火刃并与他谈一谈，看看他是否相信你是火刃氏族中的一员，然后回到奥格瑞玛的萨尔那里。', '很好!太棒了，$C!$B$B今天你所做的事情仅仅是更为宏大的事业的第一步，这项事业就是彻底摧毁暗影议会。$B$B把他的话原原本本地告诉我……不要漏掉哪怕一个字，这比你所能想象的更加重要。', '嗯，$C?他相信我们了没有?要不然就是事情比预计的更加糟糕?$B$B向尼尔鲁证明你的价值，这样我们就更容易进入暗影议会。我们可以利用他提供的大量情报找到真正的幕后主使。', '看看尼尔鲁·火刃是否相信你是火刃氏族的成员', '去找奥格瑞玛的萨尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5728, '隐藏的敌人', '嗯，灼刃氏族的首领……这可是件至关重要的事。如果他们是尼尔鲁的干将，那他们就是我们的首要目标。这个萨特……巴扎兰，以及另一个尼尔鲁提及的家伙——他是干什么的来着，是个术士？——必须被除掉。$B$B回到怒焰裂谷去，$N。找到灼刃氏族的两名首领，杀死他们。但是别让尼尔鲁知道是你干的。你必须继续伪装成他的忠实追随者，不要暴露身份。', '杀死巴扎兰和祈求者耶戈什，然后回到奥格瑞玛的萨尔那里。', '很高兴你回来了，$N。我的眼线已经告诉我了，由于首领被杀，奥格瑞玛地下的洞穴之中乱成一团。甚至有报告称尼尔鲁陷入了极度的惊恐和不安。我们这一步走得非常成功，即使是这样的小胜利，也让我感到了喜悦。', '你找到他们了吗，$N?我是说灼刃氏族的领袖。$B$B我知道暗影议会想要从我手中夺走奥格瑞玛以及整个部落，但是我还不清楚他们能以多快的速度渗透到这座城市里来。这群叛徒拥有如此大的势力……我们可以全力以赴，奋勇杀敌，直至筋疲力尽，但是情况并不会好转多少。我必须让我的探子更活跃一些。', '', '去找奥格瑞玛的萨尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5741, '圣光节杖', '据说，东边雷斧要塞中的火刃氏族从纳迦那里得到了圣光节杖。那根节杖的力量足以让整座城市瞬间沉入无尽之海中。这样的力量一定不能落入火刃氏族的魔掌！$B$B你必须去拿回节杖！它在一个火刃先知手中，那个先知就待在某座雷斧哨塔的顶部。', '拿到圣光节杖，并将它交给艾瑟雷索塔里的阿佐尔·奥达蒙特。', '强大的圣光权杖!你终于拿到它了，这个世界上又少了一个巨大的威胁。干得好，$C，干得非常好。', '你拿到圣光权杖了吗?', '', '去凄凉之地找艾瑟雷索的阿佐尔·奥达蒙特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5742, '救赎', '你干得很好，朋友。休息一下，然后听听我的自我介绍。', '听听提里奥·弗丁要说什么。', '弗丁的救赎是一个困难的任务，你准备好了吗?', '朋友，请你坐下听听我的故事。', '提里奥的故事', '去西瘟疫之地找索多里尔河的提里奥·弗丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5761, '饥饿者塔拉加曼', '我们伟大的酋长交给我的首要任务就是搜寻那些利用恶魔的力量破坏城市的敌人。火刃氏族是个威胁，但是这里还存在着其它的威胁，比如在怒焰裂谷安家的燃刃氏族，他们暗地里计划着袭击部落的无辜民众。$B$B要想阻止他们，就必须杀死他们的领袖——那个被称作饥饿者塔拉加曼的恶魔守卫。$B$B杀死他，萨尔看到他的精华之后一定会安心很多，这点我可以确信。', '进入怒焰裂谷，杀死饥饿者塔拉加曼，然后把他的精华交给奥格瑞玛的尼尔鲁·火刃。', '啊!你成功了!萨尔会很满意的。$B$B我会好好看管这颗心脏。$B$B庆祝你的胜利吧，我将把你的名字告知萨尔。$B$B感谢你的帮助，$C。', '你杀死那头野兽了吗?他一定是怒焰裂谷中那些灼刃氏族成员的首领。', '', '去找奥格瑞玛的尼尔鲁·火刃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5762, '赫米特·奈辛瓦里二世', '我有个包裹要给我的老顾客，一个名叫赫米特·奈辛瓦里二世的矮人。这个包裹花了几个星期才到我这里，那时候赫米特早就走了。他说他要去荆棘谷打猎，但是他给我留了一些钱，让我在有必要的时候把他的包裹寄给他。$B$B赫米特是个富有的矮人，所以我们最好和这号人物保持良好的关系，是不是？那么…\r\n…你愿意帮我递送包裹吗？$B$B我听说赫米特在荆棘谷里扎了营，就在格罗姆高的北边。', '将克拉维尔的箱子送到荆棘谷的赫米特·奈辛瓦里二世那里。', '太好了，浓须给我的包裹!谢谢你，$N。这个木箱里装着特别尺寸的弹药 - 我父亲发誓 - 这对我们在丛林中很有帮助!$B$B这是你应得的报酬，告诉我，那个易怒的老克拉维尔最近过得怎么样?我打赌他还是不太好……', '你的领子上是沙漠的尘土吗?$B$B嗯……如果我的鼻子没有毛病的话，那不是沙漠上的尘土，是沙漠盐!你去过闪光平原了，是不是?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5763, '荆棘谷狩猎', '很久以前，有一个矮人来到这片土地上。他的名字叫做赫米特，他的目标是狩猎强大的野兽。他用起火枪来简直是出神入化，我们在一起狩猎了很多天，甚至遗忘了不同种族之间的隔阂与憎恨。$B$B现在他离开凄凉之地去了荆棘谷，我期待有一天他可以回来，这样我们就可以再次一起狩猎了。不过，他现在到一个未知的世界去狩猎了，所以他的儿子接替了他的位置。$B$B把这支科多兽角交给赫米特二世……我听说他在荆棘谷里扎了营，就在格罗姆高的北边。', '将鲁恩的科多兽角送到荆棘谷的赫米特·奈辛瓦里二世那里。', '啊，这支角是属于一个牛头人的，鲁恩.蛮鬃。我父亲常提起他们一起狩猎凄凉之地野兽的美好时光。那么说来鲁恩是要邀请我加入他，是不是?$B$B我们现在正在丛林中，但是仍然谢谢你，$N。也许我下次远征会回到凄凉之地去，回到那片半人马的土地。', '坐下，$C。不久之后，你就要重新杀入丛林之中了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5781, '遗忘的记忆', '为了帮泰兰找回他失去的东西，你必须收集他过去曾经使用过的物品。$B$B第一件是一个玩具，那是他7岁的时候我送给他的。这个玩具是他最珍爱的礼物：一只小小的战锤，那是我的战锤的复制品。$B$B在我因叛国罪而被驱逐出去的时候，他妈妈告诉他我已经死了。他被带到了我的“坟墓”前，就在南边的墓室旁边，把那只小战锤和对我的记忆永远地埋在了那里。$B$B你必须去一趟墓室，拿回泰兰之锤。', '到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。', '<提里奥眨了眨眼睛，忍住将要流出来的泪水。>$B$B命运安排了我们的相遇，$N。你已经用你的仁慈善良赐福给我了。', '他必须得到救赎。', '', '去西瘟疫之地找索多里尔河的提里奥·弗丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5801, '火羽山', '你需要两块瑟银锭和一个强大的热源来锻造钥匙的主体部分。你得自己去找瑟银，但是我可以帮你找到热源。$B$B我们西面的安戈洛尔环形山里有一座温度极高的火山，它被称作火羽山。山顶的岩浆足以把瑟银和骨头熔在一起。你只需把买来的模具浸入熔岩湖中，然后就不用管其它的了。$B$B我的任务这就算是完成了。要完成你的钥匙的话，你还得去跟阿尔比顿再谈谈。', '把骷髅钥匙模具和2块瑟银锭带到安戈洛尔环形山地区的火羽山顶部。在熔岩湖旁使用骷髅钥匙模具，铸造出一把未完工的骷髅钥匙。$B$B把未完工的骷髅钥匙交给西瘟疫之地冰风岗的化学家阿尔比顿。', '我们终于拿到这支花费巨大的骷髅钥匙啦，$N!但是它还差一点才能完成，我们还得继续努力。最终，你将要面对安多哈尔城中的强敌……那个在废弃的城墙中徘徊的邪恶生物。$B$B我说的是『召唤者』阿拉基，一个巫妖，天灾军团中最强大的爪牙之一。', '你铸造出骷髅钥匙的主体部分了吗?很抱歉你得自己掏钱来买这个模具，但是我们必须各尽所能地共同对抗天灾军团。一旦你把未完成的钥匙交给我，你就可以开始准备铸造钥匙所需的最后一件物品了。$B$B虽然这并不简单，但是你为了进攻安多哈尔所做的准备将会初见成效。你会看到的。', '', '去西瘟疫之地找冰风岗的化学家阿尔比顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5802, '火羽山', '你需要两块瑟银锭和一个强大的热源来锻造钥匙的主体部分。你得自己去找瑟银，但是我可以帮你找到热源。$B$B我们西面的安戈洛尔环形山里有一座温度极高的火山，它被称作火羽山。山顶的岩浆足以把瑟银和骨头熔在一起。你只需把买来的模具浸入熔岩湖中，然后就不用管其它的了。$B$B我的任务这就算是完成了。要完成你的钥匙的话，你还得去跟迪瑟斯再谈谈。', '把骷髅钥匙模具和2块瑟银锭带到安戈洛尔环形山地区的火羽山顶部。在熔岩湖旁使用骷髅钥匙模具，铸造出一把未完工的骷髅钥匙。$B$B把未完工的骷髅钥匙交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。', '我们终于拿到这支花费巨大的骷髅钥匙啦，$N!但是它还差一点才能完成，我们还得继续努力。最终，你将要面对安多哈尔城中的强敌……那个在废弃的城墙中徘徊的邪恶生物。$B$B我说的是『召唤者』阿拉基，一个巫妖，天灾军团中最强大的爪牙之一。', '你铸造出骷髅钥匙的主体部分了吗?很抱歉你得自己掏钱来买这个模具，但是我们必须各尽所能地共同对抗天灾军团。一旦你把未完成的钥匙交给我，你就可以开始准备铸造钥匙所需的最后一件物品了。$B$B虽然这并不简单，但是你为了进攻安多哈尔所做的准备将会初见成效。你会看到的。', '', '去提瑞斯法林地找亡灵壁垒的药剂师迪瑟斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5803, '阿拉基的圣甲虫', '召唤者阿拉基在一次莫名其妙的胜利之后占据了安多哈尔。我们知道他以前曾是通灵学院的领导者，为了完成钥匙，我们就必须拿到他的那个被称作圣甲虫的图章，用它来制作钥匙的头部。$B$B攻入他的要塞，把他干掉。$B$B杀掉召唤者阿拉基之后，就把他的圣甲虫给我拿回来！$B$B通灵学院的钥匙在等着你，$N！', '杀掉召唤者阿拉基，并将阿拉基的圣甲虫交给西瘟疫之地冰风岗的化学家阿尔比顿。', '没错，就是它!我……我又一次被你的英勇慑服了。我相信你一定愿意为了战胜黑暗而努力。$B$B现在该轮到我来尽点力了。我准备了一个特殊的溶剂让我可以把圣甲虫镶在钥匙的头部，这样它就能具有打开通灵学院大门的力量。$B$B没什么难的……', '你必须明白，$N―只有摧毁『召唤者』阿拉基的肉身才能拿到完成钥匙所必需的材料。把阿拉基的圣甲虫交给我，我会将它制成钥匙的头部。', '', '去西瘟疫之地找冰风岗的化学家阿尔比顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5804, '阿拉基的圣甲虫', '召唤者阿拉基在一次莫名其妙的胜利之后占据了安多哈尔。我们知道他以前曾是通灵学院的领导者，为了完成钥匙，我们就必须拿到他的那个被称作圣甲虫的图章，用它来制作钥匙的头部。$B$B攻入他的要塞，把他干掉。$B$B杀掉召唤者阿拉基之后，就把他的圣甲虫给我拿回来！$B$B通灵学院的钥匙在等着你，$N！', '杀掉召唤者阿拉基，并将阿拉基的圣甲虫交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。', '没错，就是它!我……我又一次被你的机敏和勇敢折服了，我相信你一定愿意为了获得最终的胜利而努力。$B$B现在该轮到我来尽点力了。让我把圣甲虫镶在钥匙的头部，这样它就能具有打开通灵学院大门的力量。$B$B没什么难的……', '你必须明白，$N―只有摧毁『召唤者』阿拉基的肉身才能拿到完成钥匙所必需的材料。把阿拉基的圣甲虫交给我，我会将它制成钥匙的头部。', '', '去提瑞斯法林地找亡灵壁垒的药剂师迪瑟斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5805, '欢迎！', '欢迎来到魔兽世界！$B$B为了感谢您购买魔兽世界典藏版，请将这张礼券交给闪金镇的梅里萨·斯蒂维尔。您将得到一份特别的礼物：陪伴您踏上冒险旅途的小宠物！$B$B再次感谢您的支持，请尽情享受魔兽世界的乐趣吧！', '将闪金镇礼品券交给闪金镇的梅里萨·斯蒂维尔。', '您一定会成为一个真正的英雄，$N。欢迎您来到艾泽拉斯世界，请从我们为您精心准备的特殊礼品中挑选一件吧!', '您好!很高兴见到您!$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5821, '雇佣保镖', '一般来说，里格和我会率领我们的科多兽商队经过科卡尔半人马的领地。我们不时地听到半人马的战鼓声，而每当听到那种可怕的声音，我们就会停下。为了挣几个钱把命送掉可不值得！$B$B你猜怎么着，$c，如果你保护我们通过科尔卡半人马的村庄，我们会给你相应的报酬。$B$B这段路程很短，你需要做的就是让商队免受损失，然后你就可以从斯米德·瑟卡布斯库那里领取你的奖赏了——他在就在路的那一边。我们有些生意上的往来。', '护送基泽尔顿商队通过科卡尔半人马村，然后与瑟卡布斯库的营地中的斯米德谈话以领取你的奖赏。', '你知道，为了护卫基泽尔顿商队而付钱给你这样的$r并不怎么让我放心。如果我再高一点的话，我就能兼职打一份工，拿着我能拿动的最大号的枪坐在科多兽背上保护商队……我会让那些该死的半人马知道谁才是真正的大爷!$B', '为什么我要等那可恶的商队?$B$B<斯米德看起来若有所悟。>$B$B哦，对了，他们付钱。你看到他们了吗?', '护送基泽尔顿车队穿过科卡尔半人马的村庄', '去凄凉之地找瑟卡布斯库的营地的斯米德·瑟卡布斯库。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5841, '欢迎！', '欢迎来到魔兽世界！$B$B为了感谢您购买魔兽世界典藏版，请将这张礼券交给卡拉诺斯的尤里·碎盔。您将得到一份特别的礼物：陪伴您踏上冒险旅途的小宠物！$B$B再次感谢您的支持，请尽情享受魔兽世界的乐趣吧！', '将卡拉诺斯礼品券交给卡拉诺斯的尤里·碎盔。', '您一定会成为一个真正的英雄，$N。欢迎您来到艾泽拉斯世界，请从我们为您精心准备的特殊礼品中挑选一件吧!', '您好!很高兴见到您!$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5842, '欢迎！', '欢迎来到魔兽世界！$B$B为了感谢您购买魔兽世界典藏版，请将这张礼券交给多兰纳尔的奥雷希尔·语风。您将得到一份特别的礼物：陪伴您踏上冒险旅途的小宠物！$B$B再次感谢您的支持，请尽情享受魔兽世界的乐趣吧！', '将多兰纳尔礼品券交给多兰纳尔的奥雷希尔·语风。', '您一定会成为一个真正的英雄，$N。欢迎您来到艾泽拉斯世界，请从我们为您精心准备的特殊礼品中挑选一件吧!', '您好!很高兴见到您!$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5843, '欢迎！', '欢迎来到魔兽世界！$B$B为了感谢您购买魔兽世界典藏版，请将这张礼券交给剃刀岭的玛卡尔。您将得到一份特别的礼物：陪伴您踏上冒险旅途的小宠物！$B$B再次感谢您的支持，请尽情享受魔兽世界的乐趣吧！', '将剃刀岭礼品券交给剃刀岭的玛卡尔。', '您一定会成为一个真正的英雄，$N。欢迎您来到艾泽拉斯世界，请从我们为您精心准备的特殊礼品中挑选一件吧!$B', '您好!很高兴见到您!$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5844, '欢迎！', '欢迎来到魔兽世界！$B$B为了感谢您购买魔兽世界典藏版，请将这张礼券交给血蹄村的沃恩·星眼。您将得到一份特别的礼物：陪伴您踏上冒险旅途的小宠物！$B$B再次感谢您的支持，请尽情享受魔兽世界的乐趣吧！', '将血蹄村礼品券交给血蹄村的沃恩·星眼。', '您一定会成为一个真正的英雄，$N。欢迎您来到艾泽拉斯世界，请从我们为您精心准备的特殊礼品中挑选一件吧!', '您好!很高兴见到您!$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5845, '失落的荣耀', '当乌瑟尔被杀之后，白银之手骑士团完全瓦解了。$B$B这孩子竭尽所能地坚持着。当他被逼入饱经战乱的北谷中时，他做了最后的抵抗。$B$B骑士团是否还有别人活着，这还有什么意义吗？$B$B正是带着这样的想法，泰兰抛弃了骑士团的战旗，并否认了他所熟知的一切。他的荣誉被遗弃在了北谷那浸满鲜血的土地上。$B$B你必须到北谷去，找回那面代表失落的荣耀的战旗。', '到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。', '即使在如此破败的情形下，它也仍然像我当初注视着它并宣誓效忠骑士团的那个时候一样充满了荣耀和骄傲。$B$B他即将得到救赎，也许还有我……', '我的信仰会指引你，$N。光明无界。', '', '去西瘟疫之地找索多里尔河的提里奥·弗丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5847, '欢迎！', '欢迎来到魔兽世界！$B$B为了感谢您购买魔兽世界典藏版，请将这张礼券交给布瑞尔的克莱尔·韦洛。您将得到一份特别的礼物：陪伴您踏上冒险旅途的小宠物！$B$B再次感谢您的支持，请尽情享受魔兽世界的乐趣吧！', '将布瑞尔礼品券交给布瑞尔的克莱尔·韦洛。', '您一定会成为一个真正的英雄，$N。欢迎您来到艾泽拉斯世界，请从我们为您精心准备的特殊礼品中挑选一件吧!', '您好!很高兴见到您!$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5848, '爱与家庭', '那幅画……它悬挂在我工作室的墙上——在骑士团的兵营里面，一直挂了许多年。$B$B在提里奥的试炼结束以后，我就知道我再也不能把那幅画挂在公开的场合中了。我把它藏在了一个他们永远都不会想到去看的地方。$B$B到斯坦索姆去，深入现在被血色十字军当作基地的区域，寻找一幅绘有两个月亮的画。把上面的油漆铲掉，你就可以找到我的杰作“爱与家庭”。$B$B愿圣光指引你的行动。', '到瘟疫之地北部的斯坦索姆去。你可以在血色十字军堡垒中找到“爱与家庭”这幅画，它被隐藏在另一幅描绘两个月亮的画之后。$B$B把这幅画还给提里奥·弗丁。', '<提里奥看到画以后几乎崩溃了。>$B$B<他开始像疯了一样掩面哭泣。>', '画，$N。你找到画了吗?', '', '去西瘟疫之地找索多里尔河的提里奥·弗丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5861, '寻找麦兰达', '$N，你完成了我交给你的所有任务，你的救赎任务只剩最后一步了。$B$B你必须把你收集到的东西交给泰兰。不幸的是，泰兰和他的血色十字军一看见你就会立刻攻击你。$B$B要传递我的信件只有一个办法，那就是进行伪装。$B$B往南走，你可以在那边找到乌瑟尔之墓。我有个值得信赖的老朋友麦兰达住在那儿，找到她，把这些东西给她看看，她会帮助你的。', '到瘟疫之地南部的乌瑟尔之墓去，将提里奥的礼物交给巫女麦兰达。', '在提里奥.弗丁当上玛登霍尔德领主的时候，我就是他最信任的导师了。我因公开反对白银之手骑士团的裁决而被放逐。$B$B他为此心痛失望了好长一段时间，$C。你准备纠正弗丁犯下的错误吗?', '我就知道会有这么一天的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5862, '血色幻象', '我就是你们所说的……幻术师。虽然我可以创造一个幻象，让你平安进入壁炉谷，但是你要知道，我的力量也不是无限的。$B$B如果你离开这个地区太远的话，幻象会渐渐消失。这个法术需要花费大量的精力，即使这样我也只能坚持很短的时间。$B$B当你准备好之后再和我说话吧。', '和巫女麦兰达交谈以获得血色幻象的效果。在血色幻象的掩护下深入壁炉谷，将提里奥的礼物交给大领主泰兰·弗丁。$B$B壁炉谷在北方，泰兰应该在玛登霍尔德城堡里面。', '这是什么，士兵?$B$B<泰兰打开盒子查看里面的东西。>$B$B这……这不可能。但是你所带给我的东西……$B$B<泰兰单膝跪下，他的心跳加速。多年来沉积的愤怒即将爆发。>', '你是从提尔之手来的援军吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5863, '砂槌食人魔', '最近一段时间，一大群食人魔来到了塔纳利斯。他们已经在南面占领了大片沙漠，并创建了一个营地。当前，食人魔的几个小团伙正在沙漠里四处游荡，其中有些已经侵占了古老的巨魔废墟。$B$B你必须去消灭砂槌食人魔！我们不能让这些家伙的势力壮大起来。$B$B他们的头目名叫掠夺者格玛洛克，我认为如果能杀掉他，食人魔的势力就会土崩瓦解。', '加基森的安迪·利恩想要你攻入砂槌营地，杀死10个砂槌蛮兵、10个砂槌执行者，以及掠夺者格玛洛克。', '我很高兴你能成功，$N!谢谢你的帮助!', '我很担心!请保重!', '', '去找塔纳利斯的安迪·利恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5881, '召回卫兵', '部落在保持军队战斗力这方面做得很好……大战之后我们一直在卡利姆多大陆上繁衍生息。$B$B我想让你帮个忙，$n。我手下有个名叫瑞什·远行者的士兵，他驻守在南贫瘠之地的升降梯附近。把这封信交给他，信中说我将派出一名战士去接替他的工作，这样他就能回家看看了。先前他曾向我提出过这样的要求，他听到这个消息一定会很高兴的。', '马格兰希望你将信送到贫瘠之地升降梯的瑞什·远行者手中。', '这真是个好消息，我在这儿守着这堆木头已经有很长时间了。现在我终于能跟家人团聚了……太好了!', '你有来自马格兰的消息吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5882, '狩猎换药膏', '', '', '干得好，这是给你的塞纳里奥植物药膏，回到费伍德森林中去，拯救这片堕落的土地吧!', '只要你拿着塞纳里奥信标，你就能从那些堕落的野兽身上找到受污染的灵魂裂片，为了费伍德森林的未来，你一定要拿到那些裂片。我会对裂片进行研磨加工，将其制成塞纳里奥植物药膏。我们可以用这种药膏拯救那些奄奄一息的堕落植物。$B$B如果你能给我弄些裂片来，我就可以给你几份植物药膏。', '', '去找费伍德森林的阿拉珊蒂丝·银空。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5883, '采矿换药膏', '', '', '干得好，这里是一些塞纳里奥植物药膏。如果你能在费伍德森林采矿过程中找到更多的硝酸盐的话，记得一定要把它们交给我!这东西越多，我就能造成越多的药膏来。', '如果你随身带着塞纳里奥信标，那么你在采矿的时候就会看到那些污染了矿脉的硫酸盐。我可以对那些硫酸盐进行净化，然后把它们制成塞纳里奥植物药膏。你可以用这种药膏来拯救堕落的大自然。$B$B给我弄些受污染的硫酸盐来，我就可以给你几份药膏。', '', '去找费伍德森林的阿拉珊蒂丝·银空。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5884, '采集换药膏', '', '', '干得好，$N―这种东西只要经过处理就可以帮助我们净化费伍德森林。拿着这些塞纳里奥植物药膏，然后回到森林中去吧。夺回费伍德森林的任务迫在眉睫，$N!', '训练有素的草药师可以用塞纳里奥信标探测到那些被污染的魔藤―这是费伍德森林被污染后所诞生的产物。我在这里进行了一些研究工作，现在我可以把魔藤转化为一种净化原料……然后就可以用它来制作我们所说的塞纳里奥植物药膏了。$B$B当你在费伍德森林里收集草药的时候，别忘了带着这个信标来寻找魔藤。给我弄些魔藤来，我就给你几份药膏作为交换。', '', '去找费伍德森林的阿拉珊蒂丝·银空。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5885, '剥皮换药膏', '', '', '这正是我所需要的。拿着这些药膏，把它们用于拯救费伍德森林吧。你一定要坚持到底，$N!', '训练有素的剥皮匠可以用塞纳里奥信标从费伍德森林里的生物身上找到受污染的毛皮，我可以把这些皮制作成塞纳里奥植物药膏。$B$B当你在这里采集兽皮的时候，记得带上信标。给我弄些受污染的毛皮来，我就可以给你几份药膏。', '', '去找费伍德森林的阿拉珊蒂丝·银空。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5886, '分解换药膏', '', '', '这里是一些塞纳里奥植物药膏―我只需要一份次级虚空精华就够了，$N。这种精华是我迄今为止碰到过的最具魔法潜能的东西，我可以用它们来拯救这片森林。如果你需要更多的药膏，那就到这里来找我吧!', '分解物品所得到的魔法精华中蕴藏着相当大的能量。我已经研究出一种方法，可以把炼金术所使用的原始精华材料转化为制作塞纳里奥植物药膏所需的材料。你不需要拿着塞纳里奥信标，只要是能够分解出次级虚空精华的物品都适用。$B$B我只需要一个次级虚空精华，作为交换，我可以给你一些塞纳里奥植物药膏。那些精华的能量很强大，所以即使很少的精华就能制作出不少的药膏了。', '', '去找费伍德森林的阿拉珊蒂丝·银空。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5887, '狩猎换药膏', '', '', '干得好，这是给你的塞纳里奥植物药膏，回到费伍德森林中去，拯救这片堕落的土地吧!', '只要你拿着塞纳里奥信标，你就能从那些堕落的野兽身上找到受污染的灵魂裂片，为了费伍德森林的未来，你一定要拿到那些裂片。我会对裂片进行研磨加工，将其制成塞纳里奥植物药膏。我们可以用这种药膏拯救那些奄奄一息的堕落植物。$B$B如果你能给我弄些裂片来，我就可以给你几份植物药膏。', '', '去找费伍德森林的梅贝丝·河风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5888, '采矿换药膏', '', '', '干得好，这里是一些塞纳里奥植物药膏。如果你能在费伍德森林采矿过程中找到更多的硝酸盐的话，记得一定要把它们交给我!这东西越多，我就能造成越多的药膏来。', '如果你随身带着塞纳里奥信标，那么你在采矿的时候就会看到那些污染了矿脉的硫酸盐。我可以对那些硫酸盐进行净化，然后把它们制成塞纳里奥植物药膏。你可以用这种药膏来拯救堕落的大自然。$B$B给我弄些受污染的硫酸盐来，我就可以给你几份药膏。', '', '去找费伍德森林的梅贝丝·河风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5889, '采集换药膏', '', '', '干得好，$N―这种东西只要经过处理就可以帮助我们净化费伍德森林。拿着这些塞纳里奥植物药膏，然后回到森林中去吧。夺回费伍德森林的任务迫在眉睫，$N!', '训练有素的草药师可以用塞纳里奥信标探测到那些被污染的魔藤―这是费伍德森林被污染后所诞生的产物。我在这里进行了一些研究工作，现在我可以把魔藤转化为一种净化原料……然后就可以用它来制作我们所说的塞纳里奥植物药膏了。$B$B当你在费伍德森林里收集草药的时候，别忘了带着这个信标来寻找魔藤。给我弄些魔藤来，我就给你几份药膏作为交换。', '', '去找费伍德森林的梅贝丝·河风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5890, '剥皮换药膏', '', '', '这正是我所需要的。拿着这些药膏，把它们用于拯救费伍德森林吧。你一定要坚持到底，$N!', '训练有素的剥皮匠可以用塞纳里奥信标从费伍德森林里的生物身上找到受污染的毛皮，我可以把这些皮制作成塞纳里奥植物药膏。$B$B当你在这里采集兽皮的时候，记得带上信标。给我弄些受污染的毛皮来，我就可以给你几份药膏。', '', '去找费伍德森林的梅贝丝·河风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5891, '分解换药膏', '', '', '这里是一些塞纳里奥植物药膏―我只需要一份次级虚空精华就够了，$N。这种精华是我迄今为止碰到过的最具魔法潜能的东西，我可以用它们来拯救这片森林。如果你需要更多的药膏，那就到这里来找我吧!', '分解物品所得到的魔法精华中蕴藏着相当大的能量。我已经研究出一种方法，可以把炼金术所使用的原始精华材料转化为制作塞纳里奥植物药膏所需的材料。你不需要拿着塞纳里奥信标，只要是能够分解出次级虚空精华的物品都适用。$B$B我只需要一个次级虚空精华，作为交换，我可以给你一些塞纳里奥植物药膏。那些精华的能量很强大，所以即使很少的精华就能制作出不少的药膏了。', '', '去找费伍德森林的梅贝丝·河风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5892, '深铁矿洞的补给', '在战斗开始前，我们曾在丹巴达尔的深铁矿洞储存了很多补给品。那个时候穴居人对于那里的骚扰在我们强大的军力面前简直是不堪一击，但是现在我们必须和部落作战，所以没有足够的人手来控制深铁矿洞。$B$B我们需要深铁矿洞中的补给品，$N。进入矿洞，把它们取回来。', '把10份深铁矿洞补给品交给丹巴达尔的联盟军需官。', '干得好!我一定会把这些补给品用在最需要它们的地方!谢谢你，$N!', '你拿到补给品了吗，$N?我们的补给品一直都很缺乏!', '', '去奥特兰克山谷找丹巴达尔的雷矛军需官。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5893, '冷齿矿洞的补给', '北边的冷齿矿洞是一个储存多馀补给品的好东西，但是为了抵御雷矛部族的疯狂攻击，我们没有足够的士兵驻守在那座矿洞中。因此，现在那里经常落入联盟的控制，或被地下冒出来的渣滓们控制……$B$B但是我们仍然需要补给品，$N！去冷齿矿洞，帮我拿回一些补给品来。小心那里的敌人，战局瞬息万变……', '把10份冷齿矿洞补给品交给霜狼要塞的部落军需官。', '啊，你拿到它们了。干得好，$N!这些补给品在那个黑暗的矿坑中放了太久，沾了不少灰尘，但是我们一定会好好利用它们的。$B$B谢谢你，$N。你为维持我们的战斗力做出了杰出的贡献。', '你去过冷齿矿坑了吗，$N?你拿到我要的补给品没有?', '', '去奥特兰克山谷找霜狼要塞的霜狼军需官。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5901, '瘟疫与你', '为了削弱血色十字军，我要拿下那座对他们来说至关重要的伐木场。我相信，如果他们损失了这么重要的一个资源，定然会在构建防御和重建城镇的过程中捉襟见肘。你愿意帮我的忙吗，$N？$B$B把这个瓶子拿到东瘟疫之地的病木林去，在那里的蚁丘上抓些白蚁，放进这个瓶子里。当你收集到了足够多的白蚁之后就回到我这里来。', '在东瘟疫之地的蚁丘上使用空的白蚁瓶。当你收集了100只瘟疫白蚁之后，就回到提瑞斯法林地的亡灵壁垒去找米克·莱文。', '这些就足够了，$N。谢谢你。$B$B如果你准备好了，我们就可以进行下一步了。', '你拿到白蚁了吗，$N?我确定像你这样聪明的$C肯定可以很轻松地完成这个任务。$B$B一旦你收集到了足够的白蚁，我们就能确保再也没有人可以使用那个伐木场了!', '', '去提瑞斯法林地找亡灵壁垒的米克·莱文。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5903, '瘟疫与你', '我试过很多方法来清除血色十字军，但是从来都没有成功过。好吧，我决定更换一下行事方法，我要让他们吃吃苦头。$B$B如果你愿意帮我的话，我准备用最恐怖的白蚁来毁灭他们的伐木场。$B$B在靠近斯坦索姆的病木林里有一种被瘟疫扭曲的白蚁。找到它们的巢穴，在瓶子里装满白蚁，然后我们就把它们放到血色十字军的伐木场里！', '在东瘟疫之地的蚁丘上使用空的白蚁瓶。当你收集了100只瘟疫白蚁之后，就回到西瘟疫之地的冰风岗去找纳萨尼尔·杜马。', '这些就足够了，$N。谢谢你。看看它们……密密麻麻地抱成一团。我都有点为十字军感到难过了，但是为了让他们得不到那座伐木场，我们必须这样做，对吗?', '你找到蚁丘了吗，$N?我听说病木林里到处都是这种巢穴。', '', '去西瘟疫之地找冰风岗的纳萨尼尔·杜马', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5941, '返回克罗米身边', '你已经收集了达隆郡之战中留下来的许多遗物。每次你给我带回更多的遗物，我的心就更加向往我的家园……更加急切地想要改变它的命运。$B$B我觉得这不可能，但是克罗米——那个安多哈尔奇怪的侏儒告诉我说，这是有可能的。她说你可以拯救达隆郡！$b$b她要我收集所有的遗物，然后由你去把那些东西交给她。她说她仍然在安多哈尔的废弃旅店里等你。', '将一包遗物交给安多哈尔的克罗米。', '啊，没错。这些东西放在一起就可以施放强大的法术，足以唤醒达隆郡的灵魂。$B$B有了这个法术，再加上一些运气，我们就可以拯救约瑟夫.雷德帕斯!', '我一直和你的朋友卡林保持联系。他对自己的村庄遭受的厄运感到极度痛苦，但是他对你评价很高并知道你可以把事情搞定。$B$B哦，但是好像我有点离题了……$N，你拿到我需要的圣物了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5942, '隐藏的宝藏', '爸爸让我给你这把钥匙，他说你可以用它打开房子后面的一只箱子。$B$B他还要让我谢谢你。你是不是帮过他？你有没有告诉他你帮我找到了我的洋娃娃？$B$B好吧，这里是钥匙。谢谢你，$N。谢谢你！你是个好心的$g先生:小姐;！', '用约瑟夫的钥匙打开约瑟夫的箱子。', '箱子打开了……', '这只箱子非常破旧，表面满是污迹。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5943, '基泽尔顿车队', '你看上去是个能干的$r，想不想赚点外快？考克和我为了赚钱而开始了这趟旅程，但是我们不知道此行的凶险！$B$B前面就是玛诺洛克集会所……通常那里的恶魔会忽视我们，但是这一次，有些东西把科多兽赶得四散惊逃。我愿意付钱让你保护我们通过玛诺洛克集会所，在我们安全通过之后，你就可以到瑟卡布斯库的营地去，从我们商业伙伴斯米德那里获得你的奖励。', '护送基泽尔顿车队通过玛诺洛克集会所，然后与瑟卡布斯库的营地的斯米德谈一谈，领取你的奖励。', '不知道用那么多钱来请人保护基泽尔顿车队是否值得。考克和里格每周只赚一个金币，但是只要他们一直为我的科多兽付钱，我就不会去管他们生意的事情。', '你要知道，如果那个车队没有到达目的地的话，那我就完了!你不是带来厄运的使者，是不是?$B$B<斯米德擦了一下额头。>$B$B感谢贪婪女神!', '护送基泽尔顿车队通过玛诺洛克集会所', '去凄凉之地找瑟卡布斯库的营地的斯米德·瑟卡布斯库。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5944, '在梦中', '那么长时间以来，我都是大十字军战士的傀儡。是什么让血色十字军变成了他们努力抗争的东西？数十年来，我对于父亲的记忆从未丢掉一丝一毫，这些宝贵的东西让我继续活在这世上。$B$B我经常做梦，在梦里，我的父亲和我在一起。他骄傲地站在我的身旁，看着我加入骑士团。我们和成群的天灾士兵作战，我们给联盟和洛丹伦带来了荣耀。$B$B我再也不想做梦了。$B$B把我带到他那里去。', '护送泰兰·弗丁走出壁炉谷。', '我的儿子死在这些怪物手中，这段记忆绝不会随着岁月的流逝而消失在我的脑海中。虽然我非常悲伤，但是我知道骑士团已经重生了。$B$B现在我是新的白银之手骑士团大领主。$B$B这些是我过去所拥有的东西，也是我可以给你的所有东西。请你收下它们当作我对你的感谢，它们这些年来一直跟随着我。$B$B希望我们可以再次相见，在更美好的时代，或者在以往的记忆之中……经过了激烈的战斗……我的梦想得到了救赎。', '<提里奥恢复了镇静。>', '救赎？', '去西瘟疫之地找索多里尔河的提里奥·弗丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5981, '狂暴的巨人', '大约四千年前，泰兰德·语风从狂暴的巨人手中救了霜刃豹女王的命。从那个时候开始，霜刃豹就是暗夜精灵的盟友。$B$B那些对霜刃豹造成极大威胁的巨人依然在这附近徘徊——霜槌巨人占据了这里南边的一处山谷。$B$B向霜刃豹证明你的忠诚吧；以霜刃豹女王希洛塔姆的名义杀死那些巨人！', '雷沃·霜翼要你去杀死4个霜槌巨人和4个霜槌保卫者。', '非常好，$N。你已经适时地表现出你的决心了。', '你必须持续的证明你的忠诚，$N。', '', '去冬泉谷找霜刀石的雷沃·霜翼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6002, '身心之力', '在贫瘠之地的陶拉祖营地西边——就在快要进入莫高雷的地方——有一块月夜枭兽之石。月夜枭兽是一种特殊的兽类，不是当地土生土长的动物。月爪枭兽是那块石头的守护者，只有当塞纳里奥月尘洒在石头上的时候它才会出现。月爪枭兽的体内有一种力量，你必须得到这种力量，才能成为真正的利爪德鲁伊。$B$B你已经获得了使用塞纳里奥月尘的权力，$N……现在向我证明你已经赢得了拥有身心之力的权力！', '使用莫高雷与贫瘠之地交界处的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。$B$B任务完成之后，与雷霆崖的图拉克·符文图腾谈一谈。', '你终于大步迈进了一个更加广阔的世界，$N。我感觉到你已经掌握了巨熊之灵所传授的知识，还有月爪枭兽曾经拥有的力量。$B$B在你的面前没有其它的障碍了……现在，让我告诉你成为一个利爪德鲁伊意味着什么吧!', '当你面对挑战的时候，你对身心之力的理解就会更加充分。在你领会那种力量的精髓之前，我无法帮你做什么。', '击败月爪枭兽并吸取它所拥有的身心之力。', '去找雷霆崖的图拉克·符文图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6004, '未竟的事业', '我以间谍的身份来此暗中搞破坏，并负责侦查壁炉谷的防御力量。联盟中的一些人认为这座小镇的重要性并不局限于其历史意义，不过这与我的工作无关。但无论如何，我要好好休息一下才有精力继续做事。$B$B如果你愿意的话，我愿意出大价钱换取你的帮助。沿着堡垒附近的营帐往南查看。如果你能证明自己的实力，或许你就能帮上我的大忙呢。', '杀死2个血色医护员、2个血色猎人、2个血色魔法师和2个血色骑士，然后回到西瘟疫之地的科尔斯塔·迪普沙东那儿。', '干得好，$N。你这么快就搞定了，这真让人吃惊。谢谢你。$B$B血色十字军的教义是扭曲的。和暴风城中的所有人一样，我也信仰光明，但是十字军的行为却表明他们只想杀死那些不忠于他们的人……连无辜者也不能幸免。', '进展如何，$N?它们比你想象得更加强大吗?我希望不是。如果换成是我的话，还不知要费多大的劲呢。', '', '去找西瘟疫之地的科尔斯塔·迪普沙东。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6021, '流亡者塞达尔', '在经历了瘟疫之地的一次次祸事之后……我们还得防着盗贼。你能相信吗？他们不是普通的盗贼，而是巨魔盗贼。$B$B不是普通的巨魔盗贼。而是亡灵巨魔盗贼！$B$B统帅这伙盗贼的是一个身体魁梧的亡灵巨魔，流亡者塞达尔，他们趁着夜色来到这里，从事罪恶的勾当，再偷偷溜回他们那邪恶的藏身之所——西边的墓室中。$B$B到那儿去，干掉塞达尔，$N。我对他深恶痛绝！', '将塞达尔的徽记交给圣光之愿礼拜堂的护理者奥林。', '好极了，你杀掉他了!我希望你也让他的同伙吃足了苦头!', '你找到他的藏身之处了吗，$N?你有没有干掉塞达尔?', '', '去东瘟疫之地找圣光之愿礼拜堂的护理者奥林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6022, '杀戮的理由', '我的要求就是你杀戮的理由。$B$B你的第一个任务是喂养我的猎犬。$B$B拿着这个研钵和捣杵，然后到考林路口去。你可以在那里发现很多可供你屠杀的亡灵，从他们身上取得生命腐质，把它们放在研钵里捣烂，然后等待它凝固。把凝固腐质给我拿回来。$B$B记住，笨蛋，那些生命腐质不会长时间保持“活力”，你必须动作快一些！', '到东边的考林路口去屠杀镇里的亡灵天灾。在10分钟内收集7块生命腐质，使用研钵和捣杵将其研磨成凝固腐质。', '真遗憾。我原本希望用你来喂我的狗。$B$B<纳萨诺斯叹了一口气。>$B$B好吧，至少现在它们有东西可以吃了。', '你在哭吗?如果这个任务对你来说太“艰难”了，我的“英雄”，那么我建议你回到黑暗女王那里，向她哭诉你在我这里遇到的遭遇。$B$B现在从我的视野中消失!', '', '去东瘟疫之地找玛瑞斯农场的纳萨诺斯·凋零者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6023, '未完的任务', '我的真正任务是要削弱血色十字军的外围力量，然后潜入壁炉谷，探查他们的军队规模。现在我对这个行动还没有什么设想，因此我也许要再次请你帮助我，可以吗，$N？根据我所收集的资料，血色十字军在镇外部署了两个主要成员：猎人莱德雷和骑士杜尔根。杀了他们，这样我们就离成功更近了一步。他们应该驻扎在壁炉谷小径那里，就在哨塔的附近。', '杀掉猎人莱德雷和骑士杜尔根，然后向西瘟疫之地的科尔斯塔·迪普沙东复命。', '谢谢你，$N。你给予我的帮助比我预想的还要多。这里的空气正在消磨我的意志，我感到很累，在这里待得越久，我就越虚弱。$B$B我不能确定如何才能够潜入壁炉谷侦察，然后对血色十字军的实力作出正确评估。$B$B但是那是以后的事情了，在你离开这里之前，请拿着这个……这是你应得的报酬。再次感谢你。', '你找到他们了吗，$N?如果你能干掉他们两个，我就可以进入壁炉谷好好侦察一番了。没有你的帮助，我是根本做不到这些的。请你一定要帮我找到莱德雷和杜尔根。', '', '去找西瘟疫之地的科尔斯塔·迪普沙东。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6024, '哈米亚的请求', '杀了我。否则就太迟了。$B$B我是哈米亚。在穿越祖玛沙尔的时候，我和我的兄弟吃了点坏掉的肉……我们已经变了。我们已经被感染了。$B$B现在我可以感觉到巫妖的话语，他要求我去祖玛沙尔，并感染更多我的同胞。我无法抵抗他的命令，所以在我失去一切之前，我写下了这张卷轴。$B$B我在这座地穴的后方埋了一只箱子，就在货车旁的土堆中。但是只有我的钥匙可以打开它，钥匙在我的手里。如果你想要得到我的财宝，就来找到我。$B$B杀了我。否则就太迟了。', '杀了渗透者哈米亚，用他的钥匙开启墓室后的一堆泥土。', '哈米亚的箱子被打开了!!', '这只箱子被牢牢地锁着。', '', '去找辛特兰的一堆泥土。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6025, '未完的任务', '什么？真的？你想要知道更多的情报？但是你已经为我做了很多了，$N。我不能要求你为了我进入壁炉谷。$B$B你当真要去，$N？壁炉谷里面可比那条小径危险很多——我不能给你提供任何保护，也没法告诉你那里有什么样的危险。$B$B好吧，如果你真的想帮忙，那就到那个镇子里去，找一个可以俯瞰全景的制高点。你可以在那里估算一下十字军的人数，然后回来向我报告。但是你一定要小心……', '进入壁炉谷并找一处制高点，你可以在那里观察整个城镇并估算血色十字军的兵力，然后向西瘟疫之地的科尔斯塔·迪普沙东回报。', '你成功了，$N!谢谢你!$B$B我会尽快回到伊林……我是说尽快回到暴风城去。拿着这个，我只能给你这个了。你是个值得信任的$C，$N。谢谢你，祝你好运。', '这是个危险的任务，$N。我羡慕你的勇气。', '在壁炉谷中寻找一处高地，在那里观察小镇。', '去找西瘟疫之地的科尔斯塔·迪普沙东。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6026, '狮子大开口', '银色黎明的成员让烟鬼给他们干一些“爆炸性的”工作，烟鬼可不是小角色！只要你愿意掏钱，我随时为你效劳。这就是我的座右铭！$B$B如果你能为我做点跑腿之类的小事，那么我也愿意和你一起分享荣誉。具体说来是这样的：我要去一趟病木林，然后给我们将要摧毁的建筑物做上标记，而你就负责收集制造炸弹所需的材料。当你拿到所有东西之后就把它们交给我。你觉得怎么样？', '烟鬼拉鲁恩要你拿来2块瑟银锭、1根金棒、8颗高爆炸弹和8个不牢固的扳机。$B$B你需要找铁匠和工程学技师帮忙制作这些东西。', '我可以在工作完成之前给你一半的报酬，事成之后再给你一半。', '相信烟鬼吧，$C。你所能得到的奖励值得你费一番周折。那些银色黎明的家伙在付钱的时候可是非常吝啬的。', '', '去东瘟疫之地找圣光之愿礼拜堂的烟鬼拉鲁恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6027, '上古之书', '$n，拿着这颗毒蛇宝石。在这里的西北面有一座小岛，到那里去把这颗宝石放在毒蛇雕像的手里。它会召唤保护上古之书的守护者。那本书中包含了纳迦的秘密，被埋藏了数百年的秘密。把这本书交给我，然后我们就会对那些长着鳞片的混蛋有更多的了解！', '拿到上古之书，将其交给艾瑟雷索塔中的阿佐尔·奥达蒙特。', '失踪许久的上古之书!我会确保把这本书送到议会手里的。你今天干得很漂亮，你这样的英雄应该受到感谢!', '啊，$N!很高兴再见到你。你拿到上古之书了吗?', '', '去凄凉之地找艾瑟雷索的阿佐尔·奥达蒙特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6028, '永望镇报告', '我正在找一个愿意帮忙的$r，这事情虽然小，但是非常重要。我是作为银色黎明的代表来考察永望镇这里的管理情况的，现在我要给冰风岗的银色黎明军官普尔哈特提交一份进度报告，冰风岗就在西瘟疫地的南部。$B$B如果你接下我的任务，就可以得到一个接触我上司的好机会，也许你还可以从她那里获得一些工作！', '把永望镇报告送给西瘟疫地冰风岗的银色黎明军官普尔哈特。', '格雷戈做得很好。他跟热砂企业打交道已经有些日子了，在哥布尔的谈判“艺术”方面俨然成了个专家。虽然哥布尔只对付钱最多的人表示忠诚，但是他们也明白并且尊重外交的价值。这样他们才能不断有新的顾客……$B$B不管怎么样，银色黎明需要你的帮助。请收下这个，谢谢你。', '你好，$C。以银色黎明的名义，我在冰风营地这里保护你的安全。我也许有些工作要让你去做……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6029, '永望镇报告', '我正在找一个愿意帮忙的$r，这事情虽然小，但是非常重要。我是作为银色黎明的代表来考察永望镇这里的管理情况的，现在我要给亡灵壁垒的银色黎明军官加鲁什提交一份进度报告。亡灵壁垒就在西瘟疫之地的西部，提瑞斯法林地的东边。$B$B如果你接下我的任务，就可以得到一个接触我上司的好机会，也许你还可以从他那里获得一些工作！', '把永望镇报告送给西瘟疫地亡灵壁垒的银色黎明军官加鲁什。', '从人类的角度来说，格雷戈是个足智多谋的人。他跟热砂企业打交道已经有些日子了，在哥布尔的谈判“艺术”方面俨然成了个专家。虽然哥布尔只对付钱最多的人表示忠诚，但是他们也明白并且尊重外交的价值。这样他们才能不断有新的顾客……$B$B不管怎么样，银色黎明需要你的帮助。请收下这个，谢谢你。', '你好，$C。以银色黎明的名义，我在亡灵壁垒这里保护你的安全。我还会为你提供一个机会，让你为了值得争取的东西而战斗!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6030, '尼古拉斯·瑟伦霍夫公爵', '阿姆布兰希发现的这本书为银色黎明提供了丰富的文学财富……它也是迄今为止我读过的最让人摸不着头脑的古书之一。$B$B我们令人尊敬的领袖尼古拉斯·瑟伦霍夫公爵是个睿智的语言学家。你能帮我把这个交给他吗？当然会有奖励。他现在就在圣光之愿礼拜堂，东瘟疫之地的最东部。', '将《灵语研究》这本书交给东瘟疫之地圣光之愿礼拜堂的尼古拉斯·瑟伦霍夫公爵。', '这……这本书非常特殊。我的意思是，我所说的“特殊”意味着“独特而且非常具有启迪意义”，但是我还得仔细看过之后才能下结论。$B$B好吧，我听格雷戈提到过阿姆布兰希，他干得不错。我将尽力来破译这本书。至于你……请你收下这个―这是银色黎明的礼仪。也许我还会有别的事情需要你帮忙。', '愿圣光照亮你前行的道路，$C。是什么在这黑暗而动荡的时代中将你带到这个希望之地来的?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6031, '符文布', '我们木喉熊怪过着自给自足的生活，我们不喜欢陌生人。这对我们来说很好，但是这对交易不好。$B$B不久之前，一个暗夜精灵朋友来到了这里，她披了一件符文布做成的披风。符文布在我们这里很少见，但是那件袍子真的很不错，所以伙伴们要我去找到更多的符文布。$B$B你愿意给我弄些符文布来吗？如果你能给我足够的符文布，那我可以给你一些东西作为交换。', '把30块符文布交给木喉要塞的梅罗什。', '啊，你把布带来了。瞧这材质多棒啊!$B$B谢谢你，$N。你是个真正的朋友。请收下这个吧。', '你有符文布吗?我们需要符文布来制作很多东西!', '', '去费伍德森林找木喉要塞的梅罗什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6032, '神圣的月布', '虽然木喉熊怪很喜欢符文布，但是它对我们来说并不是神圣的。月布才是神圣的。$B$B给我带一些这种神圣的布来，然后我就教你一种神秘的编织技巧。', '把2块月布交给木喉要塞的梅罗什。', '啊，很好。这些月布将会被用来为我们制作神圣的衣物。谢谢你，$N。现在我会对你进行一些训练。', '你带来月布了吗，$N?', '', '去费伍德森林找木喉要塞的梅罗什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6041, '烟鬼的炸药', '在你收集材料的同时，我让一些手下给那些亡灵天灾的建筑物做上了标记。$B$B计划是这样的：我将给你十根由我特制的炸药。你要拿着它们去病木林，把它们放在那些已经被\r\n做上标记的天灾建筑物中。$B$B<烟鬼打了个响指。>$B$B嘭！然后世界就清静了。', '到圣光之愿礼拜堂西北方的病木林去。在那些有爆炸标记的建筑物中对爆炸标记使用烟鬼的特殊混合物，以此来摧毁8座亡灵天灾建筑。烟鬼已经给通灵塔和屠宰房做上了标记。$B$B一旦你放置好炸弹，就离那些建筑物远一些，然后尽情欣赏你的杰作吧。$B$B顺便说一句，烟鬼的特殊混合物相当不稳定……', '在我的记忆中，你可没这么黑。这样子很适合你呢，你的肤色告诉我们:“我差点没被爆裂物给烧焦了。”$B$B<烟鬼大笑起来。>$B$B无论如何，这是你的那份。另外我这里还有一些可以治疗烧伤的东西。', '我这里还库存了一些材料，可以制造更多含有特殊混合物的炸药。如果你需要的话，告诉烟鬼就行了。', '', '去东瘟疫之地找圣光之愿礼拜堂的烟鬼拉鲁恩。', '摧毁天灾建筑物', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6042, '讨厌的蝙蝠', '只要你离开农场两步，就肯定可以撞见那些讨厌的蝙蝠。我想带着这些猎犬出去，在不惊动这些该死的家伙的情况下剿灭亡灵天灾。很明显，与其让我去没日没夜地砍杀蝙蝠，还不如做点更有意思的事情。但是你跟我不同。$B$B什么？你的培训？这就是培训！出发吧，如果你不杀死一定数量的蝙蝠就别回来。不要让我失望。', '杀掉20只毒性天灾蝙蝠和10只巨型天灾蝙蝠，然后回到纳萨诺斯·凋零者那里。', '一点点愤怒就能帮助你完成任务，这真令我诧异。', '情况也许会更糟，我应该让你去收集蝙蝠粪便的。$B$B<纳萨诺斯注视着你。>$B$B嗯……嘿!等等，你要去哪儿?', '', '去东瘟疫之地找玛瑞斯农场的纳萨诺斯·凋零者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6061, '驯服野兽', '作为牛头人，通过与强大的生物作战来延续我们传统是非常重要的。战胜这些生物后，我们就能融合它们的灵魂，使自己与大地母亲的联系更加紧密。$B$B同样，驯服野兽，使它们与我们一同战斗，这有助于我们达到天人合一的境界。你最终要学习驯服一头你中意的野兽，但是所有的事情都必须勤加练习才行，你要学的东西还很多。拿着这根驯兽棒开始训练吧，你必须驯服一只成年陆行鸟。', '使用驯兽棒驯服成年陆行鸟。练习你的技能，然后将驯兽棒还给血蹄村的雅文·刺鬃。', '我已收到来自大地之母的指示，你做得很好。', '练习你的技能，$N。去驯服成年平原陆行鸟。', '驯服一只成年陆行鸟', '去莫高雷找血蹄村的雅文·刺鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6062, '驯服野兽', '拥有对自然的控制权是个令人羡慕的技能。作为一名猎人，你必须努力去了解并善用对自己驯服的生物身上那些与生俱来的力量。$B$B控制动物可不是件容易的事情，而是一项你必须下定决心去完成的艰巨任务。$B$B你的第一项任务是使用这根驯兽棒去驯服一头可怕的杂斑野猪，它们一般生活在剃刀岭附近。在战斗中练习你的技能，驯服野猪，然后回到我这里。', '使用驯兽棒驯服可怕的杂斑野猪。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。', '你做得很好，$N。我相信你已经为下一个任务做好了准备。', '年轻的猎人，祝你好运。', '驯服一只可怕的杂斑野猪', '去杜隆塔尔找剃刀岭的索塔尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6063, '驯服野兽', '作为一名猎人，谨记自己的职责是很重要的。自然不会屈服于我们的欲望，它就像比你更强大的某种力量一样，应该得到你的尊敬和认可。$B$B$N，在你驯服动物使之成为你的同伴之前，你必须证明你已经理解了这一点。$B$B你的第一个任务是拿着这根驯兽棒，用它驯服一只树林潜伏者，以此来练习你的技能吧。', '使用驯兽棒驯服树林潜伏者。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。', '棒极了，$N!你学起来可真快。', '你要努力地学习，$N，总有一天你会成为一名优秀的猎人。', '驯服一只树林潜伏者', '去泰达希尔找多兰纳尔的达扎拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6064, '驯服野兽', '嗨，这儿，$G小子:姑娘;！嗯，你想知道如何获得自己的宠物？$B$B好吧，我们这就开始吧。说到狩猎，没有什么比你的装备更重要了，但我们可以另选个时候来谈谈我的新式火枪。现在，我们说正经的，你肯定对此感兴趣：宠物！$B$B对你来说，学习的最好方法是挑选出一些生物来作为你的同伴，然后看看你喜欢哪些。那么，去找一头大型峭壁野猪，然后使用驯兽棒驯服它吧。', '使用驯兽棒驯服大型峭壁野猪。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。', '我知道，我知道……你想知道下一个任务是什么，对吧?', '别担心，$G小子:小姑娘;!你要多多尝试才能知道自己该怎么做。', '驯服一只大型峭壁野猪', '去找丹莫罗的格瑞夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6082, '驯服野兽', '你需要驯服的最后一种生物是危险的硬甲蝎，它攻击速度非常快，而且非常准确，猎人就应该控制这样的力量。$B$B你成功归来后，我将传授你驯服宠物的技能，这种生物从此将听从你的命令。在你的控制之下，它将与你同甘共苦，我还要为你演示如何召唤它，以及在必要的时候如何解散它。', '使用驯兽棒驯服硬甲蝎。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。', '你已经掌握了我所能传授给你的所有知识，$N。现在是你利用这些知识去选择自己的宠物的时候了。$B$B现在，$N。我将传授你驯服和召唤野兽、以及在适当的时候解散它的方法。自豪地使用你的新技能吧。', '你驯服蝎子了吗?', '驯服一只硬甲蝎', '去杜隆塔尔找剃刀岭的索塔尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6083, '驯服野兽', '当你面对敌人时，宠物可为你提供有力的支持，$N。当你取得对某只野兽的控制权时，你自己的力量也会得到增强。你的宠物必须成为你自己的扩展。$B$B下一项任务要求你到海边去，在那里寻找另一种可供你驯服的生物。在森金村附近有一种名叫海浪蟹的螃蟹，使用驯兽棒驯服它，以此来练习你的技能。', '使用驯兽棒驯服海浪蟹。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。', '你可学得真快呀，$N。干得好。', '你需要练习以掌握有效控制宠物的方法。你驯服海浪蟹了吗?', '驯服一只海浪蟹', '去杜隆塔尔找剃刀岭的索塔尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6084, '驯服野兽', '这些峭壁野猪相当魁梧，或许你希望选择一种更合适自己的野兽？好吧，我明白了。在此地的南面和东面有一种名叫雪豹的大型动物。它们就像精雕细琢的步枪一样，在美丽的外表下隐藏着强大的战斗力和惊人的破坏力。你会发现它们比你先前驯服的野猪更为敏捷。$B$B带着这根驯兽棒，看看你有多喜欢雪豹吧。', '使用驯兽棒驯服雪豹。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。', '当我觉得你已经掌握了足够技能的时候，我将赋予你选择自己所喜欢的宠物的能力。', '你认为雪豹怎么样，$N?', '驯服一只雪豹', '去找丹莫罗的格瑞夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6085, '驯服野兽', '也许你想要同又聪明又强壮的野兽对抗，对于像你这样初出茅庐的猎人来说，冰爪熊可以成为极佳的同伴，你可以在卡拉诺斯东边找到它。拿着这个驯兽棒，把冰爪熊变成你的宠物，看看你是否喜欢它！$B$B你回来以后，我会向你传授驯服野兽的方法，这种野兽将与你一同面对挑战，并与你一起成长。我还会向你展示召唤和解散它的方法。', '使用驯服兽棒驯服一头冰爪熊。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。', '很好，$N。现在，我将向你传授驯服和召唤野兽的技能，以及解散它的方法。$B$B为自己选一只忠诚的宠物，尽情享受狩猎的乐趣吧!', '你驯服冰爪熊了吗?', '驯服一头冰爪熊', '去找丹莫罗的格瑞夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6087, '驯服野兽', '你是个勇敢的猎人，现在你已经准备好接受下一次挑战了。$B$B你的下一个任务是驯服被称为草原捕食者的狼。这是一种敏捷而无畏的野兽，要让它成为你的宠物，你必须同样具备这些品质。$B$B在战斗中，你将学会如何与自己的宠物并肩作战。最终，你们的行动必须融为一体。$B$B这是驯兽棒，$N。去驯服一只草原捕食者，练习你的技能。', '使用驯兽棒驯服一只草原捕食者。练习你的技能，然后将驯兽棒还给血蹄村的雅文·刺鬃。', '是的……大地之母相信你已为下一课做好了准备。', '你找到草原捕食者了没有?', '驯服一只草原捕食者', '去莫高雷找血蹄村的雅文·刺鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6088, '驯服野兽', '我给你最后一个任务是驯服一种在空中飞行的生物。猛鹫是个难缠的对手，但是一旦它成为你的同伴，你就会发现它的快捷和威慑力对你来收都是很有用的。$B$B当你返回时，我将根据大地母亲的意愿，向你传授驯服野兽的技能。这种野兽从此以后将与你一同面临挑战、共同成长。我还将为你展示召唤和解散它的方法。', '使用驯兽棒驯服一只猛鹫。练习你的技能，然后将驯服法杖交还给血蹄村的雅文·刺鬃。', '你已经掌握了我所能传授给你的所有知识，$N。愿大地之母祝福你，指引你选择自己中意的宠物。$B$B现在，$N，我将赋予你驯服和召唤野兽，以及适当的时候解散它的能力。自豪地使用你的新技能吧，让大地之母以你为傲。', '你很快就会准备就绪，$N。', '驯服一只猛鹫', '去莫高雷找血蹄村的雅文·刺鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6101, '驯服野兽', '大自然的复杂和多变是永恒的，$N。它不会一成不变，它总是在不断地改变着。$B$B我给你的任务将帮助你了解各种野兽之间的不同之处。$B$B带上这根驯兽棒，去驯服南边的夜刃捕食者，练习你的驯兽技巧，然后你就会开始了解大自然的相似性和相异性。', '使用驯兽棒驯服一只夜刃捕食者。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。', '你已经掌握了我传授给你的技能，$N。', '了解自然的平衡是每个夜精灵的必修课。', '驯服一只夜刃捕食者', '去泰达希尔找多兰纳尔的达扎拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6102, '驯服野兽', '你已经驯服了在这里繁衍生息的两种生物，现在你必须再驯服一种在空中飞翔的生物。使用驯兽棒去驯服西边的巨翼恶枭，用这种强大的猫头鹰来练习自己的技能吧。$B$B当你回来的时候，我将告诉你如何将野兽驯服成为你的同伴，它将与你一同面临挑战，与你一同在战斗和历险中成长。我还会向你展示如何召唤它，以及如何在必要的时候解散它。', '使用驯兽棒驯服一只巨翼恶枭。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。', '你已经掌握了我传授给你的所有知识，$N。我再给你一个建议吧:一定要慎重选择你的第一只宠物。你是要选择在陆地上疾驰的走兽、在江河湖海中游走的水兽，还是在空中翱翔的飞禽?不管你选择了哪种生物，当它成为你的宠物之后，都会陪伴你很长一段时间。$B$B现在，$N，我将赋予你驯服和召唤野兽的能力，以及在适当的时候解散它的方法。自豪地使用你的新的技能吧，你已经凭自己的努力赢得了它。', '我为你的成功而自豪，$N。你完成我给你的任务了吗?', '驯服一只巨翼恶枭', '去泰达希尔找多兰纳尔的达扎拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6122, '毒水之源', '黑海岸的峭壁之泉是这个地区的主要水源，我认为那里就是造成当地的动物大量中毒的罪魁祸首。用这个取样器在洞口取一些水样，你要小心一些，瀑布旁\r\n边的一个洞穴中居住着危险的纳迦。$B$B一旦你拿到了水样，就把它送到奥伯丁的奥兰达利亚·夜歌那里去。她是向我们寻求帮助的人之一，往后你将和她一起工作。', '使用空的峭壁之泉取样器在瀑布洞口获得水样。$B$B将盛满的峭壁之泉取样器送到黑海岸奥伯丁的奥兰达利亚·夜歌那里。', '以艾露恩的名义，这种水实在是太恶心了!怪不得鹿都生病了。$B$B有某种东西正在污染水源，最终它会污染到整个黑海岸的水域―这里已经到处都是病鹿了。不过除了这个主要的污染源之外，似乎还有别的什么东西也在污染水质……$B$B这个水样将帮助我们找到治疗的方法。在研究这些水样的同时，我需要一些东西来制作治疗药剂……', '你是月光林地的塞纳里奥议会派来的?太好了!那些中毒的鹿危在旦夕，我们很高兴能够获得你的帮助。$B$B你拿到德迪利特.星焰所说的水样了吗?他告诉过我说你会拿来一份水样，让我们一起找出应对的方法。', '', '去黑海岸找奥伯丁的奥兰达利亚·夜歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6123, '收集解药', '这些水将作为解毒药膏的基础材料。为了使它产生治疗效果，我需要一些地根草。采药人知道怎样找到它，如果你不懂草药学的话，那你就得找一个懂行的来帮你。$B$B另外，为了增强药力，我们还需要一些月亮菇。寻找月亮菇很简单——这里东面的洞穴里到处都是。不过这些洞穴里住着一些月光枭兽，它们很容易发怒，所以你要多加小心。', '收集5个地根草和12个月亮菇，把它们交给奥伯丁的奥兰达利亚·夜歌，这样她就可以制作解药了。', '很好，$N，这些可以制成不少解药―至少可以让现在的局面有所改观。$B$B制作解药有时是很困难的，因为每种毒药都需要特定的解药。如果我们可以不考虑这种对应性，随意地制作解药，那就好了!$B$B现在，让我开始工作吧!', '你拿到我制作解药所需的材料了吗?鹿群无法自己恢复健康，所以我们一定要帮助它们!', '', '去黑海岸找奥伯丁的奥兰达利亚·夜歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6124, '消除疾病', '你所带来的材料足够制作十份解药，$n。在我继续想办法准备更多解药的时候，希望你可以给我们开个好头。黑海岸到处都是生病的鹿，对它们使用药膏就可以治疗它们的疾病。$B$B在你完成任务之后，就去找月光林地的德迪利特·星焰谈一谈。请向那里的塞纳里奥议会转达奥伯丁的谢意……另外，我要对你所提供的帮助表示感谢！', '对黑海岸的10头生病的鹿使用动物医疗药膏，以此来治疗它们。从壁泉河到奥伯丁，直到最南端靠近灰谷的地区都有生病的鹿出没。', '你在治愈黑海岸的那些鹿的过程中表现得非常出色。这些可怕的污染和堕落在整个大陆上造成了无数生灵的痛苦，达纳苏斯的一些人愿意承认这个危险的存在……而另一些则对其视而不见。我希望你可以认清现在的形势，$N。$B$B不管怎么样，你是大自然和塞纳里奥议会的朋友―请拿着这个作为我们友谊的象征。', '你完成了奥伯丁的奥兰达利亚.夜歌给你的任务了吗?不要倦怠!', '', '去月光林地找永夜港的德迪利特·星焰。', '治疗生病的鹿', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6127, '毒水之源', '看来，十字路口的西北面的鬼雾峰是最有可能散播毒药的地点。那里的水池可能已经被崇拜恶魔的火刃氏族污染了。$B$B用取样器在山顶的水池中收集一些水样，灌满之后就把它送到十字路口的图加·符文图腾那里去。他是向我们寻求帮助的人之一，往后你将和他一起工作。', '使用空的鬼雾峰取样器在山顶取水样。$B$B将盛满的鬼雾峰取样器送到贫瘠之地十字路口的图加·符文图腾那里。', '以我祖先的名义，这种水实在是太恶心了!怪不得瞪羚都生病了。$B$B有某种东西正在污染水源，最终它会污染到整个北贫瘠之地的水域―这里已经到处都是生病的瞪羚了。不过除了这个主要的污染源之外，似乎还有别的什么东西也在污染水质……$B$B这个水样将帮助我们找到治疗的方法。在研究这些水样的同时，我需要一些东西来制作治疗药剂……', '你是月光林地的塞纳里奥议会派来的?太好了!我们正在致力于救治那些中毒的蹬羚，很高兴能够获得你的帮助。$B$B你拿到德迪利特.星焰所说的水样了吗?他告诉过我说你会拿来一份水样，让我们一起找出应对的方法。', '', '去找十字路口的图加·符文图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6128, '收集解药', '这些水将作为解毒药膏的基础材料。为了使它产生治疗效果，我需要一些地根草。采药人知道怎样找到它，如果你不懂草药学的话，那你就得找一个懂行的来帮你。$B$B另外，为了增强药力，我们还需要一些科多兽角——小碎片可不行。贫瘠之地的北部区域有许多科多兽，为了治愈大自然的恶疾，你必须杀掉一些，把它们的角拿来给我。', '收集5个地根草和5个科多兽角，把它们交给十字路口的图加·符文图腾，这样他就可以制作解药了。', '很好，$N，这些可以制成不少解药―至少可以让现在的局面有所改观。$B$B制作解药有时是很困难的，因为每种毒药都需要特定的解药。如果我们可以不考虑这种对应性，随意地制作解药，那就好了!$B$B现在，让我开始工作吧!', '你拿到我制作解药所需的材料了吗?瞪羚无法自己恢复健康，所以我们一定要帮助它们!', '', '去找十字路口的图加·符文图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6129, '消除疾病', '你所带来的材料足够制作十份解药，$n。在我继续想办法准备更多解药的时候，希望你可以给我们开个好头。贫瘠之地北部到处都是生病的瞪羚，对它们使用药膏就可以治疗它们的疾病。$B$B在你完成任务之后，就去找月光林地的德迪利特·星焰谈一谈。请向那里的塞纳里奥议会转达奥伯丁的谢意……另外，我要对你所提供的帮助表示感谢！', '对贫瘠之地北部的10只生病的瞪羚使用动物医疗药膏，以此来治疗它们。在穿过十字路口的那条东西走向的大路北面到处都是生病的蹬羚。', '你在治愈贫瘠之地的那些蹬羚的过程中表现得非常出色。这些可怕的污染和堕落在整个大陆上造成了无数生灵的痛苦，而你们牛头人对于塞纳留斯的精神和信仰求之若渴;你和你们那些在雷霆崖的长老都已经知道，维护自然平衡的职责要求我们超越种族的隔阂。$B$B$N，你是大自然和塞纳里奥议会的朋友―请拿着这个作为我们友谊的象征。', '你完成了十字路口的图加.符文图腾给你的任务了吗?不要倦怠!', '', '去月光林地找永夜港的德迪利特·星焰。', '治疗生病的瞪羚', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6132, '救我出去！', '救我出去！$B$B我本来是到长矛谷这里找玛洛迪半人马谈判的……我本以为可以跟他们做点生意……但他们根本不想做生意！我想他们要吃了我！$B$B救我出去吧，我哥哥霍恩尼兹会给你很多钱的！他在东边靠近科多兽坟场的营地里。$B$B我们赶紧出发吧，$N。大概两分钟前，我听到几只半人马说要找些木头烧火……', '护送梅丽萨，然后与凄凉之地科多兽坟场的霍恩尼兹谈一谈。', '我妹妹梅丽萨说过你会来的。多谢你把她从困境中解救出来，但她现在很可能又已经陷入新的困境了，这可真糟糕!', '你有没有看到我妹妹梅丽萨?她总是到处乱跑，到处给我惹麻烦。', '护送梅丽萨抵达安全地带', '去找凄凉之地的霍恩尼兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6133, '游侠之王的命令', '奎尔林斯小屋里的高等精灵拿着一件属于我的东西，一本记录着我生前的那些往事的日记。$B$B在你询问之前，我要先明确地告诉你：你不得翻阅这些资料。照我说的做，你这条虫子，去给我找到这份文件。$B$B另外，一定要让他们饱尝痛苦和悲伤，让他们受尽苦难和折磨……', '到东瘟疫之地的北方边界去找回奎尔萨拉斯名册，这件物品在奎尔林斯小屋的某处。$B$B另外你还必须杀掉8个游侠、8个巡路者和8个护林者。', '我相信你没有读过这份文件。即使是你这样的蠢货也不会蠢到那个地步……', '不要让我空等，$C。', '', '去东瘟疫之地找玛瑞斯农场的纳萨诺斯·凋零者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6134, '幽灵电浆', '东南方有一处山谷——白骨之谷，那里是玛格拉姆半人马的鬼魂出没的地方。听起来很可怕，不是吗？好吧，想想那里对玛格拉姆半人马有多么可怕吧！如果我们从那个地方收集鬼魂的能量，我敢打赌它对那些半人马来说是很值钱的。$B$B给，拿着这箱幽灵磁铁。如果你把它放在山谷中的两具大骷髅之间，那么鬼魂就会实体化，并聚集到它旁边。干掉那些鬼魂并收集他们的幽灵电浆——那就是我们要卖给玛格拉姆部族的东西。', '把幽灵磁铁箱和8份幽灵电浆交给凄凉之地的霍恩尼兹。', '它在那儿!看起来你身上还沾了一点。有点黏，是吗?$B$B哦，给你添了那么多麻烦，真的很谢谢你，$N。这东西值一大笔钱……如果我能让半人马们相信这是什么!', '我的鬼魂电浆在哪里，$N?', '', '', '杀死8只亡灵劫掠者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6135, '暗翼蝠', '到现在为止，你已经完成了我配置的所有任务，虽然并不是非常及时。$B$B我想你认为自己已经准备好接受真正的挑战了。很好……很好，蠢货，也许你需要一些更加棘手的任务。$B$B苍白的恶魔蝙蝠——暗翼蝠——就在这里的北方游荡。消灭它，把它的毛皮给我带回来，你会得到奖赏的。', '找到暗翼蝠并杀掉它。从尸体上取下一块暗翼蝠的皮，并把它交给纳萨诺斯·凋零者。$B$B据说暗翼蝠游荡在玛瑞斯农场北面的荒原上。', '干得漂亮，白痴。我要把这块毛皮做成你可以使用的东西。', '我不建议你独自迎接这次挑战，$C。', '', '去东瘟疫之地找玛瑞斯农场的纳萨诺斯·凋零者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6136, '肥大的食腐虫', '在圣光之愿礼拜堂和北谷西边的银色黎明营地，你就可以找到一条非常肥胖的蛆虫，它叫淤血虫。$B$B那个怪物曾经让我损失了一大票士兵。而且它吃得越多就变得越大……$B$B虽然这头怪兽吃了你我也不会觉得悲伤，但我还是希望你能获胜。我建议你召集一些同伴来完成这项任务，淤血虫曾吃掉过无数贸然攻击它的蠢货。', '找到东瘟疫之地北方荒原中的淤血虫并消灭它。任务完成之后，向纳萨诺斯·凋零者复命。', '继续保持下去，我可能就得把你从低能儿提升到心智障碍一级了。', '最近我有没有告诉你，我恨你?', '', '去东瘟疫之地找玛瑞斯农场的纳萨诺斯·凋零者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6142, '蚌肉鱼饵', '你看起来像是个渔夫，$c！我喜欢钓鱼——我一生都在钓鱼。最好用的鱼饵是软壳蚌肉，鱼儿根本无法抗拒它的诱惑，你知道我说的是什么吗？$B$B往北方走，你可以在海岸边找到一艘失事的船，那一带到处都是软壳蚌肉。如果你给我带回来十块软壳蚌肉，我也会给你一些回报。', '找到10块软壳蚌肉，把它们交给葬影村的麦拉斯。', '真不错，这正是巫医教给我的治疗头痛的方法。他说，“麦拉斯，钓鱼去。这会让你感觉好得多。”$B$B哦，我已经觉得好多了，谢谢你!', '我等不及要带些新鲜的软壳蚌肉去钓鱼了，你弄到我要的十块肉了吗?', '', '去凄凉之地找葬影村的麦拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6143, '另一种鱼', '你可能听说过，也可能没有……我的同伴和我一起在靠近纳迦岛的地方钓鱼，就在北面海岸边的那艘失事船舶的更北面。我们过去常常在那里钓鱼，但是现在我满脑子想的都是为我死去的同伴报仇。$B$B有一天早上，纳迦攻击了我们，杀了除我以外的所有人。$B$B我的心每天都被内疚和仇恨煎熬着，$c。我想让你去把纳迦全都给干掉，而且我保证你的努力会得到回报的。那么，你愿意帮我吗？', '杀死7个滑刃侍从、7个滑刃纳迦，以及5个滑刃巫师，然后与葬影村的杜泽加尔谈谈。', '听到纳迦被击败的消息固然很好，但我的心仍然觉得空荡荡的。在我的馀生中，我发誓要把他们全都杀掉。$B$B给你老兄，这是我许诺的奖赏。比起惩罚罪恶累累的纳迦而带来的满足感，这点东西是微不足道的。', '我还能听到我的手下在被纳迦屠杀时哭喊求救的声音。如果不是因为我的膝盖坏掉了，我肯定会跟你一起去，帮你杀死那些混蛋纳迦!$B$B你通常都可以在水下的珊瑚礁深处找到他们……潜伏着……策划着阴谋……', '', '去凄凉之地找葬影村的杜泽加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6145, '红衣信使', '就像身体没有头就不能存活一样，头没有了身体也不能存活。斯坦索姆城中的血色十字军司令部几乎是无法攻破的。因此，我们必须把他们的身体从头下切断。$B$B我的亡灵哨兵一直在斯坦索姆城外搜集十字军活动的情报，每天都有有一份报告从他们的指挥部送到提尔之手去。这报告就是关键，$r！找到红衣信使并取回那份报告，然后把它交给纳萨诺斯。', '返回东瘟疫之地，找到并杀死红衣信使，拿到大十字军的命令。$B$B把命令交给纳萨诺斯·凋零者，并等待进一步的指示。', '<纳萨诺斯大笑了起来。>$B$B太好了!我终于等到了一个可以消灭血色十字军神谕者的机会!', '如果你成功了，那你也许可以就此赢得我的尊敬，$C。', '', '去东瘟疫之地找玛瑞斯农场的纳萨诺斯·凋零者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6146, '纳萨诺斯的计谋', '我已经对这份命令做了一些调整。如果我们的小计谋成功了，他们就会暴露血色十字军圣贤，然后我们就可以出击了！$B$B现在听好了，$c。你要把这份命令交给十字军领主瓦德玛尔。$B$B怎么交给他？亲手交给他，你这白痴。$B$B把命令和这只烂苹果拿到提尔之手去。当你快到那里的时候，吃掉这个苹果，你会变成某种更加……能被人类接受的东西。把这份命令交给十字军领主瓦德玛尔。', '到玛瑞斯农场东南方的提尔之手去，抵达那里之后就咬一口烂苹果。在血色十字军伪装的掩护下，把大十字军的命令交给十字军领主瓦德玛尔。', '你去哪儿了?我们还以为天灾军团把你给捉住了。', '这是不可接受的，士兵!', '', '去东瘟疫之地找提尔之手的十字军领主瓦德玛尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6148, '血色十字军圣者，德米提雅', '德米提雅是大十字军的首席顾问，她因为具备“来世的感觉”而被称作圣者。她已经成功地帮助十字军赢得了数次对亡灵天灾的战斗。$B$B如果她真的有点本事的话，那么眼下她应该已经预见到自己会有麻烦了。你要去帮她验证这一点，给她点“麻烦”尝尝。$B$B找到圣者德米提雅并杀了她。在我们说话的时候，他们应该正在从提尔之手出发去巡逻。别让我失望。', '血色十字军正在从提尔之手到斯坦索姆的路上巡逻，你可以在巡逻队中找到圣者德米提雅和她的随从，找到并杀死她。如果你成功了，就回到纳萨诺斯·凋零者那里去复命。', '十字军遭受的这次损失将会使他们从此一蹶不振!干得漂亮，$N!你不仅赢得了我的尊敬，而且还赢得了这份奖赏。', '怎么样了，$N?', '', '去东瘟疫之地找玛瑞斯农场的纳萨诺斯·凋零者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6161, '拉克摩尔的财宝！', '拉克摩尔的日志上面说，他的船是在驶向羽月要塞的途中受到海洋生物攻击的。为了避免自己的财宝落入敌人之手，他将宝物箱藏在了一座岛上。$B$B你需要两把钥匙才能打开箱子，一把金钥匙和一把银钥匙。这两把钥匙都丢失了，但是如果你能找到钥匙和宝箱，就能得到财宝了！', '找到拉克摩尔的银钥匙和金钥匙。找到并打开拉克摩尔的箱子。', '箱子打开了，拉克摩尔的财宝展现在你面前!', '这个箱子被牢牢地锁着。', '', '去凄凉之地的萨瑟里斯海岸找拉克摩尔的箱子。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6162, '最后一战', '我的丈夫为了氏族的荣耀去了费伍德森林，与暗影议会和其它堕落的势力作战！$B$B他多次从死亡边缘逃了回来，直到我收到了他的一封信，说是有一名德鲁伊请他帮忙干掉一只被称作主宰洛尔的熊怪——但他们两个再也没有了音信。$B$B我想要洛尔的爪子，$N。我要它偿还令我成为寡妇的代价！我相信这头野兽就在南边……靠近灰谷的边境。', '杀死主宰洛尔，把他的爪子交给费伍德森林血毒岗哨的德雷卡苏。', '你遵守了你的诺言。我的丈夫在战斗中牺牲─他以此为傲，但是我不能安心，除非我知道那个让我孤独一生的那头野兽已经对它的所作所为付出了代价。$B$B再次谢谢你，$N。', '你拿到那野兽的爪子了吗，$N?它会为它的罪行付出代价的。我不管它是堕落了还是仅仅因为生活在这片阴暗的森林中而感到愤怒。任何熊怪都不能在对我的家庭犯下这种恶行之后逍遥法外!', '', '去费伍德森林找血毒岗哨的德雷卡苏。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6163, '吞咽者拉姆斯登', '我被完全击败了。为了守卫我们的家园，为了守卫洛丹伦，我在这里绝望地战斗着……一切抵抗者都在潮水般的天灾士兵面前被夷为废墟。$B$B那个邪恶而肮脏的怪物把我踏在脚下，我能看到它丑恶的内在。$B$B我被亡灵天灾唤醒了，一直以来，我是如此的无助。我的意志被巫妖王牢牢地控制着。$B$B她赶来解救了我……不管用什么方式，在什么地方，我知道她早晚会这么做的。自由。$B$B现在，我必须进行复仇——对那些夺取我生命的敌人进行复仇。毁灭它。', '到斯坦索姆去，杀掉吞咽者拉姆斯登。把他的徽记交给纳萨诺斯。', '我想要知道……它求饶了没有?它知道什么是怜悯吗?$B$B<纳萨诺斯吐了一口唾沫。>$B$B我会把那个野兽的头颅挂在我的墙上。$B$B你将成为我麾下诸多勇士的一员，$N。$B$B<纳萨诺斯向你敬礼。>', '在希尔瓦娜斯让我获得自由之后的这几个月来，我一直都在这片废土上狩猎那个混蛋，它居然躲进了斯坦索姆……', '', '去东瘟疫之地找玛瑞斯农场的纳萨诺斯·凋零者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6164, '奥古斯图斯的收据册', '准备开张！你想要点什么？$B$B啊，等等……没有收据册，我就不能开张。没有收据册的话，我怎么能搞清楚帐目呢？$B$B我一定是把它丢在镇子里了。我在旅店里住过，一定是在那里。$B$B把我的收据册拿回来吧。请把它交给我！我要尽快开张营业，而你会看到我的价格完全出乎你的意料！', '在恐惧谷的旅店中取得奥古斯图斯的收据册。', '你成功了!天哪!我简直都忘记这里面记载了多少东西!$B$B真是荣耀的一天，$N!太惊人了!简直太棒了!', '你找到我的收据册了吗?我还等着重新开业哪!', '', '去东瘟疫之地恐惧谷找被感动的奥古斯图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6181, '快递消息', '尽管我没有直接从暴风城得到很多帮助，但是城里有个好心人一直在为我提供护具。他的名字叫做奥斯瑞克·斯图恩，他在暴风城的旧城区里开了一家名叫“有限防护”的店。$B$B现在我们的护甲供应短缺，所以我必须联系到奥斯瑞克以得到更多的装备。你能把这张便笺交给他吗？$B$B到暴风城去的最快捷的办法就是通过索尔，我们的狮鹫管理员。他就在山脚下，把我的便笺拿给他看看，然后从他那里租一头狮鹫飞到暴风城去吧。', '将刘易斯的便笺交给狮鹫管理员索尔。', '你要把这封信送到暴风城去?没问题，骑我的狮鹫兽去吧!', '你看起来是要急着赶路。嗯，你来对地方了!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6185, '东部的瘟疫', '正如我所说的，你的第一项任务就是侦察工作。没什么难度，$N。你必须到东瘟疫之地去寻找任何有关这个凋零者的线索。$B$B留意我们的几个失踪的密探。我们只能是认为他们已经死了，不过如果他们确实死了，那就一定可以在某个地方找到……他们的尸体。$B$B<弗林特艰难地咽了一下唾沫。>$B$B所有的军情七处成员都有这样的一枚徽章。$B$B<弗林特给你看了他的军情七处徽章。>$B$B把你发现的所有东西都带回来给我。', '搜寻东瘟疫之地，寻找“凋零者”的线索以及失踪的军情七处密探。如果你找到任何军情七处徽章，就把它们交给冰风岗的弗林特·沙多摩尔。', '拉戈尔。弗雷多。特伊恩。都……死了……$B$B<弗林特紧紧抓住徽记。>$B$B他们在哪里?你有没有发现关于这个混蛋的更多消息，就是凋零者?', '你发现……发现什么了吗?', '找到凋零者', '去西瘟疫之地找冰风岗的弗林特·沙多摩尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6187, '重铸秩序', '你知道这个世界上总共才出现过多少游侠领主吗？你知道这其中的人类游侠领主有几个吗？$B$B纳萨诺斯的贡献是空前的。他是个战术天才，他让联盟获得了无数次战斗的胜利。$B$B现在……他却成了被遗忘者的勇士。$B$B不，事情不可能是这样的。我们必须恢复那里的秩序。$B$B召集一支部队，$N。回到瘟疫之地，杀掉凋零者。$B$B祝你好运，$N。事实上，这次你确实需要一些好运。', '组织一支部队，然后到东瘟疫之地去。向纳萨诺斯·凋零者和任何敢于保护他的部落成员发起攻击。$B$B你要倾尽全力，$N。部落会不惜一切代价保护他们的游侠领主。', '这是个悲剧。我想……我认为我们的种族是被诅咒的，$N。我们损失了最伟大的战士，我们最高贵的英雄，我们最富智慧的智者。$B$B我们很荣幸能够拥有你，并且我向你保证，$N，不管纳萨诺斯.玛瑞斯如今在哪里，他一定正在对着你微笑。', '<瓦里安.乌瑞恩国王陷入了沉思。>', '', '去暴风城找暴风要塞的瓦里安·乌瑞恩国王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6261, '杜加尔·朗德瑞克', '$N，我收集了奥斯瑞克需要的所有东西，把它们都放在这个箱子里了。你能帮我把它运过去吗？$B$B如果你以前和西部荒野的索尔说过话，那么你就可以搭乘狮鹫直接飞回他那里。杜加尔·朗德瑞克是我们的狮鹫管理员，就在贸易区那边。$B$B和杜加尔谈一谈，然后尽快把这个东西交给刘易斯。我们不希望西部荒野的战士们赤手空拳地进行战斗！', '将奥斯瑞克的箱子交给狮鹫管理员杜加尔·朗德瑞克。', '这是要送到西部荒野去的木箱，对吗?你以前去过西部荒野?如果你去过那里的话，那就没有问题了，我的朋友。我的这些训练有素的狮鹫兽可以载着你直飞那里!', '看你满头大汗的，$g小伙子:小姑娘;，跑来跑去的真是太辛苦了。下一次，你应该搭乘狮鹫兽!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6281, '赶赴暴风城', '只需花费很少的钱，你就可以坐狮鹫去暴风城，把刘易斯的便笺交给奥斯瑞克。这是你到那里去的最快捷的办法。$B$B如果你觉得可行的话，就做好准备，然后再次和我对话。我的收费非常低廉，而且绝对物有所值！', '从狮鹫管理员索尔那里租用一头狮鹫，然后把刘易斯的便笺交给暴风城的奥斯瑞克·斯图恩。', '啊，军需官路易斯的信?他需要更多的装备，这一点我并不感到奇怪。哨兵岭是如此的遥远，它几乎都要被暴风城遗忘了。$B$B好吧，谢谢你，$N。这是给你的旅费。', '你是在到处旅行吗?有没有去过什么有趣的地方?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6282, '鹰身人的威胁', '牛头人以保护这片土地而感到骄傲。毫无疑问，你知道我为什么对石爪山的鹰身人的数量感到担心。$B$B血怒鹰身人是卡利姆多大陆上膨胀速度最快的鹰身人族群，它们会阻止任何人离开它们的领地。$B$B你必须去减少它们的数量，$N！', '烈日石居的马格兰要你去杀掉7个血怒鹰身人、7个血怒伏击者、7个血怒杀戮者和7个血怒游荡者。', '太好了!再跟我说说你是如何让那些邪恶的鹰身人四散逃窜的。血怒鹰身人已经遭受了重创!', '不要对焦炭谷掉以轻心，许多邪恶的生物都盘踞在那里。保持斗志，$N，你将帮助我们消除这些威胁。现在出发去痛击敌人吧―让我们的后代永远都不知道这些邪恶曾经存在过。', '', '去石爪山脉找烈日石居的马格兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6283, '血怒一族', '限制血怒鹰身人的数量还不够，要解决它们的问题，唯一的方法就是杀了它们的领袖，血怒撕裂者！$B$B她是那些邪恶生物的女王。只要杀了她，鹰身人的数量就一定会减少。$B$B回到焦炭谷去，你可以在西部的山岭中找到她。她可不好对付，但是如果你完成这个任务的话，我也会给你可观的奖励。', '烈日石居的马格兰要你去杀掉血怒撕裂者，然后把她的遗体带回来作为证据。', '我的愤怒正在逐渐消退。我该怎么办呢?当我知道邪恶的力量靠近我的家园时，我的思绪就无法稳定下来，虽然它们现在很沉寂。也许这是件好事……也许我现在可以专注于一些好的事情，就像所有牛头人都应该做的那样。$B$B请收下这个作为你的奖励。', '血怒撕裂者是个肮脏的生物!你可以在焦炭谷西部的山岭中找到她。$B$B只要干掉了她，血怒鹰身人就会乱作一团……然后我们就可以把它们完全消灭掉!', '', '去石爪山脉找烈日石居的马格兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6284, '贝瑟莱斯', '警告：从这里往西进入希塞尔山谷的旅行者请多加小心。$B$B贝瑟莱斯和她的蜘蛛后代们占领了这座峡谷，将其作为它们的巢穴。$B$B烈日石居的马格兰正在悬赏贝瑟莱斯。杀了她并将证据交给马格兰以换取奖励。', '杀掉贝瑟莱斯，然后把贝瑟莱斯的牙齿交给烈日石居的马格兰。', '干得好，$N!贝瑟莱斯一直以来都威胁着我们……我不会想念她的。拿着这件奖励品吧，勇士。$B$B<马格兰抚摸着贝瑟莱斯给他留下的伤口。>$B$B也许更多旅行者会因为不必再担心这个威胁而来到烈日石居了。', '贝瑟莱斯是个残忍的猎食者……我晚上都不敢独自在蛛网小径行走。每当那个时候，她和她的孩子们就会潜伏在黑暗中，准备猎捕无辜的旅人。我也曾经落入她的魔爪，幸运的是我活着逃了出来。我会为干掉这头怪兽而付出一切的。', '', '去石爪山脉找烈日石居的马格兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6285, '返回西部荒野', '西部荒野的狮鹫管理员是索尔。如果你以前和他谈过的话，那你就可以乘坐我的狮鹫去他那里。$B$B有件事情你应该知道：狮鹫总是可以从外围城镇直飞主城的，不过只有在你和当地的狮鹫饲养员谈过话之后才行。$B$B你已经去过索尔那里了，那么，你只需再次和我说话就可以乘坐狮鹫去西部荒野。到了那里之后，把奥斯瑞克的箱子交给军需官刘易斯。', '从狮鹫管理员杜加尔·朗德瑞克那里租用一头狮鹫飞到哨兵岭，然后将奥斯瑞克的箱子交给哨兵岭的刘易斯。', '很好!我会把这些护甲分发给需要它们的人。$B$B谢谢你，$N。你的努力对我们的帮助很大。现在你对狮鹫兽已经不陌生了，我希望你多为哨兵岭出一些力!', '你从暴风城回来了?奥斯瑞克的护甲拿到了没有?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6301, '生生不息', '工业集团的贪婪和持续不断的战事已经让了石爪山脉的土地饱经创伤，在我的血管中流淌着的萨满能量可以帮助这里的森林。$B$B$N，我需要派你去寻找一种特殊的种子。盖亚之种仅生长石爪山地区，你可以在北边的暗色湖一带找到盖亚之种，就在湖岸边。$B$B当你把种子交给我之后，我就会为它们灌入萨满的能量，使它们快速成长。', '烈日石居的塔姆拉·荒原想让你去收集10枚盖亚之种。', '啊，$N，你拿到盖亚之种了。看看这些种子将如何给土地带来新的活力吧，只有这些纯净的植物可以治愈大地的创伤。$B$B<塔姆拉开始吟唱魔法。>', '战争带来的持续破坏，还有那些想要从木材贸易中牟利的商人都深深地刺痛了我。我们所能做的就是尽量治愈大自然，种植盖亚之种，用新生的森林来抚平大地的创伤。你弄到我要的盖亚之种了吗，$C?', '', '去石爪山脉找烈日石居的塔姆拉·荒原。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6321, '瑟伯切尔的补给', '执行官哈德瑞克让我清查我们在瑟伯切尔的装备。由于森林中潜伏着的天灾军团士兵的威胁，他不希望我们在装备方面有所短缺。$B$B我发现，我们的武器装备基本上库存丰富，但是我们仍然需要更多的武器来替换那些在战场上丢失的武器。$B$B这是一份武器订单，把它交给幽暗城里的武器供应商高顿·温德哈姆。带着订单去找我们的蝙蝠管理员卡洛斯·拉佐克，跟他谈谈关于转至幽暗城的事儿吧。', '将博迪瑞格的订单交给卡洛斯·拉佐克。', '啊，一份供给订单。毫无疑问，你想要带着这份订单去幽暗城。那么就快点动身吧，瑟伯切尔急需物资补给。$B', '你似乎是有公务在身……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6322, '迈克尔·加勒特', '我已经将瑟伯切尔那边要求的物资装箱了。如果你已经拜访过瑟伯切尔，并与他们那里的蝙蝠管理员打过招呼，那么你就可以乘坐蝙蝠回到那儿去。$B$B与幽暗城的蝙蝠饲养员迈克尔·加勒特谈谈吧，他可以为你提供一只飞往瑟伯切尔的蝙蝠。', '将高顿的箱子交给迈克尔·加勒特。', '这只木箱是要送往银松森林的瑟伯切尔?这很容易，我们的蝙蝠每天都往那儿飞。', '如果你非得进行长途跋涉的话，最好选择乘坐蝙蝠的方式。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6323, '飞往幽暗城', '只需一小笔费用，我的蝙蝠就可以把你带到幽暗城去。当你准备就绪时再来找我，然后我会帮你安排剩下的事情。$B$B你可以在幽暗城的贸易区里找到高顿·温德哈姆，我的蝙蝠正好会降落在那个区域。', '从蝙蝠管理员卡洛斯·拉佐克那里租一只蝙蝠飞往幽暗城，然后将博迪瑞格的订单交给幽暗城里的高顿·温德哈姆。', '一份来自瑟伯切尔的订单?好极了。能为黑暗女王的侍从提供服务是我的荣幸。', '我的武器保养得无懈可击。它们毫无瑕疵，随时都可使用。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6324, '向博迪瑞格回报', '瑟伯切尔的蝙蝠管理员是卡洛斯·拉佐克。如果你们已经见过面，那么我可以为你提供一只返回他那儿去的蝙蝠。$B$B这些蝙蝠都可以直飞幽暗城，但是如果你想要飞到更遥远的地方去，就必须先拜访那个区域的蝙蝠饲养员。$B$B你已经在瑟伯切尔跟卡洛斯碰过面了，现在你可以乘坐蝙蝠回到他那里去。当你准备就绪时再来找我吧。', '从蝙蝠管理员迈克尔·加勒特那儿租一只蝙蝠飞往瑟伯切尔，然后将高顿的箱子交给瑟伯切尔的亡灵卫兵博迪瑞格。', '干得不错，$N。这些武器能确保我们的士兵有充足的准备。$B$B你为黑暗女王做出了颇具价值的贡献。$B', '$N，你回来了。你从幽暗城带来我们所需的物资了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6341, '泰达希尔的渔业', '鲁瑟兰村周围水域中的鱼又大又肥，所以这里的渔业很昌盛。我希望把从这里捕获的鱼和卡里姆多的鱼进行比较，研究一下它们有何不同。$B$B我收集了一些鱼骨头和鳞片，想要把它们带到我在黑海岸的一个同事那里去。他的名字叫做莱尔德，是奥伯丁的鱼商。$B$B把我的东西拿到角鹰兽管理员维斯派塔斯那里去，跟他谈谈关于去奥伯丁的事宜。', '将尼莎的货物交给维斯派塔斯。', '啊，你要把这个送到奥伯丁?很好……', '我能帮你什么忙吗?你是来搭乘角鹰兽的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6342, '飞往奥伯丁', '从鲁瑟兰村到奥伯丁去的方法有两种：乘船或者骑角鹰兽。这两种方式都很迅捷可靠，但是如果你没有搭乘过角鹰兽的话，我建议你试一下。$B$B\r\n另外，你最好和各个城镇中的角鹰兽管理员谈谈。一旦你和某地的角鹰兽饲养员打过了招呼，那么以后你就可以从其它城镇飞到那里去了。$B$B这里是尼莎的货物。如果你准备好了的话，就再次和我对话，然后把这包东西送到莱尔德那里。', '从角鹰兽管理员维斯派塔斯那里租用一只角鹰兽飞到奥伯丁，然后将尼莎的货物交给莱尔德。', '奈莎送来的包裹?谢谢你，$N!她说过如果她在鲁瑟兰村钓到鱼的话，就会托人把样品送到我这里来。她认为那里的鱼可能和这边的不太一样……$B$B我的天啊!这条鱼的个头几乎比这里的同类大了两倍!这些鳞片都有拳头那么大!太令人惊奇了!$B', '你是从泰达希尔来的?告诉我，那里的渔业近况如何?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6343, '飞回泰达希尔', '我必须给尼莎回信，她应该会对这里的鱼跟泰达希尔沿岸的那些鱼的差异感兴趣。出现这种差异的原因……也许是世界之树在影响其周围的生物！$B$B请你帮我给尼莎捎个信。如果你想要乘坐角鹰兽回鲁瑟兰村的话，那就去跟角鹰兽管理员凯莱斯·月羽谈谈吧。如果你要搭船回去，西北面的码头那里有定时的航班。', '将莱尔德的回信交给尼莎·影歌。', '真有趣。这里的鱼很大，但是我不认为它们和卡利姆多大陆的鱼有很大的差异。这一定是有原因的……$B$B很好，谢谢你，$N。我会和其他村民讨论一下的。也许有一天，我们能搞清楚这种情况出现的原因。但是在此之前，我们要尽情享受它给我们带来的好处!$B', '$N，你从奥伯丁必来了?你和赖尔德谈过了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6361, '一捆兽皮', '我有一捆从贫瘠之地采集的兽皮，必须要把它们送到雷霆崖去。我在那儿的同伴安哈努需要用这些兽皮来制作皮件。$B$B你能帮我把这些兽皮交给他吗？$B$B转至雷霆崖最为快捷的方法就是乘坐双足飞龙。带着这捆兽皮去十字路口找双足飞龙管理员迪弗拉克，跟他谈谈到雷霆崖去的事儿。', '带着兽皮去找十字路口的迪弗拉克。', '你要把这些兽皮送到雷霆崖去?找我就对了!', '你是来租用双足飞龙的吗?你需要运送什么货物吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6362, '飞往雷霆崖', '只需一小笔费用，我就可以为你提供飞往雷霆崖的驭风者。没有比这更方便快捷的旅行方式了！$B$B如果你愿意的话，准备一下就来找我吧。$B$B如果你要把这些兽皮交给安哈努，就到雷霆崖驭风者高塔底层的海瓦的武器店里去找他吧，就是你降落的地方！', '从双足飞龙管理员迪弗拉克那里租一只驭风者飞往雷霆崖，然后将这捆兽皮交给雷霆崖的安哈努。', '啊，一捆新的兽皮。我要马上就开始动手制作皮件!$B$B谢谢你，$g兄弟:姐妹;。你帮了我的大忙。这些是你的报酬。', '你肩膀上有来自贫瘠之地的灰尘。你同我的朋友加翰见过面吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6363, '双足飞龙管理员塔尔', '我已经为加翰准备好了供他在十字路口出售的皮件。请你把这些交给他好吗？$B$B如果你已经拜访过了十字路口的双足飞龙管理员，那么你就可以乘坐雷霆崖的双足飞龙返回他那儿了。$B$B将皮件交给雷霆崖的双足飞龙管理员塔尔，然后和他谈谈转至十字路口的行程安排。', '将安哈努的皮货交给雷霆崖的塔尔。', '你要把这个送到十字路口去，对吗?没问题。要是你已经去过那儿，并且和迪弗拉克打过招呼，你就可以乘坐我的双足飞龙直接回到他那儿了。', '你好，$C。我能为你做什么吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6364, '向加翰回复', '想要飞回某座城镇的话，你必须已经徒步到达过那里，并且和那里的双足飞龙管理员打过招呼。如果你去过十字路口并和他们的双足飞龙管理员迪弗拉克谈过话，那么你就可以从这里搭乘双足飞龙直接飞过去了。$B$B如果你准备好了，就再次和我谈谈。一旦到了十字路口，你就可以把这些皮货交给加翰·鹰翼了。', '从双足飞龙管理员塔尔那里租用一头飞往十字路口的双足飞龙，并把安哈努的皮货交给加翰·鹰翼。', '安哈努送来了皮货?很好!十字路口这里有很多猎人和冒险者来来往往，生意也非常火爆。我肯定我会很快把这些货物都卖光的。$B$B谢谢你的努力，$N。我欠你的人情。$B', '$N，你是从雷霆崖回来的吗?你把皮革送到安哈努那里了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6365, '送往奥格瑞玛的肉', '我有一些上等的肉片想送给我的朋友。她的名字叫雷什卡，是奥格瑞玛旅店的老板。你可以替我把这些肉交给她吗？$B$B到奥格瑞玛去的最快捷方法就是乘坐双足飞龙。带着这些肉去找十字路口的双足飞龙管理员迪弗拉克，跟他谈谈关于到奥格瑞玛去的事情。', '把扎尔夫的肉品交给十字路口的迪弗拉克。', '你要把这块肉送到奥格瑞玛去?没问题。只需支付一点点费用，我的双足飞龙就可以把你带去。', '你需要快速赶到某个地方去?找我就对了!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6381, '新的生命', '如你所见，$c，我纯净的心灵可以为这片不毛之地带来新的生机。你必须将这些种子种植在破坏之源中，在西边的焦炭谷里就是破坏大自然的源泉——这片被污染的土地上到处都是鹰身人和凶恶的火元素。$B$B$N，拿着这些附有魔法的盖亚之种，把它们种植在盖亚土堆里。', '将10枚盖亚之种种植在盖亚土堆中，然后与烈日石居的塔姆拉谈一谈。', '这对森林之灵来说是一次伟大的胜利。地精风险投资公司将会收拾起他们那些嗡嗡作响的锯子和斧头，火元素将会因燃料的缺乏而被削弱，鹰身人再也不能建造更多的巢穴了。$B$B只有到那时，$N，这片土地才能拥有真正的和平。$B$B你干得很好，作为对你的回报，请挑选一样东西吧。', '你所种下的种子将使得森林更加强大，使它可以抵御那些足够杀死所有新生命的堕落能量。它们将不断生长，防止死亡和破坏继续在这块土地上蔓延。$B$B你种下所有的盖亚之种了吗?', '', '去石爪山脉找烈日石居的塔姆拉·荒原。', '种植盖亚之种', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6384, '飞往奥格瑞玛', '只需一小笔费用，我就可以为你提供飞往奥格瑞玛的驭风者。当你到那儿后，就去把扎尔夫的肉品交给格雷什卡。她在距离通天塔不远的力量谷里，驭风者会在通天塔上降落。$B$B当你准备动身的时候就来找我吧。', '从双足飞龙管理员迪弗拉克那里租一只驭风者飞往奥格瑞玛，然后将扎尔夫的肉品交给奥格瑞玛的格雷什卡。', '啊，棒极了!这些肉真不错!这些是札尔夫给我的肉，是吗?那个家伙倒是很清楚如何赢得女士的芳心啊……$B$B我马上就要把这些肉煮了吃，但是不能煮得太多!物以稀为贵，你说对吧?', '这味儿真好闻!你身上带着新鲜的肉，对吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6385, '双足飞龙管理员多拉斯', '我已经为扎尔夫写了一封感谢信。你能帮我交给他吗？如果你已经去过十字路口，并且和那里的双足飞龙管理员谈过话，那么你就可以乘坐一头双足飞龙直飞到那里去。$B$B把我的信交给奥格瑞玛的双足飞龙管理员多拉斯，并同他谈谈去十字路口的事儿。', '将格雷什卡的信交给奥格瑞玛的多拉斯。', '你要把这个带到贫瘠之地的十字路口去吗?嗯，没问题……', '你需要租用双足飞龙吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6386, '返回十字路口', '经过训练，我的驭风者可以飞往许多不同的地方，只要你已经去过那个地方，并且与那里的驭风者管理员进行了交谈，驭风者就可以载着你转至那地方。$B$B你已经去过十字路口，也跟那里的驭风者饲养员迪弗拉克打过了招呼，所以现在你可以直接飞到他那儿了。一旦你到了十字路口，就把格雷什卡的信交给扎尔夫。$B$B当你准备出发时就来找我谈谈。', '从驭风者管理员多拉斯那里雇一只驭风者转至十字路口，然后将格雷什卡的信交给十字路口的扎尔夫。', '哈!我就知道她会喜欢的!除了一大块鲜美多汁的烤肉，没有什么能让这样一位小姐的脸颊泛起红光了!\r\n\r\n谢谢你，$N。你帮了我的大忙。这是我给你的一点报酬，要是我邀请你参加我的婚礼，可别感到惊讶啊!', '你是从奥格瑞玛回来的吗?格雷什卡喜欢我送给她的肉吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6387, '荣誉学员', '我看见门前聚集了一大群年轻的矮人，他们都迫切地想要学习采矿技巧。如果说有一件东西是矿工最为需要的工具的话，那当然是铁锄无疑了！$B$B我有一张学习采矿的学生的名单，他们表现得都很出色，因此都将获得一把荣誉锄。把这张名单交给铁炉堡的高尼尔·石趾，他会为你准备好荣誉锄。$B$B去铁炉堡最快的途径是乘坐狮鹫，带着这张名单去找狮鹫管理员索格拉姆·伯雷森吧，跟他谈谈去铁炉堡的事儿。', '将布洛克的名单交给塞尔萨玛的索格拉姆·伯雷森。', '你要带着这个去铁炉堡，对吗?你只需支付一小笔费用，我就可以为你提供一匹狮鹫兽，它将把你带到那儿去。怎么样?', '你这么快就办完了在塞尔萨玛的事儿吗?现在你是要转至其它座城市吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6388, '格莱斯·瑟登', '这是给布洛克的学生的荣誉锄。如果你已经去过塞尔萨玛了，那么就乘坐狮鹫返回那里吧！$B$B把这些荣誉锄交给狮鹫管理员格莱斯·瑟登，跟他谈谈关于返回塞尔萨玛的事儿。', '将荣誉锄交给铁炉堡的格莱斯·瑟登。', '你要把这些东西带到塞尔萨玛去，对吗?没问题。只要你已经去过塞尔萨玛，而且跟索格拉姆.伯雷森谈过话，你就能乘坐我的狮鹫兽回到他那儿。', '似乎你是要外出旅行，需要乘坐狮鹫兽吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6389, '瘟疫与你', '你在伐木场附近寻找能打开桶的工具，很快就找到了一根铁棍，似乎可以用它撬开桶。$B$B你开始撬桶，并暗自祈祷能在白蚁发现你之前离开伐木场。', '使用北山伐木场里的铁棍放出那里的瘟疫白蚁，然后向西瘟疫之地冰风岗的纳萨尼尔·杜马报告。', '哈哈!谢谢你，$N!你做到了!我父亲的灵魂可以安息了，我也能安安宁宁地过日子了。$B$B再次感谢你。要是有什么我可以帮忙的地方，请尽管开口。', '你完成任务了吗，$N?你把白蚁放出来了吗?愿圣光保佑我们，将血色十字军逐出伐木场和壁炉谷，我们不能让他们控制任何一处地方。血色十字军只不过是利用上一次战争的牺牲者来达到自己疯狂的目标而已，因此你应该像杀死那些发疯的动物一样杀死他们!', '', '去西瘟疫之地找冰风岗的纳萨尼尔·杜马。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6390, '瘟疫与你', '你在伐木场附近寻找能打开桶的工具，很快就找到了一根铁棍，似乎可以用它撬开桶。$B$B你开始撬桶，并暗自祈祷能在白蚁发现你之前离开伐木场。', '使用北山伐木场里的铁棍放出那里的瘟疫白蚁，然后向提瑞斯法林地亡灵壁垒的米克·莱文报告。', '谢谢你，$N。请拿着这枚硬币吧。很抱歉我没有更多的硬币，但是你可以从摧毁血色十字军的成就中获得一些乐趣!', '你完成任务了吗，$N?你把伐木场里的白蚁放出来了吗?我的系列成员失去了工作和生命，这糟糕透了，但是看着我儿时成长的地方被那些令人厌恶的所谓圣徒占据着……啊!!', '', '去提瑞斯法林地找亡灵壁垒的米克·莱文。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6391, '飞往铁炉堡', '只需一小笔费用，我就能为你提供一只飞往铁炉堡的狮鹫，让你把布洛克的名单交给高尼尔·石趾。你可以在铁炉堡大锻炉区的深山矿工协会里找到他，狮鹫也会在那个区域降落！$B$B当你准备出发时就来找我。', '从狮鹫管理员索格拉姆·伯雷森那里租一只狮鹫飞往铁炉堡，然后将布洛克的名单交给铁炉堡的高尼尔·石趾。', '啊，最新的布洛克优秀学生名单。我已经准备好了一批荣誉锄，现在只需要学生的名字刻上去就行了……', '$g先生:女士;，我能为您做点什么吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6392, '向布洛克回复', '只需一小笔费用，我就能为你提供一只飞往塞尔萨玛的狮鹫，当然，在这之前你必须已经去过塞尔萨玛了。狮鹫只能载着你飞往你以前曾经去过的地方，因此你必须跟你所见到的每个狮鹫管理员交谈，以确保稍后你能乘坐狮鹫飞到管理员那里。$B$B你已经见过了塞尔萨玛的狮鹫管理员索格拉姆，因此现在你可以返回他那儿了。到了塞尔萨玛之后，把这些镐交给布洛克·寻石者。$B$B当你准备出发时就来找我吧。', '从狮鹫管理员格莱斯·瑟登那里租用一头飞往塞尔萨玛的狮鹫，然后将荣誉锄交给塞尔萨玛的布洛克·寻石者。', '你带来了镐。棒极了!我将把它们分给我的优秀学员们。我敢肯定他们会很乐意在洛克莫丹的矿产开采中使用这些镐的。$B$B谢谢你的帮助，$N。我欠你的人情，但是希望这些钱能补偿你在旅途中的开销。$B', '啊，$N。你已经从铁炉堡回来了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6393, '元素战争', '海潮议会派我来与石爪山的火元素作战。水元素的统帅，猎潮者耐普图隆对于消灭火元素很感兴趣。$B$B$N，你可以通过消灭焦炭谷的火元素来赢得我们的青睐。当火元素被摧毁之后，它们会留下焚火馀烬。把那些东西给我带回来，然后你就能获得奖励。', '将10块焚火馀烬交给烈日石居的苏纳曼。', '我体内的水之灵变得异常兴奋。$N，我可以将你辉煌的胜利报告给海潮议会。', '海潮议会开始变得有些不耐烦了。他们试图结束这场持续数年、波及各个位面的战争。我的同胞们迫切地希望听到战胜那些讨厌的火元素的消息。你拿到我要的东西了吗?', '', '去石抓山脉找烈日石居的苏纳曼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6394, '塔兹利尔的镐', '$N，你是个值得信赖的$r。我能把另一个任务也托付给你吗？$B$B不久前，我在北边的一个洞穴中挖掘矿石的时候不小心弄丢了我最喜欢的镐。后来当我回去找它的时候，却发现洞穴中住满了邪恶的野兽！到那个被称作火刃集会所的洞穴中去帮我取回我的镐，行吗？$B$B我把它放在一个有瀑布的大厅里了。我的镐附有魔法，你在黑暗中也能看见它，所以你不必担心找不到它……只要小心那些守护它的野兽就是了！', '将塔兹利尔的镐还给塔兹利尔。', '好极了!非常感谢你，$N。这是我最喜欢的镐!要是我的苦工能砍完这些树，我们或许就能找到一个挖矿的好去处了!', '你进入燃刃集会所了吗，$N?你找到我的镐了吗?', '', '去找杜隆塔尔的工头塔兹利尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6395, '玛拉的遗愿', '瘟疫发生之前，我的朋友玛拉·菲普斯和她的丈夫塞缪尔生活在一起。但是瘟疫扫过这片土地之后，塞缪尔加入了亡灵天灾的队伍。$B$B玛拉逃过了瘟疫，却惨死在她那愚蠢的丈夫手里。唉，这个傻女人深爱着自己的丈夫，她的遗愿竟然是同塞缪尔葬在一起。$B$B塞缪尔·菲普斯就住在丧钟镇东北边，在路旁的一座废弃的营帐里。去打败他，实现玛拉的遗愿——将他葬在玛拉的坟墓里，就在墓地的第一排。', '将塞缪尔·菲普斯的遗骸带到玛拉的坟墓去，然后回到新兵艾尔雷斯那里。', '你今天可做了一件好事，$N。虽然我们与天灾军团的斗争还在继续，但是我希望玛拉和山缪都能安息。', '我们尊重死者，$N。这是我们与天灾军团的不同之处……', '', '去提瑞斯法林地找丧钟镇的新兵艾尔雷斯。', '安葬塞缪尔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6403, '潜藏者', '朋友，黑石塔那一仗可真是惊心动魄，我欠你一大笔人情。也许等这一切都结束之后……$B$B就像你已经确认了的那样，女伯爵卡特拉娜·普瑞斯托就是奥妮克希亚，死亡之翼系列中的一员，黑石塔内的那个奈法利安的姐妹。$B$B她长期以来一直在操纵着我们的王国。连伯瓦尔·弗塔根公爵也被她耍得团团转。今天这一切都将结束了……她的魔法将被破除。$B$B不要怕，我们会取得胜利的！$B$B你准备好了吗？', '跟随雷吉纳德·温德索尔元帅在暴风城中前进。保护他，别让他受到伤害！', '<伯瓦尔握着破碎的勋章。>$B$B这上面肯定附着了魔法，让我们不知不觉就被控制的魔法。$B$B温德索尔元帅的牺牲拯救了我们的王国，但是奥妮克希亚和她的系列仍然在威胁着我们。$B$B这勋章迷惑了我的头脑和身体，但它也让我洞察了奥妮克希亚的思维―她的秘密。虽然记忆有些混乱，但是我仍记得一些事情。', '我……我……我没有力量了。', '雷吉纳德·温德索尔的征讨', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6421, '滚岩峡谷', '石爪山脉有些事不大对劲。你能感觉到空气中的紧张气氛吗，$N？在此地以南的滚岩峡谷中有一处很深的洞穴，狗头人正在那儿疯狂地开采一种被称作共鸣水晶的稀有矿石。我需要你去取回一些矿石样本，那样我就能了解洞穴中究竟发生了什么事儿。另外，你还得去勘查一下洞穴的深度。$B$B去吧，年轻的$c，我必须知道这里的山脉中潜伏着什么样的邪恶力量。', '深入滚岩峡谷的洞穴中，为烈日石居的摩罗加尔取回10块共鸣水晶以供研究。', '啊……没错!就是这个。共鸣水晶附有土灵的魔法。狗头人一定挖得很深，结果把土灵给挖出来了。$B$B传说土灵是泰坦创造的生物，他们曾协助泰坦创造了我们脚下的土地。这是个不能忽视的威胁。$B$B<摩罗加尔晃动着他的脑袋。>$B$B或许我能为这些矿石样本附上一些魔法，以此来破坏狗头人的阴谋。', '你在滚岩峡谷有什么发现吗?我记得一些与共鸣水晶有关的传说……但是我没法亲自去那儿。或许当我知道洞穴底部都有些什么东西的时候就能洞察他们的意图了。', '调查滚岩峡谷', '去石爪山脉找烈日石居的摩罗加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6441, '萨特之角', '你好啊！我要穿越灰谷往棘齿城去，途中在碎木哨岗这里稍作休息。我一直在寻找发财的机会，眼下似乎就有一个——这些日子以来棘齿城的萨特角行情看涨。$B$B在附近询问了一番之后，我认为夜道谷、萨提纳尔和萨维亚的萨特头上的角都符合我的要求。不过我可不是萨特的对手……你也许能行！$B$B帮我收集一些角吧，我会给你报酬的。', '为碎木哨岗的皮克希尔收集16只萨特的角。', '完美的角，$N!谢谢你!$B$B哦，这是你应得的酬劳……', '我希望你能快点找到这些角，$N。我马上就要回棘齿城了!', '', '去灰谷找碎木岗哨的皮克希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6442, '佐拉姆海岸的纳迦', '邪恶的力量正潜伏在海岸边，$c。$B$B海面下长眠着一座在很久以前就被摧毁的城市，佐拉姆城。这座城市差不多都快要被遗忘了。$B$B现在，出于某种未知的原因，纳迦又重新回来了。但是这其中的原因并不重要，重要的是，我们必须为这片土地而战！我们必须保卫经过浴血奋战而得来的领土。$B$B去奋勇杀敌吧，$n，给我带\r\n回20个纳迦的徽记来！将它们逼回深海！', '将20颗怒尾纳迦的徽记交给佐拉姆海岸的玛鲁凯。', '我们需要的就是你这样的$C，$N，谢谢你的帮助。', '纳迦的数量正在激增，$N。请赶快完成我交给你的任务。', '', '去灰谷找佐拉姆加前哨站的玛鲁凯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6461, '盗窃的蜘蛛', '玛拉卡金的巨魔在这片土地上繁衍生息，石爪山脉是我们赖以生存的狩猎场。$B$B但是近来却有些不请自来的客人……山中的蜘蛛常常在夜间洗劫我们的营帐，窃取我们的猎物。$B$B如果你能帮我们杀死这些可怕的怪物，玛拉卡金的巨魔会对你感激不尽的。石爪山脉到处都是蜘蛛——往北走，你就会看到的。', '玛拉卡金的辛吉拉要求你杀死10只深苔爬行者和7只深苔毒蜘蛛。', '很好!这真是个好消息，也许今天晚上我们就不会有那么多不请自来的访客了。$B$B就向我说过的一样，我欠你的人情……这些东西里面有没有你用得到的?', '嘿，你杀死那些浑身长毛、性格暴躁的畜生了吗?我在石爪山什么都不怕，但是晚上我可不敢在附近闲逛……你该明白我的意思吧!$B$B只有我确信自己不会成为它们的盘中餐，我才会感到安全。$B$B祝你好运，$C!', '', '去石爪山脉找玛拉卡金的辛吉拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6462, '巨魔符咒', '我的族人携带着大量神圣的巨魔符咒到这里来，但是在他们抵达佐拉姆加之前，蓟皮熊怪袭击了他们，把他们全都给杀了！这些可憎的熊怪！$B$B我思念那些死去的兄弟姐妹，但愿我们能在另一个世界重逢。不过，他们的巨魔符咒蕴含着强大的魔力。这些符咒落在熊怪手里对我们来说简直是一种耻辱！$B$B$N，你必须取回符咒！蓟皮熊怪的村落在阿斯特兰纳背面，穿过村落进入那个被称作蓟皮要塞的洞穴，从它们的箱子里拿回我们的符咒。', '将8个巨魔符咒交给佐拉姆加前哨站的米苏瓦。', '你找到它们了!谢谢你!谢谢你，$N!你可帮了我的大忙了。$B$B没有符咒的巨魔就好像没有因作战而留下伤疤的兽人一样……$B$B毫无价值。', '你找到符咒了吗，$N?一想到那些神圣的符咒落在熊怪手中，我就气不打一处来!', '', '去灰谷找佐拉姆加前哨站的米苏瓦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6481, '土灵的觉醒', '你已经找到了一个隐藏在这片土地中的威胁，$c。你在洞穴中发现的共鸣桶中藏有一个沉睡的土灵，他的名字叫做高戈罗克。$B$B我已经用萨满力量改变了你收集的共鸣水晶的成分。用这块魔化共鸣水晶打开那只藏有土灵的共鸣桶。$B$B当高戈罗克清醒过来时，他的能力也将减弱……杀死他，$N！', '使用魔化共鸣水晶打开共鸣桶，然后杀死高戈罗克。将这个消息告诉摩罗加尔，并把魔化共鸣水晶还给他。', '你带来了好消息，$C!我正担心土灵可能会给卡利姆多大陆造成灾难呢。$B$B只有英雄才能完成这个危险的任务。你做得很好，整个石爪山和卡利姆多都感谢你，高贵的$C。$B$B请收下这个，这是我们所能提供的最好的回报了。', '如果我们不能尽快解决威胁的话，也许我们会丧失整个石爪山地区。任何魔法都无法与土灵的力量抗衡。当高戈罗克清醒时，他的力量将因长期沉睡而减弱，你必须利用这个机会……去吧，$N!', '', '去石爪山脉找烈日石居的摩罗加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6482, '鲁尔的自由', '呃？你是谁？$B$B$N？你不是熊怪，它们是邪恶的生物！它们认为我是一头熊并俘虏了我，现在它们又让我忍饥挨饿！我快要没力气了……$B$B帮我逃离这里，然后到东面的碎木哨岗去找我的妹妹雅玛。$B$B$N！我必须离开这儿！', '护送鲁尔，然后与碎木岗哨的雅玛·雪蹄谈一谈。', '你找到了我的兄弟!他被蓟皮熊怪捉住了吗?这真是个可怕的消息，尽管许多熊怪都是高贵的生物，但蓟皮熊怪却是堕落的家伙。$B$B谢谢你营救了我的兄弟，$N。我简直不敢想象它们是怎样对待可怜的卢尔的。历经磨难之后，他终于可以安心睡一觉了……', '你看见我的兄弟卢尔了吗?他几天前进入了森林，一直都没有回来……', '护送鲁尔逃离蓟皮熊怪的领地。', '去灰谷找弗伦河的雅玛·雪蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6501, '巨龙之眼', '我所能给你的就是这枚奖章的碎片。$B$B你必须找到另一个愿意帮你铸造新钥匙的龙类。在得到钥匙之后，你必须到尘泥沼泽的巨龙沼泽那里去。你将会在那里找到她的巢穴，$N。$B$B到哪儿去找到其它愿意帮忙的龙呢？遗憾的是，我不知道……据说是有的。其中的一些也许就混迹于我们当中，化装成某种人型生物的样子。祝你好运。', '你必须寻遍世界以找到一种能恢复龙眼碎片的能量的生物。你对这种生物的唯一了解就是：他们确实存在。', '我早该猜到的……黑龙公主奥妮克希亚。真令我恶心……', '我感到了你身上散发出的邪恶气息，$r。是什么让你被这种气息笼罩?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6502, '龙火护符', '这是龙身上的一部分，一片龙鳞——它已经被附上了魔法，不再是普通的龙鳞了。完整的龙鳞可以帮助我们找到那头野兽的巢穴，而破碎的龙鳞就毫无用处。$B$B要修复龙鳞也不是没有办法，但是你需要黑龙勇士的血。眼下就有一个……他被称为达基萨斯将军，是奈法利安龙人军队的首领。也许你以前听说过他？$B$B把他的血带回来，$c，我将为这块碎片附魔，使你能进入奥妮克希亚的巢穴。', '你必须从达基萨斯将军身上取回黑龙勇士之血，你可以在黑石塔的晋升大厅后面的房间里找到他。', '这个护符可以让你进入你想去的地方。奥妮克希亚的巢穴在尘泥沼泽中。一旦你拥有了护符，她的结界就无法阻止你进入了。$B$B蓝龙军团祝福你，$N。', '时间的流动不会停止或滞后，$r。我的生命是永恒的，但是你的却不是。不要浪费时间了……', '', '去冬泉谷找凯斯利尔废墟的哈尔琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6503, '灰谷先驱者', '我们得到消息说，不久前从灰谷派出的先遣人员离开了银翼哨站，现在正向我们的领地渗透。我们不能让这些间谍得到我们防御工事的情报！$B$B悄悄穿过我们岗哨南边以及联盟的银翼哨站东边的森林，找到并杀死那些先驱者，然后回到我这里来。', '杀掉9个灰谷先驱者，然后回到碎木哨岗的库莱比那里。', '很好，$N。你的猎杀技术真不错……$B$B失去那些先驱者会让联盟无法得到情报，而当他们缺乏情报的时候，他们就不太可能发动攻击了。', '我等待着你杀死先驱者的消息，$N。', '', '去灰谷找碎木岗哨的库莱比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6504, '丢失的书页', '我刚刚从棘齿城得到了这台伐木机，准备回到战歌伐木场去上班。伐木机中放着一本操作说明书，但在回来的路上，一阵强风把它从我手中吹走了，纸张散落得到处都是，剩下的就只有封面了。$B$B现在那些纸都飞到不知哪里去了……没有它们，我就压根不知道该如何操作这台伐木机！你能帮我找到它们吗？', '找到丢失的12页伐木机操作指南，把它们合并为第1、2、3章。然后带着这些书页回到碎木岗哨去找古尔达·怒痕。', '阅读不是我的强项……但我现在至少可以回去工作了!谢谢你，$N!', '我希望你尽快把纸张找回来，$N!我必须马上回去工作!', '', '去灰谷找碎木岗哨的古尔达·怒痕。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6521, '邪恶的盟友', '玛克林声称他在剃刀高地外面。这位大使必须被干掉——他的任务在巫妖王的眼中是彻头彻尾的失败。$B$B他在那里的出现确实解释了我们的一些发现，比如某些野猪人已经变得非常强大，并且还显示出了被感染亡灵疫病的迹象。那一定是他们达成某种交易的征兆。$B$B找到玛克林并杀了他，$N。任务完成后回来找我。', '把玛克林大使的徽记交给幽暗城的布拉贡·血拳。', '很好。干得漂亮，$C。$B$B现在玛克林死了，我们至少知道天灾军团的行动被延缓了。黑暗女王对你的行动表示感谢，并希望给你一份礼物作为奖励。$B$B尽管我们不清楚天灾军团在剃刀高地的影响范围，但我敢肯定，我们很快就会揭穿他们的阴谋。$B', '你找到大使了吗，$N?他死了吗?$B$B我们承受不起让天灾军团在卡利姆多建立据点的威胁。现在我们陷入了两面作战的境地，这足以说明他们已经对我们构成了足够的威胁。$B$B你告诉我的事情中唯一让我感到乐观的事情就是那个野猪人的首领看起来还未被腐蚀。她肯定知道天灾军团可能会带来巨大的力量，但如果她同意接受他们的条件，贫瘠之地并不会真正成为她的地盘。', '', '转至幽暗城，去找皇家区的布拉贡·血拳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6522, '邪恶的盟友', '大人：$B$B您很清楚我们可以提供什么。您占领贫瘠之地及其它土地的机会非常大，我们也只想要您的帮助作为回报。所谓的帮助不过是让您授予我们在这一带行动的自由。$B$B请允许我们说得更远些。我们拥有强大的力量，并愿意与那些希望加入我们的聪明人分享。我当前仍待在剃刀高地外面。$B$B向您致以最高的敬意，$B玛克林大使', '把小卷轴交给幽暗城皇家区的布拉贡·血拳。', '我认得这个卷轴上的徽记，$N。你在那个统治剃刀沼泽的野猪人身上找到的?真有趣。$B$B天灾军团看起来并不满足于统治一块大陆。这个玛克林大使─这个写便条的家伙─是天灾军团的一个仆从，在瘟疫来临之前曾是洛丹伦王国的大使。$B$B如果天灾军团想在卡利姆多占据一个立足点，那么我们就该立刻出手干预。$B', '你有什么事，$N?如果你不断来烦我，那你一定是有什么你以为很重要的事情。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6543, '战歌报告', '我最近派了一些斥候进入灰谷，所以我得找个跑腿的去把他们的报告带回来。$B$B你的第一站应该是西面的佐拉姆海岸边的佐拉姆加前哨站，在那里可以找到第一个斥候。另外你还要到北边的碎木哨岗去，它就在东边的路上，靠近艾萨拉地区。你可以在那里找到一个斥候和一个侦查骑兵。$B$B给他们每人一份报告，然后把他们的最新报告拿回来。', '打开报告集，把战歌报告交给战歌斥候、战歌信使和战歌侦查骑兵。把他们的最新报告交给贫瘠之地北部哨塔上的卡德拉克。', '我看得出你是个值得信赖的$C。这些报告对于我们在灰谷巩固阵地的意义非常重大。接下来，我们就可以盘算下一步该怎么办了。', '快点，$N。我们必须拿到他们的报告，事关紧急。', '', '去贫瘠之地找摩尔沙农场的卡德拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6544, '托雷克的突袭', '嘿！$C！到这儿来！$B$B我将和我的部队准备袭击西边的银翼哨站，这次行动的目标是他们的首领杜瑞尔·月火。据侦察，那座哨站中有重兵把守。这将是一场激烈而光荣的战役！$B$B你愿意加入我们的队伍吗，$N？如果你愿意的话，那么当战役结束时，你就可以去将我们胜利的消息汇报给慰藉之林的埃尔托格·怒齿了。$B$B你认为怎么样，要跟我们一起来吗？', '保护在银翼哨站与杜瑞尔·月火作战的托雷克，然后向慰籍之林的埃尔托格·怒齿汇报胜利的消息。', '托雷克获胜了!干得好，$N。夜精灵是相当顽强的对手，虽然他们身材瘦小，但是力量强大，勇猛无比!我想这场战役肯定很激烈……$B$B希望你在战争中留下了荣耀的伤痕!', '托雷克被派去执行突袭银翼哨站的任务了，他取得胜利了吗?', '攻占银翼哨站。', '去灰谷找弗伦河的埃尔托格·怒齿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6545, '战歌信使的报告', '', '', '哦，我的报告会向卡德拉克解释这一大堆事情，你必须尽快把这个交给他。', '那么，你是来给我传达上面的命令的?看见你这样体格健壮、意志坚定的新兵，我总是会感到很高兴。$B$B要是你希望继续在这里待下去的话，最好尽快成长起来。纳迦的威胁正在日益增长，$N。自从我到这儿之后，就开始着手研究对策，并在这个前哨站里抵挡了他们的多次进攻。$B$B但是如果你也想要投入到对敌作战中，就去跟这里的其它人也谈谈吧。', '', '去找费伍德森林的战歌信使。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6546, '战歌侍从的报告', '', '', '把我的报告交给卡德拉克，要快，$N。', '这条路上危机四伏，$N。你最好在整个旅途中都牢记这一点。联盟的威胁近在咫尺。$B$B我们已经陷入了四面受敌的困境，灰谷东部的萨特是一种可怕的生物，而纳迦也已经占据了艾萨拉的大片区域。$B$B我们的军队数量始终维持在较高的水准，这很好，随时准备应付我们的敌人吧，$N。', '', '去找艾萨拉的战歌侦查骑兵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6547, '战歌斥候的报告', '', '', '告诉卡德拉克，我们已经成功地阻止了夜精灵的进攻。一切进展顺利。', '保持警惕，$r。精灵总是潜伏在黑暗中……$B$B我们必须继续监视敌人。我们在努力地控制这片土地，而精灵也在寻找机会从我们手中夺走它。$B$B我想你是来传达卡德拉克下达给我的新命令的吧?', '', '去找灰谷的战歌斥候。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6548, '为我的村庄复仇', '恐怖图腾氏族劫掠了我的村庄，一个活口都没留下。我奋力杀敌，但还是差一点就被杀掉了。$b$b$N，现在我唯一的愿望就是让他们付出血的代价。你可以在这里的西面找到他们。', '杀掉8个恐怖图腾恶徒和6个恐怖图腾佣兵，然后向石爪山脉东南边界处的玛卡巴·扁蹄复命。', '$N，谢谢你……但我永远都不会忘记恐怖图腾氏族对我的村庄做过什么。', '你杀死他们了吗?', '', '去石爪山脉和贫瘠之地的交界处找玛卡巴·扁蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6561, '黑暗深渊中的邪恶', '我的力量已经离我而去。我需要你的帮助！$B$B很久以前，这里曾经是伟大的月神殿。但是不幸降临了，一名堕落的上古之神从地下冒出来，污染了神圣的月亮井。 $B$B上古之神的奴仆阿库麦尔从水中升起。$B$B暮光之锤的信徒和纳迦一起占领了这块土地。由克尔里斯领导的那些信徒为了让阿库麦尔获得力量而牺牲了许多无辜的生命。$B$B请你杀掉克尔里斯，把他的徽记交给雷霆崖的巴珊娜。', '把梦游者克尔里斯的徽记交给雷霆崖的巴珊娜·符文图腾。', '克尔里斯一直以来都在躲避着银色黎明的追杀。$B$B一段时间以来，他们认为他已经死了，或者是失踪了。$B$B你的行为使很多无辜的生命幸免于难，$N。$B$B大地之母会因此而赞扬你!为了个人利益而牺牲他人是一种可耻的行为!$B$B今天你做了一件伟大的事情。克尔里斯是一个恶魔，他想要通过膜拜如上古诸神这样的生物而把世界重新带回一片混乱之中。谢谢你，$N。', '愿大地之母与你同在，$N。$B$B世界和平是我们的目标。大地之母对整个世界有一个宏伟的计画，我们都在其中扮演了某种角色。', '', '去莫高雷的雷霆崖找巴珊娜·符文图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6563, '阿库麦尔水晶', '在通往黑暗深渊入口的通道中有许多生长在洞穴墙壁上的蓝宝石，最近有消息说纳迦正在挖掘这些宝石。在搞清楚他们的动机之前，我们应该先阻止它们。这些水晶中蕴含着强大的元素力量，只要经过一定的处理，它们就可以被制作成强大的魔法材料。$B$B你能帮帮我吗，$N？从我们的哨所往北走，然后就可以在佐拉姆海岸附近找到黑暗深渊了。', '收集20颗阿库麦尔蓝宝石，把它们交给灰谷的耶努萨克雷。', '干得好，$N。这就是我提到的那些水晶。真迷人……$B$B我可以感受到蕴藏在其中的力量，水之灵在水晶中激荡。纳迦想要利用它们……嗯，我们应该感到高兴，因为这些水晶已经不在他们手里了。', '搜寻水晶的工作进行得如何，$N?你有见到纳迦在采集它们吗?祖先保佑，希望我们能找到纳迦收集这些东西的原因。', '', '去灰谷找佐拉姆加前哨站的耶努萨克雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6564, '上古之神的仆从', '皱巴巴的便笺上潦草地写着：$B$B“对，通知所有的祭司把水晶带到我这里来，水元素的灵魂蕴含其中，它们能够很好地帮助我们的水占师进行召唤仪式。$B$B通过控制水晶中的力量，我们就可以取悦阿库麦尔。终有一天，我们会获得足够的力量，把阿库麦尔带回到我们身边，整个世界都将要迎接一个伟大的新时代！一个由上古之神统治的时代！”', '把潮湿的便笺交给灰谷佐拉姆加前哨站的耶努萨克雷。', '这确实非常有趣。很高兴你能把它交给我。$B$B现在我们可以找到这一连串麻烦的幕后真凶了……洛古斯.杰特。', '什么事，$N?你需要什么吗?对于纳迦正在收集的那些水晶，我还知之甚少。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6565, '上古之神的仆从', '我们绝对不能让这个暮光之锤的信徒完成他的计划。暮光之锤根本不了解自然的真义。他们信仰上古之神——很久之前就被击败了的、代表着混乱和毁灭的生物。你必须阻止洛古斯，$N。我无法自己来完成这个任务——因为我太脆弱了。$B$B到黑暗深渊去，找到他，杀了他。完成任务之后就回到我这里来。', '杀掉黑暗深渊里的洛古斯·杰特，然后向灰谷的耶努萨克雷复命。', '太好了!谢谢你，$N。我们也许无法完全阻止暮光之锤，但是你至少阻止了他们将上古诸神带回这个世界的计划。$B$B不晓得他们是不是还有别的计划在酝酿中，但是现在我们至少可以休息一下了。$B', '你找到他了没有，$N?我们必须阻止洛古斯!', '', '去灰谷找佐拉姆加前哨站的耶努萨克雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6566, '风吹来的消息', '很高兴再次看到你，$N。风从东部王国带来了新的消息。$B$B坐下，听我说。', '听萨尔讲话。', '你准备好接受这个任务了吗?', '耐心点，$N。注意听!', '萨尔的故事', '去找奥格瑞玛的萨尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6568, '幻术的欺诈', '你对幻象有什么了解吗，$N？你必须要制造一个幻象，这样你才能骗过那些黑龙的眼睛。$B$B我知道有一个人也许愿意帮你完成任务。她过去曾经帮助过我们，因此她值得信任。$B$B你可以在西瘟疫之地找到巫女麦兰达，她是被洛丹伦联盟放逐的幻术师。把这个交给她。', '把罗卡鲁的信交给西瘟疫之地的巫女麦兰达。', '<米兰达拿着便笺\r\n看了看，然后笑了笑。>$B$B他最近怎么样了?我说的是罗卡洛。哦，过来，不要感到奇怪。这张信纸是故意留着空白的，其中包含了罗卡洛的意图和想法。从其中的内容来看，无疑是罗卡洛故意这么做的。如果你被抓了或者被杀了的话，其中的资讯也不会泄露!$B$B哦，不要介意!米兰达会帮你的，$r。我欠大酋长的情。$B$B<米兰达微笑着。>', '我很少在这里见到部落来的$r。你给米兰达带什么来了?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6569, '黑龙幻象', '那么，一个$r想要变成一条黑龙，是吗？$B$B你所通过一个试炼才能制造幻象，但是我们所需的原料却是非常难以获得的。酋长非常信任你，而且把这个任务交给了你，所以麦兰达也同样认为你可以胜任。$B$B到黑石塔的上层堡垒去，杀掉足够多的黑色龙人，把它们的眼睛给我拿回来。', '到黑石塔去收集20颗黑色龙人的眼球，完成任务之后回到巫女麦兰达那里。', '让米兰达看看，$C。$B$B哦，没错，这些够用了。$B$B有了这些材料，米兰达就可以为你制作一枚勋章，有了它，你就可以创造一个用以迷惑黑龙军团看门者的幻影了。', '那些眼睛是制作幻影所必需的重要材料，$N。$B$B<米兰达指了指一个标着“血色十字军”字样的满是眼球的袋子，哈哈大笑着。>', '', '去西瘟疫之地找悔恨岭的巫女麦兰达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6571, '战歌氏族的补给品', '我们在战歌伐木场中的某些物资出现了短缺！$B$B碎木哨岗的皮克希尔有我们所需的战歌锯条，另外，你必须转至藏宝海湾，从码头管理员罗兹基尔那儿取回一箱斧头。$B$B不过要取回油和绳索就比较困难了。熊怪盗走了绳索，萨特截走了油，在它们的仪式中使用！$B$B如果我不能尽快把这批物资送过去，我可就麻烦大了——你能帮帮我吗？', '收集战歌氏族的补给品：战歌锯条、伐木绳、战歌之油，还有一箱战歌之斧。', '太棒了，$N。你帮我省了不少事儿!$B$B我对你非常感激!', '希望你能成功运送这批物资!如果我不快点运送这些货物我就会有大麻烦了!', '', '去灰谷找碎木岗哨的洛克·奥卡尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6581, '战歌锯条', '', '', '这真是太完美了―就是它!好吧，这是你要的货物。', '战歌锯刃!当然，我这儿就有。$B$B……但是你要如何回报我呢?要知道，你可不能白拿!我的时间可不能白费!$B$B我真正想要的是一把好枪，我要在旅途中随身携带它。女孩子要学会自我保护，你明白吗?我想，精通工程学的人可以毫不费力地制作出一把我喜欢的枪来。$B$B如果你能给我一把威力强大的火枪，我就给你这些锯刃。这笔交易如何?', '', '去找灰谷的皮克希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6582, '龙骨试炼，斯克利尔', '我们是死亡之翼的孩子，小黑龙。我们对于其它低等龙类的控制必须得到保障。$B$B如果你真的有价值的话，那些低等龙类就会因为你的到来而毁灭。$B$B找到他们，以我们父亲的名义消灭他们！$B$B到冬泉谷去猎杀强大的蓝龙斯克利尔，杀了它以及任何胆敢阻挡你的蓝龙。把它的颅骨给我拿回来。', '找到蓝龙斯克利尔并杀掉他。从他的身上取下他的颅骨，然后将其交给埃博斯塔夫。$B$B你可以在冬泉谷找到斯克利尔。', '第一个试炼结束了，接下来是第二个……', '<艾博斯塔夫发出嘶嘶声。>', '', '去找尘泥沼泽的埃博斯塔夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6583, '龙骨试炼，索姆努斯', '我们的父亲击溃了其它守护巨龙，我们也必须给他们的孩子带来混乱和毁灭。$B$B你必须在那些绿龙的孩子身上检验你的力量。$B$B到悲伤沼泽去找到索姆努斯，它是绿龙的勇士。让它感受你的愤怒，杀掉那只可怜的小虫……把他的颅骨给我拿回来……', '杀掉绿龙索姆努斯，把他的颅骨交给埃博斯塔夫。', '两个任务完成了，还有两个……', '在你浸浴敌人的鲜血前不要回来，让它们感受死亡和痛苦吧。', '', '去找尘泥沼泽的埃博斯塔夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6584, '龙骨试炼，克鲁纳里斯', '诺兹多姆，时间之王……他的孩子们……$B$B有三条龙看守着时光之穴，但我们黑龙只对其中一条感兴趣：时光的转换者，克鲁纳里斯，他是诺兹多姆最喜欢的孩子……$B$B把他杀掉，让整个沙漠都因你的力量而震动，把他的颅骨给我拿回来……', '诺兹多姆的孩子克鲁纳里斯在塔纳利斯沙漠守卫着时光之穴。杀了他，把他的颅骨交给埃博斯塔夫。', '最让人憎恨的那个还活着……', '小家伙，你必须知道，时间紧迫……', '', '去找尘泥沼泽的埃博斯塔夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6585, '龙骨试炼，埃克托兹', '我们的父亲在格瑞姆巴托的群山中大发神威，对抗守护之龙的力量。阿莱克斯塔萨，那个懦弱的背叛者，她畏怯地逃跑了。$B$B多么可耻的行为……$B$B现在红龙守卫着格瑞姆巴托，他们的领导者埃克托兹必须被干掉，把他的颅骨给我带回来。为了我们的父亲而战，小黑龙！', '到格瑞姆巴托去杀掉红龙埃克托兹，把他的颅骨交给埃博斯塔夫。', '我之前曾对你有所怀疑，小家伙。你坚持了下来，清除了我们的敌人，为我们黑龙带来了荣耀。$B$B接下来我要为你的庆典准备这些颅骨……', '改变……我感觉到了你的改变，小家伙。通过这个试炼，等着你的就是庆典了。', '', '去找尘泥沼泽的埃博斯塔夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6601, '晋升……', '我用我们的那些敌人的徽记制作了一枚勋章，你知道这枚勋章的用处吧？你以前一定看到过你的前辈戴着这样的一枚勋章了。$B$B拿着它，小黑龙。回到黑石塔去，把它给达基萨斯将军看看，将军会对它进行最后的点化，将它与你的灵魂绑在一起。$B$B完成之后的勋章将使你感到你所拥有的荣誉，它象征着你已经达到了一个令人敬畏的高度：我们母亲的守护者。$b$b现在就出发吧！', '看来这场假面舞会就要结束了。你知道麦兰达为你制作的龙形护符在黑石塔里面不会发挥作用，也许你应该去找罗卡鲁，将你的困境告诉他。把黯淡的龙火护符给他看看，也许他知道下一步该怎么做。', '那只是单纯龙与龙之间的对话，$N，热空气多过于实际有用的资讯。它们那些龙就只会采取豹而不实或者激进的行动。$B', '别慌，$N！', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6602, '黑龙勇士之血', '你要去拜访一下将军，没错，但并不是以黑龙的样子去拜访。$B$B你看，这个仪式所需的不过是更多的流血而已。$B$B这个未完成的饰物只需要将军的血就可激活，这是它们那野蛮而原始的备用机制。$B$B回到黑石塔去干掉达基萨斯，把他的血拿来给我，然后我就可以帮你激活开启奥妮克希亚巢穴的钥匙。', '到黑石塔去杀掉达基萨斯将军，把它的血交给罗卡鲁。', '你的英勇事迹将会永远流传，$N。龙火护符是通往奥妮克希亚巢穴的钥匙，聚集你的同伴，以部落的名义征服那里吧。', '达基萨斯并不是那么好对付的，$N。死在他手上的人不计其数。', '', '去凄凉之地找葬影村的罗卡鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6607, '钓鱼专家纳特·帕格', '我不能说我非常喜欢钓鱼，但是算起来我也已经钓了有二三十年了吧。$B$B我想很多人都是因为各种各样的原因而去做他们正在做的那些事情吧。$B$B当然，我的意思并不是你也得耐着性子钓三十年才能成为一个钓鱼高手。我想你只需有足够的耐心和定力，可以一坐就是几个小时，而且要在这期间什么都不干。$B$B我跟你说啊，给我抓来一些非常稀有的鱼，然后我就会教你几招。以下是列表：', '纳特·帕格要你钓到以下几种鱼：$B$B悲伤沼泽芦苇海岸的芦苇海岸大马哈鱼。$B$B凄凉之地萨瑟里斯海岸的萨瑟里斯虎鱼。$B$B菲拉斯沃丹提斯河的菲拉斯草鱼。$B$B荆棘谷野人海岸的野人海岸蓝色叉牙鱼。$B$B当你钓到这些鱼之后，就可以回到纳特·帕格那里去了！', '干得漂亮!$B$B来吧，让我教你几招钓鱼的方法吧。', '有东西上钩了吗?', '', '去尘泥沼泽找纳特的码头的纳特·帕格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6610, '蚌肉大餐', '你听说过蚌肉大餐没有？显然没有！这是我最最终极、最最伟大的烹饪杰作！哦，$N，只是想一想蚌肉大餐就足以让我垂涎三尺了。$B$B不幸的是，我没有足够的原料来烹饪它！我们来做笔交易怎么样？你为我收集必需的原料，我将这种无上美味的烹饪方法告诉你，此外我还请你吃一顿蚌肉大餐！如何？$B$B很好！我需要下列材料：', '迪尔格·奎克里弗想要你收集这些原料：$B$B10只巨蛋。你可以在塔纳利斯的大鹏或是其它大型鸟类那里获得这种蛋。$B$B10块美味的蚌肉。你可以从任何蚌类身上获得这种原料！$B$B20块奥特兰克冷酪。去买就是了！$B$B收集好所有原料，然后把它们交给迪尔格。', '你会被这种美味折服的，$N。看好了!$B$B<戴格开始准备蚌肉大餐。>', '我真是迫不及待了!在我把自己的存货都吃完之前，你得把这事给办妥了。', '', '去找塔纳利斯的迪尔格·奎克里弗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6621, '污林熊怪之王', '$N，熊怪的污林部族住在阿斯特兰纳的东南面。它们在数量上并没有蓟皮熊怪多，但是其残暴和好战的性格却对我们造成了巨大的威胁。我们必须给它们一个严厉的警告。$B$B拿着这面旗子，把它插在污林村庄的图腾堆中。这会激怒那些熊怪，让它们冲上来想要除去旗子，但是你一定要坚守自己的位置，最终你就会面对它们的酋长穆戈特。击败它，把它身上的图腾给我拿回来。$B$B别忘了和你的朋友一起去，$n，仅凭一个$c是无法成功的。', '把卡拉恩的旗子插到污林图腾堆中。不要让熊怪摧毁这面旗子。击败穆戈特酋长，将穆戈特的图腾交给佐拉姆加的卡拉恩·阿玛卡。', '干得好，$N。对污林熊怪发起挑战并击败它们的首领，这给它们传达了一个强烈的讯息:$B$B部落是不可轻视的。$B$B我相信那个熊怪部族好一段时间不会给我们惹麻烦了。', '你击败了穆戈特酋长了吗，$N?你拿回他的图腾了吗?', '', '去灰谷找佐拉姆加前哨站的卡拉恩·阿玛卡。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6622, '救死扶伤', '你好，医生。我们将在今天下午对你的医术进行检验。如果你通过了测试，那么你将荣幸地成为部落外科医疗队的一员。$B$B现在注意了！致命伤要优先处理，然后是重伤，伤势一般的病患放在最后处理。你必须拯救至少15个病人才能通过这个测试。如果有6个病人在这个过程中死亡，那么你就失败了。$B$B我们会给你提供治疗所需的绷带。$B$B祝你好运，医生。', '使用急救绷带来治疗病人。你必须在6个病人死亡之前拯救15个病人。$B$B一定要牢记治疗的顺序！受致命伤的病人会很快死亡，其次是重伤病人，受普通伤的病人死亡得最慢。所以你最好在治疗那些受致命伤和重伤的病人之后再去治疗受普通伤的病人。', '$N医生，欢迎加入联盟外科医疗队。', '干得太出色了，医生。实在是太出色了。', '拯救15个病人！', '去阿拉希高地找落锤镇的格里高利·维克托医生。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6624, '救死扶伤', '你好，医生。我们将在今天下午对你的医术进行检验。如果你通过了测试，那么你将荣幸地成为联盟外科医疗队的一员。$B$B现在注意了！致命伤要优先处理，然后是重伤，伤势一般的病患放在最后处理。你必须拯救至少15个病人才能通过这个测试。如果有6个病人在这个过程中死亡，那么你就失败了。$B$B我们会给你提供治疗所需的绷带。$B$B祝你好运，医生。', '使用急救绷带来治疗病人。你必须在6个病人死亡之前拯救15个病人。$B$B一定要牢记治疗的顺序！受致命伤的病人会很快死亡，其次是重伤病人，受普通伤的病人死亡得最慢。所以你最好在治疗那些受致命伤和重伤的病人之后再去治疗受普通伤的病人。', '$N医生，欢迎加入联盟外科医疗队。', '干得太出色了，医生。实在是太出色了。', '拯救15个病人！', '去尘泥沼泽找塞拉摩岛的古斯塔夫·范沃森医生。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6626, '邪恶之地', '被遗忘者不会因为他们的疾病而逝去……至少我所看到的是这样。这使得他们的追随者在某种意义上可以获得永恒的生命。我在想，他也许是亡灵天灾的一员。$B$B至于现在，我关注的不是他，而是他身边不断膨胀的部队。他们总是躲藏在阴影之中，总是向他祈求更多的力量。$B$B现在我无法自己去和他们作战，$N。你看怎么样\r\n？你做好大战一场的准备了吗？', '杀掉8个剃刀沼泽护卫者、8个剃刀沼泽织棘者和8个亡首教徒，然后向剃刀高地入口处的麦雷姆·月歌复命。', '谢谢你，$N!你所完成的任务无疑会给我们提供巨大的帮助，这一点我可以肯定。$B$B我会对这一地区的情况以及这里剩馀的野猪人继续进行研究。如果你想要迎接更大的挑战，那就召集一些同伴，进入那座仿佛巨大的野猪嘴的洞穴吧。我相信你会在洞中遇到更危险的敌人。', '狩猎行动进行得怎么样了，$N?看到这么一小批家伙，我就已经不再怀疑天灾军团是这个世界上最大的威胁了。', '', '转至贫瘠之地，去找剃刀高地入口附近的麦雷姆·月歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6627, '知识试炼', '你把这本书带来给了我，现在是向你提问的时候了。你准备好了吗？$B$B时间并不紧迫，$c，所以不要太紧张。你可以在准备妥当之后再来接受提问。', '成功回答布劳格·幽魂的问题，然后和他再次对话。他会一直在石爪山等你回答问题。', '干得好，$C。你已经认真读过了我要求你学习的东西，你通过了我们的又一个测试。', '生命中充满了疑问，$C。你永远无法全部回答它们，但是随着时间的流逝和学习的深入，也许你可以获得更多的知识。', '成功回答布劳格·幽魂的问题', '去找石爪山脉的布劳格·幽魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6628, '知识试炼', '我们又将面临一个考验。作为知识的学生，你在接受我的任务的时候展示了惊人的坚韧和决心。$B$B现在我将要向你提出一个问题。如果你准备好了，就再次和我说话，你的时间很充分，$N，别太着急。', '成功回答帕科瓦·芬塔拉斯的问题，然后再次和他对话。他会一直在幽暗城等你回答问题。', '干得好，$N。我曾经怀疑你是否认真读过了我要求你学习的那些文字，但是你做出了正确的回答。', '我觉得，如果你想要在这个世界上生存的话，就需要明白一个道理:你知道的越多，你能看到的就越多。$B$B如果你不断学习，不断观察，那么你就可以看到这个世界上的许多其它$r看不见的东西。', '成功回答帕科瓦·芬塔拉斯的问题', '去幽暗城找炼金房的帕科瓦·芬塔拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6629, '杀死格鲁迪格·暗云', '$N，你很好地完成了杀掉恐怖图腾成员的任务。如果你有胆量的话，就去挑战格鲁迪格·暗云和他的手下吧，他们是最难对付的敌人，而格鲁迪格就是攻击我们村庄的主谋。$B$B你可以在这里西边稍远的地方找到恐怖图腾岗哨，他就在那里。杀了他，我会永远感谢你的。', '杀掉格鲁迪格·暗云和6个恐怖图腾蛮兵，然后向石爪山东南面的玛卡巴·扁蹄复命。', '格鲁迪格.暗云死了!$N，我会永远感谢你的。', '你把格鲁迪格.暗云和他的手下都干掉了吗?', '', '去石爪山脉和贫瘠之地的交界处找玛卡巴·扁蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6642, '兄弟会的好感 - 黑铁矿石', '', '', '你的贡献被接受了。你获得了我们的好感。继续做下去，你就可以接触到那些历史悠久的生意了。', '黑铁矿蕴藏在黑石山脉的深处，对于兄弟会来说，它是很有价值的商品。拉格纳罗斯神圣的护甲和装备都需要黑铁。$B$B你每给我十块黑铁矿石，兄弟会对你的好感就会增加。', '', '去找奥特兰克山脉的罗克图斯·暗契。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6643, '兄弟会的好感 - 炽热之核', '', '', '你的贡献被接受了。你获得了我们的好感，继续做下去，你就可以接触到那些历史悠久的生意了。', '在熔火之心中人人命运难测，死亡说到就到，惩罚来得毫不留情。$B$B兄弟会里面有很多人为了搜寻炽热之核而丧失生命。$B$B给我一个炽热之核，兄弟会对你的好感就会增加。', '', '去找奥特兰克山脉的罗克图斯·暗契。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6644, '兄弟会的好感 - 熔岩之核', '', '', '你的贡献被接受了。你获得了我们的好感，继续做下去，你就可以接触到那些历史悠久的生意了。', '你和瑟银兄弟会同心同德，$r。因此洛克索斯才会被授权与你进行交易。$B$B拿一块熔岩之核来，你就会得到兄弟会的好感。', '', '去找奥特兰克山脉的罗克图斯·暗契。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6645, '兄弟会的好感 - 熔火犬皮', '', '', '你的贡献被接受了。你获得了我们的好感，继续做下去，你就可以接触到那些历史悠久的生意了。', '许多神圣的配方需要拉格纳罗斯心爱的宠物皮毛。$B$B拿二块来，将可以获得兄弟会对你的好感。从熔火之心的熔核犬身上割下的熔核犬皮。', '', '去找奥特兰克山脉的罗克图斯·暗契。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6646, '兄弟会的好感 - 山脉之血', '', '', '你的贡献被接受了。你获得了我们的好感，继续做下去，你就可以接触到那些历史悠久的生意了。', '火焰之王的眼泪是一种非常稀有的珍宝。$B$B给我一个山脉之血，你就可以获得兄弟会的好感。', '', '去找奥特兰克山脉的罗克图斯·暗契。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6661, '捕捉矿道老鼠', '慢着，你这饭桶。你……你在找活干吗？我们这儿鼠灾泛滥，甲板上人手不够。$B$B你说什么？你只需要吹奏这只捕鼠者之笛就行了，它们会跟着你走向生命的尽头！$B$B给我抓五只小坏蛋来，把它们交给我，我要活的。$B$B啊……', '使用捕鼠者之笛捕获5只矿道老鼠，把它们引到蒙提那儿去。别忘了退还笛子。', '很好，伙计。我兄弟需要欢蹦乱跳的老鼠，而不是已经腐烂发臭的……你也不想吃发酸的烤肉串吧?', '呀……$g哥们:小姐;，你还没搞定吗?', '', '去铁炉堡找坑道地铁的蒙提。', '捕获老鼠', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6662, '我的兄弟，尼普希', '我的兄弟尼普希在矿道的另一边经营一家烤老鼠肉的摊点。你必须在这箱老鼠坏掉之前把它们交给他。赶快！$B$B你以前坐过地铁的，对吧？很简单，只要等车停下，走上去，然后就享受你的旅程吧。在车行进时可别伸胳膊伸腿的，免得你下半辈子靠假肢过日子。', '把装着神秘肉品的纸箱交给暴风城矿道地铁仓库的尼普希。', '可怜的蒙提。自从诺姆瑞根事件后，他就变了。那个孩子从来都从没看过海，更不用说什么海贼了。$B$B<尼普希叹了口气。>$B$B至少他还一直为我供货。', '<尼普希把他的食指伸进纸箱的换气孔。>$B$B生气勃勃，活力十足……而且时间刚刚好!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6681, '拉文霍德庄园', '$N：$B$B拉文霍德已经对你感兴趣了，小贼。我们一直在观察你。你的状况有些尴尬，但没有什么是我们不能改变的。$B$B如果你想要在拉文霍德大人手下谋求一份工作，以及成为刺客联盟的一员，只需把拉文霍德徽记（已附在信中）拿到拉文霍德庄园来。$B$B你的第一项任务就是要找到庄园，它就隐藏在希尔斯布莱德的群山之中，你要充分发挥你的聪明才智。$B$B向你致敬，$B$B- 法拉德。', '把拉文霍德徽记交给拉文霍德庄园的法拉德，庄园就坐落在希尔斯布莱德的群山之中。$B$B你的智慧将在这次旅途中得到考验。做好准备吧。', '真精彩，小贼。$B$B你看起来似乎比较寒酸，但穿得还算得体。$B$B前面还有很长的旅程在等待着你去探索呢。你准备好迎接你在拉文霍德庄园的命运了吗?$B$B与外面的警卫谈谈，他们会告诉你如何开始的。', '你遇到密尔顿了吗?$B$B<法拉德笑了起来。>', '', '去希尔斯布莱德丘陵找拉文霍德庄园的法拉德。', '', '狡诈仪式', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6701, '辛迪加徽章', '', '', '哈哈，干得好!继续吧，其它的盗贼会对你刮目相看的。', '我们与辛迪加交战数年，他们战斗技艺极差，却屡屡以数量取胜。单凭砍杀是不可能对他们的数量造成明显影响的!$B$B不过我们发现，要削减辛迪加的人数，最好的办法是窃取他们的纹章。谁丢失了纹章，他们的组织就会“处理”谁。$B$B去翻他们的口袋，把纹章交给我或是其它的守卫。$B$B你就从南边的敦霍尔德城堡开始吧。', '', '去希尔斯布莱德丘陵的拉文霍德庄园找拉文霍德卫兵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6741, '取之于敌', '', '', '这些就很不错。我会把它们熔掉，然后重新打造成坚固的护甲，而且你根本看不出它们是从那些联盟的懦夫身上拿来的!$B$B谢谢你，$N。让我来帮你修补一下护甲……', '当你和敌人作战的时候，别忘了帮我收集他们的护甲碎块。我会用这些碎块来给我们自己的军队制造护甲!', '', '去找奥特兰克山谷的铁匠雷格萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6781, '护甲碎片', '', '', '这里有不少上好的材料呢，$N。我可以用这些东西来给我们的军队提供新的装备。$B$B如果我可以得到更多补给的话，也许我们的主力部队就就可以开进战场了!', '奥特兰克山谷中的战斗永不停息，从铁炉堡送来的补给并不能满足我们军队的需要。$B$B如果你可以从战场上收集护甲碎块的话，那就把它们交给我吧!', '', '去找奥特兰克山谷的莫高特·深炉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6801, '冰雪之王洛克霍拉', '', '', '我们敌人的鲜血洒满了战场。我会将这些血液和先前收集到的血液混合，在献祭结束之后，冰雪之王就会让这些雷矛矮人看看霜狼氏族的威力!', '我来自雷霆崖，$C。凯恩亲自指示我在眼前这个艰难的时刻协助霜狼氏族。$B$B我们简单明了地说吧，你必须击倒我们的敌人，把他们的鲜血交给我。一旦我收集到了足够的鲜血，召唤仪式就可以开始了。$B$B当元素之王冲入矮人的部队中时，胜利就是我们的了。', '', '去找奥特兰克山谷的指挥官瑟鲁加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6804, '被囚禁的水元素', '一支水元素侦查部队被派往洛丹伦的东瘟疫之地，但是那里的瘟疫把它们感染并扭曲了。我们水元素不允许这样的事情破坏我们的纯洁性！$B$B拿上这个瓶子，它里面装着的是海神之水。如果将它用在被感染的水元素身上，海神之水就会和它们身体中的毒素抗争，并治愈它们！但是水元素体内发生的争斗也会使它们变得非常疯狂。$B$B打败这些疯狂的水元素，然后把它们的缚灵护腕交给我。', '对东瘟疫之地的被感染的水元素使用海神之水。把12副不谐护腕和海神之水交给艾萨拉的海达克西斯公爵。', '你干得很好，$C。那些堕落的水元素对于所有的水体都是一种玷污。我们的力量来自于我们的纯洁性，如果我们要赢得这场战争，我们就必须保持强盛。', '你拿到那些护腕了吗?', '', '去艾萨拉找风暴海湾的海达克西斯公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6805, '雷暴和盘石', '我们水元素一直在与其它下等的元素生物交战。如果你在这场纷争中站在我们这一边，就拿出点证明来！$B$B在最南端的希利苏斯沙漠，空气元素和地元素的仆从聚集在一处被称作水晶谷的地方。它们保卫着某些强大的物品，不让你们这些凡人接触它们。尽管我不知道那些元素生物为什么要这样做，但我希望挫败他们。$B$B到希利苏斯的水晶谷去，击败我们的敌人，然后回到我这儿来。', '杀死15个灰尘风暴和15个沙漠奔行者，然后回到艾萨拉的海达克西斯公爵那儿。', '你证明了自己的勇敢，也证明了你对我们的价值。或许将来我还会交给你新的任务，更适合水元素的忠诚盟友的任务。', '胆怯不是我们所尊崇的品德，$C。去希利苏斯证明自己的勇敢吧。', '', '去艾萨拉找风暴海湾的海达克西斯公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6821, '艾博希尔之眼', '你已经证明了自己可以击败我们的敌人，并能为水元素执行更为艰巨的任务。但是到当前为止，你所面对的敌人并不算强大……如果面对强敌，你还能获胜吗？$B$B这就是你的新任务。$B$B兽人在黑石塔的高处捕获了一个火焰元素的仆从——烈焰卫士艾博希尔。找到关押他的地方，杀死看守着他的兽人，然后杀死艾博希尔。把他的眼珠交给我，以此来证明你的价值。', '将艾博希尔之眼交给艾萨拉的海达克西斯公爵。', '啊，你真能干。而且你还很聪明，显然单靠蛮力是不可能进入黑石塔的。$B$B$N，你真是个难得的盟友……', '你拿到眼珠了吗，$C?你有能力杀入黑石塔吗?', '', '去艾萨拉找风暴海湾的海达克西斯公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6822, '熔火之心', '$n，也许现在已经到了派给你一项真正的考验的时候了。你准备好了吗？$B$B在黑石深渊的底部有一条通往熔火之心的小径。那里是我们死敌的要塞，由这个世上最强大的火焰奴仆把守着。$B$B到熔火之心去，$N。让我看到你拥有足以打败他们的力量和意志。$B$B如果你有朋友和盟军，就召集他们。没有一支强大的军队，就别想进入熔火之心并活着出来。', '杀死一个火焰之王、一个熔岩巨人、一个上古熔火恶犬和一个熔岩奔腾者，然后回到艾萨拉的海达克西斯公爵那里。', '你已经做到了大多数$r都认为是绝无可能的事。你挑战了熔火之心中的敌人，并且获得了胜利!$B$B对于如此渺小的生物来说，你所拥有的力量非常惊人。$B$B也许有一天，我们水元素和你们$r将结成真正同生共死的盟约。', '胜利在熔火之心向你招手，$N。', '', '去艾萨拉找风暴海湾的海达克西斯公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6824, '敌人之手', '$N，你的贡献对我们来说是无价的，我们不愿意损失你这样一个有用的人才，但是为了最后一个任务，也只能勉强为之了。$B$B如果你成功了，战争的天平将朝着对我们有利的方向发展……它值得你为之冒险。$B$B我们要将盘踞在熔火之心的几个火元素的头目干掉：鲁西弗隆，萨弗隆，基赫纳斯和沙斯拉尔。杀了他们，把他们的手给我拿来！$B$B这项任务需要你尽全力而为之，$N，如果你能够成功的话，火元素将遭受重大的打击。', '将鲁西弗隆之手、萨弗隆之手、基赫纳斯之手和沙斯拉尔之手交给艾萨拉的海达克西斯公爵。', '你成功了!火元素的头目们都被击败了!我原本以为这是不可能完成的任务，我没有想到你是如此的强大。$B$B$N，你对水元素做出了巨大的贡献，你的名字将在水元素的贵族之间传播。$B$B待会儿再和我对话，$N。我也许会给你另外一个任务……', '你打败鲁西弗隆和其它的家伙了吗，$N?你拿到他们的手了吗?', '', '去艾萨拉找风暴海湾的海达克西斯公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6825, '天空的召唤 - 古斯的部队', '', '', '我们需要更多的肉来喂养部队，这将不断消耗敌人的实力。$B$B空军已经准备完毕了!', '我们必须准备新的空军部队，$C!我们的驭风者已经准备就绪了，但是首先，我必须让它们吃饱喝足，这样它们才能做好突击的准备!$B$B雷矛士兵总会随身带着一些肉，从他们那里把肉抢过来，让我们的双足飞龙吃饱!我相信你可以办成这件事的，对不对?出发吧!', '', '去找奥特兰克山谷的空军指挥官古斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6826, '天空的召唤 - 杰斯托的部队', '', '', '更多的肉!更多的肉!多带点肉回来，那我的部队马上就能出发了!', '你工作得很努力，$N，但是我们只是刚刚开始而已!$B$B我的驭风者部队要在吃饱之后才能对敌人发起突袭!$B$B我的部队在我们的空军中实力排名第二，它们将对敌人最强的部队发起进攻。因此它们也需要优质的食物，从雷矛士官那里抢夺他们随身携带的生肉吧。$B$B快点出发，勇士!', '', '去找奥特兰克山谷的空军指挥官杰斯托。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6827, '天空的召唤 - 穆维里克的部队', '', '', '还不够!这些肉对于一个新手来说还差不多，但是你，$N?再努力一些，士兵!快点行动!我们需要更多的肉!', '我曾经被终日锁在一个矮小的洞穴里，我要报仇!$B$B我们必须仔细计画一下。$B$B首先，我的驭风者必须吃到最优质的食物，才能储备精力以待发起攻击。从雷矛指挥官那里抢一些生肉来喂养它们。不幸的是，那些可恶的家伙都躲在最后方!显然，你面临的是一个艰巨的任务。', '', '去找奥特兰克山谷的空军指挥官穆维里克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6844, '档案管理员阿姆伯尔', '我们有很多事情要做，但是我认为把这个带回议会进行分析是最关键的。相信我，如果这团粘呼呼的东西里面是一本日记的话，议会将最终打开通往过去的窗口！$B$B把这个交给永夜港议会的档案管理员阿姆伯尔，他是个才华横溢的人，虽然有些疯疯癫癫，但是真的非常能干！阿姆伯尔曾补救许多远比这本书更破旧的典籍，他肯定可以胜任这个工作。。', '将异种蝎粘液包裹的物体交给月光林地永夜港的阿姆伯尔，他是塞纳里奥议会的档案管理员。', '哦，瞧瞧，这是什么?我猜是书吧……我可以尝试补好剥落的部分。$B$B是莱耶要你从希利苏斯跑到我这儿来的?我听到一些零零碎碎的谣言，说是有很恐怖的东西在那里出没。结合我不喜欢跟虫子打交道的个性，你就能明白我为什么要待在这里整天对付这些书了!', '嘿，你好!嗯……$B$B老实对你说，朋友……你的体味有些夸张。也许有人说你浑身都散发着恶臭。我不会对你的种族进行抨击，我只是说说……下一次你离开战场的时候最好清洗一下，这会使你给其它人留下的第一印象大大改善!$B$B总之……我能为你做什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6846, '展开攻击！', '', '', '啊，命令下来了!他们说我可以随时发动攻击，那么……就现在吧!', '我的军队已经整装待发，准备攻击。只要诺雷格.雷矛中尉一声令下，我们就会发起冲锋!', '', '去找奥特兰克山谷的特拉瓦雷元帅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6881, '森林之王伊弗斯', '', '', '干得好，$N，但是我们还需要更多的水晶。森林之王是我们对抗堕落力量的关键!', '霜狼氏族被一种堕落的元素能量保护着。如果我们不加以注意的话，他们的萨满必然会利用这种力量来毁掉我们。$B$B这种能量已经不是议会可以控制的了!我们必须找到伊弗斯，寻求他的帮助。$B$B霜狼氏族的战士身上带着一种名叫暴风水晶的符咒，我们可以用这些符咒来召唤伊弗斯。快去拿来那些水晶吧，$N!', '', '去找奥特兰克山谷的大德鲁伊雷弗拉尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6921, '废墟之间', '暮光之锤已经进入了黑暗深渊中的月光神殿废墟里去了，他们的目标肯定是要强迫元素生物来对付我们。如果我们不及早采取对策的话，这个地区就将永远被他们控制。$B$B到黑暗深渊去找到废墟中的深渊之石，它应该在靠近水边的地方。深渊之石里面是深渊之核——那里面记载了所有元素生物的历史。如果我拥有了它，我和大地之环就能阻止他们了！', '把深渊之核交给灰谷佐拉姆加前哨站里的耶努萨克雷。', '这正是我需要的东西!深渊之核是个非常完美的资讯源，我可以从中获取许多资讯。不管暮光之锤在干什么―反正肯定不会是什么好事情―我和我的同事都会努力找出真相。$B$B你干得很好，大地之环非常感谢你对我们的帮助。同时，你也帮助了整个部落，因此你应该感到光荣。', '你找到深渊之核了吗?没有它的话，我们就无法得知暮光之锤究竟在那里做什么。', '', '去灰谷找佐拉姆加前哨站的耶努萨克雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6922, '阿奎尼斯男爵', '被击败的水元素留下了一个奇怪的水球，你猜想这东西可能是为水元素提供能量的。一股看起来就很恶心的水流在球体内翻腾喷溅，而球体本身似乎不受任何自然力的影响。$B$B如果说有人能对这个东西有所了解，那就只能是大地之环的耶努萨克雷了。他就在灰谷的佐拉姆加前哨站里。', '把奇怪的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。', '这……这真是一个大发现，$N。$B$B你说你是从黑暗深渊的阿奎尼斯男爵那里得到这东西的?阿奎尼斯男爵一直以来都被认为是腐败的元素生物，这个球体将证明到底是什么腐蚀了它。如果最终证明是暮光之锤搞的鬼，那么我一点也不会感到吃惊，但是我们的研究还是可以搞清楚他们是怎么做的。$B$B感谢你把这个球体交给我，请接受大地之环最诚挚的敬意。', '啊，又见面了，$N。我正在像往常一样观察海洋的波涛。什么风把你吹到这里来了?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6941, '天空的召唤 - 维波里的空军', '', '', '空袭马上准备就绪。继续努力吧!', '你必须去对付守卫前线的部落精英士兵!我现在命令你去削弱那些绿皮蛮子的力量，把他们的中尉和军团士兵的勋章给我拿来。当我拿到足够的勋章时，我会命令开始对他们进行空中打击的。', '', '去找奥特兰克山谷的空军指挥官维波里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6942, '天空的召唤 - 斯里多尔的空军', '', '', '继续带勋章回来，士兵!狮鹫兽空袭马上就要准备好了!', '我的狮鹫兽应该在前线作战，但是在那里的敌人被削弱之前，它们是无法发动攻击的。$B$B部落的战士胸前挂着代表荣誉的勋章勇猛冲锋，而你要做的就是从他们腐烂的尸体上把勋章拿下来，并把它们交给我。$B$B只要敌人在前线的力量受到足够的打击，我就会发出命令进行空袭!我们将从空中给敌人造成致命的创伤!', '', '去找奥特兰克山谷的空军指挥官斯里多尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6943, '天空的召唤 - 艾克曼的空军', '', '', '你看到了吗?看看它们，$C!它们开始跃跃欲试了……不久之后，艾克曼的空军将再次发动对部落的空袭!雷矛部族将主宰天空!', '它们的士气很低，战士。自从我们上次对部落的空中打击失败之后，它们就拒绝再次飞行!你必须鼓舞它们的士气。$B$B回到战场并攻击部落的核心力量，杀死他们的指挥官和卫兵。尽可能带回更多的勋章!我向你保证，当我的狮鹫兽看到这些战利品并嗅到敌人的鲜血时，它们就会再次起飞!现在就出发吧!', '', '去找奥特兰克山谷的空军指挥官艾克曼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6962, '冬幕节的礼物', '嗨，年轻的$g小伙子:姑娘;，你能帮冬天爷爷一个忙吗？$B$B似乎没有必要以第三人称来称呼自己，但是冬天爷爷在这儿一整天了，他也想要一份礼品呢。小姜饼和冰镇牛奶正合他的胃口。你能为冬天爷爷取些来吗？', '将5个小姜饼和一杯冰镇牛奶交给奥格瑞玛的冬天爷爷。', '你对冬天爷爷真是太好了，$N。祝你冬幕节快乐。$B$B这些小东西……就当作给你的奖励吧。', '一天到晚给别人礼物让我自己也想要礼物了。嗯……我要姜饼和牛奶……', '', '去找奥格瑞玛的冬天爷爷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6981, '发光的碎片', '这块碎片透出异样的绿色光芒，虽然它完全是一块固体，但是却让人感觉好像有一股烟从碎片中冒出来。你情不自禁地注视着这块水晶的深处，这时你突然觉得这其中必定包含着许多曲折的故事。$B$B也许你应该去棘齿城看看那里有没有人知道这块碎片的来历。', '寻找更多有关这块噩梦碎片的信息。', '哦……我从来没有见过这种东西……', '你好啊，风尘仆仆的$r。我可以为你做些什么吗?', '找人谈谈噩梦碎片的事情', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6982, '冷齿矿洞的补给', '冷齿矿洞是部落的物资储存点。他们的军粮实在不是我们能吃下去的东西，但是他们的武器和护甲却很棒！在眼下这种物资十分短缺的时候，我们要利用一切可以利用的东西！$B$B进入冷齿矿洞，帮我把他们的补给品拿回来。那些补给品可以帮助联盟保持战斗力，同时也削弱了部落。$B$B祝你好运，$N。那座矿洞在南边很远的地方，就在部落领地的深处。', '把10份冷齿矿洞补给品交给丹巴达尔的联盟军需官。', '你拿到它们了!干得好，$N!我会好好利用这些补给来加强我们的部队!', '你去过部落领地中的冷齿矿坑了吗，$N?你有没有抢到他们的补给品?', '', '去奥特兰克山谷找丹巴达尔的雷矛军需官。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6983, '天寒地冻', '有有有有个名叫格林奇的家伙，他他他偷走了我们的礼礼礼品，$N。要小小小心！是他让我在这冰冰冰冰天雪地里乱作一团！$B$B如果你要跟跟跟他对抗的话，你就就就需要帮助。我看到他在雪雪雪怪出没的地方徘徊，他他他他肯定就在那附附附近！找找找回礼品，$N，带带带回奥格瑞玛的烟林牧场零售店去，告告告诉他们想办法给我解冻！', '寻找被偷走的礼品，把它交还给奥格瑞玛的凯玛德·考伯宾奇。看起来是格林奇偷走了礼品，他就在奥特兰克山脉雪域附近。', '你找到它了!你拯救了熏木牧场冬幕节的礼物!$B$B可怜的萨克斯……我们会派一支队伍去找他并想办法帮他解冻的。希望他能够及时回来和我们一起欢度这个节日;虽然他要补上这段时间没有干的活。这些都是因为你的功劳才能够实现的啊!', '$N―我们冬幕节的礼物如果没有那些货物的话就准备不好了!格拉库就没有机会和这些好孩子们一起分享他的美味肉派了……', '', '去找奥格瑞玛的凯玛德·考伯宾奇。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6985, '深铁矿洞的补给', '雷矛部族的矮人把深铁矿洞作为储藏物资的地方。我要派你去那个矿洞里，把里面的补给品给我拿回来。这样不但可以削弱雷矛部族在奥特兰克山谷的势力，还可以给我们提供必需的物资！$B$B小心一点，$N。深铁矿洞在联盟的控制下，如果我们能控制那座矿洞，那么整个奥特兰克山谷就会被我们牢牢掌握。', '把10份深铁矿洞补给品交给霜狼要塞的部落军需官。', '你拿到它们了!干得好，$N!你有没有顺便干掉几个矮人?', '你去过深铁矿坑了吗，$N?你有没有拿到那里的补给品?', '', '去奥特兰克山谷找霜狼要塞的霜狼军需官。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7001, '补充坐骑', '奥特兰克山谷中的战争在不断消耗我们的军力，因此我们必须不断补充新的力量！$B$B如果我们可以找到更多的坐骑，狼骑兵部队就能再一次投入战斗之中。$B$B拿上这根缰绳，去追踪附近森林中的霜狼。一旦你找到了霜狼，就对它使用缰绳以驯服它。把驯服的霜狼带回我这里来，这样我就可以把它编入骑兵部队了。$B$B当我们拥有足够的坐骑之后，狼骑兵就会再一次冲锋陷阵！', '找到奥特兰克山谷中的霜狼。使用霜狼口套来驯服它们。被驯服的霜狼会跟随你回到兽栏管理员那里，然后与兽栏管理员谈话以获得你的奖励。', '我希望那些收集山羊皮的家伙具有与你一样坚定的决心，$N。$B$B按照这种速度，我们的兽栏很快就将爆满!', '没有你的帮助，霜狼氏族的狼骑兵就无法获得足够的坐骑来进行作战。你干得很好!', '驯服并上缴霜狼', '去找奥特兰克山谷的霜狼兽栏管理员。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7002, '羊皮坐具', '', '', '干得好，士兵。当我收集到足够的皮毛时，我会通知你的。$B$B继续好好干吧!', '在我们的一些战士帮助兽栏管理员捕捉巨狼的同时，其它人还需要去找一些将它们变成坐骑所必需的东西，比如缰绳和坐鞍。$B$B你必须去猎捕这个地区的山羊，也就是那些与雷矛骑兵的坐骑很相似的山羊!$B$B杀了它们，把它们的皮交给我。只要收集到足够多的羊皮，我们就可以开始为骑手们制作坐具了。霜狼部族的狼骑兵很快就将再次驰骋在战场上!', '', '去找奥特兰克山谷的霜狼骑兵指挥官。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7003, '被缩小的巨人', '如果我还想继续在这里混的话，就必须对那些巨人采取一些措施了！他们把我的生意搞得一团糟，难道不是吗？$B$B眼下我正在实验各种各样的侏儒缩小射线，但是重点在于，我用尖端的地精科技强化了这种装置！为了防止它可能对我自身造成的各种不良影响，比如死亡之类的，我希望你用它在菲拉斯的任何一种巨人身上试验一下。在你把他们缩小之后，就可以从他们身上找到微缩残渣——把那种东西拿来给我！', '使用索尔宾的超级压缩器来缩小菲拉斯的任意种类的巨人，将他们缩小到更容易控制的体积。从缩小过的巨人身上收集15份微缩残渣，把它们交给菲拉斯被遗忘的海岸码头的索尔宾·范达瑟。', '太棒了!让我高兴的不仅是你带回了微缩残渣，而且你压根没有缺胳膊少腿!这就是说，使用超级压缩器没有危险，太好了!$B$B感谢你对我的帮助，$N。你真是哥布尔的朋友。请收下这个吧!', '微缩残渣，我可以确信地告诉你，它是工程学中非常重要的一种材料!好吧，它可以确保压缩器不会发生诸如爆炸之类的让人感到不爽的故障。$B$B哦，我说的当然不是给你的那一台。当然不是!', '', '去菲拉斯的被遗忘的海岸找索尔宾·范达瑟。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7025, '冬幕节的礼物', '嗨，年轻的$g小伙子:姑娘;，你能帮冬天爷爷一个忙吗？$B$B似乎没有必要以第三人称来称呼自己，但是冬天爷爷在这儿一整天了，他也想要一份礼品呢。小姜饼和冰镇牛奶正合他的胃口。你能为冬天爷爷取些来吗？', '将5个小姜饼和一杯冰镇牛奶交给铁炉堡的冬天爷爷。', '你对冬天爷爷真是太好了，$N。祝你冬幕节快乐。$B$B这些小东西……就当作给你的奖励吧。', '所有这些关于礼物的谈话都让我十分向往。嗯~~~~~姜饼与牛奶…', '', '去找丹莫罗的冬天爷爷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7026, '山羊坐具', '', '', '干得好，士兵。当我存储了足够的皮毛之后，我就会通知你。$B$B继续努力吧!', '没有鞍具，雷矛部族就无法重新投入到战斗中!我们必须为坐骑配上鞍具，这样我们才不会像野蛮人一样骑着一头光溜溜的山羊。$B$B我们可以简单地干掉基地周围的山羊来获得皮革，但是那样做是非常愚蠢的。因为我们还要把那些山羊驯化成坐骑哪!$B$B你必须去攻击敌人的基地，杀死他们的霜狼坐骑，然后拿回他们的皮。把它们的皮交给我，这样我就可以帮我们的骑兵制作鞍具了。出发吧!', '', '去找奥特兰克山谷的雷矛山羊骑兵指挥官。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7027, '补充坐骑', '看看这里的兽栏，$N！空空如也！雷矛部族的骑兵部队没有坐骑——它已经名存实亡了。$B$B你必须帮助我们，士兵。拿着这根颈圈，到山谷中去寻找四处徘徊的奥特兰克山羊，并使用训练颈圈来抓住它们。当你抓住山羊之后，就把它给我带回来，然后我就可以将它配备给骑兵部队了。$B$B当我们有足够的山羊之后，山羊骑兵将再次准备就绪。有了你的帮助，骑兵部队将会获得重生！', '找到奥特兰克山谷中的山羊。使用雷矛训练颈圈来驯服它们。被驯服的山羊会跟随你回到兽栏管理员那里，然后与兽栏管理员谈话以获得你的奖励。', '兽栏马上就会被山羊挤满了。继续好好干!', '没有你的帮助，雷矛部族的山羊骑兵就无法获得足够的坐骑来进行作战。你干得很好!', '驯服并上缴山羊', '去奥特兰克山谷找丹巴达尔的雷矛兽栏管理员。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7028, '扭曲的邪恶', '泰拉莫克水晶洞穴坐落在这里的西边，在玛拉顿的深处……那里是一处拥有悠久历史的古迹。我希望从那里得到一些东西，$c。上古之神的遗物就在那些巨门的后面。$B$B如果你愿意挑战潜伏在玛拉顿里的那些扭曲的邪恶力量，我一定会让你为做出这个决定而感到满意的。收集你所找到的瑟莱德丝水晶雕像，把它们交给我。$B$B一旦我拿到雕像，我就能……研究它们。雕像中蕴含的力量已经沉睡太久了……', '为凄凉之地的维洛收集15个瑟莱德丝水晶雕像。', '哈哈哈!我知道你会回来的。$B$B<维洛自言自语着。>$B$B……太容易说服了。$B$B……看来只要有钱，什么事都好办。呵呵呵呵……', '不要问问题!$B$B我给你的指示是非常明确的。', '', '去找凄凉之地的维洛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7029, '维利塔恩的污染', '一个名叫维利塔恩的萨特正在玷污玛拉顿的洞穴，使那里的许多植物无法生长。$B$B拿着这个瓶子，$N。用洞穴里面橙色水晶池中的水装满这个瓶子；瓶中所包含的物质可以中和毒药，将它变成一种治疗药剂。$B$B你可以在橙色的洞穴中找到维利斯塔姆藤蔓，然后对它们使用净化过的液体。这样，附着在植物上的堕落物质就会被净化，但是你要知道维利塔恩仍然控制着这些植物。他会利用它来对付你……', '在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。$B$B在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。$B$B治疗8株植物并杀死那些诺克赛恩幼体，然后向葬影村的瓦克·战痕复命。', '感谢你把这个拿回来交给我，$N。有了这些剩下的液体，我就可以继续进行研究了。$B$B虽然现在我们还有很多事情要做，但是你至少帮我阻止了维利塔恩的堕落力量继续在玛拉顿中蔓延。请接受这个作为我的感谢。', '如果你可以治疗那些植物，它们就可以再次生长了。我们必须尽力而为，$N……', '', '去凄凉之地找葬影村的瓦克·战痕。', '治疗维利斯塔姆藤蔓', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7041, '维利塔恩的污染', '一个名叫维利塔恩的萨特正在玷污玛拉顿的洞穴，使那里的许多植物无法生长。$B$B拿着这个瓶子，$N。用洞穴里面橙色水晶池中的水装满这个瓶子；瓶中所包含的物质可以中和毒药，将它变成一种治疗药剂。$B$B你可以在橙色的洞穴中找到维利斯塔姆藤蔓，然后对它们使用净化过的液体。这样，附着在植物上的堕落物质就会被净化，但是你要知道维利塔恩仍然控制着这些植物。他会利用它来对付你……', '在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。$B$B在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。$B$B治疗8株植物并杀死那些诺克赛恩幼体，然后向尼耶尔前哨站的塔琳德莉亚复命。', '感谢你把这个拿回来交给我，$N。有了这些剩下的液体，我就可以继续进行研究了。$B$B虽然现在我们还有很多事情要做，但是你至少帮我阻止了维利塔恩的堕落力量继续在玛拉顿中蔓延。请接受这个作为我的感谢。', '如果你可以治疗那些植物，它们就可以再次生长了。我们必须尽力而为，$N……', '', '去凄凉之地找尼耶尔前哨站的塔琳德莉亚。', '治疗维利斯塔姆藤蔓', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7043, '天寒地冻', '有有有有个名叫格林奇的家伙，他他他偷走了我们的礼礼礼品，$N。要小小小心！是他让我在这冰冰冰冰天雪地里乱作一团！$B$B如果你要跟跟跟他对抗的话，你就就就需要帮助。我看到他在雪雪雪怪出没的地方徘徊，他他他他肯定就在那附附附近！找找找回礼品，$N，带带带回铁炉堡的烟林牧场零售店去，告告告诉他们想办法给我解冻！', '寻找被偷走的礼品，把它交还给铁炉堡的乌莫尔特。看起来是格林奇偷走了礼品，他就在奥特兰克山脉雪域附近。', '你找到它了!你拯救了熏木牧场冬幕节的礼物!$B$B可怜的萨克斯……我们会派一支队伍去找他并想办法帮他解冻的。希望他能够及时回来和我们一起欢度这个节日;虽然他要补上这段时间没有干的活。这些都是因为你的功劳才能够实现的啊!', '$N―我们冬幕节的礼物如果没有那些货物的话就准备不好了!格拉库就没有机会和这些好孩子们一起分享他的美味肉派了……', '', '转至铁炉堡，去找平民大厅的乌莫尔特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7044, '玛拉顿的传说', '一个名叫维利塔恩的黑暗萨特在这些蜿蜒曲折的洞穴中散播着他的邪恶力量。他住在有着紫色水晶的入口那边。$B$B维利塔恩还创造了一个名叫诺克赛恩的堕落生物，让它把守在有着橙色水晶的入口那边。他们偷取了我兄弟的节杖。塞雷布拉斯，我的兄弟……他在洞中毫无目的地游荡，被堕落的力量所诅咒。$B$B你必须帮助他！找到节杖的两个部分，然后……想办法和我兄弟谈谈。', '找回塞雷布拉斯节杖的两个部分：塞雷布拉斯魔棒和塞雷布拉斯钻石。$B$B然后设法和塞雷布拉斯对话。', '现在你找到了权杖的两个部分，玛拉顿终于有了摆脱维利塔恩堕落力量的希望。', '我从看似永无止境的梦魇中醒来……', '', '去找玛拉顿的塞雷布拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7046, '塞雷布拉斯节杖', '我的权杖是我希望的源泉。它的力量可以让我自由穿梭于这些洞穴中。我希望能够让我叔叔的灵魂得到安宁……这是我要交给你的任务。$B$B为了让这两个部分再次结合起来，我需要你的协助来完成仪式。请跟着我，听从我的指示行动，然后我就会重新把钻石镶到节杖上。$B$B让我们一起把塞雷布拉斯节杖重新组合起来！', '帮助赎罪的塞雷布拉斯制作塞雷布拉斯节杖。$B$B当仪式完成之后再和他谈谈。', '请拿着这个，你一定要好好利用它。继续你的旅程，带着希望穿越洞穴，你可以找到我的叔叔的遗体。前方还有很多危险在等着你，$N。$B$B如果你需要的话，就再次找我对话。', '如果你希望重新启动仪式，请放弃我们的这一次尝试，然后再和我谈谈。', '制造塞雷布拉斯节杖', '去找玛拉顿的塞雷布拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7061, '冬幕节', '嗯——如果你对冬幕节的历史知识感兴趣的话，就读读这本书吧。虽然我认为我们对传说的认知是正确的，但是我是个真正的学者，我希望能收集到全面的信息。$B$B阅读完这本书后，将它交给雷霆崖的凯恩·血蹄。要是听说有人对我们的传说感兴趣，他会很开心的。', '阅读《冬幕节》学习更多关于该节日的知识。当你读完后，将书交给雷霆崖的凯恩·血蹄。', '笼罩着冬幕的传奇与故事在这几年中已经慢慢地由广为人知变得较为隐密了。我知道哥布尔们为了他们自己而正在帮忙提倡这个节庆，而我们族人的反应至少在某种形式上对于保住这些传说是有帮助的。$B$B你想要越过物质并且学习我们的过去是值得敬佩的特质，年轻的$C。我向你的智慧致敬。', '我敢打赌莫高雷以及谦卑的雷霆崖都非常欢迎你，朋友。我对选择去关注王国，人民以及其传说的人一直都非常的感兴趣，这就是你站在我面前的原因吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7063, '冬幕节', '嗯——如果你对冬幕节的历史知识感兴趣的话，就读读这本书吧。虽然我认为我们对传说的认知是正确的，但是我是个真正的学者，我希望能收集到全面的信息。$B$B阅读完这边书后，将它交给国王麦格尼·铜须。要是听说有人对古老的传说感兴趣，他会很开心的。', '阅读《冬幕节》学习更多关于该节日的知识。当你读完后，将书交给铁炉堡国王麦格尼·铜须。', '笼罩着冬幕的传奇与故事在这几年中已经慢慢地由广为人知变得较为隐密了。当我察觉到哥布林们为了他们自己而正在帮忙提倡这个节庆时，我们族人的反应至少在某种形式上对于保住这些传说是有帮助的。\r\n\r\n你想要越过物质并且学习我们的过去是值得敬佩的特质，年轻的$C。我向你博学的天性致敬。', '我敢打赌铁炉堡王国很欢迎你，朋友。我对选择去关注王国，人民与及其传说的人一直都非常的感兴趣，这是你站在我面前的原因吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7064, '大地的污染', '在玛拉顿的深处居住着一个邪恶的混乱生物——瑟莱德丝公主，她是一个和上古之神相关的地元素。很早以前，她和塞纳留斯的长子扎尔塔结合，他们的后代……被称为半人马。那些半人马杀掉了扎尔塔，并保留了他的遗体。我的任务是征召足够强大的冒险者去杀死瑟莱德丝，这样我们就可以在回到石爪山之前找到扎尔塔的遗体了。', '杀死瑟莱德丝公主，然后回到凄凉之地葬影村附近的瑟琳德拉那里复命。', '这个消息真是再好不过了，$N!谢谢你!$B$B我原本想要和玛兰迪斯谈谈，并就札尔塔遗体的问题寻求他的指引，但是你已经克服了这个任务中最困难的部分。$B$B我这里有些东西，是为那些帮助我们的冒险者准备的。你帮了我们的大忙，因此，你可以从中选择一件来作为报酬。', '我原本想要自己去进行这场战斗，但是我们没有选择―我们需要更加强大的帮手，而艾泽拉斯的各个种族早已证明，只要他们团结起来就可以击败非常可怕的敌人。所以我寻求你的帮助。$B$B我希望这已经足够了。$B$B作为雷姆洛斯的兄弟，札尔塔给这个世界带来了无尽的痛苦，并最终导致了他自己的死亡。我只希望我们不会再造成更多的死亡。', '', '去凄凉之地找萨瑟里斯海岸的瑟琳德拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7065, '大地的污染', '在玛拉顿的深处居住着一个邪恶的混乱生物——瑟莱德丝公主，她是一个和上古之神相关的地元素。很早以前，她和塞纳留斯的长子扎尔塔结合，他们的后代……被称为半人马。那些半人马杀掉了扎尔塔，并保留了他的遗体。我的任务是征召足够强大的冒险者去杀死瑟莱德丝，这样我们就可以在回到石爪山之前找到扎尔塔的遗体了。', '杀死瑟莱德丝公主，然后回到凄凉之地尼耶尔前哨站的守护者玛兰迪斯那里复命。', '这个消息真是再好不过了，$N!谢谢你!$B$B虽然你无法带回札尔塔的遗体来让我当面质问这个塞纳留斯的长子，但是半人马的意志会慢慢被消磨，他们对于鲜血的渴望会慢慢衰减―我们希望如此。$B$B我这里有些东西，是为那些帮助我们的冒险者准备的。你帮了我们的大忙，因此，你可以从中选择一件来作为报酬。', '我原本想要自己去进行这场战斗，但是我们没有选择―我们需要更加强大的帮手，而艾泽拉斯的各个种族早已证明，只要他们团结起来就可以击败非常可怕的敌人。所以我寻求你的帮助。$B$B我希望这已经足够了。$B$B作为雷姆洛斯的兄弟，札尔塔给这个世界带来了无尽的痛苦，并最终导致了他自己的死亡。这对我们来说是很有报警意义的。', '', '去找凄凉之地的守护者玛兰迪斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7066, '生命之种', '这些私生的半人马——我的儿子和女儿——需要他们的父亲。$B$B看看你的周围——这个地方遍布着希望，遍布着我父亲塞纳留斯梦想中的宁静。它们在从我的体内源源不断地涌出来！我不能剥夺他们享受这一切的权利……即便他们对我犯下了深重的罪恶。$B$B但是我有一件事情需要请你帮助，以便让我兄弟的心灵得到抚慰。拿着这个……这是我的遗体孕育出来的第一颗种子。告诉他，我的灵魂还在这里，我还在继续活着。我相信他可以理解我。', '到月光林地去找到雷姆洛斯，将生命之种交给他。', '那么说来我的兄弟终于安息了?我很荣幸能够在有生之年得知这件事。他的傲慢自大和愤怒让我以为他已经远离了我们，但是他……他的牺牲证明我错了―他已经重生了。他尽到了自己对大自然的职责。$B$B谢谢你，$N。你让我看到了一丝我原以为早已丧失的希望。这颗种子对于这个饱受战火创伤的世界来说非常重要……我已经感觉到了这一点。', '你身上有堕落的气味，$N……最近一段时间到这里来的许多旅行者都是这样。但是你身上的有所不同。你来这里是有什么事情要告诉我的吗?你身上有一种让我感觉非常熟悉的气息，但是我不知道那是什么。$B$B请你告诉我，你为什么要来找我?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7067, '贱民的指引', '虽然我被当作异教徒流放了，但我的信仰还是一如既往——它将永远激励我前进。为了完成我的使命，我不得不借助外来者的力量……而不是我的半人马同胞们。这真可悲。$B$B这个任务需要深入神圣的玛拉顿——那座坟墓被我的同胞保护着，只有最为虔诚的半人马才能进入。$B$B如果你愿意帮助我，只需点点头就行了。我会给你一块羊皮纸，上面写着具体的指示。阅读那块羊皮纸然后考虑一下我的话。', '阅读贱民的指引，然后从玛拉顿得到联合坠饰，将其交给凄凉之地南部的半人马贱民。', '就是这个，$r!就是这个!现在我就可以开始伟大的部族复兴计画了。谢谢你。$B$B请你拿着这个。希望我们下次见面的时候，一切都与现在不同。', '你考虑得怎么样了，$N?你能帮助我吗?你愿意进入那块圣地并帮我重建一个伟大的半人马部族吗?', '', '去凄凉之地找玛诺洛克集会所的半人马贱民。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7068, '暗影残片', '在半人马的圣地玛拉顿中有着强大的魔法，凄凉之地的半人马用他们的生命来保卫那个地方，但他们无法阻止我们拿走我们想要的东西。$B$B你现在要去一趟玛拉顿，寻找那些由暗影残片组成的石头生物。如果你把那种紫色的水晶交给我，那么尤塞尔奈就会为你付出的时间而奖励你。$B$B那个地方很危险，也许你应该找一些朋友与你一同探险。', '从玛拉顿收集10块暗影残片，然后把它们交给奥格瑞玛的尤塞尔奈。', '啊，这些对我的魔法来说简直是太完美了。给你，你可以拿走这些饰物中的一样，然后就赶快离开吧……我要开始进行研究工作了。', '你找到水晶了吗?强大的仪式，惊人的法术―那些裂影碎片可能对于各种魔法都有极大的帮助。', '', '去找奥格瑞玛的尤塞尔奈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7070, '暗影残片', '我最近开始测试不同的水晶和它们所具有的魔法特性。普罗德摩尔女士让我征集一些旅行者去凄凉之地寻找一处被称作玛拉顿的地方。在那座废弃的庙宇中，巨大的元素生物带有紫色的石头，我把那种石头称为暗影残片。$B$B如果你决定去那里的话，请帮我找些暗影残片回来，我会非常感谢你的。如果你需要的话，我甚至可以用它们制作一件饰物给你。', '从玛拉顿收集10块暗影残片，然后把它们交给尘泥沼泽塞拉摩岛上的大法师特沃什。', '这些真是太完美了，$N。我还征集了一些其它的冒险中从那里帮我收集水晶，所以我有充足的材料做出这些东西……嗯，从中拿一件作为你辛勤工作的奖励吧。感谢你把这些样品交给我来进行研究。', '你去过玛拉顿了吗?我知道那是很危险的，但是如果你成功了，那一切努力都是值得的。', '', '去找塞拉摩岛的大法师特沃什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7081, '奥特兰克山谷的墓地', '奥特兰克山谷中的墓地具有非常重要的战略价值，部落和联盟为争夺这些神圣的土地疯狂地厮杀，双方都付出了惨重的代价。而你，$N，你做好加入战斗的准备了吗？$B$B如果你想要知道一块墓地是由哪一方控制的，只需观察插在墓地上的旗帜就知道了。看到由部落占领的墓地就把它攻打下来！一直杀到墓地中间去，拔出部落的旗帜。这样一来，那片墓地就是我们的了！', '占领一座墓地，然后向丹巴达尔的诺雷格·雷矛中尉复命。', '干得好!墓地对于我们控制奥特兰克山谷具有十分重要的价值。当你占领一座墓地之后，联盟在这里的优势就得到了进一步的巩固。$B$B现在回到战场上去，$N。如果你再看到被部落占领的墓地……你就知道该怎么做了!', '$N，你还没有占领一座墓地。当你完成任务之后再回到我这里来!', '', '去奥特兰克山脉找加文高地的杜尔根·雷矛。', '占领墓地', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7082, '奥特兰克山谷的墓地', '奥特兰克山谷中的战斗总是寸土必争的。在殊死的拼杀中，我们和敌人所控制的区域在不断地变化。而对墓地的争夺则是最激烈的战斗，$N。$B$B为部落占领一座墓地！找到插着联盟战旗的墓地，把他们的旗子拔掉。然后这座墓地就是我们的了！', '占领一座墓地，然后向霜狼村的亚斯拉复命。', '干得好，$N!当我们控制了墓地之后，敌人的鲜血就将染红奥特兰克山谷的雪地!', '为联盟占领一座墓地!', '', '去找奥特兰克山脉的提卡·血牙。', '占领墓地', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7101, '哨塔和碉堡', '哨塔和碉堡是非常重要的战略设施，我们必须完全占领它们！因此，我要求你去进攻被敌人占领的哨塔和碉堡。$B$B想要占领一座哨塔和碉堡，你就必须杀进去，将联盟的旗帜拔掉，这样部落的旗帜就会在那里出现，然后大功告成！$B$B此时你就完成了我下达给你的任务，如果我们能够占据那些设施足够长的时间，并且不被联盟夺回去，那么我们就可以控制那一带了！', '占领敌方的某座哨塔，然后向霜狼村的提卡·血牙复命。', '我听说你成功地完成了任务!这让我很高兴……$B$B我们的部队现在可以全面出击，让那些联盟的家伙尝尝苦头了。让他们知道奥特兰克山谷中没有他们的容身之地!', '你还没有攻陷任何一座哨塔，$N!你是不是在等着别人来夺取属于你的荣耀?', '', '去找奥特兰克山脉的提卡·血牙。', '占领哨塔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7102, '哨塔和碉堡', '哨塔和碉堡是非常重要的战略设施，我们必须完全占领它们！因此，我要求你去进攻被敌人占领的哨塔和碉堡。$B$B想要占领一座哨塔和碉堡，你就必须杀进去，将部落的旗帜拔掉，这样联盟的旗帜就会在那里出现，然后大功告成！$B$B此时你就完成了我下达给你的任务，如果我们能够占据那些设施足够长的时间，并且不被部落夺回去，那么我们就可以控制那一带了！', '摧毁敌方的某座哨塔或者碉堡中的旗帜，然后向丹巴达尔的杜尔根·雷矛复命。', '我接到报告说你成功地拔掉敌人的旌旗。干得好，$N!有了我们的步枪兵助阵，我们就可以抵御部落的反攻，并牢牢握住这块地区的控制权!', '你还没有攻陷任何一座哨塔，$N!你在等什么?', '', '去奥特兰克山脉找加文高地的杜尔根·雷矛。', '摧毁旗帜', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7122, '占领矿洞', '奥特兰克的这座矿洞蕴藏不仅仅是矿藏。部落和联盟都在深铁矿洞和冷齿矿洞中储藏了大量的补给……如果我们能控制它们的话，那就太好不过了！$B$B占领一座矿洞，然后回到我这里来。想要占领一个矿洞的话，你必须进入一个还未被我们控制的矿洞并杀死那里的领袖。这样矿洞就是我们的了，而我们也将派遣部队来保护它！', '占领一座还没有被雷矛部族控制的矿洞，然后向丹巴达尔的雷矛军需官复命。', '你成功了!干得好，$N!$B$B只要我们控制了矿坑，并派遣部队驻扎在那里，我们就可以源源不断地获得物资补给了。', '你还没有占领一座矿坑，$N!$B$B只有控制了矿坑，我们才能方便地采集矿石和获取补给。', '', '去奥特兰克山脉找加文高地的杜尔根·雷矛。', '占领矿洞', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7124, '占领矿洞', '奥特兰克山谷中战事不断升级，对冷齿矿洞和深铁矿洞的争夺也越来越激烈。丰富的矿藏和物资储备吸引了双方的势力，它们的价值实在是太高了！$B$B请帮助我们的部队，$N！为部落占领一座矿洞！你必须进入一个仍未被我们控制的矿洞，然后干掉其中的首领。当你完成这个目标之后，这座矿洞就是我们的了，而且我们会派遣部队驻守其中！', '占领一座矿洞，然后向霜狼村的霜狼军需官报告。', '你控制了一座矿坑!有了我们的军队驻守在那里，矿坑中的矿石或补给品都是我们的囊中之物了。$B$B干得好，$N。你帮了我们的大忙。', '你还没有占领一座矿坑，$N!找到一个还未被我们控制的矿坑，然后击败里面的首领!', '', '去找奥特兰克山脉的提卡·血牙。', '占领矿洞', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7141, '奥特兰克的战斗', '侦查人员报告说，在奥特兰克山谷中隐藏着许多神器，但是霜狼氏族的兽人不会让我们接近它们。我们不能让部落阻止我们对于学术的追求！去干掉他们的统帅，德雷克塔尔。只要他死了，那些兽人就会乱成一团。$B$B德雷克塔尔在奥特兰克山谷南端的霜狼要塞中，把他除掉，然后回到我这里来。', '进入奥特兰克山谷，击败部落将军德雷克塔尔。然后回到勘查员塔雷·石镐那里。', '啊，你找到它们了!干得好，$N!我会让我们的勘察员对地图进行研究，以便决定未来的挖掘点。部落得知他们的将军被干掉的话一定会气急败坏，那时我们就能抽出工夫来进行更多的探索了!', '你拿到地图了吗，$N?那些地图上可能标明了更多神器的位置!', '击败德雷克塔尔。', '去找勘查员塔雷·石镐。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7161, '实验场', '你好，$c。经过如此长时间的等待，我们终于有机会响应战斗的召唤了。旧日的感觉正在慢慢恢复，我们又将热血沸腾！$B$B所有新兵都必须完成氏族的试炼。$B$B在附近的蛮爪豺狼人山洞里面有一面霜狼氏族的旗帜。去那里拿回旗帜，然后把它还给我，我就将授予你霜狼新兵的勋章。', '到主基地东南边的蛮爪洞穴中去找到霜狼军旗，然后把它交给拉格隆德。', '你所感觉到的激情是你的灵魂正在被唤醒的证明─它已经响应了战争的召唤。$B$B现在你是霜狼氏族的一员了，$N。恭喜你。$B$B一直戴着这枚徽记吧。当你在霜狼中的军阶再次提升后就回来找我，我会给你颁发更高级、更强大的徽记。$B$B也许有一天你在霜狼氏族中获得最尊贵的荣誉。当那一天到来的时候，你将获得整个氏族军队的控制权。', '醒醒！醒醒，$N！这不是做梦。你已经进入了战场中央！', '', '去找奥特兰克山脉的拉格隆德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7162, '实验场', '你来得真及时，$c。那些霜狼氏族的蛮子就是不愿意放弃！我们要让他们看看联盟真正的力量，让他们一溃千里。$B$B在你踏入战场之前，你最好先通过雷矛部族的试炼。$B$B在这里东南边的冰翼洞穴深处有一面雷矛部族的旗帜。到那里去，把旗帜带回来，然后把它交给我。这样你就可以得到一枚雷矛部族新兵的勋章。', '到主基地东南边的冰翼洞穴中去找到雷矛军旗，然后把它交给哈格丁中尉。', '拿着这枚徽记，$N。当你在雷矛部族中的军阶再次提升后就回来找我，我会给你颁发更高级、更强大的徽记。$B$B也许有一天你会成为新的英雄，到那个时候，你就可以获得对整个部族军队的控制权了。', '小心那个地区的鹰身人，$C。它们会毫不留情地割破你的喉咙!', '', '去希尔斯布莱德丘陵找达隆山的哈格丁中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7163, '崭露头角', '', '', '让我们的敌人被一一击倒吧!为了雷矛部族的荣誉而战!', '许多人都没有活到摆脱平庸的那一天。你已经证明了自己是一个勇士的楷模，$C。现在是提升你的军阶的时候了。$B$B这是你的新徽记。', '', '去找奥特兰克山脉的拉格隆德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7164, '氏族的尊敬', '', '', '<拉格隆德向你致敬。>$B$B出发吧，$N!继续为霜狼氏族作战。我们一定要赢得这场战争!为了德雷克塔尔!为了大酋长!', '很高兴再看到你，$C。我没有想到你能回来。啊，你还证明了自己是部落勇敢而光荣的勇士。$B$B现在又是嘉奖你的时候了，$N。你赢得了又一个新的军阶，因此你将获得一枚新的徽记。$B$B拿着吧。', '', '去找奥特兰克山脉的拉格隆德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7165, '赢得尊敬', '', '', '<拉格隆德咆哮着。>$B$B他们已经开始传颂你的事迹了，$N。雷矛士兵听到你的名字就会胆战心惊。继续好好干吧!', '如此多的勇士献出了生命，鲜血染红了整个战场。然而，你活下来了……你还坚定地站在这里。你带领我们的部队取得了无数胜利，你做出了杰出的贡献，这为你赢得了更高的声望和军阶。$B$B这就是你的新徽记。', '', '去找奥特兰克山脉的拉格隆德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7166, '传说的英雄', '', '', '我们的部队将听从你的调遣!', '在我的面前站着的是联盟所尊崇的英雄。$B$B<哈格丁中尉向你敬礼。>$B$B很少人能够在雷矛部族赢得这样的称号。我看到敌人向你蜂拥而来，旋即全部倒下。$B$B你踏入战场，就成了我们部队的明灯!$B$B这是你的新徽记。', '', '去找奥特兰克山脉的拉格隆德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7167, '命令之眼', '', '', '倾泻出徽记的力量吧，让敌人听到你的声音，让他们被你震慑。部落的力量不容蔑视!', '德雷克塔尔赞美着你的伟业，卡利姆多到处都在传颂你的事迹。大酋长很高兴―你为我们部落做出的贡献让他感到非常高兴。$B$B你将统御我们的部队。$B$B这就是你的新徽记，指挥官$N。$B$B<拉格隆德向你致敬。>', '', '去找奥特兰克山脉的拉格隆德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7168, '崭露头角', '', '', '让我们的敌人被一一击倒吧!为了雷矛部族的荣誉而战!', '许多人都没有活到摆脱平庸的那一天。你已经证明了自己是一个勇士的楷模，$C。现在是提升你的军阶的时候了。$B$B这是你的新徽记。', '', '去找奥特兰克山脉的哈格丁中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7169, '卫兵的尊敬', '', '', '国王也已经听闻了你的英雄事迹，$C。继续为雷矛部族作战吧!', '整个基地中都在传颂你在征战平原上英勇杀敌的事迹!你对我们的敌人造成了沉重的打击，把他们杀得四散逃窜!为此，你在雷矛部族中的军阶获得了提升。$B$B这就是你的新徽记。', '', '去找奥特兰克山脉的哈格丁中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7170, '赢得尊敬', '', '', '<拉格隆德咆哮着。>$B$B他们已经开始传颂你的事迹了，$N。雷矛士兵听到你的名字就会胆战心惊。继续好好干吧!', '如此多的勇士献出了生命，鲜血染红了整个战场。然而，你活下来了……你还坚定地站在这里。你带领我们的部队取得了无数胜利，你做出了杰出的贡献，这为你赢得了更高的声望和军阶。$B$B这就是你的新徽记。', '', '去找奥特兰克山脉的哈格丁中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7171, '传说的英雄', '', '', '我们的部队将听从你的调遣!', '在我的面前站着的是联盟所尊崇的英雄。$B$B<哈格丁中尉向你敬礼。>$B$B很少人能够在雷矛部族赢得这样的称号。我看到敌人向你蜂拥而来，旋即全部倒下。$B$B你踏入战场，就成了我们部队的明灯!$B$B这是你的新徽记。', '', '去找奥特兰克山脉的哈格丁中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7172, '命令之眼', '', '', '倾泻出徽记的力量吧，让敌人听到你的声音，让他们被你震慑。部落的力量不容蔑视!', '德雷克塔尔赞美着你的伟业，卡利姆多到处都在传颂你的事迹。大酋长很高兴―你为我们部落做出的贡献让他感到非常高兴。$B$B你将统御我们的部队。$B$B这就是你的新徽记，指挥官$N。$B$B<拉格隆德向你致敬。>', '', '去找奥特兰克山脉的哈格丁中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7201, '最后的元素', '只有那些进入深渊的冒险者才能迎接这个挑战，$N。$B$B黑铁矮人已经掌握了制造强大的作战傀儡的方法。$B$B来自间谍的报告显示，那些矮人使用某种独特的能量源为他们所创造的傀儡提供无与伦比的杀戮能力。$B$B如果我们能得到这种元素精华的话，我们的憎恶怪就可以得到极大的加强！把那座城市翻个底朝天也在所不惜，找不到精华你就别回来！我们给予的报酬值得你去冒这个险。', '到黑石深渊去取得10份元素精华。你应该在那些作战傀儡和傀儡制造者身上找找，另外，薇薇安·拉格雷也提到了一些有关元素生物的话题……', '棒极了!我立刻就派信差把它们送到幽暗城去!$B$B这是我承诺会给你的报酬。拿着吧!', '<搓揉着她的双手。>$B$B给我看看!', '', '去荒芜之地找卡加斯的暗法师薇薇安·拉格雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7223, '护甲碎片', '战争在奥特兰克山谷激烈地进行着，从铁炉堡运来的物资不足以让我们为部队提供充足的补给。$B$B如果你能在战场上找到护甲碎片，那么就帮我带一些回来吧！', '给丹巴达尔的莫高特·深炉带去20块护甲碎片。', '这里有不少上好的材料呢，$N。我可以用这些东西来给我们的军队提供新的装备。$B$B如果我可以得到更多补给的话，也许我们的主力部队就就可以开进战场了!', '你带回护甲碎块了吗，$N?', '', '去奥特兰克山谷找丹巴达尔的莫高特·深炉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7224, '敌人的物资', '当你和敌人作战的时候，收集他们护甲的碎片并把它们带给我。我会用这些碎片来制作我们自己军队的护甲的！', '给霜狼村的铁匠雷格萨带去20块护甲碎片。', '这些材料正好可以用。我会将它们溶解然后再把它们重新铸造起来，然后看起来绝对不会看出来是从雷矛那些懦夫那里来的!$B$B谢谢你，$N。让我为你清洁一下你的护甲……', '收集工作进行得怎么样，$N。你有没有可以给我的护甲碎块?', '', '去奥特兰克山谷找霜狼村的铁匠雷格萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7281, '兄弟情深', '真是一个悲剧……我的兄弟居然在战场上和我进行殊死搏杀：他是雷矛部族的指挥官。$B$B在雷矛部族的四个指挥官中，他无疑是最危险的。如果他被干掉的话，那女妖之王就可以把他变成我这个样子，让他纠正自己错误的道路……$B$B你可以在敌方领地的深处找到我的兄弟。杀了他，然后回到我这里来。我相信你有能力完成这个任务，士兵。$B$B还有，不要独自行动。', '深入雷矛部族的领地，杀掉指挥官卡尔·菲利普。任务完成之后向指挥官刘易斯·菲利普复命。', '你的英雄事迹不会被埋没，$N。$B$B我必须抓紧时间来拯救他。我必须马上联系希尔瓦娜斯!', '他一定非常痛苦，因为只有他独自活着，而他的兄弟已经升华到了一个完美的境界。', '', '去找哨塔高地的指挥官刘易斯·菲利普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7282, '兄弟情深', '他一定要摆脱他正在遭受的痛苦，士兵！他根本不知道自己在干什么，他已经成为了女妖之王的傀儡。$B$B现在就出发，穿过战火纷飞的战场，深入霜狼氏族的腹地。找到我的兄弟，杀掉他。这样他的痛苦才能结束。', '深入霜狼氏族的领地，杀掉指挥官刘易斯·菲利普。任务完成之后，回到指挥官卡尔·菲利普处复命。', '你确定已经把他的尸体烧掉了，对吗?', '我下达这个命令的时候心情非常沉重，士兵。', '', '去找奥特兰克山谷的指挥官卡尔·菲利普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7301, '被捕的空军指挥官', '我们的军官被俘虏了，$r。我说的是那些空军指挥官。我们在空中进行了一次激烈的交战，但是他们不幸失败了！更糟糕的是，我们最好的飞行员在反攻霜狼要塞过程中被射落了下来。你必须去找到他们。$B$B搜寻西部哨塔和霜狼要塞，那里是他们最后出现过的地方——彻底搜寻这些地区！', '到霜狼氏族的领地中去搜寻空军指挥官斯里多尔、空军指挥官维波里和空军指挥官艾克曼。任务完成之后向指挥官杜菲复命。', '不可思议!你救出他们了，是不是?是不是???不过至少我们知道他们被关在哪里了。', '有什么要让我知道的事情?', '', '去找奥特兰克山谷的指挥官杜菲。', '找到艾克曼', '找到维波里', '找到斯里多尔', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7302, '被捕的空军指挥官', '我们的空中支持现在处于困境之中，$N。空军指挥官在敌人的领地中被射落，你必须找到他们，然后我们才可以开始营救行动！$B$B古斯最后一次飞行时曾出现在冰翼碉堡上空，杰斯托的双足飞龙应该在雷矛伐木场附近。至于穆维里克……那个笨蛋据说落在了丹巴达尔北部碉堡一带。$B$B这是我这里汇总的所有情报。赶快出发，彻底搜索那些地区！', '找到空军指挥官古斯、空军指挥官杰斯托和空军指挥官穆维里克。任务完成之后向挥官穆法特复命。', '做得好!你找到的资讯对我们的行动来说价值菲浅。', '任务进行得怎么样，士兵?', '', '去奥特兰克山谷找霜狼村的指挥官穆法特。', '找到古斯', '找到杰斯托', '找到穆维里克', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7321, '海龟汤', '谁说我们亡灵不懂烹饪？比如说我的秘密食谱海龟汤吧，很多部落成员千里迢迢慕名而来，只为品尝一碗海龟汤！嘿嘿嘿……$B$B不过我最近一直都没做过这种美食。我曾经从达拉然一直走到洛丹米尔湖去捕猎钳嘴龟，不过眼下实在不是外出冒险的时候。如果你从东边那条河里弄点钳嘴龟身上的海龟肉来给我，我就能很快做出点海龟汤来让你大饱口福。', '给塔伦米尔的克里斯托弗·杰弗寇特带去10块海龟肉。', '我的海龟汤可以让你在寒冷的夜晚也能感到温暖……如果你还能感觉到温暖的话。$B', 'Any luck finding the ingredients?  I\'ll tell you, the alliance maggots are far too numerous in this area now... In my opinion, they have come far too close already...', '', '去希尔斯布莱德丘陵找塔伦米尔的克里斯托弗·杰弗寇特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7341, '公平交易', '', '', '太好了!我是个遵守诺言的牛头人，$C。这些箭是你的了。', '你好，$r。我是考拉克，来自雷霆崖的赏金猎人。我游历了整个世界，见识过很多奇异的事情。$B$B我穿越了整个南海，并偶然找到了这些奇妙的瑟银之箭。啊，我有无数的箭，但是我的子弹都用光了。呸，没有好的装备，一个牛头人怎么可能横行战场。这些箭现在毫无用处!$B$B我们来进行一个交易:你可以用瑟银弹来交换我的瑟银之箭。怎么样?', '', '去找艾萨拉的赏金猎人考拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7342, '胆小鬼才用弓箭！', '', '', '你带来我要的东西了，交易成功!这些箭是你的了。', '你能相信吗?!刚从卡拉诺斯运来的这一批弹药都是劣等货!我们现在手里只有这些弓箭!我要用这500000支瑟银箭来做什么?$B$B我告诉你，孩子。如果你可以给我弄些瑟银弹壳，我就给你瑟银箭作为交换―成交吗?', '', '去找湿地的炮兵舍尔杜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7361, '暗矛的青睐', '<纳亚克咆哮着。>$B$B暗夜精灵的祖先是巨魔，有巨魔才有暗夜精灵。$B$B他们对于我们的攻击是无法忍受的。鹿盔想要把我们全部干掉——那么就让我们干掉所有听从他命令的蠢货！他们决无可能达到他们的目的！$B$B你每杀掉一个暗夜精灵，纳亚克都会代表暗矛部族对你表示感谢。你的事迹将会在整个卡利姆多和东部王国传播开来。现在就出发，为了暗矛部族而战！', '你被指派去杀死奥特兰克山谷中的暗夜精灵玩家。$B$B杀死一个暗夜精灵，然后把暗夜精灵的徽记交给霜狼要塞的纳亚克·海克森。', '啊，虽然这只是数千个头颅中的一个，但是不管怎么样，你干得很出色。', '他们想要灭绝我们?他们自己才应该被灭绝。', '', '去奥特兰克山谷找霜狼村的纳亚克·海克森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7362, '牛头人的盟友', '长者派我到这个战场上来研究其它的种族。我在这里最主要的任务就是对侏儒进行分析，玛加萨对于他们的生存能力很感兴趣。啊，那些侏儒——虽然他们看上去如此可怜而娇小——但他们却能迸发出今人惊讶的韧性。$B$B祝你好运，我一直以来都在找人帮我完成玛加萨的任务。当你收集到侏儒的头发之后就把它交给我，这样你就会被认为是牛头人的盟友。', '你被指派去杀死奥特兰克山谷中的侏儒玩家。$B$B杀死一个侏儒，然后把一束侏儒的头发交给霜狼要塞的拉瓦克·恐怖图腾。', '<拉瓦克把地精的头发放在自己的鼻子前面深深地吸了一口气。>$B$B啊，这一定是地精的头发。干得好，$r，但是还有更多的事情等着你去做。', '我可不管头发是什么地方来的，$r。', '', '去奥特兰克山谷找霜狼村的拉瓦克·恐怖图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7363, '人类的病态', '人类是如此让我感到憎恶。$B$B<指挥官菲利普咬牙切齿地说道。>$B$B虽然我是霜狼氏族的士兵，但我也是希尔瓦娜斯的仆人。$B$B我在幽暗城任职期间曾经帮助幽暗城的黑暗炼金师进行过研究。$B$B我接到一个任务，需要收集人类的骨头碎片，用它们来治疗那些人类所残存的人性。$B$B我被授权将这个任务下派给我的士兵。$B$B找到他们，杀死他们。把他们的骨头交给我。', '你被指派去杀死奥特兰克山谷中的人类玩家。$B$B杀死一个人类，然后把人类的骨头交给指挥官刘易斯·菲利普（他一般出现在前线和霜狼要塞之间）。$B$B治疗人类的药剂唾手可得！', '如果那些人类能够安然接受他们病入膏肓的事实，并接受你的治疗，那么事情就会变得简单很多。但是这样也许就不太有趣了。继续好好干!我们终归是要治愈他们的，方法并不重要。', '对，事实确实如此。我的兄弟是人类。这让我感到惭愧……这是我几乎完美的纪录上的一个污点。', '', '去找哨塔高地的指挥官刘易斯·菲利普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7366, '大主教的仁慈', '大主教Ĥہ慈如同他的智慧一样闻名于世。他居然对这样一类邪恶的生物怀着同情心……$B$B<菲利浦怀疑地摇着头。>$B$B他真是太仁慈了……太仁慈了。$B$B大主教说我们应该对亡灵保持同情心，并让他们能够尽快获得真实而永恒的死亡。为了表现这样的仁慈，我们需要他们黑色的、被疾病折磨的心脏。$B$B把被遗忘者的精华交给我，然后我们会在光明大教堂中把它们隆重地焚烧掉。快点行动，$N！', '你被指派去杀死奥特兰克山谷中的被遗忘者玩家。$B$B杀死一个被遗忘者，然后把一枚被遗忘者的精华交给指挥官卡尔·菲利普（他一般在伐木场和矿井之间徘徊）。', '赞美本尼迪塔斯!又一个失落的灵魂即将被燃烧的光明烈焰所拯救!$B$B继续前进吧!我们要拯救更多的被遗忘者!', '本尼迪塔斯!我无法从他的光辉中找到一丝瑕疵。赞美他!', '', '去找奥特兰克山谷的指挥官卡尔·菲利普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7383, '大地之冠', '然而泰达希尔并不是一切都尽如人意。范达尔·鹿盔对于世界之树的计划正如他自己所希望的那样一步步展开了，但是还有一个小问题，这个问题或许会给泰达希尔带来一些麻烦。$b$b不过我不打算介入此事。你得去一趟最后一口月亮井，就在这里西北面的神谕林地里，就在神谕之树的树干下面，那是我们的第一口也是最强大的一口月亮井。在那里灌一瓶水，然后回来向我报告。', '用月亮井的水装满紫水晶瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。', '在神谕之树面前……你会感觉到自己几乎能把智慧抓在手里。让我继续说下去……$B$B随着泰达希尔的成长，大德鲁伊去祈求巨龙的祝福，因为在古代，那些巨龙的地位远在诺达希尔之上。但是时间之王诺兹多姆拒绝祝福泰达希尔，反而斥责德鲁伊的傲慢。和诺兹多姆一样，阿莱克斯塔萨也拒绝了德鲁伊们的要求，但是没有她的祝福，泰达希尔的成长就会受到不良的影响，后果难以预料……', '神谕之树、大德鲁伊和德鲁伊们一起密切关注着泰达希尔的成长。但是虽然我们有了一个新家，但我们还没有重新得到不朽的生命。', '', '去泰达希尔找多兰纳尔的科瑞萨斯·月怒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7385, '联盟之血', '', '', '我会将这些血液和先前收集到的血液混合，在献祭结束之后，冰雪之王就会让雷矛氏族的那些蠢货尝尝霜狼氏族的厉害!', '你可以为我提供更多敌人的鲜血。我很乐意接受更多，$N。', '', '去找奥特兰克山谷的指挥官瑟鲁加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7386, '水晶簇', '', '', '干得好，$N。我可以使用这些水晶中的力量来增强现有的魔法。当我积累了足够的力量之后，就可以释放这些力量，召唤森林之王来帮助我们。', '你可以避开硝烟弥漫的战场。在激烈的战斗之外，你可以帮我收集霜狼氏族的风暴水晶。$B$B议会正在收集这样的水晶，$N。', '', '去找奥特兰克山谷的大德鲁伊雷弗拉尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7401, '通缉：矮人！', '根据亚斯拉·血矛的命令，在战场上遇到矮人的时候要格杀勿论。$B$B如果你在战场上干掉了矮人，就把他们的脊椎骨挖出来，留下那具血迹斑斑的尸体，警告所有胆敢冒犯霜狼氏族的蠢货。$B$B把脊椎骨交给亚斯拉·血矛，以此来证明你的功勋。', '你被指派去杀死奥特兰克山谷中的矮人玩家。$B$B杀掉一个矮人，然后把矮人的脊椎交给霜狼要塞的亚斯拉·血矛。', '你现在被授权大批屠杀矮人，$C!$B$B<亚斯拉眺望了一会儿远方。>$B$B你永远不会忘记这一次的行动……', '你是来观光的么，$C?', '', '去找奥特兰克山谷的亚斯拉·血矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7429, '逃出生天！', '', '', '你真是太厉害了!谢谢你救了我!$B$B我就知道，我命中注定不会成为巨魔的开胃菜!', '我说的是戈多克镣铐钥匙―好吧，那些胖家伙是这么叫它的。任何巨魔都有可能拿着这把钥匙，不过我不清楚到底谁拿着它。没准那些卫兵是负责看管钥匙的……$B$B啊呀，我到底在想什么?你已经拿到钥匙了，对吧?', '', '去找奥特兰克山脉的诺特·希姆加克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7441, '普希林和埃斯托尔迪', '我只是让自己稍微松懈了一下，就酿成了大错。在我匆匆逃离堕落王子的魔爪时，我被洗劫一空。一个名叫普希林的小鬼拿走了我的法术书，还有艾德雷萨拉斯大厅的钥匙。$B$B我对钥匙已经不再有兴趣了，因为我已经以永生换来了自由，但是我一定要找回我的法术书。$B$B找到普希林，然后找回我的法术书。$B$B到厄运之槌的扭木广场去找普希林吧。', '到厄运之槌去找到小鬼普希林。你可以使用任何手段从小鬼那里得到埃斯托尔迪的咒术之书。$B$B找到咒术之书后，回到拉瑞斯小亭的埃斯托尔迪那里。', '你终于找到它了!那个小鬼真可怜。啊，我这里还有一些很不错的东西，你可以从中选择一件。', '我无怨无悔，陌生的$r。女王很久之前就已经逝去，辛德拉的工作成果已经被那个托塞德林王子的疯狂毁灭了。我要的只是自由……我只有选择逃跑……', '', '去找菲拉斯的埃斯托尔迪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7461, '伊莫塔尔的疯狂', '你难道还没有听够吗？你到底有没有能力解决问题？$B$B这种疯狂必须得到遏制，永生的岁月早已过去了。摧毁水晶塔周围的守卫，削弱能量力场的保护作用，然后干掉伊莫塔尔。此时王子的力量将被大大削弱，趁机解决他，让这座城市中的灵魂得到安息，冒险者。', '你必须干掉5座水晶塔周围的守卫，那5座水晶塔维持着关押伊莫塔尔的监狱。一旦水晶塔的能量被削弱，伊莫塔尔周围的能量力场就会消散。$B$B进入伊莫塔尔的监狱，干掉站在中间的那个恶魔。最后，在图书馆挑战托塞德林王子。$B$B当任务完成之后，到庭院中去找辛德拉古灵。', '我们感谢你，英雄。', '你要小心，冒险者。王子非常善于……花言巧语。', '', '去菲拉斯找厄运之槌的辛德拉古灵', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7463, '久违的法师', '一个$r法师！这太让我感到惊讶了。我已经有将近……现在是什么时候？哦，已经有500年没有看到过你这样的法师了！$B$B我有些东西，你肯定会很感兴趣，但是你必须先帮我完成一个任务。$B$B<莱德罗斯窃笑着。>$B$B在艾德雷萨拉斯发生了奇怪的事情，有个水元素出现在艾德雷萨拉斯的东侧，它的出现简直就是一场灾难！$B$B到扭木广场去，从它身上收集一瓶海多斯博恩的元素精华。把它拿回来交给我，然后我就可以教你一个非常有用的法术。', '到厄运之槌的扭木广场去杀掉水元素海多斯博恩。把海多斯博恩精华交给图书馆的博学者莱德罗斯。', '太好了!你是谁?哦，那不重要。我应该给你什么?嗯……你是个法师，也许你会发现这个有点用处。', '什么?我认识你吗?', '', '去找厄运之槌的博学者莱德罗斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7481, '精灵的传说', '几年前，一个名叫卡里尔·温萨鲁斯的精灵领主独自带着几件上古精灵的神器逃离了他那饱经战乱的家乡。$B$B为了寻找这位失踪的领主，我们离开了奎尔萨拉斯的废墟，穿过燃烧平原以及广阔的海洋，最终来到了菲拉斯。$B$B我们认为他就躲在埃雷萨拉斯（现在被称为厄运之槌）的大厅里。$B$B你必须找到他，冒险者。无论他是死是活，我们必须拿回那些他所带走的东西！', '到厄运之槌去寻找卡里尔·温萨鲁斯。向莫沙彻营地的先知科鲁拉克报告你所找到的信息。', '真是遗憾……真是一场悲剧。你说那些东西不见了?没有任何线索，是不是?', '我的同事，夜精灵的学者卢索恩.纹角正在找人帮助他来完成这项任务。', '寻找卡里尔·温萨鲁斯', '去菲拉斯找莫沙彻营地的先知科鲁拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7482, '精灵的传说', '几年前，一个名叫卡里尔·温萨鲁斯的精灵领主独自带着几件上古精灵的神器逃离了他那饱经战乱的家乡。$B$B为了寻找这位失踪的领主，我们离开了奎尔萨拉斯的废墟，穿过燃烧平原以及广阔的海洋，最终来到了菲拉斯。$B$B我们认为他就躲在埃雷萨拉斯（现在被称为厄运之槌）的大厅里。$B$B你必须找到他，冒险者。无论他是死是活，我们必须拿回那些他所带走的东西！', '到厄运之槌去寻找卡里尔·温萨鲁斯。向羽月要塞的学者卢索恩·纹角报告你所找到的信息。', '真是遗憾……真是一个悲剧。你说那些东西不见了?没有任何线索，是不是?', '我的同事，牛头人的先知科鲁拉克正在找人帮助他来完成这项任务。', '寻找卡里尔·温萨鲁斯', '去菲拉斯找羽月要塞的学者卢索恩·纹角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7483, '急速圣典', '温萨鲁斯在这里的东侧遗失了急速圣典，那本圣典可以给你的装备附加上少许的加速效果。那只是一个微不足道的小魔法，真的……$B$B不管怎么样，如果你感兴趣的话，就去把圣典和一些基本材料给我带来。$B$B嗯……你还需要准备一些英雄之血，一块原始黑钻石，外加一些大块魔光碎片。当然我也有可能说得不完全正确！$B$B<莱德罗斯耸了耸肩膀。>', '将急速圣典、1块原始黑钻石、2份大块魔光碎片和2份英雄之血交给厄运之槌的博学者莱德罗斯，以换取一份急速秘药。', '<莱德罗斯打了个哈欠。>$B$B答应我，这份疾速秘纹，千万别一次用光它。$B$B<莱德罗斯窃笑>', '你有什么事?我还有很多事得做!', '', '去找厄运之槌的博学者莱德罗斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7484, '专注圣典', '这本圣典几乎令一个年轻的学者废寝忘食。但是，几个星期之后他就不再热衷于此了。$B$B你们当中那些对魔法更有洞察力的$r会发现，这些东西是非常有趣的。$B$B专注圣典已经不见了，我相信是那些上层精灵的灵魂拿走了它。$B$B把圣典给我拿来，再准备一些大块魔光碎片和暗影之皮，外加一块原始黑钻石，然后我就可以合成秘药了。', '将专注圣典、1块原始黑钻石、4份大块魔光碎片和2张暗影之皮交给厄运之槌的博学者莱德罗斯，以换取一份专注秘药。', '在使用这种东西的时候不要弄伤了你自己，$C。', '你又来了?这一次你有什么事?', '', '去找厄运之槌的博学者莱德罗斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7485, '防护圣典', '他因为遗失了圣典而像婴孩一样哭泣。告诉你吧，我自己也曾因为一些文字而哭泣——世界上没有比知识和历史化为乌有更大的损失了——但是为了这些几乎无用的咒语而哭泣，这值得吗？太荒谬了！这让我相信王子把他杀掉对他来说反而是一种恩惠。$B$B把圣典交给我，还有一块原始黑钻石和一些大块魔光碎片，外加一份磨损的憎恶缝合线，这样我就可以帮你合成秘药了。$B$B哦，你应该到北侧去找那本圣典。', '将防护圣典、1块原始黑钻石、2份大块魔光碎片和1份磨损的憎恶缝合线交给厄运之槌的博学者莱德罗斯，以换取一份防护秘药。', '嗯……冷静一下。正如我所承诺的那样，这里是给你的秘纹。', '我的耐心让你免受痛苦。', '', '去找厄运之槌的博学者莱德罗斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7487, '熔火之心的传送门', '裂隙在翻滚，它撕裂并吞噬我们周围所有的东西，$c。我所站立的地方旁边的裂隙就是穿过黑石深渊直通火焰之王所在地的传送门。$B$B你感到很惊奇吗？真是遗憾……凡人总是无法领悟那些他们无法看到、触摸到或者感觉到的东西。$B$B我向你保证，这个传送门可以到达熔火之心。$B$B你开始感兴趣了吗？其实这是很简单的。进入熔火之心，获得一块熔火碎片，把它交给我，然后我就会将你的灵魂与传送门进行同步。', '进入黑石深渊，在通往熔火之心的传送门附近找到一块熔火碎片，然后回到黑石山脉的洛索斯·天痕那里。', '步入我右方的裂隙，你就将进入熔火之心。', '现在跳入裂缝之中将会给你带来无穷的灾难……', '', '去燃烧平原找黑石山的洛索斯·天痕。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7488, '蕾瑟塔蒂丝的网', '蕾瑟塔蒂丝是一个邪恶的血精灵法师，她对魔法有着近乎变态的痴迷，而且残忍无比，现在她逃进了厄运之棰中。蕾瑟塔蒂丝制造了一张可以收集魔法能量的网。我担心如果不加以控制的话，她的力量将会足以摧毁整个世界！$B$B去阻止她，$N。找到她并拿回她的网。她应该在厄运之槌的扭木广场中，就在那些萨特附近。把她的网交给我，让我来把它的能量安全地释放出来。', '把蕾瑟塔蒂丝的网交给菲拉斯羽月要塞的拉托尼库斯·月矛。', '你拿到网了!干得好，$N!蕾瑟塔蒂丝和她的同类一样，不顾一切地滥用魔法，对我们的世界造成了巨大的威胁。他们认为自己是魔法的主人，却完全没有意识到自己其实是魔法的奴隶。她的死让我感到遗憾，但是这是必须的。$B$B谢谢你，$N。我会找一块开阔的地方安全地释放掉网中的\r\n能量，并将其摧毁，以防止它再惹出什么乱子来。', '你拿到了网了没有，$N?我们必须驱散它所汇集的魔法能量!', '', '去菲拉斯找羽月要塞的拉托尼库斯·月矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7489, '蕾瑟塔蒂丝的网', '血精灵蕾瑟塔蒂丝已经疯了，她极端饥渴着收集魔法的力量，这使她敢于挑战她的同胞，并创造了一种危险的装置，一张可以收集厄运之棰中的那些被污染的魔法能量的网。现在她正在收集那些能量，并计划将其用于对付她的敌人。$B$B我们必须阻止蕾瑟塔蒂丝。在厄运之槌的扭木广场找到她，击败她，把她的网交给我，这样我们也许可以把它交给那些头脑比较冷静的血精灵进行研究。', '把蕾瑟塔蒂丝的网交给非拉斯莫沙彻营地的塔罗·刺蹄。', '你干得很好，$N。这张网包含了大量厄运之槌中的能量，我认为如果它继续留在像蕾瑟塔蒂丝这样的家伙手里，会对我们造成很大的威胁。我对于她的死感到悲伤，但是谁让她多此一举地制造了这张网呢?$B$B谢谢你，$N。我会把网送到那些比蕾瑟塔蒂丝更有负责感的魔法学员那里，他们将负责保管它。', '你拿到蕾瑟塔蒂丝的网了吗?', '', '去菲拉斯找莫沙彻营地的塔罗·刺蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7490, '部落的胜利', '你完成了一个几乎不可能完成的任务。黑龙公主已经被你斩杀。拿下她的徽记，把它交给你的酋长。', '将奥妮克希亚的徽记交给奥格瑞玛的萨尔。', '这对于部落来说是一次伟大的胜利，$N。你多次让你的酋长感到荣耀，现在是大酋长赐予你荣耀的时候了。', '<萨尔看着奥妮克希亚那颗巨大的头颅，努力克制着自己的情绪，强大的末日之锤已经被他握在手中了。>', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7495, '联盟的胜利', '你完成了一个几乎不可能完成的任务。黑龙公主已经被你斩杀。拿下她的徽记，把它交给暴风城的瓦里安·乌瑞恩国王。', '将奥妮克希亚的徽记交给暴风城的瓦里安·乌瑞恩国王。', '今天，我们要庆祝这光荣的胜利!', '以乌瑟尔的胡须的名义!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7498, '迦罗娜：潜行与诡计研究', '这本典籍印有图书馆的标记。', '将这本典籍交给它的主人。', '干得好，$C。如果你找到更多的书籍，请尽快把它交给我们。$B$B随着时间的推移，我们计画进行一些改变，并增加交还书籍后的奖励。', '你找到了一本书!', '', '', '', '', '', '');
