INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7500, '奥法师的食谱', '这本典籍印有图书馆的标记。', '将这本典籍交给它的主人。', '干得好，$C。如果你找到更多的书籍，请尽快把它交给我们。$B$B随着时间的推移，我们计画进行一些改变，并增加交还书籍后的奖励。', '你找到了一本书!', '', '', '', '', '', '');
