INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7504, '光明不会告诉你的事情', '这本典籍印有图书馆的标记。', '将这本典籍交给它的主人。', '干得好，$C。如果你找到更多的书籍，请尽快把它交给我们。$B$B随着时间的推移，我们计画进行一些改变，并增加交还书籍后的奖励。', '你找到了一本书!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7505, '你与冰霜震击', '这本典籍印有图书馆的标记。', '将这本典籍交给它的主人。', '干得好，$C。如果你找到更多的书籍，请尽快把它交给我们。$B$B随着时间的推移，我们计画进行一些改变，并增加交还书籍后的奖励。', '你找到了一本书!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7506, '翡翠梦境……', '这本典籍印有图书馆的标记。', '将这本典籍交给它的主人。', '干得好，$C。如果你找到更多的书籍，请尽快把它交给我们。$B$B随着时间的推移，我们计画进行一些改变，并增加交还书籍后的奖励。', '你找到了一本书!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7507, '弗洛尔的屠龙技术纲要', '你找到了一些非常重要的东西。这本书和你看到过的其它的书不太一样。$B$B某些人或者某些东西将图书馆的封印揭掉了，这本书中的文字十分混乱，根本无法辨识。', '将《弗洛尔的屠龙技术纲要》还回图书馆。', '你原本可以在黑市上把这本书卖个好价钱，$N。尤其是保护这本书的封印已经被破坏，这使得任何具备必要知识的研究者都可以了解书中包含的屠龙秘密。$B$B也许我们应该给你一份丰厚的奖励……好吧，你必须付出巨大的努力才可以获得这份奖励。$B$B<莱德罗斯对着你咧嘴笑着。>', '啊，我们最伟大的书籍中的一卷。它已经遗失很久很久了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7508, '铸造奎尔塞拉', '如果你想要接手这个任务，那就把这把黯淡的精灵剑交给莱德罗斯吧。', '把黯淡的精灵剑交给博学者莱德罗斯。', '如果你能想办法进入黑龙的巢穴，以她的火焰气息加热这把剑，然后用她的鲜血为它淬火，我就可以为你复原它。', '太好了，让我们开始吧……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7509, '铸造奎尔塞拉', '将未淬火的上古之刃拿到奥妮克希亚的巢穴中，并与她作战。$B$B你需要使用一些技巧来加热这把剑。在战斗中，奥妮克希亚一定会使用火焰的气息来灼烧你。你应该将未淬火的上古之刃放在附近，并期望黑龙的火焰气息会为这把剑加热。如果你可以活着等到那个时候，就捡起加热过的上古之刃，然后杀掉奥妮克希亚。$B$B将加热过的上古之刃插入她的尸体中，这样就可以完成它最后的铸造仪式，并得到一把精制上古之刃。', '你必须设法让奥妮克希亚对这把未淬火的上古之刃喷射火焰。完成之后，捡起加热过的上古之刃。你要注意的是，加热过的上古之刃不会一直保持被加热的状态，时间非常紧迫。$B$B在把它给我拿回来之前的最后一步是杀掉那条龙，并将加热过的上古之刃插入她的尸体中。$B$B完成这些之后，奎尔塞拉就是你的了。', '<莱德罗斯低声吟唱着一些你无法理解的咒语。>$B$B正如我所承诺的，$C，你的精灵之剑，奎尔赛拉。', '也许有一天，会有一位勇士重新挥舞这把棱彩古剑。', '', '去找厄运之槌的博学者莱德罗斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7563, '血之狂暴', '恐惧战马居住在一个名叫克索诺斯的异世界中，它们奔驰在那里的火光冲天的平原上，想要控制这样一头野兽，你就必须吟唱蕴含强大能量的符文。我可以为你在羊皮纸上书写这样的符文，但是首先，我需要一种特殊的墨水。$B$B在遥远的冬泉谷中居住着一种枭兽。它们曾经是纯洁的生物，但是由于受到暗语峡谷中的恶魔力量的影响，它们变得十分疯狂，开始在雪地中游荡。$B$B它们的血正是我制作墨水所必需的材料。', '把30瓶狂暴野兽的血交给燃烧平原的莫苏尔·召血者。', '啊，非常好。我会把这些血液蒸馏制成墨水，然后用它来撰写羊皮纸。也许我还会留下一些给自己，因为据说它们的味道不错……', '你找到那些疯狂的枭兽了吗，$N?那些生物拥有很强大的魔法能量，而它们那饱经折磨的躯体中流淌的血液就是这种能量的载体。', '', '去燃烧平原找风暴祭坛的莫苏尔·召血者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7564, '戈瑟奇·邪眼', '我的仆人戈瑟奇是个不错的炼金师。他可以为我准备撰写羊皮纸所需的墨水。我把你收集的血液包在了一起，把它交给戈瑟奇，然后他就可以进行下一步的工作了。', '把血箱交给燃烧平原风暴祭坛的戈瑟奇·邪眼。', '哦，血。是莫苏尔大人让你去收集的吧?他对这种东西十分着迷，喜欢看着它慢慢地流淌。而我则喜欢留着一只活老鼠之类的小动物，那么在我需要血的时候……它还是热的。$B$B这种血液具有非常强大的力量。莫苏尔一定是在准备另一份召唤恐惧战马的羊皮纸!太让人感到兴奋了!$B$B如果这是真的，那么看来你就是那个准备迎接挑战的术士，那么……除了血液之外，你还需要很多其它的东西，我的朋友。', '你有东西要给我?难道是一只巨大而多汁的蜘蛛?或者是一只蟑螂?我希望它还是活的……我很喜欢嚼活蜘蛛或者蟑螂……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7581, '监牢之链', '你必须从低级恶魔身上找到特定的材料，才能开始制作关押末日守卫的监牢。$B$B厄运之槌中的荒野萨特身上的血液正合适，那些血液凝固之后就可以把赫达琳碎片连接起来，强化水晶监牢。', '到菲拉斯的厄运之槌去，从扭木广场的荒野萨特身上找到15份萨特之血，然后把它们交给腐烂之痕的戴奥。', '啊，太棒了。这些血可以让末日守卫的魔法防御结界彻底失效。', '只有荒野萨特之血才能满足要求。', '', '去诅咒之地腐烂之痕找衰老的戴奥。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7582, '监牢之壁', '那些盘踞在海加尔山脚下的赫达琳恶魔正在秘密地研制强大而邪恶的毒药，这种毒药经过慢火熬制之后会形成一块致密的抗魔水晶——赫达琳之泪。$B$B即使是最强大的末日守卫也无法将一块由赫达琳之泪组成的监牢击碎。$B$B到冬泉谷的暗语峡谷去寻找赫达琳之泪吧。', '到冬泉谷的暗语峡谷去，从盘踞在峡谷中的赫达琳恶魔身上找到5块赫达琳之泪。完成任务之后回到腐烂之痕的戴奥那里。', '我只需将荒野之血和这些水晶融合，就可以完成监牢的制造了。', '赫达琳恶魔绝对不会轻易放弃它们珍贵的宝石，$N。', '', '去诅咒之地腐烂之痕找衰老的戴奥。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7583, '压制', '监牢已经准备就绪，现在是整个任务中最困难的部分。$B$B你必须到诅咒之地的腐烂之痕去，在那里使用这个水晶监牢捕获一个末日守卫指挥官。$B$B你要多加小心！末日守卫指挥官是一种狡猾而又致命的对手，它会在你施展禁锢法术的同时想方设法毁灭你。而且被关进监牢之后，他也会努力挣扎。$B$B它会不顾一切地干掉你，$N。因此，我建议你召集一些强大的同伴来帮助你！', '在腐烂之痕中找到一个末日守卫指挥官。$B$B对其使用光芒水晶监牢。你要做好承受疯狂攻击的准备，那个恶魔会拼命挣扎试图逃脱。$B$B如果你成功了，就把被囚禁的末日守卫交给腐烂之痕的戴奥。', '你完成了我交给你的任务，现在你已经可以学习召唤和控制这头野兽的方法了。', '嗯?干得怎么样了?', '', '去诅咒之地腐烂之痕找衰老的戴奥。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7602, '无瑕的恶魔精华', '如果你要复活克罗苏斯，那就必须用到魔火。我可以制作魔火，不过我需要一些材料。$B$B你必须从三个遥远的地方收集无瑕的恶魔精华，并把它们交给我。$B$B在艾萨拉的雷加斯萨特身上可以找到第一种精华；费伍德森林的加德纳尔军团士兵有第二种精华；而诅咒之地的地狱卫士斥候身上有第三种。$B$B把每种精华都拿一份来给我，然后我会为你制作魔火，这样克罗苏斯就可以重生了。', '费伍德的伊普斯要求你从三个不同的地区收集三块无瑕的恶魔精华，然后把它们交给他。$B$B艾萨拉的雷加斯萨特、费伍德森林的加德纳尔军团士兵和诅咒之地的地狱卫士斥候分别拥有一种无瑕的恶魔精华。', '给我一分钟，我会帮你把这些精华做成魔化火焰。$B', '不要告诉别人，其实尼比是个傻瓜。', '', '去费伍德森林找碎痕谷的伊普斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7603, '克罗苏斯的恶魔之核', '克罗苏斯就躺在在东北边的碎痕谷中。带上魔火，在他的尸体上使用它。魔火将会使那个倒下的地狱火重新站起来。$B$B当然，我相信他可以轻松地把你和你的朋友连窝端了——相信我，你最好带些朋友一起去。$B$B如果奇迹出现，也就是说你和你的朋友碰巧把克罗苏斯摆平了的话，那就把他的恶魔之核交给尼比。', '在费伍德森林的碎痕谷中搜寻克罗苏斯的尸体。当你找到尸体后，在他身上使用魔火，并等待克罗苏斯复生。当这个地狱火被唤醒之后，干掉他，从他的身上拿取克罗苏斯的恶魔之核。$B$B把克罗苏斯的恶魔之核交给费伍德森林的尼比。', '交易是要讲诚信的!快，拿着这个，把这个写下来。我可没有时间!我即将进行我有生以来最伟大的召唤!', '你是\r\n不是迷路了?', '', '去费伍德森林找碎痕谷的万能的尼比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7604, '瑟银兄弟会契约', '签署下面这份契约者担保他们交给瑟银兄弟会（TB Ltd.）的萨弗隆铁锭是真品，绝非伪造。签署这份契约还将使瑟银兄弟会不对因签署者个人试图铸造、寻找、创造、销售或食用萨弗拉斯而造成的一切不良后果负有任何责任。$B$B签署这份契约即表明你同意以上所有条款。$B$B签名：_________________', '如果你愿意接受萨弗隆的设计图，请将瑟银兄弟会契约交给罗克图斯·暗契。', '很高兴和你做生意，$N!$B$B我谨代表瑟银兄弟会祝你在寻找萨弗拉斯的路上一路顺风!', '我们之间有商业往来吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7624, '背叛者乌拉泰克', '你想要得到我的帮助？那么就为我而战吧。$B$B我的奴仆乌拉泰克跪在我面前的时候表现出无比的可怜和谦卑，但其实他只不过是在为克索诺斯位面的赫尔努拉斯工作。赫尔努拉斯想要夺取我在这里的位置和权力，而乌拉泰克就是他的间谍……$B$B如果你想要证明你效忠的是我而不是我的对手，就去找到乌拉泰克，它就在西边的暗影堡里。告诉他我已经知道了他的秘密，然后就看着恐惧吞噬他吧。把那个叛徒的精华给我带回来！', '找到并杀死乌拉泰克，然后把叛徒的精华交给加德纳尔的魔王贝恩霍勒。', '啊，太好了!静置一个星期任由它腐烂之后，这颗心脏将会成为一道多汁的佳肴!也许我还应该让你把乌拉泰克的脑袋也提过来，这样在我品尝这颗心脏的时候，就可以把他的脑袋也放在我的面前欣赏了……$B$B你为我做了很多，$C，现在我对你的耐心稍稍多了那么一点。', '我仿佛已经可以尝到乌拉泰克心脏的味道了。叛徒的血肉真是美味……', '', '去费伍德森林找加德纳尔的魔王贝恩霍勒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7625, '克索诺斯星尘', '你到我这里是要找克索诺斯星尘的？你希望开启一个通往克索诺斯——也就是我的对手赫尔努拉斯所在的世界的传送门？也许你是想要从他那里偷取他宝贵的恐惧战马？$B$B非常好。我的仆人乌尔丹有很多克索诺斯星尘。你可以从他那里得到它……当然，你必须付出足够的代价。', '转至费伍德森林的加德纳尔，从暗影堡的乌尔丹那里购买克索诺斯星尘，把它交给燃烧平原的戈瑟奇·邪眼。', '就是这个!我简直不敢相信你弄到它了!你一定在惊惧领主那里碰到了不少麻烦，也许还付出了很大的代价，或者两者皆是!$B$B莫苏尔马上就可以得到他的墨水，然后开始动手制作雕纹，最终，你将去打开通往克索诺斯的传送门，并找到一匹恐惧战马!', '你去过加德纳尔了吗，$N?你有没有从贝恩霍勒领主那里弄到星尘?', '', '去燃烧平原找风暴祭坛的戈瑟奇·邪眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7626, '达斯莫拉之铃', '达斯莫拉之铃是三件制造强力召唤法阵所必需的物品之一，它的名字来源于着名的术士达斯莫拉·暗眼。当它与黑暗战车之轮和末日蜡烛共同激活之后，它们就会引导出强大的魔法力量。$B$B我的仆人戈瑟奇可以为你铃铛，但是他需要大量的暗影之力药剂。让一个炼金师帮你制作这些药剂，然后把它们交给戈瑟奇。', '把2瓶暗影之力药剂交给燃烧平原的戈瑟奇·邪眼。', '非常好!我希望弄到这些药剂的过程对你来说并不是非常困难。有些时候，炼金师对于他们的产品显得特别吝啬……$B$B我会帮你制作铃铛并保管它，直到你做好进行仪式的准备。', '你拿到那些药剂了吗，$N?莫苏尔说你需要一只达斯莫拉之铃，我需要那些药剂才能制造充满暗影力量的东西!', '', '去燃烧平原找风暴祭坛的戈瑟奇·邪眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7627, '黑暗战车之轮', '黑暗战车之轮可以为强力召唤法阵提供并控制它所需要的能量。如果你需要戈瑟奇制造的黑暗战车之轮，他就需要一些附魔师提供的大块魔光碎片，以及高级矿工可以提供的黑铁矿石。$B$B去弄到那些东西，然后把它们交给我的仆人。', '把6份大块魔光碎片和25块黑铁矿石交给燃烧平原的戈瑟奇·邪眼。', '就是这些!我听说黑铁矿石来自于黑石深渊，相信那些魔光裂片也不是很容易入手的东西。我非常敬佩你们这些术士的执着和坚定。如果你能将这些精力全部投入抓虫的艺术之中，那么你无疑将得到极大的享受!$B$B对不起，我有些离题了。我将负责保管你的黑暗战车之轮，直到你准备开始仪式为止。', '黑暗战车之轮并不容易制造，而且它也需要很多材料。你收集到了我所需的材料了吗?', '', '去燃烧平原找风暴祭坛的戈瑟奇·邪眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7628, '末日蜡烛', '末日蜡烛汇集了火焰的力量，并将其倾斜在那些胆敢打断你的召唤仪式的蠢货身上。当你制造了一个强力召唤法阵并点燃蜡烛之后，任何胆敢闯入结界的恶魔都会被烧成灰烬！$B$B但是想要保存这样的火焰可不容易，你必须有黑龙鳞片中的精华成分。收集这些鳞片，然后把它们交给戈瑟奇·邪眼。', '把3块黑龙鳞片交给燃烧平原的戈瑟奇·邪眼。', '啊，很好。我需要用这些东西来保存蜡烛的火焰。有了这些黑龙鳞片之后，我就可以制作蜡烛，然后代你保管它，直到你准备好进行强力召唤法阵的仪式。', '你把龙鳞带来了吗，$N?在你带来鳞片之前我不会开始制作蜡烛……否则整个营地都会被炸上天的!', '', '去燃烧平原找风暴祭坛的戈瑟奇·邪眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7629, '瓶中的小鬼', '只需一步就能完成莫苏尔的羊皮纸了。我需要一张注入克索诺斯星尘力量的纸，另外……我恐怕我无法在这里完成工作，因为我没有必需的设备！$B$B不过我知道有一座炼金实验室，那里有我所需的一切东西。它就在西瘟疫之地凯尔达隆岛上的通灵学院里。$B$B我自己没法亲自去那里，不过你可以。拿着这只瓶子，这里面有一个非常聪明的小鬼。在实验室里把它放出来，然后它就会帮你搞定羊皮纸。', '把瓶中的小鬼带到通灵学院的炼金实验室中。在小鬼制造出羊皮纸之后，把瓶子还给戈瑟奇·邪眼。', '啊，干得好。耶维尔完成了羊皮纸的制作。你认为通灵学院怎么样?那是个让人着迷的地方，你说呢?还有那里的虫子……我听说它们的味道很不错!$B$B感谢你把我的瓶子带回来，$N。我对它有着很深的感情……我决不会把它卖了的!', '你去过通灵学院了没有，$N?小鬼有没有用星尘制作羊皮纸?', '', '去燃烧平原找风暴祭坛的戈瑟奇·邪眼。', '制造羊皮纸', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7630, '奥金锭', '现在达斯莫拉之铃、黑暗战车之轮和末日蜡烛都已经准备好了，我还得给你准备一块黑色磁石。在仪式进行的过程中，你必须不断用黑色磁石激活那些失效的物品才能维持法阵。$B$B因此，我需要一些奥金锭。你有奥金锭吗？如果没有的话……那么，去找个炼金师问一问吧。$B$B当你拿到奥金锭之后再回来，我会用它制作黑色磁石。', '把1块奥金锭交给燃烧平原的戈瑟奇·邪眼。', '你终于弄到奥金锭了!太好了!现在我可以制作一块黑色磁石，当你开始进行强力召唤法阵之后，你就得用它来保证法阵不会失效!', '你拿到奥金了吗，$N?我需要这种材料来制作黑色磁石。', '', '去燃烧平原找风暴祭坛的戈瑟奇·邪眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7632, '远古石叶', '这片青翠的叶子泛着微微的绿光。叶子的表面很不平整，上面遍布着叶脉和皱褶。$B$B你猜想这片叶子是来源于一个古老而又强大的生命体。$B$B也许你可以找到这片叶子的真正主人？', '找到远古石叶的主人。祝你好运，$N。这个世界是很大的。', '我当然认得自己的叶子，它保存得很好!$B$B真是太谢谢你了，$C。$B$B也许你和我们之间可以创建良好的合作关系。', '<瓦特鲁斯呻吟着。>', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7634, '龙筋箭袋', '你好，$c。我是知识古树哈斯塔特。我这里保管着很久以前就消逝了的知识。$B$B在适当的条件之下，我的一片树叶可以变成一只近万年来都没有出现过的箭袋。这只箭袋配合上古之弓就将发挥无穷的力量。$B$B将一头成年蓝龙的肌腱交给我，这只箭袋就是你的了。', '费伍德森林的古树哈斯塔特要求你带回一块成年蓝龙的肌腱。', '愿我的树叶为你的弓箭提供保护。愿你的每支箭都能射穿敌人的心脏。愿我们这个世界中的一切邪恶都受到惩戒。', '欢迎回来，年轻的$C。', '', '去费伍德森林找铁木森林的古树哈斯塔特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7635, '合适的弓弦', '瓦特鲁斯可以提供给你一根手杖来制作上古之弓，但是只有当我给弓弦附了魔法之后，你才能得到完整的弓。$B$B这是个简单的任务，小东西。杀掉一头成年的黑龙，然后从它的骨头上割下一块肌腱。把它交给我，然后我就可以对弓弦进行附魔，使其变成一根坚固无比的弓弦。', '费伍德森林的古树斯托玛要求你带给他一块成年黑龙的肌腱。', '这是一条邪恶无比的龙，它的肌腱散发着邪恶的味道。$B$B给我一点时间，让我来净化这块肌腱，然后就可以进行附魔工作了。', '我确信找一头黑龙然后干掉它并没有什么难度，$N。不要浪费我的时间。', '', '去费伍德森林找铁木森林的古树斯托玛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7636, '古树的手杖', '燃烧军团的仆从依然在这个世界上活跃着，$c。它们接触过的所有东西变会得堕落，自然界因为它们的存在而枯萎并哭泣着。$B$B你必须找到这些恶魔，然后消灭它们，$N。你要注意，你必须独自挑战它们，否则那些怯懦的恶魔就会逃跑。只要你孤身一人，它们就会想方设法干掉你。你必须击败它们，让它们的傲慢变成痛苦。$B$B这里是我的一块树皮，上面的文字将引领你找到你的目标。去吧，拿回它们的徽记。', '你必须找到并干掉下列4个恶魔：$B$B迷人的西蒙妮。$B$B疯狂的克林弗兰。$B$BS屠杀者索伦诺尔。$B$B摧毁者阿托留斯。$B$B杀掉这些恶魔，然后回到费伍德森林的古树瓦特鲁斯那里去。$B$B根据你背包中的石化树皮来找到它们所在位置的线索。$B$B你必须独自完成这个任务。', '你干得很漂亮，$N!拿着这根手杖，将它和斯托玛制作的弓弦组合起来。这样，它们就将合成一把最强大的武器。', '不要被它们的伪装所迷惑!', '', '去费伍德森林找铁木森林的古树瓦特鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7637, '牺牲精神', '为了做好迎接这个挑战的准备，你必须首先展示自己的牺牲和公正……主要是牺牲。$B$B你必须从高阶牧师洛汉那里取得驱魔香炉，才能进行下一步的任务。不过，虽然你的目标是正义的，但你仍然需要为驱魔香炉提供一定的补偿。$B$B去铁炉堡和高阶牧师谈谈吧。给他足够的金钱来换取驱魔香炉，这将会体现出你的牺牲精神。$B$B现在就去吧，$N，时间紧迫。', '到铁炉堡去找高阶牧师洛汉，从他那里拿到驱魔香炉。你需要捐赠150金币来获得它。', '祝福你，圣骑士。你的捐款比我们所需要的还要多得多。你的牺牲不仅将帮助我们获得我们急需的东西，还可以帮助铁炉堡中最需要帮助的平民。$B$B现在，让我来确认一下这个香炉是否已经准备妥当了……', '你好，高贵的圣骑士!我已经准备好了我最珍贵的香炉，里面放入了最新鲜的熏香并施以祝福三次供你使用。你的捐献不但将帮助我们在铁炉堡制作一个新的香炉，还可以用于购买食物来帮助我们的人们。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7639, '圣骑士的审判', '请拿着这只驱魔香炉，我祝福你一路顺风。我自己曾多次使用它驱除了邪恶，而且我相信它一定会帮助你完成艰巨的任务。$B$B回到暴风城去找格雷森·沙东布瑞克公爵吧，$N。他将告诉你接下来该怎么做。', '把驱魔香炉交给暴风城教堂区的格雷森·沙东布瑞克公爵。', '嗯，很好。你还将继续进行这样的牺牲，我很高兴看到你很乐意这么做。牺牲是圣骑士众多职责中最重要的一部分……但是我想我不需要为此而专门对你进行说教。$B$B现在，$N，你将会开始进行审判。这只香炉将会指引你去我们失落的土地上，审判那些饱受折磨的灵魂。', '欢迎回来，$N。你得到驱魔香炉了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7640, '恐惧谷的灵魂', '我在香炉中放了一撮东瘟疫之地恐惧谷中的腐烂泥土。你可以用它来找到出现灵魂异动的区域。寻找绿色的光芒渗入地表的地方——那里就是物质世界和灵魂世界结合的边缘，在那里用香炉将邪恶的灵魂召唤出来。$B$B当你对那里的灵魂进行了足够的审判之后，就可以继续下一步了。', '使用驱魔香炉召唤恐惧谷中的灵魂。当你杀掉25个恐惧谷的灵魂之后，回到暴风城教堂区的格雷森·沙东布瑞克公爵那里复命。', '干得好，$N。我们必须对那些躲藏在黑暗中的邪恶力量进行审判，这是我们应该极力完成的职责。你已经完成了牺牲和对恐惧谷灵魂的审判。$B$B你的下一步将是对一匹堕落的战骑的灵魂进行牺牲和审判，它现在是死亡骑士达克雷尔的坐骑。', '很高兴再次见到你，$N。你在恐惧谷的工作完成了?', '', '去找暴风城的格雷森·沙东布瑞克公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7642, '收集材料', '你需要为马饰准备四样东西——做内衬用的符文布，做铠甲用的奥金锭，调和灵魂所需的阿尔萨斯之泪，以及灌入灵魂时要用到的斯坦索姆圣水。实际上，你还需要一样东西……就是为我支付酬劳的金币，这其中包括了我的辛苦钱，外加马鞍和马镫的费用。$B$B在你拿齐了所有东西之后，我就可以动手给你打造马饰了。在你收集到那些我要的东西之前，我还有些准备工作要做。', '把40块符文布、6块奥金锭、10棵阿尔萨斯之泪、5瓶斯坦索姆圣水和150枚金币交给暴风城矮人区的格瑞曼德·艾尔默。', '这……嗯，这正是我需要的。你真是个机智的圣骑士，是吗?$B$B好吧，我这就开始为你制作马铠!', '啊，$N。如果没有我说的那些东西，我是无法完成你的马饰的。你拿到所有东西了吗?', '', '去找艾尔文森林的格瑞曼德·艾尔默。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7643, '上古圣马之魂', '你的马饰需要一种特殊的祝福，一个来自特定灵魂的祝福。在厄运之槌有这样一个灵魂，上古圣马之魂。现在它被一个堕落的树人特迪斯·扭木控制着。审判这个堕落的野兽吧，$N。$B$B你要了解这一点——单单给它带来自由是不够的。你必须在接受这个灵魂的祝福之前安抚它。因此，你需要特殊的饲料。到南海镇去，和那里的梅丽德丝·卡尔森谈谈……准备付出更多的牺牲吧。', '你需要特殊的饲料来喂养灵魂马。南海镇的梅丽德丝·卡尔森可以为你提供这样的粮草。$B$B到菲拉斯的厄运之槌去，杀掉特迪斯·扭木，释放上古圣马之魂。用特殊的粮草喂养它，这样可以安抚它的灵魂。最后，把奥金马铠交给它就可以完成祝福。', '上古圣马之魂接受了魔法粮草，它用\r\n鼻子拱着盛放粮草的容器，津津有味地吃着。在吃了几口之后，它看着你手里的马饰，好像在示意你把它放到它的背上去……', '上古圣马之魂期盼地看着你，好像它希望从你这里得到什么。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7644, '被祝福的奥金马铠', '当马饰被放在上古圣马之魂的背上时，它开始微微发光。周围的空气开始凝结，然后马饰就从上古圣马之魂的背上消失，回到了你的背包里。$B$B看来马饰已经受到了祝福。根据沙东布瑞克公爵的指引，你应该带着马饰回暴风城去找他。', '将被祝福的奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。', '你已经做了很多，我的朋友。你的马饰已经准备了。$B$B在完成了救赎任务之后，你就可以用这套马饰来装备你的战骑。然而，在那之前，你还有一项意义重大的任务需要完成。你即将大功告成了!$B$B我们还需要制作最后一样东西，$N。希望你在制作了马饰之后依然有足够的资源继续下去……', '$N，你回来了!你有没有搞定梅丽德丝.卡尔森和特迪斯.扭木?老实说，我现在还不能确定哪一个威胁更大……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7645, '魔法粮草', '当我告诉白银之手骑士团的那帮家伙说我可以制造特殊的饲料来喂养灵魂马的时候，他们以为我疯了。每个人都认为我疯了！好吧，现在是算账的时候了！$B$B我可以制作你需要的东西，圣骑士$g先生:小姐;……所谓的勇士……不过你得为此破费一番。我需要只有银色黎明才会出售的可口的小点心——我要把它混合在饲料中。我还要求——没错，要求——我还要求你拿金币来弥补我所遭受的痛苦！$B$B向我展示你们吹嘘已久的牺牲精神吧，圣骑士。', '把制作魔法粮草所需要的重要材料：20块可口的魔法点心带给希尔斯布莱德丘陵的梅丽德丝·卡尔森。据说银色黎明会出售这种饼干。$B$B你还需要给她50金币来对她进行安抚。', '哼哼，现在看看谁才是……等等……你真的给我钱?你不是那些说我疯了的家伙……但是你依然愿意为你没有犯的错而作出牺牲?$B$B我……我看错你了。如果你还需要更多的粮草，那就再来找我好了。我会免费给你的。谢谢你……高贵的圣骑士。$B$B不过说归说，我还是会收下这些钱……我还没有富到可以肆意挥霍的程度。', '怎么样，我证明你是错的了，是不是?我证明你们都错了!我一直以来都是正确的!!!', '', '去希尔斯布莱德丘陵找南海镇的梅丽德丝·卡尔森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7646, '预言水晶球', '你现在必须制作出一颗预言水晶球，只有用它，你才能开始救赎堕落战马的试炼。你的预言水晶球实际上已经快要完成了。在恐惧谷中用过的驱魔香炉其实是它的催化剂，另外我还会专门为这个装置制作一个外壳。$B$B我最后需要的材料是两块钻石，也就是一块艾泽拉斯钻石和一块原始黑钻石。这两块钻石将被放在预言水晶球中，让它射出足以撕破黑暗的光芒！', '把一块艾泽拉斯钻石和一块原始黑钻石交给暴风城教堂区的格雷森·沙东布瑞克公爵。', '非常完美，$N―现在最后一块东西也准备好了。你即将大功告成了!$B$B在通灵学院的尸骨储藏所中有许多生物的骨骸，其中就有一匹高贵的战骑。这匹战骑的灵魂现在成了死亡骑士达克雷尔的坐骑。你要击败他，并对这匹战骑进行审判。只有你，$N，能够救赎它的灵魂，并将它从痛苦的折磨中拯救出来。', '你已经走到了这一步，$N。你为它所做的一切牺牲都将为你带来伟大的成就。我可以向你保证这一点。', '', '去找暴风城的格雷森·沙东布瑞克公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7647, '审判和救赎', '拿着这个背包——里面有你的任务要用到的所有东西。$B$B在尸骨储藏所地下室的中心使用预言水晶球，将被诅咒的灵魂引领出来，你一定要对它们进行审判。在这次试炼中，你要合理地使用你的审判——它们的作用比你想象中的还要大。在这些灵魂被审判之后，死亡骑士将会出现，此时你就要将其击败，然后获得战马的灵魂。只有这样，你才能对其进行救赎，然后将你的马饰放在你的新坐骑上！$B$B祝你好运！', '在通灵学院尸骨储藏所地下室的中心使用预言水晶球。将你要审判的灵魂引领出来。将这些灵魂击败然后死亡骑士达克雷尔就将被召唤出来。将其击败然后获得堕落战马的灵魂。$B$B把赎罪的战马之魂和被祝福的奥金马铠一起附在达克雷尔的堕落战马身上。', '当你把这匹战骑的被审判的灵魂放回去的时候，它空洞的眼中闪过了一丝生命的光芒。你感到一股神圣的暖流在你的周围涌动，战骑已经得到了救赎。它用鼻子淘气地顶着你的头，似乎已经把自己身上的重负都甩掉了。现在这匹战骑已经完全被你驯服，并将成为你的坐骑。$B$B你已经获得了自己的顶级战骑，恭喜你，圣骑士!', '堕落的战骑之灵用悲哀的眼神凝视着你。它空洞的双眼中充满了绝望。', '', '去找达克雷尔的堕落战马。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7648, '艾尔默的手艺', '<格瑞曼德擦了擦额角的汗，露出非常自豪的笑容。>　$B$B给你，我的朋友。这是我能打造出来的最好的作品——它的质量和我亲手为沙东布瑞克公爵的坐骑制作的马饰不相上下。感谢你对我的手艺的信任。$B$B毫无疑问，葛瑞森也想亲自看看这个作品。把你的马饰交给它，然后替我感谢他交给我这个光荣的任务。', '把奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。', '太完美了。看来格瑞曼德虽然老了，但是他的手艺却越来越好。说起来还真是令我感到不可思议，当年他帮我制作马饰的时候，他的手艺已经是超一流的水准了，而现在他居然还能继续提高!$B$B虽然这套马饰也可以用于普通的坐骑，但是我们当然不会将它浪费在一头普通的畜牲身上。你必须为你的马饰进行祝福，让它真正能配得上圣骑士的战骑。', '你的任务进展得不错，$N。一旦你完成了马饰，就可以进入任务的下一步了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7649, '魔化瑟银板甲：第一卷', '这本典籍印有图书馆的标记。', '将这本典籍交给它的主人。', '干得好，$C。$B$B<博学者莱德罗斯从书中撕出一页。>$B$B我相信你会发现这个配方很有用的。', '你找到了一本书!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7650, '魔化瑟银板甲：第二卷', '这本典籍印有图书馆的标记。', '将这本典籍交给它的主人。', '干得好，$C。$B$B<博学者莱德罗斯从书中撕出一页。>$B$B我相信你会发现这个配方很有用的。', '你找到了一本书!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7651, '魔化瑟银板甲：第三卷', '这本典籍印有图书馆的标记。', '将这本典籍交给它的主人。', '干得好，$C。$B$B<博学者莱德罗斯从书中撕出一页。>$B$B我相信你会发现这个配方很有用的。', '你找到了一本书!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7653, '君王板甲腰带', '', '', '很高兴和你做生意。$B$B另外，$N，你能不能不要把那讨厌的表情挂在脸上?', '你想得到腰带的设计图，就给我拿10块瑟银锭来。', '', '去找塔纳利斯的德罗泰恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7654, '君王板甲战靴', '', '', '很高兴和你做生意。$B$B另外，$N，你能不能不要把那讨厌的表情挂在脸上?', '你想得到靴子的设计图，就给我拿20块瑟银锭来。对，20块。你是不是要哭了?你要不要手帕?$B$B<德罗泰恩大笑着。>', '', '去找塔纳利斯的德罗泰恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7655, '君王板甲护腕', '', '', '很高兴和你做生意。$B$B另外，$N，你能不能不要把那讨厌的表情挂在脸上?', '你想得到护腕的设计图，就给我拿10块瑟银锭来。$B$B你还好吧，$g伙计:小姑娘;?你看起来似乎已经满脸通红了。', '', '去找塔纳利斯的德罗泰恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7656, '君王板甲护胸', '', '', '很高兴和你做生意。$B$B另外，$N，你能不能不要把那讨厌的表情挂在脸上?', '想得到胸甲的设计图，就给我拿30块瑟银锭来。$B$B哦，孩子，又是你。你是否要跑到你的神明那里哭诉，抱怨他们为什么要抛弃你?!?坚强点，孩子!没有人说过生活是公平的。', '', '去找塔纳利斯的德罗泰恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7657, '君王板甲头盔', '', '', '很高兴和你做生意。$B$B另外，$N，你能不能不要把那讨厌的表情挂在脸上?', '只要给我25块瑟银锭，头盔的设计图就是你的了。', '', '去找塔纳利斯的德罗泰恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7658, '君王板甲护腿', '', '', '很高兴和你做生意。$B$B另外，$N，你能不能不要把那讨厌的表情挂在脸上?', '只要给我30块瑟银锭，护腿的设计图就是你的了。$B$B我知道，我快要把你搞得破产了!但是你那些陈腔滥调的悲惨故事我早就听腻了，省省吧。', '', '去找塔纳利斯的德罗泰恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7659, '君王板甲护肩', '', '', '很高兴和你做生意。$B$B另外，$N，你能不能不要把那讨厌的表情挂在脸上?', '你想得到护肩的设计图，就给我拿10块瑟银锭来。', '', '去找塔纳利斯的德罗泰恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7667, '收集材料', '$N，这是一件我希望能得到你帮助的事情，一件重要的事情……请允许我解释一下。$B$B在洛丹伦的通灵学院中有一个被称为尸骨储藏所的房间。我要制造一个能够洞穿那个房间中的邪恶力量的装置，因此我需要两块钻石：一块艾泽拉斯钻石和一块原始黑钻石。我知道这两样东西都不是那么容易得到的，而且我自己没有办法得到。$B$B你能帮我拿来这两样东西吗？', '如果你愿意帮助奥格瑞玛智慧谷的萨格尼，就将一块艾泽拉斯钻石和一块原始黑钻石交给他。', '你真的是非常慷慨，$N。我感谢你的好意。$B$B现在我终于可以完成我的预言水晶球了，而且我还可以进一步地改善它……也许你可以帮我使用它?这是一个非常重要的任务，我向你保证……如果这个任务无法完成的话，那么灵魂世界将会面临令人无法想象的灾难!', '我知道开口要这些材料并不好，但是我的预言水晶球―就是我想要制作的装置―必须用到它们。如果你不能帮助我的话，我也可以理解。', '', '去找奥格瑞玛的萨格尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7701, '悬赏：工头玛托留斯', '工头玛托留斯原本是瑟银兄弟会的盗贼密探，现在却在熔渣之池中担任黑铁矮人的指挥官。根据工头奥菲斯特的命令，杀死工头玛托留斯并将他的徽记带回来即可领取奖赏。$B$B请向侦查队长洛洛尔领取奖励。', '那个叫做工头玛托留斯的黑铁矮人叛徒就藏在大熔炉的熔渣之池深处。$B$B杀死工头玛托留斯，将他的徽记交给灼热峡谷的侦查队长洛洛尔以换取你的奖励。', '我从来都没有见过比这家伙更丑的!$B$B不过只看脑袋似乎没那么丑了……$B$B这是给你的奖励*嗝*，$C。', '你没看见我正忙着吗?你*嗝*想要什么?*嗝*', '', '去灼热峡谷找瑟银哨塔的侦查队长洛洛尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7702, '让他们失眠！', '如果你想要破坏黑铁矮人在熔渣之池的生产活动，就必须抓住其弱点给予致命一击。$B$B众所周知，矮人——特别是黑铁矮人——需要休息！需要充足的休息！$B$B我问你，他们睡觉难道不用枕头吗？对，$N，他们不能没有枕头。你必须小心翼翼地潜入熔渣之池，偷走他们的枕头。', '在大熔炉的熔渣之池深处，你可以发现黑铁矮人的休息区。$B$B到休息区去偷走20只黑铁枕头。当你完成任务后就回到灼热峡谷的艾沃奈斯那里复命。', '棒极了!那些困乏的黑铁矮人会回家去休息，这样就可以大大降低他们熔渣之池中的生产效率。', '别被这古怪的护目镜迷惑了，$N。我是这儿最聪明的。', '', '去灼热峡谷找大熔炉的艾沃奈斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7703, '戈多克食人魔的事务', '现在你是大王，你可以从那个精灵王子手里拿回令戈多克骄傲的神器！你前一任的大王失败了，自从托塞德林那个可恶的精灵从我们古代戈多克大王手中偷走它之后，没有一个大王能想办法把它夺回来！$B$B这个神器叫做戈多克力量护手。传说说只有真正的戈多克大王才能把它拿回来。这个可恶的精灵还在附近——如果你找到它的话，那你就可以使用它！真的！', '找到戈多克力量护手，并将它交给厄运之槌的克罗卡斯。$B$B根据克罗卡斯所说的，“传说”自称是王子的精灵托塞德林从一名戈多克食人魔手中偷走了那件神器。', '喔……你是真正的大王!我这辈子都从来没有看见过它!看来上面的油都要干了……也许那个可恶的精灵把它偷走之后就再也没用过它。好吧，我要对他说哈哈哈哈哈!$B$B看这里―护手上的标志是一个很古老的魔法印记，据说比戈多克巨魔的历史还要久远。好吧，作为戈多克的队长，我们曾经学习过一种知识―如何将印记还原并将力量重新注入护手中!$B$B我会为你这么做的，大王!给你，拿着护手，永远统治我们吧!', '哈哈，你还没有找到它，是不是，老大?也许那只是一个故事……很难相信那个可恶的精灵居然可以从我们戈多克的大王身边偷走东西!', '', '去银松森林找厄运之槌的克罗卡斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7721, '压缩器的动力', '如果我想要在被遗忘的海岸这里开一家可以正常经营的工程学商店，那我就必须先解决这些讨厌的元素生物——它们简直是无法无天！$B$B幸运的是，我发现这些元素生物身上有一种可以给我的超级压缩器提供动力的理想材料——我希望你可以好好地教训它们，拿到我要的东西！把它们身上的水元素核心给我拿来！', '从菲拉斯被遗忘的海岸那里的海元素和巨型海元素身上获取10块水元素核心，把它们交给码头附近的索尔宾·范达瑟。', '太棒了!这些水元素核心可以让我使用好长一段时间了。另外海岸边的元素生物也少了很多，我不必再担心自己选错了开店的地方了!$B$B谢谢你，$N，感谢你为我做的一切。虽然给你奖励会让我囊中羞涩，但是请一定收下这些……收下吧!', '也许你会对那些技术细节感到厌烦，但是我所准备付出的报酬一定会让你动心的。怎么样，你完成任务了没有?', '', '去菲拉斯的被遗忘的海岸找索尔宾·范达瑟。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7722, '绝密配方！', '当那个混账玛托留斯离开我们的部族时，他还带走了比无瑕的奥术水晶更加宝贵的东西——我们制作炽热助熔剂的配方！我相信他一定在利用这个配方从黑铁矮人那里获取利益。$B$B我希望你拿回我们的秘密配方，$N。我确信它们就在玛托留斯身边，而他正躲在熔渣之池的深处。', '在大熔炉的熔渣之池中的某个地方，你可以找到工头玛托留斯偷走的秘密设计图：炽热助熔剂。找到这些设计图，把它们还给灼热峡谷的大铁匠博恩奈特。', '我希望你把那个混蛋的牙齿都给打落了，$N。拉格纳罗斯在上，他罪有应得。$B$B现在我们可以继续进行我们的交易了。', '你找到那些设计图了吗?', '', '去灼热峡谷找瑟银哨塔的大铁匠博恩奈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7723, '该死的手指头！', '真糟糕，由于我近来变得越来越胖，我已经不能像以前那样大吃大喝啦。你瞧瞧这儿的气候，而且气压还很低，我的手指都肿胀起来啦，看上去就像是粗大的塞尔萨玛血肠……$B$B你得帮我做点事情。$B$B让我看看我的日程安排，第一件事情是……杀死峡谷中的重型作战傀儡。把它们全都干掉。', '汉瑟尔·重拳让你杀掉20个重型作战傀儡。$B$B重型作战傀儡就在灼热峡谷的大熔炉附近。当你杀死足够多的傀儡后，就回去找汉瑟尔·重拳。', '你是个优秀的$g小伙子:姑娘;，真的。我会报答你一样礼物。', '你杀死它们了吗?', '', '去灼热峡谷找瑟银哨塔的汉瑟尔·重拳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7724, '熔岩蜘蛛的威胁！', '你不知道吗，每次汉瑟尔想要放松放松，反思他的人生的时候，上面就会给他指派新的工作。$B$B我要思考！你知道我在说什么吗？知道吗？$B$B巨型熔岩蜘蛛在这儿引起了一些麻烦，奥菲斯特说他跟这些畜牲势不两立……嗯，无论如何，这些蜘蛛让孩子们感到不安。$B$B我想我们得杀掉它们，你正是最佳人选。', '汉瑟尔·重拳要你杀死灼热峡谷中的20只巨型熔岩蜘蛛。你可以在灼热峡谷的高地和熔岩池里找到巨型熔岩蜘蛛。$B$B当你杀死足够的巨型熔岩蜘蛛之后，回到汉瑟尔·重拳那里复命。', '<汉瑟尔打了个喷嚏。>$B$B我想我感冒了。这寒冷的气候真该死!', '奥菲斯特说的是真的吗?那些蜘蛛真的是从屁股里吐丝的吗?', '', '去灼热峡谷找瑟银哨塔的汉瑟尔·重拳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7725, '更多被缩小的巨人！', '我知道你为我收集了一些微缩残渣……如果你想要找一份全职工作的话，我想我一直都会需要这种残渣的。$B$B虽然我无法付出足够的报酬，但是我很乐意让我的地精朋友们都了解你这个伟大的$r$c，地精之友！$B$B相信我，$g先生:女士;，地精们的耳朵都是很灵验的……', '使用索尔宾的超级压缩器来缩小菲拉斯的任意种类的巨人，将他们缩小到更容易控制的体积。从缩小过的巨人身上收集10份微缩残渣，把它们交给菲拉斯被遗忘的海岸码头的索尔宾·范达瑟。', '实在是太棒了，$N!你又帮了我的忙，谢谢你。$B$B非常感谢!$B$B也许我给的报酬比不上你从别人那里得到的，但是你在热砂企业哥布尔社群中的声望将大大提升。如果你还有什么事，尽管找我说就好了!', '啊，微缩残渣，甜蜜的结晶!好吧，老实说，我不会在进行研究的时候尝它的味道。$B$B基本不会……', '', '去菲拉斯的被遗忘的海岸找索尔宾·范达瑟。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7726, '补充动力', '你需要更多的工作，是吗？难道我让你去收集元素生物体内的粘液的宏伟任务还无法满足你的冒险欲望？也许我要找到无数类似的事情让你做才行……$B$B好吧，不说废话了，我需要更多的水元素核心。我正想尽办法在这里开店，所以我给你的奖励并不会很丰厚……但是我向你保证，我会把你的热心和勇敢告诉所有人。你要相信我——我在热砂集团里认识很多人！', '从菲拉斯被遗忘的海岸那里的海元素和巨型海元素身上获取6块水元素核心，把它们交给码头附近的索尔宾·范达瑟。', '太棒了，$N，太棒了!我给你的报酬也许算不得太多，但是你的壮举将在热砂企业中广为传颂!$B$B如果你想要找些别的事情来做，请尽管告诉我。我还需要更多的水元素核心。', '你有没有找到我要的水元素核心?', '', '去菲拉斯的被遗忘的海岸找索尔宾·范达瑟。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7727, '熏火龙', '拇趾囊肿，$g小伙子:姑娘;。我的拇趾了出现囊肿。难道在这种混乱的情况下我只能砍下自己的脚来解除痛苦吗？这就是我请求你帮助我的原因。$B$B斯克兰格和博恩奈特让我杀掉这些家伙，这样他们就能派出探险队进入熔渣之池进行探索了，我说的就是那种叫做熏火龙还是什么玩艺的麻烦家伙。现在去杀了它们吧，在消灭熏火龙之前别回来找我。', '汉瑟尔·重拳让你去杀掉20个熏火龙。$B$B熏火龙侵占了熔渣之池中的那些岩浆池。熔渣之池就在灼热峡谷的大熔炉中。$B$B当你杀死足够数量的熏火龙后，就回去找汉瑟尔·重拳。', '哦，我的脚趾痛死啦。$B$B我说，既然你没有丝瓜……', '<汉瑟尔正忙着揉搓他肿胀的指头。>$B$B别站在那儿，去抢一些油和一根丝瓜，用这些东西来消解我的疼痛。$B$B你没有丝瓜吗?嗯好!或许你该出去找些丝瓜了?$B$B嘿，你去哪儿?', '', '去灼热峡谷找瑟银哨塔的汉瑟尔·重拳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7728, '被盗：鼓风机和望远镜', '下列物品已被盗走：$B$B*一台黑铁鼓风机。$B$B一支侦查员的望远镜。$B$B找到并归还这些被盗物品者将获得奖励。$B$B瑟银兄弟会相信，这些物品是被那些居住在灼热峡谷中的该死的黑铁矮人偷走的。$B$B那支望远镜是侦查员的有力工具，而鼓风机则是宝贵的冶铁设备。$B$B如果你找到丢失的物品，请将它们交给斯克兰格。', '找到冶炼鼓风机和侦查员的望远镜，把它们还给灼热峡谷的监工斯克兰格。$B$B你所知道的关于这些物品的惟一信息是：它们肯定是被黑铁矮人偷走的。冶炼鼓风机是铁匠用的锻造工具，侦查员的望远镜是侦查员所需的侦查工具。', '棒极了!这是你应得的奖励。', '如果你是来领取奖励的，那么你必须把被盗的物品交给我。', '', '去灼热峡谷找瑟银哨塔的监工斯克兰格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7729, '工作机会：肃清竞争对手', '监工斯克兰格正在寻找一些优秀的冒险者深入灼热峡谷。$B$B如果你对此感兴趣的话，就到灼热峡谷去，杀死你见到的所有黑铁工头和黑铁奴隶贩子。$B$B当你全身都沾满那些家伙的鲜血之后，就回到监工斯克兰格那儿去。$B$B你自己应该知道什么叫“全身沾满他们的鲜血”，所以别问来问去的。', '杀死15个黑铁工头和15个黑铁奴隶贩子。完成任务之后就回去找监工斯克兰格。', '15.9磅!这一定是沾在衣服上的血液重量的最新记录!恭喜你，$C!', '我们得比较你穿上衣服时和脱下衣服后的体重。', '', '去灼热峡谷找瑟银哨塔的监工斯克兰格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7730, '祖卡什的入侵', '根据有限的侦查，我们得出结论，豺狼人南面的敌人是一个类似昆虫的物种。坦率地说，它们是否具有智慧现在已经不重要了。如果是它们将豺狼人逼得疯狂进犯我们的领地，那么这些虫子就是比豺狼人还要巨大的威胁。$B$B杀入那些祖卡什虫类的巢穴，那个地方被称作痛苦深渊。削减它们的数量，然后把你发现的情报给我带回来，另外别忘了拿回它们的甲壳作为你的努力的证明。', '把20块祖卡什虫壳交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。', '干得好，$C。虽然祖卡什虫类现在还没有对我们发动全面的进攻，但你至少为我们赢得时间来策划妥当的应对方法。$B$B我一定会好好分析这些虫壳的，我们必须全方位地了解它们，然后再想办法解决这个比我们预想中的还要大得多的麻烦。', '你的狩猎进行得怎么样了，$N?你是不是要向我报告你成功的消息?', '', '去菲拉斯找莫沙彻营地的哈杜肯·迅蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7731, '毒刺鞭笞者', '在调查痛苦深渊的时候，我们的斥候发现了一只巨型昆虫——它的体积比我们见过的所有昆虫都要巨大，眼下它就在那里游荡。它不仅体积很大，而且它身上似乎还有其它昆虫所不具备的某种气息。我们给它取了一个名字——毒刺鞭笞者。$B$B它的内脏可以帮助我们研究出对付这个新威胁的方法，把它的分泌腺割下来，然后立刻回来！', '击败痛苦深渊中的毒刺鞭笞者，把它的腺体交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。', '太好了，$C……你干得太出色了!如果毒刺鞭笞者确实是那些虫子里面最强的一个，那么对于它的研究将会对现在的局势非常有帮助。现在我的责任就是在确保我们安全的同时想出利用它的办法。$B$B请收下这些钱币作为整个营地对你的感谢，$N。干得好。', '你有没有把毒刺鞭笞者干掉?', '', '去菲拉斯找莫沙彻营地的哈杜肯·迅蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7732, '祖卡什报告', '在解决祖卡什虫类的威胁这个问题上，你表现得非常出色。但是这个威胁远未得到彻底的解决，我希望能再次请求你为了部落的利益而战。$B$B这份文件中记录了所有与祖卡什虫类有关的信息。我希望把它交给奥格瑞玛暗巷区的基尔兹宾·鼓眼。他是个异型生物专家，希望他能从我们的发现中找到一些有价值的信息。', '把莫沙彻营地祖卡什报告交给奥格瑞玛暗巷区的基尔兹宾·鼓眼。', '啊，我正等着这个呢。这些你面对的生物……它们是部落一直以来都忽略的威胁。哈杜肯把这份文件―还有你―送到我这里来，这是个很明智的决定。$B$B祖卡什虫类是属于异种虫类的一支，有些人认为它们是没有智慧的虫子，但是我可以向你保证―它们对我们而言，远远比联盟更有威胁。$B$B如果你愿意的话，我可以协助你开始铲除这个威胁的行动。', '你好，朋友……看来你到这里来是有急事在身。我有什么可以帮你的?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7733, '更高的品质', '我找到了一个更好的雪人毛皮来源，这真令人难以置信！在菲拉斯北部的怒痕堡中有另外一批雪人，它们比你遇到过的雪人可要难对付多了，如果你想要尝试更大的挑战，就去那里吧！$B$B如果你可以给我弄来一些它们的毛皮，我会给你丰厚的奖励！', '把10块怒痕雪人的毛皮交给菲拉斯羽月要塞的普拉特·马克格鲁比。', '太好了，太好了!这些绝对能派上大用场―只要经过适当的工艺处理，它们就会变得更加厚实。$B$B再次感谢你的帮助，$N。拿着这个―这是我的最新产品。', '如果怒痕雪人的毛皮的品质可以和那些深痕谷中的雪人相媲美，那么它们一定像瑟银一样具有韧性!$B$B想象一下吧!', '', '去菲拉斯找羽月要塞的普拉特·马克格鲁比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7734, '更高的品质', '我找到了一个更好的雪人毛皮来源，这真令人难以置信！在菲拉斯北部的怒痕堡中有另外一批雪人，它们比你遇到过的雪人可要难对付多了，如果你想要尝试更大的挑战，就去那里吧！$B$B如果你可以给我弄来一些它们的毛皮，我会给你丰厚的奖励！', '把10块怒痕雪人的毛皮交给菲拉斯莫沙彻营地的杉多尔·迅蹄。', '太好了，太好了!这些绝对能派上大用场―只要经过适当的工艺处理，它们就会变得更加厚实。$B$B再次感谢你的帮助，$N。拿着这个―这是我的最新产品。', '如果怒痕雪人的毛皮的品质可以和那些深痕谷中的雪人相媲美，那么它们一定像瑟银一样具有韧性!$B$B想象一下吧!', '', '去菲拉斯找莫沙彻营地的杉多尔·迅蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7735, '原始雪人毛皮', '你找到了一块原始雪人毛皮。它非常厚实——比那些怒痕雪人的毛皮要厚实许多。$B$B羽月要塞的普拉特·马克格鲁比是专门做雪人毛皮生意的，这些毛皮一定可以引起他的兴趣。', '把原始雪人毛皮交给菲拉斯羽月要塞的普拉特·马克格鲁比。', '太不可思议了!你也许找到了所有雪人的爷爷的毛皮!$B$B我肯定为此付钱的。一般来说，我不会为了一张毛皮付出那么多的钱，但是我可以用这张皮来做一些特别的东西。感谢你把这个给我拿来，$N!', '嗯……$N?你有什么特别的东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7736, '炽热助熔剂的补给：皇血草', '', '', '炽热助熔剂的数量总是不够。继续收集吧……除非我叫你停止。', '我没时间跟你扯东扯西的，$r。现在是补充我们日益减少的炽热助熔剂储备的时候了。$B$B我需要的物品有:$B$B*熏火龙的鳞片。$B$B*皇血草。$B$B*煤块。$B$B凡是你能给我的，我都要!$B$B如果你想要跟兄弟会搞好关系的话，就最好快点去找。', '', '去找灼热峡谷的大铁匠博恩奈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7737, '获得更多信任', '', '', '继续拿残油来!', '你已经达到了可以和兄弟会进行合作的层次了，$r。我们开始对你另眼相看。干得很不错!$B$B如果你希望能赢得我们更多的尊敬，那就听好了。$B$B我们可以通过在炽热助熔剂中添加黑铁残油的方式来进一步提炼它，到黑石深渊去收集黑铁残油吧。$B$B把你找到的所有黑铁残油都交给我!', '', '去找灼热峡谷的大铁匠博恩奈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7738, '完美的雪人毛皮', '你找到了一块非常完美的雪人毛皮，它非常厚实——比那些怒痕雪人的毛皮要厚实许多。$B$B莫沙彻营地的杉多尔·迅蹄专门做雪人毛皮的生意，这些毛皮一定可以引起他的兴趣。', '把完美的雪人毛皮交给菲拉斯莫沙彻营地的杉多尔·迅蹄。', '这个发现使在是太不可思议了!我相信这是我见过的最完美的雪人毛皮!$B$B我肯定为此付钱的。一般来说，我不会为了一张毛皮付出那么多的钱，但是我可以用这张皮来做一些特别的东西。感谢你把这个给我拿来，$N!', '嗯……$N?你有什么特别的东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7781, '黑石之王', '以前的感觉又回来了，胜利的喜悦和伤痛的折磨流遍你的身体。在你面前的是奈法利安那枚巨大而布满创痕的徽记。勇士，将这颗徽记交给你暴风城的瓦里安·乌瑞恩国王吧。', '将奈法利安的徽记交给暴风城的瓦里安·乌瑞恩国王。', '你所做的事情的意义简直无法用言语表达，$N。历史将会铭记这一天。对联盟来说，已经很多年都没有取得这样辉煌的胜利了!', '难以置信!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7783, '黑石之王', '以前的感觉又回来了，胜利的喜悦和伤痛的折磨流遍你的身体。在你面前的是奈法利安那枚巨大而布满创痕的徽记。勇士，将这颗徽记交给你的酋长吧。', '将奈法利安的徽记交给奥格瑞玛的萨尔。', '你再次将荣耀带给了部落，$N.死亡之翼的儿子已经不复存在了。当然，邪恶者兴风作浪。', ' $N，真希望我能亲眼看到那头野兽被你杀掉之前那张痛苦的脸。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7785, '复生之瓶', '去查看一下他的复生之瓶，凡人。逐风者会在那儿重生！', '查看复生之瓶，然后回到德米提恩那里去。', '愿你在征途中受到护佑，愿主人为你的努力而祝福你。', '你会帮助他从那永恒的牢狱中解脱出来吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7786, '逐风者桑德兰', '我已经把我所知道的东西都告诉你了，$N。你必须找到源质，你必须毁灭拉格纳罗斯的躯体。$B$B快点出发吧，完成我的命令，你就将获得桑德兰的祝福。', '如果你想要把逐风者桑德兰从监牢里释放出来，你就必须找到左右两块逐风者禁锢之颅，10块源质锭，以及火焰之王的精华，把它们交给德米提恩。', '即使在梦中，我也没有想到会有这么一天。$B$B看吧，凡人!$B$B见证比这个世界还要古老的力量!$B$B见证这个曾经面对过泰坦和神灵的王者!$B$B复苏吧，我的主人!摆脱你的枷锁和束缚!复苏吧!', '即使要毁灭整个世界都在所不惜!', '', '去找希利苏斯的德米提恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7787, '觉醒吧，雷霆之怒！', '你已经击败了逐风者，那么，拿上风吻之刃，让那个叛徒德米提恩用你提供的材料唤醒雷霆之怒吧。', '把风吻之刃交给德米提恩。', '请你不要伤害我!拿着这把剑!拿着它!给德米提恩一个改过的机会!', '<德米提恩看到你的时候蜷缩成了一团。>', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7789, '镇压银翼部队', '灰谷森林将在强大的部落面前屈服，$r。无论暗夜精灵们说什么做什么，都无法阻止我们的推进。卡利姆多属于部落，谁敢阻止我们拿取属于我们的东西，谁就要死！$B$B让你的心中充满荣耀之光，让那些胆敢阻止我们的敌人一个个倒下。摧毁银翼要塞中的哨兵部队，并拿到一枚战歌荣誉奖章。把这样一枚奖章给我拿来，你就可以获得奖赏。', '进入战歌峡谷击败联盟小队，获得一枚战歌荣誉奖章，然后向莫尔杉营地的沙塔尔·碎颅复命。', '<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要让多少联盟的渣滓牺牲在部落的面前才能让他们退却?只有时间可以说明一切，$C……', '敌人的鲜血就是我们的荣耀的象征，你做得很出色。', '', '去贫瘠之地找莫尔杉营地的沙塔尔·碎颅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7791, '捐献毛料', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '我们现在接受毛料的捐赠。只要捐赠60块毛料，暴风城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。', '', '去找艾尔文森林的克拉维斯·纳文哈姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7792, '捐献毛料', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '我们现在接受毛料的捐赠。只要捐赠60块毛料，暴风城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。', '', '去找秘蓝岛的度戈鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7793, '捐献丝绸', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在这个社区中的地位无疑将大大提升!那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。', '', '去找艾尔文森林的克拉维斯·纳文哈姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7794, '捐献魔纹布', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '我们的魔纹布储量很低，而你可以帮助我们补充库存!如果计算整个社区所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被铁炉堡的矮人广为传颂，这一点我可以向你保证!$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。', '', '去找艾尔文森林的克拉维斯·纳文哈姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7795, '捐献符文布', '', '', '太棒了―我向你保证，这些一定能派上用场。再次感谢你的帮助!如果没有你的话，我们肯定会一筹莫展的。$B$B鉴于你一贯的慷慨，我会欣然接受你随时捐赠更多的符文布。请及时与我联系，我个人可以确保你所做的好事一定会被广为传颂!', '$N，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$B$B如果你愿意的话，请把你多馀的符文布捐献给我。我们现在接受一次60块符文布捐赠。', '', '去找艾尔文森林的克拉维斯·纳文哈姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7796, '更多的符文布', '', '', '$N―如果没有像你这样的英雄为暴风城亲力亲为的话，我们肯定会碰到很多麻烦。感谢你为我们付出的努力!', '你好，$N!我们的符文布一直比较紧缺，如果你可以省出一些符文布来给我们的话，我们总是表示欢迎的。要是你可以再给我们20块符文布，那么我可以保证，你一定会因为对于暴风城的贡献而被大家认同。$B$B随时欢迎你捐献符文布。', '', '去找艾尔文森林的克拉维斯·纳文哈姆。', '', '', '', '');
