INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7811, '捐献符文布', '', '', '太棒了―我向你保证，这些一定能派上用场。再次感谢你的帮助!如果没有你的话，我们肯定会一筹莫展的。$B$B鉴于你一贯的慷慨，我会欣然接受你随时捐赠更多的符文布。请及时与我联系，我个人可以确保你所做的好事一定会被广为传颂!', '$N，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$B$B如果你愿意的话，请把你多馀的符文布捐献给我。我们现在接受一次60块符文布捐赠。', '', '去找湿地的巴巴罗·阿克巴斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7812, '更多的符文布', '', '', '$N―如果没有像你这样的英雄为暴风城亲力亲为的话，我们肯定会碰到很多麻烦。感谢你为我们付出的努力!', '你好，$N!我们的符文布一直比较紧缺，如果你可以省出一些符文布来给我们的话，我们总是表示欢迎的。要是你可以再给我们20块符文布，那么我可以保证，你一定会因为对于暴风城的贡献而被大家认同。$B$B随时欢迎你捐献符文布。', '', '去找湿地的巴巴罗·阿克巴斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7813, '捐献毛料', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '我们现在接受毛料的捐赠。只要捐赠60块毛料，暴风城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。', '', '去找西瘟疫之地的莱斯顿·法斯雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7814, '捐献丝绸', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在这个社区中的地位无疑将大大提升!那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。', '', '去找西瘟疫之地的莱斯顿·法斯雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7815, '钳嘴龟！', '不要让它们的大眼睛迷惑了你，伙计！那些海水钳嘴龟真是个麻烦。我钓鱼都不能安宁五分钟，那些巨型鱼罐头就会把我的鱼饵给偷吃掉。$B$B帮恶齿巨魔一个忙吧，干掉它们，伙计。$B$B把它们都干掉！', '辛特兰恶齿村的钓鱼者卡图姆要你去杀掉10只海水钳嘴龟。完成任务之后回到他那里去复命。', '哦，伙计!我对你感激不尽!希望你喜欢这柄钓鱼竿。', '狩猎进行得怎么样?', '', '去辛特兰找恶齿村的钓鱼者卡图姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7816, '加莫里塔！', '嘿，我说，这里的海边有一只特殊的乌龟，她叫加莫里塔，是那帮卑鄙的海水钳嘴龟的头儿。$B$B伙计，她偷了我最好的鱼饵，就在我眼皮底下！而且自从那次以后，鱼儿就再也不咬我的钩了。$B$B找到加莫里塔，把我的鱼饵从她的胃里挖出来！', '辛特兰恶齿村的钓鱼者卡图姆要你去杀掉加莫里塔，并从它的尸体上找到卡图姆的超级鱼饵。$B$B卡图姆说加莫里塔和其它海龟都在海岸附近活动。', '伙计!这太棒了!我现在有了最好的鱼饵，而且海水钳嘴龟的数量也下降了不少，我的钓鱼生意一定会好很多的。', '你拿到它了吗?', '', '去辛特兰找恶齿村的钓鱼者卡图姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7817, '捐献魔纹布', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '我们的魔纹布储量很低，而你可以帮助我们补充库存!如果计算整个社区所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被铁炉堡的矮人广为传颂，这一点我可以向你保证!$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。', '', '去找西瘟疫之地的莱斯顿·法斯雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7818, '捐献符文布', '', '', '太棒了―我向你保证，这些一定能派上用场。再次感谢你的帮助!如果没有你的话，我们肯定会一筹莫展的。$B$B鉴于你一贯的慷慨，我会欣然接受你随时捐赠更多的符文布。请及时与我联系，我个人可以确保你所做的好事一定会被广为传颂!', '$N，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$B$B如果你愿意的话，请把你多馀的符文布捐献给我。我们现在接受一次60块符文布捐赠。', '', '去找西瘟疫之地的莱斯顿·法斯雷。', '', '', '', '');
