INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7824, '捐献符文布', '', '', '太棒了―我向你保证，这些一定能派上用场。再次感谢你的帮助!如果没有你的话，我们肯定会一筹莫展的。$B$B鉴于你一贯的慷慨，我会欣然接受你随时捐赠更多的符文布。请及时与我联系，我个人可以确保你所做的好事一定会被广为传颂!', '$N，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$B$B如果你愿意的话，请把你多馀的符文布捐献给我。我们现在接受一次60块符文布捐赠。', '', '去找杜隆塔尔的莱什纳·刺藤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7825, '更多的符文布', '', '', '$N―如果没有像你这样的英雄为暴风城亲力亲为的话，我们肯定会碰到很多麻烦。感谢你为我们付出的努力!', '你好，$N!我们的符文布一直比较紧缺，如果你可以省出一些符文布来给我们的话，我们总是表示欢迎的。要是你可以再给我们20块符文布，那么我可以保证，你一定会因为对于暴风城的贡献而被大家认同。$B$B随时欢迎你捐献符文布。', '', '去找凄凉之地的拉姆斯塔格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7826, '捐献毛料', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '我们现在接受毛料的捐赠。只要捐赠60块毛料，暴风城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。', '', '去找奥格瑞玛的莱什纳·刺藤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7827, '捐献丝绸', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在这个社区中的地位无疑将大大提升!那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。', '', '去找奥格瑞玛的莱什纳·刺藤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7828, '银鬃捕猎者', '许多勇敢的巨魔都在辛特兰的森林中失踪了，$r。银鬃狼对我们的猎人来说是最大的威胁。它们静静地隐藏在灌木丛中，当时机成熟之后就发起突然袭击。$B$B我们一定要阻止这种残忍的行为！$B$B你必须和银鬃狼一样思考。我们要以牙还牙，猎捕它们！把它们全都干掉！', '辛特兰恶齿村的猎户马克霍尔要求你去杀掉5头银鬃捕猎者和5头银鬃嗥狼。完成任务之后就回到他那里复命。$B$B马克霍尔说过那些狼都躲在辛特兰的野外。', '干得好，$C。恶齿巨魔感谢你的贡献。', '让它们尝尝恶齿巨魔的厉害!', '', '去辛特兰找恶齿村的猎户马克霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7829, '野蛮的枭兽', '辛特兰地区最令人讨厌的生物之一就是那些野蛮的枭兽。很多勇敢的恶齿战士都倒在了那些野兽的利爪和尖嘴之下。$B$B干掉你看到的每个野蛮的枭兽，$r。当你把它们杀得血流成河的时候就回到我这里来，你的贡献一定会得到我们的赞赏。', '辛特兰恶齿村的猎户马克霍尔要求你去杀掉10头野蛮的枭兽。完成任务之后就回到他那里复命。$B$B马克霍尔说过那些野蛮的枭兽都躲在辛特兰的野外。', '你已经证明了自己对恶齿巨魔来说是个不可多得的盟友，$N。做得好。', '清除你心中的杂念，$r。成为大自然的一部分!', '', '去辛特兰找恶齿村的猎户马克霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7830, '死者的复仇', '现在蛮锤部族训练的狮鹫正在肆意屠杀巨魔。这真是太可怕了，但是我知道不久之后正义就将得到伸张。$B$B现在我需要派你去清除那些成年的狮鹫首领，也就是那种翱翔的狮鹫。$B$B干掉它们中的一个，然后把它的羽毛交给我。', '辛特兰恶齿村的猎户马克霍尔要求你杀掉一头翱翔的锋喙狮鹫，并将它的狮鹫长羽拿回去交给他。$B$B马克霍尔说过那些翱翔的锋喙狮鹫就躲在辛特兰的野外。', '<马克霍尔看了一下羽毛。>$B$B我真想知道这头野兽在被正法之前曾吞噬了我们多少优秀的猎人。', '翱翔的锋喙狮鹫兽是狮鹫兽中的稀有品种，它的职责是繁衍后代。', '', '去辛特兰找恶齿村的猎户马克霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7831, '捐献魔纹布', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '我们的魔纹布储量很低，而你可以帮助我们补充库存!如果计算整个社区所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被铁炉堡的矮人广为传颂，这一点我可以向你保证!$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。', '', '去找奥格瑞玛的莱什纳·刺藤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7832, '更多的符文布', '', '', '$N―如果没有像你这样的英雄为暴风城亲力亲为的话，我们肯定会碰到很多麻烦。感谢你为我们付出的努力!', '你好，$N!我们的符文布一直比较紧缺，如果你可以省出一些符文布来给我们的话，我们总是表示欢迎的。要是你可以再给我们20块符文布，那么我可以保证，你一定会因为对于暴风城的贡献而被大家认同。$B$B随时欢迎你捐献符文布。', '', '去找奥格瑞玛的莱什纳·刺藤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7833, '捐献毛料', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '我们现在接受毛料的捐赠。只要捐赠60块毛料，暴风城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。', '', '去找奥格瑞玛的维赫纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7834, '捐献丝绸', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在这个社区中的地位无疑将大大提升!那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。', '', '去找杜隆塔尔的维赫纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7835, '捐献魔纹布', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '我们的魔纹布储量很低，而你可以帮助我们补充库存!如果计算整个社区所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被铁炉堡的矮人广为传颂，这一点我可以向你保证!$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。', '', '去找奥格瑞玛的维赫纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7836, '捐献符文布', '', '', '太棒了―我向你保证，这些一定能派上用场。再次感谢你的帮助!如果没有你的话，我们肯定会一筹莫展的。$B$B鉴于你一贯的慷慨，我会欣然接受你随时捐赠更多的符文布。请及时与我联系，我个人可以确保你所做的好事一定会被广为传颂!', '$N，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$B$B如果你愿意的话，请把你多馀的符文布捐献给我。我们现在接受一次60块符文布捐赠。', '', '去找奥格瑞玛的维赫纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7837, '更多的符文布', '', '', '$N―如果没有像你这样的英雄为暴风城亲力亲为的话，我们肯定会碰到很多麻烦。感谢你为我们付出的努力!', '你好，$N!我们的符文布一直比较紧缺，如果你可以省出一些符文布来给我们的话，我们总是表示欢迎的。要是你可以再给我们20块符文布，那么我可以保证，你一定会因为对于暴风城的贡献而被大家认同。$B$B随时欢迎你捐献符文布。', '', '去找奥格瑞玛的维赫纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7838, '竞技场大师', '', '', '你让竞技场的地面洒满了鲜血，我很高兴能宣布你成为竞技场的大师!', '嘿，傻大个!给我12个竞技场大师饰物，你就可以成为古拉巴什竞技场的宗师!', '', '去荆棘谷找古拉巴什竞技场的小个子约翰·米斯瑞尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7839, '邪枝窃贼', '邪枝巨魔入侵了我们的村子，偷走了我的工具！我有备用的工具，但是那套被偷走的工具是当年的一个救了我性命的侏儒送给我的。$B$B我要拿回那套工具，$N——它们对我来说意味着整个世界。$B$B马克霍尔报告说那些工具就在亚戈瓦萨和沙尔瓦萨神庙附近。$B$B那些神庙坐落在辛特兰的东北区域。$B$B找回我的工具！', '辛特兰恶齿村的铁匠斯拉提要你去找到斯拉提的工具。完成任务之后就回到他那里去。$B$B你记得铁匠斯拉提说过，你可以在辛特兰东北部的某个邪枝巨魔神庙中找到它，要不然就是在隐匿石那边。', '我的工具!你找到它们了!哦，多么光辉的一天!感谢你，$N。', '小心邪枝巨魔，$N。他们是一群无情冷血的渣滓。', '', '去辛特兰找恶齿村的铁匠斯拉提。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7840, '拉尔德的午餐', '拉尔德在一个秘密的地方享用野餐，这时丑陋的邪枝巨魔一棍打翻了我。拉尔德跑回了恶齿村，但是把午餐留在了那里。拉尔德饿了。也许你可以去那个秘密的地方找回拉尔德的午餐？拉尔德害怕。出发吧！北边的岛就是那个秘密的地方。', '辛特兰恶齿村的拉尔德要求你去找到拉尔德的午餐。完成任务之后就回到他那里去。$B$B拉尔德说他把午餐留在了北面的岛上。当心邪枝巨魔。', '<拉尔德从你手中夺过巨大的肉块，然后塞进嘴里。>$B$B这太好了!感谢你，小东西。$B$B为了表示感谢，拉尔德特地帮你制作了野餐食物篮。', '<拉尔德揉着他硕大的肚子。>$B$B拉尔德好饿。', '', '去辛特兰找恶齿村的拉尔德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7841, '给蛮锤部族的警告', '蛮锤部族的矮人和我们的敌人联合起来，形成了新的联盟。这一次，他们和高等精灵站在了一起，伙计。$B$B<奥索吐了口唾沫。>$B$B我们必须给那些蛮锤矮人传达一条信息，一条用我们敌人的鲜血书写的警告。杀掉你所看到的所有高原高等精灵，把他们的尸体留在那里作为警告。$B$B永远不要与巨魔为敌！', '辛特兰恶齿村的奥索·莫吉克要你去杀掉8个高原前锋、5个高原斥候和2个高原神射手。任务完成之后回到他那里去复命。$B$B你可以在辛特兰西北部的奎尔丹尼小屋找到那些高原精灵。', '看来恶齿村也有了新的盟友，伙计!你做得很不错。', '你看起来太干净了，伙计。你要努力啊―让敌人的鲜血沾满你的身体吧。', '', '去辛特兰找恶齿村的奥索·莫吉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7842, '又一个给蛮锤部族的警告', '他们说蛮锤部族和狮鹫的关系就好像情侣一般。这让我感到挺恶心的，但是我们可以利用这一点，伙计。我们可以送给他们另外一条警告。$B$B把你在辛特兰看到的所有狮鹫都干掉，收集一根细长的狮鹫羽毛。然后我们就可以发出最后一条警告了。', '辛特兰恶齿村的奥索·莫吉克要你从辛特兰的狮鹫身上收集1根细长的狮鹫羽毛。任务完成之后回到他那里去复命。$B$B在辛特兰各处都有狮鹫出没。', '哦，伙计，太棒了。很快，蛮锤矮人就会发现他们无法与巨魔抗衡!', '最后一条警告一定会让他们胆战心惊，或者会让他们变得非常非常愤怒。', '', '去辛特兰找恶齿村的奥索·莫吉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7843, '给蛮锤部族的最后警告', '<奥索递给你一柄包在几片狮鹫羽毛中的、浸满血迹的长矛。>$B$B拿着这个，伙计。把它带到鹰巢山去，就去镇子中间的水井旁。把这根长矛插在那里！就插在地上！让矮人知道我们巨魔的厉害！当你完成这个壮举之后就回来吧。希望你能活着回来。', '辛特兰恶齿村的奥索·莫吉克要你去辛特兰西部的鹰巢山，把给蛮锤部族的警告插在城镇中心的水井旁边。任务完成之后回到他那里去复命。$B$B当心那些愤怒的蛮锤矮人以及野蛮的联盟成员。', '我真希望能亲临现场看看他们脸上的表情，伙计。他们是不是在急急忙忙地收拾行李，准备逃离镇子?$B$B你做得很好，$N。真的很好。奥索奖励你好东西。', '进行得怎么样，伙计?', '传达给蛮锤部族的警告', '去辛特兰找恶齿村的奥索·莫吉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7844, '野蛮的亲戚', '三个不同的巨魔部族居住在辛特兰地区，$N。我们之间的共同点是：我们都是巨魔，而且我们都住在辛特兰。$B$B邪枝巨魔——正如他们的名字一样，是一群堕落的巨魔；他们以其它的巨魔和人型生物为食。$B$B如果祖尔金在这里的话，他一定会手腕一抖灭掉这个部族——啊，祖尔金还没有回来，所以我们要自己动手了。$B$B现在，你的职责就是把这帮渣滓给干掉！', '辛特兰恶齿村的秘法师雅尔金要你去杀掉6个邪枝割颅者和2个邪枝占卜者。任务完成之后回到他那里去复命。$B$B秘法师雅尔金说过，你可以在辛特兰东北部的沙尔瓦萨和亚戈瓦萨神庙附近找到那些巨魔。', '做得好，$C。即使是祖尔金亲自动手，也不一定做得比你好!', '邪枝割颅者和邪枝预卜者居住在辛特兰的东北部。', '', '去辛特兰找恶齿村的秘法师雅尔金。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7846, '找回钥匙！', '我的镣铐的钥匙在守护者希坦亚手里，她就在洞穴附近。小心一点，$c，她身边有强悍的守卫。$B$B干掉她，然后用她的钥匙打开我的镣铐。只有这样我才能回家。', '辛萨罗的断齿长者要求你杀掉守护者希坦亚，并用她身上的镣铐钥匙打开他的镣铐。当你找到钥匙之后就回到他那里去。', '我终于自由了!感谢你，$N。恶齿村感谢你的英勇行为!', '你必须马上行动!', '', '去辛特兰找辛萨罗的断齿长者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7848, '熔火之心的传送门', '裂隙在翻滚，它撕裂并吞噬我们周围所有的东西，$c。我所站立的地方旁边的裂隙就是穿过黑石深渊直通火焰之王所在地的传送门。$B$B你感到很惊奇吗？真是遗憾……凡人总是无法领悟那些他们无法看到、触摸到或者感觉到的东西。$B$B我向你保证，这个传送门可以到达熔火之心。$B$B你开始感兴趣了吗？其实这是很简单的。进入熔火之心，获得一块熔火碎片，把它交给我，然后我就会将你的灵魂与传送门进行同步。', '进入黑石深渊，在通往熔火之心的传送门附近找到一块熔火碎片，然后回到黑石山脉的洛索斯·天痕那里。', '步入我右方的裂隙，你就将进入熔火之心。', '现在跳入裂缝之中将会给你带来无穷的灾难……', '', '去燃烧平原找黑石山的洛索斯·天痕。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7849, '分离的痛苦', '和许多朋友一样，我挚爱的亲人也在野外永远逝去了。啊，我的双胞胎兄弟莫克霍尔——他在邪枝巨魔突袭的那天晚上死了。$B$B他被残忍地处死，他的尸体被软泥怪和邪枝巨魔的狼分食。$B$B现在拯救他的肉体已经太晚了，但我们要拯救他的灵魂。把他的遗体带回来，$N。', '辛特兰恶齿村的猎户马克霍尔要你去找回他的双胞胎兄弟的尸体。找到它，然后把猎户莫克霍尔的徽记和猎户莫克霍尔的骨头交给猎户马克霍尔。$B$B马克霍尔说过，他兄弟的尸体被软泥怪和邪枝巨魔的狼群分食。他还提到在辛萨罗有个大坑，里面全都是软泥怪，那里还有个狼穴。这两个地方都在靠近辛萨罗神庙顶部的区域。', '我最亲爱的兄弟，我非常想念你。$B$B感谢你的帮助，$N。你是真正的英雄。', '当我看到他的尸体时，我会把它交给雅尔金，并进行一个火葬仪式。', '', '去辛特兰找恶齿村的猎户马克霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7850, '黑暗之瓶', '邪枝巨魔正在疯狂地进攻我们，这是因为他们受到了邪恶祭司海克斯的堕落魔法的影响。$B$B你可以在辛萨罗找到腐化之血。那只装着腐化之血的瓶子散发着邪神哈卡的堕落能量，这让邪枝巨魔们充满了力量，并让他们变得疯狂。$B$B把那些腐化之血交给我，这样我就可以去除其中的堕落能量，以此来削弱邪神的力量。', '辛特兰恶齿村的断齿族长要你在辛萨罗找到5瓶腐化之血。任务完成之后就回到断齿族长那里。', '笼罩在邪枝巨魔身上的黑暗能量被消除了―至少现在是这样。我们必须在和邪恶力量战斗的过程中保持警惕，即使邪恶祭司已经被干掉了，很快就会有另一个巨魔替换她的位置。', '在和邪枝巨魔作战的时候要多加小心，$N。他们的理智已经丧失了―他们会奋战到底。', '', '去辛特兰找恶齿村的断齿族长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7861, '通缉：邪恶祭司海克斯和她的爪牙', '根据断齿族长的命令，邪恶祭司海克斯和她的手下必须受到制裁！$B$B如果你能除掉邪恶祭司海克斯和她的精英卫兵，那么你就可以获得丰富的奖励。', '你必须杀掉邪恶祭司海克斯和5名邪枝精英守卫。任务完成之后回到辛特兰的恶齿村，向断齿族长报告。$B$B你可以在辛特兰的邪枝巨魔城市辛萨罗的顶部找到他们。', '这真是对邪枝巨魔的一次沉重打击。你应该得到嘉奖，$N。', '你从辛萨罗那边带来什么消息了吗?', '', '去辛特兰找恶齿村的断齿族长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7862, '职位空缺：恶齿村卫兵队长', '在卫兵队长马克霍尔牺牲之后，恶齿村卫兵队长的职位再次空缺。如果你有兴趣成为恶齿村的卫兵队长，就必须完成以下任务，然后向断齿族长提交申请表：$B$B消灭邪枝狂战士。$B$B消灭邪枝暗影猎手。$B$B消灭邪枝饮血者。$B$B消灭邪枝噬魂者。', '你必须消灭5个邪枝狂战士、3个邪枝暗影猎手、3个邪枝饮血者和3个邪枝噬魂者。$B$B完成任务之后向辛特兰恶齿村的断齿族长复命。', '你是这个职位的理想候选人，$N。请收下这个饰物作为我们对你辛勤工作的奖励吧。我会在明年审阅所有的申请。', '你是来这里申请职位的吗?', '', '去辛特兰找恶齿村的断齿族长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7874, '镇压银翼部队', '灰谷森林将在强大的部落面前屈服，$r。无论暗夜精灵们说什么做什么，都无法阻止我们的推进。卡利姆多属于部落，谁敢阻止我们拿取属于我们的东西，谁就要死！$B$B让你的心中充满荣耀之光，让那些胆敢阻止我们的敌人一个个倒下。摧毁银翼要塞中的哨兵部队，并拿到一枚战歌荣誉奖章。把这样一枚奖章给我拿来，你就可以获得奖赏。', '进入战歌峡谷击败联盟小队，获得一枚战歌荣誉奖章，然后向莫尔杉营地的沙塔尔·碎颅复命。', '<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要让多少联盟的渣滓牺牲在部落的面前才能让他们退却?只有时间可以说明一切，$C……', '敌人的鲜血就是我们的荣耀的象征，你做得很出色。', '', '去贫瘠之地找莫尔杉营地的沙塔尔·碎颅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7875, '镇压银翼部队', '灰谷森林将在强大的部落面前屈服，$r。无论暗夜精灵们说什么做什么，都无法阻止我们的推进。卡利姆多属于部落，谁敢阻止我们拿取属于我们的东西，谁就要死！$B$B让你的心中充满荣耀之光，让那些胆敢阻止我们的敌人一个个倒下。摧毁银翼要塞中的哨兵部队，并拿到一枚战歌荣誉奖章。把这样一枚奖章给我拿来，你就可以获得奖赏。', '进入战歌峡谷击败联盟小队，获得一枚战歌荣誉奖章，然后向莫尔杉营地的沙塔尔·碎颅复命。', '<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要让多少联盟的渣滓牺牲在部落的面前才能让他们退却?只有时间可以说明一切，$C……', '敌人的鲜血就是我们的荣耀的象征，你做得很出色。', '', '去贫瘠之地找莫尔杉营地的沙塔尔·碎颅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7876, '镇压银翼部队', '灰谷森林将在强大的部落面前屈服，$r。无论暗夜精灵们说什么做什么，都无法阻止我们的推进。卡利姆多属于部落，谁敢阻止我们拿取属于我们的东西，谁就要死！$B$B让你的心中充满荣耀之光，让那些胆敢阻止我们的敌人一个个倒下。摧毁银翼要塞中的哨兵部队，并拿到一枚战歌荣誉奖章。把这样一枚奖章给我拿来，你就可以获得奖赏。', '进入战歌峡谷击败联盟小队，获得一枚战歌荣誉奖章，然后向莫尔杉营地的沙塔尔·碎颅复命。', '<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要让多少联盟的渣滓牺牲在部落的面前才能让他们退却?只有时间可以说明一切，$C……', '敌人的鲜血就是我们的荣耀的象征，你做得很出色。', '', '去贫瘠之地找莫尔杉营地的沙塔尔·碎颅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7881, '狂欢节长靴', '', '', '感谢你，$N。你干得真不错。你的手艺绝对是顶级的!这里是给你的暗月马戏团奖券……希望你喜欢，$g先生:女士;。', '我们暗月马戏团四海为家。我们从一个地方走到另外一个地方……事实上，你会发现我们永远停不下来!因此我们穿破了无数的鞋子也不足为奇!我们需要时髦而且耐穿的鞋子，而雕花皮甲长靴正好满足我们的需要。$B$B你!你是一个制皮匠，那么帮我制作雕花皮甲长靴吧，我会给你一张暗月马戏团奖券作为回报。', '', '去找克洛诺斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7882, '狂欢节外套', '', '', '啊，你把衣服带来了。太好了。我可以问一下你是用什么动物的皮革制作它们的吗?这针线活做得真是太好了，皮革的材质也很不错。你真是个技艺精湛的工匠!$B$B感谢你，$N，这里是你的奖券。', '我们的工作人员不仅仅是负责清扫垃圾的!他们还在大篷车在巡游的时候负责警戒，因此他们需要优质的护甲。$B$B如果你可以制作结实的皮甲，那我可以保证它一定会物尽所用。我会给你一些暗月马戏团奖券作为报酬。', '', '去找克洛诺斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7883, '世界上最大的侏儒！', '', '', '哦，天啊，这些戏服还真大!我无法想象有地精可以合身的穿上它们，但是不要担心-如果我们找到的地精身材不够大的话，那么我可以调整他的戏服。$B$B非常感谢，$N。这是我允诺给你的奖券。', '亚布.尼比盖尔正在找寻更多的天才来加入他的演出，他正在找世界上个头最大的地精。你知道有身材尺寸合适的地精吗?$B$B在我们找到那个地精之前，他希望可以把他的演出服装给准备好。我想野人背心就可以胜任，你可以制作一些背心吗?如果可以的话，我会给你一叠暗月马戏团奖券的……', '', '去找克洛诺斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7884, '鳄鱼小子和有胡子的鱼人', '', '', '太好了!这些东西很不错……我希望我不是那个将要去清扫鳄鱼笼子的家伙。那些野兽的兽性十足， 嗯嗯……$B$B这是你的奖券，$N。尽情享受你在暗月马戏团的时光吧!', '亚布正在为他的动物园增加新的观光景点，包括一间沼泽小屋，用来安顿一个被鳄鱼喂养长大的小男孩，或者也许是给一个鱼人住的。我们需要高档的防水护腿，避免在水底行动的时候弄得浑身湿透。我想我们需要龟壳护腿。$B$B$N，你可以制作这种护腿吗?如果可以的话，那么一大堆暗月马戏团奖券就是你的了……', '', '去找克洛诺斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7885, '护甲片', '', '', '太棒了!我刚刚发现了帐篷上的一条裂缝，正需要用这些护甲片中的一块来修补它!$B$B非常感谢你，$N。它们可以帮我们节省大量的修补费用。这里是你的奖券―祝你玩得愉快!', '你可能不会相信，但是经营一个流动的嘉年华会是很花钱的!每样东西都耗损的那么快，我们还可以赚钱实在是个奇迹。$B$B为了节省开支，我们一直在寻找方法来尽可能便宜的维护我们的设备。举例来说，我们的帐棚常常会裂开，但是我发现皮制护甲片可以拿来做很好的修复。你可以帮我带一些护甲片来吗?这会让我们在买新帐篷的花费上节省许多!如果你可以做到的话，我有一大堆的暗月马戏团奖券可以给你……', '', '去找克洛诺斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7889, '粗制平衡石', '', '', '太棒了!这些东西非常合适!它们不太重，但是也不太轻，正好用来帮我来强化肌肉!$B$B非常感谢你，$N。这是你的暗月马戏团奖券!', '要当世界上最强壮的女人可不是一件容易的事情!我的体重已经开始变得太轻了，要维持适当的身材就需要增加更多体重!$B$B你认为你可以给我弄一些镇石来吗?如果可以的话，那么我会给你一张暗月马戏团奖券。', '', '去找克莉·希克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7890, '重砂轮', '', '', '你把石头带来了!嗯，非常重!我已经可以感到我的肌肉在膨胀了。感谢你，$N!$B$B拿着，拿着这些奖券，不要在这里吃太多的甜食。像你这样强大的$C需要一直保持自己的身材!', '如果你想要帮我健身的话，我需要一根两头穿着重砂轮的杖子，然后我把这根杖子举过头顶来锻炼。听起来并不简单，但是作为世界上最强的女人，我不能有丝毫的松懈!$B$B你能不能帮我?我需要更多的重砂轮―给我弄一些来，我可以用暗月马戏团奖券和你进行交易。', '', '去找克莉·希克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7891, '绿铁护腕', '', '', '太好了!这些正是我所需要的!多么迷人的颜色啊，而且它们让我的臂膀显得如此强大!太完美了!$B$B给你，$N。这是你的奖券─希望你喜欢!', '我正在忙着制作一件新的戏服，当我有自己的展台来展示我是世界上最强的女人时，就可以穿着它上台了!现在我正在寻找合适的护腕。它们不能遮盖太多，否则大家就看不到我的肌肉了，另外我希望它能有些闪光，你明白了吗?$B$B你看绿铁护腕是不是适合我呢，$N?你可以帮我做一双绿铁护腕吗?如果可以的话，我有许多的暗月马戏团奖券可以送给你。', '', '去找克莉·希克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7892, '巨型黑色锤', '', '', '啊，太棒了!这柄铁锤的头很大。我打赌我可以用它敲碎掉任何东西。我只希望砸东西的时候它自己不要碎掉!$B$B这里是你的奖券，$N。尽情享受在马戏团的时光吧!', '作为世界上最强的女人，我计画从观众那里收集各种东西，然后用大锤把它们全都敲碎!$B$B你可以帮我制作一柄巨型黑锤吗，$N?', '', '去找克莉·希克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7893, '力量仪式', '', '', '谢谢你，$N。我将用这些砂轮来进行一种我从荆棘谷中的古老石板上读到的力量仪式。$B$B据说成功完成仪式的人将获得十倍于牛头人的力量和耐力!', '$N，在我寻求成为世上最强的女人过程中，我曾周游世界，从各种高手那里和古书中学到了强化肌肉的秘密。我掌握着可以让你将弱者轻松击溃的锻炼方法!$B$B要进行这种训练的话，我需要很多砂轮。$N，你有砂轮吗?', '', '去找克莉·希克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7894, '铜质调节器', '', '', '啊哈!调节器!太棒了!$B$B我不能告诉你我们正在制作什么，但是这些调节器对我们来说真是无价之宝啊。我欠你的人情，$N，请收下这张暗月马戏团奖券作为回报吧。', '亚布正在为动物园研制一种新玩意儿，它能使人们沉浸在疯狂的愉悦中!但是这东西需要耗费大量精力和原料……$B$B其中包括铜质调节器。我们需要大量的铜质调节器作为机械部件，我会用暗月马戏团奖券来与你交换。', '', '去找瑞林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7895, '高速青铜齿轮', '', '', '你带来了高速青铜齿轮!太棒了!我现在就能听到这些高速青铜齿轮欢快的吟唱声!啊，当我的售货亭一切就绪时，它将成为世界上最伟大的奇观，等着瞧吧!$B$B这是你的优惠券，$N。尽情享受吧!', '我的崭新的售货亭将是一道风景线，没错!一道风景线，而且……只有少数的幸运儿才可以接近!$B$B当顾客走近我的售货亭时，那些高速青铜齿轮便会欢快地吟唱起来!$B$B啊……现在我需要一些高速青铜齿轮来实现这一梦想。$N，请给我弄点高速青铜齿轮来吧……我会用暗月马戏团奖券来和你交换的!', '', '去找瑞林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7896, '绿色焰火', '', '', '你带来了烟火，好极了，$N!我真想赶快点燃烟火，告诉全世界我的售货亭开张啦!但是还得等等，恐怕还得相当一段日子……等我准备就绪，自然会开张的。$B$B这儿是你的奖券，$N。尽情享受吧!', '当我的售货亭一切准备就绪，开始营业时，我会做一些广告!还有什么宣传方式比烟火更加有效呢?$B$B嗯，或许有人认为在沸腾的大熔炉中翻煮敌人的头颅更能吸引人群，但是……我们这里什么种族的成员都有。烟火一定能达到华丽的效果!$B$B给我绿色烟火，$N，我会用一叠暗月马戏团奖券来交换的。', '', '去找瑞林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7897, '机械修理包', '', '', '谢谢你!现在我可以修理这些东西啦。$B$B我需要大量的机械修理包，不眠不休好多天才能把所有东西都修理完毕。有时，我觉得自己最好回到故乡，重操旧业，做一名猎头者，但是……暗月马戏团对我来说相当重要。$B$B带上这些奖券，$N，尽情享受吧!', '我的售货亭不能开张的最大原因是……所有的东西都坏啦!我需要机械修理包进行修理!$B$B你能给我机械修理包吗，$N?我会用暗月马戏团奖券来交换的，你觉得怎么样?', '', '去找瑞林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7898, '瑟银零件', '', '', '啊，谢谢你，$N!亚布会用得到它们的。我不知道他准备用这些东西来干什么，但亚布是个聪明的小地精……他聪明得几乎有些狡猾了……$B$B如果他喜欢吃人，那他简直就是个彻头彻尾的巨魔了!$B$B拿着这个，$N。这些奖券是你的了。', '亚布.尼比盖尔跟我一样，正在进行一项新发明。叶博说，这个这东西是那么的惊人华丽，足以把整个世界的人都吸引过来……这将会让我们每个人都变的非常非常的富有!$B$B他说他需要瑟银零件来进行这项工程，所以要我去收集给他。你觉得如何，$N?你想要用瑟银零件来交换暗月马戏团奖券吗?', '', '去找瑞林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7899, '毛茸茸的小爪子', '', '', '哈哈，毛茸茸的小爪子，棒极了!我们可以使用这些爪子来制作玩具和别的小玩意儿，这些能吸引更多的观众来到暗月马戏团!$B$B这是你的奖券，$N。是你应得的报酬!', '要吸引人潮的第一课就是:用小东西跟小玩意儿引诱他们!你可以帮我吗?$B$B我需要毛茸茸的小爪子做为奖品。你可以在贫瘠之地或是黑海岸的猫身上取得它们……$B$B帮我带一些爪子来，我可以用暗月马戏团奖券来交换它们。', '', '去找亚布·尼比盖尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7900, '破损的熊皮', '', '', '很好的熊皮，$N!我会找人将它们缝制成绒毛玩具的。再加上点填充料和颜料，我想它们就会成为艾泽拉斯所有小朋友的最爱!$B$B奖券?啊，对，你的报酬!给你!', '小孩子喜欢玩具!我发现所有的小孩都喜欢用破损的熊皮制成的绒毛玩具!$B$B你可以在灰谷或希尔斯布莱德的熊身上弄到熊皮。我会用暗月马戏团奖券来和你交换的!', '', '去找亚布·尼比盖尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7901, '柔软的狼尾', '', '', '做得好，$N!这些狼尾将为我们的观众带来惊喜，然后他们会跟他们的朋友谈及此事，从而为我们招揽更多的观众!$B$B这是你的奖券!尽情享受暗月马戏团的好时光吧……别忘记跟你的朋友谈起我们!', '人们评断事物价值的方法实在很奇妙!就这么举例来说好了，一根绑上了一条柔软的狼尾的木棍。现在，你跟我可能都会觉得像这样的东西并不是那么的值钱……但是如果你替那个垃圾取个很棒的名字，像是“荒野绒毛小尾巴”，然后把它放到一个很漂亮的盒子里面，那人们就会觉得它价值不斐。垃圾立刻变黄金!$B$B帮我从凄凉之地跟荒芜之地带些柔软的狼尾回来，我就给你暗月马戏团奖券。', '', '去找亚布·尼比盖尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7902, '鲜艳的羽毛', '', '', '啊，羽毛!这真令人惊异，不是吗?在这样美丽的东西面前，人的想象力是很容易爆发的!$B$B你做得棒极了，$N。当游客们面露微笑时，我们就得到了最好的回报，请收下这些奖券吧。', '�人的想象力实在是很不可思议的东西。它能让小小的山丘变成巍峨的高峰，让平淡无奇的阴影变成恐怖的梦魇!$B$B在暗月马戏团，它可以让最无害的影子表现的像是个可怕的梦靥!$B$B我们暗月马戏团就是要让我们的参观者的想象力无尽扩展!但是要诱发他们的想象力……有时候我们必须耍点小手段。$B$B我其中一个吸引点需要用到鲜艳的羽毛。你可以从艾泽拉斯大陆上一些危险的地区中的鸟身上取得。把这些羽毛带来给我，你就可以得到很多的奖券!', '', '去找亚布·尼比盖尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7903, '邪恶的蝙蝠眼', '', '', '很好!很好!我希望那些蝙蝠曾把你吓坏了，因为如果它们的眼睛可以把你这样勇敢的$C吓得心惊胆战，那它们一定可以把游客们吓得魂飞魄散!$B$B拿着这些奖券吧，$N，谢谢你的帮助。', '你有没有曾经在一个伸手不见五指的洞穴里游荡，追寻冒险跟刺激?你有?真的吗?很好，那你一定看过蝙蝠那令人毛骨悚然的眼睛从高高的地方凝视着你，等待着你放松戒备的时候好来吸你的血!$B$B很可怕的想法，你不觉得吗?当然!蝙蝠眼毫无疑问是很可怕的!$B$B你可以帮我拿些蝙蝠眼来吗，$N?我需要它们来……给我正在设计的某件东西。某件很可怕的东西。$B$B你可以从东瘟疫之地的蝙蝠身上找到它们。', '', '去找亚布·尼比盖尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7905, '暗月马戏团', '暗月马戏团就要来啦！尽情享受这一激动人心的盛典吧！$B$B现在赶快行动，用这张优惠券换取免费的礼品券！带上你的赠券去狂欢节上找吉瓦斯·格里加特吧，别把它弄丢了！现在就出发吧！', '到暗月马戏团的场地里去，将免费券交给吉瓦斯·格里加特。', '欢迎来到暗月马戏团!这张礼券可以兑换5张奖品券呢!$B$B你可以用奖品券兑换一些价值不菲的奖品券越多，能换取的奖品也就越多。哈哈!', '我的朋友，我能帮你什么忙吗?你有需要兑换的礼券吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7907, '暗月野兽套牌', '你现在已经收集到了野兽套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。', '当暗月马戏团来到镇上的时候，把野兽套牌交给他们。', '现在你已经集满了整套野兽套卡。把它还给我们会让你和暗月马戏团之间创建永不断裂的联系。请允许我将一张更强大的暗月卡片回送给你做为酬谢你的一份薄礼。', '看来你集满一整套野兽套卡了!恭喜你!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7926, '暗月马戏团', '暗月马戏团就要来啦！尽情享受这一激动人心的盛典吧！$B$B现在赶快行动，用这张优惠券换取免费的礼品券！带上你的赠券去狂欢节上找吉瓦斯·格里加特吧，别把它弄丢了！现在就出发吧！', '到暗月马戏团的场地里去，将免费券交给吉瓦斯·格里加特。', '欢迎来到暗月马戏团!这张礼券可以兑换5张奖品券呢!$B$B你可以用奖品券兑换一些价值不菲的奖品券越多，能换取的奖品也就越多。哈哈!', '我的朋友，我能帮你什么忙吗?你有需要兑换的礼券吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7927, '暗月入口套牌', '你现在已经收集到了入口套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。', '当暗月马戏团来到镇上的时候，把入口套牌交给他们。', '现在你已经集满了整套传送门套卡。把它还给我们会让你和暗月马戏团之间创建永不断裂的联系。请允许我将一张更强大的暗月卡片回送给你做为酬谢你的一份薄礼。', '看来你集满一整套传送门套卡了!恭喜你!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7928, '暗月督军套牌', '你现在已经收集到了督军套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。', '当暗月马戏团来到镇上的时候，把督军套牌交给他们。', '现在你已经集满了整套督军套卡。把它还给我们会让你和暗月马戏团之间创建永不断裂的联系。请允许我将一张更强大的暗月卡片回送给你做为酬谢你的一份薄礼。', '看来你集满一整套督军套卡了!恭喜你!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7929, '暗月元素套牌', '你现在已经收集到了元素套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。', '当暗月马戏团来到镇上的时候，把元素套牌交给他们。', '现在你已经集满了整套元素套卡。把它还给我们会让你和暗月马戏团之间创建永不断裂的联系。请允许我将一张更强大的暗月卡片回送给你做为酬谢你的一份薄礼。', '看来你集满一整套元素套卡了!恭喜你!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7930, '5张奖券 - 暗月花束', '', '', '拿去吧，拿去吧!一个最适合$g国王:皇后;的奖品!恭喜你，我的朋友!$B$B如果你有更多奖券想要兑换，请告诉我!只要暗月马戏团还在这里，我就会兑换你的奖券。', '靠过来，靠过来!如果你想要兑换暗月马戏团奖券，尽管开口吧!你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧!', '', '去找吉瓦斯·格里加特。', '', '', '', '');
