INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7935, '10张奖券 - 上个月的羊肉', '', '', '拿去吧，拿去吧!一个最适合$g国王:皇后;的奖品!恭喜你，我的朋友!$B$B如果你有更多奖券想要兑换，请告诉我!只要暗月马戏团还在这里，我就会兑换你的奖券。', '靠过来，靠过来!如果你想要兑换从暗月马戏团得到的奖券，尽管开口吧!你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看\r\n吧!', '', '去找吉瓦斯·格里加特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7936, '50张奖券 - 去年的羊肉', '', '', '拿去吧，拿去吧!一个最适合$g国王:皇后;的奖品!恭喜你，我的朋友!$B$B如果你有更多奖券想要兑换，请告诉我!只要暗月马戏团还在这里，我就会兑换你的奖券。', '靠过来，靠过来!如果你想要兑换暗月马戏团奖券，尽管开口吧!你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧!', '', '去找吉瓦斯·格里加特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7937, '财富在等着你……', '“东谷的财宝正等着你。”$B$B你抚摸着手中的塔罗牌，感到一丝暖意。你紧紧地握住它，眼前浮现出艾尔文森林东谷伐木场的影像。你专注地观察着，发现马厩附近有一堆干草。', '到艾尔文森林的东谷伐木场去寻找你的财宝吧。', '你快速搜查了干草堆，找到一只带锁的小带锁箱!似乎你已经找到财宝了!', '这堆干草看起来跟幻象中的很像……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7938, '财富在等着你……', '“死亡矿井中的财宝正等着你。”$B$B你抚摸着手中的塔罗牌，感到一丝暖意。你紧紧地握住它，眼前浮现出位于西部荒野月溪镇的死亡矿井的影像。你专注地观察着，发现蜿蜒的道路尽头是一道发光的门……通往矿洞中心的门。你穿过大门，不知从哪儿冒出一个奇怪的箱子。', '到西部荒野的死亡矿井中去寻找你的财宝吧。', '你快速搜查了带锁箱，找到一只带锁的小带锁箱!似乎你已经找到财宝了!', '这箱子看起来跟幻象中的很像……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7939, '更多致密砂轮', '', '', '啊，感谢你$N。请收下这些奖券，然后把关于暗月马戏团的事情告诉你所有的朋友!', '$N，感谢你所给予我的一切帮助。我实在无法足够的表达我的谢意!$B$B虽然我没那么需要了……但是如果你带给我更多的致密砂轮，我可以给你更多暗月马戏团奖券。', '', '去找克莉·希克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7940, '1200张奖券 - 暗月宝珠', '', '', '拿去吧，拿去吧!一个最适合$g国王:皇后;的奖品!恭喜你，我的朋友!$B$B如果你有更多奖券想要兑换，请告诉我!只要暗月马戏团还在这里，我就会兑换你的奖券。', '靠过来，靠过来!如果你想要兑换暗月马戏团奖券，尽管开口吧!你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧!', '', '去找吉瓦斯·格里加特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7941, '更多护甲片', '', '', '给你，$N。很公平的交易。希望你喜欢。', '$N，我必须要感谢你的帮助。我有很多的补给了，当然这里面你帮了很大的忙，如果你可以带更多的护甲片给我的话，我会很乐意用暗月马戏团奖券来交换它们。', '', '去找克洛诺斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7942, '更多瑟银零件', '', '', '给你，$N。这些是暗月马戏团奖券，去尽情狂欢吧。可别在同一个地方把它们都花光啦!', '$N，你对我们真是太好了，一直不嫌疲倦的替我带来这些货物。我由衷的感谢你!$B$B虽然我们对于瑟银零件的需求已经不像之前那么大了，但是你仍然可以拿来给我，我还是会很乐意用它们来交换暗月马戏团奖券的。', '', '去找瑞林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7943, '更多蝙蝠眼', '', '', '再次感谢你，$N。这是给你的奖券!', '$N，我正在设计的东西将是继诺姆瑞根被入侵后最可怕的事件!这要大力的感谢你以及你带给我的小玩意儿。真是太太太感谢你了!$B$B虽然我已经不太需要了，但是……如果你可以从东瘟疫之地的蝙蝠身上取得更多的邪恶蝙蝠眼给我的话……我也许会给你更多暗月马戏团奖券。', '', '去找亚布·尼比盖尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7944, '财富在等着你……', '“哀嚎洞穴中的财宝正等着你。”$B$B你抚摸着手中的塔罗牌，感到一丝暖意。你紧紧地握住它，眼前浮现出了位于贫瘠之地十字路口西南方的一处洞穴的影像。你专注地观察着，发现蜿蜒的道路尽头是一道发光的门……通往洞穴中心的门。你穿过大门，不知从哪儿冒出了一个奇怪的箱子。', '到贫瘠之地的哀嚎洞穴中去寻找你的财宝吧。', '你快速搜查了带锁箱，找到一只带锁的小带锁箱!似乎你已经找到财宝了!', '这箱子看起来跟幻象中的很像……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7945, '财富在等着你……', '“灰月洞穴外的财宝正等着你。”$B$B你抚摸着手中的塔罗牌，感到一丝暖意。你紧紧地握住它，眼前浮现出莫高雷灰月洞穴的影像。你专注地观察着，发现洞穴入口附近有一块树桩。', '到莫高雷的灰月洞穴去寻找你的财宝吧。', '你快速搜查了树桩，找到一只带锁的小带锁箱!似乎你已经找到财宝了!', '这树桩看起来跟幻象中的很像……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7946, '加布加布', '', '', '感谢你，$N。拿着这颗蛋吧!虽然它不会马上孵化，但是当它孵化的时候，你将拥有一个非常棒的宠物!', '我真高兴啾啾终于回来了。她是那么喜欢黑铁麦芽酒，所以当我没有了以后，她就跑去找更多的酒了!$B$B现在啾啾回来了，我要所有我可以取得的麦芽酒!我不希望她再跑掉了!$B$B你有黑铁麦芽酒吗?如果你有的话，我愿意用1颗啾啾的蛋跟你换1杯酒……', '', '去找摩尔亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7981, '1200张奖券 - 暗月护符', '', '', '拿去吧，拿去吧!一个最适合$g国王:皇后;的奖品!恭喜你，我的朋友!$B$B如果你有更多奖券想要兑换，请告诉我!只要暗月马戏团还在这里，我就会兑换你的奖券。', '靠过来，靠过来!如果你想要兑换暗月马戏团的奖券，尽管开口吧!你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧!', '', '去找吉瓦斯·格里加特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8042, '穆贾巴之力', '', '', '我们会再见面的，$C。', '见到你身体健康真好，$N。这场显赫的战斗影响着这个星球上的所有生物。绝不能让哈卡离开祖尔格拉布，否则世界将会毁在他无尽的欲望中。$B$B把坠饰给我吧，我会强化它的力量。运用穆贾巴之力惩罚我们的敌人吧!', '', '去找荆棘谷的击碎者金罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8043, '穆贾巴之力', '', '', '我们会再见面的，$C。', '见到你身体健康真好，$N。这场显赫的战斗影响着这个星球上的所有生物。绝不能让哈卡离开祖尔格拉布，否则世界将会毁在他无尽的欲望中。$B$B把坠饰给我吧，我会强化它的力量。运用穆贾巴之力惩罚我们的敌人吧!', '', '去找荆棘谷的击碎者金罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8044, '穆贾巴的怒火', '', '', '祖尔金都会羡慕的，战士。去吧，征服你的敌人!', '拉斯塔哈向你致敬，$N。这样的荣誉对非赞达拉部族的成员来说还是头一次。$B$B<金罗克向你鞠躬。>$B$B把坠饰给我吧，我会再次强化它的力量。穆贾巴的怒火已经与你的灵魂连在了一起。', '', '去找荆棘谷的击碎者金罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8046, '异教徒的烙印', '', '', '去吧，你必须打败我们的敌人，$C。即使这意味着要借助圣光的力量。$B$B<金罗克浑身战栗。>', '我的判断看来有些草率，$C。似乎你对圣光的盲目信仰还有些用处。$B$B把烙印给我吧，我会强化它的力量。', '', '去找荆棘谷的击碎者金罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8047, '异教徒的烙印', '', '', '去吧，你必须打败我们的敌人，$C。即使这意味着要借助圣光的力量。$B$B<金罗克浑身战栗。>', '我的判断看来有些草率，$C。似乎你对圣光的盲目信仰还有些用处。$B$B把烙印给我吧，我会强化它的力量。', '', '去找荆棘谷的击碎者金罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8048, '英雄的烙印', '', '', '警觉、荣誉、忠诚、勇敢……你拥有所有的优点，你的烙印也应如此。', '你获得了国王的认可，$C。拉斯塔哈承认你是赞达拉真正的盟友，这在你的族人中还是头一次呢。$B$B你将收到丰厚的奖励。把烙印给我吧，我会最后一次强化它。', '', '去找荆棘谷的击碎者金罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8050, '祖达萨之眼', '', '', '$N，你要坚持不懈地奋力战斗。夺魂者会试图汲取你求生的意志。', '牧师，你与古拉巴什一族作战的英勇事迹早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。', '', '去找荆棘谷的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8051, '祖达萨之眼', '', '', '$N，你要坚持不懈地奋力战斗。夺魂者会试图汲取你求生的意志。', '牧师，你与古拉巴什一族作战的英勇事迹早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。', '', '去找荆棘谷的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8052, '祖达萨全视之眼', '', '', '给他们迎头痛击，让哈卡尝尝失败的滋味……', '$N，如果我们有上万名像你这样的人物，哈卡的军队将在瞬间灰飞烟灭。$B$B<阿塔比姆发出了一声叹息。>$B$B唉，祖达萨之眼就要发挥它所有的潜能了。把它给我。', '', '去找荆棘谷的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8053, '权力珍宝：思考者护臂', '你是一名异教徒。异教徒在部族中也占有一席之地，他们是赞达拉的思考者。思考者面对压迫，毫不畏惧；他们愿意为自己的信仰而死。我们知道，你也愿意为自己的信仰而死。我会给你一个证明自己实力的机会。$B$B我们必须拿到足够的权力珍宝。去祖尔格拉布吧，去杀死哈卡的爪牙。当你找到权力珍宝后再回到我这儿来。我会奖给你一件赞达拉思考者的战斗装备。$B$B去吧。', '从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱护腕。你还必须在赞达拉部族中达到友善或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。', '你令我们感到荣耀。你的双手沾满了哈卡爪牙的鲜血。你是部族的朋友。$B$B戴着这些臂甲。它们是思考者臂甲。这是我所谓真正的力量。', '你回来了?你带回权力珍宝了吗?你在浪费我时间吗?$B$B我希望不是，异教徒。', '', '去荆棘谷找尤亚姆巴岛的击碎者金罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8054, '权力珍宝：思考者腰带', '你的信仰与我们大不相同，异教徒。古时的赞达拉部族被称为异教徒。那时古拉巴什帝国还很强大，异教徒冒险挑战哈卡的牧师，但是被杀死了。这些异教徒打败哈卡的信念从未动摇，因此我们对他们表示尊敬。他们是思考者。$B$B杀死祖尔格拉布里面的哈卡的爪牙，找回我需要的权力珍宝。如果你成功的话，就可以得到丰厚的奖励。$B$B去吧。', '从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱披肩。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。', '你将获得部族的尊敬。你血洗了祖尔格拉布。敌人在你的信念前倒下。敌人因你的力量而死。$B$B这是思考者腰带。它是荣誉的象征。它是强大的魔精。现在它属于你了。', '你获胜了?你取回权力珍宝了吗?你杀死敌人了吗?', '', '去荆棘谷找尤亚姆巴岛的击碎者金罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8055, '权力珍宝：思考者胸甲', '战争赋予你强大的力量。思考者得到的就是这样的力量，他们都是狂热的家伙，他们在胸甲中浸入魔精——这样，就算他们在面对敌人时动摇了自己的信仰，他们的胸甲也不会有丝毫变化。$B$B你在赞达拉部族中的声望必须达到崇拜才能拥有这样一件胸甲。去祖尔格拉布吧，带回我需要的权力珍宝。给予那儿的蠢货们狠狠一击，取回权力珍宝。证明自己作为思考者的实力。', '从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱徽章。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。', '你做到了很多人永远也无法做到的事情。你打败了哈卡的爪牙，让他们见识到思考者的能力。异教徒在赞达拉部族中也能赢得崇拜。你拥有不可思议的力量，你就是力量的化身。$B$B思考者，拿走属于你的胸甲吧。粉碎那些反对你的家伙。', '你拿到权力珍宝了吗?那里面有魔精，我们必须得到它。你必须帮助我们。', '', '去荆棘谷找尤亚姆巴岛的击碎者金罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8056, '权力珍宝：预言者护腕', '预言者以他们超凡的眼界在部族中倍受尊敬。他们不是巫医，他们是通过抛掷骨头或是辨识树叶来进行预言的。作为一名萨满祭司，你已经掌握了预言者的一些能力；赞达拉部族非常重视他们的预言。$B$B去祖尔格拉布，取回我需要的权力珍宝，证明自己的价值。如果你成功的话，我就会送你一副预言者护腕的！', '从祖尔格拉布把以下权力珍宝交给祖达萨的梅维克：1条原始哈卡莱护臂。你还必须在赞达拉部族中达到友善或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。', '看起来你有点赞达拉占兆师的模样了。我们知道你在祖尔格拉布为我们所做的一切。这些权力珍宝将帮助赞达拉部族―或许我应该说，你的朋友。收下这些护腕吧，$N，这是你应得的!', '你有没有从祖尔格拉布取回我需要的权力珍宝?这些护腕值得你为之付出努力!', '', '去荆棘谷的尤亚姆巴岛找祖达萨的梅维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8057, '权力珍宝：占卜师护腕', '占卜师是我们部族的重要成员，聆听他们的教诲是你明智的选择。通过和动物交流以及在必要的时候把它们献给魂灵，他们将会给我们提供神圣的指引。在过去的岁月中，占卜师的洞察力和智慧帮助我们在和古拉巴什的战争中渡过了难关。$B$B从祖尔格拉布帮我带回权力珍宝来，证明你的价值。只要你带回那些东西，我就会给你赞达拉占卜师梦寐以求的护腕。', '从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友好或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。', '啊，我能感觉到这些权力珍宝释放的能量，$N。你是我们部族的朋友。按照我们的承诺，$N……占卜师护腕属于你了!', '你有没有从祖尔格拉布找到权力珍宝?这些护腕价值不菲呢，$N。相信我!', '', '去荆棘谷的尤亚姆巴岛找祖达萨的梅维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8058, '权力珍宝：辩护者护臂', '复仇便是力量。赞达拉辩护者拥有这样的力量。我们的部族有很多敌人，辩护者要让他们付出代价。对抗我们的愚蠢之人必将受到惩罚，辩护者就是施加惩罚的执行人。敌人害怕复仇，他们永远都会害怕你。$B$B充当起辩护者的角色吧。去祖尔格拉布寻找权力珍宝。杀死哈卡的爪牙，以部族的名义复仇。你会得到奖励的。', '从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱护臂。你还必须在赞达拉部族中达到友善或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。', '你的复仇行动已经成功了，你也因此而具备了辩护者的资格。你打败了血神哈卡的爪牙。$B$B收下这个吧。它会在今后的复仇行动中帮助你。现在，你是赞达拉部族的朋友了。', '你取回权力珍宝了吗?你以赞达拉的名义复仇了吗?', '', '去荆棘谷找尤亚姆巴岛的击碎者金罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8059, '权力珍宝：恶魔师裹带', '术士在和恶魔打交道的过程中冒着极大的危险，但是我们的恶魔师的研究更近一步。通过一个古老的魔法仪式，他们让恶魔进入他们的躯壳。他们从身体内部奴役了恶魔，而不是让恶魔占据他们，这些野兽的力量将永远被他们控制。这种技能只有少数人可以掌握。$B$B为了让你了解恶魔的力量，我必须获得祖尔格拉布的权力珍宝。去那里带回我们所需的东西。', '从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友善或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。', '干得好……显然他们在交出权力珍宝之前痛苦地挣扎了一番。拿着这个―恶魔师裹带。这是用恶魔祈祷中使用的强大魔精制作而成的，它将在你追求力量的过程中成为有用的工具。', '你有没有带回权力珍宝?如果你可以击败哈卡的恶魔仆从，那么你不仅向我们证明了自己的实力，而且还证明了你想要学习恶魔之道的意愿。', '', '去荆棘谷找尤亚姆巴岛的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8060, '权力珍宝：幻术师裹布', '法师在我们的部族中被称为幻术师。他们在咒术中使用了强大的魔精，能迷惑部族的敌人！$B$B<阿塔比姆顽皮地笑起来。>$B$B看到这样一名强大的幻术师全力以赴，击败敌人，真令人兴奋！$B$B如果你要了解幻术师的话，就去祖尔格拉布找回我需要的权力珍宝吧。如果你成功了，我就会送你一件织入幻术师法术的装备。', '从祖尔格拉布把以下权力珍宝带给全知者阿塔比姆：1条原始哈卡莱护腕。你还必须在赞达拉部族中达到友善或更高的声望。$B$B全知者阿塔比姆克在荆棘谷的尤亚姆巴岛上。', '太令人惊讶了……你能感觉到魔精的力量在这些珍宝中涌动吗?在古拉巴什帝国统治一切的时代，权力珍宝被作为流通货币。现在，赞达拉将利用珍宝中隐藏的魔精对抗哈卡的第二次崛起!$B$B你做得很好—你是赞达拉部族的朋友。依照我们的承诺，幻术师裹布是你的了!', '$N―你已经回来啦?你带回我需要的权力珍宝了吗?', '', '去荆棘谷找尤亚姆巴岛的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8061, '权力珍宝：忏悔者裹布', '我们赞达拉部族将权力授予那些能和神灵直接沟通的成员。我们的祭司不仅仅是治疗者，也是忏悔者。邪恶不但来自外部的威胁——比如哈卡，也来自部族内部。我们的忏悔者在此担起了法官的职责，避免我们被那股吞噬了古拉巴什帝国的邪恶力量所毁灭。$B$B我需要的权力珍宝就在祖尔格拉布中，去找到那些珍宝，了解忏悔者的职责和精神，保护我们免受邪恶的侵蚀。', '从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友善或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。', '太好了，$N!你能把这些带给我可真不容易。无疑，你今天成为了我们部族的忏悔者，你帮助我们化解了哈卡的威胁!', '你从祖尔格拉布回来了?你有没有成功地从哈卡的手下那里获得权力珍宝?', '', '去荆棘谷找尤亚姆巴岛的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8062, '权力珍宝：捕猎者护腕', '在古拉巴什帝国毁灭后的黑暗岁月里，赞达拉捕猎者凭借自己的能力维系着部族的生存。猎人跟我们部族的捕猎者很像——狩猎便是捕猎者的基本工作。你在祖尔格拉布的狩猎之旅将证明你有没有资格成为捕猎者中的一员。$B$B从祖尔格拉布取回权力珍宝吧，如果你成功了，那么你就会在成为捕猎者的生涯中迈出第一步。', '从祖尔格拉布把以下权力珍宝带给盲眼法希尔克：1条原始哈卡莱护腕。你还必须在赞达拉部族中达到友善或更高的声望。$B$B盲眼法希尔克在荆棘谷的尤亚姆巴岛上。', '嗯……我不用眼睛看也能感觉到权力珍宝的存在。你在祖尔格拉布取得的胜利令整个部族都很感动。我们不仅将你看作赞达拉的朋友，还认为你值得拥有捕猎者的护腕', '去祖尔格拉布，打败那些拥有权力珍宝的家伙，$N。他们是你的猎物，他们拥有我们需要的东西。', '', '去荆棘谷找尤亚姆巴岛的盲眼法希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8063, '权力珍宝：狂妄者护腕', '赞达拉狂妄者和盗贼很像，但是他们信奉疯狂……混乱……无可预见的存在。狂妄者在战场上是个巨大的威胁，他们在敌人中散播混乱和伤害的种子。$B$B从祖尔格拉布带回我需要的权力珍宝，我就会送你一件狂妄者护甲。拥抱疯狂吧！', '从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1条原始哈卡莱护腕。你还必须在赞达拉部族中达到友善或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。', '干得好，$N……你在祖尔格拉布取得了成功，赞达拉部族会从此将你视为朋友。现在我要实现对你的承诺，请收下这份奖励!', '去祖尔格拉布寻找那些发狂的家伙，用你自己的力量征服他们，$N!丰厚的奖励在等待着你，不要让哈卡占了上风!', '', '去荆棘谷找尤亚姆巴岛的盲眼法希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8064, '权力珍宝：占卜师腰带', '赞达拉部族不了解德鲁伊的行事之道。我们按照自己的需求塑造自然，而不是通过别的方式达到目标。当然，占卜师是我们当中与自然的关系最为和谐的。放弃一头小动物的灵魂是成为占卜师的重要步骤之一，那就是自然的真正力量。$B$B从祖尔格拉布帮我带回权力珍宝，向我们证明你的价值。只要你带回那些东西，我就会给你赞达拉占卜师使用的强大物品，一条腰带。$B$B非常强大！', '从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱腰带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。', '你成功地收集到了所需要的权力珍宝，$N;为此我们对你表示感谢。你向我们证明了你是值得赞达拉部族尊敬的$r。按照我们所承诺的，现在它是你的了!', '从祖尔格拉布带回我需要的权力珍宝了吗?只要你带来那些东西占卜师腰带就是你的了。', '', '去荆棘谷的尤亚姆巴岛找祖达萨的梅维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8065, '权力珍宝：占卜师外套', '衣着是占卜师力量的标志，$N。占卜师的外套象征了他们自己和他们所寻找的神圣智慧之间的联系。通常，外套中织入了用作祭品的小动物的部分肢体，这可以让他们时刻记着自己是如何获得强大的力量的。$B$B从祖尔格拉布帮我带回权力珍宝来，向我们证明你的价值。只要你带回那些东西，我就会给你一件包含占卜师真正力量的外套。', '从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱徽章。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。', '你成功地收集到了我需要的权力珍宝，$N……这真让我惊讶。你代表赞达拉部族在祖尔格拉布所施行的正义已经成为了传说。从此，你将为整个部族所崇敬。这是你的外套，强大的德鲁伊!', '从祖尔格拉布带回我需要的权力珍宝了吗?占卜师外套绝对值得你付出那些努力。', '', '去荆棘谷的尤亚姆巴岛找祖达萨的梅维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8066, '权力珍宝：捕猎者腰带', '捕猎者知道如何追踪猎物，而成功的捕猎者知道如何一击解决他的猎物。你必须掌握这两种技能才能在祖尔格拉布生存下来，才有可能具备赞达拉捕猎者的风采……$B$B从祖尔格拉布带回我需要的权力珍宝。我将抽取那些东西的力量，而你会得到赞达拉捕猎者腰带——这是笔好买卖，相信我。', '从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1条原始哈卡莱披肩。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。', '我刚才感觉到了你的存在，$N，但是你的行踪还是让人很难察觉。是你身上的权力珍宝曝露了你的行踪。我不用看见这些小饰物也能感到它们释放的能量;它们蕴含的魔精', '攻击祖尔格拉布那些愚蠢的哈卡爪牙―他们身上有权力珍宝，$N。宣告自己的胜利，向部族证明你的实力。', '', '去荆棘谷找尤亚姆巴岛的盲眼法希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8067, '权力珍宝：捕猎者衬肩', '赞达拉部族将衣着视为成就的象征。你无需观察别人的衣着，只需感觉它所散发的力量——力量超越视觉。赞达拉捕猎者的衣服正是如此，他们最珍视的莫过于衬肩了。衬肩能使他们的身形变得模糊……并可以随心所欲地显形。$B$B去祖尔格拉布取回我需要的权力珍宝，捕猎者衬肩就属于你了。', '从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1块原始哈卡莱盾牌。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。', '成功了……你将受到部族的崇拜，$N。找到披肩所需的权力珍宝并不容易，但是你以捕猎者的方式成功地做到了。你在这里赢得了一席之地，并且获得了穿上他们的披肩的权利。', '你在祖尔格拉布取得胜利了吗，$N?你只有带回我需要的权力珍宝，证明你对部族的价值，才能赢得赞达拉捕猎者披肩。', '', '去荆棘谷找尤亚姆巴岛的盲眼法希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8068, '权力珍宝：幻术师衬肩', '魔法是供强者随心所欲运用的原始力量。魔精便是这种力量的外延，我们以幻术的形式来操纵这种魔法。谁希望自己打败的敌人并非真实的存在呢？赞达拉部族了解这种魔法，幻术师在部族中倍受尊敬。$B$B从祖尔格拉布带回我需要的权力珍宝吧——如果你成功的话，你就将受到部族的尊敬，并获得幻术师所使用的衬肩！', '从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱披肩。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B全知者阿塔比姆克在荆棘谷的尤亚姆巴岛上。', '成功了!你从今后将得到整个部族的尊敬!祖尔格拉布的家伙们一定尝到了赞达拉的厉害，谢谢你，$N。$B$B带着部族的祝福，请收下赞达拉幻术师的披肩。愿它助你一臂之力。', '祖尔格拉布的情况如何?你利用幻术的力量打败敌人了吗?无论如何，他们都得死―从他们那儿取回的权力珍宝将会帮助我们打败哈卡。', '', '去荆棘谷找尤亚姆巴岛的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8069, '权力珍宝：幻术师长袍', '赞达拉部族通过衣着来识别着装者的身份和力量。我们的衣服都是用最好的材料织成的，其中还添加了魔精，这使得我们更加强大。幻术师也不例外，据说他们的长袍中含有自己的幻术精华。传说幻术师的长袍每时每刻都在变化。$B$B我会给你一件幻术师长袍，$N……但是你首先必须赢得部族的崇拜！从祖尔格拉布给我带回权力珍宝来！', '从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1块原始哈卡莱套索。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。', '终于有人配得上这件幻术师长袍了!你在祖尔格拉布取得了巨大的成功，赞达拉部族的成员将永远崇拜你。骄傲地穿上它吧，$N!', '你带回我们需要的权力珍宝了吗?我知道这并不容易……但是我早有预言，会有外来者帮助我们打败哈卡。你就是那个预言中的$r!', '', '去荆棘谷找尤亚姆巴岛的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8070, '权力珍宝：忏悔者腰带', '在古拉巴什帝国陷落之后，我们赞达拉部族几乎被一股来自部族内部的邪恶力量所击败。这个时候有一些忏悔者挺身而出，将那些对自己同胞下手的败类驱逐了出去。他们不仅让我们精神得到升华，而且还让我们保存了性命。$B$B去祖尔格拉布，亲眼见证哈卡的倒下，也顺便拜访一下古拉巴什帝国吧。从他们那里夺得我们所需的权力珍宝，在成功之后，你就将获得奖励！', '从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱腰带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。', '成功了!要对抗哈卡的复苏，我们还有很多事情要做。有了你的帮助，血神就无法将我们完全毁灭了。$B$B你今天赢得了部族的尊敬，$N。拿着这个 - 忏悔者束腕 - 这是我们对你的感谢。', '权力珍宝……你拿到它们了吗?只有当我们拥有了它们之后，才能使用那些储存在里面的强大能量。如果我们能对血神的仆从发起反攻，就再好不过了……', '', '去荆棘谷找尤亚姆巴岛的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8071, '权力珍宝：忏悔者衬肩', '赞达拉的忏悔者都穿着独特的护肩，这可以将他们标示为部族的保护者。这些护肩是用强大的魔精制作的，它会帮助那些为我们部族而战的勇士。作为一个牧师，你也需要这样一副护肩的庇护。$B$B进入祖尔格拉布，和哈卡的爪牙作战，然后把权力珍宝给我带回来，我会给你一副只有最优秀的忏悔者才能获得的护肩。', '从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1块原始哈卡莱之盾。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。', '干得好，$N - 哈卡的爪牙一定感觉到了赞达拉的复仇，感谢你。你已经赢得了部族永远的崇敬。请接受我们的祝福，并收下这件忏悔者披肩!', '你拿到祖尔格拉布的权力珍宝了吗?', '', '去荆棘谷找尤亚姆巴岛的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8072, '权力珍宝：狂妄者衬肩', '卡瓦萨尔是一位声名远播的赞达拉狂妄者。相传他首次对敌作战时穿着一件织入了“疯狂之纹”的特殊衬肩。他以极快的速度挥舞着两把匕首，全身都处于衬肩和匕首的双重保护之下，滴水不漏。今天，狂妄者把衬肩看作自己在整个部族中的地位的标志。$B$B把权力珍宝交给我，我就把衬肩送给你，它会令敌人闻风丧胆。', '从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1条原始哈卡莱束带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。', '胜利属于我们，谢谢你令我们的敌人发狂!赞达拉部族向你致敬，没有什么比狂妄者的披肩更能表达我们的谢意了!', '你回来了―你带来了我需要的权力珍宝了吗?$B$B卡瓦萨尔的传说告诉我们，无论敌人有多强大，他们都不是不可战胜的。混乱会使所有人屈服，这点是毫无疑问的……而混乱中那些最有序的因素也可能使所有人屈服。', '', '去荆棘谷找尤亚姆巴岛的盲眼法希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8073, '权力珍宝：狂妄者外套', '我的眼睛很早以前就瞎了，但是我一点也不怀念它们。在我们这样的部族中，衣饰代表了着装者的地位和意图，而最强大的衣服所蕴涵的力量不是用肉眼就能看出来的。赞达拉狂妄者外套也不例外，它蕴藏着可任你操控的混乱和疯狂之力。$B$B我需要的权力珍宝就在祖尔格拉布中，去找到那些珍宝，我会奖励你一件传说中的外套……适合狂妄者的外套。', '从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1块原始哈卡莱之盾。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。', '很出色……你做到了很多人无法做到的事情。你获得了部族永远的崇敬，$N。你获得了穿上狂妄者外套的权力 - 带着我们的祝福穿上它吧。', '欢迎回到尤亚姆巴岛，$N……你成功地取回权力珍宝了吗?', '', '去荆棘谷找野人海岸的盲眼法希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8074, '权力珍宝：预言者腰带', '预言者了解元素中蕴含的魔精，他们将其作为指引部族繁荣发展的工具。在古拉巴什帝国毁灭后的黑暗岁月里，他们将我们领回祖尔格拉布的山谷中。$B$B从祖尔格拉布把权力珍宝给我带回来，证明你的实力。如果你能做到的话，我会送你一条预言者使用的腰带——里面有强大的魔精！', '从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱束带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。', '我能嗅到你身上散发出击败恶魔的味道，$N。这味道真甜美老兄……我想你很熟悉这味道。$B$B我知道你能取得权力珍宝不是件简单的事。你的壮举不仅让部族倍感荣耀，也让你在整个部族中赢得尊敬。给你—拿着占兆师的腰带并穿上它吧!', '我需要的正是权力珍宝―在对祖尔格拉布的恶魔作战时，我们可以利用它的力量。你带来权力珍宝了吗?', '', '去荆棘谷的尤亚姆巴岛找祖达萨的梅维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8075, '权力珍宝：预言者外套', '赞达拉预言者都身着一件与众不同的外套。它是由最好的丝绸和布料织成的，其中还编入了坚韧的锁链。这不仅是神力的象征，也是权力的标志。跟那些用尽毕生精力与灵魂交谈的预言者唱反调绝不是明智之举……$B$B从祖尔格拉布找回我需要的权力珍宝，证明你的价值。如果你成功的话，我就送你一件预言者梦寐以求的外套！', '从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱徽章。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。', '我明白你历经千辛万苦才为我取回权力珍宝，$N。这不简单，老兄 - 打败一个像淤泥般盘踞在祖尔格拉布的恶魔 -', '权力珍宝是魔法的关键来源—占兆师炼衫中也蕴藏了这样的魔法。把我需要的东西交给我，我就送你一件赞达拉占兆师梦寐以求的炼衫。', '', '去荆棘谷的尤亚姆巴岛找祖达萨的梅维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8076, '权力珍宝：恶魔师衬肩', '恶魔师的目标是直接吸收所有的能量，而不是简单地占据它。我们的许多恶魔师都在和恶魔战斗的过程中失败了；我们的敌人——尤其是古拉巴什的敌人——在威胁着我们，因此在真正需要牺牲的时候，恶魔师的力量将会倾泻在敌人的头上。我们能否生访问决于能否摧毁那些想要毁灭我们的人；古拉巴什帝国的沦陷让我们学会了这些东西。$B$B去祖尔格拉布，拿回我们所需的权力珍宝。完成了这一任务之后，我们将会奖励你一件珍贵的东西。', '从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱腰带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。', '干得好，$N。祖尔格拉布的权利珍宝是一种废弃的力量的纪念。古拉巴什帝国十分强大，但是他们被自己强大的力量反噬了。恶魔师知道他们正在进行类似的游戏，但是\r\n释放能量将是生存所必需。$B$B穿上这件披肩吧，成为赞达拉部族尊敬的盟友……它将为你做出很大的贡献。', '你找到了祖尔格拉布中的权力珍宝?我们将从这些物品中抽取力量并为我们所用，如果你成功了，我们会给你应得的奖励……', '', '去荆棘谷找尤亚姆巴岛的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8077, '权力珍宝：恶魔师长袍', '力量的终极象征就是我们在战斗中穿着的服饰。恶魔师的长袍都是用优良的符文布和强大的魔精制作而成的。长袍的外表会让所有看到他的人感到恐惧……特别是那些恶魔师想要控制的恶魔。$B$B去祖尔格拉布找回我所需要的权力珍宝。这会非常困难……但是你的成功将会为你换来一件无以匹敌的长袍。', '从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1块原始哈卡莱套索。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。', '太好了―你在祖尔格拉布的胜利向我们，不，是向整个世界作出了保证，哈卡绝对无法为所欲为。你最终将要直接面对血神……你在赞达拉部族中也将获得极高的声望。$B$B哦，这件简单的长袍也能帮你一些忙。$B$B<阿塔比姆意味深长地对你眨了眨眼睛。>', '权力珍宝……你有没有找到它们?只有我们得到这些东西，你才能获得恶魔力量的终极象征，$N。', '', '去荆棘谷找尤亚姆巴岛的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8078, '权力珍宝：辩护者腰带', '祖尔格拉布将再次沐浴在仇恨的洗礼中。哈卡，这个摧毁了古拉巴什帝国的恶魔必须被消灭，无论我们付出多大代价也都在所不惜。现在的巨魔只不过是光芒消退后残存的阴影而已，这都是哈卡造成的！$B$B成为一名辩护者吧，去消灭恶魔的爪牙。祖尔格拉布将要尝到来自赞达拉的复仇。把权力珍宝交给我，我会给你一条辩护者腰带，让你拥有真实的力量。$B$B去吧。', '从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱束带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。', '你已经了解了辩护者之道。你令部族倍感荣耀。你为自己赢得了尊敬。你让敌人尝到了痛苦的滋味。$B$B辩护者腰带属于你了。你已经具备了成为辩护者的资格。', '你带回权力珍宝了吗?你打败部族的敌人了吗?必须让哈卡尝到辩护者的愤怒!', '', '去荆棘谷找尤亚姆巴岛的击碎者金罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8079, '权力珍宝：辩护者胸甲', '胸甲是辩护者力量的象征。它是由魔精制成的。只有那些受到部族崇敬的勇士才能拥有它，这是赞达拉复仇的象征。$B$B要成为辩护者，就必须复仇。从祖尔格拉布取回我们需要的权力珍宝，夺回被盗的魔精。哈卡的爪牙将为此付出代价，而你将因此获得辩护者胸甲。$B$B去吧。成为我们的复仇之神，$N。', '从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱套索。你还必须在赞达拉部族中达到崇敬或更高的声望。$B$B击碎者金罗克在荆棘谷的尤亚姆巴岛上。', '你将因此受到部族的崇敬。部族也会奖励它的英雄。祖尔格拉布已经尝到了来自赞达拉前所未有的复仇。$B$B你的英勇事迹将鼓舞后来的勇士，他们会将你视为力量的象征。他们会视你为复仇之神!', '你获胜了吗?你取回权力珍宝了吗?告诉我你的复仇经历!', '', '去荆棘谷找尤亚姆巴岛的击碎者金罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8080, '阿拉希盆地的资源！', '我们必须依靠我们的士兵进行战斗，所有的士兵都会这么告诉你的。他们还会告诉你，他们正在使用破烂不堪的装备，饥肠辘辘地开向战场！$B$B这就是阿拉希盆地显得非常重要的原因。金属，武器，食物，木材——所有我们所需要的东西都可以从那里获得。$B$B那就是我需要你发挥作用的地方，$N。进入阿拉希盆地，比敌人占据更多的基地，以此来获得战斗的胜利，然后给我带回一箱资源来。', '获得阿拉希盆地战斗的胜利，获取一只阿拉希资源箱，然后向避难谷地的玛克里尔中士复命。', '你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们配置给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。', '你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好干一仗……', '', '去阿拉希高地找避难谷地的玛克里尔中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8081, '更多的资源', '', '', '啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。', '虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。', '', '去找阿拉希高地的玛克里尔中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8102, '卡亚罗之石', '', '', '$C，这块坠饰上镶嵌的卡亚罗之石来自南海的卡亚罗山脉。卡亚罗山脉地带分布着许多活火山，那里的地质地形不断发生剧烈的变动。$B$B随着你与赞达拉巨魔的关系日益密切，卡亚罗之石的力量也会增强。利用这块石头的力量打败我们的敌人吧。就像卡亚罗山脉那样:迅速、致命、富有爆炸力……', '欢迎回来，$c。我能发现卡亚罗之石有了变化。很多敌人都栽在你那超凡的能力下了。他们罪有应得。是该让我提升石头的能力了。把它拿给我。', '', '去找荆棘谷的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8104, '卡亚罗的珠宝', '', '', '<阿塔比姆以你前所未见的强大力量击碎了石头。>$B$B看见了吗?卡亚罗之石便是我们所说的异质晶簇。石头中蕴藏中汲取了潜在能量的水晶，破开石头便能发挥最大潜能。用它来消灭我们的敌人吧。', '把坠饰给我吧，$N。我要给你看点东西。', '', '去找荆棘谷的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8107, '科赞的玷污', '', '', '请收下这块坠饰，$C。运用它的力量消灭我们共同的敌人。$B$B戴在你脖子上的坠饰蕴涵着一段历史。科赞原本是赞达拉帝国的领土。但是哥布尔的贸易大亨玷污了此地，将我的兄弟姐妹赶了出来。$B$B科赞现在是哥布尔主城幽坑城的属地;但是在科赞被玷污之前，它曾是一片伟大的土地。即使在今天，我们仍将科赞看作神圣的地方。', 'NULL', '', '去找荆棘谷的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8108, '科赞的玷污', '', '', '请收下这块坠饰，$C。运用它的力量消灭我们共同的敌人。$B$B戴在你脖子上的坠饰蕴涵着一段历史。科赞原本是赞达拉帝国的领土。但是哥布尔的贸易大亨玷污了此地，将我的兄弟姐妹赶了出来。$B$B科赞现在是哥布尔主城幽坑城的属地;但是在科赞被玷污之前，它曾是一片伟大的土地。即使在今天，我们仍将科赞看作神圣的地方。', 'NULL', '', '去找荆棘谷的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8109, '科赞的强力玷污', '', '', '剥去他们尸体上的鲜肉。看着黑暗的力量吞噬哈卡，从他们的恐惧中汲取力量，$C。让科赞的玷污再次强化……', '召唤恶魔，$C。让它们汲取玷污科赞的黑暗能量。指挥它们大开杀戒!$B$B是的……是时候对科赞的玷污进行最后一次强化了。把它给我吧。', '', '去找荆棘谷的全知者阿塔比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8111, '南海魔化海藻', '', '', '看到这些海藻了吗?它们产自南海。我们往其中添加了一点魔精和魔法，它就成为一件非常有用的饰品。$B$B你是个德鲁伊，这对你来说相当容易。把它戴在你的脖子上，想象一下大自然、松鼠或是所有你们会喜欢的东西。', 'NULL', '', '去荆棘谷找祖达萨的梅维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8112, '南海魔化海藻', '', '', '看到这些海藻了吗?它们产自南海。我们往其中添加了一点魔精和魔法，它就成为一件非常有用的饰品。$B$B你是个德鲁伊，这对你来说相当容易。把它戴在你的脖子上，想象一下大自然、松鼠或是所有你们会喜欢的东西。', 'NULL', '', '去荆棘谷找祖达萨的梅维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8113, '原始南海魔化海藻', '', '', '$N，旅途愉快。继续取哈卡和他的爪牙的性命吧。', '$N!好久不见。拉斯塔哈命令我为你的坠饰加入更多的魔精和魔法，这可是最后一次呢，你知道吗?真的!要不是亲眼所见，我怎么都无法相信呢。把坠饰放在这儿吧。', '', '去荆棘谷找祖达萨的梅维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8117, '巫毒幻象', '', '', '看看吧，$N。巫毒的力量更加强大了，不是吗?让原始的力量流遍你吧。', '啊哈!梅维基闹了一个笑话!$B$B<梅维基大笑。>$B$B这么说，你一直利用灵魂和元素的力量对抗那些藏在祖尔格拉布的敌人，是吗?这值得奖励!$B$B梅维基会磨亮你的宝珠的。把宝珠放在这儿，$N。', '', '去荆棘谷找祖达萨的梅维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8118, '巫毒幻象', '', '', '看看吧，$N。巫毒的力量更加强大了，不是吗?让原始的力量流遍你吧。', '啊哈!梅维基闹了一个笑话!$B$B<梅维基大笑。>$B$B这么说，你一直利用灵魂和元素的力量对抗那些藏在祖尔格拉布的敌人，是吗?这值得奖励!$B$B梅维基会磨亮你的宝珠的。把宝珠放在这儿，$N。', '', '去荆棘谷找祖达萨的梅维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8119, '完美巫毒幻象', '', '', '$N，终有一天你可以使用宝珠直接与我交流。一旦你结束了与哈卡的战争，梅维基就能重返家园。让我们呼唤那些强大的灵魂，让那一天早日到来吧。', '<梅维基指着你的坠饰。>$B$B看看它，$N!看起来象真的一样。灵魂在围绕着宝珠跳舞。$B$B把它交给梅维基吧，她会进行最后一次调整的。', '', '去荆棘谷找祖达萨的梅维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8124, '更多的资源', '', '', '啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。', '虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。', '', '去找阿拉希高地的亡灵哨兵莫提斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8142, '赞达拉暗影坠饰', '', '', '年轻人$C，你进步神速。或许是该让你加入塞拉利卡―赞达拉的精英组织了。数千年来，我们一直充当着赞达拉帝国的刺客，但是长期以来我们都很懒散松懈，这使得哈卡的力量不断扩张。当我们再次面对哈卡大军的时候，却没了巨魔同盟的支持。你和你的盟友必须帮助我们消灭血神和他的爪牙!$B$B带上这个坠饰，它会助你一臂之力的。', 'NULL', '', '去找荆棘谷的盲眼法希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8143, '赞达拉暗影坠饰', '', '', '年轻人$C，你进步神速。或许是该让你加入塞拉利卡―赞达拉的精英组织了。数千年来，我们一直充当着赞达拉帝国的刺客，但是长期以来我们都很懒散松懈，这使得哈卡的力量不断扩张。当我们再次面对哈卡大军的时候，却没了巨魔同盟的支持。你和你的盟友必须帮助我们消灭血神和他的爪牙!$B$B带上这个坠饰，它会助你一臂之力的。', 'NULL', '', '去找荆棘谷的盲眼法希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8144, '赞达拉暗影大师坠饰', '', '', '这是我们最后一次在塞拉利卡的庇护下进行交谈。你已经知道自己该做什么了。带上坠饰继续杀戮吧，绝不能让哈卡离开祖尔格拉布。', '$N，它渴望成长。坠饰已经吸取了祖尔格拉布上千具巨魔尸体的能量。把它给我吧，我会对它做最后一次强化。', '', '去找荆棘谷的盲眼法希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8146, '漩涡之藤', '', '', '在赞达拉，猎人是倍受尊崇的职业。最好的猎人都要转至漩涡边缘接受考验。$B$B他们从海洋中心采摘一种名为漩涡之藤的海藻，然后将其编织成坠饰。这种坠饰在附魔后可以提高猎人狩猎时的准确度和力度。$B$B现在，我将一串漩涡之藤编织成的坠饰交给你。随着你与赞达拉的关系日益密切，我还会进一步强化坠饰。', 'NULL', '', '去找荆棘谷的盲眼法希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8147, '漩涡之藤', '', '', '在赞达拉，猎人是倍受尊崇的职业。最好的猎人都要转至漩涡边缘接受考验。$B$B他们从海洋中心采摘一种名为漩涡之藤的海藻，然后将其编织成坠饰。这种坠饰在附魔后可以提高猎人狩猎时的准确度和力度。$B$B现在，我将一串漩涡之藤编织成的坠饰交给你。随着你与赞达拉的关系日益密切，我还会进一步强化坠饰。', 'NULL', '', '去找荆棘谷的盲眼法希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8148, '漩涡之怒', '', '', '年轻的$C，旅途才刚刚开始。或许有一天你会去大漩涡看看世界的中心。$B$B愿力量和坚韧与你同在!', '莫托尔替拉斯塔哈传话给你，$N。皇室对你全力剿灭哈卡军队的行为倍加赞赏。我会在坠饰中编入最后一根漩涡之藤的。把它给我吧。', '', '去找荆棘谷的盲眼法希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8149, '缅怀英雄', '在艾泽拉斯收获节上，我们对那些无私奉献英雄们表示感谢，他们中的一些甚至献出了自己的性命。联盟曾涌现出很多的英雄，但是没有谁的光芒能超越光明使者乌瑟尔。$B$B将这些祭品带到西瘟疫之地光明使者乌瑟尔的墓碑那儿，去表达我们的敬意吧。把祭品放在墓碑下，然后回到我们这儿来。收获节结束之前我会一直在这儿，别浪费时间了，出发吧。', '转至西瘟疫之地的光明使者乌瑟尔的墓碑，在墓碑前放下他的祭品。在收获节结束之前返回铁炉堡的瓦格纳·巨锤那儿。', '乌瑟是英雄中的英雄。我简直难以想象阿尔萨斯变节时他所承受的痛苦，阿尔萨斯是他最优秀的学生，他就像疼爱自己的儿子一样疼爱他。他尽了全力去阻止阿尔萨斯，他永远都是一个真正的圣骑士。乌瑟的战斗已经结束了，想想那些他曾经拯救过的人吧。$B$B谢谢你，$N。你向这位伟大的英雄献上了祭品，以此来纪念了他的精神和收获节的精神。', '你到达光明使者乌瑟的墓碑，放下他的祭品了吗?$B$B对经验并不丰富的冒险家来说，这是一次危险的旅程;沿着穿越希尔斯布莱德的河流向北进入瘟疫之地是一条相对安全的道路。河流从悔恨岭附近的湖泊发源，往西奔流进入群山，穿过寂静的坟墓……那儿到处都是天灾军团的爪牙。', '将祭品放在光明使者乌瑟尔的墓碑前', '去丹莫罗的铁炉堡大门找瓦格纳·巨锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8150, '缅怀英雄', '在艾泽拉斯收获节上，我们对那些无私奉献英雄们表示感谢，他们中的一些甚至献出了自己的性命。部落曾涌现出许多英雄，但是没有谁的光芒能超越格罗姆·地狱咆哮。$B$B将这些祭品带到灰谷屠魔峡谷中的格罗姆·地狱咆哮的墓碑那儿，去表达我们的敬意吧。把祭品放在墓碑下，然后回到我们这儿来。收获节结束之前我会一直在这儿，别浪费时间了，出发吧。', '转至灰谷屠魔峡谷的格罗姆·地狱咆哮的墓碑，在墓碑前放下他的祭品。在收获节结束之前返回奥格瑞玛的亚尼·纳沙克那儿。', '格罗姆的全名是格罗姆，这个名字的意思是“巨人之心”，他勇敢地与玛诺洛斯抗争。我想，在兽人受到诅咒之后，格罗姆与玛诺洛斯同归于尽的壮举是对此最好的诠释。他的牺牲―或者说是赎罪，为部落后来的发展奠定了基础。$B$B谢谢你，$N。你向这位伟大的英雄献上了祭品，纪念了他的精神和收获节的精神。', '你造访了格罗姆.地狱咆哮的纪念碑，放下他的祭品了吗?$B$B纪念碑的所在地仍然受到燃烧军团的污染。当你接近纪念碑时，一定要多加小心，不要太过冒险了。', '将祭品放在格罗姆·地狱咆哮的墓碑前', '去找奥格瑞玛的亚尼·纳沙克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8153, '苔蹄快步者的鹿角', '艾萨拉的苔蹄快步者那强劲有力的鹿角是它们发动进攻时的有效武器，可以造成不小的伤害。完好的、自然的鹿角是这种动物的精神和信心的标志。$B$B如果你持有这样的鹿角，你也将拥有同样的自信。$B$B猎杀苔蹄快步者，把完好的鹿角交给我。', '将一副完好的苔蹄快步者鹿角交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶。', '只有拥有敏锐视力和无比耐心的人才能得到它们。做得好。', '你找到鹿角了吗?', '', '去艾萨拉找破碎海岸的奥汀克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8154, '阿拉希盆地的资源！', '我们必须依靠我们的士兵进行战斗，所有的士兵都会这么告诉你的。他们还会告诉你，他们正在使用破烂不堪的装备，饥肠辘辘地开向战场！$B$B这就是阿拉希盆地显得非常重要的原因。金属，武器，食物，木材——所有我们所需要的东西都可以从那里获得。$B$B那就是我需要你发挥作用的地方，$N。进入阿拉希盆地，比敌人占据更多的基地，以此来获得战斗的胜利，然后给我带回一箱资源来。', '获得阿拉希盆地战斗的胜利，获取一只阿拉希资源箱，然后向避难谷地的玛克里尔中士复命。', '你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们配置给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。', '你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好打一仗……', '', '去阿拉希高地找避难谷地的玛克里尔中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8155, '阿拉希盆地的资源！', '我们必须依靠我们的士兵进行战斗，所有的士兵都会这么告诉你的。他们还会告诉你，他们正在使用破烂不堪的装备，饥肠辘辘地开向战场！$B$B这就是阿拉希盆地显得非常重要的原因。金属，武器，食物，木材——所有我们所需要的东西都可以从那里获得。$B$B那就是我需要你发挥作用的地方，$N。进入阿拉希盆地，比敌人占据更多的基地，以此来获得战斗的胜利，然后给我带回一箱资源来。', '获得阿拉希盆地战斗的胜利，获取一只阿拉希资源箱，然后向避难谷地的玛克里尔中士复命。', '你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们配置给我们的军队。$B$B谢谢你，$N。事实上，履行这样的任务将是赢得最终胜利的关键要素。', '你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好打一仗……', '', '去阿拉希高地找避难谷地的玛克里尔中士。', '', '', '', '');
