INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8157, '更多的资源', '', '', '啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。', '虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。', '', '去找阿拉希高地的玛克里尔中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8158, '更多的资源', '', '', '啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。', '虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。', '', '去找阿拉希高地的玛克里尔中士。', '', '', '', '');
