INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8183, '哈卡之心', '哈卡之心熊熊燃烧着。虽然夺魂者已经被击败，但是他邪恶的力量依然在被诅咒的躯体之中涌动。', '把哈卡之心交给尤亚姆巴岛上的莫托尔。', '啊，哈卡之心。这说明夺魂者已经被干掉了!我们的世界终于被拯救了!$B$B$N，你对于我们的贡献简直是再造之恩。你是这世界的英雄!', '$N，一种邪灵的臭味环绕着你。你是否已经被夺魂者诅咒了?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8184, '力量的证明', '', '', '好好使用它吧，$C，不要对那些哈卡的信徒心存任何怜悯!', '只要有合适的材料，赞札就能制造古老的巨魔附魔。$B$B首先你得从最强大的哈卡莱副官:金度和血领主那里夺来1个原始哈卡莱塑像。$B$B接下来是打孔的巫毒人偶。你可以在散落此地的垃圾堆中找到。看看霉运巫毒堆里面有没有。$B$B把这些物品都给我找来，我会为你制作一个强大的附魔!', '', '去找无眠者赞扎。', '', '', '', '');
