INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8192, '灵魂的安抚', '', '', '好好使用它吧，$C，不要对那些哈卡的信徒心存任何怜悯!', '只要有合适的材料，赞札就能制造古老的巨魔附魔。$B$B首先你得从最强大的哈卡莱副官:金度和血领主那里夺来1个原始哈卡莱塑像。$B$B接下来是打孔的巫毒人偶。你可以在散落此地的垃圾堆中找到。看看霉运巫毒堆里面有没有。$B$B把这些物品都给我找来，我会为你制作一个强大的附魔!', '', '去找无眠者赞扎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8193, '钓鱼大师', '', '', '如果你想要赢得钓鱼大师的称号，就赶快去钓鱼吧!我在这儿饥肠辘辘地站了好几个小时啦!快把上钩的鱼儿给我!', '今天下午2点到4点，我们会有一场比赛，看谁是最厉害的钓鱼达人!你只要能率先从荆棘谷海岸的特定水域中钓出40条可口鱼来，就能赢得钓鱼大师的称号!这些鱼群是很容易找到的，你只需留意水面的动静就可以啦!$B$B即使你不是第一个钓到40条鱼的参赛者，我的学徒也会按每5条一定价格的方式向你收购你钓到的鱼。$B$B啊呀，你还犹豫什么，可口鱼游得很快的!', '', '去找荆棘谷的林格·巴斯贝特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8194, '钓鱼学徒', '', '', '哈哈，皆大欢喜!', '虽然比赛冠军已经出来了，但是我仍然会以合理的价格收购你钓到的鱼。怎么样?', '', '去找荆棘谷的贾恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8195, '祖利安、拉扎什和哈卡莱硬币', '', '', '棒极了―这套硬币将进一步扩充我们的宝库……并用于抵抗血神哈卡崛起的邪恶势力。$N，你已经获得了荣誉勋章以及整个部族的感谢!', '我在寻找被称为部族硬币的权力珍宝。在过去，祖尔格拉布的居民们将它们作为流通货币使用，每一枚硬币都浸入了微量而强效的魔精。$B$B这些硬币分为9种。如果你有多馀的硬币，我可以按三枚硬币对应一枚荣誉勋章的价值跟你交换，然后你就可以用勋章跟林沃斯换取某些特殊的物品。', '', '去找荆棘谷的温卡萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8196, '芒果精华', '', '', '公平的交易，我的朋友―请接受部族的祝福，并尽情享受来自南海的甘甜水果吧!', '南海的许多岛屿上都生长着拥有强效精华的芒果树。吃下芒果的人在身体上和精神上都会有焕然一新的感觉。如果你没有吃过，那真是太可惜了!$B$B这岛上有足够的芒果，你可以用赞达拉荣誉勋章来跟我们交换。如果你想知道如何获得勋章，就去跟温卡萨谈谈。如果你有勋章的话，我们就立即交易吧!', '', '去找荆棘谷的商人林沃斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8201, '祭司的徽记', '这是真的。哈卡现在藏身在祖尔格拉布中，他正沐浴在我们的神的力量之下。被迷惑的高阶祭司们正将我们最神圣的能量传输给夺灵者，他的力量即将超过艾泽拉斯世界上所有的生物。我们必须阻止他！$B$B拿着这根神圣之索，将它穿过负责传输我们神的能量的高阶祭司们的徽记。$B$B当你完成了这一步之后，就回到我这里来。', '将神圣之索穿上5颗导魔师的徽记，然后把这一串徽记交给尤亚姆巴岛上的伊克萨尔。', '你拿到头颅了!你阻止了哈卡继续劫掠我们的神之力量，并削弱了哈卡!$B$B你做出了英雄般的壮举，$N。愿这些巨魔头颅的主人在他们的鲜血流尽之后得到宽恕。', '你拿到那些头颅了吗，$N?我们必须在哈卡获得更多力量前阻止他!', '', '去荆棘谷找尤亚姆巴岛的伊克萨尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8221, '稀有鱼类 - 基佛天使鱼', '', '', '*吱吱*$B$B基佛天使鱼鉴定完毕。$B$B现在你可以获得奖励了。$B$B*喀喀**嘶嘶*$B$B', '*吱吱**喀喀*$B$B我在帮钓鱼大师布鲁吉尔寻找世界上的各种稀有鱼类。如果你可以帮我找来一些基佛天使鱼，那么我就把这个很不错的奖励品送给你。$B$B*嘎嘎**吱吱*', '', '去找荆棘谷的钓鱼机器人5000型。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8222, '闪光的蝎血', '', '', '干得好，$N!非常感谢!我会用这种血来把所有廉价的垃圾变成闪光的财宝!$B$B这是你的奖券，再次感谢你!', '在我为马戏团工作的这段时间中，我学到了很多关于顾客的事情。以下是我的一些经验:顾客喜欢闪光的东西!不管它是什么东西―你甚至可以把一根椅脚拆掉然后使它发光，这样，每个孩子都会从很远的地方赶来要一根。$B$B因此，$N，我需要发光的蝎血。你可以在希利苏斯、燃烧平原或者诅咒之地找到它。', '', '去找亚布·尼比盖尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8223, '更多闪光的蝎血', '', '', '再次感谢你，$N。这是给你的奖券!', '发光的蝎血非常不错，$N!只需要一些闪烁的光芒就可以把一件原本一文不值的垃圾变成价格高昂的商品。所有人都喜欢这样的东西，你不这样认为吗……$B$B你帮我了大忙，$N，虽然不需要更多的发光的蝎血，但是如果你能继续提供给我的话，我将继续给你奖券。', '', '去找亚布·尼比盖尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8224, '稀有鱼类 - 迪森皇后鱼', '', '', '*吱吱*$B$B迪森皇后鱼鉴定完毕。$B$B现在你可以获得奖励了。$B$B*喀喀**嘶嘶*$B$B', '*吱吱**喀喀*$B$B我在帮钓鱼大师布鲁吉尔寻找世界上的各种稀有鱼类。如果你可以帮我找来一些迪森皇后鱼，那么我就把这个很不错的奖励品送给你。$B$B*嘎嘎**吱吱*', '', '去找荆棘谷的钓鱼机器人5000型。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8225, '稀有鱼类 - 布隆奈尔蓝斑鱼', '', '', '*吱吱*$B$B布隆奈尔蓝斑鱼鉴定完毕。$B$B现在你可以获得奖励了。$B$B*喀喀**嘶嘶*$B$B', '*吱吱**喀喀*$B$B我在帮钓鱼大师布鲁吉尔寻找世界上的各种稀有鱼类。如果你可以帮我找来一些布隆奈尔蓝斑鱼，那么我就把这个很不错的奖励品送给你。$B$B*嘎嘎**吱吱*', '', '去找荆棘谷的钓鱼机器人5000型。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8227, '纳特的卷尺', '在散落的鱼饵和滚轴之中是一卷光滑的测量卷尺。卷尺上的标签写着：$B$B“纳特·帕格，尘泥沼泽。”', '将纳特的卷尺交给尘泥沼泽的纳特·帕格。', '啊，你居然找到我最喜欢的卷尺了!我爱这个卷尺!我用它测量过我钓到的最大的鱼……$B$B但是，我是在祖尔格拉布遗失卷尺的……这么说你去过祖尔格拉布了?你有没有看到传说中的加兹兰卡?$B$B好吧……你想抓到他吗?', '你好，$g小朋友:小姑娘;。你是来钓鱼的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8231, '碎浪多头怪', '碎浪多头怪是一种生活在艾萨拉的海陆两栖生物。它们拥有强大的力量和顽强的生命力。$B$B碎浪多头怪身上的坚硬光滑的鳞片是猎人实力的证明。$B$B猎杀艾萨拉沿岸的碎浪多头怪，给我带回它们的鳞片作为证明吧。', '将6块碎浪多头怪的鳞片交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶部。', '碎浪多头蛇很难对付，在水生环境下跟它们作战更是困难重重。$B$B你证明了自己的实力，你已经具备了猎杀更可怕的生物的能力。', '你成功了吗?', '', '去艾萨拉找破碎海岸的奥汀克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8232, '神庙中的绿龙', '我要交给你一项危险的狩猎任务：杀死绿龙摩弗拉斯，把它的牙齿带回来给我。摩弗拉斯居住在悲伤沼泽的阿塔哈卡神庙深处。$B$B如果你想要打败它的话，就必须叫上你的伙伴同去。这条绿龙是很多人共同的敌人——去寻找那些志同道合的盟友吧。$B$B绿龙的牙齿是猎人实力的证明。将牙齿交给我，你会在狩猎中得到成长。', '将摩弗拉斯的牙齿交给艾萨拉的奥汀克。他住在埃达拉斯废墟东北部悬崖的顶端。', '你已经学会了猎人那古老的狩猎方法，$N;我会送你一样我猎手生涯中的战利品。', '在你双眼我看到了智慧，$N。你狩猎结束了吗?', '', '去艾萨拉找破碎海岸的奥汀克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8234, '密封的蓝袋子', '事分轻重缓急。我丢了一个蓝色的小袋子，里面的东西很私密。$B$B但是，你不用追踪那些小偷啦，因为他们已经死了。我所知道的是，那些傻瓜费了九牛二虎之力也没能打开包裹，因此他们将包裹作为“神圣的器物”卖给了艾萨拉的木喉萨满祭司。这些家伙很聪明。$B$B我想让你转至艾萨拉，从萨满祭司那儿凭借智慧取回包裹……当然你也可以凭借武力。我认为第一种方法比较保险。一旦你成功了，就把包裹交给大法师克希雷姆。', '从艾萨拉的木喉萨满祭司那儿取回密封的蓝袋子，将它交给艾萨拉的大法师克希雷姆。', '你有拉文霍德领主的包裹。你怎么不早说，$G小伙子:姑娘;?', '我认识你吗?', '', '去艾萨拉找在熊头的大法师克希雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8235, '密文碎片', '拉文霍德公爵想让我们俩帮他个忙。他希望解除施加在这只袋子上的魔法。$B$B不幸的是，我的那些关于驱散魔法的书籍被一些暴徒夺走并销毁了，但书籍残存的碎片对我来说仍有利用价值。如果你能给我找来至少10块密文碎片，我就能将它们还原。你可以去杀一些森林软泥怪试试。它们通常什么东西都捡……你可以在艾萨拉的东北部找到森林软泥怪。', '将10块密文碎片交给艾萨拉的大法师克希雷姆。', '看起来你找到了某些保存较为完好的碎片。或许你也不是那么没用。', '你找到够多碎片让我继续我的工作了吗?', '', '去艾萨拉找在熊头的大法师克希雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8236, '碧蓝钥匙', '要解读这些碎片并删除魔化效果需要一点时间。当我完成这个工作后，我会亲自将袋子交给拉文霍德公爵。$B$B眼下的问题是钥匙，据说钥匙在绿龙摩弗拉斯手中，而摩弗拉斯则居住在阿塔哈卡神庙的深处，就是那个泡在悲伤沼泽里的神庙。$B$B叫上你的朋友，转至绿龙的巢穴吧。拉文霍德公爵在等你取回钥匙呢。', '将碧蓝钥匙交给乔拉齐·拉文霍德公爵。', '钥匙!我还以为我会永远失去它。请收下这件附魔衣服吧―这些是为那些拥有非凡技能和忠诚的盗贼准备的。$N可不是等闲之辈!$B$B<乔拉齐打开包裹，里面金光闪闪。他睁大了双眼，凝视着眼前的一切……>', '我已经收到了大法师克希雷姆送来的包裹，你找到钥匙了吗?', '', '去希尔斯布莱德丘陵找拉文霍德庄园的乔拉齐·拉文霍德公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8238, '古拉巴什、邪枝和枯木硬币', '', '', '棒极了―这套硬币将进一步扩充我们的宝库……并用于抵抗血神哈卡崛起的邪恶势力。$N，你已经获得了荣誉勋章以及整个部族的感谢!', '我在寻找被称为部族硬币的权力珍宝。在过去，祖尔格拉布的居民们将它们作为流通货币使用，每一枚硬币都浸入了微量而强效的魔精。$B$B这些硬币分为9种。如果你有多馀的硬币，我可以按3枚硬币对应一枚荣誉勋章的价格跟你交换，然后你就可以用勋章去跟林沃斯换取某些特殊的物品了。', '', '去找荆棘谷的温卡萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8239, '沙怒、碎颅和血顶硬币', '', '', '棒极了―这套硬币将进一步扩充我们的宝库……并用于抵抗血神哈卡崛起的邪恶势力。$N，你已经获得了荣誉勋章以及整个部族的感谢!', '我在寻找被称为部族硬币的权力珍宝。在过去，祖尔格拉布的居民们将它们作为流通货币使用，每一枚硬币都浸入了微量而强效的魔精。$B$B这些硬币分为9种。如果你有多馀的硬币，我可以按3枚硬币对应一枚荣誉勋章的价格跟你交换，然后你就可以用勋章去跟林沃斯换取某些特殊的物品了。', '', '去找荆棘谷的温卡萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8240, '赞扎的宝石', '销毁哈卡莱宝石对我们来说至关重要，我们甚至欢迎氏族之外的人帮助我们摧毁哈卡莱宝石！$B$B将你在祖尔格拉布找到的宝石带往赞扎祭坛进行销毁。我会送你一枚额外的部族荣誉勋章，仅此一次，下不为例；这东西可不是轻易就能获得的。$B$B愿赞扎的祝福与你同在！', '将你在祖尔格拉布找到的哈卡莱宝石带往尤亚姆巴岛的赞扎祭坛进行销毁，然后跟祭坛旁边的温卡萨谈一谈。', '棒极了……每当我们从血神的爪牙那儿夺得一块宝石，离彻底消灭他们就更近了一步。你高尚的行为为赞达拉以及你本人赢得了无上的荣誉。$B$B记住，$N，你可以继续利用祭坛摧毁在祖尔格拉布找到的宝石。每摧毁一块，你将获得1枚荣誉勋章!要是你还没有获得荣誉勋章，记得在背包中多留些空位。', '你在赞札祭坛摧毁宝石了吗?要是你成功的话，你会收到赞札的双倍祝福!', '', '去荆棘谷找尤亚姆巴岛的温卡萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8241, '炽热助熔剂的补给：铁锭', '', '', '炽热助熔剂的数量总是不够。继续收集吧……除非我叫你停止。', '我没时间跟你扯东扯西的，$r。现在是补充我们日益减少的炽热助熔剂储备的时候了。$B$B我需要的物品有:$B$B*熏火龙的鳞片。$B$B*铁锭。$B$B*煤块。$B$B凡是你能给我的，我都要!$B$B如果你想要跟兄弟会搞好关系的话，就最好快点去找。', '', '去找灼热峡谷的大铁匠博恩奈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8242, '炽热助熔剂的补给：重皮', '', '', '炽热助熔剂的数量总是不够。继续收集吧……除非我叫你停止。', '我没时间跟你扯东扯西的，$r。现在是补充我们日益减少的炽热助熔剂储备的时候了。$B$B我需要的物品有:$B$B*熏火龙的鳞片。$B$B*重皮。$B$B*煤块。$B$B凡是你能给我的，我都要!$B$B如果你想要跟兄弟会搞好关系的话，就最好快点去找。', '', '去找灼热峡谷的大铁匠博恩奈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8243, '赞扎的饮料', '', '', '公平的交易，我的朋友―请接受赞札的祝福和我们的赞赏吧!', '随着你在部族中的声望不断提高，你可以购买到更多的强效饮料。你要知道……这些饮料含有很强的魔精—并且被赞达拉部族所钟爱，它特别适合那些到处冒险的旅行者!$B$B我可以让你从这三件中选择一个;不过作为交换，我需要赞达拉荣誉勋章。你要知道，同一时间内，你身上只可以有一种精神效果。$B$B当你准备好进行交换的时候，就来找我吧!', '', '去找荆棘谷的商人林沃斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8246, '赞达拉的徽记', '', '', '公平的交易，我的朋友―请收下部族的祝福和你的徽记吧!', '$N，当你在赞达拉部族中的声望达到了崇拜之后，我有一些特别的东西要给你。这来自于我们在南海的家园……赞达拉的徽记!这些徽记可以用于加强你所拥有的任何护肩。如果你在寻求力量，魔精或者平静……那么我有你所需要的一切!$B$B我需要十五块赞达拉荣誉勋章才会给你一枚徽记。如果你拥有了足够的勋章，那么就来找我吧!', '', '去找荆棘谷的商人林沃斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8249, '垃圾箱', '', '', '愿这些飞刀能飞到别人的心脏里。$B$B我是说真的。', '我们的盗贼需要练习开锁技能，因此我需要有足够挑战性的上锁的箱子―不过我们手头上的箱子难度太低，只适合那些初学者们练手。$B$B如果你能给我5个重垃圾箱，我就送你一把品质极佳的飞刀。$B$B你可以打开箱子，取出里面的东西，但是至少你得留下一点硬币……即使对训练中的盗贼来说，他们也需要动力的。', '', '去找奥特兰克山脉的法拉德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8251, '魔法的尘埃', '艾萨拉的血精灵正在寻求一种碾磨他们获得的魔法物品的方法，通过这种方法所获得的粉末与普通的分解法术所获得的材料是不同的。$B$B当我派我的学徒去交换这种粉末的时候，血精灵们毫不犹豫地把他干掉了。因此，他们必须付出代价。$B$B谈判结束，$N。找到艾萨拉北部的这些血精灵，然后使用更具“说服力”的方法来获得他们的那些闪光尘埃。', '为大法师克希雷姆收集10份闪光尘埃。', '干得好，$N!秘法飞弹的说服能力总能让我感到惊叹。', '你找到粉末了吗?', '', '去艾萨拉找在熊头的大法师克希雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8252, '纳迦的珊瑚', '看看你的四周吧。遗迹和海岸被恶鞭纳迦所占据了。最近，它们开始熟悉这块土地，并开始接触产于艾萨拉的稀有材料。$B$B我说的就是魔化珊瑚——不知道为什么，恶鞭纳迦也盯上了它。海湾中的珊瑚已经所剩无几了，但是它们对于我的研究工作来说是至关重要的。我需要你去从恶鞭海妖那里抢回一些魔化珊瑚，然后把它们带给我。', '收集6块魔化珊瑚，然后把它们交给大法师克希雷姆。', '这是一种非常棒的珊瑚，$N。你的技术无疑非常出众。$B$B不要认为你的所做所为不会受到关注。也许你值得进行一次真正的技术试炼……', '恶鞭海妖是非常强大的法师。我想，他们不及你强大吧?', '', '去艾萨拉找在熊头的大法师克希雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8253, '毁灭摩弗拉斯', '在沉没的阿塔哈卡神庙深处，有一条名叫摩弗拉斯的绿龙。$B$B数年前我受到他的袭击，在我组织起有效的防御之前，他就把我的学徒整个吞了下去。虽然死掉个把学徒对我来说不是很严重的事情，但他身上有一块巨大的、拥有极强能量的奥术碎片。$B$B你必须召集队友，共同深入神庙。去杀死摩弗拉斯，从这家伙的胃中取出我的奥术碎片来。', '从摩弗拉斯身上取回奥术碎片，然后返回大法师克希雷姆那儿。', '难以置信。数年来，裂片吸收了绿龙的能量，变得更加强大。$B$B现在我对你没什么要求啦。有了这块裂片，我将再次拥有铸造秘法的能力。我铸造的第一件物品是给你的，$N，你得选择……', '你杀死了我的敌人吗?', '', '去艾萨拉找在熊头的大法师克希雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8255, '苔蹄快步者', '艾萨拉的苔蹄快步者是一种曾经居住在费伍德森林的生物，它们对疾病和毒药免疫，因此没有被那里的堕落力量所感染。在它们与生俱来的智慧的指引下，苔蹄快步者简单地选择了离开。$B$B虽然我感到非常遗憾，但是我希望你能帮助我去猎捕这些强大的野兽。收集四份健康的野鹿腺体，这是净化药膏的第一种成分——我们会利用净化药膏来治疗费伍德森林。', '收集4份健康的野鹿腺体，把它们交给艾萨拉的奥汀克。奥汀克住在埃达拉斯废墟东北部悬崖的顶部。', '神圣的道路引导你来到我们身边，$N。你的信仰与制作药膏的任务并不冲突。$B$B你看，对塞纳里奥议会来说苔蹄快步者是神圣的生物，无论以何种理由猎杀它们都能杀杀它们的威风。', '你回来了。你成功了没?', '', '去艾萨拉找破碎海岸的奥汀克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8256, '亡灵的腐液', '制作净化药膏所需的配方极其简单：一份有毒的药剂，两份治疗药剂。你已经获得了一份治疗药剂，那么你得收集一份毒药。$B$B埃达拉斯废墟附近徘徊的上层精灵充满了邪恶的力量，它们经常会生出一些令人作呕的绿色粘液。这种东西被称为亡灵腐液。$B$B这种东西的邪恶力量非常强大，因此我只需要你带给我一份亡灵腐液就行了。', '为艾萨拉的奥汀克带回一份亡灵腐液。奥汀克住在埃达拉斯废墟东北部悬崖的顶端。', '获得这样一种邪恶的物质，我并没有感到愉快，但是这东西是必要的。谢谢你，$N。', '我们必须迅速获得腐液。你找到它了吗?', '', '去艾萨拉找破碎海岸的奥汀克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8257, '摩弗拉斯之血', '药剂的最后一种成分就是我以前说的第二种治疗药剂。$B$B据说绿龙摩弗拉斯对任何形式的毒药和疾病都免疫——这是无数德鲁伊用生命换来的信息。毫无疑问，他的血液符合我们的要求。$B$B在你收集最后一种成分时，塞纳里奥议会的一名信使将带走你已经收集到的成分。召集你的伙伴，转至沉没的阿塔哈卡神庙中的绿龙巢穴吧。将他的血液交给费伍德森林中的格雷塔·苔蹄。', '转至沉没的阿塔哈卡神庙，杀死绿龙摩弗拉斯，将他的血液交给费伍德森林中的格雷塔·苔蹄。沉没的神庙的入口就在悲伤沼泽中。', '你已经杀死了摩弗拉斯，并且将他的血液带给了我们……这消息真令人难以置信!$B$B我们得立即将这些成分组合到一起，开始治疗费伍德森林的植被和生物。要使这儿恢复原貌得花去一生的时间，但是$N，你给了我们一件强大的武器，帮助我们与污染抗争。', '你把摩弗拉斯的血液带来了吗?', '', '去费伍德森林找翡翠圣地的格雷塔·苔蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8258, '达克雷尔的威胁', '死亡骑士达克雷尔主宰了通灵学院的尸骨储藏所。他威胁要扭曲整个灵魂国度来达到他自己的目的，我们必须阻止他！这就是水晶球可以帮助你的地方。$B$B在尸骨储藏所地下室的中心使用预言水晶球，以此来召唤达克雷尔的爪牙。击败这些爪牙，接下来死亡骑士就会出现了。$N，把他的徽记带给我！只有他的死亡才可以将灵魂国度的局势扭转过来！', '在通灵学院地下室的尸骨储藏所的中心使用预言水晶球，然后与被召唤出来的幽灵作战。击败这些幽灵之后，死亡骑士达克雷尔才会出现，你的任务就是击败他。$B$B把死亡骑士达克雷尔的徽记交给奥格瑞玛智慧谷的萨格尼。', '这是一个值得庆祝的胜利，$N!死亡骑士达克雷尔的毁灭将会恢复脆弱的灵魂国度。$B$B你已经很好地完成了任务，即使在没有奖励或者补偿的情况下，你也认真地作出了努力并获得了成功。你是一个有价值的萨满，我的朋友。$B$B我知道你拯救灵魂国度的行动所需要的只是感谢，但是请你把这份礼物和我的感谢一起收下。', '时间非常紧迫，$N―你有没有成功解除死亡骑士达克雷尔的威胁?', '', '去找奥格瑞玛的萨格尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8277, '沙漠中的剧毒', '比提克斯·斯巴格为你效劳！我的堂兄诺格在为塞纳里奥要塞的炼金师进行稀有草药的采集工作，好吧，至少以前他在这么做。在他最后一次回来的时候，他的血液中带着一种强力毒液。$B$B我已经设法减缓毒性发作的时间，但是如果想要完全中和它的话，我就需要这种毒液的原始样本。$B$B诺格是从北面回来的，因此我想应该是石鞭蝎或者掠沙蜘蛛干的。带给我一些尖刺和毒牙，然后我就可以制作解毒剂了。', '希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你带8个石鞭蝎之刺和8个掠沙蜘蛛的牙齿给他。', '祈祷吧，朋友!希望我们能拯救诺格!', '你完成了样本收集工作吗?拯救诺格刻不容缓!', '', '去希利苏斯找塞纳里奥要塞的比提克斯·斯巴格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8278, '诺格的最后一线希望', '该死的！解毒剂没有生效。诺格一定是被南边的某种毒性更强的生物蜇了。$B$B我需要你去那里给我带回更多的样品，$N。好消息是因为它们的毒性够强，所以我需要的样品数量不用那么多。坏消息是南部各种有毒生物的种类更多，因此我需要各种各样的样品。', '希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你给他带去3个石鞭巨钳蝎之刺、3个石鞭掠夺者之刺和3个石行蜘蛛的牙齿。', '太好了!看来起效果了，诺格正在恢复。我们欠你个大大的人情!', '这是我们最后一次救诺格的机会!快!', '', '去希利苏斯找塞纳里奥要塞的比提克斯·斯巴格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8279, '暮光词典', '暮光之锤对于敢于侵犯他们的人绝不会手软。他们把我当作野兽一样进行猎捕。不用说，他们的敌人就是我的朋友！$B$B要破译这块石板上的文字，我需要用他们的文字撰写的书籍来破译这些秘密的信息——我需要暮光词典。这么重要的工具被他们分成三章，放在了不同的地方！掌管它们的人被称为暮光守护者，去暮光之锤营地找到他们吧。', '把暮光词典的三个章节交给希利苏斯的隐士奥泰尔。', '对!就是这几个部分!让我们开始吧，$N。$B$B第三章中每三个字进行一下交换……或者第一章中每两个字进行一下交换……等等，是不是应该恰好相反?', '是谁啊?喔，是你!你找到所有的词典章篇了吗?', '', '去找希利苏斯的隐士奥泰尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8280, '保护补给线', '塞纳里奥要塞具有相当重要的战略意义。我确信只要我们可以控制住它，那么我们对于异种虫类的胜利必定会实现。另外我们还需要保证我们的物资补给可以及时到位。$B$B对于我们的补给商队来说，遍地都是的沙虫比异种虫类威胁还要大。就在今天早上，一大批晨光麦被掘泥打击者袭击并全部损失；我需要你去减少它们的数量，以此来保证我们的物资流通顺畅。', '希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死15只掘泥打击者。', '你赢得了我最诚挚的敬意。你对于塞纳里奥城堡的帮助显示了你真正的勇气。', '掘泥打击者是一个很严重的威胁，必须马上解决他们!', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8281, '确保安全', '迄今为止，你的表现很好地证明了你的实力，$N。然而，我们的补给线还没有完全安全。在解决了掘泥打击者的问题之后，他们南部的亲戚会占据他们留下的空缺。$B$B你需要击杀一些掘泥摧毁者，让它们不敢轻易越雷池一步，我们绝不能视我们的补给线安全为儿戏。', '希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死20只掘泥摧毁者。', '太好了!你已经证明了自己的实力，在和异种虫类作战的过程中，你无疑是个有价值的盟友。', '掘泥打击者是一个很严重的威胁，必须立即将他们解决!', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8282, '诺格的背包', '我在哪里？我的包在哪里？*气喘吁吁*我一定是在逃脱那只巨蝎“死亡弯钩”的时候把它给弄丢了。我在逃命的时候匆匆忙忙就跑进了一个石鞭掠夺者的巢穴。$B$B那个包里有各种各样的稀有材料。没有了它们，我和比提克斯就没有办法制造塞纳里奥要塞所需要的药剂了。我现在太虚弱，已经没有办法爬起来了，但是如果你可以把我的材料拿回来，那么我就可以帮你制作这些药剂。$B$B我是在南边山中碰到死亡弯钩的，就在铜须营地的后面。', '从希利苏斯南部山中找到诺格的背包，然后将它交给塞纳里奥要塞中的诺格。', '太好了!你找回我的背袋了。所有的稀有材料都在这里!我欠你很大一个人情。', '还没找到我的包包吗?不过我已经很幸运了，至少毒药已经被净化过。', '', '去希利苏斯找塞纳里奥要塞的诺格·斯巴格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8283, '通缉：死亡弯钩', '我们相信，可怕的蝎子“死亡弯钩”正在南面的山脉一带活动。对南边的巡逻士兵和远征军而言，她是个极大的威胁。谁能杀掉这个祸害，就将获得价值不菲的奖励。你可以向塞纳里奥要塞了望塔的卫兵队长维斯·库鲁兹询问奖励事宜。', '将死亡弯钩的蝎钳交给卫兵队长维斯·库鲁兹。', '太棒了!死亡弯钩一死，我们就能利用南部山脉的地势，智取异种虫巢。感谢你为此做出的努力。', '我需要那个生物的刺针做为证据。没有刺针，没有奖励。', '', '去希利苏斯找塞纳里奥要塞的维斯·库鲁兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8284, '暮光的秘密', '暮光之锤教徒曾在西北方进行发展。如果你现在去那里，还会发现那个区域到处都是元素生物，四周散落着的木头碎片和帆布可以帮你找到营地所在的地点。$B$B我从那里找回了一些粘土石板碎片，但是数量还不足以拼成有用的东西。如果你可以帮我找到其它的石板碎片，我们也许可以找到暮光之锤出现在希利苏斯的原因。', '希利苏斯塞纳里奥要塞的地质学家拉克斯班要你去收集8块暮光石板碎片。', '就和我怀疑的一样。我可以解译出石板上的所有文字，但是这些文字之间没有任何逻辑关系或者含义。现在还不知道暮光之锤究竟用了什么样的密码来掩盖这些文字的含义……我们必须找到一些更加了解这方面资讯的人。', '那个荒芜的营地就在这里的西北方。拿到所有的碎片后再回来。', '', '去希利苏斯找塞纳里奥要塞的地质学家拉克斯班。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8285, '沙漠隐士', '传说有一个前暮光之锤成员奥泰尔离开了这个团体，听说他现在隐居在南风村。也许你可以在那里寻求关于破译这块石板的帮助。$B$B带上这块拼好的石板，找到奥泰尔吧。', '把复原的石板带给希利苏斯的隐士奥泰尔。', '看来你对我以前所属的组织十分熟悉，你一定是塞纳里奥议会派来的。$B$B你想要找到对抗暮光之锤的资讯?过来，也许我们可以互帮互助。', '你!你怎么找到我的?你是谁?没人跟着你来吧，有吗?说话!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8286, '明天的希望', '当他出现时，我已经奄奄一息，濒临死亡。他对着我受伤的身体呼了一口气，便耐心地等待着时间的沙砾清理我的伤口。$B$B他说，“如果必须这样的话，你将永远活下去。”这样，我成为了一名守望者。$B$B看那片沙漠，第二场战争就要来临了。你必须找到青铜龙的栖身之所。去时光之穴看看主人回来了没有。我必须确认这一点才能有所行动。', '转至塔纳利斯的时光之穴寻找诺兹多姆的子嗣，阿纳克洛斯。$B$B完成任务后回到希利苏斯塞纳里奥要塞的流沙守望者巴里斯托尔斯那儿。', '我担心的事情还是发生了。新的危机已经来临。我的守护工作结束了……', '安纳克罗斯回来了吗?', '找到诺兹多姆的子嗣。', '去希利苏斯找塞纳里奥要塞的流沙守望者巴里斯托尔斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8287, '摆脱困境', '嗯，是这样的……我这里有相当有用的信息！我看到塞纳里奥议会的人来到了希利苏斯。他们计划把暮光之锤赶出这个地区，是不是？这很好；$B$B把这块羊皮纸袋给他们的领袖，指挥官玛尔利斯。不久之后暮光之锤就会被消灭，然后我就将永远脱离他们的魔爪！', '把解密石板碑文交给指挥官玛尔利斯。', '这确实是非常有趣的资讯，$N。它说明了暮光之锤出现在希利苏斯的部分原因，无疑这将帮助我们更好地和他们进行战斗。你的努力将获得丰厚的回报，$C。', '你带给我的是什么，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8288, '唯一的领袖', '不能再浪费时间了！我们必须找到一位英雄！完成任务需要一支军队，但是必须有一位真正的勇士担负起统帅整个盟军的重任。$B$B黑石之王的巢穴中有一头异常凶猛的野兽：勒什雷尔。他守护着征战大厅，阻止外人进入奈法利安的圣所。杀死那个邪恶的家伙，把它的徽记带给我，然后你就可以开始下一步的旅程了。', '到黑石山中的奈法利安巢穴去，杀死勒什雷尔，并带回它的徽记。$B$B将勒什雷尔的徽记交给希利苏斯塞纳里奥要塞的流沙守望者巴里斯托尔斯。', '你就是千年以来首位赢得青铜龙青睐的凡人吗?', '你必须赢得诺兹多姆的子嗣的好感。', '', '去希利苏斯找塞纳里奥要塞的流沙守望者巴里斯托尔斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8294, '镇压银翼部队', '灰谷森林将在强大的部落面前屈服，$r。无论暗夜精灵们说什么做什么，都无法阻止我们的推进。卡利姆多属于部落，谁敢阻止我们拿取属于我们的东西，谁就要死！$B$B让你的心中充满荣耀之光，让那些胆敢阻止我们的敌人一个个倒下。摧毁银翼要塞中的哨兵部队，并拿到一枚战歌荣誉奖章。把这样一枚奖章给我拿来，你就可以获得奖赏。', '进入战歌峡谷击败联盟小队，获得一枚战歌荣誉奖章，然后向莫尔杉营地的沙塔尔·碎颅复命。', '<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要牺牲多少联盟的渣滓才能让他们退却?只有时间可以说明一切，$r……', '敌人的鲜血就是我们的荣耀，你干得很出色。', '', '去贫瘠之地找莫尔杉营地的沙塔尔·碎颅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8297, '阿拉希盆地的资源！', '我们必须依靠我们的士兵进行战斗，所有的士兵都会这么告诉你的。他们还会告诉你，他们正在使用破烂不堪的装备，饥肠辘辘地开向战场！$B$B这就是阿拉希盆地显得非常重要的原因。金属，武器，食物，木材——所有我们所需要的东西都可以从那里获得。$B$B那就是我需要你发挥作用的地方，$N。进入阿拉希盆地，比敌人占据更多的基地，以此来获得战斗的胜利，然后给我带回一箱资源来。', '获得阿拉希盆地战斗的胜利，获取一只阿拉希资源箱，然后向避难谷地的玛克里尔中士复命。', '你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们配置给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。', '你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好干一仗……', '', '去阿拉希高地找避难谷地的玛克里尔中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8298, '更多的资源', '', '', '啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。', '虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。', '', '去找阿拉希高地的玛克里尔中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8300, '更多的资源', '', '', '啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。', '虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。', '', '去找阿拉希高地的亡灵哨兵莫提斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8301, '正义之路', '诺兹多姆的子嗣根本不信任低等种族。虽然你已经向我证明了你的确具备了英雄的潜质，但是现在你还得向我的主人证明这一点。$B$B亚什虫巢、佐拉虫巢、雷戈虫巢，这些地方的虫子们蠢蠢欲动，对我们形成了极大的威胁。杀死这些虫巢中的异种虫类，从它们的甲壳上取下碎片。当你获得足够多的碎片时，回到我这儿来。', '希利苏斯塞纳里奥要塞的流沙守望者巴里斯托尔斯想要你杀死亚什虫巢、佐拉虫巢和雷戈虫巢中的异种虫类。从死去的虫子尸体上收集异种蝎壳碎片。当你收集到200块异种蝎壳碎片时，回到巴里斯托尔斯那儿去。$B$B作为一名诺兹多姆的特使，只有你和你的副官可以从异种虫类的尸体上拾取异种蝎壳碎片。请注意保持你的包裹空间足够多。', '你并不孤单，英雄。我现在让你有能力可以指派别人帮你完成任务。如果你想成为人民的拥护者，你在任务和职责之中都需要协助。', '它们之所以不信任人类种族是有深厚的历史因素的;不过，唉，这种故事还是留给他的子嗣在对的时机来讲吧。', '', '去希利苏斯找塞纳里奥要塞的流沙守望者巴里斯托尔斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8302, '正义之手', '凡人，明智地选择你的副官。每当你完成一次任务，你就可以选择一个新的副官。$B$B我需要更多的异种蝎壳碎片。别浪费时间！', '希利苏斯塞纳里奥要塞的流沙守望者巴里斯托尔斯想要你杀死亚什虫巢、佐拉虫巢和雷戈虫巢中的异种虫类。从死去的虫子尸体上收集异种蝎壳碎片。当你收集到200块异种蝎壳碎片时，回到巴里斯托尔斯那儿去。', '做的好，英雄。你现在可以指派另一个诺兹多姆的代理人。', '说不定有一天整个塞纳里奥要塞都会在你的控制之下。', '', '去希利苏斯找塞纳里奥要塞的流沙守望者巴里斯托尔斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8304, '亲爱的纳塔莉亚', '我亲爱的纳塔莉亚走失了。$B$B老实说，她失踪之前好几周都行为怪异。我不止一次看到她在四下无人时喃喃自语。她坚持说什么自己是对的，坚持继续自己的研究。$B$B我最后一次见她的时候，她正朝着南边的铜须营地走去。$B$B我的兵力非常薄弱，$N。所以我想请你转至铜须营地，问问那些矮人。', '希利苏斯塞纳里奥要塞的指挥官玛尔利斯想要你询问铜须营地的矮人。你可以在塞纳里奥要塞以南找到铜须营地。$B$B一旦你收集到有用的信息，就回到指挥官玛尔利斯那儿。', '<指挥官玛尔利斯低头沉思。>$B$B不管她是生是死，我一定要做对的事。一定要找到她。唉，我因职责在身不能离开这个前哨基地。你能再帮我一次吗，$N?', '别浪费时间了，$N!', '', '去希利苏斯找塞纳里奥要塞的指挥官玛尔利斯。', '询问弗兰卡', '询问鲁特加尔', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8306, '深入疯狂之口', '我想让你转至雷戈虫巢，看看我心爱的纳塔莉亚变成什么样了，$N。要单独完成这项任务并不容易，我建议你带上几个朋友。在你动身转至虫巢之前，请一定返回营地跟那些矮人谈谈。他们或许会告诉你对付居住在虫巢中的异种虫类的窍门。$B$B$N，如果纳塔莉亚真的如他们所说的那样变得疯狂……做你应该做的。$B$B<指挥官玛尔利斯转过身去。>', '希利苏斯塞纳里奥要塞的指挥官玛尔利斯想要你找到他心爱的纳塔莉亚。你收集到的信息表明纳塔莉亚·玛尔利斯可能在南面的雷戈虫巢。$B$B在你赶往虫巢之前，记得去铜须营地拜访一下那儿的矮人，他们或许会给你提些建议。$B$B$N，记住指挥官的话：做你应该做的……', '<指挥官玛尔利斯抱住他的胸前。>$B$B克苏恩?这到底是什么意思?什么是克苏恩?这个魔鬼怎么会把我可爱的娜塔莉雅变成你们所说的怪物?', '娜塔莉雅?', '', '去希利苏斯找塞纳里奥要塞的指挥官玛尔利斯。', '纳塔莉亚·玛尔利斯的命运', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8308, '布莱恩·铜须的信', '致此信的读者：$B$B当你读到这儿时，我可能已经死了，也可能很快就会死去，这很难说。总之，大部分人都已经死掉了。$B$B我已经找到了有关一位泰坦的信息。他和一个上古之神展开了一场激战。是的，上古之神。我还找到通往安其拉的古老隧道。$B$B将这封信带回我的营地，保证我的猴子有充足的食物和水，记得多抱抱它。$B$B- 布莱恩·铜须，探险特派员$B$B附：注意那些崇拜上古之神的暗夜精灵。', '将布莱恩·铜须的信件带往希利苏斯南部的铜须营地。', '嗯，这解释了很多事。如果你找到去安其拉的路，注意一下老布莱恩。我怕他没有猴子会很无力。', '喔，亲爱的。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8309, '追查雕文', '在我们首次尝试进攻虫巢、玛尔利斯夫人变得疯疯癫癫之后，那些虫巢中就不断涌出虫子来！这也许跟那些奇怪的水晶上的雕文有关。$B$B我们必须从三个虫巢的水晶上取下拓文。如果我们能得到拓文，或许能揭开这种疯症的谜团。$B$B带上拓文工具，邀上你的伙伴，转至虫巢去吧，$N。取下三座虫巢中的拓文之后再回到我这儿来。', '希利苏斯铜须营地的鲁特加尔·雕石想要你转至亚什虫巢、佐拉虫巢和雷戈虫巢，从虫巢中的雕文水晶上取下拓文。$B$B使用地质学家的抄录工具包获取古老雕文的摹本。完成任务后回到鲁特加尔·雕石那儿。', '我不能理解这些雕纹。我从没看过像这样的东西!我希望法兰克尔的研究可以让这片混乱有些头绪。', '如果你在其中一个虫巢里发现一些疯狂的夜精灵小姑娘，别忘了替我们给她点颜色瞧瞧。', '', '去希利苏斯找铜须营地的鲁特加尔·雕石。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8310, '破译密码', '我得制作一种药剂，帮助我们解读拓文以及其拉虫人和异种虫的语言！我需要什么？很高兴你能这么问！我需要脑子！确切地说，我需要居住在虫巢中的不同种群的异种虫的脑子。把它们的脑子给我，或许鲁特加尔的努力就不会白费。', '希利苏斯铜须营地的弗兰卡·石桥想让你取回一个亚什异种虫脑、一个佐拉异种虫脑和一个雷戈异种虫脑。完成任务后回到弗兰卡那儿。', '太棒了!别跑太远啊，孩子。我们可能还需要你去完成另一两个任务。', '去和猴子玩吧，小鬼。我现在没空。', '', '去希利苏斯找铜须营地的弗兰卡·石桥。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8311, '耶斯帕尔的万圣节糖果！', '我想要去讨万圣节糖果，但是我不能去，因为我生病了。如果你可以代我去的话，我会给你一些我已有的糖果！我想你会喜欢这些糖果的……它可以让你变成又好玩又可怕的东西！$B$B每座主城的旅店老板都有准备万圣节的糖果——你只要和他们交谈，然后按照他们所要求的做就可以了！另外，铁炉堡有个叫塔瓦斯德的小侏儒也在散发糖果。如果你得到了所有的糖果，就把它们都带回来给我吧！', '与暴风城、铁炉堡和达纳苏斯的旅店老板以及铁炉堡的塔瓦斯德·基瑟尔谈一谈。按照他们的要求做出动作，并获得他们的礼物。$B$B把达纳苏斯水果糖、诺莫瑞根橡皮糖、暴风城杏仁糖和铁炉堡薄荷糖交给暴风城孤儿院的耶斯帕尔。', '哇，你全都拿来了!你真棒!$B$B谢谢你代替我去完成不给糖就捣蛋。拿着这些南瓜糖吧 – 我想你会很喜欢的!$B$B万鬼节尾声快乐，$N!', '你完成“不给糖就捣蛋”了吗?我很遗憾我生病了不能去，不过你的帮忙让我感觉好多了…', '', '去找暴风城的耶斯帕尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8312, '斯波普斯的万圣节糖果！', '我想要去讨万圣节糖果，但是我不能去，因为我生病了。如果你可以代我去的话，我会给你一些我已有的糖果！我想你会喜欢这些糖果的……它可以让你变成又好玩又可怕的东西！$B$B每座主城的旅店老板都有准备万圣节的糖果——你只要和他们交谈，然后按照他们所要求的做就可以了！另外，森金村的一个名叫卡利·雷米克的巨魔也在散发糖果。如果你得到了所有的糖果，就把它们都带回来给我吧！', '与奥格瑞玛、幽暗城和雷霆崖的旅店老板以及森金村的卡利·雷米克谈一谈。按照他们的要求做出动作，并获得他们的礼物。$B$B把雷霆崖奶糖、暗矛橡皮糖、奥格瑞玛软糖和幽暗城薄荷糖交给奥格瑞玛孤儿院的斯波普斯。', '哇，你全都拿来了!你真棒!$B$B谢谢你代替我去完成不给糖就捣蛋。拿着这些南瓜糖吧 – 我想你会很喜欢的!$B$B万鬼节尾声快乐，$N!', '你完成“不给糖就捣蛋”了吗?我很遗憾我生病了不能去，不过你的帮忙让我感觉好多了…', '', '去找奥格瑞玛的斯波普斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8313, '分享知识', '虽然你能读懂沙虫的烹饪配方，但是里面提到的草药和香料你都从未听说过。卡兰德拉斯或许对此有些了解。', '将破碎的食谱交给塞纳里奥要塞旅店中的卡兰德拉斯。', '让我们来看看…$B$B这看起来够简单了。他们有些药草有自己的名称，不过那都可以简单理解。来，让我证明给你看!', '你学得食谱了吗?你不会想占为己有吧，我希望!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8314, '揭开秘密', '我们就快要取得突破了，$N！我们可以通过你取回的拓文在这块晶华棱柱上重现雕文。很明显，其拉虫人和某种未知生物利用这种文字与异种虫交流信息。$B$B不幸的是，我们只能从雕文中发现这一点。我们需要设法揭开水晶中隐藏的秘密。$B$B将雕文水晶棱柱交给塞纳里奥要塞的地质学家拉克斯班。她或许能帮上忙。', '铜须营地的鲁特加尔·雕石想让你将雕文水晶棱柱交给希利苏斯塞纳里奥要塞的地质学家拉克斯班。', '矮人无法解读雕纹的原因是因为根本就没有东西可以解读。柱体变动的外层一定要和内部水晶的印记密切配合才能传送出讯息。聪明…$B$B我们虽然可以翻译出这些资料，但首先一定要解开密码。在柱体表面只有一条线索 – 假设印记有正确地转变 – 而且它看起来很恐怖。', '天啊!你手上的是什么东西，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8315, '召唤', '雕文显示，一位其拉虫人的使者跟三个异种虫相约在一处龙骨旁见面。关于雕文上方的文字，我只能假设那是某种密码。这密码很可能是召唤其拉虫人使者的关键。$B$B我将制作一份雕文密码的副本，你把它放到格拉卡洛之骨的沙中。如果我没猜错的话，主宰会认为可以传递新数据了。杀死他们，然后跟其拉虫人使者作战。他是揭开水晶之谜的关键人物……', '希利苏斯塞纳里奥要塞的地质学家拉克斯班想让你从其拉虫人使者那里取回水晶分解装置。$B$B你已经奉命将召唤雕文带往塞纳里奥要塞以南的格拉卡洛之骨处，将它们从沙中引出。一旦其拉虫人使者露面，就杀死它，获得水晶分解装置。成功之后回到地质学家拉克斯班那儿去。$B$B你必须召集一支强大的军队来完成这项任务，$N！', '我的手中握有两万年的历史，$N!', '你一定要在机会出现时奋力一击!', '', '去希利苏斯找塞纳里奥要塞的地质学家拉克斯班。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8317, '下厨', '这食谱肯定会派上用场的。我得去准备沙漠肉丸子了。我需要你的帮助，当然，我是不会让你白费力气的。', '塞纳里奥要塞的卡兰德拉斯需要制作10只沙漠肉丸子。', '太棒了!你是个救命恩人。这些饺子真棒。没想过暮光之锤的东西可以做出这么好的味道。', '丸子做的怎么样了?', '', '去希利苏斯找塞纳里奥要塞的卡兰德拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8318, '秘密交流', '一些暮光之锤的教徒带着写有含糊不清词句的纸片。我希望你可以弄一些来给我，$c。$B$B我说不清“含糊不清”是什么概念，总之是含义不清的！他们用这些纸片进行不同团队之间的秘密交流，如果我们可以找到更多这样的纸片，那么他们所能进行的交流就会更少！', '把10片暮光密文信交给塞纳里奥要塞的鲍尔·蛮鬃。', '太好了!我要把这些都存放起来，搞不好以后会有需要。', '你找到那些纸片了吗?', '', '去希利苏斯找塞纳里奥要塞的鲍尔·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8319, '暮光密文信', '', '', '做的好!我会帮你多说点好话的。', '继续带文件给我。我们很快就能逼暮光之锤回到他们爬出来的巢穴了。', '', '去找希利苏斯的鲍尔·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8320, '暮光地王', '暮光之锤，一群屈服于毁灭力量的教徒，他们在希利苏斯安营扎寨，日夜举行奇怪的仪式。我们还不知道他们的计划是什么，但是我相信他们正在试图和那些沙漠中的红色水晶进行联系。$B$B虽然迟早我们会发现他们的秘密，但是眼下，我们需要立即中止他们的威胁。到他们在西边设立的营地去，找到暮光地王。他们是这些恶棍的首领，也就是你要去击杀的对象！', '杀死10个暮光地王，然后向塞纳里奥要塞的霍姆·蛮鬃复命。', '这是个执行的非常出色的任务，$N。杀死暮光地领主对他们的教派造成了很大的损失。希望他们的计画因此缓慢下来…', '进入沙漠寻找暮光地领主，$N。杀了他们之后回来找我。', '', '去希利苏斯找塞纳里奥要塞的霍姆·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8321, '邪恶的维拉尔', '我们发现又一个为暮光之锤运作的基地。那里被称为暮光小径，它是一个位于希利苏斯东北角的洞穴。该地区的首领，邪恶的维拉尔就徘徊在这个洞穴中——他就是你的下一个目标。当你完成这个任务之后，把他的戒指带回来。$B$B祝你好运，$N。暮光之锤的恶行一定要被阻止。', '把维拉尔的徽记之戒交给塞纳里奥要塞的霍姆·蛮鬃。', '你成功了!维拉尔被杀了!这只能算是暮光之锤在希利苏斯的毁灭。一定还有更多成员在四处捣乱，不过你今天给他们的教训也够厉害了。', '$N，你打败卑鄙的维拉尔了吗?有没有拿到他的玺戒呢?', '', '去希利苏斯找塞纳里奥要塞的霍姆·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8323, '真正的信徒', '现在我拥有了暮光词典，不过我还需要你帮我个小忙。$B$B我抛弃了我以前的组织，但是我还是很怀念他们每个月的时事通讯刊物。$B$B如果你想要笑的话就笑吧，但是在这段离开的日子阅读《真正的信徒》是我消磨时间的好办法。$B$B这份读物中有许多我可以和你分享的信息。请把任何你从暮光之锤成员身上找到的加过密的文字带给我。', '隐士奥泰尔要你带回10张暮光密文信。', '太好了!我会尽快把这些文件尽快解码。如果我发现任何有趣的东西，我会找到方法给你讯息的。', '你有找到任何加密文件吗?我对阅读这个月的真实信仰者感到非常好奇!', '', '去找希利苏斯的隐士奥泰尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8324, '更多的读物', '', '', '太好了!我已经迫不及待地想要阅读这些文件了。如果你还有找到更多文件的话，请持续把它们带来给我。', '有找到更多的加密文件吗? 带给我一大批这些文件，解码的工作会花上一些时间。', '', '去找希利苏斯的隐士奥泰尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8325, '夺回逐日岛', '你越快开始接受训练，$N，就对我们大家越有好处。我们已经没有任何容忍犯错的馀地了\r\n，所以你可要听仔细。$B$B那些太阳之塔西边的悬浮着的绿色物体，就是燃烧水晶，它们长期以来给岛内供应着能源，而法力浮龙则负责守护着这些水晶。天灾军团对奎尔萨拉斯的入侵大大干扰了我们对这些法力浮龙的魔法控制，导致它们变得不听调遣。$B$B除了削减它们的数量以外，已经没有其它的办法了。去吧，完成之后再回来向我复命。', '杀死8只法力浮龙。它们位于法师塔和阳台附近的燃烧水晶周围。', '你成功的完成了你的第一个任务;你会因此得到祝贺的。这样的成功让我相信你会比那些不记取大师教训的年轻血精灵更优秀。持续的成功是会有代价的 -', '我们重整社会的工程就在这里展开，$N。当我们救回我们的家园，就能扬眉吐气了。', '', '去永歌森林找逐日岛的魔导师艾洛娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8326, '令人遗憾的措施', '你所做出的努力产生了一些后果，坦率地说，是我不希望看到的后果。燃烧水晶中紊乱的力量给这个岛屿上的生态平衡带来的破坏远比我的预料严重许多。我想，我们现在必须采取一些令人遗憾的措施来稳定局势了。$B$B附近的山猫已经受到了水晶魔力的影响，成为了牺牲品，我们不得不清除它们。带回它们的项圈，$N，这样我就可以看看是否能给这些项圈附上一定的魔法抗性，帮助它们从疯狂中恢复过来。', '杀死一些魔泉山猫和魔泉山猫幼崽，并从它们身上收集8个山猫的项圈。完成之后向逐日岛的魔导师艾洛娜复命。', '哨塔和附近的区域现在应该已经安全了，虽然只是暂时的。你做的很好，但是如果我们要在这里长久生存，我们就得夺回整座岛的控制权。这表示除了误入歧途的法力龙鳗和山猫，有更多的威胁牵扯其中。$B$B拿着这个，$N - 你绝对会在接下来的任务中用到这个好东西的。', '要你杀死这些野兽对我来说也不是件快乐的事。过去我们也与这些生物和平共处，现在情况已大不相同了。对所有的辛多雷而言，最重要的一个任务就是生存;记住这一点。', '', '去永歌森林找逐日岛的魔导师艾洛娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8330, '索兰尼亚的物品', '由于逐日岛这段时间以来所发生的混乱和变故，我几乎完全没有时间来收回我散落在岛上的东西。现在我必须守在这里观察太阳之井，所以我想只能拜托你替我收回这些东西了。$B$B我需要我的占卜宝珠，我的天灾魔法卷轴，还有我的日记本。来，拿着这个小背包，我的东西实在是太多了，你可以把它们都装在这里面带回来。请一定要把它们带回来给我，我会给你一点小礼物以表达谢意的——另外，这个小背包你也可以留下！', '收集护井者索兰尼亚的占卜宝珠、天灾魔法卷轴和日记。它们分别位于逐日岛上的池塘边、喷泉附近以及一块燃烧水晶旁。找到所有物品后，将它们归还给太阳之塔上的护井者索兰尼亚。', '做得好 - 我就知道你适合这个任务。一旦能安全的查看我们在岛上的户外设施，我就会好好利用这些东西。$B$B如我所说过的，请收下这个背袋。还有，你会发现这件装备很有用的。就把它当作是尽忠职守的一点补偿吧!', '你找到了我的东西吗?只要我们重拾逐日岛的统治权，我就会需要这些东西。至于现在，我必须继续看守着太阳之井……或是它剩下的土地。', '', '去逐日岛找太阳之塔的护井者索兰尼亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8332, '议会的公爵', '我们认为应该可能使用一块风石来伏击一名深渊议会的公爵。前提是，需要有人通过风石来进行联系，并让公爵确认你是暮光之锤的一名中层人员。$B$B因此我们需要暮光信徒身份勋章的复制品。我可以制作这样一枚勋章，但是我需要一个大块魔光碎片，还有深渊圣殿骑士所佩戴的纹章。$B$B把这些带给我，然后我就可以完成剩下的工作了。', '把1个大块魔光碎片和3顶深渊纹章交给塞纳利奥要塞的奥蕾尔·金叶。', '啊，很好。我忙着制作大勋章 - 现在有了这些材料，我马上就能完成了…$B$B好了。大勋章做好了，$N。$B$B你在启动暮光之锤的风石时要戴着它。戴上它，还有这些暮光服饰，然后深渊议会的人就会以为你是他们的祭司部属中的一员了。', '你拿到裂片和羽饰了吗，$N?我需要它们才能制作暮光信徒身份勋章。', '', '去希利苏斯找塞纳里奥要塞的奥蕾尔·金叶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8333, '身份勋章', '', '', '拿去吧，$N。再给你一个暮光身分大勋章。好好使用它，祝你成功对抗深渊议会!', '如果你还需要另一个暮光信徒身份勋章，我很乐意效劳。不过，我还需要另一块艳丽的裂片和一些深渊纹章。', '', '去找希利苏斯的奥蕾尔·金叶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8334, '攻势', '在派你进入学院之前，我还另外有件任务要你立刻处理。尽管这群凶暴的树人嫩苗过去曾是我们逐日岛上园丁们的好伙伴，可现在它们却已经失去了控制。你要迅速将它们全部清除。不过你也要小心，失去控制以后，它们已经变得更加具有攻击性。这样的情况下，除了杀死它们，我们已经没有其它办法来清除这些曾经温顺的仆从了。$B$B向你下达这样的命令，我感到很难过，但生存的需要大于一切。我以后会为它们哀悼的。', '杀死7只树人嫩苗和7只凶猛的树人嫩苗，然后向逐日岛的兰萨恩·派雷隆复命。', '他们的死并没有给我带来任何快乐，不过这让我知道你已经准备好接下逐日岛最重要的任务。拿着这个，好好利用它;你的下一个任务需要好的物品和敏锐的智慧。我们能不能夺回小岛的控制权全看这了。', '你最好多了解一点生存的意义 - 还有生存的代价 - 早点知道比较好。身为一个血精灵，作困难的决定是你即将习惯的事。$B$B当天灾军团将我们的家园一分为二的时候没有人伸出援手。是我们，我们自己重新振作，东山再起。', '', '去永歌森林找逐日岛的兰萨恩·派雷隆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8335, '放逐者菲伦德雷', '西南方法瑟林学院的顶部住着一个背叛了我们的家伙。$B$B他名叫菲伦德雷，因为藐视导师与长老们的警告而被放逐出了血精灵的土地。他是我们社会中的一颗毒瘤，如今已经只为满足其自身贪得无厌的魔瘾而活着。他拒绝学习控制魔瘾的方法，于是现在成为了一具行尸走肉，成为了一个失心者，并威胁着太阳之塔的安全。$B$B给予他人道的毁灭吧，同时也记得杀死那些被他当作仆从的奥术怨灵。', '杀死8只奥术怨灵和2只被污染的奥术怨灵，以及放逐者菲伦德雷，他们位于法瑟林学院。将菲伦德雷的徽记交给逐日岛的兰萨恩·派雷隆。', '法兰德伦的头颅……你会受到嘉奖的，$N。你达成了其它人，像是法兰德伦，彻底失败的事。或许你真的准备好作为一个血精灵的成员。$B$B你的成功代表你能克服永歌的强大威胁……相信我，还有更多要面对的。', '记住这个警告 -', '', '去找逐日岛的兰萨恩·派雷隆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8336, '奥术薄片', '我们失去了对岛屿上许多生物的控制，这真是太糟糕了。这里曾是一片无比宁静和谐的地方，最适合学习与研究了。可是现在，我们整天都把时间浪费在防备那些原本是被我们圈养的生物上！$B$B我现在将给你一个难得的机会，你只需要帮我做一些收集工作，我就可以帮你施展一个小魔法做为报酬。你可以在逐日岛上所有使用魔法的生物身上找到一种名叫奥术薄片的东西，给我带一打那玩意回来，完成之后，我会在你身上施放一个小法术，这样你就能更好地在岛上冒险了。', '从逐日岛上的任意使用魔法的生物身上收集6块奥术薄片，把它们交给奥术师伊塔纳斯。', '很好 –', '岛上许多生物都因为我们的魔法忽然变的无侵略性又温驯。在天灾军团摧毁太阳之井后，我们对这些生物的控制就被粉碎了。秘法棱片是我们曾掌握控制的一点馀烬，或许能从中想出一个新对策，让我们重拾对这些生物的控制权。$B$B更顺利的话，或许棱片还能让我们知道这座岛到底是为何而抑郁。', '', '去永歌森林找逐日岛的奥术师伊塔纳斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8338, '被污染的奥术薄片', '你在这只被污染的奥术怨灵的尸体旁发现了一块古怪的薄片，它已经被魔法结晶化了。这块薄片与你见过的其它奥术薄片有着明显的不同，散发着黑暗与邪恶的气息，正如怨灵一般。只是拿着它，你就感觉到了某种非自然的邪恶预兆。$B$B太阳之塔露台旁的奥术师赫里恩或许能对这块薄片进行一些研究。', '将被污染的奥术薄片交给逐日岛的太阳之塔露台上的奥术师赫里恩。', '这…真是太有趣了。如果我说有趣，就表示这比任何东西还令人心神不宁。$B$B在太阳之井遭到摧毁后，想重新夺回岛上的控制权对我们而言是个挑战。我怀疑不管是什么邪恶的源头正腐败着小岛，它就在中心;这个棱片或许对解开事情真相有一些帮助。$B$B你把这个拿来给我是很聪明的，$N。收下这个作为你的奖励。谢谢你。', '从你的举止看来，好像有什么急事。有什么特别的事我可以帮你吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8341, '议会的领主', '深渊议会的高阶领主只有通过更大的风石才能召唤出来，而只有最高等级的暮光之锤官员才可以和他们说话。不过……我找到了进一步伪装你并欺骗深渊领主的方法！$B$B我们要伪造一枚只有他们教派中最高级别的成员才拥有的暮光贵族之戒。如果你可以带给我大块魔光碎片和深渊徽记的话，我就可以帮你制作一个。', '把5个大块魔光碎片和3个深渊徽记交给塞纳里奥要塞的奥蕾尔·金叶。', '谢谢。我马上就会把戒指准备好给你…$B$B好了。现在你可以出发了。$B$B记得一定要在启动较强大的风石时戴上这枚戒指，身分大勋章和这些暮光服饰。照着做，深渊议会的人就会以为你是他们的奴仆之一。然后，或许你就能引诱出一个人落入陷阱!', '你拿到裂片和羽饰了吗，$N?我需要它们才能制作一个贵族之戒。', '', '去希利苏斯找塞纳里奥要塞的奥蕾尔·金叶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8342, '暮光徽记之戒', '', '', '啊，我看的出来你的信念很坚定。没几个人敢挑战那个啊，我看的出来你的信念很坚定。没几个人敢挑战那个议会的人!$B$B这是你的戒指，$N。但愿你的意志和运气坚毅不摇。', '$N，如果你打算再次联系深渊高等议会，那么你需要另一枚暮光徽记之戒。带更多的裂片和羽饰给我，我就能为你制作一枚戒指。', '', '去找希利苏斯的奥蕾尔·金叶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8344, '力量之源', '记住我说的话，年轻的$n，这座岛屿已经被严重污染了，这种污染的威胁比起天灾军团留下的馀孽还要大。$B$B我确信，这片岛屿上应该有真正的恶魔存在。$B$B就在这里西面的法瑟林学院，滋生着大量的奥术怨灵，它们就是一个能让我们接触到恶魔力量之源的窗口。你现在的任务就是给我带回一些未被污染的怨灵精华，以及一些被污染的怨灵精华。$B$B作为给你的报酬，我会教你如何召唤小鬼，它将成为你所拥有的第一个恶魔仆从。', '给逐日岛的太阳之塔中的召唤者泰里拉伦带回4份怨灵精华以及1份被污染的怨灵精华。', '做的好!嗯，这些精华应该足够让我开始我的研究。我有一种强烈的预感这个腐坏的精华就是那个东西…窗口，如我之前提过的。$B$B遵照大师的命令是年轻术士绝对该做的事。如我向你保证的，遵照指示并完成他们就会得到奖励。', '怨灵精华会是很好的来源实验品。身为一个术士，在新事物扭曲我们的意志前从中学习，对你们而言是很重要的。恶魔是最重要的能量泉源，如果这岛上真有这样的污染会是很好的利益。$B$B嗯…是我们术士的利益。', '', '去找永歌森林的召唤者泰里拉伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8345, '达斯雷玛的神龛', '日复一日，我矗立在这里，观察着，思索着，等待着。当我极目远眺着海平线时，有许多人指责我只会缅怀过去的日子，无法自拔。但我仍然坚定地认为，每一位来到这座岛屿的访客都应纪念那些曾为我们的生存而付出并牺牲一切的人。$B$B达斯雷玛·逐日者是我们的第一任国王。他领导着我们穿越了大漩涡，从卡利姆多来到这里。$B$B去西边寻找他的神龛吧，阅读了上面的纪念铭文之后再回来找我。', '阅读达斯雷玛的神龛上的铭文之后，向逐日岛太阳之塔上的护井者索兰尼亚复命。', '啊，$N – 谢谢你与我分享在达斯雷玛神殿的经验。首先，你的责任感和尊敬值得被佳许 –', '你已经读过神殿中的铭文了吗，$C?', '', '去永歌森林找逐日岛的护井者索兰尼亚。', '阅读达斯雷玛的神龛上的铭文', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8346, '无尽的渴求', '如果说你在逐日岛学到的最重要一课是什么，那无疑就是如何控制你对魔法的渴求了。血精灵对魔法的渴求是一种无止境的渴求，$N，你所吸收的能量必须完全处于你的掌控之中，并且通过奥术洪流将能量释放出去。如果你失败了的话，就将变成一个失心者……变成一个在绝望与疯狂中苟活的瘾君子。$B$B去岛上寻找一条法力浮龙，对它使用奥术洪流技能吧。学会掌握欲望所生成的力量。当你学会如何释放这种力量之后，回来找我。', '对一条法力浮龙使用种族特长技能“奥术洪流”，然后向奥术师赫里恩复命。', '你今天表现的很好，$N。你愿意学习的精神告诉我，或许你会克服血精灵对魔法不屈的渴求。$B$B别因此而懈怠，年轻人，应该要试着掌握你所学的。只有努力才能让我们种族存活下来。$B$B拿着这个 – 对你或许有用。去吧，为我们人民再一次带来荣耀。', '这不是一个选择题…你一定要抑制对魔法的渴望。如果失败了就会像血精灵一样。他们以为自己可以不受折磨地控制自己的需求，现在也只是跟那些失落者一样罢了。$B$B你不会想象一个发疯的上瘾者一样结束生命的。相信我。', '', '去永歌森林找逐日岛的奥术师赫里恩。', '使用奥术洪流', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8348, '公爵的徽记', '霍姆告诉我说你知道召唤深渊公爵的方法了！真是件了不起的事儿。$B$B还有什么能称得上是了不起的成就呢？打扁这些家伙。如果你明白我在说什么，你就该知道这会对他们的属下带来多大的冲击。把他们的徽记带回来作为证据。', '将深渊徽记交给塞纳里奥要塞的霍姆·蛮鬃。', '从我第一眼看到你走进塞纳里奥城堡的时候，我就知道你是个勇敢的$C。好好保持下去!', '你跟深渊公爵进行得如何?它打人很痛吗?', '', '去希利苏斯找塞纳里奥要塞的鲍尔·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8350, '送信', '又一位信使的牺牲……这真是一个悲剧，但早在我们接下这份工作的时候，就已经有牺牲的觉悟了。太阳之塔的魔导师艾洛娜希望我们把这只包裹运送到鹰翼广场的旅店去，越快越好。$B$B但当前我们缺乏人手，我已经没有任何同伴可以执行这个任务了。$B$B我不想对你说谎，从这里通向鹰翼广场的道路是非常危险的，一但离开黎明之路的安全范围，就可能随时遭遇攻击。你能为我们完成这个任务吗，$N？', '将艾洛娜的包裹交给永歌森林鹰翼广场旅店中的旅店老板德兰妮尔。', '谢谢你，很感激你的快递服务。$B$B请把这里当做你的家。如果你还没有炉石，请拿一个并将你的家绑定在这。使用炉石可以让你每半小时传送回旅店一次。如果你弄丢了你的炉石，只要回到任何一间旅店', '欢迎来到我的旅店，$C。你有什么东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8352, '议会的节杖', '霍姆和我刚才还谈起你呢。他说你已经准备好跟深渊领主作战了！$B$B我必须告诉你，这是一项非常危险的任务。你最好叫上支持人员。我并不是让你带上一两个朋友，你需要的是一支做好充分的战斗准备的精英团队。如果你的朋友跟你一样出色，你们或许能打败他！$B$B如果你打败了深渊领主，和往常一样，向我出示证据，我就会给你丰厚的奖励。', '将一柄深渊节杖交给塞纳里奥要塞的鲍尔·蛮鬃。', '你…你做到了!你真的作到了，$N!拿着这个，这是我们所拥有的最大的胸甲，里面装满了我们所找到的最好物品。', '嗯，事情进行得如何?我会不计代价让自己离开这个地点并与它们搏斗的。', '', '去希利苏斯找塞纳里奥要塞的鲍尔·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8355, '学火车，换糖果', '要糖果的恶作剧游戏！哈哈！$B$B即使你正在做什么高尚的事儿，比如为生病的小孩收集糖果之类的，我也不会轻易放过你。我有一颗诺莫瑞根橡皮糖要送给那个生病的孩子……如果你愿意模仿火车声音的话！哈哈，是的，这就是恶作剧！你要拿到水果糖，就得模仿火车的声音！$B$B咔咔－呜呜，$C！', '为塔瓦斯德·基瑟尔模仿火车的声音，作为交换，你将得到一颗诺莫瑞根橡皮糖！', '哇!做的好，$N!这是你的糖果。$B$B万鬼节快乐!', '嗯，开始吧…', '', '去找湿地的塔瓦斯德·基瑟尔。', '为塔瓦斯德模仿火车的声音', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8356, '显肌肉，换糖果', '你……你的装束真有趣。即使你心眼好，在陪一个生病的小孩子玩要糖果的恶作剧游戏，恐怕我还是得要求你做点什么！$B$B让我想想……你穿的衣服……看起来非常奇怪……你得炫耀自己的肌肉！是的，就是现在，炫耀你的肌肉吧，强壮的$g男:女;$c！$B$B你必须炫耀肌肉，这样我才会给你美味的暴风城杏仁糖。这可是万圣节的超美味糖果哦。', '向旅店老板奥里森炫耀自己强壮的肌肉，作为交换，你将得到一颗暴风城杏仁糖！', '你真是了不起，哈哈!做的好，你真是个有趣的人。这是你的糖果。$B$B万鬼节快乐，$N!', '你不展示肌肉是不会有糖果的，$N……', '', '去找暴风城的旅店老板奥里森。', '向旅店老板奥里森炫耀肌肉', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8357, '跳跳舞，换糖果', '即使你在陪一个生病的小孩子玩要糖果的恶作剧游戏，你也要做点什么来换取糖果！传统习俗可不能被破坏……$B$B我想一颗糖果的代价就是你得跳支舞！是的，让我们看看你的舞姿！跳舞吧，我会给你美味的奶糖的！', '为旅店老板塞琳尼模仿跳舞动作，作为交换，你将得到一颗达纳苏斯水果糖！', '你跳的真不赖，$N!$B$B这是你应得的糖果。万鬼节快乐，替我问候那个生病的小朋友!希望他们能快点好起来。', '你会跳舞吧?先伸你的右脚…再缩你的右脚…伸你的右脚…扭扭身子…', '', '去找达纳苏斯的旅店老板塞琳尼。', '为旅店老板塞琳尼跳舞', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8358, '学火车，换糖果', '要糖果的恶作剧游戏！哈哈！$B$B即使你正在做什么高尚的事儿，比如为生病的小孩收集糖果之类的，我也不会轻易放过你。我有一颗暗矛橡皮糖要送给那个生病的孩子……如果你愿意模仿火车声音的话！哈哈，是的，这就是恶作剧！你要拿到水果糖，就得模仿火车的声音！$B$B咔咔－呜呜，$C！', '为卡利·雷米克模仿火车的声音，作为交换，你将得到一颗暗矛橡皮糖！', '哇!做的好，$N!这是你的糖果。$B$B万鬼节快乐!', '嗯，开始吧……', '', '去杜隆塔尔找暗矛海滩的卡利·雷米克。', '为卡利·雷米克模仿火车的声音', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8359, '显肌肉，换糖果', '你……你的装束真有趣。即使你心眼好，在陪一个生病的小孩子玩要糖果的恶作剧游戏，恐怕我还是得要求你做点什么！$B$B让我想想……你穿的衣服……看起来非常奇怪……你得炫耀自己的肌肉！是的，就是现在，炫耀你的肌肉吧，强壮的$g男:女;$c！$B$B你必须炫耀肌肉，这样我才会给你美味的奥格瑞玛软糖。这可是万圣节的超美味糖果哦。', '向旅店老板格雷什卡炫耀自己强壮的肌肉，作为交换，你将得到一颗奥格瑞玛软糖！', '你真是了不起，哈哈!做的好，你真是个有趣的人。这是你的糖果。$B$B万鬼节快乐，$N!', '你不展示肌肉是不会有糖果的，$N……', '', '去找奥格瑞玛的旅店老板格雷什卡。', '向旅店老板格雷什卡炫耀肌肉', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8360, '跳跳舞，换糖果', '即使你在陪一个生病的小孩子玩要糖果的恶作剧游戏，你也要做点什么来换取糖果！传统习俗可不能被破坏……$B$B我想一颗糖果的代价就是你得跳支舞！是的，让我们看看你的舞姿！跳舞吧，我会给你美味的奶糖的！', '为旅店老板帕拉曼模仿跳舞动作，作为交换，你将得到一颗雷霆崖奶糖！', '你跳的真不赖，$N!$B$B这是你应得的糖果。万鬼节快乐，替我问候那个生病的小朋友!希望他能快点好起来。', '你会跳舞吧?先伸你的右脚…再缩你的右脚…伸你的右脚…扭扭身子…', '', '去找雷霆崖的旅店老板帕拉。', '为旅店老板帕拉跳舞', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8361, '深渊联络', '我们见过暮光之锤的信徒举行仪式召唤强大的元素生物。我们不知道这些生物是他们崇拜的对象还是他们准备通过这些生物来和更加强大的力量进行沟通。有一件事是可以肯定的：他们听从这些元素生物的命令。$B$B我需要你找到一名深渊圣殿骑士，然后击败他！擒贼先擒王，当你完成任务之后把证明带回来。', '希利苏斯塞纳里奥要塞的鲍尔·蛮鬃要求你击败一名深渊圣殿骑士，并将一个深渊纹章带回来作为证明。', '哈!你办到了，$N!暮光之锤很快就会被粉碎了!', '你完成工作了吗?', '', '去希利苏斯找塞纳里奥要塞的鲍尔·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8362, '深渊纹章', '', '', '干得好!圣殿骑士的数量又减少了。$B$B给你，$N。希望这些东西对你有用。', '你已经证明了自己，$N。让我们继续给暮光之锤施压吧。我需要你去击杀更多的深渊圣殿骑士!我会奖励你一些我和胡姆在战斗中找到的东西。', '', '去找希利苏斯的鲍尔·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8363, '深渊徽记', '', '', '太好了，$N!击败那些公爵将使得暮光之锤陷入一段时间的混乱。按照我的承诺，这是你应得的奖励。这是我和胡姆能够找到的比较好的东西。', '你证明自己可以应付深渊公爵，$N。我总是鼓励好的习惯。因此记得给我带来更多的徽记，我会给你相应的奖励。', '', '去找希利苏斯的鲍尔·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8364, '深渊节杖', '', '', '我知道你可以的，$N!这是你应得的奖励。', '你已经完全超越了我的期望，$N。你干掉了我和霍姆一直以来都不敢面对的敌人。$B$B现在我能做的就是继续奖励你对抗暮光之锤的行为。$B$B带给我更多的深渊权杖，然后我将尽力给你最好的奖励。', '', '去找希利苏斯的鲍尔·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8365, '海盗的帽子！', '你是公司派来帮忙的？我相信你可以的。听好了，$c。就如你所知的那样，我是艾泽拉斯上层社会最顶极服饰的提供者。皇帝和皇后，酋长和他们部落所称的皇后，他们所有的穿着都由我亲自推荐。他们可是为此付出了大价钱，而且他们确实得到了最好的服饰。$B$B接下来就是你该做的。你应该去落帆海湾，无论你用什么办法，都要去弄到尽量多的海盗的帽子。你认为你可以完成这个任务吗？', '塔纳利斯热砂港的傲慢的店主要你去帮他收集20顶南海海盗帽。', '哦，你真是个可爱的$r，虽然你花的时间比我预计的要长。这些帽子在经过清洗和翻新之后可以帮我赚到不少钱。我总是愿意奖励那些辛勤工作的人，所以我有些东西要给你。我希望你可以在洗澡的时候用到它。', '你收集到20顶帽子了吗?我不相信你，让我看到那些帽子。它们最好保存完好!', '', '去塔纳利斯的热砂港找傲慢的店主。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8366, '南海复仇', '啊！他们想要我完成一个不可能完成的任务！$B$B热砂港想要我给南海海盗一些教训。问题是我不能同时在两个地方；我必须待在这里守护和平。$B$B最近，那些海盗似乎忘记了热砂港给他们的保护费。所以我希望你可以代表我去给他们洗洗脑子。$B$B你可以在这里南边不远的落帆海湾找到他们。谢谢你，$N，我欠你的人情！', '塔纳利斯热砂港的安全主管吉罗姆·比格维兹要你去干掉10个南海海盗、10个南海劫掠者、10个南海码头工人和10个南海流氓。', '$N!你真是好样的!我确信在你干掉那些人渣之后，热砂港对我的压力会减小一些。让我看看，我能给你什么奖励?你觉得一些钱以及从这些东西中选一样怎么样?', '那么快就回来了?我希望你好好教训了那帮无赖，让他们一辈子都无法忘记。', '', '去塔纳利斯找热砂港的安全主管吉罗姆·比格维兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8367, '无上的荣耀', '与联盟作战是为部落效劳的莫大荣耀！那些在各条战线上和联盟作战的士兵是我们最伟大的成员。我们要消灭我们的对手，而不是仅仅进行小规模的遭遇战，我们要打精心准备的大战。$B$B去每一条战线上消灭联盟吧！为了荣耀！为了部落！', '在每个战场上都取得1枚荣誉奖章，并将它们交给任意部落主城或沙塔斯城中的部落战争使者。', '你的试炼不会很轻松，但是你的勇气没有丧失，你的力量将会永存。和过去的辉煌告别吧，$C。没有人需要它们来证明自己的价值。向前进，$N。今天你将以英雄的姿态昂首向前!', '阿拉希到处流淌着战士的鲜血，奥特兰克的金属碰撞声不绝于耳。除非你从前线带回了消息，否则不要浪费我的时间!', '', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8368, '峡谷中的战斗', '我们在战歌峡谷对银翼哨兵展开攻势，这一战役至关重要。联盟以保护这片不属于他们的森林为由，妄图从部落手中夺取我们最大的伐木场。$B$B别让他们的妄想成为事实，$N！为了部落，证明你的价值！成功之后再回到我这儿来。', '将3枚战歌荣誉奖章交给战场外的部落战争使者。', '棒极了!你在战歌峡谷保卫战中表现很出色!愿你的英雄事迹在我们的土地上流传开来。', '你有战歌峡谷的消息吗，$N?', '', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8369, '奥特兰克的入侵者', '听好了，$N。不管你以前听说奥特兰克山谷的战斗进行得怎么样，只有一件事情是真的：雷矛探险队侵入了霜狼的领地。如果有一天我们可以让联盟从容地侵占部落的领地，那么我将会在那一天蒙羞自杀。出发吧，干掉入侵者！', '把1枚奥特兰克山谷荣誉奖章交给战场外的部落战争使者。', '在保卫奥特兰克山谷的过程中，你展示了无比的勇气!我会向我的上级汇报你的事迹。', '你从霜狼的地盘上带来了什么消息?现在奥特兰克山谷的战事进行得怎样了?', '', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8371, '共同的努力', '我们并不是在独自与部落交战，$g小伙子:小姑娘;。$B$B如果我们可以取得胜利，那么我们就可以使用部落的资源来在其它的战场上对抗他们。反之，如果我们输掉了这场战争，那么在其它的战场上，部落将会占有优势。$B$B联盟需要更多你这种身经百战、意志坚定的老兵！$N，当你在所有战场上都与部落交战之后再回到我这里。', '在每个战场上都取得1枚荣誉奖章，并将它们交给任意联盟主城、达拉然或沙塔斯城中的联盟准将。', '你没有让我失望，$N!你所学到的东西已经超越了奖章和表扬所能达到的范畴，它只有通过经验积累和在战场上的磨练才可以获得。$B$B你干得很好，$C。你是联盟真正的英雄!', '你做得怎么样了，$g小伙子:小姑娘;?', '', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8375, '铭记奥特兰克！', '不要搞错了，$N。部落认为奥特兰克山谷是霜狼氏族的领地，这种看法是很正确的。$B$B你看，雷矛探险队来这里是为了和平地搜索矿石和遗迹，而霜狼对此的反应却极其粗暴和不文明，这是联盟所没有预想到的。$B$B让我们为那些被偷袭的勇敢的矮人默哀吧。现在出发，$C，参加奥特兰克山谷的大战。为了联盟！', '把3枚奥特兰克山谷荣誉奖章交给战场外的联盟准将。', '你完成了你的任务，$N。联盟不会让部落的野蛮行为继续下去的!', '你带来了什么消息，$N?', '', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8385, '共同的努力', '', '', '你的声名远播，$N。如果没有你这样的人，联盟将无法对抗部落的野蛮攻击。', '啊，$N。我希望你在各个战场的前线传授你的经验。许多刚刚来到战场上的小伙子和小姑娘都非常尊敬你这样的老兵。', '', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8386, '自然屏障', '', '', '干得好，$N。感谢你，我们在灰谷的自然屏障又能安稳地度过一天了。', '不要忘记，在战歌峡谷中进行战斗不止是为了保护森林，更重要的是我们在保护灰谷和贫瘠之地之间的自然屏障。你有没有从战场带回什么消息，$N?', '', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8387, '奥特兰克的入侵者', '', '', '干得好，$N!你应该为自己感到骄傲。联盟入侵者必将被赶出奥特兰克!', '奥特兰克山谷的战斗正在激烈地进行中!你必须回到奥特兰克山谷，把入侵者赶出霜狼氏族的领地，$N!', '', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8388, '无上的荣耀', '', '', '你继续为部落带来荣耀，$N。我很高兴看到你还是一样的坚强。', '许多勇敢的士兵都非常尊敬你，$N。你一直是那些和联盟艰苦作战的勇士的榜样。你从旅途中带回了什么消息?', '', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8389, '峡谷中的战斗', '', '', '干得好，$C!在你的帮助下，部落取得了战歌峡谷的胜利!', '战歌峡谷的战事趋于白热化，$N。尽你的努力将银翼哨兵驱逐出我们的土地!', '', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8410, '元素掌握', '捕风者巴斯拉需要你这样充满智慧的萨满祭司。他要你带上每种元素的样本，证明你已准备就绪。$B$B你可以沿着塔伦米尔以东的河流往北走，巴斯拉就居住在沿途的一处废墟中。', '为捕风者巴斯拉收集一份空气样本、一份火元素样本、一份土元素样本和一份水元素样本。', '太棒了。我们谈谈吧。', '你为我带来了什么东西，$C?', '', '去奥特兰克山脉找冰风岗的捕风者巴斯拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8411, '控制元素', '欢迎。把元素交给我，然后我们再谈谈。$B$B火焰，空气，水，还有大地。把它们交给我，然后我才能相信你。', '将土元素、空气元素、火元素和水元素交给捕风者巴斯拉。', '这些是我需要的元素。我们谈谈吧。', '元素在那?', '', '去奥特兰克山脉找冰风岗的捕风者巴斯拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8412, '灵魂图腾', '这地方的元素灵魂不再欢迎我了。$B$B我们都熟悉图腾，现在我需要灵魂图腾来保护自己。它由四种元素和一些更原始、更接近自然的材料构成。$B$B你可以去西瘟疫之地获取熊爪和蜘蛛的眼球，另外有时食腐的鸟类也会掉落这两种东西中的任何一种，这取决于它们上一顿吃了什么东西……去吧，$N。', '将灵魂图腾所需的材料交给捕风者巴斯拉。', '太棒了，老兄!我们试试吧……$B', '灵魂们很清楚我们在干嘛，他们想要杀了我!我希望你能取得材料。', '', '去奥特兰克山脉找冰风岗的捕风者巴斯拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8413, '巫毒羽毛', '灵魂图腾还不够。我们还需要一些巫毒魔法来让它发挥效力。$B$B沉没的神庙中的巨魔身上有巫毒羽毛。去杀掉加什尔、米杉、祖罗、胡库、祖罗尔和洛若尔。这样我们就能拥有一个真正的、具有魔法力量的灵魂图腾了。', '将巫毒羽毛交给捕风者巴斯拉。', '现在，巨魔能好好睡个觉了!灵魂图腾会保护我的。$B$B我花了很多时间才收集到这些东西，或许你也想要一根图腾?', '羽毛在那?', '', '去奥特兰克山脉找冰风岗的捕风者巴斯拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8414, '驱散邪恶', '你好，$C。在这片荒无人烟的土地上，像你这样的十字军是受到欢迎的。$B$B我们需要借助你神圣的力量来消灭这里无穷无尽的亡灵。更重要的是，我们想让你收集大量的天灾石，将它们交给高阶牧师赛尔丹尼斯。赛尔丹尼斯就在距离此地不远的悔恨岭守护乌瑟尔之墓。$B$B只有佩戴银色黎明委任徽章的人可以找到天灾石，如果你没有徽章的话，就去跟军官普尔哈特谈谈吧。', '收集20个爪牙的天灾石，并将它们交给西瘟疫之地的高阶牧师赛尔丹尼斯。', '驱散天灾石的邪恶力量是有风险的，就算在万里之遥，它也能跟不死族有所感应。但是你拥有如此强大的力量，$N，我并不你担心……', '你带给我什么邪恶的东西?', '', '去西瘟疫之地找乌瑟尔之墓的高阶牧师赛尔丹尼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8416, '惰性天灾石', '天灾石上的邪恶力量已经被清除了，$N。$B$B我了解指挥官阿什拉姆的计划，他还需要一块惰性天灾石。把惰性天灾石带给他，或许我们就能以正义之火消灭亡灵天灾。', '将惰性天灾石交给冰风岗的指挥官阿什拉姆·瓦罗菲斯特。', '你成功地完成了我交给你的任务，$N。$B$B你赢得了我的信任。或许现在我可以告诉你更多计画的详细信息了。', '赛尔丹尼斯净化了天灾石吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8417, '困扰的灵魂', '在诅咒之地中有个受到困扰的灵魂，他生前曾是部落的一位伟大的英雄。战士的荣耀绝不会随着肉体的毁灭而消逝，如果可能的话，我希望你能帮帮他。', '到诅咒之地的入口去，与部落英雄的灵魂谈一谈。', '这么说，你是来解除我的痛苦的。希望这和打败我一样简单，但显然它不是……', '我对你很感兴趣，$C。你为什么来到这里?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8418, '铸造力量之石', '现在我们必须把惰性天灾石组合起来，制造一件可以击溃亡灵的武器。这不是一件轻松的任务，$n。只有沉没的神庙中的那些巨魔身上携带着的魔法才拥有这种力量，正所谓以毒攻毒。。$B$B我需要沉没的神庙里那些巨魔的巫毒羽毛。加什尔、米杉、祖罗、胡库、祖罗尔和洛若尔会掉落巫毒羽毛。不要为他们感到难过……他们是极端邪恶的存在。', '转至沉没的神庙，从巨魔守护者们身上取得琥珀巫毒羽毛、蓝色巫毒羽毛和绿色巫毒羽毛。', '太好了，$N。我有些吃惊，不过我知道你不会让我失望的。$B$B我很荣幸地将这块神圣力量之石交给你，好好使用它吧。', '你把那些邪恶的巨魔杀死了吗?', '', '去西瘟疫之地找冰风岗的指挥官阿什拉姆·瓦罗菲斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8419, '小鬼的要求', '$N，费伍德森林有个名叫伊普斯的小鬼让你去见他。这听上去有些奇怪，因为他让你带上一块恶魔布作为忠实的象征。既然你已经是个强大的术士了，那我想不用说你也知道费伍德的萨特身上有时会带着恶魔布吧？$B$B你可以在血毒瀑布以北找到伊普斯，我听说这个季节血毒瀑布非常漂亮。', '将一块恶魔布交给费伍德森林的伊普斯。', '你是个很棒的$C!$B$B<伊普斯将恶魔布贴在脸上。>$B$B哦，我喜欢这感觉，那种轻微灼烧皮肤的感觉，那种往你的心灵注入邪恶力量的感觉……', '你带来恶魔布了吗?', '', '去费伍德森林找碎痕谷的伊普斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8420, '灼热的疼痛', '或许一个小鬼说这话有些奇怪，但是我希望拥有自己的宠物。尼比把我当作宠物，我却没有宠物，这不公平！$B$B事实上，我并不需要什么活物。如果你能给我一块恶魔布的话，我就能制造一个宠物。这周围的萨特身上经常带着恶魔布，所以你可以去跟他们打打交道，你觉得如何？', '将一块恶魔布交给费伍德森林的伊普斯。', '啊!你真是太好了，尤其是对一个术士来说!$B$B<伊普斯将恶魔布贴在脸上。>$B$B哦，我喜欢这感觉，那种轻微灼烧皮肤的感觉，那种往你的心灵注入邪恶力量的感觉……', '你带恶魔布来了吗?', '', '去费伍德森林找碎痕谷的伊普斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8421, '奇怪的材料', '我已经有恶魔布啦，现在我可以开始制造*我的*宠物了。$B$B但是我还需要一些东西来制造宠物的眼睛。你能不能帮我从铁树上剥些腐烂的木头来？这样我才能雕刻出可爱的眼睛。我还需要血毒精华，让我的宠物具有恶魔的气息。被污染的软泥怪具有这种精华，他们就在我们附近出没。', '将10块腐烂的木头和4个血毒精华交给费伍德森林的伊普斯。', '这真是个好东西。', '我要的东西你带来了吗?', '', '去费伍德森林找碎痕谷的伊普斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8422, '巨魔的羽毛', '我的宠物差不多要制作完成了。现在我需要一些填充物。$B$B我需要沉没的神庙里那些巨魔的巫毒羽毛。加什尔、米杉、祖罗、胡库、祖罗尔和洛若尔会掉落巫毒羽毛。干掉他们。全部。$B$B这项任务可不简单，$N，我会送你一些尼比的东西——反正他似乎也用不着。', '到沉没的神庙去，从巨魔们身上获得6支巫毒羽毛。', '太好了，我的宠物制作完成了!$B$B<伊普斯很快将玩偶填充好，紧紧抱住它。>$B$B啊，这些巫毒羽毛拥有多么神奇的力量啊……', '你把羽毛带来了吗?这个玩偶需要填充物!', '', '去费伍德森林找碎痕谷的伊普斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8423, '战士的血脉', '<英雄注视着你。>$B$B毫无疑问，你是一位$C。我要给你一项光荣的任务，但是首先，你必须证明自己的力量。$B$B据说雷克萨检验他的战斧是否锋利的标准，乃是它能否一下斩杀一头地狱野猪。现在，我要通过让你杀死它们来证明你拥有足够的力量。', '杀死7头地狱野猪，然后回到部落英雄的灵魂那儿。', '我不需要你给我任何证据来证明你的所作所为，$C。我可以从你的行为看到决心。', '地狱野猪浑身都是令人毛骨悚然的伤疤。不要害怕疼痛和缺陷，$C，跟我现在所遭受的永恒痛苦相比，它们根本不算什么。', '', '去悲伤沼泽断矛路口找部落英雄的灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8424, '魔誓者之战', '我的存在本身就是个苦难，魔誓者更是为我带来了无穷无尽的痛苦，他们的黑暗仪式让我感到了比死亡还要可怕的苦楚。$B$B现在你可以帮我把痛苦带给他们。去吧，成为我的愤怒的象征。', '杀死诅咒之地的魔誓者，然后回到部落英雄的灵魂那儿。', '你减轻了我的痛苦并给予我荣耀，谢谢你，$C。', '要打败影誓者并不容易，是吗?但是你是个战士，要嘛获胜，要嘛死去。', '', '去悲伤沼泽断矛路口找部落英雄的灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8425, '巫毒羽毛', '你为我带来一丝平静。我得给你点什么作为回报。$B$B我的武器和护甲陪我度过了光辉的岁月，现在它们对我来说都没什么用处了。还是送给你吧。$B$B去沉没的神庙，杀死巨魔守卫加什尔、米杉、祖罗、胡库、祖罗尔和洛若尔。他们的巫毒羽毛能使我的肉身重现一段时间，足够给你奖励了。将巫毒羽毛带给我吧。', '将你从沉没的神庙的巨魔身上得到的巫毒羽毛交给部落英雄的灵魂。', '我终于又能感受到冰冷的钢铁了，尽管只有一下下而已。', '你这么快就回来了?时间对我的意义不太一样，或许对你而言，这是一次相当长的旅途……', '', '去悲伤沼泽断矛路口找部落英雄的灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8426, '峡谷中的战斗', '我们在战歌峡谷对银翼哨兵展开攻势，这一战役至关重要。联盟以保护这片不属于他们的森林为由，妄图从部落手中夺取我们最大的伐木场。$B$B别让他们的妄想成为事实，$N！为了部落，证明你的价值！成功之后再回到我这儿来。', '将3枚战歌荣誉奖章交给战场外的部落战争使者。', '太棒了!你在战歌峡谷保卫战中表现很出色!愿你的英雄事迹在我们的土地上流传开来。', '你有战歌峡谷的消息吗，$N?', '', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8427, '峡谷中的战斗', '我们在战歌峡谷对银翼哨兵展开攻势，这一战役至关重要。联盟以保护这片不属于他们的森林为由，妄图从部落手中夺取我们最大的伐木场。$B$B别让他们的妄想成为事实，$N！为了部落，证明你的价值！成功之后再回到我这儿来。', '将3枚战歌荣誉奖章交给战场外的部落战争使者。', '太棒了!你在战歌峡谷保卫战中表现很出色!愿你的英雄事迹在我们的土地上流传开来。', '你有战歌峡谷的消息吗，$N?', '', '去找部落战争使者。', '', '', '', '');
