INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8435, '峡谷中的战斗', '', '', '干得好，$C!在你的帮助下，部落取得了战歌峡谷的胜利!', '战歌峡谷的战事趋于白热化，$N。尽你的努力将银翼哨兵驱逐出我们的土地!', '', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8446, '梦魇的缠绕', '这东西了渗出堕落的力量。$B$B它和来自翡翠梦境的龙类或许有些关系。你必须找到能解读这东西的人。或许月光林地或是塞纳里奥要塞的德鲁伊能帮助你。', '寻找能解读梦魇包裹的物品中所隐藏的信息的人。$B$B或许拥有强大力量的德鲁伊可以帮助你。', '我必须将污染从这东西上清除。这或许对翡翠梦境的研究工作有所帮助。把它给我。', '怎么了，$r?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8460, '木喉熊怪的盟友', '木喉部族是唯一没有被堕落力量污染的熊怪部族。然而，许多其它的种族盲目地屠杀熊怪，却并没有搞清他们是敌是友。因此，木喉熊怪很少相信别人。$B$B你想要证明自己的立场吗？去赶走腐化的死木部族，我们以后也许会接受你成为盟友。你可以在费伍德的南部找到死木战士、探路者和园丁。', '格拉兹要你去杀死6个死木战士、6个死木探路者以及6个死木园丁。', '我们在过去的事件中遭受了很多痛苦。谢谢你为帮助保护木喉部族所做的一切。$B', '加油，$N。如果你想赢得我们的信任，你就需要向我们证明你的能力。', '', '去费伍德森林找翡翠圣地的格拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8461, '北方的死木熊怪', '此地西南方向有一处死木熊怪的营地。我不清楚他们想要干什么，但是我希望能在他们开始捣乱之前就结果他们。$B$B死木部族非常邪恶，是恶魔的力量侵蚀了他们的心智。他们的天性并不坏，但是现在一切都无法挽回了。因此，我对被迫与自己的同胞作战感到非常悲哀。$B$B$N，去结果他们吧，别对我说起战斗的具体过程，我不忍心听到那些。', '格拉兹要你去杀死6个死木守卫、6个死木复仇者和6个死木萨满祭司。', '很高兴你回来了，$N。我希望死木部族对你而言并不难对付。$B', '一旦你获得了木喉部族的信任，作为对你的忠诚的回报，也许我们可以帮你做点什么。', '', '去费伍德森林找魔爪村附近的纳菲恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8463, '不稳定的法力水晶', '最近有一伙失心者从我们的奥术圣殿那边劫走了一批极不稳定的法力水晶。如果不能妥善处置的话，那些水晶恐怕会引起爆炸，威力大得足以在城墙上开个洞出来。$B$B至于那些该死的家伙们是否会在从水晶中抽取法力时被炸飞，我一点都不关心了，但整件事情仍然让我脸面上很挂不住。$B$B把剩下的水晶给我找回来，它们或许还在原来的箱子里。', '给鹰翼广场的艾尔杜·炙痕带回6块不稳定的法力水晶。', '做的好，$N。', '你拿回被偷走的物品了没?', '', '去永歌森林找鹰翼广场的艾尔杜·炙痕。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8464, '冬泉熊怪的活动', '木喉部族倾向于防守，$N。虽然我们允许那些值得信赖的朋友安全地通过，但我们还是尽可能地避开其它熊怪部族。$B$B最近我注意到冬泉部族与我们的敌对情绪有所增长。他们似乎处于极度愤怒的状态，完全陷入了对一切他们无法理解的事物的恐慌和仇视。$B$B如果你能削减他们的数量，那对我们来说将是莫大的帮助，$N。', '萨尔法要你去杀死8个冬泉萨满祭司、8个冬泉巢穴守卫和8个冬泉巨熊怪。萨尔法就站在冬泉谷的木喉要塞入口处。', '感谢你所做的一切。请收下这枚感谢的硬币。$B$B请继续帮助我们，$N。我们的盟友很少，若你不再帮助我们，威胁我们部族的危险会增强到我们无法抵抗的地步。$B', '我们很感激你为木喉部族所做的一切，$N。', '', '去找冬泉谷的萨尔法。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8466, '给格拉兹的羽毛', '', '', '做的好，$N!我会让我的族人都知道你的行为。$B$B记得把你找到的羽毛带给我。只要还有需要，我会继续收下它们。$B', '虽然你已向我证明自己的来意，你还需要继续努力向我部族怀疑的兄弟们证明你自己。只有这样，我才能继续帮助你。$B$B有些死木熊怪戴着特殊的头饰，可以作为削减他们势力的证据。带给我你从任何头饰上取得的羽毛;你每给我一套5个，就会赢得木喉的信赖。', '', '去找费伍德森林的格拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8467, '给纳菲恩的羽毛', '', '', '做的好，$N!我会让我的族人都知道你的行为。\r\n\r\n记得把你找到的羽毛带给我。只要还有需要，我会继续收下它们。', '虽然你已向我证明自己的来意，你还需要继续努力向我部族怀疑的兄弟们证明你自己。只有这样，我才能继续帮助你。$B$B有些死木熊怪戴着特殊的头饰，可以作为削减他们势力的证据。带给我你从任何头饰上取得的羽毛;你每给我一套5个，就会赢得木喉的信赖。', '', '去找费伍德森林的纳菲恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8468, '通缉：饥饿者泰里斯', '银月城政府在此发布公告，悬赏声名狼籍的失心者团伙头目，饥饿者泰里斯。他因涉嫌参与包括谋杀两名城市卫队士兵在内的多起危害广大银月城人民群众的恶性案件而被通缉。$B$B请向坎雷中士报告以领取赏金。', '将泰里斯的徽记交给永歌森林鹰翼广场的坎雷中士。', '那个恶棍泰利斯终于走到生命的尽头了。做的好，$N。这下鄙恶者总算能安静一会儿了。', '你有东西要给我瞧瞧吗?', '', '去永歌森林找鹰翼广场的坎雷中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8469, '给萨尔法的珠串', '', '', '你再一次的向我们证明了你的信誉!我会让我的族人都知道你的行为。$B$B记得把你找到的冬泉谷珠子带来给我。只要你把一套珠子给我，我就会继续为你向部族说些好话。$B', '你无疑地得到了我的信任，$N，但你仍要努力得到我整个部族的信任。拜托…让我继续帮助你。$B$B冬泉谷的人都会配戴灵魂珠子来避开邪恶的灵魂。但这些珠子显然失去了它们的意义，因为冬泉谷的人就是腐败的媒介。帮我从冬泉谷熊怪那里带来这些灵魂珠子;你每给我一套5个，就会赢得木喉的信赖。', '', '去找费伍德森林的萨尔法。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8470, '木喉熊怪的盟友', '你找到了一根死木仪祭图腾。图腾本身没有什么雕刻的痕迹，但是一种让人绝望的感觉却在其中不断地散发。如果有什么东西导致了死木熊人的堕落的话，那么这件东西貌似就是罪魁祸首了。$B$B木喉要塞中的某个熊人一定会用它……当然，你首先需要赢得和他们交谈的声望。', '把死木仪祭图腾带到木喉要塞然后看看是否有熊人可以使用它。木喉要塞的熊人只有当你的声望达到中立或者更高的时候才会和你说话。', '这个图腾…我知道它是死木部族的东西，但是它发出浓烈的腐败恶臭。让我们的手足与我们反目成仇的邪恶东西一定就在这个物体里。$B$B你把这个拿来给我们是很明智的行为，$N。或许透过研究和仪式，我们可以了解是什么污染了我们手足的心智。谢谢你，朋友 –', '$C，我可以帮你什么忙吗?你平静地走在我们之中，虽然一定有什么事情出错了。我感觉到什么东西…麻烦的东西…', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8471, '木喉熊怪的盟友', '你找到了一根冬泉仪祭图腾。图腾本身没有什么雕刻的痕迹，但是它却散发出一种让人绝望的气息。如果有什么东西导致了冬泉熊怪的堕落的话，那么这件东西应该就是罪魁祸首了。$B$B木喉要塞中的某个熊怪一定对它有兴趣……当然，你首先需要在他们当中赢得一定的声望。', '把冬泉仪祭图腾拿到木喉要塞去，看看是否有熊怪想要研究一下它。只有当你在木喉要塞的声望达到中立或者更高级别的时候，木喉要塞的熊怪才会和你说话。', '这个东西…它是冬泉仪式图腾的形状，但是它被我无法理解的力量给扭曲了。让冬泉部族与我们反目成仇的邪恶东西一定就在这个物体里。$B$B你把这个拿来给我们是很明智的行为，$N。我们会仔细研究这个物体;或许有一天，冬泉部族将不会再与我们为敌。$B$B谢谢你，朋友 – 请收下这个以答谢你的恩惠。', '$C – 你以平静的姿态向我们走来，但我可以感觉你是为了沉重、严肃的事而来…因为熊怪和$r是相似的。你有什么事要告诉我们?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8472, '失效的傀儡', '在旧城区的废墟里，有一些原本负责保卫城市的奥术傀儡最近因为年久失修而失去了控制。它们已经无法辨认出自己的主人，只要见到我们就会立即对我们发起攻击！$B$B尽管它们是很多年前制造出来的，但它们体内用于驱动机关运行的奥术核心仍然对我们很有价值。我希望你能为我回收这些奥术核心，我想它们还可以在某些地方派上用场。这些傀儡在西北方的银月城废墟中到处都是，很容易找到。', '从游荡在银月城遗迹中的奥术巡逻者身上获取6枚奥术核心，把它们交给永歌森林鹰翼广场的魔导师亚隆尼斯。', '你做的很好，$N。我们尽全力去运行秘法圣所，这些能量核心将足够供应我们的需求好长一段时间。', '你有顺利收集完秘法核心吗，$N?', '', '去永歌森林找鹰翼广场的魔导师亚隆尼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8473, '痛苦的抉择', '这些日子对我们来说，真是一段艰难的时刻，$N。为了防止天灾军团的扩张，我们必须烧毁永歌森林与幽魂之地边境处的森林，这无疑是个艰难的抉择。$B$B而最近，那些过去几年中还曾是我们朋友的树人，正在尝试着重新培育焦痕谷周围的树木。$B$B这是个令人痛苦的抉择，$c，但我们已经无法说服这些曾经的盟友放弃他们的做法了。我要求你立刻阻止他们，而你唯一可用的手段，就是武力。', '在焦痕谷一带杀死10名枯萎的护卫者，然后向永歌森林焦痕谷西北方的高塔内的拉莉亚娜·河风复命。', '所以，都结束了。诅咒这时代使我们逼近绝望的手段…并诅咒我们的敌人，天灾军团!$B$B你要知道，$N。我们一定要保护国土，不论花多少代价。我们要战胜一切!', '我不太敢问，$N……任务完成了吗?', '', '去永歌森林找金枝小径的拉莉亚娜·河风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8474, '怀特巴克的坠饰', '坠饰上刻着两个字“河风”。\r\n 或许这两个字可以告诉你谁是这个坠饰的制造者。', '寻找制造怀特巴克的坠饰的人。他们或许会提供一些关于这件物品的线索。', '这个……这个坠饰。之前因为老白树帮我们重建村庄，所以把这个送给他当礼物。$B$B我想你会将它还给我，想必他是……$B$B<血精灵清了清她的喉咙镇定自己。>$B$B谢谢你带回来，$N。我想一个人静一静。', '你有东西要给我瞧瞧吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8475, '死亡之痕', '满目葱绿的永歌森林中，那道丑陋的黑色伤痕无时无刻不在提醒着我们：要铭记阿尔萨斯入侵我们心爱的城市的那段屈辱的日子。$B$B这些污瑕不仅仅是我们的眼中钉，最近这几天也总是吸引着幽魂之地的天灾军团向银月城这边移动。$B$B去吧，$N，帮助我的手下把那些在死亡之痕游荡的亡灵全部消灭掉，这样我或许会感觉好过些。', '杀死8个瘟疫骨骸，然后向永歌森林死亡之痕的游侠杰拉复命。', '我们不期望能对天灾军团先发制人，但我们仍感谢任何保卫断崖的援助。', '你回来了，$N。你击退了死亡之痕的不死族吗?', '', '去永歌森林找死亡之痕的游侠杰拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8476, '阿曼尼的进犯', '我们的王国所占有的领土并不像人类与兽人的那样广袤。我们在艾泽拉斯大陆上仅剩的土地基本上都已经在你眼前了，$N。$B$B在我们能够抵达外域，并在那里找到新的家园之前，我们必须不惜一切代价守护住这片小小的土地。$B$B东南方那些未开化的阿曼尼巨魔正对我们的土地虎视眈眈，我们已经彻底无法再容忍他们的骚扰了！到他们的居住地塞布瓦萨和托尔瓦萨去，给他们点颜色看看。', '永歌森林远行者居所的达恩·晨行者中尉要求你杀死5名阿曼尼狂战士和5名阿曼尼掷斧者。', '做的好，$N。有越多像你这样的人我们就能越快让我们的土地重返荣耀。', '你在东南方可以找到拉伯瓦萨，杀掉巨魔再回来。', '', '去永歌森林找远行者居所的达恩·晨行者中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8477, '制矛师之锤', '阿曼尼巨魔和辛多雷在历史上素来敌对，早有许多大规模的战争。但这并不妨碍我对他们的一些工艺作品的欣赏之情，$N。$B$B我曾使用过几件阿曼尼武器，它们在金属工艺上的造诣给我留下了深刻的印象。据说制矛师奥特姆比有一把魔法锻造锤，非常轻盈，平衡性也非常好，这使得他在工作时可以充分发挥自己的灵巧与技艺。$B$B如果你能把这件工具带回来给我的话，我可以用它为你打造一件武器。', '到远行者居所东南方的托尔瓦萨去，找到制矛师奥特姆比，将奥特姆比之锤带回远行者居所去交给阿拉瑟尔。', '有些谣言是真的，$N。这铁锤同时具有轻巧却强大的力量;而我还有几个工作没完成。当然，我会让你第一个挑武器。', '你有带回欧坦毕之锤给我吗，$N?', '', '去永歌森林找远行者居所的阿拉瑟尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8479, '祖玛洛什', '过来，朋友。别害怕，文亚什是不会伤害你的。$B$B我们暗矛部族同样也是阿曼尼巨魔的敌人，跟你一样。他们的头儿祖玛洛什是个邪恶的巨魔，他给我喂了毒药，把我扔在这个笼子里等死。$B$B我并不是怕死，朋友。就算死神来到我面前我也是要大声嘲笑她的。$B$B但我告诉你，$c，如果祖玛洛什没死，我就算是死了也不会瞑目。我会一直在这里坚持下去，直到你给我带来他的徽记，朋友。只有那样我才能安心上路。', '被囚禁在托尔瓦萨的巨魔俘虏文亚什要求你把祖玛洛什酋长的徽记交给他。祖玛洛什酋长居住在艾伦达尔湖对岸的塞布瓦萨。', '对了，兄弟。祖玛罗什来过。他烧毁了凡加许的村子，而我在他们抓我进牢笼前也杀了很多阿曼尼人。我在沙子里藏了一个东西，是我要给你的礼物。$B$B啊……啊，毒性……已扩散全身了。该安息了……', '你带回祖玛罗什头颅了没?', '', '去永歌森林找托尔瓦萨的文亚什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8480, '失落的军备', '看起来，失心者的数量每日都在增长，$N。他们甚至已经相互联合起来，在统一的指挥下对阳帆港发起了一次攻击。$B$B更令我们游侠部队感到窘迫的是，我们的大部分武器都在他们攻占港口时遗落在了那里。把我们的武器带回来，这样我们就可以让那些该死的无赖知道谁才是老大了！', '将8个辛多雷军备物品交给永歌森林的维雷迪斯·雪晨。', '做的太棒了，$N。让鄙恶者看看我们的厉害!', '你收集好丢失的武器了吗?', '', '去找永歌森林的维雷迪斯·雪晨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8481, '万恶之源', '$N，感谢你的帮助，我们已经找到了致使冬泉部族堕落的根源——有一个堕落的恶魔正在控制着他们！$B$B把这支火炬拿到冬泉酋长所在的山洞去，然后放在那里。这样就可以让那个恶魔现身。此时你和你的盟友就要把它击倒！只有使用恶魔身上的精华才能帮助我们进行治愈冬泉部族的工作……最终解除他们对木喉要塞的威胁。', '把恶魔召唤火炬放在寒水村的冬泉酋长的洞穴入口处。击败召唤出来的恶魔，然后把沙迪维尔斯精华交给木喉要塞的独眼高恩。', '你…你救了我们!你击败了沙迪维尔斯，确保木喉要塞未来多年的安全。你真是我们族人的英雄。$B$B拜托你收下这个，是我们的祝福。虽然熊怪的治疗过程会很缓慢 – 而冲突仍然会发生 – 你仍给了冬泉部族从未拥有过的东西。$B$B他们有机会生存了。', '你回到我们这里了，$N…这代表恶魔已经被杀死了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8482, '秘密文件', '这份文件中包含着永歌森林中数座极富战略意义的建筑物的详细地图，更有一份关于奥术圣殿的详细建筑结构图表。图的下方还有数行用某种你不认识的语言写成的注释，看起来十分缜密。$B$B既然这份文件是你从一个达纳苏斯方面的间谍那里找到的，或许把它交给卫兵队长艾尔杜·炙痕是最正确的选择。', '将秘密文件交给永歌森林鹰翼广场的艾尔杜·炙痕。', '你确定你在夜精灵身上发现这些吗?他们以矮人文字清楚的记载着……$B$B就我所了解这封信的内容，不管写信的人是谁，都不是他造成运作的不良，他只是个被派来这里观察结果的间谍。他们说我们的行为鲁莽又危险……但会是谁?$B$B没错!就是那个铁炉堡的使者!我们实在是太愚蠢了，竟然会完全相信联盟的所有人!', '你有带东西给我吗?让我瞧瞧。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8483, '矮人间谍', '听着，$N。当前的事态很敏感，就算我们已经知道他的间谍身份，但我们仍然不能公开地处死他。我们也不能尝试逮捕他，如果被他逃走，那么风险就太大了。$B$B我希望你立刻转至北部圣殿，找到勘测员安威瓦尔德，并秘密刺杀他。做这件事的时候要注意保密，我们也不想让“城市内有个间谍”这样的消息流传出去。$B$B带回他的徽记作为证明。铁炉堡应该学会不要和辛多雷作对！', '将安威瓦尔德的徽记交给永歌森林鹰翼广场的艾尔杜·炙痕。', '好，任务已完成。你真是优秀。$B$B话已传到游侠将军耳边，相信我，矮人要为他们的背叛付出极高的代价。$B$B你已为你的人民立下很大的功劳和贡献，$N。', '你有管好入侵者吗?', '', '去永歌森林找鹰翼广场的艾尔杜·炙痕。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8484, '重铸和平', '你的事迹已经远远超过英雄的范畴，$N。如果你代表了你的人民，那么我们一定会努力和你的人民保持和平。$B$B请你把这个交给住在钢铁之山中的那位矮人国王，我想你们把那里叫做铁炉堡。过去，他曾经代表联盟试图和我们创建联系。现在我们需要依赖你来实现木喉部族与联盟之间的和平。', '将木喉和平契约交给铁炉堡的国王麦格尼·铜须。', '的确，这是最幸运的事了。如果这些生物能维持永远的和平，对我们在卡利姆多的事务很有助益…这项事务是夜精灵们无法自行解决的。我会立即通知其它联盟的领导者，并会发送进一步的公文!$B$B至于你，$N…你在外交手腕和行为上都表现了你的勇气。谢谢你，整个联盟也感谢你。', '$C，我的领地欢迎你。铁炉堡永远是像你这样的英雄的家。现在，你找我有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8485, '重铸和平', '你的事迹已经远远超过英雄的范畴，$N。如果你代表了你的人民，那么我们一定会努力和你的人民保持和平。$B$B请你把这个交给住在杜隆塔尔的兽人酋长，我想你们把那里叫做奥格瑞玛。过去，他曾经代表部落试图和我们创建联系。现在我们需要依赖你来实现木喉熊怪和部落之间的和平。', '将木喉和平契约交给奥格瑞玛的萨尔。', '的确，这是个偶然又幸运的转机。盼和平永随这些生物，这一定会让我们在保卫卡利姆多上占优势，以免于外在威胁。我会立刻通知部落其他首领，并派遣外交使节!$B$B至于你，$N…你已在外交及行动上展现了勇气。我和全部落都感谢你。$B', '大酋长向你问好，$C。在这混乱时代，你的功绩让部落日益茁壮。现在，有什么事要与我讨论吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8486, '不稳定的奥术', '真是时候啊！居然凯丹尼斯在这个关口派了人过来。$B$B我早就警告过他们西部圣殿负荷加剧的危险性了！现在，我们为数不多的几个能量转换装置里又有一个彻底毁坏了，而且法力怨灵也跑了出来，满地都是！$B$B在我们派人修理这里之前，我需要你帮我处理这些该死的生物。快点！', '魔网监护者薇兰妮亚要求你杀死5只法力怨灵和5只法力漫步者。', '谢谢你，$N。因为秘法怨灵受制，我们才能重建牧地圣所。希望牧地水流不再遭受持续的伤害。', '你杀死那些秘法怨灵了吗?', '', '去永歌森林找西部圣殿的魔网监护者薇兰妮亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8487, '被腐蚀的土地', '在阿尔萨斯和天灾军团在森林里犁出一条通向银月城的路之前，这里曾是一座功能完备的奥术圣殿。$B$B可是现在，它已经和死亡之痕里的其它东西一样对我们毫无用处了。土地被腐蚀，亡灵被这腐蚀的土壤源源不断地吸引而来，而魔网管道中的能量也被污染了。$B$B现在我最想知道的事，$N，就是这种腐蚀是否可逆。我要你从这个区域中收集一些土壤样本来供我研究。或许不久之后，我们就能让这片土地恢复健康。', '永歌森林东部圣殿的学徒米尔维达要求你收集8堆被污染的土壤样本。', '太棒了。我要对样品施法，这样才能好好解析土壤的腐败。', '你收集好我要求的样品了吗，$N?', '', '去永歌森林找东部圣殿的学徒米尔维达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8490, '增强防御', '在永歌森林的边界曾经有数十块古老的符石组成结界，封闭国土以免外敌入侵。这些符石在阿尔萨斯入侵时大多被损坏了，还有一些被偷走了。$B$B当前，还有三块符石遗留在那里，这三块中，也只有一块仍然维持着能量。这块符石就在东边，或许它还有挽救的馀地。$B$B把这块水晶带过去，将里面的能量小心地注入东部符石中。这个过程或许会需要一些时间，所以你要有耐心。此外，你还得小心，附近的天灾军团士兵或许会被它吸引过去。千万不要让它们摧毁符石。', '将魔能水晶放置在东部符石上，并确保它在1分钟之内免遭天灾军团的攻击。之后将魔能水晶交给永歌森林的符文看守者德尔雅，以换取你的奖励。', '很好。这样就能防守天灾军团更久些。谢谢你助我们一臂之力，$N。', '你成功的增强符文石了吗，$N?', '', '去永歌森林找法利萨斯符文石的符文看守者德尔雅。', '给符石充能', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8491, '收集豹皮', '栖息在这一地区的魔泉豹以它们高质量的毛皮而知名，我们甚至曾见过一些卑贱的暗夜精灵猎人跑到这一地区来狩猎它们。$B$B当前，我们与阿曼尼巨魔之间的形势十分紧张，已经发生了多起冲突事件，这也导致我们的游侠必须随时待命，不再有时间去狩猎豹皮，可是装备又很紧缺……$B$B如果你愿意帮忙收集一些魔泉豹皮的话，我将可以送给你一件我亲自制作的护具。你可以在北边的林地附近找到很多魔泉捕猎者。', '永歌森林晴风村的维兰·布雷托克要求你帮他收集6张魔泉豹皮。', '这些会非常有用，$N。请收下这个护甲做为奖励。我会用你带来给我的毛皮做更多护甲。', '你回来了，你有带那些毛皮吗?', '', '去永歌森林找晴风村的维兰·布雷托克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8492, '联盟需要铜锭！', '你好，$c，看来你很合适为我们的备战计划做出点贡献！我们欢迎一切帮助来准备安其拉之战。$B$B为了这样一件有意义的事情，我正在收集20块一组的铜锭。你觉得怎么样？', '把20块铜锭交给丹莫罗飞机场的布罗恩·石眉。', '你成功了$g小伙子:小姑娘;!我们会将那些铜锭堆放好并立刻做成有用的战器。就是有你这样的人努力才让我觉得为联盟效力是骄傲的。做的好，士兵!', '你收集好那20个铜锭了吗?', '', '去找丹莫罗的布罗恩·石眉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8493, '联盟需要更多铜锭！', '又回来了，$c？太好了！我们还需要大量的铜锭，为了准备安其拉之战，请尽你所能地帮我收集铜锭。你愿意帮帮我们吗？', '把20块铜锭交给丹莫罗飞机场的布罗恩·石眉。', '做的好!到处挖铜一定是个很大的冒险吧。除非你是在拍卖场买到它们的。反正，我都需要它们。你对战事的贡献会受到表扬的$C。', '又回来了$C?太好了!我们还需要大量的铜锭，为了准备安其拉之战，请尽你所能地帮我收集铜锭，这些铜锭是要用来建造蒸汽坦克跟旋翼机，$B$B我们为了安其拉战役，真的还需要更多铜锭，你愿意帮帮我们吗?', '', '去找丹莫罗的布罗恩·石眉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8494, '联盟需要铁锭！', '你好，$g先生:小姐;，你不是传说中云游四海，无所不知的那种冒险者吗？最近的事情你都不知道？联盟正在准备对安其拉发动战争，我们需要大量的铁锭，越多越好。把它们带给我，每20块一组。我们会在功劳薄上为你记上一笔，怎么样，$c？', '把20块铁锭交给丹莫罗飞机场的卡恩斯下士。', '嗯，嗯，多亏了你$N。你渡过难关了。我想现在我要多注意你。我不想这么说，但是谢谢你的帮忙。联盟不会忘记，我也不会。现在快离开这里去看看还有什么需要收集。', '如果你收集到那20个铁锭，我可不想发现你把它们都藏起来了!', '', '去找丹莫罗的卡恩斯下士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8495, '联盟需要更多铁锭！', '这么快就回来了？请不要试图让我改变鄙视你的想法，$c，你让我感到难受。那么，你是否可以告诉我，为什么我们还没有足够的铁锭来制作所有必需的武器、护甲和蒸汽坦克这些战争装备呢？你是否可以在这几天去祖尔格拉布或者别的什么地方的路上顺手收集20块铁锭？', '把20块铁锭交给丹莫罗飞机场的卡恩斯下士。', '燃烧平原那里一定是个寒冷的天气。看这里，是$N，而且$g他:她;给我带来了一个礼物。20个铁锭!正是我一直想要的。$B$B我真的万分感谢你，$N。你是自己也是联盟的荣誉。现在离开这里去收集更多战争需要的东西吧。', '这么快就回来了?不要让我再重新评估对你不好的看法$C，你让我觉得很感伤。那么，你知道我们仍然没有足够的铁锭供应武器、护甲、蒸汽坦克和搜寻故障所有需要的东西。你觉得你可以在去祖尔格拉布的路上，或是你们这些孩子现在鬼混的地方带回另一批20个铁锭吗?', '', '去找丹莫罗的卡恩斯下士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8496, '战场上的绷带', '我们的绷带储备在最近接连不断的战事之后急剧降低。收集大量的急救物资，把它们交给塞纳里奥要塞的唤风者梅恩·长角。', '把30根厚符文布绷带、30根厚魔纹绷带和30根厚丝质绷带交给唤风者梅恩·长角。你还必须随身带着后勤任务简报 X才能完成这个任务。', '来的正好。这些补给能救回性命，$N。我们感谢你的努力。这是你的下一个任务。', '你有东西要给我吗，$N?', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8497, '沙漠生存包', '当前塞纳里奥要塞涌入了大量的新兵，我们的首要问题就成了如何保证他们在沙漠中生存下来。缺水的环境和遍布希利苏斯的剧毒生物都威胁着这些缺乏经验的志愿者。去收集一些必需的物资，把他们交给要塞里的卡兰德拉斯吧。', '把4份纯水之球、4份特效抗毒药剂和4份烤鲑鱼交给希利苏斯塞纳里奥要塞的卡兰德拉斯。你还必须随身带着后勤任务简报 I才能完成这个任务。', '很好。我们正需要这些，$N。做的好。', '你有东西要给我吗?', '', '去希利苏斯找塞纳里奥要塞的卡兰德拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8498, '暮光作战命令', '我们的侦察兵报告暮光之锤的领袖收到了新的战斗命令。现在这个命令正被重兵把守着发送到各个暮光先知那里。拦截这封命令然后把他们带给指挥官玛尔利斯。', '拿到暮光作战命令然后带给希利苏斯塞纳里奥要塞的指挥官玛尔利斯。', '很好。比敌人抢先一步是很重要的。这项消息可以让我们预测暮光之锤的攻击。', '你带了什么东西要给我吗?', '', '去希利苏斯找塞纳里奥要塞的指挥官玛尔利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8499, '联盟需要瑟银锭！', '你能主动关心联盟需要什么东西，这真是太好了。除了现在正在收集的各种物资之外，我们还需要大量的瑟银锭，我将负责这方面的收集。所有的瑟银都将用于制作各种战争必需的物资，特别是用来制造一个军团的蒸汽坦克，准备进攻希利苏斯。你能帮帮我吗，$c？', '把20块瑟银锭交给丹莫洛飞机场的达米。', '喔，谢谢你，$C!谢谢你!这样就完成了20个，还有无法估计的数量要收集。你赢得联盟的感谢，你的努力会得到应有的奖励。等你收集更多的瑟银锭再次与我交谈吧。', '我希望你已经成功收集好我们之前讲的瑟银锭了。', '', '去找丹莫罗的达米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8500, '联盟需要更多瑟银锭！', '很高兴再次见到你。我希望你一切安好。如你所见，我们仍然需要瑟银锭。如果你有多馀的瑟银锭的话，可以把它们捐出来，好让我们为安其拉战争作准备。', '把20块瑟银锭交给丹莫洛飞机场的达米。', '很好，$C!做的很好。我会看着那些瑟银锭被放入机器并在铁匠和工程师的手上变成军队的补给。再次谢谢你，如果你有更多瑟银锭记得拿给我。', '能再见到你真好，$N。希望你一切都好。我们现在还需要瑟银锭。如果你有的\r\n话请分给我，我正在为安其拉之战收集。', '', '去找丹莫罗的达米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8501, '目标：亚什毒蝎', '这一地区猖獗的异种虫类对我们来说是个巨大的威胁。你被指派负责对亚什虫巢发动攻击，主要目标是亚什毒蝎。$B$B在你的任务完成之后，向指挥官玛尔利斯汇报。', '击杀30只亚什毒蝎，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 XII才能完成这个任务。', '干得好，$N。你在亚什虫巢攻击行动中的卓越表现已经引起了关注。', '你有什么事要跟我说吗，$N?', '', '去希利苏斯找塞纳里奥要塞的指挥官玛尔利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8502, '目标：亚什工蝎', '这一地区猖獗的异种虫类对我们来说是个巨大的威胁。你被指派负责对亚什虫巢发动攻击，主要目标是亚什工蝎。$B$B在你的任务完成之后，向指挥官玛尔利斯汇报。', '击杀30只亚什工蝎，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 III才能完成这个任务。', '做的好，$N。少了他们的工蝎，异种蝎就很难修补他们虫巢结构所受的伤害。', '你有事要告诉我，$C。', '', '去希利苏斯找塞纳里奥要塞的指挥官玛尔利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8503, '联盟需要荆棘藻！', '那么$c，我是否告诉过你荆棘藻的所有用处？有没有说过？哦，好吧……不管怎么样，我们需要很多荆棘藻，我说很多的意思就是非常非常多！你可以帮帮我吗？我知道这意味着你无法用它来制作许多你需要的东西，但是我们是在为了正义的事业而努力！', '把20棵荆棘藻交给丹莫罗飞机场的列兵德拉里格。', '万岁!又少了20个。你是最棒的。来看看，我要怎么奖励你?首先我要将你的名字写在我的名单中然后再将它传给别人，让大家都知道你的贡献。再次的感谢你$C!', '这不是真的!我从来没有将这些堆积物上面的荆棘藻去除过。有人可能会认为它几乎就是经济利义下有效的万灵丹。*咳咳*你不会正好有我们先前谈的荆棘藻吧?', '', '去找丹莫罗的列兵德拉里格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8505, '联盟需要紫莲花！', '$c，紫莲花是一种非常有用的植物。我在这里作为联盟的官员收集紫莲花，我要负责监督整个收集过程，并保证在战时有足够的紫莲花储量可供使用。$B$B我希望你可以到世界各地帮我带回一些紫莲花。你可以做到吗？', '把20朵紫莲花交给丹莫罗飞机场的艾文·夜歌。', '我们非常感谢你的贡献，$C。只有大家同心协力才能将无情的异种发展和所有驱使他们的力量击退。就连部落也都在收集他们自己的紫莲花。如果你收集得够多，请带到这里给我。', '你有我要的紫莲花草药了吗?', '', '去找铁炉堡的艾文·夜歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8507, '战地任务', '你好，$N。在我为你布置更重要的任务之前，你需要首先完成一些常规的战地任务。$B$B你可以在佐拉虫穴外找到布莱卡维尔上尉的部队。$B$B向他或者他的副官珍妮拉·钢锤报到，然后回到我这里来。那时我将会给你下达进一步的指令。$B$B哦，别忘了离奥格瑞玛军团远一些。由于这两股势力之间的互相仇视，我们被迫把他们分开来。', '向佐拉虫巢外的铁炉堡军团报到，从布莱卡维尔上尉那里拿到签过字的战地任务文件，把它交给希利苏斯塞纳里奥要塞的唤风者卡尔东。$B$B注意：给铁炉堡军团的士兵治疗或者施放增益法术会打开你的PvP标志。', '很好，$N。我已准备了一系列最适合你的技能的任务。$B$B有你和像你这样的人继续努力，我们的敌人很快就会被击败了!$B$B要取得新的任务简报，回去找布莱卡维尔上尉。', '你可以在佐拉虫巢外找到布莱卡维尔上尉的军队。和他的中尉，珍妮拉.顽锤谈谈，如果你能找到他的话。', '', '去希利苏斯找塞纳里奥要塞的唤风者卡尔东。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8508, '战地任务文件', '', '', '啊，我想刚才经历了那场小遭遇战也可以被称为完成了一项“战地任务”吧。把这些带回塞纳里奥城堡去，我相信他们一定会有重要任务给你的。$B$B快出发!', '我会拿到那些你想要的已签字文件，$G小伙子:小姑娘;?', '', '去找希利苏斯的布莱卡维尔上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8509, '联盟需要阿尔萨斯之泪！', '我会简要地告诉你重点，$c。联盟需要大量的阿尔萨斯之泪来准备安其拉战争。不要问我它们是用来做什么的，我并不关心这个。但是我需要你收集尽可能多地这种草药，并把它们交给我。你愿意这样做吗？', '把20棵阿尔萨斯之泪交给铁炉堡军事区的士官长戈麦恩。', '做的好，$C。我必需说我真的有点惊讶。让我把它们装进木箱里并标上你的名字，然后再来谈谈我是否需要更多那些植物。', '那是什么?大声的说出来，$C!你拿到我要的阿尔萨斯之泪吗?', '', '去找丹莫罗的士官长戈麦恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8511, '联盟需要轻皮！', '我们系列历代都是着名的剥皮匠，$c。这就是联盟要求我们为了安其拉之战而收集轻皮的原因。我在这里的工作是确保皮革经过正确的处理，准备投入使用。但是我们需要你的帮助。$B$B因为我不得不留在这里，所以我需要你去帮忙收集皮革，然后把它们交给我。你觉得怎么样，$g小伙子:小姑娘;，你会帮我吗？', '把10块轻皮交给丹莫罗飞机场的波尼·碎石。', '我敢说联盟一定会因为你这里的皮革感到很高兴，$C。我不会浪费任何一块皮革。谢谢你，记得在我清点好它们的时候回来找我，看看我是否需要更多的皮革。', '$C，我希望你带来了你所允诺的轻皮。', '', '去找丹莫罗的波尼·碎石。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8512, '联盟需要更多轻皮！', '很高兴再见到你，$n。看来我们需要更多的轻皮来制作各种物资。如果你可以再带给我10块轻皮的话，那就太完美了。', '把10块轻皮交给丹莫罗飞机场的波尼·碎石。', '谢谢你慷慨的捐献，$N。我会让相关人士知道你的名字，这样高权者就会知道你为战争做的努力。看来我们好像永远都需要更多的轻皮。快点回来找我。', '很高兴再见到你，$N。显然我们需要更多轻皮来制作各种战争要用的东西。如果你能再帮我带来10张轻皮就太完美了。', '', '去找丹莫罗的波尼·碎石。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8513, '联盟需要中皮！', '长官！我正在负责收集所有战争所需的中皮。如果你有足够的精力和资金来收集中皮的话，那么请把它们交给我。我们希望有更多像你这样的人来帮助我们。', '把10块中皮交给铁炉堡军事区的下士波特。', '哇!看来你是自愿来帮忙的。非常感谢你的捐献。我会把它们都装箱并点清。你真知道怎么讨人开心。', '是的$g先生:女士;，我记得你。你带来的是中皮吗?', '', '去找丹莫罗的列兵波特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8514, '联盟需要更多中皮！', '长官！现在我们已经收集了$2063w块中皮。我知道这个数字是很大的，但是如果你愿意的话，我希望你能继续帮助我来完成剩下的份额。', '把10块中皮交给丹莫罗飞机场的下士波特。', '天啊，你真的带了很多中皮来$g先生:女士;!我会将你的名字和功绩列在清单上。有你的帮忙我们很快就能将中皮收集好了!$B$B谢谢，$N!', '是的$g先生:女士;，看来当前我们已经收集了很多中皮。但我们需要更多的中皮。我可以向你保证这很好用;一块也不要浪费。我知道这个数量很庞大，但如果你愿意，我可以藉由你的帮忙让我的配额减少一点。', '', '去找丹莫罗的列兵波特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8515, '联盟需要厚皮！', '这一定会很有意思！$c，安其拉之战迫在眉睫，我正在负责收集厚皮。我们需要大量的储备，但是首先我们必须先从第一批开始。总之这就是你来这里的原因。$B$B那么，你是否可以帮我带来一些质量不错的厚皮呢？可以吗，可以吗？', '把10块厚皮交给铁炉堡军事区的玛塔·钢轴。', '喔，我就知道你可以做到，$C，我就知道!我会尽快把这些东西交到正确的人手里。现在，来看看这里。嗯，看来我们的货物进展的不错。你应该在我清点好之后再回来看我需不需要更多的重皮。因为如果我们需要的话，你就是我要找的助手!', '你包包里的东西是重皮吗，$C?是吗?我等不及你把它们交给我了!大家都会很满意我们的，你说是吗?', '', '去找铁炉堡军事区的玛尔塔·钢轴。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8516, '联盟需要更多厚皮！', '嗯，现在的数量还不够，$N。我们还没有达到我们的目标，也就是$2071w块厚皮。请尽一切所能来帮我们达到这个指标！所有的护甲和武器都需要用到它。另外蒸汽坦克和步枪瞄准镜也需要它们！工程护目镜也需要足够的厚皮，我打赌如果我们收集得足够多的话，那么我们可以用它们帮部落造些飞艇出来！$B$B你能带给我更多的厚皮吗？', '把10块厚皮交给丹莫罗飞机场的玛塔·钢轴。', '你又办到了!你能踏出这里收集所有的东西真是太神奇了，然后再把它们带回来交给我。我告诉你，如果他们知道你帮了多大的忙，你走到街上就一定会有人跟你要签名。$B$B再次谢谢你慷慨的捐献重皮，$N。', '没错，存货仍然不够。$N，我们仍未达到理想的目标。想想我们能用重皮做的所有东西!各种护甲和武器。蒸汽坦克的零件和步枪瞄准器!工程学护目镜，而且如果到最后我们还有剩下，可以把它们交给部落的齐柏林飞艇!$B$B你会为我带更多的重皮回来吗?', '', '去找铁炉堡军事区的玛尔塔·钢轴。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8517, '联盟需要亚麻绷带！', '安其拉的战争将会持续很长时间，并且会非常残酷。显然联盟寻求你们这些冒险者的帮助是很明智的选择，我们需要收集足够的资源来赢得这场战争。$B$B我在这里收集战争所需要的亚麻绷带，希望你可以帮助我们达成目标。现在一切物资都很紧缺，但是至少亚麻绷带还是比较容易制作的。你愿意帮助我们吗，$c？', '把20卷亚麻绷带交给铁炉堡军事区的哨兵塞尔瓦·银空。', '很多士兵都会因为你的捐献而受惠，$C。我会亲自确定联盟的人都知道你的努力。先让我储存好这些绷带并更新我的数量，然后你要再回来看看我是否还需要更多。$B$B愿艾露恩之光照耀着你，$r!', '你有我要的20个亚麻布绷带了吗，$C?', '', '去找丹莫罗的哨兵塞尔瓦·银空。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8518, '联盟需要更多亚麻绷带！', '我非常惊奇有那么多无私的人将私欲抛于一旁。$c，我还需要收集更多的亚麻绷带，直到完成我的指标。你是否可以再帮我收集一些亚麻绷带呢？', '把20卷亚麻绷带交给丹莫罗飞机场的哨兵塞尔瓦·银空。', '你会受到表扬，$N。当其它人会在我们的战争立足点上占经济的便宜来填满他们的荷包时，你却对联盟牺牲奉献，而且对整个艾泽拉斯而言你是第一个这么做的人。$B$B愿艾露恩的祝福永远跟随你!', '我对于你在私下还有如此无私的行为感到很惊讶。$C，在我的任务完成之前我仍需要一些亚麻布绷带。你能再次帮我收集那些绷带吗?', '', '去找丹莫罗的哨兵塞尔瓦·银空。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8520, '联盟需要丝质绷带！', '安其拉的战争阴云正笼罩着大地，我们需要尽力让我们的士兵做好准备。现在我正在做的就是这件事情：负责收集足够多的丝质绷带。$B$B你可以帮帮我吗，$c？', '把20卷丝质绷带交给铁炉堡军事区的女护士斯通菲尔德。', '$C，你成功了!多亏了你，我们又离收集丝质绷带的目标更近一步了。我先把那些绷带储存好再来和你谈谈。', '你好，$C，你拿到那20个丝质绷带了吗?', '', '去找丹莫罗的女护士斯通菲尔德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8521, '联盟需要更多丝质绷带！', '很高兴你能再次伸出援手，$c。看来我们已经收集了$2082w卷丝质绷带了，不过我们仍然需要更多。', '把20卷丝质绷带交给丹莫罗飞机场的女护士斯通菲尔德。', '你真是个无私的人。非常谢谢你对战争的贡献。只有像你这样的人才能让安其拉的成功和失败有所区别。我只希望这些东西已经足够。$B$B再次感谢，$N。', '你能再次提供我协助真是太好了，$C。看来我们已经收集了一堆丝质绷带，不过我们还需要更多。$N，你可以再想办法弄另一捆绷带拿来给我吗?联盟和我都会非常感激的。', '', '去找丹莫罗的女护士斯通菲尔德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8522, '联盟需要符文布绷带！', '关于战争的走向，你可以随意评说，$c，但是现在这场战争已经箭在弦上。看看你周围的朋友和家人，问问你自己，如果战争真的爆发，你会为此做些什么，你周围的人会一定会尽其所能地努力生存下来。$B$B现在，我在这里收集符文布绷带。你愿意捐赠一些吗？', '把20卷符文布绷带交给铁炉堡军事区的守护者莫沙·月影。', '你会因为这次任务的坚毅不拔受到表扬的，$C。我要把这些绷带收好，然后再和你谈谈有关收集更多符文布绷带的可能性。', '日子一天天过去，我们也继续向前走。$C，你有那些符文布绷带了吗?', '', '去找铁炉堡军事区的守护者莫沙·月影。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8523, '联盟需要更多符文布绷带！', '现在是我们再次讨论重要事宜的时候了，$c。我要对你上次的努力表示感谢；不是所有人都愿意如此无私而慷慨的。但是我们还有更多的工作需要完成。$B$B$N，你是否愿意收集更多的符文布绷带给我呢？', '把20卷符文布绷带交给丹莫罗飞机场的守护者莫沙·月影。', '这是我们一起走过的美好回忆，$N。你是个杰出的工作伙伴。我要再次感谢你的努力，联盟也很感激你。早点回来和我聊聊。', '又是讨论紧急事件的时候了，$C。我再次感谢你之前所作的努力;不是每个人都能如此无私奉献。但是我们仍然很多事要完成。$B$B$N，你可以再去收集符文布绷带并拿回来这里给我吗?', '', '去找铁炉堡军事区的守护者莫沙·月影。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8524, '联盟需要彩鳍鱼！', '你好，朋友！你不认为士兵也和别人一样需要吃饭吗？你当然会赞同这一点。我110%地同意你的看法！很高兴我们达成了一致。现在我要你做的就是去钓很多很多新鲜的彩鳍鱼，然后把它们烧好，带到我这里来。嗯，我仿佛已经可以尝到它们了……', '把20条彩鳍鱼交给丹莫罗飞机场的美食家斯里克。', '两条给联盟，一条给我，两条给联盟，一条给我。嘿，鱼贩，做的好。我可以预见你将要成为团体里真正的荣耀了。对我而言我们可能还需要那种鱼。你何不出去再弄些鱼回来呢。我已经听见我肚子咕噜噜叫了。', '我敢打赌你已经带回我们之前讨论的彩鳍鱼了，对吧?', '', '去找丹莫罗的美食家斯里克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8525, '联盟需要更多彩鳍鱼！', '什么！又是你？你还没尝够……你是来帮忙的？好吧，我不能说我在责怪你。你难道不喜欢这些食物的味道吗？<流口水>$B$B闲话说够了！快点去弄来更多的彩鳍鱼给我！', '把20条彩鳍鱼交给丹莫罗飞机场的美食家斯里克。', '我知道你把它放在你的包包里。你看起来就像是知道$g他:她;喜欢什么的样子。尤其是你喜欢讨好我和那些权势。而且你成功了，我保证。$B$B哈哈，好了，我先把这些鱼收好，然后你和我就能谈谈关于收集另外20条鱼的事了。', '什么!又是你?嗯，我是只猴子的舅舅…其实我是一个地精。正确的说是挑嘴的美食家!你又回来帮忙啦?嗯，我不能用责备你的口吻。但是你不喜欢那些食物的香味吗?<流口水>$B$B闲晃够了!去给我带回来更多的彩鳍鱼!', '', '去找丹莫罗的美食家斯里克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8526, '联盟需要烤迅猛龙肉！', '嘿，最近过得怎么样啊，$c？我看你好像有兴趣帮即将开始的安其拉战争收集食品物资。我爸爸觉得我来这里帮忙是一个学习的好方法。这可是个大错误，我根本不喜欢吃肉。$B$B不管怎么样，如果你愿意的话，请带给我大量的烤迅猛龙肉。显然这是所有士兵都想要的美食。', '把20块烤迅猛龙肉交给铁炉堡军事区的萨拉·塞维斯。', '天啊，真棒。谢谢你带给我这些烤肉，$C。我先把它们堆放在这。我相信会有人看好它的。我猜如果你有空的话会带更多肉给我吧?', '你拿到所有的烤迅猛龙肉了吗?', '', '去找丹莫罗的萨拉·塞维斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8528, '联盟需要斑点黄尾鱼！', '虽然看起来烧鱼算不上什么英雄事迹，但是绝对不要低估战前准备的价值，年轻的$c。士兵和其它人一样需要吃饭，我们在这里要准备的可是安其拉战争开始后所必需的东西。$B$B为此，我在这里收集斑点黄尾鱼，一种适合于存储并且可以用于多种菜肴的物资。另外它也没有其它咸水鱼的那种难闻的味道。你愿意帮助我吗？', '把20条斑点黄尾鱼交给铁炉堡军事区的女猎手蕾尔·急流。', '谢谢你的礼物，$C，还有你迅速的动作。我会让大家都知道你今天所做的事。先让我把这些鱼储存起来，然后如果你愿意，我们可以讨论第二次的渔获量。', '我有信心你很快就会带着我们讨论的斑点黄尾鱼回来。', '', '去找铁炉堡军事区的女猎手蕾尔·急流。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8529, '联盟需要更多斑点黄尾鱼！', '如果你还愿意帮忙的话，那么再去捉一些斑点黄尾鱼来，$N。我相信第一次的经验会让你这一次做起来更快更好的，正所谓一回生二回熟……你愿意去吗？', '把20条斑点黄尾鱼交给丹莫罗的女猎手蕾尔·急流。', '你真是联盟的一份子，$N。你的努力不会被忽略或不被赏识。也谢谢你把鱼都煮好。我会将它们存放好，然后更新我的存量。每个人都给我们这么多就能更接近目标。', '如果你愿意我想派你再去捕一批斑点黄尾鱼，$N。我想你有了第一次的经验，这次捕鱼一定会更快更容易。你愿意吗?', '', '去找铁炉堡军事区的女猎手蕾尔·急流。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8532, '部落需要铜锭！', '很高兴你来帮助我们。并不是所有人都能搞清楚我所需要的东西是什么，所以我要确保你不犯错误。我需要的是铜锭，不是铜矿石。我们没有时间自己进行熔炼，希望你可以帮助我们。你可以办到吧，$c？', '把20块铜锭交给奥格瑞玛精神谷的矿工克罗威尔。', '这些铜锭很好，谢谢你没有打亮它们。要将它们熔解做成战争要用的东西时，不需要把它们弄得那么漂亮。我会把它们堆放好，也会确定你的名字有被记下。如果你有兴趣帮我另外带20个的话再来和我谈谈。', '我希望你带来的是20个铜锭，$C。', '', '去找杜隆塔尔的矿工克罗威尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8533, '部落需要更多铜锭！', '那么快就回来了？你一定是个出色的矿工，$c。那么，你知道该怎么做了。我需要你去收集大量铜矿，熔炼成铜锭，然后把它们给我带来。我知道这对于你来说不是难事，但是你愿意做吗？', '把20块铜锭交给杜隆塔尔的矿工克罗威尔。', '你已向我证明了你自己，$C。我会让部落的人都知道你的名字。不过现在，我需要将这些铜锭弄上货板并清点。如果你还有意愿，我希望能藉助你的力量收集更多。', '这么快就回来了?你很快就会成为一个真正的矿工了$C。那么，你已经知道怎么钻孔了;我需要你出去帮我挖掘一堆铜矿，熔解它们做成铜锭再带回来给我。我知道你能办到，问题是，你愿意吗?', '', '去找杜隆塔尔的矿工克罗威尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8534, '灰烬公爵', '暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。$B$B根据可靠情报，那个被称作灰烬公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。', '设法召唤并击杀灰烬公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。', '你的努力获得很大的赞赏，$N。我要立刻显示这些侦察报告，去接你的下一个任务吧。', '你会在佐拉虫巢里找到塞纳里奥斥候艾泽奈尔。快，$N!时间就是金钱。', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8535, '深渊公爵', '暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。$B$B根据可靠情报，那个被称深渊公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。', '设法召唤并击杀深渊公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。', '做的好，$N。这是你的下一个任务。', '你的任务完成了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的鲍尔·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8536, '碎石公爵', '暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。$B$B根据可靠情报，那个被称作碎石公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。', '设法召唤并击杀碎石公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。', '做的好，$N。这是你的下一个任务。', '你的任务完成了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的鲍尔·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8537, '微风公爵', '暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。$B$B根据可靠情报，那个被称作微风公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。', '设法召唤并击杀微风公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。', '做的好，$N。这是你的下一个任务。', '你的任务完成了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的鲍尔·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8538, '圣殿骑士', '暮光之锤和深渊议会之间的联系看来比我们想象中的还要意义重大。$B$B根据可靠情报，那些被称作深渊圣殿骑士的元素领主们可能正在策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他们引诱出来，然后击杀他们。', '设法召唤并击杀四个深渊圣殿骑士，然后向塞纳里奥要塞的唤风者梅恩·长角复命。', '你为我们完成了一项伟大的任务，$N。你消除了对我们而言相当严重的威胁。在些表达我深深的谢意。', '你的任务完成了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的指挥官玛尔利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8539, '目标：佐拉雌蝎', '我们需要援军进攻佐拉虫巢。你的主要目标是那些佐拉雌蝎，当你的任务完成之后就去向指挥官玛尔利斯报告。', '击杀30只佐拉雌蝎，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 V才能完成这个任务。', '做的好，$N。你是个有价值的盟友。', '你有事要告诉我吗，$C?', '', '去希利苏斯找塞纳里奥要塞的指挥官玛尔利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8540, '卫兵的护甲片', '当前塞纳里奥要塞的骑兵团缺乏足够的毛皮护甲片，去收集大量护甲片，然后立即把它们交给塞纳里奥要塞的维斯·库鲁兹队长。', '把3双精制秘银战靴交给希利苏斯塞纳里奥要塞的维斯·库鲁兹。你还必须随身带着后勤任务简报 II才能完成这个任务。', '很好。我们正需要这些，$N。做的好。', '你有东西要给我吗?', '', '去希利苏斯找塞纳里奥要塞的维斯·库鲁兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8541, '卫兵的磨刀石', '塞纳里奥要塞的卫兵急需磨刀石。去收集足够的磨刀石，然后立即把它们交给塞纳里奥要塞的维斯·库鲁兹队长。', '把10块致密砂轮、10块坚固的砂轮和10块重砂轮交给希利苏斯塞纳里奥要塞的维斯·库鲁兹。你还必须随身带着后勤任务简报 III才能完成这个任务。', '很好。我们正需要这些，$N。做的好。', '你有东西要给我吗?', '', '去希利苏斯找塞纳里奥要塞的维斯·库鲁兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8542, '部落需要锡锭！', '你好，$r。我没有很多时间来向你进行解释。我们现在正在准备和安其拉开战，但是首先，酋长决定要我们进行一些工作，这些工作被称为“备战”。这意味我需要派你出去帮我收集锡锭，我想我需要的锡锭数量连我自己都数不过来。$B$B你还留在这里干什么？', '把20块锡锭交给奥格瑞玛精神谷的步兵玛乌格。', '嗯，我想这应该是正确的锡锭数字。别想蒙骗我，$C!清点数量让我感到头疼。现在去收集一样的数量来，但要快一点!', '为了你好，我希望你有那些锡锭，$C!', '', '去找奥格瑞玛精神谷的步兵玛乌格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8543, '部落需要更多锡锭！', '很好，我相信你已经开始严肃对待这场即将爆发的战争了。我急切地盼望冲上前线一展身手，这就是说，如果你不尽快把我要的东西拿来，那你就有大麻烦了。没准我会先拿你练练手。$B$B哈哈！也许不会，不然谁来给我收集锡锭呢？', '把20块锡锭交给杜隆塔尔的步兵玛乌格。', '(兽人语)你好，$N。你带来的锡锭让我和部落都感到荣耀。我会把它们堆放好并用它们制作东西。然后一切都准备好的时候我们就会上战场，教教渺小的联盟如何打仗。$B$B现在帮我带更多的锡锭回来!', '很好，我看的出你对这场战争很用心。我有点期盼战争可以赶快开始，我想你应该也是一样，$C。当战争开始时一定会是很光荣的。部落这在希利苏斯沙漠的尘土上奔驰着，手上拿着武器，冲锋陷阵在无数的虫群之中。总有一天将会取得极大的荣耀!$B$B哈!但是首先我们需要锡锭。真有趣，这样的小东西却可以带来巨大的不同，你说不是吗?', '', '去找奥格瑞玛精神谷的步兵玛乌格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8544, '征服者的肩铠', '据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！', '把其拉命令腕轮、2个夜晚塑像、5个岩石甲虫和5个陶土甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你需要的保护也能让我们的敌人尝到恐惧的滋味。', '你收集好我要的材料了吗?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8545, '部落需要秘银锭！', '$c，战争即将到来，我们所能做的就是准备作战。在这方面我们可以互相帮助。你看，他们派我来负责收集秘银锭，以供制作我们所需的东西。现在我需要更多秘银锭！$B$B那么，我希望你可以帮我去找来一些秘银矿石，然后熔化成锭。你可以做到这些吧？', '把20块秘银锭交给奥格瑞玛精神谷的军士长克拉恩。', '这对我们二个而言是个好的开始，$C。我又可以将这20个秘银锭放入库存清点数量了。我会记得把你的名字写在旁边，这点你可以放心。大家都会因为你的协助而感到高兴的。$B$B你要记得回来找我因为你应该知道我们还需要更多的秘银锭。', '如果能拥有所有安其拉之战需要的秘银锭就好了。这就是你回来的原因吗?你把我的秘银锭带来了?', '', '去杜隆塔尔找军士长克拉恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8546, '部落需要更多秘银锭！', '', '', '做的好，$N!另外20个秘银锭，让我们离目标又更近一步了，也让我们获得更多战场材料。我会提起你的名字让部落知道你正尽你的职责帮忙。如果你有其它的秘银锭，记得要拿来这里给我。', '太好了，很高兴你出现在这。你之前帮过我，现在我再次需要你的帮忙。我们仍然需要更多的秘银锭;需要制作很多护甲和武器还有其它东西来歼灭那些安其拉的虫子。$B$B所以如果你是个真正的朋友，你就会为我带回来更多的秘银锭。我会一直收下你的秘银锭直到达到我们的配额。你现在就可以给我一些吗?', '', '去杜隆塔尔找军士长克拉恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8547, '欢迎！', '欢迎来到魔兽世界！$B$B为了感谢您购买魔兽世界典藏版，请将这张礼券交给鹰翼广场的玛希尔拉·晨星。您将得到一份特别的礼物：陪伴您踏上冒险旅途的小宠物！$B$B再次感谢您的支持，请尽情享受魔兽世界的乐趣吧！', '将鹰翼广场礼品券交给鹰翼广场的玛希尔拉·晨星。', '您一定会成为一个真正的英雄，$N。欢迎您来到艾泽拉斯世界，请从我们为您精心准备的特殊礼品中挑选一件吧!', '您好!很高兴见到您!$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8548, '志愿兵的装备', '$N，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。$B$B希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。', '把5枚作战徽章、3枚后勤徽章和7枚战术徽章交给塞纳里奥要塞的瓦古斯。你必须在塞纳里奥议会中达到友善声望才能完成这个任务。', '做的好，$N。请接受这个代表塞纳里奥议会的象征。这是你应得的，朋友!', '你完成必要的任务了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的瓦古斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8549, '部落需要宁神花！', '据说每一代人都需要面对一次决定性的试炼。恐怕安其拉之战将是我们这一辈人所要经历的残酷考验。我们要做好准备，了解自己的实力究竟如何。$B$B我在这里志愿帮忙收集宁神花，我们会用它们制作战争所需的药水。我希望你来这里是为了帮助我们，如果是这样的话，那么我需要你帮我带回大量的这种草药。你会帮助我吗，$c？', '把20朵宁神花交给奥格瑞玛精神谷的草药学家波德·飞羽。', '我们的努力让我们离战争越来越近。谢谢你努力帮忙收集这些宁神花。我保证它们会有很好的用途，而且你的贡献会被大家所认同的，$N。如果你还有意愿的话，请带更多的花回来给我。在那之前，愿大地之母指引你。', '这么快就带着宁神花回来了吗，$C?', '', '去找奥格瑞玛精神谷的草药学家波德·飞羽。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8551, '船长的箱子', '我过去在一条专跑从这里到卡利姆多的棘齿城的航线上干过。我是个很优秀也很有名望的船长。$B$B直到……$B$B那些该死的海巨人毁了我的生活！他们打沉了我的船，杀光了我的水手，把我丢在一条救生艇上，让我漂回了藏宝海湾。还有，其中一个名叫高拉什的巨人还把我的箱子给偷走了，他说要拿这东西当鼻烟盒，简直是神经病！$B$B我听说有人看见高拉什最近在东边的海岸一带闲逛。找到他，把我的箱子给抢回来！快去，你会得到一位船长的敬意的。', '将斯莫特的箱子交给藏宝海湾的海克拜瑞·斯莫特。', '你找到它啦!啊，今天我太高兴啦!谢谢你，$N。得到这个箱子之后，我内心里的愤懑也就平息了。$B$B但我还是要复仇……', '你好啊，$N!你找到高拉什了吗?那箱子是我最喜欢的，里面有个小夹层，我最值钱的宝贝都藏在里面!', '', '去荆棘谷找藏宝海湾的海克拜瑞·斯莫特船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8552, '刺着字母的腰带', '这条精致的腰带的边上刺着两个字母“HS”。', '将刺着字母的腰带还给他的主人。', '你把我的束带找回来了?这么说……你一定已经把海巨人摩卡什干掉了!万岁!$B$B摩卡什正是那些把我的船搞沉、把我的船员们都杀光的三个海巨人之一。$B$B那已经是第三次了。$B$B你确实是一位优秀的$C，$N。', '你好。你有什么事吗?', '', '去荆棘谷找藏宝海湾刺着字母的腰带的主人。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8554, '挑战奈古拉什', '奈古拉什总是一副随时准备把一切都吞下去充饥的样子。$B$B那些巨人袭击我们的船的时候，奈古拉什直接冲向了我的厨房，不过他可不像其它巨人那样喜欢吃人。奈古拉什要的是酒……还有我秘制的烧烤秃鹰翅膀。嘿，这可都是我的拿手菜，我当年可是跑到荒芜之地才弄到这食谱的！$B$B如果你想把奈古拉什给引出来，只要用点酒再加上一碟烤翅就行啦。把这些东西放进我们当初丢在东南边海岸上的救生艇里，然后你就等着奈古拉什闻到食物的味儿乖乖上钩吧！', '将10块烧烤秃鹰翅膀和5瓶密林葡萄酒带到斯莫特船长的救生艇上去。$B$B然后杀死奈古拉什，将斯莫特的弯刀交给荆棘谷的斯莫特船长。', '你把我的弯剑从奈古拉什那儿抢回来啦!我简直不敢相信这是真的，$N!自从见到你之后，我似乎就时来运转了呀，没错，肯定是这样的!$B$B谢谢你!以后，要是我能再搞到一条新船的话，你要出海就尽管来找我，我让你随便坐，你永远都是我最欢迎的客人!', '把我的弯剑抢回来没有，$N?', '', '去荆棘谷找藏宝海湾的海克拜瑞·斯莫特船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8556, '坚定力量之戒', '据说其拉虫人的军官所佩戴的戒指可以给他们带来无穷的能量。那些戒指上镶嵌着腐化的宝石，也许我们可以用纯净的材料替换它们，以此来制作净化版本的戒指。$B$B那些装饰在其拉雕像上的宝石就非常合适，它们的质量非常好。$B$B把戒指和雕像交给我，我会为你制作一枚强大的戒指，$c。', '将1枚其拉将领戒指、2个柔光雕像、5个青铜甲虫和5个象牙甲虫交给唤风者耶萨德拉。', '我会帮你把戒指上的宝石换下来。你会发现效果会变的比较…协调。', '你帮我把戒指和材料带来了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8557, '坚定力量披风', '我很高兴听说你愿意帮助我们进攻安其拉，$N。我可以制作一件装备，让你在作战时获得一些保护，$c。$B$B我需要一件其拉斗篷，然后把它按照你的体型进行修改。我还需要其拉塑像和圣甲虫，这样我才能制作合适的扣子。$B$B我保证你一定不会失望的。', '将1件其拉军用披风、2个玛瑙雕像、5个银质甲虫和5个白骨甲虫交给凯伊·迅爪。你必须在塞纳里奥议会中达到崇敬声望才能完成这个任务。', '啊，太好了……这件披氅非常完美。$B$B拿着这个披氅，$N。愿它保护你对抗其拉虫人的邪恶魔法。', '你帮我带来了披风的材料吗，$N?', '', '去希利苏斯找塞纳里奥要塞的凯伊·迅爪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8558, '坚定力量之镰', '其拉虫人和他们的奴仆所使用的装备是由最珍稀宝贵的物品制作而成的，包括古代巨兽的骨头，大地最深处的宝石，以及最坚硬纯净的金属。$B$B这些其拉神器让我有一种冲动，想要用一些这样的材料来锻炼我的技艺。向塞纳里奥议会证明你的忠诚吧，$N，我会用最好的其拉虫人材料帮你制作一把强大的武器。', '将1件其拉尖刺刀柄、2个雪白雕像、5个水晶甲虫和5个岩石甲虫交给希利苏斯的守望者哈尔洛。你必须在塞纳里奥议会中达到崇拜声望才能完成这个任务。', '你做的很好，$C。真是把杰作之剑……它的平衡感非常完美。$B$B拿着你的武器，$N。带着无比的自信使用它并消灭我们的敌人吧!', '你把我要的材料带来了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的守望者哈尔洛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8559, '征服者的胫甲', '其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。', '把其拉命令腕轮、2个战争塑像、5个象牙甲虫和5个黄金甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。', '你把我要的东西都带来了吗，$N?', '', '去找安其拉的坎多斯特拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8560, '征服者的腿铠', '你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些规模生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。', '把奥罗的外皮、2个死亡塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。', '太好了…这块虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。', '你把我要的材料带来了吗，$N?', '', '去找安其拉的坎多斯特拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8561, '征服者的皇冠', '双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。', '把维克尼拉斯的头饰、2个太阳塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。', '你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。', '你有带我要的材料吗，$N?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8562, '征服者的胸甲', '最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！', '把上古之神的外鞘、2个战争塑像、5个银质甲虫和5个白骨甲虫交给安其拉的温瑟拉。你必须在诺兹多姆的子嗣中达到尊敬声望才能完成这个任务。', '我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个胸甲做为光荣的象征和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!', '在安其拉的住所里，可怕的克苏恩在睡眠中等待着。', '', '去找安其拉的温瑟拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8572, '精兵的装备', '$N，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。$B$B希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。', '把7枚作战徽章、4枚后勤徽章和4枚战术徽章交给塞纳里奥要塞的瓦古斯。你必须在塞纳里奥议会中达到友善声望才能完成这个任务。', '做的好，$N。请接受这个代表塞纳里奥议会的象征。这是你应得的，朋友!', '你完成必要的任务了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的瓦古斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8573, '勇士的装备', '$N，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。$B$B希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。', '把15枚作战徽章、20枚后勤徽章、20枚战术徽章和1枚塞纳留斯印记交给塞纳里奥要塞的瓦古斯。你必须在塞纳里奥议会中达到崇拜声望才能完成这个任务。', '做的好，$N。请接受这个代表塞纳里奥议会的象征。这是你应得的，朋友!', '你完成必要的任务了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的瓦古斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8574, '忠诚者的装备', '$N，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。$B$B希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。', '把15枚作战徽章、20枚后勤徽章、17枚战术徽章和1枚雷姆洛斯印记交给塞纳里奥要塞的瓦古斯。你必须在塞纳里奥议会中达到崇敬声望才能完成这个任务。', '做的好，$N。请接受这个代表塞纳里奥议会的象征。这是你应得的，朋友!', '你完成必要的任务了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的瓦古斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8575, '艾索雷葛斯的魔法账本', '<你无法理解这上面的字。你甚至不知道这些文字是什么语言！>', '把魔法账本交给塔纳利斯的纳瑞安。', '<纳里安积极地检视字母。>$B$B太特别了，$r!这是什么?我完全看不懂龙语。', '喔!魔法跳动的东西!是给我的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8578, '占卜眼镜？没问题！', '<你听到箱子里面传来一个声音。>$B$B你只需要他的占卜眼镜？很好！这不是问题……给我一分钟……嘿！该死……在哪里！$B$B好吧，我这里有一些坏消息，还有一些更坏的消息。坏消息是我把眼镜给弄丢了。更坏的消息是，我是上个星期在熔火之心里晃悠的时候把它给弄丢的。是的，熔火之心……我想这不是我能搞定的了！再见！', '找到纳瑞安的占卜眼镜。', '太好了!我把那只500磅的鸡和第二卷的＂龙语傻瓜教程″放在哪了???喔，这是给你的一点小意思!', '熔火之心啊?我希望我的护目镜还完好如初!', '', '去找塔纳利斯的纳瑞安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8580, '部落需要火焰花！', '嘿，$c。就是你！部落需要非常大量的火焰花来支持安其拉之战。也许他们会把火焰花用在一些爆炸物中，也许还会把它们交给联盟来作为蒸汽坦克的燃料？谁知道？但这不是关键！这不关比雷凯基的事情！$B$B比雷凯基只知道……只知道你会帮助他收集很多火焰花，对不对？', '把20份火焰花交给奥格瑞玛精神谷的蝙蝠骑士比雷凯基。', '$C!比雷凯基现在开心了。比雷凯基把所有的火焰花收进盒子里保持新鲜。比雷凯基还告诉首领你的行为，所以大家都会对$N感到很高兴。如果你还有拿到其它的火焰花，就快点去找比雷凯基。比雷凯基还需要更多的花。', '你不想让比雷凯基生气吧。要让比雷凯基高兴，你就得快速地带给他很多的火焰花。', '', '去找奥格瑞玛精神谷的蝙蝠骑士比雷凯基。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8582, '部落需要紫莲花！', '紫莲花是很多药水、药剂和精油的重要材料，它对于我们准备发动的安其拉之战很重要。我们正在为这场战争准备许多药剂，而且我还希望能发掘出更多紫莲花的用途。但前提是，我们需要大量的这种花朵。$B$B这就是你来这里的目的。去收集尽可能多的紫莲花。你还擅长别的什么事情吗？', '把20份紫莲花交给交给奥格瑞玛精神谷的药剂师耶泽尔。', '值得表扬的努力，$C。我会测试这些样本找出它们适合的用途并记下你的贡献。这些紫莲花在我使用之前要先好好储藏起来。至于你，如果你还有空的话我还需要更多的紫莲花。等一会儿再回来找我。', '你已经带着我要的紫莲花回来了吗，$C?你一定得尽快做好这件事，否则我这里要做的事全是空谈。', '', '去找奥格瑞玛精神谷的药剂师耶泽尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8583, '部落需要更多紫莲花！', '', '', '真是杰出又完美的表现，$N。你的努力会被表扬，你的名声也刚被传开。我会亲自监督不让这些紫莲花被浪费掉，而你的名字也将被提及。$B$B再次感谢你，如果你有更多紫莲花，不要犹豫，用最快的速度把它们拿来给我。', '事实上我们需要更多的紫莲花，$C。虽然我自己的研究尚未找出草药的新配方，但仍有已被试验和需要的试剂要使用。$B$B我需要你再去帮我收集至少20朵紫莲花样本。把它们交给我。', '', '去找奥格瑞玛精神谷的药剂师耶泽尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8585, '恐怖之岛！', '传说菲拉斯恐怖之岛的那群名叫奇美洛克的奇美拉族群是最鲜美多汁的食物！现在它们之中出现了一个首领，它的肉在经过巧妙的烹调之后可以变成一盘极品大餐！$B$B去恐怖之岛杀掉拉克麦拉，然后把它的肉带回来。这就可以满足那个侏儒了，而我则需要你带一些奇美洛克的腰肋肉给我。$B$B我会给你那500磅的肉鸡和一些别的什么东西作为交换。', '加基森的迪尔格·奎克里弗要你去菲拉斯的恐怖之岛击杀拉克麦拉，获得拉克麦拉的肉，并从岛上收集20份奇美洛克的腰肋肉。', '看看那些嫩腰肉!太棒了!$B$B关于那只鸡……嗯，让我看看。我需要几分钟策划食谱。', '嗯……奇美洛克……', '', '去找塔纳利斯的迪尔格·奎克里弗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8586, '迪尔格的超美味奇美拉肉片', '我的食谱完成了！我还需要一些火箭燃料和石中盐，只要把这些调料和你带给我的肉混合起来就可以了。$B$B如果你带来了我要的东西，纳瑞安想要的那只鸡就可以完成了。', '加基森的迪尔格·奎克里弗要你给他带去20份地精火箭燃油和20份石中盐。', '准备好了!我要呈现给你我最棒的创作:戴格的超美味奇美拉肉片!', '快一点，孩子。我们不想让肉坏掉。', '', '去找塔纳利斯的迪尔格·奎克里弗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8587, '向纳瑞安回复', '我是一个不会食言的地精，孩子。这是你要的500磅的小鸡。$B$B为什么那侏儒想要一只500磅的小鸡，那我就不知道了……$B$B<迪尔格喃喃自语着。>$B$B也许那家伙想要睡在里面……肮脏的侏儒……', '把500磅的小鸡交给塔纳利斯的纳瑞安。', '<纳里安将两只拳头伸进那只巨大的鸡里，整张脸塞在戴格美味的佳肴里。>$B$B嗯……这真是不可思议!我吃过最好吃的鸡!', '是什么味道这么香?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8588, '部落需要重皮！', '我们正在准备进行一场战争，所以我们最好首先把所有的物资准备妥当，你认为不该这样做吗，朋友？我们所需要的一类重要物资就是重皮。我们可以把它用在各个方面，强化护甲和制作防水布都用得到它。$B$B我们需要大量的重皮。这就是你的工作，$c。磨快你的剥皮刀，给我带回大量的重皮吧。做完这件事情，我们再继续谈谈。', '把10块重皮交给奥格瑞玛精神谷的剥皮师亚曼尼。', '喔，你真的有我要的重皮。你的刀真的很锐利，$C;这些真是好皮!现在既然我们已经有了该有的东西，我一定会将你对事业的贡献让大家都知道。如果你刚好又有更多的重皮，请带来这里给我。', '如果你只是要来这里碎碎念的话我可没有时间，$C。有太多堆重皮需要保存。等你至少有10张后再回来找我。', '', '去找奥格瑞玛的剥皮师亚曼尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8589, '部落需要更多重皮！', '', '', '谢谢你的重皮。每一点都让我们离目标更接近。我会好好保存并确定你的名字被写在清单上，这样首领们就会知道你的努力。$B$B再次谢谢你，$N，如果你又有更多的重皮，你知道在哪里可以找的到我。', '没错，$C，我还需要更多重皮。将军和军需官的需求似乎永无止尽。而这些跟飞艇管理员所要求的数量比起来更加微不足道!$B$B我需要收集双倍的配额量。$N，帮我带更多重皮来，越快越好!', '', '去找奥格瑞玛的剥皮师亚曼尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8590, '部落需要厚皮！', '我很高兴你决定和我谈谈这个，$c。部落方面已经着手为即将开始的安其拉之战做准备了，你我都要做好自己该做的事情。$B$B我被指派来收集大量的厚皮，我需要你帮忙去收集这些东西。这项工作是你的荣耀，也是表示你对部落的忠诚的好机会。你愿意帮忙吗？', '把10块厚皮交给奥格瑞玛精神谷的乌玛拉中士。', '做的好，$C。我相信这些厚皮会被拿来做齐柏林飞艇的增援和所有护甲及武器。谢谢你，部落也很感激你。如果你旅途中有更多的厚皮请回来找我。', '$C，你这么快就带着我们说的10张厚皮回来了吗?', '', '去找奥格瑞玛的乌玛拉中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8591, '部落需要更多厚皮！', '', '', '你办到了，$N，我就知道你可以。我再一次代表整个部落谢谢你。你的努力会被大家知道并获得诚挚的谢意。如果你找到更多厚皮愿意贡献，把它们带来这里给我吧。$B$B部落的荣耀!', '$C，你可以看见我仍需要收集更多厚皮。我再次要求你协助这个任务，并且保证，如果你完成任务我们会肯定你的努力。$B$B时间就是金钱!带着厚皮回来找我，我们就能完成准备去打仗!', '', '去找奥格瑞玛的乌玛拉中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8592, '神谕者的皇冠', '双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。', '把维克尼拉斯的头饰、2个先知塑像、5个银质甲虫和5个白骨甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。', '你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。', '你带回我要求的材料了吗，$N?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8593, '神谕者的长裤', '你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些规模生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。', '把巨型沙虫的皮、2个重生塑像、5个黄金甲虫和5个陶土甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。', '太好了……这块虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。', '你把我需要的材料带来了吗，$N?', '', '去找安其拉的坎多斯特拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8594, '神谕者的衬肩', '据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！', '把其拉命令腕轮、2个重生塑像、5个银质甲虫和5个象牙甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你需要的保护也能让我们的敌人尝到恐惧的滋味。', '你收集好我要的材料了吗?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8595, '凡人中的勇士', '', '', '你继续好好的效忠我们吧，$N。我们的协定依然存在。', '杀死其拉主使者对人类而言是个显着的成就，$N。无论如何，他们拥有强大的能量与数量。继续对抗他们以证明自己成为我们勇士的价值。', '', '去找坎多斯特拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8596, '神谕者的裹足', '其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。', '把其拉命令腕轮、2个死亡塑像、5个青铜甲虫和5个黄金甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。', '你把我要的东西都带来了吗，$N?', '', '去找安其拉的坎多斯特拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8598, '敲诈', '<便笺上用不同的字体拼凑出一段话。>$B$B我们已经拿到了你宝贵的书，侏儒。如果你想再见到它的话，那么你就必须按照我们说的来做。$B$B<以下是长达3页的具体指示说明。>$B$B把钱带来，只需你一个人来！', '把勒索信交给塔纳利斯的纳瑞安。', '<纳里安的脸愤怒而发红。>$B$B他们绑架我的……书，是吗?我会让他们知道玩弄超自然地精的下场!', '嘿，有什么事吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8599, '唱给纳瑞安的情歌', '并不是总是有人来拜访我。上一次有人来拜访，还是那次我把那个可爱的侏儒从坠毁的机器中救出来的时候。$B$B<米莉蒂丝若有所思。>$B$B你认识他吗？他叫纳瑞安……哦，如果有人可以替我给他传个话，那就太好了。我一定要告诉他我的感觉！我知道这就是爱！就是这样的！$B$B你可以帮我传话给纳瑞安吗？我永远都不会忘记你的！', '把米莉蒂丝的情书交给塔纳利斯的纳瑞安。', '什么!?$B$B<纳里安开始坐立不安。>$B$B嗯……你要我怎么做???她是一条鱼!我告诉你是一条鱼!而且我是个地精。我们是不可能在一起的。', '你身上都是鱼腥味!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8600, '部落需要硬甲皮！', '我发现你的刀子的手感比锋利的程度更重要。只要使用得当，最钝的刀子也可以切开东西。但是我们不会碰到这样的问题，因为我们把武器保养得都很好。$B$B好吧，不多说了。我现在有个任务给你，$c。为了部落，你现在要为安其拉之战做出你的贡献，我需要你帮忙收集大量的硬甲皮。你愿意吗？', '把10块硬甲皮交给奥格瑞玛精神谷的塞拉图斯。', '很好，这算是及格的工作了，虽然有些皮看起来切割的参差不齐。没关系，任务完成了，你获得了你的奖励。我会把你的名字写在皮革旁边;我肯定部落会很感谢你的努力。如果你又有了另一批硬甲皮，请尽快将它们带来给我。', '帮我切割10张硬甲皮不需要这么久的时间吧!你是不是应该磨锐你的剥皮小刀了呢?', '', '去找奥格瑞玛的塞拉图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8602, '风暴召唤者的肩甲', '据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！', '把其拉统御腕轮、2个生命塑像、5个黄金甲虫和5个水晶甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，人类。希望它们能给你需要的保护也能让我们的敌人尝到恐惧的滋味。', '你收集好我要的材料了吗?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8603, '神谕者的外套', '最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！', '把上古之神的外鞘、2个死亡塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的温瑟拉。你必须在诺兹多姆的子嗣中达到尊敬声望才能完成这个任务。', '我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个法衣做为光荣的象征和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!', '在安其拉的住所里，可怕的克苏恩在睡眠中等待着。', '', '去找安其拉的温瑟拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8604, '部落需要绒线绷带！', '你好，$c。为了准备安其拉之战，我在这里帮助部落协调收集绒线绷带。在战场上，士兵们不能指望总有医师跟着他们，所以我们要为他们准备急救包。$B$B如果你有时间的话，我需要很多绒线绷带，请把绷带交给我，我会奖励你的。', '把20卷绒线绷带交给奥格瑞玛精神谷的医师朗兰纳。', '谢谢你，$C，部落也很感激你。如果你有更多的绒线绷带，又希望对战事做更多贡献的话，请带到这边给我。在那之前，愿你的祖先守护着你!', '啊，$C，你这么快就带着绒线绷带回来了吗?', '', '去找奥格瑞玛的医师朗兰纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8607, '部落需要魔纹布绷带！', '我相信你来找我是想要帮助我收集东西？很好！不管怎么样，我接受所有的帮助，并且我需要你帮忙去收集厚魔纹绷带。最好是新做的，但不是必须。把它们交给我，$c，我会给你适当的奖励的。', '把20卷魔纹绷带交给奥格瑞玛精神谷的卡隆。', '很惊讶，但是差强人意。或许我低估了你的“…能力”…$C。或许吧。你完成了一个非常简单的任务，因此你会获得不成比例的奖励。但是不要让它影响到你。如果你真的想证明自己就再去帮我带回另一堆魔纹布绷带吧。', '不许失败让我颜面扫地，$C!尽快带着我们讨论的魔纹布绷带回到这里。', '', '去找奥格瑞玛的卡隆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8609, '部落需要符文布绷带！', '毫无疑问，部落和联盟在准备安其拉之战的过程中会发生摩擦。奇怪的是，这场战争居然不是在部落和联盟之间进行的，双方的敌人都是异种虫类和控制这些虫子的幕后黑手。部落和联盟都在积极收集资源来发动这场战争。$B$B我负责收集符文布绷带，但是如果我得不到帮助的话就不会成功。你能帮助我吗，$c？', '把20卷符文布绷带交给奥格瑞玛精神谷的尼根·陶蹄。', '你对部落而言是个荣耀，$C。谢谢你的努力;我们很感谢!我要把这些新鲜的绷带打包好并算算我们离目标还差多少。如果你愿意，可以帮我收集更多符文布绷带再回来这里。', '战争很快就来了，$C。你取得了我们之前说的符文布绷带吗?', '', '去找奥格瑞玛的尼根·陶蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8611, '部落需要瘦狼排！', '我站在这里可不是为了把自己皮肤晒成健康色的，$c。我们必须为战争做好准备。如果我们想要把那些安其拉的虫子都碾碎的话，那么我们现在就得好好准备一下了，这当然包括食物的储备工作！$B$B我们需要收集足够的狼肉来为战争做好准备。我要待在这里进行整理工作，所以我要委托你去杀几条狼，然后把它们的肉烧成瘦狼排给我。你知道该怎么做了吗？', '把20块瘦狼排交给奥格瑞玛精神谷的血卫士拉尔塔。', '嗯，这堆肉看起来很好。我会用盐腌制它们并打包好，希望能一直保持新鲜到要吃的时候。$B$B谢谢你将它们带来给我;我会确认你的烹饪工作被记录下来。你还能再带给我另一批吗?', '这么快就带着瘦狼排回来了吗，$C?我不在乎它们烤太熟或沾了塔塔酱，只要它们是美味的就快点带来给我!', '', '去找杜隆塔尔的血卫士拉尔塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8613, '部落需要斑点黄尾鱼！', '真是钓鱼的好天气，你不这么认为吗，$g小伙子:姑娘;？这天气真好，我正好需要很多的鱼。部落让我负责收集大量的斑点黄尾鱼。这是为了即将开始的安其拉之战做准备。我告诉他们我会尽力而为的，所以我现在需要一些帮助。你可以帮帮我吗，$c？', '把20条斑点黄尾鱼交给奥格瑞玛精神谷的渔夫林度。', '喔耶，这真是好东西。我会把它们收好，不会浪费。谢谢你帮我们这样的忙。我想你是个一流的渔夫$g先生:小姐;能钓到这些斑点黄尾鱼。如果你刚好钓到并煮好更多鱼，拿到这里给我;我要让大家都知道你的表现!', '这么快就带着斑点黄尾鱼回来了吗，$C?你有把它们煮好吧?我们可不想在炎热的沙漠艳阳下给士兵们生鱼吃。', '', '去杜隆塔尔找奥格瑞玛的渔夫林度。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8615, '部落需要烤鲑鱼！', '安其拉之战的准备工作是一项浩大的工程，$c。所有的物资都将在这里进行收集，无论是铸造武器所需的金属，还是士兵日常生活所需的食物都非常重要。比如说，如果你几天没有吃东西，那么你一定没有力气挥舞战斧。$B$B因此我们需要收集尽可能多的食物。我在这里负责收集烤鲑鱼，它的口味和营养都非常适合我们的士兵。你能帮帮我吗，$c？', '把20份烤鲑鱼交给奥格瑞玛精神谷的图拉·利爪。', '谢谢你为战事提供帮忙，$C。很多人都会忽略我们的需要，选择赚取利润。但是他们无法获得部落的感谢，无法像你现在所做的一样。他们的心不是丰盈的，不像你现在的心一样，因为无私的奉献充满骄傲。$B$B我再一次的感谢你。如果你能在我们的准备完成前再次帮助我们，我会在这里等你。', '你带着烤鲑鱼回来了吗，$C?记住，一定要煮熟的;我们不能用生的鱼。', '', '去找杜隆塔尔的图拉·利爪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8620, '唯一的方案', '我就知道，我最大的敌人，维维尔博士又开始玩他那老一套了！现在，由于你在冬泉谷的失败，维维尔把我的书给毁掉了！你现在还怎么拯救世界，大英雄？$B$B我收集到的仅存的《龙语傻瓜教程：第二卷》被撕成8份，散落在世界各地！如果你可以收集到这些遗失的章节，那么就用这个魔法书封面把它们合在一起，然后给我带回来。', '把8章《龙语傻瓜教程》的章节用魔法书封面合起来，然后把完整的《龙语傻瓜教程：第二卷》交给塔纳利斯的纳瑞安。', '太棒了!真不敢相信你真的突破了那个难题!你是机器吗?换作是我，我可能会让整个世界爆炸。$B$B告诉你，$g先生:女士; 。英勇的行为一定会得到奖励的。', '我和你一样把裤子穿上 - 一次穿一条腿进去。只不过等你穿好了，我已经在制作奥金浮标了。奥金浮标啊，宝贝!', '', '去找塔纳利斯的纳瑞安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8625, '神秘肩垫', '据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！', '把其拉命令腕轮、2个死亡塑像、5个岩石甲虫和5个青铜甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你适时的保护也能让我们的敌人尝到恐惧的滋味。', '你收集好我要的材料了吗?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8626, '攻击者的足甲', '其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。', '把其拉命令腕轮、2个生命塑像、5个岩石甲虫和5个白骨甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。', '你拿到我所需要的东西了吗，$N?', '', '去找安其拉的坎多斯特拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8627, '复仇者的胸甲', '最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！', '把上古之神的外鞘、2个先知塑像、5个银质甲虫和5个白骨甲虫交给安其拉的温瑟拉。', '我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个胸部铠甲做为光荣的象征和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!', '在安其拉的住所里，可怕的克苏恩在睡眠中等待着。', '', '去找安其拉的温瑟拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8628, '复仇者的王冠', '双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。', '把维克洛尔的王冠、2个重生塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。', '你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。', '你把我所要求的材料都带回来了吗， $N?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8629, '复仇者的护腿', '你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些规模生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。', '把巨型沙虫的皮、2个征战塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。', '太好了……虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。', '你把我需要的材料带来了吗，$N?', '', '去找安其拉的坎多斯特拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8630, '复仇者的护肩', '据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！', '把其拉统御腕轮、2个生命塑像、5个水晶甲虫和5个黄金甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你适时的保护也能让我们的敌人尝到恐惧的滋味。', '你收集好我要的材料了吗?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8632, '神秘头饰', '双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。', '把维克尼拉斯的头饰、2个夜晚塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。', '你成功了!双子帝王的耳语停止了。$B$\r\nB收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。', '你把我所要求的材料都带回来了吗， $N?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8633, '神秘长袍', '最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！', '把上古之神的外鞘、2个太阳塑像、5个黄金甲虫和5个陶土甲虫交给安其拉的温瑟拉。你必须在诺兹多姆的子嗣中达到尊敬声望才能完成这个任务。', '我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个长袍做为光荣的象征和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!', '在安其拉的住所里，可怕的克苏恩在睡眠中等待着。', '', '去找安其拉的温瑟拉。', '', '', '', '');
