INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8641, '死亡执行者的护肩', '据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！', '把其拉命令腕轮、2个太阳塑像、5个银质甲虫和5个陶土甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你适时的保护也能让我们的敌人尝到恐惧的滋味。', '你收集好我要的材料了吗?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8655, '复仇者的胫甲', '其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。', '把其拉统御腕轮、2个先知塑像、5个青铜甲虫和5个陶土甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。', '你拿到我所需要的东西了吗，$N?', '', '去找安其拉的坎多斯特拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8656, '攻击者的护甲', '最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！', '把上古之神的外鞘、2个生命塑像、5个黄金甲虫和5个陶土甲虫交给安其拉的温瑟拉。', '我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个胸部铠甲做为光荣的象征和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!', '在安其拉的住所里，可怕的克苏恩在睡眠中等待着。', '', '去找安其拉的温瑟拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8657, '攻击者的王冠', '双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。', '把维克尼拉斯的头饰、2个征战塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。', '你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。', '你把我所要求的材料都带回来了吗， $N?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8659, '攻击者的护肩', '据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！', '把其拉命令腕轮、2个战争塑像、5个水晶甲虫和5个象牙甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你适时的保护也能让我们的敌人尝到恐惧的滋味。', '你收集好我要的材料了吗?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8660, '厄运召唤者的裹足', '其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。', '把其拉统御腕轮、2个夜晚塑像、5个陶土甲虫和5个象牙甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。', '你拿到我要的物品了吗，$N?', '', '去找安其拉的坎多斯特拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8662, '厄运召唤者的头饰', '双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。', '把维克尼拉斯的头饰、2个死亡塑像、5个银质甲虫和5个白骨甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。', '你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧……这会让他们想起死去的领导者还有杀死他们的人类。', '你有带我要的材料吗，$N?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8663, '厄运召唤者的长裤', '你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些规模生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。', '把巨型沙虫的皮、2个重生塑像、5个黄金甲虫和5个陶土甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。', '嗯……这条虫子的皮可以制成非常好的保护层。和安其拉的其它材料配合起来，我们就可以制作一件完美的护甲。希望它可以帮助你对抗那些潜伏在神殿中的恐怖力量!', '你把我要的材料带来了吗，$N?', '', '去找安其拉的坎多斯特拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8664, '厄运召唤者的衬肩', '据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！', '把其拉统御腕轮、2个先知塑像、5个青铜甲虫和5个白骨甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，人类。希望它们能给你需要的保护也能让我们的敌人尝到恐惧的滋味。', '你收集好我要的材料了吗?', '', '去找安其拉的安多葛斯。', '', '', '', '');
