INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8669, '起源护肩', '据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！', '把其拉统御腕轮、2个征战塑像、5个黄金甲虫和5个白骨甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能保护你，让我们的敌人笼罩在它们所带来的恐惧中。', '你收集好我要的材料了吗?', '', '去找安其拉的安多葛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8687, '目标：佐拉坑道蝎', '我们需要援军进攻佐拉虫巢。你的主要目标是那些佐拉坑道蝎，当你的任务完成之后就去向指挥官玛尔利斯报告。', '击杀30只佐拉坑道蝎，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 VII才能完成这个任务。', '做的好，$N。少了他们的坑道蝎，异种蝎就很难修补他们虫巢结构所受的伤害。我猜你想要一个新任务。', '你有事要告诉我吗，$C?', '', '去希利苏斯找塞纳里奥要塞的指挥官玛尔利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8689, '无尽智慧披风', '我很高兴听说你愿意帮助我们进攻安其拉，$N。我可以制作一件装备，让你在作战时获得一些保护，$c。$B$B我需要一件其拉斗篷，然后把它按照你的体型进行修改。我还需要其拉塑像和圣甲虫，这样我才能制作合适的扣子。$B$B我保证你一定不会失望的。', '将1件其拉军用披风、2个翠玉雕像、5个黄金甲虫和5个陶土甲虫交给凯伊·迅爪。你必须在塞纳里奥议会中达到崇敬声望才能完成这个任务。', '啊，太好了……这件披氅非常完美。$B$B拿着这个披氅，$N。愿它保护你对抗其拉虫人的邪恶魔法。', '你帮我带来了披风的材料吗，$N?', '', '去希利苏斯找塞纳里奥要塞的凯伊·迅爪。', '', '', '', '');
