INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8697, '无尽智慧之戒', '据说其拉虫人的军官所佩戴的戒指可以给他们带来无穷的能量。那些戒指上镶嵌着腐化的宝石，也许我们可以用纯净的材料替换它们，以此来制作净化版本的戒指。$B$B那些装饰在其拉雕像上的宝石就非常合适，它们的质量非常好。$B$B把戒指和雕像交给我，我会为你制作一枚强大的戒指，$c。', '将1枚其拉典礼戒指、2个黑曜石雕像、5个银质甲虫和5个白骨甲虫交给唤风者耶萨德拉。你必须在塞纳里奥议会中达到尊敬声望才能完成这个任务。', '我会帮你把戒指上的宝石换下来。你会发现效果会变的比较……协调。', '你帮我把戒指和材料带来了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8698, '聚集风暴之戒', '据说其拉虫人的军官所佩戴的戒指可以给他们带来无穷的能量。那些戒指上镶嵌着腐化的宝石，也许我们可以用纯净的材料替换它们，以此来制作净化版本的戒指。$B$B那些装饰在其拉雕像上的宝石就非常合适，它们的质量非常好。$B$B把戒指和雕像交给我，我会为你制作一枚强大的戒指，$c。', '将1枚其拉将领戒指、2个朱红雕像、5个银质甲虫和5个白骨甲虫交给唤风者耶萨德拉。', '我会帮你把戒指上的宝石换下来。你会发现效果会变的比较……协调。', '你帮我把戒指和材料带来了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
