INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8703, '永恒公正之戒', '据说其拉虫人的军官所佩戴的戒指可以给他们带来无穷的能量。那些戒指上镶嵌着腐化的宝石，也许我们可以用纯净的材料替换它们，以此来制作净化版本的戒指。$B$B那些装饰在其拉雕像上的宝石就非常合适，它们的质量非常好。$B$B把戒指和雕像交给我，我会为你制作一枚强大的戒指，$c。', '将1枚其拉将领戒指、2个朱红雕像、5个银质甲虫和5个白骨甲虫交给唤风者耶萨德拉。你必须在塞纳里奥议会中达到尊敬声望才能完成这个任务。', '我会帮你把戒指上的宝石换下来。你会发现效果会变的比较……协调。', '你帮我把戒指和材料带来了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8704, '隐秘通途之戒', '据说其拉虫人的军官所佩戴的戒指可以给他们带来无穷的能量。那些戒指上镶嵌着腐化的宝石，也许我们可以用纯净的材料替换它们，以此来制作净化版本的戒指。$B$B那些装饰在其拉雕像上的宝石就非常合适，它们的质量非常好。$B$B把戒指和雕像交给我，我会为你制作一枚强大的戒指，$c。', '将1枚其拉典礼戒指、2个琥珀雕像、5个黄金甲虫和5个陶土甲虫交给唤风者耶萨德拉。你必须在塞纳里奥议会中达到尊敬声望才能完成这个任务。', '我会帮你把戒指上的宝石换下来。你会发现效果会变的比较……协调。', '你帮我把戒指和材料带来了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8705, '无尽智慧之锤', '其拉虫人和他们的奴仆所使用的装备是由最珍稀宝贵的物品制作而成的，包括古代巨兽的骨头，大地最深处的宝石，以及最坚硬纯净的金属。$B$B这些其拉神器让我有一种冲动，想要用一些这样的材料来锻炼我的技艺。向塞纳里奥议会证明你的忠诚吧，$N，我会用最好的其拉虫人材料帮你制作一把强大的武器。', '将1件其拉装饰刀柄、2个柔光雕像、5个青铜甲虫和5个象牙甲虫交给希利苏斯的守望者哈尔洛。你必须在塞纳里奥议会中达到崇拜声望才能完成这个任务。', '你做的很好，$C。这是把杰作之剑……它的平衡非常完美。$B$B拿着你的武器，$N。带着无比的自信使用它并消灭我们的敌人吧!', '你带了我要的材料来吗，$N?', '', '去希利苏斯找塞纳里奥要塞的守望者哈尔洛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8706, '聚集风暴之锤', '其拉虫人和他们的奴仆所使用的装备是由最珍稀宝贵的物品制作而成的，包括古代巨兽的骨头，大地最深处的宝石，以及最坚硬纯净的金属。$B$B这些其拉神器让我有一种冲动，想要用一些这样的材料来锻炼我的技艺。向塞纳里奥议会证明你的忠诚吧，$N，我会用最好的其拉虫人材料帮你制作一把强大的武器。', '将1件其拉尖刺刀柄、2个琥珀雕像、5个象牙甲虫和5个青铜甲虫交给希利苏斯的守望者哈尔洛。你必须在塞纳里奥议会中达到崇拜声望才能完成这个任务。', '你做的很好，$C。这是把杰作之剑……它的平衡非常完美。$B$B拿着你的武器，$N。带着无比的自信使用它并消灭我们的敌人吧!', '你带了我要的材料来吗，$N?', '', '去希利苏斯找塞纳里奥要塞的守望者哈尔洛。', '', '', '', '');
