INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8712, '隐秘通途之镰', '其拉虫人和他们的奴仆所使用的装备是由最珍稀宝贵的物品制作而成的，包括古代巨兽的骨头，大地最深处的宝石，以及最坚硬纯净的金属。$B$B这些其拉神器让我有一种冲动，想要用一些这样的材料来锻炼我的技艺。向塞纳里奥议会证明你的忠诚吧，$N，我会用最好的其拉虫人材料帮你制作一把强大的武器。', '将1件其拉尖刺刀柄、2个碧蓝雕像、5个银质甲虫和5个白骨甲虫交给希利苏斯的守望者哈尔洛。你必须在塞纳里奥议会中达到崇拜声望才能完成这个任务。', '你做的很好，$C。这是把杰作之剑……它的平衡非常完美。$B$B拿着你的武器，$N。带着无比的自信使用它并消灭我们的敌人吧!', '你带了我要的材料来吗，$N?', '', '去希利苏斯找塞纳里奥要塞的守望者哈尔洛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8728, '好消息和坏消息', '好吧，这比预期的时间稍微长了一些。现在让我看看账本上都写了些什么。$B$B<纳瑞安默默地读着账本，有的时候还喃喃自语。>$B$B好消息是，我可以99%地肯定，我能为你制作一个奥金鱼漂。当然，还有一个坏消息。$B$B坏消息就是，我需要大量的奥金，源质矿石，还有一些珍贵的宝石。$B$B把它们带来，然后我就可以开工了。', '塔纳利斯的纳瑞安要你给他带去20块奥金锭、10块源质矿石、10颗艾泽拉斯钻石，以及10颗蓝宝石。', '就这么说定了。我当然希望你知道自己在做什么，$N。要钓如此大量的鱼是件很麻烦的事。', '奥金浮标不会自己制造，$N。还有，你不要指望可以在我这里赊账。', '', '去找塔纳利斯的纳瑞安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8729, '耐普图洛斯的愤怒', '我和你说说过坏消息了吗？它的名字叫巨齿鲨，身长100尺，死亡和毁灭的化身。我想我忘记和你说这个了。$B$B根据我的超级精神共振同频分析器提供的信息，你可以在艾萨拉的海岸找到最合适使用这个鱼漂的地方，就在风暴海湾。$B$B你要寻找一个大漩涡，它附近应该都是沉船。$B$B另外，我希望你带上你的朋友，很多朋友。$B$B如果你成功的话，就把节杖碎片交给阿纳克洛斯吧。', '在艾萨拉风暴海湾一带的湍急的漩涡处使用奥金鱼漂。', '干得好，$N。我将马上重新制作流沙权杖。', '时间在不断流逝，勇士。', '', '去塔纳利斯找时光之穴的阿纳克洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8730, '奈法里奥斯的腐蚀', '勇士，是你吗？我受命保管这个碎片已经一千年了，在我最黑暗的时候，应该有人站出来替我把它拿回来……但是一切都是任重道远的。$B$B<瓦拉斯塔兹轻轻地咳嗽着。>$B$B耐……耐法里奥斯现在掌握着节杖碎片。$B$B时间是最关键的。耐法里奥斯将要摧毁这个节杖。你必须赶快！', '干掉奈法利安并拿到红色节杖碎片。把红色节杖碎片带给塔纳利斯时光之穴门口的阿纳克洛斯。你必须在5小时之内完成这个任务。', '瓦拉斯塔兹的灵魂终于平静了，勇士。所有的守护巨龙都在关注着你的进展。他们知道你的身边有强大的盟友。$B$B我奉命送给你一些东西，希望它可以在这场战斗中帮助你。好好使用它……', '又有一位英雄因为挑战死亡之翼的子嗣而阵亡了。我们将因这样的损失而被永远诅咒……', '', '去塔纳利斯找时光之穴的阿纳克洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8731, '战地任务', '你好，$N。在我为你布置更重要的任务之前，你需要首先完成一些常规的战地任务。$B$B你可以在佐拉虫穴外找到克鲁格·碎颅的部队。$B$B向他报到，然后拿着你完成任务的证明文件回到我这里来。那时我将会给你下达进一步的指令。$B$B哦，别忘了离铁炉堡军团远一些。由于联盟和部落的志愿兵之间摩擦不断，我们被迫把他们分开来。', '向雷戈虫巢外的奥格瑞玛军团报到，从克鲁格·碎颅那里拿到签过字的战地任务文件，把它交给希利苏斯塞纳里奥要塞的唤风者卡尔东。$B$B注意：给奥格瑞玛军团的士兵治疗或者施放增益法术会打开你的PvP标志。', '看的出来克鲁格不常使用文书工作。他用异种的鲜血签署这份文件!$B$B很好，$N。我安排了一连串适合$C技能的任务给你。$B$B有你和像你一样的人继续努力，我们的敌人很快就会被击垮!', '你已完成你的战地任务了吗，$N?你可以在雷戈虫巢外面找到劈颅队长。', '', '去希利苏斯找塞纳里奥要塞的唤风者卡尔东。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8732, '战地任务文件', '', '', '啊，我想刚才经历了那场小遭遇战也可以被称为完成了一项“战地任务”吧。把这些带回塞纳里奥城堡去，我相信他们一定会有重要任务给你的。$B$B快出发!', '我会拿到那些你想要的已签字文件，$G小伙子:小姑娘;?', '', '去找希利苏斯塞纳里奥议会的唤风者梅恩·长角', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8735, '腐蚀梦魇', '你必须到艾泽拉斯世界的四个翡翠梦境入口去。在每个入口处，你都可以收集到腐蚀梦魇的碎片。住在这些地区的龙类生物身上会携带着这样的碎片。当你收集到全部四块碎片后就回到我这里来。', '到艾泽拉斯世界的四个翡翠梦境入口去，分别收集该处的腐蚀梦魇的碎片。当你任务完成之后，就回到月光林地的守护者雷姆洛斯那里。', '你准备好了吗?我们即将乞求庇护的世界准备好了吗?我不知道…我对玛法里奥有一定的职责，职责与荣耀…', '<雷姆洛斯陷入沉思。>', '', '去月光林地找雷姆洛斯神殿的守护者雷姆洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8737, '灰烬公爵', '暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。$B$B根据可靠情报，那个被称作灰烬公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。', '设法召唤并击杀灰烬公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。', '干得好，$N。这里是你的下一个任务。', '你的任务完成了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的鲍尔·蛮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8738, '雷戈虫巢侦查报告', '我们派出了最好的斥候深入异种虫类的巢穴收集情报。兰迪奥这几天来一直在监视佐拉虫巢，去找到他，拿回他的书面报告。我们需要这些情报来制定战术，要尽快，$n。', '在雷戈虫巢内找到塞纳里奥斥候兰迪奥，然后把雷戈虫巢侦查报告交给塞纳里奥要塞的唤风者梅恩·长角。你还必须随身带着战术任务简报 VII才能完成这个任务。', '你的努力获得很大的赞赏，$N。我要立刻显示这些侦察报告，去接你的下一个任务吧。', '到雷戈虫巢去找斥候兰迪奥，快一点，$N!时间紧迫!', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8739, '灰烬公爵', '暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。$B$B根据可靠情报，那个被称作灰烬公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。', '设法召唤并击杀灰烬公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。', '你的努力获得很大的赞赏，$N。我要立刻显示这些侦察报告，去接你的下一个任务吧。', '到亚什虫巢去找到斥候佳莉亚，快一点，$N!时间紧迫!', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8740, '暮光掠夺者', '许多幕光之锤的骑兵教徒经常在我们塞纳里奥要塞守卫范围之外的区域游荡，并伺机袭击我们巡逻和商旅小队。$B$B找到并击败暮光掠夺者和他们的领袖，一个叫做莫娜的恐怖战士。当任务完成之后向唤风者梅恩·长角报告。', '干掉暮光掠夺者莫娜和2个暮光掠夺者。任务完成之后向唤风者梅恩·长角报告。你还必须随身携带战术任务简报 IX以完成这个任务。', '做的好，$N。暮光掠夺者曾经让我们的巡逻队吃尽了苦头，造成伤亡无数。这是你的下一个任务。', '你的任务完成了吗，$N?', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8743, '敲响甲虫之锣！', '', '', '在甲虫之锣的下方悬挂着一颗特别的水晶，也许是龙类所留下的?', '甲虫之锣嗡嗡作响，给你一种不安的感觉。坚强起来，$N。一旦甲虫之锣被敲响，安其拉的大门就将被打开。$B$B从这扇大门之后涌出来的将会是混乱和毁灭。保护你的人民!', '', '去找希利苏斯的甲虫之锣。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8746, '驯鹿梅森', '出大事啦！驯鹿梅森被绑架了！$B$B冬天爷爷有八头驯鹿，梅森是其中的一头，也是烟林牧场的财产。我们收到了宣称对此次绑架事件负责的组织寄来的勒索信，而且不是一封，是两封！两封，你明白吗？节日即将来临，我们早已经穷得叮当响啦！帮帮忙吧，帮我们找到梅森，把它救回来！$B$B你可以看看这些勒索信里面有什么线索，找到梅森之后，把驯鹿之尘洒在它身上，这样就可以让它摆脱一切束缚！$B$B事不宜迟！', '找到驯鹿梅森。在你手头上的便笺中查找有关梅森下落的线索。$B$B当你找到它之后，往它身上洒一些驯鹿之尘，这样就可以让它摆脱任何束缚。$B$B解救梅森之后，把驯鹿之尘还给奥格瑞玛的凯玛德·考伯宾奇。', '你办到了!万岁!$B$B梅特森已经飞回去冬天爷爷的兽栏里了－－是的，梅特森是会飞的－－就在不久之前!这个尘土有点像是个符咒;我知道它可以的。你拯救了冬幕节还有熏木牧场免于疾病的侵袭。谢谢你，$N。$B$B听着……因为你对这里的贡献，我希望你可以拿着这个。这是一个非常特别的东西;如果你有坐骑的话，我想你可以好好的试试它。冬幕节快乐!', '$N!你找到它了吗?我给你的背袋中的纸条，有给你足够的讯息来确定梅特森的位置吗?我简直不敢去想那些恶棍会对梅特森做些什么……但我们绝对不会对这样的绑架勒索行为妥协!', '', '去找奥格瑞玛的凯玛德·考伯宾奇。', '拯救驯鹿梅森', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8747, '保护者之路', '', '', '相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献已被记录下来。$B$B防卫者的徽记之戒将会在你对抗邪恶力量时提供更多的保护。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。', '相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献已被记录下来。$B$B防卫者的徽记之戒将会在你对抗邪恶力量时提供更多的保护。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8748, '保护者之路', '', '', '相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献已被记录下来。$B$B防卫者的徽记之戒将会在你对抗邪恶力量时提供更多的保护。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。', '你一直保护卡利姆多生灵的行为已经被我们认可。把徽记之戒拿来，让我增强它的能量。', '', '去找塔纳利斯的阿纳克洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8749, '保护者之路', '', '', '相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献已被记录下来。$B$B防卫者的徽记之戒将会在你对抗邪恶力量时提供更多的保护。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。', '向你致敬，$N。粉碎卡利姆多的敌人！告诉他们污染这片不灭星光照耀下的大陆要付出什么代价！$b$b你又赢得了一个强效施法。请把徽记之戒给我，我来灌注能量。', '', '去找塔纳利斯的阿纳克洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8750, '保护者之路', '', '', '相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献已被记录下来。$B$B防卫者的徽记之戒将会在你对抗邪恶力量时提供更多的保护。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。', '如此巨大的奉献真是少有。你已证明了你的意志坚定，$N。你会因为勇敢的守护着我们的世界而获得重赏。$B$B请将你的徽记之戒交给我，这样我才能强化它的能量。', '', '去找塔纳利斯的阿纳克洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8751, '卡利姆多的保护者', '', '', '起身吧，卡利姆多的保卫者!让世人看到你的力量!', '我从没看过这样不屈不挠的凡人!青铜龙军团将给你最后的附魔强化。这是永恒之王本人的希望!$B$B请将你的徽记之戒交给我，这样我才能开始施法。', '', '去找塔纳利斯的阿纳克洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8752, '征服者之路', '', '', '你的兴起是所有人之中最出色的，$N。愿你永远不会在征服者之路上迷失!', '相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献令人印象深刻。$B$B征服者徽记之戒将会大大提升你的力量和速度。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8753, '征服者之路', '', '', '你的兴起是所有人之中最出色的，$N。愿你永远不会在征服者之路上迷失!', '你一直保护卡利姆多生灵的行为已经被我们认可。把徽记之戒拿来，让我增强它的能量。', '', '去找塔纳利斯的阿纳克洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8754, '征服者之路', '', '', '你的兴起是所有人之中最出色的，$N。愿你永远不会在征服者之路上迷失!', '向你致敬，$N。粉碎卡利姆多的敌人！告诉他们污染这片不灭星光照耀下的大陆要付出什么代价！$b$b你又赢得了一个强效附魔。请把徽记之戒给我，我来灌注能量。', '', '去找塔纳利斯的阿纳克洛斯。', '', '', '', '');
