INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8760, '祈求者之路', '', '', '相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献令人印象深刻。$B$B塑能师的徽记之戒将会大大提升你的魔法和自然能力。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。', '如此巨大的奉献真是少有。你已证明了你的意志坚定，$N。你会因为勇敢的守护着我们的世界而获得重赏。$B$B请将你的徽记之戒交给我，这样我才能强化它的能量。', '', '去找塔纳利斯的阿纳克洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8761, '虔诚的祈求者', '', '', '起身吧，大塑能师!让世人看到你的力量!', '我从没看过这样不屈不挠的凡人!青铜龙军团将给你最后的附魔强化。这是永恒之王本人的希望!$B$B请将你的徽记之戒交给我，这样我才能开始施法。', '', '去找塔纳利斯的阿纳克洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8762, '驯鹿梅森', '出大事啦！驯鹿梅森被绑架了！$B$B冬天爷爷有八头驯鹿，梅森是其中的一头，也是烟林牧场的财产。我们收到了宣称对此次绑架事件负责的组织寄来的勒索信，而且不是一封，是两封！两封，你明白吗？节日即将来临，我们早已经穷得叮当响啦！帮帮忙吧，帮我们找到梅森，把它救回来！$B$B你可以看看这些勒索信里面有什么线索，找到梅森之后，把驯鹿之尘洒在它身上，这样就可以让它摆脱一切束缚！$B$B事不宜迟！', '找到驯鹿梅森。在你手头上的便笺中查找有关梅森下落的线索。$B$B当你找到它之后，往它身上洒一些驯鹿之尘，这样就可以让它摆脱任何束缚。$B$B解救梅森之后，把驯鹿之尘还给铁炉堡的乌莫尔特。', '你办到了!万岁!$B$B梅特森已经飞回去冬天爷爷的兽栏里了－－是的，梅特森是会飞的－－就在不久之前!这个尘土有点像是个符咒;我知道它可以的。你拯救了冬幕节还有熏木牧场免于疾病的侵袭。谢谢你，$N。$B$B听着……因为你对这里的贡献，我希望你可以拿着这个。这是一个非常特别的东西;如果你有坐骑的话，我想你可以好好的试试它。冬幕节快乐!', '$N!我给你的背袋里面的信息有没有包含什么有用的线索?我简直不敢去想那些恶棍会对梅特森做些什么……但我们绝对不可能付得出这么过份的赎金!', '', '转至铁炉堡，去找平民大厅的乌莫尔特。', '拯救驯鹿梅森', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8764, '远离保护者之路', '', '', '很好，$N。如果你改变心意，我会在这里帮助你。', '勇士，如果你决定走上另一条道路，请将你的徽记之戒交给我并从我们的安其拉敌人那里带回一堆甲虫。', '', '去找塔纳利斯的阿纳克洛斯。', '', '', '', '');
