INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8776, '目标：雷戈制奴者', '这一地区猖獗的异种虫类对我们来说是个巨大的威胁。你被指派负责对雷戈虫巢发动攻击，主要目标是雷戈制奴者。$B$B在你的任务完成之后，向指挥官玛尔利斯汇报。', '击杀30只雷戈制奴者，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 X才能完成这个任务。', '干得好，$N。你在佐拉虫巢攻击行动中的卓越表现已经引起了关注。', '你有什么事吗，$N?', '', '去希利苏斯找塞纳里奥要塞的指挥官玛尔利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8777, '目标：雷戈掘洞者', '这一地区猖獗的异种虫类对我们来说是个巨大的威胁。你被指派负责对雷戈虫巢发动攻击，主要目标是雷戈掘洞者。$B$B在你的任务完成之后，向指挥官玛尔利斯汇报。', '击杀30只雷戈掘洞者，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 XI才能完成这个任务。', '干得好，$N。你在雷戈虫巢攻击行动中的卓越表现已经引起了关注。', '你有什么事吗，$N?', '', '去希利苏斯找塞纳里奥要塞的指挥官玛尔利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8778, '铁炉堡军团需要爆炸品！', '铁炉堡军团突然要求我们提供一批高度危险的……材料。收集必需的物资，把他们交给铁炉堡军团的诺斯宾先生。', '把6瓶献祭之油、5瓶地精火箭燃油和10份致密炸药粉交给希利苏斯地区的佐拉虫巢附近的奥术师诺斯宾。你还必须带着后勤任务简报 IV才能完成这个任务。', '啊，太好了!这些东西会很有用!非常感激，$N!', '你有东西要给我吗，$N?', '', '去希利苏斯找佐拉虫巢附近的奥术师诺斯宾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8779, '研究材料', '地质学家拉克斯班的研究对于我们在希利苏斯的行动很有帮助，她最近需要一些特别的材料，以进行更多的研究。$B$B请收集这些材料，把它们交给拉克斯班。', '把1份大块魔光碎片、1份大块强光碎片和1块巨型绿宝石交给希利苏斯塞纳里奥要塞的地质学家拉克斯班。你还必须随身带着后勤任务简报 V才能完成这个任务。', '很好…这些东西有很大的帮助!这些材料在沙漠中很难取得，$N。谢谢你。', '你有东西要给我吗，$N?', '', '去希利苏斯找塞纳里奥要塞的地质学家拉克斯班。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8780, '战场上的护甲片', '我们的绷带储备在最近接连不断的战事之后急剧降低。收集大量的急救物资，把它们交给塞纳里奥要塞的唤风者梅恩·长角。', '将8块毛皮护甲片和8块重型护甲片交给佐拉虫巢附近的珍妮拉·钢锤。你还必须随身带着后勤任务简报 VII才能完成这个任务。', '谢谢你，我会把它们分发出去的。', '你有什么要给我的吗，$N?', '', '去希利苏斯的佐拉虫巢附近找珍妮拉·钢锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8781, '战场上的武器', '我们的绷带储备在最近接连不断的战事之后急剧降低。收集大量的急救物资，把它们交给塞纳里奥要塞的唤风者梅恩·长角。', '将2把月钢宽剑交给佐拉虫巢附近的珍妮拉·钢锤。你还必须随身带着后勤任务简报 VI才能完成这个任务。', '喔，太好了!我不用再听他们抱怨那些没用的武器了。谢谢你，$N。', '你有东西要给我吗，$N?', '', '去希利苏斯的佐拉虫巢附近找珍妮拉·钢锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8782, '制服供应', '战场的绷带储存量在最近战争伤亡之后急剧降低。把大量的急救物资带给塞纳里奥要塞的唤风者梅恩·长角。', '把1块月布、2卷符文布卷和1份铁网蛛丝交给塞纳里奥要塞的唤风者梅恩·长角。你还必须随身带着后勤任务简报 VIII才能完成这个任务。', '啊，我们正需要这些。非常感谢你，$N。', '你有什么要给我的吗，$N?', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8783, '特殊的材料', '瓦古斯是塞纳里奥要塞的铁匠，他需要一些附魔材料来为我们的部队制作强力的武器。去找到这些材料，把它们直接交给瓦古斯，这样塞纳里奥议会的军队就有了作战装备的保障。', '把2块魔化瑟银锭和2块魔化皮交给希利苏斯塞纳里奥要塞的瓦古斯。你还必须随身带着后勤任务简报 IX才能完成这个任务。', '啊，很好。这些材料的品质都很棒。谢谢你，$N。', '你有东西要给我吗，$N?', '', '去希利苏斯找塞纳里奥要塞的瓦古斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8784, '其拉的秘密', '你找到了一件上古其拉神器！也许神殿入口附近的龙用得到这件东西。', '把上古其拉神器交给隐藏在神殿入口处的龙类。', '真是重大的发现，$N。简直是太惊人了!这绝对会让我们对敌人古怪的心理多点了解。', '你看起来容光焕发!我知道这代表什么…', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8785, '奥格瑞玛军团需要魔精！', '奥格瑞玛军团要求我们提供一些不寻常的物资。他们在希利苏斯的表现很不错，因此我们最好尽快满足他们的需求。收集必需的材料，把它们交给那个名叫沙艾的巨魔。', '把6份强力魔精、6份大瓶魔精和8份献祭之油交给希利苏斯地区的雷戈虫巢附近的暗影祭司沙艾。你还必须随身带着后勤任务简报 IV才能完成这个任务。', '啊，很好。正是我需要的东西!我会用这些东西做一个特别的混合物。一个异种绝不会喜欢的东西!', '你带来了我要的材料吗，$N?', '', '去希利苏斯找雷戈虫巢的暗影祭司沙艾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8786, '战场上的武器', '奥格瑞玛军团需要更多的武器，但我们手头也很吃紧。想办法弄到他们要的武器，然后把东西交给雷戈虫巢附近的梅洛克·远途。', '将3把巨型铁斧交给雷戈虫巢附近的梅洛克·远途。你还必须随身带着后勤任务简报 VI才能完成这个任务。', '来的正好。这些补给能救回性命，$N。', '你有东西要给我吗，$N?', '', '去希利苏斯找雷戈虫巢的梅洛克·远途。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8787, '战场上的护甲片', '奥格瑞玛军团的志愿者赶来帮助我们作战，但是他们的护甲片在旅途中丢失了。去收集一些护甲片，把东西交给雷戈虫巢附近的梅洛克·远途。', '将8块毛皮护甲片和8块重型护甲片交给雷戈虫巢附近的梅洛克·远途。你还必须随身带着后勤任务简报 VII才能完成这个任务。', '啊，很好…我会把这些东西配置给军队，$N。奥格瑞玛军团感谢你!', '你有东西要给我吗，$N?', '', '去希利苏斯找雷戈虫巢的梅洛克·远途。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8789, '其拉帝王武器', '一千年以来，我们并没有无所事事地留在这里，$N。$B$B我们在这里看着这些野兽耗尽资源时自相残杀，我们倾听了它们密谋毁灭我们世界的谈话，我们还知道了它们内部的争权夺利。$B$B它们确实有弱点，而且我们知道如何利用这些弱点。$B$B找到它们在葬礼仪祭上陪葬用的武器，把它和他们自己的神所创造的最强的元素融合在一起，我们就可以创造出终结一切的武器。', '把其拉帝王武器和3块源质矿石交给安其拉神殿的亚雷戈斯，他会帮你制作使用源质强化过的武器。', '有了源质的灌注，这些武器就能轻易的击败其拉和他们的神。', '找到我要的东西。你就能变的强大无比，勇士。', '', '去找亚雷戈斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8790, '其拉帝王徽记', '亚雷戈斯认为，在一定情况下，因上古之神和他们的仆从之间的冲突而产生的元素也会对他们本身造成致命的威胁。凡人，我指的是源质。$B$B将其拉帝王徽记和这种元素交给我，我就能为武器注入巨大的力量。', '把其拉帝王徽记和3块源质矿石交给安其拉神殿的梦境之龙麦琳瑟拉，她会帮你制作使用源质强化过的武器。', '好好使用这个物品，$N。让他们尝尝自己附加在别人身上的痛苦。', '你会将他们击败并让我们脱离这些束缚。', '', '去找梦境之龙麦琳瑟拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8791, '奥斯里安之死', '来自其拉虫人的威胁已经被平息。可怕的奥斯里安被消灭了。$B$B卡利姆多的人民听到这个消息应该可以松口气了。将奥斯里安的徽记交给塞纳里奥要塞的指挥官玛尔利斯。', '将无疤者奥斯里安的徽记交给希利苏斯塞纳里奥要塞的指挥官玛尔利斯。', '我要给你最高的奖励，你还能选择一样强大的物品，$N。你为卡利姆多的人民做了伟大的贡献。', '啊，$N，你回来了!而且还安然无恙，我应该说。你从安其拉带回来什么消息?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8801, '克苏恩的遗产', '安其拉的高墙在震颤。一个比这个世界本身还要古老的邪恶力量已经被摧毁了。$B$B你看着巨大的尸体，心跳几乎要停止了。在死一般的寂静中，你还是能感受到克苏恩的邪恶力量。$B$B你完成了一件不可能完成的任务。$B$B你取下了这个恶魔的眼珠，把它放入背包。$B$B把克苏恩之眼交给下一间房子里的龙类吧。', '将克苏恩之眼交给安其拉神殿的凯雷斯特拉兹。', '我们会自己离开这个地方，$G殿下:女士;$N – 只要我们确定里面的恶魔已经被完全消灭，你的传说之旅就要结束了。', '<凯雷斯塔兹在你面前跪下。>$B$B$G大人:女士;$N，你可以随意差遣我。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8802, '卡利姆多的救世主', '到时光之穴去吧，$N$g大人:女士;。阿纳克洛斯还在等你回去呢。把克苏恩之眼交给他，我相信他一定会很乐意在自己的收藏品中增加这么一件东西。', '把克苏恩之眼交给时光之穴的阿纳克洛斯。', '勇士，主人把数千年来散落在时光之穴中的神器留给了你 – 你可以随意挑选。', '$G殿下:女士;$N!结束了…', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8807, '研究材料', '地质学家拉克斯班的研究对于我们在希利苏斯的行动很有帮助，她最近需要一些特别的材料，以进行更多的研究。$B$B请收集这些材料，把它们交给拉克斯班。', '把1份大块魔光碎片、1份大块强光碎片和1块巨型绿宝石交给希利苏斯塞纳里奥要塞的地质学家拉克斯班。你还必须随身带着后勤任务简报 V才能完成这个任务。', '很好…这些东西有很大的帮助!这些材料在沙漠中很难取得，$N。谢谢你。', '你有东西要给我吗，$N?', '', '去希利苏斯找塞纳里奥要塞的地质学家拉克斯班。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8808, '制服供应', '最近不断涌来的志愿者导致我们制服紧缺。去搜集一些制服的材料，然后把它们交给唤风者梅恩·长角。', '把1块月布、2卷符文布卷和1份铁网蛛丝交给塞纳里奥要塞的唤风者梅恩·长角。你还必须随身带着后勤任务简报\r\n VIII才能完成这个任务。', '啊，我们正需要这些东西。你的努力很受肯定，$N。', '你有东西要给我吗，$N?', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8809, '特殊的材料', '瓦古斯是塞纳里奥要塞的铁匠，他需要一些附魔材料来为我们的部队制作强力的武器。去找到这些材料，把它们直接交给瓦古斯，这样塞纳里奥议会的军队就有了作战装备的保障。', '把2块魔化瑟银锭和2块魔化皮交给希利苏斯塞纳里奥要塞的瓦古斯。你还必须随身带着后勤任务简报 IX才能完成这个任务。', '啊，很好。这些材料的品质都很棒。谢谢你，$N。', '你有东西要给我吗，$N?', '', '去希利苏斯找塞纳里奥要塞的瓦古斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8810, '战场上的绷带', '我们的绷带储备在最近接连不断的战事之后急剧降低。收集大量的急救物资，把它们交给塞纳里奥要塞的唤风者梅恩·长角。', '把30根重符文绷带，30根厚丝质绷带和30根厚绒线绷带带给唤风者梅恩·长角。你还必须随身带着后勤任务简报 X才能完成这个任务。', '来的正好。这些补给能救回性命，$N。我们感谢你的努力。这是你的下一个任务。', '你有东西要给我吗，$N?', '', '去希利苏斯找塞纳里奥要塞的唤风者梅恩·长角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8811, '一枚荣誉徽章', '', '', '很好，你的贡献已经被记录在册，而你也得到了不错的评价。继续好好干，$C。$B$B如果你有更多徽章的话，我随时可以帮你进一步提高声望。', '如果你只有一枚荣誉徽章，我可以用它来帮助你提高在暴风城的知名度。$B$B请注意，你最好一次交给我十枚荣誉徽章，这样你的知名度会获得更大的提高。我们提供针对一枚荣誉徽章的交换服务是为了方便那些没有足够荣誉徽章的冒险者。$B$B总之，如果你想要用一枚荣誉徽章来换取声望的话，我随时在这里等着你。', '', '去找丹莫罗的达纳苏斯嘉奖官。', '', '', '', '');
