INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8829, '沙漠生存包', '当前塞纳里奥要塞的骑兵团缺乏足够的马刺，去收集大量马刺，然后立即把它们交给塞纳里奥要塞的维斯·库鲁兹队长。', '将1块暗影之皮、3条磨损的憎恶缝合线和1件暮光信徒长袍交给塞纳里奥要塞的奥蕾尔·金叶。你还必须随身带着后勤任务简报 XI才能完成这个任务。', '太好了，我相信这些就足够了。我会把这些制成暮光之锤大使所穿的衣服。我向艾露恩祈祷我的制作技能可以再次骗过我们的敌人。$B$B不过别担心，你已经尽了你的责任，会获得适当的奖励。你是个忠诚、可靠的盟友，$N。', '你有东西要给我吗?', '', '去希利苏斯找塞纳里奥要塞的奥蕾尔·金叶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8830, '一枚荣誉徽章', '', '', '很好，你的贡献已经被记录在册，而你也得到了不错的评价。继续好好干，$C。$B$B如果你有更多徽章的话，我随时可以帮你进一步提高声望。', '如果你只有一枚荣誉徽章，我可以用它来帮助你提高在暴风城的知名度。$B$B请注意，你最好一次交给我十枚荣誉徽章，这样你的知名度会获得更大的提高。我们提供针对一枚荣誉徽章的交换服务是为了方便那些没有足够荣誉徽章的冒险者。$B$B总之，如果你想要用一枚荣誉徽章来换取声望的话，我随时在这里等着你。', '', '去找泰达希尔的军官鲁娜莱。', '', '', '', '');
