INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8844, '一枚荣誉徽章', '', '', '很好，你的贡献已经被记录在册，而你也得到了不错的评价。继续好好干，$C。$B$B如果你有更多徽章的话，我随时可以帮你进一步提高声望。', '如果你只有一枚荣誉徽章，我可以用它来帮助你提高在暴风城的知名度。$B$B请注意，你最好一次交给我十枚荣誉徽章，这样你的知名度会获得更大的提高。我们提供针对一枚荣誉徽章的交换服务是为了方便那些没有足够荣誉徽章的冒险者。$B$B总之，如果你想要用一枚荣誉徽章来换取声望的话，我随时在这里等着你。', '', '去找军官乌萨雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8845, '十枚荣誉徽章', '', '', '非常好!你肯定做出了巨大的牺牲才能获得这些荣誉徽章，为此你将得到充分的肯定。正是许许多多像你一样的冒险者让一切都变得不同的。$B$B如果你还有更多荣誉徽章的话，尽管来找我，我很高兴能为你做点什么。', '完成了自己的任务并得到荣誉徽章的冒险者可以把他们的徽章交给我，你每次把10枚徽章交给我，我都可以用它们来显着提升你在暴风城的声望。当然，我也接受单枚徽章的交换申请，但是这对于声望的提升效果就会逊色许多。虽然我们不会忘记每一位冒险者的努力，但是贡献越大，回报就越大。$B$B如果你有足够的荣誉徽章要给我的话，随时来找我。', '', '去找军官乌萨雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8857, '亚什巨像的秘密', '我正在寻找那些经过战争洗礼的冒险者，看他们是否愿意从亚什巨像的尸体上取到新鲜的獠牙样本，并把它交给藏宝海湾的奥格索普。不，不，我可不希望你在那家伙的尸体附近游荡。你只需迅速取回样本，这东西腐烂了就不好办了！', '把亚什巨像的獠牙交给藏宝海湾的奥格索普·奥布诺提斯。', '哦，我会利用这块甲壳雕刻出栩栩如生的小鸡的!干得好，$G小伙子:姑娘;!', '嗯?你发现了什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8858, '雷戈巨像的秘密', '我最想做的就是将这块獠牙套到奥菲斯特那肥硕的脑壳上……但是，我得留在这儿从那些畸形的蟑螂身上收集样本。你瞧这工作量，我大概要到凌晨时分才能赶到那儿。$B$B替我将这份样本交给奥菲斯特，要快，$C。他会付给你丰厚的报酬！$B$B他就在灼热峡谷的瑟银哨塔。', '把雷戈巨像的獠牙交给灼热峡谷的工头奥菲斯特。', '太棒了。我们一定会利用这东西制造出拥有强大力量的护甲的。这是先前许诺的奖励。', '嗯……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8859, '佐拉巨像的秘密', '我的仆人几乎搭上性命才取回这个样本。你必须赶快！玛克斯韦尔·泰罗索斯男爵迫切地想要一份新鲜的獠牙样本。他相信巨像背后的秘密能帮助我们对抗亡灵天灾！$B$B你怎么还在这儿？快去圣光之愿礼拜堂！当然，你会因此获得一笔丰厚的奖励……', '把佐拉巨像的獠牙交给东瘟疫之地圣光之愿礼拜堂的玛克斯韦尔·泰罗索斯男爵。', '太棒了，时间刚刚好!干得好，$G小伙子:姑娘;!', '朋友，你穿那双靴子看起来有些笨拙。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8860, '庆祝新年！', '暴风城正在举行新年庆典！所有人都可以全天畅饮美酒佳肴，晚上还会有焰火表演！听起来是不错……不过藏宝海湾也有这样的庆典，我敢说这个肯定更棒！$B$B总之，暴风城的旅店老板奥里森需要一些烟林牧场的补给品才能应付需求量巨大的庆典，你能帮我送一趟货吗？$B$B谢谢你，$n！旅店老板奥里森在镶金玫瑰旅店，就在暴风城的贸易区里。', '将烟林补给品交给暴风城的旅店老板奥里森。', '喔，我的熏木补给品!太好了!我很需要这些东西来喂饱来参加城里参加庆典的人们!$B$B谢谢你，$N。请收下这个当作报酬，还有，别忘了畅饮几杯，并和外面的狂欢者一起跳个舞吧!', '你好啊!你是来参加新年庆典的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8861, '庆祝新年！', '雷霆崖正在举行新年庆典！所有人都可以全天畅饮美酒佳肴，晚上还会有焰火表演！听起来是不错……不过藏宝海湾也有这样的庆典，我敢说这个肯定更棒！$B$B总之，雷霆崖的旅店老板帕拉需要一些烟林牧场的补给品才能应付需求量巨大的庆典，你能帮我送一趟货吗？$B$B谢谢你，$n！帕拉的旅店就在通往猎人高地的吊桥边。', '将烟林补给品交给雷霆崖的旅店老板帕拉。', '喔，非常好!这些补给品可以用来喂饱来这里庆祝新年的民众!$B$B感谢你，$N。我欠你一个人情。请收下这一点钱吧吧…别忘了 - 尽情地饮用外面的酒，和大家一起好好庆祝一番!', '你好啊，$C!你是来雷霆崖参加新年庆典的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8862, '艾露恩的蜡烛', '', '', '太好了－我收下这些先祖硬币。请带着艾露恩的蜡烛以及我的祝福。还有，请收下赠送的烟火。$B$B祝你新年快乐，充满喜悦，$N。$B$B如果你选择挑战年兽及他的爪牙，你就会发现艾露恩的蜡烛非常有用……', '艾露恩的蜡烛对新年信徒而言是个带有极大尊敬的工艺品。蜡烛内有着真正的月光，等待被释放!$B$B这个光束对大部分的生物都是无害的，但是你会发现年兽和他的爪牙会感到眩目并被它灼伤。', '', '去找月光林地的瓦拉达尔·星歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8864, '节庆长裙', '', '', '很好 – 我接受这些先祖硬币。这件衣服现在属于你了，祝你好运。另外，我免费赠送这些烟火。$B$B如果你有更多的先祖硬币要交易，就再来和我谈谈。谢谢你，愿你有个愉快的新年。', '你可能会对我出售的洋装感兴趣。这样的洋装适合在新年穿着，而且我今天带来的款式都是最好的一批。每件洋装都是用最精细柔软的材料手工缝制。$B$B拿一些先祖硬币来交换，我就会让你从这三种款式中挑选一件。这样你可以接受吗?', '', '去找月光林地的瓦拉达尔·星歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8865, '节庆裤装', '', '', '很好 – 我接受这些先祖硬币。请收下我的祝福。另外，我免费赠送这些烟火。$B$B如果你有更多的先祖硬币要交易，就再来和我谈谈。我在整个新年都会提供不同的物品。', '很高兴告诉你，我有一系列的节庆长裤套装供你选择…只是要用先祖硬币来交换。如果时髦对你而言很重要的话，这些就是你要找的东西!我跟你保证，你不可能在别的地方买到这样的长裤套装。$B$B拿一点先祖硬币来交换，我就会让你从这三种样式中挑选一件。这样你可以接受吗?', '', '去找月光林地的瓦拉达尔·星歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8867, '春节烟花', '每年月光林地的德鲁伊们都会举行庆典，纪念我们打败远古恶魔的日子。$B$B我们赞美长者的智慧，共享美食盛宴，当然……我们还会燃放烟花！$B$B这些不是普通的烟花表演，$N。这些烟花承载着月神的赐福，用月火点燃它们，以此来祝愿大家健康。$B$B你只需付出一点点花费，就可以从我们的商人那里购买一些五颜六色的烟花，然后在周围的发射器上点燃它们。', '点燃8枚春节烟花和2组春节烟花束，然后回到任何一座主城的春节预告者身边。', '做的好，$N。$B$B既然你对此感兴趣，何不接受月光林地庆典的邀请呢?$B$B如果你有空参加的话，那是个愉快的盛典。我们有美食、好酒、趣事，当然…还有烟火表演!$B$B站在月光之环中打开邀请函，你就会被传送至月光林地去了。', '你找到那些发射器了吗，$N?', '', '去找春节预告者。', '点燃春节烟花', '点燃春节烟花束', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8881, '大型烟花束', '', '', '谢谢你，$N。这是大型烟花束的设计图。愿你制造出来的烟花给所有人都带来快乐和幸运!', '必须有许多材料和精湛的技艺才能制作大型烟花束，但效果绝对惊人且值回票价!!给我一些先祖硬币，我就把大型烟花束的制作工艺传授给你。', '', '去找月光林地的法蕾尔·星歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8882, '烟花束发射器', '', '', '这是你的结构图。仔细研究，学会它……$B$B祝你好运，$N。希望你的庆祝活动会像新年一样有趣!', '最灿烂的烟火秀一定要发射烟花束，而且那些烟花束绝对要用烟花束发射器发射!那么要你学会制作烟花束发射器的秘诀不是很有道理吗?拿点先祖硬币来给我，我就会传授你这个知识。', '', '去找月光林地的法蕾尔·星歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8884, '鱼人……', '你好，$c。看看海岸那边，你发现有什么不对劲吗？对，对，我们的海滩……我们的静谧海岸，竟然成了一群卑贱鱼人的乐土。$B$B这是对我们的侮辱，是对我们尊严的践踏，我们绝对不能接受！$B$B如果你觉得自己能够胜任的话，我有个任务要给你。我要它们的徽记！看看这样的威吓能不能让它们彻底消失，如果它们长了脑子的话，就应该会立即退回到属于它们的肮脏深海里去！', '收集8枚暗鳞鱼人的徽记，并把它们带回永歌森林中的一处可遥望静谧海岸的悬崖旁，交给那里的哈斯温里奥。', '做的好，$C。凭这味道，我敢说你一定带着我要的东西回来了，说不定还超出我要的数量。我相信这些东西一定有其用途，做个炖肉之类的。$B$B唉，不过你的努力似乎没有给他们足够的教训;这些鱼人并没有撤退。这表示我们需要一些更直接的行动!', '我们远行者居所的骑兵巡逻队奉命导正我们这块美好土地上遭到的破坏。为达此目的我们会无所不用其极。$B$B我相信你已带着我要你去收集的鱼人头颅回来?', '', '去找永歌森林的哈斯温里奥。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8885, '呜啦哇啦的戒指', '该死，你的恐吓行为看来失败了，暗鳞鱼人完全没有被吓跑。但是，不用怕，我想我还是很清楚怎样才能把它们送上路的。我个人的小小复仇也可以趁此机会得到实现了。$B$B那里有个自称呜啦哇啦的鱼人酋长，它总是喜欢在河口南边的金色沙滩上散步，还戴着一枚象征挑衅与嘲弄的戒指。$B$B杀掉呜啦哇啦，把它的戒指给我拿来。然后我们就可以坐观这群妖孽惊惶失措的样子了！', '从暗鳞酋长的尸体上夺回呜啦哇啦的戒指，并把它带回永歌森林中的一处可遥望静谧海岸的悬崖旁，交给那里的哈斯温里奥。', '终于!虽然厉鳞没有如期望地按原本的计画行事，但是当你将他们所谓的首领给宰了，看着他们惊慌失措实在有够过瘾。谢谢你，银月城的辛多雷也感激你!$B$B请从这些东西里选择一个以慰劳你付出的努力。', '你是我成功与复仇的希望，$C。你拿到戒指了吗?', '', '去找永歌森林的哈斯温里奥。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8886, '暗鳞强盗！', '有你这位$c来帮忙就太好了！那些浑身上下粘糊糊的暗鳞鱼人竟然抢走了我的货！失心者把我的那些魔法货物偷走就已经够糟的了，现在可好，鱼人竟然把剩下的货物都抢走了！以后要怎么办才好！$B$B你看，你能帮我把货给抢回来吗？我也不指望你能把全部的货物都带回来，但你要是能帮忙收回一点点来，我也会感激万分的。我想，那群暗鳞鱼人应该就躲在港口西南方的金色沙滩上的那些茅草屋里。', '夺回6箱凯莉森德拉船长的货物，把它们交给永歌森林阳帆港东侧营地中的凯莉森德拉船长。', '你办到了!你让我免于毁灭还让那些恶心的生物尝到了我的复仇!$B$B现在我只希望请那两名漂亮的游侠帮我把这个货物装载到运货车上，不要再引诱鄙恶者，我终于能够离开这里了!我们会等微兰德丝和他的游侠重新取回船厂再回来。$B$B来，收下这笔钱。这是我的一点心意，也是我为了奖励你的努力仅能做的。', '我对像你这样的人来帮忙感到十分感激，$N。你的帮助几乎让我可以绽放笑容。但后来我就知道这些怪物对我的船做了还有奎尔萨拉斯发生了什么事。$B$B你有货物的消息了吗?', '', '去找永歌森林的凯莉森德拉船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8887, '凯莉森德拉船长的航海图', '有趣……你找到的这个东西是一只防水的小皮筒，里面装着几张整齐折叠好、并经过防水涂蜡处理的羊皮纸。展开纸张之后，你发现纸上清晰地标明了一些航海线路，角上都印着某位“凯莉森德拉船长”的私人印章。$B$B你似乎听说过，有一处小规模的营地就在阳帆港东侧不远的地方。或许这位船长也在那里？', '将凯莉森德拉船长的航海图交还给永歌森林阳帆港东侧营地中的凯莉森德拉船长。', '喔你这个可爱的、可爱的$C!我完全不晓得那些恶心的厉鳞鱼人还偷走了我的航海方针!没了它们，我们到泊地修船后就再也没机会航海了。$B$B非常谢谢你!来，收下这些钱以聊表我一点心意。', '嗨，$C，见到你真高兴。我知道，我出现在这里是很疯狂的事，泊地都被鄙恶者给占据了。微兰德丝和他的游侠发誓要保护我直到我取回我的货物。$B$B你手里拿得是什么……看起来有那么点眼熟?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8889, '关闭高塔', '正如我之前说过的，这里有些事需要你的帮助。你应该已经知道了，魔导师达斯维瑟派我来关闭支撑着这座法师塔的能源系统。它们一共有三处，分别位于塔中不同的位置。$B$B但不幸的是，我来得有些太晚了，整个达斯维瑟之塔正如当前你所见到的这样，已经完全被某种奇怪的魔法生物占据了。我是没有办法使用暴力来完成这个任务的，而你，一位优秀的$c，是否能轻松解决这个小问题呢？', '关闭达斯维瑟之塔内的3处达斯维瑟之塔能量源，然后将断能宝石还给永歌森林的学徒罗拉塔莉丝。', '我非常感激你的帮忙，但听到有些学徒堕落于他们的魔法瘾真让我痛心。$B$B现在尖塔的能源被关闭，我想我可以在这里待一阵子，看看情况是否够稳定，我再潜入塔中取回他们的遗物。', '我从这里看不清楚……你已经关闭了暮萎尖塔的能源开关吗?', '', '去找永歌森林的学徒罗拉塔莉丝。', '关闭第一处能量源', '关闭第二处能量源', '关闭第三处能量源', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8891, '被放弃的研究', '你发现了一本似乎是魔导师达斯维瑟的研究日记之类的东西。粗略的浏览之后，你发现这本日记中记载了一些十分具有震撼性的研究尝试，他曾试图过滤已被腐蚀的魔法能量流！这或许也是造成达斯维瑟之塔事故的重要原因之一。魔导师肯定希望能找回这本日记。', '将魔导师达斯维瑟的日记交还给永歌森林远行者居所的魔导师达斯维瑟。', '拿去，$N，我犯罪的证据。这本日志包含我所有计画不周的研究。$B$B我不听劝告，执意我的研究，直到一切为时已晚。然后，等到我知道自己犯了错，我已尽力挽回。但是几个学生早已逃之夭夭。我撤空了塔以避免他们受到腐败，但是我慌乱之中忘了关闭能源。$B$B我会烧了这本册子，不让其它人再身受其害。我只想帮助辛多雷。', '这是什么?好眼熟。喔不，这本日志……我的调查…….这就是造成现在一切的根源。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8892, '阳帆港', '阳帆港现在已经彻底沦落为失心者的巢穴了。一旦我们得到了增援，就可以彻底将他们连人带尸全部从那里扫出去，$N。$B$B但在那之前，我希望你能先过去给他们一些教训。去吧，让他们见识见识我们的手段。从晴风村一直沿路向西走，就可以找到阳帆港了。', '杀死5名失心者暴徒和5名失心者无赖，然后向永歌森林的游侠戴戈利恩复命。', '这应该足以让那些家伙记取教训了。做的好，$N。', '你给鄙恶者那些败类一点颜色瞧瞧了吗?', '', '去找永歌森林的游侠戴戈利恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8893, '超级测蛋器', '', '', '你将角鹰兽的蛋放入机器，随后里面传来了一些奇怪的机械声响和嘟嘟声。$B$B似乎测蛋器正在为这颗蛋称重、测量和包装。真是快捷又完善的服务!', '超级测蛋器是克格尔.曲藤的最新成果，看起来真是令人印象深刻。$B$B你刚刚接触到超级测蛋器的控制面板，它就劈啪作响了起来。', '', '去找塔纳利斯的测蛋器。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8894, '清理广场', '这太可怕了！真的太可怕了！法师塔里发生了一些奇怪的事情，魔导师和他的学徒都已经跑光了，现在整座塔内都充斥着这些魔法能量构成的野兽！谁告诉我的？没有人告诉我！别问我没有人是谁……$B$B$C，你一定得帮我把些东西全部清理掉……我可没法在这个畸形怪兽满地乱跑的庭院里打扫卫生！', '杀死6只法力蛇和6只以太魔，然后向永歌森林达斯维瑟广场的看守者维林森复命。', '嗯，我想这样应该可以了，是吧?谢谢帮忙，$C。我只希望在博学者回到暮萎尖塔前能把这一团乱完全清理掉。$B$B你离开的路上可以再多杀几只怪物，如\r\n果你有这么好心的话。', '你把他们处理掉了吗?消灭了一堆怪物吗?要是博学者暮萎又带着这些东西出现我该怎么办?', '', '去永歌森林找达斯维瑟广场的看守者维林森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8895, '送往北部圣殿的信', '看来你确实有一定的能力，$N，这让我很欣慰。既然你这么渴望能有所建树，那么我再给你一个任务。$B$B这是一封写给魔网监护者凯丹尼斯的信。他是一名奥术师，负责管理北部圣殿。从鹰翼广场出去后向西南方向前进就可以找到他。他是一位非常重要的人物，所以我希望你不要用无关紧要的琐事打扰他。', '将无记号的信件送给永歌森林北部圣殿的魔网监护者凯丹尼斯。', '谢谢你，$N。我一直都在等这封信。', '找我有事吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8897, '亲爱的科兰拉', '我得在城门驻守巡逻，但是我心里一直想着我的恋人科兰拉。如果幸运的话，我还能注视她一会儿；但是，你瞧瞧我，我不过是个薪水微薄的小军官，随时都可能奉命赶赴前线。$B$B她会忘记我吗？城里有那么多男人，其中不乏有钱的家伙。$B$B不管怎样，我写了一些东西给她……如果你能帮我交给她的话，我会很感谢你的。', '将亨德瑞克中尉精心书写的信件交给暴风城银行外面的科兰拉·迪恩。', '喔，太贴心哩!这是他第一次寄东西给我。你觉得他是认真的吗?$B$B克莱拉.迪恩?我猜这里面有戒指吧，喔，我好像讲话讲太快了。谢谢你。', '$g嗨，帅哥。有什么是我帮得上忙的吗?:喔，天啊!我能帮你什么呢?;', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8898, '亲爱的科兰拉', '我上次去暴风城银行办事时遇到一位少女。她偷走了我的心。现在，我想她想得快发疯了！我想把这封信给她——我反反复复写了12次呢！$B$B这封信装满了我的心意，我一定要让她看看。$B$B如果你顺路的话，能帮我这个忙吗？', '将皱褶的信件交给暴风城银行外面的科兰拉·迪恩。', '托眉克? 喔，对。我当然记得他。他留着很性格的胡子，胡子下还有着亲切的笑容。$B$B啊，不敢相信他还记得我!', '$g嗨，帅哥。有什么是我帮得上忙的吗?:喔，天啊!我能帮你什么呢?;', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8899, '亲爱的科兰拉', '要怎么描述她的美丽呢？我脑海里涌现了数千个形容词，却不知道该挑哪些。$B$B这些词语扰乱了我的思绪，令我的舌头打结。$B$B我久久地思考着，却发现任何一个词语都不足以描述她清新脱俗的容貌。啊，不行，她一定得尽快看到我的情书，不然其它的追求者肯定会夺走她的芳心。', '将精美的信件交给暴风城银行外面的科兰拉·迪恩。', '我之前从来都没收过这种耶。好可爱!', '$g嗨，帅哥。有什么是我帮得上忙的吗?:喔，天啊!我能帮你什么呢?;', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8900, '亲爱的艾琳娜', '她是如此悲伤，上次我路经幽暗城的时候就注意到了。我是说，她看起来很忧郁——你不这样认为吗？$B$B但是在一番交谈之后，我们的关系有了微妙的变化。除了她，谁都不能理解我心里所想的事儿。$B$B当我把这种感觉告诉别人时，他们总是嘲笑我，因此我再也没有跟她讲过话了。但是我好想她……你能帮我把这封信带给她吗？你得亲自把信送到她手上。', '将轻折的信件交给幽暗城银行附近的艾琳娜·海东。', '你知道兽人一向不善表达。当然我们也没机会去一探究竟。谢谢你带这个给我。', '喔，我要怎么报答这个忙呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8901, '亲爱的艾琳娜', '年轻的$c，你知道什么是爱情吗？我一直以为自己跟爱情扯不上什么关系，直到最近在幽暗城邂逅了一位名叫艾琳娜的少女。我和我的族人们都不常外出，更不要说被遗忘者了。$B$B但是，我日日夜夜都在想她。$B$B你能帮我把这封信带给她吗？我想请她来莫高雷。希望她能接受我的邀请。', '将精心书写的信件交给幽暗城银行附近的艾琳娜·海东。', '泰玛写给我的信真是窝心。但是，虽然他的文字让我很感动，我还是不能考虑一个牛头人的爱。你想想，外型和思想我们都太不相同了。$B$B还好他不是一个人当面拿给我。我不忍心伤他的心啊。', '喔，我要怎么报答这个忙呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8902, '亲爱的艾琳娜', '很久很久以前，我就跟青梅竹马的艾琳娜订婚了。虽然我对她的爱恋在多年之前就消退了，但她依然时常闯入我的内心。$B$B也许，即使在经历了那么多事情之后，我们的心中还是为爱情留下了空间。$B$B我相信她也变了许多。你能帮我把这封信交给她吗？我自己去的话肯定会很紧张的。', '将充满感情的信件交给幽暗城银行附近的艾琳娜·海东。', '这勾起了好久前的回忆，$N。艾妮亚.托尔。这本来应该是我的名字，你知道吗。我们本来会在湖岸边有一场美丽的婚礼。当他退休后，我们就会找个农场隐退。$B$B不过，那都是梦。$B$B如果他现在看到我，我怀疑他还会不会在我身上看到艾妮亚。只有冰冷的躯体和已死的心……', '喔，我要怎么报答这个忙呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8903, '危险的爱情', '这场突然爆发的爱情流行感冒一定有问题。这不合常理，这是丑恶的，这甚至可能是对我们联盟安全的一个重大威胁。$b$b你想想，要是所有的卫兵都染上了这花痴病，那可怎么办？这种事情绝不能发生。$b$b到暴风城的卫兵中间去打探打探，给我抓一个已经着了道的卫兵出来。', '弄到一张暴风城卫兵的卡片，并把它交给暴风城的阿瑞斯坦·莫塔。', '果然是真的。真是不可思议。怎么会发生这种事?让我想想。这后面一定有什么原因。', '我的担心是对的吗?守卫们感染了这种相思病吗?', '', '去找暴风城的阿瑞斯坦·莫塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8904, '危险的爱情', '这场突然爆发的爱情流行感冒一定有问题。这可真讨厌，我们的防御力量被大大削弱了！这是对我们安全状况的一个重大威胁。$b$b那么多人都染了这种病，整天做些奇怪的事，这就已经很糟糕了。更糟的是，这种情况现在已经蔓延向了我们的卫兵，本来他们应该绝对免疫这类诱惑的。$b$b到幽暗城的卫兵中间去打探打探，给我抓一个已经走火入魔的卫兵出来。', '弄到一张发臭的卡片，并把它交给幽暗城的芬斯塔·艾吉勒。', '果然是真的。真是不可思议。怎么会发生这种事?让我想想。这后面一定有什么原因。', '我的担心是对的吗?我们的白痴守卫克服了没?', '', '去银松森林找幽暗城的芬斯塔·艾吉勒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8905, '热心的建议', '你好，$c。我这里有一些你可能会很感兴趣的东西。$B$B它跟你们这个职业的人平常穿着的那些护甲有点类似，但质量上远远好于你们现在所拥有的。要是你能帮我一个小忙的话，我愿意拿它来从你手里换一件普通的套装组件。$B$B栖息在冬泉谷的霜刃豹和熊身上的血液有着某种我当前很需要的特性。给我带来一批样本，再把普通套装的手腕部分拿来，当然了，你还得支付一些金币。你会发现这其实是笔很划算的交易。', '将15份冬泉谷血样、20枚金币以及一副野性之心护腕交给铁炉堡的德莉亚娜。', '太棒了!那就来交易吧。要能和这件护甲搭配，还真不是件容易的事。可是我怕我马上就用不到这件了。$B$B若你还想帮我忙，我就再给你其它装备。', '你把我要的东西带来了吗，$N?', '', '去铁炉堡找王座厅的德莉亚娜。', '', '', '', '');
