INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8919, '热心的建议', '嗨，$C！从你的言行举止就能看出你是个历经沧桑、见多识广的家伙。但是我打赌你没有见过这么一件护甲。$B$B要是你能帮我一个小忙的话，我愿意拿它来从你手里换一件普通套装的手腕\r\n部分。$B$B我需要大量生活在希利苏斯地区的蝎子和蜘蛛的毒液。把毒液样本带给我，再支付一些金币，我就跟你交换。', '将15份希利苏斯毒液样品、20枚金币以及一副鬼雾护腕交给奥格瑞玛的莫克瓦尔。', '啊，是的。莫克斯一定会对这个感到非常满意。$B$B那护腕以前是大型护甲装备的一部份。如果你能再帮我忙的话，我这里还有更多可以跟你护腕搭配的装备。', '你把我要的东西都带来了吗，$N?', '', '去找奥格瑞玛的莫克瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8920, '热心的建议', '嗨，$C！从你的言行举止就能看出你是个历经沧桑、见多识广的家伙。但是我打赌你没有见过这么一件护甲。$B$B要是你能帮我一个小忙的话，我愿意拿它来从你手里换一件普通套装的手腕部分。$B$B我需要大量生活在希利苏斯地区的蝎子和蜘蛛的毒液。把毒液样本带给我，再支付一些金币，我就跟你交换。', '将15份希利苏斯毒液样品、20枚金币以及一副勇气护腕交给奥格瑞玛的莫克瓦尔。', '啊，是的。莫克斯一定会对这个感到非常满意。$B$B那护腕以前是大型护甲装备的一部份。如果你能再帮我忙的话，我这里还有更多可以跟你护腕搭配的装备。', '你把我要的东西都带来了吗，$N?', '', '去找奥格瑞玛的莫克瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8921, '灵质提纯器', '啊，你需要我最新的研究产品……超维度幽灵显形器！不过遗憾的是，我已经消耗光了所有的人力和资金，没法继续研究了。$B$B你说你愿意帮忙？太好了！我们首先需要创建起一个能够收集亡灵物质的设备，制造一台灵质提纯器！这可不是一项简单的工作，$N。$B$B我需要你给我找来一个奥金转换器，一些强效不灭精华和一些石鳞鱼油。我还需要一些来自燃烧平原的岩浆流里的火山灰，用来制造过滤网。', '将1个精密奥金转换器、4份强效不灭精华、10瓶石鳞鱼油、25份火山灰和40枚金币交给加基森的穆克斯·玛纳斯卡波。', '这正是我要的材料。你也及时赶上了，$N!$B$B再过一下子你的蒸馏器马上就要派上用场了!同时，收下这个作为你协助我完成计画的奖励!', '我知道材料有点贵……但是我保证每一项物品都是必需的!', '', '去找塔纳利斯的穆克斯·玛纳斯卡波。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8922, '超自然的设备', '我必须想个办法与安泰恩·哈尔蒙谈谈……更确切地说，和他的鬼魂好好谈谈！$B$B我知道有个技师对这种超自然的东西有着一种奇怪的兴趣。他宣称他可以造出一台能让与死者对话的机器！$B$B你收集来的血其实是为他所准备的，到加基森去，把这些带给他，就算是支付给他的酬劳吧！', '将封起来的血液容器交给加基森的穆克斯·玛纳斯卡波。', '太好了!我正好需要它!$B$B你说是德莉娜派你来的?', '你有东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8923, '超自然的设备', '你竟然收集到了这么多，看来真是个够胆量的家伙。要不然就是我给你的护甲组件挑起了你兴趣吧。要是你还愿意帮我的忙，我还能给你更多的组件。$B$要你采集的毒液样本是为我的一个熟人穆克斯·玛纳斯卡波准备的。他是个技师，对于超自然的事物有着浓厚的兴趣。他最近研究中的新项目是一台可以让你与死者交谈的机器！那也是我联络安泰恩，并且了解自己处境的最后希望了。', '将封起来的毒液容器交给加基森的穆克斯·玛纳斯卡波。', '太好了!我正好需要它!$B$B你说是莫克瓦派你来的?', '你想跟我谈谈吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8924, '猎取灵质', '这真是一件完美的器物，若能应用在工程学里就太好了，我不得不这么说！恐怕，你现在需要跑点远路了，得去一些我们所必需的虚体亡灵生物里的灵质来。$B$B你看，不同的气候将会导致幽灵体的亡灵生物的灵质不同。希利苏斯的被折磨的暗夜精灵，冬泉谷的上层精灵幽灵，以及东瘟疫之地的幽灵和女妖或许能分别给我们提供不同的灵质样本。在收集之前，一定要把萃取器放在它们附近！', '使用灵质提纯器在希利苏斯收集12份烧焦的灵质，在冬泉谷收集12份冰冻的灵质，以及在东瘟疫之地收集12份稳定的灵质。然后将这些东西与灵质提纯器一起交给加基森的穆克斯·玛纳斯卡波。', '太好了，这些一定很棒!$B$B汲取这些物质里超自然的能量，我们就能与那些灵魂尚未离开这世界的人接触了!', '你收集好魂能了吗，$r?', '', '去塔纳利斯找加基森的穆克斯·玛纳斯卡波。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8925, '便携的能量源', '接下来我们需要找到一种稳定且便于携带的能量，以便维持灵质的活性。我听说有个名叫熔岩领主博奥克的强大土元素，它的心脏是个富含能量的岩浆核，永远地在不停地散发着热能！$B$B据说它就居住在燃烧平原的大熔炉。把它的心脏取来，这样我们就可以获得足够的富含热能的液体来维持超维度幽灵显形器的运转了！', '转至燃烧平原，找到熔岩领主博奥克，把它的岩浆核心交给加基森的穆克斯·玛纳斯卡波。', '你成功了!这将有足够的能量启动超空间鬼魂显像机!', '你见到麦格玛了吗，$N?', '', '去塔纳利斯找加基森的穆克斯·玛纳斯卡波。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8926, '小小的补偿', '你做到了你所承诺的事，把穆克斯制造的装备给我带了回来，那么我也按承诺给予你一件不错的奖励。把你原先使用的腰带和手套拿来吧，我会帮你升级它们。我敢保证，新的装备会比原来的好得多。', '将一条野性之心腰带和一副野性之心手套交给铁炉堡的德莉亚娜。', '你已达成交易，我也会保留我的。$B$B记住，我会保留最好的部份，就等你完成任务了。', '你准备好要交易了吗?', '', '去铁炉堡找王座厅的德莉亚娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8927, '小小的补偿', '你已经证明了自己是个非常守信誉的$r，$N。我坚信你能够帮我走出当前的困境，当然我也会根据你的表现给予你一些奖励。$B$B现在我可以帮你更换腰带和手套，如果事情进展顺利，我会继续帮你升级其它的部件。', '将一条野性之心腰带和一副野性之心手套交给奥格瑞玛的莫克瓦尔。', '我们的协议仍在。记住，这还只是个前菜而已。帮我从受诅咒的命运解除开来，我会奖励你超强大的物品。', '你准备好要交换了吗?', '', '去找奥格瑞玛的莫克瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8928, '小巧的商人', '那个核心可以提供足够的岩浆来驱动我们的装置，现在我们只需要制造一根耐性足够，不会被熔掉的导流棒来引导能量就可以了！$B$B我曾在冬泉谷见过一个贩卖各类奇特货物的小鬼。他似乎有一根由某种元素制成的棒子，应该就是最完美的了。现在我真想抽自己的耳光，为什么当初没有买下它。$B$B他就住在暗语峡谷入口附近的一处洞穴里。看看你能不能找到他吧！$B$B记住，超过40金币就别要了，这是他过去给我开的价！', '到冬泉谷南部的暗语峡谷入口附近去，在那里的一处洞穴内的某个小鬼那里购买一根恶魔元素之杖，并把它交给加基森的穆克斯·玛纳斯卡波。', '你办到了!这支棍棒非常完美。现在把所有东西放在一起……', '你找到暗语峡谷里的小鬼了吗?', '', '去找塔纳利斯的穆克斯·玛纳斯卡波。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8931, '小小的补偿', '你做到了你所承诺的事，把穆克斯制造的装备给我带了回来，那么我也按承诺给予你一件不错的奖励。把你原先使用的腰带和手套拿来吧，我会帮你升级它们。我敢保证，新的装备会比原来的好得多。', '将一条野兽追猎者腰带和一副野兽追猎者手套交给铁炉堡的德莉亚娜。', '你已达成交易，我也会保留我的。$B$B记住，我会保留最好的部份，就等你完成任务了。', '你准备好要交易了吗?', '', '去铁炉堡找王座厅的德莉亚娜。', '', '', '', '');
