INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9003, '最后的奖赏', '这真是个令人惊异的故事，$N！我实在是太感谢你了，其它一些与此有关的人也会对你表示真心诚意的感激。或许今天晚上我就能睡个安稳觉了。$B$B这儿还有些你绝对会很喜欢的东西，送你算作奖励吧。', '将你的虔诚头冠与虔诚长袍交给德莉亚娜。', '我会想念你的，$N。我欠你很大一份人情;我想我永远也无法报答你。$B$B希望你喜欢你的新头饰和胸甲，也希望它能保护你很长一段时间。', '依照我们的约定，你准备好交出你的虔诚装备来换取全新的善洁王冠和长袍了吗?', '', '去铁炉堡找王座厅的德莉亚娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9004, '最后的奖赏', '这真是个令人惊异的故事，$N！我实在是太感谢你了，其它一些与此有关的人也会对你表示真心诚意的感激。或许今天晚上我就能睡个安稳觉了。$B$B这儿还有些你绝对会很喜欢的东西，送你算作奖励吧。', '将你的迅影罩帽与迅影外套交给德莉亚娜。', '我会想念你的，$N。我欠你很大一份人情;我想我永远也无法报答你。$B$B希望你喜欢你的新头饰和胸甲，也希望它能保护你很长一段时间。', '依照我们的约定，你准备好交出你的迅影装备来换取全新的暗影军帽和外套了吗?', '', '去铁炉堡找王座厅的德莉亚娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9005, '最后的奖赏', '这真是个令人惊异的故事，$N！我实在是太感谢你了，其它一些与此有关的人也会对你表示真心诚意的感激。或许今天晚上我就能睡个安稳觉了。$B$B这儿还有些你绝对会很喜欢的东西，送你算作奖励吧。', '将你的鬼雾面具与鬼雾长袍交给德莉亚娜。', '我会想念你的，$N。我欠你很大一份人情;我想我永远也无法报答你。$B$B希望你喜欢你的新头饰和胸甲，也希望它能保护你很长一段时间。', '依照我们的约定，你准备好交出你的鬼雾装备来换取全新的亡雾面具和长袍了吗?', '', '去铁炉堡找王座厅的德莉亚娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9006, '最后的奖赏', '这真是个令人惊异的故事，$N！我实在是太感谢你了，其它一些与此有关的人也会对你表示真心诚意的感激。或许今天晚上我就能睡个安稳觉了。$B$B这儿还有些你绝对会很喜欢的东西，送你算作奖励吧。', '将你的勇气头盔与勇气胸甲交给德莉亚娜。', '我会想念你的，$N。我欠你很大一份人情;我想我永远也无法报答你。$B$B希望你喜欢你的新头饰和胸甲，也希望它能保护你很长一段时间。', '依照我们的约定，你准备好交出你的勇气装备来换取全新的英雄头盔和胸甲了吗?', '', '去铁炉堡找王座厅的德莉亚娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9007, '最后的奖赏', '确实是个令人惊异的故事，$N！我实在是太感谢你了，其它一些与此有关的人也会对你表示真心诚意的感激，这一点我向你保证。你的努力使我们终于认识到了自己过去所犯的错误。$B$B这儿还有些你绝对会很喜欢的东西，送你算作奖励吧。', '将你的野性之心兜帽与野性之心外衣交给莫克瓦尔。', '我真的会很想你，$N。我欠你一份人情，这是我永远也无法回报的。$B$B好好使用你的新头饰和胸甲。愿它能保护你很长一段时间，为你带来更多的荣耀!', '你准备好用你的野性之心装备和我交换全新的野兽之心风帽和外衣了吗?', '', '去找奥格瑞玛的莫克瓦尔。', '', '', '', '');
