INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9020, '告别安泰恩', '瓦塔拉克的灵魂就封印在这枚护符里。因为贪婪，我们愚蠢地将它分成了好几部分，丝毫不了解这会为我们带来怎样残酷的诅咒。$B$B唯一解除瓦塔拉克的法术的办法，就是将这枚勋章重新组合在一起。回到莫克瓦尔那里去，告诉他说，伯德雷已经是他找齐剩馀部分的最后希望了。顺便跟他提一下你应得的报酬。$B$B我只希望能从此安息。祝你好运……你会非常需要运气的！', '带上一双迅影长靴、一条迅影短裤和一副迅影肩甲，回去向奥格瑞玛的莫克瓦尔复命。', '就因为这个勋章，这个诅咒才会降临到我们身上。瓦萨拉克领主显然知道如何掌握仇恨。$B$B我们会尽力找到剩下的碎块 - 希望是在我面临最终的死期之前。不过在那之前，让我们先来看看你的奖励。', '你回来了，我从你的眼睛里看出来你有很多话想跟我讲，$N。让我们先处理好你的奖励。', '', '去找奥格瑞玛的莫克瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9021, '告别安泰恩', '瓦塔拉克的灵魂就封印在这枚护符里。因为贪婪，我们愚蠢地将它分成了好几部分，丝毫不了解这会为我们带来怎样残酷的诅咒。$B$B唯一解除瓦塔拉克的法术的办法，就是将这枚勋章重新组合在一起。回到莫克瓦尔那里去，告诉他说，伯德雷已经是他找齐剩馀部分的最后希望了。顺便跟他提一下你应得的报酬。$B$B我只希望能从此安息。祝你好运……你会非常需要运气的！', '带上一双鬼雾便鞋、一条鬼雾护腿和一副鬼雾衬肩，回去向奥格瑞玛的莫克瓦尔复命。', '就因为这个勋章，这个诅咒才会降临到我们身上。瓦萨拉克领主显然知道如何掌握仇恨。$B$B我们会尽力找到剩下的碎块 - 希望是在我面临最终的死期之前。不过在那之前，让我们先来看看你的奖励。', '你回来了，我从你的眼睛里看出来你有很多话想跟我讲，$N。让我们先处理好你的奖励。', '', '去找奥格瑞玛的莫克瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9022, '告别安泰恩', '瓦塔拉克的灵魂就封印在这枚护符里。因为贪婪，我们愚蠢地将它分成了好几部分，丝毫不了解这会为我们带来怎样残酷的诅咒。$B$B唯一解除瓦塔拉克的法术的办法，就是将这枚勋章重新组合在一起。回到莫克瓦尔那里去，告诉他说，伯德雷已经是他找齐剩馀部分的最后希望了。顺便跟他提一下你应得的报酬。$B$B我只希望能从此安息。祝你好运……你会非常需要运气的！', '带上一双勇气战靴、一条勇气腿铠和一副勇气肩甲，回去向奥格瑞玛的莫克瓦尔复命。', '就因为这个勋章，这个诅咒才会降临到我们身上。瓦萨拉克领主显然知道如何掌握仇恨。$B$B我们会尽力找到剩下的碎块 - 希望是在我面临最终的死期之前。不过在那之前，让我们先来看看你的奖励。', '你回来了，我从你的眼睛里看出来你有很多话想跟我讲，$N。让我们先处理好你的奖励。', '', '去找奥格瑞玛的莫克瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9023, '完美的毒药', '我和我的兄弟在拉文霍德庄园外进行毒药研究。$B$B拉文霍德公爵命令我们研制一种极效混合毒药，祖尔格拉布和安其拉废墟出产这种毒药的原料，也就是毒囊。$B$B有两只剧毒的野兽居住在那些可怕的废墟中，它们很可能有我们需要的毒囊。$C，去取回库林纳克斯和温诺希斯的毒囊，我们会永远记得你的恩情的。', '塞纳里奥要塞的德尔克·雷木让你把温诺希斯的毒囊和库林纳克斯的毒囊交给他。', '拉文霍德感谢你，英雄!带着你的奖励走吧!', '这不是个简单的任务，$N。你需要带些朋友去。', '', '去希利苏斯找塞纳里奥要塞的德尔克·雷木。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9024, '阿瑞斯坦的预感', '我找到了！你闻到过风中的新香气没有？新的香水现在有那么流行么？我们的卫兵不该这么简单就这样抛弃他们的职责！$b$b嗯，一定是因为他们的理智完全被这些该死的炼金术产品所盖过去了。$b$b要想搞清楚问题，只有一个办法：弄一些香水的样本，把它们交给摩根·匹斯特，并把我的推断告诉他。别担心，你回来的时候我会把买香水的钱付给你的。', '将1瓶古龙水和1瓶香水交给暴风城贸易区的摩根·匹斯特。', '我了解艾里斯坦的疑虑，但我真的觉得他反应过度了。让年轻男女做他们想做的事吧。我想艾里斯坦已经忘了年轻和恋爱的感觉。$B$B不过还是不要告诉他比较好。我们就迁就他吧。', '有什么能帮你的吗?', '', '去找暴风城的摩根·匹斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9033, '战争的回响', '上一次战争距今已有5年了……$B$B数万名士兵战死沙场，他们的牺牲换来了什么？危机远远没有消失。$B$B巫妖王再次蠢蠢欲动……他的走狗克尔苏加德正在集聚军队，准备对我们的家园发动新一轮的袭击。$B$B我们绝不会让他得逞！拿出你的奉献精神吧。勇敢地投入战斗，以此证明你的无畏！银色黎明和血色十字军组成的联军将是你坚强的后盾和战友。$B$B转至纳克萨玛斯的宫殿，打败天灾军团……', '东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者要你杀死5个畸形妖、5只岩肤石像鬼、8个死亡骑士队长和3只毒性捕猎者。', '做的好!你会因为替圣光之愿的男男女女牺牲奉献而获得奖励。', '职责，荣誉，奉献……这些字眼对你而言有什么意义?', '', '去找东瘟疫之地的指挥官埃里戈尔·黎明使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9034, '无畏胸甲', '在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。', '如果你将1件被玷污的胸甲、25块板甲碎片、4块奥金锭和2块连结水晶交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一件无畏胸甲。', '让他们再次尝到恐惧的滋味，$C。让他们感受不到仁慈。', '纳克萨玛斯握有古老的邪恶，$N。', '', '去找东瘟疫之地的科尔法克斯，圣光之勇士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9036, '无畏腿铠', '在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。', '如果你将1副被玷污的腿铠、20块板甲碎片、4块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一副无畏腿铠。', '把他们粉碎在你的脚下。', '记住那些在你面前倒下的人，$N。', '', '去找东瘟疫之地的科尔法克斯，圣光之勇士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9037, '无畏头盔', '在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。', '如果你将1顶被玷污的头盔、15块板甲碎片、5块奥金锭和1块连结水晶交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一顶无畏头盔。', '记住，如果你的脑袋还在头颅里，你就不算真的死亡。时时记得这点……', '头部是全身最敏感的位置。', '', '去找东瘟疫之地的科尔法克斯，圣光之勇士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9038, '无畏肩铠', '在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。', '如果你将1副被玷污的肩铠、12块板甲碎片、2块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一副无畏肩铠。', '我一直认为肩铠是最显眼的一件护甲。我想你同意吧。', '秘诀就在于团结一致。', '', '去找东瘟疫之地的科尔法克斯，圣光之勇士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9039, '无畏马靴', '在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。', '如果你将1双被玷污的马靴、12块板甲碎片、2块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一双无畏马靴。', '在最后一场战役中，我目睹莫格莱尼用这双靴子踩碎那些半死不活的人的头颅。', '永远不要低估一双好鞋的价值。尤其是柯菲斯做的鞋子!', '', '去找东瘟疫之地的科尔法克斯，圣光之勇士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9040, '无畏护手', '在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。', '如果你将1副被玷污的护手、8块板甲碎片、1块奥金锭和5个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一副无畏护手。', '希望你紧紧掐住克尔苏加德的脖子。$B$B<柯菲斯用手做了一个猛拧的手势。>', '这些护手就是要配上精良的武器。', '', '去找东瘟疫之地的科尔法克斯，圣光之勇士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9041, '无畏腰带', '在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。', '如果你将1条被玷污的护腰、8块板甲碎片、1块奥金锭和5个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一条无畏护腰。', '把它当做绞索来对付你的敌人。还有，戴着它到你们当地的舞厅去。你一定会成为镇上的大红人!', '腰带不仅是个时髦的象征也是强大的保护装备。', '', '去找东瘟疫之地的科尔法克斯，圣光之勇士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9042, '无畏护腕', '在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。', '如果你将1副被玷污的护腕、6块板甲碎片、1块奥金锭和1块连结水晶交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一副无畏护腕。', '记住，手腕是全身第五脆弱的部位!保护你的手腕，它们就绝对会保护你的手肘 - 或许啦。', '手腕是全身第二脆弱的部位……还是第四个?', '', '去找东瘟疫之地的科尔法克斯，圣光之勇士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9043, '救赎外套', '杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着删除护甲上的诅咒，重新为你打造一件精良的护甲。', '如果你将1件被玷污的外套，25块板甲碎片，4块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一件救赎外套。', '好好穿它吧，$C。', '我的制作都是高水准的，$N。', '', '去找东瘟疫之地的指挥官埃里戈尔·黎明使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9044, '救赎腿甲', '杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着删除护甲上的诅咒，重新为你打造一件精良的护甲。', '如果你将1副被玷污的腿甲，20块板甲碎片，4块奥金锭和2块连结水晶交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一副救赎腿甲。', '近战和魔法间的平衡与这些腿甲息息相关。', '你不会再找到比这更适合神圣战士的腿甲了。', '', '去找东瘟疫之地的指挥官埃里戈尔·黎明使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9045, '救赎头饰', '杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着删除护甲上的诅咒，重新为你打造一件精良的护甲。', '如果你将1件被玷污的头饰，15块板甲碎片，5块奥金锭和2个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一件救赎头饰。', '<艾利格指着他的头。>$B$B戴好罩帽，$C。', '<艾利格抬头看着你又继续说。>', '', '去找东瘟疫之地的指挥官埃里戈尔·黎明使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9046, '救赎肩铠', '杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着删除护甲上的诅咒，重新为你打造一件精良的护甲。', '如果你将1副被玷污的肩铠，12块板甲碎片，2块奥金锭和2块连结水晶交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一副救赎肩铠。', '任何圣骑士都会告诉你，他们冲击的力量来自于肩膀。越大越好……', '你没看到我们在忙吗，$N?', '', '去找东瘟疫之地的指挥官埃里戈尔·黎明使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9047, '救赎长靴', '杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着删除护甲上的诅咒，重新为你打造一件精良的护甲。', '如果你将1双被玷污的长靴，12块板甲碎片，2块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一双救赎长靴。', '这双靴子会保护你的双脚不受矮小的天灾军团攻击。', '如果你要我帮你制作护甲就一定要将我说的东西带来。', '', '去找东瘟疫之地的指挥官埃里戈尔·黎明使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9048, '救赎护手', '杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着删除护甲上的诅咒，重新为你打造一件精良的护甲。', '如果你将1副被玷污的护手，8块板甲碎片，1块奥金锭和5个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一副救赎护手。', '让圣光引导这些手甲击倒你的敌人!', '如果你要我帮你制作护甲就一定要将我说的东西带来。', '', '去找东瘟疫之地的指挥官埃里戈尔·黎明使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9049, '救赎束带', '杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着删除护甲上的诅咒，重新为你打造一件精良的护甲。', '如果你将1条被玷污的束带，8块板甲碎片，1块奥金锭和3块连结水晶交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一条救赎束带。', '这条束腰有两种功能:1)它会保护你并引导你对抗天灾军团，2)让你看起来轻20磅。', '如果你要我帮你制作护甲就一定要将我说的东西带来。', '', '去找东瘟疫之地的指挥官埃里戈尔·黎明使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9050, '救赎护腕', '杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着删除护甲上的诅咒，重新为你打造一件精良的护甲。', '如果你将1副被玷污的护腕，6块板甲碎片，1块奥金锭和2个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一副救赎护腕。', '这些东西制作的非常划算，但是请小心，如果你太常让它们溅水的话是会生锈的。', '如果你要我帮你制作护甲就一定要将我说的东西带来。', '', '去找东瘟疫之地的指挥官埃里戈尔·黎明使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9051, '毒性测试', '这些你帮我制造的毒素有着特殊的用途。环形山里的魔暴龙使得那里的狩猎和生存环境对我来说都变得十分恶劣。即使我足够强壮，杀死一只魔暴龙也只会让另一只游荡入那块带领地而已。$b$b带上这根毒针并将其刺入一只活着的魔暴龙体内。毒素会使它很快就安静下来，不过……我不知道很快有多快……', '将魔暴龙之刺扎入一只魔暴龙的体内。', '感谢你，$N。你很勇敢也很有智慧。$B$B跟我说说看那个恶龙的毒性反应如何?', '你驯服那头野兽了吗?', '把毒刺扎入魔暴龙体内', '去安戈洛环形山找沼泽地的托尔瓦·寻路者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9052, '血瓣毒药', '我要你帮我制作一批毒素，用来制服某些生活在环形山里的巨兽。它并非是致命性的，不过只有一个足够细心和聪明的$c才能收集到所有的材料。$b$b在环形山里任意血瓣花苗身上，你都可以找到一些血帽蘑菇，而格里什钉刺则可以从环形山南部巨痕谷中的那些巨蜂身上找到。', '收集一些血帽和格里什钉刺，然后向托尔瓦·寻路者复命。', '终于拿到了材料!$B$B有了安戈洛的泥土，调制毒素就变的轻而易举……', '成功了吗?', '', '去安戈洛环形山找沼泽地的托尔瓦·寻路者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9053, '更好的材料', '这正是我所担心的，看来毒素的力量还是太弱了，无法对这样强大的生物产生影响。$b$b我们必须造出一种更强力的毒素，你需要转至阿塔哈卡神庙的底部，揭开那个祭坛的秘密，并从那里的守卫身上取一些腐烂的藤蔓来。神庙很危险，我建议你带些朋友一起去。$b$b完成之后回到我这里来吧。', '从沉没的神庙底部的守卫身上得到一些腐烂藤蔓，把它们交给托尔瓦·寻路者。', '这毒素终于完成了。我不敢\r\n再像之前一样过份，要你对这生物下毒手。$B$B你赢得了我的感谢与尊敬，祝福你一路顺风，$N。', '你拿回藤蔓了吗?', '', '去安戈洛环形山找沼泽地的托尔瓦·寻路者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9054, '地穴追猎者外套', '我发现地穴恶魔的甲壳大有用处。我可以利用这种甲壳以及丢失在纳克萨玛斯宫殿中的被玷污的护甲，打造出一套轻便时尚的、具有毁灭性力量的套装。$B$B帮我寻找必需的材料，我就能制作出这套前所未有的装备！', '如果你将1件被玷污的外套、25块锁甲碎片、4块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的猎手雷奥普德，他会为你制作一件地穴追猎者外套。', '他们会畏惧你，$N。', '你有我要的物品了吗，$C?', '', '去东瘟疫之地找圣光之愿礼拜堂的猎手雷奥普德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9055, '地穴追猎者腿甲', '我发现地穴恶魔的甲壳大有用处。我可以利用这种甲壳以及丢失在纳克萨玛斯宫殿中的被玷污的护甲，打造出一套轻便时尚的、具有毁灭性力量的套装。$B$B帮我寻找必需的材料，我就能制作出这套前所未有的装备！', '如果你将1条被玷污的腿甲、20块锁甲碎片、3块奥金锭和5个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的猎手雷奥普德，他会为你制作一条地穴追猎者腿甲。', '当你穿上这件护甲，你就会发现你的人开始改变。你会有不可思议的杀人能力。或许，甚至有一点嗜血。$B$B先说好我不会对你卷入的任何混乱负责……', '你有我要的物品了吗，$C?', '', '去东瘟疫之地找圣光之愿礼拜堂的猎手雷奥普德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9056, '地穴追猎者头饰', '我发现地穴恶魔的甲壳大有用处。我可以利用这种甲壳以及丢失在纳克萨玛斯宫殿中的被玷污的护甲，打造出一套轻便时尚的、具有毁灭性力量的套装。$B$B帮我寻找必需的材料，我就能制作出这套前所未有的装备！', '如果你将1件被玷污的头饰、15块锁甲碎片、4块奥金锭和2块连结水晶交给东瘟疫之地圣光之愿礼拜堂的猎手雷奥普德，他会为你制作一件地穴追猎者头饰。', '你变成了一个可怕的生物，$N。', '你有我要的物品了吗，$C?', '', '去东瘟疫之地找圣光之愿礼拜堂的猎手雷奥普德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9057, '地穴追猎者肩饰', '我发现地穴恶魔的甲壳大有用处。我可以利用这种甲壳以及丢失在纳克萨玛斯宫殿中的被玷污的护甲，打造出一套轻便时尚的、具有毁灭性力量的套装。$B$B帮我寻找必需的材料，我就能制作出这套前所未有的装备！', '如果你将1副被玷污的肩饰、12块锁甲碎片、2块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的猎手雷奥普德，他会为你制作一副地穴追猎者肩饰。', '我非常小心地制作这些护肩，让它们尽可能又大又明显。我保证;你一定会爱上它们……', '你有我要的物品了吗，$C?', '', '去东瘟疫之地找圣光之愿礼拜堂的猎手雷奥普德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9058, '地穴追猎者长靴', '我发现地穴恶魔的甲壳大有用处。我可以利用这种甲壳以及丢失在纳克萨玛斯宫殿中的被玷污的护甲，打造出一套轻便时尚的、具有毁灭性力量的套装。$B$B帮我寻找必需的材料，我就能制作出这套前所未有的装备！', '如果你将1双被玷污的长靴、12块锁甲碎片、1块奥金锭和3块连结水晶交给东瘟疫之地圣光之愿礼拜堂的猎手雷奥普德，他会为你制作一双地穴追猎者长靴。', '靴子准备好了，$N!好好地穿。', '你有我要的物品了吗，$C?', '', '去东瘟疫之地找圣光之愿礼拜堂的猎手雷奥普德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9059, '地穴追猎者护手', '我发现地穴恶魔的甲壳大有用处。我可以利用这种甲壳以及丢失在纳克萨玛斯宫殿中的被玷污的护甲，打造出一套轻便时尚的、具有毁灭性力量的套装。$B$B帮我寻找必需的材料，我就能制作出这套前所未有的装备！', '如果你将1副被玷污的手甲、8块锁甲碎片、1块奥金锭和5个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的猎手雷奥普德，他会为你制作一副地穴追猎者护手。', '让地穴恶魔带领你的手吧，$N。', '你有我要的物品了吗，$C?', '', '去东瘟疫之地找圣光之愿礼拜堂的猎手雷奥普德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9060, '地穴追猎者束带', '我发现地穴恶魔的甲壳大有用处。我可以利用这种甲壳以及丢失在纳克萨玛斯宫殿中的被玷污的护甲，打造出一套轻便时尚的、具有毁灭性力量的套装。$B$B帮我寻找必需的材料，我就能制作出这套前所未有的装备！', '如果你将1条被玷污的束带、8块锁甲碎片、1块奥金锭和3块连结水晶交给东瘟疫之地圣光之愿礼拜堂的猎手雷奥普德，他会为你制作一条地穴追猎者束带。', '一个忠诚的束腰!为你准备好了，$N。', '你有我要的物品了吗，$C?', '', '去东瘟疫之地找圣光之愿礼拜堂的猎手雷奥普德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9061, '地穴追猎者腕甲', '我发现地穴恶魔的甲壳大有用处。我可以利用这种甲壳以及丢失在纳克萨玛斯宫殿中的被玷污的护甲，打造出一套轻便时尚的、具有毁灭性力量的套装。$B$B帮我寻找必需的材料，我就能制作出这套前所未有的装备！', '如果你将1副被玷污的腕甲、6块锁甲碎片、1块奥金锭和2个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的猎手雷奥普德，他会为你制作一副地穴追猎者腕甲。', '腕甲准备好了。好好使用吧!', '你有我要的物品了吗，$C?', '', '去东瘟疫之地找圣光之愿礼拜堂的猎手雷奥普德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9062, '浸水的书页', '如果你拿起武器反抗的话，那些肮脏的家伙必然会逃之夭夭。只是眼下还不是追赶他们的时候。我得找到指导者的元素魔典。我看见某个懦弱的家伙将它扔进了河里，确切位置我就不得而知了。我想或许你能睁大双眼，帮我找找。如果你能找到的话，我会给你一些钱币作为报酬的。', '永歌森林的学徒梅雷多尔让你搜寻附近桥梁下的水域，帮他找到安瑟隆的元素魔典。', '这本书已经完全浸湿了。导师安西欧会不高兴的。$B$B来，拿着这些钱。我有个主意。', '运气不好?嗯，继续找。那本书极为重要，$C。', '', '去找死亡之痕的学徒梅雷多尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9064, '学徒的欺瞒', '安瑟隆要是发现他的书被毁掉了，必定会勃然大怒。我有一个小小的建议——别着急呀，我当然会酬谢你的。$B$B把这本书交给安瑟隆，但是别告诉他发生了什么事。如果他问起的话，就说你不小心把书掉到水池里啦。他可管不着你，也就不会把你怎么样的。你会帮助我们的，对吧？我会给你一大笔酬金的！', '将安瑟隆的元素魔典交给永歌森林的萦语水池旁的指导者安瑟隆。', '你说那两个无能的蠢蛋收买你来骗我?你来找我做的非常好，$N。', '有什么事需要打断我的演讲，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9066, '导师的训诫', '希望你能学到一点处事之道，$N。不要相信满嘴谎言的家伙。$B$B现在，我想让你回去找那两个愚蠢的学生，使用这根魔杖召回他们的学徒徽章。这根杖子不仅能取下两人身上的徽章，还会给予他们适当的惩罚。$B$B做完这事儿就来找我吧。我会酬谢你的。', '对指导者安瑟隆的两名学生：学徒拉尔雷和学徒梅雷多尔使用他交给你的魔杖。然后将安瑟隆的训诫棒还给永歌森林萦语水池旁的安瑟隆。', '做的好，$N。别担心，他们不会永远变成那个样子。不过，他们的学徒资格在他们自己把它挣回来之前是不会再出现的。', '你做了我要你做的事吗，$N?', '', '去永歌森林找萦语水池的指导者安瑟隆。', '训诫学徒梅雷多尔', '训诫学徒拉尔雷', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9067, '无尽的宴会', '我最喜欢举办舞会和酒会了……这都是为伟大而辉煌的奎尔萨拉斯庆贺与祝福！$B$B但……但是，我手头上还有别的事，所以我希望你能帮我带过来一些货物。$B$B请你帮我从银月城旅店的调酒师桑塔基德那里买一瓶日光陈酿，从远行者居所的萨蕾妮·晨光那里买一些魔泉美味回来，然后再从晴风村的哈里斯·晨行者那里买点烟花。$B$B快点，别让我等急了！', '购买一瓶日光陈酿、一些魔泉美味和一捆烟花，然后向永歌森林萨瑟利尔庄园的萨瑟利尔男爵复命。', '你真是个精力旺盛的，年轻$g男人:女人;对吗?$B$B这些看起来非常足够。你为我收集这些东西绝对值得奖励，还有一些别的东西我想。$B$B喔，我差点忘了，这是一张派对的邀请函。还有，$C，下次你来的时候记得要穿的更……体面一点。', '我不是派你去为派对收集更多食物吗?是你吗?喔，我不可能永远记住每个人的长相，对吧?我见过太多……有趣的人。$B$B你想要什么?', '', '去永歌森林找萨瑟利尔庄园的萨瑟利尔男爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9068, '碎地者外套', '你能将那些战死沙场的英雄的护甲给我带回来吗？$B$B那些护甲被邪恶的敌人夺去，早已被玷污了，但是护甲碎片能彻底清洁它们，让我们重新穿着它们杀入战场。$B$B将阵亡英雄的遗物以及那些净化所需的材料交给我，我会为你打造碎地者的套装。$B$B到纳克萨玛斯去寻找吧！', '如果你将1件被玷污的外套、25块锁甲碎片、4块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的雷布拉特·碎地者，他将为你制作一件碎地者外套。', '碎地者是最强大且引人敬畏的护甲。我的祖先会为你的成就而微笑的，$N。', '<林布拉特对你嗤之以鼻。>', '', '去东瘟疫之地找圣光之愿礼拜堂的雷布拉特·碎地者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9069, '碎地者腿甲', '你能将那些战死沙场的英雄的护甲给我带回来吗？$B$B那些护甲被邪恶的敌人夺去，早已被玷污了，但是护甲碎片能彻底清洁它们，让我们重新穿着它们杀入战场。$B$B将阵亡英雄的遗物以及那些净化所需的材料交给我，我会为你打造碎地者的套装。$B$B到纳克萨玛斯去寻找吧！', '如果你将1副被玷污的腿甲、20块锁甲碎片、3块奥金锭和5个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的雷布拉特·碎地者，他将为你制作一副碎地者腿甲。', '我希望你不会和之前来这里的人有一样的命运，$N。', '不论如何，我们一定要拯救这块土地。', '', '去东瘟疫之地找 圣光之愿礼拜堂的雷布拉特·碎地者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9070, '碎地者头饰', '你能将那些战死沙场的英雄的护甲给我带回来吗？$B$B那些护甲被邪恶的敌人夺去，早已被玷污了，但是护甲碎片能彻底清洁它们，让我们重新穿着它们杀入战场。$B$B将阵亡英雄的遗物以及那些净化所需的材料交给我，我会为你打造碎地者的套装。$B$B到纳克萨玛斯去寻找吧！', '如果你将1件被玷污的头饰、15块锁甲碎片、4块奥金锭和2块连结水晶交给东瘟疫之地圣光之愿礼拜堂的雷布拉特·碎地者，他将为你制作一件碎地者头饰。', '让我为你献上碎地者装备中的一件:碎地者盔帽……', '你把我要的东西带来了吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的雷布拉特·碎地者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9071, '碎地者肩饰', '你能将那些战死沙场的英雄的护甲给我带回来吗？$B$B那些护甲被邪恶的敌人夺去，早已被玷污了，但是护甲碎片能彻底清洁它们，让我们重新穿着它们杀入战场。$B$B将阵亡英雄的遗物以及那些净化所需的材料交给我，我会为你打造碎地者的套装。$B$B到纳克萨玛斯去寻找吧！', '如果你将1副被玷污的肩饰、12块锁甲碎片、2块奥金锭和2张月布交给东瘟疫之地圣光之愿礼拜堂的雷布拉特·碎地者，他将为你制作一副碎地者肩饰。', '肩膀让你平衡。', '你把我要的东西带来了吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的雷布拉特·碎地者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9072, '碎地者长靴', '你能将那些战死沙场的英雄的护甲给我带回来吗？$B$B那些护甲被邪恶的敌人夺去，早已被玷污了，但是护甲碎片能彻底清洁它们，让我们重新穿着它们杀入战场。$B$B将阵亡英雄的遗物以及那些净化所需的材料交给我，我会为你打造碎地者的套装。$B$B到纳克萨玛斯去寻找吧！', '如果你将1双被玷污的长靴、12块锁甲碎片、1块奥金锭和3块连结水晶交给东瘟疫之地圣光之愿礼拜堂的雷布拉特·碎地者，他将为你制作一双碎地者长靴。', '这些靴子注入了我的祖先的力量!睿智地上路吧……', '你把我要的东西带来了吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的雷布拉特·碎地者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9073, '碎地者护手', '你能将那些战死沙场的英雄的护甲给我带回来吗？$B$B那些护甲被邪恶的敌人夺去，早已被玷污了，但是护甲碎片能彻底清洁它们，让我们重新穿着它们杀入战场。$B$B将阵亡英雄的遗物以及那些净化所需的材料交给我，我会为你打造碎地者的套装。$B$B到纳克萨玛斯去寻找吧！', '如果你将1双被玷污的护手、8块锁甲碎片、1块奥金锭和5个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的雷布拉特·碎地者，他将为你制作一双碎地者护手。', '这些手甲引导元素的能量!', '你把我要的东西带来了吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的雷布拉特·碎地者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9074, '碎地者束带', '你能将那些战死沙场的英雄的护甲给我带回来吗？$B$B那些护甲被邪恶的敌人夺去，早已被玷污了，但是护甲碎片能彻底清洁它们，让我们重新穿着它们杀入战场。$B$B将阵亡英雄的遗物以及那些净化所需的材料交给我，我会为你打造碎地者的套装。$B$B到纳克萨玛斯去寻找吧！', '如果你将1条被玷污的束带、8块锁甲碎片、1块奥金锭和3块连结水晶交给东瘟疫之地圣光之愿礼拜堂的雷布拉特·碎地者，他将为你制作一条碎地者束带。', '束腰准备好了，$N。$B$B<林布拉特鞠躬。>', '你把我要的东西带来了吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的雷布拉特·碎地者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9075, '碎地者护腕', '你能将那些战死沙场的英雄的护甲给我带回来吗？$B$B那些护甲被邪恶的敌人夺去，早已被玷污了，但是护甲碎片能彻底清洁它们，让我们重新穿着它们杀入战场。$B$B将阵亡英雄的遗物以及那些净化所需的材料交给我，我会为你打造碎地者的套装。$B$B到纳克萨玛斯去寻找吧！', '如果你将1副被玷污的护腕、6块锁甲碎片、1块奥金锭和2个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的雷布拉特·碎地者，他将为你制作一副碎地者护腕。', '腕甲准备好了，$N。$B$B<林布拉特鞠躬。>', '你把我要的东西带来了吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的雷布拉特·碎地者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9076, '失心者的领袖', '那些失心者囫囵吞枣似的研究着低劣的魔法，尚未察觉我们已经取回了大部分武器。但是，我们不能指望他们一直这么愚钝。现在是时候策划一场决定性的突袭了，目标就锁定他们的首领奥尔达隆吧。他就在船坞旁边那幢建筑物的顶层。把他的徽记交给我，我会酬谢你的。', '将奥尔达隆的徽记交给永歌森林阳帆港附近的维雷迪斯·雪晨。', '你击败他了!我的手下果然帮你削弱了他的力量。$B$B我开玩笑的，$N。你做的很好。继续保持你会千古流芳的。', '嗯，你拿到他的头了吗?我没时间浪费，$N。', '', '去找永歌森林的维雷迪斯·雪晨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9077, '骨镰胸甲', '如果你想要骨镰护甲，就得帮我找来一些必需的材料。$B$B进入纳克萨玛斯的宫殿——就是那座漂浮在空中的巨大城市，去收集被玷污的护甲和皮甲碎片。集齐所有材料，我就能为你打造骨镰护甲。噢，对了，你还得付点金币给我……制作护甲所需的骨头由我来提供。', '如果你将1件被玷污的胸甲、25块皮甲碎片、2块奥金锭和6个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的杀手洛汗，他会为你制作一件骨镰胸甲。', '拿去吧，$r。如同先前允诺的，骨镰胸甲。我希望服装专家不在附近。你可能会因为穿着这个被丢进监狱!', '<罗汉让你看他的移动。>$B$B这是什么，$N?为了之后的竞争我必须正中这个记号。', '', '去东瘟疫之地找圣光之愿礼拜堂的杀手洛汗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9078, '骨镰腿铠', '如果你想要骨镰护甲，就得帮我找来一些必需的材料。$B$B进入纳克萨玛斯的宫殿——就是那座漂浮在空中的巨大城市，去收集被玷污的护甲和皮甲碎片。集齐所有材料，我就能为你打造骨镰护甲。噢，对了，你还得付点金币给我……制作护甲所需的骨头由我来提供。', '如果你将1副被玷污的腿铠、20块皮甲碎片、1块奥金锭、8个熟化毛皮和100金币交给东瘟疫之地圣光之愿礼拜堂的杀手洛汗，他会为你制作一副骨镰腿铠。', '戴着这东西要小心一点。你可能会伤了自己。', '<罗汉笑着。>$B$B我了解了这整个事情的讽刺之处。', '', '去东瘟疫之地找圣光之愿礼拜堂的杀手洛汗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9079, '骨镰头盔', '如果你想要骨镰护甲，就得帮我找来一些必需的材料。$B$B进入纳克萨玛斯的宫殿——就是那座漂浮在空中的巨大城市，去收集被玷污的护甲和皮甲碎片。集齐所有材料，我就能为你打造骨镰护甲。噢，对了，你还得付点金币给我……制作护甲所需的骨头由我来提供。', '如果你将1顶被玷污的头盔、15块皮甲碎片、8个熟化毛皮、1块连结水晶和75金币交给东瘟疫之地圣光之愿礼拜堂的杀手洛汗，他会为你制作一顶骨镰头盔。', '我的骨镰盔帽和胡力欧的不同之处在于格调，$N。格调……', '你要给我钱。$B$B<罗汉笑着。>$B$B那还是能打动我。', '', '去东瘟疫之地找圣光之愿礼拜堂的杀手洛汗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9080, '骨镰肩铠', '如果你想要骨镰护甲，就得帮我找来一些必需的材料。$B$B进入纳克萨玛斯的宫殿——就是那座漂浮在空中的巨大城市，去收集被玷污的护甲和皮甲碎片。集齐所有材料，我就能为你打造骨镰护甲。噢，对了，你还得付点金币给我……制作护甲所需的骨头由我来提供。', '如果你将1副被玷污的肩铠、12块皮甲碎片、5个熟化毛皮、1块连结水晶和50金币交给东瘟疫之地圣光之愿礼拜堂的杀手洛汗，他会为你制作一副骨镰肩铠。', '<罗汉将眉毛上的汗珠擦掉。>$B$B这些护肩费了不少功夫!不要走出去像个呆子一样被人杀了，$N。', '<罗汉很怀疑地看着你。>$B$B你最近去过提尔之手?', '', '去东瘟疫之地找圣光之愿礼拜堂的杀手洛汗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9081, '骨镰马靴', '如果你想要骨镰护甲，就得帮我找来一些必需的材料。$B$B进入纳克萨玛斯的宫殿——就是那座漂浮在空中的巨大城市，去收集被玷污的护甲和皮甲碎片。集齐所有材料，我就能为你打造骨镰护甲。噢，对了，你还得付点金币给我……制作护甲所需的骨头由我来提供。', '如果你将1双被玷污的马靴、12块皮甲碎片、3个熟化毛皮、2块连结水晶和25金币交给东瘟疫之地圣光之愿礼拜堂的杀手洛汗，他会为你制作一双骨镰马靴。', '他们穿在你脚上很适合。对了，你最近没有再去提尔之手了吧?', '赶快把材料带给我不要再浪费我的时间了，$C。', '', '去东瘟疫之地找圣光之愿礼拜堂的杀手洛汗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9082, '骨镰护手', '如果你想要骨镰护甲，就得帮我找来一些必需的材料。$B$B进入纳克萨玛斯的宫殿——就是那座漂浮在空中的巨大城市，去收集被玷污的护甲和皮甲碎片。集齐所有材料，我就能为你打造骨镰护甲。噢，对了，你还得付点金币给我……制作护甲所需的骨头由我来提供。', '如果你将1双被玷污的护手、8块皮甲碎片、1块奥金锭和5个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的杀手洛汗，他会为你制作一双骨镰护手。', '这些护手必要时可能可以替换武器。骄傲的穿戴上它们吧!', '没有我需要的物品，你要我怎么做出什么东西来?', '', '去东瘟疫之地找圣光之愿礼拜堂的杀手洛汗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9083, '骨镰护腰', '如果你想要骨镰护甲，就得帮我找来一些必需的材料。$B$B进入纳克萨玛斯的宫殿——就是那座漂浮在空中的巨大城市，去收集被玷污的护甲和皮甲碎片。集齐所有材料，我就能为你打造骨镰护甲。噢，对了，你还得付点金币给我……制作护甲所需的骨头由我来提供。', '如果你将1条被玷污的护腰、8块皮甲碎片、5个熟化毛皮、1块连结水晶和15金币交给东瘟疫之地圣光之愿礼拜堂的杀手洛汗，他会为你制作一条骨镰护腰。', '腰带准备好了，$N。你有看过这样高品质的物品以如此低价出售吗?', '没有我需要的物品，你要我怎么做出什么东西来?', '', '去东瘟疫之地找圣光之愿礼拜堂的杀手洛汗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9084, '骨镰护腕', '如果你想要骨镰护甲，就得帮我找来一些必需的材料。$B$B进入纳克萨玛斯的宫殿——就是那座漂浮在空中的巨大城市，去收集被玷污的护甲和皮甲碎片。集齐所有材料，我就能为你打造骨镰护甲。噢，对了，你还得付点金币给我……制作护甲所需的骨头由我来提供。', '如果你将1副被玷污的护腕、6块皮甲碎片、1块奥金锭、2个熟化毛皮和10金币交给东瘟疫之地圣光之愿礼拜堂的杀手洛汗，他会为你制作一副骨镰护腕。', '护腕准备好了，$N。$B$B<罗汉鞠躬。>', '没有我需要的物品，你要我怎么做出什么东西来?', '', '去东瘟疫之地找圣光之愿礼拜堂的杀手洛汗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9085, '末日之影', '在你攻破天灾军团的召唤法阵后，就要面对守护法阵的侍僧了。$B$B说老实话，这些家伙不是人，而是暗影，巫妖王最恐怖的爪牙。使用死灵石可令它们显形，魔法和武器攻击都能取它们的性命。', '转至一处召唤法阵，杀死一名末日之影，然后向东瘟疫之地圣光之愿礼拜堂的指挥官托马斯·海勒拉复命。', '做得漂亮，$N。随着暗影被摧毁，我们对抗巫妖的胜利希望也得以保存。', '运气如何，$N?', '', '去东瘟疫之地找圣光之愿礼拜堂的指挥官托马斯·海勒拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9086, '梦游者外套', '许多英雄在那场战争中丧生，直到今天还有无数勇士前赴后继，与天灾军团进行殊死的搏斗。天灾士兵们从阵亡的英雄身上脱下护甲，带回纳克萨玛斯进行秘密研究。$B$B取回那些被玷污的护甲碎片和我需要的其它材料，我就能为你打造梦游者护甲。', '如果你将1件被玷污的外套、25块皮甲碎片、6个熟化毛皮和2块连结水晶交给东瘟疫之地圣光之愿礼拜堂的莱茵，他会为你制作一件梦游者外套。', '你的梦行者外套准备好了，$N。', '材料虽然昂贵，但你很快就不会放在心上了。', '', '去东瘟疫之地找圣光之愿礼拜堂的莱茵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9087, '梦游者腿甲', '许多英雄在那场战争中丧生，直到今天还有无数勇士前赴后继，与天灾军团进行殊死的搏斗。天灾士兵们从阵亡的英雄身上脱下护甲，带回纳克萨玛斯进行秘密研究。$B$B取回那些被玷污的护甲碎片和我需要的其它材料，我就能为你打造梦游者护甲。', '如果你将1件被玷污的腿甲、20块皮甲碎片、8个熟化毛皮和1块连结水晶交给东瘟疫之地圣光之愿礼拜堂的莱茵，他会为你制作一件梦游者腿甲。', '如我所允诺的，梦行者腿甲。$B$B<瑞恩将护甲交给你。>', '材料虽然昂贵，但你很快就不会放在心上了。', '', '去东瘟疫之地找圣光之愿礼拜堂的莱茵。', '', '', '', '');
