INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9111, '信仰长袍', '<蒙托尔神父在你面前做了一个奇怪的手势。>$B$B幸运的$G小伙子:姑娘;，你找到那些阵亡士兵的护甲了吗？这些可怜的英雄在那场战争中咽下了最后一口气，还被天灾士兵脱去了所有护甲，连死亡的尊严都没能保住。$B$B把被玷污的护甲部件和净化所需的材料给我带来，你就会了解信仰的含义。', '如果你将1件被玷污的长袍、25块布衣碎片、4张月布和2块连结水晶交给东瘟疫之地圣光之愿礼拜堂的英尼戈·蒙托尔神父，他会为你制作一件信仰长袍。', '装备准备好了，$N。用你的公正之火将那些伤害我们世界的人击溃。', '你帮我把试剂带来了吗，孩子?', '', '去东瘟疫之地找圣光之愿礼拜堂的英尼戈·蒙托尔神父。', '', '', '', '');
