INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9117, '信仰腰带', '<蒙托尔神父在你面前做了一个奇怪的手势。>$B$B幸运的$G小伙子:姑娘;，你找到那些阵亡士兵的护甲了吗？这些可怜的英雄在那场战争中咽下了最后一口气，还被天灾士兵脱去了所有护甲，连死亡的尊严都没能保住。$B$B把被玷污的护甲部件和净化所需的材料给我带来，你就会了解信仰的含义。', '如果你将1条被玷污的腰带、8块布衣碎片、2块奥术水晶和2张月布交给东瘟疫之地圣光之愿礼拜堂的英尼戈·蒙托尔神父，他会为你制作一条信仰腰带。', '装备准备好了，$N。用你的公正之火将那些伤害我们世界的人击溃。', '你帮我把试剂带来了吗，孩子?', '', '去东瘟疫之地找圣光之愿礼拜堂的英尼戈·蒙托尔神父。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9118, '信仰腕轮', '<蒙托尔神父在你面前做了一个奇怪的手势。>$B$B幸运的$G小伙子:姑娘;，你找到那些阵亡士兵的护甲了吗？这些可怜的英雄在那场战争中咽下了最后一口气，还被天灾士兵脱去了所有护甲，连死亡的尊严都没能保住。$B$B把被玷污的护甲部件和净化所需的材料给我带来，你就会了解信仰的含义。', '如果你将1副被玷污的腕轮、6块布衣碎片、1块奥术水晶和1块连结水晶交给东瘟疫之地圣光之愿礼拜堂的英尼戈·蒙托尔神父，他会为你制作一副信仰腕轮。', '装备准备好了，$N。用你的公正之火将那些伤害我们世界的人击溃。', '你帮我把试剂带来了吗，孩子?', '', '去东瘟疫之地找圣光之愿礼拜堂的英尼戈·蒙托尔神父。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9121, '恐怖之城，纳克萨玛斯', '病木林深处就是纳克萨玛斯的宫殿入口。那儿的符文传送门被魔法结界笼罩，一般人是根本进不去的，不过现在不一样了。$B$B我们已经想出了破除结界的方法——奥术掩码。我对肯瑞托古老的咒语进行了一些修改，使它具备了破除纳克萨玛斯结界的能力。但是你在银色黎明的声望还不高，$N，因此你需要支付一大笔钱。或者当你的声望达到崇敬或是崇拜时再来找我，我会给你打折的。', '东瘟疫之地圣光之愿礼拜堂的大法师安吉拉·杜萨图斯需要5块奥术水晶、2块连结水晶、1个正义宝珠和60金币。你在银色黎明中的声望必须达到尊敬。', '你会感到一点刺痛，$N。那种感觉就表示它发挥作用了。完成之后，你就能踏上病木林里的符文传送门进入纳克萨玛斯。', '从没有人能进入纳克萨玛斯还活着讲他的故事。', '', '去东瘟疫之地找圣光之愿礼拜堂的大法师安吉拉·杜萨图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9122, '恐怖之城，纳克萨玛斯', '病木林深处就是纳克萨玛斯的宫殿入口。那儿的符文传送门被魔法结界笼罩，一般人是根本进不去的，不过现在不一样了。$B$B我们已经想出了破除结界的方法——奥术掩码。我对肯瑞托古老的咒语进行了一些修改，使它具备了破除纳克萨玛斯结界的能力。我说过，这种咒语价格不菲，但是你对银色黎明的贡献令人非常敬佩，我们会给你打个折扣的。', '东瘟疫之地圣光之愿礼拜堂的大法师安吉拉·杜萨图斯需要2块奥术水晶、1块连结水晶和30金币。你在银色黎明中的声望必须达到崇敬。', '你会感到一点刺痛，$N。那种感觉就表示它发挥作用了。完成之后，你就能踏上病木林里的符文传送门进入纳克萨玛斯。', '从没有人能进入纳克萨玛斯还活着讲他的故事。', '', '去东瘟疫之地找圣光之愿礼拜堂的大法师安吉拉·杜萨图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9123, '恐怖之城，纳克萨玛斯', '病木林深处就是纳克萨玛斯的宫殿入口。那儿的符文传送门被魔法结界笼罩，一般人是根本进不去的，不过现在不一样了。$B$B我们已经想出了破除结界的方法——奥术掩码。我对肯瑞托古老的咒语进行了一些修改，使它具备了破除纳克萨玛斯结界的能力。我说过，这种咒语价格不菲，但是你对银色黎明的贡献是不可估量的！我们不会向你收取任何费用。', '东瘟疫之地圣光之愿礼拜堂的大法师安吉拉·杜萨图斯会免费为你施放奥术掩码的咒语。你在银色黎明中的声望必须达到崇拜。', '你会感到一点刺痛，$N。那种感觉就表示它发挥作用了。完成之后，你就能踏上病木林里的符文传送门进入纳克萨玛斯。', '从没有人能进入纳克萨玛斯还活着讲他的故事。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9124, '地穴追猎者护甲的材料……', '你想赚到这些亮闪闪的玩意儿吗？$B$B<雷奥普德举起一枚十字军徽记。>$B$B我有点小麻烦，或许你能帮得上忙，$N。瞧，我会为那些敢于进入纳克萨玛斯宫殿的勇士们制作地穴追猎者套装。虽然他们能为我提供所需的主要材料，但是我还需要地穴魔的碎块。把一组碎块交给我，我会送你一枚十字军徽记作为奖励的，这东西在军需官那儿大有用处。', '东瘟疫之地圣光之愿礼拜堂的猎手雷奥普德要30份地穴魔的碎块。', '啊，这会很适用，$N。记住，我永远都会接受更多的部位。你每给我一束，我就会奖励你一枚徽记。', '狩猎的如何?', '', '去东瘟疫之地找圣光之愿礼拜堂的猎手雷奥普德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9125, '地穴魔的碎块', '', '', '非常好，$N!这些绝对会很有助益。', '你的第一批货是个示范性的成就，$N。如果你有更多，我现在就会收下它们。你每交给我一束，我就会用一枚徽记奖励你。', '', '去东瘟疫之地找圣光之愿礼拜堂的猎手雷奥普德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9126, '骨镰的材料', '打造胡里奥的骨镰护甲需要大量白骨碎片。虽然那些勇敢的家伙们已经从纳克萨玛斯的宫殿中为我取回了重要材料，但是我还需要白骨碎片。$B$B你觉得怎么样？想接受这项任务，顺便杀些天灾士兵吗？这可是件双赢的好事儿。', '东瘟疫之地圣光之愿礼拜堂的洛汉要30个白骨碎片。', '你工作的很快，$N。快的跟狐狸一样……嘿，我有跟你说过我在美容沙龙四重唱的日子吗?$B$B提醒我最近找一天跟你说那个故事。', '我可以指引你去骷髅遍布的地方，$C。', '', '去东瘟疫之地找圣光之愿礼拜堂的杀手洛汗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9127, '白骨碎片', '', '', '我在加基森的舞厅当全职舞者的梦想终于要实现了!继续努力，$N。', '我的人手里从没有人能拥有许多骨头碎片，$N。不论何时，只要你有多馀的碎片，把它们带来给我，我就会用另一枚徽记奖励你。', '', '去东瘟疫之地找圣光之愿礼拜堂的杀手洛汗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9128, '元素交易', '冒险者，你好啊！你对这儿的工作感兴趣吗？如果你替我做事的话，我会给你这些徽记作为报酬的。你可以用它们在军需官那里购买各种物品。$B$B我只需要元素之核，越多越好！$B$B你在整个艾泽拉斯世界都可以找到形状尺寸各异的元素之核。', '东瘟疫之地圣光之愿礼拜堂的大法师安吉拉·杜萨图斯要30个元素之核。', '做的好，$N!如同先前允诺的，徽记是你的了。只要记住，还有很多熔火……', '我只能将你引入正途，$N。', '', '去东瘟疫之地找圣光之愿礼拜堂的大法师安吉拉·杜萨图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9129, '元素之核', '', '', '你为我们奉献许多，$N。做的好!', '说实话，我用熔核来制作霜火护甲。这是法师用来对抗纳克萨玛斯的护甲。如果没有你和其它像你一样的人，我们大概绝对会输掉这场战役。$B$B说到这，如果你给我更多熔核，我就会给你更多徽记。', '', '去找东瘟疫之地的大法师安吉拉·杜萨图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9130, '银月城的货物', '欢迎你，志愿者！如你所见，我们的物资储备有些不足。眼下的储备情况难以维持人员供给，更不要说对抗达尔坎和天灾军队了。$B$B我们的新盟友血精灵许诺会为我们提供物资援助，这也是\r\n你来这儿的目的吧，$C。$B$B我想请你把这份货物清单交给飞行管理员加尼斯·日翼。他会告诉你转至银月城的捷径。', '将军需官雷米尔的货运清单交给塔奎林的飞行管理员加尼斯·日翼。', '里莫要你转至银月城把她的货物带回来，是吗?没问题，我可以让你快速地到达那里……当然，要收一点费用。', '嗯，这是什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9131, '无畏护甲的材料', '你有见过无畏套装吗，$C？噢，你当然没有见过。你还是个$G小伙子:姑娘;，孩子。让我来告诉你吧，无畏套装是一套象征着荣耀的护甲。$B$B你或许会问，这跟你有什么关系呢？我要说的是，如果你有黑铁碎片的话，我会很乐意统统买下的。$B$B我需要这些碎片为勇士们打造无畏套装。把碎片给我，你会得到报酬的。', '东瘟疫之地圣光之愿礼拜堂的科尔法克斯要30个黑铁碎片。', '就当前而言，这已足够。如果你又有更多，你知道可以在哪里找到我。', '<柯菲斯对你咆哮。>$B$B你想要什么?指导?我可以提供……', '', '去找东瘟疫之地的科尔法克斯，圣光之勇士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9132, '黑铁碎片', '', '', '你只带了这些来给我?你可能没听清楚我说的话。我要更多!', '你每给我一堆碎块，我就会给你一枚徽记 - 越多越好。在我把你碎成两半之前快离开我的视线!', '', '去找东瘟疫之地的科尔法克斯，圣光之勇士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9133, '飞往银月城', '$C，只需花费几个小钱，我就可以让这些神奇的野兽把你送到你想去的地方，绝对快捷舒适。更重要的是，绝对比走路安全，这一点我可以向你保证！$B$B你到了银月城之后，就去花园街市找萨斯雷·蓝空吧。$B$B等你有足够的勇气上天飞行之后，再来和我谈谈。', '租用飞行服务转至银月城，并将军需官雷米尔的货运清单交给银月城的萨斯雷·蓝空。', '这是什么?里莫的脑袋从头里掉出来了吗?他要这些的全部!?$B$B你有带人来帮你运回去吗?', '你手上拿着的清单还真不简单，朋友。让我看看它。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9134, '葛拉米', '嗯，看来你既没有推车，也没有驮载用的牲畜，还是量力而行吧。我会给你适当数量的货物，如果你已经跟塔奎林的飞行管理员加尼斯·日翼谈过，就尽快飞回塔奎林，把这些东西交给军需官雷米尔。$B$B将货物交给银月城的飞行管理员葛拉米做最后的检查工作，然后跟她谈谈飞回塔奎林的事。葛拉米就在银月城的牧羊人之门外。', '将军需官雷米尔的货物交给银月城的葛拉米。', '那么，回到幽魂之地的塔奎林?没问题，我可以让你很快就回到那里!', '哇，你手上的盒子看起来很重!你想不想把它放在我的飞行驮兽身上?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9135, '返回军需官雷米尔身边', '飞行是要付费的，我能告诉你的仅此而已。萨斯雷根本不懂得节约，我敢说塔奎林会把我们所能提供的援助物资用得一干二净。似乎被遗忘者的处境不妙，虽然这些家伙长相丑陋，四肢腐烂，但我们对他们还是心存感激。$B$B问题是，你有没有跟我在塔奎林的同事加尼斯·日翼谈过？如果有的话，事情就好办了。你只需支付一笔小小的费用，就可以飞回去啦。$B$B准备好了之后就告诉我一声。', '租用飞行服务返回幽魂之地的塔奎林，将军需官雷米尔的货物交给塔奎林的军需官雷米尔。', '嗯，我想如果他说剩下的东西很快就会送来的话，我就会相信他的话。我们成为盟友以来他一直都在短时间内提供物品。\r\n\r\n谢谢你，$N，你是辛多雷的荣耀!拿着这些钱……它们一整天都在我口袋里叮当响。', '$C，这么快就回来了?那是我要你去找的物品吗?看起来不像是我要的全部东西!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9136, '蛮荒之叶', '我会为那些进入纳克萨玛斯宫殿的勇士们打造一套名为梦游者的护甲。他们能为我提供大多数材料，但是我还需要来自艾泽拉斯某种植株的蛮荒之叶。$B$B你或许认为这项任务太过容易，但是蛮荒之叶是打造梦游者套装的必备材料。$B$B如果你能完成任务，我还会让你挑选一枚银色黎明徽记或是十字军徽记作为奖励。', '东瘟疫之地圣光之愿礼拜堂的莱茵需要30片蛮荒之叶。', '我很感激，$N。$B$B<瑞恩鞠躬。>$B$B请记得我永远都会收受藻叶。', '我非常熟悉我们世界的植物群。你需要指导吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的莱茵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9137, '蛮荒之叶', '', '', '谢谢你，$N。你的贡献对我们成功战胜天灾军团极为重要。', '你每给我一束藻叶我就会给你一枚黎明徽记或十字军徽记。$B$B徽记可以交给军需官换取不同的奖励。', '', '去东瘟疫之地找圣光之愿礼拜堂的莱茵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9138, '日冕村', '$c，我们被包围了。亡灵天灾侵占了所有的外围村落！$B$B你最好立即转至东北方的日冕村，解除蛛怪的威胁。那是一种蜘蛛类的生物，很容易辨认。$B$B时间紧迫……我们必须收复奎尔萨拉斯！', '杀死10个蛛怪卫兵，然后向幽魂之地塔奎林的奥术师范迪瑞尔复命。', '太棒了!但是，在天灾军团的威胁被永远赶出奎尔萨拉斯之前还有很多事要做。$B$B来，拿着这个钱币……虽然不多，但这是你应得的。', '有你的协助我们一定可以遏制天灾军团，$C。达克汗会被制服的!$B$B你有处理过日冠村奈幽蛛怪的问题吗?', '', '去幽魂之地找塔奎林的奥术师范迪瑞尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9139, '金雾村', '我们终于获得了一次胜利，但仍有两个村庄需要收复。$B$B金雾村将是我们的下一个目标。它位于西北方向，当前被一些高等精灵的怨灵与鬼魂所占据。听起来确实很可怕，我也知道，但这的确是天灾军团的惯用战术。$B$B去消灭那里的鬼魂和怨灵，$c。出了塔奎林后，沿道路一直向西走就可以到达那里。', '在金雾村消灭6个奎尔多雷鬼魂和4个奎尔多雷怨灵，然后向幽魂之地塔奎林的奥术师范迪瑞尔复命。', '你在金雾村的成功带领着我们往收复领土更加迈近了一步。不过别因而欺骗自己，$C;这场战役还没结束。$B$B拿着，这是你应得的。当你转至对付风行者村时会需要这个的。', '我在这里已经经历过很多对抗天灾军团的事了。他们会被击退的，但是一定要一小步一小步慢慢地来。他们有一种卑鄙的手段，就是将你们死去的人抢走，加入他们自己的力量成为新的势力，因此你们一路上千万不能有一点疏失。$B$B那么，金雾村的战绩如何?', '', '去幽魂之地找塔奎林的奥术师范迪瑞尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9140, '风行村', '$N，现在，收复幽魂之地最后一座村庄的任务也将落在你的肩上。风行村位于这里的西南方，当前被一群非常强大的天灾军团飞行部队占据了。这些飞行部队由石像鬼和阴影组成。你将是我们进攻力量的核心，将是羽箭之锋芒，将是担负起削弱对方军力的重任的先锋。$B$B附近的太阳圣殿里的魔导师们最近还递交了一份特殊申请，他们希望能获得一些天灾军团生物的残骸碎片用于研究，看看能否找到它们的弱点。$B$B祝你狩猎愉快！', '收集6份幻影灵质和4块石像鬼碎片，把它们交给幽魂之地塔奎林的奥术师范迪瑞尔。', '你办到了，$N。你击破了天灾军团三个村子的要塞!现在我们可以集中我们的火力，更能轻易对抗死亡之痕和死亡之域南方的天灾军团了。$B$B来，从里面选择一个。我相信你哪都不会去吧?我们还需要你持续协助我们!', '$C，风行者村被释放了吗?那些可恶的太阳圣所博学者严厉地要我把那些我要你去收集的天灾遗物交到他们手中。$B$B不过别担心。你慢慢来把工作做好。让我来烦恼那些博学者的事。', '', '去幽魂之地找塔奎林的奥术师范迪瑞尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9141, '梅兹的文书', '你想要文书？什么？你认为多少人梦寐以求的文书仅仅是用来炫耀的吗？你错了，无知的家伙。世界各地的工匠们都想要为前线战事贡献自己的一份力量。$B$B如果你想拿到订单的话，就得证明你愿意投身这项事业。将一枚勇气勋章交给我吧。$B$B惟有杀戮能让你这卑微的家伙了解真相。', '东瘟疫之地圣光之愿礼拜堂的物资官员梅兹要一枚银色黎明勇气勋章。', '好，这是它使用的方式:你每交出一枚勇气勋章，我就会给你另一个令状。你要完成令状上的任务并将它交给军需筹备官石汉。懂了吗?很好。现在快滚吧。', '<指挥官梅兹抽着他的雪茄。>$B$B有什么事吗?我是个大忙人。', '', '去找东瘟疫之地的物资官员梅兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9143, '塞布索雷的巨魔', '中尉事先并未侦察敌情，就贸然命令我们向湖对面的巨魔开战。我们就因为他的愚蠢而全军复没！你听到了我说话了吗，托曼森？你这个废物！白痴！$B$B你能帮帮我们吗，$c？我们仍然需要削减巨魔的数量，可我又得留在这儿照顾他——我想这家伙八成是傻了。$B$B朝东走，湖对面便是塞布索雷，我要复仇……把表明他们身份的标记给我带来！', '收集6个塞布索雷巨魔标记，把它们交给幽魂之地的游侠瓦兰娜。', '感谢你为我们做的一切，$C!谢谢你。现在，我能够确定那些在这次征战中消失的生命不会白费了。', '你拿到他们的耳朵了吗?你知道的，如果我们能够常常得到塔奎林的帮助，那他们就不再是一个麻烦了。我真高兴你来了。', '', '去找幽魂之地的游侠瓦兰娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9147, '倒下的信使', '你还站在那边做什么？你没看见这个小伙子需要照顾吗？看起来瘟疫正在逐渐侵袭他的躯体。再耽搁一会儿，就连我这样的药剂大师也无能为力了。$B$B河流南岸的动物的血液中都携带着瘟疫，去给我猎杀一些动物，带足够的瘟疫血样回来，这样我才能提炼出足以挽救这个小伙子的血清。快一点！', '药剂师瑟德拉要求你从幽魂之地的野兽身上收集4份染疫血样。', '来的正好，$N!我刚好要开始帮我们的朋友在这里挖一个洞。$B$B我的药剂似乎开始产生作用了，他正苏醒过来。$B$B嘿，我想他想要跟你聊聊。你何不跟他说说话呢?', '嗯?你把我需要的东西带来了吗?快点，否则那个可爱的血精灵男孩就要死了!', '', '去找永歌森林的药剂师瑟德拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9148, '送往塔奎林的信件', '我……我太虚弱了，没法前行。这封信是摄政王洛瑟玛·塞隆大人的亲笔信，只能靠你……帮我送信了。$B$B把它交给塔奎林的奥术师范迪瑞尔。沿着这条路继续朝南走就可以到那里了。去那里……找到范迪瑞尔……', '将银月城的信件交给幽魂之地塔奎林的奥术师范迪瑞尔。', '啊，终于!我们等着地区统治者的回复等了好几个礼拜!让我看看……$B$B<范德隆开始展读这封信。>$B$B什么?一股黑暗的力量?他感觉到幽魂之地有一股黑暗的力量?!别开玩笑了;这我也会说!$B$B这就是我们一直在等的回复?', '你有东西要给我?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9149, '瘟疫海岸', '要找出治愈瘟疫的办法，首先要分析它对各种生物带来的影响，从最复杂的生命体到最低等的亚种都要搞清楚。$B$B幽魂之地的鱼人在这场瘟疫中奇迹般地活了下来，我一直在研究其中的奥秘。这种低等的动物为何能抵御瘟疫的侵袭？$N，我必须找出答案！$B$B转至西北方的鱼人村落，将鱼人的脊骨带回来，我要研究骨髓的成分。谁知道它们小小的脊骨中隐藏着什么秘密？', '将6根染疫鱼人脊骨交给塔奎林的药剂师雷兹特恩。', '太好了!我会好好利用这些脊椎。$B$B收下这些做为奖励。如果你想回到海岸就会需要它们。', '你弄到我要你取得的样本了吗，$N?', '', '去幽魂之地找塔奎林的药剂师雷兹特恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9150, '重建历史', '你相信吗？我们在东南方设立了一座能够正常运转的奥术圣殿——太阳圣殿。声名显赫的魔导师全都去了太阳圣殿负责管理工作。$B$B他们显然忽视了月亮圣殿的存在。在被废弃的月亮圣殿中，残馀的能量滋生出某些奇异的生物体。$B$B我可不愿意让这么好的资源白白浪费。转至月亮圣殿，从那里的生物身上取回一些晶化法力精华。', '魔导师戴伦尼斯要你转至塔奎林以西的月亮圣殿，从那里的奥术吞噬者和法力流窜者身上取回8份晶化法力精华。', '这些东西会非常有用，$N。我对你所做的努力很高兴。', '你拿到那些精华了吗，$N?', '', '去幽魂之地找塔奎林的魔导师戴伦尼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9152, '托博尔的补给品', '如果我连补给品都拿不到，还怎么开店？我所倚仗的护送队伍压根就没有出现过，所以我只好一个人出发，结果在经过西边的时候遭到一帮食尸鬼的攻击，有辆推车落在了那儿。$B$B你能帮帮我吗？沿着西边的道路走出城镇，穿过墓地。在死亡之痕对面有个岔路口，我的推车就停在路那边的小山坡上。', '找到拉提斯·托博尔的补给品，把它交给幽魂之地塔奎林的拉提斯·托博尔。', '剩下的商品都在这里，我总算能够开店了。我相信高阶执行官会很高兴听到达克汗和天灾军团的战争开始了。$B$B还有，当然，这里是你的一点报酬。很好，$C，这就是我提过的钱。记得一定要来看看有没有你需要的商品。', '只要我拿回剩下的商品，我就会开始营业。如果他们无法购买所需的贸易物资，武力就会无法往前进行。$B$B战区真是个图利的好地方啊!你说是吗，$C?$B$B那么，你成功的从那些食尸鬼手中抢回我的运货车了吗?', '', '去幽魂之地找塔奎林的拉提斯·托博尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9153, '阴影之下', '那些漂浮在空中的天灾浮空城污染了部落和联盟的土地。塔纳利斯、诅咒之地、冬泉谷和燃烧平原都笼罩在它们的阴影之下。$B$B我们只有协力作战，才能消灭敌人。$B$B在天灾入侵之地，有多处魔法阵支持着这些浮空城。我们决定要攻破法阵周围的防御势力。', '在你的地图上寻找天灾入侵的地区。击败浮空城周围的天灾士兵，摧毁一处浮空城。将10块死灵石交给东瘟疫之地圣光之愿礼拜堂的指挥官托马斯·海勒拉。', '你做的很好，$N。透过持续增加的获胜记录，我们将可以战胜巫妖王和他的手下。$B$B休息一下养精蓄锐，但你之后务必要再次回到前线，以免我们损失了今天才夺回的土地。$B$B为了在日后的战役中帮助你，我们会用特别的物品和你交易更多的亡域符文。', '要战胜这个威胁需要一些时间。你的进展如何，$N?', '', '去东瘟疫之地找圣光之愿礼拜堂的指挥官托马斯·海勒拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9155, '转至死亡之痕', '你应该已经见过死亡之痕了吧，阿尔萨斯当年沿着这条路线杀入银月城，而现在无数没脑子的天灾士兵正虎视眈眈地盘踞在那里。$B$B去做点有用的事情吧，削减死亡之痕一带的天灾士兵的数量。如果你能证明自己的价值，我会替你美言几句的。', '在死亡之痕除掉10个复生的饥饿者和10个笨拙的食尸者，然后向塔奎林的亡灵哨兵拉提尔复命。', '不错，$N。继续保持，我们可以多用些像你一样的人。', '你完成你的任务了吗?', '', '去幽魂之地找塔奎林的亡灵哨兵拉提尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9156, '通缉：纳克雷洛特和卢兹兰', '塔奎林对两名憎恶：纳克雷洛特和卢兹兰发出通缉令。这些可怕的生物是达尔坎的创造物，有目击者称它们在鬼嚎通灵塔和鲜血通灵塔附近巡逻。拿回纳克雷洛特和卢兹兰的徽记作为凭证，在亡灵哨兵拉提尔处领取赏金。', '在幽魂之地搜寻并杀死纳克雷洛特和卢兹兰，将他们的徽记交给塔奎林的亡灵哨兵拉提尔换取奖励。', '啊……纳克罗和路斯莱恩!你看起来不那么强壮了，是吗?我看的出来你还是和以前一样丑陋。$B$B拿着这个奖励，$N。你获得了它。', '你有东西要给我吗，$N?', '', '去幽魂之地找塔奎林的亡灵哨兵拉提尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9157, '被遗忘的仪祭', '每年我们日冕村的村民都会举行仪式控制各种不同的自然生物。我们需要召唤并奴役阿奎艾森来控制水元素，但是由于一个法术的失误，阿奎艾森挣脱了束缚，反过来奴役了我们！$B$B那场仪式的参与者们都佩戴着波浪状的勋章。我们需要取回那些勋章，重新控制阿奎艾森，解放我们的灵魂！', '将8枚波浪勋章交给幽魂之地的格兰尼斯·月晨。', '有了这些勋章我们就能再次召唤海之平衡。叛变的元素将会付出代价而我们的死也得以报复。', '你拿到勋章了吗，$N?溺死的鬼魂仍然在这湖边徘徊!', '', '去找幽魂之地的格兰尼斯·月晨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9158, '瘟疫的使者', '你能来幽魂之地就证明你相当勇敢，$N。要做的事儿还很多，懦弱的家伙是无法胜任的。$B$B如果你愿意伸出援手的话，我有一项艰巨的任务要交给你。瘟疫已经污染了此地的野生动植物，我们必须阻止瘟疫的继续扩散。去清理东边和南边的鬼爪山猫，然后回来向我复命。', '远行者营地的远行者塞蒂娜要求你杀死10只鬼爪山猫。', '你做的很好，$N。瘟疫绝不能散播到永歌森林健康的野生生物身上。如果你想找事做的话我这里还有一些工作。', '你完成了我要你去做的任务吗，$N?', '', '去幽魂之地找远行者营地的远行者塞蒂娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9159, '控制瘟疫', '你已经证明了自己的价值，$N。我需要你继续猎杀更多被污染的生物。现在去寻找更危险的野兽吧。清除死亡之痕西边的纺丝潜伏者和这里南边的吸血迷雾蝠，然后回来向我复命。', '远行者营地的远行者塞蒂娜要求你杀死8只纺丝潜伏者和10只吸血迷雾蝠。', '你很认真的看待任务因此我要给你一个适当的奖励。我们需要更多和你一样有勇气和决心的盟友，$N。', '你完成了我要你去做的任务吗，$N?', '', '去幽魂之地找远行者营地的远行者塞蒂娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9160, '调查安达洛斯', '很高兴你能伸出援手，$C。我们和最近出现的一群暗夜精灵斥候之间出了点问题。我们不清楚他们有什么目的，只知道这些家伙在此地西北方一处名为安达洛斯的古代高等精灵魔网节点设立了营地。你需要穿越死亡之痕才能到达那儿。$B$B希望你能转至调查他们的动向，多杀几个自以为是的暗夜精灵。', '调查安达洛斯一带，杀死12个哨兵部队间谍，然后向幽魂之地塔奎林的奥莉菲洛丝夫人复命。', '很遗憾他们在安都拉斯的计画还不明确。不过，那些看起来像小魔法树，上面又有能量宝珠的东西听起来很有趣。$B$B没关系，我们不会这样就被吓倒的。我们只需要以后更积极的收集情报。$B$B来，拿着这些钱和药水。我相信在我们对付完夜精灵之前你会发现它们很有用的。', '$C，你从安都拉斯带回来什么消息还有夜精灵都在那边做什么?', '调查安达洛斯', '去找幽魂之地的奥莉菲洛丝夫人。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9162, '往日的线索', '当你翻阅这本日记时，突然觉得背后有诡异的目光注视着自己。$B$B日记上记录的内容相当混乱。达尔坎的心中充满了对自己族人的仇恨和蔑视。日记中详细描述了他的诡计和阴谋。$B$B或许维恩娜会用得上这本日记。', '将达尔坎的日记交给远行者营地的游侠维恩娜。', '这项资讯非常有价值，$N。我们都知道达克汗计画偷取太阳之井的能量给天灾军团，但这里发现的资讯对我们而言是全新的线索。太阳圣所的博学者坎德立斯会想看看这个的。', '告诉我，$N，你发现了什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9163, '深入敌境', '现在，我们将展开一系列行动以探明这些暗夜精灵来此的真正目的。你将负责执行这个计划，首先，你要转至他们所占据的小岛，收集任何你所能得到的情报。$B$B我要求你出镇后直接沿路向西前进，去海岸对面的沙兰蒂斯岛。到那里之后，在船上和岛屿上寻找任何行动计划书之类的东西。', '窃取暗夜精灵计划表：安达洛斯、暗夜精灵计划表：安欧维恩和暗夜精灵计划表：监视辛多雷，然后向幽魂之地塔奎林的奥莉菲洛丝夫人复命。', '事情有点棘手!这些计画说明了除了我们原本就知道的安都拉斯，夜精灵也在安欧恩，一个东南方更遥远的能量界线连结点也有他们的地盘。$B$B在东边有我们没提过的第三个连结点。它叫做安泰拉斯。对此，我有着不详的预感，$C。', '你去萨蓝迪斯岛搜寻夜精灵秘密计画一事进行得如何了，$C?', '', '去幽魂之地找塔奎林的奥莉菲洛丝夫人。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9164, '戴索姆的俘虏', '啊，当然。我最得意的发明。这种药膏可以解除多种形式的药物控制效果。$B$B副作用可能包括昏迷、呕吐或者暂时性的失明。这些显然都比天灾军团对俘虏所采用的手段要舒服得多……$B$B祝你好运，勇敢的$c。', '转至塔奎林，从药剂师雷兹特恩那儿拿到雷兹特恩的疗伤药膏，然后转至戴索姆，救治学徒瓦尼斯、药剂师恩尼斯和游侠维多兰。完成任务之后返回太阳圣殿找奥术师亚尼达领取奖励。', '做的很好，$N。如果没有你的帮忙那些俘虏的思想与灵魂就会毁在天灾军团手里。', '死亡之域的囚犯都变成什么样子了?你去过那里了吗?', '', '去幽魂之地找太阳圣殿的奥术师亚尼达。', '营救药剂师恩尼斯', '营救学徒瓦尼斯', '', '营救游侠维多兰');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9165, '通行文书', '要是没有那些探险者的帮助，我的商队肯定难逃此劫！天灾士兵突然从黑暗中显身，拦住了我们的去路。$B$B<卫兵迪迪尔擦了擦眉毛上的汗水。>$B$B现在我们得在这儿等待查博斯元帅。他会在你的通行文书上签字，之后你就要返回圣光之愿礼拜堂找物资官员梅兹。$B$B$N，在查博斯元帅面前说话可得小心点。他是那种一怒起来就会冲过来砍下你的脑袋再吐口痰的家伙——而且他真的会这么做……', '将签过字的通行文书交给东瘟疫之地圣光之愿礼拜堂的物资官员梅兹。', '<发送指挥官梅兹接过令状并签署。>$B$B做的好，$N。可以说是相当杰出!收下这个以表我们的感谢。别说客套话了，小鬼。', '报上名字，军阶还有编号!', '', '', '', '在通行文书上签字', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9166, '返回安泰拉斯', '$N，我想请你带上从沙兰蒂斯岛取回的暗夜精灵计划表，去一趟安泰拉斯。$B$B安泰拉斯就在此地以东，太阳圣殿东北方的阳痕峰南坡上。魔导师塞拉斯托在那儿研究着高等精灵的魔网节点，他或许知道那些暗夜精灵有什么打算。$B$B请按照他的指示行事。', '将暗夜精灵计划表交给幽魂之地安泰拉斯的魔导师塞拉斯托。', '真是太糟糕了!夜精灵!他们在这里召唤月水晶以进行他们的恶毒计画，但是我悄悄地转至太阳圣所，招集更多的斥候和施法者并组成一支小队。我们杀死了大部分的夜精灵，小队的其它成员当前正在追杀他们残存的党羽!$B$B很高兴你来帮忙;我的身边只剩下几名保护我的斥候而已!这里并不是个安全的地方!$B$B给我一点时间，让我从这份计画中看出那些夜精灵打的是什么主意。', '喔，真是太感谢你了!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9167, '叛徒的毁灭', '我们在幽魂之地所做的一切都是为了夺回原本属于我们的东西。天灾军团已经在它们的要塞里苟延残喘太久了。$B$B复仇的时候到了，$N。感谢你的帮助，也感谢被遗忘者们的帮助，我们终于等到了这一刻。$B$B妄图盗取太阳井力量的家伙必须死。杀入死亡之痕南部的天灾要塞戴索姆，将达尔坎的徽记取回来，你将名垂千古，$N！', '进入戴索姆杀死达尔坎，将他的徽记交给幽魂之地太阳圣殿的魔导师坎迪瑞斯。', '今天你在天灾军团的势力范围内给了他们致命的一击。$B$B没有了可恶的叛国者，我们很快就能夺回自己的土地，重振声威。', '那么，完成了吗?杀死达克汗了吗?', '', '去幽魂之地找太阳圣殿的魔导师坎迪瑞斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9169, '关闭安欧维恩', '他们的月亮水晶是一种侦测工具，他们显然要利用这东西来侦察我们的行动。据我所知，安达洛斯那里的能量不够强大，无法支持起这种工具，但正南方的安欧维恩则毫无疑问具备足够的能量强度！$B$B我研究了一下这些计划书，基本上搞清楚了月亮水晶是如何运作的，并且也知道如何关闭它们。你必须立刻赶往安欧维恩，从某个暗夜精灵手中抢到控制宝珠，然后在月亮水晶上使用它，这样就可以关闭月亮水晶，阻止他们的计划了！$B$B行动快一点，$c！', '获取水晶控制宝珠，用它关闭安欧维恩的暗夜精灵月亮水晶，然后向幽魂之地安泰拉斯的魔导师塞拉斯托复命。', '真是令人感到欣慰，$C!我向你保证，如果你没有关闭安欧恩的占卜宝珠，我们的情势会比现在还要凄惨!想想看，被敌人层层包围而且他们其中一人甚至还能占卜出我们每一个行动的念头!$B$B但是现在我们不用担心了，多亏了你!来，拿着这个，我要奖励你的努力而且我手边刚好有这些不用的东西。$B$B再次谢谢你，$N!', '结束了吗，$C?你成功地关闭安欧恩的夜精灵月水晶了吗?', '', '去找幽魂之地的魔导师塞拉斯托。', '关闭暗夜精灵月亮水晶', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9170, '达尔坎的军官', '可憎的叛徒达尔坎在天灾军团中掌握了实权。他麾下的军官统领着亡灵大军，而我方的军队数量却在不断减少。$B$B黑衣玛索菲特、欺诈者尤瑞恩、放血者鲍尔古斯和堕落者米尔杜兰是幽魂之地天灾军团的首领人物。杀死这些军官，天灾军团自然会陷入混乱。', '魔导师伊东尼斯要你转至戴索姆杀死黑衣玛索菲特、欺诈者尤瑞恩、放血者鲍尔古斯和堕落者米尔杜兰，完成任务后回到幽魂之地的太阳圣殿向他复命。', '达克汗的军队很快就会瓦解。天灾军团不会有机会对抗被遗忘者与辛多雷结合的力量了。', '你成功的切断了天灾军团的指挥炼吗，$N?达克汗的副官们都死了吗?', '', '去幽魂之地找太阳圣殿的魔导师伊东尼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9171, '松脆蜘蛛腿', '这简直难以忍受！我在这儿根本没事可做！奥莉菲洛丝夫人命令我从银月城赶来这里……当然，我不能违抗她的命令。她需要享用美味的菜肴才能造福国民，不是吗？但是我到了这鬼地方，却发现根本没有可用的食材。$B$B你得帮帮我，$C，出去猎杀一些野兽吧，也好让我做点什么食物出来。$B$B奥莉菲洛丝夫人喜欢吃松脆的东西。有卫兵提到过这里的西边有大量的纺丝潜伏者。我知道那是一种恶心的生物，但是我正要取它入菜。', '将5条松脆蜘蛛腿交给幽魂之地塔奎林的大厨师莫迪尔。', '非常好，这些材料很有用。不，别描述它们在地上爬来爬去的样子，我不想知道!我会用这些腿肉施展我的厨艺，它们会变的相当美味。一点点香料，一小撮草药，当然还有一点秘法原料，瞧，这不是一顿给女王的大餐吗……应该是说，夫人。$B$B你的努力非常足够，$C。来，拿着这个食谱和一些试吃样品。', '我想我在这里就能听到夫人的肚子在咕噜咕噜叫了!我想你会在这里跟我说话是因为你已经弄到我要你去找的东西了吧?', '', '去幽魂之地找塔奎林的大厨师莫迪尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9172, '向魔导师坎迪瑞斯报到', '在被遗忘者的帮助下，太阳圣殿的魔导师在研究天灾军团的弱点方面取得了很大的进展。坎迪瑞斯会知道该如何处理这本日记的。$B$B你得赶快，$N。达尔坎是个狡猾的敌人，每时每刻都在监视我们的动向！', '将达尔坎的日记交给幽魂之地太阳圣殿的魔导师坎迪瑞斯。', '这本书……不可能!这真的是达克汗亲笔写下的。这其中一定透露了我们敌人的弱点。$B$B你来找我们是对的，$N。远行者将这件事交给我们是相当睿智的行为。这件护甲应该是你帮助促成我们的原因。', '你想和我谈谈?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9173, '夺回风行者之塔', '$N，真是久仰大名啊！很高兴终于能见着你了。我有事情要麻烦你，请你帮我夺回风行者之塔！$B$B这是一项荣耀的差事，真的。风行者之塔乃是被遗忘者的女王希尔瓦娜斯·风行者以前居住的地方，但是那儿被天灾军团占据了。$B$B沿着道路一直往南走，在分岔路口右转，穿过死亡之痕后向西南方走。你没理由找不到那地方。', '杀死8个戴索姆侍僧和8个堕落游侠，然后向塔奎林的高级执行官玛尔伦复命。', '我相信希尔瓦娜斯会很高兴听到我们在这件事上大有进展。$B$B收下这些钱做为你努力的奖励。', '我相信你是清除了风行者塔的天灾军团才回来的吧?', '', '去幽魂之地找塔奎林的高级执行官玛尔伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9174, '消灭阿奎艾森', '在那个决定命运的日子里，可怕的元素生物夺走了许多族人的性命。他召集低级的鱼人破坏了仪式，叛变后就开始了疯狂的屠杀。$B$B让他尝尝复仇的怒火！将这些勋章放在湖底的海潮掌控祭坛上。阿奎艾森很快就会回应你的召唤！$B$B要小心，$c！这家伙在摆脱我们的魔法控制后变得极度狂暴。杀死阿奎艾森，让我们安息吧！', '格兰尼斯·月晨要你潜入日冕村东面的湖底，对海潮掌控祭坛使用你手中的一堆勋章。杀死你召唤出的元素生物阿奎艾森，然后向格兰尼斯复命。', '你为我们的死报了仇并解放了我们在海之平衡手上的灵魂。我们终于可以安息了。', '海之平衡被消灭了吗?', '', '去找幽魂之地的格兰尼斯·月晨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9175, '女王的项链', '这串项链闪闪发光，弥漫在幽魂之地的阴暗空气也无法掩盖那块宝石的光辉。从项链上所刻的字来看，这是希尔瓦娜斯·风行者的东西！$B$B或许应该把它先交给塔奎林的高级执行官玛尔伦？他似乎是这儿最有地位的被遗忘者，他一定知道要怎么处理这根项链。', '将女王的项链交给幽魂之地塔奎林的高级执行官玛尔伦。', '你说你是在风行者塔里的天灾军团身上找到它的，而且上面还有铭文?让我看看，还有…收下这些钱做为奖励。', '你手里拿的是什么，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9176, '通灵双塔', '从日记来看，达尔坎答应将光芒之石和烈焰之石交给天灾军团。这两件精灵神器拥有太阳之井的魔法力量，可以用来对抗天灾军团。$B$B它们似乎被送到了鲜血通灵塔和鬼嚎通灵塔，就在死亡之痕的中部。如果它们仍在那里，我们就必须尽快找到它们。这两块晶体拥有的力量对我们有很大帮助。', '转至鲜血通灵塔和鬼嚎通灵塔寻找光芒之石和烈焰之石，然后向太阳圣殿的魔导师坎迪瑞斯复命。', '谣言果然是真的!圣光之石和火焰之石真的存在!有了它们的能量我们就能制造对付达克汗的武器了。$B$B在对的时机使用它们，抑制在里面的太阳之井能量就会消灭他，以最初他想从我们这里偷走的力量!', '你取回那些水晶了吗?', '', '去幽魂之地找太阳圣殿的魔导师坎迪瑞斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9178, '工匠文书 - 致密平衡石', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单BS-091：$B$B120个致密平衡石。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将120个致密平衡石和工匠文书 - 致密平衡石交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '是的，这些东西会成为步兵易于操作的攻击武器。', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9179, '工匠文书 - 君王板甲护胸', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单BS-428：$B$B3个君王板甲护胸。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将3个君王板甲护胸和工匠文书 - 君王板甲护胸交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '有更多的护甲给我们的军队!太棒了，$N!', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9180, '幽暗城之旅', '这可了不得！这根项链似乎是女王的姐姐奥蕾莉亚·风行者送给她的礼物！$B$B你最好立即将这东西送往幽暗城，亲自交给女王。希尔瓦娜斯·风行者就在幽暗城的皇家区。$B$B你可以穿过银月城的传送门，然后乘坐电梯到达幽暗城。如果你找不着皇家区，最好看看地图。', '将女王的项链交给幽暗城皇家区的希尔瓦娜斯·风行者。', '<希尔瓦娜斯从你手中拿走项炼。>$B$B这怎么可能!这么久以来，我以为我永远失去它了。$B$B<一阵静默后，女王开始重新注意到周围的情况，镇定了下来。>$B$B你以为这样就能取悦我吗?你以为我还会怀念那段成为被遗忘者女王之前的时光吗?就跟你这个人一样，这东西对我来说完全没有意义，而艾兰里亚.风行者也只是一段逝去的回忆罢了!$B$B<她把护符丢到地上去。>$B$B你现在可以立刻消失在我眼前，$C。', '你是?你手里有什么?那个项炼好眼熟。拿来这儿吧!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9181, '工匠文书 - 火山战锤', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单BS-697：$B$B3个火山战锤。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将3把火山战锤和工匠文书 - 火山战锤交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '这些东西和我们储备的致密平衡石会配合的很好。', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9182, '工匠文书 - 巨型瑟银战斧', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单BS-6020：$B$B3个巨型瑟银战斧。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将3把巨型瑟银战斧和工匠文书 - 巨型瑟银战斧交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '这些东西没有我想象中巨大。不过，我信守承诺。', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9183, '工匠文书 - 辐光头饰', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单BS-80：$B$B3个辐光头饰。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将3个辐光头饰和工匠文书 - 辐光头饰交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '我还是不敢相信梅兹竟期望我们的军队穿戴这种劣质的垃圾来抵抗天灾军团的攻击。', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9184, '工匠文书 - 邪恶皮甲头环', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单LW-971：$B$B10个邪恶皮甲头环。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将10个邪恶皮甲头环和工匠文书 - 邪恶皮甲头环交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '这些东西真是……很棒。', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9185, '工匠文书 - 毛皮护甲片', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单LW-448：$B$B25个毛皮护甲片。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将25个毛皮护甲片和工匠文书 - 毛皮护甲片交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '毛皮护甲片的用处比你想象中还多，$N。他不只可以给予防具更多的护甲，他也可以拿来当做茶壶垫!', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9186, '工匠文书 - 邪恶皮甲腰带', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单LW-736：$B$B9条邪恶皮甲腰带。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将9条邪恶皮甲腰带和工匠文书 - 邪恶皮甲腰带交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '这些邪恶皮甲腰带看起来比邪恶皮甲头带还要更加的棒-如果你相信他说的话。', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9187, '工匠文书 - 符文皮甲短裤', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单LW-8485：$B$B4条符文皮甲短裤。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将4条符文皮甲短裤和工匠文书 - 符文皮甲短裤交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '德鲁伊们一定会感激制作符文皮甲束裤的工匠，非常感谢。', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9188, '工匠文书 - 亮布短裤', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单TR-95：$B$B6条亮布短裤。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将6条亮布短裤和工匠文书 - 亮布短裤交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '哇，这些东西几乎可以将我的样子反射出来!', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9189, '送往瑟伯切尔的信', '你搅得女王心神不宁，虽然她的心早已不再跳动。$B$B我有若干份指令要送往银松森林的瑟伯切尔，顾问索雷伦负责跟那儿的被遗忘者沟通。如果不乘坐蝙蝠的话，转至瑟伯切尔的最快路线是出了幽暗城的城门之后往南走。沿途有路标，应该不难找。打起精神来，瑟伯切尔是座荒芜的墓穴。$B$B那些被遗忘者显然都是些古怪的家伙。', '将密封的辛多雷命令交给银松森林瑟伯切尔的顾问索雷伦。', '啊，很好。我看的出来忧日大使对你水涨船高的辛多雷声望抱着很大的希望。不过很遗憾那是希尔瓦娜斯的差事。别担心，$N，你归还她的项炼是正确的。$B$B当你在这里的时候，你应该选择协助被遗忘者的不同任务，尽你最大所能。你不会想破坏和部落创建的新关系吧?', '你好，$g兄弟:姐妹;，你带来了什么消息?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9190, '工匠文书 - 符文布靴', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单TR-635：$B$B8双符文布靴。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将8双符文布靴和工匠文书 - 符文布靴交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '你真的带来了这些符文布靴，看来是我的胡子赌赢了!', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9191, '工匠文书 - 符文布背包', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单TR-9999：$B$B8个符文布背包。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将8个符文布背包和工匠文书 - 符文布背包交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '我的天啊，这真的是那个吗?你知道吗，这些士兵们每天都不停在跟我抱怨说都没有空间来装军备品，甚至还有一位士兵画了一张图来给我看-真是些没用的家伙……$B$B有了这些包包一定可以让我的耳根子清静一下。', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9192, '幽光矿洞的麻烦', '麻烦事儿总是接踵而至，$C。瞧，又是一份报告，一群自称为黑爪部族的豺狼人占领了西南方的幽光矿洞。不用我说你也知道这件事情的严重性，那些矿产可是我们在幽魂之地的作战物资！$B$B从镇子南面的路走出去，遇到岔路之后向右走，走过通灵塔，你就会看到一条通往西边的小路。$B$B$C，去那儿对付豺狼人吧……必须保证矿物的供给！', '杀死8个黑爪豺狼人、6个黑爪食腐者和4个黑爪萨满祭司，然后向幽魂之地塔奎林的亡灵哨兵玛尔特迪斯复命。', '你完成了一件十足的屠杀任务，$C。我为你感到高兴。没有什么事是比豺狼人侵扰更惹人厌的了。我收回刚刚那句话…我差点忘了还有鱼人。$B$B我们会让矿坑重新运作。我相信他们会很失望自己的假期结束了，但我们必须制作护甲和武器，而那就需要先开采矿石。$B$B来，这是你完成职责的奖励。去把你的护甲和武器修一修，再来和我喝一杯。你已赢得它了。', '是好消息，还是坏消息，$C?', '', '去幽魂之地找塔奎林的亡灵哨兵玛尔特迪斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9193, '调查阿曼尼墓穴', '$C，我们的线人报告说，被埋葬在阳痕峰阿曼尼墓穴内的巨魔尸体竟然重新站立了起来。奥莉菲洛丝夫人希望你去调查这些墓穴，并烧掉那些还没有活化的尸体，这样就可以避免它们为亡灵生物所利用。$B$B以你最快的速度向北出镇吧，在第一个路口向右转，到达山的北侧，然后再折向南就可以看到那里的入口了。', '调查阿曼尼墓穴并烧毁10具巨魔木乃伊残骸，然后向幽魂之地塔奎林的顾问瓦尔文复命。', '很恶心，但我向你保证这是必须的。你调查这件事是帮了我们一个大忙，$C。拜托，收下这个做为我们慷慨的奖赏及感激。', '这是件最无情又有失威严的差事，$C。我相信你会完成这项任务让女士满意。', '调查阿曼尼墓穴', '去幽魂之地找塔奎林的顾问瓦尔文。', '烧毁巨魔木乃伊残骸', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9194, '工匠文书 - 符文布袍', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单TR-7229：$B$B8件符文布袍。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将8件符文布袍和工匠文书 - 符文布袍交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '你真的不需要提供这些!真的，你不需要。不知道那个梅兹在想些什么，不过真的没有人会穿着这些袍子进入纳克萨玛斯。$B$B<军需筹备官石汉叹了口气。>又是一堆我要必须要送到前线的垃圾，钱柏一定又会来跟我抱怨的。', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9195, '工匠文书 - 地精工兵炸药', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单EN-11：$B$B20个地精工兵炸药。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将20个地精工兵炸药和工匠文书 - 地精工兵炸药交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '这样就对了，$C。我最喜欢会爆炸的东西了。', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9196, '工匠文书 - 瑟银手榴弹', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单EN-7：$B$B20枚瑟银手榴弹。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将20枚瑟银手榴弹和工匠文书 - 瑟银手榴弹交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '这些手榴弹一定花不少钱来制作。我说的对吗，$N?', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9197, '工匠文书 - 侏儒作战小鸡', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单EN-0：$B$B4只侏儒作战小鸡。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将4只侏儒作战小鸡和工匠文书 - 侏儒作战小鸡交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '你在笑什么?有什么那么好笑?听着，$g小子:女孩;，千万不要小看地精作战小鸡，他们在战役中是多么的重要啊，因为地精作战小鸡是唯一能够在有瘟疫的环境中生存并消灭那些被传染的昆虫和瘟疫带原者，大家都知道机器人都是对疾病免疫的。$B$B我想你现在应该觉得自己没有想象中的聪明了吧，大笨蛋……', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9198, '工匠文书 - 瑟银管', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单EN-558：$B$B14根瑟银管。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将14根瑟银管和工匠文书 - 瑟银管交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '瑟银管?喔，谢谢。$B$B<军需筹备官石汉把那些瑟银管顺手丢到旁边的垃圾堆。>', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9199, '巨魔的邪符', '$C，埋葬在阿曼尼墓穴的巨魔死而复生了！我想让你去消灭他们。某些亡灵巨魔和活着的巨魔身上带着邪符，那是一种蕴含着未知能量的发光物体。我们还不确定它是否跟巨魔的复活有关……也许这就是问题的关键！$B$B阿曼尼墓穴就在此地以东的阳痕峰内。据说沿着山北面的道路可以快速到达那里。快一点，$c！', '收集8个巨魔的邪符，然后向幽魂之地塔奎林的亡灵哨兵玛尔特迪斯复命。', '木乃伊是被巨魔牧师唤醒的……真聪明!。影松巨魔一定是想透过死灵术来壮大自己的数量!我敢保证神谕者在他们的复活仪式中会使用护符。我需要确定它们被交到太阳圣所的某人手中进行研究。$B$B你再次尽了一个$C该尽的职责，提高了你的声望。请收下这个做为报酬。', '我不需要提醒你吧，$C，我们根本不能承受这大麻烦啊，你瞧我们后院这些巨魔亡灵的数量一直在增加!', '', '去找幽魂之地的亡灵哨兵玛尔特迪斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9200, '工匠文书 - 特效法力药水', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单AL-473：$B$B10份特效法力药水。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将10份特效法力药水和工匠文书 - 特效法力药水交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '这些药水的功能真的是好到无可挑剔。', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9201, '工匠文书 - 强效奥术防护药水', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单AL-1420：$B$B15份强效奥术防护药水。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将15份强效奥术防护药水和工匠文书 - 强效奥术防护药水交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '<军需筹备官石汉拿了一瓶强效秘法防护药水起来，然后一口喝下。>$B$B哇!这个还真好喝!好喝!', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9202, '工匠文书 - 特效治疗药水', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单AL-169110：$B$B20份特效治疗药水。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将20份特效治疗药水和工匠文书 - 特效治疗药水交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '你知道在前线作战的士兵给这种药水取了什么外号吗?装在瓶子里的牧师……$B$B<军需筹备官石汉开始唱歌。>“我是你瓶中的牧师……宝贝……只要你需要我就帮你治疗……”', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9203, '工匠文书 - 化石药水', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单AL-90：$B$B1份化石药水。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将1份化石药水和工匠文书 - 化石药水交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '无可奉告。$B$B<军需筹备官石汉看看了你>$B$B我都说了无可奉告了!滚出我的视线!$B', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9204, '工匠文书 - 石鳞鳗', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单FS-5：$B$B40条石鳞鳗。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将40条石鳞鳗和工匠文书 - 石鳞鳗交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '你原本可以用这些材料去做其它物品的，可是你没有，对吧?现在你想反悔也来不及了，$N。', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9205, '工匠文书 - 板鳞鱼', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单FS-12：$B$B30条板鳞鱼。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将30条板鳞鱼和工匠文书 - 板鳞鱼交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '你真的不知道这个是做什么用的?$B$B<军需筹备官石汉大笑。>$B$B别想指望我会告诉你!', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9206, '工匠文书 - 电鳗', '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单FS-9：$B$B30条电鳗。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹', '将30条电鳗和工匠文书 - 电鳗交给东瘟疫之地圣光之愿礼拜堂的马队管理器布鲁斯·石锤。', '用这些电鳗做的电鳗卷真的是全世界最好吃的食物!没错-全世界!', '完成工作令了吗，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9207, '幽光矿石样本', '我是被太阳圣殿派过来收集矿石样本的，但这里已经完全被豺狼人占据了！如果我不能马上给魔导师带去矿石，那他可就想要我的脑袋了。或许你能帮帮我，$c？$B$B你可以在这里的锡矿和铜矿上找到矿石的样本，豺狼人身上也有携带着。有了足够的矿石以后，请直接把它交给太阳圣殿的魔导师奎尔林提斯。向东走，穿过死亡之痕，你可以在阳痕峰的正南方发现太阳圣殿。', '收集6块幽光矿石，把它们交给幽魂之地太阳圣殿的魔导师奎尔林提斯。', '我的学徒无法自己处理这些东西吗?等她回来我要好好和她谈一谈，豺狼人什么的。对了，讲到这，她怎么没跟你一起回来?$B$B<博学者叹了口气。>$B$B这是个麻烦事，要适当地训练也会是个挑战。谢谢你，$C，替我带\r\n回这些样本。我们希望可以揭开他们特殊物品的神秘面纱，这样一来，对付天灾军团就更加游刃有馀了。$B$B请收下这些钱做为我感激你的奖励。', '需要帮忙吗，$C?', '', '去幽魂之地找太阳圣殿的魔导师奎尔林提斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9208, '野性戒卫 - 防护秘药', '赞扎可以使用适当的材料对你的装备进行古老的魔法增强处理！你听说过野性戒卫吗？啊，你当然没有听说过。你满脑子都是那些低级的暗夜精灵的魔法。$B$B给我拿来一份暗夜精灵的秘药，我也许能重新为你附魔。去吧，我会把野性戒卫作为奖励送给你的。', '祖尔格拉布的无眠者赞扎需要一份防护秘药。', '看到这些无用的精灵魔法让我更加的愤怒而这些愤怒也能让我获得更多的力量。$B$B再去多拿一些秘药来给我，你就能获得另一个野蛮护卫。', '拿到秘纹了吗?', '', '去找祖尔格拉布的无眠者赞扎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9209, '野性戒卫 - 急速秘药', '赞扎可以使用适当的材料对你的装备进行古老的魔法增强处理！你听说过野性戒卫吗？啊，你当然没有听说过。你满脑子都是那些低级的暗夜精灵的魔法。$B$B给我拿来一份暗夜精灵的秘药，我也许能重新为你附魔。去吧，我会把野性戒卫作为奖励送给你的。', '祖尔格拉布的无眠者赞扎需要一份急速秘药。', '看到这些无用的精灵魔法让我更加的愤怒而这些愤怒也能让我获得更多的力量。$B$B再去多拿一些秘药来给我，你就能获得另一个野蛮护卫。', '拿到秘纹了吗?', '', '去找祖尔格拉布的无眠者赞扎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9210, '野性戒卫 - 专注秘药', '赞扎可以使用适当的材料对你的装备进行古老的魔法增强处理！你听说过野性戒卫吗？啊，你当然没有听说过。你满脑子都是那些低级的暗夜精灵的魔法。$B$B给我拿来一份暗夜精灵的秘药，我也许能重新为你附魔。去吧，我会把野性戒卫作为奖励送给你的。', '祖尔格拉布的无眠者赞扎需要一份专注秘药。', '看到这些无用的精灵魔法让我更加的愤怒而这些愤怒也能让我获得更多的力量。$B$B再去多拿一些秘药来给我，你就能获得另一个野蛮护卫。', '拿到秘纹了吗?', '', '去找祖尔格拉布的无眠者赞扎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9211, '寒冰戒卫', '啊，寒冰戒卫。它可以在某些护甲表面生成稀薄的魔法保护光环。寒冰戒卫能在你遭受冰霜系的攻击时起到额外的保护作用。$B$B愤怒者玛塔乌斯的创造物总是相当昂贵的，就算你哭着求我，我也不会降价。你感兴趣吗？', '东瘟疫之地圣光之愿礼拜堂的愤怒者玛塔乌斯需要10枚十字军徽记和30金币。', '<麦特斯将金币收进口袋。>$B$B往后的修理费用可不便宜，$r。纳克萨玛斯对那些不熟悉的人可是没有那么仁慈。', '如果没有这些银色黎明的卫兵在这，我一定把你打到屁滚尿流。', '', '去东瘟疫之地找圣光之愿礼拜堂的愤怒者玛塔乌斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9213, '暗影戒卫', '天才的创造物！跟寒冰戒卫类似，暗影戒卫可以在某些护甲表面生成稀薄的魔法保护光环。当然，暗影戒卫跟寒冰戒卫一样价值不菲。$B$B<玛塔乌斯搓着手。>$B$B你感兴趣吗？', '东瘟疫之地圣光之愿礼拜堂的愤怒者玛塔乌斯需要10枚十字军徽记和30金币。', '<麦特斯将金币收进袍内。>$B$B你还站在这做什么，$r? 我们的交易已经结束了。', '<施怒者麦特斯大吼>$B$B滚开，无知的人，除非你有我需要的东西。', '', '去东瘟疫之地找圣光之愿礼拜堂的愤怒者玛塔乌斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9214, '暗松巨魔的武器', '$c，我需要你尽可能杀死更多的暗松巨魔。我们必须大大削减他们的人数，才能把主力部队调往戴索姆。另外，别忘了在清理巨魔的时候顺便把他们的武器给我拿回来，与其让巨魔浪费掉这些武器，还不如让我们的士兵拿着它们作战，这是一石二鸟之计。$B$B他们的营地就在东边和南边的塞布提拉和塞布努瓦。', '收集3把猎头者战斧、3把暗影施法者钉锤、3只驭豹者之爪和3根妖术师法杖，然后向远行者营地的赫里奥斯中尉复命。', '我会立刻派一些巡逻兵去调查你对影松巨魔造成的伤害。我相信不用多久，我们就可以在你的攻击之后向天灾军团进攻，拿着你成功取回的武器而大获全胜。$B$B拿着，我要你收下这枚硬币当作谢礼，反正我的钱包也满到快装不下了。', '你拿到他们的武器了吗?等影松巨魔的实力被削弱了以后，我们终于可以转移目标对付天灾军团。', '', '去幽魂之地找远行者营地的赫里奥斯中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9215, '克尔加什的徽记！', '悬赏：将暗松巨魔酋长克尔加什的徽记交给赫里奥斯中尉。不要问任何其它问题。根据当前的情报，克尔加什居住在塞布努瓦南部某处。$B$B$B$B奖励：有奖励，但无预付！', '将克尔加什的徽记交给远行者营地的赫里奥斯中尉。', '啊，原来那颗头颅就是恶臭冲天的东西。做的好，$C!$B$B一旦他们的头目死了，影松巨魔就会陷入一片混乱。加上我们最近致力于削弱他们的势力，这应该是个完美的反击时机。$B$B谢谢你，$N。我可以给你一点奖励吗?', '这可怕的味道是什么啊?', '', '去幽魂之地找远行者营地的赫里奥斯中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9216, '腐烂精华', '我听说阿曼尼巨魔认为吃下敌人的精华可以获得他们的力量。$N，这种巨魔的习俗也许并非只是迷信。经过适当的处理，亡者的精华可以被制成各种强效的药剂。$B$B杀掉死亡之痕的食尸鬼，把他们的精华带回来。我会为你配制一份药剂，提高你对亡灵的物理攻击力。', '将10颗腐烂的精华交给塔奎林的魔导师艾米妮尔。', '拿着这个药水，$N。喝下之后，它将给你强大的力量去对付天灾军团。如果你又有大量的腐烂之心，要记得通知我。', '你有带回我要的腐烂之心吗，$N?', '', '去幽魂之地找塔奎林的魔导师艾米妮尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9217, '更多腐烂精华', '', '', '这将能替你增强魔法能量来对付天灾军团。多带一些腐烂之心回来吧，$N。', '你有更多的腐烂之心吗?你有多少，我就用多少，$N。', '', '去找幽魂之地的魔导师艾米妮尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9218, '脊骨之尘', '黑暗的能量在复苏的骷髅体内涌动着，并聚集在它们的脊骨中。我发现，若是在药水中注入这种能量，饮用后可以提高我们对亡灵的魔法攻击力。$B$B将脊骨之尘带回来，我就给你配制一份药水。去西边的死亡之痕吧，那儿聚集着大量的骷髅。', '将10份脊骨之尘交给塔奎林的魔导师艾米妮尔。', '收下这个，$N。你会立刻感觉到不同!$B$B多带一些脊骨之尘回来;你有多少我就能用多少。副作用?你可能会觉得你的关节开始出点毛病。没有永久的影响，我保证!', '你有带回我要的样本吗，$N?', '', '去幽魂之地找塔奎林的魔导师艾米妮尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9219, '更多脊骨之尘', '', '', '这些粉末有着强大的能量，$N。如果你想增加你的魔法力量来对抗天灾军团的话，那就持续把它带来给我。', '你有更多的脊骨之尘吗?你有多少，我就用多少。', '', '去找幽魂之地的魔导师艾米妮尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9220, '戴索姆之战', '如果你想要伸出援手，现在正是时候。$B$B我们最近重建了太阳圣殿，并正式向戴索姆的敌军宣战。$B$B转至那座天灾军团的要塞，英勇作战吧。', '转至戴索姆杀死5个达尔坎之眼、6个蛛怪百夫长和6个恸哭者，然后向幽魂之地太阳圣殿的魔导师伊东尼斯复命。', '天灾军团深切感受到我们的狂怒，$N。他们被诅咒的要塞很快就要失陷了。$B$B随着他们数量的减少，该是时候发动一场战斗攻击更多重要的目标。', '你战胜死亡之域了吗，$N?', '', '去幽魂之地找太阳圣殿的魔导师伊东尼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9221, '精良的作战装备 - 银色黎明友善', '朋友，你好。你想要用银色黎明徽记或十字军徽记换取这些物品吗？$B$B我得提醒你，如果你在银色黎明的声望只达到友好的话，这笔交易可是要收取很高的附加费的。我建议你跟银色黎明创建更高的声望之后再实施你的计划。', '如果你有30枚银色黎明徽记和30枚十字军徽记，就能从银色黎明的宝藏中挑选一件物品。', '祝你有个美好的一天，$N，很高兴和你做生意。', '小心选择，这可是没办法退货的。', '', '去东瘟疫之地找圣光之愿礼拜堂的军需官米兰达·布利洛克。', '', '', '', '');
