INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9225, '史诗级的作战装备 - 银色黎明崇敬', '朋友，你好。你想要用银色黎明徽记或十字军徽记换取这些物品吗？$B$B我得提醒你，就算你在银色黎明的声望达到崇敬，购买史诗级物品仍然相当昂贵。我建议你跟银色黎明创建更高的声望之后再实施你的计划。', '如果你有45枚银色黎明徽记和45枚十字军徽记，就能从银色黎明库存的宝藏中挑选一件物品。', '祝你有个美好的一天，$N，很高兴和你做生意。', '小心选择，这可是没办法退货的。', '', '去东瘟疫之地找圣光之愿礼拜堂的军需官米兰达·布利洛克。', '', '', '', '');
