INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9228, '史诗级的作战装备 - 银色黎明崇拜', '朋友，你好。你想要用银色黎明徽记或十字军徽记换取这些物品吗？$B$B如果你在银色黎明的声望达到崇拜的话，我们会给你最低的折扣！我建议你现在就购买吧！', '如果你有27枚银色黎明徽记和27枚十字军徽记，就能从银色黎明库存的宝藏中挑选一件物品。', '祝你有个美好的一天，$N，很高兴和你做生意。', '小心选择，这可是没办法退货的。', '', '去东瘟疫之地找圣光之愿礼拜堂的军需官米兰达·布利洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9229, '拉玛兰迪的命运', '拉玛兰迪是兄弟会的一名战士，早在银色黎明成立之前他便是莫格莱尼阁下的学生了！当莫格莱尼的死讯传来时，仇恨和愤怒充斥着他的心灵。$B$B试想一下吧，$N，一个被复仇的怒火占据了心灵的人还能算个人吗，无非是个被情绪操控的傀儡。拉玛兰迪在盛怒之下冲进了纳克萨玛斯的宫殿，想为恩师报仇……可惜是肉包子打狗。$B$B转至纳克萨玛斯的宫殿打探拉玛兰迪的下落吧。', '进入纳克萨玛斯的宫殿，找到拉玛兰迪的下落。', '这就是他的戒指没错!不过光芒却已不在。你还有找到其它罗马拉丁尼的物品吗?$B$B<柯菲斯露出痛苦的表情。>$B$B这样看来罗马拉丁尼应该是凶多吉少了。不过这戒指……应该还能恢复他原有的光芒。', '有罗马拉丁尼的消息吗?', '', '去找东瘟疫之地的科尔法克斯，圣光之勇士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9230, '拉玛兰迪的寒冰之握', '要修复这枚戒指可不是件容易的事儿，$N。瞧，它的原材料是取自天灾建筑物中形成的冰冻符文，例如纳克萨玛斯的宫殿。当然我还需要其它材料，但是你的主要任务就是找到冰冻符文。把我所需的材料拿来，我会让这枚戒指重新恢复光泽的。', '东瘟疫之地圣光之愿礼拜堂的科尔法克斯要1个冰冻符文、1块蓝宝石和1块奥金锭。', '就连罗马拉丁尼他自己也不可能做的比这个更完美!就像我所承诺的，我已经把这颗戒指恢复了他原有的光芒甚至更好，希望他能给你更多的帮助。', '在纳克萨玛斯里应该可以找到冰冻符文。', '', '去找东瘟疫之地的科尔法克斯，圣光之勇士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9232, '我只会唱这一首歌……', '你自诩为银色黎明的英雄，是吗？克尔苏加德手下的小喽啰能轻松砍翻我军最优秀的士兵，这是我亲眼所见！像你这样的蠢货还想去纳克萨玛斯的宫殿？$B$B<威尔海姆叹了一口气。>$B$B呸，我还能有什么选择？你是我惟一的希望；我或许能帮上忙。$B$B“奥玛里恩悄悄地走，除了一份图样，他什么都没留……”，我只会唱这一首歌……嗯，我可以为你制作一条很棒的裤子，但是你得为我提供材料。', '将2个冰冻符文、2个水之精华、2块蓝宝石和30金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。', '<维尔海姆擦了一下额头上的汗。>$B$B呼，制作这件束裤比我想象中的难!希望这束裤能帮上你的忙，$C。', '你还没见过工匠大师欧玛利安，对吧?', '', '去东瘟疫之地找圣光之愿礼拜堂的工匠威尔海姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9233, '奥玛里恩的手册', '威尔海姆：$B$B当你翻阅这本手册时，我已经咽气了——这对我来说是个解脱。我想告诉你，我临死前还想着你和你那糟糕的商业头脑。不幸的是，就工匠技能来说，送手册给你的家伙连你都不如。$B$B这本手册记载了我生前研制的配方，可以让手册的持有者制造出任何他们想要的东西。我想你一定会向别人收取高额费用的，因为你就是这么个混帐。$B$B我鄙视你，$B$B奥玛里恩', '将奥玛里恩的手册交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。', '他在纂写这本手册的时候一定是发疯了吧!我和欧玛利安－我们可是贼世至尊呢!$B$B总而言之，这也为我们开创了新的契机，$N。我现在可以制造更多新样式的物品了－当然，要付一点工资和材料费。', '这跟我想的是一样的吗?$B$B<维尔海姆流口水貌。>', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9234, '破冰护手', '感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作破冰护手了。你要做的只是为我提供材料，并支付一笔小小的加工费。', '将5个冰冻符文、12块瑟银锭、2块奥金锭、2个水之精华和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。', '这是你要求的东西，$N。依约抵达!', '你有带材料来吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的工匠威尔海姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9235, '破冰护腕', '感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作破冰护腕了。你要做的只是为我提供材料，并支付一笔小小的加工费。', '将4个冰冻符文、12块瑟银锭、2块奥金锭、2个水之精华和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。', '这是你要求的东西，$N。依约抵达!', '你有带材料来吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的工匠威尔海姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9236, '破冰胸甲', '感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作破冰胸甲了。你要做的只是为我提供材料，并支付一笔小小的加工费。', '将8个冰冻符文、16块瑟银锭、2块奥金锭、4个水之精华和300金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。你在银色黎明的声望必须达到崇拜。', '这是你要求的东西，$N。依约抵达!', '你有带材料来吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的工匠威尔海姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9237, '冰川披风', '感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作冰川披风了。你要做的只是为我提供材料，并支付一笔小小的加工费。', '将5个冰冻符文、4个符文布卷、2个水之精华、4个铁网蛛丝和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。你在银色黎明的声望必须达到崇拜。', '这是你要求的东西，$N。依约抵达!', '你有带材料来吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的工匠威尔海姆。', '', '', '', '');
