INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9242, '北极手套', '感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作北极手套了。你要做的只是为我提供材料，并支付一笔小小的加工费。', '将5个冰冻符文、12个魔化皮、3个水之精华、3个熟化毛皮和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。', '这是你要求的东西，$N。依约抵达!', '你有带材料来吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的工匠威尔海姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9243, '北极外套', '感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作北极外套了。你要做的只是为我提供材料，并支付一笔小小的加工费。', '将8个冰冻符文、16个魔化皮、5个水之精华、5个熟化毛皮和300金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。你在银色黎明的声望必须达到崇拜。', '这是你要求的东西，$N。依约抵达!', '你有带材料来吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的工匠威尔海姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9244, '寒鳞护腕', '感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作寒鳞护腕了。你要做的只是为我提供材料，并支付一笔小小的加工费。', '将4个冰冻符文、16片厚蝎鳞、5个水之精华、3个熟化毛皮和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。', '这是你要求的东西，$N。依约抵达!', '你有带材料来吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的工匠威尔海姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9245, '寒鳞护手', '感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作寒鳞护手了。你要做的只是为我提供材料，并支付一笔小小的加工费。', '将5个冰冻符文、16片厚蝎鳞、5个水之精华、3个熟化毛皮和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。', '这是你要求的东西，$N。依约抵达!', '你有带材料来吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的工匠威尔海姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9246, '寒鳞胸甲', '感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作寒鳞胸甲了。你要做的只是为我提供材料，并支付一笔小小的加工费。', '将8个冰冻符文、24片厚蝎鳞、7个水之精华、5个熟化毛皮和300金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。你在银色黎明的声望必须达到崇拜。', '这是你要求的东西，$N。依约抵达!', '你有带材料来吗?', '', '去东瘟疫之地找圣光之愿礼拜堂的工匠威尔海姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9248, '谦卑的馈赠', 'Ishnu-alah，$R。让我看看能证明你杀死深渊议会领主的证据，我就奖励你一件好东西，它能在你与其拉虫人作战时帮你一臂之力。', '将一根深渊节杖交给希利苏斯塞纳里奥要塞的奥蕾尔·金叶。你在塞纳里奥议会的声望必须达到尊敬。', '安德索拉斯-尔西斯，在我母语里的意思是代表“愿你的烦恼减至最低”。$B$B骄傲地戴上戒指，保佑你健健康康，$N。', '(达纳苏斯语)报上名来?喔，请原谅我，$N。我没有认出你来。你拿到权杖了吗?', '', '去希利苏斯找塞纳里奥要塞的奥蕾尔·金叶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9249, '40张奖券 - 高级奖品', '', '', '拿去吧，拿去吧!一个最适合$g国王:皇后;的奖品!恭喜你，我的朋友!$B$B如果你有更多奖券想要兑换，请告诉我!只要暗月马戏团还在这里，我就会兑换你的奖券。', '靠过来，靠过来!如果你想要兑换暗月马戏团奖券，尽管开口吧!你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧!', '', '去找吉瓦斯·格里加特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9250, '埃提耶什之杖', '合成杖柄之后，从形状上来看，守护者的传说之杖埃提耶什只差法杖顶部和杖柄末端两个部分了。还有个小问题就是：这根杖子蕴涵着萨格拉斯的邪恶力量。$B$B看看有谁能帮你找到残馀的法杖碎片并且净化那些邪恶的力量。', '看看有谁能帮你找到法杖的最后两个部分，并且净化邪恶的力量。', '大法师已经死了。$B$B别为他们的死而哀伤，$N。这一切都是命。就好像你手握守护者之杖也是命中注定……', '她的时辰到了，凡人。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9251, '埃提耶什，被玷污的传说之杖', '你很困惑为何自己还活在世上吧。毕竟，你拥有这么一件邪恶的物品。没有确切的答案，$N。我只是做我应该做的事儿罢了。$B$B克尔苏加德就在纳克萨玛斯宫殿的王座上策划着某个阴谋……他要找的东西在你手中，而你要找的东西在他手中。$B$B一位名叫布莱恩·铜须的矮人曾携带杖柄的末端进入安其拉，却不小心将它遗失在了安其拉里面。$B$B一旦你成功拿到杖柄末端，就立即来找我吧。', '塔纳利斯时光之穴的阿纳克洛斯要你找到埃提耶什的法杖顶部和埃提耶什的杖柄末端。', '里面有一个东西……一个不存在于世界上的东西。', '以现状来看，法杖落在人类手上实在是太危险了。', '', '去塔纳利斯找时光之穴的阿纳克洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9252, '保卫晴风村', '$N，亡灵天灾的攻击愈发频繁，晴风村薄弱的防御力量已经有些捉襟见肘了，而银月城的援军又迟迟没有消息。死亡之痕里到处都是天灾军团的士兵，去帮我们削减它们的数量吧。', '杀死4个腐肢劫掠者和4个黑暗怨灵，然后向永歌森林晴风村的游侠萨蕾恩复命。', '非常感谢，$N。这是个吃力不讨好的工作，但今天有你帮忙，实在是让这工作轻松不少。', '我们会战胜的，$N。', '', '去找永歌森林晴风村的游侠萨蕾恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9255, '研究笔记', '虽然研究结果令人气馁，但是我在研究笔记中记录的数据还是很有价值的。我想听听导师对这些数据的意见。到西边的晴风村去，把笔记交给魔导师兰德拉·晨行者。', '将研究笔记交给永歌森林晴风村的魔导师兰德拉·晨行者。', '这份资料……令人震惊。如果它们是正确的，表示死亡之痕的伤害是无法补救了。$B$B我会立刻通知大博学者。有更多的理由要让我们的种族逃离这个世界并了解在外域中的真正命运。', '你有东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9259, '血帆海盗的叛徒', '', '', '让我们为这些阵亡的朋友哀悼，$N。$B$B<血帆背叛者对你咧嘴笑了笑，使了个眼色。>$B$B当一个背叛者是一回事，杀死你自己的兄弟……那才是真正可鄙的事!', '里维加兹那个肮脏的家伙已经饶恕了所有愿意改过自新的血帆!那船底的人渣要我去杀了其它的人并把他们的面罩带回来做为证据。$B$B我不想这么做，所以也不会叫你去做。帮我带来一些丝绸和红色染料，我就能制作合适的复制品。我会跟男爵说你变节了，但是请小心……血帆不会喜欢这个主意的!', '', '去找荆棘谷的血帆叛徒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9266, '痛改前非', '', '', '谢谢你，$N。你很快就重拾我们城镇对你的好感了。', '你一定是对我们或我们的朋友做了什么可怕的事，$N。无论如何，我是来提供你一个方法赢回我们的好感。$B$B你知道，冬泉谷还满冷的。我们有这么多的哥布尔从别的城市过来，需要一些帮忙来保持温暖。帮我带一些符文布和煤炭来我就会帮你说点好话。不过要小心，我们的敌人不会对你的帮忙产生好感的。', '', '去找冬泉谷的布隆恩·菲兹维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9267, '抚平旧伤', '', '', '我很高兴你这样弥补自身的过错，$N。继续将物资送来;我们不会那么容易忘记你的，先生!', '你在到达棘齿城之前要考虑清楚，$N!到处都传言着你的肮脏行为。$B$B不过你运气不错，刚好有一艘和血帆海盗交战过、载满伤者的船只抵达。这是你证明自己不是彻底的坏蛋的机会。帮我们把制作绷带的亚麻布和装药水的空瓶子拿来。', '', '去贫瘠之地找棘齿城的穆普斯·沙克菲德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9268, '海上的战争', '', '', '继续保持，$N。我们哥布尔没那么健忘!', '你想再次与塔纳利斯的哥布尔交朋友吗，$N?我们正需要航海的材料和击败旧仇血帆海盗的枪枝。帮我把魔纹和强效助熔剂拿来，我们就能赦免你的罪过。', '', '去找塔纳利斯的卢森·费兹布拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9274, '水中鬼魂', '$N，从我记事起，北边的湖泊就一直有先祖的鬼魂出没。那是一场悲惨的灾难，很多人被活活溺死，他们的灵魂仍在世间飘荡。$B$B虽然族人们对那场灾变的记忆已经模糊，但是湖边凄凉的哭泣声似乎在述说着他们被诅咒的命运。$B$B$N，如果你愿意接受这项任务，就去湖边结束他们的痛苦吧。我想……他们和我都会感激你的。', '在附近的湖泊周围杀死8个复仇的幽灵和8个贪婪的幽灵，然后向远行者营地的游侠克雷安复命。', '我感谢你的帮助，$N。看到祖先们的灵魂处于那样可怜的状态我就很痛苦。愿他们终于获得应得的安息。', '你完成了我要你做的事吗，$N?', '', '去幽魂之地找远行者营地的游侠克雷安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9275, '香料', '我奉命从塔奎林来到远行者营地对付巨魔，而且我很快就想到了一个好法子。$B$B炼制一批强效毒药对我来说容易得很。你知道，巨魔这种生物总归要进食的吧，如果在他们的食物中投毒……唔，那一定非常有趣！$B$B你愿意帮我们消灭南面塞布努瓦的暗松巨魔吗？他们的营地分布在通往祖阿曼的道路的南北两侧。', '转至塞布努瓦的巨魔营地，给他们的食物中投毒，然后向远行者营地的药剂师温努图斯复命。', '啊，太棒了!我就知道$r-运输系统使用毒药最有效率。幸运的话影松巨魔会吃过量有毒的食物。这样应该能让这些巨魔远离远行者也能让我回到塔奎林去。$B$B和你合作很愉快，$C。', '我相信你已经到札布诺瓦的巨魔营地并在他们的食物里动了手脚吧，$C?', '', '去找远行者营地的药剂师温努图斯。', '给生肉架投毒', '给熏肉架投毒', '给鲜鱼架投毒', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9276, '进攻塞布提拉', '$c，远行者营地的兵力相当分布，我们迫切需要你的帮助。我奉命骚扰附近的暗松巨魔营地。根据作战计划，不能让暗松巨魔有任何喘息的机会，要闹得他们不得安宁，然后再伺机发动反攻，将这帮家伙统统消灭。$B$B因此，我们需要所有冒险者伸出援手，帮我们削减巨魔的数量。$B$B你愿意转至东边的塞布提拉，给巨魔们一点苦头吃吗？', '杀死8个暗松影法师和8个暗松猎头者，然后向远行者营地的远行者索兰娜复命。', '很好，很好!你处理的非常好，让我们来看看你能否接下更困难一点的任务。', '你在札布泰拉的攻击行动进行的怎么样了?', '', '去幽魂之地找远行者营地的远行者索兰娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9277, '突袭塞布努瓦', '接下来的这项任务稍微有点挑战性。南边的塞布努瓦聚集了一批更强的暗松巨魔。我们要继续削减巨魔的数量；因此，我派你转至塞布努瓦对付暗松巨魔，随便你用什么方法，杀死他们就成。$B$B$N，怎么样？你准备好了吗？', '杀死10个暗松驭豹者和10个暗松妖术师，然后向远行者营地的远行者索兰娜复命。', '不可思议!你真的应该和队长谈谈加入远行者的事!$B$B好了，$N，你已给了我们需要的空间喘口气，继续增强我们的军力。事实上，依据你的估计根本没有那么多巨魔!或许我们现在可以加入塔奎林攻打死亡之域的行列?$B$B我想你有获得一些经验吧。拿去，这是你的奖赏。', '你在札布诺瓦的攻击完成了吗?', '', '去幽魂之地找远行者营地的远行者索兰娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9278, '欢迎！', '欢迎来到魔兽世界！$B$B为了感谢您购买魔兽世界典藏版，请将这张礼券交给碧蓝岗哨的亚埃雷尔。您将得到一份特别的礼物：陪伴您踏上冒险旅途的小宠物！$B$B再次感谢您的支持，请尽情享受魔兽世界的乐趣吧！', '将碧蓝岗哨礼品券交给碧蓝岗哨的亚埃雷尔。', '您一定会成为一个真正的英雄，$N。欢迎您来到艾泽拉斯世界，请从我们为您精心准备的特殊礼品中挑选一件吧!', '您好!很高兴见到您!$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9280, '补充治疗水晶', '我们当前最紧迫的问题就是，治疗水晶的存量已经几乎为零了。我们必须立刻补充这种水晶。$B$B但糟糕的是，当前补充水晶的唯一可行办法就是从周围的蛾类生物血液中分解出有用的物质，因为它们的血液中含有某种非常合适的替换品。$B$B这些蛾类生物在谷中遍地都是，西北方更加集中一些。', '从附近的峡谷蛾身上取得8瓶蛾血，然后将它们交给埃门谷坠毁点的普罗尼图斯。', '令人遗憾的，那些生物必须死亡我们才能生存 - 不分青红皂白的杀戮不是我们德莱尼人的作风。不过，你所收集的血清会补充我们的治疗水晶，所以他们不会死得毫无价值。$B', '你弄到治疗水晶必要的飞蛾血清了吗?溪谷里到处都是生还者，时间紧迫!', '', '去埃门谷找坠毁点的普罗尼图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9281, '清理道路', '魔导师坎迪瑞斯派我来这里猎杀那些具有攻击性的野生动物。如果能解除这些家伙构成的威胁，我们就准备在这块地方创建一座前哨站，监视亡灵天灾的动向。$B$B要说我在做学徒时学会了什么诀窍，那就是把事情委托给别人来做——尤其是那些有生命危险的事情！$B$B如果你感兴趣的话，就去西边和南边猎杀巨型纺丝蜘蛛和鬼爪破坏者，我会给你一笔不小的报酬。', '杀死10只巨型纺丝蜘蛛和10只鬼爪破坏者，然后向幽魂之地安迪尔林庄园的学徒沃尔伊复命。', '谢谢你帮我的忙，$N。想到要冒险通过离死亡之域这么近的树林真是令人害怕。', '你完成了我要你去做的任务吗，$N?', '', '去幽魂之地找安迪尔林庄园的学徒沃尔伊。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9283, '拯救幸存者！', '治疗水晶终于补足了，但这不是我们唯一的帮助伤者的方式。所有德莱尼人都曾受到过纳鲁的赐福，得到了治疗的能力。$b$b你一定要善用这种能力去帮助幸存者。$b$b在这里的西边和西北边，你会发现大量的幸存者，埃索达坠毁时，他们跳船逃生，散落在了谷中。$b$b这些幸存者大多是被能量水晶的辐射严重灼伤，所以你可以通过包围着他们躯体的红光发现他们。$B$B你一定要赶快救救他们，$N。', '使用你的“纳鲁的赐福”这一能力拯救埃门谷中的任意一名德莱尼幸存者，然后向埃门谷坠毁点的扎尔杜复命。', '赞美圣光!你完成了一个真正的$g英雄:女英雄;会做的事，$N!你拯救的那个德莱尼，能够延续生命，都靠你无私的奉献!$B$B请收下这个补给包。你看起来比我需要它。', '有你的帮忙我们会安然度过!', '', '去埃门谷找坠毁点的扎尔杜。', '拯救德莱尼幸存者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9292, '破碎的死灵水晶', '你在憎恶的尸体上找到一块散发着腐坏能量的破碎水晶。', '将破碎的死灵水晶交给暴风城门外的奥林中尉。', '嗯，你从一具受到憎恨侵袭的尸体身上取得这项物品?$B$B我们已听说天灾军团召唤亡域基础营地的事。我猜他们想在暴风城里也造一个。很好，这样他们就等着迎接失败吧。', '你需要协助吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9293, '必需的措施……', '有一块从船体中脱离出来的能量水晶掉落入了附近的一处湖泊中，污染了湖水。埃门谷中的许多植物与动物都因此而受到了辐射的影响，产生了变异。$B$B我当前构思出了一个方法，或许可以消除湖水的污染，但我必须首先进行一些分析实验，这需要一些变异鞭笞者的样本进行分析。在西边的埃门平原一带就可以找到这些变异生物。$B$B你愿意帮我采集一些样本回来吗，$c？', '收集10份鞭笞者样本，把它们交给埃门谷坠毁点的植物学家塔蕾克丝。', '这些样本很不错。谢谢你，$C!$B$B你出去的时候，我设法找到了一些器材来分析样本。应该不会花太久的时间。', '如果我们要净化湖水，我就需要那些样本保持在良好状态。我知道你能胜任这个挑战，$C，如果我之前太歇斯底里，我很抱歉。$B$B我们没有多少时间了，$C!', '', '去找埃门谷坠毁点的植物学家塔蕾克丝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9294, '净化湖水', '谢天谢地，我想这应该是有效的！我现在给你一份中和媒介，你要将它洒在南方的银链湖中。它将中和能量水晶所产生的辐射效果。$B$B到了湖边之后，你需要游进湖里去，将中和媒介倒在水晶周围。不用担心，你不会在辐射下暴露很长时间的。', '将中和媒介散布在辐射能量水晶旁，然后向埃门谷坠毁点的植物学家塔蕾克丝复命。', '从你所描述的听来，中和剂发挥作用了!我只希望我能知道它会维持多久;我们真的需要把那个能量水晶从湖里整个删除。$B$B谢谢你，$N!我会要泰德昂立刻在俘虏的野兽身上试试中和剂。', '你越快将中和剂散播在湖里，就会有越少的生物因为喝了湖水而产生突变，包括我们!$B$B很遗憾我们对已经被感染的生物束手无策。要是我的实验器材还完整就好了。', '', '去找埃门谷坠毁点的植物学家塔蕾克丝。', '散布中和媒介', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9299, '潦草的便笺', '你在某个天灾士兵的尸体上找到了这封信。破旧发黄的信纸散发着霉臭，看来它在亡灵手里已经有些日子了。或许圣光之愿礼拜堂的家伙会对此感兴趣的……', '将潦草的便笺交给东瘟疫之地圣光之愿礼拜堂的名单登记员。', '多悲哀啊\r\n。这些话语，清楚的是要传达给某个士兵深爱的人，只是它永远也到不了目的地了。里面写的事情是多年前发生的;我不确定原本的收件者是否还活着。$B$B不过，还是有希望。有他写的名字和讯息，我大概可以找到那户人家 !需要一点时间调查，不过暴风城的图书馆员还欠我个人情……$B$B谢谢你把这个带来给我。有你的帮忙，我们终于能让某人的心灵得到平静。', '什么事吗?你手里拿着的是什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9301, '浸血的信封', '你在某个天灾士兵的尸体上找到了这封信。破旧发黄的信纸散发着霉臭，看来它在亡灵手里已经有些日子了。或许圣光之愿礼拜堂的家伙会对此感兴趣的……', '将浸血的信封交给东瘟疫之地圣光之愿礼拜堂的名单登记员。', '多悲哀啊。这些话语，清楚的是要传达给某个士兵深爱的人，只是它永远也到不了目的地了。里面写的事情是多年前发生的;我不确定原本的收件者是否还活着。$B$B不过，还是有希望。有他写的名字和讯息，我大概可以找到那户人家 !需要一点时间调查，不过暴风城的图书馆员还欠我个人情……$B$B谢谢你把这个带来给我。有你的帮忙，我们终于能让某人的心灵得到平静。', '什么事吗?你手里拿着的是什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9303, '疫苗', '沙娜安需要我们帮她回收一些埃索达的零件。塔蕾克丝准备了一个接种装置，它可以让生活在附近这片地区的木巢枭兽得到拯救。$B$B你只需靠近那些尚未被辐射影响到的枭兽，然后对它们使用这枚水晶就可以了。而那些已经被辐射影响的枭兽……很遗憾，你只能杀死它们。到东南方的木巢山去，枭兽们就居住在那里的木巢林地中。', '对6只木巢枭兽使用疫苗水晶，然后向埃门谷坠毁点的守备官奥达尔复命。', '现在许多的枭兽都被注射了，我们就可以专心想办法离开这里而不用担心消减这里的枭兽总数。$B$B来，从这些东西里选一个。你做的很好，值得被奖励!', '我们越努力把奈斯特清理干净，就能越快让萨那开始动工 。', '', '去埃门谷找坠毁点的守备官奥达尔。', '给木巢枭兽接种疫苗', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9304, '肮脏的信', '你在某个天灾士兵的尸体上找到了这封信。破旧发黄的信纸散发着霉臭，看来它在亡灵手里已经有些日子了。或许圣光之愿礼拜堂的家伙会对此感兴趣的……', '将肮脏的信交给东瘟疫之地圣光之愿礼拜堂的名单登记员。', '多悲哀啊。这些话语，清楚的是要传达给某个士兵深爱的人，只是它永远也到不了目的地了。里面写的事情是多年前发生的;我不确定原本的收件者是否还活着。$B$B不过，还是有希望。有他写的名字和讯息，我大概可以找到那户人家 !需要一点时间调查，不过暴风城的图书馆员还欠我个人情……$B$B谢谢你把这个带来给我。有你的帮忙，我们终于能让某人的心灵得到平静。', '什么事吗?你手里拿着的是什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9305, '备用零件', '我们最近成功地从坠毁地区回收了一个已经损坏的全息图象发射器。如果我们能把它修好，就有机会找到其它在埃门谷之外的幸存者了。$B$B埃索达坠毁时，有些备用零件也散落出了船外。本来我们可以迅速回收的，可它们现在被这一地区的枭兽全部运走了。$B$B$N，你必须立刻到南方的木巢林地和木巢山去，回收那些备用零件。', '收集4份发射器备用零件，然后向埃门谷坠毁点的技师沙娜安复命。', '让我看看那些东西。$B$B很好，我想这些会很有用;做的好，$N。这个发射器相当复杂所以需要花点时间来完成修补。准备好后我会告诉你。$B$B在这同时，你可以去找复仇者艾德看看他是否需要你的协助。', '等我们收集完那些备用零件，我相信我们就能修好这个发射器。幸运的话，还可以跟留在那边的人谈话。', '', '去埃门谷找坠毁点的技师沙娜安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9311, '血精灵间谍', '我有一个计划，我们必须杀死他们的领袖。没有了领袖，他们也许就会立刻撤退并重组，这样我们就获得了修复装置的宝贵时间。$b$b守备官奥达尔应该明白这一点。杀死血精灵的测量员，然后向他报告我们发现的一切。', '杀死测量员卡蒂瑞丝，并把这个消息通知给埃门谷坠毁点的守备官奥达尔。', '感谢你解决掉血精灵勘测员。想必她就是他们的领导者。放心，我们会处理仍留在这附近的其它人。$B$B请选择一项武器做为我答谢你的奖赏。', '那么那是真的……埃门谷这里有一批侦察血精灵小队!他们怎么跟踪到我们的?$B$B我要立刻派个人去把托兰带回来!', '', '去埃门谷找坠毁点的守备官奥达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9315, '阿诺克苏塔', '靠近一点，我就要……死了。$B$B我奉命来这儿……猎杀蛛怪，但是范迪瑞尔还不知道……这里有一个蛛怪的领袖。$B$B<垂死的血精灵咳出一大口鲜血。>$B$B你必须……杀死阿诺克苏塔。最好叫上你的伙伴。那家伙在日冕村……附近游荡。', '杀死阿诺克苏塔，然后向幽魂之地塔奎林的奥术师范迪瑞尔复命。', '我为我错误的情报道歉，$C。如果我事前知道有这个安罗科舒顿，我一定会告诉你。我们的力量太单薄，消息总会从隙缝中溜走!', '一个奈幽蛛怪领袖?没有任何侦察报告提到关于这个安罗科舒顿的事!', '', '去幽魂之地找塔奎林的奥术师范迪瑞尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9319, '黑暗中的光明', '我们不是这世界上唯一庆祝这个节日的人， $n。所有种族，所有文化，都曾为火焰的寓意所深深触动。即使是在这世界上最阴暗、最寒冷的处所，仍有明亮的火焰在跳动。$b$b如果你想自己证实这一点，就到那些地下城里去看看吧。去看看通灵学院、斯坦索姆、黑石塔和厄运之槌厅堂内的篝火，我会在这里等你回来的。', '找到并碰触在黑石塔、厄运之槌、通灵学院和斯坦索姆内的火盆，并回到节日护火者处。', '你的本质和你所找到的火焰能量共鸣着，$N。你找到的火焰相当强大，只需要正确地处理，就能增强它的力量……$B$B<老者对着空气中低语，然后拿出一个发光的瓶子。>$B$B啊!好了。不管你往何处去，愿它照亮你的道路。', '你找到你在黑暗中的路了吗?', '', '去找大地之环长者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9322, '卡利姆多的野火', '艾泽拉斯世界上的每一处地方都会庆祝仲夏的来临，广袤的卡利姆多大陆也是如此，或许你会有兴趣那那边看一看。$b$b若你没有真正地感受过那些熊熊燃烧着的火焰，那么你是无法彻底了解仲夏的。庆祝者已经在寒冷的冬泉谷西部、艾萨拉东北部、希利苏斯废土上的勇士之墓附近，以及富饶美丽的安戈洛环行山入口处都点起了火焰，去看看吧。你的旅程结束以后，别忘了回来找我。', '造访艾萨拉、希利苏斯、安戈洛环行山和冬泉谷的仲夏庆典营地，然后回到节日护火者处。', '你的精神闪耀着卡利姆多火焰温暖的光，朋友。热度不够鼓舞你吗?$B$B一旦力量从你身上褪去，或许这些能够帮你重新振作感觉。', '卡利姆多的火焰烧地旺吗?', '', '去找节日护火者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9323, '东部王国的野火', '我们的庆典已经在全世界展开了，$c。几乎每一处地方都已经点燃了圣火，在节日光辉的照耀之下，强大的火焰映射着明亮的蓝天。去寻找它们吧。$b$b有一处就在黑石塔的北方。其它的火焰，有的在东瘟疫之地一处衰败的城镇前，有的在辛特兰悬崖的路旁，还有在诅咒之地的黑暗之门附近。$b$b去寻找它们吧，旅程结束后回来找我。', '造访诅咒之地、东瘟疫之地、辛特兰和灼热峡谷的火焰节营地，然后回到节日护火者处。', '啊，你来了。有点疲倦，有点脏乱，但是很有知识!热情在这个季节都深触我们的心并让我们团结在一起;你的人也和你所触摸的火焰一起发光发热。$B$B啊，但是这年头教化已经不是出任务很好的奖励了，我想。收下这些，然后，尽情在庆典上玩乐吧。', '你在大陆上旅行了吗?启蒙等待着你。', '', '去找节日护火者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9324, '盗取奥格瑞玛的烈焰', '从奥格瑞玛中心偷来的烈焰令你感到异常的温暖。你对这种罕见的力量一无所知，但是博学者或许知道些什么……', '将奥格瑞玛烈焰交给节日博学者。', '这是什么?要是我没猜错，这个火焰应该是从奥格瑞玛中心拿到的吧!它燃烧的热度反映出兽人和巨魔凶猛的内心。真是为我们的收集品画龙点睛 -', '你几乎在发着光芒，$r。你带了什么来?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9325, '盗取雷霆崖的烈焰', '从雷霆崖萨满祭司身上偷来的烈焰令你感到异常的温暖。你对这种罕见的力量一无所知，但是博学者或许知道些什么……', '将雷霆崖烈焰交给节日博学者。', '除非我猜错了，否则这个火焰应该是从雷霆崖的悬崖边拿到的!听听它和精神力量的共鸣!你真是个厉害的窃贼，$N。收下这个做为你的奖励。现在，如果我们能有全部四个城市的火焰……', '你几乎在发着光芒，$r。你带了什么来?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9326, '盗取幽暗城的烈焰', '从幽暗城上面的洛丹伦废墟偷来的烈焰令你感到异常的温暖。你对这种罕见的力量一无所知，但是博学者或许知道些什么……', '将幽暗城烈焰交给节日博学者。', '嗯……真是把奇怪的火焰!它很柔和，几乎是无火苗的闷烧，但它的中心又很强烈。你说你是从幽暗城取得它的吗?好极了。如果有了全部四个城市的火焰，谁知道我们能怎么样?', '你几乎在发着光芒，$r。你带了什么来?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9328, '辛多雷的英雄', '这是我们血精灵一族的历史新篇章的开始，$N。我们将收复所有失地，并与希尔瓦娜斯和她的盟友紧密地连接在一起。$B$B将这个叛徒的徽记拿去交给银月城的摄政王洛瑟玛·塞隆。他一定是最渴望听到这个消息的人。', '将达尔坎的徽记交给银月城的洛瑟玛·塞隆。', '我没想到会这么快就见到你。$B$B这真是个好消息，$N，比你可能想象的还要好。', '你想和我说话，$C?我不记得我们有约。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9329, '被遗忘者', '我知道被遗忘者出现在这儿很诡异，可他们确实是来帮忙的。跟高级执行官玛尔伦谈谈，他就在镇子西边的哨塔里。$B$B另外，$c，跟他谈完之后回到我这儿来，我还有件相当紧迫的艰巨任务要交给你去办！', '与塔奎林的高级执行官玛尔伦谈一谈。', '我知道我们被遗忘者在你们眼中就像怪物，但我向你保证，我们对你们的人民绝无恶意。我们会来这里是因为与血精灵有共同的敌人;背叛者达克汗!他已重回世上并率领着天灾军团从死亡之域往南入侵这片土地。$B$B来自这片土地的希尔瓦娜斯.风行者，她曾是个精灵，现在是我们的领导者。她曾和达克汗交手过，所以也跟你们一样希望达克汗死!$B$B我们会一同击败他的，$C!', '哈罗，血精灵。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9330, '盗取暴风城的烈焰', '从暴风城中心偷来的烈焰令你感到异常的温暖。你对这种罕见的力量一无所知，但是诗人或许知道些什么……', '将暴风城烈焰交给节日诗人。', '这把烧地明亮的火焰……你说这是从暴风城来的?了不起!那一定是趟真正的冒险!当然，我会给你一点报酬。如果你又找到这样类似的东西，记得再来和我谈谈。', '你几乎在发着光芒，$r。你带了什么来?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9331, '盗取铁炉堡的烈焰', '从铁炉堡中心偷来的烈焰令你感到异常的温暖。你对这种罕见的力量一无所知，但是诗人或许知道些什么……', '将铁炉堡烈焰交给节日诗人。', '这个热烈的火焰一定是从铁炉堡的大厅来的;它和那些矮人一样坚定。做的好，$N。如果我有其它城市的火焰……啊，没事。这是你的酬劳。', '你几乎在发着光芒，$r。你带了什么来?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9332, '盗取达纳苏斯的烈焰', '从泰达希尔海岸边偷来的烈焰令你感到异常的温暖。你对这种罕见的力量一无所知，但是诗人或许知道些什么……', '将达纳苏斯烈焰交给节日诗人。', '这把火烧着古老的哀伤，$N。你说你是从泰达希尔根部拉出这个的吗?好极了\r\n!这是你努力的奖励。如果你找到任何像这样的东西就再来找我;我或许会有些用途。', '你几乎在发着光芒，$r。你带了什么来?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9338, '塞纳里奥议会的盟友', '', '', '你为我们带来荣耀，$N。有你持续的努力我们会克服所有障碍的。', '即使你对我们提供的奖励没有兴趣，这些徽章仍象征着我们互相的信任和友谊。$B$B把它们带来给我。如果你的职责表现良好，我会做好应有的记录的。', '', '去找希利苏斯的唤风者卡尔东。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9340, '大裂隙', '联盟的军队几乎包围了猎鹰岗哨，我们的处境相当危险。艾泽拉斯世界的血精灵朝圣者们蜂拥而至，我们必须修筑一条安全的路线，躲避敌人的窥探。$B$B我已经想好了解决此事的办法，那就是开辟一条穿越大裂隙的秘密通道。$B$B好吧，我知道那儿盘踞着凶猛的剥石者，可它们只是一群野兽而已。给它们点教训，它们就不敢滋扰我们了。我要你转至大裂隙猎杀这些家伙，让它们知道我们的厉害。', '猎鹰岗哨的游侠队长维恩雷要你转至猎鹰岗哨以东的大裂隙，杀死8个石镰幼崽和3个石镰突击者。', '做的好，$N。岩石镰夺怪现在应该知道要离我们远一点了。', '你回来了。任务完成了吗?', '', '去地狱火半岛找猎鹰岗哨的游侠队长维恩雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9345, '准备药膏', '在我试图进入塞斯高的时候，一名燃烧军团的巡逻兵发现了我。我拼命地逃，想躲进不远处的那些塔里去，可是他们放出了地狱猎犬，扑倒了我，几乎差点把我弄成残废！$B$B后来，我挣扎着逃到了这里，不过我的一条腿已经严重骨折了。石头守卫安比兰发现我之后，把我带到了这里。$B现在，我必须先想办法医治好这条腿。北边白骨之谷那里生长着一种刺叶植物，用它制成的药膏应该能够缓解我的伤痛，让我痊愈。', '将制作药膏所需的12片地狱火刺叶交给断背岗哨的葛雷拉格。', '这些就是我所需要的。我要开始准备药膏并完成我的夹板再回到萨尔玛。我怎么感觉我知道当先知瑞卡酷看到我的时候她会说什么?$B$B<格莱克无趣地叹了口气。>$B$B谢谢你的帮忙，$N。我这还有一些剩下的骨叶，你可以将它们带走，谁知道这些叶子在何时会证明它的用途呢?', '你把那些植物带来了吗?', '', '去地狱火半岛找断背岗哨的葛雷拉格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9349, '掠食者的卵', '哦哦……我快要饿死了！$B$B嘿，朋友，你是不是觉得很讽刺？厨师快被活活饿死了？$B$B<雷加希干笑两声，从口袋中掏出一张褶皱的羊皮纸，并慢慢展开。>$B$B根据我们的旅游地图，我们的飞艇被搞下来之前是要飞去西南边靠近泰罗卡森林的一个叫荆刺小径的地方。据说那里盛产掠食者的卵，无比美味！如果你够胆去那里帮我弄些这种蛋回来的话，我就能做顿大餐了！前菜是蛋黄沙拉配蛋花汤，主菜是芥末煎蛋卷配蛋炒饭，甜点是蛋挞，唔，听起来好象有点扯蛋……', '将12枚饥饿掠食者的卵交给地狱火半岛飞艇坠毁点的雷加希。', '想吃美味的料理，就需要特级的食材。这些蛋看起来太棒了!$B$B我刚洗完我的锅子，所以欢迎你跟我一起品尝美食!', '你取回那些蛋了没?$B$B<雷噶西的肚子等得咕噜咕噜叫。>', '', '去地狱火半岛找飞艇坠毁点的雷加希。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9351, '疯狂的虚空行者', '虽然飞艇的机身已经修好了，但我还得找一些能烧的东西来发动引擎。我们的燃料全部用完了，在这个地方又搞不到新的燃料！$B$B在我们的正南面有个叫迁跃平原的地方，那里有许多失去控制的、凶猛的虚空行者。不过在我看来，那就是一群活蹦乱跳活泼可爱的活电池。$B$B如果你能帮我搞到些它们的精华，我就可以将飞艇的引擎改为由它们驱动的装置，说不定能比以前飞得更远哩！', '将10份浓缩的虚空行者精华交给飞艇坠毁点的“尖嗓子”斯克里·拉克希德。', '太完美了!事实上，我想它会发挥极佳的功用。我会重新设计引擎来充分利用这份额外的动力。我是说，如果，当我们顺利离开这里，我将会展示我的新设计，让每一位回到52区的人欣赏!!', '你取到精华了吗?', '', '去地狱火半岛找飞艇坠毁点的“尖嗓子”斯克里·拉克希德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9352, '达纳苏斯的侵扰', '我除了时刻警惕失心者滋扰生事之外，还要处理一堆声称看到暗夜精灵的虚假情报。$B$B虽然事实证明大多数情报都是子虚乌有，但是有件事倒是值得深入调查下。最近，我们的主要能源供给站西部圣殿遭到了严重破坏，传言都说是达纳苏斯的暗夜精灵干的。$B$B去那儿看看有没有可疑的家伙出没。然后向驻守在西部圣殿的魔网监护者薇兰妮亚汇报情况。', '转至鹰翼广场西南方的西部圣殿击败在那一带出现的入侵者，然后将你发现的情况汇报给魔网监护者薇兰妮亚。', '夜精灵?这里?那些小人!$B$B你觉得他们和我的圣所运作不良有关吗?如果你有任何消息，最好立即送给桑布兰德队长。', '你发现了什么吗?与夜精灵也有关吗?', '', '去永歌森林找西部圣殿的魔网监护者薇兰妮亚。', '击败入侵者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9355, '聪明人的工作', '你好，$c。总算有援兵过来了，现在我们终于可以开始处理周边生物所造成的问题了！$B$B我们的首要目标是确保西南边的那条道路的交通安全，但现在那些该死的硬壳穿地虫在那里频繁出没，将路面也破坏得凌乱不堪。$B$B如果你愿意帮助我们解决那些可恶的家伙，洛萨之子将感激不尽。不过，你千万得小心，它们很敏感。', '杀死15只游荡的硬壳穿地虫，然后向荣耀堡的工头比格姆斯复命。', '做的好，$N。不过我们先不要高兴的太早。我确定我们还没完全消灭那些虫仔。如果你又在这附近看到他们窜头窜脑，洛萨之子会准备好杀死他们的!', '你清理完道路了吗?', '', '去地狱火半岛找荣耀堡矿洞的工头比格姆斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9356, '万无一失', '斯克里总是喜欢夸自己的飞行技术“万无一失”，但我觉得这家伙好象随时能把飞艇开坠毁的样子！$B$B看看那边的残骸吧，那就是他某次成功的“紧急迫降”搞出来的。$B$B当然，那时候我们的确也遭到了敌人的攻击，但如果他能少吹嘘几句他的飞行技术，我就愿意原谅他！$B$B哦，对了，我想我得帮他搞点鸟翅来，这家伙说吃啥补啥，给他来点翅膀或许他的飞行技术也会好点。在东边的白骨之谷中，你可以看到许多啄骨秃鹰，它们的翅膀巨大多汁，最合适烧烤了。', '将12只强壮的秃鹫翅膀交给飞艇坠毁点的雷加希。', '劫毁者蛋。有了!$B$B地狱野猪的培根。有了!$B$B秃鹫翅膀。有了!有了!$B$B真是棒极了的一餐。你真该尝一尝。', '我等不及想看到他开始修复飞艇时的表情了。自从失事之后，他老是抱怨我整天只会想着食物。嗯，当他在做修复工作时，我们总是要解决食物来源的问题!', '', '去地狱火半岛找飞艇坠毁点的雷加希。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9360, '阿曼尼的入侵', '虽然你看不懂作战计划书中的文字，但是你发现有幅地图上清晰地标示着远行者居所和晴风村的位置。$B$B最好把这一情况汇报给远行者居所的达恩·晨行者中尉。', '将阿曼尼入侵计划交给远行者居所的达恩·晨行者中尉。', '巨魔一边把我们困在这里一边策划着攻击晴风村。我们完全没料想到。', '你想要给我什么东西?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9361, '地狱野猪，另一种白肉', '这些蛋好极了，但为什么我们不再来点别的呢？$B$B加上一些熏肉会让这顿大餐更加完美，而且，我知道在哪里能弄到熏肉。$B$B你看，这片区域到处都有地狱野猪，而且这里没有人去检查它们的肉是否能够食用，也没有人会烹饪那些肉。不过我们非常幸运！$B$B<雷加希在背包里仔细翻找，拿出了一个小瓶子。>$B$B这个虽然不是专为猪肉所准备的，不过，你要知道，烹饪需要创意！', '飞艇坠毁点的雷加希要你收集8块纯净的地狱野猪肉。你必须首先猎杀地狱野猪，然后利用净化药剂来净化被污染的地狱野猪肉。', '嗯……$B$B它看起来可以吃了，只要再适当调味一下。千万不要告诉希德他的早餐哪里来的，好吗?', '你成功地净化了地狱野猪肉吗?', '', '去地狱火半岛找飞艇坠毁点的雷加希。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9362, '军阀克雷利安', '没什么时间了，$n！我的探知法术最近发现了一个很强大的法术源。但我却不能离开法师塔，所以只有请你帮我杀死那个占有这件神器的邪恶生物。$b$b这个邪恶的家伙名叫军阀克雷利安，他躲藏在守卫森严的辛玛洛神殿。把他烧成灰，然后将他垂涎已久的虹彩贝壳给我带回来。', '为大法师克希雷姆夺回虹彩贝壳。大法师克希雷姆就居住在艾萨拉北部悬崖上的一座塔中。', '我必须说，这个贝壳有一种奇怪的光环。看来要奖励你取得它的一部分报酬就是派你去测试它的魔法潜力……', '没有时间可以浪费了!你拿到贝壳了吗?', '', '去艾萨拉找在熊头的大法师克希雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9364, '魔法的碎片', '我的研究发现了这个虹彩贝壳的一个特殊用途。$b$b带上这个贝壳，到艾萨拉四处找一些恶鞭纳迦，使用一下变形术看看。如果你愿意等一段时间，那么这个贝壳上所附带的光环会使他们分裂为几个小一些的相似物体。尽快杀死这些物体，贝壳就可以收集它们的精华。$b$b等贝壳满了之后，回来找我。', '对艾萨拉的恶鞭纳迦使用变形术，然后杀死几秒钟后出现的相似体。当你杀了50个相似体后，回去向大法师克希雷姆复命。', '太棒了!太棒了!$B$B现在我们就可以重新将这魔法组成新的法术。看啊!', '你收集到那些魔法了吗?', '', '去艾萨拉找在熊头的大法师克希雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9366, '邪恶之血', '此地东北方的阿苟纳之池曾是德莱尼人的圣地，恶魔阿苟纳的血液洒入池水后，整片区域都被污染了。$B$B虽然事隔多时，被稀释的恶魔之血仍然蕴涵着强大的力量。盘踞在那儿的恐惧魔也拥有了阿苟纳血液中的邪恶力量。杀死他们，替我取回一些邪恶样本。我不会让你白忙活的。', '猎鹰岗哨的阴沉的利亚森要你转至阿苟纳之池，从恐惧魔身上收集6份邪血样本。', '这些样本里含有的能量非常庞大，$N。现在我们只需要确定我们能持续从这里取得魔化之血。', '魔化之血……你弄到手了吗，$N?', '', '去找地狱火半岛猎鹰岗哨的阴沉的利亚森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9367, '火焰的节日', '仲夏就要来了！$b$b每一年，按照传统，各大城市里都会选出护火者来照看我们城中的篝火。当火焰燃烧在艾泽拉斯世界的各处时，我们就可以通过这种世上最热诚也最明亮的事物向夏天这个季节表示敬意。$b$b事实上，若你不介意的话，我有个任务要交给你。我还不知道是否所有城市里的火焰都已经点起了。到各大城市去吧，让那里的火焰温暖你的身躯，当然，首先要确认它们已经被点燃了！', '碰触暴风城、铁炉堡和达纳苏斯城里的篝火，然后与城市内的节日博学者交谈。', '太好了!如果那些营火真的如你们所说的那样炽热的燃烧着，看来我们今年指派的火焰管理器都很尽责。谢谢你帮我去调查;来，收下这个做为我一点小意思。', '火焰都发烫着吗?', '', '去找节日博学者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9368, '火焰的节日', '仲夏就要来了！$b$b每一年，按照传统，各大城市里都会选出护火者来照看我们城中的篝火。当火焰燃烧在艾泽拉斯世界的各处时，我们就可以通过这种世上最热诚也最明亮的事物向夏天这个季节表示敬意。$b$b事实上，若你不介意的话，我有个任务要交给你。我还不知道是否所有城市里的火焰都已经点起了。到各大城市去吧，让那里的火焰温暖你的身躯，当然，首先要确认它们已经被点燃了！', '碰触奥格瑞玛、雷霆崖和幽暗城里的篝火，然后与城市内的节日诗人交谈。', '太好了!如果那些营火真的如你们所说的那样炽热的燃烧着，看来我们今年指派的火焰管理器都很尽责。谢谢你帮我去调查;来，收下这个做为我一点小意思。', '火焰都发烫着吗?', '', '去找节日诗人。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9369, '补充治疗水晶', '我们是德莱尼人。许多族人在飞船坠毁时身负重伤，亟待医治，可是治疗水晶已经所剩不多了。我们必须迅速补充库存！$B$B眼下这种窘迫的局面，也只能用峡谷蛾的血液作为治疗水晶的替换品。$B$B峡谷蛾随处可见，不过它们大多分布在西北边。', '从附近的峡谷蛾身上收集8瓶蛾血，然后向埃门谷坠毁点的普罗尼图斯复命。', '令人遗憾的，那些生物必须死亡我们才能生存 - 不分青红皂白的杀戮不是我们德莱尼人的作风。不过，你所收集的血清会补充我们的治疗水晶，所以他们不会死得毫无价值。', '你弄到治疗水晶必要的飞蛾血清了吗?溪谷里到处都是生还者，时间紧迫!', '', '去埃门谷找坠毁点的普罗尼图斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9370, '阻止净化', '我们的斥候在阿苟纳之池俘获了一名德莱尼圣骑士。当时他正在操办某种净化仪式，看来德莱尼人企图净化阿苟纳之池。我们必须阻止他们，否则邪血样本的来源就会被切断！$B$B我们从圣骑士身上搜出一枚信号宝石，这东西似乎是用来标记安全地点的，这样那些自称为“学者”的德莱尼牧师就知道该在哪里启动净化仪式了。将这颗宝石放置在阿苟纳祭坛附近，击败靠近它的德莱尼人。$B$B我建议你最好带上一两个朋友。', '转至阿苟纳之池，将信号宝石放置在阿苟纳祭坛附近，击败被召唤出来的德莱尼学者。完成任务后返回猎鹰岗哨，将信号宝石交还给阴沉的利亚森。', '那会让那些神圣的狂热者不再干扰别人的事。', '你回来了，$N。你结束了德莱尼愚蠢的行为吗?', '', '去找地狱火半岛猎鹰岗哨的阴沉的利亚森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9372, '恶魔的玷污', '欢迎来到塞纳里奥哨站，$c。我们很少结交外面的朋友，不过，依然很高兴见到你。为了研究这个破碎世界中的生物与生态，我常常会转至许多偏远的角落。$B$B不过，上一次塞纳里奥远征队派我去研究外域中最危险的野生生物时，我却发现了一件惊人的事情。当这里的许多生物遭受辐射之后，它们的身体都发生了可怕的变异。当前，我正在收集血样，试图研究这些变异。如果你愿意帮忙的话，我会非常感激你的。', '地狱火半岛塞纳里奥哨站的塞安·红鬃要你从笨拙的地狱野猪身上收集6份地狱野猪血样。', '做的好，$N。这些鲜血样本对我的研究和远征队对外域生物更广阔的研究会很有帮助。$B$B如果我可以分离出造成这些生物持续改变的因子，或许我就能调制解药。', '你收集到鲜血样本了吗?', '', '去地狱火半岛找塞纳里奥哨站的塞安·红鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9373, '遗失的信件', '仔细地显示过这只坏掉的皮箱子之后，你发现它很明显是遭到了那些虫子消化道内的腐蚀性液体的破坏。它表面的皮革似乎经过了一些简单的加工，但装饰与加工的细节已经无从辨认，也无法提供线索了。$B$B皮箱上唯一能看清楚的是一小块已经磨损很严重的塞纳里奥议会的标志。除此以外，你没有办法了解更多有关这个小皮箱的情况了。因此，你认为最好的处理方法就是将它交给一名塞纳奥议会的成员。', '转至地狱火半岛西部的沙纳尔废墟，将被腐蚀的皮箱交给驻扎在废墟附近的塞安·红鬃。', '谢谢你把这个带来给我，$C。我还纳闷怎么这么久都没听到远征队的消息。不知道这则讯息是多久以前就被发出，而信差不晓得发生什么事了。$B$B这些钱是给你的。', '你好，$C。你怎么会到我的营地来?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9374, '埃雷利恩的日记', '来到外域后，我的丈夫埃雷利恩便对阿苟纳之池着了迷。他耗费大量的时间去那儿研究软泥怪！$B$B几天前，他突然失踪了。他们都说他已经死了，劝我放弃一切希望。$B$B我唯一能做的就是找回他的研究笔记。转至阿苟纳之池的东北方寻找他的日记，他总是把它放在那个褐色的背包中。', '地狱火半岛猎鹰岗哨的魔导师卡尔琳达要你转至阿苟纳之池，找回埃雷利恩的日记。', '我丈夫的日记……这一点也无关研究!$B$B我怎么会这么傻?“魔化泥浆怪的魔法特性”。他真的要我这样做。', '找到了吗，$N?你可以在地狱火半岛北边找到阿葛纳尔之池。', '', '去地狱火半岛找猎鹰岗哨的魔导师卡尔琳达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9375, '猎鹰岗哨之路', '<这个受尽折磨的血精灵看到你之后，脸上的痛苦表情显得平缓了许多。>$B$B$c，请你一定把我救出去。唉……我太愚蠢了，没有听从玛提克·托塞多雷的警告，一意孤行离开了萨尔玛。结果，我在路上遭到了那些可怕怪物的袭击，是的，没错，就是玛提克·托塞多雷提到过的掠食者。我好不容易击退了它们，可没想到竟然遇到了更大的麻烦。$B$B在我包扎伤口的时候，那些鸟人发现了我，并把我抓来这个洞穴，锁进了这只笼子里！我必须出去，我必须到猎鹰岗哨去！', '护送受伤的血精灵朝圣者返回猎鹰岗哨，然后与塔雷里斯·晨光谈一谈。', '<达勒利斯对前哨站的几个血精灵大吼。>$B$B把她带进去看看她的伤势!$B$B<达勒利斯转回来看着你。>$B$B她很幸运被你找到，$C。我想她在那里活不了多久。$B$B你能了解她之前说了什么吗?', '你有什么需要，$C?', '护送受伤的血精灵朝圣者回到猎鹰岗哨', '去地狱火半岛找猎鹰岗哨的塔雷里斯·晨光。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9376, '朝圣者的困境', '这名受伤的朝圣者在昏迷中似乎一直在说着什么，好象有提到什么背包的样子。$B$B那么，你遇到她的时候，在附近看到过她的背包吗？$B$B嗯……她一定是在逃走的时候把它弄丢了。南边峡谷的钢牙掠食者常常会袭击单身的旅行者。$B$B如果她不能平静下来的话，我是没有办法为她疗伤的，唉，她的倔强会要了她的命……$B$B去尘羽峡谷看看能否找到她的营地吧，或许她把背包遗留在那里了。', '受伤的血精灵朝圣者在尘羽峡谷宿营时遭到了钢牙掠食者的袭击。转至那处营地寻找丢失的背包。', '谢谢你把它拿来，$N。我不知道那个受伤的朝圣者到底有着什么重要的东西，但她拒绝让任何人靠近她，除非那个背包到了她的手里。', '事情进展的不太好。这样一来，她永远都无法再上路了。你能找到那个背包吗?', '', '去地狱火半岛找猎鹰岗哨塔的雷里斯·晨光。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9381, '箭矢之羽', '最近，朝圣者的大批涌入和联盟军队的不断进犯都清楚地表明，猎鹰岗哨正经历着一个多事之秋。连我这样的人，最近在有空的时候都会帮那些游侠们准备箭支。不过，最近空闲太少，我已经有很长时间无法去收集箭尾要用的羽毛了。$B$B如果你能帮我收集一些啄骨秃鹫的尾羽，我会给你一些钱作为报酬的。我以前经常在猎鹰岗哨北边的巨兽尸骨周围找到它们，你也可以去那边看看。', '从啄骨秃鹫身上收集8片啄骨秃鹰的尾羽，把它们交给猎鹰岗哨的驯鹰者德蕾娜·河风。', '这些就足够了。我还担心游侠会有好一阵子没有足够的箭，但现在我又少了一件要担心的事了。谢谢你的帮忙，$C。', '你拿到那些羽毛了吗?', '', '去地狱火半岛找猎鹰岗哨的驯鹰者德蕾娜·河风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9383, '艰巨的计划', '血精灵就是滥用魔法者的典型，$c。现在，他们已经无法控制魔法的能量，更确切地说，他们已经沦为了魔法的奴隶，彻底根本无法摆脱对魔法能量的依赖与沉迷了。来到外域之后，他们开始汲取外域的虚空行者的力量，并强化了他们那种源自恶魔的法术。$B$B我准备了一块附有符咒的水晶，它可以中和一个虚空行者的身躯，使它被毁灭后就立即切断与这个世界的关联，去试试它吧。我常常看见虚空行者出现在地狱火堡垒东南边的迁跃平原。', '在失控的虚空行者受伤之后对其使用净化水晶，然后返回塔哈玛特神殿向艾尔萨娜复命。', '你做的很好，$N。看来遏制水晶当前已受到控制，但没人知道这样的状况能维持多久。我们会持续监控，同时准备更多的水晶。', '你使用水晶的魔法来对抗无法控制的虚无行者了吗?', '', '去地狱火半岛找塔哈玛特神殿的艾尔萨娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9385, '钢牙掠食者', '荣耀堡派我们来消灭这一带的鸦人势力，到了这边以后，我们觉得这里是个不错的地方，于是就驻扎了下来。然而，我们却根本没有发现这里与钢牙掠食者的老巢竟然如此接近。$B$B它们都是些非常凶猛的掠食者，经常骚扰这里，让我们根本无法进行工作。如果你愿意帮我们干掉它们的话，我们愿意支付你一笔不错的报酬，你觉得怎么样呢？', '杀死10只钢牙掠食者，然后向地狱火半岛的格雷尼·长须复命。', '做的好，$N。这应该让那些怪物知道了谁才是老大!', '你在处理劫毁者威胁上有所斩获了吗?', '', '去找地狱火半岛的格雷尼·长须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9387, '堕落之源', '那些没有堕落的德莱尼人，例如这个倒霉的家伙，都是圣光忠实的拥护者。究竟是什么导致这个伟大的种族分化出破碎者和失落者呢？$B$B我听来的说法是恶魔的力量导致了德莱尼人的变异。我想验证这种推测是否属实。$B$B此地西北方便是沙纳尔废墟。那儿聚集着地位低下的破碎者，伊利达雷监工负责看管他们。将监工身上的恶魔精华带回来给我，这样我就能用它们在德莱尼人身上做试验了。', '转至地狱火半岛的沙纳尔废墟，从伊利达雷监工身上收集5个恶魔精华。完成任务后返回猎鹰岗哨，向药剂师艾瑟森复命。', '你真的帮了很大的忙，$N。现在让我们看看可以从样本中了解什么。', '你取得了那些样本吗?', '', '去地狱火半岛找猎鹰岗哨的药剂师艾瑟森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9388, '卡利姆多的火焰', '今天，全世界上各处有无数的火焰在熊熊燃烧着，$n。那些最狡诈的火焰往往都是绿色的，如果不小心照看的话，它们很快就会灭掉。为我们的护火者确认一下卡利姆多上的几处翡翠烈焰是否还在燃烧着，好吗？$b$b你能在贫瘠之地的棘齿城、黑海岸的主宰之剑、银翼岗哨附近的桥，以及石爪山尘风峡谷的路旁去寻找这样的篝火堆。', '造访灰谷、贫瘠之地、黑海岸和石爪山的篝火堆，然后回来与节日护火者交谈。', '啊，所以它们真的还在燃烧。我很高兴;时间没到之前那些火焰不能熄灭。你做的很好，$N。收下这个和我的祝福。', '庆典结束之前火焰都不能熄灭!', '', '去找节日护火者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9389, '东部王国的火焰', '仲夏火焰节的传统就是建起一座金字塔状的火焰。有些人说绿色的火焰是最好的，因为它们最难以维持燃烧，而且有着如此美丽的颜色。$b$b你去为我们的护火者确认一下东部王国的绿色火焰是否都在正常燃烧吧。它们分别座落于湿地的丹莫德，银松森林的焚木村旁，西部荒野能望见灯塔的悬崖边，以及希尔斯布莱德那座被废弃的哨塔边。', '造访希尔斯布莱德丘陵、银松森林、西部荒野和湿地的篝火堆，然后回来与节日护火者交谈。', '你回来了，也见过大陆上翠绿色的火焰了。你觉得怎么样呢?确切的说，那是一种罕见又美好的景象。不过，我知道，还是要有实质的奖励比较好……那么拜托你，收下这个做为奖励。', '你完成你的任务了吗?', '', '去找节日护火者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9391, '点燃灯塔', '我们成功地削减了剥石者的数量，现在只需要指引朝圣者们踏上这条安全的通道。带上这柄燃烧的火炬返回大裂隙，在东边寻找沿途的三座灯塔。$B$B点燃三座灯塔，然后回来向我复命。当你点燃灯塔时，小心那些被吸引而来的剥石者。', '转至地狱火半岛的大裂隙，点燃南部灯塔、西部灯塔和中部灯塔。完成任务后返回猎鹰岗哨，将燃烧的火炬还给游侠队长维恩雷。', '大裂缝，虽然仍然很危险，但它会是我们朝圣者一条安全的路径。$B$B联盟看守着进出猎鹰哨站的所有道路，这是我们必须奋不顾身去执行的动作。', '你完成我所交代的事了吗，$N?', '', '去地狱火半岛找猎鹰岗哨的游侠队长维恩雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9396, '鸦人的魔法', '外域隐藏着许多秘密，$N。要揭开这些秘密，我们需要的只是时间。$B$B半人半鸟的鸦人氏族掌握着古老而神秘的知识，可以帮助我们探索这个世界。转至南边的哈尔什巢穴。从哈尔什鸟人手中夺得魔法卷轴，将它们带回来给我。', '将4个哈尔什卷轴交给地狱火半岛猎鹰岗哨的奥术师卡雷希斯·晨星。', '做的好，$N。外域的秘密不久后就会被我们揭开了。$B$B成为这世界的主宰是我们的天命。', '你取得了卷轴吗，$N?', '', '去地狱火半岛找猎鹰岗哨的奥术师卡雷希斯·晨星。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9397, '捉小鸟', '哈尔什鸦人驯养了一种名叫卡利鸟的飞禽，它们的羽毛非常漂亮。$B$B我设法抓来了一只雄性小卡利鸟，凭我的经验，驯养这种鸟类应该不成问题。不过雌性卡利鸟非常罕见，如果能抓来一只雌鸟，我就能尝试繁殖出它们的后代。但是……她必须是一只小卡利鸟才行。若是强行将成年卡利鸟囚禁起来，她肯定无法存活。$B$B带上这个笼子转至南边的哈尔什巢穴。在卡利鸟巢穴中搜寻那些即将孵化的鸟蛋，如果你能为我抓回一只雌性小卡利鸟，我一定会好好奖赏你的。', '转至地狱火半岛的哈尔什巢穴，在卡利鸟巢穴中寻找雌性小卡利鸟。利用空鸟笼捕获雌性小卡利鸟，将其交给猎鹰岗哨的驯鹰者德蕾娜·河风。', '你办到了!你捉到了一只母幼鸟!$B$B她很珍贵的。非常感谢你，$N。', '你回来了。你带回了母卡里瑞鸟吗?', '', '去地狱火半岛找猎鹰岗哨的驯鹰者德蕾娜·河风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9398, '致命的猎手', '外域的破碎者是个悲惨的民族，他们的生存权利和自由一直在遭受着无止境的侵害。所以，当黑暗之门开启时，他们满怀着希望大批地涌入了这里，希望转至我们的世界，这一点也不奇怪。$B$B然而不幸的是，栖息在大裂隙附近的那些掠食者却把这些从南边惶恐逃亡过来的兄弟姐妹们当成了唾手可得的猎物。你必须到那里去削减掠食者的力量，这样我们的同胞的生存机会就能改善许多。', '地狱火半岛塔哈玛特神殿的斥候瓦努拉要你杀死8只石镰幼崽和4只石镰突击者。', '你做得很好，$N。靠着夺取别人的生命以存活总是一件不幸的事情，即使对象是一只如同岩石镰夺怪的危险野兽也是一样。$B$B谢谢你完成了这个残酷的任务。', '欢迎回来，$N。你完成了我要你做的任务吗?', '', '去找地狱火半岛塔哈玛特神殿的斥候瓦努拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9399, '残忍的监工', '你该不会认为大多数破碎者都是邪恶的吧？其实，他们大多本性善良，只是缺少正确的道德与信仰指引而已。$B$B在见到欧麦尼——也就是神殿中的这些德莱尼人以前，我也几乎完全迷失了自我。$B$B兽人的恶魔法术折磨着我们的思想，从而让我们很容易受到他们的迷惑，被他们利用。$B$B除此以外，恶魔们也会和伊利丹联手，他们常常袭击地狱火半岛，并将我们变成他们的奴隶。直到欧麦尼出现之后，我们才有了希望。到西南边的沙纳尔废墟去杀掉那些伊利达雷监工，我的人民才有希望获得自由！', '转至沙纳尔废墟，杀死4名伊利达雷监工，然后向地狱火半岛塔哈玛特神殿的伊坎复命。', '你办到了!我欠你一份人情，$N。看看那些出现的崔互德人们。$B$B在我的领导下，他们将会学习到许多传统，等着瞧吧。', '你回来了!你完成任务了吗?', '', '去地狱火半岛找塔哈玛特神殿的伊坎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9401, '奇怪的武器', '你从尸体上拔下了这把石斧，放在眼前仔细检查。这把武器的制造工艺有点不同寻常。$B$B它的样式与外形的确是兽人风格，但材料却是你从来没有见过的。纳兹格雷尔或许会对这把武器有点兴趣。', '将重型石斧交给萨尔玛的纳兹格雷尔。', '他是被这个武器杀死的?不可能!$B$B我们……找到他们了吗?', '告诉我，刺客死了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9402, '捞瓶子', '那么……你叫$n，对吗？不用惊讶，我知道你是谁，我的一个学生常常称赞你，简直是赞不绝口呢。$b$b嗯……如果你想给$g她:他;留下深刻的印象，为什么不帮我做点什么事呢？在我身后的池塘底有一只小瓶子，到水里去帮我找到它。', '在萦语水池底部为指导者安瑟隆找到碧蓝瓶。', '喔，做的好……我才刚要你跳进池塘，你就已经去了。我想你会这样做，都是因为好朋友要求你这样做。$B$B如果你想要为此获得一个奖励，是这样的:永远不要在不清楚回报前做任何事。法师的心智是$g他:她;最好的武器。记住这点，并多用用你的脑袋。', '叫你潜水的事情进行的如何?', '', '去永歌森林找萦语水池的指导者安瑟隆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9403, '最纯净的水', '现在你应该算是学到点东西了，我想让你去做点更重要的事情。这关系到你在近战中保护自己的能力。当然，除非万不得已，你不应该让敌人靠近你，但是同样你也不能在敌人靠近之后毫无办法。$b$b我会给你制作一根适合你用的法杖。你要做的就是带上这只你刚刚捞上来的瓶子，在里面灌满艾伦达尔瀑布的水。沿着河往东南边走就可以找到瀑布了。', '指导者安瑟隆希望你能在碧蓝瓶中装满艾伦达尔瀑布的水。', '来看看你给我带了什么来……$B$B<他拿起玻璃瓶到光源下仔细地检视。>$B$B很好，这很适合。做的好，$N。', '只有从艾兰达瀑布取得之最纯净的水才能被跟法术一起使用。你拿到它了吗?', '', '去永歌森林找萦语水池的指导者安瑟隆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9404, '活动的树木', '你应该注意到在艾伦达尔瀑布附近行走的那些树了吧？作为大自然的守护者，它们身上都有着原始的魔法能量，我们可以使用你收集的水来改造这些魔法能量。$b$b不幸的是，这些绿色的守护者们都是些狂暴而扭曲的生物，所以如果你想找到一根有用的树枝，也许需要干掉许多守护者。', '清理永歌护卫者，直至你找到指导者安瑟隆所需要的生命绿枝。', '你已完成我要你做的事了，$N，你可以拿走你的奖励了。', '你拿到了吗?快把它交给我!', '', '去永歌森林找萦语水池的指导者安瑟隆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9405, '酋长的命令', '你应该知道，酋长之所以在这支远征军中投入了这么多的资源，其理由只有一个。这个世界曾是我们的故乡，这里是我们的根源所在。$B$B来到这里，对于一个兽人与一个血精灵来说有着完全不同的意义。他们来到这里，是为了寻找一处新的家园，而我们则是回到了久违的故乡。$B$B不知是谁用我们兽人的工艺制成了这把石斧，但我们一定要找到他。它很重要，有了它，就可以利用我们最传统的方法来找到制作者。把这武器拿给先知雷古库特看看，她知道该做什么。', '将重型石斧交给萨尔玛的先知雷古库特。', '我了解纳兹格雷尔的要求，$C。不要再说了。', '告诉我你在找了什么，我可以帮助你找到它。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9406, '玛格汉', '这……这就是你从黑暗之门的那一边带来的消息吗？你是说……你是说杜隆坦的儿子正统治着那边的国度，还……还已经摆脱了恶魔的操控？现在，他的手下已经回到了这个世界？！你要我们相信这些吗？$B$B希望这不是你开的玩笑，$c。这对我的人民来说意味着……不，这简直无法形容……我必须立刻通知纳格兰那边，必须立刻通知地狱咆哮大人。$B$B把这封信送给你在萨尔玛的上级。告诉他们，玛格汉欢迎他们回家！', '将玛格汉的来信送给萨尔玛的纳兹格雷尔。', '你确定吗?真正的兽人……就在地狱火这里!这可是件大新闻，$N。$B$B我们必须立刻通知大酋长。', '你带了什么来给我们，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9409, '紧急物资！', '你收集到的蛾血足以填补治疗水晶的需求缺口，将这一组药水瓶交给牧师扎尔杜吧，他在飞船的中央室里照顾受伤的伙伴。', '将一组药水瓶交给埃门谷坠毁点的扎尔杜。', '做的好!这很适合补充我们消耗的治疗水晶。$B$B但既然你来到这里，我想我有另一件事要交给你，你愿意吗?', '嗨，$C。你拿着什么?是给我的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9410, '灵魂的指引', '使用幽灵狼吧，即使是最优秀的战狼在追踪技巧上也无法与它们匹敌，$N。元素之灵的感官与了解世界的方式和我们完全不同。它们并不是使用嗅觉，而是使用心灵来进行追踪。$B$B去吧， $c，将这支图腾带上，在你发现那把石斧的地方使用它。', '在你找到克伦·断脊者尸体的地方使用先祖狼魂图腾，并跟随先祖狼魂前进。', '你是谁，竟敢不经通报就擅自进入?瑞卡感应到有灵魂伴随着你，所以我命令我的人守护在这。$B$B说吧，但慎选你的言词，我们可是很少相信这么接近堡垒的陌生人。', '你还活着真的是很幸运。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9417, '鸦人的威胁', '鸦人是一种非常聪明的生物……他们可能跟你遇见过的所有侏儒一样聪明。更厉害的是，他们也同样精通魔法，并且，所有鸦人都无一例外地有着暴躁易怒的坏脾气。$B$B最近他们常常袭击荣耀堡周围的巡逻兵，这也是我们被派到这里来的原因。不过呢，你瞧，米伦和我都是众所周知的超级射手！但我们擅长的是森林围猎和射击比赛……而不是对付这些……这些会放闪电的鸟人。$B$B所以，你愿意助我们一臂之力吗？你在西南方就能找到哈尔什巢穴。', '地狱火半岛的格雷尼·长须要你杀死4名哈尔什风行者和6名哈尔什利爪卫兵。', '做得好，$N!我以长须之名赞扬你。$B$B待在这和我们一起喝一杯，好吗?', '你回来了!如何?', '', '去找地狱火半岛的格雷尼·长须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9418, '亚维鲁的宝珠', '<当你将宝珠逐渐拿过来时，忽然某个声音对你说起话来。>$B$B我知道你不是鸦人，所以我想跟你做笔交易，让我获得自由。我叫埃拉纳斯，是空气元素的首领之一。不幸的是，我被哈尔什的法师亚维鲁利用妖术困在了这个宝珠内。$B$B首先，你要找到鸦人囚禁我的祭坛，它就隐藏在鸦人洞穴的东南边。然后，你必须将宝珠带去那里，释放我出来，并把宝珠交给我，这样一切就都结束了。到时候，为了感谢你让我重获自由，我会送你一些珍贵的财宝！', '转至地狱火半岛哈尔什巢穴东南方的哈尔什祭坛，将亚维鲁的宝珠交给重获自由的埃拉纳斯。', '有了这个宝珠我又重获自由。拿着这个奖励，凡人，这样我们的帐就一笔勾销了。', '我一直盼望的自由终于是我的了!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9419, '横扫沙漠', '最近我们发现部落正在希利苏斯的沙漠上进行一些扫荡行动，以争夺宝贵的资源，不过不必担心这些家伙。我们不认为他们值得我军在酷热的沙漠上派驻大批兵员。$b$b但是，资源的重要性却是不容质疑的，我们也决定做出一些行动。$b$b如果你有能力的话，立刻进入沙漠地区，夺回一些希利苏斯水晶尘，然后回到这里。', '找到一份水晶尘，将其送到水晶尘萃取器那里，然后向佐拉虫巢外联盟营地的布鲁沃尔元帅复命。', '感谢圣光你成功了。$B$B如果我们可以早点这么做，我们的需求就不会如此迫切了。我们绝对不能让沙漠里的物资落入部落手中。', '在那里动作要小心，但也要快速。我们没有时间可以浪费。', '', '去找希利苏斯的布鲁沃尔元帅。', '运回水晶尘', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9420, '绝世好帽', '南边哈尔什巢穴的鸦人驯养了一种巨型的卡利鸟，而这种鸟类的羽毛是艾泽拉斯世界许多贸易站重金收购的目标。想想吧，要是卖一批过去，我就能买无数的麦酒了！$B$B总之，你帮我搞一些卡利鸟的羽毛回来，我会送给你一顶我家特制的帽子，你觉得怎么样？放心，你决不可能在别的地方找到那样一顶绝世好帽的！来，做笔交易吧，怎么样？', '转至哈尔什巢穴，从各种卡利鸟身上收集8片卡利鸟的羽毛，将它们交给地狱火半岛的米伦·长须。', '你完成了你的部份。我想一言为定吧!$B$B这是你该获得的。好好善待它。', '你把卡里瑞羽毛带回来给我了吗，$C?', '', '去找地狱火半岛的米伦·长须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9422, '横扫沙漠', '不久以前，我们开始吸收希利苏斯沙漠中水晶资源的力量。过去，开采过程中唯一遇到的危险不过是那些以沙漠为家的野兽，以及沙漠的干旱和炎热。$b$b但现在联盟似乎也开始争夺这些我们先发现的东西了。现在看来，我们正在展开一场竞赛，双方都想要彻底占领这些资源，并防止它们落入对方的手中。$b$b我需要一切可以依靠的力量，希望你能帮助我。', '找到一份水晶尘，将其送到水晶尘萃取器那里，然后向雷戈虫巢外部落营地的吉里卡将军复命。', '你做的很好，$N。这些资源会加入我们的库存之中，每一分都是我们的优势，敌人的弱势。', '小心沙漠里的危险，$N。有联盟在沙丘里埋伏，你的任何一步都可能是最后一步。', '', '去希利苏斯找雷戈虫巢的吉里卡将军。', '运回水晶尘', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9424, '玛库鲁的复仇', '瑟丹就像是玛库鲁的兄弟。我们欠他的实在太多了！他们说玛库鲁疯了，可如果这些欧麦尼不为瑟丹的死亡做点什么，他们才是最疯狂的！$B$B在这个世界上玛库鲁拥有的东西不多，不过你愿意帮瑟丹报仇的话，他会把他唯一的财产给你。$B$B玛库鲁在东北边的山坡上看到过玛格汉步兵。他们对我们充满了敌意！我们绝对不能对他们仁慈！去为瑟丹报仇！把他们的先祖念珠带回来证明他们已经死掉了！', '地狱火半岛塔哈玛特神殿的玛库鲁要你带回10个玛格汉先祖念珠。', '很好……报仇了!你做得很好。$B$B拿着这个。这是希戴给的礼物。只是玛酷鲁不太想看到。', '你代替玛酷鲁替希戴报仇了吗?', '', '去地狱火半岛找塔哈玛特神殿的玛库鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9426, '阿苟纳之池', '昔日的德拉诺世界发生了翻天复地的变化。恶魔的力量在大地的某些地方留下了永恒的烙印。$B$B阿苟纳之池便是被污染的圣地之一。那儿曾经流淌着德莱尼氏族神圣的泉水，但是现在，恶魔阿苟纳的血液污染了圣水的精华。如果我们想要夺回阿苟纳之池，就必须清理掉那些被邪血污染的生物。转至东边的阿苟纳之池，杀死盘踞在那里的恐惧魔和腐泥怪。', '智者阿曼恩要你转至阿苟纳之池，杀死6个恐惧魔和6个起泡的腐泥怪。', '是的，我感觉恶魔力量愈来愈薄弱了。$B$B你做得很好，$N。', '你完成你的任务了吗，$N?', '', '去地狱火半岛找塔哈玛特神殿的智者阿曼恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9427, '净化水体', '我想麻烦你再跑一趟，帮助我们实现净化阿苟纳之池的愿望。你成功地削弱了恶魔的势力，现在只需带上这个净化水瓶，将它倒在阿苟纳之池的污染源——阿苟纳的尸体上。$B$B恶魔的尸骨就在阿苟纳之池的最北边。千万小心，我觉得他的精华并没有完全离开这个世界。', '转至阿苟纳之池，对阿苟纳的尸体使用净化水瓶。当阿苟纳的精华被净化之后，回去向智者阿曼恩复命。', '阿葛纳尔的本质以他腐败的产物赖以为生。因为你成功地击败了恶魔，我们才能再次让池子恢复到原本的纯净。$B$B我们非常感谢你，$N。你的付出对这个世界有极大的影响。', '你回来了，$N。这些水已经净化了吗?', '', '去地狱火半岛找塔哈玛特神殿的智者阿曼恩。', '净化阿苟纳的气息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9430, '沙纳尔圣物', '正如我之前所说的，我并没有看到别人无法看到的东西。我不会对你帮助玛库鲁这件事做任何评论，我想你需要的是对自己见到的事物有更深入的了解。$B$B到西南边的沙纳尔废墟去寻找散落在那里的圣物。如果运气好的话，你会找到我们所需要的东西。$B$B你不会马上就明白这个任务的意义，不过你一定要有信心，$N。只有拥有足够的耐心时，你才能明白其中的道理。', '地狱火半岛塔哈玛特神殿的智者阿曼恩要你去沙纳尔废墟找回10个沙纳尔圣物。', '你非常幸运。如我所期望的一样，你已经找到和这些相同的特殊圣物。', '你拿到夏纳圣物了吗，$N?', '', '去地狱火半岛找塔哈玛特神殿的智者阿曼恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9431, '另一条路', '你一定很想问，怎么会有一个血精灵站在千针石林的风蚀丘陵上，而不是在银月城的厅堂之中的？$B$B我的同族们抛弃了我，不再需要我了。我所有有关自然可以治愈我们那种魔瘾的论文都被烧毁了。$B$B现在我可以自由自在地在这里进行研究，可惜的是，我的研究材料用光了。如果你愿意从栖息在千针石林最西边的雷鸣岩石元素身上帮我采集一些净化过的泥土，并帮我带去给我在白沙岗哨的同事，那么我会非常感谢你的。', '从雷鸣岩石元素身上收集两份纯净之土，把它们交给白沙岗哨的维兹罗。', '什么?她没提到月井?那是她脑中一直以来所想的。我承认整件事有点古怪，但我怎能拒绝客户，尤其当她是我唯一的客户时?$B$B或许试着溜进夜精灵聚居地并从他们的月井偷水，不是我帮客户做的最聪明的事，但她的钱和任何人的一样金啊!', '博学者伊罗赛的笔记有点隐秘，但我想我了解她想告诉我的话。如果你有她说的泥土，我就能将它放进你需要用来取月井之水的容器中。', '', '去千针石林找白沙岗哨的维兹罗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9433, '月亮井的水', '嘿，别这么看着我！我可没说我会派你带着汲取器和广口瓶去萨兰纳尔的月井那里！$B$B但我……哦……你看……我正在帮另外一位客户修理产品。事实上，我已经在萨兰纳尔附近安置了遥控机器人，也在隐蔽的地方安装了一个便携式控制台。你所需要做的，就是带这个控制单元过去，躲避在控制台的掩体内，然后使用控制台操作着机器人去办事就可以了。很简单吧！$B$B但你要保密，如果我的客户知道了我把遥控机器人从包装里拿了出来，她非用我的耳朵勒死我不可！', '在千针石林边界靠近萨兰纳尔的一处灌木丛中找到隐蔽的控制台，并在那里控制机器助手3000型进入萨兰纳尔收集一份月亮井的水，然后把水交给白沙岗哨的维兹罗。', '它运作的比我期望的还要好!为良好的老哥布尔足智多谋又加了一笔!$B$B唯一的问题就是它布满了灰尘!我要花一辈子的时间才能把这个东西给清理干净并放回它的木箱。$B$B当然，我也有的是时间。', '它照做了吗?', '', '去千针石林找白沙岗哨的维兹罗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9434, '测试药剂', '<维兹罗从机器人中取出了井水样本，并放入了一个还放有雷鸣石元素土和其它几件物品的箱子中。>$B$B给你，这就是魔导师艾洛塞清单上的所有东西了。告诉她，能为她服务我非常荣幸，祝她在研究方面有好运气。', '将这箱材料交给乱风岗的魔导师艾洛塞。', '太好了，看来所有东西都在这了。现在，我要做的就是把全部的东西混合在一起然后试试看。如果这个药水的效果会跟我的研究结论相同，那么我就发明了一种能减少我的人民对于魔法上瘾影响的好方法了。$B$B你将要目睹历史的过程了，$N。想想看，如果没有你的帮忙，这一切都不可能成真。', '你和维兹罗收集好试剂了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9435, '遗失的水晶', '关于希尔斯布莱德，我这里有个真理要告诉你，那就是：这片土地命中注定是要笼罩在战争阴影之下的。即使是一辆装满石头的无害马车，也会成为被攻击的目标。$B$B如果只是丢了一辆装满建筑材料的马车，倒也无伤大雅，可这辆马车上偏偏装有从碧玉矿洞运来的一箱稀有水晶样本，那正是我十分想研究的。被遗忘者的小分队截走了这辆车，把它带去了东北方的一处他们想要重建的哨塔里。回收这些水晶是当前最紧迫的事，$c！', '从被遗忘者手中夺回一箱稀有的水晶，把它交给南海镇的忽尔兰。', '感谢圣光!从工头信中的语调看来，那箱水晶似乎蕴含着矿坑里唯一所知的样本。如果我们弄丢了它们，$N，我们就永远也看不到这样的东西了。$B$B我太感谢你的帮忙了。$B', '你从被遗忘者那里夺回了水晶吗?', '', '去希尔斯布莱德丘陵找南海镇的忽尔兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9436, '血顶巨魔的魔法', '很高兴见到你，$c。我当前正在进行一项行为学调查，研究我在旅途中所见到的各个巨魔部族的不同战斗技巧。当前，我发现了一种很有意思的趋势：最北边的伽什废墟和巴拉尔废墟的血顶巨魔使用着一种与北方森林中的阿曼尼巨魔相似的战术。$B$B他们的魔法与其它巨魔的不同，形成了一种十分独特的分支。他们利用这样的魔法成为了这里最强大的部族。这或许是对抗阿曼尼巨魔的关键，但在那之前，我得先找到更多的研究素材。', '格罗姆高营地的纳密斯·鹰眼希望你能从某个血顶萨满祭司身上带回一个血顶图腾给他。', '做的好。现在，这很令人好奇……$B$B这个图腾上的铭文是用巨魔不可能学习的语言所写的，但却是我们可理解的语言。持有者的名字是一个叫奈亚斯的水元素盟友并注明他是值得引导其力量的人。$B$B这真是意想不到，但也不完全那么糟，$N。有你的帮忙，我想更进一步研究它。', '别让我失望，$N。如果我们可以让这个血顶魔法屈服在我们的意志之下，我的人民就能消灭阿曼尼威胁了。', '', '去荆棘谷找格罗姆高营地的纳密斯·鹰眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9437, '黎明号的黄昏', '这些浑身酒臭的食人魔除了能讲些粗俗的笑话，玩脑袋撞来撞去的蠢游戏之外简直一无是处。我的船“黎明号”搁浅时，塞拉摩的那帮混账抢走了我的货物，虏走了惟一幸存的船员。我千辛万苦来到此地寻求帮助，可是当我试图向食人魔讲述这段遭遇时，这群没用的废物只会茫然地盯着我。$B$B你是个值得信赖的$r，请转至东北方的北点哨塔取回残存的货物，搭救我的大副伊萨妮亚吧。', '转至北点哨塔，从塞拉摩军队手中夺回黎明号的货物，搭救大副伊萨妮亚，然后返回蕨墙村向巴尔兰达·新星复命。', '做的好，$N!只要等伊萨妮亚休息一下，我的准备完成后，我们就会离开这个荒地回到文明世界。', '你从那些光鲜亮丽的私掠船员手中救出了伊萨妮亚并取回我的货物吗?', '', '去尘泥沼泽找蕨墙村的巴尔兰达·新星。', '', '从北点哨塔营救伊萨妮亚', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9438, '通知萨尔', '自从我们踏上外域土地的第一步起，酋长就一直在等待着这一刻。现在，你将荣幸地亲自将玛格汉的消息告诉他。$B$B快去吧，$N。带上这封信，这里已经盖上了我的私人印章。没什么消息比你所带去的这个更能令他高兴了。', '转至奥格瑞玛，将纳兹格雷尔的来信交给萨尔。', '<当萨尔开始阅读纳兹格雷尔的讯息时他的嘴巴跟着微张。>$B$B我的人民……我们一定要去找他们。我们一定要尽快转至纳格兰!', '你从外域带来消息，$C?快说!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9439, '被抢走的财物', '这里就是卡加斯？啊，天啊……我还以为这里是一处……一处……呃，一处城市，一处荒野中的文明象征。$B$B看来我是大错特错了。这样几间挤满了脏兮兮、只会咧嘴傻笑的野蛮人的劣质小木屋怎么有资格被称作远征军的总部？当我告诉这群粗鄙无礼的野蛮人，一群黑铁矮人抢劫了我然后溜进苦痛堡垒的时候，他们竟然敢嘲笑我。我想，只有你才能帮助我夺回财产和尊严了，是不是？', '从苦痛堡垒中夺回顾问的背包和顾问的细剑，然后向卡加斯的顾问萨洛法斯复命。', '你是个神奇的工作者，$N!我告诉你，我这一生从没这么渴望换衣服过。$B$B还有我的细剑!没有我的剑感觉就像被扒光了衣服一样。$B$B你会因你的努力被赞赏和奖励。别让人说萨罗法斯没感谢帮助他的人!', '看在逐日者的份上，别盯着我看!我被迫穿着这件肮脏的衣服就已经够糟的了!在我经历过这么多事后，我最不希望的一件事就是被人盯着看。你从那些黑铁矮人称为堡垒的狭小地窖收集到我的财产了吗?', '', '去荒芜之地找卡加斯的顾问萨洛法斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9440, '一点食物', '我正在想办法强化一件可以用来对付德莱尼人的武器，你一定要帮助我！$B$B失落者是德莱尼人退化后的产物，我打算用他们来做实验。我只需要你喂一些污染过的饲料给失落者圈养的牲畜吃，就可以了。这样一来，他们屠宰这些牲畜并吃下它们的肉以后就会被诅咒啦！避难营的学者阿弗恩必定手足无措！$B$B快去快去！在农田避难所的东北方向就可以找到失落者和他们的牲畜笼。', '将邪恶侵蚀的食物喂给被失落者捕获的猎物。然后将剩馀的饲料带回去交给悲伤沼泽斯通纳德的瑟尔希·暗歌。', '喔，太棒了!我等不及要验收最近这一批货的效果了!$B$B嗯，你做了一件令人钦佩的工作，甜心。真希望我能给你比这个更多的东西来感谢你提供的娱乐，但你能了解的。沼泽这里没什么钱可赚。$B$B我相信为了乐趣这也是值得的!$B', '你把所有的食物都喂了他们被捕捉的动物吗?慢着!你没有给关在笼子中那些愚蠢的人类吃吧?，你有吗?$B$B喔，很好!不然真是浪费食物!', '', '去找悲伤沼泽的瑟尔希·暗歌。', '喂食被捕获的鳄鱼', '喂食被捕获的沼泽虎', '喂食被捕获的狼蛛', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9442, '虚弱的疾病', '$N，你肯帮忙真是太好了。步兵们误饮了被污染的水后都病倒了，眼下我正缺一种药材来配制治疗药膏。我需要一种罕见的蘑菇——枯顶蘑菇。$B$B我们的首要任务是确保玛格汉岗哨的隐秘性，因此我不能冒险外出寻找药材。地狱火半岛上，只有岗哨南边的大裂隙一带的某处洞穴中生长着枯顶蘑菇。$B$B如果你要去那儿寻找蘑菇的话，请加倍小心。', '从大裂隙的洞穴中采摘一朵枯顶蘑菇，将其交给地狱火半岛玛格汉岗哨的唤地者利迦。', '葛坎说了你一些好话。它们果然是真的。$B$B谢谢你的帮忙。', '你取得了我需要的蘑菇吗，$N?', '', '去地狱火半岛找玛格汉岗哨的唤地者利迦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9443, '所谓的光明使者印记', '我曾是白银之手骑士团的创建者乌瑟尔·光明使者的学徒。我曾亲眼见到他教育阿尔萨斯王子时候所遭遇的失败。这也使我的家乡奎尔萨拉斯遭遇了毁灭的命运，这都是乌瑟尔的错，都是因为他的无能才导致了这一切！现在他还居然有一座像模像样的陵墓，而且还有人纪念他，真不错啊！$B$B我的线人告诉我，血色十字军在壁炉谷大门附近的一座哨塔顶上保留了一件他留下的圣物。$B$B去西瘟疫之地把它取来给我。', '拿到光明使者的印记，把它交给西瘟疫之地亡灵壁垒的麦拉·黎明之刃。', '第一步完成了。把光明使者的印记交给我，我就会将它变成更适合的东西。$B$B然后我的复仇就会真正开始，$C!', '等你取得了他的\'记号\'，我们就要把它做些改变;让它变的更好。', '', '去提瑞斯法林地找亡灵壁垒的麦拉·黎明之刃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9444, '亵渎乌瑟尔之墓', '这样就好多了。我已经在其中加入了一些邪恶的魔法。$B$B现在，你必须把这个东西带到他那坐落在西瘟疫之地的陵墓去，在乌瑟尔的雕像前使用这个已被亵渎的神圣符记！你一定要接近那里，这样才能完成任务。$B$B你只需要从安多哈尔遗迹的西南侧沿路过去就可以找到他的陵墓。完成任务后再回来找我。$B$B动作快些，$c！', '亵渎乌瑟尔之墓，并向西瘟疫之地亡灵壁垒的麦拉·黎明之刃复命。', '原谅我?他原谅我?!!!$B$B我不在乎那个老鬼魂要说什么 - 那是他的错!所有发生在奎尔萨拉斯的事都是因为他的无能!$B$B很明显亵渎并没有发挥作用。去吧，消失在我的视线!我一定要好好想一想。', '那么，完成了?乌瑟之墓被亵渎了?', '', '去提瑞斯法林地找亡灵壁垒的麦拉·黎明之刃。', '亵渎乌瑟尔之墓', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9446, '光明使者之墓', '现在你已经夺回了光明使者的印记，剩下的事就是把它交还到乌瑟尔之墓去了。$B$B你愿意陪同我完成这件事吗？这里离陵墓并不远，我也很希望你能陪伴我一起去。等下回来之后你可以再向高阶牧师玛多妮尔汇报这件事。$B$B你觉得怎么样，$N？', '护送学者特卢恩转至西瘟疫之地的乌瑟尔之墓，然后与西瘟疫之地冰风岗的高阶牧师玛多妮尔谈一谈。', '光明使者在你之前出现?真是太令人惊讶了!而你对隐士无私的帮忙让一切都成真了。$B$B如果这故事有一半是可信的，那乌瑟真的是好人。还有，你就像他一样，都是艾泽拉斯所有好人中真正的英雄，$N!', '你不是该和隐士.楚恩一起走到乌瑟之墓吗?', '护送学者特卢恩转至乌瑟尔之墓', '去西瘟疫之地找冰风岗的高阶牧师玛多妮尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9447, '治疗疾病', '我利用你采摘到的蘑菇配制好了一剂治疗药膏，它能帮助步兵恢复体力。带上药膏医治岗哨附近疲惫的步兵，完成任务后回来向我复命。', '唤地者利迦要你对地狱火半岛玛格汉岗哨附近的那些疲惫的玛格汉步兵使用治疗药膏，医治10个疲惫的玛格汉步兵。', '愿灵魂祝福你，$N。玛格汉永远欠你一份人情。', '你回来了，$N。你的任务完成了吗?', '', '去地狱火半岛找玛格汉岗哨的唤地者利迦。', '治愈疲惫的玛格汉步兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9448, '阿弗恩的怜悯', '那个血精灵女巫瑟尔希·暗歌一直在诅咒失落者，我敢肯定！我不知道这是为了什么，她又是怎样做的，但这一切的结果都是悲剧。一些失落者当前被腐化得更深了，邪恶的能量充斥着他们体内！$B$B$C，你是否感觉自己有些可怜这些生物了？他们不应该在这样可怕的状况中继续活下去。$B$B你在农田避难所就可以找到这些被诅咒的失落者，只需沿路一直向东。', '杀死3名被诅咒的失落者，然后向悲伤沼泽避难所的学者阿弗恩复命。', '那么就完成了。感谢你展现你的怜悯。一旦被瑟赛喂给他们的任何东西而导致腐败，就没有什么办法可以解决。\r\n\r\n他们现在很平静，希望我对其他元素的研究也能有个结果，让他们恢复原状。', '你做了正确的事，$C。失落者已经受了这么多苦难。他们不该再忍受这样的屈辱。', '', '去找悲伤沼泽的学者阿弗恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9450, '大地的召唤', '突如其来的德莱尼人严重破坏了埃门谷中的元素平衡。飞船坠落，激怒了大地之灵；其它元素生物赶来平息这场骚乱，却遭到了强烈的反击。元素们只有在和睦相处的情况下才能达成默契。$B$B因此，你得承担起促成元素间平衡的重担。在我身后的这片树林中，躁动的大地之灵正在与其它三种元素交战。请设法重建元素间的平衡。', '杀死4个躁动的大地之灵，然后向埃门谷的元素圣谷中的峡谷之灵复命。', '你做得很好。削减不安的灵魂你就能帮助治疗元素间的不平衡，那也是你的人民无意造成的。$B$B在你的萨满之旅中，当你召唤我们的力量时一定要记住这点。一定要保持平衡。', '在我看来元素还是处在失衡状态，$N。', '', '去秘蓝岛找元素圣谷的峡谷之灵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9451, '大地的召唤', '现在我就将一块取自我身体的碎片交给你，你可以用它来制造大地图腾。回去向派你来这里的人复命吧。$B$B我们的命运从此紧密相联，大地的力量将永远与你相随。等到你离开尘世之日，尸骨回归大地，万物在轮回中达成平衡。$B$B好好运用我们的力量吧。', '将大地水晶交给埃门谷坠毁点的费曼瓦尔。', '你做得很好，$N。在帮助树林的元素取得平衡时，你也创造了德莱尼和这世界的大地元素间的平衡。或许这也会为那些不认同我们的人带来一点谅解?$B$B我会帮你制造一个图腾，让你可以召唤大地的力量。时间久了，你就会知道更多大地的秘密。$B$B现在，带走你的图腾吧，萨满。', '破碎者和德莱尼会一起重获对元素秘密更深的了解。$B$B你带回制造大地图腾所需的物品了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9452, '美味的红钳鱼', '我发现这里的水中到处都是这种活蹦乱跳的红钳鱼，这种鱼味道可棒啦！只要有一张渔网，我就可以捞到许多的鱼给许多德莱尼人吃了！可惜的是，我前几天在河边捞鱼的时候被一群鱼人给偷袭了，它们还把我打伤了，让我没法继续捞鱼。我需要帮助，需要帮助！$B$B在东边晶水河里的红钳鱼群旁使用这张渔网捞一些鱼吧。$B$B怎么样？能帮忙吗？干完记得把渔网也还我。', '使用德莱尼渔网抓住10只红钳鱼。任务完成后把鱼和渔网交给秘蓝岛的迪泰娜。', '我希望鱼人没造成太多麻烦，$N。你所做的事让我欠你太多了。$B$B或许我可以教你如何钓鱼?我甚至可以提供钓鱼竿和小玩意。', '小心鱼人:奇怪又特别讨人厌的小生物。', '', '去秘蓝岛找埃门海滩的迪泰娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9453, '找到艾克提恩！', '你做得非常不错，$N。我们的人民一定会对你能够施以援手表示非常感谢。说到这个，你愿意帮我将这些红钳鱼带给他们吗？只需要带去给碧蓝岗哨的艾克提恩就可以啦。$B$B他一直在等待着这批鱼，你应该不难找到他。', '将一箱红钳鱼交给碧蓝岗哨的艾克提恩。', '可怜的狄克泰纳……那个鱼人把她吓了一大跳。$B$B<艾克缇昂叹气。>$B$B希望她的伤会很快好起来……$B$B我想你是来找工作的。嗯，在蓝色守望有很路复用作可找!', '你觉得我的护甲怎么样?我自己制作的!这和我们习惯上穿的不太一样，但却极为舒服。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9454, '狩猎月痕鹿', '你最近越来越有名了，$N。要不要也来尝试一下狩猎？$B$B在德拉诺的时候，我们族中最优秀的猎人经常会狩猎一种名叫塔布羊的生物，它和这片地区的月痕鹿倒是十分相似。$B$B如果你认为自己非常具备德莱尼猎人的气质，不如到野外去尝试猎杀月痕鹿吧，一定要把你的背包装满月痕鹿肉再回来。$B$B碧蓝岗哨南边就有许多月痕鹿，小心别被它们的角顶伤！', '将6份月痕鹿的嫩腰肉交给碧蓝岗哨的艾克提恩。', '做得好，$N，做得真好!$B$B来，你不在的时候我煮了一些嫩腰肉。或许你也想要食谱?', '成鹿皮革容易损坏也因此形成柔软多汁的鹿肉。', '', '去秘蓝岛找碧蓝岗哨的艾克提恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9455, '奇怪的发现', '这块你从夜行豹幼崽身上找出的水晶看起来应该是埃索达的一部分。这样或许就能解释为什么这个地区的动物有着大量反常的行为和举动了。$B$B将这块水晶带回碧蓝岗哨，大主教一定非常想要了解这个小发现。', '将微微发光的水晶交给碧蓝岗哨的大主教梅内莱厄斯。', '这种东西怎么会跑到夜间潜猎者的胃里?失事的残骸已经让更多野兽感染了吗?', '你找到了什么?在哪里?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9456, '清理夜行豹……', '对于你的发现，我不会用任何借口或是理由来搪塞。这的确是我们的错。我们已经收到报告说坠毁时崩裂的水晶碎片流入了东边的河水中，不过我们还暂时没有采取行动。现在，我们要么只是坐在这座小岛上朝天哭诉着岛上发生的悲剧，要么干脆真正站出来做些什么，以阻止悲剧的蔓延。$B$B现在，我希望你能立刻回到荒野中去，尽量杀死更多已被感染的夜行豹。', '碧蓝岗哨的大主教梅内莱厄斯要求你杀死8只感染的夜行豹幼崽。', '我只希望这一切不会太晚……', '我们不能冒险让感染继续扩散。我从血色守望收到的报告已经够糟了。这一定要现在就被阻止!', '', '去秘蓝岛找碧蓝岗哨的大主教梅内莱厄斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9457, '不寻常的发现', '这么说，这个奈亚斯就是使血顶巨魔掌握了这种奇特法术的幕后主使者？我不得不承认，调查走到这个方向，是我当前最不希望看到的。但无所谓，我们的发现肯定是有用的。$B$B在海岸西北方有一座小岛，当前它被许多次级水元素占据了。那里还有一块巨大的厚石板，或许是巨魔们用以祭祀水元素的祭坛。将你找到的图腾带到那个祭坛去，看看我们是否能够引出这个奈亚斯，然后将他的力量转化为另一种我们更喜欢的形式。', '在奈亚斯祭坛附近使用奈亚斯的礼物，召唤出水元素奈亚斯。击败它之后，将奈亚斯之心交给格罗姆高营地的纳密斯·鹰眼。', '我可以感觉这个宝石里蕴含的纯粹原始力量，$N。我会把它送到银月城让我们的博学者做进一步的研究，但我相信它一定能帮助我们对抗阿曼尼。$B$B你取得这个宝石的努力是无价的，我会让远行者知道是哪个$r让这个发现成真。', '有奈亚斯的消息吗，$N?', '', '去荆棘谷找格罗姆高营地的纳密斯·鹰眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9460, '窃取情报', '克尔图斯·暗叶报到！$b$b呃……但你是谁呢？如果你是为我的报告而来，那你就得先帮我一个忙。$b$b我准备袭击暗夜精灵哨兵部队的间谍，但我打算让我忠实的蝙蝠维丝帕尔去打头阵。她需要嗅到敌人的味道才能确定攻击的目标。$b$b你能悄悄进去，在哨兵部队的首领身上为她找到一些东西吗？', '克尔图斯·暗叶希望你能从哨兵队长身上偷取一张花边手帕。', '太棒了!这样的私人物品带着强烈的入侵者气味 - 足以引导私语进入他们的军队……', '你弄到了吗?', '', '去找永歌森林的克尔图斯·暗叶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9463, '医疗材料', '我最近发现岛上的鞭笞者的枝条具备十分优良的治疗能力。经过适当的处理，我们可以把这些枝条制成某种强力的治疗药膏。但糟糕的是，碧蓝岗哨这里有太多受伤的德莱尼人，我们的药品存量已经严重不足了。$B$B而且，现在还有一名意外的可爱访客受了重伤，躺在这里。昨天，我们发现她倒在了晶水河旁，并且失去了意识。如果你能收集一些枝条来，我想我们就能救她一命了。$B$B碧蓝岗哨的东面和南面都有根须诱捕者出没。', '碧蓝岗哨的学者法蒂玛希望你帮她收集8份根须诱捕者的枝条。', '让我们期望这个药膏会强化她的灵魂吧!', '我担心她的病况正持续恶化中。', '', '去秘蓝岛找碧蓝岗哨的学者法蒂玛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9465, '火焰的召唤', '我的一个名叫赫图尔的同胞已经被你们那艘坠毁的飞船弄疯了。他开始要求当地所有的枭兽膜拜他。$B$B一定要制止这样的行为！我们不能狂妄地以为自己是个神灵！恢复平衡的重任就交给你了。$B$B首先，你必须到西边的止松要塞去，取回被那里的疯狂枭兽抢走的仪祭火炬。$B$B将火炬带回来给我。', '取回仪祭火炬，把它交给秘蓝岛灰烬林地中的坦普。', '看到它的火焰永远都不会熄灭了吗?那是郝特的杰作。那是他自大的象征。火焰本来就是要消耗，燃烧殆尽后自行熄灭，等待下一次重新再来。$B$B我会帮你弄熄火焰，但你要对付郝特的话它就一定要是点燃的。我们会让它燃烧久一点。', '你拿到火炬了?', '', '去秘蓝岛找灰烬林地的坦普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9466, '通缉：黑色利爪', '游侠队长有令，悬赏捕杀邪恶的剥石者母兽——黑色利爪的勇士。$B$B黑色利爪最近一次被发现是在大裂隙的某处洞穴中。取回它的爪子，以此为证领取奖赏。', '将黑色利爪的爪子交给地狱火半岛猎鹰岗哨的游侠队长维恩雷。', '你是个勇敢的$C，$N。那个野蛮的野兽夺走了我手下许多最棒的猎人性命。$B$B收下这个奖励，你赢得了它。', '你有黑爪的消息?', '', '去地狱火半岛找猎鹰岗哨的游侠队长维恩雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9467, '火焰的召唤', '西南边秘银岛上有一处月翼洞穴，那里的枭兽都被赫图尔迷惑了，认为他是值得崇拜的神明。但他其实只是一个堕落的元素生物而已，只有终结他的生命，才能终结他的痛苦。这把火炬是毁灭他的关键之物。$B$B赫图尔会定期要求这些枭兽以他的名义焚烧一座雕像。所以当你点燃雕像的时候，他就会出现。杀掉他，将他的灰烬给我带回来。我会给你一个小背包，里面的宝珠可以直接把你传送回来。', '取得赫图尔的灰烬，把它交给秘蓝岛灰烬林地中的坦普。在你得到灰烬后，可以用背包里的回归宝珠传送回坦普身边。', '你今天上了很宝贵的一课。这是个结束和新开始的故事。$B$B当我们第一次交谈时，我告诉你火焰不只是毁灭，也是重生的元素力量。你的行为同时摧毁和拯救了郝特，因为他会从他的灰烬中重生。', '没拿到郝特的骨骸就不要来跟我说话。', '', '去秘蓝岛找灰烬林地的坦普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9468, '火焰的召唤', '今天你完成了一件非常重要的任务，它能帮助你加深对火焰的理解。记住，一定要对火焰保持崇敬的态度，这样才能不被它的力量吞噬。$B$B我将赫图尔的一部分灰烬留给你，这样你就可以用它来制造你的火焰图腾。记住你为了得到它所学到的东西。$B$B现在，回去找图伦吧。', '将赫图尔的灰烬交给秘蓝岛上的碧蓝岗哨中的图伦。', '你经历了火焰净化并重获新生，$N。这和德莱尼人民现在经历的磨难没什么两样。而藉由把郝特从他自身的堕落中拯救出来，你也拯救了你和这世界的元素火焰连结。', '你的衣服边缘看起来有些烧焦。你和火焰的交流进展的如何，萨满?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9470, '善意的表示', '辛特兰那崎岖而连绵的丘陵地区不仅仅是蛮锤矮人与狮鹫的家，也是许多森林巨魔部族的藏身之处。$B$B巨魔们将蛮锤矮人视作他们古老土地上的入侵者，从不放过任何通过攻击狮鹫来打击与挑衅蛮锤矮人的机会。想要在蛮锤矮人的眼中证明自己的价值，有一个最好的办法就是去杀死枯木巨魔的领袖，巫医麦金。这样就可以抑制住敌人对狮鹫的猎杀势头。巫医麦金藏在伯根的棚屋，就在沙德拉洛以西。', '鹰巢山的鲁雷斯大使要求你杀死巫医麦金和他的蜘蛛宠物查卡斯。', '做的好，$N。蛮锤会很高兴知道他们不是独自和枯木奋战。让他们知道联盟可以是保护狮鹫兽的可靠伙伴会让我们的论点更有份量一点。', '你带着巫医梅金的死讯回来了吗?', '', '去辛特兰找鹰巢山的鲁雷斯大使。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9471, '猎杀狼群', '蛮锤矮人一直以来都是狮鹫的伙伴，保姆和训练师。狮鹫的天敌非常多，特别是森林巨魔的部族中有许多猎头者。$B$B此外，有些时候，威胁则来自大自然的中的食肉动物，例如狼。单独的食肉动物无法与狮鹫对抗，但群居的食肉动物在猎物匮乏的情况下，会选择以狮鹫作为捕猎目标。捕杀狼群的话，可以降低它们对于狮鹫的威胁，也可以帮助我们联盟取得蛮锤矮人的好感。', '鹰巢山的鲁雷斯大使要求你杀死10只癞皮银鬃狼和5只银鬃狼。', '<当你交出你的报告时洛勒斯大使对你点点头。>$B$B你做的很好。银鬃被削减的事一定会让蛮锤知道。等我和他们的领导者见面时，我相信你的行为会在联盟中获得良好的回应。请收下这些钱以表达我的感谢，$N。', '你削减了银鬃的数量吗?', '', '去辛特兰找鹰巢山的鲁雷斯大使。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9472, '埃雷利恩的“恋人”', '有那么多重要的事情要做，埃雷利恩居然还能挤出时间去见他的“恋人”！$B$B这件事已经再清楚不过了。薇拉·火语，这个混账……我要让她知道跟魔导师作对的下场。$B$B带上这个卷轴去找薇拉。想办法诱使她离开岗哨，然后利用卷轴来对付她。$B$B埃雷利恩在日记中提到，她难以抗拒塞纳里奥德鲁伊的特酿热酒。转至地狱火半岛西边的赞加沼泽，或许你能在塞纳里奥庇护所买到这种酒。', '猎鹰岗哨的魔导师卡尔琳达要你诱使薇拉·火语离开岗哨，然后对她使用卡尔琳达的惩戒卷轴。', '非常好!那个小贱货暂时不会再跟别人的丈夫乱搞了。$B$B这是给你的一点小意思。我想这件事只有我俩知道就好，$N。', '嗯，$N。完成了吗?', '', '去地狱火半岛找猎鹰岗哨的魔导师卡尔琳达。', '使用卡尔琳达的惩戒卷轴', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9473, '备选方案的备选方案', '仅仅依靠这种药膏恐怕很难挽救她，她太虚弱了。或许还有其它的办法……$B$B秘蓝岛的森林中蕴藏着许多的秘密，其中之一就是某种名叫碧蓝金鱼草的稀有植物，这种植物据说是一种万能药，可以医治所有的病症与伤痛。$B$B这种植物的样子很容易鉴定，它与秘蓝岛上的其它植物在颜色上有着巨大的反差，一般都在生长在蓝松树下，还会闪闪发光。快去吧！$B$B哦，对了，$N，你还得小心那片地区的根须痛击者。它们以碧蓝金鱼草为食，或许会攻击你。', '碧蓝岗哨的丹达尔希望你帮他收集5株碧蓝金鱼草。', '看看这个植物神奇的效用!', '别浪费时间，$g男孩:女孩;。', '', '去秘蓝岛找碧蓝岗哨的丹达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9474, '光明使者的印记', '尽管我来到艾泽拉斯的时间还不长，但我已经了解到了许多这里的英雄事迹。在他们所有人当中，光明使者乌瑟尔无疑是最伟大的。虽然他最终被自己最得意的学生阿尔萨斯背叛，但乌瑟尔无疑仍是个顶天立地的英雄。$B$B为了纪念他，我希望能将一些东西归还到他的陵墓中。据说血色十字军保存着一件乌瑟尔的圣物，它被放在壁炉谷大门附近的一座哨塔上。$B$B$C，请帮我取回它。', '取得光明使者的印记，然后把它交给西瘟疫之地冰风岗的学者特卢恩。', '谢谢你，$C!取得这个神圣象征对我和其它尊敬怀念乌瑟.光明使者的人而言有着极大的意义。', '光明使者的印记是乌瑟对圣光信念的一个强大象征。', '', '去西瘟疫之地找冰风岗的学者特卢恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9475, '夺回狮鹫卵', '仔细检查过后，你猜测这具已经被彻底打扁敲碎了的骸骨应该属于羽须。骸骨的手中握有一张已经揉成一团，破烂不堪的纸张。你小心翼翼地将这张纸取下摊平，发现上面一张潦草手绘的地图和几句匆忙写下的笔记。$B$B地图看起来像是描绘着沙德拉洛附近的三座神殿，并且在几处地方画有“X”形的记号，想必那里就是藏匿被盗的狮鹫卵的地点了。你将地图小心折好，收进了背包中，打算在一处更安全的地方仔细检视它。', '收集5枚狮鹫卵，然后向鹰巢山的鲁雷斯大使复命。', '<将蛋交给大使，你描述在羽须小屋及沙德拉洛的发现。>$B$B枯木族杀了羽须?$B$B<洛勒斯的脸在你描述这位矮人的死及与洛勒斯的任务关连时恐怖的扭曲着。>$B$B我明白为什么他觉得必须去寻找这些蛋，但我希望他该想到带其它人一起去。他的死无疑将激怒弗斯塔德.蛮锤，并引发对巨魔的复仇，这必定会无限期地延后我们的会面。', '你脸上的表情说明你带来了坏消息。你发现了什么?', '', '去辛特兰找鹰巢山的鲁雷斯大使。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9483, '生命的乐趣', '', '', '你知道，或许我们可以成为朋友。跟我来;我们不想和别人分享这个东西，对吧?', '就因为我们参与这次的朝圣并不代表我们要放弃所有生命的乐趣。距离我上次喝杯好酒已经是好几世代前的事了。$B$B为了一瓶塞纳里奥烈酒要我杀人也无所谓!$B$B我知道，我知道，我怎么会这么落伍喜欢喝夜精灵酿的酒。', '', '去地狱火半岛找猎鹰岗哨的薇拉·火语。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9484, '驯服野兽', '为保护自己的安全和维持生计，你已经猎杀了许多野兽，现在你要学会如何亲近它们，指挥它们来帮助你。我会教你怎么去做的。$b$b带上这根魔法驯兽棒，它会让那些野兽暂时听从你的指挥，与你并肩战斗。在远行者居所外找到疯狂的龙鹰，那是一只非常容易驯服的鸟。将它驯服之后回来向我报告。', '使用驯兽棒驯服一只疯狂的龙鹰，然后向达恩·晨行者中尉复命。', '能抵挡龙鹰无数的爪子和噬咬就显示了你的韧性。你有力量学习更多东西吗?', '你制服龙鹰了吗?', '驯服一只疯狂的龙鹰', '去永歌森林找远行者居所的达恩·晨行者中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9485, '驯服野兽', '你做得很好，$n。你对大自然的理解在不断加深。$b$b迷雾蝠是一种狡猾的猎手，它们拥有龙鹰的敏捷和魔泉豹的凶残。跨过南边的艾伦达尔河就可以找到它们，这些蝙蝠常常埋伏在路边，袭击无辜的行人。$b$b带上最后这根驯兽棒去驯服一只迷雾蝠，完成任务后回来向我报告。', '使用驯兽棒驯服一只迷雾蝠，然后向达恩·晨行者中尉复命。', '你看$N，我已经没有东西可以教你了。你已经知道如何与你猎捕的生物当朋友了。你只需要从这些自然的盟友中挑选一个和你特性相符的。', '你驯服迷雾蝙蝠了吗?', '驯服一只迷雾蝠', '去永歌森林找远行者居所的达恩·晨行者中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9486, '驯服野兽', '老魔泉豹是一种高效而且敏捷的猎手。在你尝试驯服它的时候，它会认为你是它的猎物。不要因此而退却。$b$b带上这根驯兽棒，去驯服一只老魔泉豹吧，它会成为你最佳的狩猎帮手。永歌森林中到处都有老魔泉豹，有一些还经常在这附近出没。当你学习到足够的经验之后回来找我。', '使用驯兽棒驯服一只老魔泉豹，然后向达恩·晨行者中尉复命。', '你同时展现了力量和韧性。剩下最后一个考验你就能不使用魔法来驯服了。', '你和泉爪山猫一起打猎了吗?', '驯服一只老魔泉豹', '去永歌森林找远行者居所的达恩·晨行者中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9487, '奥术掠夺者', '奥术掠夺者是野蛮粗暴的魔法生物。它们装备着重甲，可以轻而易举地击晕对手。但是，你可以无视奥术掠夺者的防御能力，避开它们的攻击。$N，这就是你作为法师的优势。$B$B转至晨星之塔轰杀奥术掠夺者，从它们的残骸中收集蕴藏着魔法能量的结晶碎片。晨星之塔就在东边的湖泊对岸。', '奥术师范迪瑞尔要你为他收集10块奥术残片。', '真是浪费，使用魔法来建造有肉体力量的生物。毕竟，我一直认为那是我们和较弱的种族结盟的原因。$B$B你摧毁他们是对的，这样我们就能把残存的物质拿来做更好的运用。', '你没靠那些畜生太近吧?', '', '去幽魂之地找塔奎林的奥术师范迪瑞尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9488, '简单的长袍', '你收集的这些奥术残片很不错。$B$B想知道做什么用？为你这样的$c制作一件漂亮的长袍！$B$B现在我们只需要一些亚麻布和一个纺丝蜘蛛的丝囊就万事俱备了。你可以在纺丝蜘蛛身上找到丝囊，当然首先你得杀死它们。', '将15张亚麻布和1个纺丝蜘蛛的丝囊交给奥术师范迪瑞尔。', '你真的不必知道制作一件魔法长袍的复杂手续，$N，你只要知道把什么带给我就好。$B$B老实说，你带来的东西可以做好几件长袍。我赚到的利益会比制作你的长袍所需的花费还多，甚至还够买一些好东西给我自己。看来要好好感谢你了!', '没有必须的材料就无法完成长袍。但你知道这点，对吧?', '', '去幽魂之地找塔奎林的奥术师范迪瑞尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9489, '清理死亡之痕', '$N，你能来真是太好了。天灾军团在不断袭击我们的城市，我担心守卫们会丧失士气。$b$b杰拉和她的游侠在南边的死亡之痕严阵以待，你赶紧到那里去，召唤圣光的力量为他们祝福吧。', '对死亡之痕的6个永歌游侠施放真言术：韧。', '游侠们已带着敬畏和尊敬提到你的祝福了。现在你知道圣光对我们多重要了，让我们能帮助他人，不过要在我们先帮助自己之后。', '你给予他们希望了吗?', '', '去永歌森林找鹰翼广场的珀纳瑞斯。', '祝福永歌游侠', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9490, '剥石者的女王', '生活在岩石地域的掠夺者是一种狡诈而好斗的生物，它们的一生是短暂而凶暴的。不过，跟它们种群的女王“凶猛的黑色利爪”相比，普通的掠夺者都简直跟鹦鹉一样乖巧了。$B$B我的堂弟就是被这个所谓的女王给吃掉的，唉……我发誓总有一天要让这只“黑色利爪”付出代价。如果你能将它死亡的证明带回来给我，我愿意把我一生的储蓄都给你算作报酬，你觉得怎么样？$B$B哦，对了，你最好带上一些高大威猛，而且装备精良的朋友们一起去。那只黑色利爪就在大裂隙的洞穴中，你很容易就能找到它，祝你好运！', '转至大裂隙杀死凶猛的黑色利爪，将黑色利爪的爪子交给地狱火半岛塔哈玛特神殿的伊坎。', '没错，我记得这些锐利的爪子!$B$B收下这个奖励，$N。你完成了一个危险的任务。你值得这些奖励。', '你带回黑爪死亡的证据了吗，$N?', '', '去地狱火半岛找塔哈玛特神殿的伊坎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9491, '贪婪', '昨天有位浑身铜臭的富商路经此地，他说阿曼尼墓穴中埋着无数带锁的箱子，其中一只箱子中放置着一枚“极具考古价值”的戒指。他对戒指的来历避而不谈，只是反复强调自己愿意出重金换取这枚戒指。$B$B这样吧，我来提供盗贼工具，如果你能帮我取回戒指，我付给你的钱足购让你买十枚戒指！', '转至阿曼尼墓穴取回陪葬的金戒指，然后向塔奎林的艾拉兰复命。', '这就是那枚戒指，对吗?没什么好看的，但你知道他们怎么说一个精灵的垃圾……$B$B别忘记你的酬劳。在这里就可以花掉它$g宝贝:姐妹;!', '请告诉我你找到戒指了。那个商人不久后就会找上他自己的盗贼了。', '', '去幽魂之地找塔奎林的艾拉兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9492, '扭转战局', '身在外域，你所必须面对的数个悲惨事实之一就是：这片土地长久以来一直笼罩在邪兽人势力的阴影之下。我们洛萨之子曾相信自己已用鲜血换回了荣耀堡片刻的安宁，可事实上，真正的和平从未降临过这里。$B$B洛萨之子绝对不会向任何兽人屈服，无论他们的皮肤是绿色，棕色，还是现在的红色。我们要么战胜他们，要么全部光荣战死。要想获得真正的胜利，就必须攻下地狱火堡垒。现在，去把他们那个自封为“酋长”的卡加斯·刃拳干掉，你会得到封赏的。', '将卡加斯酋长之拳交给荣耀堡的远征军指挥官达纳斯·托尔贝恩。', '做的好，$N。有你在地狱火堡垒的胜利，我们就对兽人造成了很大的打击。$B$B我一定要和战场元帅洛摩斯谈谈接下来的事，并确定兽人保持在防守状态。既然我们有了援军，就能做比防御荣耀堡更多的事。', '你带回“大酋长”卡加斯.刃拳死亡的证据了吗?', '', '转至地狱火半岛，去找荣耀堡的远征军指挥官达纳斯·托尔贝恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9493, '邪部落的荣耀', '我们对于地狱火堡垒内邪部落的存在所知确实甚少，而且，就这样一点信息，也付出了许多生命的代价。$B$B邪部落的各军团都由卡加斯·刃拳指挥，他们残忍，好战，并因邪恶魔法的加持而拥有无穷尽的力量。其中的精英是碎手军团，他们的军团士兵、勇士和百夫长都深受其它士兵的敬畏，是其它军团的中下层军官。$B$B尽可能地消灭他们吧，这将是我们破坏邪部落领导和指挥体系的作战中最为重要的一步。', '荣耀堡的战地指挥官洛姆斯要求你杀死8名碎手军团士兵、4名碎手百夫长和4名碎手勇士。', '这是个很棒的消息，真的，$N。有了地狱火堡垒的报告进展，我们或许可以把注意力转到出现在半岛和外域其它地方的魔狱部落。', '我不会天真到认为击败了破碎之手军团士兵就预告了我们对魔狱部落的胜利，但这的确是个很好的开始。', '', '转至地狱火半岛，去找荣耀堡的战地指挥官洛姆斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9494, '邪能灰烬', '艾泽拉斯那边的老学究们看来是龟缩在高塔里太久太久了，向大家展示真正尖端的研究成果的重任显然已经落在了我的肩膀之上！他们不敢玩火，没关系，我敢，即使是双手都被火焰吞噬也没什么。$B$B地狱火堡垒内的破碎大厅里的高阶术士奈瑟库斯拥有一对神秘的火盆。凭借这个，他就可以进行某种强大的召唤仪式。用他的容器装着邪能灰烬，给我带一份回来，$N。', '荣耀堡的大法师萨布兰希要求你给她带回一块邪能灰烬。', '做的好!我不期望模仿大术士奈德克斯的技艺，我也不渴求，但如果忽略魔化馀烬的力量那我们就是蠢蛋了。$B$B不过，还是有些人会禁止我要着手的研究类型，因此，我的努力一定要保密。拜托不要跟任何人说起这些事，$N。', '<魔导师萨柏瑞希斯扫视了一下艾咪希.迷雾长者并压低她的声音。>$B$B你把，呃，馀烬带来了吗?', '', '转至地狱火半岛，去找荣耀堡的大法师萨布兰希。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9495, '酋长的意志', '将所有的兽人从腐化之血的诅咒中解救出来，这远远没有想象中的那么容易，$N。萨尔酋长已经目睹了太多兽人英雄倒在命运之手的操控之下。现在，似乎卡加斯·刃拳也要落到这个下场了。$B$B卡加斯·刃拳当前正在地狱火堡垒的破碎大厅当中做着他的白日梦，宣称他是那个邪部落的唯一的“酋长”。有了那群狂热而嗜血的军团的帮助，他不将萨尔玛夷为平地是不会善罢甘休的。萨尔酋长已经下了命令，不惜一切代价消灭卡加斯和他的军团。', '将卡加斯酋长之拳交给萨尔玛的纳兹格雷尔。', '你做的很好，$N。卡加斯.刃拳在壮年期间是个优秀的战士，是他人民的英雄和典范。$B$B他的死对我们所有人都是个打击，尤其是对大酋长萨尔而言。在他最后的日子里，不管发生了什么事，我们都不该忘记卡加斯曾经是怎样的兽人，也不能忘记他的死带给我们什么样的教训。$B$B至于你对部落的效劳，$N，你可以在这些武器中选一个做为奖励。', '你有卡加斯.刃拳战败的证据吗?', '', '转至地狱火半岛，去找萨尔玛的纳兹格雷尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9496, '邪部落的荣耀', '大督军霍恩·重拳对邪兽人嗤之以鼻，但我们仍然不能小看邪部落的力量，$n。$B$B根据我们所掌握的情报，邪部落的各军团都由卡加斯·刃拳指挥，他们残忍，好战，并因邪恶魔法的加持而拥有无穷尽的力量。其中的精英是碎手军团，他们的军团士兵、勇士和百夫长都深受其它士兵的敬畏，是其它军团的中下层军官。$B$B尽可能地消灭他们吧，这将是我们破坏邪部落领导和指挥体系的作战中最为重要的一步。', '萨尔玛的暗影猎手塔金要求你杀死8名碎手军团士兵、4名碎手百夫长和4名碎手勇士。', '做的好，$N。既然军团士兵被击破了，在战场上挑战魔狱部落就会更容易，虽然他们仍是可怕的敌人。', '一旦破碎之手军团士兵被击破，我们就能开始进展对付魔狱部落的战役。你完成你的任务了吗，$N?', '', '转至地狱火半岛，去找萨尔玛的暗影猎手塔金。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9503, '水之召唤', '为了与其它的元素平衡，水元素是维系所有生命的源泉。它孕育了生命，所有的生命都离不开它。然而它一旦遭到污染，所有的生命都会灭亡。$B$B我们必须知道水被污染的程度。在西南边有一处被污染的水体，它被称作污淤之池。到那里去，帮我从居住在池塘里的水之魂身上找一些邪恶精华回来。', '收集6份邪恶精华，把它们交给秘血岛藏帆暗礁的阿奎欧斯。', '谢谢你，萨满。这些应该够我检验污染了。然后我们就会比较清楚该如何着手。', '你这么快就从我不幸的姐妹身上收集好腐败精华了吗，$N?', '', '去秘血岛找藏帆暗礁的阿奎欧斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9504, '水之召唤', '情况比我担心的更糟。污染相当严重，如果不加以制止的话，这片海洋乃至整个艾泽拉斯都会受到影响！$B$B我们需要一份未被污染的水源样本来对比污染的程度。这座岛的东南方还有未被污染的区域。到那里有怒鳞纳迦居住的废墟去，取得那里的泉水。$B$B带上这只波涛之袋，用它取得泉水样品。行动一定要快，$N！', '将水注满空的波涛之袋，然后把它交给秘血岛藏帆暗礁的阿奎欧斯。', '要分离水很容易，但把足够的水聚集在一起就会产生挡不住的力量。它冲刷泥土和火焰，轻易地将空气推到一边。$B$B我们就是那股阻挡不了的力量，$N，不是那些毒害了秘血岛的人!', '你从废墟弄来纯净的水了吗?', '', '去秘血岛找藏帆暗礁的阿奎欧斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9506, '第三类接触', '我是联盟海军司令部所属的海军上将奥德修斯。我们的船最近因为遭受到了多次袭击，被迫在你们的岛上停留下来。当然，说起来非常尴尬，我们前几天竟然被一些地精成功混上了两艘战舰，甚至被他们成功地避开了我们的斥候。$B$B昨天夜里，当大部分的船员都在船舱里睡觉时，他们突然出现并袭击了我们！$B$B更奇怪的是，他们只是拿走了我们的航海设备，然后就直接跳船了！$B$B后来他们消失在了东边的那处灌木丛中，你能过去帮我们搜索一下我们的装备吗？你可能需要使用武力。', '奥德修斯营地的海军上将奥德修斯希望你能夺回被风险投资公司偷走的航海罗盘和航海图。', '你真是个机智的人!有了我们的航海工具，我们就能知道自己偏离航道多少了。$B$B但是等等，这是什么?地图里还卷着一个东西。让我看看……$B$B这些是风险投资公司的穆戈尔欧.瑞斯丹克所下的命令。根据这些计画，他们想挖光岛上的水晶残骸，并在完成后劫走我们的船。$B$B我的老天爷啊!这是为什么他们要逼迫我们登陆吗?他们怎么会知道我们的计画?$B$B我闻到叛徒的味道……', '运气如何，陌生人?', '', '去秘蓝岛找奥德修斯营地的海军上将奥德修斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9508, '水之召唤', '我知道污染源在哪里了。这都是由于一些疯狂的研究活动所导致的，你必须去阻止它！$B$B在污淤之池西南边有一小片营地，你可以在那里找到正在进行“研究”的污染者塔希恩，他制造出的污染物渗透到了周围的水中。$B$B利用你在灰谷找到的纯水毁掉他的贮藏桶，他一定会跳出来的。$B$B我们必须让这一切都立刻结束！', '将塔希恩的徽记交给秘血岛藏帆暗礁的阿奎欧斯。', '那么就完成了!危险解除，你让秘血岛的水复原了。随着时间过去，水和其它元素结合后会自己治愈。$B$B不幸的是，血精灵并不知道污染了他们的环境，他们自己也会死亡的!', '你成功了吗?', '', '去秘血岛找藏帆暗礁的阿奎欧斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9509, '水之召唤', '我留下了一些你从灰谷带回来的水，这并非因为我怀疑你办事的能力。相反，我知道你一定能成功，我只是想确定你能将某些特别的东西带回去交给努波顿。$B$B给你，$N，带上这瓶纯净的水。有了它，你就可以得到一根有着强大力量的水之图腾。$B$B预言者努波顿在埃索达等着你回去。', '将纯水之瓶交给秘蓝岛埃索达的预言者努波顿。', '你展现了超出你年纪的智慧，$N。我可以感觉水元素对你的行为感到很满意。收下你带来的纯水并将它的精华与你新的水图腾结合在一起是我极大的荣耀。$B$B今后记得水的训诫，你将会对元素的认知和掌握了解更多。', '元素对我说了你完成的伟大事绩。来，让我们谈谈。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9512, '曲奇的大餐', '上将是对的，你可真是足智多谋。或许你能帮我做饭？$B$B要是我今天晚上又给船员们做鸡当饭吃，他们非把我丢去划舢板不可。$B$B其实，我发现这海边上竟然有这么多又肥又大的螃蟹，多到数不清！要不你给我打些螃蟹肉来吧，我一辈子也忘不了你这份恩情的。$B$B你就帮帮我这个从良的老海贼吧。', '奥德修斯营地的“曲奇”米维克索斯要你给他带回6块迅捷螃蟹的肉。', '愿你心想事成，陌生人。我还需要花一阵工夫才能提升船员的士气。', '啊……呃……喔天啊……嗯，抱歉$g小伙子:小姑娘;，我要练习一下海贼的事免得我忘记……', '', '去秘蓝岛找奥德修斯营地的“曲奇”米维克索斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9513, '夺回废墟', '大部分人都把我们流落到这里、陷入这种进退两难的境地视为不幸或时运不济，但我却感觉我们来到这里是有一个必然的原因。看不见的命运之手将我们推上了这条道路，很快那个原因就会逐渐显现。$B$B在西边有一座古代暗夜精灵的城市，现在已经是废墟了，并且它已经被纳迦占领。我绝对无法坐视纳迦盘踞在我们祖先的土地上不管。$B$B你已经展示出自己身为$c的优秀能力，请帮我清理遗迹中那些不受欢迎的客人，并以此纪念我的祖先吧。', '秘蓝岛奥德修斯营地的女祭司基琳·伊尔蒂娜要求你杀死5只怒鳞侍从、5只怒鳞纳迦和5只怒鳞海妖。', '赞美艾露恩!不安的灵魂终究会得到安息。', '你为我的人民做了一件好事，$N。', '', '去秘蓝岛找奥德修斯营地的女祭司基琳·伊尔蒂娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9514, '写满符文的石板', '你完全无法理解这块石板上所有符号所表达的内容。或许女祭司能够解读这些神秘的符文。', '将写满符文的石板交给秘蓝岛奥德修斯营地的女祭司基琳·伊尔蒂娜。', '我看不懂这些符文，不过我知道谁可以看懂……', '你找到什么了?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9515, '督军斯雷提兹', '纳迦的入侵绝对是灾难性的，$N。我曾见过纳迦所能造成的灾难，而且再也不愿再看见这种灾难降临在任何地方。我想，这个督军斯雷提兹就躲藏在岛上的某个洞穴之内，或许就在西边的海岸上。$B$B立刻找到督军斯雷提兹，结束他的统治吧。', '秘蓝岛奥德修斯营地的女祭司基琳·伊尔蒂娜要求你杀死督军斯雷提兹。', '督军司瑞史提斯一死，纳迦入侵的可能性就只是遥远的记忆了。我们安全了，至少当前是……$B$B我必须承认，我错看你了，$N。你让我知道你不像阿克蒙德那样的肮脏。收下这个做为夜精灵的礼物。', '保持警惕!', '', '去秘蓝岛找奥德修斯营地的女祭司基琳·伊尔蒂娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9516, '毁灭燃烧军团', '我绝不能容忍他们在这个世界存在！燃烧军团几乎彻底毁灭了我们的种族！我们被迫逃到了一个新的世界，创建了新的家园，可他们竟然又追了过来！这样的事情重复太多次了！$B$B不能再这样下去了！$B$B当前燃烧军团还有一部分残留部队盘踞在南边的冥火岭、屠魔峡谷和屠魔山。他们都是上次军团入侵时进入这个世界的馀孽。$B$B在一切还没有变得太糟糕的时候，赶快去把他们都清除掉！', '杀死6个玛诺洛克鞭笞者、6个恶魔守卫和6个灼热的地狱火，然后向灰谷林歌神殿的守备官维达尔复命。', '我尊敬你并感谢你，$C。或许我们可以在这里建立一个新家园而不用再担心燃烧军团的事。', '那些恶魔还存在吗?', '', '去灰谷找林歌神殿的守备官维达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9517, '可耻的浪费', '欢迎来到林歌神殿，$c。现在你还只能看到帐篷，但很快这里将拥有许多雄伟的建筑物。不过，要想将这里建设成心中梦想的样子，还需要源源不断的运送建筑材料过来。我是无法让我们的工人对这片树林中任何的参天古树做出任何砍伐行为的，但我们位于西南方的邻居对森林却没有任何尊重可言。$B$B我想，我们完全可以回收战歌伐木工们所造成的浪费，还可以从西边的萨特营地中回收一些被玷污的木材。将这些木材带给纳亚尔，他会把它们净化成我们可以使用的木材。', '将15块战歌木材和5块萨提纳尔木材交给林歌神殿的纳亚尔。', '用兽人粗糙的刀身砍下的木头一定是扭曲的，毕竟它暴露在极端的元素中', '<长者一边转向你一边发出咯吱声。>$B$B建筑师尼莫斯说你会从伐木者营地和污染的萨提纳尔带来木材。', '', '去灰谷找战歌伐木营地的纳亚尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9518, '毁灭的使者', '战歌伐木营地就是我们如锦缎般美丽的大地上的一处锈斑。每次我们暂时成功地阻止了他们，监工古尔萨克就会让他手下的伐木工加倍砍伐我们的树木！$B$B现在，兽人砍伐下的树木已经远远超过了他们所需要的，他们甚至就让那些砍下来的新鲜树木堆在一旁腐烂！这绝对不是我们所能容忍的，$N，我们一定要让他们知道，我们是绝对不会容忍任何毁灭我们土地的行为！$B$B去吧，战斗吧，直到监工古尔萨克和他的手下全都死掉为止！', '林歌神殿的哨兵卢希尔·星语要求你杀死监工古尔萨克、2台战歌伐木机、5名部落伐木工和10名部落斥候。', '我们终于发出一个兽人不敢忽视的讯息了。任何到伐木场替换高萨克的监督者或工头都会感受我的愤怒!$B$B我们一定要把握我们的优势，$N，而且在战歌伐木营地成为遥远的记忆，树木高耸在地上之前都不能停歇。', '只要监督者高萨克还活着，我就会对抗他。伐木场有什么消息?', '', '去灰谷找林歌神殿的哨兵卢希尔·星语。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9519, '失落的圣杯', '我们西边有一处叫作萨提纳尔的地方，过去曾是由我的人民所建的重要神殿。里面藏有一件名叫艾露恩的圣杯的无价圣物，艾露恩的祭司们曾将它交给神殿的守卫保管。据说这圣杯具有治愈之力，所以曾有无数的朝圣者前去祭祀。$B$B或许这听起来像是老婆婆讲的故事，但假如确实如此，那么或许这件圣物将是治愈这片森林的关键所在。我必须了解清楚，$N。', '将艾露恩的圣杯交给林歌神殿的凯尼斯·静风。', '做的好，$N。就算持续暴露在萨特的腐败气息中，这股力量也不会因此黯淡。就算经过了这么多年，你不是仍能看到它发出的光芒吗?', '你感觉到了吗，$N，腐败的气息弥漫在风中?如果我们什么都不做，它就会持续进展。这就是为什么我要寻找艾露恩酒杯的原因。你可以找到它吗?', '', '去灰谷找林歌神殿的凯尼斯·静风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9520, '恶魔的计划', '这张羊皮纸是恶魔留下的，最令人惊奇的是，上面的文字竟然是用通用语写的！这里提到了迪亚索鲁斯和戈加农，这是两个声名狼籍的恐惧魔王，它们统领着周围的恶魔。$B$B这里明确地写出了恶魔们进攻北面林歌神殿的具体计划。最近有一些德莱尼人在那里创建了新的营地。$B$B或许林歌神殿的守备官维达尔会对此感兴趣？', '将恶魔的计划交给灰谷林歌神殿的守备官维达尔。', '我的老天爷啊，不可能!他们计划要攻击我们林歌神殿?!$B$B有我在就不可能!$B$B<复仇者维达将恶魔草写的计划书在手中捏皱。>$B$B不。我们不会允许这样的事发生!$B', '你手里拿着什么，$g先生:小;?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9521, '北方前线的报告', '负责牵制与对抗战歌伐木营地的战争力量可不仅仅在林歌神殿，$N。在西南方靠近贫瘠之地边界的银翼树林，还有一处更为坚固的银翼哨兵据点。在树林的那一侧，哨兵艾蒂亚·轻歌负责领导着我军力量对抗那些试图破坏森林的敌人。$B$B我已经很长一段时间没有给哨兵艾蒂亚·轻歌送出我们的报告了，但当前的局势让我完全无法离开林歌神殿。如果你最近要经过银翼树林的话，是否能帮我送去我的报告书？', '将哨兵卢希尔的报告送给银翼树林的哨兵艾蒂亚·轻歌。', '谢谢你把这个报告送来，$C。从哨兵露西欧写的东西看来，我们最害怕的事情似乎要发生了。我们每有一点进展，每当我们有所进展，部落似乎就更加笃定地把伤害尽可能加大。$B$B我们不能放弃;我们先祖之地的命运悬而未决。只要前线有越多像你的人，我相信我们就能获得胜利。你会加入我们的战局吗?', '你手里拿着什么，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9522, '休想！', '$N，你必须想办法确保燃烧军团的这次进攻遭到挫败！去杀死这两只恐惧魔王！没有了他们，剩下的恶魔就会失去领导，变成一群无脑的生物。$B$B你可以在冥火岭正南方的屠魔峡谷中找到戈加农，就在玛诺洛斯那根悬浮在空中的短矛旁边。$B$B搜寻者迪亚索鲁斯住在屠魔山顶部的一处小洞穴里。要到达山顶，你需要从格罗姆·地狱咆哮的纪念碑旁的小径上攀爬上去。', '杀死戈加农和搜寻者迪亚索鲁斯，然后向灰谷林歌神殿的守备官维达尔复命。', '燃烧军团永远不能再威胁我们了!你把我们从一场极可能输掉的战争中救了出来，$C.\r\n\r\n感谢你，阿古斯之手也给予最深的感激。有你在我们这一边让我备感光荣。', '我们的夜精灵斥候报告攻击的准备似乎仍在进行。那些恐惧领主一定要立刻死掉，$N!', '', '去灰谷找林歌神殿的守备官维达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9523, '贵重物品，小心轻放', '祭司告诉我说，西边的那处遗迹乃是暗夜精灵文明的遗产。这时候我就想起来，我老爸在我小的时候也经常提到过暗夜精灵的遗迹，他怎么说来着，“儿子，你一看到暗夜精灵的遗迹，就要想到暗夜精灵的圣物肯定也在附近。”$B$B既然如此，要是我看见暗夜精灵的圣物，还不派人去挖，我还能算个矮人么？！快去快去！', '秘蓝岛奥德修斯营地的考古学家阿达曼特·铁心要求你给他找到8块上古圣物。', '我爸爸会很骄傲的!他的儿子在他碰到的第一个夜精灵废墟就大捞了一笔……当然，是因为你的帮忙。没错，别担心。我不会在这个发现中忽略你的名字的。你叫做$N，对吗?他们会在铁炉堡了解所有关于你的事。', '没拿到古代圣物就不要回来。', '', '去秘蓝岛找奥德修斯营地的考古学家阿达曼特·铁心。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9526, '夺回冥火岭', '小家伙，你知道吗？在夜歌森林的南部有一片地方，最近因为恶魔的横行而换名叫冥火岭了。看到这样一片地方被散发着腐朽气息的恶魔们所占据，真是让我感觉到无比的悲伤。$B$B不知道你是否能帮我做点什么，夺回那片地方？$B$B我这里有一些种子，可以挽救那里的环境。把它们带到冥火岭去，然后种植在那里肥沃的土壤之中。', '将8棵小树苗种植在肥沃的土壤中，然后向灰谷林歌神殿的纳亚尔回报。', '好。虽然这些幼苗要长大还要好几年的时间，但最终它们会帮我们对抗冥火岭的恶魔。$B$B安心的离开吧，小$g兄弟:姐妹;。', '你还没把我全部的种子都种下去吧?', '', '去灰谷找林歌神殿的纳亚尔。', '种植小树苗', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9527, '遗体', '我们与这座岛上的枭兽和平共存了许多年。你完全可以想象出，当它们风暴般席卷海滩并袭击我们时，我那无比惊讶的表情。$B$B我们当时竭尽全力与它们对抗，可它们还是在力量上轻易压倒了我们。后来，我被沉重的一击彻底打昏了过去，一直没有醒来，我真希望我的家人当时没有遭受任何痛苦。$B$B我醒来以后，周围已经是一片死寂了。黄沙被他们的血彻底染成了一片赤红。他们大概全部被吃了。$B$B我已经不求复仇或是别的什么了，$N。只求我能得回她们的遗体，以便安葬。', '秘蓝岛的库雷要求你回收他的家人的遗体。', '谢谢你，$N。他们的灵魂现在可以安息了。', '我的妻子叫萨尔瑞莎，我的女儿是麦格文。', '', '去找秘蓝岛的库雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9528, '乞求帮助', '我的家人几周前被这座岛上的鱼人和枭兽攻击了。我想尽办法才逃了出来，而我的父母……恐怕已经被杀了吧。现在，我不知道现在该去哪，也不知道该做些什么，但……我一定要想办法回家，无论那里变成了什么样子，都要回家……你能帮助我穿过森林吗？', '护送麦戈薇穿越小岛，回到家中。', '<喜悦的泪水滑落科伦的脸庞。>$B$B我要如何才能回报你，$N?拜托，收下这个传家宝。它象征着夜精灵间一份神圣的友谊，信任和爱。你是我的$g兄弟:姐妹; -', '嗨，$N。', '护送麦戈薇', '去秘蓝岛找秘银岛的库雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9530, '天才的方案！', '我一直以来都在怀疑是否会有这样的情况，但现在已经证明确有其事了。$B$B我们当中确实有一个叛徒。$B$B在这份地精文件里面所提到的计划中，我嗅到了共谋的气息。我当前还不知道这个叛徒是谁，所以我需要你的帮助，找出他。现在这种状况下，我的每一个船员都无法信任了。$B$B我现在需要一棵中空的树干和许多树叶，这样计划就能成功了。到我们北边的树林里去找找看有没有树干，另外也要收集一些树叶，看看森林里面有没没有吧。', '秘蓝岛奥德修斯营地的海军上将奥德修斯要求你收集一株中空的树干和5堆树叶。', '我一定要警告你，我接下来要叫你做的事很危险。如果你决定不帮我，我也不会看轻你的，$N。', '我爱计画成形的时候……', '', '去秘蓝岛找奥德修斯营地的海军上将奥德修斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9531, '间谍之树', '根据他们的计划，这个叛徒和地精们的领袖吉兹尔会在西侧岛屿的一处小海湾的沙滩上见面。我要求你到那里去监视他们的会面，$N。$B$B还记得我要你带回来的树干和树叶吗？你一定要穿着它们去监视会面，这是最好的伪装了！$B$B到那处小海湾去，找找看有没有纳迦的旗帜。找到旗帜以后立刻在旁边使用伪装包把自己伪装起来，然后等待他们的会面。很快这个叛徒就会在那里和地精会面的。查明他的身份以后，立刻回来找我。', '秘蓝岛奥德修斯营地的海军上将奥德修斯要求你监视吉兹尔与叛徒的会面与谈话。$B$B确认叛徒的身份之后回去向他复命。', '不敢相信!自始至终竟是地精……我早该知道了!', '背叛者会希望他从未惹上联盟海军指挥!', '', '去秘蓝岛找奥德修斯营地的海军上将奥德修斯。', '找到叛徒', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9534, '毁灭燃烧军团', '燃烧军团的恶魔馀孽们最近经常袭扰我们的战歌伐木营地！$B$B这些恶魔是从东边几处分别叫作冥火岭、屠魔山谷、和屠魔山的地方出发的。$B$B去杀死尽可能多的恶魔，为你自己和部落带来荣耀吧！', '杀死6个玛诺洛克鞭笞者、6个恶魔守卫和6个灼热的地狱火，然后向灰谷碎木岗哨的瓦鲁莎复命。', '这样好多了!没什么比让我们的世界摆脱恶魔要来的好了。他们也是有价值的敌人，不像联盟的懦弱种族。', '那里还有没有恶魔的存在?你说你自己是个$r?作战是没有时间休息的!', '', '去灰谷找碎木岗哨的瓦鲁莎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9535, '恶魔的计划', '这张羊皮纸是恶魔留下的，最令人惊奇的是，上面的文字竟然是用通用语写的！这里提到了迪亚索鲁斯和戈加农，这是两个声名狼籍的恐惧魔王，它们统领着周围的恶魔。$B$B这里明确地写出了恶魔们进攻西北方的碎木岗哨的具体计划。$B$B或许碎木岗哨的瓦鲁莎会对此感兴趣？', '将恶魔的计划交给灰谷碎木岗哨的瓦鲁莎。', '惊惧领主!他们计画要攻击我们碎木岗哨?!$B$B我还有一口气在就不可能!$B$B<瓦露萨将恶魔草写的计画书在手中捏皱。>$B$B不。我们不会让这种事发生!他们是我们世界的祸害!', '你手里拿着什么，$t兄弟:姐妹;?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9536, '休想！', '$N，你必须想办法确保燃烧军团的这次进攻遭到挫败！去杀死这两只恐惧魔王！没有了他们，剩下的恶魔就会失去领导，变成一群无脑的生物。$B$B你可以在冥火岭正南方的屠魔峡谷中找到戈加农，就在玛诺洛斯那根悬浮在空中的短矛旁边。$B$B搜寻者迪亚索鲁斯住在屠魔山顶部的一处小洞穴里。要到达山顶，你需要从格罗姆·地狱咆哮的纪念碑旁的小径上攀爬上去。', '杀死戈加农和搜寻者迪亚索鲁斯。', '燃烧军团再也不能奴役兽人或任何其他部落的种族!$B$B英勇奋战，$C!你身体里跳动的是真正的部落的心!你让我们备感光荣!', '那些恐惧领主一定要快点死掉，$N!', '', '去灰谷找碎木岗哨的瓦鲁莎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9537, '绳侏儒以法', '必须立刻将欧格林德绳之以法！$B$B我要求你立刻转至海滩上去，找到那个侏儒叛徒。找到他以后，马上绑起来全面搜身，他身上发现的任何信息都要保留下来！$B$B要是这样一位高阶的联盟军官都做出了叛国行为，谁知道军队里还有没有其它同伙呢？$B$B还有，$N，必要的时候可以使用武力……', '奥德修斯营地的海军上将奥德修斯要求你从工程师欧格林德那里取得叛徒的证据。', '不可思议!这全都是他们计画的一部分!$B$B这个消息一定要让国王和你的领导者知道。这个牵连会令人难以致信。', '你找到那个撒谎的无赖了吗?', '', '去秘蓝岛找奥德修斯营地的海军上将奥德修斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9538, '学外语……', '我想我已经完成解码了，$N！$B$B<奥鲁恩指着图腾。>$B$B现在我们最需要知道的就是这些印刻在图腾上的止松熊怪语言的涵义。只要对它们的符号语言略有基础性的了解，我们就可以研究这些图腾，并与熊怪们进行交流了。$B$B我已经把基本的符号对照表写在了这张纸片上。你好好研究研究，再看看图腾吧。它应该会指引你去阅读下一个刻有信息的图腾。你完成学习之后，就可以与阿鲁古对话了。', '阅读奥鲁恩给你的止松熊怪语言入门，以便和碧蓝岗哨的阿基达图腾交流。', '这图腾有不同的原始印记。你看到图腾表面刻着猫头鹰，熊，狼，和雄鹿。$B$B你注意到一堆陌生的象征让你的嘴巴发出了阿契达的音。', '你可以听见一个低音的嗡嗡声从图腾里散发出来。', '阅读止松熊怪语言入门', '去找秘蓝岛的阿基达图腾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9544, '阿基达的预言', '这块图腾上印刻的画面描绘出了止松和刺臂两个熊怪部族的争战场面。画面中，你可以看出刺臂熊怪曾对止松熊怪犯下了滔天的罪行。$B$B在混乱之中，一个古老的预言逐渐显露了出来：一位并非是熊怪族人的英雄会站出来，拯救止松部族。$B$B杀死刺臂村的刺臂熊怪，找出他们身上的钥匙，并用这些钥匙救出止松俘虏。释放所有俘虏之后，回到止松部族的阿鲁古那里去！', '在刺臂村中释放8名止松俘虏。完成任务之后回到碧蓝岗哨，找止松部族的阿鲁古复命。', '[熊怪语]预言说过有一个人会出现并将我们从须肢压迫的控制下解救出来 - 灵魂们自己会宣告这位英雄的到来。$B$B而现在，你来了。$B$B我景仰你，伟大的英雄。', '[熊怪语]所以阿契达的预言是真的……一个英雄被送来我们这里。', '', '去秘蓝岛找碧蓝岗哨的阿鲁古。', '释放止松俘虏', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9545, '先知的圣物', '顽固者禁锢了自己的思想，相信只有他们才是对的。睿智者却能看到导致当前局势和未来发展的各种可能性。$B$B把这件圣物带到你发现瑟丹的地方去。$N不要只用你的眼睛去看，更要用你的思想去思考。', '地狱火半岛塔哈玛特神殿的智者阿曼恩要你回到瑟丹的尸体旁，使用先知的圣物。任务完成之后回去向他复命。', '我希望你见到的幻象会让你对希戴的死有些洞察。圣物让你看见一连串导致现况的事件。真相或许会不同，我们当然永远不会知道。$B$B你现在知道了这些事会有不同的行动吗?$B$B谁知道我们和兽人的斗争会不会继续呢?重要的是要对可能性抱持开放的态度。', '你见到幻象了吗，$N?', '', '去地狱火半岛找塔哈玛特神殿的智者阿曼恩。', '看到幻像', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9548, '被偷走的设备', '嘘！小声点，别让人注意到我。$B$B如果被鱼人发现，试验就完蛋了！我现在已经面临资料被毁坏的危险了。$B$B昨天我出去寻找食物的时候，有一些鱼人到处游走，发现了我的营地。结果我回来的时候恰巧看到有两个鱼人正在搬走装着我大部分设备的柳条箱！箱子一定在附近的某个鱼人营地中，但我不能冒着被发现的危险出去寻找。你能帮帮我吗？', '找回克劳伯的设备，把它交给躲在海滩龟壳中的克劳伯·维兹班。', '这真是太棒了!我的装备被偷却让我对这些鱼人的天性有了更多的了解，这比几个礼拜的观察所能获得的见解还要多!$B$B我已经知道要在报告中说些什么了。$B$B\'当黑沙面对高科技文化的产物时，他们对人类物种新兴的文化特色一点兴趣也没有。\'$B$B真是太高明了!铁炉堡的绅士们会很爱它的!我太感谢你了，$N。', '你找到我的装备了吗?', '', '去找秘血岛的克劳伯·维兹班。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9549, '黑沙神器', '我的观察报告和论文详细地介绍了有关黑沙鱼人的情况，$N，但这仅仅只是开始。我准备把黑沙鱼人利用最基本的工艺技能制造出的物品带回铁炉堡。$B$B问题是黑沙鱼人随身携带这些物品，杀掉它们又会让我内疚。你能不能帮我收集到黑沙先知身上的神像，还有黑沙士兵和黑沙巡滩者身上的小刀？我不会询问你是用什么方法得到的。', '收集3个粗糙的鱼人神像和6把粗糙的鱼人小刀，把它们交给躲藏在海滩龟壳里的克劳伯·维兹班。', '令人惊奇，就是惊奇!这些东西非常完美，$N。我已经可以看见它们被放在铁炉堡博物馆的玻璃里面了。展示的文字差不多就写在我脑袋里了!$B$B你的帮忙让我的研究回到轨道上，这是无价的。你的名字怎么写?我会让它以共同执笔者的身份出现在我的报告里。$B$B船上的某个家伙给了我这张“宝藏地图”作为还赌债，但神话不是我研究的强项。那是迷信，水手。', '你弄到那些样本让我带回铁炉堡吗?', '', '去找秘血岛的克劳伯·维兹班。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9550, '一张地图？', '从这张潦草的地图上看不出任何有关画图者的信息，但可以看出画图人的手一直在颤抖。弯弯曲曲的线条和记号显示出，在一座被水淹没的高塔西边有一处由破裂的柱子搭建的小亭。$B$B如果这张地图是真的，这片废墟应该位于岛的东海岸。你无法预见会在那里找到什么，但它被记录下来显然说明它具有足够的重要性。', '找出图中描述的亭子，寻找画图人所记录的信息。', '仔细地检查这本书，你推论这一定是本日记。它的书页写满了优雅的字迹，和地图大不相同。很多页的文字都被制图者的图画和笔迹弄的模糊不清。$B$B在制图者描述船员的海岸假期，豪饮故事下，几乎不可能辨视出原本的文字。', '或许这本旧日记是地图参考的出处。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9554, '空气的召唤', '代表其它元素的兄弟姐妹会要求你去完成不同的任务，但我不会再要求你去做什么了。我想你已经有能力去弥补因为你们的飞船坠落在这里而造成的灾难。我能感受到你现在已经充满了智慧，明白该如何明智地使用空气元素的力量。$B$B将这部分空气元素带回去交给预言者努波顿，他会帮你制造你的图腾的。当你准备好的时候，我会将你送回埃索达。', '将空气之漩交给埃索达的预言者努波顿。', '我以你为傲，$N。你在别人动摇时还能不屈不挠，过程中你也对元素和自己有了更多的了解。在你的生活中记住它们的教诲，你就能过的更有智慧。$B$B现在，把苏瑟拉斯的漩涡交给我，这样我就能将它渗透进你的风之图腾。和其它的图腾一样，它会聚焦也会提醒着你和铸造元素的关系。', '这么快就回来了?你的头发还真乱。$B$B<诺柏多会心地露齿而笑。>', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9557, '破译书籍', '你没有办法了解日记的内容，于是开始思索有谁能够帮助你将写日记人的笔迹与画图者的潦草字迹区分开来。$B$B你想起学者菲索斯，他收藏了无数来自各种文明的古董。你希望富有经验的学者菲索斯能帮你读懂日记的内容。', '把这本日记交给秘血岗哨的学者菲索斯。', '嗯……这真的很有趣。没问题，我想我可以辨别出这本书原着所写的东西。$B$B我应该有了程序需要的所有东西。这应该只要一下子。', '圣光照耀你所有的努力，$C。你手里拿着什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9560, '末日的野兽！', '当时，我和我的哥哥正在东边的森林里打猎，突然不知从哪里跳出来一群长得像昆虫一样的奇怪生物袭击了我们。我们从来没有在秘蓝岛上见过那种生物！难道这是大灾变的征兆吗？难道预言中那个将被你阻止的大灾变就快要发生了吗？$B$B如果你真的是那位救世主，就请你将那些末日一般的生物都消灭掉吧……记得把它们的壳带回来。我没准能把这些壳做成很坚固的铠甲！$B$B越过道路一直向东就可以找到它们了。', '秘蓝岛止松要塞的莫多要求你给他带回8张掠食者的皮。', '不只预言是真的，连这个护甲都超棒的!它绝对是配得上勇士的护甲!而且我以折扣价卖给你，就没有毛的那一件。$B$B我开玩笑的……第一件是赠送的。', '他们是丑陋的小生物。就连盲目者麦格特都能看见他们……他是盲人。', '', '去秘蓝岛找止松要塞的莫多。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9562, '鱼人……', '这几天真是最黑暗的日子，救世主大人，现在就连鱼人也跑来踩我们的尾巴！若只是尾巴，只是自尊的话，倒也没什么，但它们伤害到的可不仅只是自尊而已。$B$B我们这边和沙鳞鱼人的关系一直很微妙，但我们从来没有料到它们竟然有胆对我们发动那样的大规模袭击，还抢走了我们全部的食物储备！请立刻到西边的淤泥海岸去，夺回我们的食物！$B$B还有，如果你看见某只深色皮肤的鱼人在它那全是蹼的脚趾上套了块白色毛皮的话……', '秘蓝岛止松要塞的古尔弗要求你找回5袋止松谷物。', '嗯……美味的谷物……帕卡特会很高兴的!', '一只鱼人从我后面踢我一脚还对我吐口水……就在光天化日之下!', '', '去秘蓝岛找止松要塞的古尔弗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9563, '米伦的信任', '那你是想得到我们的信任？我现在已经不会再那么轻易相信别人了。$B$B不久之前，这里刚刚有人背叛了我们，投奔了鸦人的阵营，这件事让我非常愤怒。$B$B这么说吧，如果你能向荣耀堡证明你的忠诚，比如……给我搞一杯守望堡烈酒回来……是的，听起来不错……到那个时候我就会派事情交给你去做。$B$B守望堡的波尼储藏了许多上好的烈酒。', '将一杯守望堡烈酒交给米伦·长须。完成任务后，你在荣耀堡的声望必须达到友好才能完成这个任务。', '什么，太好了!看来你是个还满不错的$r。我想我可以信任你。', '苦啤酒很难找吗?守望堡的老波尼应该有储存几桶。$B$B除非他的都喝光了……那就太悲惨了!', '', '去找地狱火半岛的米伦·长须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9564, '古尔弗的尊严', '你找到了一件古尔弗在与鱼人的打斗中“丢失”的毛皮。将这块毛皮带回去交给古尔弗，并告诉他可怕的咕噜咕拉已经被杀了。', '将古尔弗的尊严交给秘蓝岛止松要塞的古尔弗。', '<克夫在那块毛皮上吐了口口水，想把它黏回背上那块无毛的地方。>$B$B这应该没问题了!希望某个萨满能把损坏修补回来。', '这是我想的那个东西吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9567, '知己知彼', '非常高兴能再次见到新面孔出现在秘血岗哨，$c。尽管血精灵是我们迫在眉睫的威胁，但秘血岛上还有其它邪恶的生物。$B$B你尤其需要注意的是纳兹维安萨特\r\n。它们是一群邪恶的魔鬼，拥有黑暗的魔法，并吸取了大量埃索达坠落后泄漏的堕落能量。$B$B我们必须阻止它们，但首先，我们必须了解更多关于萨特的信息。到西南边的纳兹维安去，看看能否从它们怪异的碑石中了解到一些情况。', '找到纳兹维安的碑石，将得到的纳兹维安碑石雕文交给秘血岗哨的守备官艾蕾希亚。', '做得好，$N。看看我能从这个雕纹中学到什么，这样我们就可以计画下一步要怎么做。', '你成功的取得对纳兹维斯萨特的了解吗?', '', '去秘血岛找秘血岗哨的守备官艾蕾希亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9569, '化解危机', '既然萨特已经知道了我们的存在，我们必须告诉他们，德莱尼人绝对不能容忍燃烧军团的爪牙出现在这里。$B$B为了躲避燃烧军团和它的爪牙的追杀，德莱尼人有很长一段时间都在逃亡，$N。一旦燃烧军团发现我们，它们绝对不会心慈手软。$B$B我们一定不能让萨特利用埃索达坠毁泄漏出的能量和水晶作为武器！到北边的阿克萨林去，杀掉它们的首领，找到它所收集的被腐蚀的水晶！', '杀掉5个阿克萨林暗影行者、5个阿克萨林唤魔者和塞弗拉克斯，然后收集5块被腐蚀的水晶，把它们交给秘血岗哨的守备官艾蕾希亚。', '没有他们的领导者，又取回了被污染的水晶，我们就能安全的抑制萨特了。天晓得还有多少这些可恶的生物在外游荡。$B$B我和通报者米可拉斯很感激你提供的协助，在萨特变成更强大的威胁前对抗他们。你的努力提醒我们警惕是对抗燃烧军团和他们爪牙胜利的关键。', '<复仇者艾乐希雅像是看着你的后方而不是看着你，她的心思系着那些萨特。>$B$B你有照着我的话把萨特领导者给铲除吗?', '', '去秘血岛找秘血岗哨的守备官艾蕾希亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9570, '可怕的库肯', '水晶风暴逐渐退去之后，一只神秘的野兽冲进了我们的村庄。这只名叫库肯的野兽是枭兽们入侵时带来的，它凶猛无比，几乎将我们的村子夷为平地。为了保卫我们的家园，为了征服这只可怕的恶魔，许多同胞都惨烈地牺牲，失去了宝贵的生命。$B$B而在我的梦境中，我看见有人杀死了库肯。那个人一定就是你了，$N。你是我们最后的希望。进入止松要塞杀死库肯，把它的毛皮带回来作为证据。', '秘蓝岛止松要塞的启示者库尔兹要求你杀死库肯，并带回库肯的毛皮。', '允诺者获胜!$B$B预言就要成真了。至于皮革……', '<克兹咕哝着对你说。>', '', '去秘蓝岛找止松要塞的启示者库尔兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9571, '库肯的毛皮', '将库肯的毛皮交给村子另一边的莫多。他会用这块皮按你的要求为你制作一件东西。', '将库肯的毛皮交给止松要塞的莫多。', '这是我做过最坚固的护甲!好好利用它，$N。', '哈罗，英雄!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9572, '攻陷城墙', '快点，时间真的不多了。萨尔玛的存续现在已经是危在旦夕！$B$B我们西边有地狱火堡垒虎视耽耽，东边又有燃烧军团的威胁。现在燃烧军团暂时把注意力转向了黑暗之门那边，我们必须利用这个机会给地狱火堡垒中的邪兽人以一次真正的打击。完成这次打击的关键在于破坏他们的城墙！$B$B立刻到那里去，杀死他们的领袖，然后把证据交给屋子那边的卡萨雷兹。', '杀死巡视者加戈玛、无疤者奥摩尔和座龙纳杉，并将加戈玛之手、奥摩尔之蹄和纳杉之颅交给地狱火半岛上的萨尔玛内的卡萨雷兹。', '这是个好的开始。那三个家伙死了他们的军队就会陷入混乱。他们的炮火沉默，我们就能更轻易地接近并拿下堡垒!$B$B不过，我有预感这事情没有看起来那么简单 - 所以我要请你做件事。$B$B不过目前为止，你做的很好。从这些萨尔玛护甲中拿一个吧。$B', '是$N，对吗?史托克顿告诉我要等你的报告。$B$B我相信你带来了好消息?', '', '转至地狱火半岛，去找萨尔玛的卡萨雷兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9573, '欧莫鲁酋长', '我是止松酋长，这个部族遗产的继承者。正如您所见，我的卫兵已经给那些想要从止松要塞中攻出来的疯狂枭兽们设了一个通向死亡的圈套。可是我们现在所有人都必须守在这里，没法攻入堡垒里面。如果您能进去并刺杀它们的领袖，或许我们就能有机会展开攻击。$B$B找到欧莫鲁酋长，消灭它。哦，顺便杀死您在路上遭遇到的所有疯狂枭兽吧。', '秘蓝岛止松要塞的止松酋长要求你杀死欧莫鲁酋长和9只发狂的野枭兽。', '这就是我们需要的机会!我会立刻发出攻击!静松感谢你的帮忙，$N!', '任务完成了吗?', '', '去秘蓝岛找止松要塞的止松酋长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9574, '腐蚀的牺牲品', '因为我们的到来，秘血岛一直在改变。埃索达坠落后，碎片散落在整座岛上，我想这会给野生动植物造成不良的影响。$B$B在证实我的想法前，我需要了解更详细的情况。水晶的能量似乎对于树木的影响最大，这样的话，我们应该可以从树人身上看到某些征兆。如果你能帮我从堕落的树人身上找些树皮样本回来，我就能进行深入的研究了。', '找到6片晶化树皮，把它们交给秘血岗哨的莫莱。', '这些够我研究的了。谢谢你，$N。如果你又找到其它水晶腐败秘血岛自然生物的证据，立刻让我知道。', '你拿到我要的样本了吗?', '', '去秘血岛找秘血岗哨的莫莱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9575, '攻陷城墙', '快点，时间真的不多了。荣耀堡的存续现在已经是危在旦夕！$B$B我们西边有地狱火堡垒虎视耽耽，东边又有燃烧军团的威胁。现在燃烧军团暂时把注意力转向了黑暗之门那边，我们必须利用这个机会给地狱火堡垒中的邪兽人以一次真正的打击。完成这次打击的关键在于破坏他们的城墙！$B$B立刻到那里去，杀死他们的领袖，然后把证据交给大厅那边的冈尼。', '杀死巡视者加戈玛、无疤者奥摩尔和座龙纳杉，并将加戈玛之手、奥摩尔之蹄和纳杉之颅交给地狱火半岛上的荣耀堡内的冈尼。', '你知道什么比错误更让我痛恨吗?我以金子来打赌你没办法打倒它，甜心。$B$B太杰出了!那三个家伙死了他们的军队就会陷入混乱。他们的炮火沉默，我们就能更轻易地接近并拿下堡垒!$B$B不过，我有预感这事情没有看起来那么简单 - 所以我要请你做件事。来，从这些护甲中拿一个。$B', '是$N，对吗?查德威克告诉我要等你的报告。$B$B你来找我有什么事吗?!你的任务完成了吗?你是个彻底的白痴吗?你让我很想吐!$B$B现在把你无用的身躯拿来对付防御，做你该做的事!听见了没?!', '', '转至地狱火半岛，去找荣耀堡的冈尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9576, '克鲁芬的项链', '仔细地查看这个做工粗糙的坠饰之后，你发现水晶在轻轻地、有规律地脉动。尽管它没有发光，你却感受得到水晶散发出一股邪恶的能量。$B$B你不知道是什么力量驱使克鲁芬制造了这个坠饰，但这个发现非常重要，一定不能忽视。你最好把它拿回秘血岗哨去给那里的某个人看看。', '将红色水晶坠饰交给秘血岗哨的莫莱。', '这真是难以理解，$C。我们从没见过鱼人佩戴任何一种装饰品。$B$B大家都知道水晶裂片拥有的腐败影响，佩戴这个坠饰的鱼人一定是以为它会给予他出众的力量。如果他迅速地生长超过同伴鱼人的体型并获得力量，那我不会太惊讶。', '你手里拿着什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9579, '加莱恩的命运', '你没有办法通过莫莱提供给你的信息辨认出尸体是不是加莱恩，但从被撕碎的衣服上看，像是被人搜过身。$B$B灾难过后，这一带的血精灵一定会来夺取那些有价值的东西，包括加莱恩脖子上那条镶着宝石的护身符。$B$B尽管莫莱的丈夫在埃索达坠毁时未能幸免于难，但你相信如果能找回被血精灵夺走的护身符，她也会很感激你的。', '将加莱恩的护符交给秘血岗哨的莫莱。', '<你告诉莫瑞伊你在冬眠核心的残骸身上找到的东西。>$B$B所以……他……$B$B我想我也大概猜到了，但就是不想让自己相信。这不是我希望听到的消息，但我非常感谢你帮忙找到高拉恩。', '<莫瑞伊怀抱希望的看着你。>$B$B你的搜索有找到高拉恩的任何蛛丝马迹吗?', '', '去秘血岛找秘血岗哨的莫莱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9580, '猎熊', '相信你在秘血岛这段时间已经看到，我们将这里改变了不少。我经受的考验和经历告诉我，任何一种环境中的生物，即便是这里的，也多少可以派上用场。$B$B我们的资源所剩不多，必须动脑子去想想如何发掘新的资源。我正在收集遍布全岛的棕熊身上的肉，以此补充我们的贮藏。如果烹饪方法正确，它们的肉是可以安全食用的。如果你要出去走走的话，为什么不帮我找些熊肉回来，补充我们的库存呢？', '收集8块老年棕熊的肉，把它们交给秘血岗哨的追踪者兰塞恩。', '这会让我们这阵子都有足够的补给，处理它一定会让我忙上好一会儿。谢谢你的帮忙，$N。', '打猎进行的怎么样，$N?', '', '去秘血岛找秘血岗哨的追踪者兰塞恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9581, '研究水晶', '欢迎来到秘血岗哨，$c。保护前哨站的安全是我的首要责任，但埃索达的首领们又交给我一些其它的任务。$B$B现在的问题是岛上非常危险，如果派出大批的研究员，他们的安全就很难得到保证。我需要找一个合适的冒险者去岛上的不同区域帮我收集水晶样本。$B$B第一个目标是坠毁飞船的碎片，在城镇南边，穿过桥的地方就可以找到这种样本。', '使用水晶矿锄在坠毁点水晶上采集一份坠毁点水晶样本，把它交给秘血岗哨的先行官米库拉斯。', '由于这个水晶裂片来自秘血岛较无污染的区域，它让我们的研究员有个基准可以比较岛上其它地区的样本。$B$B在我们弄到一整套样本前我不能把它寄出去，但这是个很棒的开始。如果你愿意帮忙收集其它的样本，我会确保你获得应有的奖励。', '你收集到第一个水晶样本了吗?', '', '去秘血岛找秘血岗哨的先行官米库拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9582, '一人之力', '我们的飞船坠毁时，船上兽栏所在的舱室分离了出去，坠落在岛上的东北角。前两天，有人将这把钥匙交给了我，这把钥匙所对应的笼子中关着的是死亡掠食者，世上最为危险的物种之一。这种生物的表皮可以反射大部分的魔法，但却并不坚硬，用一把利刃就可以轻松杀死它。$b$b拿着这把钥匙，去让这只生物从牢笼中获得自由，也让它的灵魂从痛苦中获得解脱。如果它从笼中逃脱出来，并对当前已经千疮百孔的生态环境造成更大的损害，我们绝对承受不起。', '打开掠食者的牢笼，干掉死亡掠食者，然后向碧蓝岗哨的鲁安达复命。', '<罗达严肃的点点头。>$B$B这样就完成了。$B$B你已经准备好下一次的学习了，$N，不过我不是那个教你的人。', '你解决掉那个野兽了吗?', '', '去秘蓝岛找碧蓝岗哨的鲁安达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9584, '第二份样本', '既然已经有了作为衡量标准的水晶，我们现在就需要从岛上更危险的区域寻找其它的样本。$B$B接下去需要的样本来自秘血岗哨西北边的刀林，那里的血精灵持有我们要的水晶。有报告说他们对水晶进行改造，把它加入某种魔法装置中。你去看看能否找到一块他们还未使用过的水晶，从上面采集一块样本给我。', '使用水晶矿锄在变异的秘血水晶上采集一份变异水晶样本，把它交给秘血岗哨的先行官米库拉斯。', '<通报者米可拉斯检查水晶裂片。>$B$B这个裂片和初始的样本有很大的不同。$B$B<通报者米可拉斯高举水晶照射光线。>$B$B你有看到它的搏动吗?这很令人担心。我会将血精灵对这水晶的改变附注在我的报告里。再次谢谢你的帮忙，$N。', '你弄到第二个水晶样本了吗?', '', '去秘血岛找秘血岗哨的先行官米库拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9585, '最终的样本', '在我将所有的水晶送回埃索达前，还差一个样本没有收集到，$n。最后一类样本来自西北边的萨特要塞阿克萨林。$B$B我不知道能从这块水晶样本上发现些什么，但是我敢肯定一定会有一些腐蚀的迹象。像你所做的那样，小心地从那里的水晶上采集碎片，否则我们的研究员就没法进行正确的比较了。', '使用水晶矿锄在阿克萨林水晶上采集一份阿克萨林水晶样本，把它交给秘血岗哨的先行官米库拉斯。', '<通报者米可拉斯向你接过最后一个水晶。>$B$B这样一套就完整了。剩下要做的就是把它们装箱送到埃索达。$B$B<通报者看起来很高兴任务完成。>$B$B别误会，$N，我相信这研究是有价值的，但我们还面对着外面许多其它要紧的问题。', '你带着我要的最后一个样本回来了吗?', '', '去找秘血岛的先行官米库拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9586, '帮助塔瓦拉', '我们这里的一位草药师塔瓦拉进森林采药，但是到现在还没回来。我害怕她受伤，如果那样的话，她可能需要帮助，但我自己却没办法去找她。$b$b请你去帮我找她吧，如果她受了伤，也请你帮她治疗一下，$c朋友。她离开碧蓝岗哨后，一直向东走向那些温泉的方向去了。', '碧蓝岗哨的古安要求你找到塔瓦拉并治好她的伤势。', '谢谢你帮助塔瓦拉。太多人不熟悉这些土地并在他们未料想到的地方遇上麻烦。$B$B如果你穿上这些长袍会让我备感光荣。它们代表你是蓝色守望的保卫者之一也是圣光忠诚的追随者。', '你找到塔瓦拉了吗?', '', '去秘蓝岛找碧蓝岗哨的古安。', '治愈塔瓦拉', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9587, '黑暗之潮', '在传令官瓦兹德那具已经失去了生命气息的尸体上，你发现了一封折起来的信，上面的火漆封引还没有撕开。一个由血红色墨水所精心书写的“I”字跃然于信封之上。小心撕开信封，里面信纸上的文字却让你十分困惑。$B$B荣耀堡的远征军指挥官达纳斯·托尔贝恩或许很有兴趣看看这个！', '将不祥的信件交给地狱火半岛上荣耀堡的远征军指挥官达纳斯·托尔贝恩。', '你说这有伊利丹的签名?!给我吧。$B$B<军队指挥者阅读这封信，之后又看了第二遍，思考了片刻。>$B$B你所带来的这个消息的确是不祥的没错。知道这个消息后，我们必须加快我们对抗地狱火堡垒及鲜血熔炉的计画。你已经表达你可以完成这任务，所以我要你来带领这些计画。$B$B甘尼将会给你下一个任务，不过我想这比你第一次的任务更加危险。$B$B愿圣光与你同在，$N!', '你拿着什么东西吗，$g年轻人:女士;?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9588, '黑暗之潮', '在传令官瓦兹德那具已经失去了生命气息的尸体上，你发现了一封折起来的信，上面的火漆封引还没有撕开。一个由血红色墨水所精心书写的“I”字跃然于信封之上。小心撕开信封，里面信纸上的文字却让你十分困惑。$B$B萨尔玛的纳兹格雷尔或许很有兴趣看看这个！', '将不祥的信件交给地狱火半岛上萨尔玛的纳兹格雷尔。', '你说这有伊利丹的签名?!给我吧。$B$B<纳兹格雷尔阅读这封信，之后又看了第二遍，思考了片刻。>$B$B你所带来的这个消息的确是不祥的没错。知道这个消息后，我们必须加快我们对抗地狱火堡垒及鲜血熔炉的计画。你已经证实你可以完成这任务，所以我要你来带领这些计画!$B$B百夫长卡沙瑞斯将会给你下一个任务，但是我想这比你第一次的任务更加危险。$B$B为了部落，$N!', '你手里拿着什么信，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9589, '鲜血就是生命', '那封信里的内容若是传出去，恐怕会让这里炸了锅。要是大家知道了信里的内容，一定会要求我们得想办法对付那些新近出现的邪兽人。可我们还得对付东边的燃烧军团，这可真糟糕。$B$B所以，你看，你的机会来了，甜心！你不如立刻去地狱火堡垒的鲜血熔炉散散步，多棒的主意！$B$B快到那里去，杀死一些邪兽人，然后采集一些他们的血样回来。$B$B你觉得你能搞定吗？', '收集10份邪兽人血样，把它们交给地狱火半岛上的荣耀堡内的冈尼。', '真是太出色了!就现在而言，$T平民:平民;$N，你是我在这可悲的星球可悲的遗迹中最喜欢的人!$B$B我相信当我把那些血交给理论家研究的时候他们一定会尿裤子的。谁知道，或许我们会发明一种新武器来对抗那些可恶的邪兽人?', '你拿到那些血了，亲爱的?如果我们要你去弄到手那就一定是很重要的，你知道吧?', '', '转至地狱火半岛，去找荣耀堡的冈尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9590, '鲜血就是生命', '那封信真是令人困扰，绝不仅仅因为它是背叛者所书写的。现在，我们已经知道他们正在制造某种新类型的邪兽人了，必须想点办法阻止这一切发生！可我们还得对付东边的燃烧军团，这已经够糟糕了，而现在又要有一支庞大的邪兽人军团即将出现在西边！$B$B你必须立刻潜入地狱火堡垒里面的鲜血熔炉，从那里带一些邪兽人的血样回来。', '收集10份邪兽人血样，把它们交给地狱火半岛上的萨尔玛内的卡萨雷兹。', '我对你的能力印象深刻，$N。你不只一次，而是二次为我们渗入地狱火堡垒完成要求的工作。$B$B我会确保这些血被送到可以解开秘密的人手里。谁知道，或许我们可以找到一个方法来扭转局势?', '你没这么快就收集好血液了吧?', '', '转至地狱火半岛，去找萨尔玛的卡萨雷兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9591, '驯服野兽', '每一名$c刚刚开始$g他:她;的$c之路时，$g他:她;总是先从杀戮学起。但现在看来，你已经准备好学习其它知识了。$b$b止松熊怪提供了一种不需几个月的研究和学习就可掌握驯化技术的方法。他们可以雕刻出某种对应特定种类动物的图腾。利用这种图腾，你就可以与那类生物中的某一只创建起暂时的连接。$b$b那么，你的第一课就是去海岛西岸，对那里的带刺的螃蟹使用这根图腾。', '使用驯兽图腾驯化一只带刺的螃蟹，成功之后向女猎手凯拉·夜弓复命。', '我相信你学会的第一件事就是爬行者在相处过程是多么的冷漠。在他们知道你不是去把他们丢到滚烫的热水前他们都不会松懈。', '你能驾驭图腾的魔法和尖刺的爬行者做朋友吗?他们是烦躁不安的小生物!', '驯化一只带刺的螃蟹', '去找秘蓝岛的女猎手凯拉·夜弓。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9592, '驯服野兽', '与螃蟹的连接无疑能证明你的能力，但是，去驯化一只林地陆行鸟更能显示出你的决心。只有精神与体魄更加坚韧的猎人才有资格拥有更加强大的盟友。$b$b拿着这根图腾，去驯化一只巨型林地陆行鸟。这些生物一般生活在秘蓝岛北边。', '使用驯兽图腾驯化一只巨型林地陆行鸟，成功之后向女猎手凯拉·夜弓复命。', '看来林地陆行鸟没把你的眼珠啄出来。$B$B<凯拉望向别的地方一会儿。>$B$B我当然不认为这会发生啦!', '林地陆行鸟是一种强大的鸟类，掠夺者常判断错误而导致悲惨的结局。', '驯化一只巨型林地陆行鸟', '去找秘蓝岛的女猎手凯拉·夜弓。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9593, '驯服野兽', '在驯化陆行鸟的时候，你可能已经注意到附近有一种名为夜行豹的大型猫科动物。它们的狩猎方式高效而致命，是丛林最优秀的猎手……与盟友。$b$b用这根图腾去驯化一只夜行豹。要小心地对待这种猫科动物，不要让它们受到伤害。成功以后回来找我。', '使用驯兽图腾驯化一只夜行豹，成功之后向女猎手凯拉·夜弓复命。', '我必须说，$N，你学的比我想象的还要快。看来我们不需要使用这最后的驯服图腾了。老实说，我甚至不确定这是什么。它看来像一种有着翅膀和长尾巴的可怕爬行动物。喔呃，或许下次再说吧!$B$B你已经体验够多可以靠自己的力量试试看了，不用驯服图腾帮忙。祝好运!', '夜间潜猎者基本上只是有剃刀般的锐爪和爱吃肉的大猫咪而已……', '驯化一只夜行豹', '去找秘蓝岛的女猎手凯拉·夜弓。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9594, '军团的徽记', '这块盔甲碎片是由一种黑漆漆的金属铸造的，似乎在不断吸收光亮。尽管它看起来似乎没有被施加魔法，不过你仍能明显地感觉到它充满邪恶的力量。$B$B只有一支军队会使用这样的盔甲——燃烧军团。燃烧军团出现在这个地方只可能有一个原因，那就是调动岛上的萨特来攻击德莱尼。$B$B去干掉这里的萨特，然后返回秘血岗哨，将这块盔甲碎片交给守备官艾蕾希亚。', '除掉8个纳兹维安萨特和8个纳兹维安魔誓者，然后将瑟拉克的护甲块交给秘血岗哨的守备官艾蕾希亚。', '你把这个带来给我是非常正确的，$N。这绝对是恶魔守卫的护甲碎片。$B$B那么，就如我所担心的。纳兹维斯萨特正在重建和燃烧军团的联系。如果我们不阻止他们，萨特和他们的恶魔盟友就会把我们踩在脚下。我会立刻通知通报者米可拉斯。', '什么事，$C?你拿着什么?', '', '去秘血岛找秘血岗哨的守备官艾蕾希亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9595, '控制', '你既然选择了$c之路，就必须学会控制魔法。魔法，若不加以控制，是能腐蚀人的灵魂，甚至能够毁灭这个世界的。$b$b为了彻底了解这一点，你必须向一名彻底被魔法吞噬了心智的人挑战。到秘蓝岛西北方的海岸边，用你的法术消灭那里的鱼人。这样一来，你展示出的魔法力量一定会引起某个潜藏在那里的法师怨灵的注意。引出这个邪恶的奎尔多雷法师怨灵，并且消灭它。$b$b完成这一切后，去埃索达的圣光穹顶，找巴蒂谈一谈。', '杀死淤泥海岸附近的鱼人以召唤出奎尔多雷法师怨灵，并消灭它。完成之后与埃索达圣光穹顶的巴蒂谈一谈。', '使用每一个法术时你都要让自己对抗它的诱惑，只有在正面目的需要时才会使用它。希望法怨让你稍微了解如果你太大意会变成什么样子 -', '你挑战了你的梦魇吗?', '', '去找埃索达的圣光穹顶的巴蒂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9598, '救赎', '当圣骑士们决意为圣光献出一切和保卫我们的人民免受威胁的时候，我负责指引他们获得更强大的力量。$B$B是时候让你迈出成为真正勇士的第一步了。如果你愿意的话，我会给你一本圣洁之书。阅读书中的内容后，你对圣光的理解会更加深入，知道你应该做些什么。如果你能够对此有所体会，而且具备必需的能力，那你就将成功地获得更强的力量。', '阅读圣洁之书后和约尔谈一谈。', '你已经看完了圣洁之书，对吗?$B$B那么你应该可以接受成为圣骑士的测验了。由于埃索达的失事，我们在这片新大陆有许多的任务需要完成:对盟友的协助、了解需要帮助的人们以及要歼灭的敌人……$B$B藉由你帮助他人，尤其是最需要帮助的人的那份善心，才可以证明你属于圣光的一份子。', '欢迎回来，$N。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9600, '救赎', '你的任务就是去帮助我们新的同伴——止松熊怪。$b$b一些年轻的止松萨满祭司偶然闯入一处刺臂营地，结果全部被杀掉了。带着这枚生命符记，去复活一个萨满祭司。$b$b刺臂熊怪的领地在路的东边，穿过连接秘蓝岛和秘血岛的桥就能看到。完成这件事情后回来跟我谈一谈。', '约尔希望你利用生命符记复活一个年轻的熊怪萨满祭司，然后回去向她复命。', '别烦恼那些你拯救的人所经历的混乱。重新回到这世上的人体验迷惘是正常的事，想象遇到一个陌生生物的震惊感觉就知道了。$B$B年轻的萨满多亏了你才能从这样严酷的经验中生还，你也可以在适当的时候召唤出这个力量。', '所有的生命都值得被拯救，只要不与我们作对就好。只有我们的敌人才要永远安息。', '', '去埃索达找圣光穹顶的约尔。', '复活年轻的熊怪萨满祭司', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9602, '邪恶的书信', '你必须立刻让你的人民得知这些信息，$N。如果不是你勇敢的行动延缓了凯尔萨斯和他那邪恶主人的计划，毫无疑问这里还要继续受到攻击。$B$B把这个叛徒的证据交给你的领袖吧。他们一定得亲自看看这些东西，或许他们更能理解上面文字的涵义。', '将叛徒的证据交给碧蓝岗哨的大主教梅内莱厄斯。', '<主教米奈奥斯从你手中接过信开始阅读。>$B$B他们这些该死的家伙……他们最好全都进入虚空。他们有个间谍一直在观察我们的所做所为!持续多久了?$B$B我会立刻通知费伦!$B$B你帮了我们一个很大的忙，$N。回到你的岗位上，因为等预言者指示我该怎么做之后我就会通知你了。', '你回来了!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9603, '床铺，绷带，以及更多', '欢迎来到秘血岗哨，$c。请不要介意到处都乱糟糟的。人很容易把一些简单的事情认为是理所当然的，就好象在你不得不新建一个什么都没有的旅馆前，你会觉得修建一个完全装修好、供货充足的旅店不是件什么大事。$B$B我们利用这个舱来建造一个旅店，但没有固定的家具和急救站的设备，这旅店跟一顶美化过的帐篷没有区别。埃索达的努古尼可以为我们提供迫切需要的东西，但我得找一个人帮我把这张货物清单交给他。', '将托菲尔的清单交给秘血岗哨的角鹰兽管理员兰度。', '所以你要去埃索达?$B$B那会是个长途旅行，但别担心，我有办法让你很快就到那里。', '你好，$N。你有兴趣租一只角鹰兽吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9604, '乘坐角鹰兽', '只需要花一点点钱，你就可以乘坐角鹰兽飞去埃索达。$B$B乘坐角鹰兽既快又安全，那些携带着重要消息的人都会选择这种途径。如果你愿意的话，我可以帮你安排。', '乘坐角鹰兽从兰度处飞往埃索达。到达后，将托菲尔的清单交给纳鲁之座的努古尼。', '太棒了!你带了塔伏尔的单子来!我正希望今天可以收到呢。来看看他需要什么。\r\n\r\n<鲁古尼看完单子后开始在箱子里放入各种物品。>\r\n\r\n他要的东西大多都在这里了。床对角鹰兽来说太大了没办法运送，我会另外安排货车送过去的。', '你好，朋友。看来你长途跋涉了许久。我能帮你什么忙吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9605, '斯泰法努斯', '拿着这只盒子，$N。有了这些东西，托菲尔的旅店就能开张了。告诉他，如果还需要更多的东西，尽管来找我。秘血岗哨迫切地需要一个地方来照顾伤员和安顿旅行者。$B$B当你准备返回秘血岗哨时，去埃索达大门附近找斯泰法努斯。', '找到埃索达外的斯泰法努斯，乘坐他的角鹰兽回到秘血岗哨。', '所以你要带着这个包裹回去血色守望?没有问题，$C。再和我谈谈我就可以让你带着那些补给品上路了。', '你要去哪，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9606, '返回托菲尔·罗阿身边', '如果我没有记错，秘血岗哨的角鹰兽管理员是兰度。如果你之前和他聊过天，那你就可以乘坐我的角鹰兽直接飞到他那里去。$B$B有一个道理你一定要明白：训练过的角鹰兽通常只会飞去它们的主城，或者那些你曾经拜访过的角鹰兽管理员处。$B$B既然你曾经乘坐过兰度的角鹰兽，那你就可以带着托菲尔的补给品按原路飞回秘血岗哨。', '与斯泰法努斯谈一谈，然后租用一头角鹰兽回秘血岗哨。达到后，将努古尼的补给品交给托菲尔·罗阿。', '<将箱子交给塔伏尔，你告诉他鲁古尼已在安排将较大的物品用货车运送。>\r\n\r\n太棒了!现在，我终于能铺几张床，设立急救站，让我们遇到的伤者和任何生还者都有更好的对待。\r\n\r\n我无法表达对你有多感激，$N.血色守望的复仇者也感谢你。', '欢迎回来，$N。鲁古尼把单子上的所有东西都收集好了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9607, '愤怒之心', '$C，立刻集合一支部队去彻底调查地狱火堡垒的鲜血熔炉！现在就去！$B$B我们布置在附近的魔法阵显示出这里发生了一些非常奇怪的事情。但鲜血熔炉内又有某种强大的魔法屏障阻隔了我们的探测与调查。这太可疑了！$B$B那里面的抵抗非常强烈，我们以往派去执行这个任务的人从没有回来过！$B$B记得彻底侦察那边的情况，然后把所见的一切都报告给指挥官。', '全面调查鲜血熔炉，然后向地狱火半岛上的荣耀堡内的远征军指挥官达纳斯·托尔贝恩汇报。', '他们有一个深渊领主?!$B$B<军队指挥官看看四周其它人注视着他，降低他的声音说起悄悄话。>$B$B就是它。他们一定是利用这个深渊领主的血液来制造这些不知为何没有与燃烧军团结盟的新邪兽人。如果他们可以对咖啡色皮肤的兽人这样做，他们也可以对绿皮肤的兽人这样做。对于所有新涌入黑暗之门的部落兽人来说，这很不妙!$B$B我们一定要直击他们的军事力量中心，而且要快!', '$T平民:平民;，报告!你调查了整个鲜血熔炉了吗?', '全面调查鲜血熔炉', '转至地狱火半岛，去找荣耀堡的远征军指挥官达纳斯·托尔贝恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9608, '愤怒之心', '$C，你现在必须立刻集合一支部队去彻底调查地狱火堡垒里的鲜血熔炉！现在就去！$B$B我们布置在附近的魔法阵显示出这里发生了一些非常奇怪的事情。但鲜血熔炉内又有某种强大的魔法屏障阻隔了我们的探测与调查。这太可疑了！$B$B那里面的抵抗非常强烈，我们以往派去执行这个任务的人从没有回来过！$B$B记得彻底侦察那边的情况，然后把所见的一切都报告给萨尔酋长大人的顾问纳兹格雷尔。', '全面调查鲜血熔炉，然后向地狱火半岛上的萨尔玛内的纳兹格雷尔汇报。', '他们有一个深渊领主?!$B$B<纳兹格雷尔注意到其它人瞄了他一眼，降低他的声音说起悄悄话。>$B$B就是它。他们一定是利用这个深渊领主的血液来制造这些不知为何没有与燃烧军团结盟的新邪兽人。如果他们可以对玛格汉的咖啡色皮肤兽人这样做，他们也可以对我们这样做!$B$B我们要直击他们的军事力量中心，而且要快!', '你调查完整个鲜血熔炉了吗?你有什么消息要告诉我?', '全面调查鲜血熔炉', '转至地狱火半岛，去找萨尔玛的纳兹格雷尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9610, '泪水之池', '我对研究艾泽拉斯的历史非常有兴趣，不知道你是否愿意帮助我？$B$B附近的沼泽地区有一处非常重要的历史遗迹，我希望你能帮我探索一下拿来。泪水之池就在东南方，据说在那里的岸边和水底埋藏着阿塔莱巨魔文明留下的神器。$B$B但你要小心，那里现在被一只年老的绿龙索姆努斯和他手下的龙类仆从守护着，水中有还有肉食性的鱼类，非常危险！', '取得5个阿塔莱神器，将它们交给悲伤沼泽避难营的霍拉鲁。', '谢谢你，$C。这些神器的研究会让我忙上好一阵子。如果我们破碎者和德莱尼不了解你们世界的历史，那我们要怎样才能融入呢?$B', '我期待着你收集好足够的阿塔莱神器，这样我就能开始研究它们了。我迫切的想了解他们曾经伟大的文明究竟发生什么事了。', '', '去找悲伤沼泽的霍拉鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9616, '强盗！', '这看起来是像是一张悬赏通告。你无法理解上面的血精灵语言，但你注意到了上面描绘有一个狂笑着的血精灵站在一个死去的德莱尼人身上，还有一个代表着血精灵货币的符号。$B$B他们一定是在狩猎德莱尼人！你必须马上通知大主教。', '将血精灵布告交给碧蓝岗哨的大主教梅内莱厄斯。', '感谢欧萝丝!你把这个带来给我真是太好了，$N。这些血精灵四处游荡就是为了……嗯，血。要立刻通知费伦!收下这个做为奖励。', '什么事?我很忙，$N。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9618, '交回报告', '你的本事让人印象深刻，我相信委托你把我的报告交给瑟兰尼斯是不会错的。', '将克尔图斯·暗叶的报告交给银月城的瑟兰尼斯。', '所有这些报告都是来自卡特斯?他真的都很忙。$B$B卡特斯是盗贼中的盗贼 - 他很少遵照信上的命令，常常用自己的方法来解决事情!不过，别误会，因为他是我最信任的间谍之一，没有他我们会很茫然。$B$B你今天做了示范性的工作。请接受这把剑，将它刺入我们敌人的背后吧。', '你找到卡特斯了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9619, '召唤符文', '虚空石显现出一座被幽灵笼罩着的多层建筑。图像时而模糊，时而清晰，又出现了一些其它的建筑物，你断定这是金雾村。$b$b屋顶和树木一闪而过，你可以看到一条沿着艾伦达尔河一直向西，最终到达金雾村的路。$b$b到那里之后，在村庄中心的建筑物顶部使用虚空石召唤一只虚空行者。只有打败它，你才能回到导师那里去。', '在金雾村使用虚空石召唤出虚空行者，打败它，然后回到银月城的塔莱尼娅身边。', '我真惊讶你会站在这里，$N。许多学徒都死在虚无行者的手下，甚至是虚无石本身。$B$B虚无行者现在听你使唤了。好好利用你的仆人。', '你沿着虚无石显现出来的路走了吗?', '', '去银月城找密室的塔莱尼娅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9621, '部落的特使', '在我们潜在的新盟友之中，似乎有些人还对我们的能力有所质疑。如果他们发觉我们连自己家门口的问题都不能摆平，又怎么会觉得我们能对他们有所帮助呢？$B$B你做的事情将会改变这个状况。我们的能力很快就不再会受到任何质疑。我们将很快以与新盟友们对等的身份加入部落。$B$B将这封信交给被遗忘者的领袖，希尔瓦娜斯女王。她一直站在我们这一边，达尔坎的死讯对她来说无疑将会是最美妙的音乐。做好长途旅行的准备吧，$N。如果一切顺利，她可能会派你去奥格瑞玛。', '到提瑞斯法林地去，将洛瑟玛·塞隆的信交给被遗忘者的首都幽暗城中的希尔瓦娜斯·风行者。', '看来他的生命已经结束了。可恶的背叛者已经得到了该有的报应。$B$B你对血精灵和部落的帮助很大。达克汗是萨尔用来拒绝他们加入我们同盟的借口。你为新部落开创了新局面，$N。$B$B我也看到洛索玛有了其它的消息会大大地改善他与萨尔的关系。非常好!', '我听说奎尔萨拉斯有个访客要来。我以为是个血精灵，老实说。$B$B你带来了什么消息?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9623, '成年', '在我们的这片新家园周围的荒野中，你生存了下来，并展示出比同龄人优秀许多的能力。我相信你已经有能力去支持我们在秘血岛那边的前线战场了。阿古斯之手一定会非常需要你这样的$r。$B$B立刻向象群管理器妥拉留斯报到。他就在埃索达外面管理雷象群。把这些命令交给他，他会指引你去秘血岛接受新的指令。', '碧蓝岗哨的大主教梅内莱厄斯要求你将主教的命令交给埃索达门外的象群管理器妥拉留斯。', '<托拉利斯叹气。>$B$B好吧，让我看看那些命令。', '<托拉利斯调整他的眼罩注视着你。>$B$B这是我们能提供阿古斯之手最好的人吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9624, '美味的点心', '我有一个惊人的发现，$c。在岛上没有被污染的地方生长出了一种不寻常的水果，我称之为沙梨。它们生长在靠近树根的地方。$B$B我用它们做了一些馅饼，但只要我一不留神，雷象就会在周围徘徊，偷走我的水果。我很愿意收集足够多的水果与动物们共享，但我已经没有多馀的库存，而馅饼的需求又回升了。我需要制作另一批馅饼，你愿意帮我收集水果吗？我保证我一定会让大家一起分享的！', '凯希尔路口的奥纳尔希望你能帮他找到10个沙梨。', '你找的很辛苦吗?我都要花上越来越多的时间才能回来。$B$B我很快就要全部停摆了，因为我将不再有空。谢谢你帮我收集梨子，$N。这让我在产季结束前还能做最后一两个派。', '沙梨越来越难找，当然，这也表示伊莱克的派和飨宴也越来越少。你可以收集到所有我需要的水果吗?', '', '去秘血岛找凯希尔路口的奥纳尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9626, '觐见酋长', '你知道的，我还没有丧失对往昔的故乡与人民的爱。我曾为了银月城能在幽暗城与奥格瑞玛的谈判桌上有一席之地而与兽人针锋相对。$B$B你带来的消息可以让任何反对者闭上嘴。立刻将这封信送给奥格瑞玛的萨尔酋长。身为部落的领袖，他会最终接受你们种族的效忠宣誓。$B$B我已经在信上盖了自己的印章，表明了我个人的认可。到城市的西北方去，你就可以找到地精飞艇的空港，搭乘飞艇可以很快到达杜隆塔尔。', '希尔瓦娜斯·风行者要求你将她的密信交给杜隆塔尔首都奥格瑞玛的萨尔。', '<萨尔开始读这封信。>\r\n\r\n希尔瓦娜斯是个固执的人。所以她派了银月城的一个勇士……这能改变什么?', '你是来见我的吗，血精灵?有话快说。我没有时间来你们种族那套繁文缛节。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9628, '夺回数据', '要想帮助测量员完成他们的任务已经来不及了，但看上去他们已经收集到了先行官米库拉斯想要寻找到的情报。在他们被洗劫过的背包里找不到记载着测量数据的水晶，所以一定是被怒鳞纳迦夺走了。$B$B你知道先行官米库拉斯一定会因为测量人员的伤亡而感到伤心难过，但他肯定也希望能夺回珍贵的测量数据。', '从测量人员尸体附近的怒鳞纳迦手中夺回测量数据水晶，把它交给秘血岗哨的先行官米库拉斯。', '<你告诉通报者米可拉斯调查小组的命运。他从你手中接过水晶，但保持沉默了好一阵子。>$B$B他们是好人，$N，他们也知道自己的任务很危险。我很感激你帮忙找到小组并取回水晶。$B$B<通报者的拳头紧握。>$B$B我们已失去太多好人了，而我们的任务才刚开始而已。', '你知道是什么让调查小组无法回来了吗?', '', '去秘血岛找秘血岗哨的先行官米库拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9629, '研究鱼人', '西南边海岸的黑沙鱼人是一群古怪的生物。在某些方面它们完全缺乏感知能力，然而在别的时候，它们又显示出了卓越的组织性。$B$B我对此有一些粗略的理论，但迄今为止还没有真正地对它们进行过考察。我想出了个办法，可以帮助我追踪那些我感兴趣的鱼人，而且不会造成什么严重的后果或者扰乱它们的自然行为。如果你愿意帮我去标记出这些鱼人，我非常乐意付给你一些酬劳。', '秘血岗哨的莫莱希望你用鱼人标记枪去“标记”6个黑沙斥候。', '做的好，$N。我本来担心标记仪器会运作不良，但看来一切都有照着计画进行。', '仪器有用吗?你为我的研究标记好鱼人了吗?', '', '去秘血岛找秘血岗哨的莫莱。', '标记黑沙斥候', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9631, '同事的帮助', '我还有一个细节没有考虑到。这块龙骨碎片中蕴藏的麦迪文的精华残留物已经完全丧失了活力。换句话说，它就像阿坎纳苟斯一样，已经死了。$B$B但是，我们还有办法！我知道有个人可以帮我们解决这个难题。$B$B将焦骨碎块交给虚空风暴52区的卡琳娜·拉瑟德，她明白该怎么做。', '将焦骨碎块交给虚空风暴52区的卡琳娜·拉瑟德。', '艾特罗斯想让整只龙死而复生?用想的就知道这不是件简单的事。$B$B让我们讨论一下该如何为彼此提供协助，$N。', '艾特罗斯派你来的。星星已预测你的到来。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9632, '新的盟友', '先行官米库拉斯保卫秘血岗哨的表现值得称赞，$c。但是我们的敌人太多，而我们的资源太少。$B$B我们的敌人非常清楚我们的弱势，可是他们还不知道你与联盟的部队有联络。我准备了一封介绍信，向离这最近的联盟居住地奥伯丁的人民示好，并提议共同对抗我们的敌人。把信带上，在埃索达西边码头附近找到女猎手凯拉·夜弓。', '将介绍信交给秘蓝岛的女猎手凯拉·夜弓。', '我可以让你到达奥伯丁。很幸运的，只要坐一小段船就可以到!', '你好，$C。你带了什么来?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9633, '转至奥伯丁', '你在码头稍等片刻，就可以看到一艘船从黑海岸的奥伯丁港口方向驶过来。等到船上的乘客都下了船你就可以上去了。$B$B经过一小段旅程之后，船将在奥伯丁靠港，你就可以去传递消息了。$B$B你最好将信交给我的一个老朋友桑迪斯·织风，他在镇里算是个备受尊敬的人。', '在女猎手凯拉·夜弓附近的码头乘船去奥伯丁。到达奥伯丁后，将介绍信交给桑迪斯·织风。', '<桑迪斯从你手中接过信并快速地开始阅读，一边点着头。>$B$B德莱尼口中的蓝谜和秘血岛，在很久以前都是我的族人居住的地方。隐士裴萨斯和他的同胞所面临的一些威胁来自于夜精灵古老的敌人。$B$B我确信奥伯丁的人民愿意向我们的新盟友提供协助。等我和市民及哨兵谈过之后，我就会通知裴萨斯。', '欢迎来到奥伯丁，朋友。你怎么会来黑海岸呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9634, '大战异型掠夺者', '在我们的旅行中学到的一件很重要的事情就是：遇到不同世界的野生生物时必须倍加小心。当埃索达坠毁的时候，上面装载着外域中的多种不同生物，包括一种被称作掠食者的凶猛虫类。$B$B它们中的一些已经死掉，但多数幸存了下来，在荒野中游荡。如果我们不加以阻止，它们必定会扰乱岛上的生态平衡。$b$b在凯希尔路口西边靠近海岸的地方，你可以找到许多掠食者。', '杀掉10个秘血幼崽，然后向秘血岛凯希尔路口的雷象管理器沃克汉复命。', '做的好，$N。劫毁者数量需要再观察一阵子，但我们有了个好的开始。', '我们一定要在劫毁者开始取代秘血岛当地的捕食者前采取行动。你开始削减劫毁者的数量了吗?', '', '去秘血岛找凯希尔路口的雷象管理器沃克汉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9635, '气阀微粒提取器！', '朋友，沼气这种神奇的能源很有价值！但是首先你得设法提取出沼气，这就需要一台气阀微粒提取器。$B$B我倒是可以将提取器的结构图给你，不过有个交换条件。替我找些蒸汽泵零件怎么样？遥远的东北方有一处死亡泥潭，泥潭中损坏的蒸汽泵附近就散落着许多零件。$B$B听说枯萎的巨人将它们弄得到处都是，干涸的湖床上随处可见。', '将15个蒸汽泵零件交给赞加沼泽萨布拉金的马克·迪沃。', '很好!如果我们有延长线圈，羊皮夹钳，暴食软管和一些黏黏的鸭子缎带就好。然后我们就能真的做点东西了!$B$B好好好，我想你赢得了这个，$N。玩的愉快!', '你弄到那些零件了吗?我要先忙着潜水。', '', '去赞加沼泽找萨布拉金的马克·迪沃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9636, '气阀微粒提取器！', '你见过沼气吗？就是沼泽中那种发光的气体？$B$B利用气阀微粒提取器就能提取出沼气。我可以将提取器的结构图给你，不过我需要一些蒸汽泵的零件来修理工程设备。$B$B东北方有一处死亡泥潭，泥潭中的蒸汽泵附近就散落着许多零件，我想一定是枯萎的巨人弄坏了蒸汽泵。$B$B我们以此做为交换条件如何？', '将15个蒸汽泵零件交给赞加沼泽泰雷多尔的凯莉·弗莱。', '闪亮!而且真的，哪个工程师会觉得自己有足够的备用零件呢?喔，或许我可以卖掉一些多馀的零件来买一些提古勒和弗洛尔的草莓冰淇淋?!我爱死草莓了!你觉得他们这附近有卖吗?$B$B好好好，我想你赢得了这个，$N。玩的愉快!', '你弄到那些零件了吗?在隐士阿浩恩把我脖子扭下来之前我有一个压缩线圈要修理!', '', '去赞加沼泽找泰雷多尔的凯莉·弗莱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9637, '卡琳娜的要求', '为了追求一些禁断的知识，我被迫离开了肯瑞托；讽刺的是，现在这帮家伙竟然请求我利用这样的知识反过来帮助他们。$B$B想要我伸出援手的话，不难。不过，你得先帮我做件事，替我取回两本书典，都是我梦寐以求的东西。$B$B第一本书是《暮色魔典》，在一个名叫奈瑟库斯的兽人术士手中；另一本是《忘却之名》，是鸦人领袖——黑暗编织者塞斯的东西。', '从地狱火堡垒破碎大厅的高阶术士奈瑟库斯手中夺得暮色魔典，从奥金顿塞泰克大厅的黑暗编织者塞斯手中夺得忘却之名，将它们交给卡琳娜·拉瑟德。$B$B该任务必须在英雄难度下完成。', '非常好，$N。我试图取得这些书有好久的时间了。很庆幸我们能彼此帮助。', '你弄到我要的秘典了吗，$N?', '', '去找虚空风暴的卡琳娜·拉瑟德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9640, '埃兰之影', '让我想想。紫罗兰之眼……麦迪文的日记……啊，我全都想起来了。$B$B我记得在我开始阅读这些卷轴之前，就已经找到了你说的那本日记……$B$B埃兰……对，是埃兰要去了那本日记，他可真和蔼。我也只能把日记交给他咯。为什么？你难道不知道他是麦迪文的父亲吗？', '将麦迪文的日记交给卡拉赞守护者的图书馆中的卡姆希丝。', '你找到你要找的东西了吗?你在找某个东西，对吧?', '你不是在找一本日记还是什么的吗?', '', '去找卡拉赞的卡姆希丝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9641, '辐射水晶碎片', '埃索达的坠毁导致邪恶的水晶碎片散落在秘血岛全境，污染了水和环境。$B$B我们甚至已经在许多动物体内找到了被它们误食的水晶碎片。我找到了一个办法，可以净化碎片，并使其变成有用的水晶。如果你愿意帮我带些碎片回来，我愿意用我净化好的水晶作为交换。到当前为止，我从居住在岛上污染区的熊、掠食者、巨蛾和树人身上都找到过水晶碎片。', '秘血岗哨的守备官波鲁斯希望你帮他收集10块辐射水晶碎片。', '做的好。这些会为另一批增强水晶提供纯原材料。$B$B欢迎你从我制作的三种水晶中选择一种。我发现它们对追踪不同的猎物各有所长。', '你从秘血岛的生物身上收集到水晶裂片了吗?', '', '去秘血岛找秘血岗哨的守备官波鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9642, '更多辐射水晶碎片', '', '', '非常好，这里是我的水晶，$N。好好使用它们。', '如果你有更多受到辐射的水晶裂片，我很乐意和你交换。', '', '去找秘血岛的守备官波鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9643, '荆棘巨藤', '一个聪明的猎手善于利用一切资源，$c。即便是最怪异的生物也拥有着我们可充分利用的特征。$B$B秘血岗哨不断地遭到炎鹰部队的攻击，我们正借助包括陷阱在内的多种自然防御方法来增强防卫。我觉得鞭笞者的荆棘藤蔓非常适合制作陷阱，锋利的刺和致命的毒药一定可以将毫无戒备的攻击者致于死地。给我带些变异的荆棘巨藤回来，我就可以开始制作陷阱了。', '秘血岗哨的追踪者兰塞恩希望你帮他收集6根荆棘巨藤。', '这些看来够坚固可以拿来用。谢谢你的帮忙，$N。你对血色守望防御的贡献不会被遗忘的。', '你弄到蟒藤了吗?', '', '去秘血岛找秘血岗哨的追踪者兰塞恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9644, '夜之魇', '你完成了契约中规定的义务。我将把你的灵魂和那条死去的蓝龙绑定在一起。$B$B在主宰的露台上有一罐骨灰，碰触那罐骨灰，就可以释放出里面的能量，令阿坎纳苟斯的焦骨碎块复生。击败复生后的阿坎纳苟斯，你就可以得到奥图鲁斯一直想要的精华了。$B$B但是，不要高兴得太早，星相显示你根本无法成功复活阿坎纳苟斯。事实上，这个法术只会将那些骸骨组合某个极度恐怖的生物。$B$B是的，那就是骨龙夜之魇！', '进入卡拉赞的主宰的露台，碰触黑色骨灰，召唤夜之魇并杀死它，然后从夜之魇的尸体上取得暗淡的奥术精华，并将它交给大法师奥图鲁斯。', '这真是令人惊奇!你不只带回来麦迪文的日记，还取得了他精华的碎片。$B$B虽然这个苟延残喘的精华很微弱，它会显示极重要的麦迪文讯息。我们不能忘记，$C。', '你带来了什么消息呢，$N?', '', '去找逆风小径的大法师奥图鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9645, '主宰的露台', '日记？什么日记？$B$B哦，对了。那本日记！紫罗兰之眼派我来卡拉赞寻找的那本日记。我全都想起来了。$B$B<卡姆希丝将日记翻到了某一页。>$B$B这就是奥图鲁斯感兴趣的内容。你知道吗？别人的日记是记录回忆的工具，而麦迪文的日记就是他的回忆本身。$B$B试试吧，去主宰的露台阅读这本日记以后，你就会明白我的意思了。然后，你替我把这本麦迪文的日记交给奥图鲁斯，我还想在这里多待上一阵子。', '进入卡拉赞的主宰的露台，阅读麦迪文的日记。完成任务后将麦迪文的日记交给大法师奥图鲁斯。', '我们派去的密探屈服于卡拉赞的魔法真是一件可耻的事。至少你设法取得了他们寻找的东西。', '你回来了!你带来了什么消息?', '阅读日记', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9646, '通缉：死爪', '根据先行官米库拉斯的命令，凡是能证明自己杀掉了凶猛的棕熊死爪的勇士都将获得18枚银币的奖赏。$B$B死爪是一头极度危险的野兽，他在秘血岗哨西北边海岸杀死了一整支勘测队。旅行者应避免涉足那一带。', '将死爪的爪子交给秘血岗哨的先行官米库拉斯。', '做的好。据我所知，这不是场好打的仗。你不只是赢得你的奖励而已，$N。', '有什么我能帮忙的吗，$C?', '', '去找秘血岛的先行官米库拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9647, '消灭巨蛾', '当我们第一次见到巨蛾时，它们身上已经出现了一些堕落的迹象，然后情况就变得越来越糟……$B$B现在事情已经发展到它们开始破坏一切的地步。它们的这种行为都是受了埃索达坠毁后散落的水晶碎片的影响。我们没有其它办法，只能杀掉秘血岗哨北边的巨蛾。', '秘血岗哨的追踪者兰塞恩要你杀掉10只鲜艳的蓝翼巨蛾。', '时间过去，我们必须想出一个办法来让这些物种恢复他们原本的状态，但现在，定期地删减他们的数量仍是最好的方法。谢谢你的帮忙，$N。', '你剔除掉那些蛀虫了没?', '', '去秘血岛找秘血岗哨的追踪者兰塞恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9648, '玛凯雷蘑菇展', '你知道吗，去寻找采集蘑菇比吃下蘑菇要危险得多？蘑菇采集者常常会身陷未知的险境，而且还有隐藏在黑暗中的猛兽的威胁！$B$B如果生活中一点危险都没有，那该是怎样的一番体验呢？我需要收集一些蘑菇。在这片还未被探索过的荒野中，你可以找到四种不同类型的蘑菇：水生臭角菇、血蘑菇、致命孢子簇和邪锥蘑菇。它们是秘血岛的不同区域所特有的物种。把这些蘑菇带回来给我。', '玛凯雷的耶塞拉希望你找到一个水生臭角菇、一个血蘑菇、一个致命孢子簇和一个邪锥蘑菇。', '嗯，我有警告你 - 对吧?希望这个款项能补偿你经历的一些不安。等你恢复力量再来找我，或许我会有另一个工作给你 - 当然是跟蘑菇有关的!', '记住，我所要的蘑菇都是秘血岛上独特的品种。', '', '去秘血岛的秘血岗哨找玛凯雷的耶塞拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9649, '伊瑟拉之泪', '很高兴再次见到你，$N！我交给你的上一个任务完成得格外出色。或许你对另外一个任务也会有兴趣？$B$B在东北边的龙痕岛上有一种被称作伊瑟拉之泪的稀有蘑菇，那是以居住在岛上的绿龙来命名的。我只需要一点点蘑菇的样本，不过我必须要提醒你那些绿龙非常不欢迎外来者。万事小心啊。', '玛凯雷的耶塞拉希望你找到2个伊瑟拉之泪。', '我希望这不是个太费力的工作，$N。你再一次地证明了自己是个能干又审慎的$r。我表达我的感谢并提供一点金融上的报酬。', '这么快就回来了?', '', '去秘血岛的秘血岗哨找玛凯雷的耶塞拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9663, '凯希尔的信使', '你来得正好，$N。过去的一个星期里，血精灵在这片地区的活动变得更加猖獗。我们的密探报告说，那些自称炎鹰部队的血精灵近期会袭击秘蓝岛。我需要你去通知我们的同盟和同胞。$B$B通知止松要塞的止松老酋长、碧蓝岗哨的大主教梅内莱厄斯和奥德修斯营地的海军上将奥德修斯。$B$B事情非常紧急，所以我把我的雷象借给你。记住，一定要让它远离水域。', '凯希尔路口的凯希尔要你把血精灵即将入侵的消息通知给止松要塞的止松老酋长、碧蓝岗哨的大主教梅内莱厄斯和奥德修斯营地的海军上将奥德修斯。你只有15分钟的时间。（记住让雷象远离水体。）', '做的好，$N。这个困难的试验考验着你的能力，但是你的成绩非常亮眼。要成为一个阿古斯之手的士兵;你一定要通过许多这样的考验。', '没有时间松懈了!', '', '去找秘血岛的凯希尔。', '通知止松老酋长', '通知大主教梅内莱厄斯', '通知海军上将奥德修斯', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9664, '建立新据点', '欢迎来到瘟疫之地，$n。正如你所知，被遗忘者和他们的盟友控制着西边的土地，并与我们互相抗衡。联盟的指挥官们决定在东部建立数个新的据点，以加强我们在敌人外圈的包围网。$b$b洛丹伦战争后期被废弃的那些哨塔正好用来达成这个目标。不过，这些地方都非常危险，我们需要你的帮助。', '夺取东瘟疫之地的皇冠哨塔、东墙哨塔、北地哨塔和病木林哨塔，然后向圣光之愿礼拜堂的白须大使复命。', '很好，$N。握有这些哨塔防止更多的攻击对我们而言是很重要的，为达此目的，在援军前来保卫这里前我们都需要你的帮助。', '等哨塔在我们的控制之下时，我们很快就能包围被遗忘者。在那之后，粉碎他们就是迟早的事了。', '', '去东瘟疫之地找圣光之愿礼拜堂的白须大使。', '占领皇冠哨塔', '占领东墙哨塔', '占领北地哨塔', '占领病木林哨塔');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9665, '加强防御', '被遗忘者的密探发现，最近联盟试图在东瘟疫之地利用那些废弃的哨塔创建一系列的据点。$b$b现在，情况非常急迫，我们显然不能允许他们在我们东部边界的一系列重要地点创建这样的据点，因此我们必须击退联盟的这次进犯，并把他们赶出那些已经被占据的哨塔，同时，我们还要将那些哨塔占领下来，以应对以后的进攻。', '夺取东瘟疫之地的皇冠哨塔、东墙哨塔、北地哨塔和病木林哨塔，然后向圣光之愿礼拜堂的高莫克大使复命。', '这是好消息，$N。在我们将联盟军队完全赶离瘟疫之地前这里会一直争战不休。$B$B在那天到来之前，我希望我们能获得你持续的帮助。', '他们一定是白痴才认为我们会让他们在离我们主城那么近的地方创建基地。$B$B我们会赶尽杀绝直到他们夹着尾巴逃回南方去。', '', '去东瘟疫之地找圣光之愿礼拜堂的高莫克大使。', '占领皇冠哨塔', '占领东墙哨塔', '占领北地哨塔', '占领病木林哨塔');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9666, '展示力量', '你见过那些蛇人吗？那些称自己为纳迦的家伙？$B$B〈凯希尔轻蔑地说。〉$B$B他们趁着天黑，在三天前攻击了这个营地。你能相信那些野兽们的胆子居然有这样大吗？$B$B我想让你去教训教训他们的首领，$N。东北边的怒鳞巢穴是克希兹领主的老窝。找到他，在那里把他干掉，然后将这面旗帜插在他的尸体上。$B$B让他们在我们的军旗前感到恐惧吧！', '秘血岛凯希尔路口的凯希尔要你杀掉怒鳞巢穴的克希兹领主，并将德莱尼军旗插在他的尸体上。', '我很抱歉你得这么做，$N。压制的武力不是德莱尼的做法，但有的时候这是唯一的方法。$B$B这是人生的其中一个真理，许多人了解的时候已经来不及了。当我们被兽人屠杀的时候，这么做是为了我们的人民。$B$B成为一个阿古斯之手就好比重生的过程。而新生总伴随着痛楚……', '完成了吗?', '展示力量', '去秘血岛找凯希尔路口的凯希尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9667, '拯救止松公主', '帮帮我，$N！刺臂部族抓住了我，正准备将我献给他们的神灵！$B$B刺臂酋长拿着牢笼的钥匙。如果你想让他现身，就必须杀掉邪恶的刺臂熊怪，他们居住在西边的那两座营地中。如果你杀掉足够多的刺臂熊怪，他一定会气急败坏地出来寻仇的！当他出现的时候，杀掉他，找到牢笼的钥匙！如果你把我救出来，我的父亲一定会给你丰厚的酬劳作为奖赏的！', '将止松公主救出牢笼，然后与秘血岗哨的止松大使弗拉萨布谈一谈。$B$B你必须杀掉刺臂酋长才能拿到牢笼的钥匙。', '你再一次的证明你就是预言中的英雄人物。大酋长永远的感激你$N-还有这些静松圣物可供你选择……', '我时间不多了，$N。他们很快就会杀了我……', '', '去秘血岛找秘血岗哨的止松大使弗拉萨布。', '拯救止松公主', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9669, '复灭的远征队', '一个星期前，我和我的远征队正在秘血岛西部的荒野中勘察时，遭到了嗜血蜘蛛的袭击。水晶造成的腐蚀影响在它们身上表现得很明显，这些蜘蛛变得巨大且极具攻击性。$B$B我逃了出来，但是我的队员就没那么幸运了。我们不能让其它人也遭受同样的悲惨命运，去西边的琥珀蛛网小径，杀掉那些蜘蛛和它们的首领萨拉肯。', '杀掉8个秘网编织者、8个秘网吸血者和它们的首领萨拉肯。任务完成后向秘血岗哨的阿彻鲁斯复命。', '真是不可思议!你有找到任何生还者吗?$B$B<阿奇拉斯降低他的声音说悄悄话。>$B$B老实说，$N;没有其它人愿意接下这个任务。你是个勇敢的$C……', '那是场可怕的灾难……', '', '去秘血岛找秘血岗哨的阿彻鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9670, '他们还活着！也许……', '真是一个血腥的场面，$N。我们遭到了一大群蜘蛛的伏击，它们以惊人的速度袭击我们，将我们用网裹了起来。$B$B当我们身陷蛛网后，她就开始在我们附近产卵。我们将成为她后代的食物！食物！$B$B我拼命地逃了出来，但我不能丢下其它人不管。到当前为止，我还是没法靠近蜘蛛们盘踞的小径。你能帮帮我吗？$B$B破坏那些蜘蛛网！但愿还有队员幸存！', '研究员考内留斯要你救出5个远征队研究员。', '你救了超过一半的队员!你的英勇行为绝对会传回血色守望和主教那里的。再次谢谢你，$N。', '运气如何?', '', '去秘血岛找琥珀蛛网小径的研究员考内留斯。', '解救远征队研究员', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9674, '血咒纳迦', '他们说当世界分崩离析的时候，这片土地放声痛哭。无数的暗夜精灵坠入湮灭的深渊，被扭曲成一种令人憎恶的怪物——纳迦。$B$B他们听命于扭曲的女王艾萨拉，所有从他们的海域中经过的人都会被杀死。从几千年前到现在一直都是这样——直到今天。$B$B你要做的第一件事就是消灭掉暗礁中的血咒纳迦。', '龙痕岛的艾德华·汉斯船长要你杀掉10个血咒纳迦。', '这是一个好的开始，但还有很多事要做!', '他们是恶心的生物……', '', '去秘血岛找龙痕岛的艾德华·汉斯船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9678, '第一项试炼', '你已经学习过许多关于战斗与牺牲这方面的事了，见习骑士。但你还有更多的东西需要掌握。$B$B对圣光的理解与掌握需要你拥有高度集中的精神和坚固而强大的意志力。没有这些，你至多只能算是个比一般的街头小混混略强一点的小人物而已。$B$B在幽魂之地的东北边界附近有一座小岛，名叫苦难岛，我们一般都在那里磨砺自己的技艺。你会在那里的一处洞穴中找到一只火盆。跪在火盆前，点亮它，并集中精神，看看你眼前会发生什么吧。', '转至骑士领主布拉德瓦罗所描述的那座小岛，找到洞穴，并点亮火盆。当第一个试炼完成之后，向银月城的骑士领主布拉德瓦罗复命。', '我知道你在想什么。$B$B没错，我派静刃去杀你。$B$B这不是冒犯，$N;这是个必要的测试。血骑士是一个兄弟会，但我们务必要确定我们的兄弟保持警戒并且随时准备应付突发状况。一定要杀死静刃才能让你了解这个意义吗?$B$B是的，而且那就和你任何的武器训练一样重要。', '愿圣光的力量在你每次的奋战中都为你所用。', '', '去找永歌森林的骑士领主布拉德瓦罗。', '完成第一个试炼', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9680, '挖掘历史', '卡姆希丝说得对！这里面的内容至关重要。$B$B你看，这里写道，当时麦迪文将自身生命的精华与他所施展的法术相融合，击败了蓝龙阿坎纳苟斯。如果这是真的，那就意味着我们有很大的机会从蓝龙的尸骸中分离出麦迪文的生命精华的残留物质。天啊，这逆风小径中，竟掩藏着这样伟大的未知奥秘，等待着世人发觉。$B$B你立刻到卡拉赞之塔南方的山脉中去取回一块龙骨的碎片回来。', '大法师奥图鲁斯要求你转至逆风小径，从卡拉赞以南的山脉中取回一块焦骨碎块。', '太棒了!虽然这个碎片很小，但它充满了能量，我可以感觉的到!', '你取回我要的骨头碎片了吗，$N?', '', '去找逆风小径的大法师奥图鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9682, '绝望者……', '在比你找到血咒纳迦的地方更深的暗礁中，你会发现那些绝望的血咒航海者，那些被血咒夺去生命的灵魂。$B$B我现在要你做的事情会让人感到悲痛……但他们必须被消灭，把他们被诅咒的躯壳带回来给我。$B$B他们的灵魂必须得到安息。完成我交代的事情后回来找我，我还有最后一件事要麻烦你帮忙。', '龙痕岛的艾德华·汉斯船长要你找到4个血咒之魂。', '你帮了绝望者一个大忙，$N。不过还有最后一个任务:杀死血咒的领导者。', '不必为他们的死亡哀悼，$N。', '', '去秘血岛找龙痕岛的艾德华·汉斯船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9683, '血咒的终结', '你可以在南边找到血咒岛。岛上的神殿供奉着纳迦女王艾萨拉的雕像。毁掉那座雕像，把它彻底烧掉！这一定会让血咒部族的首领埃托弗极其愤怒。$B$B杀掉埃托弗，然后回来找我！', '龙痕岛的艾德华·汉斯船长要你毁掉艾萨拉女王的雕像，并杀掉血咒者埃托弗。', '你成功了!几百个灵魂都对你所做的一切感激不尽。$B$B让我给你一个礼物……', '一定要把阿托夫引诱出来!', '', '去秘血岛找龙痕岛的艾德华·汉斯船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9684, '驾驭圣光', '拿着这只瓶子，$N。启动其中的魔法，你就可以吸取这些魔导师身上残存的光明能量。他们曾经负责控制那个被我们捕获的纳鲁，因此纳鲁的能量还有一部分留在他们体内。$B$B这应该就足以让你的伙伴起死回生了。$B$B不用为这些魔导师担心，$N。我正在照料他们，而且索拉纳·血怒大人向我保证过，莉亚德琳大人正在积极寻找新的能量源。', '用血精灵魔导师身上的能量装满微光容器，然后向银月城的骑士领主布拉德瓦罗复命。', '做的好，$N。圣光所给予的力量永远不会是血骑士与生俱来的，但我们也不会软弱到任由命运来宰制我们。$B$B我们对秘法专精提供了这条道路，来帮助我们度过这段困难的时光。力量不再自由地弥漫于这些殿堂之间，但我们还是有坚定而强壮的意志力。如今很少有人有这样的兴趣与天赋来钻研此道，但我相信你不会让骑士团失望的。', '你和博学者阿斯塔乐.血誓谈过了吗?', '', '去找永歌森林的骑士领主布拉德瓦罗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9686, '第二项试炼', '现在你在骑士团中已经是最接近正式骑士地位的见习成员了，$N。但真正成为正式骑士之前，你必须还要接受另一个试炼，以证明你自己的价值。$B$B第二个试炼与前一个最大的不同之处在于，这次将不会有任何令你吃惊的成分。你需要面对的挑战很简单，只需要依次与四名最优秀的血骑士英雄比武就可以了。$B$B在你接受挑战之后，一颗水晶会出现在帐篷中央。你只需碰触这颗水晶就可以开始试炼了。注意，比武中千万不要远离这座建筑物。$B$B你准备好了吗？', '击败克雷伦·血伤一旁帐篷中的勇士布拉维·血怒、勇士莱伦德·光痕、勇士玛尔娅·迅刃和勇士斯塔克·射日者，完成第二项试炼。', '做的好，$N!你已证明自己拥有血骑士正式的成员身份资格并提升到高手等级。不过，在你入会之前还有几个任务要完成。', '血骑士宁死也不会向敌人屈服。记住这点，$N。', '完成第二项试炼', '去永歌森林找银月城废墟的克雷伦·血伤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9687, '找回尊严', '不久前，在这片区域一直过着平静生活的枭兽出现在了岸边。他们一个接一个地偷走了死去龙族的尸骨。我不知道是什么让这些生物如此地不安，也不知道为什么他们要偷走龙骨，不过因为这样的行为，龙族的灵魂无法得到安息。$B$B到西边去，穿过红砂海滩，你会看到怒羽山。进入枭兽的营地，找回被偷走的龙族尸骨吧。', '龙痕岛的托雷斯王子要你找回8根龙骨。', '一个仪式?枭兽已经和平的住在这块土地好几千年了。这样的事是脱离常轨的!$B$B真是遗憾……', '龙的战争已过去好久了。所剩仅有骨头和被激怒的伊瑟拉后裔残存者。', '', '去秘血岛找龙痕岛的托雷斯王子。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9688, '进入梦境', '你在岛上看到的幼龙是躁动不安的绿龙之魂。他们跟我一样被困在了这里，灵魂无法得到安息。$B$B找回他们的尸骨让他们暂时安定了一些，不过你还必须采取进一步的行动才能永久解决这个问题。$B$B毁掉他们的怨魂，在那之前我都不能离开这里。一定要彻底解救他们！', '龙痕岛的托雷斯王子要你杀掉5只绿色雏龙和5只绿色龙崽。', '虽然你的任务令人感到不忍心，但总是要有人把它完成。现在你必须正式面对事件背后的邪恶力量。', '看到这种情景让我感到很痛苦。拜托，我们不要再谈下去了。', '', '去秘血岛找龙痕岛的托雷斯王子。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9689, '刺喉', '许许多多的黑龙在战斗中被杀死了。其中有一个死亡之翼的亲信军官，他的灵魂至今仍出没在这里。如果你望向天空，就会看到他那幽灵般的面孔浮现在空中。即便已经死去，他的仇恨还是那么强烈。$B$B带上你之前帮我收集到的龙骨到岛上的山顶去，把它们放在永燃火堆中。这样一定可以把刺喉引下来。等他出现以后，毁灭他的灵魂。', '龙痕岛的托雷斯王子要你杀掉刺喉。', '事情已经发生多久了?一千年?或许是一万年?你为我和我的往生族民们做了一件伟大的事，$N。请接受这件蕴含强大魔力的物品做为罗萨伦的感谢', '我建议你多带几名盟友一同转至，$N。', '', '去秘血岛找龙痕岛的托雷斯王子。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9692, '骑士之路', '在新的正式骑士被骑士团接受之前，$g他:她;必须首先锻造一把骑士团特有规格的武器，也就是淬血长矛。$B$B此外，你还需要争取到佩戴骑士团徽章的权利。自骑士团创建之日起，我们的徽章就严格控制着总数，每一名新晋级的正式骑士都需要从一名资深骑士那里继承徽章。你的徽章曾属于一名勇敢带队突袭了戴索姆的骑士，可这位骑士已经牺牲了。$B$B这里还有一份笔记，你需要按照上面的说明去做。', '将一块被污染的科尔宝石、一箱血铸铁锭、一份愤怒者之血和一枚血骑士徽章交给银月城的骑士领主布拉德瓦罗。', '非常好，$N。材料已经收集完毕。剩下的就是要铸造武器了。', '你取得所有要你拿到的东西了吗?', '', '去找永歌森林的骑士领主布拉德瓦罗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9694, '秘血岗哨', '秘血岗哨是阿古斯之手驻守的两座前哨站之一。另一处便是碧蓝岗哨，你已经去过了。秘血岛上的情形却截然不同。我们初次到来时，秘血岛跟秘蓝岛一样美丽。我们甚至把这里命名为银风岛，但是如今，疾病侵蚀着整座岛屿，更糟糕的是，部分血精灵侥幸在埃索达的清剿中逃生。我有一项任务要交给你：转至西北方的刀林，消灭躲藏在那儿的血精灵。', '杀死10个炎鹰间谍，然后向秘血岗哨的守备官波鲁斯复命。', '你回来了-而且平安无事!$B$B我有些好消息，$N。我们收到了一些新的资讯关于更多生还者可能的所在位置，同时我们发现了一个新的失事地点!等我处理完那些事情，我会再找你来的。', '他们数量太多以致于我认为他们好像是以倍数成长。', '', '去秘血岛找秘血岗哨的守备官波鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9696, '翻译……', '审讯者埃莉西亚精通萨拉斯语。将这封信件交给她，听听她怎么说。', '将炎鹰信函交给秘血岗哨的审讯者埃莉西亚。', '<伊莱希雅阅读文件。>\r\n\r\n如果这份文件说的是真的，血精灵已打开了通往外域的传送门!这绝对可以说明为何他们的援军数量好像永无止尽……', '我现在有点忙，密探$N。你要说的事最好很重要。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9698, '会见先知', '$N，我要你亲自将翻译好的信件交给维伦。这事儿交给信使办我可不放心。$B$B告诉先知维伦，血精灵不断从外域派来援军，而且埃索达中躲藏着一名德莱尼奸细。维伦就在埃索达的圣光穹顶。$B$B行动要快！', '将炎鹰信函的译文交给埃索达的先知维伦。', '<费伦开始阅读文件。>$B$B真有趣……这的确解释了很多事情。', '<费伦微笑。>$B$B你好，$N。我一直在等你。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9699, '真相还是谎言', '$N，感谢你及时送信给我。你已经逐渐成长为阿古斯之手的优秀成员了。$B$B要是能查明秘血岛上的血精灵头目是谁就好了，更重要的是，我们得找到太阳之门的位置……那儿必定派有重兵把守。$B$B对搜索工作有兴趣吗？$B$B如果你愿意的话，就把我的命令交给守备官波鲁斯。他会给你安排新的任务的。', '将维伦的命令交给秘血岗哨的守备官波鲁斯。', '这是个好计画，但也很危险。我想你会没事的。', '怎么样呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9700, '黑暗中的魔法', '按照维伦的说法，如果血精灵一直在打开外域与这座岛屿间的虚空裂痕，那么所有传送门附近的区域都会出现法力残渣或是畸能体。你必须搜寻整座岛屿，确定有畸能活动的区域。$B$B$N，要小心；某些畸能可能来自虚空。如果你发现虚空畸能，就立即杀死它们！一旦你收集到新情报，就立即回来向我汇报。就从此地以北的跳跃引擎开始搜索吧。', '转至太阳传送站杀死5个虚空畸能，然后向秘血岗哨的守备官波鲁斯复命。', '你说你在星移活塞看到了几个反常者?他们到底打开这个太阳之门几次了?这是个非常糟的消息……$B$B唉，你学会了所有我能教你的事，$N。等时候到了库罗斯就会要你前去找他了。', '我听过传闻说那区域有奇怪的生物出现。不管他们是当地的突变动物或是真正的虚无反常者都是你要去调查的事情。', '确认太阳传送站', '去秘血岛找秘血岗哨的守备官波鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9701, '观察孢子人', '我们要尽可能地调查居住在孢子村的孢子人，了解它们的生活习性，以及他们与其它生物之间的关系。这就是我当前的工作：观察并记录它们的活动情况。$B$B我希望你转至西边的孢殖林，调查整片区域，然后向我汇报你的发现。', '调查赞加沼泽的孢殖林，然后返回赞加沼泽的塞纳里奥岗哨，向观察者莉萨奥汇报你的发现。', '什么?!跨格山脊的泥沼领主在吃孢子人的孢子囊?情况不妙!', '这么快就回来了?你对孢子村的孢子人观察对我的研究是非常重要的。我希望你不是敷衍了事的那种人。展现一点耐心确定你探勘了整个重生峡谷再给我你最后的报告。', '调查孢殖林', '去赞加沼泽找塞纳里奥岗哨的观察者莉萨奥。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9702, '狼吞虎咽', '我一直在想，沼泽领主为何离开自己的地盘，跑去孢殖林觅食——难道是饥饿难耐？这可不行！$B$B唔，通常我不会插手这种闲事，但是如果任由它们吞食孢子囊，孢子人很快就会绝种的！$B$B我决定留在这儿，你去东边的泥泞山跑一趟吧，调查究竟是什么原因导致沼泽领主吞食孢子囊。', '将10份丢弃的食物交给赞加沼泽塞纳里奥岗哨的观察者莉萨奥。', '这就是你的发现?那就怪了。这些除去外皮的蘑菇看起来既奇怪又熟悉。$B$B我得好好思考一下。别离开这里!', '你一定要小心地收集所有的证据，$C!我们正在拼凑一个很大的谜题。你犯一个错就会让我们导出错误的结论。$B$B那么我们对赞加沼泽的生态学能有多少了解呢?', '', '去赞加沼泽找塞纳里奥岗哨的观察者莉萨奥。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9703, '冷却核心', '$N，我们已经派人对太阳传送门进行了追踪调查，现在我有别的任务要交给你。$B$B波鲁斯收到了关于另一处坠毁点的新消息。据悉，这处坠毁点正是埃索达的冷却核心。冷却核心其实是个大型分离舱，舱内包括若干与埃门岛坠毁点的建筑类似的小舱。$B$B那儿应该储备有大量医疗补给品。转至秘血岗哨西面的冷却核心搜寻医疗补给品和幸存者吧。', '取回12箱医疗补给品，然后向秘血岗哨的守备官库卢斯复命。', '只有血精灵?没有生还者?这真是麻烦。我要花点时间思考，$N。或许艾伊森或波罗斯还有任务要你完成。', '消息正确吗?', '', '去秘血岛找秘血岗哨的守备官库卢斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9705, '找回包裹', '经过仔细辨认，这个包裹确实是魔导师艾洛娜的东西。奥拉莉恩应该会让你把这东西归还给她吧。', '将艾洛娜的包裹交给信使奥拉莉恩。', '以太阳之井之名!这是我们这个月失去的第三个先驱者了。$B$B我欣赏你冒险进入黎明小路的勇气。守卫要盯牢这些可恶的鄙恶者。', '你发现了什么，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9706, '加莱恩的日记 - 守备官撒鲁安的命运', '你颤抖着捡起日记。一定要把这场悲剧告知库卢斯。将这本日记交给他。', '将加莱恩的日记交给秘血岗哨的守备官库卢斯。', '<库罗斯一边阅读日志，脸色一边变的苍白，眼泪从他脸庞滑落。>$B$B萨鲁安是我的主人……我的良师……我的益友……我最近才替换了他在三头政治的位子 - 在我们放弃寻找他后。$B$B<库罗斯的脸愤怒的扭曲。>$B$B玛提斯……', '你手上拿的是什么东西，$N?那是一本日志吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9707, '铸造武器', '你又一次在骑士团与你的同龄人面前证明了自己的价值。我现在怀着极大的喜悦授予你正式骑士的衔位，$N。凯尔萨斯王子也会为你而感到自豪的。$B$B我们所有人都为能与你并肩作战而感到荣幸。继续以身作则，让那些想要加入我们的血精灵以你为榜样吧。你要拒绝一切仁慈与懦弱，保卫你的人民与兄弟，并继续提高你在圣光运用上的造诣。$B$B现在，去领取那把象征晋级的武器吧。', '将这箱材料交给银月城的波玛尔。', '看来你有了所有我需要的东西。开始动手吧!', '恭喜，$N。达到高手的阶级不是件简单的事，相信我。我见过许多进入那栋建筑物的人，却只有很少人撑的够久可以带着这些东西来见我。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9708, '熟悉的蘑菇', '唔，对，我记得曾在赞加沼泽的某处见过这种特殊的蘑菇！$B$B此地以北就是菌杆沼泽。真是个奇怪的地名，不过我从来没有去过那儿。我需要一些蘑菇样本来验证自己的猜测是否正确。$B$B$c，千万小心。听说菌杆沼泽是食人魔的驻地，恐怕你得从他们手中抢些蘑菇样本。这或许就是沼泽领主不去那儿觅食的原因。', '将15份蘑菇样本交给赞加沼泽塞纳里奥岗哨的观察者莉萨奥。', '我们想的没错。巨魔的存在和他们做的事解释了一切。现在我知道为什么要叫开辟泥沼了，真笨!$B$B我们得对这个情况想些办法，但是什么办法呢?我们不能就这样杀掉所有的巨魔;他们和所有泥沼的其它生物一样有权利待在那里!', '你弄到那些样本了吗?', '', '去赞加沼泽找塞纳里奥岗哨的观察者莉萨奥。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9709, '偷回蘑菇', '$C，我想到解决此事的办法了。我要你再去北边跑一趟，深入食人魔驻地的中心！$B$B菌杆沼泽西北方有一座巨大的蘑菇桥，桥对面的浮岛名叫安葛洛什要塞。$B$B食人魔肯定会把蘑菇储存在要塞中。我敢打赌那儿到处都是蘑菇，说不定你还可以在食人魔身上找到它们！$B$B替我带回几箱蘑菇，我会试着为沼泽领主提供新的食物。', '将10箱蘑菇交给赞加沼泽塞纳里奥岗哨的观察者莉萨奥。', '这些真是完美!喔，谢谢你，$C!$B$B你是那么小心的没有扰乱事物的自然秩序，而我们在这样短的时间里收集了这么多资讯!$B$B现在，来看看我们为泥沼领主栽种新食物补给的小计画是否能成功。', '你带回了所有我们帮泥沼领主规划的新菜园所需要的蘑菇吗?', '', '去赞加沼泽找塞纳里奥岗哨的观察者莉萨奥。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9714, '我还要红色木槿！', '', '', '这些会非常适合，但我们永远都需要更多。或许你会很快再来幽暗沼泽?', '我们仍然需要从盘牙蓄湖的幽暗沼泽跛行者，泥沼巨人和幽暗沼泽蝙蝠那里弄来更多的血红木槿。帮我以一束五朵的数量带来我会很感激你。', '', '去赞加沼泽找孢子村的舒特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9715, '我要红色木槿！', '红色木槿的用途广泛，因此我们需要补充这种花朵的储量。它们原本跟灌木一样茂密，但是沼泽水位下降后，就只能在盘牙水库的幽暗沼泽中见到红色木槿了。$B$B据说蹒跚者、泥沼巨人和幽暗蝠将其视为美食。如果你愿意帮助我们的话，就去猎杀这些沼泽生物，将红色木槿带回来给我。', '将5朵红色木槿交给赞加沼泽孢子村的舒特。', '这些会非常适合，但我们永远都需要更多。或许你会很快再来幽暗沼泽?', '你取得所有我要你收集的木槿花了吗?', '', '去赞加沼泽找孢子村的舒特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9716, '暗泽湖的异常', '我们满怀期冀地来到外域，希望能发现新的物种。刚到赞加沼泽时，我们所见的是一处繁荣茂盛的生态系统。$B$B可惜最初的判断是错误的。经过测量，我们发现这个区域的湖泊和沼泽的水位在不断下降。$B$B这很可能给当地的动植物带来毁灭性的灾难。转至西南方的暗泽湖，调查水位下降的原因。', '调查暗泽湖水位下降的原因，然后返回赞加沼泽的塞纳里奥避难所，向伊谢尔·风歌复命。', '是纳迦搞的鬼!但是为什么呢?从你的描述听来，那个蒸汽帮浦一定是沼泽水位下降的部分原因!$B$B不论如何 - 这解释了他们对我们公开的敌意。不要浪费时间了，我要你为我们进行另一个任务。', '你发现了什么吗，$N?', '调查暗泽湖', '去赞加沼泽找塞纳里奥庇护所的伊谢尔·风歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9717, '孢子叶', '虽然我们爱好和平，却不得不与泥沼巨人交战。有句谚语是这么说的：蘑菇，战争，都要不择手段！$B$B霍加尔芬是泥沼巨人的首领之一，他负责照料那株名叫幽暗孢子的特殊植物。如果这株寿命已有千年的植物受到任何损伤，对霍加尔芬而言必定是个沉重的打击。$B$B转至盘牙水库的幽暗沼泽，偷偷摘取一片幽暗孢子叶。相信我，他会察觉你的行为的。', '将一片幽暗孢子叶交给赞加沼泽孢子村的塔苏。', '<孢子人发出了一声像是从鼻子喷气的笑声。>$B$B太完美了!当他们发现你所做的事后，孢子巨人的士气绝对会大受打击的。$B$B或者，他们会因为受辱而很快再攻击我们。$B$B<塔苏做了个耸肩的动作。>', '幽暗沼泽是个非常危险的地方。如果你不敢去那里我也不会说你是懦夫的。但如果你没带着我要的东西回来，我也不会感谢你的。', '', '去赞加沼泽找孢子村的塔苏。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9718, '乌鸦的飞翔', '我们必须查明纳迦的活动范围，以便采取相应的措施。$B$B逐一调查赞加沼泽的湖泊将会耗费大量时间。如果你愿意的话，我可以使用魔法将你变形为更适合执行侦察任务的飞鸟。$B$B当你准备就绪后，就在我附近的平台上使用这个护符。完成任务后，我会指引你安全返回的。', '伊谢尔·风歌要求你使用风暴乌鸦护符，然后调查赞加沼泽的主要湖泊。', '如我所想的一样。纳迦在赞加沼泽所有的主要湖泊都设立了抽水站。$B$B如果还想保住沼泽的话就一定要阻止他们。', '嗨，$N。', '调查赞加沼泽的湖泊', '去赞加沼泽找塞纳里奥庇护所的伊谢尔·风歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9719, '黑色阔步者', '一直以来，我们都将泥沼游荡者视为最大的威胁。如今我们却要面临来自泥沼巨人的攻势，恐怕无力与宿敌抗衡。$B$B$c，你是位颇具实力的勇士。你愿意前往盘牙水库的幽暗沼泽，杀死泥沼游荡者之母——黑色阔步者吗？$B$B做为凭证，将它的大脑带回来给我。', '将黑色阔步者的大脑交给赞加沼泽孢子村的肯尼克斯。', '黑色阔步者死了!通常我不会陶醉于这种屠杀行为，但那个族母和她的子嗣几个世纪以来带给我们的痛苦实在是无法用言语形容。$B$B很不幸的现在她的另一个后代将要取代她的位子，但那还需要时间，使我们有空间喘口气，暂时先不用担心沼泽巡者的事。', '你回来了。这表示黑色阔步者已不复存在了吗?', '', '去赞加沼泽找孢子村的肯尼克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9720, '恢复平衡', '我无法理解纳迦为何要将水排出自己的栖息地，我只知道必须制止他们的行为。$B$B这些种子包含着大地的愤怒，我要你利用它们破坏纳迦的蒸汽泵控制台。$B$B从种子中抽出的藤蔓会像你的手臂一样粗壮，像铸铁一样坚硬。$N，去吧。恢复赞加沼泽原有的生态平衡。', '伊谢尔·风歌要你利用铁藤种子，破坏毒蛇湖、暗泽湖、沼光湖和环礁湖的蒸汽泵控制台，然后返回赞加沼泽的塞纳里奥庇护所，将剩馀的铁藤种子还给她。', '完成了。沼泽现在已经没事了。$B$B千万别以为这是我们最后一次听到纳迦的消息。在我们继续外域任务的同时也要对敌人保持警惕。', '完成了吗，$C?', '', '去赞加沼泽找塞纳里奥庇护所的伊谢尔·风歌。', '破坏暗泽湖控制台', '破坏沼光湖控制台', '破坏毒蛇湖控制台', '破坏环礁湖控制台');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9723, '血骑士的义务', '血骑士的忠诚并不仅仅体现在$g他:她;的剑上，$N。骑士团对其成员的要求也不仅仅在于杀戮与战斗。一位真正的骑士能够对骑士团所有的活动做出贡献，尽管其中有些在表面上看起来可能不是那么光鲜。$B$B第一个任务不需要你去战斗，看起来也并不光荣，但如果没有人做出这样的贡献，骑士团必将衰落。我先给你一张清单，魔导师阿斯塔洛·血誓的人需要这些物品，否则就无法持续供应给我们圣光能量了。', '将40块符文布、6块奥金锭、10株太阳草、5个黑暗符文和150枚金币交给银月城的索拉纳·血怒。', '非常好。看来所有东西都在这里。$B$B别担心，你的下一个任务会让你有很多机会挥舞你的武器，我保证。$B$B我要让新加入者把所有的东西带给博学者阿斯塔乐。还有更多重要的事要做的时候就不需要派你去做这些琐碎的差事了。', '你带着博学者阿斯塔乐.血誓要的材料回来了吗?', '', '去找银月城的索拉纳·血怒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9725, '忠诚的表现', '我们血骑士以保卫奎尔萨拉斯为己任，$N。这是你所接受的一切训练的核心目的。我们的敌人凶猛残暴而冷酷无情，银月城和她的居民却能因为我们的努力与盟友们的援助而安然无恙。$B$B我最近收到了一些消息，据说一批新生成的天灾军团出现在了我们领土与东瘟疫之地的边界附近。而众多天灾军团的攻城设备及负责操作它们的工程师也已经到位，似乎想要进攻幽魂之地。一定要阻止它们！', '银月城的索拉纳·血怒要求你摧毁3台天灾绞肉车，并杀死15名天灾攻城技师。', '你展现了对家园的忠诚和对命令的奉献，$N。在你获得大师的称号之前我还有最后一个任务要给你。', '欢迎回来，$N。你击溃了天灾军团和他们的血尸战车吗?', '', '去找银月城的索拉纳·血怒。', '', '摧毁天灾绞肉车', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9726, '既然我们是朋友……', '东北边血鳞领地的纳迦正在追杀我们的人民。我们绝对不容许这样的事情继续发生，$c！$B$B希望你能去给他们点颜色瞧瞧，同时也可以证明我们之间的友谊。', '杀掉12个血鳞驱奴者和6个血鳞女巫，然后向赞加沼泽孢子村的舒特复命。', '<卡思汗特对你点点头。>$B$B我们很高兴你肯定了我们的友谊，$N。既然我们有了这样强大的盟友，或许纳迦异教徒在考虑骚扰我们的时候会三思而行?', '你去拜访过那些纳迦了吗?', '', '去赞加沼泽找孢子村的舒特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9727, '既然我们仍是朋友……', '有报告说东北边血鳞领地的纳迦还在继续追杀我们的人民。我们觉得你有经验去解决这件事，$c！$B$B我想委托你去好好教训教训他们，作为我们友谊延续的证明。', '杀掉12个血鳞驱奴者和6个血鳞女巫，然后向赞加沼泽孢子村的舒特复命。', '<卡思汗特对你点点头。>$B$B我们很高兴你重新肯定了我们的友谊，$N。既然你已经多次把我们的决心表达的很清楚了，他们对我们无意义的攻击会停止了吧?', '你去拜访过那些纳迦了吗?', '', '去赞加沼泽找孢子村的舒特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9728, '热情的欢迎', '在塞纳里奥远征队的德鲁伊们忙于研究植被和勘测湖泊时，我承担起了保卫庇护所的重责。$B$B自打我们来到赞加沼泽，纳迦就在毫无征兆的情况下多次对我们发动突袭。我们已经尽力牵制他们的攻势，可惜毕竟人手有限。$B$B我想让你转至纳迦在赞加沼泽的各个据点，让他们明白我们不是好惹的。把纳迦的爪子带回来给我，作为你击杀他们的证据。', '将30个纳迦爪子交给塞纳里奥庇护所的监护者哈穆特。', '做的好，$N。你抒发一点心里的痛悔是好的。这些纳迦是邪恶的生物 - 比艾泽拉斯的纳迦更坏。', '再见到你真好，$N。你猎捕纳迦的事进行的如何了?', '', '去赞加沼泽找塞纳里奥庇护所的监护者哈穆特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9729, '弗沃尔发怒了！', '纳迦惹恼了弗沃尔！孢子人是弗沃尔的朋友，所以弗沃尔要抢走萨斯里斯圣柜。$B$B我们去附近的纳迦村落吧。你愿意帮忙吗？那就叫上你的朋友！', '护送弗沃尔进入沼光湖水域，在蒸汽泵处找回萨斯里斯圣柜，保护弗沃尔携带圣柜安然返回，然后向赞加沼泽孢子村的舒特复命。', '费斯伍尔是个好巨人。我们一阵子前从纳迦手中把他救出来，后来他就留在这里帮我们的忙。$B$B我们只能希望纳迦会收到暗示并了解到如果我们可以渗入他们的村子，偷取他们最珍贵的财产，我们就可以做更多可怕的事。或许现在他们会回到洞穴并还给我们安静的日子?', '费斯伍尔还好吗?你取回方舟了吗?', '将萨斯里斯圣柜送回孢子村', '去赞加沼泽找孢子村的舒特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9730, '暗潮纳迦的首领', '塞纳里奥远征队重金悬赏击杀暗潮纳迦首领——哈格哈兹王子的勇士。塞纳里奥斥候最后一次发现哈格哈兹是在赞加沼泽中南部的环礁湖。$B$B暗潮纳迦曾多次袭击塞纳里奥远征队，他们的首领被视为极度危险的人物。$B$B诛杀哈格哈兹王子的勇士可在监护者哈穆特处领取奖赏。', '杀死环礁湖的哈格哈兹王子，然后返回赞加沼泽的塞纳里奥远征队，向监护者哈穆特领取奖赏。', '我不喜欢艾泽拉斯的纳迦而且我更不喜欢这里的纳迦。我们的任务不能维持和平真是一件憾事，但你不会看到我为死去的纳迦掉泪。$B$B这是你杀掉暗羽领导者的奖励，$N。', '你想谈谈关于洛迦海卡斯特的赏金?嗯，他死了吗?没什么好说的了!', '', '去赞加沼泽找塞纳里奥庇护所的监护者哈穆特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9731, '抽水泵结构图', '这张结构图上绘制着连接毒蛇湖和邻近湖泊的地下排水系统。$B$B如果图表属实的话，那么毒蛇湖的中心必定有一台巨大的抽水泵。核实这个消息是否属实，然后返回塞纳里奥庇护所复命。', '转至毒蛇湖搜寻抽水泵的踪迹，然后向塞纳里奥庇护所的伊谢尔·风歌汇报你的发现。', '纳迦把毒蛇之湖变成了赞加沼泽的一个巨大水槽。他们到底在干嘛?$B$B你把这个消息带来给我们很好，$N。我们会派一组人去调查你发现的这个排水设备。同时我有个不同的任务要给你。', '你带来了什么消息，$N?', '发现抽水泵', '去赞加沼泽找塞纳里奥庇护所的伊谢尔·风歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9735, '圣光的主人', '血骑士能够以一种那些所谓的“圣骑士”完全无法理解的精妙技巧运用圣光的力量。但尽管我们发挥出了圣光的真正潜能，他们仍然保持着对我们的轻视。$B$B我们必须把自己的力量展示给他们，告诉他们，我们绝对不是他们可以随意嘲讽的对象。我当前已经有了一个主意，不过它有些复杂，也很艰难。但我想，你一定可以胜任。那么，首先你需要潜入提尔之手修道院的图书馆区，并获得一瓶提尔之手圣水。', '银月城的索拉纳·血怒要求你给他带回一瓶提尔之手圣水。', '嗯……这个份量有点少，但如果我们小心点，这应该足够。你知道，血色十字军相信他们是为圣光奉献的。我想他们应该仍是，只是方式扭曲了，而那正是我所希望利用的。$B$B他们错误的热情甚至污染了这水的祝福，非常适合我的目的。', '你弄到水了吗?', '', '去找银月城的索拉纳·血怒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9736, '圣光的主人', '现在我们拥有圣水了，但还需要一些其它的材料。$N，这其中有些物质十分稀有，而且价格昂贵，但我已经找到了可靠的货源。$B$B你应该可以从一个名叫萨尔雷的材料商那里买到一些奥术触媒，他的商店开在死亡之痕附近的一处旷野上。城内谋杀小径的盗贼训练师一旁的毒药商达尔莉亚那里有一些黄昏之尘的存货。$B$B此外，要完成这种混合药剂，我还需要一颗艾泽拉斯钻石和一颗原始黑钻石。', '银月城的索拉纳·血怒要求你给他带回一份奥术触媒、一份黄昏之尘、一颗艾泽拉斯钻石和一颗原始黑钻石。', '既然我们有了所有的材料，我就能准备混合物了。$B$B<一个缓慢的笑容在女伯爵莉亚德琳脸上展开。>$B$B这全都非常完美，$N。等到完成后，我会详细告诉你还有什么事要做。', '你收集到我要的材料了吗?', '', '去找银月城的索拉纳·血怒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9737, '圣光的主人', '我们利用圣光的方式才是最完美的方式，$N。一定让那些自称“圣骑士”的家伙们知道他们利用圣光的方式有多么的愚蠢，一定要把这个事实明明白白地摆在他们的面前。$B$B阿隆索斯礼拜堂是白银之手骑士团组建的地方，似乎在毁灭斯坦索姆的大火之中也被完整地保存了下来。这处教堂里的永恒之焰有着圣光力量的保护，但如果你使用这份药剂的话，就可以熄灭那里的火焰，保护结界也会不复存在。火焰熄灭之后，我们对圣光的统驭之力就会被全世界知晓了。', '在阿隆索斯礼拜堂的永恒之焰上使用熄焰之水，除去圣光的保护，然后消灭所有试图保卫礼拜堂的人。', '做的好，$N。所有反抗我们的人都会留心你传达的警告。我们的敌人应该知道他们有危险了，从最低阶的步兵到最强大的英雄。$B$B你已在大师的阶级里赢得你的位置了。你的奉献和力量是所有血骑士的榜样。做为你新身分的象征，我要给你召唤和指挥萨拉斯战骑的能力。', '你有照我的话做并传达了我的讯息吗?世界上的假圣骑士都一定要知道他们的时代已经结束了。', '', '去找银月城的索拉纳·血怒。', '解除阿隆索斯礼拜堂的保护', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9738, '失踪的同伴', '你必须帮助我！伊谢尔派我们来这里调查神秘的蒸汽泵事件，以及纳迦为什么要利用蒸汽泵排出沼泽地的水。但是我的几位同伴闹了别扭，竟然撇下我独自行动。$B$B那四个家伙有时候脾气是挺古怪，不过我还是很喜欢他们的。$B$B我要你查明他们到底出了什么状况，我很担心他们遭遇不测。去奴隶围栏和幽暗沼泽看看吧。$B$B谢谢你，$c。', '查明缚地者雷葛、博学者拜特、除草者格林萨姆和唤风者克劳恩的下落，然后返回赞加沼泽的盘牙水库，向观察者杰哈恩复命。', '我很高兴我还有些朋友活着，但听到其它人的命运还是让我心碎。<叹气>$B$B至少他们是为了生前最喜欢做的事而死。我永远都感谢你帮了我这个忙，$N。$B$B请你从这些当中挑选一样当作我的感谢。', '你知道我那四个同伴的下落了吗?', '', '去赞加沼泽找盘牙水库的观察者杰哈恩。', '找到缚地者雷葛', '找到博学者拜特', '找到除草者格林萨姆', '找到唤风者克劳恩');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9739, '孢子人的困境', '喂，叫你呢！你必须帮助我们！$B$B真菌巨人正在吞食孢子囊！必须想点什么办法，不然我们的孩子就都没命了！$B$B孢子囊刚刚开始生长的时候体积较大，随着囊内空气的消耗会逐渐缩小。寻找那些体积较小的成熟的孢子囊，尽你所能地拯救它们！', '孢殖林的法恩森要你收集10个成熟的孢子囊。', '你办到了!我的族人感谢你。$B$B我希望你了解……这是我们幼苗出生的地方。我们不能让这些野兽吞噬孢子囊!', '孢子囊!你拿到它们了吗?', '', '去赞加沼泽找孢殖林的法恩森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9740, '太阳之门', '谢谢你，我们已经找到了太阳之门的位置。血精灵可随意移动传送门的位置，以此对付突发状况，所以上次让你空跑一趟也就不足为奇了。$B$B但是，可移动的传送门有许多弊端。太阳之门靠传送门控制器固定。如果我们卸下控制器，就可以摧毁传送门。太阳之门现在的位置在这里的西边，矢量感应器南面的区域。去找到它，摧毁它！', '秘血岗哨的守备官伊索姆要你摧毁太阳之门。', '太棒了!我们切断了他们的补给线。现在我们要做的就是把他们给解决掉!', '你一定要先毁掉他们的传送门控制器才能摧毁传送门!', '', '去秘血岛找秘血岗哨的守备官伊索姆。', '摧毁太阳之门', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9741, '虚空幼体', '数日前，伊索姆派我的人外出搜寻太阳之门。当然，我们找到了……$B$B<洛伊指着约莉。>$B$B愚蠢的血精灵在打开传送门的同时，释放了虚空的力量。现在这儿出现了成群的虚空幼体。$B$B我们必须在它们成长为虚空畸能之前杀掉它们。西南方的太阳之门附近聚集了大量这种生物。杀死它们，然后向伊索姆复命。', '杀死12个虚空幼体，然后向秘血岗哨的守备官伊索姆复命。', '那里真是一团乱吧?你做的很好，$N。我会派一些隐士去帮罗莉和乔尔力。', '虚无异常者变成虚无反常者。说实话，我们真的不知道这些生物是什么……名字只是一个分类的方法。', '', '去秘血岛找秘血岗哨的守备官伊索姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9742, '更多孢子囊', '', '', '太好了!你救了更多的孢子囊。$B$B你和其它的外来者真不一样。我会让我的同胞们知道你的善行!<这个任务可以重复进行直到友好声望阶级。>', '你救了更多的孢子囊吗，$r?', '', '去赞加沼泽找孢殖林的法恩森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9743, '天敌', '孢子人与沼泽领主是世代的宿敌。过去，我们利用长矛和石块与之抗衡。近来他们似乎变得更具攻击性……并且更加不计后果。他们不再惧怕我们，也无视我们手中的武器。$B$B你的威慑力和装备都远胜于我们。如果你愿意替我们打败沼泽领主的话，孢子人会永远感激你的！把他们的卷须带回来给我，这样我就知道你确实在帮助我们了。', '将6根沼泽领主的卷须交给赞加沼泽孢殖林的法恩森。', '你平安的回来了!我会让其它孢子人都知道你这个人!$N，巨人杀手!', '泥沼领主杀的怎么样了?教那些畜生不要再进入孢子人的领土!', '', '去赞加沼泽找孢殖林的法恩森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9744, '更多卷须！', '', '', '不可思议!你杀死的巨人数量需要几百个孢子同胞才能办到。我会让大家都知道你的英勇事绩!$B$B<这个任务可以一直重复进行直到友好声望阶级。>', '你杀了许多巨人，但还有更多随侍在后。他们仍在攻击我们的孢子囊!', '', '去赞加沼泽找孢殖林的法恩森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9746, '精疲力尽', '$N，胜利在望。我们已经发现了太阳之门，很快就能彻底切断血精灵的补给线。首先，我们要削减他们的数量。$B$B此地以西有许多炎鹰部队营地。炎鹰火法师和炎鹰防御者是那里的主要防备力量。去杀死他们，然后向我复命。', '杀死10个炎鹰火法师和10个炎鹰防御者，然后向秘血岗哨的守备官伊索姆复命。', '这绝对会使他们的防御变弱，让他们在仓促行事的时候三思而行!', '他们的领导者不可能永远躲着我们。我们会有系统地消灭所有可能的藏身地点，直到找到赛罗娜斯为止。', '', '去秘血岛找秘血岗哨的守备官伊索姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9747, '暗泽部族', '纳迦真是可憎的生物，但是暗地里帮助纳迦的破碎者和失落者更加令人厌恶！$B$B其中尤以暗泽失落者部族的行径最为恶劣，他们利用黑暗的魔法奴役其它人。暗泽失落者对企图逃跑的奴隶非常残忍，如果我离开庇护所，肯定会被他们干掉的。$B$B转至南边的暗泽村，杀死暗泽失落者和他们的首领卡塔鲁，否则我就要在惶惶不安中度过馀生了。', '塞纳里奥庇护所的伊卡因希望你转至暗泽村，杀死卡塔鲁、8个暗泽先知、6个暗泽巫医和6个暗泽神谕者。', '谢谢你，$N。我终于能安心的在夜里睡觉了。要不是我又老又弱，我就会自己对付我的敌人。$B$B拿着这些金子。虽然不多，但你的好心不能没有报酬。', '你回来了;卡塔鲁和昂布拉凡奴隶死了吗?', '', '去赞加沼泽找塞纳里奥庇护所的伊卡因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9748, '毒水', '据我们的萨满祭司说，由于水源受到污染，水元素变得躁动难安。我们知道西边的山脉中散落着埃索达的能量核心。一定是能量核心泄漏出的挥发性液体污染了水源！我要你去采集水样。$B$B<伊索姆指着一只小瓶，点了点头。>$B$B拿上这只小瓶，沿着河岸往北走，在秘血岛河流入海口附近取一份水样，然后把水样带回来给我。', '用水样瓶取回一份秘血岛水样，然后向秘血岗哨的守备官伊索姆复命。', '就如我想的一样，这个水会变成红色是因为核心液体渗漏所造成的污染。$B$B我希望你没有在任何一个被污染的水里游泳。', '不要喝那个水，$N!', '', '去秘血岛找秘血岗哨的守备官伊索姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9761, '清除路障', '只有历经战火洗礼、高贵无畏和意志坚定的德莱尼人才有资格接受莱戈苏的任务。主教是不会指派阿古斯之手的成员来破坏矢量感应器、杀死希隆娜丝的。他拒绝将任何德莱尼人派去完成那个任务——因为这无异于自杀……$B$B<考尔琳叹了口气。>$B$B我的职责是削弱炎鹰部队的防御力量。杀掉那些驻守在矢量感应器附近的炎鹰血精灵，为未来的勇士清除路障吧。', '杀死8个炎鹰破坏者和8个炎鹰侦察兵，然后向守备官营地的守备官考尔琳复命。', '希望在他们召唤援军来保护你刚守卫的区域前会有一个英雄到来。', '你有在这附近看到勇敢又强大的不寻常的德莱尼吗?', '', '去秘血岛的守备官营地找守备官考尔琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9763, '督军的末日', '当你悄悄地隐藏在敌人的藏身之处外面的入口时，会发现一些非常有用的情报。$B$B几个小时前，我看到有一群纳迦穿过了左边第二个隧道的石门。我不太懂他们的语言，但是我非常肯定地听清了其中一个词：卡利瑟里斯。$B$B那里一定是通往督军卡利瑟里斯的指挥营——蒸汽地窟的入口。你必须找到并阻止他。我太虚弱了，没有办法帮上一点忙。', '观察者杰哈恩要求你找到并杀死盘牙水库的督军卡利瑟里斯。', '我们在这区域最大的敌人终于死了。你帮了远征队一个大忙，$N。$B$B我们永远都欠你一份人情。', '卡利斯瑞怎么样了?他死了吗，$N?', '', '去赞加沼泽找盘牙水库的观察者杰哈恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9764, '瓦丝琪的命令', '这封信中记载了一份详细的指令，是下达给那些操作蒸汽泵的盘牙纳迦的。指令中提到塞纳里奥德鲁伊已经进入盘牙水库，并命令他们一旦发现入侵者就格杀勿论。这份命令还指示需要将其它湖泊引入盘牙水库的水量翻倍。信上盖有声名狼藉的瓦丝琪的印章。$B$B塞纳里奥远征队的德鲁伊会对这封信感兴趣的。将它交给远征队的首领伊谢尔·风歌吧。', '将瓦丝琪女王的命令交给赞加沼泽塞纳里奥庇护所的伊谢尔·风歌。', '瓦许!$B$B这比我们预料的还惊人。我们对抗纳迦的小胜利根本不算什么。$B$B瓦丝琪女王也涉入其中，所以比我们还强大的力量正在运作中。$B$B你把这带来给我们是对的，$N。现在我们一定要准备作战了。', '你手里拿着什么，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9765, '战争准备', '塞纳里奥远征队抱着和平的意图而来，却不得不面临与纳迦的这场全面战争。$B$B远征队的许多成员斗志昂扬地准备投入战斗，可惜我们的装备过于简陋。替我夺回一些纳迦的武器来，这样我们就能将它们重新铸造成利刃和箭头。$B$B$N，我们要利用盘牙武器铸造最好的兵器。盘牙水库便是纳迦的据点。', '从盘牙水库的纳迦手中夺得盘牙武器，将它们交给赞加沼泽塞纳里奥庇护所的伊谢尔·风歌。', '这些非常适合，$N。你找到任何多的装备就带来给我。我们的需求量很大而我们的资源很不足。', '你弄到我要的装备了吗，$N?', '', '去赞加沼泽找塞纳里奥庇护所的伊谢尔·风歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9766, '盘牙武器', '', '', '做的好，$N。这样纳迦就会知道不能小看我们。', '我们会将纳迦自己的钢铁拿来铸造成武器对付他们。帮我把你在盘牙蓄湖找到的装备带来给我。', '', '去找伊谢尔·风歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9769, '时尚无罪', '<玛加沙莞尔一笑。>$B$B我敢打赌，如果他们知道自己身上的衣物取材于昆虫的翅膀，这种流行趋势立马就会终结。$B$B一开始，我们杀死岗哨附近的萤火虫仅仅是因为它们妨碍了我们的建筑工作。后来，有位商人曾在沼泽鼠岗哨留宿一晚，次日就买走了所有的虫翼！$B$B据说他利用虫翼来制作衣服。唔，我还是喜欢自己的盔甲。如果你能收集到一些虫翼，我很乐意将它们买下来。', '猎杀赞加沼泽的萤火虫，将8片透明的虫翼交给沼泽鼠岗哨的玛加沙。', '这些翅膀非常好，$N。这是你的酬劳。$B$B<玛卡莎弯曲一个翅膀并将它拿到头旁边。>$B$B不，不适合我，但我要跟谁抱怨?$B$B<玛卡莎耸耸肩。>$B$B有钱能使鬼推磨。', '那是什么?你被萤光蛾咬啦?$B$B<玛卡莎对她自己的笑话咯咯笑个不停。>', '', '去赞加沼泽找沼泽鼠岗哨的玛加沙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9770, '沼牙的威胁', '有时候我真希望德恩加能派一位萨满祭司来沼泽鼠岗哨，或者至少给我们一根图腾来牵制沼牙撕裂者吧。$B$B这些害虫泛滥成灾！事情有些不大对头，难道它们没有天敌吗？$B$B我们轮流负责捕杀沼牙撕裂者，真是疲惫不堪。$N，你来得正是时候。祝贺你！现在就出去猎杀这些该死的害虫吧！', '沼泽鼠岗哨的里维伊要你去杀死10只沼牙撕裂者。', '你已经杀了足够的数量吗?$B$B<瑞伏基笑了笑。>$B$B我们的访客都待不久是有原因的。$B$B如果我有选择的话，我会找个更宜人的地方当前哨，但我宁愿解决那些沼牙生物也不想再忍受丹杰的脾气了。', '我还是看的见沼牙生物，$N。你当然没那么快就完成。', '', '去赞加沼泽找沼泽鼠岗哨的里维伊。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9772, '尤尔巴的报告', '枯萎的蘑菇碎粒布满斥候尤尔巴的尸体。杀死他的一定是某种浑身长满菌类的生物，比如说盘踞在死亡泥潭的枯萎的巨人。枯萎的巨人很可能趁尤尔巴坐下来写报告时偷袭了他。$B$B若是找不到那份报告，我们根本无从得知他究竟发现了什么秘密。如果你找到了尤尔巴的报告，就把它交给祖莱。', '从枯萎的巨人手中夺回斥候尤尔巴的报告，把它交给沼泽鼠岗哨的祖莱。', '<祖瑞伊从你手中接过报告并简略阅读它。>$B$B这里大部分的资讯我们都已经知道了。那区域里的一切几乎都干枯或凋谢，但这里有个新线索。$B$B他说真菌巨人缺乏水份后似乎变的很狂暴。从你的描述看来，那八成是杀了他的凶手。$B$B我会吩咐我的人避开那个区域。我们不能再失去更多人手了。', '你回来了，但杰巴没跟你一起回来。他怎么了?', '', '去赞加沼泽找沼泽鼠岗哨的祖莱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9773, '别再提蘑菇了！', '蘑菇汤、蘑菇粥、蘑菇丸子、蘑菇酱！$B$B蘑菇、蘑菇、蘑菇！这里能吃的只有蘑菇。如果你饿了，厨师会扔给你一把斧头，让你自己去采些蘑菇回来！$B$B唔，我厌倦了每餐都吃蘑菇。我曾在这附近的湖泊中见过某种鳗鱼。虽然它们的长相着实恶心，但总比蘑菇好！$B$B我得吃顿像样的食物才行，说吧，我出多少钱可以让你替我弄些鱼肉大餐来？', '猎杀暗泽鳗鱼，将8份电鳗鱼片交给沼泽鼠岗哨的玛加沙。', '终于，在千篇一律的蘑菇之后可以休息一下了!如果你不是一身鱼腥味的话，我会拥抱你!$B$B让我们来看看其它人闻到鱼在火上烤的时候会有多么羡慕。', '告诉我你没有空手回来，$N。', '', '去赞加沼泽找沼泽鼠岗哨的玛加沙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9774, '厚重多头蛇鳞片', '里维伊带来了他的皮甲，真是明智啊。用不了多久，沼泽地潮湿的环境就会让我这身锁甲完全报废。$B$B我一直在设法替换这些快要生锈的部件。居住在沼泽中的多头蛇具有厚重的鳞片，能帮助它们抵御湿气。$B$B但是，要筛选出合适的鳞片却颇为费事。那些品质优良的鳞片要么被撕裂，要么因为长期的磨损，已经薄得不适合制作护甲了。去较大的湖泊中帮我找些厚重多头蛇鳞片来吧。', '将12块厚重多头蛇鳞片交给沼泽鼠岗哨的祖莱。', '谢谢你，$N。每一小片都派的上用场。$B$B我还要很久的时间才能替换完全，但事实上，我在等待巡逻的时候还有什么事可以做呢?', '我看到你在奸笑了。是的，我的护甲在所有的旧金属都替换完成前都会看起来很奇怪，但这样总比毫无防护来的好。', '', '去赞加沼泽找沼泽鼠岗哨的祖莱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9775, '向暗影猎手德恩加报到', '暗影猎手德恩加一定盼望着能收到沼泽鼠岗哨建设进度的报告。我已经准备好了一份简明报告，可惜斥候尤尔巴不幸丧命，我们根本抽不出多馀的人手去送报告。$B$B如果你正要转至西边的话，能不能把这份报告捎给萨布拉金的德恩加？$B$B暗影猎手德恩加乍看起来很有威慑力，不过跟他相处久了，你就会发现他其实是个挺不错的家伙。', '将祖莱的报告交给赞加沼泽中萨布拉金的暗影猎手德恩加。', '你为什么不说你有祖瑞伊的报告?我一直在等他的消息。$B$B我派他去那里向我们报告东边边界的消息，不是闲闲没事。让我看看他有什么话要说。', '你看起来不像是我的人。说吧，$r。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9777, '灿烂的孢子', '$N，赞加沼泽中的可燃材料数量非常稀少，我们必须通过其它途径来解决泰雷多尔的照明问题。生活在沼泽中的许多动植物都可以散发出柔和的光芒。$B$B捕捉并囚禁那些发光的动物过于残忍，因此我们选择了某种特殊的蘑菇做为光源。$B$B虽然我们在泰雷多尔种植了这种灿烂的孢子，但仍然无法满足照明的需求，因此时常需要外出采摘。这种绿色的小蘑菇通常生长在泰雷多尔附近较大的蘑菇的根部。', '将6个灿烂的孢子交给泰雷多尔的鲁埃姆。', '这些是很好的孢子，应该可以让我们持续运作好一段时间。谢谢你帮我们补充物资，$N。', '照情况来看，我们需要很快的补充蘑菇。', '', '去赞加沼泽找泰雷多尔的鲁埃姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9779, '拦截情报', '$N，很高兴见到你。或许你能帮我解决眼下的难题。$B$B位于炎鹰部队后方的密探回报，他们发现炎鹰士兵正在研究一份非同寻常的文件。$B$B可惜我们没能获得这份文件的副本，因此我要你转至血精灵营地取回文件。我相信，只要你采取足够强硬的手段，我们必定能从某个炎鹰士兵那儿获得相关的信息。我允许你随心所欲地使用武力。', '不断杀死炎鹰血精灵，直到你找到炎鹰信函，然后向秘血岗哨的守备官波鲁斯复命。', '<复仇者波罗斯看着文件。>$B$B这是萨拉斯语。幸好，我知道谁可以翻译……', '这么快就回来了?你找到书信了吗?', '', '去秘血岛找秘血岗哨的守备官波鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9780, '电鳗鱼片', '真高兴能在这里见到新面孔。我和海尔伦初次来到泰雷多尔时，也像陌生人那样拘谨，不过那似乎是很久以前的事了。$B$B我们欢迎所有路经此地的冒险者，并努力确保泰雷多尔维持着充足的食物供给。虽然我们无法回报好心肠的泰雷多尔学者，但是我们会以他们为榜样，将温暖的关怀传递到每个角落。$B$B附近的湖泊中生活着一种名叫电鳗的鱼类，它们的肉是我们的主要食物来源。如果你愿意帮忙的话，就去收集一些电鳗鱼片吧。', '将8份电鳗鱼片交给泰雷多尔的诺兰妮。', '谢谢你的帮忙，$N。我们不会忘记你的慷慨协助。', '你有任何鱼肉可贡献给我们储藏吗?', '', '去赞加沼泽找泰雷多尔的诺兰妮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9781, '不堪重负', '上次外出狩猎时，我发现一群巨魔正在建造新的岗哨。毫无疑问，他们已经开始捕杀沼泽地的动物了。$B$B如果他们打算长期驻扎下来的话，食物的竞争将变得非常激烈。我们总不能无缘无故地向这些巨魔发动攻击吧？但是，我们可以设法减轻大自然中跟我们竞争食物的动物所带来的压力。$B$B干掉一只泥潭多头蛇，就少了三张贪吃的嘴！多划算啊！', '杀死10只泥潭多头蛇，然后向泰雷多尔的海尔伦复命。', '做的好。那应该可以减缓这里迫切的食物补给需求，虽然我们还需要找到新的食物来源。鱼和蘑菇够了，但我们永远不能低估了变化。', '打猎进行的怎么样，朋友?', '', '去赞加沼泽找泰雷多尔的海尔伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9782, '死亡泥潭', '$N，我与泰雷多尔的学者们共同生活了一段时间，对赞加沼泽的生态环境有了深刻的了解。最近，我留意到东北方的沼泽地出现了令人不安的变化。$B$B所有的生命似乎都无缘无故地开始枯萎并死亡。我大概猜到发生了什么事，但也仅仅是我个人的推测而已。如果你能取回一份泥土样本，我或许能弄清楚真相。', '将一份死亡泥潭土壤样本交给泰雷多尔的守备官伊达尔。', '嗯……泥土看起来已经耗尽了，所以这不可能是问题的原因，我认为。这里的共同关连是什么?为什么所有的东西都突然死亡了呢?', '你拿到死亡污泥的泥土样本了吗?', '', '去赞加沼泽找泰雷多尔的守备官伊达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9783, '异样的干旱', '$N，你带回的泥土样本几乎完全失去了水分。如果连土壤都干涸的话，生活在死亡泥潭的生物一定面临着巨大的痛苦。$B$B瞧瞧那些枯萎的真菌巨人，难以忍受的苦楚令他们丧失了心智，到处攻击别的生物。$B$B这些巨人根本不明白发生了什么事。我们没有能力挽救枯萎的巨人，只能选择结束他们的痛苦。', '泰雷多尔的守备官伊达尔要你去杀死12个枯萎的巨人。', '谢谢你帮忙解决这个困难的任务，$N。我们在死亡污泥的工作还没结束，但现在我们会致力于复原区域的平衡。', '毁灭死亡污泥的生物让我很痛苦，但我们也救不了他们。我们能做的就是努力让该区域复原，养育一个新世代。', '', '去赞加沼泽找泰雷多尔的守备官伊达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9784, '鉴定植物', '', '', '非常好。继续带给我更多的植物组织。$B$B<这个任务可以重复进行直到声望达到尊敬。>', '我还需要更多的植物组织。随着湖泊的水分流失，我有预感入侵当地生态的品种数量正不断的攀升。不过，我需要更多的数据来支持我的理论。', '', '去赞加沼泽找塞纳里奥庇护所的劳兰娜·萨维尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9785, '古树的祝福', '$N，你已经赢得了塞纳里奥远征队的信任。现在，与我们的盟友——古树埃西恩和克勒斯谈谈吧，获得他们的祝福。$B$B这些古树所赐的印记可以赋予你强大的力量。随着你在塞纳里奥远征队的声望不断提升，印记的力量也会相应增强。$B$B$N，去吧，请求古树赐福与你。', '唤风者塔鲁·黑蹄要求你与塞纳里奥庇护所的埃西恩和克勒斯谈一谈，获得古树的祝福。', '你回来了。你得到古树的祝福了吗?', '你和古树谈过了吗，$N?', '', '去赞加沼泽找塞纳里奥庇护所的唤风者塔鲁·黑蹄。', '知识印记', '战争印记', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9786, '博哈姆废墟', '在兽人大肆屠杀我的族人之前，泰雷多尔曾是德莱尼学者和灵魂师的庇护所。一部分德莱尼学者和守备官奉命管理这片区域的数座神殿。$B$B在混战中，我们与驻守神殿的学者失去了联系，尤其是西南方的博哈姆神殿。有报告称一支失落者氏族已经在那儿安营扎寨。调查博哈姆废墟，然后向我汇报情况。', '泰雷多尔的学者安霍尔要你去侦察博哈姆废墟。', '所以，菲拉芬的失落者已接管废墟了?真有趣。他们一定记得自己的继承物和该地点的重要性。我们一定要了解更多，$N。这个神庙可能是解救失落者和重新团结许多德莱尼的关键。', '你探勘过波哈姆废墟了吗?你能想象他们全盛辉煌的时期是什么样子吗?', '侦察博哈姆废墟', '去赞加沼泽找泰雷多尔的学者安霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9787, '蛮沼雕像', '从你在博哈姆废墟观测到的情况来看，这支失落者氏族似乎恢复了对野兽之灵的崇拜。想要接近他们，就必须了解到更多关于该氏族信仰的信息。$B$B返回蛮沼村，小心地收集一些雕像，把它们带回来供我研究。$N，尽量避免惹恼蛮沼失落者，否则很可能破坏我们与他们创建沟通的机会。', '将6个蛮沼雕像交给泰雷多尔的学者安霍尔。', '这应该足够了，$N。他们似乎对鸟类很迷恋，但是这很奇怪，因为赞加沼泽没有土生的鸟类。这代表什么?$B$B他们有可能遇到了阿拉卡吗?对一个萨满民族而言，他们可能喜欢强大的鸟类灵魂化身。', '你拿到塑像了吗?', '', '去赞加沼泽找泰雷多尔的学者安霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9788, '阴冷之地', '我逃出暗泽村后，就躲藏在村子南边的洞穴中。我根本不知道沼泽生物和孢子人正在争夺那处洞穴！$B$B在匆忙撤离洞穴时，我不小心落下了一只装满我全部珍宝的箱子。$B$B我好不容易才带着宝箱逃离暗泽村，没想到这么快又失去了它，这简直是命运对我的嘲弄。如果你愿意帮我找回它，我就送你一件好东西。$N，你觉得怎么样？', '进入暗泽村以南的一处洞穴寻找伊卡因的物品，把它们还给赞加沼泽塞纳里奥庇护所的伊卡因。', '我的东西!全都在这!$B$B谢谢你，$N。如我所承诺的，我要让你选一个物品。我没有太多东西，但我的族人永远都乐于分享仅有的一切。', '你找到我的东西了吗，$N?那洞穴离昂布拉凡不远，就在纳格兰的边界附近。', '', '去赞加沼泽找塞纳里奥庇护所的伊卡因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9789, '狩猎裂蹄牛', '想在狩猎队中赢得一席之地？那你就得证明自己的实力。$B$B我可不管你以前杀过什么猛兽；如果你没捕获过纳格兰的野兽，就不算合格的猎手。如果你认为自己够强壮，就从猎杀裂蹄牛开始吧。$B$B它们分布在狩猎队营地四周以及偏南的地带。', '杀死12头裂蹄牛，然后向纳格兰奈辛瓦里狩猎队营地的赫米特·奈辛瓦里复命。', '一个不错的开始。不过这只是个开始。$B$B低等的裂蹄证明不了什么。来面对更大的挑战吧。', '纳格兰的裂蹄是个很好的挑战。我已经猎捕到好一些了。$B$B你进行的怎么样?', '', '去纳格兰找奈辛瓦里狩猎队营地的赫米特·奈辛瓦里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9790, '透明的虫翼', '生活在这穷乡僻壤，迫使我们学会了就地取材，物尽其用。当然，你最好别去细想某些材料的来源。$B$B我发现暗光钉刺者的翅膀具有防水效果。它们的质地坚韧、轻薄而富有弹性。$B$B<海尔伦轻声地笑了。>$B$B瞧你脸上的表情。我说过，别去细想这些材料的来源。如果你正要出去走走，能不能帮我带回一些虫翼？', '猎杀赞加沼泽的萤火虫，将8片透明的虫翼交给泰雷多尔的海尔伦。', '谢谢你，$N。$B$B<哈尔隆恩悲怜地微笑。>$B$B至少你不用清理它们。这是所有工作中最讨厌的一个，但一旦完成后，你永远也不会知道它是来自于一只庞大的昆虫。', '你收集到那些萤光蛾翅膀了吗?', '', '去赞加沼泽找泰雷多尔的海尔伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9791, '沼牙的威胁', '在兽人与德莱尼人交战期间，为了避免遭受袭击或是沦为俘虏，我们很少离开泰雷多尔。现在，我们时常会冒险外出，但是沼泽地依然危机四伏。$B$B最近几个月，虚空鳐越发肆虐起来。不知道是不是跟激烈的捕食竞争有关，它们频繁地攻击我们的粮草征收队。如果我们能削减泰雷多尔附近的虚空鳐的数量，或许它们就不会再来滋扰生事了。', '杀掉10个沼牙撕裂者，然后向泰雷多尔的诺兰妮复命。', '谢谢你帮忙清除了一些沼牙撕裂者，$N。如果他们有点智慧的话，或许他们就会知道生命和放生是最好的选择。$B$B<诺纳尼耸了耸肩。>$B$B巨大，过度生长又有智慧的虫子。不知道那是什么样子……', '你的沼牙打猎进行的顺利吗?', '', '去赞加沼泽找泰雷多尔的诺兰妮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9793, '图雷姆的命运', '先知维伦坚持不懈寻求盟友的事迹鼓舞了外域的德莱尼人，他们开始搜寻自己的同盟。燃烧军团将我们逐出城镇和神殿，却没能摧毁我们的文明。$B$B泰罗卡森林的图雷姆曾经是我的家园，也是第一座被兽人侵占的城镇。我很久都没有收到来自图雷姆的消息了。转至泰罗卡森林的奥蕾莉亚要塞，将这封信交给安达尔吧，顺便查探那儿的情况。', '将守备官伊达尔的信交给泰罗卡森林奥蕾莉亚要塞的安达尔。', '嗯……我记得我有听过我们的斥候谈起北边森林有个德莱尼居住地的废墟。我本身不太了解那废墟的事，不过你可以和一些斥候聊聊。', '我能帮你什么忙吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9794, '禁止拆阅', '$N，我想请你帮个忙。通常我都是自己来做这件事，不过眼下实在是忙不过来。$B$B我的朋友基亚隆居住在北边刀锋山的希尔瓦纳。他希望近期能收到我的回信，不过我怀疑信件的内容只会令他心情不悦。$B$B如果你能帮我把这封信交给他，我会非常感谢你的。我要强调一下，这事儿非同小可，你绝对不能私下拆阅。只有基亚隆有权阅读此信。', '将迪莫斯的信交给刀锋山希尔瓦纳的基亚隆。', '所以你带了提莫斯的答复来?$B$B<齐亚隆读了一下信，然后笑了。>$B$B他说他把一切都搞定了。他说不需要帮忙。我就知道!$B$B有些人就是不会变。看，他还有时间纠正我的拼写。$B$B<齐亚隆发出一声无趣的叹息。>$B$B我不该寄这封信的。我忘了。专家永远都能掌控情势。永远。', '<齐亚隆怀疑地看着你。>$B$B我不认识你，$r。你有事找我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9798, '血精灵计划书', '这些计划书似乎挺重要的，你应该将它们交给坠毁点的守备官奥达尔。', '将血精灵计划书交给埃门谷坠毁点的守备官奥达尔。', '来，让我看看那些计画书。$B$B血精灵跟踪我们到了这里?他们真是坏到骨子里了，应该让他们消失在这世界上!$B$B<复仇者平复了一下他的心情。>$B$B我道歉，刚刚失礼了。你发现这个消息让我们欠你一个人情，$N。', '你拿着什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9799, '跑腿采花', '此地的鞭笞者大多聚集在西边的埃门平原。由于地下水源已经被附近的湖水污染，植物学家塔蕾克丝担心在我们净化湖水之前，这些鞭笞者恐怕无法繁衍后代。$B$B转至埃门平原采集一些被污染的花朵，我或许能找出解决办法来。被污染的花朵有着非比寻常的红色花瓣，很容易辨认。', '采集3朵被污染的花朵，然后向埃门谷坠毁点的学徒维莎尔复命。', '这些看起来像完好的品种。谢谢你完成了牧场的工作。等我有时间分析它们，我应该就能知道如何使牧场复原了。', '哈罗，$C。你弄到那些花了吗?', '', '去埃门谷找坠毁点的学徒维莎尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9800, '稀有的豆子', '凭你这身差劲的装备，怎么能与纳格兰躁动不安的元素抗衡呢？还是先提升下自己的装备再想想如何帮助大地之环吧，比如……潜水用品。$B$B在元素王座西边的草原上，随处可见纳格兰的野生动物留下的粪堆。你拔开粪堆之后就可以找到一些卡拉果。这种果实制成的小药片能帮助你潜水，对抗那些元素生物。$B$B收集两只拳头那么大的一堆卡拉果……我是说按食人魔的拳头尺寸来算。', '将8颗挖出来的卡拉果交给纳格兰元素王座的元素师鲁艾普。', '请不要用王座神圣的水洗你的身体。$B$B<元素师罗艾柏拿出一个预先准备好的豆子药片。>$B$B将这个放在你的舌头下面让时间融化它。等它融解了，你就能像在呼吸空气一样在水里呼吸。', '<元素师罗艾柏做出两个拳头对立的样子并不同意的摇摇头。>$B$B巨魔般尺寸的拳头……', '', '去纳格兰找元素王座的元素师鲁艾普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9801, '收集材料', '我觉得失落者也许不会友善地对待德莱尼人，但是他们肯定会对鸦人示好。我可以配制一\r\n种特殊的药水，让你在短时间内伪装成鸦人。这种药水需要两种材料，但是它们无法长期储藏，必须在采集后的数小时内使用，否则就会失效。$B$B替我收集一些孢子蝠的眼睛和沼泽阔步者的触须。孢子蝠和沼泽阔步者分布在泰雷多尔四周。', '将4只孢子蝠的眼睛和4根沼泽阔步者的触须交给泰雷多尔的学者安霍尔。', '这些会非常有用。让我混合一下这个药水。', '你收集到材料了吗?', '', '去赞加沼泽找泰雷多尔的学者安霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9802, '赞加沼泽的植物', '赞加沼泽的湖泊日益干涸，我们尚未查明具体原因，但是许多植物正面临灭绝的危险。$B$B做为远征队的编目者，我的任务是记录和鉴定植株，帮助我们更好地了解它们的特性。$B$B如果你愿意帮忙，就替我采集一些未鉴定过的植物。如果你恰好是草药师的话，可以直接从地面上采集到这种植物，当然你也可以在沼泽生物身上找到它们。', '将10株未鉴定过的植物交给赞加沼泽塞纳里奥庇护所的劳兰娜·萨维尔。', '本地品种的数量减少情形令人忧心。侵入性品种的增加可能和最近的生态干扰有关。不过我还没有足够的资讯可做结论。$B$B<罗安娜一边检视那些植物一边在日记上草草记下一些笔记。>$B$B带着这些，$N。它们或许对你有用。$B$B把任何你找到的其它未经辨认的植物组织带来。我就会把它们统计在我的资料里。', '你有找到任何植物组织吗?', '', '去赞加沼泽找塞纳里奥庇护所的劳兰娜·萨维尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9803, '蛮沼的信使', '是时候向蛮沼失落者表明我们的诚意了，让他们明白圣光并没有抛弃他们。带上我为你准备的药水，转至博哈姆废墟。$B$B到达废墟后立即喝下药水，伪装成蛮沼失落者崇拜的猛禽之魂的模样。与长者库鲁提谈一谈，告诉他德莱尼人将蛮沼失落者视为失散多年的同胞，我们期待着与他们的重聚。', '到达博哈姆废墟后饮下安霍尔的药剂，伪装成鸦人，然后与长者库鲁提谈一谈。', '他们拒绝?他们可以选择自己想要的道路，当然，但他们的选择让我太惊讶了。我认为所有的德莱尼，包括破碎者和失落者，都会记得我们全都是同一个种族的一份子。$B$B我们是不该欺骗他们，但难道他看不出我们的意图是友善的吗?', '你和菲拉芬的长者谈过了吗?', '', '去赞加沼泽找泰雷多尔的学者安霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9804, '天歌湖的元素', '纳格兰水域中那异常的潮汐涨落令天歌湖的湖水之魂躁动不安。它们沿着水道，企图将骚乱的种子传播到其它地方。$B$B流水之贤者瓦图苏以幻像的形式出现在我们面前，请求大地之环伸出援手，找出这场骚乱的根源，令躁动的元素恢复平静。$B$B我们一定要揪出破坏自然平衡的幕后真凶，不过首先你必须解决元素王座眼前的难题。杀死湖水之魂，然后向我复命。', '消灭8个湖水之魂，然后向纳格兰元素王座的元素师鲁艾普复命。', '<元素师罗艾柏在水里跪下并开始祈祷。>$B$B大地之环对所做的事并不自豪。我们做该做的事来治疗大地。', '在你还没潜入太深的湖底时使用纳格兰樱桃。', '', '去纳格兰找元素王座的元素师鲁艾普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9805, '伊森拉图斯的祝福', '卑鄙的失落者！那群家伙被放逐到赞加沼泽后，仍然蠢蠢欲动，企图将污秽的种子传播到世界的其它角落。$B$B我已向元素寻求解决之道，并与他们达成了共识：要根治这场骚乱，就得让失落者尝尝元素的厉害！$B$B这蔟活火取自伊森拉图斯的火焰精华。转至东南方的风茅村，用活火焚毁失落者的小屋！让他们看看那熊熊燃烧的怒火！', '纳格兰元素王座的元素师鲁艾普要你焚毁风茅村的大棚屋、西部棚屋、南部棚屋和东部棚屋。$B$B完成任务后将活火还给元素师鲁艾普。', '你的努力抑止了污染的散播但其它的问题仍浮上台面。', '我非常惭愧的告诉你，是我的族人想在纳格兰的水源建造沼泽地。', '', '去纳格兰找元素王座的元素师鲁艾普。', '烧毁大棚屋', '烧毁西部棚屋', '烧毁南部棚屋', '烧毁东部棚屋');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9806, '成熟的孢子', '孢子蝠和泥沼游荡者通常聚集在沼泽地的长杆蘑菇附近，它们的附肢上堆积着许多成熟的孢子。$B$B瞧，我们身材矮小，能够采集到的孢子非常有限。你能帮我们从孢子蝠和泥沼游荡者身上收集成熟的孢子吗？所有的孢子人都会感谢你的。', '从赞加沼泽的孢子蝠和泥沼游荡者身上收集6个成熟的孢子，把它们交给孢子村的格沙弗。', '这些是很棒的孢子，$N!长梗蘑菇对重建我们的城镇来说是很重要的。在经历所有的泥沼领主攻击后，我们的物品正短缺。', '你回来了，$N。你取得了丰饶孢子吗?', '', '去赞加沼泽找孢子村的格沙弗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9807, '更多成熟的孢子', '', '', '感谢你的帮忙，$N。你会继续努力吧?', '我们永远都需要更多的丰饶孢子，$r。长梗蘑菇是非常有用的蘑菇。种植它们让我们可以利用它们做很多事。', '', '去赞加沼泽找孢子村的格沙弗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9808, '亮顶蘑菇', '我看见你们使用亮闪闪的金属圆片来交换各自需要的东西。其实我们跟你们差不多吧，不过我们用的是亮闪闪的圆蘑菇。$B$B沼泽地里遍布着亮顶蘑菇，你只需要懂得如何采集这些蘑菇而不至于将它们弄坏就行了。如果你愿意帮助我们采集一些亮顶蘑菇，我就告诉你该怎么做。$N，你觉得怎么样？', '将10枚亮顶蘑菇交给赞加沼泽孢子村中的姆希菲。', '这可以让我们和其它孢子人交换食物和补给。孢子村感谢你，$N!', '你找到白闪菇了吗，$N?它们真的在沼泽里到处都是。$B$B如果你注意的话，远远就可以看见它们闪亮的白光了。', '', '去赞加沼泽找孢子村的姆希菲。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9809, '更多亮顶蘑菇', '', '', '谢谢你，$N。身为孢子村的长者，我一定要确保我的人民有足够的补给。你让我的工作更轻松了。', '如果你有更多白闪菇就给我。我们村子永远都需要更多白闪菇。', '', '去赞加沼泽找孢子村的姆希菲。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9810, '污染的灵魂', '瓦图苏设法抵御了这场灾难的侵袭，可惜这位贤者却不慎在净化过程中制造出了一块扭曲的灵魂精华。这块灵魂精华汇集了最可怕的元素污染质！$B$B转至西南方的沼泽地，瓦图苏的污染精华就藏匿在日泉湖的深处。$B$B杀死瓦图苏的污染精华以及日泉湖中被污染的水元素生物。', '杀死瓦图苏的污染精华和8个湖水涌动者，然后向纳格兰元素王座的元素师鲁艾普复命。', '在污染的精华被摧毁的一刻，元素赞颂你的胜利!大地之环感谢你并请你选一个奖励。', '大地之环会尽全力帮忙。', '', '去纳格兰找元素王座的元素师鲁艾普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9811, '辛多雷的朋友', '这是血精灵历史新篇章的开始，$N。你让我们的种族与你的种族之间的联系更加紧密了。$B$B将这个叛徒的首级拿去交给银月城的摄政王洛瑟玛·塞隆。他一定是最渴望听到这个消息的人。', '将达尔坎的徽记交给银月城的洛瑟玛·塞隆。', '你杀了达克汗，$r?了不起。我有预感我们的人民很快就会变成好朋友了。', '你想和我说话，$C?我可不记得你有先预约喔。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9813, '觐见酋长', '你知道的，我还没有丧失对往昔的故乡与人民的爱。我曾为了银月城能在幽暗城与奥格瑞玛的谈判桌上有一席之地而与兽人针锋相对。$B$B你带来的消息可以让任何反对者闭上嘴。立刻将这封信送给奥格瑞玛的萨尔酋长。身为部落的领袖，他会最终接受辛多雷的效忠宣誓。$B$B我已经在信上盖了自己的印章，表明了我个人的认可。到城市的西北方去，你就可以找到地精飞艇的空港，搭乘飞艇可以很快到达杜隆塔尔。', '希尔瓦娜斯·风行者要求你将她的密信交给杜隆塔尔首都奥格瑞玛的萨尔。', '<萨尔开始读信。>\r\n\r\n血精灵终于解决掉他们的小麻烦了。别介意它借助了你和整个被遗忘者军队的帮助才完成工作。\r\n\r\n<萨尔笑了起来。>\r\n\r\n我想这谁都阻止不了。最后我们会需要他们就像他们需要我们一样。', '是吧，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9814, '爆顶蘑菇', '朋友，你喜欢蘑菇吗？赞加沼泽萨布拉金附近生长着一种威力强大的蘑菇。$B$B不过你要当心，它们被称为爆顶蘑菇是有原因的。如果你没有做好防护措施就贸然靠近的话，它会突然爆炸！砰！形成一团有毒的孢子云。$B$B我利用这种蘑菇预测吉凶，可是已经快用完了。', '将6枚爆顶蘑菇交给巫医托尔加什。', '这些非常好，老兄!$B$B跟你说吧。既然你是个好人又帮忙弄到蘑菇，我就让你进来玩玩!', '你弄到蘑菇了吗，老兄?', '', '去赞加沼泽找萨布拉金的巫医托尔加什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9815, '潜水', '在纳格兰被污染的各处水域之中，以西南方哈兰盆地的情况最为严重。那里有许多躁动难安的水元素在废弃的哈兰城下徘徊。一般来说，某些元素生物的残骸不会对环境造成任何影响，泥泞爪牙则不然，必须将它们的残骸全部销毁。$B$B泥泞爪牙死后，会留下沾满淤泥的核心。如果不加处理的话，就会继续扩散开来，对环境造成负面影响。$B$B杀掉泥泞爪牙，将沾满淤泥的核心带回来给我。', '将5个沾满淤泥的核心交给纳格兰元素王座的元素师鲁艾普。', '大地之环感谢你，$N。元素也感谢你。我们感谢并会记住你对净化我们世界持续的努力。', '不要留下任何受污染的菌体!', '', '去纳格兰找元素王座的元素师鲁艾普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9816, '你见过鱼人吗？', '朋友，你不觉得赞加沼泽少了点什么吗！这里居然没有鱼人。$B$B别担心，我来解决这个问题。看见加尔戈和古尔戈了吗？我准备将鱼人作为礼物送给失落者！$B$B带上这只笼子转至匕潭村，在村子东北角把它们放出来。当然，我可不能让加尔戈和古尔戈跟着你去那种危险的地方，但是我会给你一笼子各色各样的小鱼人。将鱼人笼放在那块平坦的岩石上，然后打开笼门！', '将鱼人笼放在匕潭村附近的平坦的岩石上。', '做的好，老兄!我希望他们玩的愉快!', '<巫医托卡斯咧嘴笑了笑。>$B$B失落者喜欢他们的礼物吗?', '', '去赞加沼泽找萨布拉金的巫医托尔加什。', '在匕潭村放生小鱼人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9817, '血鳞纳迦的领袖', '塞纳里奥远征队悬赏击杀血鳞纳迦的首领弗亚希王女的勇士。这名纳迦女巫最后一次被发现是在赞加沼泽北部的毒蛇湖。$B$B血鳞纳迦极度危险，想要挑战他们的首领的勇士必须非常小心谨慎。$B$B成功击杀弗亚希王女之后，请向塞纳里奥庇护所的监护者哈穆特领取奖赏。', '杀死毒蛇湖的弗亚希王女，然后返回赞加沼泽的塞纳里奥庇护所，向监护者哈穆特领取奖赏。', '我打赌血鳞下次要攻击远征队斥候时会三思而行。拿着这个做为奖励，$N。这是你应得的。', '你是来领取纳吉斯.法亚司的赏金吗?这是我今天听到最好的消息了。', '', '去赞加沼泽找塞纳里奥庇护所的监护者哈穆特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9819, '被折磨的地灵', '将侵占者揪出来。你会找到他的，只要你遵循我的指示。首先消灭那些被折磨的地灵。必须让它们再次沉睡。$B$B<戈达乌挥拳击中大地，碎裂的土壤传来腐臭的气味。>$B$B必须让它们沉睡！$B$B<戈达乌指向东南方。>$B$B地灵就分布在那片山岭中。$B$B让它们睡去吧。$B$B东南方的……塔拉盆地。', '纳格兰元素王座的戈达乌要你消灭10个被折磨的地灵。', '<戈达乌肯定的点点头。>$B$B很好。灵魂安息了。', '他们沉睡了吗?', '', '去纳格兰找元素王座的戈达乌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9820, '通缉：格罗阿克', '死亡通缉令：格罗阿克，安葛洛什食人魔砍伐蘑菇行动的监工。$B$B这个蛮横的渣滓和他的斧头帮走狗砍光了萨布拉金以北的蘑菇林。我们必须阻止格罗阿克，否则他和他的手下就会开辟出一条直达萨布拉金城墙的通道。$B$B击杀格罗阿克的勇士请将他的徽记交给暗影猎手德恩加，领取重赏。', '将格罗阿克的徽记交给萨布拉金的暗影猎手德恩加。', '做的好，$N。不过这些巨魔距离我们前哨这么近，着实让我担心。看来他们从北边的山上往下渗入已经有一段时间了。', '你拿着什么，$N?', '', '去赞加沼泽找萨布拉金的暗影猎手德恩加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9821, '吞食诅咒', '<戈达乌捡起一块岩石咀嚼起来。>$B$B戈达乌要辨别味道。戈达乌知道这块岩石来自何处。$B$B<戈达乌抬起脚，重重地踏向大地。>$B$B瞧。纳格兰。$B$B<戈达乌让你观察他的脚印。地面竟然凹显出一幅完美的纳格兰地形图，戈达乌要你转至地图上被标记的地方消灭被激怒的碾压者。>$B$B杀掉它们！把岩石碎片带给戈达乌！$B$B带上地图。', '将10块被激怒的碾压者的核心交给纳格兰元素王座的戈达乌。', '<戈达乌把咀嚼过的石块吐出来，在你面前形成了一个碎石堆。>$B$B毒药。这些石头不是纳格兰的。这些石头是毒药做的。你要摧毁毒药石块。你要找到“侵入者”古罗克。', '戈达乌吃着这块石头。戈达乌找到“侵入者”。把石头带来!', '', '去纳格兰找元素王座的戈达乌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9822, '战斗迫近', '食人魔选择在萨布拉金附近砍伐蘑菇绝非偶然。我猜测他们准备攻击萨布拉金。$B$B$N，我必须搞清楚这件事。食人魔在西北方设立了另一处哨站——安葛洛什营地。如果他们在密谋袭击计划，一定会留下证据的。$N，转至安葛洛什营地搜寻食人魔进攻计划的线索。将任何可疑的东西都带回来给我。', '将安葛洛什攻击计划交给交给萨布拉金的暗影猎手德恩加。', '<暗影猎人丹杰检查计画书。>$B$B我知道了!巨魔的恶臭总是带着一股暗示的威胁。既然我们有了他们意图的证据，我们一定要比他们先采取行动。', '你找到巨魔意图的证据了吗?', '', '去赞加沼泽找萨布拉金的暗影猎手德恩加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9823, '你死我活', '要解除安葛洛什食人魔的威胁，就必须杀死他们的首领戈尔费斯大王。不过，我们还可以做得更有威慑力一些。$B$B转至安葛洛什要塞，与我们的敌人战斗吧。要塞就在萨布拉金西北方某座小岛的洞穴中。跨越沼泽地边缘那株倒下的蘑菇形成的桥梁，就能看见要塞了。$B$B$N，不要心软。这帮家伙绝不会放过我们。', '杀死戈尔费斯大王、10个安葛洛什殴斗者和10个安葛洛什食魂者，完成任务后向萨布拉金的暗影猎手德恩加复命。', '我们要庆祝你在安格拉斯的胜利，$N。不晓得那些巨魔畜生什么时候会再找到一个嗜血的酋长。$B$B不管如何，我们会准备好对付他们。', '安格拉斯威胁不断向我们逼近。你消灭了他们的领导者吗?', '', '去赞加沼泽找萨布拉金的暗影猎手德恩加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9824, '奥术扰动', '一直以来，我都想要获得一份卡拉赞内能量谱系的拓印……当然，仅仅是出于私人研究之用。可惜我至今仍一无所获。若我能再靠近一些这里的地下水源，这块水晶所能接收的能量信号就会更清晰一些了。$B$B我听说麦迪文的酒窖中有一处地下水井和一处地下水池，那些地方应该就是最合适的采样地点。但是，酒窖里到处都是鬼魂，对我这样的老头子来说太危险了。$N，你愿意帮我这位老人探测卡拉赞的能量谱系吗？', '在麦迪文的酒窖内的地下水源附近使用紫罗兰占卜水晶，然后向卡拉赞外的大法师奥图鲁斯复命。', '这些读数是不好的预兆，$N。卡拉赞应该在放射出各种秘法流……只不过它变成一个巨大的能量真空。没有讯号。什么都没有。除了一个非常微弱的恶魔回音。$B$B这是坏消息，$N。', '读数，$N。你完成了吗?', '', '去找逆风小径的大法师奥图鲁斯。', '收集地下水井的信号', '收集地下水池的信号', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9825, '幽灵的活动', '你也注意到那些徘徊在卡拉赞外的幽灵与鬼魂了吧。它们出现在此地的原因当前完全不明，这令我非常困扰！$B$B去帮我从它们身上收集一些幽灵精华来，或许我可以研究出它们的来意。$N，卡拉赞中隐藏着许多秘密，而我，决心揭开这些秘密之后的真相。', '将10个幽灵精华交给卡拉赞外的大法师奥图鲁斯。', '太好了。我会研究这些精华，$N。谢谢你的帮忙。', '你拿到我要的鬼魅精华了吗，$C?', '', '去找逆风小径的大法师奥图鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9826, '联络达拉然', '$N，探测结果并不乐观。我向来不是个守口如瓶的人，那么就让我告诉你一些关于我所属的组织——紫罗兰之眼的内幕吧。$B$B我们是达拉然肯瑞托法师议会直属的密探，负责监视麦迪文和卡拉赞之塔的状况，避免这里局势失控。$B$B在麦迪文失踪后，我们对这里展开了一次非常迅速的“调查行动”，然后这里就沉寂了下来。$B$B那么，这是一份详细的调查报告，将它交给达拉然巨坑外的大法师塞德瑞克，他也是紫罗兰之眼的成员。', '将奥图鲁斯的报告交给达拉然巨坑外的大法师塞德瑞克。', '艾特罗斯将这个讯息委托给你?那个老笨蛋。$B$B我想伤害已经造成，我们也要好好利用你。你会合作吧?', '你知道紫罗兰之眼的事?你看起来不太眼熟。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9827, '枯萎的孢芽', '仔细地检查孢芽之后，你发现许多可能曾被用来容纳某种东西的凹痕。这枚怪异的蘑菇是一个谜团，它完全不健康，但是你找不到任何线索来了解它可能曾经派作什么用场。$B$B也许熟悉赞加沼泽生态的人应该可以告诉你更多有关这种孢芽的情况。', '将枯萎的孢芽交给赞加沼泽中泰雷多尔的鲁埃姆。', '它看起来像泥沼巨人的孢子台，但我从没看过这种状态的。我听说死亡污泥的巨物也开始枯萎，但它进展的速度远比我所想的还快。\r\n\r\n死亡污泥曾是个湖泊，就像泥沼里其他湖一样，而且是巨物的重生地。但是水退了，这样的改变似乎让巨物无法生长。如果这样的情形持续下去，巨物会完全消失。', '你拿着什么，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9828, '枯萎的孢芽', '仔细地检查孢芽之后，你发现许多可能曾被用来容纳某种东西的凹痕。这枚怪异的蘑菇是一个谜团，它完全不健康，但是你找不到任何线索来了解它可能曾经派作什么用场。$B$B也许熟悉赞加沼泽生态的人应该可以告诉你更多有关这种孢芽的情况。', '将枯萎的孢芽交给赞加沼泽中沼泽鼠岗哨的里维伊。', '它看起来像泥沼领主的孢子台，但我从没看过这种状态的。我听说死亡污泥的巨物也开始枯萎，但它进展的速度远比我所想的还快。$B$B死亡污泥曾是个湖泊，就像泥沼里其他湖一样，而且是巨物的重生地。但是水退了，这样的改变似乎让巨物无法生长。如果这样的情形持续下去，巨物会完全消失。$B', '你拿着什么，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9830, '沼泽中的毒液', '在和德莱尼人交谈时，我总觉得他们的语气中透露出被逐出家园的怨气。他们似乎非常同情破碎者，认为我们失去了某种东西。$B$B虽然圣光不再眷顾破碎者氏族，但是丰富的阅历使我们对自然界的了解更加深入。$B$B我的族人能洞悉到许多潜在的机会，却很少有德莱尼人能如此独具慧眼。举个例子吧，此地的南面和西面是沼光抽血者的聚集地，这种生物分泌的毒液具有广泛的用途，无论是狩猎还是疗伤都用得着。', '将6份沼光抽血者的毒液交给奥雷柏尔营地的普尔鲁。', '谢谢你带毒素来，$N。若要不消耗我个人的存货又要让我的示范成功，那还有好长的路要走。', '我想示范毒囊对 隐士阿浩恩和泰伦多尔其它人的功用。那需要我库存的双倍份量。', '', '去赞加沼泽找奥雷柏尔营地的普尔鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9831, '卡拉赞的钥匙', '这份报告书里提到的情况让我十分担忧，$N，看来的确需要进入卡拉赞调查，但你也要知道，进入卡拉赞是十分困难的。$B$B当初，我本人在外域几乎走投无路，处境十分艰难，于是我就将卡拉赞的钥匙分成三个部分藏了起来。$B$B当时，我将它们分别放进了三个魔法容器中，分别藏匿在三个我认为十分安全的地方。$B$B可是，时过境迁……随着黑暗势力逐渐笼罩了外域，这些地方也不再有安全可言。第一部分碎片在奥金顿中，那个区域当前被暗影议会占据着。将这块碎片带回来给我吧。', '卡德加要求你进入奥金顿的暗影迷宫中，回收储藏在那里的一个奥术容器中的第一块钥匙碎片。', '你做的很好，$N。我不确定你会成功。$B$B容器附魔着一个强大的法术，让那些没有价值的眼睛无法看到它。我很高兴它们没有避开你。', '你拿到碎片了吗，$C?不要浪费时间才会把这件事做好。', '', '去找沙塔斯城的卡德加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9832, '第二块和第三块', '第二部分的钥匙，被我藏在了毒蛇湖的湖底，当时那里还不叫这个名字。纳迦们占据了毒蛇湖之后，在湖中央安装了巨大的抽水装置。恐怕容器也被吸进了盘牙水库的深处。$B$B第三部分则更加难以回收，我原本将其留在了风暴要塞，当时那里在纳鲁的掌控之下。可现在凯尔萨斯占领了要塞，而我原来存放容器的地方也变成了一处监狱。$B$B把这些钥匙的碎片给我带回来吧，$N。一切都要依靠你了。', '从盘牙水库内的一个奥术容器中拿到第二块钥匙碎片，从风暴要塞内的一个奥术容器中拿到第三块钥匙碎片。任务完成之后向沙塔斯城的卡德加复命。', '你拿到了钥匙碎片。这真是太令人钦佩了，$N。你有那个价值带着钥匙去卡拉赞。$B$B还剩下一个小问题。', '你的钥匙碎片找的怎么样了，$N?', '', '去找沙塔斯城的卡德加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9833, '通讯路线', '我们跟随伊库提来到赞加沼泽，此行的目的之一就是开辟一条安全通道，帮助德莱尼人与居住在纳格兰塔拉的库雷尼人创建通信。为了让信使在塔拉和泰雷多尔之间通行无阻，我们必须确保道路的安全。$B$B在来时的路上，我们多次遭到沼牙切割者的袭击。尽管我们将它们全部击退，但是对孤单的信使而言，这些野兽必定会带来巨大的威胁。削弱它们的数量才能确保信使的安全。', '奥雷柏尔营地的普尔鲁要你杀死12个沼牙切割者。', '这是很棒的消息。道路离完全安全还有很大的距离，但信差是聪明又富于机智的。', '你在保卫道路上有何进展吗?', '', '去赞加沼泽找奥雷柏尔营地的普尔鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9834, '天然的护甲', '即使在阴暗的沼泽地，玛克图也能在一里开外看见那些穿着闪亮盔甲的德莱尼人！$B$B玛克图想要嘲笑他们，但是他又想到德莱尼人对待库雷尼人的态度是多么友善，因此玛克图想教教他们制作护甲的方法。$B$B玛克图曾经用泥爪毁坏者的黑鳞皮制作过最好的护甲。如果$N愿意去毒蛇湖深处猎杀泥爪毁坏者，把泥爪皮交给玛克图，他一定会乐意送给$N几件护甲的。', '将8张泥爪皮交给奥雷柏尔营地的玛克图。', '玛克吐认为这些是很好的皮革。它们会做出非常好的护甲。$B$B谁知道?说不定还有剩下的皮革可以让玛克吐做一些护甲给德莱尼。', '$N有玛克吐要的皮革吗?', '', '去赞加沼泽找奥雷柏尔营地的玛克图。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9835, '安葛洛什的威胁', '我带领这支破碎者小队，奉命从纳格兰的塔拉赶来奥雷柏尔营地执行任务。我们称自己为库雷尼人，是渴望与德莱尼同胞重聚的破碎者。$B$B我们来此的目的就是加强库雷尼人与泰雷多尔的德莱尼人之间的沟通。$B$B如果任由安葛洛什食人魔为所欲为，这座营地很快就会失守。他们已经砍光了菌杆沼泽中高大的蘑菇，离我们的避难所越来越近。如果你是我们的朋友，就帮我们击退敌人吧。', '杀死10个安葛洛什食人魔和5个安葛洛什萨满祭司，然后返回奥雷柏尔营地向伊库提复命。', '安格拉斯威胁已经暂时控制住了，但我确信他们不会轻易放弃。自从我结束了德莱尼身份后就忘记了许多事情，但巨魔的固执是永远的记忆。', '对抗安格拉斯的战役进行的怎么样了?', '', '去赞加沼泽找奥雷柏尔营地的伊库提。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9836, '麦迪文的触摸', '所有碎片已经组合完毕，这就是我当学徒时使用过的那把钥匙了。看上去倒是跟以前没什么两样，但是如果你想用它来打开卡拉赞的大门，这东西不过是一块废金属罢了。$B$B除非获得麦迪文的同意，否则这把钥匙就毫无价值。唔，我当然知道麦迪文已经死了。这事儿不是不可能，只是有些难办而已。$B$B在艾泽拉斯世界，有一处名叫时光之穴的地方，青铜龙守护着那块圣地。设法进入时光之穴，返回过去，说服麦迪文让这把钥匙重新获得打开卡拉赞大门的能力吧。', '进入时光之穴，说服麦迪文让复原的学徒钥匙重新获得打开卡拉赞大门的能力。', '那把钥匙，我认得。那是卡德加的钥匙……当然我还没交给他。', '你是谁，你想怎么样?', '麦迪文的触摸', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9839, '戈尔费斯大王', '食人魔首领是整个氏族的核心。一旦失去首领，安葛洛什部族就会瓦解，他们会自相残杀，争夺新一任首领的头衔。$B$B尽管食人魔曾在这片区域出没，但是他们的主要势力聚集在西北边的安葛洛什要塞。沼泽地边缘有一株倒下的蘑菇，要塞就位于那座蘑菇桥对面小岛上的洞穴中。$B$B去那里杀死戈尔费斯大王，缓解奥雷柏尔营地的危机。', '杀死戈尔费斯大王和10个安葛洛什殴斗者，完成任务后向奥雷柏尔营地的伊库提复命。', '终于!我们感谢你帮忙巩固我们在奥雷伯尔港的地位。我会把你的行为传话到纳格兰，泰拉的库雷尼那里。未来将会有许多机会让我们的人民一起合作。', '完成了吗?你解决掉血拳主宰了吗?', '', '去赞加沼泽找奥雷柏尔营地的伊库提。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9841, '清除沼光抽血者', '这吵死人的嗡嗡声简直让人没法干活！你听见了吗？$B$B我满脑子都是这声音！我知道谁在制造噪音——那些该死的沼光抽血者！噪音总是从村子的南边和西边传来。$B$B沼光抽血者体型庞大，不能象对付小虫子那样拍死、踩死或是赶走它们。消除噪音的唯一办法就是杀死它们。$N，我可不管你准备用什么方法，总之让它们安静下来！', '杀死8个沼光抽血者，然后向萨布拉金的加巴林卡复命。', '我也是这样想。我已经可以听出它的差别了。我终于能回去工作，多亏了你。如果你需要什么交易技能补给，别忘了坎巴利卡!', '那声音似乎变的越来越远了。那是我一厢情愿的想法还是你真的解决掉那个麻烦了?', '', '去找赞加沼泽的加巴林卡。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9842, '最锋利的刀刃', '沼泽地潮湿的环境使我的金属工具严重受损。这让原本简单的木工活变得困难许多，所以我放弃了使用金属刀刃。$B$B萨布拉金的南边和西边生活着一种名叫沼牙切割者的沼泽生物，它们锋利的附肢是我所使用过的最好的刀刃，同时还具有防锈和抗磨损的功能。当然，要灵活运用这种利器需要一点点技巧，不过这对我来说已经不成问题了。如果你能帮我取回一些沼牙切割者之刃的话，我会非常感激你的。', '将10柄沼牙切割者之刃交给萨布拉金的加巴林卡。', '这些应该足够我用上一阵子了!我想其它人已经开始注意了。已经有些人出价要买我的剑了。贩卖它们可以提供我比平时更好的生意。', '你收集到那些剑了吗?', '', '去找赞加沼泽的加巴林卡。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9843, '金娜的日记', '再说一次，你要找谁来着？金娜？$B$B哦哦，我以前也曾在卡拉赞见过一个名字也叫金娜的女人，她那时一直呆在会客间那边。我本应保守这个秘密的。$B$B你说你替紫罗兰之眼办事？不，我从来没听过这个组织。$B$B如果你不介意的话，我回去干活了。$B$B<库雷恩一瞬间就似乎已经完全忘记了你。>', '在卡拉赞的会客间搜寻金娜的日记，然后将它交给卡拉赞外的大法师奥图鲁斯。', '你找到日志了。我希望我们需要的资讯就在这里，$N。', '琪安娜的日志……你找到了吗?', '', '去找逆风小径的大法师奥图鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9844, '恶魔的气息', '金娜的最后几篇日记证实了我们的怀疑，卡拉赞中确实有恶魔出没。$B$B她曾在卡拉赞中发现燃烧军团的一名密探出没，位置，我看看……按描述应该是从塔顶潜入的。$B$B写到这里，日记就中断了。$B$B$c，卡拉赞是一处至关重要的所在，它是连接扭曲虚空与这个世界的传送门，是照耀着异界天空的灯塔。一旦卡拉赞落入邪恶势力之手，后果将不堪设想。我们必须阻止这些恶魔的入侵，$N，你是唯一有钥匙的人，这重大的使命就交给你了。', '大法师奥图鲁斯要求你消灭出现在卡拉赞顶部的恶魔。', '你办到了!读数恢复正常了!$B$B我们一定要把这个消息告诉赛卓克。他一定会对你的成就很惊讶的。', '我不敢问，$N。卡拉赞里的情况变的如何?', '', '去找逆风小径的大法师奥图鲁斯。', '摧毁恶魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9845, '下钩钓鱼', '长途跋涉穿越荒凉的地狱火半岛后，待在有水的地方真是舒坦，我原本还担心外域很可能没有适合垂钓的地方呢。$B$B现在，我真高兴随行带了渔具过来。大多数时候，钓鱼是一件非常愉快的事情，如果没有毒蛇湖里那些讨厌的泥爪毁坏者的话。$B$B它们不仅把鱼吓跑了，还胆敢咬掉我鱼钩上的诱饵。我不得不花更多的时间一次次地重装诱饵，根本没法钓到任何东西！', '杀死10个泥爪毁坏者，然后向萨布拉金的苏尔加亚复命。', '我等不及回去钓鱼了!现在我可以带着真正的鱼回到镇上去，坎巴利卡也不能再嘲笑我了!', '我现在可以安全的钓鱼了吗?', '', '去赞加沼泽找萨布拉金的苏尔加亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9846, '蛮沼之灵', '据说沼泽地中最强大的失落者氏族——蛮沼氏族拥有某种神奇的药膏。虽然这个流言有可能是假的，但一切可能帮我引导这个世界灵魂的东西都不容忽视。$B$B$N，从蛮沼秘法师、蛮沼猎人和蛮沼德鲁伊手中夺得保护图腾。图腾上的雕文应该记载着我想要知道的东西。', '将10根蛮沼保护图腾交给萨布拉金的先知亚尼迪。', '嗯……它们似乎分成了毒蛇之魂和翼鸟之魂。有自尊心的暗矛巨魔不会致力于崇拜翼鸟。它们的灵魂太脆弱，善变，最好留给阿曼尼的萨满。$B$B但是毒蛇的就不同了，$N，毒蛇灵魂拥有强大的力量而这就是我要研究的灵魂。', '你收集到那些图腾了吗?', '', '去赞加沼泽找萨布拉金的先知亚尼迪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9847, '灵魂之盟？', '我们必须查明蛮沼毒蛇之魂到底蕴藏着多大的力量，以及它是否愿意服从我们的意志。如果我能随意支配来自外域的灵魂的力量……难以想象！$B$B带上图腾转至博哈姆废墟，将它插在台阶底部的地面上。只有这样，我们才能通过毒蛇之魂了解到究竟是谁使用过保护图腾。', '转至博哈姆废墟，将蛮沼图腾插在台阶底部的地面上。然后返回萨布拉金，向先知亚尼迪汇报你的发现。', '<你要把使用图腾时发生的事告诉先知贾尼迪。>$B$B灵魂攻击你了吗?它一定和那些失落者有更密切的关系。要强迫它为我效命必定要耗费庞大的力气。我得在这悲惨的世界上寻找一种新的力量来源。', '你召唤出菲拉芬灵魂了吗?', '', '去赞加沼泽找萨布拉金的先知亚尼迪。', '召唤毒蛇之魂', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9848, '匕潭的秘密', '虫子、虫子、虫子！赞加沼泽到处都是虫子，营地的同伴们似乎为此深感困扰。$B$B呸，我真是受够这些虫子了！不过有件更有趣的事情吸引了我的注意。营地以西是一座失落者村落，他们自称为匕潭失落者。$B$B整个部族由训练有素的暗杀者组成。我留意到他们所配制并使用的某种强效毒药，我迫切地想要了解这种毒药，但是我需要一份配方和一小瓶样本。', '将匕潭毒药手册和一只匕潭毒药瓶交给奥雷柏尔营地的迪莫斯·丹尼斯。', '<提莫斯快速翻阅手册。>$B$B他们使用拉格维花做为毒药的基底?不，不可能。拉格维花没有毒性特质。$B$B把拉格维花放进毒药里就像盗贼使用双手锤一样。当然，你可以这么做，但那不是你使命的本质!我不懂……$B$B<提莫斯清了清他的喉咙。>$B$B我是说，谢谢你把这些东西带给我。我会在时机允许时试试这毒药。', '你让匕首沼地村说出我要的资讯来解开那个毒药的秘密了吗?', '', '去赞加沼泽找奥雷柏尔营地的迪莫斯·丹尼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9849, '打碎外壳', '<戈达乌从后背掰下一块岩石。>$B$B我把这块代表大地之怒的碎片交给你。将戈达乌的石块砸向破碎奔行者。击碎他们的外壳，看看这帮家伙的真面目。杀死侵占者的爪牙，然后返回元素王座，将侵占者的名字告诉戈达乌。$B$B破碎奔行者分布在纳格兰西南方的边缘地带。', '纳格兰元素王座的戈达乌要你杀死30个戈隆克的爪牙。', '戈隆克!戈隆克背叛了元素!', '戈达乌要你带着巨砾回来。', '', '去纳格兰找元素王座的戈达乌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9850, '狩猎裂蹄牛', '看来猎杀裂蹄牛对你来说已经不在话下，不过裂蹄公牛就不那么容易对付了，它是比裂蹄牛更危险的猎物。$B$B杀死十二头裂蹄公牛，然后再来夸耀你的狩猎技能吧。$B$B你可以在营地以西和以南方向的纳格兰中心地带找到它们的踪迹。', '杀死12头裂蹄公牛，然后向纳格兰奈辛瓦里狩猎队营地的赫米特·奈辛瓦里复命。', '令人印象深刻。非常了不起。$B$B你有潜力，孩子。现在我要给你机会尝尝真正的乐趣!', '你以为那些公裂蹄会就这样在营火前阵亡在你脚边吗?', '', '去纳格兰找奈辛瓦里狩猎队营地的赫米特·奈辛瓦里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9851, '狩猎裂蹄牛', '班塔尔是外域的裂蹄牛中最凶猛也是最难捕捉的一只。她身上的鬃毛也是最浓密的。$B$B据说她和一群裂蹄牛生活在沃舒古附近的灵魂平原上。想要证明你的狩猎技能？把她的犄角带回来！', '将班塔尔的犄角交给纳格兰奈辛瓦里狩猎队营地的赫米特·奈辛瓦里。', '你办到了!你击败了班萨尔!我从未怀疑，$N。$B$B来，我认为你比这些奖励更有价值。', '一个温暖的火堆和一个$g女人:男人;陪你闲话家常是你在家做的事。在这里我们要猎杀大型猎物或搏命演出。', '', '去纳格兰找奈辛瓦里狩猎队营地的赫米特·奈辛瓦里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9852, '终极挑战', '塔丝克是纳格兰所有雷象的王后，你在别处肯定见不到像她这样体型庞大的雷象！$B$B你最好不要小瞧塔丝克，一定要尊敬这个强大的对手！巴克洛尔、裂肠者和班塔尔的力量都\r\n不足以与她相提并论。遥远的西南方有一处高耸的断崖，可以眺望沃舒古，据说她经常在那一带的某处悬崖附近出没。将塔丝克之心带回来给我。$B$B哦，对了，你要不要留下一封遗书？要是你不幸没有回来，我可以帮忙将它交给你的家人。', '将塔丝克之心交给纳格兰奈辛瓦里狩猎队营地的赫米特·奈辛瓦里。', '$N!你为这个老矮人的心带来了喜悦。$B$B你现在证明了自己;你已跻身精英阶级!其它人害怕的逃走，或是阵亡，在野兽的脚下被践踏。你用你的头脑，你的狡猾，你的决心来证明你在打猎上的专精。$B$B带着这个，记得我们永远欢迎你来打猎!', '承认你没那个胆猎捕这大地上最强大的动物不是什么可耻的事，$N。', '', '去纳格兰找奈辛瓦里狩猎队营地的赫米特·奈辛瓦里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9853, '侵占者戈隆克', '必须召唤出戈隆克。你，召唤戈隆克，然后杀掉他。$B$B去西北方的战槌山，那里的食人魔将戈隆克当作神崇拜。收集战槌食人魔的徽记，摆放在战槌山的大地印记上。只有这样才能召唤出戈隆克。记得，7枚徽记。$B$B如果你能获胜，就将戈隆克的徽记带回来交给戈达乌。戈达乌会毁掉他的徽记。$B$B<戈达乌做出猛烈撕咬的动作，你脚下的大地震颤起来。>', '杀死侵占者戈隆克，将戈隆克的徽记交给纳格兰元素王座的戈达乌。', '<戈达乌大口咀嚼着戈隆克的大地头盔，几乎要瓦解了石头形态。>$B$B戈隆克的统治时期结束。土灵元素自由了。一切沉睡。优胜者获得奖励!', '戈达乌吃掉戈隆克力量。', '', '去纳格兰找元素王座的戈达乌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9854, '狩猎风鹏', '$c，你是否跟我一样向往猎手的生活？你知道追捕猎物时如何保持沉着冷静吗？知道怎样才算是对倒下的猎物的尊敬吗？我会教你领悟其中的秘诀。$B$B纳格兰葱翠的大草原上生活着无数野生动物。去猎杀一些风鹏，然后再来跟我谈话。$B$B营地四周都能找到它们的踪迹。', '杀死12只风鹏，然后向纳格兰奈辛瓦里狩猎队营地的“好儿子”沙度·远行者复命。', '每一天都是一个礼物。要善用它。因为明天我们要比今天更迅捷地驰骋在草原上。我们会张开双臂努力达到我们今晚所梦想的目标，虽然它可能总是会难倒我们。', '明白自己在大自然中的位置能带给你一种平静，你了解那种平静吗?你是猎人还是猎物?', '', '去纳格兰找奈辛瓦里狩猎队营地的“好儿子”沙度·远行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9855, '狩猎风鹏', '想要猎杀最强大的野兽，就必须保持进取心！在你茫然不知所措的时候，我会为你指明方向。$B$B纳格兰生活着另一种更可怕的风鹏。下一步就是猎杀那些饥饿的风鹏。你可以在营地以西和西南方向的纳格兰中心地带找到它们的踪迹。', '杀死12只饥饿的风鹏，然后向纳格兰奈辛瓦里狩猎队营地的“好儿子”沙度·远行者复命。', '你再次证明了你的技能，$C。现在你一定要去猎捕最凶猛的风翼猫头鹰。', '你学会让你的心跳冷静下来吗?和一面平静的湖泊一样冷静有耐心，等待最佳的时机扑杀你的猎物?', '', '去纳格兰找奈辛瓦里狩猎队营地的“好儿子”沙度·远行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9856, '狩猎风鹏', '$c，备战吧。勇敢地面对风鹏的女王——裂肠者！你杀了这么多女王的子民；为了表示对猎物的尊重，至少你要给她复仇的机会吧！去遥远的西边寻找裂肠者，她跟体型较大的风鹏生活在一起。$B$B如果你能战胜她，就把裂肠者的眼睛带回来。', '将裂肠者的眼睛交给纳格兰奈辛瓦里狩猎队营地的“好儿子”沙度·远行者。', '她的眼睛看起来好像她还活着一样。你觉得她还是能看透你的灵魂吗?$B$B$N，你现在可以自称为一个精英的狩猎人了。你离追踪这片土地最终的猎物，长牙又更进一步了!$B$B这是你的努力所赚取的报酬。愿它对你有所助益。', '你挑战了卡特瑞普吗?', '', '去纳格兰找奈辛瓦里狩猎队营地的“好儿子”沙度·远行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9857, '狩猎塔布羊', '我今天不想外出狩猎。你愿意替我跑一趟吗？$B$B我跟赫米特提过，今天会去猎杀一些塔布羊。塔布羊在纳格兰广为分布，雄性塔布羊更是上等的猎物。你可以在附近的树林中找到它们。$B$B你能胜任这件差事吗？', '杀死12头塔布雄羊，然后向纳格兰奈辛瓦里狩猎队营地的哈罗德·兰恩复命。', '那是个好故事……<咳嗽>……你如何猎捕那些雄鹿的故事，$C。但我想你可以做的更好。我想好了别的事要给你做。', '我想在这里躺久一点。我很快就没事了。', '', '去纳格兰找奈辛瓦里狩猎队营地的哈罗德·兰恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9858, '狩猎塔布羊', '这该死的伤简直是要了我的命。你愿意再……<咳嗽声>……替我跑一趟吗？$B$B这次你要猎杀一些食棘者。跟雄性塔布羊比起来，它们更难对付，你千万不能大意。你可以在……<咳嗽声>……营地以西和以南方向的纳格兰中心地带找到塔布羊食棘者的踪迹。$B$B去吧……<咳嗽声>……让赫米特瞧瞧你的能力。我会没事的。', '杀死12头塔布羊食棘者，然后向纳格兰奈辛瓦里狩猎队营地的哈罗德·兰恩复命。', '<咳嗽>，<咳嗽>……$N!你办到了。只剩下……<咳嗽>……一件事要……<咳嗽>……做了。', '我想你该不会……<咳嗽>……已经解决了那些……<咳嗽>……食棘者吧?', '', '去纳格兰找奈辛瓦里狩猎队营地的哈罗德·兰恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9859, '狩猎塔布羊', '<剧烈的咳嗽声。>$B$B别担心……<咳嗽声>……我。我会没事的。这点小伤……<咳嗽声>……算不了什么。$B$B唔，我想你还得……<咳嗽声>……再替我跑……<咳嗽声>……跑一趟。$B$B猎杀那头名叫巴克洛尔的塔布羊，他是塔布……<咳嗽声>……塔布羊之王。你最好……<咳嗽声>……带上你的朋友。$B$B把他的蹄子……<咳嗽声>、<咳嗽声>……带回来。$B$B去遥远的西边寻找……<咳嗽声>寻找他的踪迹。', '将巴克洛尔的蹄子交给纳格兰奈辛瓦里狩猎队营地的哈罗德·兰恩。', '哇!你办到了!这真的是巴奇洛尔之蹄!$B$B嗯，我开始感觉好多了。来，让我给你点东西庆祝你证明了你的打猎本领!', '<哈洛德虚弱地抬起头看着你，仍勉强挤出微笑。>$B$B你拿到……<咳嗽>……蹄子了吗?', '', '去纳格兰找奈辛瓦里狩猎队营地的哈罗德·兰恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9861, '呼嚎之风', '这团飘忽不定的空气元素用你难以理解的语言述说着什么。你认为这是被称为古卡利姆多语的元素语言。或许元素王座那里的人会对这件与众不同的东西有独到的见解。', '返回元素王座寻找某个会讲古卡利姆多语的人，将呼嚎之风交给他。', '这是个苦恼的请求，$r。一股外在力量正在破坏元素。', '在这里!快!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9862, '暗血腐蚀者', '是暗血破碎者！他们抓走了空气之灵并肆意地折磨它们！说起来，暗血氏族跟我同属破碎者一族，不过他们却听命于盘牙水库的沼地领主穆塞雷克。$B$B那些暗血净化者抓走了好些空气之灵，利用它们在元素界制造骚乱。而且，暗血破碎者似乎还刚刚洗劫了西南方一座名叫日泉岗哨的兽人村落，企图利用元素强大的魔法力量扰乱湖中的水之灵。去杀掉那些暗血净化者，$N！', '纳格兰元素王座的元素师莫格要你杀死5个暗血净化者。', '你看到他们控制元素?风也向他们屈服了?$B$B<莫夫沉思了一会儿。>$B$B这很麻烦，$N。我一定要和其它人商量。$B$B我们感谢你的努力，$N。或许你该回到你的村子，看看他们有没有其它关于黑暗之血和他们恶毒目标的消息。', '风灵声称黑暗之血在寻找日春的某个东西……', '', '去纳格兰找元素王座的元素师鲁艾普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9863, '邪恶的信仰', '盖亚安祖母的病情加重之后，玛格汉氏族就不断遭到外族侵袭，而卑鄙的暗血氏族在我们四面受敌之际乘虚而入！$B$B这些天来，暗血破碎者发动了不下五次攻击。他们还占领了原本属于我们的日泉岗哨。$B$B我们必须要打击暗血氏族的嚣张气焰，给他们点颜色瞧瞧！杀掉那些信仰邪教的家伙，将他们随身携带的神像抢回来，这样他们就知道厉害了。', '将10个暗血神像交给纳格兰加拉达尔的先知古库斯。', '你给闪电之子带来希望，$N。如果我们的领导者不能保护我们，或许还有其它人可以 - 就像你。', '为我们完成任务因为我们无法自己完成。', '', '去纳格兰找加拉达尔的先知古库斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9865, '我们曾是战士', '陌生人，虽然我不认识你，不过能请你帮个忙吗？虽然乞求他人的帮助令我感到很羞愧，但是整个战斗小队只有我一人侥幸活了下来。$B$B满腔的怒火让我难以自制。我……我要报仇，血债血偿！你可曾有过这样的经历？我想要抡起斧头，将敌人统统劈成两半，直到耗尽最后的气力，再也挥不动武器。$B$B正南方就是日泉岗哨。我们的敌人就盘踞在那儿……杀了他们……不留活口……', '消灭20个暗血清道夫和10个暗血掠夺者。', '<萨鲁法尔转向面对你。>$B$B我闻到的是血吗?很遗憾我无法帮上忙。你可以感到非常的骄傲。从我胸膛里激动的复仇心跳声就知道你完成的伟业。$B$B你的同胞都跟你一样英勇吗?在你的家乡，还有更多像你一样的英雄吗?', '每杀死我的一个同胞，我就要杀死他们十个人!', '', '去纳格兰找玛格汉车队的小萨鲁法尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9867, '暗血领袖', '新近爆发的战争夺走了许多伙伴的性命。$B$B数十年来，我们与纳格兰的食人魔一直处于交战状态；最近却遭遇了新的威胁。暗血破碎者氏族袭击了西南方的渔村——日泉岗哨，而村里的兽人要么被屠杀，要么被逐出了家园。$B$B虽然别的族人认为我们应该将入侵者悉数杀掉，不过我觉得“擒贼先擒王”方为上策。我不知道暗血酋长是谁，不过我想你应该辨认得出。', '将暗血酋长奥托尔的徽记交给纳格兰加拉达尔的先知玛加迪。', '所以，这是我们敌人的脸孔?我将它置于长矛上，公布在卡拉达尔外的入口附近。如果他们想再攻击我们，他们就会尝到这样做的后果……', '帮我把他们领导者的头颅带来，$N。', '', '去纳格兰找加拉达尔的先知玛加迪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9868, '卡达什图腾', '陌生人，谢谢你。要不是你路经此地，我肯定早没命了。$B$B三天前，暗血破碎者趁着夜色袭击了加拉达尔，我也不幸沦为战俘。后来，我听到，这帮野蛮的家伙居然在寻找卡达什图腾！若是被他们找到，外域很可能会再次陷入动荡！绝不能让卡达什图腾落入暗血破碎者的手中！$B$B请带我逃离日泉岗哨。陌生人，如果我不能活着返回加拉达尔，那请你务必将这里的情况转告给加尔鲁什……', '护送玛格汉俘虏逃离日泉岗哨，完成任务后返回加拉达尔，向加尔鲁什复命。', '有什么差?主母快死了。再活下去也没意义了……', '<加尔鲁什几乎没有看到你出现。他看起来非常地沮丧。>', '营救玛格汉俘虏', '去纳格兰找加拉达尔的加尔鲁什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9871, '暗血入侵者', '羊皮纸上粗略地描绘着纳格兰的地图。塔拉的位置标记着一个大大的红叉。似乎这帮野蛮人想要攻击这座小镇。立刻将暗血入侵计划交给塔拉的阿雷克隆。', '将暗血入侵计划交给纳格兰的塔拉的阿雷克隆。', '<阿尔克隆将拳头击在他的手心上。>$B$B奥拓尔……奸诈的混蛋!', '这是什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9872, '暗血入侵者', '羊皮纸上粗略地描绘着纳格兰的地图。在加拉达尔的位置画着一个红色的大叉。看来这帮野蛮的家伙计划入侵这座镇子。将暗血入侵计划交给加拉达尔的加尔鲁什。', '将暗血入侵计划交给加尔鲁什。', '<加尔鲁什揉烂地图把它丢进火里。>$B$B有什么用?他们已经攻击我们好几个礼拜。这不是新闻了。$B$B你不懂吗?我们太累了……主母吉雅快死了。', '这是什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9873, '奥托尔，我的老朋友……', '这些入侵计划书应该是由暗血酋长奥托尔所拟定的。他原本曾是一位高贵的破碎者，精通于驾驭元素的力量，但可惜现在已经成为沼地领主穆塞雷克身边一条摇尾乞怜的哈巴狗了。$B$B计划书中写道，他们已经占领了西北方一座名叫日泉岗哨的兽人村落。$B$B立刻转至日泉岗哨杀死暗血酋长奥托尔。你所做的一切都是为了我们大家的生存……', '杀死暗血酋长奥托尔，然后向纳格兰塔拉的阿雷克隆复命。', '你说有一千个死掉的兽人?是什么造成这样大胆的兽人土地入侵行动?他死掉是好的但这一切只是凤毛麟角。', '记住，$N，奥拓尔是个强大的萨满。', '', '去纳格兰找塔拉盆地的阿雷克隆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9874, '阻止污染', '$N，我刚刚得知日泉岗哨那场惨绝人寰的悲剧。邪恶的暗血氏族侵占了西北方的日泉岗哨，大肆杀戮居住在那儿的兽人。更糟糕的是，他们开始将尸体抛入日泉湖。一旦尸体腐烂，我们的主要水源就会遭到严重污染。$B$B我要交给你的这项任务相当恶心，但是势在必行。带上这把魔油火炬，返回日泉岗哨，烧掉那些腐烂的兽人遗体……', '用魔油火炬烧掉10具日泉村民的遗体，然后向纳格兰塔拉的先知欧图布复命，并归还魔油火炬。', '<欧塔布叹气。>$B$B这会让我们和兽人再维持10年和平的机会受到挫折。至少我们还能在这看看那些尸体如果腐烂会发生什么事。', '兽人不会了解我们在做什么但它一定要完成。为了兽人和破碎者好。', '', '去纳格兰找塔拉的先知欧图布。', '烧掉日泉村民的遗体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9875, '未归类的植物', '劳兰娜一定没见过这株特殊的植物。你确定你所发现的是她尚未编录的新物种。你最好把它交给劳兰娜，看看她对此了解多少。', '将未归类的植物交给赞加沼泽塞纳里奥庇护所的劳兰娜·萨维尔。', '一个新品种!你是说真的吗?$B$B<罗安娜.快速翻阅好几页笔记和图表。>$B$B做的好，$N。我们会把它列进我们的清单中。你觉得“紫叶$N环”听起来怎么样?它上面真的有一个圆圈。', '你有东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9878, '解决问题', '暗血氏族在纳格兰滋扰生事，严重影响了我们周围的环境。元素们躁动难安，由此波及到此地所有生物。更糟糕的是，日泉岗哨的大屠杀事件重新点燃了兽人们对破碎者的新仇与旧恨。$B$B虽然库雷尼跟暗血是截然不同的两个氏族，可在兽人看来，我们都是十恶不赦的破碎者。$B$B我们必须解决眼下这进退维谷的窘境。转至西北方的日泉岗哨，消灭盘踞在那儿的暗血破碎者。', '消灭10个暗血清道夫和5个暗血掠夺者，然后向纳格兰塔拉的智者普里鲁鲁克复命。', '不知道兽人是否会了解或感谢你所做的一切，但纳格兰的确因此脱离险境。谢谢你，麻烦解决者……', '黑暗之血是破碎者中一个恶毒的部族，$N。虽然他们看起来像库雷尼但他们绝对是野蛮，凶残的野兽。', '', '去纳格兰找塔拉的智者普里\r\n鲁鲁克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9882, '偷盗贼的东西……能算偷么？', '节点亲王哈拉迈德大人严令禁止我们在沃舒古中开采水晶，惟恐这样会激怒某位强大的纳鲁。这令我们的工作严重受阻。$B$B不过，我已经找到空子可钻了。$B$B你看，被这块大钻石吸引来的虚灵可不仅仅只有我们星界财团而已，还有个名叫加瓦克希的盗贼头目领着一帮虚灵手下也进入了沃舒古，并且已经开始搬运那些大块的碎片了。$B$B$r，你的任务就是替我们夺得那些水晶碎片，这可不算是我们亲自开采的。偷取这些盗贼的东西可不算偷，对吧？', '将10块沃舒古水晶碎片交给纳格兰埃瑞斯码头的杰赫。', '真是令我惊讶。这些碎片的状态都非常好，大部分来说。$B$B我会为你向我们人民说些好话的。', '你取回我要你弄到的水晶碎片了吗，$N?', '', '去纳格兰找埃瑞斯码头的杰赫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9883, '更多水晶碎片', '', '', '继续拿水晶碎片来，$N。我们不能让这些小偷拿走我们的财产。$B$B虽然说它们也还不完全是我们的。当然，。', '你有更多水晶碎片?确定你拿的都已不属于那座山了;我们可不想跟纳鲁惹上麻烦。', '', '去找纳格兰的杰赫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9889, '别杀那个胖家伙！', '数日来，我一直在观察这帮野蛮的食人魔。他们当中的那个大胖子说要等待时机，但是他究竟在等什么就不得而知了。$B$B我倒是有个法子，不过你得使用暴力。杀掉他手下的仆从，然后将这家伙揍个半死。他一定会跪地求饶，乖乖地吐露秘密的。', '泰罗卡森林的吉尔拉斯要求你杀死10名石拳入侵者，并击败无情的安克尔，让他招供。', '放我一条生路我就告诉你所有想知道的事!', '我投降!我投降!', '安克尔招供', '去泰罗卡森林找血环废墟的无情的安克尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9892, '更多黑曜石作战念珠', '', '', '我们会因此大赚一笔，$N。我会确保科瑞希知道你在这里的努力。', '你取得更多战争串珠了吗?你可以在远北找到很多巨魔，就在赞加沼泽的边界附近。', '', '去找纳格兰的杰赫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9893, '黑曜石作战念珠', '$N，不知道什么时候我们才能开采沃舒古的水晶。眼下我们只能呆在这儿干耗着。$B$B幸运的是，我发现了另一项收入来源。纳格兰的食人魔都佩戴着黑曜石制成的作战念珠，这种矿石在许多地方都价值不菲。$B$B最近瑟利德为了解决埃瑞斯码头的安全问题已经干掉了不少食人魔。他搞的那些作战念珠就当是我们额外的收入吧……抱歉，我自言自语了。总之，你什么都不用管，只需去从食人魔身上把东西拿来，然后交给我。', '将10串黑曜石作战念珠交给纳格兰埃瑞斯码头的杰赫。', '太好了。在我们等待沙塔尔完成欧夏刚里不知道什么的家务时，这能维持我们的收入。', '那些巨魔待你如何，$N?他们很难搞吧?', '', '去纳格兰找埃瑞斯码头的杰赫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9894, '保护观察者', '在赞加沼泽的旅途中，你可能遇见过一些远征队的观察者。他们通常在户外作业：记录沼泽地特有的生物，收集样本以及核对物种目录。$B$B$c，观察者的安全非常重要。因为沼泽兽的袭击，我们不得不召回派去南边蘑菇洞的观察者。监护者哈穆特认为只要杀死它们的首领克拉其大王，沼泽兽的攻击就会立即结束。', '杀死克拉其大王，然后向塞纳里奥庇护所的唤风者塔鲁·黑蹄复命。', '我和守夜人都非常感谢你，$N。他们听到可以继续在南方工作而不用担心遭到攻击一定会欢欣鼓舞的。', '你找到并解决掉卡拉奎领主了吗?', '', '去赞加沼泽找塞纳里奥庇护所的唤风者塔鲁·黑蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9895, '崩溃的平衡', '$N，你仔细观察过周围的环境吗？这片土地呈现出明显的病态，它挣扎着想要保持平衡却失败了。$B$B如果你留意到沼泽地的生态，必定能看出一些端倪。某些生物以惊人的速度生长着，体型大大超过同类物种，变得越来越具有侵略性。$B$B沼泽之鞭正是不受抑制、过度生长的生物的典型。如果你愿意的话，就去庇护所南边的沼泽地亲眼看看。$B$B一定要做好防御准备。这只怪物不懂什么是仁慈。', '找到沼泽之鞭并杀死它，然后向塞纳里奥庇护所的莱森·月火复命。', '既然你已亲眼看过失衡的症状，在你的旅途中要小心它们。', '你遇到伯克拉斯了吗?', '', '去赞加沼泽找塞纳里奥庇护所的莱森·月火。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9896, '黑钉之刺', '以卡兹格罗斯的名义发誓，这儿真是炙热难耐！我没有理由责怪先前撤离的队伍，但是大伙儿心里明白，迫使他们离开的并不是热浪。唔，这帮家伙不愿意承认罢了，他们是因为惧怕黑钉才撤离的。$B$B探险队曾驻扎在此地以西德莱尼双塔的南面，就在蛮沼村以北。那儿分布着巨大的胡蜂群，他们常常受到无情的攻击！我迫不及待地想知道，当我将黑钉之刺带回铁炉堡时，他们的脸上会有什么样的表情！', '将黑钉之刺交给泰雷多尔的勘探员柯纳尔。', '我太感激你了，$g小伙子:小姑娘;。我要好好享受一下这个东西……', '你弄到刺针了吗?记住，如果它有损坏那就没用了。', '', '去赞加沼泽找泰雷多尔的勘探员柯纳尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9897, '我得救了！', '我是很乐意与他人分享的。你从甘克雷手中救了我的命，我真是太高兴了！我从赞加沼泽收集了大量皮革，分一点给别人完全不成问题！', '将一捆皮革交给纳格兰奈辛瓦里狩猎队营地的哈罗德·兰恩。', '嗯，我看不出你究竟对拯救克莉斯坦有没有帮助。但如果她给你一捆皮革那么你就没事了。$B$B这是你的奖励。', '克莉斯坦愿意分享她的皮革真是个很好的……<咳嗽>……人，你不觉得吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9898, '求爱的礼物', '她将属于我。没错，她一定会是我的。$B$B玛加沙难道不是你所见过的最美丽的巨魔吗？我必须想办法赢得她的心。当然，现在她的眼里只有祖莱，不过我要改变这一切。我已经想好了一个简单有效的办法。$B$B我要向她证明，我是位优秀的猎手。朋友，这就是我要交代你的事情。西边的德莱尼双塔以南有一只名叫黑钉的巨蜂。将黑钉之刺带回来给我，我就可以施展我的魅力了。', '将黑钉之刺交给沼泽鼠岗哨的里维伊。', '太好了!我不会忘记你是如何帮助我赢取她的芳心。其实，你可以贵宾的身份出席我们的婚礼。', '我的运气就要改变了 - 我有预感。', '', '去赞加沼泽找沼泽鼠岗哨的里维伊。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9899, '未完的职责', '想办法让里维伊清醒过来吧！他完全忘记了自己的职责，整天就想着怎么讨我欢心。我试着不去理睬他，也劝说过他好几次，可根本无济于事。$B$B我不得不替他收拾这堆烂摊子。他原本奉命杀掉孢子之翼，但我打赌这只蝙蝠还活得好好的。如果你有时间的话，能不能去死亡泥潭西部杀死孢子之翼？我要利用这段时间，让里维伊清醒过来。', '沼泽鼠岗哨的玛加沙要你杀死孢子之翼。', '至少有人还尽了$g他的:她的;力量。谢谢你解决了这件事，$N。我必须和祖瑞伊谈谈瑞伏基。他的诡计多端和白日梦已经做太久了。', '我发誓他的想法一点都没改变。我想我要请暗影猎人丹杰把我传送回萨布拉金。', '', '去赞加沼泽找沼泽鼠岗哨的玛加沙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9900, '加瓦克希', '杰赫看待问题总是会往好的方面想，他认为我们大可利用在沃舒古活动的虚灵盗贼获取水晶碎片，可是这帮虚灵严重威胁着埃瑞斯码头的安全。$B$B他们的首领加瓦克希更是名极度危险的罪犯。而我的首要职责就是消灭这类隐患。$B$B如果你想要证明自己的实力，就去做掉加瓦克希吧。我保证会好好奖励你的。', '杀死沃舒古附近的加瓦克希，然后向纳格兰埃瑞斯码头的瑟利德复命。', '我们不用再担心卡沃希了，多亏了你。现在让我们来安排一下你的奖励。', '你回来了，$r。卡沃希死了吗?', '', '去纳格兰找埃瑞斯码头的瑟利德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9901, '遗留事务', '探险者协会派出的第一支远征队发回报告，称他们被一只名叫孢子之翼的巨型蝙蝠袭击。他们在沼泽地中并未停留太久便匆忙离开了，因此没有机会杀死它，我打算帮他们解决这个问题。$B$B远征队在报告中提到这只蝙蝠在死亡泥潭的西南方活动。我听守备官伊达尔说，死亡泥潭就在泰雷多尔的东北方。', '泰雷多尔的勘探员柯纳尔要求你干掉孢子之翼。', '做的好，$N。我想我们已让整个勘察小组相形失色了。等我回到铁炉堡，我相信我会得到我想要的任务。', '你找到斯柏温了吗?', '', '去赞加沼泽找泰雷多尔的勘探员柯纳尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9902, '沼光湖的恐怖', '在穿越纳迦聚集地的旅途中，我才了解到残忍的纳迦是如何对待那些倒霉的同胞的。在西南方的沼光湖，我亲眼目睹了一名极度邪恶的工头玩起致命的游戏。每当那只名叫恐爪的龙虾人要进食时，他便强行将奴隶们赶到沼光湖的小岛上。$B$B我没有必要继续描述接下来发生的事情了。我们势单力薄，不能直接向纳迦发动攻击；但是我们可以杀死这只宠物，阻止这种残忍的取乐方式。', '杀死恐爪，然后向奥雷柏尔营地的普尔鲁复命。', '谢谢你，$N。或许有了德莱尼的帮助，这个沼泽有一天会脱离纳迦的魔掌。我无法想象被迫服侍他们会是什么样子。$B$B玛克吐不常谈到，但他曾是一个奴隶。', '我很惭愧我不能为我被奴役的同胞多做些什么，但至少我们阻止了更多不必要的死亡。', '', '去赞加沼泽找奥雷柏尔营地的普尔鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9903, '多头蛇之王', '你杀死了很多小多头蛇，但是我怀疑穆拉格什对此毫不在意。这头狡猾凶残的巨兽令许多垂钓者吃足了苦头。$B$B看来我们要给它带来的麻烦划上句号了。穆拉格什就躲藏在东北方毒蛇湖的深处，它早已风光不在，可惜它自己还没有意识到这一点。', '杀死穆拉格什，然后向萨布拉金的苏尔加亚复命。', '我想那个老家伙一定知道他来日不多了。有这些新人来，老规矩站不住脚了。他的灵魂现在安息也好。', '你让老莫拉吉斯“退休”了吗?', '', '去赞加沼泽找萨布拉金的苏尔加亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9904, '猎杀恐爪', '我在沼泽地中钓到过各种各样的鱼，不过有件事却始终让我耿耿于怀。你看，我连电鳗和泥鳞狂鱼都钓上来过，但是上次我在沼光湖的小岛上钓鱼时，眼看一个巨型泥沼龙虾人上了钩，却被它咬断鱼线逃走了。$B$B这家伙名叫恐爪，在它死掉之前我都不会安心的。恐爪身型庞大，普通的渔夫是不可能捉到它的，因此我们只能采用古老的办法，那就是直接杀死它。', '杀死恐爪，然后向萨布拉金的苏尔加亚复命。', '终于!人家说所有出色的渔夫都有一条“抓不到的鱼”，但我还没遇过哪一条鱼是我无法解决的。', '我想恐惧之爪应该死了吧?', '', '去赞加沼泽找萨布拉金的苏尔加亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9905, '玛克图的复仇', '上次玛克图在毒蛇湖收集多头蛇鳞片时，遭到一头前所未见的巨型多头蛇的袭击。玛克图伸手去取他的长矛，但是已经来不及了。他侥幸蛇口逃生。$B$B谁知道呢？说不定下次就没这么幸运了。玛克图不希望有下次。你愿意帮玛克图报仇，杀死穆拉格什吗？', '找到穆拉格什并杀死他，然后返回奥雷柏尔营地向玛克图复命。', '<玛克吐认可地点点头。>$B$B玛克吐感谢你的帮忙。玛克吐终于可以放下心来。他不会再突如其来的被攻击了。', '要是很久以前，玛克吐可能会拿莫拉吉斯的皮来做强健的护甲。莫拉吉斯现在已经太老了。皮革太软不适合做好的护甲。', '', '去赞加沼泽找奥雷柏尔营地的玛克图。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9906, '粗暴的信号', '食人魔只会屈从于力量。一旦我们显露出内心的软弱，他们就会利用这一点彻底击溃我们。$B$B加尔鲁什大概已经放弃了抵抗，任由那些强盗侵犯我们的家园，但是我绝不会束手就擒！$N，我要你给石拳食人魔捎个信，用他们看得懂的语言：暴力。$B$B转至此地东南方的火刃废墟，让他们尝尝玛格汉氏族的厉害。$B$B$N，对了，在你离开之前不妨问问其它人，看他们是否愿意帮助你，与你同去。', '纳格兰加拉达尔的约林·死眼要你杀死8个石拳打击者和8个石拳秘术师。', '我们的任务尚未完成。还有更多人需要被教训一下!', '我派出了一支规模搜索队寻找剩下的村民。', '', '去纳格兰找加拉达尔的约林·死眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9907, '大胆的攻势', '此地的正西边就是哈兰盆地。石拳食人魔的突击部队就驻扎在盆地的北风裂谷和南风裂谷中。$B$B我要你以玛格汉氏族的名义，杀死你遇见的所有石拳食人魔。', '纳格兰加拉达尔的约林·死眼要你杀死10个石拳战士和10个石拳法师。', '如果这无法让他们就此罢休，那就没有别的办法了。你已实践了玛格汉的正义，$N。而对正义，玛格汉会大大地奖励。', '一定要提醒他们我们也是这区域里有影响力的人。', '', '去纳格兰找加拉达尔的约林·死眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9910, '扬旗示威', '如果你正要转至火刃废墟的话，我恰好有项任务要拜托你。带上这些玛格汉军旗，将它们插在火刃食人魔营地三处最显眼的地方。我建议你挑选那些引人注目的区域，比如那些营地上层熊熊燃烧的篝火堆。总之，将玛格汉军旗分别插在第一堆火刃篝火、第二堆火刃篝火和第三堆火刃篝火附近。$B$B让这些军旗可以时刻提醒那些侥幸捞到一条命的食人魔，我们玛格汉兽人不是好惹的！', '纳格兰加拉达尔的秘法师埃尔卡甘要你将玛格汉军旗分别插在第一堆火刃篝火、第二堆火刃篝火和第三堆火刃篝火附近。完成任务后将剩馀的玛格汉军旗还给他。', '或许你想要另一个任务?一个更棘手的工作?', '因恐惧而尊敬你的敌人!这方法非常好。', '', '去纳格兰找加拉达尔的秘法师埃尔卡甘。', '放置第一面军旗', '放置第二面军旗', '放置第三面军旗', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9911, '沼泽中的伯爵', '这块带血的下颚骨是虚空鳐的骨头，这只体型庞大的虚空鳐一定是赞加沼泽中最大的生物。从下颚骨的构造来看，“伯爵”放弃了食用腐肉的传统，改吃新鲜的肉类。$B$B想必塞纳里奥远征队会对这件样本感兴趣的。去泥泞山西边的营地找观察者莉萨奥谈谈吧。', '将“伯爵”昂古拉的下颚骨交给赞加沼泽中塞纳里奥哨站的观察者莉萨奥。', '你确定那是真的吗?我是说，我知道泥沼有大型野生生物，但是真的大型生物，而且是超大型的昆虫。$B$B想想看，孢子人的确提过一个关于可怕虫体的故事，在泥沼领主入侵之前这个大虫令他们恐惧不已\r\n。$B$B如果故事是真的呢?喔，天啊。我最好妥善保管它。远征队会想知道这件事的。', '<看守者惊讶的眨了几次眼。>$B$B你从哪里弄到这个……东西?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9914, '象牙生意', '象牙，那可是供不应求的紧俏货。许多顾客都不顾路途遥远赶来排队抢购。$B$B我可以考虑让你入伙，分你一笔利润。$B$B纳格兰野生雷象的象牙成色极佳，属于最受欢迎的品种。不过，好斗的雷象例外，它们的象牙破碎太多，品质过于低劣。$B$B别担心，这不属于偷猎；我与兽人和德莱尼都达成了协议。$B$B怎么样，你入伙吗？', '将3对象牙交给纳格兰埃瑞斯码头的沙德雷克。', '我从未对你有过一丝一毫的怀疑，$N。它们大部分看起来是很好的样本，只是有一点脏和刮痕。但我还是认为它们值得我们先前同意的价值。$B$B我希望我们未来可以持续再合作。', '我要我的象牙，不要有借口。当然，如果你要那样，我们可以重新协商你的利润。我想你不会满意那个结果。', '', '去纳格兰找埃瑞斯码头的沙德雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9915, '更多象牙', '', '', '太好了，更多完美的长牙样本，虽然有些看起来有点脏。$B$B联合团真的深深地感激你，$N。', '我还需要更多对野生伊莱克的象长牙。不幸的是，我的经费短缺无法支付你的利润。不过，如果你持续提供我需要的东西，你就会得到联合团的欢心。', '', '去找纳格兰的沙德雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9916, '血环补给箱', '石拳食人魔洗劫了我们的村落，将偷来的补给箱运去了西边哈兰盆地的北风裂谷和南风裂谷。$B$B如果你要去那边的话，就替我留意一下这些血环补给箱吧。如果我们能拿回这些补给箱，或许能帮加拉达尔减轻一点负担。', '纳格兰加拉达尔的秘法师埃尔卡甘要你找回10个血环补给箱。', '我们大部分的财产都在攻击中被偷或被毁了。我不能给你什么，但这里有一些可能对你有用的东西……', '或许有一天孩子们不用再承受饥饿的痛苦。', '', '去纳格兰找加拉达尔的秘法师埃尔卡甘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9917, '是我眼花了？', '是我眼花了，还是远处真的有一队食人魔在狩猎？他们远离老巢来这儿做什么？陌生人，我一点都不喜欢食人魔！麻烦真多，先是暗血破碎者，现在又是食人魔。我们却没有足够的人手来解决这些滋扰生事的家伙。$B$B你能调查一下食人魔在东边的活动情况吗？此地以东大约两百码的地方就是他们的营地。那些石拳猎手就驻守在营地周围，很容易辨识。干掉他们，搞清楚他们的计划！', '找回石拳计划书，然后向纳格兰塔拉的女猎手彬图克复命。', '<班吐克读着计画书。>$B$B以圣光之名!他们的字迹糟透了。就我所能收集到的资讯，他们不是在计画着“吃掉蓝皮肤的家伙并夺走他们的村子”就是在烤蓝莓派。这两种都有可能。我们一定要查个水落石出!', '你有发现任何消息吗?', '', '去纳格兰找塔拉的女猎手彬图克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9918, '这是我的地盘！', '作战计划书出自某个食人魔中尉之手。他应该是叫达普，或者是拉普吧。$B$B<彬图克将羊皮纸放在一旁，仰起头来想了想。>$B$B也有可能是比利。$B$B我想你得再跑一趟，跟这位比利或者拉普或者达普……管他叫什么！跟这家伙谈谈。小心翼翼地靠近他，若是谈话行不通，那就拳脚伺候。', '与拉普交谈，获取足够的情报后向纳格兰塔拉的女猎手彬图克复命。', '喔天啊!这只是规模侦察和猎捕集会吗?你一定要告诉姆摩尔你的发现。', '他可能在山脊上睡觉。', '', '去纳格兰找塔拉的女猎手彬图克。', '审问拉普', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9919, '孢子村', '你真是个好心的$r，$N。完全不像我见过的其它人。$B$B你应该去见见我的同胞，他们一定会感激你的。把这些孢子囊拿去交给我的首领姆希菲。你可以在北边的孢子村找到他。', '去赞加沼泽孢殖林北边的孢子村，将抢救出来的孢子囊交给姆希菲。', '你帮忙保护了下一代的孢子人，$r。我们只能以欢迎你来作客做为答谢。留下来一会儿，见见其它的孢子人。他们会有很多问题问你，我希望你不介意。', '你有东西要给我吗，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9921, '火刃废墟', '这些食人魔狩猎队分明是入侵者的先遣部队。我们必须在这帮家伙纠集大军夷平城镇之前歼灭他们。$B$B你的双手将不可避免地沾满鲜血，$r。$B$B食人魔的主营地设在塔拉正东方，泰罗卡森林边界处的火刃废墟处。要让石拳氏族知道，塔拉绝不会屈服！', '杀死8个石拳打击者和8个石拳秘术师，然后向纳格兰塔拉的击碎者姆摩尔复命。', '太好了。你刚好找到那个笨蛋信上提的传授者生物吗?$B$B不管怎样，我们一定要继续努力。我收到报告指出有更多的巨魔活动需要立刻解决!', '我们最近才刚把泰拉抢回来。我们不会再失去它!', '', '去纳格兰找塔拉的击碎者姆摩尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9922, '纳格兰的峡谷', '$N，干得漂亮。准备好接受新任务了吗？$B$B报告称石拳食人魔的另一支分遣队躲藏在纳格兰西北部哈兰盆地中的两个大裂谷里。$B$B去对付那些剩下的石拳食人魔吧。', '杀死10个石拳战士和10个石拳法师，然后向纳格兰塔拉的击碎者姆摩尔复命。', '做的好!我当前在研究石拳中尉提到的战槌部族。现在你已完成的任务必须被检验。', '小心盆地里的元素，$N。', '', '去纳格兰找塔拉的击碎者姆摩尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9923, '救命啊！', '救命啊！他们会吃了我的！真的！$B$B钥匙，我知道钥匙在那边的某个食人魔身上。$B$B要是你能救我出去，我的父亲一定会用丰厚的奖励答谢你！他是塔拉的老大，对，就是阿雷克隆。', '找到石拳钥匙，解救考尔奇，然后向塔拉的阿雷克隆复命。', '我真的很抱歉，$r。他总是搞一堆麻烦。我真想用皮带把他拴住……', '那个孩子……$B$B<阿尔克隆不开心的摇摇头。>$B$B他会把我给气死。', '', '去纳格兰找塔拉的阿雷克隆。', '营救考尔奇', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9924, '考尔奇又走丢了！', '<阿雷克隆叹了口气。>$B$B真是难为情啊。你还记得我的儿子考尔奇吗？对，就是你不久前从火刃废墟救出来的那个孩子。哎，他的好奇心比较过剩，这次他说他要帮姆摩尔大叔调查石拳部族，结果直奔北边的食人魔老巢哈兰盆地去了。$B$B你能转至哈兰盆地搜寻他的下落吗？我会永远铭记你的恩情。', '塔拉的阿雷克隆要你去搭救考尔奇。', '非常感谢你，$N。他妈妈今后会看好他。', '你找到他了吗?', '', '去纳格兰找塔拉的阿雷克隆。', '再次营救考尔奇', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9925, '安全问题', '杰赫不顾我们的安危，将星界财团的营地设立在靠近沃舒古的地方。他为何这么做？就因为这家伙认为在码头做买卖比在南边的山脉能多获得十个百分点的收入。$B$B至于那些距我们只有十步之遥的空灵爪牙，那就是我这个安全官员的事儿了，完全与杰赫无关。$B$B替我杀掉一些空灵爪牙，我就付你星界财团本地安全预算的十个百分点。别激动，这笔预算的金额没你想象的那么多。', '纳格兰埃瑞斯码头的瑟利德要求你杀死沃舒古附近的8个空灵爪牙。', '你让我的脸上露出一丝笑容，$N。或者应该说，假如我有脸的话。$B$B继续努力，我们就会成为最好的朋友。', '你解决掉那些虚无再生者了吗，$N?', '', '去纳格兰找埃瑞斯码头的瑟利德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9927, '无情的计谋', '<兰特瑞索递给你一捆旗帜。>$B$B这些是我最近收集到的一批战槌食人魔军旗。$B$B我要你转至正南方的基尔索罗要塞，尽你所能地杀死那里的基尔索罗成员。每杀死一名基尔索罗士兵，就在尸体上插一面战槌食人魔军旗。完成这项任务以及计划所需的另一项任务之后，回来向我复命。', '转至基尔索罗堡垒，将10面战槌食人魔军旗插在基尔索罗成员的尸体上，然后返回纳格兰火刃废墟向兰特瑞索·火刃复命。$B$B将没有用完的战槌食人魔军旗还给兰特瑞索。', '你能想象他们对发生的事有多困惑吗，$r?这将会非常荣耀。', '<传授者困惑的张开眼睛。>$B$B完成了吗?', '', '去纳格兰找火刃废墟的兰特瑞索·火刃。', '放置战槌食人魔军旗', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9928, '欺诈所需的军备', '要实现我的计划，你就得从基尔索罗堡垒偷些军备过来。$B$B在堡垒中搜寻装有基尔索罗军备的箱子，然后把这些箱子统统带回来给我就可以了。$B$B基尔索罗堡垒就在火刃废墟正南偏西一点的位置。', '纳格兰火刃废墟的兰特瑞索·火刃要你收集10份基尔索罗军备。', '太好了!我们的下一个目标就是狞笑骷髅氏族废墟。', '我们会点燃两个氏族间至今都未见的仇恨!', '', '去纳格兰找火刃废墟的兰特瑞索·火刃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9931, '以牙还牙', '我要你在那些战槌食人魔愚蠢而肥胖的脑袋里播下仇恨的种子。去吧，嘲颅废墟就坐落在此地西北方的山脚下。$B$B<兰特瑞索指着你带回来的基尔索罗军备箱。>$B$B你认得这些旗子吗？这就是基尔索罗军旗。我要你杀入嘲颅废墟，将这些基尔索罗军旗插在战槌食人魔的尸体上。记住，战槌食人魔的老巢在西北方，别找错了地方。', '纳格兰火刃废墟的兰特瑞索·火刃要你杀入嘲颅废墟，将10面基尔索罗军旗插在战槌食人魔的尸体上。$B$B将没有用完的基尔索罗军旗还给兰特瑞索。', '计画非常完美，$N。我准备好看你努力的成果了。', '你能预料到下次会发生什么事吗?', '', '去纳格兰找火刃废墟的兰特瑞索·火刃。', '放置基尔索罗军旗', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9932, '尸证', '你在基尔索罗堡垒的这一场杀戮为我们创造了非常有利的机会。这些基尔索罗士兵的尸体完全可以用来伪装一个混战后的现场。$B$B现在，你立刻转至嘲颅废墟的嘲颅营地。营地中应该有一堆燃烧的战槌篝火堆，当你清理掉碍事的战槌食人魔以后，就点燃这张潮湿的毛毯。我手下的石拳食人魔看到烟雾信号后就会悄悄潜入，将基尔索罗士兵的尸体丢弃在营地中。$B$B这将会是战争的导火索！', '纳格兰火刃废墟的兰特瑞索·火刃要你转至嘲颅营地，在燃烧的战槌篝火堆处点燃潮湿的毛毯，利用烟雾向食人魔传递信号。', '我必须承认，我已经几十年没有感到这么有活力过了。你做的很好，$N。', '你现在知道为什么你永远打赢不了我了吗?', '', '去纳格兰找火刃废墟的兰特瑞索·火刃。', '放置基尔索罗尸体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9933, '回到塔拉', '<兰特瑞索指着一个没有标志的箱子。>$B$B拿着。这是我送给你的人民的礼物。是你让我的氏族免遭灭顶之灾。$B$B回去告诉你的首领，火刃废墟的兰特瑞索和整个石拳食人魔氏族愿意与你们和平相处。$B$B<兰特瑞索鞠了一躬。>', '将火刃的议和礼物交给纳格兰的塔拉的阿雷克隆。', '拜托，$N，拿走和平礼物里你想要的东西。毕竟，没有你的努力，这一切都不可能发生。', '你说和平?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9934, '回到加拉达尔', '<兰特瑞索指着一个没有标志的箱子。>$B$B拿着。这是我送给你的人民的礼物。是你让我的氏族免遭灭顶之灾。$B$B回去告诉你的首领，火刃废墟的兰特瑞索和整个石拳食人魔氏族愿意与你们和平相处。$B$B<兰特瑞索鞠了一躬。>', '将火刃的议和礼物交给加拉达尔的加尔鲁什。', '<加尔鲁什把木箱踢到一边。>$B$B你在浪费你的时间，$r。拿走木箱里任何你想要的东西。我和卡拉达尔都不需要这些没用的饰品。', '<加尔鲁什看来对礼物不为所动。>', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9935, '通缉：巫婆吉塞尔达', '死亡通缉令：$B$B基尔索罗的巫婆吉塞尔达和她的仆从们犯下了诸多谋杀、绑架、行窃、举行活祭仪式、与燃烧军团来往密切等重大罪行。$B$B他们聚集在纳格兰东南部的基尔索罗堡垒，就在纳格兰与泰罗卡森林的交界处附近。$B$B谁能让吉塞尔达得到正义的制裁，就能从加拉达尔的监护者布罗克处领到一笔丰厚的赏金。', '杀死巫婆吉塞尔达以及任意10名基尔索罗成员，完成任务后向加拉达尔的监护者布罗克复命。', '那个老巫婆被杀了!这消息真是太棒了，$N。这是你的奖励。', '你是来领取奖励的吗?', '', '去纳格兰找加拉达尔的监护者布罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9936, '通缉：巫婆吉塞尔达', '死亡通缉令：$B$B基尔索罗的巫婆吉塞尔达和她的仆从们犯下了诸多谋杀、绑架、行窃、举行活祭仪式、与燃烧军团来往密切等重大罪行。$B$B他们聚集在纳格兰东南部的基尔索罗堡垒，就在纳格兰与泰罗卡森林的交界处附近。$B$B谁能让吉塞尔达得到正义的制裁，就能从塔拉的监护者莫布吉尔处领到一笔丰厚的赏金。', '杀死巫婆吉塞尔达以及任意10名基尔索罗成员，完成任务后返回塔拉向监护者莫布吉尔复命。', '那个老巫婆被杀了!这消息真是太棒了，$N。这是你的奖励。', '你是来领取奖励的吗?', '', '去纳格兰找塔拉的监护者莫布吉尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9937, '通缉：饥饿者杜恩', '$N，你已经解决了纳格兰的两大威胁，是否能再奔赴灵魂平原，为我们清理另一个祸害呢？$B$B饥饿者杜恩长期以来在沃舒古一带作威作福；谁敢挡他的道就会招来杀身之祸。迄今为止，没人能除掉这个凶残的戈隆。召集你的盟友，转至西南方沃舒古附近的灵魂平原寻找杜恩的下落。杀掉他就可以到我这里领取一笔丰厚的赏金，我保证数目不会让你失望的。', '杀死饥饿者杜恩，完成任务后向监护者布罗克复命。', '唐恩的残忍掌控解除了!因为你，英雄，纳格兰有了更明亮的明天。做的好!', '为了玛格汉!', '', '去纳格兰找加拉达尔的监护者布罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9938, '通缉：饥饿者杜恩', '$N，你已经解决了纳格兰的两大威胁，是否能再奔赴灵魂平原，为我们清理另一个祸害呢？$B$B饥饿者杜恩长期以来在沃舒古一带作威作福；谁敢挡他的道就会招来杀身之祸。迄今为止，没人能除掉这个凶残的戈隆。召集你的盟友，转至西边沃舒古附近的灵魂平原寻找杜恩的下落。杀掉他就可以到我这里领取一笔丰厚的赏金，我保证数目不会让你失望的。', '杀死饥饿者杜恩，完成任务后向塔拉的监护者莫布吉尔复命。', '唐恩的残忍掌控解除了!因为你，英雄，纳格兰有了更明亮的明天。做的好!', '不要浪费时间!一定要阻止唐恩!', '', '去纳格兰找塔拉的监护者莫布吉尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9939, '通缉：顾问佐尔布', '死亡通缉令：$B$B顾问佐尔布曾策划多起针对加拉达尔的袭击事件，并伙同其手下的劫掠者和萨满祭司杀害了无数的兽人。毫无疑问，他是个心狠手辣的危险份子。$B$B佐尔布盘踞在纳格兰北部的嘲颅废墟。$B$B谁能杀死顾问佐尔布，就能从加拉达尔的监护者布罗克处领到一笔丰厚的赏金。', '杀死顾问佐尔布、5个战槌萨满祭司和5个战槌劫掠者，完成任务后向监护者布罗克复命。', '这是卡拉达尔人民伟大的胜利!做的好，$N!', '你是来领取奖励的吗?', '', '去纳格兰找加拉达尔的监护者布罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9940, '通缉：顾问佐尔布', '死亡通缉令：$B$B顾问佐尔布曾策划多起针对塔拉的袭击事件，并伙同其手下的劫掠者和萨满祭司杀害了无数的破碎者。毫无疑问，他是个心狠手辣的危险份子。$B$B佐尔布盘踞在纳格兰北部的嘲颅废墟。$B$B谁能杀死顾问佐尔布，就能从塔拉的监护者莫布吉尔处领到一笔丰厚的赏金。', '杀死顾问佐尔布、5个战槌萨满祭司和5个战槌劫掠者，完成任务后向塔拉的监护者莫布吉尔复命。', '这是泰拉人民伟大的胜利!做的好，$N!', '你是来领取奖励的吗?', '', '去纳格兰找塔拉的监护者莫布吉尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9945, '战槌之战', '在转至先祖之地的途中，我们遭到了战槌食人魔的伏击。他们从四面八方涌来，很快就杀死了车队的卫兵和其它兽人，躺在车上的长者遗体也惨遭亵渎。$B$B难道这样的羞辱就能显示战槌氏族的强大？就连石拳食人魔都不会犯下如此低劣的恶行。$B$B$N，即使是身为玛格汉氏族的灵魂师，我也有很多力所不能及的事，所以我需要你的帮助。请你立刻转至西北方的战槌山寻找那帮强盗，杀光他们！', '纳格兰玛格汉车队的长者尤尔雷要求你杀死8个战槌蛮兵和8个战槌术士。', '这是个好的开始，但我们一定要解决掉他们的领导者，因为你的行为会有持续性的作用。', '这只是冗长过程中的一小步而已。就像狗一样，一定要让巨魔们看到对与错的不同。告诉他们没有任何帮助。', '', '去纳格兰找玛格汉车队的长者安格雷兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9946, '掠夺者考瓦尔', '$r，你见过食人魔之王吗？很少有人能从他的魔爪下逃生。我们要对付的正是这样一位残暴的君主。$B$B那些野蛮的战槌食人魔全都听命于考瓦尔。据说他甚至撵走了原本统治着那些食人魔的戈隆，大摇大摆地登上王座，并解散了为戈隆服务的食人魔氏族，将他们重新揉成了一个新的氏族，是的，战槌食人魔就此诞生。$B$B去战槌山洞窟的深处杀掉考瓦尔，将他的徽记带回来给我。', '纳格兰玛格汉车队的长者尤尔雷要求你杀死掠夺者考瓦尔，并将考瓦尔的徽记带回来复命。', '这颗头颅会悬挂在卡拉达尔的大门让所有人看见。巨魔会在打断玛格汉利神圣的仪式前三思。', '他那里绝对是戒备森严。', '', '去纳格兰找玛格汉车队的长者安格雷兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9948, '寻找幸存者', '我只知道食人魔喜食新鲜的肉类。也就是说，他们很可能将掳去的玛格汉战俘暂时囚禁起来，以保持食物的新鲜。想想就令人作呕，但是我们可以利用这一点。$B$B转至战槌山寻找玛格汉俘虏。牢笼的钥匙通常由各个牢笼附近的食人魔保管。$B$B杀掉看守牢笼的食人魔，夺得钥匙，搭救玛格汉俘虏。', '纳格兰玛格汉车队的长者安格雷兹要求你去释放5个玛格汉俘虏。', '你完成了别人认为不可能的任务，还把我失踪的兄弟姐妹都带回来了。你是玛格汉的英雄，$N。所有人都会知道你的名字和你为我们所做的事。', '<昂古力斯叹气。>$B$B我知道这样要求太多，$N;但让他们活着回来……', '', '去纳格兰找玛格汉车队的长者安格雷兹。', '营救玛格汉俘虏', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9950, '鸟眼视线', '没有未来的资讯，我们现在处于一个艰难的状况。我不会放弃寻找并拯救杜葛尔。他被绑架不是意外，$N。\r\n\r\n阿拉卡在动鬼脑筋，但他们究竟在计划什么呢?\r\n\r\n库尔卡拓克术士知道他们一些特殊的魔法。如果有正确的工具，他可以凑出一些新资讯给我们。他需要白骨荒野北边各个阿拉卡城镇的“眼睛”水晶 - 就在迷雾斯奇司，迷雾瑞斯克，和迷雾辛诺那里。', '将迷雾斯奇司之眼，迷雾辛诺之眼，和迷雾瑞斯克之眼交给裂石堡的库尔卡拓克。', '看来你有了我们需要的一切东西。我准备好马上就要开始了。$B$B现在，我不能保证我会提供有用的讯息，但我会试着占卜出所有讯息来了解阿拉卡把杜葛尔带到哪里。', '瑞克格告诉我了他的计画。如果你把材料带来了，我们就可以开始了。', '', '去找泰罗卡森林的库加托克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9951, '它在盯着你！', '快，藏起来！纳弗塔拉那双眼睛正死死地盯着你……它也盯着我们！$B$B我可不敢冒险去塔顶跟它交谈，但你就不同了……你似乎知道该跟它说些什么。千万小心，它不喜欢玩笑话，更容忍不了愚蠢的言行。$B$B如果可以的话，说服它下来品茶吧。不过，你要尽一切办法让它别那么盯着我！', '杀死纳弗塔拉，然后返回泰罗卡森林的塞纳里奥树林向监护者忒洛斯复命。', '这是最好的方式，真的。如果它不能有礼地接受邀请，那么它就不会有事。$B$B<守望者崔洛斯看起来困惑了一下。>$B$B你是谁，你在这里干嘛?你要趁来的及的时候快点离开这里!', '我们根本不该邀他们来晚餐。这绝对是肯定的!$B$B不然，我们至少该坚持多上几道菜再吃他们带来的甜点。', '', '去泰罗卡森林找塞纳里奥树林的监护者忒洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9955, '掠夺者考瓦尔', '$N，那些食人魔称他为掠夺者考瓦尔。他赶走了统治战槌食人魔的戈隆，自己做了氏族之王。你最好相信我的话，他是个可怕的对手！$B$B我听厨师说考瓦尔居住在那边的大洞穴中……无论如何，取来钥匙，把我从这鬼地方救出去！如果我们能逃得此劫，我父亲必定会好好赏赐你的！救出我之后，就去找他吧。', '夺得考瓦尔的钥匙，将考尔奇从牢笼中释放出来，完成任务后返回塔拉向阿雷克隆复命。', '谢谢你，$N。柯尔奇被送去刀锋山和夜精灵一起住了。希望他们能让他远离麻烦。$B$B至于奖励……', '柯尔奇在哪?', '', '去纳格兰找塔拉的阿雷克隆。', '营救考尔奇', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9956, '不幸的商队', '我是商队的一名成员，我们当时奉命将一批货物运往赞加沼泽的奥雷柏尔营地。然而，就在车队行进到沼泽边界附近时，一队战槌食人魔突然拦住了我们的去路。他们残忍地杀害了商队的其它成员，将我和所有的货物一并劫回了营地。$B$B谢天谢地，他们忘了锁住关押我的牢笼，于是我趁他们睡着时逃了出来。$B$B虽然伙伴们都不幸罹难，可是那些被偷走的货物还是能用的，请你一定要帮我们回收。战槌山就在纳格兰西北部。', '收集10个塔拉补给箱，把它们交给塔拉的女猎手琪玛。', '不可思议!你怎么一个人把这些东西搬回来的?', '我觉得自己好蠢。阿尔克隆的儿子，柯尔奇问我发生了什么事然后我就告诉他。现在他又再次失踪了!', '', '去纳格兰找塔拉的女猎手琪玛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9962, '鲜血竞技场：断蹄', '那么你已经做好迎接首场较量的准备了？等你准备就绪，我就宣布比赛开始。你只需进入鲜血竞技场，等待对手登场。$B$B你的对手名叫断蹄，是一头凶残的裂蹄牛。$B$B祝你好运！希望你带了朋友一起来。$B$B记住，你和你的对手中有任何一方倒地身亡，战斗即宣告结束。', '击败断蹄，获胜之后找巨魔仆从伍迪领取奖励。', '嗯，不错。真的很不错……你有潜力，孩子。这里有一些让你填满荷包的金子……', '当你或你的对手阵亡倒地时打斗就结束了。', '击败断蹄', '去找纳格兰的巨魔仆从伍迪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9967, '鲜血竞技场：蓝色兄弟', '接下来，你要同时挑战两名对手——准确地说是孪生兄弟。他们自称为“蓝色兄弟”。$B$B$N，现在选择退出还来得及，我能理解。$B$B如果你想要试试的话，就进入鲜血竞技场，等待暗血双胞胎登场吧。$B$B击杀对手便可获胜！', '击败自称为蓝色兄弟的暗血双胞胎，获胜之后找巨魔仆从伍迪领取奖励。', '我承认我以为你没有祷告，$N!真是太精采了!要不要再来一场赛?我有超棒的对手在排着队。', '当你或你的对手阵亡倒地时打斗就结束了。', '击败蓝色兄弟', '去找纳格兰的巨魔仆从伍迪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9968, '奇怪的能量', '塞纳里奥树林中的巨蛾不知何故发生了巨变。 $B$B这儿曾栖息着许多种生物，现在却只剩巨蛾了。它们本是性情温顺的小昆虫，如今却变得极具攻击性。$B$B我要将邪恶巨蛾与普通的巨蛾进行比较。你能替我收集这两类蛾子的标本吗？那些未受影响的蛾子分布在南边和北边。$B$B我想这必定与德鲁伊被杀一事有关。', '收集4份巨蛾样本和4份邪恶巨蛾样本，然后向泰罗卡森林中塞纳里奥树林外的缚地者塔弗格伦复命。', '真奇怪。凶恶的泰洛飞蛾样本充满了一种能量，我认为是一股纯粹的法力能量。$B$B看起来不管是什么东西引起生物大量的死亡，事后还残留着一股强大的能量磁场。但是由于某种原因，那些飞蛾竟然存活了下来;而且陷入了被激怒的状态。$B$B很显然的这股奇怪的能量是某样东西攻击灌木林所留下来的副作用。', '你弄到我要的样本了吗?', '', '去泰罗卡森林找塞纳里奥树林的缚地者塔弗格伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9970, '鲜血竞技场：裂石之王洛卡达尔', '$N，这将是一场苦战。你有没有叫上可靠的朋友来帮忙？食人魔从刀锋山找来了一位名叫洛卡达尔的巨人！相信我，你必须跟你的朋友们一起战斗。这家伙看起来就很猛！他跟岩石一样坚韧，事实上他就是个极能打的石巨人！$B$B如果你想要跟他较量一番，就进入鲜血竞技场，等待他登场吧。', '击败裂石之王洛卡达尔，获胜之后找巨魔仆从伍迪领取奖励。', '你让巨魔流了不少汗，小鬼!这次有些特别不一样的东西 - 不要一次把它们全用完。$B$B你准备好下一场挑战了吗?', '当你或你的对手阵亡倒地时打斗就结束了。', '击败裂石之王洛卡达尔', '去找纳格兰的巨魔仆从伍迪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9971, '树林中的线索', '不知道是谁杀光了这儿的德鲁伊。我一直在此地以南的白骨荒野进行调查研究，因此逃得一劫。$B$B请你一定要伸出援手，帮我揭开这场惨剧的真相。如果可以的话，进入塞纳里奥树林寻找线索吧。我记得曾在树林中看见一具破碎者的尸体，他旁边还有个奇怪的物体。这条线索可能对我们有所帮助。$B$B别担心忒洛斯，他虽然受到惊吓失了心智，可我相信他不会伤害你。', '调查破碎者的尸体旁的奇怪物体，看看究竟是什么在滋扰塞纳里奥树林，然后向塞纳里奥树林外的缚地者塔弗格伦复命。', '所以，我是对的。那是一具破碎者的尸体吗?你确定他旁边地上有个奇怪的物体?$B$B真是不合理。那个破碎者去那里做什么?他拥有的是什么东西?$B$B就是那个东西导致他遇害的吗?', '你发现了什么吗?', '', '去泰罗卡森林找塞纳里奥树林的缚地者塔弗格伦。', '检查奇怪的物体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9972, '鲜血竞技场：瑟克拉加斯', '孩子，你差点没把那帮食人魔活活气死！这次他们耍了个小花招，让虚空领主代为出场。看来他们还不想派出冠军选手跟你一较高下。那个蹩脚的穆戈尔在那边对你嚷嚷呢，听见了吗？这场比赛赌注很高呢！$B$B进入鲜血竞技场，迅速解决你的对手吧！', '击败瑟克拉加斯，获胜之后找巨魔仆从伍迪领取奖励。', '小鬼!小鬼就是这样!下一场赛很重要!是勇士赛!$B$B好，沉着以对。我们不想让巨魔知道我们任何的动静。', '当你或你的对手阵亡倒地时打斗就结束了。', '击败瑟克拉加斯', '去找纳格兰的巨魔仆从伍迪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9973, '鲜血竞技场：战槌勇士', '他们不得不派出这位来自刀锋山格斗场的冠军选手。这名选手经过严酷的训练，每次都有三名山岭巨人同时跟他较量。$B$B如果你赢了这场比赛，你就是新的冠军了。孩子，你觉得获胜的希望有多大？愿意试试吗？只要你接受挑战，我就把所有的赌注都下在你身上。$B$B进入鲜血竞技场，战胜对手！', '击败战槌勇士，获胜之后找巨魔仆从伍迪领取奖励。', '喔天啊。穆戈尔以战槌英雄的身分加入战斗。你必须打败他!$B$B从来没人说战槌有好的运动家……呃……巨魔。', '当你或你的对手阵亡倒地时打斗就结束了。', '击败战槌勇士', '去找纳格兰的巨魔仆从伍迪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9977, '鲜血竞技场：终极挑战', '<古尔戈索克贪婪地数着大堆的金币。>$B$B孩子，你真是个招财宝。如果你能击败穆戈尔，我发誓我会好好酬谢你的。你在鲜血竞技场洒下的热血一定会得到回报！$B$B进入鲜血竞技场，让那些食人魔知道你才是真正的强者！', '击败战槌英雄穆戈尔，获胜之后找巨魔仆从伍迪领取奖励。', '我说过会让你值回票价的，小鬼。拿走你的奖励吧!', '当你或你的对手阵亡倒地时打斗就结束了。', '击败战槌英雄穆戈尔', '去找纳格兰的巨魔仆从伍迪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9986, '教训鸦人', '我们必须让那些该死的鸦人知道，任何攻击我们的人都要付出惨重的代价。否则，我们在泰罗卡森林内的所有商人、信使和士兵将会面临他们的威胁。$B$B我的斥候已经确认了鸦人在这个地区各个主要定居点的首领。去吧，找到里斯克鸦巢的阿什卡兹、西诺鸦巢的埃伊特和基斯鸦巢的乌达克，将他们全部定点清除。', '杀死里斯克鸦巢的阿什卡兹，西诺鸦巢的埃伊特和基斯鸦巢的乌达克，然后返回奥蕾莉亚要塞向山德复命。', '做的好，$N。我们不用再担心阿拉卡什么时候又会引诱我们的商人和信差了。', '再见到你真好，$N。你完成了我交代的事吗?', '', '去泰罗卡森林找奥蕾莉亚要塞的山德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9987, '教训鸦人', '我们必须让那些该死的鸦人知道，任何攻击我们的人都要付出惨重的代价。否则，我们在泰罗卡森林内的所有商人、信使和士兵将会面临他们的威胁。$B$B我的斥候已经确认了鸦人在这个地区各个主要定居点的首领。去吧，找到里斯克鸦巢的阿什卡兹、西诺鸦巢的埃伊特和基斯鸦巢的乌达克，将他们全部定点清除。', '杀死里斯克鸦巢的阿什卡兹，西诺鸦巢的埃伊特和基斯鸦巢的乌达克，然后返回裂石堡向罗卡格复命。', '做的好，$N。我们不用再担心阿拉卡什么时候又会引诱我们的商人和信差了。', '欢迎回来，$N。你解决了阿拉卡的领导者吗?', '', '去泰罗卡森林找裂石堡的罗卡格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9990, '调查图雷姆', '我想起来了。大约一个月前，我确实将几盒奇异的工程零件卖给了埃博尔。我不知道它们有什么用处，只知道这批货物是运往图雷姆的。$B$B或许那里还留有一两只盒子？', '找到密封的盒子，将其交给塞纳里奥树林外的缚地者塔弗格伦。', '以太族?送到杜瑞的物品?特殊的工程学零件?还有一个血精灵准备要将最后一箱送到火翼岗哨?$B$B这些话是什么意思?!这些跟塞纳里奥灌木林里的那些德鲁伊有什么关系?$B$B我想我们该看看箱子里的东西。', '你带来了什么消息，$N?', '', '去泰罗卡森林找塞纳里奥树林的缚地者塔弗格伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9991, '侦查大地', '你若想成为我的耳目，就必须加倍勤勉些才行。首先，马上去执行一次高空侦察任务吧。奈瑟兰达姆斯将载着你飞越燃烧军团的几处铸魔营地，你必须记下你所看到的一切，哪怕是最微不足道的细节也不能放过。你认为无关紧要的信息，其实有可能派上大用场。$B$B我要你特别留意营地中的建筑物布局和防御力量的部署。$B$B$N，奈瑟兰达姆斯正等你呢，别害怕，他会确保你的安全。', '好好享受这趟旅程吧。调查完毕之后跟奥图里斯谈一谈。', '做的好，$N!现在我们有计画反击的重点了!', '从没坐过虚空龙飞行吧?', '侦查铸魔营地', '去纳格兰找受难者奥图里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9992, '奥雷巴种子', '你不觉得这片森林里的树很漂亮吗？我经常会希望能在艾泽拉斯世界也看到这么美丽的树。$B$B可是我很犹豫该不该将种子带回去。这些树种跟普通的种子不同，很难运输，带上它们将会给旅程增加许多不便。这些包藏在坚硬的松果内的种子一旦成熟，就会从树枝上掉下来。$B$B如果你在旅行途中见到掉落下来的松果，能帮我把里面的种子带一些回来吗？', '收集30颗奥雷巴种子，把它们交给奥蕾莉亚要塞的洛瑟蕾丝。', '谢谢你带来这些种子。我快要可以将第一批送回去了!', '我开始收集种子了，但我需要一些帮忙才能有足够的种子带回暴风城的公园。', '', '去泰罗卡森林找奥蕾莉亚要塞的洛瑟蕾丝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9993, '奥雷巴油', '森林里奥雷巴树上结的那些油乎乎的种子非常有用。我一直想要收集这类种子，榨出它们的油，然后再想想能用它来做什么。$B$B你看，外面的森林中到处都是奥雷巴树，许多种子都被浪费掉了。总之，我不管最后榨出来的是食用油也好，灯油也好，武器油也好，我希望不要浪费那些种子！$B$B将你从奥雷巴果中收集到的种子带回来给我，森林里到处都是这些玩意。', '将30颗奥雷巴种子交给裂石堡的拉克妮亚。', '这是个好的开始，但我们需要更多才能挤出相当份量的油!', '你有种子给我吗?', '', '去泰罗卡森林找裂石堡的拉克妮亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9994, '这些东西是什么？', '我不知道你怎么想，但是我对这些东西压根没有了解。我只知道它们看上去相当危险！$B$B$N，我想你应该将这箱零件交给东南方奥蕾莉亚要塞的杰奈·星语。她或许知道这些东西的来历。', '将这一箱零件交给泰罗卡森林奥蕾莉亚要塞的杰奈·星语。', '喔不!这真是个可怕的消息!我不敢相信除了两个塞纳里奥朋友还活着外其它所有人都死了。$B$B好吧，让我看看那些零件。我只希望它们不是我所猜想的东西。$B$B没错，如同我担心的一样，我相信这些是炸弹零件。我们在沙塔斯城的眼线告诉我们有些以太族向他们有来往的地方进口违禁品。', '你看起来很担心。那是什么，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9995, '这些东西是什么？', '我不知道你怎么想，但是我对这些东西压根没有了解。我只知道它们看上去相当危险！$B$B$N，我想你应该将这箱零件交给东南方裂石堡的图基。他或许知道这些东西的来历。', '将这一箱零件交给泰罗卡森林裂石堡的图基。', '喔不!这真是个可怕的消息!我不敢相信除了两个塞纳里奥朋友还活着外其它所有人都死了。$B$B好吧，让我看看那些零件。我只希望它们不是我所猜想的东西。', '你看起来很担心。那是什么，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9996, '攻击火翼岗哨', '火翼岗哨的血精灵为凯尔萨斯和伊利丹效力。从你说的情况来看，血精灵显然在利用图雷姆的破碎者偷运零件，企图制造某种杀伤力极强的武器。$B$B无论他们在打什么鬼主意，现在我们能做的就是削减这帮家伙的数量。$B$B除掉火翼血精灵！转至北边的火翼岗哨，给他们点颜色瞧瞧。', '杀死10个火翼防御者、10个火翼血警卫和10个火翼术士，然后向泰罗卡森林奥蕾莉亚岗哨的米利迪安中尉复命。', '这是个好的开始，而且根据你在那里的庭院所看到的，和我们接收到的消息一样，看来当前情况非常迫切了!', '回报。你从火翼岗哨带回了什么消息?', '', '去泰罗卡森林找奥蕾莉亚岗哨的米利迪安中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9997, '攻击火翼岗哨', '火翼岗哨的血精灵为凯尔萨斯和伊利丹效力。从你说的情况来看，血精灵显然在利用图雷姆的破碎者偷运零件，企图制造某种杀伤力极强的武器。$B$B无论他们在打什么鬼主意，现在我们能做的就是削减这帮家伙的数量。$B$B除掉火翼血精灵！转至东北方的火翼岗哨，给他们点颜色瞧瞧。', '杀死10个火翼防御者、10个火翼血警卫和10个火翼术士，然后向泰罗卡森林裂石堡的卡乌尼中士复命。', '这是个好的开始，而且根据你在那里的庭院所看到的，和我们接收到的消息一样，看来当前情况非常迫切了!', '回报。你从火翼岗哨带回了什么消息?', '', '去找泰罗卡森林裂石营地的卡乌尼中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9998, '野蛮的邻居', '最近占据了东边废墟的那些邪兽人给山德制造了成堆的困扰和麻烦。他们一进入废墟，就迫不及待地开始建造堡垒并整修了房屋。$B$B现在，他们日夜不停地赶工，似乎在谋划着什么。我已经派了一名非常值得信赖的斥候去监视他们，不过，我们不能再耽误时间了。你要立刻转至噬骨废墟，消灭他们的苦工，然后去北边的奥蕾莉亚岗哨找到塞洛莉娅·影衣，她会给你指示后续的任务。', '杀死12名扭曲的苦工，然后向奥蕾莉亚岗哨的塞洛莉娅·影衣报告。', '<高等精灵点点头。>$B$B这是个好的开始，但伯特泰欧派你来是对的。我有个新发现或许能解释邪兽人出现在这的原因。', '我猜是伯特泰欧派你来阻挠他们的苦工吧?', '', '去泰罗卡森林找奥蕾莉亚岗哨的塞洛莉娅·影衣。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9999, '争取时间', '只要那些传送装置仍然完好无损，燃烧军团就能源源不断地向各处铸魔营地输送兵力。这样一来，我们是不可能彻底摧毁那些铸魔营地的。必须设法破坏他们的传送装置。$B$B现在我马上开始制定一个完美的攻击计划。但我需要时间，如果你能杀掉一些工程师和修理工，必定会令营地陷入混乱，这样我就有了宝贵的时间。$B$B$N，尽可能避开那些监工，他们很难对付。', '纳格兰西部的受难者奥图里斯要求你除掉2个恶魔卫士军团士兵、3个莫尔葛工程师和8个甘尔葛修理工。', '如我所猜想的一样。没有特定摧毁地狱钢铁的方法。然而，一切都没有不见……', '这么快就回来了?', '', '去找纳格兰的受难者奥图里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10000, '不受欢迎者', '我们在萨尔玛的军队认为地狱火堡垒附近区域的邪兽人已经全部清除掉了，但是最近，在东边废墟一带，我们又发现了一些邪兽人。$B$B现在，我们必须阻止他们在那里创建新的据点。罗卡格已经派追踪者凯德去监视他们的行动了，但我们还得采取进一步的措施来阻止他们继续深入废墟。$B$B你先去废墟里清理一些他们的苦工，然后去北边的树林找里找到凯德。他会告诉你接下去做什么。', '杀死12名扭曲的苦工，然后向追踪者凯德报告。', '恐怕阻止邪兽人将不只是干扰他们的工人。我发现那解释了他们出现在这里的原因并加强了我们一定要快点动作的信念。', '我正要传个消息给瑞克格建议发动攻击，但我看现在不太需要了。', '', '去找泰罗卡森林裂石营地的追踪者凯德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10001, '主规划师', '所有铸魔营地的都是由一名莫尔葛主规划师进行设计的。这个人将会负责规划铸魔营地中各个建筑物类型、位置和数量。而且，这些信息将会被整理成一份蓝图，由该营地的主规划师随身携带，妥善保管。$B$B我们现在需要的就是这份主规划师的蓝图。一旦这东西到手，我们就可以去找我的一位老朋友，并说服他帮助我们。$B$B总之你，你现在先去杀掉莫尔葛主规划师，并夺得蓝图。他现在应该就在铸魔营地中。', '纳格兰西部的受难者奥图里斯要求你取回主规划师的蓝图。', '希望我的朋友知道如何摧毁炼冶场。毕竟他是燃烧军团工程师……', '不论如何一定要避开监督者。绝对不能让他们见到你。后果会不堪设想!', '', '去找纳格兰的受难者奥图里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10002, '莉塞蕾·火纹', '在过去的几天里，我看到过一个女血精灵出入邪兽人的要塞，与邪兽人的首领进行会谈。从她的肢体语言中，我可以看出她是在发布命令。但这到底是怎么回事？她是在传达谁的命令？$B$B我对此充满好奇，所以我在她离开邪兽人营地时跟踪她，结果发现她往北边的火翼岗哨去了。我在火翼岗哨边界停止了跟踪。$B$B在她下一次离开邪兽人营地前杀掉她。', '找到莉塞蕾·火纹并杀掉她，然后向塞洛莉娅·影衣复命。', '<瑟萝莉雅对你点点头。>$B$B做的好。我们替自己争取了一点时间。血精灵会对他们朋友发生的事开始好奇。希望到那时候，我们会更了解他们的意图。', '营地里的活动持续在扩大。你完成了你的任务吗?', '', '去泰罗卡森林找奥蕾莉亚岗哨的塞洛莉娅·影衣。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10003, '莉塞蕾·火纹', '在过去的几天里，我看到过一个女血精灵出入邪兽人的要塞，与邪兽人的首领进行会谈。从她的肢体语言中，我可以看出她是在发布命令。但这到底是怎么回事？她是在传达谁的命令？$B$B我对此充满好奇，所以我在她离开邪兽人营地时跟踪她，结果发现她往北边的火翼岗哨去了。我在火翼岗哨边界停止了跟踪。$B$B在她下一次离开邪兽人营地前杀掉她。', '找到莉塞蕾·火纹并杀掉她，然后向追踪者凯德复命。', '<凯德对你点点头。>$B$B做的好。我们给自己买了一点时间。血精灵会对他们朋友发生的事开始好奇，我们会更了解他们的意图。$B$B等到时机到来，我会告诉瑞克格我们的进度。', '我们让他们准备越久就越难将他们根除。你切断他们的联系了吗?', '', '去找泰罗卡森林裂石营地的追踪者凯德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10007, '削弱邪兽人', '你得了解山德和波尔泰姆的心理，他们连群鸟人都不能忍，就更不会允许如此强大的敌人在我们的大门口创建起据点。所以，得他们让派些援军过来。要攻击邪兽人营地的驻军，仅仅依靠我们两人的力量是不够的。$B$B我们必须抑制住来自邪兽人的威胁。我决定了，你去骚扰他们，我会想办法阻止他们的援兵。', '杀死10名噬骨蹂躏者和6名噬骨碎脊者，然后向塞洛莉娅·影衣复命。', '事情开始好转了。我想如果我们可以阻止邪兽人增加他们的援军，我们就能保住这个前哨。', '你的攻击成功吗?', '', '去泰罗卡森林找奥蕾莉亚岗哨的塞洛莉娅·影衣。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10008, '泰罗卡的事情，在泰罗卡解决', '如果立刻把邪兽人没有被完全消灭干净通知萨尔玛，那边一定会增派更多的援兵过来碾平一切。但是，说实话，我不太希望情况演变成这样，所以我们一点风声都不要透露出去，知道吗？$B$B如果我们剿灭这些邪兽人的速度足够快，那就不会引起裂石堡以外任何人的关注。所以，现在就开始行动吧。$B$B你现在立刻拿起武器，用你能想到的一切办法去袭击他们——只要能将邪兽人消灭干净，怎样都好。', '追踪者凯德要你杀死10名噬骨蹂躏者和6名噬骨碎脊者。', '我知道你见识多广，但你要了解，$N，有些故事最好留在它们发生的地方。这样你懂了吗?', '告诉我选你执行这个任务是对的……', '', '去找泰罗卡森林裂石营地的追踪者凯德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10009, '大打出手', '<萨萨拉比姆大笑起来。>$B$B这是都是我萨萨拉比姆设计的。$B$B<萨萨拉比姆指着蓝图上绘制的建筑物。>$B$B瞧这些塔。恶魔猎手双眼不能视物，对吧？可怜的奥图里斯。如果他能看见铸魔营地的构架，恐怕会失声痛哭。$B$B只要你肯帮萨萨拉比姆，萨萨拉比姆就帮你。$B$B<萨萨拉比姆递给你一本账本。>$B$B这些家伙欠萨萨拉比姆的钱。很多很多钱。为萨萨拉比姆讨回债务，他们肯定不愿意乖乖交出金币，你得使用武力，好在你是个强者。连萨萨拉比姆都不是你的对手呢！', '沙塔斯城的萨萨拉比姆要你取回拉里克的债款、库什库什的债款和弗鲁恩的债款。', '现在成交，不过当沙萨拉毕恩告诉你的时候，不可以生气，好吗?', '没有拿到沙萨拉毕恩的金子就不要回来!', '', '去泰罗卡森林找沙塔斯城的萨萨拉比姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10011, '扫荡铸魔营地', '$N，召集你的盟友吧。监工都是些很难对付的强者，你需要朋友的帮助。$B$B和你的盟友们并肩作战，杀掉铸魔营地的监工，然后用他们的钥匙调转邪能火炮的炮口，朝着铸魔营地开火吧。摧毁营地后回来向我复命。', '纳格兰西部的受难者奥图里斯要求你摧毁铸魔营地：仇恨和铸魔营地：畏惧。', '我们胜利了!燃烧军团的发展已终止!$B$B我给你英勇的行为一个奖励选择!', '完成了吗?', '', '去找纳格兰的受难者奥图里斯。', '摧毁铸魔营地：仇恨', '摧毁铸魔营地：畏惧', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10012, '邪兽人的计划', '这张潦草无比的计划书明显出自于某一个邪兽人的手笔。虽然你不知道它到底在说什么，但里面隐含的意思却非常清楚：邪兽人接受了火翼岗哨的血精灵下达的命令。$B$B为什么这两个种族会联合起来？波尔泰姆或许会知道一些内幕。你决定把地图带回奥蕾莉亚要塞去交给他。', '将邪兽人的计划交给泰罗卡森林中奥蕾莉亚要塞的波尔泰姆。', '<伯特泰欧从你手中接过计画书并阅读它们。>$B$B如果你没有把这份图像带来，我只能说你真是疯了，但现在它在这里，非常清楚。邪兽人不只效命于血精灵，很明显的，他们受命要抓住我们的注意力。$B$B这份图像带来了比答案更多的问题，但它让我们更了解我们面对的是什么情形。', '你替暴风城所做出的贡献应该得到表扬，$N。如果范克里夫成功地实行了他的计画，无疑将会给王国带来巨大的灾难，我们必须避免这种事发生。$B$B收下这个吧，$C，它代表了我的谢意。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10013, '幕后黑手', '这张潦草无比的计划书明显出自于某一个邪兽人的手笔。虽然你不知道它到底在说什么，但里面隐含的意思却非常清楚：邪兽人接受了火翼岗哨的血精灵下达的命令。$B$B为什么这两个种族会联合起来？罗卡格或许会知道一些内幕。你决定把地图带回裂石堡去交给他。', '将邪兽人的计划交给泰罗卡森林中裂石堡的罗卡格。', '<瑞克格从你手中接过计画书并阅读它们。>$B$B凯德说的是真的!那些\r\n邪兽人垃圾果然在搞鬼。我从没想过他们会和血精灵串通。$B$B从这份地图看来，邪兽人是要让我们无暇分心……但为什么呢?这真是让我心神不宁，$N。你立刻把它带来给我是正确的行为。', '你手里拿着什么，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10015, '火翼岗哨的项目', '正如我说的那样，我们已经收到了新的情报，并且面临着更棘手的问题。$B$B血精灵正在火翼岗哨拼命地制造第二枚炸弹。用不着我再多说，你也知道一旦他们建成这个装置并投入使用的话，对裂石堡来说该意味着什么了！$B$B我的侦察员告诉我他们在环绕中心庭院的四座较小的建筑物里看守着该装置的密码。趁现在还来得及，到那里去帮我把密码偷回来！', '偷取四张魔法炸弹密码表，把它们交给泰罗卡森林中裂石营地的卡乌尼中士。', '干得好!$B$B让我看看这些密码单。我有个点子，这可能会很疯狂!', '你拿到哪些密码了没?你看过那些塞纳里奥灌木林的德鲁伊发生得事。$B$B你想要那些事发生在碎石堡吗?', '', '去找泰罗卡森林的卡乌尼中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10016, '森林座狼的尾巴', '你在旅行途中遇到任何森林座狼没有？当我在勘察森林北边扩展区域时看到过它们。我建议，如果你没有准备好战斗的话，千万不要靠近它们。$B$B它们一点也不害怕我们，而且会毫不迟疑地保卫它们的领地。$B$B不过，森林座狼的尾巴都非常非常的漂亮。我正在收集它们的尾毛来装饰我的新斗篷，不过但它们总是能逃脱我的捕捉。你能帮帮我的忙吗？', '奥蕾莉亚要塞的波尔泰姆想让你收集12条森林座狼的尾巴。这些尾巴可以从森林座狼和森林座狼前锋身上获得。', '啊，做的好，朋友。它们比我想象中的还要好。它们会让我做出很棒的披风。$B$B<伯特泰欧往旅店看了一眼。>$B$B对，它会是一件很棒的披风。', '你在森林的严苛环境中生存下来了。你带了我披风需要的尾巴来吗?', '', '去泰罗卡森林找奥蕾莉亚要塞的波尔泰姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10017, '物资紧张', '每天涌入沙塔斯城寻求庇护的难民越来越多了。很多人还受了严重的伤，他们能活着坚持到这里，可真是个奇迹。$B$B我可以医治大部分的寻常伤症。身为一名奥尔多医者，我所接受过的训练让我对此有着良好的准备和应对经验。染毒的伤症则略麻烦一些，更何况我这里的抗毒剂储备量已经不太够了。$B$B给从我当地的巨牙蜘蛛身上取一些毒囊来吧，这样我就能制作更多的解毒剂了。在泰罗卡地区东南方的那块地方，你就可以找到那些蜘蛛。', '给沙塔斯城的莎妮尔带回8个巨牙毒囊。$B$B为奥尔多完成任务将会使你在占星者阵营中的声望等级降低。', '感谢你，$N。奥多尔会记得你的行为。', '你拿到毒囊了吗，$N?这些难民等不了太久的。', '', '去找泰罗卡森林的莎妮尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10018, '狼魂之衣', '很久以前，当兽人部落还居住在泰罗卡森林的时候，他们非常崇拜狼的野性。而在他们离开之后，兽人开始变得不再需要狼之魂，并将它遗弃在了森林中。$B$B在那些日子里，狼之魂渐渐地感到孤独，最后离开了森林。$B$B我相信我能将狼之魂召唤回泰罗卡森林，就像我们一样回到祖先的家园。我要为仪式准备一些用森林中狼的毛皮制作的祭袍，这样才能指引灵魂回来。', '给裂石堡的玛鲁卡兹带回12块森林座狼的毛皮交。', '这些非常完美，$N!这就是我想要的。', '你找到所有我需要的毛皮了吗?', '', '去泰罗卡森林找裂石堡的玛鲁卡兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10019, '更多毒囊', '', '', '谢谢你，$N。纳鲁已对这些不幸的灵魂加强保护，如果他们到了沙塔斯却因为先前的伤口而死去那会是一大憾事。$B$B<这个任务可以重复进行直到声望到达中立。>', '很多难民还需要治疗他们中毒的伤口。你带了更多的毒囊来给我吗，$N?', '', '去找地狱火半岛的莎妮尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10020, '萨恩莉亚的解药', '我右侧的这位女士的头部曾受过非常严重的创伤。虽然她很幸运地活了下来，却失去了视力。$B$B有一种非常传统的方法可以治愈她的眼睛，但是这需要使用一种原始蜥蜴的血。$B$B不幸的是，这里来自世界各地的偷猎者数量实在太多，导致栖息在泰罗卡森林里的蜥蜴数量正在逐渐变少。$B$B有一只名叫“凝石者”的蜥蜴非常着名，我小时侯就经常听到它的名字。据说它就住在东边，陆地的尽头。$B$B把它的血带回来给我，这样萨恩莉亚就能重见光明了。', '将凝石者的血交给沙塔斯城的莎妮尔。$B$B为奥尔多完成任务将会使你在占星者阵营中的声望等级降低。', '谢谢你，$N。照顾那些有需要的人是一件困难的工作，但是时间久了我发现它也有它的奖励。', '你取得血液了吗，$N?没有它，札丽亚就无法再见到她的儿子。', '', '去找泰罗卡森林的莎妮尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10021, '重现圣光', '以前，有许多德莱尼人生活在这个地区，而我们奥尔多则担负着守卫德莱尼圣地与祭坛的任务。现在，这些圣地与祭坛大多已经被我们的敌人摧毁或占据了。$B$B从这里向东去，就有一处鸦人的据点。这处据点是故意创建在过去我们的三处神圣祭坛之上的。那些鸦人利用他们的邪恶魔法扭曲并亵渎了圣地中原生的纯洁能量。$B$B把这个带到那处据点去，用它净化那里的三座祭坛。', '伊沙娜希望你能转至沙塔斯城正东方的鸦人前哨站，使用神圣之瓶净化东部祭坛、西部祭坛和北部祭坛。$B$B为奥尔多完成任务将会使你在占星者阵营中的声望等级降低。', '感谢你，$N。我们是圣光的守护者，不能背弃我们的责任，就算是在最艰难的时期也一样。', '你完成了你的任务吗，$N?', '', '去沙塔斯城找奥尔多高地的伊沙娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10022, '狡猾的铁腭', '我这里已经有了许多非常漂亮的毛皮，但是，我还是最想得到一件由狼的毛皮作成的斗篷兜帽，那样一切就完美了。想想，假如你看到你的敌人披着森林里最狡猾的掠夺者的毛皮，是不是会感觉害怕呢！$B$B我曾捕捉过那只叫铁腭的老狼，但没有成功。那时候我试过将它逼上死路，试过最精巧的陷阱，也试过最诱人的肉饵，但是都失败了……它可真聪明。$B$B这家伙通常都游荡在森林东北边的扩展区域。如果你能帮我捉到它，我一定会支付你一大笔报酬的。', '为奥蕾莉亚要塞的波尔泰姆带回铁腭的毛皮。', '我对你的技巧甘拜下风，$N。你已证明了你是个高超的猎人。$B$B我不会忘记你对制作这件披风的帮忙。这绝对是件独一无二的披风，我会骄傲地穿上它。', '老铁颚也把你撂倒了吗，朋友?还是你比那个老家伙更聪明呢?', '', '去泰罗卡森林找奥蕾莉亚要塞的波尔泰姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10023, '狼王铁腭', '收集第一批毛皮的工作，你完成得非常出色。$B$B不过，制作祭袍还需要另一块特殊的毛皮。你知道吗，森林中有一只很特别的狼，它年老却相当狡猾，还是森林中狼群的族长。它是一只力量非常强大的食肉动物，名叫铁腭。$B$B我常常看到它在森林的东北边漫步。如果能将它的毛皮添加到祭袍中，一定能为狼之魂指明道路。$B$B不要为铁腭的死亡而感到悲伤，它会为此受到所有人的尊敬。', '将铁腭的毛皮交给裂石堡的玛鲁卡兹。', '这毛皮比我期望的还要好!这是个好预兆，$N，灵魂会因为你对这次典礼的贡献而认同你的。$B$B我用剩下的毛皮为你做了一顶盔帽，$N。它验明你是万能的猎人，也是泰罗卡森林伟大狼魂的盟友。', '灵魂等待着，$N。你拿到狼之族王的毛皮了吗?', '', '去泰罗卡森林找裂石堡的玛鲁卡兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10024, '沃雷塔尔的预言', '我们的领袖先知沃雷塔尔曾是凯尔萨斯最重要的一名顾问。有一天，他的预言梦境却警告他说，如果凯尔继续沿着当前的道路走下去，那么等待我们整个种族的只有毁灭。$B$B梦境一般都是非常模糊和不确定的，但我们的炼金师为他发明了一种药剂，使他可以集中感官与意识去了解梦境的内容。然而，这种药剂需要一种非常稀有的材料：蜥蜴的眼球。我之前的供货商，也就是这个可怜的虚灵，太令我失望了。$B$B在泰罗卡的岩石地域寻找这些湿鳞蜥蜴吧，把它们的眼球带回来给我。', '将8颗湿鳞蜥蜴的眼睛交给沙塔斯城的奥术师艾蒂莉亚。$B$B为占星者完成任务将会使你在奥尔多阵营中的声望等级降低。', '这些眼睛的状态都很好，$N。继续努力你很快就会成为占星者的朋友了。', '你为沃蓝索的精华取得蜥蜴眼了吗?', '', '去找沙塔斯城的奥术师艾蒂莉亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10025, '更多蜥蜴眼', '', '', '谢谢你，$N。沃蓝索的预言总有一天会决定我们种族的命运。我们有必要尽力确保那些预言尽可能准确发生。$B$B<这个任务可以重复进行直到声望达到中立。>', '制作一小瓶的沃蓝索精华就要很多的蜥蜴眼。给我更多必定可以引来占星者的认同。', '', '去找地狱火半岛的奥术师艾蒂莉亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10026, '魔法扰动', '虽然承认这件事令我的确很尴尬，但是最近泰罗卡森林里发生了许多奇怪的事情，这在我当学徒的时候可从未发生过。$B$B比如说，我的魔法在泰罗卡森林内偶尔会失效，而且我肯定所有的施法步骤都没有出错。第一次发生这样的事情时，我差点疯掉。$B$B不过，我想我已经找到原因了。这片森林里到处都有一种叫迁跃跟踪者的怪兽，它们首选魔法能量，而且能影响施法者施法。最好的解决办法就是杀掉它们。', '奥蕾莉亚要塞的安达尔要求你杀死10只迁跃跟踪者。', '<安达尔欧用长袍的袖子在他的额头上轻拍了几下。>$B$B感谢老天。我正开始纳闷是否森林里剩下的生物都被迫离开了。', '你处理掉堡垒附近的扭曲巡者了吗?', '', '去泰罗卡森林找奥蕾莉亚要塞的安达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10027, '魔法扰动', '没有什么事情能比在施法时被某些未知的力量所干扰更让人烦心了。在做了四次尝试后，我终于明白这绝对不是巧合，于是我派了凯比希尔出去调查此事。$B$B我敢保证，你这辈子绝对没有遇到过比它还爱顶嘴的小鬼，让它干点活可真难。$B$B不过它最后还是找到了问题的根源，是一种叫作迁跃跟踪者的怪物在从中捣鬼。无论出现在什么地方，它们总是习惯于扰乱魔法能量流。我已经受够了，把它们都干掉。', '杀死10只迁跃跟踪者，然后向裂石堡的库加托克复命。', '奇柏伊斯欧很欣慰你解决了那个小问题，对吗，奇柏伊斯欧?$B$B<小鬼忽略它的主人，想必是很愤怒。>$B$B你要原谅他不好的态度。你知道恶魔是什么样子……', '奇柏伊斯欧想知道是否能安全的掷出一个火球而不让他再次出糗。$B$B<小鬼发出了几次卡嗒声然后术士便转向他。>$B$B不，不是我的暗影箭!收回它，你这个过度生长的小妖精!', '', '去泰罗卡森林找裂石堡的库加托克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10028, '强大的容器', '在图雷姆废墟中有许多富含原始魔法能量的容器。非常幸运的是，当前侵占了图雷姆的那些破碎者并不知道这些容器的存在。但是，恐怕不久之后他们就会发现这一点。$B$B如果我们这些幸存者能够掌握容器中的魔法能量，或许就能抵挡住恶魔魔法的引诱。每拯救一名奎尔多雷，都能为我们赢得失去的荣耀。帮我带一些那种容器回来，$c。', '为奥蕾莉亚要塞的洛瑟蕾丝带回8个德莱尼容器。', '我希望这些不是城里仅有的容器。这是个好的开始，但我怀疑我们需要比这些更多的容器。', '你找到任何完整的容器了吗?', '', '去泰罗卡森林找奥蕾莉亚要塞的洛瑟蕾丝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10030, '收集骸骨', '无数德莱尼人在奥金顿大爆炸中不幸罹难，尸骨就散落在白骨荒野。他们不安宁的灵魂仍在世间飘荡。$B$B$C，帮帮我吧，将他们的尸骨带往最终的安息之地！只有这样，他们才能安然长眠。$B$B收集无眠之骨，将它们交给白骨荒野中心奥金顿的疯狂的拉姆杜尔。尽管此人名字古怪，可他懂得如何处理这些尸骨。', '收集10根无眠之骨，并将它们交给奥金顿仪式广场西侧的疯狂的拉姆杜尔，奥金顿就在泰罗卡森林白骨荒野的中心。', '太好了，正好是我需要的……更多的骨头。$B$B<蓝姆多叹了口气。>$B$B是的，是的，我会确认这些属于我们光荣的祖先的遗体将会有一个适合的葬礼，别担心。$B$B假如你真的想帮助这些往生者的话还有一件事情你可以帮忙。', '这是什么?你是谁?', '', '去泰罗卡森林奥金顿的仪式广场找疯狂的拉姆杜尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10031, '迷失者的解脱', '奥金顿大爆炸使许多德莱尼人的灵魂堕落腐化。如今，他们痛苦地在白骨荒野徘徊着。$B$B$N，求求你，让他们获得安宁吧。消灭奥金顿外的失落的幽魂和破碎的骷髅。$B$B什么？你认为让他们继续在痛苦中挣扎会更好？$B$B完成任务后你就返回难民车队，告诉苏拉文你都做了什么。', '消灭10个失落的幽魂和10只破碎的骷髅，然后向泰罗卡森林白骨荒野难民车队的苏拉文复命。', '你做了必须做的事。虽然我的祖先成为可怕的不死族让我很伤心，但你的行为让他们得到安息。$B$B谢谢你让他们获得自由。', '你完成了索拉伏恩要你做的事了吗?', '', '去白骨荒野找难民车队的苏拉文。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10033, '通缉：白骨秃鹫！', '通缉：白骨荒野的白骨秃鹫。这些携带着瘟疫的白骨秃鹫必须被悉数消灭！$B$B虽然它们的行踪遍布白骨荒野，但多数集中在北边的腐臭山。$B$B完成任务后可以向泰拉·远途领取奖赏。', '杀死20只白骨秃鹫，然后向泰罗卡森林内奥蕾莉亚要塞的泰拉·远途复命。', '是的，我相信你杀了所有的鞭骨者。很明显地从上尉要你交回的悬赏布告就可以证明。$B$B<泰伊拉挖苦的看了你一眼>$B$B我会把你的话记在上面。不知道该怪谁去承揽这个职务的，不过还是谢谢你为联盟出的力。这里有些东西是要给你的补偿。', '我猜你是为了鞭骨者的赏金对吧?', '', '去泰罗卡森林找奥蕾莉亚要塞的泰拉·远途。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10034, '通缉：白骨秃鹫！', '白骨荒野的白骨秃鹫袭击了玛乌格，令他身染疾症。他现在想要杀死所有的白骨秃鹫！$B$B虽然它们的行踪遍布白骨荒野，但多数集中在北边的腐臭山。$B$B完成任务后向玛乌格·锐箭领赏吧。', '杀死20只白骨秃鹫，然后向泰罗卡森林裂石堡的玛乌格·锐箭复命。', '你一定杀了很多鞭骨者吧!太好了，我恨他们!自从我被他们其中一位袭击后，我持续有昏晕的症状。$B$B你能了解这有多尴尬吗?嘿，就把这个当作是你帮我报仇的谢礼吧。', '我闻到的味道是你手上的鞭骨者的血吗?', '', '去泰罗卡森林找裂石堡的玛乌格·锐箭。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10035, '托古斯！', '白骨荒野中有一只非常可怕的生物，只有最无畏的勇者才有胆去猎杀它。$B$B没错，我说的便是白骨秃鹫之王托古斯，它盘踞在位于白骨荒野西部边缘的哈兹鸦巢。$B$B可是鸦人们在那附近扎了一个被称为托古斯克星的大型稻草人，这玩意令托古斯胆怯不已。不过，如果你能将托古斯的配偶特拉克拉的残骸放在稻草人脚下，它必定会不顾一切地飞离鸦巢冲过来。你可以在白骨荒野北边的腐臭山找到特拉克拉。$B$B如果成功杀死了托古斯，记得将一片托古斯的尾羽带回来给我。', '利用特拉克拉的残骸引出托古斯，将托古斯交给泰罗卡森林奥蕾莉亚要塞的泰拉·远途。', '令我印象深刻，$C。托苟斯是我在纳格兰这边所知道最凶猛的生物。$B$B这个嘛，我想这值得从艾兰里堡垒的宝藏中给你某个东西。挑一个吧。', '你拿到羽毛了吗?我是否应该为了你的勇于尝试的勇气而奖赏你呢?', '', '去泰罗卡森林找奥蕾莉亚要塞的泰拉·远途。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10036, '托古斯！', '我想要白骨秃鹫之王托古斯的命！$B$B不久前，我在白骨荒野西部边缘的哈兹鸦巢狩猎时，它突然扑向我。$B$B<玛乌格拍了拍他的眼罩。>$B$B它啄瞎了我的眼睛，那么我就要它的命！将一片托古斯的尾羽带回来给我，我会好好奖赏你的。$B$B鸦巢附近竖着一个被称为托古斯克星的稻草人，这玩意令托古斯胆怯不已。不过，如果能将托古斯的配偶特拉克拉的残骸放在稻草人脚下，它必定会不顾一切地飞离鸦巢。$B$B你可以在白骨荒野北边的腐臭山找到特拉克拉。', '利用特拉克拉的残骸引出托古斯，将托古斯交给泰罗卡森林裂石堡的玛乌格·锐箭。', '真是太感谢了，$N!你帮我报了仇，而就像我承诺的，你将得到你的奖赏!$B$B从这些当中挑一个并好好的使用它!!', '你杀了他吗?托苟斯死了?!$B$B你的证据呢?', '', '去泰罗卡森林找裂石堡的玛乌格·锐箭。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10037, '宁可去钓鱼', '说到湖泊，东北边的那面湖泊是钓鱼的好地方。我以前常常跟朋友们一起去，但是现在，我妈妈不再让我去那个地方了。$B$B她总是说那里很危险，但是，我只看到一些小蜘蛛出现在湖泊周围啊。或许，或许……说不准这些蜘蛛会对你做些什么吧……$B$B但是，但是呢，我特别爱吃湖里的鳗鱼。如果你恰好也要去湖泊那边的话，能不能帮我带回来一些呢？你放心，这些狂躁不安的鳗鱼一旦被制服，就能轻易地带回来了哦。', '为沙塔斯城的塞瑟带回8条新鲜的亮鳞电鳗。', '谢了!我都快想不起上一次有鳗鱼时什么时候了!$B$B我要怎么煮它们呢?', '<塞斯用力拉了拉你的披风。>$B$B你有找到鳗鱼吗?有吗?', '', '去找沙塔斯城贫民窟的塞瑟。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10040, '他们是谁？', '我不知道他们究竟是谁，但我知道他们充满了敌意！$B$B据我观察，营地中有三个家伙总是喋喋不休的。穿上这件伪装服，潜入格兰戈瓦村，与阴暗新兵、阴暗劳工和阴暗顾问聊聊天。$B$B要小心，阴暗猎人可以识破你的伪装，这些猎人看上去就不好对付！维系伪装的魔法能量有些脆弱，因此打探敌情期间，你千万不能离开村子。如果你弄丢了这件伪装，就回来找我吧。我会为你另做一件的。', '在伪装状态下，与阴暗新兵、阴暗劳工和阴暗顾问交谈，然后向泰罗卡森林格兰戈瓦村的列兵维克斯复命。', '太好了，你终于回来了!嗯嗯，你发现了什么?他们是谁?', '你跟他们都谈过了吗?他们说了什么?', '', '去泰罗卡森林找格兰戈瓦村的列兵维克斯。', '与阴暗新兵交谈', '与阴暗劳工交谈', '与阴暗顾问交谈', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10041, '他们是谁？', '我不知道他们究竟是谁，但我知道他们充满了敌意！$B$B据我观察，营地中有三个家伙总是喋喋不休的。穿上这件伪装服，潜入格兰戈瓦村，与阴暗新兵、阴暗劳工和阴暗顾问聊聊天。$B$B要小心，阴暗猎人可以识破你的伪装，这些猎人看上去就不好对付！维系伪装的魔法能量有些脆弱，因此打探敌情期间，你千万不能离开村子。如果你弄丢了这件伪装，就回来找我吧。我会为你另做一件的。', '在伪装状态下，与阴暗新兵、阴暗劳工和阴暗顾问交谈，然后向泰罗卡森林格兰戈瓦村的斥候奈弗蒂丝复命。', '太好了，你终于回来了!嗯嗯，你发现了什么?他们是谁?', '你跟他们都谈过了吗?他们说了什么?', '', '去泰罗卡森林找格兰戈瓦村的斥候奈弗蒂丝。', '与阴暗新兵交谈', '与阴暗劳工交谈', '与阴暗顾问交谈', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10042, '暗影议会必须死！', '什么！这帮家伙是暗影议会的成员？！$B$B$N，你必须返回格兰戈瓦村消灭他们！我要你杀掉他们的暗影主宰，并且尽可能多地干掉阴暗刽子手和阴暗召唤者。$B$B完成任务后向奥蕾莉亚要塞的加维·砂锤中尉复命。$B$B$c，祝你好运！', '杀死10个阴暗刽子手、10个阴暗召唤者和暗影主宰格里弗，然后向泰罗卡森林奥蕾莉亚要塞的加维·砂锤中尉复命。', '这的确是个可怕的讯息!恩，看来似乎我派你去帮忙维克斯是对的。我们最不希望看到的一件事就是暗影议会伫立在我们门前!$B$B$N，我认同你在葛兰戈瓦村的努力，以此授予你有权从这些奖励品中挑选一项作为奖赏。', '那么，你找到什么呢，$g小伙子:小姑娘;?', '', '去泰罗卡森林找奥蕾莉亚要塞的加维·砂锤中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10043, '暗影议会必须死！', '什么！这帮家伙是暗影议会的成员？！$B$B$N，你必须返回格兰戈瓦村消灭他们！我要你杀掉他们的暗影主宰，并且尽可能多地干掉阴暗刽子手和阴暗召唤者。$B$B完成任务后向裂石堡的顾问菲埃拉复命。$B$B$c，祝你好运！', '杀死10个阴暗刽子手、10个阴暗召唤者和暗影主宰格里弗，然后向泰罗卡森林裂石堡的顾问菲埃拉复命。', '这真是不幸的消息不过，当然，派你去帮忙奈夫提斯是对的决定。接下来我们需要的是暗影议会就在我们门前创建据点!$B$B$N，你替你自己赚得了好东西。来吧，挑一个。', '那么，你找到什么呢?', '', '去泰罗卡森林找裂石堡的顾问菲埃拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10044, '拜访盖亚安祖母', '盖亚安祖母要我来找你，并替她向你传个口信。是这样的，她想再跟你谈谈。$B$B$N，我先警告你，虽然祖母病重的消息令我意志很消沉，不过你若是惹恼了她，我还是会召集玛格汉氏族的勇士把你给劈了！她在大厅里等你。$B$B<加尔鲁什指着北边的那座大型建筑物。>$B$B耐心地听她的话，她吩咐你的事情一律照办。', '与盖亚安祖母谈谈，听她讲述故事。', '我们得先扩展你的心灵，这样你才能与先祖们交流。', '请坐，亲爱的。', '聆听盖亚安祖母的话', '去纳格兰找加拉达尔的盖亚安祖母。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10045, '必需的材料', '$N，卡舒尔宗母想跟你谈谈。但在此之前，你必须先去采集一些特殊的草药，我要为你配制一瓶开拓心智的药水，让你具备与先祖的灵魂沟通的能力。$B$B我需要一根泰罗卡森林的奥雷巴根须、一颗赞加沼泽的沼泽莓、一片纳格兰的塔拉蕨和一株刀锋山的龙脊草草。这张羊皮纸上记载了四种草药的地理位置。集齐草药后回来向我复命。', '纳格兰加拉达尔的盖亚安祖母要你收集1根奥雷巴根须、1颗沼泽莓、1片塔拉蕨和1株龙脊草草。', '你非常聪明，$N。我们最了不起的收集者都要花两倍的时间来收集这些药草。$B$B<主母吉雅将这些药草混合成一剂药剂，然后将药剂放到你的嘴巴，要你喝下去。>$B$B别害怕。', '嗨，亲爱的。', '', '去纳格兰找加拉达尔的盖亚安祖母。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10047, '荣耀之路', '“荣耀之路”，他们如此称呼它。这条路从他们那阴森恐怖的要塞中心一直扩展到黑暗之门，路上铺满了我的同胞的尸骨。$B$B他们像对待动物一样追杀我们，摧毁我们的家园，折磨我们的幸存者。这样做还远远不够，他们甚至把我们的尸骨当做铺路石，不让我的同胞得到圣光的照耀。$B$B那些被折磨的灵魂至今还徘徊在这地方，大声呼喊着要解脱出来。$N，我希望你能帮我完成这件事情。', '在荣耀之路上使用德莱尼圣水净化8个被践踏的骷髅，然后返回荣耀堡向位面占卜者克雷夫复命。', '对你的努力致上我最真挚的感谢，$N。虽然尚有非常多未完成，但很高兴知道我们已经帮助他们其中一些找到了永远的安息。', '这哭喊不知为何…….比之前更微弱了。愿圣光给予他们多过想要的。', '', '去地狱火半岛找荣耀堡的位面占卜者克雷夫。', '净化被践踏的骷髅', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10050, '阴魂不散', '当我们征讨德拉诺世界的战役接近尾声的时候，南边的物资库遭到了部落中最为阴险的死亡骑士的攻击。那些卑鄙的幽灵诅咒了物资库的卫兵，他们的灵魂就此遭受到了禁锢，无法得到安息。我们必须拯救那些高贵的灵魂！我请求你结束我的同胞们的痛苦，$N，我实在不忍心亲手杀掉他们。', '荣耀堡卫兵维斯洛要你转至南边的远征军物资库，杀死12个步兵的阴魂、10个巫师的阴魂和5个骑士的阴魂。', '洛萨之子感谢你的帮忙，虽然很少人愿意提起军械库的事。', '我的要求对其它人来说是件恐怖的事。但你得了解的是许多人都不愿意靠近废墟。那些记忆跟伤痛太过鲜明，但我们不能让那些灵魂继续徘徊下去。$B$B他们存在的愈久，就失去更多他们与过去生活的连结，而变的残暴。', '', '去地狱火半岛找荣耀堡的荣耀堡卫兵维斯洛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10055, '回收材料', '有增援军到来是件好事，但是我发现他们没有带来金属和木材。$B$B朋友，看看这周围。木材从来都是稀缺物资，而矿井又被燃烧军团的渣滓侵占了。$B$B我根本找不到供应源，只得去寻找替换物，不过幸好我们可以回收利用一切合适的物资。$B$B荣耀之路南部边缘有许多废弃的攻城车，它们的一些零件还可以使用。你能帮我们找一些回来，补充我们的供给吗？', '给荣耀堡的达姆菲带去8块回收的金属和8块回收的木材。', '状况比我想象的好。当然，要去掉这些铁锈，焦炭，及其它相似物需要一点时间，但我不会抱怨的。', '你可以从外面那些尘土，灰烬，及焦炭中找些可用物资回来吗?', '', '去地狱火半岛找荣耀堡的达姆菲。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10057, '寻找首领', '尽管你帮了大忙，远征军物资库那里却仍处于混乱的状态。没有人知道那里到底发生了什么事情，也没人清楚真正是什么样的诅咒将那些已死士兵的鬼魂禁锢在废墟中。$B$B不过，或许我们完全理解错了。我一直以为每一个鬼魂都是被废墟所禁锢的，但也有很大可能是他们的首领在束缚着他们！$B$B大法师辛托尔和塔沃斯少校的鬼魂应该就在其它鬼魂附近，或许击败他们就可以让其它人得到安息。', '击败大法师辛托尔和塔沃斯少校的鬼魂，然后向荣耀堡西北部哨塔的荣耀堡卫兵维斯洛复命。', '我们只能希望这些步兵的灵魂会跟随着军官的鬼魂安息。再一次感谢你的帮忙，$N。', '你有办法打倒废墟里的军官吗?', '', '去地狱火半岛找荣耀堡的荣耀堡卫兵维斯洛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10058, '古老的礼物', '<牧师把目光缓缓地从杯子前转移到了你的身上。>$B$B难道你不知道，千万不要去打扰借酒消愁的人吗？$B$B唉，有什么用？我觉得有陌生人来是件好事，不过，不知道图拉扬会怎么想？$B$B我记得许多年前，我们从艾泽拉斯出发的前夜，我把《圣光的秘密》借给了他。在战争期间和之后的许多年里，他每天都阅读那本书中的内容，激励他身边的人，赐予他们祝福。$B$B然而，当他必须再次离开我们的时候，他把书还给了我。而我，就像个傻子一样，居然以为把它放在物资库南边的营房中会很安全，就一直把它丢在那里了。', '将《圣光的秘密》交给荣耀堡的玛格尔·戴维迪库斯神父。', '这真的是我要的东西吗?真难相信它竟在战争中保存了下来。废墟的状况并不是太好，我很高兴能再得到它。$B$B这是我仅有的图拉扬的遗物了。$B$B<神父戴维迪克斯似乎正强忍着泪水。>$B$B当你长久与某人并肩作战，彼此的感情会变得比家人更加亲近。', '我想我要求过你不要打扰我。这是什么?', '', '去地狱火半岛找荣耀堡的玛格尔·戴维迪库斯神父。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10065, '披荆斩棘', '当我们去侦察炎鹰部队和他们的传送门时，我受了重伤。斥候洛伊帮我止住了流血，并试图找到一条出路将我送回秘血岗哨。$B$B为了能安全地回去，我们不得不放弃任务。$B$B不过一旦离开这个地方，我们就会遭到掠食者袭击。如果你能帮我们干掉一些野蛮的掠食者，我们回去的路途就会更加安全。', '杀掉10个被激怒的掠食者，然后向守备官营地的斥候约莉复命。', '情况看起来有比较好了，但我还是怀疑是否我在这等待军医不会变得比较好。', '你已经准备好去清理一些这的劫毁者了吗?', '', '去秘血岛找守备官营地的斥候约莉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10066, '纠结之网', '我们不敢丢弃前哨站，也不敢去离守备官营地太远的地方徘徊。靠近矢量感应器的那些变异生物因为水晶泄漏出的能量发生了巨大的变化。$B$B堕落的纠结者似乎获得了某种感知能力，它们学会了制造、安装和隐藏邪恶的陷阱，即便是最小心的士兵也会被它们捕获。$B$B如果我们继续面临这样的处境，那就永远都无法对抗炎鹰部队。杀掉那些纠结者，$N。', '杀掉8只变异的纠结者，然后向守备官营地的守备官考尔琳复命。', '做的好，$N。现在从血色守望派遣援兵会容易多，或在准备与太阳之鹰对抗时不用担心纠缠者在忙什么了。', '你已经准备好去清理这些突变的纠缠者了吗?', '', '去找秘血岛的守备官考尔琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10067, '污秽的水之魂', '大部分接触到水晶能量的生物都发生了相同的变化：它们的身上出现了奇怪的记号，变得更具攻击性，在它们的身体中都有小的水晶碎片。而北边的污秽的水之魂似乎整个身体都变成了水晶。$B$B我从未见过水晶会造成这样的影响，当我们侦察污淤之池时，它们显得尤其危险。我们必须赶在炎鹰部队将它们作为一种新的能量源之前除掉它们。', '除掉6个污秽的水之魂，然后向守备官营地的守备官考尔琳复命。', '做的好，$N。不要漏掉任何消灭太阳之鹰补给的机会是很重要的。', '你已经开始着手清理污浊的水精灵了吗?', '', '去找秘血岛的守备官考尔琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10074, '沃舒古水晶尘', '哈兰曾经是德莱尼人研究纳鲁水晶的重要基地。$B$B我们发现，产自“钻石山”沃舒古的水晶具有极高的研究价值，而且这个区域的所有生物体内似乎都残留着这种水晶尘。如果你在探险途中找到水晶尘的话，就把它们统统拿来给我吧。我会奖励你一枚勋章，你可以用它向军需官购买东西。', '将10份沃舒古水晶尘样本交给哈兰的主研究员阿米蒂恩。', '太棒了，$N。这将会帮助我们与外域中出现的联盟垃圾们对抗。', '从山上来的结晶粉末充满着这个区域的地心。', '', '去纳格兰找哈兰的主研究员阿米蒂恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10075, '沃舒古水晶尘', '', '', '我一直都接受水晶粉末的捐献，$N。你每捐献一组发现的样本都将会得到补偿的。', '这地方就是德莱尼研究纳鲁水晶的主要研究场所。$B$B我们所发现的是与来自“', '', '去纳格兰找哈兰的主研究员阿米蒂恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10076, '沃舒古水晶尘', '哈兰曾经是德莱尼人研究纳鲁水晶的重要基地。$B$B我们发现，产自“钻石山”沃舒古的水晶具有极高的研究价值，而且这个区域的所有生物体内似乎都残留着这种水晶尘。如果你在探险途中找到水晶尘的话，就把它们统统拿来给我吧。我会奖励你一枚勋章，你可以用它向军需官购买东西。', '将10份沃舒古水晶尘样本交给哈兰的主研究员卡托斯。', '太棒了，$N。这将会帮助我们与外域中出现的联盟垃圾们对抗。', '从山上来的结晶粉末充满着这个区域的地心。', '', '去纳格兰找哈兰的主研究员卡托斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10077, '沃舒古水晶尘样本', '', '', '我一直都接受水晶粉末的捐献，$N。你每捐献一组发现的样本都将会得到补偿的。', '这地方就是德莱尼研究纳鲁水晶的主要研究场所。$B$B我们所发现的是与来自“', '', '去纳格兰找哈兰的主研究员卡托斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10078, '烧毁掷刀车', '既然我们的营救计划已经取得了进展，是时候准备进行第二步计划了。$B$B在荣耀之路的另一边，部落仍旧在利用他们古老的掷刀车对付我们。$N，别被它们的年龄蒙骗，这些武器仍然非常危险。我们要继续夺回一切可用的东西，同样我们也不能指望部落会毁掉他们的武器。$B$B带上这个火把，烧毁那些残馀的攻城器械，我必须尽力保证荣耀堡的安全。', '使用燃烧的火把烧毁分布在荣耀之路周围的部落掷刀车，然后将燃烧的火把交给荣耀堡的达姆菲。', '就是这股精神!$B$B我很高兴我们终于有了援军，但我不太确定他们对部落的想法。我来的地方，任何用武器指着你的都是敌人而且需要像个敌人一样的解决掉!', '你看起来精神很好。烧了部落攻城器械让你回复了活力吗?', '', '去地狱火半岛找荣耀堡的达姆菲。', '烧毁东部的掷刀车', '烧毁中部偏东的掷刀车', '烧毁中部偏西的掷刀车', '烧毁西部的掷刀车');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10079, '乱糟糟的矿洞', '那帮该死的甘尔葛小恶魔竟然占领了矿井！$B$B他们不但赶走了我派去的所有工人，还日日夜夜敲打个不停，要把所有的矿石都采光！更糟糕的是，现在达纳斯又开始唠叨个没完！他说如果我不能尽快地解决这件事，他就要拿走我的麦酒！$B$B但是，没有一个矿工愿意帮忙，我的卫兵们也正喝得晕头转向。$B$B$N，我求你了，帮帮我。达纳斯可以夺走我的尊严，但绝不能他拿走我的麦酒！', '杀死12个甘尔葛工兵，然后向工头比格姆斯复命。', '铜须的铜……须，你做到了!你是个英雄，$N。', '告诉我震摇已经结束了而我的人能够回去工作了……拜托?', '', '去地狱火半岛找荣耀堡矿洞的工头比格姆斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10082, '激动的灵魂', '瞧见那些游荡在先祖之地的灵魂了吗？这儿本是一块祥和安宁的净土。$B$B最近，不知道为什么，原本沉睡在宁静之中的先祖灵魂突然复苏，变得躁动不安起来。我们必须揭开滋扰这片净土的根源，不过，更首要的问题是眼前的混乱。$B$B徘徊在先祖之地的鬼魂并不是兽人先祖的灵魂本身，他们只是先祖意识形态的某种存在方式。消灭那些激动的兽人灵魂，完成任务后回来向我复命。', '卡舒尔宗母要求你让8个激动的兽人灵魂再次安息。', '没有用。他们还是继续出现。一定是有某种更加邪恶的事物暗中进行着。', '你不需要药剂就可以看到灵魂了，$N。', '', '去纳格兰找先祖之地的卡舒尔宗母。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10085, '拜访先祖之魂', '$N，我要你调查几座曾有先祖灵魂出没的村落，看看那里是否还有他们的踪迹。$B$B转至此地以北的日泉岗哨，更北处山脚下的嘲颅废墟，东北方的加拉达尔，以及位于纳格兰和泰罗卡森林交界处的血环废墟，调查这四座村落的情况。$B$B完成任务后回来向我复命。', '纳格兰先祖之地的卡舒尔宗母要你去拜访日泉岗哨、嘲颅废墟、加拉达尔和血环废墟。', '这非常的麻烦。你说这些村落中的先祖都不在吗?他们全都往南方去了?', '像风一样快速的动身吧，$N。', '', '去纳格兰找先祖之地的卡舒尔宗母。', '拜访日泉岗哨', '拜访嘲颅废墟', '拜访加拉达尔', '拜访血环废墟');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10086, '我为部落工作！', '你相信吗？这些兽人居然雇佣我帮他们制造炸药来炸毁要塞。这是我梦想已久的工作！糟糕的是我们的材料已经不够了，不过像我这样聪明的地精知道该怎样去做！$B$B你愿意帮帮我吗？我需要荣耀之路两边的攻城器械周围散落的木材和金属，一定要小心那些红皮肤的兽人！$B$B任务完成后，你会得到丰厚的奖赏！', '给萨尔玛的泽格·纳克布斯带去8块回收的金属和8块回收的木材。', '这些东西简直是太棒了!虽然有点弯曲以及烧过的焦痕，但是我一向都可以把粗糙的材料做成高度精密的爆裂物。\r\n\r\n感谢你，$N。你真的具有捡破烂的才能!', '回收物资的工作进行的如何呢?你有找到可以利用的东西吗?', '', '去地狱火半岛找萨尔玛的泽格·纳克布斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10087, '为了部落，烧！', '我是一个非常非常幸运的地精。我要制作的炸弹和工程装备很快就能在重要的任务中派上用场了！$B$B说到任务，我刚收到来自萨尔玛的一条命令：毁掉在荣耀之路附近的联盟火炮……这些设施令部落的要塞时刻处于危险中。带上这只火把，去毁掉你看到的每一座火炮。点燃火把就行啦！', '利用燃烧的火把烧毁东部联盟火炮和西部联盟火炮，然后返回萨尔玛向泽格·纳克布斯复命。', '我就知道!从这边我不能辨识摧毁的情形，但是我可以想象它的惨状。太棒了!$B$B做的好，$N。萨尔玛指挥官将会很高兴听到你的捷报。', '我一直在找火炮被烧毁的明显迹象-燃烧的烟云或者着火的邪兽人的哀号声……$B$B你的任务成功了吗?', '', '去地狱火半岛找萨尔玛的泽格·纳克布斯。', '烧毁东部火炮', '烧毁西部火炮', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10091, '灵魂装置', '啊！他们一直在拷问我，想让我吐露所有的秘密。$B$B我屈服了……他们竟然将别的间谍喂给赫尔默吃，还说我就是下一个。但是我没有泄露任何重要的信息！$B$B这帮疯子！他们试图召唤自己根本无力控制的恶魔力量！$B$B他们利用某种特殊的装置制造灵魂碎片，以此强化召唤能力，你必须偷走这些装置！$B$B我原本打算和你一起去的，但我必须先返回沙塔斯城，向贫民窟的间谍女王报告。', '偷取5个灵魂装置，将它们交给沙塔斯城圣光广场的间谍女王梅丽萨·海克隆。', '吐刚先前才来这里将他的报告交给我。他应该和你一起留下帮忙的!$B$B我派他出去协助葛瑞克萨了。我想他们会是很适合的一对。$B$B所以，这些就是暗影议会用来提升他们召唤力量的灵魂仪器?它们看起来很危险 - 或许占星者能好好利用它们?$B$B来，选择一个做为奖励，这是你削弱暗影议会在迷宫的运作应得的。', '嗯恩?我能为你做什么呢，$C?', '', '去沙塔斯城找圣光广场的间谍女王梅丽萨·海克隆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10095, '深入迷宫', '暗影议会两年前召唤出的庞然大物已经摆脱了他们的控制！那场召唤仪式导致了奥金顿大爆炸，并由此形成了白骨荒野。$B$B这只名叫摩摩尔的生物想要颠复暗影议会，逃离奥金顿，在我们的世界重获自由！$B$B沃匹尔大师和暗影议会的其它领袖都已经丧命，现在只有你能消灭那只怪物了，你将是外域唯一的希望！$B$B$N，你应该很清楚，你和你的同伴绝不能失败！', '杀死摩摩尔，然后返回沙塔斯城的圣光广场，将暗影迷宫的秘密告诉间谍女王梅丽萨·海克隆。', '摩摩尔已经快要获得自由了?!他们已经控制它两年了……我怀疑是什么使他们在这么久的时间后失去对它的控制?$B$B$N，打倒那个怪物你就能拯救我们所有人!我不禁害怕要是那怪物获得自由了，那沙塔斯城及外域其它地方会变成怎样!$B$B我很高兴你帮我们取得了事情的掌控权并对付奥齐顿的暗影议会威胁。我们要怎么奖励你呢?', '$N，你从暗影迷宫带回了什么消息阿?', '', '去沙塔斯城找圣光广场的间谍女王梅丽萨·海克隆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10096, '拯救孢子人', '伊卡因反复跟我描述他在洞穴中的遭遇，真是恐怖的经历！$B$B或许我们应该帮帮那些可怜的孢子人。伊卡因说他们原本居住蘑菇洞中，最近却被沼泽生物侵占了家园。$B$B转至西南方的蘑菇洞，帮孢子人干掉一些沼泽生物怎么样？', '杀死10个沼泽掘泥者和10个沼泽潜伏者，然后向塞纳里奥庇护所的劳兰娜·萨维尔复命。', '太好了!那些沼泽怪物们没有权利去侵犯斯柏路克的家!$B$B要是这些生物们能够学着和平共处会更好，不过那是不可能的，所以我们会在这关切情况!$B$B这里，请从中挑选一样做为你提供帮助的酬谢。', '什么?这么快就回来了?变怎样了?', '', '去赞加沼泽找塞纳里奥庇护所的劳兰娜·萨维尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10097, '兄弟反目', '塞泰克在奥金顿爆炸后便离开了斯克提斯，此事的起因源于我们的主人终将降临的预言。$B$B我的兄弟塞斯是他们的领袖之一，他说我们必须进入神庙遗迹，迎接我们的神。$B$B我们在神庙废墟创建了定居点，并将它命名为塞泰克大厅；但这时，我对塞斯和他的盟友艾吉斯起了疑心。$B$B不久，塞斯就将我逐出塞泰克大厅，但是他拒绝让我带走我的妹妹拉卡。你愿意帮我救出她吗？', '进入塞泰克大厅，杀死黑暗编织者塞斯，然后解救被囚禁的拉卡。完成任务后向塞泰克大厅外的伊斯法尔复命。', '我没办法充分表达出我的感谢，$N。知道拉卡已经获得自由表示我能够斩断与塞泰克剩下的关联了。$B$B一部份的我对于希斯的死无法原谅我自己，但却不得不这么做。在我到达司凯堤斯后，我会为他举行葬礼。也许他的灵魂会在为将我们人民误导入歧途这件事赎罪后找到安息。', '你有找到她吗，$N?她还被扣留在大厅里吗?', '', '去泰罗卡森林找白骨荒野的伊斯法尔。', '', '解救拉卡', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10098, '泰罗克的传说', '我的族人崇拜一位名叫泰罗克的远古英雄。小鸦人听着他的故事长大，幻想能拥有他那样漂亮的羽毛。$B$B他曾与族人们共同生活达数百年之久，却在某一天突然神秘消失，只留下了他的面具、羽毛和手稿。$B$B鸦人氏族非常珍视这些圣物。当塞泰克从斯克提斯分裂出去时，他们掳走了这几件东西，我们为此心碎不已。$B$B对于塞泰克大厅的情况，我只是略知一二，不过我把它们都写下来了，应该对你有些用处。', '将泰罗克的面具、泰罗克的羽毛和泰罗克的传说交给塞泰克大厅外的伊斯法尔。', '我也许永远都无法原谅自己在这场塞泰克的罪行中所扮演的脚色，但也许透过归还泰洛克的遗物这件事，我可以开始解放我自己。$B$B感谢你在这件事上的帮忙，$N。你不知道今日你所做的事是有多么的重要。', '泰洛克的遗物已经从司凯堤斯离开太久了。你能把他们从塞泰克带回来吗?', '', '去泰罗卡森林找白骨荒野的伊斯法尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10099, '主谋', '那些可恶的甘尔葛仍然在不断地涌入矿井！你刚杀掉一个，马上就会又出现更多！$B$B一定有人在矿井的最深处指挥着这次入侵。上一次的战斗中你表现非常出色，圣光告诉我，恐怕你是唯一一个敢于深入矿井探险的勇士了。拜托你，找出这次入侵事件的指挥者，让他付出应有的代价！', '进入荣耀堡的地下矿洞，找到并杀死兹克拉，然后向工头比格姆斯复命。', '我很开心你试着去处里这个，这个……你说他叫他自己什么来着?希卡洛?$B$B从你的描述中，听起来比较像是“它”而不是“他”不过无论怎样结果就是它死了。', '我几乎不敢问。看到你安好的从矿坑里走出来代表着有两种可能:要不就是你杀了那怪物，要不就是你失去了你的胆量。那么，是哪一个呢?', '', '去地狱火半岛找荣耀堡矿洞的工头比格姆斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10106, '地狱火半岛的工事', '地狱火堡垒与我们的军队一直有着小规模的冲突与交战。当前，我们自己的领地大多守备稳固，但一直没能对他们发动真正的进攻。为了筹备进攻，我们要首先占领地狱火堡垒外围的战略要地。$B$B我们的斥候当前确定了三处互成犄角之势的工事，希望你能协助这三处的防守。占领所有工事之后回来向我报告。$B$B愿你能在接下来的战斗中有好运气，$N，毫无疑问，你得面对部落的威胁，他们也同样想占领这三处重要的工事。', '占领了望台、竞赛场和碎石岭，然后向地狱火半岛上荣耀堡内的委任官翠希·普罗维尔复命。', '做的好，$N。你这次的行动有助于我们在地狱火半岛的战斗。', '$N，等你协助完每一个堡垒的占领行动后回来找我!', '', '去地狱火半岛找荣耀堡的委任官翠希·普罗维尔。', '占领瞭望台', '占领竞赛场', '占领碎石岭', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10109, '我想要这些鸟蛋！', '瞧见那些鸟蛋了吗？以口臭的加兹鲁维的名义发誓，我一定要搞到这些蛋！唔，你看上去很能打的样子。$B$B$r，如果你能为我收集一样东西，等我调试好超级蹦床4000型，我就送你一把启动这玩意的钥匙！你想知道超级蹦床4000型有什么用处？有了这宝贝，你几乎什么都能做……$B$B我要你从纳格兰的大气元素身上收集气元素实体。别跟我说你找不到气元素，它们遍布整个纳格兰！', '将3份气元素实体交给纳格兰南部氏族岗哨对面的瓦萨特。', '太棒了!现在只要些许的调整这个东西就会像新的一样棒了。喔对了，你的钥匙!拿去吧。$B$B顺带一提，这个装置还是有一些技术性问题需要解决。呃，小心一点就是了。', '拿到气体了吗?', '', '去找纳格兰的瓦萨特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10110, '地狱火半岛的工事', '在我们的故乡肆虐的所有地狱火堡垒邪兽人都必须要消灭干净！但要想攻击地狱火堡垒，我们必须首先占领堡垒外围的几处战略要地。$B$B巡逻队发现有三处工事正好适合我们的目的。但联盟竟与我们不谋而合，现在已经派出部队占领了那里！$B$B我要求你立刻阻止联盟的行动，并占领这些工事。协助我军占领工事之后，立刻回来向我报告。$B$B为了部落！', '占领了望台、竞赛场和碎石岭，然后向地狱火半岛上萨尔玛的传令官布莱肯·黑眼复命。', '做的好，$N。我几乎可以听到在那些堡垒战斗的声音。我真希望在那里看见他们!', '在你协助占领完每一个堡垒后回来找我吧!', '', '去地狱火半岛找萨尔玛的传令官布莱肯·黑眼。', '占领瞭望台', '占领竞赛场', '占领碎石岭', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10111, '给我鸟蛋！', '你已经拿到了钥匙，现在我要你从树上给我取一枚鸟蛋来！使用超级蹦床4000型跳上鸟巢。要小心！跳得不好的话难免会受伤流血，甚至可能永久残废呢。', '纳格兰的瓦萨特要你利用超级蹦床4000型从附近树上的鸟巢中偷取神秘的鸟蛋。', '嗯，这不是蛋……嘿!我也爱鸡!我只要拿菜刀从它的鸡爪中间切下去就可以了!感谢你!', '我有跟你说我对蛋的爱恋程度吗?', '', '去找纳格兰的瓦萨特。', '尝试偷取鸟蛋', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10112, '私人事务', '嗯？你说的是一盒东西？还是好几盒？你知道盒子是用什么材制成的吗？$B$B还有，这名商人叫什么来着？埃博尔？你确定他是个破碎者吗？我跟破碎者很少有贸易往来。$B$B如果你能帮我个忙，我或许能想起点什么。$B$B基斯鸦人是一群远古的施法者，最近他们从我这儿偷走了一批珍奇的货物。我要找回那批货物！$B$B基斯鸦人就聚集在沙塔斯城以南的基斯鸦巢。', '将5箱拉斯莱的货物交给沙塔斯城贫民窟天涯旅店附近的星界商人拉斯莱。', '是的，没错，我真的确定现在都想起来了。$B$B而我认为你在这件事上的努力值得比得到你所需要的消息来的更多。', '嗯，我的记忆有增进吗?', '', '去沙塔斯城找贫民窟的星界商人拉斯莱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10115, '匕潭的威胁', '库雷尼人和德莱尼人常常会出现意见分歧，尤其是在对待失落者的问题上。我们乐意去帮助那些向我们求助的失落者，但不会主动伸出援手。德莱尼人则想要使所有的失落者得到“救赎”。$B$B但是，某些失落者部族已经偏离了正道，例如匕潭失落者。此地西边就是他们的村落，匕潭失落者滥用毒药、善于欺诈，他们的恶行已经到了难以容忍的地步。$B$B我们必须好好教训这帮渣滓，不能任由他们胡作非为。', '杀死3个匕潭刺客和15个匕潭泥居者。', '你做的很好，$N。匕首沼地者远在任何的正常规范之外，不过我不确定德莱尼会在这状况中适当的采取行动。', '你有看到这些匕首沼地者做了什么吗?现在你了解为什么我们必须将他们与其它失落者隔离了吧。', '', '去赞加沼泽找奥雷柏尔营地的伊库提。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10116, '通缉：穆玛基酋长', '通缉：穆玛基酋长！邪恶堕落的匕潭部族首领因对奥雷柏尔营地犯下的罪行而被通缉。$B$B穆玛基和他的同党必须为数起谋杀库雷尼和德莱尼的行径付出代价。只有经验丰富的勇士才能击败他。$B$B旅行者应该尽量避免在奥雷柏尔营地西边的匕潭村区域行走。$B$B领取奖赏者必须向伊库提出示足以证明自己杀掉穆玛基酋长的证据。', '将穆玛基酋长的图腾交给奥雷柏尔营地的伊库提。', '太棒了!有许多人想要领取这份奖赏，但都没有回来过。不难了解他们发生了什么事。\r\n\r\n我很放心我们不用再被姆玛奇及他的堕落所困扰了。', '你想要领取姆玛奇酋长的奖赏吗?', '', '去赞加沼泽找奥雷柏尔营地的伊库提。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10117, '通缉：穆玛基酋长', '通缉：穆玛基酋长！邪恶堕落的匕潭部族首领因对萨布拉金犯下的罪行而被通缉。$B$B穆玛基和他的同党必须为数起谋杀信使和斥候的行径付出代价。只有经验丰富的勇士才能击败他。$B$B旅行者应该尽量避免在萨布拉金西北边的匕潭村区域行走。$B$B领取奖赏者必须向暗影猎手德恩加出示足以证明自己杀掉穆玛基酋长的证据。', '将穆玛基酋长的图腾交给暗影猎手德恩加。', '你拥有我的感激，$N。我都已经开始打算我必须自己带领大批的军力去那里解决掉姆玛奇。当然，就没有办法知道之后萨布拉金会发生什么事了。$B', '你想要领取姆玛奇酋长的奖赏吗?', '', '去赞加沼泽找萨布拉金的暗影猎手德恩加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10118, '警告匕潭失落者', '在赞加沼泽的所有失落者部族中，匕潭失落者以狡猾和侵略性着称。他们的组织性极强，从不掩饰想控制沼泽地中其它失落者的野心。$B$B死在他们手中的斥候和信使已经不计其数，我再也经不起任何人员伤亡了。$B$B如果我们不赶快采取行动的话，他们就会完全控制萨布拉金附近的所有通道。', '杀死3个匕潭刺客和15个匕潭泥居者，然后返回萨布拉金向暗影猎手德恩加复命。', '我认为你可以试着传送一则相当强烈的讯息给他们。也许现在，剩下的其它人就不会如此害怕与匕首沼地者对战。或者，要是他们会怕，他们会因缺乏勇气而觉得羞耻。', '匕首沼地者唯一了解的事就是快速又残暴的攻击。他们应该知道我们不会让他们任意妄为。', '', '去赞加沼泽找萨布拉金的暗影猎手德恩加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10120, '抵达外域', '我手下的部队当前在联盟的帮助下正坚守着这里的防线，不过，我需要你帮助我送一份报告到萨尔玛去，递交给克拉库克将军。有了他的帮助，我们就可以把这些恶魔一扫而空，彻底赶回他们的深渊老家去！跟后面平台上的维拉加·乱羽谈谈吧。她会送你尽快过去的。', '地狱火半岛上黑暗之门旁的沃雷恩中将要求你将沃雷恩的报告交给维拉加·乱羽。', '所以你是欧莱恩新的传令员吗?我祈祷你的遭遇会比上次他派来的那个好一点，$C。随着军团的逼近，你绝对没有办法徒步送回萨尔玛的。说吧，我的双足翼龙会将你安全送达那里。', '我看到你在跟欧莱恩谈话 - 一定是很重要的事吧……', '', '去地狱火半岛找命运阶梯的维拉加·乱羽。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10123, '魔火峡谷', '末日领主卡扎克是外域一带燃烧军团的最高指挥官。虽然我们现在还没有办法直接去挑战卡扎克，但我们可以先斩除他的左臂右膀——那些燃烧军团的高级军官。$B$B当前，有一队恐惧魔王驻扎在东边的魔火峡谷，他们负责指挥和制造那些在我们头顶上飞来飞去的地狱火。去干掉他们和他们的手下，燃烧军团会因此受到重创。', '萨尔玛东侧补给车队的斯古尔·碎颅者中士要求你杀死4个唤火小鬼、6个地狱火战争使者和1个恐惧召唤者。', '表现的太好了，士兵。攻击的频率一定会减低 - 至少在他们招来更多的惊惧领主前。$B$B现在有个坏消息:我收到了有关你的最新命令……', '只要秘法师和他的血法师们持续在前线，萨尔玛就安全了。', '', '去地狱火半岛找补给车队的斯古尔·碎颅者中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10129, '任务：穆尔凯斯和沙德拉兹之门', '我们已经找到了燃烧军团当前所使用的两条运输增援军的主要线路：穆尔凯斯和沙德拉兹之门。$B$B如果你沿着荣耀之路一直向西走，就可以在路边看见它们了。而我要你做的，就是把它们都给我炸上天！$B$B这是你要用的炸弹，是我请52区的一个地精技师特别设计的。现在，去和空军指挥官布拉克谈一谈，他会给你配置一只双足飞龙的。', '与空军指挥官布拉克谈谈，轰炸穆尔凯斯之门和沙德拉兹之门，然后向机甲残骸处的前线指挥官托尔克复命。', '他们需要数周的时间才能恢复!了不起的工作，$N。燃烧军团从未预期过如此严重的反击。', '假如你在第一次操作的时候失败了，这里是第二个炸弹……', '', '去地狱火半岛找机甲残骸的前线指挥官托尔克。', '摧毁穆尔凯斯之门', '摧毁沙德拉兹之门', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10132, '巨人的威胁', '你看见北边那块巨大的红色水晶了吗？那是不久前从空中掉下来的，还引起了这周围的大规模地震。$B$B后来，我们过去调查它的时候，发现有许多以前从未见过的巨人徘徊在四周。$B$B这块水晶一定有古怪，它散发出的能量也非常奇异。但是，我没有时间去处理这件事情，我必须时刻提防着那些山丘巨人。$B$B如果可能的话，我希望你能带上你的朋友们，一起去坠星山帮我解决掉那些山丘巨人。', '杀死5个暴怒的巨人，然后返回地狱火半岛的塞纳里奥哨站，向图拉希恩复命。', '做的好。$B$B假如你问我，所有我们必须做的是杀死足够的那些戈罗西，然后我们就不必再担心那片山脊或位在山脊中间的那颗奇怪水晶。$B$B来，从这些物品之中选取一个作为塞纳里奥远征队送给你的礼物。', '你已经消灭了这个巨大的威胁了吗?', '', '去地狱火半岛找塞纳里奥哨站的图拉希恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10134, '火红水晶中的线索', '当这个巨人在你面前缓缓倒下时，突然一小块水晶碎片从它身上掉了下来。$B$B尽管这块碎片映衬在山丘巨人那庞大身躯旁是那么的渺小，但你还注意到了它。拾起它之后，你感到它非常的沉重。似乎它是从坠星山那块巨大的水晶上的散落下来的碎片。$B$B这显然是一个线索，能使大家了解清楚这里为什么会发生那么多奇怪的事。你认为南边塞纳里奥哨站的德鲁伊一定会想研究研究这块碎片。', '将火红水晶碎片交给地狱火半岛塞纳里奥哨站的图拉希恩。', '嗯。对我来说，看起来就像是一大块尚未提炼的水晶。$B$B我能清楚的感觉到它散发出一股令人厌恶、邪恶的气息，但那究竟不在我职责的范围内。我到这里是来结束山岳巨人的威胁的。', '你手中的水晶还真大。那是你到山脊杀死戈罗西时得到的吗?$B$B让我看看。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10136, '阿拉修斯的意图', '魔导师文森特·血鹰破译了你之前找到的燃烧军团信件。看来这份计划书是卡扎克麾下的军官阿拉修斯所拟。很明显阿拉修斯统领着燃烧军团部署在地狱火半岛的陆军。是时候解决这个麻烦了，$N。用武力去结束这一切。$B$B到西边的阿苟纳之池去，干掉这个所谓的“燃烧军团领主”。今天，部落将要夺回地狱火半岛，让燃烧军团见鬼去吧！', '除掉残酷的阿拉修斯，然后返回萨尔玛向纳兹格雷尔复命。', '将来部落的后代们，会流传歌颂今日发生的壮举，$N-关于你英勇事迹的歌曲。我希望萨尔可以在这边跟我们一起庆祝。燃烧军团已经玩完了-而地狱火半岛如今再次回到我们部落的手中啦!这个充满破坏与蹂躏的世界看起来还是存有希望-而我们部落在其中还可以拥有一席之地。$B$B为了部落!', '命运来的时候谁都挡不住，$N。残忍的阿拉萨尔斯已经逃避他的命运够久了。把他的死讯告诉那些胆敢反抗部落之人。而你就是下一个。', '', '去地狱火半岛找萨尔玛的纳兹格雷尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10140, '荣耀堡之旅', '如果你准备好了的话，我就要为你安排一次直接到荣耀堡的飞行了。$B$B到了那边以后，和伊斯多尔元帅谈谈，然后把杜隆的报告交给他。看到又一位来自故乡的新兵，他一定会很高兴的。而且，我得说，这份报告也非常重要！', '乘座狮鹫转至荣耀堡，将杜隆的报告交给伊斯多尔元帅。', '我们对这个被遗弃，残破的世界的远征已经几乎裹足不前了。$N。我们遇到了超乎我们估计的阻碍。$B$B好像我们单单对抗燃烧军团的处境还不够恶劣一样-这片土地上还存在着我们以前从未遇过的邪恶事物。', '感谢圣光你安全的将它送达这里。荣耀堡需要集合所有经验丰富的战士。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10142, '苦痛之路', '末日领主卡扎克指挥着外域所有的燃烧军团部队。当然，我们当前还不能直接和卡扎克对抗，但我们可以——而且必须——开始铲除他军团中的军官，彻底扰乱他们的指挥体系。$B$B他们在东边的苦痛之路派驻了一批恐惧魔王。正是这些恐惧魔王负责着在我们头顶上不停地降下地狱火之雨。立刻清除他们，还有他们的手下，这样燃烧军团就将遭受重大的损失。', '荣耀堡外面的东补给车队的沃图姆斯中士要求你杀死4只唤火小鬼、6只地狱火战争使者和1只恐惧召唤者。', '杰出的表现，士兵。他们攻击的频率必定会降低 - 至少直到他们运送新的惊惧领主前来战线。$B$B现在宣布坏消息:我要下新的命令给你……', '只要弓箭手看守着我们的领空，荣耀堡就会很安全。', '', '去地狱火半岛找东补给车队的沃图姆斯中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10144, '阻断援军', '你从这里一直向西北方走，就可以到达军团前线。那里部署着许多通向外域各地的传送门，使这里的燃烧军团能够随时得到增援。$n，我们决定摧毁所有的传送门！$B$B带上这捆雷管，它是由52区的技师设计的，可以利用恶魔自身的力量产生强大的爆炸！首先你要杀死格雷姆传送门和凯勒兹传送门旁边的那些军团士兵，收集他们身上的恶魔符文石，然后在传送门内使用雷管去引爆这些符文石……接下来，我们就可以看烟火表演了！！$B$B快去吧，$n，完成任务之后向我复命。', '消灭格雷姆传送门和凯勒兹传送门附近的敌人，收集它们身上的恶魔符文石。$B$B然后在格雷姆传送门和凯勒兹传送门内使用金斯顿的雷管。$B$B完成任务后，将剩馀的炸药还给前线指挥官金斯顿。', '做的好，$N。瘫痪那些传送门将会好一段时间的切断燃烧军团源源不绝的援军!$B$B但是我们还不能休息……', '真希望我能到那里观赏烟火展示。那些爆裂物的威力强大!', '', '去地狱火半岛找远征军岗哨的前线指挥官金斯顿。', '破坏格雷姆传送门', '破坏凯勒兹传送门', '摧毁军团感应器：湮灭', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10146, '任务：穆尔凯斯和沙德拉兹之门', '就在黑暗之门的西边，有两处巨大的传送装置，它们分别被称作穆尔凯斯之门和沙德拉兹之门。$B$B如果你沿着荣耀之路一直向西走，就可以在路边看见它们了。而我要你做的，就是把它们都给我炸上天！$B$B这是你要用的炸弹，是我请52区的一个地精技师特别设计的。现在，去和空军指挥官达比利谈谈吧，他会用狮鹫把你一路送过去的。', '与空军指挥官达比利谈谈，轰炸穆尔凯斯之门和沙德拉兹之门，然后向远征军岗哨的前线指挥官金斯顿复命。', '毫无疑问的，那将减缓他们的行动!我想你让我的心情变得异常的好，$N!', '这是个非常重要的任务，$N。是个我不会轻易相信随便任何人的任务。', '', '去地狱火半岛找远征军岗哨的前线指挥官金斯顿。', '摧毁穆尔凯斯之门', '摧毁沙德拉兹之门', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10159, '扫清棘牙岭！', '我们当前正为扫清那些棘牙岭的掠食者而战。毕竟，如果我们这里与赞加沼泽庇护所之间的联系被完全切断，事态就太过糟糕了。$B$B其实，我们并也不想将这些生物全部赶出家园，但它们经常袭击这里的旅行者，而且最近变得越来越具备攻击性，因此，我们已经没有其它选择了。$B$B如果你愿意帮忙的话，就太好了。', '杀死8只棘牙掠食者和8只棘牙喷毒者，然后返回地狱火半岛的塞纳里奥哨站，向玛霍拉姆·硬蹄复命。', '随着劫毁者被清除了，那些往返于赞加沼泽上塞纳里奥避难所的旅人应该会比较轻松了。$B$B塞纳里奥远征队感谢你。', '你去清理棘牙丘陵的这件事进展得如何?', '', '去地狱火半岛找塞纳里奥哨站的玛霍拉姆·硬蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10161, '以防万一……', '身为一名飞艇的艇长，在遇到紧急情况时，特别是当你的副驾驶只愿意服从来自胃部的命令时，你必须要保持头脑的冷静。$B$B比如现在，我就很冷静。我这里有一个好消息和一个坏消息，好消息是我们不必等待好几天才有替换零件可用；坏消息呢，就是我们的“备用零件”从这里一直散落到了东边的白骨之谷。$B$B啊，还有没有其它的坏消息？ 好吧，简单来说，备用零件已经没有了。嗯，对，在我们迫降的时候，零件全都掉落出去了。你能帮我把它们收集回来吗？这样我们就能把这玩意给修好了。', '将30块飞艇碎片交给飞艇坠毁点的“尖嗓子”斯克里·拉克希德。', '这些零件有的歪七扭八的，但是应该足够这里使用了。随着一些充满创意的工程，我有自信能够让它起作用!', '你找到足够的零件了吗?如果没有，我可能得使用那个雷噶西一直在附近挥舞的平底锅。接着，我必须将飞艇重新命名为＂飞行平底锅″。', '', '去地狱火半岛找飞艇坠毁点的“尖嗓子”斯克里·拉克希德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10162, '任务：地狱岩床', '既然你现在已经可以飞行了，或许你会对另一个轰炸任务感兴趣？$B$B我们已经孤立了燃烧军团的主要生产区域，就在铸魔营地的正北方。而你要做的事情，就是乘坐双足飞龙去那里，炸掉那些该死的东西！$B$B这是给你的炸弹——当你准备好了的时候就去跟空军指挥官布拉克谈一谈。', '地狱火半岛机甲残骸的前线指挥官托尔克要求你杀死20个甘尔葛苦工和5个莫尔葛监工，并摧毁5门邪能火炮。', '你做得好像你一辈子都在飞行一样，$N。表现很杰出!双足翼龙毁灭者的身上甚至连一道抓痕都没有!', '让他们知道不只有领空是安全的!', '', '去地狱火半岛找机甲残骸的前线指挥官托尔克。', '', '', '摧毁邪能火炮', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10163, '任务：地狱岩床', '既然现在你也能够很熟练地飞行了，也许你还想再来一次轰炸任务？$B$B我们已经孤立了燃烧军团的主要生产区域，就在铸魔营地的正北方。我要你马上骑着狮鹫去摧毁这些该死的东西！$B$B拿上你的炸弹，准备完毕之后就去找狮鹫骑士维比洛吧。', '地狱火半岛破碎岗哨的空军指挥官格莱芬加尔要求你杀死20个甘尔葛苦工和5个莫尔葛监工，并摧毁5门邪能火炮。', '你做得好像你一辈子都在飞行一样，$N。表现很杰出!狮鹫兽毁灭者的身上甚至连一道抓痕都没有!', '让他们知道不只有领空是安全的!', '', '去地狱火半岛找破碎岗哨的空军指挥官格莱芬加尔。', '', '', '摧毁邪能火炮', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10164, '一切都会变好的', '$N，看来你有着丰富的冒险经历，甚至进入过奥金尼地穴探险。$B$B我是个幸运的幽灵。我既没有沦为利维休斯的仆从，也没有成为大大主教玛拉达尔那罪恶的通灵术实验中的牺牲品。尽管你杀死了利维休斯，玛拉达尔却还活着，继续折磨着地穴中痛苦的灵魂。$B$B我希望你做的事很简单。进入奥金尼地穴杀死大大主教玛拉达尔，让那些被禁锢的灵魂得以安息。', '奥金顿奥金尼地穴外的奥德里姆斯宗父要你进入奥金尼地穴，消灭大大主教玛拉达尔。', '你做到了，$N!灵魂被释放了!$B$B虽然我没有一个物质上的表示，但我仍然能以来自精灵世界的物品奖赏你。小心使用，像这样的物品经常是具爆炸性且能更使它们的用户受到重大伤害。', '拯救那些灵魂，$N。', '', '去泰罗卡森林找奥金顿的奥德里姆斯宗父。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10165, '扫除竞争者', '沙法尔真是个精明的家伙，我一定要治治他……星界社团只能眼睁睁地看着他将墓穴里值钱的东西劫掠一空。$r，瞧瞧我手下的这帮蠢材，他们根本无力突破沙法尔的防线，不如我们来做笔交易吧。$B$B进入法力陵墓，杀死节点亲王沙法尔。带回沙法尔的护腕带，做为你杀死他的凭证。我不会亏待你的。', '法力陵墓外的节点亲王哈拉迈德要你杀死节点亲王沙法尔，并将沙法尔的护腕带交给他。', '另一个竞争者消失了……你为了一个噬尸兽做了一件好事，$r。如果你来虚空风暴，来拜访我。我就住在风暴之尖。', '我不喜欢『分享』。', '', '去泰罗卡森林找白骨荒野的节点亲王哈拉迈德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10166, '怀特巴克的记忆', '这件坠饰让我想起了那段非比寻常的岁月，真是一段美好的时光……$B$B可惜现在我已经不需要任何回忆了。$B$B让这件坠饰和回忆都埋入焦痕谷的符石吧。我就是在那儿遇见那位树人长者的。让所有关于这位故人的回忆都一起埋葬了吧。', '拉莉亚娜·河风要你将怀特巴克的坠饰放在焦痕谷的符石上。', '我已经不再属于这个世界了，而且必须承认失败。这片土地已经永远改变了，没有什么会是永远不变的。$B$B把这个墬饰留在这里给我吧，$N。也许有一天，在精灵们消失很久以后，一颗新生之树会在这个特别的地方生长 -', '你回来了，$N。你做得还不够吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10167, '奥金顿……', '奥金尼地穴深处有一座坟墓。破碎的外域随处都可以看到墓穴，惟有这座坟墓与众不同。奥金顿的陵墓群就起源于这座墓穴。$B$B进入奥金顿的奥金尼地穴，找到这处坟墓。杀死墓穴的守卫，解救出被关押在墓穴中的灵魂。那个灵魂就是一切的关键……', '转至泰罗卡森林白骨荒野的奥金尼地穴，杀死大大主教玛拉达尔，解救德欧里的灵魂。', '记忆是生动的，$N。我的能量完全被爆炸吸收。当预言者费伦和他的德莱尼同胞抬起我的遗体并且将它们带来这里时，我只是一个暗淡少量的虚无能量。在经过许多仪式之后，我那变小的身体被埋葬在这个石棺内。我花了差不多一千年一直在重生。循环过程几乎完成了……', '<迪欧瑞的鬼魂哼了几下。>$B$B你好啊，$N。', '', '去希尔斯布莱德丘陵找达隆山的德欧里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10168, '灵魂之眼', '数百年来，无数奥金顿的灵魂被卷入了我体内黯淡的精华之中，我的能量一直不断衰竭，奥金尼地穴也因此频发灾难。$B$B很遗憾，没有什么能阻止这个循环。这便是纳鲁生命的轮回——没有虚空，圣光也不可能存在。$B$B惟一的挽救措施就是在纳格兰的兽人灵魂堕落为虚空生物之前消灭他们。这座墓穴中的灵魂之镜可以搭救他们……', '在奥金尼地穴中找到一面灵魂之镜，用它召唤纳格兰上古兽人先祖的黑暗之魂。消灭15个黑暗的灵魂，让兽人先祖得以安然长眠。$B$B完成任务后，向先祖之地的卡舒尔宗母复命。', '你已经完成了一次又长远又危险的旅行，冒着生命危险去确保玛格汉的安全和我们祖先的宁静。对此我不知道要怎么表达我的感谢。', '<族母卡修尔看起来很生气。>$B$B这些纳鲁远比世界上所有形态的生命还要聪明。', '', '去纳格兰找先祖之地的卡舒尔宗母。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10169, '镇静剂', '奥尔多如今看来是得到沙塔尔的恩宠了。怎么说好呢，这真是意料之外，情理之中。$B$B看吧，他们竟然在离阿达尔那么近的地方炫耀着他们的队列操演。除了拍纳鲁的马屁，他们还能干点别的正经事吗？$B$B先驱者哈隆奈姆的火枪手中队未免也太认真了点，居然因为担心午饭时间过长耽搁了操练，把自己的锅都给带来了。我们可不能放过这个机会，得给他们点颜色看看，$N。$B$B我要你把这个瓶子里的东西倒进他们的饭菜里。这样一来，结果可就……有趣了。', '沙塔斯城内的魔导师法尔里斯要求你将一瓶镇静剂带去圣光广场，倒入射手队的烹饪锅内。', '奥多尔神射手似乎被他们的训练分布注意力，让你有充裕的时间将药水放进炖菜里。', '这些药草跟香料的香味充满着锅炉周围的空气中。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10172, '毫无希望', '$N，你是一位可敬的$r。你给予了玛格汉氏族太多的帮助，没有谁能否定你为我的子民所做的一切。唉，玛格汉氏族的历史已经划上了句号。事实证明，我并不适合做氏族的领导者。我的体内涌动着被诅咒的血液。我不能……不能像我的父亲那样，被堕落之血操控身心。$B$B$N，请将我的话转告给祖母。我没脸见她……我不敢看她的眼睛。', '将加尔鲁什所说的话转告给盖亚安祖母。', '<眼泪从主母吉雅的脸上流了下来。>$B$B去找你的大酋长。告诉他我在这里等他……', '<主母吉雅躺了下来。>', '与盖亚安祖母谈话', '去纳格兰找加拉达尔的盖亚安祖母。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10173, '大法师的法杖', '请允许我作个自我介绍，$C。$B$B我名叫拉文德维尔，是大法师瓦格斯的学徒。$B$B我的导师当前……暂且说是状况不适吧。我来到这里是有要事的。$B$B城东南方的阿尔科隆遗迹当前已被燃烧军团所占据，成了他们进行邪恶活动的温床。他们在遗迹里活动的目标既不是我，也不是我的导师，而是由他们的领袖埃克拉斯所持有的大法师的法杖。$B$B这份召唤粉尘可以帮你诱使那个恶魔从藏身地现身，将它撒在遗迹中心的火盆里吧。', '从审讯者埃克拉斯手中夺得大法师瓦格斯的法杖，将它交给52区的拉文德维尔。要使埃克拉斯从藏身处现身，你需要向遗迹中心的火盆喷撒召唤粉尘。', '啊，你设法取回了权杖。让人印象深刻，$N。或许你是我一直寻找的那个人。$B$B喔，是的，你的报酬……$B$B<罗樊德威将几个硬币放到你的手掌上。>$B$B毫无疑问的你期望得更多，但是那也要随着时机而来。现在，将机会当成是真正的报酬。', '直到大法师瓦戈斯之杖归还我才会休息。你可以从恶魔的手中将它抢回来吗?', '', '去找虚空风暴52区的拉文德维尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10176, '守护者阿尔凯洛斯', '你已经集齐了破除凯尔萨斯的诅咒所需的物品，要做的事情仅剩一件了。凯尔萨斯封印紫罗兰之塔时，将一个名叫阿尔凯洛斯的奥术傀儡留在了塔楼顶层。$B$B你必须击败阿尔凯洛斯，让我恢复塔内的魔法系统。$B$B当你进入紫罗兰之塔的那一刻起，凯尔萨斯的诅咒就会在你身上生效。$B$B击败阿尔凯洛斯之后，你要登上塔楼，协助我准备仪式。', '进入肯瑞瓦村中心的紫罗兰之塔，击败阿尔凯洛斯，然后与大法师瓦格斯谈一谈。', '你做的很好，$N。摧毁这个结界将有助于我可以更容易的解除这个塔的诅咒。', '终于，我们见面了。', '', '去虚空风暴的紫罗兰之塔找大法师瓦格斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10182, '战斗法师达斯利克', '这柄剑材质上等，锻造工艺精湛，整体质量经过平衡，非常适合战斗法师使用。剑柄上镶嵌着肯瑞托议会的徽章，还刻着“达斯利克”的名字。$B$B在手中翻转这件武器时，你注意到金属中似乎辐射出某种异样的感觉，似乎这柄剑在两个维度中迅速地切换着。难道它竟是战斗法师达斯利克的灵魂在这个世界唯一的羁绊？$B$B或许将这柄剑放回原来的位置，就能破除这羁绊，令达斯利克的灵魂得以安息。', '在巫师街内找到战斗法师达斯利克的家，将剑放回他的武器架上。然后与肯瑞瓦村的管理器戴沃斯谈一谈。', '你做的很好，$N。我不再感应到达斯立克灵魂的任何骚动。我愿意付出更多以得到再一次与他对话的机会，但他最终安息了那就够了。', '你找到什么了，$N?', '', '去虚空风暴找肯瑞瓦村的管理器戴沃斯。', '', '让达斯利克的灵魂安息', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10183, '转至52区', '我在这里潜心研究伟大的虚空——以太流以及虚空中的一切。这里真是最理想的研究点，没有刺眼的灯光，也没有镇上的喧闹。这座桥挺不错的吧？要是我能把这副破望远镜修好就更棒了。$B$B嘿，朋友，如果你想找事做的话，就去52区吧！沿着路往前走，在分岔口往右转。$B$B不如顺便把我最新的研究成果带去交给火箭主管弗斯拉格？我敢肯定他有一堆事要丢给你做，他就在X-52太空船那儿，很好找的！', '将虚空学家的笔记交给虚空风暴52区的火箭主管弗斯拉格。', '喔，卡伯尼寇斯终于决定回报他的发现了，是吗?懒惰的科学家!$B$B这是什么?$B$B<这位主管快速翻阅这些纪录好几次，明显的一脸不可置信。>$B$B他这里说到流动在虚空风暴间的狂暴虚空力量会在几个月内将所有东西都扯成碎片。$B$B这实在令我们太困扰了 - 现在我们得加快火箭船的建造时间!', '忙阿忙阿。没有时间可以浪费了!有一艘火箭船等着施工呢!$B$B你要干嘛?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10184, '狂暴的幽灵', '村中的大多数幽灵生前都是肯瑞托的法师。他们丧失了往昔的记忆，带着沉重的怨念游荡在废墟中。$B$B但是，最开始的时候并不是这样的。那场袭击后，灵魂们只是显得不太安分而已，远没有像现在这样充满敌意。时间一久，他们却变得越来越暴戾。我已经不敢靠近村子的南部了，他们恐怕连我都不会放过。请你净化法师们愤怒的灵魂，让他们平静下来吧。', '肯瑞瓦村的管理器戴沃斯要求你去肯瑞瓦村广场消灭20个被杀死的幽魂。', '<管理器戴沃斯温和的摇摇他的头。>$B$B这不是他们应得的，但却是我们能做的。', '它让我痛到了解能为我们的同胞做的太少了。', '', '去虚空风暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10185, '悲惨的命运', '血精灵将肯瑞瓦村夷为平地后，便在西北方建起了一座高大的建筑物。没有大法师的知识，我们也无从得知那座建筑物的用途。$B$B不过，有点事倒是明摆着：血精灵的活动导致饥饿的法力生物如潮水般涌入村落。它们似乎对巫师街特别感兴趣，不断亵渎着法师们的遗物。我们必须制止这群法力生物。', '杀死10个法师杀手和10个法力搜寻者，然后向肯瑞瓦村的管理器戴沃斯复命。', '<管理器看起来很沮丧。>$B$B我几乎可以预见从地平线涌出的下一波。除掉他们暂且是可行，但仍需要长久的评估。', '你有设法解决一些村庄废墟里的法力生物吗?', '', '去虚空风暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10186, '你被雇了！', '就让我成为第一个欢迎你到来的人吧，三等见习技师$N！$B$B我们正忙于一项伟大的工程——虚空火箭X-52！$B$B不过，首先我们得准备好零件和燃料，这就是你要做的事。$B$B我需要水晶——注意，是大量的水晶，我要利用这些水晶构造火箭的以太锂引擎矩阵。德莱尼人那里到处都是水晶！$B$B你可以在北边的恩卡特废墟搞到水晶！当心那些德莱尼幽灵。', '将10块以太锂矩阵水晶交给虚空风暴52区的火箭主管弗斯拉格。', '哇!看起来很劣质呢。也许我们可以将它们使用在第三引擎歧管?$B$B尽管如此，做的好，资浅技师第三级!你很快就可以变成资浅技师第二级了。', 'X-52虚空火箭看起来像是准备好可以发射了吗?我是为了我驾驶座的舒适而漫行虚空的吗?开发陌生的新世界?寻找新科技及商机?勇敢的去那些没有哥布尔去过的地方?$B$B不是的!$B$B因此，我希望你能有我给你之后的那些水晶。', '', '去找虚空风暴52区的火箭主管弗斯拉格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10188, '克拉苏斯的魔符', '多年前，在我们离开艾泽拉斯世界之前，肯瑞托议会曾授予远征军一件威力强大的神器——克拉苏斯的魔符。在我们与兽人的战争中，它的存在就是我们胜利的保障；事实上，这枚魔符还能破除禁锢我的妖术。$B$B但是，凯尔萨斯夺走了我全部的财产，并将魔符交给留驻此地的缚法者玛亚纳保管。玛亚纳若是意识到这件神器的力量，肯定不会心甘情愿地拱手相让。', '转至紫罗兰之塔西北方的法力熔炉：库鲁恩，从缚法者玛亚纳手中夺得克拉苏斯的魔符。', '阿，它就像我记得的那样尊贵。你感觉不到从它身上发出的力量吗?$B$B当然，还有很多事要做，但关于符印的交还，你拥有我最深刻的感谢。', '如果我要解开这座塔的诅咒，我就必须有那个符印。', '', '使用大法师瓦格斯的法杖投射一个大法师的影像并告知你的进度。$B$B如果你不小心遗失了大法师瓦格斯的法杖，可以向52区的拉文德维尔再要一根。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10189, '法力熔炉：布纳尔', '在来52区的路上，你大概已经发现了一座法力熔炉。那座巨大的紫色建筑物正源源不断地汲取着能量，想起来了吗？$B$B我们奉沙塔尔之命来这儿调查敌情。如果能搞到人员名册就好了。那上面记载着法力熔炉驻军的身份以及他们的计划，都是非常宝贵的信息。$B$B阿拉森上尉率领着一支弩炮队驻扎在法力熔炉：布纳尔外，他手中必定有一本名册。替我们取回布纳尔人员名册。', '52区的间谍大师萨罗迪恩要你从法力熔炉：布纳尔外的阿拉森上尉手中夺得布纳尔人员名册。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '好极了!有了这份名单我们在瞄准法力熔炉那些凯尔的部下时就可以做出适合的决定。$B$B真糟糕，我开始爱上随意杀掉他的仆从这件事。', '你拿到我要你去拿的东西了吗，$N?', '', '去虚空风暴找52区的间谍大师萨罗迪恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10190, '电池充电', '我肩负着从废墟中收集机械零件的重要任务，眼下却遭遇了电能不足的麻烦事。$B$B相位猎手——就是那些长得像法力浮龙的生物——体内充满了能量！它们漂浮在虚空中，在这座岛的边缘地带就能找到相位猎手。$B$B将电池装在充能器上，对着虚弱的相位猎手使用充能器，吸满电能后关闭它就行了。', '对相位猎手使用电池充能器，直到电池充能等级到达10。然后将它交给虚空风暴恩卡特废墟的机器人专家艾蕾。', '嘿，小心你用那个指到的东西!你已经把它的功能设定成“杀”!!!看起来你已经把电池充满电，其它的也是。这样我的机器人就可以继续运作，你帮了我一个大忙。', '你已经将电池充满电了吗?', '', '去虚空风暴找恩卡特废墟的机器人专家艾蕾。', '电池充能等级', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10191, '麦克斯米林V型活了！', '你好，$r。充能完毕，我的各项机能已全面恢复。$B$B这片废墟中散落着许多脆弱的德莱尼机械装置，我需要将它们回收。我腕部的伸缩装置配有精细的机械臂，以及最新型的可燃及助燃气体吸收泵，可以妥当地处理那些脆弱的装置。$B$B但是，盘踞在废墟中的幽灵很可能会攻击我，因此我需要你和你的朋友陪我一起进去，保护我的安全。', '护送麦克斯米林V型穿越恩卡特废墟并返回安全地带，然后与虚空风暴恩卡特废墟外的机器人专家艾蕾谈一谈。', '你做到了!你做到了!我要亲你!$B$B喔，该死……马克斯A型机器人五号又要没电了。阿还好，它还够维持到完成这个工作，那才是最重要!$B$B火箭主管夫斯拉吉会很乐意将这些德莱尼机械吊挂在X-52虚空火箭里的!那表示是对我的升等!我好开心阿，我一定要给你奖励!$B$B来，从这些里面挑一个吧。', '这么快就回来了?$B$B马克斯A型机器人五号还好吗?!', '护送麦克斯米林V型穿越恩卡特废墟', '去虚空风暴找恩卡特废墟的机器人专家艾蕾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10192, '克拉苏斯的魔法纲要', '肯瑞托议会将另一件克拉苏斯的物品也授予了远征军，就是那本名叫《克拉苏斯的魔法纲要》的法术书。书中记载了克拉苏斯掌握的全部法术，这本魔法纲要曾在战争中为我们赢得了巨大的优势。$B$B不过，在凯尔萨斯和他的军队攻陷肯瑞瓦村之前，一个试图修习通灵术的学徒偷走了《克拉苏斯的魔法纲要》。他和他的党羽为了掩人耳目，将纲要分成了数份，各自保存在他们位于镇子南部的家中。', '转至肯瑞瓦村的城镇广场，收集克拉苏斯的魔法纲要 - 第一章，克拉苏斯的魔法纲要 - 第二章和克拉苏斯的魔法纲要 - 第三章。', '<大法师瓦戈斯的影像看来像在检查这本手册。>$B$B表皮有点受损，但想想它遭遇过的事，能够保存着真是个奇迹。护送它，$N。没了这本书，我们打破塔的防御的机率就变小了。', '你把书带来了吗?', '', '使用大法师瓦格斯的法杖与大法师取得联络。$B$B如果你不小心遗失了大法师瓦格斯的法杖，可以向52区的拉文德维尔再要一根。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10193, '有价值的目标', '根据名册记载的信息来看，空间主宰和迁跃技师操纵着法力熔炉。他们负责从法力熔炉中提取一种名叫“迁跃能量”的物质，然后通过地下管道系统输送到别的地方。$B$B除空间主宰和迁跃技师外，凯尔还在法力熔炉派驻了若干名地质学家。剩下的驻军就是普通的士兵和魔导师了，应该很容易对付。$B$B进入法力熔炉：布纳尔，杀掉凯尔麾下的走狗；这必定会大大削弱他的势力。', '52区的间谍大师萨罗迪恩要你进入法力熔炉：布纳尔，杀死2名日怒空间主宰、6名日怒迁跃技师和8名日怒地质学家。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '你是个可靠的 $g家伙:小姑娘;，$N。如果还有比我杀掉凯尔萨斯的走狗更让我高兴的事，那就是找其它人来替我下手。$B$B这方法可以让我少沾点血腥。', '进行的怎样，$N?有任何消息吗?你最近为我做了什么?', '', '去虚空风暴找52区的间谍大师萨罗迪恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10197, '以假乱真', '潜入凯尔军中可不是件容易的事。我可以运用幻象术将你伪装成凯尔的追随者，不过我没法模仿这帮家伙制服上的小细节，那样的话，伪装就很可能被识破。$B$B将一件日怒长袍、一副日怒手套和一枚日怒卫士勋章带回来给我，这样就能让我的幻象术效果更加逼真。', '收集一件日怒奥术师长袍、一副日怒研究员手套和一枚日怒卫士勋章，然后返回虚空风暴的法力熔炉：库鲁恩，将它们交给卡勒迪斯·晨光。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '太好了!当我完成你的伪装，你就可以混入日怒军队而不被发现了。', '你有拿到我要的那些东西吗?', '', '去虚空风暴找法力熔炉：库鲁恩的卡勒迪斯·晨光。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10198, '收集情报', '我利用你取回的东西做了件日怒制服，并对它施放了幻象术。$B$B几分钟前，指挥官纳萨托·晨铸来到法力熔炉：库鲁恩，准备与奥术师阿尔杜尼斯会面。纳萨托随身带着一帮护卫，他们必定是准备商谈要事。潜入日怒军营，看看能不能探得这次会面的详情。$B$B啊，差点忘了。你最好离奥术傀儡远些，它们在法力熔炉中巡逻，可以看穿伪装上的幻象术。', '利用日怒伪装包进入法力熔炉：库鲁恩，偷听指挥官纳萨托·晨铸和奥术师阿尔杜尼斯的谈话。完成任务后向法力熔炉：库鲁恩的卡勒迪斯·晨光复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '法力熔炉杜罗有困难?我相信间谍大师萨洛迪恩会很想听到这个消息。我们先专注在这里的工作吧。', '窃听的如何阿，$N?你最好快一点。我已经开始坐立不安了。', '收集情报', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10199, '一点添加剂', '眼下只缺最后一种原料了，它可以让这瓶混合物发挥额外的效力。$B$B瞧见那些在岩肤劫掠者旁边游荡的虚空鳐了吗？它们的钉刺就再好不过了。替我收集一些虚空鳐的钉刺，我就能分解出其中的毒液！$B$B只要在混合物中加入这种毒液，效果肯定好得很！', '将5根虚空鳐的钉刺交给虚空风暴52区的布兹。', '哇噢!好极了，现在我们正在讨论呢!$B$B就让我拿着这些小美人们将不好的东西挤出来。这实在该做成一桶火箭燃料酒将大家狠狠的击飞!$B$B来，就让我将页岩油及这个刺毒混在一起，看看会发生什么事……', '如果我能从这些虚空鳍刺萃取出足够的毒液，我想我们会拥有有史以来最具爆炸性的燃料!', '', '去虚空风暴找52区的布兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10201, '真相大白', '这些油总算准备好了，现在我们马上准备开始进行第一次试验。这种油质量很重，看起来是一种非常好的的武器油。$B$B不过，要真正验证这一点，还是得靠专家。看到那边通缉公告旁边站着的葛雷克了吗？噢，好吧，他虽然不是一个耍笔杆子的普通“专家”，但所有的兽人都知道他耍枪的本事！$B$B将这个油的样本带去给他，让他用他的枪去试试。等他试验完之后，告诉我他觉得这个油怎么样。', '找到葛雷克，让他用枪试试油的品质。试验完成之后，向拉克妮亚报告结果。', '<你告诉瑞蔻莉雅测试的结果然后她仰头，大笑。>', '那么，你有测试的结果了吗?', '', '去泰罗卡森林找裂石堡的拉克妮亚。', '让葛雷克测试奥雷巴油', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10203, '价值连城的设备', '看见横贯52区的裂隙了吗？是我们干的！嘿嘿！<傻笑声>$B$B我们把所有的资源都用来建造虚空火箭X-52了，结果眼下出现了设备短缺的窘境。$B$B在燃烧军团进驻东南方的阿尔科隆废墟之前，我们一直在那里进行采集作业，我要你转至废墟，利用超级拆解器带回散落在废墟中的设备，把它们交给裂隙东端的首席工兵布拉斯特菲兹。$B$B三等见习技师$N，这可是你晋升的好机会，千万别放过！', '利用超级拆解器将高转速挖掘器、机械气压挖掘爪、多光谱地形扫描仪和一大车炸药带回52区。然后向虚空风暴52区裂隙东端的首席工兵布拉斯特菲兹报到。', '你一定就是那个从废墟中把所有损坏的设备都传回我们这里的人!为你喝采!$B$B我已经重新将这些设备配置到我们其它的地点。现在我们就能够藉由一项重要的命令来加速我们在这整个岛的裂缝作用!虚空火箭要马上完成!$B$B呃呃，那是之后的事。等等，你说你传了4个回来给我们吗?我只收到3个……', '这地方是不是很棒阿?而且每天都生产出崭新且奇特的东西!$B$B真是幸运，我们差点在探钻下来时毁了这座城镇。', '', '去虚空风暴找52区的首席工兵布拉斯特菲兹。', '回收高转速挖掘器', '回收机械气压挖掘爪', '回收多光谱地形扫描仪', '回收一大车炸药');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10204, '血宝石', '凯尔的魔导师已将法力熔炉使用得炉火纯青，瞬间就能汲取到大量能量。$B$B他们利用小块的血宝石碎片，从巨大的血宝石水晶中源源不断地抽取能量。$B$B转至法力熔炉：布纳尔，从日怒魔导师手中夺得一块碎片，然后用这块碎片汲取大块水晶的能量。$B$B完成任务后回到我这儿来，让我研究能量光环的效果。别担心，它所引发的任何副作用都只是暂时的。', '魔导师拉恩娜要你进入法力熔炉：布纳尔，从日怒魔导师手中夺得血宝石碎片。在较大的血宝石水晶附近使用这块碎片，然后返回52区向她复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '嗯嗯……就如同我想得一样。$B$B暴露在这种等级的原始能量下大幅扩大了我们与生俱来的魔法沉溺。$B$B我不意外凯尔因为这样而侥幸成功;基本上他所有的部下都是喝这个的。', '你调查过日怒博学者使用的那些血宝石了吗，$N?', '吸取血宝石的能量', '去虚空风暴找52区的魔导师拉恩娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10205, '星界强盗奈萨德', '必须干掉星界强盗奈萨德！我真想不通他是怎么从我的必杀技下逃生的，但是我绝不容忍他继续干坏事。$B$B灭了奈萨德，他在机甲废场的西南角建\r\n有一处小营地。$B$B$c，希望你别像我那样被他骗过了。', '杀死星界强盗奈萨德，然后返回虚空风暴52区，向虚空猎手卡尔伊复命。', '听到那个残渣终于被解决了真是松了口气。你作得很好，$N……我可以这样放肆的直呼你的名讳吗?$B$B如果你愿意的话，我有另一个任务需要完成。一个非常重要而且很明显的你应该能够轻易应付的对象。', '结束了吗?星移劫掠者尼萨德死了?', '', '去虚空风暴找52区的虚空猎手卡尔伊。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10206, '偷来偷去', '那些奸猾的虚灵和我们一样，都是彻头彻尾的机会主义者。他们渴望得到利益，我就给他们利益。但是没有人，我是说没有人，可以染指爆缸航天局的财产！$B$B南边那块机甲废场是我们的，我们没说给他们，他们不能抢！$B$B要制造出伟大的虚空火箭X-52，我们需要一切能够得到的新技术。我们必须以同样的手段回敬那帮偷东西的虚灵，这样才显得公平。$B$B不如你现在就去机甲废场，看看能不能从他们鼻子底下搞些他们的科技成果来。', '收集10件虚灵科技的产品碎片，将它们交给虚空风暴52区的维勒老爹。', '嘿嘿，以太族的混蛋!$B$B感谢你为我们带来了这三个部份，$C。我发誓我会将这些小宝贝们好好的勾在火箭内。我怀疑他们在做些什么?应该会找得很快乐吧!$B$B嗯嗯，我看看是否我可以挖出点钱来打发你。', '这么快就带着他们的技术回来罗?你最好不要只是在这扯我的后腿，$C。$B$B这里的X-52计画成功与否，就全靠你赶快将那些东西带来给我们了!', '', '去虚空风暴找52区的维勒老爹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10208, '阻断援军', '正东边是军团前线。就可以到达军团前线。那里部署着许多通向外域各地的传送门，使这里的燃烧军团能够随时得到增援。$n，我们决定摧毁所有的传送门！$B$B带上这捆雷管，它是由52区的技师设计的，可以利用恶魔自身的力量产生强大的爆炸！首先你要杀死希鲁斯传送门和科卢尔传送门旁边的那些军团士兵，收集他们身上的恶魔符文石，然后在传送门内使用雷管去引爆这些符文石，你必须亲眼看着传送门都被炸掉！任务完成后回来向我报告。', '消灭希鲁斯传送门和科卢尔传送门附近的敌人，收集它们身上的恶魔符文石。$B$B然后在希鲁斯传送门和科卢尔传送门内使用托尔克的雷管。$B$B完成任务后，将剩馀的炸药还给地狱火半岛机甲残骸处的托尔克。', '做得好!我从这里几乎还能感觉到爆炸的震动!$B$B现在，我们还有一个爆炸任务要给你……', '军团会对你带给他们的惊喜措手不及，对吧 $N?', '', '去地狱火半岛找机甲残骸的前线指挥官托尔克。', '破坏希鲁斯传送门', '破坏科卢尔传送门', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10209, '召唤者坎西恩的战利品', '接下来你必须帮我救出我的魔宠格拉修斯，它被血精灵召唤师坎西恩捉去了。在凯尔萨斯派来毁灭肯瑞瓦村的军队中，坎西恩是地位最高的魔导师之一。他将格拉修斯当作战利品，得意地在其它人面前炫耀。$B$B当然，我敢肯定这个蠢货一定尝试过强迫格拉修斯为他效力。从占卜结果来看，坎西恩就在“法力熔炉：杜隆”，你应该知道这个地方吧。', '转至位于日怒堡北部岛屿的法力熔炉：杜隆，从召唤者坎西恩手中夺回格拉修斯之石。', '<你不确定这是苦恼呢，还是这位大法师真的是在笑。>$B$B随着我的最后一个财产归还，我有了所有用来破解凯尔萨斯魔法所需要的物品。我现在就要开始执行法术了。', '你有安全的取得葛拉希厄斯之石吗?', '', '使用大法师瓦格斯的法杖与大法师取得联络。$B$B如果你不小心遗失了大法师瓦格斯的法杖，可以向52区的拉文德维尔再要一根。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10211, '圣光之城', '别拿那么多的问题去打扰阿达尔，$c。他是你所能面对的最强大的存在。$B$B你看起来有点陌生。我猜你应该很想了解一些有关这座城市的事吧？$B$B我本想亲自带你去参观这里，可我不巧需要和阿达尔讨论一些战略决策。那么我召唤一位仆从代替我去如何？希望你不会觉得这样很失礼。好，那就这样吧！', '跟随卡德加的仆从游览城市并聆听这里的历史故事。完成任务后回去向卡德加复命。', '我希望你有学到一两件有关沙塔斯的事，$N。也许需要点时间才有办法了解所有的事情。', '人的故事是短暂的，$N。而城市的故事才能长远流传。', '圣光之城', '去找沙塔斯城的卡德加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10216, '安全第一', '沙法尔手下的虚灵将我们完全隔绝在了法力陵墓外。不过我已经想好了对付他的法子。虽然我们无法从正门进入，但是陵墓内应该设有好几台传送器。$B$B我要你去替我的手下清理陵墓的通路，然后激活传送器，将我们传送到法力陵墓中。$B$B通路清理完毕后，直接激活沙法尔的房间之前那个房间中的传送器就可以了。放心吧，我不会让你白跑这一趟的……', '工匠莫法鲁斯要你杀死10个虚灵盗墓者、5个虚灵巫师、5个节点盗贼和5个虚灵缚法者。$B$B全部搞定之后，激活沙法尔房间的前一个房间中的虚灵传送器。', '<你闭上了眼睛按了一个钮。>', '这个装备有上百个按钮，没有一个你看的懂得。', '', '去找希尔斯布莱德农场的虚灵传送器控制台。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10218, '别人的烂摊子', '你以为是谁！？莫法鲁斯那个饭桶已经被“降职”了，现在由我来处理他留下的烂摊子。我只有一件事需要你帮忙，在我从沙法尔的灵体收集器中收集灵体能量时保护我。如果我顺利完成使命的话，哈拉迈德会亲自奖励你的！$B$B怎么样？护送我穿越法力陵墓并收集这些令人目瞪口呆的宝藏，听起来如何？你看，你已经完成大部分的工作了！我们身后已经没有活的东西了，不是吗？', '护送低温工程师沙赫恩穿过法力陵墓，在他从沙法尔的灵体收集器中收集灵体能量时保护他。$B$B完成任务后向节点亲王哈拉迈德复命，他就在星界财团设立在法力陵墓外的营地中。', '看看工匠莫法利厄司的点子的成果，我决定让他复职了。做的好啊小噬尸兽。的确是做的好!$B$B记住，要是你想找工作或是到虚空风暴的时候，到风暴之尖来找我。', '哈罗，小噬尸兽。', '护送低温工程师沙赫恩', '去泰罗卡森林找白骨荒野的节点亲王哈拉迈德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10220, '聆听之魂', '我到这里来是为了和那些阴魂进行交流的。这些阴魂过去曾是一群值得骄傲的联盟士兵，但很久之前，他们全部都战死了。从此以后，他们被诅咒的灵魂就盘踞在西边的遗迹中。$B$B若是他们能够加入我们，我们就可以得到一批强力的援军了。想想吧，这样一群拥有不死之身的战士能够帮助我们御敌，那该有多好。可是，这些阴魂都因仇恨而变得疯狂与扭曲，恐怕不会与我好好交流。$B$B或许，我们应该使用武力逼迫他们与我们结盟。', '莫迪巴要求你转至断背岗哨以西的远征军物资库，击败12个步兵的阴魂、8个骑士的阴魂和6个巫师的阴魂。', '这些不屈者已经知道部落的力量了。无庸置疑的他们很快就会接受听取我的结盟提议的。', '你让那些不屈的灵魂见识到反抗被遗忘者的下场了吗?', '', '去地狱火半岛找断背岗哨的莫迪巴大使。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10221, '砰砰博士！', '$N，斯巴奇·尤伯萨斯特这家伙以前一直在我的保护之下。我们来到52区后，他老是不肯带上虚空头盔，终于在某一天摇身一变，成了臭名昭着的砰砰博士！$B$B他偷走了许多重要的挖掘设备，躲藏在东北方的某处营地！他和他的那些砰砰机器人已经对52区构成了巨大的威胁。$B$B我要你立即转至城镇外砰砰博士的营地，结果他的性命！利用这些砰砰厄运炸弹炸飞他。$B$B小心点，不要离他或者那些砰砰机器人太近！', '杀死砰砰博士，然后将胜利的消息汇报给虚空风暴52区的首席工兵布拉斯特菲兹。', '我会怀念史巴克的。<鼻酸>但是现在知道布姆博士无法再威胁我们的这件事使我们都可以睡的更好!$B$B就让这件事给你上一课。千万不要没戴虚空盔帽就下来这里!$B$B现在，我要怎么回报你呢?', '你将我们从布姆博士的蹂躏中解救出来了吗?我发誓现在将不会有任何爆炸性的武器了，虽然那非常的有趣!$B$B我们真的应该要常常那样做。', '', '去虚空风暴找52区的首席工兵布拉斯特菲兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10222, '日怒堡', '凯尔萨斯王子的军队摧毁了肯瑞瓦村，将大法师囚禁在紫罗兰之塔，然后便退驻到了东北方的日怒堡。我们眼睁睁地看着他们庆祝着“伟大的胜利”却毫无复仇之力。$B$B绝不能容忍他们这样行恶！为我们的复仇事业而战吧，$N。转至日怒堡，让那些双手沾满鲜血的罪人得到正义的裁决。', '肯瑞瓦村的管理器戴沃斯要你杀死10名日怒射手。', '你今日所做的事永远无法挽回村子的沦陷，但也许这有助于安抚他们的灵魂。虽然，说实话，再多的血腥都无法平息我对凯尔萨斯的怒火。', '完成了吗，$N!你已经为了肯瑞瓦村庄的沦陷复仇了吗?', '', '去虚空风暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10223, '达尔利斯之死', '我永远都不会忘记袭击肯瑞瓦村的血精灵首领。他穿着一身血红色的铠甲，佩戴着我从未见过的徽章。$B$B跟其它血精灵军官不同，这位残忍的首领竟然冲锋在最前线。那场战争中，许多肯瑞托法师都死在他的箭下。他在日怒堡驻留了一段时间，然后就被凯尔萨斯派去法力熔炉：杜隆，镇压那里的骚乱。$N，找到他的下落，让他的弓弦永久沉寂吧。', '肯瑞瓦村的管理器戴沃斯要你杀死达尔利斯·晨击。', '<你并不确定，但是看起来管理器戴沃斯已经濒临要落泪了。>$B$B终于，结束了。如果我可以选择离开这个世界，我会的，但事实上我却不知道该如何放手。为了那些在村庄牺牲的人们，这是个困难但明确的决定。我想这就是我们为了在这个地方维持强大势力所要付出的代价吧。', '你完成任务了吗，$N?', '', '去虚空风暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10224, '引擎的能源', '身为X-52的技术主管，我必须确保这艘虚空火箭的主引擎具备最优化的性能。$B$B可惜我到现在都还没有把这些主引擎造出来。$B$B$C，眼下的情况非常窘迫！除了引擎核心外，所有的零件都齐了。$B$B不过，我想我们可以利用法力怨魂的精华来发动引擎。$B$B它们遍布在岛屿北部那些闪闪发光的沟渠附近。当然，52区里可没这种生物。', '将7块法力怨魂精华交给虚空风暴52区的主工程师特雷普。', '哇喔，好多精华喔!$B$B好了，让我们看看将它及伊斯利母体水晶混合后会发生什么事。', '你拿到所有精华了吗?', '', '去虚空风暴找52区的主工程师特雷普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10225, '向主工程师汇报', '$N！我要你将这些以太锂水晶交给主工程师特雷普，他是我们的，嗯，领头的工程师。$B$B他应该知道如何处理这些水晶。如果他不知道，你就在那里盯着他，直到他想出法子来！', '将以太锂矩阵水晶交给虚空风暴52区的主工程师特雷普。', '喔，伊斯利母体水晶。耶，这些听起来很重要耶!$B$B就放在这边，我会尽快找出它们的用途。', '嗯，嗨。我现在有点忙。你有什么东西要给我吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10226, '元素能量萃取器', '该死，这玩意根本就不行！$B$B噢噢，我想到个新主意！我曾让塞希罗制作过一台元素能量萃取器，不知道这东西收集来的能量管不管用，但至少我们可以试试。$B$B南边的碎裂废土分布着许多碎裂的滚石和迁跃畸变体，它们体内的能量可以发动引擎！$B$B击败元素生物后，利用这台萃取器将它们的能量转化为便于收集的固体。然后把那些固体带回来给我就行啦。', '萃取5份元素能量，将它们交给虚空风暴52区的主工程师特雷普。', '这才像话嘛!太好了，现在我想我们可以开工了。$B$B就让我将这些东西倒到这个什么什么里面，我相信将会喷出一个全功能的引擎核心。$B$B喔，嘿，我猜我应该要感谢你保住了我的小命!嘿嘿。', '你从那些元素生物身上得到力量了没?喔，我不是想催你或什么的。只不过我的生活及工作都靠你了。', '', '去虚空风暴找52区的主工程师特雷普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10229, '解读书卷', '这本书卷上似乎用某种隐秘的联盟密码语言记录着一些历史事件。那个当前逗留在断背岗哨的历史学家奥尔森研究阴魂已经很久了，或许他能够破解这种联盟密码，并翻译整本书的内容。', '将神秘的典籍交给断背岗哨的史学家奥尔森。', '我一辈子都在研究先祖历史。但我从未见过像这样的一本书。里面记载整个军械库的历史，包括毁灭之后发生的事。$B$B不屈者延续了他们的历史，即使是在他们于战斗中沦陷后。藉由这本书我们将可了解不屈者并说服他们加入。', '这是什么?一本传达不屈者意念的书?真是奇怪。我研究看看。也许我有办法知道不屈者的历史。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10230, '战斗的号角', '或许我们之前接触阴魂的方式是完全错误的？$B$B这本书中的内容告诉我，远征军物资库很久以前就被兽人和死亡骑士毁灭了。这些阴魂是被禁锢在这里的一批复仇之灵，与邪兽人各氏族进行着永恒的战争。$B$B现在，他们所想的事情除了复仇之外再无它物。我们必须让阴魂们击败他们最憎恨的敌人。请你再去一趟远征军物资库，找到塔沃斯少校。他身上带着一只可以召唤所有阴魂的战斗号角。把它带回来给我。', '从塔沃斯少校那里拿到顽强战斗号角，把它交给断背岗哨的史学家奥尔森。', '你做得很好 $N。这个先祖号角使我们能够招集不屈者。$B$B不过，得要他们愿意才行。', '我们得尽快帮助不屈者。要是我们能够说服他们加入我们，部落将获得一个有利的盟友。', '', '去找断背岗哨的史学家奥尔森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10231, '什么书？我没见过什么书', '拉姆杜尔？呃，让我想想……拉姆杜尔……哦，是那个死亡祭司。他要亡者之书做什么？唔，无所谓。很抱歉，我没说实话，但那本书真的不在我这儿。准确地说，我不再拥有它了。它被偷走了，或许是某个卑贱的难民干的。$B$B奥金顿已是了无生气的死地，亡者之书对我们来说没有任何用处了。如果你找到它，就留着好了。$B$B上周我还看见那帮无赖鬼鬼祟祟地在附近出没。就从他们身上开始调查吧。现在他们可能在贫民窟玩骰子。', '伊瑟基尔说亡者之书已经被偷走了。你最好去问问那些无赖，看他们是否知道些什么。', '好，好!不要伤害我们。我们是有这本书不过我们卖掉了……', '你要啥?', '教训“脏鬼”拉瑞，获取信息', '去找沙塔斯城的“脏鬼”拉瑞。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10232, '废料场中的燃烧军团', '沿着道路往东走，桥对面的废料场原本是我们的地盘，可现在被燃烧军团侵占了。$B$B这会给我们造成很大的麻烦！先是阿尔科隆废墟，接下来是废料场，局势越来越糟糕了，不知道52区的火箭计划是否会受到影响。$B$B$N，我要你转至废料场消灭那些恶魔！我本想亲自动手的，但我是个讨厌打斗和杀戮的博爱者。$B$B没错，这是一项艰难的任务，我知道！', '杀死5名莫尔葛铁匠和15名甘尔葛工程师，然后向虚空风暴52区的维勒老爹复命。', '好吧，有好消息也有坏消息，是吧? 我们给了他们一击，但随着燃烧军团遍布整个虚空风暴上 - 并且更接近我们了 -', '我当然希望你忙着与燃烧军团战斗。$B$B没有什么是比背信更让我厌恶的，还有<咳嗽>地精，而恶魔必定就是这两种其中一种!', '', '去虚空风暴找52区的维勒老爹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10233, '烧毁日怒堡', '哪怕我们杀光日怒堡的驻军，也不能阻止血精灵重新夺回城堡。凯尔萨斯的追随者狂热而顽强，如果我们留下任何有用的器物，他们肯定会利用这些东西向我们发动反击。$B$B不行，必须毁掉日怒堡的一切。焚毁那里的帐篷和弩车！$B$B<鬼魂攥紧了拳头。>$B$B$N，你可以从日怒护火者手中夺得火炬来完成这项任务。', '使用燃烧的火把烧毁4台日怒弩车和4顶日怒帐篷，然后向肯瑞瓦村的巫师上尉莫尔兰复命。', '<莫尔兰巫士中尉严肃的点头。>$B$B肯瑞托很难从建筑物本身的利益来欣赏它，但我们并不会因为对抗敌人而觉得良心不安，就算死的也一样。', '烟从日怒要塞的堡垒中升起。那是你的杰作吗?', '', '去虚空风暴找肯瑞瓦村的巫师上尉莫尔兰。', '烧毁日怒弩车', '烧毁日怒帐篷', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10234, '恶魔的垃圾……', '你看上去像是位有能力的年轻人！我想知道你是否能帮我个忙？$B$B在东边的废料场，对，就是燃烧军团的驻地，那里堆满了大型魔能机甲零件之外，还散落着许多小尺寸的零件。而且，恶魔们似乎不怎么在意那些小零件。$B$B我要你转至废料场，将那些小尺寸的魔能机甲零件带回来给我！', '收集10个魔能机甲零件，然后返回虚空风暴的中央生态圆顶，将它们交给中央圆顶哨站的维勒老妈。', '我认为这些都得现在就去做了。只要我们能够将他们吓跑。$B$B嘿，这让我想到了个办法!', '你取得那些零件了吗?随着燃烧军团每次一个一个进驻我们在这里的领地，我们所剩的时间不多了。', '', '去虚空风暴找中央生态圆顶的维勒老妈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10235, '厄运之爪', '你知道怎样才能让他们垂头丧气吗？那就是干掉他们的头目！$B$B我听说这招特别有效。若是他们目睹一位彪悍的$c，比如你，一刀砍翻他们的头目……哇，我敢打赌他们会立即卷起尾巴仓惶逃走！$B$B返回废料场，干掉他们的首领厄运之爪。我听说他躲藏在废料场东边的管道下面。$B$B哦，记得把他的爪子给我带来！我们或许用得上。', '取得厄运之爪的手，然后返回虚空风暴的中央生态圆顶，将它们交给中央圆顶哨站的维勒老妈。', '他，嗯……他说什么?他们将要侵犯52区?!$B$B喔，这太糟了……糟透了!', '解决末日裂爪了没?', '', '去虚空风暴找中央生态圆顶的维勒老妈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10236, '外域这烂地方！', '我真不敢相信我竟然会离开藏宝海湾来到外域。我的兄弟斯克里·拉克希德许诺说我能在这里赚一大笔钱，但这家伙倒是乘坐飞艇离开了，把我留在这个破矿井里混吃等死。$B$B这鬼地方整天被地狱野猪、恶魔还有邪兽人攻击，叫我怎么活？我的伐木机昨天也坏了，修理机器的备用零件还被邪兽人偷走了。他们把零件搬到了西南边的裂谷中，没准就丢在那边呢。', '找到6个伐木机备用零件，然后返回萨尔玛西北方的矿洞，将它们交给工头拉泽克拉兹。', '喔耶，你找到零件了!也许现在我可以修好我的伐木机了。假如我可以赚到足够的钱我就可以回去藏宝海湾了。$B$B我真希望我的堂弟，史哥利德.幸运心，还有他的飞艇一起坠机。我不敢相信他骗我来外域。', '你帮我的伐木机找到修理的零件了吗?我希望赶快修好他我才能继续去矿坑工作。不论如何我都必须要赚钱过日子，只有这样我才能赚足够的钱买一张回去藏宝海湾的单程票。', '', '去地狱火半岛找萨尔玛的工头拉泽克拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10238, '如何为地精效力', '为什么邪兽人要偷走我的伐木机零件？我讨厌他们。这帮家伙老是溜进营地偷东西。几天前，他们竟然偷走了三名苦工！现在，矿洞的其它苦工都跑光了，他们可不想被邪兽人吃掉。$B$B没苦工叫我怎么开矿啊？要是你能把那些苦工救回来，没准其它人就肯回来工作了。邪兽人的营地就在西南边的城墙下。', '从邪兽人的营地中救出曼尼、莫恩和雅克，然后返回萨尔玛西北方的矿洞，向工头拉泽克拉兹复命。', '感谢你拯救了我的苦工们。也许现在我就可以叫他们拿着零件去修我的伐木机，赚到足够的钱然后离开外域。我等不及想回去藏宝海湾了。', '你救回我的苦工了没?拜托快一点，我怕他们很快就会被吃掉而且他们应该不好吃。假如邪兽人吃了倒胃口的话他们可是会迁怒到我呢。', '', '去地狱火半岛找萨尔玛矿洞的工头拉泽克拉兹。', '营救曼尼', '营救莫恩', '营救雅克', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10239, '强大的能量源', '我们并非是唯一与法力生物抗争的势力。血精灵也深受它们的困扰，不过我并不清楚原因。$B$B无论血精灵在法力熔炉遭遇了怎样的麻烦，他们却没有收手的意思。我发现，他们用各种方法杀死法力生物，其中最有效的就是利用高度集中的能量形成魔法防御屏障。$B$B转至法力熔炉：库鲁恩夺取一些能量源，然后带回来给我。如果有机会的话，别忘记给血精灵制造一点麻烦。', '肯瑞瓦村的巫师上尉莫尔兰要你转至法力熔炉：库鲁恩，取回10块能量隔离器。', '<莫兰小心翼翼的处理其中一个容器。>$B$B我不相信我之前曾看过任何跟这一样的东西。一定有很多的能量悬浮在这里，但是是以原始的状态。我们得小心处理，不过我想我们能找到方法来改写这些能量进而协助抵挡那些法力生物。', '你有办法取得到任何他们的能量来源吗?', '', '去虚空风暴找肯瑞瓦村的巫师上尉莫尔兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10240, '构筑能量壁障', '现在，我们计划利用这些从血精灵手中夺来的能量源在村子周围创建起一道能量壁障。我不敢保证这绝对有效，但总得试试看。$B$B否则法力生物就会源源不断地涌进村落，继续吞噬肯瑞托法师的灵魂。$B$B利用这个装置激活村子周围的小符文。如果力场分布得没有错，每激活一块符文，你就能感受到周围的变化。', '对东部符文、东北部符文和西部符文使用符文激活装置。你可以在肯瑞瓦村城镇广场和巫师街周边找到这些符文。完成任务后向巫师上尉莫尔兰复命。', '做得好。抓紧你的手，$N。我要启动防护罩了。', '你启动了所有的符文了吗?我很急切的想知道是否我们无法改善这里的血精灵秩序。任何凯尔萨斯的手下可以做到的事，真正的肯瑞托可以做的更好。', '', '去虚空风暴找肯瑞瓦村的巫师上尉莫尔兰。', '激活东部符文', '激活东北部符文', '激活西部符文', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10241, '削弱法力熔炉：布纳尔', '沙塔尔派我们来调查凯尔萨斯的军队运转法力熔炉的情况。不幸的是，占星者威胁说，如果我们不派兵支持，他们就拒绝履行信息收集义务。$B$B如果因为政治原因导致任务失败，我们可承担不起这样的后果。因此，我们同意削弱法力熔炉的防御力量，让占星者安全完成他们的工作。$B$B向奥尔多证明你的忠诚吧，去消灭驻守法力熔炉：布纳尔的日怒魔导师和日怒血卫士。', '杀死8名日怒魔导师和8名日怒血卫士，然后向52区的大主教欧雷里斯复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '做得好，$N。先知者已经揭露了宝贵的资讯以感谢你的扰乱行动。也许这次他们会真的跟我们分享了。', '你完成任务了吗，$N?', '', '去虚空风暴找52区的大主教欧雷里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10242, '断背岗哨', '$N，真是可惜，现有的设备无法进行我想要做的血液检测。不过，我可以找断背岗哨的药剂师阿尔布雷克帮忙，他有合适的器械。$B$B我有一份血环兽人的血样，是萨尔玛的间谍执行任务时收集到的。将这份血样交给阿尔布雷克研究研究。$B$B要去断背岗哨的话，跟空军指挥官布拉克谈谈就可以了。他就在南边那群双足飞龙旁边。', '机甲残骸的药剂师塞兰娜要你与空军指挥官布拉克谈一谈，搭乘双足飞龙转至断背岗哨，并将血环血样交给断背岗哨的药剂师阿尔布雷克。', '一个血液测试，是吗?我很荣幸。我向来喜欢与血为伍……', '欢迎来到断脊氏族岗哨。我能帮你什么忙吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10243, '纳鲁科技', '占星者得到了一份法力熔炉：布纳尔的人员名册，他们花了一整天时间挑选暗杀目标。$B$B然而，占星者却没有留意到写在名册边上的一串潦草的符号。这些符号似乎是进出像埃索达或是风暴要塞这样的纳鲁建筑物的密码。$B$B进入法力熔炉寻找控制台，将控制台上的读数拓在这个卷轴上。我们必须确认这些符号的来源。', '进入法力熔炉：布纳尔，找到布纳尔控制台。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '你打开了卷轴准备好要将这些怪异的符号复制下来。', '这个在你面前出现的符号看起来怪异且难懂。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10245, '布纳尔控制台拓文', '无数图形在你眼前快速掠过，你尝试着拓下它们的形状。卷轴上的拓文虽欠精确，但它们足以证明奥尔多的猜想是否正确了。', '将布纳尔控制台拓文交给虚空风暴52区的学者卡尔亚。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '你做得很好，$N。给我几分钟去看一下你的誊本。$B$B你拥有全体牧师的感谢，$C。', '让我们看看你带了什么要给我们，$N。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10246, '攻击法力熔炉：库鲁恩', '你在法力熔炉：布纳尔获得了令人侧目的成就。我敢肯定学者卡尔亚一定希望你在法力熔炉：库鲁恩也有同样优秀的表现。$B$B最近我们得到消息，一大群地位显赫的日怒奥术师和研究者被派驻到了法力熔炉：库鲁恩，我要你以他们为作战目标。如果你能成功的话，这将是对敌人的一次沉重打击。', '转至法力熔炉：库鲁恩，杀死8名日怒奥术师和5名日怒研究员，完成任务后向大主教欧雷里斯复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '做得好，$N。有你的全力奉献我们必定能打败我们的敌人。', '完成你的任务了吗，$N?', '', '去虚空风暴找52区的大主教欧雷里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10248, '你，机器人', '工程学博士沃米萨愿意为您效劳！来，拿着这个控制器。我要你启动它，遥控我新造的这台再造机甲X6000型四下转转。$B$B别跑远了！控制器是连接在控制台上的。要是你跑得太远，遥控设备就会停止运转。$B$B记得把所有的功能都测试一下……我会根据实验结果来校准它的随动系统。', '启动再造机甲X6000型控制器并测试其性能，灵活应对测试过程中的突发状况。然后向虚空风暴实验场的工程学博士沃米萨汇报实验结果。', '嗯，我的$g男孩:女孩;那还真是刺激呀!由于制造它的资金有限，我觉得废料劫夺者X6000的表现非常的棒，尽管那个驾驶是个菜鸟。$B$B嘿嘿，不，别生气，我只是开玩笑而已。毕竟，你刚刚已经把52区还有X-52虚空火箭从毁灭的边缘救回来了!', '你觉得如何?是否需要大翻修呢?', '', '去虚空风暴找实验场的工程学博士沃米萨。', '完成再造机甲X6000型的测试', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10250, '血之复仇', '这里的正东方有一处已被摧毁的联盟攻城塔，现在那里只有一片废墟。很久以前，许多联盟的战士牺牲在那处攻城塔中，而且他们的军旗也被一个邪兽人军官夺取了。$B$B到联盟的军旗下面去吹响这只战斗号角。它会引起乌尔特拉克的注意，也会召来那些在战斗中倒下的士兵。', '在联盟战旗附近吹响顽强战斗号角。然后杀死乌尔特拉克，并向断背岗哨的史学家奥尔森复命。', '很高兴听到不屈者加入了你的战斗。我以为他们只会听从他们自己的战斗号角，但是我并不确定。也许是因为我们给予他们最渴望的复仇机会。$B$B你已经杀死乌崔克而我们必须向远征队军械库的指挥官霍卡尔斯回报你的胜利消息。他会了解你对他们的付出。', '你在攻塔时吹了这个号角了吗?我们必须快点进行这件事。谁知道萨尔玛何时会需要不屈者。', '', '去找断背岗哨的史学家奥尔森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10252, '亡者的视界', '利维休斯已经开始实施他的计划了。他站在奥金顿遗址顶部，诵读着亡者之书。他叫着亡者的名字，将他们召唤出来，然后利用恶魔的仪祭扭曲这些灵魂的意志，使其成为他的仆从。如果不阻止利维休斯的话，他一定会控制奥金顿的所有亡者！$B$B但是……你必须做好充分的准备。你是无法与你看不见的敌人作战的。$B$B<尼特林递给你一张羊皮纸。>$B$B替我找来这些材料，我就为你配制一瓶通灵药剂。它能打开你的心智，让你看到灵魂的世界。', '收集1颗山丘戈隆的眼球、1个完美的大型风鹏之喙和1份老迈裂蹄牛的脂肪，然后返回纳格兰废弃的军械库，把它们交给尼特林。', '陌生人……我对你并不诚实。一旦你喝了这个药剂，你将永远看得到死者的世界。你喝的配方是给奥齐顿所有死亡祭司的入门祭仪。许多人在它的效用持续发作后发疯了。看见死者是……可怕的。$B$B<奈崔恩将那药剂放到你的嘴唇。>$B$B你想要继续吗?', '勒威萨斯的军队每分每秒都在茁壮。你一定要加紧脚步。', '', '去找纳格兰的博学者尼特林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10253, '唤魂者利维休斯', '$N，去吧。利维休斯就在奥金顿遗迹的顶部。从白骨荒野南侧进入奥金顿，他被灵魂的风暴围绕着……$B$B杀死利维休斯，夺走亡者之书。一旦你得到那本被诅咒的书，就立即销毁它！一定要销毁它，绝不能让它落入其它野心家手中。', '杀死利维休斯，夺得亡者之书。$B$B将亡者之书交给疯狂的拉姆杜尔，他就站在奥金顿的奥金尼地穴入口外。$B$B你们之间有协议的，还记得吗？', '如果老德莱尼告诉你把书摧毁，为什么你没做?$B$B<蓝姆多怒视着你。>$B$B呸，有什么差别。你也许是贪婪的不过至少你诚实。$B$B而我在另一方面……我说谎以得到这本书。我不知道这些可怜的失落灵魂将他们的财宝藏在哪里，也不会告诉你我有没有 - 虽然 -', '你是谁，你想要干嘛?喔……是你喔。', '', '去泰罗卡森林的奥金顿找疯狂的拉姆杜尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10255, '测试解毒剂', '我想，我们可以利用本地生物血液中的某些成分来制作解毒药剂。你觉得我疯了吗？别那么看着我好不好！$B$B你要知道，这是自然界中的普遍规律，通常能治愈毒症的成分都是来源于毒素本身，我就是遵循着这个规律在尝试。$B$B将这些野猪身上的恶魔力量祛除之后，或许它们就不会再这样具有攻击性了。我们也可以借机仔细地观察一下净化的过程和状况，看看怎样才能更好地帮助其它物种。', '对笨拙的地狱野猪使用塞纳里奥解毒剂，并观察解毒剂的效果。然后返回地狱火半岛的塞纳里奥哨站，向塞安·红鬃汇报实验的结果。', '<当你描述了实验的结果，塞伊亚.红发瞪大了眼睛。>$B$B这，这怎么可能呢?我确定我正确的调配了解毒剂!$B$B它明明就可以解开蜘蛛还有蛇的毒液，那么为什么这次会失败呢?也许是外域的差异性造成的吧，$N。我最好把这项讯息传递给其它的同伴们知道。', '你知道实验的结果了吗?', '', '去地狱火半岛找塞纳里奥哨站的塞安·红鬃。', '测试解毒剂', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10257, '夺回钥石', '凯尔萨斯将钥石交给指挥官萨拉妮丝这样的人保管，我一点都不觉得惊讶。凯尔萨斯王子在许多方面都非常优秀，他绝对不是傻子。$B$B为了永久破除这个诅咒，你必须杀入风暴要塞夺回钥石。$B$B一旦钥石被摧毁，我就能重获久违的自由。', '进入风暴要塞的生态船，从指挥官萨拉妮丝手中夺得钥石，将它交给紫罗兰之塔的大法师瓦格斯。', '<当你把石头交给他时，大法师的眼睛发亮。>$B$B真是惊人!根据我所看到的少许关于法拉隆德的命运，我不确定我想要出去了，但是这会比我困在这里度过馀生来得好多了。', '你拿到拱心石了吗?', '', '去虚空风暴找紫罗兰之塔的大法师瓦格斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10261, '悬赏：歼灭者机械臂', '悬赏：我需要一根歼灭者机械臂来替换长管光谱分析仪中损坏的零件。$B$B你和你的朋友可以去西边的法力熔炉：布纳尔，看看那里的血精灵是否有这类备用零件。法力熔炉中似乎有奥术歼灭者活动。$B$B请将一根品质完好的歼灭者机械臂交给52区的维勒老爹。', '将一根歼灭者机械臂交给虚空风暴52区的维勒老爹。', '喔呵!你知道要得到这些东西有多难吗?这跟我在这里收到的普通零件可不一样。$B$B告诉你吧，我要你从我的旧货盒中拿取一样东西做为报酬。我相信那里有你可以用得东西。如果不是的话，就卖掉吧。$B$B好了，让我从你手中接过这样东西并在这个坏掉的伺服电动机爆炸前放进我的长颈光谱分析器中。', '我希望你是来关切我张贴的悬赏布告!', '', '去虚空风暴找52区的维勒老爹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10262, '叛徒的徽记', '我还有件事要你帮忙。$B$B一个名叫萨克希斯的虚灵组织已经脱离了星界财团，经营起自己的生意来。他们居然和日怒血精灵有贸易往来，我无法容忍这种行径！$B$B我偷偷潜入了南边的机甲废场，那里就是萨克希斯虚灵的营地。在干掉了他们的领袖之后，我不得不逃回52区。$B$B$C，返回机甲废场，把他们的徽记带回来给我。当然，你不必赶尽杀绝，给他们点颜色瞧瞧就可以了，这帮家伙全是懦夫。', '收集10枚萨克希斯徽记，将它们交给虚空风暴52区的虚空猎手卡尔伊。', '这些徽记是一个好开始。$B$B不幸的是，当你在聚集之地时，我在萨希斯的其它密探其中之一捎话给我，星移劫掠者尼萨德还活着!', '完成了吗?你有除去外域的萨希斯渣滓，并将他们的徽记带来给我了吗?', '', '去虚空风暴找52区的虚空猎手卡尔伊。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10265, '星界财团的水晶', '我们的领袖——节点亲王哈拉迈德派我转至东南方的阿尔科隆废墟，取回一件水晶神器。$B$B那里是一处古老的德莱尼文明废墟，我和此地的地精遇到了同样的麻烦：燃烧军团已经进驻阿尔科隆废墟并启动了挖掘工事。$B$B如果你愿意帮助我的话，就进入废墟将那件水晶神器从恐惧魔王匹塔塞隆手中抢回来吧。', '将一件阿尔科隆水晶神器交给虚空风暴52区的虚空猎手卡尔伊。', '让我看一下那东西。$B$B嗯，看来似乎没有什么特别的。我怀疑这就是那个东西吗，虽然你所描述燃烧军团在废墟活动的方式，听起来好像他们正在寻找某些特别的东西。$B$B让我们期望这不会是节点亲王那么想拥有的水晶。', '我有印象王子正在寻找一颗特别的水晶，但是我不确定它是什么。$B$B你已经从惊惧领主那拿到一个了吗?', '', '去虚空风暴找52区的虚空猎手卡尔伊。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10267, '贸易终结', '我们与血精灵之间的贸易关系看来就此终结了。几周前，我们按订货单为法力熔炉：杜隆送去了一批探测设备，但是血精灵拒绝付款。$B$B$N，我要你去东边的法力熔炉：杜隆跑一趟。他们似乎正为肆虐的法力生物烦恼不已，你可以趁机混入法力熔炉。$B$B我根本不关心他们的境遇，我只想取回星界财团的财产。', '收集10箱测量装置，然后返回虚空风暴中央生态圆顶的中央圆顶哨站，将它们交给加鲁斯。', '嗯，我个人对于解决了这桩小生意感到很开心。我不记得何时联合团与那样粗野且无法信任的生物交易过。$B$B不过，你好像很值得信任，$N。或许你不介意帮我更多的忙?', '你拿到那些血精灵拖欠的调查设备了吗?', '', '去虚空风暴找中央生态圆顶的加鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10268, '与节点亲王会面', '节点亲王哈拉迈德刚刚派来特使向我转达了他的意愿，亲王殿下希望我们立刻将这件无价之宝归还到他本人手中。如果你能帮我跑这一趟的话，我会由衷地感激你。$B$B能够得到节点亲王的召见将是无上的荣耀，我相信他会非常乐意聆听你在虚空风暴的冒险故事。$B$B转至北边的风暴尖塔吧，亲王将在塔顶的大厅中接见你。哦，你可能会注意到，他通常以全息影像的方式现身。', '转至虚空风暴的风暴尖塔，将测量装置交给节点亲王哈拉迈德的影像。', '欢迎来到风暴之尖，$C。请享用联合团的殷勤招待。$B$B你可以将那个设备放在任何地方。我猜你可能很快地就要背起它了。', '靠近。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10269, '一号三角点', '还有一个原因让我们必须取回那些测量装置。德莱尼人的传说中曾提到一颗神奇的水晶，它对我来说非常重要。$B$B据说这颗水晶中蕴藏着能与神祗媲美的力量！但现在，它很可能落入了燃烧军团的手中。$B$B$N，利用测量仪找到第一个三角点。我想它应该在法力熔炉：乌提斯以东的某个地方。$B$B找到之后，与法力熔炉：乌提斯所在的浮岛上的商人哈斯辛谈一谈，他是我派驻在那里的代理人。', '利用三角测量仪找到一号三角点。找到之后，立刻转至虚空风暴法力熔炉：乌提斯的维序派哨站，向商人哈斯辛汇报三角点的位置。', '<商人海辛降低他的声音变成耳语一般。>$B$B啊，我知道你的任务。这对节点亲王哈拉迈德来说非常重要!$B$B既然我们知道第一个三角测量点的位置，你必须迅速动身去找到第二个!', '你好啊，旅人。你到海辛这来是想要买我的商品吗?', '找到一号三角测量点', '去虚空风暴找维序派哨站的商人哈斯辛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10270, '不太谦虚的提议', '从你脸上的神色我看得出，你是个擅长为自己谋取利益的$r。$B$B我是位小有名气的特种货物贸易商，最近我正打算展开一段新的冒险。$B$B眼下，我需要一名可靠的下线帮我从苍穹之脊搞些货物来，不知你意下如何？$B$B首先，你需要给传送器补充能量。在法力熔炉：乌提斯南侧的瑟安竖井处有一套备用的能量包，你可以利用它来充能。维序派正在那一带活动，你可以根据他们留下的踪迹行动。', '取回传送器能量包，将它带至法力熔炉：乌提斯东边苍穹之脊上的虚灵传送器。激活传送器，然后将传送器能量包交给星界商人玛里德的影像，让他进行安装。', '这个电池应该要为了我们的目标保留。一旦钱进帐后，我们就能将它改良得更好。$B$B有这样的东西就够了。每个讨论的片段都会造成利益的损失。', '你准备好现在谈生意了吗，$N?', '', '去虚空风暴的苍穹之脊并使用虚灵传送器找星界商人玛里德的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10271, '重要生意', '你肯定已经看见了，这一带生活着许多处于不同生长阶段的虚空龙。无论是幼龙还是成年虚空龙，体内都蕴涵着某种精华。凯……呃，我的一名客户迫切地想要得到它。$B$B大多数人都不敢冒着生命危险来收集龙类精华，因此我们只能自己动手啦。你可以从虚空龙身上收集到这种精华，但关键问题在于我们是否能联手创建起一条稳定的供应渠道。这样，你搞到第一批之后就立即带回来给我。', '收集8份虚空龙类精华，然后返回虚灵传送器区域。你可以从虚空幼龙或虚空之龙身上收集到虚空龙类精华。', '想想看，卑鄙的以太族要把这些精华像糖果一样卖给血精灵……', '我相信你会有很多问题，所有的问题都会在适当的时间得到回答。', '', '去虚空风暴的苍穹之脊虚灵传送器区域。找到隐蔽的身影并与其对话。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10272, '成功的开始', '谣传此地近来有奇异的龙族血脉出现，我们正是来调查此事真实性的，据说它们可能是死亡之翼的后代。不过，这些龙显然不是普通的黑龙。$B$B如果有机会检查它们的卵，或许我们就能了解到更多秘密。这些虚空龙非常仇视蓝龙，因此我根本无法接近它们的卵，你能帮帮我吗？', '收集15枚虚空龙卵，然后向苍穹之脊的泰莉和乔拉德复命。', '这些蛋会得到良好的运用，$N。谢谢你同意帮助我们。$B$B不过，在我们继续之前，还有其它事情需要我们先处理。', '你可以去收集蛋吗?', '', '去虚空风暴找苍穹之脊的泰莉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10273, '棘手的目标', '你之前的雇主——星界商人玛里德一定听到了风声，知道你正在帮助我们。通过投影，我发现他手下的虚空猎手已经进入了这片地区，想要搜寻我们的下落。$B$B到当前为止，我们总能成功地躲避猎手的攻击；但是为了避免事情闹到不可收拾的地步，你必须先发制人，替我们铲除玛里德。$B$B如果你了解玛里德的话，就会明白这家伙肯定会不惜代价地确保货物供应线的安全。回去找他吧，告诉他你要和他做笔交易。将玛里德引离商栈，然后杀死他。', '与星界商人玛里德谈一谈，诱使他离开商栈。杀死玛里德后向苍穹之脊的泰莉和乔拉德复命。', '既然那令人讨厌的以太族已经被解决掉了，我们可以努力专注去了解这些虚空龙了。我有一个机会可以去检查这些蛋，而且我得到了一些发现。', '这个玛利德是个笨蛋，或者我该说，曾经是个笨蛋。', '', '去虚空风暴找苍穹之脊的泰莉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10274, '占领苍穹之脊', '虚空龙的性情与它们的黑龙同宗一样凶暴而狂躁，但也有一些截然不同的地方。虚空龙的孵化期和成长期十分短暂，身上涌动着奇特的能量。这种能量流是在德拉诺世界毁灭的时候产生的，从而导致了虚空龙这一族群的诞生。$B$B我还需要了解更多的细节，我相信这种能量可以为蓝龙所用。如果我能取代这些虚空龙的领袖维拉库，充分展示我的统御力，我们就能令其它虚空龙屈服。', '转至苍穹之脊的南端，使用蓝龙的挑战激怒维拉库。击败他后向苍穹之脊的泰莉和乔拉德复命。', '做得好，$N。的确做得很好。虚空龙族最初不愿接受一条蓝龙混在他们之中，但是随着时间和我坚定的展示权威，他们会到这里这。分布的，单独的，没有一位可靠的领导人，我们必须警戒避免它们落入邪恶力量的统治，永远保持他们的控制权。', '你去挑战并且打败维拉库了吗?', '', '去虚空风暴找苍穹之脊的泰莉。', '消灭维拉库', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10275, '二号三角点', '根据你提供的一号三角点的信息，我对这台三角测量仪进行了重新校正。你可以采用同样的方法寻找二号三角点。$B$B我唯一能告诉你的就是它可能在极远的西方。$B$B一旦你发现了二号三角点，立即与节点亲王的另一名代理人——星界商人图鲁曼取得联系，他乔装成武器商，藏身于法力熔炉：艾拉所在的浮岛上，过了桥就能看见他的商栈。', '利用三角测量仪找到二号三角点。找到之后，立刻转至虚空风暴法力熔炉：艾拉对面的图鲁曼的营地，向星界商人图鲁曼汇报三角点的位置。', '的确非常好。节点亲王会很高兴!$B$B我们现在知道第2个点了，它将告诉我们第3个点在哪里，以及水晶的大概位置!', '你要买还是要卖?', '找到二号三角测量点', '去虚空风暴找图鲁曼的营地的星界商人图鲁曼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10276, '三角测量', '利用一号和二号三角点的资料，我敢确定那颗水晶就在东北方法兰伦废墟的上方。$B$B不幸的是，数据显示它一直在移动，这就是说燃烧军团很可能已经得到了这颗水晶！$B$B为了以防万一，我建议你召集几个朋友一同转至法兰伦废墟。$B$B从恶魔手中夺回水晶，将它交给节点亲王哈拉迈德吧。', '夺得阿塔玛水晶，然后返回虚空风暴的风暴之塔，将它交给节点亲王哈拉迈德的影像。', '出乎我最疯狂的想象之外，我从没想到你能取回水晶!$B$B还真的将它交给我!你知道它有多么强大吗?$B$B你的无私是鼓舞人心和无可非议的，$N!你给了我许多值得思考的事。', '又见面啦，我的朋友。水晶找的如何阿?', '', '去虚空风暴的风暴尖塔找节点亲王哈拉迈德的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10277, '时光之穴', '$N，你好。请跟随时光监护者。她会帮助你理解这一切……', '时光之穴的安多尔姆要你跟随时光监护者游览时光之穴。', '希望你现在对于在等着你的东西有更多的了解。', '直到你至少初步了解到发生的事情前都不要回来。', '游览时光之穴', '去塔纳利斯找时光之穴的安多尔姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10278, '迁跃裂隙', '从很久以前开始，我就在外域的土地上流浪，在这里探\r\n索有关扭曲虚空的秘密了。现在，我已经老迈而虚弱，但你……或许你可以帮助我？$B$B我一定要了解那些虚空行者的秘密。拜托你转至西边的迁跃平原，也就是远征军物资库西面的那片地方。那里位于深渊的边界旁，时间与空间都已变得扭曲而异常了。使用我所制造的这个不稳定的迁跃裂隙生成器，在那边制造一个空间裂隙吧，然后从裂隙里涌出的生物身上收集尽量多的迁跃虚空能量。', '在迁跃平原使用不稳定的迁跃裂隙生成器。从不稳定的虚空行者身上收集3份迁跃虚空能量，把它们交给断背岗哨的疯狂的欧加斯。', '难以相信。你碰触了虚无本身!$N，你保住了我毕生的研究。不过还有更多事必须完成，而你可以帮助我。', '你有试着使用我的实验设备吗?我认为我的不稳定的扭曲裂隙生成器会在如此接近坑道的深处的地方发生作用。', '', '去地狱火半岛找断背岗哨的疯狂的欧加斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10280, '送往沙塔斯的特殊货物', '我是位信守诺言的虚灵，$N。你的行为令我深受感动。$B$B给，将这块阿塔玛水晶转交给纳鲁吧。是你从恶魔手中夺回了这颗水晶，因此由你将它献给纳鲁是再合适不过的了。$B$B你可以使用我的私人传送装置直接抵达沙塔斯城。只要踩上去，你就会被传送过去。$B$B将阿塔玛水晶交给圣光广场中的纳鲁阿达尔，愿自由之风伴你前行。', '将阿塔玛水晶交给沙塔斯城圣光广场的阿达尔。', '你取回了鬼魂之歌!这个阿塔莫水晶就是预言者费伦转至埃索达进行他不幸的任务前留给族人保管的东西。$B$B奇怪的是他并没有预见它会落入燃烧军团的手中，就算只是暂时而已。$B$B或者，也许他预见了?也许他预见了这全部的事，所以将它留在那里好让你可以取回水晶并且来到这里把它交付给我?$B$B我觉得那就是事情的实情。你是你族人的伟大英雄，$N!', '<纳鲁说话的美妙口音充满了你的内心。>$B$B我感觉到你带着某种拥有巨大力量的东西，$r。你带给我的是什么呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10283, '塔蕾莎的计谋', '塔蕾莎是挽救萨尔性命的关键人物，她还教会了萨尔如何思考，为他日后成长为部落酋长奠定了坚实的基础。$B$B正是塔蕾莎在敦霍尔德城堡采取的声东击西战术，帮助萨尔成功脱逃。$B$B永恒之龙却将塔蕾莎囚禁在塔伦米尔。倘若我们袖手旁观的话，就不会发生这场混乱，萨尔也无从逃脱。你必须利用我交给你的燃烧弹，焚毁敦霍尔德城堡的收容所。引爆燃烧弹后，跟被关押在敦霍尔德城堡地牢中的年轻的萨尔谈谈。', '进入敦霍尔德城堡，将伊洛希恩交给你的燃烧弹包分别放入5间收容所内的木桶，并启动定时装置。$B$B引爆燃烧弹后，与被关押在敦霍尔德城堡地牢中的萨尔谈一谈。', '你是塔蕾莎的朋友吗?所以这是她的新计画吗?非常好……', '你是谁?', '', '去找萨尔。', '点燃收容所', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10284, '逃离敦霍尔德', '在你看来，我现在不过是个小孩，但是在我心中藏着远大的梦想。陌生人，我已经为我的族人规划了未来。终有一天，他们会团结一致，推翻人类的压迫。他们会挣脱束缚，新生的兽人部落将再次崛起。$B$B陌生人，我向你保证，只要你伸出援手，帮助我们从这儿逃生，一旦我有能力报答你，我必定会找到你……必定。$B$B<萨尔点了点头。>$B$B等你准备就绪，我们就出发吧。', '准备就绪后告知萨尔。保护萨尔逃离敦霍尔德城堡，并与他一起搭救塔蕾莎。$B$B任务完成后与旧希尔斯布莱德丘陵的伊洛希恩谈一谈。', '你完成了一件伟大的事，$N。哎呀，这个年轻大酋长对这些事件的回忆一定和当时分毫不差……安杜姆就在主人的藏身处等着你。', '<伊洛森点了点头。>', '', '去找旧希尔斯布莱德丘陵的伊洛希恩。', '完成萨尔的命运', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10288, '抵达外域', '我要你去和阿米什·蛮锤谈谈，他就站在我们南边30步远的地方。他可以安排你搭乘狮鹫直飞荣耀堡。到达荣耀堡之后，你会先和伊斯多尔元帅碰面。我这里还准备了一份书面报告，描述了这里的情况。你要把这份报告带给他，并向他报到。$B$B这就是我给你的命令，立刻去执行！你的力量将一定可以帮助我们对付那些恶魔，别在这里浪费时间了。荣耀堡更加需要你的帮助。', '地狱火半岛上黑暗之门的指挥官杜隆要求你将杜隆的报告交给阿米什·蛮锤。', '回报荣耀堡吗?没问题 -- 我的狮鹫兽将安全迅速地带你到那里!', '我看过你在那跟杜朗交谈。你一定是在进行一项重要的任务吧!', '', '去地狱火半岛找命运阶梯的阿米什·蛮锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10289, '萨尔玛之旅', '我随时都可以召唤双足飞龙将你送去萨尔玛，只要你准备好就可以了。到了那边之后，记得马上将沃雷恩的报告交给克拉库克将军。$B$BLok\'tar ogar，$n，祝你好运。', '乘坐维拉加·乱羽的双足飞龙转至萨尔玛，并将沃雷恩的报告交给克拉库克将军。', '我将集结我所能调动的军队，并且派他们去援助在黑暗之门的欧莱恩部队。不久之后燃烧军团将忘不了部落的战吼声!至于你$N，你今天已经为萨尔玛做了一项伟大的事。我期待你在这里能给我们很大的协助……假如你有让自己生存下去的智慧的话。', '来自欧莱恩的报告吗?快一点拿过来!$B$B<克洛克尔克将军皱着眉头迅速地审视了潦草的文件。>$B$B可恶，这是我们所担心的。欧莱恩和他的战士们随时可能被包围!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10290, '寻找法兰石', '此地东北方就是虚空石。虚空石的景致跟这里的青翠绿地截然不同，暴露在地表外的水晶石几乎结成了阵。我们将水晶中包含的矿物质命名为法兰石，以此纪念这片土地以前的主人。$B$B我们开采到的少量法兰石成了市面上的抢手货。不过，高纯度的法兰石并非来自沉积水晶岩，而是取自虚空石附近的石巨人身上。如果你能帮我收集天然法兰石的话，我就与你分享销售收入。', '收集4块天然法兰石，将它们交给风暴尖塔的伊格努比。', '啊，是的。这种等级确实是我所期待的。假如我们能从巨人身上取得稳定的进货来源，我们也许能完全的放弃开采水晶矿。', '我了解收集法拉莱特的风险，但是做生意也是如此。不愿意冒险的商人最好关门大吉，为自己减少麻烦。', '', '去虚空风暴找风暴尖塔的伊格努比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10293, '完美的水晶', '有了优良的基准产品，接下来我们需要寻找品质更高的水晶。当然，当前为止我们开采到的法兰石已经相当不错了，但是我知道哪里有更好的水晶。$B$B我们要从法兰伦石巨人族长克拉格斯卡身上直接采集一份样品！他与别的石巨人一起生活在虚空石。他的后背生长着巨大的法兰石水晶簇，那正是我们需要的东西。打倒这个巨人，然后将他身上的法兰石核心带回来。', '风暴尖塔的伊格努比要你取回一个法兰石核心。', '做得好!我等不及要测试这东西了。', '你仍然活着，表示你已取得核心，或者你已经改变主意。是哪一个呢?', '', '去虚空风暴找风暴尖塔的伊格努比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10294, '虚空山脉', '我们得略微改进一下我这台迁跃裂隙生成器。这样，你带着它到虚空山脉去，就在这里的正东方。你去的路上要小心避开塞斯高。在塞斯高那边东侧的山里应该有条隐秘的小路，直接沿着这条小路过去，就可以找到虚空山脉了，那是一片位于深渊边缘的可怕的地方。$B$B到了那边以后，你要先杀死几只虚空行者，然后把它们的灵魂碎片带回来。有了它们的力量，我就可以大大强化迁跃裂隙生成器的功率，打开一扇永远不会关闭的传送门了。', '转至虚空山脉杀死当地的生物。收集40块虚空山脉灵魂碎片，把它们交给断背岗哨的疯狂的欧加斯。', '非常好，扭曲裂隙生成器几乎完成了。我们只需要最后一种原料。不久我们将能打开一道扭曲裂隙通往深渊的最深处。$B$B谁知道什么奇怪的生物会穿过裂隙而来?想想看$N，探索未知地学得的知识所带来的益处是不可限量的。', '你已经完成了吗?你拿到我们需要的裂片了吗?', '', '去地狱火半岛找断背岗哨的疯狂的欧加斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10295, '来自深渊', '我的迁跃裂隙生成器完成了。现在你可以直接用它召唤出一个真正的虚空行者贵族，只有它的灵魂碎片才能告诉我们，那无底深渊之中到底有些什么样的存在。$B$B立刻转至虚空山脉，在那里的深渊边缘寻找一簇一簇的水晶石，对，它们的学名叫虚空石。然后，你在那些虚空石旁边使用我的迁跃裂隙生成器，虚空男爵加拉希斯会跨越巨大的空间裂隙出现在你的面前。$B$B杀死这只生物，把它的灵魂碎片给我带回来。', '杀死虚空男爵加拉希斯，并得到他的灵魂碎片，把它交给断背岗哨的疯狂的欧加斯。', '你挽救了我一生的工作$N。$B$B他们说我疯了、他们嘲笑我、他们认为我为虚无山脉和扭曲原野而着魔发狂。现在有这块灵魂裂片我就能解开虚无行者的秘密了。我将拥有深渊的力量。', '你解决虚无男爵.加伦希斯了没?', '', '去地狱火半岛找断背岗哨的疯狂的欧加斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10297, '开启黑暗之门', '在这条时光通道的尽头，守护者麦迪文正在黑色沼泽中心兴奋地忙碌着，想要打开黑暗之门，让兽人大军尽数入侵艾泽拉斯世界。$B$B永恒之龙派出裂隙领主滋扰生事，企图阻止黑暗之门的开启。$B$B这些裂隙领主潜伏在黑色沼泽的各处伺机而动，他们的目标是破坏麦迪文的法力护盾，最终杀死麦迪文。$B$B消灭裂隙领主和他们的首领！保护麦迪文，直到黑暗之门成功开启。这个时空道标可以帮上你的忙。', '时光之穴黑色沼泽的萨艾特要求你保护麦迪文，直到他成功开启黑暗之门。$B$B任务完成后向萨艾特复命。', '做得好，$N。安杜姆这个孩子，希望再一次与你谈话。', '你在每一个时光之袋只可以使用一个时间信号灯。', '开启黑暗之门', '去找黑色沼泽的萨艾特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10299, '关闭法力熔炉：布纳尔', '若是强行摧毁法力熔炉，由此引发的大爆炸很可能会波及整个外域，我们可不能冒这样大的风险。$B$B从你取回的拓文来看，控制台配备了紧急关闭装置，纳鲁科技通常会在建筑物中使用这种安全的控制机制。$B$B要关闭控制台，你就必须夺得控制水晶。根据我们掌握的情报来看，这颗水晶就在工头瑟瑞狄斯手中。', '返回法力熔炉：布纳尔，从工头瑟瑞狄斯手中夺得布纳尔控制水晶。使用水晶关闭法力熔炉：布纳尔控制台，然后向学者卡尔亚复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '圣光眷顾着你，$N。我们全都祈求你的成功。', '你已经完成你的任务了吗，$N?', '', '去虚空风暴找52区的学者卡尔亚。', '', '关闭法力熔炉：布纳尔', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10300, '修复法杖', '<拉文德维尔仔细检查着法杖，突然注意到杖头部分缺失了。>$B$B这太野蛮了！埃克拉斯肯定将水晶杖头拆了下来挪作它用，完全破坏了杖头与法杖其它部分的魔力平衡。$B$B杖头一旦损坏，势必会大大削弱法杖的力量。若是能找到合适的德莱尼水晶，我应该可以修复它。我听地精们说，北边恩卡特废墟的鬼魂身上有这种水晶。', '从恩卡特废墟的鬼魂身上收集4块无瑕的水晶碎片，将它们交给52区的拉文德维尔。', '<罗樊德威仔细地检验水晶，然后从中挑选一个。>$B$B这水晶应该可以。我将重新雕塑法杖以装上新的法杖首盔。$B$B当大法师瓦戈斯看见法杖时，他将感到失望，但是如果这么做可以释放主人，我能承担主人的失望。', '你已经设法找到适合当作大法师法杖头部配件的水晶了吗?', '', '去找虚空风暴52区的拉文德维尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10301, '魔法纲要的防护', '你夺回了克拉苏斯的魔法纲要，这令我非常欣慰。但是如果没有紫色单片眼镜的话，这本书就是一摞废纸。睿智的克拉苏斯非常清楚，许多人都会觊觎书中记载的强大法术；于是他为魔法纲要设置了完美的防护机制。$B$B只有知识渊博的法师才能利用紫色单片眼镜揭开书中的秘密。$B$B在凯尔萨斯进攻这里时，他手下一位名叫掠法者玛拉瑟雷的军官将眼镜抢走，带去了日怒堡东北方的一处法师塔中。她只是把它当成了一件有点价值的小玩意收藏着。', '从日怒堡的掠法者玛拉瑟雷手中夺得紫色单片眼镜。', '太好了，$N。现在，我们已经获得大多数我们需要用来破除凯尔萨斯之魔法的东西了。$B$B如果血精灵丧失他们本地的指挥官而感到苦恼的话，当然更好。', '你拿到紫罗兰之目了吗?', '', '使用大法师瓦格斯的法杖与大法师取得联络。$B$B如果你不小心遗失了大法师瓦格斯的法杖，可以向52区的拉文德维尔再要一根。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10302, '暴躁的变异体', '埃索达的放射能量核心肆意破坏着这一带的环境。最显着的负面效应当属能量核心周围如雨后春笋般冒\r\n出来的怪异生物。$B$B我们或许能拯救这些可怜的变异体，可是它们越生越多，我们可应付不过来。$B$B希望你能稍微削减一下暴躁的变异体的数量，或许我能想出拯救它们的方法。', '杀死8个暴躁的变异体，然后向埃门谷坠毁点的植物学家塔蕾克丝复命。', '已经完成了吗?那真是个好消息。希望将来我们可以找到一个方法避免杀害那些突变的野兽。$B$B我相信我已经想出一个计画使我们对这个问题可以有别的解决方法，但是我将需要你的帮忙。', '我正在进行我认为对这些奇怪生物有效的解决办法。我只是需要更多的时间。', '', '去找埃门谷坠毁点的植物学家塔蕾克丝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10303, '血精灵', '你必须解除……血精灵的……威胁。查明……他们的……目的！$B$B他们就在我身后的……山脊中。', '杀死10个血精灵斥候，然后向埃门谷暗影山的图兰复命。', '这些血精灵想杀死我们全部。我们该怎样让他们转移到别的方向?', '他们的人数太多了……我们必须削弱他们，否则那些幸存者将没有机会对抗他们。', '', '去埃门谷找暗影山的图兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10305, '防御法师贝尔玛拉', '虽说是肯瑞托法师之物，这本破旧的书卷却并不是什么法术书。书页里都是手抄体的故事，字体娟秀，还配有精美的彩色插画。$B$B书卷看上去比它的主人还要古老，很可能是系列的传家宝吧。贝尔玛拉的灵魂至今仍在肯瑞瓦村的废墟中徘徊，这本书卷似乎是她在世间最后的羁绊。将它放回贝尔玛拉家中的书架上，或许就可以平息她的怒火。', '在巫师街内找到防御法师贝尔玛拉的住所，将书放回书架上。然后与肯瑞瓦村的管理器戴沃斯谈一谈。', '啊，是的。我已经听说弃绝者贝马拉有一本旧的故事书，但是我不知道她将它带到了外域。你已经找到这本书并且将它带回她的住处，我相信她的灵魂将得到更多的宁静。', '你发现了什么，$N?', '', '去虚空风暴找肯瑞瓦村的管理器戴沃斯。', '让贝尔玛拉的灵魂安息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10306, '咒术师鲁米拉斯', '这件披风无疑出自高等精灵匠人之手，即便是以肯瑞托法师的标准来看，它也称得上材质华美、价格不菲的精品。你看不懂绣在披风上的符号与文字，但显然衣料中附着了魔法属性。$B$B或许它仍然将主人的灵魂羁绊在这个物质位面中。如果是这样的话，就将这件披风放回咒术师鲁米拉斯家中的衣柜里，或许就能破除羁绊，让他的灵魂得到安息。', '在巫师街内找到咒术师鲁米拉斯的住所，将披风放回衣柜里。然后与肯瑞瓦村的管理器戴沃斯谈一谈。', '我们总是常常说卢瑞斯不论穿什么衣服都会搭配那件披风。对他来说，红色在搭配上与白色、黑色、紫色、蓝色、黄色、橘色和绿色同样好。他绝不会连续两天穿相同的长袍，但他总是穿着那件披风……', '你发现了什么，$N?', '', '去虚空风暴找肯瑞瓦村的管理器戴沃斯。', '让鲁米拉斯的灵魂安息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10307, '考利恩·霜纹', '看着这顶帽子，你禁不住怀疑有哪位肯瑞托法师会拥有这样的头部装备。从帽子的磨损程度看得出，它的侏儒主人无论走到哪里都戴着它。$B$B你试着戴上帽子，发现除了一点点想要跳舞的冲动外，这顶帽子没有任何魔法属性。$B$B这件珍贵的物品很可能将主人的灵魂羁绊在了村庄中。将它放回考利恩家中的小提箱里，或许就能让法师的灵魂得到自由了吧。', '在巫师街内找到考利恩·霜纹的住所，将帽子放回小提箱中。然后与肯瑞瓦村的管理器戴沃斯谈一谈。', '<管理器听到了考林的名字以后露出了微笑。>$B$B关于那顶帽子你说对了。他总是穿着它而且不会让它离开他的视线。$B$B他曾经有一个法师同事，我不方便透露名字，“借走了”那顶帽子然后恶作剧的把它藏起来。不用说你也知道后来考林的寒冰箭让他改变了主意。$B$B我会非常想念小考林的。他对女精灵很有一套。', '你发现了什么，$N?', '', '去虚空风暴找肯瑞瓦村的管理器戴沃斯。', '让考利恩的灵魂安息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10308, '更多叛徒的徽记', '', '', '他们全都是叛徒!$B$B做得好，$C!如果你有再到那里去，我一直都想增加他们徽记的收藏。', '联合团对于彻底消灭所有在南方聚集之地的萨希斯反叛者感到强烈的兴趣。$B$B$C，如果你想让我们更加喜欢你，就回去那里带回更多他们的联合徽记。', '', '去虚空风暴找52区的虚空猎手卡尔伊。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10309, '魔能机甲的心跳', '你看见南边那些破损的魔能机甲了吗？你不觉得它很美吗？$B$B我想它要的心！$B$B什么？是的，它当然有心……为什么没有？$B$B<米西·米恩卡普的语气中透出一丝恼怒。>$B$B橇开魔能机甲的装甲，把我想要的东西给带回来，我会付给你一大笔钱当报酬的。$B$B哦，如果我是你的话，我会带一两个朋友同去，因为那里有许多萨克希斯虚灵！$B$B带上这个邪能起搏器，在你卸下魔能机甲之心前，记得先使用这个小玩意。', '将魔能机甲之心交给虚空风暴机甲废场的米西·米恩卡普。', '哇，看看那个……一颗跳动的恶魔劫夺者之心!呃，它其实没＂跳动″，但是你知道我的意思。$B$B我等不及要充分利用这件东西了。或者，考虑出售它。我知道一些呆瓜……呃，感兴趣的客户。$B$B来，你已经挣得了你的薪水!', '我的视力一定是随虚空辐射线而去了。你取得恶魔劫夺者之心了吗?', '', '去虚空风暴找机甲废场的米西·米恩卡普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10310, '破坏迁跃门！', '燃烧军团已经占领了附近的魔能机甲废料场，我们必须竭尽全力阻止这群该死的恶魔继续向前推进，入侵到这里。$B$B他们在南边有一处名为登陆场：破坏的营地，营地中设有迁跃门。$B$B我要你护送我进入营地，并在我破坏迁跃门时确保我的安全。$B$B完成任务后，就返回北边中央生态圆顶的中央圆顶哨站，将这一好消息告诉加鲁斯。$B$B不过，我们恐怕还需要另外一两位朋友来帮忙。', '护送德里亚到达登陆场：破坏的迁跃门，并在他尝试破坏迁跃门的过程中保护他的安全。然后返回虚空风暴的中央生态圆顶，向中央圆顶哨站的加鲁斯复命。', '那真是最好的消息，我的朋友!$B$B你和迪耶亚已经为我们做了一项伟大的事。随着那星移门的损坏，附近的恶魔将不会再有任何增援部队了。$B$B请允许我以联合团的名义给予你适当的奖励。', '我可以帮你什么吗?', '破坏燃烧军团迁跃门', '去虚空风暴找中央生态圆顶的加鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10312, '肯瑞瓦名册', '看来我们的期望落空了，上一次的行动并没有彻底消除他们的攻击性。你看，那些曾被你制服的邪恶幽灵再度出现镇子的街道上。$B$B我们必须揭开其中的隐秘。躁动难安的灵魂……难道肯瑞瓦的毁灭才刚刚拉开序幕吗？$B$B肯瑞瓦的城镇大厅就在村子的东南角，那里保存着一本村民资料的名册。我听说战斗法师达斯利克负责保管它，说不定他的灵魂还守护着这本名册。', '从肯瑞瓦村的城镇大厅中取回肯瑞瓦名册，将它交给管理器戴沃斯。', '<监护者戴沃斯接过你手中的记录簿，匆匆翻阅那些书页。>$B$B嗯……$B$B看起来我猜的没错，这件事有规律可寻。$B$B最具侵略性和最危险的鬼魂与居住在村庄里的最强大和最高等级的肯瑞托相符。比较起来市镇居民和小贩好像被忽略了。这意味着什么?', '你找得到记录簿吗?', '', '去虚空风暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10313, '测量迁跃能量', '如果我们直觉没有错，这些法力熔炉应该都是利用风暴要塞的科技建造而成的。这样一来，整个外域恐怕就岌岌可危了。$B$B风暴要塞的能量补给机制绝对不适合在靠近陆地的地方使用。虽说能量管道是凯尔萨斯设计的，但是传输过程中产生的强大迁跃能量流也足以使整片陆地失去生机。$B$B必须采取行动！带上这颗宝珠转至法力熔炉布纳尔，它能监测到迁跃能量的强度。在法力熔炉管道的末端，也就是管道进入地下的那里使用它。', '52区的大主教欧雷里斯要你将迁跃共鸣宝珠带往法力熔炉：布纳尔，并在法力熔炉四条管道的末端使用它。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '这是重要的消息，$N。从管线流出的扭曲能量具高危险性。$B$B我们必须找到方法关闭法力熔炉，否则爆炸之后外域只会剩下几块碎片而已。', '你执行过我要的测量了吗，$N?', '', '去虚空风暴找52区的大主教欧雷里斯。', '测量北部管道', '测量东部管道', '测量南部管道', '测量西部管道');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10314, '久远的痕迹', '你从没见过如此奇特的魔法装置，它显然不是血精灵的制品。$B$B你发现，一旦有幽灵靠近建筑物，球体所发出的光芒就会变得强烈；而当幽灵走远后，光芒也会逐渐黯淡下来。毫无疑问，这台装置与幽灵的堕落有着密切的关系。$B$B但是它的设计原理仍然还是一个谜。如果你将观测结果告知管理器戴沃斯，再从幽灵身上收集一些碎片供他研究，或许他能揭开其中的秘密。', '从肯瑞瓦村礼拜堂广场中扭曲的幽灵身上收集10份令人厌恶的残留物，将它们交给管理器戴沃斯。', '<监护者戴沃斯检验残馀物。>$B$B你描述的装置听起来好像是一种死灵法术的媒介……我本该知道那个不学好的学徒会因此而堕落。我本以为他的训练会使他远离今日的堕落程度，但是我想他已经证明我是错的。', '你发现了什么，$N?', '', '去虚空风暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10315, '消灭虚空法师', '所有血精灵都是蠢货！和他们解除贸易关系真是件值得庆幸的好事。我走遍了宇宙中的每个角落，却从来没有见过这样自私自利的生物。$B$B他们利用法力熔炉不断地侵蚀着我们周围的土地，那么我们就在桥对面的法力熔炉：艾拉搞点破坏好了。$B$B据我所知，要想稳定法力熔炉的能量流，血精灵的虚空法师们必须利用血宝石不停地引导能量。转至法力熔炉：艾拉，干掉那些虚空法师！', '消灭15名日怒虚空法师，然后返回虚空风暴内的图鲁曼的营地，向虚空猎手奥尔苏复命。', '任何我们能推动他们停止在这些法力熔炉所做的事都是好事。$B$B他们当然不会跟你讲道理。而且我很清楚无论他们的领导人在想什么，他们都是疯狂的。$B$B如果不会冒犯你的话，我想要给你属于你们国度的钱币作为达成联合团目标之忠诚服务的报酬。', '你计画要杀掉几个虚空术师?', '', '去虚空风暴找图鲁曼的营地的虚空猎手奥尔苏。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10318, '督工格林加尔', '我曾是法力熔炉的工头，不过我已经被降职了。不久前我忽然意识到，当初从奎尔萨拉斯一路朝圣来到外域，经历多少苦难，而这一切全都是个骗局。$B$B这是凯尔萨斯为了壮大他在虚空风暴的军队而布下的骗局。$B$B我试图说服同胞们离开燃烧军团，但他们性情顽固，不肯相信我。$B$B你能帮我个忙吗？去干掉督工格林加尔，然后回到你的虚灵朋友那里，告诉他我不再与他为敌了。', '杀死督工格林加尔，然后返回虚空风暴内图鲁曼的营地，向星界商人图鲁曼复命。', '一个末日守卫征服者?真是奇怪!燃烧军团在那边做什么呢?$B$B所以，一部分的血精灵正在逃离。我们应该记住这点，假如我们将来想靠武力征服那里的话。至少这些事情带来了一些好消息，不是吗?$B$B来吧，$N，收下这个东西还有我最深的感激吧。', '你带了什么有关法力熔炉艾拉的消息吗?你解决了工头日落吗?', '', '去虚空风暴找图鲁曼的营地的星界商人图鲁曼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10319, '纳比留斯的护符匣', '我想事情已经水落石出了。你应该已经和学徒拉文瑞德尔见过面了吧，不过大法师还有一位名叫纳比留斯的学徒。$B$B他是个勤奋的学生，却因沉迷通灵术而无法自拔。当凯尔萨斯率领大军逼近肯瑞瓦村时，纳比留斯借机背叛了大法师，将紫罗兰之塔的防御机密告诉了凯尔萨斯。$B$B他似乎已经沦为巫妖。如果要阻止他继续做恶，就必须夺得他的护符匣。你要知道，这个狡猾的家伙绝对不会将它埋在他视线之外的地方。', '在肯瑞瓦村的礼拜堂广场中找到纳比留斯的护符匣，将它交给管理器戴沃斯。', '做得好，$N。这个骨匣将是我们获胜的关键。当你与纳伯瑞厄斯战斗时，我将粉碎骨匣，使他暴露在你的攻击中。', '在我们能攻击他之前，你必须取得纳伯瑞厄斯的骨匣。否则，他会是刀枪不入的。', '', '去虚空风暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10320, '毁灭纳比留斯！', '大法师沃格斯早已意识到纳比留斯研习通灵术的危险。但我想，他恐怕未曾预料到自己的学徒会给肯瑞托带来这场毁灭性的灾难。$B$B你必须击败纳比留斯，$N。否则，他将继续奴役肯瑞托法师的灵魂，让他们永远得不到安宁，最终他将使肯瑞瓦的每一寸土地都落入毁灭的深渊。$B$B只要得到了他的护符匣，我们就可以派出两到三名刺客对付他，否则，谁有知道他会对赶去围剿他的军队用出什么样的法术呢？', '肯瑞瓦村的管理器戴沃斯要你击败礼拜堂广场中的纳比留斯。', '击败纳伯瑞厄斯是一项伟大的成就，$N。我一直在想假如当时纳伯瑞厄斯没有背叛大法师的话，我们可能有击溃凯尔萨斯大军的机会。', '你消毁了那个卑鄙的纳伯瑞厄斯的尸体了吗?', '', '去虚空风暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10321, '关闭法力熔炉：库鲁恩', '你在布纳尔的成功为我们燃起了新的希望，$N。$B$B我们和占星者分享了最新的发现；作为回报，他们将剩下几座法力熔炉的情况告诉了我们。$B$B当前，仍有三座法力熔炉在运作中，而且都在日怒血精灵的掌控之下。$B$B转至东边的法力熔炉：库鲁恩，从工头希兰娜手中夺得库鲁恩控制水晶。对法力熔炉：库鲁恩的控制台使用水晶，启动紧急关闭装置。$B$B$N，我们都指望你了。', '转至52区以东的法力熔炉：库鲁恩，从工头希兰娜手中夺得库鲁恩控制水晶。对法力熔炉：库鲁恩的控制台使用水晶关闭法力熔炉，然后向学者卡尔亚复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '做得好。只剩两个法力熔炉保持运作。$B$B很快地凯尔萨斯的主要动力就会被切断了。', '你完成你的任务了吗，$N?', '', '去虚空风暴找52区的学者卡尔亚。', '', '关闭法力熔炉：库鲁恩', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10322, '关闭法力熔炉：杜隆', '我们收到消息说，仍在运行的两座熔炉中，日怒血精灵突然失去了对法力熔炉：杜隆的控制。$B$B大群狂乱的法力生物被高速增长的能量流所吸引，冲入了法力熔炉。$B$B如果杜隆发生爆炸的话，很可能引发波及整个外域的大规模连锁反应。你必须从工头安萨奈尔手中夺得控制水晶，并安全关闭法力熔炉：杜隆。', '学者卡尔亚要你转至法力熔炉：杜隆，从工头安萨奈尔手中夺得杜隆控制水晶。对法力熔炉：杜隆的控制台使用水晶关闭法力熔炉。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '纳鲁祝福你，$N。你付出的供献将不会被忽略或者未受奖赏。', '你完成你的任务了吗，$N?', '', '去虚空风暴找52区的学者卡尔亚。', '', '关闭法力熔炉：杜隆', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10323, '关闭法力熔炉：艾拉', '现在仅剩一座法力熔炉来维持整个风暴要塞的能源供给了。如果我们能摧毁法力熔炉：艾拉，凯尔就不得不启用他之前储存的能量。$B$B关闭西北方的法力熔炉：艾拉，给予凯尔萨斯最沉重的一击。$B$B最后一块控制水晶由工头阿扎拉德保管。注意，这是凯尔最后一座仍在运行中的法力熔炉，恐怕你会遭到非常顽强的抵抗。你可能会需要可靠的朋友帮忙。', '转至法力熔炉：艾拉，从工头阿扎拉德手中夺得艾拉控制水晶。对法力熔炉：艾拉的控制台使用水晶关闭法力熔炉。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '燃烧军团?与凯尔萨斯.逐日者结盟?$B$B这真是个可怕的消息。这解释了我们在这及影月所见到的景象。$B$B我们必须马上将消息传回沙塔斯城。', '你完成我要求的任务了吗，$N?', '', '去虚空风暴找52区的学者卡尔亚。', '', '关闭法力熔炉：艾拉', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10324, '狩猎月痕鹿', '干得好，$n！$b$b你利用月痕雄鹿好好地磨练了自己的狩猎技术，现在是时候让你面对更强大一些的猎物了，比如月痕巨鹿。你可千万不要被月痕巨鹿寻常的那种温顺与懒洋洋的样子给骗了。只要一被激怒，它们马上就会变为最可怕的野兽。$b$b在这里的正北方就可以找到这些月痕巨鹿，祝你狩猎愉快。', '将6张月痕鹿皮交给碧蓝岗哨的艾克提恩。', '太完美了!你彻底变成猎人了，$N。$B$B你要如\r\n何看起来更像我呢?你的机会到了!在你外出狩猎时，我用四周的雄鹿皮革制做了这些东西。选一个吧!', '这些雄鹿的皮革是坚固而表面布满粗线条的图案，他们的肉非常的坚韧 - 几乎不能吃，但是我们有其它的用途。', '', '去秘蓝岛找碧蓝岗哨的艾克提恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10325, '基尔加丹印记', '你应该已经知道了，$N，我们奥尔多是圣光的守护者，是纳鲁的仆从。$B$B而我们最直接的敌人就是燃烧军团——那群以扭曲和毁灭世界，腐化和侵蚀无辜种族为乐的恶魔。$B$B如果你想对奥尔多证明自己的价值，那么就给我带一些低级燃烧军团士兵和暗影议会成员的徽记回来吧。暗影议会在白骨荒野有一处据点，而燃烧军团的据点则大多分布在刀锋山脉和纳格兰。', '将10枚基尔加丹印记交给沙塔斯城内的圣光护卫者阿德因。$B$B为奥尔多完成任务将会使你在占星者声望中的声望等级降低。', '对抗燃烧军团的恶魔和崇拜他们的疯狂教徒不是件容易的事，$N。你已经展现了伟大的功勋和勇气。坚持下去，你在奥多尔中的名望将继续成长。', '你手上有任何我们敌人的徽记吗，$N?', '', '去沙塔斯城找奥尔多高地的圣光护卫者阿德因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10326, '更多基尔加丹印记', '', '', '继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。$B$B<这个任务可重复执行直到声望阶级到达尊敬。>', '你带回了更多敌人的印记了吗，$C?燃烧军团仍是一个威胁，不论天涯海角我们都将继续对抗他们。', '', '去找圣光护卫者阿德因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10327, '单枚基尔加丹印记', '', '', '继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。$B$B<这个任务可重复执行直到声望阶级到达尊敬。>', '我将拿走你剩下的所有印记。别担心;你的行为将被正式的表扬。', '', '去找圣光护卫者阿德因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10328, '日怒简报', '法力熔炉的事一直在困扰着我，$N。纳鲁的科技水平遥遥领先，即便是凯尔萨斯，也应该需要数年时间才能掌握。$B$B凯尔萨斯的军队纪律严明，他们会及时销毁所有书面通信证据，情报收集工作非常艰难。$B$B我们接到消息，法力熔炉：杜隆遭到了法力生物的入侵。血精灵很可能还来不及销毁那里的文件和简报。立刻将这些东西带回来给我。', '转至法力熔炉：杜隆，从日怒军团士兵手中夺得日怒军事简报和日怒奥术简报。完成任务后向大主教欧雷里斯复命。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '做得好，$N!让我们看看能从这些简报里发现些什么。', '你去法力熔炉杜罗取得简报的进展如何?', '', '去虚空风暴找52区的大主教欧雷里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10329, '关闭法力熔炉：布纳尔', '你外出执行任务时，我和奥尔多进行了一番友好的谈话。法力熔炉极像是风暴要塞中纳鲁科技的改良建筑物。当然，大多数纳鲁建筑物都会配备安全装置，倘若出现紧急情况，就可以启动安全装置彻底废掉这类建筑物。$B$B通常，他们会利用控制水晶来关闭建筑物的控制台。瞧！这本名册上写道，工头瑟瑞狄斯掌管着控制水晶。夺得水晶，看看能不能派上用场。', '返回法力熔炉：布纳尔，从工头瑟瑞狄斯手中夺得布纳尔控制水晶。对法力熔炉：布纳尔的控制台使用水晶关闭法力熔炉，然后向间谍大师萨罗迪恩复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '这么做当然会成功!我是一个间谍大师;我刺探到的军情永远是正确的。$B$B无论如何，我有一个全新的刺激任务等着你去完成。你想听吗?当然你想。', '计画成功了吗?老实跟你说我预计有一半的机会你会一起被炸死。', '', '去虚空风暴找52区的间谍大师萨罗迪恩。', '', '关闭法力熔炉：布纳尔', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10330, '关闭法力熔炉：库鲁恩', '萨罗迪恩告诉我说，你成功地关闭了法力熔炉：布纳尔。他希望能如法炮制地关闭法力熔炉：库鲁恩，因此下令寻找拥有控制水晶的人。我们已经查明工头希兰娜掌管着控制水晶。$B$B去关闭法力熔炉：库鲁恩吧。这次别偷偷摸摸的。直接夺得水晶，关掉法力熔炉，杀死企图阻止你的技师，然后撤退。$B$B快，凯尔的走狗很快就能查到我们的下落。', '从工头希兰娜手中夺得库鲁恩控制水晶。对法力熔炉：库鲁恩的控制台使用水晶关闭法力熔炉，然后向卡勒迪斯·晨光复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '我们听到了全场的骚动并正要离开。很高兴看见你没有受到多大的伤害。', '你完成你的任务了吗，$N?', '', '去虚空风暴找法力熔炉：库鲁恩的卡勒迪斯·晨光。', '', '关闭法力熔炉：库鲁恩', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10331, '必备的工具', '你有没有在附近看见一把重型铁匠锤？我原本要用它给阿莫尔林那老家伙的马匹钉上铁蹄的，可现在却找不到了。$B$B我翻遍了整座马厩，找了十来次，还是一无所获。会不会是哪个学徒捡到铁锤，把它带回我的铁匠铺了？你愿意到那边去帮我找找吗？我的铺子就在城镇广场塔楼的东南边。', '从肯瑞瓦学徒手中夺回铁匠锤，将它交给肯瑞瓦村的学徒安德雷萨。', '感谢老天爷!现在我可以继续工作了。我知道你会觉得我疯了，竟然不在一般锻造的适合地点制造可以帮我赢得熟练工地位的作品，但是我不能冒险让其它的学徒们抄袭我的作品。', '你找我的锤子找的还顺利吗?', '', '去虚空风暴找肯瑞瓦村的学徒安德雷萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10332, '铁匠大师罗恩苏斯', '终于，我的学徒课程全部结束了！我真是等不及要告诉罗恩苏斯大师了。$B$B<学徒认真地听你你描述取回铁锤的经历。>$B$B他们攻击了你？所有人？圣光啊，他们一定是疯了！$B$B那我们要怎么办，$N？难道必须要杀死罗恩苏斯大师，哦，说出这话已经让我十分悲痛了。这样下去……我或许就是肯瑞瓦村唯一的铁匠了，但我相信我的能力足以满足全镇的需要。', '肯瑞瓦村的学徒安德雷萨要你消灭镇上铁匠大师罗恩苏斯的鬼魂。', '我的一切智识技能都是朗瑟士大师教我的。我将透过我的技能服务肯瑞瓦的人们来纪念他。', '<眼泪在这个徒弟开口时冒上了他的眼眶。>$B$B你已经……解决朗瑟士大师了吗?', '', '去虚空风暴找肯瑞瓦村的学徒安德雷萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10334, '贝希的铃铛', '在哪里呢，我的贝希跑到哪里去了？那次袭击之后，我就一直在农田和礼拜堂广场附近寻找她，可怎么都看不见她的身影！$B$B贝希留下的唯一对象就是这个老铃铛了。过去她一听到铃铛响就会跑过来，但是我这把骨头恐怕已经摇不响它了。$B$B我把贝希的铃铛交给你，你能帮我到田地那边去摇摇铃铛，看看她会不会出现……或许贝希正四处寻找着这铃铛的声音呢。', '在虚空风暴肯瑞瓦村礼拜堂小丘附近的农田中找到贝希。', '<从你的背包取出颈铃来，你摇动铃铛一会儿并把它秀给似乎认得它的贝丝看。母牛允许将这个铃铛的绳子系在她的颈子上，并且期待的看着你。>', '<这只牛站在本来的地方，怀疑地看着你。>', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10335, '调查废墟', '我打算立刻转至法兰伦废墟进行挖掘工作！但问题是那里恶魔肆虐，根本无法进入！$B$B或许你能帮我做些挖掘之前的初期准备工作？$B$B我想在遗迹东北角的三处地点放下测量标记。测量点附近各有一面德莱尼旗帜，很好辨认。$B$B放好测量标记后回来找我。', '放置好三枚测量标记，然后返回虚空风暴的风暴尖塔里，向塞菲里恩复命。', '你不会扯我的后腿吧?那真是最好的消息啊!$B$B现在你已经完成了轻松的实地调查工作，我可以带着我的团队到废墟上面去寻宝了。$B$B感谢你，$C。', '动作真快。你一定是一个非常有效率的人，已经将那3个标记全部放置妥当。', '', '去虚空风暴找风暴尖塔的塞菲里恩。', '放置一号测量标记', '放置二号测量标记', '放置三号测量标记', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10336, '库鲁萨斯的爪牙', '几周前，燃烧军团占据了法兰伦废墟，彻底阻碍了我们调查遗迹并挖掘文物的计划。$B$B今天早些时候我收到情报，据称一个名叫库鲁萨斯的恐惧魔王杀光了军中的其它将士，然后便开始召唤恶魔来侍奉他。$B$B$C，我要你转至东北方的法兰伦废墟，将这些恶魔全部消灭。', '杀死10只库鲁萨斯的猎犬和5只库鲁萨斯之眼。然后返回虚空风暴的风暴尖塔，向虚空猎手纳乌希思复命。', '做的真好。$B$B在卡露萨斯的恶魔被杀后，塞菲尔恩将能安全的把他的挖掘队带进法拉隆废墟。$B$B收下这枚硬币代表我对你的感激。', '你把所有法拉隆废墟的恶魔都杀掉了没?', '', '去虚空风暴找风暴尖塔的虚空猎手纳乌希思。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10338, '关闭法力熔炉：杜隆', '法力熔炉：杜隆遭到攻击，局势已经失控？这真叫我为难！如果杜隆被摧毁，风暴要塞也就在劫难逃了。唯一的缺憾是……风暴要塞被摧毁时引发的大爆炸势必会将这片被遗忘的土地夷为平地。$B$B凯尔萨斯死掉固然很好，可是白白搭上这许多无辜的生命……就不太好吧。没办法，只能由我们来收拾凯尔萨斯留下的烂摊子咯。你只能转至法力熔炉：杜隆，在这座法力熔炉爆炸前关闭它。控制水晶由工头安萨奈尔掌管。', '返回法力熔炉：杜隆，从工头安萨奈尔手中夺得杜隆控制水晶。对法力熔炉：杜隆的控制台使用水晶关闭法力熔炉，然后向间谍大师萨罗迪恩复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '你已经关掉了三个法力熔炉了，$N。凯尔萨斯现在一定昏倒了吧。', '你完成关闭的任务了吗?你得在我改变对这整个计画的心意前快点完成。', '', '去虚空风暴找52区的间谍大师萨罗迪恩。', '', '关闭法力熔炉：杜隆', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10339, '复仇军', '此地正南方就是复仇军前沿基地。最近，大批复仇军在那里筹备着什么行动……或许他们是想突袭乌提斯。$B$B万一他们的目标是我们就麻烦了，我们绝不能冒这个风险，$c。立刻突破他们的外围防御网，摧毁他们的训练设施。$B$B杀死索瓦克斯上尉和他手下的士兵后，找到复仇军发射器 - 塞塔。利用它与我取得联系，我会传达给你后续的命令。', '指挥官阿米尔要你杀死5名复仇军刺客、5名复仇军突击队员、2名复仇军研究员和索瓦克斯上尉，然后启动复仇军发射器 - 塞塔。', '我们必须收集他们已经储存在这个区域的任何资料。', '做得好，凡人……', '', '去虚空风暴的复仇军前沿基地用复仇军发射器塞塔找到指挥官阿米尔的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10341, '乘胜追击', '$N，你打探回来的消息对我们大为有利。如此一来，你就能顺利地混入法力熔炉：杜隆，狠狠地打击凯尔军队的嚣张气焰。$B$B趁法力熔炉：杜隆陷入混乱之际杀掉那些掉队的日怒士兵。$B$B跟萨罗迪恩不同，我不喜欢无意义的屠杀；不过放弃此次战略优势就太可惜了。', '杀死8名日怒咒术师、6名日怒弓箭手和4名日怒百夫长。完成任务后返回52区向魔导师拉恩娜复命。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '你做得很好，$N。凯尔萨斯的军队会很难从你今天的打击中恢复。', '你完成了你的任务了吗，$N?', '', '去虚空风暴找52区的魔导师拉恩娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10342, '收集岩肤油块', '我在52区售卖饮料，赚了不少钱。可我还想要赚更多！$B$B火箭主管总是向我抱怨说他找不到能让X-52飞上天的燃料。$B$B我们可以帮他搞定这个小问题。$B$B首先，我必须要从此地的岩肤劫掠者的油块上分解出原油来！浓缩后的原油就可以用作混合燃料的燃基。$B$B去那些紫色的岩石附近寻找岩肤劫掠者吧，替我取回它们身上的油块。', '收集5块岩肤油块，将它们交给虚空风暴52区的布兹。', '好了!第一号原料完成了。$B$B现在，要是你加把劲，我们可以继续收集某种可提供页岩油一点需要额外刺激的东西来将虚空火箭推进扭曲虚空里……或者是发生爆炸，看看哪个会先发生。', '你取得足够的页岩了吗?我需要大量去淬取出可用于X-52 虚空火箭燃料所需的油。', '', '去虚空风暴找52区的布兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10343, '无尽的入侵', '凯尔萨斯首先朝肯瑞瓦村西北角的军官区发动了攻击，当时那里突然传来雷鸣般的噪音，接着便从空中落下一道闪电。军官区成为了肯瑞瓦村破坏最为严重的区域。血精灵撤军后，就发生了怪事。$B$B由纯法力构成的生命体突然如潮水般从四面八方涌入村中。到当前为止，我们还能勉强牵制住肆虐的法力生物。不过如果我们能了解到凯尔萨斯所用武器的更多信息，就有机会彻底切断它们的来路。', '在肯瑞瓦村中法力生物肆虐的地区收集一块魔法炸弹碎片，将它交给巫师上尉莫尔兰。', '一枚法力炸弹?$B$B<莫尔兰将手中的碎片翻来翻去。>$B$B几乎难以想象!即使在达拉然里最聪明的人也不可能想象出一种像这样的武器。一定是这场大骚动在虚空中撕破一道裂隙，让这些生物可以进入我们的土地。', '你有找到凯尔萨斯用来攻击村子所剩下的武器吗?', '', '去虚空风暴找肯瑞瓦村的巫师上尉莫尔兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10345, '血肉会撒谎……', '$r，瞧见这些尸体了吗？是阿克努斯干的。他吸干了尸体，只留下一具干枯的躯壳。但是，你千万别被表象欺骗了！尸体中蛰伏着蠢蠢欲动的血肉兽，随时准备伏击那些放松警惕的蠢材。$B$B我刚刚接到新的指令，必须留在这里等待增援。不如你拿上我的点火器，替我烧毁矿井中的干枯的尸体。无论如何，我们必须完成任务。', '对12具干枯的尸体使用维序派点火器。完成任务后将维序派点火器还给瑟安竖井外的代理人阿拉克塞。', '你救了我的伪装，$N。护国者将会知道你今日的作为，朋友。', '亚希克斯找得如何?', '', '去找虚空风暴瑟安竖井外的代理人阿拉克塞。', '焚烧干枯的尸体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10346, '返回地狱岩床', '$n，听说你早已证明自己是个合格的狮鹫骑士了。现在，我们正好需要你的力量，来协助地狱岩床附近的作战。你怎么说，$c？还想再来几次飞行吗？', '地狱火半岛破碎岗哨的狮鹫骑士维比洛要求你杀死20个甘尔葛苦工和5个莫尔葛监工，并摧毁5门邪能火炮。', '这次进展如何?你状况很不错喔……或许好到甚至可以进行下一个回合!', '在这个深渊沙洲上仍然有许多的目标，$N。当你准备好进行下一回合时找只狮鹫兽吧。', '', '去地狱火半岛找破碎岗哨的狮鹫骑士维比洛。', '', '', '摧毁邪能火炮', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10347, '返回地狱岩床', '$n，你已经准备再次去突袭地狱岩床了吗？我担心如果我们不继续向那里的燃烧军团施加压力，一旦他们增强了要塞的军力，大批的恶魔就会从北边袭击我们。$B$B你觉得呢，$c？你愿意乘坐驭风者，再次去轰炸地狱岩床的燃烧军团吗？', '地狱火半岛机甲残骸的空军指挥官布拉克要求你杀死20个甘尔葛苦工和5个莫尔葛监工，并摧毁5门邪能火炮。', '其它的双足飞龙飞行员对你赞扬极高，$N。你在深渊沙洲上的击杀得到了相当多的分数。保持好成绩!', '军团一定不认为他们在这深渊沙洲的高顶上是安全的。我们一定要不断的攻击他们!', '', '去地狱火半岛的机甲残骸找空军指挥官布拉克。', '', '', '摧毁邪能火炮', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10348, '新的机遇', '我听说一群来自艾泽拉斯世界的“德鲁伊”对生态圆顶技术非常感兴趣。$B$B塞纳里奥远征队的代表希望得到生长在圆顶内的植株，尤其是象牙铃笼草，这种植物\r\n具有良好的医疗效果。中央生态圆顶的大型植株下就分布着成簇的象牙铃笼草。$B$B如果你愿意替我采集这种草药的话，我就和你分享利润。', '收集15株象牙铃笼草，然后向中央圆顶哨站的玛尔达德复命。', '有趣的选择，对吧?这个治疗的效果最好是很惊人。我可是为这个相貌平凡的花定了很高的价格呢。', '你设法去采取这些药草了吗?', '', '去虚空风暴找中央生态圆顶的玛尔达德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10349, '缚地者', '你应该把这块水晶碎片交给缚地者。她跟你一样……总是喜欢思考，并以揭开一个又一个的谜团为乐。$B$B其实在我看来，她倒是根本不用去想那么多事的。$B$B你把这块水晶碎片交给她吧，然后，为了弄清坠星山事件的真相，她肯定会丢一堆麻烦的事情给你去做的。', '将火红水晶碎片交给地狱火半岛塞纳里奥哨站的缚地者加兰蒂娅·夜风。', '噢，太好了!我一直等待把那件东西弄到手，但是塔拉希恩一直拖拖拉拉的。$B$B他应该是到那去帮我调查坠天山脉发生了什么事。相反的他只是不断的派你这种可怜的傻瓜 - 别生气 - 上去那里送死。$B$B假如你给我水晶，或许我能找到在它与戈罗西之间的关联。', '那就是来自坠天山脉上大水晶裂片的一部分吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10351, '自然的治愈', '一定是水晶散发出的邪恶力量将那些山丘巨人吸引到周围，而且还令它们发狂了。$B$B那块水晶实在太大了，我们根本没办法把它移走，毁掉它似乎也不太现实……不过，我想我知道一个办法，至少可以驱散它的力量。$B$B我已经在坠星山的水晶西北角布置了一个法阵。你将这粒种子带到法阵去，引导它蕴涵的魔法能量，通过细雨、骄阳和轻风这些自然的力量治愈那片土地。$B$B不过，$N，你一定要小心，我可以感觉到有一股外界的力量……邪恶的力量盘踞在那里！', '在缚地者法阵中使用新生之种，治愈水晶周围的土地。然后返回地狱火半岛的塞纳里奥哨站，向缚地者加兰蒂娅·夜风汇报情况。', '哥利亚森?计算者帕萨雷恩?$B$B凯尔萨斯!?$B$B凯尔萨斯王子也有参予这件事?$B$B<缚地者感到愤怒。>这么做他简直是疯了!从空中丢下巨大的水晶并且毁坏大地这种事情只有疯子才做的出来!$B$B我可以向你保证，假如他们的部队还想尝试任何进一步的行动那么塞纳里奥远征队将会反击回去直到类似的事件不再发生。$B$B我们欠你的人情实在太多了，$N。', '有用吗?你学到了什么?你找出是谁或者什么东西在背后主导发生在坠天山脉的事件吗?', '', '去地狱火半岛找塞纳里奥哨站的缚地者加兰蒂娅·夜风。', '治愈坠星山', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10352, '捐献毛料', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '我们现在接受毛料的捐赠。只要捐赠60块毛料，暴风城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。', '', '去找泰达希尔的莱顿·暗影。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10353, '贪婪者阿克努斯', '两天前，我和阿拉克塞奉命来到乌提斯。我们的任务是找到并消灭虚空领主阿克努斯。我们一路追踪着他来到这座矿井，发现他一直在这片区域吸取其它生物体内的能量。$B$B在与阿克努斯初次交战的过程中，我和阿拉克塞失散了。眼下我身负重伤，被困在这里动弹不得。但任务绝不能就这样失败！$B$B如果你能消灭阿克努斯的话，指挥官一定会对你表示感谢的。你愿意接受这项任务吗？我的镜像会协助你作战。', '虚空风暴瑟安竖井的代理人亚希克斯要你杀死贪婪者阿克努斯，然后向虚空风暴维序派哨站的指挥官阿米尔复命。', '亚希克斯呢?他还健在吗?$B$B我们只好希望如此了。我无法让增援部队回到他们那里……复仇军现在占领了整个地区。$B$B抱歉，我差点忘记你的报酬了。', '报出名来，凡人?报上你的名来?', '', '去虚空风暴找维序派哨站的指挥官阿米尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10354, '捐献丝绸', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在这个社区中的地位无疑将大大提升!那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。', '', '去找泰达希尔的莱顿·暗影。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10355, '枯萎的血肉', '我们必须搞清楚灾害的波及范围究竟有多广。你带回的孢芽来自于某个泥沼巨人。沼泽领主是泥沼巨人的近亲，但是他们的体型较大，足以抵御困扰发生在泥沼巨人身上的衰竭现象。$B$B我们最好查明死亡泥潭的水位变化是否影响到了居住在那里的其它生物。$B$B返回死亡泥潭，替我取回一些多头蛇的样本和沼泽领主的样本。', '将5份干燥的多头蛇样本和5份枯萎的沼泽领主样本交给泰雷多尔的鲁埃姆。', '<洛安玛检验了那些样本，看起来很忧伤。>$B$B这正是我所担心的，$N。逐渐干枯的环境对那些从没想过要住在沼泽以外的生物造成很大的负担。我们只好继续观察该区域然后跟塞纳里奥远征队协商看看我们能做些什么。', '你能够去收集这些样本吗?', '', '去赞加沼泽找泰雷多尔的鲁埃姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10356, '捐献魔纹布', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '我们的魔纹布储量很低，而你可以帮助我们补充库存!如果计算整个社区所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被铁炉堡的矮人广为传颂，这一点我可以向你保证!$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。', '', '去找秘蓝岛的度戈鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10357, '捐献符文布', '', '', '太棒了―我向你保证，这些一定能派上用场。再次感谢你的帮助!如果没有你的话，我们肯定会一筹莫展的。$B$B鉴于你一贯的慷慨，我会欣然接受你随时捐赠更多的符文布。请及时与我联系，我个人可以确保你所做的好事一定会被广为传颂!', '$N，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$B$B如果你愿意的话，请把你多馀的符文布捐献给我。我们现在接受一次60块符文布捐赠。', '', '去找秘蓝岛的度戈鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10358, '更多的符文布', '', '', '$N―如果没有像你这样的英雄为暴风城亲力亲为的话，我们肯定会碰到很多麻烦。感谢你为我们付出的努力!', '你好，$N!我们的符文布一直比较紧缺，如果你可以省出一些符文布来给我们的话，我们总是表示欢迎的。要是你可以再给我们20块符文布，那么我可以保证，你一定会因为对于暴风城的贡献而被大家认同。$B$B随时欢迎你捐献符文布。', '', '去找秘蓝岛的度戈鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10359, '捐献毛料', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '我们现在接受毛料的捐赠。只要捐赠60块毛料，暴风城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。', '', '去找永歌森林的索瑞姆·轻歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10360, '捐献丝绸', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '和其它纺织材料一样，我们的丝绸库存也已经降到了历史最低点。如果有足够的补给，我们就可以达成预期的目标。$B$B如果你愿意将丝绸作为礼物送给我们的话，那你在这个社区中的地位无疑将大大提升!那么，要是你有60块丝绸并且愿意把它们捐出来，那现在就可以给我了。', '', '去找永歌森林的索瑞姆·轻歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10361, '捐献魔纹布', '', '', '太好了!我们感谢你慷慨的捐赠，$N!', '我们的魔纹布储量很低，而你可以帮助我们补充库存!如果计算整个社区所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被铁炉堡的矮人广为传颂，这一点我可以向你保证!$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。', '', '去找永歌森林的索瑞姆·轻歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10362, '捐献符文布', '', '', '太棒了―我向你保证，这些一定能派上用场。再次感谢你的帮助!如果没有你的话，我们肯定会一筹莫展的。$B$B鉴于你一贯的慷慨，我会欣然接受你随时捐赠更多的符文布。请及时与我联系，我个人可以确保你所做的好事一定会被广为传颂!', '$N，你对于我们的布匹储量做出了巨大的贡献。我们正在尽力补充我们的物资，而我要告诉你的是，现在我们最需要的是符文布。我们的符文布储量实在是太匮乏了，希望你能一如既往地帮助我们。$B$B如果你愿意的话，请把你多馀的符文布捐献给我。我们现在接受一次60块符文布捐赠。', '', '去找永歌森林的索瑞姆·轻歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10363, '更多的符文布', '', '', '$N―如果没有像你这样的英雄为暴风城亲力亲为的话，我们肯定会碰到很多麻烦。感谢你为我们付出的努力!', '你好，$N!我们的符文布一直比较紧缺，如果你可以省出一些符文布来给我们的话，我们总是表示欢迎的。要是你可以再给我们20块符文布，那么我可以保证，你一定会因为对于暴风城的贡献而被大家认同。$B$B随时欢迎你捐献符文布。', '', '去找永歌森林的索瑞姆·轻歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10365, '关闭法力熔炉：艾拉', '你取得的成就完全出乎我们的意料。法力熔炉：艾拉是凯尔萨斯硕果仅存的一座法力熔炉。它位于此地西北方的浮岛上，不过你得绕一大圈才能到达那儿。关闭最后这座法力熔炉。$B$B控制水晶由工头阿扎拉德掌管。据我们所知，法力熔炉：艾拉是凯尔最后一处能量来源，必定驻派了重兵把守。换做是我的话，我会叫上一帮朋友共同转至。$B$B唔……阿扎拉德。辛多雷取这样的名字真是古怪。', '转至法力熔炉：艾拉，从工头阿扎拉德手中夺得艾拉控制水晶。对法力熔炉：艾拉的控制台使用水晶关闭法力熔炉。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '燃烧军团与凯尔合伙?嘿!听到这情报沃蓝索将会很高兴。$B$B你认为来自艾泽拉斯的数千位朝圣者想要与燃烧军团有关联吗?我认为不会喔!', '你完成了我要求你的任务了吗，$N?', '', '去虚空风暴找52区的间谍大师萨罗迪恩。', '', '关闭法力熔炉：艾拉', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10367, '叛徒', '在每个被奴役的破碎者部族中，必定有一位叛徒作祟。这个卑鄙的家伙为了得到力量不惜出卖自己的同胞。$B$B沙纳尔废墟中心的阶梯顶部有一间小屋。那便是背叛者的居所。$B$B他现在恰好不在，如果你有耐心的话，可以悄悄地潜进去。小屋中有个箱子，里面的钥匙可以打开囚禁残冠长者的镣铐。把钥匙带回来给我。$B$B千万小心，无情的阿尔泽斯就在小屋附近徘徊。', '沙纳尔废墟的纳拉杜要你在附近的小屋中找到沙纳尔钥匙。', '感谢你，$N。我的人民很快就会获得自由，感谢你。', '你拿到钥匙了吗，$N?', '', '去地狱火半岛找沙纳尔废墟的纳拉杜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10368, '残冠长者', '残冠长者被囚禁后，氏族的灵魂便陷入了绝望。带上这把钥匙，去搭救残冠长者。$B$B救出抚风者莫洛德、召火者阿库鲁和唤水者埃伊兰。一旦他们重获自由，灵魂就会返回残冠氏族。', '搭救被囚禁在沙纳尔废墟的抚风者莫洛德、召火者阿库鲁和唤水者埃伊兰。完成任务后向纳拉杜复命。', '我能感觉到，$N!精灵们要回归我们身边。', '告诉我，$N。那些崔互德长者是否已经被释放了?', '', '去地狱火半岛找沙纳尔废墟的纳拉杜。', '释放抚风者莫洛德', '释放召火者阿库鲁', '释放唤水者埃伊兰', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10369, '阿尔泽斯之死', '没错，元素的灵魂已经回到了我们身边！虽然我们不如从前那样强大，但是使用得当的话，一点点魔法都会发挥巨大的功效。$B$B阿尔泽斯的主子赐予了他可怕的力量。带上这根法杖，它曾是残冠氏族力量的象征。利用它对付阿尔泽斯，法杖能让阿尔泽斯的力量暂时消失。趁机杀死他，我们才能获得真正的自由！', '对无情的阿尔泽斯使用残冠长者法杖，趁阿尔泽斯失去力量时杀死他。完成任务后向沙纳尔废墟的纳拉杜复命。', '没错，$N。我曾经是大地守卫者纳拉杜。$B$B就是我背叛了其它的崔互德长者换取力量的空泛诺言。如果你想的话，你现在就能轻视我。重要的是我的部族再一次得到自由，而精灵们也已经回到我们身边。$B$B我无法再被部族的其它人接纳，但是我现在能安稳地死去了。愿大地之灵能够在我的兄弟中找到一位新的服侍者。', '完成了吗，$N?阿尔塞斯死了吗?', '', '去地狱火半岛找沙纳尔废墟的纳拉杜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10380, '黑暗的契约', '$N，两个最危险的敌人已经结为同盟，而我们竟然一无所知！$B$B如果是占星者故意隐瞒这个消息的话，我并不会为此感到惊讶。但是，我们必须面对现实。燃烧军团已经和凯尔萨斯的日怒军团站到了同一阵线上。$B$B凯尔萨斯能够利用风暴要塞的科技，肯定和燃烧军团的恶魔有关。根据欧雷里斯的指示，我命令你立即消灭他们。', '图鲁曼的营地中的凯兰恩要你杀死6名甘尔葛迁跃修理师、3名命运之女和3名莫尔葛空间主宰。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '那时就完成了。我们来这里，奉我们大师们的命令来猎杀它们。完全不留馀地。$B$B有时会让你心存怀疑。', '你完成任务了吗，$N?', '', '去虚空风暴图鲁曼的营地找凯兰恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10384, '复仇军的数据', '仔细查看你四周，这台传送器附近应该有一份复仇军数据单元。找到这份数据单元，取出里面的内容。$B$B然后立刻将它带回传送器面前！', '复仇军前沿基地中的复仇军发射器 - 塞塔所投射出来的指挥官阿米尔的影像要你带回复仇军数据单元。', '<你将数据机体交出让阿密尔可以阅览这个计画。>$B$B没事……该死!他们是很聪明没错但是绝没有阿密尔那么聪明!$B$B我将要求你去做的事情非常危险。要是你不想继续的话我可以理解，凡人。', '你拿到数据机体了吗?', '', '去虚空风暴的复仇军前沿基地用复仇军发射器塞塔找到指挥官阿米尔的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10385, '脑部损伤几率：高', '复仇军利用一种名叫传达者的东西在各个前线基地之间传递消息。$B$B想要发现并解读传达者携带的信息，只有一个办法。不幸的是，这样做很可能使你受到无可挽回的脑部损伤。$B$B如果你仍然有兴趣的话，就转至前线基地杀死复仇军虚灵，取出他们的精华。饮下虚灵精华后，你就能暂时看见复仇军传达者，精华的有效时间足以让你摧毁传达者并解读它携带的信息。', '复仇军前沿基地中的复仇军发射器 - 塞塔所投射出来的指挥官阿米尔的影像要你带回15份复仇军中继数据。', '护国者之所以存在的原因现在完全了解了。$B$B复仇军不是到这里猎补迪曼修斯!他们想在这里操控虚无!$B$B他们在这个法力熔炉里操作虚无能量以结合他们自己的能量成为一种叫做奈萨斯潜猎者的生物。$B$B他们毫无疑问地使用一台原始加速器去完成转化过程。', '你拿到传达资料了吗?', '', '去虚空风暴的复仇军前沿基地用复仇军发射器塞塔找到指挥官阿米尔的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10389, '痛苦与黑暗', '你好，$N。我破译出了燃烧军团的信件，发现了这些恶魔进攻地狱火半岛的战略计划。似乎有一大群可怕的恐惧魔聚集在了西边的阿苟纳之池附近。我们绝对不能允许这样一支庞大的军队来攻击我们。你必须赶到那里去，杀掉那些该死的恶魔，削弱他们的力量。', '魔导师文森特·血鹰要你在阿苟纳之池杀掉10个恐惧魔。', '太棒了，$N。我就知道你会凯旋归来!军团离失败越来越接近了!', '嗯，$C - 你打败恐惧恶魔了吗?', '', '去地狱火半岛找萨尔玛的魔导师文森特·血鹰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10390, '铸魔营地：暴虐', '$N，我们有理由相信最东边的铸魔营地还没有完全建造好。燃烧军团的甘尔葛仆从正在日夜赶工让营地运作起来，我们必须阻止他们。$B$B去东边的铸魔营地：暴虐，杀掉10个甘尔葛仆从。把他们的主人剃刀电锯的徽记给我带回来——燃烧军团的魔能机甲铸造计划必须停止！', '萨尔玛的纳兹格雷尔命令你攻击铸魔营地：暴虐，杀死10个甘尔葛仆从，然后将剃刀电锯的徽记带回去交给纳兹格雷尔。', '做得好，$C，那是我们需要担心的炼冶场中较规模的一个。这会让军团花一些时间来取回这些设备备份及照料。你刚为我们买到了我们缺乏的东西', '快点，$C，我们得在这些恶魔建造完成前让黑色祭坛停工!', '', '去地狱火半岛找萨尔玛的纳兹格雷尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10391, '军团的火炮', '第二个铸魔营地：狂乱位于萨尔玛的东北边。恶魔们将一些邪能火炮部署在了山脉地区——他们将攻击目标直接瞄准了我们！你必须进入到营地中毁掉这些邪能火炮。$B$B$N，你必须引爆所有的邪能火炮，否则燃烧军团仍会利用这些该死的东西来对付我们！', '摧毁铸魔营地：狂乱中的3座邪能火炮I型，然后返回萨尔玛向纳兹格雷尔复命。', '我知道你很勇敢，$N，但这次你超越了你自己!我们听到那些可怜的火炮从这里爆炸!那应该可以让军团们学到别低估了杜隆塔尔之子!', '军团随时都有可能对我们发射，$N!你得去毁掉那些该死的火炮!', '', '去地狱火半岛找萨尔玛的纳兹格雷尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10392, '深渊之门', '我们为你感到荣耀，$N。不过现在我们必须在燃烧军团恢复实力之前再给他们一次重击！萨尔玛的北边就是登陆场：歼灭，里面有一座传送门负责传送燃烧军团的增援军。$B$B你必须设法使它过载，把它炸成灰烬。开启传送门的钥匙在登陆场指挥官阿利萨玛尔身上。杀掉他，找到钥匙，用钥匙打开传送门后炸毁它。愿酋长祝福你。', '杀掉阿利萨玛尔，找到燃烧军团传送门钥匙，利用它毁掉怨恨符文，然后返回萨尔玛向纳兹格雷尔复命。', '赞美先祖，你做到了，$N!军团遭到了重大的攻击 -', '快点，$N。传送门每开一秒，就多一个邪恶的恶魔被带到这个世界里!', '', '去地狱火半岛找萨尔玛的纳兹格雷尔。', '', '关闭燃烧军团传送门', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10393, '邪恶的计划', '信上的字是使用某种黑暗而潦草的笔迹书写的，难以辨认。你盯着看的时间越久，那些符号在你的眼前就变得越发扭曲，似乎要熊熊燃烧起来。在萨尔玛只有一个人能辨认出这样邪恶的笔迹——血精灵魔导师文森特·血鹰。', '将燃烧军团信件交给交给萨尔玛的魔导师文森特·血鹰。', '你把这份文件带给我是对的。这可能是一份要求制造更多恶魔劫夺者的命令-或者新的攻击计画!我需要一些时间才能解读这份命令。去吧。当我有更进一步的了解我会叫你来的。$B$B<在你转身离开的时候博学者血鹰对你点了点头。>$B$B你是一个行家，$N。我应该会很期待听到你的新事迹。', '我没有太多时间可以浪费，$C。这就是让你要烦我的东西吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10394, '铸魔营地：暴虐', '听仔细了，$N。我们正在调查前方山脉中的燃烧军团营地。我们有理由相信这些所谓的“铸魔营地”是他们铸造那些该死的魔能机甲的地方。$B$B你可以看到最近的一处目标，也就是西边的铸魔营地：暴虐。情报表明这座营地仍在建造中。如果你能杀掉甘尔葛仆从和他们的主人剃刀电锯，我们就可以阻止燃烧军团铸造魔能机甲的计划！', '杀掉铸魔营地：暴虐的剃刀电锯和10个甘尔葛仆从，然后返回荣耀岗哨向巴洛克元帅复命。', '好吧，我必须说，我很感动，$N。我之前根本不认为你有勇气完成这个任务。做得好。真的做得很好。', '不要告诉我你害怕了，$C。要是他们完成了炼治场的兴建，你就有比那些恶魔劫夺者更多需要担心的事!去吧!', '', '去找军团前线的巴洛克元帅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10395, '邪恶的信件', '信上的字是使用某种黑暗而潦草的笔迹书写的，难以辨认。你盯着看的时间越久，那些符号在你的眼前就变得越发扭曲，似乎要熊熊燃烧起来。荣耀堡只有一个人能辨认出这种古老的笔迹，那就是德莱尼秘法师克雷夫。$B$B将燃烧军团信件交给荣耀堡的位面占卜者克雷夫。', '将燃烧军团信件交给荣耀堡的位面占卜者克雷夫。', '你很幸运的拦截到了这封书信，$N。虽然这得花费我一点时间来解译，但我已经能够感受到从这份卷轴里发出的恨意及急迫。我担心军团对这个大陆的真正目的将会很快显露出来……$B$B给我一点时间辨认这个字迹。$B$B<星移占卜师克里开始阅读这份恶魔书信。>', '这是什么，$C?我感觉你找到的东西说明了一场即将到来的灾难。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10396, '我的敌人的敌人……', '我们的第二个目标是铸魔营地：狂乱，它就在铸魔营地：暴虐的西边。但现在的问题是，恶魔们将许多邪能火炮直接瞄准了部落的前哨基地萨尔玛！尽管这听起来有些奇怪，但我们确实需要部落帮忙守住黑暗之门的战线。因此绝对不能让萨尔玛失守，你必须在燃烧军团击败我们的同伴之前毁掉这些火炮！', '摧毁铸魔营地：狂乱中的3座邪能火炮I型，然后返回荣耀岗哨向巴洛克元帅复命。', '我一定要为你鼓掌，$N，你是个天生的斗士!那些部落老粗可能永远都不知道他们曾经离死亡有多接近。使用真正的身份来代表你的敌人出面干预。就是这种信誉及奉献将联盟团结起来!$B$B<战场元帅布洛克俐落的向你致敬。>', '军团随时都有可能开始炮轰部落，$N!你得摧毁那些该死的火炮!', '', '去找军团前线的巴洛克元帅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10397, '登陆场：歼灭', '嗯，我们锁定了燃烧军团的最后一座营地——登陆场：歼灭。它位于铸魔营地：狂乱的西北边，在里面有一座传送燃烧军团援军的传送门！$B$B你必须将那座传送门毁掉，阻止燃烧军团利用它输送更多的恶魔。传送门的钥匙在那里的头目阿利萨玛尔身上。将钥匙夺过来，炸毁那道门！', '杀掉阿利萨玛尔，找到燃烧军团传送门钥匙，利用它毁掉怨恨符文。', '做得好!这应该会大大削弱那些试着想要悄悄偷袭我们的恶魔数量。感谢不足以表达我对你提供帮助的谢意，$N。', '你关闭传送门了没，$N?当你在这拖拖拉拉的同时，就有更多的恶魔进入了外域!', '', '去找军团前线的巴洛克元帅。', '', '关闭燃烧军团传送门', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10399, '黑暗之心', '正如我担心的那样。你之前杀死的那个恶魔阿利萨玛尔听命于一个神秘的燃烧军团领主，残酷的阿拉修斯。这个恶棍似乎在阿苟纳之池附近聚集了一支可恶的恐惧魔部队。$B$B你必须赶在他们袭击我们之前去那里杀掉恐惧魔。不过你一定要小心，朋友——阿苟纳之池在一个充满剧毒的山谷中，你可以在西北边找到这个邪恶的地方，就在地狱火堡垒的那一边。$B$B圣光与你同在， $N。', '在阿苟纳之池杀掉10个恐惧魔，然后向荣耀堡的位面占卜者克雷夫复命。', '我预见了这场伟大的胜利，$N。今日，神圣的纳鲁偏爱你。', '我感觉到你心中一股日渐增长的黑暗，$C。你正视过你的恐惧吗?或是它还在阿葛纳尔之池那等待着你呢?', '', '去地狱火半岛找荣耀堡的位面占卜者克雷夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10400, '霸王', '$N，尊敬的位面占卜者说你冒着生命危险发现了新的敌人。如果克雷夫说得没错，那这个“残酷的阿拉修斯”就无疑是个非常强大而又邪恶的敌人了。$B$B你愿意帮助我们吗，$N？你愿意去对付这个燃烧军团的头目，让他受到圣光的制裁吗？如果你愿意的话，就去阿苟纳之池找到他吧。如果你不去杀掉他，他的邪恶力量也终究会找到你。', '转至阿苟纳之池，除掉残酷的阿拉修斯，然后返回荣耀堡向远征军指挥官达纳斯·托尔贝恩复命。', '赞美圣光，我就知道你可以的!阿拉萨尔斯和他的爪牙消失了!很快地，军团就会滚回家，我们将再度的安全了。接着，当正义被彰显，我们也就可以回家。$B$B谢谢你，$N - 联盟及洛萨之子今日以你为荣!', '告诉我，$N，任务完成了吗?军团领主被制伏了吗?', '', '去地狱火半岛找荣耀堡的远征军指挥官达纳斯·托尔贝恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10405, '破坏行动', '我们必须摧毁将复仇军的虚灵变异为节点猎手的特殊机器。但是这种机器是虚灵科技的产物，直接破坏原质加速器根本不起作用。我们得破坏那些传输魔法能量的管道。$B$B眼下还缺一份材料，没有它，我无法制造能使管道能量超负荷的设备。为了校准这台设备，我要你从尚未变异的虚灵执政官或主宰身上拿来他的裹布。', '复仇军前沿基地中的复仇军发射器 - 塞塔所投射出来的指挥官阿米尔的影像要你带回1条精制复仇军裹布。', '太好了!现在校准装置。', '你拿到裹带了吗?', '', '去虚空风暴的复仇军前沿基地用复仇军发射器塞塔找到指挥官阿米尔的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10406, '传达信息', '我打算派一名爆破师去放置扰流器。希望你能在他安装扰流器时保护他。$B$B一定要确保他的安全！他\r\n会以全息影像的形式执行这项任务，因此遭到攻击时他根本无法反抗，但是全息影像是可以被摧毁的！$B$B完成任务后回来向我复命。', '复仇军前沿基地中的复仇军发射器 - 塞塔所投射出来的指挥官阿米尔的影像要你护送维序派爆破师转至法力熔炉：乌提斯的管道，并在他破坏时保护他的安全。', '感谢你，他们的计画泡汤了!现在只剩下一件事情……萨哈达尔。', '他一定得成功!', '破坏复仇军管道', '去虚空风暴的复仇军前沿基地用复仇军发射器塞塔找到指挥官阿米尔的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10407, '索克雷萨之影', '索克雷萨，这个声名狼藉的艾瑞达人统领着整个虚空风暴的燃烧军团部队。单是提起他的名字，就足以令大多数德莱尼人吓得发抖。索克雷萨驻扎在西北方的某座浮岛上，只有他最信任的军官才有资格与他会面。$B$B你必须夺得传送石才能进入那座浮岛，这可不是件容易的事。传送石的上半部在铸魔基地：湮灭的熔炉主管莫鲁格手中，而下半部则由铸魔基地：炼狱的希尔洛斯保管。', '52区的学者卡尔亚要你从铸魔基地：湮灭的熔炉主管莫鲁格手中夺得索克雷萨之石的上半部，并从铸魔基地：炼狱的希尔洛斯手中夺得索克雷萨之石的下半部。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '你对我们理想的奉献足以作为模范，$N。现在我们已经拥有了索奎萨尔的传送石，只剩下一件事情需要去做。', '你拿到索奎萨尔的传送石了吗，$N?', '', '去虚空风暴找52区的学者卡尔亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10408, '节点之王萨哈达尔', '我这里还有一个扰流器，它能摧毁环绕着萨哈达尔的三根管道。一旦管道尽数被毁，萨哈达尔身上的保护力场就会消失。$N，那样的话，他会爆发出你前所未见的狂暴力量，你将与他展开激烈的战斗。$B$B如果你决意要铲除萨哈达尔，我就将这个扰流器交给你。', '复仇军前沿基地的复仇军发射器 - 塞塔中投射出来的指挥官阿米尔的影像要你使用维序派扰流器关闭萨哈达尔防御力场，然后杀死节点之王萨哈达尔。', '已经一千年了，或许更久，自从萨哈达尔开始他的圣战以消灭所有挡住他的事物。我几乎不能相信这是它的最后……你已经为我们所有人做了件伟大的事，$N，而为此你将被奖赏。', '他……他真的死了吗?被杀了?', '', '去虚空风暴的复仇军前沿基地用复仇军发射器塞塔找到指挥官阿米尔的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10409, '重创燃烧军团', '在面对拥有强大力量的艾瑞达人时，以数量制胜恐怕是无稽之谈。他们的腐蚀力足以令凡人迅速堕落，只有意志最坚定的勇士才敢于面对这种挑战。$B$B召集你最亲密和最优秀的战友，带上这块传送石，转至位于铸魔基地：湮灭和铸魔基地：炼狱之间的登陆场：霸王。欧雷里斯和卡尔亚会在索克雷萨之座等你，我还会派阿德因一同去帮助你。$B$B圣光必胜，$N！让索克雷萨消亡吧！', '高阶祭司伊沙娜要你转至虚空风暴西北角的军团传送控制器，利用它传送到索克雷萨之座，然后击败索克雷萨。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '完成了，$N。索奎萨尔已经被消灭。$B$B我和其它人将自我们的伤口恢复，$N。但是，索奎萨尔魔法的愤怒远非年轻的凯岚所能承受的。即使是我最强大的祷言也无法唤起他。$B$B那是不堪忍受的遗憾，一个如此年轻的人在战斗中阵亡。不过，最后他的强大意志能使它从军团的腐败中恢复，则是我们感到欣慰的地方。', '愿圣光与你同在，$C。', '重创燃烧军团', '去沙塔斯城找奥尔多高地的伊沙娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10410, '伊沙娜的帮助', '是时候面对索克雷萨了，$N。对我们来说，挑战艾瑞达人的领袖并不是一件容易的事。如果准备得不够妥当，那么任何微小的错误都会让我们付出生命的代价。$B$B带上索克雷萨的传送石，转至沙塔斯城的永恒圣光神殿，去找高阶祭司伊沙娜。她会告诉我们要如何应对当前的情况。', '返回沙塔斯城奥尔多高地的永恒圣光神殿，将索克雷萨的传送石交给高阶祭师伊沙娜。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '索奎萨尔……我记得那个名字。他曾经是一位着名的圣光战士，而骄傲是他唯一的瑕疵。', '什么困扰着你呢，孩子?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10411, '电磁冲击！', '你在法力熔炉的废墟四周可以发现大量从迪门修斯体内渗透出的流质。滴水的淤泥怪已经占据了乌提斯外围的池塘，池塘正下方就是复仇军的前线基地，基地中到处都是一种名叫空灵废弃者的流质生命体。$B$B要对付这些软泥怪，最好的办法就是用电磁冲击枪将它们轰成小水珠。利用这瓶药剂强化你的电流攻击能力吧，如此一来，那些软泥怪就会衰变成原始的形态。消灭那些水珠！', '虚空风暴维序派哨站的研究员纳乌德要你摧毁30只空灵废弃者水珠和30只滴水的淤泥怪水珠。', '我希望不会太迟。你有发现附近或是在虚无荒废者被吸入的地区有任何异常的大型泥浆怪的出现?', '淤泥怪和荒废者都带有极毒。如果不予理会的话，他们将形成凝结的虚无恐兽!', '', '去虚空风暴找维序派哨站的研究员纳乌德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10412, '火翼徽记', '凯尔萨斯·逐日者已将我们视为一个巨大的威胁，这早就不再是什么秘密了。让我们勇敢地面对他们吧，并不是所有银月城的辛多雷都愿意追随凯尔萨斯的。$B$B此外，我们与凯尔萨斯·逐日者之间的冲突也早已不只停留在文字与纸面上，这也不是秘密了。现在，占星者与凯尔萨斯的军队只要一见面就会交战。而你唯一向我们证明自身价值的方式，就是让我们分享你的力量，$N。$B$B凯尔的低阶追随者身上都带有用于标识其阶级的火翼徽记。将它们带回来给我。', '沙塔斯城的魔导师菲亚琳要求你给她带回10个火翼徽记。$B$B为占星者完成任务将会使你在奥尔多阵营中的声望等级降低。', '做得好，$N。你或许可以证明是一个有用的盟友。', '继续，$N。请说。', '', '去找泰罗卡森林的魔导师菲亚琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10413, '虚空的软泥', '你小心地将虚空软泥留下的泥浆装入瓶中。$B$B维序派哨站的研究员纳乌德一定会对此感兴趣的！快把这瓶虚空软泥带给他吧！', '将一瓶虚空软泥交给虚空风暴维序派哨站的研究员纳乌德。', '什么!?你跟一个虚无恐兽交手?而且还活着?!难以置信!$B$B这个样品比等重的黄金还有价值，像这样的发现应该要好好奖励。', '哇，你看起来有点脏……你是掉进什么地方里面?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10414, '单枚火翼徽记', '', '', '太好了……凯尔萨斯的部队人数持续缩减而我们的数目持续上升。$B$B<这个任务可以重复进行直到声望阶级达到尊敬。>', '即使是最小的贡献也会被注意到，$N。我们的敌人很多，但是我们将战胜他们!', '', '去找泰罗卡森林的魔导师菲亚琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10415, '更多火翼徽记', '', '', '太好了!反抗我们的人都将被消灭!$B$B<这个任务可以重复进行直到声望阶级达到尊敬。>', '你最近为我们做了什么，$N?对凯尔萨斯的战争是不会自己开始的，你知道吗?', '', '去找泰罗卡森林的魔导师菲亚琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10416, '能量的聚合', '奥法宝典并不是一般的描写或记载奥术魔法相关内容的书籍，它们蕴涵着某种自身固有的能量。而我可以将这种能量吸收并转化，合成为一枚奥术符文。$B$B如果你在冒险的旅途中找到奥法宝典的话，可以把它带来给我，我愿意帮你将其转化成这种符文。只有最强大的施法者身上才会带着我所说的奥法宝典。而在外域，最强的施法者一般就是指凯尔手下的血精灵，但这也并不是绝对的。', '沙塔斯城内的先知沃雷塔尔要求你取得一本奥法宝典。为占星者完成任务将会使你在奥尔多阵营中的声望等级降低。', '像许诺的那样，$N。秘典所有的自然力量，被浓缩成一个符文。', '你拿到秘法宝典了没，$N?', '', '去找泰罗卡森林的先知沃雷塔尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10417, '诊断报告', '无论星界财团在何处搭建新营地，我们都会利用生态圆顶科技。你要知道，我们时常需要在环境恶劣的地方做生意，而生态圆顶的力场能为我们提供可控的、适合生物生存的大气环境。$B$B然而，虚空风暴中的那些暴戾的生命体和多变的气候已经开始毁坏用于维持生态圆顶的装置了，特别是那些我们部署在东边的力场发生器。我已经启动了诊断程序，希望能分析出修复损害的办法。你能帮我取回诊断报告吗？', '取回诊断报告，将它们交给中央圆顶哨站的玛尔达德。', '<玛戴德点头，然后检验诊断结果。>$B$B这真是令人烦恼。损害比我想象的更加严重。我能送一些工具到风暴之尖去开始修理，但是那没用，除非我们能先将损坏设备的东西给隔离。', '你取得诊断结果了吗?', '', '去虚空风暴找中央生态圆顶的玛尔达德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10418, '解决破坏者', '在这片区域收集装置损害的线索时，我在北边的小湖里发现了一些护罩发生器的残骸。我真不明白为什么鳄鱼会对这些设备感兴趣，但我们必须解决这个问题。$B$B星界财团对此的态度非常明确。如果要在装置和鳄鱼之间做出选择的话，那么让这些野兽去死吧。如果你能帮我解决它们，我是不会亏待你的。', '中央圆顶哨站的玛尔达德要你杀死8条钩鳞鳄鱼。', '这地区已经看起来更清楚了。秘境十分有用，但是主要缺点是他们在某些地方刺激繁茂的生长，加速当地生物种类的生长和发展。', '你释放了那些动物的生命了吗?不要误解我，我真的是一个动物爱好者，不过不是当动物们把给予它们食物和庇护的人的手给咬掉的时候。', '', '去虚空风暴找中央生态圆顶的玛尔达德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10419, '奥法宝典', '', '', '包含在这本秘典里的力量是惊人的。然而一个纯正心灵的人却可以轻易的将它压缩成一个符文。', '你拿到更多的秘法宝典了吗，$N?', '', '去找泰罗卡森林的先知沃雷塔尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10420, '净化之光', '这处神殿是外域最为神圣的地点之一。在这里，你可以感受到相当强大的圣光之力，即使是沾染了最邪恶的污迹的物品，也可以在这里得到净化。$B$B最近，你在与恶魔交战的时候，是否曾经获得一些邪能装备呢？把它们交给我，我可以利用圣光的力量将它们净化。', '将一套邪能装备交给沙塔斯城的伊沙娜。$B$B为奥尔多完成任务将会使你在占星者阵营中的声望等级降低。', '看着当令人厌恶的物质瓦解时。看着当金属转为灰尘时。$B$B圣光净化全部事物，只剩下最纯净的躯体。', '你有拿到任何魔化武器没，$N?', '', '去沙塔斯城找奥尔多高地的伊沙娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10421, '邪能装备', '', '', '将恶魔势力从这个世界除净。让圣光照耀大地。', '你今天有拿到任何魔化武器吗?让圣光消灭他们，$N。别让哪些污秽的生物残存在这世界上。', '', '去找伊沙娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10422, '泰拉留斯上尉', '十天前，泰拉留斯上尉带领一小队士兵去了南边的复仇军前沿基地，至今杳无音信。$B$B他们很可能遭到了伏击，说不定已经命丧敌手，但是我的仪器接收到了奇怪的信号。$B$B我认为是求援信号，但是这东西以前出过好几次差错，所以我们也不敢肯定。如果泰拉留斯还活着，他应该是被囚禁起来了。你必须设法营救他，或许牢笼的钥匙就在守卫身上。', '虚空风暴维序派哨站的驯兽者维里迪斯要你找到并营救泰拉留斯上尉。', '谢谢你，$N。泰拉里斯受到了严重的伤害，但是我想它应该可以称过去。$B$B他提及监狱的场所，很像你从中拯救他的那个。监狱充满来自整个宇宙的生物!$B$B当我们准备好可以突破它时，我们会进行联系。联合团已经表示对派遣一些团队并且着手进行一些技术来突破复仇军的封锁感到兴趣。', '你找到泰拉里斯了吗?', '', '去虚空风暴找维序派哨站的驯兽者维里迪斯。', '营救泰拉留斯上尉', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10424, '重要的诊断', '如果玛尔达德的诊断结果正确无误——当然，我相信他不会犯错，那么生态圆顶要有大麻烦了。$B$B看来玛尔达德并没有查明造成这种状况的根本原因。以前也曾发生过生物损坏发生器的情况，但从来都没有这么严重过。$B$B为了安全起见，我打算派你去风暴尖塔的主圆顶发生器运行一次诊断程序，它就在最东端的苏瑟伦生态圆顶上。', '在苏瑟伦生态圆顶发生器旁使用诊断设备，然后将诊断设备报告交给风暴尖塔的贾巴尔。', '这些结果正好符合玛戴德，但是为什么?我能想起的唯一可能解释是一些秘境生成设备已经失效或者失踪。那将使秘境明显地衰弱，并且失去平衡，正如诊断表明的。', '你取得那些诊断了吗?', '', '去虚空风暴找风暴尖塔的贾巴尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10425, '逃离前沿基地', '感谢卡雷什！他差点没把我给撕碎！$B$B你好，我是一名维序派士兵。十天前，我所属的分队奉命外出执行侦察任务。就在我们穿越这座浮岛时，一群复仇军士兵突然袭击了我们。至少我觉得是复仇军干的。他们的能量团颜色与复仇军虚灵相同，只是裹带的颜色有些暗淡。$B$B只有泰拉留斯活了下来，他似乎被单独关押起来了。$B$B我必须返回维序派哨站！你能护送我回去吗？', '护送被俘虏的维序派前锋返回虚空风暴的维序派哨站。', '<指挥官阿密尔露出高兴的表情。>$B$B做的好，新兵!这名士兵可能是攻下复仇军行动的主要关键。', '嗯?', '护送被俘虏的维序派前锋', '去虚空风暴找维序派哨站的指挥官阿米尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10426, '生态圆顶中的花朵', '看看周围，$c！很神奇吧？生命体难以置信地在复苏！虽然这是虚灵的生态圆顶的副产品，但你想想，如果远征队也能掌握这种科技，那将会发挥多大的效用。$B$B我准备和这些虚灵好好协商，看能不能获得这项技术。不过，我想要更直观地了解它对植株的影响力。$B$B这是我制造的调节器，它能将圆顶的能量集中照射在那些鞭笞者身上。你愿意帮我做这项实验，然后告诉我结果吗？', '对法兰伦鞭笞者使用能量力场调节器并观察实验结果，进行10次实验后返回风暴尖塔，向欧瑞恩·月焰汇报情况。', '喔我的天!集中秘境的能量似乎会持续加快它的成长并使它产生强大的侵略性。如果我们真的获得使用这项技术的能力，我们必须确定要正确地校验它。', '你有试着去集中秘境的能量吗?', '', '去虚空风暴找风暴尖塔的欧瑞恩·月焰。', '测试能量调节器', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10427, '生态圆顶中的生物', '你在鞭笞者身上进行的实验取得了令人惊愕的结果，但我还想确认它对动物是否同样有效。$B$B从生态圆顶中的塔布羊身上收集一些信息吧，我想这比研究鞭笞者更为有效。$B$B你可以利用这个标记器，催眠并标记生命力衰弱的塔布羊，便于我追踪它们的生长状况。但是标记器对活蹦乱跳的塔布羊可不起作用，你得先令它们耗尽精力。', '为风暴尖塔的欧瑞恩·月焰标记12只塔布羊。你可以使用塔布羊标记器来标记雄性塔布羊和雌性塔布羊。', '做得好。我将密切注意那些你加上标示的，并且看看是否他们与秘境里其它生命成熟的一样迅速。$B$B只要控制得适当，我们能使用这技术去使外域和艾泽拉斯被毁坏的地区恢复生机。', '你替足够的塔巴克贴上标示了吗?', '', '去虚空风暴找风暴尖塔的欧瑞恩·月焰。', '', '标记塔布羊', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10429, '失控的大自然', '圆顶科技竟然如此强大！当然，$N，我们不能毫无节制地滥用这种力量。$B$B如果生物生长得过于旺盛，肥沃的土地将因此变得贫瘠。$B$B谣传东边池塘中就生活着这种巨型生物，据说有的虚灵商人无聊时就利用那些大型多头怪进行狩猎娱乐。我想要进一步了解这种过度生长的生物，你能取回它的心脏供我研究吗？', '风暴尖塔的欧瑞恩·月焰要你取回一颗巨大的多头怪之心。', '<阿鲁尼收下那颗心。>$B$B就算是那种尺寸的生物，这个心也太大了。它努力跟上生物的庞大身体。我怀疑它可能在达到正常寿命的一半之前就死了。$B$B即使这样做有很大的风险，我决定说服联合团分享他们的技术。现在有太多承诺要放弃。', '你从那个巨大的海蛇身上取得样本了吗?', '', '去虚空风暴找风暴尖塔的欧瑞恩·月焰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10430, '测试原型', '我一直在研制便携式的发生器维修包，供星界财团在气候恶劣的地区使用。虽然当前的设计并非为虚空风暴定制的，但我想问题应该不大。$B$B我准备派一批最优秀的技师在虚空石西边方的边缘生态圆顶对它进行测试。将维修设备交给塔沙尔吧，他知道如何使用它。如果效果不错的话，我们就利用维修包来强化大型生态圆顶的护罩发生器。', '将实验维修设备交给虚空风暴边缘生态圆顶的塔沙尔。', '这个东西看起来有点奇特。加巴绝对不是为了虚空风暴而制造这个东西。$B$B别露出惊讶的表情，$N。跟我们在其它工作的环境比较起来虚空风暴的环境算是温和的了。然而一个失败的秘境总是会令人担心。', '看来你已经取得原型了。是加巴派你来的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10432, '可怕的证据', '你大概也注意到了，法力熔炉：艾拉遍布着燃烧军团的仆从。凯尔萨斯已经与燃烧军团结为盟友。他定然察觉到伊利丹堕入了疯狂的边缘，对魔法的渴求促使他投靠燃烧军团麾下。$B$B如果此事证据确凿，那么这支实力雄厚的联合军队可不容小觑。占星者已经得到确切消息，称法力熔炉的燃烧军团将士们都听从凯尔萨斯的指挥。$B$B将凯尔萨斯的命令交给萨罗迪恩吧。', '从法力熔炉：艾拉的恶魔手中夺得8份凯尔萨斯的命令，将它们交给52区的间谍大师萨罗迪恩。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '这是一件大事，$N。非常大!$B$B沃蓝索将会想要尽快听到这事。', '喔?萨洛迪恩有说什么吗?', '', '去虚空风暴找52区的间谍大师萨罗迪恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10433, '保持伪装', '虚灵都是聪明而机警的家伙，因此我不得不伪装成普通的毛皮商人。事实上我是52区的商业间谍，奉命来到这里评估他们搭建生态圆顶的科技。$B$B我需要你的帮助，$c。你看，必要的时候，我们就会利用非地精的间谍。$B$B我要你伪装成猎手，给我弄些锋牙山猫的毛皮回来，中央生态圆顶内到处都是这种山猫。', '为中央圆顶哨站的舒利·波尔带回10张锋牙山猫的毛皮。', '<休利对你带回来的毛皮露出赞叹的表情。>$B$B这些毛皮品质太好了，真的太棒了!我愿意付给你最高的价钱!多少钱才可以让你继续维持这种服务呢?', '<休利提高了声量以吸引那里的以太族注意。>$B$B有任何毛皮要卖的吗?', '', '去虚空风暴找中央生态圆顶的舒利·波尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10435, '找回货物', '<奥蒂环顾四周，压低了嗓门。>$B$B我想舒利向你提过我们来这里的真正目的吧。当贾森和我在生态圆顶中“狩猎”时，我们会趁机收集掩码生成器的碎片，并将它们藏在猎物的毛皮中。$B$B通常我们都在边缘生态圆顶中猎杀迅猛龙，那地方位于风暴尖塔东北方，离虚空石很近。你能去那里帮我们收集掩码生成器的碎片吗？', '风暴尖塔的针眼奥蒂要你取回10块掩码生成器碎片。', '做的好!计画里最难的部分已经完成了。现在，所有我们需要的是如何将这些带回到52区的方法，并同时吸引塞纳里奥探险队的兴趣。这里应该足够我们自己的需要，加上一点额外的利润。', '你收集到所有东西了吗?', '', '去虚空风暴找风暴尖塔的针眼奥蒂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10436, '全部清理！', '我们必须首先确保这片区域没有其它干扰因素才能进行实验。我是指那些过度生长的蜥蜴类的生物。$B$B<塔沙尔指了指远处的镰牙迅猛龙。>$B$B如果它们在发生器充能时突然冲上去咬一口，天知道会发生什么事。在我担任技师的这些年里，见过不少诡异的事情，例如目睹某些可爱的小动物成长为异型怪兽。', '边缘生态圆顶的塔沙尔要你杀死12只镰牙迅猛龙。', '做得好。看起来一切都就绪了。我们准备要开始了。', '你把测试区域清除了吗?', '', '去虚空风暴找边缘生态圆顶的塔沙尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10437, '毁灭的材料', '虚空领主迪门修斯利用法力熔炉：乌提斯顶部的虚空裂隙进入了我们的世界。这处裂隙使得迪门修斯能在物质世界和扭曲虚空间自由穿行，免疫一切物理伤害。如果我们能切断空灵管道的能量流，迪门修斯将被困在这个位面，再也无法进行相位变换。那样的话，我们就能轻而易举地消灭它了。$B$B要完成这个计划，我们需要你从迪门修斯创造的虚空生物身上收集一些来自虚空领主本体的碎片。', '虚空风暴维序派哨站的达比雷教授要你取回8块迪门修斯的碎片。', '太好了。有了这些碎片，我们就能校准一颗炸弹摧毁奥崔斯上面的虚无导线。随着虚无导线的摧毁，迪曼修斯将无法与虚无连结并变得毫无防御!', '你收集到足够的碎片了吗?', '', '去虚空风暴找维序派哨站的达比雷教授。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10438, '虚空幼龙之翼', '给，$N。带上这些相位扰流器出发吧！维序派的虚空幼龙会将你送到乌提斯上空，然后你要对准空灵管道投掷相位扰流器。$B$B为了彻底摧毁空灵管道，你必须尽可能多地抛下扰流器！$B$B等你准备就绪，就与虚空幼龙谈一谈，它会载你转至目的地的。$B$B如果你没能瞄准目标，浪费了太多扰流器的话，可以回来向我再要一些。', '虚空风暴维序派哨站的达比雷教授要你转至法力熔炉：乌提斯，在顶部的空灵管道附近使用相位扰流器。为了彻底摧毁空灵管道，你必须尽可能多地抛下相位扰流器。只要投掷的距离够近，相位扰流器就会自动依附在空灵管道上。$B$B完成任务后向达比雷教授复命。', '出击的时候到了!随着裂洞消失，迪曼修斯的身体及魔力上变得不堪一击!', '你击中目标了吗?', '', '去虚空风暴找维序派哨站的达比雷教授。', '摧毁空灵管道', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10439, '诸界吞噬者迪门修斯', '你勇敢的行动为阿米尔赢得了有利的时机！他已经调派了萨义德上尉和复仇者部队准备出击。$B$B与迪门修斯决战的时刻就要来临了。$B$B你准备妥当后就联络萨义德。如果他当前没有执行其它战斗任务的话，应该在此地正东方等待你的调遣。$B$B告诉他你已经准备好迎战迪门修斯，他的部队会配合你展开行动！$B$B祝你好运，肉乎乎的朋友！我们奉命追杀迪门修斯已经有千年之久了，胜利就在眼前！', '虚空风暴维序派哨站的达比雷教授要你与萨义德上尉谈一谈，然后跟随他的军队转至法力熔炉：乌提斯，杀死诸界吞噬者迪门修斯！', '一千年来，我们知道的就是战斗。我们已经保护我的人民以免遭受虚无生物及以太族同类的攻击。$B$B现在，我们憎恨的敌人之一已经死亡了 - 终于。$B$B我致上十亿名以太族的感谢，凡人。', '虚无领主怎么样了?', '', '去虚空风暴找维序派哨站的达比雷教授。', '', '与萨义德上尉交谈', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10445, '永恒水瓶', '伊利丹从永恒之井中取出了七瓶水。他将其中三瓶倒入海加尔山颠的湖泊中，由此形成了第二口永恒之井。岁月流逝，剩下的四瓶水已不知去向。$B$B黑暗之门开启后，我们得知伊利丹将两瓶水交给了他的副官凯尔萨斯和瓦丝琪。取回残馀的永恒之水，我们可以利用它打开通往近代或是远古时期的海加尔山的时光通道。我们必须维持海加尔圣战的事件不被改变。', '时光之穴的索莉多米要你从盘牙水库的瓦丝琪那里取回瓦丝琪的水瓶残馀，并从风暴要塞的凯尔萨斯·逐日者那里取回凯尔萨斯的水瓶残馀。', '即使是这么少量的永恒之井水也包含了不可思议的能量。\r\n\r\n我可以清楚的看到与海加尔相关的每个时空……第二个永恒之井的诞生，伊利丹的监禁，世界之树的附魔，还有……没错!海加尔山战役。\r\n\r\n我们必须加快脚步，时间线并不稳定。', '我要求你做的事几乎是不可能办到的，但我仍然希望你可以成功。全靠你了。', '', '去找塔纳利斯的索莉多米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10446, '终极密码', '他们正在火翼岗哨的庭院中制作第二枚魔法炸弹。这枚魔法炸弹的终极密码在火翼岗哨的监工沙尔斯·沃多恩手中。$B$B$N，你必须返回那儿，夺取终极密码。他就在那座最高的塔中。$B$B使用终极密码引爆中央庭院的魔法炸弹，只有这样才能确保奥蕾莉亚要塞的安全。', '米利迪安中尉要你使用终极密码引爆魔法炸弹，然后向泰罗卡森林奥蕾莉亚要塞的杰奈·星语复命。', '你做到了!你拯救了我们!你救了整个艾兰里堡垒!!$B$B随着他们部队的消灭，领导者的死亡以及法力炸弹的摧毁，我们现在能够更自在的呼吸了。$B$B$N，我从来都没有这么忘我过……', '莫瑞狄恩中尉一直都在通报我们有关火翼岗哨的状况。一切都还好吗?', '', '去泰罗卡森林找奥蕾莉亚要塞的杰奈·星语。', '', '引爆魔法炸弹', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10447, '终极密码', '他们正在火翼岗哨的庭院中制作第二枚魔法炸弹。这枚魔法炸弹的终极密码在火翼岗哨的监工沙尔斯·沃多恩手中。$B$B$N，你必须返回那儿，夺取终极密码。他就在那座最高的塔中。$B$B使用终极密码引爆中央庭院的魔法炸弹，只有这样才能确保裂石堡的安全。', '卡乌尼中士要你使用终极密码引爆魔法炸弹，然后向泰罗卡森林裂石堡的图基复命。', '你做到了!你拯救了我们!你救了整个碎石堡!!$B$B随着他们部队的消灭，领导者的死亡以及法力炸弹的摧毁，我们现在能够更自在的呼吸了。$B$B$N，我从来都没有如此忘我过……如此的英勇!请接受这个代表我们所有人的东西。', '丘尼士官一直都在通报我们有关火翼岗哨的状况。一切都还好吗?', '', '去泰罗卡森林找裂石堡的图基。', '', '引爆魔法炸弹', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10449, '药剂师塞兰娜', '药剂师塞兰娜一直在研究地狱火半岛一带的野生动物，她也需要一份你之前采集到的血样。运气好的话，她或许能检测出令噬骨邪兽人的皮肤变红的原因！$B$B塞兰娜在萨尔玛东南方的机甲残骸。沿着道路往东走，你很快就会看见一块发着绿光的大块金属残体，那就是你的目的地。她在那群双足飞龙后面设立了一处营地。', '萨尔玛的乌托克·断斧要你转至机甲残骸，将噬骨血样交给药剂师塞兰娜。', '啊，太好了。噬骨者氏族的血。我对这些兽人很好奇……他们仍是过去堕落的恶魔，但他们的力量却比我所听过的更强大了……$B$B嗯，让我们开始吧?', '为部落效劳是我的荣幸。我能帮你什么忙?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10450, '噬骨之血', '噬骨邪兽人！他们都该死！一看到他们的红色皮肤和堕落的模样，我浑身就热血沸腾！$B$B$N，我有项任务要给你。去干掉那些噬骨邪兽人，然后收集一些他们污秽的血液。有一位药剂师需要这些血液来做检测，结果出来以后，我们或许就能了解到这些兽人是如何被恶魔腐化身心的。事实上，我们也是刚刚摆脱这种腐化。$B$B噬骨邪兽人分布在南边荣耀之路两侧的碉堡废墟附近，任务完成后回来向我复命。', '将12瓶噬骨之血交给萨尔玛的乌托克·断斧。', '哈!所以你真的挑战了噬骨者，我们堕落的亲戚。做的好，$N。我唯一的悔恨就是他们不能放下他们的生命溅洒他们的鲜血，来平息我的暴行!', '你挑战了噬骨者吗，$N。我希望他们的鲜血洒满大地!', '', '去地狱火半岛找萨尔玛的乌托克·断斧。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10451, '逃离库斯卡水池', '感谢大地之母！几天前我跟大地之环的伙伴分开，决心揭开水元素之魂躁动的秘密。我一路探寻，发现库斯卡的纳迦正在污染影月谷的水源。$B$B不幸的是，我不小心暴露了行踪，被关了起来。不知道这帮家伙会用什么样的法子来折磨我。$B$B我们必须离开这里！护送我逃离库斯卡水池，然后到诅咒祭坛去找托洛克。', '护送大地治愈者维尔达逃离库斯卡水池，然后转至古尔丹之手以西的诅咒祭坛，向大地治愈者托洛克复命。', '赞美大地之母。我确定威尔达将会找到回家的路。请收下这个以表我们的谢意。', '你找到威尔达姐妹了吗?', '护送大地治愈者维尔达到达安全地点', '去影月谷找诅咒祭坛的大地治愈者托洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10455, '危险的荒野', '我们当前正在全力进行着活木林生态环境的培育，但这里的山猫数量有些超出了控制范围。$B$B虽然林地山猫的数量曾经处于比较稳定的状态，但是现在它们已经威胁到了希尔瓦纳的生存空间，并可能导致许多令人不愉快的事情。$B$B我现在甚至怀疑拉什鸦巢的那群鸦人正是此事的幕后黑手，但现在，最迫切的问题还是来自于这些山猫本身。$B$B若是你能帮助我们解决这个问题，那可就真是太好了。', '杀死12只林地山猫。', '速度很快。你确定有解决到足够的量吗?$B$B很好，有其他的事情需要你帮忙，如果你愿意的话。$B', 'NULL', '', '去刀锋山找希尔瓦纳的莉娜·月泉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10456, '徘徊的恶狼', '那些肮脏污秽的部落在东边创建了一处定居点。他们还带了一大群恐狼来，估计要用来看家或是当作座骑。$B$B这些野兽经常冲过桥来劫掠和骚扰我们的营地。它们甚至捕食了我们的许多精灵龙，这已经严重影响了活木林内所有植物的授粉，影响到了它们的生长和繁殖。$B$B你立刻从这里东侧出镇，越过血槌峡谷上的桥，到东边的锯齿山去猎杀那里的狼群，记得将它们的尾巴砍下来作为证据！', '收集4条雷神恶狼的尾巴。', '很好。我会看看是不是可以将这些尾巴做成什么有用的东西。$B$B无庸置疑的这些部落会找方法补足他们的狼群数量，不过现在我们可以透口气了。$B$B$N，如果你愿意的话我有其它的事要要求你保护希尔瓦纳及生命之林。', '我无法充分的强调杀掉那些雷霆王恐狼的必要性。他们的存在危及到生命之林的稳定以及我们在这的工作。', '', '去刀锋山找希尔瓦纳的莉娜·月泉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10457, '自我保护', '尽管你已经为防卫活木林做出了许多卓越的贡献，但我还是觉得这处新的家园需要更多的保护。$B$B拜托你，带上这棵已被我灌注入自然之力的小树苗。只要在那些被我埋下了种子的地方使用它，它就会令种子迅速成长，破土而出，成为强大的树人卫士。$B$B这些树人卫士对于林地的防御体系来说相当重要，既然你选择了希尔瓦纳作为长期的住所，想必你也会很重视这套防御体系。', '在5处活木林树苗上使用莉娜的树枝，召唤生物保卫活木林。', '现在你已经加强了树林里的防御，我觉得安全多了。$B$B你已经赢得我们对你的赞赏与感恩之心$B$B当然，这刚好提醒我还有其他的事需要去关切!$B', 'NULL', '', '去刀锋山找希尔瓦纳的莉娜·月泉。', '召唤活木林防御者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10458, '愤怒的火灵和地灵', '我们必须设法挽救现在的局面。跟这片区域的元素沟通，看看有什么补救措施！$B$B$r，我将灵魂图腾交给你。如果你在图腾附近杀死暴怒的元素之灵，灵魂图腾将吸收它们的灵魂。使用图腾吸收元素生物的灵魂，然后向我复命。$B$B首先对付火之灵和土之灵吧，将装满土之魂和火之魂的灵魂图腾交给我。', '使用灵魂图腾俘获8个土之魂和8个火之魂，然后向影月谷诅咒祭坛的大地治愈者托洛克复命。', '当这个区域的所有元素之灵被放置到这个图腾里时，我们会与他们交流并找出是否能为影月谷做得事。', '我担心这个大陆可能失去希望了。', '', '去影月谷找诅咒祭坛的大地治愈者托洛克。', '捕获土之魂', '捕获火之魂', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10464, '先知的誓约', '$c，你既然做出了承诺，就要实现自己的诺言。$B$B为流沙之鳞效力，你就会获得应得的奖励。如果你失败的话，历史的进程将被破坏！', '当你在流沙之鳞中的声望达到尊敬后，将永恒之戒交给时空之穴的索莉多米。', '你已经证明了你的价值，$r。至少，提升到某个阶段了。$B$B诺兹多姆的最佳伙伴这个荣耀可是没那么高速缓冲得的。', '你一直对我们很有贡献，$N。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10465, '治愈者的誓约', '$c，你既然做出了承诺，就要实现自己的诺言。$B$B为流沙之鳞效力，你就会获得应得的奖励。如果你失败的话，历史的进程将被破坏！', '当你在流沙之鳞中的声望达到尊敬后，将永恒之戒交给时空之穴的索莉多米。', '你已经证明了你的价值，$r。至少，提升到某个阶段了。$B$B诺兹多姆的最佳伙伴这个荣耀可是没那么高速缓冲得的。', '你一直对我们很有贡献，$N。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10466, '勇士的誓约', '$c，你既然做出了承诺，就要实现自己的诺言。$B$B为流沙之鳞效力，你就会获得应得的奖励。如果你失败的话，历史的进程将被破坏！', '当你在流沙之鳞中的声望达到尊敬后，将永恒之戒交给时空之穴的索莉多米。', '你已经证明了你的价值，$r。至少，提升到某个阶段了。$B$B诺兹多姆的最佳伙伴这个荣耀可是没那么高速缓冲得的。', '你一直对我们很有贡献，$N。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10467, '防御者的誓约', '$c，你既然做出了承诺，就要实现自己的诺言。$B$B为流沙之鳞效力，你就会获得应得的奖励。如果你失败的话，历史的进程将被破坏！', '当你在流沙之鳞中的声望达到尊敬后，将永恒之戒交给时空之穴的索莉多米。', '你已经证明了你的价值，$r。至少，提升到某个阶段了。$B$B诺兹多姆的最佳伙伴这个荣耀可是没那么高速缓冲得的。', '你一直对我们很有贡献，$N。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10468, '先知的誓言', '$N，你实现了自己的诺言。为此，你获得了青铜龙的赏识。$B$B只要你继续维护发生在海加尔山的历史事件的正常进程，那么我将不断在永恒之戒中注入力量，直至达到它所能容纳的能量的颠峰。这一天不会太远的。', '当你在流沙之鳞中的声望达到崇敬后，将永恒之戒交给时空之穴的索莉多米。', '你的确是个值得的盟友。随着你力量的成长，永恒指环也随着增强!', '你回来了。想要跟我谈谈吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10469, '治愈者的誓言', '$N，你实现了自己的诺言。为此，你获得了青铜龙的赏识。$B$B只要你继续维护发生在海加尔山的历史事件的正常进程，那么我将不断在永恒之戒中注入力量，直至达到它所能容纳的能量的颠峰。这一天不会太远的。', '当你在流沙之鳞中的声望达到崇敬后，将永恒之戒交给时空之穴的索莉多米。', '你的确是个值得的盟友。随着你力量的成长，永恒指环也随着增强!', '你回来了。想要跟我谈谈吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10470, '勇士的誓言', '$N，你实现了自己的诺言。为此，你获得了青铜龙的赏识。$B$B只要你继续维护发生在海加尔山的历史事件的正常进程，那么我将不断在永恒之戒中注入力量，直至达到它所能容纳的能量的颠峰。这一天不会太远的。', '当你在流沙之鳞中的声望达到崇敬后，将永恒之戒交给时空之穴的索莉多米。', '你的确是个值得的盟友。随着你力量的成长，永恒指环也随着增强!', '你回来了。想要跟我谈谈吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10471, '防御者的誓言', '$N，你实现了自己的诺言。为此，你获得了青铜龙的赏识。$B$B只要你继续维护发生在海加尔山的历史事件的正常进程，那么我将不断在永恒之戒中注入力量，直至达到它所能容纳的能量的颠峰。这一天不会太远的。', '当你在流沙之鳞中的声望达到崇敬后，将永恒之戒交给时空之穴的索莉多米。', '你的确是个值得的盟友。随着你力量的成长，永恒指环也随着增强!', '你回来了。想要跟我谈谈吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10472, '先知的盟约', '$N，你取得的成就已经超越了我的想象。$B$B与青铜龙一样，你能自由地穿行在时空中。你注定会成为一名强者，而我非常乐意帮你达成这一目标。$B$B继续为流沙之鳞效力吧，我将继续在永恒之戒中注入力量，直至达到它所能容纳的能量的颠峰。', '当你在流沙之鳞中的声望达到崇拜后，将永恒之戒交给时空之穴的索莉多米。', '你与时光同在，$N。你与我们同在。$B$B瞧!即使属于永恒之井中微小的遗迹都能释放出超越凡人所能理解的力量。$B$B收下这个礼物，这样大家才知道你是流沙之鳞的盟友……这样大家才知道你是时间本身的盟友!', '愿时光永远与你同在，$N。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10473, '治愈者的盟约', '$N，你取得的成就已经超越了我的想象。$B$B与青铜龙一样，你能自由地穿行在时空中。你注定会成为一名强者，而我非常乐意帮你达成这一目标。$B$B继续为流沙之鳞效力吧，我将继续在永恒之戒中注入力量，直至达到它所能容纳的能量的颠峰。', '当你在流沙之鳞中的声望达到崇拜后，将永恒之戒交给时空之穴的索莉多米。', '你与时光同在，$N。你与我们同在。$B$B瞧!即使属于永恒之井中微小的遗迹都能释放出超越凡人所能理解的力量。$B$B收下这个礼物，这样大家才知道你是流沙之鳞的盟友……这样大家才知道你是时间本身的盟友!', '愿时光永远与你同在，$N。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10474, '勇士的盟约', '$N，你取得的成就已经超越了我的想象。$B$B与青铜龙一样，你能自由地穿行在时空中。你注定会成为一名强者，而我非常乐意帮你达成这一目标。$B$B继续为流沙之鳞效力吧，我将继续\r\n在永恒之戒中注入力量，直至达到它所能容纳的能量的颠峰。', '当你在流沙之鳞中的声望达到崇拜后，将永恒之戒交给时空之穴的索莉多米。', '你与时光同在，$N。你与我们同在。$B$B瞧!即使属于永恒之井中微小的遗迹都能释放出超越凡人所能理解的力量。$B$B收下这个礼物，这样大家才知道你是流沙之鳞的盟友……这样大家才知道你是时间本身的盟友!', '愿时光永远与你同在，$N。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10475, '防御者的盟约', '$N，你取得的成就已经超越了我的想象。$B$B与青铜龙一样，你能自由地穿行在时空中。你注定会成为一名强者，而我非常乐意帮你达成这一目标。$B$B继续为流沙之鳞效力吧，我将继续在永恒之戒中注入力量，直至达到它所能容纳的能量的颠峰。', '当你在流沙之鳞中的声望达到崇拜后，将永恒之戒交给时空之穴的索莉多米。', '你与时光同在，$N。你与我们同在。$B$B瞧!即使属于永恒之井中微小的遗迹都能释放出超越凡人所能理解的力量。$B$B收下这个礼物，这样大家才知道你是流沙之鳞的盟友……这样大家才知道你是时间本身的盟友!', '愿时光永远与你同在，$N。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10476, '强悍的敌人', '想要证明你对我们的忠诚，就勇敢地与我们的敌人作战吧。$B$B残忍野蛮的食人魔是塔拉最大的威胁。因此，如果你想证明自己的实力，就把他们脖子上的作战念珠带回来给我。我会将你的功绩告诉氏族其它成员的。', '塔拉的监护者莫布吉尔要你从纳格兰的食人魔身上收集10串黑曜石作战念珠。', '你开始证实你身为一位盟友及战士的价值了。继续保持下去吧。', '那么，$N?你是只要跟我谈一谈还是有什么东西要给我看一看?', '', '去纳格兰找塔拉的监护者莫布吉尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10477, '更多作战念珠', '', '', '你继续对我们证明你的价值吧，$N。愿你的力量永不遗弃你。', '你还有其它的黑曜石战争串珠吗，$N?', '', '去纳格兰找塔拉的监护者莫布吉尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10478, '更多作战念珠！', '', '', '你继续证明你的力量及荣耀吧，$N。', '你有更多的战争串珠吗，$N?', '', '去纳格兰找加拉达尔的监护者布罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10479, '证明你的力量', '平静的生活谁不向往？可是我们不得不面对许多敌对势力的挑战。残忍野蛮的食人魔是加拉达尔最大的威胁。$B$B如果你想证明自己的实力，就把他们脖子上的作战念珠带回来给我。我会将你取得的成就告诉氏族其它成员的。', '加拉达尔的监护者布罗克要你从纳格兰的食人魔身上收集10串黑曜石作战念珠。', '你的确是个强大的盟友，$N。前去对抗这些外域的巨魔可不是每个人都可以做得事。', '你有东西要给我看吗，$N?', '', '去纳格兰找加拉达尔的监护者布罗克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10480, '愤怒的水灵', '这个地区的纳迦控制着影月谷唯一干净的水源。$B$B此地正北方便是纳迦的老巢库斯卡。那里周围分布着许多小水洼，水面剧烈地翻腾着，仿佛在对大地发出阵阵痛苦的哀嚎。暴怒的水灵就在水洼附近游荡。$B$B转至库斯卡，使用灵魂图腾俘获水之魂。那些水灵大多聚集在库斯卡水池。', '使用灵魂图腾俘获5个水之魂，然后向影月谷诅咒祭坛的大地治愈者托洛克复命。', '只剩下空气了，$N。', '你在找到纳迦的地方就差不多可以找到那些受折磨的水之灵。', '', '去影月谷找诅咒祭坛的大地治愈者托洛克。', '捕获水之魂', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10481, '愤怒的气灵', '英雄，往东南方前进吧。当你看见大片破土而出的巨型蓝色水晶时，就说明你的目的地灵翼平原到了。暴怒的空气之灵在平原四周的悬崖和山岭附近游荡。$B$B杀死这些被折磨的元素生物，使用灵魂图腾俘获气之魂。完成任务后回来向我复命。', '使用灵魂图腾俘获10个气之魂，然后向影月谷诅咒祭坛的大地治愈者托洛克复命。', '让我为你克服如此艰巨的任务而奖励你，英雄。$B$B现在，我们必须进行我们的工作!请站后面一点，这样我才可以将图腾放在这并释放这些灵魂。', '很快的，我会将可与灵魂对话。', '', '去影月谷找诅咒祭坛的大地治愈者托洛克。', '捕获气之魂', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10482, '邪兽人清理者', '噬骨清理者躲藏在荒废的城垛上，窥视着荣耀之路的动向。我们相信，这帮邪兽人正在替地狱火堡垒中的主子收集战争机器的组件——必须阻止他们！$B$B$N，荣耀堡北边聚集了大批噬骨兽人。去杀死他们！但是不可掉以轻心，虽然噬骨兽人是邪兽人氏族中不起眼的一支，但是他们的力量跟那些绿皮兽人不相上下……', '杀死20个噬骨兽人，然后向荣耀堡的阿曼蒂复命。', '做得好。我相信地狱火堡垒会感觉到他们的损失。虽然那个黑暗堡垒逼近我们，看起来好像不能克服，但只有你们果敢行事我们才能战胜邪兽人!', '噬骨者大量出现，$N。杀了他们否则邪兽人会侵扰我们!', '', '去地狱火半岛找荣耀堡的阿曼蒂中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10483, '邪恶的咒语', '$N，在与血环邪兽人交战时，我们发现他们身上佩戴着某种不祥的饰物。那些邪兽人从荣耀堡士兵的尸体上取下徽章，制作成被诅咒的护符。我们担心血环兽人利用黑暗魔法将我们的徽章变成了咒符，还用来对付我们！$B$B转至荣耀堡以东的塞斯高，从血环兽人手中夺得一枚被诅咒的护符，然后将它交给塞斯高东北方远征军岗哨的埃隆雷下士。', '荣耀堡的阿曼蒂中尉要你转至远征军岗哨，将1枚被诅咒的护符交给埃隆雷下士。', '啊，你从血之谷兽人那里取回一个徽记了?很好 - 他们使用我们自己的象征来对抗我们，嘲笑我们阵亡在红皮肤野兽手下的同伴真是滔天大罪!', '从荣耀堡回报，$N?很好 - 我们对抗恶魔和邪兽人的战役已越来越缺少健全的人手了!', '', '去地狱火半岛找远征军岗哨的埃隆雷下士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10484, '被诅咒的护符', '$N，我们绝对不能让血环兽人继续利用被诅咒的护符！你必须替我们夺回护符，让那些牺牲的荣耀堡士兵们得到应有的尊重。$B$B转至血环兽人被诅咒的据点塞斯高，执行这项艰巨的任务……集齐护符后返回荣耀堡向我复命。', '将12枚被诅咒的护符交给远征军岗哨的埃隆雷下士。', '谢谢你，$N。看到这些护符我的心真痛 -', '你弄到护符了吗，$N?知道那些被诅咒的兽人拥有我们士兵的徽记真令我心痛……', '', '去地狱火半岛找远征军岗哨的埃隆雷下士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10485, '血环督军', '你能够幸运地从塞斯高安然返回，足以证明你具备优秀的作战能力！现在，我有一项艰巨的任务要交给你，希望这次好运气还能伴随你……$B$B督军摩尔肯坐镇于塞斯高的兵营，指挥着他的邪兽人军团与我们作战。他的战术灵活而残忍，我必须承认，他重挫了我军的士气。因此，$N，我命令你除掉摩尔肯。将他的护甲带回来，我要将它放在这儿示众，鼓舞军中的将士。', '把督军摩尔肯的破碎护甲交给远征军岗哨的埃隆雷下士。', '你办到了!莫克被杀了!现在，我们对抗那些邪兽人野兽有望了!$B$B谢谢你，$N。你对这里的战事支持难以估计。', '莫克的破碎胸甲在哪?你再次勇闯萨斯葛尔了吗?', '', '去地狱火半岛找远征军岗哨的埃隆雷下士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10486, '荒野的危险', '在饮下玛诺洛斯之血转变成邪兽人之前，雷神氏族曾是高贵的兽人氏族。$B$B在雷神氏族舍弃这座要塞后，食人魔便在此创建了据点，不过最近我们刚从食人魔手中收复了雷神要塞。$B$B我们决定守护这座要塞，希望你能伸出援手。$B$B要塞以南和以西的锯齿山中聚集着大量刃翼放血者，它们的繁殖速度极快，已经对要塞的安全构成了严重威胁。$B$B杀死刃翼放血者，然后回来向我复命。', '杀死12个刃翼放血者。', '比我本来想得还要快。你确定你有解决足够的数量吗?$B$B很好，还有一件事我要你帮忙的。一件更重要的事。$B', 'NULL', '', '去刀锋山找雷神要塞的高德雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10487, '仙龙之尘', '暗夜精灵利用精灵一族的魔法，在雷神要塞西边安营扎寨，并迅速发展成一片林地。我们必须削弱他们的防御力量，防止联盟进一步扩大势力范围。$B$B我有一项绝妙的作战计划。我要你沿着西南方的石桥跨越血槌峡谷，转至活木林。$B$B杀掉活木林中的仙龙，削弱暗夜精灵的防御力量。记得将仙龙翅膀上的魔法尘带回来给我。', '收集4份仙龙之尘。', '不只有你去削弱他们的防御，我们也将使用这个粉尘来坚固我们本身对抗联盟的防守。', '看来联盟似乎决定一路跟着我们不管到哪。让我们教教他们这样子没办法吓倒我们。$B$B你有带来我要的东西来吗?', '', '去刀锋山找雷神要塞的高德雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10488, '自卫', '我利用你取回的魔法尘配制了一种药膏，可用于强化我们的防御力量。$B$B雷神恶狼是雷神氏族驯养的坐骑，它们还承担着重要的警戒工作，是氏族忠诚的伙伴；但是那帮卑鄙的联盟居然在锯齿山大肆捕杀雷神恶狼。$B$B$N，让雷神恶狼服下这种药膏，联盟猎手们下次再来捕杀雷神恶狼时就有苦头吃了。$B$B雷神恶狼可能不喜欢这种药膏的怪味儿，当心它们攻击你。', '对5匹雷神恶狼使用高德雷克的药膏。', '现在你已经强化了这些狼匹，和锯齿山脊当地的防御，也许我们能够重新将注意力放在更要命的事情上，像是巨魔啦?\r\n\r\n你帮了我们这里很大的忙。我们可以用的上能力足够的人帮助我们，就像是你一样，假如你决定留下来的话。\r\n\r\n无论你的决定是什么，你已经得到了我们的尊敬跟感激。', 'NULL', '', '去刀锋山找雷神要塞的高德雷克。', '强化雷神恶狼', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10489, '追杀战争古树', '悬赏！$B$B深根古树，他是一棵战争古树，同时也是希尔瓦纳南部的活木林防御者的首领。$B$B沿着西边的石桥跨越血槌峡谷，寻找他的踪迹。$B$B将深根古树的树干交给雷神要塞旅店中的托查克·双爪。', '取得深根古树的树干。', '斯卓霖普.深根的大箱!你是靠自己击倒他的吗?$B$B我赌你一定是。你知道的，我们正在寻找一个年轻力壮的$C，就像你这样的人来帮助这里，特别是一直以来我们与巨魔之间存在的问题。确信你大有可能继续跟我合作。$B$B唉呀这个大箱很明显的就是证明，表示你来这里是要领取奖励而不是听我讲话的。来吧，选一个东西吧。', '你拿的那个是什么?你真是个勇敢的家伙!', '', '去刀锋山找雷神要塞的托查克·双爪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10492, '热心的建议', '你好，$c。我这里有一些你可能会很感兴趣的东西。$B$B它跟你们这个职业的人平常穿着的那些护甲有点类似，但质量上远远好于你们现在所拥有的。要是你能帮我一个小忙的话，我愿意拿它来从你手里换一件普通的套装组件。$B$B栖息在冬泉谷的霜刃豹和熊身上的血液有着某种我当前很需要的特性。给我带来一批样本，再把普通套装的手腕部分拿来，当然了，你还得支付一些金币。你会发现这其实是笔很划算的交易。', '将15份冬泉谷血样、20枚金币以及一副元素护腕交给铁炉堡的德莉亚娜。', '太棒了!那就来交易吧。要能和这件护甲搭配，还真不是件容易的事。可是我怕我马上就用不到这件了。$B$B若你还想帮我忙，我就再给你其它装备。', '你把我要的东西带来了吗，$N?', '', '去铁炉堡找王座厅的德莉亚娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10493, '热心的建议', '嗨，$C！从你的言行举止就能看出你是个历经沧桑、见多识广的家伙。但是我打赌你没有见过这么一件护甲。$B$B要是你能帮我一个小忙的话，我愿意拿它来从你手里换一件普通套装的手腕部分。$B$B我需要大量生活在希利苏斯地区的蝎子和蜘蛛的毒液。把毒液样本带给我，再支付一些金币，我就跟你交换。', '将15份希利苏斯毒液样品、20枚金币以及一副光铸护腕交给奥格瑞玛的莫克瓦尔。', '啊，是的。莫克斯一定会对这个感到非常满意。$B$B那护腕以前是大型护甲装备的一部份。如果你能再帮我忙的话，我这里还有更多可以跟你护腕搭配的装备。', '你把我要的东西都带来了吗，$N?', '', '去找奥格瑞玛的莫克瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10494, '小小的补偿', '你做到了你所承诺的事，把穆克斯制造的装备给我带了回来，那么我也按承诺给予你一件不错的奖励。把你原先使用的腰带和手套拿来吧，我会帮你升级它们。我敢保证，新的装备会比原来的好得多。', '将一条元素腰带和一副元素护手交给铁炉堡的德莉亚娜。', '你已达成交易，我也会保留我的。$B$B记住，我会保留最好的部份，就等你完成任务了。', '你准备好要交易了吗?', '', '去铁炉堡找王座厅的德莉亚娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10495, '小小的补偿', '你已经证明了自己是个非常守信誉的$r，$N。我坚信你能够帮我走出当前的困境，当然我也会根据你的表现给予你一些奖励。$B$B现在我可以帮你更换腰带和手套，如果事情进展顺利，我会继续帮你升级其它的部件。', '将一条光铸腰带和一副光铸护手交给奥格瑞玛的莫克瓦尔。', '我们的协议仍在。记住，这还只是个前菜而已。帮我从受诅咒的命运解除开来，我会奖励你超强大的物品。', '你准备好要交换了吗?', '', '去找奥格瑞玛的莫克瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10496, '告别安泰恩', '瓦塔拉克的灵魂就封印在这枚护符里。因为贪婪，我们愚蠢地将它分成了好几部分，丝毫不了解这会为我们带来怎样残酷的诅咒。$B$B唯一解除瓦塔拉克的法术的办法，就是将这枚勋章重新组合在一起。回到德莉亚娜那里去，告诉她说，伯德雷已经是她找齐剩馀部分的最后希望了。顺便跟她提一下你应得的报酬。$B$B我只希望能从此安息。祝你好运……你会非常需要运气的！', '带上一双元素长靴、一条元素护腿和一副元素护肩，回去向铁炉堡的德莉亚娜复命。', '我真不敢相信我们的日子就因为这个愚蠢的勋章而绑死了!你确定安希恩有提到布德利吗?$B$B嗯，你完成了你的工作，让我们来看看你的奖励吧。', '你回来了，$N。你一定要告诉我你发现的所有事情。但是首先让我们先来看看你的奖励。', '', '去铁炉堡找王座厅的德莉亚娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10497, '告别安泰恩', '瓦塔拉克的灵魂就封印在这枚护符里。因为贪婪，我们愚蠢地将它分成了好几部分，丝毫不了解这会为我们带来怎样残酷的诅咒。$B$B唯一解除瓦塔拉克的法术的办法，就是将这枚勋章重新组合在一起。回到莫克瓦尔那里去，告诉他说，伯德雷已经是他找齐剩馀部分的最后希望了。顺便跟他提一下你应得的报酬。$B$B我只希望能从此安息。祝你好运……你会非常需要运气的！', '带上一双光铸战靴、一条光铸腿铠和一副光铸肩铠，回去向奥格瑞玛的莫克瓦尔复命。', '就因为这个勋章，这个诅咒才会降临到我们身上。瓦萨拉克领主显然知道如何掌握仇恨。$B$B我们会尽力找到剩下的碎块 - 希望是在我面临最终的死期之前。不过在那之前，让我们先来看看你的奖励。', '你回来了，我从你的眼睛里看出来你有很多话想跟我讲，$N。让我们先处理好你的奖励。', '', '去找奥格瑞玛的莫克瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10498, '最后的奖赏', '这真是个令人惊异的故事，$N！我实在是太感谢你了，其它一些与此有关的人也会对你表示真心诚意的感激。或许今天晚上我就能睡个安稳觉了。$B$B这儿还有些你绝对会很喜欢的东西，送你算作奖励吧。', '将你的元素罩帽与元素外衣交给德莉亚娜。', '我会想念你的，$N。我欠你很大一份人情;我想我永远也无法报答你。$B$B希望你喜欢你的新头饰和胸甲，也希望它能保护你很长一段时间。', '依照我们的约定，你准备好交出你的元素装备来换取全新的五雷兜帽和外衣了吗?', '', '去铁炉堡找王座厅的德莉亚娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10499, '最后的奖赏', '确实是个令人惊异的故事，$N！我实在是太感谢你了，其它一些与此有关的人也会对你表示真心诚意的感激，这一点我向你保证。你的努力使我们终于认识到了自己过去所犯的错误。$B$B这儿还有些你绝对会很喜欢的东西，送你算作奖励吧。', '将你的光铸头盔与光铸胸甲交给莫克瓦尔。', '我真的会很想你，$N。我欠你一份人情，这是我永远也无法回报的。$B$B好好使用你的新头饰和胸甲。愿它能保护你很长一段时间，为你带来更多的荣耀!', '你准备好用你的光铸装备和我交换全新的魂铸头盔和胸甲了吗?', '', '去找奥格瑞玛的莫克瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10502, '血槌食人魔', '比起部落的雷神要塞，另一群势力对希尔瓦纳具备着更致命的威胁。$B$B我说的正是栖息在群山之中的食人魔原住民。血槌氏族居住在峡谷内的东方和南方，他们的确不是唯一一群威胁着我们的食人魔，但他们却是最近的。$B$B你要立刻向南，穿越活木林，然后沿路向东走入谷地，进入他们的哨站。之后，就请在血槌哨站消灭尽量多的食人魔吧。', '消灭血槌哨站的任意30个血槌食人魔。', '对于守护希尔瓦纳及林地踏出了成功的第一步。$B$B因为巨魔的人数不再这么众多，血槌就会好好思考有关攻击我们的事。$B$B现在，但愿他们是唯一我们需要担心的巨魔氏族。$B', '我们的斥候回报这些刀塔食人魔已经在更接近山路的地方创建了一个营地，就是从他们的堡垒到我们这里的那条路。$B$B很不幸的我们无法苟同就这样屈服于这些巨魔垃圾底下，但如果他们想要开战，他们会发现部落不只适应力好而已。', '', '去刀锋山找希尔瓦纳的指挥官萨卡斯·天影。', '杀死血槌食人魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10503, '刀塔的威胁', '雷神要塞所面临的形势比联盟的希尔瓦纳更加严峻。$B$B我指的是那些刀塔氏族的食人魔，当前驻扎在正西边的沟壑之中。的确，他们不是唯一一支食人魔氏族，但他们离我们最近，威胁也最大，我们必须击败他们，才能得到生存的空间。$B$B你立刻向北走，穿过锯齿山，然后沿着路一直前进，进入他们的要塞。到那里以后，你要尽全部力量消灭刀塔要塞和刀塔平原那边的刀塔食人魔和刀塔迅猛龙。', '消灭刀塔要塞和刀塔平原的30个刀塔食人魔和10只刀塔迅猛龙。', '对于守护希尔瓦纳及林地踏出了成功的第一步。$B$B随着他们的人数减少，刀塔会好好思考有关再度攻击雷神要塞的事。$B$B现在，但愿他们是我们唯一需要担心的食人魔氏族。', '我们的斥候回报这些刀塔食人魔已经在更接近山路的地方创建了一个营地，就是从他们的堡垒到我们这里的那条路。$B$B很不幸的我们无法苟同就这样屈服于这些巨魔垃圾底下，但如果他们想要开战，他们会发现部落不只适应力好而已。', '', '去刀锋山找雷神要塞的托查克·双爪。', '杀死刀塔食人魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10504, '刀塔食人魔', '在血槌氏族北方，坐落着另一个更具威胁的食人魔氏族的大本营——刀塔氏族的刀塔要塞。$B$B刀塔食人魔是刀锋山脉中最强大的食人魔氏族，甚至已经得到了屠龙者格鲁尔和他七个儿子的宠爱。$B$B现在我们已经解决掉了血槌氏族，是时候关注一下他们的竞争对手了。$B$B你从血槌要塞出发的话，只需直接向北穿越谷地，就可以直接抵达刀塔要塞和刀塔平原。请在那边消灭尽量多的刀塔食人魔吧。', '消灭刀塔要塞和刀塔平原的任意30个刀塔食人魔。', '你对抗血槌及刀塔食人魔氏族的行动对保护希尔瓦纳的未来有很大的帮助。因为我们不打算扩宽超越这个大陆的辖区，起初我们什么都没发现的地方，不过我们也不会折磨那些可能会摧毁我们的。$B$B因为你为我们立了大功，我会奖励你以表示联盟的感谢之意。', '血槌或是刀塔，都不重要。所有的食人魔氏族互相征战，争取拥有弑龙者格鲁尔支持的统治权。$B$B每一个都是我们的敌人，不管最后花落谁家。', '', '去刀锋山找希尔瓦纳的指挥官萨卡斯·天影。', '杀死刀塔食人魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10505, '血槌食人魔', '除了刀塔氏族以外，还有另一支食人魔力量威胁着我们的安全，那就是血槌食人魔，他们甚至在刀塔哨站的南方创建起了血槌哨站。$B$B虽然血槌食人魔并非是山脉中最强大的氏族，但是他们也崇拜屠龙者格鲁尔，同样具有相当强大的实力。$B$B既然我们已经解决掉了刀塔氏族，那么现在是时候来对付他们的竞争对手了。$B$B从刀塔要塞往南走，穿过峡谷就能到达血槌哨站，到那里去吧，在哨站周围消灭尽可能多的血槌食人魔。', '消灭血槌哨站内的任意30个血槌食人魔。', '你对抗刀塔及血槌巨魔氏族的行动对保护雷神要塞的未来有很大的帮助。我们不会接受那些会阻碍我们在这的使命的事情。$B$B因为你在消灭这些食人魔这件事上立了大功，我打算以奖励你来表示部落的感谢之意。$B', '血槌或是刀塔，都不重要。所有的食人魔氏族互相征战，争取拥有弑龙者格鲁尔支持的统治权。$B$B每一个都是我们的敌人，不管最后花落谁家。', '', '去刀锋山找雷神要塞的托查克·双爪。', '杀死血槌食人魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10506, '严峻的形势', '部落的狼群数量锐减之后，他们已经开始积极地寻找替换品。不过，这附近没有任何可用的野兽资源，他们的目标或许在谷底。$B$B谷地底下的血槌食人魔养着大量的恶狼作为看门宠物。但是，我对上次把你派去屠杀雷神狼群的做法也感到十分厌恶，我们为什么就不能换一个方法呢？$B$B最近我从精灵龙的翅膀上掉落下的粉尘中提炼出了一种很有意思的魔粉。把这些粉末撒在血槌恐狼的身上，这样部落就不会想要它们了。', '对血槌哨站和血槌峡谷内的5只血槌巨狼使用莉娜的缩小粉尘。完成之后回到刀锋山的希尔瓦纳向她复命。', '我很高兴听到任务已经完成了。那些必须牺牲的自然生物愈少愈好。$B$B因为你为我们作得所有事情，我得说我开始愈来愈喜欢你们的团队了。$B$B保重，$N。', '有任何收获吗?我知道混在血槌巨魔中进行这项工作很危险，不过要是我们能够避免再杀害任何动物，我会觉得比较开心。', '', '去刀锋山找希尔瓦纳的莉娜·月泉。', '削弱血槌巨狼', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10507, '转折点', '$N，我们一直在等待这样的机会。凯尔萨斯与燃烧军团私下勾结的阴谋已经败露，现在你要拿起武器，击败凯尔的新主子——索克雷萨。$B$B我的健康状态不允许我亲自上阵，无法与你并肩作战真是遗憾。我将这颗宝珠交给你，它能聚集我全部的能量，帮助你击败索克雷萨。', '转至位于铸魔基地：湮灭以北的登陆场：霸王，使用索克雷萨的传送石将你的小队传送到索克雷萨之座。利用沃雷塔尔的宝珠击败索克雷萨。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '你是个拥有强大力量的人，$N。先知者很幸运能有你这个盟友。$B$B随着凯尔萨斯新东家的消息散布出去，更多的人都会跟我们看法一样了。我们可以宣称在对抗凯尔萨斯的新霸主上如此决定性的胜利使情势变得有利于我们。', '完成了吗，$N?', '', '去泰罗卡森林找占星者之台的先知沃雷塔尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10508, '给沃雷塔尔的礼物', '我可不想让你两手空空去见沃雷塔尔，低调不是我做事的风格。$B$B想要进入北边的索克雷萨之座，我们就必须使用索克雷萨的传送器，而只有他的传送石才能启动传送器。铸魔基地：湮灭的熔炉主管莫鲁格掌管着索克雷萨之石的上半部，索克雷萨之石的下半部则由铸魔基地：炼狱的希尔洛斯保管。$B$B夺得索克雷萨之石的上半部和下半部，沃雷塔尔必定会惊讶得说不出话来。', '52区的间谍大师萨罗迪恩要你从铸魔基地：湮灭的熔炉主管莫鲁格手中夺得索克雷萨之石的上半部，并从铸魔基地：炼狱的希尔洛斯手中夺得索克雷萨之石的下半部。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '你真是让我惊喜，$N!很高兴你是与我们同一阵线的。', '你拿到索奎萨尔的传送石了吗，$N?', '', '去虚空风暴找52区的间谍大师萨罗迪恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10510, '进入德拉诺晶矿', '啊啊，终于找到愿意帮助我们的人了！$B$B我和伯格瑞姆都是探险者协会的成员，到这里来就是为了考察这处伟大的山脉。我们听过许多有关这里的传说，真是迫不及待地要安顿下来开始研究了。$B$B听这里的暗夜精灵说，在谷地下面的正东向，有一处叫作德拉诺晶矿的地方出产一种很特殊的水晶。我对这种水晶非常有兴趣，所以想要搞到一些水晶的样本进行研究。', '收集5块德拉诺矿洞水晶。', '喔，看看这些东西，他们可是优良的样本。我等不及要用我的实验工具打开亲眼看看他们!$B$B感谢你!', '很刺激吧?在这些希利苏斯灰泥及虫子之外，这个地方像个天堂。', '', '去刀锋山找希尔瓦纳的布隆薇·硬锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10511, '奇怪的美酒', '悠闲假日的最好伴侣那就是美酒名酿了，来这里度假怎么能没有酒。但糟糕的是，这些精灵真的完全不懂发酵与酿造的艺术。$B$B我听说谷地下面的血槌食人魔也是嗜酒如命，存有不少美酒。说起来，我还真想试上一试。$B$B嘿，帮我个忙怎么样？你马上向南穿越活木林，沿路下坡，进入东边的血槌哨站里，替我抢点酒来如何？我听说那里到处都是装得满满的大酒桶，由他们的酿酒师负责保管。', '收集11桶血槌烈酒。', '这是什么味道?喔不，不要告诉我那就是巨魔的酒?!$B$B我连喝都不想喝看看这东西。喔好吧，究竟是什么鬼东西啊?倒掉!', '这里变得很无聊。没有东西喝得话我要怎么享受我的假期呢?', '', '去刀锋山找希尔瓦纳的伯格瑞姆·硬锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10512, '灌醉刀塔食人魔', '打死我也不会再喝一口这难闻到家的泥浆了！不过，我突然有了一个好主意。$B$B<伯格瑞姆狡黠地眨了眨眼睛。>$B$B那么，计划如此：血槌食人魔没有这种泥浆水是活不成的，这一点我们都知道了。但我也很好奇，想知道他们的死对头刀塔食人魔对这玩意有什么看法。$B$B$N，我要求你立刻把这桶垃圾拿到刀塔食人魔那边去，丢给他们喝。从血槌哨站一路沿着谷地向北去就可以找到刀塔食人魔了。', '用血槌酒桶将5个刀塔食人魔灌醉。', '啊，哈哈哈!跟我想的一样。我猜巨魔什么都喝。$B$B笨蛋，全部都是!$B$B好吧，我得说虽然我没有得到我要的酒，不过你已经带给我的假期一个美好的开始。$B$B跟你说……我们这有各种我们不需要的东西。你要哪一个呢?', '如何?这些刀塔食人魔跟那些血槌一样吗，或是像我一样被他们去掉小命?', '', '去刀锋山找希尔瓦纳的伯格瑞姆·硬锤。', '灌醉刀塔食人魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10514, '历经沧桑……', '陌生人，我曾历经沧桑，但是昔日的辉煌已是过眼云烟。时过境迁，我现在不过是个普通的农夫罢了。$B$B我在农场训练地狱野猪，教它们从破碎平原的坚硬土壤中掘出影月块茎。但是，来自东北方的一批剥石者最近不断袭击猪圈，搞得我没办法收集块茎。$B$B你愿意去北边的农地帮我采集块茎吗？你可以站在影月块茎露出根须的地方吹响这只哨子，就会有地狱野猪跑来掘出块茎！', '影月谷欧鲁诺克农场的欧鲁诺克·裂心要你在破碎平原收集10个影月块茎。$B$B任务完成后把欧鲁诺克的野猪哨一并归还给他。', '你提到那边的那些镰夺怪多到超乎你的想象?看来是除掉这些垃圾的时候了。', '去帮我把那些肉条带来!', '', '去影月谷找欧鲁诺克农场的欧鲁诺克·裂心。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10515, '严厉的教训', '这帮剥石者胆敢冒犯欧鲁诺克，我们要给他们点厉害瞧瞧！$B$B我要你返回破碎平原，摧毁贪婪剥石者的卵。它们大多分布在剥石者的老巢中，因此请千万小心。', '返回破碎平原，摧毁10枚贪婪剥石者的卵，然后向影月谷欧鲁诺克农场的欧鲁诺克·裂心复命。', '那会让那些该死，下流的生物得到教训不再杀害我的野猪!做得好，$N!', '赶尽杀绝!', '', '去影月谷找欧鲁诺克农场的欧鲁诺克·裂心。', '摧毁贪婪剥石者的卵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10516, '守备官的困境', '这听起来很奇怪，但我确实是故意要继续待在这只笼子里面的。我来这里的目的是收集刀塔食人魔的情报，当前的状况给了我一个非常好的机会。$B$B其实，只要我愿意，我随时都可以离开，但是我需要先拿回我的佩剑和盾牌。$B$B这群食人魔中的两个头目拿着它们：德罗加姆拿着剑，玛戈多格拿着盾牌。$B$B要是有必要谨慎些的话，你可以去南边的血槌哨站搞一些酒来，把他们周围的其它食人魔都灌醉，这样他们就不会有援手了，当然，还是得小心那些不喝酒的守卫！', '夺回守备官乌里恩之剑和守备官乌里恩之盾。', '现在我欠你一个人情，因为你帮助我守住我的面子。但是我们在这个工作尚未完成。', '$C，你拿到我的剑跟盾了吗?$B$B虽然我随时都可以离开，但是失去我的武器两手空空的回到希尔瓦纳是一件很丢脸的事。', '', '去刀锋山找刀塔要塞的守备官乌里恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10517, '高尔迪姆，你完蛋了……', '刀塔要塞的领袖据说是高尔迪姆。相信我……应该就是这个名字没错了。$B$B不过，我可绝对不会轻视这个家伙。他将自己的氏族发展壮大了许多，不仅得到了屠龙者格鲁尔的宠爱，甚至成为了刀锋山脉的统治者。高尔迪姆身边总是带着大量的随从，甚至有几名发誓绝对不碰酒的可靠侍卫。$B$B为了希尔瓦纳的安全，我命令你立刻返回那边，刺杀高尔迪姆。', '杀死刀塔要塞内的食人魔头目高尔迪姆。', '很好。你非常聪明，$C，那是一定的。$B$B我怀疑接下来是否会有另外一件事情你能为了我及希尔瓦纳去完成呢?', '那些噪音是什么?是因为你解决哥尔迪姆的关系吗?', '', '去刀锋山找刀塔要塞的守备官乌里恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10518, '插旗子', '我要你从那些刀塔勇士的身上偷一面刀塔旗帜，带到南边的血槌哨站去。之后，你要把旗子插在那里的北槌哨塔的顶上。$B$B这样一来，你就会马上激怒那些血槌食人魔，遭到他们的无情攻击，同时也会进一步挑起他们对刀塔要塞的仇恨，使他们忽略掉希尔瓦纳。$B$B你插上旗子之后，必定会引出血槌氏族的古恩·格鲁诺什，杀死他并夺走他的头盔，然后你就可以返回希尔瓦纳了。$B$B$N，这可是个艰难的任务，最好还是带上一两位朋友同行吧。', '在北槌哨塔顶上使用刀塔旗帜，引出古恩·格鲁诺什。然后将旗帜和古恩·格鲁诺什的头盔一起交给刀锋山希尔瓦纳的指挥官萨卡斯·天影。', '葛恩.格罗姆巴诺斯的头盔及一面刀塔氏族旌旗?$B$B你跟复仇者想出这个计画真的十分的聪明。$B$B藉由将血槌氏族的注意力保留在剑刃要塞那，你减轻了因为他们想要进犯我们这里的压力。$B$B请收下来自希尔瓦纳这份微薄的礼物，$N。', '是什么将你引领到我这?不是与血槌巨魔氏族之间更多的麻烦吧?', '', '去刀锋山找希尔瓦纳的指挥官萨卡斯·天影。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10519, '诅咒密码 - 真相和历史', '<欧鲁诺克变换了站姿，挺直了腰板，身形顿时高大起来。>$B$B$N，我从不做没把握的事。刚才算是对你的考验吧，请原谅我现在才显露真面目。我并不是一位普通的兽人老农。$B$B如果你是为诅咒密码而来，就先听听我的故事吧。等你做好准备，我们就开始吧。', '影月谷欧鲁诺克农场的欧鲁诺克·裂心要你听听他的故事。跟欧鲁诺克谈谈，听这位年老的兽人讲述他的故事。', '你了解必须做什么了吧?去找欧朗诺克之子。找到我的儿子们……', '耐心的听吧，$N。', '诅咒密码 - 真相和历史', '去找影月谷欧鲁诺克农场的欧鲁诺克·裂心。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10522, '诅咒密码 - 格洛姆托的命令', '这是我今天审问的第六个纳迦。这家伙身穿华丽的护甲，想必知道些内情。其它的都是些一无是处的废物。$B$B<格洛姆托指着地上横七竖八的纳迦尸体。>$B$B我揍了他一顿，他就什么都说了。$B$B诅咒密码的第一块碎片被锁在库斯卡岗哨或是库斯卡水池的某个箱子中，钥匙就在纳迦身上。杀死纳迦，夺得钥匙，取回碎片之后回到我这里来。', '取回诅咒密码的第一块碎片，然后向影月谷库斯卡岗哨的欧鲁诺克之子格洛姆托复命。', '这个必须马上送回去给父亲。', '运气好吗?', '', '去影月谷找库斯卡岗哨的格洛姆托，欧鲁诺克之子。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10523, '诅咒密码 - 第一块碎片', '<格洛姆托将诅咒密码的第一块碎片卷起来，放入带锁的箱子中。>$B$B把这只箱子交给我的父亲。他在东北方的欧鲁诺克农场等你。$B$B请转告他，我玩够了就会回家，很快的……', '将格洛姆托的箱子交给影月谷欧鲁诺克农场的欧鲁诺克·裂心。', '当毁灭密码改正后，我们就该终止这个诅咒了!', '你成功了?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10524, '雷神氏族的神器', '这些印有标记的器物都是由雷神氏族的兽人制造的。在变异成邪兽人以后，这些兽人一直居住在雷神要塞中。$B$B刀塔氏族的食人魔甚至也曾在要塞居住过一段时间，直到最近才被部落赶走。$B$B想必你已经听说了还有其它部分圣物遗失的消息，包括一面鼓、一支箭，还有一块石板，当前我们正在搜索它们的踪迹，希望你也来帮忙。$B$B去刀塔要塞寻找这几样东西吧，如果找到的话，请把它们交给洛克加·血握。', '找回雷神氏族战鼓、雷神氏族箭矢和雷神氏族石板。', '我不敢相信我看到了什么!如果这是某种骗局，我会把你碎尸万段的，$C!$B$B快，在被你笨手笨脚弄坏前，先让我鉴定一下这些宝贵的神器。', '我认识你吗?', '', '去刀锋山找雷神要塞的洛克加·血握。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10525, '幻像的指引', '你这愚蠢的$R，你几乎毁掉了这面鼓！$B$B我费劲了千心万苦才来到这里，直到现在什么也没找到。其它寻找圣物的人也都失败了，或者遇到更糟的事。唉，算了，至少你能成功地把东西带回来。$B$B是时候召唤出幻像，让它指引你找到我所寻找的最后一件圣物了。$B$B带上这片炽热灵魂碎块，它可以将你的身体变为火焰，并将你的灵魂领入一个幻像中。那时，你就能知道最后一件雷神圣物在哪里了。', '利用炽热灵魂碎块将你的灵魂转变为指引你方向的幻像。找到最后一个雷神圣物的位置。', '德莱尼矿坑的后面?一定是血槌氏族从刀塔食人魔那偷来的。$B$B呸!那对我来说太远了……太过深入血槌的领土。$B$B不过对你就不是。你知道怎么去。你要代替我去那里!', '你看\r\n到了什么?告诉我，我必须知道它在哪里!', '找到最后的雷神圣物', '与刀锋山找雷神要塞的洛克加·血握。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10526, '雷霆之刺', '如果我让你看到的幻境里所显示的地点没错，那你就必须去峡谷那边一趟。总之，到血槌峡谷南部边缘去，你可以在那里找到德拉诺晶矿。$B$B然后，你要绕到矿井背后找回雷霆之刺。千万别去管其它的东西！我对矿井里的水晶和食人魔都没有兴趣。$B$B找到圣物后马上把它带回来给我！$B$B嘿，$N，一定要非常小心……我实在不愿去想象你将它折断后会有怎样的结果。', '找回雷霆之刺。', '我现在很感动!你知道有多少其它鬼魂想要取回所有这些神器吗?$B$B我何其幸运有你在这与我们共事，$N。虽然你动作有点慢。$B$B请让我为了你的贡献而酬谢你。挑一个吧，不过请做出明智的选择。当你完成后，我就会交出神器来平息雷神要塞的鬼魂。', '我相信，你一定很疑惑这些神器的用义。$B$B当我们五个都拥有的时候，我们在雷神要塞的所有权就可藉由安抚那些死去的鬼魂而稳固。$B$B你现在开始领会为何这有这么重要了吗?你了解为何我会这么挑剔了吧?', '', '去刀锋山找雷神要塞的洛克加·血握。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10528, '恶魔的水晶牢笼', '漂浮在半空中的水晶环绕着地面上的神秘符文，水晶射出的能量光束形成禁锢法阵，将阿托尔的尸体困在法阵中央。你试着想要移动这具尸体，却发现怎么用力都无济于事。$B$B你注意到所有的水晶底座上都有一个空槽，或许它们都配有钥匙吧。附近似乎时不时还有魅魔在举行某种仪式。$B$B在伊利达雷岗哨寻找魅魔首领的下落，也许她携带着解除禁锢法阵的钥匙。', '杀死伊利达雷岗哨的痛苦女王加布莉萨，夺得晶体钥匙，然后返回欧鲁诺克之子阿托尔的尸体旁。', '你将结晶钥匙转动插入每一个恶魔结晶底部的缝孔中。', '阿尔托无生气的飘浮在你面前。', '', '去影月谷找伊利达雷岗哨的阿托尔，欧鲁诺克之子。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10537, '洛恩戈鲁，裂心之弓', '这就是命运，$N，我的灵魂从未停止过抗争。我必须取回诅咒密码的第一块碎片。只要你肯伸出援手，就可以帮我达成这个未遂的心愿。$B$B在此之前，请替我取回长弓洛恩戈鲁。那是裂心系列世代相传的宝物。$B$B直觉告诉我，肯定是某个恶魔掳走了它。杀死岗哨中的恶魔，直到你找到洛恩戈鲁。', '影月谷伊利达雷岗哨的阿托尔的灵魂要你从驻守岗哨的恶魔手中夺得洛恩戈鲁，裂心之弓。', '这在我的母语中代表着“英雄居所”的意思。就算现在听起来还是很真实 - 这个世代的英雄都已经死了……$B$B看来似乎永远都会有人接班。', '无所畏惧，英雄。到了合适的时机，我就会协助你的……', '', '去影月谷的伊利达雷岗哨找阿托尔的灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10538, '沸腾之血', '上次的实验不能算完全失败，至少我保留了一些你带来的血样。血液一经煮沸，血环巫师在邪兽人血液中施加的诅咒就能得以消除。$B$B我需要更多的血样进行研究。从塞斯高的兽人身上收集血环血样，然后将它们投入被诅咒的大锅中煮沸，然后把沸腾之血带回来给我。', '将血环血样投入被诅咒的大锅中煮沸，然后将12份沸腾之血交给断背岗哨的药剂师阿尔布雷克。', '非常好。现在我能更容易地进行我的测试……$B$B谢谢你，$N。你很有天份。', '你弄到沸腾的血了吗，$N?我急着想研究它不想中断……', '', '去地狱火半岛找断背岗哨的药剂师阿尔布雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10540, '诅咒密码 - 阿托尔的命令', '一切准备就绪。英雄，这是从我的灵魂中抽离出的一块碎片。它会保护你的安全，帮助你对抗邪恶势力。$B$B伊利达雷岗哨以南的祭坛附近躲藏着一个名叫维内拉图斯的怪物。一旦维内拉图斯出现在灵魂碎片的追踪范围内，我的灵魂猎手就会召唤出他来。$B$B杀了维内拉图斯，取回诅咒密码的第二块碎片。', '从维内拉图斯手中夺得诅咒密码的第二块碎片，然后向影月谷伊利达雷岗哨的阿托尔的灵魂复命。$B$B你无法从被灵魂猎手攻击或杀死的怪物身上获得物品和经验值。', '<阿尔托逐渐变淡失去了形体。>$B$B看来我的时间快到了，英雄。', '你一定要把密码抢回来!', '', '去找蛮锤要塞的阿托尔的灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10541, '诅咒密码 - 第二块碎片', '英雄，谢谢你。没有你的帮助，我的灵魂将永远禁锢在这个被诅咒的地方。$B$B<阿托尔递给你一只带锁的箱子。>$B$B把箱子交给我的父亲，他住在库斯卡水池附近的农场，在遥远的东北方……箱子里面装着洛恩戈鲁和诅咒密码的第二块碎片。$B$B他听闻我的死讯后必定会非常悲伤。答应我，让他相信我是在宁静祥和中离开这个世界的。告诉他我看见了美丽的狩猎场，告诉他我在那儿等他……', '将阿托尔的箱子交给影月谷欧鲁诺克农场的欧鲁诺克·裂心。', '<欧朗诺克擦掉眼泪对你微笑。>$B$B谢谢你。我答应你，英雄，会以你为名写一首赞颂的歌曲。', '<一滴眼泪从欧朗诺克的脸颊落下。>', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10542, '他们偷走了我的水烟袋和酒！', '塔卡里以前是一个很好很好的巨魔。我来到这个地方教血槌食人魔如何酿酒。但在我教会他们以后，血槌食人魔却将我塔卡里埋在这里不管了，他们让我在慢慢地死去，烂掉！$B$B更可气的是，他们偷走了我的水烟袋！$B$B你愿意帮帮塔卡里吗？去把水烟袋给我找回来。塔卡里认为那些食人魔把水烟袋带到西南边的矿井那里去了。$B$B哦，你到了那里之后，顺便帮我收集一些酒回来！', '找回塔卡里的水烟袋和10瓶血槌烈酒。', '没错，那就是提洽里说的东西!虽然我不知道那些巨魔放入了什么东西;但我在水烟筒闻到的并不是提洽里的烟草。$B$B没关系，提洽里已经很高兴了。事实上，因为太高兴了所以我还有别的事情要你去做。', '嗨，你拿到我的水烟筒还有那些酒了吗?', '', '去刀锋山找血槌峡谷的巫医塔卡里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10543, '葛雷诺克和库尔加，你们完了！', '塔卡里一直在等待机会报仇！$B$B第一天，那群该死的食人魔把塔卡里埋在这里，让我等死，带头的好象是葛雷诺克。第二天，从南边来的库尔加又跑来劫掠塔卡里，还踢了我的头。$B$B他们全部都得死！$B$B你可以在血槌哨站的南槌哨塔顶上找到葛雷诺克，而库尔加在刀塔要塞北部边缘的一座建筑物顶上。库尔加周围有很多完全不喝酒的卫兵，但库尔加自己则嗜酒如命，所以你要利用这些酒将他从那些卫兵身边引诱过来。', '杀掉葛雷诺克和库尔加。', '提洽里很高兴柯尔卡赫还有葛瑞诺克.巴拓伯恩变成跟他一样的下场。$B$B但是提洽里对复仇的渴望还没有得到纾解。还有一件事你必须去做!', '你以为提洽里喜欢现在这个样子吗?不!$B$B那么，你已经强制执行我的复仇了吗?葛瑞诺克还有柯尔卡赫已经死了吗?', '', '去刀锋山找血槌峡谷的巫医塔卡里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10544, '诅咒你们的氏族！', '塔卡里想要报复所有的食人魔！$B$B塔卡里生前是一个非常有影响力的巫医。只要进入到他的坟墓，你就能找到一个充满着邪恶力量的雕像。$B$B在刀塔要塞和血槌哨站的建筑物和塔的入口处使用这个雕像，不过要小心，施法召唤时会出现出一个邪灵，你必须先击败它。当你击败这个邪灵后，它所在的那座建筑物就会被诅咒。$B$B一定要小心，如果你试图诅咒一座已经被诅咒过的建筑物，那么你就又要面对一个邪灵的挑战！', '利用邪恶雕像诅咒刀塔要塞的5座建筑物或者哨塔，以及血槌哨站的2座建筑物或者哨塔。', '哈哈哈，复仇的滋味真好!$B$B但是，提洽里看的出来你帮我复仇了以后已经想离开了。我了解……活人有他们自己的生活。$B$B这样吧，提洽里的坟墓里面还有很多的好东西。你可以挑一件你最喜欢的!', '提洽里一点都不想讲话直到$N使用神像诅咒刀塔氏族还有血槌氏族的建筑物还有高塔!', '', '去刀锋山找血槌峡谷的巫医塔卡里。', '诅咒刀塔要塞的建筑物', '诅咒血槌哨站的建筑物', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10545, '血槌醉汉', '就像巫医塔卡里之前说过的那样，他帮助他的血槌食人魔朋友酿酒，却一直没有说过为什么要这样做。$B$B血槌氏族当前的状况特别窘迫。刀塔氏族一直在压迫他们，他们需要一件新的武器来反抗。$B$B这时候，塔卡里有了一个好主意，为什么不通过完美的酒来壮大自己而削弱敌人呢？唯一的问题就是，塔卡里不知道这招有没有效。$B$B所以，你不如把这些酒带去刀塔氏族那里试试看。', '使用血槌酒桶灌醉5个刀塔食人魔。', '那真是个好消息!那种酒将会在提洽里接着要你去做的事情里面派上用场。', '告诉提洽里……那种酒对他们有效吗?那些刀塔食人魔喜欢喝吗?', '', '去刀锋山找血槌峡谷的巫医塔卡里。', '灌醉刀塔食人魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10547, '血蓟交易……', '要不是我发现了一个重要线索，也许我早就放弃了跟踪……这家伙是个血蓟瘾君子。刚开始我还没有注意到，后来却发现种种迹象都指向这一点……$B$B如果我们能弄到血蓟，事情就好办了。$B$B我曾在沙塔斯城遇见一个名叫托比亚斯的破碎者。$B$B托比亚斯跟血精灵有贸易往来，他将血蓟卖给血精灵，以换取腐烂的鸦人之卵。$B$B此地正西方就是一片鸦人废墟。去那里寻找一枚腐烂的鸦人之卵，然后转至沙塔斯城的贫民窟找到托比亚斯。', '位于日蚀岗哨北面石桥旁的欧鲁诺克之子伯拉克要你将一枚腐烂的鸦人之卵交给沙塔斯城中的暴食者托比亚斯。', '你有腐烂的阿拉卡蛋?你怎么不早说!我想我们可以成交。$B$B<图比亚斯微笑，露出了满嘴污秽的蛀牙。>', '<图比亚斯吓了一跳。>$B$B血蓟?我从来没听过……你是保安官吗?假如你是的话你要跟我说……我有我的权利!', '', '去泰罗卡森林找沙塔斯城的暴食者托比亚斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10548, '悲伤的事实', '还记得我跟你提过的那个寻找指环的胖商人吗？这位商人派他那醉心于考古学的儿子外出搜寻古物，可惜此行不顺。我的意思是，他挂了，死在了巨魔手里。$B$B虽然这样说显得冷酷无情，不过这位父亲愿意出重金取回他儿子的徽记。这项任务派你去再适合不过了！$B$B转至东边的巨魔废墟塞布提拉和塞布努瓦，徽记应该就在某个营地的某个箱子里。', '从塞布提拉或是塞布努瓦的某个箱子中取出考古学家的徽记，然后向塔奎林的艾拉兰复命。', '喔，我的天啊。看了真令人心酸。我相信那个商人会比我还要感激你。$B$B至于酬劳，那个商人付钱订了我的一个特殊库存物品要送给你，选一个吧$g帅哥:美女;!', '猎头行动进行的如何呢?', '', '去幽魂之地找塔奎林的艾拉兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10550, '一捆血蓟', '我可没说谎。这蛋真是美味中的极品。你从哪儿搞到的？$B$B唔，如果你想要更多的血蓟，只管来找我，咱们各取所需嘛。$B$B这是你要的一捆血蓟。回去找你的头儿吧。', '将一捆血蓟交给位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克。', '现在可以设下陷阱了!', '你取得血蓟了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10555, '诡异的魔法', '拉什鸦人的魔法非常诡异。他们从自己身上扯下一把羽毛做为魔法材料！$B$B这听起来就很下等。我来希尔瓦纳就是为了研究他们的法术，可惜我一直不敢太靠近拉什鸦巢。$B$B不如你替我跑一趟，设法让他们的法术效果作用在你身上，然后回来向我复命。你还要阅读拉什鸦人放置在拉什鸦巢顶部的一本法术书。$B$B除非你身上长着我看不见的羽毛，不然，我想你必须从鸦人身上收集到足够的羽毛才行。', '收集18片拉什鸦人的羽毛。', '翻阅拉斯汗阿拉卡留下的破损便签和细长的字条，你发现有一页出现了你曾在迷雾拉斯看过的魔力法阵图案。', '你从这本古老的书上发现的粗糙图文中记载着，需要大量的拉斯汗羽毛才能施放书中的该项法术。', '', '打开刀锋山拉什鸦巢的拉什鸦巢宝典', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10556, '潦草的字迹', '书页上绘制的图案显示鸦人在拉什鸦巢的某个法阵中用羽毛施法。$B$B似乎鸦人是在利用这个诡异的法术召唤出卡利鸟的灵魂。', '在拉什鸦巢法阵使用一把羽毛。', '我不知道该说什么。这个法术非常的奇怪。这不是某种召唤法术或者附魔，而是某种共享或者连结术。$B$B我不了解这个法术的原理，$N。我还要再想想。$B$B但还是感谢你的协助!我想迟早我都会想通的。', '真是太棒啦!我等不及要看这个法术的效果了。', '', '去刀锋山找希尔瓦纳的达兰妮尔。', '让达兰妮尔分析卡利鸟光环', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10557, '试飞：风动电容器', '我造了一个很棒很棒的装置，叫风动电容器，它完美无缺，肯定能正常工作！但……你就说你愿不愿意帮我测试一下吧？$B$B报酬可是绝对非常丰厚喔！$B$B去和我的孪生兄弟拉雷谈谈吧。祝你好运，$N。实验完成以后再回来找我。或者……要是万一你受伤或者挂了的话，你的亲戚将可以拿走你的报酬。', '与拉雷·萨普纳波谈一谈，并使用风动电容器。', '哦，你成功了!而你身上连一处瘀青还是骨折都没有!你看吧，我告诉你一切都会顺利成功的!$B$B这是给你的报酬，$N，虽然我当初多算了医疗开销而你用不上……所以算你赚到了!', '别害怕!你的牺牲都是为了科学，而科学的成长是痛苦的!', '测试塔利的装置', '去刀锋山找托什雷的基地的塔利·萨普纳波。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10562, '兵临城下！', '保持警惕，$r。燃烧军团的攻击从没有停止过。$B$B他们当前盘踞在西南方的军团要塞，每天召唤出的地狱火总能像潮水般朝我们这里涌来。我们消灭敌人的速度根本就跟不上他们补充兵力的速度。$B$B现在，士兵们个个都精疲力竭，我也不知道他们还能撑多久了。$N，请你向我们伸出援手吧，帮助我们对抗军团。冲上前线，阻止那些地狱火的攻势！', '蛮锤要塞外的空军指挥官努埃恩要求你杀死10个地狱火攻击者。', '感谢你减轻了我们的压力，$N。多了你的帮助，还有其它人的帮助，我们还撑的下去。不幸的是，勉强支撑是不够的。我们要主动出击。', '你已经累了吗，$C?', '', '去影月谷找蛮锤要塞的空军指挥官努埃恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10563, '转至军团要塞', '军团要塞固若金汤，难以攻取。老实说，我军也没有足够的兵力发动袭击。$N，所有的希望都寄托在你身上。$B$B从我们当前掌握的零碎情报来看，燃烧军团正在要塞中囤积和准备他们的地狱火大军。穿上这套伪装潜入军团要塞，打探他们的秘密计划。$B$B或许你能从燃烧军团指挥官们的谈话中偷听到一些东西。祝你好运，$N。', '转至军团要塞寻找军团通讯装置。在伪装状态下站在军团通讯装置附近，偷听燃烧军团的计划。完成任务后向蛮锤要塞的空军指挥官努埃恩复命。', '<空军指挥官奴艾恩听了你的报告，你的每一句话都更加的提高了他的警戒心。>$B$B你是说他们拥有充分的炼狱火可以猛烈的炮轰我们?假如我们不能阻止他们进行下一步计画，蛮锤要塞就玩完了。', '你发现了什么?', '', '去影月谷找蛮锤要塞的空军指挥官努埃恩。', '', '', '偷听燃烧军团的计划', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10564, '炸毁地狱火！', '我们装配出来的这玩意虽然其丑无比，但是它能消灭军团要塞的地狱火大军。瞧瞧魔能机甲能量核心对恶臭之池的影响，这东西蕴藏的爆炸威力可不容小觑。$B$B如果在军团要塞的绿色雕文中心引爆这个邪能炸弹，应该可以一举歼灭所有地狱火。', '站在军团要塞的绿色雕文上使用魔能炸弹消灭地狱火，然后向蛮锤要塞的空军指挥官努埃恩复命。', '做的好，$N!我希望我可以说燃烧军团在遭遇了这样的挫折之后会有放弃的念头，但是你我都知道这是不可能的事情。你在侦察任务中查探过的死亡熔炉将是我们的下一个目标。', '你找到摧毁军团囤积炼狱火的方法了吗?', '', '去影月谷找蛮锤要塞的空军指挥官努埃恩。', '', '摧毁军团要塞的地狱火', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10565, '维克鸦巢水晶', '多年来维克鸦人一直是我们的眼中钉。他们信奉某种奇怪的宗教，行为也因此变得癫狂。据说他们身上携带的维克鸦巢水晶具有某种邪恶的用途。$B$B我对维克鸦人的宗教仪式了解得不多，只知道他们利用维克鸦巢法阵对维克鸦巢水晶充能。杀入维克鸦巢，直到你找到水晶，然后将充能的水晶带回来供我研究。', '在维克鸦巢法阵使用维克鸦巢水晶，来制造充能的维克鸦巢水晶。', '哦，看它发光的样子!我一定要马上试试它。', '维克尼尔的阿拉卡多年来一直是和善的一族，但是现在某种东西正在煽动他们。', '', '去刀锋山找莫克纳萨村的德尔托克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10566, '测试魔杖', '我制作了四根魔杖，它们能强化维克鸦巢水晶的能量。带上这四根魔杖转至托格玛洞穴，在鸦人的食人魔奴隶身上试验它们的效果。$B$B每根魔杖都需要一颗充能的维克鸦巢水晶才能发挥效用。$B$B当你找出效果最好的那根魔杖后，回来向我复命。', '利用鸦人的食人魔奴隶试验德尔托克制作的四根魔杖。每根魔杖都需要一颗充能的维克鸦巢水晶才能发挥效用。', '这个资料非常的有用，$N。我将会进一步改良它的设计并且看看我们能否扩大它的用途。', '我热切的等待你的测试结果，$N。', '', '去刀锋山找莫克纳萨村的德尔托克。', '测试第一根魔杖', '测试第二根魔杖', '测试第三根魔杖', '测试第四根魔杖');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10567, '制造坠饰', '卢安荒野的鸦人是乌鸦之神的狂热崇拜者，整个氏族都听从乌鸦预言者的号令。$B$B鸦人们相信预言者为他们传达乌鸦之神的教义，是氏族的守护者。$B$B乌鸦预言者在鸦人中享有绝对的控制力，因此我们需要预言者佩戴的魔法坠饰。$B$B杀死卢安鸦人，将卢安利爪放置在祭坛处以吸引乌鸦预言者的注意。', '收集6只卢安利爪，在卢安预言法阵中使用它们召唤一名乌鸦预言者。杀死乌鸦预言者，将预言者的坠饰交给卢安荒野的坦莫。', '你得到了!$B$B有了这个坠饰，我就可以使你与葛瑞许纳什的阿拉卡同调化，这样就可以让你了解他们的语言。$B$B以这种方式，我们就可以进一步的了解阿拉卡还有他们神只的天性。我需要你的帮助才能完成这件事。', '一旦乌鸦神谕使察觉到你在攻击他的同胞，他会立刻开始反击。', '', '去刀锋山找常青林的坦莫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10568, '巴尔里石板', '影月谷中心的火山正是那位可怕的术士古尔丹数十年前的杰作，也因此，它被命名为古尔丹之手。当初，在这里的西南方曾有一座名叫巴尔里的德莱尼村落。火山爆发当日，大多数的村民和许多神圣古器都那场灾难中尽数被火山岩浆淹没，埋入了地底。$B$B最近，一支名叫灰舌的破碎者氏族奉伊利丹之命，在巴尔里废墟展开了一系列挖掘工作。他们的目标毫无疑问就是找回那些神器。我们必须利用这个机会夺回巴尔里石板。据说，那上面记载着许多卡拉波神殿——也就是黑暗神殿的秘密。', '沙塔尔祭坛的学者希拉要你收集12块巴尔里石板，它们散落在巴尔里废墟中，那里的灰舌工人身上也携带着这种石板。$B$B为奥尔多阵营完成任务将降低你在占星者阵营中的声望等级。', '巴瑞碑文!没错，这也许会提供我们非常有用的资料。', '你找到碑文了吗，$N?', '', '去影月谷找沙塔尔祭坛的学者希拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10569, '斯克瑟隆废墟', '从斥候带回的消息来看，附近那座废弃的鸦人营地的情形令人堪忧。$B$B鸦人魔法师们阴魂不散，他们拥有的强大力量超出了我们的想象。这些幽灵们似乎在有组织地预谋着什么，可惜我们对此所知有限。面对潜伏的危机，我们绝不能无动于衷！$B$B从这里向北走，到死亡熔炉西北方的斯克瑟隆废墟搜寻线索。', '从斯克瑟隆废墟黑暗教团的鸦人身上夺得斯克瑟隆指挥官的日记 - 第1页、斯克瑟隆指挥官的日记 - 第2页，以及斯克瑟隆指挥官的日记 - 第3页，将它们交给狮鹫骑士基尔兰。', '<凯兰快速的翻阅日记页面。>$B$B大部分的内容都难以辨识，但是我可以东拼西凑的看出内容是关于一个偏向邪恶的法术准备仪式、受害者还有堕落的场景。还有一个奇怪的注明关于一个\'背弃者\'。', '你发现了什么?', '', '去影月谷找蛮锤要塞的狮鹫骑士基尔兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10570, '血蓟瘾君子', '<伯拉克接过血蓟，放到鼻子下嗅了嗅。>$B$B真刺鼻……$B$B把这包东西放在石桥的另一端。特使每天都会在日蚀岗哨四处巡视；当他发现血蓟时，一定会撇下护卫，迫不及待地跑来捡起包裹。你知道，血精灵最瞧不起那些对血蓟上瘾的家伙。如果他的族人发现了这一点……$B$B你只需埋伏在一旁，等待特使遣散他的护卫，然后给他致命一击！杀掉特使，取回他携带的信件。', '将怒风的信件交给位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克。', '<柏尔拉克从你身上拿走了信件并且阅读它。>$B$B这些耍小聪明的精灵!这是伊利丹的指令，指示他们下一封密信藏在哪里。很显然的，他们一直更改藏信的地点。这封信件并没有告诉我们下一封密信藏在哪里……假如我们可以把这封公文送到他们的手上，我们就可以知道他们藏匿下一封密信的地点。$B$B可惜这封公文的封条已经被拆开了，要交还给他们已经不可能了。$B$B嗯，现在还不行……', '动作快一点，$g男孩:女孩;。', '', '去找影月谷的伯拉克，欧鲁诺克之子。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10571, '长者奥洛努', '根据巴尔里石板的记载，巴尔里废墟中埋藏着一件名为卡拉波勋章的神器。在过去，德莱尼人当中只有最高阶的祭司团成员才有资格得到这件神器，从而也获得了自由进出卡拉波神殿的权利。$B$B我们现在必须查明灰舌破碎者们是否已从废墟中挖掘出了这枚勋章。这件神器一定可以对我们抵抗伊利丹有所帮助。$B$B现在，驻守在巴尔里废墟的灰舌军官——长者奥洛努每天都会接到他的上司阿卡玛的书面指令。去把阿卡玛的命令带来给我。', '沙塔尔祭坛的学者希拉要求你从巴尔里废墟的长者奥洛努手中夺得阿卡玛的命令。$B$B为奥尔多阵营完成任务将降低你在占星者阵营中的声望等级。', '阿卡玛的亲笔书信。像他这样如此有智慧又被敬爱的人竟然会变成现在这个样子，真是想起来也叫我难过。', '你带回来了什么新消息了吗，$N?我们快没有时间了。', '', '去影月谷找沙塔尔祭坛的学者希拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10572, '制造炸弹', '燃烧军团意欲在转至黑暗神殿的行军途中摧毁蛮锤要塞，我们绝不能让他们的奸计得逞。$B$B$N，要阻止这场战事只有一个办法，那就是使用威力强大的炸弹将军团要塞的地狱火大军统统炸毁。$B$B军团要塞附近有一片恶臭之池，那里的魔能机甲动力核心可用作炸药。那些魔能机甲附近另一处废墟中的魔能机甲护板可用作炸弹外壳。', '将魔能机甲动力核心和魔能机甲护板交给蛮锤要塞的空军指挥官努埃恩。', '<空军指挥官将能量核心插入铠甲并密封仪器焊缝，点点头。>$B$B这应该可以了。如果要我说，这足以制造一个相当大的爆炸。', '<你将材料交给空军指挥官。>', '', '去影月谷找蛮锤要塞的空军指挥官努埃恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10574, '灰舌腐蚀者', '阿卡玛在指令中提到，被挖掘出来的4块勋章碎片分别由四位灰舌腐蚀者负责保管。这些灰舌腐蚀者本都是氏族中的萨满祭司，如今却转而与他们曾经崇拜与侍奉的元素为敌，唉……$B$B气之腐蚀者哈鲁姆当前在灵翼小径；地之腐蚀者埃肯尼和火之腐蚀者乌拉鲁，曾有人看见他们在古尔丹之手附近的魔能熔池旁出没；水之腐蚀者拉坎恩据说在库斯卡岗哨附近。$B$B杀死他们，取回全部的勋章碎片。', '从哈鲁姆、埃肯尼、拉坎恩和乌拉鲁手中夺得他们的勋章碎片，并把这些碎片交给影月谷沙塔尔祭坛的学者希拉。$B$B为奥尔多阵营完成任务将降低你在占星者阵营中的声望等级。', '没错!这就是四个勋章碎片。现在，来将它们结合在一起……', '你已经取回四个勋章碎片了吗，$N?', '', '去影月谷找沙塔尔祭坛的学者希拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10576, '影月谷的乔装者', '<伯拉克打量着你。>$B$B这事儿有些棘手，不过我应该能办到。$B$B$N，我打算把你伪装成一名伊利达雷血精灵。但首先你得给我找些血精灵的护甲来，护甲必须保持整洁，不能有任何血渍！这样才不会引起怀疑。$B$B替我收集一些护甲，剩下的事就交给我吧。$B$B伪装完毕后，你就要亲自把口信传达给他们的总指挥官了。', '将6件日蚀护甲交给位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克。', '做的好，$N。我希望你是一个很好的$g男演员:女演员;。在我伟大的计画里下一步将需要一些戏剧成分!', '这太复杂了，$r。你不会了解的。', '', '去找影月谷的伯拉克，欧鲁诺克之子。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10577, '伊利丹的信使……', '带上这件血精灵伪装转至日蚀岗哨。记得及时换上伪装。日蚀血精灵大多不可能识破你的真面目，一路畅行无阻，你便可以见到总指挥官卢斯克。$B$B找到卢斯克后，告诉他诅咒密码的下一个藏匿点。$N，这场戏你可得用心去演。摆足架势，把自己想象成传达伊利丹口信的长官。这样必定能唬到他！$B$B哦，记得避开日蚀龙鹰，它们可以识破你的伪装。', '位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克要求你将伊利丹的口信传达给日蚀岗哨的总指挥官卢斯克。', '现在你只需要去拿到那个密件而已。很简单，对吧?', '这真是个巧妙的伪装。除了步行以外的其它动作都会中断维持伪装的魔法力量。', '传达伊利丹的口信', '去找影月谷的伯拉克，欧鲁诺克之子。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10578, '诅咒密码 - 伯拉克的命令', '不能让祖鲁希德拿到诅咒密码的碎片。你必须抢在亵渎者鲁尔将它转交给祖鲁希德之前劫回碎片。$B$B在这里的正东方，灵翼平原对面便是龙喉要塞，鲁尔就在龙喉要塞和群星圣殿之间的某处。一旦你发现他的踪迹，就迅速杀掉他！$N，从我们套出的情报来看，鲁尔是个不好对付的家伙。请千万小心。$B$B夺得诅咒密码的碎片后就回来向我复命。', '从亵渎者鲁尔手中夺回诅咒密码的第二块碎片，然后向位于影月谷日蚀岗哨附近石桥处的欧鲁诺克之子伯拉克复命。$B$B该任务最好组队完成。', '终于!密码碎片终于是我们的了!$B$B\r\n<柏尔拉克将碎片收入了一个箱子里。>', '你必须动作快一点!', '', '去找影月谷的伯拉克，欧鲁诺克之子。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10579, '诅咒密码 - 第三块碎片', '将箱子交给我的父亲。他住在库斯卡水池附近的欧鲁诺克农场，在遥远的北方。一旦集齐了碎片，我们就可以解读诅咒密码了。$B$B祝你好运，$N。请转告我的父亲，我会尽快启程返家。', '将伯拉克的箱子交给影月谷欧鲁诺克农场的欧鲁诺克·裂心。', '等到三块密码碎片重新结合，隐藏在里头的古老文字就会出现。$B$B毫无疑问的是找回这个碎片的困难度很高。你应该为你的英勇行为受到奖赏。', '$N!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10582, '暗影议会的爪牙', '<伊万一边听着你汇报军团要塞的情况，一边不停地点着头。>$B$B听你这么一说，我们探察到的线索逐渐清晰了许多。侦察兵们曾隐约发现他们在向军团要塞那边输送地狱火，但是未能探得更多细节。$B$B暗影议会则将死亡熔炉部署得跟雷霆啤酒桶一般密不透风。因此，你首先得扫平外围的障碍。去消灭驻守在死亡熔炉入口处的暗影议会卫兵吧！', '杀死10个死亡熔炉守护者和5个死亡熔炉召唤者，然后向死亡熔炉哨塔的伊万·蛮翼复命。', '我希望我也可以跟你一同前去!闲置已久的战锤使我非常手痒，谁叫我的任务是观察，不是杀戳呢。$B$B现在你已经在他们的防御网上打出了一个缺口，让我们去终止死亡熔炉的生产线吧。', '你已经清出一条路通往死亡熔炉的通道了吗?', '', '去影月谷找死亡熔炉哨塔的伊万·蛮翼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10583, '弗兰尼斯的命运', '空军指挥官努埃恩指派我和另外两名侦察兵来这儿密切注视死亡熔炉的动向，并收集情报。弗兰尼斯·迅翼自告奋勇潜入死亡熔炉，可是数日来都没有他的消息。$B$B我担心事情不妙了，$N。虽然弗兰尼斯是一位经验丰富的侦察兵，可是这次他孤身深入敌后，我们已经无法与他取得联系。请你立刻转至死亡熔炉寻找他的行踪，获取他收集到的情报或物品。', '死亡熔炉哨塔的伊万·蛮翼要你转至死亡熔炉寻找弗兰尼斯·迅翼，并找回弗兰尼斯的背包。', '<艾文摇了摇头的从你手中接收了背包。>$B$B我想弗蓝尼斯并不了解死亡熔炉的守备有多森严。现在我们了解了那边的真实状况，我并不怪他们。我只希望弗蓝尼斯在进去之前就先能了解那边的状况。$B$B我只希望这里有东西可以帮助我们永久的让死亡熔炉停工。', '你在死亡熔炉有找到任何弗蓝尼斯的踪迹吗?', '', '去影月谷找死亡熔炉哨塔的伊万·蛮翼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10584, '能量转换器', '北边刀塔哨站里那些蠢笨的食人魔曾袭击过我们，抢走了我们的能量转换器！你得去把它们给我抢回来，有多少抢回来多少。$B$B不过，想都不用想，他们那又肥又笨的手掌肯定把转换器都搞坏了。那么这样吧，你需要直接释放它们里面的能量，然后对着释放出来的电浆使用这个电磁收集器，把它固化吸收。$B$B它可能会给你搞出点麻烦，所以收录进磁力球之后，你得把它“杀掉”。', '使用电磁收集器收集5个电荷元素。', '太棒了!反正你帮我们取回来的电源能量可以让我们的机械运作好一阵子了。$B$B当ZC号的电源耗尽的时候还真是一个没用的东西!$B$B我希望取回电流体的这件事不会太困难。我有别的事情想请你去做，而我有预感这将会有一点危险。', '我们用电流体所进行的一系列研究还真是刺激呀!想想看……只要我们愿意就可以生产有智慧的电子生物并且只会听从我们的指令!$B$B还有什么地方会出差错呢?', '', '去刀锋山找托什雷的基地的托什雷。', '收集电荷元素', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10585, '召唤之厅', '为了满足燃烧军团的地狱火兵力需求，暗影议会必定挑选了一处隐蔽之地，在那里召唤堕落的元素生物来构成地狱火的核心部分。$B$B召唤室通常在地下，附近会有被污染的水池或熔岩。转至死亡熔炉寻找召唤大厅，并设法破坏他们的召唤仪式。一些莫尔葛恶魔也参与了制造地狱火，他们身上携带的某种工具或许能打断召唤师的魔法。', '从死亡熔炉铁匠或死亡熔炉杂役身上取得元素置换器，用它打断召唤大厅中的召唤仪式。完成任务后返回死亡熔炉哨塔向伊万·蛮翼复命。', '做的好，$N。瓦解暗影议会的召唤仪式让我们在终止死亡熔炉运作这件事上更进一步了。', '我们不能容许他们继续制造地狱火。你已经终止召唤仪式了吗?', '', '去影月谷找死亡熔炉哨塔的伊万·蛮翼。', '终止地狱火召唤仪式', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10586, '击败战争使者！', '我们这次成功地阻止了暗影议会在死亡熔炉的军事扩张行动，但是要想取得全面胜利，就必须击败燃烧军团派驻在死亡熔炉的头目。$B$B我在弗兰尼斯的背包中找到了一把钥匙。它必定能帮你找到军团要塞的战争使者拉索恩的行踪。$B$B找到并击败战争使者拉索恩，然后直接向空军指挥官努埃恩复命。他正在焦急地等你的好消息呢！', '击败战争使者拉索恩，取回拉索恩的命令，然后返回蛮锤要塞向空军指挥官努埃恩复命。', '<你向空军指挥官回报并且交给他夺回的文件。>$B$B击败战争使者瑞术恩可能表示我们与燃烧军团之间的战事已经划下句点了，但是这些文件中的描述显示出他们的计画远比我想象中还要大许多。恐怕我们还有很多事情要做。', '你从死亡熔炉带回了什么消息呀?', '', '去影月谷找蛮锤要塞的空军指挥官努埃恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10587, '卡拉波训练场', '据斥候回报，一支由日怒血精灵新兵组成的大部队当前正朝卡拉波废墟前进。原本，如此大规模的军事行动势必会构成强烈的军事威胁，但是我们相信此事另有内情。$B$B他们的服饰和战斗风格很像伊利丹麾下的部队。我可不想自乱阵脚。转至卡拉波废墟取回他们的武器，这样我们就能搞清楚状况了。', '沙塔尔祭坛的大主教欧纳拉要你转至沙塔尔祭坛东南方的卡拉波废墟，从恶魔猎手学员和恶魔猎手新兵身上夺取8柄日怒阔剑。$B$B为奥尔多完成任务将会降低你在占星者阵营中的声望等级。', '让我们靠近一点看这些武器，$N。嗯……这还真是令人不安啊。', '你已经完成我要求的工作了吗，$N?', '', '去影月谷找沙塔尔祭坛的大主教欧纳拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10588, '诅咒密码', '不知道这条危害世间的咒语被使用过多少次。你也看到了，它强大的破坏力是毋庸置疑的。$B$B带上经过修复的诅咒密码，转至诅咒祭坛，在古尔丹面前吟唱咒语。$B$B念诵咒语时，那些镌刻在大地上的回忆将浮现在你眼前，而你要做的就是等待火焰之王森卢肯现身。$B$B$N，你必须击败他。这片土地已经无法承受新一轮的摧残了。', '在诅咒祭坛念诵诅咒密码，召唤出火焰之王森卢肯。$B$B杀死火焰之王森卢肯，然后与诅咒祭坛的大地治愈者托洛克谈一谈。', '<大地治愈者托尔洛克从你身上拿走了毁灭密码。>$B$B你已经完成了元素们的要求。关于你的付出，我们非常感谢。我将给你应得的报酬，但是问题仍然潜伏在台面下，蠢蠢欲动。这件事情引起了火焰之灵们的一阵骚动。它们已经做出了决定。毁灭密码被它们认为是另外一样东西。$B$B我也知道这件事情很神秘，可是火焰之灵们也只让我知道这么多而已。这件事还有这个符号……$B$B<大地治愈者托尔洛克转过身背对着你然后指向了天空。>$B$B这代表着什么意义呢?', '完成了吗?', '', '去影月谷找诅咒祭坛的大地治愈者托洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10589, '控制权', '从拉索恩的命令来看，地狱火大军转移到了登陆场：灾难，就在北面的山上！只有使用军团要塞内的传送装置才能达到那里。$B$B燃烧军团的某些爪牙必定随身携带着可以控制传送装置的设备。你必须搞到这种设备才能使用传送装置。杀光那些恶魔，一一搜尸，绝不能空手而归。', '将军团传送控制器交给蛮锤要塞的空军指挥官努埃恩。据说军团要塞的莫尔葛武器匠身上携带着这东西。', '让我看看这个东西怎么使用……', '我们必须想办法摧毁剩下的炼狱火，$N。我们已经奋斗到了这个地步，但是一次失败就可能让我们失去所有。', '', '去影月谷找蛮锤要塞的空军指挥官努埃恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10590, '仇恨的证明', '阿尔萨斯和他的天灾军团背负着沉重的血债……你要牢记这段不该被遗忘的历史。$B$B燃起复仇的怒火是释放我们内心伤痛的惟一途径。不幸的是，恐惧和痛楚对这帮行尸走肉完全不起作用。只有将其彻底毁灭才能给你的心灵带来一点点慰藉。$B$B与银色黎明的军官加鲁什交谈，了解天灾石的来历以及获得天灾石的方法。在我们再次交谈之前，我需要你交给我一些天灾石，作为你的能力和仇恨的凭证。', '亡灵壁垒的麦拉·黎明之刃要求你给他带去20枚爪牙的天灾石。', '非常好，$N。或许你对复仇很有天份。', '你尝到复仇的快感了吗?', '', '去找提瑞斯法林地的麦拉·黎明之刃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10592, '女妖之王的智慧', '一旦脱离了主人的身体，天灾石的力量就会减弱。瞧，我轻轻一握就能粉碎它们。$B$B<麦拉将天灾石捏成了碎片。>$B$B转至幽暗城的皇家区，将这些天灾石碎片交给女妖之王希尔瓦娜斯·风行者。女王知道如何将这些碎片铸造成对抗亡灵天灾的利器。', '转至幽暗城，将天灾石碎片交给希尔瓦娜斯女王。', '这些石头带着一个我不想记起的污点，但我也无法忘记。你把这些带来给我是在考验我的耐心。$B$B不过，很清楚的，你和我寻求一样的复仇，我会帮助你并给你指示。', '你有什么东西要给我吗，$r?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10593, '远古的邪恶', '想要把这堆石头打造成武器来对抗天灾士兵，你就需要某种侵染着邪恶气息的物品来强化它们。$B$B悲伤沼泽的阿塔哈卡神庙深处潜伏着古老的邪灵。释放并击败这个邪灵，然后将他的残骸交给麦拉·黎明之刃。我的卫兵们会替你将天灾石碎片交给麦拉的。', '揭开阿塔哈卡神庙的秘密，释放阿塔拉利恩并击败他，从他的尸体上取走腐烂藤蔓。完成任务之后向亡灵壁垒的麦拉·黎明之刃复命。', '女妖之王将你引导的很好。这确切是我需要去结合碎片的东西。$B$B<当藤蔓穿过碎片交织时，米哈尔注视着并把他们捆在一起。>$B$B那里!天灾毒物，我将召唤它。当你使用它时，谨慎小心，因为它违反它的意愿为你效劳。', '假使你活着，我只能推测你运气好得获得智慧，而不是希尔瓦娜斯所给予的死亡。', '', '去找提瑞斯法林地的麦拉·黎明之刃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10594, '测量振荡频率', '把这些扫描器带到晶歌山脉去。你只需把它们按照特定的样式和位置摆放在地上，就可以创造出一个多维度的力场群，这个力场群会解读和分析出那些水晶的频谱。然后呢，你要按这样的方式站在它们中间，让五个振动场都能复盖到你，这样我就可以得到我需要的信息了！$B$B你的扫描器甚至还会对落入场中的其它东西产生反应。$B$B哦，对了，运行的时候，可能还会产生一道空间裂隙！我不知道里面有什么东西会跑出来，但你最好有心理准备。', '测量者尼克维克要你将振荡频率扫描器按照一定方式摆放在地上，当你站进中央时，你必须能够同时受到5个重叠扫描场的影响。', '哇，这真是太棒了!我实在搞不清楚……就好像这些水晶是有生命似的。$B$B我在想这些水晶跟虚空龙之间有没有某种特殊的关连性?$B$B谢谢你，谢谢!你一定要收下我的一点感谢之意，一些我的零件和完成品珍藏。$B$B他们之中一定有一个适合你。', '嗯，你已经完成了我要求的歌唱水晶的测量资料了吗?', '测量歌唱水晶震荡频率', '去刀锋山找托什雷的基地的测量者尼克维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10595, '兵临城下！', '<古尔穆克望着天空。>$B$B哎……我们的士兵消灭敌人的速度根本就跟不上他们补充兵力的速度。$B$B燃烧军团当前盘踞在西南方的军团要塞，每天召唤出的地狱火总能像潮水般朝我们这里涌来。就算是库卡隆的精英将士也没法阻挡他们的攻势。$B$B每一位强壮的$c都应该承担起保卫影月村的重担。这可不是儿戏，$c，形势确实已经岌岌可危。为了部落的荣耀，加入前线大军的阵列吧！', '影月村外的血卫士古尔穆要求你杀死10个地狱火攻击者。', '你可以在这场大屠杀当中存活下来让我印象深刻。你可能就是我们要执行危险任务的最佳人选。', '你已经累了吗，$C?', '', '去影月谷找影月村的血卫士古尔穆克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10596, '转至军团要塞', '你的目的地是军团要塞。你没有援军，所以就不要想发动正面攻击了。$B$B从我们当前掌握的零碎情报来看，燃烧军团正在要塞中囤积和准备他们的地狱火大军。穿上这套伪装潜入军团要塞，打探他们的秘密计划。$B$B或许你能从燃烧军团指挥官们的谈话中偷听到一些东西。', '转至军团要塞寻找军团通讯装置。在伪装状态下站在军团通讯装置附近，偷听燃烧军团的计划。完成任务后向影月村的血卫士古尔穆克复命。', '<血卫士高莫克听着你的报告，他的警戒心随着你的每一句话而提高。>$B$B你说他们将加速轰炸攻击的准备是什么意思?我们不能允许这样的事情发生。在影月村还没有被完全摧毁之前回去那边解决这个问题!', '你发现了什么?', '', '去影月谷找影月村的血卫士古尔穆克。', '', '', '偷听燃烧军团的计划', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10597, '制造炸弹', '燃烧军团意欲在转至黑暗神殿的行军途中摧毁蛮锤要塞，我们绝不能让他们的奸计得逞。$B$B设法消灭地狱火大军。$N，这不是请求，而是命令。$B$B军团要塞附近有一片恶臭之池，那里的魔能机甲动力核心可用作炸药。那些魔能机甲附近另一处废墟中的魔能机甲护板可用作炸弹外壳。收集这些两样东西来，然后你就可以制造出一枚威力强大的魔能炸弹了。', '将魔能机甲动力核心和魔能机甲护板交给影月村的血卫士古尔穆克。', '<高莫克将能量核心插入外罩并将它密封。>$B$B这应该可以了。当爆炸发生的时候我可不想在堡垒里。', '<你将材料交给高莫克。>', '', '去影月谷找影月村的血卫士古尔穆克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10598, '炸毁地狱火！', '我们装配出来的这玩意虽然奇丑无比，但是它能消灭军团要塞的地狱火大军。瞧瞧魔能机甲能量核心对恶臭之池的影响，这东西蕴藏的爆炸威力可不容小觑。$B$B如果在军团要塞的绿色雕文中心引爆这个邪能炸弹，应该可以一举歼灭所有地狱火。', '站在军团要塞的绿色雕文上使用魔能炸弹消灭地狱火，然后向影月村的血卫士古尔穆克复命。', '<高莫克严肃的点了点头。>$B$B现在可不是庆祝的时候，$N。我们还没脱离险境。我有新的指令要交给你。', '你找到摧毁军团囤积炼狱火的方法了吗?', '', '去影月谷找影月村的血卫士古尔穆克。', '', '摧毁军团要塞的地狱火', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10600, '暗影议会的爪牙', '<萨格兰听你汇报军团要塞的情况，不停地点着头。>$B$B你探察到的情况跟我们掌握的线索恰好吻合。侦察兵们曾隐约发现他们在向军团要塞那里运送地狱火，但是未能探得更多细节。$B$B暗影议会将死亡熔炉部署得密不透风。看来你得首先扫平沿途的障碍，先去消灭驻守在死亡熔炉入口处的暗影议会卫兵吧！', '杀死10个死亡熔炉守护者和5个死亡熔炉召唤者，然后向熔渣哨塔的斥候萨格兰复命。', '我自己也曾经去过那边敲碎敌人的脑袋，但是我现在有命令在身不允许我跟敌人交战。$B$B<这个斥候一边用模仿的唯妙唯肖的血卫士高莫克的声音一边说着。>$B$B让我们去终止他们的生产线吧。', '你已经清除通往死亡熔炉的道路了吗?', '', '去影月谷找熔渣哨塔的斥候萨格兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10601, '卡格罗什的命运', '侦察小队原本有三名成员，偏偏卡格罗什这家伙逞强好胜，想当英雄。$B$B他孤身潜入死亡熔炉后，便与我们失去了联系。$B$B现在，这个蠢货很可能已经被杀掉了，暗影议会的成员可不是傻子，卡格罗什也算不得侦察兵中的佼佼者。你立刻转至死亡熔炉寻找他的行踪，带回他收集到的情报或物品。', '熔渣哨塔的斥候萨格兰要你转至死亡熔炉寻找卡格罗什，并找回卡格罗什的背包。', '<萨葛兰一边摇头一边接过了你找回的背包。>$B$B我跟你说过他是一个笨蛋。我希望背包里头有我们可用的东西，这样才不枉你花那么多的时间去寻找他。', '你在死亡熔炉有找到凯格罗西的踪影吗?', '', '去影月谷找熔渣哨塔的斥候萨格兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10602, '召唤之厅', '为了满足燃烧军团的地狱火兵力需求，暗影议会必定挑选了一处隐蔽之地，在那里召唤堕落的元素生物来构成地狱火的核心部分。$B$B召唤室通常在地下，附近会有被污染的水池或熔岩。转至死亡熔炉寻找召唤大厅，并设法破坏他们的召唤仪式。一些莫尔葛恶魔也参与了制造地狱火，他们身上携带的某种工具或许能打断召唤师的魔法。', '从死亡熔炉铁匠或死亡熔炉杂役身上取得元素置换器，用它打断召唤大厅中的召唤仪式。完成任务后返回熔渣哨塔向斥候萨格兰复命。', '太好了，我们又更进一步了。这让我们更加靠近终止死亡熔炉运作然后安全回到影月村的目标\r\n。', '我们不能允许他们继续生产。你已经终止了他们的召唤仪式吗?', '', '去影月谷找熔渣哨塔的斥候萨格兰。', '终止地狱火召唤仪式', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10603, '击败战争使者！', '我们成功地阻止了暗影议会在死亡熔炉的军事扩张行动，现在是彻底肃清这帮家伙的时候了。$B$B我在卡格罗什的背包中找到一把钥匙。看来卡格罗什还是有所收获的。$B$B这把钥匙应该能帮你找到军团要塞的战争使者拉索恩的行踪。$B$B搜寻并击败战争使者拉索恩，然后直接向血卫士古尔穆克复命。可别让他等太久。', '击败战争使者拉索恩，取回拉索恩的命令，然后返回影月村向血卫士古尔穆克复命。', '<你向血卫士回报的同时交出了你夺回的指令。>$B$B做的好，$N，但是别以为这件事可以让你拿到任何勋章绶带。让夜精灵们随他们的意思来装饰自己的战服吧。真正的战士只会透过一大杯的麦芽酒来歌颂自己的英勇战绩。', '你从死亡熔炉带回了什么消息呢?', '', '去影月谷找影月村的血卫士古尔穆克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10604, '控制权', '从拉索恩的命令来看，地狱火大军转移到了登陆场：灾难，就在我们村子后面的山上！只有使用军团要塞内的传送装置才能达到那里。$B$B燃烧军团的某些爪牙必定随身携带着可以控制传送装置的设备，你必须搞到这种设备才能使用传送装置。杀光那些恶魔，一一搜尸，绝不能空手而归。快去吧，情势危急，敌人离我们很近了。', '将军团传送控制器交给影月村的血卫士古尔穆克。据说军团要塞的莫尔葛武器匠身上携带着这东西。', '终于，我们有办法把燃烧军团赶出影月谷了!', '我们无法容忍燃烧军团出现在我们之中!我们必须在他们重组突击攻击前想办法解决。', '', '去影月谷找影月村的血卫士古尔穆克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10606, '魔能机甲维修窍门大全', '歼灭燃烧军团残馀势力的最好办法便是以彼之道还施彼身。我一直在开发某种可以操控魔能机甲斥候的仪器。$B$B当然，还有一堆设计上的问题没解决。我需要加特里克博士的手册。不过，这家伙总是把它锁在斜坡底部的箱子里，他应该不会轻易交出钥匙。你得用抢的，朋友。取回魔能机甲的手册，剩下的就由我来搞定！', '杀死加特里克博士，用博士的钥匙打开博士的保险箱，从中取出魔能机甲维修窍门大全，把它交给登陆场：灾难的普雷西。', '喔，这正是我们需要的。我从来没有谴责燃烧军团会出版任何类似文学的东西，但是现在它可是帮了我一个大忙。', '你拿到那本手册了吗?', '', '去影月谷找登陆场：灾难的普雷西。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10607, '乌鸦之神的低语', '格里施纳的鸦人利用乌鸦预言者留下的图腾，聆听来自乌鸦之神的神喻。不幸的是，我们无法解读鸦人的语言。$B$B这枚预言者的坠饰或许能帮助我们。你必须借助鸦人的灵魂来破解他们的语言。当鸦人之魂附着在你身上后，你就能破解图腾的秘密了。$B$B$N，帮我们揭开乌鸦之神的秘密吧。', '杀死格里施纳的鸦人，获得持续2分钟的理解鸦语效果。利用该法术破解四座神殿的预言，完成任务后向坦莫复命。', '这真是令人不安啊。阿拉卡人长久以来一直是和平的民族。他们对乌鸦神的狂热信仰只能用不正常还有疯狂来形容。$B$B但是他们的力量已经成长到我们无法低估的境界。也许这个乌鸦神还有我们所不知道的事情。', '这个乌鸦神是谁?他们以为他会做出什么事?他们以为他会怎么引导他们?', '', '去刀锋山找常青林的坦莫。', '获知第一个预言', '获知第二个预言', '获知第三个预言', '获知第四个预言');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10608, '水晶剥石者的麻烦', '那些该死的剥石者搞得我根本没办法到晶歌山脉下面去进行研究！它们一直在不停地挖掘那里的水晶，每一爪都是在毁灭我研究这些歌唱水晶的机会。$B$B你看起来像是个能帮我解决问题的人。到南边去，把那些该死的水晶剥石者都消灭干净吧。', '杀死10只水晶剥石者。', '杀的好呀;我说。这些可恶的东西!$B$B假如你已经确定你消灭了那些害虫，那么我有一个小小的研究计画要请你帮忙。我想你会喜欢的。', '你已经杀死了美声山脊的水晶镰夺怪了吗?不然我们的研究就无法进行了。', '', '去刀锋山找托什雷的基地的测量者尼克维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10609, '先有龙还是先有蛋？', '我正在研究各种龙类精华的药用价值，它们很可能是治愈多种疾病的灵药！$B$B我想派人转至南边的晶歌山脉，取回一些龙类精华。$B$B你愿意帮忙吗？对着那些从虚空龙蛋中孵化出的虚空幼龙使用时间定相调节器就行，将你收集到的各种龙类精华带回来给我。$B$B不过，这个时间定相调节器只是个我改造出来的工具，其实我自己也不知道虚空幼龙能转化出什么样龙类精华。', '收集3份始祖虚空幼龙的精华、3份健壮虚空幼龙的精华和3份成熟虚空幼龙的精华。', '你不知道这个研究的重要性。谢谢你!$B$B能够深入的去研究这些精华是很有趣的。我特别好奇想知道把黑龙蛋突变成虚空龙蛋的虚空效应会不会对我的研究有任何额外帮助的潜力。$B$B我在想，事实上你应该是第一个享受到我所做出来的小混和物好处的人。拿好这些初级试验品，当你有需要的时候就使用它们吧。', '东西到手了吗?你已经拿到了我衷心需要用来继续我的研究的三种龙之精华了吗?$B$B你知道那些虚空龙蛋曾经是黑龙蛋吗?这是事实!但是当德拉诺毁灭的时候，残存的虚空龙们跨越彼此种族而产下突变的蛋。', '', '去刀锋山托什雷的基地找菲兹特·表针。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10611, '魔能机甲维修窍门大全', '歼灭燃烧军团残馀势力的最好办法便是以彼之道还施彼身。我一直在开发某种可以操控魔能机甲斥候的仪器。$B$B当然，还有一堆设计上的问题没解决。我需要麦尔费苏斯博士的手册。不过，这家伙总是把它锁在斜坡底部的箱子里，他应该不会轻易交出钥匙。你得用抢的，朋友。取回魔能机甲的手册，剩下的就由我来搞定！', '杀死麦尔费苏斯博士，用博士的钥匙打开博士的保险箱，从中取出魔能机甲维修窍门大全，把它交给登陆场：灾难的纳斯坎。', '这有我要的资讯。只要再一下子，我们就能让你控制恶魔劫夺者。', '你取得手册了吗?', '', '去影月谷找登陆场：灾难的纳坎斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10612, '狂暴的魔能机甲', '<普雷西迅速翻阅着手册。>$B$B嗯，手册上记载着我需要的所有信息，现在只剩最后一个问题了。要知道，魔能机甲并不具备遥控的功能。$B$B不过，我们倒是可以改装出一台控制器来，但是它的控制有效期很短；你得抓紧时间，不然谁也无法预料会发生什么事！那帮燃烧军团的走狗目睹被控制的魔能机甲引发骚乱，必定会大跌眼镜。保持警惕，尽可能地消灭那些地狱火！', '使用魔能机甲控制台控制一台魔能机甲斥候，并在控制失效之前杀死60个死亡熔炉地狱火。完成任务后向登陆场：灾难的普雷西复命。', '太棒了!你已经成功的办到所有蛮锤要塞的狮鹫骑士都做不到的事情!你已经断了燃烧军团发展的后路而且你拯救了我们从他们的炼狱火手中被歼灭的命运。你的英勇行为已经赢得我们最高的感激，$N。', '你回来啦，我猜你的行动进行顺利。你有什么要向我报告呢?', '', '去影月谷找登陆场：灾难的普雷西。', '摧毁死亡熔炉的地狱火', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10613, '狂暴的魔能机甲', '<纳坎斯迅速翻阅着手册。>$B$B嗯，手册上记载了我需要的所有信息，现在只剩最后一个问题了。要知道，魔能机甲并不具备遥控的功能。$B$B不过，我们倒是可以改装出一台控制器来，但是它的控制有效期很短；你得抓紧时间，不然谁也无法预料会发生什么事！那帮燃烧军团的走狗目睹被控制的魔能机甲引发骚乱，必定会大跌眼镜。在确保自身安全的同时请以影月村赋予你的使命为重！', '使用魔能机甲控制台控制一台魔能机甲斥候，并在控制失效之前杀死60个死亡熔炉地狱火。完成任务后向登陆场：灾难的纳坎斯复命。', '我承认，$N。你完成的壮举让我很佩服。摧毁燃烧军团在影月的作战能力将会给我们机会扭转战局。', '你回来啦，我猜你的行动进行顺利。你有什么要向我报告呢?', '', '去影月谷找登陆场：灾难的纳坎斯。', '摧毁死亡熔炉的地狱火', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10617, '丝翼蛾茧', '丝翼巨蛾的茧丝用途广泛，是制作各种生活用品的主要原料。我们对茧丝的需求量居高不下。$b$b但是当幼虫开始蜕变时，就很难收集到蛾茧了。$b$b我们的士兵正忙着抵抗外敌入侵，如果你愿意抽空帮我们收集一些蛾茧就最好不过了。', '从丝翼幼虫身上收集8个丝翼蛾茧。$b$b迅速杀死幼虫，否则它们就会蜕变成丝翼巨蛾，破坏蛾茧。', '这些茧的品质真好。我看的出来你的手很适合采集它们。$B$B我们自己也有尝试养丝翼幼虫，但是可惜小只的幼虫并没有生产足够的茧供大家使用。', '采集茧需要一双快速而稳健的手。我希望你能成功。', '', '去刀锋山找莫克纳萨村的塔耶雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10618, '最柔软的翅膀', '对年轻的士兵而言，捕杀丝翼幼虫是一个艰巨的挑战。值得庆幸的是，就算无法从幼虫身上收集到蛾茧，我们仍然能够利用丝翼巨蛾的翅膀。$b$b事实上，蛾翼的用途比蛾茧更为广泛，我们对此的需求量也相当巨大。$b$b如果你恰好要外出，能不能帮我带些蛾翼回来？', '收集12片虹光之翼。', '谢谢你，$N。我们会比你想得更快使用这些东西。', '这些翅膀十分精致，不过可加入我们的设计成为一个装饰的成份。', '', '去刀锋山找莫克纳萨村的希尔玛拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10619, '灰舌氏族', '灰舌氏族是所有破碎者中最可怕的存在，这个氏族的成员都经过阿卡玛的精挑细选，个个生性邪恶、嗜血成瘾。即使是与伊利丹麾下的其它纳迦部队、恶魔部队或是血精灵部队相比，他们的残忍与无情也毫不逊色。眼下，有大批灰舌破碎者盘踞在西南方的巴尔里废墟一带。我们要先下手为强，在这帮家伙有机会攻击我们之前削弱他们的势力。', '守备官奥鲁门要你进入巴尔里废墟，杀死3名灰舌驯兽者、4名灰舌战士和6名灰舌萨满祭司。$B$B为奥尔多完成任务将降低你在占星者阵营中的声望等级。', '纳鲁万岁，$N。你已经完成圣光的命令打败了伊利丹的追随者。', '你已经完成我交给你的任务了吗，$N?', '', '去影月谷找沙塔尔祭坛的守备官奥鲁门。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10620, '山脊上的危险', '托什雷最初决定迁移到外域时，就雇佣了我们作帮手，我们从那时候起就搬到了这里。$B$B现在，我们终于在这里扎下一些根基了。这里几乎所有的狂热科学家们都在进行着各自的研究计划，而我们这些硬汉队的成员则要负责保护他们。$B$B现在我们需要你帮忙，请转至北边的剃刀山，或是东边的鳞翼岩床，清理那边的捕猎者吧。这些行踪诡秘的蜘蛛总是隐藏在露出地面的大块岩石附近，一旦有警惕心松懈的旅人经过，就会跳出来发动袭击。', '杀死10只山脊捕猎者。', '以一个菜鸟来说你做的还不错。结果我们有一批由书呆子组成的小队伍想要去北边“勘查”以太族还有他们的科技。这些书呆子要是知道了你帮他们清除了路上的危险一定很兴奋。$B$B来，这些拿去。我们拥有的数量并不多，但是希望它们可以在将来帮上你的忙。', '你已经清光那些巡者了吗?我们已经有几个人往北边去却失踪了。$B$B假如是那些巡者造成的话，我要确保这种事情不会再发生。', '', '去刀锋山托什雷的基地里找晕乎乎的迪娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10621, '伊利达雷斩除碎片', '这似乎是一块武器的残片，金属表面镌刻着的符文依然清晰可辨，并闪烁着诡异的光芒。$B$B这把武器的用途已经不得而知，但你很想解开这个疑团。军团要塞的莫尔葛武器匠似乎经常使用这种材质的金属铸造武器。或许蛮锤要塞的武器锻造师能替你揭开谜底？', '将伊利达雷斩除碎片交给蛮锤要塞的奥丁·雷拳。', '<欧尔汀从你手中接过了武器碎片。>$B$B我好久没看过这种东西了。当然，这是由一个稀有的矿石所制造的，但是它肯定不是一般普通的武器，$N。它的剑身被注入一股消灭恶魔的魔法能量。假如你是从燃烧军团那边取来的，那一定是他们在制造某种“秘密武器”，计画用来对付伊利丹。真是一大发现!', '你手中的是什么东西?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10622, '忠诚的证明', '$N，你不知道，其实阿卡玛大人一直在暗中观察你的动向。$B$B事实上，你在巴尔里废墟杀死的那些灰舌氏族成员正是所有破碎者中生性最为邪恶的一群，阿卡玛精心挑选出这样一批凶残的成员，为的正是利用他们的表现迷惑伊利丹。而我们灰舌死誓者才是阿卡玛真正的心腹，只有我们才了解大人真正的意图。$B$B最重要的事情是，我们必须确定你不是伊利丹的同伙。伊利丹指派了一个名叫杉德拉斯的萨特负责监视整座守望者牢笼。杀死他，以此证明你的忠诚。', '杀死影月谷内守望者牢笼的杉德拉斯，然后向萨诺鲁复命。', '很好，$N。你已经表明了你的立场。你现在可以见阿卡玛。', '你完成我要求你的事了吗，$N?', '', '去影月谷找守望者牢笼的萨诺鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10623, '伊利达雷斩除碎片', '这似乎是一块武器的残片，金属表面镌刻着的符文依然清晰可辨，并闪烁着诡异的光芒。$B$B这把武器的用途已经不得而知，但你很想解开这个疑团。军团要塞的莫尔葛武器匠似乎经常使用这种材质的金属铸造武器。或许影月村的武器锻造师能替你揭开谜底？', '将伊利达雷斩除碎片交给影月村的格罗克姆·死眼。', '<格罗姆空从你手中接过了武器碎片。>$B$B我好久没看过这种东西了。这块碎片不光是从一个稀有的矿石所打造的，它也不是用在一般的武器上面，$N。上面的魔法图样赋予了武器消灭恶魔的力量。假如他们愿意让他们的部队配备消灭恶魔的武器，这表示燃烧军团有多痛恨伊利丹。我们可以利用这点从中获利。', '你带来了什么东西呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10624, '阴森的历史', '你感受到阵阵的寒意了吗？就像冰凉的手掌落在肩上？$r，这并不是你的错觉。这儿确实有鬼魂出没，不散的怨灵永世在这片土地上徘徊着。$B$B你确定想看看他们的模样吗？这很可能会影响你的一生——而且是不良的影响。$B$B那么好吧，我要你转至影月谷西部的熔岩池收集一些永燃灰烬。绿色熔岩池附近到处都是这种东西……', '将15份永燃灰烬样本交给影月谷影月村的主药剂师希尔达迦。', '你的世界即将改变，$N。$B$B<希尔达嘉开始用灰烬制造某样东西。>', '你的意思是?很明显的-我要把这些灰烬制成某种东西。', '', '去影月谷找影月村的主药剂师希尔达迦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10625, '幽灵眼镜', '我把这东西称为“幽灵眼镜”。很棒的名字，不是吗？戴上这副护目镜，你就能看见影月谷中的鬼魂。$B$B在把幽灵眼镜交给你之前，你得答应我一件事：帮我们清除影月村的鬼魂。$B$B来吧，戴上护目镜，杀掉徘徊在村落中的鬼魂。希望这能起到杀一儆百的效果，迫使剩馀的鬼魂离开影月村。', '影月谷影月村的主药剂师希尔达迦要你去杀死12个影月狂徒。', '血魔?泰…… 泰朗.血魔?这……这怎么可能呢?$B$B血魔怎么可能会在这里呢?这是不可能的!$B$B传说中的泰朗.血魔当初可是造成连遗忘者都会因恐惧而发抖呢。总而言之，血魔曾经是古尔丹的一个术士-他自身就拥有非常强大的力量。当血魔被奥格林.末日锤给杀了之后，古尔丹把这个阵亡的术士灵魂拿去植入一个被杀死的暴风城已故骑士受损的躯体之中。部落的第一个死亡骑士于是就这么诞生了。', '假如你遗失了你的护目镜，让我知道我会制造一副新的给你。', '', '去影月谷找影月村的主药剂师希尔达迦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10626, '夺取武器', '如果你能提供更多的此类材料，我就能为你铸造一柄适合的武器。$B$B军团要塞的两位深渊领主玛卡扎顿和莫戈洛隆就随身带着这种特殊的抗魔武器。如果能取回这两柄武器重新熔铸，应该就有足够的材料了，或许还有许多剩下来的呢。$B$B<奥丁咧嘴一笑。>$B$B用燃烧军团的“秘密武器”来对付他们应该相当有趣，不是吗？', '将玛卡扎顿之刃和莫戈洛隆之刃交给蛮锤要塞的奥丁·雷拳。', '这些就够了。现在，让我们把它们打造成更有用的形态吧。', '你找到那些原始样本了吗?', '', '去影月谷找蛮锤要塞的奥丁·雷拳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10627, '夺取武器', '如果你能提供更多的此类材料，我就能为你铸造一柄适合的武器。$B$B军团要塞的两位深渊领主玛卡扎顿和莫戈洛隆就随身带着这种特殊的抗魔武器。如果能取回这两柄武器重新熔铸，应该就有足够的材料了，或许还会有许多剩下来呢。$B$B真是迫不及待地想让那些家伙尝尝抗魔武器的厉害了。', '将玛卡扎顿之刃和莫戈洛隆之刃交给影月村的格罗克姆·死眼。', '这些就够了。现在，让我们把它们打造成更有用的形态吧。', '你找到那些原始样本了吗?', '', '去影月谷找影月村的格罗克姆·死眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10629, '肮脏的工作', '伐木机总算是修好了，可我好像又把钥匙弄丢了。我养了一群地狱警卫犬来保护营地，不过这帮废物除了喜欢咬我之外什么事儿都办不成。它们还特别喜欢亮晶晶的东西。我猜伐木机钥匙大约是被其中一只警卫犬给吃了。如果你愿意带它出去散散步的话，我就付给你一大笔钱。散步的时候杀些地狱野猪来喂它，饱餐之后它肯定得按自然规律办事。然后，你就在它排出的“残渣”里找找看有没有钥匙吧。', '使用地狱犬哨召唤一只恶魔警卫犬。带恶魔警卫犬外出散步，并猎杀疯狂的地狱野猪来喂养它。在恶魔警卫犬排出的“残渣”中寻找伐木机钥匙。然后返回萨尔玛西北方的矿洞，将伐木机钥匙交给工头拉泽克拉兹。', '你身上的味道真臭。但是你找到我的钥匙了!非常的感谢你。现在我的伐木机可以开始帮我赚钱了。不用多久我就可以赚到足够的钱离开外域了。我不知道你为什么想待在这里，我痛恨这个地方。你难道不想回藏宝海湾吗?$B$B也许可以钓钓鱼?', '你找到我的钥匙了吗?我确定我养的其中一只恶魔犬吃了它。可能是我派去给你的那一只。大概是吧。', '', '去地狱火半岛找萨尔玛矿洞的工头拉泽克拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10630, '萨尔玛的地下', '我本来马上就可以开始干活了。可……现在问题是我的矿里怎么会有这么多的甘尔葛。我没法派苦工进去，而且，虽然机器人修好了，可我也不想在战斗中把它弄坏。矿洞的深处肯定有一个甘尔葛的头目在坐镇指挥。要是你去把它干掉，或许这帮甘尔葛就会被吓跑，然后我就可以开始挣钱买票回家了。', '杀死乌加兹，然后返回萨尔玛西北方的矿洞，向工头拉泽克拉兹复命。', '全部的甘纳格已经要离开了。我会再一个礼拜之内回到藏宝海湾。我等不及想再次钓鱼了。来到外域是一个错误的决定。假如你肯接受我的建议的话，就顺原路回去。花点时间待在荆棘谷，或者假如你有冒险的精神，也可以去安戈洛环形山。反正不要待在这里就对了。', '他已经死了吗?我不敢看。', '', '去地狱火半岛找萨尔玛矿洞的工头拉泽克拉兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10632, '锋利的牙齿', '你能帮助托什雷和他的科学家朋友们，这可真是太好了。然而，我却没有那个奢侈的条件去纵容我的“个人兴趣爱好”。$B$B如果你真想改善这里的状况，就得按我说的去做。现在，我需要武器。$B$B我们的枪在远距离的时候效果很不错，但如果被那些虫子接近的话，就需要强力的近战武器了。$B$B栖息在北边剃刀山一带的刃喉鞭尾龙有着锋利的牙齿，非常适合做成武器的刃部。给我带一些回来。', '收集5颗非常锐利的刃喉龙牙。', '做的好，小朋友。只要有一个士兵因为你的努力而救回一命的话，你所受的苦都是值得的。$B$B我想你付出的汗水与泪水应该被奖励。既然我们不久之后就会有一批新的武器，你就先从我这拿走一把吧?', '你的牙齿收集的如何呢?$B$B我确定你可以为我们顺利的取得它们。在你完成之前，我们会一直驻守在哨站这边。', '', '去刀锋山找托什雷的基地的拉沙克·铁墙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10634, '占卜：血魔的护甲', '血魔活着的时候就是个不折不扣的混蛋，死了之后依然恶性不改，祸害世间。$B$B东南方的灵翼浮岛本是影月谷大陆的一部分，如今已变成一座残破的浮岛。$B$B这个地方曾经是死亡之翼的后嗣厄库尔的家园，但现在这里只是他的埋骨之地。厄库尔还在浮岛上空盘旋着，被血魔击败的耻辱令他狂怒不已。$B$B想要取回血魔的护甲，就得打败厄库尔。', '将血魔的护甲交给影月谷东南方暗影祭坛的上古影月之魂。', '我必须拥有全部三样的物品才能占卜到血魔的去向。', '飞到虚空之翼岩架取回物品。', '', '去影月谷找暗影祭坛的上古影月之魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10635, '占卜：血魔的披风', '血魔这家伙可谓是罪行累累，其中最残忍一次的要数卡拉波的牧师大屠杀事件。$B$B当年，古尔丹率领大军击败了驻守在卡拉波神殿的德莱尼人，幸存的卡拉波祭司们沦为战俘，兽人们便将这些牧师统统关押在地狱火堡垒中。$B$B那时，血魔还未堕落成死亡骑士，这个冷血的畜生竟然杀光了那些毫无反抗能力的战俘。如今，卡拉波祭司们的怨灵依然在黑暗神殿前游荡着，他们心中复仇的怒火愈燃愈烈。$B$B血魔的披风就在那些卡拉波的牧师手中。', '将血魔的披风交给影月谷东南方暗影祭坛的上古影月之魂。', '当我拥有全部三样的物品才能占卜到血魔的去向。', '你必须使用显灵镜才能看见影月谷的灵魂。', '', '去影月谷找暗影祭坛的上古影月之魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10636, '占卜：血魔的权杖', '他们一个接一个地跪下来，愿以自身性命为誓效忠血魔。血魔手起刀落，砍下了他们的首级。大屠杀之后，这个残忍的刽子手便自杀了。$B$B他可不是诚心悔罪！绝不是，这家伙是在追求永生！卡拉波幽灵骑士在死亡骑士的尸体上复苏。$B$B他们绕着古尔丹之手行进，等待着主人的归来。血魔的权杖就在他们手中。把它取回来……', '将血魔的权杖交给影月谷东南方暗影祭坛的上古影月之魂。', '只有三样东西都到齐我才能帮你解开你迫切想寻找的答案!', '你必须使用显灵镜才能看见影月谷的灵魂。', '', '去影月谷找暗影祭坛的上古影月之魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10637, '必要的混乱', '这些武器足以证明我们的担忧不是没有道理。伊利丹确实在卡拉波废墟训练恶魔猎手，我们必须阻止他进一步扩大势力。$B$B$N，别被恶魔猎手这名字给迷惑了，总有一天这帮家伙会像对付恶魔那样来对付我们的。$B$B当前，还有一批日怒术士在卡拉波废墟召唤并奴役恶魔，用于新兵训练。他们曾召唤出一个名叫阿萨洛斯的深渊领主，不过阿萨洛斯过于强大，并不适合新兵的训练课程，术士们只得不断地放逐他。设法令阿萨洛斯摆脱放逐，这场混乱必定能为我们赢得了解敌情的时间。', '大主教欧纳拉要你返回卡拉波废墟，设法令阿萨洛斯摆脱放逐状态。$B$B为奥尔多完成任务将会降低你在占星者阵营中的声望等级。', '希望你制造的混乱可以帮我们争取到足够的时间，让我们对卡拉伯尔废墟训练场有充份的了解。', '你已经完成我的要求了吗?', '', '去影月谷找沙塔尔祭坛的大主教欧纳拉。', '释放阿萨洛斯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10641, '对抗军团', '燃烧军团可以令凡人的灵魂堕落腐化，这已是不争的事实，所以我并不信任你。想要从我口中得知恶魔训练场的详情，就必须证明你并非是燃烧军团的间谍。$B$B我正在追踪一个名叫萨莎尔的女恶魔，可惜她是以虚体形态存在的，因此总能逃脱我的侦测。$B$B萨莎尔负责管理铸魔基地：炼狱的天罚祭司，这些天罚祭司是她的心腹和爪牙，只听从她的命令。杀掉她的天罚祭司，将那祭司体内的魔血泼在地上。这必定会激得萨莎尔暂时显露真身，趁此机会杀死她。', '受难者奥图里斯要你转至虚空风暴的铸魔基地：炼狱，从天罚祭司身上取回一份新鲜的魔血。然后，将新鲜的魔血泼在地上，并杀死萨莎尔的化身。完成任务之后向奥图里斯复命。', '你已经证明你并没有跟燃烧军团接触而腐化而我的敌人的敌人则是我的朋友。', '你杀死那个恶魔了吗?', '', '去找纳格兰的受难者奥图里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10642, '要塞中的幽灵', '这些笨蛋矮人根本不知道他们把蛮锤要塞建在了什么地方。这儿曾是影月谷兽人的埋骨地。是的，$r，就是兽人的鬼魂。$B$B近二十年来，他们一直静静地躺在蛮锤要塞地下，最近却不知何故躁动起来。$B$B离开蛮锤要塞，在影月谷中搜寻熔岩池或是熔岩流。那附近到处都是永燃灰烬，去收集一些这种灰烬，我或许能利用它制作一件有用的物品。', '将15份永燃灰烬样本交给影月谷蛮锤要塞的仲裁者索鲁斯。', '<索罗斯开始用灰烬样本制造某样东西。>$B$B做好了。你看，显灵镜!', '嗯，有一个灵跟在你后面……我可以感觉到。', '', '去影月谷找蛮锤要塞的仲裁者索鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10643, '影月先驱者', '要知道，索鲁斯是很有幽默感的。$B$B不过，闲聊到此为止吧。戴上幽灵眼镜，你就能看见徘徊在蛮锤要塞的兽人鬼魂了。别怕，其实我们才算是真正的入侵者。唉，可惜我们不得不痛下杀手，他们本应在平静中永远沉睡的。$B$B杀死滋扰蛮锤要塞的影月先驱者，然后向我复命。', '影月谷蛮锤要塞的仲裁者索鲁斯要你去杀死12个影月先驱者。', '你说你听见那些鬼魂跟你低声耳语?而他们提到了泰朗.血魔?$B$B<索罗斯颤抖着。>$B$B是的……我知道泰朗.血魔。更确切的说，我只知道他的过去。长久以来人们都认为他已经死了。这些鬼魂们是怎么说他的呢?', '假如你弄丢了你的护目镜，跟我说我就会帮你重造一副。', '', '去影月谷找蛮锤要塞的仲裁者索鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10645, '我就是塔隆·血魔……', '你取回了塔隆·血魔的所有对象，离谜底仅剩一步之遥：寄主。$B$B<上古影月之魂邪恶地咧嘴一笑。>$B$B你显然不相信我之前告诉你的故事。暗影祭坛便是我的牢狱。没有你的帮助，我大概会永世被禁锢在这座祭坛中。现在，我要寄宿在你体内。杀死上古看守者卡修斯，让我摆脱束缚。如果你拒绝的话，那咱俩就永远留在这儿好了。$B$B塔隆·血魔就要重获自由了！', '上古影月之魂利用了你！在你集齐所有的物品后，他便露出了真面目，原来这家伙就是塔隆·血魔。想要摆脱束缚，就必须按他的吩咐杀死上古看守者卡修斯。$B$B杀死卡修斯之后，向蛮锤要塞的仲裁者索鲁斯复命。', '你做了什么?愚蠢!$B$B你必须纠正你犯下的错。毕竟，这是你的责任。从这里挑一顶盔帽去吧。每一顶盔帽都灌注了你帮我取得的永燃灰烬。更重要的是，他们会赋予你看见影月谷鬼魂的能力，包含泰朗.血魔。$B$B当你找到泰朗.血魔的时候，杀死他。', '你说什么?', '', '去影月谷找蛮锤要塞的仲裁者索鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10647, '通缉：乌鲁洛斯，影月谷的祸患', '死亡通缉令：$B$B乌鲁洛斯，影月谷的祸患。$B$B奉奥巴洛恩大王之命，必须击杀邪恶的野兽乌鲁洛斯，并从它的尸首上取下烈焰之鬃做为凭证。如果你成功完成使命，请将乌鲁洛斯的烈焰之鬃交给战争召唤者萨尔东·图斯莱。$B$B乌鲁洛斯曾在影月村以东，位于影月谷中心的古尔丹之手附近出没。', '杀死乌鲁洛斯，将乌鲁洛斯的烈焰之鬃交给影月谷影月村的战争召唤者萨尔东·图斯莱。', '得来不易，嗯。做的好!你要领你的奖赏了吗。别担心!', '要来讨你的奖赏了吗，嗯?', '', '去影月谷找影月村的战争召唤者萨尔东·图斯莱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10648, '通缉：乌鲁洛斯，影月谷的祸患', '死亡通缉令：$B$B乌鲁洛斯，影月谷的祸患。$B$B奉大领主尤雷加尔之命，必须击杀邪恶的野兽乌鲁洛斯，并从它的尸首上取下烈焰之鬃做为凭证。如果你成功完成使命，请将乌鲁洛斯的烈焰之鬃交给战争召唤者萨尔东·图斯莱。$B$B乌鲁洛斯曾在蛮锤要塞东北方，位于影月谷中心的古尔丹之手附近出没。', '杀死乌鲁洛斯，将乌鲁洛斯的烈焰之鬃交给影月谷蛮锤要塞的战争召唤者比尔斯诺特。', '来，这是你的报酬。不要一次把它花光光。', '我希望你已经完成了我们的要求，$g小伙子:小姑娘;。不然就滚到一边去!', '', '去影月谷找蛮锤要塞的战争召唤者比尔斯诺特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10649, '恶魔名册', '我理解你想要消灭瓦雷迪斯及其追随者的心愿，但时机尚未成熟，现在的你恐怕难以与他抗衡。除非，你能找到那件赐予他力量的神器。$B$B据说，恶魔名册在奥金顿暗影迷宫的煽动者布莱卡特手中，它是你击败瓦雷迪斯的唯一希望。', '进入奥金顿的暗影迷宫，从煽动者布莱卡特手中夺得恶魔名册。完成任务后返回纳格兰向奥图里斯复命。', '我从好远的距离外就感觉到这本书的力量了。我想将它据为己有的想法……实在是非常的强烈。', '你已经把书拿回来了吗，$N?', '', '去纳格兰找铸魔营地：仇恨的受难者奥图里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10651, '阻止瓦雷迪斯', '我们必须摧毁这个邪恶的神器，但在那之前，可以先利用它来削弱瓦雷迪斯的力量。$B$B要彻底毁掉卡拉波废墟的训练场，就必须杀掉瓦雷迪斯，以及他手下的恶魔猎手阿兰蒂恩、瑟拉斯和奈萨里尔。$B$B召集你的朋友，一起返回卡拉波废墟。根据奥图里斯的指示击败瓦雷迪斯。希望这办法能起作用。', '大主教欧纳拉要你转至卡拉波废墟，杀死阿兰蒂恩、瑟拉斯、奈萨里尔和瓦雷迪斯。在瓦雷迪斯变身为恶魔形态时利用恶魔名册削弱他的力量。完成任务后将恶魔名册交给大主教欧纳拉。$B$B为奥尔多完成任务将会降低你在占星者阵营中的声望等级。', '做的好，$N!击败瓦瑞迪斯将会对我们跟伊利丹的战争带来巨大的影响。$B$B不管是对奥多尔还是整个外域你已经证明了你的实力。', '你已经完成我的要求了吗，$N?', '', '去影月谷找沙塔尔祭坛的大主教欧纳拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10653, '萨格拉斯印记', '现在，我想你已经非常清楚为什么我们要和燃烧军团和他们的追随者对抗了。$B$B如果你想在奥尔多阵营中证明自己，那么就给我带来一些只有高阶燃烧军团成员和高阶暗影议会成员才能拥有的徽记。最高级别的燃烧军\r\n团成员一般都在虚空风暴和影月谷一带活动。', '将10枚萨格拉斯印记交给沙塔斯城内的圣光护卫者阿德因。$B$B为奥尔多完成任务将会使你在占星者阵营中的声望等级降低。', '面对燃烧军团的恶魔还有崇拜他们的狂热信徒可不是件小事情，$N。你已经表现出极大的奉献还有勇气。继续下去，你对奥多尔的声望将持续上升。', '你有带敌人的徽记回来吗，$N?', '', '去沙塔斯城找奥尔多高地的圣光护卫者阿德因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10654, '更多萨格拉斯印记', '', '', '继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。', '你佩带了更多我们敌人的徽记了吗，$C?燃烧军团仍是一个威胁，我们将继续在任何我们找到他们的地方追捕他们。', '', '去找圣光护卫者阿德因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10655, '单枚萨格拉斯印记', '', '', '继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。', '我愿意收下你身上任何多的印记。别担心;你的行为将受到适当的表扬。', '', '去找圣光护卫者阿德因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10656, '日怒徽记', '正如你所知，占星者与凯尔萨斯的军队之间的冲突已经全面爆发。凯尔萨斯一直将我们视为他愚弄和统治所有血精灵的重大障碍与威胁，并时刻幻想着彻底消灭我们。$B$B如果你想要帮助我们与凯尔萨斯的军队作战，那么你有许多目标都可以攻击。凯尔手下最高阶的士兵都佩戴着日怒徽记以体现他们的阶级。你可以在虚空风暴和影月谷中找到并干掉他们。', '沙塔斯城的魔导师菲亚琳要求你给她带回10枚日怒徽记。$B$B为占星者完成任务将会使你在奥尔多阵营中的声望等级降低。', '凯尔萨斯的部队是一支训练精良的军队。你做的很好，$N。', '继续说，$N。', '', '去找泰罗卡森林的魔导师菲亚琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10657, '电闪雷鸣', '现在风动电容器使用起来的能源成本实在是太高了。但是，我突然想起来东边的鳞翼岩床附近的飞蛇可以喷吐出闪电，它的腺体应该可以为我们所用。$B$B我已经重新设定了这个电磁收集器的极性，令它可以吸收闪电。现在，你直接带着它去吸收那些飞蛇喷出的免费闪电吧。', '使用极化电磁球从鳞翼飞蛇身上吸收25发闪电打击，再收集5份鳞翼闪电腺体。', '太好了，成功了!老实跟你说我并不相信……根据我的计算你有百分之二十三点七二的机率在遭受第三下闪电打击的时候就会爆炸。$B$B<托斯利天真的笑着。>$B$B如此说来我们就可以知道球体是可以使用的，这样我们就可以达到ZC号的能量需求了。嗯，那也必须要有自愿出去被电的人才行。$B$B不管怎么说，你为了我们而当第一个试验品所以我们应该给予你奖赏!', '使用再极化的磁力发电机球体的秘诀就是知道何时该关掉它不然你会被烤焦。$B$B当然，你需要在开关之间衡量你要对付多少只飞蛇。$B$B讲到这，你有没有帮球体充电了呢?', '', '去刀锋山找托什雷的基地的托什雷。', '吸收闪电打击', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10658, '更多日怒徽记', '', '', '太棒了!这样就可以让凯尔萨斯知道不要低估我们的力量。', '你最近为我们做了什么，$N?对凯尔萨斯的战争是不会自己开始的，你知道吗?', '', '去找泰罗卡森林的魔导师菲亚琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10659, '单枚日怒徽记', '', '', '占星者胜利!凯尔的力量很快就会粉碎。', '即使是最小的贡献也会被注意到，$N。我们的敌人很多，但是我们将战胜他们!', '', '去找泰罗卡森林的魔导师菲亚琳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10660, '奇怪的生物……', '我对生活在影月谷熔岩流附近的爬行动物很感兴趣，这些奇怪的生物竟然能承受液态的岩浆所产生的高温，真是闻所未闻！$B$B你可以在影月村外发现许多魔火双帆龙，它们聚集在岩浆喷涌之处。杀死这些魔火双帆龙，将它们身上的魔火脾脏带回来。这样，我就能开始研究它们如何抵御高温了。$B$B从村子东南方开始搜寻吧。', '影月谷影月村的研究员提欧鲁斯要求你给他带回8个魔火脾脏。', '<研究员提欧鲁斯拿走了脾脏并且开始检查。>$B$B这可能要花点时间。这些钱是你辛苦工作的报酬。', '脾脏!给我脾脏!', '', '去影月谷找影月村的研究员提欧鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10661, '美味的脾脏！', '你听说过食物会自己变熟并一直保持刚出锅的新鲜吗？嘿，你要敢于想象才行！$B$B不过，这可真不是什么白日梦！在蛮锤要塞外面，你可以找到许多魔火双帆龙，它们无视灼热的高温，聚集在熔岩池或是熔岩流附近。$B$B矮人们告诉我，魔火双帆龙的脾脏堪称美味中的极品，而且这东西在它们身上就已经煮熟了！给我搞些魔火脾脏来，这些金币就归你。$B$B从要塞正东方开始搜寻吧。', '影月谷蛮锤要塞的诺姆斯要求你给他带回8个魔火脾脏。', '<饥饿的葛诺玛斯一把抓走了那些脾脏。>$B$B这是我答应要给你的钱。假如我需要更多的脾脏的话我会告诉你的。$B$B真好吃……我想说他们真是“好吃透了”!', '脾脏!给我脾脏!', '', '去影月谷找蛮锤要塞的诺姆斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10662, '隐居的铁匠', '<奥丁试图将这些金属块锻造成武器，但是失败了。他遗憾地摇了摇头。>$B$B这些铁锭并非不能用于锻造武器，只是我的能力有限罢了。$B$B我知道有位技艺精湛的铁匠名叫戴维·韦恩，他是跟随着洛萨之子来到德拉诺的。现在，这位着名的铁匠已经离开了远征军，隐居在泰罗卡森林地区的火翼岗哨东北方的某个半岛上。带上铁锭去找他吧，或许他能有办法为你锻造武器。', '将一箱铁锭交给泰罗卡森林内韦恩的避难所的戴维·韦恩。', '欧尔汀派你带着这些东西来找我?$B$B<这个铁匠检视了这些金属块。>$B$B他是对的。大部份内含的魔力已经完成，但是我仍然可以感觉到它未完成的部份。给我一些“奇特”的材料还有一些加工的时间，我可以用这个金属锭帮你打造出一把强而有力的抗恶魔剑。', '你来这里做什么，$C?我没有太多的访客。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10663, '隐居的铁匠', '<你面前的这位兽人摇了摇头，他明显是失败了。>$B$B这些铁锭并非不能用于锻造武器，只是我的能力有限而已。$B$B虽然这么说挺伤自尊的，可你唯一的希望是一位名叫戴维·韦恩的人类铁匠。他曾是联盟远征军的一员，不过那已经是猴年马月的事了。这位铁匠现在早已离开洛萨之子，隐居在泰罗卡森林地区的火翼岗哨东北方的某个半岛上。带上这些铁锭去找他吧，或许他能有办法为你锻造武器。', '将一箱铁锭交给泰罗卡森林内韦恩的避难所的戴维·韦恩。', '欧尔汀派你带着这些东西来找我?$B$B<这个铁匠检视了这些金属块。>$B$B他是对的。大部份内含的魔力已经完成，但是我仍然可以感觉到它未完成的部份。给我一些“奇特”的材料还有一些加工的时间，我可以用这个金属锭帮你打造出一把强而有力的抗恶魔剑。', '你来这里做什么，$C?我没有太多的访客。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10664, '其它的材料', '你带来的铁锭是铸造剑刃的主要原料，但是我还需要别的材料来制作武器的其它部分。$B$B让我看看，我还需要一个精金框架、一些重结缔皮和一个恶魔防护结界图腾。熟练的工匠能制作出前两样东西，第三样就需要转至沙塔斯城的贫民窟向施法材料商芬提购买了。他跟其它商人一起在那块区域做生意。', '将一个精金框架、4张重结缔皮和一个恶魔防护结界图腾交给韦恩的避难所的戴维·韦恩。', '<那位铁匠收下了材料，对你表示认同的点了点头。>$B$B这些就够了。剩下来我需要的材料可不容易弄到手。', '你已经收集完材料了吗?', '', '去泰罗卡森林找韦恩的避难所的戴维·韦恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10665, '能源舰的热源', '要熔炼你带来的铁锭需要极高的温度，普通的熔炉无法提供这样的温度。$B$B我需要一种特殊的热源，外域中能制造出如此高温的东西屈指可数。$B$B风暴要塞的能源舰里就能生产这种蕴涵着不可思议的能量的魔法晶格。这些超载的魔法晶格就分布在机械领主卡帕西图斯周围，去取一块吧。', '将超载的魔法晶格交给韦恩的避难所的戴维·韦恩。', '它的性能比我想象的还要好!有了这么大的能量，我可以做出一打的剑了!', '你可以从能源舰区走私一个法力容器给我吗?', '', '去泰罗卡森林找韦恩的避难所的戴维·韦恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10666, '魔语辞典', '只有用恶魔语吟唱法术才能重新为剑刃附魔。$B$B虽然我做学徒的时候完全没有学过什么恶魔语，可眼下没别的路可走了。暗影议会的某个术士手中有一本魔语辞典，其中记载了附魔所需的大部分恶魔语词汇。$B$B沃匹尔大师是此书的主人，这个难以对付的家伙就躲在奥金顿暗影迷宫的大厅深处。去吧，无论如何也要把魔语辞典完好无损地给抢回来。', '从沃匹尔大师手中夺得魔语辞典，将它交给韦恩的避难所的戴维·韦恩。', '<大卫一边匆匆的翻阅着那本书，一边颤抖着。>$B$B这可不是一个可以开玩笑的东西，$N。在武器制造完成的时候，我会毁掉它。即使这些文字不公诸于世，世界上的恶魔力量也已经太多了。', '你已经得到那本书了吗?', '', '去泰罗卡森林找韦恩的避难所的戴维·韦恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10667, '地下的土壤', '你先前带来的精金框架未经强化是不能承受金属熔化后产生的热量的。我们可以往精金框架中填入某种稀有土壤，强化其冷却性能。$B$B这种名为水下洞穴沃土的土壤被纳迦视为珍品，极少数纳迦才有资格拥有它；而据我所知，在外域，只有盘踞在盘牙水库内蒸汽地窟的水术师瑟丝比娅使用这种土壤。', '从水术师瑟丝比娅手中夺得水下洞穴的沃土，将它交给韦恩的避难所的戴维·韦恩。', '这样应该就可以成功了。我本来希望可以多拿一点，但是老实说，我们在这里能获得任何东西都算是幸运了。', '你已经得到幽界土壤了吗?', '', '去泰罗卡森林找韦恩的避难所的戴维·韦恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10668, '对抗伊利丹', '我对伊利丹仍然心存敬意。若不是他，我也不会走上恶魔猎手之路。$B$B可惜，他已经不再是过去的他了。对力量的渴求让他出卖了灵魂，而数次失败又令他扭曲了心智。他已经成为了我发誓要彻底铲除的那种存在。伊利丹和他的仆从——那些被称为伊利达雷的家伙，现在跟燃烧军团的恶魔爪牙已经没什么区别。$B$B虽然伊利丹在外域的统治权已经越来越弱，但是他的势力依然不容小觑。转至影月谷的伊利达雷岗哨，杀死伊利丹手下的军官洛瑟鲁斯，以此证明你的立场。', '受难者奥图里斯要你转至影月谷的伊利达雷岗哨杀死洛瑟鲁斯。', '所以你不是跟伊利丹一伙。你还差一步就可以得到我完全的信任。', '伊利达瑞副官死了吗?', '', '去找纳格兰的受难者奥图里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10669, '扫除馀孽', '这世上也有少数恶魔依旧我行我素，不会起誓效忠他人。但是，真正的恶魔猎手绝不会因此生恻隐之心。$B$B恶魔克瑟勒斯曾被生活在赞加沼泽的原始沼泽生物奉为神灵，他一直拒绝加入燃烧军团。德拉诺世界险些被摧毁时，他躲到沼光湖底，陷入了沉睡。转至沼光湖附近的荒弃传送门，将这根银色魔枪插入地面。$B$B这样一来，克瑟勒斯必定会苏醒。杀掉他，以此证明你也不是恶魔一伙的。', '受难者奥图里斯要你转至赞加沼泽，在沼光湖附近的荒弃传送门使用银色魔枪以唤醒克瑟勒斯。杀死这个恶魔之后，向奥图里斯复命。', '做的好，$N。他还记得我把这长矛刺进他身体的那一天吗?那已经是好久以前的事了……', '你回来啦。希乐斯已经被你杀死了吗?', '', '去找纳格兰的受难者奥图里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10670, '大地之母的眼泪', '剑刃的附魔还需要将一些强大的能源体熔化入其中，例如宝石。有一颗宝石可以为我们所用，要知道，这世上能容纳如此强大的魔法能量而不碎裂的宝石可不多见。$B$B这颗名为“大地之母的眼泪”的宝石是食人魔制造的，当前在战争使者沃姆罗格手中。这家伙盘踞在地狱火堡垒内的破碎大厅内，有很多强大的手下帮衬，不好对付。$N，取回大地之母的眼泪，一路小心。', '从战争使者沃姆罗格手中夺得大地之母的眼泪，将它交给韦恩的避难所的戴维·韦恩。', '<大卫.伟恩将这个宝石举高，透过阳光欣赏着它。>$B$B这个宝石真是毫无瑕疵呀，而且这正是我们所需要的。一个有瑕疵的宝石将会危害将来挥舞这把剑的人，造成剑中的附魔效果反扑其主人。', '你能从欧姆拉格的手中抢回宝石吗?', '', '去泰罗卡森林找韦恩的避难所的戴维·韦恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10671, '不仅仅是一磅肉', '$N，我这里还有点别的事情想拜托你。我们这有个大脑袋的侏儒想研究一下剃刀山北方拉扎安码头一带的魔化野兽。$B$B更具体地说，他们想要直接研究那些血肉兽的肌肉。$B$B<迪娜厌恶地皱了皱眉。>$B$B但是，首先，显然他们不想弄脏自己的双手；其次，他们只想要充入了以太能量的肉。但这似乎并不是所有的血肉兽身上都会有。$B$B我得说，我们算是人穷志就短，没选择了，只能干，你呢？', '收集5份以太能量肉块。', '这些就足够了。不过，它们还真臭对吗?$B$B我希望你所做的努力是值得的……我只是很高兴去收集的人是你而不是我!', '你已经取得我要的一磅肉了吗?什么，你不觉得那样讲很好笑吗?', '', '去刀锋山托什雷的基地里找晕乎乎的迪娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10672, '没理由啊……', '我们必须深入研究这些生物。$B$B此地以东便是巴尔里废墟。在那里，巨大的熔岩流从地表喷涌而出，而你可以在熔岩附近找到魔蝎控制器。这些控制器是一个名叫诺姆斯的天才制造的，可以用于操纵机械蝎探测熔岩。$B$B可惜的是，这家伙早已迷失心窍，现在他只对以辛辣着称的侏儒食品感兴趣。$B$B<提欧鲁斯露出滑稽的表情。>$B$B我要你使用控制器标记熔岩流中的大型魔火双帆龙，以便展开下一步的研究工作。', '影月谷影月村的研究员提欧鲁斯要求你转至巴尔里废墟附近的熔岩流，使用魔蝎控制器控制一只魔蝎，并用它标记8只大型魔火双帆龙。', '听好，我们没有时间可以浪费了。我一直在注意那些上了标示的双帆龙然后发现它们全部都会向一只巨大的，不，应该说超巨大的双帆龙伟大的魔脊回报。', '注意听好，我没有时间也不想解释这么做的意义何在。你只要标好这些双帆龙就够了。', '', '去影月谷找影月村的研究员提欧鲁斯。', '标记大型魔火双帆龙', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10673, '魔脊龙', '诺姆斯知道那条巨型魔火双帆龙的存在，并且打算把它吃了！我可以通过魔蝎发现魔脊龙，他必定也早已知晓了。没时间多解释了。诺姆斯这个疯子，魔脊龙的皮是上好的防火服，可不能让他给吃了。$B$B返回巴尔里废墟附近的熔岩流，搜寻魔脊龙。一旦你找到这头巨兽，立即杀掉它，然后将魔脊龙之皮带回来给我。$B$B$N，别跟我争辩。我早就不屑于此了。', '杀死魔脊龙，将魔脊龙之皮交给影月谷影月村的研究员提欧鲁斯。', '终于!对抗熔岩高温的完全防护是我的了!当然你也会分到这项工艺技术的好处，$N。这是你应得的!', '动作快一点!那个地精的胃口没有上限的!', '', '去影月谷找影月村的研究员提欧鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10674, '捕捉光球', '拉扎安虚灵正在北边的拉扎安码头研究着某些非常有趣的科技。$B$B我想，要是你去拿这个陷阱把他们的那些飘在空中的粉红色小光球偷几个过来的话，他们应该是不会介意的吧？反正看起来好像也就是他们用来装饰房子的东西。$B$B这个陷阱具备特殊的功能设计，只要打开，就可以直接把那种光球给吸引过来。当然，那些光球也可能会向拉扎安虚灵报警，暴露你的位置。', '用多光谱光能陷阱捕获15颗拉扎安光球。', '喂!等一下!!$B$B情况看起来不太妙……', '我想既然我们已经在谈话了，那表示你已经找到雷森平台的光球?能够看看它们的构造一定很有趣，让我看看那些以太族在做些什么。', '', '去刀锋山找托什雷的基地的托什雷。', '捕捉拉扎安光球', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10675, '侏儒之怒！', '<托什雷擦去了脸上的血。>$B$B这些光球竟然是由虚空能量和灵魂混合组成的，甚至其中还包含着侏儒的灵魂！$B$B他们竟敢……难道那些我们派去探索北方的人就是被他们杀死的吗？！$B$B$N，你必须阻止这一切。不过，恐怕唯一的阻止方式就只有杀死他们的头目——节点亲王拉扎安了。$B$B我想，你必须首先干掉大票的拉扎安虚灵，把他引出藏身之地。$B$B把他身上收集到所有灵魂都给我带回来。', '取得灵魂之盒。', '你能解决他真是太好了!谢谢你终止了他们玩弄魔法还有科技的可怕行径。$B$B谨代表世界各地的地精英雄们，我现在将赠与你我们最高的荣誉…一些能量转换器以及从以下的奖品中任选其一。$B$B我知道你会好好使用它们的!', '你已经解决那个偷取灵魂的混蛋，雷森了吗?', '', '去刀锋山找托什雷的基地的托什雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10677, '第二道菜……', '我曾在古尔丹之手以东、巴尔里废墟周围的熔岩流附近见过大型魔火双帆龙。我要你从它们身上取回一个巨大的魔火胃囊。这东西不太好切下来，运气不好的话，你可能要多杀几只才能弄到合适的。加油！下一顿美餐就靠你了。', '影月谷蛮锤要塞的诺姆斯要求你给他带回一个巨大的魔火胃囊。', '你做的很好但是我刚刚收到了一个不可思议的消息!', '今日特餐:胃囊大餐。', '', '去影月谷找蛮锤要塞的诺姆斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10678, '主菜！', '长话短说，我曾与一位名叫提欧鲁斯的血精灵共事过一段时间。但自从我醉心美食之后，他便与我分道扬镳了。这家伙非常自以为是，现在居然还在继续用我发明的设备进行研究。他前几天指派某个蠢货利用我的魔蝎勘测了巴尔里废墟的熔岩流，结果发现了所有双帆龙的头目！$B$B我要你赶在他之前去杀掉那条名叫魔脊龙的双帆龙王，将魔脊龙之皮带回来给我。$B$B快去！', '将魔脊龙之皮交给影月谷蛮锤要塞的诺姆斯。', '我想要一个人独处一下，$N。感谢你的帮忙!', '今日特餐:魔脊的毛皮大餐。', '', '去影月谷找蛮锤要塞的诺姆斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10679, '淬火', '武器就快锻造成功了！$B$B你几乎能感受到钢刃中的魔法力量在慢慢凝聚，只差最后一步了。$B$B转至影月谷内古尔丹之手顶部的滚烫熔池，将铸成的伊利达雷斩除之刃放入熔岩池中淬火，然后再将淬火的伊利达雷斩除之刃带回来给我。', '转至古尔丹之手顶部寻找滚烫熔池，将铸成的伊利达雷斩除之刃放入熔岩池中淬火。然后将淬火的伊利达雷斩除之刃交给韦恩的避难所的戴维·韦恩。', '做的好!$B$B<这名铁匠很靠近的检查这把剑。>$B$B跟你一开始的粗糙军团武器比起来现在已经有了大幅度的增强了。这把剑不光是可以拿来砍伊利丹的恶魔们，还可以拿来对付燃烧军团的手下。', '你将这把刀放进古尔丹火山的熔岩池里冷却过了吗?', '', '去泰罗卡森林找韦恩的避难所的戴维·韦恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10682, '该谈判了……', '当我们刚刚抵达卢安荒野时，拜龙教还仅仅在西边隧道另一侧的黑翼集会所周围活动。但现在，他们的势力范围越来越大，已经接近我们的周边了。$B$B我要求你立刻去找到拜龙教派往这里的监工，他应该就在卢安荒野里的几处营地之间来回巡逻。$B$B去与他谈判，转告他，只要他们不再胡乱屠杀野生动物，不再砍伐树木，我们之间就还有和平共处的空间与馀地。', '去与工头努埃尔谈判。', '什么?!他们马上就把你以及我们的提议否决?$B$B真是令人吃惊!我们带着善意去找他们，而他们把你赶走连试着听听协议都不肯?$B$B好吧，我们走着瞧!', '一切都还好吗?', '完成与工头努埃尔的谈判', '去刀锋山找常青林的护树者查恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10683, '巴尔里石板', '最近，一支名叫灰舌的破碎者氏族奉伊利丹之命，在巴尔里废墟展开了一系列挖掘工作。他们的目标毫无疑问就是当初那些被古尔丹所引发的火山爆发埋入地下的神圣古器。我们必须利用这个机会夺回巴尔里石板。据说，那上面记载着许多卡拉波神殿——也就是黑暗神殿的秘密。', '群星圣殿的奥术师塞里斯要你收集12块巴尔里石板。它们散落在巴尔里废墟中，那里的灰舌工人身上也携带着这种石板。$B$B为占星者阵营完成任务将降低你在奥尔多阵营中的声望等级。', '巴瑞碑文!没错，这也许会提供我们非常有用的资料。', '你找到那些碑文了没，$N?', '', '去影月谷找群星圣殿的奥术师塞里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10684, '长者奥洛努', '根据巴尔里石板的记载，巴尔里废墟中埋藏着一件名为卡拉波勋章的神器。在过去，德莱尼人当中只有最高阶的祭司团成员才有资格得到这件神器，从而也获得了自由进出卡拉波神殿的权利。$B$B我们现在必须查明灰舌破碎者们是否已从废墟中挖掘出了这枚勋章。这件神器一定可以对我们抵抗伊利丹有所帮助。$B$B现在，驻守在巴尔里废墟的灰舌军官——长者奥洛努每天都会接到他的上司阿卡玛的书面指令。去把阿卡玛的命令带来给我。', '群星圣殿的奥术师塞里斯要求你从巴尔里废墟的长者奥洛努手中夺得阿卡玛的命令。$B$B为占星者阵营完成任务将降低你在奥尔多阵营中的声望等级。', '阿卡玛的亲笔书信…… 看看我们能从中得到什么资讯吧。', '有任何消息了没，$N?我们快没有时间了。', '', '去影月谷找群星圣殿的奥术师塞里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10685, '灰舌腐蚀者', '阿卡玛在指令中提到，被挖掘出来的4块勋章碎片分别由四位灰舌腐蚀者负责保管。这些灰舌腐蚀者本都是氏族中的萨满祭司，如今却转而与他们曾经崇拜与侍奉的元素为敌，唉……$B$B气之腐蚀者哈鲁姆当前在灵翼小径；地之腐蚀者埃肯尼和火之腐蚀者乌拉鲁，曾有人看见他们在古尔丹之手附近的魔能熔池旁出没；水之腐蚀者拉坎恩据说在库斯卡岗哨附近。$B$B杀死他们，取回全部的勋章碎片。', '从哈鲁姆、埃肯尼、拉坎恩和乌拉鲁手中夺得他们的勋章碎片，并把这些碎片交给影月谷群星圣殿的奥术师塞里斯。$B$B为占星者阵营完成任务将降低你在奥尔多阵营中的声望等级。', '没错!这就是四个勋章碎片。现在，来将它们结合在一起……', '你已经取回四个勋章碎片了吗，$N?', '', '去影月谷找群星圣殿的奥术师塞里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10687, '卡拉波训练场', '据斥候回报，一支由日怒血精灵新兵组成的大部队当前正朝卡拉波废墟前进。原本，如此大规模的军事行动势必会构成强烈的军事威胁，但是我们相信此事另有内情。$B$B他们的服饰和战斗风格很像伊利丹麾下的部队。我可不想自乱阵脚。转至卡拉波废墟取回他们的武器，这样我们就能搞清楚状况了。', '群星圣殿的拉瑞萨·射日者要你转至群星圣殿东北方的卡拉波废墟，从恶魔猎手学员和恶魔猎手新兵身上夺取8柄日怒阔剑。$B$B为占星者完成任务将会降低你在奥尔多阵营中的声望等级。', '让我们仔细地看一下这些武器，$N。嗯……这令人感到相当的不安。', '你已经完成我要求的工作了吗，$N?', '', '去影月谷找群星圣殿的拉瑞萨·射日者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10688, '必要的混乱', '这些武器足以证明我们的担忧不是没有道理。伊利丹确实在卡拉波废墟训练恶魔猎手，我们必须阻止他进一步扩大势力。$B$B$N，别被恶魔猎手这名字给迷惑了，总有一天这帮家伙会像对付恶魔那样来对付我们的。$B$B当前，还有一批日怒术士在卡拉波废墟召唤并奴役恶魔，用于新兵训练。他们曾召唤出一个名叫阿萨洛斯的深渊领主，不过阿萨洛斯过于强大，并不适合新兵的训练课程，术士们只得不断地放逐他。设法令阿萨洛斯摆脱放逐，这场混乱必定能为我们赢得了解敌情的时间。', '拉瑞萨·射日者要你返回卡拉波废墟，设法令阿萨洛斯摆脱放逐状态。$B$B为占星者完成任务将会降低你在奥尔多阵营中的声望等级。', '那应该可以给我们一些时间……希望它足够让我们获得更多的情报。', '你已经完成我要求的工作了吗，$N?', '', '去影月谷找群星圣殿的拉瑞萨·射日者。', '释放阿萨洛斯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10690, '兽穴之母', '悬赏！$B$B雷玛，兽穴之母，雷神要塞正南方锯齿山地区的主要守卫者。$B$B向东出城，过桥后横穿血槌峡谷便可找到她。她就隐蔽在山岭南部边缘一处隧道的尽头。$B$B将她的死亡消息告知希尔瓦纳的指挥官萨卡斯·天影以换取报酬。', '杀死雷玛。', '难以相信。你独自一人杀死瑞玛了吗?$B$B以你的外表，我认为你能。你知道，我们正在寻找年轻、强壮的$C，像你那样，在这周遭帮忙，特别是我们与巨魔们持续有的那些问题。确定在那可能性上你会与我做后续联系。$B$B好的，你已经明确赢得我发布在那张通缉布告上的赏金。$B$B请，选择你想要的。', '今天我可以帮你什么呢?', '', '去刀锋山找希尔瓦纳的指挥官萨卡斯·天影。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10692, '阻止瓦雷迪斯', '我们当然必须摧毁这个邪恶的神器，但在那之前，可以先利用它来削弱瓦雷迪斯的力量。$B$B要彻底毁掉卡拉波废墟的训练场，就必须杀掉瓦雷迪斯，以及他手下的恶魔猎手阿兰蒂恩、瑟拉斯和奈萨里尔。$B$B召集你的朋友，一起返回卡拉波废墟。根据奥图里斯的指示击败瓦雷迪斯。希望这办法能起作用，否则……我只能说跟你合作愉快了。', '拉瑞萨·射日者要你转至卡拉波废墟，杀死阿兰蒂恩、瑟拉斯、奈萨里尔和瓦雷迪斯。在瓦雷迪斯变身为恶魔形态时利用恶魔名册削弱他的力量。完成任务后将恶魔名册交给拉瑞萨·射日者。$B$B为占星者完成任务将会降低你在奥尔多阵营中的声望等级。', '做得好，$N。在杀死瓦瑞迪斯时，你已结束了伊利丹最危险的计画之一。$B$B在这之后你的名字将确定会四处传播。$B$B请允许我取走恶魔之名宝典的遗稿。我保证它将被正确地……处理。', '你已经完成我要求的工作了吗，$N?', '', '去影月谷找群星圣殿的拉瑞萨·射日者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10701, '消灭灵岩巨人', '致所有关心虚空火箭X-52建设大计的朋友：$B$B本地的山岭巨人之王灵岩巨人一直是碎裂废土的安全隐患。他严重阻碍了浮岛南部建设作业的进展！$B$B召集你的朋友消灭他！然后返回52区到我这里领取奖赏。$B$B火箭主管弗斯拉格', '杀死灵岩巨人，然后向虚空风暴52区的火箭主管弗斯拉格复命。', '喔!喔……你解决了虚空石。真是好消息!$B$B随着那个讨人厌的山巨人消失，我们会更易于剥……发现，节约破碎荒地的资源。$B$B很高兴听到那些可怜，无辜的元素们不用再受到他的欺压。$B$B我要如何报答你呢?', '什么?什么?!动作要快一点……这里还有很多事要做。$B$B总有一天我要让这个东西飞上天，了解吗?', '', '去找虚空风暴52区的火箭主管弗斯拉格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10702, '步兵的工作……', '驻守影月村的兵力都被调去抵抗燃烧军团的入侵了。因此，日常的警备巡逻工作几乎完全没有人来做。$B$B负责物资供给的商队随时会受到影月谷野生动物的威胁，他们只要稍微偏离大道，就会撞见奇美拉、地狱野猪或是变异的大蝎子之类的怪兽。$B$B帮我们清理影月谷的野生动物！杀光它们！', '影月谷影月村的奥巴洛恩大王要你去杀死20只影月谷的野生动物。$B$B地狱野猪、邪翼奇美拉和灼壳蝎均属于影月谷的野生动物。无论种类，杀满20只即可。', '太棒了!要是我有其它蛮兵的工作需要完成，我会找你的。', '在我们商队往来荒野都很安全时回来找我。', '', '去影月谷找影月村的奥巴洛恩大王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10703, '穿好你的盔甲……', '有件琐碎的事要交给你做。不然你以为是什么？爬之前要学会走路，对吧？呃，说反了……$B$B驻守要塞的兵力都被调去抵抗燃烧军团的入侵了。因此，消灭影月谷的野生动物的重任自然要落到你肩上。$B$B带上你喜欢的武器，剑或是法杖什么的，杀掉那些讨厌的野兽。你得确保我们的商队能安全通行！', '影月谷蛮锤要塞的大领主尤雷加尔要你去杀死20只影月谷的野生动物。$B$B地狱野猪、邪翼奇美拉和灼壳蝎均属于影月谷的野生动物。无论种类，杀满20只即可。', '好，做得好!这有一些钱以奖励你的努力。如果我们需要把清除更多的垃圾的话，我会知道要找谁的。', '在我们商队往来荒野都很安全时回来找我。', '', '去影月谷找蛮锤要塞的大领主尤雷加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10704, '如何杀入禁魔监狱', '你找回的阿塔玛水晶中包含着一条信息。节点亲王哈拉迈德为我们进攻风暴要塞提供了至关重要的情报。$B$B他说只要将禁魔监狱钥匙的上半块和下半块组合起来，就能打开风暴要塞的禁魔监狱。$B$B其中一块钥匙碎片在生态船的迁跃扭木手中，另一块则由能源舰的计算者帕萨雷恩保管。$B$B取回这两块碎片，我会将它们组合成禁魔监狱钥匙。', '阿达尔要你取回禁魔监狱钥匙的上半块和下半块，他会将这两块碎片组合成禁魔监狱钥匙。', '我好感动，$N，虽然我不该对将阿塔莫带来给我们的$g英雄:女英雄;期望太低。$B$B将那两部分的裂片交给我，我会将他们合成为最终的样子。接着你就会拥有进入禁魔监狱的权限了。', '<阿达欧的声音优美的回荡过你的心中。>$B$B你回来了。你有带禁魔监狱钥匙的两个裂片来吗?', '', '去沙塔斯城找贫民窟的阿达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10707, '阿塔玛平台', '那些邪兽人奉伊利丹之命，在阿塔玛平台看守着那块名叫愤怒之心的阿塔玛水晶。他们利用黑暗魔法遮蔽了水晶散发的能量，避免被沙塔尔发现。$B$B现在，你立刻杀入黑暗神殿外的阿塔玛平台，当你抬头向上看的时候，你会发现暗影领主达斯维尔就在平台上徘徊。你必须杀死他和他手下的兽人术士才能夺得水晶。$B$B$N，这项任务可不轻松。祝你好运。', '转至影月谷的阿塔玛平台顶部，夺得愤怒之心。完成任务后向影月谷守望者牢笼的阿卡玛复命。', '就是这个水晶!它的力量……现在在我手中了!', '你回来了，$N。', '', '去影月谷找守望者牢笼的阿卡玛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10710, '试飞：晶歌山脉', '最近我一直在摆弄风动电容器，而且又有了个新的测试项目想要做一下！你想帮忙吗？$B$B这次的飞行距离很短，也会很快！$B$B啊……虽然……我保证这东西没危险……但这个，你看……你最好是签了这份免责声明。走个形式而已嘛，真的！$B$B祝你好运！要发射的话就去和拉雷谈谈吧，实验结束以后再回来找我！', '签署塔利的声明，然后与拉雷·萨普纳波谈一谈，并使用风动电容器。', '哇喔!你再一次的活下来了!原来我是个比我自己所想得还要更好的工程师呢!$B$B这是你的报酬!等等再跟我连系一下……我有更多的实验需要更多的实验对象!', '别担心，$N!担心永远让人哪里都到不了!', '进行飞行试验。', '去刀锋山找托什雷的基地的塔利·萨普纳波。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10711, '试飞：拉扎安码头', '$n，我刚刚提高了风动电容器百分之三十的功率，马上要开始一个与体重和风速有关的新实验了！要不要来试试我的新理论？这个实验会把你送到拉扎安码头附近。$B$B准备好发射以后，就与拉雷谈谈吧……', '与拉雷·萨普纳波谈一谈，并使用风动电容器。', '喔，糟了!你回来得太快了!我有看到你起飞像个火箭一样迅速升起!我相信至少要一个月的恢复期来修理这次飞行损坏的支架!你很强悍，勇敢，而且有勇无谋!不过主要是……你勇气十足!', '什么?你不想进行这个实验?别担心，$N!我一直在背后支持你!', '飞到高空的极限。', '去刀锋山找托什雷的基地的塔利·萨普纳波。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10712, '试飞：卢安荒野', '嘿，$N！总算找到你了，真高兴！我这里又有个非常重要的任务了！$B$B这是一个虚空风向标。我希望你在飞行中记录上面的读数，然后把资料送给我在卢安荒野的表弟。$B$B跟拉雷谈谈，用风动电容器飞去卢安荒野吧。飞的时候，记得旋转风向标！$B$B着陆以后，把这个风向标交给欧玛利·萨普纳波。$B$B祝你好运，$n。千万别迟到！', '与拉雷·萨普纳波谈一谈，并使用风动电容器。在飞往卢安荒野的过程中旋转虚空风向标，着陆后将旋转的虚空风向标交给常青林的欧玛利·萨普纳波。', '喔，你看过虚空天气风向仪的数据了?太棒了!这个机器所提供的资料 - 与我对德鲁伊的魔法测量相结合 - 将会结出许多的果实!$B$B喔，我向你保证，将会实用的惊人!', '你好啊!我的……我是说，我的亲戚塔利告诉过我你会顺道来拜访。你有什么东西要给我吗?', '发射到卢安荒野。', '去刀锋山找常青林的欧玛利·萨普纳波。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10713, '……谈判不成就动手！', '他们所做的事情无异于毁灭整个卢安荒野，我们绝不能袖手旁观。我们当前最重要的任务就是保护这里的树木。$B$B$C，我要求你立刻进入荒野之中，向他们送达我们的意图。我要求你杀死每一名你所见到的伐木工！$B$B他们既然不肯听从理性的劝告，那就让我们用这种更霸道的方式去说服他们吧！', '杀死10名拜龙教伐木工。', '感谢你，$N。$B$B虽然我们知道这些野生生物会很快的补足自己，树会重新生长，以一种特别自然的方式，是一种更加时间紧凑的过程。$B', '你有保护那些树木吗?那些砍伐者数量有变少吗?', '', '去刀锋山找常青林的护树者查恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10714, '斯比雷之翼', '血槌食人魔竟敢滋扰莫克纳萨氏族，就让我来替父亲排忧解难吧。食人魔是头脑简单的生物，他们从莫克纳萨氏族捞不到什么好处的。$B$B这件事背后一定另有阴谋。$N，让我的猎鹰斯比雷偷听血槌首领们的谈话，或许它能识破其中的隐情。', '寻找正在交谈的血槌工头和血槌占卜师，使用雷克萨的哨子召唤斯比雷偷听他们的谈话。', '<小灵伫立在雷克萨的肩上，雷克萨正专心听着。>$B$B所以是格鲁尔的儿子在食人魔们的背后策划行动的。他们命令血槌食人魔去破坏摩克纳萨尔以获得他们的支持。', '你知道了什么，$N?', '', '去刀锋山找雷神要塞的雷克萨。', '窃听血槌食人魔的计划', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10715, '进入沸土峡谷', '雷克萨要我为他配制毒药？我会满足他的要求，不过凡事都有代价，朋友之间也不例外。免费的东西只会破坏友谊。$B$B首先，你得去西南方的沸土峡谷跑一趟。$B$B那儿生活着外域乃至诸界中最毒的生物——硬壳穿地虫。我需要这种生物的毒囊做为毒药的原料。', '萨博迈恩男爵说，为雷克萨配制毒药需要7个硬壳穿地虫的毒囊。集齐毒囊后返回刀锋山的鲜血之环向他复命。', '非常好，以世人的角度来看，一份简单的工作完成了。现在，把腺体交给我，我就会进行最困难的部分。$B', 'NULL', '', '去刀锋山找鲜血之环的萨博迈恩男爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10717, '偷猎', '对不起，我失礼了，但我确实是在无意中听到了你与查恩的对话。我想，我或许能帮得上忙。$B$B我最近在研究黑翼集会所的状况，帮助德鲁伊们应付来自那边的威胁。$B$B我希望能从那边捉来几只雏龙以供研究，这样我们就能了解到他们到底是在崇拜与畏惧一个怎样的存在了。$B$B但首先，我们得弄到更多的网。我注意到在卢安荒野附近活动的拜龙教偷猎者身上似乎总是带着网。', '取得5张拜龙教之网。', '喔，那些网子看起来很棒。这些祭司一定对技术有很高的要求。$B$B这些网子被拿去误用实在太可惜了。$B$B现在我们有了这些网子了，你是不是愿意帮我这个老人一两件事呢?', '网子收集得如何?从我之前看到的来判断，那些侵入者使用的网子应该够坚固到足以应付接下来的任务。', '', '去刀锋山找常青林的萨米亚·因克林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10719, '你拿到记录了吗？', '你在这名拜龙教徒的身上发现了这张便笺，似乎是要送给工头努埃尔的，而署名则是库尔菲斯·暗鳞。$B$B或许护树者查恩会对这张便笺有兴趣。', '将会议记录交给刀锋山常青林的护树者查恩。', '有趣，但令人不安。我怀疑是否沙弥亚知道这个克菲斯.暗鳞是何方神圣?', '你手上的东西是什么?那本笔记上是不是血染?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10720, '最小的生物', '若是你贸然闯入血槌营地投毒，必定会引起食人魔的注意。这帮家伙虽说头脑简单，可毕竟不是傻子。我来教你如何利用自然界中那些体型小巧的生物完成投毒任务。$B$B你只要有节奏地敲击这面科多皮鼓，土拨鼠就会听你的号令行动。$B$B雷神要塞以北，沿着刃喉谷越过鲜血之环之后就是血槌营地，营地附近就有个土拨鼠洞。$B$B利用土拨鼠在血槌营地的酒桶中投毒。', '在土拨鼠洞附近敲击科多皮鼓。利用土拨鼠在血槌营地的3只酒桶中投毒。', '多年来我致力于研究与大自然沟通的方式。这不过是动物们能协助你之潜力里头的一小部分。', '完成了吗?', '', '去刀锋山找雷神要塞的雷克萨。', '在绿泡烈酒桶中投毒', '在月光陈酿酒桶中投毒', '在发酵种芽啤酒桶中投毒', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10721, '格鲁洛克和野猪', '$N，我有一只名叫霍弗的野猪宠物，就让它来陪格鲁尔之子格鲁洛克玩玩吧。$B$B格鲁洛克居住在雷神要塞附近的诅咒洞窟中。当你到达洞窟后，就用这只哨子召唤出霍弗。那个傻大个必定会跑来追逐野猪，你就借此机会偷来格鲁洛克的包裹，然后将它交给萨博迈恩男爵。$B$B出了雷神要塞往北走，诅咒洞窟就位于巨龙之末的东部边缘。', '取得格鲁洛克的包裹。', '<沙伯迈恩男爵凝视着戈隆的袋子里面并且好像很满足。>$B$B非常好，你已经履行约定了。作为代价，我会给雷克萨他在寻找的。', '这么快就回来了喔?你是来送雷克萨欠我的东西的吗?', '', '去刀锋山找鲜血之环的萨博迈恩男爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10722, '黑翼集会所', '我知道该怎么做了！$N，你必须立刻伪装成工头努埃尔的样子，并且去出席那个会议！$B$B那些在集会所的里拜龙教徒都穿着完全一样的标准装束，只要从他们那里收集来一些衣物，就可以搞一身完美的伪装了。$B$B到时候，你可以伪装成工头努埃尔的样子去与库尔菲斯·暗鳞会面，看看他要说些什么，然后把这一切报告给护树者查恩。$B$B穿过龙颅小径以后，沿着路穿越乌鸦林和格里施纳就可以了，集会所就在路的尽头。', '从各类拜龙教成员身上收集衣物碎片，制作一件工头伪装服。使用工头伪装服混入库尔菲斯·暗鳞主办的集会。', '攻击我们?将我们消灭?我可不同意!$B$B这个黑翼集会所要是认为塞纳里奥是好欺负的话他们会大大地得到教训的!$B$B他们是怎么形容这种状况?背叛是公平的竞争!', '你带来了什么消息?你知道那些巨龙教徒在忙些什么吗?', '参加库尔菲斯·暗鳞的会议', '去刀锋山找常青林的护树者查恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10723, '食龙者高格鲁姆', '我们要对付的戈隆是食龙者高格鲁姆。利用萨博迈恩的陷阱，你就能轻易地除掉他。他正在砾石营地接受食人魔的供奉。$B$B沿着鲜血之环北面的道路走，在卢安荒野向西转，穿过隧道后再一直往西北方前进就抵达砾石营地了。$B$B杀入砾石营地，取得食人魔的徽记，向高格鲁姆宣战。在祭坛处利用陷阱杀死高格鲁姆，将3个可怕的图腾插在他旁边，以此打击血槌食人魔的气焰。$B$B带上我的熊吧。$B$B<米莎咆哮着。>', '从砾石食人魔手中夺得3根可怕的图腾。在高格鲁姆的祭坛处使用萨博迈恩的陷阱召唤并消灭食龙者高格鲁姆。$B$B高格鲁姆死后，将3根可怕的图腾插在他旁边。', '血槌的巨魔们和他们的主人，高格鲁姆，将不会再烦扰摩克纳萨尔了。$B$B然而，我担心我们的行动会影响其它戈隆。我相信我们必须永远结束这场战斗。$B', 'NULL', '', '去刀锋山找雷神要塞的雷克萨。', '放置可怕的图腾', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10724, '刀塔的囚犯', '抵达刀锋山后不久我便遭到了刀塔食人魔的袭击。$B$B我奋起反抗，杀出一条血路后总算得以脱身；双足飞龙雷欧克却被食人魔俘获了。斯比雷在格鲁尔的巢穴外发现了它的下落，它被囚禁在刀塔要塞中心的牢笼里。$B$B牢笼的钥匙必定在某个食人魔身上。找到钥匙，让斯比雷打开双足飞龙牢笼。$B$B沿着刃喉谷一直往北走就是刀塔要塞。', '从刀塔食人魔手中夺得双足飞龙牢笼钥匙。拿到钥匙后，在双足飞龙牢笼前使用斯比雷的哨子召唤出斯比雷，它会打开牢笼，营救雷欧克。', '里奥克已经把飞龙之末其中一只黑龙的头带来给我们了。有了这个，我们就能激怒苟克，那个抓住他的戈隆，并且诱骗苟克进入战斗。', '能够再次得到里奥克的协助真是太好了。', '', '去刀锋山找雷神要塞的雷克萨。', '', '', '营救雷欧克', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10742, '摊牌', '决战的时刻即将来临。我们要将苟克从巢穴中引出，然后杀掉这个祸根。苟克一死，刀塔食人魔必定不敢再来侵犯莫克纳萨氏族。转至格鲁尔的巢穴，在巢穴外苟克的祭坛处吹响我的战斗号角。我会跟你并肩作战，共同击败格鲁尔之子。', '在苟克的祭坛处吹响雷克萨的战斗号角，杀死苟克。', '战斗是艰苦的，而你战斗的非常好，$N。我很荣幸能在对抗茍克的战斗中站在你身旁。 我的感谢无法用言语形容。$B$B摩克纳萨尔应该知道这些大失败，但是我还不准备面对他们。我知道我的父亲的心意，并且我知道我的心。仍然有许多我能学习并且变得更强大的，以向他显示我是他真正的儿子。$B', 'NULL', '', '去刀锋山找雷神要塞的雷克萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10747, '拜龙教的龙崽', '我得好好检查检查那些他们在黑翼集会所培育出来的雏龙。$B$B在他们那处洞穴内的基地周围，有许多雏龙在活动。洞穴内还有一个大规模的龙蛋群，只要你接近，就会有雏龙从中破壳而出。$B$B拜托你，$N，带上这张网，捉几只雏龙过来。$B$B向西走过龙颅之桥，然后一路穿越龙颅小径，再沿着道路穿过格里施纳和乌鸦林，就可以找到它们了。', '萨米亚·因克林要求你使用黑色龙崽之网捕捉10只拜龙教黑色龙崽。', '喔我的老天阿，这些比我本来期望的还要多呢!你一定要为了你的勇猛行为受到赞美!$B$B这只优秀的黑色幼龙的幼兽看起来适合用来作一个好的开始。开始检查他们吧。$B$B请接受这个当做报酬。收下吧!', '你在捕抓这些幼龙时有遇到很多麻烦吗?我希望你不会被烧焦!', '', '去刀锋山找常青林的萨米亚·因克林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10748, '玛克纳尔必须死！', '他们让我们别无选择，$N。现在看来，必须除掉他们的头目——灰烬之喉玛克纳尔，才能彻底消灭黑翼集会所的威胁。$B$B我不知道你经过那附近的时候有没有见过他的样子，他算是一只半龙人，半身是人，半身是龙。他很强，千万不要轻敌！$B$B迅速解决掉他，这样就能确保卢安荒野和常青林的安宁与和谐了。', '立刻杀死灰烬之喉玛克纳尔。', '知道我们敌人的首领已经被解决掉使我们现在可以松一口气了。不只如此，你还守住了整片山区免于受到他们的破坏。$B$B不管他们最终的目的为何，你都把他们击退了!$B$B我们对你感激不尽，$N。请收下这个以表我们的敬意，还有我们无尽的欢迎。', '你已经解决了灰喉麦克斯纳尔?$B$B找到他有很麻烦吗?如我所了解的你一进到洞穴后如果是朝右边进去，那些弯来拐去的路最终都会引你到它所在的地方。', '', '去刀锋山找常青林的护树者查恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10749, '萨博迈恩男爵的毒药', '给，把它交给雷克萨。我相信雷克萨会好好利用这瓶毒药的。$B$B哦，记得提醒他，他还欠我一份人情呢。$B$B雷克萨知道我想要什么。我想他一定会设法替我办妥此事，很快我们就会再见面的。$B$B好啦，快把这瓶毒药交给雷克萨吧。', '将萨博迈恩男爵的毒药交给刀锋山雷神要塞的雷克萨。', '这个毒药的用途并不光明正大。但是却可以完成我们想要做得事。', '$C，你这么快就回来了喔?有拿到毒药吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10750, '征服之路', '$N，我从驭风者那儿得知，日蚀血精灵正在谋划一次大规模的行动。他们当前已经开始在东南方的征服之路一带聚集兵力。$B$B我要你转至日蚀岗哨附近的征服之路侦察敌情。判断清楚局势后，使用这支信号枪。一名库卡隆驭风者会在看到信号之后去接应你。将你探得的情报告诉他，而他也会给你下一步的指示。', '转至影月谷的征服之路。', '没错，这些讨厌的家伙们正忙于进行某些邪恶的事。我们必须进行更深入的调查……$B', '你有什么要报告的吗，士兵?', '侦查征服之路', '使用库卡隆信号枪召唤一名库卡隆驭风者。$B$B如果你不慎丢失了库卡隆信号枪，可以问奥巴洛恩大王另要一支。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10751, '扫清道路', '$r，我们必须得继续深入调查。我和另一些驭风者将进入征服之路的上空。真希望我们能查探到更详细的敌情。不过，请你为我们清理前面路上的障碍，当然，最重要的是，确保我们不被血精灵的弓箭给射下来！$B$B在你成功削减他们的数量之后，使用库卡隆信号枪，给我们的驭风者编队发出信号。', '杀死20名日蚀士兵、10名日蚀骑兵和10名日蚀缚法者。', '你不会相信的，步兵。$B', '你有什么要报告吗，士兵?', '', '使用库卡隆信号枪召唤一名库卡隆驭风者。$B$B如果你不慎丢失了库卡隆信号枪，可以问影月谷内影月村的奥巴洛恩大王另要一支。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10753, '清理荒野', '燃烧军团所犯下的恶行可谓磬竹难书。对于这片土地上任何敢于反抗他们的生物，他们都会派出军团实行残忍的清洗政策，而无力反抗他们的种族已经一个接一个地都灭绝了。$N，帮助我阻止他们对自然所犯下的罪孽吧。$B$B越过东边的丘陵地带，你就会看见刀刃峡谷内，正有燃烧军团的爪牙在那里腐化着大自然。阻止这一切，尽可能多地杀掉邪能腐蚀者和魔誓生物吧。', '杀死4只魔誓鳞翼风蛇、4只魔誓刃喉龙和2只邪能腐蚀者。', '知道我们摧毁了当初艾露恩所创造的东西，我并不感到自豪，但是燃烧军团腐化大地这件事需要被阻止。你做得很好$C。', '你已经执行正义了吗?', '', '去刀锋山找常青林的法拉蒂拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10754, '堡垒的钥匙', '这件模具看上去是用来浇铸某种钥匙的。从背后雕刻的图像来看，它似乎跟地狱火堡垒有关。$B$B或许荣耀堡的远征军指挥官达纳斯·托尔贝恩会对此感兴趣。', '将原始钥匙模具交给地狱火半岛荣耀堡的远征军指挥官达纳斯·托尔贝恩。', '这有可能吗?让我仔细看这个模子。', '你有什么东西要给我吗，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10755, '堡垒的钥匙', '这件模具看上去是用来浇铸某种钥匙的。从背后雕刻的图像来看，它似乎跟地狱火堡垒有关。$B$B或许萨尔玛的部落统领纳兹格雷尔会对此感兴趣。', '将原始钥匙模具交给地狱火半岛萨尔玛的纳兹格雷尔。', '一个钥匙模子?这有可能可以让我们进入破碎大厅吗?', '你有什么东西要给我吗，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10756, '罗霍克大师', '钥匙柄上的符号……雕刻在模具内的符号很难辨别，但是我能认出这是碎手邪兽人的钥匙。$B$B这是个很好的机会，这把钥匙可以让你进入破碎大厅。$B$B与我们的铁匠罗霍克谈一谈。如果说有谁能铸造这把钥匙的话，只能是他了。', '将原始钥匙模具交给萨尔玛的罗霍克。', '纳兹格雷尔想要我去做一把钥匙吗?他忘记我们在战场里吗?那里还有成堆刀剑和矛要锻造!', '这是什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10757, '罗霍克的要求', '邪兽人铁匠或许算不上技艺最精湛的铁匠，但他们还是有两把刷子的。想要利用这个模具配制出能用的钥匙，就必须以魔铁锭为熔料——其它材料很可能会破坏模具。$B$B我需要几块魔铁锭、一点奥法之尘还有几颗火焰微粒。我会试着铸造钥匙，但是我不保证能成功。', '将4块魔铁锭、2份奥法之尘和4颗火焰微粒交给地狱火半岛萨尔玛的罗霍克。', '太好了。让我们试试。', '你拿到我要的原料了吗?', '', '去地狱火半岛找萨尔玛的罗霍克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10758, '比地狱更炎热', '$N，真是糟透了！不管我往火堆里扔多少煤块，就是达不到需要的温度。$B$B我唯一能想到的热源就是燃烧军团的魔能机甲，只有利用它体内的高温才能对钥匙进行淬火处理。$B$B我曾亲眼目睹魔能机甲被摧毁时的景象。毁损的机甲喷射着火花和蒸汽，在浓烟中轰然倒地。将钥匙模具插入魔能机甲的残骸中淬火。想要摧毁魔能机甲的话，我建议你叫上几个朋友。', '摧毁地狱火半岛的魔能机甲，将未淬火的钥匙模具插入魔能机甲的残骸，然后将灼烧过的钥匙模具交给萨尔玛的罗霍克。', '你已经成功了!剩下唯一要做的事情只有去试一试它。', '你完成我要求你的事了吗，$C?', '', '去地狱火半岛找萨尔玛的罗霍克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10760, '斯克瑟隆废墟', '东边的斯克瑟隆废墟是个诡异的地方，苦工们都相信那片土地被诅咒了。$B$B然而，这里没有多少树木，因此他们不得不冒险进入鸦人的废墟砍伐木材。于是，鸦人之魂终日折磨着那些苦工，汲取他们的生命来强化邪恶的魔法。$B$B我们必须查明黑暗教团的意图，及时阻止威胁蔓延。你现在就转至斯克瑟隆废墟，搜寻黑暗教团神秘计划的证据。', '从斯克瑟隆废墟黑暗教团的鸦人身上夺得斯克瑟隆指挥官的日记 - 第1页、斯克瑟隆指挥官的日记 - 第2页，以及斯克瑟隆指挥官的日记 - 第3页，将它们交给影月村的卡格鲁尔中士。', '<中士检查日志。>$B$B我看不出来他要多大的用途，但是至少知道有两项证明它是有用。看来似乎这些阿拉卡准备了某种精心制作的魔法仪式，直到他们死的时候，但是为什么呢?这里也有关于一个“背弃者”的奇特笔记。', '你发现了什么?', '', '去影月谷找影月村的卡格鲁尔中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10762, '达姆菲大师', '钥匙柄上有着一个奇特的符号……这种符号应该很难在熔铸的模具上直接印刻出来，不过我认得出这是碎手氏族的标记。$B$B这是个很好的机会，你可以利用这模具配出钥匙，并进入破碎大厅。$B$B与达姆菲谈一谈。他精通各种铁匠工艺，如果他都无法配制出钥匙，那就没人能办得到了。', '将原始钥匙模具交给荣耀堡的达姆菲。', '一把钥匙吗?达纳斯应该让我们做攻城机具的!', '这是什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10763, '达姆菲的要求', '虽然邪兽人都是些没脑子的笨蛋，但是他们的锻造技术却不像你想得那样简单。如果我们想要让铸造出的这把钥匙真正能起作用，那么在铸造时就只能使用魔铁，而其它的材料都有可能造成铸造失败的结果。$B$B给我带一些魔铁锭、奥法之尘和火焰微粒回来。我要亲自试试看，不过不敢保证成功。', '将4块魔铁锭、2份奥法之尘和4颗火焰微粒交给地狱火半岛荣耀堡的达姆菲。', '让我试试看。让我看看邪兽人的制品到底是如何的。', '你有拿到我要求的资源吗?', '', '去地狱火半岛找荣耀堡的达姆菲。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10764, '比地狱更炎热', '不行啊。$g小伙子:姑娘;，看来炉子的温度不够啊……这些材料根本无法熔化和混合。$B$B不过，你知道么，燃烧军团使用的那些魔能机甲是利用某种由十分灼热的魔火所构成的核心所驱动的。那种魔火比一般火的温度要高上许多。$B$B如果你能找到足够的人手去毁掉一台魔能机甲，就可以将这个模具放进机甲的核心中进行加温。$c，一定要小心，那些魔能机甲的战斗力是非常强大的。', '摧毁地狱火半岛的魔能机甲，将未淬火的钥匙模具插入魔能机甲的残骸，然后将灼烧过的钥匙模具交给荣耀堡的达姆菲。', '你做到了，$g少年:少女;!剩下要做的只有把它带到地狱火堡垒并且杀一些兽人!', '你完成我要求你的事了吗，$C?', '', '去地狱火半岛找荣耀堡的达姆菲。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10765, '世界的碰撞……', '在征服之路的南端，有一处商队的大棚车营地。在那里，我发现一个巨人在和一个血精灵使者密会。你大概也已经注意到，这一带有许多体型较小的巨人出没。这事情绝对不简单，士兵。$B$B我要你杀入征服之路，到密会的现场去破坏他们的谈判，再看看能否搜寻到什么线索和信息。完成任务后，使用信号枪给我们驭风者发出信号。', '杀死特派使者莉芙·血叶和强大的考罗克，夺得伊利丹的命令。', '因此他们试图获得那些巨人的支持，呃?我有一个计画能切断这个邪恶的联盟。', '你有什么要报告吗，士兵?', '', '使用库卡隆信号枪召唤一名库卡隆驭风者。$B$B如果你不慎丢失了库卡隆信号枪，可以问影月谷内影月村的奥巴洛恩大王另要一支。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10768, '伊利达雷徽章', '现在我们驭风者部队必须返回影月村，马上开始准备发动下一轮的进攻。而你，我命令你在这边收集一些日蚀血精灵身上的徽章。$B$B收集到足够的徽章之后，你可以使用库卡隆信号枪召唤来一名驭风者。$r，接下来你就要当间谍了！', '收集10件伊利达雷徽章。', '啊哈!这些将完成的十分好。$B', '你有什么要报告的，士兵?', '', '使用库卡隆信号枪召唤一名库卡隆驭风者。$B$B如果你不慎丢失了库卡隆信号枪，可以问影月谷内影月村的奥巴洛恩大王另要一支。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10769, '散播敌意……', '附魔材料全是研究员提欧鲁斯准备的，我所要做的不过是将伊利达雷徽章浸入这些混合物中。好，完成了，这件徽章现在已经融合了伊利达雷的精华。$B$B带上这件魔化伊利达雷徽章，转至位于日蚀岗哨西南方的日蚀平原。你一进入平原后就立即换上它，伪装成伊利丹的手下，之后，利用这伪装杀死那些在平原上游荡的疯狂的巨人。这样一来，他们必定会认为血精灵缺乏与其结盟的诚意！', '伪装成伊利达雷血精灵，杀死5个疯狂的巨人，然后向影月谷内影月村的奥巴洛恩大王复命，并将库卡隆信号枪一并交还给他。', '嗯，嗯，很好……这不是我派到战场的蛮兵。你回来了，完整的回来了。$B$B<欧巴洛卡赫点头。>$B$B我知道你不会让我失望的，士兵。你已经阻止了伊利达瑞主要的前进，而在此过程中，你已为你自己赢得一点报酬。', '你回来了!', '', '去影月谷找影月村的奥巴洛恩大王。', '在伪装状态下杀死疯狂的巨人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10770, '灰烬中的小鬼', '在这里的东北方有一处高地，那里被我古老家乡燃烧之后留下的厚厚的尘埃复盖着。那曾是一片郁郁葱葱、枝繁叶茂的大森林，但是却被燃烧军团派遣小鬼烧光了，无数的生灵死于非命。尽管这件事已经过去了好几个世纪，但我复仇的信念却一直没有消逝过。那些小鬼的数量繁多，这让我们收复失地的工作进展艰难，但若是你去的话，一定会让它们感到恐惧的。$B$B你愿意帮助我吗？', '古树莫斯伍德要求你杀死8只灼烧小鬼，然后回去向他复命。', '它们的数量实在太多，我们永远无法全部杀死他们，但是你已经给我希望了。或许我应该再稍微努力试试几个世纪来让我深爱的树木复活。', '不久我将安息于森林的深处。在我将根深入地下，并且永远闭上双眼前，我希望知道那些卑鄙的小鬼遭受处罚并且死亡。', '', '去刀锋山找常青林的古树莫斯伍德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10771, '灰烬中的新生', '一直沿着路向东走，越过山顶后再折向北方，你就会到达我那失落已久的家乡。$b$b那里曾是一片美丽而宁静的大森林，它的名字我已经记不清了。但是在几百年前，燃烧军团召唤出了无数的小鬼和其它火元素生物进攻了那里。于是，我的家园毁灭了，宗族的成员四散奔逃，只有我还留在这里。$B$B现在，我这里有一些铁根种子，它们当中蕴涵着强大的魔法力量，可以在肥沃的火山灰里健康成长。替我将它们种植在那里吧，我会以一些古老的财宝回报你的。', '古树莫斯伍德要求你转至焦火荒野，将铁根种子植入那里三堆不同的肥沃的火山灰中，然后回到卢安荒野向他复命。', '你杀死了那么多的邪恶小生物。知道这消息我就能早点安心休息了。', '完成了吗?你把一些生物送回我的故乡了吗?', '', '去刀锋山找常青林的古树莫斯伍德。', '南部火山灰', '中部火山灰', '北部火山灰', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10772, '征服之路', '$N，我从狮鹫骑士们那边得知，日蚀血精灵正在谋划一次大规模的行动。他们当前已经开始在东南方的征服之路一带聚集兵力。$B$B我要你转至日蚀岗哨附近的征服之路侦察敌情。判断清楚局势后，使用这支信号枪。一名蛮锤狮鹫骑士会在看到信号之后去接应你。将你探得的情报告诉他，而他也会给你下一步的指示。', '转至影月谷的征服之路。', '没错，这些讨厌的家伙们正忙于进行某些邪恶的事。我们必须进行更深入的调查……', '你有什么要报告的吗，士兵?', '侦查征服之路', '使用蛮锤信号枪召唤一名蛮锤狮鹫骑士。$B$B如果你不慎丢失了蛮锤信号枪，可以问影月谷内蛮锤要塞的大领主尤雷加尔另要一支。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10773, '扫清道路', '$r，我们必须得继续深入调查。我和另一些狮鹫骑士将进入征服之路的上空。真希望我们能查探到更详细的敌情。不过，请你为我们清理前面路上的障碍，当然，最重要的是，确保我们不被血精灵的弓箭给射下来！$B$B在你成功削减他们的数量之后，使用蛮锤信号枪，给我们的狮鹫骑士编队发出信号。', '杀死20名日蚀士兵、10名日蚀骑兵和5个考罗克之子。', '你不会相信这的，士兵!$B', '你有什么要报告的，士兵?', '', '使用蛮锤信号枪召唤一名蛮锤狮鹫骑士。$B$B如果你不慎丢失了蛮锤信号枪，可以问影月谷内蛮锤要塞的大领主尤雷加尔另要一支。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10774, '血精灵 + 巨人 = ？？', '在征服之路的南端，有一处商队的大棚车营地。在那里，我发现一个巨人在和一个血精灵使者密会。你大概也已经注意到，这一带有许多体型较小的巨人出没。这事情绝对不简单，士兵。$B$B我要你杀入征服之路，到密会的现场去破坏他们的谈判，再看看能否搜寻到什么线索和信息。完成任务后，使用信号枪给我们狮鹫骑士发出信号。', '杀死特派使者莉芙·血叶和强大的考罗克，夺得伊利丹的命令。', '因此他们试图获得那些巨人的支持，呃?我有一个计画能切断这个邪恶的联盟。', '你有什么要报告的，士兵?', '', '使用蛮锤信号枪召唤一名蛮锤狮鹫骑士。$B$B如果你不慎丢失了蛮锤信号枪，可以问影月谷内蛮锤要塞的大领主尤雷加尔另要一支。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10775, '伊利达雷徽章', '现在我们狮鹫骑士编队必须返回蛮锤要塞，马上开始准备发动下一轮的进攻。而你，我命令你在这边收集一些日蚀血精灵身上的徽章。$B$B收集到足够的徽章之后，你可以使用蛮锤信号枪召唤来一名狮鹫骑士。$r，接下来你就要当间谍了！', '收集10件伊利达雷徽章。', '啊哈!这些将完成的十分好。', '你有什么要报告的，士兵?', '', '使用蛮锤信号枪召唤一名蛮锤狮鹫骑士。$B$B如果你不慎丢失了蛮锤信号枪，可以问影月谷内蛮锤要塞的大领主尤雷加尔另要一支。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10776, '散播敌意……', '附魔材料全是诺姆斯准备的，我所要做的不过是将伊利达雷徽章浸入这些混合物中。好，完成了，这件徽章现在已经融合了伊利达雷的精华。$B$B带上这件魔化伊利达雷徽章，转至位于日蚀岗哨西南方的日蚀平原。你一进入平原后就立即换上它，伪装成伊利丹的手下，之后，利用这伪装杀死那些在平原上游荡的疯狂的巨人。这样一来，他们必定会认为血精灵缺乏与其结盟的诚意！', '伪装成伊利丹的手下，杀死5个疯狂的巨人，然后向影月谷内蛮锤要塞的大领主尤雷加尔复命，并将蛮锤信号枪一并交还给他。', '嗯，嗯，很好……这不是我派到战场的士兵。你回来了，完整的回来了。$B$B<忧瑞卡尔点头。>$B$B我知道你不会让我失望的，士兵。你已经阻止了伊利达瑞主要的前进，而在此过程中，你已为你自己赢得一点报酬。', '你回来了!', '', '去影月谷找蛮锤要塞的大领主尤雷加尔。', '在伪装状态下杀死疯狂的巨人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10777, '阿斯迦的图腾', '你从指挥官的日记中读到的故事是真的。当初，就在古尔丹集结兽人大军准备入侵艾泽拉斯世界时，我的族人们勇敢地提出抗议，想要阻止这场灾难。古尔丹获悉了这一切，便施放强大的法术摧毁了我们氏族的营地，扭曲了族人们的灵魂。$B$B必须在黑暗教团的家伙释放出更可怕的邪灵前阻止他们！转至北方的斯克瑟隆废墟寻找阿斯迦，取回他随身携带的图腾。这样，我们就能制止黑暗教团的计划了。', '将斯克瑟隆作战图腾交给熔岩平原的帕沙恩。', '<帕莎检查图腾。>$B$B很好。过了这么多年这个旧图腾也没失去它的力量，但是只有它还不够制止黑暗议会。', '你从阿斯格那取得图腾了吗?', '', '去影月谷找熔岩平原的帕沙恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10778, '莉安丝魔棒', '斯克瑟隆作战图腾尚不足以与黑暗教团的邪恶魔法抗衡。$B$B我们可将图腾和其它拥有强大力量的物品组合起来，制作成一根聚能法杖。虽然已经无法将族人们从堕落的深渊中拯救出来，可我们至少能阻止他们越陷越深。$B$B首先我需要莉安丝魔棒，它在东南方日蚀岗哨的血精灵们手中。它被放置在废墟顶层的营帐中，周围有重兵把守。千万小心，$N。', '从日蚀岗哨的血精灵身上夺得莉安丝的钥匙，用它打开莉安丝的保险箱并取出莉安丝魔棒。然后向熔岩平原的帕沙恩复命。', '做得好。这样的一个宝物不应该只是被隔离在一个黑暗的箱子里。我们将看见它用于有价值的目的。', '你有拿到那根魔棒吗?', '', '去影月谷找熔岩平原的帕沙恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10780, '斯克瑟隆羽毛', '制作法杖还缺一样东西。我们必须将法杖的力量调整成可以针对黑暗教团精神力量的属性。$B$B收集散落在斯克瑟隆营地周围的羽毛来制作法杖。那个营地位于这里以南，蛮锤要塞以东。$B$B古尔丹强大的力量彻底摧毁了族人们的肉身，只剩下他们的灵魂在世间游荡，可事情远没有终结。鸦人还汲取了残留的魔法力量，他们那邪恶的仪式不断吞噬着族人们的灵魂。', '收集8片斯克瑟隆羽毛，然后向熔岩平原的帕沙恩复命。', '<帕莎接过除去灰尘的羽毛，摇着头。>$B$B如果他们那天死了，就会更好一点儿，但是不会那么简单的。那古尔丹的魔法将会把他们变成他们试图制止的威胁，是一种特别残酷之命运的扭曲。', '你收集到权杖所需要的羽毛了吗?', '', '去影月谷找熔岩平原的帕沙恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10781, '火红岗哨之战', '他们很可能正在征服之路附近搜寻你的下落。$r，快逃命去吧！$B$B别管我了，我已经不行了……这帮家伙……我已经听见他们的脚步声了。现在就走！否则肯定来不及了！快逃走吧！如果你选择留下来，就必须奋战到底！$B$B若是你能在战斗中活下来，请一定要将此地的情形转告给沙塔斯城的阿达尔。', '击败驻守在火红岗哨的伊利丹的部队！$B$B获胜后向沙塔斯城的阿达尔复命。', '赤红法印将会受到调查。他们威胁了德拉诺的所有生命。我预见了他们的黑暗主人有天必须对他的罪行负责。或许将是你将他送交审判，英雄。', '<阿达欧问候你。>', '消灭火色魔印的军队', '去泰罗卡森林找沙塔斯城的阿达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10782, '为杖头充能', '法杖就快做好了！$B$B这片被诅咒的土地上依然涌动着古尔丹残存的力量，我们需要将这种力量灌入未完成的杖头。东边的魔能熔池附近有一座诅咒祭坛，就在死亡熔炉南面。$B$B那儿禁锢着古尔丹的残骸碎片。如果携带未完成的杖头进入祭坛，某些实体可能会对此做出回应，你可别惊慌失措。此行危险重重，请千万小心。', '带上未完成的杖头，转至诅咒祭坛，在古尔丹附近使用未完成的杖头。将充满能量的杖头交给熔岩平原的帕沙恩。', '<帕莎接过权杖头，小心冀冀地拿着。>$B$B这东西拥有足够的力让我们中断在史凯瑟隆营地里黑暗议会的所有努力。', '你带着充满能量的权杖头回来了吗?', '', '去影月谷找熔岩平原的帕沙恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10784, '踏平血槌营地', '<托查克凑到你耳边，压低了嗓门。>$B$B$N，有你这样的勇士帮助我们对抗食人魔真是荣幸。我相信雷克萨已经制定了周密的计划，但是我还想请你帮个忙，在你返回雷神要塞前能不能去血槌营地杀些食人魔？$B$B这样会收到事半功倍的效果。$B$B沿着雷神要塞北边的坡道一直走，在坡道尽头往西穿越巨龙之末，然后往北穿越沸土峡谷和刃喉谷就到了。', '杀死10个血槌粗暴者和5个血槌术士。', '<吐查克明显的点了点头嘉许你杀敌的勇猛。>$B$B你持续的让我印像深刻，$N。每一次打倒一个巨魔之时，我们就更进一步摆脱了我们不值得的仇敌。', '你消灭血槌营地了没?', '', '去刀锋山找雷神要塞的托查克·双爪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10785, '这是个陷阱！', '我对格鲁尔之子和他们的父亲简直恨之入骨。他们残忍地杀害了我的族人，连毫无抵抗力的孩子都没有放过，我要复仇。$B$B这是龙火制成的陷阱，如果你够聪明的话，应该能利用它杀死戈隆。$B$B把龙火陷阱交给雷克萨吧。平息我心中的怒火！', '将龙火陷阱交给刀锋山雷神要塞的雷克萨。', '嗯，一个由龙火的精华制作的陷阱吗?我很好奇沙伯迈恩是如何得到这种稀有的物质吗?$B$B那一点都不重要。重要的是我们将用它来杀死一个格鲁尔的儿子!', '你有在戈隆的大袋里找到沙伯迈恩所需要的吗?他给了我们什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10786, '砾石营地的食人魔', '我知道雷克萨要你转至砾石营地执行任务，恰好有件事可以交给你顺路去办。$B$B我们必须把握一切机会，击毙盘踞在刀锋山的食人魔，否则他们就会攻入雷神要塞，摧毁我们用生命换来的土地！$B$B砾石营地在遥远的西北方。转至北面的卢安荒野，然后向西转，穿越隧道和乌鸦林就到了。$B$B$N，我要你杀死砾石营地的刀塔食人魔。消灭他们！', '杀死5个砾石蛮兵和3个砾石萨满祭司，然后返回刀锋山的雷神要塞向托查克·双爪复命。', '<吐查克露出牙齿笑着关于你告诉他那些你在圆面之地冒险的故事。>$B$B嗯，我真希望我也在场。让我告诉你某些事情，$N∶决不要接受妨碍你战场光荣的任何职责!$B$B哈!在所有食人魔都被你杀死之后，在这些山里还有剩下给我的吗? !$B', '我们在短时间内造就了许多，你和我。我敢说你是我所知道之最有能力的巨魔猎人。$B$B我相信你不久后将会对付圆面之地的巨魔们吧?', '', '去刀锋山找雷神要塞的托查克·双爪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10791, '迎接狼魂', '仪式中要穿的祭袍我差不多已经制作好了。不过，还有最后一件事情要做，我要你帮我把这熏香放置在左边符石附近的烛台旁。$B$B这是以前的兽人部落制作的东西，我相信它能帮助我们引起狼之魂的注意。我还隐约能回忆起我的祖先们在每一次狩猎成功之后，在祭祀狼之魂的仪式上使用这种熏香的情景。$B$B一旦你将熏香放置好，我就将开始仪式。', '在玛鲁卡兹的棚屋中靠近烛台的地方使用仪祭熏香，并观看仪式。仪式完成之后，与玛鲁卡兹谈一谈。', '这是难以置信的!我在不确定是否狼魂将回应我们召唤的旅行上出发，但现在彷佛觉得他总是到过这里。或许他到过，$N。$B$B或许他正等着兽人意识到他们的选择已经做了。', '与狼魂重建联系正是我旅行的开始，而非结束。', '', '去泰罗卡森林找裂石堡的玛鲁卡兹。', '', '帮助玛鲁卡兹召唤狼之魂', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10792, '燃烧吧，塞斯高！', '血环氏族背离了兽人高贵的传统！只有誓死与玛诺洛斯的嗜血诅咒抗争过的勇士才算得上真正的兽人。我们鄙视那些邪恶的表亲，瞧瞧他们软弱低贱的模样……堕落的兽人应该被烧死！$B$B进入东边血环兽人的据点塞斯高，烧毁他们的建筑物。从血环苦工手中夺得火炬，利用塞斯高的熔炉点燃火炬并将它们扔进兽人的房舍、兽栏和兵营。焚毁塞斯高，然后再回来找我！$B$B为了部落！', '从血环苦工手中夺得火炬，利用塞斯高的熔炉点燃火炬，并将它们扔进塞斯高的建筑物中。', '哈!我从这里就能看见萨斯葛尔的烟雾和火焰!那些血之谷恶魔可能已烧成灰，并且漂离了任何真实兽人的视线!$B$B感谢你，N。你帮助烧毁了每一个兽人灵魂的梦魇。', '萨斯葛尔必须被烧毁，$N!当你的任务完成时，再次与我谈话。', '', '去地狱火半岛找断背岗哨的达克霍尔上尉。', '烧毁兵营', '烧毁东部小屋', '烧毁西部小屋', '烧毁兽栏');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10793, '瓦萨雷克的日记：战争的前奏', '日志中记载了伊利丹军队近期的动向，还提到了瓦萨雷克率兵驻守征服之路的原因。原来这家伙亲手俘虏了一名沙塔尔高级将领。$B$B当前，这位将军被关押在位于征服之路南端的火红岗哨。一个名叫火色魔印的神秘组织负责看守囚犯。你若是想要调查此事，最好叫上你的朋友一同转至。', '转至火红岗哨寻找玛库斯·奥拉林，他是沙塔尔的高级将领。$B$B你可以在一间水晶监狱中找到他。', '你杀掉他们的征服者了?那么我们没有很多时间……$B$B赤红法印是一个由伊利丹杰出的爪牙所组成团体。他们是在黑暗神庙外所有伊利达瑞部队之指挥系统的顶端。这些士兵直接与这里的背叛者通信，并毫无疑问地执行他的命令。$B$B他们无疑是对这个世界发动攻击的恶魔，践踏挡住他们道路的所有人。', '<阿瑞利恩将军漂浮在水晶中间。>$B$B你……你在这里做什么?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10795, '多古克', '我在常青林见过你好几次，一直想跟你商量件事。$B$B我接到好几份报告，称血槌食人魔准备对希尔瓦纳和卢安荒野发动攻击。我们还不知道是谁在背后捣鬼，不过先下手为强，必须将他们的计划扼杀在摇篮中！$B$B食人魔的作战基地血槌营地就在卢安荒野的西北方，去干掉他们的首领多古克！', '转至血槌营地杀死多古克。', '多尔哥克一死，血槌巨魔就没有领导了，且应该会处在混乱里，直到另一位领导人从他们的行列里出现。$B$B谢谢你，$C，我认为我们现在能呼吸得容易一点了。', '我无法足够强烈地表示你尽快杀死多尔哥克有多重要。', '', '去刀锋山找常青林的指挥官海弗斯·石墙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10796, '踏平血槌营地！', '听说你狠狠地打击了食人魔的嚣张气焰，大家都为此感到自豪。现在我要你再次拿起武器，踏平血槌营地！$B$B沿着卢安荒野西北方的坡谷一直走就是血槌营地了。$B$B$c，祝你好运！', '杀死10个血槌粗暴者和5个血槌术士。', '<中尉点头明显嘉许你杀敌的勇猛。>$B$B我对你印象深刻，$N。你的声望名副其实。$B$B每一次打倒一个巨魔时，我们就朝摆脱危险留下平静更接近一步了。', '你摧毁了血槌营地了吗?', '', '去刀锋山找常青林的法维瑟中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10797, '戈隆的信物', '一尊小雕像从多古克掌中滑落。雕像上的人物竟然与某个戈隆惊人地相似。$B$B指挥官海弗斯·石墙一定会对此感兴趣的！沿着东面的坡谷进入卢安荒野，去常青林找他吧。', '将高格鲁姆的信物交给刀锋山常青林的指挥官海弗斯·石墙。', '喔，漂亮。看起来很像总是在指挥周遭刀塔食人魔的那些戈隆。$B$B奇怪的是你应该在血槌领导人之一的手里找到它。', '你好，$g少年:少女;，你带来什么消息?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10799, '进入沸土峡谷', '嗯，我会帮你制作龙火陷阱，但是你得用别的东西来交换。$B$B鲜血之环附近居住着一个戈隆，他手中有我想要的东西。但是你不能直接面对他，至少现在还不是时候。$B$B我打算利用硬壳穿地虫的毒囊配制某种催眠粉。$B$B硬壳穿地虫就分布在西南方的沸土峡谷，把它们的毒囊带回来给我，动作快点！', '将7个硬壳穿地虫的毒囊交给刀锋山鲜血之环的萨博迈恩男爵。', '非常好，以世人的角度来看，一份简单的工作完成了。现在，把腺体交给我，我就会进行最困难的部分。\r\n\r\n', '你弄到全部的地壳穿刺者毒腺了吗?如果不是，就离开这里不要浪费我的时间! ', '', '去刀锋山找鲜血之环的萨博迈恩男爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10800, '晚安，戈隆', '我真是个天才。催眠粉已经配制好了，利用它去对付那个名叫格鲁洛克的戈隆吧。我说过，这家伙手中有我想要的东西。$B$B转至鲜血之环另一侧，巨龙之末东部边缘的诅咒洞窟寻找他的踪迹。$B$B如果我是你的话，一拿到格鲁洛克的包裹，我就会立即离开。催眠粉的有效时间不会持续太长的。', '偷走格鲁洛克的包裹，将它交给刀锋山鲜血之环的萨博迈恩男爵。', '<沙伯迈恩男爵凝视着戈隆的袋子里面，看起来好像很满足。>$B$B非常好，你已经履行约定了。现在，我将给你的指挥官海法斯.石墙那个陷阱。', '你再次来到我面前，$C。这必定代表着你已经从格鲁洛克的鼻子下面取出袋子。', '', '去刀锋山找鲜血之环的萨博迈恩男爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10801, '这是个陷阱！', '我对格鲁尔之子和他们的父亲简直恨之入骨！他们残忍地杀害了我的族人，连毫无抵抗力的孩子都没有放过，我要复仇！$B$B这是龙火制成的陷阱，如果你够聪明的话，应该能利用它杀死戈隆。$B$B我知道你有自己的计划，不过我不在乎你杀死的是哪一个。把龙火陷阱交给指挥官海弗斯·石墙吧。$B$B平息我心中的怒火！', '将龙火陷阱交给刀锋山常青林的指挥官海弗斯·石墙。', '嗯，一个由龙火焰的本质制作的陷阱吗?不知道沙伯迈恩怎样得到这样稀薄的物质?$B$B一点儿也不重要。重要的是我们将用它来杀死一个格鲁尔的儿子!', '男爵帮我们做了陷阱了吗?强大的足以杀死一只戈隆吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10802, '食龙者高格鲁姆', '必须让食人魔明白，我们不是好惹的。得给他们点颜色看看。$B$B杀入砾石营地，取得食人魔的徽记。$B$B在高格鲁姆的祭坛处布下陷阱，诱使高格鲁姆落入圈套。利用陷阱杀死高格鲁姆后，将可怕的图腾插在他的尸体旁。那些食人魔就会知道，如果他们胆敢再次来犯的话，高格鲁姆和那些死去的同伴就是他们的下场。', '转至砾石营地，从砾石食人魔手中夺得3根可怕的图腾。在高格鲁姆的祭坛处使用萨博迈恩的陷阱召唤并杀死食龙者高格鲁姆。$B$B高格鲁姆死后，将3根可怕的图腾插在他旁边，然后返回刀锋山常青林向指挥官海弗斯·石墙复命。', '做得好，$N。做得好!$B$B我怀疑我们会从巨魔和他们的主人那里听到更多消息。$B', '讯息被递送了吗?', '', '去刀锋山找常青林的指挥官海弗斯·石墙。', '放置可怕的图腾', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10803, '砾石营地的食人魔', '我知道你要转至砾石营地执行任务，恰好有件事可以交给你顺路去办。$B$B我们必须把握一切机会，击毙盘踞在刀锋山的食人魔，否则他们就会攻入常青林，摧毁我们用生命换来的土地！$B$B砾石营地就在西边。往西南方前进，越过大桥和隧道，乌鸦林以西就是砾石营地了。$B$B$N，我要你杀死砾石营地的刀塔食人魔。', '杀死5个砾石蛮兵和3个砾石萨满祭司。', '<中尉费尔威德笑着听你诉说那些你在圆面之地冒险的故事。>$B$B嗯，真希望我当时也能与你一起在那里。让我告诉你一件事情，$N∶绝不要接受任何妨碍你战场光荣的职责!$B$B哈!在所有食人魔都被你杀死之后，这些山里还有剩下给我的吗?!$B', '我敢说你是我所知道最有能力的巨魔猎人。$B$B我相信那时你很快就会对付圆面巨魔吧?', '', '去找常青林的法维瑟中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10804, '友善', '不知道它们受到了什么惊吓，$r。$B$B<莫德奈指着盘旋在空中的虚空幼龙。>$B$B它们甚至不肯下来进食。已经有好几只虚空幼龙精疲力竭，直挺挺地坠落在地。$B$B我们必须挽救它们的性命！虚空幼龙以岩爪劫掠者为食。猎杀水晶附近的岩爪劫掠者，将岩爪劫掠者肉块放在地上等待虚空幼龙前来进食。只要你站立不动，别做任何进攻性的动作，它们是不会伤害你的。', '影月谷灵翼平原的莫德奈要你喂养8只成熟的灵翼幼龙。', '你是亲切和有同情心的$r，朋友。', '我不能靠自己救出他们，$N!', '', '去影月谷找灵翼平原的莫德奈。', '喂养成熟的灵翼幼龙', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10805, '扫荡格鲁尔的巢穴', '你真是位足智多谋的勇士，现在我要派你去对付格鲁尔和他的儿子们，为我报仇雪恨。$B$B刀塔氏族备受戈隆的宠爱。你或许杀过不少刀塔食人魔，但是应该还没有跟他们中的强者较量过吧。$B$B格鲁尔安排了最强壮的食人魔驻守在巢穴外，你必须削弱他们的防御力量。往北穿越刃喉谷，格鲁尔的巢穴就在刃喉谷尽头。', '杀死10个刀塔执行者、5个刀塔战斗法师、5个刀塔掠食者和他们的首领芬戈洛姆。', '非常好，我选你带领我的战斗是明智选择。我想，事情进展到全新的局面了。$B$B你记得你从在格鲁洛克的鼻子下面为我偷的那个小东西吗?你将要有机会充分利用它了。', '你设法消灭在格鲁尔的巢穴的刀塔食人魔了吗?$B$B不要给我理由，$g男孩:女孩;!完成这工作!', '', '去刀锋山找鲜血之环的萨博迈恩男爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10806, '摊牌', '与刀塔食人魔的统治者——苟克决战的时刻即将来临。我要亲临现场，见证戈隆的死亡。$B$B在苟克的祭坛处使用我的徽记，我会与你并肩作战。$B$B让我们共同击败苟克吧。', '在苟克的祭坛处使用萨博迈恩的徽记，杀死苟克。', '你身为$r的战斗出色的令人吃惊，很荣幸有你在我身边。我的转变一定让你感到相当的惊讶。我相信它没吓到你吧?\r\n\r\n让我们替我的真实身份保密，好吗?做为报答，和感谢你的内行服务，我准许你选择这些小玩意中的任何一个。\r\n\r\n', '不久之后，格鲁尔全部的儿子都将被消灭。 ', '', '去刀锋山找鲜血之环的萨博迈恩男爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10807, '灰舌破碎者', '灰舌氏族是所有破碎者中最可怕的存在，这个氏族的成员都经过阿卡玛的精挑细选，个个生性邪恶、嗜血成瘾。即使是与伊利丹麾下的其它纳迦部队、恶魔部队或是血精灵部队相比，他们的残忍与无情也毫不逊色。眼下，有大批灰舌破碎者盘踞在北方的巴尔里废墟一带。我们要先下手为强，在这帮家伙有机会攻击我们之前削弱他们的势力。', '劝诫者瓦伦要你进入巴尔里废墟，杀死3名灰舌驯兽者、4名灰舌战士和6名灰舌萨满祭司。$B$B为占星者完成任务将降低你在奥尔多阵营中的声望等级。', '占星者万岁，$N。你已经完成预言者的命令打败了伊利丹的追随者。', '你已经完成我交给你的任务了吗，$N?', '', '去影月谷找群星圣殿的劝诫者瓦伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10808, '阻止黑暗教团', '黑暗教团当前正在斯克瑟隆营地以南的熔岩坑举行仪式，企图召唤强大的上古邪灵。$B$B他们汲取了古尔丹残存的魔法，强化了自身的力量，想要帮助邪灵来到我们的世界！$N，我们绝不能让这种事发生。一旦黑暗教团的奸计得逞，上古邪灵引发的毁灭性后果简直难以想象！$B$B带上法杖转至熔岩坑，彻底破坏黑暗教团的召唤仪式！', '杀死黑暗教团仪祭者，然后使用帕沙恩的法杖破坏黑暗教团的召唤仪式。完成任务之后向熔岩平原的帕沙恩复命。', '我已经寻找一种可制止黑暗议会的方法许多年了，而你已经在我失败的地方成功了。议会的黑暗仪式将不再威胁我们。$B$B我经常为多年以前放弃我全部的同伴感到内疚，但是现在我终于知道我做了正确的决定。那么，要不是因为我摇摆的良心，我可能只是他们其中的一个幽影了。', '完成了吗，$N?你阻止黑暗议会完成他们的仪式了吗?', '', '去影月谷找熔岩平原的帕沙恩。', '终结黑暗教团的召唤仪式', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10809, '通缉：座狼主宰卡鲁什', '通缉令：$B$B“悬赏击杀座狼主宰卡鲁什的勇士。卡鲁什是血环氏族狼骑兵的首领，他曾多次率兵袭击断背岗哨的补给车队。”$B$B“据斥候回报，他当前藏匿在塞斯高内。任何能取得他徽记的英雄将受到部落的感激，以及大笔赏金。”$B$B“- 达克霍尔上尉”', '杀死座狼主宰卡鲁什，将他的徽记交给断背岗哨的达克霍尔上尉。', '啊，因此你杀了那个恶棍，科洛斯!做得好，$N!做得好!他的死将使那些受诅咒的座狼骑士受挫。事实上，我希望你在突袭萨斯葛尔期间解决掉他们一些人!$B$B这里是你的报酬。这是你应得的!', '报告，$N。我在你袖子上看见的是血之谷的血吗?我希望是!', '', '去地狱火半岛找断背岗哨的达克霍尔上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10810, '损坏的面具', '当你检查着这个破碎的面具时，似乎听到其中传出了某种奇怪的声音。如果这个面具没有损坏，或许声音还会更清晰一些。$B$B卢安荒野的塔利·萨普纳波或许能修好这个面具。', '将损坏的面具交给卢安荒野的欧玛利·萨普纳波。', '喔，你拿来了什么?让我仔细的看看，$C。是的，是的……这跟我想的一样。嘿，让我帮你把这个面具修好吧。', '别来烦我!你看不出来我正在解开神秘力量的秘密吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10812, '神秘的面具', '好了，现在应该没问题了。啊？你问这是什么？怎么说呢，它是个联络工具，有了这个，那些傻瓜就可以互相联络了。谁是傻瓜？就是燃烧军团呀！我建议你把这个面具带去给荒野之王安塔里恩看看，他就在那边踱着方步呢。他老是走来走去的，静不下来。$B$B好了，快去吧，他最近一直想搞到一个这种面具。', '将神秘的面具交给刀锋山常青林的荒野之王安塔里恩。', '你手上的面具叫做邪誓防毒面具，而且从外观上看来并没有破损。这下子我们可以在炼冶场:怒气制造的麻烦就很多了。你有兴趣帮助我们吗，$N?', '我不敢相信我的眼睛。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10813, '格里洛克之眼', '$N，你勇敢地进入血环兽人的老巢——可怕的塞斯高，并毫发无伤地回来了！既然你这么强，一定有能力帮助我窥探血环氏族最强的巫师格里洛克的思想！$B$B使用这块碎片捕获格里洛克之眼，让眼球与你连接在一起，然后回到我这儿来，走近我的锅……它会令格里洛克之眼与你分离。$B$B去吧，$N。小心一点。只要稍不留神，格里洛克之眼就可能把你暴露给我们的敌人。', '使用塞萨克的碎片捕获格里洛克之眼，然后利用塞萨克的熔锅使格里洛克之眼与你分离。完成任务后将塞萨克的碎片还给塞萨克。', '我感激你，$N。你已经再次英勇地面对萨斯葛尔，并且把它的黑暗靠近你的心。我将研究这颗眼睛，或许能识破它的主人，葛锐洛克的秘密。$B$B让我们希望他再也不能使用它的魔法!', '血之谷氏族的兽人很久以前是黑暗的盟友……甚至是比现在更黑暗的敌人。', '', '去地狱火半岛找断背岗哨的塞萨克。', '交回格里洛克之眼', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10814, '奈尔萨拉库的故事', '这些信息可能对你有用。请仔细听我说，$r。', '与奈尔萨拉库谈一谈，听听他的故事。', '所以你会帮助我们吗?', '允许我告诉你我完整的故事。', '奈尔萨拉库的故事', '去影月谷找灵翼平原的奈尔萨拉库。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10816, '夺回圣地', '$N，你狠狠地打击了盘踞在巴尔里废墟的灰舌破碎者。现在，让我们再来看看你如何对付伊利丹麾下的其它恐怖军队。$B$B影月氏族的邪兽人占领了阿塔玛平台，那儿曾是我的族人们使用阿塔玛水晶举行神圣仪式的圣地。$B$B我们确信这帮家伙将那块阿塔玛水晶藏在了阿塔玛平台附近，可惜我占卜不到它的下落。无论如何，邪兽人侵占了德莱尼人的圣地，他们就得死。', '杀死8名影月斩杀者、8名影月天选者和4名影月暗法师，然后向守备官奥鲁门复命。$B$B为奥尔多完成任务会使你在占星者阵营中的声望等级降低。', '做的好，$C。愿圣光继续保护你。', '嘿，\r\n $N。你带了什么消息回来?', '', '去影月谷找沙塔尔祭坛的守备官奥鲁门。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10817, '严厉的报复', '你狠狠地打击了灰舌破碎者的嚣张气焰，$N。如果你对自己有信心的话，我就再交给你一项任务。$B$B不久前，伊利丹手下的邪兽人曾大举侵犯群星圣殿。$B$B我们断定滋扰生事的是阿塔玛平台的影月谷兽人。$B$B让这帮家伙尝尝占星者的厉害。', '劝诫者瓦伦要求你杀死8名影月斩杀者、8名影月天选者和4名影月暗法师。$B$B为占星者完成任务会使你在奥尔多阵营中的声望等级降低。', '你今天获得我最大的尊敬，$N。$B$B杀死一个邪兽人不是一项容易的任务。大量屠杀他们则是，呃……英勇的。', '嘿， $N。你带了什么消息回来?', '', '去影月谷找群星圣殿的劝诫者瓦伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10820, '欺骗敌人', '你要是再一声也不吭，你就死定了！说话！说话呀！$B$B什么？营地里有叛乱？绝对不可能！我的仆从从来不会有胆子反抗我的权威。$B$B什么，是真的？好吧，背叛的代价，可是会越来越沉重的，直到他们根本无法负担。让他们都永远闭上嘴吧！完成了命令再来向我报告。', '杀死4名末日熔炉随从和4名末日熔炉技师。', '这下子就可以告诉其它人不听我的话的下场……$B$B对了……末日哀嚎者在哪里?为什么你要向我回报这场叛变而不是她?', '我已经失去耐性了，为什么那些人还没解决呢?', '', '去刀锋山找铸魔营地：怒火的军团联络器。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10821, '你玩完了！', '什么？厄运传令者对这次的叛乱袖手旁观？她也敢！她以前好几次都想取代我的地位，不过失败了。这是最后一次了，我不会再给她机会了。这个位子是我的，我不给，她不能抢！你必须立刻把她召唤出来，干掉她。$B$B召唤她到铸魔营地：怒火的钥匙是由她手下最精锐的怒火守卫拿着的。把那五支钥匙抢来，启动营地里的五块军团方尖塔。方尖塔的作用时间很短，所以你要尽量同时启动它们。记住，怒火守卫不是只会看守钥匙的简单人物。', '杀死厄运传令者。', '好消息，这真是个好消息，$N。我无法要求一个更好的结局了。我们的人民非常感谢你的付出;请从下列这些给英雄物品当中选择一样吧。$B$B你的名字将永远留在我们人民的心中。', '你想被我加入可派去送死的士兵名单吗?拿到那些钥匙然后杀死末日哀嚎者!', '', '去刀锋山找常青林的荒野之王安塔里恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10822, '单枚日怒徽记', '', '', '占星者胜利!凯尔的力量很快就会粉碎。', '即使是最小的贡献也会被注意到，$N。我们的敌人很多，但是我们将战胜他们!', '', '去找影月谷的战斗法师弗亚拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10823, '更多日怒徽记', '', '', '太棒了!这样就可以让凯尔萨斯知道不要低估我们的力量。', '你最近为我们做了什么，$N?对凯尔萨斯的战争是不会自己开始的，你知道吗?', '', '去找影月谷的战斗法师弗亚拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10824, '日怒徽记', '凯尔萨斯疯狂地扩充兵力，占星者的生存面临着危机。来自奎尔萨拉斯的血精灵不断加入凯尔萨斯的部队，为他赢得这场战争添加筹码。他的兵力越雄厚，获胜的希望就越大。$B$B但是，我们的新兵数量堪忧。向占星者证明你的价值吧，转至西边的日蚀岗哨和东北方的卡拉波废墟，消灭那些与凯尔萨斯和伊利丹结盟的高阶血精灵，将他们佩戴的日怒徽记带回来给我。', '将10枚日怒徽记交给群星圣殿的战斗法师弗亚拉。$B$B为占星者完成任务会使你在奥尔多阵营中的声望等级降低。', '凯尔的精灵极其训练有素。做的好。', '继续，$N。说吧。', '', '去影月谷找群星圣殿的战斗法师弗亚拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10825, '神秘的宝珠', '这枚不同寻常的神秘宝珠是从鸦人身上掉落出来的。$B$B它散发出一股奇异的紫色光芒，内部似乎还有着什么东西跳动的声音。将它捧在手中时，你立刻感到略微的不适，所以你赶紧将它放进了背包里。$B$B或许卢安荒野的护树者查恩会有兴趣研究一下这枚宝珠，你决定立刻向西穿过隧道和龙颅之桥，前去见他。', '将格里施纳宝珠交给刀锋山卢安荒野的护树者查恩。', '是的，你手里拿着的是那个宝珠!奇怪，它看起来是阿拉卡的设计。你最近是在葛瑞许纳什吗?$B$B好吧，那解释了一切，但我怀疑这物体有着什么残忍的意图。虽然它散发出邪恶，但也彷佛觉得它连接着自然界。$B$B来，让我试着启动它。它里面的邪恶如此强大，这里有着某种残馀记忆……', '$C，你感觉到了吗?我感觉到附近有反常和邪恶的东西。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10826, '萨格拉斯印记', '现在你应该早已明白为什么我们要与燃烧军团及其爪牙为敌了吧。$B$B如果你想向奥尔多证明自己的价值，就转至西边的军团要塞和死亡熔炉，消灭燃烧军团的高阶将士和暗影议会的爪牙们，将他们佩戴的萨格拉斯印记带回来给我。', '将10枚萨格拉斯印记交给影月谷的先驱者萨隆尼。$B$B为奥尔多完成任务会使你在占星者阵营中的声望等级降低。', '你很有勇气，朋友。让大家都知道你是所有牧师的可靠盟友!', '你身上还有我们敌人的印记吗，$N?', '', '去影月谷找沙塔尔祭坛的先驱者萨隆尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10827, '更多萨格拉斯印记', '', '', '继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。', '你佩带了更多我们敌人的徽记了吗，$C?燃烧军团仍是一个威胁，我们将继续在任何我们找到他们的地方追捕他们。', '', '去找影月谷的先驱者萨隆尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10828, '单枚萨格拉斯印记', '', '', '继续证明你的价值，$N。跟圣光的敌人战斗吧，不管他们在哪里;你的行为将获得良好的报酬。', '我愿意收下你身上任何多的印记。别担心;你的行为将受到适当的表扬。', '', '去找影月谷的先驱者萨隆尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10830, '树人的驱魔', '格里施纳让邪恶的柯柯之灵控制了许多叶须古树和石皮古树的思想。$B$B我们必须拯救乌鸦林中所有的树木，不然很快我们就会永远失去它们！$B$B去格里施纳找一些格里施纳鸦人宝珠，将其内蕴涵的魔法能量与恶鸦身上的恐怖绒毛中蕴涵的魔法能量结合起来。$B$B之后，再使用组合而成的驱魔羽毛引出古树身上的柯柯的灵魂，并杀死它，就可以挽救一切了。石皮古树的力量十分强大，恐怕无法被仪式所影响，但只要你能拯救足够多的叶须古树，它们也能得到解放。', '收集5颗格里施纳鸦人宝珠和5根恐怖绒毛，然后将它们合成驱魔羽毛。利用这些羽毛从乌鸦林叶须古树身上召唤出5只柯柯的灵魂，并杀死它们。', '乌鸦林的邪恶势力被铲除了!你能感觉到吗，$N?$B$B你拯救我们和所有周遭的野生生物免于绝对的毁灭，小家伙!$B$B我在我的大树枝里存放了四个魔法戒指以用于这样的场合，当一位$g英雄:女英雄;出现并且做出伟大的行径时。$B$B你就是一名这样的$g英雄:女英雄;!代表乌鸦林的所有生物，我们感谢你。', '居住在树林里的邪恶魔物开始渗入树林里所有属于大自然的生物。$B$B你必须动作快一点，$N，在一切来不及挽回之前!', '', '去刀锋山找乌鸦林的特维布尔。', '为叶须树人驱魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10831, '成为月布裁缝', '如果你对月布裁缝感兴趣的话，我可以教你。月布裁缝在制造原始月布时，消耗同等的材料却能获得两倍于普通裁缝的产量，而且还能学到很多独一无二的图样。你只需要通过一项简单的测试就能成为一名月布裁缝。$B$B你得转至塞纳里奥庇护所，在月亮井中制造一块原始月布样品。我会为你提供所有的材料。完成任务后，将原始月布样品带回来给我。', '在塞纳里奥庇护所的月亮井中将一块魔化灵纹布制造成原始月布样品。将原始月布样品交给沙塔斯城贫民窟的纳丝玛拉·月歌。$B$B*注意！* 你只能选择一种裁缝专精。', '<那斯马拉检验布料，在她手上翻转它。>$B$B这是一个非常好的样本，$N。你会成为一名优秀的月布裁缝师。', '你制作了原始月布样本了吗?', '', '去找沙塔斯城的纳丝玛拉·月歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10832, '成为魔焰裁缝', '如果你对魔焰裁缝的技术感兴趣的话，我可以教你。但我得先提醒你，这可是一项危险的事业。$B$B在虚空风暴制造魔法布会招来强大的虚空怨灵。我需要更多的虚空怨灵精华来研究如何减少这一负面效应。$B$B带上虚空怨灵信标转至虚空风暴，用它召唤虚空怨灵。将虚空怨灵精华带回来给我，我就收你为徒。魔焰裁缝技术在制造魔法布时，消耗同等的材料却能获得两倍于普通裁缝的产量。此外，你还能学到很多独一无二的图样。', '将虚空怨灵精华的样本交给沙塔斯城贫民窟的金吉·斯比维尔。$B$B*注意！* 你只能选择一种裁缝专精。', '<盖吉检验了虚空怨灵精华。>$B$B即使是一个这么小的生物精华样本也散发出力量。或许我误解了正在发生的情况。我们自环境取用能量并未激怒怨灵。相反的，怨灵和环境是一样的东西!$B$B如果你获得任何更进一步的发现，不要犹豫立刻让我知道，现在你已经成为一名魔焰裁缝师。', '你取得虚空怨灵的样本了吗?', '', '去找沙塔斯城的金吉·斯比维尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10833, '成为暗纹裁缝', '暗纹裁缝在制造暗影布时，消耗同等的材料却能获得两倍于普通裁缝的产量，还能学到很多独一无二的图样。$B$B当然，所有的裁缝都能使用暗影祭坛制造暗影布，但是暗影布裁缝与祭坛存在强大的魔法共鸣，能令祭坛的能量发挥到极致。$B$B带上这块深影水晶转至影月谷东部，沿着灵翼平原的灵翼小径一直往南走。影月谷的边缘便是暗影祭坛。在祭坛处使用水晶。', '在暗影祭坛附近使用深影水晶，使你与祭坛产生更强大的魔法共鸣，然后返回沙塔斯城的贫民窟，向安迪恩·达克斯宾复命。$B$B*注意！* 你只能选择一种裁缝专精。', '我能看见你已成功的勘查祭坛了。你身上已有微妙而不可见的差异，但不用怀疑它确实存在。', '你有使用水晶的力量来加深你与暗影祭坛的融合吗?', '', '去找沙塔斯城的安迪恩·达克斯宾。', '增强与暗影祭坛的共鸣', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10834, '“暗眼”格里洛克', '“暗眼”格里洛克将身体的一部分献祭给了黑暗势力，因此获得强大的魔法能力。他失去了一只眼睛，原本眼球的位置被灼烧成可怖的窟窿……他用眼罩遮住了这处背叛者的象征，这眼罩中也是有秘密的。$B$B将格里洛克的眼罩带来给我，$N，我一定会重重奖励你的……', '杀死“暗眼”格里洛克，将格里洛克的眼罩交给断背岗哨的塞萨克。', '啊，是的。就像在战斗中失去一只手或者一条腿的人会常常感觉到他们被切断的四肢，我怀疑葛锐洛克是否仍在他黑暗的梦里抓着他失去的眼睛……$B$B我也会做这个梦，如果我们幸运的话，那或许我会知道是什么驱使葛锐洛克和血之谷兽人屈从于恶魔的。', '血之谷兽人的罪恶没有止境，而且只有他们的破碎之手亲戚可以和他们匹敌。', '', '去地狱火半岛找断背岗哨的塞萨克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10835, '药剂师安东尼维奇', '$N，我就当前针对血环兽人的研究发现写了一份初步报告。我在萨尔玛的同事安东尼维奇一定很想看。他也在研究邪兽人的相关现象……希望能避免这样的悲剧再次降临在我们的兽人盟友身上。$B$B把这份报告书带给他，我会继续研究你带来的血样。运气够好的话，我们就能分析出使邪兽人陷入痛苦之中的真正原因了。', '将阿尔布雷克的发现交给地狱火半岛萨尔玛的药剂师安东尼维奇。', '啊，来自艾柏瑞克的报告吗?非常好。皇家药剂师学会热切地工作想了解地狱火半岛的兽人是如何变成邪兽人的。他们的背叛是不可原谅的……而我们必须保证我们的兽人朋友可永远免于未来的腐败。', '祝你有美好的一天，$N。你在地狱火半岛过的如何?我相信是丰收的……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10836, '攻击龙喉要塞', '我一时半会儿也想不出法子来挽救我的子嗣和配偶。凡人，你得为我争取时间。$B$B转至灵翼平原东部边缘的龙喉要塞，杀掉那里的龙喉兽人。你制造的这场骚乱应该能阻挠他们的计划。$B$B千万小心，部分龙族成员已经被龙喉兽人侵蚀了心智。等待他们的只有死亡。我允许你一并了结他们的性命。', '杀死15名龙喉兽人，然后向飞翔在影月谷灵翼平原上空的奈尔萨拉库复命。$B$B任何龙喉要塞的龙喉兽人都可以。', '做得好，$N。我发现了一个方法可以释放被关在龙喉堡垒里被奴役的龙了。', '你已经完成了吗?我只能希望一切不会太迟……', '', '去影月谷找灵翼平原的奈尔萨拉库。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10837, '转至灵翼浮岛！', '我能将自己的精华注入灵藤水晶，形成魔化灵藤水晶。这种魔化水晶蕴涵的力量足以从龙喉兽人手中释放那些被奴役的虚空幼龙。$B$B转至灵翼浮岛收集灵藤水晶，灵翼浮岛是漂浮在影月谷东南边缘的一座小岛。当你收集到足够的灵藤水晶后就回来向我复命。$B$B$N，当心居住在岛上的龙喉兽人。', '转至灵翼浮岛收集12枚灵藤水晶，然后向飞翔在影月谷灵翼平原上空的奈尔萨拉库复命。', '<奈尔斯阿拉古从你那里拿走水晶。>$B$B我现在将为你准备水晶。', '我需要幽藤水晶。', '', '去影月谷找灵翼平原的奈尔萨拉库。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10838, '恶魔占卜器', '恶魔占卜器已经准备好了。转至地狱火堡垒正后方的地狱火盆地，然后召唤恶魔占卜器。它会以地狱火堡垒为目标开始自动调幅。完成调幅后跟它谈谈，将它告诉你的语句都记录下来，然后将这份手稿给我……$B$B去吧，$N，你千万要做好准备。毫无疑问，地狱火堡垒会侦测到恶魔占卜器的存在，还会派出守卫来消灭它！', '在地狱火盆地使用恶魔占卜器，等待它与地狱火堡垒创建共鸣，然后与恶魔占卜器交谈并获得恶魔占卜器之语。$B$B完成任务后将恶魔占卜器和恶魔占卜器之语一起交给萨尔玛的药剂师安东尼维奇。', '你获得读数了吗?很好 -- 我确信这数据将证明我们的研究无价。我将转达药剂师席莲娜和艾柏瑞克。$B$B你应该感到骄傲，$N。你的力量和英勇是无庸置疑的……与你对部落的奉献一样。', '你弄到读数了吗?你的恶魔占卜器任务成功了吗?', '', '去地狱火半岛找萨尔玛的药剂师安东尼维奇。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10839, '基斯鸦巢：泰罗克黑石', '基斯鸦巢位于难民车队西北方，就在沙塔斯城以南某处隐蔽的小树林中。据说鸦人在这座斯克提斯的属地上创建了一座邪恶的祭坛。想要救赎基斯鸦巢的鸦人，就必须净化这座泰罗克黑石。$B$B对着黑石使用这根净化法杖，它受到过阿达尔的赐福，应该可以净化黑石。出发吧，愿圣光与你同在。', '对基斯鸦巢的泰罗克黑石使用净化之杖，然后向白骨荒野难民车队的基尔利克复命。', '我听到有爆炸。不是用我的耳朵，而是用我的心。$B$B假如神圣纳鲁，阿达欧的触摸不足以救赎阿拉卡，那没有什么可以。未将他们自己交给圣光的那些人只是邪恶的仆人。$B$B他们必须被消灭。', '黑暗围绕我们。你有什么关于迷雾斯奇司的事要说吗?', '尝试净化泰罗克黑石', '去找白骨荒野难民车队的觉醒者基尔利克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10840, '圣光之墓', '在东边焦土之下，掩埋着圣光之墓，那是一处不为人知的死者安息之地。而在我的车队被袭击之前，我正准备去清除游荡在那附近大量邪灵。$B$B但现在，我却得知另外一种邪恶的灵体生物已经完全占据了圣光之墓。那些该死的虚灵居然还开始大肆掠夺很多年以前与那些死者共同安息在陵墓中的宝物。$B$B在我的车队处于困境中时，我绝对不能离开，你是否可以帮忙替我去圣光之墓完成的我的工作呢？', '高阶祭司奥戈鲁要你去圣光之墓，杀死10名虚灵邪术师和10名虚灵掠夺者，然后回到难民车队向他复命。', '在外域的荒野这里，我们很少有英雄来保护我们的权利，但是你已经让他们惧怕了$C。我认为以太族不会很快忘记$N强壮的右臂。', '你消灭了多少以太族?我希望那足够从圣光之墓中将他们驱赶出来。', '', '去白骨荒野找难民车队的高阶祭司奥戈鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10842, '复仇的灵魂', '圣光之墓现在已经被暗影议会所腐蚀了，里面那些死去的德莱尼人的灵魂受到了深入骨髓的诅咒，成为了内心中充满愤怒、困惑，以及对生者之怨念的邪灵。$B$B进入那座墓穴，找到那些悲惨的牺牲品。让他们得到最后的安息。', '高阶祭司奥戈鲁要你去圣光之墓，击败5名复仇的德莱尼。', '你不知道你在这里做了什么$N.你已经将我们这么多人从永恒的黑暗中拯救出来。我能为活着的人做的事很少，而且没有什么东西足以用来感谢你。带走对你有用的东西吧。', '你已经救了我们。我们该怎么感谢你?', '', '转至白骨荒野的难民车队，同那里的高阶祭司奥戈鲁交谈。', '已杀死复仇的德莱尼', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10843, '很久以前……', '很久很久以前，我们就和刀塔食人魔干上了，双方的战争到现在都没有停止过。$B$B在我们猛烈的攻势下，刀塔食人魔节节败退，他们的残余部队不得不退避到刀塔哨站。刀塔哨站位于剃刀山的西南边缘，就在你来时的路上。$B$B我要你去哨站干掉他们的首领诺什·布罗纳特，以此证明你的能力。$B$B让我们看看你有多大能耐！', '杀死刀塔哨站的食人魔首领诺什·布罗纳特。', '<李欧罗克斯以锐利的眼睛打量你，好像要测量你一样。>$B$B葛诺斯.布罗格纳的死是所有摩克纳萨尔的恩惠。这对你是件好事。$B$B让我们看看是否我们能将你高超的本领再提升一些。', '摩克纳萨尔不接受失败，或者找理由。要不就是你消灭敌人，要不就是$g他:她;杀死你!$B$B既然你正站在我面前，你一定已经杀死了葛诺斯.布罗格纳。', '', '去刀锋山找莫克纳萨村的莱欧洛克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10845, '恐惧之翼', '我曾经派了一批猎手前去侦察晶歌山脉，他们回报称水晶附近的虚空幼龙数量急速增长，对我们构成了严重的威胁。$B$B在上一项任务中，你成功地证明了自己是一位出色的杀手；那么现在就让我们瞧瞧你有没有本事干掉一头成年的虚空龙吧。$B$B往南穿越鳞翼岩床之后就是晶歌山脉。进入山脉杀死虚空幼龙之母——恐惧之翼。', '杀死恐惧之翼。', '不?你杀掉魔翼了吗?或许我看错你了，$C。$B$B或许。$B$B尽管如此，你已经杀死我们面对三个最大威胁的首领。那是值得骄傲的事。$B$B我给你一个标记以表我的感谢，但是不让它冲昏了你的脑袋。你仍然不完全了解摩克纳萨尔是什么，而我们可能仍需要你的技能。', '虽然在我眼里你不能更进一步，但是承认你无法胜任杀死美声山脊虚空龙之母的挑战并不羞耻。$B$B那是你要告诉我的吗?', '', '去刀锋山找莫克纳萨村的莱欧洛克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10846, '了解莫克纳萨', '<莱欧洛克斯死死地盯着你，不由令你心生寒意。>$B$B你对莫克纳萨氏族一无所知。我们在夹缝中艰难求生，你能理解吗？$B$B如果你想体会这种感受，就必须经受严酷的生存考验。$B$B村子南边的托格玛洞穴是维克鸦人的地盘。他们将食人魔战俘囚禁在洞穴中，那里也是鸦人首领维克的栖身处。$B$B杀死维克！', '除去维克鸦人的首领维克。', '维克尼尔最不是我们的对手。$B$B所以，你知道怎样杀死一只长得太快的鸟。这不能让你为一个真正的战士。这也无法让你完全了解我们的方式。$B$B但它是一个开始。', '我们有很多敌人。有些是我们选择的，而有些，像是维克尼尔，却不是我们选择的。$B$B不管怎样，我们将杀死他们的所有首领，直到没有一个可以站在我们面前。', '', '去刀锋山找莫克纳萨村的莱欧洛克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10847, '斯克提斯之眼', '斯克提斯弥漫着一股不祥的气息。$B$B恐怖的邪恶力量笼罩了整个鸦人氏族，命运已经露出狰狞的面孔。我们曾滥用黑暗魔法，做了不少坏事。在阿达尔的指引之下，我才了解到圣光的真谛，并由此得到救赎。$B$B泰罗克通过施放了黑暗魔法的宝珠监视斯克提斯的所有属地。从泰罗卡森林北部的里斯克鸦巢和西诺鸦巢偷回宝珠，让我也透过斯克提斯之眼看看泰罗克都在监视些什么。', '将里斯克鸦巢之眼和西诺鸦巢之眼交给沙塔斯城贫民窟的救赎者瑞拉克。', '你的英勇应该被赞扬。司凯堤斯的守护者不愿意舍弃他们的财产。$B$B但是过去的豪壮行为只是现在的微小结果。我们要看看这样的英勇行为在未来是否会坚持下去，因为泰洛克注视着南方。$B$B这些眼睛全部都在看着。', '你回来了，$C。你带来了什么消息?', '', '去找沙塔斯城贫民窟的救赎者瑞拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10848, '哈兹鸦巢：邪恶的幽灵', '哈兹鸦巢是斯克提斯最邪恶的属地。$B$B尽管奥金顿大爆炸将整座村落夷为平地，泰罗克的力量依然侵蚀了游荡在那里的邪灵。转至西边的哈兹鸦巢，消灭那些可悲的幽灵。他们聚集在位于白骨荒野和泰罗卡森林边界的暗影墓穴。$B$B这将是我们向泰罗克和斯克提斯守护者发动的第一轮攻击。', '杀死4只死爪幽魂、4个尖啸幽魂和2只幽灵乌鸦，然后向难民车队的基尔利克复命。', '那些邪恶的灵魂应当受死。他们对其它人会造成的死亡已是足够的理由。$B$B我们不能奢望救回那些在泰洛克掌握之下的人。我们将以圣光的名义给他们毁灭性的一击。', '迷雾瑞汉兹的魔物日渐强大。消灭他们，$r。', '', '去找白骨荒野难民车队的觉醒者基尔利克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10849, '寻找基尔利克', '还有另一位鸦人也选择了背弃泰罗克的道路，那就是觉醒者基尔利克。$B$B在基尔利克看来，泰罗克根本称不上先知，不过是个夸夸其谈的骗子罢了。泰罗克唯一预见到的只有他自己的恶行招致的厄运而已。$B$B基尔利克引领着我们勇敢地逃离了斯克提斯。而在我们转至沙塔斯城寻求圣光的救赎时，他则转至别的属地搭救其它不甘堕落的鸦人。$B$B这封信件讲述了泰罗克通过宝珠监视属地的情况。必须把此事告诉基尔利克！走出沙塔斯城之后，你沿着南边的道路进入白骨荒野，寻找难民车队，就可以找到他。', '将瑞拉克的信件交给白骨荒野难民车队的觉醒者基尔利克。', '里拉的描述令我怵目惊心，旅人。就如你看见商队那边的状况一样，最近泰罗卡森林充满了哀伤与阴郁。', '你长途跋涉替我带来了消息。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10850, '虚空气体燃料', '', '', '恶魔劫夺者的引擎开始发出轰隆声与劈啪声因为你倒错了燃料。', '你打开恶魔劫夺者倒入燃料的盖子。', '', '去虚空风暴找未激活的魔能机甲。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10851, '敌人的图腾', '有些氏族奉行正确的行事之道，以此表达对先祖的尊敬；有些氏族则误入了歧途。$B$B刀塔食人魔总是随身携带着图腾，但他们不是利用图腾来表达对先祖的敬意，而是滥用它们来满足自己的控制欲。$B$B我们应该偷走他们的图腾，因为刀塔食人魔不配拥有哪怕一根图腾！只有我们才能更好地利用它们。$B$B刀塔哨站位于莫克纳萨村以西，就在剃刀山的西南方。杀死刀塔秘术师和刀塔打击者，将他们的图腾带回来给我！', '收集5根刀塔图腾。', '这些看起来像是不错的灵魂聚合品。我们应该可以在它们之中找到一两个图腾可以用在正当的用途上。$B$B事实上，我想到一个使用他们的用途!', '你已经去剑刃岗哨取走他们的图腾了吗?', '', '去刀锋山找莫克纳萨村的唤灵者多戈加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10852, '失踪的伙伴', '我们在这里遇到了大麻烦。一些鸟人趁着夜晚闯了进来，引起了一场大骚乱。太吓人了。都不知道我们什么时候才能继续前进。$B$B而且，我的一些朋友在那次骚乱之后就不见了，我们完全不知道他们在哪。我想，搞不好是是那群可怕的鸟人把他们带到西北边去了。他们现在说不定正被锁在笼子里，说不定，都已经被吃掉了！如果你能去找他们的话，那就再好不过了。说实话，我非常担心他们的安危。', '伊森要你去基斯鸦巢找到12位失踪的伙伴，然后回难民车队向他复命。', '你把我的朋友都找回来了!现在我有玩伴了。谢谢你，$N$G先生:小姐;。$B$B既然我有朋友陪我玩，也许你想要我的其中一个玩具吗?这样你也有东西可以一起玩了。', '我好无聊，没有人可以陪我玩。你找到我的朋友了吗?', '', '去白骨荒野找难民车队的伊森。', '营救儿童', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10853, '召唤灵魂', '我们必须拯救晶歌山脉中的虚空幼龙之灵。$B$B在孵化前，这些虚空幼龙原本是黑龙。$B$B但是当德拉诺世界爆炸时，一股虚空力量席卷了所有生灵，由此产生的副作用改变了黑龙卵。$B$B孵化出的虚空幼龙沦为扭曲的异形生命体，我们要帮助它们恢复以往的平静。$B$B转至晶歌山脉，杀死灵魂召唤图腾附近的虚空幼龙，然后将虚空幼龙之灵带回来。', '利用灵魂召唤图腾收集8个规模虚空幼龙之灵。', '你今天做了一件好事，$C。那些龙的灵魂现在可以再次忘情的高歌因为他们已经自由了。而他们灵魂遗留在那边的剩馀部份也是一种效力强大的药材。$B$B我在想，你愿意去北边一趟吗?我对那边的某样东西很好奇但是牵涉到以太族在那边的活动。$B$B我感到一股巨大的痛苦感觉从那个方向传来。', '美声山脊的那些龙也许对我们是一种威胁，但是我想他们是崇高的生物。$B$B或者说，至少他们曾经是如此。我希望你可以拯救他们的灵魂。$B$B假如你需要更多的图腾，我还有多的可以给你。', '', '去刀锋山找莫克纳萨村的唤灵者多戈加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10854, '奈尔萨拉库之力', '带上魔化灵藤水晶返回龙喉要塞。寻找被奴役的虚空幼龙，然后释放灵藤水晶中的魔法能量。我的精华将喷涌而出，帮助幼龙挣脱束缚。幼龙受尽折磨必定相当虚弱，你得帮它打败龙喉兽人！$B$B$N，解救被奴役的虚空幼龙，然后向我复命。', '解救5只被奴役的灵翼幼龙，然后向飞翔在影月谷灵翼平原上空的奈尔萨拉库复命。', '<奈尔斯阿拉古大笑。>$B$B那些兽人一定很惊讶那些龙以这种方式反噬他们。做的好，$N。也许你是我们龙族的英雄。', '别浪费时间，我们还有很多事情要做!', '', '去影月谷找灵翼平原的奈尔萨拉库。', '解救被奴役的灵翼幼龙', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10855, '魔能机甲？不了，谢谢！', '对，没错，魔能机甲！它无疑是燃烧军团所造出的最可怕的机械生物。情报显示，燃烧军团准备投入三台魔能机甲对风暴尖塔发动攻击。$B$B幸运的是，他们还没有启动这些机甲。我们可以趁机搞点破坏，而不用与这些机械怪物硬碰硬地死磕。$B$B转至铸魔基地：湮灭，从甘尔葛机械师手中夺得浓缩灵能瓦斯，然后将其注入魔能机甲的燃料箱中。我相信机甲的引擎根本无法承受这种烈性燃料。', '从风暴尖塔西北方的铸魔基地：湮灭里的甘尔葛机械师身上收集5份浓缩的虚空气体，将它们灌入附近一台未激活的魔能机甲内。完成任务后向虚空猎手纳乌希思复命。', '这真是好消息，$N。现在我们已经知道怎么对付这些东西，我就可以派人去破坏剩下的劫夺者了。', '你已经试过我的小实验了吗，$N?', '', '去虚空风暴找风暴尖塔的虚空猎手纳乌希思。', '', '摧毁未激活的魔能机甲', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10856, '最好的防御', '破坏敌人的机械生物只能略微改善我们所处的窘境，$N。铸魔基地：湮灭是燃烧军团装配魔能机甲的集结点，铸魔基地：炼狱则是军团的主营地，他们在那里架设了大量的传送装置。$B$B我要你转至铸魔营地：炼狱，削减恶魔军队的数量。那里驻扎着整编的天罚使者军团，我们不能容忍这支部队的存在。', '虚空猎手纳乌希思要你转至风暴尖塔以北的铸魔基地：炼狱，消灭12名天罚使者。', '做得好，$N。继续加油我就会在节点亲王面前替你美言几句。', '进行的如何?你有机会教训一下那些燃烧军团吗?', '', '去虚空风暴找风暴尖塔的虚空猎手纳乌希思。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10857, '传送这个看看！', '或许你觉得斩杀恶魔很有意思，但是燃烧军团总是能通过传送装置迅速补充兵力，因此我们必须破坏他们的传送装置，才能一劳永逸地解决问题。$B$B可惜我这里没有高性能的爆炸物……但是我们可以向看守传送装置的莫尔葛恶魔“借”。$B$B带上这根魔杖……它可以扰乱莫尔葛恶魔脑波的频率。返回铸魔基地：炼狱，对莫尔葛恶魔使用魔杖。它的控制时间不会太长，你必须利用这段时间对传送装置使用莫尔葛的爆破能力。', '虚空猎手纳乌希思要你转至铸魔基地：炼狱，对莫尔葛恶魔使用精神干涉魔杖，然后对铸魔基地内的三处传送装置使用他们的引爆传送器能力。', '感谢你，$N，我可以呼吸地容易一点了。这当然是个比喻!$B$B我想你现在应该想要一些报酬。', '你成功了吗?传送器已经被摧毁了吗?', '', '去虚空风暴找风暴尖塔的虚空猎手纳乌希思。', '摧毁西部传送器', '摧毁中部传送器', '摧毁东部传送器', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10859, '收集光球', '拉扎安虚灵拥有一些奇怪的装置，能发射出细小的粉红色光球，它们总是让我联想到灵魂。$B$B这种光球与虚灵死亡时体内迸发出的巨大的黄色光球截然不同。$B$B我要你转至北边的拉扎安码头，利用图腾收集到一些粉红色光球。$B$B将它们带回来，这样我或许就能知道这到底是什么东西了。', '唤灵者多戈加尔要你利用宝珠收集图腾收集15颗拉扎安光球。', '有些事情不太对劲。$B$B拜托，$N，把那些图腾交给我。我必须检查那些光球!', '你已经收集完毕所需的雷森光球了吗?', '', '去刀锋山找莫克纳萨村的唤灵者多戈加尔。', '收集扎拉安光球', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10860, '莫克纳萨的美味', '你饿吗，$r？只有善于自助的人才能得到魂灵的眷顾。如果你想享受美餐，那就听好了——这世上不会有免费的东西，美味佳肴也是如此！$B$B剃刀山的迅猛龙以及鳞翼岩床的鳞翼蛇是制作两道佳肴的主料。给我带一些迅猛龙肋排和蛇肉回来，我就为你烹饪美食。$B$B如果你办事够利索的话，我甚至可以教你怎么制作这两道菜。', '收集3根迅猛龙肋排和3块蛇肉。', '嗯，我已经可以想象它们的味道了。快，把材料交给我……我要把它们切好拿去烤!$B$B你很幸运，这种东西可以保存很久，我的意思是很久!那么，这些给你，而且你还这么好心的帮我的储藏室补货我想你也应该得到它的食谱。', '你已经找齐了所有的材料了吗?讲到这里我都快流口水了!', '', '去刀锋山找莫克纳萨村的瓦拉伊。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10861, '雷希鸦巢：先发制人', '西南方的雷希鸦巢是斯克提斯的属地之一，泰罗克的爪牙企图在鸦人幼雏孵化之前就令他们堕落。雷希鸦巢的黑暗巫师们对那些尚未孵化的蛋施加了暗影诅咒，一旦幼雏破壳而出，就会对泰罗克唯命是从。$B$B你现在立刻转至雷希鸦巢，在诅咒生效之前打破鸟蛋。如果为时已晚的话，你可以杀掉那些邪恶的雏鸟。$B$B要记住，圣光在黑暗中最为耀眼。', '打破雷希鸦巢中被诅咒的鸟蛋。解救3只雏鸟，并杀死3只邪恶的雏鸟，然后向难民车队的基尔利克复命。', '解决某人的幼鸟是件残忍的工作，然而忽视酝酿中的邪恶也是一件可怕的事情。你已经做得很好了。阿达欧的恩惠照亮在你的心上。', '你完成你的命令了吗?在太迟之前毁掉恶魔!', '', '去找白骨荒野难民车队的觉醒者基尔利克。', '救赎雏鸟', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10864, '收集灵魂', '我有一种分析邪恶魔法的设备，叫作恶魔占卜器。我想让你使用它进行分析工作，但在那之前……你必须先取悦它。你看，这里面囚禁着一个具备高度智慧的生物，它的需求……怎么说呢……很古怪。$B$B要想取悦它，你就得杀兽人，而且还必须是碎手兽人。占卜器想要他们的灵魂。$B$B收割到足够的灵魂后再回来找我。地狱火堡垒北边、南边以及堡垒周围都有碎手兽人。', '杀死20个碎手兽人，然后向萨尔玛的药剂师安东尼维奇复命。', '做得好，$N。你的灵魂背负着许多亡魂……现在恶魔占卜器将会执行你的命令。$B$B让我们希望你可以准备好迎接下一个考验……', '恶魔占卜器还没有缓和下来，$N。当你收集足够的破碎之手兽人灵魂就回来找我。', '', '去地狱火半岛找萨尔玛的药剂师安东尼维奇。', '收割碎手之魂', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10866, '疲惫的祖鲁希德', '他蛰伏在我的思想里。等待我崩溃的那一刻……要我屈服于他的意志。$B$B他的死期到了。我要呼唤他，告诉他我愿意俯首听令。你必须趁他现身之际杀掉这个家伙，拿到钥匙！$B$B祖鲁希德是位兽人长者，拥有深不可测的强大力量，他必定得到了伊利丹的力量。你是在用生命做赌注，你真的愿意做这样大的牺牲吗？', '杀死疲惫的祖鲁希德，取回祖鲁希德的钥匙，并用它打开祖鲁希德的锁链，释放卡瑞纳库。', '我自由了!你已经拯救了我们了，$N!', '<凯瑞纳古呻吟着。>', '', '去影月谷找龙喉要塞的卡瑞纳库。', '解救卡瑞纳库', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10867, '只有一个办法', '只有一个办法能阻止他们……阻止他们亵渎莫克纳萨氏族先祖的灵魂！$B$B愿亡者的灵魂能享受安宁……$N，如果你愿意帮助我们的话，就立即返回拉扎安码头。$B$B杀死拉扎安虚灵，直到他们的首领节点亲王拉扎安露面。从拉扎安手中夺得灵魂之盒，然后将它交给唤灵者多戈加尔！', '夺得灵魂之盒。', '好在那些污秽的以太族还有他们的首\r\n领都死了。我希望有一千个瘟疫降临在他们的同伴身上!$B$B我代表所有的摩克纳萨尔人为你的行为而奖励你，$N!你真是我们之中的一位英雄。$B$B现在让我们把祖先的灵魂在净化火焰中释放吧。', '你完成了吗?我们祖先的灵魂已经安全的从邪恶的以太族手上取回了吗?', '', '去刀锋山找莫克纳萨村的唤灵者多戈加尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10868, '鸦人的战争', '那些鸦人再次偷袭了我们，他们这一次在夜间侵入，行动迅速，而且在我们的主力部队冲出去反击之前就利用黑暗魔法逃走了，甚至还有空利用召唤法阵救走了那些已被我军重创的士兵。但是，如果我们去攻击他们的老巢，他们恐怕就没有办法逃走了。里斯克鸦巢和西诺鸦巢就在北边和东北边。$B$B立刻找到这两个巢穴，消灭尽量多的鸦人。', '顾问菲埃拉要你杀掉14个西诺鸦爪战士和6个西诺巫师，然后返回裂石堡向她复命。', '做得好$C。那些阿拉卡一定会牢牢记住部落力量的可怕之处。', '你杀了多少阿拉卡呢$N?他们有没有逃跑?他们有没有在你横冲直撞的杀进他们营地的时候吓得躲躲藏藏呢?', '', '去泰罗卡森林找裂石堡的顾问菲埃拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10869, '剿灭鸦人', '那群该死的鸦人再次攻击了我们。这一次他们趁着天黑进行袭击，然后趁我们集结军队反攻之前，利用他们的黑暗魔法逃走了。$B$B我要你立刻转至北边的里斯克鸦巢和西边的西诺鸦巢，到那里去干掉里面的所有鸦人。他们看来对我们完全没有任何畏惧之意，所以我们至少要削弱他们的力量，若能震慑到他们，则更好。', '加维·砂锤中尉要你杀掉14个西诺鸦爪战士和6个西诺巫师，然后返回奥蕾莉亚要塞向他复命。', '做得好$C。那些阿拉卡一定会牢牢记住联盟力量的可怕之处。', '你杀了多少阿拉卡呢$N?', '', '去泰罗卡森林找奥蕾莉亚要塞的加维·砂锤中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10873, '夜间的绑架', '我们的前哨站不断地遭到各类攻击。几天前的一个晚上，白骨荒野东南边缘灵网山脊一带的蜘蛛甚至也向我们发动了一次突然袭击。它们向我们许多同伴喷射了毒液，然后用蜘蛛网将他们裹起后带走了。一些士兵勇敢地拿起武器抵抗这次攻击，可他们在那些蜘蛛撤退后却也毫无准备地追了上去。$B$B自那以后，我们再也没见过被捉走的人和那些转至追击的士兵。我们希望还有他们都还活着，只是被蜘蛛囚禁了起来。不过，我们的人手已经不多了，无法分兵转至救援。你愿意帮我去寻找我们的同伴吗？', '斥候纳弗林要你去灵网山脊解救6名被网住的沙塔尔战士，然后返回沙塔尔营地向他复命。', '你救回了好多人。我原本以为再也见不到他们了。我们真是太感激你了，$N。', '你找到我们失踪的人了吗?', '', '去白骨荒野找沙塔尔营地的斥候纳弗林。', '解救沙塔尔战士', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10874, '沙拉斯鸦巢：信号火焰', '泰罗克的老巢斯克提斯位于白骨荒野以东，那里的沙拉斯鸦巢是泰罗克势力范围内最难以对付的属地。泰罗克的先遣军就在沙拉斯鸦巢的要塞公然向圣光挑起了战争。$B$B沙拉斯鸦巢的驻军利用复杂的魔法信号火焰与他们的主人传递信息。$r，转至东边的沙拉斯鸦巢熄灭信号火焰。只有阻止沙拉斯鸦巢传递消息，我们才有可能摧毁整个斯克提斯。$B$B但是，现在说这个还为时过早。', '难民车队的基尔利克要你熄灭沙拉斯鸦巢的4簇信号火焰。', '我们看到了受诅咒的烟从这边升起。你真是勇敢的人，$C。', '迷雾撒拉斯必须要被消灭!', '', '去找白骨荒野难民车队的觉醒者基尔利克。', '熄灭蓝玉信号火焰', '熄灭翡翠信号火焰', '熄灭紫罗兰信号火焰', '熄灭血石信号火焰');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10876, '城墙之底', '指挥官戈拉克斯正在地狱火堡垒外训练碎手军官，要把这些军官磨砺成最嗜血的利刃。你必须杀死他，$N。失去他对邪兽人来说将是一次非常沉重的打击。$B$B但是，光杀死他还不够。$B$B你把这面旗子带上，到时候别忘了插在他旁边。戈拉克斯的上级——卡加斯之手——如果还流淌有哪怕一滴真正的兽人之血，那么他就一定会接受你的挑战！$B$B卡加斯之手的徽记，就是我想要的东西。', '杀死指挥官戈拉克斯，将部落的挑战插在他旁边。然后杀死卡加斯之手，将卡加斯之手的徽记交给萨尔玛的纳兹格雷尔。', '你已经完成了一个伟大功绩，$N。邪兽人是所有正统兽人的耻辱。假如有事物让我们感到畏惧的话，那就是担心我们会再一次屈服在恶魔的手下。因此你知道，我们对抗邪兽人的战争不只是单纯的跟凶猛的敌人战斗-同时也是对抗我们自己的战斗。$B$B有了力量，你再次展现的力量，这场战争我们会赢。', '你已经挑战卡加斯之手了吗，$N?', '', '去地狱火半岛找萨尔玛的纳兹格雷尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10877, '恐怖圣物', '很久以前，有一支车队奉命转至奥金顿古老的墓穴中寻找恐怖圣物。找到圣物之后，他们被那强大的力量吓得逃走了，但圣物却仍然毁灭了他们。那个圣物中蕴涵着邪恶的力量，一旦被触碰就能召唤出强大的妖魔。后来，他们所有人都死在了篷车旁，就在这里向东的某个地方。$B$B不过，这个黑暗的神器却是击败那只飘荡在白骨荒野上的受诅者泰里布斯的关键之物。如果你愿意的话，就帮我把它找回来，要小心，你的生命，甚至是你的灵魂都将面临危险。', '沃尔昆要你去东边被遗弃的篷车找回恐怖圣物。任务完成后向沃尔昆复命。', '你能成功回来真是不可思议。恐怖圣物比我所担心的还要强大。只有一个强而有力的英雄才能在运送如此亵渎的邪恶遗物时撑过如此长的旅途。', '你已经取得恐怖圣物了吗?我们必须拥有它。', '', '去白骨荒野找沙塔尔营地的沃尔昆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10878, '黑暗前夕', '我们的车队遭到暗影议会秘教信徒的袭击之后，派遣了一位斥候来到沙塔斯城寻求帮助。可是，这里的卫兵却认为我们现在已经安全了，他们完全低估了那些疯子。$B$B总之，我们绝对会被这些秘教新兵在半夜里割破喉咙。所以，你最好能在他们来攻击我们之前把他们解决掉。$B$B在南边的奥金顿北门就能找到那些袭击者。', '难民车队的米克达要你消灭8名秘教散兵，4名秘教织法者和2名秘教新兵。', '现在我可以松一口气了，$N。暗影议会暂时无法伤害我们了。$B$B他们是凶手也是胆小鬼，而你的英勇行径将会使他们退回海湾边。', '你已经完成我的要求了吗，$N?我担心我们的生命安全。', '', '去白骨荒野找难民车队的米克达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10879, '斯克提斯的攻势', '斯克提斯对我们发动了攻击！你召集到足够的盟友守护沙塔斯城了吗？$B$B阻止他们的攻击！', '击败入侵者，然后与瑞拉克谈一谈。', '让我为你在战斗中的英勇行径鼓掌，$C。你已经证明你是一个真正的圣光防卫者。希望阿达欧的祝福会在你最无助的时候帮助你。$B$B但是你看地平线的远处，乌云笼罩着司凯堤斯。泰洛克肯定在策划他的下一个行动。沙塔斯城已经暂时安全了。但是要等到明天才能知道什么样的恐惧会突然袭击我们。', '现在不是闲聊的时候，$N。我们已经被攻击了!阻止那些侵略者!', '抵挡进攻', '去找沙塔斯城贫民窟的救赎者瑞拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10880, '秘教的命令', '这封信上印有一个黑色的图章，尽管它所使用的语言你可以理解，但似乎仍然使用了某些暗语。$B$B或许难民车队里有人能读得懂这封信。', '将秘教的命令交给泰罗卡森林难民车队的米克达。', '哦，对了……这是用暗影密码的基本型式所写成的。我对它的了解还不够完美但是应该足够翻译这封信。$B$B当你住在贫民窟的难民还有流放者当中你就会学到不少这种不正当的知识。', '你想给我看什么东西吗，$N?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10881, '暗影墓穴', '许多人认为是暗影议会制造了爆炸使得奥金顿被炸得粉碎。根据这个传说所说，他们唤醒了居住在奥金顿里的一个非常邪恶的存在。$B$B如果传闻是真的，那个恶魔一定与他们发生了激烈的战斗。根据这份命令所述，一些暗影议会成员逃离了奥金顿，并将许多圣物藏在了暗影墓穴。$B$B这其中，有三件圣物是非常强大的，它们是伟大的祖先阿鲁内、克埃林和阿塔洛的遗物。我要你去把它们找回来。', '进入难民车队西边的暗影墓穴，找回阿鲁内的披风、克埃林的木槌和阿塔洛的卷轴。任务完成后返回难民车队向米克达复命。', '也许圣光已经忘了我，但是我从未忘记圣光。这些遗物对我的同胞来说曾经是神圣的。$B$B让暗影议会将它们的力量使用在邪恶的行为上是……无法想象的!', '你已经取得那些遗物了吗，$N?我们不能允许暗影议会使用它们的力量来从事邪恶的行为。', '', '去白骨荒野找难民车队的米克达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10882, '末日的预言者', '<阿达尔发出的乐声中突然搀杂了几个“不悦的”重音。>$B$B凯尔萨斯王子的典狱官真是蹩脚，被关押在禁魔监狱的怪物已经挣脱了束缚。$B$B其中有一个名叫预言者斯克瑞斯的，这位上古之神的仆从妄图实现他主人那征服世界的狂想。$B$B你必须阻止他逃出禁魔监狱，$N。进入风暴要塞的禁魔监狱，杀死预言者斯克瑞斯，阻止事态的进一步恶化！', '进入风暴要塞的禁魔监狱，杀死预言者斯克瑞斯。完成任务后返回沙塔斯城的圣光广场，向阿达尔复命。', '<阿达欧清晰的语调中带着一种安祥平静的旋律，使你听起来跟上次的对话大不相同。>$B$B你再一次的展现了你的勇气。假如预言者斯克瑞斯得到自由，数不清的数以万计生命将会在接踵而来的战争冲突中丧失性命，就好像上古诸神在艾泽拉斯的另一个仆人斯克拉姆一样。$B$B$N，我给你的报酬也许跟你的贡献比起来是非常微小的，但是你要知道上面包含了我们沙塔尔永恒的感激。', '<阿达欧将注意力放在你身上，他的凝视使你几乎无法忍受。>$B$B$N，也许你不了解你的任务的重要性?已经没有时间可以浪费了……召集你的队友一起进入禁魔监狱。$B$B结束预言者斯克瑞斯的生命吧。', '', '去沙塔斯城找贫民窟的阿达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10884, '纳鲁的试炼：仁慈', '想要证明你自己拥有获得风暴钥匙的资格，你必须首先完成四个试炼。$B$B近日里，有三名你的同族被囚禁在地狱火堡垒的破碎大厅中。他们被残忍无情的卡加斯·拳刃所逮捕，很快就要被他以展示力量与气概为由处死。你必须在这场暴行发生之前将这些可怜的囚徒拯救出来。你要带回刽子手还未来得及使用的斩首斧作为证据。斧刃上不能有一滴鲜血存在！', '沙塔斯城的阿达尔要求你从地狱火堡垒的破碎大厅中取回未使用的刽子手之斧。$B$B该任务必须在英雄等级难度的地下城中完成。', '做得好，$N。你已经通过宽容的试炼。', '<阿达欧问候你。>', '', '去沙塔斯城找贫民窟的阿达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10885, '纳鲁的试炼：力量', '想要证明你自己拥有获得风暴钥匙的资格，你必须首先完成四个试炼。$B$B力量的试炼将被分为两部分。你必须摧毁盘牙水库蒸汽地窟的首领，督军卡利瑟里斯，并带回他的三叉戟。此外，你还要杀死躲藏在奥金顿暗影迷宫中的外位面生物摩摩尔，并把他的精华给我带回来。$B$B完成了这些，你就通过了力量之试炼。', '沙塔斯城的阿达尔要求你取回卡利瑟里斯的三叉戟和摩摩尔的精华。$B$B该任务必须在英雄等级难度的地下城中完成。', '做得好，$N。你已经通过力量的试炼。', '<阿达欧问候你。>', '', '去沙塔斯城找贫民窟的阿达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10886, '纳鲁的试炼：坚韧', '想要证明你自己拥有获得风暴钥匙的资格，你必须首先完成四个试炼。$B$B在我们长年的位面旅行中，我们遭遇过许多危险的存在。其中，有一部分这样的生物被我们囚禁在了风暴要塞的禁魔监狱里。$B$B其中，有一名囚徒却是个无辜的牺牲品。他是一个在错误的时间登上错误飞船的偷渡者。$B$B立刻转至禁魔监狱，救出侏儒米尔豪斯·法力风暴。确保他活着出来。', '沙塔斯城的阿达尔要求你从风暴要塞的禁魔监狱中救出米尔豪斯·法力风暴。$B$B该任务必须在英雄等级难度的地下城中完成。', '做得好，$N。你已经通过坚毅的试炼。', '<阿达欧问候你。>', '营救米尔豪斯·法力风暴', '去沙塔斯城找贫民窟的阿达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10887, '逃离墓穴', '我很感激你的帮助，$N。我还以为我会被杀掉呢。$B$B不过，现在我们得赶紧离开这里了，用不了多久就会有更多的秘会教徒来追捕我们。', '帮助阿库诺回到泰罗卡森林的难民车队。任务完成后与米克达谈一谈。', '你救了我的好朋友，阿库诺。因此我欠你人情，$N。', '嗯，$N?', '', '去白骨荒野找难民车队的米克达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10888, '纳鲁的试炼：玛瑟里顿', '想要证明你自己拥有获得风暴钥匙的资格，你必须首先完成四个试炼。$B$B现在，你只需要跨越最后一个障碍了，凡人。聚集一支军队，转至地狱火堡垒深处，在玛瑟里顿的巢穴中杀出一条血路，进入中央的密室，杀死那个邪恶的腐蚀者！', '沙塔斯城的阿达尔要求你杀死玛瑟里顿。', '你已经证明了你是拥有强大力量的人。纳鲁赞同你……', '<阿达欧问候你。>', '', '去沙塔斯城找贫民窟的阿达尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10893, '德莱卡·长尾', '那些黑翼拜龙教徒彻底占据了隧道，我们面临的情况越来越严峻了。坦白地讲，他们人数太多了。$B$B尽管我们当前还能应付他们小规模的进犯，但如果对方全力认真进攻这里的话，我们几乎无法对他们造成任何阻碍。$B$B当前的状况要求我们必须选出一个人，穿越隧道到另一边去，刺杀他们的领袖德莱卡·长尾。你愿意成为这个人吗？', '消灭龙颅小径内的拜龙教领袖德莱卡·长尾。', '由于德拉卡已被解决，我们应该可以利用现在的情势。他们将会彼此争夺看谁能掌权，这将会减轻一些压力。$B$B那就是，除非在你给我的笔记中提到的监督者出来取代她的位置。$B$B让我们看看是否你能做点什么保证那绝不会发生!', '她死了吗?$B$B$N，如果我们在这里有作战机会，我们需要你透过杀死德拉卡.长尾让他们乱成一团!', '', '去刀锋山找鲜血之环的观察者希德·月影。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10894, '龙颅观察者', '嗯嗯，我也不是很清楚我们现在该做些什么。我并不擅长制订军事计划。$B$B但观察者希德·月影一定知道该怎么做。他正在龙颅之桥以西的龙颅小径一带领导着那里的防御力量。事实上，我们在那边驻扎了一支守备部队，以防拜龙教采取什么行动。$B$B拜托你了，把这张便笺立刻送给他。', '将会议记录交给刀锋山龙颅小径入口附近的观察者希德·月影。', '就跟我想的一样，那样并不好!$B$B我想到一个方法可以帮助你，但是首先，我在想你可以帮助我们吗?$B$B人人为我，我为人人。', '我可以帮你什么?你是从永恒树林带消息来吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10895, '燃烧吧，塞斯高！', '现在是对塞斯高展开空中打击的时候了！我们的狮鹫骑士已经准备妥当，随时可以出击，$n。但他们需要有人在地上指引他们的火力。你能完成这个任务吗？$B$B把这些烟雾信标带去西边血环氏族的据点塞斯高。他们拥有四座哨塔：一座靠近北墙，一座靠近南墙，还有一座在熔炉边上，而最后一座在小山丘上。将这些烟雾信标放在哨塔下面，这样我们就能俯冲轰炸它们了！', '将烟雾信标放置在塞斯高的四座哨塔下，然后向远征军岗哨的空军指挥官达比利复命。', '我能看见这里的烟和火焰!做得好，$N!我们狮鹫骑士对你的赞扬可不只一两句而已 -- 你刚刚的行为非常勇敢……', '时间紧急，$N。我们需要烧掉那些警卫塔!', '', '去地狱火半岛找远征军岗哨的空军指挥官达比利。', '标记北部哨塔', '标记南部哨塔', '标记熔炉哨塔', '标记丘陵哨塔');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10896, '被感染的保卫者', '这片土地上的所有树木都已经被奥金顿释放出来的能量破坏掉了，那股恶魔能量亵渎与腐蚀了周围的环境，将茂密的森林变成了现在你眼中的这片废土。而那些存活下来的树木，现在正遭受着木螨的侵扰，它们在树皮下蠕动，啃咬着树木的躯干。$B$B东北侧林地边缘的那些腐烂的森林愤怒者和被感染的根须漫步者身上都有木螨滋生。杀掉那些怪物，然后再杀掉从它们身上掉下来的木螨。', '拉库泰要你杀掉25只木螨，然后返回难民车队向他复命。在腐烂的森林愤怒者和被感染的根须漫步者身上都可以找到木螨。', '你已经做了非常多来帮助泰罗卡森林，$N。在蚀木虫群最糟的破坏后，我们尚能恢复这块荒地。', '你消灭了最坏的侵扰了吗?', '', '去白骨荒野找难民车队的拉库泰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10897, '药水大师', '炼金师可以利用不同植物的药效，配制出恢复力量和生命的药水。$B$B我熟悉外域中的所有植物，可以教会炼金师们如何有效得利用它们。如果你对此感兴趣的话，我有一项任务要交给你。$B$B据说风暴要塞的高级植物学家弗雷温着有一本内容全面的植物学指南。将它和你配制的药水样本一同带回来给我，我就教给你想学的东西。', '劳兰娜·萨维尔要你转至风暴要塞的生态船，从高级植物学家弗雷温手中夺得植物学家的指南。此外，将5瓶超级治疗药水、5瓶超级法力药水和5瓶特效无梦睡眠药水一并交给她。$B$B*注意！* 你只能选择一种炼金术专精。', '太好了!看起来你渴望着学习，那就让我们开始吧。我将教你怎样让你用在炼金术药水里的植物起最大效用。$B$B你将发现如果你知道你正做什么，你能使药草拥有很大的用途。有时候，你能以一份药水的材料做出两罐药水。', '你确定要这么做吗，$N?专精于药水将使你无法专精于其它领域。', '', '去赞加沼泽找塞纳里奥庇护所的劳兰娜·萨维尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10898, '天空之翼', '天空之翼在你周围绕来绕去。$b$b你觉得他是想让你跟着他走。', '护送天空之翼，完成之后向沙塔斯城的救赎者瑞拉克报告。', '哎呀，可怜的天翼处在『禁锢者』卢安卡可怕的诅咒之下!$B$B天翼转至迷雾撒拉斯试图说服其它人正视圣光的道路。他们并未轻视他的行动，特别是坐在司凯堤斯的门阶上。$B$B卢安卡是泰洛克最惧怕的密探之一。你已经释放了天翼，做得好!我感谢你。', '你为什么而来呢?', '护送天空之翼', '去找沙塔斯城贫民窟的救赎者瑞拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10899, '转化大师', '很多炼金师都会告诉你，物质具有延展性和可塑性，它能从一种形态转化为另一种形态——在转化的过程中遵循能量守恒的原理，没有创造，也没有湮灭。为了得到某样东西，就需要付出同等的代价，这就是炼金术的等价交换原则，我们曾将此奉为世界的真理。$B$B但是精通物质转化的大师可以从等价交换的原则中解放，而我可以教给你这种方法！$B$B想要成为转化大师，就必须了解源生之能这种由各种源生材料聚合而成的物质。只要你能证明自己的转化能力，我就与你分享我的知识。', '虚空风暴风暴尖塔的萨雷维要你给他带去4份源生之能。$B$B*注意！* 你只能选择一种炼金术专精。', '做得好，$N!你的转化能力真是无可挑剔!$B$B我现在将教你炼金术转化过程中利用空气转化物品的方法!充分利用你的知识，转化大师。$B$B现在，如果你不介意，我必须去见一个对原始的力量感兴趣的买家。', '你确定要成为一名转化大师?假如你专精在这个领域的话就不能专精在药水或者药剂上。', '', '去虚空风暴找风暴尖塔的萨雷维。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10901, '卡达什圣杖', '将制作圣杖所需的元素徽记给我带回来！$B$B土灵徽记在屠龙者格鲁尔手中，他就躲在刀锋山的巢穴里。$B$B另一枚徽记是夜之魇的心脏，据说这只神秘的野兽居住在先知麦迪文的高塔内。$B$B迅速行动吧！', '将土灵徽记和灿烂徽记交给盘牙水库奴隶围栏的异教徒斯卡希斯。', '终于!$B$B挣脱了这些束缚，斗棍也重回我的身边，我就可以把那个深海女巫送回冰冷的深渊去…', '用这根重组过的斗棍，我将挣脱我的束缚并且返回毒蛇神殿向瓦许和她的爪牙报仇!', '', '去盘牙水库找奴隶围栏的异教徒斯卡希斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10902, '药剂大师', '我几乎把毕生心血都投入到精炼药剂的事业中去了。尽管我获得了许多成功，但仍有一个愿望未尽。至今，我还无法制造出永生药剂。$B$B不过，我已经知道我缺少什么材料了。我听说在艾泽拉斯世界有一处地方叫作时光之穴。有许多被称为裂隙领主和裂隙守卫者的怪物会在那里切入和切出时间线。$B$B这样频繁的切入和切出时光会让时光之河本身流出眼泪，最终将使时光那种无穷尽的特性扭曲并晶体化，形成某种精华。把这种精华和你的工作样本一起带回来，我就会教给你我所知道的一切。', '进入时光之穴的黑色沼泽，从裂隙领主和裂隙守卫者身上获取10份永恒精华。将这些与5瓶特效防御药剂、5瓶掌控药剂和5瓶特效敏捷药剂一起交给沙塔斯城贫民窟中的罗罗基姆。$B$B*注意* 你只能选择一种炼金术专精。', '假如你带来的这些东西是指标的话，那就表示你对药剂很有心得。你将会是个很好的学生。$B$B这些精华将会提供我足够的材料来调配我的配方。我的发现将会使我在所有的炼金师中非常出名!$B$B现在，假如你愿意学习的话，我就愿意教你。', '精华!你已经拿到了吗?', '', '去找沙塔斯城的罗罗基姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10904, '收集邪能炮弹', '我们必须阻止燃烧军团继续利用死亡之门，必须要关闭它。不过，首先得毁掉他们的两道迁跃门才行！$B$B但问题是，我们没有任何摧毁大型设施所需要的工具，所以你必须利用他们自己的武器去对付他们。$B$B那边的死亡之力、死亡注视者、死亡熔炉锻造师，还有死亡熔炉技师的身上都携带有邪能火炮的炮弹。$B$B虽然一般来说没有东西可以摧毁那几道门，但如果你能将这些炮弹带回来给我，我就能在其中灌注入自然的愤怒能量！', '常青林德鲁伊要你收集5枚邪能炮弹。任务完成后，使用德鲁伊信号弹通知刀锋山死亡之门的常青林德鲁伊。', '那些东西比我想象得还要臭!$B$B快一点，把它们交给我，我会让它们充满自然的力量，这样它们就会对它们的恶魔主人和邪恶的创造物造成致命的影响。', '你弄到炮弹了吗?', '', '去刀锋山的死亡之门内用德鲁伊信号弹召唤常青林德鲁伊。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10909, '邪灵', '尤勒斯上校是上次在碎手邪兽人的据点高加兹前哨附近作战时候被诅咒的。我的导师巴拉达正竭尽全力以拯救这位可怜的军官，可他需要帮助。尤勒斯那饱受折磨的灵魂需要平和下来，而让他平和下来的途径……我想，只有复仇这一种了。$B$B将学者的圣物带往高加兹前哨，放置在地上，并将附近的碎手兽人杀死。这样一来，邪兽人体内的邪恶精魂就会被直接释放出来。之后，你必须消灭这些邪恶精魂，这样尤勒斯的灵魂才能复原。', '荣耀堡的克拉图要你在荣耀堡西南方的高加兹前哨使用学者的圣物，杀死圣物附近的碎手狂战士，然后消灭10个被释放的邪灵，为尤勒斯上校复仇。', '破碎之手兽人是邪恶和绝望的，但拯救乔渥上校的道路如此血腥让我的心十分悲伤。', '破碎之手兽人的邪恶灵魂正在逐渐枯萎可怜的乔渥灵魂。告诉我，$N……他的情况已经被缓和了吗?', '', '去地狱火半岛找荣耀堡的助手克拉图。', '为尤勒斯复仇', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10911, '开火！', '现在是你利用自然能量炮弹，摧毁燃烧军团基地的时候了。$B$B死亡之门有两座迁跃门，燃烧军团通过迁跃门召唤扭曲虚空的恶魔，以此强化后援兵力。南北两座迁跃门都在邪能火炮的射程之内。$B$B利用自然能量炮弹控制死亡之门邪能火炮，摧毁南部迁跃门和北部迁跃门。$B$B在火炮的压制下攻击迁跃门，并阻止燃烧军团的防御者破坏邪能火炮。', '利用自然能量炮弹控制死亡之门邪能火炮，摧毁南部迁跃门和北部迁跃门。然后使用德鲁伊信号弹召唤一名常青林德鲁伊，告诉他你已完成任务。', '你的英勇行径真是太了不起了!$B$B很好，摧毁那两座星移门之后，只剩下一件事可以做。', '你已经摧毁那两座星移门了吗?', '', '去刀锋山的死亡之门使用德鲁伊信号弹召唤常青林德鲁伊。', '摧毁南部迁跃门', '摧毁北部迁跃门', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10912, '犬王', '犬王拜尔蒙必须死！他负责主持着令传送门生效的仪式。$B$B死亡之门就在峡谷的最北端，你看到它的时候，也就意味着你找到了拜尔蒙。$B$B带上这根魔杖，它会对你有帮助的。当你与犬王拜尔蒙战斗时，立刻使用它，我的两个朋友就会出现，助你一臂之力。$B$B击败拜尔蒙之后，立刻回去向荒野之王安塔里恩复命。$B$B还有，$N，谢谢你来这里为我们贡献自己的力量。', '杀死犬王拜尔蒙。', '你真棒$r!假如之前我已经认为我们欠了你不少人情，那么现在我们欠你的将更没有办法还清。$B$B但是我们仍然会继续尝试。谢谢你，永恒树林的$g英雄:女英雄;!', '事情已经解决了吗?死亡之门的危机已经解除了吗?', '', '去刀锋山找常青林的荒野之王安塔里恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10913, '不适当的葬礼', '难道没有办法阻止堕落继续发生吗？我的士兵们与奥金尼的士兵交战多日了，到现在还不知道什么时候战争才能结束。可是，每一名死者——不管是奥金尼的士兵还是沙塔尔的士兵——他们的灵魂都被带到了未知的领域。$B$B我绝对不允许这样的事情发生！虽然不能好好地安葬他们，但也绝对不能让那些魔鬼夺走他们的灵魂！带上这个火把到正东边的战场去。烧掉你看到的每一具遗体！我们不能让他们利用这些遗体来进行任何邪恶的祭祀。', '泰罗卡森林白骨荒野沙塔尔前哨站的指挥官拉瓦伊要你焚烧8名被杀死的奥金尼战士和8名被杀死的沙塔尔守备官的遗体。', '<指挥官洛沃双手托住了他的头。>$B$B这样不够……这样是不够的。', '这个问题很难启齿，我知道……', '', '去泰罗卡森林找白骨荒野的指挥官拉瓦伊。', '焚烧被杀死的沙塔尔守备官的尸体', '焚烧被杀死的奥金尼战士的尸体', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10914, '呼唤英雄', '这样还不够，我们需要一位真正的英雄。奥金尼的士兵数量还在源源不断地增加，我们的军队很快就会被彻底被击败。$B$B<指挥官拉瓦伊看着你。>$B$B你是我们所期待的英雄吗？回到战场上去吧，与他们的士兵战斗，让他们的注意力集中到与你的战斗上，这样我的斥候们才能深入敌后去探察他们到底在干些什么。', '泰罗卡森林中白骨荒野沙塔尔前哨站的指挥官拉瓦伊要你消灭12名奥金尼学徒和5名奥金尼厄运预言者。', '你成功了，$N!由于你的帮忙，我们有了新的发现……', '不要留活口!', '', '去泰罗卡森林找白骨荒野的指挥官拉瓦伊。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10915, '死去的主教', '他们偷取这些灵魂是为了把它们填入某个从奥金尼地穴挖出的灵柩中。我的斥候们认为那具灵柩中所容的正是奥金尼地穴第一任大主教的遗体。他们想复活这个古老的家伙！$B$B你必须奋力闯进奥金顿西边，在他们将他复活之前消灭掉一切。跟着那些正向那边走过去的灵魂，你就不会迷路。$B$B听着，无论你在灵柩中看到了什么，都必须毁灭他！', '泰罗卡森林中白骨荒野沙塔尔前哨站的指挥官拉瓦伊要你消灭掉奥金尼棺材里装着的生物。', '胜利是属于我们的!这场战败会让奥奇奈受挫好几个礼拜。', '你必须在那个古老的祸害恢复它的力量之前摧毁它。', '', '去泰罗卡森林找白骨荒野的指挥官拉瓦伊。', '摧毁奥金尼棺材中的生物', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10916, '挖掘念珠', '学者巴拉达计划利用驱魔仪式来破除尤勒斯上校身上的腐蚀，他需要一个助手，一个准备完全的助手……$B$B我不得不尴尬地承认，我把我的念珠在荣耀堡的庭院里搞丢了。我猜应该是那只叫菲菲的小狗把它偷走藏起来了，但我找不到在哪儿。你能与他的主人委任官翠希·普罗维尔谈谈，她应该知道菲菲把它的宝贝都藏在哪里了。', '将德莱尼祈祷念珠交给荣耀堡的助手克拉图。', '你已经找到祈祷珠串了!做得好，$N。你的确是不可思议-前一刻你杀死地狱火半岛的魔物然后下一刻你找到失落的宝物。像你这样的人真会鼓舞他人!$B$B你能找回这些珠串真好……因为它们在接下来的驱魔仪式里面是非常重要的。', '你已经找到祈祷珠串了吗，$N?它们的法力对很多的神圣祭仪都很重要…包括驱邪的祭仪。', '', '去地狱火半岛找荣耀堡的助手克拉图。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10917, '流亡者的交易', '作为一个从故乡被放逐出来的鸦人，我永远也不会忘记斯克提斯的同胞们对我们进行的屠杀。我这一生都无法消除这种恐惧，不过，这并不意味着我不想报复。$B$B我还藏有一些财产，如果你愿意帮我消灭掉那些随时都会来暗杀我的鸦人，我非常乐意将财产分一部分给你。这样吧，你就将居住在泰罗卡森林内的各个鸦巢中的鸦人羽毛给我带回来，以此证明他们的死亡。', '将30片鸦人的羽毛交给沙塔斯城贫民窟的维卡克斯。', '<威卡斯在你向他呈献敌人的遗物时发出欢愉的叫声。>$B$B太好了，这样就可以告诉司凯堤斯我们流亡者不会静静的躺着等他们进攻。这里是我答应要\r\n给你的报酬。我可以安排再多给你一些报酬，只要你帮我拿来更多的羽毛。', '你带着羽毛回来了吗，$N?', '', '去沙塔斯城找贫民窟的维卡克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10918, '更多羽毛', '', '', '<威卡斯在你向他呈献敌人的遗物时发出欢愉的叫声。>$B$B太好了，这样就可以告诉司凯堤斯我们流亡者不会静静的躺着等他们进攻。这里是我答应要给你的报酬。我可以安排再多给你一些报酬，只要你帮我拿来更多的羽毛。', '司凯堤斯的手下仍然在不远的距离监视着我们这些流亡者。现在所有我们在沙塔斯城外的人都离死不远。$B$B帮我带回来更多的羽毛当作你战胜他们的证明。', '', '去沙塔斯城找贫民窟的维卡克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10919, '菲菲的狗粮', '', '', '<菲菲高兴的叫着并且咬起狗饼干。他左看右看……决定他应该把这个新的宝物藏在哪里……>', '菲菲以期待的眼神看着你……', '', '去找地狱火半岛的菲菲。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10920, '复仇之战', '当那些巨牙寡妇蛛攻击前哨站时，我们仿佛听到纳鲁的声音在召唤我们奋起反抗。蜘蛛在夜幕的掩护下逃走时，我们毅然选择追击这些怪物。在黑暗之中，我们发现一部分被捉走的同胞已经被杀死，而且听到了另一部分幸存的人与那些蜘蛛殊死搏斗的声音。$B$B临近天亮时，我们追赶到了这里，与巨牙寡妇蛛群展开了一场激烈的战斗。但是，我们被击败了。我想，不久之后，毒液就会发作，我和同伴们将就此倒在这里。但是，在我永远闭上双眼之前，我必须看到所有的巨牙寡妇蛛都被尽数消灭。', '守备官海雷恩要你杀掉20只巨牙寡妇蛛，然后返回灵网山脊西边向他复命。', '我从这里就可以听见你战斗的声音了，$C。你战胜的声音让我的内心充满了希望。假如你可以在如此渺茫的机会中战胜，也许我可以找到力量将我的同伴们拖离这个险境。', '我可以感觉到毒液在我的血液中流窜。纳鲁在呼唤我，我可以看见引领我的光了。你已经战胜那些惧牙寡妇了吗?', '', '去白骨荒野的灵网山脊边缘找守备官海雷恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10921, '泰罗卡狼蛛', '虽然你已经杀掉了许多的巨牙寡妇蛛，但它们的数量仍在不断增长，很快，它们就能再次形成可以攻击我们的规模。它们的蛛后泰罗卡狼蛛隐藏在灵网山脊深处，就是它繁殖出了这些可恶的怪物。为了我们的安全，必须斩草除根，去把它干掉。', '守备官海雷恩要你杀掉泰罗卡狼蛛，然后返回灵网山脊西边向他复命。', '这些惧牙生物已经被打败了。你已经杀了许多，而且连他们的母亲都在你面前倒下了。我已经中毒太深所以无法以战斗的方式获得自由。$B$B请从我的装备中挑几样带走吧。这样可以减轻我的负担而且提供你转至沙塔尔前哨的回程所需的工具。', '你已经杀死泰洛卡狼蛛了吗?', '', '去白骨荒野的灵网山脊外面找守备官海雷恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10922, '挖掘行动', '啊！你看上去是个有点能力的家伙，$r。嘿，你知道么！我和我的队员希望能找到一个护卫，在我们挖掘通向北边的隧道时能保护我们的安全。要知道，报酬相当丰厚哦！而且你要做的，仅仅是确保我和我的同伴们不会被那些可恶的怪物们杀掉，不要你去挖土的！$B$B如果你能顺利地完成任务，保证我们不出任何意外的话，杜瓦弗维兹会给你一大笔钱的！', '护送雷托尔和他的队员，当他们在挖掘时保护他们的安全。任务完成后向沙塔尔前哨站的杜瓦弗维兹复命。', '一只白骨虫!太棒了!这可是历史上头一次首席考古学家里同有了新发现。', '工作完成你就可以领钱了，$g小男孩:小女孩;。', '保护探险家们', '去泰罗卡森林找白骨荒野的杜瓦弗维兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10923, '邪恶临近', '如果想要挑战受诅者泰里布斯，你就必须利用恐怖圣物进行一场邪恶的巫术仪式。在东北方奥金顿的另一侧，有一处聚集有许多通灵师的痛苦之丘。$B$B那里的奥金尼亡语者和奥金尼厄运预言者带有许多毁灭徽记。这种毁灭徽记上附着着力量强大的通灵附魔。如果有足够多的徽记，你就能将它们的力量和恐怖圣物的力量相结合，命令泰里布斯来面对你了。', '沃尔昆要你将恐怖圣物带到痛苦之丘，在那里杀死一些奥金尼亡语者和奥金尼厄运预言者，并收集20个毁灭徽记。然后找到痛苦之丘召唤法阵，利用恐怖圣物召唤出受诅者泰里布斯并杀死它。任务完成后向沃尔昆复命。', '已经从泰洛卡净化了一个巨大的邪恶宿主。沙塔尔欠你一份人情。', '泰洛卡的受诅咒的泰利巴斯已经被净化了吗?', '', '去白骨荒野找沙塔尔营地的沃尔昆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10924, '绝对不可能！', '这片区域中分布着许多迁跃追迹者，它们的血液可用作强效的材料。这种稀有的原料是我这里最畅销的货物之一。$B$B通常我都带上小鬼塞比特外出采集血液。迁跃追迹者的血液具有高度的腐蚀性，对我们来说过于危险，但塞比特就完全没问题。$B$B我要忙着打点店里的生意，根本抽不出时间。你能帮我收集血液吗？塞比特这家伙特别容易走神，杀死追迹者后你要停在尸体旁，让塞比特去干它的活。', '为扳钳镇的萨布奥斯带回8瓶迁跃追迹者之血。', '这些足以提供我大量的需求了。$B$B我希望我的小鬼没有给你太多麻烦。他有张令人讨厌的嘴。', '塞皮有乖乖合作和你一同取得我要的血吗?', '', '去虚空风暴找扳钳镇的萨布奥斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10927, '消灭洞穴蛛', '指挥官萨卡斯·天影希望清除隧道中的障碍，确保我们和营地之间的贸易线畅通无阻。我不得擅离职守，因此希望你能帮我完成这项任务。清除隧道中的障碍后就立即向指挥官萨卡斯·天影报到！', '杀死6只洞穴蛛。', '做得好，$C。那个通道是我们通往那片沼泽的重要路线。$B', 'NULL', '', '去刀锋山找希尔瓦纳的指挥官萨卡斯·天影。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10928, '消灭洞穴蛛', '托查克·双爪希望清除隧道中的障碍，确保我们和沼泽鼠岗哨之间的贸易线畅通无阻。我不得擅离职守，因此希望你能帮我完成这项任务。清除隧道中的障碍后就立即向托查克·双爪报到！', '杀死6只洞穴蛛。', '做得好，$C。那个通道是我们通往那片沼泽的重要路线。$B', 'NULL', '', '去刀锋山找雷神要塞的托查克·双爪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10929, '击鼓', '你愿意再帮我们探险者协会一个忙吗？我们对这些骨虫非常好奇，想要研究研究。$B$B你看，这里有一只鼓，到时候你把它带到白骨荒野去使劲敲，看看会发生什么事情。如果骨虫出现的话，就杀掉它，并且把尸体带回来给我们研究。我们需要很多虫尸的样本，才能更有效地进行试验。', '白骨荒野沙塔尔前哨站的杜瓦弗维兹要你带回8具成年筛骨虫的尸体。', '沙尘地精?对阿，没错……沙漠会对一个人产生奇怪的影响。$B$B我想有了这些虫我们可以有突破性的进展!', '我们认为那只从洞口跳出来的实际上是一只幼虫!', '', '去泰罗卡森林找白骨荒野的杜瓦弗维兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10930, '巨大的骨虫', '我猜得果然没错！你带回来的这些尸体都其实都是幼年的骨虫。你知道这意味着什么吗，这附近肯定有一只成年的骨虫！如果有一些它所喜爱的食物，我们就可以把它引诱出来。让我想想……成年的骨虫！啊！$B$B我想起来了，我过去在东边白骨荒野的另一侧见过一些裂蹄牛。你到那里去杀死一只裂蹄牛。然后，你在一旁敲打这只鼓。希望到时候那只成年的骨虫会出来寻找食物。如果你将它杀掉，记得把它的内脏带回来给我！', '白骨荒野沙塔尔前哨站的杜瓦弗维兹要你找回巨虫的内脏。$B$B他希望你也能把他的虫鼓带回去。', '太神奇了!看看这个器官!这叫阿猫阿狗的东西竟然有某种粉尘在它阿猫阿狗的器官里面。噢!我还是不要用那些科学术语令你厌烦。我倒是从幼虫身上拔出一些牙齿制作这些异常锋利的刀。想要一把吗?', '带个队友一同前去吧!', '', '去泰罗卡森林找白骨荒野的杜瓦弗维兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10935, '尤勒斯的驱魔仪式', '$N，现在我们必须去拯救尤勒斯上校了。他的状况又有恶化，巴拉达担心如果我们还不能净化他身上的腐蚀，他就要永远离开我们了。$B$B拿着这串念珠去找学者巴拉达，马上开始仪式。不要让任何人打扰到仪式的进行……，如果一切顺利，我想尤勒斯上校还是能拯救回来的。他的情况好转之后，和他谈谈，然后再回来找我。', '与学者巴拉达交谈，利用祈祷念珠帮助巴拉达完成仪式。与获救的尤勒斯上校交谈，然后向助手克拉图复命。', '你成功了，$N。你拯救了乔渥上校的灵魂并且将他体内的邪恶驱逐到属于它的地方。这真是一个伟大、高尚的行为!英雄的一天!', '去找隐士巴瑞达，$N。假如想救回上校祭仪就必须成功。', '', '去地狱火半岛找荣耀堡的助手克拉图。', '拯救尤勒斯上校', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10937, '教官祖罗克', '我收到的情报显示，地狱火堡垒内外的所有碎手邪兽人正在严密的组织下准备发动一次全面攻击。毫无疑问，他们对于你前几日针对各邪兽人氏族所取得的成功很恼火，想要展开报复行动。$B$B现在你只要沿着荣耀之路走到头，到达堡垒的下面，你就会发现所有的邪兽人都在忙着进行准备工作，这下你就能攻其不备了。$B$B杀死他们的头目，教官祖罗克！', '远征军指挥官达纳斯·托尔贝恩命令你尽快杀死教官祖罗克。完成任务后返回地狱火半岛的荣耀堡，向远征军指挥官复命。', '在我听到你亲自向我回报之前我都不敢相信那是真的。我们的斥候已经陆续回报，那些破碎之手氏族少了他们亲爱的训练员指挥他们，当前已经陷入一片混乱。$B$B你已经历经了长途的跋涉，$N。我相信你会接受这个护甲还有我的感谢。光荣的穿上它吧，这是你应得的!', '训练员死了吗?嗯，或许是我的斥候搞错了?', '', '去地狱火半岛找荣耀堡的远征军指挥官达纳斯·托尔贝恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10938, '暗月祝福套牌', '你现在已经收集到了祝福套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。', '当暗月马戏团来到镇上的时候，把祝福套牌交给他们。', '现在你已经集满了整套祝福套卡。把它还给我们会让你和暗月马戏团之间创建永不断裂的联系。请允许我将一张更强大的暗月卡片回送给你做为酬谢你的一份薄礼。', '看来你已集满全套的祝福套卡!恭喜你!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10939, '暗月风暴套牌', '你现在已经收集到了风暴套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。', '当暗月马戏团来到镇上的时候，把风暴套牌交给他们。', '现在你已经集满了整套风暴套卡。把它还给我们会让你和暗月马戏团之间创建永不断裂的联系。请允许我将一张更强大的暗月卡片回送给你做为酬谢你的一份薄礼。', '看来你已集满全套的风暴套卡!恭喜你!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10940, '暗月报复套牌', '你现在已经收集到了报复套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。', '当暗月马戏团来到镇上的时候，把报复套牌交给他们。', '现在你已经集满了整套狂怒套卡。把它还给我们会让你和暗月马戏团之间创建永不断裂的联系。请允许我将一张更强大的暗月卡片回送给你做为酬谢你的一份薄礼。', '看来你已集满全套的狂怒套卡!恭喜你!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10941, '暗月愚人套牌', '你现在已经收集到了愚人套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。', '当暗月马戏团来到镇上的时候，把愚人套牌交给他们。', '现在你已经集满了整套失心套卡。把它还给我们会让你和暗月马戏团之间创建永不断裂的联系。请允许我将一张更强大的暗月卡片回送给你做为酬谢你的一份薄礼。', '看来你已集满全套的失心套卡!恭喜你!', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10946, '灰舌的计谋', '奥鲁姆的牺牲太巨大了。我从未要求他为这份事业贡献出自己的生命，但他却义无反顾地这么做了。$B$B如果我们还想让伊利丹继续认为自己仍处于安全的境地，就必须服从他的命令，至少现在如此。$B$B我当前统率着一支数量庞大的灰舌军团，但除了其中的死誓者以外，军团内没有任何其它人值得信任。$B$B所以，必须要由你去执行伊利丹的命令。带上这件兜帽，它上面附有特殊的魔法。穿上它之后，在你杀死凯尔萨斯的凤凰时，所有人都会以为你是我的手下。', '转至风暴要塞，在穿着灰舌兜帽的情况下杀死奥。完成任务之后回到影月谷，向阿卡玛复命。', '做的好，$N。我们距离使伊利丹的焦点从我们以及…身上转移又向前迈进了一步，$B$B<阿卡玛的目光望着玛维.影歌的方向。>$B$B还有更多的事情要做，$N。', '命令已经达成了吗，$N?伊利丹不是一个有耐心的主人!', '灰舌的计谋', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10947, '往日的神器', '伊利丹的注意力已经转移到了凯尔萨斯身上，这都得感谢你。我们现在有机会继续行动了。$B$B我曾在梦境中见过一件神器——巫妖雷基·冬寒的护符匣，它必定能帮助我们对付背叛者。可惜当雷基在海加尔山战役败北之后，护符匣便丧失了原有的能量。$B$B要取回这件神器也不是没有办法。传说青铜龙军团在艾泽拉斯世界中守护着一处神秘的地方……过去和现在的交汇之地。去吧，那里就是你的目的地。', '转至塔纳利斯的时空之穴，进入海加尔山战役之后击败雷基·冬寒，将他的时光护符匣交给影月谷的阿卡玛。', '我的预兆……现在全都变清楚了。这个神器的力量超越了灵魂……控制它……将它吸取到自身……我会利用那些力量来夺回属于我的东西!我们挑战伊利丹的时刻已经来临了!', '你已经取得骨匣了吗，$N?', '', '去影月谷找守望者牢笼的阿卡玛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10957, '灰舌的救赎', '尽管当时停留在外域的大部分破碎者都决定效忠伊利丹，但最睿智的阿卡玛却有所保留。不过，他也知道，在那时候公开反对背叛者，只会将他的种族引领上全面灭绝的道路。$B$B因此，他采取了隐忍的策略，并将这个绝密的计划一直保守到今天。如果今天我们失败了，后果将是灾难性的……不仅仅是阿卡玛，不仅仅是破碎者，整个外域都会陷入毁灭。这个世界上还没有任何人能像伊利丹一样，给我们造成这样大的恐慌与痛苦。$B$B帮助阿卡玛释放他的灵魂吧，这样他就能带你转至伊利丹的最终秘室了。', '击败黑暗神殿内的阿卡玛之影，帮助阿卡玛夺回灵魂的控制权。完成任务之后向先知坎奈复命。', '是时候了，$N。击垮伊利丹的时刻来临了。', '什么事，$N?', '', '去找黑暗神殿的先知坎奈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10959, '背叛者之死', '伊利丹麾下的诸位军官已被击败，阿卡玛大人现在应该能够强行打开通向伊利丹秘室的大门了。召集你的盟友，趁阿卡玛打开大门时冲入秘室。$B$B我们还不知道玛维的情形，或许我们不得不在没有她助阵的情况下提前行动。$B$B我希望你和你的盟友能完成历史赋予你们的使命。伊利丹与阿卡玛见面之后，他们两人里恐怕只有一个会活下来。', '先知坎奈要求你击败黑暗神殿内的伊利丹。', '和预言说的一样，$N。一个接一个，伊利丹的副官们都倒下了……现在背叛者也迎接了他的死期!$B$B你要知道，$N:自从伊利丹到来之后，阿卡玛所做的每一个决定和生命中的每一刻，都是为了这一刻而计画着。伊利丹终于死了，我的族人……也自由了!', '什么事，$N?', '', '去找黑暗神殿的先知坎奈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10961, '唤醒戒卫', '很久之前，用于传授风暴乌鸦形态知识的圣物被托付给克林塔尔·梦行者保管。$B$B克林塔尔的躯体在月光林地的兽穴中休眠，他的灵魂则在翡翠梦境中徜徉。$B$B我得准备一剂可以令他的灵魂复苏的药膏。制造这种混合剂需要一些普通的草药，还有生长在赞加沼泽高大的蘑菇顶端的沼泽花。采集沼泽花的时候要小心，它们非常脆弱，而且可能会爆发出致命的毒气。', '将10株沼泽花、10簇远古苔和10株梦露花交给塞纳里奥庇护所的莫希斯·轻翼。', '<莫西斯从你手中接过草药，检视它们。拿了一个瓶子，开始混合药水。>$B$B这只需要一下子，$N。然后，你一定要转至月光林地。', '你弄到准备药剂需要的所有材料了吗?请小心别把花粉洒在我的身上。这种花粉会让我不停的打喷嚏。$B$B<莫西斯嗅了一下材料然后打了个喷嚏。>', '', '去找赞加沼泽的莫希斯·轻翼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10962, '参观时光之穴', '曾经有位年老的牧师路经孤儿院，给我们讲过时空之穴的故事。他说位于时间中心的时空之穴起着维护历史进程的重要作用。$B$B我不知道那是什么意思，但是他说那儿驻守着守护世界的龙族！我想看看龙长什么样！$B$B我们可以去时空之穴吗？那位牧师说入口就在那片名叫塔纳利斯的沙漠东部边缘。$B$B我们去了那里之后，你能给我买件纪念品吗？', '将孤儿多尔南带到时光之穴中央平台上的扎拉多姆面前。如果你到达时她不在你身边，记得召唤她。$B$B然后在时间守护者的军需官艾鲁尔米那儿为她购买一个玩具龙，艾鲁尔米就在入口通道底部附近。', '太棒了!一只专属于我的龙!我希望有天能够幸运到有只龙当我的朋友。$B$B<朵娜开心的跳上跳下，用力抱住她的新玩具。>$B$B这真是一趟最棒的旅行!我真希望永远不会结束。', '你认为他们所说的关于时光之穴的事都是真的吗?', '带多尔南转至时光之穴', '使用你的孤儿哨召唤德莱尼孤儿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10963, '参观时光之穴', '曾经有位年老的牧师路经孤儿院，跟我们讲起时光之穴的故事。他说位于时间中心的时光之穴起着维护历史进程的重要作用。$B$B我不知道那是什么意思，但是他说那儿驻守着守护世界的龙族！我真想看看龙是长什么样的啊！$B$B我们可以去时光之穴吗？那位牧师说入口就在那片名叫塔纳利斯的沙漠东部边缘。$B$B还有还有，我们去了之后，你可以给我买件纪念品吗？', '将孤儿萨兰蒂亚带到时空之穴中央平台上的扎拉多姆面前。如果你到达时她不在你身边，记得召唤她。$B$B然后在时光守护者的军需官艾鲁尔米那儿为她购买一个玩具龙，艾鲁尔米就在入口通道底部附近。', '太帅了!一只专属于我的龙!有天我打算要拥有一只真的龙。$B$B<瑟兰德雅狡猾的看着她的新玩具，心里不知道在转着什么主意。>$B$B这真是一趟最棒的旅行!我希望永远不要结束。', '要是他们对于时光之穴的说法是真的，那么这里一定是一个强大力量之地。', '带萨兰蒂亚转至时光之穴', '使用你的孤儿哨召唤血精灵孤儿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10964, '唤醒沉睡者', '带上唤醒戒卫转至月光林地的怒风兽穴。克林塔尔·梦行者就在最南端的那个驻有梦境守卫者的洞穴中。$B$B喂他服下药膏，等待他慢慢苏醒。在克林塔尔·梦行者的灵魂与身体重新结合的过程中，他会处于异常脆弱的状态；当然，他是不可能认出你的。$N，一旦他恢复神志，请立即通报你的身份。他需要你的帮助才能收集到仪式所需的圣物。', '使用唤醒戒卫帮助克林塔尔·梦行者从翡翠梦境中苏醒。当他恢复意识后跟他谈谈。', '<这个德鲁伊从睡眠中清醒过来，看起来无力且憔悴。他的视线扫过这个房间搜寻看不见的追捕者。>$B$B莫西斯?$B$B不，你不是莫西斯…你是谁，$r，你为何打扰我休息?$B$B<除了问题本身的敌意外，德鲁伊看来几乎并不在意被叫醒这件事。>', '<你准备对沉睡中的德鲁伊使用药剂。>', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10965, '梦境危机', '<克林塔尔听你传达莫希斯的指示，他点着头，脸上却流露出忧虑的神情。>$B$B我无法完全从翡翠梦境中脱身，但是这块取自我的灵魂的碎片可以帮助你寻找圣物。$r，好好保护它，这东西相当脆弱。$B$B翡翠梦境已经成为了危机重重的是非之地。它紧紧地抓住我，只有等这儿恢复正常，我才可能全身而退。你所看到的不过是梦境中折射出的影像！', '在克林塔尔·梦行者的灵魂收集艾维娜圣物时保护他，然后与梦境卫士鲁罗萨谈一谈。', '你很幸运还好克林塔够强壮到足以维持他的本体分裂得如此长久，$N。很少有德鲁伊能够在翡翠梦境遭攻击时还能设法进行这样的法术。好好保护圣器!', '快点，$r。如果这些怪物从墓穴中脱逃，将不只是克林塔梦境行者会有危险而已。', '', '去月光林地找月神湖的梦境卫士鲁罗萨。', '协助克林塔尔收集圣物', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10966, '返回孤儿院', '糟糕！我该返回沙塔斯城的孤儿院了。$B$B跟你在一起的日子非常愉快。$N，你是世界上最好的人！就像我的大$g哥哥:姐姐;一样！$B$B<多尔南的眼中泛起泪花。>$B$B我会想你的！长大之后，我要做一个像你一样的人！！！', '将德莱尼孤儿哨归还给沙塔斯城贫民窟的孤儿院长莫希。', '能够让人知道有像你这样的$g英雄:英雌;愿意如此无私地付出你们的时间是好事。$B$B我看的出来你和朵娜在一起的时光让她印象深刻。对孩子们来说能够有机会出外去见识这个世界是一件好事。$B$B来，她告诉我她想要你照顾她最喜欢的宠物之一，就像你照顾她那样。一个能让你记得她的东西。$B$B有空要常回来看我们。', '很高兴又见到你了，$C。我相信你和年轻的朵娜一起共渡了一段美好的时光吧?', '', '去找沙塔斯城的孤儿院长莫希。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10967, '返回孤儿院', '糟糕！我该返回沙塔斯城的孤儿院了。$B$B跟你在一起的日子非常愉快。$N，你是世界上最好的人！就像我的亲$g哥哥:姐姐;一样！$B$B<萨兰蒂亚的眼中泛起泪花。>$B$B我会想你的！长大之后，我要做一个像你一样的人！！！', '将血精灵孤儿哨归还给沙塔斯城贫民窟的孤儿院长莫希。', '能够让人知道有像你这样的$g英雄:女英雄;愿意如此无私地付出你们的时间是好事。$B$B我看的出来你和瑟兰德雅在一起的时光让她印象深刻。对孩子们来说能够有机会出外去见识这个世界是一件好事。$B$B来，她告诉我她想要你照顾她最喜欢的宠物之一，就像你照顾她那样。一个能让你记得她的东西。$B$B有空要常回来看我们。', '很高兴又见到你了，$C。我相信你和年轻的瑟兰德雅一起共渡了一段美好的时光吧?', '', '去找沙塔斯城的孤儿院长莫希。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10970, '拯救任务', '上次进入复仇军的地盘执行侦察任务时，我们发现了这个球状监牢并将它带了回来。当时要不是监牢中发出微弱的求救信号，我们根本不会留意到它。$B$B我们猜测有位伙伴被困在这里面，但是想要不伤害里面的人就打开它几乎是不可能的。$B$B或许复仇军的成员可能会随身携带着这个监牢的钥匙。只要夺得一把钥匙，我们就能揭开其中的秘密了。', '为虚空风暴维序派哨站的指挥官阿米尔夺得复仇军监狱钥匙。', '退后，$N。这个很有可能是一个复仇军陷阱。', '进展的如何?', '', '去虚空风暴找维序派哨站的指挥官阿米尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10971, '复仇军的秘密', '<阿米尔举起一枚标识牌。>$B$B我在一名维序派前锋的尸体上找到了这块身份标识牌。我猜他们在所有的囚犯身上都挂上了这种标识牌。$B$B接下来，我要将这些标识牌归档研究，看看能否对他们的刑狱系统有所了解。如果你找到更多的复仇军监狱钥匙的话，就用它们打开此地正南方复仇军前沿基地的监狱。将你发现的标识牌统统带回来给我。', '虚空风暴维序派哨站的指挥官阿米尔要你取回一块复仇军囚犯标识牌。', '看起来他的功能不只是辨识身分而已。标签上有一些用某种密码编写的文字。我就快要破解它了，也许只要再几片就可以了。', '你找到身分标签了吗?', '', '去虚空风暴找维序派哨站的指挥官阿米尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10972, '复仇军囚犯的标识牌', '我需要更多的身份标识牌，$N。我发现这些身份标识牌不仅用于标识囚犯身份，还记录着囚犯被囚禁的地点！$B$B一旦破解了标识牌的密码，我们就能找到所有被俘虏的伙伴，然后以最小的代价将他们解救出来。', '', '我们快要破解他门的密码了，$N。', '我需要更多的身分标签，$N。当前为止我发现这些标签不只是拿来辨识囚犯的身分而已，它同时也记载着位置!$B$B一旦我破解上面的编码，就可以明确的知道所有盟友被囚\r\n禁的位置，并且以最小的冲突救出他们。', '', '去虚空风暴找维序派哨站的指挥官阿米尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10973, '一千个世界', '我已经破解了标识牌的密码！标识牌上的编码由固定的字段组成。所有的标识牌正面都写着“千百个世界……”，我不太理解这段文字的意思，不过听上去就透露着邪气。$B$B标识牌背面的信息至关重要。编码的前半部分表明关押地点，后半部分则是囚犯的种类。此外，似乎这些钥匙能组合成进入另一类监狱的特殊钥匙。现在，我需要更多的钥匙来研究……', '虚空风暴维序派哨站的指挥官阿米尔要你取回5把复仇军监牢钥匙。', '<阿密尔灵巧的将钥匙组合起来，并且开始阅读这个刚组合完成的钥匙碎片上的记号。>$B$B“摧毁了上千个世界，还有上千个世界要征服……这就是节点之王的意志。”$B$B<阿密尔将钥匙碎片转到了背面开始阅读。>$B$B巴什伊尔的静止密室?', '我知道你付出了很多，但是想想这样你可以拯救多少人啊!', '', '去虚空风暴找维序派哨站的指挥官阿米尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10974, '巴什伊尔的静止间', '复仇军在刀锋山最北端创建了一处名叫巴什伊尔码头的营地。根据钥匙石板上的记录，复仇军在那里设立了更大的监狱。他们将这些监狱命名为静止间。$B$B这块钥匙石板能让你进入巴什伊尔码头的特殊静止间——阿尔法静止间。$B$B我的全息影像会在码头等你完成探查任务。到那边再联络吧。', '使用复仇军钥匙石板 - 阿尔法开启刀锋山巴什伊尔码头的阿尔法静止间。$B$B将阿尔法静止间的证物交给巴什伊尔码头的指挥官阿米尔的影像。', '<指挥官阿密尔的影像仔细查看你带回来的证据。>$B$B情况比我想的还糟……这些密室中关的都是许许多多不同世界的凶猛野兽与生物。他们希望有一天可以控制这些野兽，听从他们的命令。我们必须杀光他们!', '你办到了!有什么发现吗?', '', '去刀锋山找巴什伊尔码头的指挥官阿米尔的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10975, '巴什伊尔的房间', '', '', '要做的事情总是那么多，$N。现在去开启一个静止密室并且消灭里头的魔物!', '我们当前陷入了僵局，$N。你收集到的资料已经给我们足够的资讯以救出我们被关在虚空风暴小监狱里头的盟友们，但是我们必须一股作气的把复仇军对巴什伊尔平台造成的威胁连根拔起。$B$B加入与复仇军的战斗吧!把复仇军监狱钥匙交给我，而我将帮你打造复仇军监狱钥匙，使你得以开启巴什伊尔平台静止密室。', '', '去刀锋山找巴什伊尔码头的指挥官阿米尔的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10976, '节点之王的印记', '我必须查明复仇军到底在奥金顿的法力陵墓中藏着什么东西。$B$B如果你与巴什伊尔静止间内的怪兽打斗过的话，应该见过一种名叫节点之王的印记的东西。如果你找到这种印记，立即带回来给我！它是制作法力陵墓静止间钥匙所需的最后一件材料。', '刀锋山巴什伊尔码头的指挥官阿米尔的影像要你取回节点之王的印记。', '终于!$B$B<指挥官阿密尔读着节点之王印记上面的记载。>$B$B最后2名囚犯?我不敢想象里头有什么恐怖的东西在等着……', '这将会是你最不愿面对的任务，$N。', '', '去刀锋山找巴什伊尔码头的指挥官阿米尔的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10977, '法力陵墓的静止间', '我利用你取回的这枚节点之王的印记铸造了一把新钥匙，可以用来打开法力陵墓内的静止间。$B$B从印记上雕刻的文字来看，法力陵墓设有两处静止间，一处在入口附近，另一处则在节点亲王沙法尔旁边。我给你的这把钥匙能打开入口附近的静止间。$B$B我要你进入奥金顿的法力陵墓，打开法力陵墓静止间。', '刀锋山巴什伊尔码头的指挥官阿米尔的影像要你进入奥金顿的法力陵墓，对静止间使用法力陵墓静止间钥匙。$B$B此任务必须在英雄难度的地下城中完成。', '我已经听说了你的英勇行径，$N。哈拉玛德与我都同意你的英勇行为应该得到崇高的奖赏。$B$B虽然……算了，你已经做的够多了。假如我再要求你做更多的事情的话，我会觉得对不起自己的良心。', '假如你选择不再进行下去，我能谅解的，$N。', '调查法力陵墓静止间', '去刀锋山找巴什伊尔码头的指挥官阿米尔的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10978, '返回莫希斯·轻翼身边', '圣物已经取回，你必须立刻离开这里，$N。克林塔尔置自己和梦境守卫者的安全于不顾，帮助你找回圣物；现在，他必须专心对抗那些滋扰翡翠梦境的入侵者了。$B$B将圣物交给莫希斯·轻翼，并将你看到的情形告诉他。或许他可以帮助我们判断入侵翡翠梦境的人究竟是谁。', '将艾维娜圣物交给赞加沼泽塞纳里奥庇护所的莫希斯·轻翼。', '<莫西斯一边听你诉说兽穴的情况一边从你手中接过了圣物。>$B$B真是令人担忧的消息，$N。翡翠梦境中发生了许多奇怪的骚动，但是我不记得听说过任何外界势力入侵翡翠梦境的消息。你确定克林塔也是这么想吗?', '克林塔帮助你取得圣器了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10980, '乌鸦之书', '莫希斯的猜测是对的，这支鸦人部族很可能跟翡翠梦境的躁动有关，但是在没搞清楚情况之前，我们不能贸然行动。$B$B坦莫在研究中发现，鸦人部族很可能保有一本古老而神圣的“乌鸦之书”。$B$B鸦人的灵魂不会自己显现在你的眼前，所以你需要带着这块石头，到刀锋山的西部高峰去，在乌鸦林的南边弄到一颗以太鳐之眼。把它们组合起来，你就可以看到鸦人的灵魂了。你要寻找的目标，是一个名叫长者塞克卡尔的灵魂。', '使用一颗以太鳐之眼和你的先知之石找到乌鸦教派的幽灵。在漩涡峰寻找长者塞克卡尔的灵魂，向他询问有关乌鸦之书的问题，然后向常青林的阿尔索恩·风歌复命。', '即使在阿拉卡之间，乌鸦教徒也被认为是异教徒，你不觉得很神奇吗?传统的阿拉卡祭司因为痛恨他们所以毁掉他们的圣典，真是不可思议!我们必须取得那本圣典，$N。$B$B这本圣典是解开乌鸦神谜团以及防止他占领翡翠梦境的关键。$B$B假如我们成功的话，也许莫西斯最后会答应收我为徒!', '<亚索充满希望的看着你。>$B$B你找到任何关于乌鸦圣典的讯息吗?', '', '去刀锋山找常青林的阿尔索恩·风歌。', '了解有关乌鸦之书的知识', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10981, '节点亲王沙法尔的私人房间', '', '', '我已经完成你的要求了，这是通往萨法尔私人密室的钥匙。', '只有意志最坚定以及最勇猛善战的冒险者才会向我提出这项要求，$N。假如你想要面对法力陵墓第二间密室里头的惊恐魔物，我可以帮你制作通往那里的钥匙。给我一个节点之王印记，我就可以达成你的愿望。', '', '去刀锋山找巴什伊尔码头的指挥官阿米尔的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10985, '帮助阿卡玛', '<克希利身上发出阵阵淡泊的光芒，而他身边的奥尔多和占星者军队也回应着他的命令。克希利的军团已经完全准备好了，随时可以将伊利丹的军队压制住，并为阿卡玛吸引敌人的注意力。现在，这位纳鲁正等待着你给出进攻开始的信号。>', '在克希利的军队发动佯攻之后，保护阿卡玛和玛维进入影月谷内的黑暗神殿。', '<你感觉手中出现了一个物品，希瑞脉动着能量。这是你替阿卡玛交给阿达欧的勋章，藉由纳鲁的魔法加强了力量。沙塔尔将卡拉伯尔勋章委托给你，有了它就能进入黑暗神庙。>', '<希瑞对你打了招呼。>', '帮助阿卡玛和玛维进入黑暗神殿。', '去影月谷找巴尔里废墟的克希利。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10987, '捕获麻鹰', '纳格兰的野生麻鹰是视觉最为敏锐的食肉鸟类。但是由于体型较小，因此受到风鹏的排挤，纳格兰大部分区域已经难寻它们的踪迹。$B$B大多数的麻鹰栖息在暮光岭。如果你能捕获一只麻鹰，我可以训练它去寻找被掩埋的书典残片。$B$B但是捕捉麻鹰并不是件容易的事，它们极易受到惊吓，一旦有陌生人靠近就会立即飞走。我建议你悄悄接近这些敏感的生物，伺机投掷罗网。', '用麻鹰网捕捉一只野生麻鹰，把它交给暮光岭的观察者艾莱亚。', '做的好!虽然我还在获得雀应信赖的阶段，但是我对它们的了解已经足以帮你训练一只雀鹰。', '你已经抓到雀鹰了吗?', '', '去纳格兰找暮光岭的观察者艾莱亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10988, '乌鸦石', '经过训练，这只麻鹰已经能对鸟哨声做出反应了。吹响鸟哨，它就会飞到你身边，指引你寻找书典残片。阿尔索恩捎话过来说，你要找的残片应该都在斯克提斯及其周围的峡谷中，去那里找麻鹰吧。$B$B当你集齐残片后，将鸟哨还给阿尔索恩，她会将这只麻鹰放归大自然的。$B$B代我向阿尔索恩问好。', '在斯克提斯收集8块乌鸦石，把它们交给刀锋山常青林的阿尔索恩·风歌。', '<亚索从你手中拿走了乌鸦圣典的碎片然后开始重组它们。>$B$B有些字已经磨损了，但是我应该可以辨别大部分的内容……', '你收集的碎片够让我重组乌鸦圣典了吗?', '', '去刀锋山找常青林的阿尔索恩·风歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10990, '雄鹰精华', '根据乌鸦之书的记载，在远古时代，崇拜鸦神的鸦人捕捉三种与鸦神为敌的猛禽，将它们的精华封印在石头神殿中。每座神殿都由专门的守护者看守，防止鸦神的敌人释放这些被禁锢的精华。$B$B如果我们能拿到这些精华，就应该能引出鸦神并击败它。$B$B书中提到，第一座神殿中禁锢着雄鹰精华，这座神殿位于泰罗卡森林尤鲁恩湖以南的山丘中。$B$B乌鸦之书中还说，雄鹰勇敢地战斗，但最终被潮水般涌来的敌人淹没。你的熊形态所具备的坚韧与强壮应该可以在这场战斗中发挥巨大的作用。', '击败雄鹰守护者，取得雄鹰精华。使用阿尔索恩的麻鹰哨以召唤麻鹰传递你获胜的消息。$B$B如果你弄丢了阿尔索恩的麻鹰哨，可以回到常青林找阿尔索恩·风歌再拿一个。', '<亚索似乎透过雀鹰的感知感觉到取回的精华力量。>$B$B即使经过了数千年的束缚，战鹰的力量依然惊人。假如其它的精华也像战鹰的一样强大，乌鸦神将会对你感到畏惧。', '<雀鹰似乎用亚索的声音说话。>$B$B你已经成功的释放战鹰灵魂的精华了吗?', '', '去找阿尔索恩的麻鹰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10991, '猎鹰精华', '<麻鹰口中传出阿尔索恩的声音。>$B$B崇拜乌鸦之神的鸦人们还封印了猎鹰精华。$B$B它被禁锢在斯克提斯附近的神殿中，昭示着乌鸦祭司那叱诧风云的辉煌岁月。$B$B那座神殿就在斯克提斯西北方的艾雷诺湖岸边。$B$B要战胜猎鹰守护者，你必须借助猎鹰的力量。在猎豹形态下，利用你的速度和敏捷，趁守护者恢复能力之前击败他！', '击败猎鹰守护者，取得猎鹰精华。使用阿尔索恩的麻鹰哨以召唤麻鹰传递你获胜的消息。$B$B如果你弄丢了阿尔索恩的麻鹰哨，可以回到常青林找阿尔索恩·风歌再拿一个。', '<雀鹰尽职地传达亚索的意思。>$B$B做的好，$N。我还担心猎隼的石龛在奥齐顿的大爆炸中被摧毁了。我们已经差不多准备好面对安祖了，$N。我很想跟你同行，去看这个自封为“神”的家伙被送回属于它的地狱!', '<再一次地，亚索的声音由雀鹰发出。>$B$B你已经取得猎隼的精华了吗?', '', '去找阿尔索恩的麻鹰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10992, '山鹰精华', '<麻鹰口中传出阿尔索恩的声音。>根据乌鸦之书记载，被封印的最后一块也是最强大的一块精华是山鹰精华。它被禁锢在远离斯克提斯的神殿中，就在奥金顿东南方某座偏僻的小岛上。$B$B从书中的描述来看，应该就是被称为悲翼之地的岛屿。$B$B山鹰守护者几乎对鸟类利爪的攻击完全免疫。放弃物理攻击吧，呼唤群星之怒击败他。不要重蹈山鹰的复辙。', '击败山鹰守护者，将山鹰精华交给常青林的阿尔索恩·风歌。', '既然我们拥有全部的精华，莫西斯.语翼就必须找到一个方法将它们合成一个符咒让你对付乌鸦神，将他从翡翠梦境中引诱出来并且击败他。我会透过灵魂们传送我的意思给乌鸦神，希望他了解我理论的重要性。$B$B每一个灵魂都会受到和我给你的符咒一样的祝福。', '你已经战胜猎鹰守护者并取得它的精华了吗?', '', '去刀锋山找常青林的阿尔索恩·风歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10993, '返回塞纳里奥庇护所', '将这些精华交给莫希斯·轻翼，并告诉他我们收集到的关于鸦神的新情报。$B$B莫希斯懂得如何利用这些精华引出鸦神安苏。快去找他吧，不知道克林塔尔和梦境守卫者还能在鸦神的攻击下坚持多久！$B$B<在你准备转身离开的时候，阿尔索恩抓住了你的手臂。>$B$B$N，拜托你告诉莫希斯，我帮你了多大的忙。我担心他不知道我为此做出的贡献！', '将阿尔索恩的包裹交给塞纳里奥庇护所的莫希斯·轻翼。', '<莫西斯收下了包裹，打开并且取出亚索的笔记。他读完了这些笔记，并未对作者做出任何评论。>$B$B以某种程度上来说，终于知道敌人的真面目让我松了一口气，但是这个安祖拥有相当强大的力量。了解敌人的名称与实力是很重要的，但是我们还没准备好面对他。', '我一直在等亚索的消息。你们发现了什么呢?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10994, '寻找月亮石', '如果能将三种精华与某种罕见的宝石——比如南国之怒月亮石——相结合，它们所释放的能量就应该可以引出安苏。$B$B眼下惟一的问题是南国之怒月亮石非常稀有，据说只有在艾萨拉的悬崖边才能找到这种宝石。去艾萨拉的悬崖瀑布附近寻找吧。$B$B昨晚，有一队暗夜精灵在搜寻南国之怒月亮石的过程中惨遭不幸。他们的船只仍然停泊在河岸边，他们就是在那里看到月亮石的。多留心一点，在艾萨拉一岸仔细寻找吧。', '将一块南国之怒月亮石交给塞纳里奥庇护所的莫希斯·轻翼。', '<莫西斯的眼神泛着泪光，同时对你所描述的寻找历程以及想起你几乎要失去月亮石的经过感到好笑。他整理一下自己的情绪然后注视着这个发光的石头。>$B$B我要开始将那些鸟的灵魂精华注入月亮石。不久之后你就可以准备好挑战我们的敌人了。', '看起来你经过了重重考验才来到这里。寻找月亮石真的那么难吗?', '', '去找赞加沼泽的莫希斯·轻翼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10995, '格鲁洛克的巨龙颅骨', '诅咒洞窟就在东边巨龙之末的边界。当前，格鲁尔之子格鲁洛克正在那里密谋着他那愚蠢的计划。$B$B不过，我听说他有一件重要财产被人用诡计偷走了，是不是你干的？真不错，唯一的遗憾是他居然没被杀掉。$B$B如果我们想要重获自由，你还得去把他另一件最珍贵的财产给我夺回来。那就是他的父亲在与黑龙军团作战时得到的巨龙颅骨，后来他的父亲把那东西赏赐给了他。而得到这个巨龙颅骨的唯一办法，就是杀死他。', '夺回格鲁洛克的巨龙颅骨，将其交给刀锋山鲜血之环塔顶上的枯瘦的莫戈多格。', '的确，你一定经历了一场恶斗，$C。他不再威胁着我们，我已经可以放心了。$B$B我会把这个头骨交给丘特妥善保管。我开始认为有了你的帮助，我们可能会成功。', '格鲁洛克已经死了吗?', '', '去刀锋山的鲜血之环塔顶找枯瘦的莫戈多格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10996, '玛古克的宝箱', '玛古克一般在东南边的剃刀山上巡逻，那是因为他的父亲派他去看守东边的山脉。他非常喜欢去威胁那些妨碍到他的生物。$B$B因为他是格鲁尔的儿子，所以，如果我们想要继续活下来，他就必须被消灭，而你将负责执行这一任务。$B$B玛古克一直随身带着一只宝箱，你记得把箱子带回来给我，以证明你确实把他干掉了。当然，箱子里的东西你可以随意处置。', '夺取玛古克的宝箱。', '你说箱子里面是空的?真可惜，但是你可以由此得知我们在对抗的这种残忍暴行。$B$B随着玛古克的死亡，我们已经越来越接近实现我的梦想，一个可以让我们决定自己命运的巨魔家园。', '你取得宝箱了吗?', '', '去刀锋山的鲜血之环塔顶找枯瘦的莫戈多格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10997, '戈隆的军旗', '你熟悉沙塔斯城吗，$c？在它的西北边有个地方叫壁垒山，进去的唯一途径是乘坐飞行坐骑。$B$B格鲁尔的一个儿子斯莱格控制了居住在那里的戈杜尼食人魔。虽然他们距离我们的确非常遥远，但我们也不能让他有好日子过，否则他在知道其馀的兄弟被杀害之后，很可能会回来给我们制造麻烦。$B$B$N，你赶紧到那里去干掉他，将他的军旗带回来，作为他死亡的证明。', '夺取斯莱格的军旗。', '史拉格已经死了，真是令人松了一口气。我们不再处于他的恐怖暴行威胁之下了。$B$B假如你不介意的话，我想取走这面军旗，当作是山区所有巨魔的希望象征。$B$B感谢你，$N。', '你把史拉格的军旗带回来了吗?', '', '去刀锋山的鲜血之环塔顶找枯瘦的莫戈多格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (10998, '维姆高尔的魔典', '还有一个戈隆必须要消灭，那就是斯古洛克·磨魂者。他现在藏起来了，不过有一个办法能将他引诱出来。$B$B有个食人魔术士叫邪恶的维姆高尔，他是斯古洛克的老师，你必须将他的魔典带回来！$B$B只要站在维姆高尔的法阵周围的火环中，就可以召唤出维姆高尔。维姆高尔的法阵就在东北边的山脉上，靠近破碎荒野的地方。$B$B还有一件事，$N，如果你听到维姆高尔在大喊什么变得更大之类的话，就让你的朋友们分别站在五个火环中，打断他的法术！', '夺取维姆高尔的魔典。', '我在想应不应该碰触如此邪恶的东西。然而如果我们想知道其中的记载并且引诱史库洛克从藏身处现身的话，就必须阅读它。', '你已经召唤邪恶的梵戈并且从他的手中取得魔典了吗?', '', '去刀锋山的鲜血之环塔顶找枯瘦的莫戈多格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11000, '磨魂者', '魔典是击败斯古洛克的关键之物。$B$B转至磨魂者之穴，大声诵读魔典，启动召唤仪式。仪式中将出现一件名叫磨魂者的物品，与此同时，被斯古洛克残害的灵魂们也会现身，试图毁掉这件物品。你必须阻止他们，让斯古洛克的真身完全被召唤到这个世界。$B$B往北穿越鲜血之环另一边的刃喉谷就能到达磨魂者之穴，就在格鲁尔的巢穴的正前方。$B$B将斯古洛克的灵魂带回来。', '夺得斯古洛克的灵魂。', '这么说来事情结束了。你已经帮助我们脱离格鲁尔之子的奴役枷锁。你解救了血槌氏族即将灭族的命运。$B$B再多的言语也无法表达刀锋山所有的巨魔所欠你的人情，不管是血槌氏族还是刀塔氏族都一样，$N。$B$B看看下面，甚至现在巨魔们还是聚集起来对你献上最高的敬意。让格鲁尔还有他的傀儡，不再是国王的莫加尔在他们的巢穴中蜷缩吧。去下面巨魔们聚集的地方当我们的新$g国王:皇后;吧!', '你已经取得史库洛克的灵魂了吗?', '', '去刀锋山的鲜血之环塔顶找枯瘦的莫戈多格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11001, '消灭乌鸦之神', '我们不能再浪费时间了。你必须将这块注入猛禽精华的月亮石放置在某个充盈着强大能量的地方，将鸦神从相对安全的翡翠梦境中引出。$B$B进入塞泰克大厅，在鸦神之爪那里释放月亮石的能量，你可以在利爪之王的大厅前找到这个地方。如果一切顺利的话，安苏会认为他的崇拜者们已经聚集一堂，迎接他返回这个世界。一旦鸦神现身，就别对他手下留情！', '杀死乌鸦之神，然后向塞纳里奥庇护所的莫希斯·轻翼复命。$B$B这项任务必须在英雄难度的地下城中完成。', '很高兴再度见到你，$N。你击败乌鸦神的壮举远胜过任何我原先想赋予你的试验或者考验祭仪。$B$B你已经在猛禽德鲁伊世世代代所守护的知识上证明了你自己。', '你从塞泰克大厅带来了什么消息呢?你打败安祖了吗?', '', '去找赞加沼泽的莫希斯·轻翼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11002, '玛瑟里顿之死', '伊利丹·怒风的邪兽人军队之源已经被彻底铲除了。这座巨大的工厂已经停止了它那邪恶而肮脏的生产——至少现在如此。现在，这里唯一剩下的就是这处断壁残垣与你手中所捧着的巨大徽记。事实上，这正是一个联盟英雄的胜利象征。$B$B将玛瑟里顿的徽记带回荣耀堡，交给达纳斯·托尔贝恩。', '将玛瑟里顿的徽记交给荣耀堡的远征军指挥官达纳斯·托尔贝恩。', '这项战胜的消息不光对伊利丹造成打击，$N。对燃烧军团也是……深渊领主指挥官被消灭了。地狱火堡垒的围攻行动对燃烧军团来说已经失去意义。毫无疑问地，所有他们造的孽最终都会转而回归黑暗神庙。$B$B伊利丹要赎罪的日子来了……而且快了。', '从有记忆开始，这是我第一次感受到了安静。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11003, '玛瑟里顿之死', '伊利丹·怒风的邪兽人军队之源已经被彻底铲除了。这座巨大的工厂已经停止了它那邪恶而肮脏的生产——至少现在如此。现在，这里唯一剩下的就是这处断壁残垣与你手中所捧着的巨大徽记。事实上，这正是一个部落英雄的胜利象征。$B$B将玛瑟里顿的徽记带回萨尔玛，交给纳兹格雷尔。', '将玛瑟里顿的徽记交给萨尔玛的纳兹格雷尔。', '这项战胜的消息不光对伊利丹造成打击，$N。对燃烧军团也是……深渊领主指挥官被消灭了。地狱火堡垒的围攻行动对燃烧军团来说已经失去意义。毫无疑问地，所有他们造的孽最终都会转而回归黑暗神庙。$B$B伊利丹要赎罪的日子来了……而且快了。', '从有记忆开始，这是我第一次感受到了安静。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11004, '阴影世界', '空军指挥官阿达利斯在斯克提斯的一次袭击中受了伤。从那个时候起，他就时而昏迷，时而清醒。$B$B我担心他会因为发烧变得神志不清。不过，在为数不多的清醒时刻，他曾要求我找到一瓶用鸦人身上掉落下来的暗影之尘配制出的药剂。他似乎认为这种药剂能让他找到鸦人的首领的巢穴“阴影世界”。$B$B虽然我根本不相信他说的这些胡话，但我担心，如果不帮他找到那样的一瓶药剂，他会一直嚷嚷下去。你愿意帮帮忙吗？', '瑟维里要你进入斯克提斯，从居住在那里的鸦人身上找到6份暗影之尘。', '感谢你，$N。我会给指挥官一小部分……跟他开个小玩笑。剩下的你可以留着，也许你将来用的上。', '你已经取回暗影之尘了吗，$N?', '', '去泰罗卡森林找黑风码头的瑟维里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11005, '鸦爪祭司的秘密', '谢谢你把我的胡言乱语记在心上。一直以来，我们都在千方百计地想要粉碎斯克提斯的统治。现在，我们已经得知三位被称为鸦爪祭司的牧师负责统领整个斯克提斯，不过，从来没有人能够亲眼见过他们——现在我们已经知道为什么会这样了。$B$B跟瑟维里谈谈，利用他发现的药剂找到并杀死伊沙尔、斯卡基克和塞尔利克三位鸦爪祭司。有传言说，他们就居住在黑风湖东岸的奥拉克鸦巢。', '从瑟维里那儿获取暗影药剂。转至斯克提斯，利用暗影药剂找到并杀死伊沙尔、斯卡基克和塞尔利克三位鸦爪祭司。完成任务后向空军指挥官阿达利斯复命。', '你做的很好，$N。你杀死魔爪祭司对敌人造成了很大的打击。', '完成了吗，$N?要不是我受伤，我会亲自杀了那些该死的鸟人。', '', '去泰罗卡森林的黑风码头找空军指挥官阿达利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11006, '更多暗影之尘', '', '', '继续把暗影之尘交给我。你要多少药剂我都可以给你。$B$B这是指挥官的命令。', '看来指挥官并不是胡言乱语。交给我更多的暗影之尘，我就给你另一份药剂。', '', '去泰罗卡森林找黑风码头的瑟维里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11007, '凯尔萨斯和翠绿的魔珠', '耳畔传来轻柔的歌唱声，纳鲁知道你已经获胜。你仿佛听见他们的指示，俯身从凯尔萨斯·逐日者尚在抽搐的尸体上拾起了这块翠绿的魔珠。这东西蕴藏着什么秘密？$B$B或许沙塔斯城的阿达尔知晓内情。', '将翠绿的魔珠交给沙塔斯城的阿达尔。', '<阿达欧的思想与你合而为一。>$B$B那个球体……奇怪。你知道他还活着吗?是的。他就在这里 - 球体的里面。当然他受了很重的伤。他现在呼唤了一股更强大的力量。不，不是伊利丹。$B$B更强大的力量。$B$B欺诈者基尔加丹来了……$B$B不是来这里……$B$B<阿达欧在你的脑海中指示着另一个地方。>$B$B艾泽拉斯。不明地点。$B$B休息一下吧。现在你的兄弟和姐妹们将会重新夺回风暴要塞。$B$B<阿达欧哼起了战斗之歌。>', '你听见我的呼唤了吗?是的……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11008, '轰炸斯克提斯', '你觉得你能成为一个空中卫队的成员？那我们必须瞧瞧你在空中应对敌人的本事如何。$B$B鸦人饲养了一大群不同种类的宠物，用来攻击我们的斥候。我希望你将这些炸弹带去，炸掉鸦人巢穴上面的孵化场。小心看守孵化场的巨型卡利鸟，它们会抓住你稍微走神的瞬间，毫不留情地将你从坐骑上击落。', '找到斯克提斯巢穴上面的巨大的卡利鸟蛋，利用天空卫队的炸弹毁掉它们。完成任务之后回去向空军上尉杜尔因复命。', '干得好，$N!这下子可以让那些鸟人知道何谓空中优势!', '你的工作完成了没?', '', '去泰罗卡森林找黑风码头的空军上尉杜尔因。', '炸毁巨大的卡利鸟蛋', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11010, '轰炸任务', '你有飞行坐骑……这也值得炫耀？你以为自己能熟练驾驭飞行坐骑？$B$B北面的铸魔营地：天罚和南面的铸魔营地：恐怖是我的心腹之患，同样它们也对爱好和平的奥格瑞拉构成了威胁。在邪能火炮的攻击下，天空卫士伤亡惨重，根本无法侦察敌情。$B$B想要证明自己的实力吗？带上这些炸弹，瞄准铸魔营地的邪能炮弹堆投掷吧！当心别被炮弹击中！', '使用天空卫队炸弹炸毁15堆邪能炮弹。', '嗯，我想你毕竟还是有两把刷子。\r\n\r\n做的好。也许老凯勒对你看走眼了。\r\n\r\n<天空士官樊德丽奸笑着。>', '你用加农炮炸掉他们的炮弹堆了吗？', '', '去刀锋山找天空卫队哨站的空军上尉范德里普。', '炸毁邪能炮弹堆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11013, '为伊利达雷效力', '灵翼浮岛……那本是灵翼龙族的避难所，如今却沦为龙喉氏族横行之地。虽然兽人们侵占了我们的领地，可是他们无法削弱龙族强大的魔法力量。凭借这种力量，我们可以掩盖你的真实身份，帮助你安全混入龙喉氏族。$B$B我已经备好一封书信，我要你飞往龙喉营地，将它交给莫格霍尔大王。届时，你将以伊利丹·怒风麾下一名邪兽人的身份开始新的生活。', '转至灵翼浮岛，将伊利达雷服役文书交给龙喉营地的莫格霍尔大王。', '<莫格读了信并大笑。>$B$B死亡骑士?你连死亡骑士的靴子都没办法擦亮，废物。$B$B<莫格仔细地打量你。>$B$B但是好……你或许可以当个苦工。最糟的话，我就把你丢进深渊让你自生自灭……', '<莫格咕哝着。>$B$B你迟到了……', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11015, '灵翼水晶', '你什么都不擅长吗？好吧。你虽说有些愚钝，不过还是可以替我们做些事的。猎杀灵翼浮岛上的生物，你或许可以从它们身上找到灵翼水晶。替我收集一些灵翼水晶，今天的任务就算完成了。', '将30块灵翼水晶交给影月谷龙喉营地的工头瓦尔库勒·龙息。', '今天就到这里吧，孩子。明天如果你还活着再来找我。', '虚空水晶有很多用处。主要是用来制造武器和护甲……', '', '去影月谷找灵翼浮岛的工头瓦尔库勒·龙息。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11016, '虚空矿洞剥石者的外皮', '嗯，剥皮师？这儿可是剥皮师的天堂啊！猎杀水晶蔟附近的剥石者，替我收集一些虚空矿洞剥石者的外皮。', '将35张虚空矿洞剥石者的外皮交给影月谷龙喉营地的工头瓦尔库勒·龙息。', '今天就到这里吧，孩子。明天如果你还活着再来找我。', '我们拿镰夺怪皮革来制作护甲内里和建筑陷阱。', '', '去影月谷找灵翼浮岛的工头瓦尔库勒·龙息。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11017, '灵尘花粉', '采药者？！很有趣的营生啊……我们的法师和萨满祭司正好需要你的帮助。灵翼浮岛上的灵尘灌木拥有奇异的花粉，对他们研究魔法很有帮助。替我收集一些灵尘花粉，今天的任务就算完成了。', '将40份灵尘花粉交给影月谷龙喉营地的工头瓦尔库勒·龙息。', '今天就到这里吧，孩子。明天如果你还活着再来找我。', '像我说的，虚空之尘花粉是我们法术施放者使用的东西。', '', '去影月谷找灵翼浮岛的工头瓦尔库勒·龙息。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11018, '虚空矿石', '矿工！$B$B<瓦尔库勒向你敬礼。>$B$B咱们真是志趣相投！瓦尔库勒也是一名矿工！没有什么比蓬头垢面地挖掘矿脉更有趣的事了，对吧？$B$B寻找虚空矿脉，替我收集一些虚空矿石。', '将40块虚空矿石交给影月谷龙喉营地的工头瓦尔库勒·龙息。', '今天就到这里吧，孩子。明天如果你还活着再来找我。', '在那里的贾格会用矿石来加强我们的武器和护甲。', '', '去影月谷找灵翼浮岛的工头瓦尔库勒·龙息。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11020, '缓慢的死亡', '龙喉兽人几乎在每丛水晶簇都设立了苦工营地。直接杀掉兽人必定会惹来不必要的麻烦，但是我们可以略施妙计，既能削减他们的数量，又不会引起莫格霍尔的怀疑。$B$B在影月谷中猎杀那些被感染的野生动物，取出它们的邪能腺体。将邪能腺体和这团羊肉混合起来，放在苦工营地附近。他们只要吃上一口就会倒地身亡！', '影月谷龙喉营地的雇佣兵亚兹尔要你将邪能腺体和亚兹尔的羊肉的混合物投放在12座龙喉苦工营地附近，毒杀龙喉苦工。', '<亚吉欧低声私语。>$B$B做的好，$N。低调一点。明天再来找我，我们可以再做一次。', '这是件肮脏的工作，$N。', '', '去影月谷找灵翼浮岛的雇佣兵亚兹尔。', '在龙喉苦工营地投毒', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11021, '伊沙尔的历书', '这本神秘的书籍是从鸦爪祭司伊沙尔的尸体上找到的。书页中有一些你难以理解的神秘符号和天体图表。$B$B你根本看不懂上面的文字，似乎是某种古老的鸦人语。或许你应该将它交给空军指挥官阿达利斯。', '将伊沙尔的历书交给斯克提斯北面的空军指挥官阿达利斯。', '你带来了什么东西?我无法辨识书中的文字，$N……由于流血的缘故……影响了我的视力。', '你有东西要给我看吗?', '', '去泰罗卡森林的黑风码头找空军指挥官阿达利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11023, '继续轰炸！', '$N，邪能火炮依然令我们头痛不已。$B$B别误会，上次你出色地完成了轰炸任务。可惜功亏一篑，那帮该死的恶魔迅速补充了弹药供给。如此一来，天空卫士飞越铸魔营地时平添了许多危险，奥格瑞拉的安全状况也令人堪忧。$B$B怎么样？再来一次空袭如何？', '使用天空卫队炸弹炸毁15堆邪能炮弹。', '了不起的工作，$N!我本来想叫你飞上空中再次轰炸他们，但是这里的规定是要确定所有的飞行员可以获得充分的休息。抱歉，规则不是我定的，但是我确定你一定得这样做$B$B我们明天再见，好吗?', '轰炸任务进行的如何呢?', '', '去刀锋山找天空卫队哨站的空军上尉范德里普。', '炸毁邪能炮弹堆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11024, '贫民窟的盟友', '贫民窟中有个名叫瑞拉克的鸦人……他是值得信赖的。把这本书籍……交给他看看。$B$B<阿达利斯将书递给你之后又陷入了神志不清的状态。>', '将伊沙尔的历书交给沙塔斯城贫民窟中的救赎者瑞拉克。', '这不可能……这曾经属于一个魔爪祭司所有。你从何处得到这个东西?', '解释一下!为什么你身上有着司凯堤斯的味道!', '', '去找沙塔斯城贫民窟的救赎者瑞拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11025, '埃匹希斯水晶', '经过适当的处理之后，奥格瑞拉山脉出产的水晶就会展示出多种诡异的能量。$B$B居住在山顶的所有生物都在觊觎着这些水晶碎片，企图利用水晶实现自己的梦想，它们之间甚至形成了某种默契。$B$B要帮助我们，你自己首先必须要了解这种埃匹希斯碎片，去收集一些埃匹希斯碎片，把它们带回来给我吧。奥格瑞拉的任何生物身上都可能会带有埃匹希斯碎片，你还可以在剥石者开采水晶的挖掘地附近找到这种碎片。', '取得5块埃匹希斯碎片。', '<裘阿洛左边的头开始讲话。>$B$B这样就可以了。$B$B记住，$N，这些裂片的价值不在于它们值多少钱。它们的价值甚至不在于你能用它们熔铸出什么好东西，虽然这个观点还有待争议。$B$B<裘阿洛右边的头接着把话说完……>$B$B真正的价值在于你取得它们的这段旅程。', '当你了解那些裂片和水晶的本质与用途，你就能对底下的巨魔同胞们提供更大的帮助。$B$B那些裂片的名字来自于曾经居住在山顶的一个已经灭亡的古阿拉卡文明。$B$B你把那些裂片带来了吗?', '', '去刀锋山找奥格瑞拉的库洛尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11026, '放逐恶魔', '朋友，你来的真是时候！我们需要帮助。做为回报，你会得到某件珍奇的器物，这对你我都有好处。$B$B我们早已摒弃残暴的陋习，但是附近的恶魔对奥格瑞拉和天空卫队的安全造成了威胁。这些恶魔能反复以新的形体重生，简直杀之不尽！$B$B利用这颗水晶打开放逐之门。如果你在传送门附近杀死恶魔，他们的精华就会被卷入传送门中，永远地从这个世界上消失！', '转至刀锋山的铸魔营地：天罚或是铸魔营地：恐怖，利用放逐水晶放逐15个恶魔。', '这会让他们学乖!喔，当然，这是你的报酬。$B$B北方炼冶场:愤怒的恶魔们在他们的南方边界上制造了一个特殊的传送门。这个实验性的门被用来扩充炼冶场，我想我不用告诉你他们扩充过大所会对我们带来什么影响。$B$B然而，如果我们是你，我们会把这个暗色符文拿给贾克，并且问他你该如何帮忙。不要对他太严格，$N，他跟你一样才刚来这个地方。', '我们相信你已经使用驱逐水晶把整个燃烧军团的杂碎们送回去了?!', '', '去刀锋山找奥格瑞拉的科隆克。', '放逐恶魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11027, '你有黑暗符印吗？', '那个营地的恶魔时常修理他们的传送门。贾克说$N这一次给那些恶魔好看!$B$B但是，贾克要另一个暗色符文来制作晶铸暗色符文给你。', '假如小$r没有暗色符文，你就去跟克朗克说话。他试着每天做一个暗色符文!也许你可以去他的袋子里拿一个?!', '哈哈，太好了!贾克喜欢暗色符文!你拿走贾克之前做好的晶铸暗色符文。$B$B$N，记住，控制恶魔守卫剥蚀者，然后用锤子击碎夏图欧传送门的魔法护盾。释放另一只恶魔然后跟他战斗才能控制他!接着继续击碎护盾，控制更多恶魔直到没有为止!$B$B然后你就拯救了奥格瑞拉!', '那个营地的恶魔时常修理他们的传送门。贾克说$N这一次给那些恶魔好看!$B$B但是，贾克要另一个暗色符文来制作晶铸暗色符文给你。$B$B假如小$r没有暗色符文，你就去跟克朗克说话。他试着每天做一个暗色符文!也许你可以去他的袋子里拿一个?!', '', '去找刀锋山的甘克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11029, '粗糙的伪装', '$N，包里装的是一件伪装服。看起来不太靠谱，是吧？$B$B我曾为星界财团的走私贩子们制作这样的伪装服，帮助他们搜寻稀有的古籍。斯克提斯的中心小岛——泰罗克之墓上居住着一位名叫萨哈克的鸦人书吏，他年岁已高，双目近乎失明。$B$B穿上伪装跟他谈谈，取回那本名叫《仇敌的血脉》的书籍。$N，小心。其它鸦人是可以轻易看穿这件伪装服的。', '穿上粗糙的鸦人伪装服，从萨哈克那儿取得《仇敌的血脉》，然后向哈吉克复命。', '太好了!这本书记载了泰洛克古老敌人的子嗣。有人预言他们的死亡会随着泰洛克的归来而发生。', '那本书，$N。你弄到它了吗?', '', '去泰罗卡森林找黑风码头的哈吉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11030, '未来的天空卫队游侠', '$C，我们遇到了麻烦——瞧瞧这帮孩子。自从天空卫队驻扎到奥格瑞拉附近后，孩子们便整日吵着要加入天空卫队。$B$B做为父亲，我为此倍感自豪，也想帮助他们达成梦想。你愿意转至北边或南边的铸魔营地，利用邪能水晶熔炉帮我制作不稳定的野兽合剂吗？$B$B这种合剂需要10块埃匹希斯碎片。我们本应该为你提供原料的，可惜现在恰好缺货。', '取得不稳定的野兽合剂。', '你是个救星，$N。我们的儿子听到这消息会非常兴奋!$B$B好，所以一个解决了还有另一个。我们有跟你说他们需要另一瓶魔法药水的事吧?', '你弄到那个魔法药水了吗?那对小托卡司而言是全世界。', '', '去刀锋山找奥格瑞拉的托尔库斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11031, '远离大法师之路', '', '', '小心地做下一个决定。我们尽最大的努力来配合我们的盟友，但就连达拉然的资源都有他们的底限。', '你决定违背先前的选择?我想我可以帮你改变它。最终达拉然在意你的忠诚比你选择如何表现它来的多。$B$B它索费不低。当然，我需要你把旧的戒指交回来。', '', '去找逆风小径的大法师蕾尔达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11032, '远离保卫者之路', '', '', '小心地做下一个决定。我们尽最大的努力来配合我们的盟友，但就连达拉然的资源都有他们的底限。', '你决定违背先前的选择?我想我可以帮你改变它。最终达拉然在意你的忠诚比你选择如何表现它来的多。$B$B它索费不低。当然，我需要你把旧的戒指交回来。', '', '去找逆风小径的大法师蕾尔达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11033, '远离刺客之路', '', '', '小心地做下一个决定。我们尽最大的努力来配合我们的盟友，但就连达拉然的资源都有他们的底限。', '你决定违背先前的选择?我想我可以帮你改变它。最终达拉然在意你的忠诚比你选择如何表现它来的多。$B$B它索费不低。当然，我需要你把旧的戒指交回来。', '', '去找逆风小径的大法师蕾尔达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11034, '远离治愈者之路', '', '', '小心地做下一个决定。我们尽最大的努力来配合我们的盟友，但就连达拉然的资源都有他们的底限。', '你决定违背先前的选择?我想我可以帮你改变它。最终达拉然在意你的忠诚比你选择如何表现它来的多。$B$B它索费不低。当然，我需要你把旧的戒指交回来。', '', '去找逆风小径的大法师蕾尔达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11035, '危险的天空', '龙喉兽人在灵翼浮岛的东北边缘设立了港口，用于运送灵翼水晶和灵翼圣物。龙喉碎天者负责将货物从港口运往龙喉要塞，龙喉晋升者则担当起地面的守卫工作，防止入侵者滋扰生事。$B$B我们可以利用龙喉空港这个防御缺口，狠狠地打击龙喉兽人的嚣张气焰。$B$B飞往龙喉空港，袭击运送货物的龙喉碎天者，夺回被偷走的灵翼圣物！', '将10件灵翼圣物交给影月谷龙喉营地的雇佣兵亚兹尔。', '<亚吉欧低声的跟你说话。>$B$B你帮了虚空之翼一个很大的忙，$N。慢慢地，我们会打垮那些龙喉兽人。他们内部开始感染一种疾病 - 一种没有解药的疾病……$B$B假如你有兴趣继续在龙喉航线执行任务的话，明天再来找我。', '死掉的兽人才不会走漏风声，$N。你一定要确保那些龙喉输送者没有逃走。', '', '去影月谷找灵翼浮岛的雇佣兵亚兹尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11036, '食物储备！', '首先，我得承认我不太明白这份订单是干嘛用的。不过，火箭主管弗斯拉格列出了详细的说明——这批果脯需以品质上等的水果为原料，必须经过严格的防腐和密封处理。$B$B他还提出了别的要求，失重状态、低气压什么的。我根本就不懂这些术语，好在他开出的价格不错，那么我就按他的吩咐交货吧。总之，将这个食品箱交给52区的火箭主管弗斯拉格。沿着这条道路进入虚空风暴后一直走就到52区了。', '将这箱果脯交给虚空风暴52区的火箭主管弗斯拉格。', '<主管检视木箱里的东西。>$B$B看起来都不错。清单上的项目又完成了一样。现在我们所要做的就是让火箭离开地面!', '这是老欧洛克要送给我的东西吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11040, '给火箭主管的零件', '我与地精合作的次数，你用一只手就能数得过来，更多的时候我们是竞争关系。但是，当火箭主管弗斯拉格说他需要材料时，我还是不忍心拒绝他的请求。$B$B这只箱子里装的都是我不需要的零件，不过火箭主管或许能用得上。如果你正要去52区的话，就顺路把这箱子带给他，好吗？$B$B说不定装上这些做工精细的侏儒零件后，他的工程制品就不会爆炸了！', '将波希的备用零件交给虚空风暴52区的火箭主管弗斯拉格。', '我连某些零件是用来干嘛的都不知道!我确定我可以利用其中一些零件，但我从来没想过我必须学着用地精的方式来思考!', '那个木箱看起来很像哥布尔工程大师的东西。是波西派你来的吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11041, '未完的工作……', '以圣主之名……为伊利丹的荣耀而战！$B$B莫格霍尔大王下令，不惜一切代价确保灵翼浮岛的安全。岛上的虚空幼龙要么被我们俘虏，要么已经逃之夭夭；剥石者趁势猖獗起来，严重影响了水晶的开采工事。$B$B杀光它们，还有母兽巴莱什以及她的配偶阿尔沃安。$B$B这是莫格霍尔大王的命令！$B$B<看来这个兽人正被此事烦得焦头烂额，不妨趁此机会证明你对莫格霍尔的忠诚！>', '杀死10只灵翼矿洞剥石者和母兽巴莱什。完成任务后向龙喉营地的莫格霍尔大王复命。', '所以你从我手下的监督者遗体身上取得了命令并自己接下了任务?你的确让莫格印象深刻。做的好……', '谁敢接近莫格?最好是很重要的事。', '', '去影月谷找灵翼浮岛的莫格霍尔大王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11049, '寻找灵翼龙卵', '如果你在灵翼浮岛上发现灵翼龙卵，就把它们统统带回来给我。$B$B不过，灵翼龙卵极其罕见。找不到的话，也不必产生挫败感。大多数灵翼龙卵都被龙喉兽人运往了未知的地方。$B$B你能在岛上的各种生物身上找到灵翼龙卵，它们零星地分布在水晶簇、矿洞、虚空矿脉或是灵尘灌木附近。$B$B保持低调，别引起莫格霍尔的注意。', '将一枚灵翼龙卵交给影月谷龙喉营地的雇佣兵亚兹尔。', '奈尔斯阿拉古会非常高兴，$N。做得好。', '猎蛋行动进行的怎么样了?', '', '去影月谷找灵翼浮岛的雇佣兵亚兹尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11050, '所有的龙卵', '', '', '你是个真正的英雄，$N。', '我们不需要那些蛋落入不对的人手里，$N。把任何你找到多馀的蛋都交给我。$B$B只要记得行事低调避免引起怀疑!', '', '去找影月谷的雇佣兵亚兹尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11051, '放逐更多恶魔', '我们一直密切注视着铸魔营地的动向，恶魔们正在全力重建被破坏的迁跃门。$B$B如果你还想要黑暗符印的话，不妨再碰碰运气。带上放逐水晶，消灭盘踞在铸魔营地的恶魔。你确实想要帮助我们减轻恶魔的威胁，对吧？$B$B当然这事真的要看运气，黑暗符印的制作工艺存在谬误，所以你可能会得到一枚黑暗符印，也可能是别的玩意。', '转至刀锋山的铸魔营地：天罚或是铸魔营地：恐怖，利用放逐水晶放逐15个恶魔。', '我们很希望制造暗色符文的过程是极简单的，$N。唉，但它不是。请收下这个包包看看里面，知道我们今天努力了什么。我们不敢自己看。$B$B记住，如果你得到一个暗色符文，拿去和贾克交换一个晶铸暗色符文。然后你就能再一次瓦解夏图欧的传送门。$B$B喔，还有$N，别忘记明天再来这里拿驱逐水晶。永远都有更多恶魔需要被驱逐。', '一个像你一样老练的专家在驱逐恶魔上应该不会有任何困难。你没有困难吧，$r?', '', '去刀锋山找奥格瑞拉的科隆克。', '放逐恶魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11054, '新的监工：正确的选择', '你就是新来的监工吧？所有的监工都得配备一件合适的训诫刑具。在你跑出去教训那些懒惰的苦工之前，你最好给自己搞一双这样的训诫靴。按照传统，监工必须自己收集制造训诫靴所需的材料，你也不例外。$B$B我需要一些结缔皮和泰拉图斯的硬皮。泰拉图斯就在虚空风暴北部边境处的边缘生态圆顶中。', '影月谷龙喉营地的高级监工玛德拉普要你给他带回10张结缔皮和1张泰拉图斯的硬皮。', '啊!你毕竟是个监督者。那只过大的蜥蝪是许多兽人的克星!$B$B<大监督者马朗开始制作武器。>', '那里有苦工要被惩罚，$N!动作快!', '', '去影月谷找灵翼浮岛的高级监工玛德拉普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11055, '训诫靴：懒惰苦工的惩戒', '这是你的训诫靴。世界上有许多训诫靴，但这一双是你的。$B$B做为一名监工，你必须利用训诫靴好好教训那些不服从命令的苦工。只要使用得当，苦工们自然会听命于你，乖乖地替我们做事。$B$B去前面的水晶田监督苦工吧，惩罚那些懒散的家伙，让他们尝尝训诫靴的厉害！', '影月谷龙喉营地的高级监工玛德拉普要你惩罚20名懒惰的龙喉苦工，然后将训诫靴还给他。', '辛苦的一天!但很值得，对吧?看到那些没用的家畜认真的挖掘那些水晶让你的心很温暖……总之，今天就这样吧。明天再来另一回合的回力靴惩罚。', '关键全在于腕部的技巧，$N。', '', '去影月谷找灵翼浮岛的高级监工玛德拉普。', '教训龙喉苦工', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11056, '哈吉克的协议', '别让别人注意到我们的谈话。阿达利斯会不高兴的。$B$B$N，我在鸦人社会中属于身份最低的那个等级。根据泰罗卡的法律，我本该被鸦爪祭司献祭给他们所崇拜的黑暗力量。你刚才说，那些鸦爪祭司正谋划着将泰罗卡召唤回这个世界，如果这是真的，那么不论你的上司说什么，你也一定要想办法去阻止他们！$B$B有些东西你肯定会用得上，我过去在上层夏尔克鸦巢的房子里藏了一个包裹，把它带回来给我！', '进入斯克提斯的东部区域，在哈吉克的住处中找到哈吉克的包裹，然后把包裹带回去给他。', '非常好，$N。你会看到我说的话是真的。', '你回来了，$N。我才开始想着你会不会放弃我了。', '', '去泰罗卡森林找黑风码头的哈吉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11058, '埃匹希斯圣物', '很久以前，在奥格瑞拉居住着一支名叫埃匹希斯的鸦人氏族。现在，埃匹希斯氏族早已灭绝，他们在这一带留下了许多文明的遗物——埃匹希斯圣物。$B$B我们发现，采用适当的方法就可以令它们展示出潜在的能量。每件埃匹希斯圣物都有独特的色彩序列，只要以正确的顺序安放水晶，就能激发圣物中所蕴藏的潜能。$B$B你必须使用埃匹希斯碎片来引导埃匹希斯圣物内的能量。当你利用埃匹希斯圣物获得埃匹希斯的感应效果后，就回来找我吧。', '利用埃匹希斯圣物获得埃匹希斯的感应效果，然后。', '<裘阿洛满意地对你的成就点点头。>$B$B你的头脑很聪明，$N。我们花了更久的时间才成功地利用圣物。$B$B既然你已知道方法，你就可以做很多想做的事。只要记住它们需要顶尖裂片才能启动。', '你学会如何使用顶尖圣物了吗?我们和北边的沙塔尔天空卫队都对你所学到的东西很有兴趣。', '获得埃匹希斯的感应效果', '去刀锋山找奥格瑞拉的库洛尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11059, '纪念碑的守护者', '你已经掌握了小块埃匹希斯圣物的使用方法，不过你应该也留意到了它们环绕着体积更大的物体。$B$B这些埃匹希斯纪念碑的使用方法与埃匹希斯圣物如出一辙，不过需要四个人使用更多的埃匹希斯碎片才能激活它们。$B$B在激活埃匹希斯纪念碑的过程中，它还会召唤出埃匹希斯卫士。但是，这些水晶构造体生物早已背叛了它们的鸦人主子，演变成了威胁奥格瑞拉的祸害。$B$B去杀掉一尊埃匹希斯卫士，并带回它的徽记做为凭证。', '将埃匹希斯卫士的徽记交给刀锋山奥格瑞拉的库洛尔，作为你击杀埃匹希斯卫士的证据。', '<裘阿洛的脸上堆满对你尊敬的笑容。>$B$B我们不仅佩服你和你朋友的聪明机智，也欠你一份人情，奥格瑞拉和天空卫队都是，感谢你帮忙保卫我们在这里的生命。$B$B记住，$N，你任何时候都可以召集其它人回到任何一个大型顶尖纪念碑去使用它们;只要你有足够的顶尖裂片来启动它。', '我们厌恶暴力，但至少我们派你去对抗的结构不是一个活的生命。$B$B说到这，你弄到那个头颅了吗?', '', '去刀锋山找奥格瑞拉的库洛尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11060, '晶铸黑暗符印', '', '', '小$r，记住，当你控制了那个剥蚀者，你就用它的锤子来粉碎那个星移门的庇护并释放出里面的恶魔。$B$B然后你摧毁那个恶魔并控制它。然后又一个恶魔过来你再控制它，直到埃雷达尔监督者出现。$B$B然后你也杀了他!!!', '恶魔正扩大建造炼冶场:愤怒。很快的，他们就会变的很强大并粉碎我们。你要先去毁了他们!$B$B夏图欧的传送门是关键，但它受到一种魔法护盾和一个叫剥蚀者的恶魔所保护。我们强大的术士制作了特殊的暗色符文让你能控制那个剥蚀者。$R给贾克暗色符文，我们给$r晶铸暗色符文。$B$B控制那个剥蚀者并尽可能支配从那个大门进出的恶魔来阻止他们!', '', '去找刀锋山的甘克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11061, '父亲的职责', '要制作另一种合剂，只能利用巴什伊尔码头的水晶熔炉。那是一处虚灵的营地，他们对外来者很不友好，恐怕你得费些力气才能得到这种合剂。$B$B巴什伊尔码头的位置……唔，乘坐飞行坐骑往东北偏北方向前进，飞越铸魔营地：天罚之后就到了。巴什伊尔的水晶熔炉就在码头的东北角。$B$B$N，谢谢你。对我的孩子们来说，它意味着整个世界！', '为他取得不稳定的巫术合剂。', '我们太感谢你了，$N!$B$B现在有了这两瓶药水，虽然它们很不稳定，我们还是能将一个儿子送到北方的天空卫队前哨。$B$B来，等一下，我们叫他们其中一人来。$B$B<托卡司右边的头用低沉的咆哮声调用他的儿子。>', '那个巫士的药水绝对会让我的儿子们变的更聪明，那对他们到了沙塔尔天空卫队之后要做的事会有很大的帮助。', '', '去刀锋山找奥格瑞拉的托尔库斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11065, '捕捉一些以太鳐！', '愿意帮助天空卫队和奥格瑞拉吗？$B$B$g帅小伙子:俏姑娘;，别急着走开，听我说。我们需要补充飞行坐骑！在轰炸铸魔营地以及与巴什伊尔码头交火的过程中，以太鳐损伤惨重。$B$B以太鳐看来是不错的飞行坐骑，你可以在漩涡峰和东北方的水晶之脊上空找到它们的踪迹。你只需用索套捆住以太鳐就行了，不用将它们带回哨站，我们稍后就会去捕捉动弹不得的以太鳐。$B$B怎么样？', '天空卫士卡提要你用牧绳捕捉5只以太鳐。', '万岁!做的好，$N!那些鳍刺会是非常棒的坐骑!$B$B别走太远孩子……沙塔尔天空卫队永远都需要一个像你一样有天赋的$g男人:女人;!', '你捆绑好一些苍穹鳍刺了吗?你看起来还满会使用绳索的，所以应该花不了你太多的时间。', '', '去刀锋山找天空卫队哨站的天空卫士卡提。', '捕捉以太鳐', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11066, '捕捉更多以太鳐！', '嗯，我希望你能帮助天空卫队捕获更多的以太鳐！我看得出来，你是个使用索套的能手！如此一来，我们不仅能补充飞行坐骑的数量，还能更好地保护奥格瑞拉。$B$B你可以在漩涡峰和东北方的水晶之脊上空找到以太鳐的踪迹。$B$B你愿意帮忙吗？', '天空卫士卡提要你用牧绳捕捉5只以太鳐。', '你再一次的让我惊艳!告诉你……你何不明天再回来，我们现在先让绳子休息一下?$B$B<卡缇笑着。>$B$B非常感谢你，$N!', '你对我们贡献良多，$N。我要你知道我们真的很感谢你所做的一切，让我们有足够存量的最新坐骑!', '', '去刀锋山找天空卫队哨站的天空卫士卡提。', '捕捉以太鳐', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11067, '壮志凌云：粗野的特罗普', '龙喉氏族看来待你不薄啊，$N。就连我这么卑微下等的家伙也有机会跟你玩玩了。现在，要想证明你对他们的价值，就必须先打败我。$B$B看我的厉害吧，看我一口气用龙尾巴把你像掸跳蚤一样打飞出去……$B$B你准备好以后我们就可以开始了。', '驾驶飞行坐骑紧紧跟随粗野的特罗普。击败粗野的特罗普之后，将你的胜利消息报告给向影月谷龙喉营地的亚恩·诺斯利。', '有趣……你的下一场比赛绝对会更困难。克洛克不是省油的灯。', '川普击败了我一些最厉害的骑手。别让他的污秽骗了你。', '击败粗野的特罗普', '去影月谷找灵翼浮岛的亚恩·诺斯利。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11070, '壮志凌云：空军指挥官穆维里克', '三年多的血泪生涯啊……有甜蜜也有悲伤，不过大多数时候是悲伤……你不会知道那些真正战场的士兵，我当初的那些战友真哭起来喊起来是什么样子的。$B$B“他们骑着马就进塔了！”“联盟基地怎么那么难打！”“急救站丢了，速度输！”“别拿落雪，听指挥啊！”$B$B这群白痴……$B$B反正后来，黑暗之门一开，我就马上离开了那个村子，来到了这里。老子现在壮志凌云，要当龙喉氏族的第一骑手！你要是也这么想，就得先打败我。$B$B准备好以后就开始吧。', '驾驶飞行坐骑紧紧跟随空军指挥官穆维里克。击败空军指挥官穆维里克之后，将你的胜利消息报告给向影月谷龙喉营地的亚恩·诺斯利。', '嗯看来现在只有你和队长了，蛮兵。祝你好运!你会需要的!', '穆维里克是我见过最有天赋的骑手。唯一让他无法坐到顶尖兽人位置的问题，就是他的鲁莽。', '击败空军指挥官穆维里克', '去影月谷找灵翼浮岛的亚恩·诺斯利。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11071, '壮志凌云：汤告鲁士·碎空', '你竟然有胆挑战我汤告鲁士？你周围的世界会彻底堕入黑暗，而天堂也会被我的流星击为碎片。$B$B你不会有任何机会的，士兵。不过，你既然这么渴望一死……$B$B若只是为了向那些做着同样愚蠢的梦，犯着同样愚蠢的错误人们展示我的力量，那么我就来好好享受你的惶恐与不安吧。$B$B你准备好了我们就开始！', '驾驶飞行坐骑紧紧跟随汤告鲁士·碎空。击败汤告鲁士·碎空之后，将你的胜利消息报告给向影月谷龙喉营地的亚恩·诺斯利。', '我从没想过会有人那么厉害能击败碎天者。你知道这代表了什么意义吧?你现在是顶尖兽人!你一定要守住你的头衔。', '第二名不是那么糟，$N。你可以取代穆维里克在阵容里的位置……', '击败汤告鲁士·碎空', '去影月谷找灵翼浮岛的亚恩·诺斯利。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11072, '仇敌的血脉', '这本书中列有斯克提斯爪之祭司所囚禁着的所有泰罗克的宿敌的后裔，包括猎手吉萨拉克、水晶巨人卡尔洛格，还有被贬为异端的黑暗尖啸者阿克卡莱和风怒者瓦克奇斯。必须要在泰罗克回到这个世界之前将他们全部杀死。$B$B你首先需要夺取一些迷失鸦人身上带着的卷轴，然后在斯克提斯的召唤法阵中烧掉卷轴，召唤并杀死它们，从它们身上各找一样信物带回来。要知道，它们都是非常非常强大的存在，你最好带上几个朋友一起去。', '在斯克提斯找到召唤法阵中央的徽记堆，在此使用10个迷失卷轴，并击败每一只被召唤出来的后裔。完成之后带着从它们身上取下的信物回去向哈吉克复命。', '太好了!收下这个。我用你取得的物品准备了这个包裹。它们会让你召唤泰洛克。$B$B小心，$N。他是世界上最强大的阿拉卡。别小看他!', '完成你的任务了吗，$N?', '', '去泰罗卡森林找黑风码头的哈吉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11073, '泰罗克的毁灭', '对于你和那只鸦人囚徒之间的交易和计划，我……我曾经假装没有看见。现在看来，你的直觉果然没有错，你的确应该和他合作。$B$B但你必须也得理解我……站在我的立场上，比起让我认可你将泰罗克召唤到这个世界上来的行为，还不如让我直接去面对一场兵变算了。你的行动风险非常大。$B$B现在，快带上哈吉克为你准备的东西，继续你的计划吧。到时候，我会命令我的人尽可能支持你的。你最好也带上一小股部队。恐怕你只有这一次机会了。', '将哈吉克准备好的失落的祭品带到斯克提斯中央的徽记堆，召唤出泰罗克并击败它。完成这个任务之后回去向空军指挥官阿达利斯复命。', '你让我们感到非常骄傲，$N。我会让沙塔斯的人都知道你的行为。天空卫队永远都欠你一份人情。', '完成了吗，$N?泰洛克被击败了吗?', '', '去泰罗卡森林的黑风码头找空军指挥官阿达利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11074, '仇敌的血脉', '这本书中列有斯克提斯爪之祭司所囚禁着的所有泰罗克的宿敌的后裔，包括猎手吉萨拉克、水晶巨人卡尔洛格，还有被贬为异端的黑暗尖啸者阿克卡莱和风怒者瓦克奇斯。必须要在泰罗克回到这个世界之前将他们全部杀死。$B$B你首先需要夺取一些迷失鸦人身上带着的卷轴，然后在斯克提斯的召唤法阵中烧掉卷轴，召唤并杀死它们，从它们身上各找一样信物带回来。要知道，它们都是非常非常强大的存在，你最好带上几个朋友一起去。', '从斯克提斯的迷失鸦人身上收集迷失卷轴，然后将它们拿到召唤法阵的徽记堆内，召唤出泰罗克仇敌的后裔，并击败它们。然后带着阿克卡莱之爪、卡尔洛格之脊、瓦克奇斯之鳞和吉萨拉克之爪回去向哈吉克复命。', '太好了!收下这个。我用你取得的物品准备了这个包裹。它们会让你召唤泰洛克。$B$B小心，$N。他是世界上最强大的阿拉卡。别小看他!', '我要每个泰洛克劲敌子嗣的象征物品。只有这样我们才能准备好召唤泰洛克。', '', '去泰罗卡森林找黑风码头的哈吉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11076, '回收货物', '我们的劳动成果！成堆的货物被散乱地丢弃在矿洞中！当前的情况是一片混乱，我们根本没法取回货物。$B$B$N，这就是我叫你过来帮忙的原因。你在这里的日常工作就是深入矿洞，收集那些被矿工抛下的货物。$B$B将灵翼矿洞的货物带回来，交给我或是我的姐妹。', '影月谷灵翼矿洞的矿洞女王要你取回15份虚空矿洞的货物。', '做的好，$N。明天再来矿坑深处进行另一次的任务。', '你收集好货品了吗?', '', '去影月谷找灵翼矿洞的矿洞女王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11077, '龙？不是问题', '被惊醒的虚空龙引发了一连续的骚动，混乱的场面激怒了其它居住在矿洞中的生物。其中，虚空矿洞剥石者和虚空矿洞掠食者简直是龙喉氏族的眼中钉。你必须帮助我们清除这些野兽，我要你把这当做日常的工作来做。$B$B去吧，尽量削减它们的数量！', '影月谷灵翼矿洞的龙喉工头要你杀死15只虚空矿洞剥石者和5只虚空矿洞掠食者。', '今天就到这里吧，监督者。明天再来进行另一次的清除。', '镰夺怪侵扰的问题解决的怎么样了?', '', '去影月谷找灵翼矿洞的龙喉工头。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11078, '统治天空', '当你在这附近飞行时，一定注意到了那几条在高空盘旋的巨龙，不过想必你还没有跟它们交过手吧？$N，去帮我们干掉那些巨龙如何！$B$B雷文达克和欧比斯迪一直盘踞在奥格瑞拉上空，因斯迪安和弗雷文则在东北方的高空作威作福，它们在各自的领地上修筑了巢穴。如果你和你的朋友能打破巢穴中的龙蛋，必定会激怒巨龙。$B$B将龙齿带回来给我，做为你击杀巨龙的凭证。天空的统治者要么是它们，要么就是我们。', '收集龙齿。', '很好!那些牙齿看起来利的可以咬断任何东西!$B$B让我鼓励你和你的朋友继续维持这样的表现!那些龙是凶猛的掠夺者让天空变的非常危险。$B$B你或许也注意到，龙鳞。我听说如果你在它们身上各取得一个鳞片，它们很适合用来做强大的披风。如果你不满意得到的披风，我很乐意用一个顶尖水晶来做交换。', '你的任务进展的如何，$N?我不需要告诉你这对我们继续在这附近飞行有多重要吧。', '', '去刀锋山找天空卫队哨站的天空指挥官凯勒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11079, '甘克的魔鞭', '卡提觉得，聪明人也有脑子进水的时候，甘克竟然不愿意思考。我想让你来对付那帮恶魔！$B$B铸魔营地的首领手中都握着一根魔鞭，用来抽打那些恶魔。为甘克夺回一根鞭子！$B$B你可以在铸魔营地的绿色水晶棱柱附近利用埃匹希斯碎片召唤恶魔首领。他们名叫迦瓦诺斯、布拉克休斯、萨克辛和莫尔葛焚化者。', '取得一根魔鞭。', '贾克喜欢皮鞭。或许贾克会用皮鞭来鞭打恶魔!$B$B我跟$r说$r只要有朋友和很多裂片$r任何时候都可以召唤恶魔首领。', '你弄到皮鞭了吗?', '', '去刀锋山找奥格瑞拉的甘克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11080, '埃匹希斯的顿悟', '既然你已经感受到了埃匹希斯的感应所带来的启迪，那么就继续探索埃匹希斯圣物的奥秘吧。你的发现会使我们获益匪浅！$B$B增强你的能力与埃匹希斯圣物之间的关联，你就能领悟到更高深的知识，这就是埃匹希斯的顿悟。$B$B当你利用埃匹希斯圣物获得埃匹希斯的顿悟效果后就回来找我吧。', '利用埃匹希斯圣物获得埃匹希斯的顿悟效果。', '你处理圣物的睿智再一次令我们惊艳，$N。我们可以建议你每天与圣物交流至少一次，以维持如此的心智敏锐度吗?', '你从顶尖圣物取得了放射增益吗?', '获得埃匹希斯的顿悟效果', '去刀锋山找奥格瑞拉的库洛尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11081, '暗血大逃亡', '这份文档概述了暗血破碎者的叛逃计划。看来他们企图利用那只虚空龙分布我们的注意力，想要借此机会集体逃亡。矿洞中横七竖八地躺满了暗血破碎者的尸体，很明显，他们的计划失败了。$B$B将这份逃亡计划交给矿洞女王。', '将暗血逃亡计划交给矿洞女王。', '做的好，监督者。莫格会知道你为龙喉做的杰出表现。$B$B现在回去找这些黑暗之血无赖。他们策划逃亡?他们敢违抗外域真正的领主?他们的主人会为此付出代价!', '这是什么?', '', '去影月谷找灵翼矿洞的矿洞女王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11082, '寻找真相', '这群愚蠢的矿工居然还制订出了逃跑计划。我们必须揪出煽动他们叛逃的幕后主使，然后狠狠地惩罚他。我要你深入矿洞，寻找暗血监工的下落。如果他们还没有被矿洞中的野兽给干掉的话，那肯定是找到什么隐秘之处藏起来了。$B$B如果你搜出一名暗血监工，就立即拷问他，逼他供出逃亡计划的主使者。得知幕后主谋的真实身份后，将监工之手带回来向我复命。', '找到一名暗血监工，然后审讯他。向矿洞女王汇报审讯的结果，并将监工之手交给她。', '无可奉告?或许等他躺在这个该死的矿坑地上失血而死的时候他就会想起来……想起和伊利丹的力量作对是什么意思!', '怎么样?为什么那么久?', '收集暗血情报', '去影月谷找灵翼矿洞的矿洞女王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11083, '疯狂与困惑', '别管那只虚空龙，$N。我们自有别的安排……$B$B灵翼矿洞深处有一群疯狂的暗血破碎者，自从虚空龙捣毁矿洞后，他们就被困在了下面。孤立无援的感受大概不好受吧，才两天而已，这帮家伙就彻底丧失了理智。$B$B他们竟然有了食尸的癖好，并开始自残肢体。我们绝不容许这些癫狂的生物存在。去干掉他们！一个不剩！', '影月谷灵翼矿洞的驱奴者鲁纳格要你杀死疯狂的暗血工头和5名疯狂的暗血矿工。', '不，我不了解……你会觉得就算再过两天，他们也不至于那么饿。黑暗之血……$B$B<罗纳葛摇摇他的头。>$B$B可恶他们真笨……', '问题“解决”了吗?', '', '去影月谷找灵翼矿洞的驱奴者鲁纳格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11085, '逃离斯克提斯', '太好了，$N。我非常感谢你特意过来帮助我。$B$B我在执行侦察任务的时候，被那些鸦人所饲养的大怪鸟从虚空鳐的背上给撞了下来。$B$B趁一切还来得及，我们赶紧离开这里吧。', '护送天空卫队囚犯转至安全的地方，然后向空军上尉杜尔因复命。', '谢谢你救了我们的一个斥候，$N。我们每天都在损失优秀人才，没有足够的新手能替换他们。', '什么事，$N?', '营救天空卫队囚犯。', '去泰罗卡森林找黑风码头的空军上尉杜尔因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11086, '暮光岭的传送门', '身为一名龙喉队长，你最重要的责任之一就是扼杀燃烧军团在外域的一切活动。记住，让那些打扰到伊利丹大人的家伙都永远闭嘴，这是你的义务！$B$B现在，那群愚蠢的恶魔正尝试在纳格兰西方的暮光岭一带创建一处传送门。他们必须为背叛而付出代价，而你，就将是我们派去收取这代价的代表。$B$B转至暮光岭，消灭那里的恶魔。对他们的防御工事，你至少每天得发动一次攻击。', '影月谷龙喉营地的莫格霍尔大王要你杀死20名死影密探。', '做的好，队长!伊利丹大人会知道你的英雄事迹的!', '毕竟，是我们的领主把那些恶魔从外域放逐并关闭了他们的传送门。一切都应向伊利丹的辉煌鞠躬。', '', '去影月谷找灵翼浮岛的莫格霍尔大王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11089, '雷萨赫尔的灵魂火炮', '雷萨赫尔顿领导着纳格兰暮光谷的恶魔。让这样一个力量强大的艾瑞达人在这个世上嚣张，实在是有损我们伊利达雷的脸面……但是我们也没有足够的力量去对付雷萨赫尔顿。至少在当前战火已经烧到黑暗神殿门口的状况下，我们没有……哦……不对……我有个更好的计划。$B$B你，没错，你将去制服雷萨赫尔顿，将他丢进暮光传送门去，将他放逐出这个世界。但要执行这个计划，必须先铸造一台灵魂火炮。$B$B把清单上所列的东西带回来给我。', '影月谷龙喉营地的伊利达雷领主巴塔斯要你将2块魔钢锭、1个精金框架、1个氪金能量核心和1份完美的奥术精华交给他。', '<巴萨斯熟练地将你带给他的材料组合在一起。>$B$B你现在可以进行计画的第二阶段了，队长。', '你收集好制作灵魂火炮需要的材料了吗?', '', '去影月谷找灵翼浮岛的伊利达雷领主巴塔斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11090, '征服者雷萨赫尔顿', '<巴塔斯手里拿着一件古怪的装置。>$B$B这是一台灵魂火炮，完成同调操作的火炮具备毁灭性的效果。我已经将它与我的血液进行了同调，而雷萨赫尔顿体内流动着的血液和我的完全相同。是的，他是我的兄弟。哎，可惜他选错了效忠的主子，而这也就导致了他的灭亡。$B$B带上灵魂火炮转至纳格兰的暮光岭，找到雷萨赫尔顿并向他开火！你必须待在你的座骑上，确保距离在射程之内。只要你坚持得住，最终他只能落败而逃！', '影月谷龙喉营地的伊利达雷领主巴塔斯要你转至纳格兰，对征服者雷萨赫尔顿使用灵魂火炮。$B$B完成任务后归还灵魂火炮。', '他会回来的，但现在军团对伊利丹大人的攻击已经减弱了。他应该知道你的功绩，队长。', '完成了吗?', '战胜征服者雷萨赫尔顿', '去影月谷找灵翼浮岛的伊利达雷领主巴塔斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11093, '饥饿的虚空鳐', '只要加以合适的训练，虚空鳐也能成为一种无比忠诚而且高度服从的坐骑。但糟糕的是，我们在与斯克提斯的战争之中损失了太多的虚空鳐。$B$B每天，都会有无数的鸦人试图突破我们的包围网，这些可怜的家伙们随时要上战场，根本得不到休息。更何况，这里给养不足，饲料也不够。就算它们命大，没在战斗里被那些该死的鸟人杀掉，恐怕也得饿死。$B$B如果你想帮忙的话，就带上一只虚空鳐去南边的森林里放放风吧。它们现在连迁跃追猎者的肉也能接受了——只要足够新鲜。', '在黑风码头南边的森林内使用虚空鳐的笼子，并在饥饿的虚空鳐旁杀死黑风追迹者。完成任务之后回去向天空卫队训练师德萨克复命。', '谢谢你帮忙照料鳍刺，$N。天知道这些家伙吃饱的时候飞的更好。我们不希望我们的人被射杀是因为他们的鳍刺太虚弱而无法飞行。', '你回来了!你的鳍刺有乖乖的吗?', '', '去泰罗卡森林找黑风码头的天空卫队训练师德萨克。', '', '喂食虚空鳐', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11094, '把他们都干掉！', '指挥官$N，立正！现在，你将立刻领导一队碎天者转至攻击黑暗神殿西北方的占星者哨站。只要摧毁了群星圣殿，我们与库斯卡岗哨之间的补给线就可以重新运作起来了。$B$B快去吧，用这个信号枪指引碎天者展开攻击！', '将任务的相关情报和龙喉信号枪一起交给群星圣殿的奥术师塞里斯。', '你来找我们是件好事。或许我们可以利用这次攻击扭转对龙喉的情势。', '安顿下来，孩子。', '', '去影月谷找群星圣殿的奥术师塞里斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11095, '指挥官霍布', '龙喉氏族也就只敢趁我们不备时发动攻击。要是我们有所准备的话，他们肯定没有取胜的机会。$B$B$N，我要你引他们来战。$B$B<塞里斯点了点头。>$B$B对，没错……这是陷阱。莫格霍尔大王不是给了你一把信号枪吗？将信号枪交给这座建筑物外面的指挥官霍布。', '将龙喉信号枪交给影月谷群星圣殿的指挥官霍布。', '<赫布露齿而笑。>$B$B史上最致命的陷阱……', '<赫布点点头。>', '', '去影月谷找群星圣殿的指挥官霍布。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11096, '临近的威胁', '这么说，你想加入天空卫队？好吧，我知道你确实能飞……可你会战斗吗？$B$B天空卫队誓死保卫沙塔斯免受一切威胁。当前居住在北方壁垒山中的戈杜尼食人魔是最紧迫的威胁。$B$B这些食人魔已经危害到了沙塔斯的地面交通和人员安全。这就是我们必须要去解决的问题。现在让我们来看看你能帮上什么忙吧。', '在壁垒山杀死任意20个戈杜尼食人魔，然后向沙塔斯城的尤拉复命。', '做的好，高手。我有预感，你会和我们处的很好。', '你完成了你的任务吗，$N?', '', '去找泰罗卡森林的尤拉。', '戈杜尼食人魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11097, '最致命的陷阱', '带上这些占星者勋章。战斗结束后，有了这些“胜利”的证据，莫格霍尔就会深信不疑了。他一定会以为这些都是由你从占星者士兵的尸体上拿来的。$B$B现在，唯一要做的事情就是利用这把信号枪引来龙喉氏族的部队。等你准备好之后我们就可以彻底消灭他们了。就等你发话呢。', '协助指挥官霍布和占星者保卫群星圣殿。击溃所有龙喉军队后，带上占星者勋章返回龙喉营地，向莫格霍尔大王复命。', '<莫格大笑。>$B$B哈!我就知道你不会让我失望，指挥官!我要你每天带领一个团队转至星光圣所至少一次。他们会别无选择而离开影月谷!', '你把他们粉碎在你脚下了吗，指挥官?', '击败龙喉氏族的军队', '去影月谷找灵翼浮岛的莫格霍尔大王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11098, '转至斯克提斯！', '壁垒山只是我们的战略目标之一。最近，位于鸦羽山另一侧的鸦人巢穴斯克提斯逐渐成为了我们的新的威胁，虽然这处鸦人势力离我们甚远，但是他们的强大力量绝对不容忽视。$B$B几个月前，斥候回报说那里有大规模的鸦人活动，紧接着沙塔斯城就遭到了攻击。我们已经在斯克提斯外围部署了部队。$B$B转至斯克提斯外的黑风码头将这些爆炸物交给空军上尉杜尔因。顺便告诉他，你是我派去的新兵。', '转至位于斯克提斯外的黑风码头，将炸药包交给空军上尉杜尔因。', '感谢你的物资;我们会善用它们!一个新兵?嗯，让我们看看你是块什么料。', '你有东西要给我，$g小伙子:小姑娘;?', '', '去泰罗卡森林找黑风码头的空军上尉杜尔因。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11099, '把他们都干掉！', '指挥官$N，立正！现在，你将立刻领导一队碎天者转至攻击黑暗神殿西北方的奥尔多哨站——沙塔尔祭坛。只要摧毁了沙塔尔祭坛，我们与库斯卡岗哨之间的补给线就可以重新运作起来了。$B$B快去吧，用这个信号枪指引碎天者展开攻击！', '将任务的相关情报和龙喉信号枪一起交给沙塔尔祭坛的学者希拉。', '你来找我们是件好事。或许我们可以利用这次攻击扭转对龙喉的情势。', '安顿下来，孩子。', '', '去影月谷找沙塔尔祭坛的学者希拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11100, '指挥官阿库斯', '龙喉氏族也就只敢趁我们不备时发动攻击。要是我们有所准备的话，他们肯定没有取胜的机会。$B$B$N，我要你引他们来战。$B$B<希拉点了点头。>$B$B对，没错……这是陷阱。莫格霍尔大王不是给了你一把信号枪吗？将信号枪交给这座建筑物外面的指挥官阿库斯。', '将龙喉信号枪交给影月谷沙塔尔祭坛的指挥官阿库斯。', '<阿克斯露齿而笑。>$B$B史上最致命的陷阱……', '<阿克斯点点头。>', '', '去影月谷找沙塔尔祭坛的指挥官阿库斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11101, '最致命的陷阱', '带上这些奥尔多勋章。战斗结束后，有了这些“胜利”的证据，莫格霍尔就会深信不疑了。他一定会以为这些都是由你从奥尔多士兵的尸体上拿来的。$B$B现在，唯一要做的事情就是利用这把信号枪引来龙喉氏族的部队。等你准备好之后我们就可以彻底消灭他们了。就等你发话呢。', '协助指挥官阿库斯和奥尔多保卫沙塔尔祭坛。击溃所有龙喉军队后，带上奥尔多勋章返回龙喉营地，向莫格霍尔大王复命。', '<莫格大笑。>$B$B哈!我就知道你不会让我失望，指挥官!我要你每天带领一个团队转至沙塔尔祭坛至少一次。他们会别无选择而离开影月谷!', '你把他们粉碎在你脚下了吗，指挥官?', '击败龙喉氏族的军队', '去影月谷找灵翼浮岛的莫格霍尔大王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11102, '轰炸任务', '你能变成乌鸦飞来飞去……这也值得炫耀？你从高空命中过地面的目标吗？想试试空战吗？$B$B北面的铸魔营地：天罚和南面的铸魔营地：恐怖是我的心腹之患，同样它们也对爱好和平的奥格瑞拉构成了威胁。在邪能火炮的攻击下，天空卫士伤亡惨重，根本无法侦察敌情。$B$B想要证明自己的实力吗？带上这些炸弹，瞄准铸魔营地的邪能炮弹堆投掷吧！当心别被炮弹击中！', '使用天空卫队炸弹炸毁15堆邪能炮弹。', '嗯，我想你毕竟还是有两把刷子。\r\n\r\n做的好。也许老凯勒对你看走眼了。\r\n\r\n<天空士官樊德丽奸笑着。>\r\n', '你用加农炮炸掉他们的炮弹堆了吗？', '', '去刀锋山找天空卫队哨站的空军上尉范德里普。', '炸毁邪能炮弹堆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11103, '远离先知之路', '', '', '时间之沙向前流逝很容易。它们可以倒着流，但困难度很高。', '你戒指里的力量是可塑的，虽然改变你的选择不容易。你确定你想替换它现在的形态吗?', '', '去找塔纳利斯的索莉多米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11104, '远离治愈者之路', '', '', '小心地做下一个决定。我们尽最大的努力来配合我们的盟友，但就连达拉然的资源都有他们的底限。', '你决定违背先前的选择?我想我可以帮你改变它。最终达拉然在意你的忠诚比你选择如何表现它来的多。$B$B它索费不低。当然，我需要你把旧的戒指交回来。', '', '去找塔纳利斯的索莉多米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11105, '远离勇士之路', '', '', '时间之沙向前流逝很容易。它们可以倒着流，但困难度很高。', '你戒指里的力量是可塑的，虽然改变你的选择不容易。你确定你想替换它现在的形态吗?', '', '去找塔纳利斯的索莉多米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11106, '远离防御者之路', '', '', '时间之沙向前流逝很容易。它们可以倒着流，但困难度很高。', '你戒指里的力量是可塑的，虽然改变你的选择不容易。你确定你想替换它现在的形态吗?', '', '去找塔纳利斯的索莉多米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11108, '伊利丹·怒风大人', '来吧，大领主$N。伊利丹大人正等着你呢！', '与伊利丹·怒风会面。如果你有幸活下来，就转至沙塔斯城的贫民窟寻找巴萨姆斯。', '我是第一个，你知道。怪物遗弃的孩子……$B$B<巴萨姆斯摇摇他的头。>$B$B我们欠你太多了，$N。你独自粉碎了龙喉帝国并收集到足以让我的兄弟忙碌十辈子的资讯。$B$B我们能提供某个东西，不过不多就是了……我的同类都愿意加入你们在外域的任务。只要问问他们就会跟你走。', '你的冒险可真刺激，$N。', '与伊利丹·怒风会面', '去泰罗卡森林的沙塔斯城找巴萨姆斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11117, '抓住鹿角小飞兔！', '你听见了吗？山丘中传来的声音。那是鹿角小飞兔！这些狡猾的家伙被美酒的香味吸引而来……我想要捕捉一些鹿角小飞兔，可惜我的膝盖受了伤，动弹不得。但是你可以帮我！$B$B利用这张网来捕捉那些讨厌的小东西吧。你要是能带回5只鹿角小飞兔，我就好好奖赏你！噢，还有一件事——只有在醉酒的情况下你才能看见这些家伙！再多喝些酒吧，或者从我这里拿一副合成酿酒护目镜，带上它也能起到和醉酒一样的作用。', '葛达克·猎枪要你用鹿角小飞兔网捕捉5只昏迷的鹿角小飞兔。他说，你必须喝得酩酊大醉，或者是戴上合成酿酒护目镜，才能看见它们。', '很好，瞧!你带来了满满一桶的鹿角兔!<他从酒杯中喝了满满一大口。>$B$B我要告诉你我打算怎么做。既然你是个这么高明的猎人，我会让你养一只!', '你醉到可以看见那些小兔崽子了吗?', '', '去找丹莫罗的葛达克·猎枪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11118, '粉色的雷象', '一醉方休是美酒节上的传统，所有人都必须喝得醉醺醺的才行！我接二连三地接到来自艾泽拉斯世界的报告，据说幻象生物正在美酒节庆典上滋扰生事！这种事情令人难以忍受！$B$B普通的武器难以对付幻象状态下的雷象，子弹啊箭啊什么的穿越它们的虚体，却无法造成伤害。来，带上这台神奇的侏儒高科技武器，去别处的啤酒店消灭雷象吧。记住，只有你喝醉了，或者是带上合成酿酒护目镜，才有可能看见它们！如果你需要一副合成酿酒护目镜，那就来找我吧。', '转至暴风城、达纳苏斯和埃索达城外的啤酒店，分别杀死三头雷象，然后向葛达克·猎枪复命。你必须在醉酒或者戴上合成酿酒护目镜的情况下才能看见这些粉色的雷象。', '做得好!粉红伊莱克…多荒谬的幻觉!', '那些讨厌的粉红伊莱克被解决掉了吗?', '', '去找丹莫罗的葛达克·猎枪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11120, '粉色的雷象', '瞧，我们在这里做生意呢。人们喝得烂醉如泥？这正是生意红火的表现呀。不过我们遇到了一件麻烦事，幻象生物在美酒节上捣乱，对我们的收益造成了不小的影响。我收到报告称，酒鬼们——呃，尊贵的客人们被那些粉色的雷象烦透了。$B$B我可不能让客人们为了这等小事烦恼。来，带上这台射线发射器，去别处的啤酒店解决掉那些雷象好吗？记得一定要喝醉，或者戴上合成酿酒护目镜才能看到那些幻象生物。想要合成酿酒护目镜的话，就来找我吧。', '转至银月城、雷霆崖和幽暗城外的啤酒店，分别杀死三头雷象，然后向高达克·枪猎复命。你必须在醉酒或者戴上合成酿酒护目镜的情况下才能看见这些粉色的雷象。', '干得好，小伙子。把这些拿去当作是报酬吧。', '你搞定了我们提到的小问题吗?', '', '去找杜隆塔尔的高达克·枪猎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11122, '来来回回', '这么说，你想帮忙置办美酒节？我恰好有项任务交给你。骑上一头赛羊转至卡拉诺斯，替我取回一些酒桶。$B$B弗莱恩·火酒在一座小山坡上等着你呢，他附近就有一堆酒桶。当你跑近他时，他会把酒桶抛给你，然后你带着酒桶回到这儿来，再把酒桶抛给波尔·冻石就行啦。不过你每次只能携带一只酒桶。$B$B准备好出发了吗？', '从卡拉诺斯的弗莱恩·火酒那儿接过一只酒桶，然后将它交给波尔·冻石。在赛羊消失之前取回3只酒桶。', '多亏了你的帮忙!只要啤酒节还在进行，那些黑铁矮人也不放弃攻击的话，就还是需要人来帮我运送酒桶。如果你还想多赚几个奖品章，你可以每天都来找我。$B$B就先这样吧，我还得付给你今天的酬劳呢。这些是你的奖品章，祝你在啤酒节玩得开心!', '我需要那些酒桶!你还在等什么!?!', '', '去找丹莫罗的尼尔·拉姆斯登。', '运送酒桶', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11126, '叛徒', '见到你很荣幸，$c。我来到塞拉摩是为了帮忙解决这些叛逃者的麻烦。他们不仅到处张贴宣传海报，甚至已经有一些人渗透进了我们的城镇。$B$B这些叛逃者正到处散布着谣言和宣传资料，希望能说服其它人加入他们的队伍。$B$B事实上，从城镇到码头的每个岗哨附近都能看到他们的身影。找到他们，揭露他们，然后羞辱他们。在现在这个节骨眼上，任何事情都有可能给他们带来更多的同情者。', '与5个叛逃煽动者对质，然后向塞拉摩码头附近的加莉亚·哈斯汀汇报。', '做得好，$N。我想我们已设法在他们还没准备好时将他们揭发了。他们的间谍可能曾经认为待在城里就安全了。$B$B一段时间之后，那些煽动家又会回来散布他们的谎言。我们要用你争取到的时间进一步地让他们闭嘴。', '你把那些叛逃者间谍赶出塞拉摩了吗?', '', '去尘泥沼泽找塞拉摩岛的加莉亚·哈斯汀。', '揭露叛逃煽动者的面目', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11128, '宣传战', '这些叛逃者并非只是在说服卫兵那么简单。我们还在码头的一艘船上发现了大量不知道怎么偷运进来的叛逃者传单。$B$B那艘用来运送传单的船现在还停泊在塞拉摩，就在最远端的码头那里。如果你能潜入那艘船，夺走他们宣传资料的话，他们的人就会失去最有力的工具。不过小心！这艘船被一群经验丰富的海盗控制着，而且货物很可能被藏在船长室里。', '将叛逃者传单交给塞拉摩码头附近的加莉亚·哈斯汀。', '<军情七处的探员赞许地点点头。>$B$B干得好。我正好有个计画让这些叛逃者身败名裂，在塞拉摩没有立足之地。', '你拿到了那些剩下的宣传单了吗?', '', '去尘泥沼泽找塞拉摩岛的加莉亚·哈斯汀。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11129, '凯雷失踪了！', '帮帮忙啊，$N！我的小狗凯雷不见了！我只知道它应该是在血蹄村周围跑丢的，现在它一定又饿又着急！$B$B你能帮我找到它，然后给它喂点东西吃吗？它吃饱了之后就会回家了。$B$B如果你要给它喂食，就得先找到食物。它最喜欢的食物是鲜嫩的陆行鸟肉。你可以在东边找到许多陆行鸟，把它们的肉带给凯雷就行啦！看到它之后把肉放在地上，它就会过来的。', '血蹄村的阿哈布·麦蹄希望你帮他给小狗凯雷喂食。$B$B让凯雷吃过鲜嫩的陆行鸟肉之后回去向阿哈布·麦蹄复命。', '干得好，$N!凯尔一吃饱就跑回来睡着了。感谢你的帮忙。', '你找到凯尔了吗?', '', '去找莫高雷的阿哈布·麦蹄。', '', '给凯雷喂食', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11130, '闪亮闪亮的东西！', '过来过来，$G伙计:宝贝儿;！让我老格里伏塔看看那些闪亮闪亮的东西……$b$b嗯嗯，嘿，不错不错，但应该还有更好的。对，对，好上许多的。$b$b<格里伏塔向你斜过身来，低声耳语道。>$b$b很多地方呢，有许多许多宝贵的闪亮闪亮的小玩意，但你得知道哪里有才行！不过今天呢，可就是你的幸运日了。我认识一个能帮你忙的家伙，可以让你找到无数亮闪闪的东西，多得你都拿不动。$b$b去吧，去找我的老朋友巴德，他就在祖阿曼附近。你呢，就跟他说是老格里伏塔派你去的，他就会让你参加他的新计划啦。', '格里伏塔要求你将他的便笺交给幽魂之地的巴德，他就在祖阿曼外。', '<霸德读着便条。>$B$B啊哈!格利夫塔的朋友?欢迎!$B$B你来的时机真是太完美了，$C。就像是命运安排好一样，我最近才刚失去了我的新合伙人。一场悲剧，真的，但高风险高获利。最好不要老想着负面的事情!$B$B我猜想你一定听说过我数不清的探索与发现。但一切都比不上这个!事实上，我就要在祖阿曼创造历史了，而命运注定了你也要参与这件大事!', '<霸德怀疑地打量着便条。>$B$B你拿着些什么，$C?', '', '去找幽魂之地的巴德·奈德雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11131, '赶快灭火！', '你一定要帮帮我们！无头骑士正在进攻我们的村庄。到处都是火焰！孩子们有危险！$B$B$n，加入消防队吧。拿上水桶去灭火，或者把它递给更靠近火焰的伙伴。只有扑灭所有的火焰才能拯救我们！', '穿戏服的孤儿院长希望你帮忙扑灭村子里的所有火焰。在所有火焰都被扑灭后，回去向穿戏服的孤儿院长汇报。', '噢，感谢你!愿圣光祝福你的善举，仁慈的$g先生:女士;。黑暗骑士的阴影依旧在逼近，但起码现在，村子不受他的火焰威胁了。', '$N，你答应过会拯救那些孩子的!', '扑灭火焰', '去找穿戏服的孤儿院长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11132, '诱人的保证', '我的理论证实了祖阿曼中存在着大量财宝的传闻，当然了，我的理论不是你们这些凡人可以理解的。$B$B很快每个人都将获得享不尽的荣华富贵了！$b$b不过，你得先去完成一些重要的事情, 你必须通过努力来挣得你的那一份, 毕竟……$B$B我们的初期行动并没有像我希望的那样顺利进行。事实上，我的地图，和那个借走我地图的新手，在深入纳洛拉克的平台调查后就失踪了。要替换一个人很简单，但我需要那份地图！$b$b只要成功了，人们就会永远的记住你，是你帮助巴德·奈德雷克解开了祖阿曼的秘密！', '战斧岭的巴德·奈德雷克要你转至祖阿曼的高阶祭司纳洛拉克所在的平台，找回他的地图。', '<霸德看起来有点震惊。>噢?你真的找到了\r\n地图?$B$B啊嗯，我是说，当然你找到了!干得好啊，$C。$B$B让我找找给能不能给一点好东西…噢对，这应该可以。', '噢对，$N，我没叫错吧?$B$B你找到了我的地图吗?', '', '去找幽魂之地的巴德·奈德雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11133, '羞辱叛逃者', '我已经把你从叛逃者手中夺来的传单修改了。现在，任何人读到这些传单，都会得到一个和他们的本意截然相反的观点。$B$B如果我们将这些传单分发给足够多的卫兵，那样这些叛逃者在我们的领地里就会陷入空前的窘境。$B$B<加莉亚递给你一叠修改过的传单。>$B$B你为什么不在我策划下一步行动的时候赶紧行动起来呢？', '加莉亚·哈斯汀希望你向6个塞拉摩卫兵发放修改过的传单，然后返回塞拉摩码头附近向她复命。', '<在你形容那些守卫看到传单的反应时，卡莉雅笑得差点呛到。>$B$B正如我所预期!我想这下任何叛逃者间谍再想来渗透塞拉摩，只会被大笑着轰出去!', '我想我听到了兵营传来的笑声。你把我给你的传单都发出去了吗?', '', '去尘泥沼泽找塞拉摩岛的加莉亚·哈斯汀。', '发放传单', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11134, '叛逃者的末日', '现在我们已经把这些叛逃者从塞拉摩扫了出去，是时候完成最后一击了。我的线人告诉我，叛逃者们正在一艘停泊在码头东南面小岛旁的船上部署着行动。$B$B逮捕他们的首领贾维斯·格雷希德，这样应该会让其它人失去战斗的决心。去船上找到他，并说服他投降。如果他表现出战意的话，我一点都不惊讶。不过当他知道自己不可能获胜的时候，他一定会投降的。', '抓住贾维斯·格雷希德，然后向塞拉摩码头附近的加莉亚·哈斯汀复命。', '盖维司的要求并没有乍听那么奇怪。透过适当的控制，吉安娜女士应该可以让这些叛逃者重回岗位，当然这要看女士的决定。$B$B跟你合作十分愉快，$N。要是没有你的帮助，我怀疑这次的行动能否进行的如此顺利。等我回报暴风城的时候，我会称你为终结叛逃者威胁的$C。', '你完成了对叛逃者基地的突袭任务吗?', '', '去尘泥沼泽找塞拉摩岛的加莉亚·哈斯汀。', '抓获贾维斯·格雷希德', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11137, '尘泥沼泽有迪菲亚兄弟会？', '我手下的斥候前几天报告说，有一条受了重创的远航帆船搁浅在了东北方的海滩上。不过，海难并不是那条船上唯一不寻常的地方，报告还指出，船上的全部幸存者都戴着红色的头巾！$B$B要知道，迪菲亚兄弟会的主要成员都是石匠和公会成员，没有水手。那么这群人在一片他们完全不感兴趣的大陆上对着船只的残骸又在干些什么呢？$B$B据说他们的头目就在哨塔东北边海岸对面的那座岛屿上。杀死他，把他那里的所有文件都带回来。', '从加恩·马瑟斯手中夺得迪菲亚命令书，把它们交给警戒岗哨的维摩尔上尉。', '<卫摩尔上尉从你那边收下了指令并且仔细地阅读。>\r\n\r\n这个‘珍贵的货物’指的是什么?迪菲亚确实有在暴风城一带进行一些小规模走私，但这看来完全超过了他们的范畴。而且这样的文字明显是出自于一个富豪或是贵族赞助人。', '你逮到他们的领袖了吗?', '', '去尘泥沼泽找警戒哨岗的维摩尔上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11138, '雷恩·米克基尔', '根据你带来的这些命令书所说，这些迪菲亚的家伙们当前第一优先要做的事情，就是找到并确保那个什么货物的安全。$B$B暴风城军情七处有一位救援潜水员名叫雷恩·米克基尔，当前正在塞拉摩工作。他听说海难的消息之后，就转至了迪菲亚兄弟会占据的那座小岛附近。$B$B如果我们想从迪菲亚兄弟会手里搞到这个所谓的货物，就必定需要他的帮助。总之，你可以到你之前刚刚拜访过的那座岛屿北边的一处小岛旁去找他，他应该就在小岛东北边的水里潜伏着。', '将迪菲亚命令书交给恐惧海岸水边的雷恩·米克基尔。', '<瑞恩看着那些指令。>\r\n\r\n所以那艘船上有些有价值的货物!我们一定要在迪菲亚发现之前先找到它们。他们并不是潜水员，但如果你要帮我一起找那些货物的话，我们就会需要他们的一些装备。', '你好，$C。什么风把你吹到这里来?', '', '去尘泥沼泽找恐惧海岸的瑞恩·米克基尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11139, '二手潜水设备', '从这里到奥卡兹岛周围的海底，到处都散布着那条船的残骸与碎片。而且，迪菲亚那边已经派出了一些潜水员在附近搜索着些什么。只要穿上他们的装备，我们也能把你派去混到他们中间，加入他们的搜寻活动。不过，首先你得非常非常“有创意”地借一点他们的东西过来。$B$B搜索这座岛屿，给我弄来一箱潜水设备，再带些修理工具回来，我可以帮你把它们制作成合适的潜水设备！', '将工具包和损坏的潜水设备交给尘泥沼泽的雷恩·米克基尔。', '哇喔，这装备的状况比我想得还严重，还有这些工具……\r\n\r\n好吧，既然我说过要帮你把装备修好，我最好现在开始动手。', '让我们看看你从迪菲亚那边‘借到’了些什么。', '', '去尘泥沼泽找恐惧海岸的瑞恩·米克基尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11140, '找回货物！', '呃，我确实能把这东西彻底修好，能让你真的用它去潜水。只是……时间上的估算略有一点小错误。$B$B沉船的残骸当前遍布整个海底，在这座岛屿东边的海岸直到奥卡兹岛之间几乎都是。这顶头盔可以确定出残骸的位置，你可以用它来寻找残骸。然后，再利用这个打捞设备来搜索残骸，看看那个什么货物是否在其中。小心点，别太接近奥卡兹岛，那些多头蛇非常凶暴和危险。', '将6只打捞上来的保险箱交给尘泥沼泽的雷恩·米克基尔。', '<瑞恩将你发现的保险箱中的东西一扫而空。 > $B$B做得好。现在，让我们来瞧瞧我们『珍贵的货物』有没有在里面...', '你有找到任何与迪菲亚货物有关的残骸吗?', '', '去尘泥沼泽找恐惧海岸的瑞恩·米克基尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11144, '寻找证据', '恐怖图腾可能是牛头人中最好战的部族，但是他们绝不是是一盘散沙。如果是他们烧毁了树荫旅店，那么他们必定是从他们的部族长者那里接受了命令才会这么做。$B$B在这里的西北方，有一处庞大的恐怖图腾定居点——黑蹄村。他们一直把黑蹄村作为进攻哨塔的基地，我打赌如果你去那里寻找的话，一定会找到命令书之类的东西。去黑蹄村的长者那里寻找证据吧。', '将恐怖图腾作战计划交给北点哨塔的达利尔上尉。', '<达利尔上尉粗略地看了一下作战计划。>\r\n\r\n没有比这更明显的证据了。他们打算自己对抗在这个区域殖民的人类，我怀疑塞拉摩就是他们的下一个目标。', '你有找到任何命令的线索吗?', '', '去尘泥沼泽找北点哨塔的达利尔上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11145, '恐怖图腾的囚犯', '我们正在尽全力不让恐怖图腾的那些混账接近这里，但他们一直都在发动对哨塔的攻击。更糟的是，他们发现并俘虏了上尉派去收集情报的斥候，开始在路上驻守起来。$B$B我怀疑那些俘虏都被关押在黑蹄村，就在这里的西北方。根据我对恐怖图腾的了解，村里的卫兵很可能会随身带着囚笼的钥匙。我不管你怎么做，$c，我只想看到我们的人活着回来。', '北点哨塔的卢卡斯中士希望你能解救5名塞拉摩囚犯。', '从黑蹄村被释放的俘虏已经开始回报了。俘虏所提供的情报让我们能在下一次对抗恐怖图腾的战斗中取得优势。\r\n\r\n我和我的手下们衷心地感谢你。', '你释放了那些在黑蹄村的俘虏吗?', '', '去找尘泥沼泽北点哨塔的卢卡斯中士。', '解救塞拉摩囚犯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11146, '捕捉迅猛龙', '这片沼泽的东北部有一块地方被一群肮脏无比的迅猛龙占据了。它们夺走了不止一个士兵的生命，但我想，我们可以利用它们来对付那帮牛头人邻居。$B$B将这根绳子带过去，用它抓捕几只血沼迅猛龙或是血沼尖啸龙来，当然，你得先制服它们。只有你先在战斗中将它们打得晕头转向以后才可以抓捕。总之，会有点困难，加油吧。', '北点哨塔的卢卡斯中士要求你捕捉6只迅猛龙。血沼迅猛龙或是血沼尖啸龙都可以满足他的要求。', '你看起来受了一点抓伤，不过不太严重。你的遭遇绝对会比那些恐怖图腾遇上我们的新朋友来得好呢', '你抓到了那些迅猛龙吗?', '', '去找尘泥沼泽北点哨塔的卢卡斯中士。', '捕获迅猛龙', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11147, '放生迅猛龙', '现在我们有迅猛龙了，下一步就是想办法“鼓励”它们去攻击西北边黑蹄村里的那些恐怖图腾牛头人。$B$B我这里刚好还有一些没吃完的烤牛腰，或者是烤羊腰……不管了……爱是什么是什么吧。总之，你可以拿它当饵。把它放进黑蹄村中央那架风车的下面，那些迅猛龙就知道该做什么了。', '北点哨塔的卢卡斯中士要求你将迅猛龙诱饵放在黑蹄村的风车附近。', '<中士毫不掩饰他的大笑。 > $B$B很好。这样应该可以阻止他们一两次的劫掠。', '你把迅猛龙放进了黑蹄村了吗?', '', '去找尘泥沼泽北点哨塔的卢卡斯中士。', '放生迅猛龙', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11148, '恐怖图腾的军备', '如果你在树荫旅店找到的装备是属于恐怖图腾部队的话，那么很可能他们在西北部的营地里会有更多类似的装备。$B$B我们还不能从黑蹄村得到更多的情报。不过从袭击者的规模来看，那里驻守着大量的部队。$B$B想办法去那里弄一些他们的装备来，这样我们就可以拿它们和你在旅店找到的那些比较一下了。', '北点哨塔的达利尔上尉希望你能交给他7件黑蹄军备。', '<达利尔上尉检查着你从黑蹄村带来的武装。>\r\n\r\n毫无疑问，他们完全符合，但还有一个问题 -- 这些武装从来没有用在战斗中。黑蹄村一定不是沼泽中唯一的恐怖图腾据点。', '你从黑蹄村拿到那些武装了吗?', '', '去尘泥沼泽找北点哨塔的达利尔上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11150, '烧毁恐角岗哨！', '根本没有必要用水晶球来看看我们的新“邻居”在干些什么。如果这就是焚毁树荫旅店的那支部队，那么我们也没有理由再容忍他们的存在。$B$B拿上这根火把，将他们的营地夷为平地吧！你可以在我的农场略北一些的地方找到恐角岗哨。你不可能看不到，真的，因为恐怖图腾在那里竖着许多非常华丽的图腾，以此表明他们对图腾的喜爱。', '烧毁恐角岗哨的北部帐篷、东部帐篷和东北部帐篷，然后回到塔贝萨的农场，向塔贝萨复命。', '我希望恐怖图腾收到我们的警告了。任何再回来的企图将会遭遇比被火烧还惨的后果，这一点我和我的学徒们能跟你保证。', '你有好好利用那把火炬吗?', '', '去尘泥沼泽找塔贝萨的农场的塔贝萨。', '烧毁北部帐篷', '烧毁东北部帐篷', '烧毁东部帐篷', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11152, '安息', '我希望有办法让詹姆斯·海厄尔的妻儿知道我们已经将杀害他们的凶手绳之以法了。$B$B<维米斯队长拿出了一个小花圈。>$B$B有人说只要这样做，即使我们不能联系到他们，他们的在天之灵也会安息。我希望你可以把这个花圈放在海厄尔系列的墓碑前，就是塞拉摩大门北面墓地中的大石碑。', '塞拉摩城堡中的盖兰·维米斯队长想让你在海厄尔系列墓碑前放上一个花圈。', '<在你讲述海尔家族墓地的事情时，维米斯上尉露出了一点淡淡的笑容。>\r\n\r\n他们能了解真的很好。你没有跟他们谈起詹姆士的事吧?\r\n\r\n我会把他妻子的消息传给他，不过我很怀疑他能明白。', '你已经献上花圈了吗?', '', '去尘泥沼泽找塞拉摩堡垒的盖兰·维米斯队长。', '在海厄尔家族墓碑前放置花圈', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11153, '冲破封锁', '我们的船都沉了！我们需要你去搞定海盗部署在碎裂海峡的封锁线！$B$B带上这些集束炸弹乘坐地精飞艇，那是哈隆梅瑟尔“借”给我们的。飞艇可以带你飞过那些混帐海盗控制的港口，而你要负责给他们点颜色看看！$B$B如果你不把他们炸成碎片的话，我们就没办法冲破封锁线了。', '使用匹特洛夫的集束炸弹炸死25名封锁船海盗，并摧毁10门封锁船的火炮。完成任务后返回嚎风峡湾的西部卫戍要塞，向炮兵匹特洛夫复命。', '这正是我想听见的!你干得漂亮，$N，无庸置疑!$B$B等我们明天做出更多炸弹的时候，你愿意再来吗?我宁可你现在就再来一趟，但是我的助手费克努还没有从收集粪便的路上回来。$B$B我真不知道为什么要这么久?', '我们已经谈过了，对吧?这表示你完成了!你一定已经给那些腐烂的北海海贼一些颜色瞧瞧$B$B对吧?', '', '去嚎风峡湾找西部卫戍要塞的炮兵匹特洛夫。', '', '摧毁封锁船的火炮', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11154, '吓出它们的……', '嗨，叫你呢……快来帮帮我！$B$B匹特洛夫让我来这里收集制造炸弹所需的蝙蝠粪便。这分明是让我去送死嘛！$B$B北边的裂木森林中挂满了暗爪蝙蝠，但是你别想叫我挪动一步，除非是回家！$B$B嗯……我觉得你可以帮我搞定这件事！好不好呀？求求你啦！！$B$B给，这是特制的爆竹。将它们扔到那些蝙蝠的下方，它们肯定会被爆炸声吓得屎尿齐流！', '将10坨暗爪蝙蝠的粪便交给嚎风峡湾钢铁之门的工程师菲纳特。', '恶，什么东西那么臭?哎哟，就是你!嗯，我猜，我请你做了一件“很有味”的任务!$B$B谢啦，$C，别担心，只要我们离开这里，我会马上把这些东西送给派特洛夫。$B$B<费克努对着探险者大吼大叫。>$B$B你听见那些家伙说的吗?让我们赶紧离开这儿吧!!!', '拜托告诉我你拿到蝙蝠粪便了?!', '', '去嚎风峡湾找钢铁之门的工程师菲纳特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11155, '又是铲齿鹿汤？', '我们饲养的家禽都离奇失踪了。如果不能尽快补充食物，麻烦就大了。那样的话，我们要担心的就不仅仅是这附近的野兽了！$B$B你瞧，我负责照顾这一大帮人的饮食。你能去东边跑一趟，帮我搞些肉回来吗？准确地说，我想要烹制铲齿鹿肉。$B$B小心那些雄鹿……它们很讨厌！', '将6块铲齿鹿肉交给西部卫戍要塞的厨师凯图·黑罐。', '这样可以为男人们弄来一餐好料。$B$B<主厨靠近你在耳边悄悄说。>$B$B拿去，$g孩子:亲爱的;，你自己也吃一点吧。你看起来需要多长点肉啊!', '这世间没有比锹牙腹侧的柔软嫩肉更奢侈的了!', '', '去嚎风峡湾找西部卫戍要塞的厨师凯图·黑罐。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11156, '恐角袭击者', '恐怖图腾的成员聚集在这里北面的恐角岗哨，现在他们真是越来越大胆了。在晚上，你能常常听到他们在颂唱与这里的居民战斗的“事迹”。$B$B他们决心把我们从农场上赶走，但是塔贝萨在这里训练了一代代的学徒，怎么会说走就走呢？我们尽全力保护着农场，但学徒加里奥在上次战斗中受伤了。$B$B去恐角岗哨消灭你所找到的一切恐怖图腾成员！必须阻止他们的进攻！', '在恐角岗哨消灭12个恐怖图腾成员，然后向塔贝萨农场的学徒莫兰恩复命。', '<学徒莫兰恩点点头。 > $B$B很好。如果你把前来骚扰叫作陪伴的话，我不认为我会想念他们的。你会觉得至少在沼泽中可以获得些许隐私权，懂吗?', '关于阻止恐怖图腾进攻，你有任何进展吗?', '', '去尘泥沼泽找塔贝萨的农场的学徒莫兰恩。', '杀死恐角岗哨的恐怖图腾成员', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11157, '邪恶之巢', '$N，这件事只有交给你来办我才放心。瞧见东南方那片着火的森林了吧，我要你去那儿对付始祖幼龙和满地的始祖龙蛋！$B$B灰烬龙巢的火势一直没有得到控制，一定是某种神秘的魔法力量在作祟。如果不尽快采取措施的话，再过几周我们就会被大火包围！$B$B摧毁始祖龙蛋，杀掉始祖龙崽，帮助我们解除威胁吧。', '摧毁15枚始祖龙卵，并杀死15只始祖龙崽，然后返回西部卫戍要塞，向亚当斯上尉复命。', '干得好!运气好的话，毁灭这些蛋和幼龙应该足以逼退这些热腾腾的野兽，并且阻止魔法火焰的扩散。$B$B等等…那是什么声音?那听起来像是某种翅膀拍动声。', '你进行得如何?', '', '去嚎风峡湾找西部卫戍要塞的亚当斯上尉。', '摧毁始祖龙卵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11158, '血沼羽毛', '看见布洛格在这里，你是不是非常惊讶呢，小$r？别担心，泥链镇的地精都是布洛格的朋友，你也可以喔。$B$B新的大王不敢向那些摧毁了我们故乡并屠杀我们同胞的黑龙复仇，所以布洛格就离开了蕨墙村。布洛格来这里，是为了让那些朋友们的灵魂重新得到安息，并向黑龙复仇！不过，布洛格首先需要一些准备。为了仪式，布洛格需要羽毛，具有强大魔力的羽毛，比如镇子西边鲜血沼泽墓穴那边的迅猛龙的羽毛。', '将5片血沼羽毛交给泥链镇的布洛格。', '<布洛葛收下那些羽毛。 > $B$B布洛葛对这些羽毛感到很满意。魔力很强。布洛葛不知道迅猛龙如何给这些羽毛力量，但迅猛龙羽毛总是最适合仪式了。', '<布洛葛满怀希望地看着你。>$B$B你带了血沼羽毛吗?', '', '去尘泥沼泽找泥链镇的布洛格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11159, '石槌之魂', '布洛格已经完成了图腾，它可以让朋友们的灵魂回归安息。那些龙打过来的时候，杀死了几乎所有没来得及逃走的朋友。布洛格和莫格穆洛克大王，一直希望能领导其它幸存下来的石槌食人魔发动反击。$B$B不过，反击一直没有开始，而死去同胞们的灵魂却一直困扰着布洛格与其它人。把这根图腾带到石槌废墟去，在那些食人魔的骸骨旁使用它，将他们的灵魂吸引到你这里，击败那些灵魂，就能让他们获得安息了。', '泥链镇的布洛格要求你让10个石槌之魂得到安息。', '布洛葛感谢你的帮忙，虽然他知道莫格穆洛克主宰一定不会感谢你。起码幸存的石槌终于可以专心面对生者的问题，而让死者获得归属。布洛葛现在只剩下一件事了。', '布洛葛一定要知道，你有没有带给那些暴力的石槌之灵平静?', '', '去尘泥沼泽找泥链镇的布洛格。', '让石槌之魂安息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11160, '石槌战旗', '当那些龙跑过来夺走布洛格的家时，大多数的石槌食人魔都逃跑了，没来得及带走任何东西，甚至包括氏族的旗帜。$B$B布洛格知道旗帜就藏在石槌食人魔山中，不过现在，那地方被称作火焰洞穴了。布洛格一定要夺回旗帜，用它向那些杀死了朋友们的龙复仇。$B$B总之，布洛格氏族的领地，现在叫火焰洞穴，就在泥链镇的西北方向，不过那里现在全是龙了。旗帜一定就藏在洞穴深处，要小心，$N。', '夺取石槌战旗，并将它交给泥链镇的布洛格。', '布洛葛感谢你，$N. 布洛葛对氏族军旗有个大计划', '你带了石槌旌旗吗?', '', '去尘泥沼泽找泥链镇的布洛格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11161, '憎恨的精华', '要想做出布洛格在仪式上必须要用到的图腾，就需要那些曾杀死朋友们的生物的精华。布洛格的敌人所发散出来的仇恨与愤怒，将会给魔法灌入仇恨的力量。$B$B去找火鬃斥候、火鬃灰尾龙人，还有火鬃守卫，杀死它们，再在尸体上使用图腾。龙类只有在死去的时候才会释放出精华。$B$B这些家伙就在西北方的火焰洞穴和北方的石槌废墟一带活动。', '将10份黑龙精华交给泥链镇的布洛格。', '布洛葛感谢你，$N. 一旦布洛葛把这些魔法加进图腾里，就可以使布洛葛死去的朋友获得救赎。', '你拿到那些精华了吗?布洛葛一定要有那些东西才能替他的朋友复仇!', '', '去尘泥沼泽找泥链镇的布洛格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11162, '挑战黑龙军团', '布洛格已经决定要对沼泽里那些黑龙展开复仇了。$N，你可以给我很大的帮助。你会帮忙吗？$B$B把布洛格的氏族旗帜带上，到东边去找一处类似龙嘴的洞穴，把旗帜插在那里。这样就象征着我正式对奥妮克希亚宣战了。$B$B布洛格，还有石槌氏族一定要夺回属于我们自己的土地！', '将石槌战旗插在奥妮克希亚的巢穴入口附近，等待奥妮克希亚的回应，然后回去向泥链镇的布洛格复命。', '<布洛葛听你讲述在奥妮克希亚的巢穴入口的情况。 > $B$B布洛葛料到奥妮克希亚胆小到不敢出来面对你。就像黑龙军团总是等到确定胜利时才愿意出击。 $B$B布洛葛很感谢你的帮助，$N， 布洛葛永远不会忘记你替他做的。布洛葛永远也不会放弃让石槌回到故乡的任务。', '布洛葛要进行他的复仇!', '', '去尘泥沼泽找泥链镇的布洛格。', '为石槌氏族复仇', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11164, '夺牙奇兵', '嗨，朋友！你是新来的吧？ 我托你办件事吧....$b$b巴德一直想让他的森林巨魔伪装变得更逼真。他说他就快完成了——只是需要最后一点加工，只是需要点獠牙而已……$B$B我的剥皮才能在这里毫无用处，拔那些巨魔的獠牙让我感到恶心。$b$b带10根巨魔獠牙回来给我，怎么样，朋友？', '普雷蒙要你从祖阿曼的巨魔身上收集10根森林巨魔獠牙，把它们带回巴德的营地交给他。', '啊哈，这是我需要的!$B$B是我先前答应过的报酬，$C。', '快点，兄弟!$B$B如果我再不快点给那些长牙，他就要把我送进祖阿曼去试验他的面具。', '', '去找幽魂之地的普雷蒙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11166, 'X标记……你的末日！', '那群蠢货究竟是如何失败的？$b$b我一再嘱咐他们要小心，要小心——为了帮助他们潜入祖阿曼，我甚至把我的地图和伪装都给了他们。$b$b啊，不过任何事总有好的一面，他们的失败对你和你的朋友们来说是个机会。只要成功了，你们就可以名正言顺地加入我的队伍，和我一起分享即将到手的那些无尽的荣誉。并不是\r\n我贪心，只是让你意识到这点而已。$b$b在我将最终的挖掘计划准备妥当之前，我的地图上还有几块区域需要更详尽的探索……', '进入祖阿曼并调查哈尔拉兹的大厅、加亚莱的平台和埃基尔松的平台。将这些地方的细节报告给巴德，他的营地就在幽魂之地。', '<霸德挣扎地想维持自己的冷静。>$B$B呃 - 嗯，$N - 这，喔，你也该回来了。是 - 事实上你拖延了整个行动。$B$B嗯，现在得来把地图的空白填补起来……', '我相信我手制的伪装能够你在祖阿曼适当的保护。$B$B你替我勘查过那些区域了吗?还是我应该要开始找取代你的人?', '', '去找幽魂之地的巴德·奈德雷克。', '调查哈尔拉兹的大厅', '调查加亚莱的平台', '调查埃基尔松的平台', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11167, '新的药剂', '阿尔萨斯让我们所有人都变成了这幅佝偻的样子，剥落了我们死后的宁静。随后，我们皇家药剂师学会也决定大力研究自己的药剂。$B$B现在，这种药剂已经研究完成，并且我们还计划将它运用在这里，天灾军团的腹地。$B$B然而，那条载有幽暗城实验室新培植的药剂的船却被联盟海军击沉了。立刻到东南边的沉船残骸边上去回收装有药剂的容器，挽回越多越好。', '复仇港的药剂师雷杉德尔要求你从东南边的沉船残骸附近回收10个完整的药剂容器。', '你安全地回来了，真不错。其实光是带着这些容器就染疫的机率，也并非完全没有，不过我想我应该早提醒过你了。', '你回收了那些瓶子吗，$N?', '', '去嚎风峡湾找复仇港的药剂师雷杉德尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11168, '强化毒素', '我感觉长时间的海上旅行似乎影响了药剂的效果。我们得用一种强力的催化剂刺激出药剂本身的活性。$B$B根据我的记忆，洛丹伦大陆那边一种小体型的热带棕壳潮行蟹体内就有蕴涵着非常厉害的催化剂，它的麻痹性甚至可以在几秒内把一只食人魔弄得不醒人事。而附近海滩上的这些螃蟹似乎是那些热带潮行蟹的变种，理论上体内也应该有强烈的催化活性。$B$B而且，根据我们熟知的“体型大一切都大”的原则，这些本地变种体内巨大的毒腺一定具有更强的催化活性。给我弄一些回来！', '从巨型潮行蟹身上获取3个巨型毒腺，把它们交给复仇港的药剂师雷杉德尔。', '你一再地证明了自己的能力，$N。希望这些毒素能够把我们的瘟疫强化到要求的标准。$B$B最起码它也应该要能削弱得病的人，然后让他们更容易被感染。', '你拿到了我要毒素腺体了吗，$N?', '', '去嚎风峡湾找复仇港的药剂师雷杉德尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11169, '恐怖图腾的武器', '我在上次恐怖图腾进攻的时候受伤了，不过在受伤之前，我从敌人那里夺取了一根奇怪的图腾。$B$B那个东西在战斗中会发出让人感到刺痛的魔法箭，不过我实验了这么久，还是想不出它是怎么运作的。如果你愿意帮我测试一下那图腾的话，我很愿意把它借给你。$B$B那些令人讨厌的尘泥杂斑鳄鱼把农场周围的泥沼地当成了自己的家。相信我，你不会找不到它们的。尽量在图腾附近和鳄鱼战斗吧。', '塔贝萨农场的学徒加里奥希望你在10头尘泥杂斑鳄鱼身上测试被捕获的图腾。', '<学徒仔细听着你关于测试情况的描述。 > $B$B薄雾和一些闪电?就这样?那个图腾一定不只这些!恐怖图腾不会把这种东西带上战场除非它有一些实际的功效.', '你测试图腾的时候可有什么好运?', '', '去尘泥沼泽找塔贝萨的农场的学徒加里奥。', '测试图腾', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11170, '海中测试', '我们最近收到的情报指出，联盟军队即将获得大量的增援。这时机真是好得不能再好了！$B$B就先让联盟派过来的那些北方舰队预备兵尝尝这种药剂的厉害吧！$B$B带上这些药剂瓶，然后去找蝙蝠管理员卡米蕾，告诉她你要征用一只蝙蝠执行特殊任务。$B$B等你骑着蝙蝠飞到海上之后，使用你的药剂瓶就可以了。真想马上知道实验的结果呀！', '与蝙蝠管理员卡米蕾交谈，骑乘蝙蝠前去拦截联盟的增援部队。飞到联盟舰队上空时，使用药剂瓶拦截他们并统计16份测试结果。', '嗯…实地测试的结果…不太令人满意!', '你回来了!', '', '去嚎风峡湾找复仇港的药剂师雷杉德尔。', '拦截北方舰队预备兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11171, '妖术领主？哈！', '太棒啦！看来我很快就能进入祖阿曼了。$B$B$N，你表现得非常出色。我和同伴们谈过了，他们对你的印象颇好哟。你马上就能成为我们中的一份子啦。眼下，你还得完成一项任务——除掉妖术领主。$B$B这对你来说简直是小菜一碟。只要你毫不畏惧地向他发动攻击，这家伙就会胆怯地转身逃走。那些年老体衰的巨魔通常会给自己冠上可怕的头衔，以此掩饰他们脆弱的本性，你明白吗？', '战斧岭的巴德·奈德雷克要你转至祖阿曼，杀死妖术领主玛拉卡斯。', '终于!现在轻松的工作都完成了，我现在可以在历史上留下另一笔了。但首先，还有一件小事你要处理…$B$B我担心，$N，是时候要让你走了。我感觉到你的潜力就算还没超过，也已经到了尽头。$B$B别难过。毕竟这需要一个超凡入圣的人才能进行如此卓越的事情而不会失去他们的心智。来这儿看看。我有点小东西要留给你好让你时时想起我。', '我希望你会感激我给你的好机会，$N。$B$B你解决了老玛拉克雷斯没?', '', '去找幽魂之地的巴德·奈德雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11173, '沼泽中的毒药', '如果你指望学徒莫兰恩去做些什么的话，我想他所能做的也只有对着材料发牢骚了。$b$b我通常都是无视他，但根本不起作用。这次，我要试些不同的方法。$b$b如果我在他发现之前把缺少的材料放回去，也许他就能让我安静一会了。我们都要用到的最常用的材料是沼泽毒药，那东西可以从农场北面沼泽的暗牙爬行者和毒性切割者身上得到。如果你能帮我弄来毒药，我就可以在莫兰恩发现前把它放回去。', '将6瓶沼泽毒药交给塔贝萨农场的学徒加里奥。', '〈学徒加利昂检视着毒液。 〉 $B$B这真是太完美了!他将不会发现任何差异之处。', '你取得毒液了吗?莫兰恩随时都可能发现它不见了……', '', '去尘泥沼泽找塔贝萨的农场的学徒加里奥。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11174, '阻止腐蚀', '看看这个地方！到处都是软泥怪，要是我不想点什么办法控制它们的话，它们就会腐蚀掉残骸和飞艇的货物！$B$B我不能空手回去，$c！在这些软泥怪消化掉所有东西之前，帮我消灭它们吧！$B$B这台设备充电后可以将能量集中到这些软泥怪身上，让它们爆炸。飞艇的能量核心碎片应该可以给这台设备提供能量，靠近主坠毁点的那个始终可以正常工作，不过其它的时好时坏。', '莫希·斯蒂格里希望你去溶解10只软泥怪，然后回到比吉尔的飞艇残骸旁向她复命。', '嗯，这里的确看起来空多了…… $B$B我想接下来是时候抢救这些残骸了。', '你对这些软泥怪的进展如何呢?', '', '去尘泥沼泽找比吉尔的飞艇残骸的莫希·斯蒂格里。', '溶解软泥怪', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11178, '督军之血', '当你观察这只瓶子时，你突然想起了祖阿曼外面那个狂妄的家伙。$B$B你迫不及待地想要看到巴德的表情！', '把祖尔金之血交给祖阿曼外面幽魂之地的巴德。', '你是说那―那个祖尔金身上的血吗?$B$B<回神了以后，霸德继续说下去。>$B$B感谢你的好意，$C，但是我早就可以轻易地打倒他了。他不可能像传说中的那么可怕。有些东西总是被故事给夸大了，将来你就能体会这点。更可能发生的是，那个可怜的老侏儒败给了关节炎!$B$B总而言之，我想在我对你如此慷慨之后，这是你能提供最起码的回报。$B$B现在你可以离开了―我必须处理这罐瓶子!', '<霸德试着在你面前掩饰他的不悦。>$B$B又是你…$B$B我不知道该说什么了 - 准备事项实在太忙了，我真的没空照顾你了。$B$B相信我，$N，这是一切都是为你好。或许，靠着一些奇迹，你可以靠自己成就一点名声。$B$B假如这真的发生，你就可以跟别人说当初是举世无双的霸德.奈德瑞克提拔的!', '', '去找幽魂之地的巴德·奈德雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11180, '女巫岭的幽灵', '我长途跋涉来到这里拜访加尔的新家，但无尽的恐惧一直在笼罩着我！这里肯定有什么东西有问题，并不是只有我的感觉有问题而已……$B$B你看到那些在女巫岭附近游荡的鬼魂和尸体了吗？如果说有人会知道这里曾经发生过了什么，我想也只有他们了。在这附近寻找复活的躯壳和复活的游魂，打败他们，让他们安静下来，在这些恶魔吞噬掉加尔之前，看看你能从他们身上了解到什么！', '水光庄园的摩丹特·格雷斯比希望你能从10个复活的躯壳或复活的游魂身上收集到信息。', '<莫丹特拿出羊皮纸与笔，开始记录你的发现。>$B$B透过你的发现，那些鬼魂不只是此地过去的居民，而是每一个曾在这里生活过的人。$B$B某种东西腐化并且杀害了他们。那些人无法及时发现问题。我们一定得要阻止这件事，$N!', '你从在此出没的冤魂身上知道了些什么?', '', '去尘泥沼泽找水光庄园的摩丹特·格雷斯比。', '收集信息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11181, '除巫草', '在我身为草药师的这么多年里，我观察到大自然可以为大部分烦人的问题提供完美的解决方案。我曾经读到流浪法师和巫医经常使用一种被称为“除巫草”的草药，它的烟能将恶魔从隐藏的暗处吸引出来。$b$b如果这是真的，那么除巫草应该就生长在女巫岭的浅水附近。它有着阔叶和红色茎秆，你应该很容易就能分辨出来。把你能找到的药草都带回来给我吧，$N。它可能是我们唯一的希望了。', '将9根除巫草交给水光庄园的摩丹特·格雷斯比。', '<莫丹特收下了你给他的草药。>$B$B这完全符合那些描述!我在你出去的时候准备好了火炬。接下只需要把草药固定在火炬的末端就行了。', '你有替我找到任何草药吗?我们得加快动作，要赶在那种不知名的邪恶大举入侵控制这个地区之前。', '', '去尘泥沼泽找水光庄园的摩丹特·格雷斯比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11182, '问题的根源', '平衡是自然界的主旋律。只有剔除那些不和谐的音符，才能实现真正的平衡。$B$B这么说吧，杀死幼龙抑或是摧毁龙蛋的做法是治标不治本的。新近崛起的维库人以及他们的主人——斯克尔德·达拉克森才是这场森林火灾的罪魁祸首。$B$B去击败他们吧，他们的巢穴就在灰烬龙巢南部。', '杀死斯克尔德·达拉克森和5名掠龙训练者，完成任务后向灰烬龙巢中的灰烬龙巢古树复命。', '很不幸地，我们得靠掠食者来解决另外一种掠食者，但这就是自然的法则。$B$B或许现在那些元龙和他们的幼龙能够恢复到平静的生活。虽然我很怀疑，在维库人重新苏醒的情况下，它们是否真的办得到。', '对付那些好管闲事的管理器的事情你进行得如何了，小家伙?', '', '去嚎风峡湾找灰烬龙巢古树。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11183, '净化女巫岭', '火把已经准备好了。把它插在码头的尽头，对可能出现的一切情况做好准备吧。$B$B我不知道火把的浓烟会带来什么……如果真的有东西出现的话。我必须说，我对这种民间魔法是有所怀疑的，但现在我们也没有时间来想其它办法了。看在你和加尔的份上，祝你好运。', '水光庄园的摩丹特·格雷斯比希望你将火把放置在码头的尽头，并打败随后出现的任何东西。', '它有用吗?$B$B<莫丹特清了清喉咙。>$B$B我的意思是…它有用!加尔和我欠你一份情，$N。现在唯一的问题就是我朋友对于家具的品味了，不过我想这恐怕没那么好解决。', '结束了吗?', '', '去尘泥沼泽找水光庄园的摩丹特·格雷斯比。', '净化女巫岭', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11184, '悬赏：贪婪的血爪', '旅行者以及从事野外作业的热砂港雇员请注意，不要靠近城镇西边的鲜血沼泽墓穴。$B$B大群迅猛龙盘踞在那片区域，它们的首领“贪婪的血爪”既残忍又狡猾，至少有两名热砂港工程师惨死于这只野兽的利爪之下。$B$B如果谁能替泥链镇解除威胁，德拉兹特·迪普瓦尔愿意慷慨解囊，奖赏这位勇士。', '杀死贪婪的血爪，然后向泥链镇的德拉兹特·迪普瓦尔复命。', '感谢上天终于有人担下了这个任务。我差点以为我得把赏金加到三倍才有人肯把那只蠢迅猛龙给干掉，但我们的预算可付不出这笔数字!', '你看起来对自己信心满满。是来领那只怪物迅猛龙的赏金吗?', '', '去尘泥沼泽找泥链镇的德拉兹特·迪普瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11185, '药剂师的信', '这封信是从一个被遗忘者炼金师的尸体上得到的，信的内容显示了恐怖图腾和洛丹伦新主人之间关系密切的证据。$B$B“作为善意的表示和我们新创建的信任的标志，我们派出了炼金师塞尔拉，帮助你们与卡利姆多大陆上的那些我们共同的敌人作战。没有人可以打败我们联合的力量和决心。”$B$B这封信应该会引起塔贝萨农场那位军情七处密探安德罗·波特的注意。', '将密封的信函交给塔贝萨农场中的安德罗·波特。', '<安德罗阅读这封信件，对信中的内容感到震惊。>\r\n\r\n我们一直以来都担心部落和被遗忘者之间的合作关系，而这封信证实了我们的疑虑。随着被遗忘者暗中供应的魔法和装备，恐怖图腾将成为更可怕的敌人。卡利姆多的势力平衡可能因此而变的动荡不安。', '你身上带着的是什么东西呢，$C?', '', '去尘泥沼泽找泥潭沼泽的安德罗·波特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11186, '背叛的端倪？', '这封信是从一个被遗忘者炼金师的尸体上找到的，信的内容暗示了恐怖图腾和幽暗城之间的秘密联系。$B$B“作为善意的表示和我们新创建的信任的标志，我们派出了炼金师塞尔拉帮助你们在卡利姆多与我们共同的敌人作战。没有人能打败我们联合的力量和决心。”$B$B也许蕨墙村的纳泽尔·血矛知道该怎么处理这种信息。', '将密封的信函交给蕨墙村的纳泽尔·血矛。', '假如这封信的内容属实，那么被遗忘者必须提出合理的解释! $B$B恐怖图腾卖弄的这些小动作一直以来都在挑衅着酋长的耐心。我们过去一直把它视为牛头人一族的问题，但是这封信将改变这一切。 $B$B我们需要一些时间来调查这件事，但是别跟其他人谈起你今天的所见所闻。', '你身上带着的是什么东西呢，$C?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11188, '一错再错……', '我们激怒了灰烬龙巢的始祖龙，它们很可能会持续攻击要塞……这可不行。$B$B我讨厌做挖肉补疮的蠢事，但是当前看来只能杀掉这些生物了。虽然这样做令我于心不忍，可我们别无选择。$B$B喏，这是我的魔杖。我已经设法延长了它的射程，可惜威力很一般。不过没关系，它能吸引始祖龙的注意就行啦。', '西部卫戍要塞的法师中尉玛利斯特要你杀死3只始祖幼龙。', '<法师中尉叹了一口气。>$B$B真是个糟糕的任务。好吧，事情做了就是做了。起码那些在馀烬窝巢成长的幼龙应该不会知道我们可耻的行为。$B$B如果再好运一些的话，那个魔法森林的范围应该也不会继续扩张了。$B$B拿着，$N，这点从藏宝库拿出来的报酬，希望能弥补给你添的麻烦。这是我们至少能做的。', '真不幸，队长要你去激怒那些元龙。尽管他们欠缺一般我们熟知的龙族智慧，但他们依旧看起来像是种高贵的生物。更别提这带给我们的处境。$B$B我能斗胆询问你状况解决了吗?', '', '去嚎风峡湾找西部卫戍要塞的法师中尉玛利斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11190, '非标准炮弹', '是哪个天杀的设计出这些非标准尺寸的大炮？这下好了，我们不得不为这些大炮铸造特殊的炮弹！$B$B如果你能帮我们捡回射出去的炮弹，我会好好谢谢你的。从发射炮弹的轨道来看，它们肯定落在了南边和东边。$B$B<炮兵张开双手，比划着炮弹的尺寸。>$B$B这肯定比重新铸造新的炮弹要快。', '收集10颗西部卫戍要塞炮弹，将它们交给西部卫戍要塞的炮兵伊莱。', '喔，祝福你，$N!$B$B只要让我把它们的尺寸调整一下。我手下的小伙子会尽快把它们填装好，接下来我们就不需要担心斯考恩的问题了。', '我们炮弹的数量越来越少，$C。我们的敌人需要被重击，尤其是那些斯考恩!$B$B你拿到需要更多的炮弹了吗?', '', '去嚎风峡湾找西部卫戍要塞的炮兵伊莱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11192, '蛇颈鱼油', '灯塔里古老的航海日志上记载着，可以用生活在这附近海岸的蛇颈龙的油作为燃料。$B$B<巴布在提起这种过时的技术时皱了一下鼻子。>$B$B我想这会有用的，虽然只能算是个土办法。日志上还写着，最年幼的黑色蛇颈龙是最好的选择，而那些家伙就生活在塞拉摩的码头下面。$B$B如果你要去那里的话，能帮我弄点灯塔所需的燃料吗？', '将4瓶蛇颈龙油交给塞拉摩附近灯塔的巴布·菲兹托克。', '老实说，我有点怀疑，但这是现在唯一可行的办法。一旦我们让那座灯塔重新运作，我相信就有时间可以寻找其他方法提供那盏灯燃油了。', '你取得那种蛇颈龙油了吗?', '', '去尘泥沼泽塞拉摩岛找巴布·菲兹托克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11193, '深海中的卑鄙生物', '要知道，能在这座古老的灯塔里面找到这东西实在是太棒了。在我点亮了灯以后，我发现某个古老的箱子里有本书。$B$B<巴布拿起书，激动地读着书名。>$B$B《深海中的卑鄙生物》！$B$B啊，我想若是有幸看到里面所说的生物，我可能会笑得昏过去！我相信这本书实在很搞笑，不过现在我完全没时间去读它。$B$B你知道谁会感兴趣，就是那个码头上的鱼商，“脏鬼”迈克尔·克罗维。他收藏古老的书籍。', '将《深海中的卑鄙生物》交给塞拉摩码头上的“脏鬼”迈克尔·克罗维。', '嗯，鲍伯斯还真好心叫你送来给我。我不知道你看过这本书了没，不过书中的故事有许多都是真的。你也知道它们并不完全是水手们虚构的。', '今天想买什么呢?婢鲈看起来相当新鲜。', '', '去尘泥沼泽找塞拉摩岛的“脏鬼”迈克尔·克罗维。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11195, '破烂的巫毒人偶', '我太感动了，$n，居然是真的。我都不记得上一次有$r帮助苏加姆走出困境是什么时候了。$B$B这个是我从一个忙着锁住我的野蛮人身上弄来的，看上去并不值多少钱，但是如果说有人可以确定它的价值，我想就只有我的好朋友格里伏塔了！$B$B如果你能成功活着离开这里，不如把这个交给他看看。', '将破烂的巫毒人偶交给沙塔斯城的格里伏塔。', '嘿，你从哪里弄来这个?$B$B不，不，不要告诉我 -', '嗨，$N!我听说你要去加入霸德。你一定不会后悔这件事的，朋友，我可以保证。$B$B你那边有些什么，兄弟?', '', '去找沙塔斯城的格里伏塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11198, '击败泰瑟尔！', '不管海怪是不是真的存在，我们都不准备让船只去冒险。我已经命令最棒的神射手做好与泰瑟尔交战的准备了。炮兵已经在码头增加了三门迫击炮。如果泰瑟尔进攻的话，你的任务就是在那个怪兽杀害所有神射手之前，用迫击炮打倒它。', '塞拉摩码头的米尔斯少校希望你打败泰瑟尔。', '干得好，$N!我得承认，当我第一次看那个怪兽的时候，我怀疑我们能不能守住码头，但你却漂亮地使守军团结在一起!', '回报你的情况。', '保卫塞拉摩港口不受泰瑟尔破坏', '去尘泥沼泽找塞拉摩岛的米尔斯少校。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11200, '绝非偶然', '我们从旅店的废墟里收集了尽可能多的线索。我不知道调查的结果到底是什么，但我们必须知道真相。$B$B这些蹄印和有着莫萨恩记号的盾牌，让我感觉到恐怖图腾可能和这件事有关。他们最近在沼泽地里创建了一个被称作黑蹄村的定居点，就在这里的东北方向。去黑蹄村寻找更多莫萨恩的武器制品吧。', '蕨墙村的克罗格希望你去收集7份黑蹄军备。', '<克罗格检查你从黑蹄村带回来的武器和装备。 > $B$B这肯定是莫萨恩的作品。询问莫萨恩可能会引起太多的关注，但我们在对付恐怖图腾上仍有其它的选择。', '你在黑蹄村的搜索行动有什么发现吗?', '', '去尘泥沼泽找蕨墙村的克罗格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11201, '恐怖图腾的密谋', '随着恐怖图腾在千针石林的行动被揭露，现在很多牛头人都对他们产生了怀疑。我们了解到恐怖图腾的高阶成员使用谋杀和绑架的手段来提升他们的影响里，也许我们会变成他们的下一个目标。$B$B东北边靠近蓝色沼泽的黑蹄村是恐怖图腾新的大型据点。他们的长者都按照从雷霆崖送来的命令行事。去看看你是否能截获他们的命令书，把它们拼凑起来，了解恐怖图腾的计划。', '把恐怖图腾作战计划交给蕨墙村的克罗格。', '<克罗格阅读着这份作战计划。 > $B$B我深信这些恐怖图腾正转向对付人类。我尚未理解的是他们对我们抱着什么样的企图。恐怖图腾的行动在过去不断挑起部落之中紧张的情势，但酋长一直舒缓这种紧绷的情势。', '你有找到任何命令的线索吗?', '', '去找尘泥沼泽的克罗格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11202, '任务：永恒的烈焰', '被遗忘者可没安什么好心，你瞧，他们显然是想利用那些药剂罐做坏事。$B$B我觉得吧，我们应该尽快摧毁这些罐子，省得日后麻烦。我从灰烬龙巢搞来了一些火把，它们燃烧了好几天都没有熄灭！$B$B给，我相信你比我更擅长于火焰净化，去摧毁那些药剂罐吧。', '灰烬长矛塔楼的斥候诺勒斯要你利用永燃火炬摧毁哈尔格林德附近的4只药剂罐。', '太好了!$B$B但你在瘟疫槽里面找到的是什么?你说被遗忘者在对那里的维库人散布瘟疫?', '真的很难说明这里到底发生了什么事。你把那些瘟疫槽烧毁了吗?', '', '去嚎风峡湾找灰烬长矛塔楼的斥候诺勒斯。', '摧毁西南部药剂罐', '摧毁西北部药剂罐', '摧毁东北部药剂罐', '摧毁东南部药剂罐');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11205, '烧毁恐角岗哨！', '根本没有必要用水晶球来看看我们的新“邻居”在干些什么。如果这就是焚毁树荫旅店的那支部队，那么我们也没有理由再容忍他们的存在。$B$B拿上这根火把，将他们的营地夷为平地吧！你可以在我的农场略北一些的地方找到恐角岗哨。你不可能看不到，真的，因为恐怖图腾在那里竖着许多非常华丽的图腾，以此表明他们对图腾的喜爱。', '烧毁恐角岗哨的北部帐篷、东部帐篷和东北部帐篷，然后回到塔贝萨的农场，向塔贝萨复命。', '恐怖图腾应该可以轻易地了解我们最近的行动想表达的敌意。 $B$B至于你，你在蕨墙村的联络人一定很想知道你干的好事。我知道烧毁树荫旅店这件事可能会成为部落和联盟之间情势紧绷的导火线。假如我遇到塞拉摩派来的调查员，我会很高兴的转达恐怖图腾独力犯下这起事件。', '你有好好利用那把火炬吗?', '', '去尘泥沼泽找塔贝萨的农场的塔贝萨。', '烧毁北部帐篷', '烧毁东北部帐篷', '烧毁东部帐篷', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11207, '回收货物！', '这艘飞艇运送了足足6个月的补给品给我们的泥链镇！当然，他们可以想办法坚持一段时间，但他们没法坚持太久。$B$B我被派到这里来寻找任何我能找到的货物，但飞船的残骸支离破碎地散落在这块区域。我确信有很多货物没能在坠毁中幸存下来，但你能帮我找到尽可能多的货物吗？', '比吉尔的飞艇残骸处的莫希·斯蒂格里要你找回8件飞艇上的货物。', '哇!你收回的货物比我预期可找到的还多。我不确定德拉席特以为我们能找到多少货物，但是现在他应该对我们寻回的数量感到高兴才对。', '<莫克希看起来相当地担忧。>$B$B货物都还在吗?你有找到幸免的货物吗?', '', '去尘泥沼泽找比吉尔的飞艇残骸的莫希·斯蒂格里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11208, '给德拉兹特的货物', '德拉兹特会很高兴看到这些货物的，不过我不觉得这地方已经被清理干净了，所以我还不能离开这里。如果你有时间的话，你愿意帮我把货物送到泥链镇去给他吗？$B$B如果你还没去过那里，那我告诉你，那里是石槌废墟另一边的一个小小的定居点。你也可以沿着塔贝萨的农场那边的路过去。在你到达泥链镇以后，你要做的事情就是找到德拉兹特·迪普瓦尔。', '把飞艇上的货物交给泥链镇的德拉兹特·迪普瓦尔。', '<德拉席特接过你手上的货物。>$B$B我可真是饿了，饿得可以吃下一头龙!感谢上天莫克希终于设法将一些货物送到这里来。\r\n我们已经沦落到要和巨魔玩骰子，来换取任何落入他狩猎陷阱的东西!', '嗯?', '', '去尘泥沼泽找泥链镇的德拉兹特·迪普瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11209, '纳特的交易', '这么说来你找到了一本《深海中的卑鄙生物》，是吗？好吧，以我的经验来看，一切都是真的。我甚至还亲眼见过几个。$b$b不过你真的想知道什么是泰瑟尔吗？这样吧，我和你来做笔交易吧，我正在研制一种新的鱼饵，但我还没有机会来测试它。我希望你能帮我去测试一下。$B$B只要把这些鱼肉酱——没错，它闻上去有点腐烂的味道——粘在你身上，然后游到西南方的那座破船周围去。如果你能活下来的话，回来告诉我效果如何！', '纳特的码头上的纳特·帕格想让你去测试一下他的新鱼饵。', '不错嘛，但你要知道，如果我是你的话，我会尽快去洗个澡。\r\n\r\n现在，关于你的海怪…\r\n\r\n为了你好，现在先多喝两杯吧。', '记着，交易的条件是‘要是没东西咬你的话，就别回来。’', '', '去尘泥沼泽找纳特的码头的纳特·帕格。', '测试鱼肉酱', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11217, '龙尾草', '飞艇的坠毁延缓了补给品的到达，我们的药品和绷带都用完了。$B$B我们正在利用一切可以获得的资源，不过这些虫子、伤者和一切与我们为敌的家伙都让我们焦头烂额，我快要坚持不下去了！我找到了一种草药，可以治疗伤口和缓解疼痛，但它也快要用完了。$B$B这种草药被称为龙尾草，它遍布在村子东面的黑龙谷和巨龙沼泽地区。那种植物的茎杆是卷曲的，而且似乎会微微地跳动。', '泥链镇的吉兹克斯·格里古格希望你帮他收集8根龙尾草。', '感谢你!这将使我们能在莫克希从飞艇失事地回来之前继续从事一些野外的活动。', '你有找到龙尾草吗?', '', '去尘泥沼泽找泥链镇的吉兹克斯·格里古格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11218, '危险！爆炸品！', '$N，亚当斯上尉交给我一项棘手的任务，而我需要你的帮助。$B$B我在探险者协会的一群同事进入北边的低语峡谷从事挖掘工事，但他们突然全都疯掉了。你能想象吗？他们会攻击所有企图接近峡谷的人。$B$B亚当斯上尉的脑子里却只有矿石供给这一件事情。好在我有办法解决眼前的难题。$B$B我要你进入低语峡谷，炸开矿脉，然后把矿石碎片和宝石给我带回来。维持要塞的运作可不便宜！$B$B不过我要警告你，那里的矿石很奇怪！', '利用斯迪尔林的安全雷管收集6份低语峡谷矿石碎块和18颗低语峡谷宝石，将它们交给西部卫戍要塞的斯迪尔林。', '矿石带给你奇怪的感觉?也许我们根本就不会用到那些东西。$B$B<钢环看了看，往后退一步，然后改变了话题。>$B$B这些宝石看起来真不错!不晓得我可以从中得到些什么?当然啦，总是有东西要修，新东西要做。$B$B你知道吗，我真的觉得跟你一块儿工作有很多油水可以捞。收下这些…这是我最少能做到的!', '在这里的建筑工事似乎是个没完没了的工作，我真希望你能拿到让我们能继续进行工作的物品。', '', '去找嚎风峡湾西部卫戍要塞的工兵斯迪尔林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11219, '赶快灭火！', '部落的孩子需要你，$n。无头骑士曾经是一位人类圣骑士，然而现在却变成了一个疯狂的恶魔，在我们的村子里面纵火！你必须去扑灭那些火焰！提上一桶水去扑灭熊熊燃烧的火焰，要么就把它交给离火焰更近的伙伴们。熄灭所有的火焰，挫败无头骑士的阴谋吧！', '戴面具的孤儿院长希望你能帮忙扑灭村子里的所有火焰。在扑灭了所有火焰之后，回去向戴面具的孤儿院长汇报。', '火势被扑灭了!你和你的救火队胜利了!呀哈!$B$B无头骑士的攻击失败了，但除非他和他的头一起被消灭，他还会再回来的。$B$B在此之前，让我们好好享受你为这些孩子们带来的安全吧。我很荣幸能目睹你今天勇敢的行为。', '部落的孩子需要你!别抛下他们!', '扑灭火焰', '去找戴面具的孤儿院长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11221, '战况报告', '我们来到诺森德的目标是干掉阿尔萨斯。联盟是我们唯一的绊脚石，看到他们时绝对不能手软。$B$B我们已经摧毁了他们最东边的舰队，但那些残馀份子却在南边的荒弃海岸设置了路障，躲藏了起来。$B$B我们的部队早该摧毁他们的临时工事，但显然我们低估了他们的求生欲望。到战场上去找到我的部下，黑暗游侠莉安娜和死亡猎手拉扎尔，让他们报告当前的形势。', '转至复仇港南方的鲜血谷，与战场上的黑暗游侠莉安娜和死亡猎手拉扎尔谈一谈。完成任务后向高级执行官安希尔姆复命。', '火炮阻碍了我们的攻势?我会让他们见识看看什么才叫火炮。', '你要回来报告了吗，$N?', '', '去嚎风峡湾找复仇港的高级执行官安希尔姆。', '听取拉扎尔的报告', '听取莉安娜的报告', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11224, '骡子和货物', '谣传北面的低语峡谷发生了可怕的事。数日前，探险者协会的一批勘查员进入了峡谷，据说他们发现了某种能令人发疯的东西。$B$B最要命的是，他们带走了绝大多数的骡子和装备。我可不想失去那些骡子！$B$B如果你碰巧要去那里，又碰巧遇见我的骡子的话，就悄悄地靠近，然后挥舞手臂吓唬它们。这样。它们肯定会害怕得跑回来。', '探险者亚比盖尔要你吓唬10头被遗弃的骡子（使用/raise命令），然后返回西部卫戍要塞向她复命。', '我很感激你，$C。起码我们现在保住了大部分的骡子和装备，要重建的速度也会提高很多。$B$B拜托，请收下这些。', '这对我们来说真是一大打击。我甚至不想知道他们在那里到底发现了什么。$B$B光是用想象的，就足够让我一整晚睡不着觉了。', '', '去嚎风峡湾找西部卫戍要塞的探险者亚比盖尔。', '吓唬被遗弃的骡子', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11227, '让它们吃乌鸦', '高级执行官要我派猎犬把那些敌人的斥候探子还有间谍都给挖出来，但这帮死狗……你看，是瘟疫犬……的确是死狗……不把它们喂饱就不肯干活。$B$B我们的军人一点都没有意识到这群死狗有多么挑食，军队配给的那些垃圾狗食它们闻都不要闻，还怎么能指望靠狗抓斥候呢？$B$B如果……我是说如果，你有时间的话，不如帮我们喂饱它们。你看，西边有许多乌鸦，那些乌鸦的肉是这些死狗最爱吃的，虽然我们不觉得美味。怎么样，帮我带着一条狗去打一些乌鸦牙祭吧？', '复仇港的猎犬管理员伯提乌斯要求你使用瘟疫犬笼召唤一只饥饿的瘟疫犬，并用复仇港西边那些峡湾乌鸦的肉将它喂饱。', '你猎了几只乌鸦呢，小伙子?好狗儿，好狗儿!$B$B喔，这些猎犬让我想起来我在提里斯法饲养纯种犬的日子…那真是一段美好时光!', '你喂饱了那个小恶棍吗?', '', '去嚎风峡湾找复仇港的伯提乌斯。', '给瘟疫犬喂食', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11231, '钥匙和牢笼', '上校可能并没有注意到，但据我们所知，维库人正在亚勒伯龙的北部进行一种残忍的“觉醒”仪式。$B$B他们在那种邪恶的仪式上进行活祭！$B$B$C，你必须去阻止他们！无论那些牢笼里关着什么人或生物，我们都得把他们放走。我估计那些维库人身上会有钥匙。$B$B如果再不处理的话，天知道我们是会遇见更多诡异的维库人，还是他们会唤醒某些更邪恶的东西！', '莱瓦里安神父要你去搜集足够的亚勒伯龙牢笼钥匙，用它们解救10个亚勒伯龙囚犯。完成任务后，返回西部卫戍要塞向他复命。', '圣光祝福你，孩子!有了你的帮助，圣光甚至能照亮最黑暗的角落。$B$B拜托，收下这个以补偿你的善行义举。我可以看见你所释放的那些人获救;起码，那些真的与圣光和联盟同在的人，都回到这座要塞了。', '只要夏勒布隆的囚犯被释放，维库人就无法继续他们不洁的仪式。$B$B你是阻止他们的唯一希望。', '', '去嚎风峡湾找西部卫戍要塞的莱瓦里安神父。', '释放亚勒伯龙囚犯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11232, '指引方位', '现在我们可以发动反击了。但是现在的能见度比预期的要差一些，我们需要你到岸上去标记出打击目标。$B$B联盟的军队死守着西边的荒弃海岸，我要你带上这些烟雾弹，利用它们标记出荒弃海岸北墙外的炮位。$B$B标记了所有火炮的位置之后，你就立刻去向莉安娜报告。我们会照顾好自己的。', '使用烟雾信号弹标记出荒弃海岸北墙外的联盟火炮位置。完成任务后向鲜血谷的黑暗游侠莉安娜复命。', '太棒了。我会用信号通知我们的地面部队进行行动。', '那些火炮，$N。有人要去搞定它们吗?', '', '去嚎风峡湾找鲜血谷的黑暗游侠莉安娜。', '标记东面的火炮', '标记西面的火炮', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11233, '致命的打击', '你已经在战场上用行动证明了自己，$N。你的出色表现正使得战局向着对我们有利的方向发展。$B$B现在我要交给你一项非常重要的任务。我不知道我们的劣势还会持续多久，所以必须采取一些非常手段。$B$B我要求你在我们的进攻掩护下潜入敌人后方，刺杀他们的首领。他们分别是：欧斯勒上尉，塞雷尼中尉和洛瑞克中士。祝你好运，$c。', '复仇港南方的黑暗游侠莉安娜要你潜入荒弃海岸，杀死欧斯勒上尉、塞雷尼中尉和洛瑞克中士。', '这无疑代表着我方的胜利。安赛姆听到这个消息一定非常开心。', '那些联盟首领都死了吗，$N?除非他们都死了，不然不要回来。', '', '去嚎风峡湾找鲜血谷的黑暗游侠莉安娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11236, '通灵主宰麦森', '天灾军团正在亚勒伯龙出没，其中还有通灵师！他们肯定是想把维库人拉到阿尔萨斯的阵营里去。$B$B我要你去杀死这些通灵师的头目！$B$B$N，你要\r\n不惜一切代价完成这个任务。只要杀死通灵主宰麦森，那么无论他想要干什么，都会落空。$B$B我不想看见维库人和天灾军团结成同盟！$B$B麦森就在亚勒伯龙右后区的平台上。', '杀死通灵主宰麦森，然后返回西部卫戍要塞向亚当斯上尉复命。', '<队长松了一口气。>$B$B很好，这样减轻了我们的一些压力。$B$B$N，你又一次证明了你对镇西要塞和联盟的价值。从财宝库中挑选一些吧，$g小伙子:小姑娘;!这是我们起码能做的!', '你确定你杀死了梅赞和他的死灵领主，$C?', '', '去嚎风峡湾找西部卫戍要塞的亚当斯上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11237, '亚勒伯龙攻击计划', '这些计划清晰地表明了一场即将对西部卫戍要塞发动的进攻。看来盘旋在空中的冰霜巨龙格拉希恩将会被用作进攻的手段。$B$B法师中尉玛利斯特应该可以提供一些建议，将计划交给他，他就在南方的要塞中。', '转至西部卫戍要塞，将亚勒伯龙攻击计划交给法师中尉玛利斯特。', '$N，我们绝对不能让它发生!', '什么?!攻击要塞的计画!$B$B一只冰霜巨龙?!!!', '', '去嚎风峡湾找西部卫戍要塞的法师中尉玛利斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11238, '冰霜巨龙和它的主人', '幸亏你把这份计划书交给了我，$N。你必须带着援军转至北边的亚勒伯龙，杀死那条龙和它的主人，唤龙者维尔！$B$B我们说话这会儿，那条冰霜巨龙说不定已经在路上了。$B$B但如果我对这份计划的理解正确无误，只要能找到唤龙者放在亚勒伯龙左后区平台上的号角，吹响它就可以把格拉希恩召唤回去。等它着陆以后，你必须击败它！$B$B同时，$N，请把那只号角带回来交给我。我们不能让它再落入邪恶的人手里。', '杀死唤龙者维尔，使用唤龙者的号角召唤并杀死格拉希恩。然后返回西部卫戍要塞，将号角交给法师中尉玛利斯特。', '哇喔，那个号角真是冰啊!$B$B你又再一次的拯救了镇西要塞免于毁灭。你真是个令人感到好奇的$g男人:女人;，$N。要是多有几个你就好了。$B$B哎呀，这一定要受到奖赏的。你喜欢哪一样啊?', '阻止攻击了吗?冰霜巨龙和他的主人被摧毁了吗?$B$B你拿回号角了吗?', '', '去嚎风峡湾找西部卫戍要塞的法师中尉玛利斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11239, '为圣光效力', '你已经成为了我们的榜样，$N，但有些东西依然让我感到不安，那就是：天灾军团。$B$B圣光无法容忍他们的存在，我们也不能。我不知道这个要求是不是太过分了，但我希望你能回到北边的亚勒伯龙，杀死那些邪恶的天灾军团成员！别忘了顺便检查一下亚勒伯龙下面的苏醒之厅！$B$B净化是救赎的关键，我的孩子。我们为你感到骄傲！', '消灭10个不死的看守者、4个可怕的丧尸和2个腐烂的畸形妖，然后返回西部卫戍要塞向莱瓦里安神父复命。', '<神父静默地为你祷念祝愿。>$B$B祝福你，$N，你回应了我的祈祷。骄傲的立于圣光中，光荣的了解到你的行为非常的神圣!$B$B我相信教堂的保险箱里一定可以提供某些你用得到的东西。', '圣光经由你的行为散播出去，并进入所有的事物中。$B$B没有任何生物，没有任何地方，不管有多怪异，都无法可以逃过它的愤怒!', '', '去嚎风峡湾找西部卫戍要塞的莱瓦里安神父。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11242, '终于解脱了！', '愤怒囚禁了我，$N，而你则把我救了出来。尽管我一直认为我所做的一切都是正确的，但我的灵魂却一直在为那些不幸因我而亡的艾泽拉斯人民哭泣着，为他们所经历的恐怖与死亡而哭泣。或许，我不会再次迷失方向了。$B$B把这本祷言书带给孤儿们吧，这样他们就会明白，我不会再纠缠他们了。', '将这本破损的圣典交给闪金镇、卡拉诺斯或秘蓝岗哨的穿戏服的孤儿院长。', '这是什么?汤玛斯.托姆森的圣典?但这是无头骑士被诅咒前的姓名!这表示他终获自由了吗?这表示他不会在折磨这些艾泽拉斯的善良百姓了吗?$B$B多么令人喜悦的一天!$N，你的事迹将永远与我们同在。孩子们，那些孩子们将会歌颂你的英名!', '你有东西要给我吗，善良的$N?', '', '去找穿戏服的孤儿院长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11243, '如果瓦加德失守……', '一旦瓦加德港口失守，连接诺森德的主要供给线就会被切断。那样的话，我们沦为巫妖王的奴隶便是迟早的事了。我不清楚你的情况，但是我的妻子和三个孩子还在艾尔文森林等我回家，说什么我都要奋力一搏。$B$B眼下战况危急，我们必须调用所有能派上用场的人手。去前门帮助卫兵抵御那些怪物的入侵吧！', '嚎风峡湾瓦加德港口的凯勒中将要你杀死12个掠龙入侵者或掠龙座狼。', '你给了我们的防卫者超乎预期的协助，$N。现在的士气前所未有的高涨，感谢你。我相信他们能够应付剩下的突袭。我对你有更多的计画……', '世界的命运可能就掌握在我们手中。', '', '去嚎风峡湾找瓦加德的凯勒中将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11244, '营救行动', '一个月前，我们刚刚抵达瓦加德港口时，就和来历不明的畸形巨人交上了手。平日里自命不凡的将士们被打了个措手不及，军队损失惨重。一支考古队失踪，还有不少村民遭到绑架，被带去了废墟中。我们已经陷入了劣势。$B$B更糟糕的是，我派出去营救村民的斥候遭到了维库人的攻击。他们被捕鲸枪击中，奄奄一息地躺在港口正北方的那片森林中。拔出鱼叉，解除他们的痛苦吧！', '嚎风峡湾瓦加德港口的凯勒中将要你解救8名奄奄一息的瓦加德斥候。', '维库人对我们斥候所做的行为既残酷又野蛮。这是一种恐吓战术，想要削弱我们的决心…想让我们怕得四处逃命。$B$B它们失败了。$B$B我们要让这些混蛋瞧瞧和联盟开战会怎样!', '找到那些斥候!', '', '去嚎风峡湾找瓦加德的凯勒中将。', '解救瓦加德斥候', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11245, '危险的塔楼', '$G先生:女士;，如果我们想要通过斯克恩，就必须清除那些塔楼！$B$B如果您注意过那些塔楼，就会发现楼顶上站满了施法者。太靠近它们的话，我们都会完蛋的！$B$B但我们已经从西部卫戍要塞请求了火力支持。为了准确地摧毁那些塔楼，我们要尽量靠近它们，然后放出定位的烟幕弹。$B$B别靠得太近就行了！', '西部卫戍军士要你转至斯克恩，利用军士的烟幕弹标记四座塔楼的位置，供炮击定位用。', '标得好，$g先生:小姐;!我得记得请后方要塞的火炮手喝东西。', '只要那些投掷器存在，太过靠近的下场就只有死。', '', '去找西部卫戍军士。如果西部卫戍军士不在附近那么请使用你的西部卫戍令牌。', '标记西北塔楼', '标记东部塔楼', '标记西南塔楼', '标记东南塔楼');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11246, '可怕而必要的手段', '我们得到报告说，这些维库人会死而复生。他们和天灾军团不一样，是另一种形式的不死生物。$B$B我们不能冒这个险。$B$B来，拿着我的刀。当我们穿过这个地区的时候，你要用它确保那些被我们打倒的维库人不会再突然跳起来。这本该是我的工作，可惜我的胃比较脆弱。$B$B<中士幸灾乐祸地笑了笑。>$B$B这把刀我已经磨了一上午了，肯定非常好用。', '西部卫戍军士要你转至斯克恩，利用军士的弯刀确保20个斯克恩部族的维库人无法复活。', '嗯，$g先生:女士;，我得说你做那项工作的时候有点太过投入了。$B$B<士官小心翼翼地看着你。>$B$B总之，如果你不介意，我要拿回我的砍刀了。它有点钝了，而且我也不想要你意外滑跤然后把我也给砍了。', '我很确定，我不想看到这些大块头在我们打倒之后又站起来!', '', '去找西部卫戍军士。如果西部卫戍军士不在附近那么请使用你的西部卫戍令牌。', '确保斯克恩的维库人不再复活', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11247, '燃烧吧，斯克恩，燃烧吧！', '亚当斯上尉曾经严令我必须重点打击此地的基础设施。$B$B但既然现在这里由您负责，那您可以酌情处理。$B$B我建议我们是否可以去烧毁斯克恩洼地里的那两座长屋和兵营？我们只需要进入这些建筑内部，然后把这根火炬扔进去就行了。', '西部卫戍军士要你转至斯克恩，利用军士的火炬烧毁东北方的长屋、西北方的长屋以及兵营。', '非常好，$g先生:小姐;。没有你的帮助，事情也完成不了。$B$B我确信队长听到我报告我们在这的所做所为一定会感到很满意。', '我有个建议，当我们放火烧掉这些建筑时，可以不要在里面待太久吗?', '', '去找西部卫戍军士。如果西部卫戍军士不在附近那么请使用你的西部卫戍令牌。', '点燃西北方的长屋', '点燃东北方的长屋', '点燃兵营', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11249, '阻止升华！', '这张巨大的卷轴是用龙皮制作的。展开这张长达十尺的卷轴之后，你看到复盖着鳞片的卷轴上画着一副维库人的神秘仪式的场景。$B$B一个维库领主，在一群天使形象的生物的环绕中，正缓缓升入天堂。而这副图的后台，则是一个神秘而巨大的黑影。$B$B你突然意识到，这就是斯克恩的领主正要去做的事。你必须阻止他！在斯克恩的顶层，领主的房间外已经堆好了一大捆木柴。', '在领主的火堆附近展开维库升华卷轴，召唤出维库领主并杀死他。完成以后，鉴于这种仪式的性质，你确信西部卫戍要塞里的莱瓦里安神父会对这张卷轴感兴趣。', '没错，$g男孩:女孩;，那是不祥的东西，你显然做了对的选择。$B$B谢谢你把这个卷轴带来给我。我非常想要研究一下这东西的含意。如果要我大胆做出猜测，我会说这些维库人有可以超越死亡的方法;至少那些都是名人。$B$B由于你击败了温特斯考恩族长，你证明了他的无用。圣光只知道，假如你没有杀掉他，他会变成什么样子，还有他会对我们做什么恐怖的事。', '嗯?我可以帮你什么吗，孩子?', '', '去嚎风峡湾找西部卫戍要塞的莱瓦里安神父。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11250, '向斯克恩的征服者致敬！', '我们——好吧，是您——已经完成了我们在这里的所有任务。我必须承认，能够听从您这样一个出色的年轻$c的指挥，让我感到非常荣幸。$B$B上尉一定在等待您凯旋的消息，但是如果您打算再逗留一段时间，我也非常乐意为您效劳。', '将西部卫戍令牌交给西部卫戍要塞的亚当斯上尉。', '这真是个不可置信的好消息!我就知道你能办到，$N!$B$B总算这边有人能够获得一些成果!$B$B当然，这必须要有奖励。去吧，任君挑选，藏宝库为你而开。', '既然你人在这里，我想斯考恩已经不复存在对吗?', '', '去嚎风峡湾找西部卫戍要塞的亚当斯上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11252, '杀入乌特加德！', '听着，年轻人。我已经把我对于这群生物的了解记录下来了——还有你了解到的其它信息。这些是你必须知道的……$b$b维库人对战斗无所畏惧。确切地说，他们似乎很渴望战死在沙场上。他们的数量和凶残让我们毫无还手之力。$B$B不过他们非常敬重叫做一个因格瓦尔的家伙。我不知道为什么他们一直在寻求他的赞扬，不过如果能够打倒他的话，就一定可以重创他们的士气。$B$B然后，也许，我们会有机会……', '防御者墨尔顿指派你去消灭乌特加德城堡的劫掠者因格瓦尔。$B$B将因格瓦尔的徽记交给凯勒中将。', '太棒了!$B$B这可能就是我们一直期待的转机。$B$B干得好，$N!', '$N，看到你还活着很让我高兴。$B$B我们的伤亡快要超过可以控制的范围了。', '', '去嚎风峡湾找瓦加德的凯勒中将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11254, '龙皮地图', '仔细辨认后，你发现这张卷轴其实是一幅精心绘制的嚎风峡湾地图。各个村落都以相应的氏族徽记进行标识。$B$B复仇港所在的位置却画着一颗硕大的骷髅头。$B$B这幅地图对高级执行官安希尔姆来说显然具有极高的军事价值。', '将龙皮地图交给复仇港的高级执行官安希尔姆。', '<高阶执行官专心地看着地图，偶而抬起头看看峡湾附近的地形。>$B$B这里是东部的海岸线。掠龙者和温特斯考恩的村落在这里和这里…而我们在这里，标记着死亡。', '你有东西要给我看吗，$C?', '', '去嚎风峡湾找复仇港的高级执行官安希尔姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11255, '龙颅村的囚犯', '$N，战争远远没有结束。我们必须搭救村子中的幸存者。$B$B<凯勒中将对你点了点头。>$B$B前往北方的龙颅村寻找幸存者的下落吧。如果他们被囚禁起来了，你要设法打开牢笼。$B$B或许他们能提供更为详细的关于畸形巨人的情报。', '嚎风峡湾瓦加德港口的凯勒中将要你营救3名被俘虏的瓦加德囚犯。', '你救回来的士兵提供了我们一些有用的消息。那些怪物自称叫“维库”。居住在龙颅村的部族由一个叫做雅尼思的秘法师领导，而他又是另一个叫做『盗掠者』因格瓦的维库人的手下。', '有点毅力，$N!人命关天啊!', '', '去嚎风峡湾找瓦加德的凯勒中将。', '营救瓦加德囚犯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11257, '可怕而必要的手段', '我们的长者说这些维库人是可以复生的，他们可能就像你们所说的“天灾军团的行尸走肉”差不多，不过只是另一种复生方式。$B$B我们最好不要冒险行事。$B$B过来，拿上我的弯刀。在我们穿过这个地区的时候，确保那些被我们杀死的维库人不会再跳起来。$B$B我花了一个早晨的时间使它变得更锋利，我想应该够用了。', '冬蹄营地勇士要你转至斯克恩，利用勇士的弯刀确保20个斯克恩部族的维库人无法复活。', '你该不会做过屠夫吧?你使用砍刀的技巧真纯熟。$B$B<勇者小心翼翼的看着你。>$B$B我把刀拿回去罗，$C。', '维库人的传统真诡异，同意吧，$N?', '', '去找冬蹄勇士。如果他不在附经那么请使用你的冬蹄徽章召唤他。', '确保斯克恩的维库人不再复活', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11258, '燃烧吧，斯克恩，燃烧吧！', '灰烬图腾酋长命令我摧毁这里的建筑物。$B$B不过，现在这件事由你负责。$B$B我建议我们将斯克恩地区地势较低的两座长屋和兵营烧为灰烬吧。我们要做的就是进入这些建筑，然后用这把火炬烧了它们。', '冬蹄勇士建议你转至斯克恩，利用勇士的火炬烧毁东北方的长屋、西北方的长屋以及兵营。', '<勇者朝你点点头，明显地对你使用火炬的方式表示赞许。>$B$B让这些维库族人感受大地的热度吧。让他们了解到他们带给别人的恐惧!', '我建议当建筑物起火以后，就不要待在里面了。火灵对破坏的渴望不会放过我们两个的。', '', '去找冬蹄勇士。如果他不在附经那么请使用你的冬蹄徽章召唤他。', '点燃西北方的长屋', '点燃东北方的长屋', '点燃兵营', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11259, '危险的塔楼', '在我们穿越斯克恩的同时，还必须把那些塔楼给端掉。$B$B如果你有注意的话，就会发现它们的顶端站满了法师。要是离它们太近，无疑就意味着毁灭。$B$B不过，我们可以调用冬蹄营地的双足飞龙向这里进行空中打击。要这么做的话，我们就得尽可能靠近塔楼，然后你向塔楼顶部抛射一发烟幕弹。$B$B不过不要太靠近了。', '冬蹄勇士要你转至斯克恩，利用勇士的烟幕弹为空袭部队标记四座塔楼的位置。', '你的胳膊很强壮，$N。$B$B看来，那些双足飞龙总算派上用场，而不光只是整天杵着喝水而已。', '只要那些施法者在上面，太靠近那些哨塔就是找死。', '', '去找冬蹄勇士。如果他不在附经那么请使用你的冬蹄徽章召唤他。', '标记西北塔楼', '标记东部塔楼', '标记西南塔楼', '标记东南塔楼');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11260, '阻止升华！', '这张巨大的卷轴是用龙皮制作的。展开这张长达十尺的卷轴之后，你看到覆盖着鳞片的卷轴上画着一副维库人的神秘仪式的场景。$B$B一个维库领主，在一群天使形象的生物的环绕中，正缓缓升入天堂。而这副图的背景，则是一个神秘而巨大的黑影。$B$B你突然意识到，这就是斯克恩的领主正要去做的事。你必须阻止他！在斯克恩的顶层，领主的房间外已经堆好了一大捆木柴。', '在领主的火堆附近展开维库升华卷轴，召唤出维库领主并杀死他。完成以后，鉴于这种仪式的性质，你确信冬蹄营地里的安卡祖母会对这张卷轴感兴趣。', '没错，那是不祥的东西，你显然做了对的选择。$B$B谢谢你把这个卷轴带来给我，我非常想要研究一下这东西的意涵。如果要我大胆做出猜测，我会说这些维库人有可以超越死亡的方法;至少那些都是有资格的人。$B$B由于你击败了温特斯考恩族长，你证明了他没有资格。假如你没有杀掉他，天晓得他会变成什么样子，又会对我们做什么恐怖的事呢?', '嗯?我可以帮你什么吗，孩子?', '', '去嚎风峡湾找冬蹄营地的安卡祖母。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11261, '斯克恩的征服者！', '你完成了我们指派的所有任务，$c。我必须承认你干得很棒。看来$r并不像我最初所想的那样奇怪。$B$B灰烬图腾酋长一定很想知道你的成就，不过如果你决定待在这里的话，我会仍然和你并肩战斗。', '将冬蹄徽章交给冬蹄营地的灰烬图腾酋长。', '这真是好消息!你为我们离开的准备提供了许多喘息的空间。$B$B请收下其中一样谢礼吧。', '你带来了什么斯考恩的消息，$N?', '', '去嚎风峡湾找冬蹄营地的灰烬图腾酋长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11262, '除掉因格瓦尔！', '终于有人来了。我在这里等得实在太久，脑子都快要不好用了。整个侦察队只有我幸存了下来。$B$B我会把我的报告交给你，根据这些情报，你要采取怎样的行动就完全由你自己决定了。$c，你要知道，这东西可是多么来之不易啊。$B$B这些维库人就是一群无情的战斗机器。以他们的数量和凶残的战术来说，我们唯一的希望只能是打倒他们的首领，祈祷这样会引起他们内部的混乱。$b$b因格瓦尔是他们的首领，等你完成任务之后，把他的徽记交给安希尔姆。', '黑暗游侠玛尔拉要求你杀死乌特加德城堡内的劫掠者因格瓦尔，然后把他的徽记交给复仇港的高级执行官安希尔姆。', '干得漂亮，$N。除掉了他们的领袖，我们对抗那些维库人将会更成功。$B$B这样的付出一定要给予奖励!', '做好准备，$r。$B$B还有很路复用作等着你完成。这只是冰山一角。', '', '去嚎风峡湾找复仇港的高级执行官安希尔姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11263, '亚勒伯龙的麻烦', '幸存的远行者回来告诉我说，维库人在西面的要塞里苏醒了过来。$B$B那块禁地被称为亚勒伯龙，维库人正在那里进行着什么奇怪的仪式。$B$B我们不能坐视不管。$B$B你准备继续帮助我们吗？你能在亚勒伯龙的维库人完成他们的仪式、向这里发动进攻之前消灭他们吗？', '灰烬图腾酋长要你杀死15个亚勒伯龙战士、8个亚勒伯龙符文法师和8个亚勒伯龙沉睡卫士，然后返回冬蹄营地向他复命。', '请收下我的感激之意，$N。我知道，你对我或我的族人，并没有任何的责任。$B$B你说的那个地方仍然困扰着我，我感觉到我们的洗该地的行动尚未结束。', '夏勒布隆的战斗情形如何?', '', '去嚎风峡湾找冬蹄营地的灰烬图腾酋长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11265, '钥匙和牢笼', '根据现在所了解到的一小部分信息来看，维库人正在亚勒伯龙的北部进行一种残忍的“觉醒”仪式。$B$B他们在那种邪恶的仪式上进行活祭！$B$B$N，你必须去阻止这一切。不管笼子里面是谁，你都得解救他们。我猜想维库人一定会把钥匙带在身边。$B$B如果放任不管，那些奇怪的维库人就会给我们带来更多更严重的威胁，或者唤醒更加邪恶的东西……', '安卡祖母要你去搜集足够的亚勒伯龙牢笼钥匙，用它们解救10个亚勒伯龙囚犯。完成任务后返回冬蹄营地向她复命。', '听到你的成功，我肩膀上的大石头终于落了下来。而我也很开心的知道你所救出的囚犯就是牦牛人。$B$B请你收下这个礼物，回报你所做的一切。我要去照顾那些你救出来的牦牛人人。', '只要夏勒布隆的囚犯被放走，维库人就无法继续他们的仪式了。', '', '去嚎风峡湾找冬蹄营地的安卡祖母。', '释放亚勒伯龙囚犯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11266, '亚勒伯龙攻击计划', '这些计划清晰地表明了一场即将对冬蹄营地发动的进攻。看来盘旋在空中的冰霜巨龙格拉希恩将会被用作进攻的手段。$B$B塞莉亚·冰鬃应该可以提供一些建议，将计划交给她，她就在东面的营地里。', '将亚勒伯龙攻击计划交给冬蹄营地的塞莉亚·冰鬃。', '$N，我们不能让这件事成真!', '什么?!计画攻击我们的营地?$B$B凶手是一只天上的大巨龙?!!!', '', '去嚎风峡湾找冬蹄营地的塞莉亚·冰鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11267, '冰霜巨龙和它的主人', '你把这件东西交给我是非常正确的选择，但是我的双足飞龙恐怕无法战胜一条龙。你必须带着援军回到西边的亚勒伯龙去，杀死那条冰霜巨龙和它的主人——唤龙者维尔！$B$B我们说话这会儿，那条冰霜巨龙说不定已经在路上了！$B$B但如果我对这份计划的理解正确无误，只要找到唤龙者放在亚勒伯龙左后区平台上的号角，然后吹响它就可以把格拉希恩召唤回去。等它着陆以后，你必须击败它！$B$B$N，请把那只号角带回来交给我。我们不能让它再落入邪恶的人手里！', '杀死唤龙者维尔，使用唤龙者的号角召唤并杀死格拉希恩。然后返回冬蹄营地，将号角交给塞莉亚·冰鬃。', '这个号角就像这片土地一样冰冷…说不定更冷!$B$B你让冬蹄营地从必死的命运中存活下来，我们将不会在这里待太久。你真是个好奇的$g男人:女人;，$N。或许你们这些来自海洋另一边的$r家伙并不完全都那么坏。$B$B这一定要受到奖赏的。你喜欢哪一样啊?', '阻止攻击了吗?这个巨大的死亡巨龙和他的主人被摧毁了吗?$B$B你拿回号角了吗?', '', '去嚎风峡湾找冬蹄营地的塞莉亚·冰鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11268, '行尸走肉', '你为我们提供的帮助远远超出了我们的期望，$N，不过仍然有件事情让我感到烦心：就是这些所谓的天灾。$B$B大地和空气之灵，地下的水与火，都不能忍受他们的存在，但似乎对他们毫无办法。那么，我们要负责解决他们！$B$B也许我的要求太过分了，但我希望你能回到西面的亚勒伯龙去，消灭这群天灾！别忘了顺便检查一下亚勒伯龙下面的苏醒之厅！', '消灭10个不死的看守者、4个可怕的丧尸和2个腐烂的畸形妖，然后返回冬蹄营地向安卡祖母复命。', '<主母点点头，对你的行为表示赞许。>$B$B感谢你，$N，你做得很正确，并且替我们的撤离争取了更多的时间。我们很快就会往北去。$B$B我已经太老了;等我们要离去时，我不可能带走每一样东西。你想要替我分担一些吗?', '你消灭了那些横行夏勒布隆的活尸了吗?', '', '去嚎风峡湾找冬蹄营地的安卡祖母。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11269, '羽绒披风', '再过几天，联盟的先锋部队就该抵达这里了。我们得提前为将士们准备好过冬的物资，眼下就差披风啦。$B$B斑点角鹰兽的羽毛是绝好的内层填充材料，不过存货已经不多了！$B$B$N，帮帮我吧。如果不能按期缝制好足够数量的披风，亚当斯上尉肯定会扒了我的皮！现在正是角鹰兽换毛的季节，要塞附近的荒野上随处可见它们散落的羽毛。把你找到的羽毛都带回来交给我。', '基尔·克利瑟要你去收集10根斑点角鹰兽的羽毛。', '谢天谢地!这应该足以及时完成命令了。当然，我会等到队伍抵达才会入睡，不过那远比把亚当斯队长惹毛来得好多了。$B$B我听他们说过他的故事!', '你有带任何羽绒来吗?我非常需要它…', '', '去嚎风峡湾找维德瓦堡垒的基尔·克利瑟。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11270, '地狱般的战争', '我们正在慢慢消灭暴风城的北方舰队驻扎在这片海岸上的残馀部队。漂往西方的尸体暗示着这场战斗是多么的残酷。$B$B这并不妨碍我优雅的审美趣味，但却说明我们正处在危险之中。$B$B在巫妖王的领地上，死者随时可能重新站起来攻击我们。带上这根火把——你要进行净化仪式，让逝者安息。', '复仇港的高级执行官安希尔姆要求你到镇子的西边去，使用净化之炬净化10具尸体。', '我很高兴你证明了你是听从命令的人。如果我从每个身穿闪亮护甲来到这里，自以为高于指挥体系的笨蛋手中都收取一枚铜币…我看我大概已经攒了好几枚金币了。$B$B既然你已经证明你是个遵守纪律的人，我还有其它任务，更符合像你这种程度的对象。', '我不在意之前你杀过多少的巨人，龙或是狗头人。去完成这份工作，并在完成后回来这里。', '', '去嚎风峡湾找复仇港的高级执行官安希尔姆。', '净化尸体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11271, '物资储备', '斑点角鹰兽的羽毛用途广泛，在我们的日常生活中扮演着重要的角色，从制作箭羽到仪式用的服饰都用得上这种材料。眼下正是收集绒毛的季节，可惜我们很快就要撤离冬蹄营地了，我必须抓紧最后的机会。$B$B这次迁移路途遥远，但是我相信在你的帮助下，我们有能力为所有人员配备足够的物资。局势越来越严峻了，危机随时可能降临。$B$B你可以在营地附近的地面上找到那些羽毛。', '冬蹄营地的安霍塔·白霜要你去收集10根斑点角鹰兽的羽毛。', '因为你的贡献，我们得以作好旅行的准备。我没什么东西可以答谢你，不过你可以从我多出来的战斗装备中选一件拿走。', '你有收集到任何羽绒吗?', '', '去嚎风峡湾找冬蹄营地的安霍塔·白霜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11272, '旗开得胜', '这个精灵王子真以为他可以自由进出我的镇子，侮辱我的女王，屠戮我的手下？他真以为当乌特加德的部队在全力筹备总攻的时候，我们会袖手旁观？$B$B让我们来证明他大错特错了。$B$B你立刻转至乌特加德，记住，要从正门进去，当着那群维库猩猩的面把他干掉。我要让阿尔萨斯知道，我们来了，我们要跟他玩到底。', '高级执行官安希尔姆要求你进入乌特加德城堡，杀死凯雷塞斯王子。', '复仇的感觉真好。尽管把这当作是真正复仇的开胃菜吧。$B$B阿尔萨斯将很快得到报应。只有这样我才能死而无憾。', '很开心又看到你了，$N。除非你还没杀了那个精灵混蛋，如果我是你，在这样的情况下我就会赶紧出发了。', '', '去嚎风峡湾找复仇港的高级执行官安希尔姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11275, '制作号角', '我的族人世代以狩猎雪人为业，今年将是我首次参加狩猎活动。这很可能是我们撤离哨站前的最后一次狩猎了。$B$B营地附近的雪地上游荡着许多山羊，我必须利用它们的犄角制作一只声音宏亮的号角才能去狩猎。听长者们说，号角能模拟出雌性雪人发情时的叫声，其实我挺怀疑这个说法的。$B$B$N，帮我取回一批完好无损的犄角吧，我会从中挑选一只来制作号角。', '冬蹄营地的诺库玛·雪眼要你将6只完整的羊角交给她。', '这些角的品质优良，$N。让我来检验一下它们，并从中挑选一个给我用来打猎。$B$B我会将剩下的交给工匠，让他们用在雕刻上。', '你带着合适的角来了吗?', '', '去嚎风峡湾找冬蹄营地的诺库玛·雪眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11277, '堕落的深渊', '他们把戴加恩关在那边的斗技场旁边的一只笼子里。我还知道，那群掠龙部族的混帐会把他们的囚犯扔给最强的角斗士虐杀，更糟糕是，他们还会把失败者的尸体丢进下面的地穴里，让里面的天灾军团通灵师给变成食尸鬼！太可怕了！太恐怖了！$B$B但最最重要的是，石板被他们弄得到处都是，全散落在这个大地洞里了。你要是想当英雄，还是先把石板都先收集起来吧。', '乌特加德墓穴的格罗菲尔德要你收集10块龙颅石板。', '你干得很好，伙伴。现在我们已经弄到了石板，我们可以去试着救出迪刚恩，并找到密码，帮我们解开隐藏在这些古老神器背后的意义!$B$B我拿好这些石板，你去救迪刚恩。', '检查所有角落与缝隙!', '', '去嚎风峡湾找乌特加德墓穴的格罗菲尔德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11278, '返回瓦加德', '在发掘这些圣物的时候损失了两位最好的队员，这真是个耻辱。为了保存这些史料的安全，他们甚至付出生命的代价，太悲哀了……$B$B<格罗菲尔德将密码表与石板小心地包裹在了一块布中。>$B$B把这些带回瓦加德。接下来的事情交给米科索夫就可以了，他会知道该怎么做的。$B$B我？我不会有问题的。你就放心离开吧！', '将格罗菲尔德的包裹交给瓦加德港口的贝尔塔德·米科索夫。', '要把这些石板分类可能需要一点时间。而我先前的所有研究都说明了这里原本住着人类的祖先。那些维库人可能把他们全杀了。不管如何，等我把这些古物架设起来，我就会知道得更多。', '你回来了!', '', '去找嚎风峡湾的贝尔塔德·米科索夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11279, '绿色的龙卵和龙崽', '我们正在研究一种新型药剂，我觉得应该扩大物种研究范围。$B$B就拿始祖龙来做实验怎么样？！$B$B喏，我身上恰好有一瓶多馀的试剂，而你看上去又很靠谱，事情怎么这么巧啊。$B$B转至西北方的灰烬龙巢，将试剂洒在龙卵上，然后取回感染了试剂的始祖龙崽样本。', '将10份被感染的始祖龙崽样本交给新阿加曼德的药剂师提灵哈斯特。', '什么?!不，不可能。$B$B该死!$B$B这一批瘟疫除了将元龙变绿之外，对他们似乎没有任何实际效果!$B$B在所有接触到的生物身上使用这股瘟疫的梦想似乎又化为乌有了!', '没有那些样本，我要如何分辨这个最新的瘟疫菌种是不是可以用于其它所有的物种身上呢?', '', '去嚎风峡湾找新阿加曼德的药剂师提灵哈斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11280, '龙的胃病', '等等，我想到一个问题！会不会是因为试剂只喷在蛋壳上的缘故才没有击败幼龙呢？$B$B$N，我明白了！喏，我这里恰好有些特殊肉块。带上它转至灰烬龙巢喂食始祖龙崽！$B$B等等，再让我想想。应该找更大一点的，比如始祖幼龙。$B$B对！$B$B你就待在附近观察它进食后的情况。当然了，它可能会攻击你，这就是研究工作的代价嘛。', '新阿加曼德的药剂师提灵哈斯特要你利用提灵哈斯特的特殊肉块吸引一头始祖幼龙，并观察它进食后的反应。', '不~~~~~~~~~!!$B$B<瘟疫使者哭了出来。>$B$B我全部的希望…我所有的梦想，都毁了!$B$B走开，$N。让我自己一个人绝望吧。我一无是处。$B$B拿去，你可以拿走我这辈子所有的财产。等其它的药剂师听到我的失败时，我会被处理掉，再也用不上它们了。', '好啦，拿出来!我们的小实验有用吗?$B$B元龙喜欢它的点心吗?它有从体内开始溶解吗?', '', '去嚎风峡湾找新阿加曼德的药剂师提灵哈斯特。', '观察始祖幼龙吞食特殊肉块后的情况', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11281, '模仿叫声', '我在犄角上绘制了草案，但是在雕刻之前我得搞清楚它能不能正常发声。听安霍塔讲，他去了哨站东北方的瀑布测试号角。氏族的猎人世代利用寒冰瀑布的音效来测试狩猎用的号角。我真是迫不及待地想要对此有更多了解！$B$B你能帮我测试这只号角吗？如果它能正常发声的话，很可能会引来雪人，所以你最好做好战斗的准备！测试完毕后把号角带回来给我。', '测试雕刻过的号角，然后返回冬蹄营地向诺库玛·雪眼汇报测试结果。', '<诺可玛听取你的测试报告。>$B$B我很欣慰号角作用的还不错…也许效果太好了，如果你说的都是事实的话。你确定那只野兽开口说话了?如果这是真的，我不知道我是否可以继续这场猎杀。我得跟灰烬图腾酋长谈谈。$B$B这只号角也许最后只能用来装饰，但是那并不会抹杀它本身的价值。谢谢你提供的所有帮助，$N。', '你有机会测试号角吗?', '', '去嚎风峡湾找冬蹄营地的诺库玛·雪眼。', '测试诺库玛的号角', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11282, '领略恐惧', '等你像戈斯一样身经百战之后，你就会明白，击败敌人的最好方式就是让他们对死亡产生恐惧！$B$B但那些维库人却从来不知道什么是恐惧。你刚杀死一个，马上会冲上来另一个拿着更大号武器的……还呜呀呜呀地发出怪叫。$B$B唯一能让这帮家伙害怕的方法就是杀死他们中最厉害最邪恶的那几个。$B$B越过封锁线，杀死那些维库人，直到他们的英雄露面为止！然后将那三个人干掉，再把女王陛下的旗帜插在他们面前。这样维库人才会害怕！', '戈斯要你杀死放血者伍尔弗、恶毒的奥瑞克和贡纳·索瓦德森，并将被遗忘者旗帜插在他们面前。你需要杀死数名封锁线对面的维库人，直到他们露面。', '杀得好。我看到维库人一见希尔瓦娜斯的旗帜就吓得跌倒。对我们来说可是件好事!', '你杀死那几个维库人了?他们一定很难缠!', '', '去\r\n找嚎风峡湾复仇升降梯附近的戈斯中士。', '将旗帜插在恶毒的奥瑞克的尸体前面', '将旗帜插在放血者伍尔弗的尸体前面', '将旗帜插在贡纳·索瓦德森的尸体前面', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11283, '血战拜尔海姆', '那些维库人源源不断地从西边的镇子里涌来！$B$B戈斯有个法子。你进入那个镇子，杀死那些斯克恩维库人。这样就能阻止他们了！', '戈斯中士要你转至拜尔海姆，杀死16名斯克恩维库人。', '你杀人的技术一定练习了很久，你几乎跟葛司一样厉害!', '你杀够了吗?温特斯考恩的城镇就在对面!', '', '去找嚎风峡湾复仇升降梯附近的戈斯中士。', '拜尔海姆死亡人数', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11284, '隔壁的雪人', '那些哨兵完全不把我当回事，你愿意帮帮我吗？我带领一群矿工在桥对面的矿洞开采矿石，为转至灰熊丘陵的远征军锻造武器。$B$B但是有只大雪人冲进了矿洞，霸占了隧道！我们尝试过高声呵斥，想要吓跑他，可这家伙就是赖着不走，连烟熏的法子都不管用。$B$B你瞧，镇子附近的雪地上生活着许多霜角山羊，或许你可以利用山羊肉诱使大雪人出洞？帮帮忙吧？我们已经被逼得走投无路了！', '维德瓦堡垒的工头科尔贝要你击败裂角。', '你成功了?圣光在上啊，你真是个活生生的奇迹!我正开始想要找个理由向亚当斯队长说明，为什么他手下的武器无法准时完成!', '你顺利地把那只笨雪人移出我的矿坑了吗?', '', '去嚎风峡湾找维德瓦堡垒的工头科尔贝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11285, '拜尔海姆在燃烧！', '光杀死这些维库人还不够。我们应该烧毁他们的房子！嗯……还有桥梁。为了安全起见，还是烧掉整个镇子比较妥当！$B$B带上火把转至西边的拜尔海姆，点燃所有建筑物！狠狠地教训他们。', '戈斯中士要你转至拜尔海姆，使用戈斯的火把烧毁1座斯克恩民房、1座斯克恩了望塔、1座斯克恩桥梁和1座斯克恩兵营。', '我想你已经烧毁所有的东西了。我看到了几处没有起火…但是对葛司来说已经很不错了。', '你把所有的建筑都烧完了吗?确定你没有留下什么没烧掉。', '', '去找嚎风峡湾复仇升降梯附近的戈斯中士。', '烧毁斯克恩民房', '烧毁斯克恩瞭望塔', '烧毁斯克恩桥梁', '烧毁斯克恩兵营');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11286, '钢铁之门的古器', '我肩负着不同寻常的使命，有位老朋友在梦境中指引我来到这里。可我只看见这些小家伙用他们的机器在地面制造大洞，这让我非常生气。$B$B我看出来了，这些矮人在挖掘古器，这里埋藏的古器对我们来说有着重要的历史意义。$B$B我希望你能替我找回它们，别让那些矮人挡住你的去路。', '将10件钢铁之门古器交给嚎风峡湾钢铁之门的先知拉瑞恩·迷雾行者。', '<贤者对于你替他做的事赞许地呼了一口气。>$B$B或许我会尽快找些时间好好研究一下这些神器，了解这些神器所代表的意义。$B$B但是，现在有更要紧的事情要处理。', '你从钢铁之门收集了多少神器?', '', '去嚎风峡湾找钢铁之门的先知拉瑞恩·迷雾行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11288, '闪耀的圣光', '<奄奄一息的阿瑞斯喘着粗气，努力地说着话。>$B$B我是银色北伐军的一名特使，肩负着神圣的使命。$B$B我们的部队在瘟疫之地全军复没。在黎明之光的照耀下，那件神器得到了净化，再次变得纯洁而神圣。为了净化它，许多人不惜献出自己的生命。$B$B机会尚存……我们必须把握最后的时间。$B$B圣剑就在亡者之窟的深处，由残忍的死灵看守着。$B$B<阿瑞斯的身体发出炫目的光芒。>$B$B愿……圣光……保佑……你。', '乌特加德墓穴的誓缚者阿瑞斯要你夺回圣器。$B$B这是一项限时任务。', '你感觉到一股强制之力使你将这把神圣之刃放置在爱力士的身旁。$B$B在放好后，你马上又感受到令人目眩的圣光。', '<爱力士失去意识。>', '', '去嚎风峡湾找乌特加德墓穴的誓缚者阿瑞斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11289, '荣耀的指引', '<阿瑞斯露出了笑容。>$B$B圣光保佑。你成功了！$B$B<阿瑞斯咳嗽起来。>返回瓦加德，将这件圣器交给伊鲁伦·图布雷勋爵吧。$B$B朋友，愿荣耀永远与你同在，永远。$B$B<阿瑞斯死了。>', '将圣器交给瓦加德的伊鲁伦·图布雷勋爵。', '许许多多的人为了收回这柄剑而牺牲。唉，我担心英勇的爱力士不会是最后一个。$B$B但是你替圣光行道，英雄。这把圣洁之剑将会由提里奥.弗丁大人亲自使用。即便是现在，银色北伐军依旧朝着冰冠冰川前进。弗丁大人誓言将亲自摧毁这道诅咒之地的大墙!只要有了这把剑，他就有机会能与巫妖王一搏。$B$B弗丁大人仍是我们最大的希望。', '以圣光之名!', '', '去嚎风峡湾找瓦加德的伊鲁伦·图布雷勋爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11290, '掠龙作战计划', '我们无法获知因格瓦尔的行踪，不过从当前掌握的信息来看，亚尼斯就在龙颅村的座狼圈旁的洞穴中。$B$B你营救回来的士兵们说亚尼斯手中有掠龙作战计划。$B$B我要你返回龙颅村，夺得他们的作战计划。若是维库人阻挠你前进，就将他们统统干掉，亚尼斯也不例外！', '嚎风峡湾瓦加德港口的凯勒中将要你取回掠龙作战计划。', '<海军中将凯勒看了一眼计画的内容。>$B$B太好了!事情看起来，嚎风峡湾中还存在这更多的维库村落，一个不同的维库部族正准备袭击镇西要塞。可恶，就我所知，可能已经太晚了。我已经有几天没有听到镇西一带的消息了。不论如何，我们一定要警告镇西要塞!', '你找到掠龙战斗计画了吗?', '', '去嚎风峡湾找瓦加德的凯勒中将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11291, '转至西部卫戍要塞！', '<凯勒中将把作战计划卷了起来。>$B$B瓦加德港口的局势已在控制中，现在你必须带上作战计划转至位于峡湾西部峭壁的西部卫戍要塞。与飞行管理员助理艾米鲁尔·冬风谈一谈，乘坐她的狮鹫飞往西部卫戍要塞。$B$B抵达目的地后去找亚当斯上尉，他负责处理西部卫戍要塞的所有事宜。将作战计划交给他，看完之后他自然会明白要如何应付。', '将掠龙作战计划交给嚎风峡湾西部卫戍要塞的亚当斯上尉。', '<亚当斯队长从你手中接过计画。>$B$B我很开心你决定过来这里。我的顾问们跟我想必需要花一点时间来研读这些计画。在这一段时间内，我们会尽量利用我们可取得的帮助!', '瓦尔加德没有沦陷?真是意外。$B$B一定是因为你的帮忙。肯定跟凯勒没有关系。', '', '去嚎风峡湾找西部卫戍要塞的亚当斯上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11292, '陷阱中的猎物', '很高兴见到你。我从灰熊丘陵来，想和你们的部队做生意。我们在灰熊丘陵设有一座很大的哨站，朝北走就能遇见，欢迎你去坐一坐哦。$B$B我在附近的森林和雪地中设了许多陷阱，打算用猎物的肉品皮毛之类的东西去跟镇上的居民交换商品。$B$B如果你能帮我带回困在陷阱里的猎物，我就分你一些利润。小心点，你并不是唯一的捕猎者。', '将8份被陷阱捕获的猎物交给维德瓦堡垒的猎户杰森。', '<陷捕者杰桑检视了你带给他的生物。>$B$B做得很好。这些货物中有一些价格可以卖得比较好，不过我应该有足够和本地人交易的数量。', '希望你没有空手而回。我想我们之间有过协定了。', '', '去嚎风峡湾找维德瓦堡垒的猎户杰森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11293, '为麦酒呐喊！', '我们计划在美酒节上推销大麦酒。你得在银行外、军事区、探险者大厅以及秘法区的旗帜下高声叫喊。我自然会为你提供便利，喏，我的赛羊借你用4分钟哦。这根马鞭也给你。你稍微鞭打一下它就行啦，要是你抽得太厉害的话，它就会离开你。', '在银行外、军事区、探险者大厅以及秘法区的旗帜下高声叫喊，宣传美酒节。', '做的好!这样的大肆宣传一定可以增加我们的生意。$B$B这是我们答应你的报酬。麦酒总是信守承诺。$B$B噢，你可以改天再来帮忙宣传麦酒的好名声。', '你完成了啤酒节的宣传了吗?更重要的是，你让大家知道麦酒了吗?', '', '去找丹莫罗的贝坎·麦酒。', '在银行外大喊', '在军事区大喊', '在探险者大厅大喊', '在秘法区大喊');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11294, '为雷酒呐喊！', '现在是推销雷霆啤酒的大好时机。你得在银行外、军事区、探险者大厅以及秘法区的旗帜下高声叫喊。$B$B我自然会为你提供便利，喏，我的赛羊和马鞭借你用4分钟哦。$B$B你稍微鞭打一下它就行啦，铁炉堡中可没有苹果箱，我们绝对不能输给大麦酒的推销员。', '在银行外、军事区、探险者大厅以及秘法区的旗帜下高声叫喊，宣传美酒节。', '做得好!让那些骄傲的麦酒家的人瞧瞧。$B$B这是我们承诺过的酬劳我们雷酒可是很大方的，麦酒那些家伙只是会给虚伪的承诺和假名声。$B$B你要谨慎地选择。$B$B要是你打继续这种正确的选择，你可以改天再来帮忙宣传。', '你让大家知道雷酒将在啤酒节登场吗?', '', '去找丹莫罗的达兰·雷酒。', '在银行外大喊', '在军事区大喊', '在探险者大厅大喊', '在秘法区大喊');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11296, '裂木森林的囚犯', '天灾军团的出现令居住在这里的生物变得焦躁不安。$B$B我们奉命护送先知来到这里，在队伍路过北边的裂木森林时，遭到了裂木寡妇蛛的袭击。这种体型庞大、性格凶残的蜘蛛虏走了许多远行者。$B$B我必须待在这里保护幸存者，你……你能去营救那些被缚在茧中的远行者吗？$B$B陌生人，帮帮忙吧。', '远行者斯图卡·天云要你去营救7名冬蹄远行者，完成任务后钢铁之门向他复命。', '这十分勇敢的行为，$C。我并不知道你的同胞如此的无私。$B$B下一次我会把长老的警告放在心上，避开裂木森林。我也同样地建议你。', '我抱着希望，盼望我的狩猎部队还活着。$B$B寡妇的刺毒并不会立刻致命。它们会让猎物活得够久，好让那些小蜘蛛孵化时可以大快朵颐。', '', '去嚎风峡湾找钢铁之门的远行者斯图卡·天云。', '营救冬蹄远行者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11298, '酒里有什么？', '东南方有一片地区叫作低语峡谷，那里聚集了一群探险者协会的矮人，好吧，这不是重点。重点是，他们都疯了，完全疯了！他们竟然主动攻击我们的补给车队，抢走了所有的物资。$B$B我一直在想弄清楚他们为什么疯成这样！当前来看，我怀疑他们的酒有问题。嗯嗯，我得再仔细研究研究，这样，你去给我偷几桶酒回来。对，趁他们忙着挖来挖去的时候动手就可以了。', '将5只矮人酒桶交给药剂师营地的药剂师玛尔苏斯。', '<药剂师倒了一大杯饮料给自己。>$B$B好吧，我要喝了!', '你拿到那些酒桶了没?', '', '去嚎风峡湾找药剂师营地的药剂师玛尔苏斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11300, '扫平竞技场', '只要你打败他们的那一票角斗士，沃鲁夫就会亲自下场了。这恐怕是拿回密码表的唯一方法。上吧，杀进审判竞技场，杀得他们片甲不留！要是拿回了密码表，你就直接到入口那边去找格罗菲尔德。$B$B我？别管我了！我们马上就要找到人类物种演变过程中遗失的那一环了！', '击败审判竞技场内的所有角斗士，然后挑战残暴的沃鲁夫。击败沃鲁夫并夺回古代密码表。$B$B将古代密码表交给乌特加德墓穴入口处的格罗菲尔德。', '太神奇了!真的有人在审判这些东西?到什么程度?!又有什么目的?$B$B好吧，别在意那些鬼扯了。总有人能解开这些东西。我们拿回了密码和石板 - 而这场灾难只有两个人牺牲。', '迪刚恩?密码?', '', '去嚎风峡湾找乌特加德墓穴的格罗菲尔德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11301, '疯狂的研究', '是不是玛尔苏斯又把你抓过去灌输那些所谓的啤酒桶和疯矮人的奇幻故事啦？$B$B以科学的观点看来，我固然不否认那些矮人确实是疯了，但我深刻质疑偷盗啤酒的正当性及其对科学研究的贡献程度。$B$B科学研究真正需要的是头脑，你明白吗？我们要揭开表面现象看本质，或许……能直接发现某种可用于研究的材料。$B$B拿上这把锯子转至东南方的低语峡谷，先把那些疯矮人干掉，然后采集他们的……嗯……样本。', '将12份疯狂探险者的“样本”交给药剂师营地的药剂师葛瑞克。', '这些脑子可真美!实在是太漂亮了!正是我所需要的。$B$B感谢你的帮助，$N。现在我要来揭露马尔萨斯的啤酒眼镜也无法看透的真相。', '你拿到了那些脑子吗?如果没有，我要把我的锯子要回来。你最好不要想把锯子给带走。', '', '去嚎风峡湾找药剂师营地的药剂师葛瑞克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11304, '新阿加曼德', '复仇港这里的实验装备恐怕不是最好的。毕竟，这里只是一座小小的军港而已。$B$B我需要你帮我将这份菌株样品交给新阿加曼德的首席药剂师哈瑞斯。沿拜尔海姆外面的路向南走，沿着路走到西边就可以到达那里了。$B$B你必须尽快把样品送过去，$N。我们的敌人每天都在变强，数量上我们也不再有任何优势。所以，我们必须发展出一种真正可靠的武器来应对他们的挑战！', '转至嚎风峡湾西部的新阿加曼德，将雷杉德尔的菌株交给首席药剂师哈瑞斯。', '这个菌种绝对不是没有价值，朋友!那些复仇台地的蠢蛋老早就把答案含在嘴里了!', '嗯，$N?', '', '去嚎风峡湾找新阿加曼德的首席药剂师哈瑞斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11305, '量身订制', '我们已经在一处叫哈尔格林德的维库人村落里连续散布了好几周的药剂了，但还是出了一些问题。$B$B$N，从当前的试验结果来看，几乎所有物种都会受到药剂影响，但由于环境变化，难免会携带不少杂质。因此我们需要配制出能对维库人生效的新的配方。$B$B在我们攻陷哈尔格林德时，维库人酋长逃出了村子。你可以在西边找到他。作为掠龙氏族的首领，他的样本非常理想。', '转至托尔瓦德的营地，从托尔瓦德身上取得掠龙族长的样本，将它交给新阿加曼德的首席药剂师哈瑞斯。', '这就成了，轮到正牌药剂师的工作登场啦，$N!', '你拿到我需要的样本了吗，$N?', '', '去嚎风峡湾找新阿加曼德的首席药剂师哈瑞斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11306, '加热搅拌', '到当前为止，你做得都很不错，$N。接下来我要教给你一些更深入的技术和知识，帮助你更好地了解你的任务。$B$B拿着这只空瓶子，到我左边的坩埚里去盛一些液体来，然后把它和我右边的那些药剂样本混合起来，仔细调配比例，直到你获得了一种完美均衡的混合溶液为止。', '在大锅旁装满药剂师的空瓶，然后在其中混入哈瑞斯的药剂样本，最终调制出一瓶均衡的溶液。$B$B完成调制任务后向首席药剂师哈瑞斯复命。', '太好了!你真是个机敏的学生，$N。$B$B有趣的部份来了，部属它们!', '你的实验进行的如何，$N?如果你有任何包含科学的问题的话，让我知道!', '', '去嚎风峡湾找新阿加曼德的首席药剂师哈瑞斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11309, '重要零件', '你的意思是说，哈瑞斯想要把那里弄“干净”，是吗？\r\n啊，行，我能帮上忙。$B$B不过，你先得给我去弄点零件回来。我可不想在这种随时会爆炸的东西上浪费我宝贵的优质零件。$B$B首先，我需要一些铲齿鹿筋……高强度高韧性，非常好用。$B$B哦，我还需要一磅肉，有个叫安东的旅行商卖便宜的肉，他一直在西边那条路上沿街叫卖。', '新阿加曼德的“钢锯”杰妮要求你收集6条铲齿鹿筋，再从旅行商安东那里购买一磅鲜肉，然后把这些东西带回去交给她。', '太棒了!没错，没错，这些正好!', '你收集到我要的材料没有?', '', '去嚎风峡湾找新阿加曼德的“钢锯”杰妮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11310, '集中处理', '完成了，给你！我们的这个新朋友可能会有点……怎么说呢，不稳定。所以我建议你在抵达哈尔格林德前不要把它放出来。$B$B一旦你抵达那里，用这只憎恶在维库人最多的地方“转一圈”，然后直接自爆，就行了，轻松愉快。$B$B之后，你要记得把所有剩下来的“零件”给我带回来，没准还能有别的用处呢！', '在哈尔格林德内使用憎恶装配包，然后使用无脑的憎恶消灭感染的维库人。至少打倒20个维库人以后回去向新阿加曼德的“钢锯”杰妮复命。', '$N，干得好。总之，你总不会想要要求…永久保固，对吧?我相信可以在这些尸块中找到能用的!', '你清理干净霍葛莱了吗?', '', '去嚎风峡湾找新阿加曼德的“钢锯”杰妮。', '消灭被感染的维库人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11311, '压制元素生物', '要在这样恶劣的环境下生存，就必须像我们一样敢于接受自然的挑战。北部雪山中元素生物的数量急速增长，稍微放松警惕的话，它们就能要了你的命。$B$B在撤离营地之前，我们计划再次缩减它们的势力范围，就算是为自然界的平衡尽最后一份心力吧。你也瞧见啦，这次迁移还有许多准备工作没有做，你能不能帮帮我们呢？$B$B我要你杀死营地附近雪山中的咆哮的旋风或是碎冰元素。', '冬蹄营地的驯风者卡根要你杀死附近雪山中的8个元素生物，咆哮的旋风或是碎冰元素都可以。', '元素精灵的影响力开始退去，但它们还是会回来。但我们已经争取了足够的时间，完成我们在此地的任务并且离开。', '你削减了那些元素吗?', '', '去嚎风峡湾找冬蹄营地的驯风者卡根。', '杀死雪山中的元素生物', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11313, '冰之精魂', '原本，环绕在这片林地周围的冰元素都是我们最忠实的伙伴，可是现在，一股暴烈与毁灭的力量横扫了整片大地，竟将它们变成了敌人！$B$B我与姐妹们最痛苦的经历也不过如此了。为了抓住最后一丝希望，我们甚至放弃了从不与外界接触的律令，寻求你的帮助。只有你才能帮助我们抵抗这腐蚀着林地、并毒害着姐妹们的枯萎与凋零！$B$B我们已经从那些冰元素的尸体上收集了一些核心，而且一直妥善地保存着。或许依靠这些核心，我们可以让它们复生！你也愿意帮忙收集吗？', '冰雪林地的鲁莉尔蕾要求你为她带回15块冰冷核心。', '<露丽儿静静的从你那儿收下了核心。>$B$B谢谢你，$N。<露丽儿哀伤的望着这些核心。>$B$B我保证，吾友，我会尽一切努力让你复原的。', '你拿到任何的核心了吗?', '', '去嚎风峡湾找冰雪林地的鲁莉尔蕾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11314, '堕落的姐妹', '西南边有一片林地，过去它与这里几乎一模一样。然而，神秘的力量与诡秘的魔法在不久之前把那里彻底改变了。现在，那片林地已经摆脱了正常气候的制御，变得不再寒冷，而生活在那里的姐妹们，也被这种改变逼入了疯狂的深渊。$B$B甚至当我们尝试去接近她们的时候，还被她们攻击了！恐怕她们当中大多数都已经无法挽救了，但我不能放弃希望！$B$B带上我的坠饰，转至西南方的活力之林，试试使用它拯救我的姐妹们。', '冰雪林地的鲁莉尔蕾要你对7只冰冷树妖使用她的坠饰。', '所以我的姊妹们还有希望?$B$B<露丽儿的目光从你身上离开，望向了地面。>$B$B没有早点想到使用坠饰让我充满了罪恶感。我们得救出更多的姊妹们。', '你有办法用我的坠饰治疗姊妹们吗?', '', '去嚎风峡湾找冰雪林地的鲁莉尔蕾。', '解救冰冷树妖', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11315, '野蛮之藤', '西南方活力之林内的姐妹们过去一直很喜欢那些缤纷绚丽而又卓然天成的血色常青藤，甚至一直把那些藤条当作床。然而，那种将她们逼疯的神秘力量同样也改变了这些可怜的植物。$B$B现在，这些原本温和的植物疯狂生长了起来。它们的茎变成了鞭子一般的荆棘，随时都会将任何试图接近的人紧紧地缠绕起来，并无情地绞杀。因此，在夺回林地之前，我们必须先驯服这些植物，或者……把它们全部连根铲除！$B$B去吧，尽你的全力清理这些植物。它们已经完全失去了大自然的控制。', '冰雪林地的鲁莉尔蕾要求你杀死8只血色常青藤。', '$N，感谢你的帮忙，鲜亮林地曾经是个美丽的地方，当我们返回那里以后，我们会使它再次变美的。', '你从鲜亮林地回来了吗?', '', '去嚎风峡湾找冰雪林地的鲁莉尔蕾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11316, '扭曲之林', '在这里的西边，也有一处林地被神秘的魔法力量变成了极为可怕的地方。现在，我们称那里为扭曲之林。那里的树林中，岩石后，池塘里，突然多出了无数凶猛可怖的野兽。$B$B我不知道这些野兽是从哪里来的，也不知道究竟是什么力量在操纵着它们，但我知道，我们必须要消灭它们！$B$B如果继续让它们统治那片林地，那里一定会被毒化得无法挽回。清除那些生物，为我的姐妹们复仇！', '冰雪林地的鲁莉尔蕾要求你杀死10只棘藤爬行者。', '你做得很好，$N。如果我们在土地初变化时就遇到像你这样的盟友的话，或许我们还有办法保留一些已经失去的部份。', '你有亲眼看到扭曲林地的惨状吗?', '', '去嚎风峡湾找冰雪林地的鲁莉尔蕾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11317, '净化', '我们敢于进入裂木森林都是因为我那杂乱无章的梦。最近我总是在做噩梦，内容都是关于我的座狼朋友——乌尔芬。他在寻求帮助，你必须赶快去帮助他。$B$B不过你既不懂得座狼的语言，也无法安全地在座狼群中穿行。别担心，我有个法子。$B$B首先，你必须通过冥想来净化你的灵魂。$B$B在冬蹄营地东北方的霜刃峰顶有一座神龛，沿着西边山脚的道路往上走就到了。$B$B在那里进行冥想，然后回到我这里来。', '钢铁之门的先知拉瑞恩·迷雾行者建议你转至霜刃神龛，通过冥想净化你内心的杂念。', '我可以感受到你的变化。$B$B你准备好进行下一步了吗?', '你在圣坛找到了内在平静吗?你的骚动消除了吗?', '', '去嚎风峡湾找钢铁之门的先知拉瑞恩·迷雾行者。', '清除你内心的杂念', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11318, '赛羊会前的热身', '你想要参加赛羊会？希望你已经准备好体验速度的刺激了。但是在你四处撒野之前，你得证明自己能够驾驭这些彪悍的坐骑。$B$B那么，我会借你一根特殊的马鞭和一头赛羊。你需要证明自己的驾驭能力。$B$B让赛羊保持快走、慢跑和疾跑状况各8秒。关于如何驱使赛羊，你可以询问我的学徒波尔·冻石。', '你有4分钟时间驾驭赛羊，让它保持三种不同的速度各8秒。', '干得漂亮!要学会怎么操控你的山羊得花上不少时间。当你一旦做到，你就会希望每只山羊都是竞速山羊。$B$B你说什么?“我的报酬在哪里?”哈哈哈…你得试试最快的山羊!你想要更多?那这样如何…$B$B你赢得了替啤酒节服务的权力，那边有许路复用作可做，有许多的报酬。尤其是对一个年轻急躁的山羊赛手。', '你能够掌控速度吗?', '', '去找丹莫罗的尼尔·拉姆斯登。', '维持快走状态8秒', '维持慢跑状态8秒', '维持疾跑状态8秒', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11319, '暗魂守护者的种子', '西北边有一处现在被称为扭曲之林的地方，过去它曾是一群丛林守护者的家园。那时候，他们和姐妹们一起维护着附近林地的和平与安宁。$B$B然而，当林地被魔法力量改变时，那里的姐妹们都死去了，可不知为什么，这些守护者却存活了下来，并沦为了邪恶力量的奴仆，转而在林地里播撒着剧毒植物的种子。这些种子具有强烈的侵占性，甚至会剥夺其它健康植物的生命力，令它们完全无法生存。$B$B我会给你一颗冰元素的冰冷核心，当你摧毁了一颗孢子之后，你必须用冰冷核心将其冻住，阻止它再生。', '冰雪林地的鲁莉尔蕾要求你冻结8个孢子。', '冰结之核很有用罗?我得记下来。我很确定看守者不会因为我们破坏了他们的心血一次就停手。', '这个扭曲的林地是个可怕的地方。我从没想过我们的家会变成这么恶心的东西。', '', '去嚎风峡湾找冰雪林地的鲁莉尔蕾。', '冻结孢子', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11321, '刚才有人说“纪念品”？', '美酒节除了赛羊会外，还有一项传统，那就是饮酒狂欢！如果你有时间的话，就将这张礼品券交给贝尔比吧。她就在美酒节营地的后面。要是你看不见她，没关系，她一定会看见你的。$B$B无论如何，将礼品券交给她，你就能免费领到一只美酒节酒杯。她还出售各种美酒哦。', '在美酒节营地的贝尔比处兑换礼品券。', '噢，只是张酒杯兑换券…说不定你还花了一番力气才弄来。好吧，这是你今年的酒杯。$B$B不过我猜我应该还会常常再看到你。无论如何，要是想兑换啤酒节奖卷，你找我就对了…$B$B或他找我…$B$B噢噢喔…或是他…', '怎么啦宝贝?有东西要给我?', '', '去找丹\r\n莫罗的贝尔比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11322, '净化', '最近我一直在做噩梦，梦中频频出现一头名叫乌尔芬的座狼。他需要帮助，你必须找到他。$B$B不过你既不懂得座狼的语言，也无法安全地在座狼群中穿行。别担心，我有个法子。$B$B首先，你必须通过冥想来净化你的灵魂。$B$B遥远的东北方有一座霜刃峰，在那座山峰的顶端有一处神龛，沿着西边山脚的道路往上走就到了。$B$B在那里进行冥想，然后回到我这里来。', '钢铁之门的观察者莉莎·月叶建议你转至霜刃神龛，通过冥想净化你内心的杂念。', '我可以感受到你的变化。$B$B你准备好进行下一步了吗?', '你在圣坛找到了内在平静吗?你的骚动消除了吗?', '', '去嚎风峡湾找钢铁之门的观察者莉莎·月叶。', '清除你内心的杂念', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11324, '头狼', '既然你夺得了塔隆斯里克的眼珠，那你一定也能看见迦瓦尔并咬断他的喉咙！$B$B$R，去裂木森林的西部杀死迦瓦尔吧，你杀掉他以后，就回去告诉迷雾行者，我又一次成为头狼了！', '乌尔芬要你去杀死迦瓦尔。然后返回钢铁之门，将座狼伪装还给先知拉瑞恩·迷雾行者。', '贾尔沃绝对不是座狼!我很了解这些生物…他们是狼人。$B$B不过，巫牙说它是从灰熊丘陵南下而来的?怪了，那儿可没有什么狼人才对。$B$B我非常感谢你帮助巫牙重返它在狼群中的地位。终于，我们能高枕无忧了。$B$B感激不尽，请你一定要收下这份谢礼。', '$N，你回来了。有巫牙的消息吗?', '', '去嚎风峡湾找钢铁之门的先知拉瑞恩·迷雾行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11326, '头狼', '既然你夺得了塔隆斯里克的眼珠，那你一定也能看见迦瓦尔并咬断他的喉咙！$B$B$R，去裂木森林的西部杀死迦瓦尔吧，你杀掉他以后，就回去告诉月叶，我又一次成为头狼了！', '乌尔芬要你去杀死迦瓦尔。然后返回钢铁之门，将座狼伪装还给观察者莉莎·月叶。', '贾尔沃绝对不是座狼!根据你的形容，听起来更像是狼人!$B$B不过，巫牙说他是从南方的灰熊丘陵过来的?奇怪了，那边可没有什么狼人才对。$B$B我非常感谢你帮助巫牙重返它在狼群中的地位。终于，我等能高枕无忧了。$B$B感激不尽，请你一定要收下这份谢礼。', '$N，你回来了。有巫牙的消息吗?', '', '去嚎风峡湾找钢铁之门的观察者莉莎·月叶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11327, '任务：夺回包裹', '该死的，我们需要一些治疗瘟疫的物品。$B$B我想起来了！$B$B你去摧毁那些容器的时候，我正好看见一个从新阿加曼德来的药剂商人被维库人拖到哈尔格林德里面去了，就在那边。可怜的家伙。$B$B$N，我需要那个药剂商人的货物。你能到哈尔格林德去把他的包裹找回来吗？', '斥候诺勒斯要你转至哈尔格林德，夺回药剂师的包裹。然后返回灰烬长矛塔楼向他复命。', '天啊…这是什么鬼?!看看这些东西!$B$B我们要立刻把这东西送回要塞，刻不容缓!', '那个地方看起真像是个噩梦。不管是不是维库人，没有人应该要沦为皇家药剂师学会的受害者。$B$B幸好我平安地站在这里。你拿到包裹了吗?', '', '去嚎风峡湾找灰烬长矛塔楼的斥候诺勒斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11328, '任务：被遗忘者的情报', '好吧，我想你得回要塞去，把这个东西交给贝比·鲁诺兹。她只能算是个业馀炼金师，但她也是我们这儿唯一懂炼金术的人了。$B$B关于贝比……她就喜欢喝两杯。所以你应该能在旅店找到她，而且多半喝得昏天黑地。$B$B我想她应该知道怎么办。', '斥候诺勒斯要你将药剂师的包裹送往西部卫戍要塞，交给贝比·鲁诺兹。', '喔…唉，这可不一样!$B$B好吧，让我瞧瞧这东西。我最喜欢用炼金术敲敲补补了!$B$B很有趣，很有趣…喏，我想我知道要做什么了。这个混一点进去，然后再加一点那个。$B$B你知道吗，我猜加一点酒进去也会有点效果吧…嗝!', '呀，你想要啥…嗝?', '', '去嚎风峡湾找西部卫戍要塞的贝比·鲁诺兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11329, '想尽办法！', '见鬼，我这辈子再也不想看见咸鱼了！每天我不停在这里往一个又一个的桶里塞上一条又一条的鱼，好不容易钓够了塞满一桶，抬头一看居然还有几百个桶在等着塞！$B$B钓鱼又不容易……要是没把纳特·帕格卖我的高级鱼饵用完就好了。那鱼饵效果之好有如魔法一般！算了，不扯了，继续钓鱼……希望一小时之内至少能钓上来一只。$B$B我听说北方鲇鱼可以做成非常不错的鱼饵，但……要潜进又冰又冷的湖水在那些浓密的水草间游来游去地捉它们，这未免太疯狂了。我是肯定不会去的，但……你或许……好吧，只是或许……会去的。', '维德瓦堡垒的克里斯托弗·斯洛安要求你给他带回5条北方鲇鱼。', '哇，这些鱼真的是丑得可以，但是如果真的有用，我想我不会介意的。等到远征队走了以后我才能松一口气，回到原先只需要为了晚餐钓鱼的时刻。', '看来你安然无恙，拿到鱼饵了吗?', '', '去嚎风峡湾找维德瓦堡垒的克里斯托弗·斯洛安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11332, '任务：瘟疫罐！', '皇家药剂师协会正在研究一种新瘟疫，准备把我们全撂倒？！$B$B我不能让这种事发生！$B$B到院子里去跟格雷尔·岩锤谈一谈。他会给你一头狮鹫和一些炸弹，我希望你能去把新阿加曼德的瘟疫罐炸个粉碎！', '亚当斯上尉命令你转至新阿加曼德，对瘟疫罐投下5颗炸弹。完成任务后返回西部卫戍要塞向他复命。', '干得好，$N，漂亮!$B$B<队长看起来非常兴奋而高兴。>$B$B这样可以让那些没用的被遗忘者少来惹我们!$B$B我认为你为自己赚了金库中的一些东西!!', '瘟疫槽毁掉了吗?新的瘟疫就像死亡的阴影一样笼罩在我们的头上，$C!', '', '去嚎风峡湾找西部卫戍要塞的亚当斯上尉。', '轰炸瘟疫罐', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11333, '进入灵魂世界', '虽然探险者协会能够从他们的考古发现中推测出一些零碎的古代信息，中将或许能通过强大的力量抽取一些现在的信息，但唯有灵魂可以知晓全部的真相。$B$B我可以通过一些特殊的材料进入灵魂的世界。那里揭示了诺森德的过去、现在和未来。$B$B如果你想了解详细的情况，我就要用到我的材料包了。不过我把它落在了一条船上，现在这条船就沉在东面的匕鞘湾底下。', '瓦加德的智者索拉留斯要你找回他的材料包。', '虽然因为泡水而受损了一些，但应该还能用。$B$B<索拉利亚思把手伸入袋子里，掏出了一些奇怪外型的根。>$B$B现在把它们丢进火里，然后吸入那些气体!$B$B<索拉利亚思把根丢进燃烧的熏香炉中。>$B$B<索拉利亚思深吸了一口气。他的身体也随之颤抖起来。>$B$B什…什么…这不可能…我不能……', '你找到了我的试剂袋吗?', '', '去嚎风峡湾找瓦加德的智者索拉留斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11335, '战斗的召唤：阿拉希盆地', '事实上，我们在多线作战，$g小子:小姑娘;，而且我们不能把军队部署得太过分布，否则我们可能会全盘皆输！$b$b我们需要以天为单位来部署最关键的部队，今天，阿拉希盆地的战斗最需要勇敢的士兵！$b$b带着胜利的消息回来吧，$n。我们不允许部落狗来威胁属于我们的资源！', '在阿拉希盆地战场中获得一场胜利，然后向任意联盟主城、冬拥湖、达拉然或沙塔斯城中的联盟准将复命。', '好消息，$C!如果我们的战术持续运作成功，那么部落要不了多久就得全面撤退了。', '告诉我，$N。你从前线带来了什么消息?', '在阿拉希盆地获胜', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11336, '战斗的召唤：奥特兰克山谷', '事实上，我们在多线作战，$g小子:小姑娘;，而且我们不能把军队部署得太过分布，否则我们可能会全盘皆输！$b$b我们需要以天为单位来部署最关键的部队，今天，奥特兰克山谷的战斗最需要勇敢的士兵们！$b$b现在就出发吧，$N，去帮助雷矛远征军。我们不能就这么看着霜狼氏族逃脱他们应受的惩罚。', '在奥特兰克山谷战场中获得一场胜利，然后向任意联盟主城、冬拥湖、达拉然或沙塔斯城中的联盟准将复命。', '正是我想听到的!在奥特兰克山谷的胜利 - 既使只是暂时的 - 也对我们对抗部落的战略非常重要。', '告诉我，$N。你从前线带来了什么消息?', '在奥特兰克山谷获胜', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11337, '战斗的召唤：风暴之眼', '与部落的战斗永远都不会结束，$N。即使在外域，领土的争夺和往日的仇恨也足够引起新的战争。$B$B进入风暴之眼吧，相信联盟在外域也会像在艾泽拉斯那样所向披靡。', '在风暴之眼战场中获得一场胜利，然后向任意联盟主城、冬拥湖、达拉然或沙塔斯城中的联盟准将复命。', '我们只差一步就可以完全战胜部落了。我们不能让敌人占领这个世界或其它地方的任何据点。', '告诉我，$N。你从前线带来了什么消息?', '在风暴之眼获胜', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11338, '战斗的召唤：战歌峡谷', '银翼哨兵通过战斗来保护战歌峡谷的森林。我们帮助他们，并不是因为我们爱好树木，而是因为森林为联盟领地提供了天然的屏障。$B$B今天他们那里的情势非常危急，远远超过以往任何时候。我们必须立刻派出援军，除非我们希望看到灰谷成为贫瘠之地的附属地！', '在战歌峡谷战场中获得一场胜利，然后向任意联盟主城、冬拥湖、达拉然或沙塔斯城中的联盟准将复命。', '干得漂亮，$N。我们不惜任何代价也要维持疆界的完整!', '你从前线带来了什么消息，$N?', '在战歌峡谷获胜', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11339, '战斗的召唤：阿拉希盆地', '阿拉希盆地快要让联盟夺走了，我们必须尽快派出援兵，否则我们所做的一切都将成为徒劳。$B$B不要拖延了，$c。去阿拉希盆地消灭敌人，胜利属于部落！', '在阿拉希盆地战场中获得一场胜利，然后向任意部落主城、冬拥湖、达拉然或沙塔斯城中的部落战争使者复命。', '你为部落带来了莫大的荣耀，$N。你今日的胜利将可确保明日无数的胜利!', '你回来了。你带来了胜利的消息吗?', '在阿拉希盆地获胜', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11340, '战斗的召唤：奥特兰克山谷', '我们就快要把雷矛入侵者从奥特兰克山谷赶走了，因此我们必须调动一切可能的增援力量来帮助霜狼氏族。$B$B一场决定性的胜利可以让我们腾出足够的资源在其它战场上消灭联盟的那些混蛋。$B$B出发吧，$N。听从霜狼氏族的号令，去赢得无上的荣耀吧！', '在奥特兰克山谷战场中获得一场胜利，然后向任意部落主城、冬拥湖、达拉然或沙塔斯城中的部落战争使者复命。', '再也没有比将入侵者从部落领土中驱逐更大的荣耀了。我们对你今日所援助我们军队的莫大勇气致敬。', '你回来了!你带来了胜利的消息吗?', '在奥特兰克山谷获胜', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11341, '战斗的召唤：风暴之眼', '无论在哪里，只要找到敌人，我们就要和他们战斗到底，并消灭他们。艾泽拉斯或者外域，这两者没有任何区别。$B$B我们不能让联盟在风暴之眼取得优势，今天就去跟他们战斗吧……明天也许就太晚了！', '在风暴之眼战场中获得一场胜利，然后向任意部落主城、冬拥湖、达拉然或沙塔斯城中的部落战争使者复命。', '你将荣耀带给了我们大家，$N。我们一定会让敌人知道无论我们在何处发现他们都将会战斗到底。', '你回来了!你带来了胜利的消息吗?', '在风暴之眼获胜', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11342, '战斗的召唤：战歌峡谷', '联盟真是个阴险的敌人，$N。他们张口闭口说在保护灰谷的森林，以此证明他们对我们贫瘠之地领土的进攻行动是正当的。$B$B今天，我们有机会把敌人彻底赶出部落的领土。去战歌峡谷，夺回一切本属于我们的东西！', '在战歌峡谷战场中获得一场胜利，然后向任意部落主城、冬拥湖、达拉然或沙塔斯城中的部落战争使者复命。', '部落欠你一次人情，$N。你让你的族人以你勇敢防卫我们的大陆为荣。', '你回来了!你带来了胜利的消息吗?', '在战歌峡谷获胜', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11343, '伊米隆的回响', '灵魂世界已经被巫妖王控制了。噩梦凝结成的恐怖生物看守着元素的世界。我感到这些瓦格里维库人在守护着一个可怕的秘密。$B$B我已经老了，虚弱得无法再进去一次了。你必须代我去一次，$N。$B$B带着这只香料炉转至龙颅村，使用它进入灵魂的世界。你要搜索龙颅村东北角的那座最大的建筑物！记得躲开那些瓦格里维库人，否则他们会把你永远禁锢在他们的世界里。', '智者索拉留斯要你进入灵魂世界，搜索龙颅村并找出龙颅村的秘密。', '我不明白。你所看到的生物看起来像是攻击瓦尔加德的维库族?', '你发现了什么?', '发现龙颅村的秘密', '去嚎风峡湾找瓦加德的智者索拉留斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11344, '尼弗莱瓦的痛苦', '我们只知道维库人是最近才出现在诺森德的。那为什么我们会在一万五千年前的影像里看到维库人？如果维库人之前就在诺森德生活，我们怎么会不知道呢？$B$B你必须立刻转至尼弗莱瓦。你要取道东北，穿过龙颅村，越过水坝。尼弗莱瓦就位于海湾的悬崖之上。$B$B你到达尼弗莱瓦以后，要使用焚香炉寻找那里的线索。', '智者索拉留斯要你进入灵魂世界，搜索尼弗莱瓦并找出尼弗莱瓦的秘密。', '维库人生下的人类小孩?而依米伦下令杀死所有的人类后裔?$B$B<索拉利亚思沉默了一会儿。>$B$B虽然我很想否认在我眼前的事实，但我办不到。人类的血脉并不像是探险者协会所说的那样『消失的血缘连结』。那些维库人就是『消失的血缘连结』。他们就是人类的祖先。', '你发现了什么?', '发现尼弗莱瓦的秘密', '去嚎风峡湾找瓦加德的智者索拉留斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11346, '符文之书', '铁矮人侵占了东南方那片广阔的岩地——巨人平原。据侦察兵汇报，矮人们哄骗石巨人从地下显身，然后在他们身上雕刻符文。$B$B我猜不透铁矮人的动机，不过我怀疑他们企图将石巨人转化成武器。铁符文唤石者和铁符文束缚者随身携带的秘典中必定有关于石巨人符文的资料。$B$B$N，从他们手中夺得秘典的书页，拼凑成完整的书籍交给我。', '维德瓦堡垒的勘测员贝瓦尔要你将符文之书交给他。', '<勘察员贝尔瓦翻阅着符文之书。>$B$B嗯嗯…内容实在太多了。我需要一点时间来阅读，而且如果我们想要了解这些符文的话，我们就需要亲自制作看看。', '你把书带回来了吗?', '', '去嚎风峡湾找维德瓦堡垒的勘测员贝瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11348, '命令符文', '我在这块石板上刻了几行符文，你能感受到它们所散发的能量吗？和铁矮人使用的符文相比，这些符文较为低等。但是我们依然可以利用它们粉碎铁矮人的阴谋。$B$B带上符文转至巨人平原，对一个尚未被改造的石巨人使用符文。$B$B在符文的作用下，石巨人会听从你的指挥并逐渐恢复原有的力量。接下来，你要在他的帮助下击败缚石者穆迪斯，这家伙就是盘踞在巨人平原的铁矮人领袖。', '维德瓦堡垒的勘测员贝瓦尔要你去测试命令符文，并击败缚石者穆迪斯。', '你能击败束缚者穆迪斯真是太好了，但铁矮人不会轻易放弃的。$B$B我们在了解他们如何使用符文上获得了很多进展。或许下一次我们遭遇他们时，我们的知识将会变成优势。', '你测试过符文了吗?', '', '去嚎风峡湾找维德瓦堡垒的勘测员贝瓦尔。', '测试命令符文', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11349, '掌控符文', '我这倒是有锄头、铁锤和凿子什么的，可惜它们不能雕刻符文。铁矮人使用的雕琢工具就不一样啦，他们在铸造工具时向里面灌注了魔法力量。$B$B使用这样的工具进行雕刻，符文就不仅仅是简单的字符了，它们具备了束缚、支配与扭曲的力量。$B$B这些我都了然于心，眼下就缺少雕琢工具进行实践了。转至巨人平原的铁矮人营帐附近寻找工具箱，把它们带回来给我。', '将一套铁符文雕刻工具交给维德瓦堡垒的勘测员贝瓦尔。', '<贝尔瓦仔细的处理这些工具。>$B$B我要来试用这些工具。如果我们想要了解铁矮人的动机并打败他们，我就需要了解符文确实的功用。', '你带着那些工具回来了吗?', '', '去嚎风峡湾找维德瓦堡垒的勘测员贝瓦尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11350, '符文之书', '灰烬图腾酋长派我穿越冰雪林地，侦察东南方那片广阔的岩地——巨人平原。$B$B那里已经被铁矮人占领了，我还瞧见很多石巨人从地下显身。矮人们在巨人身上雕刻符文，似乎打算改造他们。$B$B铁符文唤石者和铁符文束缚者随身携带的秘典中必定有关于石巨人符文的资料。$B$B从他们手中夺得秘典的书页，拼凑成完整的书籍交给我。这是我们破解他们阴谋的唯一途径。', '冬蹄营地的远行者贝姆比要你将符文之书交给他。', '<远侦斥候翻阅着符文之书。>$B$B我不是博学大师，但我对铁矮人的语言还算熟悉。我猜他们刻在巨人身上的符文是来自于他们日常的语言，但有着些许的不同。', '你找到书了吗?', '', '去嚎风峡湾找冬蹄营地的远行者贝姆比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11351, '掌控符文', '我大致猜到了铁矮人在做些什么。他们在铸造符文雕刻工具时向里面灌注了魔法力量。$B$B使用这样的工具进行雕刻，符文就不仅仅是简单的字符了，它们具备了束缚、支配与扭曲的力量。$B$B如果能搞到这样一套工具，我或许能模拟出秘典中的符文。我这里有一只从巨人平原的铁矮人营帐附近捡回的箱子，不过里面是空的。去那里寻找这样的箱子，替我弄回一套完整的工具来。', '将一套铁符文雕刻工具交给冬蹄营地的远行者贝姆比。', '<潘比检查着那些工具。>$B$B它们比我想象得还要更精致。请稍等一下让我试试看它们。', '你带回来那些工具了吗?', '', '去嚎风峡湾找冬蹄营地的远行者贝姆比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11352, '命令符文', '我在这块石板上刻了几行符文，你能感受到它们所散发的能量吗？和铁矮人使用的符文相比，这些符文较为低等。但是我们依然可以利用它们粉碎铁矮人的阴谋。$B$B带上符文转至巨人平原，对一个尚未被改造的石巨人使用符文。$B$B在符文的作用下，石巨人会听从你的指挥并逐渐恢复原有的力量。接下来，你要在他的帮助下击败缚石者穆迪斯，这家伙就是盘踞在巨人平原的铁矮人领袖。', '冬蹄营地的远行者贝姆比要你去测试命令符文，并击败缚石者穆迪斯。', '你能击败束缚者穆迪斯真是太好了，但铁矮人不会轻易放弃的。$B$B当我的族人往北，我很确信我们会再次遭遇铁矮人。下一次，我们会在他们开始之前就先打败他们。', '你测试过符文了吗?', '', '去嚎风峡湾找冬蹄营地的远行者贝姆比。', '测试命令符文', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11354, '悬赏：纳杉的骑鞭', '今天，有位顾客对伊利丹的传令官及其坐骑表现出莫大的兴趣。当然，我指的是传令官瓦兹德和纳杉。$B$B想要领取酬金的话，就转至地狱火堡垒，进入地狱火城墙，将纳杉的骑鞭带回来。$B$B我得到的情报有点奇怪，据说纳杉的骑鞭是由纳杉自己来保管的，而且还据说这头龙从来都不肯让传令官使用骑鞭。', '商人扎雷姆要求你夺得纳杉的骑鞭。将骑鞭带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '我又可以满足一位客户的要求了。这件物品看起来状况良好。你可以领取赏金了。$B$B请你明天再回来，我将有新的任务要交给你执行。', '请把骑乘马鞭交给我。', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11355, '巨人的迁徙', '东边的巨人平原起了骚动，刻有符文的石巨人开始往北边的霜刃峰迁徙。我不知道他们的目的地是哪儿。$B$B刻在他们身上的符文散发着诡异的光芒，驱使他们前进。如果你能击倒巨人，从他们体表剥下一些符文，符文的效力就会消散，便于我们展开研究。$B$B利用这把锄从巨人身上剥下一些符文石板，然后把它们给我带回来。', '维德瓦堡垒的研究员艾德兰要你在4个符文石巨人的尸体上使用符文搜寻之锄。', '<研究员艾德兰听着你的发现。>$B$B象征『北方』与『西方』的符文反复出现?这表示强大的命令他们往那个方向移动，但符文不只是推力。某种东西吸引着他们，但是什么呢?', '你找到了些什么?', '', '去嚎风峡湾找维德瓦堡垒的研究员艾德兰。', '分析符文石巨人的尸体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11358, '破碎石板', '如果能查明是什么东西诱使巨人朝西北方迁徙，我们或许可以设法阻止他们。$B$B虽然我破译了你取回的样本上的一部分符文，但是我更想了解那些我没看懂的文字的含义。我曾经在巨人平原东北部，与霜刃峰的雪原交界处见过一块巨大的残破石板。带上这份样本，去与那里的石板进行比较，看看能不能有所发现。', '维德瓦堡垒的研究员艾德兰要你对符文样本与破碎石板进行比较。', '<艾德兰听你叙述你的发现。>$B$B原来如此!麦加力斯一定是那些铁矮人计画的核心。我们一定要在计画实现之前摧毁它!', '你查出来为什么诱因吸引那些巨人了吗?', '', '去嚎风峡湾找维德瓦堡垒的研究员艾德兰。', '将符文样本与破碎石板进行比较', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11359, '击败麦加利斯', '在缚石者穆迪斯改造出的符文巨人中，拥有强大力量的麦加利斯脱颖而出，成为巨人迁徙行动的领头者。只要击败麦加利斯，巨人就会像无头苍蝇一样丧失方向。远征军赶来后，我们的士兵就能逐个消灭剩馀的巨人，将铁矮人驱逐出巨人平原。$B$B转至巨人平原的北部边界，在霜刃峰的丘陵地带搜寻麦加利斯的下落并击败他！', '击败麦加利斯，然后返回维德瓦堡垒，向研究员艾德兰复命。', '击倒麦加力斯真是太好了，但我对他最后说的话有些好奇。$B$B你确定他说的是石铸堡?$B$B我没有听过这个名字，但是它听起来和泰坦有着相同的起源。这些铁矮人对那地点究竟有何计画?$N，这值得观察，在这些铁矮人的计画成功以前，我们必需要先找到它。', '你来带麦加力斯被击败的消息了吗?', '', '去嚎风峡湾找维德瓦堡垒的研究员艾德兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11360, '消防练习', '在无头骑士的威胁之下，闪金镇的英雄们随时都准备着组成消防队，扑灭这里的火势。你愿意加入我们吗？$B$B就在这里北边不远，暴风城的卫兵们已经创建了一处小营地，练习救火。你也到那里去练习吧，用小水桶把水泼到火盆上就行了。小水桶在水缸周围放了许多，你可以自由取用。$B$B再见，$N。你完成了消防队的练习之后，请再过来找我们！', '将小水桶里的水倒在5处火盆上，然后与穿戏服的孤儿院长谈一谈。', '你身上全给烟灰弄脏了!你想必已经扑灭了那些火焰!$B$B干得好!身为一个救火队的荣誉成员，我请求你在村庄需要你的时候回来帮助我们!', '你好，$N。你是否磨练了你的救火技巧了呢?别忘了演练区就在南边!', '', '去艾尔文森林找闪金镇的穿戏服的孤儿院长。', '灭火', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11361, '灭火练习', '步兵队在村外不远的地方设立了一处消防练习点。要知道，剃刀岭的建筑物这几天总是会着火。你也应该去参加练习，成为一名消防员！$B$B从西门走出剃刀岭，然后立刻转向右边，就能找到训练营。到那里拿个水桶就赶紧开始练习灭火吧！', '将小水桶里的水倒在5处火盆上，然后回到剃刀岭，与戴面具的孤儿院长谈一谈。', '做得好，$N!孩子们，好好地看看这位$C。要长得像$g他:她;一样强壮和勇敢，然后有一天你们也会为了部落而战。', '你扑灭过火焰了吗，$N?演练区就在剃刀岭西边出口的西方。', '', '去杜隆塔尔的剃刀岭找戴面具的孤儿院长。', '灭火', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11362, '悬赏：克里丹的羽饰法杖', '俗话说青菜萝卜各有所爱，就拿我刚接待的顾客来说吧。$B$B地狱火堡垒中有个名叫击碎者克里丹的邪兽人，他有一柄极其寻常的法杖，根本不值一哂，但这位顾客偏偏就指名要这柄法杖。$B$B我怎么能拒绝顾客的请求呢？$B$B想要领取酬金的话，就转至鲜血熔炉，从克里丹手中夺回法杖。', '商人扎雷姆要求你夺得克里丹的羽饰法杖。将法杖带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '也许我会将一些新的羽毛绑在手杖上，然后再寄给那位买家。我想有这么多阿拉卡在附近，那些羽毛只算是小事一桩，不会影响你应该取得的赏金。$B$B请你明天再回来，我将有新的任务要交给你执行。', '我们再次的交谈……你一定取回手杖了。', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11363, '悬赏：刃拳的印记', '今天我接待了一名腰缠万贯的收藏家，这位贵客想要购买某件特殊的器物。$B$B酋长卡加斯·刃拳总是随身携带着一枚印章，用来签署各类官方文件。我要你替我夺回这东西。$B$B卡加斯·刃拳就在破碎大厅深处。毫无疑问，你需要铲除大量兽人杂兵才能到达酋长面前，不过我深信你会凯旋的。', '商人扎雷姆要求你夺得刃拳的印记。将印记带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '你夺回这件东西的英勇行为应该被诗人们记载在羊皮纸上才对。这是你的赏金，你的行径远比这点小钱来的伟大。$B$B请你明天再回来，我将有新的任务要交给你执行。', '我听说大酋长用武器取代了他的双手。这是真的吗?', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11364, '悬赏：碎手百夫长', '你经常质疑你的主人吗？玛哈杜恩可绝对不会。$B$B现在，我需要的就是破碎之手氏族百夫长的血。你可以在地狱火堡垒的破碎大厅中找到他们。$B$B如果你还想要赏金，就赶紧去杀了他们再回来。', '虚空猎手玛哈杜恩要求你杀死4名碎手百夫长。完成任务后返回沙塔斯城的贫民窟，找他领取奖赏。', '很好，你已经赚到这笔赏金了。$B$B明天再回来找我吧，风将会再次对玛顿恩细诉。', '你回来了。那些百夫长都死了吗?', '', '去找泰罗卡森林的虚空猎手玛哈杜恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11365, '巨人的迁徙', '东边的巨人平原起了骚动，刻有符文的石巨人开始往北边的霜刃峰迁徙。我不知道他们的意图，也不清楚他们的目的地。$B$B刻在他们身上的符文散发着诡异的光芒，驱使他们前进。如果你能击倒巨人，从他们体表剥下一些符文，符文的效力就会消散，便于我们展开研究。$B$B利用这把锄从巨人身上剥下一些符文石板，然后把它们给我带回来。', '冬蹄营地的先知厄丹要你在4个符文石巨人的尸体上使用符文搜寻之锄。', '<贤者听着你的发现。>$B$B象征“北方”与“西方”的符文反复出现?这表示强大的命令他们往那个方向移动，但符文不只是推力。某种东西吸引着他们，但是什么呢?', '你发现了什么?', '', '去嚎风峡湾找冬蹄营地的先知厄丹。', '分析符文石巨人的尸体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11366, '破碎石板', '我们必须查明是什么东西诱使巨人朝西北方迁徙，这样就能设法阻止他们。$B$B样本上的符文为我们提供了部分线索，但是我更想了解那些我没看懂的文字的含义。我曾经在巨人平原东北部，与霜刃峰的雪原交界处见过一块巨大的残破石板。带上这份样本，去与那里的石板进行比较，看看能不能有所发现。', '冬蹄营地的先知厄丹要你对符文样本与破碎石板进行比较。', '<伊丹听你叙述你的发现。>$B$B麦加力斯?一份石板的文字翻译!这个麦加力斯一定是那些铁家伙神秘计画的核心。', '你查出来是什么诱因吸引那些巨人了吗?', '', '去嚎风峡湾找冬蹄营地的先知厄丹。', '将符文样本与破碎石板进行比较', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11367, '击败麦加利斯', '在缚石者穆迪斯改造出的符文巨人中，拥有强大力量的麦加利斯脱颖而出，成为巨人迁徙行动的领头者。只要击败麦加利斯，巨人就会像无头苍蝇一样丧失方向。当我们向北迁徙时，我会请求酋长派遣一队士兵对付剩馀的巨人。没有了巨人的助力，那些铁矮人肯定抵挡不了多久。$B$B转至巨人平原的北部边界，在霜刃峰的丘陵地带搜寻麦加利斯的下落并击败他！', '击败麦加利斯，然后返回冬蹄营地，向先知厄丹复命。', '击倒麦加力斯真是太好了，但我对他最后说的话有些好奇。$B$B你确定他说的是石铸堡?$B$B这可不是我们同胞所熟悉的名字，不过那可能是外人所谓的“泰坦”的创生物。铁矮人一直以来都是冷酷而危险的敌人，$N。我们一定要盯着这些矮人，并且在他们行动之前就先找到这个石铸堡。', '你带来麦加力斯被击败的消息了吗?', '', '去嚎风峡湾找冬蹄营地的先知厄丹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11368, '悬赏：夸格米拉之心', '我有个不太寻常的请求。有个特别特别有钱的家伙通过地下渠道向我求购一件令人毛骨悚然的东西。$B$B明确地讲，她想要夸格米拉的心脏。$B$B我听说那只动物有三颗心脏，不过一颗就足够满足我们这里的订单了。如果我记得没错，你可以在奴隶围栏里一处很深的水池中找到它。', '商人扎雷姆要求你取回夸格米拉之心。将心脏带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '现在我才觉得可惜，没有叫你顺便把另外两颗心脏一起带回来。也许下一次吧。不管如何，你得赢得了你的奖赏。$B$B明天再来找我吧，我还有别的任务要托付给你。', '我想你在运送的过程中应该懂得如何保藏这颗心脏吧?', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11369, '悬赏：黑色阔步者的卵', '据说，赞加沼泽的所有沼泽行者都有一个共同的母体，那就是黑色阔步者。假如黑色阔步者死去，它曾产下的卵就会孵化出来，成为新的黑色阔步者。$B$B现在，有位买家对那些卵感兴趣，据说她的动物园里想要添加一只新动物，以吸引游客。$B$B如果你对我开出的赏金感兴趣，就赶快去幽暗沼泽的黑色阔步者那里搞来它的卵吧。', '商人扎雷姆要求你取回一枚黑色阔步者的卵。将卵带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '可以从蛋中感受到生命的脉动并不稀奇?我最好赶快把蛋送去给买家。我们可不希望它在这里孵化，对吧?$B$B你的酬劳已经准备好了。$B$B明天再来找我吧，我还有别的任务要托付给你。', '我们再次交谈是因为你已经拿到了蛋，对吧?太杰出了，让我看看它!', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11370, '悬赏：督军的论文', '许多人都可以从头衔上得知，督军卡利瑟里斯是一位非常强大的战士，可是很少人知道他还是一位军事大师。$B$B我有一位客户恰好知道此事，而且对他的军事论文非常非常感兴趣。$B$B我要你立刻转至盘牙水库里的蒸汽地窟，去把那本书给我带回来。', '商人扎雷姆要求你夺得督军的论文。将论文带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '嗯，我怕我的顾客没有足够的时间把整本书看完了。不过，这不是我们该担心的事情。这是你的酬劳。$B$B明天再来找我，我还有别的任务要托付给你。', '我的顾客有点不耐烦了。我相信他想要了解督军的战术思考，好帮助他进行他的计画。', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11371, '悬赏：盘牙侍从', '玛哈杜恩听到了一些消息，并且打算借你的手去做些事情。$B$B总之，有人要我去想办法搞定那些盘牙部族的侍从，盘牙水库的蒸汽地窟就是他们的藏身之所。$B$B去吧，记住，他们必须被彻底消灭。', '虚空猎手玛哈杜恩要求你杀死14名盘牙侍从。完成任务后返回沙塔斯城的贫民窟，找他领取奖赏。', '我相信这场战斗值得你所消耗的时间?起码赏金一定是值得的。$B$B明天再来找我吧，风将会再次对玛顿恩细诉。', '你和盘牙部属的战斗进展的如何了?', '', '去找泰罗卡森林的虚空猎手玛哈杜恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11372, '悬赏：艾吉斯的冠羽', '最近，有一位牛头人女士的丈夫马上就要升任酋长了，因此她来找我，希望能为丈夫的帽子上添加一片特别的装饰。$B$B因此，她想要利爪之王艾吉斯的羽毛，对，就是那个卑鄙而可憎的利爪之王艾吉斯。$B$B如果你对赏金有兴趣的话，就立刻到奥金顿的塞泰克大厅里去干掉他吧。', '商人扎雷姆要求你夺得艾吉斯的冠羽。将羽毛带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '我相信这些羽毛一定可以替酋长的头饰增色不少。你已经赢得了你的酬劳，$C。$B$B明天再来找我，我还有别的任务要托付给你。', '酋长仪式的日期快要到了。', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11373, '悬赏：沙法尔的精致饰物', '今天，我有一个私人请求想要委托你去处理，当然，难度也会跟酬劳成正比。$B$B怎么说呢，我的系列跟节点亲王沙法尔还有他的那群手下有点“往事”。如果你能把他的饰物带到我这里来，我就可以确认他已经被妥当地“处置”了。$B$B怎么样，如果我开出的赏金对你还算有诱惑的话，就到奥金顿的法力陵墓去找他吧。', '商人扎雷姆要求你夺得沙法尔的精致饰物。将饰物带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '<你可以感觉到风之贸易者获得了很大的满足。>$B$B很好，我很高兴听到他死去的消息。或许我能自己解开他护符的秘密。不然，我也可以把它卖个好价钱。$B$B我相信这样的报酬应该很适当。$B$B明天再来找我，我还别的任务要托付给你。', '没多少人知道萨法尔的魔力来自于他的护符。没有了护符他就失去了力量。$B$B不过，你有了这个就表示他已经死了。', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11374, '悬赏：主教的灵魂宝钻', '在奥金尼地穴中，那些人为了了解通灵魔法的真谛，正进行着一系列令人作呕的实验。无数无辜的灵魂在那里受到了无止境的折磨与摧残。$B$B我有一位客户非常希望解放这些灵魂。我听说这些灵魂被囚禁在一块灵魂宝石之内，而这块宝石就在大大主教玛拉达尔的手上。$B$B立刻到地穴内找到他，把宝石抢回来吧。', '商人扎雷姆要求你夺得主教的灵魂宝钻。将宝钻带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '你真是个$g英雄:女英雄;，$N。我相信我的顾客应该可以找到办法来释放宝石中他们所爱的人。这真是一次杰出的工作，你的酬劳已经准备好了。$B$B明天再来找我，我还有别的任务要托付给你。', '你能想象自己永远被禁锢在宝石中吗?', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11375, '悬赏：摩摩尔的低语', '听我说完以后，你恐怕就不会想要去做这份委托了。$B$B我有个非常古怪的客户对研究已死的其它物质世界非常有兴趣。你也知道，据说摩摩尔曾经将上一个召唤出它的世界毁灭掉了。因此这位教授对摩摩尔的“耳语”非常感兴趣，据说这是它的某个能力还是什么类似的东西。$B$B你愿意转至奥金顿的暗影迷宫，把它取回来给我吗？', '商人扎雷姆要求你夺得摩摩尔的低语。将这件器物带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '我还担心你回不来了。我想你应该没有因为和摩摩尔战斗而聋了?$B$B这是你的奖赏。毫无疑问教授一定会很高兴的，虽然我有点担心他要拿这东西做什么。$B$B明天再来吧，我还有别的任务要你帮忙。', '我甚至不太确定一个低语要如何在物质世界中具现，但教授向我保证，当你看到的时候你就会明白。$B$B也许那个东西像是个喉头?', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11376, '悬赏：恶毒导师', '玛哈杜恩听说在暗影迷宫之内有一些可怕而残忍的六臂女魔头。$B$B立刻到奥金顿去，把这些恶魔都找出来，然后干掉。$B$B如果你连这么简单的委托都不能完成，我们以后恐怕就再也不用谈什么生意了。', '虚空猎手玛哈杜恩要求你杀死3名恶毒导师。完成任务后返回沙塔斯城的贫民窟，找他领取奖赏。', '我很满意。透过虚空传达意旨的，也会同样满意。玛顿恩准备好你的赏金了。$B$B明天再来找我吧，风将会再次对玛顿恩细诉。', '那些导师，她们都死光了吗?没有?$B$B我不是说没杀光她们之前不要回来吗?', '', '去找泰罗卡森林的虚空猎手玛哈杜恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11377, '甜美的复仇', '我正在给一些与众不同的客人准备伙食。他们中有个家伙在从斯克提斯飞来的途中被一头巨大的卡利鸟撞了个嘴啃泥——他的腿严重骨折了。$b$b他们希望我能给他的康复聚会提供一点特别的食物：炖卡利鸟。$B$B我可以把我的烹锅借给你，这样你就可以用它来烹制美味了。这个食谱其实很简单，不过你需要一根巨型卡利鸟的翅膀和一些迁跃兽汉堡。', '贫民窟的巨石洛克希望你用他的烹锅制作一些炖卡利鸟，完成之后回去找他。', '噢，我真的闻到美味的食物了!我希望你好好揍了一顿那些臭鸟。$B$B别客气，自己拿一些多的。我相信你的才能一定可以派上好用场的。', '我是不是闻到什么很美味的东西?', '', '去找泰罗卡森林的巨石洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11378, '悬赏：时空猎手的徽记', '我的客户很多，品位从最平凡最普通的直到最奇特最古怪的都有。而且呢，有些时候，他们会用你能找到的最奇特最古怪的东西去做一些最平凡最普通的事情。$B$B你看，比如说刚才这桩委托。我这位匿名的客户想要得到时空猎手的徽记来装饰他家的墙壁。$B$B嗯，你现在是否可以通过时光之穴回到过去的希尔斯布莱德丘陵，去帮我把那个所谓的战利品给带回来呢？', '商人扎雷姆要求你取回时空猎手的徽记。将徽记带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '你安然回到现在的时空了。$B$B<风之贸易者四处张望。>$B$B看来并没有什么事情改变。但我又怎么会知道是否发生过改变呢?$B$B这一刀斩得俐落，我的顾客会很高兴的。这是你的赏金。$B$B明天再来吧，我还有别的任务要托付给你。', '时空猎手的头颅…怎么会有人想要把这种东西挂在墙上?$B$B而且还不是亲自去猎杀它，而是叫他的朋友去对付那个东西?$B$B我猜，他只是在说谎。', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11379, '超级美味烧烤', '我正在尝试创造一些充满活力的东西。不过说实话，现在我更像是一个只会纸上谈兵的地精，我已经失去了冒险的感觉。$B$B但你……让我想起了我年轻的日子，一手握着剑，一手握着一口锅子。准备去征服整个世界吧！$B$B我希望你能拿上我最喜爱的烹锅去刀锋山，把一些肋排和香脆蛇——已经煮熟的最棒的香料——放在深渊烈焰使者的尸体上烤一下，那可是唯一可以把它们烤透的东西。', '贫民窟的巨石洛克希望你用他的烹锅、两份莫克纳萨肋排和一份香脆蛇制作一些恶魔烧烤，完成之后回去找他。', '看看这样东西……$B$B<洛克尝了一口这道混合的菜肴，他的脸呈现出一种既痛快又开心的奇特表情。>$B$B我的阿达欧啊，这味道真棒!像你这么有潜力的厨师应该随时都带着烹饪的材料。从我储备的材料中拿一些走，然后让我以你为荣吧。', '我的小实验进行的如何了呢?', '', '去找泰罗卡森林的巨石洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11380, '魔法美味', '你知不知道，我刚把鱼和肉储存起来，就有个人过来要求我做一份既可以让他吃饱、又能让他精神振奋的食物：魔法草莓大餐。$B$B不幸的是，魔法莓只生长在虚空风暴的生态圆顶里。对了，虚灵对魔法莓有着特别的偏爱，所以风暴尖塔附近的魔法莓都被采光了。$B$B我只相信只有那些受过良好烹饪训练的厨师才能采到最好的魔法莓，所以不要让我失望！', '贫民窟的巨石洛克要求你从虚空风暴的生态圆顶中收集15颗魔法莓，完成之后回去找他。', '这些可是我看过最多汁的法力莓果了。我想光是瞧着它们就让我变聪明了。$B$B看来我不太需要那些鱼肉的存货，你要不要拿一些走?相信你一定可以做出一些美味的料理。', '运气如何，朋友?', '', '去找泰罗卡森林的巨石洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11381, '灵魂之汤', '我感觉到了一股强烈的杀气。我还从未收到过这么多购买我的名菜——灵魂之汤的订单。。$B$B我一眼就能看出，你和我一样醉心厨艺……那么你愿意帮我一把，顺便赚点小钱吗？$B$B过来，拿上我的烹锅，收集一些裂蹄牛肉，并且我会让你分享我的秘密。什么让我的汤如此大补？因为那不是鸡肉——我在纳格兰的先祖之地烹饪它，让它在那里吸收了所有灵气。', '贫民窟的巨石洛克希望你用他的烹锅制作一些灵魂之汤，完成之后回去找他。', '我可没闻过这么香的心灵鸡汤。只要一小撮胡椒就完成了。$B$B这是先前答应过的酬劳。因为你做得这么好，我大概得丢掉一些先前的存货了。', '什么闻起来这么香?', '', '去找泰罗卡森林的巨石洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11382, '悬赏：埃欧努斯的沙漏', '我敢发誓，这个客户一定是疯了。你看，世上有许多值得你去追求的东西，但也有你绝对不该想的！$B$B现在我的这个客户的脑子绝对绝对是进水，魔法冰川水！他竟然觊觎垂涎起埃欧努斯的沙漏了。$B$B对，你没有听错，永永恒之龙的埃欧努斯！$B$B但是……但是……他付出了能把一个国王赎回来的钱，我又有什么好说的？总之，去吧，到时光之穴的黑色沼泽去，把那沙漏给我取回来。', '商人扎雷姆要求你夺得埃欧努斯的沙漏。将沙漏带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '这里面的沙子还往上流，真是诡异。我想我最好还是尽快把东西交给它新的主人。$B$B我感谢你完成了这个困难的工作，$C。$B$B明天再来找我，我还有别的任务要托付给你。', '要是我是你，我一定会非常小心应付时光旅行。你说不定会不小心杀死你的某一位祖先，以致于抹消你现在的存在!', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11383, '悬赏：裂隙领主', '玛哈杜恩知道你该去哪儿，玛哈杜恩还知道你必须得去杀裂隙领主，但问题是，玛哈杜恩不知道你什么时候该去。$B$B我知道这话你不明白，不过传来的命令就是这样了。$B$B转至时光之穴的黑色沼泽，一切就都会明白了。', '虚空猎手玛哈杜恩要求你杀死4名裂隙领主。完成任务后返回沙塔斯城的贫民窟，找他领取奖赏。', '你找到方法穿越时空了。你一定是个伟大的$r$C。你得到了赏金。$B$B明天再来找我吧，风将会再次对玛顿恩细诉。', '我们谈过了，我可以感觉到那些裂隙领主还没有死绝。$B$B等他们都死光了再回来找我，$C。', '', '去找泰罗卡森林的虚空猎手玛哈杜恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11384, '悬赏：扭木碎片', '不久之前，一位卡多雷德鲁伊曾请求过我，喔，真的很令人同情。当然，开价也不错！$B$B总之，达纳苏斯方面希望能让一株叫作跃迁扭木的古树获得新生。当前，这棵树陷入了精神的混乱或是说污染，我不太确定。总之，你可以在风暴要塞的生态船那边找到。$B$B哦，她还说，她们只需要一小条嫩枝就可以使它重生。', '商人扎雷姆要求你夺得一份扭木碎片。将碎片带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '哇，你拿到了!它好细小。不过，等那些德鲁伊完成了他们的计画 -- 我听说得花上非常久的时间 -- 迁跃扭木就会重新长成。$B$B这是先前答应的酬劳。$B$B明天再来找我，我还有别的任务要托付给你。', '你不知道怎么去生态船?你不会认错的……它就在风暴要塞，靠近虚空风暴的东侧边缘。', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11385, '悬赏：寻日者导魔者', '今天，有人向玛哈杜恩传信说，希望看见那些寻日者部队手下的导魔者全都完蛋。$B$B他们就在风暴要塞的生态船里。$B$B如果你想要赏金，就去杀了那些导魔者。', '虚空猎手玛哈杜恩要求你杀死6名寻日者导魔者。完成任务后返回沙塔斯城的贫民窟，找他领取奖赏。', '现在他们全都死去了，再也没有导魔师了。透过虚空低语者获得了满足，你可以领取你的赏金了。$B$B明天再来找我吧，风将会再次对玛顿恩细诉。', '我们怎么可以在导魔师尚未死去前闲谈呢?', '', '去找泰罗卡森林的虚空猎手玛哈杜恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11386, '悬赏：帕萨雷恩的投影仪', '我一直以为计算者帕萨雷恩是使用魔法将自己的投影传送到外域各地的，但显然我是错了。$B$B反正我当前的客户告诉我说那个血精灵是使用一台机械设备与凯尔萨斯王子手下各项计划的领导者联络的。我现在明白了，这一定是从虚空风暴的萨克希斯叛军那里搞到的。不如你去拜访一下帕萨雷恩吧？他就在风暴要塞的能源舰上。', '商人扎雷姆要求你夺得帕萨雷恩的投影仪。将投影仪带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '我打算把这个东西自己留下来，然后把钱退给我的客户。这一定能够大大拓展我的生意范围。$B$B<风之贸易者叹气。>$B$B但是我得维持我的声誉。$B$B说到我的声誉，感谢你帮忙维持它。这是你的酬劳。$B$B明天再来找我，我还别的任务要托付给你。', '并不是那个投射科技有什么特别之处，而是它能投射的范围才是真正的技术突破!', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11387, '悬赏：风暴锻铸摧毁者', '玛哈杜恩接到了指示，说在能源舰中有些机器必须被拆掉。$B$B去风暴要塞，找到那些风暴锻铸摧毁者，摧毁它们。$B$B然后你就可以回来领取赏金了。', '虚空猎手玛哈杜恩要求你杀死5名风暴锻铸摧毁者。完成任务后返回沙塔斯城的贫民窟，找他领取奖赏。', '玛顿恩喜欢和构装生物作战，它们不像有机生物那样麻烦。$B$B赏金是你的了。$B$B明天再来找我吧，风将会再次对玛顿恩细诉。', '<虚空巡者歪着头，显然对你的出现感到困惑。>$B$B那些毁灭者还没有被全数消灭。', '', '去找泰罗卡森林的虚空猎手玛哈杜恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11388, '悬赏：斯克瑞斯的卷轴', '今天的客户似乎在寻找某样很特别的东西。$B$B据说，上古之神有一位仆从叫作预言者斯克瑞斯，它身上携带着一份上古之神的卷轴，里面写着让他操控宇宙中的其它生物为他们服务的指示。$B$B我当前这位买主想要这份卷轴，至于读不读得懂，他不关心。$B$B现在，立刻去风暴要塞的禁魔监狱，帮我把这份卷轴抢回来吧。你说怎么样，$c？', '商人扎雷姆要求你夺得斯克瑞斯的卷轴。将卷轴带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式下完成。', '我可不敢碰那个卷轴，说不定会引起上古诸神的注意，太冒险了。我会让我的助手把东西送出去。$B$B你不只是赚得你的赏金，$C，我祝福你在所有已知的世界中都福星高照。$B$B明天再来找我，我还有别的任务要托付给你。', '牵扯进入上古诸神的事情一定非常危险。$B$B幸好是你不是我!', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11389, '悬赏：禁魔监狱斥候', '禁魔监狱内的所有哨兵都陷入了混乱状态。里面的囚犯发动了暴乱，而那些守卫竟然攻击前去帮助他们的人。$B$B玛哈杜恩从灵风之中听到了雇主的要求，他要我们摧毁那些哨兵。$B$B去完成这个委托，赏金就是你的了。', '虚空猎手玛哈杜恩要求你杀死5名禁魔监狱斥候。完成任务后返回沙塔斯城的贫民窟，找他领取奖赏。', '既然那些哨兵已经被摧毁了，也许纳鲁会叫联合团取代他们?玛顿恩并不知道也不想知道。$B$B你已经可以领取赏金了。$B$B明天再来找我吧，风将会再次对玛顿恩细诉。', '你不知道怎么去风暴要塞和禁魔监狱吗?它们位在虚空风暴的东边，一个在高空中，而另一个高度较低，看你想去哪一个地方。', '', '去找泰罗卡森林的虚空猎手玛哈杜恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11390, '我有飞行器！', '那么，你还在等什么呢？我们有大把工作要做！$B$B这是飞行器的钥匙。将3袋古器运到钢铁之门北面和南面的起重机平台上。我会在平台上做好标记，免得你找不到。$B$B快去吧！别浪费时间了！', '钢铁之门首席考古学家希望你将3袋古器从挖掘场底部运到钢铁之门北边或南边的平台上。$B$B利用飞行器上的抓升钩搬运古器。$B$B完成任务后向钢铁之门首席考古学家复命。', '干得好，不过我觉得你应该要补习一下基础的驾驶课程。$B$B嗳，没关系，有总比没有好。这是你今天的报酬。', '哎?你拖运完所有东西了吗?', '', '去嚎风峡湾找的钢铁之门找钢铁之门首席考古学家。', '运送古器', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11391, '钢铁之门的巡逻兵', '嗯？你又回来找活干了？$B$B很好，来，给你钥匙。我们今天没什么需要搬运的，你只要出去巡逻一圈，留神任何可疑情况就行了，明白吗？$B$B我已经在飞行器上装载了火箭弹和机关枪——以防万一嘛。', '你已经是钢铁之门的王牌飞行员了，因此钢铁之门首席考古学家要你在挖掘场四周巡逻，对付来袭的敌人。$B$B完成巡逻任务后向他复命。', '瞄得准，高手。$B$B这是你的报酬。明天再来巡一趟，有听到吗?', '石像鬼?!我看过他们!你把他们全都解决了吗?$B$B这世界到底发生什么事，连矮人在挖掘时都会被攻击。', '', '去嚎风峡湾找的钢铁之门找钢铁之门首席考古学家。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11394, '比鱼人更恶臭……', '有传言说切米尔海岸埋藏着珍贵的古器，于是我跟随探险队来这里调查实情。我原本以为海滩是鱼人的地盘，但是当我看见这一切时，简直不敢相信自己的眼睛！$B$B<探险者伸出头来瞧了瞧四周。>$B$B天灾军团占领了切米尔海岸，他们将鱼人和其它生物变成了一具具的行尸走肉！$B$B$C，我们应该做点什么。你能解决掉那些天灾军团的成员吗？', '探险者亚伦要你转至切米尔海岸，在那里杀死15名任意种类的天灾军团成员，完成任务后向他复命。', '<贾伦看来对你的成功十分兴奋，但还是提醒你要把声音压低。>$B$B干得好，$N!不过你身上还真是沾了不少天灾军的口水。你可能得考虑跳进海峡里泡个澡。那会很冷，不过可以马上把你给弄干净。', '我不知道，$C，看起来你消灭的数量还不够。', '', '去嚎风峡湾找切米尔海岸的探险者亚伦。', '杀死切米尔海岸的天灾军团成员', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11395, '天灾装置', '死去的天灾军团成员手中紧握着一件装置，上面镶嵌着一枚宝石，看上去很像是悬浮在天灾水晶顶端的那种宝石。$B$B应该把这玩意儿交给探险者亚伦瞧瞧。', '将天灾设备交给切米尔海岸的探险者亚伦。', '我知道这是什么!$N，这是那些天灾水晶的控制装置!$B$B我跟你打赌这一定能关闭他们的能量力场。嗯嗯。$B$B<探险者看起来陷入了沉思，推敲着你持有这个装置的意义。>', '你拿了一个看来很奇怪的装置，$C。让我看仔细点。', '', '去嚎风峡湾找切米尔海岸的探险者亚伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11396, '关闭护盾', '瞧，控制器侧面有个按钮。我敢打赌，如果你离天灾水晶够近的话，就可以用控制器关闭它的护盾。接下来嘛，在护盾恢复之前摧毁水晶就行啦。$B$B$N，怎么样？你愿意接受这项任务吗？只要你顺利地关闭护盾并摧毁水晶，就能得到一份很棒的奖励。$B$B天灾军团疯狂地将其它生物转换成他们的同类，这是我们唯一能阻止他们的方法。', '切米尔海岸的探险者亚伦要你摧毁3颗天灾水晶。', '漂亮!$B$B<贾伦飞快地四处张望了一下，确保没有人注意到他的欢呼。>$B$B好吧，你赢得了一份我在这里挖掘发现的东西。$B$B还有，$N，如果你回到钢铁之门，把我的爱带给艾琳娜，告诉她我一切平安。', '我不知道，$N。我觉得你应该要解决更多那种东西。', '', '去嚎风峡湾找切米尔海岸的探险者亚伦。', '摧毁天灾水晶', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11397, '比鱼人更恶臭……', '有传言说天灾军团的势力已经渗透到了这里，我是来调查实情的。我原本以为海滩是鱼人的地盘，但是当我看见这一切时，简直不敢相信自己的眼睛！天灾军团占领了切米尔海岸，他们将鱼人和其它生物变成了一具具的行尸走肉！$B$B$C，我们必须阻止天灾军团继续扩充他们的亡灵部队，尤其是鱼人！沿着营地西北方的斜坡一直走就是海滩了。尽快解决掉那些天灾军团的成员！', '药剂师安娜斯塔西娅要你转至切米尔海岸，杀死15名任意种类的天灾军团成员。完成任务后返回药剂师营地向她复命。', '<安娜塔西亚思索了你的成功一阵子。>$B$B你的工作令人满意，然而我感觉到我们应该要多做点什么，以阻止天灾军在这片海滩上的扩张。', '这很有趣，我上次观察的结果似乎你摧毁的数量还不够。也许你应该要加倍努力?', '', '去嚎风峡湾找药剂师营地的药剂师安娜斯塔西娅。', '杀死切米尔海岸的天灾军团成员', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11398, '天灾装置', '死去的天灾军团成员手中紧握着一件装置，上面镶嵌着一枚宝石，看上去很像是悬浮在天灾水晶顶端的那种宝石。$B$B应该把这玩意儿交给药剂师安娜斯塔西娅瞧瞧。', '将天灾设备交给药剂师营地的安娜斯塔西娅。', '我知道这是什么，$N。这是那些天灾水晶的控制装置!$B$B我跟你打赌这一定能关闭他们的能量力场。嗯嗯。$B$B<药剂师看起来陷入了沉思，推敲着你持有这个装置的影响。>', '你拿的是什么，$C?让我看一看那个东西!', '', '去嚎风峡湾找药剂师营地的药剂师安娜斯塔西娅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11399, '关闭护盾', '瞧，控制器侧面有个按钮。我敢打赌，如果你离天灾水晶够近的话，就可以用控制器关闭它的护盾。接下来嘛，在护盾恢复之前摧毁水晶就行啦。$B$B$N，怎么样？你愿意接受这项任务吗？只要你顺利地关闭护盾并摧毁水晶，就能得到一份很棒的奖励。$B$B你无法拒绝这样一个削弱天灾士兵数量的大好机会——尤其是考虑到“天灾鱼人”这种可怕的东西时……', '药剂师营地的药剂师安娜斯塔西娅要你摧毁3颗天灾水晶。', '<安娜塔西亚转身对她的魅魔微笑。>$B$B很好，$N。我愿意承认你替自己赢得了一些选择的权力。', '你摧毁的天灾水晶数量还不够。你要摧毁够多才能拿到报酬。', '', '去嚎风峡湾找药剂师营地的药剂师安娜斯塔西娅。', '摧毁天灾水晶', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11400, '美酒节赛羊会', '如果你将手上的戳印给波尔·冻石看看，就能从他那里买到赛羊会的赛羊。', '给丹莫罗美酒节会场入口处的波尔·冻石看看你手上的戳印。', '干得好，$N…你赢得了节庆酿酒师的信任，获得了借用啤酒节骑乘用山羊的资格。', '在你手上的是『荣誉酿酒者』手印吗?', '', '去找丹莫罗的波尔·冻石。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11405, '召唤无头骑士', '许多悲伤蜡烛装饰着这座南瓜祭坛，摇曳的火光似乎是在窃笑与嘲讽着你……', '将一根悲伤蜡烛插入翻过的泥土。', '你要放下阴郁蜡烛，从无头骑士受阻咒的永眠中召唤他吗?', '这处的泥土最近曾被翻开过。蚯蚓爬在泥土的表层上，挣扎地想要逃开底下的黑暗深渊。', '', '去血色修道院找到一片翻过的泥土。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11407, '为德罗恩的美酒呐喊！', '你想要为美酒节增添光彩吗？我们要你在力量谷的拍卖所外、荣誉谷、智慧谷以及精神谷的旗帜下高声叫喊。$B$B我的赛羊和马鞭借你用4分钟哦。$B$B千万小心，吝啬的地精们可不会在奥格瑞玛里面放上苹果箱。', '在力量谷的拍卖行外、荣誉谷、智慧谷以及精神谷的旗帜下高声叫喊，宣传美酒节。', '你信守诺言，让人知道了我们啤酒大师的名号。感谢你。这是我们答应的奖品章，很高兴能交给你这些。我想那些巨魔一定很吝于支付这些奖品章…$B$B改天再回来帮忙啤酒节的宣传吧。', '你结束了为啤酒节的宣传了吗?', '', '去找杜隆塔尔的考尔特·高斯登。', '在拍卖行外大喊', '在荣誉谷大喊', '在智慧谷大喊', '在精神谷大喊');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11408, '为塔卡里的巫毒酒呐喊！', '我们计划在美酒节上推销巨魔酿造的美酒。你得在力量谷的拍卖所外、荣誉谷、智慧谷以及精神谷的旗帜下高声叫喊。$B$B不过我会为你提供便利的，喏，我的赛羊和马鞭借你用4分钟哦。$B$B千万小心，地精们可不会在奥格瑞玛中放上苹果箱，他们是一帮不折不扣的吝啬鬼。', '在力量谷的拍卖行外、荣誉谷、智慧谷以及精神谷的旗帜下高声叫喊，宣传美酒节。', '你做到了!客人会像潮水般涌来我们这边，得及早准备!感谢!$B$B对了，这是我们承诺过的酬劳。可不能忘了这个…$B$B改天再回来帮忙啤酒节的宣传吧。', '你结束了为啤酒节的宣传了吗?更重要的是，你让大家知道了惊人的巨魔啤酒了吗?', '', '去找杜隆塔尔的亚隆。', '在拍卖行外大喊', '在荣誉谷大喊', '在智慧谷大喊', '在精神谷大喊');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11409, '赛羊会前的热身', '你想要参加赛羊会？矮人们都说自己是驾驭山羊的高手，不过说实话，他们大多数时候都醉醺醺的，骑羊能又什么难的？$B$B在你大显身手之前，你得证明自己能够驾驭这些彪悍的坐骑。$B$B那么，我会借你一根特殊的马鞭和一头赛羊。你需要证明自己的驾驭能力。$B$B让赛羊保持快走、慢跑和疾跑状况各8秒。', '你有4分钟时间驾驭赛羊，让它保持三种不同的速度各8秒。', '干得漂亮!要学会怎么操控你的山羊得花上不少时间。当你一旦做到，你就会希望每只山羊都是竞速山羊。$B$B你说什么?“我的报酬在哪里?”哈哈哈…你得试试最快的山羊!你想要更多?那这样如何…$B$B你赢得了替啤酒节服务的权力，那边有许路复用作可做，有许多的报酬。尤其是对一个年轻急躁的山羊赛手。', '你能够掌控速度吗?', '', '去杜隆塔尔找野猪农场的赛羊管理员雷恩。', '维持快走状态8秒', '维持慢跑状态8秒', '维持疾跑状态8秒', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11410, '逃走的大鱼', '你带来的鲇鱼很不错，做成的鱼饵对大多数的鱼都有效果，不过……我担心它会引来那只水怪！$B$B刚到这里的时，我在鱼钩上用过一些纳特·帕格的鱼饵，当时想也没想就抛杆入水。结果……一只大水怪咬住了鱼钩，并且在挣扎的时候把线缠在了它体表那嶙峋的冰柱上！$B$B那时候要不是我眼疾手快切断了线，早就被拖进水里吃掉了！在干掉这只名叫霜鳞的怪物之前，我是绝对不敢用新鱼饵的。这个工作就交给你了，到湖中央沉船那边去使用这种新鱼饵，把那只水怪诱出来干掉。它一定会上钩的！一定！', '维德瓦堡垒的克里斯托弗·斯洛安要你击败霜鳞。', '终于，我们可以平安地钓鱼了!当然，在我们抓鱼的时候，远征队就会来到这里然后宣称一切归他们所有。$B$B我们由衷地感谢你，$N。在这里不用拘束。', '我很渴望尝试新饵。$B$B你处理霜鳍的情况还顺利吗?', '', '去嚎风峡湾找维德瓦堡垒的克里斯托弗·斯洛安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11412, '来来回回', '你在这儿真好，我们遇到大麻烦了！替我运送酒桶的地精在离开剃刀岭的路上遇到了意外事件。你必须替我们运回那些酒桶！$B$B骑上一头赛羊转至剃刀岭吧。$B$B当你跑近他时，他会把酒桶抛给你，然后你带着酒桶回到这儿来，再把酒桶抛给我的助手就行啦。我们总共需要3只酒桶。这事儿你要是能办得妥当，我或许能安排些别的工作给你。', '转至剃刀岭，途中你会遇见一名束手无策的地精，从他手中接过一只酒桶，然后将它交给雷恩的助手。在赛羊消失之前取回3只酒桶。', '多亏了你的帮忙!只要啤酒节还在进行，那些黑铁矮人也不放弃攻击，而我们的供应商仍然被困在峡谷之中的话，我就需要有人来帮我运送酒桶。如果你还想多赚几个奖品章，你可以每天都来找我。$B$B这些是你的奖品章，玩得开心点!', '你看到那个哥布尔制造的麻烦了吗?我希望你一路上并没有摔着。', '', '去杜隆塔尔找野猪农场的赛羊管理员雷恩。', '运送酒桶', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11413, '刚才有人说“纪念品”？', '我们不仅供应美酒，还独家出售啤酒杯呢！瞧这些漂亮的杯子，非常具有纪念意义哦！这是一张礼品券。$B$B与美酒节营地背后的布利克斯谈一谈。他是个古怪的家伙，总是带着一副护目镜。他负责兑换礼品券，以及出售各类美酒。', '在美酒节营地背后的布利克斯·菲克维特处兑换礼品券。', '这是什么?酒杯兑换券?你喜欢喝酒吗?太棒了!我把酒杯给你以后，你就可以喝个痛快了!然后再多喝几杯。也许接着再多来几杯……跟着，重点来了，再回来找我。$B$B听着，我知道迟早你一定会再回来找我的。假如你想要兑换啤酒节奖券或者酒桶保管者印记的话，你就要回来找我。$B$B总而言之，这是你的酒杯，记得以后有需要的话再来找我。', '怎么啦宝贝?有东西要给我?', '', '去找杜隆塔尔的布利克斯·菲克维特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11415, '兄弟的背叛', '我梦见过迷雾行者！如果你是她的朋友，那么你也是我的朋友。$B$B直到上一次月圆之夜前，我一直都是族群里的头狼。后来，那头奇怪的白狼，迦瓦尔，从北方来到了这里。在我曾经的兄弟们的帮助下，他很快成了新的头狼。他非常奇怪，很不正常。$B$B如果你想帮我，就先去杀掉那些背叛我的家伙。$B$B比奥莫弗到钢铁之门的西北方去捕猎了，瓦尔戈则在东南方的西部长矛塔楼附近。$B$B他们能轻易识破你的伪装。', '乌尔芬要你去杀死背叛他的座狼，比奥莫弗和瓦尔戈。完成任务后，穿着斗篷回到裂木森林向他复命。$B$B如果你弄丢了座狼伪装，可以去找先知拉瑞恩·迷雾行者再要一件。', '你口鼻上叛徒的血腥味让我很舒爽，兄弟之间是不应该彼此攻击的。', '<巫牙的喉咙里传来一阵低嚎。>$B$B毕欧莫夫和瓦尔格还没死!', '', '去嚎风峡湾找裂木森林的乌尔芬。你需要使用座狼伪装。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11416, '巨鹰之眼', '迦瓦尔用一种奇怪的魔法隐藏了自己的踪迹。除非他自己愿意，没有人能看见或闻到他。但我们也许能有办法。$B$B我的敌人，那头名叫塔隆斯里克的鹰，据说有一双能看穿一切的眼睛。如果你能拿到她的眼珠，就一定能看见迦瓦尔。$B$B塔隆斯里克的巢穴在维库人的据点斯克恩西南方的一条瀑布底下。只要你去翻动鹰巢里的卵，她就会从天空冲下来攻击你。$B$B把她的眼珠给我带回来。', '乌尔芬要你去拿到巨鹰之眼。完成任务后，穿着斗篷回到裂木森林向他复命。$B$B如果你弄丢了座狼伪装，可以去找观察者莉莎·月叶再要一件。', '<巫牙因你击败了他的巨鹰敌人而大声嗥叫。>$B$B击杀的荣耀属于你。我真希望最后包复她颈脖的是我的嘴。$B$B我们别浪费了她的牺牲。东西在这，吃了它们!', '你拿到雌鹰之眼了?', '', '去嚎风峡湾找裂木森林的乌尔芬。你需要使用座狼伪装。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11417, '巨鹰之眼', '迦瓦尔用一种奇怪的魔法隐藏了自己的踪迹。除非他自己愿意，没有人能看见或闻到他。但我们也许能有办法。$B$B我的敌人，那头名叫塔隆斯里克的鹰，据说有一双能看穿一切的眼睛。如果你能拿到她的眼珠，就一定能看见迦瓦尔。$B$B塔隆斯里克的巢穴在维库人的据点斯克恩西南方的一条瀑布底下。只要你去翻动鹰巢里的卵，她就会从天空冲下来攻击你。$B$B把她的眼珠给我带回来。', '乌尔芬要你去拿到巨鹰之眼。完成任务后，穿着斗篷回到裂木森林向他复命。$B$B如果你弄丢了座狼伪装，可以去找先知拉瑞恩·迷雾行者再要一件。', '<巫牙因你击败了他的巨鹰敌人而大声嗥叫。>$B$B击杀的荣耀属于你。我真希望最后包复她颈脖的是我的嘴。$B$B我们别浪费了她的牺牲。东西在这，吃了它们!', '你拿到雌鹰之眼了?', '', '去嚎风峡湾找裂木森林的乌尔芬。你需要使用座狼伪装。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11418, '我们叫他钢羽', '一只勇敢的角鹰兽在堡垒上空盘旋，时不时俯冲下来捕捉猎物。杰森朝他射了好几箭，可是都没有命中目标！$B$B我们给这只出色的角鹰兽取了个名字叫钢羽，不过就是搞不懂他为什么就喜欢在维德瓦堡垒附近出没。大多数角鹰兽都不喜欢人类。$B$B研究员艾德兰用角鹰兽的羽毛制作了一枚护符，据说这枚护符能让用户通过钢羽的眼睛观察世界。', '找到盘旋在维德瓦堡垒上空的钢羽，利用饰羽符咒揭开他的秘密。然后向基尔·克利瑟报告情况。', '你看到了一个巢，还有小幼兽?嗯…所以我们的“他”实际上是个“她”，是吗?$B$B<吉尔给了陷捕者杰桑一个嘲弄的眼神。>$B$B我很确定我们会处得很好，只要杰桑别想要把她变成战利品之一就好了。', '艾德兰的符咒有用吗?', '', '去嚎风峡湾找维德瓦堡垒的基尔·克利瑟。', '发现钢羽的秘密', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11419, '美酒节赛羊会', '如果你将手上的戳印给德利兹·塔波奎克看看，就能从他那里买到赛羊会的赛羊。', '给杜隆塔尔美酒节会场入口处的德利兹·塔波奎克看看你手上的戳印。', '干得好，$N…你赢得了节庆酿酒师的信任，获得了借用啤酒节骑乘用山羊的资格。', '在你手上的是『荣誉酿酒者』手印吗?', '', '去杜隆塔尔找野猪农场的德利兹·塔波奎克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11420, '报复之路', '两周前，我们的主工程师搞到了一把维库人的鱼叉。没错，那帮杂种就是用这玩意儿击沉了我们的船只。经过潜心研究，他居然鼓捣出了一本详尽的操作手册。$B$B不幸的是，他被绑架到了北边的龙颅村。我们找到这位工程师时，他已经奄奄一息了，那本手册也不见了。临死前他告诉我们，那本手册就在龙颅村西北角的乌特加德墓穴中。替我取回它！', '瓦加德的守卫队长索雷克要你取回鱼叉操作手册。', '<索芮克迅速翻阅着手册。>$B$B嗯，有意思…$B$B根据这本手册，维库人有一种特殊工具让他们可以精准地控制鱼叉猎枪。那个东西看起来有点像是我们船上的轮子。而且，这个东西是可携带的，可以像把钥匙一样插在鱼叉猎枪上。我们需要得到这个东西!', '你找到手册了吗?', '', '去嚎风峡湾找瓦加德的守卫队长索雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11421, '扫射龙颅村', '趁着维库人的军队陷入混乱，我们发动反攻吧！带上鱼叉控制器转至尼弗莱瓦，在靠近村子的悬崖上寻找最北端的鱼叉房。$B$B维库人在那里堆放了大批捕鲸用的鱼叉，你只需抢来一把，朝着悬崖下的龙颅村扫射！我要你摧毁长屋、码头和仓库，并杀死转至阻止你的卫兵！$B$B完成你的使命，匕鞘湾的安全就靠你啦！', '嚎风峡湾的约格莫夫·冰锤中尉要你摧毁掠龙长屋、掠龙码头和掠龙仓库，并杀死8名掠龙防御者。$B$B完成任务后将鱼叉控制器交给他。', '干得漂亮，$N!你可是狠狠打击了那些龙骑兵，他们的首领一定气炸了。$B$B你愿意回到瓦尔加德把这个好消息告诉索芮克吗?如果是的话，我倒是有个疯狂的主意!', '龙颅村失火了吗?', '', '去嚎风峡湾找约格莫夫·冰锤中尉。', '', '摧毁掠龙长屋', '摧毁掠龙码头', '摧毁掠龙仓库');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11422, '腐鳃的三叉戟', '<他在地上画出一些潦草的符号，你从中辨认出三叉戟、摩尔古鱼人、一艘破船、太阳，旁边还有一幅模糊的人像，似乎代表你本人。>$B$B<你想了很久才明白这只鱼人的意思。他是要你转至切米尔海岸夺回一柄三叉戟，可太阳是什么意思呢？啊，指的是他的儿子吧。>$B$B<他的儿子肯定是变成了摩尔古鱼人！他要你转至南边的船只残骸附近，杀死他的儿子，夺回三叉戟。>', '老冰鳞要你夺得腐鳃的三叉戟，然后返回切米尔海岸的小岛上向他复命。', '<老冰鳍伸出手从你手上拿走他儿子的三叉戟，他的手微微颤抖着。会是因为这个老鱼人在伤心吗?>$B$B<在他眼底凝聚的那只是水气而已吗?>', '<老冰鳍瞪着一只死鱼眼研究着你，仔细寻找有关他儿子的三叉戟消息。>', '', '去嚎风峡湾找风险湾的老冰鳞。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11423, '敌人的史诗', '随着我们的军队逐步深入诺森德大陆，诸多敌对势力也在节节败退。他们的房屋将被熊熊的战火烧毁，他们的尸体也将被可怕的瘟疫吞噬。所有他们兴盛过与存在过的痕迹，都将被无情地彻底抹除。$B$B但这并不令我感到有多么兴奋，相反，身为一名历史学者，我对此感到十分担忧。东边那座维库人的小镇尼弗莱瓦很快就要被复仇港派出的军队踏平了。可是维库人的吟游诗人赫尔古斯曾经居住在那里，这位伟大的诗人着有三部史诗，分别是《寒冬诅咒的传说》《女武神的传说》和《双子的传说》。趁尼弗莱瓦还没被毁灭，把它们带回来给我。', '进入幽刃岗哨北方的尼弗莱瓦，寻找寒冬诅咒的传说、女武神的传说和双子的传说。', '这真的很有价值，$N。我一定要更努力来抢救并且翻译这些维库文献。$B$B别误会我。我们的敌人固然要被摧毁…但他们古老的知识却未必。', '卷轴，$N?你拿到它们了吗?', '', '去嚎风峡湾找幽刃岗哨的书记员塞古茵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11424, '盾牌岭', '在这种战争时节，零件收集工作做起来总是不太难的。对我来说，到处都能找到合用的零件。$B$B不过话说回来，虽然不难，却也不是特别的简单。尤其是幽暗城那些书呆子科学家们做了无数的药剂散布到无数的镇子里以后，大多数上好的材料都被破坏了$B$B要找趁手的材料真的很困难，不过好在还有些地方可以考虑。南边有处地方叫作盾牌岭，那里还有不少完好的徽记，给我取一些回来，我会给你一笔丰厚报酬的。', '“钢锯”杰妮要你转至新阿加曼德以南的盾牌岭，打败那些被复活的维库人，并收集5枚古代维库人徽记。', '嗯嗯嗯嗯…这些就可以了。当中看起来似乎有些古怪。$B$B告诉你 - 我已经处理尸块好几年了，我的胃从来都没有过这种怪异的感觉。无论如何，君子一言，驷马难追。这是你的报酬。', '拿到我要的骨头了?', '', '去嚎风峡湾找新阿加曼德的“钢锯”杰妮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11426, '寻找控制器', '$N，放心吧。我正在构思一个大计划！绝对震撼！你相信我，照我说的去做准没错。$B$B接下来，我们要搞到手册中提到的控制设备。我觉得吧，龙颅村中那些握着鱼叉的维库人身上肯定有这玩意儿。他们就聚集在村子东边码头的长屋附近。', '将鱼叉控制器交给瓦加德的守卫队长索雷克。', '太棒了!那些发育过度的猿猴很快就会知道惹毛了联盟会有什么下场!', '你找到装置了吗?', '', '去嚎风峡湾找瓦加德的守卫队长索雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11427, '约格莫夫·冰锤中尉', '你瞧见东北方悬崖上维库人搭建的建筑群了吗？他们将那里命名为尼弗莱瓦，利用地理优势和鱼叉朝我们的舰队发动攻击。$B$B不过他们得意不了多久了！$N，把握复仇的机会。我要你将鱼叉控制器交给约格莫夫·冰锤中尉，他就躲在尼弗莱瓦西北方的一座维库人建筑物中。$B$B如果你准备就绪的话，就乘坐我们的狮鹫出发吧！', '守卫队长索雷克要你将鱼叉控制器交给驻扎在尼弗莱瓦外的约格莫夫·冰锤中尉。', '<冰锤中尉从你手中接过鱼叉控制装置。>$B$B啊，你人来还带礼物喔!', '这是什么?我看起来像保姆吗?', '', '去嚎风峡湾找约格莫夫·冰锤中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11428, '凋零之叶', '你是我们最值得尊敬的朋友与盟友之一，$N。因此，我还有一件事需要你的帮助。$B$B之前，你应该已经见过扭曲之林一带的腐蚀情况和那边动物们的惨状了。那些堕落的守护者们一直在不停地扭曲着大自然，并污染着林地中的水源与土壤。只有我们才能阻止他们！$B$B他们的头领名叫凋零之叶，杀了他，这样才能开启那片林地的救赎之门。就像你当初拯救我的姐妹们那样，拯救那里吧！', '冰雪林地的鲁莉尔蕾要求你杀死凋零之叶。', '当我知道守护者背离我们时，我的心都碎了。一度，我们以为他们是我们的兄弟，最亲近的朋友。$B$B我为了我们所失去的兄弟姐妹们感到悲伤，不过要是没有你的帮助，我们的未来就会惨澹无光了。我们永远欢迎你，$N。', '你除掉扭曲林地的守护者凋叶了吗?', '', '去嚎风峡湾找冰雪林地的鲁莉尔蕾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11429, '不倒的军旗！', '我才不会将这样的任务随便交给那些没经验的小杂兵。$B$B如果你想证明自己具备完成这项任务的实力，就照我说的去做。$B$B带上这面军旗转至正北方的拜尔海姆。我要你将旗帜插在拜尔海姆的中央，并击败前来抢夺旗帜的维库人，维护联盟的尊严！你能做到的话，再回来找我吧！', '嚎风峡湾的约格莫夫·冰锤中尉要你将联盟军旗插在拜尔海姆中央，然后击败前来抢夺旗帜的维库人。$B$B完成任务后将联盟军旗还给他。', '为了联盟!你很强壮，$N。强壮到足以打破尼弗瓦的某个维库人头了。', '我看看，还活着嘛。很明显的你并没有很辛苦。', '保卫联盟军旗', '去嚎风峡湾找约格莫夫·冰锤中尉。', '放置联盟军旗', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11431, '抓住鹿角小飞兔！', '嘿！我是位癫狂的矮人！矮人们相信，当你醉到一定程度的时候，就能看见那些无形的生物。事实上，它们现在就可能在美酒节的营地附近转悠呢！但是你只有在醉酒的状态下才能看见它们。$B$B矮人们从来不会拒绝开怀畅饮的机会。$B$B我敢打赌你一定也想来几杯吧……那么，用这张网替我捕捉5只鹿角小飞兔吧，我是从一位喝得醉醺醺的矮人手中搞到这东西的。$B$B如果你看不见鹿角小飞兔，那就从我这里拿一副合成酿酒护目镜带上，它也能让你像喝醉了一样！', '“矮人”高达克·枪猎要你用鹿角小飞兔网捕捉5只昏迷的鹿角小飞兔。他说，你必须喝得酩酊大醉，或者是戴上合成酿酒护目镜，才有可能看见它们。', '什么!它们真的存在!现在我对猛踢那个矮人的膝盖有点不好意思了…$B$B我需要一分钟…还有一杯酒…$B$B<他又喝了一整杯。>$B$B我猜我可以让你留一只…证明那些喝醉酒的矮人(有没喝醉的矮人吗?)说的是真的。', '你有带东西给我或是你只是需要另一个喝得烂醉的理由?', '', '去找杜隆塔尔的高达克·枪猎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11432, '休眠的巨人', '我听到了你和莱瓦里安神父的谈话。恕我直言，他对你的指导还不够。$B$B你还得去解决那些在亚勒伯龙地下的苏醒之厅中休眠的维库人！$B$B我相信唤醒他们就是毁灭他们的关键。亡灵巫师手中可能有能让这些维库人在未成熟的状态下提前苏醒的东西。$B$B提前苏醒对这些维库人来说必定是非常致命的。', '法师中尉玛利斯特要你杀死5名休眠的维库人。完成任务后返回西部卫戍要塞向他复命。', '你完成了必须的任务。或许有些人会觉得杀死那些无法反抗的人有违荣誉，但在这个情况下，用其它的方法只会说明你是个傻子。$B$B而我们绝对不能坐视他们的仪式完成，对吧?$B$B你在墓窖之中为我们大家所做真的很勇敢，$N。', '$N，我无法相信你解决了那么多的冬眠维库人。等你完成之后再来找我。', '', '去嚎风峡湾找西部卫戍要塞的法师中尉玛利斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11433, '休眠的巨人', '我无意中听到你跟安卡祖母的谈话。恕我直言，她对你的指导还不够。$B$B你还得去解决那些在亚勒伯龙地下的苏醒之厅中休眠的维库人！$B$B我相信唤醒他们就是毁灭他们的关键。亡灵巫师手中可能有能让这些维库人在未成熟的状态下提前苏醒的东西。$B$B提前苏醒对这些维库人来说必定是非常致命的。', '安霍塔·白霜要你杀死5名休眠的维库人。完成任务后返回冬蹄营地向他复命。', '你完成了必须的任务。那些愚昧的人或许会觉得杀死那些无法反抗的人有违荣誉，但在这个情况下，用其它的方法只会说明你是个傻子。$B$B而我们绝对不能坐视他们的仪式完成，对吧?$B$B你在墓窖之中为我们大家所做真的很勇敢，$r。', '我不太相信你解决了那么多的冬眠维库人。等你完成之后再来找我。', '', '去嚎风峡湾找冬蹄营地的安霍塔·白霜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11434, '被遗忘的宝藏', '我的巨额财富来自我对那些一般海盗不感兴趣的财宝的眼光，比如绘画、古董、收藏品之类的。$B$B多年前，康拉德的船队沉没在这里的南方。所有的金币和珠宝都已经被人捞走了，但那里还留着两件古董。一件是殿堂级的阿曼尼花瓶，另一件是一座雄鹰雕像。$B$B把这两件古董给我带来，我会向其它海盗担保你。另外，我还会给你一些小玩意，让你的水下作业更加轻松。', '无赖港的帅哥泰里要求你到南方的沉船上找到一只阿曼尼花瓶和一座雄鹰雕像，并把它们交给他。', '我们应该要结伴游历，$N。靠着我的帅气和你的…能干，我们一定能大赚一票。', '你有拿到我的圣物吗，$N?没人能靠长得帅过一辈子…就算是我也不行!', '', '去嚎风峡湾找无赖港的帅哥泰里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11436, '冲浪去！', '飞越嚎风峡湾的陡峭悬崖一直是个大难题！而我在结合维库人的技术和矮人的心灵手巧以后，终于想出了解决办法。通过改装和仔细调整，我制造出了冰锤牌鱼叉控制器！当然这个产品还没有测试过，但这难道不就是我叫你来的意义所在吗？$B$B拿着这个控制器去找到尼弗莱瓦的大炮，然后用它把你自己发射到瓦加德去。把你的好消息告诉索雷克。哦，当然了，你可以留下那个控制器。', '使用尼弗莱瓦的大型维库鱼叉炮把你自己发射到瓦加德去。向守卫队长索雷克报告你战胜维库人的消息。', '你真是疯了，$N!哪种智障会把鱼叉猎枪当成交通工具啊?$B$B但是我想只有像你这样的疯子才能做出悬崖上的壮举!精彩万分!我们听说掠龙的老大因格瓦快气炸了!也许有一天你会有机会把他的脸踩进烂泥巴里 -', '<索芮克瞠目结舌地看着你。>', '完成鱼叉冲浪', '去嚎风峡湾找瓦加德的守卫队长索雷克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11439, '消防练习', '卡拉诺斯最勇敢的矮人们已经组建了一支消防队，随时准备抵御无头骑士的进攻。你想帮忙吗？$B$B巡山人在这里的南边设立了一处练习场，训练大家的灭火技术。你也到那里去练习吧，用小水桶把水泼到火盆上。小水桶在水缸周围放了许多，你可以自由取用。$B$B再见，$N。你完成了消防队的练习之后，请再过来找我们！', '将小水桶里的水倒在5处火盆上，然后与穿戏服的孤儿院长谈一谈。', '你身上全给烟灰弄脏了!你想必已经扑灭了那些火焰!$B$B干得好!身为一个救火队的荣誉成员，我请求你在村庄需要你的时候回来帮助我们!', '你好，$N。你是否磨练了你的救火技巧了呢?别忘了演练区就在南边!', '', '去丹莫罗找卡拉诺斯的穿戏服的孤儿院长。', '灭火', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11440, '消防练习', '在无头骑士的威胁之下，秘蓝岗哨的英雄们随时都准备着组成消防队，扑灭这里的火势。你愿意加入我们吗？$B$B就在这里西边不远，卫兵们已经创建了一处小营地以便练习救火。你也到那里去练习吧，用小水桶把水泼到火盆上就是了。小水桶在水缸周围放了许多，你可以自由取用。$B$B再见，$N。你完成了消防队的练习之后，请再过来找我们！', '将小水桶里的水倒在5处火盆上，然后与穿戏服的孤儿院长谈一谈。', '你身上全给烟灰弄脏了!你想必已经扑灭了那些火焰!$B$B干得好!身为一个救火队的荣誉成员，我请求你在村庄需要你的时候回来帮助我们!', '你好，$N。你是否磨练了你的救火技巧了呢?别忘了演练区就在南边!', '', '去秘蓝岛找碧蓝岗哨的穿戏服的孤儿院长。', '灭火', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11443, '匕鞘湾潜水行动', '嘿……呃……你有什么事？你下来干什么？$B$B我？噢……那个，你瞧……我是……嗯……我是来清理这个地方的！凯勒亲口向我下的命令！他对我说：“哈洛德，我要你戴上潜水钟去搜索匕鞘湾里的船只残骸，找到我们的东西……”$B$B你看，既然你已经来了，帮我点忙怎么样？海湾里散落着各种宝……呃，我是说补给品。去帮我找一些回来，什么都可以。戴上这个潜水头盔，这样你就不会窒息了。', '匕鞘湾海底的哈洛德·拉格拉斯要你打捞10只瓦加德补给箱。', '哇!你的效率可真高。对嗯，把这些木箱交给我就对了。我需要把他们登记列单，还有一些你没受过训练也不会懂的事情。别担心，我一定会让凯勒你知道你在这里的丰功伟业!对对对，你可以走了。快溜!', '你找到任何补给品吗?', '', '去嚎风峡湾找匕鞘湾的哈洛德·拉格拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11448, '探险者协会哨站', '全是一些无法解读的神秘文字！就算是有这份密码表，我也完全搞不出任何头绪来。必须得承认，解译密码完全不是我的强项。$B$B你带上这些密码表和石板立刻去找我们的密码破译员斯坦瓦德，请求他的帮助吧。不过糟糕的是，我两周没和斯坦瓦德联系上了。他前几天和二十多个科学家一起去了峡湾东南边一处峭壁上的挖掘站，自那以后就一直没他的消息。我想，最好的办法就是让米克高维尔用飞行器带你过去，省时省力。', '将米科索夫的包裹送给嚎风峡湾探险者协会哨站的斯坦瓦德。', '<史坦华从你手中接过包裹然后开始把资料分类。>$B$B哇，你说为了拿到这份资料死了多少人?$B$B<史坦华摇摇头。>$B$B你应该要觉得高兴，麦克索夫和那群低能手下发现的是冻原中的一份古老文件。他没有提到一般蔬菜的图案，或是那些人嘴大嚼蔬菜的象形文字?你根本不需要那些该死的密码就能破解这些编码!', '<史坦华嘟哝着。>', '', '去找嚎风峡湾的斯坦瓦德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11449, '灭火练习', '卫兵们在镇外不远的地方设立了一处消防练习点。我们绝对不能让布瑞尔的建筑物处在火灾的威胁之下。你也应该去参加练习，成为一名消防员！$B$B从西门经过墓地，然后一直沿路走，就能找到训练营。到那里拿个水桶就赶紧开始练习灭火吧！', '将小水桶里的水倒在5处火盆上，然后回到布瑞尔，与戴面具的孤儿院长谈一谈。', '做得好，$N。孩子们，好好地看看这位$C。让$g他:她;成为你们茁壮的榜样。', '你有扑灭过火焰吗，$N?演练区就在布瑞尔的西边。', '', '去提瑞斯法林地的布瑞尔找戴面具的孤儿院长。', '灭火', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11450, '灭火练习', '卫兵们在镇外不远的地方设立了一处消防练习点。我们绝对不能让无头骑士摧毁我们耗费了如此巨大的代价才重建起来的建筑物。你也应该去参加练习，成为一名消防员！$B$B从南边出门，然后走到十字路口，就能找到训练营了。', '将小水桶里的水倒在5处火盆上，然后回到鹰翼广场，与戴面具的孤儿院长谈一谈。', '做得好，$N。孩子们，好好地看看这位$C。让$g他:她;成为你们学习的榜样。', '你有扑灭过火焰吗，$N?演练区就在猎鹰之翼广场的南边。', '', '去永歌森林的鹰翼广场找戴面具的孤儿院长。', '灭火', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11451, '奥利卡的诗', '嗨，我给我的朋友凯莉写了一首诗。她喜欢待在沙塔斯城的奥尔多区域，沙塔斯城，外域，你知道的吧？$B$B你能帮我把这首诗转交给她吗？我妈妈说我年纪还太小，去不了沙塔斯城！', '将奥利卡的诗交给外域沙塔斯城中的凯莉·达克。', '多动人的一首诗，感谢你!', '噢，这是一首诗?', '', '去找沙塔斯城的凯莉·达克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11452, '沉睡的国王', '死去的首领手中握着一卷羊皮纸，你从中辨认出了下面墓穴里正在举行的仪式场景。$B$B但维库人的王后安格博达女王似乎在唤醒伊米隆国王时遇到了困难。仪式就在亚勒伯龙最北端的寒冬大厅中举行。$B$B如果你动作够快，或许还来得及阻止她。', '击败安格博达女王并阻止唤醒伊米隆国王的仪式。完成任务后，回到西部卫戍要塞向亚当斯上尉复命。', '我不确定自己是不是高兴听到这个!巫妖王放过依米伦只表示一件事:麻烦。可惜你没办法把他们夫妻一起杀死。$B$B但你终究为我们争取了宝贵的时间。$B$B谁知道呢，或许透过你的方法，你有机会再次遇见依米伦王。不过我相信下次他只会更难缠。', '$N，你带了什么消息来?', '', '去嚎风峡湾找西部卫戍要塞的亚当斯上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11453, '沉睡的国王', '死去的首领手中握着一卷羊皮纸，你从中辨认出了下面墓穴里正在举行的仪式场景。$B$B但维库人的王后安格博达女王似乎在唤醒伊米隆国王时遇到了困难。仪式就在亚勒伯龙最北端的寒冬大厅中举行。$B$B如果你动作够快，或许还来得及阻止她。', '击败安格博达女王并阻止唤醒伊米隆国王的仪式。完成任务后，回到冬蹄营地向灰烬图腾酋长复命。', '我不确定自己是不是高兴听到这个!巫妖王放过依米伦只表示一件事:麻烦。可惜你没办法把他们夫妻一起杀死。$B$B但你终究为我们争取了宝贵的时间。$B$B谁知道呢，或许透过你的方法，你有机会再次遇见依米伦王。不过我相信下次他只会更难缠。', '$N，你带了什么消息来?', '', '去嚎风峡湾找冬蹄营地的灰烬图腾酋长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11455, '金币的芳香', '我们海盗有许多出名的特征，但卫生从来都不是其中一项。大多数海盗船上的老鼠都是船员数量的五到六倍。$B$B难怪我们搬到这里以后，岛上的熊都感染上了疫病。总之，上头要我们杀光这些熊。$B$B我刚巧听说有一种熊麝香在暴风城的贵族中很流行。我们可以杀死这些熊，然后把麝香卖掉。我已经预见到了巨大的商机！你还有什么想法吗？', '无赖港里的帅哥泰里要你从附近的狂暴棕熊身上收集4份熊麝香。', '干得好!或许这没像在公海劫掠那么大胆，不过如果我错失了这个机会，那么我就是个该死的甲板清理员之子。', '你有野熊麝香要给我吗，伙伴?', '', '去嚎风峡湾找无赖港的帅哥泰里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11456, '难民的食物', '我们海象人以鱼为主食。但在食物短缺的时候，我们偶尔也会捕猎陆地上的动物。$B$B附近的伊斯卡尔村最近被海盗袭击了，难民不断涌到我们这里来。$B$B这周我们在海上的收获并不多，但这岛上有许多铲齿鹿，它们的肉又肥又多。$B$B为了帮助我的同胞，请你去捕猎这些巨大的动物，把它们的肉带给我。', '卡玛古的长者阿图伊克要你转至长矛岛，从长矛岛铲齿鹿身上收集6份长矛岛铲齿鹿肉。', '感谢你，$N。我的同胞正处在一个迫切需要的时期。', '你拿到了我们需要的肉吗?', '', '去嚎风峡湾找卡玛古的长者阿图伊克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11457, '卡玛古的武装', '战争之神伊斯利鲁克，在我们的部族中被描绘成一头银色的雄鹰。部落里一直流传着伊斯利鲁克打败了一百头座狼、拯救了它的孩子的传说。$B$B现在，我们也要为拯救自己的族人而战斗了。首先，我们要制作新的武器。在这座小岛的雪原上生活的霜翼奇美拉的犄角非常锋利，可以制成很好的矛头。请你帮我带一些最好的角回来。', '长者阿图伊克要你去收集3根奇美拉角。', '你再度证明了你身为盟友的价值，$N。你的义行将永远不会被忘记。', '很高兴能再次看到你，$r。', '', '去嚎风峡湾找卡玛古的长者阿图伊克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11458, '伊斯卡尔的复仇', '伊斯利鲁克的图腾已经准备好了，$N，我要谢谢你。我们必须暂时抛弃平静的生活，打击那些侵犯我们领地的敌人。$B$B那些攻击伊斯卡尔的海盗已经失去了理智，他们杀死了所有的俘虏。到东方的伊斯卡尔去做你该做的事吧。带上这只号角，当你需要我们的帮助时，就吹响它。', '长者阿图伊克要你转至伊斯卡尔，消灭8个疯狂的北海奴隶贩子。如果你需要帮助，可以吹响卡玛古号角。', '你是个非常杰出的盟友，$N。我的族人将永远欠你一份人情。', '你把我要求的事情做好了吗，$N?', '', '去嚎风峡湾找卡玛古的长者阿图伊克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11460, '获得信任', '猎鹰训练术的关键在于训鹰者与猎鹰之间的关系。你必须赢得它们的信任！$B$B<希达尔格指着他脚边笼子里的猎鹰。>$B$B首先，你要通过喂食来博得这些动物的信任。$B$B这种名叫岩石猎鹰的鸟类以幼虫为食，而这片稀松的岩地正是峡湾幼虫的温床。我要你用幼虫来喂养笼子里的猎鹰。', '嚎风峡湾探险者协会哨站的希达尔格要你用一只峡湾幼虫喂养关在他脚边笼子里的猎鹰。', '很好，$N。我可以感觉到伙伴的关系正在形成。她开始接受你为主人。', '这是个很重要的经验，$N。如果你想成为一个驯鹰者，你要学会如何喂饱你的鸟儿。', '给岩石猎鹰喂食', '去嚎风峡湾找探险者协会哨站的驯鹰大师希达尔格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11464, '赌债', '我听说你为泰里做了点事。我一直期待能有个可靠的人出现这附近。$B$B你瞧，海盗们喜欢赌博，却不喜欢支付他们的赌债。$B$B如果你愿意作为我的代表来帮我收账的话，我会很乐意给你一点提成的。$B$B先从简单的开始吧，“银月”哈瑞是个有点偏执的家伙，在他的帐篷里藏着各种昂贵的血精灵玩意——然而我每次看到他时，他总是装出一幅身无分文的样子。帮我把钱拿回来。', '无赖港的塔鲁克希望你帮他讨回“银月”哈瑞的赌债。', '很漂亮的一件工作。这是你的那一份，$N。我还有很多欠款待讨。$B$B这座岛上永远都不缺赖债的海贼。', '你回来啦。你拿到他欠我的钱了吗?', '', '去嚎风峡湾找无赖港的塔鲁克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11465, '被袭击的车队', '我率领一支商队从瓦加德出发，路过这里时遭到了掠龙氏族的袭击，我竟然是唯一的幸存者。混乱中，一车峡湾火鸡也不见了。这正是你训练岩石猎鹰的大好机会呀。$B$B<希达尔格将笼子递给你。>$B$B带上这只猎鹰笼，沿着营地西边的道路一直走。利用猎鹰捕获走失的火鸡，完成任务后回来向我复命。$B$B记得要喂养猎鹰！', '嚎风峡湾探险者协会哨站的希达尔格要你利用训练过的岩石猎鹰捕捉5只峡湾火鸡。$B$B完成任务后将笼子交给希达尔格。', '有耐心又聪明的混蛋!我们不能再继续低估我们的敌人。这些维库人是致命的狩猎者!$B$B毫不停歇直到任务完成。也许这是时候让你猎一些更困难的猎物，而不是一些肥胖的火鸡，对吧?', '你必须要持续喂食你的隼鹰，否则它就会把猎物给吃了。', '', '去嚎风峡湾找探险者协会哨站的驯鹰大师希达尔格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11466, '嗜酒的杰克', '我们的下一个顾客，杰克·亚当，并不像哈瑞那样好对付。他整天都在和他那群强壮的海盗朋友们一起喝酒。这次我们不要使用武力，因为使用武力的话对你来说结局会很悲惨。$B$B看看你是不是可以利用他嗜酒的习性，因为他只能喝一丁点。$B$B也许某个酒吧女郎能助你一臂之力。等他出门以后，看看你是否有机会把你的手滑到他的口袋里，帮我取回我的那份。', '无赖港的塔鲁克希望你帮他讨回杰克·亚当的赌债。', '你让我印象深刻，$N。我可不是那种随便称赞别人的人。', '你拿到属于我的东西了吗，$N?', '', '去嚎风峡湾找无赖港的塔鲁克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11467, '死人的债务', '你可能听说过康纳德，他是这一地区有名的海盗。$B$B呃，他跟我赌过一把，当然他也没有付赌债。$B$B我很想把钱收回来，但问题是……他已经死了。$B$B我几乎准备要把他的欠债都给一笔勾销了，结果我发现了这个……$B$B<塔鲁克展开一张长矛岛的地图，你发现东北方的高原区域画着一把大叉。>$B$B他把他的财宝藏在了海象人的土地上，我希望你能帮我把它拿回来。要是我让那个混账就这么没还清赌债就走了，我就活该下地狱。', '无赖港的塔鲁克要你转至伊斯卡尔以北的长矛岛，在该岛的东北尽头寻找康纳德的宝藏。', '我要拿走黄金，这是康拉德欠我的。剩下你可以留着。$B$B如果你需要一点更持久的东西，我敢保证我能替你安排一些。愿你的航行风吹不息，朋友。', '你找到宝藏了吗，$N?', '', '去嚎风峡湾找无赖港的塔鲁克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11468, '鹰隼之战', '$N，你能感受到自己与猎鹰之间的亲密关系吗？你们被一条看不见的纽带连接起来了。如果我说一旦时机成熟，你就能拥有鹰眼的视野，你相信吗？真的，那是猎鹰训练术的最高境界。$B$B但是首先，你还要接受更多的狩猎训练！你必须将这只猎鹰训练成反应敏锐的猛禽。让它去对付更可怕的敌人！峡湾隼就栖息在这四周的树梢上，它们就是你的下一个目标！', '嚎风峡湾探险者协会哨站的希达尔格要你利用训练过的岩石猎鹰捕捉10只峡湾隼。$B$B完成任务后将笼子交给希达尔格。', '哎，隼鹰的地域性很强，且常常成群结队的旅行。我想我应该在派你出发前就先告诉你的。', '你必须持续喂食你的猎鹰，否则它就会把你要它捕抓的猎物给杀了。', '', '去嚎风峡湾找探险者协会哨站的驯鹰大师希达尔格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11469, '制作肥皂的原料', '你瞧，我要赶在疯子乔纳斯回来之前将码头打扫干净。但我不能用手去擦地板！$B$B我们的肥皂用光了。伙计，你新来的吧？很好，这件事就交给你来搞定。$B$B西北边的海岸上生活着一大票的海狮，它们的首领大个子罗伊就在浮冰旁嬉戏呢。把它的油脂带回来给我，我就能制作出最上等的肥皂！', '斯卡特·弗洛斯普要你取回制作魔法肥皂的主要原料——大个子罗伊的脂肪。完成任务后返回无赖港东边的海盗船向她复命。', '恶，我从来没闻过这么臭的东西!$B$B过来，把东西放在这里。让我来施法，它就会变成清洁肥皂!', '油脂在哪里?别告诉我他身上什么都没有。$B$B大罗伊该死地胖成那样，他还会动真是个奇迹!', '', '去嚎风峡湾找无赖港的斯卡特·弗洛斯普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11470, '鸟类可不管什么荣耀！', '$N，你是不是迫不及待地想要接受猎鹰训练术的下一课程了？$B$B带上猎鹰，转至东边的石墙升降梯附近的维库人猎鹰栖木，让它偷取峡湾隼的卵。峡湾隼将巢穴搭建在栖木四周的峭壁上，一旦你发现了它们的巢穴，就派猎鹰去偷蛋！$B$B$N，当心那些雌性峡湾隼。如果你遭到攻击，就利用猎鹰的逃脱和飞翔技能逃命吧！', '嚎风峡湾探险者协会哨站的希达尔格要你利用训练过的岩石猎鹰偷取8枚峡湾隼的卵。$B$B完成任务后将笼子交给希达尔格。', '太棒了，$N!太棒了!你和你的石隼之间那种亲蜜的联结很强烈!或许你在不远的将来能够执行一些勘察维库的任务?', '你现在已经掌握绝窍了，$N。带领你的石隼并将那些蛋带来给我。', '', '去嚎风峡湾找探险者协会哨站的驯鹰大师希达尔格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11471, '取而代之', '我知道你来这里的目的，$N。他们派你来杀死我们的首领，约纳·斯特林。$B$B我愿意帮助你——约纳的领导已经快把我们全毁了。$B$B同时攻击部落和联盟的舰队？那就是自杀！明知道海象人离开这里的气候环境就会在几天内死去还把他们当奴隶卖掉？真是灾难！$B$B约纳就藏在西边的洞穴里，把他的望远镜给我带来。我一当上首领，就会立即下令停止攻击你的盟友。', '无赖港的安妮·波恩要你把“疯狗”约纳·斯特林的望远镜交给她。', '乔纳.斯德林也会有这一天啊!他做梦也都想不到这个“村姑”做得到!$B$B等到乔纳的死这件事在海贼当中传遍时，我将会巩固我的领导权。你的盟友们将不会受到我手下的干扰，$N。', '如何，$N。你拿到乔纳的头颅了吗?$B$B我不太可能单凭你的话说你成功了，懂吗?毕竟我是个海贼。', '', '去嚎风峡湾找无赖港的安妮·波恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11475, '必需的工具', '我研究这台没启动的构造体有好几天了，$N。我认为我也能仿造出一台跟这台一样的、超级完美的、令人着魔的构造体出来，对，里面还能坐进去一个人。靠这玩意，我们就能轻而易举地骗过那些白痴铁矮人，光明正大地混进巴尔古挖掘场里面去啦。$B$B不过，我现在手里只有铁锤和烙铁，这样可什么都干不了。我需要我的工具！那群铁矮人出现的时候，我吓得扭头就跑，结果把工具丢在伊瓦尔德废墟里了。帮我取回来！$B$B伊瓦尔德废墟就在东北不远的地方。', '嚎风峡湾探险者协会哨站的沃尔特要求你取回他的建造工具。', '现在我拿到了我的工具，可以开始动工了。喔，只要我有材料的话。你接下来要帮我取得那些材料。', '步骤1:替渥特取得他的工具。', '', '去嚎风峡湾找探险者协会哨站的沃尔特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11476, '呱呱叫的和刮东西的', '海盗嘛……有一套自己的黑话。塞吉的说话方式……有点特别……反正是一团糟。$B$B就我的理解，他想要一只青蛙和一把小刀。$B$B“银月”哈瑞正好有一把小刀。你瞧，镇子里到处都是青蛙。随便抓一只来，将青蛙和小刀交给他就好啦。$B$B我真不敢想象这只可怜的小家伙的下场，你明白我的意思吧？', '向“银月”哈瑞要一把闪亮的小刀，并抓一只无赖蛙。把它们交给无赖港的塞吉。', '感激感激，阿呆。呱呱看起来真会叫!', '你拿到切切和呱呱了吗，老兄?', '', '去嚎风峡湾找无赖港的塞吉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11478, '远方的哨站', '大概你还没有去南边的探险者协会哨站拜访过我的弟弟斯坦瓦德吧。不如你就帮东尼一个忙，把这封信交给他，如何？他一定会对这边铁矮人的活动很感兴趣的。$B$B一路向南走，在进入巴尔古挖掘场之前，你就会在路的右边看见他们的哨站。', '将东尼的信交给探险者协会哨站的斯坦瓦德。', '没错，这并不是我们所不知道的事情。至少多尼还活着。', '来自多尼的消息?', '', '去找嚎风峡湾的斯坦瓦德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11483, '我们可以重建它', '工具？有了。材料？没有。$B$B要想把这东西造出来，没材料可不行，这事就拜托你了。$B$B首先，我是说首先，$N，要构造基本的骨架，我需要尼弗莱瓦那边的大桶，还有瓦加德那边的黑铁条，再从拜尔海姆搞来一根高强度绳索。$B$B尼弗莱瓦和拜尔海姆都是维库人的镇子，在西北方。瓦加德就在匕鞘湾里，也在西北边，到那里以后，你可以去找米克高维尔要黑铁条。等你收集到了所有材料以后，米克高维尔还可以开飞机把你送回这里来。', '嚎风峡湾探险者协会哨站的沃尔特要你带回一只大桶、一根高强度绳索和一些黑铁条。', '太好了。结合这些东西再加上一层外皮，就可以做出一个完美的铁矮人傀儡复制品。', '你拿到了那些基本材料了吗?', '', '去嚎风峡湾找探险者协会哨站的沃尔特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11484, '我们有技术', '固然对一台机械来说，内部的骨架非常重要，但我们也不能就此忽视它的外表。尤其是它得跟那些铁矮人造出来的一模一样才行，如果我们还想糊弄过关的话！$B$B这一点对我来说完全不算什么。$B$B你只需要给我带回来一张本地区的天然铲齿鹿皮和一些钢质棱条就行了，当然，你得到西北方的尼弗莱瓦或是拜尔海姆，去跟那里的维库人“借”一些钢质棱条来……', '嚎风峡湾探险者协会哨站的沃尔特要你带回一张天然铲齿鹿皮和一根钢质棱条。', '我几乎已经完成了整个傀儡，只等基本结构完成。', '我们将会尽高速缓冲回我们圣物!', '', '去嚎风峡湾找探险者协会哨站的沃尔特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11485, '铁符文构造体与你：火箭跳', '好了，$N，接下来，是时候让你爬进这东西里面试试基本操作了，不了解它的各项能力可不行。你准备好以后，就坐上驾驶座，我会把你放进构造体里去的。$B$B你要学的第一课是如何使用这台构造体的移动系统。你应该已经注意到了，那些铁矮人在挖掘站周围设置了许多特殊的符文石碑，他们的构造体可以从那些石碑里抽取能量，然后在各个点上飞来飞去。来，用这个符文雕像试试看，这是我之前仿造的。', '嚎风峡湾探险者协会哨站的沃尔特要你在沃尔特的铁符文雕像上使用铁符文构造体的火箭助推技能。$B$B完成任务，你可以在宠物选项菜单中点击解散宠物来解散构造体。', '你几乎已经可以将这个艺术品开进原野操作了，$N!', '别对这些反对者多费唇舌!', '掌握火箭跳功能', '去嚎风峡湾找探险者协会哨站的沃尔特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11486, '美酒中的美酒', '我知道像你这样的$G小子:姑娘;最喜欢阻止冲突了，对吧？你想要让你们的美酒节平平安安地办完，不要出乱子。那么我有一个提议……$B$B在这只酒杯中装满我们最棒的烈酒，然后把它交给铁炉堡外的美酒节组织者，这样我们黑铁矮人也算是参加了这个节日！全艾泽拉斯最棒的烈酒来自这里！黑石山的深处！不要忘了这一点！', '将黑铁啤酒杯交给丹莫罗的埃菲库格·铁桶。', '所以你去找了黑铁矮人，以为可以阻止他们的破坏?他们不久前才又发动一次攻击。看来黑铁的承诺就跟他们的啤酒一样可靠，嗯?$B$B不过你还是帮了忙。这是一杯你从山里头带出来的“麦芽酒”，就当成是报酬吧。打败那些黑铁矮人想必也让你渴了!', '这是什么?', '', '去找丹莫罗的埃菲库格·铁桶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11487, '美酒中的美酒', '我知道像你这样的$G小子:姑娘;最喜欢阻止冲突了，对吧？你想要让你们的美酒节平平安安地办完，不要出乱子。那么我有一个提议……$B$B在这只酒杯中装满我们最棒的烈酒，然后把它交给奥格瑞玛外的美酒节组织者，这样我们黑铁矮人也算是参加了这个节日！全艾泽拉斯最棒的烈酒来自这里！黑石山的深处！不要忘了这一点！', '将黑铁啤酒杯交给杜隆塔尔的塔波尔·斯威雷格。', '所以你去找了黑铁矮人，以为可以阻止他们的破坏?他们不久前才又发动一次攻击。看来黑铁的承诺就跟他们的啤酒一样可靠，嗯?$B$B不过我猜想你还是帮了忙。这是一杯你从山里头带出来的“麦芽酒”，就当成是报酬吧。别推辞，这起码是我能做的。', '你拿来的是什么?', '', '去找杜隆塔尔的塔波尔·斯威雷格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11488, '魔导师平台', '欢迎来到太阳之井，$c。你最好尽快习惯这里的事态，并且随时准备贡献自己的一切力量……要知道，这里太需要你的贡献了！$b$b我？对，我这里确实有些事情需要别人帮忙处理，不过我还不清楚你是否已经准备好了。$b$b我们有一位线人当前正潜伏在魔导师平台内，为我们收集情报。但是这几天以来我们一直没有收到他的报告，我对此非常担心。$b$b魔导师平台就在东边那块高地之上。他给我们提供的情报非常重要。$b$b你能帮我们处理这件事吗，$r？', '破碎残阳基地的主教拉雷索尔要求你转至魔导师平台，寻找血精灵间谍塔雷斯的踪迹。', '…靠近点，$r…仔细听我接下来的话……', '你到我们失踪的间谍了吗，$r?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11490, '占星球', '<塔雷斯一边呻吟着一边说话。>$b$b去……去平台上，使用那颗宝珠。$b$b……他们将能量都灌入了太阳之井……$b$b<塔雷斯猛喘了一大口气。>$b$b快点……必须马上阻止他们……不要等到他们……$b$b<塔雷斯咽下了最后一口气。>', '塔雷斯要求你使用魔导师平台内的阳台上的宝珠。', '我认为我们今天的交会并非巧合。$B$B我可以感应到命运的交缠……', '去仔细地看看宝珠，凡人。', '', '去找魔导师平台的卡雷苟斯。', '激活占卜宝珠', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11491, '铁符文构造体与你：唬骗', '朋友，出来做事呢，没有后备计划是不行的，尤其是在你的主要计划出岔子的时候！这就是我为什么要在这台构造体里安一台反智慧生物系统的原因。$B$B你那菜到不能行的操作一定会在巴尔古挖掘场里引起敌人的怀疑，这时候你就要用到这套唬骗系统了！简单来说，就是当你被任何铁矮人盯上的时候，就使用这套系统，之后就是全自动操作，保证你不会有事。$B$B你可以拿雷波斯基测试一下，去踩他的地毯。只要他一开始骂你，就马上使用唬骗系统！$B$B来，坐上驾驶座，我们现在就开始。', '嚎风峡湾探险者协会哨站的沃尔特要你在走过雷波斯基的地毯时使用铁符文构造体的唬骗技能。$B$B完成任务，你可以在宠物选项菜单中点击解散宠物来解散构造体。', '你证明给他看了!该是让你正式上场了。$B$B要有信心，我希望啦……', '不用担心他，$N。他会撑过去的……', '唬骗雷波斯基', '去嚎风峡湾找探险者协会哨站的沃尔特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11492, '大难不死', '欢迎来到太阳之井，凡人。你来的正是时候。$b$b你应当也已经看到了，现在燃烧军团正夜以继日地将太阳之井内的强大能量运用于他们那些邪恶而卑贱的目的。$b$b凯尔萨斯也重新站了起来，并继续领导和统筹着他的部队配合燃烧军团。我们必须再一次阻止他。$b$b但是，现在有一件更加紧急和复杂的事情等着我去处理，凯尔萨斯的命运恐怕必须交给你来完结了。千万不要让我失望。$b$b祝你好运，我们很快还会再见面的。', '卡雷苟斯要求你击败魔导师平台内的凯尔萨斯。取下凯尔萨斯的徽记之后，立刻向破碎残阳基地的主教拉雷索尔复命。', '<雷索尔专心地听着你在魔导师平台的壮举。>$B$B提里斯将被怀念 - 他是个好人。感谢你，好让他的死不会白费。$B$B我低估你了，$r。请你接受这样礼物，来表扬你对太阳之井进攻部队的贡献 - 像你这样的英雄才值得的礼物。', '很好，$C，我必须承认，我不确定我会再遇见你。$B$B你带来了什么消息吗?', '', '去找奎尔丹纳斯岛的主教拉雷索尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11495, '轰鸣的雷霆', '我们在巴尔古挖掘场挖开的那个洞穴……许多人见了都是绕着走的……我倒也不怪他们胆小。那个洞穴里一直发出雷鸣一般的声音，$N！轰鸣的雷声！$B$B而且你要知道，所有进去探索过的人都遭遇了不幸！好多人甚至再也没回来过。于是到最后，就没有任何人敢进去那里了。$B$B不过，既然你要去巴尔古挖掘场，不如帮我们去查看一下那个洞穴吧。仔细研究一下那里面的泰坦雕塑，然后把你了解到的东西告诉我。', '嚎风峡湾探险者协会哨站的沃尔特要你使用铁符文构造体仔细探索巴尔古挖掘场内的雷霆洞穴。$B$B完成任务，你可以在宠物选项菜单中点击解散宠物来解散构造体。', '不可思议!这些铁矮人讨厌鬼到底想干嘛?他们在风暴峭壁做什么?这个洛肯又是什么东西!?我要把这些情报送去给我们在龙骨荒野的中央基地，$N。我也会告诉他们你在获取这些资讯的过程中扮演了无可取代的角色。', '运气如何?', '调查雷霆洞穴', '去嚎风峡湾找探险者协会哨站的沃尔特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11496, '圣殿的结界', '我们的首要任务是占领阳湾圣殿。只要控制了它，我们就能利用它的能量，开启一道从沙塔斯城到这里来的传送门。$B$B圣殿周围现在到处都是失心者——退化成脑残形态的血精灵。通常来说，它的防御设施应该能够阻止敌人的入侵，但失心者把防护结界的能量源给偷走了。$B$B消灭那些失心者，从他们手上的夺回法力馀烬，用它们重新激活圣殿的防护结界。', '破碎残阳基地的瑟里斯·黎明之心希望你能从失心魔瘾者和失心吞噬者那里获取4份法力馀烬，用它们激活东边的阳湾圣殿周围的水晶结界。', '做得好，$N。结界正在慢慢恢复它的能量。圣所很快就是我们的了!', '你重新启动了水晶结界吗，$N?', '激活水晶结界', '去奎尔丹纳斯岛的破碎残阳基地找瑟里斯·黎明之心。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11499, '悬赏：凯尔萨斯王子的徽记之戒', '$C，今天我要让你执行一件几乎不可能完成的任务。今天，你必须得到血精灵之王凯尔萨斯的徽记之戒。$B$B没错，这是真的，有谣言说他其实没有死在风暴要塞，而是被某些邪恶的手段救活了回来。他上一次再度出现是在奎尔丹纳斯岛上的魔导师平台。至于他在那里做些什么，就让别人来告诉你吧。反正我只知道有无数的收藏家在询问我要多少钱才能买到他的戒指，所以我决定先把戒指搞到手再说。$B$B或者说，我决定让你先帮我把戒指搞到手再说。', '商人扎雷姆要求你夺得凯尔萨斯王子的徽记之戒。将戒指带回沙塔斯城的贫民窟交给他，就能领取奖赏。$B$B该任务只能在英雄模式的魔导师平台完成。', '所以，血精灵王子这次真的死了?真可惜，我一直觉得他挺有格调的。想到一个那么高傲的人却得为这么琐碎的小钱而死。$B$B不过就如大家讲的，在商言商。你赢得了你的酬劳，冒险者。$B$B明天再来找我，我还有别的任务要托付给你。', '这么靠近太阳之井，魔导师平台一定是个非常危险的地方。$B$B我相信你应该不会为此而迟疑?', '', '去找泰罗卡森林的商人扎雷姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11500, '悬赏：痛苦妖女', '玛哈杜恩再一次收到了风带来的消息，我们要把痛苦妖女送回地狱之中。$B$B玛哈杜恩知道，这些恶魔就在奎尔丹纳斯岛上的魔导师平台里面。$B$B除掉她们，你就能得到赏金，否则，你就得不到。', '虚空猎手玛哈杜恩要求你杀死4名痛苦妖女。完成任务后返回沙塔斯城的贫民窟，向他领取奖赏。', '谁能说那些恶魔之女需要被杀死呢?你在意吗?$B$B玛顿恩认为你只在意赏金罢了。$B$B明天再回来找我吧，风将会再次对玛顿恩细诉。', '它透过虚空的风对玛顿恩诉说。它说你尚未处理完那些女性。$B$B$N一点也不在意赏金吗?', '', '去找泰罗卡森林的虚空猎手玛哈杜恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11502, '保卫哈兰', '我们不是一个好战的种族，$r。尽管如此，当战争真正蔓延到我们的土地上时，我们绝对不会怯战逃跑。$B$B联盟与部落在西北方的哈兰一带进行着激烈的冲突。我们当前还不清楚那些血精灵到底在图谋什么，但我们知道，一旦让部落获得胜利，结果将是灾难性的。毫无疑问，我们与兽人之间的历史充满了鲜血淋漓的背叛与征战。$B$B立刻转至哈兰，杀光那里的全部敌人，你会得到象征着声望与荣誉的徽记作为奖励。', '在哈兰击败10名敌对方玩家，然后向塔拉的拉库尔复命。', '感谢你，$N。你的贡献不会被忽略的。', '你完成任务了吗，$N?', '', '去纳格兰找塔拉的拉库尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11503, '新仇旧怨', '我们的宿敌德莱尼人带着无数强大的盟友回来了。现在他们在西南方的哈兰挑起了战争。$B$B我们无法容忍他们取得胜利，否则加拉达尔肯定会陷入危险之中。$B$B立刻到那里去，干掉那些帮助我们宿敌的人。', '在哈兰击败10名敌对方玩家，然后向加拉达尔的卡尔托格复命。', '你替我们的同胞带来了莫大的光荣。我们感谢你。', '你完成任务了吗，$N?', '', '去纳格兰找加拉达尔的卡尔托格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11504, '亡者复生！', '我们东面的那条小路通往海象人的主要狩猎地。至少是以前的主要狩猎地……$B$B最近以来，我们的猎人回到卡玛古后，声称那里到处充斥着亡灵，残害着周围的生物！那也就是我和我的儿子来这里的原因。长者阿图伊克希望我们能找到答案。$B$B你能在我们需要的时候助我们一臂之力吗？我在寻找愿意去盾牌岭冒险的英雄，盾牌岭就在这里的东南面。去调查一下那些被亵渎的墓地，把你的发现的线索给我带回来。', '上古升降梯的奥弗斯希望你去寻找芬基尔的线索、洛丁的线索、伊斯多弗的线索和温丹的线索。', '<欧弗斯鬓胡竖了起来。>$B$B海贼…他们的邪恶是没有尽头的吗?$B$B我们一定得找回这些被偷走的神器，并将东西还回这个被诅咒的地方，这样我的族人们才可以重获平静。', '巨牙海民需要你的帮助!', '', '去嚎风峡湾找上古升降梯的卡玛古的奥弗斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11505, '奥金顿的幽魂', '奥金顿的诸多灵魂原本不会介入联盟与部落的战争之中，但是如果能得到它们的眷顾，毫无疑问将会为我们在这一地区增加许多优势。$B$B根据远古的习俗，生者要在每天特定的时段于白骨荒野上的灵魂之塔前礼拜，向亡者们献上敬意。$B$B如果届时你能够转至那些灵魂之塔，并协助保卫那里的安全，你就可以将灵魂的眷顾带到我们这一边来。$B$B我们必须得到那些灵魂的眷顾，对我们来说，他们将成为巨大的助益，帮助我们占尽先机。', '帮助联盟占据白骨荒野上的一座灵魂之塔。', '灵魂们只差一步就能平静地安息。能获得它们的眷顾是件好事，尤其是我们得在离它们安息之地如此靠近的地方掀起战争。', '灵魂依旧在躁动，$N。你完成了你的任务吗?', '占据一座灵魂之塔', '去泰罗卡森林找奥蕾莉亚要塞的驱魔师苏利文。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11506, '奥金顿的幽魂', '虽然德莱尼人的确是我们的敌人，但他们那些盘踞在奥金顿外的先祖之魂却并不会偏向任何一方。$B$B$B$B按照德莱尼人的远古习俗，生者要在每天特定的时段于白骨荒野上的灵魂之塔前礼拜，向亡者们献上敬意。$B$B如果届时你能够转至那些灵魂之塔，并协助保卫那里的安全，毫无疑问你可以让那些灵魂回到奥金顿中，得到安息。$B$B联盟肯定会去占领那些灵魂之塔，而我们所要做的，就是先发制人。', '帮助部落占据白骨荒野上的一座灵魂之塔。', '灵魂们只差一步就能平静地安息，并且赐予我们他们的眷顾。$B$B尽管这只是暂时的，但依旧能给予我们的敌人羞辱的一击，他们的祖先居然反过来与他们为敌。', '奥齐顿的灵魂依旧围绕在我们四周。他们会给予我们协助吗?', '占据一座灵魂之塔', '去泰罗卡森林找裂石堡的驱魔师瓦沙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11507, '卡玛古的长者阿图伊克', '<奥弗斯把你给他的线索捆扎在一起。>$B$B我的人民正悲惨地卷入一场与北海海盗的战争。如果说有哪个海象人能帮我们纠正海盗们所犯下的大错，我想那也只有卡玛古的长者阿图伊克了。你一定要马上把这些线索交给他。$B$B要去卡玛古的话，你必须乘坐我身后的这架上古升降梯，直达卡玛古，找到长者阿图伊克。', '嚎风峡湾的奥弗斯希望你能把他的包裹交给卡玛古的长者阿图伊克。', '欧弗斯是个优良的巨牙海民 - 我们当中最强的战士。我知道他绝对不会让我们失望。$B$B让我看看你带来的是什么。', '来自欧弗斯的消息?', '', '去嚎风峡湾找卡玛古的长者阿图伊克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11510, '斯库德', '约纳·斯特林疯掉以后做了第一件事就是夺走了我珍贵的辛多雷占卜水晶，把它拿去喂了我的克星，逆戟鲸斯库德。$B$B不，不是我给那个该死的家伙取这个名字的，我只是知道它在无赖港东南方的船群中游荡而已。杀死那条头大无脑的傻鱼，把我那漂亮的辛多雷水晶从从它的胃里挖出来。$B$B做完这个，我们才能好好坐下来谈谈。', '无赖港的“银月”哈瑞希望你能从逆戟鲸斯库德那里夺回他的辛多雷占卜水晶。', '<哈利从你手上接过水晶，温柔地抚摸着它。>$B$B喔，我的宝贝!那个又大又坏的鲸鱼伤害了你吗?现在都没事了。我再也不会让你离开我的视线了!$B$B<哈利抬起头看着你。>$B$B嗯，我们谈到那里了?', '你迷路了吗?', '', '去嚎风峡湾找无赖港的“银月”哈瑞。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11511, '风暴愤怒法杖', '那些圣物都受到了诅咒，而你竟然要去寻找它们，实在太疯狂了，$r。据我所知，任何与这些物品有直接联系的家伙不是疯了就是死了。$B$B以法杖为例。我最后一次听说它的下落是这样的：载有它的那艘船被遗弃了，任由它腐烂在这里北面长矛岛的海岸边。$B$B如果你想要找那东西，就去船里的储存室找找。$B$B但是不管怎样，不要把那法杖带到这里来！还有记得绕开阿卜杜尔，他会把你的心挖出来的。', '找回风暴愤怒法杖，把它交给嚎风峡湾的海象人——卡玛古的奥弗斯。', '我们必须归还所有的神器，$N。等四样全部收集齐全，你就要把它们放回墓穴中。', '你拿到法杖了吗?', '', '去嚎风峡湾找上古升降梯的卡玛古的奥弗斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11512, '伊斯多弗的冰冷之心', '有人说约纳从来都没有这么不正常过，我知道原因，是那颗心。那颗该死的冰冷之心！我看到了他把它从墓穴中拔出时的那一刹那，他整个人都变了。我能看到他的血液在血管中冻结了……随后疯狂完全地占有了他。$B$B他离开了我们，一个人躲在这座岛北面的山洞里。我听说他把冰冷之心扔在了洞穴的深处。已经太晚了……$B$B如果你敢把那颗心带回这里的话，信不信我会亲手杀了你？', '找回伊斯多弗的冰冷之心，把它交给嚎风峡湾的海象人——卡玛古的奥弗斯。', '我们必须归还所有的神器，$N。等四样全部收集齐全，你就要把它们放回墓穴中。', '伊…伊苏铎夫的冰冻心脏?', '', '去嚎风峡湾找上古升降梯的卡玛古的奥弗斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11513, '截获法力晶格', '我前些日子亲自制订了一个计划，要为我们即将开启的传送门准备一个稳定的能量源。$B$B巴什伊尔码头那里的虚灵正在从风暴要塞走私大量的法力晶格，并把它们运送到太阳之井，供凯尔萨斯使用。$B$B他们把这些法力晶格隐藏在非常隐秘的地方，但你仍有一个方法可以找到它们，那就是利用虚灵身上携带着的相位设备。$B$B不过，小心守卫在那些晶格旁边的相位浮龙。', '夺取10块走私来的法力晶格，把它们带回沙塔斯城，交给圣光广场上的主教纳苏恩。', '这些法力电池对我们的计画十分重要。我们很快就可以创建直达太阳之井岛的传送门!$B$B明天再来找我，我会派你再去从我们那些巴什伊尔『朋友』那多弄点来。', '你找到那些法力电池了吗?', '', '去沙塔斯城找圣光广场的主教纳苏恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11514, '维持传送门', '我们必须维持传送门的能量供应，否则它会直接坍塌。所以，我们还得继续从巴什伊尔码头的那些虚灵手中抢夺法力晶格。码头就在刀锋山的西北角，偏北方向。$B$B记住，你要先从虚灵手里抢到一台相位设备，才能定位那些法力晶格的位置。$B$B你还必须小心那些相位浮龙，那是虚灵们部署在那里守卫法力晶格的。', '夺取10块走私来的法力晶格，把它们带回沙塔斯城，交给圣光广场上的主教纳苏恩。', '这些法力电池可以继续维持传送门的能量。$B$B明天再来找我，我要派你去再多弄点来。', '$N，你今天替我们收集法力电池的进度如何了?', '', '去沙塔斯城找圣光广场的主教纳苏恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11515, '血债血偿', '当凯尔萨斯的部队通过那道传送门撤退时，他最忠诚的侍从们得到了可怕的奖励。他们留了下来，啜饮着恶魔的血液。$B$B这些血液改变了他们，赐予了他们新的力量，也证明了他们的堕落。$B$B从恶魔身上取得血液样本，用血液激活魔能虹吸宝石的能量，然后夺走这些傲慢蠢货的新力量。在他们变得虚弱之后杀死他们，然后回来向我复命。', '基尔加丹王座的魔导师瑟伊拉希望你使用魔能虹吸宝石杀死4个憔悴的魔血精灵。你需要用附近的天怒先锋身上的恶魔血液来启动魔能虹吸宝石。', '蠢蛋。他们学会了如何吸收魔化的能量却没学会如何保存它们。$B$B我们真是幸运，$N。茁壮后的魔化血精灵可是难以对付的敌手。', '这些怪胎污辱了我们的种族。你一定得毁灭他们，$N。', '', '去地狱火半岛找基尔加丹王座的魔导师瑟伊拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11516, '轰炸传送门', '我们必须得关闭这道传送门，阻断燃烧军团向太阳之井增援。$B$B拿上这些灰烬，里面有我创造的活焰。只要有足够的能量支持，它就能产生强大的破坏力。$B$B在活焰周围杀死那些游荡的魔能火花，这样活焰就可以逐渐得到能量，变得越来越活跃。$B$B等你完成后，把活焰带到传送门那里去，它知道下一步该怎么做。', '基尔加丹王座的魔导师瑟伊拉希望你使用炽热的灰烬召唤一个活焰，在它周围消灭大型魔能火花，它就会逐渐变成一个不稳定的活焰。带着不稳定的活焰去摧毁军团传送门。', '干得好，$N。那些恶魔或许有办法再度修复入口。我推测我们到时得再炸一次。', '完成了吗，$N?我们必须阻止更多的燃烧军团部队去增援凯尔萨斯。', '摧毁军团传送门', '去地狱火半岛找基尔加丹王座的魔导师瑟伊拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11520, '寻根知底', '你好，$r。$B$B恐怕在我的材料到货之前，我们没有什么能向你提供的。$B$B在我所需的补给中，有一种特殊的材料——荆刺根须，不过要获取它非常困难。$b$b幸运的是，我知道一个秘密……$B$B利用荆刺剥石者的腺体，就可以控制一头掠食者来帮你挖出这些根须。$B$B想要找到这些根须的话，从外域的沙塔斯城一直往东北飞，就能到达荆刺高地了。', '阳湾港口的玛尔娜希望你转至外域的荆刺高地，收集5根荆刺根须给她。', '这些真的不错，$C。$B$B我感谢你的协助。', '说真的，$N，我没空发呆聊天。$B$B等你收集到那些根茎再告诉我。', '', '去奎尔丹纳斯岛找阳湾港口的玛尔娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11521, '继续寻根', '我的存货当前很充足，但仍然需要大量的荆刺根须来保证日常所需。$B$B采集这些根须的确很困难，但我知道有一种特别的方式可以获得它们。$B$B利用荆刺剥石者的腺体，就可以控制一头掠食者来帮你挖出这些根须。$B$B想要找到这些根须的话，从外域的沙塔斯城一直往东北飞，就能到达荆刺高地了。$B$B$n，等你采集到了5份根须后就回到我这里来吧。', '阳湾港口的玛尔娜希望你转至外域的荆刺高地，收集5根荆刺根须给她。', '干得好，$N。$B$B再次感谢你的帮助!', '说真的，$N，我没空发呆聊天。$B$B等你收集到那些根茎再告诉我。', '', '去奎尔丹纳斯岛找阳湾港口的玛尔娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11523, '激活结界！', '我们已经成功地让圣殿周围的水晶结界恢复正常，但为什么就这么罢手呢？我们的其它建筑都需要创建防御措施，不过失心者仍然在顽固地偷取着结界的能量。$B$B消灭那些失心者，夺回他们手上的法力馀烬，用以激活圣殿的结界。我们的安全就全都靠它了。', '破碎残阳基地的瑟里斯·黎明之心希望你能从失心魔瘾者和失心吞噬者那里获取4份法力馀烬，用它们激活阳湾港建筑物外围的水晶结界。', '做得好，$N。结界正在慢慢地恢复力量。日境很快就是我们的了!', '你重新启动了那些水晶结界吗，$N?', '激活水晶结界', '去奎尔丹纳斯岛的破碎残阳基地找瑟里斯·黎明之心。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11524, '游荡的奥术守卫', '我们现在的人手还不足以去占领阳湾圣殿，但我有一个计划，可以让形势向我们有利的方向转变。$B$B太阳之井释放出的能量，使得那些在岛上巡逻的奥术守卫体内的水晶核心遭到了破坏，似乎已经无法修复了。$B$B我制造了一些新的水晶，可以让它们接受我们的指令。把它们放入那些被打败的奥术守卫的外壳内去吧。我们需要一切可以得到的帮助。', '破碎残阳基地的守备官夏安希望你将调和过的水晶核心放入5台被打败的奥术守卫体内，将它们转换成友军。', '干得好，$N。圣所很快就是我们的了!', '你转化了那些哨兵吗，$N?', '', '去奎尔丹纳斯岛找破碎残阳基地的守备官夏安。', '转化奥术守卫', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11525, '转化更多奥术守卫', '我的计划成功了。依靠这些奥术守卫的帮助，我们已经成功得拿下了阳湾圣殿。$B$B我制造了一批新的水晶，可以让更多的奥术守卫接受我们的指令。把它们放入那些被打败的奥术守卫的外壳里。成功控制它们之后，我会把它们部署到别的地方去。', '破碎残阳基地的守备官夏安希望你将调和过的水晶核心放入5台被打败的奥术守卫体内，将它们转换成友军。', '太好了。这些转换后的哨兵可以守护我们的周边环境。', '你转化了那些哨兵吗，$N?', '', '去奎尔丹纳斯岛找破碎残阳基地的守备官夏安。', '转化奥术守卫', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11526, '失踪的魔导师', '我们已经派出一名精英人员前去调查南边黎明广场中央的恶魔传送门的状况，但她一直没有回来。$B$B带上这张卷轴，这是我们从一名敌人的尸体上搜出来的。我们相信它能让你使用那座传送门，一旦穿越了那道传送门以后，立刻找到魔导师瑟伊拉，并尽可能协助她。', '在黎明广场的传送门附近使用军团传送卷轴。穿越传送门之后，立刻找到魔导师瑟伊拉。', '塞里斯还担心我的安危，这真是太贴心了。但我们这里却还有更严重的问题，严重得多。', '安静点，$C。燃烧军团的部队正在监视大门的南边。', '', '去地狱火半岛找基尔加丹王座的魔导师瑟伊拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11527, '慈悲修女号上的叛变', '是的，我们有麻烦了，朋友。$B$B我的炮手们叛变了！就在我和我的手下在上面设法教训索罗夫的时候，那群炮手却在下面商讨着造反的计划。$B$B你得去下面解决那群背叛我的水兵，夺回爆破火药来填装尾楼的大炮。$B$B有你控制大炮，索罗夫就死定了！', '嚎风峡湾的慈悲修女号上的艾尔雷斯船长要求你从船上的储藏室夺回5个炸药桶。', '那些不忠的船底老鼠总算得到了一点教训!现在是时候来填装大炮了，兄弟!', '叛乱的水手和巨人太多了!', '', '去嚎风峡湾找慈悲修女号的艾尔雷斯船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11529, '索罗夫的宝藏', '我的手下已经为你填装好了大炮，朋友。它正在船那端的尾楼上。等索罗夫进入射程，就给他几颗炮弹尝尝。$B$B那个旱鸭子挂了之后，你得给我们拿回宝藏，为啥？因为我们离不开这艘该死的船！等你拿回宝藏，你就能得到你要的盾牌了……', '用大炮杀死索罗夫，夺得索罗夫的宝藏。将索罗夫的宝藏交给慈悲修女号上的艾尔雷斯船长。', '约定就是约定，伙计!', '照子放亮点，伙计们!', '', '去嚎风峡湾找慈悲修女号的艾尔雷斯船长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11530, '古神之盾', '这是你要的盾。我希望它不会像诅咒我和我的手下那样诅咒你。别害怕，不过你不能待在这里……我确信还是有东西会想要把它夺回去的。$B$B现在就拿着那东西离开我的船！', '将古神之盾带到嚎风峡湾的上古升降梯去，交给卡玛古的奥弗斯。', '我们必须归还所有的神器，$N。等四样全部收集齐全，你就要把它们放回墓穴中。', '你回来了!', '', '去嚎风峡湾找上古升降梯的卡玛古的奥弗斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11531, '奇怪的发动机零件', '这件奇怪的发动机零件不像水泵零件，也不像你所见过的任何机械零件。或许凯莉·弗莱知道点什么吧。', '将奇怪的发动机零件交给泰雷多尔的凯莉·弗莱。', '<李小炸注视着那个引擎零件，接着望向远方。>$B$B这东西真的很特别。很难说这东西从哪里来的--说不定是从天上掉下来的。我得要保留这个东西，并且付钱补偿你。$B$B这件事最好你知我知，别向任何人提起比较好。$B$B<李小炸堆起她最有魅力的笑容。>', '喔，天啊!你拿来了什么，$N?', '', '去赞加沼泽找泰雷多尔的凯莉·弗莱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11532, '轰炸死亡之痕', '死亡之痕的亡灵天灾眼下正让燃烧军团忙得焦头烂额，不过用不了多久，等燃烧军团的部队从南方解脱出来，就会把矛头指向我们。$B$B我希望你能驾驭龙鹰飞越死亡之痕，用这些奥术炸弹好好教训一下恶魔们。$B$B如果一切进展顺利的话，他们甚至不会注意到我们从凯尔萨斯的部队手中夺下军械库的行动。如果你已经做好了飞行的准备，就去和港口西面的龙鹰管理员艾雷谈谈吧。', '战斗法师艾尔娜希望你去和艾雷·碎云谈一谈，飞往死亡之痕。用奥术炸弹杀死2个深渊霸主、3个艾瑞达巫师和12个天怒执行者。', '你真的很有天分，孩子。你有想过要加入御\r\n天者吗?$B$B我说笑的，$N。如果我们想要尽快拿下码头，就需要你在这里帮忙。', '你完成了你的任务吗，$N?', '', '去奎尔丹纳斯岛找阳湾圣殿的战斗法师艾尔娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11533, '继续空袭', '由于我们对死亡之痕的燃烧军团保持空袭，我们成功地拿下了军械库。$B$B事实上，如果我们能持续对他们进行空袭的话，一切都会变得非常顺利。拿上这些奥术炸弹，去对付那些恶魔。$B$B如果你做好了飞行准备，就去和阳湾港口的艾雷·碎云谈谈。', '战斗法师艾尔娜希望你去和艾雷·碎云谈一谈，飞往死亡之痕。用奥术炸弹杀死2个深渊霸主、3个艾瑞达巫师和12个天怒执行者。', '今天杀死的恶魔，我们明天就不需要对付他们。继续加油。', '你完成了你的任务吗，$N?', '', '去奎尔丹纳斯岛找阳湾圣殿的战斗法师艾尔娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11535, '做好准备', '据说补给品应该已经到了，据说而已。$B$B但无论怎样，我们不能就这么干等着，不能让我们的攻势就这么停下。我们必须利用一切可以利用的资源。$B$B对我来说，我需要一些矿石来重新制作铁砧，这样我就可以开始强化士兵们的武器装备了。$B$B这里东面的海岸上有一群纳迦正在采集矿石，他们把矿石打包运送给燃烧军团。$B$B如果能从他们手上夺取矿石的话，可真称得上是一石二鸟……', '阳湾军械库的铁匠霍尔萨希望你去杀死东面的暗脊侍从，夺取他们的钥匙，然后从他们的箱子里偷取3块矿石。', '太好了!我们又更进一步了……$B$B很快我就可以造出一个铁钻，让真正的工作开始进行。', '你去拿我需要的矿石了吗?', '', '去奎尔丹纳斯岛找阳湾军械库的铁匠霍尔萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11536, '不要停下……', '既然我们已经有了铁砧，那么我就可以真正地开始工作了。$B$B不管我们能得到多少帮助，都要好好利用这些暗脊铁矿石。如果我们想在这里取得胜利，就需要持续地补充武器和装备。$B$B这里东面的海岸上有一群纳迦正在采集矿石，他们把矿石打包运送给燃烧军团。$B$B如果能从他们手上夺取矿石的话，可真称得上是一石二鸟……', '阳湾军械库的铁匠霍尔萨希望你去杀死东面的暗脊侍从，夺取他们的钥匙，然后从他们的箱子里偷取3块矿石。', '太好了!这能够帮我维持士兵的武器与盔甲。$B$B你的帮助真的意义重大!', '你去拿我要求的矿石了吗?', '', '去奎尔丹纳斯岛找阳湾军械库的铁匠霍尔萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11537, '继续作战', '我们必须持续不断地消灭燃烧军团的部队，挫败他们的锐气。$B$B仇恨使者是燃烧军团的特种部队，专门负责增援重要的战略地点。燃烧军团的士兵会因为他们的到来而更加奋勇作战，因为他们对仇恨使者的恐惧远大于对我们的恐惧。$B$B今天我们会改变这一切。拿上这面战旗，去黎明广场扫荡恶魔。等到他们派出仇恨使者后，干掉他，把战旗插在他的尸体上。', '先驱者伊努罗希望你转至黎明广场，杀死仇恨使者和6名燃烧军团恶魔，然后将破碎残阳战旗插在仇恨使者的尸体上。', '你的贡献立下了楷模，$N。我们向燃烧军团的部队证明了我们的能耐。', '你成功了吗，$N?', '', '去奎尔丹纳斯岛找阳湾圣殿的先驱者伊努罗。', '将战旗插在仇恨使者的尸体上', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11538, '军械库之战', '燃烧军团控制了军械库，它对于我们的行动来说是一个战略要地。只要他们的士气仍然这么高涨，我们就不可能从他们手里夺取军械库的控制权。$B$B仇恨使者是燃烧军团的特种部队，专门负责增援重要的战略地点。燃烧军团的士兵会因为他们的到来而更加奋勇作战，因为他们对仇恨使者的恐惧远大于对我们的恐惧。$B$B今天我们会改变这一切。拿上这面战旗，去黎明广场扫荡恶魔。等到他们派出仇恨使者后，干掉他，把战旗插在他的尸体上。', '先驱者伊努罗希望你转至黎明广场或者阳湾军械库，杀死仇恨使者和6名燃烧军团恶魔，然后将破碎残阳战旗插在仇恨使者的尸体上。', '你的贡献立下了楷模，$N。我们很快就能从军团的手中夺下军械库!', '你完成了我的要求吗，$N?', '', '去奎尔丹纳斯岛找阳湾圣殿的先驱者伊努罗。', '将战旗插在仇恨使者的尸体上', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11539, '占领港口', '凯尔萨斯最精英的一支部队——晨锋军团已经驻扎在了阳湾港口和晨星村。$B$B港口对我们的行动来说是至关重要的，任何晨锋部队的人员伤亡都可以给我们带来极大的帮助。凯尔萨斯会为背叛他的人民和站在燃烧军团一边而感到后悔的。', '阳湾军械库的魔导师伊拉斯塔希望你去消灭6个晨锋召唤者、6个晨锋血骑士和3个晨锋射手。', '做得非常好，$C。凯尔的军队将会开始动摇退缩，只要我们能拿下港口，就能给他致命的一击!', '你杀死了那些曦刃人渣吗，$N?', '', '去奎尔丹纳斯岛找阳湾军械库的魔导师伊拉斯塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11540, '击溃晨锋部队', '晨锋军队已经被我们赶出了阳湾港口，这一带已经完全在我们的控制之下了。但不知道为什么……我并不满意。$B$B我希望你能转至西面的晨星村，消灭任何残馀的晨锋部队。他们追随凯尔萨斯来到这里时，命运就已经注定了。', '阳湾军械库的魔导师伊拉斯塔希望你去消灭6个晨锋召唤者、6个晨锋血骑士和3个晨锋射手。', '不知道凯尔萨斯.逐日者王子在听到他的军队溃败时，他的脑袋里在想什么?$B$B他会感到绝望吗?无助?恐惧?$B$B我倒是很希望他这样觉得。', '你杀死了那些曦刃人渣吗，$N?', '', '去奎尔丹纳斯岛找阳湾军械库的魔导师伊拉斯塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11541, '解救绿鳃奴隶', '纳迦占领了东南面的绿鳃海岸。那些被称为暗脊海妖的女性纳迦用魔法奴役了当地的鱼人。$B$B我有责任破坏纳迦在那里所进行的一切活动，这也就是你来这里的原因。$B$B$C，我希望你能从那些女性纳迦身上夺取控制宝珠，将它们扔在绿鳃奴隶周围，打碎宝珠就能让鱼人恢复自由。$B$B我想这样鱼人就会被激怒，反抗他们的主人。', '瓦琳德拉上尉希望你能解救10个绿鳃奴隶。完成任务之后，去阳湾港口的银月之傲号上向她复命。', '今天这样就够了。缓慢而稳定就是关键。过多的干扰会让他们把注意力转到我们身上;这可不是我们想要的。$B$B明天再来找我，我们可以继续进行这边的工作。', '我的斥候告诉我，纳迦今天所受的干扰还不够多。', '', '去奎尔丹纳斯岛找阳湾港口的瓦琳德拉上尉。', '解救绿鳃奴隶', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11542, '拦截援军', '我们最近一直在努力尝试攻占港口，以试图控制整个阳湾港。然而不幸的是，有一支满载着晨锋预备兵的舰队正在路上，凯尔萨斯的军队很快就将得到增援。$B$B带上这瓶油，向艾雷·碎云要一只龙鹰。你可以骑着龙鹰飞经舰队上空，一旦达到攻击距离，就用油在他们的船帆上放火。$B$B之后，你要降落在船上，攻击那些预备兵。他们的船帆着火以后，肯定会忙作一团，从而无心防御你的攻击。', '阳湾军械库的守备官凯兰要求你去跟艾雷·碎云谈一谈，并飞越晨锋部队的增援舰队。将火油投掷到对方的船帆上，使之引燃。落地后，再杀死6名晨锋预备兵。', '做得好，$N。这应该会让港口有一阵子不会出现援军。', '你完成了你的任务吗，$N?', '', '去奎尔丹纳斯岛找阳湾军械库的守备官凯兰。', '烧毁辛洛雷号', '烧毁血誓号', '烧毁曙光追寻者号', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11543, '拒敌港外', '我们刚刚攻占了阳湾港口，然而不幸的是，有一支满载着晨锋预备兵的舰队正在路上，凯尔萨斯的军队很快就将得到增援。$B$B带上这瓶油，向艾雷·碎云要一只龙鹰。你可以骑着龙鹰飞经舰队上空，一旦达到攻击距离，就用油在他们的船帆上放火。$B$B之后，你要降落在船上，攻击那些预备兵。他们的船帆着火以后，肯定会忙作一团，从而无心防御你的攻击。', '阳湾军械库的守备官凯兰要求你去跟艾雷·碎云谈一谈，并飞越晨锋部队的增援舰队。将火油投掷到对方的船帆上，使之引燃。落地后，再杀死6名晨锋预备兵。', '做得好，$N。这应该会让港口有一阵子不会出现援军。', '你完成了你的任务吗，$N?', '', '去奎尔丹纳斯岛找阳湾军械库的守备官凯兰。', '烧毁辛洛雷号', '烧毁血誓号', '烧毁曙光追寻者号', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11544, '阿塔玛军备', '影月谷东面的阿塔玛平台对于德莱尼人来说是个神圣的地方，但现在那里满地都是邪兽人。他们用从那里挖掘出的特殊矿石制造着邪恶的武器和装备。$B$B我需要这些装备，用它们和纳迦那里抢来的矿石制造合金。我们的学者已经让铁砧具备了净化金属的能力。$B$B从影月天选者、影月斩杀者和影月暗法师身上找到这些装备。把它们拿到这里来，在我的铁砧上打碎并净化它们，然后把净化过的阿塔玛金属交给我。', '铁匠霍尔萨要求你在奎尔丹纳斯岛阳湾军械库的铁砧上打碎阿塔玛军备，以此制造5块净化过的阿塔玛金属。', '感谢你，我的朋友。现在我可以制造更多的特殊合金来锻造部队的武器与盔甲了。$B$B我手边还有一些在拆解过程中产生的萃取物，可以方便地使用于你的武器上。别客气，请从中挑选对你最有帮助的吧。$B$B明天再来找我，我必定还需要更多的武装。', '我需要所有净化过的阿塔莫金属，好让我可以着手工作，$C。', '', '去奎尔丹纳斯岛找绿鳃海岸的铁匠霍尔萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11545, '仁慈的募捐', '我们已经从敌人的手中彻底夺回了阳湾港，最终的胜利就在眼前。不过，我们也付出了非常沉重的代价，许多英勇的战士倒在了敌人的刀下。$B$B我现在唯一想做的事情就是让这些牺牲者永远被人们铭记，永远不被遗忘。现在我们打算在这里建造一座纪念碑，在上面篆刻所有牺牲者的姓名。当然，如果你能捐一笔钱就再好不过了，希望你能考虑一下这件事。多馀的资金将会用来帮助英烈们留下来的孤儿与遗孀。', '奎尔丹纳斯岛阳湾港的学者艾尤莉希望你捐赠10枚金币。', '你有着善良的灵魂，$N。人们很容易在战争的混乱与胜利的兴奋中遗忘了那些牺牲者。我代死者的亲友感谢你。', '你愿意捐款吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11546, '开始营业', '欢迎你，$n。$B$B我有多种方式可以帮助你进行作战准备。$b$b比如说，我最近领悟了一种独特的药剂配方。$b$b艾泽拉斯很多野外地区都生长着血莓，长久以来人们只把它们当成是一种公害而已。不过我了解到，在这种植物受到太阳之井能量的影响后，就会产生一种特殊成分——提取这种成分可以提升用户的能力。$b$b从附近的灌木丛中找一株样本给我，我会让你知道我所指的是什么。', '阳湾港口的玛尔娜希望你从奎尔丹纳斯岛上的灌木丛中收集5颗血莓。', '太好了，$N。$B$B我希望这些东西可以帮得上你的忙。', '你收集到那些莓子了吗?', '', '去奎尔丹纳斯岛找阳湾港口的玛尔娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11547, '魔网能量线的读数', '一群不劳而获的家伙！$B$B你们都只想取得便利，却从没想过要去制造一道最简单的传送门。$B$B也许给你们一点小小的教训会让你们对我在这里所做的一切有所感激。$B$B拿上这颗水晶，在这里西面的血水晶、南面的黎明广场传送门和东南方的绿鳃海岸一带的纳迦神殿那里调节水晶。$B$B也许这样你就会认识到传送魔法的珍贵……', '阳湾圣殿的星术师达纳里安希望你在血水晶、黎明广场传送门和绿鳃海岸的纳迦神殿上使用星术师的水晶。', '好，好，好。现在让我们来瞧一瞧?$B$B看来事情都很顺利，非常好。这是你的变位器。$B$B如果你的数据有任何瑕疵，可就没人知道你会跑去哪儿了，提醒你，到时候你就只能怪自己了。', '你让水晶同调了吗，$C?', '', '去奎尔丹纳斯岛找阳湾圣殿的星术师达纳里安。', '接收传送门读数', '接收神殿读数', '接收血水晶读数', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11548, '鼎力支持', '我们已经为那些在本次战争中牺牲的人们建起了一座纪念碑。对牺牲者的家人与爱人，对那些永远失去了挚爱的人们来说，这只能给他们一些微薄的安慰。$B$B我还在募集一笔捐款，以供养那些已经牺牲的英雄们留下的遗族。如果你愿意的话，请帮助他们吧。', '奎尔丹纳斯岛阳湾港的学者艾尤莉希望你捐赠10枚金币。', '你有着善良的灵魂，$N。人们很容易在战争的混乱与胜利的兴奋中遗忘了那些牺牲者。我代死者的亲友感谢你。', '你愿意捐款吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11549, '慷慨的捐赠者', '你已经为我们做了许多事情，$N。我们非常感谢你的协助。$B$B不过，不知道你是否注意到屋外正在募捐的学者艾尤莉？她是一位非常有魅力的善良人，但尽管如此，捐献的数额却还不太够。$B$B如果你愿意捐一笔钱给她，协助她的事业，我想你一定会声名远扬的。你觉得怎么样？', '学者卡伊索斯希望你捐献1000枚金币以协助学者艾尤莉的事业。若完成这个任务，你将会获得“破碎残阳的$N”的称号。', '你真是个慷慨的人，也是个可靠的盟友。从今天起，你将会被称为破碎残阳的$N，每个在此奋战的人都会知道你的义举!', '你打算要捐款了吗?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11559, '冬鳞鱼人的贸易', '既然你已经学会了冬鳞鱼人的语言，不妨与他们接触试试。说到打交道，最好的方法当然是做生意啦。$B$B鱼人将蚌壳看得比什么都重要。你看，呀噜咕噜是冬鳞氏族唯一幸存的商人，如果我是你的话，我就将一堆冬鳞蚌壳送给他做礼物。$B$B冬鳞村以及洞穴附近的水渠中到处都是那种蚌壳。', '收集5只冬鳞蚌壳，将它们交给冬鳞避难所的呀噜咕噜。', '这是给我的?这不是什么$r诡计吧?不是?$B$B那好吧，多谢你啦!你可以再带更多的蚌壳回来，我们可以做点生意!', '这什么?你是谁啊?$B$B你这家伙是个$r!你怎么会说我们的话?', '', '去北风苔原找冬鳞避难所的呀噜咕噜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11560, '救救蝌蚪！', '啊，你总算回来啦！$B$B在那场事故中，地壳运动导致洼地下沉以及洞穴抬升。居住在洞穴中的龙虾人克拉西姆斯趁机虏走了许多冬鳞蝌蚪。$B$B村落中的鱼人也不知遭遇了什么变故，全都听从于克拉西姆斯的指挥。$B$B$C，你必须穿越洼地，解救被困在村落和洞穴中的蝌蚪。$B$B冬鳞氏族的未来就靠你了！', '国王姆嘎姆嘎要你解救20只冬鳞蝌蚪。完成任务后返回冬鳞避难所向他复命。', '现在无论发生什么事，冬鳍鱼人都拥有了一个安全的未来。$B$B因为你的无私，你应该接受赞许，还有奖励。', '如果不能救出更多的蝌蚪，不管我们做了什么:冬鳍鱼人就一点未来都没有了!', '', '去北风苔原找冬鳞避难所的国王姆嘎姆嘎。', '营救冬鳞蝌蚪', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11561, '就是他们！', '昔日的兄弟姐妹已经沦为我们的仇敌。他们掳走冬鳞蝌蚪，将我们逐出村落，还杀害了不计其数的同胞。$B$B$r，证明你的实力吧！穿越裂谷，杀死他们！$B$B虽然国王姆嘎姆嘎对你很有好感，但是只有在你完成这项任务后，我们才会考虑完全接纳你。如果任务失败，你最好滚得远远的，再也别回来！', '冬鳞避难所的吧咕姆咕要你杀死15名冬鳞鱼人，战士、智者或是巡滩者都行。', '我很满意。我可以闻到你手上他们血液中的铜味。$B$B这是个好开始，$r。', '如果你杀死那么多的冬鳍叛徒，那为什么我看过去水中的时候，还会看到这么多那种家伙?', '', '去北风苔原找冬鳞避难所的吧咕姆咕。', '杀死冬鳞鱼人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11563, '咕噜咕噜呜啦哇啦！', '瞪大你那双哀怨的小眼睛仔细看看，北部海湾中的逆戟鲸正在肆意杀害我们的同胞！$B$B想要替你的暗夜精灵“国王”讨回那件备用的鱼人服，就得帮我取回逆戟鲸首领咕拉咕拉的头。他总是逆着汹涌的命运之潮而游，那些被海妖的死亡之歌所诱的生灵统统成为了他的腹中餐！$B$B$r，赶紧行动吧。冬鳞鱼人都快死绝了，你却还在这里和我悠闲地聊天！', '冬鳞避难所的姆姆咕咕要你将咕拉咕拉的徽记带回来给他。', '不错。这东西可以煮成一顿大餐!$B$B虎鲸王一死，它们对我们的攻击也将减轻，它们会忙着彼此争夺统治权。', '如果你没有吉尔戈的头颅，那就不要浪费我的时间!', '', '去北风苔原找冬鳞避难所的姆姆咕咕。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11564, '美味炖鲸肉', '我听说，你正打算去捕猎逆戟鲸的首领咕拉咕拉。$B$B这本来也是稀松平常的事儿，但是如果你喝过鲜美的鲸鱼汤，就一定会感叹还是活着好啊。从分布在幽光海湾的逆戟鲸身上取几块肥美的逆戟鲸脂肪回来，我就让你尝尝这世间的美味。$B$B快去吧……我还得仔细处理下这颗巨大的逆戟鲸头呢。', '北风苔原冬鳞避难所的屠夫布咕布噜要你去收集7块肥美的逆戟鲸脂肪。', '喔耶，这些应该很够用。$B$B就把它们随便找个地方丢着吧。你可以拿走一些我昨晚剩下的炖肉。', '你拿到我需要的所有虎鲸油脂了吗?', '', '去北风苔原找冬鳞村的屠夫布咕布噜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11565, '备用的鱼人服', '很好，如果那个“国王”肯一心一意地帮助我们抵御外敌，我就为他保守秘密。$B$B把这个还给他吧。我仔细清洗过这件鱼人服了，不过我想不明白他为什么要搞两套伪装。$B$B或许他是有什么计划吧？', '返回冬鳞避难所，将国王姆嘎姆嘎的备用鱼人服交给他。', '<看着备用的鱼人服装，国王兴奋地摩擦着他鱼人装上的附肢。>$B$B干得不错。现在回到我们当前的问题上。我有件非常重要的事情要让你去做。', '你拿到了我的备用服装吗，$N?', '', '去北风苔原找冬鳞避难所的国王姆嘎姆嘎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11566, '决不投降！', '$N，让我们结束这场骚乱吧。如果冬鳞鱼人想在这里繁衍生息的话，就必须除掉克拉西姆斯！$B$B我要你穿上这件备用的鱼人服，以投降为借口进入冬鳞洞穴。你手上举着小白旗，他们是不会攻击你的。$B$B克拉西姆斯就躲在洞穴最西南的角落。我要你杀死克拉西姆斯，将他的钳带回来作为你完成这项任务的凭证。', '冬鳞避难所的国王姆嘎姆嘎要你将克拉西姆斯的钳子带回来给他。', '令人遗憾，但却无可避免。我将会带走这只爪子，$N.$B$B谢谢你所提供的一切帮助。随着克拉希穆司被击败，也许我们可以重新结合剩余的鱼人，封锁那些洞穴。$B$B我的朋友，请收下这个…对于你所给予我们的所有帮助，我至少得给你这个!', '你完成任务了吗，$C?克拉希穆司死了吗?', '', '去北风苔原找冬鳞避难所的国王姆嘎姆嘎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11567, '克瓦迪尔上古甲胄', '我曾经呆在那艘载有甲胄的船上。当时我们正在转舵折回这里，突然被一艘被遗忘者的驱逐舰攻击了。$B$B他们强行登上了我们的船，夺走了所有的财宝，随后弄沉了她。$B$B那是我最后一次看到甲胄。如果你想要去找的话，就坐我的小船从无赖港转至那艘驱逐舰所在的小岛吧。我的女人奥兰雅就在外面，跟她谈谈。她会帮你上船的。$B$B如果你找到甲胄，给我带回来！', '找回克瓦迪尔上古甲胄，把它交给嚎风峡湾卡玛古的奥弗斯。', '我们必须归还所有的神器，$N。等四样全部收集齐全，你就要把它们放回墓穴中。', '你找到盔甲了吗?', '', '去嚎风峡湾找上古升降梯的卡玛古的奥弗斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11568, '安息', '<奥弗斯交给你一个背包。>$B$B背包里装着你找回的圣物。到东南边的盾牌岭去，找到这些物品被偷走前所在的墓穴，把它们放回原来的位置。我希望这样能让那些神出鬼没的灵魂们安静下来。$B$B勇敢些，$N……', '在盾牌岭那些被掠夺过的墓穴处使用维库圣物，将伊斯多弗的冰冷之心、古神之盾、风暴愤怒法杖和克瓦迪尔上古甲胄放回它们原本的位置。$B$B完成任务之后回到上古升降梯，向卡玛古的奥弗斯复命。', '糟糕的消息，$N。我的人民正处在危险之中，需要被警告。那些来自海上的怪物将不会对卡鲁亚克手下留情。', '完成了吗?灵魂平静下来了吗?', '', '去嚎风峡湾找上古升降梯的卡玛古的奥弗斯。', '放回古神之盾', '放回风暴愤怒法杖', '放回伊斯多弗的冰冷之心', '放回克瓦迪尔上古甲胄');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11569, '钥匙管理器呜啦咕噜', '我们必须逃离这里！洞穴中充斥着来自考达拉的魔法力量，操控了所有鱼人的心智。$B$B钥匙管理器呜啦咕噜就在南边的地下洞窟中。他手里有牢笼的钥匙。夺得钥匙，我们就能打开牢笼逃走啦。$B$B$r，求你快一点！', '冬鳞洞穴的咕啦咕啦要你夺回呜啦咕噜的钥匙。', '快!把它递过来!', '你拿到钥匙了吗?$B$B不，我其它什么事都不管。我只想离开这里!', '', '去北风苔原找冬鳞洞穴的咕啦咕啦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11570, '逃离冬鳞洞穴', '这笼子似乎不是很结实，但是我才不会在没把握的情况下傻兮兮地自己跑出去。$B$B你愿意帮助我逃离这里吗？$r，没时间可以浪费了。$B$B如果我们能顺利逃脱，请转告国王我已经安全归来。他会好好奖赏你的。', '护送噜呱吧呱抵达安全区域，然后返回冬鳞避难所，向国王姆嘎姆嘎汇报这一好消息。', '这个消息真是太好了!你刚才说鲁格伯发现了从洞穴弥漫出的东西正是造成疯狂的原因?$B$B那肯定是凛惧岛的魔法越来越强大了。奥核之战…那是一场蓝龙军团与其馀龙族之间的战争，尸横遍野。$B$B很快，我们全都会被牵扯进去的!', '嗯，$N，我能帮你什么吗?', '护送噜呱吧呱回到安全地带', '去北风苔原找冬鳞避难所的国王姆嘎姆嘎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11571, '学习沟通', '你必须学会冬鳞鱼人的语言才能帮得上忙。这就要借助自然与魔法的双重力量了。$B$B我将这枚空贝壳交给你。水渠底部生活着一位名叫斯卡德尔的元素生物，她拥有水和空气的力量。$B$B击败她后，你就利用这枚贝壳从她的残骸上收集魔法气体。把装满气体的贝壳带回来给我，我就将冬鳞鱼人的语言灌注到你的头脑中。$B$B嘿嘿，你挺走运的。我从朋友那儿学来的水下呼吸法术刚好能派上用场。', '冬鳞避难所的国王姆嘎姆嘎要你对斯卡德尔的尸体使用空贝壳，然后将国王的充盈贝壳交给他。', '现在我可以使用史卡德的精华，好将我对冬鳍鱼人语言的知识传授给你。', '你把海螺装满了史卡德的蒸汽了吗?', '', '去北风苔原找冬鳞避难所的国王姆嘎姆嘎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11576, '监视裂谷：悬崖异常', '$r，你好。我是达拉然的法师盖伦。$b$b不久前，琥珀崖还是一片和平的景象——至少从地热学的角度上讲。近来，频繁的地壳运动使地表沟壑纵横，形成了奇特的能量力场。$b$b我的任务就是记录这些异常现象。刚才我的仪器显示在西南边的悬崖一带发生了一次异常的扰动。$B$B带上这件设备，找到新的扰动发生地之后就使用它。', '琥珀崖的盖伦要你在悬崖异常处使用奥术测量器。', '太惊人了!这是最严重的环境灾害。$B$B但是我担心后头还有更糟糕的事情。', '你帮我弄到那些读数了吗，$C?', '', '去北风苔原找琥珀崖的图书馆员盖伦。', '获取悬崖异常处的读数', '峭壁断层读数', '悬崖异常处读数', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11582, '监视裂谷：峭壁断层', '你听到了吗？！那只是一场馀震而已……几分钟之前那次才叫天崩地裂呢！$B$B看来我不得不再次请你帮忙了。我的仪器显示在西边的水下深处发生了一次巨大的扰动。$B$B和以前一样，我需要你带着这件仪器去收集扰动的数据。$B$B我会给你施加一个水下呼吸的法术。如果在你找到目标地点之前法术效果就要消失了，回来告诉我一声，我会重新对你施放这个法术。', '琥珀崖的盖伦要你在峭壁断层处使用奥术测量器，并将读数带回去交给他。', '它有多大?$B$B这是不可能的!我必须立刻向达拉然报告!', '嗯，$C?$B$B你有找到异常区吗?', '', '去北风苔原找琥珀崖的图书馆员盖伦。', '获取峭壁断层处的读数', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11587, '越狱', '$c，你好。我是多纳森，达拉然的使者。$b$b请原谅我的唐突，但是局势危急，我不得不寻求帮助。艾泽拉斯世界的许多法师都被绑架了，我奉命招募人手来协助调查这件事的内幕。$b$b我打算从南边的营地入手。我要你转至营地中，解救一名被囚禁的法师。当然，你得从那附近的法师猎手身上找到奥术牢笼的钥匙。', '琥珀崖的图书馆员多纳森要你转至蓝玉营地，从蓝玉法师猎手那里夺得蓝玉监狱钥匙，利用它从奥术牢笼中解救一名被囚禁的法师。', '你做得很好，$N。$B$B肯瑞托很乐意接受你提供的协助。请了解，所有你给予我们的帮助都不会白白付出。$B$B请收下这份薄礼代表达拉然对你的感谢。', '我相信你正努力救出被囚禁的法师……', '', '去北风苔原找琥珀崖的图书馆员多纳森。', '营救奥术囚犯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11590, '调查', '$n，我们遇到麻烦了。$b$b我刚刚得知，一位奉命从达拉然赶来的大法师失踪了。我们很自然地联想到，法师猎手与这件事脱不了干系。$b$b时间紧迫，我们必须尽快查明艾瓦诺尔女士的下落并设法营救她。$b$b带上这件装置返回蓝玉营地，对一名临死的蓝玉巫师使用它。它的束缚效果能持续很长时间，足够让你把他押回这里接受调查的了。', '多纳森要你转至蓝玉营地，对一名受伤的蓝玉巫师使用奥术镣铐，并将他带回琥珀崖。', '干得好，$N。$B$B我们会立刻准备让他接受审问。', '你抓到了碧晶巫士了吗，$N?', '', '去北风苔原找琥珀崖的图书馆员多纳森。', '俘获蓝玉巫师', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11593, '亡者的尊严', '那些死难者应该像英雄一样被埋葬，但我们不能把他们葬在牦牛人的圣地里。$B$B我不会让你他们的尸体拖回来，我要你拿上这个到墓地里去。如果你找到死难的车队守卫和工人，就用这火把让他们安息吧。$B$B向死难者致敬，$c！', '钢腭的车队处的步兵沃塔·怒拳要你用火把烧掉10具车队卫兵和车队工人的遗体。', '感谢你，$C!我们是部落，我们绝不会抛下死去的同伴!$B$B这一切本来根本不会发生。都是钢颚那个蠢蛋!', '我在四处观察，不过我们死者的尸体依旧在那边。$B$B尽你在部落的义务，$C!', '', '去北风苔原钢腭的车队找步兵沃塔·怒拳。', '点燃车队卫兵和工人的遗体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11594, '让他们安息', '指挥官斯尔加·钢腭干的蠢事把事情搞得一团糟。他到底是怎么想的？居然让车队穿过牦牛人的墓地！$B$B可事情已经发生了，现在我们必须收拾残局。$B$B博古洛克大王要我尽一切可能帮助远行者达玛·傲蹄，现在远行者要我们设法让他的祖先重新安息。$B$B你说什么，$c？你是不是够$g 种:胆;去完成这个简单的任务呢？', '让20个牦牛人的灵魂安息，幽灵先知或者复苏的远行者都可以。完成任务之后回到钢腭的车队，向步兵沃塔·怒拳复命。', '干得好，$C!你一定在对抗不死族方面非常经验老到。而且，如果你之前没有遇过，那么你现在有经验了。$B$B如果你想要在诺森德生存的话，你会需要这种经验。', '如果你真的做得很棒，为什么我还是可以在那里看到它们?', '', '去北风苔原钢腭的车队找步兵沃塔·怒拳。', '让牦牛人的灵魂安息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11598, '夺回巨石采掘场', '战歌要塞处于10尺厚的钢铁与岩石的保护之下，可外面那座采石场却完全暴露在蛛怪的威胁中。$B$B<拉兹格尔大王指了指西边。>$B$B在它背后，成百上千的天灾军团士兵正在集结，等待着进攻的命令。如果蛛怪利用采石场的地下通道攻入城中，毫无疑问，这里会被阿尔萨斯的天灾军团夷为平地。$B$B我们绝不能坐视不管，我要你主动出击，杀光采石场中的蛛怪。$B$B士兵，鲜血与雷霆！出发吧！', '战歌要塞的拉兹格尔大王要你杀死15只尼鲁巴尔蛛魔。', '你减缓了他们的攻势，但它们的数量却越来越多。你有办法找到它们卵囊的位置吗?', '不是我们在奈幽虫族的隧道系统上面盖东西，而是那些混蛋把隧道朝我们挖!', '', '去北风苔原找战歌要塞的拉兹格尔大王。', '杀死尼鲁巴尔蛛魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11600, '威廉·奥雷顿之死', '威廉的脖子似乎是被某样十分锋利的刀刃砍断了。$B$B经过仔细调查之后，你又发现了一条可以带给莉蕾萨的消息——你发现了一张写有威廉·奥雷顿姓名的征兵通知书。', '将征兵通知书交给北风苔原无畏要塞中的莉蕾萨。', '你认为威廉是被天灾军随意杀死的吗?事情太可疑了。$B$B这一定有什么内幕。我们要找到萨沙理安。', '你和威廉谈过了吗，$N?', '', '去北风苔原找无畏要塞的莉蕾萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11602, '切断虫源', '经过空中侦测，我们发现蛛魔将它们的卵储存在采石场四周的脚手架上。这些畜生还真聪明啊……这样一来，既可以保证蜘蛛卵位于干燥的高处，还能起到减震的作用。$B$B我要你返回采石场，摧毁蜘蛛卵。记住，一颗也不能留下。$B$B这一枚卵能孵化出至少二十只蛛魔呢。', '战歌要塞的拉兹格尔大王要你摧毁10个尼鲁巴尔蛛卵簇。', '它们还在持续增援，尽管我们做了最大的努力。有些事情总得去做，$N。', '你需要摧毁那些卵囊!', '', '去北风苔原找战歌要塞的拉兹格尔大王。', '', '', '', '摧毁尼鲁巴尔蛛卵簇');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11603, '酒中的真相', '军队恐怕是科布恩那个老家伙一生中唯一牵挂和依赖的事物了。他退役之后也一直和军队保持着关系。$B$B将军的名字，每个支队、旅团、特遣队的编号与编制，这些东西他说起来那可真是如数家珍。他一定可以帮上你的忙。$B$B问题是，他的脑子有点不太好使了，性格也很孤僻。要是没有他最喜欢的库尔提拉斯葡萄酒，恐怕你根本没法跟他说上话，只有那种酒才能让他回到当初身为海军远征舰队一员的岁月。$B$B不过，我好几个月来都没有进过这种酒了。上次有一条从库尔提拉斯过来的商船在东北边的海岸触礁沉没了，不如你那里去碰碰运气吧，看看能不能给老科布恩捞上来一瓶两瓶的。', '从无畏要塞东北方的船只残骸附近打捞一瓶库尔提拉斯葡萄酒，把它交给无畏要塞旅店里的老人科布恩。', '嗯嗯嗯…不会太苦…不会太涩…就像过去的日子一样，和小伙子一起在兵营的日子。', '<老人面无表情的抬头看你。>', '', '去北风苔原找无畏要塞的老人科布恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11605, '海象人的先祖', '<当你凝视石像时，脑海中传来一阵若隐若现的声音。>$B$B陌生人，别害怕。我是海象人氏族的先祖阿特卡诺克，生前我是名技艺精湛的工匠，死后便负责守卫冷石采掘场，一晃已经数百年了。$B$B采掘场早已沦为废墟，留下许多未完工的石像，海象人先祖的灵魂也在这里游荡。你愿意帮我为海象人氏族做点事吗？$B$B首先，我必须知道那些游荡的先祖之魂的名字。去石像附近寻找线索吧。', '冷石采掘场外的长者阿特卡诺克要你找到长者克苏克、长者萨加尼和长者塔克勒特的石像。', '<阿特那克长老在你靠近他的雕像时出声欢迎你。>$B$B干得好，$N。有了徘徊的先祖姓名，我们就能继续在攻击中被打断的仪式。不过，在先祖的灵魂被引领到他们的石头前，我们一定得让这些被杀的工匠和萨满灵魂平静下来。否则，这些先祖之灵可能永远都听不到仪式的召唤。', '<遥远的声音重返脑海。>$B$B你找到这些先祖的名字了吗?', '', '去北风苔原找冷石采掘场的长者阿特卡诺克。', '找到长者克苏克', '找到长者萨加尼', '找到长者塔克勒特', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11606, '耐心是我们不需要的美德', '我们可以杀死我们见到的每一只蛛魔，摧毁我们找到的每一枚卵，但是只有彻底炸毁它们修筑的隧道才能阻止这些家伙。那样的话，我们就需要大批弹药，可是大部分库存都让地精和铁匠们拿去制造攻城坦克和武器了。$B$B好在巨石采掘场有一批存货——就埋在层层叠叠的蛛魔排泄物下面。尽快替我取回一些来。', '战歌要塞的军需官霍尔古斯要你找回15箱战歌军需品。', '如果我没算错 - 虽然我常常算错 - 你会需要大概10-20个爆盐深水炸药。$B$B喔耶，你会将这些家伙击回它们的坑道口。', '我们没有多少时间了，$C。', '', '去北风苔原找战歌要塞的军需官霍尔古斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11607, '失落的灵魂', '在采掘场里劳作的萨满祭司和工匠都在那次袭击中被杀害了，灵魂世界因此陷入混乱。除非我们能安抚被杀害的灵魂，否则就无法指引先祖之魂回到各自的家园。$B$B入侵者并未留意到灵魂的存在，他们的蓝玉猎犬却能有所感应并将灵魂禁锢起来。$B$B杀死那些蓝玉猎犬，利用残馀的能量释放被禁锢的无辜者的灵魂。', '冷石采掘场外的长者阿特卡诺克要你释放3名卡斯卡拉工匠和3名卡斯卡拉萨满祭司的灵魂。', '我可以感觉到灵魂世界的动乱开始趋于平静。你做得很好，$N。先祖的灵魂很幸运地能够在需要的时候有你们协助。', '这些无辜的灵魂好吗?', '', '去北风苔原找冷石采掘场的长者阿特卡诺克。', '释放卡斯卡拉工匠的灵魂', '释放卡斯卡拉萨满祭司的灵魂', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11608, '活埋了那些蟑螂！', '东，南，西，北。在这座要塞周围的巨石采掘场内分布着四个尼鲁巴尔虫孔。$B$B<霍尔古斯递给你一只包裹。>$B$B$N，别掉以轻心。一个不小心，你就会被炸得灰飞烟灭。$B$B里面装着高能爆盐炸药。将它们塞进那些尼鲁巴尔虫孔，如果顺利的话，应该能摧毁它们的隧道。$B$B快去吧！', '战歌要塞的军需官霍尔古斯要你利用高能爆盐炸药包摧毁要塞东西南北四个方向的尼鲁巴尔虫孔。', '这会阻挠他们 - 起码我认为这可以阻挡他们。不管如何，你完成了你的任务。一个兽人还能要求什么呢，不是吗?', '如何?', '', '去北风苔原找战歌要塞的军需官霍尔古斯。', '炸毁南部尼鲁巴尔虫孔', '炸毁东部尼鲁巴尔虫孔', '炸毁西部尼鲁巴尔虫孔', '炸毁北部尼鲁巴尔虫孔');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11609, '寻找古器', '被杀害的工匠和萨满祭司的灵魂已经重获自由，我们可以继续先前被打断的仪式了。你必须以海象人萨满祭司的身份来主持仪式，这样的话你就需要一套仪式必备的道具。$B$B没时间打造新的了，你不妨在采掘场中仔细搜寻，说不定能找到在战乱中遗落的道具。$N，小心点，它们都是上百年的古器。你可能得从入侵者手中夺回这些器物。', '将6个海象人仪式道具交给冷石采掘场外的长者阿特卡诺克。', '<你携带着仪式物品来到了阿特那克长老的雕像的面前。>$B$B虽然仪式物品的状态不太好，但勉强堪用。其中有些物品历经了数百年的使用，却被野蛮人盗取和损坏。', '你找回了一整套的仪式物品吗?', '', '去北风苔原找冷石采掘场的长者阿特卡诺克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11610, '先祖的回归', '在你的帮助下，先祖之魂总算有机会重返家园了，卡斯卡拉工匠和萨满祭司精心雕凿的石像便是他们的安息之地。$B$B先前，指引先祖之魂的仪式被入侵者打断了，你必须继续完成那个仪式。带上你从采掘场找回的仪式道具，站在那些刻有先祖之魂名字的石像前，吟诵这首圣歌。$B$B<你的耳畔回荡着一曲艰涩难懂的歌，歌词却牢牢地印在你的脑海中。>', '长者阿特卡诺克要你指引长者克苏克、长者萨加尼和长者塔克勒特的灵魂回到各自的石像中。', '先祖们找到了他们的雕像，他们很感激你，$N。卡斯卡拉的工匠将会回到矿场中继续确保先祖们的延续。至于我们，先祖将会持续的关注你，因为看来你的道路才刚刚开始而已。', '你替先祖们完成祭仪了吗?', '', '去北风苔原找冷石采掘场的长者阿特卡诺克。', '完成长者克苏克的仪式', '完成长者萨加尼的仪式', '完成长者塔克勒特的仪式', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11612, '夺回采掘场', '$c，很高兴见到你。我叫伊塔鲁克，曾经是冷石采掘场的一名工匠。$B$B在准备进行最后一次仪式时，我和同伴正在雕凿新的石像，突然发现空中飘来许多神秘的蓝色平台。$B$B平台着陆后，蜂拥而上的法师猎手就在采掘场中肆意杀戮。如果我们不加以阻止的话，他们就会摧毁所有的石像，卷走海象人的古器。你愿意帮我击败入侵者吗？', '冷石采掘场入口附近的伊塔鲁克要你杀死12名蓝玉财宝猎人。', '现在狩法猎人知道了，卡斯卡拉工匠和其盟友不会轻言放弃矿场，我们必须加把劲彻底击垮他们。$B$B我在卡斯卡拉的兄弟们也遭受了攻击，无法前来支持我们，但有了你的帮助，$N，我们一定能战胜这些掠夺者。', '你开始骚扰矿场中的敌人了吗?', '', '去北风苔原找冷石采掘场的伊塔鲁克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11613, '卡鲁克的誓言', '他们称自己为“克瓦迪尔”。我们世代流传的某个传说就是与他们有关的；我们将他们称为“图克哈里克”——迷雾中的行者。$B$B就是这些迷雾中冒出来的巨人毁灭了我们的村庄，杀害了我身边的每一个人，其中还包括我的父亲埃鲁伊克。$B$B按照海象人的传统，我必须为我的亲人报仇。$B$B但我只是个渔夫，至今还没通过成年试炼……要我去和那些卑鄙的克瓦迪尔人正面对抗完全不可能啊。$B$B如果你能帮我履行这个责任的话，我会对你表示由衷的感激。', '卡鲁克希望你杀死6个斯卡迪尔袭击者和5个斯卡迪尔船工。', '你帮我的族人一个大忙，$N。但是，我还有一件事情想要拜托你。', '你成功了吗，$r?科瓦迪尔是残酷的战士。不可能期待他们会有任何慈悲。', '', '去找北风苔原的卡鲁克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11615, '尼鲁巴尔的秘密', '你快速翻阅日记，寻找着重要信息。在最后一页，你发现了一些非常潦草的文字：$B$B通灵领主。我估计至少有一打。$B$B西边的农场已经成了恐怖的天灾军团生产基地。$B$B数不清的牺牲者。$B$B我想他们已经发现我了。他们想要抓我。我不能被活捉。$B$B剧毒药丸。如果他们想吃我的话，一定会大吃一惊的。$B$B请把这些情报转交给巴尔苏斯。', '把卢瑟尔的日记交给战歌要塞的暗影密探巴尔苏斯。', '<巴素司快速翻到日志的最后一页并开始阅读。>$B$B这是非常糟的消息。一定得马上向地狱咆哮报告。', '他死了吗?', '', '去找北风苔原的暗影密探巴尔苏斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11616, '通知地狱咆哮', '<巴尔苏斯把最后一页撕下并卷了起来。>$B$B立刻把它交给地狱咆哮！同时我会派一队斥候去侦察那些农场。$B$B务必要告诉地狱咆哮：我们需要增援。', '把巴尔苏斯的便笺交给战歌要塞的加尔鲁什·地狱咆哮。', '<地狱咆哮看了日志页。>$B$B就这样吗?', '打扰我是有什么重要的事吗?不要用没意义的事来烦我!', '', '去北风苔原的战歌要塞找加尔鲁什·地狱咆哮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11617, '别让他们逃了！', '你也留意到漂浮在采掘场上空那些蓝白色的平台了吧。它们原本是法师猎手空降到这里的交通工具，如今却被用于运送海象人的古器和石像残片。$B$B我们得在他们撤离采掘场之前阻止他们。$B$B采掘场的挖掘工都携带着炸药，利用它们来摧毁那三座浮空平台吧。他们的首领呆在降落在地面的那座平台上，我们待会再来对付他。', '冷石采掘场外的伊塔鲁克要你摧毁北部平台、东部平台和西部平台。', '那些狩法猎人会发现掠夺我们的矿场偷走我们的东西可没那么简单。有了你的帮助，我们可以夺回矿场，导正现在的情况。', '你成功地摧毁了那些狩法猎人的飞行平台吗?', '', '去北风苔原找冷石采掘场的伊塔鲁克。', '摧毁东部平台', '摧毁北部平台', '摧毁西部平台', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11619, '残忍的贾梅尔', '我的父亲被这群匪徒的首领——残忍的贾梅尔杀害了。那个凶手就住在海滩上的山洞里。$B$B你已经解决了他的手下，去把他也结果了吧，$N。为我的父亲复仇，我会尽全力报答你的恩情。', '卡鲁克希望你转至裂鞭海岸，击败残忍的贾梅尔。', '你办到了，$N!被杀害的巨牙海民之魂终于可以安息了-他们的死已经得到复仇了!', '你打败加迈尔了吗，$C?', '', '去找北风苔原的卡鲁克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11623, '拜访馆长', '馆长因萨维斯统领着入侵的法师猎手部队。海象人世代以狩猎海中和陆地上的野兽为生，但是我从未见过像馆长因萨维斯这样的家伙。$B$B他乘坐的飞行平台就停靠在采掘场的上层，监管着手下法师猎手实施抢劫。$N，我相信你就是先祖派来拯救我们的英雄，希望你能帮我将这帮入侵者永远逐出采掘场。', '冷石采掘场入口附近的伊塔鲁克要你杀死馆长因萨维斯。', '监管者和他的手下一定觉得矿场是个掠夺的好目标，但你证明他们错了。$N，我深深地感谢你，我相信先祖们会持续地看照你。', '你解决了监管者吗?', '', '去北风苔原找冷石采掘场的伊塔鲁克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11625, '纳兹亚的三叉戟', '五百年前，艾萨拉女王将一头名为利维洛斯的巨兽囚禁在裂鞭废墟的海底。现在，这帮野蛮的克瓦迪尔族人竟然想把它放出来！$B$B他们占领了我们的城市，将我的同胞当作祭品，企图唤醒利维洛斯！在杀光了纳迦之后，他们转而屠杀海象人。我要克瓦迪尔为此付出惨痛的代价！$B$B复仇之路相当漫长，不过我会帮你对付他们。克瓦迪尔的首领拉格纳就在裂鞭废墟的东北角，夺取他手中那柄金色的三叉戟，把它带来给我！', '裂鞭海岸的维赫亚要你转至裂鞭废墟的东北角，杀死拉格纳·德拉卡伦并取回纳兹亚的三叉戟。', '太好了!我们可以杀死科瓦迪尔的野兽了!我会让那些畜生知道，绝对不要招惹鳞类女祭司!', '你拿到了三叉戟吗?', '', '去北风苔原找蛇鳞神殿的维赫亚。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11628, '天灾的外衣', '东北方的圣城恩其拉是天灾军团在北风苔原的基地。天灾军团的指挥官从那里派出蛛怪大军将我们层层包围。$B$B如果只是一味地采取守势，我们迟早难逃一劫。在这样的危急关头，偏偏顾问们在战略问题上无法达成一致的意见。杜尔姆主张直接攻入敌阵，而先知埃恩雷则认为应该采取秘密行动。$B$B天灾军团的势力范围仍在不断扩张，这一带的生灵惨遭屠戮。埃恩雷说利用天灾猛犸的毛皮或许可以制作一件伪装用的衣服，以此混入圣城恩其拉。', '将5张天灾猛犸的毛皮交给牦牛村的冬风酋长。', '尽管我讨厌把这些受疾病支配的东西带回村子里来，但我们可以利用它来对付我们的敌人。$B$B<酋长对贤者艾睿做了一个手势，然后对长毛象皮挥挥手让人拿下去。>$B$B在她处理毛皮的时候，我们还需要另一样东西来制成隐匿披风。', '你带回了长毛象皮吗?', '', '去北风苔原找牦牛村的冬风酋长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11629, '返回灵语者身边', '既然你遵照我的吩咐办完了事，我自然会兑现自己的诺言。$B$B将这团精华交给博古洛克前哨站的灵语者斯纳尔芬。如果她够聪明的话，就该懂得如何利用它来执行某种仪式，获知你想要的信息。', '将因波莉安的原始精华交给博古洛克前哨站的灵语者斯纳尔芬。', '英波里安把她自己的元神精华给了你?我可以听到她的哭号的风声了!$B$B我知道一种仪式，可以好好利用它。在她的元神精华开始斑驳以前，我们得加快脚步!', '$N，你回来了，你学到了什么?$B$B那是什么声音?', '', '去北风苔原找博古洛克前哨站的灵语者斯纳尔芬。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11630, '腐化的土地', '先知埃恩雷相信，用圣城恩其拉外被污染的土壤加工过的毛皮所制成的披风可以蒙蔽大多数天灾军团的爪牙。她说你应该能够顺利混入敌方基地。$B$B希望她的话可信吧，这是我们收集情报以策划反攻的唯一机会。$B$B你可以在圣城恩其拉的南部和西部地区找到埃恩雷所需的土块。收集到足够的土块，将它们带回来给我。', '将8块疫病土壤交给牦牛村的冬风酋长。', '<冬风酋长谨慎地收下你收集到的土块。>$B$B我们要尽快把这些交到贤者艾睿的手上。$B$B<酋长咕哝着，假装没有受到那些污染泥土的干扰。>$B$B我们永远也不知道天灾军的指挥官什么时候会对村子发动最后的攻击。', '你拿到了贤者艾睿要用来制作披风的材料吗?', '', '去北风苔原找牦牛村的冬风酋长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11631, '空气的幻象', '$N，我将这团原始精华与你进行了同调。$B$B接下来，你要站在空气图腾面前，集中精神，头脑中只想着先知格雷姆沃克。$B$B风之魂无所不在，它一定能帮你捕捉到远方的景象。', '对斯纳尔芬的图腾使用因波莉安的原始精华来执行仪式，获取先知格雷姆沃克的消息。$B$B完成仪式后，与博古洛克前哨站的灵语者斯纳尔芬谈一谈。', '他们束缚了他的灵魂，$N，我们必须将他的折磨作个结束!$B$B你一定要深入玛格默斯，找到方法释放他!', '等你觉得你已经看得足够，将元神带回来给我。', '', '去北风苔原找博古洛克前哨站的灵语者斯纳尔芬。', '占卜先知格雷姆沃克的命运', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11632, '寒风中的怪兽……', '你拿起了收割者伊斯里克斯的甲壳碎片，并意识到这只是一个开始。即使是在此时此刻，你依然感到胜利是那么短暂。显然巫妖王还控制着成千上万像伊斯里克斯这样的野兽，随时准备向部落发动攻势。$B$B带着你的战利品去见战歌要塞的萨鲁法尔大王，他会对你战胜了这个强大的天灾首领的事感兴趣的。', '带着伊斯里克斯的甲壳去见战歌要塞的萨鲁法尔大王。', '<萨鲁法尔咧嘴而笑。>$B$B这看来很眼熟…卡利姆多联军曾经希利苏斯的沙漠中碾碎了上千只这种臭虫。$B$B这里是另一个地方 - 另一种环境 - 但结果将会是一样的。$B$B<萨鲁法尔看着你。>$B$B你在诺森德将骄傲与荣誉带给了部落，$N。$B$B<萨鲁法尔点点头。>', '你拿的是什么?', '', '去北风苔原找战歌要塞的萨鲁法尔大王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11633, '乔装潜入', '先知埃恩雷做好了披风，你带上它转至圣城恩其拉吧。进入敌方基地后就穿上披风，它可以蒙蔽大多数天灾军团的爪牙。这是收集敌人的防御部署情报以及首领信息的大好机会。$B$B你的任务是侦察圣城中的三座尖塔。记住，虽然大多数天灾军团爪牙难以察觉你的行踪，恩其拉憎恶却能识破这件伪装。', '牦牛村的冬风酋长要你穿上魔法天灾外衣进入圣城恩其拉，侦察鲜血尖塔、苦痛尖塔和凋零尖塔。', '<冬风酋长聆听着你的叙述。>$B$B你所收集的情报可以帮助我们计画对圣城的突击。我们得找出方法击败你发现的军官，并攻进亡域。', '你侦察完天灾军团的堡垒了没?', '', '去北风苔原找牦牛村的冬风酋长。', '侦察凋零尖塔', '侦察鲜血尖塔', '侦察苦痛尖塔', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11637, '卡加尼舒', '猛犸人杀掉我的随从后，就将我拖到洞穴中当作祭品杀害了。执行仪式的北地狗头人名叫卡加尼舒。$B$B虽然你消灭了他手下的萨满祭司，但是我的灵魂依然被禁锢在这里。卡加尼舒将我的躯体制成了物像，我的灵魂因此受到羁绊，无法获得自由。他还利用这尊物像窃取我所掌握的萨满祭司教义。$B$B你必须从他手中夺得物像，并对我的灵魂使用它。卡加尼舒就在附近的洞穴中。$B$B记住，只有这样我才能重获自由。', '夺得卡加尼舒的神像，对先知格雷姆沃克的残骸使用它。$B$B然后将物像还给滞留在犸格莫斯内的先知格雷姆沃克的灵魂。', '我自由了。感谢你，$N。$B$B现在，我有最后一样任务要交给你。', '快一点，$C，在一切太迟之前对我使用神像。', '', '去北风苔原的犸格莫斯找先知格雷姆沃克的灵魂。', '使先知格雷姆沃克重获自由', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11638, '落叶归根', '$N，我的灵魂已经重获自由，请你将我的遗体交给灵语者斯纳尔芬。喏，我的躯壳就躺在地上。$B$B我最后一次看见灵语者是在西边的博古洛克前哨站，我想她应该还在那里吧。', '将先知格雷姆沃克的遗骸交给北风苔原博古洛克前哨站的灵语者斯纳尔芬。', '感谢你从卡甘尼苏手上解放了他的灵魂，并将他的遗骸拿回来。我们没有什么能奖赏你的，如果有什么你中意的就拿去吧。$B$B那么现在，我要将他回归到他所该去的地方。', '你比我预期的还要早回来。你知晓了什么?', '', '去北风苔原找博古洛克前哨站的灵语者斯纳尔芬。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11639, '向犸格莫斯复仇', '大王禁止萨满祭司为我疗伤。他让我好好反省，从失败中吸取教训。$B$B但是，你愿意替我和那些葬身犸格莫斯的伙伴报仇吗？$B$B我听说你答应了灵语者的请求，正要去那里营救先知。$B$B犸格莫斯就在东边。$c，去吧……杀掉猛犸人和他们的狗头人仆从，为了博古洛克前哨站的荣耀而战！', '杀死10个犸格莫斯萨满祭司、5个犸格莫斯劫掠者、3个犸格莫斯碾压者和3个犸格莫斯雷加的配偶。然后博古洛克前哨站，向奥尔托什复命。', '你的行为荣耀了死者，$N。$B$B<受伤的兽人点头并慢慢的吐出一口气。>$B$B或许现在我能再次成为一名战士，如同过去的我一样。', '(兽人语)部落的荣耀，$C。你不可能在这么短的时间内将玛格默斯的所有敌人都杀光了吧!', '', '去北风苔原找博古洛克前哨站的奥尔托什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11640, '力量之语', '从你收集到的情报来看，那些地位较高的军官，也就是所谓的高阶祭司，在三座尖塔中指挥着天灾军团的军事行动。他们手中肯定有进入浮空城、面见最高统领的通行证。$B$B如果不能一举消灭他们的首脑，天灾军团的爪牙就会源源不断地朝我们的村落涌来。尽管杜尔姆迫切地想要与敌人开战，但是我不能将村落的防御力量全部抽调走。$N，杀死高阶祭司的任务就交给你了，把他们的卷轴带回来给我。', '将高阶祭司纳菲塞特的卷轴、高阶祭司塔雷坎的卷轴和高阶祭司安多拉斯的卷轴交给牦牛村的冬风酋长。', '<冬风酋长阅读着卷轴上的文字。>$B$B“Shabtir bakh sokhen。”$B$B如此古老的文字和看似严厉的语言，正是奈幽虫族善用的语言。$B$B“仆从顺从于主人的权威。”这句话将可让你进入亡域。', '如果我们要穿过天灾军团，我们一定得进入亡域，为村民清出一条路。', '', '去北风苔原找牦牛村的冬风酋长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11641, '勇猛的进攻', '从一开始我就建议冬风酋长召集一批骁勇善战的战士向敌人的基地发动猛攻，但是他根本听不进我的劝告。事实证明，他宁愿执行先知埃恩雷的计划，谨慎地采取行动。$B$B我决定不再苦苦空等了。如果冬风酋长这个懦弱的家伙不敢派兵上阵，或许你能让他明白直接开战就能取得胜利。$N，进入圣城恩其拉，杀掉所有胆敢阻挠你前进的敌人。', '杀死15名恩其拉食尸鬼和5名恩其拉通灵师，然后返回牦牛村向杜尔姆·冰皮复命。', '你证明了你的无畏和战斗中的英勇。我相信你能成为一个很好的牦牛人战士。我只希望酋长也能有同样的理解。$B$B幸好我们能有你这样一个盟友，能在天灾军攻陷村庄之前撤离。', '除非你是要回报任务成功，否则就别来吵我。', '', '去北风苔原找牦牛村的杜尔姆·冰皮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11643, '莫布的坦克零件气动装配器', '这些钳子完全不好用，伙计。我需要我的强力坦克零件气动装配器，有了那玩意我才能把这些坦克发动起来！不过，糟糕的是，我把它忘在附近的一处挖掘站里了，就在这码头的另一边。东西在马厩旁的一处被压扁的房子里，你快去把它取回来给我，因为本大爷绝对不想靠近那股迷雾，听见了吗，绝对不。$B$B哦哦，对了，伙计，小心这雾。这迷雾绝对不简单，整片海岸都被它笼罩了。', '回音海岸的莫布要求你为他取回坦克零件气动装配器。', '干得好，老兄!咦，我把备用零件放哪去了……', '你找到了气动式坦克外钻模夹具吗?', '', '去北风苔原找回音海岸的莫布。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11644, '超强度金属板！', '我需要大量金属来修补坦克装甲上的损伤！从加尔鲁什码头到海湾底部，到处都散布着超高强度的金属板。$B$B不过，收集这些金属的时候你千万要小心。这片雾……嗯……它有攻击性！这片雾甚至摧毁了码头与附近的一处海象人小镇。可怜的海象人……', '回音海岸的莫布要求你收集10块超强度金属板。', '干得漂亮，兄弟!咦，我把气动式坦克外钻模夹具放哪去了。', '记住，迷雾不是好东西!', '', '去北风苔原找回音海岸的莫布。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11645, '恶心的北地狗头人！', '那些肮脏的北地狗头人……竟然偷光了我的补给箱！$B$B你没见过北地狗头人？他们长得跟狗头人似的，对猛犸人唯命是从，十足的奴才样。想想就恶心！$B$B有谁愿意帮帮我吗？我真是蠢到家了，竟然将补给箱随手堆在机场北边，还以为那里很安全。$B$B不如你往北边走一趟，如果你能从犸格莫斯取回我的补给箱，我就赏你一笔金子！', '将10箱机灵鬼的货物交给菲兹兰克机场的机灵鬼沃比斯波基。', '喔，$N，你是最棒的!$B$B这些我答应你的酬劳。', '你拿回了我所有的补给品吗，$C?要是没有那些东西我什么事也做不了!', '', '去北风苔原找菲兹兰克机场的机灵鬼沃比斯波基。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11647, '中和瘟疫之锅', '$N，圣城恩其拉中安置了几口瘟疫之锅，这件事让我很是担忧啊。冬风酋长对你收集到的情报以及对局势做出的判断深信不疑。既然你能帮助酋长执行他的计划，能不能也帮我解除瘟疫之锅的威胁呢？$B$B这根图腾可以起到中和瘟疫之锅的作用，你必须在锅的附近使用它。每摧毁一口瘟疫之锅，我们离胜利就更近了一步。', '牦牛村的先知埃恩雷要你利用她的图腾来中和圣城恩其拉中的东部瘟疫之锅、中部瘟疫之锅和西部瘟疫之锅。', '<贤者艾睿从你手中接过图腾。>$B$B图腾有效吗?准备图腾所使用的上古魔法，贤者们已经有许多个世代不曾使用了。所以传承下来的知识，至今只有一小部分仍在使用。', '你对每一个瘟疫大锅都使用了图腾吗?', '', '去北风苔原找牦牛村的先知埃恩雷。', '净化东部瘟疫之锅', '净化中部瘟疫之锅', '净化西部瘟疫之锅', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11648, '说服的艺术', '$r，能得到你的帮助真是幸运。$b$b你要知道，肯瑞托的行为守则规定，无论情况有多紧急，都不赞成采取“极端”措施。$b$b虽然你不是法师议会的人，但是我也希望你采用一些柔和的手段来处理这件事情。$b$b放心去做吧。我们必须尽快查出艾瓦诺尔女士的下落！$b$b我还得忙着整理手边的事情呢。哦，这玩意儿你或许用得着……', '琥珀崖的图书馆员诺曼提斯要你对被囚禁的蓝玉巫师使用催眠魔杖，查出艾瓦诺尔女士的下落。', '太好了!收集到这份情报很要紧。$B$B做得好，朋友。', '所以?你知道伊娃诺女士被关在哪里了吗?', '', '去北风苔原找琥珀崖的图书馆员诺曼提斯。', '调查囚犯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11649, '风暴微粒', '元素之间的争端总算平息下来，但是你和灵语者的问题就比较麻烦。$B$B你也瞧见了，火元素与水元素长期互不相让地死掐，我的仆从因此变得极为暴躁。虽然局势还要一段时间才能恢复正常，但对你来说倒是很有利的。$B$B我要你进入废墟，从风暴元素身上收集风暴微粒，我需要这些微粒才能帮你。', '将5颗风暴微粒交给埃德拉纳斯废墟的因波莉安。', '我替那些暴风的损失感到后悔，但我言出必行…即便是向你这样的凡人所许下的承诺。$B$B现在，让我们看看能否形成一些对你有用的东西。', '一旦你拿到了必要的微粒，我会用这些做成一份我的精华。到时候你就会拿到你所需要的。', '', '去北风苔原找埃德拉纳斯废墟的因波莉安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11650, '还要一些东西……', '你瞧见了吧，我们居然将跑道建在了猛犸人洞穴南面的空地上！$B$B<沃比斯波基压低嗓门嘟囔着，发泄她对菲兹兰克的不满。>$B$B这糟老头居然还有脸叫我去想什么……有创意的方案来解决眼前的危机。你要明白，如果我们不赶快采取行动，那些猛犸人就会蜂拥而上，将我们撕成碎片！$B$B现在是你发挥作用的时候了。$B$B喏，将这份购物单上的东西统统搞到手。谢谢。', '收集机灵鬼的工具、一个超载电容器和一捧洛克纳尔的沙砾，把它们交给菲兹兰克机场的机灵鬼沃比斯波基。', '很好，这才像话!现在我们该做的就是将这些东西组合在一起。$B$B没错，你即将帮我把那东西完成。$B$B拉住你的马匹，既然我都已经拿回我的工具了，这只要一下子就好了!', '为什么我不相信你已经收集到清单上的所有东西呢?', '', '去北风苔原找菲兹兰克机场的机灵鬼沃比斯波基。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11652, '纳萨姆平原', '那么，你准备完成以后，就立刻跳进坦克，并驾驶它进入东南方的纳萨姆平原吧。$B$B进入平原以后，使用坦克的武器系统摧毁你看见的所有天灾军团士兵。比如，如果你前方聚集了大批量的敌人，那就使用“粉碎锤”把它们全部撕碎，哦，还有，沿路也别忘记放下地雷！如果在战场发现我们的人，一定要把他们带回来！哦，还有，补充燃料也不难，那里到处都能找到油桶。$B$B除了消灭敌人和营救我们的人，你还有一件任务要执行，那就是去侦察一下中央的那座建筑物。$B$B如果一切任务都顺利完成，并且你还活着的话，就直接去找地狱咆哮吧！', '在纳萨姆平原使用部落攻城坦克消灭100名天灾士兵，并营救出3名受伤的战歌士兵。同时你也必须鉴别出领导这次突袭行动的天灾军团指挥官。$B$B完成任务之后向战歌要塞的加尔鲁什·地狱咆哮复命。', '克尔苏加德?所以这是真的了-纳克萨玛斯回来了…$B$B也许我低估了你，$N。你替部落做出了一个重大的贡献。大酋长会感到骄傲的!$B$B<加尔鲁什停下来想了想。>$B$B如果说克尔苏加德控制着这些天灾军，谁知道巫妖王还替我们准备了哪些惊喜…我需要一点时间思索这个新讯息，$N。你可以退下了。', '嗯?发生了什么事?', '鉴别天灾军团的指挥官', '去北风苔原找战歌要塞的加尔鲁什·地狱咆哮。', '消灭天灾军团士兵', '营救受伤的战歌士兵', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11653, '大块头', '大功告成！接下来嘛……$B$B我要你带上这件装置，转至北边的犸格莫斯。是这样……我们必须缩小那些怪物的体型，才有可能与他们抗衡。$B$B为了测试缩小射线枪的效果，你得趁它在猛犸人身上生效时杀死目标。对犸格莫斯碾压者或犸格莫斯雷加的配偶使用就行了，猛犸人幼崽就免啦……他们能有什么威胁。', '对5名犸格莫斯碾压者或犸格莫斯雷加的配偶使用超级缩小射线枪原型机进行测试。完成任务后返回菲兹兰克机场，向机灵鬼沃比斯波基汇报测试结果。', '你说没用是什么意思?!$B$B可是…可是…$B$B<卡芙缇开始啜泣。>$B$B好吧，我们可以解决这个问题的。我是个大女孩了。该是跳脱既定想法的时候了!', '你确定你在够多的丑陋怪物身上检测过光束枪了吗?', '', '去北风苔原找菲兹兰克机场的机灵鬼沃比斯波基。', '测试缩小射线枪', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11654, '鲜血尖塔', '你捡起这只装满血液的小瓶，发现它竟然是温热的。看来受害者可能是刚刚被放血，说不定还活着呢。$B$B天灾军团采集血液做什么？过去他们对活着的囚犯可没兴趣。如果能找到血液的来源，或许就能洞察天灾军团的阴谋。', '搜寻鲜血尖塔，找到这瓶新鲜血液的更多线索。', '<牦牛人的雪地追踪者显得十分虚弱，只能勉强回答你。>$B$B我已经…很久。或许…或许…你能够阻止他们…在…之前…', '你…你怎么找到我的?', '', '去找北风苔原的踏雪者戈鲁姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11655, '深入迷雾', '穿越迷雾往北走就是加尔鲁什码头，南面的废墟则是我昔日的家园帕尔依。不过现在，一支名叫克瓦迪尔的维库人部族已经将这两处地方洗劫一空。$B$B这些野蛮的渣滓残忍地杀害了我的同胞，将你的族人逐往内陆。$B$B他们还将帕尔依海象人世代相传的古器据为己有。虽然我们并不是复仇心重的种族，但是正义必须得到伸张！我必须夺回海象人的圣物。进入迷雾区找到它们……', '北风苔原回音海岸的瓦托尔要你杀死克瓦迪尔成员，并取回8件海象人的圣物。', '<华特无法抑制他的悲伤。>$B$B废墟…这就是他们苏醒后所留下的。他们一定要获得教训。', '以血与荣誉为誓…巨牙海民的遗物一定要拿回来。', '', '去北风苔原找回音海岸找的瓦托尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11656, '烧毁船只', '海象人使用的魔法与萨满教的类似。虽然我们信奉元素的方式与你们不同，但是我们也能召唤出强大的力量。$B$B<瓦托尔朝你挥舞着一根火炬状的权杖。>$B$B带上这根海象人火炬返回迷雾区，烧毁克瓦迪尔的船只。有三艘船停泊在北边的加尔鲁什码头，另一艘在南边帕尔依的海岸边。烧毁它们！让那些维库人见识一下海象人的怒火！', '北风苔原回音海岸的瓦托尔要你利用海象人火炬烧毁停泊在帕尔依和加尔鲁什码头的4艘克瓦迪尔船只——毒蛇之喉、库尔达卡、伯尔之锤和伯尔之砧。', '对那些科瓦迪尔人所展开的抵抗，或许正是拯救我们其它营地的族人所需要的。如果那些科瓦迪尔相信会有报复攻击的话，他们或许会在采取行动前三思。', '完成了吗?那些船只都起火了吗?', '', '去北风苔原找回音海岸找的瓦托尔。', '烧毁毒蛇之喉', '烧毁库尔达卡', '烧毁伯尔之锤', '烧毁伯尔之砧');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11658, 'B计划', '别慌啊！虽然射线枪不管用，但我们还有别的法子。$B$B<机灵鬼打了个响指。>$B$B比如说，转移猛犸人的注意力！这样的话，我们就得事先准备好一些东西。$B$B<她将你从头到脚地打量了一番。>$B$B几天前，钢腭的车队为了抄近路，竟然想穿过西边的牦牛人墓地，当然他们都被复活的幽灵杀死了。$B$B我要你从死去的兽人身上扒些衣服什么的回来。顺便搞一面旗帜，别忘了！', '收集10套战歌衣物和一面战歌旗帜，将它们交给菲兹兰克机场的机灵鬼沃比斯波基。', '很好，可是这些衣服臭死了!$B$B就我自己来说，杀了我也不要穿这些破布。但是，我们得从这些衣服里面挑出适合你的，呃…尺寸。', '事情要成功，我们需要一大堆他们的衣服才行，我可不是女红…我们来找找有没有适合你的吧!$B$B然后，由我这样的工程学天才摸一下，吹口气，你看起来就像你要扮演的角色了。', '', '去北风苔原找菲兹兰克机场的机灵鬼沃比斯波基。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11660, '古代水手的号角', '指挥克瓦迪尔军队袭击帕尔依的维库人军官名叫奥拉布斯。在攻陷两座村落之后，他就消失在了迷雾中。$B$B听说奥拉布斯将一只号角送给了克瓦迪尔织雾者。只要吹响号角，他就会出现。$B$B如果我们能从克瓦迪尔织雾者手中夺得号角，召唤奥拉布斯并杀死他，这些野蛮人或许会撤退。$B$B转至南边的帕尔依寻找织雾者吧。', '北风苔原回音海岸的瓦托尔要你夺得古代水手的号角。', '你一定得要使用这个上古海员号角来召唤欧拉布斯。', '找到上古海员号角!', '', '去北风苔原找回音海岸找的瓦托尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11661, '舵手奥拉布斯', '带着这只号角转至西边的战歌防波堤。在防波堤尽头吹响号角，奥拉布斯就会出现。$B$B把他干掉之后再回来！', '北风苔原回音海岸的瓦托尔要你利用古代水手的号角召唤舵手奥拉布斯并杀死他。', '看来损失了他们的副官只造成了一点骚动。他们比之前更愤怒也更具有侵略性了!$B$B<华特叹息。>$B$B你尽力了，朋友。起码你减少了他们的数量，无论如何都应该要给你报酬。', '欧拉布斯必须要被摧毁!', '', '去北风苔原找回音海岸找的瓦托尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11665, '城中的鳄鱼', '你好，伙计。很高兴你能听听我这老家伙所说的话，并且帮我几个忙。$b$b最近有个旅行商人把许多小鳄鱼卖给了这里的孩子们。你要知道，鳄鱼可是一种很凶暴的东西，它们很快就逃光了，全都躲进了城市的下水道里。$b$b去找根最结实的鱼杆，拿一捆最结实的渔线，到暴风城和奥格瑞玛去开工吧，把它们都给我捉回来。我还听说有几只小鳄鱼跑到了别的城市去，但这条消息并不确定。', '为老渔夫巴尔洛带回一只鳄鱼宝宝。你可以在沙塔斯城东北面的希尔米耶湖旁找到他。', '多恶毒的小东西!我相信洛克一定可以拿它做点美味的料理出来。$B$B喔，我只是在开玩笑。$B$B<老人巴洛俏皮地眨眨眼睛。>', '在下水道抓到任何的鳄鱼了吗?', '', '去泰罗卡森林找希尔米耶湖的老渔夫巴尔洛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11666, '黑鳞镖鲈', '你知道不知道金镖鱼？这种鱼在泰罗卡森林的河流里很常见，对这里的祭司们来说是上等的精肴美馔。不过，黑鳞镖鲈呢？恐怕你就没有听说过了吧！$b$b这种鱼非常之聪明，非常之狡猾，非常之难以捕捉。你首先得非常非常有耐心，然后必须得在它咬钩的一瞬间拉线。稍微慢一点，你就会发现钩子上的饵被它们咬走了。$b$b总之，在泰罗卡森林那边的河流里钓钓看吧，让我这老家伙看看你技术怎么样。不要去湖边，因为黑鳞镖鲈只在流动的水中生活。', '为老渔夫巴尔洛带回一只黑鳞镖鲈。你可以在沙塔斯城东北面的希尔米耶湖旁找到他。', '哎呀瞧瞧…你抓到只大尾的呢!这个老人今晚有得吃了。', '今天的垂钓成果如何啊，$g小伙子:姑娘;?', '', '去泰罗卡森林\r\n找希尔米耶湖的老渔夫巴尔洛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11667, '世界上最大的泥鱼', '菲格鲁泥鱼栖息在纳格兰地区的湖底。它们的体形从出生到死亡一直都在成长，很容易长成非常巨大的生物。此外，它们也是出了名的凶猛、狂暴、好斗。$b$b几年前，我曾抓到过一只这种鱼，呃，至少在它挣断了渔线逃跑之前算是抓到了……那几乎可以说是世界上最大的鱼！$b$b总之，一个像你这样有才华的钓鱼高手应该知道自己要怎么做——嘿，朋友，你的命运正在纳格兰的湖水中等着你！', '为老渔夫巴尔洛捕捉到世界上最大的泥鱼。你可以在沙塔斯城东北面的希尔米耶湖旁找到他。', '就是它!我到哪里都认得出那个疤痕。$B$B老实说，我以为他应该……更大。很好，我想我应该放他走，然后改天再试试。', '告诉我你抓到它了。拜托你告诉我你抓住那只鱼崽子。', '', '去泰罗卡森林找希尔米耶湖的老渔夫巴尔洛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11668, '巨型淡水虾', '赞加沼泽的湖里有许多大鱼，你想知道这些大鱼是靠吃什么过活的吗？$b$b是虾！巨型淡水虾。巨石洛克曾教给过我几道用虾作材料的菜谱。$b$b但是呢，虾的体形太小，用鱼钩和鱼线来抓并不方便。所以我要教你一个绝招：你先钓一些刺鳃鲑鱼上来，然后找出那些看起来最肥、鱼腹最肿胀的，把它们的肚子剖开，就能找到几只虾啦。', '为老渔夫巴尔洛带回10只巨型淡水虾。你可以在沙塔斯城东北面的希尔米耶湖旁找到他。', '你对于使用钩和刀都很熟悉了。把那些甜美的珍馐交出来，我就让你尝一口。', '今天的捕获量多少啊，$g小伙子:姑娘;?', '', '去泰罗卡森林找希尔米耶湖的老渔夫巴尔洛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11669, '魔血鲷鱼', '嘿嘿，我这个老家伙马上又要出发去狩猎了。我的目标是一只在艾萨拉海域游弋的大鲨鱼。$b$b不过，问题是，我现在需要一些能够涂在渔叉上、并且即使是泡在水里也不会稀释的毒液。想要制作这种毒药呢，我就需要一些魔血鲷鱼的毒囊，这一种非常稀少的剧毒鱼。$b$b要想找到它，你恐怕只有去影月谷或是地狱火半岛上那些可怕的水域里看看了。给我带回来一条这种鱼吧，我这个老渔夫一定会非常高兴的。', '为老渔夫巴尔洛带回一只巨型魔血鲷鱼。你可以在沙塔斯城东北面的希尔米耶湖旁找到他。', '那是我见过最大尾，最丑陋的鱼了。我根本不敢想象你是用什么来诱捕它的。$B$B把那条野兽放地上就好，一旦我确认它真的死了，我就会去处理它了。', '魔化之血是演化中的奇迹。它能存活于任何的液体中，就算是熔岩也行，渔夫则是它唯一的自然克星。$B$B你的猎捕行动有任何成果吗?', '', '去泰罗卡森林找希尔米耶湖的老渔夫巴尔洛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11670, '是兽人干的！真的！', '我费了好大劲才将这些衣料拼凑成一件战歌兽人伪装。别担心，我在衣料中添加了去年万圣节剩下的好东西，它应该非常结实。啊，我真是个天才！$B$B喏，袋子里装着兽人伪装和你取回的那面旗帜。带上它转至犸格莫斯，杀死猛犸人的酋长犸格莫斯雷加。$B$B你必须在伪装状态下将旗帜插在犸格莫斯雷加的尸体上，令猛犸人的注意力转移到战歌兽人身上。', '伪装成战歌兽人，将战歌旗帜插在犸格莫斯雷加的尸体上。完成任务后返回菲兹兰克机场，将伪装还给机灵鬼沃比斯波基。', '喔呵呵，你做到了!$B$B很好，现在那些讨厌的猛玛象人和他们的烦人跟班应该会把注意转向部落。$B$B我该怎么报答你，$N?', '都完成了吗?你完成了那些下流的手段并且陷害博格洛克前哨的兽人吗?', '', '去北风苔原找菲兹兰克机场的机灵鬼沃比斯波基。', '将战歌旗帜插在犸格莫斯雷加的尸体上', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11671, '与时间赛跑', '这么说，艾瓦诺尔女士果然是被劫持了。$b$b$r，我们必须搭救她。$b$b我得待在这儿做好营救准备。那么，又要麻烦你帮我从莎尔兰德手中夺回牢笼的钥匙了。我们对莎尔兰德所知甚少，只知道如果她的魔法护盾完好无损，就可以免疫一切伤害。$b$b不过，这捆特殊的炸药应该能突破护盾，帮助你完成任务。夺得钥匙后就回来找我。$b$b$n，时间紧迫，艾瓦诺尔女士正在痛苦中煎熬！', '琥珀崖的多纳森要你使用蓝玉护盾炸药摧毁蓝玉营地的魔法护盾，然后击败莎尔兰德，夺取她的钥匙。', '坏了?$B$B让我看看……', '你取得沙尔伦的钥匙了吗?', '', '去北风苔原找琥珀崖的图书馆员多纳森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11676, '慈悲为怀', '他们把一些还没来得及杀害的士兵囚禁在农场四周的牢笼里。我们设法偷到了一些钥匙，但无法在不被发现的情况下接近这些囚犯。$B$B我们需要你的“天赋”帮忙，去拿到那些钥匙并释放这些囚犯。去把那些通灵领主和畸变者揍扁，拿走他们的钥匙。用这些钥匙去释放天灾军团的囚犯。', '战歌农场哨站的暗影密探卡纳留斯要你去释放5名天灾囚犯。', '每拯救一个囚犯，我们该解决的不死畸形者就少一个，$N。你大大的帮助了部落。', '救救那些囚犯!', '', '去找北风苔原战歌农场哨站的暗影密探卡纳留斯。', '释放天灾囚犯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11679, '重铸钥匙', '突发状况真是层出不穷……我们不能再耽搁时间了！$b$b我本来不愿意麻烦苏雷斯塔兹大人的，但他是我们营救艾瓦诺尔的唯一希望。$b$b将钥匙碎片交给他，希望他的心情不算太差。$b$b$c，时间紧迫。我们的突击队已经整装待发了。', '多纳森要你与琥珀崖的苏雷斯塔兹谈一谈。', '你在这里耍的小把戏没有任何意义…$B$B你和你的达拉然盟友只在意那些琐碎的事情，却没有想过这个世界的未来即将要被撕碎。$B$B然而，这也许能提供我的龙群一些必要的消遣。$B$B把钥匙给我瞧瞧……', '你胆敢靠近我，凡人?$B$B为了你尚未出世的孩子，祈祷你的理由是值得的。', '', '去找北风苔原的苏雷斯塔兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11683, '坠落的浮空城', '西边那座坠落的浮空城中肯定有大批天灾军团的成员。$B$B$c，我要你杀入塔尔拉玛斯，消灭那些巫妖王的仆从。你可以在浮空城以及附近的池塘一带找到他们的踪迹。', '在塔尔拉玛斯和溃烂之池杀死任意20名天灾军团成员，然后向亡者之穴以南的先知赫米萨复命。', '谢谢你，$N。$B$B巫妖王和他的天灾军团真是诺森德的恶梦。直到天灾军团真正死去，而巫妖王的存在被消灭之前，我们都不能懈怠!', '我想你不可能在这么短的时间之内就杀掉那么多的天灾军吧?', '', '去找北风苔原的先知赫米萨。', '摧毁塔尔拉玛斯的天灾势力', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11684, '侦查虫孔', '你感觉到地表的震动了吗？$B$B天灾军团的蛛魔们正隐藏在我们脚下的深处。它们已经渗入了西南方的喷泉平原，并持续骚扰着冬风酋长派出的巡逻队。$B$B<这位牦牛人长老递给你一卷看起来非常古旧的地图。>$B$B或许巡逻队没能找到的东西，你这位冒险者可以独自找到。带上这张地图转至喷泉平原，将所有蛛魔虫孔的位置都标记出来。', '牦牛村的玛罕宗父要求你使用喷泉平原地图标记出南部虫孔、西北部虫孔和东北部虫孔的位置。', '<主父玛哈接过地图，不过毫无检视的动作。>$B$B我们之后可以参考你的资讯，一旦我们准备好要实行计画。', '你纪录下坑道口的位置了吗?', '', '去北风苔原找牦牛村的玛罕宗父。', '标记南部虫孔的位置', '标记东北部虫孔的位置', '标记西北部虫孔的位置', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11685, '元素之心', '那么，现在终于清楚这些蛛魔虫孔的位置了，我们应该立刻把它们全部封上，以阻止天灾军团的进犯。驯风者巴兰知道如何束缚元素、利用元素的力量摧毁那些地下通道，不过恐怕她需要你提供一些帮助。$B$B穿越村子附近东南方的冰冻平原，在海岸边有大量的冻土元素。我想，你在那里能采集到许多巴兰急需的元素之心。', '将5份元素之心交给牦牛村的驯风者巴兰。', '这些应该足以创建一个强大的元素，不过单单只有石头可无法给予我的元素生命。', '主父玛哈告诉我你愿意协助去破坏通道。', '', '去北风苔原找牦牛村的驯风者巴兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11686, '战歌农场', '根据卢瑟尔的记录，那些在附近四处游荡的怪物就是天灾军团从这个地方生产出来的。$B$B<伊克里斯打了个寒战。>$B$B这些怪物曾经是兽人……牛头人……$B$B在制定详细的作战计划前，我们需要更多的情报。我要你去天灾军团防守最严密的三个地方侦察情况：西南方的战歌粮仓，正西方的托普的农场和北方的战歌屠宰场。$B$B侦察清楚以后立刻回来向我复命。', '战歌农场哨站的暗影密探伊克里斯要你去侦察战歌粮仓、托普的农场和战歌屠宰场的情况。', '这远比纪录在卢瑟的日记上的情况还要糟糕。他们已经将这个地方布满了天灾军团，且正在感染每一样他们碰触的事物。$B$B<艾寇里斯点头。>$B$B情况变糟了 - 如果你能够料想到的话……', '你搜查过农场了吗?', '', '去找北风苔原战歌农场哨站的暗影密探伊克里斯。', '侦察战歌粮仓', '侦察托普的农场', '侦察战歌屠宰场', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11687, '博士和巫妖领主', '他们俩……必须……除掉。$B$B博士……巫妖领主……就在浮空城里……上面。找到他们……杀……$B$B否则……一切……都晚了……', '杀死拉佐格林博士和巫妖领主基尔温特，然后向北风苔原亡者之穴以南的先知赫米萨复命。', '鬃角死了?!$B$B我真不应该让他自己去那里的。', '$N，你回来了!', '', '去找北风苔原的先知赫米萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11688, '该死的猪', '看看吧，我漂亮的科多兽正在无助地挣扎，想要摆脱那些肮脏的死猪！帮我争取一些时间，$r。我想我可以治好科多兽的病，但你不能让这些死猪靠近它们，否则它们就再也不用治了！$B$B去把那些死猪送回坟墓——我是指永远地送回去！', '战歌农场哨站的农夫托普要你杀死10只亡灵猪。', '我想我成功了，$r!', '我需要更多的时间!别让那些猪靠近我的科多兽!', '', '去北风苔原找战歌农场哨站的农夫托普。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11690, '把它们活着带回去', '拿着这副笼口，$N。你一定注意到我在嚼子里放了一小片药剂。一旦科多兽咬下嚼子，它们的疫病就会被治愈。治好它们以后，你还要把它们带回家。它们会很虚弱，所以你在控制的时候一定要温柔一点。$B$B把我的宝贝们带回家吧，$N！我还要提醒你一件事，你只有十分钟！笼口里的解毒剂只能维持这点时间。', '战歌农场哨站的农夫托普要你帮忙解救8只被感染的科多兽。', '你是个真正的英雄，$N。没有你，我的科多兽就会死在那里了。我由衷地感谢你，也替所有即将使用这些科多兽巩固我们在诺森德生活的士兵和工匠们感谢你!', '帮它们逃出那些天灾军团受感染的田地!', '', '去北风苔原找战歌农场哨站的农夫托普。', '解救科多兽', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11695, '元素愤怒号角', '我可以用这些毫无生气的石块制造出类似元素生物的东西，不过为它赋予生命就比较麻烦了，所以我需要一点点运气和你的帮助。$B$B在牦牛人的传说中，有一件被称为元素愤怒号角的神器，伟大的牦牛人英雄一直在寻找它。喏，这就是写有那个传说的卷轴，你可以从中发现关于号角碎片的线索。我不知道这些线索是不是真的，但这时候了，也只好撞撞运气。如果传说是真的，那么号角的碎片可能在村子北边和西南边的洪荒平原上。', '从布戈布咕酋长和咕戈布咕酋长手中夺得号角的上半截和号角的下半截，将它们交给牦牛村的驯风者巴兰。', '<巴拉从你手中收下角的块片并开始试着将它们合在一起。>$B$B风暴之蹄会以你为傲，$N。或许当我们解决掉天灾军团，我会带着这个角转至风暴之蹄的墓地朝圣。', '你成功找到号角了吗?传说是真的吗?', '', '去北风苔原找牦牛村的驯风者巴兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11699, '我被困在笼子里了……', '那些教徒利用魔法诱使我踩入陷阱。瞧，这牢笼连个门都没有。幸好他们还不知道我是机场的首席传送工程师！$B$B只要你肯帮忙，我很快就能逃出来。当然，这件事稍微有点麻烦。$B$B你得从食尸鬼那里搞到引擎核心水晶，从某个博士手中夺得魔法陀螺仪，还要从顶层的巫妖领主那里抢到导航天灾石。$B$B将这三件零件交给我，我就可以制造一台传送装置，利用它返回机场。哼哼，这就是侏儒的逃跑方式！', '将引擎核心水晶、魔法陀螺仪和导航天灾石交给塔尔拉玛斯的丁奇·火哨。', '太杰出了!现在只要小小的调整一下这里，还有转一转那里……', '你拿到所有东西了吗?', '', '去找塔尔拉玛斯的丁奇·火哨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11705, '愚蠢的努力', '这真是发疯了。他们怎么能指望我们能干掉一个天灾军团的通灵领主和他数不清的手下？$B$B<盖特莱叹了口气。>$B$B既然伊克里斯派你来，那么他一定相信你能完成这个壮举。也许你今天能创造奇迹呢，嗯？$B$B等你准备好了以后，我们就下去和瓦雷杜斯开打。$B$B如果恶战以后我们还能留下一口气的话，你就到战歌要塞去向地狱咆哮复命吧。', '帮助盖特莱击败战歌农场的残忍的瓦雷杜斯。$B$B完成任务后向加尔鲁什·地狱咆哮复命。', '如同我想的一样，你凯旋归来了!我对萨鲁法尔说过你做得到的。$B$B<地狱咆哮故意咕哝着。>$B$B也许这可以让那个老家伙知道他并不总是对的，是吧?', '<地狱咆哮瞠目结舌地看着你。>$B$B我听到有关天灾死灵领主的消息是什么?', '击败残忍的瓦雷杜斯', '去北风苔原找战歌要塞的加尔鲁什·地狱咆哮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11706, '天崩地裂', '我利用这只元素愤怒号角创造出了奥卢维斯，并将它束缚在了号角内。你带着它转至喷泉平原，在最南方的虫孔旁吹响这只号角，奥卢维斯就会响应你的召唤，出现在你的面前。$B$B奥卢维斯制造出的大地震足以使蛛魔的隧道体系彻底崩塌，并就此终止它们那没完没了的偷袭。不过，你要小心一点，那些蛛魔的头目很有可能在地震发生时出现在你面前。这也正好，如果地震还不能使它们停止进攻，那么再失去头目，它们恐怕就真的要大伤元气了。', '牦牛村的驯风者巴兰要求你使用元素愤怒号角将蛛魔的虫孔弄塌，并击败克里卡希斯。', '你对抗奈幽虫族的努力给予我们暂时免于天灾军团的强力攻势。感谢你的成就，让我们可以无需担心来自西边的攻击而进攻东北边的天灾堡垒。$B$B至于这个号角，我将会保护它，一直到下次我们需要它的力量之时。风暴之蹄付出了他的生命来守护这个号角，我们无法承受再一次的遗失。', '你释放了艾鲁威斯并摧毁奈幽巴的攻击了吗?', '', '去北风苔原找牦牛村的驯风者巴兰。', '', '摧毁蛛魔隧道', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11708, '机械侏儒', '你既然来了，就先听我讲讲当前的情况。$B$B听完之后，去外面找副指挥官金吉·温纳特谈一谈。从现在起，她负责处理所有的事务。', '听菲兹兰克·铁阀讲诉当前的情况，然后与菲兹兰克机场的金吉·温纳特谈一谈。', '老人派你来找我，是吗?他跟你讲了所有发生的事吗?$B$B很好…我们开始动手处理吧!', '嗨你好。', '听菲兹兰克陈述当前的情况。', '去北风苔原找菲兹兰克机场的金吉·温纳特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11710, '转换器怎么了？', '备用零件散落在东边的滚烫熔池和喷泉平原……甚至连那座泵站附近都有。替我收集一些零件。我或许能利用它们修好这台设备的传出装置，另外还得调整传入装置。$B$B我实在不想再出什么事故了……', '将15个菲兹兰克备用零件交给菲兹兰克机场的墨尔杜·旋轮。', '太好了，$C!这些零件看起来还可以使用。$B$B现在只要能搞懂这个混蛋机器该怎么修理……', '要让这个玩意儿维持运作需要非常多备用零件。$B$B拜托你告诉我，你带了所有需要的东西回来。', '', '去北风苔原找菲兹兰克机场的墨尔杜·旋轮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11711, '逃兵快递，30分钟送到否则免费', '这些天来，逃兵络绎不绝地涌来。收容所哪儿来那么多房间关押这帮蠢货呢？你瞧，我们的猪因为空间变窄都有些瘦了！$B$B<诺克高声大笑。>$B$B我要你押送一个懦夫转至要塞东边的十字路口并鸣响信号枪，他们的队长就会来领走这个胆小鬼。$B$B交接工作完成之后，就向东边路上的斥候图古克报到吧。', '将联盟逃兵押送到战歌要塞东边的十字路口，鸣响战歌信号枪通知联盟。$B$B顺利完成押送任务后向斥候图古克报到。', '干得不错，$N。我们现在可以少养一个下流没用的联盟人渣…$B$B如果你想找些工作，这附近的牛头人和血精灵需要一些帮忙。$B$B当然我们这里也有不少问题得处理……', '<敦苟克嘀咕了几声。>$B$B你有好好照料那些逃兵吗?', '交接联盟逃兵', '去北风苔原找血孢平原的斥候图古克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11712, '物质转换注射器', '菲兹兰克应该告诉过你这附近的侏儒完全被转变了吧？机甲专家麦卡佐德将某种感染源植入侏儒体内，逆转了“血肉诅咒”的效果，将他们变成了机械侏儒！$B$B我们可以再次逆转诅咒，让他们恢复正常。对机械侏儒的尸体使用这个物质转换注射器就行啦。$B$B希望这个法子管用，这样我们就能将他们传送到别的地方去了。$B$B$N，你觉得呢？', '菲兹兰克机场的金吉·温纳特要你对6名菲兹兰克机械侏儒使用物质转换注射器。', '你办到了…这有效!$B$B我简直不敢相信你能救了这么多人。我们真幸运能有你帮忙!', '你治疗了几个机械地精，$C?', '', '去北风苔原找菲兹兰克机场的金吉·温纳特。', '传送走恢复正常的菲兹兰克侏儒', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11713, '侦查虫孔', '菲兹兰克早先派出了一支空中侦察部队去探察喷泉平原南部的虫孔位置，可他们一直没有回来。我们没有更多的时间来等待这些情报了，所以现在必须立刻派人徒步去找到那些虫孔。$B$B我知道这非常危险，所以我会付给你非常可观的报酬。拿上这张地图，到了平原上之后，将你遇到的每一个虫孔的所有重要信息都标在上面。', '菲兹兰克机场的阿布尼·扭矩要求你使用喷泉平原地图标记出南部虫孔、西北部虫孔和东北部虫孔的位置。', '<艾伯奈接过你手上的地图，然后仔细的检视。>$B$B太好了!这全都是我们着手工作所需要的讯息。', '你纪录下坑道口的位置了吗?', '', '去北风苔原找菲兹兰克机场的阿布尼·扭矩。', '标记南部虫孔的位置', '标记东北部虫孔的位置', '标记西北部虫孔的位置', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11714, '清除北地狗头人', '你愿意帮我清理这片土地吗？北风苔原到处都是肮脏的渣滓！你走到哪儿都能看见狗头人，狗头人，以及更多的狗头人！光是他们身上的臭味就够我受的了！$B$B$N，帮我除掉这些可憎的家伙，我会好好奖赏你的。', '血孢平原的斥候图古克要你杀死8个血孢收割者、5个血孢点火者和2个血孢烘烤者。', '做得很好，$N!谢谢你!', '这个工作真臭……', '', '去北风苔原找血孢平原的斥候图古克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11715, '石油资源', '我计划建造一台能制造出高频率高幅度地震的机器，用它来彻底震塌天灾蛛魔用于布置兵力的地下隧道网。当前，建造计划的最大难题在于燃料，我们的主钻井系统状态不太好，所以必须另想办法为它收集足够的燃料。$B$B外面喷泉平原的东南方地区有许多冒着泡的油塘，如果你能在那些油塘里采集到足够的油，我就可以从中提炼出适合这台机器的燃料。$B$B你只需要把这个收集器放近池边，它会自动将油吸进油箱的。', '菲兹兰克机场的阿布尼·扭矩要求你利用移动采油器收集8桶油。', '<艾伯奈开始吸取收集器的油箱。>$B$B手工进行提取会搞得脏兮兮的，但我可以很快地拥有成品。在这段时间内，我们需要更多的原料来完成这个机器。', '你有燃料了吗?', '', '去北风苔原找菲兹兰克机场的阿布尼·扭矩。', '收集燃油', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11716, '奇妙的血孢', '$n，我们正在见证自然界的奇迹。离我们几步之遥的地方，竟然生长着某种从未被记录在册的植株！我猜测就是血孢改变了周围的自然环境。$B$B我从附近的雄性植株上采集了一些花粉，不过还需要雌蕊才能进行人工授粉。你去帮我收集一些血孢心皮如何？在周围的大型植株附近就可以找到它们。$B$B当心那些狗头人守卫！它们不会让你轻易得手的！', '血孢平原的血法师劳莉丝要你收集10片血孢心皮。', '漂亮!真是漂亮!$B$B<罗瑞斯对着一朵血孢心皮铺了一阵花粉雾，接着念出一段咒文。>$B$B呃…我不懂。除非…啊当然啦!', '测试一定得继续下去!', '', '去北风苔原找血孢平原的血法师劳莉丝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11717, '授粉的巨蛾', '我就知道！这种植株是以北风苔原的血孢巨蛾为媒介完成授粉的。那么这些蛾子体内一定含有某种类似催化剂的物质吧。$N，我都想明白啦。难怪狗头人不杀这些蛾子，还大老远地跑来保护它们！这些小蠢货看来早就知道了这一点！$B$B那么，我们需要一些蛾子身上的花粉！怎么样？看在科学研究的份上，帮帮我吧！', '血孢平原的血法师劳莉丝要你收集5份血孢巨蛾花粉。', '啊哈!$B$B<罗瑞斯将孢蛾花粉洒在血孢心皮上。>$B$B瞧!', '花粉就是关键!', '', '去北风苔原找血孢平原的血法师劳莉丝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11718, '猛犸的毛皮', '为了强化地震的幅度以保证弄塌那些隧道，我彻底地改装了机器人的基本骨架。不过，这样一来，整台机器也就过于精密和脆弱了，而且对于诺森德那寒冷的气候也比较敏感。$B$B我打算使用本地猛犸象的厚重皮毛包住机器人的外层装甲，起到保温和缓冲的作用。这些猛犸一般漫步在机场南部和喷泉平原临近的地区。给我带回它们的毛皮，这样机器就算是大功告成——那些蛛魔就要倒大霉啦！', '菲兹兰克机场的阿布尼·扭矩要求你为他带回6张厚猛犸皮。', '<艾伯奈检查那些毛皮，毛皮上的灰尘让他不停地咳嗽。>$B$B难道这些动物都不会想要保持干净吗?这些东西真的是超脏的。嗯，我想我最好开始清理它们。没有时间可以浪费了。', '尽快把毛皮带来给我!没有它们就没办法完成飞行器!', '', '去北风苔原找菲兹兰克机场的阿布尼·扭矩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11721, '折磨者迦莫斯拉', '猛犸人和狮子一样，属于群居生物：一到两名雄性统治着族群中的所有雌性以及幼崽。西边那座名叫迦莫斯的巢穴中就盘踞着一群猛犸人，他们的首领就是迦莫斯拉。迦莫斯拉在族群繁衍后代的过程中扮演了重要的角色，因此我们必须除掉他。$B$B带上血孢花的粉末进入迦莫斯。利用它削弱迦莫斯拉的力量，然后杀死他！把他的像章带回来给我。', '杀死迦莫斯拉，将他的像章交给北风苔原血孢平原的普雷玛·巨角。', '做得太棒了，$N!你想要拿着这个野兽的头颅荣耀罗瑞斯和我，并将它呈现给地狱咆哮吗?他必定会非常高兴。', '这种粉末可用来削弱所有的猛玛象人。这就是为什么本区的胆小鬼如此保护它的原因。', '', '去北风苔原找血孢平原的普雷玛·巨角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11722, '迦莫斯的战利品', '$N，我们可不敢把功劳算在自己头上，部落能取得这样的胜利全得靠你呀。是你冒着生命危险测试血孢的效果，也是你除掉了迦莫斯拉。$B$B返回战歌要塞，将迦莫斯拉的徽记交给加尔鲁什·地狱咆哮吧。', '将迦莫斯拉的徽记交给战歌要塞的加尔鲁什·地狱咆哮。', '<地狱咆哮单手举起了甘默斯拉的头颅，并朝甘默斯拉的脸吐了口口水。>$B$B他们会得到教训，$N…他们全都会得到教训。千万不要小看部落……', '这么快就回来了?', '', '去北风苔原找战歌要塞的加尔鲁什·地狱咆哮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11723, '天摇地动！', '小心点，这可是一台能把我们从蛛魔的威胁中拯救出来的机器！$B$B<阿布尼带着骄傲的神情向你展示着最终的成品机器人。>$B$B带上这个控制器，立刻到喷泉平原最南端的蛛魔虫孔附近去，使用遥控器启动地震器5000型，它会自动完成剩下的一切工作。$B$B如果它引起的震动把蛛魔的头目引来了，你也不要慌张。毕竟，杀掉它对我们彻底瓦解它们的攻势更有帮助。', '菲兹兰克机场的阿布尼·扭矩要求你使用地震器5000型将蛛魔的隧道网弄坍塌，并杀死克里卡希斯。', '<艾伯奈热切的聆听着你报告你和摇震器5000型的成功。>$B$B嘶轴将会很乐意听到这个讯息!而且谁知道，或许我们制作一个你的机械人也说不定!', '那么，你部署好摇震器5000型了吗?', '', '去北风苔原找菲兹兰克机场的阿布尼·扭矩。', '', '部署地震器5000型', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11724, '巨大的蛾卵', '这枚蛋似乎有着非同寻常的意义，附近横躺着的尸体就是证据。蛋壳上贴着的标签表明，收货人是血孢平原的血法师劳莉丝。血孢平原就在东边！$B$B将这枚蛋交给那位血法师吧。', '将发光的巨蛋交给血孢平原的血法师劳莉丝。', '艾尔克尔死了，是吗?可怜…至于这颗蛋，对我们来说再也没有用途了。我们现在有更大的问题要处理。', '你好!', '', '去北风苔原找血孢平原的血法师劳莉丝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11726, '一点辣椒', '那群狼被困在飞行器的残骸中好些天，恐怕它们已经饿得头昏眼花，将我们辛辛苦苦拍摄下来的微缩胶片都吞进肚里啦。$B$B我倒是有法子回收胶片，但我需要你的帮助。$B$B洪荒平原南边和东边居住着一种被称为鳄鱼人的生物。它们使用某种其辣无比的辣椒来烹制食物，其它生物若是吃下这种辣椒，就会引起严重的肠胃不适，然后……嗯嗯……你知道啦。如果你能从蒸汽鳄鱼人或游荡鳄鱼人身上收集到足够的辣椒袋，我就可以做出一顿“美味”给那些狼吃，然后……嗯嗯。', '滚烫熔池的“尾旋”伊吉·齿钉要你去收集4个鳄鱼人的辣椒袋。', '<艾基掩住鼻子倒出那些香料，声音充满了鼻音。>$B$B现在我们有了必须的材料，可以用紧急口粮调配出给狼群的饵食。', '你拿到那些香料包了吗?', '', '去北风苔原找滚烫熔池的“尾旋”伊吉·齿钉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11728, '狼的排泄物', '你就算再饿，也别动那些饵。瞧见那群被困在油塘中的狼了吧？将饵食丢在它们附近就行了，这帮饥肠辘辘的野兽连胶卷都吃，一定抵挡不了饵食的诱惑。$B$B接下来就耐心等待吧。等到它们有了反应之后，你就开始仔细搜索那些……该怎么讲……包裹着胶片的东西。$B$B如果我特制的狼类遗留物搜查器在身边，本来可以借给你用的，可惜我把它丢在机场了。恐怕你必须……怎么讲……用一些传统方式来进行搜索了。', '滚烫熔池的“尾旋”伊吉·齿钉要你带回8张微缩胶片。', '<艾基捏着鼻子收下微缩胶卷。>$B$B恶心，嗯，我们已经按照紧急守则的第八条第二点的段落B行动，并且收回了胶卷。不过，紧急守则并没有说我有责任得清理胶卷。', '你找到胶卷了吗?', '', '去北风苔原找滚烫熔池的“尾旋”伊吉·齿钉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11729, '超声波螺丝刀', '你在机械侏儒体内发现了这件东西。$B$B它的结构看上去相当复杂……或许你应该将它交给机场的工程师看看——比如机灵鬼沃比斯波基？', '将超声波螺丝刀带回菲兹兰克机场，交给机灵鬼沃比斯波基。', '我的螺丝起子…你找到了我的螺丝起子!我还在想这东西丢到哪里去了。$B$B嗯，你说，你在他们的机器人体内找到它?这倒是给了我一个点子……', '嗨!', '', '去北风苔原找菲兹兰克机场的机灵鬼沃比斯波基。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11730, '主与仆', '超声波螺丝刀简直是万能工具，它可以用在所有的机械物体上！$B$B返回滚烫熔池，干掉一些麦卡佐德的机器人。你只需要对机器人的残骸使用螺丝刀，它们就会转而投靠我们——虽然这种友好状态只能持续很短的一段时间。$B$B不过这玩意儿对机械侏儒不管用，别去招惹他们。$B$B在使用螺丝刀之前，记得从机器人的尸体上捞一笔！', '使用超声波螺丝刀为15个机器人重新编程，然后将超声波螺丝刀带回菲兹兰克机场，还给机灵鬼沃比斯波基。$B$B在改编程序之前，记得从机器人的尸体上顺手捞点什么。', '哇喔!你还将螺丝起子原封不动的带回来了!$B$B重新设定那些机器人在对抗齿轮大师梅卡佐德的战争中结果竟是有利于我们的强大优势。我想你从中学到了一点东西。', '你已经重设了几个机器人啊?', '', '去北风苔原找菲兹兰克机场的机灵鬼沃比斯波基。', '对机器人进行重新编程', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11788, '左膀右臂', '好啦，还差最后一步，我们就可以发动攻击了……要击败麦卡佐德，就必须先除掉他手下的副官！$B$B托奇、ED-210、麦克斯·布拉斯托和研磨者分别驻守在西部哨站、北部哨站、中部哨站和南部哨站。$B$B要让它们露面，只需转动哨站的阀门，破坏那里的设施就行啦——你不用理会它们到底要在那里干什么，这不重要。你应该不难找到那些哨站，上面都安置着旋转灯呢。', '摧毁托奇、ED-210、麦克斯·布拉斯托和研磨者，然后返回菲兹兰克机场向金吉·温纳特复命。', '哇，你活下来了!$B$B我猜，现在只剩下齿轮大师梅卡佐德要对付了。', '搞定齿轮大师梅卡佐德的手下了没?', '', '去北风苔原找菲兹兰克机场的金吉·温纳特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11789, '急需帮助的士兵', '嘿，说你呢！快来，我需要你的帮助。如果我们不快一点的话，这个士兵就会被地穴恶魔的毒液给干掉了。$B$B我已经设法减缓了毒液的发作速度，但没有合适的解毒剂，就无法彻底治好他。$B$B我已经预定了新的解毒剂，斩雷号这次去南方的时候应该运回来了一些。请你到它的货舱里去找一箱急救用品。$B$B要快，$c！我们已经无法承受任何非必要的减员了。', '无畏要塞外的医师哈索恩要你到斩雷号的货舱里去找到急救物资箱，然后带一份哈索恩的解毒剂回来。', '感谢你，$N。这个人可能会需要一段时间才能康复，但我们起码不会失去他。$B$B你说什么?你在风暴破碎者发现教徒?你最好赶快通知其它人…最好还要有证据。', '抗毒剂…你找到了吗?', '', '去北风苔原找纳萨姆沙地的医师哈索恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11792, '圣光的敌人', '慢点来。我不知道你怎么想，$c，但我多少有点不相信将军的话。我不是很肯定……道听途说总是不如眼见为实。$B$B这里的情况不太妙，我们所有的侦察活动都被否决和推迟了。现在我们必须采取一种更加独立的方式。$B$B如果我们想要了解要塞内的诅咒教徒的情况……就必须从外部开始调查。$B$B情报显示，这里的北方有一小群诅咒教徒，他们正在帮助天灾军团作战。你去看看能不能从他们那里弄到什么线索。', '先驱者乌尔雷要你到无畏要塞北方的致远郡去寻找诅咒教徒通灵师，并从他们手上夺取诅咒教徒公报。', '谨慎点，$N。我们不能在众多窥视的眼睛前查看这个证据。', '你回来了，$N。', '', '去北风苔原找无畏要塞的先驱者乌尔雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11793, '继续调查', '我恐怕必须把这事交给我手下的探子了……一些行动更加隐蔽的人。我要你带上这份文件，到旅店去找守备官雅拉。$B$B告诉她是我派你去的，一定要把情况私下告诉她。我们还不清楚有哪些人在为诅咒教派卖命。', '将诅咒教徒公报交给无畏要塞旅店内的守备官雅拉。', '快点说，$C。你有什么关于教派的讯息?', '先驱者瓦锐恩派你来的?', '', '去北风苔原找无畏要塞的守备官雅拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11794, '猎杀行动', '我一直在尽可能地了解这些邪恶的死亡信徒，包括他们的密语。$B$B乌尔雷猜得对，这些诅咒教徒提到他们在无畏要塞的各处都安插了密探：下面的码头上，中心城堡的监狱内和旅店的厨房里。$B$B拿着这只透镜。在这三处地点使用它，所有在近期内使用过诅咒教派通灵术的人身上都会浮现出黑色的光环。在可怕的事情发生之前，一定要除掉那些诅咒教徒。', '守备官雅拉要你转至无畏要塞的三个地点使用驱魔师的透镜，找出并击败诅咒教派的成员。', '你做得很好，$N。不过，我直觉这不会是我们最后一次见到这些死亡教徒。$B$B邪恶自有方法隐于日常之中。', '你完成我交代你的任务了吗，$N?', '', '去北风苔原找无畏要塞的守备官雅拉。', '击败码头的诅咒教徒', '击败监狱的诅咒教徒', '击败厨房的诅咒教徒', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11795, '紧急情况守则：第8章，第2节，第3段', '无论有没有受伤，身为中队长，我都有责任为那些已经牺牲的飞行员找到并带回他们的徽章。我跟着菲兹兰克已经好多年了，而且我们俩多年以来从没有在这件事上让死去的弟兄们失望过。$B$B但现在，我的伤势确实让我无法亲自在那些残骸中寻找徽章了，或许你能帮我把徽章都收集起来？在你替我收集徽章的同时，我也可以做一些身为中队长该做的其它的事情。', '在菲兹兰克侦察机飞行员的尸体上找到6枚菲兹兰克飞行员徽章，把它们交给滚烫熔池的“尾旋”伊吉·齿钉。', '再次谢谢你，$N。有了你的帮助，就算曾经很悲惨，我或许有一天可以完成这个任务，并回到嘶轴进行报告，确实荣耀已死之人。', '你拿到那些徽记了吗?', '', '去北风苔原找滚烫熔池的“尾旋”伊吉·齿钉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11796, '紧急情况守则：第8章，第2节，第4段', '现在，在回去机场进行报告之前，我还剩最后一件事要做了。根据紧急情况守则第8章第2节第4段的要求，我必须尽量彻底摧毁飞行器的残骸，以防我们的高科技流入敌手。$B$B我会把我的火炬借给你……若是你愿意帮我完成这项最后的工作。我可不敢想象这些高科技机械若是落入那些跟部落联系密切的地精手里，一切会变得怎么样。', '“尾旋”伊吉·齿钉要求你将东部残骸、一处南部残骸和一处西北部残骸彻底毁坏。', '再一次的，非常感谢你，$N。没有你，我不可能从这场灾害中取回任何有用的物品。', '你去破坏残骸了没?', '', '去北风苔原找滚烫熔池的“尾旋”伊吉·齿钉。', '摧毁东部残骸', '摧毁一处南部残骸', '摧毁一处西北部残骸', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11797, '虫临城下', '很好，很好。阿洛斯终于肯把秘密武器拿出来了。$B$B别误会——我的小伙子们一直很努力，但有你这样着名的英雄与他们并肩战斗，一定会让局势向有利于我们的方向发展。我不知道还能阻挡这些亡灵蛛魔多久。$B$B你出去帮我杀掉一些爬虫怎么样？给小伙子们做个榜样。', '哈默希尔中士要你到无畏要塞外的纳萨姆沙地去杀死6个地穴爬行者。', '干得好，$N。告诉这些小子你是怎么做到的。最好的蠕行者就是死掉的蠕行者!', '你回来了。希望你已经减少敌人的数量了。', '', '去北风苔原找无畏要塞的哈默希尔中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11798, '机甲专家麦卡佐德', '机甲专家麦卡佐德真是个疯子！他说他能删除所谓的“血肉诅咒”，让我们获得永生。没想到他是借此制造机械奴隶！$B$B$N，这家伙一定还在东边滚烫熔池中央的泵站。$B$B我们最后一次见到他时，他正在泵站顶端发号施令呢。去那里研究一下他的东西。$B$B你必须击败麦卡佐德，否则他会害死所有的侏儒……不，是所有的生物！', '研究机甲专家的手册，并将麦卡佐德的徽记交给菲兹兰克·铁阀。', '<老地精长长地吁了一口气，放松了不少。>$B$B完成了…你拯救了我们!如果你没有在这里阻止他，谁知到他的疯狂会散布得多远?$B$B在蓝龙和奥核战争的威胁之下，更别提还有巫妖王，我们最不需要的东西就是一个疯狂而且失控的泰坦制玩具!$B$B感谢你，$N!', '金基告诉我可以期待你。完成了吗?', '', '去北风苔原找菲兹兰克机场的菲兹兰克·铁阀。', '研究机甲专家的手册', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11807, '祭拜这团火焰', '', '', '荣耀银松森林的火焰。', 'NULL', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11865, '死不足惜', '营地南边的那些驯鹿原本一直过着自由而悠闲的生活，甚至时不时地在营地周围散步。但是奈辛瓦里的出现改变了一切。现在这群驯鹿陷入了永久的恐慌与凶暴状态中。每日每夜，隐藏在原野上的猎户与陷阱都在不断夺走它们的生命。$B$B仅仅以死亡来惩戒那些奈辛瓦里的走狗是远远不够的！他们必须像那些可怜的驯鹿一样尝尝被折磨的滋味！$B$B带上这堆仿制的皮毛，把它放在那些猎户设置的陷阱附近作为诱饵，然后就找地方埋伏好，静静等待那些人渣踏进他们自己的陷阱吧！', '仁德会营地的扎扎要求你使用一堆人造皮毛抓捕8名奈辛瓦里猎户。', '你执行了大地之母的工作，$N，不过别沈溺在这场胜利中太久。我们已经发现陷捕者头目的躲藏地了。', '别可怜他们，$r。', '', '去北风苔原找仁德会营地的扎扎。', '捕获奈辛瓦里猎户', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11866, '敌人的耳环', '无论是寻宝者还是偷猎者，任何试图支持奈辛瓦里并胆敢危害我们所珍爱的大自然的人，都是“仁慈对待野生动物德鲁伊协会”的敌人。$B$B如果你消灭了某个奈辛瓦里的同党，把他的死亡证据带回来，就可以赢得所有仁德会成员的奖励与祝福。', '仁德会营地的大德鲁伊拉索留斯许诺，若你能带回15只奈辛瓦里同党的耳环，他就会给予你丰厚的奖赏。', '这些将会环绕在我的脖子上。让这些耳朵听见我们的讯息，成为装载着我们真理的容器!', '这些耳朵将会非常适合……', '', '去北风苔原找仁德会营地的大德鲁伊拉索留斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11867, '更多耳环……', '无论是寻宝者还是偷猎者，任何试图支持奈辛瓦里并胆敢危害我们所珍爱的大自然的人，都是“仁慈对待野生动物德鲁伊协会”的敌人。$B$B如果你消灭了某个奈辛瓦里的同党，把他的死亡证据带回来，就可以赢得所有仁德会成员的奖励与祝福。', '仁德会营地的大德鲁伊拉索留斯许诺，若你能带回15只奈辛瓦里同党的耳环，他就会给予你丰厚的奖赏。', '这些将会环绕在我的脖子上。让这些耳朵听见我们的讯息，成为装载着我们真理的容器!', '无论他们是荒原的宝藏搜寻者或是嗜血猎人，任何援助奈辛瓦里且胆敢破坏我们珍爱的野生动物者都会被当作是D.E.H.T.A.的敌人。$B$B如果你杀了这些肮脏的奈辛瓦里支持者，就将他们的死亡证明带给我，你将会获得来自D.E.H.T.A.德鲁伊的祝福奖励。', '', '去北风苔原找仁德会营地的大德鲁伊拉索留斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11868, '驯鹿杀手之死', '这群驯鹿猎人有一处营地在悬崖的南部，他们那奸诈的领袖也躲在那里。她的残忍与野蛮是无人能及的，她甚至可以大摇大摆地站在被虐杀的动物的尸骸上喝它们的血，并对着月亮放声大笑！$B$B找到这个凶手卡琳，结束她那毫无意义与价值的生命。$B$B不过，你也要做好万全的准备，$N。驯鹿杀手卡琳一直是奈辛瓦里与其它富翁们最重视的猎人之一！她装备非常精良，而且周围有大批跟班。', '仁德会营地的扎扎要求你除掉驯鹿杀手卡琳。', '或许她的死亡将成为警惕，让其它胆敢以消遣和谋财为目的而杀害动物的人引以为戒。', '大自然需要正义!', '', '去北风苔原找仁德会营地的扎扎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11869, '欢乐的蚌壳', '这里西边不远之处就是库姆亚湖。据我们所知，那里栖息着这世界上唯一的淡水巨蚌族群。$B$B当然，奈辛瓦里那帮卑贱的猎人也看上了这里，想从那些巨蚌中得到大粒的珍珠。必须阻止他们！必须好好给那些为了一己私欲就危害珍稀物种的家伙们上一课。$B$B立刻转至库姆亚湖，找到那些利欲熏心的潜水员，把他们都给干掉，即使让湖水变成红色也没有关系！完成任务之后回来找我。', '仁德会营地的圣职者塞妮丝要求你杀死10名利欲熏心的潜水员。', '现在让我们瞧瞧当他们看到同伴的下场后，还能有多镇定!', '我们正在进行的是件可怕的工作，$N。', '', '去北风苔原找仁德会营地的圣职者塞妮丝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11871, '不可容忍', '在这片海岸上，在那些漂浮着的货物与残骸之间，无数的木箱与皮袋中满满地装着他们从动物身上残忍取下的东西。奈辛瓦里似乎和北海海盗勾结到了一起。这些肮脏的海盗们正在把所有堆积在海岸上的货物运回南方去。而且毫无疑问，他们背后的买主是艾泽拉斯那些毫无道德与廉耻可言、只知炫耀与奢华的富人们。$B$B必须阻止这一切。你立刻到海岸边去，把所有的货物都夺走，他们不配拥有这一切！', '遗弃海岸的圣职者莉安德拉要求你找回12个动物杂货箱。', '干得好，$N。现在我们着手攻击海贼头目吧!', '我们将会好好地埋葬那些动物。', '', '去北风苔原找遗弃海岸的圣职者莉安德拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11872, '罪恶的蛤蜊主宰……', '我今天听到了一件无耻之极、荒诞之极的事。有个家伙自封为什么“蛤蜊主宰”，就好象他已经掌握了海洋中的所有生物的生杀大权一样。这世上没有任何人有权利这么做！$B$B必须立刻找到并杀掉这个所谓的“蛤蜊主宰”。他最近好象出没在遗弃海岸附近的沉船残骸附近。你立刻展开行动吧。$B$B一旦事成，去北边的仁德会营地找圣职者塞妮丝，向她汇报一切的任务的进展。', '杀死蛤蜊主宰老K，然后向仁德会营地的圣职者塞妮丝复命。', '干得好，$N。我们令奈辛瓦里陷入绝境了!', '你有什么好消息通知我吗?', '', '去北风苔原找仁德会营地的圣职者塞妮丝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11875, '占据上风', '破碎残阳的部队需要一切能够协助我们击败基尔加丹的东西。我在暴风城的同事发明出了一种魔法油，可以强化我们部队的武器和装备。$B$B虚空残渣是其中最重要的成份，它们遍及外域的各个角落。任何大师级的草药师、剥皮师和矿工都可以在日常的工作中发现它的踪迹。所有外域特有的草药、矿石和野兽都可能含有这种虚空残渣。', '给沙塔斯城的摩尔丁特使带去8份虚空残渣。', '感谢你的帮助，$N。这场战争如果没有捐助的话，也就无法得到太大的成果。我们的人在这场战争中将会需要所有他们能够得到的优势。', '你有任何的残渣要给我吗?', '', '去找泰罗卡森林的摩尔丁特使。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11876, '帮助弱小', '它们是最尊贵的动物，难道不是吗？$B$B<拉索留斯指着北边一群缓缓走过苔原的猛犸巨象，喃喃地说。>$B$B可是，它们的族群数量却日益减少，一群自称为猎人的恶魔每天只是为了娱乐与发财而屠杀这种高贵的动物。$B$B<拉索留斯猛然转过头来，愤怒之情溢于言表。>$B$B它们的哀鸣已经快让我发疯了，$N。你也听听看，听啊，这风中传来的哀鸣。那些被困在猎人们罪恶陷阱中的小猛犸象正在呼唤我们的帮助。$B$B拿上这把锤子，毁掉那些陷阱，还它们以自由！', '仁德会营地的大德鲁伊拉索留斯要求你使用陷阱破坏锤释放8只猛犸幼崽。', '<大德鲁伊拉索利厄思擦干他的泪水。>$B$B他们从来没有希望。现在还失去了双亲，他们必定得孤独死去了。', '必须释放它们!', '', '去北风苔原找仁德会营地的大德鲁伊拉索留斯。', '营救猛犸幼崽', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11877, '日怒攻击计划', '在我们向奎尔丹纳斯岛发动进攻时，我们发现凯尔萨斯的走狗们正在计划一次反击。他命令虚空风暴的日怒血精灵对我们部署在外域的部队发动攻击，希望这样可以牵制住我们的军队，并让我们的注意力远离太阳之井。$B$B我们必须阻止这样的事情，$N。所有人都要上前线！$B$B去虚空风暴夺取他们的攻击计划书。在那儿的任何血精灵都有可能带着计划书。祝你好运，$N。', '沙塔斯城的托沃斯男爵希望你能缴获日怒攻击计划。', '<托沃斯领主接过计画并仔细阅读。>$B$B你帮了进攻部队一个大忙，$N，不过我们一刻都无法休息。我不会放任我们的敌人继续计画更多的争端。', '你连计画一起带回来了吗?', '', '去找沙塔斯城的托沃斯男爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11879, '猛犸毁灭者卡奥', '你独自一个人是无法为我的族群复仇的。但是，所有苔原上的猛犸都将帮助你！$B$B到平原上去，找一只雄性猛犸象，他会让你骑上他的背，并听从你的命令。骑着他往这里的北边走，找到卡奥的营地。你们将一起终结猛犸毁灭者卡奥的生命。$B$B完成这一切之后，带着卡奥的战戟回到仁德会营地去找拉索留斯。', '杀死猛犸毁灭者卡奥，并夺取卡奥的战戟。将卡奥的战戟带回北风苔原的仁德会营地，交给大德鲁伊拉索留斯。', '<拉索利厄思从你手中接过战戟。>$B$B这就是我想的那个东西吗?$B$B<拉索利厄思笑了。>$B$B太棒了!太杰出了!另一个奈辛瓦里的仆从被绳之以法了!', '发生什么事?', '', '去北风苔原找仁德会营地的大德鲁伊拉索留斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11880, '多相数据调查', '那个“侏儒发明家”一定是个疯子。他一直在嘟囔着说，纳格兰沃舒古附近的灵魂平原开始出现了一些暗色的云雾。$B$B按照他所说的，这些，多相……唔……什么光谱眼镜可以让佩戴者看到这些云雾，并能从中收集一些数据。他强调说上面记录的数据对我们在太阳之井的行动非常重要。我想他肯定是疯了，不过我需要任何可能对我们有帮助的东西。你不介意帮我去收集一些数据吧？', '沙塔斯城的先驱者哈隆奈姆希望你使用多相光谱护目镜去获取6份多相数据。', '感谢你的帮忙。你一点都不明白跟那个炸饼“博士”相处有多难。在他每次来“检查”我的进度的中间，他都忙着兜售一些小东西或他那些军事发明。', '你取得那些读数了吗?要是我还不拿到他珍贵的资料，那个地精又要向我尖叫大吼了。', '', '去沙塔斯城找圣光广场的先驱者哈隆奈姆。', '获取多相读数', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11881, '运货行动！', '你见过那些突突突冒着烟的飞行器吗？那就是号称侏儒科技的最高杰作。$B$B我一直想搞些能代表侏儒科技的东西研究研究，嘿，你瞧，现在机会来啦。前几天有一架侦察机在喷泉平原西南的滚烫熔池附近坠毁了。$B$B我要你找到那架飞行器的坠落点，然后吹响这枚哨子，我最忠实的伙伴——骡子珍妮就会到你身旁。她会一直跟着你，你可以把所有回收来的东西都放进她背上的口袋里。不过，你得保证她的安全。要是被攻击的话，她可能会甩掉货物。', '帮助珍妮从坠毁点返回牦牛村的菲兹克斯·盖维斯特身边，并确保她驮载的货物完好无损。', '<菲奇司仔细地检查可利用的残骸。>$B$B洁妮有点被伤到，不过她会没事的。至于这个可利用的残骸，它有点…比我期望的还要零碎，但是我应该可以设法利用它。不过，你的工作还没结束。我们将要重新组织这个东西。', '别失败!我就指望你了。', '', '去北风苔原找牦牛村的菲兹克斯·盖维斯特。', '护送珍妮返回安全地带并确保货物完好无损', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11884, '尼达尔，犀牛之王……', '在西边库姆亚湖附近的一处高崖之上，游荡着一个名叫尼达尔的家伙。他自称为“犀牛之王”，而且每天都在做一些偷鸡摸狗的懦弱行为——狩猎那些没有自我防卫能力的可怜犀牛，比如幼年的，或是受伤的。他还复活了一只死去的犀牛当作自己的坐骑和保镖，这对所有被他狩猎的犀牛来说都是莫大的屈辱。$B$B“仁慈对待野生动物德鲁伊协会”多年来很少下令杀死动物，而这一次……尼达尔那只被玷污的犀牛尸体必须要处理掉……把他们两个都干掉，然后回来见我。', '仁德会营地的兽穴卫士凯林格要求你杀死“犀牛之王”尼达尔以及他的宠物“午餐盒”。', '起码现在犀牛获得了平静。感谢你，$N。', '你打败他们了吗?', '', '去北风苔原找仁德会营地的兽穴卫士凯林格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11885, '仇敌的血脉', '这本书中列有斯克提斯爪之祭司所囚禁着的所有泰罗克的宿敌的后裔，包括猎手吉萨拉克、水晶巨人卡尔洛格，还有被贬为异端的黑暗尖啸者阿克卡莱和风怒者瓦克奇斯。必须要在泰罗克回到这个世界之前将他们全部杀死。$B$B你首先需要夺取一些迷失鸦人身上带着的卷轴，然后在斯克提斯的召唤法阵中烧掉卷轴，这样才能召唤并杀死它们。要知道，它们都是非常非常强大的存在，你最好带上几个朋友一起去。', '在斯克提斯寻找召唤法阵中的徽记堆，用10张迷失卷轴召唤出一个泰罗克仇敌的后裔，并击败总共四个泰罗克仇敌的后裔。完成任务之后回去向黑风码头的哈吉克复命。', '太好了!收下这个。我用你象征你手下败将的物品准备了这个包裹。它们会让你召唤泰洛克。$B$B小心，$N。他是世界上最强大的阿拉卡。别小看他!', '完成你的任务了吗，$N?', '', '去泰罗卡森林找黑风码头的哈吉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11886, '反常的活动', '$c，欢声笑语笼罩下的火焰节已是暗潮涌动。$B$B我们接到报告称，暮光教徒近来在佐拉姆海岸的黑暗深渊附近频繁活动。莫非这帮狂热份子也在庆祝节日？我看不像。转至黑暗深渊入口南边的废墟，暮光信徒在那里设有营地，去打探打探情报吧。收集到情报之后，用这个信标召唤一条幽灵狼。', '转至灰谷的佐拉姆海岸，在黑暗深渊入口以南寻找新建的暮光营地，从该处的暮光教徒身上搜寻暮光信件，然后使用图腾信标召唤大地之环幽灵狼。', '这真令人担心，朋友。它暗示着一个更大的阴谋，除了当地火和水元素骚动外，这里需要更进一步的调查…', '你发现了什么?', '', '去找大地之环幽灵狼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11887, '应急的物资', '你在侏儒的尸体上发现了一只小包裹，里面装满了军粮、工具以及一卷侏儒胶卷。这些东西说不定能帮助菲兹克斯·盖维斯特研究如何仿造侏儒飞行器。$B$B如果再拣几个飞行员背包回去，说不定菲兹克斯会赏你点什么呢。', '从坠机的菲兹兰克侦察机飞行员尸体上收集7个侏儒应急工具包，将它们交给牦牛村的菲兹克斯·盖维斯特。', '地精工具?给我的?这应该可以让修复飞行器变得更简单一些。', '你手里拿着什么?', '', '去北风苔原找牦牛村的菲兹克斯·盖维斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11889, '空中的虫子', '一直以来，我们的防线都固若金汤，没有让这些虫子前进一步。但有些可恶的杂种会飞，这样它们就可以飞过外围防线，直接攻击我们的内部防御圈。$B$B我已经向民用船只征集了一些强化捕网。如果你的臂力足够的话，这些网能帮你扫清空中的敌人。去干掉一些虫子，让我们守住要塞。', '哈默希尔中士要你到无畏要塞外使用强化捕网捕捉并杀死6只天灾烈焰蛛。', '它们从地上我们会击败它们，它们从空中来我们也会给它们好看。如果那些没爹没娘的不死生物敢从海上来，我们绝对让它们没命回去。', '你回来了。但愿是好消息?', '', '去北风苔原找无畏要塞的哈默希尔中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11890, '他们想干什么？', '西边那些水池一带的侏儒似乎遇到了麻烦。谁叫他们整天搞些乱七八糟的“发明”，真是活该。$B$B我要你转至他们的泵站调查情况，然后向我汇报结果。', '调查菲兹兰克泵站周围的区域，然后返回北风苔原的牦牛村，向天空大地先知汇报你的发现。', '真是个糟糕的消息。$B$B我的族人很快就要离开这个地方了。我们要冲破天灾军的防线转至我们在龙骨荒野的主城，冰雾。$B$B但在此之前，我们要解决地精的疯狂所造成的灾害。', '你找到了什么，$r?', '调查菲兹兰克泵站附近的区域。', '去北风苔原找牦牛村的天空大地先知。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11891, '人畜无害', '暮光教徒似乎在佐拉姆海岸西北方创建了新的营地，眼下他们正与某个……神秘的访客密谋着什么。$B$B$r，如果你能偷听到谈话内容，我们或许可以了解内情。这颗宝珠能将你伪装成一只普通的沙滩蟹，带上宝珠转至西北方的营地，偷听暮光教徒与他们的“客人”之间的谈话，然后回来向我复命。', '在灰谷佐拉姆海岸的黑暗深渊入口以西寻找新建的暮光营地，使用螃蟹宝珠打探情报，然后使用图腾信标召唤大地之环幽灵狼。', '他们想召唤一个冰霜领主到我们的世界?不!他们不能破坏平衡!', '你知道他们的秘密了吗?', '偷听暮光教徒的阴谋。', '去找大地之环幽灵狼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11892, '刺杀哈罗德·兰恩', '你已经为北风苔原上的野生动物做了许多贡献，$N。奈辛瓦里手下那群卑贱的家伙们连续遭受了那么多次失败，这些教训恐怕他们一辈子也无法忘记。$B$B哈罗德·兰恩，这个曾被指控应为纳格兰多起屠杀事件负责的家伙，当前掌管着奈辛瓦里在北风苔原的一切事务。他本人就在西边的库姆亚湖附近扎营。$B$B<说着，拉索留斯交给你一支非常精致的橡木号角。>$B$B找到哈罗德·兰恩，杀了他。如果需要我们的帮助，就吹响这支号角。', '仁德会营地的大德鲁伊拉索留斯要求你杀死哈罗德·兰恩。', '唉，奈辛瓦里走了，也许他从来就没在这里…$B$B<拉索利厄思叹了口气。>$B$B这恶魔很狡猾，但是他的时日不多了。我们会把他揪出来的，一定会…', '杀掉冻原屠夫了吗?', '', '去北风苔原找仁德会营地的大德鲁伊拉索留斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11893, '元素的力量', '我一直在提醒这个笨蛋地精，叫他别太相信那些破烂机器的稳定性。$B$B但是我所掌握的元素之力并不完整，等到修行结束后，我才能完全地运用这种能力。不过，我还是能帮菲兹克斯一些忙的。$B$B带上这个风魂图腾转至西边的村落，将它插在蒸汽狂怒者旁边，图腾会从死去的元素身上汲取能量。将充满能量的图腾带回来给我，接下来的事我自己会搞定的。', '牦牛村的多莱安·霜蹄要你利用风魂图腾收集10只蒸汽狂怒者的能量。', '<杜然点点头。>$B$B很好，这样应该足以向菲奇司表达我一直想告诉他的事情。', '你替图腾充能完毕了吗?', '', '去北风苔原找牦牛村的多莱安·霜蹄。', '采集能量', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11894, '修修补补', '还记得前几天你带回来的那些侏儒胶带吗？$B$B嘿嘿，我终于知道那玩意儿是干嘛的了。你瞧，这台飞行器的机身严重受损，要让它飞起来的话就需要好好加固了。$B$B多莱安说牦牛人利用蒸汽处理驯鹿皮，然后将这种韧性极强的熟化驯鹿皮制成密封的容器。村子附近就生活着许多沼泽驯鹿，南边的洪荒平原也有它们的踪迹。我要你搞一些它们的皮，然后在蒸汽平原的蒸汽泉眼上处理一下。', '牦牛村的菲兹克斯·盖维斯特要你给他带回5张蒸汽熟化鹿皮。', '太好了!再让我多乔几下，我就可以成为飞天地精啦!', '你带了蒸汽熏制皮给我吗?', '', '去北风苔原找牦牛村的菲兹克斯·盖维斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11895, '风暴的主宰', '从调查结果来看，那些机械生物应该不难对付。但是你必须先掌握风暴的力量。$B$B我身后的小屋中有一根图腾，当你做好准备之后，面对图腾集中精神，狂乱风暴就会现身。你必须击败它才能汲取它的精华。$B$B如果能找到帮手的话就更好啦。$c，完成任务后再回来向我复命吧。', '击败狂乱风暴，然后向北风苔原牦牛村的天空大地先知复命。', '我可以感觉到风暴的力量在你的身体中奔驰!$B$B你准备好了，$N。让我们开始吧。', '你驾驭了风暴吗?', '', '去北风苔原找牦牛村的天空大地先知。', '掌握风暴的力量', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11896, '闪电的力量', '你已经掌握了风暴的力量。我会教你如何运用这种力量来削弱西边滚烫熔池里的机器人。$B$B这是一根闪电魔杖，它可以帮你对付机械侏儒的创造物。就别在机械侏儒身上浪费时间了，塔迦祖母有别的法子对付他们。$B$B借助风暴的力量削弱机器人，然后彻底地摧毁它们！', '利用风暴的力量削弱并摧毁15名机器人（不包括那些机械侏儒）。你可以在菲兹兰克泵站周围的池塘中找到它们。$B$B完成任务后回到北风苔原的牦牛村，向天空大地先知复命。', '随着他们的机器爪牙被解决，就该是我们进行更大牺牲的时候了。不幸的是，尽管如此，我还是能感觉到风暴之力在你体内逐渐散去。$B$B不过，这符合它的目的，我想就算没有这东西，你还是有办法进行下一步。', '你解除了那些邪恶产物身上的风暴之力了吗?', '', '去北风苔原找牦牛村的天空大地先知。', '削弱并摧毁机器人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11897, '炸毁虫孔', '天灾军团还没有后撤的迹象，$N。都是那些该死的虫孔。据我们所知，这些虫孔直接通向冰冠冰川，而且巨大的亡灵虫子正在地下不知疲倦地拓展着虫孔。$B$B如果说我从多年的矿工工作中学到了什么的话，那就是如果没有支撑梁，只需要进行一次爆破，隧道就会非常容易崩塌。$B$B带上这些炸弹，把它们放在西边海滩那边的山脊上的虫孔入口处。炸掉那些虫孔后回来向我复命。', '哈默希尔中士要你使用火焰炸弹摧毁无畏要塞西南方和西北方的虫孔。', '做得非常好，$N。没有你，骁勇要塞也许无法抵挡得住敌人。谢谢你的协助，我们将会继续战斗下去。', '你成功了吗，$N?我们需要减缓天灾军团的进攻，否则骁勇要塞将会被攻陷。', '', '去北风苔原找无畏要塞的哈默希尔中士。', '在南部虫孔安装炸弹', '在北部虫孔安装炸弹', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11898, '过关斩将', '圣城恩其拉的最底层有一座笼罩在光芒之中的灰色祭坛。站在祭坛上，就可以进入那座可怕的浮空城——纳克萨纳尔。$B$B$N，千万小心。瓦拉纳王子拥有众多侍从，这帮走狗宁愿死也不会让你伤害他们的主子。$B$B你必须在浮空城中杀出一条血路，直抵王子的宝座。$N，如果你败在他手中，恐怕我的族人们就再也没有机会安全撤离到冰雾村了。', '击败瓦拉纳王子以及他手下的两名中尉，残忍的范瑟雷和邪恶的卢修恩，然后向牦牛村的冬风酋长复命。', '随着王子被击败，天灾军团在北风苔原的存在也形同破灭。我想他们将会有一阵子不敢前来，所以我得专心准备让德姆带领村民出发转至冰雾。$B$B<酋长慢慢的摇摇头。>$B$B尽管我与德姆之间有过许多的意见不同，我相信他的判断力和能力。我无法遗弃坦卡雷，所以我将会保卫坦卡雷直到我咽下最后一口气。', '你击败瓦拉纳尔王子了吗?', '', '去北风苔原找牦牛村的冬风酋长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11899, '灵魂的解脱', '也不知道西边滚烫熔池的机械侏儒是从哪儿冒出来的。总之，在泵站作业的侏儒莫名其妙地消失之后，机械侏儒就出现了。$B$B天知道这些家伙会搞出什么事来，我们还是解决掉他们比较好。$B$B带上这个捕魂器，对机械侏儒的尸体使用它就能捕获他们的灵魂。然后我们可以释放他们的灵魂，了解这些侏儒究竟遭遇了什么。', '使用祖母的捕魂器捕获10个菲兹兰克机械侏儒的灵魂。完成任务后返回北风苔原的牦牛村，向塔迦祖母复命。', '现在我们必须释放你抓住的这些灵魂。', '你的进展如何?', '', '去北风苔原找牦牛村的塔迦祖母。', '捕获机械侏儒的灵魂', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11900, '监测数据', '我原本还希望魔枢的影响仅仅限于这个地区。但最近从艾泽拉斯各地发来的大量分析报告指出，地质活动的不稳定程度正在以几何级数增长！$b$b在研究应对方法的同时，我需要魔枢的定期监测数据。$b$b我已经在考达拉四周安装了灵敏的监测仪器，并且把它们伪装成了玛里苟斯的占卜宝珠的样子。其中一台仪器在魔枢附近的壕沟里，另外三台藏在山谷边界的建筑物中。你去帮我查看一下，把仪器的监测数据给我带回来吧。', '永生之盾的大法师伯林纳德要你去收集他安装在考达拉的监测仪器上的数据。', '这比我预期的还糟糕。$B$B玛里苟斯引导太多力量到这个地方了。如果再不阻止他，艾泽拉斯将会成为另一个外域!$B$B幸好，我相信我找到了一个暂时的解决之道……', '你检查了我的每一个仪器吗，$C?', '', '去北风苔原找永生之盾的大法师伯林纳德。', '收集魔枢的地质读数', '收集考达拉南部的地质读数', '收集考达拉北部的地质读数', '收集考达拉西部的地质读数');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11903, '战斗的时刻', '你瞧，$N。致远郡的守军全部战死了，甚至更糟……所以我们只能靠自己打败天灾军团了。$B$B我们已经把致远郡里剩下的壮丁全部编入了民兵团，但如果没有你的帮助，他们胜利的希望会很渺茫。去帮他们一把……我和我的士兵们会守住这条路。绝对不能让天灾军团通过！', '致远郡的吉拉德·格林要你去杀死14个天灾食腐者。', '你以天灾军团唯一的语言:暴力与死亡好好地沟通了一番。只可惜他们却彷佛永远也杀不完!', '你好好打击了那些食尸鬼吗?', '', '去北风苔原找致远郡的吉拉德·格林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11904, '劳动的果实', '天灾军团还在不断涌来……但我们不能放弃！听着，$N。在矿井里有一车矿石，是联盟在这一地区所能采集到的最后一点矿石，因此非常珍贵。$B$B问题是矿石车被锁住了。军队开进矿井的时候，亚克布上尉征用了所有的重要设备，包括矿石车的钥匙。$B$B现在亚克布肯定也和矿井里的士兵一样被瘟疫感染了。你去从他那里拿回钥匙，把矿石带回来。', '转至致远郡的矿井，从亚克布上尉身上夺取矿石车钥匙，并用它开启矿石车。完成任务后向致远郡的吉拉德·格林复命。', '谢谢你，$N。这个矿石将会在接下来对联盟产生不可或缺的重要性。我想我们今日做出了贡献。', '$N，矿还安全吗?', '', '去北风苔原找致远郡的吉拉德·格林。', '启动矿石车', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11905, '延缓灾难', '我终于发现地质状态不稳定的根本原因了！$b$b艾泽拉斯的魔网能量线正在被重新定向到魔枢。这发现真是太惊人了！我恨不能用毕生的精力去研究这种异变……$b$b可惜我必须立即解决眼前的危机。源源不断的奥术能量正在不同位面之间撕开一条裂隙。$b$b在魔枢深处，我们这个世界的基础结构正在被削弱。我无法阻止这种变化，但我研究出了一种减缓这种异变的方法。$b$b把这东西拿到魔枢里去，靠近正在形成的裂隙，然后激活它。', '永生之盾的大法师伯林纳德要你在魔枢的裂隙附近使用交叉空间重塑器。', '极佳的成果，$N，震动已经开始减缓了。$B$B很幸运，你的努力带给我们足够的时间找出令玛里苟斯的挫败的方法。', '你到过魔枢的裂隙了吗?', '', '去北风苔原找永生之盾的大法师伯林纳德。', '延缓空间裂隙的形成', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11906, '净化水池', '<一行眼泪从铁眼的脸颊上滑落。>$B$B我听说你要回到西边的水池。真是巧得很，能顺便帮我个忙吗？$B$B侏儒真\r\n是缺乏环保意识的下等种族，瞧瞧他们鼓捣出的机械设备多污染环境呀。我要你收集一些备用零件。$B$B把你收集到的零件带回来给我。在我们撤离村子之前，我会妥善处理掉这些东西。', '将15个菲兹兰克备用零件交给北风苔原牦牛村的铁眼。', '在我们继续旅程之前，我们把土地回归原始，这就是牦牛人的传统。$B$B我们将要转至我们的首都，冰雾，很快就会出发。你的协助让我们的速度提高了不少。$B$B感谢你。', '如果我们无法关照大地，她也不会容忍我们长久生活的。', '', '去北风苔原找牦牛村的铁眼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11907, '机械副官', '据说机甲专家麦卡佐德指派了四名副官来操纵滚烫熔池的机器人。$B$B必须消灭他们！$B$B根据我们的远行者和猎人的说法，你只需转至西部哨站、北部哨站、中部哨站和南部哨站，转动那些哨站的阀门以破坏设施，就可以让他们露面。$B$B你应该不难找到那些哨站，上面都安置着旋转灯呢。$B$B$N，抓紧时间！', '摧毁托奇、ED-210、麦克斯·布拉斯托和研磨者，然后返回北风苔原的牦牛村，向天空大地先知复命。', '感谢你，$N。$B$B解决了这些奇怪的东西，要应付水池剩下的部分就容易多了。$B$B我们欠你一份情。', '你解决了副手吗?', '', '去北风苔原找牦牛村的天空大地先知。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11908, '参考资料', '我原本是负责管理收割傀儡的——在天灾军团毁掉我们的大部分农场前，这可是个要紧活儿。但我想我们可以重新利用这些傀儡。$B$B我想重新组装这些傀儡，让它们帮忙抗击天灾军团。$B$B但我对此不是很精通，我需要查阅我的工作手册才行。问题是，我把它落在车间里了……就是矿井旁边那间着火的屋子。你能帮我把它拿回来吗？', '耶雷米亚·霍宁要你到致远郡矿井旁那间着火的屋子里拿回他的手册《农田、工厂与车间》。', '太好了!我要的资料应该就在里面。', '你把我的书找回来了吗?', '', '去北风苔原找致远郡农场的耶雷米亚·霍宁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11909, '击败机甲专家', '这个名叫机甲专家麦卡佐德的家伙显然是疯了。如果他如法炮制地拿“永生”来蛊惑我们，那我们也会成为机械奴隶！必须阻止他！$B$B我听见来自风中的低语，这家伙就呆在西边滚烫熔池中央的泵站。$B$B他很可能还在泵站顶端的指挥室里发号施令呢。进去研究一下他究竟在干什么吧。$B$B$N，你必须击败机甲专家麦卡佐德，否则他迟早会害死我们！', '研究机甲专家的手册，并将机甲专家麦卡佐德的徽记带回北风苔原的牦牛村，向塔迦祖母汇报你获胜的消息。', '<主母大大地松了一口气。>$B$B结束了…你拯救了我们!如果你没有在这里阻止他，谁知道这个地精的错误会散播多远?$B$B在蓝龙和奥核战争的威胁之下，更别提还有巫妖王，我们最不需要的东西就是一个疯狂而且失控的泰坦制玩具!$B$B感谢你，$N。', '结束了吗?齿轮大师梅卡佐德的威胁已经解除了吗?', '', '去北风苔原找牦牛村的塔迦祖母。', '研究机甲专家的手册', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11910, '古树的秘密', '显然这一地区的地质异常活动已经影响了当地的生物。$b$b我对冰川古树和它们最近表现出来的适应性变异很感兴趣。我相信它们这种向“魔缚古树”转化的变异方式是对我们当前困难的一种启示。$b$b为了研究，我需要这两种生物的样本。请你快点行动吧……', '永生之盾的大法师伯林纳德要你从考达拉的古树身上收集3块冰川古树碎片和3块魔缚古树碎片。', '对，对，对。这样应该够了。$B$B感谢你，$r。', '你收集到我需要的样本了吗?', '', '去北风苔原找永生之盾的大法师伯林纳德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11911, '苏醒', '虽然我们可能正在见证自己的毁灭，但我还是忍不住要惊叹。我在这里进行研究的时间虽然很短，但是我所取得的成果却是过去几十年的好几倍。$b$b这些古树由于长时间受到高层级的奥术能量辐射，正在逐渐转变成……另一种生物。$b$b我认为它们的变异应该还存在着一种终极形态。请你进入魔枢，找到这种终极形态存在的证据。$B$B请多加小心……', '永生之盾的大法师伯林纳德要你进入魔枢，并从晶化保卫者身上收集5块奥术古树碎片。', '太惊人了!$B$B你说，他们也很具有侵略性。这表示有某些势力在幕后操控。这并非自然的现象…$B$B拜托，$N，接受这个象征我们对你的感谢。达拉然将会为你效力。', '结晶古树…他们真的存在吗?', '', '去北风苔原找永生之盾的大法师伯林纳德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11912, '冰冷的草莓', '呀！能看到一张新面孔真是让我感到欣慰，我还以为我们已经被抛弃了呢。$b$b我们的补给线已经被切断好几天了，而当前的形势似乎有点——好吧，是非常糟糕。老实说，我觉得这完全是个自杀式的任务。$b$b可能我并没有应付这种暴力场面的天赋——更不要说这要命的冰天雪地了！我宁愿回达拉然去研究古代文献。$b$b现在的关键是，我们的食品储备已经快没了，请你帮我尽可能多地收集食物回来。', '永生之盾的图书馆员塞尔拉要你从考达拉的冰莓灌木丛上收集10份冰莓。', '嗯，这不太多，但应该够让我们撑过一天。$B$B我相信你应该会觉得以你的努力来说，这样的报酬很公平。', '你找到任何食物了吗?', '', '去北风苔原找永生之盾的图书馆员塞尔拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11913, '万无一失', '我听到你和吉拉德的谈话了，而且我一点也不喜欢这个消息。如果那些狂热者们能在矿井的粮食里下毒，那对外面的粮食就更容易得手。$B$B我们没有时间去分辨粮食的好坏了，必须立即行动，把所有粮食都销毁。$B$B带上这支火把，把附近所有你能找到的粮食全部烧掉。如果我们从这场袭击中幸存下来，结果却死于瘟疫，那可真成大笑话了。', '温蒂·达伦要你使用温蒂的火炬烧掉8袋致远郡谷物。', '谢谢你，$N。攻击的幸存者却为了受到瘟疫污染的远郡谷物而丧命，这是我所不乐见到的。', '你做到我吩咐的事情了吗，$N?', '', '去北风苔原找致远郡农场的温蒂·达伦。', '焚烧致远郡谷物', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11914, '保持隐蔽', '我们能在这里站稳脚跟，全得仰仗我们的隐蔽措施。一旦护盾消失，哪怕只是一小会儿，玛里苟斯的手下就会发现我们。$b$b我的职责之一就是维持巫师们的法力水平，以免护盾失效。由于补给线被切断，我必须自己想办法。$b$b我需要你的帮助，$n。$b$b在靠近魔枢的地方，有一些吸收了大量魔法能量的奥术浮蛇。它们在死亡的时候会释放出体内的法力精华来，我需要这些精华。', '永生之盾的图书馆员塞尔拉要你杀死魔枢附近的奥术浮蛇，并收集5份魔枢法力精华。', '达拉然不会忘记你的付出，$r。$B$B我希望你对些报酬感到满意。', '你拿到了我需要的法力水晶吗?', '', '去北风苔原找永生之盾的图书馆员塞尔拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11917, '反击', '我们必须采取行动，维系平衡！时间非常紧迫。$B$B返回佐拉姆海岸的暮光营地。暮光教徒企图利用寒冰之石与元素交流，就跟他们在希利苏斯的做法一样。虽然我很不情愿这样做，但是灵魂会理解的——你必须召唤并杀死埃霍恩手下的一员军官。或许这样就能阻止暮光教徒的阴谋……', '转至灰谷的佐拉姆海岸，杀死从寒冰之石中召唤出来的冰浪上尉，然后返回任意主城中的大地之环长者处复命。', '你做得很好。这也许看来是很小的一步，但对大局来说却可以做为战斗的支持。收下这个和我的祝福，然后晚点再来，也许我会有更多事要让你去做。', '你凯旋归来了吗?', '', '去找大地之环长者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11918, '基本的训练', '这是战争，凡人，而我们就是刺向敌人的长矛。$b$b你们那种为了领土或财富而进行的小打小闹与这场战争比起来真是不值一提。我们要面对的是玛里苟斯和他的整个蓝龙军团。你要牢牢记住，如果他胜利了，这个世界就会灰飞烟灭。$b$b我们的人手很少，而敌人的数量远远超过我们。牺牲是难以避免的，我们只要能拖住敌人就是胜利。$b$b去吧。在我想好该给你指派什么任务前，先自己找点事情来干干。', '永生之盾的莱洛拉斯要你消灭10个考达拉织法者。', '好吧，$C，现在你对我们的敌人有所了解，现在可以真的进行工作了。', '你让我们的敌人认识你了吗，$C?', '', '去北风苔原找永生之盾的莱洛拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11919, '猎龙', '蓝龙军团开始在他们的龙身上画满神秘的符文，我要知道他们的意图。$b$b<莱洛拉斯用一支长矛刺破了手指，矛尖沾上了他的血。>$b$b使用这只长矛去驯服一只龙。在它虚弱的时候制服它，并在法力消失前把它给我带回来。$b$b蓝龙的幼崽都放养在山谷的西北边界上。', '莱洛拉斯要你使用他的长矛驯服一只魔枢雏龙，并把它带回永生之盾交给他。', '不需要为了这些年幼雏龙的命运感到良心不安，$r。玛里苟斯才应该要为此负责。$B$B我努力不懈地研究想揭开这些符文的奥秘。$B$B我向你保证，除非必要我们不会再夺取更多的生命了。', '你抓到一只奥核雏龙了吗?', '', '去北风苔原找永生之盾的莱洛拉斯。', '捕获魔枢雏龙', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11921, '继续扔火炬', '嗨，玩火炬的！挺开心的嘛？瞧你那副乐在其中的模样！怎么样，扔火炬游戏玩得炉火纯青了吧？接下来，你要面对新的挑战啦……$B$B你知道游戏规则的：将火炬扔向带标记的火盆。这次呢，时限有所延长，但火盆的数量就多得多了。$B$B准备好了吗？', '赢得一场扔火炬游戏，然后与吞火大师谈一谈。', '哇喔，你做到了!你真棒!也许明年你可以在节庆上找到一份工作!', '快点!没有时间可以浪费了!', '击中20个火盆。', '去找吞火大师。', '击中火盆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11922, '扔火炬', '你想成为一名玩火炬的艺人？你具备相应的素质吗？比如机敏？灵活？……勇气？如果你有信心的话，不妨来试试身手！$B$B带上火炬去篝火堆附近吧。当你看见某只火盆上方显现标记时，就将火炬扔过去。动作要快！在标记消失前扔出火炬才能得分！$B$B这是一项限时游戏，你要击中规定数量的带有标记的火盆，然后回到我这儿来……准备接受新的挑战。', '赢得一场扔火炬游戏，然后与食焰大师谈一谈。', '做得好!你很快就可以成为一名火焰杂耍师了!下一次的考验就是来真的了……', '快点!没有时间可以浪费了!', '击中8个火盆。', '去找食焰大师。', '击中火盆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11923, '接火炬', '扔火炬游戏对你来说已经易如反掌啦，那么试试接火炬吧！$B$B带上这捆未点燃的火炬，在篝火堆附近用力向上抛起一只，在火炬落地之前接住它……然后再往上抛！连续接住火炬4次，然后回来找我。可别接不住呀！如果你接不住的话，就得返回篝火堆那里从头再来咯。祝你好运！', '连续接住火炬4次，然后与食焰大师谈一谈。', '你有被烧到吗?假如你被烧到的话，也许下次玩火的时候可要三思一下……$B$B开玩笑的啦!你做的很好!你获得了正式的肯定。你已经是一位正式的火焰杂耍师了。现在你可以去好好地玩得开心了!', '接火炬是非常有趣的活动，你不这么觉得吗?但要小心!你不会想被烧伤的!', '连续接住火炬4次。', '去找食焰大师。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11926, '继续扔火炬', '嗨，玩火炬的！挺开心的嘛？瞧你那副乐在其中的模样！怎么样，扔火炬游戏玩得炉火纯青了吧？接下来，你要面对新的挑战啦……$B$B你知道游戏规则的：将火炬扔向带标记的火盆。这次呢，时限有所延长，但火盆的数量就多得多了。$B$B准备好了吗？', '赢得一场扔火炬游戏，然后与食焰大师谈一谈。', '哇喔，你做到了!你真棒!也许明年你可以在节庆上找到一份工作!', '快点!没有时间可以浪费了!', '击中20个火盆。', '去找食焰大师。', '击中火盆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11931, '破译密码', '我感觉到这里的龙与我们有着明显的不同，但我依然无法破解它们身体上的符文。$b$b如果没有资料的话，我就需要花上更多的时间来破译它们，可我们没有那么多时间了。$b$b一个名叫卡勒拉斯的肯瑞托叛徒就在附近，他手里可能有我需要的文献，他的手下还有我进行破译工作所需的符文。$b$b快去吧，凡人。玛里苟斯正在变得越来越强大。', '永生之盾的莱洛拉斯要你从审讯者卡勒拉斯那里取得碧蓝书典，并从他手下的考达拉缚法者那里收集3枚闪烁的符文。', '你做得很好，$r。$B$B希望当中会有可以用来对抗玛里苟斯的线索。', '动作快点，凡人。$B$B随着时间分秒过去，玛里苟斯的力量就愈加强大。', '', '去北风苔原找永生之盾的莱洛拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11933, '盗取埃索达的烈焰', '从埃索达偷来的烈焰令你感到异常的温暖。你对这种罕见的力量一无所知，但是节日诗人或许知道些什么……', '将埃索达烈焰交给节日诗人。', '火焰看来很陌生…但，你说这是从埃索达来的?太惊人了!你竟然能进入那艘船中…当然，我会支付报酬的。如果你找到任何类似的东西，别忘了来找我谈谈。', '你几乎在发着光芒，$r。你带了什么来?', '', '去找节日诗人。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11935, '盗取银月城的烈焰', '从银月城偷来的烈焰令你感到异常的温暖。你对这种罕见的力量一无所知，但是博学者或许知道些什么……', '将银月城烈焰交给节日博学者。', '多荣耀的火焰!你说，你从银月城拿到这个的?太不可置信了!有了四座城市的火焰，谁知道我们能达成什么?', '你几乎在发着光芒，$r。你带了什么来?', '', '去找节日博学者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11936, '蓝龙的卵', '我们来这里的目的很简单：在不让玛里苟斯发现的前提下观察他的后裔，并尽可能阻挠他的行动。为了完成这个目标，我现在要交给你一项任务。$b$b蓝龙把他们的卵都藏在魔枢的底部。长期接受大量奥术能量的辐射显然会加快这些卵的孵化速度，而且会对幼龙的成长产生不可预见的影响。$b$b我没兴趣去研究这种影响。你现在就去杀掉一些龙人，用它们冰冷的斧头砸掉那些卵。', '永生之盾的莱洛拉斯要你杀死考达拉龙人，并用它们的冰霜战斧打碎5枚蓝龙卵。', '不管是不是敌人，摧毁龙蛋都令我很痛苦。$B$B希望这样的牺牲是有意义的……', '你摧毁那些蓝龙蛋了吗，$C?', '', '去北风苔原找永生之盾的莱洛拉斯。', '摧毁龙卵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11938, '争取时间', '好了，现在有了护命匣，我应该可以得到我想知道的一切了。不过，圣城那边的天灾军团不可能对此一无所知，他们很快就会反应过来的。$B$B我们绝对无法抵御他们的全力攻击。或许我可以……算了，就当我没说。$B$B我希望你能到那边去，骚扰他们一下，给他们造成一些损失。希望这样可以耽搁他们足够久的时间，让这两个家伙把肠肠肚肚都给我吐出来……当然，这只是个比喻的说法。带上鲁瑞德，他肯定能助你一臂之力。', '悲叹通灵塔里的萨萨里安要求你杀进圣城恩其拉，消灭20名天灾军团士兵。如果你需要帮助，就使用鲁瑞德的骨头。', '这应该可以为我们争取一些时间。伊希多鲁斯很合作，但我真的需要和这个巫妖单独相处一下。', '完成了吗?', '', '去北风苔原找悲叹通灵塔的萨萨里安。', '消灭恩其拉中的天灾军团士兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11940, '猎龙', '为了研究它们身上的符文，我需要更多的雏龙。$b$b你可以在山谷的西北边界找到它们……$b$b<莱洛拉斯用一支长矛刺破了手指，矛尖沾上了他的血。>$b$b使用这只长矛去驯服一只龙。在它虚弱的时候制服它，并在法力消失前把它给我带回来。', '莱洛拉斯要你使用他的长矛驯服一只魔枢雏龙，并把它带回永生之盾交给他。', '不需要为了这些年幼雏龙的命运感到良心不安，$r。玛里苟斯才应该要为此负责。$B$B我努力不懈地研究想揭开这些符文的奥秘。$B$B我向你保证，除非必要我们不会再夺取更多的生命了。', '你为我的研究找到雏龙了吗?', '', '去北风苔原找永生之盾的莱洛拉斯。', '捕获魔枢雏龙', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11941, '奇怪……', '这块金属碎片的某些特性吸引了你，使你没有随手把它仍掉。$b$b莱洛拉斯也许能发现它的作用。', '把闪耀的碎片交给永生之盾的莱洛拉斯。', '你把这个带来给我是明智的，$N。$B$B<瑞洛拉兹看着碎片并且缓缓点头。>$B$B如果你真的愿意做出贡献，那么不管风险有多少，我都应该和你分享它的意义。', '你找到了什么，$C?', '', '去北风苔原找永生之盾的莱洛拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11942, '通行之语', '那只巫妖终于肯张嘴了，$N。恩其拉的高阶祭司们掌握着如何进入纳克萨纳尔的秘密。$B$B立刻转至鲜血尖塔、痛苦尖塔，和凋零尖塔，进去以后杀死里面的祭司。$B$B拿到他们身上的三张卷轴之后马上回来。', '悲叹通灵塔里的萨萨里安要求你转至圣城恩其拉，在痛苦尖塔中夺取高阶祭司塔雷坎的卷轴，在凋零尖塔中夺取高阶祭司纳菲塞特的卷轴，在鲜血尖塔中夺取高阶祭司安多拉斯的卷轴。', '干的漂亮，$N。现在只需要再问出最后一点资讯。', '慢慢来是吧?我可不知道我还能够困住这个巫妖多久。', '', '去北风苔原找悲叹通灵塔的萨萨里安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11943, '牢笼', '你发现的这块碎片是一种特殊牢笼的组成部分，$n。$b$b玛里苟斯的手下用这种牢笼关押他们俘虏的法师和其它奥术实体，但这只牢笼似乎是用来关押一种……更强大的生物。$b$b敌人的敌人很可能就是我们的朋友。你应该去搜索这只牢笼的其它碎片。$b$b它们很可能在玛里苟斯最亲信的下属手里。', '永生之盾的莱洛拉斯要你从塞鲁利恩将军手里夺取牢笼外壳，从战争使者戈德拉克手里夺取能量核心。', '<你所收集的部分在瑞洛拉兹手上发出光芒。>$B$B成了。$B$B我感应到这个监牢中有个强大的存在。希望我们能找到一个盟友。', '你找到了监牢的其它部分吗?', '', '去北风苔原找永生之盾的莱洛拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11944, '我们被包围了！', '我们现在的情况很让人绝望。我们接到命令说，要凭借两只手都数得过来的兵力占领悲叹通灵塔。$B$B我们能守住这个地方跟天灾军团对峙就已经很不错了！现在，我们寡不敌众，伤痕累累，而且还找不到撤退路线。$B$B如果你能帮忙减轻一下压力，我们有就机会巩固防线了。把围在建筑周边的那些亡灵干掉一些吧，那样我们就能抵挡住他们的进攻了。', '死亡营地的韦恩下士希望你消灭7名通灵塔防御者。', '那样应该会为我们争取到一些时间。$N。我们还抱着一线希望，希望会有来自骁勇要塞的援军抵达。', '你有任\r\n何进展吗?我们被困在这里。', '', '去北风苔原找死亡营地的韦恩下士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11945, '做最坏的打算', '黑暗已经降临。卡库特的灵魂漫步在卡斯卡拉，召集死去的海象人的幽魂。$B$B潜伏在迷雾中的敌人杀害了我们许多的同胞。很快，卡斯卡拉就会沦为死亡一般寂静的废墟。$B$B但是，还有一线希望。部分族人开始往乌努比转移。我们竭尽全力地作战，为的是让他们安全撤离这里。$B$B他们急需食物补给，否则就会活活饿死，因为乌努比也没有足够的粮食。请你尽快替我们的族人收集到足够的食物。', '乌泰克要你在卡斯卡拉收集8份卡斯卡拉补给品。', '感谢你，$N。这些补给品将会喂饱我们的族人。即使卡斯卡拉陷落了，我们的部族也得以延续。', '$N，你成功了吗?我们在昂纽沛的亲属就靠你的努力了。', '', '去北风苔原找卡斯卡拉的乌泰克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11947, '反击', '我们必须采取行动，维系平衡！时间非常紧迫。$B$B暮光教徒在凄凉之地西北方的艾瑟雷索创建了营地，企图利用寒冰之石与元素交流，就跟他们在希利苏斯的做法一样。虽然我很不情愿这样做，但是灵魂会理解的——你必须召唤并杀死埃霍恩手下的一员军官。或许这样就能阻止暮光教徒的阴谋……', '转至凄凉之地的艾瑟雷索，杀死从寒冰之石中召唤出来的冰雹上尉，然后返回任意主城中的大地之环长者处复命。', '你做得很好。这也许看来是很小的一步，但对大局来说却可以做为战斗的支持。收下这个和我的祝福，然后晚点再来，也许我会有更多事要让你去做。', '你凯旋归来了吗?', '', '去找大地之环长者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11948, '反击', '我们必须采取行动，维系平衡！时间非常紧迫。$B$B荆棘谷西部有一座受猎潮者耐普图隆管辖的岛屿。暮光教徒已经转至那座岛屿，企图利用寒冰之石与猎潮者所在的世界交流，就跟他们在希利苏斯的做法一样。虽然我很不情愿这样做，但是灵魂会理解的——你必须召唤并杀死埃霍恩手下的一员军官。或许这样就能阻止暮光教徒的阴谋……', '转至荆棘谷西部那座有水元素出没的岛屿，杀死从寒冰之石中召唤出来的寒风上尉，然后返回任意主城中的大地之环长者处复命。', '你做得很好。这也许看来是很小的一步，但对大局来说却可以做为战斗的支持。收下这个和我的祝福，然后晚点再来，也许我会有更多事要让你去做。', '你凯旋归来了吗?', '', '去找大地之环长者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11949, '战斗到底！', '$r，卡斯卡拉是我们海象人氏族的圣地。塔尤卡的灵魂指引我们的祖先来到这里。$B$B眼下，潜伏在迷雾中的邪恶生灵不断向我们发动攻击。$B$B是时候给它们点颜色瞧瞧了，我们的长矛可不仅仅是捕鲸的工具。朋友，请和我们并肩作战吧。海象人氏族将铭记你的恩情。', '阿泰卡要你在卡斯卡拉杀死12名克瓦迪尔劫掠者。', '感谢你，$N。如果我们真的能活下来的话，我欠你很大一份人情。', '我们要用牙齿和爪子来战斗，$N。科瓦迪尔得到的每一寸土地都要他们付出惨痛的代价。', '', '去北风苔原找卡斯卡拉的阿泰卡。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11951, '诱饵', '我在被囚禁期间了解到很多玛里苟斯的情况。在命运的推动下，我们终于有机会用这些情报来对抗他。$b$b在魔枢的上方盘旋着一条强大的蓝龙，莎拉苟萨。她既是玛里苟斯的护卫，也是他的配偶。如果有严重的威胁逼近，她就会警告她的主人。$b$b我在被囚禁的日子里可没少吃莎拉苟萨的苦头，现在她的末日就要来临了。但首先，我们要准备一个绝妙的诱饵……', '克莉斯塔萨要你在考达拉一带收集10块晶化法力碎片。$b$b如果你把奥术牢笼弄丢了，可以去找永生之盾的莱洛拉斯。', '感谢你，$N。$B$B我在被拘禁的期间耗尽了气力，而我的力量也从来没有恢复得这么缓慢过。$B$B我得谨慎地使用这些水晶的力量。它们是玛里苟斯邪恶计画的副产品。幸运的话，它们或许还能在玛里苟斯的毁灭上贡献一份力量。', '你收集到了我要求的法力裂片吗?', '', '去北风苔原找考达拉的克莉斯塔萨。如果你丢失了强化过的奥术牢笼，去找永生之盾的莱洛拉斯', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11952, '反击', '我们必须采取行动，维系平衡！时间非常紧迫。$B$B暮光教徒在灼热峡谷的观火岭创建了营地，企图利用寒冰之石与猎潮者所在的世界交流，就跟他们在希利苏斯的做法一样。虽然我很不情愿这样做，但是灵魂会理解的——你必须召唤并杀死埃霍恩手下的一员军官。或许这样就能阻止暮光教徒的阴谋……', '转至灼热峡谷西北部观火岭下的洞穴，杀死从寒冰之石中召唤出来的严寒上尉，然后返回任意主城中的大地之环长者处复命。', '你做得很好。这也许看来是很小的一步，但对大局来说却可以做为战斗的支持。收下这个和我的祝福，然后晚点再来，也许我会有更多事要让你去做。', '你凯旋归来了吗?', '', '去找大地之环长者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11953, '反击', '我们必须采取行动，维系平衡！时间非常紧迫。$B$B希利苏斯是暮光教徒在艾泽拉斯世界的大本营，他们在希利苏斯北部利用寒冰之石与猎潮者所在的世界交流。虽然我很不情愿这样做，但是灵魂会理解的——你必须召唤并杀死埃霍恩手下的一员军官。或许这样就能阻止暮光教徒的阴谋……', '转至希利苏斯北部的暮光小径，杀死从寒冰之石中召唤出来的冰川上尉，然后返回任意主城中的大地之环长者处复命。', '你做得很好。这也许看来是很小的一步，但对大局来说却可以做为战斗的支持。收下这个和我的祝福，然后晚点再来，也许我会有更多事要让你去做。', '你凯旋归来了吗?', '', '去找大地之环长者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11954, '反击', '我们必须采取行动，维系平衡！时间非常紧迫。$B$B暮光教徒在德拉诺世界的黑暗之门附近创建了营地，利用寒冰之石与冰霜之王交流。虽然我很不情愿这样做，但是灵魂会理解的——你必须召唤并杀死埃霍恩手下的一员军官。或许这样就能阻止暮光教徒的阴谋……', '转至地狱火半岛的黑暗之门，杀死从寒冰之石中召唤出来的冰川圣殿骑士，然后返回任意主城中的大地之环长者处复命。', '你做得很好。这也许看来是很小的一步，但对大局来说却可以做为战斗的支持。收下这个和我的祝福，然后晚点再来，也许我会有更多事要让你去做。', '你凯旋归来了吗?', '', '去找大地之环长者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11956, '寻找护命匣', '没时间说别的了，$N。我被派来执行一项自杀式的任务，要我们占领这座通灵塔。我已经完成了作为一个士兵的义务，现在，我要去寻求一些答案。$B$B这只巫妖掌握着许多我希望知道的情报，但我却无法对他造成任何伤害。$B$B这只巫妖将他的灵魂封在了一个护命匣中，藏在了其它地方。只要找不到那个护命匣，我就拿他一点办法都没有。$B$B所以，你得立刻回到营地去，骑上我的战马“黄昏”，它会带你去找到护命匣，把它带回来给我。', '转至死亡营地，骑着黄昏找到塔纳沙尔藏匿护命匣的地方。将它找出来并带回悲叹通灵塔，交给萨萨里安。', '你刚好赶上，$N。要束缚住一个巫妖并不像看上去那么容易。', '你回来了，$N。你拿到骨匣了吗?', '', '去北风苔原找悲叹通灵塔的萨萨里安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11957, '莎拉苟萨的末日', '我用你收集的法力结晶制造了这个能量源。$b$b莎拉苟萨非常贪婪，她肯定无法抵抗它的诱惑，但是能量源里面蕴涵的魔法可以严重削弱她的力量。但愿她不会看穿我的计划……$b$b去做好准备，$n。当你做好与莎拉苟萨战斗的准备之后再来找我。', '克莉斯塔萨要你使用奥术能量源引出莎拉苟萨并打败她。', '现在没有了萨拉苟莎，这个世界又改善了一些，但我们的工作还没有结束。$B$B现在是时候对付玛里苟斯本人了!', '绝不能让萨拉苟莎活着!', '', '去北风苔原找考达拉的克莉斯塔萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11958, '不要浪费', '狼獾人一直是我们的天敌。不过随着你们的人大量涌入龙骨荒野，他们已经被逼到了北面的一小块林地里。$B$B今早的地震过后，他们的攻击性变得更强了。到现在，他们已经劫走了我们好几批货物……那都是我们迁徙途中的必需品。$B$B为了证实你的善意和友好，请从飘雪林地的狼獾人那里夺回我们的货物。', '从狼獾人手中夺回6份被偷走的莫亚基货物，把它们带回龙骨荒野的莫亚基港口，交给长者库纳尼。', '拜托你为我们做这种事情很让我过意不去，但为了尽快完成我们的远行，这是我们唯一能做的。虽然要去哪里，我们现在还不知道。$B$B我的巫士们告诉我，你就是要从暗影行者手中拯救这片土地的人。$B$B我同样相信，你会拯救这片土地上的人们。', '最近，自然的平衡一再的被破坏。$B$B我希望你能帮助我们度过这场生命的剧变。', '', '去龙骨荒野找莫亚基港口的长者库纳尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11959, '消灭洛根', '情况越来越糟糕了。现在只有一个办法……虽然很遗憾，但我们必须杀了洛根！$B$B他是飘雪林地部族的首领，一个残忍的狼獾人。这是让他们暂停劫掠的唯一办法了。$B$B他的茅屋就在林地的北部，这个“金刚狼”应该就站在自己的房前。他的房子比其它狼獾人的都大，你不会认错的。去杀死他，将他的鲜血抹在身上，以显示你的强大和高贵。', '将洛根的血抹在身上，然后回到龙骨荒野的莫亚基港口，向长者库纳尼复命。', '洛根在你手上光荣的牺牲，正是我的族人所需要的，而我们会令其它的獾狼怪争夺他的位置。$B$B这样就足够了。', '你身上的是洛根的血，还是你自己的，$r?', '', '去龙骨荒野找莫亚基港口的长者库纳尼。', '将洛根的血涂在身上', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11960, '未来的种子', '如果我们想要生存下去，就必须对狼獾人采取果断行动了。但我担心我们的狂热会导致残酷的屠杀。$B$B飘雪林地的狼獾人和我们一样拥有生存的权利。我们要确保他们能得到生存下去的机会。$B$B就算长者库纳尼现在还没有提出，迟早他也会让你去解决他们的。当你转至北面的林地时，请你把他们的幼崽带回来。', '找到12个飘雪林地幼崽，把他们带回莫亚基港口，交给猎手莫伊。', '很好，我想你应该拯救了不少。感谢你，$r。$B$B现在獾狼怪有机会我们一起存活下来了。当然，如果我们能幸存的话。$B$B你明天可以再回来一趟，好让更多幼犬获救吗?', '这么短的时间内，你能救多少幼犬?', '', '去龙骨荒野找莫亚基港口的猎手莫伊。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11961, '神灵的眷顾', '拥有强大力量的灵魂守护着海象人的氏族，卡斯卡拉是不会沦陷的。$B$B伊斯利鲁克赐予我们勇气，塔尤卡为幸存的族人提供食物和避难所，卡库特则负责守护亡魂并确保他们不会迷失方向。$B$B眼下我们迫切需要伊斯利鲁克的指引。我本来派了我的侄子伊鲁克去取回伊斯利鲁克的图腾，但是他不幸被克瓦迪尔的长矛刺穿，倒在北边的海水中。$N，替我取回图腾。别让我的侄子就这么白白搭上一条性命。', '尼约德海湾的长者穆希特要你潜入水中找到伊鲁克的尸体，取回伊斯利鲁克的图腾。', '你能感受到依斯里鲁克的存在吗，$N?他不希望他的子民在迷雾行者的手中死去。', '你拿了那个图腾吗，$r?', '', '去北风苔原找尼约德海湾的长者穆希特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11962, '最后一批矿石', '那么，有了你带回来的矿石，我们总算能凑齐足够的物资送往无畏要塞了。$B$B如果致远郡从艾泽拉斯的版图上消失，至少人们会记住，我们是第一批站出来保卫自己土地的人，也是最后一批倒下的人。$B$B把这些矿石交给希尔达·熔石——她是我的好朋友。让她用这些矿石制造一些精良的武器，我们很快就会需要大量武器了。', '将一箱致远郡矿石交给无畏要塞里的希尔达·熔石。', '从远郡来的矿石?日程表上没有这次运送。发生什么事了吗?', '你带了些什么?', '', '去北风苔原找无畏要塞的希尔达·熔石。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11964, '夏季的焚香', '每座联盟营地外都设有节日篝火，你知道吗？护火者就驻扎在营地外的帐篷中，确保篝火熊熊燃烧，直到火焰节结束。$B$B每个护火者身边都会有一个夏季火元素，它是火元素之魂派来的使者。$B$B你想不想去祭拜一下这些夏季火元素呢，$N？拿着这把夏季焚香，把它交给任意一个夏季火元素。只要你对这些小家伙表示出足够的敬意，它就会奖赏你。', '节日博学者希望你带着夏季焚香转至任意联盟营地外的篝火旁，将焚香交给该处的夏季火元素。', '喔，这是什么?多么令人开心的芳香!我肯定这一定会让火焰烧得更加纯净与明亮!$B$B收下这些花朵，$N。收下它并且让我独自一人…我一定好好感受这珍贵的香气…', '炽热地问候，可敬的$C。欢迎来到仲夏火焰节庆的圣地。', '', '去找夏季火元素。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11965, '集结的钟声！', '现在致远郡有了放手一搏的能力，$N。你做到了我们甚至不敢奢望的事。$B$B现在我们必须集合起来发动进攻。我会让我的人把武器运到镇子的议事大厅里，请你去敲响议事厅里的钟，让所有的幸存者到那里集合。$B$B现在该让天灾军团看看我们的力量了。', '转至致远郡的议事大厅，敲响里面的钟。', '再次感谢你协助我们，$N。远郡的居民永远不会忘记你的。', '你召集了幸存者了吗，$N?', '', '去北风苔原找致远郡的吉拉德·格林。', '敲响致远郡的钟', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11966, '节日的焚香', '每座部落营地外都设有节日篝火，你知道吗？护焰者就驻扎在营地外的帐篷中，确保篝火熊熊燃烧，直到火焰节结束。$B$B每个护焰者身边都会有一个夏季火元素，它是火元素之魂派来的使者。$B$B你想不想去祭拜一下这些夏季火元素呢，$N？拿着这把夏季焚香，把它交给任意一个夏季火元素。只要你对这些小家伙表示出足够的敬意，它就会奖赏你。', '节日诗人希望你带着夏季焚香转至任意部落营地外的篝火旁，将焚香交给该处的夏季火元素。', '喔，这是什么?多么令人开心的芳香!我肯定这一定会让火焰烧得更加纯净与明亮!$B$B收下这些花朵，$N。收下它并且让我独自一人…我一定好好感受这珍贵的香气…', '炽热地问候，可敬的$C。欢迎来到仲夏火焰节庆的圣地。', '', '去找节日火元素宠物。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11967, '集结红龙', '玛里苟斯肯定已经发现情况有些不对劲了。$b$b我了解他。他的精神很难集中。我敢肯定，如果他知道他那亲爱的莎拉苟萨出了什么事，肯定会不顾危险地从他的领地里冲出来。$b$b立刻带我去见莱洛拉斯，$n。他必须调集所有的龙来对抗玛里苟斯。', '克莉斯塔萨要你带她去永生之盾会见莱洛拉斯。', '我已经知道了克莉斯塔萨获救的消息。你很令人赞赏。$B$B我需要尽快和她谈谈。', '你有消息要带给我，$N?', '', '去北风苔原找永生之盾的莱洛拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11968, '情势扭转', '$N，神灵们听到了我们发出的呼喊，卡斯卡拉的局势也许会有所转机。$B$B趁着浓雾潜入尼约德海湾，除掉克瓦迪尔部族的首领。只要他一死，我们就能稳占上风。', '长者穆希特要你去除掉尼约德海湾的可怕的赫迦尔。', '我们欠你一份很大的人情，$r。战斗还没有胜利，但我的同胞有了一线希望。', '你完成了被交付的任务吗，$N?', '', '去北风苔原找尼约德海湾的长者穆希特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11969, '触动陷阱', '多亏了你的帮助，我们才能得到这个机会，$n。$b$b所以应该由你来发动对玛里苟斯的攻势。$b$b转至魔枢的西北入口处，用这种火花点燃那里的信号火焰。克莉斯塔萨会与你并肩作战的。', '莱洛拉斯要你在考达拉的信号火焰处使用莱洛拉斯的火花。', '我们对玛里苟斯做出了一次打击，但代价很高昂。', '你见到了克莉斯塔萨?', '', '去北风苔原找永生之盾的莱洛拉斯。', '突袭玛里苟斯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11972, '埃霍恩的碎片', '碎片跳动着，透露出不祥的征兆。难道其中蕴含着冰霜领主的精华？', '将寒冰碎片交给鲁玛·天母。', '的确，这些裂片蕴含着冰霜领主在这块土地上最后的精华。我们会处理它，把艾胡恩放逐到冰冷的虚空国度。$B$B感谢你，$N。你的名字将被大地之环永远传颂。如果你收下这点东西会是我们的荣幸，这象征了你的仁慈、温暖与光明。', '你好，$N。你看来很忧虑，但你应该要高兴。冰霜领主已经被打倒了!', '', '去埃霍恩领主的仲夏所在地找鲁玛·天母。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11973, '战争的囚徒', '玛里苟斯把克莉斯塔萨抓走了？！他要强迫她成为他的新配偶？！这简直无法想象！$b$b她一定很不情愿，但玛里苟斯的力量非常强大，她的意志最终还是会屈服的。$b$b我们不能让这种事发生，$n。我不允许她遭受这种侮辱。$B$B你必须进入魔枢，尽一切可能让她免受侮辱！', '永生之盾的莱洛拉斯要你进入魔枢并释放克莉斯塔萨。', '所以，任务已经完成了…$B$B我们的族人将永远都不会忘记克莉斯塔萨为此所做的牺牲。我们也不会忘了你所参与的部分，$N。$B$B愿此件惨事让我们更加坚定我们的决心，对抗所面对的威胁。$B$B以红龙军团的名义，请收下这份表达我们感谢的礼物。', '你找到了克莉斯塔萨吗?你有办法从控制她的束缚中解放她吗?', '', '去北风苔原找永生之盾的莱洛拉斯。', '让克莉斯塔萨安息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11978, '深入密林', '在正式将牦牛人引入部落之前，我们得先把附近森林里那些阿努巴尔蛛魔夺走的东西抢回来。昨天深夜里，阿格玛之锤过来的一支补给车队遭到了天灾军团的伏击，武器装备都被抢走了。$B$B去吧，进入西风避难营东边的森林，夺回我们的武器装备，$r。', '龙骨荒野西风避难营的特使艾米萨·闪蹄要求你找回10套部落军备。', '这正是我们所需要的，$N!印着部落徽记的武器将会提振他们的精神，并且提供他们对抗天灾军团的保护。$B$B你准备好加入典礼了吗?$B$B<亮蹄点点头。>$B$B你将会见证我们的新盟友加入部落。', '没有武器和盔甲我们的新成员在迁徙往阿格玛之锤的路上将毫无防御之力。', '', '去龙骨荒野找西风避难营的特使艾米萨·闪蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11980, '部落的荣耀', '我们的运输车队原本是要把大批武器装备运到这处营地来，而我是负责护送运输车队的卫兵之一。谁知道天灾军团毫无征兆地发动了一次闪电般的突袭。我们全力奋战，杀死了无数蛛魔，可最终还是被它们的数量完全压制。全队的卫兵，似乎只有我和托尔辛活了下来……$B$B若不是因为伤势太重，我们肯定会满森林地寻找那些该死的蛛魔，拼了命也要杀光它们。但现在……唉……你能帮我们夺回失去的荣耀吗？搜索这片森林的东部，找出所有的阿努巴尔蛛魔，灭绝它们！为了部落！', '龙骨荒野西风避难营的血卫士洛恩基尔要求你消灭15只阿努巴尔伏击者。', '<罗奇尔向你敬礼。>$B$B你维护了我们的荣誉，$N。托辛和我感谢你无私的举动!', '不必留情，$r。杀死那些阿努巴害虫!', '', '去龙骨荒野找西风避难营的血卫士洛恩基尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11982, '巨石横飞', '我们下方就是铁矮人自古以来的领地——索尔莫丹。几千年前，石巨人踏裂了大地，将那座地底城市的一部分永远掩埋在了坍塌的山石之下，另一部分则暴露出了地表，几近毁灭。$B$B然而，直到今天，那些铁矮人仍在试图夺回他们过去的王城，但我们绝不会允许。我手下的巨人们每天都在用巨岩与碎石填补着他们挖出来的沟壑，希望能阻止他们的进犯，让他们永远放弃这里。你也带上一些巨石到东北方的沟壑边去，帮助我们彻底毁灭敌人的顽抗吧。', '在丘陵上俯瞰索尔莫丹的库伦要求你向索尔莫丹的露天区域投掷石块，以此骚扰铁矮人的挖掘工作。', '我们持续地填塞裂沟，铁矮人则是拼命地清理。我们从上方的袭击无法攻下整座城市。你必须要协助底下广场的土灵。', '你要回报些什么?', '', '去灰熊丘陵找巨石丘陵的库伦。', '骚扰铁矮人的工作', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11983, '部落的血誓', '他们已经准备好了，$N。这些牦牛人迫切地希望加入部落，并愿意倾尽全力向亡灵天灾复仇。$B$B<特使掏出了一封印有部落徽记的羊皮卷，郑重地递给了你。>$B$B这封卷轴上写着部落的血誓。根据我们古老而高贵的传统，牦牛人兄弟姐妹们将跟随着一位引导人念出卷轴上面所载的神圣誓言，从而完成加入部落的仪式。$B$B去吧，将这个卷轴交给他们，让牦牛人们宣誓加入部落，指挥官。完成你在仪式中的职责之后，再回来找我。', '与西风避难营的牛头人交谈，并收集5份他们对部落的效忠宣誓书。$B$B完成任务之后，带着部落的血誓向特使艾米萨·闪蹄复命。', '感谢你，指挥官$N。他们已经一无所有了。你给了他们一个目标，而目标能带来希望…对崭新明天的希望…一个新生命的希望。', '他们会让部落更加强大，指挥官。', '', '去龙骨荒野找西风避难营的特使艾米萨·闪蹄。', '牦牛人加入部落', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11984, '抓巨魔', '巴德以前也风光过。$B$B不过从幽魂之地开始，他就对我们毫无用处。很多事情我们只好自己想办法去做，所以我们打算把冰巨魔卖给出价最高的人。$B$B幸运的是，我们最近发现又有地方可以用到巴德了。以他的“条件”，他可以很轻易地混在本地的巨魔之中，所以我们只要教他一点小把戏，他就能给我们带来一笔可观的收入。$B$B去和巴德谈谈，把他带去西南方的达克辛废墟，等他标记了某个巨魔之后就使用这只笼子。', '岩石之泉的萨米尔希望你对被巴德打昏的达卡莱巨魔使用赏金猎人的笼子。', '做的好哇，$C。看来我们可以让霸德在这多待久一点。$B$B我们马上就把你的笼子处理好，这是你的赏金。$B$B喔，欢迎来到营地，多逛逛，我相信我们能合作愉快的…', '你准备好抓住寒冰巨魔了吗?', '', '去灰熊丘陵找岩石之泉的萨米尔。', '活捉冰巨魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11985, '攻破防线', '如果不能攻破索尔莫丹的外围防线，那么铁矮人就永远不会投降。土灵战士们正在勇敢地应对着那些钢铁之子造出来的机械，可这些机械的强大与坚韧彻底将他们阻拦在了城市之外。$B$B周围那些可以用于潜入的坑道却又太过狭窄，巨人们完全无法利用，所以，我们的选择很有限。你愿意潜入城市，帮我们除掉指挥防务的矮人军官吗？', '库伦要你杀死指挥官阿格鲁姆，然后返回鸟瞰索尔莫丹的小山坡向他复命。', '干得好，$N。铁矮人丧失了他们的指挥者，这应该足以让我们击垮他们剩下的防卫力量。土灵应该能应付那些幸存者。', '你杀死指挥者了吗?', '', '去灰熊丘陵找巨石丘陵的库伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11986, '破损的日记', '你翻阅着这本污渍斑斑、残缺不全的日记，发现书页上排着密密麻麻的笔记，还配有图表和地图。$B$B作者的字迹有些眼熟，可一时之间你也想不起是谁，直到你看见一则笔记中留有布莱恩·铜须的名字。$B$B日记的后半部分被撕掉了，无法看到最新的笔记内容。书页散落在战场上，要想知道布莱恩究竟发现了什么，就必须复原这本日记。', '找到8张遗失的日记书页，将它们与不完整的日记拼凑起来，然后将日记交给月溪旅营地的托尔森·迪普迪格。', '你找到了布莱恩的日志?不可思议!协会很久没有他的消息了，我们开始担心他被抓了或是被杀害。他在铎尔莫丹中发现了什么?', '你找到了什么?', '', '去灰熊丘陵找月溪旅营地的托尔森·迪普迪格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11988, '符文钥石', '布莱恩在日记中提到，他利用符文钥石来破译雕刻在金属板上的符文。没有那玩意儿的话，我们根本无法参透金属板上的内容。$B$B最后一则笔记写道，铁矮人从布莱恩手中抢走了符文钥石，将它砸成若干块碎片，分别保存起来。我们必须夺回碎片，才能破译符文金属板。索尔莫丹以及附近的建筑物中到处都是矮人，他们可能携带着符文钥石碎片。', '将5块符文钥石碎片交给月溪旅营地的托尔森·迪普迪格。', '<多杉迅速地重组你收集来的碎片。>$B$B这还不够完整，但应该足以让我们从金属板上取得大部分的资讯了。', '你收集到足够的碎片好重做拱心石了吗?', '', '去灰熊丘陵找月溪旅营地的托尔森·迪普迪格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11989, '停战？', '你给我小心点。$B$B达库鲁已经记不清自己拿到过多少颗$r徽记了——即便能记得，我都不知道该怎么数下去了。对你来说幸运的是，我被关在了这只笼子里，否则我的名单上又会增加一个名字。$B$B不过事情总是在发展的，也许我们可以把彼此之间的分歧暂时放在一边，嗯？$B$B达库鲁知道一些事情，朋友。一些能帮助你的事情。$B$B<达库鲁用他的獠牙割开了手掌，然后把手伸出笼子。>$B$B那么，你怎么想，朋友……让我们定下停战协议，歃血为盟怎么样？', '岩石之泉的达库鲁希望你在他的笼子附近使用钝刻刀，然后和他对话。', '啊哈!$B$B现在我们透过血而相连了，老兄。我们有了真正的羁绊。$B$B你仔细听达库鲁的，$r，我们有很多事情得做。', '正确的选择，老兄。你不会活着后悔这件事情……', '', '去灰熊丘陵找岩石之泉的达库鲁。', '与达库鲁定下血契', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11990, '幻象之瓶', '事有轻重缓急，朋友。首先有些准备工作需要去做。$B$B我不知道他们要把我关在这里多久，所以你需要一种强大的药剂让我们保持联络。$B$B你真幸运，我正好知道怎么制作那东西，而这附近碰巧又有必需的材料。$B$B我需要一只瓶子——那边的巨魔朋友就有卖，一些生长在这里北面湖泊里面的水草叶，外加几片营地周围就有的薄雾叶。$B$B在他们把我拖走之前，赶紧的，朋友。', '岩石之泉的达库鲁希望你把一只灌魔之瓶、一片水草叶和3片薄雾叶交给他。', '<达库鲁将材料熟练地混合在一起并且放入瓶中。>$B$B这样应该可以了，老兄。上工的时候到了。', '你找到那些东西了吗，老兄?', '', '去灰熊丘陵找岩石之泉的达库鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11993, '符文中的预言', '时间宝贵！我们已经完全修复了符文钥石——呃，几乎是完全。不管怎么说，现在可以破译那些符文金属板啦，布莱恩在失踪前一直潜心研究金属板上面的内容。$B$B我们也不确定布莱恩是否能解读三块金属板上的所有文字，但是他应该会采用抽丝剥茧、逐一破译的思路。$B$B在三块金属板前分别使用钥石解读上面的内容。布莱恩的希望就寄托在我们身上了！', '月溪旅营地的托尔森·迪普迪格要你破译3块符文金属板的内容。', '<多杉听你解说符文板上的内容。>$B$B玛多兰的锤子啊，他找到了一个新的泰坦城市!$B$B石头与钢铁的发源地。$B$B“奥杜亚座落于风暴之中。”$B$B你知道那是什么意思吗?那里可能就是我们的起源故乡，在这么多年之后?$B$B我们得跟着他!我们得找到他!', '你发现了什么?', '', '去灰熊丘陵找月溪旅营地的托尔森·迪普迪格。', '破译第一个预言', '破译第二个预言', '破译第三个预言', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11998, '灵活的手段', '想让大部队迅速抵达冰冠冰川，最好的方法就是利用铁矮人的古老城邦——索尔莫丹的地下隧道系统。$B$B探险者协会的布鲁加尔·石剪和他手下的同伴多半不乐意这样做，但是军令如山，就由不得他啦。$B$B如果你能捎上一桶冰风月光酒，他或许会勉为其难地接受这项指令。沿着林地线往东南走，你可以从红木商栈的猎户休·格兰斯手中买到这种酒。$B$B那家伙的神经有点不正常，不过他卖的酒倒是绝无第二家的。', '将一桶冰风月光酒交给月溪旅营地的布鲁加尔·石剪。', '让我搞清楚 -- 一个我不认识的$r，带给我一桶这个该死的森林中最好的酒。好吧，那你在打什么主意?', '你找到了什么?', '', '去灰熊丘陵找月溪旅营地的布鲁加尔·石剪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (11999, '寻找线索', '西南面的眠月花园以前曾经是一群高贵的上层精灵的最终安息地，那里同样是一个强大的魔网能量线枢纽。$B$B蓝龙军团利用一种被他们自己称为“湍流之针”的魔法设备摧毁了那个枢纽，释放了能量，将能量指引去他们想要的地方。$B$B我希望你能帮我寻找我想要的信息。$B$B在这片土地被摧毁之后，上层精灵的鬼魂开始复活并击败了一部分法师猎手成员。去他们的尸体上看看有什么有用的信息。', '找到眠月花园计划书，然后返回阿格玛之锤，将它交给大法师艾萨斯·夺日者的影像。', '有意思，他们想要和复仇军合作。以太族确实对于玛里苟斯和他的疯狂而言是个强力的盟友。$B$B这样可不行!', '你回来了。你发现了些什么?', '', '去龙骨荒野的阿格玛之锤找大法师艾萨斯·夺日者的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12000, '寻找线索', '西南面的眠月花园以前曾经是一群高贵的上层精灵的最终安息地，那里同样是一个强大的魔网能量线枢纽。$B$B蓝龙军团利用一种被他们自己称为“湍流之针”的魔法设备摧毁了那个枢纽，释放了能量，将能量指引去他们想要的地方。$B$B我希望你能帮我寻找我想要的信息。$B$B在这片土地被摧毁之后，上层精灵的鬼魂开始复活并击败了一部分法师猎手成员。去他们的尸体上看看有什么有用的信息。', '找到眠月花园计划书，然后返回群星之墓，将它交给大法师茉德拉的影像。', '有意思，他们想要和复仇军合作。以太族确实对于玛里苟斯和他的疯狂而言是个强力的盟友。$B$B这样可不行!', '你回来了。你发现了什么?', '', '去龙骨荒野的群星之墓找大法师茉德拉的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12002, '战斗中的兄弟', '战争打响后，我就下令探险队撤离了索尔莫丹，格里安难道不知道？除非那里恢复和平，否则别想让我们挖掘地下隧道。$B$B你能赢得格里安·斯托曼的信任，看上去倒是个勇敢的家伙。$B$B索尔莫丹就在东北方，我们的同伴还在和那些该死的铁矮人作战呢。帮助他们赢得胜利，这样我才能着手部署详细的调查方案。', '消灭10台符文作战魔像，然后返回月溪旅营地向布鲁加尔·石剪复命。', '<布鲁嘉听着你的回报。>$B$B听起来事情似乎和缓了一些。我们会开始寻找进入铁矮人隧道系统的方法。', '铎尔莫丹的情况如何?', '', '去灰熊丘陵找月溪旅营地的布鲁加尔·石剪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12003, '寻找隧道', '我们打算从索尔莫丹边缘地带的建筑群开始搜寻，看看能不能发现地下隧道系统的入口。$B$B探险队撤离那里时，我留意到铁矮人防御者将建筑物作为掩体，所以你得当心点。$B$B隧道入口极有可能位于建筑物背面。格里安·斯托曼大概希望我们有所发现吧，不过我怀疑铁矮人会不会让我们轻易得手。', '月溪旅营地的布鲁加尔·石剪要你前去侦查索尔莫丹的北部建筑物、东部建筑物和南部建筑物。', '<布鲁嘉啐了一声以矮人语咒骂着。>$B$B没有入口?没有?$B$B不，这当然不可能太容易。嗯，看来想尽入城市是免不了一场战斗。我的手下再也没办法进行真正的工作。', '我很怀疑你有打算找到隧道，你有吗?', '', '去灰熊丘陵找月溪旅营地的布鲁加尔·石剪。', '调查北部建筑物', '调查东部建筑物', '调查南部建筑物', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12004, '阻碍协议', '现在我们需要做的就是一箭双雕，$c。$B$B你就是那支箭，而商人穆法赫和古拉莫什就是那两只雕。他们应该就在眠月花园的西半边，去那座两层楼的大房子里找找看。$B$B如果可以的话，我希望看到他们死亡的凭证。', '将商人穆法赫的遗骸和古拉莫什的鳞片带回群星之墓，交给大法师茉德拉的影像。', '可惜葛拉莫什指出协议已经达成了。$B$B但不管怎样，终究是少了两只需要烦心的虫子。让我们来进行更重要的事情吧。', '你阻止蓝龙军团与复仇军的协议了吗?', '', '去龙骨荒野的群星之墓找大法师茉德拉的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12005, '阻碍协议', '现在我们需要做的就是一箭双雕，$c。$B$B你就是那支箭，而商人穆法赫和古拉莫什就是那两只雕。他们应该就在眠月花园的西半边，去那座两层楼的大房子里找找看。$B$B如果可以的话，我希望看到他们死亡的凭证。', '将商人穆法赫的遗骸和古拉莫什的鳞片带回阿格玛之锤，交给大法师艾萨斯·夺日者的影像。', '这样就好，$C，就把他们放在阿格玛的王座前。$B$B<你几乎可以感觉到大法师在头盔下的笑容。>$B$B可惜葛拉莫什指出协议已经达成了。$B$B但不管怎样，终究是少了两只需要烦心的虫子。让我们来进行更重要的事情吧。', '你阻止蓝龙军团与复仇军的协议了吗?', '', '去龙骨荒野的阿格玛之锤找大法师艾萨斯·夺日者的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12006, '上层精灵的愤怒', '那些所谓的法师猎手毁了我们的安息之地。$B$B去为我们复仇，否则，我发誓——你们的基地会被亡者的怒火夷为平地！', '击败龙骨荒野法师猎手、眠月魔犬、湍流之针巫师和魔法焦点巫师，总计15名。完成任务后返回眠月花园，向伊瑟尼安·月影复命。', '很好，你已经满足我对你的要求了。$B$B谢谢你，$r。', '我总觉得你还没杀够这些污染者!', '', '去龙骨荒野找眠月花园的伊瑟尼安·月影。', '击败眠月花园的蓝龙军团士兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12007, '必要的牺牲', '我明白了，朋友！$B$B在北边，塞布哈拉克的通灵塔上有个镶着红宝石眼睛的石头脑袋，其中一颗红宝石就是预言者之眼！你要把它拿到那里的火盆旁，然后喝下我的药剂。$B$B跟以前一样，你仍然需要一些特殊的魔精才能让我的药剂生效——这次是督军希姆波的。他就藏在塞布哈拉克的某个棚屋里。$B$B要杀死希姆波真的很可惜，但他发过血誓要保卫达克萨隆，最后却失败了。现在他的魔精能够帮助我们夺回达克萨隆。', '达库鲁希望你转至塞布哈拉克，找到他的火盆，并将预言者之眼交给他。$b$b你需要取得督军希姆波的魔精，才能在那里使用达库鲁的药剂。', '就是它，老兄!$B$B它比我期望的更珍贵。这肯定能在这样黑暗的时刻带给我的人民希望。$B$B现在，没有时间可以浪费了。让我们来瞧瞧下一个神器被藏在那里。', '你拿到预言者之眼了吗，老兄?', '', '去灰熊丘陵的塞布哈拉克找达库鲁的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12009, '图尔凯的螃蟹陷阱', '一片混乱之中，我和我的助手失散了。你能不能帮我个忙呢？$B$B我在港口的水下设了许多捉螃蟹的陷阱，你能帮我去把它们收回来吗？我太老了，干不了这种活，而且水下很危险。$B$B拿着这只气囊，它能帮你在水下呼吸。', '收集8个图尔凯的螃蟹陷阱，然后把它们交给莫亚基港口的图尔凯。', '我只是一个普通的陷捕者，这个世界突然间天翻地复，一点理由也没有。$B$B我希望你能导正这一切。', '你打算要抓多少只螃蟹?', '', '去龙骨荒野找莫亚基港口的图尔凯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12012, '通知长者', '必须立即把这条消息通知到大地之环的所有成员。我不知道要如何做到这一点，但是派你来执行这项任务的长者应该知道。请你立即返回长者身边，做好进行下一步任务的准备——我们必须立即做点什么！', '返回任意主城，同大地之环长者交谈。', '这的确是个严重的消息。我们一定要竭尽全力来避免战争的发生。', '有什么让你困扰吗，孩子?', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12013, '阿坎尼姆斯的终结', '我还要请你做最后一件事，$r$N。我要你去杀死阿坎尼姆斯！$B$B西面的那些巫师在空中部署的巨大装置……它在我们的安息之地里炸出一个大坑，也释放出了那个怪物！$B$B如果它只对凡人感兴趣，那我才懒得理它。但是阿坎尼姆斯专吃死者的灵魂。$B$B你必须立刻去终结它！', '摧毁阿坎尼姆斯，然后返回眠月花园向伊瑟尼安·月影复命。', '我献上最深的感激，$N。$B$B如果你还没的话，你应该快去警告你的长官关于蓝龙军团所带来的危险。透过炸毁花园之下的地脉锚点，他们可能会摧毁我们全部人!', '你以为我是笨蛋吗?阿肯尼玛斯还在吞食我兄弟姊妹的灵魂，$C!', '', '去龙骨荒野找眠月花园的伊瑟尼安·月影。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12014, '坚如盘石？', '奥尔隆德在日记中写道，他随身携带着一件名叫便携式测震仪的器械，不过你在他的尸体附近没找到这样的东西。$B$B勘察记录显示，除了“暴露在地表的那条隧道的东部端口”，奥尔隆德已经对索尔莫丹的其它隧道进行了稳定性测试。$B$B从最后一则日记来看，他企图躲入水中避难，却遭到水下蛇颈龙的攻击。那件器械很可能是被蛇颈龙夺走了。你必须取回仪器才能完成测试工作。', '夺回便携式测震仪，并用它记录索尔莫丹地下隧道的稳定性指数，然后返回月溪旅营地，向布鲁加尔·石剪复命。', '<布鲁嘉查看了报告。>$B$B这可不妙，就算我们能凿开挡住的坑道，也无法保证是否会再度崩塌。看起来这区域几个世代以来就已经没有人使用它了。我们必须把这个坏消息告诉格里安上尉。', '你找到了什么?', '', '去灰熊丘陵找月溪旅营地的布鲁加尔·石剪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12016, '诱饵', '我可以肯定……远古的水族复仇者，“戏耍猎物者”图格瓦尔已经回来了。我们必须给它设一个陷阱。$B$B图格瓦尔唯一的弱点就是贪吃。有一种肉它是绝对无法抗拒的。$B$B所有螃蟹的母亲，“双钳巨蟹”基利瓦盘踞在西南方的小岛上。你必须去找到她，把她的肉带回来。', '取得“双钳巨蟹”的肉，把它交给莫亚基港口的图尔凯。', '你能够杀死齐里厄雅…或许也能对付吐乌格瓦。$B$B也许不行。', '你带回了齐里厄雅的多汁肉块吗?', '', '去龙骨荒野找莫亚基港口的图尔凯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12017, '鱼钩上的肉', '是时候了，我的朋友。我们必须解决图格瓦尔！$B$B我已经把肉准备好了，只要你把肉挂在我放进水里的鱼钩上，它就肯定会出现。你只需顺着这根鱼线就能找到鱼钩。$B$B无论怎样，可千万别让图格瓦尔把你给吞了，$N！', '杀死图格瓦尔，然后向莫亚基港口的图尔凯复命。', '年轻的朋友啊，我们为你的成功欢声雷动!海水中满是我等敌人的血液!$B$B请你收下我这个老渔夫永恒的感谢，只要我将这个消息散布开来，还有所有的卡鲁亚克族人将同样万分感谢!$B$B请收下，我坚持，从中挑选你的奖赏。', '我想我看到了一些翻滚的浪花…吐乌格瓦死了吗?', '', '去龙骨荒野找莫亚基港口的图尔凯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12019, '最后的义务', '我之所以会在死后侍奉阿尔萨斯，是因为我别无选择。他曾经完完全全地控制我的意志与我的身体。而诅咒教派则不同，他们全体成员……都自愿地侍奉阿尔萨斯……$B$B现在，既然已经知道了进入纳克萨纳尔的咒语，我们就可以彻底消灭诅咒教派。立刻转至恩其拉，在浮空城的正下方寻找传送宝珠。$B$B找到之后，和我在上面会合。准备好你的一切武器与装备，鼓起你的勇气，我们或许……会永远倒在那里。', '进入圣城恩其拉，找到浮空城纳克萨纳尔下方的传送宝珠。使用它进入浮空城的顶部，然后帮助萨萨里安。', '你做得很好，$N。我就是希望能够让我妹妹不要涉入这一切。她能活得好好的都要感谢你。$B$B我对吾王与我军的责任已经圆满的达成了。显然，我在我的同志之间已不受欢迎。我必须找出我自己的道路，仅参与吾之战争，仅听从吾心之令。$B$B也许我们将会再见面，$C。在重逢之日到来之前，拿着这个以象征我的感激。', '向你致敬，$N。', '最后的义务', '去北风苔原找纳克萨纳尔的萨萨里安。', '最后的义务', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12022, '扔酒杯！', '嗨！你看上去酒量不错。不过不知道你扔杯子的技术是不是也很棒？$B$B黑铁矮人实施了复仇计划，想要破坏我们的美酒节庆典。朝他们扔杯子就能阻止这帮家伙；但首先，你得试试能不能用酒杯击中掷杯训练器。$b$b很简单，拿起免费美酒节取样器喝上一口。然后朝着掷杯训练器抛过去就行啦，确保你要面向训练器哦。等你击中训练器5次后，再来找我谈谈。', '用免费美酒节取样器击中掷杯训练器5次，然后与波克希·博斯宾谈一谈。', '你知道那是什么吗?地精工程学的最高杰作!S.T.O.U.T.能像个斗士般耐打!$B$B我认为你现在已经准备好应付那些黑铁矮人，如果那些家伙再次出现的话。', '一个往后丢，一个往前丢。S.T.O.U.T.撑得住，不然我造他出来干嘛。', '', '去找丹莫罗的波克希·博斯宾。', '击中掷杯训练器', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12026, '破损的日记', '你翻阅着这本污渍斑斑、残缺不全的日记，发现书页上排着密密麻麻的、以矮人语写下的笔记，还配有图表和地图。$B$B在某个角落中，你解读出了唯一一段你能理解的字句，这是一个姓名——布莱恩·铜须。$B$B日记的后半部分被撕掉了，无法看到最新的笔记内容。或许是有些人认为这上面所记载的内容过于机密，因此想要毁灭它。或许把失去的那几页找回来，你就能得到更多的线索。', '收集8张遗失的日记书页，将它们与不完整的日记合并，然后将完整的日记交给欧尼瓦营地的先知帕鲁纳。', '这个布莱恩.铜须是谁?铁矮人没理由要和他交涉，我也不知道为什么要对他写的文字感兴趣。', '你找到了什么?', '', '去灰熊丘陵找欧尼瓦营地的先知帕鲁纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12028, '灵魂视界', '$R，自从上次大地震动并裂开以后，我们在因度雷村的同胞就没有任何消息了！$B$B你能帮我去看看吗？你连洛根都能杀死，我想你一定能胜任的。$B$B我会给你一种特殊的香料。把它洒在我的火盆里，然后深深吸入它的香气，你的灵魂就会浮到空中，看到因度雷村的情况。$B$B当你的灵魂在天空翱翔的时候，我就能透过你的眼睛看到一切。', '通过灵魂视界观察因度雷村，然后向莫亚基港口的秘法师图阿鲁汇报情况。', '鬼魂与语无伦次的疯狂?这不可能!$B$B我们一定要找到更进一步的引导。', '你在想什么?', '通过灵魂视界观察因度雷村的情况。', '去龙骨荒野找莫亚基港口的秘法师图阿鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12029, '净化天灾巨魔', '<嗝儿>……必须得在这些巨魔又开始起来走动前采取行动。$B$B爸爸经常跟我说，比起不得不干掉一个巨魔来说更糟的只有一件事，就是必须得杀死一个巨魔两次。$B$B呃，<嗝儿>……说起天灾，在我们想办法削减那些巨魔的数量之前，显然是没法进入北边那座巨魔城堡的。$B$B不如你带上一些我的酒，把这些巨魔在复活前通通净化掉？', '岩石之泉的马克希望你在达克萨隆用他的烈酒净化20个饥饿的天灾巨魔。', '干得好!$B$B<麦客歇斯底里地笑了一阵子。>$B$B喔，拜托。真是有够好笑…<嗝>。', '完成了吗，$N?', '', '去灰熊丘陵找岩石之泉的马克·菲尔森。', '净化天灾巨魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12031, '解脱和安息', '西面的精灵圣地已经崩裂，它们的魔法能量正在这片土地上流动，所到之处皆成废墟。$B$B由于蓝龙军团正试图控制这股法力，卡鲁亚克的亡魂们现在正处于极度的危险之中。$B$B湖中溢出的能量杀死了村中的大部分人，少数幸存下来的也都疯了。$B$B$N，你必须去释放那些灵魂，让他们离开。别去管那些发疯的人，他们也许会慢慢恢复理智的。', '让15名因度雷海象人安息，渔夫、秘法师或是战士都行。完成任务后向因度雷村的长者玛纳洛复命。', '这并不是什么讨喜的任务，但这是必要而仁慈的。$B$B现在，你注定要替卡鲁亚克完成另外一件事。', '<长者马纳洛亚的视线穿透你，感觉到你还没完成他的任务。>', '', '去龙骨荒野找因度雷村的长者玛纳洛。', '让因度雷的灵魂安息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12032, '海洋女神', '我们必须去请求水之女神奥卡诺娅的指引；只有她知道卡鲁亚克的命运会怎样。而只有深海珍珠才能把她从黑暗的虚空中召唤出来。$B$B西南方的海岸上有一座被称为海洋之巅的山峰，那颗珍珠就在山顶的祭坛上。$B$B去祭坛上祈祷吧，奥卡诺娅一定会听到你的召唤。你一定要按照她的吩咐行事，以免激怒她，给所有海象人召来灾难。$B$B如果你成功了，就去向秘法师复命吧。', '与深海珍珠进行沟通，按照海之女神奥卡诺娅的指示行动。$B$B通过考验后，回到龙骨荒野的莫亚基港口，向秘法师图阿鲁复命。', '你和奥卡诺娅说过话了?!$B$B若是她的意旨让我族和你的同胞并肩作战，那么我们就依她所愿。无论幸或不幸，长者科纳尼会接受我们的宿命。$B$B我的族人相信，所有的灵魂都是存在世上魔法力量的其中之一，所以我们必须对抗企图控制魔法的蓝龙大军，否则我们即将万劫不复!$B$B我从不认为一个$r会成为卡鲁亚克的勇士，但你证明我错了。代表我的族人，我向你献上感激，$N。$B$B愿诸神向你微笑并守护你的安危。', '$N，你回来了!', '服从奥卡诺娅的意志。', '去龙骨荒野找莫亚基港口的秘法师图阿鲁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12033, '萨鲁法尔的信', '<托弗斯一边与你握手，一边悄悄塞给你一只信封。>$B$B<托弗斯压低了声音对你说道。>$B$B假装什么事也没发生，$N。$B$B能在这里找到你真好，士兵！毫无疑问，地狱咆哮大人将最优秀的士兵派给了阿格玛大人！$B$B<托弗斯继续压低声音说道。>$B$B读了这封信之后就在我旁边的火盆上把它烧掉。', '阅读萨鲁法尔给你的信，然后摧毁它。$B$B做完这件事情之后与信使托弗斯谈一谈。', '<托伏斯点点头。>$B$B都明白了?那么我将回去向大人回报，你已经接受了。', '我们将会粉碎天灾军!', '阅读并摧毁萨鲁法尔的信', '去龙骨荒野找阿格玛之锤的信使托弗斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12035, '重新装配', '好，我明白了！重新组装的活儿有点复杂，但还有什么事能难倒像你这么聪明的$c呢。$B$B带上我的工具，去打倒一些收割采集者。等它们停止运转以后，使用工具把所有的红色线路接到蓝色接口里，这样它们就会进入自动防卫模式。快去，$N。再拖延下去的话，就没有活人需要我们去拯救了。', '致远郡的耶雷米亚·霍宁要你打倒5个收割采集者，并使用耶雷米亚的工具重新组装它们。', '做得漂亮!我总算又觉得自己派上用场了…这可意义不凡。', '你完成了吗，$N?', '', '去北风苔原找致远郡农场的耶雷米亚·霍宁。', '重新组装收割采集者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12038, '净化天灾巨魔', '你在等什么呢，$c？那些天灾巨魔是不会自己净化自己的！$B$B你知道什么叫反复练习吗？带上一些烈酒，从远处把它扔到那些家伙身上……<嗝儿>。然后你要做的就是坐下，看他们被净化。', '岩石之泉的马克希望你在达克萨隆用他的烈酒净化30个饥饿的天灾巨魔。', '干得好!$B$B<麦客歇斯底里地笑了好一阵子。>$B$B哇哈哈，现在来吧。真的很好玩…嘻嘻。', '你对天灾军降下天火了吗，$N?', '', '去灰熊丘陵找岩石之泉的马克·菲尔森。', '净化天灾巨魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12039, '尤格萨伦的黑血', '天灾之门安加萨……我曾无数次看见那道金属巨门的表面如同有生命一般跳动、起伏！五十多年来，我从未见过金属会这样“呼吸”。$B$B恐怕只有海象人略略了解其中的秘密，他们将其称为“尤格萨伦的黑血”，还让我对其敬而远之。$B$B冰雾村外面有一处蛛魔的虫孔，纳尔苏深渊。我听说这个虫孔里面有很多这种奇特的金属矿石，如果你顺路的话，能不能帮我取些矿石的样本回来？', '阿格玛之锤的伯鲁斯·折铁要求你收集10份尤格萨伦黑血样本。', '这么轻…几乎没有什么重量!我要开始分析这种金属，看看能不能用它来制造点什么!实验!要尽快开始实验!$B$B我会和你保持联络，$N。要是我有什么成果，我一定第一个通知你。', '没有冒险生命怎么会有趣?', '', '去龙骨荒野找阿格玛之锤的伯鲁斯·折铁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12040, '阿尔萨斯的死敌', '我们已经深陷内战的漩涡，无法自拔。在地下，我族中仅存的生者正在挣扎着避免逐渐迫近的灭绝厄运。巫妖王不惜一切代价想要彻底统治伟大的艾卓-尼拉布王国，所有拒绝侍奉巫妖王的人都将被天灾军团消灭。$B$B阿尔萨斯是我族与你们共同的敌人……$B$B帮助我们……帮助我们净化这里，净化阿努巴尔蛛魔的玷污！让阿努巴拉克听到它们死亡时的凄惨哀嚎吧！', '纳尔苏深渊的拆解者基里克斯要求你杀死6只阿努巴尔蛛魔领主。', '他们还有几千个，从诺森德的每个暗处裂缝蜂拥而出。孤身一人，你毫无胜机，但合作的话…或许…', '阿兹欧帝国将会再次复兴!', '', '去龙骨荒野找纳尔苏深渊的拆解者基里克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12041, '失落的帝国', '你已经证明自己在这灭世的险境中愿意协助艾卓帝国的意愿，因此，我们艾卓帝国也愿意协助部落。$B$B将这张卷轴交给你们的领袖，卷轴上面详细记录着那些侵略冰雾村的蛛魔的优势与弱点。把它视为我们所表达出的诚意与善意吧，我们的确愿意帮助你们。如果你能利用这些知识击垮阿努巴尔蛛魔，我们所有人都将因此受益。$B$B再见了，$r。', '将基里克斯的作战计划带到东边的阿格玛之锤去，交给阿格玛大王。', '<霸主阿格玛研究着文件。>$B$B这是我想的东西吗?有了这些文件上的资料，我们将可以粉碎阿努巴的攻击!$B$B干得好，$N，能把这份文件带到我手上。或许你有机会亲身参与安格拉萨的最终战役!为了部落!', '你拿的是什么?', '', '去龙骨荒野找阿格玛之锤的阿格玛大王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12043, '诺兹拉斯的防御', '你，$c！南边那些亡灵整天对我们骚扰不休，我们的工作受到了很大的影响。去把它们都干掉，行不行？', '在迦拉克隆之墓附近的挖掘站内杀死12个废土挖掘者和1个废土工头。完成任务之后向诺兹拉斯哨站的纳尔弗复命。', '噢!对，不死生物。这是你的铜板，滚远点。', '呃?你是谁?你想干嘛?', '', '去龙骨荒野找诺兹拉斯哨站的纳尔弗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12044, '囤积矿石', '你好你好！天灾军团正在南边那几处上古巨龙的坟墓里挖来挖去。我原本不是很关心它们在那里做些什么，不过后来，它们挖出了许多合金矿石，我对此绝对不能坐视不管。$b$b给我搞一些那种矿石回来，趁部落大张旗鼓地扩充军备时狠狠赚他一票！', '在迦拉克隆之墓附近的挖掘站内收集8堆合金矿石，把它们交给诺兹拉斯哨站的辛克。', '哈!这可不少哇!你的背还撑得住吧?', '你拿到矿石了吗?我的搬运工很快就会回来 - 我们必须要在战斗持续进行时把这批货送出去!', '', '去龙骨荒野找诺兹拉斯哨站的辛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12045, '刨冰', '我似乎从来没有见过你……你是新来水晶裂痕这边的吗？初次见面，请多关照。我这里总是需要别人多关照的。$b$b你看，我现在得完成这项发明，你帮我收集材料怎么样，造好之后直接卖给那些指挥官啊什么的，我们就能发笔大财啦！$b$b当然，主要的材料我基本上都已经准备齐全了，就是武器部分还没搞定而已。纳尔弗说北边那些元素生物身上的冰片非常合适用来制作破片炸弹，给我弄点来，怎么样？', '在北边的冰元素身上收集4块碎冰簇，把它们交给诺兹拉斯哨站的希弗里克斯。', '太好了!比我想得更锐利。我要把它们埋进雪里，等到炸弹做好。$B$B让我们来瞧瞧… 下一个是…', '你拿到那些碎片了吗?我几乎要完成主要冷冻零件了。', '', '去龙骨荒野找诺兹拉斯哨站的希弗里克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12046, '柔软的包装', '看来我得另选材料来制造破片炸弹的外壳了。当前我手里的所有材料都太过坚硬，这会导致里面包裹的破片在爆炸时不能四散溅射伤人。$b$b其实最合适的材料应该是比较薄的动物皮。西边那些掘洞冰虫就不错，或者也可以试试那些整天啃龙骨头的秃鹫。总之，无论是哪种皮，都搞回来一些吧。', '从诺兹拉斯哨站附近的掘洞冰虫或龙骨秃鹫身上收集12张薄兽皮，把它们交给希弗里克斯。', '很好…很好…这些就够用了。榴炮弹几乎要完成了。$B$B等等…我的寒冰裂片怎么了?纳孚告诉我说这些元素身上的裂片都附有魔法，可是它们就跟挂在他下巴上的碎冰一样融化了!', '狩猎状况如何?拿到我要的皮革了吗?', '', '去龙骨荒野找诺兹拉斯哨站的希弗里克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12047, '不会融化的东西', '不行不行不行！这些冰块完全不行！它们在爆炸之前就全融化成水了。见鬼，这是我最后一次上纳尔弗的当了。这意味着我们要完全另找一种材料来制作破片。$b$b嗯……啊……我知道了！我真是个天才！骨头的碎片就可以呀！$b$b这周围到处都是冰虫啃过的骨头，尺寸和形状都不错。你快去看看，给我找些骨头碎片回来。', '在诺兹拉斯哨站东边的巨龙骸骨堆里收集12块破碎的骨片。', '太棒了!这大概会是我的新炸弹所需要测试的最后一样东西了。给我一点时间，我马上试试看!', '你找到裂块了没?', '', '去龙骨荒野找诺兹拉斯哨站的希弗里克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12048, '天灾的装备', '这该死的天灾矿石，我完全想不出来该怎么搞。你看，它根本不熔化！而且，我费尽了力气，也没法让这些金属的外形改变一丁点！$B$B看来，我必须搞一些铸造好的天灾军团武器装备，好好分析研究一下，才能弄清楚这些东西到底是怎么造出来的。$B$B冰雾村里面现在盘踞着大量披盔带甲的蛛魔，它们身上的盔甲就是不错的样品，去帮我弄一些来！只要你肯出手帮忙，我没准可以从这些矿石里捣鼓出一些名堂来。$B$B冰雾村就在西边，快去吧。', '阿格玛之锤的伯鲁斯·折铁要求你给他带回8套天灾军备。', '它们的情况真不错，$N。我要立刻开始工作了。如果有任何进展的话，我一定会让你第一个知道!', '<伯鲁斯把他的工具丢到地上。>$B$B这根本没用!', '', '去龙骨荒野找阿格玛之锤的伯鲁斯·折铁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12049, '难以下咽', '部队显然需要超大量的食物补给才能满足士兵们的胃。$B$B在这种常规食材极端稀匮乏的环境下，我不得不跟你分享一个机密，一般情况像你这种胆小的$r食客绝对不可能知道的机密。你不知道吧，那些冰虫的肉其实味道很棒，像鸡肉。$b$b你去东边引一只巨大的冰虫出来，显然你不可能采取传统方式干掉它，但只要使用这个小工具，趁它张大嘴的时候直接扔进它的喉咙里就可以了。你能背多少肉，就带多少回来。', '在诺兹拉斯哨站东面与巨大的冰虫作战，直到它张开嘴，然后将高能炸药扔进它的嘴里。爆炸之后，收集6块烧焦的冰虫肉，把它们交给辛克。', '哈哈!有一片肉甚至飞到我这了!做得好!', '都拿到了吗?我闻得出来。', '', '去龙骨荒野找诺兹拉斯哨站的辛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12050, '抢木材', '接下来，我们需要囤积一些木材，你看，联盟部队正在附近修建好几座哨塔，木材很是稀缺。不过，南边的树都太细了，只有北边那些被鹰身人占据了的树，才能制成符合哨塔结构要求的横梁或立柱。$b$b拿上这个，等你进入有鹰身人筑巢的森林之后，就用这个控制器操纵我的伐木机开始工作吧。采集的木材越多越好。如果那些鹰身人胆敢对你砍倒它们的窝有什么不满的话，就把它们也砍了好了。$b$b尽快开工吧！', '转至北边的鹰身人巢穴，使用辛克的伐木机控制器召唤出一只伐木机器人。从该区域的树上收集50捆木材，然后把它们交给诺兹拉斯哨站的辛克。$B$B如果你弄丢了辛克的伐木机控制器，就去找诺兹拉斯哨站的辛克再要一个。', '如果一棵树在森林中倒下，而你却无法透过锯刃听见，那它真的有发出声音吗?', '那个搬运工呢?希望蛰猛巨虫没有逮到他。他那时候可是带了不少东西。', '', '去龙骨荒野找诺兹拉斯哨站的辛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12052, '该死的鹰身人！', '$C，你看到那个鹰身人没有？就是它率领手下，对我们派去天灾之门的补给车队发动了袭击！我在冷风高地见过它！$B$B看来这些鸟人是不想活了！杀光它们！', '转至诺兹拉斯哨站西北方的山地中，杀死冷风女王和15个冷风女巫。完成任务之后向纳尔弗复命。$B$B如果你需要辛克的伐木机控制器，就去找诺兹拉斯哨站的辛克。', '这应该可以让那些丑家伙三思。拿去…拿了奖赏之后就滚开。', '我记得你。你没死，那么，那些鹰身人最好是死罗。', '', '去龙骨荒野找诺兹拉斯哨站的纳尔弗。', '', '冷风鹰身人', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12053, '部落的力量', '现在，牦牛人决定与我们并肩作战。我们必须体现出部落的团结与互助精神，为他们夺回冰雾村。$B$B冰雾村就在阿格玛之锤的西方，就在山脚下。立刻到那边去，对那里的阿努巴尔蛛魔发起攻击！你要把我们最高贵最神圣的部落旗帜插在冰雾村的土地上，并消灭一切试图亵渎它的敌人！$B$B让阿努巴尔蛛魔感受一下部落的真正力量吧！让我们的战旗成为它们死前见到的最后一样东西！', '阿格玛之锤的军士长祖托克要求你在冰雾村使用战歌军旗，并确保它免遭一切攻击。$B$B完成任务之后，将战歌军旗还给军士长祖托克。', '我们在陆地上击溃了他们!要不了多久，也要在空中击溃他们!', '真是个挑战，$N!', '保卫战歌军旗', '去龙骨荒野找阿格玛之锤的军士长祖托克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12054, '翻译日记', '沃塔肯是对的，绝不能让这个绝好的机会就这样从我们手边悄然溜走。$B$B幸亏我知道有个办法，能把这个布莱恩的日记翻译成我们可以理解的文字。$B$B红牙熊怪部族的萨满祭司聚集在我们营地西南方的心血神殿，他们平常会栽培一种被称为灵息草的药草，这种药草制成的熏香可以帮助他们寻求祖先的智慧和指引。$B$B去找到一个名叫格鲁巴德·独眼的萨满祭司，鉴于他对乌索克的虔诚，他很可能随身携带着这种草药。', '将一小株灵息草交给欧尼瓦营地的先知帕鲁纳。', '干得好，$N。我会准备好熏香，接下来我们就可以看看这位矮人王族离家这么远在做什么。', '你带了足够的草药回来了吗?', '', '去灰熊丘陵找欧尼瓦营地的先知帕鲁纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12055, '奇怪的设备', '你拣起了这个奇怪的设备，并且立刻断定它充满着魔力。但它似乎并没有任何用处。$B$B也许眠月花园东面群星之墓那里的大法师略知一二？', '将古拉莫什的奇怪设备带回群星之墓，交给大法师茉德拉的影像。', '$N，要是没搞错，你发现了关键的装置，可以让我们精确寻找出狩法猎人大军要转至的地方!', '你手上的是?', '', '去龙骨荒野的群星之墓找大法师茉德拉的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12056, '死亡名单：高阶教徒扎古斯', '我亲眼见证了他的背叛！那个混蛋领着一群阿努巴尔蛛魔偷袭了这座要塞，令我们数百名最优秀的士兵失去了生命。$B$B<高尔特愤懑地摇了摇头。>$B$B他私下竟然为天灾军团做了那么多事，可我们却从来没有抓到任何蛛丝马迹！和扎古斯一样为天灾军团效力的到底还有多少人？我们必须把他们全部找出来，并且全部清除……$B$B<高尔特在脖子上比划了一下。>$B$B名单上的第一个人是这个扎古斯，我们的斥候发现他躲藏在西边的纳尔苏深渊。找到他，杀掉他，把他的徽记带回来给我。', '杀死高阶教徒扎古斯，并将高阶教徒扎古斯的徽记带回龙骨荒野的阿格玛之锤，交给高尔特上尉。', '<苟尔特高举他的头，并瞪着他已死的双眼。>$B$B我说过我们会逮到你的…$B$B这是你的酬劳，$C，头疼的事情总算少了一桩。', '你的背包里有颗砍下来的兽人头呢，还是你只是很开心见到我?', '', '去龙骨荒野找阿格玛之锤的高尔特上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12057, '血之魔典', '这本书似乎是以特殊的材料写成，历久弥新。仔细阅读之后，你发现书页上充斥着某种奇特符号。$B$B无论这本书里究竟写的是什么，它一定都是非常重要的内容。立刻把它带回冰雾村东边的阿格玛之锤，交给高尔特上尉。', '将血之魔典交给阿格玛之锤的高尔特上尉。', '<苟尔特从你手上接过骨书。>$B$B野蛮…竟然用兽人的血肉拼成…这种语言…这本书的存在从来没被证实过。这是亡者的语言…天灾军所说的话。', '<苟尔特很惊讶。>', '', '去龙骨荒野找阿格玛之锤的高尔特上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12058, '符文中的预言', '布莱恩的日记里记载了一套解读铁矮人文字的方法。我已经把这些内容抄写在了一块钥石上，它可以帮助你弄清楚那些铁矮人的符文板上到底写了什么。$B$B此外，这本日记里还记述了布莱恩追寻矮人一族起源之谜的详情，包括他所发现的全部线索与证据。千万要留意他所提到的这些线索，这可以把我们导向他的藏身之处。$B$B好了，现在你立刻回到索尔莫丹，到那里的每一块巨型符文板前面，使用这块钥石解读上面的内容。我们绝不能让联盟先找到他。', '欧尼瓦营地的先知帕鲁纳要求你解读出三块符文板上的文字。', '<当你回想着石板上的翻译时，贤者帕努纳聆听着。>$B$B这么说，布莱恩觉得他找到了一座新的泰坦之城?$B$B“奥杜亚座落于风暴之中。”$B$B我会请求酋长派遣远侦斥候到风暴峭壁去。我的族人很清楚这些地方，很有机会能查出这个难以捉摸的矮人下落。', '你找出铎尔莫丹的秘密了没?', '', '去灰熊丘陵找欧尼瓦营地的先知帕鲁纳。', '解读第一个预言', '解读第二个预言', '解读第三个预言', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12059, '奇怪的设备', '你拣起了这个奇怪的设备，并且立刻断定它充满着魔力。但它似乎并没有任何用处。$B$B也许眠月花园东北面阿格玛之锤那里的大法师略知一二？', '将古拉莫什的奇怪设备带回阿格玛之锤，交给大法师艾萨斯·夺日者的影像。', '$N，要是没搞错，你发现了关键的装置，可以让我们精确寻找出狩法猎人大军要转至的地方!', '你手上的是?', '', '去龙骨荒野的阿格玛之锤找大法师艾萨斯·夺日者的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12060, '投影和计划', '这是一件传送装置。如果要我说的话，它多半通往漂浮在西面眠月花园上空的湍流之针平台。$B$B我打算派你去用它调查一下那里。这种设备似乎是双向的，这样你就不用从平台上跳下来了。$B$B我猜想等你传送到湍流之针后，会看到一些与之关联的设备。$B$B我觉得你应该能在眠月花园内的任何地方使用这件传送装置。', '靠近并观察漂浮在眠月花园上空的湍流之针上的物品。$B$B完成任务后返回群星之墓，向大法师茉德拉的影像汇报你的发现。', '照你的描述…那是奥舆全览图投影!$B$B<大法师焦虑的神情马上就被他冷酷的外表给掩饰住了。>$B$B奥舆全览图是世界上所有魔力地脉交会点的地图。蓝龙军团利用它寻找并摧毁地脉“锚点”，以便把魔力能量送回魔枢。$B$B问题是，破坏的路径应该是通往西方，但是为何是往东方呢?', '这么快就回来了?', '', '去龙骨荒野的群星之墓找大法师茉德拉的影像。', '检查湍流之针上的物体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12061, '投影和计划', '这是一件传送装置。如果要我说的话，它多半通往漂浮在西南方眠月花园上空的湍流之针平台。$B$B$N，我打算派你去用它调查一下那里。这种设备似乎是双向的，这样你就不用从平台上跳下来了。$B$B我猜想等你传送到湍流之针后，会看到一些与之关联的设备。$B$B我觉得你应该能在眠月花园内的任何地方使用这件传送装置。', '靠近并观察漂浮在眠月花园上空的湍流之针上的物品。$B$B完成任务后返回阿格玛之锤，向大法师艾萨斯·夺日者的影像汇报你的发现。', '照你的描述…那是奥舆全览图投影!$B$B<大法师焦虑的神情马上就被他冷酷的外表给掩饰住了。>$B$B奥舆全览图是世界上所有魔力地脉交会点的地图。蓝龙军团利用它寻找并摧毁地脉“锚点”，以便把魔力能量送回魔枢。$B$B问题是，破坏的路径应该是通往西方，但是为何是往东方呢?', '这么快就回来了?', '', '去龙骨荒野的阿格玛之锤找大法师艾萨斯·夺日者的影像。', '检查湍流之针上的物体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12064, '阿努巴尔的束缚', '他们用魔法锁链构成的结界将我父亲囚禁在冰雾村的正中央。根据我所了解到的情报，这个囚笼被三名最强大的阿努巴尔法师控制着，他们每人拿着钥匙的一部分。$B$B请你在村里找到这三个大法师，杀死他们，并夺取他们手中的钥匙碎片。只要集齐了三块钥匙碎片，我的父亲就有救了。只要他能获得自由……$B$B复仇的时刻就将到来。', '冰雾村的班索克·冰雾要求你将安诺科拉的钥匙碎片、提瓦克斯的钥匙碎片和西诺克的钥匙碎片交给他。', '是的，这就行了。$B$B<班索克精熟的操作这些钥匙碎片。>$B$B拿去，$C，有了这把钥匙，我的父亲就能从阿努巴监狱中释放出来了。', '把那些钥匙碎片拿给我!', '', '去龙骨荒野找冰雾村的班索克·冰雾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12065, '海岸上的魔法焦点', '法师猎手部队正在眠月花园南面的灿烂海岸忙碌着。我想你应该可以在沙滩上看到被重兵防守着的魔法焦点和领头的指挥官。$B$B很显然，指挥官肯定会随身带着些什么控制设备。夺取控制器，然后在魔法焦点上使用它。$B$B如果足够幸运的话，我们可以获取更多有关他们真正目的的信息。', '夺取魔网能量焦点控制指环，用它从灿烂海岸的魔网能量线焦点中获取信息。$B$B然后返回群星之墓，向大法师茉德拉的影像复命。', '这个资讯在你身上沾染了非常奇怪的魔法气息。$B$B所以，我们现在不仅知道他们正在重新导向从月眠花园流出的能量，我们还知道这股力量在某方面还被刻意地改变了。他们到底想对魔法做什么?$B$B我不喜欢它被导向的地方，$N，一点也不!', '你从海滩上带回来什么消息吗，$C?', '', '去龙骨荒野的群星之墓找大法师茉德拉的影像。', '接收魔网能量线焦点信息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12066, '海岸上的魔法焦点', '法师猎手部队正在眠月花园南面的灿烂海岸忙碌着。我想你应该可以在沙滩上看到被重兵防守着的魔法焦点和领头的指挥官。$B$B很显然，指挥官肯定会随身带着些什么控制设备。夺取控制器，然后在魔法焦点上使用它。$B$B我们可以毫不费劲地获取更多有关他们真正目的的信息。', '夺取魔网能量焦点控制指环，用它从灿烂海岸的魔网能量线焦点中获取信息。$B$B然后返回阿格玛之锤，向大法师艾萨斯·夺日者的影像复命。', '这个资讯在你身上沾染了非常奇怪的魔法气息。$B$B所以，我们现在不仅知道他们正在重新导向从月眠花园流出的能量，我们还知道这股力量在某方面还被刻意地改变了。他们到底想对魔法做什么?$B$B我不喜欢它被导向的地方，$N。', '你从海滩上带回来什么消息吗，$C?', '', '去龙骨荒野的阿格玛之锤找大法师艾萨斯·夺日者的影像。', '接收魔网能量线焦点信息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12067, '一封家书', '你发现在她的长袍里藏着一封信。信上写着：“父亲，$B$B我为我的不辞而别感到歉疚。如果您读到了这封信，那这就意味着我已经死了。$B$B玛里苟斯的军队逼迫我为他们工作，并威胁说如果我不照做的话，他们会杀死我的全家。我感到很羞愧。$B$B如果您要与他们战斗的话，不用为我担心。我愚弄了他们，并暗中在他们内部进行着破坏活动。$B$B我爱你，爸爸！$B$B艾米”$B$B你应该把这封信交给指挥官塞雅·蓝钢！', '将艾米·马林的信交给群星之墓的指挥官塞雅·蓝钢。', '不会吧…所以我们把你送去那里杀了她，是吗?$B$B<指挥官摇了摇她的头，叹了一口气。>$B$B我很抱歉。我会确定这封信立刻送到他父亲，暴风城的大法师马林手上。别担心，你不会被连累的…这不是你的错。$B$B试着忘记这件事。你无法事先得知真相，$N。', '有封给我的信?$B$B<指挥官对你的脸端详片刻。>$B$B我想不是…必然是坏消息。', '', '去龙骨荒野找罗萨洛尔森林的指挥官塞雅·蓝钢。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12068, '灰尘之声', '<达库鲁把预言者之眼放在额前，然后把古树精华宝石放在胸口。>$B$B我们很接近了，朋友，非常接近了……$B$B达卡莱石板是我们要找的最后一件东西。没有人知道它有多古老，也没人知道石板上面写着什么，但有了预言者之眼和古树精华宝石，达库鲁就能读懂它们。你可以在东边达基尔金的墓穴深处找到它们。$B$B等你拿到石板后，从先知和保卫者身上收集一些神圣魔精，这样就可以召唤我了。为这样的目标牺牲，他们会感到自豪的。', '达库鲁希望你在达基尔金废墟中找到达卡莱石板，并从达卡莱先知和达卡莱保卫者身上收集5份神圣魔精。然后在废墟中达库鲁的火盆上使用达库鲁的药剂，召唤出他的影像。', '我们做到了，$N!$B$B我们有了净化仪式所需的每一样东西。', '看到你真好，$N。$B$B找到石板了吗?', '', '去灰熊丘陵的达基尔金废墟找达库鲁的影像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12069, '大酋长归来', '<班索克将钥匙交给你。>$B$B你必须尽快行动，$N。拿着这把钥匙，把我的父亲从阿努巴尔的囚笼中释放出来。一旦他获得了自由，就帮助他消灭阿努巴尔的头目——虫王阿努布耶坎。杀死它之后，把它甲壳上的碎片拿去交给阿格玛。让阿格玛之锤的部落成员们见识一下大酋长的力量吧！', '使用阿努巴尔牢笼钥匙放出冰雾部族的大酋长，并协助他击败虫王阿努布耶坎。$B$B取回一片阿努布耶坎的外壳碎片，把它带回龙骨荒野的阿格玛之锤，交给阿格玛大王。', '你是个勇敢的$C，$N。你解救大酋长等于是替部落立了大功。', '那是什么，$N?我很忙啊。', '', '去龙骨荒野找阿格玛之锤的阿格玛大王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12070, '鼓舞士气', '那些钢铁之子利用他们的符文魔法束缚住了我们许多的兄弟，甚至奴役他们来解除索尔莫丹之围。我们真的非常希望不必去和那些可怜的兄弟们作战，但却别无选择。$B$B现在，我手下的巨人们就快要抵挡不住了，必须解决这个问题。$B$B这里有一块注入了祝福之力的土灵碎片，其中的魔法将会大大提振我军的战力与士气。带着它到北边巨石丘陵的前线去，使用它固化我族的身体，强化我族的信心。$B$B如果那里有任何铁矮人胆敢阻拦我们的军团，就赐予他死亡。', '使用大地碎片鼓舞巨石丘陵的灰熊丘陵巨人，杀死所有与你交战的铁矮人，然后回到俯瞰索尔莫丹的丘陵地带，向库伦复命。', '你给了我们的盟友继续作战的力量，我为此感谢你。但尽管如此，我们依旧要开始展开计画，在我们被打倒之前结束这场战争。', '你将我的祝福传递给巨人们了吗?', '', '去灰熊丘陵找巨石丘陵的库伦。', '鼓舞灰熊丘陵巨人', '杀死铁符文复仇者', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12072, '该死的荒芜兽！', '我想你应该已经见过冰雾村里那些蛛魔们制造出的阿努巴尔荒芜兽大军了。阿努巴尔蛛魔计划将这些怪物送去天灾之门，消灭我们派驻在那里的守军。绝不能让这种事情发生！$B$B带上这把信号枪，立刻到西边的冰雾村去。在那边，你可以用它直接调用我的双足飞龙，并乘坐它飞上天空，消灭一切你能看见的荒芜兽！$B$B消灭了敌人的空中力量之后，回来找我领取报酬！', '在冰雾村内使用瓦诺克的信号枪调用一只库卡隆作战双足飞龙，骑坐它杀死25只阿努巴尔荒芜兽！$B$B完成任务后返回阿格玛之锤向瓦诺克·风怒复命。', '<沃尔诺克敬礼。>$B$B他们被我们的空袭打的屁滚尿流!也许不久你就会被征召到安格拉萨去了，大英雄!', '请注意，战斗坐骑被训练只在冰雾村进行战斗。你要是把它飞到别处，战斗坐骑会把你摔下来的。', '', '去龙骨荒野找阿格玛之锤的瓦诺克·风怒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12073, '“钢铁之子”', '在灰熊丘陵，我们要面对的敌人不仅仅是联盟。尽管索尔莫丹几乎已经快被那些石巨人给踏平了，可是铁矮人当前还是牢固地掌握着东海岸一带。$B$B在格斗中，一位富有技巧与经验的战士都知道利用敌人身上的弱点，那么在战略角度上，我们如果忽视了铁矮人在索尔莫丹那边暴露出来的弱点，就显得太愚蠢啦。不要心怀任何仁慈，杀光所有胆敢反抗的家伙。$B$B那些所谓的“钢铁之子”要学会对部落心怀恐惧与敬畏。', '杀死10名守卫索尔莫丹的铁矮人，然后向欧尼瓦营地的斥候沃塔肯复命。', '<斥候沃塔克微笑着。>$B$B当前铎尔莫丹面临崩溃的边缘了吧?$B$B很好。我们很快就能将注意转向丹亚戈了。', '你把我交付的铁矮人赶走了吗?', '', '去灰熊丘陵找欧尼瓦营地的斥候沃塔肯。', '消灭铁矮人防御者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12075, '采集样本', '这里够冷的，不是吗，$r？$B$B科查尔至今都不想与我见面。看来他只顾着想一些要紧事了——比如说，从地下突然冒出来袭击他们的那些冰虫。或许你能帮我说服科查尔，让他相信我是一个好人。$b$b话说，我在北边的洞穴口上看见有一个巨人被一群冰虫吃掉了……那些虫子能如此轻易地杀死那样一个庞然大物，这真让我感到惊诧。你去给我到那个巨人的尸体上采集一些伤口附近的样本回来，我要好好研究一下。', '转至佐特的北面，在水晶裂痕下面的洞穴入口处的冰巨人尸体上收集一份岩石躯体样本。完成收集工作之后把它交给峡谷中央的佐特。', '这太棒了，谢谢你，$C。', '你带着我的样本回来了吗?很高兴寒冷的天候没有夺走你的性命。', '', '去龙骨荒野找水晶裂痕的佐特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12076, '恶心的生意', '我一眼就看出，这些唾液样本带有明显的腐蚀性特征。那么，我们接下来就可以很自然地推论出，这些大虫子正是利用这种腐蚀性的唾液在地下打洞钻来钻去，同时在面对冰巨人时将其作为武器。$b$b带上这把刮刀，去挑逗那些冰虫，如果它们对你吐出唾液的话，就把它从你身上刮下来，收集起来带给我。记住，量一定要足够，我打算以这些唾液为基础，制造一种高级的药剂。', '对自己使用佐特的刮刀，并收集2瓶腐蚀性的唾液。将你收集到的东西交给水晶裂痕内的佐特。', '还很新鲜。等我一下，我马上就把它跟准备好的药剂剩馀部份混合在一起$B$B', '你肩膀上还有口水啦，$r。小心它会把你的护甲烧穿。', '', '去龙骨荒野找水晶裂痕的佐特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12077, '主动示好', '这种药剂可以保护你免受它们唾液的威胁。帮我把它交给科查尔，行吗？告诉他，我这里还有足够的储备，只要他能“报答”我，要多少都行。', '将佐特准备好的药剂交给坚不可摧的科查尔。', '我就直说了小家伙-我不相信这个混合物，而且我也不会使用它。留着吧…如果你比我更信任那个绿矮子，也许你用的着它。', '我猜那个小矮子想要我替他作战。这是我吃惊的表情。', '', '去龙骨荒野的水晶裂痕找坚不可摧的科查尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12078, '抓虫子', '随他便好了。如果巨人不能成为盟友，那我们就只好去利用那些虫子了。这一带的冰虫肯定都是由地洞深处的母虫繁殖出来的。带上这只盒子，去抓3只小虫来给我。$b$b既然外交手段失败，改用奴役或许也不错。', '进入水晶裂痕下方的洞穴，使用盒子抓捕3只冷心冰虫幼体。记得在冷心冰虫幼体钻进盒子之后拿起盒子！$B$B将你抓获的冷心冰虫幼体带回水晶裂痕，交给佐特。', '这些很适合。也许当我把它们养成成虫之后，我会带它们回来，私底下介绍它们和巨人认识。$B$B一堆没用的臭石头，如果你问我的意见的话。', '你回来了!你捉到那些猛兽了吗?我得离开这里…我很确定寇恰几分钟之前试着要把我踩扁。', '', '去龙骨荒野找水晶裂痕的佐特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12079, '践踏大地', '你好，小家伙。虽然我不知道是哪种疯狂的力量将你带来这里的，但我仍想对你表达欢迎之意。$b$b这些冰虫……它们已经喜欢上以我兄弟的肉为食了。恐怕，在这凄惨的战争时节，我的任何一位同伴都不会友善地面对你，但如果你真是来帮助我们对付那些虫子的话，我可以给你一些忠告。$b$b在将脚下那处洞穴夺回来之前，我们必须先把峡谷里的冰虫喂食者清理干净。加入我们的战斗吧，$R！', '坚不可摧的科查尔要求你进入水晶裂痕北部末端的洞穴，杀死8条冷心冰虫喂食者。', '这是个令人满意的屠杀成果。', '战斗还在继续中，如果没带好消息来就不要打扰我，小家伙。', '', '去龙骨荒野的水晶裂痕找坚不可摧的科查尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12080, '冰虫之母', '这个冰虫族群的母虫躲在下面的洞穴里。我们称它为钻雪虫，这是一位来自瘟疫之地的冒险者给它所起的名字。我曾在它们最初发动的几次进攻中见过它的身影，它确实非常庞大，甚至令我这寒冰造就的躯体也颤抖不已。除非彻底除掉它，否则这座洞穴永远都不会属于我们。$b$b召集你的伙伴，去干掉它。', '进入水晶裂痕底部的洞穴并杀死钻雪虫。如果你手中还有佐特的防护药剂，记得使用它来避免受到冰虫酸液的伤害。$B$B完成任务之后回去向坚不可摧的科查尔复命。', '所以，她死了。她早该死了。这证实了你的情操远比那些矮个子高贵许多。$B$B通过北方的峡谷，你就能看到晶歌森林。$r，那是个被诅咒的危险地方。那是你接下来要去的地方，请小心行动。$B$B小朋友，请收下这个作为你努力的回报，带着我的祝福，离开这片冲突之地。', '我希望你带来的是好消息，小家伙。', '', '去龙骨荒野的水晶裂痕找坚不可摧的科查尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12083, '森林上空', '我相信一定存在更多的魔法焦点，每一处魔法焦点都依次改变着魔网能量的流向——尽管我们仍然不知道他们到底会把这些能量用到哪里去。$B$B我猜想你可以在东南面的罗萨洛尔森林上空找到另一个。当然，你需要再次找到控制它的家伙，拿到他们携带的控制设备，我相信每一个魔法焦点都有自己的控制设备。$B$B小心，$N，那片森林非常危险。', '夺取魔网能量焦点控制护符，用它从罗萨洛尔森林的的魔网能量线焦点中获取信息。$B$B然后返回群星之墓，向大法师茉德拉的影像复命。', '他们用节点来强化力量?不合理啊;狩法猎人没有那么强!$B$B这一定表示他们只有在导引魔网能量的终点处使用魔法。$B$B若是要揭露同时阻止他们，我们会需要更多的资讯!', '你在树林里有何发现？', '', '去龙骨荒野的群星之墓找大法师茉德拉的影像。', '接收魔网能量线焦点信息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12084, '森林上空', '我相信一定存在更多的魔法焦点，每一处魔法焦点都依次改变着魔网能量的流向——尽管我们仍然不知道他们到底会把这些能量用到哪里去。$B$B我猜想你可以在南面的罗萨洛尔森林上空找到另一个。当然，你需要再次找到控制它的家伙，拿到他们携带的控制设备，我相信每一个魔法焦点都有自己的控制设备。$B$B快点，$c。我感觉时间不多了。', '夺取魔网能量焦点控制护符，用它从罗萨洛尔森林的的魔网能量线焦点中获取信息。$B$B然后返回阿格玛之锤，向大法师艾萨斯·夺日者的影像复命。', '他们用节点来强化力量?一点也不合理;狩法猎人没有那么强!$B$B这一定表示他们只有在导引魔网能量的终点处使用魔法。$B$B若是要研究出他们的对策，我们会需要更多的资讯!', '那些林地上方有什么发现吗?', '', '去龙骨荒野的阿格玛之锤找大法师艾萨斯·夺日者的影像。', '接收魔网能量线焦点信息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12085, '一封家书', '你发现在他的长袍里藏着一封信。信上写着：“迪诺，$B$B我为我的不辞而别感到歉疚。如果您读到了这封信，那这就意味着我已经死了。$B$B玛里苟斯的军队逼迫我为他们工作，并威胁说如果我不照做的话，他们会杀死我的全家。塔辛尼不想让这种事情发生！$B$B不用为我担心，保护好你的孩子们就行了。我愚弄了这些家伙，在他们的内部进行着破坏活动。$B$B我爱你，姐姐！$B$B塔辛尼”$B$B你应该把这封信交给阿格玛大王！', '将塔辛尼中尉的信交给阿格玛之锤的阿格玛大王。', '啊哈哈哈…呵呵，好感人啊。$B$B<霸主从高傲的笑声诉说了一切。>$B$B我能说什么?叛徒!很久以前我就认识了迪诺，她至少是个有荣誉心的巨魔!$B$B我会记得让她知道她哥哥发生了什么事，我甚至忘记要告诉她，是你，杀了她哥哥。$B$B<阿格玛用打量的目光瞪着你。>$B$B但是，你现在是我的，$C!', '这是什么?你以为你可以寄信吗?$B$B所有的信都必须先经过我才行，我们之中有间谍和叛徒!$B$B<霸主迅速的打量你一番，你担心他是不是马上要格杀你。>$B$B很好，快把信交给我。但是，如果我对我读到的东西不满意，我会把你拿去喂座狼。$B$B<阿格玛狞笑着，同时，加迈克和拉科吐克转过头看着你，似乎你就是它们的下一餐。>', '', '去龙骨荒野找阿格玛之锤的阿格玛大王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12089, '通缉：魔导师凯尔多努斯', '阿格玛大王敕晓：$B$B通缉目标：魔导师凯尔多努斯$B$B罪名：通敌叛国$B$B状态：有效$B$B前阿格玛之锤的法师指挥官之一的魔导师凯尔多努斯，当前已被部落军事法庭判处死刑。即日起，任何发现他的人可以立即代执行。$B$B根据军方记录显示，凯尔多努斯最后一次被发现时，正向西南方的眠月花园逃窜并试图加入蓝龙军团。$B$B接近凯尔多努斯时请务必慎重，他是一名强大的施法者，切勿单独与之战斗。$B$B全部赏金将在阿格玛之锤的高尔特上尉处兑现。', '杀死魔导师凯尔多努斯，然后返回龙骨荒野的阿格玛之锤，向高尔特上尉复命。', '他不是第一个背叛我们的娘娘腔法师，当然，他也不会是最后一个。同时，可耻的是…他是我们最厉害的法师。他可以招出一顿让你垂涎三尺回味再三的餐桌…$B$B啐!', '你来领赏的吗?', '', '去龙骨荒野找阿格玛之锤的高尔特上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12090, '通缉：吉加托尔', '阿格玛大王敕晓：$B$B通缉目标：吉加托尔$B$B罪名：袭击部落，以及“长相过于丑陋”$B$B状态：有效$B$B猛犸人领袖吉加托尔涉嫌在龙骨荒野多次袭击部落巡逻队及基地，给部落人民生命财产带来重大损失，因此被通缉。$B$B根据军方记录显示，吉加托尔最后一次被发现时，正在阿格玛之锤东南偏东方向道路旁的林地一带活动。$B$B吉加托尔身上携带有武器，并极度危险，切勿单独与之战斗。$B$B全部赏金将在阿格玛之锤的高尔特上尉处兑现。', '杀死吉加托尔，然后返回龙骨荒野的阿格玛之锤，向高尔特上尉复命。', '你逮到那个丑八怪马脸了，嗄?我们的士兵们在这片冰冻荒原上总算少一件麻烦事要应付了。', '你来领赏的吗?', '', '去龙骨荒野找阿格玛之锤的高尔特上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12091, '通缉：恐怖之爪', '阿格玛大王敕晓：$B$B通缉目标：恐怖之爪$B$B罪名：袭击部落$B$B状态：有效$B$B恐怖之爪因涉嫌多次袭击部落往来于本地与怨毒镇之间的车队而被通缉。$B$B恐怖之爪当前在阿格玛之锤以东一处可以俯瞰到红玉巨龙圣地的地区筑有巢穴。它非常危险，接近时候务必谨慎小心，切勿单独与之战斗。$B$B全部赏金将在阿格玛之锤的高尔特上尉处兑现。', '杀死恐怖之爪，然后返回龙骨荒野的阿格玛之锤，向高尔特上尉复命。', '也该是时候有人终止那卑鄙野兽的杀戮取乐了!做的好，$N。', '你来领赏的吗?', '', '去龙骨荒野找阿格玛之锤的高尔特上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12092, '强化古树', '并不是只有$r才受到了蓝龙军团所作所为的影响，东南面罗萨洛尔森林中的古树也是受害者。$B$B其中有一些已经受到了感染——你无论如何也要避开它们——但大部分仍然还有救。不过，森林里的树人似乎没有被渗透在这片大陆上的魔力和随之而生的奥术浮龙所影响。$B$B去问树人要一些它们身上的树皮，把它交给古树。希望这样可以拯救它们。', '使用树人的树皮让3个罗萨洛尔古树恢复力量，然后向群星之墓的萨蕾德亚娜复命。', '感谢你，$r!我们损失的已经太多了。你确保了我们不会失去那些崇高的诺森德子民。$B$B我马上就动身前去和那些你拯救的古树谈谈，他们是否愿意在我们需要的时候伸出援手。', '拯救这些古树的附带价值就是，他们会考虑带着他们坚硬的躯体帮助联盟。而且，这也算做了一件好事。$B$B那么，你强化了几个古树呢，$C?', '', '去龙骨荒野找群星之墓的萨蕾德亚娜。', '强化罗萨洛尔古树', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12093, '压制符文', '即使库伦攻下了索尔莫丹，那些铁矮人仍然可以用那种该死的符文魔法对付我们的兄弟。他们的做法是这样的，首先将我的兄弟们从泥土中召唤出来，接着趁他们懵懂之际直接通过符文进行束缚，然后逼迫他们与同为岩石之子的我们作战。$B$B他们用于召唤和束缚的压制符文就矗立在东风海岸沿岸，被奴役的兄弟们也是从那里被送向北边战场去的。$B$B找到这四处压制符文，杀死每个符文法阵周围全部的织魔者，这样这四处符文法阵的工头就会被你引诱出来。干掉他们。没有了工头，符文法阵就只是废物而已了。', '泰塞斯废墟内的加弗洛克要求你通过击败工头多瓦尔、工头库尔甘、工头洛克里和工头布隆诺的方式中和全部四处压制符文。', '很好。现在我们要尽快行动，趁那些铁之子还没发现他们符文已经被解除了。', '你消除那些符文的效力了吗?', '', '去灰熊丘陵找泰塞斯废墟内的加弗洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12094, '潜在的能量', '压制符文已经全部停止运转，我想，解放那些符文巨人的机会来了。$B$B拿着这块石头，朋友。它是在我诞生时从我身上分离出来的一部分，如果向石头中正确地灌入能量，它完全可以解放那些被束缚的巨人。$B$B我要你找到三块远古巨石，其中两块位于铁铸之路和林边哨站之间——用你们的语言来解释，就是所谓魔网能量线的交汇点。另一块位于这片废墟最南端的一座岛屿上，转至每一块巨石，为这块碎片充能吧。', '分别在第一块远古巨石、第二块远古巨石和第三块远古巨石为加弗洛克碎片充能，然后向泰塞斯废墟内的加弗洛克复命。', '我可以检测到你灌注在裂片中的能量，我希望这足以打破符文魔法。', '你找到远古之石了吗?', '', '去灰熊丘陵找泰塞斯废墟内的加弗洛克。', '从第一块远古巨石吸取能量', '从第二块远古巨石吸取能量', '从第三块远古巨石吸取能量', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12096, '强化古树', '南面罗萨洛尔森林中的古树被奥术浮龙感染了……那里现在到处都是浮龙！$B$B已经被感染了的那些古树非常危险，而且对我们来说毫无用处，但大多数还有救。幸运的是，森林里的树人似乎没有受到任何不利影响。$B$B去问树人要一些它们身上的树皮，然后把树皮交给古树们。这应该能让它们恢复力量。$B$B快去吧！我还要盯着这些药剂师呢。', '使用树人的树皮让3个罗萨洛尔古树恢复力量，然后向阿格玛之锤的大地看守者格莱弗复命。', '请接受我的感谢，$C。$B$B只要我了解了这些恶心的药剂师到底要干嘛以后，我会马上赶去树林，看看我有没有办法说服这些古树加入我们。$B$B又或者，如果没辄的话，我至少会说服他们不要攻击拯救他们的人!', '如果我们能赶在繁星之眠的林精和夜向导之前拯救这些古树，也许他们会愿意和部落结盟。$B$B或者，至少，在攻击我们之前会三思而行。$B$B那么，你已经救了多少?', '', '去龙骨荒野找阿格玛之锤的大地看守者格莱弗。', '强化罗萨洛尔古树', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12097, '萨拉斯塔，北地的灾祸', '我手下的猎人不是死了，就是被那该死的龙冻得快死了，$N。你和你的伙伴——如果有的话——恐怕是这里唯一能帮上你的人啦。怎么？还是不想放弃？行啊，你准备好了的话，告诉我就行，我会帮你把那只龙给弄下来。$B$B要是你真地走好运干掉了它，就把它的冰块心脏带回阿格玛之锤，给高尔特看看。他肯定重重有赏啊，伙计。', '与猎龙营地的洛坎交谈，让他将冰霜巨龙萨拉斯塔召唤下来。$B$B杀死萨拉斯塔，并将萨拉斯塔的冰冻之心交给阿格玛之锤的高尔特上尉。', '哈!你办到了!愤怒之门的士兵都欠你一份，$N!这一定可以让几个士兵再多活个一天。', '<苟尔特很惊讶。>$B$B这么快就回来了?', '', '去龙骨荒野找阿格玛之锤的高尔特上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12099, '终获解救', '这块你充能过的岩石碎片应该足以打破那些束缚着兄弟们的符文魔法了。$B$B带上它，到东风海岸北边去寻找那些符文巨人，在他们面前释放出岩石中存储的能量，然后看看结果吧。$B$B如果确实有效的话，那些符文巨人应该会立刻恢复意识，并摆脱铁矮人的控制。如果没有用，巨人恐怕仍然会攻击你，不过他们的力量会被削弱许多。不过话说回来，如果真的无效，那时我们又该怎么办？总之，无论如何得先尝试一下，如果我们只是袖手旁观，他们就将永远被奴役在绝望之中。', '使用加弗洛克的符文碎裂之石解救4名符文巨人，然后向泰塞斯废墟内的加弗洛克复命。', '所以这是个不稳定的东西吗?我希望这不是单靠机率，但至少我们是在往正确的方向前进。要是没有你的帮忙，根本连不可能都称不上。假如你得知更多关于铁矮人的阴谋，和他们对岩石之子的计画的话，来找我们，我们将会倾听，$N。', '你成功的释放我的兄弟了吗?', '', '去灰熊丘陵找泰塞斯废墟内的加弗洛克。', '解救符文巨人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12100, '腐烂的器官', '伴随天灾军团而来还有死亡和疾病。在天灾军团肆虐之地，野生动物根本不能抵御蔓延的疾病，逐渐在腐烂中痛苦地死去。等我们察觉到事态的严重性时已经晚了。$B$B龙骨荒野的大多数动物都难逃此劫。它们被天灾军团带来的疾病所感染，体表开始溃烂，性子也变得格外暴躁。$B$B你必须转至西边的纳尔苏深渊，杀死已经被感染的野生动物。从它们的尸体上找到一个完好无损的器官，这样我们或许能研制出根治这场瘟疫的疫苗。', '龙骨荒野阿格玛之锤的索艾·鹰怒要你杀死15只被感染的野生动物，并取回一个防腐内脏。', '杀死动物对我来说很痛苦，但这是非得付出不可的努力。现在让我们进行下一个步骤:接种疫苗。', '杀死那些野兽以防病情扩散，并带给我一份抗腐内脏。', '', '去龙骨荒野找阿格玛之锤的索艾·鹰怒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12101, '好医生……', '被遗忘者指派了多名医术精湛的药剂师来到天灾之门，帮助我们抵御天灾军团。其中一位名叫辛塔尔·玛菲奥斯博士的药剂师对如何阻止天灾瘟疫散播很有研究。之前，我和他就野生动物疫苗的事情交谈过，他说配制疫苗需要一个未被感染的器官。$B$B将这个防腐内脏交给辛塔尔·玛菲奥斯博士，他会告诉你接下来该做什么的。', '将防腐内脏交给阿格玛之锤的辛塔尔·玛菲奥斯博士。', '那只痴呆的牛人真的弄到了一副抗腐脏器?该死的… 我还以为这项工作可以占据他畸形的心灵一千年呢。$B$B好吧，放在这，$g男孩:女孩;。除了你这微薄的干扰之外我还有一大堆事情要做。', '干什么?', '', '去龙骨荒野找阿格玛之锤的辛塔尔·玛菲奥斯博士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12102, '红玉丁香', '红玉巨龙圣地就在东边，真是太幸运了。那里生长着一种名叫红玉丁香的植株。我需要它做药引来配制疫苗，使那些尚未被传染的野生动物免受瘟疫的滋扰。$B$B转至东边的红玉巨龙圣地寻找这种丁香花吧。$B$B记住：在这片被诅咒的冰封之地，所有的巨龙圣地都有天灾军团在肆虐。千万要当心，我们可不想让你变成灰烬之龙的腹中餐。$B$B<辛塔尔哈哈大笑。>', '龙骨荒野阿格玛之锤的辛塔尔·玛菲奥斯博士要你采集一株红玉丁香。', '不是那么难嘛，是吧?$B$B给我一点时间准备疫苗。', '你拿到晶红紫丁香了吗?', '', '去龙骨荒野找阿格玛之锤的辛塔尔·玛菲奥斯博士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12104, '返回索艾身边', '<玛菲奥斯将一瓶黑糊糊的液体递给你。>$B$B$r，就是它了。把它带回去交给那牛头人吧，告诉他我欠他的人情就算还清了。咱们“扯平”了。$B$B你可以走了，不然我就叫杰宁斯赶你。', '将辛塔尔的疫苗交给阿格玛之锤的索艾·鹰怒。', '<梭尔把瓶子举向天空查看它的内容物。>$B$B现在只剩一件事要做。', '你拿到疫苗了吗?', '', '去龙骨荒野找阿格玛之锤的索艾·鹰怒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12105, '坠入黑暗', '这本日记是一位名叫米克哈尔的银溪镇居民所写下的。其中详细描述了一伙自称为“拜狼教”的黑暗崇拜团体进入村子以后一直至今的情况。$B$B村民们最初对这个教派的布道与说教都非常反感，但是不久之后，却有越来越多的人开始成为他们的信徒。$B$B对此感到非常不安的米克哈尔把他的女儿萨莎送离了银溪镇，而他自己则留下来试图劝说银溪镇的其它居民理智下来，放弃拜狼教的信仰。$B$B日记中的最后一条提到镇中的长老级人物会在空石矿洞讨论一些问题，具体内容日记中并没有说明。', '将米克哈尔的日记交给琥珀松木营地的杜蒙特中尉。', '我怀疑，这不只是一个单纯对我们抱有敌意的小镇。$B$B我们在穴石矿坑布有人力，我们乐于做些调查。', '你手上拿的是什么?', '', '去灰熊丘陵找琥珀松木营地的杜蒙特中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12107, '魔网能量线的终端', '你在他的法袍内发现了两件东西。$B$B一只护符，很明显这是一个魔网焦点控制设备。而另一件则是某个名叫希达苟斯的家伙发布的一组命令，看来这个希达苟斯应该是眠月花园事件的幕后主使。$B$B湿透的羊皮卷上写着，他正准备将所有的法师猎手部队转移到东面的碧蓝巨龙圣地去。$B$B也许你应该先从魔网焦点处收集一些信息，然后转至东面的碧蓝巨龙圣地，从西侧展开调查。', '使用魔网能量焦点控制饰品从因度雷湖底的魔网能量焦点处收集信息。然后往东抵达龙骨荒野中南部的碧蓝巨龙圣地，从圣地西侧展开调查。$B$B完成任务后返回群星之墓，向大法师茉德拉的影像复命。', '什么?!$B$B<你眼前的影像扭曲了一会儿，大法师试图保持镇定。>$B$B当然，我们早该想到这是他们的企图。快，不要浪费时间。$B$B要有人去警告龙眠神殿!', '$N，怎么了?你看起来很激动。$B$B慢慢来，喘口气吧。', '', '去龙骨荒野的群星之墓找大法师茉德拉的影像。', '接收魔网能量线焦点信息', '观察碧蓝巨龙圣地', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12110, '魔网能量线的终端', '你在他的法袍内发现了两件东西。$B$B一只护符，很明显这是一个魔网焦点控制设备。而另一件则是某个名叫希达苟斯的家伙发布的一组命令，看来这个希达苟斯应该是眠月花园事件的幕后主使。$B$B湿透的羊皮卷上写着，他正准备将所有的法师猎手部队转移到东面的碧蓝巨龙圣地去。$B$B也许你应该先从魔网焦点处收集一些信息，然后转至东面的碧蓝巨龙圣地，在它的西侧展开调查。', '使用魔网能量焦点控制饰品从因度雷湖底的魔网能量焦点处收集信息。然后向东走，转至龙骨荒野中南部本地的碧蓝巨龙圣地，在那里的西侧进行调查。$B$B完成调查之后，回到龙骨荒野的阿格玛之锤，向大法师艾萨斯·夺日者的影像复命。', '什么?!$B$B<你眼前的影像扭曲了一会儿，大法师试图保持镇定。>$B$B当然，我们早该想到这是他们的企图。快，不要浪费时间。$B$B要有人去警告龙眠神殿!', '怎么了，$C?你看来很激动。$B$B何事如此要紧，以至于在我和霸主面前如此邋遢?', '', '去龙骨荒野的阿格玛之锤找大法师艾萨斯·夺日者的影像。', '接收魔网能量线焦点信息', '观察碧蓝巨龙圣地', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12113, '等肉下锅', '你好啊，$c！过来坐到我的篝火旁。$B$B我很想和你分享一份热呼呼的美食，只是我也没有。我要在这里等一个合伙人，所以走不开，否则我肯定会自己去解决这个问题啦。$B$B呃，你好像很闲，而且这附近到处都是肉。不如你帮我个忙，去弄些食物怎么样？', '哈考尔营地的哈考尔希望你能帮他从暗嚎徘徊者身上收集10块多汁的座狼肉，从厚蹄食草鹿身上收集10块铲角肉排。', '杰出!$B$B没有什么比大口吃肉更棒的了。', '我的肚子已经咕噜噜的叫啦，$r。你准备猎捕一些食物给我了吗?', '', '去灰熊丘陵找哈考尔营地的哈考尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12114, '心灵的创伤', '巨魔……我恨巨魔！<哈考尔吐了一口唾沫。>$b$b我曾经被那些混蛋抓住过……他们差点就把我的脑袋给揪下来了！$b$b我的朋友都劝我把这事忘了，可我就是做不到。$b$b知道怎么样才能让我舒服点吗，$r？只有一个方法，那就是让巨魔不舒服！如果你能做到的话，我会付给你金币的。', '哈考尔营地的哈考尔要你在达基尔金废墟外面杀死10个达卡莱保卫者和10个达卡莱先知。', '谢你啊，$C。$B$B时候允许的话，我会起来四处逛逛。', '巨魔猎杀的如何呀?', '', '去灰熊丘陵找哈考尔营地的哈考尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12115, '库尔迪拉和亡者之语', '有一个最近刚刚加入我们的人或许能够解读这本书。他是一位摆脱了巫妖王控制的死亡骑士，名叫库尔迪拉\r\n·织亡者，当前暂时居住在阿格玛之锤。以前他被阿尔萨斯奴役时，曾是天灾军团的一员，因此他或许了解这种亡者的语言。$B$B将这本血之魔典交给库尔迪拉，让他帮你翻译上面的文字。', '将血之魔典交给库尔迪拉·织亡者。', '人世间只有两件事情我还有兴趣，小兵，而替你翻译天灾军团的书算不上其中任何一件。$B$B然而…也许我们可以找出对双方都有利的作法。$B$B<寇尔提拉抽出了他的武器。>$B$B这是我的符文剑，霜倚。霜倚渴求巫妖王与其手下的鲜血，但我得先刻上它的力量符文:冰霜、血魄与秽邪的符号。替我带来能量之源，我就替你翻译这本书。', '有什么事，$r?', '', '去龙骨荒野找阿格玛之锤的库尔迪拉·织亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12116, '孤胆英雄……', '欢迎你，$c。感谢你愿意停下来听克拉斯说话。$b$b多年以来，克拉斯一直都在倾听灵魂的话语，完成他们的愿望。$b$b最近，这片废墟中有许多声音向克拉斯哭诉，说他们不能安息。$b$b如果你愿意帮助这些灵魂，就到这里的墓穴中去，把这些受难灵魂的遗物带出来。', '哈考尔营地的克拉斯要你进入达基尔金废墟，收集5只达卡莱之罐。', '内脏?选得好，$r。$B$B卡拉兹会试试看能从这些器官里面知道些什么。感谢你勇敢地进入那个地方。', '地穴里有找到什么给卡拉兹吗，$C?', '', '去灰熊丘陵找哈考尔营地的克拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12119, '拜见红龙女王', '$N，你必须马上动身转至龙眠神殿，把这封信交给看门人塔里奥斯塔兹。神殿就座落在龙骨荒野的中央。沿着这条路往东一直走到尽头，然后穿过巨龙废土就到了。$B$B我相信塔里奥斯塔兹在了解你的来由后会引荐你拜见阿莱克丝塔萨女王陛下的。我们只能希望一切还不算太晚。$B$B感谢你为我们所做的一切，一路平安！', '转至龙眠神殿，将这封给龙眠神殿的介绍信交给塔里奥斯塔兹。', '一封谒见龙后的介绍信函?让我看看。$B$B无论你的来意为何，我希望事关要紧。今日的天空满是蓝龙的攻击!', '嗯，我能为你做些什么呢，$r?', '', '去龙骨荒野找巨龙废土的塔里奥斯塔兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12120, '达卡古尔之槌', '腐化的气息……$B$B你还没把这些罐子交给我的时候，我就已经能感觉到它们里面的腐化气息了。这种气息弥漫在充满忧虑的古代达卡莱幽魂周围，使它们不能安息。$B$B克拉斯从不说谎，$c。净化这个地方需要付出很大的牺牲，不过我们可以另找个时间来谈这个问题。$B$B在这里的活人中有一个家伙掌握着净化的关键。把它拿回来，克拉斯会告诉你更多的事情。', '哈考尔营地的克拉斯希望你去杀死达基尔金废墟外的达卡古尔，然后把达基尔金之槌交给他。', '到当前为止你都做得很好，$N，但真正的考验现在才开始。', '你找到木槌了吗，$N?', '', '去灰熊丘陵找哈考尔营地的克拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12122, '拜见红龙女王', '$N，你必须马上动身转至龙眠神殿，把这封信交给看门人塔里奥斯塔兹。神殿就座落在龙骨荒野的中央。沿着这条路往东一直走到尽头，然后穿过巨龙废土就到了。$B$B我相信塔里奥斯塔兹在了解你的来由后会引荐你拜见阿莱克丝塔萨女王陛下的。我们只能希望一切还不算太晚。$B$B感谢你为我们所做的一切，一路平安！', '转至龙眠神殿，将这封给龙眠神殿的介绍信交给塔里奥斯塔兹。', '一封谒见龙后的介绍信函?让我看看。$B$B无论你的来意为何，我希望事关要紧。今日的天空满是蓝龙的攻击!', '嗯，我能为你做些什么呢，$r?', '', '去龙骨荒野找龙眠神殿的塔里奥斯塔兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12123, '通知女王', '<向导形态的红龙读着你的介绍信，他的脸上渐渐出现了担忧的神情。>$B$B嗯……嗯，我想这应该可以让你立即拜见女王！$B$B等你准备好了之后，就来告诉我一声，我会让这些幼龙把你安全地送到神殿的顶端。你必须亲自把这封信交给阿莱克丝塔萨女王陛下。', '转至龙眠神殿，将这封给龙眠神殿的介绍信交给阿莱克丝塔萨，生命的缚誓者。', '能将这个消息带给我们一定需要莫大的勇气。我正开始怀疑为何蓝龙军团敢如此大胆地对神庙本身发动攻击。如今我晓得，他们大量使用那些原本蓝龙军团视为对造成艾泽拉斯巨大威胁的魔法。<龙后无可奈何地摇了摇头。>$B$B很伪善，但任由他们去吧。如果玛里苟斯不能恢复理智，我们除了对他的进犯进行反击之外，别无他法。', '$N，能见到你本人真好。我在你出生之前就认识你了。', '', '去龙骨荒野找龙眠神殿的阿莱克丝塔萨，生命的缚誓者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12124, '通知女王', '<向导形态的红龙读着你的介绍信，他的脸上渐渐出现了担忧的神情。>$B$B嗯……嗯，我想这应该可以让你立即拜见女王！$B$B等你准备好了之后，就来告诉我一声，我会让这些幼龙把你安全地送到神殿的顶端。你必须亲自把这封信交给阿莱克丝塔萨女王陛下。', '转至龙眠神殿，将这封给龙眠神殿的介绍信交给阿莱克丝塔萨，生命的缚誓者。', '能将这个消息带给我们一定需要莫大的勇气。我正开始怀疑为何蓝龙军团敢如此大胆地对神庙本身发动攻击。如今我晓得，他们大量使用那些原本蓝龙军团视为对造成艾泽拉斯巨大威胁的魔法。<龙后无可奈何地摇了摇头。>$B$B很伪善，但任由他们去吧。如果玛里苟斯不能恢复理智，我们除了对他的进犯进行反击之外，别无他法。', '$N，能见到你本人真好。我在你出生之前就认识你了。', '', '去龙骨荒野找龙眠神殿的阿莱克丝塔萨，生命的缚誓者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12125, '邪能之约', '我们需要能令这把剑满足的祭品，可是部落的军令禁止我们用以往的形式完成充能。$B$B<库尔迪拉停下来思考了片刻。>$B$B是时候做出一些改变啦。在这里的南方的高崖之上，有一处叫作因度雷的海象人村落。这座村落最近被蓝龙军团的混乱魔法侵蚀了，村中所有的海象人都陷入疯狂。$B$B带上这颗能量宝石，对那些疯狂的村民使用它，抽取他们的精神能量。', '龙骨荒野阿格玛之锤的库尔迪拉·织亡者要求你在一名疯狂的因度雷村民身上使用能量宝石，然后将充能的能量宝石还给他。', '给呆子做的简单工作。不出我所料。', '带羔羊之血给我。', '', '去龙骨荒野找阿格玛之锤的库尔迪拉·织亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12126, '邪恶之约', '我们一直贪图着邪恶所带来的力量。这种力量是我等死亡骑士存在的根基，早已渗透入我们的血脉之中。有谁胆敢藐视我们的力量，他就得死！幸好，我还有办法在不违背新誓言的情况下获得这种力量。$B$B带着这颗邪恶宝石去东边的红玉巨龙圣地。在那里，你可以找到一位忠于阿尔萨斯的死亡骑士瓦伦哈尔公爵。你要与他战斗，击溃他的意志，然后对他释放出宝石中的力量。之后，你就可以杀死他，并夺取他全部的邪恶能量！', '龙骨荒野阿格玛之锤的库尔迪拉·织亡者要求你对瓦伦哈尔公爵使用邪恶宝石，然后将充能的邪恶宝石还给他。', '<寇尔提拉瞪大了眼睛。>$B$B令人印象深刻。你击败了一名阿尔萨斯的死亡骑士…很显然你不是独力办到的…不过这仍旧是…', '将宝石装满秽邪之力!', '', '去龙骨荒野找阿格玛之锤的库尔迪拉·织亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12127, '冰霜之约', '噬骨的冰霜之力永远在死亡骑士作战时保卫着他们。号令冰霜之力的死亡骑士就是混乱与毁灭的代名词！$B$B拿着这颗冰霜宝石，穿过龙骨荒野的苔原，到龙眠神殿以东的黎明之镜去。在那里，你将与湖面上的冰雪亡魂军团作战，并夺取他们的冰霜精华。在削弱它们以后，你就可以利用宝石的力量了，$N！', '龙骨荒野阿格玛之锤的库尔迪拉·织亡者要求你对冰雪亡魂使用冰霜宝石，然后将充能的冰霜宝石还给他。', '我已经可以感受到寒冷流窜我全身，$N。', '在这诺森德，吾等全为冰霜效力。', '', '去龙骨荒野找阿格玛之锤的库尔迪拉·织亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12129, '完美的计划', '铁矮人显然在进行战前准备。这帮家伙有石巨人、作战魔像和闪电元素来扩充兵力，相比之下月溪旅就处于劣势了。如果联盟没有及时找到往北挺进的路线，铁矮人很可能会出其不意地发动袭击。$B$B我们必须牵制铁矮人的行动，好在我已经想到办法啦。大批铁符文铸造师聚集在丹厄古尔制造作战魔像。他们狡猾地将设计图分成若干部分，分别保存起来。你必须收集到一份完整的设计图。', '将一份完整的作战魔像蓝图交给勘探员哨站的莱加尔·断眉。', '你全都拿到了?太棒了!我等不及想看他们看见魔像完成时脸上的表情了。', '你从符文铁匠那边弄到设计图了吗?', '', '去灰熊丘陵找勘探员哨站的莱加尔·断眉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12130, '抢夺零件', '设计图是到手了，但是缺零件怎么搞啊！我们既没铸造工具，也没原材料，不过……应该能在丹厄古尔找到不少零件。$B$B你的任务？$B$B你的任务就是替我弄些回来啊。$B$B在铁符文铸造师工作的建筑物附近就散落着很多零件。当然，这属于偷窃他人的劳动成果，我可不敢保证那些铁矮人不会冲你发火。尽可能多弄些零件回来吧，这样我们才能制造作战魔像。', '将8份作战魔像零件交给勘探员哨站的莱加尔·断眉。', '<瑞加尔用手背擦擦额头。>$B$B喔不，这比我想的还要困难。这些东西上面没有编号之类的东西对吧?$B$B当你需要地精的时候他们总是不在你身边…', '嗯，看来你全身而退了。你有拿到零件吗?', '', '去灰熊丘陵找勘探员哨站的莱加尔·断眉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12131, '我们有能源', '就快大功告成啦，不过作战魔像需要能量晶格做动力源。在被丹厄古尔的铁矮人发现之前，我们已经收集到了很多颇有价值的情报。符文铸造师杜拉尔和符文铸造师卡索恩身上就有能量晶格。$B$B我们得设法搞来这两块能量晶格。$B$B他们应该在丹厄古尔中层的两座车间里。', '将杜拉尔的能量晶格和卡索恩的能量晶格交给勘探员哨站的莱加尔·断眉。', '<瑞加尔从你手中取走了电池。>$B$B太棒了，我们应该可以准备上路了。', '嗯，你拿到那些电池没?', '', '去灰熊丘陵找勘探员哨站的莱加尔·断眉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12133, '击碎南瓜', '村子中央放置着一盏巨大的南瓜灯。它闪烁着诡异的光芒，透露出难以捉摸的诡异气息。$B$B击碎南瓜灯后，你发现了一枚烧焦的神圣符记。', '将烧焦的神圣符记交给穿戏服的孤儿院长。', '你从无头骑士的南瓜灯笼中找到的?这是个古老的圣光徽记。在他受到诅咒变成今天这样的怪物之前，这一定曾属于无头骑士。感谢你，$N。这个徽记应该属于圣骑士。我会确保他们收到这个。$B$B喔，我差点忘了!你有个秘密的仰慕者……$g她:他;太害羞，不敢把这个亲自交给你。', '$N，怎么了吗?', '', '去找穿戏服的孤儿院长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12134, '萨莎的狩猎', '这个东西……这个诅咒……它毁了银溪镇，它毁了冬至村……它将所有的人都变成了野兽。$B$B我的父亲曾试图警告他们，但他们已经完全沦落成了拜狼教的奴隶。$B$B他们已经无可挽救了，为了让他们的灵魂解脱……你必须去除掉他们。', '萨莎要求你在冬至村中击败12名冬至村猎人。', '杀死这些怪物也不能换回我父亲…但这并不是重点，对吗?', '你处理掉村子里的猎人了没，$N?', '', '去找灰熊丘陵白松商栈的萨莎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12135, '“放火过来吧！”', '你必须帮帮我们！无头骑士随时都有可能发动攻击！到时候村子里肯定火光连天！孤儿院的孩子性命堪忧！$B$B$n，你愿意熄灭无头骑士燃起的火焰吗？加入消防队吧。拿上水桶去灭火，或者把它递给更靠近火焰的伙伴。只有扑灭所有的火焰才能拯救我们！', '穿戏服的孤儿院长希望你在无头骑士发动攻击时帮忙扑灭村子里的所有火焰。完成任务后与穿戏服的孤儿院长谈一谈。', '噢，感谢你!愿圣光祝福你的善举，仁慈的$g先生:女士;。黑暗骑士的阴影依旧在逼近，但起码现在，村子不受他的火焰威胁了。', '$N，你答应过要拯救这些孩子的!', '扑灭火焰', '去找穿戏服的孤儿院长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12136, '翻译过的魔典', '给你，$N。我已经把这本书上面每一页所写着的东西都翻译给你了。在这些内容中有一份诅咒教派的成员名单，名单上详细罗列了他们分布在整个大陆的间谍网和行动组织的成员及结构。$B$B说实话，这套情报网的确非常优秀。$B$B再见，朋友。愿这本书上的内容能帮到你。', '将翻译过的血之魔典交给阿格玛之锤的高尔特上尉。', '<苟尔特从你这接过了骨书读了起来。>$B$B什么!不可能吧。我已经认识这些兽人好多年了!$B$B$N，留我一个人吧。我有很多事情要做，要来处决这些叛徒。$B$B从这些东西里面挑一件吧，就当作麻烦你的奖赏。今天，你为部落做出了伟大的贡献。', '总该回来了吧!你去哪了?', '', '去龙骨荒野找阿格玛之锤的高尔特上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12137, '冷静一下，伙计', '正如预言所说的那样，朋友。一个$r$c会来到这里，让我们的灵魂得到安息。我们已经等了很久了！$B$B达卡莱巨魔已经迷失了，他们残暴而又野蛮，他们忘记了许多神圣的戒律，而现在他们正在为此付出代价。$B$B但是我们在这里所忍受的痛苦，却并非是我们自己的错误所引起的。这个地方需要得到净化，而只有活人可以这么做。$B$B当你准备好重新回到你的躯壳中时，就找我谈谈，然后拿上我身旁箱子里的雪，让我的同胞长眠吧。$B$B把他们的残迹交给你的灵魂导师。他知道下一步该怎么做。', '甘休希望你能从他在达基尔金废墟的箱子里拿到永恒休眠之雪。$B$B对那里的上古阿卡莱幽魂使用永恒休眠之雪，然后把它们的达卡莱灵魂微粒交给哈考尔营地的克拉斯。', '干得好。$B$B请坐，专心听。我们要好好讨论一些事情。', '$C，地穴里面的任务你完成了吗?', '', '去灰熊丘陵找哈考尔营地的克拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12140, '洛纳乌克万岁！', '就像牛头人、被遗忘者、巨魔和血向导一样，牦牛人也需要一位源自他们血脉的领导者。你所救下的那位洛纳乌克·冰雾就是最合适的人选。$B$B<阿格玛大王交给你一份文书。>我现在给你一份你之前可能已经见过的东西——加入部落的血誓文书。$B$B将这份文书交给洛纳乌克·冰雾，并引导他以牦牛人族长的身份加入部落。$B$B快去吧，别让他等太久。$B$B<阿格玛点了点头。>', '在阿格玛之锤找到洛纳乌克·冰雾，并引导他加入部落，成为部落的领袖之一。$B$B完成任务之后带着部落的血誓向阿格玛大王复命。', '有了这么强悍的萨满协助，我们一定能够在愤怒之门获得胜利!', '不要浪费时间，$N，安格拉萨正在等着!', '', '去龙骨荒野找阿格玛之锤的阿格玛大王。', '洛纳乌克·冰雾加入部落', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12142, '害虫控制', '啊！有只狗头人趁我们忙着对付龙族时跑进营地闹腾了一番。稍不留神，它们就来捣乱……我真是受够了！$B$B狗头人就待在南边的猛犸人营地里。去那里干掉它们。$B$B如果猛犸人打算替他们的奴隶出头，就连他们一起杀掉。', '第七军团前线的杜埃尼希望你转至龙眠神殿周围的猛犸人营地，消灭10个雪原北地狗头人和3个龙骨荒野猛犸人。', '杀的好。', '你解决那些害虫了吗?', '', '去龙骨荒野找第七军团前线的杜埃尼。', '雪原北地狗头人', '龙骨荒野猛犸人', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12143, '峡谷追击', '真不敢相信！另一群狗头人刚刚偷袭了我们的营地，抢走了一批补给品。他们朝北边的峡谷逃去了，追上这帮强盗，干掉他们的首领！', '杜埃尼希望你在第七军团前线东北方向的峡谷中找到北地狗头人的踪迹，并干掉它们的领袖。', '寒牙，嗯?我听过它的名字。真是干的好，$C。希望我们现在能够把注意力转回龙的威胁上。', '解决了吗?', '', '去龙骨荒野找第七军团前线的杜埃尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12145, '峡谷追击', '开……开什么玩笑呀！又有一群见鬼的狗头人抢走了我们的补给物资。现在它们跑到那边的峡谷里去啦，你还发什么愣，追啊！追上去，不管它们是谁，让它们统统去死啊！', '肯图卡尼斯希望你在猎龙营地以南的峡谷中找到北地狗头人的踪迹，并干掉它们的领袖。', '冰拳，吭?我听过这名字。做的好，老兄。希望暗矛巨魔现在可以把注意力转回龙的威胁上了。', '你知道他们跑哪去了吗?', '', '去龙骨荒野找猎龙营地的肯图卡尼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12146, '奇怪的符号', '号角内侧装饰着一枚绘有铁锤与闪电的纹章。这显然不是猛犸人的东西。$B$B带上号角，沿着泰坦之路向南走，到龙眠神殿去看看有谁能解读其中的奥秘。', '带上精美的战斗号角转至龙眠神殿，看看那里有谁可以评估一下这潜在的威胁。', '猛玛象人带着像这样的东西确实是很奇怪…而且很重要。我很高兴你把这样东西拿给我看。', '嗯，$r?', '', '去龙骨荒野找龙眠神殿的奥拉斯塔萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12147, '古怪的暗示', '这只号角的号管内侧印刻着一个非常漂亮的徽记，图案是一只铁锤和一束闪电。而号角的某些外形特征表明这只号角似乎是从猛犸人那里流出的。$b$b往东穿越巨龙废土，将这只号角带回龙眠神殿，看看是否有人能辨识出它的出现意味着什么样的威胁。', '带上精美的战斗号角转至龙眠神殿，看看那里有谁可以评估一下这潜在的威胁。', '猛玛象人带着像这样的东西确实是很奇怪…而且很重要。我很高兴你把这样东西拿给我看。', '嗯，$r?', '', '去龙骨荒野找龙眠神殿的奥拉斯塔萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12148, '集结的信号', '这在猛犸人当中是一个非常非常少见的标识……它代表着某种大规模集结的信号。$B$B猛犸人各部族之间很少会放弃争斗，联合行动。我认为他们很可能在策划洗劫某个大型定居点。$b$b我深刻怀疑这支号角是不是用来集结各个猛犸人部族的，不过希望你能证明我是错的，否则威胁可就太大了。在碧蓝巨龙圣地西北方的悬崖地带有一个名叫裂骨者的猛犸人。去挑战他吧，把任何能证实我的担忧的证据带回来。', '在碧蓝巨龙圣地西北边的峡谷附近找到裂骨者，并杀死它。带着证据回去向龙眠神殿的奥拉斯塔萨复命。', '所以是真的了。他们真是选了个绝佳的时机来攻击…藏在天灾军团与蓝龙之间，应该还没有别人注意到。', '你找到什么了吗?', '', '去龙骨荒野找龙眠神殿的奥拉斯塔萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12149, '强大的猛犸人', '猛犸人生性凶残……一旦聚集起来，就免不了互相杀戮。这也是他们难以构成很大威胁的主要原因。但是近来，猛犸人氏族中涌现出一位强大的领袖。我们必须在猛犸人形成可怕的凝聚力之前除掉他。$B$B我会对此进行周密的调查。在此期间，我打算派你去骚扰他们。$B$B神殿东面有三支火炬，猛犸人氏族中最强大的三名头目就驻扎在火炬旁。去干掉他们，为我们争取足够的时间来收集那位领袖的信息。', '在龙眠神殿以东找到并杀死食血者、破冰者和德拉古尔。$B$B食血者盘踞在巨龙废土的东南角，就在翡翠巨龙圣地北面。裂冰者控制着黎明之镜的北部边界。德拉古尔则在青铜巨龙圣地的西部峭壁下来回巡视。$B$B杀死这三个猛犸人后返回龙眠神殿，向奥拉斯塔萨复命。', '做的好。没人能告诉我这个领袖到底是谁，不过我找出了一个家伙，他许知道我们要的答案。', '你击败猛玛象人了吗?', '', '去龙骨荒野找龙眠神殿的奥拉斯塔萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12150, '隐居的铭语师', '德雷格玛尔·符印是一名猛犸人铭语师……罕见的头衔。他过着独居的生活，却与龙骨荒野上所有具备影响力的猛犸人头目保持着密切的联系。他应该知道这位脱颖而出的新任领袖是谁。$b$b在天灾军团和蓝龙军团的双重威胁之下，恐怕我们很难得到其它同僚的情报协助。因此，我命令你不惜一切代价，从德雷格玛尔口中问出这条信息。$B$B我听说他居住在俯瞰黎明之镜的悬崖地带。', '登上俯瞰黎明之镜的悬崖，在德雷格玛尔·符印栖身的洞穴附近找到他。向他发起挑战，用尽一切办法逼他说出猛犸人领袖的名字。完成任务后返回龙眠神殿，向奥拉斯塔萨复命。', '『雷霆使者』戈洛塔尔。很好。现在就让我们来解决猛玛象人对此地造成的威胁。', '你知道名字了吗?你知道猛玛象人督军是谁了吗?', '猛犸人领袖的名字', '去龙骨荒野找龙眠神殿的奥拉斯塔萨。', '猛犸人领袖的名字', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12151, '暴虐的酋长', '没有必要怀疑达米娅所说的。无论是戈洛塔尔获胜还是你获胜，她都能置身事外。$b$b按她的指示去做吧……拿上这只号角，转至碧蓝巨龙圣地南边的火炬之环。吹响号角，向戈洛塔尔宣战。$B$B击败雷霆使者戈洛塔尔，将他的首级带回来给我。', '转至碧蓝巨龙圣地以南的火炬之环，吹响精美的战斗号角。击败雷霆使者戈洛塔尔，并将他的首级交给龙眠神殿的奥拉斯塔萨。', '你实在可敬可畏。$B$B只要『雷霆使者』戈洛塔尔不在了，我们就可以不管其馀的猛玛象人，让他们彼此互相斗争，把我们的注意力转回更严重的威胁上。$B$B令人佩服的成就， $C。', '你彻底解决我们的威胁了吗?', '', '去龙骨荒野找龙眠神殿的奥拉斯塔萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12152, '金亚拉克的末日', '很高兴看到你能活着回来。很多去过亡者世界的人都没能回来。$B$B在你离开的时候，克拉斯看到一个幻象，并得知了接下来需要做什么。$B$B在墓穴内有一份神圣的供品。带上这些由你带来的残迹制成的灵魂之尘，把它撒在供品上。$B$B这样就可以了结那个堕落的督军，并释放出无数痛苦的灵魂。$B$B让灵魂引领你的行动吧，$n。', '哈考尔营地的克拉斯希望你从达基尔金废墟收集神圣达卡莱供品，然后将达卡莱灵魂之尘撒在上面。你必须在达基尔金废墟的锣处使用灌注能量的达卡莱供品。', '完成了。$B$B你的无私带给许多灵魂永恒的平静，终结了亘古的磨难。$B$B愿此举能照耀你的灵魂，减轻你的重担，因为我的眼中仍可见你必须面对更大的危机。$B$B再会吧，$N。', '$N，吉纳拉克被击败了吗?', '', '去灰熊丘陵找哈考尔营地的克拉斯。', '消灭督军金亚拉克', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12153, '铁领主和他的保镖', '作战魔像已经充电完毕，轮到它大展身手的时候啦。在丹厄古尔引导魔像，控制它开始作战。$B$B关于丹厄古尔的铁领主弗雷哈默尔，我们收集到的情报表明他有一名非常强力的护卫。$B$B这个名叫“铁砧”的构造体随时都跟在他身旁。只要摧毁构造体，弗雷哈默尔就容易对付了。$B$B铁领主通常呆在丹厄古尔顶层的大型设备间，监督铁矮人的生产线。', '驾驶作战魔像击败铁领主弗雷哈默尔，然后返回勘探员哨站向莱加尔·断眉复命。', '真的成功了?\r\n\r\n<加尔·断眉清了清他的喉咙。>\r\n\r\n我是说…当然会成功啦!真是不可置信!\r\n\r\n今后，$N，探险者协会的新成员便能听到了加尔·断眉的故事，以及随便一尊破铜烂铁魔像就打败了丹亚戈的族长!', '你能突破铁族长的防卫吗?', '', '去灰熊丘陵找勘探员哨站的莱加尔·断眉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12154, '停电', '安置在丹厄古尔顶层大厅的能量源向整片本地提供电力。如果摧毁能量源，丹厄古尔就会暂时陷入瘫痪。$B$B如此一来，铁矮人就不能继续制造魔像和闪电元素之类的玩意了。$B$B本来呢，这些炸药是用于挖掘工事的。托铁领主弗雷哈默尔的福，我们的研究工作已经完全搁浅啦。不过，我们还是用得着这些炸药的。它是摧毁能量源的唯一手段。', '使用莱加尔的炸药摧毁丹厄古尔的符文能量核心，然后返回勘探员哨站向莱加尔·断眉复命。', '<瑞加尔.断眉表示同意的点点头。>$B$B我不能眼睁睁看着炸药被浪费掉，而这肯定可以拖慢敌人的脚步。', '你停止了他们符文熔炉里面的能量来源了吗?', '', '去灰熊丘陵找勘探员哨站的莱加尔·断眉。', '摧毁丹厄古尔能量核心', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12155, '击碎南瓜', '村子中央放置着一盏巨大的南瓜灯。它闪烁着诡异的光芒，透露出难以捉摸的诡异气息。$B$B击碎南瓜灯后，你发现了一枚烧焦的神圣符记。', '将烧焦的神圣符记交给戴面具的孤儿院长。', '你从无头骑士的南瓜灯笼中找到的?这是个古老的圣光徽记。在他受到诅咒变成今天这样的怪物之前，这一定曾属于无头骑士。感谢你，$N。这个徽记应该属于圣骑士。我会确保他们收到这个。$B$B喔，我差点忘了!你有个秘密的仰慕者……$g她:他;太害羞，不敢把这个亲自交给你。', '$N，怎么了吗?', '', '去找戴面具的孤儿院长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12159, '不能安息的灵魂', '<派特洛夫似乎是遭受到了某种沉重的打击，他的呼吸很沉重也很急促，双眼一直在扫视着矿洞内的一切。>$B$B我的同志们……我们必须让他们的灵魂得到安息！我一次又一次击败他们……可是……他们却一次又一次地站起来！$B$B我已经有了一个办法，但却不能下狠心去这么做。$B$B或许你可以帮我的忙？带着这盏灯，用里面的灯油净化他们的躯体，这样他们或许就再也不会站起来了……$B$B等下我会回答你所有的问题，先帮帮我的朋友们！', '空石矿洞的派特洛夫要求你使用矿工的灯笼净化8具空石矿工的躯体。', '安息吧我的朋友们!不要担心 -- 我会告诉大家我们从没放弃过!', '你让我的朋友安息了吗，$N?', '', '去灰熊丘陵找空石矿洞的派特洛夫。', '让矿工安息', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12164, '狼人的末日', '是时候了，$N。必须除掉阿鲁高。$B$B我们要集结一小队值得信赖的精锐冒险者转至海岸对面的血月岛，就在东边。$B$B我们必须组织一次快速的打击。先清除掉阿鲁高手下最忠心的几个守卫，等到你正式向他挑战时，我会及时赶来的。', '白松商栈的萨莎要求你转至血月岛，杀死塞拉斯、瓦拉姆、污血之喉和阿鲁高之影。', '我们给了他一顿教训，$N，但还不够。$B$B但有件事我很肯定…我们不会在这附近再看到他了。', '见到你真好，$N。', '', '去找灰熊丘陵白松商栈的萨莎。', '', '', '', '击败阿鲁高之影');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12165, '有趣的计划', '勘探员罗卡尔已经决定帮助我们，他计划利用铁矮人的力量来对付他们。$B$B我必须得承认，我没想到这个新“伙伴”有如此过人的洞察力。他指出我们的人数不够，不能发动正面进攻。$B$B转至丹厄古尔，那地方就在东南方的冰天雪地里，从那里的铁符文铸造师手里夺取所有的作战魔像蓝图。把完整的蓝图交给罗卡尔，让我们看看他的计划是否有价值。', '将完整的作战魔像蓝图交给欧尼瓦营地的勘探员罗卡尔。', '托迈克决定要采用这个计画了吗?我猜如果他否决了这个任务，他不会派你来的。$B$B噢，麻烦…我该怎么在这么大压力之下搞清楚要怎么把零件拼起来?', '你…你拿到我要的蓝图了吗?', '', '去灰熊丘陵找欧尼瓦营地的勘探员罗卡尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12166, '艾露恩的火油', '你愿意帮帮我吗，$c？$B$B天灾军团已经开进了北面的冰雾村。他们走到哪里，哪里就会变得腐烂荒芜，生灵涂炭。$B$B拿着这只瓶子，里面装满了从月亮井中汲取的艾露恩的火油。请你用它净化那些死亡的野生动物的尸体。', '群星之墓的典狱官朱蒂·月歌要你使用艾露恩的火油净化6只天灾麋鹿的尸体和6只狂暴灰熊的尸体。', '我们已经对这片土地上的生物尽吾所能了，我们必须对造成这一切的主使采取直接的手段!', '很惭愧的，我们不能在它们成为天灾军的牺牲者时，治愈这些熊与麋鹿。$B$B至少我们可以阻止污染的蔓延。', '', '去龙骨荒野找群星之墓的典狱官朱蒂·月歌。', '净化天灾麋鹿的尸体', '净化狂暴灰熊的尸体', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12167, '消灭教徒', '阿努巴尔教徒是间接造成动物们感染瘟疫的原因，因此我们必须阻止他们！$B$B他们衣服里冒出的毒雾会渗入那些接近过他们的生物体内，污染着环境。$B$B你必须到北面的冰雾村去杀了他们，把他们的衣服给我带来，我会妥善处理掉。', '群星之墓的典狱官朱蒂·月歌要你收集5件教徒的衣物。', '干得好。$B$B我会处理这些污秽的服装，投入月井中净化，并以女神之力摧毁它们。', '这些教徒正在污染生物!', '', '去龙骨荒野找群星之墓的典狱官朱蒂·月歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12168, '扎古斯的礼物', '在这件礼物的背面写着：$B$B“给我最爱的学生，$B$B如果你能继续遵守诺言，我会让你领略超乎你想象的奇迹。$B$B如果你胆敢背叛，我就毁灭你！$B$B你永远的良师，$B$B高阶教徒扎古斯”$B$B群星之墓的典狱官肯定会对这东西感兴趣的。', '将扎古斯的礼物交给群星之墓的典狱官朱蒂·月歌要。', '这么说，教徒首领已经现身了。我们有了他的名字。$B$B虚荣和骄傲将会是他的致命伤!', '我感觉到邪恶逼近。$B$B就在你身上!$N，究竟是什么?', '', '去龙骨荒野找群星之墓的典狱官朱蒂·月歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12169, '高阶教徒', '我曾经梦见过扎古斯，但如果没有你发现的这些文字，我就不可能理解那个梦意味着什么。你的发现让我明白了，这是女神给我的指示，而我们已经知道，他就在北面的纳尔苏深渊里。$B$B你知道该怎么做，$N。为了拯救这片土地，必须除掉这个高阶教徒！', '群星之墓的典狱官朱蒂·月歌要你杀死高阶教徒扎古斯。', '伴随着高阶祭司被毁灭，他的残党会被扫除，大地和万物将恢复。$B$B感谢你，$N。愿女神照亮你的道路。', '我感觉到高阶教徒赞古司还活着。$B$B$N，出了什么错吗?也许你需要先休息一下?', '', '去龙骨荒野找群星之墓的典狱官朱蒂·月歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12170, '黑水伐木场的战斗', '我们在这里出现后不久，风险投资公司就放弃了他们在这里的工程。显然他们担心我们会对他们贪婪的小把戏有所行动。$B$B既然他们已经离开了，他们的伐木场也就属于公共财产了。我们的战争机器是一头饥饿的野兽……如果没有持续不断的补给，我们是不可能成功抵达冰冠冰川的。$B$B不过，联盟似乎和我们有着相同的想法，因此我们必须保证只有部落才是最终获胜的一方。向伐木场出发吧，帮我们对抗那些联盟狗。', '骑兵队长克洛恩希望你在黑水伐木场击杀10名联盟士兵或者玩家。', '$N，做得好。我们对伐木地的控制尽管还没完成，但是因为你，我们离打扁联盟蛆虫之路又更进了一步。', '你把联盟狗宰光了吗?胜利是属于我们的!', '', '去找灰熊丘陵的骑兵队长克洛恩。', '消灭黑水伐木场的联盟', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12171, '叛徒的名单', '你必须立即把我手里的这份名单交给高级指挥官哈尔弗·维姆班恩。他指挥的第七军团就驻扎在龙骨荒野东部的暮冬要塞里。$B$B如果这份名单上的叛徒进入了暮冬要塞……那就太可怕了。$B$B赶快，$N。把这份文件给群星之墓这里的帕蕾娜·银云看看，向她解释你的任务性质。她会派最快的角鹰兽送你转至暮冬要塞！', '向群星之墓的帕蕾娜·银云出示联盟信函。', '<帕雷那读了公文。>$B$B你可以搭乘我最快的角鹰兽，$r!这个消息必须马上送到高阶指挥官海弗德.龙祸手上!', '嗨，$r。', '', '去龙骨荒野找群星之墓的帕蕾娜·银云。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12172, '达拉然的能量调和', '欢迎你，法师。$B$B你现在肯定在想，达拉然在哪里？怎样才能去那里呢？让我来帮你吧。$B$B不过在我教你如何传送到我们伟大的城市去之前，你必须得对你自己和诺森德的魔网能量线进行调和。否则，你可能会在传送过程中伤害到自己。$B$B带上这块魔网调和水晶，转至这里西面的眠月花园，在那里的湍流之针下面的深坑中使用它。这样你就完成了学习法术的准备。', '群星之墓的大法师茉德拉的影像要你与诺森德的魔网能量线进行调和。', '很好。如果你准备好了，那我就准备好了。', '你调和完成了吗?这可不能说谎喔，$N。$B$B如果你没有确切准备好，可是我教你使用这则法术，那么你使用法术的那一天就会是你的忌日!', '', '去龙骨荒野的群星之墓找大法师茉德拉的影像。', '与诺森德的魔网能量线调和', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12174, '高级指挥官哈尔弗·维姆班恩', '<帕蕾娜把公函交还给你。>$B$B雪暴会立刻把你送到暮冬要塞去的，$N。我保证它是你乘坐过的最快的坐骑！出发吧！', '转至龙骨荒野东部的暮冬要塞，将联盟信函交给高级指挥官哈尔弗·维姆班恩。', '<高阶指挥官阅读过公文，随后将它揉成一团。>$B$B你知道这张名单上的人都去哪了吗?瞧瞧外头，靠近前门的地方。他们被吊死在拱门的地方。$B$B食尸鬼的诱饵……', '士兵，你去过那里了吗?', '', '去龙骨荒野找暮冬要塞的高级指挥官哈尔弗·维姆班恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12175, '灰狼的毛皮', '让我来告诉你一些事情吧，朋友。当你负责给部落的军队提供装备时，就会需要大量的毛皮！$B$B征服者克雷娜，就是那个负责这地方各类事务的母老虎，她给我定了一个严格的交货日期。如果我不能在本周末前给她的整支部队置办好军装的话，她会把我扔进坑里跟熊摔跤的。$B$B帮我一把，我会出最好的价钱给你。我需要灰雾捕猎者身上的毛皮。$B$B你可以在这里的北面找到它们，一般来说它们都在捕猎野鹿。记住，朋友，最好的价钱哦。', '征服堡的皮货商人休尼克希望你能从北面森林的灰雾捕猎者身上获取3张灰色座狼皮。', '你救了我一命，$g哥哥:姊姊;。如果你还有兴趣的话，我们还需要更多的狼皮。', '老兄，你拿到皮革了吗?', '', '去灰熊丘陵找征服堡的皮货商人休尼克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12176, '替换品', '克雷娜想用座狼的皮来制作所有军装。可是，似乎没有足够多的座狼皮能满足她这支部队的需要。现在不够，永远也都不可能够。$B$B那些座狼实在是太瘦小了，朋友！如果你能保守秘密的话……我们可以这样……$B$B沃德伦的东面生活着像食人魔一样肥硕的大灰熊。我们可以使用那些大家伙的毛皮来充数！$B$B快点，朋友。克雷娜可没有什么耐心。', '皮货商人休尼克希望你能交给他6张灰熊皮。', '我欠你一次啊，老兄。收下这笔报酬吧。', '老兄，你拿到毛皮了吗?', '', '去灰熊丘陵找征服堡的皮货商人休尼克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12177, '休尼克的掩饰', '啊，有麻烦了，朋友！灰熊的皮……居然不是灰色，而是棕色的！$B$B让我想想……让我想想！$B$B有了，朋友！只能这样了：灰色是由黑色和白色混合起来的。你给我弄些煤块和面粉过来，我把它们碾碎，然后刷在毛皮上。没有更好的办法了！$B$B铁匠会出售冶炼用的煤块，另外你可以从粮食供应商人那里弄到面粉。', '将1份煤块和5份面粉交给灰熊丘陵征服堡的皮货商人休尼克。', '希望能成功呀，老兄。', '东西拿来了吗，老兄?', '', '去灰熊丘陵找征服堡的皮货商人休尼克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12178, '给克雷娜送货', '搞定了！让我把这些毛皮拿给克雷娜看看，是否能通过她的测试。$B$B让我们期待克雷娜什么也不会发现。', '将一捆兽皮交给征服堡的克雷娜。', '谁派你来的?这些毛皮闻起来跟面粉一样!$B$B这对部落而言是奇耻大辱!', '你以为你在和谁说话?', '', '去灰熊丘陵找征服堡的征服者克雷娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12180, '被俘虏的勘探员', '莱加尔派了一队勘察员转至丹厄古尔寻找古器，顺便收集关于这座遗址的历史数据。他们未曾料到丹厄古尔竟是个有重兵把守的要塞。$B$B勘察小队被丹厄古尔的铁矮人囚禁起来了。我们暂时找不到接替他们的人手，而莱加尔整日里挖空心思地计划如何打败铁矮人，根本无暇顾及此事。$B$B$N，营救勘察员的重任就交给你啦。铁矮人或是他们的仆从身上可能携带着囚笼的钥匙。', '营救勘探员甘恩、勘探员托尔根和勘探员瓦拉纳，然后返回勘探员哨站，向巡山人基连复命。', '<巡山人基立安听你转述被俘的勘查员对你所说的内容。>$B$B他们提到了洛肯以及一场对抗石巨人的战争?你确定吗?$B$B那么瑞加尔的直觉没有错。我们得想个办法潜进去，调查清楚他们的计画。', '你找到失踪的勘查员了吗?', '', '去灰熊丘陵找勘探员哨站的巡山人基连。', '营救勘探员甘恩', '营救勘探员托尔根', '营救勘探员瓦拉纳', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12181, '给它一个名字', '啧啧，多久了？我们为了这该死的药剂苦心研究多久了？终于……在无数次的失败之后，我们得到了完美的结晶。这……这东西甚至都还没有一个恰当的名字！这种足以让一切凋零的药剂……对，就是它了，凋零药剂！它将会把一切生命撕得粉碎！$B$B<哈瑞斯交给你一只瓶子。>$B$B现在，去找托比亚斯·萨克霍夫，给他看看这个样本。他会送你去怨毒镇的。', '向新阿加曼德的托比亚斯·萨克霍夫出示你的凋零药剂样本。', '呃，是啊，你可以带着瓶子上去，我相信你。', '要把高度致命剧毒瓦斯送到毒怨之地?快上蝙蝠吧!', '', '去嚎风峡湾找新阿加曼德的托比亚斯·萨克霍夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12182, '转至怨毒镇！', '我这里正好有一只整装待发的蝙蝠可以给你用，伙计。它可是我这里飞得最快的，保证又快又稳地把你送到怨毒镇去。$B$B到了那边之后，把样本交给首席药剂师米德尔顿就行了。', '转至龙骨荒野东部的怨毒镇，将凋零药剂样本交给首席药剂师米德尔顿。', '好个愉悦的一天!看，往东北方去、越过山脉，有一大群的天灾军等着我们来消灭!', '你是货运$g小弟:小妹;吗?', '', '去找龙骨荒野的首席药剂师米德尔顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12183, '搜集制服', '如果勘探员瓦拉纳所言非虚的话，似乎只有监工级别的铁矮人才有权接近这个洛肯。$B$B你得设法混进去探个究竟，不过这事儿有点棘手。首先我们要搞到一件监工的制服。$B$B然后我们就替你好好地伪装一番。$B$B转至丹厄古尔，干掉一名监工，把他的制服给我带回来。如果你不小心让血溅到制服上，那就自认倒霉吧。', '将一件监工的制服交给勘探员哨站的巡山人基连。', '<基立安从你这接过制服。>$B$B这就行了。我没时间缝上一片绣有“$N”的名条嘿，不过，到时候，任何人近看你都会被你的装扮给说服的。', '你拿到制服了吗?', '', '去灰熊丘陵找勘探员哨站的巡山人基连。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12184, '拍摄照片', '制服已经到手啦，不过我们需要更为详细的数据来完善伪装。$B$B这台相机是莱加尔用来记录探险队的发现的，不过它或许能派上别的用场。我要你带上它进入丹厄古尔，拍摄一些铁矮人的照片。$B$B当然，你的模特们很可能不是那么合作，如此一来呢，你就必须……嗯……制伏他们。完成任务后把相机和照片一同带回来给我。', '用基连的相机拍摄8张丹厄古尔铁矮人的照片，然后返回勘探员哨站，向巡山人基连复命。', '好，这些就派得上用场了。马上来做一个让你有办法让铁矮人信服的玩意儿。', '相片到手了吗?', '', '去灰熊丘陵找勘探员哨站的巡山人基连。', '拍摄铁矮人的照片', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12185, '笑脸面对洛肯！', '参考了你拍摄的照片之后，我已经为你做好了监工伪装包。我可不是吹牛，这玩意儿能将你包装成货真价实的铁矮人。$B$B进入丹厄古尔后使用伪装包，然后转至废墟中层最东边的建筑物。$B$B领主和监工利用安置在建筑物中的底座接收来自洛肯的指令。在伪装状态下激活底座，截获情报。', '伪装成铁符文监工，截获洛肯的指令，然后返回勘探员哨站，向巡山人基连复命。', '也许洛肯并没有夸大其词?泰坦的石族和铁族子嗣竟然为了古城奥杜亚的控制权打得不可开交。这太疯狂了，$N，这可能会把我们得知矮人族历史的唯一机会给毁了!', '伪装有用吗?', '', '去灰熊丘陵找勘探员哨站的巡山人基连。', '截获洛肯的指令', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12188, '凋零药剂与你：如何自保', '凋零药剂的化学组成是怎样它如何生效如何发挥其功能等等，这些细节问题都完全不重要。你所需要知道的仅仅就是：它是否能按设计指标达成它的性能，这就足够了。我已经成功地把成分导入了休眠状态。$B$B<米德尔顿拔开一个试管的塞子，放在鼻子边上猛吸了一口。>$B$B看，完全没事，我的身体完全没变化。这种成分只要混入使它重新活化的催化剂，就能恢复威力。$B$B现在的课题就是找到催化剂最合理的成分。你可以在南边海滩上找到许多联盟士兵的鬼魂。把他们干掉，然后把他们身上的灵质残渣带回来给我。', '怨毒镇的首席药剂师米德尔顿要求你给他带回10份灵质残渣。', '这些就够了，$N。这些可悲的蠢货有试着攻击你呢，还是纯粹对你喷洒着悲苦的鬼魂之泪呢?$B$B啊，他们实在很情绪化…', '残渣可以用作引导荒疫的活性触媒!', '', '去龙骨荒野找怨毒镇的首席药剂师米德尔顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12190, '跟我的小朋友打招呼', '哈考尔肯定愿意用金砖来换这些精选的材料。你只需把东西都带给他就行啦。$B$B他就驻营在东部海岸的那些废墟附近——好像是叫达基尔金废墟什么的。$B$B你应该能在我处理掉这些尸体之前达到那里……除非，你情愿待在这里帮这些尸体涂上防腐剂？', '普雷蒙希望你将哈考尔的调料的交给哈考尔营地的哈考尔。', '很好!好心的老皮格蒙送你来我这?$B$B有了这些，就能弄一顿好吃的啦。只要再来几样东西…', '我能为你做什么?', '', '去灰熊丘陵找哈考尔营地的哈考尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12191, '扔酒杯！', '讨厌的黑铁矮人发动了反击！你能在必须的时候保护自己吗？更重要的是，你能够保护我们的财产吗？我们最好得要考验一下你的实力。$B$B掷杯训练器已经准备就绪啦，来试试吧？拿起免费美酒节取样器喝上几口，然后将酒杯抛向训练器！击中目标5次后再来找我谈谈！', '用免费美酒节取样器击中掷杯训练器5次，然后与比兹尔·奎利弗谈一谈。', '哇…S.T.O.U.T.没有坏掉…嗯…谁想得到?$B$B我的意思是，嗯，你办到了!你的准头不赖，起码够保护这个营地了。我想你已经准备好对付那些黑铁矮人，要是他们胆敢再出现的话。', '干了这一杯，打个嗝，然后拿酒杯丢S.T.O.U.T.。我想他承受得了这种攻击。要是他做不到，我干嘛把他给偷…呃…制造出来!', '', '去找杜隆塔尔的比兹尔·奎利弗。', '击中掷杯训练器', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12193, '今年有没有纪念品？', '美酒节除了赛羊会外，还有一项传统，那就是饮酒狂欢！如果你有时间的话，就将这张礼品券交给贝尔比吧。她就在美酒节营地的后面。要是你看不见她，没关系，她一定会看见你的。$B$B无论如何，将礼品券交给她，你就能免费领到一只美酒节酒杯。她还出售各种美酒哦。', '在美酒节营地的贝尔比处兑换礼品券。', '噢，只是张酒杯兑换券…说不定你还花了一番力气才弄来。好吧，这是你今年的酒杯。$B$B不过我猜我应该还会常常再看到你。无论如何，要是想兑换啤酒节奖章，你找我就对了…$B$B或他找我…$B$B噢噢喔…或是他…', '怎么啦宝贝?有东西要给我?', '', '去找丹莫罗的贝尔比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12194, '今年有没有纪念品？', '我们不仅供应美酒，还独家出售啤酒杯呢！瞧这些漂亮的杯子，非常具有纪念意义哦！这是一张礼品券。$B$B与美酒节营地背后的布利克斯谈一谈。他是个古怪的家伙，总是带着一副护目镜。他负责兑换礼品券，以及出售各类美酒。', '在美酒节营地背后的布利克斯·菲克维特处兑换礼品券。', '这是什么?酒杯兑换券?你喜欢喝酒吗?太棒了!我把酒杯给你以后，你就可以喝个痛快了!然后再多喝几杯。也许接着再多来几杯……跟着，重点来了，再回来找我。$B$B听着，我知道迟早你一定会再回来找我的。假如你想要兑换啤酒节奖品章的话，你就要回来找我。$B$B总而言之，这是你的酒杯，记得以后有需要的话再来找我。', '怎么啦宝贝?有东西要给我?', '', '去找杜隆塔尔的布利克斯·菲克维特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12195, '不速之“客”', '刚回来的那支狩猎队不只是带了些猎物回来。$B$B他们遇到了一个从丹厄古尔的铁矮人要塞中逃出来的受伤矮人。他也许可以提供一些我们需要的情报，但首先，我们得帮他退烧。$B$B一直以来，我们都是用附近森林里的银鬃雄鹿的角来制作药膏。如果你能帮我拿来足够多的鹿角，我就可以尝试用药膏来让我们的“客人”康复。', '将5根成熟的雄鹿角交给欧尼瓦营地的托尔玛克。', '这些应该够用了。让我们看看有没有效吧。', '你把角带来了吗?', '', '去灰熊丘陵找欧尼瓦营地的托尔玛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12196, '收集零件', '我们没有足够的时间来让我亲自铸造零件，不过东南部的丹厄古尔中的铸造厂一直在日以继夜的制造着魔像零件。$B$B我觉得你应该回到那里去，帮我取回足够多的零件，让我能够根据这份蓝图制作出一台魔像。$B$B那些零件可能散落在任何铁符文锻造师的工作场所里。$B$B快一点，$N。托尔玛克好像正准备找个借口来对我发脾气呢！', '将8个作战魔像零件交给欧尼瓦营地的勘探员罗卡尔。', '<洛卡用他的手背擦了自己的额头。>$B$B喔，感激圣光。他威胁我说在你回来之前都不给我东西吃。我们来整理一下这堆零件，看看能做出什么。', '你–你把–把魔像零件带回来没啊?', '', '去灰熊丘陵找欧尼瓦营地的勘探员罗卡尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12197, '我们有能源', '那么，我们现在有了一台魔像，但这还远远不能让托尔玛克满足。他并不知道这玩意并不是只要这么组装起来就能神奇地开始工作的！我们需要用能量晶格来驱动它。$B$B我潜入丹厄古尔的时候，曾记得是由符文铸造师杜拉尔和符文铸造师卡索恩来制作晶格的。我们需要从他们那里各取一个能量晶格，这样才能引导我们的魔像。$B$B你应该可以在丹厄古尔的中层本地找到他们，那两个家伙一直在他们各自的工作间里忙活呢。', '将杜拉尔的能量晶格和卡索恩的能量晶格交给欧尼瓦营地的勘探员罗卡尔。', '<洛卡从你手中接过了电池。>$B$B虽然能量不足，但是光是引导魔像是够的。虽然，他离能够上战场打仗还有好长一段距离。', '你拿到电池了吗?', '', '去灰熊丘陵找欧尼瓦营地的勘探员罗卡尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12199, '击败铁领主', '现在魔像的电量非常充足，可以用它来对付丹厄古尔的首领了。$B$B据我观察，丹厄古尔的铁领主弗雷哈默尔一直都由他的魔像保护，真可谓万无一失。$B$B他的魔像名叫“铁砧”，你可以通过破坏它来击破铁领主的防护罩——只要使用魔像的电磁脉冲能力释放能量流就行了。$B$B铁领主弗雷哈默尔通常都会待在丹厄古尔顶端的主车间内，监督着整个生产过程。', '使用你的作战魔像去打败铁领主弗雷哈默尔，然后向欧尼瓦营地的托尔玛克复命。', '勘查员履行了他的承诺?很好。我开始好奇，搜集来这铁块和偷来的建材是不是都能作成同样的东西。$B$B很遗憾，他对我们没有更多的用处了。', '拜托告诉我成功了……', '', '去灰熊丘陵找欧尼瓦营地的托尔玛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12200, '翡翠龙泪', '现在，能使凋零药剂进入惰性状态的催化剂已经研制成功了，触发设备也没问题，唯一剩下的课题就是找到一个合适的外壳来容纳这些危险的东西。$B$B在这里的西南方，龙骨荒野中部的海岸上有一处地方叫作翡翠巨龙圣地。你可以在那里找到由绿龙的眼泪凝结而成的固体结晶。虽然具体原理我不甚了解，但我知道这些龙在死前尤其喜欢掉眼泪，所以……采集方法你了解了吧。$B$B立刻转至翡翠巨龙圣地，收集那些龙的眼泪。', '怨毒镇的首席药剂师米德尔顿要求你收集8份翡翠龙泪。', '我坚信荒疫可以进行实测了。巧合的是，惊惧城塞–纳克萨玛斯，也正在进攻温特加德要塞。它在温特加德之上，凌空而起，唤醒活死人，渴望着克尔苏加德赋予的命令。$B$B想当然尔，联盟军队人力和火力都远远不及他们。死在温特加德墓冢的人们被唤醒，渴望新鲜的血肉!$B$B也许我们可以让他们尝一口荒疫，不错吧?', '很幸运，我们的附近有很多翡翠龙之泪的残留，要不然，我就要派你去菲拉斯了。', '', '去龙骨荒野找怨毒镇的首席药剂师米德尔顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12201, '监工的制服', '看来这个洛肯是铁矮人战争机器的幕后首脑。$B$B只有最高等级的铁矮人才可能见到他，所以我们得把你伪装成一个监工，以查明他们究竟在谋划些什么。$B$B我有一个计划，但你得给我弄一些东西回来。$B$B在东南方的丹厄古尔找到一名铁符文监工，干掉他，然后把他的制服带回来。', '将监工的制服交给欧尼瓦营地的斥候沃塔肯。', '这应该有用，但是还有问题，你其它部份的伪装。就算是那些蠢翻天的金属矮人，也还是能发现只穿制服的冒充者。', '你拿到制服了吗?', '', '去灰熊丘陵找欧尼瓦营地的斥候沃塔肯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12202, '活灵活现', '现在我们要完善一下伪装，让你看上去跟那些铁矮人一样讨厌……$B$B最好的办法，就是按照真正的铁矮人那丑陋的容貌制作伪装。$B$B在托尔玛克的探险队发现那个勘探员时，他们拿走了他的照相机。我想现在我们有机会用到它了。$B$B带上这东西转至丹厄古尔，打倒一些铁矮人，趁他们不能行动的时候用这个照相机记录他们的外貌。等你有了足够的样本以后，把它拿回来给我。', '转至丹厄古尔，使用罗卡尔的照相机拍摄8张铁矮人的照片，然后向欧尼瓦营地的斥候沃塔肯复命。', '这些就够了，以加尔鲁什之名，这些家伙真是丑翻了。', '你拿到照片了没?', '', '去灰熊丘陵找欧尼瓦营地的斥候沃塔肯。', '拍摄铁矮人的照片', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12203, '洛肯的命令', '你的监工伪装包已经准就绪当了。等你穿上它的时候，尽量不要恶心得呕吐出来。我努力地让它显得尽可能真实。$B$B带上伪装包转至东南方的丹厄古尔，用它来伪装你自己，然后前去城市中层最东面的建筑物。$B$B在那里，你应该可以找到铁领主和监工接收洛肯命令所用的设备。伪装之后激活它，截获一切你所听到的情报。', '伪装成铁符文监工，从洛肯那里截获情报，然后向欧尼瓦营地的斥候沃塔肯复命。', '他是说要挑起泰坦创生种族势力间的内战?为什么泰坦城市奥杜亚对他如此重要?我猜这就是库伦和他的巨人所希望阻止的。$B$B我想我们正好处在一个可以阻止巨人彼此征战的位置上，但我们也可以找出方法来利用这个情况。我得马上通知我们的首领。', '你从洛肯那里知道了什么?', '', '去灰熊丘陵找欧尼瓦营地的斥候沃塔肯。', '截获洛肯的指令', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12204, '以洛肯之名', '铁矮人是我们在诺森德最难缠和最讨厌的敌人之一。无论我们走到哪里，他们都以洛肯的名义来和我们交战。$B$B我们必须知道这个洛肯到底是谁？他们的目的是什么？我想也许这里的当地人能给我们答案。$B$B这里东北面的红木商栈中有个名叫休·格兰斯的人类商贩。再往东走，你可以在泰塞斯废墟找到一个名叫加弗洛克的石巨人。向他们询问关于这个洛肯的事情，他们应该知道一些有用的信息。', '与休·格兰斯和加弗洛克谈谈有关洛肯的事情，然后把你的发现汇报给欧尼瓦营地的斥候沃塔肯。', '他是铁矮人的幕后主脑?我们要查出他究竟指使了丹亚戈的铁矮人做了些什么。', '你找到了什么?', '', '去灰熊丘陵找欧尼瓦营地的斥候沃塔肯。', '询问休·格兰斯', '询问加弗洛克', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12205, '通缉：血色先锋军', '根据高级执行官乌洛斯的命令，对于非法组织“血色先锋军”的所有成员格杀勿论。$B$B如果你被血色先锋军俘虏，等待你的只有死亡，甚至更糟的结局！$B$B按照高级执行官乌洛斯的话来说：“用他们的鲜血染红这片雪地吧！”', '消灭20个血色先锋军的成员，然后向怨毒镇的高级执行官乌洛斯汇报。', '非常好，$r，我相信你的屠杀充满了狡刽凶残?$B$B瞧瞧，我可以从棺材里面提供你什么奖励…呃，抱歉，我指的是金库。', '不要浪费我的时间，$g孩子:女孩;，还是，你已经完成了我对血色先锋军的报复行动?', '', '去龙骨荒野找怨毒镇的高级执行官乌洛斯。', '消灭血色先锋军成员', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12206, '测试药剂', '你看过那道通缉令了吗？$B$B高级执行官到底在想些什么？！$B$B<薇吉环视四周，然后继续压低音调。>$B$B我们不能就这样让那些血色先锋军的蠢货们一次次地被他们的牧师复活，或者更糟——被复活成天灾士兵。$B$B不，我完全赞同你的想法，我们得做点什么。$B$B我正好有样东西。拿上这个我们最近研制出来的凋零药剂，去泼在旁边的士兵身上。$B$B清洁溜溜，不会再有反复跳起来给我们找麻烦的敌人。', '怨毒镇的药剂师薇吉·莱文要你把药剂泼在血色先锋军士兵的身上。', '什么鬼东西?!不可能!荒疫的制作完美无瑕，它应该百分之百致命才对。$B$B<药剂师维琪.莱文拧着她自己的手，担忧的表情满布在那毫无生气的脸上。显然是非常挫折，她用愤怒的口问继续道。>$B$B这真的是怪得可以了。瓶子给我，$C。我可不要让人知道我是那个毁掉一切的药剂师!', '你做到了吗?$B$B嘿，我忘了告诉你最好不要让那东西碰到你!那东西很麻烦，而且一旦碰到就洗不掉了，更别提你要花几辈子的时间治疗你身上那冒泡的疹子。', '', '去龙骨荒野找怨毒镇的药剂师薇吉·莱文。', '测试凋零药剂', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12207, '沃达希尔的陨落', '很久以前，强大的德鲁伊们在这里的东北方种下了一棵树。$B$B这棵树被称为沃达希尔，它曾是诺达希尔的继承者……一棵世界之树。但不知道为什么，等沃达希尔完全长成之后，德鲁伊们却决定要将它摧毁。$B$B$N，从我们来到这里开始，大地就在向我们倾诉，它的痛苦来自于沃达希尔的遗骸所在的位置。$B$B堕落的软泥怪在那些地方徘徊。去取一些软泥怪的样本回来给我，这样我们才可以开始治愈这片土地。', '征服堡的风之先知希尔·灰角希望你转至沃达希尔之臂、沃达希尔之心或沃达希尔之泪，从熵能软泥怪那里取回6份软泥怪样本。', '这份黏液充满着黑暗的邪恶，比它巨大的形体所能显示的还要古老。这片大地保有着这股邪恶刚诞生时的记忆。$B$B$N，我们要发掘更多。', '$N，你拿到样本了吗?', '', '去灰熊丘陵找征服堡的风之先知希尔·灰角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12209, '夺取装备', '啊，很好，新人。你想证明自己的能力吗，新人？$B$B血色先锋军，也就是血色十字军中最狂热的那些成员，就盘踞在我们的南面。如果我们想要跟他们一决高下，就需要大量的装备和武器，而我在短期内想必是打造不出这么多的。$B$B为什么我们不去夺取他们的武器装备呢？$B$B换句话说，为什么你不去呢？', '怨毒镇的军需官巴莱特要你去夺取8件血色先锋军护甲和8件血色先锋军武器。', '你身上的菜虫少了一点，新面孔。$B$B还不错，这些我都收下了。我该怎么称呼你，$C?', '新面孔，只要你偷得来铠甲和武器，我就全部收下。$B$B虽然这些装备的质量比不上我锻造的，总是聊胜于无。', '', '去龙骨荒野找怨毒镇的军需官巴莱特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12211, '确保他们不再站起来！', '我真是搞不明白。凋零药剂明明应该有效的啊！$B$B不过现在也不是讨论这个的时候。$B$B<药剂师显得轻松了一些。>$B$B虽然由于奇怪的原因，它对血色先锋军不起作用，但是我们仍然要想办法阻止他们继续被牧师复活。$B$B我又想到一个办法，只要没有了佩戴的血色之印，他们就没法被牧师找到了。$B$B$N，带上一盒我的老鼠，把它们拿到新壁炉谷去，它们经过训练，可以准确地找出印记。', '怨毒镇的药剂师薇吉·莱文要你转至新壁炉谷，在15个倒下的血色先锋军成员那里使用她的老鼠箱。', '喔，甚好甚好!我一度还在考虑是不是应该先在某个家伙身上试试看这些老鼠究竟有没有效果。$B$B终究是有进展了!', '嗯?我猜你搞定了?$B$B不要告诉我他们还有某种防护措施防止尸体被老鼠吃掉?!', '', '去龙骨荒野找怨毒镇的药剂师薇吉·莱文。', '处理血色先锋军成员的尸体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12212, '补充食物', '你好啊，$c。$B$B这里的长官说部落掠夺了我们的仓库，剩馀的食物储备已经岌岌可危了。$B$B毫无疑问，我们会让这群混蛋们付出代价，但首先得把我们的注意力集中在食物的重新储备上。我的手下正在尽全力补充食物，但如果我们想要避免一场危机的话，就需要每个人都身体力行地出一份力。$B$B依你的能力，去周围猎杀些鹿肉回来应该没什么问题吧。祝你狩猎愉快！', '琥珀松木营地的护林主管安德霍尔希望你能去猎杀耸角雄鹿，并收集8份肥美的鹿肉。', '这真是上等的肉哇!', '狩猎顺利吗，$r?', '', '去灰熊丘陵找琥珀松木营地的护林主管安德霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12213, '地下的黑暗', '沃达希尔被某些……黑暗的东西笼罩着。在德鲁伊决定摧毁它后，它的空壳依然在向地底深处扎根。$B$B我希望你能转至北方那三处树干破裂的位置，尽可能地深入地下。$B$B等你进入地下以后，使用这枚宝珠来读入该本地周围的能量特征。这样才能让我知道沃达希尔身上曾经发生过什么，以及为什么它没有成为一棵世界之树。', '征服堡的风之先知希尔·灰角希望你转至沃达希尔之臂、沃达希尔之心和沃达希尔之泪，然后在地表之下使用地占师的宝珠。', '这颗宝珠…被一种纯粹的邪恶力量…污染了。$B$B无论我能从这股力量中了解什么，有一件事情是可以确定的，我必须马上摧毁这颗宝珠。这腐化的力量太强大了。', '$N，完成我交付予你的任务了吗?', '', '去灰熊丘陵找征服堡的风之先知希尔·灰角。', '在沃达希尔之心下方使用宝珠。', '在沃达希尔之臂下方使用宝珠。', '在沃达希尔之泪下方使用宝珠。', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12214, '补充坐骑', '你好啊，$g先生:女士;。我是汉瑟·鲍尔，很高兴见到你。$B$B高级执行官来到我这里对我说：“汉瑟,我希望你能给我们弄些新的坐骑。”$B$B他以为这些恐惧战马是哪来的？地里长出来的吗？$B$B<汉瑟低声地说>当然如果你能找到马墓地的话，它们的确是地里长出来的……$B$B但我们并没有那么好运！所以你要做的就是转至南面的新壁炉谷，击败那些骑士，拿上他们的马鞭，然后跳上血色先锋军战马。$B$B你可以骑马回到我这里，把它们的缰绳交给我就行了。', '怨毒镇的汉瑟·鲍尔要你牵回3匹血色先锋军战马，并将战马缰绳交给他。', '啊，没有什么比做好工作更令我开心的了。$B$B你为我们带来那些马匹，可是替毒怨之地帮了一个大忙，$C。', '我真的很高兴你回来了。但我想我得亲自到底下去凑齐那些牲口。', '', '去龙骨荒野找怨毒镇的汉瑟·鲍尔。', '牵回血色先锋军战马', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12215, '你死我活！', '所谓福无双至祸不单行……$B$B由于现在的食物危机，我们发现自己在跟当地的座狼争夺食物。情况也越来越严峻了，我担心如果我们不能马上解决这个问题的话，很快就没有东西可以去狩猎了。$B$B去森林里转转，$r。杀死你所找到的每一条灰雾座狼。最近有报告称它们在西边那条河流附近活动。', '琥珀松木营地的安德霍尔希望你能在灰熊丘陵找到并杀死6条灰雾捕猎者。', '干得好，$C，如此一来应该能确保这些野生动物能适得其所–我们营火上的烤肉架!', '我相信，森林里猎食的座狼少了一些，是吧?', '', '去灰熊丘陵找琥珀松木营地的护林主管安德霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12216, '猎熊！', '通过所有人的辛勤努力，现在食物已经开始有所盈馀了，不过离我们的目标仍然很远。我们需要更多的肉，很明显仅靠当地的鹿肉是远远不够的。$B$B恐怕你需要把注意力放在更危险的猎物上……对，灰熊。这个地区因它们而得名。它们的数量非常多，而且被河里的鱼喂得膘肥体壮。$B$B多加小心，$c！', '琥珀松木营地的安德霍尔希望你从灰熊丘陵的灰鬃熊身上收集8块灰鬃熊肋排。', '非常优秀!$B$B我们的库存近乎补足了。$N，你的工作完成了。', '望风披靡的$C回来啦!', '', '去灰熊丘陵找琥珀松木营地的护林主管安德霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12217, '鹰的眼睛', '嗯，$n。我们终于知道部落是怎么发现我们那些隐蔽的食物仓库的了。原来他们的探子就是周围那些看似悠闲的鹰。利用鹰的视界，他们就能有效地暗中监视我们的一举一动。$B$B根据长官的命令，我们必须猎杀这些高贵的鸟类，以挫败敌人的阴谋。', '琥珀松木营地的安德霍尔希望你去消灭5只白肩鹰，然后向他复命。', '我懂，这是个哀伤的任务，但是，少了敌人在我们头上的眼线，我们终于能高枕无忧了。', '$C，你的任务完成了吗?', '', '去灰熊丘陵找琥珀松木营地的护林主管安德霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12218, '传达好消息', '在我让你带着好消息转至玛菲奥斯博士那里之前，你还得再去对这种凋零药剂执行一次简单的实地测试，看看我新做的调整到底效果怎样。$B$B暮冬城的旧城区中有无数不停涌出的亡灵，它们是最好的实验材料。你可以直接在东门那里征用一辆车，然后开着它一路向东北方沿着复仇小径冲过去，一直杀到暮冬城东南城墙边的双塔边上。然后呢，你把炸弹向里面那堆亡灵那里一丢，看看结果如何，直接向我汇报就可以了。', '怨毒镇的首席药剂师米德尔顿要求你使用被遗忘者雕零战车上的雕零炸弹，在腐臭平原外围消灭30名饥饿的死尸。', '投下炸弹也许帮助了联盟…稍稍惹怒了我，但我仍要宣布，实测任务终告成功!下一站:阿格玛之锤!', '这项测试会是一连串试炼的最后一个，$N。', '', '去龙骨荒野找怨毒镇的首席药剂师米德尔顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12219, '倒下的世界之树', '很久以前，我的祖先在灰熊丘陵中部种下了一棵树。$B$B他们将它称为沃达希尔，它曾被认为是诺达希尔的继承者……一棵世界之树。$B$B不知道什么原因，在沃达希尔完全长成之后，他们却决定将它摧毁。它巨大的树干被劈成三段，躺在北边的森林里。$B$B树干接触到地面后开始腐烂，肮脏的软泥怪开始在那里蠕动。给我带些软泥怪的样本回来，这样才能开始我的工作，拯救痛苦的大地。', '琥珀松木营地的圣职者塞瑞恩希望你转至沃达希尔之臂、沃达希尔之心或沃达希尔之泪，从熵能软泥怪那里取回6份软泥怪样本。', '$N，软泥怪并不自然。它的天性是腐化与…邪恶。$B$B我们一定要找出更多。', '$N，你收集完样本了吗?', '', '去灰熊丘陵找琥珀松木营地的圣职者塞瑞恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12220, '黑暗的影响', '沃达希尔倒下之后，它的空壳仍然在向地底深处扎根。$B$B我希望你能转至北方那三处树干破裂的位置，尽可能地深入地下。它们就在灰喉堡的西边。$B$B等你进入地下以后，使用这枚宝珠来读入该本地周围的能量特征。如果我们要治愈这片土地，就必须首先查明这棵世界之树为什么会突然陨落。', '琥珀松木营地的圣职者塞瑞恩希望你转至沃达希尔之臂、沃达希尔之心和沃达希尔之泪，然后在地表之下使用地占师的宝珠。', '宝珠里的能量…异常强大…$B$B一股黑暗的力量在沃达希尔残\r\n株\r\n的附近污染了地面。我们需要更深入的调查。', '$N，完成我交付予你的任务了吗?', '', '去灰熊丘陵找琥珀松木营地的圣职者塞瑞恩。', '在沃达希尔之心下方使用宝珠', '在沃达希尔之臂下方使用宝珠', '在沃达希尔之泪下方使用宝珠', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12221, '被遗忘者的凋零药剂', '我准备了一只包裹，你必须立刻把它交给阿格玛之锤的辛塔尔·玛菲奥斯博士。包裹的内容包括凋零天灾样本的最终版本，配制及使用说明书，以及试验体的组织样本。$B$B阿格玛之锤就在龙骨荒野的西部。到了那边以后，只要在平原上寻找那种黑色的、棱角分明的兽人风格建筑就可以了，那就是阿格玛之锤。', '将被遗忘者的凋零药剂交给阿格玛之锤的辛塔尔·玛菲奥斯博士。', '<辛塔尔.玛雷菲尔斯医生端详着包裹的内容物。>$B$B无与伦比啊!完美的说明书!$B$B$N，这是你的酬劳。你的所见所为请保密，这份工作都是机密–所有发布的消息都只是最基本的。', '你天杀的也该来了吧!', '', '去龙骨荒野找阿格玛之锤的辛塔尔·玛菲奥斯博士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12222, '缚焰者的秘密', '就在我们跟部落僵持不下的时候，维库人的掠龙部族又不安分起来。他们在南边海岸旁的沃德伦村集结了大量的兵力。$B$B据说村里那些最强大的战士还被授予了一种灌入火焰能量的护符，这使得他们可以驾驭狂暴而凶残的始祖龙。如果这些始祖龙能被我们所用，那么我们就可以解决沃德伦方面逐渐加剧的威胁。$B$B负责为战士们制作这些护符的是掠龙缚焰者，杀死他们，把护符抢回来。', '将3枚烈焰能量护符交给琥珀松木营地的伐木工德拉克。', '只要咒符在手，元龙将无条件服从你。当族长发现你控制了他的元龙，我等不及要看他脸上的表情!', '咒符你收集好了吗?', '', '去灰熊丘陵找琥珀松木营地的伐木工德拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12223, '先发制人', '最近南边的维库人村落沃德伦内似乎有着大量军事活动的迹象。托瓦德·埃里克森领主和他手下那群侍卫正在筹备战争，可我们的人大多数都疲于应付部落的背叛，无暇南望，琥珀松木营地危在旦夕。$B$B必须向那群掠龙维库人显示联盟的实力，让他们知道我们不是什么软柿子。$B$B立刻转至南边海岸上的沃德伦，杀死你看到的所有侍卫。这样一来，如果他们再想要趁我们和部落冲突之时渔利，也会先称称自己的分量。', '消灭12个掠龙侍卫，然后向琥珀松木营地的伐木工德拉克复命。', '做得好，$N。我们必须进行下去，并且维持优势。', '事情办妥了吗?', '', '去灰熊丘陵找琥珀松木营地的伐木工德拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12226, '种子穿肠过……', '我们必须赶快行动起来，$r！我们不能冒这个险，让这些珍贵的种子被完全消化掉。现在就得把它们弄出来。现在！$B$B快去这里西面的河岸边寻找一些黑根草，我会帮你制作一瓶泻药来帮助你完成工作。$B$B赶快！记住，这都是你自找的……', '琥珀松木营地的安德霍尔要你去收集5份黑根草杆。', '这些刚刚好……$B$B<安德豪尔灵巧的揉拧黑根茎，并将黏滑的汁液收集进一个小瓶子里面。>$B$B好了，接下来要办正事了。', '你找到黑根茎了吗?', '', '去灰熊丘陵找琥珀松木营地的护林主管安德霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12227, '尽你的职责', '好吧，$c。就是这个了。$B$B它非常有效，所以在你进厕所前不要使用它。$B$B现在帮我把那些种子弄出来！', '琥珀松木营地的安德霍尔希望你在附近的厕所里喝下安德霍尔的泻药，以此来取回还未消化掉的琥珀种子。', '怎么，$N?拉得顺利吗?$B$B嗯，看来我们的时机刚刚好…', '$r，准备把种子给我了吗?', '', '去灰熊丘陵找琥珀松木营地的护林主管安德霍尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12229, '可能的关联', '不久以前，我们派了一支探险队前去东面调查，在那里他们受到了疯狂熊怪的袭击。一名幸存者向我们描述，那些被杀死的疯狂熊怪的尸体流出了一种黑暗的粘液物质。$B$B数千年以来，这个地区的熊怪一直崇尚和平。熊怪的异常行为很有可能和我们先前发现的黑暗能量有关系。$B$B给我带些熊怪的血样回来。你可以在东面的怒牙神殿和心血神殿找到它们。', '征服堡的风之先知希尔·灰角要你从心血神殿和怒牙神殿的熊怪身上收集8份疯狂熊怪的血液。', '血液里的腐化与稍早你得到的黏液是一样的…$N，这可不是好兆头。', '你得到血液样本了吗，$N?', '', '去灰熊丘陵找征服堡的风之先知希尔·灰角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12230, '收取炸弹', '我被指派去摧毁血色先锋军的弩炮。但不幸地是，药剂师和我在资源分配问题上有分歧，所以我没有任何可用的东西！$B$B这里的东北方是腐臭平原。在那里的熔炉和绞肉车附近摆弄器械的天灾攻城锻造师简直就是破坏的代名词。$B$B对我们来说幸运的是，他们的爆炸品扔得满地都是。$B$B我希望你能帮我把它们拿回来，不管是地上还是从那些攻城锻造师身上。', '怨毒镇的亡灵卫兵莫德尔要你收集6颗攻城锻造师的炸弹。', '<亡灵卫兵莫尔德期待着你的到来，搓摩着他的双手。>$B$B非常好。他们的失败就是我的…我们的成功!$B$B你拿着这些东西一路上没有造成任何困扰吗?这些爆裂物有些看起来不太稳定，我虽然是不死生物，但是我把我的存在看得很重!', '你以为他们让我利用荒疫散布者，也许填充进一些污秽的东西然后毁掉这些弩炮…$B$B才怪，他们告诉我荒疫散布者只能用于某些特别的任务。$B$B随他们怎么说!', '', '去龙骨荒野找怨毒镇的亡灵卫兵莫德尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12231, '熊神的后代', '很可能灰熊丘陵的熊怪和沃达希尔一样被污染了。在这么多年来的和平共处之后，它们之间爆发了部族战争。$B$B他们在东边守卫的神殿是乌索克子嗣的家园。$B$B虽然熊怪被污染了，但是乌索克的孩子——奥索恩和科蒂安有可能仍安然无恙。$B$B如果真是这样的话，去听听它们能告诉你些什么。', '征服堡的风之先知希尔·灰角希望你去跟怒牙神殿的奥索恩和心血神殿的科蒂安谈一谈。', '睿智的厄索克子嗣，他们的话语解释了当前我们所见的一切。', '你与厄索克的子嗣们交谈过了吗，$N?', '', '去灰熊丘陵找征服堡的风之先知希尔·灰角。', '奥索恩的故事', '科蒂安的故事', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12232, '炸毁弩炮', '终于，我们有机会去解决他们的攻城器械了！别把事情搞砸了，伙计。$B$B我在开玩笑呢。$B$B真的。$B$B$C，用这些炸弹去解决新壁炉谷的弩炮吧。$B$B我们要让皇家药剂师学会看看，我们是怎么以经典的方式来完成这一切的。根本不需要什么药剂！', '怨毒镇的亡灵卫兵莫德尔要你转至新壁炉谷，利用攻城锻造师的炸弹炸毁5台新壁炉谷弩炮。', '快乐的一天!$B$B既没占用到药剂师的时间和资源，就完成了这项任务，我相信这吸引了高阶执行官的注意力!$B$B不按牌理出牌，这就是我的做事态度。对，对啦，你也帮了点忙。$B$B来，如果我给你一些东西，能保证绝口不提你有参与此事吗?', '总有一天，我会成为亡灵卫兵之首的!$B$B总有一天……', '', '去龙骨荒野找怨毒镇的亡灵卫兵莫德尔。', '炸毁新壁炉谷的弩炮', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12234, '日常计划', '我需要知道新壁炉谷的那帮家伙到底想干什么。$B$B我希望你能去收集他们的命令书，这样我就能查明一切了。$B$B往南边走，在他们的修道院、兵营和海滩上寻找那些日常计划！$B$B哦，铁匠铺旁边的大型建筑物就是兵营了。', '怨毒镇的间谍女王瑞贝娅要你收集血色先锋军日常命令：修道院、血色先锋军日常命令：兵营和血色先锋军日常命令：海滩。', '所以，你还在发什么愣，$r?快把它们交给我!', '要是你花太长的时间，他们的每日计画就会不同，然后我们又得全部重来了。$B$B别花太长的时间!', '', '去龙骨荒野找怨毒镇的间谍女王瑞贝娅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12236, '乌索克，巨熊之神', '是时候了，$N。现在让我们来看看，我的努力是否能够帮助我们完成目标。$B$B拿上这些灰烬，去寻找科蒂安谈起的那个熊怪，图尔·怒爪，它就在乌索克的巢穴附近。你可以在灰喉堡的北面找到这座洞穴。$B$B说服图尔来帮助你，因为你需要一切你能找到的帮助。$B$B当你打败了熊神之后，在它的尸体上使用这些灰烬。$B$B即使它的肉身已经被摧毁，我们也必须拯救它的灵魂。', '征服堡的风之先知希尔·灰角希望你能在乌索克的巢穴的附近找到图尔·怒爪，在它的帮助下打败乌索克。然后在乌索克的尸体上使用净化过的沃达希尔的灰烬。', '<眼前的德鲁伊脸色苍白，眼神空洞地望着你。她留下了一个包裹以表示对你的凯旋表示知晓。>', '你回来了。成功了吗?', '', '去灰熊丘陵找征服堡的风之先知希尔·灰角。', '净化乌索克', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12237, '拯救暮冬城平民', '你可以用这只哨子召唤一头暮冬城狮鹫。骑上它转至东南方的暮冬城遗址吧——那里现在叫腐臭平原。到了那里以后，要注意搜索那些无助的暮冬城平民。当你发现目标的时候，就降低飞行高度，让狮鹫把他们提起来。把获救的村民带回飞行站来。$B$B那里到处都是天灾军团的成员，你一定要随时保持警惕。祝你好运！', '营救10名无助的暮冬城平民，然后向暮冬城的狮鹫指挥官乌瑞克复命。', '做的很出色，$N!有了这些救回来的百姓，我们可以使这座要塞重新运作了。', '$N，快!你得拯救那些无助的村民!', '', '去龙骨荒野找暮冬要塞的狮鹫指挥官乌瑞克。', '营救无助的平民', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12239, '新壁炉谷的卧底', '我在血色先锋军中安插了一个间谍。你把这些日常命令交给她，这样她就可以为我们策划下一步的攻击计划了。$B$B她的名字是斯古莉探员，她在魔法的作用下伪装成血色先锋军的墓地管理员。$B$B现在，快去把这些命令交给她，然后按照她的吩咐行事。墓地就在修道院旁边。', '将血色先锋军日常命令交给新壁炉谷的斯古莉探员。', '你从女间谍那儿带来了口信?$B$B<探员四顾以确保无人监视之后，放下了铲子。>$B$B把计画交给我看。', '<探员的眼睛上下打量着你，静静的指示你过来。>$B$B别毁了我的伪装，$C!', '', '去龙骨荒野找新壁炉谷的斯古莉探员。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12240, '解决方案', '我收到了亡灵壁垒的姐姐寄来的几桶白蚁，正好可以派上用场。$B$B新壁炉谷的木材场对我们来说是个麻烦，不过至今我们还没人能够去那里把他们的工头解决掉。$B$B我想如果你在他珍贵的木材上扔些白蚁的话，他肯定会气急败坏地冲出来。$B$B做好收拾他的准备了吗，$c？', '怨毒镇的药剂师薇吉·莱文要你利用莱温系列白蚁将工头卡列基引诱出来，然后杀死他。', '我就知道姊姊不会让我们失望的。$B$B干得好，$N。突袭军的伐木厂将会故障一阵子了，这表示不会有新的建筑物或者是弩炮。$B$B感谢你帮助我维系系列的名声。', '我好想我的姊姊，米克，希望她安好。', '', '去龙骨荒野找怨毒镇的药剂师薇吉·莱文。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12241, '摧毁树苗', '一定不能让熊怪成功，$N。假如最终的结果是被如此强大的腐蚀力量所侵蚀，那么即便有着善良的动机，也是毫无意义的。我们必须将树苗摧毁，因为它是黑暗力量的源头。拿上这根火炬，用它去点燃堕落的树苗，把它的灰烬给我带回来。$B$B当它被火净化之后，我将使用我的力量来净化它们所受到的污染。你需要那些灰烬来让乌索克的灵魂得到净化。', '征服堡的风之先知希尔·灰角希望你用翠绿火炬去焚烧沃达希尔的树苗。将沃达希尔的灰烬带回去交给风之先知希尔·灰角。', '$N，我不能跟你保证，但我将尽全力净化它们的。', '带来灰烬给我了吗，$N?', '', '去灰熊丘陵找征服堡的风之先知希尔·灰角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12242, '沃达希尔的种子', '我们必须得保证沃达希尔永远都不会再生。熊怪们肯定收获了它的种子。$B$B转至灰熊丘陵中部的灰喉堡，把你能找到的种子都拿回来。我会保证把它们全部销毁。', '征服堡的风之先知希尔·灰角希望你转至灰喉堡取回8颗沃达希尔的种子。', '感谢你，$N，我收下了。$B$B这些种子的腐化力量非常的危险，我必须即刻摧毁它们。', '$N，你获得沃达希尔种子了吗?', '', '去灰熊丘陵找征服堡的风之先知希尔·灰角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12243, '水火之灾', '我还有一件事要你去做。$B$B我把一些凋零药剂溶进了我那举世闻名的燃烧液里。我希望你能用它在罪人的愚行号的船帆上放上一把火。$B$B等火烧起来之后，水手们都会忙着去灭火，这样你就可以潜入船舱里面，去“拿回”船长的航海图了。$B$B那艘船就停在新壁炉谷南面的十字军码头。船长的房间就在下层甲板的第一层，楼梯的后面。', '龙骨荒野怨毒镇的药剂师薇吉·莱文要求你在罪人的愚行号的船帆上使用药剂师的燃烧液，将船帆点燃。$B$B在水手们忙着灭火的时候，转至下层甲板偷取舍雷船长的航海图。', '啊哈哈哈哈哈哈哈哈哈!$B$B没有了指针，看他们要往哪里跑?$B$B我看，血色先锋军就在还没开始之前，就已经结束了!多哀愁啊。$B$B哼哼。', '请你『别』告诉我船帆基于某种理由不能被燃烧之水点燃!$B$B我对于一再的测试感到厌烦了。', '', '去龙骨荒野找怨毒镇的药剂师薇吉·莱文。', '点燃罪人的愚行号的船帆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12244, '翻修伐木机', '听着，朋友，你为什么不卷起袖子，拿上扳手，立即开始工作呢？这里有很路复用作需要完成！他们要我翻新这些伐木机，把它们派往风险湾，而且交货时间理论上应该是昨天晚上……$B$B没有扳手？好吧，那么你会做什么呢？或许你应该去跟部落玩玩！$B$B去看看你有没有办法驾驶那些坏掉的伐木机回这里来修理。小心一点！它们的状态非常差！', '蓝天伐木场的塞尼普斯希望你将3台瘫痪的伐木机带回去交给他。', '<辛尼普斯吹起了口哨。>$B$B喔，她好美!我们会好好修理她的。$B$B如果你欠活儿干，去跟戈杜讲，然后去风险海湾，他们很缺人手。$B$B噢，当你到那达的时候，挑一台翻新伐木机使用钥匙，等着瞧这些宝贝能清理多少东西起来吧!', '没时间磨牙了，这些伐木机会是平衡联盟力量的关键!', '', '去灰熊丘陵找蓝天伐木场的塞尼普斯。', '运送伐木机', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12245, '毫不留情', '看样子，我们有更多蠢货需要派你去处理掉了。$B$B我的探子告诉我，我们有几个好市民被血色先锋军俘虏了。$B$B这可不行。$B$B回到新壁炉谷，干掉亡灵卫兵斯克尼德、首席抄写员巴里加、卫生设备工程师布尔克和司法官亚麦。$B$B从我所了解到的情报来看，他们分布在整个本地，但可以肯定的是，他们被关在笼子里面，等待着接受审问。$B$B去和他们谈谈，然后送他们上路！', '间谍女王瑞贝娅要求你去杀死亡灵卫兵斯克尼德、首席抄写员巴里加、工程师布尔克和司法官亚麦。$B$B完成任务后，向怨毒镇的高级执行官乌洛斯复命。', '什么?你认为我们该派你去救他们出来?$B$B是他们行迹败露遭致俘虏在先，我们何必多此一举?$B$B诺森德很冷，很残酷，年轻的$N。我推荐你适应它。', '轻而易举不是?你被送去杀掉四个无能的蠢蛋，他们随时可能泄漏你的\r\n秘\r\n密，快去解决这件事情。$B$B<高阶执行官罗思露出了邪恶的微笑。>', '', '去龙骨荒野找怨毒镇的高级执行官乌洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12246, '可能的关联', '居住在东边的熊怪比起我们曾经见过的熊怪来说更残忍、更具进攻性。我们的部队已经不止一次地受到它们的袭击，幸存者们无一例外地提到，有一股黑暗的液体从它们的尸体里流出。$B$B它们的情况可能与我们在沃达希尔遗骸找到的污染物有关。$B$B给我拿些熊怪的血样来。你可以在东面的怒牙神殿和心血神殿找到它们。', '琥珀松木营地的圣职者塞瑞恩要你从心血神殿和怒牙神殿的熊怪身上收集8份疯狂熊怪的血液。', '血液中显现的腐化和黏液中的腐化并无二致，对此我有不好的感觉。', '你得到血液样本了吗，$N?', '', '去灰熊丘陵找琥珀松木营地的圣职者塞瑞恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12247, '乌索克的孩子', '可以确定的是，灰熊丘陵的熊怪身上含有某种污染物质。在这么多年来的和平共处之后，它们之间爆发了部族战争。$B$B不知道被他们视为神明的熊是否同样也受到了污染。$B$B乌索克的两个孩子，奥索恩和科蒂安就居住在怒牙神殿和心血神殿，这两处地方分别在灰喉堡的南边和东南边。$B$B看看它们是否会告诉你一些东西。', '琥珀松木营地的圣职者塞瑞恩希望你去跟怒牙神殿的奥索恩和心血神殿的科蒂安谈一谈。', '睿智的厄索克子嗣，他们的话语解释了当前我们所见的一切。', '你和欧尔嵩、寇荻安讲过话了吗?', '', '去灰熊丘陵找琥珀松木营地的圣职者塞瑞恩。', '奥索恩的故事', '科蒂安的故事', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12248, '沃达希尔的树苗', '古时的德鲁伊似乎有充分的理由来摧毁沃达希尔。我们不能允许这些熊怪让它再生。$B$B但另一方面，我们需要使用树苗所包含的魔力来拯救乌索克的灵魂。$B$B拿上这根火炬，用它去烧毁树苗。灰喉堡就坐落在沃达希尔的老树根中，你可以在城堡中央找到那棵树苗。$b$b把沃达希尔的灰烬带回来给我，我希望等你用火净化它之后，我们也许可以用它的魔力来清除乌索克灵魂中的黑暗污染。', '琥珀松木营地的圣职者塞瑞恩希望你用翠绿火炬焚烧沃达希尔的树苗。将沃达希尔的灰烬带回去交给她。', '太好了!沃达希尔的魔力仍存留在这些灰烬里。也许厄索克还有希望。', '带来灰烬给我了吗，$N?', '', '去灰熊丘陵找琥珀松木营地的圣职者塞瑞恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12249, '乌索克，巨熊之神', '是时候了，$N。拿上这些灰烬去寻找科蒂安谈起的那个熊怪。如果它去寻找乌索克的话，那么它应该就在乌索克的巢穴附近，也就是灰喉堡的北面一带。$B$B你需要他的帮助，因为仅凭你一个人是不能打败乌索克的。$B$B等你打败了乌索克之后，用这些灰烬来净化它的灵魂。只有到那个时候，我们才能知道我们所做的一切是否全都是徒劳。', '琥珀松木营地的圣职者塞瑞恩希望你能在乌索克的巢穴的附近找到图尔·怒爪，在他的帮助下打败乌索克。然后在乌索克的尸体上使用净化过的沃达希尔的灰烬。', '<眼下的德鲁伊脸色苍白，眼神空洞的望着你。她留下了一个包裹以表示对你的凯旋表示知晓。>', '你回来了。成功了吗?', '', '去灰熊丘陵找琥珀松木营地的圣职者塞瑞恩。', '净化乌索克', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12250, '沃达希尔的种子', '我们不能让沃达希尔重新生长起来。如果熊怪曾经成功地让它重新生长过，那么它们就有可能再这么做一次。$B$B转至灰熊丘陵中部的灰喉堡，拿些沃达希尔的种子回来。我会保证把它们全部销毁。', '琥珀松木营地的圣职者塞瑞恩希望你转至灰喉堡取回8颗沃达希尔的种子。', '感谢你，$N。交给我吧。$B$B这些种子中堕落的力量非常危险，我必须即刻将之摧毁。', '$N，拿到种子了吗?', '', '去灰熊丘陵找琥珀松木营地的圣职者塞瑞恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12252, '拷问者里克拉夫', '够了！我希望你能终结我的人民所遭受的痛苦！$B$B血色先锋军的拷问者里克拉夫一直以来都用各种残忍的手段从俘虏口中榨取情报。我需要知道他们到底弄到了什么情报。$B$B我的线人告诉我，里克拉夫在先锋军兵营的地下室里，就在铁匠铺旁边。我会把我的权杖借给你，以确保你能完成我交代的任务。$B$B找到他，从他那里获取情报。', '怨毒镇的高级执行官乌洛斯要你对拷问者里克拉夫连续使用5次权杖，获得情报后回来报告。', '他们知道了这么多?还有，他说的那个见鬼的海军上将韦斯温到底是谁?!$B$B<高阶执行官咕哝着说他讨厌惊喜。>$B$B我们最好搞清楚，而不是在这里瞎猜。我希望你有留下你的…呃，我的印记。', '你带回什么消息?成功了，没错吧?', '', '去龙骨荒野找怨毒镇的高级执行官乌洛斯。', '从拷问者里克拉夫那里获取所有情报', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12253, '拯救暮冬城的平民', '这条路走到尽头就是暮冬城的广场了。那里过去是市民们举办各类大型活动和庆典的地方，现在则变成了战场，充斥着无数执迷于向生者复仇的危险亡灵。$B$B在广场周围的建筑里还有许多被困的平民，我们必须把他们救出来！我决定将这个任务拜托给你，$N，而且，也没有其它士兵可供你调配了，你得独立完成这个使命。快去解救我们的人民吧，立刻沿这条路转至广场，进入周边的建筑物内解救他们。路上如果有任何亡灵胆敢阻挡你的话，就消灭它！完成任务之后回来向我复命。', '暮冬要塞的高级指挥官哈尔弗·维姆班恩要求你救回6名被困的暮冬城平民。', '<海弗德为染病的人念了一段祷言。>$B$B你替圣光尽了一份力，$N。$B$B恐怕我们的工作才刚刚开始而已。$B$B<海弗德拿出一份文件。>', '你救出了我们受困的村民了吗?', '', '去龙骨荒野找暮冬要塞的高级指挥官哈尔弗·维姆班恩。', '营救被困的暮冬城平民', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12254, '祈祷之书', '这些计划昭示着即将发生一些大事。如果我们想要确定究竟会发生什么事情的话，就得赶快行动。$B$B不过首先，这些先锋军部队都有着某种奇怪的魔法保护。如果怨毒镇想要彻底解决他们，首先要做的就是查明是谁在背后释放魔法保护，并消灭他们。$B$B我注意到在新壁炉谷的另一侧，也就是伐木场后面，有一座教堂，那里的主教正在加强他对血色先锋军士兵的祝福。杀死他，把他的祈祷之书偷走。$B$B也许那本书能给我们提供一些线索。', '新壁炉谷的斯古莉探员要求你去弄到斯崔特主教的祈祷之书。', '你说书背上有个新写上去的祈祷文?$B$B<当你把最后一页翻出来的时候，探员越过你的肩头一瞥。>$B$B该死!那是高阶修士的笔迹!我敢拿你的命打赌。', '你拿到主教的祈祷书了吗?你在其中有发现任何不寻常之处吗?', '', '去龙骨荒野找新壁炉谷的斯古莉探员。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12255, '沃德伦的领主', '很好。你不仅抢来了这么多的护符，还削弱了沃德伦的防御力量。现在，我们要对他们的领袖托瓦德·埃里克森领主下手。$B$B这个领主有一只他宠爱到极点的座骑，是头名叫烈焰使者的始祖龙，它一直被领主的手下用非常粗重的铁链锁在村子的西面。有了这些护符，你就可以长时间地控制它，利用它对付托瓦德·埃里克森领主。$B$B嗯，确认你控制了烈焰使者以后，在沃德伦的那些塔楼顶层寻找领主，不要对他手下留情。', '利用烈焰使者击败托瓦德·埃里克森领主，然后向琥珀松木营地的伐木工德拉克复命。', '$N，做的好。我猜护林者们都想要尝试骑一骑元龙，但是我们承担不起掠龙氏族在灰熊丘陵创建据点的情况。要是部落有这么容易应付就好了……', '你击倒族长了吗?我们不能冒险让他继续掌权。', '', '去灰熊丘陵找琥珀松木营地的伐木工德拉克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12256, '缚焰者的秘密', '就在那群胆小如鼠的联盟杂碎向我们的阵地发动进攻时，东南面的维库人前哨站——沃德伦的掠龙氏族已经做好了战争的准备。虽然维库人不是我们在这里所面对的最强大的敌人，但我们必须要在他们能对我们造成真正的威胁之前消灭他们。$B$B他们最强大的战士能够骑着半驯服的始祖龙进行战斗，为了控制这种野兽，他们的缚焰者制造了强大的护符。你必须杀死他们并抢到护符，这样我们才能进行下一步的计划。', '将3枚烈焰能量护符交给征服堡的纳兹格利姆中士。', '有了这些咒符的力量，这些元龙将不得不臣服于你的命令之下，缚火者族长死期不远了。', '咒符你收集妥当了吗?', '', '去灰熊丘陵找征服堡的纳兹格利姆中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12257, '显示力量', '在东南面的沃德伦村中，维库人的领主正在积极备战。他们并没有大量的军队，但我们的部队过于分布，因此不可掉以轻心。$B$B我们不能让那个领主有机会对我们发动进攻，所以必须先发制人！如果你是一个真正的部落$c，就利用这个机会向他们展示部落的力量。$B$B干掉他们的卫兵，让这个掠龙氏族明白，部落并不是什么软柿子！', '消灭12个掠龙侍卫，然后向征服堡的纳兹格利姆中士复命。', '你完全做到了我要求的事。我们迫使掠龙者采取守势，很快的就是对付他们的领袖的时候了。', '你完成行动了没?', '', '去灰熊丘陵找征服堡的纳兹格利姆中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12258, '亡者的命运', '这条路走到尽头就是城镇广场，但那里已经完全被暮冬城平民的亡灵占据了！我们自己的墓地现在反而为天灾军团提供了无尽的士兵资源。别再有任何的仁慈了，$N。他们曾经身为人类时所拥有的一切情感与思想，恐怕都随着他们的生命一起消逝了，现在他们只是一群凶残狂暴的亡灵生物而已，存在的目的也只有一个：毁灭我们。$B$B你的任务就是立刻转至城镇广场，将那些妄图复仇的亡灵彻底毁灭。让他们安息吧。', '龙骨荒野暮冬要塞的指挥官莱诺尔·风矛要求你杀死15只复仇的恶鬼。', '如今他们也许能够安息，灵魂也将回归圣光。$B$B如今，我的悬念和祈祷转向了愤怒之门的弗塔根大人。我们必须坚守这里，始得争取更多的时间以击败巫妖王。温特加德不能被攻破!', '$N，把他们从悲惨的命运中解放出来!', '', '去龙骨荒野找暮冬要塞的指挥官莱诺尔·风矛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12259, '沃德伦的领主', '有了这些烈焰能量护符，我们终于可以挑战领主了。$B$B他有一只宠爱到极点的座骑，是头名叫烈焰使者的始祖龙，它一直被领主的手下用非常粗重的铁链锁在村子的西面。有了这些护符，你就可以长时间地控制它，利用它对付托瓦德·埃里克森领主。$B$B嗯，确认你控制了烈焰使者以后，在沃德伦的那些塔楼顶层寻找领主并消灭他。', '利用烈焰使者击败托瓦德·埃里克森领主，然后向征服堡的纳兹格利姆中士复命。', '残存的掠龙族人在你击败族长之后就没胆再挑战我们了。对敌人毫不容情 - 这就是部落的手段。', '你击倒族长了吗?', '', '去灰熊丘陵找征服堡的纳兹格利姆中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12260, '完美的伪装', '你可能在想我是怎么维持这个伪装的。我从间谍女王那里借来了一面魔镜。$B$B镜子里面的能量不多，不过我想对我们两个来说是足够了。过来，拿上它。我希望你用它来伪装成一个先锋军黑鸦祭司。$B$B速度快一点……我不知道在你拿着镜子的时候，我的伪装还能维持多久。$B$B还有，你要明白，你并不会立刻被伪装得天衣无缝，所以在我找到机会帮你之前，不要对它太过信任。', '新壁炉谷的斯古莉探员要求你去窃取先锋军黑鸦祭司的影像。完成任务之后，把女妖的魔镜还给她。', '不错，$C。现在镜子里禁锢了牧师的影像，我还有其它的事情得做。', '你没打破镜子吧?', '', '去龙骨荒野找新壁炉谷的斯古莉探员。', '窃取先锋军黑鸦祭司的影像', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12261, '无路可逃', '他们正在从我死去的兄弟们的骸骨中汲取能量……$B$B我不喜欢这个教派，可他们的肮脏行径更让我怒不可遏。我绝对不会对他们手下留情……不过话说回来，我一向也没对谁手下留情过。$B$B你要确保他们一个都跑不了。把这个毁灭结界放在圣地出口的尽头。在它完成充能之前，你要保护好它。', '将毁灭结界放在黑曜石巨龙圣地出口的尽头，雪花开始复盖道路的地方。保护它完成充能，然后向瑟里纳尔复命。', '很好。当他们因恐惧而逃跑的时候，那御符就会在那里为他们献上温柔的道别。', '你放好御符了没有?', '毁灭结界充能。', '去龙骨荒野找奈萨里奥之喉的瑟里纳尔。', '毁灭结界完全充能', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12262, '驱逐天灾', '一个也不能放过。$B$B外面那些下等的通灵侍僧和他们的骷髅仆从正在玷污我的土地。让他们从这片圣地上消失。', '到黑曜石巨龙圣地外面击败6个燃烧深渊通灵侍僧和10个冒烟的骷髅。完成任务后向瑟里纳尔复命。', '他们有没有可悲地求饶?软弱的东西。', '我看见你手上的血迹…那么，解决了吗?', '', '去龙骨荒野找奈萨里奥之喉的瑟里纳尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12263, '敌人的意图', '诅咒教派显然不会是仅仅为了汲取死龙的力量而来的。我大概知道他们想要什么，但我还是希望你去证实一下。$B$B我会把你变成这个死掉的通灵侍僧的模样，你要到洞穴深处中去确认他们闯入这处圣地的意图。我可以通过你的眼睛看到一切。$B$B你要小心，$N，哪怕受到一点儿伤害都会破除这个脆弱的伪装。', '等待瑟里纳尔将你变成燃烧深渊通灵侍僧，然后到奈萨里奥之喉深处去打探诅咒教派的意图。完成任务后向瑟里纳尔复命。', '我们是黑龙军团。几千年来，我们在艾泽拉斯的土地上散布死亡。破败的诅咒神教崇信死亡，我们很乐意答应他们的请求。', '我厌倦这场瘟疫。', '发现复活熔岩之龙的场所', '去龙骨荒野找奈萨里奥之喉的瑟里纳尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12264, '扫荡诅咒教派', '那个洞穴里挤满了诅咒教派的暴徒。对这种生物只有一个解决办法……你知道该怎么做的。', '转至奈萨里奥之喉，杀死3个燃烧深渊通灵师、6个冒烟的构造体和6个冒烟的恶鬼，然后向瑟里纳尔复命。', '听着他们的哀号…看着他们最后的生命从卑贱的躯壳消散…真是让我通体舒畅，可不是吗?我爱死这件事了。', '我忍不住想了解，他们究竟是太天真所以觉得我会容忍他们，抑或他们纯粹只是活腻了。', '', '去龙骨荒野找奈萨里奥之喉的瑟里纳尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12265, '污染的能量', '在你去洞穴侦察的时候，我感觉到那些符文里蕴藏着巨大的魔法能量。我不会让你去冒险抽出那些法力的……最直接的办法往往才是最有效的办法。$B$B去毁掉那些符文……把它们砸碎，绝对不能让诅咒教派的人得到里面存储的能量。', '进入奈萨里奥之喉，找到并砸碎8枚通灵符文。完成任务后向瑟里纳尔复命。', '很好，还有很多事情要做。', '能量都浪费在弱小和无用的人身上。$B$B除非找一个够资格拥有上天赋予生命和魔法的生物给我，否则在灭绝所有生物以前别跟我谈什么叫浪费。$B$B不过，别担心，我会等着。', '', '去龙骨荒野找奈萨里奥之喉的瑟里纳尔。', '摧毁通灵符文', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12267, '奈萨里奥的烈焰', '既然我们已经削减了教徒的数量，并瓦解了他们的力量，现在我们要做的就是摧毁堕落的源头。$B$B腐烂者洛森就在洞穴深处，他正试图把死去的黑龙复活成熔岩之龙。你必须转至召唤大厅，去净化黑龙的遗骨。防止它们再被人复活的唯一办法就是……用火。$B$B烧毁遗骨自然会引起腐烂者洛森的注意，你要确保他也被彻底消灭。$B$B这瓶药剂会帮你完成任务的。', '进入奈萨里奥之喉深处，使用奈萨里奥的烈焰净化召唤本地。当你吸引到腐烂者洛森的注意力之后，杀掉他，然后把瓶子还给洞穴外的瑟里纳尔。', '我子嗣的遗骨已经不再受这种侮辱。你为我付出了很多，就此而言，你应得到适当的奖赏。', '你是个十分有用的东西，$C。我欣赏你在这场净化行动中的表现。', '', '去龙骨荒野找奈萨里奥之喉的瑟里纳尔。', '净化召唤区域', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12268, '伐木机零件', '啊啊啊！这东西简直就是一堆垃圾啊！$B$B地精工程师留下了一大堆需要解决的问题，你不信吗？看看这个就知道了！要让这东西正常运转简直就是个奇迹。$B$B来帮我一把，怎么样？为了让这东西能动起来，我必须替换一些齿轮、链齿和弹簧。你应该可以很轻松地在木材切割场附近找到这些东西。', '蓝天伐木场的皮普斯维克希望你去收集4个凹槽齿轮、3个刻缺链条和2个高压弹簧。', '是的没错。这些应该能够搞定…$B$B好了。又一台伐木机能够参战了。谢啦，$N。', '收集到我要的零件了吗，$C?', '', '去灰熊丘陵找蓝天伐木场的皮普斯维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12269, '我们的矿洞？休想！', '那些该死的亡灵偷袭了我们！暮冬矿洞沦陷了。更糟的是，克尔苏加德的信徒把死难的矿工变成了天灾亡灵，并让他们用我们的矿石给他们提供原料！$B$B我们必须切断这条补给线，让死难的兄弟们得到安息。$B$B你现在就到东北方的腐臭平原去，进入暮冬矿洞，干掉那些矿工丧尸。把他们的矿工工作证带回来给我，以便我登记死难者。', '龙骨荒野的暮冬要塞里的李奥瑞克·冯·泽尔迪格公爵要你带回10张暮冬矿工的工作证。', '<李奥瑞克接过了名牌。>$B$B我会把这些交给我们的纪录员，并且通知他们家人这个不幸的消息。$B$B如果我们要在这里，以及愤怒之门获取终极的胜利，还有很多事情等着我们去完成。弗塔根领主需要我们的支持。', '你取回他们的名牌了没?', '', '去龙骨荒野找暮冬要塞的李奥瑞克·冯·泽尔迪格公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12270, '收割联盟', '看我的口型，$c——我需要那些伐木机！重要的是——我需要让它们远离联盟的控制！$B$B他们正在重新翻修伐木机，用来对我们在风险湾的弟兄们。现在我们要让他们自食其果！$B$B如果你看到伐木机，就帮我把它开回来！如果你看到伐木机上面有联盟狗，就干掉他们，然后把伐木机开回来！$B$B出发吧！', '蓝天伐木场的格利克希望你夺取3台伐木机，然后把它们交给他。', '做的好，士兵!$B$B现在拿着这把钥匙去冒险海湾。这可以让你开动一台翻新的伐木机对我们的敌人造成大混乱。$B$B喔对了，如果你想要抄捷径的话就跟达洛克谈谈!', '拿到我的伐木机了没有， $C?', '', '去灰熊丘陵找蓝天伐木场的格利克。', '运送伐木机', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12271, '强制魔棒', '里克拉夫手中的一根魔棒掉了下来。魔棒周身布满了魔法符文。$B$B是不是因为这个才让他在拷问囚犯的时候无往而不利？$B$B最好还是让高级执行官看一看这个。', '将拷问者的魔棒交给怨毒镇的高级执行官乌洛斯。', '你说乐卡夫特持有这柄权杖的吗?那么事情就说得通了。$B$B我认得它;我年轻的时候，在泰瑞纳斯国王的旧洛丹伦宫廷里担任拷问官。它被称做强制权杖。$B$B<高阶执行官为了某种邪恶的预感将双手绞在一起。>$B$B我有个主意，我们可以好好地利用这柄权杖!', '你从他们的拷问者手中拿到那柄权杖了吗?', '', '去龙骨荒野找怨毒镇的高级执行官乌洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12272, '流血的矿石', '在纳克萨玛斯入侵前不久，一名矿工发现了一块会流出粘稠液体的黑色矿脉。在疏散矿井人员的时候，因为场面混乱，我们不小心遗失了这种矿石的样品。现在天灾军团正在勘探这种矿石，想要把它应用到他们的死亡机器上去。$B$B暮冬矿洞就在东北方的腐臭平原，你必须返回那里，夺得这种未知矿石——这对我们的胜利至关重要！', '龙骨荒野暮冬要塞的攻城技师夸特弗拉什要你转至暮冬矿洞，取回10份奇怪的矿石的样品。', '也许这一刻，这一秒钟，就是形势逆转为对天灾军团不利的瞬间。你证明了你是联盟的英雄，至少在我的眼中如此，$N。$B$B现在你得让我独处一下。我需要一点时间来研究这个矿石，才能将杂质和弱点消除。$B$B继续你的任务，我的盟友。一旦我有任何发现，我会跟你联络的。', '你回收完奇怪的矿石样本了吗?', '', '去找龙骨荒野暮冬要塞的攻城技师夸特弗拉什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12273, '谴责', '是时候彻底挫败血色先锋军的士气了！$B$B我希望你带上这根魔棒，对他们的四个领导者使用——兵营楼上的指挥官乔丹，沙滩东南方斜坡上的炮兵队长泽尔哈特，铁匠铺里的铁匠古德曼，以及马厩里的兽栏管理员默希尔。$B$B让他们在魔棒的作用下公开谴责血色先锋军，然后干掉他们！', '怨毒镇的高级执行官乌洛斯要你对指挥官乔丹、炮兵队长泽尔哈特、铁匠古德曼和兽栏管理员默希尔使用强制魔棒。$B$B等他们在魔棒的作用下公开谴责血色先锋军后就杀掉他们。', '<你觉得你似乎看到罗思的脸上闪过一抹微笑，但很快就消失了。>$B$B你现在是我最欣赏的$C了，$N。如果愿意的话，我想你可以考虑以军官身份加入复仇之手。$B$B你可以先当个亡灵卫兵，然后几十年之后你就有资格当个副执行官了!$B$B不要?不要太急着回答…你仔细考虑考虑。', '怎么样?', '', '去龙骨荒野找怨毒镇的高级执行官乌洛斯。', '谴责并杀死指挥官乔丹', '谴责并杀死炮兵队长泽尔哈特', '谴责并杀死铁匠古德曼', '谴责并杀死兽栏管理员默希尔');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12274, '狼狈不堪', '我需要从高阶修士那里获取更多的情报，而且我们现在已经有了黑暗祭司的伪装，可以让你大摇大摆地与他谈话了。$B$B不幸的是，我们必须想办法让他和他的卫兵分开，否则你永远都不可能从他嘴里套出任何情报。$B$B<探员靠在她的铁铲上，思考了片刻。>$B$B我有办法了。当你在伪装状态下时，去修道院的顶端鸣响钟声。那样应该可以让修士的卫兵们跑出去集合，这样你就可以去下面和他谈谈了。', '新壁炉谷的斯古莉探员要求你转至修道院鸣钟，然后去和那里的高阶修士谈话，从他嘴里套出情报。', '到底发生什么事了?!$B$B他自个儿跳线走了?你确定你没有推他吗?$B$B<密探对你眯细了眼睛。>$B$B好吧，显然这儿发生的事比我们原先所想的还多得多。', '你找出什么了吗?你到底跟他说过话了没有?', '', '去龙骨荒野找新壁炉谷的斯古莉探员。', '拉响修道院的钟', '与高阶修士谈话', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12277, '阻绝邪恶', '如果你的心脏还能承受得了，思路也还清晰的话，就读下去吧。$B$B在矿井里，靠近工头的脚手架的地方，有一大堆炸药。你现在就去弄几捆炸药，然后到矿井的入口处去把它炸了。记住一定要把暮冬矿洞的上层入口和下层入口都炸掉。$B$B你不能给那些亡灵留下任何机会，绝对不能让里面的邪恶逃出来。圣光与你同在。', '找到暮冬矿洞炸弹，并用它把暮冬矿洞的上层入口和暮冬矿洞的下层入口炸掉。完成任务后，转至龙骨荒野的暮冬要塞，向攻城技师夸特弗拉什复命。', '朋友，他的死不会白费。史霖金因为这个消息送命，而这个消息却将成为击溃巫妖王的利器。我向你保证，我们会成功的。', '<刻闪点了点头。>$B$B他是个伟大的地精，我们之中最优秀的。永怀史霖金。', '', '去找龙骨荒野暮冬要塞的攻城技师夸特弗拉什。', '炸毁暮冬矿洞上层入口', '炸毁暮冬矿洞下层入口', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12278, '本月美酒俱乐部', '会员总是享有特权的。只要你成为“本月美酒”俱乐部的成员，就能在第一时间品尝到世间最棒的佳酿。$B$B将“本月美酒”俱乐部会员数据表交给铁炉堡石火旅店的拉尔金·雷酒吧。', '将“本月美酒”俱乐部会员数据表交给铁炉堡石火旅店的拉尔金·雷酒。', '你的数据看起来没有问题，$N，欢迎成为俱乐部的一员!$B$B每个月的第一天你会收到我们的邮件，如果你喜欢我们邮寄给你的酒，请来俱乐部，我们可以卖你更多。我们是很大方的俱乐部。', '你填妥会员表格了吗?', '', '去找丹莫罗的拉尔金·雷酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12279, '熊的美食', '谢天谢地，你回来了，乔伊！我还在担心是不是以后我和格里西达就再也见不到你了。$B$B你看，我正在做好吃的东西呢，但格里西达居然不感兴趣。$B$B她喜欢鱼，居然一大早就跑到东边的东风海岸去抓鱼了。虽然我也对吃的东西特别挑剔，可也没挑剔到她那个程度啊。看来只有使出我的必杀绝技，搞六条北地鲑鱼来满足她的舌头了。$B$B现在赶紧动身吧，乔伊……你也不想让女孩子等着吧？', '给红木商栈的休·格兰斯带去6条北地鲑鱼。', '你!你不是『瘸子』乔!', '如果你不快点，就不只她的肚子会咕噜噜的叫了…', '', '去灰熊丘陵找红木商栈的休·格兰斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12280, '修理伐木机', '明天中午之前要完成二十台伐木机！$B$B这个进度表是谁定的？都没人可以把这些废纸篓组装起来，别说是……$B$B如果我想要达成指标的话，就必须找个帮手。来帮我一下吧，我会和你分享我的酬劳……如何？$B$B我需要齿轮、链条和弹簧. 它们就散落在伐木机周围的地面上。', '蓝天伐木场的鲁尔兹希望你去收集4个凹槽齿轮、3个刻缺链条和2个高压弹簧。', '感谢，$N。那可以让我忙上一会了–至少忙到明天……$B$B这是我答应的现金。', '你把零件拿来给我了吗?', '', '去灰熊丘陵找蓝天伐木场的鲁尔兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12281, '天灾战争机器的奥秘', '虽然斯林奇的死令人伤心，但他的牺牲换来了更大的回报。我们应该为此感到欣慰。他的发现和你在矿井中的英勇表现，以及你带回来的矿石样本使我们进一步了解了天灾军团的战争机器。$B$B请把这个包裹交给高级指挥官哈尔弗·维姆班恩。里面有未知矿石的样本和我的分析报告。', '把夸特弗拉什的包裹交给暮冬要塞的高级指挥官哈尔弗·维姆班恩。', '<海弗德打开了包裹，阅读了分析数据。>$B$B我不是个科学家，$N，所以对于这份数据的贫乏了解请你见谅。那么，根据这份数据所说–假设我至少有着初出学塾的智力–我们仍然对天灾战争机器一无所知。唯一知晓的，就是天灾军利用这个恶毒的废铁制造攻城机具、护甲，和武器。$B$B<海弗德长长地叹了一口气。>', '$N，我听说你在矿坑中的英勇事迹了。', '', '去龙骨荒野找暮冬要塞的高级指挥官哈尔弗·维姆班恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12282, '往日的烙印', '往日的记忆一直盘踞在这片土地之上，$N。每晚，我似乎都能听到那些死者的哀号在诺森德回响，好像在召唤着我。$B$B阿尔萨斯在他所碰触过的一切事物上都留下了恐怖的烙印。在这里，只有枯萎与凋零能够留存于世。虽然挖掘那些往日的记忆是件很可怕的事，但这却很重要，因为我们只有深入研究过去发生的事，才能更清楚地了解我们所面对的敌人。现在已经到了让这些隐藏在深处的真相浮出水面、帮助我们取得胜利的时候了！$B$B首先，你必须从镇中的议事大厅里为我取回水晶球，$N。离开这座塔以后，直接向左转，然后沿路走到底，就可以抵达镇广场了。', '暮冬要塞的幻象师瑟里格要求你帮忙找回他的占卜宝珠。', '$N，做得很好。一如命运所预言的，你就是那位带领我们捱过艰困岁月的人。而现在，遥远的旅程正要开始。', '你找回我的占卜宝珠了吗?', '', '去龙骨荒野找暮冬要塞的幻象师瑟里格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12283, '寻找真相', '我们需要查明到底这里究竟发生了什么。我需要将军的日记。$B$B我相信你一定能在她的房子楼上的床头柜里找到它。就是教堂旁边那幢房子，穿过马厩和伐木场就到了。$B$B等你拿到了日记以后，把它交给怨毒镇的高级执行官。$B$B你只能以最直接的手段来做这件事，因为镜子的能量快要耗尽，只够供我使用了。$B$B<探员对你微笑着。>', '斯古莉探员要求你去获取阿比迪斯将军的日记，然后将它交给怨毒镇的高级执行官乌洛斯。', '该死的!为什么就不能带给我一些好消息呢?', '$N，时间也差不多了，你被什么事情给耽搁了吗?', '', '去龙骨荒野找怨毒镇的高级执行官乌洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12284, '穷追不舍', '我们在这里遭受了严重的人员伤亡，$r。$B$B唯一值得庆幸的是，他们的情况和我们差不多。我需要更多的部队，但我们的大部队被困在风险湾，所以我们现在多半只能靠自己了。$B$B不管情况变得多么糟糕，我们必须坚守阵地。这一本地珍贵的资源是部落在诺森德最终获胜的关键。$B$B我们必须在援军到达之前紧跟联盟的步伐。不要待在这里，去给他们点颜色看看。', '指挥官巴尔格克希望你在蓝天伐木场消灭15个联盟士兵或者联盟玩家。', '你说多少，十五个?很高兴听到这个消息，$C。$B$B顺利的话，你为我们争取了一些时间-我想，至少一天吧。$B$B这是你的报酬。', '$r，你武器上沾了联盟的鲜血吗?', '', '去灰熊丘陵找蓝天伐木场的指挥官巴尔格克。', '消灭联盟成员', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12285, '先发制人', '他们随时会大举进犯，$c。我命令你杀进去，取下阿比迪斯将军的首级！$B$B这并不是个简单的活儿……阿比迪斯周围肯定有很多卫兵。我推荐你带上几个伙伴一同转至。$B$B把她的徽记给我带回来，我会为了表彰你拯救怨毒镇的功劳，给你最完美的奖励。$B$B如果失败的话，就没必要再回来了！', '怨毒镇的高级执行官乌洛斯命令你将阿比迪斯将军的徽记交给他。', '让我们看看她们要怎么在没有头的情况下复活她!$B$B<高阶执行官的豪笑引来了一些侧目。>$B$B我本来担心你会让上将溜走的。今天，$N，你就是我们的$g英雄:女英雄;!收下奖励吧…这是你挣来的!', '我该告诉我的部队开始转至阿格玛之锤吗?$B$B还是你准备好杀掉大将军了?', '', '去龙骨荒野找怨毒镇的高级执行官乌洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12288, '力不能支！', '喂，$c！过来帮帮我！$B$B我们许多英勇的战士正在渐渐死去。如果不能及时让他们得到治疗，我们可能会连灰熊丘陵都一起失去！$B$B拿上这根止血带，在战场上的伤者身上使用它。$B$B赶快，$n！他们快要死了！', '蓝天伐木场的奥曼娜希望你在10名受伤的散兵身上使用急救止血带。', '喔!谢谢，谢谢你。$B$B你帮助我们捱过了另一天，也许还有一丝希望。', '治愈我们的伤兵了吗，$N?', '', '去灰熊丘陵找蓝天伐木场的奥曼娜。', '治疗受伤的散兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12289, '乘胜追击', '对于联盟来说，这真是个黑暗的日子。许多优秀的士兵阵亡，还有不少身负重伤的人已经奄奄一息了。我们唯一的安慰就是他们英勇奋战，消灭了大量敌人。$B$B由于大部队都在风险湾作战，我们只能独立迎敌。这一地区的资源对于联盟来说非常重要，它也许会决定我们与部落交战的成败。我们一定不能失败！！$B$B去吧，$n。在他们舔舐伤口的时候狠狠地打击他们。为你倒下的弟兄们报仇，让我们仍然能看到希望！', '哈斯曼中士希望你在蓝天伐木场消灭15个部落成员。', '干得好，$N。$B$B你为我们争取了些许时间，虽然看起来不超过一天，但无论如何，联盟感谢你的努力。', '$N，战况如何?', '', '去灰熊丘陵找蓝天伐木场的哈斯曼中士。', '消灭部落成员', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12290, '黑暗草', '这片海滩上游荡着成百上千个被诅咒的鬼魂。在生前，他们都是勇敢而高贵的联盟士兵，可死后，他们却遭受到了某种神秘的诅咒。在这诅咒的作用之下，他们被永久禁锢在这个世界中。或许，直到世界毁灭，他们才能得以解脱。必须要将自由还给他们！为此，我们首先得找到令他们如此痛苦的根源。$B$B你现在立刻转至东南方的埃尔德齐断崖，寻找一种名叫黑暗草的稀有草药。我可以用这种草药调配出一种药剂，它能使你暂时进入那个被遗忘的世界。快去采集吧。', '黎明河滩上的欧瑞克·图哈特要求你从埃尔德齐断崖上收集5株黑暗草。', '<欧利克拿走了阴郁草，并开始混合药剂。>$B$B$N，这不会花太多时间的。', '找回阴郁草了吗?', '', '去龙骨荒野找黎明河滩的欧瑞克·图哈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12291, '被遗忘的故事', '黑暗草药剂中的毒性会让你的意识变得朦胧，然后逐渐失去意识。这种毒性的强大力量甚至会欺骗你的灵魂，允许你短暂地进入死者的世界。$B$B成为灵魂之后，你必须立刻与遗忘海岸一带的鬼魂交谈，从他们那里问出令他们如此不安与愤怒的原因，然后回来告诉我。$B$B记住，$N，这些鬼魂都曾是联盟的士兵，你必须尊重他们，绝不可玷污他们的荣耀与尊严。$B$B拿着药剂，尽快转至南方的遗忘海岸吧。', '黎明河滩上的欧瑞克·图哈特要求你听取被遗忘的农夫、被遗忘的火枪手、被遗忘的骑士和被遗忘的步兵所讲述的故事。', '<欧利克的眼中充满了泪水。>$B$B他们不懂。全都不懂!他们相信阿尔萨斯会成为伟大的英雄，然而事实上，阿尔萨斯才是那个下令烧尽所有船只的人。是阿尔萨斯任由我们死在这片冰封的荒地上!$B$B<欧利克啜泣着。>$B$B王子舰队上的士兵中，仍有人这片寒冬中苟活下来。当我有机会和天灾军一战的时候，我还只是个孩子…就为了从这毁灭中拯救我们的家园。$N，我孤注一掷就为了这个目标。', '$N，我的阴郁草足够制作更多的药剂。', '', '去龙骨荒野找黎明河滩的欧瑞克·图哈特。', '询问被遗忘的农夫', '询问被遗忘的火枪手', '询问被遗忘的骑士', '询问被遗忘的步兵');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12292, '当地人的支持', '最近在灰熊丘陵这一带，我们和部落的军队进入了一个长期的对峙阶段。双方的军队无论是在数量上、士气上、装备上还是策略上都旗鼓相当，谁在任何一方面都不能取得优势。因此，这里的形势不可避免地陷入了僵局。$B$B好吧，至少是在今天早上之前如此。刚才，一些当地的猎人过来请求我们的援助，似乎是部落那边抢走了一些对他们来说很重要的东西……好像是某种宗教圣物的样子。$B$B我们得把这件东西抢回来，这样就能拉拢这些猎人加\r\n入联盟这边，从而获得战略上的优势。立刻出发转至征服堡西边的常青商栈，寻找一只雪松木箱。', '琥珀松木营地的杜蒙特中尉要你转至常青商栈夺回雪松木箱。', '锁住了，是吧?这看起来挺普通的。$B$B<都蒙特中尉摇了摇箱子，发出一阵嘎嘎作响的木头声。>$B$B我猜不要紧。如果这能够帮我们取得对付部落的刀剑，我甚至不在乎里面装的会不会是瘟疫的解药。', '你把箱子带来了，$N?', '', '去灰熊丘陵找琥珀松木营地的杜蒙特中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12293, '完成交易', '现在我们有了那些猎人想要的东西。是时候把他们全部拉到我们这边了。$B$B带着这只箱子到北边的白杨商栈，找一个名叫伊凡的猎人。$B$B如果一切顺利，那么这群猎人很快就将成为我们最好的斥候，为国王陛下的军队效力。', '将雪松木箱交给白杨商栈的伊凡。', '你成功了!你取回了天…你取回了部落从我们这里偷走的箱子。我们感谢你，$N。', '你有东西要给我们?', '', '去灰熊丘陵找白杨商栈的伊凡。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12297, '叛徒的名单', '你必须立即把我手里的这份名单交给高级指挥官哈尔弗·维姆班恩。他指挥的第七军团就驻扎在龙骨荒野东部的暮冬要塞里。$B$B如果这份名单上的叛徒进入了暮冬要塞……那就太可怕了。$B$B赶快，$N。把这份文件给西部卫戍要塞这里的格雷尔·岩锤看看，向他解释你的任务性质。他会派最快的狮鹫送你转至暮冬要塞！', '亚当斯上尉要你向西部卫戍要塞的格雷尔·岩锤出示联盟信函。', '<格锐尔把眼镜推到头顶然后详读文件，读完之后好奇的看着你。>$B$B我会让你骑我最快的狮鹫兽过去!这个消息一定要立刻送到高阶指挥官海弗德.龙祸手中!', '你好，$C。', '', '去嚎风峡湾找西部卫戍要塞的格雷尔·岩锤。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12298, '高级指挥官哈尔弗·维姆班恩', '<格雷尔把公函交还给你。>$B$B天空之歌会把你送往暮冬要塞，$N。我保证它将是你乘坐过的最快的狮鹫。现在就走吧！', '转至龙骨荒野东部的暮冬要塞，将联盟信函交给高级指挥官哈尔弗·维姆班恩。', '<高阶指挥官读完公文之后将之揉成一团。>$B$B你知道名单上的这些人在哪里吗?看看外面，就在前门附近。吊在拱门上面那些就是。$B$B食尸鬼的饵食…', '你手上拿着什么，士兵?', '', '去龙骨荒野找暮冬要塞的高级指挥官哈尔弗·维姆班恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12299, '北边的敌人', '很高兴见到你。传统而富有娱乐性的“消灭部落成员”活动让你们和我们达成了许多一致，这真是可喜可贺。$B$B其实这个镇子西边也有许多来自征服堡的劫掠者。不如你冲出去像对付野兽一样把他们清扫一遍？$B$B让我们看看我们的新盟友能做出多少实际行动来支持谈判桌上的努力。', '银溪镇的瑟尔基要你杀死8名征服堡劫掠者。', '不错，不错。你可能不像其它的家伙一样软弱。', '你解决那些部落混蛋了吗?', '', '去灰熊丘陵找银溪丘陵的瑟尔基。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12300, '勇气的试炼', '好吧，朋友。你的确帮了我们一两个忙，但这绝不是对勇气的真正考验。$B$B在我们这里，只有你亲自杀死某只强大的猎物，并把它的皮毛穿在身上时，人们才会承认你是一名伟大的猎手。$B$B<瑟尔基从鞘中抽出他的剥皮小刀递给了你。>$B$B那群胆敢进犯我们镇子的白痴兽人有个头目叫作博斯纳普，你可以在镇子西北边的一处营地里找到他。$B$B没错了，朋友，你要剥下那个混蛋的皮。', '在银溪镇西北边找到博斯纳普中士，以此通过勇气的试炼。', '住手，$N。派你来的人…你不该相信他们。', '银溪镇的居民…并非你表面看见的那样。', '', '去灰熊丘陵找银溪丘陵的被囚禁的猎户。', '勇气的试炼', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12303, '战争的开销', '<军需官低沉下声音轻声对你说。>$B$B$C，我需要你的帮助。我们的保险箱已经空了，因为天灾之门的库卡隆先锋营地拿走了我们的所有金币，以支持他们在那边进行的战事。$B$B不过，我听到传言说，东南面遗忘海岸一带的失事船只残骸中有着大量的宝藏。$B$B我们得马上行动，否则就没法对付那些血色先锋军了。你要知道，战争可并不便宜！', '怨毒镇的军需官巴莱特要求你去取回6份被遗忘的宝藏。', '<军需官倒抽了一口气，但随即眯细了眼睛打量你。>$B$B我相信你应该没有私藏任何财宝吧?在这毒怨之地存亡危急的时刻你不会这么自私吧?$B$B好了，我会分你一小部分的财宝。不多，但在这种时候，我们都得要做出牺牲。', '你摸来了多少联盟宝藏?', '', '去龙骨荒野找怨毒镇的军需官巴莱特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12306, '本月美酒俱乐部', '$n，所谓众人拾柴火焰高，只要你成为“本月美酒”俱乐部的成员，你和你的同胞就能品尝到世间最棒的佳酿。$B$B将“本月美酒”俱乐部会员数据表交给奥格瑞玛精神谷黑石南小屋的莱玛吧。', '将“本月美酒”俱乐部会员数据表交给奥格瑞玛精神谷黑石南小屋的莱玛。', '$N，你想加入我们的会员了吗?我们的福利很好，身为俱乐部的一员，我们一定给你最好的!$B$B每月的第一天会将啤酒寄发给你，想要更多，回来这里，我们保证让你有喝不完的啤酒。', '你填妥会员表格了吗?', '', '去找奥格瑞玛的莱玛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12307, '破狼草', '你有没有听说过一种名叫破狼草的植物？这种草非常非常可怕……它强大的繁殖与抢夺养分的能力会使我们所有的庄稼都绝收。$B$B我们上星期花了一整周的时间将这种草除光，可它们的根当前仍然还在土壤里，似乎又开始恢复生长了。$B$B虽然不是很急迫的事情，可这样一种顽强的植物生长在田地里实在是……灾难。村子附近到处都是残馀的草根，你是否能帮我们除掉它们呢？', '银溪镇的卡娅要求你拔出8株破狼草根。', '<卡特加紧张地从你身边退开。>$B$B谢谢你，$N。你身上没有祸狼根吧?我偶尔会…过敏。', '嗯，$C?', '', '去灰熊丘陵找银溪镇的卡娅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12308, '逃离银溪镇', '你……你不是他们的人？快！快把我放出来！$B$B我们必须马上逃往琥珀松木营地！一旦杜蒙特中尉发现这些家伙的真面目，就会夷平这个镇子！', '打开木笼，帮助联盟斥候逃出银溪镇。抵达琥珀松木营地后向杜蒙特中尉汇报情况。', '狼人。被诅咒的、见不得光的污秽狼人。$B$B是时候告诉这些当地人，我们文明人是怎么对付他们这种野兽的了。', '你回来了。我正替你担心呢，$N。', '', '去灰熊丘陵找琥珀松木营地的杜蒙特中尉。', '逃出银溪镇', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12310, '快速反应', '我们必须立刻对此作出反应与决断。我们一定要让那些野蛮人知道，绝对别想与我们为敌。$B$B斥候们已经找到了残馀的银溪镇猎人的位置……不过你要知道，这群家伙也绝对不愿意坐以待毙。他们当前十分高调地封锁了通向东南方的路……看来是想包围我们了。$B$B立刻转至林边哨站，处理掉他们。他们的头目据说是个叫弗拉德克的家伙……马上去搞定他。', '杜蒙特中尉要你转至林边哨站，杀死弗拉德克以及7名银溪镇猎人。', '这些陷捕者的下场很令人遗憾…折磨至死。我们本来能有更多可供战斗的人手的。$B$B希望这些可怜的混蛋安息。', '$N，解决他们了吗?', '', '去灰熊丘陵找琥珀松木营地的杜蒙特中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12311, '贵族的陵墓', '在这座墓穴冰冷的石墙内，埋葬着无数牺牲在诺森德的王公贵族与圣光教会的高阶神职人员。这些人生前的强大却在他们死后带来了麻烦，现在，有一名通灵领主被吸引到了这里，将他们的尸体不停转化为天灾军团的仆从。$B$B你必须立刻进入暮冬地穴的底部，杀死那个通灵领主阿玛里恩。中断这些邪恶行径的唯一希望就是此次突击了！$B$B此外，$N，你最好能仔细检查一下阿玛里恩的房间，留意一下其中是否有任何重要的情报。', '暮冬要塞的骑兵杜尔库要求你杀死通灵领主阿玛里恩。', '如果我们能阻挡外面天灾军的进攻，我们就能将援军送往弗塔根领主所在的愤怒之门。', '艾玛利恩死了吗?', '', '去龙骨荒野找暮冬要塞的骑兵杜尔库。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12312, '天灾的秘密', '这本长达数百页的魔典的每一页上，都用刀刻着一些奇怪的符号，还辅以数幅诡秘的图形。你完全看不明白这上面刻的是什么，但你的直觉告诉你：这一定是非常重要的情报。$B$B将这本书拿去给暮冬地穴外的骑兵杜尔库看看吧，他或许会对此有所了解。', '将血之魔典交给龙骨荒野暮冬要塞的骑兵杜尔库。', '不论这本书里藏有什么样的情报都是事关重大!我能够听见你逃跑时墓穴里传来的悲鸣哀嚎声!$B$B我们必须通知高阶指挥官!', '一本天灾军团的书?', '', '去龙骨荒野找暮冬要塞的骑兵杜尔库。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12314, '除掉佐娜船长！', '部落已经做好了战前准备，如果我们不立即反击，他们就会突破防线，夺得风险湾的控制权。佐娜船长统领着驻扎在港口的部落军队，她的船只就停泊在海湾的另一侧。$B$B只要击败她，削弱部落的防御势力，我们或许就能抓住这个机会占领港口。$N，小心，佐娜是个凶暴好斗的家伙。我估计要好几个人才能制服她，有机会的话你可以利用那台修好的伐木机。', '杀死佐娜船长，然后向风险湾的弗里曼男爵复命。', '干得好，$N!没有她的领军，部落会溃不成军的。我会命令我们的人前进。', '杀死柔纳船长了吗?', '', '去灰熊丘陵找风险湾的弗里曼男爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12315, '消灭布莱沃特船长！', '我们每前进一步，就会遭遇联盟新的增援。好像他们的指挥官能预知我的每一步行动一样！$B$B是时候解决布莱沃特船长了，那家伙在远处港湾中的联盟驱逐舰上指挥着他的部队。$B$B这场战斗并不轻松，$n。带上几个可以信赖的伙伴，或者搞到那些修理过的伐木机的钥匙，用它们去消灭布莱沃特船长！不管你用什么方法，他必须得死！', '杀死布莱沃特船长，然后向风险湾的卡兹加尔将军复命。', '你是个真正的部落士兵，$N。你的勇猛将会激励我的士兵，带领他们迎向胜利!', '你消灭敌人的队长了没?', '', '去找风险湾的卡兹加尔将军。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12316, '夺取港口！', '我们绝不能允许部落占领风险湾，它对我们在灰熊丘陵一带的军事行动起着至关重要的作用。$B$B斯托曼上尉率领月溪旅的其它士兵去东边寻找穿越山岭的道路，我们已经没有援军可用了。$B$B$N，深入敌阵收割征服堡狂战士吧，联盟必须夺得港口的控制权！', '杀死10名部落成员，然后返回风险湾向斯图亚特中尉复命。', '你的勇气激励了西荒兵团的士兵。他们现在能够更勇猛的作战。港口很快就会落入我们手中了。', '你有什么事要报告?', '', '去灰熊丘陵找风险湾的斯图亚特中尉。', '消灭风险湾的部落', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12317, '港口中的联盟', '这个混账月溪旅是一个比我们想象中更强硬的对手。尽管人数不多，但他们战斗起来非常英勇和凶猛，但是我们不能就这么和他们耗着。$B$B征服者克雷娜命令我们要尽快占领港口。你必须打破现在的僵持局面，$N。找到敌人的陆战队员，消灭他们，直到他们停止抵抗。只有这样，我们才能夺取港口的所有权。$B$B快去，我们可不想让克雷娜等太久。', '杀死10名联盟成员，然后返回风险湾向百夫长卡格鲁姆复命。', '港口很快就会落入我们手中了。你今天做得很好，$N。', '你执行命令了吗?', '', '去灰熊丘陵找风险湾的百夫长卡格鲁姆。', '消灭风险湾的联盟', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12319, '血之魔典', '这究竟是什么，$N？那个秽恶的巫妖在你身上降下的诅咒看来绝不一般！$B$B<杜尔库飞速地翻阅这本恐怖的书籍，希望能查出什么内容。>$B$B啊，不行，这书完全我不能理解，我甚至根本不知道该往哪里看。我们必须另想办法查出这本书中的有用信息！$B$B<杜尔库把书交还给你。>$B$B高级指挥官应该知道要怎么做。带上这本血之魔典去找他，记得先详细描述一下这里所发生的一切。', '将血之魔典交给龙骨荒野暮冬要塞的高级指挥官哈尔弗·维姆班恩。', '<海弗德瞪大了眼睛。>$B$B命运今天很眷顾我们，$N。我知道有谁可以处理这本书。', '死灵领主死了吗?', '', '去龙骨荒野找暮冬要塞的高级指挥官哈尔弗·维姆班恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12320, '破译魔典', '拿上书，沿门口的路一直走到兵营。进入兵营以后直接从楼梯下楼，到兵营内的监狱去。你可以在那边找到审讯员哈尔拉德，还有我们以前的市长高弗雷，我想高弗雷或许就是我们面前这张谜图中没有拼上的那一块，而哈尔拉德就是能把这块拼图拼上去的人。$B$B快去吧！', '将血之魔典交给龙骨荒野暮冬要塞监狱内的审讯员哈尔拉德。', '也许靠着一点适当的鼓励，贾弗雷就会告诉我们关于这本书的事情。$B$B<哈拉德转向贾弗雷镇长。>$B$B不是吗，镇长?', '你是从最高指挥官那里来的，我的$g孩子:女孩;?', '', '去龙骨荒野找暮冬要塞的审讯员哈尔拉德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12323, '把他们熏出来！', '还有一小部分风险投资公司的成员藏匿在风险湾中心的建筑物中。我一方面要不断地抽调人手对抗部落军队，另一方面又不能任由那些风险投资公司游荡者龟缩在暗处。$B$B或许我们能“说服”他们从工棚、锯木厂或是马厩之类的地方现身。利用这枚烟雾炸弹将他们从藏身之处熏出来。你最好别靠得太近，兔子急了也会咬人的。', '利用烟雾炸弹迫使20名风险投资公司游荡者逃出他们的藏身之地，然后向杜内恩中士复命。', '做的好，士兵!现在其它人就可以把精力集中在部落身上了。', '你把风险投资公司的人都逼走了没?', '', '去灰熊丘陵找风险湾的杜内恩中士。', '熏出风险投资公司游荡者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12324, '把他们熏出来！', '不仅仅只有那些联盟胆小鬼在这座港口出没，更糟糕的是，风险投资公司的雇员仍然占领着这里的一些建筑。他们根本不值得我们花时间去对付，而且我手头也没有多馀的人手了。$B$B也许我们可以“说服”他们离开。拿上这些烟雾弹，把他们从工棚、锯木厂或是马厩里面赶出来。不过，不要离他们太近了，我可不清楚他们携带着什么疾病。', '利用烟雾炸弹迫使20名风险投资公司游荡者逃出他们的藏身之地，然后向石头守卫诺卡·怒火图腾复命。', '将军会很高兴听到你解决了风险投资公司的问题的。现在，我们可以专心在击退联盟上了。', '你把风险投资公司的害虫们都熏走了吗?', '', '去灰熊丘陵找风险湾的石头守卫诺卡·怒火图腾。', '熏出风险投资公司游荡者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12326, '蒸汽坦克行动', '本次行动的核心内容是搜索与消灭。你将驾驶一辆坦克直接进入腐臭平原，摧毁一切天灾军团的天灾战车。此外，跟随你进入敌占区的还有三名隶属于第七军团的士兵，若想任务成功，你必须保证他们的存活！$B$B执行任务时，你只需要将坦克开近敌人的天灾战车，派出车上的工兵，掩护他们完成爆破作业，然后转至下一辆天灾战车旁即可。消灭战场上的全部天灾战车以后，你要直接将坦克开往要塞废墟前的陵园，将车组成员送到那里去。之后，进入陵园，与阿姆博·卡什会面。', '使用联盟蒸汽坦克摧毁6台天灾战车，并将第七军团精英送入暮冬陵园。成功之后与暮冬陵园里的阿姆博·卡什谈一谈。', '我为什么没穿裤子并不重要。这样说吧，我中了几发天灾军的炮弹碎片，这样行吧?$B$B所以你说你把外头的瘟疫战车都清光了，还安全地把我的士兵送来这里。很好。你是第一个做得这么好的，朋友。很遗憾你必须立刻回到腐尸农地上。没错，我们遭遇了一点挫折。', '我叫凯许。安柏.凯许。你很荣幸认识我。', '', '去龙骨荒野找暮冬陵园的阿姆博·卡什。', '摧毁天灾战车', '安全运送第七军团精英', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12327, '梦游体验', '啊，你想要知道过去发生了些什么？很好，你真是一个睿智的$r。$B$B每次有人路过这里，慕名来找我时，总是想问有关未来的事。但是当你到了我这个年纪时，你就会明白，了解过去远比了解未来更有用。$B$B饮下这瓶药水，凝视这枚水晶球吧。让我们看看你能发现些什么。', '在卢娜的水晶球旁饮下幻境药水，见证过去的景象。', '你从你要的幻象中得知了什么?你在出神状态下提到了季至村 -- 这是今天第二次有人提到这个地名了。', '嗯，$N?', '往日的景象', '去灰熊丘陵之卢娜的营地找盲眼卢娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12328, '卢娜的要求', '我不会向你收取任何费用，因为我清晰地感觉到，你的一举一动对所有人的命运都非常重要，而今天的预言则将大大推动你的进展。$B$B不过，你得帮我带回一种占卜所必需的材料。到东北边那些食蕨蛾身上收集一些幻境粉尘，我可以用它们调制出一种药水，喝下它之后，你就将在梦境中转至正确的时间与地点去见证你需要见证的一切。', '盲眼卢娜要你收集4堆幻境粉尘。', '很好。这些刚好够用。$B$B我会立刻准备好给你的药剂。', '你取得粉末了吗，$N?', '', '去灰熊丘陵卢娜的营地找盲眼卢娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12330, '阿纳托雷', '我的妹妹应该被困在这个村子里，但囚禁她的那个混蛋不愿意跟我谈判。$B$B他似乎完全不关心自己的幸福。不过我有个计划。早在拜狼教到来之前，我就认识了阿纳托雷的妻子塔特亚娜，她是个驯马师。$B$B拿上这根麻醉飞镖，她看到就知道是我派你去的，我想请她来好好谈一谈，看她能不能帮忙说服阿纳托雷。$B$B只要我们一救出我的妹妹，我一定会帮你找出这一切的幕后黑手。', '白松商栈的萨莎要你进入冬至村，对塔特亚娜使用麻醉飞镖。然后将塔特亚娜带回白松商栈。', '千…千钧一发。$B$B我们必需马上救出安雅!', '庆幸你毫发无伤。', '将塔特亚娜带回白松商栈', '去找灰熊丘陵白松商栈的萨莎。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12372, '保卫龙眠神殿', '蓝龙军团受到碧蓝巨龙圣地中流动的过剩法力的鼓舞，居然胆敢来攻击龙眠神殿！$B$B请你骑上龙眠神殿防御者加入战斗，消灭蓝龙和他们的幼龙。你还要攻击碧蓝巨龙圣地喷发出来的魔网能量，使它变得不稳定。$B$B龙眠神殿防御者就在东面和西面的平台上。与其中一头防御者交谈，他就会载你一起战斗。$B$B如果没有你的帮助，$N，我们一定会输掉这场战争。', '龙眠神殿的阿弗拉沙斯塔兹要你骑着龙眠神殿防御者加入战斗，杀死3条碧蓝巨龙和5条碧蓝幼龙，并破坏碧蓝巨龙圣地。', '不可思议!请容我这么说，汝等这种年幼的种族十分可靠，这也同时再再令我感到惊喜。$B$B我们欠你很多很多，明日还能借重你的力量吗?', '战况如何?我们阻止他们的进攻了吗?', '', '去龙骨荒野找龙眠神殿的阿弗拉沙斯塔兹。', '', '', '破坏碧蓝巨龙圣地', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12412, '我的敌人的朋友', '如果只能向你脑袋里灌输一件事的话，那么我一定会说：必须把联盟从灰熊丘陵彻底赶出去。$B$B这里太重要了，无数的木材，矿石，还有战略缓冲地，这个地方简直是寸土寸金。$B$B当前我们的行动还算成功……但是现在发生了一件事，可能会让胜利的天平略微倒向敌人那边。$B$B遥远的东边有一处林边哨站，那里的猎户竟然想加入联盟。击败他们，不要给他们提供任何威胁到我们的机会。', '征服堡的征服者克雷娜要你转至林边哨站，击败8名银溪镇猎人及他们的领袖弗拉德克。', '你活着回来了。$B$B狼人又做了什么蠢事?', '任务完成了吗?如果没有的话，那你还待在这儿干嘛?', '', '去灰熊丘陵找征服堡的征服者克雷娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12413, '攻击银溪镇', '几个小时以前，那群猎户还只不过是一群整天威胁说要加入联盟那边的乡巴佬而已。$B$B可现在，他们变成了某种……某种神秘的东西。我不喜欢神秘主义，不喜欢装神弄鬼。我要你转至灰熊丘陵北部的银溪镇，他们就聚集在镇子外面的丘陵上，帮助我的人把他们都清除掉。', '征服堡的征服者克雷娜要你转至银溪丘陵，杀死8名银溪镇防御者。', '$N，还不赖。你比我一开始以为的有用多了。', '$N，完成任务了吗?', '', '去灰熊丘陵找征服堡的征服者克雷娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12414, '顺手牵马', '斯托曼上尉一直不让我们这些骑……骑兵……好吧……养马的去参加风险湾一带的战斗。$B$B无所事事的我们只好把营地扎到了这处好地方，你看，周围漫山遍野都是高地野马在跑来跑去，从巨石丘陵到东北边，全都是！队长要我负责抓几只野马来补充坐骑。$B$B你愿意帮个忙吗？你看，绳子和棍子都有了，营地周围的土里还长满了野生胡萝卜。你只要拔上几根胡萝卜然后把它用绳子捆在棍子上，一路把野马引回到这里来，就搞定啦，轻松愉快！', '驱赶5匹高地野马回到月溪旅营地的侍从皮尔斯那里。', '哇呜!真是好马!我想上尉知道我们的成果一定会很开心的。', '你把我们要的野马抓起来了没?', '', '去灰熊丘陵找月溪旅营地的侍从皮尔斯。', '牵回高地野马', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12416, '白热化的战斗', '天灾军团向圣地发动了猛烈的攻击，而圣地的守护者达莉亚不知去向。那些在混战中死去的红龙变成了扭曲的灰烬之龙，转而与我们为敌。情况实在是糟透了，$c。$B$B伊斯坎达尔上尉率领着一支你们的军队在圣地外抵御如潮水般涌来的天灾军团。$B$B去帮帮他吧……不过别冲得太靠前了。天灾士兵源源不断地攻上来，我不想让你就这样丢了性命。', '杀死12个进攻的冰冷食尸鬼、8个进攻的冰冷恶鬼和1个进攻的冰冷憎恶，帮助伊斯坎达尔上尉守住峡谷。完成任务后向塞雷斯塔兹复命。', '这个任务令人作呕，但我为你的付出表示感激。$B$B天灾军不能向龙眠神殿推进任何一步，否则我们一定会失守的。', '很高兴你还能和我们并肩作战，$r。', '', '去龙骨荒野找巨龙废土的塞雷斯塔兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12417, '重归尘土', '还有件事要交给你办。我有很多兄弟都在激烈的空战中阵亡了。如果我们不赶快行动的话，他们就会加入灰烬之龙的队伍。$B$B请你从南面或北面的小路进入圣地……那里的天灾军团应该比较少。$B$B在圣地里寻找从树上掉下来的红玉橡果，然后把它们种在我死去的同胞们的尸体旁。这样他们就能获得新生……这是红龙氏族的高贵宿命。', '从南面或北面的小路进入红玉巨龙圣地并寻找红玉橡果。对死去的红龙使用红玉橡果，让他们的尸体回归大地。完成任务后向塞雷斯塔兹复命。', '在大地之中，我的兄弟能把他们自己赠与给新的生命。你从比死亡更糟糕的命运中拯救了他们。$B$B我不知道在你的语言之中有没有一个字能够表达这对吾族而言有多么意义重大。感谢你，$r。', '我都已经开始担心龙殿里的天灾军团夺走了你。你还活着真好。', '', '去龙骨荒野找巨龙废土的塞雷斯塔兹。', '红玉守护者重归尘土', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12418, '烈焰之地', '我还有最后一个任务要给你，$r……一个足以扭转战局的任务。$B$B请你回到圣地，去杀死那些指挥战斗的通灵师。只要他们死了，我们就能击退天灾的军队，并慢慢夺回圣地。$B$B我还要你去找到圣地下面的堕落之源并摧毁它。$B$B我知道我要你做的事情太多了，但如果你能做到的话，我们就可以赢得这场战斗。', '从南面或北面的小路进入红玉巨龙圣地，杀死6个冰冷通灵师并摧毁圣地下面的堕落之源。完成任务后向塞雷斯塔兹复命。', '妲莉雅…被他们同化了?$B$B妲莉雅长久以来对我们忠心耿耿…如果他们能将这样为我们奉献的生命腐化，其它年轻的种族恐怕也难以抵挡。感谢你解放了她，我希望她能真正安息。$B$B今天，你以你无私的援助荣耀了我们，$r。我会向汝等在此所创建的议会捎去消息。带着我们的祝福出发吧。', '你回来了!你完成了我要求的事情吗?', '', '去龙骨荒野找巨龙废土的塞雷斯塔兹。', '', '净化红玉的腐蚀', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12419, '红玉巨龙圣地的命运', '你捡起这只胸针之后，发现它所发出的微弱光芒又黯淡了一些。$B$B克拉苏斯一定很关心达莉亚的命运。把这只胸针带回龙眠神殿交给他吧。', '将达莉亚的红玉胸针带回龙眠神殿的议会大厅交给克拉苏斯，并将她的命运告诉他。', '妲莉雅陷落于天灾军团之手?对我们所有人来说，这真是悲伤的一天。$B$B我们夺回龙殿之后我会重新找一个看守者。感谢你的努力…晶红龙殿对我们来说是个圣地，你们族类所做的努力不会轻易地被遗忘的。$B$B知道还有像你这样的英雄真好 - 将来有一天我会召唤你来。直到那天到来，祝你冒险顺利、成果丰硕。', '你好，$r。我感觉到我的红宝石胸针了。把它交给我吧。$B$B妲莉雅发生了什么事?', '', '去龙骨荒野找龙眠神殿的克拉苏斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12420, '本月美酒俱乐部', '会员总是享有特权的。只要你成为“本月美酒”俱乐部的成员，就能在第一时间品尝到世间最棒的佳酿。$B$B将“本月美酒”俱乐部会员数据表交给铁炉堡石火旅店的拉尔金·雷酒吧。', '将“本月美酒”俱乐部会员数据表交给铁炉堡石火旅店的拉尔金·雷酒。', '你的数据看起来没有问题，$N，欢迎成为俱乐部的一员!$B$B每个月的第一天你会收到我们的邮件，如果你喜欢我们邮寄给你的酒，请来俱乐部，我们可以卖你更多。我们是很大方的俱乐部。', '你填妥会员表格了吗?', '', '去找丹莫罗的拉尔金·雷酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12421, '本月美酒俱乐部', '$n，所谓众人拾柴火焰高，只要你成为“本月美酒”俱乐部的成员，你和你的同胞就能品尝到世间最棒的佳酿。$B$B将“本月美酒”俱乐部会员数据表交给奥格瑞玛精神谷黑石南小屋的莱玛吧。', '将“本月美酒”俱乐部会员数据表交给奥格瑞玛精神谷黑石南小屋的莱玛。', '$N，你想加入我们的会员了吗?我们的福利很好，身为俱乐部的一员，我们一定给你最好的!$B$B每月的第一天会将啤酒寄发给你，想要更多，回来这里，我们保证让你有喝不完的啤酒。', '你填妥会员表格了吗?', '', '去找奥格瑞玛的莱玛。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12422, '顺藤摸瓜', '听着，$N。我要求你立刻前去执行一项需要高度判断力与效率的任务。$B$B克雷娜手下的一位高级士官在银溪镇外围获取了一名猎户流亡者。如果按照他们以往的方式来行事，那么这名战俘将在日落之前被处死。$B$B但我们不能让他们这么简单地把她处决掉。你看，这名战俘看起来跟米克哈尔日记中所描述的长女非常相似。$B$B如果我们放了她，并暗地跟踪她的话，就可以轻松地找到控制着那些猎户的真正幕后黑手。快，带着这封信去找她。', '带着特赦信转至银溪丘陵，将信交给被囚禁的猎户。', '你是来放我走的…就这样?听着，我不想跟你有任何瓜葛…这些浑球杀了我的父亲，带走了我的姊姊。我现在有别的事要操心。', '你是来杀我的吗?', '', '去灰熊丘陵找银溪丘陵的被囚禁的猎户。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12423, '米克哈尔的日记', '根据你所掌握的情况，你认为这本日记是一个名叫米克哈尔的银溪镇居民写下的。$B$B他想必使用了人类通用语的某种变体或是方言，以防被人读懂其中的内容。或许你应该将这本书交给征服者克雷娜。', '将米克哈尔的日记交给征服堡的征服者克雷娜。', '哈!这是某种笑话吗?$B$B我能读得懂的书几乎都对我没什么用。', '你手上拿着什么?', '', '去灰熊丘陵找征服堡的征服者克雷娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12424, '高戈娜', '嗯，没错，这日记的确是人类所用的猪一般的语言写成的。直接烧了吧，没什么价值。$B$B把它交给我妹妹高戈娜，别浪费我的时间了。', '将米克哈尔的日记交给征服堡的高戈娜。', '这是真的吗?写了这本日志的男人担心他女儿们的性命所以把她们从银溪镇送走了。$B$B我们刚刚才在城镇外缘抓到了一个流放者，而且她和这个大女儿的年纪差不多。$B$B听着，$N。这里发生的事情远超过眼睛所见…我们不能烧掉这本日志。', '你有东西要给我看?', '', '去灰熊丘陵找征服堡的高戈娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12427, '征服斗兽场：斗熊！', '听说你对打架很在行，是不是啊？这么说吧，克雷娜前一段时间发了个公告，禁止所有当兵的参加拳赛或是其它搏斗比赛什么的。但你没问题啊，你是自由身，完全不用管这条禁令嘛。$B$B怎么样，心动了吧？$B$B总之，要是你觉得有兴趣呢，我就帮你报名登记，第一个对手很简单的，就是一只花狗熊而已。你看，还可以带朋友一起上哟！', '击败征服斗兽场内的铁皮，然后找赌徒维尔金领取奖赏。', '做的好，老兄!这是你的份。', '直到你跟这头熊其中一个倒下以后才算结束，朋友!', '击败铁皮', '去灰熊丘陵找征服堡的赌徒维尔金。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12432, '驾驶红色火箭', '就是你，$c！给我滚过来！$b$b联盟已经在这里的东北方装了满满一船的木材，正准备把它们运出去。既然我们没法夺走那些木材，那么就只有一个选择了——摧毁它！$b$b码头尽头的地精已经准备好了一些鱼雷，你可以在停泊在北边的地精船只上搞到开动鱼雷所需的燃料。$B$B去弄些燃料，然后驾驶一枚鱼雷冲向他们的运输船。$B$B出发！', '风险湾灯塔的高洛克将军希望你去摧毁联盟的木材运输船。$B$B只有在部落占领灯塔的时候，高洛克将军才会出现。', '哈，哈!射得准啊，对吧$C?$B$B如果我们不能控制这里的资源，那谁也甭想得到!$B$B什么时候这些弱小的联盟害虫才能明白，他们不能跟部落的力量匹敌?', '联盟的木柴已经烧掉了吗，$C?', '', '去灰熊丘陵找风险湾的高洛克将军。', '摧毁联盟的木材运输船', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12433, '寻找溶解剂', '不会吧！又坏了一个垫圈……$B$B每次有垫圈坏掉，润滑剂都会流得到处都是。如果没有溶解剂的话，就得折腾好几个小时才能清理干净。$B$B我跟你说啊，在风险投资公司闯入的那个港口里有一种奇特的火箭燃料——我想他们把它称为“115号元素”。那东西可是很猛的溶解剂哦。$B$B帮我弄些过来，我不会让你白辛苦的。', '风险湾部落基地的古图尔要你取回一罐115号元素。', '啊，没错，可以替我节省下许多时间了。$B$B收下这个，当作我麻烦你的回报，朋友。帮我多找一些元素115来，你找到多少我收多少。', '拿到一些元素115了没，$N?', '', '去灰熊丘陵找风险湾的古图尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12436, '赚外快', '向你致敬，$C。不知道你有没有发现，在征服堡这个地方，一切都在克蕾娜的控制之下，我们买克蕾娜让我们买的，卖克蕾娜让我们卖的，连价格都是克蕾娜规定好的。$B$B这一些都在让这里的经济死亡！我决定偷偷赚一笔小钱，顺便让步兵小伙子们饱点口福。你不如去猎几头鹿，然后给我弄点鹿肉回来，怎么样？$B$B这附近的鹿可真是漫山遍野，所以呢，你必须只挑选最好的肉。', '征服堡的粮食商人洛克兰要求你从附近的耸角雄鹿身上采集5块肥美的鹿肉。', '干的好，$N。这些可以喂饱两三个蛮兵。不错。', '你拿到鹿肉了没，$N?', '', '去灰熊丘陵找征服堡的粮食商人洛克兰。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12437, '红色鱼雷', '听着，$n。这场战斗说穿了无非就是在比谁的资源多。$B$B我有一个计划，可以让我们对部落占有更大的优势。$b$b在码头尽头停泊着一些鱼雷，我们可以利用它们击毁部落停泊在西北面的木材运输船。$B$B你去北边港口里的地精船只那里弄些燃料，然后骑在一枚鱼雷上，直接冲进他们的运输船里去！', '风险湾灯塔的霍瑟尔司令希望你去摧毁部落的木材运输船。$b$b只有在联盟占领灯塔的时候，霍瑟尔司令才会出现。', '很高兴你从这场冲突中活了下来。炸得漂亮!$B$B我们不能承担部落运木船逃走的后果。$B$B干得好，$C。', '烧毁部落的运木船了吗，$N?', '', '去灰熊丘陵找风险湾的霍瑟尔司令。', '摧毁部落的木材运输船', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12438, '悬赏：克留格·碎誓者', '悬赏发布人伊露希亚·卢恩$B$B一个名叫克留格·碎誓者的天灾军团血肉巨人杀死了我的丈夫、孩子和我最好的朋友，韦斯帕尔一家。敢于揭下这张布告的勇士可以在腐臭平原东南边的海岸附近找到克留格。$B$B我要为死者讨回公道！去杀死克留格·碎誓者！$B$B杀死克留格的勇士可以去向李奥瑞克·冯·泽尔迪格公爵领取金钱和物品奖赏。$B$B请为我们伸张正义！', '杀死克留格·碎誓者，然后转至龙骨荒野的暮冬要塞，向李奥瑞克·冯·泽尔迪格公爵领取奖赏。', '做的好，$N。我会告诉伊鲁希亚有个英雄听见了她的求助并起身迎接挑战!这是你的奖赏。', '你是来领赏的吗，盟友?', '', '去龙骨荒野找暮冬要塞的李奥瑞克·冯·泽尔迪格公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12441, '通缉：高阶萨满祭司德金·血爪', '悬赏发布人：德洛菲$B$B我和我的表亲，斯克罗提和布鲁特，在埃尔德齐断崖遭到了一群邪恶的血爪氏族狼獾人的袭击。我们逃走了，但斯克罗提和布鲁特恐怕被他们抓住了。$B$B我要报仇雪恨！在此招募无畏的勇士转至龙骨荒野东南部的埃尔德齐断崖，杀死高阶萨满祭司德金·血爪和他的爪牙。$B$B杀死这个恶棍的勇士可以向李奥瑞克·冯·泽尔迪格公爵领取大笔赏金！', '杀死高阶萨满祭司德金·血爪，然后转至龙骨荒野的暮冬要塞，找李奥瑞克·冯·泽尔迪格公爵领取奖赏。', '$N，表现得很出色!我会通知德罗菲，某个英雄动身完成了他的挑战，同时，残暴的血掌将不再是威胁!', '你解决血掌了吗?', '', '去龙骨荒野找暮冬要塞的李奥瑞克·冯·泽尔迪格公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12442, '悬赏：先锋军指挥官尤斯图斯', '悬赏发布人李奥瑞克·冯·泽尔迪格公爵$B$B位于暮东城东北小径上的第七军团兵营遭到了先锋军指挥官尤斯图斯和一群疯狂的血色先锋军成员的血腥屠杀。我们必须回击这种残忍的蓄意袭击！$B$B暮冬要塞必须伸张正义！我们招募勇士转至东北方的血色先锋军营地，找到并杀死先锋军指挥官尤斯图斯。$B$B任何能够完成这个任务的人都将获得可观的奖金！', '杀死先锋军指挥官尤斯图斯，然后转至龙骨荒野的暮冬要塞，向李奥瑞克·冯·泽尔迪格公爵领取奖赏。', '所幸，血色先锋军奸恶的计画受到了挫败。你为温特加德做出了伟大的贡献，$N。', '<李奥瑞克咬牙切齿说道。>$B$B那个自负的蠢蛋死了没?', '', '去龙骨荒野找暮冬要塞的李奥瑞克·冯·泽尔迪格公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12443, '寻找溶解剂', '不会吧！又坏了一个垫圈……$B$B每次有垫圈坏掉，润滑剂都会流得到处都是。如果没有溶解剂的话，就得折腾好几个小时才能清理干净。$B$B我跟你说啊，在风险投资公司闯入的那个港口里有一种奇特的火箭燃料——我想他们把它称为“115号元素”。那东西可是很猛的溶解剂哦。$B$B帮我弄些过来，我不会让你白辛苦的。', '风险湾联盟基地的巴布芬克要你取回一罐115号元素。', '啊，没错，可以替我节省下许多时间了。$B$B收下这个，当作我麻烦你的回报，朋友。帮我多找一些元素115来，你找到多少我收多少。', '拿到一些元素115了没，$N?', '', '去灰熊丘陵找风险湾的巴布芬克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12444, '黑水伐木场的战斗', '风险投资公司正在撤离灰熊丘陵。他们以前在这里运作着木材生意，但眼下的形势对他们来说有点太危险了。$B$B他们放弃的伐木场现在很容易就能占领，我们肯定不能让部落占领它们。$B$B黑水伐木场是这一地区的三处伐木场中最小的一个，但我们仍然需要它。你的任务就是去赶走部落的部队，他们从这里获得的任何木材都将是在别处对抗我们的武器。', '斥候队长卡特尔希望你在黑水伐木场击杀10名部落士兵或者玩家。', '做得好，$N。我们应该好好利用像你一样的伙伴，让部落知道不要惹毛我们。', '狩猎情形如何?', '', '去找灰熊丘陵的斥候队长卡特尔。', '消灭黑水伐木场的部落', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12450, '烈焰之地', '我还有最后一个任务要给你，$r……一个足以扭转战局的任务。$B$B请你回到圣地，去杀死那些指挥战斗的通灵师。只要他们死了，我们就能击退天灾的军队，并慢慢夺回圣地。$B$B我还要你去找到圣地下面的堕落之源并摧毁它。$B$B我知道我要你做的事情太多了，但如果你能做到的话，我们就可以赢得这场战斗。', '从南面的小路进入红玉巨龙圣地，杀死6个冰冷通灵师并摧毁圣地下面的堕落之源。完成任务后向瓦加斯塔兹复命。', '妲莉雅…被他们同化了?$B$B妲莉雅长久以来对我们忠心耿耿…如果他们能将这样为我们奉献的生命腐化，其它年轻的种族恐怕也难以抵挡。感谢你解放了她，我希望她能真正安息。$B$B今天，你以你无私的援助荣耀了我们，$r。也许，并非所有的部落人一如他们的先祖们一样心怀恶意。我会向汝等在此所创建的议会捎去消息。', '你回来了!你完成我的要求了吗?', '', '去找龙骨荒野的瓦加斯塔兹。', '', '净化红玉的腐蚀', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12453, '白肩鹰的眼睛', '他们一直要我帮忙对抗联盟。现在我们的军队正在和对手僵持，我们必须尽可能获得优势。$B$B在这片山脉和森林中翱翔的白肩鹰可以成为我们最好的探子。带上这片银色羽毛，用它让我的视界和它们的视界结合。$B$B能够看到敌人的活动无疑会给我们带来巨大的优势。你可以在东面的山中找到大量的白肩鹰。', '风之先知希尔·灰角希望你在灰熊丘陵的6只白肩鹰身上使用银色羽毛。', '感激不尽，$N。感谢你的帮助。', '你完成我吩咐你的指示了吗，$N?', '', '去灰熊丘陵找征服堡的风之先知希尔·灰角。', '分享白肩鹰的视界', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12454, '生命的循环', '伊瑟拉在翡翠梦境中沉睡，守护着梦境世界和艾泽拉斯。但是可怕的噩梦入侵了梦境世界，这使得我担心伊瑟拉也受到了影响。$B$B最近，我请求她帮助我们对抗天灾军团——那些亡灵正在各个巨龙圣地中制造冰霜巨龙。可是她误解了我的请求。$B$B她命令我们这个巨龙圣地的守卫攻击所有非绿龙军团的人。$B$B我要你去杀死一些天爪枭，以此来恢复圣地的平衡。', '翡翠巨龙圣地的护园者尼瑟拉要你去杀死5只翡翠天爪枭。', '不要后悔你在生命的循环中所扮演的角色。出生，死亡，与重生都是自然规律中的一部分。', '越快解决翡翠天爪，越快能将翡翠龙殿的自然平衡恢复。', '', '去龙骨荒野找翡翠巨龙圣地的护园者尼瑟拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12455, '随风散落', '朋友，军需品的数量严重短缺。我们打算从暮冬要塞空运来一批弹药，却在半路遭到了冰霜巨龙的袭击。货运飞船根本不堪一击，瞬间就散了架，好在大多数弹药箱都散落在了腐臭平原。$B$B我要你转至腐臭平原，取回我们的军需品。$B$B快点！没有枪支和弹药，你叫我们如何打仗！', '龙骨荒野暮冬陵园的阿姆博·卡什要你取回8箱暮冬军需品。', '还来得及!我的部份士兵热血冲昏了头，决定朝东西两边的地穴猛攻。不用说，他们很快地就被这些无脑的食尸鬼给击溃了。我们得抢救生还者!', '我的军火呢，$g先生:小姐;?', '', '去龙骨荒野找暮冬陵园的阿姆博·卡什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12456, '奥雷托斯的羽毛', '我能感觉到圣地并没有完全恢复平衡。翠羽守护者已经被我们的行动激怒了，我预感它不会听我们解释的。$B$B奥雷托斯是一头巨大的天爪枭，它栖息在翡翠巨龙圣地的最南部，控制着整个巨龙圣地的空中防御。恐怕我们也得让它进入轮回了。$B$B把这些天爪枭的绒毛放在它能看见的地方，它就会出现。把它的羽毛给我带来。', '翡翠巨龙圣地的护园者尼瑟拉要你取得奥雷托斯的羽毛。', '别为艾里史卓斯哭泣。他将其永恒的生命奉献给护卫苍蓝龙殿，即将重生。$B$B但愿当他重返我们身边的时候，他不会因为梦境之龙所控制的翡翠梦魇而陷入迷惘。', '你准备对付艾里史卓斯了吗?别害怕向你的朋友求助。$B$B事实上，青绿看守者很强大，我推荐你结伴而行!', '', '去龙骨荒野找翡翠巨龙圣地的护园者尼瑟拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12457, '重机枪与你', '我们在正东方和正西方都架设了重型机枪和路障。受伤的士兵就躲在障碍物后，连大气都不敢出，唯恐被无脑的食尸鬼发现。$B$B弹药短缺的难题已经解决了，所以我要你拿起一挺重型机枪朝敌人扫射，掩护我们的士兵逃出来！你准备好之后，就呼唤一名受伤的士兵，然后朝涌上来的天灾军团士兵开火！$B$B前进！', '龙骨荒野暮冬陵园的阿姆博·卡什要你营救8名受伤的第七军团士兵。', '$N，自从希利苏斯的战事之后我就再也没有看过如此英勇的行为了!$B$B我相信所有的士兵将会向弗塔根领主荐举你的!$B$B那么，回归更要紧的事情，探子来报，赛尔赞逼近了。', '你救出我们受伤的士兵了吗?', '', '去龙骨荒野找暮冬陵园的阿姆博·卡什。', '营救受伤的第七军团士兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12458, '鞭笞者的种子', '我们需要更多对抗天灾军团的武器。东南方的翡翠巨龙圣地也许就是我们要寻找的答案。$B$B所有的亡灵生物——除了希尔瓦娜斯手下的那些——只要踏入圣地就会化为尘土。$B$B我需要你的帮助来完成一个试验，年轻的$r。请你到翡翠巨龙圣地去，拿一些翡翠鞭笞者的种子回来。', '龙眠神殿顶层的伊萨里奥斯勋爵要你去收集3份鞭笞者的种子。', '就算到了现在，我还是能感受到\r\n种子中自然的脉动。$B$B我们一定要善加利用这些种子!', '截至当前你已经拿到多少颗种子了呢?', '', '去龙骨荒野找龙眠神殿的伊萨里奥斯勋爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12459, '创造与毁灭的力量', '我们只有三颗种子，必须把它们用在最需要的地方。$B$B你的目标是北面迦拉克隆之墓附近的一只冰霜巨龙，东面腐臭平原的兵营废墟中的卑鄙的图尔基德，以及遥远的东北方的金萨卡拉的监工戴瑟盖斯。$B$B虽然这些种子能完全摧毁一个低级天灾士兵，但对于这三个家伙却只能起到削弱的作用。但这也足够了，因为他们被削弱之后，你就可以自己解决他们了。', '龙眠神殿顶层的伊萨里奥斯勋爵要你去杀死一头被削弱的冰霜巨龙、被削弱的图尔基德和被削弱的监工戴瑟盖斯。', '非常好。就跟我一直所猜测的一样。我得试着和伊瑟拉联络，看看她是否允许。$B$B当然，如果能从她的恶梦中哄骗出来的话。$B$B感谢你，$N。你的存在不可或缺。', '结果如何?毁掉他们了吗?$B$B我需要答案!', '', '去龙骨荒野找龙眠神殿的伊萨里奥斯勋爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12462, '深入陵园', '沿着台阶往下走，就是通往被诅咒的地宫的大门：那里聚集着数都数不清的天灾军团士兵，而且他们的数量还在不断增长。我们费尽心思收集到的情报表明，天灾军团的两名通灵领主正在前两座地穴里努力制造新的士兵。在我们攻入塞尔赞所在的核心密室之前，必须除掉这两个家伙和他们手下的天灾军团渣滓。$B$B进入暮冬陵园，杀死通灵领主、纳克萨玛斯恐怖卫士和纳克萨玛斯之影。', '龙骨荒野暮冬陵园的“灾星”尤尔德·冰须要你杀死通灵领主萨维奥斯、通灵领主霍鲁斯和15名纳克萨玛斯天灾士兵。', '这样应该替安柏争取了一点处理事情的时间。', '你搞定了吗?', '', '去龙骨荒野找暮冬陵园的“灾星”尤尔德·冰须。', '', '', '杀死纳克萨玛斯天灾士兵', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12464, '我的老对手', '我的老对手，阿比迪斯将军也来到了诺森德。$B$B她在我们对提尔之手的进攻中逃了出来，带着一小队残兵向北逃窜，在这里的南部创建了新壁炉谷。$B$B虽然他们对付天灾军团也很积极，但阿比迪斯太狡猾了，我们不能让这样的敌人继续活着。相信我，如果我们不干掉她，她的剑会在尘埃落定前架上我们的脖子。$B$B所以我们要干掉他们的首领，然后再做自己的事。把她的徽记给我带来。', '把阿比迪斯将军的徽记交给暮冬要塞的指挥官埃里戈尔·黎明使者。', '对付阿比迪斯是个不幸，但必要的任务。很久很久以前，我曾想象过和她一起并肩作战的可能性。$B$B<指挥官的声音渐止，沉浸在思绪中片刻，然后才继续说。>$B$B我有点在意你口中的这个海军上将。你说的是巴瑞恩.韦斯温?我不敢相信他竟然还活着。他一定年纪很大了。不过，我们晚点再来对付他。$B$B现在，我想你赢得了奖赏和休息时间。', '那么，任务完成了?', '', '去龙骨荒找野暮冬要塞的指挥官埃里戈尔·黎明使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12465, '普兰比尔德的日记', '看来必须找到日记中缺失的书页。袭击普兰比尔德的家伙或许就躲在隧道另一侧的房间中。一定是他们撕掉了后面的书页！$B$B一旦你找到缺失的书页，就把它们交给暮冬陵园入口处的阿姆博·卡什。', '将普兰比尔德的日记的第4页、第5页、第6页和第7页交给龙骨荒野暮冬陵园的阿姆博·卡什。', '<安柏读完恢复的日志。>$B$B有些好消息，也有些坏消息。你想先听哪一个?$B$B啊，该死的，干嘛给你选呢?好消息是，如果我们能弄到赛尔赞的骨匣，我们就能摧毁他。坏消息是，骨匣是在一条相当大的冰霜巨龙身上。', '我当然不觉得自己像个赢家…', '', '去龙骨荒野找暮冬陵园的阿姆博·卡什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12467, '追击冰雪风暴：塞尔赞的护命匣', '那头名叫冰雪风暴的冰霜巨龙就是你的目标。$B$B<泰拉里安指着西边的天空。>$B$B它真的很大！$B$B你准备好了之后，就和“龙饵”谈一谈，他会负责“吸引”冰雪风暴的注意。一旦冰雪风暴靠得足够近，我们就一拥而上，将它困在地面上！希望在你的帮助下，我们可以除掉它并夺得护命匣。$B$B然后你就返回暮冬要塞，向高级指挥官哈尔弗·维姆班恩报到。他一直在准备与塞尔赞进行最后的决战。', '从冰雪风暴手中夺得塞尔赞的护命匣，将它交给暮冬要塞的高级指挥官哈尔弗·维姆班恩。', '赛尔赞那个混蛋害我们失去了很多好士兵。我真希望当你在他面前粉碎他的骨匣，终结他的性命的时候我能够在场。', '你拿到赛尔赞的骨匣了吗?', '', '去龙骨荒野找暮冬要塞的高级指挥官哈尔弗·维姆班恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12469, '退回发件人', '经过进一步的调查，那个地精似乎是想要穿越荒地，把一大堆炸药运过去。半埋在附近雪地里的鹰身人羽毛让我们可以猜想他遇到了怎样的悲惨命运。$B$B那地精应该是从东面的某个地方出发，把炸药运向天灾之门。最谨慎的做法就是沿着山脊回到东面，向寄件人通报他们的送货员的遭遇。', '沿着山脊向东面走，将炸药包交给龙骨荒野北部诺兹拉斯哨站的辛克。', '哈!又损失了一个人，嗯?鹰身人真的是越来越烦。$B$B不管!工作得完成才行。帮个忙怎么样?', '你好啊!', '', '去龙骨荒野找冷风高地的辛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12470, '永恒之龙的秘密', '东北方的青铜巨龙圣地周围的时间风暴会阻止任何永生者进入其中。$B$B永恒之龙正在里面和守卫战斗，试图夺取巨龙圣地的控制权。我们必须利用这个机会获取一些情报。$B$B你不是永生者，因此你可以进入巨龙圣地并使用永恒沙漏。你要保护好这个沙漏，直到永恒之龙的首领显身。$B$B你要小心，永恒之龙会试图阻止你！', '克罗米要你进入青铜巨龙圣地，将永恒沙漏放在地上。$B$B保护沙漏，直到你获得克罗米想要的情报。完成任务后返回龙眠神殿顶层向她复命。', '你看见了诺兹多姆?这不合理。$B$B<克罗米思考了你所说的话许久。>$B$B事实上，那是个好消息!我们不知道时光之王转至何处或何时，只知道他离了去处理一些非常重要的事情。$B$B所以，即使永恒之龙的首领并未现身，你发现诺兹多姆安然无恙，还向他们反击!$B$B谢谢你，$N!我们将在不久的将来再会。', '你带来了什么消息?青铜巨龙圣地中发生了什么事情?$B$B你发现永恒之龙的领导者是谁了吗?', '保护永恒沙漏', '去龙骨荒野找龙眠神殿的克罗米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12472, '终结', '非常感谢你的义举，弗塔根大人已经下令对塞尔赞发动全面攻击了。第七军团已经开进了陵园的召唤大厅，现在正驻扎在一条仿佛通往地狱的走廊外。现在就缺你一个了。$B$B带着这只护命匣去暮冬陵园那里，向军团司令尤瑞克报到吧。$B$B要塞外面有一条天灾军团挖出的隧道，你可以从那里抄近路。现在就去，$N！带领我们走向胜利吧！', '带着塞尔赞的护命匣转至龙骨荒野的暮冬陵园，向军团司令尤瑞克报到。', '等你准备好以后，我会将骨匣放在门前召唤赛尔赞出来。', '<约立克放松的叹了口气。>$B$B我们还以为你不会出现呢，$N。', '', '去龙骨荒野找暮冬陵园的军团司令尤瑞克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12475, '隐藏的秘密', '自从在遗忘海岸叛变之后，阿尔萨斯王子就开始寻找霜之哀伤，而穆拉丁一直陪着他。藏有霜之哀伤的洞穴会不会就在附近呢？它隐藏着怎样的秘密呢？虽然水晶球不能给我答案，但它确实告诉了我一些信息。$B$B在暮冬要塞的东北方有一座血色先锋军的堡垒，那里面的某处收藏着一份地图。水晶球告诉我，这份地图会给我们提供很大的帮助。$B$B去把它拿来！', '暮冬要塞的幻象师瑟里格要你去找到先锋军地图。', '一个洞窟?有可能吗?这没有任何关联性啊!', '你找到突袭军地图了吗?', '', '去龙骨荒野找暮冬要塞的幻象师瑟里格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12476, '血色十字军归来？', '血色十字军，或者说血色先锋军——现在他们这样称呼自己了——最近在暮冬要塞的东北方建起了一座兵营。虽然我们不知道他们为什么来诺森德，但这帮混账显然和过去一样危险。昨天晚上血色先锋军杀死了我们十二个士兵，他们必须为此付出代价，$N。$B$B你现在就到先锋军营地去好好教训他们一顿。', '暮冬要塞的指挥官莱诺尔·风矛要你转至先锋军营地，消灭20个血色先锋军成员。', '希望对这些突袭军员来说，我们的消息已经很清楚了。我希望这些攻击行动足以让他们怀疑是否要继续加入那个组织。', '清空突袭营地，$N。', '', '去龙骨荒野找暮冬要塞的指挥官莱诺尔·风矛。', '杀死血色先锋军成员', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12477, '救赎之路', '你听说过《救赎之路》吗？据说这本日记中记载了阿比迪斯将军的预言。它提到了血色十字军的狂热动机和目的——还有许多其它胡扯的内容。$B$B你现在就到暮冬要塞东北方的先锋军营地去，从他们的士兵身上拿一本《救赎之路》回来。', '将《救赎之路》带回龙骨荒野的暮冬要塞，交给高级指挥官哈尔弗·维姆班恩。', '<海弗德阅读着这份刊物。>$B$B阿比迪斯已经走火入魔了。圣光跟她说话?$B$B除了空洞的胡言乱语之外，这份刊物让我们一窥血色狂热分子的内心。这是个重要的发现，$N，弗塔根大人会很开心的。', '你找到书了吗?', '', '去龙骨荒野找暮冬要塞的高级指挥官哈尔弗·维姆班恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12478, '霜之哀伤洞穴', '他们把这处山洞称为霜之哀伤洞穴。我们还不知道为什么血色先锋军会对此感兴趣，但据我们所知，该地区周围都有重兵把守。无论如何，我们必须勇往直前！$B$B带着这颗水晶球从镇子北方出去，然后转至西北方的血色哨站。你要进入洞穴并一直杀到最深处去。到那里以后，使用水晶球，然后回来把你的发现都告诉我。', '龙骨荒野暮冬要塞的幻象师瑟里格要你在霜之哀伤洞穴深处使用瑟里格的占卜宝珠，解开尘封的秘密！', '穆拉丁还活着?怎么可能?我得马上通知铜须国王!$B$B我得再检查宝珠，一定还有其它的情报–就在某处!', '搜过霜之哀伤洞窟了吗?', '', '去龙骨荒野找暮冬要塞的幻象师瑟里格。', '解开尘封的秘密', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12481, '骂阵', '维库人在这事上确实处理得很聪明，幸好我还有其它办法。$B$B他们的首领布约恩非常暴躁。我们用他们的语言拼出了几句脏话，好像提到了他的母亲和大型家畜之类的……我们自己也不是很明白。$B$B把这张纸上内容给他念一念。一旦他追过来，你就把他引到这里来。我们绝对不能让他再活着回去。', '在拜尔海姆对布约恩·哈古德森朗读维库人的脏话，然后把他引到林德尔的伏击点，帮助林德尔杀了他。', '干的好。那个可怜的呆子完全没发现。', '刺杀工作其实并不像看起来的那样迷人。', '', '去嚎风峡湾林德尔的伏击点找林德尔。', '嘲弄布约恩·哈古德森', '击败布约恩·哈古德森', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12482, '进攻尼弗莱瓦', '我们迫切希望复仇港派来增援，帮助我们对抗尼弗莱瓦。如果我们能够尽早夺得那里的控制权，就能在与联盟的对抗中取得巨大的优势。$B$B去尼弗莱瓦看看你能做点什么吧。', '游侠队长艾蕾尔要你转至尼弗莱瓦，杀死5名掠龙战士、4名掠龙符文法师和4条掠龙猎犬。', '做的好，$N。当复仇台地的部队抵达时，我们就可以解决剩下的维库人。', '你好，$N。', '', '去嚎风峡湾找幽刃岗哨的游侠队长艾蕾尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12483, '蘑菇汤！', '你瞧，既然你已经到了这里，不如帮老普雷蒙一个小忙怎么样？我有一个朋友，会煮一种非常好吃的菜——你从来没尝过的美味！$b$b这附近有他需要的食材，就在西南边的废墟和北边的营地里。$b$b你觉得怎么样，伙计？', '岩石之泉的普雷蒙要你在达克辛废墟中收集5份幽光雪菇和5份冰蛇之眼，再到塞布哈拉克去收集5份甜根茎。', '哦，老兄 - 炖幻光菇!我好像都尝到它的味道了…', '你替老皮格蒙收集到那些食材了吗，$N?', '', '去灰熊丘陵找岩石之泉的普雷蒙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12484, '清理天灾', '呃。$b$b要把这些可怜的巨魔清理掉让我很心疼，但不如我的背疼！$b$b帮老普雷蒙一个忙，把这拖到马克那里去。$b$b如果我们不把它们清理掉，它们很快又会变得活蹦乱跳了。', '岩石之泉的普雷蒙要你把一具僵化的巨魔尸体拖到马克·菲尔森那里，并把它用高温处理掉。', '没什么比看着天灾军烧掉更棒的啦…<嗝>。$B$B我还写了首小曲呢。想听吗?就是这样…', '你那儿有什么，$r?', '', '去灰熊丘陵找岩石之泉的马克·菲尔森。', '处理僵尸', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12491, '科林的烈酒', '断气的科林·烈酒手中还紧紧抓着一只小酒桶。这大概就是他所酿造的臭名昭着的烈酒吧！', '将科林的烈酒交给铁炉堡附近美酒节营地的埃菲库格·铁桶。', '这就是寇仁.恐酒的饮料?他急着想要在啤酒节提交的酒?嗳，官方无法认可这次的提交，不过出于对一位逝去酿酒者的尊敬，也许我会尝一尝……', '$N，你的表情看起来很严肃。有什么可怕的消息吗?', '', '去找丹莫罗的埃菲库格·铁桶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12492, '科林的烈酒', '断气的科林·烈酒手中还紧紧抓着一只小酒桶。这大概就是他所酿造的臭名昭着的烈酒吧！', '将科林的烈酒交给奥格瑞玛附近美酒节营地的塔波尔·斯威雷格。', '啊，所以恐酒最后还是提交了他的酒。真是可惜，他得以性命来完成提交…$B$B喔，这个嘛。干杯吧，嗯?', '嘿，$N，你的脸都脏了!你是去过黑石深渊吗?', '', '去找杜隆塔尔的塔波尔·斯威雷格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12498, '红龙之翼', '用这枚信标召唤一头龙眠征服者，骑上它飞往北面的迦拉克隆之墓，指挥它去消灭那些正在挖掘迦拉克隆骨架的废土挖掘者。等到整个地区都清理干净之后，飞去迦拉克隆之墓旁的邪恶之旋，消灭通灵主宰安提沃克，取回那把他用以控制冰霜巨龙的镰刀。$B$B完成这个任务后，去向阿莱克丝塔萨汇报，她会给你一份英雄应得的奖励！$B$B$N，小心在这一地区徘徊的腐烂的风暴巨人！', '消灭30个废土挖掘者并夺取安提沃克的镰刀。完成这个任务之后，回到龙眠神殿去找阿莱克丝塔萨，生命的缚誓者。', '我知道你会回来的，$N。你为龙眠联军做了很多，也从必然的死亡之中拯救了你的人民。让所有人都知道这件事，并且让它永远流传下去!', '在事情太迟之前消灭葛拉克朗安息地的天灾军!', '', '去龙骨荒野找龙眠神殿的阿莱克丝塔萨，生命的缚誓者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12501, '巡逻员', '拔出你的武器，$r。巡逻的时候到了！$b$b我们要拼死保住手中的四座岗哨，这对我们取得胜利有着关键性的意义。我要你去逐一巡查这几处岗哨，并向他们提供帮助。$b$b你可以从东南方的布兰顿上尉那里开始。等你完成他指派的任务后，他就会指引你去下一座岗哨。$b$b巡查完所有四座岗哨后再回来向我复命。记住——你回来得越快，报酬就越丰厚！所以给我动作麻利一点！$B$B解散！', '银色前沿的指挥官库恩斯要你拜访四座银色北伐军的岗哨，并完成那里的上尉交给你的任务，然后回去向他复命。$b$b布兰顿上尉和鲁伯特上尉驻扎在达克索塔。$B$B格隆迪尔上尉驻扎在达克迦尔。$B$B炼金师菲肯斯坦驻扎在赫布瓦罗。', '嗯，$N，至少你活着回来了。我想这值得一些奖励……', '有什么来自岗哨的消息吗，$r?', '', '去祖达克找银色前沿的指挥官库恩斯。', '布兰顿上尉的任务', '鲁伯特上尉的任务', '格隆迪尔上尉的任务', '炼金师菲肯斯坦的任务');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12503, '保卫银色前沿', '尽管我们在祖达克的下层本地取得了重大胜利，但还是要对面天灾军团的猛攻。在这个冰封的地狱里，事情就是这样。$B$B进攻总是一波接一波，可我的部队需要休息。如果你愿意帮忙，就请你去支持他们吧。$B$B在下面的庭院里，我的部队正在与天灾军团没日没夜地战斗。带着你的全部热情去干掉那些天灾士兵吧，$c。', '指挥官法斯塔夫要你到银色前沿的庭院中去，消灭任意10个天灾军团士兵。', '非常感谢你对这件事的帮助。如果没有你的努力，我们可能很难抵抗住那些不死生物的进攻。', '或许你可以再多杀一点?', '', '去祖达克找银色前沿的指挥官法斯塔夫。', '杀死银色前沿的天灾士兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12504, '银色北伐军，撤退！', '<中士很快读完了你交给他的命令，皱起了眉。>$B$B你看，$g小伙子:小姐;，我是很愿意卷铺盖走人的，但请你到外面去看看。我的人都在战斗。$B$B我跟你说，既然你已经来了，能帮我一个小忙，把我的士兵聚集起来好吗？$B$B告诉他们说，中士要他们立刻回来复命。如果你愿意的话，可以顺便帮帮他们。', '西莱图斯祭坛的斯塔哈默中士要你和10个银色士兵交谈，让他们回去向他复命。', '太好了。我们已经集合剩下的人并准备回到平台。$B$B真是丢脸，我们必须这么快就离开这里。我一点都不觉得在这里的工作已经完成了，而且坦白的说，我觉得祭坛前的预言者将会是个大麻烦!', '我需要更多的士兵回来回报。', '', '去祖达克找西莱图斯祭坛的斯塔哈默中士。', '让银色士兵回去向中士复命', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12505, '给斯塔哈默中士的新命令', '$C，你是来帮忙的，对吗？我对部署在北方达卡莱祭坛的部队有新的指示。$B$B那地方很容易找，只要沿着大路走就到了。到那边之后就去找斯塔哈默中士。', '指挥官库恩斯要你把调度命令交给西莱图斯祭坛的斯塔哈默中士。', '<这位矮人中士小心翼翼地看着你手中的指令。>$B$B那是要给我的新指令吗，$g先生:小姐;?', '这里面是什么?', '', '去祖达克找冰冷裂口的斯塔哈默中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12506, '西莱图斯祭坛的麻烦', '蛇神的祭坛那里有些麻烦。$B$B天灾军团的出现削弱了这片土地，$r。而这也削弱了那些原始神灵。$B$B我们知道那些达卡莱巨魔正在利用这个机会对这些神灵做某种邪恶的事。$B$B我要你充当我的耳目。西莱图斯祭坛就在通往北边的大路尽头。你要从背面潜入祭坛的主建筑里去看一眼。$B$B无论你怎么做，一定要避开那个先知！', '银色前沿的妖术师乌布戈要你去调查西莱图斯祭坛的主建筑。', '亡灵?$B$B<妖术师的灵魂明显被你所带来的消息影响。>$B$B他们杀掉了西莱图斯，并深饮了他的魔精;尤其是预言者!$B$B我们必须想出一个方法来除掉他，以免他再喝掉更多的魔精!', '你看到了什么，$r?', '调查西莱图斯祭坛的主建筑。', '去祖达克找银色前沿的妖术师乌布戈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12507, '奇怪的魔精', '这瓶奇怪的魔精也许可以解释这里所发生的一切。$B$B银色前沿的赞达拉巨魔——妖术师乌布戈可能会对这东西感兴趣。', '把奇怪的魔精交给银色前沿的妖术师乌布戈。', '那是疯狂神只的魔精，$C!$B$B这是不祥的!', '你找到了什么?', '', '去祖达克找死亡旷野的妖术师乌布戈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12508, '扫清巨魔', '很抱歉我听到了你和中士的谈话。虽然上面来了命令，但我们在这里仍然有事情要做。$B$B你出去的时候，能帮我们把一些西莱图斯的追随者从痛苦中解放出来吗？', '西莱图斯祭坛的玛加下士要你杀死任意10个西莱图斯勇士、西莱图斯祭司或达卡莱驯蛇者。', '谢啦，$C。我实在不喜欢在没有完成我们前来这里的使命前就动身离开。', '考虑再多杀一点吗?', '', '去祖达克找西莱图斯祭坛的玛加下士。', '杀死西莱图斯的追随者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12510, '珍贵的元素液体', '<妖术师仔细研究了装着魔精的瓶子。>$B$B我知道怎么对付西莱图斯的先知了。但首先，我们需要一些东西。$B$B达克索塔农田就在正南方。由于天灾军团入侵和原始神灵的死亡，诸界间的藩篱已经越来越脆弱了，许多元素生物借此机会涌了进来。$B$B我们要从它们的首领身上弄一些珍贵的元素液体来。如果你能把那些元素生物身上的三条锁链连在一起，它们的某个首领就会出现。', '银色前沿的妖术师乌布戈要你收集3份珍贵的元素液体。', '太好了。和魔精结合的话，这液体可以稀释魔精的效果却又不会完全消灭它。$B$B现在，还有一件事要做。', '你拿到珍贵液体了吗?', '', '去祖达克找银色前沿的妖术师乌布戈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12512, '一个也不能少', '啊，太好了。他们终于派人来了。$b$b听着，$r。我们需要帮助。我们的部队被击退了，达克索塔已经落入了天灾军团手里。没人知道他们是从哪里冒出来的……$b$b关键是，我们需要一切可以找到的人手，但我们最棒的几个士兵还没有从战场上回来。$b$b我要你立刻进入废墟中去，找到那些伤员，帮他们包扎好，然后把他们带回来。他们都是老兵，所以可能会隐蔽起来。找不到他们就别回来见我！$B$B就在达克索塔一带找！他们应该走不远。', '达克索塔的罗杰斯博士要你找到北伐军战士拉莫夫、北伐军战士乔纳森和北伐军战士约瑟芬。对他们使用北伐军的绷带，并护送他们安全回来。', '全都救回来了，是吗?真杰出!$B$B或许你会想要在岗哨这待下来?我们肯定用得到像你这样的人才……', '你救回我们的精兵了吗，$N?', '', '去祖达克找达克索塔的罗杰斯博士。', '营救北伐军战士乔纳森', '营救北伐军战士拉莫夫', '营救北伐军战士约瑟芬', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12513, '好帽子……', '我的帽子？是啊，那顶帽子的款式非同寻常，很早以前的事儿啦……如今可没几个裁缝知道怎么缝制。$B$B年少轻狂的时候，我将它当作身份的象征。很多人想要击败我，赢得那顶帽子……可惜没人成功。$B$B啊，这些都是陈芝麻烂谷子的事了。我已经老了，每天喝喝酒，钓钓鱼，早就不与人决斗啦。', '卡洛斯要你进入旧希尔斯布莱德，击败年轻时候的卡洛斯。然后将他的帽子交给塔纳利斯的卡洛斯。', '我…我的帽子!那么…那个人就是你。我就知道。你靠近我的时候，旧疤就隐隐作痛，但是…太年轻了!你一点都没变!$B$B好吧…所以现在你知道我的秘密了。我“曾经”被打败了…来吧:拿着这顶帽子，作为我的酬谢。它本来就是你的。', '那时候，我是无人可敌的…如此的骄傲，太骄傲了。从来没有任何挑战者赢得这顶精美的帽子……', '', '去找塔纳利斯的卡洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12514, '蘑菇混合剂', '现在我们要找一种东西，把它混入魔精，让先知喝了它以后非但不会变强，而且被大大削弱。$B$B东边的达克迦尔生长着一种蘑菇，当地的原住民称之为混乱毒菇。我想这就是我们要找的东西。$B$B帮我多采一些混乱毒菇回来，等我们把这些蘑菇混入魔精里面后，喝了它的人就会变得糊里糊涂的。', '收集10份混乱毒菇，将它们交给银色前沿的妖术师乌布戈。', '<妖术师点头赞许。>$B$B把那个菌种交给我，我会将它混进魔精和元素之王的液体之中。', '你取得所有的菌种了吗?$B$B喔，还有，小心潜伏在那里的蜥蜴。', '', '去祖达克找银色前沿的妖术师乌布戈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12515, '好帽子……', '我的帽子？是啊，那顶帽子的款式非同寻常，很早以前的事儿啦……如今可没几个裁缝知道怎么缝制。$B$B年少轻狂的时候，我将它当作身份的象征。很多人想要击败我，赢得那顶帽子……可惜没人成功。$B$B啊，这些都是陈芝麻烂谷子的事了。我已经老了，每天喝喝酒，钓钓鱼，早就不与人决斗啦。', '卡洛斯要你进入旧希尔斯布莱德，击败年轻时候的卡洛斯。然后将他的帽子交给塔纳利斯的卡洛斯。', '我…我的帽子!那么…那个人就是你。我就知道。你靠近我的时候，旧疤就隐隐作痛，但是…太年轻了!你一点都没变!$B$B好吧…所以现在你知道我的秘密了。我“曾经”被打败了…来吧:拿着这顶帽子，作为我的酬谢。它本来就是你的。', '那时候，我是无人可敌的…如此的骄傲，太骄傲了。从来没有任何挑战者赢得这顶精美的帽子……', '', '去找塔纳利斯的卡洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12516, '过犹不及', '喏，我已经重新调配过这瓶魔精了。现在先知只要喝下它，就会失去一部分力量，而且还会变得昏头昏脑。$B$B至少理论上是这样的。$B$B至于说如何能让他喝下这玩意，我想也许你只需把魔精扔给他就行了？根据他在祭坛上表现出来的傲慢态度来看，他肯定会直接喝下去的。$B$B除非你能杀了他，$c，否则你们的银色北伐军一定会落得无比悲惨的下场。', '杀死混乱的西莱图斯先知，然后向银色前沿的妖术师乌布戈复命。', '太惊人了!你拯救了你的人民和诺森德其馀的人免于他的疯狂荼毒。$B$B不幸的是，在祖尔德拉克更高处仍有更多这类型的疯子存在。', '结束了吗?$B$B调整过的魔精有效吗?$B$B你杀掉西莱图斯的预言者替他报仇了吗?', '', '去祖达克找银色前沿的妖术师乌布戈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12517, '盗贼套牌', '你现在已经收集到了盗贼套牌的所有卡片，一张新的卡片神秘地出现在你手中。卡面上描绘着一位占卜师，无论你把卡片转动到何种角度，占卜师似乎都在盯着你。$B$B你觉得似乎可以用这张卡片来联络某些人，或某些事物。', '使用盗贼套牌召唤一位暗月占卜师，并把套牌交给占卜师。', '暗月马戏团对这些塔罗牌很有兴趣，如果你收集到更多的卡片，不要犹豫，立刻呼唤我们。我们也有自己的商人，所以请让我提供一些东西，来与你交换这些卡片。', '看来你弄到了整套的群盗套卡!令人印象深刻。', '', '去找暗月占卜师。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12518, '法师套牌', '你现在已经收集到了法师套牌的所有卡片，一张新的卡片神秘地出现在你手中。卡面上描绘着一位占卜师，无论你把卡片转动到何种角度，占卜师似乎都在盯着你。$B$B你觉得似乎可以用这张卡片来联络某些人，或某些事物。', '使用法师套牌召唤一位暗月占卜师，并把套牌交给占卜师。', '暗月马戏团对这些塔罗牌很有兴趣，如果你收集到更多的卡片，不要犹豫，立刻呼唤我们。我们也有自己的商人，所以请让我提供一些东西，来与你交换这些卡片。', '看来你已集满全套的法师套卡!恭喜!', '', '去找暗月占卜师。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12519, '巡逻员：你想要勋章？', '你看看我，$r。你看我像是有时间写报告的样子吗？$b$b我正在尽力保卫这座岗哨不被该死的天灾军团攻陷，而他们却要我来做文案工作！$b$b<叹气> 抱怨是没有意义的。我要向指挥官报告上次战斗的杀敌人数。$b$b你想帮忙吗？去翻一翻附近的巨魔尸体，把所有你能找到的勋章带回来给我，勋章的数量应该跟我们杀敌的数字相差不多。', '斗兽场外面的格隆迪尔上尉要你从附近的达卡莱尸体上收集7枚达卡莱勋章。', '嗯，好!$B$B你帮我省了不少麻烦啊$g孩子:女孩;。我很感激。我会记得在报告上提到你的。$B$B你现在可以走了，菲肯斯坦应该在西边不远处等着你。', '你帮我弄到那些勋章了没，$r?', '', '去祖达克找痛苦斗兽场的格隆迪尔上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12520, '狩猎犀牛：初试身手', '就算是迫降，也不会败了老子征服索拉查盆地这片原始丛林的兴致。你瞧，营地西北方生活着许多健壮的碎角犀牛，它们是这片丛林的统治者。如果你想对探险队证明自己的实力，就去挑战这些凶猛的野兽吧。', '杀死15头碎角犀牛，然后返回奈辛瓦里营地，向赫米特·奈辛瓦里复命。', '不错，不错，不错，看来你从犀牛角下活了下来，毕竟你看起来还身体完整。不过犀牛狩猎可不只是当犀牛往你冲的时候死盯着它，然后祈祷自己瞄得够准。不，要制服传说中居住在丛林里的犀牛族王，你还需要更多技巧。', '你制服了犀牛吗，还是你丢毛巾投降了?', '', '去索拉查盆地找奈辛瓦里营地的赫米特·奈辛瓦里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12522, '需要引擎', '毁了……全毁了！我早就提醒过船长，让她小心运送精密的仪器，她怎么就不把我的话当回事呢！$B$B由于她的疏忽，导致我的飞行器“诺莫瑞根之魂”在这艘船触礁搁浅时被撞坏了。这下完蛋了吧，我们连报告都没法送出去了！$B$B不过，天无绝人之路！风险投资公司的地精或许能帮上我们。前些日子，他们击落了另一架飞行器。喏，残骸就落在东边的沼泽地里，也就是蒙特跳伞着陆的地方。我要你去回收它的引擎，这很可能是我们唯一的希望了。', '奈辛瓦里营地的维斯雷·扭钳要你帮他找到一台飞行器引擎。', '那…把东西放那就好了。小心点!如果你弄坏了这一部，我们就有大麻烦了。现在，看看我能够做些什么。', '嗳，你有办法拿到引擎吗?我只知道资助远征队的大法师要紧张了。', '', '去索拉查盆地找奈辛瓦里营地的维斯雷·扭钳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12523, '借零件', '很好，我们有了一台能用的引擎。接下来嘛，只要替换飞行器的部分零件，就能让她正常运转啦。别担心，我知道自己在做什么。$B$B优秀的机械师可以使用最烂的材料修复他的发明创造！不过，如果能找到合适的材料，那自然是再好不过啦。$B$B风险投资公司在斯温迪格林挖掘场中作业，那里到处散落着采矿设备的备用零件。喏，挖掘场就在东北方那根黄色水晶柱的另一端。替我弄一些零件回来吧。', '将7份风险投资公司备用零件交给奈辛瓦里营地的维斯雷·扭钳。', '只要小小的调整，应该就能用了。我可怜的飞行器可能到最后会看起来像是台风险投资公司的伐木机。可怜的小女孩，得等我们回到达拉然，才有办法变响应有的样子了。', '你拿到零件了吗?', '', '去索拉查盆地找奈辛瓦里营地的维斯雷·扭钳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12525, '工头斯温迪格林', '我们必须干掉工头斯温迪格林，才能彻底让他们的矿洞完蛋。但这家伙随身带着一个名叫“肉饼”的食人魔保镖。看来不经过一番激烈的搏斗，你是见不着工头的。$B$B他们很可能呆在高处的平台，监视着风险投资公司在斯温迪格林挖掘场的工作进展。$B$B挖掘场就在东北方的日灼之柱的另一端。祝你好运，$N。', '杀死工头斯温迪格林和肉饼，然后返回奈辛瓦里营地，向蒂巴尔复命。', '听到风险投资公司不会再妨碍我们，可真叫人松了一口气。你处理了这个问题，我和赫米特都很感谢你。一个猎人可不能在举起枪对着别人的时候，还有什么良心之类的问题。', '你解决了诈咧与他的保镖吗?', '', '去索拉查盆地找奈辛瓦里远征队营地的蒂巴尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12527, '贪吃的蜥蜴', '我的主人菲肯斯坦正在西北方的赫布瓦罗制作一种真言药剂，他需要大量的石化蜥蜴水晶作为材料。赫布瓦罗就在这条通往北边的西莱图斯祭坛的大道西侧。$B$B幸运的是，东边的达克迦尔就潜伏着不少蜥蜴。$B$B如果你能抓一些祖达克老鼠，把它们扔给蜥蜴吃的话，那些蜥蜴在吃掉五只老鼠以后就会变得很温顺。然后你就可以安全地从它们身上取走水晶了。$B$B杀死蜥蜴是没有用的……那样只会把水晶弄碎。', '将5块石化蜥蜴水晶交给赫布瓦罗神殿的炼金师菲肯斯坦。', '喔，太棒了!感谢你。水晶看起来的状况很不错!$B$B我一点也不怀疑捣盆让你替他做了他的工作。不过，你的协助还是非常有价值!', '这些是什么?$B$B你有看到我那个没路用的学徒，捣盆吗?$B$B我派他去办点事情，他搞了半天还不回来!', '', '转至祖达克，去找赫布瓦罗的神殿中的炼金师菲肯斯坦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12529, '猩猩猎手的奴隶', '你？伟大的猎手？你根本不属于狂心氏族，也配谈论狩猎的技巧？$B$B格拉克伊克，他才算得上是真正的猩猩猎手。要说死在他手里的猩猩，你数也数不清。$B$B你，跟着他。去东边猎杀硬皮猩猩吧。记住，你只是个奴隶，凡事都照格拉克伊克说的做。', '狂心岭的高阶萨满祭司拉克亚克要你去杀死8只硬皮抢夺者和6只硬皮冲锋者。$B$B如果你弄丢了格拉克伊克的镣铐，就去找狂心岭的长者哈尔卡克。', '苟瑞格克让笨$r奴隶见识过怎么做了。', '你还活着!硬拳还没把你吃了?$B$B也许他们晚点会把你吃了。', '', '去索拉查盆地找狂心岭的高阶萨满祭司拉克亚克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12530, '狩猎硬皮猩猩', '嘿！奴隶！$B$B拉克亚克要我带上你外出狩猎硬皮猩猩，换了平常我才不乐意呢。不过今天我的心情很好，所以打算也让你过过瘾。但是，你最好别给我惹麻烦！$B$B拉克亚克还不知道吧，其实我早就想对那只坏坏的雌性硬皮猩猩下手了。我们去东边的硬皮旷野，对软皮猩猩使用软皮木棍，这样就能迫使她显身啦！$B$B<格拉克伊克兴奋地摩挲着双手。>', '对软皮猩猩使用格拉克伊克给你的软皮木棍，将雌性硬皮猩猩引出来。击败雌性硬皮猩猩，然后向狂心岭的高阶萨满祭司拉克亚克汇报情况。$B$B如果你弄丢了格拉克伊克的镣铐，就去找狂心岭的长者哈尔卡克。', '苟瑞格克带你去杀死了硬拳的兽穴之母，嗯?你很幸运!$B$B那些愚蠢的软拳一定悦耳地大声尖叫!$B$B<拉克杰克大声地尖啸，然后突然大笑起来。>', '你要做什么，奴隶?', '', '去索拉查盆地找狂心岭的高阶萨满祭司拉克亚克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12531, '地下的威胁', '啧啧，狮子杀手，捕鸡者，新来的奴隶……$B$B我知道你不愿意当一辈子奴隶，所以啊，我来告诉你要如何获得自由的身份。你必须证明自己比其它猎手更厉害，才能赢得拉克亚克的尊重。$B$B在南部河流的沙地下，生活着一只名叫瑟菲克斯的野兽。蓝蜂、猩猩，甚至狼獾人都不是它的对手。如果你能将瑟菲克斯的爪子交给拉克亚克，或许他会考虑解除你的奴隶身份。$B$B希望达伊克能教你对付瑟菲克斯的诀窍。', '转至南部河流的沙滩，找到并杀死瑟菲克斯，将他的爪子交给狂心岭的高阶萨满祭司拉克亚克。$B$B如果你弄丢了达伊克的旧粉笔，就去找狂心岭的长者哈尔卡克。', '你杀死了瑟菲克斯?我打赌你一定跟踪一只杀死瑟菲克斯的强大獾狼怪，然后偷走了爪子。$B$B爪子现在是我的了。', '我并没有找你，$r。你要做什么?', '', '去索拉查盆地找狂心岭的高阶萨满祭司拉克亚克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12532, '鸡飞狼跳！', '格利基克没头没脑地闯入鸡舍，结果鸡们受到惊吓，全都逃掉了！$B$B它们就在附近——替我把它们抓回来！$B$B<长者哈尔卡克发出嘘声，催你赶紧去抓鸡。>', '捕捉12只逃走的小鸡，然后向长者哈尔卡克复命。$B$B如果你弄丢了达伊克的旧粉笔，就去找狂心岭的长者哈尔卡克。', '好!我还担心食物呢。我已经饿了。$B$B谢谢，$r。', '你抓到鸡了吗?', '', '去索拉查盆地找狂心岭的长者哈尔卡克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12533, '蓝蜂猎手的学徒', '拉克亚克又不蠢。或许你真的很擅长捕杀猎物。说不定狂心氏族可以将你培养成真正的猎手。$B$B说到狩猎巨型蓝蜂的本事，达伊克是所有狼獾人中最厉害的。你跟他去东南方的蓝玉虫巢或者南部的河流附近，好好学习吧。', '狂心岭的高阶萨满祭司拉克亚克要你杀死6只蓝玉虫巢巨蜂和9只蓝玉虫巢雄蜂。$B$B如果你弄丢了达伊克的旧粉笔，就去找狂心岭的长者哈尔卡克。', '我们杀很多黄蜂。$B$B拉克杰克觉得它们杀不完。', '你学会狩猎了没有?', '', '去索拉查盆地找狂心岭的高阶萨满祭司拉克亚克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12534, '蓝色蜂后', '钢刺野猪虽然颇具威胁，但它们大多生活在远离狼獾人的本地。蓝蜂就不同了，这种可怕的巨型蜂接连杀死了狂心氏族的好几名猎手……$B$B拉克亚克一直想除掉蜂后，可是最厉害的猎手也没有勇气踏足她的巢穴。我要你进入东南方的蓝玉虫巢杀死那里的蜂后，然后把她的钉刺交给拉克亚克。我敢打赌拉克亚克会欣喜若狂的。', '将蓝玉虫巢蜂后的钉刺交给狂心岭的高阶萨满祭司拉克亚克。$B$B如果你弄丢了达伊克的旧粉笔，就去找狂心岭的长者哈尔卡克。', '你杀掉女王蜂了!你比拉克杰克还强。$B$B也许现在黄蜂会走开，停止攻击狂心猎人们。', '你闻起来很像黄蜂之类的。', '', '去索拉查盆地找狂心岭的高阶萨满祭司拉克亚克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12535, '恶作剧的材料', '你是个好猎人，但我们能让你变得更厉害。哈尔卡克认为现在是时候让你承担重任了。$B$B不过呢，在派你执行重要任务之前，我要你先去收集一些东西。瞧，南面的河流沿岸分布着许多蓝水晶。拉克亚克需要很多很多蓝水晶。$B$B你这就去收集一些。', '狂心岭的高阶萨满祭司拉克亚克要你去收集8块通天水晶簇。', '好$r!好，都准备好了。', '差不多准备好长途旅行了。杰克杰克刚刚带鳄鱼回来了。', '', '去索拉查盆地找狂心岭的高阶萨满祭司拉克亚克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12536, '颠簸的航行', '瑟匹克是狂心氏族最优秀的猎手。他擅长狩猎大舌头怪……嗯，就是沼泽地里那群什么东西都要偷的丑八怪。$B$B瑟匹克打算出趟远门，摧毁大舌头怪的祭坛，把它们统统吓跑。我们要把这些家伙赶出这片土地。$B$B狂心岭的东北边锁着一只鳄鱼，就在大树旁——你和瑟匹克一起去，照他说的做就是了。', '骑上被俘虏的鳄鱼转至雾语村，向瑟匹克寻求下一步的指示。$B$B如果你弄丢了瑟匹克的狩猎号角，就去找狂心岭的长者哈尔卡克。', '我们到了!一定要快。$B$B小心大舌头。', '他们跟赛匹克说不以狂心族人标准来看的话，你是个好猎人。', '抵达雾语村。', '去找鳄鱼人猎手瑟匹克。如果他不在附近的话可以用瑟匹克的狩猎号角召唤他。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12537, '闪电确实两次打中同一个地方！', '嗯，说到水晶……$B$B大舌头怪使用水晶为天气祭坛充能。瑟匹克并不清楚其中的原理，但是一旦它们用错了水晶，就会风雨大作！$B$B原本呢，瑟匹克打算悄悄地潜入一座祭坛，结果却并不顺利。所以啊，还是拉上你一起去比较好！$B$B把这些水晶放在祭坛附近，然后击碎它们，释放其中的能量。瑟匹克也不确定会发生什么事，打破水晶之后你最好躲远点。', '瑟匹克要你在雾语天气祭坛前敲碎通天水晶簇。$B$B如果你弄丢了瑟匹克的狩猎号角，就去找狂心岭的长者哈尔卡克。', '真有效!$B$B你看到闪电打中那个神谕家伙了吗?真棒!$B$B<赛匹克摩擦着他的双手并且狂乱的笑着。>', '赛匹克觉得有同伴一起顺利多了。以不是狂心族人来说你很强。', '破坏雾语村的天气祭坛', '去找鳄鱼人猎手瑟匹克。如果他不在附近的话可以用瑟匹克的狩猎号角召唤他。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12538, '猎杀雾语鳄鱼人', '杀些猩猩和蓝蜂有什么意思啊！狩猎大舌头怪才好玩呢！$B$B在我们破坏天气祭坛的同时，不如趁机多杀几只大舌头怪。这样它们就不敢再来我们的地盘惹事啦。$B$B<瑟匹克自信地点了点头。>', '瑟匹克要你去杀死12个雾语鳄鱼人。$B$B如果你弄丢了瑟匹克的狩猎号角，就去找狂心岭的长者哈尔卡克。', '我狠狠的戳了那些大舌头一顿。$B$B我想你做的还可以。$B$B不，我只是开玩笑!你是好猎人。我很高兴跟你打猎。', '我们是盆地最棒的猎人!', '', '去找鳄鱼人猎手瑟匹克。如果他不在附近的话可以用瑟匹克的狩猎号角召唤他。', '雾语鳄鱼人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12541, '巡逻员：炼金师的帮手', '哈，你一定就是他们提过的那个巡逻兵吧。你来得真是太及时了，我正急需帮手呢。$b$b我们抓到了一个达卡莱俘虏，正准备审问他。不过在审讯开始之前，我需要你帮忙制造一种真言药水。$b$b制造真言药水是非常复杂的活，需要保持敏锐的直觉、完美地把握时机，并在每一个制作环节上都有即兴发挥的能力。$b$b你准备好以后就告诉我吧，$r。记住，对时机的掌握至关重要。', '赫布瓦罗的炼金师菲肯斯坦要你帮他制作真言药水。$b$b准备好以后与他交谈，并按照他的指示行动。', '你做到了!$B$B从巨魔口中取得的消息非常有价值。我一定会在给指挥官的报告中提到你的功劳。$B$B感谢你，$N。', '看吧，$N，真正的炼金术远不只是仅仅混和几种材料……', '', '去祖达克找赫布瓦罗的炼金师菲肯斯坦。', '制作真言药水', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12543, '给索乌拉姆的祭品', '陌生人，我们并不认识你，但是我们知道你来此的目的。$B$B想要让我与诺兹隆之骨交谈，就必须奉上祭品。我们需要眼镜王蛇的毒牙来给神谕者制作项链。$B$B转至东北方的蛮藤谷吧，找到眼镜蛇，取回完整的毒牙。然后，我们自然会让你与诺兹隆之骨对话。', '将5颗完整的眼镜蛇牙交给诺兹隆之骨附近的神谕者索乌拉姆。', '<神谕者查看了牙齿。>$B$B我们同意!诺兹朗的骨头将和$N讲话!', '我们得知道 -- 你带牙齿来了吗?', '', '去找索拉查盆地的神谕者索乌拉姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12544, '诺兹隆之骨', '诺兹隆之骨，神谕者索乌拉姆请求您为$N解惑！$B$B我们已经为你备好了熏香。你只需在诺兹隆的头部附近将它点燃，就能听到他的解答了。$B$B<你心中充满疑惑，对索乌拉姆说，你还没有说出是什么问题呢。>$B$B我们确实不知道你想问什么，但是伟大的诺兹隆知道。不用怀疑。诺兹隆会为你解答心中的一切疑问。$B$B去吧，别让诺兹隆等太久。', '在诺兹隆之骨附近使用索乌拉姆的熏香，然后返回奈辛瓦里营地，向赫米特·奈辛瓦里汇报你得到的情报。', '<赫米特听着你描述你所得知的事情。>$B$B该走的方向，$g孩子:女孩;。没有任何死犀牛可以跟赫米特.奈辛瓦里说他该去哪里，能猎捕些什么。我们会做给那堆烂骨头看。', '嗯，你询问过当地的神谕者了吗?', '', '去索拉查盆地找奈辛瓦里营地的赫米特·奈辛瓦里。', '找到法鲁恩的位置', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12545, '净化金萨卡拉', '我们从一群天灾侵略者手中夺回了这座古老的达卡莱神殿。不到一百码以外，就是金萨卡拉城的废墟。天灾通灵师在那里大肆杀戮，将活着的达卡莱巨魔转变为巫妖王的奴仆。$B$B所有的一切都不再属于圣光了，因此所有的一切都必须得到净化。$B$B<瓦鲁斯无情地看着你。>$B$B所有的一切。', '龙骨荒野圣光之望礼拜堂的北伐军战士瓦鲁斯要求你去消灭15个金萨卡拉天灾成员。', '如你所见，天灾军的战争机器不断的往前逼近，而部落和联盟的军队却还是彼此分裂，正成了他们的牺牲品。这就是我们必须团结的理由。$B$B<瓦鲁思短暂地沉浸在冥想中。>$B$B银色北伐军用的着像你这样的$g男人:女人;，也许你有意愿加入我们?在灰烬使者的身边至死奋战?', '不要留下任何东西给巫妖王复活!', '', '去龙骨荒野找圣光之望礼拜堂的北伐军战士瓦鲁斯。', '消灭金萨卡拉的天灾成员', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12546, '力挽狂澜', '时机成熟了，$N。源生石像是泰坦的诸类造物中杀伤力最强的武器之一，我本不愿在这片圣洁的土地上释放他的力量。$B$B但是，我别无选择。入侵者已经将我逼入绝境，就让泰坦的怒火将他们烧得一干二净吧。', '转至索拉查盆地的雪崩山麓，使用欧米伽符文操纵源生石像，消灭200名天灾军团的爪牙、血肉塑造者拜休斯、千墓之魔乌格雷斯和海斯克恩。$B$完成任务后与索拉查盆地的弗蕾亚的化身谈一谈。', '我很感激你的协助，$N。我的责任是看管这片土地，以及居住在其上的生物们。$B$B感谢你，这些生命能在死亡盘据边境的时候继续繁衍。$B$B你的行为不会被遗忘的。', '威胁生命的家伙们…你已经解决他们了吗?', '', '去索拉查盆地找雨声河的弗蕾亚的化身。', '杀死天灾军团爪牙', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12547, '引导符文', '这尊巨大的石像仿佛陷入了沉睡。你注意到它的胸前有一块符文形状的凹槽。$B$B或许你可以在附近找到那块失踪的符文。', '在塑造者之台内找到欧米伽符文，将它带至源生石像身边。', '<当伊提米迪安活动起来的时候你听见石头的摩擦声。>$B$B有哪里需要我吗?', '<伊提米迪安胸口的符文状凹槽似乎闪动着微弱的能量光芒。>', '', '去找安戈洛环形山的源生石像。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12549, '狩猎恶刃豹：成为猎手', '如果你和赫米特一起打过猎的话，就该知道他能轻而易举地应付多种大型猫科动物。但是索拉查盆地的恶刃豹却不然，这种凶残而敏捷的野兽比我见过的所有猫科动物都要凶狠。只有真正的猎手，才能征服这样的猎物。$B$B如果你愿意接受挑战，就勇敢地面对恶刃豹吧。营地四周的荒野以及河流南岸都有它们的踪迹。', '杀死15只恶刃豹，然后向奈辛瓦里营地的巴克·坎维尔复命。', '嗯，你已经证明了你是个能干的猎人，但你跟踪的本领又如何呢?', '你在惧刃豹身上测试过你的技巧了吗?', '', '去索拉查盆地找奈辛瓦里营地的巴克·坎维尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12550, '狩猎恶刃豹：跟踪猎物', '我曾听这里的土着提到过一只名叫杉苟的巨型恶刃豹，据说它相当富有传奇色彩。可惜我至今也没发现这家伙存在的证据。你看，我身负重伤，自然是没法离开营地进行实地调查的。$B$B如果你自认为在跟踪方面有丰富经验的话，不如帮我去探寻这件事的真相吧。蒂巴尔说她上次外出时发现了一些大脚印。我要你转至营地北边的苦潮湖，在湖的南岸寻找恶刃豹的脚印。', '奈辛瓦里营地的巴克·坎维尔要你从苦潮湖附近的恶刃豹足迹中鉴别出3条杉苟的足迹。', '<巴克听着你复述你的发现。>$B$B我想你也许真的找到了这个尚戈的证据。而且我想我知道我们该去哪里找它。', '跟踪进行的如何了?', '', '去索拉查盆地找奈辛瓦里营地的巴克·坎维尔。', '鉴别杉苟的足迹', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12551, '狩猎鳄鱼：试炼', '陌生人，我警告你：禁止对沉船的事情做任何评论。探险队那帮喋喋不休的家伙已经令我不胜其烦了。$B$B不过，如果你只是想检验一下自己的狩猎技术，我推荐你先用蛮藤谷鳄鱼试试身手。这些狡猾的野兽生活在南边的河流沿岸，以及东边的蛮藤谷。去展示一下你的实力，然后再来找我谈谈。', '杀死15条蛮藤谷鳄鱼，然后向奈辛瓦里营地的蒂巴尔复命。', '印象深刻，$C。你确定你不是远征队的一员吗?$B$B不，我是认真的。那里又有人在讲撞船的笑话了。', '你杀了足够数量了吗?', '', '去索拉查盆地找奈辛瓦里远征队营地的蒂巴尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12552, '通灵师之死', '当巨魔们推倒科尔拉玛斯的时候，它就倒在我们的东南面。不幸的时候，当它倒塌的时候，里面的天灾军团并没有死绝。$B$B现在他们正在复活我们的士兵，并用他们来对付我们！$B$B我们必须阻止这种事。你一定要杀死他们的通灵师！明白了吗？', '达克索塔的穆尔沙·月影中士要你去杀死8个哈沙尔通灵师。', '这还不够!$B$B<中士的声音为了同伴的堕落而哀嚎粗哑。>$B$B我们必须采取更多行动来表现对那些人的追忆!', '不，$C，你还没有完成任务。因为我知道科尔拉玛斯外围还有死灵魔导师在游荡。', '', '去祖达克找达克索塔的穆尔沙·月影中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12553, '撒网者的喷丝头', '为什么最棘手的任务总是派给我？$B$B科尔拉玛斯的天灾军团已经把药剂喷射器派到了离我们很近的地方，这是非常危险的。你不能想象如果他们朝这里来的话，会发生什么事！$B$B我有一个办法可以解决他们，但首先我们需要一些材料……要从天灾军团那里去弄。$B$B哈沙尔撒网者可以织出一种非常坚韧的网，正好为我们所用。给我带一些完整的喷丝头回来。', '达克索塔的专家考格维尔要你去收集5个完整的撒网者喷丝头。', '这些派的上用场!$B$B现在我们还需要一些原料来替你组装发射设备。', '如果我要组装一个设备给你用的话，非得要用完整的丝囊不可。', '', '去祖达克找达克索塔的专家考格维尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12554, '腐蚀者玛拉斯', '$N，去召集一些同伴，至少一个吧，再去科尔拉玛斯走一趟！$B$B科尔拉玛斯的首领，腐蚀者玛拉斯正在浮空城的顶端耀武扬威。$B$B去杀了他，把他的徽记给我带回来！', '达克索塔的穆尔沙·月影中士要你带回腐蚀者的徽记。', '你是此刻的$g英雄:女英雄;，$N。$B$B<月裂把头颅一脚踢开。>$B$B你值得我们深深尊敬，我想，甚至还值得更多。', '我期待着要把他的头挂在杆子上。让我们看看他这样还能不能复活!', '', '去祖达克找达克索塔的穆尔沙·月影中士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12555, '缠绕投网器', '好了！投网器已经完成，你可以用它去摧毁那些药剂喷射器了。$B$B你只需要瞄准并按下发射键，蛛网就会扰乱它们的浮空法术，直到那些喷雾器像科尔拉玛斯一样坠毁。$B$B多有诗意啊。我喜欢！', '达克索塔的专家考格维尔要你使用缠绕投网器摧毁5台药剂喷射器。', '耶!你是最棒的，$N!我并不想被传染那个天灾什么玩意的，我很肯定!我看现在那些蠢奈幽虫很难散播他们的邪恶了!$B$B感谢你拯救了我的皮肤，我给你一点小礼物怎么样?', '你确定你击坠够多了吗?我看起来像是很想要瘟疫的样子吗?', '', '去祖达克找达克索塔的专家考格维尔。', '网住并摧毁药剂喷射器', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12556, '狩猎犀牛：终极决战', '我们已经得知法鲁恩的行踪，现在就和这头巨兽来一场惊天动地的决斗吧。$N，你愿意接受挑战吗？从丛林之魂的躁动中，我可以感受到法鲁恩的强大力量。$B$B等你做好准备之后，就往北穿过日灼之柱，在苦潮湖的东北岸寻找法鲁恩。它有时甚至会在光芒之柱附近出没。杀死法鲁恩后，把它的角带回来。', '将法鲁恩的犄角交给奈辛瓦里营地的赫米特·奈辛瓦里。', '<赫米特检验了犀牛角。>$B$B一头惊人的野兽，一份震撼的战利品!$N，有谣言说盆地的北端有更大、更凶暴的猎物，我想要你帮我们跟踪它。', '你杀死那头野兽了吗?', '', '去索拉查盆地找奈辛瓦里营地的赫米特·奈辛瓦里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12557, '实验室的学徒', '我猜，你也是个想成功跻身我的学徒行列的年轻$r吧。$b$b很好，年轻人很有志气……$b$b但是我是否会接受你的申请，取决于你到底都能为我做什么，能在我的实验室里帮到什么忙了。你看，这里面有无数的材料，有些备料充足，有些就短缺了。$b$b那么，$C，你得花点时间帮我找点东西。我要一只泥潭蛆虫、一片干瘪的蝙蝠翼、一粒琥珀种子和一些冰冷的毒蛇粘液。$b$b都找到的话，我就认真考虑你的请求。', '赫布瓦罗的炼金师菲肯斯坦要求你在他的实验室内找到一只泥潭蛆虫、一片干瘪的蝙蝠翼、一粒琥珀种子和一些冰冷的毒蛇粘液。', '没错，没错，这是个好的开始。$B$B如果我要你帮忙我调制东西，你就得学会迅速地收集这些材料。$B$B好好记住，$C。$B$B再会了。', '你习惯我的实验室了吗，$C?', '', '去祖达克找赫布瓦罗的炼金师菲肯斯坦。', '找到泥潭蛆虫', '找到干瘪的蝙蝠翼', '找到琥珀种子', '找到冰冷的毒蛇粘液');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12558, '狩猎恶刃豹：突然袭击', '$N，杉苟在等着你呢。只要你的跟踪技术够娴熟，它就不会发现你，这样你就可以取得先手了。$B$B与索拉查盆地的其它恶刃豹相比，杉苟的体型应该更大，性情也更加凶残。往北走，你可以在苦潮湖西岸的瀑布附近找到杉苟的踪迹，向它发起挑战吧。如果你获胜了，就把它的毛皮给我带回来。', '将杉苟的毛皮交给奈辛瓦里营地的巴克·坎维尔。', '真是一张高贵野兽的漂亮毛皮!看到关于尚戈的传闻被证实是真的，这真教我兴奋，$N。你的猎捕真是完美无瑕。你是个真正的猎手。', '你解决尚戈了吗?', '', '去索拉查盆地找奈辛瓦里营地的巴克·坎维尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12559, '打开界门 - 造物者之座', '是时候了。让我们来引导界门吧。$B$B界门的第一道开关就在盆地西部边界的造物者之座内。$B$B千万小心，$N。那里是泰坦监视诸类造物的地方，如今仍然有许多石质魔像留守。', '雨声河的弗蕾亚的化身要你转至造物者之座，引导界门开关 - 伽玛。', '我们已经成功一半了，$N。我们要回收伊提米迪安还得再启动一个开关。', '你回来了，小家伙。我都开始担心你的安危了。', '', '去索拉查盆地找雨声河的弗蕾亚的化身。', '启动界门开关 - 伽玛', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12560, '狩猎鳄鱼：计划', '蛮藤谷鳄鱼擅长偷袭猎物，我打算以牙还牙，就用这招来对付它们。因此，我们得为你制作一件完美的伪装。材料嘛，最好用生长在河边湖畔沙地上的沙蕨。$B$B它非常适合制作伪装。喏，南边的碎浪河，北边的苦潮湖和苦潮瀑布，以及东边的河流之心，这些河流或是湖泊附近的沙地上就有这种植物。', '将5片沙蕨叶交给奈辛瓦里营地的蒂巴尔。', '<达巴尔接过砂蕨叶然后开始把它们绑在你身上。>$B$B嗯，这样应该可以了。站好别动!我们会把你弄成一丛草!', '你把我们需要的蕨叶带来了吗?', '', '去索拉查盆地找奈辛瓦里远征队营地的蒂巴尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12561, '信任危机', '这一切本不该发生的。亡灵大军如风暴般席卷了这处生命的摇篮！$B$B如果你的来意不是铲除巫妖王的爪牙，就请立即离开。若是再打扰我，必将招致我的愤怒与憎恶。', '进入迷失之地，消灭6个毁坏的天灾怪和10个骨镰劫掠者，以此获得弗蕾亚的信任。', '非常好，$r。我很高兴你不是巫妖王的爪牙…也许你能为我们做点事。', '不要浪费我的时间，凡人。泰坦的创作一定得好好守护!', '', '去索拉查盆地找雨声河的弗蕾亚的化身。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12562, '达卡莱巨魔不需要水元素！', '根据情报，自从那些水元素在达克索塔农田出现以后，大量达卡莱萨满祭司从祖达克上层赶过来控制他们。$B$B不是我罗嗦，$g先生:女士;，但这实在是太危险了。我们不希望水元素受到他们的支配。$B$B指挥官已经下令处死这些达卡莱缚水者。等你准备好了，就去南面动手吧。', '银色前沿的亚克斯中尉要求你去消灭10名达卡莱缚水者。', '做的漂亮，$g先生:女士;!$B$B我一定会向指挥官报告你的任务成果的。', '如果要我说的话，你应该再多对付几个达卡莱缚水者。', '', '去祖达克找银色前沿的亚克斯中尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12563, '巡逻员', '拔出你的武器，$r。巡逻的时候到了！$b$b我们要拼死保住手中的四座岗哨，这对我们取得胜利有着关键性的意义。我要你去逐一巡查这几处岗哨，并向他们提供帮助。$b$b你可以从东南方的布兰顿上尉那里开始。等你完成他指派的任务后，他就会指引你去下一座岗哨。$b$b巡查完所有四座岗哨后再回来向我复命。记住——你回来得越快，报酬就越丰厚！所以给我动作麻利一点！$B$B解散！', '银色前沿的指挥官库恩斯要你拜访四座银色北伐军的岗哨，并完成那里的上尉交给你的任务，然后回去向他复命。$b$b布兰顿上尉和鲁伯特上尉驻扎在达克索塔。格隆迪尔上尉驻扎在达克迦尔。炼金师菲肯斯坦驻扎在赫布瓦罗。', '嗯，$N，至少你活着回来了。我想这值得一些奖励……', '有什么来自岗哨的消息吗，$r?', '', '去祖达克找银色前沿的指挥官库恩斯。', '布兰顿上尉的任务', '鲁伯特上尉的任务', '格隆迪尔上尉的任务', '炼金师菲肯斯坦的任务');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12564, '巡逻员：止痛药', '我的弟兄们虽然坚韧勇猛，但他们毕竟是血肉之躯。$B$B受伤和疼痛削弱了他们完成任务的能力，没有什么训练或者诀窍可以改变这一点。$B$B值得欣慰的是，我们的炼金师发明了一种药膏，与我们的绷带一起使用的话，可以大大缓解士兵的疼痛。$B$B药膏需要用到一种特殊的罂粟，正好这里的巨魔在西边的达克索塔农田中种了不少。去采一些罂粟回来，以保证我们的库存充足。', '达克索塔的布兰顿上尉希望你从达克索塔农田采集5份成熟的水罂粟。', '很棒的样本，$N。$B$B我代表我的士兵感谢你今天的付出。$B$B鲁伯特上尉应该是你巡逻的下一站。他就驻守在东方的墙边。', '你收集到水罂粟了吗，$N?', '', '去祖达克找达克索塔的布兰顿上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12565, '希姆埃巴的祝福', '你们的银色北伐军在消灭天灾这件事情上表现出了极大的热诚，这让我非常感动，$r。我很愿意助你们一臂之力。$B$B达卡莱巨魔曾经在这座盛极一时的城市中定期供奉他们的神灵，而现在他们非但对神灵毫无敬意，甚至表现得更糟糕了。$B$B如果你去供奉神灵的话，他们一定会对你表示感谢的。$B$B希姆埃巴的雕像就在这里的西南面，强大的希姆埃巴会接受你供奉的达卡莱圣物，作为你正在保护祖达克的证明。', '银色前沿的妖术师乌布戈要求你在希姆埃巴的雕像前奉上10份达卡莱供品。', '<如果辛阿布瓦的脸部能动的话，他会对你露出一个凶恶的笑容。>', '<辛阿布瓦莫测高深地凝望着北方与南方。>', '', '将达卡莱供品交给祖达克银色前沿西南的希姆埃巴。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12567, '希姆埃巴的祝福', '', '', '<你感觉到辛阿布瓦的赞许。不知怎么，你知道辛阿布瓦还想要更多的贡品!>', '<辛阿布瓦石像的视线穿透了你的灵魂。$B$B你取悦了辛阿布瓦，但是他还想要你给他更多达卡莱祭品来表达你的感激与尊敬。$B$B他会好好奖励你的。>', '', '去找祖达克的希姆埃巴。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12569, '狩猎鳄鱼：伏击', '说起那条称霸水域的巨鳄，偷袭猎物的本事可高明着呢。我们都叫它“丛林霸王”，这家伙喜欢趴在河流之心的浅滩上晒太阳。喏，出了营地一路往东，河流之心就位于盆地中央，那可是索拉查盆地最大的一片湖泊。$B$B我要你带上这件伪装，埋伏在河流之心的西岸，看准机会向丛林霸王发动突袭。如果你能获胜的话，就将它的颚骨带回来。', '将丛林霸王的颚骨交给奈辛瓦里营地的蒂巴尔。', '<达巴尔听你描述了伪装的失败。>$B$B你是说，我们的计画不如预期中的有效?$B$B好吧，至少听你说起来你还是成功杀掉它了。看看这颚骨的尺寸!赫米特会为我们的成果感到骄傲的。这条鳄鱼真是只怪兽。', '我们的计画成功了吗?', '', '去索拉查盆地找奈辛瓦里远征队营地的蒂巴尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12570, '幸福的误会', '真是抱歉！我不想让你惹上麻烦！$B$B<受伤的雨声神谕者困惑地盯着你看了一会儿。>$B$B你救了我！谢谢你。我们这就返回村落。一起走吧……可以结伴同行！反正那些狗狗人很讨厌。$B$B如果你准备好了，就告诉我一声。', '护送受伤的雨声神谕者返回雨声树屋，然后与高阶神谕者索乌塞谈一谈。', '你帮了我们?那我们欢迎你，干皮人。', '你是谁?你闻起来跟小狗人一样臭。', '护送受伤的雨声神谕者返回雨声树屋', '去索拉查盆地找雨声树屋的高阶神谕者索乌塞。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12571, '赶走坏蛇', '很久之前我们就生活在这里啦，那些狗狗人是后来才跑来的。这里非常神圣——我们才不要离开。$B$B你看上去倒是挺有本事的，不过还是让拉弗乌待在你身边以防万一吧。希望你能理解我们的决定。$B$B眼镜蛇一直在偷吃我们的宝宝。你和拉弗乌一起去阻止它们，尤其要除掉东北方瀑布附近那条巨型眼镜蛇。', '雨声树屋的高阶神谕者索乌塞要你杀死毒尖和10条帝王眼镜蛇。$B$B如果你弄丢了拉弗乌的虫袋，就去找雨声树屋的高阶神谕者索乌塞。', '蛇死了?$B$B好$r。我们感谢你。', '<高阶神谕者苏-楔的视线似乎直直穿过你。>', '', '去索拉查盆地找雨声树屋的高阶神谕者索乌塞。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12572, '神祗喜欢亮闪闪的东西', '索乌塞让我们待在你身边。你会很友好的，对吧？$B$B啊！对啦！如果我们能为祭坛奉上更多祭品的话，肯定能哄索乌塞开心！我们不用走太远，村子附近就能挖到合适的祭品……留意土堆中发光的东西！$B$B走吧！走吧！去弄祭品！', '收集6份拉弗乌从土堆里挖出的闪闪发亮的宝贝，将它们交给雨声树屋的高阶神谕者索乌塞。$B$B如果你弄丢了拉弗乌的虫袋，就去找雨声树屋的高阶神谕者索乌塞。', '给伟大雨石的亮晶晶!好!很好!$B$B我们立刻把这些献祭。拉富想到的是吗?他是个很聪明的雨颂者。', '哈罗干皮人。你跟拉富相处的好吗?', '', '去索拉查盆地找雨声树屋的高阶神谕者索乌塞。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12573, '议和', '我们有个想法。既然你以前是狗狗人的朋友，他们或许会听你的。$B$B你能不能去为萨满祭司维克伊克奉上一份礼品啊？他就在西南边，河流变成瀑布的地方。告诉狗狗人，我们不想打仗。我们愿意友好相处。$B$B去吧，$r。这件事就交给你办啦。', '雨声树屋的高阶神谕者索乌塞要你将雨声议和礼物交给萨满祭司维克伊克，然后转达他的响应。$B$B如果你弄丢了拉弗乌的虫袋，就去找雨声树屋的高阶神谕者索乌塞。', '好坏!我们一直好他们一直坏。$B$B他们还想找伟大的石头麻烦…也许他们不知道伟大的石头是神圣的。', '小狗人好好相处吗?', '将议和礼物交给萨满祭司维克伊克', '去索拉查盆地找雨声树屋的高阶神谕者索乌塞。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12575, '被抢走的雾语宝物', '狗狗人又来迷雾巨石捣乱了，他们敲碎了蓝色水晶！你瞧这又是暴雨又是闪电的……不能在迷雾巨石使用蓝色水晶啊！狗狗人真该死！$B$B他们还趁乱偷走了我们在大湖中找到的宝藏。我们本来是要将它供奉给迷雾巨石的！迷雾巨石很生气，后果很严重！$B$B就是被那个塔特尔……呃，好像是塔塔克……不对不对……哦，是塔尔特克。哼，就是被塔尔特克偷走的！他逃到北边的营地去了。抢回我们的宝贝！', '雾语村的唤雾者索乌甘要你杀死督军塔尔特克，并取回雾语宝物。$B$B如果你弄丢了亚鲁乌特的宝贝水晶，就去找雨声树屋的高阶神谕者索乌塞。', '你办到了!你又强又好!雾语的好朋友!$B$B<唤雾者苏-纲露齿大笑。>', '笨小狗贼。', '', '去找索拉查盆地中雾语村的唤雾者索乌甘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12576, '被迫出手', '自从狗狗人来到这里，我们就一直想和他们保持友好关系，但是他们却不领情。$B$B本来嘛，狗狗人傻乎乎的，倒不至于造成什么麻烦。可现在他们竟然想打祭坛的主意。神圣的祭坛不容他们侵犯！这些巨石是伟大的造物主在创世的时候为我们竖立在这里的。$B$B要是迷雾巨石被破坏的话，我们该怎么办呀。去北边的狗狗人营地，阻止他们！', '雾语村的唤雾者索乌甘要你杀死8个狂心持矛者和6个狂心清除者。$B$B如果你弄丢了亚鲁乌特的宝贝水晶，就去找雨声树屋的高阶神谕者索乌塞。', '你打的好。谢谢你的帮忙。', '他们总是想打架!我们不想打架，但我们要保护圣物。', '', '去找索拉查盆地中雾语村的唤雾者索乌甘。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12578, '愤怒的鳄鱼人', '我以为你没这么快回来呢，看来是我错了。我正打算派莫乌德去警告附近苔行村的朋友们，叫他们别过来祭坛这边。苔行村在东边，就在倒塌的大石柱的东北方。$B$B你也一起去吧！莫乌德很聪明……听他的没错啦。', '抵达苔行村后与莫乌德谈一谈。$B$B如果你弄丢了莫乌德的皮球，就去找雨声树屋的高阶神谕者索乌塞。', '在你开口说话之前，不要以为我跟你见过的神谕者一样愚蠢。我曾经去世界各地旅行过，也学会了你们的语言，而我并不好骗。$B$B我们来之前我就知道苔行者已经死了，但我并不知道背后的原因是不死生物。$B$B他们应该不能进入这块地方的…一定是活血之柱的毁灭让他们跑了进来。我们必须把他们赶走。', '苏-楔有时候会犯错，但他并不笨。不过我确实认为他太过姑息了…小狗人不会停手也不会让我们好好过日子。阻止小狗人的唯一方法就是杀掉小狗人…没有“和平”这种事。$B$B<穆斗挺起胸膛指着他自己。>$B$B这我很擅长。', '抵达苔行村。', '去找莫乌德。如果莫乌德不在附近的话可以用莫乌德的皮球召唤他。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12579, '苔行祭坛的源血碎片', '我早就猜测那些大石柱是导致气候异常温暖的原因，也正是它们的力量替我们抵挡了亡灵的入侵……看来我的观点得到了初步的验证。$B$B不久前，源血之柱在巨大的爆炸声中轰然倒塌。紧接着苔行村就遭遇了不幸，气候也随即突变……转眼之间就有雪花飘落，我们从来没有见过这样的天气。$B$B苔行村的居民为苔藓巨石供奉大量的源血水晶，这才阻止了降雪。如果我们也这么做的话，说不定能抵御亡灵的进犯。', '莫乌德要你去收集10块源血碎片，但是你最好不要进入石柱中的洞穴。$B$B如果你弄丢了莫乌德的皮球，就去找雨声树屋的高阶神谕者索乌塞。', '我们要以裂片来改变状况也许太晚了一点，然而我们的选择实在不多。', '苔行者都是好人…他们不该碰上这样的事情。', '', '去找莫乌德。如果莫乌德不在附近的话可以用莫乌德的皮球召唤他。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12580, '苔行村的救星', '说不定苔行村中还有幸存者……我们不能眼睁睁地看着他们都沦为亡魂。$B$B我们要揪出这场惨剧的主谋，替他们报仇，顺便看看还有没有幸存者。', '莫乌德要你转至苔行村搭救6名苔行村受害者。也许有些鳄鱼人已经命在旦夕，难以挽救了。$B$B如果你弄丢了莫乌德的皮球，就去找雨声树屋的高阶神谕者索乌塞。', '我很高兴我们幸运地救到了几个苔行者。他们会平安的回到雨颂者之蓬的。', '我真希望我早一点知道柱子和石头之间的联系…也许我就能预防这一切。', '', '去找莫乌德。如果莫乌德不在附近的话可以用莫乌德的皮球召唤他。', '营救苔行村受害者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12581, '英雄的负担', '或许水晶真的可以逐渐恢复抵御亡灵的能力，但有件事还是要我们尽快去处理的。$B$B只有除掉这群亡灵的首领，才能确保我们不会再受侵害。如果我没猜错的话，他应该躲在倒塌的大石柱中……很可能就在崩裂碎片一带。$B$B那附近留有尸体拖拽过的痕迹，足以暗示他的行踪。$B$B我要去供奉水晶碎片，然后向索乌塞汇报消息……所以亡灵首领就交给你对付了，不过你可能需要朋友的帮助。', '杀死残忍的阿图里斯。$B$B莫乌德不能陪你执行这项任务，因此你最好召集其它伙伴帮忙。', '<在阿楚依斯的骨匣中看起来像是一团无尽的虚空…你觉得你听见了里面远处传来尖叫声。>$B$B<在你即将要离开的时候，你看到一个物体漂浮在虚空中，就在你伸手可触的地方。>', '<骨匣不祥地留在阿楚依斯死去的形体旁边地上。>', '', '去找崩裂碎片中阿图里斯的护命匣。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12583, '坠毁的喷射器', '我听说有一台药剂喷射器坠毁在西边的达克索塔一带。$B$B你为什么不去试试，看能不能找到它？我可以使用这台喷射器的零件制造一件设备，击落其它的喷射器！', '达克索塔的专家考格维尔要求你去收集药剂喷射器零件。', '<你把零件拿给专家看的时候他退后了一点。>$B$B呃，这些东西还真恶!$B$B好吧，好吧，把东西交给我，我来看看我能做些什么。也许我该叫你先拿去找牧师净化一下再拿来的。', '你拿到零件了吗?嗯?拿到没?', '', '去祖达克找达克索塔的专家考格维尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12584, '纯粹的邪恶', '情报指出，被巨魔击坠在东南方的浮空城科尔拉玛斯里面有大量的萨隆邪铁矿石。$B$B我的斥候告诉我，很多矿石就散落在那座要塞的内部。$B$B银色前沿的伊崔格和他的朋友希望能弄到一些萨隆邪铁，以便对它进行研究。$B$B我希望你去跑一趟，看看能否收集到足够多的样本。', '鲁伯特上尉要求你收集10份大块的萨隆邪铁，并将它们交给银色前沿的伊崔格。', '你没感觉到这东西的纯粹邪恶吗?$B$B我们得利用手头上的专家和魔法，然后结合圣光的力量，才能穿透这缠绕着污秽矿石的邪恶帷幕。我们得确定它的来源。$B$B快，把萨钢矿石交给我!', '嗯，$C?$B$B请告诉我你手上有我们请鲁伯特上尉去拿的萨钢矿石好吗?', '', '去祖达克找银色前沿的伊崔格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12585, '巡逻员：温暖的篝火', '好吧，这事可能不怎么有趣，但总要有人去做。$b$b我的部队已经在没膝的死水里连续激战数天了。这样对身体可不好。$b$b他们需要的一堆温暖的篝火，不但能把他们自己烤干，还可以鼓舞士气。$b$b这座城市整天都湿漉漉的，但这些荆木树的枯根却有抗潮的能力。$b$b请帮我们收集一些点火的燃料来，我们会非常感谢你的。', '达克迦尔的格隆迪尔上尉要你为他收集20份枯死的荆木。', '你人超好的，$N。真的人超好。$B$B现在你可以去西边找阿尔纳斯上尉，高地再过去就是了。', '你拿到生火的木材了吗，$r?', '', '去祖达克找达克迦尔的格隆迪尔上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12587, '巡逻员', '拔出你的武器，$r。巡逻的时候到了！$b$b我们要拼死保住手中的四座岗哨，这对我们取得胜利有着关键性的意义。我要你去逐一巡查这几处岗哨，并向他们提供帮助。$b$b你可以从东南方的布兰顿上尉那里开始。等你完成他指派的任务后，他就会指引你去下一座岗哨。$b$b巡查完所有四座岗哨后再回来向我复命。记住——你回来得越快，报酬就越丰厚！所以给我动作麻利一点！$B$B解散！', '银色前沿的指挥官库恩斯要你拜访四座银色北伐军的岗哨，并完成那里的上尉交给你的任务，然后回去向他复命。$b$b布兰顿上尉和鲁伯特上尉驻扎在达克索塔。$B$B格隆迪尔上尉驻扎在达克迦尔。$B$B炼金师菲肯斯坦驻扎在赫布瓦罗。', '嗯，$N，至少你活着回来了。我想这值得一些奖励……', '有什么来自岗哨的消息吗，$r?', '', '去祖达克找银色前沿的指挥官库恩斯。', '布兰顿上尉的任务', '鲁伯特上尉的任务', '格隆迪尔上尉的任务', '炼金师菲肯斯坦的任务');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12589, '后坐力？什么后坐力？', '你自认为是个射击能手咯？$B$B啧啧，那我倒要瞧瞧。呃，先从温和的武器开始吧。放心啦，它根本没有后坐力。记住，别把枪口对准你不想射击的目标。$B$B好啦，瞄准威尔海姆头顶的苹果，扣动扳机击飞它吧！', '使用RJR步枪击中幸运的威尔海姆头顶的苹果，然后与德洛斯坦谈一谈。', '你不是个烂射手，不过你还得多练习才能进步。你想要来赌一把吗?', '结果满意吗?', '', '去索拉查盆地找奈辛瓦里营地的德洛斯坦。', '击中幸运的威尔海姆头顶的苹果', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12592, '猎人的挑战', '看来你确实有些猎人的天分，射击技术也不赖。赫米特将你留在营地，想必是打算拉你入伙。$B$B想不想比一比啊？就咱们俩。$B$B赫米特和探险队的其它成员稍后会邀请你参与狩猎行动。我们在协助他们的过程中各自计算猎物的击杀数目，看看谁杀得比较多。这场比赛的胜负可不是瞬间就能分出的，任何种类的猎物都作数。祝你好运！', '在协助赫米特和探险队其它成员狩猎的过程中，杀死60只猎物。在你达成60个的击杀目标后，回到奈辛瓦里营地，与德洛斯坦比较猎物数量。', '哎呀，你已经要来认输啦??$B$B<当你告诉德罗斯坦说你已经达成目标的时候，他张大了嘴巴。>$B$B不可能!以艾泽拉斯之名，你是怎么办到的?我才刚杀到第58只而已。就差那么一点!$B$B但就事论事，是我低估了你，$N，而你光明正大地赢得了这场胜利。', '要来算一算吗?', '', '去索拉查盆地找奈辛瓦里营地的德洛斯坦。', '杀死猎物', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12596, '巡逻任务', '欢迎来到银色前沿，小鬼。我是指挥官库恩斯，而你——你可以叫我……指挥官。$b$b别以为你是来我这里观光的，可以自由挑选任务又不用向任何人汇报。在这里，你必须精确执行我的命令并向我汇报。明白吗？！$b$b首先，你要熟悉一下我的弟兄们，以及我们控制的地区。$b$b依次去向他们报到并执行他们的命令。完成巡逻之后再回来向我复命。', '银色前沿的指挥官库恩斯要你拜访四座银色北伐军的岗哨，并完成那里的上尉交给你的任务，然后回去向他复命。$b$b布兰顿上尉和鲁伯特上尉驻扎在东南面的达克索塔。$B$B格隆迪尔上尉驻扎在正东边的达克迦尔。$B$B炼金师菲肯斯坦驻扎在北边的赫布瓦罗。', '也该是时候你拖着尸体回来这里了!我还以为你已经死在天灾军手上了 - 虽然这算不上什么大损失…$B$B如果你要继续替十字军服务，你最好表现得好一点。$B$B记着，$r!你未来的巡逻将会根据你的时效来奖励。$B$B你可以退下了。', '你见过我的每一个上尉了吗，$r?', '', '去祖达克找银色前沿的指挥官库恩斯。', '布兰顿上尉的任务', '鲁伯特上尉的任务', '格隆迪尔上尉的任务', '炼金师菲肯斯坦的任务');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12597, '止痛药', '我的弟兄们虽然坚韧勇猛，但他们毕竟是血肉之躯。$B$B受伤和疼痛削弱了他们完成任务的能力，没有什么训练或者诀窍可以改变这一点。$B$B值得欣慰的是，我们的炼金师发明了一种药膏，与我们的绷带一起使用的话，可以大大缓解士兵的疼痛。$B$B药膏需要用到一种特殊的罂粟，正好这里的巨魔在西边的达克索塔农田中种了不少。去采一些罂粟回来，以保证我们的库存充足。', '达克索塔的布兰顿上尉希望你从达克索塔农田采集5份成熟的水罂粟。', '很棒的样本，$N。$B$B我代表我的士兵感谢你今天的付出。$B$B鲁伯特上尉应该是你巡逻的下一站。他就驻守在东方的墙边。', '你收集到水罂粟了吗，$N?', '', '去祖达克找达克索塔的布兰顿上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12598, '扔手雷', '真聪明啊……$b$b就在我们自以为已经控制了局面的时候，他们悄悄地在我们脚下挖出隧道，占领了圣殿！$b$b现在我们被两支蛛魔部队夹在中间，而且情况还在迅速恶化。$b$b我们的第一步行动是阻止他们的增援，封闭他们的隧道。$b$b拿着这些手雷，把它们扔到西北方的蛛魔隧道里去。', '达克索塔的鲁伯特上尉希望你在5个蛛魔隧道附近使用高能冲击手雷。', '我们虽然没有完全脱困，但你的努力已经减缓了敌人的攻势。$B$B德拉克亚苟的格隆戴尔上尉应该也需要你的帮助。$B$B再会了，$N。', '你封闭了奈幽族的隧道了吗，$N?', '', '去祖达克找达克索塔的鲁伯特上尉。', '封闭蛛魔隧道', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12599, '温暖的篝火', '好吧，这事可能不怎么有趣，但总要有人去做。$b$b我的部队已经在没膝的死水里连续激战数天了。这样对身体可不好。$b$b他们需要的一堆温暖的篝火，不但能把他们自己烤干，还可以鼓舞士气。$b$b这座城市整天都湿漉漉的，但这些荆木树的枯根却有抗潮的能力。$b$b请帮我们收集一些点火的燃料来，我们会非常感谢你的。', '达克迦尔的格隆迪尔上尉要你为他收集20份枯死的荆木。', '你人超好的，$N。真的人超好。$B$B现在你可以去西边找老菲肯斯坦，高地再过去就是了。', '你拿到生火的木材了吗，$r?', '', '去祖达克找达克迦尔的格隆迪尔上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12603, '磨尖你的爪子', '始生龙占据了北边和东边的大片本地，我甚至在这么远的距离都能感受到它们喷吐出的灼热气息。在挑战最强大的始祖龙之前，我们最好拿族群中较弱的成员来试试手。$B$B即便如此，你也不能放松警惕，毕竟它们可以轻易地吞噬你的躯体。等你熟练掌握与始祖龙搏斗的技巧后，再回来找我吧，我会指示你下一步该怎么做。', '杀死6只始生幼龙，然后与多里安哨站的多里安·达克斯托克谈一谈。', '我可以听出你言语中的自信。很好，这些经验将有助于我们对付飞龙女王。', '你测试了你的技巧吗?', '', '去索拉查盆地找多里安哨站的多里安·达克斯托克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12605, '诱龙出巢', '我觉得吧，像傻瓜一样手舞足蹈是不可能吸引母龙斯利维娜的注意的。我们应该耍个花招，尽快诱使她与我们作战。这样的话，我们还能为后期计划积攒一些……呃……资源。$B$B<多里安瞥了苏特菲兹一眼。>$B$B暂且不用考虑那么远啦。去营地东边和东北边寻找始生龙卵吧。我要你敲碎蛋壳，把幼龙掳走！等母龙察觉情况有异时，肯定会怒气冲冲地向我们开战。', '将6只始生龙幼崽交给多里安哨站的多里安·达克斯托克。', '喔，干得好。拿一些小雏龙给狭嘶!', '你弄到用来引诱育母的饵了吗?', '', '去索拉查盆地找多里安哨站的多里安·达克斯托克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12606, '茧中人', '既然那些隧道已经被封闭了，我们接下来就要关注那些落入敌人手里的同伴。$b$b幸运的是，我们的一些士兵还活着，只是被困在蛛魔的茧子里，情况还不算很糟糕。$b$b去把他们救出来，$c，不然就来不及了！', '鲁伯特上尉要你打开达克索塔的蛛魔之茧，释放3个被俘虏的步兵，然后回去向他复命。', '这些奈幽虫族造成了重大的损伤，$C$B$B不过，我还是很感谢你的付出。', '你把我们的士兵从奈幽虫族的魔爪中解救出来了吗?', '', '去祖达克找达克索塔的鲁伯特上尉。', '释放被俘虏的步兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12607, '驯服猛犸象', '在你前去挑战母龙斯利维娜之前，我必须指出，多里安认为你和赫米特最好能骑上猛犸象作战。$B$B营地周围到处都是裂牙猛犸，你只需用这条缰绳套住一头猛犸象的脖子就行啦。我可提醒你，别打公象的主意，它们的性情异常狂野，难以驯服。所以你要挑选一头合适的猛犸象，并将它带回营地。', '将一头裂牙猛犸交给多里安哨站的苏特菲兹。', '太完美了!现在，现在我们只要给赫米特找个梯子……', '事情都办好了吗?', '', '去索拉查盆地找多里安哨站的苏特菲兹。', '将裂牙猛犸带回营地', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12609, '收集腐液', '听着，$c。我知道这个要求有点高……$b$b新鲜的蜘蛛腐液多少有些难找，即使是在这个遍地蜘蛛的地区也是如此。但菲肯斯坦说他至少需要二十份，而且要尽快拿到。$b$b我会让我的士兵继续到野外去收集材料，但他们还需要一些帮助才能赶上炼金师规定的时间。$b$b当你在祖达克的野外冒险时，请留意那些暗门爬行者，把你能找到的所有腐液都拿回来给我。', '赫布瓦罗的阿纳斯上尉要你从祖达克的暗门爬行者身上收集7份新鲜的蜘蛛腐液。', '这些看来是很棒的样本，$N。$B$B谢谢你的协助。', '你收集到我需要的药材了吗，$C?', '', '去祖达克找赫布瓦罗的阿纳斯上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12610, '蝙蝠翅膀', '自从菲肯斯坦来了以后，我已经沦为专门为他的实验和配方收集各种材料的下手了。$b$b我会遵守参军时的誓言，无条件执行一切命令。但我毕竟是个老兵，参加过许多战斗。我更愿意上前线去，直接为北伐军做贡献。$b$b帮帮我，$r。为我收集一些蝙蝠翅膀来，这样或许我很快就能回到真正的战斗中去了。', '赫布瓦罗的阿纳斯上尉要你从祖达克蝙蝠身上收集7对完美的蝙蝠翅膀。', '做得很好，$N。$B$B我感谢你的协助。', '你替菲肯斯坦收集完那些蝙蝠翅膀没?', '', '去祖达克找赫布瓦罗的阿纳斯上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12611, '七倍奉还', '生命的源力在这片土地上涌动，巫妖王手下那些愚蠢的走狗却胆敢贸然入侵。他们造成的所有伤害，我都要七倍地奉还。$B$B指挥天灾军团腐蚀大地的罪魁祸首就是沙格兰·凋零使者，你可以在此地以北找到他。带上这个结界，使用它反射沙格兰的死亡能量。让天灾军团见识一下生命之力的伟大吧。', '弗蕾亚的化身要你使用弗蕾亚的结界将沙格兰·凋零使者的死亡之箭以7倍伤害返还，以此击败他。', '你不断的证明自己的价值，$N。也许我早先太快对你下判断了。$B$B我原以为你和那些最近坠毁在我领地上的偷猎者是一伙的，不过也许你已经抛下那些过去了。', '完成了吗，$N?', '', '去索拉查盆地找雨声河的弗蕾亚的化身。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12614, '母龙之怒', '母龙斯利维娜很难对付。她长着锋利的牙齿和巨爪，体表复盖着坚硬的骨板和骨刺。你偷走了她心爱的孩子，作为母亲，她是不会善罢甘休的。$B$B斯利维娜已经陷入了绝望与愤怒的深渊，这就是赫米特心目中猎物的最佳状态。你和赫米特，再加上这头猛犸象，应该能与她一较高下。$B$B母龙斯利维娜就在蛮荒树林北部边缘的巢穴中，心中充满了复仇的怒火。', '杀死母龙斯利维娜，然后向多里安哨站的多里安·达克斯托克复命。', '嗯，我准备了一整篇的演说，不过那个老家伙有些话想亲自对你说。', '嗯，你还活着。你做的怎么样?', '', '去索拉查盆地找多里安哨站的多里安·达克斯托克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12615, '希姆托加的祝福', '妖术师乌布戈或许曾告诉过你有关如何向祖达克的诸神献上供品的事。希姆埃巴并不是唯一被达卡莱巨魔们所遗忘的神。$B$B我们逃到了这里，在繁荣之母希姆托加的身边寻求庇佑。与希姆埃巴一样，如果你愿意向她献上供品的话，她也将很乐意祝福你。', '巫医库弗要求你在希姆托加的雕像前奉上10份达卡莱供品。', '<辛托加的思绪渗透进入了你。她感应到你所要献给她的祭品，并且显得很开心。>$B$B<她告诉你，你将会获得适当的回报。>', '<你感觉到繁荣之母的目光在看着你。她很好奇为什么一个像你这样的$r会站在她面前。>', '', '将达卡莱供品交给祖达克的希姆托加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12616, '卡拉赞的密室', '啧啧，一位经验丰富的探险者。你正是我们需要的人才啊。$b$b近来，守护麦迪文之塔的肯瑞托成员一直在谈论卡拉赞的异常氛围。卡拉赞中似乎滋生了一股新的力量，它既不同于守护者使用的魔法，也不同于燃烧军团的邪恶法术。从检测结果来看，这股力量源于一位名叫特里斯·黯血的向导族王子。而且，我们有理由相信，他是天灾军团的仆从。$b$b朋友，我要你调查黯血王子的房间，看看有没有相关的文件数据。', '银色特使要你进入卡拉赞的仆役宿舍，在特里斯·黯血王子的房间中寻找线索。', '如果你看到的命令是真的，情势就真的非常危急。我们只能期望他的任务有被及早阻止，敌人对我们的力量还没有过多的了解。$B$B谢谢你，$N。愿你在这黑暗的时代里能够永保平安。', '你发现了什么?', '了解Tenris的目的。', '去找银色特使。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12617, '消灭入侵者', '我是泰坦之女弗蕾亚的化身之一。作为生命的守护者，我肩负着保卫这片土地的重任，要确保它不被天灾军团染指。$B$B我未曾料到巫妖王竟然派遣生者破坏了水晶柱的防御结界。$B$B虽然我轻易就能捏碎那些教徒，但是我必须留在这里维持结界，阻止天灾军团的势力继续侵入索拉查盆地。去吧，$N。让那些傲慢的入侵者感受到我的愤怒。', '雨声河的弗蕾亚的化身要求你转至西北方的死亡之手营地，消灭8名诅咒教派入侵者。', '你的所言属实。营地的入侵者已经获得了处理…但我担心这已经太迟了。', '你摧毁那些入侵者了吗，$N?', '', '去索拉查盆地找雨声河的弗蕾亚的化身。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12618, '希姆托加的祝福', '', '', '<繁荣之母对你表现出了赞许之意。>', '<辛托加不带感情地看着你。她怀疑你是否想藉由贡献更多达卡莱祭品来继续获得她的祝福。>', '', '去找祖达克的希姆托加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12619, '符文之剑', '对于一名死亡骑士来说，最重要的装备无疑就是他的符文之剑。只有通过符文之剑，死亡骑士才能号令冰霜、鲜血与邪恶之力为他战斗。而且，符文之剑也像一尊水瓶一样为死亡骑士存储着他的符文之力。$B$B现在是时候让你去铸造属于自己的第一把符文之剑了。去周围的武器架上找一把破旧的长剑来。找到以后马上拿去符文熔炉旁，将它在熔炉里重新锻造成一把符文之剑。', '在黑锋要塞内的武器架上找一把破旧的长剑，并以它为基础，在符文熔炉内锻造出一把符文之剑。$B$B带着你的符文之剑去向黑锋要塞的教官拉苏维奥斯报告。', '干得好，$N。你成功地制造了你第一把的符文刃武器。你将会播下混沌与毁灭的种子!你将会在溢满鲜血，布满那些胆敢反抗天灾军团的家伙残尸的战场上苏醒。', '符文刃是你自身存在的扩展。一个死亡骑士作战时不能没有符文刃。', '', '去找阿彻鲁斯：黑锋要塞的教官拉苏维奥斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12620, '生命守卫者之怒', '$N，我们还是晚了一步。那些肮脏的教徒已经抵达光芒之柱，正在为摧毁这根水晶柱做准备。我可以感觉到空气中涌动的异样。$B$B我们的时间不多了。我要你登上光芒之柱的顶端，吹响这只号角，将我的力量导入水晶。$B$B让这帮渣滓尝尝玷污泰坦造物的后果吧。', '雨声河的弗蕾亚的化身要求你登上光芒之柱的顶端，吹响弗蕾亚的号角。', '印象深刻。我没有预期到一个小小的凡人能够像你一样证明自己是个很有价值的盟友。$B$B然而，我担心我们的付出还不够。天灾军团并没有停手的迹象。', '你解决那些教徒没，$N?', '', '去索拉查盆地找雨声河的弗蕾亚的化身。', '生命守卫者之怒', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12621, '弗蕾亚的契约', '虽然你消灭了那些教徒，但天灾军团并未停下入侵的脚步。$N，局势愈发严峻了。$B$B我不得不使出最后的绝招。在我向你透露更多秘密之前，你必须博得我毫无保留的信任。', '聆听弗蕾亚的化身的话语。', '现在已经没办法回头了。如果你同意要帮我的话，你应该不要再迟疑。', '我们时间有限。天灾军正在准备最后一次攻击。', '', '去索拉查盆地找雨声河的弗蕾亚的化身。', '弗蕾亚的契约', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12622, '金亚莱的领袖', '不知道你的想法跟埃霍奈的想法是否一致，伙计？$B$B有些一些达卡莱巨魔聚集在西南方的金亚莱。我们必须揪出他们的头头，干掉这几个混蛋。埃霍奈知道你最适合去干这个啦！$B$B立刻出发吧！你可以先拿他们的小喽罗下手，只要杀得他们鸡飞狗跳，那几个头目是一定会出现的。$B$B等他们出现之后，你得记得把他们的宝藏给拿到手……库图比萨，加瓦尼尔，还有疯子克乌罗，不要忘记哦。', '希姆托加的剥皮师埃霍奈要求你收集库图比萨的宝藏、疯子克乌罗的宝藏和加瓦尼尔的宝藏。', '割颅者认为你是个他最喜欢的$r!$B$B这些糖果棒是什么东西啊?我们要拿这些做啥啊，老兄?$B$B艾胡奈说你可以把它们拿回去!', '$C要和艾胡奈说话是因为$C拿到了所有的宝藏。', '', '去祖达克找希姆托加的剥皮师埃霍奈。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12624, '不知所踪！', '当我得知波利安小姐打算随奈辛瓦里的探险队转至索拉查盆地时，二话不说就去报了名，甘愿成为一名飞艇船员。我追求她好几个月啦，做梦都想娶她！$B$B我早已计划好了一切。飞艇坠毁那晚，我本来要向她求婚的……可现在戒指搞丢了。我到处都找遍了，却一无所获！$B$B你可以不相信我的直觉，但是我知道那枚戒指就在盆地的某处。如果不是被风险投资公司的雇员给偷去了，就是被野兽什么的给吞下了肚。肯定是这样……我知道的！', '在索拉查盆地的生物身上寻找金色订婚戒指。', '你办到了!你真的找到它了!$B$B我不知道…我不知道我该怎么感谢你!', '戒指，$N!拜托…告诉我你已经找到了!', '', '去索拉查盆地找奈辛瓦里营地的查德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12627, '横扫金亚莱', '我一直在想办法与众神取得直接的沟通。但是，金亚莱之池周围那些正在举行某种仪式的巫医给我造成了很大的麻烦。$B$B看来，排除他们的阻挠已经是迫在眉睫了。如果你能进入西南方的沼泽地域，你一定可以把他们那些不知熬着什么的锅全部掀翻。$B$B总之，把那些锅都处理掉，阻断他们那些仪式，为我扫清障碍。', '希姆托加的巫医库弗要求你破坏蓝色大锅、绿色大锅、紫色大锅和红色大锅。', '是的，我已经可以感受到差异了。谢谢你。$B$B让我们看看现在是否可以和诸神创建联系。', '我还是没有办法创建联系。那些咒医的仪式还是很完整。$B$B请回去扰乱他们的每个锅子。', '', '去祖达克找希姆托加的巫医库弗。', '破坏蓝色大锅', '破坏绿色大锅', '破坏紫色大锅', '破坏红色大锅');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12629, '无处可藏', '一旦天灾军团看上某个目标，他们就会不惜一切代价去得到他。$b$b你注定要成为一具没有思考能力的行尸……$b$b<斯特凡残忍地一笑。>$b$b……除非我们可以利用他们对你的渴望来反制他们。$b$b关于这点，我以后会解释的。现在我要准备一个复杂的魔法，需要一些特殊的材料。$b$b到正东边的痛苦之匣去，杀死那里的憎恶以收集它们的“材料”，并收集地上的食尸鬼口水，把它们给我带回来。', '黑锋哨站的斯特凡要你到折磨之匣下面去，从腐烂憎恶身上收集5份腐烂憎恶之物，并收集5份黏稠的食尸鬼口水。', '<史戴芬仔细端详这些恶心的材料。>$B$B嗯，这算不上完美，不过总是可以用。$B$B现在抱头蹲低吧，$C。这就是好玩的地方……', '你带来我需要的药材了吗，$N?', '', '去祖达克找黑锋哨站的斯特凡·瓦杜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12630, '纳斯和巨魔的毛发', '在你去见纳斯之前，有些事情我必须告诉你。$b$b纳斯曾经感染过一丁点瘟疫，所以他现在又聋又瞎，而且基本没有知觉。$b$b但这也不全是坏事。现在他已经对瘟疫之类的玩意完全免疫了，所以能够胜任某些特殊的任务——比如我将要交给你的这个任务。$b$b附近有一些刚刚感染天灾瘟疫的巨魔，我们需要研究一下瘟疫对他们造成的影响。带上纳斯和这只靴子。当你杀死一个巨魔后，就狠狠踢他一脚，这样他就会去收集毛发样本了。', '黑锋哨站的斯特凡要求你使用纳斯从干瘪的巨魔身上收集10份毛发样本。$b$b如果你把纳斯弄丢了，就回到斯特凡那里去找他。', '你知道吗，你让我想起我的纳斯。$B$B也许是因为鼻子……', '靴子还不错吧，$r?', '', '去祖达克找黑锋哨站的斯特凡·瓦杜。', '收集毛发样本', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12632, '我的后裔', '我是所有神祗中最后一个被降伏的，因此我们得先让其它的神祗重获自由。但是，由于身上的魔法束缚，我不能亲自去探察他们的情况。$B$B首先，我需要你帮我一个忙。当前达卡莱巨魔已将我的力量转过来对付我，他们还将我的后裔全部变成了畸形的怪物。$B$B带上一根我的胡须，将我那些被折磨被虐待的孩子们杀死，然后利用胡须上的魔法解放它们的灵魂，并赐予它们新的生命。', '哈克娅要求你对她的孩子们的尸体使用她的胡须，解放并复活它们。完成任务之后回到哈克娅祭坛去向她复命。', '谢谢你，$N。我永远不会忘记你所做的一切。', '还有很多我的子嗣身陷折磨之中，你必须解救他们!', '', '去祖达克找哈克娅祭坛的哈克娅。', '解放并复活哈克娅的子嗣', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12634, '酿酒的材料', '命运丢给我一颗宛如柠檬般酸涩的苦果！当我们的船横冲直撞地撞毁在这片丛林中时，酒桶全被震裂了，我辛辛苦苦酿出的美酒洒得一干二净！现在只剩下几瓶朗姆酒了，这些怎么能满足嗜酒如命的探险队呢！$B$B我必须尽快酿点什么来给他们喝！$B$B东边的蛮藤谷中生长着许多果树。如今正是果实成熟的季节，可惜我够不着高高的树干。不如你去跑一趟，从树上摇一些果子下来！有什么我就要什么。', '将1颗橙子、2串香蕉和1颗木瓜交给奈辛瓦里营地的葛瑞姆·雷酒。', '唔，这比我预计的还要丰富许多。好吧，现在问题来了:我们能够把它蒸馏成能喝的酒吗?我们最好快点开始。', '运气怎样，你有没有从那些又高又顽固的树上弄下水果来?', '', '去索拉查盆地找奈辛瓦里营地的葛瑞姆·雷酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12635, '雪豹之神的圣物', '我无意中听说你要前去为哈克娅的安宁而奋斗。祝你好运。$B$B不过，既然你要在那座祭坛周围活动的话，能不能顺便帮我收集几件他们的圣物回来呢？祭坛就在东南边不远的地方，我也不需要很多件圣物的。$B$B你看怎么样啊？', '希姆托加的记载者图基尼要求你收集10件哈克娅圣物。', '噢，最高级的样本!$B$B你可以看出这个分离形成了象征学的根基。真是杰出。$B$B这些寒冰巨魔决定自我毁灭真是令人遗憾。$B$B举例来说，你知道吗，达卡莱巨魔是因为他们极度的暴力而被其它的巨魔国家流放?$B$B这是真的!不然你以为巨魔是怎么会跑来这个气候这么严苛的地方呢?', '达卡莱巨魔彻底忙着毁灭他们自己，如果让这些历史意义重大的东西像他们的帝国一样消逝的话真是太可惜了。', '', '去祖达克找希姆托加的记载者图基尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12637, '幸免于难', '我不知道是智慧还是幸运阻止你戴上这条项圈，$r。$b$b无论如何，你找到它并不是偶然的。你已经被某个人，或者某些东西盯上了……$b$b把你的项圈交给旁边的血玫瑰达图拉。', '黑锋哨站的斯特凡要你将尸灵项圈交给血玫瑰达图拉。', '现在你目睹了原本要落在你身上的命运。$B$B就像我先前所说的，这完全不是巧合。制作这样的一件物品是很复杂的，而且所需的资源并不会胡乱浪费在随机的目标上。$B$B这是个简单的事实;天灾军团想要得到你…', '嗯，$r?', '', '去祖达克找黑锋哨站的斯特凡·瓦杜。', '发现项圈的用途', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12638, '侥幸逃脱', '我不知道是智慧还是幸运阻止你戴上这条项圈，$r。$b$b无论如何，你找到它并不是偶然的。你已经被某个人，或者某些东西盯上了……$b$b把你的项圈交给旁边的血玫瑰达图拉，让她为你演示一下差点就落在你头上的命运。', '黑锋哨站的斯特凡要你将扭曲项圈交给血玫瑰达图拉。', '现在你看到了原本会是你的下场。$B$B就像我先前所说的，这并非偶发的攻击。像这样一件物品的制作非常繁复，想必你引起了天灾军团领导阶层的注意。$B$B问题并不是怎么引起的、为何引起、甚或到底引起了谁的注意…而是我们该怎么做?', '嗯，$r?', '', '去祖达克找黑锋哨站的斯特凡·瓦杜。', '发现项圈的用途', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12639, '冻土精华', '我们获取了附近的许多元素生物，并将其驯化成了我的卫兵，这样才保证了这里拥有足够的守卫力量。但是，想要让它们保持足够的战力以应付强敌的话，则需要消耗许多能量。$B$B西北方达克玛瓦的冻土中有着大量我所需要的物质。要想让这些元素卫兵继续活动下去的话，我就需要更多的冻土精华。', '希姆托加的元素驯服者德苟达要求你收集7块冻土精华。', '谢谢你，$C。这些精华应该够我用来施展一段时间的法术。', '我希望你有带回足够的数量。金阿莱之池的攻势在你对他们做了那些事之后越来越凶恶。', '', '去祖达克找希姆托加的元素驯服者德苟达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12640, '封印裂隙', '德苟达肯定还会派你去西北方的达克玛瓦，替她和她手下的卫兵拿回更多的东西。$B$B那么，埃霍奈希望你也能顺便帮忙摧毁那些不断有元素生物跑出来的空间裂隙。这可以让我们彻底避免继续遭受它们的攻击！$B$B总之，你千万要小心，冻土中的凶猛生物会在你尝试封印裂隙的时候突然出现并袭击你。', '希姆托加的剥皮师埃霍奈要求你封印7处元素裂隙。', '艾胡奈希望达苟答有得到她想要的那些防卫者。现在那些裂隙关闭了，她不太可能再得到更多了。', '你得再封闭几个裂隙，然后我们再讲话，$N。', '', '去祖达克找希姆托加的剥皮师埃霍奈。', '封印元素裂隙', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12641, '天降厄运', '阿彻鲁斯之眼就放在这个平台的正中央。你可以用它召唤出一只探测之眼，用以侦察分析新阿瓦隆内的血色十字军部署和动向。阿彻鲁斯之眼拥有一些独特的能力，可以让你的情报收集工作更轻松一些。$B$B好好利用它的虹吸技能，侦查敌人的熔炉、市政厅、城堡，以及礼拜堂。平台的周围有数个阿彻鲁斯之眼的控制台，不要浪费时间了，$N。$B$B天灾军团必将全面占领新阿瓦隆。这是巫妖王的命令！', '巫妖王命令你使用阿彻鲁斯之眼，侦察并分析血色城堡、新阿瓦隆熔炉、新阿瓦隆市政厅和赤色烈焰礼拜堂的情况。$B$B使用阿彻鲁斯之眼的控制台来控制阿彻鲁斯之眼。', '他们正在准备着战斗，正如我所料，但不仅如此而已。我感觉到一个宿敌的存在。一个我很久以前就已经毁掉的敌人…$B$B这不重要。我们会在他们来得及撤离家园，并进驻防守之前就以天灾军团的全部军力展开攻击。', '我们对血色十字军发动的突袭将会成为传奇。', '', '去找黑锋要塞的巫妖王。', '分析新阿瓦隆熔炉', '分析新阿瓦隆市政厅', '分析血色城堡', '分析赤色烈焰礼拜堂');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12643, '一线希望', '一旦天灾军团看上某个目标，他们就会不惜一切代价去得到他。$b$b你注定要成为一具没有思考能力的行尸……$b$b<斯特凡残忍地一笑。>$b$b……除非我们可以利用他们对你的渴望来反制他们。$b$b关于这点，我以后会解释的。现在我要准备一个复杂的魔法，需要一些特殊的材料。$b$b到正东边的痛苦之匣一带去，杀死那里的食尸鬼和憎恶，把它们的“材料”给我带回来。', '黑锋哨站的斯特凡要你到折磨之匣下面去，从腐烂憎恶身上收集5份腐烂憎恶之物，并收集5份黏稠的食尸鬼口水。', '<史戴芬仔细端详这些恶心的材料。>$B$B嗯，这算不上完美，不过总是可以用。$B$B现在抱头蹲低吧，$C。这就是好玩的地方……', '你带来我需要的药材了吗，$N?', '', '去祖达克找黑锋哨站的斯特凡·瓦杜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12644, '酒香犹存', '原料搞齐啦，我的助手也准备好了蒸馏器。接下来由他监督整个酿造流程，你就负责处理所有的细节问题。你是不是想当然地认为，酿酒就是将原料一股脑儿地扔进蒸馏器，然后等它们自然发酵？你错啦。$B$B酿造过程绝没这么简单，我们必须在最适当的时候添加香料并逐步加温，同时还要控制气压。如果某个步骤慢上十来秒，那整桶酒就完蛋了。你准备就绪之后，就和“醉鬼”麦克马努斯谈谈吧。', '成功完成蒸馏作业，然后将雷酒的丛林佳酿交给奈辛瓦里营地的葛瑞姆·雷酒。', '<葛林布兹摇了摇桶子。>$B$B这里面有了东西，但最最重要的问题是，这能不能喝呢?你哪儿都别去;你也得负责监督样本测试啊。', '嗯，结果怎么样?', '', '去索拉查盆地找奈辛瓦里营地的葛瑞姆·雷酒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12645, '品酒', '现在就来揭晓真相吧！$B$B<葛瑞姆轻声地笑了。>$B$B我总是很期待这样的时刻。通常我会举办宴会供大家试饮，但是我们身处丛林，就别那么讲究啦。$B$B一切从简吧，给几位好朋友尝尝就行。让我想想，我得听听赫米特·奈辛瓦里的意见。呃，给哈迪乌斯·哈洛维也送一份。他们俩就在这座营地里。对啦，你最好去跑一趟湖边着陆场，那地方就在索拉查盆地的中央，让塔玛拉也试试。', '将雷酒的丛林佳酿的酒样交给赫米特·奈辛瓦里、哈迪乌斯·哈洛维和塔玛拉·摇链品尝，然后向奈辛瓦里营地的葛瑞姆·雷酒复命。', '三个里面有两个同意，嗯?以第一次试喝来讲还不赖。真的不赖。我想我得要弄点什么东西向塔玛拉表达歉意才行。$B$B现在…我们应该怎么称呼这支酒呢?', '不要让我一直等，$N。结果怎么样?', '', '去索拉查盆地找奈辛瓦里营地的葛瑞姆·雷酒。', '听取赫米特对酒样的评价', '听取哈迪乌斯对酒样的评价', '听取塔玛拉对酒样的评价', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12646, '我的先知，我的敌人', '我的先知当初从我身上吸取了太多的力量，而且过程也太快，结果把自己给毁灭了。现在在达克玛瓦南边留下的那处灌满雨水的巨坑就是当时爆炸产生的结果。$B$B在那以后，祭司们又将这位先知复活了，试图让他继续完成未尽的计划。他们将我的力量又重新导向了先知，很快，他就将再次醒来。$B$B趁一切还来得及，你必须去真正终结他的生命，并将我的魔精带回来。', '伦诺克祭坛的伦诺克之魂要求你找回他的极地熊神魔精。', '你办到了。$B$B但现在我还需要你帮我做一件事。', '快点，$r，你拿到我的魔精没?', '', '去祖达克找伦诺克祭坛的伦诺克之魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12647, '结束痛苦', '我的身躯已经不能挽回了，$N。那些祭司迟早会再选出一个新的先知，很快他们又将重新开始执行罪恶的计划。$B$B我将把身上最后的一些力量赐予你。那个折磨我、囚禁我的人当前正躲在祭坛的内部，他身上有一坛熏香，可以唤醒我的身躯，并让它变得不再无懈可击。$B$B请你利用这坛熏香帮我一个忙，结束我痛苦的生命吧。$B$B我要为可能会出现的反抗道歉。即使只是没有灵魂的身躯，它依然留存着极强的生存欲望。', '伦诺克祭坛的伦诺克之魂要求你对他的身躯使用折磨者的熏香，使之被唤醒。然后，你要使用伦诺克灌注在你身体内的能量杀死他。$B$B如果你不小心失去了伦诺克魔精光环的影响，可以回到伦诺克之魂那里再次寻求帮助。', '你做了你该做的事，并且荣耀了我。$B$B我对你致上最诚挚的谢意，$N。我只希望你和哈克娅能够帮助其它人。', '如果你不尽快结束我的苦难，$N，我们将失去一切。', '', '去祖达克找伦诺克祭坛的伦诺克之魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12648, '乔装打扮', '好了……我制作了一种伪装，它可以把你变成天灾军团的成员，而且不易被发现。$b$b只要伪装还没有失效，你就可以在天灾军团中自由行动。只有荒芜卫士能看穿我制造的这种幻象，你要小心它们！$b$b你要注意的另一个问题就是，这个伪装不太稳定，随时可能失效，所以你一定要保持警惕。$b$b现在让我们来测试一下效果吧。你使用项圈激活伪装，到东边去找天灾军团的商人，给我买一瓶苦痛浆液回来。', '黑锋哨站的斯特凡要你使用迷惑项圈激活天灾伪装。$b$b在天灾形态下，到骨肠那里去购买苦痛浆液。$b$b如果你丢失了迷惑项圈，可以返回黑锋哨站的斯特凡那里去再要一个。', '所以呢?你还喜欢你的天灾生活吗?$B$B相信我，并不像看起来的那么美好……', '嗯，$N?$B$B你买好那个瓶子没?', '', '去祖达克找黑锋哨站的斯特凡·瓦杜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12649, '乔装打扮！', '好了……我制作了一种伪装，它可以把你变成天灾军团的成员，而且不易被发现。$b$b只要伪装还没有失效，你就可以在天灾军团中自由行动。只有荒芜卫士能看穿我制造的这种幻象，你要小心它们！$b$b你要注意的另一个问题就是，这个伪装不太稳定，随时可能失效，所以你一定要保持警惕。$b$b现在让我们来测试一下效果吧。你使用项圈激活伪装，到东边去找天灾军团的商人，给我买一瓶苦痛浆液回来。', '黑锋哨站的斯特凡要你使用迷惑项圈激活天灾伪装。$b$b在天灾形态下，到骨肠那里去购买苦痛浆液。$b$b如果你丢失了迷惑项圈，可以返回黑锋哨站的斯特凡那里去再要一个。', '所以呢?你还喜欢你的天灾生活吗?$B$B相信我，并不像看起来的那么美好……', '嗯，$N?$B$B你买好那个瓶子没?', '', '去祖达克找黑锋哨站的斯特凡·瓦杜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12650, '自毁家园', '附近还有一处祭坛中放置有大量理应得到拯救与保护的圣物。$B$B西北边的达克玛瓦苔原另一边有一座伦诺克祭坛，据说那里的达卡莱巨魔发生了暴动，竟然毁灭了自己的圣地，将那里变成了一片焦土。$B$B$C，如果你能从那些卑贱而无知的巨魔手中救回那些圣物，我将感激不尽。', '希姆托加的记载者图基尼要求你收集7件伦诺克圣物。', '让我看看那些东西。$B$B<撰史者检验了你回收的神器。>$B$B嗯，我认为你解放了这些神器对我们来说真的是很幸运，$C。$B$B多么有趣，这些神器描绘了大崩裂。当时诺森德其实是卡利姆多的北端。$B$B但是在大崩裂之后，这块土地分裂开来，最终成了诺森德。$B$B这当然也就是为什么在南方大陆也看的到达卡莱巨魔的原因。', '我们是没有办法理解达卡莱巨魔的。他们是凶残的野蛮人，而且已经沉沦到了一个新低点。', '', '去祖达克找希姆托加的记载者图基尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12652, '喂饱食尸鬼', '嘿嘿嘿！你，食尸鬼！对！我是在跟你讲话。$b$b现在是开饭时间了。去把饭拿给那些食尸鬼！$b$b今天可是特别加大餐！看看，各种杂碎……嗯，嗯，真鲜美。$b$b去把这些装满了饭的碗丢到那些食尸鬼面前。喂饭是个交朋友的好办法。$b$b想交个食尸鬼朋友吗？啊哈哈哈哈！', '折磨之匣的骨肠要求你在10只腐烂的食尸鬼附近使用杂碎大餐。', '好吃好吃!', '你还没喂食尸鬼?', '', '去祖达克找折磨之匣的骨肠。', '为腐烂的食尸鬼喂食', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12654, '兼职猎人', '当赫米特让我陪同玛尔文来这里搭建营地时，我还以为能在修理飞行器或是修筑营地之馀练习一下狩猎技巧呢，哪知道根本忙得脱不开身！$B$B我很想干掉那头名叫匹奇的狮子。据说它就生活在这里的南边，通天之柱北面和蛮藤谷交界的地方。如果你能找到它的话，不如把你干掉它的证据给我带回来？如果小道消息确凿的话，这件战利品肯定可以让赫米特瞠目结舌！', '将匹奇的遗体交给湖边着陆场的塔玛拉·摇链。', '你拿到了!现在我只要把它做成战利品就可以了。这才是最难的部分 -- 找出方法保存它，这样赫米特才不会嘲笑我费的功夫。', '你找到匹奇了吗?', '', '去索拉查盆地找湖边着陆场的塔玛拉·摇链。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12655, '希姆鲁克的祝福', '还有一位祖达克的神祗一直被我们忽略了，那就是希姆鲁克。$B$B希姆鲁克的雕塑一直孤零零地矗立在正北边一处荒凉的地方。虽然希姆鲁克有着“智者”的称号，但他更是个吝啬和小气的神祗。他非常注重保护自己的领地，手下有着大批的护卫。这些护卫总是不停地在领地内巡逻，随时都会将擅自接近或进入的人干掉。$B$B你要小心地避开那些护卫，然后将达卡莱巨魔的供品献给希姆鲁克，这样，你将得到他的祝福。', '巫医库弗要求你在希姆鲁克的雕像前奉上10份达卡莱供品。', '<辛茹克认同了你放在他面前的祭品，即使他知道那是从别人的尸体上取来的。>$B$B<如果你将祭品献给他，他勉强同意赐予你他的祝福。>', '<你感觉到辛茹克并不相信你。他正打算要调用一个守卫。>', '', '将达卡莱供品奉献给祖达克的希姆鲁克里面的希姆鲁克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12656, '希姆鲁克的祝福', '', '', '<辛茹克在你心中灌入一个影像，他的守卫将你踩碎在脚底下。也许你该试着用更多祭品来讨好辛茹克。>', '<辛茹克对你再次躲过他的守卫感到印象深刻又泄气。至少现在是这样。>$B$B<把祭品放在他面前，然后他就会再次赐予你他的祝福。>', '', '去找祖达克的希姆鲁克里面的希姆鲁克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12658, '我的宠物大鹏', '多里安将抓来的始祖幼龙交给我训练和喂养，这让我有了新的想法。嗯，我要拥有自己的宠物！$B$B不，我当然不要龙崽子。它们能一口咬断我的胳膊，才不要这样的宠物！$B$B往东北方走，穿过始祖龙的栖息地就是埋骨地了，那里生活着大群的血爪大鹏。我可不指望能驯化成年的大鹏，所以我要你从血爪大鹏的巢穴中偷些蛋回来，等这些小家伙破壳而出时，我就开始调教它们。', '将7枚大鹏卵交给多里安哨站的苏特菲兹。', '噢，这些很棒!我已经厌倦了跟机械松鼠以及机器鸡作伴了。如果有只关节不用上油的宠物一定很棒!', '你拿到那些蛋了吗?', '', '去索拉查盆地找多里安哨站的苏特菲兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12659, '巫毒头饰！', '行动现在开始，伙计！$B$B东北边赫布达卡的那帮巨魔就是不错的目标。他们养的破蝙蝠每天晚上都要骚扰我们，这下他们该尝尝报应啦！$B$B拿着，埃霍奈把他的宝贝小刀也借给你，千万要好好干哟。', '希姆托加的剥皮师埃霍奈要求你使用埃霍奈的小刀拆下10名赫布达卡巨魔的巫毒头饰。$B$B他还提醒你，要先搜索过他们的 躯体之后再拆卸巫毒头饰。', '哎呀，我觉得这真是太有趣了。$B$B$N简直就是$r之中的我啊!$B$B你还拿着我的刀吧?', '艾胡奈知道$N绝不可能那么快就割完那么多希伯德拉卡巨魔头皮!', '', '去祖达克找希姆托加的剥皮师埃霍奈。', '赫布达卡巨魔的巫毒头饰', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12660, '毁灭性的武器', '巫妖王的爪牙竟敢将毁灭性的武器带进我的领地，我绝不能容忍这样的行径。$B$B我要你立即转至北方的天灾军团据点，摧毁他们带来的武器。我们不能让天灾军团在这片神圣的土地上再前进哪怕一步！', '弗蕾亚的化身要求你转至西北方的死亡之手营地，销毁4车不稳定的炸药。', '我感谢你，$r。你确实是个有价值的盟友。', '完成了吗，$N?', '', '去索拉查盆地找雨声河的弗蕾亚的化身。', '摧毁不稳定的炸药', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12661, '潜入沃尔塔鲁斯', '现在你可能已经猜出我的计划了。$b$b我们要利用天灾军团对你的兴趣来反制他们，也就是说，你要去潜伏在天灾军团中。我知道这和判你死刑没什么差别，但如果我们不采取行动，你就真的死定了。$b$b到东北方的痛苦之匣去，使用伪装后站到那个平台上去。进入沃尔塔鲁斯之后，你必须设法取得天灾军团指挥官的信任。$b$b完成任务之后，吹响这只号角，我会飞到你那里去和你碰头。', '斯特凡你要你使用迷惑项圈进入沃尔塔鲁斯，并按照天灾军团指挥官的命令行动。$b$b如果你丢失了迷惑项圈，可以返回黑锋哨站的斯特凡那里去再要一个。', '嗯，好吧…我承认我看到你还蛮惊讶的，$N。$B$B告诉我你得到的情报吧。', '你得到指挥官的信任了吗，$N?', '', '去祖达克找黑锋哨站的斯特凡·瓦杜。', '完成达库鲁大王的任务', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12662, '击落赫布金', '<德苟达看着埃霍奈，无奈地叹了口气。>$B$B你真想彻底消灭赫布达卡部族吗？仅仅收集几个头饰是没用的，你得把他们的头目赫布金干掉才行。$B$B可问题在于，这家伙最大的爱好是坐在蝙蝠背上巡视自己的军队。$B$B所以呢，你得去敲响他的鼓，这是让他飞下来送死的唯一方式。$B$B带上这张网，这是从他手下的猎头者手里缴获的。当他着陆之后，用网把他的蝙蝠困在地上，这样你就不用同时面对两个劲敌了。', '希姆托加的元素驯服者德苟达要求你去杀死赫布金。', '你办到了!$B$B<达苟答狠狠亲了你的脸颊一下。>$B$B你不知道这有多么令我如释重负!在每一条战线防守巨魔的攻势真是快把我们给累死了。更别提他老是喊个不停。$B$B$N，请你从我们能提供的回报里挑选一样吧。', '他还没死。我从这里就听的见他在那里嚷嚷!', '', '去祖达克找希姆托加的元素驯服者德苟达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12663, '久别重逢', '$n！$b$b你一定是收到我的礼物了吧！转个身，让我好好看看，伙计，让我仔细看看你……啊，你真令我自豪。$b$b我们历经千辛万苦才走到这一步，现在，你和我，都已经是巫妖王麾下最优秀的仆从了。$b$b你一定要紧跟着我的脚步，还有无数伟大的计划在前面等着我们呢，伙计。嗯，伟大的计划……但首先，我得给你好好补些课，对，补些课。要知道，自我们上次一别之后，发生了许多变故。$b$b去找高尔巴格，让他先带你在祖达克好好逛一圈吧。等你逛完回来之后，我就会把你该知道的所有事情都告诉你的。', '沃尔塔鲁斯的达库鲁要求你与高尔巴格交谈，并游览祖达克。', '现在你知道我们要对付的是什么啦，老兄。$B$B下去花点时间研究这个地方，然后准备点战术。$B$B我很快就会派任务给你啦。', '你跟我将会拿下古达克，老兄。', '', '去祖达克找沃尔塔鲁斯的达库鲁大王。', '游览祖达克', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12664, '黑暗的地平线', '啊，又一位志愿者响应了巫妖王的召唤。$b$b<达库鲁用不屑一顾的眼神扫了扫你。>$b$b天灾军团的新兵，是不是？你身上还满是活人的气味儿！$b$b希望获得巫妖王陛下亲自祝福的人，可是能排出几里长的队伍。你要想要从这么一大群家伙当中脱颖而出，就必须展现出真正的实力，证明你的价值。$b$b好好游览一下祖达克吧。我早就感觉到你的潜力了，所以，我才亲自下令要你来协助我。$b$b剩下的事情就取决于你了……$b$b去找高尔巴格，让他带你在祖达克里走一圈吧。如果你的确对我有些价值，那么恐怕你以后会很忙。', '沃尔塔鲁斯的达库鲁要求你与高尔巴格交谈，并游览祖达克。', '现在你知道我们要对付的是什么了，老兄。$B$B我要你下去，研究这地方，跟你的同胞混熟。准备好…$B$B很快就有很多事要你去做。不要令我失望!', '你上过战场没啊，老兄?', '', '去祖达克找沃尔塔鲁斯的达库鲁大王。', '游览祖达克', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12665, '不祥的扰动', '风蛇女神奎丝鲁恩一定也遭遇到了某种不幸。具体情况我不能清晰感知，但是我敢肯定，她的祭坛当前正在被许多强大的生物践踏。$B$B还记得你为我救出来的孩子们吗？我要派你骑着其中之一去侦察风蛇祭坛的情形。有我孩子的帮助，你们两个可以既快速又隐秘地潜行进入那一地区。$B$B侦察结束之后，我的孩子还可以保证你安全地回到这里。但是，你仍然要随时保持警惕，不可大意。$B$B准备好了就告诉我，我随时可以为你召唤孩子们。', '哈克娅要求你去查明奎丝鲁恩的状况。你可以与哈克娅交谈，乘在她孩子的背上悄悄潜入奎丝鲁恩祭坛。$B$B完成侦察任务之后，回到哈克娅祭坛向她报告。', '谢谢你把我的小猫平安的带回来。$B$B我心中早就知\r\n道了，只是想要否认它。但你的眼睛已经揭示了真相。$B$B然而，我还感觉到什么别的东西。事情并不是表面看起来的那样。', '是什么事让你耽搁了，$N?', '了解奎丝鲁恩的命运。', '去祖达克找哈克娅祭坛的哈克娅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12666, '进入灵界的准备', '奎丝鲁恩恐怕已经死了，不过我可以感觉到，她的灵魂仍在祭坛周围的灵界中游荡着。我们必须找到一个可以让你和她直接沟通的办法。$B$B幸运的是，那些曾经负责供奉我的祭司身上带有一些神圣符印，这些符印可以帮助我们做到这一点。当然，事到如今，那些家伙已经不再崇拜我，即使你去把他们全都干掉，我也不会有丝毫的怜悯。$B$B将他们身上的神圣符印抢回来给我，我可以抽出其中的能量，协助你进入奎丝鲁恩那梦魇般的灵界。', '哈克娅要求你收集8枚神圣符印，并把它们带回哈克娅祭坛交给她。', '<当你把收集好的圣徽带到她面前的时候雪豹女神看起来有些哀伤。>$B$B从前有段时光，这些东西都曾颇具意义。让我们看看能不能把它们用在更好的用途上吧。', '我从未想过事情会变成这样。达卡莱巨魔已经彻底迷失了。', '', '去祖达克找哈克娅祭坛的哈克娅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12668, '复仇的基础', '我已经为我亲爱的高阶祭司们准备了特别的惊喜。但首先你要证明一下自己，为我的复仇打好基础。$B$B你还是想活命的，对不对？$B$B如你所见，我的信徒们非常喜欢待在这里，但现在他们该做出最后的补偿了。$B$B如果你愿意的话，请帮我一个小小的忙，$N。把他们引诱到我的灵魂之泉附近来，然后结果他们的性命。$B$B他们是如此美味，而且我向你保证，他们不会白白牺牲的。', '奎丝鲁恩之魂要你在她的灵魂之泉附近杀死12个巨魔，奎丝鲁恩崇拜者或蛇灵狂暴者都可以。$B$B完成任务之后回到奎丝鲁恩祭坛向她复命。', '非常好。也许你真的有点用处。', '为什么在任务还没有完成的时候就回来?你难道还不了解我只要一个念头就能够杀死你?$B$B现在快滚，小$r。完成我所命令你去做的事!', '', '去祖达克找奎丝鲁恩祭坛的奎丝鲁恩之魂。', '在灵魂之泉附近杀死巨魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12669, '当前为止，一切很糟', '你报告的一切情况都和我们已知的情报符合。从达库鲁那里刺探情报并取得他的信任是一个非常重大的进展，可以为你的进一步任务打下基础。$b$b现在，你必须回去，听从他的指挥。你要尽可能地展现你的忠诚，$n。你的表现将产生重大的影响。$b$b这次我还要给你一个新任务：当你走到荒野上的时候，把这瓶药剂倒进他们的瘟疫之锅里去。它可以中和天灾军团的瘟疫，让锅里的病毒报废。', '黑锋哨站的斯特凡要你回到达库鲁身边并听从他的指挥。$b$b在痛苦之匣一带对5只瘟疫之锅使用稀释药剂。$b$b如果你丢失了迷惑项圈，可以返回黑锋哨站的斯特凡那里去再要一个。', '做的好，$N!$B$B稀释了那些大锅，不但可以拯救生命，还会减缓这里天灾军的成长速度。$B$B现在过来这里，告诉我你对达库鲁在祖尔德拉克的策略了解多少。', '拜托，$N，告诉我你没搞砸了你的伪装……', '', '去祖达克找黑锋哨站的斯特凡·瓦杜。', '完成达库鲁的任务', '稀释瘟疫之锅', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12671, '侦察飞行', '接下来我们要在这一地区进行试飞。教授一直想让我去看看东北边的奇怪气候。$B$B问题是，我需要副驾驶员的协助才能进入未知的领空。我才不要独自去冒险呢。$B$B怎么样？你说不定还能学到点驾驶飞行器的技巧哩。一旦学会应付极地的寒风……你就可以在任何领空飞翔啦。', '帮助飞行员维克完成侦察飞行。', '你在上头救了我一命啊，伙伴。飞得好!', '嗯，$N?', '侦察飞行', '去索拉查盆地找湖边着陆场的飞行员维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12672, '创造条件', '我可以给你一个活命的机会。$B$B祭坛周围的地上散落着许多能量碎片，它们是用来支撑我身上的诅咒的。我要你帮我去收集一些碎片来。不需要太多，否则我身上的诅咒就会消散了。只要正好让我可以向我的先知复仇就行了。$B$B去吧，爬虫。在我改变主意前，马上去执行我的命令。', '奎丝鲁恩之魂要你收集10块灵界能量碎片。完成任务后返回奎丝鲁恩祭坛向她复命。', '这些行了。其实我也根本不需要用到它们。$B$B不过看着你听我命令跑来跑去也挺有趣的。', '哈克娅没有早点派你来真是遗憾。但话说回来，她跟我也一直都处得不好。$B$B也许她故意拖延你的到来，故意让这一切发生。', '', '去祖达克找奎丝鲁恩祭坛的奎丝鲁恩之魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12673, '官大一级压死人', '如果你真的认为自己有资格接受巫妖王的赐福，就必须学会成为一名伟大的领袖——被属下敬畏的领袖！$b$b现在我要交给你一项任务，训练你的指挥技巧，伙计……$b$b去召集我的手下，训练它们采集下面的荒芜水晶，但那些家伙又懒又迟钝，所以你要指挥它们，伙计。$b$b拿上这根节杖，教它们怎样完成任务。一旦它们开始听从你的指挥，就让它们去采集水晶！', '沃尔塔鲁斯的指挥官达库鲁要你对荒芜恶鬼使用暗示节杖，并指挥它们采集7颗荒芜水晶。', '水晶从来没有堆得这么高过!$B$B你做得很好，$N。我很快就会指派你更路复用作。', '你有好好鞭打我的手下一顿吗，$N?', '', '去祖达克找沃尔塔鲁斯的达库鲁大王。', '采集荒芜水晶', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12674, '地狱的复仇', '现在你该去惩罚我那三个高阶祭司了，他们分别是穆弗努、图亚图亚和哈文尼。你可以在祭坛周围找到他们。$B$B带上这根妖术棒。我已经在里面灌注了我的怒火，它肯定会非常有用的。$B$B你只要使用它，然后去毁灭他们就行了。妖术会处理剩下的事。$B$B<奎丝鲁恩露齿一笑。>$B$B成功以后，我或许会放你走。如果你失败了，那就去死吧。', '奎丝鲁恩祭坛的奎丝鲁恩之魂要你对高阶祭司穆弗努、高阶祭司图亚图亚和高阶祭司哈文尼使用奎丝鲁恩的妖术棒，然后杀死他们。', '<你面前的恐怖灵魂发出了一阵令人脊背发冷的笑声。>$B$B他们自找的。我还会再让他们体验同样的事，一次又一次又一次又一次……', '你以为我是个蠢蛋吗?$B$B他们还没有死!', '', '去祖达克找奎丝鲁恩祭坛的奎丝鲁恩之魂。', '用妖术杀死高阶祭司穆弗努', '用妖术杀死高阶祭司图亚图亚', '用妖术杀死高阶祭司哈文尼', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12675, '最后一步', '还差最后一步，就可以实施我的复仇大计了。你必须为这些能量碎片注入某位仍然健在的神灵的精魄，才能令它们发挥威力。我推荐你请求哈克娅的帮助。$B$B如果你能成功的话，那么当你返回这里时，就不会再进入灵界，而是返回我的祭坛所在的物质世界。我的子嗣和守卫者不会再攻击你，这样你就可以轻而易举地接近我的先知。', '转至哈克娅祭坛，请求哈克娅在灵界能量碎片中注入一丝她的精魄。', '我的部分灵魂?$B$B<雪豹女神停下来想了一想。>$B$B这是十分高价的要求，尤其是为了复仇这样的目的，而且我已经因为我的镇压者而变的非常虚弱。$B$B不过，我也许知道一个方法。', '你回来了，$N。', '', '去祖达克找哈克娅祭坛的哈克娅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12676, '爆破活动', '我们一直在尝试解开水晶之谜，因此你必须返回沃尔塔鲁斯，执行达库鲁的命令。$B$B每当你成功地完成一项使命，他对你的信任就增加一分，我们也就更容易揣摩他的心思。$B$B呃，我还有一项任务要交给你。达库鲁的天灾车给我们造成了不小的威胁，我要你炸毁它们。$B$B你要设法靠近那些天灾车，然后引爆炸弹。记得迅速撤离！不然很可能伤到你自己。', '黑锋哨站的斯特凡要求你再去为达库鲁执行一项任务。$B$B除此之外，他还要你转至痛苦之匣，使用炸药束摧毁5辆天灾车。$b$b如果你丢失了迷惑项圈，可以返回黑锋哨站的斯特凡那里去再要一个。', '太棒了!$B$B你的地下工作真的很成功，$N。$B$B现在让我们来看看这柄权杖……', '你成功清除那些血尸车了吗，$N?', '', '去祖达克找黑锋哨站的斯特凡·瓦杜。', '炸毁天灾车', '完成达库鲁的任务', '洞悉达库鲁的秘密', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12677, '危险的材料', '浓缩荒芜水晶？！达库鲁到底想干什么？$b$b显然他在做一件重要的事。你要继续听从他的指挥，或许等他更熟悉你以后，会把这个秘密告诉你的。$b$b同时，我们需要看一看这些水晶。$b$b你到了沃尔塔鲁斯以后，设法悄悄弄一些水晶样品回来。$b$b哦，对了，你要小心一点！携带那些水晶会让你的伪装失效。', '黑锋哨站的斯特凡要你转至沃尔塔鲁斯,并完成达库鲁给予的任务。你还要从那里偷取5块采集到的荒芜水晶。$b$b如果你丢失了迷惑项圈，可以返回黑锋哨站的斯特凡那里去再要一个。', '好极了!$B$B我们将会立刻调查这些水晶的特性。$B$B现在告诉我，$N，达库鲁一伙人做了些什么事?', '欢迎回来，$N。$B$B你成功偷到达库鲁的水晶样本了吗?', '', '去祖达克找黑锋哨站的斯特凡·瓦杜。', '完成达库鲁的任务', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12678, '混乱战车，苦痛驭之', '现在他们准备在死亡裂口外面背水一战，徒劳地想要挽救他们的马匹、矿洞、木材和平民。$B$B你将在天灾军团中学到第一堂军事课：恐惧！$B$B到南方的前线去，击败那些血色十字军。我们可以在死亡远征时用到他们。$B$B但最重要的是：要击败那些胆小如鼠的、假扮成普通人和农夫的预备兵，他们伪装成平民来偷取我们的萨隆邪铁箭矢。在他们弄坏这些宝贵的箭矢之前击败他们，并把恐惧深深埋入那些人的心底。', '死亡裂口的瓦拉纳王子命令你击败10个血色十字军战士或血色农夫，以及10个海文郡预备兵。', '你感觉到了吗，$N?那种感觉，就是在你体内流动的全新力量。凡人是体会不到这种感觉的。$B$B前线现在已经崩解了，魂尸将会完成剩下的工作，并且替拉祖维斯准备好场地。我们则把注意力转移到更具战术性的目标上。', '这只不过是开场的奏鸣曲，死亡骑士。天灾军的死亡进行曲就从消灭前线开始。', '', '去东瘟疫之地：血色领地找死亡裂口的瓦拉纳王子。', '消灭血色十字军士兵', '消灭海文郡预备兵', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12679, '今夜，我们在海文郡欢宴！', '遮天者都是无意识的构造体，它们唯一的用途就是：战斗！$B$B不过眼下有一个小问题……它们使用的是射程极远杀伤力极大的萨隆邪铁箭矢。但萨隆矿石只有诺森德才出产，而且产量非常有限！去帮我回收一些箭矢，我会好好奖赏你的。', '死亡裂口的遮天者奥里索斯要你去回收15支萨隆邪铁箭矢。', '做的好，死亡骑士!你的所作所为替天灾战争机器补给了弹药!$B$B啊，对了，你的奖赏-我答应过的。', '他们发射的射角应该会让大多数的箭枝落在南边的避风郡农场那一带。', '', '去东瘟疫之地：血色领地找死亡裂口的遮天者奥里索斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12680, '阿彻鲁斯战马', '真是巧，离这处岗哨仅一箭之遥的地方就有一座十字军的马厩，里面有许多马匹。虽然他们守卫严密，但一个年轻勇敢的死亡骑士完全可以突破他们的防线，带走自己想要的东西！$B$B你从海文郡马厩选到一匹好马后就骑上它回来找我，我会想办法把它转化成死亡战马的。$B$B记住，$N，如果你被制伏了，就要想办法再回去弄一匹。记得当心那个管理员，基特里克！', '骑手萨拉纳尔要你从海文郡马厩中骑上一匹血色战马，然后回到死亡裂口，把马交给他。', '接下来才是真正的试炼。你能够对一头不羁的战骑展现出多少驾驭的本事，然后用蛮力夺取你最想要的东西呢?', '你不想一直徒步行走，对吧?', '', '去东瘟疫之地：血色领地找死亡裂口的骑手萨拉纳尔。', '骑上血色军马回营', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12681, '猎取材料', '达拉然的大法师伯塔鲁斯希望我们给他带回各种材料和辟邪物。索拉查盆地的原住民似乎特别迷信动物的肢体，取自血爪大鹏的扭曲的大鹏爪是他们的最爱。$B$B我没有资格评论关于这件辟邪物的传言是否属实，不过这里头总归是有些缘由的。$B$B血爪大鹏生活在东北方的埋骨地，以猛犸象的尸体为食。你能帮我收集一些爪子供大法师研究吗？', '将5只扭曲的大鹏爪交给多里安哨站的考尔文·诺灵顿。', '<寇尔文佩服地看着你带来的爪子。>$B$B这样很够了。戈洛克的说法是爪子越扭曲多节，法力就越强。我想大法师为这个营地付出的金额应该有值回票价。', '你有找到任何的扭曲爪子吗?', '', '去索拉查盆地找多里安哨站的考尔文·诺灵顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12683, '燃烧的唾液', '苦潮多头蛇的唾液是索拉查盆地中腐蚀性最强的物质。我打算用特制的容器收集一些，供大法师伯塔鲁斯进行研究。现在嘛，我需要一位勇敢的，呃……收集者。$B$B你看上去就很有冒险家的气质！怎么样，你愿意支持达拉然的研究事业吗？还能顺便赚一笔小钱哟。$B$B转至西南方的苦潮湖，挑逗那些多头蛇，用这个容器将它们向你喷射的毒液装起来就行啦。', '多里安哨站的考尔文·诺灵顿要你收集5份多头蛇唾液样本并杀死5只苦潮多头蛇。', '太棒了!这里是说好的工资。还有，呃，只是推荐一下:如果这种“烧灼感”持续不退的话，这几天你可能会想好好洗个热水澡。', '你拿到样本了吗?', '', '去索拉查盆地找多里安哨站的考尔文·诺灵顿。', '收集唾液样本', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12684, '死去神灵的血液', '猛犸之神犸托斯前些日子亲手毁灭了自己，并将他那伟大的神殿也摧毁了。他宁可死，也不愿意让达卡莱巨魔窃取他一丝一毫的力量。$B$B现在我需要牺牲自己的一部分灵魂，因此需要一些外来的能量以支撑自身的延续。$B$B犸托斯自我毁灭的地方就在东北方，奎丝鲁恩祭坛的正北边不远。他的自爆在那里留下了一个巨大的坑洞，里面满是他的血液。$B$B给我带一些他的血液回来。', '哈克娅要求你收集7份犸托斯之血，并把它们带回哈克娅祭坛交给她。', '非常好，让我们看看这是否有用……', '我希望有什么方法可以让我们把玛姆托司带回这世界，但这种方法并不存在。$B$B我们只能持续对抗达卡莱巨魔，以荣耀他和他所做的牺牲。', '', '去祖达克找哈克娅祭坛的哈克娅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12685, '种瓜得瓜种豆得豆', '复仇……复仇的时候终于到来了。$B$B<哈克娅低沉地叹了一口气。>$B$B把这只包裹里的东西带到奎丝鲁恩的尸体旁去，在她的祭坛上打开包裹，引导仪式。如果一切正常，她的灵魂将被重新拉回物质界，这样一来，她就可以从那个卑贱的先知手中夺回自己的力量。$B$B之后的一切就都指望你了，$N。你一定要在先知失去力量之后立刻杀死他，结束风蛇女神的梦魇。', '杀死虚弱的奎丝鲁恩先知，然后通知希姆托加的巫医库弗。', '<巫医不可置信的摇了摇头。>$B$B听起来你十分惊险地从奎丝鲁恩的幽界生还了。$B$B我很高兴是你去进行这个工作。我不知道我自己有没有勇气面对那种状况!', '是什么把你带回来我这里，$N?', '', '去祖达克找希姆托加的巫医库弗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12686, '不能容忍', '白痴！蠢货！这是不能容忍的！整整一批的瘟疫菌株居然都变成了废物！$b$b达穆克那个混帐！饭桶！他本应负责保养好那些瘟疫菌株的，太令我失望了！$b$b这对你来说也是个不错的教训，$n。失败往往会像传染病一样迅速传播。发生第一次失败之后，你必须立刻抓住它，消灭它，否则，它就会反过来使得你被别人消灭！$b$b拿上这根能使我们天灾巨魔更加强大的节杖。你要用它杀死达穆克。那混蛋应该就躲在南边的什么地方。$b$b就让那条败狗用自己的性命给所有人提个醒吧。让达库鲁失望，就等于死！', '沃尔塔鲁斯的达库鲁要求你转至痛苦之匣，对一名达库鲁的仆从使用强化节杖，然后使用它的技能击败达穆克。', '你做得很好，$N。你学习的速度比我想的还快。$B$B去吧，休息一下。我很快就会给你更大的考验!', '达穆克为他的失败付出代价了吗，$N?', '', '去祖达克找沃尔塔鲁斯的达库鲁大王。', '杀死达穆克', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12687, '进入暗影界', '你送来的战马已经被送往暗影界。我的黑暗骑士将在那里训练它，然后把它强化成为一匹死亡战马。你觉得自己有足够的勇气进入暗影界去夺取亡灵战马吗？$B$B如果你愿意的话，我可以把你传送到暗影界，等你到了那里之后，去我们南面的空地上寻找黑暗骑士。为了得到你自己的死亡战马，你必须击败他，夺取他的死亡战马，然后回到死亡裂口来。成功之后，就使用骑手的召唤。', '死亡裂口的骑手萨拉纳尔要求你去消灭阿彻鲁斯黑暗骑士，并夺走他的阿彻鲁斯死亡战马。$B$B如果你成功地将阿彻鲁斯死亡战马带回死亡裂口，就使用“骑手的召唤”技能召唤萨拉纳尔。', '你成功完成了大多数新兵办不到的事情，$N。为此，你将会得到可观的奖赏。$B$B<撒拉纳鞠了个躬。>', '死亡骑士，你必须靠力量抢夺死亡战骑!', '骑手的挑战', '去东瘟疫之地：血色领地找死亡裂口的骑手萨拉纳尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12690, '火上浇油', '是时候进军古达克了，朋友。是时候让你去教训教训那些不知好歹的巨魔了！$b$b那群混蛋前几天攻破了我们的城墙，还将一整支军队驻扎在了北面。$b$b哈哈哈哈！$b$b简直是给天灾之火上面浇了一把油！我要把他们的酋长都抓起来，至于其它的蝼蚁……都无关紧要了！这将是我的宏伟计划中最重要的一环……$b$b拿着这根节杖，用它来号令我的憎恶。嗯，你可以带上所有的憎恶转至那群达卡莱巨魔的营地，把他们全部击败！等他们的酋长出现以后，我的宠物岩翼会把他们全部抓回来。', '沃尔塔鲁斯的达库鲁要求你对浮肿的憎恶使用命令节杖，然后利用它们的能力在冰冷裂口击败60名达卡莱裂颅者，并将3名达卡莱酋长引诱出来。$b$b只要击败足够数量的达卡莱裂颅者，酋长们就会出现。', '做的好，老兄!$B$B我把酋长全都关起来了，而你带领着我的憎恶体打败了他们的军队。$B$B该去庆祝一下了，老兄!', '你揍扁那些巨魔了没，$N?', '', '去祖达克找沃尔塔鲁斯的达库鲁大王。', '击败达卡莱裂颅者', '诱捕达卡莱酋长', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12691, '古旧的石箱', '这个石箱似乎被锁住了，看来要在锁眼中插入相配的钥匙才能打开它。$B$B那些石头卫士身上或许带有这把钥匙。', '从索拉查卫士身上取得巨型石钥匙，用它打开造物者悬台上的古旧石箱。', '巨大的石钥匙发出了一声低沉的喀擦声，然后石箱的盖子打开来，显露出里面隐藏的财宝。', '这个石箱纹风不动。', '', '去索拉查盆地的造物者悬台找古旧的石箱。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12698, '收割者的礼物', '我从冰冷的纳克萨玛斯来到这里，以享受灵魂的盛宴，给我们的仇敌带来痛苦的打击——不过我的灵魂储备已经耗尽了。$B$B来，带上我给你的见面礼，把它带到东面的海文郡矿洞去，放在血色矿工干活的地方。用它将矿工变成被控制的矿工，等你手里有了一支小军队后回到我这里来。我给他们在灵魂容器里留了一块特别的地方！', '死亡裂口的收割者戈提克让你对血色矿工使用收割者的礼物，制造出5个被控制的血色矿工之后向戈提克复命。', '他们现在知道矿坑不再安全了。他们会加倍努力撤退，把弱点暴露出来!', '一点小提醒:矿工不是每次都会变成食尸鬼。有时候他们会变成一心一意想要杀了你的愤怒灵魂。', '', '去东瘟疫之地：血色领地找死亡裂口的收割者戈提克。', '带回被控制的血色矿工', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12699, '尴尬的处境', '出发之前，还有个小问题要解决。你看，我怎么都找不到飞行器的钥匙。$B$B除了湖里面，我哪儿都翻遍了……就是没有见着。你能帮我个忙吗？替我去湖里找找钥匙吧。$B$B我可以把我的氧气筒借给你啊。虽然里面的氧气不多，但足够你用的了。', '在河流之心的湖泊中寻找维克的钥匙。', '太棒了!', '你有找到任何东西吗，$N?', '', '去索拉查盆地找湖边着陆场的飞行员维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12701, '炮轰圣光哨站', '十字军如此手忙脚乱，一定会犯一个致命的错误：忘记检查矿车。$B$B你要做的就是回到东面的海文郡矿洞，找到我的手下放在厕所附近的矿车。爬进矿车中，那些血色矿工肯定是不会发现你的，这样你就可以安全地深入敌后了。$B$B登上他们的战舰之后，用火炮攻击他们！把他们都震晕！一旦他们失去行动能力，我们就可以顺利部署作战了。$B$B等你准备回来的时候，只需在大炮那里召唤天灾狮鹫就行了。', '死亡裂口的瓦拉纳王子命令你去打倒100个血色防御者。', '几分钟之内就把整个血色舰队扫平!我将会因此得到巫妖王的嘉奖!现在整个血色十字军只剩下新亚法隆的居民了。$B$B我会立刻把纵火者和死灵法师派去避风郡。你负责把我的报告拿去给大领主!', '死亡骑士无所畏惧!', '', '去东瘟疫之地：血色领地找死亡裂口的瓦拉纳王子。', '击败血色防御者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12702, '抓鸡狂欢节！', '我打赌你猜不到又出了什么状况。$B$B错啦，和格利基克无关，也不是鸡舍的事。$B$B好吧，我骗你的。就是格利基克！鸡们又被他吓得跑掉了。愚蠢的格利基克！我的肚子已经饿得咕咕叫了。$B$B如果你需要其它猎手的帮助，告诉我一声就是了……鸡们就躲在附近。', '狂心岭的长者哈尔卡克要你去捕捉12只逃走的小鸡。', '你真擅长这个。$B$B也许我们哪天干脆把苟瑞格克丢进水里，你就不用再做这种事了。', '通常鸡都不会跑太远…如果黄蜂不会吃掉他们的话，也许下次干脆就让它们呆在外面好了。', '', '去索拉查盆地找狂心岭的长者哈尔卡克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12703, '卡塔克的愤怒', '你就是伟大的巫妖猎手？能和你这样强大的盟友并肩作战，真是狂心氏族的荣幸。以你当前的能力，说不定足以召唤卡塔克了。$B$B大舌头怪正在攻击西南方的卡塔克要塞。杀死他们，直到你获得一份纯净的神谕者的血。将血样带回要塞的祭坛，就可以召唤出卡塔克。$B$B运气够好的话，卡塔克会占据你的躯壳……借助他的力量，尽情地享受战斗的快感吧。$B$B出发吧，猎手！', '将1份纯净的神谕者的血带去卡塔克的祭坛，召唤出卡塔克。借助他的力量在祭坛附近杀死50个灵鳍鳄鱼人，然后向卡塔克要塞的萨满祭司亚克耶克复命。', '仪式对你来说还真容易!$B$B你之后再回来多杀一点，好吗?', '好多大舌头可以杀!好好玩啊，嗯?', '', '去索拉查盆地找卡塔克要塞的萨满祭司亚克耶克。', '消灭灵鳍鳄鱼人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12704, '取悦雨水巨石', '苔行村遭到攻击，我担心这是我们对雨水巨石不够好的缘故……或许是我们太贪心了吧。我们要向祭坛供奉更多的祭品！$B$B你还记得吗，就是上次要你找的那些闪闪发亮的宝贝……你能再帮我们弄些回来吗？如果你需要某个鳄鱼人帮忙的话，告诉我一声就是了。', '雨声树屋的高阶神谕者索乌塞要你带上一名同伴，挖掘并收集6份闪闪发亮的宝贝。$B$B记得与雨声树屋的高阶神谕者索乌塞谈谈关于帮手的事。', '好多好多亮晶晶!你很擅长这个。$B$B晚点再来收集更多，好吗?', '亮晶晶永远不够…伟大雨石对我们很好，我们也要对伟大雨石很好。', '', '去索拉查盆地找雨声树屋的高阶神谕者索乌塞。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12705, '泰坦的意志', '狗狗人一直在攻击灵鳍湾……我们必须反击，否则他们会越来越有恃无恐。$B$B你是我们的好朋友，所以我们让你享受这份殊荣。很久以前，造物主指派一名守护者留下来保卫祭坛……如今他依然在这里。但是除非祭坛陷入混乱，不然他是不会显身的。$B$B那些狗狗人手里就有坏水晶，他们想用坏水晶来祭坛捣乱……我要你带上一块坏水晶去闪电祭坛，这样索乌霍鲁就会出来帮你。$B$B要是他占据了你的躯壳，你可不要惊慌……他很厉害的，肯定可以保证你的安全。', '从灵鳍湾附近的狼獾人身上取得1块被污染的水晶，将它带去闪电巨石处，召唤出索乌霍鲁。借助他的力量在神祠附近杀死50个狂心狼獾人，然后向灵鳍湾的唤雷者索乌米特复命。', '苏-侯鲁很强，对吧?我很高兴他接受你跟他分享身体作战。$B$B他比较相信他遇过的人，所以也许你还可以再回来帮忙，对吧?', '谢谢干皮的帮忙。你对我们很好。', '', '去索拉查盆地找灵鳍湾的唤雷者索乌米特。', '消灭狂心攻击者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12706, '死亡裂口大捷！', '<瓦拉纳王子交给你一份封起来的卷轴。>$B$B这是我们在死亡裂口获胜的全面报告。你去把这份报告交给莫格莱尼大人——他就在阿彻鲁斯里面。我已经把你的英雄事迹也写在了报告中。莫格莱尼肯定会好好奖励你的，$N。$B$B现在，出发吧！', '将瓦拉纳王子的报告交给黑锋要塞阿彻鲁斯的大领主达里安·莫格莱尼。', '<大领主莫格莱尼读完了报告。>$B$B整个血色舰队?$B$B<大领主莫格莱尼点了点头。>$B$B如此强大的力量，$N…我已经好几年没有看到这样支配的展现…自从我的父亲手持…$B$B<大领主莫格莱尼摇了摇头。>$B$B这不重要…$B$B是的，你的奖赏，差点忘了。', '当我派你出去的时候我很确信你不能活着回来，死亡骑士。也许你比我起初估计的更有潜力。', '', '去找黑锋要塞的大领主达里安·莫格莱尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12707, '猛犸的复仇', '埃霍奈听说你已经去过犸托斯巨坑了，朋友。犸托斯的子嗣们被激怒了，迫切地想要讨回公道！$B$B沿着东北这条路往上走到祖达克的更高一层，你可以在右边找到犸托斯祭坛的残馀部分。$B$B等你到了那里之后，在一头狂暴的猛犸象眼前晃一晃这枚犸托斯勋章，它就会冷静一段时间，这样你就可以骑到它的背上了。$B$B骑上它，用它去践踏那些犸托斯信徒吧！', '希姆托加的剥皮师埃霍奈希望你使用犸托斯勋章让被激怒的猛犸象冷静下来，然后骑乘它去消灭12个犸托斯信徒。', '咱替受害者报了一箭之仇，老兄!', '什么?你已经完成了?$B$B你已经对那些可悲的寒冰巨魔展现毛茸茸的正义了吗?', '', '去祖达克找希姆托加的剥皮师埃霍奈。', '践踏犸托斯信徒', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12708, '魔化蒂基面具战士', '我知道你正要转至东北方的佐尔玛兹要塞，$c。你到了那边以后，顺便帮我个忙，干掉督军手下的那些特殊守卫。$B$B那些被称为魔化蒂基面具战士的家伙，正如其名，具备强大的实力，对我们构成了显着的威胁。如果达卡莱巨魔能够大量生产出这种战士，恐怕我们很快就只能举白旗投降了。$B$B让我们来共同证明这种战士不堪一击，根本不值得大批量生产吧，怎么样？', '希姆托加的元素驯服者德苟达要求你消灭12名魔化蒂基面具战士。', '这样应该可以让他们再考虑考虑要不要量产这种东西了。想象和那玩意组成的军队作战真叫人发抖。$B$B<元素驯服者沉思了片刻。>$B$B我猜应该就跟对付无尽的天灾军团一样。', '想必你不可能那么快就解决了全部的附魔提基战士吧?', '', '去祖达克找希姆托加的元素驯服者德苟达。', '消灭魔化蒂基面具战士', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12709, '妖术宝箱', '很抱歉打扰你，$N。我听说你可能会转至东北边的佐尔玛兹要塞。对我们来说，你的这趟冒险也许是一个收集达卡莱巨魔文物的大好机会。$B$B据我所知，那个达卡莱督军十分多疑，因此，他用妖术保护着要塞里面所有保存着重要东西的箱子。不过，据说他手下的那些蒂基面具战士身上带有可以解除妖术的物品，但我也不太确定这一点。$B$B如果你有时间帮我弄几只箱子回来，我一定会好好酬谢你的。', '希姆托加的记载者图基尼要求你为他夺取12只佐尔玛兹要塞宝箱。', '看看你带来的东西!$B$B看这里，$N。你回收的这片东西，生动地描绘了达卡莱巨魔注意到天灾军的到来使得土地越来越虚弱。$B$B督军觉得他必须抓住这个机会，于是逼迫预言者杀死他们的神，控制他们的力量来抵抗巫妖王的军队。$B$B不管怎么样，他们都注定要毁灭。他们粗心地使自己成了灭族的元凶!', '也许在我们谈话的此刻你的包包里就装着储藏箱?', '', '去祖达克找希姆托加的记载者图基尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12710, '真相大白', '干得很不错，$n。$b$b你再次证明了我没有看走眼！现在，你也明白为什么我能获得巫妖王陛下的祝福了，因为我很少看走眼……$b$b现在，是时候把主人的计划全盘告诉你啦，朋友。$b$b你将看着我们是如何一步步将蝗虫一般的达卡莱巨魔扫出这一地区，并在古达克内获取属于我们自己的地位。$b$b带上这根权杖，它代表着我对你的信任。有了它，你就可以不受任何限制地进入上面的密室，哦……对了，别忘了好好观赏一下我们的秘密武器。', '沃尔塔鲁斯的达库鲁要求你通过传送器转至他的上层密室。', '这样你搞懂了吧，老兄。$B$B我们将会替巫妖王创造出终极的天灾军队。他一定会很高兴!$B$B你留着那枝权杖，$N。你在战场上指挥我军的时候会用得上它的…$B$B就在不久之后!', '你见识了我的作品没，$N?', '', '去祖达克找沃尔塔鲁斯的达库鲁大王。', '侦察达库鲁的上层密室', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12712, '督军佐尔玛兹的钥匙', '$N，现在我们需要找到那把钥匙，才能解开束缚着犀牛之神阿卡里的锁链。他现在状况非常危险，随时都有可能被巨魔们击败并夺走全身的神力。$B$B那把钥匙，应该就在达卡莱巨魔的督军佐尔玛兹手中。他听说了你的事情之后，已经和他的手下躲进了东北方阶梯之上的要塞里。$B$B这名督军非常强大，你或许需要一些协助才能将其击败。若你能先击败他的手下，并将他们的蒂基面具、剑和巫术这三者融合起来的话，就可以在挑战他本人时召唤到所需的助力。', '希姆托加的哈克娅要求你去夺取督军佐尔玛兹的钥匙。', '要是我没有要你把钥匙带回来，就这么直接转至古达克的话就更好了。$B$B然而，我想你最好还是先听听我要告诉你的话。', '你要不计代价取得督军的钥匙，我不能再更强调这件事的重要性了。', '', '去找祖达克的哈克娅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12713, '背叛', '好了，间谍游戏也该到此结束了，$N。$b$b你带来的情报具备非常重要的价值，现在，我们必须趁达库鲁全面展开计划之前阻止他，并将他杀死，以绝后患。$b$b你手里的这根节杖已经被我们全面改造过了。等到时机合适的时候，你就对达库鲁的瘟血巨魔释放出这根节杖中的能量。这也是你可以击败他的唯一方式。$b$b祝你好运。', '黑锋哨站的斯特凡要求你击败达库鲁。$b$b如果你丢失了迷惑项圈，可以返回黑锋哨站的斯特凡那里去再要一个。', '所以，我们成功了。$B$B我们还有很多事要做，但是此地的工作会因为你的努力而轻松许多。$B$B请收下这个象征我们谢意的礼物。', '你在战斗中面对过达库鲁了吗，$N?', '', '去祖达克找黑锋哨站的斯特凡·瓦杜。', '击败达库鲁大王', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12716, '药剂师的要求', '看这片南瓜田！你有没有发现少了什么东西？显然没有，因为你是个白痴！你的脑子可能是最先死掉的那部分。$B$B<诺斯叹了口气。>$B$B我收到命令，要部署一口天灾之锅。你要负责帮我完成任务。$B$B穿过新阿瓦隆的正门之后，你就可以看到一座旅店，进去给我弄一口锅出来。然后到城门附近的熔炉那里去，给我再弄一些铁链子。另外给我带10块十字军士兵的徽记回来——需不需要我告诉你去哪里弄这些玩意？', '药剂师诺斯要求你交给他一口空锅、一条铁链和10块十字军徽记。', '太完美了!现在给我一点时间把东西架设好。', '你收集到我要的材料没有?', '', '去东瘟疫之地：血色领地找海文郡伐木场的药剂师诺斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12717, '诺斯的特殊药剂', '天灾之锅已经准备就绪，随时都可以使用！$B$B死亡骑士，现在让我简短地介绍一下天灾之锅。锅中散发出的气体对于活人来说是致命的，不过对于天灾来说正好相反：他们从死亡中获取力量，因此浸染在天灾之锅中的时间越长，就会变得越强大。$B$B拿上这些十字军徽记，把它们扔进锅里。你会对它的结果感到满意的。', '将一堆十字军徽记放入天灾之锅。', '当你把颅骨放进去的时候，瘟疫大锅突然跳动了起来。$B$B几秒钟之后几瓶装着黑色液体的小药瓶浮了上来。', '瘟疫大锅一动也不动。', '', '去东瘟疫之地：血色领地找海文郡伐木场的瘟疫之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12718, '更多的徽记', '', '', '当你把颅骨放进去的时候，瘟疫大锅突然跳动了起来。$B$B几秒钟之后瘟疫大锅给了你黑的发亮、冒着泡沫的诺斯特调。', '瘟疫大锅不断的冒泡翻搅着有毒的液体，朝四周喷洒着浓浊的气体。$B$B你还有更多的十字军颅骨可以放进去吗?', '', '去找东瘟疫之地：血色领地的瘟疫之锅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12719, '无路可逃，无处可藏', '没有什么能比完全歼灭敌人更令人满足的了，$N。不过想要做到这点，只靠几百个无脑怪物进攻新阿瓦隆的前门是远远不够的。我们必须渗入内部，除掉他们的官员。必须得让他们知道：没人可以逃出天灾的掌心！$B$B转至西南面的新阿瓦隆市政厅，击败在那里发号施令的家伙。在市政厅里找到户籍册，把它带回来交给我。', '追忆墓穴的凯雷塞斯王子命令你去击败奎比镇长，并找到新阿瓦隆户籍册。', '这本名册能告诉我们许多关于这些血色害虫的事情。$B$B<凯雷希斯翻阅了名册。>$B$B死亡率、出生率、但最重要的是动向。$B$B看这边，$N，他们已经派了三艘船出海。让我看看…他们要去哪里?$B$B<凯雷希斯一面喃喃念着经纬度一面计算航路。>$B$B什么?这是不可能的。他们正航向诺森德!$B$B坐标旁边还写着:“赤红黎明”。', '让他们无处可逃!', '', '去东瘟疫之地：血色领地找追忆墓穴的凯雷塞斯王子。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12720, '说服者', '在我周游世界的过程中，我制造了几件有意思的小东西。比方说，你知不知道只要有足够的刺激，就能让一个人把所有真相都吐出来？真巧，我手上正好有些合适的东西。$B$B<凯雷塞斯从一只华丽的珠宝盒中取出一些东西。>$B$B这些是我的“说服者”，把它们装备上，然后到战场上去。把尖的一端指向新阿瓦隆的士兵，去了解这个“血色的黎明”到底指的是什么。', '追忆墓穴的凯雷塞斯王子命令你去探寻“血色的黎明”的真相。$B$B从精致的珠宝箱中取出凯雷塞斯的说服者，使用它们来“说服”血色十字军吐露真相。', '觉醒?你说的真是一点都没有道理，$g男孩:女孩;!什么样的蠢蛋会把自己的子民送去冰冻荒原的正中央?但也许这信差没说真话。', '对血色十字军使用说服者吧。他们之中总有人会…说溜嘴。', '发现“血色的黎明”的真相', '去东瘟疫之地：血色领地找追忆墓穴的凯雷塞斯王子。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12721, '狂暴', '$N，我们已经没有时间了。你必须带上这把钥匙，用它释放阿卡里。$B$B他就被关在古达克前面的田野上——那地方是祖达克的首都。阿卡里身上的锁链被四个锚点固定着。你必须打开所有的锚点，才能释放这位犀牛之神。$B$B古达克里面到处都是冰巨魔。但我相信，你只要够小心的话，就可以有惊无险地潜入那里。$B$B成功之后，请把这个消息告知巫医。', '希姆托加的哈克娅要你去释放阿卡里，并将这个消息通知巫医库弗。', '不!$B$B又一个神被毁灭了，又一个神的力量遭窃。现在阿卡里的预言者直接对我们造成了威胁。$B$B如果他过来的话，一定是冲着哈克娅来。我们不能让他夺走她的力量。$B$B我们必须再次与诸神商量，$N。他们会告诉我们该怎么做。', '发生了什么事?', '解除阿卡里身上的锁链。', '去祖达克找希姆托加的巫医库弗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12722, '羊入虎口', '当天灾军团的浮空城出现时，大部分人类都会吓得四处逃散。血色十字军却不会这样！$B$B我必须承认——我有点享受跟十字军之间的交流。这么多年来，天灾与他们之间的战争在人类历史上增添了几件最悲惨的事件。而现在我们又一次在战场上一决胜负！$B$B我们怎么能拒绝他们永久侍奉巫妖王的愿望呢！去新阿瓦隆帮助他们达成心愿吧。', '追忆墓穴的瑞文戴尔男爵命令你去消灭10个血色十字军士兵和15个新阿瓦隆预备兵。', '你剑法不错，$N。如果巫妖王允许的话，也许你会有兴趣当我的手下?斯坦索姆需要一个新的市长。', '就像待宰的羔羊一样……', '', '去东瘟疫之地：血色领地找追忆墓穴的瑞文戴尔男爵。', '消灭血色十字军士兵', '消灭新阿瓦隆预备兵', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12724, '十字军的巡逻路线', '我们迄今为止还没有得到任何与这个信使相关的线索，根本不知道他会在什么时候、什么地点出现。这些人类同样也一无所知。$B$B<奥尔巴兹指了指躺在地上的血色十字军尸体。>$B$B不过我从一个家伙口中得到了一些有用的情报。他们在血色城堡里面保存着一份所有巡逻路线的日程表。我希望你能闯入城堡，拿走日程表。$B$B这座城堡是新阿瓦隆里面最大的建筑物——就在这里的东北边。', '血色旅店内的奥尔巴兹·血毒命令你进入血色城堡，偷取新阿瓦隆巡逻日程表。', '<欧贝兹翻阅了日程表。>$B$B这些没用的废物可真忙!北巡路线、南巡路线、西巡路线、东巡路线，但就是没提到信差的路线。等等。这是什么?看起来像是一条从西瘟疫之地过来的西巡逻路线?这个巡逻员今天就会经过这里!我需要时间来好好计画计画。', '撕裂那座堡垒吧!日程表就在那里!', '', '去东瘟疫之地：血色领地找血色旅店的奥尔巴兹·血毒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12727, '杀出一条血路', '警钟已经敲响了，大检察官和他的随从很快就会来到这里。我的伤非常重，派不上太多用处，不过我会尽全力帮助你。$B$B击败大检察官和他的随从，把他的徽记交给萨萨里安。复仇可以抚慰他狂野的灵魂，$N。如果你能活着回到萨萨里安那里，告诉他，血色十字军正在礼拜堂处理囚犯。也许他会派你到那里去再次逞英雄。', '击败大检查官瓦洛斯，并把瓦洛斯的徽记带回新阿瓦隆的血色旅店，交给萨萨里安。', '我要把这个混帐的脑袋拿去喂食尸鬼!$B$B<萨沙理安把头颅丢到房间的角落去。>$B$B寇尔提拉有逃出来吗?$B$B<萨沙理安暂停了一会。>$B$B我相信他一定逃出来了。那些墙壁关不住他的。$B$B现在该来偿债了。', '寇尔提拉怎么样了?', '', '去东瘟疫之地：血色领地找血色旅店的萨萨里安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12728, '监视裂谷：冬鳞洞穴', '我要整理一下笔记，准备在达拉然的同僚面前进行演讲。$b$b在我做准备的时候，还得请你去一趟北方的冬鳞洞穴。在洞口处使用奥术测量器。$b$b得到数据后请立即回来找我。没有这些数据，我的文件就是不完整的。', '琥珀崖的盖伦要你在冬鳞洞穴处使用奥术测量器。', '太棒了，这样我的报告就完整了。$B$B我一定会对议会提起你的协助的，$N。', '你从冬鳍洞窟收集好数据了吗，$N?', '', '去北风苔原找琥珀崖的图书馆员盖伦。', '获取冬鳞洞穴的数据', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12729, '诸神的指引', '诸神已经开口了，我们必须遵循他们的指导。$B$B去召集你的朋友，$N。带着你的队伍到北方的希姆鲁克去，去消灭那里的守卫者，直到你找到完美的精华。然后再去东方的奎丝鲁恩祭坛，消灭那里的祭坛典狱官，夺取他们的活力精华。$B$B把这两样物品交给哈克娅，她会把它们融合起来，制作成一种可以让阿卡里先知现身的东西。', '将完美的守卫者精华和充满活力的典狱官精华交给希姆托加的哈克娅。', '你的勇气似乎是无限的，$N。$B$B请把心脏和精华交给我，然后我就会将它们制成能够强迫预言者出现在你面前的东西。', '你已经取得必要的物品了吗，$N?', '', '去找祖达克的哈克娅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12730, '在佐尔赫布相会', '你和你的朋友必须带着这件召唤设备，转至古达克南面的佐尔赫布。$B$B你会在那里发现一个能量法阵，使用召唤设备就可以强行召唤出阿卡里的先知。$B$B我的心与你同在，$N。我们一起经历过许多艰难险阻，你已经竭尽全力来拯救我，以及其它那些已经被达卡莱巨魔毁灭的神灵。$B$B但我担心这次分别后，我们就只能在死后再相见了。', '希姆托加的哈克娅要求你杀死阿卡里先知。', '你办到了!$N，你是祖尔德拉克的勇士!$B$B我们永远不能还清欠你的人情，但赞达拉巨魔把一些物品交托给我，相信你会有兴趣的。$B$B我很希望你能了解并接受我们的感激之情，但是，很快地。我又有一件紧急事件必须处理。', '我只能够给你温暖的话语，以及言语中带来的勇气。$B$B磨利你的武器做好准备吧，但我恳求你，不要花太多的时间，否则预言者可能会直接袭击我们。', '', '去找祖达克的哈克娅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12732, '日灼之力', '总有一天，雷耶克会强壮起来成为伟大的战士，你很快就会看到这一天。$B$B这个瓶子给你，你带上它去遥远的西方，到日灼之柱的顶端，把那里的水装进瓶子。$B$B接着你要去盆地的北部边境，到埋骨地以北的台地去。找到并击败血爪鹏王。$B$B取得它的精华元素后拿回来给雷耶克。', '将一瓶日灼精华交给狂心岭的雷耶克。', '瑞杰克感谢你。瑞杰克喝下去，变强，还是会一直记得伟大的$N带来的礼物。', '你给瑞杰克带礼物来了吗?', '', '去索拉查盆地找狂心岭的雷耶克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12733, '死亡的挑战', '死亡挑战源自于巫妖王在冰原中心战胜伊利丹·怒风的那一场大战，是每个死亡骑士都必须通过的仪式。$B$B去找到阿彻鲁斯的其它死亡骑士并与他们决斗。他们必须接受你的挑战，并且战斗到决出胜负为止！$B$B现在就去吧，$N！胜利属于天灾军团！为了巫妖王的荣耀！', '战斗召唤者奥尔伦命令你在决斗中战胜5名死亡骑士。$B$B你可以选择死亡骑士新兵或玩家作为对手。', '荣耀归于胜者，死亡骑士!做的好!巫妖王今天特别眷顾着你。', '你完成死亡挑战了吗?', '', '去东瘟疫之地：血色领地找死亡裂口的战斗召唤者奥尔伦。', '在决斗中战胜死亡骑士', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12734, '雷耶克：第一滴血', '雷耶克刚刚成为狂心氏族中最年轻的战士。父亲交给雷耶克一柄剑，要用它打败我们的敌人。根据传统，使用前必须首先举行一个仪式。你愿意帮雷耶克吗？$B$B我要你将这柄剑插在被击败的敌人面前。你也知道，狂心氏族的敌人很多，比如西南方的巨蜂和硬皮猩猩还有那些讨厌的大舌头怪。就去找雾语氏族吧，它们生活在遥远的西北方，就在苦潮湖附近。', '击败1只蓝玉虫巢巨蜂、1只硬皮冲锋者和3名雾语氏族的成员，完成雷耶克的仪式。你可以选择击败雾语神谕者或是雾语战士。完成任务后，向狂心岭的雷耶克复命。', '瑞杰克看到敌人的血迹沾在剑刃上了。现在瑞杰克有了一把配的上伟大战士瑞杰克的武器了!', '你让瑞杰克的剑刃喝血了?', '', '去索拉查盆地找狂心岭的雷耶克。', '用蓝玉虫巢巨蜂完成仪式', '用硬皮冲锋者完成仪式', '用雾语氏族成员完成仪式', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12735, '净化之歌', '索拉查盆地的土地是纯洁的。几个世纪以来，这些柱子一直保护着这片土地。$B$B但这里的水就不那么纯洁了，因为它们来自盆地以外……来自那些海洋、湖泊和河流。有时，水会带来邪恶的灵魂——这时就要净化它。$B$B请你带上这只钟，在苦潮湖、冬拥河和河流之心敲响它。这会激怒邪恶的灵魂……然后你必须杀死它。', '雨声树屋的索乌尼要你在苦潮湖、冬拥河和河流之心敲响净化之钟，杀死污染水源的邪灵。', '水…净化了。没错，全都净化了。$B$B你能理解我等之道，$N。', '你演奏净化之歌没，$N?', '', '去索拉查盆地找雨声河的神谕者索乌尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12736, '沉思之歌', '显然你不如鳄鱼人聪明！你只是个头脑简单的$r。$B$B但你还是有点希望的！你显示出了学习的能力。或许水晶能让你聪明起来，就像它能让我们变聪明一样！$B$B我会教你演奏乐曲，让你头脑清晰起来。你要用水晶来演奏乐曲，它能让你的脑子变得好使……虽然比不上鳄鱼人那样聪明，但肯定比你现在强。源血之柱已经倒塌，但其它的柱子还是完好的！', '雨声树屋的索乌尼要你在光芒之柱、日灼之柱、苔光之柱和通天之柱的顶端吹响沉思乐管。', '看吧?我看的出来你已经变聪明了。如果没更聪明…至少…更快乐!', '你觉得变聪明了吗，$r?', '', '去索拉查盆地找雨声河的神谕者索乌尼。', '在光芒之柱吹响沉思乐管', '在苔光之柱吹响沉思乐管', '在通天之柱吹响沉思乐管', '在日灼之柱吹响沉思乐管');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12739, '特殊的怜悯', '我们来到这里，将这个地方夷为平地，然后向牢房走去。在那里看到的一切完全出乎我们的意料，$N。看来血色十字军真是很忙碌。那里塞满了银色黎明的俘虏，当我们到达的时候，其中的大部分人都已经感染瘟疫死去了，但少数人还有呼吸。$B$B里面有一个牛头人，他感染了瘟疫，已经活不长了。去结束他的痛苦吧。', '赤色烈焰礼拜堂的骑士团指挥官普雷菲斯特希望你去探视牢房里的银色黎明俘虏，玛拉尔·勇角，并结束他的痛苦。', '感觉很棒，不是吗?你再也不是他们的一份子了，$N。你是天灾军。你是我们的一员。永远都是……', '你现在感觉如何?', '', '去找东瘟疫之地：血色领地的骑士团指挥官普雷菲斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12740, '银色北伐军的降落伞', '这些飞在空中的怪物正在残杀我的士兵！被摔死是一个非常可怕的结局。$B$B$C，你必须把这些降落伞分发给我的士兵，这样他们至少有一次挣扎求生的机会。', '银色前沿的指挥官法斯塔夫要你为庭院里的10名银色北伐军战士或银色持盾战士配备降落伞。', '你是个好人，$N。你碰巧经过这里对我们来说真是幸运。$B$B多待一阵子吧。我相信我们有很多事需要像你这样能干的$C来帮忙。', '如果你有空回来跟我讲话，为什么我还会看到我的手下摔死呢?', '', '去祖达克找银色前沿的指挥官法斯塔夫。', '为银色北伐军士兵配备降落伞', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12741, '雷雨之力', '愚蠢的大舌头怪认为对着云朵唱歌就能获得力量。雷耶克要夺得力量，要让他们看看应该怎样获得力量！$B$B在遥远的西北方，有一块被大舌头怪称为“雷暴台地”的宽阔平地，雷耶克觉得你只能通过飞行的方式上去。$B$B雷耶克听说那里的空气元素拥有可怕的力量。杀死它们，带上它们的精华转至大舌头怪在台地西侧搭建的“雷雨祭坛”。雷耶克等你带着终极力量回来。', '收集3份季风精华和3份风暴精华，将它们带到雷雨祭坛去。然后将真正的雷雨之力交给狂心岭的雷耶克。', '瑞杰克来给大舌头瞧瞧什么才是真正的使用元素!', '你把元素的真正力量带回来给瑞杰克了吗?', '', '去索拉查盆地找狂心岭的雷耶克。', '', '', '', '');
