INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12750, '特殊的怜悯', '我们来到这里，将这个地方夷为平地，然后向牢房走去。在那里看到的一切完全出乎我们的意料，$N。看来血色十字军真是很忙碌。那里塞满了银色黎明的俘虏，当我们到达的时候，其中的大部分人都已经感染瘟疫死去了，但少数人还有呼吸。$B$B里面有一个被遗忘者，他感染了瘟疫，已经活不长了。去结束他的痛苦吧。', '赤色烈焰礼拜堂的骑士团指挥官普雷菲斯特希望你去探视牢房里的银色黎明俘虏，安东尼·布拉克，并结束他的痛苦。', '感觉很棒，不是吗?你再也不是他们的一份子了，$N。你是天灾军。你是我们的一员。永远都是……', '你现在感觉如何?', '', '去找东瘟疫之地：血色领地的骑士团指挥官普雷菲斯特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12754, '悬崖伏击', '在你忙着焚烧礼拜堂、清理杂鱼的时候，我制订出了一套新的作战计划。$B$B血色十字军的信使每天都会定期经过血色悬崖，差不多就是这个时候。悬崖周围的道路都非常宽阔，视野很好，而且散布着无数的十字军士兵。等你到了血色悬崖之后，就用这套伪装工具把自己藏起来，准备伏击血色信使。当他走到你附近时，你就冲出来，以最短的时间结束战斗！击败他以后，带着他身上所有的东西回来——包括他的衣服！$B$B血色悬崖就在东边，离这里大概两百步远的地方。', '新阿瓦隆血色旅店内的奥尔巴兹·血毒要求你击败血色信使，并收集血色信使的衣物和血色信使的信件。', '<欧贝兹阅读了信息。>$B$B壁炉谷和提里斯法的军队将会一头栽进大屠杀之中。$B$B<欧贝兹微微一笑。>$B$B现在轮到计画的第二部分了。你要把这个信息送到大将军阿比迪斯的手中。这就是那些衣服的用途……', '你就要错过信差了，那样我就被迫得杀死你。说是被迫，意思就是说我会很高兴地了结你的性命。$B$B动作快!', '', '去东瘟疫之地：血色领地找血色旅店的奥尔巴兹·血毒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12755, '命运的交汇点', '这封信必须原封不动地送到阿比迪斯手上，否则必然会引起他们的猜疑，这可不是我们想看见的结果。他们必须带着“一切尽在他们掌握之中与计划之内”的想法继续进行下去。$B$B好了，现在你只需穿上这些衣服，再辅以一些黑暗魔法的帮助，就可以完美地化妆成他们的信使了。$B$B阿比迪斯当前就在血色悬崖东南方的国王港。把这封信交给她，然后仔细收集她在看完信之后所表达出来的一切情报。她必然会告诉我们有关“血色的黎明”的一切。', '奥尔巴兹·血毒命令你将血色信使的信件交给国王港的阿比迪斯将军。', '<大将军阿比迪斯读了信。>$B$B该死!壁炉谷和提里斯法的军队绝不能到新亚法隆去!天灾军会把他们给屠杀殆尽的。', '你上哪去了?你迟了整整两小时。我们正要派信差去找高阶指挥官。', '', '去东瘟疫之地：血色领地找国王港的阿比迪斯将军。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12756, '血色先锋军', '听仔细了，信使。血色十字军的领地正在不断沦陷。新阿瓦隆和海文郡已经被天灾军团踏平，死亡的阴影正盘旋在我们的头顶，随时都有可能将我们一口吞噬。$B$B你马上回到加瓦尔那里去，告诉他：$B$B“你的军队立刻转进，准备好所有的船只，准备转至那片冰冻的废土。我们将在诺森德会合。”$B$B把这个也交给加瓦尔。$B$B<阿比迪斯又递给你一本日记。>$B$B这本日记里的内容会解释一切的。$B$B血色十字军这个名字已经成为历史，从此以后我们将有一个新的名字——血色先锋军！', '将《救赎之路》交给新阿瓦隆血色旅店内的奥尔巴兹·血毒。', '<欧贝兹翻了翻日志。>$B$B真是垃圾!这就是“赤红黎明”?$B$B他们是在自寻死路!我们将注意力集中在进犯中的军队吧。', '<欧贝兹笑了笑。>$B$B这是什么?某个小孩的绘画簿吗?', '', '去东瘟疫之地：血色领地找血色旅店的奥尔巴兹·血毒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12757, '血色十字军进犯……', '看来我们得准备应付这群劲敌了，$N。立刻把你发现的全部情报汇报给莫格莱尼大人！我会给你打开一道直接返回阿彻鲁斯的传送门。你一踩上去就能直接传送回去。$B$B记得把阿比迪斯的日记交给莫格莱尼大人。或许他能从中找到一些有用的东西。', '将《救赎之路》交给黑锋要塞阿彻鲁斯内的大领主达里安·莫格莱尼。', '你成了一样毁灭工具，死亡骑士!我们将会蹂躏毁灭这只进逼的军队，然后将他们复活并成我们的亡灵军队!', '你做了什么?', '', '去找黑锋要塞的大领主达里安·莫格莱尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12758, '英雄的头盔', '雷耶克听说过在遥远的雷暴台地有金属巨人出没。沿着西北方前进，越过盆地边缘就到了。$B$B想象一下，如果能戴上金属巨人的头盔，雷耶克将是不可战胜的！雷耶克将变得无比强大！$B$B你帮雷耶克弄个金属头盔好不好啊？但是金属巨人的头盔不容易得到，所以你要先去日灼之柱附近的斯温迪格林挖掘场，从小绿人和他们的朋友那里偷来一些炸弹。这样，你就可以用炸弹来弄到金属巨人的头盔，然后把它拿来交给雷耶克了。', '转至斯温迪格林挖掘场，从风险投资公司的驻地搞到风险投资公司炸药，然后使用它们获得风暴看守的头盔。将风暴看守的头盔交给狂心岭的雷耶克。', '瑞杰克知道你成功了!现在瑞杰克要试试新的战争头盔!', '你带了瑞杰克的新头盔来了吗?', '', '去索拉查盆地找狂心岭的雷耶克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12759, '战争的工具', '我听瑟匹克说，你是他见过的最好的鳄鱼人猎手……当然，是除了瑟匹克之外最好的猎手。西南方仍然有大规模的战斗——你要去帮忙。$B$B瑟匹克在卡塔克要塞藏了很多厉害的陷阱……告诉维克加，让他利用这些陷阱作战。你也可以挑选自己喜欢的陷阱，用它们多杀些大舌头怪。$B$B越多越好！', '转至卡塔克要塞，取出被瑟匹克藏起来的陷阱。利用它们杀死50个灵鳍鳄鱼人，然后向卡塔克要塞的萨满祭司亚克耶克复命。', '你对那些陷阱的使用几乎就像赛匹克一样棒!', '真是一团乱啊!但还是很好玩。', '', '去索拉查盆地找卡塔克要塞的萨满祭司亚克耶克。', '灵鳍鳄鱼人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12760, '狂心氏族的秘密武器', '卡塔克要塞的战斗仍在继续……是时候告诉你狂心氏族的大秘密了。$B$B我们保存着一种浆果，是从我们的故乡带来的……它本身没有什么特别之处，不过一旦与酒精饮料混合饮用，就可以让狂心狼獾人变得非常强壮。现在你也是氏族的一员了……你也要变强。$B$B我给你一些饮料，喝了之后你就会变得强壮，然后就可以碾碎所有的大舌头怪。', '喝下神秘的狂心氏族饮料，然后在卡塔克要塞附近消灭30个灵鳍鳄鱼人。', '你是个凶猛的战士…快点回来进行更多战斗吧。好架永远打不够!', '费克嘎教了你这个超级秘密，嗯?只有最强的狂心族人才能知道这个秘密。', '', '去索拉查盆地找卡塔克要塞的萨满祭司亚克耶克。', '灵鳍鳄鱼人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12761, '掌握水晶', '狗狗人并未停止对灵鳍湾的攻击……如果我们不加阻拦的话，他们是不会罢手的。我们有秘密武器……我们把它交给了索乌米特，让他保护所有的鳄鱼人。$B$B秘密武器是伟大的造物主留下的……我们在神圣的造物主祭坛中找到了这些闪闪发光的水晶。你要当心……别弄碎了。$B$B水晶就放在西南方灵鳍湾神殿附近的箱子里。你要用水晶帮助索乌米特打败狗狗人。', '拿到灵鳍湾的防御水晶，借助水晶的力量杀死附近的50个狂心狼獾人。完成任务后向灵鳍湾的唤雷者索乌米特复命。', '感谢你，干皮。$B$B我会在这里用水晶继续保护我们的安全。或许你可以快点回来，再帮忙我们一些。', '非常的强大。小狗人不晓得伟大诸神的力量。呆呆小狗人。', '', '去索拉查盆地找灵鳍湾的唤雷者索乌米特。', '狂心狼獾人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12762, '造物主的力量', '狗狗人并未停止对灵鳍湾的攻击，我们必须采取一些措施。亚鲁乌特将他在河流之心发现的特殊水晶交给了我……之前我们只见到过一次类似的东西。$B$B这块水晶现在还没有能量，但是如果你将它带到离源血之柱足够近的地方，石柱的能量应该可以传导到水晶中。完成充能之后，就转至西南方的灵鳍湾，使用水晶让你变得强大起来。$B$B接下来，就该好好教训一下狗狗人了。', '在源血之柱的暴露部分附近为休眠的无瑕水晶充能。转至灵鳍湾，使用水晶的能量杀死附近的30个狂心狼獾人，然后与灵鳍湾的唤雷者索乌米特谈一谈。', '你身上的能量真强…你充满了大神们的力量!$B$B我没说谎，我有点嫉妒。', '有你在这里帮我们真好。好长的战斗。', '', '去索拉查盆地找灵鳍湾的唤雷者索乌米特。', '狂心狼獾人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12771, '铁炉堡', '圣光响应了我们的祈祷！依靠沙塔斯城的纳鲁所赐予的圣光精华，以及虔诚信徒的祈福，我们终于创造出了神圣而强大的圣物，这些圣物将成为我们对抗巫妖王的利器。$B$B带上这个，$n。你要仔细保护它，把它安全地送到铁炉堡。麦格尼·铜须急于转至诺森德参战，这件圣物可以帮助他达成目标。', '拉莎莉尔主教要你将光明圣物交给铁炉堡的国王麦格尼·铜须。', '我的胡子啊!这东西的力量可以和咱们整队的飞行器对抗!我会把它交给我的战斗牧师，我们会设计一个能够把那些肮脏的亡域赶回诺森德的作战计画…然后我们会紧跟在后面!$B$B噢，我的兄弟穆拉丁啊，你一定得好好活着!以铜须的荣誉起誓，我一定会找到你的!', '哈罗，$N。我从没看过这么结实的矮人!外域的试炼让你更强悍了，$g兄弟:姊妹;。你让你的族人很骄傲!', '', '去找铁炉堡的国王麦格尼·铜须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12773, '达纳苏斯', '圣光响应了我们的祈祷！依靠沙塔斯城的纳鲁所赐予的圣光精华，以及虔诚信徒的祈福，我们终于创造出了神圣而强大的圣物，这些圣物将成为我们对抗巫妖王的利器。$B$B带上这个，$n。你要仔细保护它，把它安全地送到达纳苏斯，并交给泰兰德·语风。在她的女祭司们与北地的堕落力量战斗时，它将成为她们手中最强大的力量之源。', '拉莎莉尔主教要你将光明圣物交给达纳苏斯的泰兰德·语风。', '这是什么?真是个恩赐!他们在这个神器中捕捉了如此强大的圣光，它就像是月光一样照亮了夜晚!我们的牧师将会把这个力量导引来对抗我们的敌人，巫妖王的侵略终将失败。谢谢你，$N。我们的世界树会很平安的。$B$B此外，我们感觉到，也许在北方远处有另外一棵世界树，隐藏在巫妖王的领域附近。也许有一天…我们会一起看照两棵树，然后宣示一个和平新时代的到来。', '$N，我的$g儿子:女儿;。我们又再一次被卷入一场可能会毁了一切我们所知事物的冲突中。幸亏有个$C愿意借出$g他:她;的能力来防卫世界树。', '', '去达纳苏斯找神殿花园的泰兰德·语风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12774, '暴风城', '圣光响应了我们的祈祷！依靠沙塔斯城的纳鲁所赐予的圣光精华，以及虔诚信徒的祈福，我们终于创造出了神圣而强大的圣物，这些圣物将成为我们对抗巫妖王的利器。$B$B带上这个，$n。你要仔细保护它，把它安全地送到暴风城。暴风城的国王最近刚刚归来，我想他一定会非常欢迎这件圣物。', '拉莎莉尔主教要你将光明圣物交给暴风城的瓦里安·乌瑞恩国王。', '所以说沙塔斯的神圣教徒依约制造了这东西!这么说来，分派出这么多的牧师和圣骑士到那里去，而非派他们去对抗天灾军，终究是正确的。有了这个神圣武器，我们就可以把那该死的巫妖王和他的爪牙都给击退!$B$B我要表扬你，$N$g大人:女士;。', '$N，我很高兴看到你来这里。你的力量与技巧无人能敌，在这充满苦难的时刻你的援手非常重要。', '', '去暴风城找暴风要塞的瓦里安·乌瑞恩国王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12776, '埃索达', '圣光响应了我们的祈祷！依靠沙塔斯城的纳鲁所赐予的圣光精华，以及虔诚信徒的祈福，我们终于创造出了神圣而强大的圣物，这些圣物将成为我们对抗巫妖王的利器。$B$B带上这个，$n。你要仔细保护它，把它安全地送到埃索达，交给圣光穹顶的先知维伦。他可以借用圣物的力量对抗阿尔萨斯的邪恶部队。', '拉莎莉尔主教要你将光明圣物交给埃索达的维伦。', '啊，我能见到纳鲁的力量在这个东西上闪耀着光辉，如同居住于此的圣光一样。这样的善行可以藉由这个工具来达成;从北方冰冻荒原派来的亡域将必然失败。', '我的$g孩子:女儿;，你在兽人与人类的土地过得不错，这股力量在你身体中逐渐增强…', '', '去找先知维伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12779, '万物的终结……', '虽然击败的血色十字军士兵早已不计其数，但你那黑暗之心仍渴求更多的胜利。你对战斗的渴望无穷无尽，$N。$B$B<巫妖王顿了一顿。>$B$B万物皆有始终，我的死亡骑士。血色十字军的部队也将面对他们的宿命。他们无论如何也不能逃脱即将到来的厄运。也因此，他们将如同狂暴的困兽一般，挣扎到最后一刻，而你将见证这一切。$B$B使用这只号角召唤我麾下的冰霜巨龙，爬上它的背脊，并号令它进行战斗，去迎接你的再一次胜利吧。', '巫妖王命令你消灭血色十字军。$B$B使用冰霜巨龙号角召唤出一条冰霜征服者，和它一起击败150名血色十字军士兵，并摧毁10台血色弩车。灵活地飞出他们的射程，免得自己被乱箭射穿！', '屈膝，勇士。我以此盔替你加冕，完成你令人惊恐的形貌。任何胆敢窥探你黑暗面容的人终将明了死亡将至。别让任何人胆敢反抗你的君王，因为他们得面对你绝不留情的愤怒，$N。$B$B现在只剩下最后的任务……$B$B<巫妖王看向西方。>$B$B圣光之愿礼拜堂。', '把他们全杀光……', '', '去东瘟疫之地：血色领地找死亡裂口的巫妖王。', '击败血色十字军士兵', '摧毁血色弩车', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12781, '欢迎！', '欢迎来到魔兽世界！$B$B为了感谢您购买魔兽世界典藏版，请将这张礼券交给黑锋要塞的女妖希奥克丝。您将得到一份特别的礼物：陪伴您踏上冒险旅途的小宠物！$B$B再次感谢您的支持，请尽情享受魔兽世界的乐趣吧！', '将黑锋要塞礼品券交给黑锋要塞的女妖希奥克丝。', '我们欢迎您来到艾泽拉斯的世界，并从下列独特礼品中供您挑选一样。', '我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品。', '', '去找女妖希奥克丝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12785, '奥格瑞玛', '终于有重大突破了！我们的僵尸样本在天灾的影响下产生了新的特性，并结出了丰硕的果实……$B$B把这只盒子带到奥格瑞玛去。里面是一枚带有僵尸疫病的徽记，上面还有我们添加的其它东西——一种反药剂。这两种将在徽记上相互作用，而我敢肯定，这枚徽记就是治愈疫病的关键。$B$B把这只盒子交给我的助手，药剂师卡尔洛夫。他就在奥格瑞玛的萨尔酋长身边。', '大药剂师普特雷斯要求你将双天灾脑质交给奥格瑞玛的药剂师卡尔洛夫。', '啊，太好了。这颗腐烂头颅的疾病虽然致命，但我们绝对不能惧怕危险或恶心。$N，某天你会了解，这该死的东西是救赎的唯一途径…', '$N，欢迎来到奥格瑞玛。大药剂师普崔司在你来以前先捎了口信过来…你手上有那颗受感染的脑子吗?', '', '去找奥格瑞玛的药剂师卡尔洛夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12786, '雷霆崖', '终于有重大突破了！我们的僵尸样本在天灾的影响下产生了新的特性，并结出了丰硕的果实……$B$B把这只盒子带到雷霆崖去。里面是一枚带有僵尸疫病的徽记，上面还有我们添加的其它东西——一种反药剂。这两种将在徽记上相互作用，而我敢肯定，这枚徽记就是治愈疫病的关键。$B$B把这个盒子交给我的助手，药剂师查恩尼。他就在雷霆崖的玛加萨·野性图腾身边。', '大药剂师普特雷斯要求你将双天灾脑质交给雷霆崖的药剂师查恩尼。', '啊，太好了。这颗腐烂头颅的疾病虽然致命，但我们绝对不能惧怕危险或恶心。$N，某天你会了解，这该死的东西是救赎的唯一途径…', '$N，欢迎来到雷霆崖。大药剂师普崔司在你来以前先捎了口信过来…你手上有那颗受感染的脑子吗?', '', '去莫高雷找雷霆崖的药剂师查恩尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12787, '幽暗城', '僵尸疫病的出现可算得上是因祸得福。在研究治疗方法的过程中，我们深入了解了天灾及其传播过程。我们的研究成果已经帮我们找到了对抗天灾的武器。是武器，也是工具……$B$B拿着这个——里面有一颗僵尸徽记，通过注射我们最近研制出的一种药剂，里面的疫病已经被部分地治愈了。把这东西交给大药剂师法拉尼尔，我要他帮忙做一系列的实验。', '大药剂师普特雷斯要求你将双天灾脑质交给幽暗城的大药剂师法拉尼尔。', '啊，你真是个绝佳的样本。这个疾病， -- 疾病 --', '向你致敬，$N。你从沙塔斯来的吧?你带来了大药剂师普崔司的指示吗?', '', '去找幽暗城炼金房的大药剂师法拉尼尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12788, '银月城', '终于有重大突破了！我们的僵尸样本在天灾的影响下产生了新的特性，并结出了丰硕的果实……$B$B把这只盒子带到银月城去。里面是一枚带有僵尸疫病的徽记，上面还有我们添加的其它东西——一种反药剂。这两种将在徽记上相互作用，而我敢肯定，这枚徽记就是治愈疫病的关键。$B$B把这只盒子交给我的助手，药剂师泰比丝。她就在银月城的洛瑟玛·塞隆身边。', '大药剂师普特雷斯要求你将双天灾脑质交给银月城的药剂师泰比丝。', '啊，太好了。这颗腐烂头颅的疾病虽然致命，但我们绝对不能惧怕危险或恶心。$N，某天你会了解，这该死的东西是救赎的唯一途径…', '$N，欢迎来到银月城。大药剂师普崔司在你来以前先捎了口信过来…你手上有那颗受感染的脑子吗?', '', '去找银月城的药剂师泰比丝。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12790, '来去如风', '有件事不知道你是否了解，是这样，你可以利用我身后平台上的那块水晶，从达拉然传送到下面的晶歌森林废墟中。$B$B当然，你也可以在废墟里找到同样的水晶，然后用它传送回达拉然来，终点就在我上面的那间传送室里。$B$B我推荐你去试一下。', '达拉然紫罗兰之门的大法师塞琳德拉要求你使用通向达拉然下方废墟的传送水晶和通向达拉然的传送水晶。', '太好了，$C。现在你知道如何下去晶歌森林，也知道怎么回来了。', '我感觉到你还没测试那两颗传送水晶。$B$B没关系，慢慢来。', '', '去达拉然找紫罗兰之门的大法师塞琳德拉。', '使用前往紫罗兰哨站的传送水晶', '使用前往达拉然的传送水晶', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12791, '魔法王国达拉然', '你好，$N。我们肯瑞托议会已经将达拉然城邦整体移动到了诺森德，你或许已经知道了，不知道也没有关系。$B$B总之，现在达拉然不再坐落于洛丹米尔湖南岸的保护罩内，而是使用魔法能源飘浮在晶歌森林上空。$B$B我们相信你已经具备拜访这座城市的资格了。做好准备之后就告诉我，我将施展魔法，直接把你传送过去。$B$B等你到了那边以后，去找大法师塞琳德拉，并将这枚戒指作为我们会面的证明交给她。', '将肯瑞托徽记之戒交给达拉然紫罗兰之门的大法师塞琳德拉。', '欢迎来到达拉然。$B$B我会确认戒指已经归还。', '你好，$C。', '', '去达拉然的紫罗兰之门找大法师塞琳德拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12794, '魔法王国达拉然', '你好，$N。我们肯瑞托议会已经将达拉然城邦整体移动到了诺森德，你或许已经知道了，不知道也没有关系。$B$B总之，现在达拉然不再坐落于洛丹米尔湖南岸的保护罩内，而是使用魔法能源飘浮在晶歌森林上空。$B$B我们相信你已经具备拜访这座城市的资格了。做好准备之后就告诉我，我将施展魔法，直接把你传送过去。$B$B等你到了那边以后，去找大法师塞琳德拉，并将这枚戒指作为我们会面的证明交给她。', '将肯瑞托徽记之戒交给达拉然紫罗兰之门的大法师塞琳德拉。', '欢迎来到达拉然。$B$B我会确认戒指已经归还。', '你好，$C。', '', '去达拉然的紫罗兰之门找大法师塞琳德拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12796, '魔法王国达拉然', '你好，$N。我们肯瑞托议会已经将达拉然城邦整体移动到了诺森德，你或许已经知道了，不知道也没有关系。$B$B总之，现在达拉然不再坐落于洛丹米尔湖南岸的保护罩内，而是使用魔法能源飘浮在晶歌森林上空。$B$B我们相信你已经具备拜访这座城市的资格了。做好准备之后就告诉我，我将施展魔法，直接把你传送过去。$B$B等你到了那边以后，去找大法师塞琳德拉，并将这枚戒指作为我们会面的证明交给她。', '将肯瑞托徽记之戒交给达拉然紫罗兰之门的大法师塞琳德拉。', '欢迎来到达拉然。$B$B我会确认戒指已经归还。', '你好，$C。', '', '去达拉然的紫罗兰之门找大法师塞琳德拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12797, '界门的回程', '你说得没错，$r。我可以清晰地感觉到索拉查盆地的能量正在被亡灵天灾腐蚀。$B$B我已经将自己封印在了这枚符文中，$r。将这枚符文交给派你前来的守卫者——只有得到她的允许，我才能踏入她的领地。', '将欧米伽符文带回索拉查盆地的雨声河，交给弗蕾亚的化身。', '你做得很好。$B$B对我们的敌人降下灾难。对服侍巫妖王而威胁泰坦创造物的人降下灾难 -- 伊提米迪安就是为此而来。', '你回来了，$N。', '', '去索拉查盆地找雨声河的弗蕾亚的化身。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12798, '长剑套牌', '你现在已经收集到了长剑套牌的所有卡片，一张新的卡片神秘地出现在你手中。卡面上描绘着一位占卜师，无论你把卡片转动到何种角度，占卜师似乎都在盯着你。$B$B你觉得似乎可以用这张卡片来联络某些人，或某些事物。', '使用长剑套牌召唤一位暗月占卜师，并把套牌交给占卜师。', '暗月马戏团对这些塔罗牌很有兴趣，如果你收集到更多的卡片，不要犹豫，立刻呼唤我们。我们也有自己的商人，所以请让我提供一些东西，来与你交换这些卡片。', '看来你已集满全套的众剑套卡。太好了。', '', '去找暗月占卜师。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12799, '吸取灵魂', '他们说，你应该对他的到来感到庆幸。他们说，你一定会非常欣喜有他加入……$b$b好了好了，反正怎么看我都没有选择的馀地。菲肯斯坦是北伐军里最好的炼金师，他选择我的岗哨开了这家炼金店铺，我真不知道是否应该为此大感荣幸。但既然人已经来了，那就意味着我们得开始为他鞍前马后地收集炼金药材了。$b$b就说，$c，你愿意不愿意帮我这个忙吧？南边有几处被远古巨魔的幽灵占据的池塘，你去那里收集一些他们的灵质来。', '赫布瓦罗的阿纳斯上尉要求你转至扎尔金之池，从迷失的达卡莱灵魂身上收集5份上古灵质。', '谢谢你，$C。$B$B这样应该能为我的手下节省一点宝贵的时间。', '你好，$r。$B$B你收集到菲肯斯坦要求的魂能了吗?', '', '去祖达克找赫布瓦罗的阿纳斯上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12801, '黎明之光', '银色黎明以圣光之愿礼拜堂为依托，顽固地对抗着我们。仅凭这一条理由，他们就应该被碎尸万段！$B$B巫妖王陛下的部队即将发动决定瘟疫之地归属的决战。今天，我们即将步入天灾军团英雄的殿堂！$B$B当你准备好了之后，就向大领主达里安·莫格莱尼报到。他将会亲自率领部队，向圣光之愿礼拜堂发动总攻。', '击败银色黎明的部队，揭开黎明之光的秘密。$B$B如果你活着从战场上归来，就去向大领主达里安·莫格莱尼复命。', '我们罪无可恕，$N。我们将永远受到诅咒，以这具怪物的躯体在世上苟活，也许巫妖王暂时放过了我们，但我们昔日所犯下的罪行也将永远折磨我们的记忆。$B$B只有一种办法可以补偿我们的罪孽……哪就是死亡。$B$B现在，我邀请你加入黑锋骑士团，与我们一起击败巫妖王，终结天灾军团。', '<大领主莫格莱尼点了点头。>', '', '去东瘟疫之地：血色领地的圣光之愿礼拜堂找大领主达里安·莫格莱尼。', '揭开黎明之光的秘密', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12804, '猎人们的肉排', '有些时候呢，最糟糕的事情莫过于有一整个营地的猎人每天出去捕猎，杀死各类大型飞禽走兽，回头来却发现它们的肉都是又干又硬根本难以入口。一整天疲倦的狩猎之后，你回到营地却发现只能吃这些东西，恐怕想死的心都有了。$B$B好在附近不远的地方就有柔软多汁的上等好肉。在河流和营地的南边有不少活蹦乱跳的长颈鹿，这些家伙能给饥肠辘辘的猎人们提供最完美的肉食。去吧，从它们身上切几块最好的肉排回来，让我好好犒劳一下这里的同志们。', '将5份食草长颈鹿肉排交给奈辛瓦里营地的菜刀库尔格。', '看，这才叫做餐点!如果从坠毁到现在有什么好事的话，那就是我们终于不用再吃一整个月的咸牛肉了!谢谢你，$N。', '你弄到那些肉排了吗?', '', '去索拉查盆地找奈辛瓦里营地的菜刀库尔格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12805, '回收生命的力量', '源血之柱崩塌时，巨大的冲击力使大地受到了重创。$B$B那些原本支撑着巨柱运转的生命能量，现在已经沾染到了崩裂碎片周围的那些元素生物身上。我不能就这样眼看着这些能量白白流失，要知道，我们只剩下四根巨柱了。$B$B你现在立刻转至东南方的崩裂碎片，并寻找那些源血元素。$B$B找到它们之后，先将其杀死，然后对它们的残骸使用这颗宝钻，回收它们释放出来的能量。在一切都结束之后，我们还要用这些能量来抚平大地的创伤。', '弗蕾亚的化身要求你转至东南方的崩裂碎片，消灭8只源血元素，然后对它们的躯体使用源血宝钻。', '我感谢你，$N。虽然柱子倒下是件憾事，但我们一定得尽力抢救。', '你收回元素身上的能量了吗，$N?', '', '去索拉查盆地找雨声河的弗蕾亚的化身。', '恢复源血能量', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12809, '铁炉堡', '圣光响应了我们的祈祷！依靠沙塔斯城的纳鲁所赐予的圣光精华，以及虔诚信徒的祈福，我们终于创造出了神圣而强大的圣物，这些圣物将成为我们对抗巫妖王的利器。$B$B带上这个，$n。你要仔细保护它，把它安全地送到铁炉堡。侏儒区的大工匠梅卡托克正在期待着借助圣物的力量为联盟效力。', '拉莎莉尔主教要你将光明圣物交给铁炉堡的大工匠梅卡托克。', '不能想象的纯净!这个设备存储的圣光能量远远超过现在已经的任何东西!喔，这几乎让我的胡须和脚指都在发抖了。喔哈!我可以用这个造出抗夜间影像分布促动器，能让黄昏变成黎明!天灾军团甚至不会知道什么打中了他们。我们只要拉下拉杆就可以把他们一扫而空!', '嗨，$N!瞧瞧你!离我上一回见你，你成长了一点七三微指距。我很确定外域的空气一定对你有所影响。', '', '去铁炉堡找侏儒区的大工匠梅卡托克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12810, '水中之血', '先锋军港口的狮鹫骑士严密地掩护着他们的地面部队，你需要一匹飞行座骑才能把他们都打下来。不过首先，我们得收集到足够的材料来引导仪式，制造出你所需的飞行座骑。$B$B这个仪式必须要用到大量的鲜血。$B$B<说着，指挥官向西北方指了指。>$B$B若是说血的话，那边的港口里难道不就有无数吗……我是指鲨鱼。在把这个气泡装满它们的血之前不要回来。', '死亡高地的高级指挥官埃雷特要求你用10只饥饿的巨鲨的血装满血囊。', '干得好。稍待一下，等你身上的海水干了我们再继续。', '并不是什么很棒的工作，但却是必须的工作。$B$B现在告诉我，为什么我们要在你完成工作之前一直讲话，$C?', '', '去冰冠冰川找死亡高地的高级指挥官埃雷特。', '从饥饿的巨鲨身上收集血液', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12812, '奥格瑞玛', '终于有重大突破了！我们的僵尸样本在天灾的影响下产生了新的特性，并结出了丰硕的果实……$B$B把这只盒子带到奥格瑞玛去。里面是一枚带有僵尸疫病的徽记，上面还有我们添加的其它东西——一种反药剂。这两种将在徽记上相互作用，而我敢肯定，这枚徽记就是治愈疫病的关键。$B$B把这只盒子交给我的助手，药剂师卡尔洛夫。他就在奥格瑞玛的萨尔酋长身边。', '大药剂师普特雷斯要求你将双天灾脑质交给奥格瑞玛的药剂师卡尔洛夫。', '啊，太好了。这颗腐烂头颅的疾病虽然致命，但我们绝对不能惧怕危险或恶心。$N，某天你会了解，这该死的东西是救赎的唯一途径…', '$N，欢迎来到奥格瑞玛。大药剂师普崔司在你来以前先捎了口信过来…你手上有那颗受感染的脑子吗?', '', '去找奥格瑞玛的药剂师卡尔洛夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12813, '转化尸体', '我们的指挥官大人真是太善良……太慷慨了。相比于人见人爱花见花开、到处撒播阳光的他，我的内心深处充满了阴暗的东西，比如仇恨什么的。$B$B在我看来，光是终结他们那悲惨的生命是不够的，远远不够！我还要让他们承受无尽的屈辱！$B$B你想想，有什么能比沦落成你最仇恨最厌恶的事物更令人难以忍受的呢？你的一生都是为了消灭某些东西而存在，可到头来你却变成了它们？$B$B多可悲啊。$B$B带着这些药剂转至西北方的先锋军港口，把它倒在先锋军士兵的尸体上，看看有什么效果。不过，注意避开大教堂。', '死亡高地的希塔尔·达克门德给了你一份达克门德的药剂，并要求你对先锋军港口一带的任意10具血色先锋军成员的尸体使用它。', '<德莱尼死亡骑士用冰冷的眼神盯着你看。她的眼神和墓穴一样死气沉沉。一丝狡猾的微笑爬上她的脸颊。>$B$B我明天还会准备好更多的酊剂。在那之前，好好保重吧。', '想必你没那么快完成吧?', '', '去冰冠冰川找死亡高地的希塔尔·达克门德。', '转化血色先锋军成员的尸体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12814, '你需要狮鹫', '你说，能有什么事比起利用他们自己的狮鹫来对付他们更加令人愉快呢？立刻前往先锋军港口，随便干掉哪个倒霉的狮鹫骑士，从他手中抢过狮鹫的缰绳。$B$B然后，你直接回到这里来，把狮鹫交给乌佐·唤亡者。他会妥善地将那只狮鹫做一些改变，并让你骑着它执行下一步任务。', '将一只先锋军狮鹫交给死亡高地的乌佐·唤亡者。', '喔太好了，这一定很棒!$B$B往后面站…我要召唤鲜血仪式的愤怒了!', '为什么花了那么久?他们的狮鹫兽速度很慢吗?我们可得想点办法才行!', '', '去冰冠冰川找死亡高地的乌佐·唤亡者。', '将先锋军狮鹫交给乌佐·唤亡者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12815, '禁飞区', '现在你已经得到白骨狮鹫了，我要求你每天带着它回到这里来执行任务，将先锋军港口的空域变成禁飞区。$B$B好吧好吧，其实你用白骨狮鹫也好，不用也好，只要能把那帮血色先锋军都打下来就行。但我得说，如果你真的试过我们的白骨狮鹫，就会发现用它们作战会容易许多。$B$B顺便说一句，白骨狮鹫有很多非常厉害的阴招，你可千万别忘了用。', '死亡高地的乌佐·唤亡者要求你杀死10名先锋军狮鹫骑士。', '这就对了!而且你要知道，我们每天都需要有人做这项工作。$B$B希望你明天还会回来。你的骸骨狮鹫兽会等着你。', '你这么快回来做什么?我还看到那些突袭军的小子在下面飞来飞去哪!', '', '去冰冠冰川找死亡高地的乌佐·唤亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12816, '调查银月城的天灾入侵', '巫妖王的部队已经在我们鼻子底下扎了营，我们可不能坐以待毙！你会拿起武器跟这些可憎的入侵者作战，保卫银月城的吧？$B$B城外出现了奇怪的符文法阵，它散发着神秘的能量，亡灵和悬浮在半空的浮空城也被同样的能量环绕着。我想这个符文法阵对天灾士兵们必然有着重要的意义，因此想让你调查此事。去和城外的亡灵作战吧，带回你杀死他们的证据，以及你的调查结果，我会奖励你的。去吧！', '从银月城外面的天灾士兵身上收集3块暗淡的死灵石，并调查天灾营地附近的发光符文法阵。', '嗯。从你告诉我的事情，法阵里的声音……它们一定是被用来做为某种沟通的工具。我一想到那些邪恶的脑袋会通过这样的魔法联系就不寒而栗。无论如何，你看起来还是很健全很清醒。银色黎明感谢你的努力。', '你调查过入侵行动了吗?没有时间可以浪费了!', '调查法阵', '去找永歌森林的尤雷克上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12817, '调查埃索达的天灾入侵', '巫妖王的部队已经在我们鼻子底下扎了营，我们可不能坐以待毙！你会拿起武器跟这些可憎的入侵者作战，保卫埃索达的吧？$B$B城外出现了奇怪的符文法阵，它散发着神秘的能量，亡灵和悬浮在半空的浮空城也被同样的能量环绕着。我想这个符文法阵对天灾士兵们必然有着重要的意义，因此想让你调查此事。去和城外的亡灵作战吧，带回你杀死他们的证据，以及你的调查结果，我会奖励你的。去吧！', '从埃索达外面的天灾士兵身上收集3块暗淡的死灵石，并调查天灾营地附近的发光符文法阵。然后向克雷格尔上尉复命。', '嗯。从你告诉我的事情，法阵里的声音……它们一定是被用来做为某种沟通的工具。我一想到那些邪恶的脑袋会通过这样的魔法联系就不寒而栗。无论如何，你看起来还是很健全很清醒。银色黎明感谢你的努力。', '你调查过入侵行动了吗?没有时间可以浪费了!', '调查法阵', '去找埃索达的克雷格尔上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12818, '清理残骸', '我们还是来谈正事吧……莉吉特要我组装一些威力更大的地雷，但我手里的零件不多了。$B$B镇子的西边有一堆火箭车的残骸，那是我们最后一辆火箭车……莉吉特在给它加油的时候有点过于激动了，不过我觉得我似乎不应该把喷嘴直接装在排气设备上。所以说活到老学到老，不是吗？$B$B在撞坏的火箭车周围肯定散落着大量零件……你不如去把那些杂七杂八的麻烦鬼赶走，给我收集一些零件回来？', 'K3的基尔·斯巴索克需要10份烧焦的零件。', '这些就可以了，谢啦!$B$B你有在那里看到丁姆吗?我之前派了他过去，但他再也没回来过。我希望他没事。$B$B说到这个…我很好奇詹克斯到哪去了……', '我们需要一些可以用来加热引擎来对抗这酷寒的东西…快想啊吉尔，快想!$B$B喔嗨!你替我弄到残骸了吗?', '', '去风暴峭壁找K3的基尔·斯巴索克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12819, '雷区里的工具', '该死的！我的工具呢？刚才还放在这儿的。$B$B噢！我可能在安放地雷的时候把它们忘在西边了。这可有点麻烦。如果你能帮我把它们拿回来，我会非常感激你的。但你可能需要留神脚下……你应该可以沿着我离开的路进去。$B$B哦，不要试图飞进去……我当时灵机一动，在那里安装了专门对付飞行物体的炮台，而且它们是不能辨别目标的。', 'K3的基尔·斯巴索克要你进入雷区，取回斯巴索克的工具。', '哈哈!就是它们!真谢谢你。我希望你在穿越雷区的时候不算太困扰。', '如果詹克斯在这儿的话，我只要派他去跑这腿就好了。噢…再想一想…我也不太确定我告诉他安全的路径在哪里了。$B$B幸亏有很多你们这种冒险份子在这附近，嗯?', '', '去风暴峭壁找K3的基尔·斯巴索克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12820, '亲密接触', '我等这些地雷已经等了一万年了！好吧，至少有好几天了。他怎么花了这么长时间？$B$B这个地方非常下等……到处都是恶心的猛犸人——你知道啦，他们体格很大，毛茸茸的，还非常丑陋——而且他们似乎非常狂热地想要霸占K3。$B$B但这是不可能的。$B$B我们已经在东北方的必经之路上设置了防御工事。可惜的是，我们的激光炮台能量供应有限……所以就要用到这些地雷了！去把他们都炸上天！', 'K3的莉吉特要求你转至加姆雷区，使用改进型地雷杀死12个从加姆方向冲过来的敌人。加姆入侵者和雪盲追随者都算数。', '于是…我就坐在这里，沉浸在我自己的伟大之中，然后我听到远方传来一声啪!然后又一声!再十几声!然后想到那些热切地奔向死亡的猛玛象人和狗头人，我的脸上就浮现了一道微笑。$B$B那是不是很精彩呀?', '我希望你也有顺便宰掉一些恶心的小狗头人，嗯?', '', '去风暴峭壁找K3的莉吉特。', '杀死加姆入侵者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12821, '开后门', '工兵小队已经准备好了。我们又有乐子了，亲爱的！$B$B现在只差搞定一件事，我们就可以完全攻陷加姆了！我派了一个人到加姆的后方去设置传送器——我必须说明，这一步是非常成功的——然后他回来拿引导传送器所需的能量块。可是传送器到现在还没有引导……这说明他没有把能量块送到那里。$B$B我要你穿过加姆雷区并找到能量块，然后用它引导位于加姆后方的加姆高地上的传送器。', 'K3的莉吉特要你去找到传送器能量晶格，并用它引导加姆高地的传送器。', '太棒了!$B$B<瑞基特脸上浮现一副凶狠的笑容。>$B$B让毁灭降临吧!', '就算是猛玛象人也该知道不要惹哥布尔。', '引导加姆传送器', '去风暴峭壁找K3的莉吉特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12822, '无所畏惧', '现在传送点已经打开了，我的计划是相当复杂的……这个计划涉及几个方面，而且要求精确的配合。而且我们还需要收集补给！还要招募士兵！可能还需要好几个星期的辛勤劳动！$B$B哈哈，很向往了吧！非常好，孩子，就看你的了。通过传送点抵达那里，然后向他们开战！我们的工兵会支持你的……他们无路可逃了。', 'K3的莉吉特要你去杀死6个加姆观察者和8个雪盲信徒。', '哈哈!这可给那些浪费我们时间的笨蛋上了一课。从今天开始，绿色的皮肤会让所有的猛玛象人打从心底恐惧!', '没有什么比哥布尔工兵更能直接对敌人造成恐慌的啦!', '', '去风暴峭壁找K3的莉吉特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12823, '完美的计划', '嘿，你！我猜你是来参加战斗的吧？$B$B我要交给你一项特殊任务……我们要把整个洞穴炸塌！到他们的洞穴顶部去，你可以找到霜胆的祭坛。悄悄靠近祭坛，把这只重磅炸药包放在祭坛附近。$B$B放好炸弹之后，你就在一边等着，确定塔尔玛·霜胆碰到炸弹之后再迅速离开！没人知道那玩意爆炸以后，这座洞穴还能支撑多久！', '加姆高地的吉诺要你把重磅炸药包偷偷放到霜胆的祭坛附近，炸死塔尔玛·霜胆，然后在洞穴坍塌前逃出来。', '整座山都在摇晃!一定很灿烂吧?我想一定是!怎么可能不灿烂呢?$B$B发明家协会还说我的东西都只会爆炸。该死的，他们还真说对了!哈!', '这个盒装爆裂物可是我的宝贝…花了我好几周的时间才做到完美。好几周!$B$B那可是很长一段时间…好吧。', '', '去风暴峭壁找加姆高地的吉诺。', '放置炸药包', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12826, '新型地雷', '看起来不错！$B$B不，我说的不是你——是我的新地雷。你是不是有点自恋啊？而我，绝对是才华横溢！我的智慧简直是无与伦比。$B$B我们刚才说到哪里了？哦，对了，我的新地雷！全新的改进型号……可以适应莉吉特的任何异想天开的计划。$B$B现在你就做个好孩子，去把它们送给莉吉特，好吗？她就在那边……这必定是一趟伟大的旅程。但你要小心，她有一点神经质。', '把基尔的改进型地雷交给K3的莉吉特。', '嗯，你不觉得这是你看过最可爱的毁灭小包裹吗?', '吉尔做好地雷了?好家伙。', '', '去风暴峭壁找K3的莉吉特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12827, '收集粮食', '嘿！新来的！能帮莉吉特一个忙吗？$B$B我们遇到了一个预料之外的问题……粮食不够了。我知道，我知道……我们应该想到这点，但你不明白。我们本来是想用工兵部队进行快速作业的，所以通常来说，我们不用担心长期性的饮食问题。但是呢，最近来K3的人越来越多了。$B$B解决方案？西面有一些豺狼人的营地……还有些豺狼人四处游荡，干着些捡破烂的勾当。你能去它们那里抢些粮食回来吗？', 'K3的莉吉特想让你从附近的野蛮岭豺狼人那里夺取16份豺狼人的干粮。', '我希望他们分享财富的时候能少点犹豫。我们至今对他们捡咱们垃圾的行为都很容忍。', '嘿你又来啦!我肚子在叫…进行的如何?', '', '去风暴峭壁找K3的莉吉特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12828, '突发奇想', '哇！真恶心。且不说豺狼人的口味如何，但我还以为它们的东西至少应该是……可以吃的东西吧。$B$B我们得想一些更有创意的点子。$B$B这样，托莉在镇子北边部署了一台炸弹储备机……离那个大洞穴的入口不远，你一定不会找不到的。我估计她是想要用炸药进行挖掘工作之类的，但我有一个更好的主意。$B$B你去拿一颗炸弹，把它扔向附近的某一头猛犸象……它们大部分都在西边活动。把它们的肉给我拿回来。', 'K3的莉吉特要你去拿取一颗D16限时炸弹，用它炸翻一头猛犸象，然后收集8块巨大的猛犸肉。', '都已经全熟啦!我自己改天也来做做看。$B$B谢啦，朋友!', '我知道我的计画很棒。别担心啦。$B$B跟大人物相处的感觉怎么样?蛮刺激的对吧?', '', '去风暴峭壁找K3的莉吉特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12829, '进入矿洞', '你好呀！我叫托莉，是K3的矿业部门的负责人……或者说很快就是了！$B$B这个洞穴里到处都是恶心的蜘蛛。我觉得，在我们进去之前，应该先除掉一些蜘蛛，你说呢？', '水晶蛛网洞穴外的托莉·兰波维奇要你杀死12只水晶蛛网蜘蛛。', '哈哈!很高兴看到你负责处理这些烂工作。$B$B感谢你啊，伙伴!', '小心那些炸弹配给器!那些东西很危险的。', '', '去风暴峭壁找水晶蛛网洞穴的托莉·兰波维奇。', '杀死水晶蛛网蜘蛛', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12830, '收集矿石', '可以进去啦！$B$B我们刚刚抵达这里的时候，洞里有一些狗头人……但它们在挖矿的时候似乎遇到了某些不幸的事。不过影响不大，我们很快就控制了局面。$B$B我派了几个矿工进去找一些矿石样本，好让我可以调整机器继续前进，但他们一直都没回来。$B$B你能进去帮我拿些样本回来吗？里面的狗头人可能随身带着矿石，不过我猜它们差不多都死光了。', '水晶蛛网洞穴外的托莉·兰波维奇要你去收集5份不纯的萨隆邪铁矿石。', '喔!可真是臭啊!你被迫杀了些极地狗头人对吧?$B$B不过我倒是很真的感激你!', '你替我弄到矿石没?', '', '去风暴峭壁找水晶蛛网洞穴的托莉·兰波维奇。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12831, '未被遗忘', '呕……我的胃里好象装了个螺旋桨。$B$B我应该还能走动，但我被洞穴深处的什么东西给咬了，现在浑身都不舒服。那东西比其它蜘蛛都大……而且色彩非常鲜艳。$B$B莉吉特没准能帮我做出解毒剂来，但她肯定要用到咬我的那个东西身上的毒囊。你能帮我找到毒囊吗？我想托莉是不会进来的。$B$B我会在这里装死，希望它们别来碰我。', '水晶蛛网洞穴里的受伤的地精矿工希望你从冰尖爬行者身上找到一个冰尖毒囊。', '这应该行了…我希望瑞基特能替我调出点东西来。那么，准备好要离开这里了吗?', '<受伤的哥布尔矿工痛苦地扭曲身子。>', '', '去风暴峭壁的水晶蛛网洞穴找受伤的地精矿工。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12832, '痛苦的离别', '呀，谢谢你！我还以为这次肯定要喂蜘蛛了呢。或许我有点太心急了——但我们还是尽快离开这里吧！$B$B准备好了就告诉我……快一点。', '护送受伤的地精矿工离开水晶蛛网洞穴，然后与K3的莉吉特谈一谈。', '谢谢你把我的矿工救回来这里，$N!我应该可以轻松制造出解毒剂。$B$B如果你再碰到托尔，替我告诉她，她是个笨蛋，好吗?', '我想洞窟里状况还不错吧?托尔对你好不好?', '护送受伤的地精矿工转至K3。', '去风暴峭壁找K3的莉吉特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12833, '库存过剩', '嘿，你好啊！你怎么没有像其它冒险家那样逃走啊？嘿，你真是个讨人喜欢的家伙！我还以为自己身上有什么奇怪的味道呢！$B$B我们仍然需要你的帮忙，而你又正好有着丰富的经验。记得那些猛犸人吗？很显然，山洞并没有完全坍塌……仍然有很多猛犸人活了下来。还有很多需要我们操心的，是不是啊？$B$B幸运的是，基尔制作了足够多的地雷。就靠你了！', 'K3的莉吉特要求你转至加姆雷区，使用改进型地雷杀死12个从加姆方向冲过来的敌人。加姆入侵者和雪盲追随者都算数。', '我喜欢你。老实说，你酷毙了!$B$B为你欢呼!', '磅!哈哈!', '', '去风暴峭壁找K3的莉吉特。', '杀死加姆入侵者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12836, '感激之情', '我正好有个工作非常适合满怀热情的新人！我们遇到了一个有关豺狼人的棘手问题……甚至可以说是巨大的威胁！这群令人讨厌的东西。它们的数量越来越多，现在竟然胆敢到我们眼皮底下偷零件了！真是不可思议。$B$B这一切的罪魁祸首都是它们那自以为是的首领——瘤皮。我希望你明白我的意思……转至西边的雪盲岭，到它的营地里去拜访它一下。$B$B你知道，我所说的“拜访它一下”是我对“让它死得难看一点”的委婉说法，明白了？明白就好！', 'K3的莉吉特要你去杀死瘤皮。', '妙极了!我就是喜欢你这样的$r。', '我喜欢瑞基特因为她这个人很妙!$B$B噢，你好啊，又见面了!你的害虫控管做的怎么样了?', '', '去风暴峭壁找K3的莉吉特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12838, '收集情报', '我希望能知道血色先锋军今天的行动计划，而你将是我达成此目标的工具。$B$B立刻飞到先锋军港口去，在他们的辎重箱里找到我要的文档。箱子应该是上了锁的，所以你要采取任何必需的手段，从血色先锋军成员身上抢到钥匙。', '死亡高地的奥卢克斯·邪鬃要求你去收集5份先锋军情报文档。', '交给我吧。我会筛检掉没用的情报，如果找出任何需要采取行动的数据，我会召唤你。$B$B无论如何，明天再过来一趟。他们是以每天改变行动方针闻名的。', '你替我弄到那些数据了吗?', '', '去冰冠冰川找死亡高地的奥卢克斯·邪鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12839, '元帅的计划', '一开始你以为这封信与其它的情报没什么不同。但在简略地阅览之后，你彻底打消了之前的想法，重视起这封信来。$B$B这封信中指出，巴利·韦斯温元帅当前就躲在这座岛屿上的某个地方，不过，他完全避开其它人，谨慎地掩饰着自己的行踪。他宣称，血色先锋军在不远的将来会消灭巫妖王，进而征服整个世界，让艾泽拉斯重获秩序。$B$B高级指挥官一定会对此很感兴趣。', '将韦斯温元帅的便笺交给死亡高地的高级指挥官埃雷特。', '韦斯温写的信笺?你为什么不早讲呢?$B$B<艾睿特从你手中把信抢去阅读。>$B$B这个蠢蛋!他真的在这儿?!$B$B<统领指挥大笑。>$B$B这是全新的情报。我很好奇他是如何幻想要在打倒巫妖王之后征服世界的呢?就算是他，也没办法在自己脑中完成这两桩疯狂想象的任何一个吧。', '血色先锋军情报应该要送去给野牛.厉祸才对。$B$B<统领指挥用一种想打发你走的表情看着你。>', '', '去冰冠冰川找死亡高地的高级指挥官埃雷特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12840, '心腹的情报', '先锋军港口内停泊着不少血色先锋军的战舰，这些战舰的船长们恐怕是最了解元帅行踪的人。$B$B<高级指挥官搓了搓双手，继续推理着。>$B$B在我印象中，那两个船长……是叫维辛顿和哈弗德吧。去拷打他们，逼问出这条重要的情报，然后结束他们那悲惨的生命。$B$B我必须弄清楚这个韦斯温元帅到底躲在哪儿！', '死亡高地的高级指挥官埃雷特要求你拷打维辛顿船长和哈弗德船长，并从他们口中得到情报。', '他们把兰格瑞复活了?那么他就是知道上将所在之处的人!', '海军上将韦斯温在哪?', '', '去冰冠冰川找死亡高地的高级指挥官埃雷特。', '拷打并杀死维辛顿船长', '拷打并杀死哈弗德船长', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12841, '女巫的交易', '没错，你一定是来找那个绿皮囚犯的……也许我们可以互相帮助。$B$B你是不可能强行把那个地精救出去的。起码不可能活着救出去。$B$B我的族人都称我为“伊克芬”，意思是幻术师。你也看到了，海德尼尔人把我囚禁了起来。$B$B如果你能搞到我的符文，我就可以帮助你乔装打扮一番。到矿井深处去找到正在巡逻的监督者希尔拉，她手里拿着我的符文。把它们夺回来，然后我们再谈谈。', '荒弃矿洞的女巫洛莉拉要求你从监督者希尔拉手中夺回伊克芬符文。', '我以为你回不来了。我不敢去想象如果我再待下去会怎样。', '我的符文呢，$N?你拿到没?', '', '去风暴峭壁找荒弃矿洞的女巫洛莉拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12842, '符文熔铸：战争的准备', '战争的烙印早已不可磨灭地蚀刻在了你灵魂的深处，死亡骑士。现在你已经学会了符文熔铸这项高深的黑暗艺术，有了它，你就可以把令人敬畏而恐惧的符文之力封印在武器中。$B$B现在我们必须立刻开始进行战争的准备了。回到阿彻鲁斯之心的符文熔炉边上去，利用符文熔铸技能，为你的武器附着符文之力！$B$B当你的利刃上真正流淌起黑暗的力量时，回来向我复命！', '黑锋要塞的教官拉苏维奥斯命令你使用“符文熔铸”能力为你的符文之剑附上任意一种由你选择的符文。$B$B只要在符文熔炉旁，你就可以随意替换附着在武器上的符文种类，无需消耗任何材料。', '记住这些话，死亡骑士:符文熔炉是一种天灾设备。它只存在于亚榭洛、纳克萨玛斯、以及冰冠冰川的中心!你只能够在符文熔炉刻缚你的武器。$B$B记得时常回来把你所有的武器刻上符文。一个死亡骑士必须准备好面对所有胆敢反抗$g他:她;的东西!', '不要浪费时间，$N。我们已经濒临天启的时刻了!', '在武器上附着符文', '去找阿彻鲁斯：黑锋要塞的教官拉苏维奥斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12843, '她们把男人都抓走了！', '你一定要帮帮我们！我们受到袭击时正在往山里走，想要在山里建设一座中继塔。$B$B那些人看起来像维库人，但皮肤是蓝色的，上面还结着一层霜……而且都是女性！她们把队伍里的男子都抓走了，把我们这些女性都放了。求求你，$N！他们应该都被关在那个名叫希弗列尔达的村子里了，就在K3的上面。', '格莱奇·菲兹巴克要你转至希弗列尔达村，救出5名地精囚犯。', '你办到了!咱的男孩们回来了!', '你找到我们的男人了吗，$N?', '', '去风暴峭壁找K3的格莱奇·菲兹巴克。', '营救地精囚犯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12844, '夺回设备', '请你帮帮忙，$N。海德尼尔人在抓走队里的男子时，还把我们所有的设备都抢走了。当然，人能回来是最重要的，但是如果你能找到我们的设备，请顺便把它们拿回来，我们都会非常感激你的。$B$B她们的村子就在我们北边的高山上。', '格莱奇·菲兹巴克要你转至K3北方的希弗列尔达村，找回8件K3设备。', '谢谢，$N!我们会好好想想要怎么利用这些装备的!', '有没有找到我们的装备，$N?', '', '去风暴峭壁找K3的格莱奇·菲兹巴克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12847, '第二次机会', '我的确听说过在他们的大教堂内有一位大主教，但我怎样也不会想到，他们竟然复活并晋升了兰德雷，这位大主教竟然就是他！大教堂有重兵守卫，而且只有一个入口，所以你需要一些帮助。$B$B我们现在仍然迫切地需要得知韦斯温元帅的位置，但我们要力求稳妥，不能有一丝冒险投机的心理！$B$B带上这个设备，它可以打开一道传送门，让我在你杀死大主教之后转至现场。$B$B到时候，我会亲自从他那卑微而懦弱的灵魂身上找到我想要的答案！我们一定会找到巴利·韦斯温元帅！', '杀死大主教兰德雷，并在他的尸体旁召唤出埃雷特之门。等高级指挥官埃雷特从大主教的灵魂那里拷问出情报以后，在赤色大教堂内与他谈一谈。', '海岛背面的隐藏洞窟。真是有趣。$B$B好吧，至少我现在知道我那些失踪的间谍都哪儿去了。', '嗯?', '', '去冰冠冰川找死亡高地的高级指挥官埃雷特。', '', '召唤埃雷特之门', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12848, '无尽的饥渴', '无尽的痛苦很快就将占据你的身心，$c。你唯一的选择只有服从我的命令。$B$B现在我授予你救赎的钥匙。$B$B你看见那些被锁链锁在阿彻鲁斯之心的叛徒了吗？拿着这把钥匙，去释放一个叛徒，然后将其击败。胜利，将终结你的痛苦；失败，你将永远在痛苦中煎熬。$B$B选择权完全属于你。', '黑锋要塞的教官拉苏维奥斯命令你释放一名黑锋叛徒，并击败他。$B$B不成功，则成仁。', '如我所料，我所选定的骑士凯旋归来!你已经准备好了，$N。', '两条性命，但只有一把钥匙…不要令我失望，$N。', '', '去找阿彻鲁斯：黑锋要塞的教官拉苏维奥斯。', '击败黑锋叛徒', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12851, '骑熊作战', '真正的试炼在等着你，女人！$b$b你是想成为战士中的女王呢，还是想做一个拖着鼻涕的缝衣女工？$b$b只要尝试一下战斗的滋味，你就能知道答案了。$b$b或许你可以欺骗你的母亲、姐妹，甚至欺骗你自己，但战场总能让一个人的本性暴露无疑。$b$b一旦你做好准备，就骑上冰牙去参加战斗吧。你必须骑在它的背上，将死亡之雨倾泻到我们敌人的头上。', '布伦希尔达村的布莉亚娜要求你骑着冰牙转至上古寒冬山谷，在那里射击7头冰霜座狼和15个冰霜巨人。', '也许你的确具备战士之心。$B$B时间将证明一切……', '你在战斗中幸存下来了吗，$N?', '', '去风暴峭壁找上古寒冬山谷的布莉亚娜。', '烧伤冰霜座狼', '烧伤冰霜巨人', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12854, '布莱恩的踪迹', '自从我们在灰熊丘陵发现布莱恩的日记之后，就很少得到与布莱恩相关的消息了。不过最近，在铁炉堡的探险者协会总部发现了一张神秘的便笺，谁也不知道这东西究竟是怎么来的。上面只是写着，我们必须转至布莱恩的营地与他碰面，并帮助他寻找某样东西。$B$B据我所知，他的营地应该就在这里的东北方，伯尔之息河的对面，泰坦之路的废墟附近。', '在布莱恩的营地中找到用麻布裹起来的便笺，把它交给冰霜堡的考古学家安多林。', '<考古学家安多林满怀期望的看着你。>$B$B你应该要带布莱恩一起回来的，而不是只带张纸回来。发生了什么事?', '你找到布莱恩的营地没?', '', '去风暴峭壁找冰霜堡的考古学家安多林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12855, '跟踪罪犯', '布莱恩在日记中暗示道，他将一包东西连同这本日记一起埋了起来。这些就是你能找到的所有线索吗？$B$B这样吧，霜脉矮人利用嗅觉敏锐的冰霜猎犬来跟踪猎物。我同意让你带上一只猎犬转至那座被毁坏的营地，让它闻闻布莱恩的气味。$B$B至少它能带你找到那些失踪的物品。如果运气够好的话，说不定还能找到布莱恩本人呢。', '在被遗弃的营地使用冰霜猎犬的项圈，查明是谁偷走了布莱恩的物品。找到这些东西之后，使用通讯设备与你所联系到的人进行交流。', '你…你不是探险者协会的一员，至少不是我记得的人。但是，如果你已经找回了通讯器，那么一定是他们派你来的。很好，我几乎就是在期望这样的情形。', '你是谁?', '', '使用通讯器联络任何你想联络的人。', '追踪小偷', '', '杀死小偷', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12856, '冰冷的心', '能战死沙场是我们的光荣，好姐妹。但是被冻成冰块并遭受无休止的耻笑并不光荣。$b$b你要飞往上古寒冬山谷的东边，进入冰霜巨人的城市——丹尼芬雷，解救一条被获取的始祖幼龙。有了它的帮助，你就可以把我们的姐妹从冰块里解救出来，并把她们安全地带回家。$b$b你要小心那些巨人的棍棒，免得自己也变成俘虏中的一员。', '布伦希尔达村东边的布莉亚娜要你飞往丹尼芬雷，解救3头被俘虏的始祖幼龙，然后解救9名布伦希尔达囚犯。', '你的任务似乎成功了，姊妹。$B$B你为布伦希尔达带来了荣耀!', '你的任务成功了吗，姊妹?', '', '去风暴峭壁找上古寒冬山谷的布莉亚娜。', '解救布伦希尔达囚犯', '解救始祖幼龙', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12857, '悬赏：怒鬃的鳍肢', '由怒爪酋长发布：$B$B怒爪酋长忠石的海狮——怒鬃咬伤了我的手。怒爪酋长觉得因为达库鲁巨魔的出现，怒鬃变坏了。怒爪酋长非常伤心地希望有人能勾去杀死怒鬃，把它的鳍肢作为证巨带回来。$B$B你可以在东南边的怒爪湖里找到怒鬃。$B$B怒爪酋长对错字表示抱欠。这是我第一次使用这中东西；而且，怒爪酋长是个狼獾人。', '得到怒鬃的鳍肢，将它交给圣光据点的怒爪酋长。', '<怒爪酋长哭了。>$B$B我从小把他养大。真是伤心的一天。先是巨魔攻击怒爪，然后巨魔害怒鬃变坏。怒爪再也不跟巨魔做生意了!', '可怜的怒鬃。他是我小舅送我的。', '', '去祖达克找圣光据点的怒爪酋长。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12858, '拼图游戏', '感谢圣光，总算有人看懂了我留下的消息。我已经逃出了铁矮人的魔掌，现在很安全。不过我需要你的帮助。解封奥杜尔文件的关键就是诺甘农的钥石，但是泰坦将它分成了两截，分别藏了起来。$B$B其中一截叫做诺甘农之壳，它被藏在奥杜尔以南，位于北部海岸的创世者的图书馆内。首先，你要从图书馆的守卫者手中取得一张圆盘的碎片。', '收集6块创世者的圆盘碎片，将它们组合成创世者的圆盘。', '太棒了!既然我们有了圆盘，那你一定要用它打开发明者的宝库!', '你把圆盘拿到手了吗?', '', '使用布莱恩的通讯器联络布莱恩·铜须。$B$B如果你弄丢了联络器，你可以与冰霜堡的考古学家安多林重新要个新的。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12859, '火仍在烧！', '巨魔攻击了怒爪巢穴，把怒爪狼獾人赶了出来！更糟的是，巨魔正在焚烧怒爪狼獾人的村庄，他们都是坏人！酋长让最厉害的萨满祭司莫奇去灭火，但是很奇怪！火还是很热，会烧掉一切。$B$B你能帮怒爪狼獾人去灭火吗？莫奇会给你怒爪狼獾人的特殊灭火器，去扑灭东南方怒爪巢穴里的火焰。有时候要喷很多下才能灭火，不过灭火器总是有足够的水！这就是厉害的怒爪魔法！', '圣光据点的萨满长者莫奇希望你转至怒爪巢穴，使用怒爪灭火器扑灭15堆火焰。', '很怪，我知道你把火灭了，但火还是在烧。也许这东西没用，呃?不过，摩基还是会回报你所作的事情!希望巨魔也烧起来!', '嗯，灭火了?', '', '去祖达克找圣光据点的萨满长者莫奇。', '扑灭火焰', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12860, '采集数据', '你拼出来的那个圆盘……是空的！米米尔这个狡猾的鬼东西肯定把信息藏到了别的什么地方。去调查一下创世者的图书馆，看看里面有没有数据库之类的东西。$B$B或许这张圆盘就是干这个用的，到数据库附近去使用它看看吧。它可能就是用来读入和存储数据库信息的。试过以后再联络我，把你的发现告诉我。同时，我要开始着手寻找钥匙的另一半了。', '使用创世者的圆盘，从数据库中获得7条秘密数据。', '<布莱恩看着你握着的磁片。>$B$B我不知道里面到底有没有存东西!你得跟我说到底发生了什么事。$B$B<你解释了资料检索流程。>$B$B所以成功了?至少我们可以期待弥米尔做事很有规划。希望他跟其他那些我听到的守护者不一样……', '你有没有试着读磁盘？可有什么发现？', '', '使用布莱恩的通讯器联络布莱恩·铜须。$B$B如果你弄丢了联络器，你可以与冰霜堡的考古学家安多林重新要个新的。', '收集秘密数据', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12861, '巨魔疯啦！', '达库鲁……你知道他是谁吗？我觉得坏巨魔们被达库鲁控制了。他们称自己是达库鲁巨魔——所以我就知道了。现在你知道为什么我能成为怒爪氏族的头儿了吗？因为我是最最聪明的狼獾人！$B$B不过这跟我现在找你的原因没有关系。坏巨魔把怒爪氏族赶出了巢穴，没来得及逃走的怒爪狼獾人都被囚禁在村子里面了。你去东南方的怒爪巢穴解救被俘虏的怒爪狼獾人吧。钥匙就在巨魔身上，也许你需要干掉很多巨魔才能拿到足够多的钥匙。', '祖达克圣光据点的怒爪酋长希望你使用从达库鲁巨魔身上找到的达库鲁“开锁器”，解救8名被俘虏的怒爪狼獾人。', '怒爪感谢你，$N。虽然怒爪巢穴可能没办法回去，而且巨魔跟怒爪的关系再也不能变好…我还想到，怒鬃也回不来了。还有我那口儿的弟弟，它也走了。嗯，你有看过我老婆吗?我想它也走了。$B$B也许你可以走了。酋长很低落。', '你救出怒爪?', '', '去祖达克找圣光据点的怒爪酋长。', '解救被俘虏的怒爪狼獾人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12863, '表示感谢', '啊！感谢你来到这里，朋友。$B$B根据你慌张的眼神和颤抖的双手来判断，我想你是个新手吧。看来你应该先去拜访一下我们那些热情好客的东道主！$B$B我们有一些额外的医疗物资……说实话，我们从未预料到能找到如此安逸的营地。去把这箱医疗物资交给格罗萨吧，如果你愿意的话，也尽可能地去帮帮他们。我们可不希望被别人看成不懂得知恩图报的混球。', '将医疗物资箱交给冰霜堡的格罗萨·硬须。', '医疗补给?谢谢你!不是很确定要拿它们怎么办，但是想必会派上用场。$B$B很高兴见到你…你们的人可真是拥有丰富的多样性啊。这地方不太常有访客? 有些新伙伴的感觉挺不错的。', '哈罗。', '', '去风暴峭壁找冰霜堡的格罗萨·硬须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12865, '忠诚的伙伴', '新来的！很高兴认识你！如果你有时间的话，我想找你帮个忙。$B$B东边就是山底平原……环境非常恶劣的一片土地，不过有相当多的犀牛在那里生活。我们的猎鹰非常喜欢吃犀牛肉，不过平原上还有许多始祖龙，让它们去那里狩猎始终是件非常危险的事情。$B$B如果你愿意的话，不如去弄些犀牛肉回来，然后回到这里上面的峭壁，喂食居住在那里的猎鹰。', '冰霜堡的弗亚林·霜眉希望你收集8块新鲜的冰犀牛肉，然后将它们喂食给小镇上方的雷羽鹰。', '由衷地感谢你...我想他们一定也充满感激之情。他们是坚定而强大的盟友;若你在我们的阵营里，你会因为他们的协助大大受益。', '这些雄鹰已被我们驯化已久...一切进展得还不错。', '', '去风暴峭壁找冰霜堡的弗亚林·霜眉。', '喂食雷羽鹰', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12866, '震慑侵犯者', '该死的鹰身人，我已经记不得教训它们多少次了……每次被打得落花流水之后，它们总会消停一段时间。这次，我还以为它们已经得到足够的教训了。$B$B显然没有。$B$B它们的记忆力可能很差劲，不过如果它们的数量不足的话，我想它们自己也会收敛一些。到北面和东面的山谷里去，帮我们消灭一些鹰身人吧，怎么样？', '冰霜堡的格罗萨·硬须希望你去杀死8个霜羽尖啸者和8个霜羽女巫。', '这不是什么好工作，我懂，但是我们很感谢你的帮忙。你说斥候提到的那个名字是什么…西拉纳?', '顽强的畜生…好像永远都摆脱不了他们。他们繁殖的跟兔子一样快。', '', '去风暴峭壁找冰霜堡的格罗萨·硬须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12867, '偷宝宝的鹰身人', '几周前，只要你抬头仰望，就可以随时看到一群群漂亮的猎鹰在天空中翱翔。现在呢？就算有，也就只剩下那么几只了。由于鹰身人一直在偷取猎鹰的卵，它们只好整天守在巢里。$B$B鹰身人对鹰肉越来越感兴趣了，似乎……这群变态的家伙想把卵中的小鹰孵化出来，然后好好地美餐一顿。去把鹰卵夺回来交给我，我会负责把它们送回鸟巢里去的。', '冰霜堡的弗亚林·霜眉希望你交给他15枚雷羽鹰卵。', '做的好，$G小子:小女孩;。你迅速地结交了朋友。$B$B如果你过阵子回来，我想一定可以找到一只雄鹰愿意让你骑的…它们现在知道可以信任你了。', '我们会把这些鹰身人处理好的…这些老鹰很快就可以再度盘旋于天空中了。', '', '去风暴峭壁找冰霜堡的弗亚林·霜眉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12868, '希尔拉娜·冰啸', '似乎这个希尔拉娜·冰啸就是煽动鹰身人的幕后主使。如果我们干掉她，也许它们的进攻就会很快消停下来。$B$B我们的一位风暴骑士声称，发现她在西北方的峭壁附近徘徊。去把她找出来，消灭她。', '冰霜堡的格罗萨·硬须要求你去杀死希尔拉娜·冰啸。', '那么就解决了。谢谢你。$B$B我跟弗尤林.霜眉谈过了 - 他说他的手下会负责对付鹰身人。只要我们不放松防备，他们就没胆攻击我们的人。$B$B我知道这不是什么愉快的工作 - 请把这个当作是谢礼收下吧。', '这里太冷了，没有一般常见的害虫…幸亏我们还有鹰身人。真幸运。', '', '去风暴峭壁找冰霜堡的格罗萨·硬须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12869, '地盘之争', '你知道洛肯这个混账吧？铁矮人抓走了始祖龙的首领维拉努斯，搞得那些始祖龙极度沮丧……而且变得极具进攻性。$B$B它们开始闯入雷羽峰一带，而山上的雷羽鹰则倾巢而出，与它们交战。雷羽鹰一直对我们忠心耿耿，现在我们该报答这些朋友了。我们正准备转至山底平原，剿灭一些始祖幼龙。$B$B约尔格·雷心国王陛下将这柄战锤传给了我——要好好使用它，用完了还给我。', '弗亚林·霜眉要你骑上雷羽鹰转至山底平原，杀死16条风暴峭壁巨龙。', '我不认为这些元龙会这么轻易放弃。如果你还有时间帮忙的话，明天记得再回来。', '局面简直一发不可收拾。', '', '去风暴峭壁找冰霜堡的弗亚林·霜眉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12870, '远古的圣物', '嘿，你好啊！$B$B在你踏上一段惊心动魄的旅途之前，我可以提一个小小的请求吗？$B$B你知道，这一地区的山岭中散落着大量珍贵的圣物和古器……这里简直就是探险者协会梦寐以求的天堂。如果你能收集沿途发现的宝藏，并把它们带回来，我会非常感谢你的。我甚至会同意与你分享我的麦酒！相信我，$g小伙子:姑娘;，这笔交易是相当合算的！', '将10件奥杜尔的圣物交给冰霜堡的洛尔克·锐须。', '赞!你真是个好家伙。$B$B跟我一起干一杯吧!让我们庆祝这伟大的发现!', '你有替我找到圣物吗?', '', '去风暴峭壁找冰霜堡的洛尔克·锐须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12871, '探险者协会的帮助', '有意思。我没有在诺甘农之壳上发现任何锁定设备，也许仅仅是找到另一半钥石可能还不够。$B$B把诺甘农之壳交给冰霜堡的探险队长拉格努斯吧。只要他能克服自己对“泰坦造物”的敬畏之心，或许就能通过诺甘农之壳推测出它的核心部分应该是什么样子。没准他们还能说服冰霜矮人帮忙寻找它呢。$B$B我要去研究一下怎么把这两半东西拼合起来，等我们都有了进展之后再联络吧。', '将诺甘农之壳交给冰霜堡的拉格努斯。', '穆拉丁的胡子啊!这是我想的那个东西吗?布莱恩这次真的超越自我了…还有你也是!家乡那些孩子们一定不会相信的。', '你好啊!', '', '去风暴峭壁找冰霜堡的拉格努斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12872, '诺甘农之壳', '正在为创世者的圆盘充能。$B$B已完成充能。$B$B准备引导紧急协议：伽玛。$B$B紧急协议已加载。请使用已充能的圆盘激活诺甘农之壳的守护者，文件员麦卡顿。在确认了你的身份之后，文件员会交出诺甘农之壳。$B$B祝你愉快一千年。', '从文件员麦卡顿那里拿到诺甘农之壳。', '就是它了!这是诺甘农拱心石的一半。做的很好，$N.当我回到铁炉堡的时候，我要引荐你成为探险者协会的荣誉会员!', '好啦，别傻站在那，让我看看壳！', '', '使用布莱恩的通讯器联络布莱恩·铜须。$B$B如果你弄丢了联络器，你可以与冰霜堡的考古学家安多林重新要个新的。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12874, '霜脉矮人的热情', '我非常乐意为旅行者提供庇护所，但我不会强迫族人插手你们的事情。$B$B我跟你说啊……我的族人都是战士，性格非常直爽，而且很真诚。当一个霜脉矮人成长为男子汉的时候，他就必须通过战斗来证明自己。他必须向所有族人证明，他会在战场上勇往直前，毫不退缩。$B$B如果你能向我证明，你和我的族人一样强壮勇敢，那么我就允许他们帮助你。去和悬崖那边的弗亚林·霜眉谈一谈，他会为你安排试炼的。', '冰霜堡的约尔格·雷心要你去和弗亚林·霜眉谈一谈，从他那里获得一匹坐骑，并迎接挑战。', '哈!真是个波澜万丈的故事，$G小子:小女孩;…也许你体内流着一点霜脉矮人的血，嗯?你不是空口说白话，这就是我想听的。', '你回来了。你是凯旋而归的吗?', '', '去风暴峭壁找冰霜堡的约尔格·雷心。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12876, '不速之客', '我们的斥候在北边的山谷里发现了铁矮人。听说国王陛下让你去拜访德鲁姆，我有点担心他的安全。$B$B如果你在路上碰到铁矮人，能帮我干掉他们吗？我想他们还不知道我们的具体位置，以及抵达这里的路线，而我希望这种情况能继续保持下去。', '冰霜堡的弗亚林·霜眉要你杀死10个雷铸铁矮人入侵者。', '坏消息，$G小子:小女孩;。这些铁矮人似乎数量越来越多…整个山区都看的到他们的踪迹。我闻到战争来临的味道。$B$B谢谢你对付这些家伙…又替咱们争取了一点时间。', '斥候说的是正确的吗?下头有很多矮人吗?', '', '去风暴峭壁找冰霜堡的弗亚林·霜眉。', '杀死雷铸铁矮人入侵者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12877, '孤独的守护者', '我从来没找到过核心……但我经常和守护者克莱特乌斯谈话，他曾因为疏忽透露了一些信息给我。你可以在山底平原东部的山上找到克莱特乌斯，他一直在守护着造物者引擎。核心可能就在那里，但你必须获得克莱特乌斯的支持。$B$B铁矮人正在这一带寻找某些东西……可能就是在找核心。他们拿走了我的戒指，去找到他们的首领，拿回戒指。只要把戒指拿给克莱特乌斯看，他就会知道是我让你去的。', '从一个铁矮人监督者手中夺回德鲁姆·霜握的徽记之戒，并把它交给山底平原的克莱特乌斯。', '德洛的戒指?我想他没有亲自介绍你给我认识，他一定不是很平安。我很遗憾。德洛是一位高贵的矮人，虽然有些好问。$B$B那么，你是为了什么事情来的?', '哈罗，$r。我很高兴你选择用你的舌头，而不是武器来认识我。我觉得在你们的种族中，有这种美德的人越来越少，越来越少。', '', '去风暴峭壁找山底平原的克莱特乌斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12880, '探险大师', '组合钥石需要用到诺甘农的拼合器……这个设备就在造物者引擎里，也就是我们旁边这个大坑。布莱恩已经带着另一半钥石到下面去了，我已经把使用这个设备的方法都告诉了他。他正在等着你。$B$B我会尽量拖住那些铁矮人，但恐怕不能阻挡他们太久。约尔格·雷心国王很快就要带着他的一部分属下回去防守冰霜堡了，你要快一点，$r。', '将诺甘农之核交给造物者引擎里的布莱恩·铜须。', '你真是不得了啊，$G小子:小女孩;!干的漂亮!今天的确会是个光荣的日子。$B$B快点，在铁矮人来到这里之前赶快把核心交给我。', '嘿，你好啊，$G小子:小女孩;!很高兴能见到你本人。你找到了吗?', '', '去风暴峭壁找造物者引擎的布莱恩·铜须。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12882, '远古的圣物', '欢迎来到风暴峭壁。$B$B在你动身踏上伟大的冒险旅程之前，我有一个简单的请求。奥杜尔的古老圣物和宝藏散布在这一带的群山之中，似乎大部分都在各个智慧种族的手中。$B$B把你找到的圣物交给我，我会好好奖励你的。或许我还会和你分享最棒的麦酒呢。', '将10件奥杜尔的圣物交给格罗玛什坠毁点的奥鲁特·埃雷古。', '这些真是太棒了!我很感激你。向你的烦恼敬一杯如何?', '你有找到我说的圣物吗?', '', '去暴风峭壁找格罗玛什坠毁点的奥鲁特·埃雷古。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12883, '达库鲁的命令', '小的们，听从主人的号令！巫妖王派我来全权管理祖达克的天灾部队。我们要做的就是消灭一切。$B$B消灭一切！！！$B$B我们正在死亡旷野对所有的尸体进行处理，然后把它们派去泽尔拉玛斯的纳瓦留斯王子手下，加强天灾军团的实力。在达库鲁的管理下，什么都不会浪费的！$B$B很快我们就将变得前所未有的强大！不久之后，祖达克和古达克就将属于天灾军团！', '将达库鲁的命令交给祖达克圣光据点的北伐军领主兰迪加。', '要是这跟达克萨隆要塞的达库鲁是同一个的话，我们就会需要…支持。$B$B亚榭洛的死亡骑士就在附近驻扎，无疑地跟随着我们银色北伐军，都是跟随着天灾军的破坏痕迹而来。我们一半的军力都在银白看台跟疯狂的达卡莱巨魔奋战，我们得跟黑锋骑士团会合。$B$B<兰迪加低声地抱怨了几句。>我本来希望能不用再看到那些混蛋的，圣光在上呀。', '达库鲁，呃?我听过这个名字……', '', '去祖达克找圣光据点的北伐军领主兰迪加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12884, '黑锋哨站', '这里的西面，穿过荒废的道路和建筑之后，就是死亡骑士的营地——黑锋哨站。$B$B<北伐军领主兰迪加卷起达库鲁的命令。>$B$B把这些命令交给斯特凡·瓦杜，他是黑锋哨站死亡骑士的指挥官。告诉他，银色北伐军会对付纳瓦留斯王子，他们要做的就是解决达库鲁。$B$B对了，多加小心，$N。转至黑锋哨站的路上到处都是天灾军团。', '将达库鲁的命令交给祖达克黑锋哨站的斯特凡·瓦杜。', '<史戴芬读了信，将它撕成碎片，丢入火中。>$B$B老故事。银色北伐军，又一次，晚了一步。我们从灰熊丘陵就在注意达库鲁了。他已经在我们的死亡名单上了。', '你有什么东西要给我，$r?', '', '去祖达克找黑锋哨站的斯特凡·瓦杜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12886, '驭龙赛', '时机已经成熟。你通过了海德比武会的绝大多数试炼……如今只剩下最后一项。在过去的战斗中，你逐渐跻身最强大最凶残的女武士之列。$B$B最后的试炼即将开始——驭龙赛，海德比武会的价值与尚武精神的完美体现。我要你骑上幼龙，使用鱼叉击败所有竞争者。$B$B不要仁慈。没有谁会对你手下留情的。', '使用海德尼尔鱼叉，在风暴神殿击败10名海德比武会龙骑士。获胜后对装饰石柱使用海德尼尔鱼叉以完成驭龙赛，然后与托里姆谈一谈。', '希芙…是你吗?', '走开!', '', '去风暴峭壁找风暴神殿的托里姆。', '击败海德比武会龙骑士', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12887, '乐趣十足', '黑锋骑士团希望能够占领西北方的天灾基地——暗影拱顶。我在他们的组织里有一个线人，他需要我们的帮助。$B$B巫妖王利用一种被称为“魔眼”的设备监视着整个本地，魔眼就飘浮在拱顶的尖塔上。如果我们想要有所进展的话，就必须先把魔眼除掉。$B$B我们的矮人制造了一种可以对付它的东西。等那只眼睛被摧毁之后，去拱顶寻找斯利文男爵。他在那里假装继续为巫妖王效力。', '摧毁魔眼，然后向暗影拱顶的斯利文男爵报告。', '也许我们终于能做点什么了。不过不要被蒙蔽了，巫妖王还是能通过天灾军的爪牙“窥探”。$B$B那就是你来此的理由。', '窥探之眼依旧屹立不摇!寇尔提拉会相信你真是一件蠢事。$B$B不管你是谁，在毁掉眼睛之前不要再来找我。我在这里的身份一定要保密!', '', '去冰冠冰川找暗影拱顶的斯利文男爵。', '摧毁魔眼', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12888, 'E型检修员', '这张卡片可以让用户进入名为“E型检修员”的机器人的控制面板，对机器人进行维护或重新编写机器人的指令。$B$BE型检修员似乎被指派进入创世者的图书馆内部工作。这张卡片上列出了已损坏的部件和瘫痪的系统，只要有合适的零件，机器人就能恢复到正常的工作状态。', '将E型检修员控制卡、4份钴螺丝和5份过载电容器交给创世者的图书馆中的E型检修员。', '<你开始依照操作卡片上面的数据修复机器人。当修复完成时，你把操作面板关起来，把开关打开。>', '<你打开了废料E号的控制面板。>', '', '去风暴峭壁创世者的图书馆找E型检修员。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12891, '我有一计……', '在我为巫妖王——啊咳——效力的时候，我们经常使用一种“统治魔棒”控制一些比较聪明的天灾成员。$B$B我要你帮忙制作一根新的统治魔棒。$B$B你很幸运，所需的材料都在附近：一根教徒的魔棒、一根憎恶的弯钩、一条恶鬼的绳子，外加一些天灾精华。$B$B这应该不难，$c。', '暗影拱顶的斯利文男爵要求你去收集一根教徒的魔棒、一根憎恶的弯钩、一条恶鬼的绳子和5份天灾精华。', '快，把他们交给我，离开我的视线!$B$B权杖、钩子、绳子都不用再加工。不过组成之后，我还得附上精华的浓缩，这样我们还可以再进行下一步。$B$B看起来很组成很简单，功能却很特别!', '当你收集好我交代给你的材料，我就可以开始制作，加上一点我们所需的小小改造，就可以上工了。', '', '去冰冠冰川找暗影拱顶的斯利文男爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12892, '乐趣十足', '黑锋骑士团希望能够占领西北方的天灾基地——暗影拱顶。我在他们的组织里有一个线人，他需要我们的帮助。$B$B巫妖王利用一种被称为“魔眼”的设备监视着整个本地，魔眼就飘浮在拱顶的尖塔上。如果我们想要有所进展的话，就必须先把魔眼除掉。$B$B我们的地精制造了一种可以对付它的东西。等那只眼睛被摧毁之后，去拱顶寻找斯利文男爵。他在那里假装继续为巫妖王效力。', '摧毁魔眼，然后向暗影拱顶的斯利文男爵报告。', '也许我们终于能做点什么了。不过不要被蒙蔽了，巫妖王还是能通过天灾军的爪牙“窥探”。$B$B那就是你来此的理由。', '窥探之眼依旧屹立不摇!寇尔提拉会相信你真是一件蠢事。$B$B不管你是谁，在毁掉眼睛之前不要再来找我。我在这里的身份一定要保密!', '', '去冰冠冰川找暗影拱顶的斯利文男爵。', '摧毁魔眼', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12893, '解放你的思想', '如果劣尸维尔、奈丝伍德夫人和跳线者可以摆脱巫妖王的控制，就将成为我们对抗巫妖王的得力助手。这就是统治魔棒的用途所在了。$B$B你可以在拱顶东面和西面的平台上，以及我们上方的拱顶中层找到它们。在它们的尸体上使用统治魔棒就行了。$B$B出发吧，这些天灾军团的成员很快就是我们的人了！', '暗影拱顶的斯利文男爵希望你在劣尸维尔、奈丝伍德夫人和跳线者的尸体上使用统治魔棒。', '当我们拿下墓穴以后，我们会好好的利用他们三个的。$B$B讲到这个……', '你还没去找他们。别污辱我的智商，$C!', '', '去冰冠冰川找暗影拱顶的斯利文男爵。', '转化劣尸维尔', '转化奈丝伍德夫人', '转化跳跃者', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12895, '失踪的布莱恩·铜须', '在动身出发之前，我曾经收到斥候沃塔肯翻译整理的有关布莱恩·铜须的文件。从布莱恩的日记和灰熊丘陵的发现来看，布莱恩肯定已经动身转至风暴峭壁了。在我们坠机之前，我发现在这里南边的山底平原对面有个露营地，俯瞰着冻结的伯尔之息河。$B$B如果布莱恩不在那里的话，就在营地一带找找，看那个该死的矮人有没有留下什么线索。如果你找到任何线索的话，把它带回来给我。', '在布莱恩的营地中找到用麻布裹起来的便笺，把它交给格罗玛什坠毁点的伯克塔·血怒。', '当然，以我们的运气来说，我早就预料到了。嗯，我们不会让他这么简单地就跑走。让我们看看信笺上写些什么。', '你有幸运地在铜须的营地找到什么吗?', '', '去风暴峭壁找格罗玛什坠毁点的伯克塔·血怒。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12896, '顽固的敌人', '除非是最特别的情况下，像莱斯班恩将军这样强大的死亡骑士，都被巫妖王紧紧地控制着，根本不能转化。$B$B莱斯班恩将军在拱顶内部监督着新武器的制作流程。我向你保证，只要弄乱北部熔炉那里的武器架，他一定会冲过来的。我会派劣尸维尔、奈丝伍德夫人和跳线者去帮助你。$B$B如果我们想得到暗影拱顶，就必须干掉莱斯班恩将军！', '击败莱斯班恩将军，然后向联盟飞行战舰上的萨萨里安报捷。', '光祸将军和他的部队都被击败了?暗影穹殿已经陷落了?', '我问你，$N，如果光祸将军还活着，为什么我们要交谈呢?', '', '去冰冠冰川找破天号的萨萨里安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12900, '制造挽具', '这么说你想骑熊咯？好吧，既然你已经到了这一步，那么你肯定得去海德比武会试一试了。$B$B先做重要的事，我们要给你制作一副挽具。$B$B你可以在南面的峭壁上找到三五成群的雪人。它们的毛皮非常坚韧，而且厚度也正合适。帮我拿些毛皮回来，我们开始朝着让你骑上熊的目标努力吧。', '布伦希尔达村的艾丝崔·约利塔尔希望你交给她3张冰鬃雪人的毛皮。', '这些毛皮很不错。我立刻就会为你准备好鞍座。', '你找到毛皮了没?你可以在下方的山丘找到雪人。', '', '去风暴峭壁找布伦希尔达村的艾丝崔·约利塔尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12901, '从无到有', '我们一定要阻止纳瓦留斯王子。不能让天灾继续把这个地方当作他们的僵尸制造场。如果我们能让坦克运转起来的话，也许还有机会。现在，我需要一些配件来修补坦克。$B$B在这里的西北方，有个被称为塞穆之末的地方，天灾军团把那里当作基地。基地周围散布着它们到来之后留下的废料，零碎的天灾金属被扔得到处都是。帮我拿些天灾金属废料回来，我会让它们物尽其用的。', '北伐军前线营地的工程师里德要求你收集10块天灾金属废料。', '这个垃圾到底是什么!啊，全都去死吧!这没有用。天灾金属没办法利用。我们到底该怎么办?', '我真的不知道这个计画行不行的通，$N。你把金属碎块带来，然后我尽我所能。', '', '去祖达克找北伐军前线营地的工程师里德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12904, '圣光不能为我复仇', '他们……他们杀死了我的兄弟。$B$B<戈尔克强忍着泪水。>$B$B他们……他们就像宰杀动物一样把他杀死了。现在他们还把我的兄弟放在营地另一端的石板上，准备进行实验。达加斯也死了。这位圣骑士在东北方的废墟中英勇抵抗，但瓦古维库人的首领奥贾尔实在是太强大了。$B$B我是唯一的幸存者，但我也支撑不了多久了。我……我快要不行了。$B$B如果圣光不能为我复仇，或许你可以，$c。把他们全部消灭。', '塞穆之末的戈尔克希望你去消灭15个瓦古维库人。', '<介尔克垂死。>$B$B他…他们说这些瓦苟是…是巫妖王觉得没用的家伙们。你…你能想…想象吗?想想…想想那些有…用的家伙会有多强……$B$B我会在彼世为你祈祷，英雄…愿你永远也不会被他们围攻。', '你是在帮这世界的忙，朋友。一定得阻止这些怪物!', '', '去祖达克找塞穆之末的戈尔克。', '杀死瓦古维库人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12906, '训诫', '我就直接了当地说吧。在矿洞里为我们工作的男性维库人都不是心甘情愿的……他们只是暂时屈服而已。$B$B每隔一段时间，他们中总是会有几个人失去动力。找到那些不合作的维库人，用这根训诫之杖好好吓唬一下他们。$B$B他们也该清醒清醒了。', '荒弃矿洞中的残酷的米尔德蕾要求你使用训诫之杖威吓6个筋疲力尽的维库人。', '对一个新任监督者来说还算不错了。如果你还有足够的勇气，我还有另一项任务要给你。', '完成了吗?我希望你没有杀掉太多维库杂种。我们还需要人手。', '', '去风暴峭壁的荒弃矿洞找残酷的米尔德蕾。', '训诫筋疲力尽的维库人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12907, '杀一儆百', '任何事情都会有两面性，我的姐妹。维库人已经不能再忍受高压了，他们逐渐开始有了反抗的念头。$B$B带头的家伙名叫加哈尔。为了进一步证明你的忠诚，去把他干掉……记得一定要当众下手，好好警告一下那些维库人。', '荒弃矿洞内的残酷的米尔德蕾命令你去处死加哈尔。', '假使你刚来的时候我对你的能力有任何存疑之处，现在都烟消云散了。只要再努力一点，你就能够成为我的永久队员。', '你回来了。你有没有杀死那头不听话的猪?', '', '去风暴峭壁的荒弃矿洞找残酷的米尔德蕾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12908, '特殊的囚犯', '你真是心狠手辣啊，不错，我相信你会表现得非常好。$B$B我还有一个任务要交给你。有一个女性维库人囚犯越来越让我不能容忍了。$B$B她竟敢宣称要有参加海德比武会的权利，那可是我们最神圣的格斗比赛！$B$B这是打开她枷锁的钥匙。下手快一点，让她少吃点苦。尽管她不是我们的人，但她毕竟是个女性。', '把米尔德蕾的钥匙交给荒弃矿洞的女巫洛莉拉。', '我就知道你会回来!快把这些镣铐弄掉，我就会帮你找到那个哥布尔。', '时间也差不多了。', '', '去风暴峭壁找雪盲台地的女巫洛莉拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12910, '跟踪罪犯', '好吧，我答应伯克塔的请求，但是我希望他能做出补偿。别用那种眼神看我。我承认，这里是伯克塔说了算，但是谁也不能对猎人随随便便指手画脚。$B$B他总是对我咆哮，“把那头野兽牵走！”“让它别再叫了！”$B$B你瞧，现在他想起我的小豹子了，这家伙真会见风使舵啊。下次他再敢嘀咕，我就让霜齿扑上去咬他一口。别担心，它会帮助你完成这项跟踪任务的。气味的源头可能是铁矮人，布莱恩，或者是别的生物。总之等它找到目标之后，接下来的事就要靠你自己去解决了。', '骑上霜齿，让它带你寻找布莱恩的便笺上的气味的源头。然后找到布莱恩的通讯器，使用它与布莱恩·铜须取得联系。', '当你引导了通讯器之后，一个矮人的影像浮现出来。他一定就是布莱恩.铜须。>$B$B<从他脸上的表情看来，布莱恩看到你似乎很震惊，然后他开始狂乱的比划手势。>', '你…你是谁?', '', '使用布莱恩的通讯器联络布莱恩·铜须。', '追踪气味的源头', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12914, '拯救盖米尔', '你说他被锁在了一只100尺高的笼子里？$B$B如果我的计算无误的话，我们至少应该能让笼子的转轴变得不那么坚固，这样巨人就可以逃出来了。$B$B如果想要实施这个计划，我就需要一些增塑剂和稳定剂。$B$B女妖精华应该是很好的增塑剂，你可以到东北边的死亡旷野去，从那里的女妖身上得到它们。西南方黑锋哨站附近的大地狂怒者身上有我要的稳定剂。$B$B开始行动吧！', '北伐军前线营地的工程师里德希望你交给他6份女妖精华和6份硅藻土。', '幸亏我们并不缺炸药。有了你带来的材料要组装出超超超大爆盐炸药就很简单。', '没有塑化剂与稳定剂的话我永远不能做出能够破坏囚牢的炸药。', '', '去祖达克找北伐军前线营地的工程师里德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12915, '弥补关系', '如果要从我兄弟手中夺到造物者圣台的控制权，我就必须先想办法修复与旧日盟友之间的关系。$b$b或许我与冰霜巨人可以通过对抗共同的敌人，开始着手恢复彼此的友谊。$b$b弗约恩正在率领铁巨人围攻丹尼芬雷。你必须在东边的弗约恩之砧击败他，并痛击他的部队，帮助霍迪尔之子赢得胜利。$b$b带上这枚符咒吧，$n。你可以用它召唤我的土灵助阵。', '风暴神殿的托里姆要你转至丹尼芬雷东边的弗约恩之砧，杀死弗约恩和5名雷铸铁巨人。$b$b你可以使用托里姆的大地符咒召唤他的土灵助战。必须借助弗约恩之砧附近的花岗岩石块才能使用这枚符咒。', '所以，你已经完成了任务。$B$B希望这样足够了。', '弗约恩还活着吗，$C?', '', '去风暴峭壁找风暴神殿的托里姆。', '杀死弗约恩', '杀死雷铸铁巨人', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12916, '唯一的希望', '我要给你的东西被称为爆盐炸弹，它是使用特殊材料制成的强力炸药。由于它的可塑性，你可以把它塞进牢笼的转轴结合处，以寻求最大的爆炸威力。$B$B去你朋友那里，用这枚巨型爆盐炸弹把他救出来吧。$B$B希望他是个守信的家伙。他是我们唯一的希望了。', '在祖达克的塞穆之末使用巨型爆盐炸弹，打开囚禁着盖米尔的天灾围栏，然后与盖米尔谈一谈。', '自由!$B$B不要害怕，小家伙。盖米尔是值得敬重的巨人。就像你与你的人民一样，我也希望看到天灾军团被逐出这块土地，也希望看到巫妖王被消灭。我会尽我所能地帮助你，就像我答应过你的一样。', '我是个信守诺言的巨人，小家伙。', '', '去祖达克找塞穆之末的盖米尔。', '炸毁天灾围栏', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12917, '寒风的声音', '如果不是运气够好的话，我们恐怕不能这么轻易地找到布莱恩。如果我们能知道布莱恩在说些什么，你就能劝他说出自己的位置了。$B$B附近群山中的风力很强，这对我们而言是件好事。一个知识渊博的萨满祭司可以通过风的声音理解全世界所有的语言。$B$B我要你到西北方的雪流平原去，寻找由风构成的生物——风暴骑士。去捕捉它们的声音，把那声音带回来给我。', '将5份寒风之声交给格罗玛什坠毁点的莫塔哈·风魂。', '现在你应该能与矮人沟通了。问问博克塔对你有什么要求。没什么时间可浪费了。', '你把风的声音带来了吗?', '', '去风暴峭壁找格罗玛什坠毁点的莫塔哈·风魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12918, '完美宝石', '看来刺骨的寒风已经吹到这里来了？现在不仅仅是缺少欣赏我手艺的顾客，而且我也没有库存的宝石可以出售了！如果你能弄些未切割的宝石来补充我的库存，我可以教你切割完美宝石的技术。切割完美宝石能让你在切割诺森德地区出产的优秀质量宝石时，有机会切割出一颗具有更高属性的完美宝石。', '将茶晶石、黑玉和暗影水晶各两颗交给瓦加德的恩霍罗。', '这些用来补充我的货架\r\n再适合不过了。我不只要教你宝石完美工法，我也会帮你把这些宝石的其中一颗切成完美宝石当作对你的回报。', '你真大方。我会教你宝石完美工法作为回报的。', '', '去嚎风峡湾找瓦加德的恩霍罗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12919, '风暴之王的复仇', '我的人民受到了巫妖王的屠杀。天灾军团正在使用风暴巨人的尸体制造血肉巨人，或者是把它们缝合成像塞穆那样的怪物。$B$B为了将它们完全消灭，我一定会竭尽全力。让我们携手剿灭那些威胁祖达克的天灾亡灵。$B$B不管是纳瓦留斯、奥贾尔还是塞穆，都要消灭掉！$B$B等你准备好之后就告诉我，让我们开始这趟破坏之旅吧。', '与盖米尔交谈以开始行动。$B$B骑着盖米尔去消灭100个天灾士兵，并消灭天选者奥贾尔、塞穆和纳瓦留斯王子。成功之后，向北伐军前线营地的北伐军战士马克拉尔报告。', '难以置信!这会是个流传百年的故事，$N!一个$g男人:女人;骑在风暴巨人之王的头上，将整个天灾军队铲平!$B$B而我就在旁边旁观了一切……', '怎么样了?我们的敌人全死了吗?', '', '去祖达克找北伐军前线营地的北伐军战士马克拉尔。', '杀死天灾士兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12920, '联络布莱恩', '你还在等什么？多亏了莫塔哈的帮助，语言障碍已经解决了。去联络布莱恩·铜须吧，找出他的藏身之所，问问他究竟在跟踪什么。$B$B或许我们还能在这场灾难中挽救一点什么。', '使用布莱恩的通讯器与布莱恩·铜须联络并与他交谈，然后与格罗玛什坠毁的伯克塔·血怒谈一谈。$B$B如果你遗失了布莱恩的通讯器，可以找格罗玛什坠毁点的莫塔哈·风魂再要一个。', '<博克塔聆听你描述和布莱恩的对话。>$B$B矮人说的是真的。沃塔克的计画不是部落的手法。如果布莱恩.铜须知道阻止铁矮人和他们幕后黑手的方法，帮助他对我们来说也很有利。', '你发现了什么?', '', '去风暴峭壁找格罗玛什坠毁点的伯克塔·血怒。', '与布莱恩谈一谈', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12922, '精炼之火', '这块表面布满孔隙的金属散发出神秘的光芒。$b$b你觉得应该把它放在弗约恩之砧上进行高温处理，除去矿石中的杂质。$b$b正当你思考这片冰原上有什么东西的温度高到足以胜任这项任务时，一只火焰亡魂从你面前飘过……', '从霜原湖的火热的亡魂身上收集10份狂怒火花，然后转至弗约恩之砧，使用那里的铁砧。', '你把金属放在铁钻上，当你一把火花加进去，立刻猛烈的与矿石作用。$B$B当它们终于烧完了以后，你带着一大块发着光芒的金属离开。', '铁钻的表面十分灼热，与周遭寒冷的空气形成强烈对比。', '', '去风暴峭壁找丹尼芬雷的弗约恩之砧。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12925, '维持传统', '巫妖王已经派密使来找过我们三次了，每次都被我们当场拒绝。$B$B但是瓦基里安的那些姐妹们却不那么忠于传统，她们接受了巫妖王的诱惑。现在，她们不再从野外捕捉幼龙，转而用瘟疫和天灾军团的邪恶力量培育龙卵。$B$B从瓦基里安的海德尼尔人身上夺取冰霜油膏，把那些已经感染了瘟疫的龙卵冻僵。据说那些龙卵都放在一个发臭的瘟疫池塘里。', '布伦希尔达村的塞拉·克文沙尔要你转至瓦基里安，从瓦基里安候选者身上夺取冰霜油膏，并用冰霜油膏摧毁30枚瘟疫始祖龙卵。', '我们感谢你，姊妹。我们不能让英勇的传统遭受腐化。', '你摧毁那些染疫的蛋了没?', '', '去风暴峭壁找布伦希尔达村的塞拉·克文沙尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12926, '拼图游戏', '我们发现铁矮人和他们控制的构造体正在与某种石头生物及其巨人盟友作战。布莱恩将这种石头生物称为土灵。我希望你能联络一下布莱恩，尽可能地帮助他。记住，他的调查结果或许能帮助我们击败铁矮人和他们的主子。', '使用布莱恩的通讯器联络布莱恩·铜须，并了解下一步的行动计划。', '动作真快!现在我们有了圆盘，该找出如何用它来解开文件库钥匙的前半部了。', '你完成圆盘了吗?', '', '使用布莱恩的通讯器联络布莱恩·铜须。$B$B如果你弄丢了联络器，你可以与格罗玛什坠毁点的莫塔哈·风魂重新要个新的。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12927, '采集数据', '你拼出来的那个圆盘……是空的！建造这个图书馆的守护者米米尔肯定把信息藏到了别的什么地方。去调查一下创世者的图书馆，看看里面有没有数据库之类的东西。$B$B或许这张圆盘就是干这个用的，到数据库附近去使用它看看吧。它可能就是用来读入和存储数据库信息的。试过以后再联络我，把你的发现告诉我。同时，我要开始着手寻找钥匙的另一半了。', '使用创世者的圆盘，从数据库中获得7条秘密数据。', '<当你举起圆盘的时候布莱恩看着它。>$B$B我看不出来里面有没有储存东西，$g小子:小女孩;。你得告诉我发生了什么事。$B$B<你描述了下载的过程。>$B$B所以说它有用啰?至少我们可以指望守护者弥米尔做事很有系统。', 'NULL', '', '使用布莱恩的通讯器联络布莱恩·铜须。$B$B如果你弄丢了联络器，你可以与格罗玛什坠毁点的莫塔哈·风魂重新要个新的。', '收集秘密数据', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12928, '诺甘农之壳', '正在为创世者的圆盘充能。$B$B已完成充能。$B$B准备引导紧急协议：伽玛。$B$B紧急协议已加载。请使用已充能的圆盘激活诺甘农之壳的守护者，文件员麦卡顿。在确认了你的身份之后，文件员会交出诺甘农之壳。$B$B祝你愉快一千年。', '从文件员麦卡顿那里拿到诺甘农之壳。', '就是它!这就是诺甘农拱心石的前半部。做的好，$N.我叫探险者协会的成员寻找外壳所在地的线索已经很久了。如果我告诉他们是个勇敢的$r替我找到它的，他们一定不会相信我。', 'NULL', '', '使用布莱恩的通讯器联络布莱恩·铜须。$B$B如果你弄丢了联络器，你可以与格罗玛什坠毁点的莫塔哈·风魂重新要个新的。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12930, '稀有的土壤', '一直以来，这些锤子只被用来敲击石头，而不是敲击铁矮人。被驱逐出奥杜尔之后，我们亲眼目睹了柔弱的伙伴一个个地死去，而我们最强壮的工匠作为战士重生。$B$B当铁矮人逼得我们节节败退时，即使最强壮的战士也无力回天。$B$B我们对伤者毫无办法，除非能有一些魔化土壤的储备。我们以前一直都是在西北方的峭壁表面上采集它们，但持续不断的战争让我们根本没有机会补充储备。你能帮助我们吗？', '使用土灵采矿锄收集7块魔化土壤。将这些土壤和5张霜纹布交给布德克拉格庇护所的塑石者布德克拉格。', '这样我们就能够修补更多倒下的人了。谢谢你，$N，我代表所有防卫避难所的人感谢你。', '你有找到土壤吗?', '', '去风暴峭壁找布德克拉格庇护所的塑石者布德克拉格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12931, '反击', '庇护所的卫兵已经尽了最大的努力来抵挡铁矮人的攻击，但是我们仍然在节节败退。我的部下非常勇敢，但他们并非不知疲倦。如果没有增援的话，我们全面溃败恐怕只是个时间问题而已。$B$B你愿意帮我们保卫庇护所吗？这样可以会大大提升卫兵的士气，并给他们——还有我——带来发动反击的希望。$B$B消灭庇护所外面的铁矮人，以及他们的创造物。', '塑石者布德克拉格希望你杀死总计10名雷铸袭击者或雷铸掠夺者，然后返回布德克拉格庇护所向他复命。', '你带来了令防御者欢欣鼓舞的消息。看到敌人被手刃使他们再度振作起来，也激励了他们的勇气。', '战况如何?', '', '去风暴峭壁找布德克拉格庇护所的塑石者布德克拉格。', '杀死雷铸攻击者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12937, '救死扶伤', '庇护所的卫兵非常勇敢，但他们也抵挡不住铁矮人无休止的冲击。$B$B有了你找来的土壤，我可以制造绷带来治疗受伤的卫兵。被我们救治的卫兵越多，我们所能坚持的时间就越久。$b$b拿上这些药膏，用它们去治疗庇护所外面受伤的卫兵，尽可能多救几个人回来，$N。每一个卫兵的伤亡都是我们的重大损失。', '使用土质药膏治疗8名倒下的土灵防御者，然后返回布德克拉格庇护所，向塑石者布德克拉格复命。', '你所治愈的战士将能帮我们把防线支撑更久一点。如果我们真的要完全摆脱铁矮人的威胁，我们就得想个方法越过战线打击他们。', '你救治了倒下的防卫者吗?', '', '去风暴峭壁找布德克拉格庇护所的塑石者布德克拉格。', '救治倒下的土灵防御者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12939, '荣耀的挑战', '首先，我们要转至尤顿海姆城中一个被称为野蛮之台的地方，就在西边的山上。$B$B维库人战士总是在那里练习格斗技巧，在他们领主的亲信们的指导下不断精进。$B$B我要你带着这面旗帜去向他们挑战，用$r的“小把戏”去挫一挫他们的锐气，如何？$B$B<公爵咧嘴一笑，他那腐烂的牙齿在昏暗的光线中闪闪发光。>', '暗影拱顶的兰克拉尔公爵要你使用挑战之旗向6名尤尔丁格斗者发起挑战，并击败他们。', '关于你在蛮荒岩台所展现的力量，我已经听到报告了。做的好，$N…做的好!$B$B<公爵再度咧嘴，而你几乎可以听见他脑中的齿轮运转声。>$B$B现在，我想是时候制裁你打败的那些维库人的族长了。', '也许你可以回去再多挑战几个人?', '', '去冰冠冰川找暗影拱顶的兰克拉尔公爵。', '挑战并击败尤尔丁格斗者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12942, '黑暗的羽翼', '叛徒。我们海德尼尔人绝对不会怜悯这种渣滓。$B$B瓦基里安的那帮家伙已经逍遥法外太久了。我们依然忠于托里姆，而她们却成了巫妖王的走狗！$B$B她们把那些接受了巫妖王恩典的人称为“瓦格里”。她们长着羽翼，就像鹰身人一样。$B$B瓦基里安就在遥远的西北方，比风暴神殿更遥远的地方。去杀死那些长着翅膀的母狼吧，姐妹。杀了她们，我会奖励你一件我最珍贵的宝物。', '布伦希尔达村的复仇者伊芬要你去瓦基里安杀死12个初生的瓦格里。', '华尔琪不过是巫妖王的走狗。我们会像杀死野狗一样地杀死她们。她们自己做出了决定，现在就要自己承担后果。', '你有没有好好惩罚我们偏离正道的同胞?', '', '去风暴峭壁找布伦希尔达村的复仇者伊芬。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12943, '暗影拱顶裁决令', '强大的乌弗朗领主就坐在野蛮之台旁边的大厅里。我研究过他的数据，这是一个极具耐心和战略头脑的维库人。他喜欢等待时机速战速决，不喜欢搞持久战斗。$B$B我要除掉他！$B$B我已经写好了他的裁决令，去当着他的面大声宣读吧。$B$B<公爵开心地扬起了眉毛。>$B$B至少……这样可以让他失去勇气。', '暗影拱顶的兰克拉尔公爵命令你向强大的乌弗朗领主宣读暗影拱顶裁决令，然后杀死他。', '<兰克洛公爵对你的报告点头表示满意。>$B$B我们面对的对手远比我们壮大，不只是在身材上，在数量上也是如此。如果我们在冰冠冰川的战斗想要获胜的话，我们就得想的比他们多!$B$B现在乌弗兰死了，我们对卓顿海姆的进攻就有了优势。让我们看看是否能好好利用它。', '我的斥候告诉我乌弗兰还活着。$B$B你不识字吗，$r?', '', '去冰冠冰川找暗影拱顶的兰克拉尔公爵。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12949, '夺取钥匙', '$C，解开这副枷锁的钥匙就挂在教官霍加尔的脖子上，他就在外面。$B$B你能去把钥匙拿过来给我吗？', '乌弗朗之厅里面的被折磨的维林要求你去夺取维林的锁链钥匙。', '谢谢你，$r。把钥匙给我吧，我会自己打开它。', '你拿到了吗?', '', '去冰冠冰川找暗影拱顶的被折磨的维林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12952, '完美宝石', '在这个鸟不生蛋的地方，我的手艺都会被荒废的。我花了很多年来学习怎么把宝石切割成完美的形态，现在却英雄无用武之地！你看上去就像是能帮我找些宝石来的那类人，如果你愿意帮忙的话，我可以教你切割完美宝石的技术。切割完美宝石能让你在切割诺森德地区出产的优秀质量宝石时，有机会切割出一颗具有更高属性的完美宝石。', '将茶晶石、黑玉和暗影水晶各两颗交给复仇港的卡特尔·迪芬斯。', '这些一定可以。我会教你宝石切割的完美技艺，同时为了证明我的技巧，我也会给你一颗完美的宝石。', '这些就可以了。我可以教你宝石完美工法作为回报。', '', '去嚎风峡湾找复仇港的卡特尔·迪芬斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12953, '燃烧吧，瓦基里安', '箱子里都是纵火用的鱼叉，你想起了外面的那些鱼叉炮和干草垛。$B$B也许伊芬会感谢你的额外贡献，并好好地奖励你。', '用瓦基里安鱼叉炮点燃6堆干草垛。', '这才叫献身嘛!那些叛徒现在也许有了个新主人，但是他们永远不会忘记姊妹们送的临别礼物!', '嗯?', '', '去风暴峭壁找布伦希尔达村的复仇者伊芬。', '点火', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12954, '痛苦斗兽场：伊戈达斯！', '我一直在想，你要等到什么时候才会出现呢，$N！鲜血之环的前冠军在这里出场，是一件多么吸引人的事情啊！我们会发财的，伙计！发大财！$B$B不过，祖达克这个烂地方，所有的冰巨魔似乎都把这里当作厕所一样搞得一团糟。他们简直是疯了！不过，谁会关心这个呢，对吧？我们是来这里赚钱的！$B$B来，先热热身，$N。等你准备好了之后就告诉我，好戏就要上演啦！', '进入痛苦斗兽场，击败伊戈达斯！回到巨魔仆从伍迪那里领取你的奖励。', '嘿!我认识你。人们讨论你在血色竞技场的胜利讨论了好几个月!因为没有出场打卫冕赛而输掉你的勇士头衔真是太可惜了!来的快，去的也快，嗯?至少你还活着。', '没打完没有奖赏，$g老兄:女士;。', '击败伊戈达斯', '去祖达克找痛苦斗兽场的巨魔仆从伍迪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12955, '消灭竞争者', '咕啦呜哇……$B$B<跳线者清了清喉咙。>$B$B很抱歉，有时候别人很难听懂我在说什么，你知道是怎么回事啦。$B$B我要说的是，如果你打算转至西边山上的野蛮之台，请你顺便除掉那里的几个对手。$B$B准确地说，我想要你在维库人面前挑战齐格莉德·冰魂、虔诚者埃弗雷姆、奥努森和丁奇·火哨，并把他们打得落花流水。', '暗影拱顶的跳线者要求你与齐格莉德·冰魂、虔诚者埃弗雷姆、奥努森和丁奇·火哨决斗，并击败他们。', '这可是重要的紧，$N。只要把他们给赶跑，当你在那里执行我们给你的任务时就不会受到他们干扰。', '你为什么在这里?$B$B快去羞辱他们!', '', '去冰冠冰川找暗影拱顶的跳线者。', '击败齐格莉德·冰魂', '击败虔诚者埃弗雷姆', '击败奥努森', '击败丁奇·火哨');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12956, '希望的火花', '显然，这不是一块普通的金属。$b$b这块矿石与你见过的任何一种都不同，它的质地非常坚硬，但并不易碎，分量也比看上去要轻得多，即使冷却下来也会放出光芒。$b$b靠近观察时，你发现金属的表面下有一枚托里姆的符文在闪烁……', '将精炼闪光矿石交给风暴神殿的托里姆。', '当你将矿石拿出来的时候，你注意到托里姆严肃的表情因为认出它而笑颜逐开。', '你手上拿着什么，小家伙?', '', '去风暴峭壁找风暴神殿的托里姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12957, '雷铸铁矮人的奴隶', '在这里的西南方，雪流平原的西面，铁矮人在山坡上掘出了一个矿洞。在那里，它们利用米米尔的仆从——被俘虏的机械侏儒来采集矿石。$B$B我不知道这些机械侏儒是哪来的，也不知道解救它们之后会怎么样，但或许它们愿意帮助我们呢？$B$B到冰霜矿洞去，$N，让这些机械侏儒恢复自由。问问它们是否愿意站在我们这边，对抗铁矮人的暴行。', '布德克拉格庇护所的塑石者布德克拉格希望你去解救6名机械侏儒俘虏，并杀死3名雷铸工头。', '我本来希望有更多奴隶加入我们的，但我不会责怪他们。自愿加入的盟友很少，而且彼此相差甚远，我们很感激你愿意为了我们而挥剑。', '你解救了雷铸的奴隶没?', '', '去风暴峭壁找布德克拉格庇护所的塑石者布德克拉格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12958, '货单：血玉护符', '我收到了一张可以给我带来丰厚利润的订单，上面明确要求订购一批血玉护符，以便在安德麦高价兜售。如果你能帮我制作一件的话，我可以奖励你一枚达拉然珠宝匠硬币。', '使用1枚维库护身符、1颗黑玉和1颗血石制造出一件血玉护符，把它交给达拉然的提莫斯·琼斯。$B$B你可以在诺森德的任意维库人身上找到维库护身符。', '这是我答应要给你的达拉然珠宝匠徽章。明天再来找我，我会需要你再帮我找点什么的!', '你有带血玉护符，好让我交付幽坑城的订单吗?', '', '去达拉然找卡蒂亚珠宝店的提莫斯·琼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12959, '货单：炽热鹿牙雕像', '我收到了一张可以给我带来丰厚利润的订单，上面明确要求订购一批炽热鹿牙雕像，以便在安德麦高价兜售。如果你能帮我制作一件的话，我可以奖励你一枚达拉然珠宝匠硬币。', '使用1根诺森德鹿牙、1颗玉髓石和1颗暗影水晶制造出一件炽热鹿牙雕像，把它交给达拉然的提莫斯·琼斯。$B$B你可以在诺森德的任意种类的铲齿鹿或猛犸身上找到这种东西。', '这是我答应要给你的达拉然珠宝匠徽章。明天再来找我，我会需要你再帮我找些什么来的!', '你有带来发光象牙刻像，好让我完成幽坑城的订单吗?', '', '去达拉然找卡蒂亚珠宝店的提莫斯·琼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12960, '货单：邪恶太阳胸针', '我收到了一张可以给我带来丰厚利润的订单，上面明确要求订购一批邪恶太阳胸针，以便在安德麦高价兜售。如果你能帮我制作一件的话，我可以奖励你一枚达拉然珠宝匠硬币。', '使用1枚铁矮人胸针、1颗茶晶石和1颗太阳水晶制造出一件邪恶太阳胸针，把它交给达拉然的提莫斯·琼斯。$B$B你可以在诺森德的任意铁矮人身上找到铁矮人胸针。', '这是我答应要给你的达拉然珠宝匠徽章。明天再来找我，我会需要你再帮我带点什么来的!', '你有带来邪恶烈日胸针，好让我交付幽坑城的订单吗?', '', '去达拉然找卡蒂亚珠宝店的提莫斯·琼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12961, '货单：精致龙骨雕像', '我收到了一张可以给我带来丰厚利润的订单，上面明确要求订购一批精致龙骨雕像，以便在安德麦高价兜售。如果你能帮我制作一件的话，我可以奖励你一枚达拉然珠宝匠硬币。', '使用1根始祖龙骨、1颗太阳水晶和1颗黑玉制造出一件精致龙骨雕像，把它交给达拉然的提莫斯·琼斯。$B$B你可以在诺森德的任意始祖龙身上找到始祖龙骨。', '这是我答应要给你的达拉然珠宝匠徽章。明天再来找我，我会需要你再帮我找点什么的!', '你有带来错综龙骨刻像，好让我完成幽坑城的订单吗?', '', '去达拉然找卡蒂亚珠宝店的提莫斯·琼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12962, '货单：光芒护甲圣物', '我收到了一张可以给我带来丰厚利润的订单，上面明确要求订购一批光芒护甲圣物，以便在安德麦高价兜售。如果你能帮我制作一件的话，我可以奖励你一枚达拉然珠宝匠硬币。', '使用1块元素护甲片、1颗血石和1颗茶晶石制造出一件光芒护甲圣物，把它交给达拉然的提莫斯·琼斯。$B$B你可以在诺森德的任意亡魂身上找到元素护甲片。', '这是我答应要给你的达拉然珠宝匠徽章。明天再来找我，我会需要你再帮我找些什么的!', '你有带来光亮护甲圣物，好让我完成幽坑城的订单吗?', '', '去达拉然找卡蒂亚珠宝店的提莫斯·琼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12963, '货单：迅捷烈日古器', '我收到了一张可以给我带来丰厚利润的订单，上面明确要求订购一批迅捷烈日古器，以便在安德麦高价兜售。如果你能帮我制作一件的话，我可以奖励你一枚达拉然珠宝匠硬币。', '使用1件天灾古物、1颗太阳水晶和1颗暗影水晶制造出一件迅捷烈日古器，把它交给达拉然的提莫斯·琼斯。$B$B你可以在诺森德的任意天灾成员身上找到天灾古物。', '这是我答应要给你的达拉然珠宝匠徽章。明天再来找我，我会需要你再帮我找点什么的!', '你有带来移形烈日珍品，好让我完成幽坑城的订单吗?', '', '去达拉然找卡蒂亚珠宝店的提莫斯·琼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12964, '黑暗的矿石', '在雪流平原西部的冰霜矿洞里，雷铸铁矮人驱使奴隶日夜不停地劳作。$B$B那里戒备森严，所以我们对里面的情况所知不多。但我的斥候报告说，他们从里面运出了许多黑暗而诡异的矿石。', '为布德克拉格庇护所的塑石者布德克拉格带回5份黑暗的矿石样本。', '<石崖伸手拿矿石，但随即缩手。>$B$B那种矿石…我没办法碰它。它翻涌着非自然的能量。没有任何石头生物能够触摸它。他们想要用这个来做什么?', '关于矿石，你发现了什么?', '', '去风暴峭壁找布德克拉格庇护所的塑石者布德克拉格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12965, '洛肯的礼物', '指挥雷铸铁矮人的是一个名叫瓦杜兰的家伙。虽然我从来没见过他们，但据说他的主人，控制着奥杜尔的守护者洛肯，给了瓦杜兰一些强大的泰坦圣物。$B$B这或许就能解释我的人在雷铸战士身上发现的那种强大而狂暴的力量。$B$B瓦杜兰的基地——尼达维里尔就在雪流平原的西南方。到那里去吧，$N，去削弱他的力量。摧毁洛肯送给他的礼物，并帮助我们消灭他的追随者。', '摧毁洛肯之怒、洛肯之力和洛肯之赐，然后返回布德克拉格庇护所，向塑石者布德克拉格复命。', '<石崖阴郁地点点头。>$B$B你削弱了雷铸，但他们还是持续作战。死伤对他们来说不算什么，但我们的防卫者却不断的倒下。就算死了一百个，甚至一千个铁矮人，他们也会一直作战下去，直到我们都被碾成粉末。', '真的吗?瓦杜然真的拥有强大的泰坦神器?你把它们破坏掉了吗?', '', '去风暴峭壁找布德克拉格庇护所的塑石者布德克拉格。', '摧毁洛肯之怒', '摧毁洛肯之力', '摧毁洛肯之赐', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12967, '元素之战', '斯诺雷曾经是我们国家的骄傲。他是一名强大的战士，许多敌人都倒在了他的棍棒下。$b$b我们尊敬他，虽然他已经大不如前了。无情的岁月使他的反应变得迟钝，力量不断衰弱。但他仍然像过去一样充满骄傲，从不错过任何参战的机会。$b$b说到战斗，我们正在冷却弗约恩之砧，好把它带回家去。但是一些残留的火焰亡魂仍在负隅顽抗。$b$b请你帮助斯诺雷重新体验他的光辉岁月，$r，请你指引他击败敌人。', '亚米尔德要求你陪伴斯诺雷转至弗约恩之砧，并帮助他杀死10个火热的亡魂。', '光荣的表现，$r。我会把你伸出援手的事告诉国王。$B$B铁钻已经差不多冷却了。我们丹尼弗兰见。', '你有带领思诺利迈向胜利吗，$C?', '', '去风暴峭壁找弗约恩之砧的亚米尔德。', '杀死火热的亡魂', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12968, '伊尔达的愚行', '那个造成一系列恶果的巫婆，风暴语者伊尔达，来到我们的村子中，一边污蔑我们高贵的传统，一边大肆宣扬什么“巫妖王将赐下力量”之类的肮脏诺言。$B$B她本该被一剑刺个透心凉，但是她的魔法非常强大，居然设法逃跑了。$B$B到瓦基里安的那座最大的建筑物里找到她，让她知道我们可不是好惹的。', '布伦希尔达村的复仇者伊芬要你进入瓦基里安，杀死风暴语者伊尔达。', '优尔达是自找的。没有人侮辱了海兹竞技之后还可以全身而退。就算是我们自己人都不行。', '你有找到优尔达吗?', '', '去风暴峭壁找布伦希尔达村的复仇者伊芬。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12969, '这是你的地精吗？', '我想那个绿色的小个子就是你要找的人了。如果我是你，我会在那个海德尼尔人把他撕成两半之前救他出来。$B$B你身处海德比武会的比武场中，所以只要你发起挑战，对方就必须接受。没有人会阻止你救出你的绿皮朋友。', '向安格妮塔·泰斯多达尔发起挑战，救出西弗·菲兹巴克。成功之后，向布伦希尔达村的女巫洛莉拉复命。', '做的好，年轻人。看来我们的约定对双方来说都已经圆满履行了。', '你回来了。', '', '去风暴峭壁找布伦希尔达村的女巫洛莉拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12970, '海德比武会', '无论你是否注意到，当你第一次在格斗中战胜海德尼尔人时，你就已经参加了海德比武会——海德尼尔人通过这种竞赛，决定由谁来代表托里姆进行统治。$B$B海德比武会就是我被囚禁的原因，因为我想参加比赛，但我太老太虚弱了，海德尼尔人看不起我。$B$B如果你不介意的话，我倒有个提议。', '听取女巫洛莉拉的提议。', '一切都安排妥当了。在我的协助下，你会在海兹竞技中大放异彩，并使伟大的托里姆重返荣耀。', '压低身子，其它人会起疑的。', '', '去风暴峭壁找布伦希尔达村的女巫洛莉拉。', '听取洛莉拉的提议', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12971, '迎接挑战者', '现在我来为你介绍一下情况。好消息是，在打败安格妮塔以后，你已经进入了下一轮的比赛。$B$B坏消息是，你所有的对手也都是在第一轮中获胜的强者，所以你就别指望能挑软柿子捏了。', '布伦希尔达村的女巫洛莉拉要你去打败6名获胜的挑战者。', '你做到了，$N。你击败了海迪尼尔最凶悍的几名斗士。', '是，$N?', '', '去风暴峭壁找布伦希尔达村的女巫洛莉拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12973, '铜须兄弟', '终于……终于拿到钥石了！它真是太漂亮了！我曾多次环游世界，自以为见多识广，但它让我又一次激动地浑身发抖了。不过呢，现在不是停下来欣赏的时候，我们必须赶快离开这里。$B$B跳到我的飞行器上面来，你要帮我除掉那些挡路的铁矮人！', '与布莱恩·铜须及其飞行器一起返回冰霜堡。', '风暴之心国王由衷地感谢你，让他与他的兄弟重逢。他似乎已动身为将临的大战作准备 - 也许你会在阿尔萨斯的大门前，和他再次碰头。', '我向你致歉，$G小子:小女孩;!那时我全神贯注，完全忽略了你的存在。', '与布莱恩·铜须一起回到冰霜堡。', '去风暴峭壁找冰霜堡的维罗格·冰啸。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12975, '回首往事', '托里姆肯定跟你提起过那场造成我们分裂的悲剧。$b$b一切都发生在东北方的落雷谷。那里遍布着冰冻的化石，它们既是那个黑暗之日的纪念，也是萦绕在那里的幽灵。$b$b如果要我的族人原谅托里姆，就必须用某些东西替代那些化石。我们必须修建一座纪念碑，以求得心灵上的宁静。$b$b霍迪尔的号角就是在那一天破碎的，去收集它的碎片吧，$r。', '丹尼芬雷的约库姆国王要求你前往落雷谷，收集8块号角碎片。', '你又代表托里姆做了一件好事，$C。$B$B这对于软化我们对托里姆的心态一定会很有帮助的。', '你找到霍迪尔号角的碎片了吗?', '', '去风暴峭壁找丹尼芬雷的约库姆国王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12976, '亡者的纪念碑', '把这些碎片交给亚米尔德。他会用这件圣物的碎片建造一座雄伟的纪念碑。$b$b希望它能够抚慰我的族人多年来的伤痛。$b$b希望它的建成能够开创一个新的时代，让我们在光荣的战斗中再次与托里姆并肩作战。$b$b现在就去吧，$c。亚米尔德在等着你。', '约库姆国王要求你将号角碎片交给丹尼芬雷的亚米尔德。', '<当尼约梅尔德把袋子里的东西倒到铁钻上的时候，他的眼睛很明显的泛出泪光。>$B$B霍迪尔号角……$B$B这是霍迪尔亲自送给我们人民的神圣赠礼，$r。这对我们来说是个非常重要的圣物。$B$B当你下次回到要塞来的时候，你应该就可以看到你努力的成果了。$B$B再会。', '你把霍迪尔号角的碎片带来了，$r?', '', '去风暴峭壁找丹尼芬雷的亚米尔德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12977, '吹响霍迪尔的号角', '你为丹尼芬雷的巨人提供了巨大的帮助。若不是你伸出援手，这座纪念碑是建不起来的。$b$b你默默地思考着它的意义，心中思绪万千。你的脑海中闪过无数的念头和影像……还有沉重的紧迫感。$b$b种种思绪消失之后，你突然明白了自己应该怎么做。你必须让落雷谷中那些不能安息的亡魂重获安宁。$b$b在你准备出发时，发现手中出现了一只灵体号角。', '转至落雷谷，击败5名尼芬雷先祖和5名永不疲倦的霜脉矮人，并对他们的尸体吹响霍迪尔的号角。然后将霍迪尔的号角带回丹尼芬雷。', '知道那些一度在雷殒之地受尽折磨的灵魂现在安息了，你心中充满了平静的感觉。', '强风在号角周围打转，让号角的音响回荡在群山之间。$B$B对不知情的过客而言，看来就像是号角的自鸣…', '', '去风暴峭壁找丹尼芬雷的约库姆国王。', '释放尼芬雷先祖', '释放永不疲倦的霜脉矮人', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12978, '进攻尼达维里尔', '和布德克拉格一样，我在奥杜尔时也曾经是守护者们手下的一名工匠。但在洛肯叛乱之后，我就把手中的铁锤指向了新的敌人。$B$B在我们还能抽出人手时，我曾率领部队进攻尼达维里尔，以减轻这边的防守压力，但眼下我们的防线已经几近崩溃了。$B$B你已经证明自己是一名强大的勇士和可以信赖的伙伴。或许你愿意举起我们的旗帜，参加对尼达维里尔的战斗。这处铁矮人的堡垒就在西南方，要穿过雪流平原。', '布德克拉格庇护所的布鲁沃·斩铁要你转至尼达维里尔，杀死10个雷铸铁矮人的士兵。雷铸勇士、雷铸大法师或雷铸作战魔像都可以。', '这也许是胜利的希望，$N。我们一直都不能持续攻击雷铸矮人，但有了你的协助，也许瓦杜然会倒下!', '你有好好地锤打尼达维里尔的那些铁块了吗?', '', '去风暴峭壁找布德克拉格庇护所的布鲁沃·斩铁。', '杀死尼达维里尔的雷铸铁矮人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12979, '黑暗的护甲板', '与这只魔像身上的其它护具相比，这片护甲板特别厚重。你迅速检查了一下魔像的尸体，发现这块大家伙似乎是后来才焊接上的，或是匆匆升级的产物。$B$B铁矮人为什么要给作战魔像装上这种多馀的、不匹配的护甲呢？$B$B如果能把雷铸作战魔像身上的这种护甲板拿给布鲁沃·斩铁检查一下的话，或许能发现些什么。', '将4份黑暗护甲板样品交给布德克拉格庇护所的布鲁沃·斩铁。', '小心。把那块护甲拿的离我远一点。光是它的存在就会造成我的痛苦。$B$B但你做对了，$N。这个护甲片对一般的魔像来说实在太过巨大了。雷铸矮人究竟在做什么?只有一个方法能找出解答。', '你手上拿着的是什么?', '', '去风暴峭壁找布德克拉格庇护所找布鲁沃·斩铁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12980, '护甲板的秘密', '这些护甲板的出现让人感到迷惑，但我们要尽量发掘出其中的秘密。这可能是瓦杜兰的诸多阴谋中的一部分。$B$B他正在以超乎寻常的热情来开采、精炼、锻造和测试这种金属。$B$B在东边，北方群山的南麓上有一座建筑物，名叫米米尔的车间。它已经停用了一段时间，但如果我们足够幸运的话，里面或许还有一些工作人员在活动。带着护甲板到那里去，尽量找出其中的秘密。', '把黑暗护甲板带到米米尔的车间去，让随从托克检查它。完成任务后，向布德克拉格庇护所的布鲁沃·斩铁复命。', '<布鲁尔听你描述在工坊的发现。>$B$B瓦杜然的主人给了他这块金属要他建造一座巨大的武器?这一定是要用来对我们做最后一击的!我们必须在他完成这个武器，对我们使用之前快点阻止他!', '你知道了什么?', '', '去风暴峭壁找布德克拉格庇护所的布鲁沃·斩铁。', '检查护甲板', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12981, '热与冷', '你凝视着铁砧，回忆起自己付出的艰辛，尤其是促成铁砧落户此地的过程。$b$b你突然想起还有许多事情要做。东边的战场上到处都是炸弹爆炸后留下的碎片，它们仍在冒烟。$b$b如果能冷却并回收这些弹片，冰霜巨人就有了足够的金属储备，顺便还可以清扫一下战争对这片土地造成的创伤。', '转至霜原湖，消灭脆弱的亡魂，并对冒烟的碎片使用冰之精华。收集6块冻铁碎片，将它们带回丹尼芬雷的弗约恩之砧。', '当你了解到你的作为持续地在修复托里姆与霍迪尔之子的关系时，你觉得很有成就感。', '一道蓝色的光芒环绕着铁钻。', '', '去风暴峭壁找丹尼芬雷的弗约恩之砧。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12982, '黑锋囚犯', '既然我已经回来了，我想男爵一定会让我去寻找我的部下。显然，我们已经有点撑不住了。巫妖王的部队源源不断地涌来，没有我的死亡骑士，防线被攻破只是时间问题而已。$B$B你可以再帮我个忙吗，$N？$B$B回到尤顿海姆，把他们从牢笼里救出来。我不管你用什么手段，打开那些该死的锁就行了——维库人身上或许会有钥匙。$B$B把我的部下救出来！', '暗影拱顶的被折磨的维林要求你去解救8位黑锋囚犯。你可以在尤顿海姆地区的各个牢笼里找到他们。', '谢谢你，$C。有了你放出来的这些死亡骑士，我们就能够守住防线…至少就当前而言。', '一定还有更多我手下的死亡骑士，等着被放出笼子吧?!', '', '去冰冠冰川找暗影拱顶的被折磨的维林。', '营救黑锋囚犯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12983, '最后的母熊', '根据我的记忆，我们最好的熊都是从东边的冬眠洞穴里抓来的。$B$B那些好日子或许已经一去不返了。现在冬眠洞穴已经被饥饿的冰虫占据，野熊几乎绝种。$B$B不过，如果你能找到一头幸存的母熊，我敢保证她的战斗力会远远超越这些圈养的熊。$B$B带着这副挽具转至冬眠洞穴，去拯救那里幸存的母熊吧。希望你找到一头母熊，祝你好运。', '布伦希尔达村的艾丝崔·约利塔尔要你去冬眠洞穴解救一头冰喉母熊。', '令人印象深刻。我从未想过能够再见到一头冰喉族母。更遑论这样的尺寸。', '你有找到族母吗?', '', '去风暴峭壁找布伦希尔达村的艾丝崔·约利塔尔。', '解救冰喉母熊', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12984, '风暴之子瓦杜兰', '我们别无选择，$N。你在米米尔的车间中的发现，意味着我们必须先发制人，在瓦杜兰完成并使用新武器前采取行动。$B$B即使是现在，庇护所的守卫还在继续战斗，为我们争取时间去解决风暴之子瓦杜兰。$B$B你必须穿过西南方的雪流平原，到尼达维里尔去找到并战胜瓦杜兰。但你并不是孤军奋战。带上这支号角，当你准备好迎战这位敌人的首领时，就吹响它。我和布鲁沃会协助你战斗的。', '当你发现风暴之子瓦杜兰时，使用布德克拉格的作战号角。击败风暴之子瓦杜兰，然后回到布德克拉格庇护所，向塑石者布德克拉格复命。', '终于，瓦杜然死了，雷铸矮人的攻势也消退下去了，但若他的自吹自擂并非虚言，我们就得继续和雷铸矮人战斗，即使他已不在。他们正建造的这件武器，也许将给我们带来末日。', '在避难所陷落之前我们一定得对付瓦杜然。', '', '去风暴峭壁找布德克拉格庇护所的塑石者布德克拉格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12985, '雷铸徽记', '欢迎你，$r。$b$b我有一件事情要交给你去办。约库姆国王认为，既然你仍在坚持争取我们族人的信任，那么你就是绝佳的人选。$b$b我计划制造一件新的圣物，用它求得霍迪尔的祝福，让他庇护我们的堡垒。我基本收集到了所有的材料，现在只缺一些敌人的徽记了。$b$b我要你带上这件工具，用它收集野外那些铁巨人的徽记。', '丹尼芬雷的亚米尔德要求你转至霜原湖，对那一带的死亡的铁巨人使用钻石尖锄，收集8枚雷铸徽记，然后回去向他复命。', '就快完成了。$B$B有了这个神器，丹尼弗兰应该可以在危险逼近之前就先得到警告。', '你收集到我需要的最后一项材料了吗，$r?', '', '去风暴峭壁找丹尼芬雷的亚米尔德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12986, '泰坦的命运', '诺甘农之核不在这里。我不知道你为什么要找它，$r，同样我也不知道你是否明白它的意义。$B$B如果你愿意帮我一个忙，那么我就可以向你提供帮助。最近我得知了守护者托里姆的事情。他的宝座岌岌可危，他的命运扑朔迷离。这让我感到困扰，因为我不知道其它守护者的近况。带着这个数据库，到东北方的神殿去探查一番，然后回到我这里来。', '山底平原的克莱特乌斯要求你转至创世神殿、寒冬神殿、生命神殿和秩序神殿，并使用数据库探查这些本地。', '你所带来的消息确实很严重。我不知道其它的看守者下场如何，但是他们的失踪，象征着艾泽拉斯全境的黑暗时代。$B$B我将会检查你带回来的信息，评估现况。不过我相信我手头上有个你认为更重要的信息，所以我会先与你分享。', '你带着我需要的信息回来了吗，$r?', '', '去风暴峭壁找山底平原的克莱特乌斯。', '调查创世神殿', '调查寒冬神殿', '调查生命神殿', '调查秩序神殿');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12987, '霍迪尔之盔', '头盔已经铸造好了。$b$b你的努力是不会白费的，小家伙。虽然还有许多事要做，但我们霍迪尔之子都非常感谢你的帮助。$b$b作为回报，我要让你亲自将霍迪尔的头盔呈献给我们的国王，我们的兄弟。$b$b飞到我前面的这根冰柱顶端上面，并像我们的族人大声宣读这块石板上的内容。$b$b好好享受这份特权吧，$c。之前从没有哪个外来人获得过这样的荣誉！', '亚米尔德要求你飞到丹尼芬雷北边的冰柱顶端，并在那里使用宣告石板。', '<尼约梅尔德凝视着头盔，看得出来深受感动。>$B$B这样就行了，小$r。$B$B这样就行了……', '你放置了霍迪尔之盔了吗，$r?', '', '去风暴峭壁找丹尼芬雷的亚米尔德。', '放置霍迪尔之盔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12988, '摧毁熔炉！', '我曾经愚蠢地以为，瓦杜兰在纳维尔支架——也就是南面那片巨大的建筑本地所进行的工程，只是在为残忍的守护者洛肯创建一座奇异的纪念碑而已。$B$B现在我们知道了真相，那是一件用来对付我们的武器！一定不能让他们完成这台钢铁巨像，$N，否则庇护所就要大祸临头了。$B$B转至纳维尔支架，找到雷铸铁矮人的闪电熔炉，把它们都给毁掉。', '使用布德克拉格的炸弹摧毁北部闪电熔炉、中部闪电熔炉和南部闪电熔炉，然后回到布德克拉格庇护所，向塑石者布德克拉格复命。', '做的好!噢，这不能阻止那些铁矮人，但是会使他们花上很多时间重建熔炉。我敢说我们现在占了优势。', '你有成功地破坏熔炉，妨碍他们吗?', '', '去风暴峭壁找布德克拉格庇护所的塑石者布德克拉格。', '炸毁北部闪电熔炉', '炸毁中部闪电熔炉', '炸毁南部闪电熔炉', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12989, '黑暗的冰虫', '恶心的冰虫几乎占领了整个冬眠洞穴。这些下等的生物……它们都是托里姆那个不争气的兄弟洛肯的后代。$B$B作为托里姆的仆人，我们应该尽力消灭这些渣滓。那个山洞就在村子的东边。', '艾丝崔·约利塔尔要你到布伦希尔达村东边的冬眠洞穴去，杀死8条饥饿的冰虫。', '蛰猛巨虫是邪恶的生物。摧毁他们是一件好事。', '你回来了!', '', '去风暴峭壁找布伦希尔达村的艾丝崔·约利塔尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12991, '正中要害', '布德克拉格已经想到了一个很棒的计划，可以扰乱铁矮人在纳维尔支架的工作，而我自己也有个点子。如果没有技师的话，那个钢铁巨像的建造工作就寸步难行了。$B$B纳维尔支架就在遮挡这座庇护所的山岭南面。到那里去，把你一路上看到的雷铸技师都给干掉。他们也许和以前的我们没有什么不同，但他们正在制造一件对我们所有人都产生了威胁的武器。', '杀死10名雷铸技师，然后返回布德克拉格庇护所，向布鲁沃·斩铁复命。', '以前我绝对不能开口要求别人做你做的这些事，但与铁矮人的交战已经消弭了那种感觉。我们替抵挡敌人进犯争取到了宝贵的时间。', '你杀死那些生产铁巨像的工匠了吗?', '', '去风暴峭壁找布德克拉格庇护所的布鲁沃·斩铁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12992, '干掉那些维库人！', '必须干掉尤顿海姆的维库人！$B$B$N好好教训他们！', '暗影拱顶的劣尸维尔希望你在尤顿海姆地区消灭15个维库人。', '$N是我最棒最棒的小$r!', '臭维库人还没死光!', '', '去冰冠冰川找暗影拱顶的劣尸维尔。', '消灭尤顿海姆的维库人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12993, '巨像的威胁', '你成功地延缓了钢铁巨像的建造工作，非常好。不过我担心，这样只会让雷铸铁矮人更加坚定地完成武器的建造工作。$B$B即便在现在，他们仍然在不停地派入新的劳工，而他们的工头也在不断逼迫他们日以继夜地工作。我们或许不能阻止他们建成钢铁巨像了。因此，我们必须知道我们将要面对的是什么。回到南面的纳维尔支架，寻找描述巨像进攻和防御能力的相关文档。它们应该在帐篷和底层的熔炉附近。', '找到巨像攻击规范说明书和巨像防御规范说明书，并把它们交给布德克拉格庇护所的塑石者布德克拉格。', '<石崖开始查看文件，然后睁大了眼睛。>$B$B我可真不晓得那些铁家伙们能做到这种事!如果这个巨大怪兽完成了，我们的手下连一点机会也没有。幸好，他们似乎缺少一个关键零件。', '你找到我们要的那些文件了吗?', '', '去风暴峭壁找布德克拉格庇护所的塑石者布德克拉格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12994, '猎杀间谍', '你和丹尼芬雷的居民之间创建起来的友谊给你带来了一些意外的发现。$B$B比如，你似乎能听懂冰霜座狼母兽的低吼和尖叫声——至少你觉得自己理解了。$B$B她似乎感受到了要塞外的威胁，要你采取防范措施。$B$B她用前爪取下脖子上的锁链，将它丢在你的脚边。当你捡起锁链时，发现上面系着一枚古老的牙齿……', '击败上古寒冬山谷中的3名雷铸间谍。$B$B对座狼的尸体使用灵体座狼之牙，召唤出一只灵体冰霜座狼，帮助你找出隐藏的敌人。完成任务之后向丹尼芬雷的冰霜座狼母兽复命。', '当你把炼子套回兽母脖子上的时候，她赞许地舔了舔你的脸。', '冰霜座狼兽母好奇地看着你。', '', '去风暴峭壁找丹尼芬雷的冰霜座狼母兽。', '杀死雷铸渗透者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12995, '彰显军威', '我们必须从各个方面向尤顿海姆的维库人发动攻击。虽然有时候蛮力还是很有用的，不过我偏向于使用更睿智的手段。$B$B我希望你能去挫败他们的士气。$B$B我的手下为你制作了许多旗帜。我希望你能带上它们，将它们竖在维库人的尸体旁。$B$B用旗帜让他们明白：他们面对的是比巫妖王之怒更加直接的威胁。', '暗影拱顶的斯利文男爵希望你转至尤顿海姆地区，将黑锋旗帜插在15具维库人的尸体附近。', '做的好，$N。就让他们看见死去同伴的尸体被亵渎，然后就会在发动攻击前三思!$B$B如果你明天再来，我还会为你准备好更多旌旗。', '噢，$N，我想你还没办完吧。', '', '去冰冠冰川找暗影拱顶的斯利文男爵。', '将黑锋旗帜插在维库人的尸体附近', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12996, '热身赛', '你非常幸运，我的姐妹。我们已经很多年没有见过这种母熊了。$B$B不过，如果没有优秀的骑术，再好的熊也是没有用武之地的。$B$B我要你骑着母熊去挑战基加拉格。动手的时候要小心一点，基加拉格是我们抓到过的体形最大的雪人。如果你撑不住了，就及时跑开，不要逞强……我们给他套上枷锁是有原因的。', '布伦希尔达村的艾丝崔·约利塔尔要你使用冰喉母熊的缰绳打败基加拉格。', '不错。我还有点期待齐尔加瑞克折断了你的颈子，这样我就能得到你的熊了。$B$B只是开个玩笑，姊妹。好吧…有一半是在开玩笑。你的熊真的很不赖。', '雪人那边进行的如何?', '', '去风暴峭壁找布伦希尔达村的艾丝崔·约利塔尔。', '打败基加拉格', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12997, '进入利齿之坑', '打败一个套着枷锁的对手是一回事，与其它骑熊的对手公平对战又是另一回事了。$B$B到利齿之坑去吧，用你学到的技巧去击败对手。祝你好运，我的姐妹。$B$B如果你获胜了，就可以获得崇高的荣誉。', '布伦希尔达村的艾丝崔·约利塔尔要你在利齿之坑里使用冰喉母熊的缰绳，并打败6头海德比武会战熊。', '你真的办到了!你完好无缺地回来了。真希望你的熊也是这样。$B$B她需要一点时间来恢复元气。不过也幸亏你暂时用不着她。', '好啊!我的姐妹。', '', '去风暴峭壁找布伦希尔达村的艾丝崔·约利塔尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (12998, '风暴之心', '按照你从纳维尔支架得到的文档来看，这台钢铁巨像已经基本完成了，只缺一个关键的要素——风暴之心。$B$B没有风暴之心的话，它将会比设计中弱很多。如果我们能阻止督工纳维尔得到风暴之心，就可以击败这台钢铁巨像。$B$B从文档中的注释来看，风暴之心就在奥迪斯，那是一座地处南面远方的泰坦设施。它的入口就在俯视伯尔之息河的高山的南面。', '布德克拉格庇护所的塑石者布德克拉格希望你转至奥迪斯，尝试阻止纳维尔获取风暴之心。', '风暴之芯落入了那维尔手中，那么巨像就会拥有完全的力量!我们别无选择，只能与它作战了。', '告诉我风暴之芯没有落入敌人的手里。', '尝试在督工纳维尔之前找到风暴之心', '去风暴峭壁找布德克拉\r\n格庇护所的塑石者布德克拉格。', '尝试夺取风暴之心', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13000, '紧急措施', '这片山区非常寒冷，而且飞艇残骸里的木头只够我们烧一到两天的。$B$B我们发现正东方的山洞里有一些座狼。我要你去找到那个山洞，弄些毛皮回来。这听起来似乎没有多大作用，不过一张毛皮可能就决定了我们是被冻死还是多活一天。$B$B座狼都是集体出动的，所以我把这枚照明弹给你。万一你被它们包围了，这东西可以为你争取一些逃命的时间。', '血卫士洛尔加要你转至东边的基莫拉克之巢，收集6张座狼的毛皮。', '这些毛皮还真是…巨大。我可不想碰上你对付的那些座狼。$B$B我们都很感激你。气温都已经开始下降了。', '你把毛皮给带来了吗?', '', '去风暴峭壁找格罗玛什坠毁点的血卫士洛尔加。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13001, '霍迪尔之矛', '时机已经成熟，小$c。星象已经预兆了这一天的到来。$b$b伟大的霍迪尔亲自向我展示了一个幻象——那是伟大的神器霍迪尔之矛的诞生过程。$b$b我们必须把它造出来！如果我们不能收到这份礼物，就会遭到灭顶之灾。$b$b作为立誓为氏族服务的仆从，我召唤你协助完成这项神圣的使命。$b$b我要你穿越峡谷，深入冬眠洞穴，从那里的冰冷坑地中收集永冻碎片，另外还要收集洞外猛犸象的毛皮。', '丹尼芬雷的博学者兰德维尔要求你转至冬眠洞穴收集3块永冻碎片，并从上古寒冬山谷的坚韧猛犸象身上收集3块坚韧猛犸象的毛皮。', '往后退，$r，见证一个预言的实现吧!', '你收集了长矛所需要的材料了吗，$r?', '', '去风暴峭壁找丹尼芬雷的博学者兰德维尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13002, '完美宝石', '欢迎来到冰天雪地的诺森德，朋友。这里也许并不能让我感到温暖，但是我学会了切割完美宝石的技术。我所需要的只不过是一些宝石，不然怎么开工啊。$B$B给我弄一些宝石来，我就把切割完美宝石的技术传授给你。切割完美宝石能让你在切割诺森德地区出产的优秀质量宝石时，有机会切割出一颗具有更高属性的完美宝石。', '将茶晶石、黑玉和暗影水晶各两颗交给战歌要塞的格巴里。', '这真是完美啊老兄。来，这就是宝石完美工法的奥秘。', '这就是我想要的。现在我要教你宝石完美工法啦。', '', '去北风苔原找战歌要塞的格巴里。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13004, '完美宝石', '战争一触即发，我们都要竭尽所能！我的长处在于切割宝石，而且不是普通的宝石，是完美的宝石！如果你能弄些未切割的宝石来给我，我也可以教你学会这种技术。切割完美宝石能让你在切割诺森德地区出产的优秀质量宝石时，有机会切割出一颗具有更高属性的完美宝石。', '将茶晶石、黑玉和暗影水晶各两颗交给无畏要塞的奥雷斯托斯。', '谢谢。我会教你宝石完美工法，并且送你一颗切好的完美宝石。', '感谢你的奉献。让我来教你宝石完美工法吧。', '', '去北风苔原找无畏要塞的奥雷斯托斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13005, '土灵的誓言', '多年以来，我一直没能履行自己的职责，整日沉浸在挫败和自责之中。$B$B但勇敢的土灵没有放弃。他们遵守了要用生命来守卫造物者圣台的誓言。$B$B直到现在，他们仍然在英勇地对抗堕落的铁矮人，期待着战局扭转的那一刻。$B$B就是现在！我们必须召集剩馀的土灵守护者，带领他们赢得光荣的胜利。吹响峭壁号角吧，把他们召集到你的身边，带领他们打败敌人，夺回造物者圣台。', '造物者圣台的托里姆要求你使用峭壁号角召集土灵，并打败20个铁矮人和7个铁哨兵。', '这是个好的开始。但是我哥哥的部队花不了多少时间就会重组。我们必须取得决定性的胜利。', '你好，$N!你带来了什么样的消息?', '', '去风暴峭壁找造物者圣台的托里姆。', '杀死铁哨兵', '杀死铁矮人攻击者', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13006, '擦亮霍迪尔的头盔', '当你靠近头盔时，你注意到它的表面在寒冷气候的侵蚀下已经变得锈迹斑斑。虽然当前只是一层薄薄的冰霜，但是用不了多久，整个头盔就会被严冰完全复盖。$B$B你不想让之前付出的努力付诸东流，于是你环视四周，想要找出解决的办法。$B$B就在你离开时，头盔的眼罩处发出微光，你的脑海中顿时浮现出冬眠洞穴的影像。', '进入丹尼芬雷以西的冬眠洞穴，从粘性油污身上收集5份粘性油。$b$b然后返回丹尼芬雷，将油涂在霍迪尔的头盔上。', '当你在头盔上抹上一层油的时候，上面的霜雪褪去，头盔表面微微闪烁着光芒。', '当你看着头盔的同时，霜雪在上面越积越厚，边缘也开始垂下冰柱……', '', '去风暴峭壁找丹尼芬雷的霍迪尔之盔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13007, '钢铁巨像', '我们未能阻止钢铁巨像的建成，$N。这就意味着我们除了和它战斗之外别无选择。$B$B布鲁沃针对钢铁巨像唯一的弱点想出了一个计划。$B$B不管它的护甲有多么坚固，它仍然容易受到酸液的腐蚀。在雪流平原的北方边缘使用宝珠控制冰虫，然后在雪流平原上寻找钢铁巨像，用冰虫来对付它。如果你需要有人帮助你控制冰虫，就和旁边的那些驭手们聊聊吧。', '使用被驯服的冰虫击败钢铁巨像，然后回到布德克拉格庇护所，向塑石者布德克拉格复命。', '我们成功了，我们真的成功了!避难所得救了，雷铸被打败了!我们一定得在洛肯试图重建他的军队之前先警告布莱恩。要维持今日的胜利唯一的方法，就是进入奥杜亚，一劳永逸地把洛肯击败!', '你击败巨像，避免避难所的毁灭了吗?', '', '去风暴峭壁找布德克拉格庇护所的塑石者布德克拉格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13008, '天灾的战术', '我们用了一个奇招，在山的这一边炸开了一个大洞，然后杀进了天灾城。结果呢，天灾军团的防线可谓固若金汤，很快它们就凭数量优势把我们打退了回来。我们撤回了山谷，开始对那些追杀过来的的天灾士兵进行炮击。这一招暂时延缓了它们的攻势，直到……直到那群怪物开始把北伐军士兵当作肉盾。我们只好停止炮击，不然就会杀死我们自己的士兵。$B$B去把那些被困在战场上的北伐军士兵救回来，$c！', '冰冠冰川银色前线基地的北伐军指挥官恩塔里要求你去解救8名被网住的北伐军士兵。', '还有许多银色北伐军的士兵待在外头的原野和天灾岸地里，$N。我们很感谢你的帮忙，但还有许多事情要做。', '你解救了被网住的十字军吗?', '', '去冰冠冰川找银色前线基地的北伐军指挥官恩塔里。', '营救被网住的北伐军士兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13009, '新的开始', '我们的族人是否能再次接纳托里姆，这还是个未知数。$b$b希望这套铠甲可以让他回忆起那段久远的岁月，那段我们充满荣耀地并肩作战、无坚不摧的岁月。', '亚米尔德要求你将重铸的风暴之王铠甲交给风暴神殿的托里姆。', '<当你将重铸的护甲展示给托里姆看的时候，他明显地深受护甲的光彩震慑。>$B$B你做的很好，$r，但还有许多事等待着我们去做。', '你的辛劳有成果了吗，$C?', '', '去风暴峭壁找风暴神殿的托里姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13010, '科洛米尔，风暴之锤', '为了夺回我在造物者圣台的家园，我们还要再做一件事。$b$b我们必须找到科洛米尔。$b$b在那个命运审判之日，我将全身心的怒气和力量灌入那柄战锤中，并将它掷向了地面，然后就发生了巨大的爆炸。$b$b这么多年来，我一直以为它已经遗失了，不过现在我必须确认这一点。$b$b请你回去问问约库姆国王，看他是否知道任何有关我的战锤的消息。', '托里姆要你与丹尼芬雷的约库姆国王谈一谈，向他打听科洛米尔的消息。', '再多言语都不能表达我的感激，$C。$B$B你替我做了很多。请收下这个，让我聊表谢意。', '回来了，小$r?', '', '去风暴峭壁找风暴神殿的托里姆。', '打听科洛米尔的下落', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13011, '肥胖的尤姆塔尔', '我有一项任务要交给你，这可以让你赢得我的族人们的认同，对你是有好处的。$b$b冰虫是一种讨厌的生物，繁殖非常快。只要给它们一点喘息之机，它们就会像兔子一样飞快地繁殖，像野火一样蔓延开来。$b$b西南方的冬眠洞穴里已经出现了冰虫的踪迹。如果不尽快杀掉那条冰虫女王，它们就会在我们的地盘上扎根了。$b$b它绝对不能抵抗食物的诱惑。带上这把刀，在它们的洞穴里随便找一头熊的尸体，割一块腰肉下来。把肉放在冰虫女王的巢穴附近，趁它进食的时候除掉它。', '丹尼芬雷的约库姆国王要求你转至冬眠洞穴，杀死尤姆塔尔。', '你完成了任务。$B$B我们听到乔穆塔的哀嚎在山谷中回响。$B$B你今天替我们的族人立下功劳，小$r。', '你杀死乔穆塔了吗?', '', '去风暴峭壁找丹尼芬雷的约库姆国王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13034, '见证者与英雄', '踏上诺森德的征程后，我在北风苔原首次遇到了牦牛人。驯风者巴兰向我讲诉了雷蹄的传说，以及他对抗牦牛人部族的宿敌“北风”的英勇事迹。$B$B于是我来到风暴峭壁，想要了解更多有关这位英雄的故事。奇怪的是，唐卡洛营地的居民似乎对他一无所知。$B$B或许我们能从营地的档案中找到一些重要的线索。我要你去寻找并阅读营地中的历史书卷，然后告诉我你从中了解到了什么。', '唐卡洛营地的夏拉托尔希望你去阅读第一份历史卷轴、第二份历史卷轴和第三份历史卷轴。', '这可奇了…听起来跟驯风者巴拉告诉我的故事不一样。', '你从坦卡罗营地的纪录里查出了些什么?', '', '去风暴峭壁找唐卡洛营地的夏拉托尔。', '阅读第一份历史卷轴', '阅读第二份历史卷轴', '阅读第三份历史卷轴', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13035, '洛肯的副官', '洛肯早就策划好了对造物者圣台的进攻策略。他派出了铁矮人军团以及几名最得力的副官。$B$B使用峭壁号角召唤土灵，在他们的帮助下击败洛肯的仆从。$B$B你可以在北面的塑造者之厅找到巨人伊森法斯，然后沿着西北方的台阶进入造物者圣台，击杀其馀的副官。', '托里姆要你杀死塑造者之厅的伊森法斯、造物者圣台的风之哈勒弗尼尔和符文巨人杜洛恩。', '一个接着一个，我兄弟的仆人都倒下了。洛肯的叛乱很快就将终结。', '再次见到你真好，$N。', '', '去风暴峭壁找造物者圣台的托里姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13038, '时间的扰动', '这里，唐卡洛战士的墓地，本来是一块远离元素侵扰的安宁之地。$B$B如今，浮冰深渊却被一股诡异的力量侵袭，正是这种异状打扰了安息的灵魂，令我的记忆变得模糊不清。$B$B我们的事迹与记忆开始逐渐从历史中消散。$B$B我活着的时候，这根图腾是我身份的象征。在我死后，它则是连接我和生者世界最后的媒介。我要你借助它的力量恢复墓地的宁静，然后将它带回唐卡洛营地。', '使用酋长的图腾封闭4道浮冰裂隙，然后将图腾还给唐卡洛营地的夏拉托尔。', '酋长的魂魄要你交给我这个?$B$B<札伦陶检查了图腾一会>$B$B啊，我了解他的意图了。他要你用图腾封闭深渊里的裂隙，是为了让我们理解时间线发生了什么事。多么睿智的迅矛酋长，即使在死后，仍然看顾着他的子民。', '你从墓地带来了什么?', '', '去风暴峭壁找唐卡洛营地的夏拉托尔。', '封闭浮冰裂隙', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13039, '保卫前线基地', '我们坚持不了多久了，$g伙计:小姑娘;。在我们打开突破口之后，天灾士兵就像开了闸的洪水一样涌了过来，真是铺天盖地！$B$B我们需要每一个人都拿起武器，抵挡天灾军团的进攻。去尽你的那份责任吧，朋友。尽可能多地干掉那些怪物！', '冰冠冰川银色前线基地的北伐军领主达尔弗斯要求你杀死15只遗忘深渊蛛魔。', '它们究竟有多少啊?我们已经杀掉的敌人，已经足以填满十个墓地了，但他们还是一直出现。情况看来相当险峻，我的朋友。', '别放弃，$N!', '', '去冰冠冰川找银色前线基地的北伐军领主达尔弗斯。', '杀死遗忘深渊蛛魔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13040, '致命的剧毒', '受伤士兵的数字一天天地增加，他们都受到了某种我们从未见过的毒素的侵袭。不管这些蛛魔的毒液是如何构成的，总之，它们非常致命，简直可以说是毫无清除的可能！就现在来说，我们唯一能做的只是减缓毒素在受害者体内的蔓延速度。但是我们一定要想出一个治疗办法来！$B$B转至西北方，到前线基地外的山谷中去，干掉一些遗忘深渊蛛魔，把它们的毒囊给我拿回来。', '冰冠冰川银色前线基地的古斯塔夫神父要求你交给他10个遗忘深渊毒囊。', '谢谢你，$N。我立刻着手研究，希望很快就可以找到解药。', '你带回那些虫子的毒腺了吗，$r?', '', '去冰冠冰川找银色前线基地的古斯塔夫神父。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13041, '完成订单', '真高兴见到你！我必须尽快将一批炽热鹿牙雕像送到安德麦去，但是恰好缺少一颗玉髓石来完成最后一尊雕像的眼睛。$B$B给我弄一颗宝石来，这枚达拉然珠宝匠硬币就是你的了。', '将一颗玉髓石交给达拉然的提莫斯·琼斯。', '这是我答应要给你的达拉然珠宝匠徽章。我总是有订单要交，所以别忘了常来看看我缺些什么东西。', '你弄到玉髓没?', '', '去达拉然找卡蒂亚珠宝店的提莫斯·琼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13042, '地下大厅的深处', '在东北方的地下大厅深处，有一个名叫恐怖博士的科学怪人，他正在秘密策划一项与他的名字相符的行动。$B$B如你所知，那些战死沙场、而且没有利用价值的维库人都会变成“瓦古”。恐怖博士正是奉了巫妖王之命，对这种被称为“瓦古”的天灾士兵进行实验。$B$B我们必须阻止他的研究工作，可是我的占卜术却无法探明他的下落。好在恐怖博士有一名助手。$B$B我要你去调查他的学徒，并获取必要的情报。如果他有所察觉，你就打败他之后赶紧回来。', '约尔达村的白骨女巫要你调查学徒奥斯特基格，弄清楚恐怖博士的计划。$B$B事成之后，击败学徒奥斯特基格，并回来向女巫汇报。', '真有趣。听起来你干得不错。让我惊讶的是，恐怖博士那家伙竟然让一个实验用的瓦苟，当他的助手。', '你还没完成我交付的工作。$B$B没完成之前别回来，否则有你好受!', '', '去冰冠冰川找约尔达村的白骨女巫。', '调查学徒奥斯特基格并得到情报', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13043, '一加一大于二', '打开书卷之后，你发现上面绘制着各种各样令人作呕的插图，它们就是被恐怖博士称为“终极武器”的丑陋怪物！$B$B很显然，这些嵌合怪的原型就是那个名叫尼尔盖德的血肉巨人，它静静地矗立在恐惧大厅的尽头。$B$B如果让巫妖王建造出这样一支军队，世界将面临毁灭的威胁。要阻止事态的恶化，唯一的办法就是杀死恐怖博士！$B$B也许在你控制血肉巨人之后，恐怖博士就会被迫现身？', '登上尼尔盖德并控制它。抵御来自恐惧大厅的居民的攻击，直到恐怖博士现身。$B$B操纵尼尔盖德杀死恐怖博士，然后返回约尔达村，向白骨女巫复命。', '你发现了博士的阴谋，并且制止了他。$B$B<被女妖所控制的女巫笑了笑，轻轻的把手放在你的肩膀上。>$B$B你狠狠地戳了巫妖王一记，但是我想我们还能做得更好。', '你找到了博士的书，但是你没有用血肉巨人把他杀掉?$B$B在事情太迟之前快回去把他给杀掉!', '', '去冰冠冰川找约尔达村的白骨女巫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13045, '空中救兵', '我们会尽全力协助你，$N。始祖龙愿意载你飞越突破口，把你送到天灾城里。尽你的全力营救每一位被困的北伐军士兵，然后立即把他们送回位于基地中央的前线基地医护所。$B$B从我身后的围栏里挑选一头银色天爪龙，马上出发吧！$B$B天灾城就在西北边，穿过回音谷和突破口就到了。', '从天灾城营救3名被俘虏的银色北伐军士兵，把他们送往银色前线基地中心的医护所。完成任务之后，向大领主提里奥·弗丁复命。', '阿尔萨斯…他鲁莽地发动攻击 - 如此的轻率又毫无戒备之心。这下我们已洞悉他的弱点了。$B$B<大领主提里奥.弗丁停顿片刻，陷入沉思之中。>$B$B我们必须加强防御，熬过将至的突袭。$B$B你熟悉火炮的操作吗，$N?', '他们生还的机会，正随着时间一点一滴地流逝。', '', '去冰冠冰川找银色前线基地的大领主提里奥·弗丁。', '营救被俘虏的北伐军士兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13047, '清算之战', '洛肯杀害了我的妻子，让我的拥护者转而与我为敌。他夺走了我的一切，但是今天……一切都将改变。$b$b今天，我们将夺回曾经的圣地。今天……就是洛肯的死期。$B$B转至奥杜尔西南方的智慧神殿，到神殿附近的桥上与我碰面。无论如何，我要和洛肯做个了断。$B$B我要你见证这场复仇之战。你不要插手——这是私人恩怨。$B$B请你向冰霜巨人之王约库姆汇报战斗的结果。他是我的好朋友，他知道该怎么做。', '转至智慧神殿附近与托里姆碰面。然后向丹尼芬雷的约库姆国王汇报战斗的结果。', '不...这不可能...$B$B没人能在决斗中击败托里姆。巨人不能，野兽也不能...不可能有人!更不可能是他那个懦夫哥哥!$B$B我以先祖之名起誓...$B$B洛肯将为此付出代价!', '啊，$N!很高兴见到你，小伙子。', '见证清算之战', '去风暴峭壁找丹尼芬雷的约库姆国王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13048, '错误的时间流', '我们可以使用知识之锤修复损坏的时间流，但是必须首先找到历史是从哪儿开始被破坏的。$b$b从迅矛酋长提供的信息以及你在浮冰深渊的发现来看，时间流是在雷蹄死亡的时刻发生改变的。$B$B我要你转至营地北边的凛风洞窟，进入已经被北风的侍从破坏的墓地。知识之锤将与雷蹄时代的圣物产生反应，实现与正确时间流的同调。', '对牦牛人的圣物使用知识之锤，让它与雷蹄生活的时间流实现同调。等它与6件雷蹄时代的圣物完成同调之后，回去向唐卡洛营地的夏拉托尔复命。', '<札伦陶收下了你手上的博识之锤。>$B$B终于，我们正确无误地在历史上，标定了风暴之蹄的年代。根据这点，我们可以恢复时间线的旧观了。', '你将博识之锤调至风暴之蹄的时代了吗?', '', '去风暴峭壁找唐卡洛营地的夏拉托尔。', '将知识之锤与雷蹄所在的时间同调', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13049, '英雄的装备', '并不是营地中的所有记录都遭到了破坏。我的手下帮我找到了那些能够反映真实时间流的记录。$B$B这些证据表明，雷蹄和村落中的长者一样，被埋葬在北边的凛风洞窟底层。$B$B北风的侍从早已将墓地破坏殆尽，还夺走了墓穴主人的陪葬品。我要你转至凛风洞窟，看看能否从那些强盗手中夺回雷蹄的武器和盔甲。', '将雷蹄的长矛和雷蹄的锁甲交给唐卡洛营地的夏拉托尔。', '你果然没有辜负我的期望，$N。有了它们，我就可以使用博识之锤，将你送回过去，到北风精灵开始败坏时间线的时候。这是我们复原此地历史的唯一机会。', '你找到风暴之蹄的武器与铠甲了吗?', '', '去风暴峭壁找唐卡洛营地的夏拉托尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13050, '维拉努斯', '要想对洛肯的军队发动攻击，我就必须找到可以让我灵活行动的方法。$B$B多年前，我将飞龙坐骑维拉努斯放归了大自然。她曾伴我征战四方，如今早已重登族群女王的宝座。$B$B我觉得我们很难找到她，不过有个法子或许能奏效。维拉努斯早已过了繁殖的年龄，但是她依然待在空空如也的巢穴里。这位名义上的族群女王以此维系着她高贵的尊严。$B$B从布伦希尔达村附近的其它巢穴中取回一些小龙卵，我再告诉你接下来要怎么做。', '风暴神殿的托里姆要你从布伦希尔达村附近的峭壁上取回5枚规模始祖龙卵。', '对了...这就对了。希望我的计画可行，$N。$B$B维拉努斯满强悍的，我可不想为了头小龙，费心安排这一切。', '你弄到蛋了吗，$N?', '', '去风暴峭壁找风暴神殿的托里姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13055, '洞穴中的药品', '终于看到一张友善的面孔了，或许也是我所看到的最后一张面孔呢。$B$B我不小心被冰虫蜇了，毒素流遍了我的全身。我可以感觉到自己的整个身体都在逐渐失去知觉。$B$B我需要一只冰虫的毒腺来制造解毒剂，另外还需要一些生长在这里的洞穴蘑菇……它们可以延缓毒素的蔓延。$B$B快一点，拜托了。我坚持不了多久。', '基莫拉克之巢的猎户瓦尔兹希望你去收集1个冰虫毒腺和8只洞穴蘑菇。', '感谢你，我的朋友。我见得到明天的太阳了。', '你...回来了，朋友?', '', '去风暴峭壁找基莫拉克之巢的猎户瓦尔兹。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13058, '改变风向', '万事俱备，我们可以纠正北风和他的侍从犯下的错误了。你已经将知识之锤与雷蹄以及他生活的时间流实现了同调。$B$B现在，我要你带上它转至西北方的平原上的生命神殿，在那里使用知识之锤，以雷蹄的身份挑战北风。你要记住，为了让时间流恢复正常，雷蹄必须在北风变得虚弱时死去。$B$B接着，你要找到并使用元素愤怒号角，消灭北风。', '使用知识之锤回到过去，以雷蹄的身份挑战北风。雷蹄倒下之后会掉落元素愤怒号角，届时你必须使用元素愤怒号角击败北风，然后返回唐卡洛营地，向夏拉托尔复命。', '你今天的所作所为，将使风暴之蹄与其事迹永载青史。同时，你也使自己名留于艾泽拉斯史册之中。我将缅怀你，并记载你不朽的成就。', '你完成任务了吗?时间线回复原状了吗?', '', '去风暴峭壁找唐卡洛营地的夏拉托尔。', '修复正确的时间流', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13059, '瓦古的复仇', '我一直在向利剑女神祈祷，希望有一位英雄能挺身而出，帮助我消灭仇敌。$B$B伊尔斯卡领主必须为他的罪行付出代价！$B$B我曾是强大的乌弗朗领主麾下的第一勇士，如今却只残留一具空洞的躯壳。在瓦哈拉斯的战斗中，伊尔斯卡利用黑暗的魔法暗中捣鬼，让我输掉了战斗，导致我沦为现在的模样。$B$B伊尔斯卡领主和他手下的勇士就在受难之环中。代表我向他发起挑战并击败他。$B$B让他明白我承受了怎样的痛苦！', '地下大厅的贝索德·菲格要你扔出他的剑，在受难之环中挑战并杀死伊尔斯卡领主。', '谢谢你，$C...谢谢你!$B$B让我沦落至斯的懦夫，将和我一样，永远地腐朽，这个讯息令我感到莫大的满足。$B$B现在，马上离开，在我还没失去控制并把你大卸八块之前。', '我感觉到你尚未击败伊尔斯卡族长。有什么阻碍了你吗?', '', '去找冰冠冰川地下大厅的贝索德·菲格。', '使用贝索德的剑发起挑战', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13064, '骨肉相残', '西芙？真的是你吗？$B$B哦？怎么是个$r？刚才我还以为……$b$b够了！我心爱的西芙……她的幻象折磨我实在太久了。是时候为她报仇、以荣耀来纪念她了。$B$B我的兄弟必须付出代价！', '托里姆希望你能倾听他的故事。', '现在你稍微了解到这片土地…我的土地的历史。我要求你协助我拨乱反正。', '听到我说的话了吗，$r?', '', '去风暴峭壁找风暴神殿的托里姆。', '聆听托里姆讲述他的往事', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13069, '把它们打下来！', '维库人凭借始祖龙骑兵和鱼叉炮，在尤顿海姆构筑了固若金汤的防御体系。他们将这些防御设施集中部\r\n署在尤顿海姆最为薄弱的北面和西面。$B$B我们正好可以利用他们的防御设施来对付他们！$B$B<跳跃者用他的独眼死死地盯着你，发出邪恶的笑声。>$B$B转至西南方的瓦哈拉斯，登上维库人搭建在悬崖上的平台，随意控制一尊鱼叉炮，击落那些始祖龙和它们的骑手！', '暗影拱顶的跳跃者要你使用尤顿海姆速射鱼叉炮，击落15头尤顿海姆始祖龙以及它们的骑手。', '你是真正的王牌，$N!你明天可以再回来一回吗?我相信一定有更多淘气的小元龙，等着你给它个痛快。', '啧啧...你还没射下今天应有的配额!', '', '去冰冠冰川找暗影拱顶的跳跃者。', '击落尤顿海姆的始祖龙以及它们的骑手', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13071, '维尔喜欢火焰！', '维尔喜欢火焰！维尔喜欢始祖龙！$B$B<这个憎恶兴奋地拍着双手。>$b$b$N，你去尤顿海姆，从约尔达村偷一条漂亮的始祖龙吧。让始祖龙喷出的烈焰在尤顿海姆燃起大火！', '暗影拱顶的劣尸维尔要你偷得一头约尔达始祖龙，用它焚毁尤顿海姆的8幢维库人建筑物。$B$B不过，你无法焚毁坚固的巴拉加德堡垒。', '嘿嘿!$N真是元龙神偷。$B$B你明天再回来嘛，咱们可以制造更华丽的烟火秀!!!', '什么?暗邪还没看到华丽的烟火秀!!!$B$B$N回去，然后制造更多火光!', '', '去冰冠冰川找暗影拱顶的劣尸维尔。', '点燃维库人的建筑物', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13074, '翡翠噩梦中的希望', '我们需要的东西只有在翡翠梦境才能找到……那是一种蕴含着强效恢复魔法的橡果。在这片神圣的林地里，许多地方都与翡翠梦境紧密相连，我的神殿也是其中之一。$B$B我要把你送入梦境去收集一些橡果。但是你也要做好准备，因为以这样的方式进入梦境是很危险的，你很可能被梦魇包围。$B$B你要赶快拿到橡果，然后跨出我的神殿，或者打自己一拳，这样就可以返回我们的世界了。', '月光林地的守护者雷姆洛斯要你进入翡翠梦境，获取3枚翡翠橡果。$B$B跨出雷姆洛斯神殿的范围就可以回到艾泽拉斯世界。', '干得好，年轻人。', '见到你安然无恙真好。你取得橡实了吗?', '', '去月光林地找月神湖的守护者雷姆洛斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13075, '雷姆洛斯的恩赐', '我会打开传送门，将你送回冰冠冰川的大德鲁伊身边。我祝福你和那位北伐军圣骑士，希望这颗橡果可以净化他，将他从瘟疫中解救出来。$B$B再见，$r。', '将翡翠橡果交给冰冠冰川沉默墓地的北伐军战士布雷登布莱德。', '提里奥派你去找雷姆洛斯?我...我简直感动得不能自己。凡人实在不值得获得如此强大的协助，无论是多么尊贵，多么无私的人。你真是个好人，为了我跋涉了那么长的距离。请接受我由衷的谢意。$B$B植下橡实吧 － 我准备好了。', '你好，$C。我就知道你会回来，尽管我已警告你，但我很高兴你听从了我的话，不让其它人暴露于染病的风险之中。$B$B你为什么回来呢?', '', '去冰冠冰川找沉默墓地的北伐军战士布雷登布莱德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13078, '达莉亚之泪', '在这黑暗的时代，我绝不能抛弃圣光的勇士。$B$B我们需要一些神圣的对象，才有可能拯救布雷登布莱德……唯有感染过亡灵瘟疫，并且已经重获新生的虔诚生灵才具备免疫这种侵蚀的能力。$B$B我要你进入红玉巨龙圣地。我的红玉看守者曾以烈焰灼烧过那片被亡灵踏足的土地，你会发现新的生命已经开始生长。将那些正在茁壮生长的达莉亚之泪带回来给我。', '龙眠神殿的阿莱克丝塔萨要你从被红玉看守者的烈焰净化过的土壤里取得达莉亚之泪。', '有了妲莉雅之泪和古老的魔法，我可以赋予你，拯救伟大十字军战士的一丝希望。', '啊，亲爱的妲莉雅。我多么地想念你。', '', '去龙骨荒野找龙眠神殿的阿莱克丝塔萨，生命的缚誓者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13079, '阿莱克丝塔萨的恩赐', '你必须明白，年轻的$r，我的能力仅限于净化躯体以促成新生……要在不影响肉体的前提下解除亡灵瘟疫，却已经超越了我的能力范围。$B$B如果布雷登布莱德真的像你所说的那样虔诚，他或许能通过净化的考验，获得新生。但是，我不确定这是否就是你所寻找的救赎之道。带着它和我的祝福上路吧。', '将阿莱克丝塔萨之息交给冰冠冰川沉默墓地的北伐军战士布雷登布莱德。', '阿莱克丝塔萨之息...你去找龙后本人?言语无法表达我心中感激之万一。$B$B我了解净化的风险，也已经做好准备。动手吧，$C。', '你又回来了，$C。为什么你要一再地涉险?', '', '去冰冠冰川找沉默墓地的北伐军战士布雷登布莱德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13083, '黑暗中的光明', '<北伐军战士布雷登布莱德的战袍放在箱子底部。呼啸的寒风掠过时，战袍微微拂动起来。>$B$B提里奥一定很希望留下这位伟大的北伐军圣骑士最后的遗物。', '将布雷登布莱德的战袍交给北伐军之峰的大领主提里奥·弗丁。', '我很高兴你拯救了他，让他不致成为不死邪物。有了阿达欧的祝福，他知道在他死后，邪恶的阴影将无法如影随行。$B$B我们会牢记他的精神，还有你无私的义行。再一次感谢你，为了你所做一切。', '他已逝去，是吗?我感觉得到，这块大陆上的光明又黯淡了一些。', '', '去冰冠冰川找北伐军之峰的大领主提里奥·弗丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13084, '破坏尤顿海姆', '我们来瞧瞧能否进一步打击维库人的信心，$N。$B$B我希望你每天都去尤顿海姆跑一趟，烧毁他们的旗帜。这虽说是件小事，但是维库人很快就会发现，他们的世袭之地每天都在遭到破坏和侮辱。我相信这比肉体伤害来得更痛苦，一定能狠狠地打击他们的士气。$B$B至少……你也没什么损失嘛。', '暗影拱顶的兰克拉尔公爵要你烧毁10面维库人旗帜。', '<公爵盯着你一会，然后点了点头。>$B$B你给卓顿海姆的维库人带来了可怕的心理创伤。这是他们最先被想到之处。这地方对他们而言，是无与伦比的，其重要性仅次于依米海姆。$B$B你应该继续对此处施加压力，而我要守住这座穹殿抵抗巫妖王的攻势。', '你有更多活得干罗。', '', '去冰冠冰川找暗影拱顶的兰克拉尔公爵。', '烧毁维库人的旗帜', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13086, '最后一道防线', '前线基地已经启动防御方案，$c！基地中的四座塔楼顶层分别安置着一门可伸缩的银色北伐军火炮，它们都得到过古斯塔夫神父的祝福。我要你飞到塔楼顶层去操纵火炮，用它摧毁巫妖王麾下的天灾军团部队。$B$B你只需注意一点：天灾军团肯定会派出冰霜巨龙来围攻塔楼，你必须击落这些野兽！如果巨龙摧毁了基地的城墙和塔楼，我们就完蛋了！', '使用银色火炮消灭100名天灾军团攻击者和3条霜巢毁灭者。$B$B完成任务后向攻城大师菲斯克复命。', '你操炮的技术简直就像个哥布尔炮手，我的朋友。你拯救了先锋驻地和银色北伐军 - 彷佛大领主本人就在战场上一般!真惊人!', '那些垂死的嘶吼老是令我不快!给他们个痛快!', '', '去冰冠冰川找银色前线基地的攻城大师菲斯克。', '杀死天灾士兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13087, '诺森德的厨师', '你有东西吃吗？我快饿死了！至少给我弄点冰冷的肉来吧，这样我就能自己做些诺森德炖肉了！如果你能帮我弄来一些冰冷的肉，我就教你怎么做炖肉，这样你也能自己炖肉吃。现在就去给我弄些肉来！', '将4块冰冷的肉交给瓦加德的布罗姆。你可以在诺森德的任意野兽身上找到冰冷的肉。', '你给我弄来了肉!食谱拿去，我得煮饭了!', '我的肉在哪!!', '', '去嚎风峡湾找瓦加德的布罗姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13088, '诺森德的厨师', '我们这里来了很多新兵，这些家伙都还饿着肚子呢！如果你能去帮我弄些冰冷的肉，我就可以做一些诺森德炖肉了，当然，我也可以教你炖肉的方法。', '将4块冰冷的肉交给无畏要塞的罗里克·玛克雷尔。你可以在诺森德的任意野兽身上找到冰冷的肉。', '这下可以喂饱咱们的新兵了!来，这是烹调的方法。', '这些孩子们需要煮炖肉的肉块。', '', '去北风苔原找无畏要塞的罗里克·玛克雷尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13089, '诺森德的厨师', '没有什么能比用新鲜的肉烹制而成的诺森德炖肉更能让你感到暖和了。从那些凶猛的野兽身上弄些冰冷的肉来，我会教你怎样做出热腾腾的诺森德炖肉。', '将4块冰冷的肉交给复仇港的托马斯·克里奇。你可以在诺森德的任意野兽身上找到冰冷的肉。', '我们立刻就能把这堆生肉变成香喷喷的炖肉。', '炖肉在等着呢…', '', '去嚎风峡湾找复仇港的托马斯·克里奇。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13090, '诺森德的厨师', '战歌要塞的士兵需要吃饱喝足才能保持充沛的体力。如果你能从犀牛或者其它野兽身上收集一些冰冷的肉，我就可以给他们做些诺森德炖肉。而且，如果你乐意的话，我也很愿意教你学会烹制这道菜的方法。', '将4块冰冷的肉交给战歌要塞的奥恩·嫩蹄。你可以在诺森德的任意野兽身上找到冰冷的肉。', '我向你致谢。', '只要有肉块，炖肉就准备好了。', '', '去北风苔原找战歌要塞的奥恩·嫩蹄。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13091, '恐怖之水', '洞穴外面的水牢里塞满了尚未被维库人法师驯服的元素生物。我可以教你一个办法，让你在短时间内控制这些生物，接着你就可以利用它们破坏尤顿海姆！$B$B<被女妖附身的维库人从空气中汲取魔法，然后将她硕大的手指点在你的前额。>$B$B去吧，打开水牢。控制一只恐怖之水，利用它消灭我们的敌人！', '约尔达村的白骨女巫要你控制一个恐怖之水，利用它杀死尤顿海姆地区的10名维库人。$B$B尤顿海姆休眠看守者、尤顿海姆战士、尤尔丁控水师、约尔达女矛手和瓦哈拉斯行尸都符合要求。', '我从未在维库人的眼中看到如此的恐惧。他们以为可以掌握他们自己的小世界。$B$B我们这就要证明他们错了。错得离谱。', '我对骸骨的解读显示，你还没完成你的工作。', '', '去冰冠冰川找约尔达村的白骨女巫。', '控制恐怖之水并杀死尤顿海姆维库人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13092, '占命卜运', '占据这名维库人的好处之一就是，我可以使用她的全部力量。作为一名女巫和符文解读者，她可以通过抛掷徽记来决定别人的命运。$B$B<女巫露出得意的笑容。>$B$B幸运的是，我有能力左右占卜的结果。$B$B我要你去尤顿海姆干掉一些维库人，把他们的徽记带回来给我。我可以抛掷徽记，让你决定自己的命运。', '约尔达村的女巫要你去收集15个维库人的徽记。', '现在，我们该看看未来有什么在等着你。$B$B<骸骨女巫将骸骨放在她面前的毯子上。>$B$B选择你的命运吧，$C。', '我有个有趣的发现，这支族群曾经支配过整个世界，当他们使用如此原始的魔法时。', '', '去冰冠冰川找约尔达村的白骨女巫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13093, '占命卜运', '', '', '选择你的命运吧，$N。', '带给我更多的维库骸骨，我们就能依你首选，操控你的命运。', '', '去找冰冠冰川的白骨女巫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13094, '他们丝毫不感到羞愧吗？', '大法师伯林纳德是肯瑞托之中对玛里苟斯的研究最深入的人。他一生都在对玛里苟斯和他的行为进行研究。$B$B前不久，他把他的研究笔记借给了我，上面记载着玛里苟斯正在试图绘制的某种被称为“魔网地图”之类的东西。但我犯了一个错误……我在跟一群借地落脚的部落冒险者聊天的时候说起了这本笔记——现在它消失了！$B$B一定是他们干的，$c。请进入魔枢，在伯林纳德向我要回研究笔记之前帮我把它找回来。', '图书馆员塞尔拉希望你进入魔枢，找回伯林纳德的研究笔记。', '你找到了!?哦是的，东西都在这儿了。$B$B请容我表达谢意。如果可以的话，贝瑞那德最好别知道这件事。', '拜托，$N，告诉我你找到贝瑞那德的研究书了……', '', '去北风苔原找永生之盾的图书馆员塞尔拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13095, '他们丝毫不感到羞愧吗？', '大法师伯林纳德是肯瑞托之中对玛里苟斯的研究最深入的人。他一生都在对玛里苟斯和他的行为进行研究。$B$B前不久，他把他的研究笔记借给了我，上面记载着玛里苟斯正在试图绘制的某种被称为“魔网地图”之类的东西。但我犯了一个错误……我在跟一群借地落脚的联盟冒险者聊天的时候说起了这本笔记——现在它消失了！$B$B一定是他们干的，$c。请进入魔枢，在伯林纳德向我要回研究笔记之前帮我把它找回来。', '图书馆员塞尔拉希望你进入魔枢，找回伯林纳德的研究笔记。', '你找到了!?哦是的，东西都在这儿了。$B$B请容我表达谢意。如果可以的话，贝瑞那德最好别知道这件事。', '拜托，$N，告诉我你找到贝瑞那德的研究书了……', '', '去北风苔原找永生之盾的图书馆员塞尔拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13096, '迦尔达拉之死', '你见过那场面吗，伙计？$b$b这是我见过的最可怕的事情了。伟大的阿卡里……在我面前被杀死了。真是太恐怖了……$b$b我曾发誓永远不会参与实际的行动，只是负责观察而已。但我实在是无法忍受了！迦尔达拉必须得到惩罚！$b$b请你进入古达克，把他找出来。当你为阿卡里复仇之后再回来见我。', '杜布拉金的托玛尔要你杀死古达克的迦尔达拉。', '你成功了?!迦尔达拉死透了?$B$B拿去吧，老兄。把这个当作你制裁那个废物的奖赏。', '阿卡里的仇报了没有，$r?', '', '去祖达克找杜布拉金的托玛尔。', '杀死迦尔达拉', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13098, '前车之鉴', '古达克注定要遭受复灭的命运，朋友。$b$b历史总是不断重复。当巨魔将矛头指向自己的神灵时，毁灭就已经注定了。这只是一个时间问题。$b$b如果我们能把这些事件清晰地记录下来，或许能阻止后人重蹈复辙。$b$b如果你足够勇敢的话，就请你进入古达克，搜寻达卡莱帝国没落至此的原因。', '杜布拉金的记载者拜基妮要你进入古达克，收集6份达卡莱历史石板。', '<巴琪妮花了一点时间检视这些刻了文字的石板，然后将注意力转回你身上。>$B$B这些都是真品，$r。我会将他们纳入我收集的文本中。$B$B也许我们未来能够制止这样的行为。', '你找到达卡莱历史石板了吗，老兄?', '', '去祖达克找杜布拉金的记载者拜基妮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13100, '魔法蘑菇肉片', '我们手上有一份重要的订单！摩尔珍品店的奥尔顿·本内特点了一份蘑菇肉片。$B$B到达拉然下水道里去，采集几枚魔法蘑菇，然后把它们跟一些冰冷的肉放在一起烘烤，做好之后立即把它给奥尔顿送去。', '将2块冰冷的肉和采自达拉然下水道的4枚魔法蘑菇放在你的煎肉锅中，烹制成一份魔法蘑菇肉片，然后将其带到达拉然的鲁因广场，交给摩尔珍品店中的奥尔顿·本内特。', '这看起来真不错!谢谢!', '你给我带了什么吃的吗？$B$B我从没能离开过这个商店，哪怕一分钟。', '', '去达拉然找摩尔珍品店的奥尔顿·本内特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13101, '魔术旅馆的集会', '魔术旅馆的埃里雷正在筹备一场集会，还要摆出筵席来款待他的客人！$B$B你要为他准备一些诺森德炖肉和一壶来自达拉然市中心的“再来一杯”奶酪店的酒，那里的店主欠我一瓶酒，你应该可以在奶酪店里的某处找到酒。$B$B把酒和炖肉一起交给埃里雷。', '将4份诺森德炖肉和从一壶达拉然的奶酪店中取来的葡萄酒带到达拉然的鲁因广场，交给魔术旅馆中的埃里雷。', '对每个人而言，这样的份量都算是丰盛的大餐吧!我想他们会满意的。', '我的餐点来了吗，会议的参加者随时都会到啊!', '', '去达拉然找魔术旅馆的埃里雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13102, '下水道炖肉', '达拉然下水道的旅店中食物短缺，该店的老板埃因·格林需要一份萝卜炖肉来款待他的顾客。$B$B到晶歌森林去采集4根晶歌胡萝卜，把它们和4块冰冷的肉一起炖了。$B$B你可以通过鲁因广场东边的传送间转至晶歌森林。$B$B等你准备好了萝卜炖肉之后，就把它交给埃因。', '将4根采自晶歌森林的晶歌胡萝卜与4块冰冷的肉放在炖肉锅里进行烹饪。$B$B炖好之后，将萝卜炖肉交给达拉然下水道的旅店老板埃因·格林。', '炖菜看来还不错。谢啦。', '你最好给我确定，这回炖菜里面没有任何和地精有关的东西!', '', '去达拉然找咒语和乌鸦旅店的埃因·格林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13103, '兰尼德的奶酪', '达拉然制皮店的兰尼德·怒金突然对酒和奶酪产生了兴趣。$B$B从达拉然市中心的“再来一杯”奶酪店收集一些没人要的奶酪，然后在城中的随便什么桌子上找一些半满的酒杯。把酒混在一起倒进瓶子，然后把它和奶酪一起交给兰尼德。$B$B我不觉得他会发现任何问题。', '把空的奶酪盘、“再来一杯”奶酪店的陈年达拉然干酪、以及在达拉然的桌子上找到的6只半满的达拉然酒杯放在一起。$B$B将美酒和奶酪盘交给魔法商业区制皮店中的兰尼德·怒金。', '这酒超正点的!我一定要知道它是哪来的。', '你有看到应该送起司和酒来给我的外送小弟吗?我超饿的!', '', '去达拉然找传说皮甲的兰尼德·怒金。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13107, '荠菜热狗！', '大法师伯塔鲁斯正准备去观看他最喜爱的战球比赛，不过他需要一些供旅途中享用的食物。$B$B你要准备4份犀牛热狗，然后从达拉然的草地上摘4片野荠菜，把它们放进他的午餐篮里。$B$B把午餐篮交给他，这样他就可以出发去观看精彩的比赛了。', '在空午餐篮里装入你烹制的4份犀牛热狗，外加你在达拉然草地上找到的4片野芥菜。$B$B将芥菜热狗篮交给达拉然城克拉苏斯平台的大法师伯塔鲁斯。', '太棒了!现在我只希望，能看到达拉然破坏者队赢球!', '我几乎准备好要出发了，只差我和我家人的午餐...呃...我的法师同事来了。', '', '去达拉然的克拉苏斯平台找大法师伯塔鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13108, '不惜代价！', '无论如何，洛肯一定要死。$b$b如果我不得不亲手撕碎他，那么他很快就会为自己的恶行付出代价。$b$b若是你碰巧赶在我前面遇到他，击败他的荣耀就全归你了。$b$b把他的信物带给我，我会祝福并感谢你的。', '丹尼芬雷的约库姆国王要你进入闪电大厅并击败洛肯，然后将洛肯的信物带回去给他。', '那畜牲死了?$B$B你赐给我的子民无比的恩惠，小$r。$B$B请收下这份礼物，作为你忠诚友谊的回报。', '洛肯得到正义的制裁了吗?', '', '去风暴峭壁找丹尼芬雷的约库姆国王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13109, '势不两立', '我要坦白告诉你，小$r。自从我们与托里姆的盟约破裂后，我的族人已经变了。$b$b作为他们的首领，我最希望他们心灵的创伤能够愈合，我们与风暴之王的友谊能够恢复。在你击败弗约恩之后，我们已经向这个目标迈进了一大步。我要请你帮助我们更进一步……$b$b有一个比弗约恩更强大的敌人住在闪电大厅里，他威胁到了我们的生存。沃尔坎和我们之间，只有一个能活下来。', '丹尼芬雷的约库姆国王要你进入闪电大厅，击败沃尔坎。', '渥克瀚不会再如同鬼魅般，萦绕在我的子民梦中了。$B$B加紧你的脚步，小$r。早晚，我的子民必定会宽恕托里姆。', '渥克瀚挂了吗，小$r?', '', '去风暴峭壁找丹尼芬雷的约库姆国王。', '击败沃尔坎', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13110, '永不安息的亡者', '并非所有的北伐军战士都活着走出了天灾城。很多人被杀害了，变成了扭曲的怪物。这就是天灾军团的行事方法。被诅咒的灵魂永远也无法享受安宁，除非我们想办法让他们安息。$B$B穿过突破口，进入天灾城，杀死那些被天灾军团复活的北伐军战士。然后将圣水撒在他们的骸骨上，以此解放他们的灵魂。', '冰冠冰川回音谷的古斯塔夫神父要你对复活的北伐军战士的尸体使用圣水，解放10个永不安息的灵魂。', '对这些正直的十字军而言，他们的路途上充满了不公与邪恶。杀戮是对他们唯一的救赎。你今天做到了，而且拯救了比我预期的更多人。', '这是个艰难的工作，$N，但它必须被完成。', '', '去冰冠冰川找回音谷的古斯塔夫神父。', '解放永不安息的灵魂', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13111, '独一无二', '听着，朋友。$b$b乍听之下，这仿佛是个老套的故事：巨魔杀死了他们所崇拜的强大神明，获得了禁忌的力量。$b$b这确实是真的，但是这些达卡莱巨魔有些特殊。如果我得到的情报属实，古达克里面的某个地方有一台魔像——独一无二的魔像！$b$b朋友，你喜欢冒险吗？到古达克去吧，帮我从那台魔像身上弄一块碎片下来。我想研究一下。', '杜布拉金的记载者拜基妮要你进入古达克，获取一块达卡莱巨像的碎片。', '啊呀我的妈!那就是我要的。$B$B喏，随你拿吧，拿点什么去解决你的麻烦。', '你帮我弄回那魔像的碎片了吗，老兄?', '', '去祖达克找杜布拉金的记载者拜基妮。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13112, '魔法蘑菇肉片', '摩尔珍品店的奥尔顿·本内特点了一份蘑菇肉片。$B$B到达拉然下水道里去，采集几枚魔法蘑菇，然后把它们跟一些冰冷的肉放在一起烘烤，做好之后立即把它给奥尔顿送去。$B$B如果议会允许我供应侏儒特色菜的话，我一定要让他们看看什么才是真正的美味！', '将2块冰冷的肉和采自达拉然下水道的4枚魔法蘑菇放在你的煎肉锅中，烹制成一份魔法蘑菇肉片，然后将其带到达拉然的鲁因广场，交给摩尔珍品店中的奥尔顿·本内特。', '这是埃维罗做的？你能保证里面没藏着侏儒吗？', '你给我带了什么吃的吗？$B$B我几乎从没离开过这个商店。', '', '去达拉然找摩尔珍品店的奥尔顿·本内特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13113, '魔术旅馆的集会', '你能相信吗？部落竟然宣布吃人是非法的……我告诉你，这是不对的！不过，在有订单的时候，我还是应该把注意力放在完成订单上。$B$B魔术旅馆的埃里雷那里来了许多客人。你要向他提供一些诺森德炖肉和一壶来自达拉然市中心的“再来一杯”奶酪店的酒。$B$B把酒和炖肉一起交给埃里雷。', '将4份诺森德炖肉和从一壶达拉然的奶酪店中取来的葡萄酒带到达拉然的鲁因广场，交给魔术旅馆中的埃里雷。', '我的客人应该还可以接受。只要别告诉他们是阿维罗做的就行。', '我的食物在哪里?客人马上就要来了!', '', '去达拉然找魔术旅馆的埃里雷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13114, '下水道炖肉', '我们又有订单啦，达拉然下水道的旅店老板需要一份萝卜炖肉来款待顾客。$b$b由于他并不满意上一次我送去的炖侏儒，这次他特意要了一份萝卜炖肉。到晶歌森林去采集4根晶歌胡萝卜，把它们和4块冰冷的肉一起炖了。$B$B你可以通过鲁因广场东边的传送间转至晶歌森林。$B$B等你准备好了萝卜炖肉之后，就把它交给埃因。', '将4根采自晶歌森林的晶歌胡萝卜与4块冰冷的肉放在炖肉锅里进行烹饪。$B$B炖好之后，将萝卜炖肉交给达拉然下水道的旅店老板埃因·格林。', '炖菜看来还不错。谢啦。', '你最好给我确定，这回炖菜里面没有任何和地精有关的东西!', '', '去达拉然找咒语和乌鸦旅店的埃因·格林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13115, '兰尼德的奶酪', '制皮店的兰尼德·怒金需要酒和奶酪。为什么他不想尝尝我这里的美味侏儒呢？$B$B从达拉然市中心的奶酪店中收集奶酪，然后从城市各个角落收集一些半满的酒杯。把酒和奶酪一起交给兰尼德。$B$B你可以把这酒称作“混合美酒”，朋友。', '把空的奶酪盘、“再来一杯”奶酪店的陈年达拉然干酪、以及在达拉然的桌子上找到的6只半满的达拉然酒杯放在一起。$B$B将美酒和奶酪盘交给魔法商业区制皮店中的兰尼德·怒金。', '这酒超正点的!我一定要知道它是哪来的。', '你有看到应该送起司和酒来给我的外送小弟吗?我超饿的!', '', '去达拉然找传说皮甲的兰尼德·怒金。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13116, '荠菜热狗！', '大法师伯塔鲁斯正准备去观看疯狂的战球比赛，不过他需要一些供旅途中享用的食物。$B$B你要准备4份犀牛热狗，然后从达拉然的草地上摘4片野荠菜，把它们放进他的午餐篮里。$B$B用美味塞满他的午餐篮吧，朋友。', '在空午餐篮里装入你烹制的4份犀牛热狗，外加你在达拉然草地上找到的4片野芥菜。$B$B将芥菜热狗篮交给达拉然城克拉苏斯平台的大法师伯塔鲁斯。', '太棒了!现在我只希望，能看到达拉然破坏者队赢球!', '我几乎准备好要出发了，只差我和我家人的午餐...呃...我的法师同事来了。', '', '去达拉然的克拉苏斯平台找大法师伯塔鲁斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13117, '它们从哪儿来的？', '下面的缝合场里聚集了大群巫妖王的爪牙，这帮不知疲倦的怪物正在夜以继日地制造憎恶和血肉巨人。$B$B不仅如此，骷髅构造体的数量也越来越多，大大加快了制造的速度。$B$B如果我们不能查明它们的来历以及高效作业的缘由，那么我们很快就会落败，连采取行动的机会都没有。我要你去东南方调查这些骷髅的来历。', '调查缝合场东部的召唤祭坛，然后返回黑色观察站，向黑暗骑士阿尔蕾汇报情况。', '<你将你在召唤祭坛的发现告诉了黑骑兵。>$B$B我老早就开始怀疑了。我们不能让这情况继续下去。我们的首要工作，是摧毁那些召唤祭坛，然后才是处理天灾军团在这里引起的混乱。', '你找到那些骷髅的来源了吗?', '', '去冰冠冰川找黑色观察站的黑暗骑士阿尔蕾。', '调查召唤祭坛', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13118, '净化天灾城', '天灾军团对银色北伐军发动了数次攻击，但是都被击退了。眼下他们正在进行“生产部队”的勾当。天灾城中的俘虏全都会被处死，然后复活成巫妖王的仆从。$B$B毫无疑问，银色北伐军会请求你让他们的战士体面地死去，但是我不会对你提出这样的要求。要想获得胜利，我们必须毫不留情地杀死所有天灾军团的成员。$B$B穿过突破口，转至西北方的天灾城，消灭所有胆敢阻挡你的去路的家伙。', '冰冠冰川回音谷的黑锋观察者要你去杀死3名遗忘深渊高阶祭司、3只遗忘深渊虫王和8名复活的北伐军战士。', '干得好，$N。削减敌人的数量，能给银色北伐军宝贵的时间，以创建一座基地。', '别白白耗费时间，$N。', '', '去冰冠冰川找回音谷的黑锋观察者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13119, '摧毁祭坛', '这么说，他们在祭坛中召唤劳工和战士？$B$B我们必须先解决这件事。召唤大师手中应该有一根法杖，用来激活传送门。如果你能杀死他并夺取那根法杖，就可以利用它使传送门过载，最终摧毁祭坛。$B$B把四座召唤祭坛都搞定，然后回来向我复命。', '杀死召唤大师扎洛德，用他的法杖摧毁第一座、第二座、第三座和第四座召唤祭坛。完成任务后返回黑色观察站，向黑暗骑士阿尔蕾复命。', '<黑骑兵亚尔利点点头，表示认同。>$B$B很好。现在，我们可以专注于破坏血肉作坊的其它部分。', '召唤祭坛都被摧毁了吗?', '', '去冰冠冰川找黑色观察站的黑暗骑士阿尔蕾。', '摧毁第一座召唤祭坛', '摧毁第二座召唤祭坛', '摧毁第三座召唤祭坛', '摧毁第四座召唤祭坛');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13120, '死亡的凝视', '缝合场是一处庞大的工地，我们很难对所有情况一览无馀，不过好在我已经想到了一个办法。$B$B<阿尔蕾从斗篷里取出一枚宝珠。>$B$B这是死亡凝视宝珠。有了它，我们就可以观察天灾军团的动向，寻找最佳的进攻时机。$B$B将这些宝珠放置在缝合场三处关键位置的支架上——西南方的憎恶装配台和血肉巨人装配台，以及西方那口巨大的绿色瘟疫之锅附近。', '使用死亡凝视宝珠，将宝珠放置在憎恶装配台宝珠支架、血肉巨人装配台宝珠支架和瘟疫之锅区域宝珠支架上，然后返回黑色观察站，向黑暗骑士阿尔蕾复命。', '<黑骑兵亚尔利闭上双眼，似乎正凝神于某件遥远的事物上。>$B$B透过死亡之眼，我看到了我们的敌人。有了这些情报，我们将彻底地毁灭他们。', '你将宝珠都安置好了吗?', '', '去冰冠冰川找黑色观察站的黑暗骑士阿尔蕾。', '在憎恶装配台放置宝珠', '在血肉巨人装配台放置宝珠', '将宝珠放置在天灾之锅区域', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13121, '巫妖王之眼', '接下来，我们必须借助巫妖王的工具才能制定出对付他的下一步计划。$B$B越过西南方的山岭，就能抵达库尔加拉要塞。那里居住着尤顿海姆的神谕者，他们执行着主人的命令并通过巫妖王之眼监视他人。$B$B你必须设法靠近巫妖王之眼。虽然它不能穿透冰冠堡垒，但是我相信你能获取到有用的信息，这样我们就能制订出最佳的策略了。', '约尔达村的白骨女巫要你使用巫妖王之眼获取情报。', '非常好!原来远古英雄伊斯卡德的谣言是真的。而瓦德玛卓本人\r\n正要前去挑战他!$B$B如果我们想要抢先一步找到他的话，我们最好快一点!', '你竟然空手而归!我帮助了你和黑锋骑士团，这就是你回报的方式吗?$B$B离开我的视线，没弄到我要的情报就别回来!', '', '去冰冠冰川找约尔达村的白骨女巫。', '为白骨女巫收集情报', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13122, '天灾石', '天灾军团的成员在诞生或是被创造出来时，都会得到一块天灾石。它可以增强持有者的力量，更重要的是，军团的头目可以用它观测到所有作战单位的位置和行动。$B$B只要有足够多的天灾石，我们就能掌握天灾军团在冰冠冰川的一举一动。$B$B当你在天灾城中杀敌时，顺便收集一些天灾石吧。装满你的背包，然后再回来找我。', '将15块天灾石交给冰冠冰川回音谷的黑锋观察者。', '现在，让我看看，是不是能利用这些石头看到更多情报。', '天灾石能协助我们找到敌人。', '', '去冰冠冰川找回音谷的黑锋观察者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13125, '凝固的空气', '想要将这片土地从天灾军团手中拯救出来，就必须击败天灾城中的几位领主。$B$B撕裂者萨兰纳克斯驻守在天灾城第一层的神殿中，高阶祭司亚萨尔蒙就在第二层的灵魂塔里布道，而虫王塔洛诺克斯则负责管辖北边的邪魔之坑。$B$B他们非常强大，你必须小心应付。如果你需要帮助，就吹响这只号角。阿彻鲁斯的死亡骑士将闻声而来。', '冰冠冰川回音谷的黑锋观察者要你去杀死撕裂者萨兰纳克斯、虫王塔洛诺克斯和高阶祭司亚萨尔蒙。', '真是血战得来的胜利，$N!这些军官将会有人替换，但是，至少今天，围绕在天灾岸地周遭的空气是凝重的。', '作掉他们，$N!', '', '去冰冠冰川找回音谷的黑锋观察者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13126, '协同作战', '请接受我们的谢意，$r。$B$B我们被达库斯俘虏，而你和你的朋友成功地击败了他。不管怎样，让我们开始并肩作战吧。$B$B在我们上方，瓦尔洛斯躲在一道难以渗透的魔法护盾后面。为了击败他，你必须干掉那些向他的护盾提供能量的离心构造体。这也正是我们来到这里的原因……$B$B我们可以提供各自所属龙族的幼龙，供你们骑乘。你们必须凭借这些幼龙的帮助才能击败瓦尔洛斯。', '贝加里斯塔兹要求你摧毁10台离心构造体，以此关闭瓦尔洛斯的护盾。然后击败瓦尔洛斯·云击。', '一如我的期望，$r。我们合作无间。$B$B愿我们的持续合作能够克服前方的挑战!', '嗯，结束了!', '', '去魔环找贝加里斯塔兹的影像。', '摧毁离心构造体', '击败瓦尔洛斯·云击', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13127, '法师领主伊洛姆', '在我们达到最终的目标之前，只剩下最后一个障碍了——伊洛姆。$B$B伊洛姆在我们上方守护着第三道魔环，等待着我们发起攻击。朋友，你必须小心他强大的召唤法术。他是一个非常可怕的对手。$B$B打倒他，让他为自己的背信弃义付出代价！', '贝加里斯塔兹要求你击败魔环的法师领主伊洛姆。', '胜利近在咫尺，朋友。$B$B集中心神，因为真正的考验现在才开始。', '你解决法师领主伊洛姆了吗?', '', '去魔环找贝加里斯塔兹的影像。', '击败法师领主伊洛姆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13128, '龙翼之力', '与埃雷苟斯正面交锋的时候到了，朋友。$B$B他非常强壮而又狡猾，是玛里苟斯最信赖的手下，他的力量来源，正是他负责保卫的能量之井，也就是魔法龙神玛里苟斯提供的无尽力量。$B$B这可不是一场简单的战斗……$B$B不过，在法师领主倒下之后，我们的幼龙已经可以发挥全部的战力了。现在，他们的技能都可以供你使用。合理使用幼龙的技能，你们一定可以击败埃雷苟斯。$b$b等你获胜之后，就回去向莱洛拉斯报捷吧。', '贝加里斯塔兹要求你击败魔环的埃雷苟斯，然后回到考达拉的永生之盾，向莱洛拉斯复命。', '<瑞洛拉兹专注地听取你的报告。>$B$B$N，这是最好的消息。$B$B从这场冲突开始以来我们从未给予魔法之王如此的重击。$B$B朋友，请收下众龙军团的谢礼。', '你带来了关于贝加瑞斯塔兹的消息吗?', '', '去北风苔原找永生之盾的莱洛拉斯。', '击败魔网守护者埃雷苟斯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13129, '欺骗游戏', '他们实在是太懒了……等等！我知道该怎么教训他们一下了！$B$B<库塞尔从她的衣服上撕下一条布料交给你。>$B$B拿着这个，$c。把它拿到旁边那个讨厌的巫妖的尸体上抹一抹，然后回到营地去，把它交给马克。$B$B当这群家伙为他们的疏忽而自责时，我就会显身，让他们大吃一惊。$B$B他们要明白不能让女士独自外出的道理！', '库塞尔希望你对达克萨隆要塞的召唤者诺沃斯的尸体使用库尔基的布片。然后把沾满腐液的布片交给灰熊丘陵岩石之泉的马克。', '<麦客看着你，然后无法控制地大笑。>$B$B噢不…为什么她要乱跑，然后让自己挂掉呢?$B$B你知道的，我真该为她写首小歌。这可以让我打起精神来!$B$B<嗝>', '<嗝>$B$B你手上拿了啥啊，$g老哥:小妞;?', '', '去灰熊丘陵找岩石之泉的马克·菲尔森。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13130, '公正堡的基石', '当前天灾城还是腐臭肮脏的一片狼藉，但是总有一天，它会变成光辉荣耀的净土。弗丁大人下令将它改造成“公正堡”。$B$B嗯，哪怕是固若金汤的冰冠堡垒，也是由一小块石头开始建起的。那么，就让天灾城的救赎之路也从第一块石头开始吧！$B$B我要你转至南方的晶歌森林，抵达森林东部的自由之林后，在那里的灌木丛中收集水晶心木，再从杉达拉废墟中收集一些古代精灵石砖。', '冰冠冰川回音谷的北伐军建筑师西拉斯要你去收集10根水晶心木和10块古代精灵石砖。', '心材天生能抵御疾病、腐朽、和瘟疫。这些心材的确是有强健的抵抗能力，才能长得这么好!这些石艺，受到无缚灌木林影响，也有同样的效果。$B$B很快地，我们就能破土动工了。', '你迷路了吗?', '', '去冰冠冰川找回音谷的北伐军建筑师西拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13131, '宝箱中的垃圾', '看呐！我的钱箱从来没像现在这样空空如也过。本来我手里的财富足够把它装满十次了！$b$b我的同伴在看见那堆宝藏时都跳了起来，可是现在，你看看他们！他们都变成了骷髅！$b$b就像我妈妈对我说的那样——比没有财富更糟糕的事就是得到一堆被诅咒的财富。$b$b你瞧，那里有一大堆宝藏，而且没有受到诅咒，我向你保证。这些死鬼已经用不着它了——对他们来说，金钱和垃圾没什么差别。$b$b去帮我把它弄出来，我会好好酬谢你的，伙计。', '乌特加德之巅的布雷格要你帮他收集5块失去光泽的银锭、3枚闪亮的饰物、2只黄金酒杯和1座碧玉雕像。', '真不赖!你干得不错，小子。$B$B现在我面对上尉时，不必担心人头落地啦，多谢你和你的伙伴啦。$B$B这里是我的一点小心意。', '你进展如何，小子?', '', '去找乌特加德之巅的布雷格。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13132, '我要复仇！', '啊！这不是他们的错，小$g伙子:姑娘;。谁都会那么做的。$b$b他们扑向了那堆金子——以为自己发了大财，实际上也确实发财了。唉……可是现在，你看看他们。就像没头没脑的弱智一样，连一个金币都拿不起来。$b$b我比较幸运，没有遭受同样的命运。在扑向金币的路上，我摔了一跤——大约是有点喝醉了。结果呢，我抬头一看，就目睹了他们变成亡灵……$b$b帮个忙吧，$c，帮我找出这里的头儿，叫他知道，诅咒我的同伴，就要付出代价。', '乌特加德之巅的布雷格要你去杀死伊米隆国王。', '干得好!我的伙伴们可以安息了。$B$B这给你，$g小伙子:小女孩;。别让人说老布瑞格是个小气鬼，不肯给对他有恩的人适当的报酬。$B$B祝你好运。', '找到负责这里的家伙了吗，$r?让他吃了苦头了没?', '', '去找乌特加德之巅的布雷格。', '杀死伊米隆国王', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13133, '找到古代英雄', '$N，我要你立即转至西南方的先祖大厅！$B$B你可以在那里找到休眠的尤尔丁人。将他们逐个叫醒，直到你找到伊斯卡德尔为止。然后你要对他使用这枚护符，将他带回来见我。$B$B快去吧，时间非常紧迫！', '约尔达村的白骨女巫要你将伊斯卡德尔带回来。', '他是个很好的样品，而且将为我们所用。$B$B现在，我们得好好运用他，以诱捕瓦德玛卓!', '远古英雄在哪里?$B$B我可没闲工夫陪你扯淡。快去先祖大厅，把他带回来，否则就太迟了!', '', '去冰冠冰川找约尔达村的白骨女巫。', '将伊斯卡德尔带到白骨女巫面前', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13134, '抛洒它们的血', '要制造血肉怪物，天灾军团就必须用到大量的血液以及防腐剂，这样才能保存肢体，并确保其机能正常。如果破坏这些材料，它们的血肉怪兽就会四分五裂，那样我们就能轻松地摧毁它们了。$B$B在天灾军团装配血肉巨人和憎恶的台子周围，你可以找到装有防腐剂的大桶以及盛满鲜血的球体。摧毁这些材料，如果有谁敢阻拦你，就将它们一并除掉！', '黑色观察站的黑暗骑士阿尔蕾要你去摧毁5桶防腐液和5枚鲜血宝珠。', '<当你将结果回报给黑骑兵，他发出一阵阴沉而空洞的笑声，作为对你的回应及赞许。>$B$B你全身上下都充满了成功的气息，$N，那真是件好消息，真的。', '你完成我要求的工作了吗?', '', '去冰冠冰川找黑色观察站的黑暗骑士阿尔蕾。', '击碎鲜血宝珠', '摧毁防腐液桶', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13135, '危险的能量', '此地东南方，就在晶歌森林的东部边缘，有一处名叫自由之林的地方，里面生活着各种生物。受自由之林的影响，这些生物有一个共同点，就是它们对魔法能量的亲和力。它们体内拥有纯净的晶化能量，这种能量一旦爆发，其威力足以杀死我们所有人！$B$B转至自由之林猎杀这些生物，从它们身上获取结晶能量。我们需要燃料，而它们需要死亡，我们管这个叫“双赢”。', '冰冠冰川回音谷的北伐军技师斯比帕提克要你去收集8块结晶能量。', '啊，太棒了。是轰炸机该出动的时刻了，我们的时间不多。', '你得到晶化能量了吗?', '', '去冰冠冰川的找回音谷的北伐军技师斯比帕提克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13136, '粗糙的碎片', '你从食尸鬼的尸体上拔出了一块不规则的黑色金属碎片。它的边缘凹凸不平，说明锻造者的技术很差，又或者这是某个机械大件上的碎片。$B$B你突然想起，缝合场的食尸鬼尸体上都能找到相似的碎片。你很好奇，为什么它们的制造者要不厌其烦地加入金属碎片呢？如果你能多收集一些这种碎片的话，或许北伐军战士欧尔拉金·萨利斯知道些什么。', '将10块粗糙的碎片交给黑色观察站的北伐军战士欧尔拉金·萨利斯。', '<欧拉金谨慎地检视这些金属裂片。>$B$B你在这下面的每个食尸鬼身上，都有找到这些玩意吗?我倒是不曾在任何与天灾军团的战斗中，见到类似的东西。', '那肮脏的玩意是什么?', '', '去冰冠冰川找黑色观察站的北伐军战士欧尔拉金·萨利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13137, '不那么光彩的战斗', '在西南方那片俯瞰尤顿海姆的群山中，战痕尖塔是最高的一座。它是维库人心目中仅次于瓦哈拉斯的神圣决斗场。$B$B但是我们要在那里打一场不那么光彩的战斗。$B$B召集你的同伴，飞上那座山峰。你准备好以后，就发出烽火信号，我会操控伊斯卡德尔的躯体出现在决斗场中。$B$B我们会“决斗”，而你将获得胜利。瓦尔德玛达肯定会去观看这场精彩的比赛！', '约尔达村的白骨女巫要你在战痕尖塔击败伊斯卡德尔。', '瓦德玛卓当前在某个安全的地方。我暂时放她一马，直到我们可以上演最后复仇的戏码为止!', '你还没击败那远古英雄!', '', '去冰冠冰川找约尔达村的白骨女巫。', '击败伊斯卡德尔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13138, '熔炼碎片', '<欧尔拉金将碎片放在掌心翻转，听着它与铠甲护手的碰撞声。>$B$B如果力道足够的话，这些碎片足以刺穿护甲。我们必须搞清楚它们的成分以及巫妖王制作它们的意图。$B$B此地以东是玛雷卡里斯，就在冰冠堡垒旁边。根据我们获得的一点点情报，那里到处都是熔炼和锻造设备。将这些碎片带去那里，在玛雷卡里斯底层的熔炉附近熔化并进行重铸，这样我们就能对其成分进行分析了。', '在玛雷卡里斯底层的熔炉附近使用一包粗糙的碎片。将熔炼过的金属锭交给黑色观察站的北伐军战士欧尔拉金·萨利斯。', '毋庸置疑地，这是生萨钢。我们曾经看过，它被用来制造巫妖王军队的武器，但这是第一次被用在其它人的武器中。开矿的规模应该很大。', '你镕炼那些碎片了吗?', '', '去冰冠冰川找黑色观察站的北伐军战士欧尔拉金·萨利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13139, '进入诺森德的冰冷腹地', '西拉斯和斯比帕提克已经就公正堡建造计划所需的原料和燃料达成了一致意见。多亏了你和黑锋骑士团的帮助，天灾城的驻军遭遇重创，他们的军官也败在你手中。$B$B我已经确定了建设地点，但是这份报告需要呈送大领主提里奥·弗丁审核，你替我跑一趟吧。只要他一声令下，我们就挥师北上，进入冰冠冰川。', '将古斯塔夫神父的报告交给冰冠冰川银色前线基地的大领主提里奥·弗丁。', '对确保战线而言，你的协助是不可或缺的。这场战争的最终胜利已唾手可得 - 这就是为什么我们的下一步如此重要。$B$B好好休息，$N，天灾军团不会未战先降。你最大的挑战还在后头。', '请随意，$N。你有什么要报告的?', '', '去冰冠冰川找银色前线基地的大领主提里奥·弗丁。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13140, '玛雷卡里斯的符文锻造师', '你发现的那些碎片只可能来自玛雷卡里斯。那里是巫妖王的冶金基地，就在恐惧之门科雷萨以东。$B$B但是无论是缝合到憎恶和血肉巨人，还是召唤骷髅仆从，都用不到萨隆邪铁啊。杀入玛雷卡里斯底层，找到那些骷髅符文锻造师，夺取它们正在加工的金属板。我们必须查明缝合场为什么需要用到这种金属。', '将5块符文萨隆邪铁板交给黑色观察站的北伐军战士欧尔拉金·萨利斯。', '这些符文板和裂片几乎完全契合。它们一定是被用来『加强』这一带的食尸鬼。这样看来，天灾军团已经到了孤注一掷的地步，必须以任何可能的材料制造武器。这些理由让我们必须加快脚步，摧毁这个令人厌恶的地方!', '你有拿到那些符文板吗?', '', '去冰冠冰川找黑色观察站的北伐军战士欧尔拉金·萨利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13142, '女妖的复仇', '时机已经成熟，$N。你和你的朋友必须向大领主巴拉加德发起挑战，他既是巴拉加德堡垒的领主，也是尤顿海姆的统治者。$B$B巴拉加德堡垒位于尤顿海姆的西南边缘，在堡垒顶部有一支号角。你要吹响它，让挑战的号角响彻这片土地。$B$B如此一来，巴拉加德就必须接受你的挑战了。而我……不，瓦尔德玛达将仲裁这场战斗。$B$B<被女妖附身的维库人发出恐怖的笑声。>', '约尔达村的白骨女巫要你挑战并击败大领主巴拉加德，为她复仇。', '任何字词都不能描述我现在的感觉，$N。我的复仇已了，再无所求。$B$B或许，唯有巫妖王倒下时，我也在场的感觉差可比拟。$B$B别高兴得太早，要“清理”卓顿海姆还有很长的一段路得走。我将继续附身在这女巫身上，直到维库人不再构成威胁。$B$B看看周遭，这洞穴里有很多值钱的玩意。随便拿点吧。', '共主巴拉加德还没死。你对寻找堡垒这件事，有任何疑问吗?', '', '去冰冠冰川找约尔达村的白骨女巫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13143, '新兵', '重要的事情优先解决吧。我在东边的城墙上发现了一些轻盈追迹者，在我们和阿尔萨斯彻底决裂之前，那些家伙曾是我们的仆从，而且堪比世界上最优秀的斥候……只要通过统御之眼控制它们就可以运用它们的能力为我们做事。$B$B我要你飞上城墙，稍微教训一下某个轻盈追迹者，然后使用这枚黑锋魔印强迫它臣服于你，它一定还认得这东西。接着，你就把它带回此地东北方的岩石上，它自己就能回到我身边来。', '苦难高地的狡诈者维雷斯要你驯服一只轻盈追迹者，然后把它带到苦难高地东北方的岩石上。', '我已经将小坏蛋拴在那边的柱上了，我也会继续抓更多的潜伏者。$B$B我们好好利用一下它们锐利的目光吧。', '我相信它们的新主人让它们过得不太好，但是没有其它方法。这些家伙很快就会忘记，我们才鞭笞过的教训。只要它们还在这块大陆上蠕动，就会害怕这些符印的。', '', '去冰冠冰川找苦难高地的狡诈者维雷斯。', '交还被驯服的轻盈追迹者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13144, '一举两得', '缝合场的憎恶装配台那里已经制造出了大量的成品。现在，这些怪物都被锁在装配台附近的柱子上。如果我们还不采取行动，它们就要随着巫妖王的部队出征了。$B$B缝合场的白骨堆里有一些骷髅手臂在扭动，这些手臂的原主呢，就是那些可以操纵火焰的骷髅。你要去找到并释放那些骷髅，把它们带到缝合完毕的憎恶附近，然后就等着看好戏吧！', '黑色观察站的黑暗骑士阿尔蕾要你借助燃烧的骷髅消灭3只被锁住的憎恶。', '啊，很好。早晨的血肉焦臭味是什么都比不上的。那是战胜天灾军团的胜利气味啊。', '你摧毁那些憎恶体的成品了吗?', '', '去冰冠冰川找黑色观察站的黑暗骑士阿尔蕾。', '焚烧被锁住的憎恶', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13145, '邪恶城堡', '首先，我们需要搞清楚敌人的底细。$B$B使用统御之眼控制一只轻盈追迹者，对这一地区进行侦察。我在飞来这里的路上留意到几处特别的地方，希望你能重点调查一下：东北方的高地、东南方的工作区、中央的大熔炉以及西南方的祭祀场。$B$B追迹者拥有惊人的跳跃能力，从高处摔落也不会受伤——你可以利用这一点，在城墙间上跳下窜。', '苦难高地的狡诈者维雷斯要你使用轻盈追迹者的能力，侦察玛雷卡里斯。', '干得好。看来向阿尔萨斯效忠的死亡骑士，比我原先预想的多。$B$B他一点也没有隐藏取代亚榭洛的意图。一座纯萨钢造的城塞确实很难摧毁。不过我们没有必要摧毁它...我们可以阻断它的建造，并且解决这些死亡骑士的领袖。就在此时此地，在他们成为真正的威胁之前。$B$B最重要的是，我们必须在他们中间引起够大的混乱，令那些死亡骑士远离他们的领导者，好让我们能发起成功的袭击。', '飞行或许更优雅一些，但是我们没办法像潜猎者一样靠得那么近又不被发现。', '', '去冰冠冰川找苦难高地的狡诈者维雷斯。', '调查牺牲祭坛', '调查鲜血熔炉', '调查冰冷哨塔', '调查符文工场');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13146, '深信不疑', '我们要制造一些麻烦……只要能让这些死亡骑士离开他们的头目身边就行了。如果能设法干掉他们手下的那些爪牙，他们就不得不投入大量精力去监督玛雷卡里斯的工作进展。$B$B憎恶是这次行动的完美猎物——它们行动迟缓、头脑简单，而且相当相当地愚蠢。利用它们对追迹者的信任，将散落在工地上的天灾炸弹拖到它们身边去。在它们反应过来之前，你有足够的时间跑到远处，然后引爆炸弹。', '狡诈者维雷斯要你使用轻盈追迹者的铁链，将天灾炸弹拖到玛雷卡里斯的4个笨拙的凶尸身边。', '他们甚至没有怀疑到你，不是吗?至少他们很好预测。', '他们有察觉到你对他们下手吗?', '', '去冰冠冰川找苦难高地的狡诈者维雷斯。', '送出天灾炸弹礼物', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13147, '煽风点火', '瓦古和低级亡灵奴仆的最大差别在于，瓦古还保留着一定的自主意识，这表现在它们依然非常蔑视体力劳动，不愿和骷髅或是食尸鬼一起工作。$B$B我们可以利用这种天生的抵触情绪，在玛雷卡里斯的阴暗蛮徒和其它亡灵之间挑起争端。这可以减缓它们的工作进度，让那些死亡骑士下来收拾局面。$B$B很简单——只要在阴暗蛮徒靠近低级亡灵时对蛮徒投掷石块就行了。', '苦难高地的狡诈者维雷斯要你趁阴暗蛮徒靠近低级亡灵时，利用轻盈追迹者向阴暗蛮徒投掷石块。挑起5起争端之后回去复命。', '他们这么容易玩弄，根本不需要牺牲我们自己人，是吧?', '容易被摸透的蠢蛋。', '', '去冰冠冰川找苦难高地的狡诈者维雷斯。', '挑起工人间的争斗', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13148, '修理项链', '这根损坏的项链上附着一张发货单，上面写着：“达拉然 - 魔法商业区 - 卡蒂亚珠宝店 - 提莫斯·琼斯的财产”。$B$B或许你应该把它修好，然后交还给他。', '用一颗玉髓石对项链进行修补，然后把它还给达拉然魔法商业区珠宝店的提莫斯·琼斯。', '你在哪里找到它的?几星期前的一次交货中，不少这样的项炼被劫走了!让我送你这个珠宝匠徽章作为回报。', '你带了什么来?', '', '去达拉然找卡蒂亚珠宝店的提莫斯·琼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13152, '看医生', '这么说来，它们在复生密室里将邪铁碎片植入食尸鬼体内？我们必须阻止它们，不能让这些新型食尸鬼变成天灾军团对付我们的利器。$B$B转至缝合场，在血肉巨人装配台一带找到复生密室的入口。食尸鬼的首脑萨布诺克博士将他最可怕的造物“补丁”关押在那里。解开“补丁”的锁链，这对你控制天灾生物是非常有用的。', '黑色观察站的黑暗骑士阿尔蕾要你进入复生密室，摧毁囚禁“补丁”的金属桩，并且帮助它击败萨布诺克博士。', '<黑骑兵阿尔利别过头去，发出阴沉的笑声。>$B$B真是这个“好”博士应得的下场，你不认为吗?', '你解开博士作品的束缚，好让他自食恶果了吗?', '', '去冰冠冰川找黑色观察站的黑暗骑士阿尔蕾。', '释放“补丁”', '帮助“补丁”击败萨布诺克博士', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13153, '保护士兵', '很高兴见到你，$n。虽然战斗暂时告一段落了，但是我们必须立即开始准备足够的军用物资。经过调查，我发现死在冰川瀑布附近的士兵身上的护甲都因为当地的特殊环境的关系，被附上了巨大的能量。部落已经在那里收集这种护甲了。$B$B到冰川瀑布去，杀死你所遇到的部落成员。把他们手中那些灌魔的护甲拿来给我。$B$B如果你找不到部落的士兵，也许可以在那里的元素生物身上发现被它们杀死的冒险者的护甲。', '冬拥堡垒的女巫凯兰娜要你转至冰川瀑布，从部落玩家身上收集10套灌魔的部落护甲。', '噢。它还在滴水耶。你就不能先把它弄干吗?', '嗯，你有找到护甲吗?', '', '去找冬拥湖的女巫凯兰娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13154, '骨头和箭矢', '龙这种生物真是个奇迹！好吧，至少它们的骨头是个奇迹！我给弓箭手们配备了龙骨制作的箭头。可惜，自从安加萨发生大屠杀以后，就很难从龙骨荒野弄到龙骨了。$B$B不过冬拥湖西边的阴影森林里也有不少龙骨，足够我们用的了。$B$B你现在就到阴影森林去，把你能找到的所有骨片都拿回来！$B$B有人看见部落也在那个地区收集骨片。去杀了那些部落渣滓！', '冬拥堡垒的制弓师兰多尔弗要你转至阴影森林，从部落玩家那里抢夺10支龙骨箭。', '非常好!这将有助我们，在不日即来的战斗中，燃起熊熊的战争烈焰。', '狩猎的结果如何?我听到一些谣言，说那里闹鬼，虽然我不曾亲自去那里冒险。', '', '去找冬拥湖的制弓师兰多尔弗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13156, '稀有的草药', '天啊，这里可真冷！让我想起了阿古斯上的风雪交加的凯因努斯雪山。在这冰天雪地中，我们的士兵很容易感冒。$B$B到冬拥湖西南方的生命草原去，帮我弄10株生长在那里的红色植物来，我会把它们制成抵御寒气的药物。$B$B有人看见部落也在那一地区收集草药。尽管杀了他们，把草药抢过来！', '冬拥堡垒的学者特尔萨要你转至生命草原，收集10只部落草药包。', '太棒了!这将能协助我们的部队对抗严寒。', '我希望你没有不小心惹到任何鞭笞者!上星期他们请大兵铎安吃了好一顿鞭子。', '', '去找冬拥湖的学者特尔萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13159, '堵截', '这是监狱的钥匙。$B$B我和我的部下会坚守在这里，万一你们抵挡不住的话，我们将是最后一道防线。$B$B快一点，$r。时间不多了。我们留在里面的人恐怕坚持不了多久。$B$B记得去跟辛克莱尔中尉谈一谈，她会给你使用监狱防御设施的许可。$B$B等你处理掉入侵之敌，记得马上回来向我汇报。', '典狱官奥图拉斯希望你进入紫罗兰监狱，消灭入侵的蓝龙军团。杀死塞安妮苟萨之后向他复命。', '危机过去了，然后呢?$B$B那的确是个好消息。我会将这个消息上呈给罗宁。$B$B请收下这个，代表达拉然的感激。', '结束了吗?你应付得了攻势吗?', '', '去达拉然找紫罗兰监狱的典狱官奥图拉斯。', '杀死塞安妮苟萨', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13160, '壮观的景象', '石像鬼既是出色的斥候，也是致命的空中作战单位，但是它们有一个明显的弱点。大部分石像鬼都需要在石头状态下进行长时间的休眠，补充足够的能量，否则就无法拖着沉重的身体飞行。$B$我曾经通过统御之眼观察过，玛雷卡里斯东面和南面的城墙上栖息着许多冰肤斥候。你可以利用追迹者高高跃起，跳到冰肤斥候身边，趁它们熟睡时干掉它们。', '苦难高地的狡诈者维雷斯要你使用轻盈追迹者的跳跃能力，杀死12只熟睡的冰肤斥候。', '他们睡觉的时候可没什么威胁性。', '简直易如反掌。', '', '去冰冠冰川找苦难高地的狡诈者维雷斯。', '摧毁冰肤斥候', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13161, '邪恶骑士', '我们该去拿走这些野兽的徽记了。$B$B我曾在洛基尔身边侍卫许久。他运用邪恶灵气的能力比我见过的其它死亡骑士要高出许多，而且他还是个非常残忍的家伙。$B$B当你在洛基尔的地盘上与他交战时，他的力量会发挥到极限。悲哀的是，我们没有办法避开这种不利局面，不过只要你躲开他的亡灵爪牙，获胜也不是不可能。$B$B要保持灵活，$c。不要有丝毫的轻敌之念。', '苦难高地的狡诈者维雷斯要你杀死洛基尔，邪恶骑士。', '没有了洛基尔，这世界会变得更美好 - 相信我。', '完成了吗?', '', '去冰冠冰川找苦难高地的狡诈者维雷斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13162, '冰霜骑士', '萨芙……这位死亡骑士和别人不同。她会对你花言巧语，让你相信她的本性并不邪恶，但是转眼之间，她就会微笑着杀了你。$B$B我相信你要战胜她并非难事，但是千万不要掉以轻心。她的危险之处在于，她会让敌人相信自己胜券在握，然后放松警惕，然后发动迅猛的冰霜攻击将其击溃。$B$B所以，你要注意保持警惕，并且不要低估了她。', '苦难高地的狡诈者维雷斯要你杀死萨芙，冰霜骑士。', '不能否认地，我会怀念她的笑声…以及她杀人的那一刻脸上挂着的笑容。不过，我不需要再时时注意背后的杀机，所以我想也没有什么好抱怨的。', '我们除掉她了吗?', '', '去冰冠冰川找苦难高地的狡诈者维雷斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13163, '鲜血骑士', '贝洛克是极少数逐步晋级上来的维库人，他的地位完全是靠血淋淋的战功累积而来的。如果你死在他手下，那也算不得是一件遗憾的事情。$B$B当你和他交战的时候，记得与同伴们保持彼此之间的距离，并尽可能远离贝洛克。他会毫不犹豫地榨干你们的生命能量，将其据为己有，所以你要有意识地阻止他使用这种能力。$B$B我对你有信心。去干掉他。', '苦难高地的狡诈者维雷斯要你杀死贝洛克，鲜血骑士。', '所以他终于死了?真是好消息。', '他死了吗?', '', '去冰冠冰川找苦难高地的狡诈者维雷斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13164, '血毒的命运', '杀死苦难之主骑士团的几个头目之后，我们就要去对付他们真正的首领——奥尔巴兹·血毒。$B$B在你外出执行任务的时候，莫格莱尼来找过我，他将奥尔巴兹的藏身之处告诉了我。在冰冠堡垒的地下，有一座巨大的深渊——你可以在深渊的边缘找到奥尔巴兹。$B$B我们已经派出了最精锐的黑锋骑士协助你战斗。奥尔巴兹的末日已经到了。', '苦难高地的狡诈者维雷斯要你杀死奥尔巴兹·血毒。', '莫格莱尼亲自到场监督处刑?我猜他们俩之间，一定有些过节 - 他想取走那畜牲尸体的一部分，实在不令人意外。$B$B你做得非常好，$r，你也会得到相应的奖赏。黑锋骑士团感谢你。', '我们终于摆脱了那个崇拜阿尔萨斯的家伙了吗?', '', '去冰冠冰川找苦难高地的狡诈者维雷斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13166, '黑锋要塞之战', '命令大厅已经被我们占领了，但是巫妖王在阿彻鲁斯之心给我们留下了一点小礼物。那个可怕的缝合怪物——帕奇维克和一群憎恶占领了第二层。$B$B使用传送器转至第二层，消灭剩馀的天灾部队。不要试图独自挑战帕奇维克！你必须协同阿彻鲁斯的其它死亡骑士，一起攻击那个怪物！$B$B出发吧，$N。我的力量与你同在！', '杀死10个天灾亡灵，并参与消灭帕奇维克的战斗。成功之后，回去向大领主达里安·莫格莱尼复命。', '干得好，死亡骑士。天灾军团的馀孽很快就会被清除，而重建的程序也将展开。$B$B我有一份最后的工作得麻烦你。', '亚榭洛是我们的!', '', '去找黑锋要塞的大领主达里安·莫格莱尼。', '', '杀死天灾士兵', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13167, '叛徒国王之死', '那个背叛我们族人的所谓国王，阿努巴拉克，当前居住在曾经荣耀一时的地下王国艾卓-尼鲁布。$B$B由于他的背叛，我们的家园变成了现在这幅肮脏凄惨的模样。他所统治的亡灵蛛魔军团如同它们的首领一样向巫妖王起誓，效忠于他。$B$B去终结叛徒国王的统治吧，$c。这样对我们和你来说都能算是一件大好事。$B$B要是你能取得成功的话，把阿努巴拉克的甲壳带回来给我。', '纳尔苏深渊的拆解者基里克斯要你去击败艾卓-尼鲁布的阿努巴拉克，并将阿努巴拉克的破损甲壳交给基里克斯。', '<当齐力克斯凝视着阿努巴拉克的壳，他所有的眼睛发出明显的灼热光芒。>$B$B完成了!$B$B$r!你的名字江会被记载在我族的历史之上。$B$B我欠了你很大一份恩情……', '你做到了吗，$C?叛徒之王得到他应有的结局了吗?', '', '去龙骨荒野找纳尔苏深渊的拆解者基里克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13168, '离别礼物', '瞧瞧……统御之眼。诅咒教派通常会不遗馀力地保护这种东西，不过大概是在自家老巢被血洗时，他们实在无暇他顾。$B$B通过统御之眼，任何拥有相关力量的生物都可以精确地控制某个亡灵奴仆的行动。你可以想象得到，这对你控制食尸鬼或是骷髅是非常有用的。$B$B想试试吗？喏，拿那边的影魔练练手吧。', '暗影拱顶的克里托斯·血刃要你使用统御之眼控制一只被捕获的幻象观察者。', '没什么困难吧，嗯?任何有智力的生物，都能轻易地操纵较低等的不死生物。我怀疑，只有真正的死灵法师，能控制更强大的不死生物。不过那不成问题 －', '使用支配之眼以掩饰行动的好处是显而易见的。这会是非常好用的工具。', '控制一只幻象观察者', '去冰冠冰川找暗影拱顶的克里托斯·血刃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13169, '亡灵的好朋友', '按照惯例，西南边那座萨隆邪铁采掘场里的亡灵会故意让瘟疫犬饿着，以保持它们的攻击性。你可以控制影魔去接近那些猎犬，喂它们一点吃的。我敢保证，它们肯定不会冲你乱吠，说不定还会认你做主子呢。$B$B但是在喂饱猎犬之前，不要靠近它们。你的影魔是逃不过它们的鼻子的。', '暗影拱顶的克里托斯·血刃要你使用幻象观察者给18条饥饿的瘟疫恶犬喂食。', '它们这会儿可都睡着了，不是吗?', '别浪费太多饲料\r\n - 那些狗只要有得吃就会听话。', '', '去冰冠冰川找暗影拱顶的克里托斯·血刃。', '杀死饥饿的瘟疫恶犬', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13170, '不择手段', '食尸鬼是非常脆弱的东西，西南边萨隆邪铁采掘场里的那些守卫也不例外。我可以肯定，你只消控制一只影魔，就可以潜入那里，悄无声息地放倒那些守卫。$B$B你要用最短的时间干掉最多的守卫……我们要在发动总攻前尽量削减它们的数量。', '暗影拱顶的克里托斯·血刃要你去刺杀20名永不休息的斥候。', '根本用不着弄脏你自己的手。', '要察觉看不见的东西是很困难的。', '', '去冰冠冰川找暗影拱顶的克里托斯·血刃。', '暗杀永不休息的斥候', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13171, '来去无踪', '我最关心的是西南方的萨隆邪铁采掘场，他们正从那里源源不断地运出大量矿石。我想知道他们到底想要造出什么东西来。所以呢，我们要从削弱他们的防御力量开始入手。$B$B我注意到采掘场中散布着一些水晶，估计那是某种类似通灵塔的防御装置。你要利用幻象观察者去摧毁那些水晶。', '暗影拱顶的克里托斯·血刃要你去摧毁10枚天灾污染水晶。', '做得好。现在我们在空中就不受威胁了。', '那些水晶都排除掉了吗?我可不希望我的狮鹫兽遇上意想不到的惊喜。', '', '去冰冠冰川找暗影拱顶的克里托斯·血刃。', '摧毁天灾污染水晶', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13172, '混乱之种', '很有用的工具，不是吗？你已经削弱了他们的防御力量，$c。现在我们可以发起总攻了。$B$B计划很简单，我们要摧毁一切会移动的东西，并趁着混乱窃取一些情报。$B$B准备好以后再来找我，我会给你一头骷髅狮鹫。', '暗影拱顶的克里托斯·血刃要你转至哭泣采掘场，杀死80个亡灵。与他对话就可以获得进攻用的骷髅狮鹫。', '算得上是毫无防备。没什么比这个更简单的。', '好玩吗，嗯?', '', '去冰冠冰川找暗影拱顶的克里托斯·血刃。', '消灭哭泣采掘场中的亡灵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13174, '一片狼藉', '终止他们的运作只是计划的一部分，我们的另一个重要目标是找出萨隆邪铁的去向。我们已经知道了一部分矿石的流向，但其巨大的产量说明，敌人正在酝酿着一个更大的计划。$B$B你进入采掘场以后要注意搜集他们的文件。如果你是坐着狮鹫去进行突袭的，可以在完成任务后降落。', '将哭泣采掘场文档、哭泣采掘场账目、哭泣采掘场地图和哭泣采掘场进度表交给暗影拱顶的克里托斯·血刃。', '让我看看…我们有什么…$B$B<凯力多斯埋首于文件堆中好一会儿，从他的神情看来，似乎没有什么新发现。忽然，他发现了他要找的东西…>$B$B玛里库立斯!邪鄙堡。看来失去他的死亡骑士，给阿尔萨斯很大的打击…我不是很确定他拿那些萨钢做什么，但是我隐约觉得他会好好“回报”我们什么。$B$B那小子实在是输不起啊。', '你有带回我要的东西吗?', '', '去冰冠冰川找暗影拱顶的克里托斯·血刃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13177, '绝不留情', '欢迎来到冬拥堡垒，$n。你的任务很简单：去杀掉十个最精锐的部落士兵。现在就去！为联盟带来胜利！', '冬拥堡垒的指挥官萨纳斯要你去杀死10个部落玩家。', '光荣无比!真的，你是联盟的精英。', '嗯，你完成你的任务了吗?', '', '去找冬拥湖的指挥官萨纳斯。', '杀死部落成员', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13178, '全都干掉！', '欢迎来到冬拥堡垒，$n。督军加尔鲁什大人只有一个要求：把敌人全都干掉！$B$B杀掉十个最精锐的联盟士兵之后再回来见我。', '冬拥堡垒的指挥官达尔多什要你去杀死10个联盟玩家。', '为了部落!部落必胜!', '嗯，你完成你的任务了吗?', '', '去找冬拥湖的指挥官达尔多什。', '杀死联盟成员', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13179, '绝不留情', '欢迎来到冬拥湖，$n。你的任务很简单：去杀掉十个最精锐的部落士兵。现在就去！为联盟带来胜利！', '冬拥湖的指挥官萨纳斯要你去杀死10个部落士兵。', '光荣无比!真的，你是联盟的精英。', '嗯，你完成你的任务了吗?', '', '去找冬拥湖的指挥官萨纳斯。', '杀死部落士兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13180, '全都干掉！', '欢迎来到冬拥湖，$n。督军加尔鲁什大人只有一个要求：把敌人全都干掉！$B$B杀掉十个最精锐的联盟士兵之后再回来见我。', '冬拥湖的指挥官达尔多什要你去杀死10个联盟玩家。', '为了部落!部落必胜!', '嗯，你完成你的任务了吗?', '', '去找冬拥湖的指挥官达尔多什。', '杀死联盟成员', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13181, '冬拥湖的胜利', '如果你能让指挥官萨纳斯看到一大堆部落士兵的尸体，他或许会感到满意，但是对于无畏远征军而言，控制冬拥湖才是最重要的目标。你一定要保证我们拥有对这个地区的控制权。$B$B但是，不要以为你只需要躲在一边发呆，让你的盟友去冲锋陷阵就行了。如果你在战斗结束的时候没有达到至少第二级的军衔，就别回来见我。', '取得一场冬拥湖战斗的胜利，然后向冬拥湖的参谋官安布拉米斯复命。你必须亲自参与战斗，才能获得胜利后的奖励。', '正是我想听到的!冬拥湖的大胜 - 即使是暂时的 - 对于我们对抗部落的全盘战略都十分重要。', '你带来胜利的消息吗?', '在冬拥湖取得胜利', '去找冬拥湖的参谋官安布拉米斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13182, '别忘了蛛卵！', '艾卓-尼鲁布里面布满了天灾蛛魔细心呵护的卵，它们很快就会孵化，进一步扩充天灾蛛魔的规模。$B$B就算我们把洞中的亡灵都干掉，但是倘若留着那些蛛卵的话，等它们孵化出来之后，一切又将会到老样子。$B$B当你去艾卓-尼鲁布探险时，记得清理掉你在我们那座古老的家园中找到的所有天灾蛛魔之卵。', '纳尔苏深渊的拆解者基里克斯希望你转至艾卓-尼鲁布，摧毁6枚天灾蛛魔之卵。', '家乡沦落至此，令我感到悲伤不已。如果我们能回到曾一度拥有的辉煌帝国时代…', '你有清除掉那些天灾蛋吗?', '', '去龙骨荒野找纳尔苏深渊的拆解者基里克斯。', '摧毁天灾蛛魔之卵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13183, '冬拥湖的胜利', '虽然只要你能不断杀敌，达尔多什就会感到满意，但是对于我们来说，控制冬拥堡垒才是最重要的目标。你一定要保证我们拥有对这个地区的控制权。$B$B但是，不要以为你只需要躲在一边发呆，让你的盟友去冲锋陷阵就行了。如果你在战斗结束的时候没有达到至少第二级的军衔，就别回来见我。', '赢得一场冬拥湖战斗的胜利，然后向冬拥湖的参谋官基尔拉斯复命。你必须亲自参与战斗，才能获得胜利后的奖励。', '你今日的成就是真正的功勋。你的牺牲将会被永载史册!', '你带来什么消息?', '在冬拥湖取得胜利', '去找冬拥湖的参谋官基尔拉斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13185, '阻止攻城', '我听见了！联盟很快就要来了。去摧毁三辆联盟攻城器械，然后回来向莫普复命。', '冬拥堡垒的莫普中尉要你摧毁3辆联盟攻城器械。', '干得好。莫普也希望能在场帮忙。', '你摧毁他们的攻城载具了吗?', '', '去找冬拥湖的莫普中尉。', '摧毁联盟攻城器械', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13186, '阻止攻城', '部落迟早会开始对这座堡垒发动攻势的。去摧毁他们的三辆攻城器械，然后回来向我复命。', '冬拥堡垒的资深攻城技师雷格索要你摧毁3辆部落攻城器械。', '很好。这会迟滞他们的攻势。', '没有时间可以浪费了，你摧毁他们的攻城载具了吗?', '', '去找冬拥湖的资深攻城技师雷格索。', '摧毁部落攻城器械', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13187, '无面者', '我的同胞们在对抗亡灵天灾的战斗中，一旦遭到失败，就会采取往深处挖洞的办法躲避敌人。他们不顾一切地往深处挖，越挖越深，终于酿成了大祸。$B$B我们不经意间挖出了一条上古之神的触须，而它变成了一种名为无面者的生物。$B$B最终，我们再也无法在遭到两面夹击的情况下坚持作战，由此输掉了那场对抗亡灵的战争，并最终失去了我们的家园。$B$B$c，转至安卡赫特，消灭那些占领我们家园的无面者。', '纳尔苏深渊的拆解者基里克斯要你去杀死安卡赫特的传令官沃拉兹和他身边的3个被遗忘的无面者。', '你做得很好，$C。$B$B你的功绩带给我的子民希望，总有一天，我们会夺回先祖创建的城市。', '你做掉那些无面的家伙了吗，$C?', '', '去龙骨荒野找纳尔苏深渊的拆解者基里克斯。', '消灭被遗忘的无面者', '击败传令官沃拉兹', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13188, '王者之城', '你现在是——也永远是——黑锋骑士团的一员了，$N。但是你要记住：你曾经是联盟的英雄。$B$B<达里安凝视着你。>$B$B为了生存下去，我们的骑士团一定要与其它势力创建同盟关系。你将代表黑锋骑士团去与联盟结盟。$B$B在我东南方的平台上，有一道通向暴风城的传送门。拿着这封弗丁大人交给我的信，通过传送门转至暴风城，把它呈给瓦里安·乌瑞恩国王。', '转至暴风城的暴风要塞，将信交给联盟的瓦里安·乌瑞恩国王。', '<瓦里安望向远方。>$B$B真正的老友…鲜血与荣耀。$B$B<瓦里安的目光转向你。>$B$B要不是提里奥的这封信，你现在已经成了地板上的一滩血迹。只有史上最伟大圣骑士的背书才能确保你的性命。$B$B我们…我们将会同心协力对抗天灾军团。对抗巫妖王!$B$B荣耀归于联盟!', '你只有几秒钟的时间可活。', '', '去暴风城找暴风要塞的瓦里安·乌瑞恩国王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13189, '酋长的祝福', '你现在是——也永远是——黑锋骑士团的一员了，$N。但是你要记住：你曾经是部落的英雄。$B$B<达里安凝视着你。>$B$B为了生存下去，我们的骑士团一定要与其它势力创建同盟关系。你将代表黑锋骑士团去与部落结盟。$B$B在我东南方的平台上，有一道通向奥格瑞玛的传送门。拿着这封弗丁大人交给我的信，通过传送门转至奥格瑞玛，把它呈给萨尔。', '转至奥格瑞玛，将信交给部落的萨尔酋长。', '伊崔格是因为这位圣骑士才活下来的。要是大领主弗丁没有将他从斯坦索姆救出来，伊崔格就会遭到处决。$B$B提里奥.弗丁，牺牲了一切来拯救一个兽人的性命…除了他以外我只认识一个会做出这种牺牲的人类。$B$B<萨尔眨了眨眼，忍住一滴泪水。>$B$B你永远都会在我心中，塔蕾莎。$B$B是的，为了提里奥.弗丁与伊崔格!我们会接纳你成为部落的一员，接纳你的骑士团做为盟友。$B$B鲜血与荣耀!为了部落!', '事情发生了有趣的转变。', '', '去找奥格瑞玛的萨尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13190, '黄金时代', '安卡赫特，我们的起源之地……$B$B我梦想着有一天可以战胜那些笼罩着我们古老家园的死亡和黑暗的力量。为了让我的梦想变为现实，我想到一个计划，可以动摇敌人的军心。$B$B我们要烧死他们那珍贵的看守者！$B$B在城市深处的火盆上焚烧他们的尸体，让那种味道在空气中弥漫，让我们的敌人知道其实他们是如此的不堪一击。$B$B记住，$c！那些亡灵的尸体非常易碎，而且会很快腐坏。', '纳尔苏深渊的拆解者基里克斯希望你弄到一具安卡哈看守者的尸体，将其放在安卡赫特的安卡赫特火盆上焚烧。$B$B这个任务只能在英雄难度下完成。', '啊哈!$B$B希望那嘲弄的失败气味，会蚀入他们空虚的灵魂!$B$B谢谢你，$C。今天，你给了那些不死生物重重一击。', '你烧掉看守者的尸体了吗，$r?', '', '去龙骨荒野找纳尔苏深渊的拆解者基里克斯。', '焚烧安卡哈看守者的尸体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13191, '战车的燃料', 'Lok\'tar，$n！虽然战事暂时平息了，但我们必须为抵御联盟的攻击做好准备！到冬拥湖东南方的烈焰之坑去，弄一些永恒灰烬回来。$B$B这种灰烬里含有煤炭，可以充当攻城车辆的燃料。$B$B我们得到情报，联盟的猪猡整天都在收集这种灰烬。杀了他们，把他们手里的灰烬抢过来！如果他们撤出了那个地区，你就去干掉一些火元素，夺取灰烬！', '冬拥堡垒的攻城技师斯托霍夫要你转至烈焰之坑，收集10份永恒灰烬。', '很好!这会让我们在不日即来的战斗中，击败联盟!', '嗯哼?你是不是被联盟打败，馀烬被抢走了，只能蹲在路边哭?', '', '去找冬拥湖的攻城技师斯托霍夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13192, '防卫城墙', '嘿，朋友。你知道吗，这个地方简直让我神经衰弱。$B$B这里游荡着太多的幽灵。我想要增强巫毒守卫，但我需要一些灵魂，朋友。但不是任何灵魂都有用的，只有强大战士的灵魂才行。$B$B冬拥湖东边的冰川瀑布那里有一种特别适合抽取灵魂的东西。去杀死那里的联盟士兵，他们身上或许有我们需要的材料。$B$B把死者的护甲给我带来。如果找不到联盟的人，那里元素生物身上或许会有。', '冬拥堡垒的邪咒师弗尔金要你转至冰川瀑布，收集10套灌魔的联盟护甲。', '噢，你弄回来我的东西的啦，老兄!', '你带回护甲了的吗，老兄?', '', '去找冬拥湖的邪咒师弗尔金。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13193, '骨头和箭矢', '他们干嘛非要派我来武装弓箭手呢？我是个吟游诗人，不是游侠！唉，抱怨是没有用的。$n，我需要一些制作箭头用的龙骨。$B$B你可以到冬拥湖西边的阴影森林去找。自从上次战斗过后，联盟就在那里搜集龙骨。杀了他们，夺走他们手中的龙骨。$B$B如果这招不管用，你或许可以从那里的幽灵身上得到一些。我听说他们喜欢用龙骨把猎物穿起来。', '冬拥堡垒的维尔隆·火羽要你转至阴影森林，从联盟玩家那里抢夺10支龙骨箭。', '嗯哼，我猜又是一个削骨头的夜晚了。为什么我不要像我哥一样待在银月城呢?', '这么快就回来了?可恶，我才想要休息一下的。', '', '去找冬拥湖的维尔隆·火羽。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13194, '治疗用的玫瑰', '在战斗的间隙中，人们或许仍会相信和平终究会降临这片土地。可惜的是，我们注定无法享受和平的生活。$B$B请你到冬拥湖西南部的生命草原去一趟。我需要那里生长的一种玫瑰，它可以用来制作疗伤药膏。$B$B但是，由于联盟的频繁采摘，这种玫瑰已经非常稀有了。杀死生命草原上的联盟成员，从他们身上夺取草药。$B$B如果这不管用，那么你或许还可以找那里的鞭笞者碰碰运气。', '指挥官莫弗尔特要你转至生命草原，收集10只联盟草药包。', '感谢你，这对治疗我们士兵的伤口有很大助益。', '你有采回药草吗?伤兵与病人又增加了。', '', '去找冬拥湖的指挥官莫弗尔特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13195, '稀有的草药', '天啊，这里可真冷！让我想起了阿古斯上的风雪交加的凯因努斯雪山。在这冰天雪地中，我们的士兵很容易感冒。$B$B到冬拥湖西南方的生命草原去，帮我从部落的成员手中抢10个部落草药包来，我会把它们制成抵御寒气的药物。$B$B有人看见部落也在那一地区收集草药。尽管杀了他们，把草药抢过来！$B$B那里的鞭笞者身上可能也有这东西。', '冬拥湖的学者特尔萨要你转至生命草原，收集10只部落草药包。', '太棒了!这将能协助我们的部队对抗严寒。', '我希望你没有不小心惹到任何鞭笞者!上星期他们请大兵铎安吃了好一顿鞭子。', '', '去找冬拥湖的学者特尔萨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13196, '骨头和箭矢', '龙这种生物真是个奇迹！好吧，至少它们的骨头是个奇迹！我给弓箭手们配备了龙骨制作的箭头。可惜，自从安加萨发生大屠杀以后，就很难从龙骨荒野弄到龙骨了。$B$B不过冬拥湖西边的阴影森林里也有不少龙骨，足够我们用的了。$B$B你现在就到阴影森林去，把你能找到的所有骨片都拿回来！$B$B有人看见部落也在那个地区收集骨片。去杀了那些部落渣滓！', '冬拥湖的制弓师兰多尔弗要你转至阴影森林，从部落玩家那里抢夺10支龙骨箭。', '非常好!这将有助我们，在不日即来的战斗中，燃起熊熊的战争烈焰。', '狩猎的结果如何?我听到一些谣言，说那里闹鬼，虽然我不曾亲自去那里冒险。', '', '去找冬拥湖的制弓师兰多尔弗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13197, '战车的燃料', '$n！你总算来了。虽然我们在上一场战斗中失利了，但还是应该为下一场战斗做好准备！到冬拥湖东南方的烈焰之坑去，弄一些永恒灰烬回来。$B$B这种灰烬里含有煤炭，可以充当攻城车辆的燃料。$B$B哦，对了，如果你在烈焰之坑遇到部落的渣滓，尽管杀了他们，把他们手里的灰烬抢过来。绝对不能让他们占据堡垒！', '冬拥湖的攻城大师斯托汉德要你转至烈焰之坑，收集10份永恒灰烬。', '非常好!这将有助我们，在不日即来的战斗中，燃起熊熊的战争烈焰。', '嗯哼?你是不是被部落打败，馀烬被抢走了，只能蹲在路边哭?', '', '去找冬拥湖的攻城大师斯托汉德。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13198, '保护士兵', '很高兴见到你，$n。我们必须为下一波攻势做好准备。经过调查，我发现死在冰川瀑布附近的士兵身上的护甲都因为当地的特殊环境的关系，被附上了巨大的能量。部落已经在那里收集这种护甲了。$B$B到冰川瀑布去，杀死你所遇到的部落成员。把他们手中那些灌魔的护甲拿来给我。$B$B如果你找不到部落的士兵，也许可以在那里的元素生物身上发现被它们杀死的冒险者的护甲。', '冬拥湖的女巫凯兰娜要你要你转至冰川瀑布，收集10套灌魔的部落护甲。', '噢。它还在滴水耶。你就不能先把它弄干吗?', '嗯，你有找到护甲吗?', '', '去找冬拥湖的女巫凯兰娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13199, '骨头和箭矢', '他们干嘛非要派我来武装弓箭手呢？我是个吟游诗人，不是游侠！唉，抱怨是没有用的。$n，我需要一些制作箭头用的龙骨。$B$B你可以到冬拥湖西边的阴影森林去找。自从上次战斗过后，联盟就在那里搜集龙骨。杀了他们，夺走他们手中的龙骨。$B$B如果这招不管用，你或许可以从那里的幽灵身上得到一些。我听说他们喜欢用龙骨把猎物穿起来。', '冬拥湖的维尔隆·火羽要你转至阴影森林，从联盟玩家那里抢夺10支龙骨箭。', '嗯哼，我猜又是一个削尖骨头的夜晚了。为什么我不要像我哥一样待在银月城呢?', '这么快就回来了?可恶，我才想要休息一下的。', '', '去找冬拥湖的维尔隆·火羽。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13200, '战车的燃料', 'Lok\'tar，$n！虽然战事暂时平息了，但我们必须为夺回堡垒做好准备！到冬拥湖东南方的烈焰之坑去，弄一些永恒灰烬回来。$B$B这种灰烬里含有煤炭，可以充当攻城车辆的燃料。$B$B我们得到情报，联盟的猪猡整天都在收集这种灰烬。杀了他们，把他们手里的灰烬抢过来！如果他们撤出了那个地区，你就去干掉一些火元素，夺取灰烬！', '冬拥湖的攻城技师斯托霍夫要你转至烈焰之坑，收集10份永恒灰烬。', '太棒了!那一定会让他们的战争机器寸步难行!', '嗯哼?你是不是被联盟打败，馀烬被抢走了，只能蹲在路边哭?', '', '去找冬拥湖的攻城技师斯托霍夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13201, '治疗用的玫瑰', '在战斗中，我们损失了许多勇士。但是如果缺医少药，我们还会失去更多的同胞。$B$B请你到冬拥湖西南部的生命草原去一趟。我需要那里生长的一种玫瑰，它可以用来制作疗伤药膏。$B$B但是，由于联盟的频繁采摘，这种玫瑰已经非常稀有了。杀死生命草原上的联盟成员，从他们身上夺取草药包。$B$B如果这不管用，那么你或许还可以找那里的鞭笞者碰碰运气。', '冬拥湖的指挥官莫弗尔特要你转至生命草原，收集10只联盟草药包。', '感谢你，这对治疗我们士兵的伤口有很大助益。', '你有采回药草吗?伤兵与病人又增加了。', '', '去找冬拥湖的指挥官莫弗尔特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13202, '攻打城墙', '嘿，朋友。你没看见联盟的人正在堡垒里悠哉游哉吗？$B$B我觉得他们也太舒服了，你说呢？这里游荡着太多的幽灵。我想要攻打堡垒，但首先我需要一些灵魂，朋友。但不是任何灵魂都有用的，只有强大战士的灵魂才行。$B$B冬拥湖东边的冰川瀑布那里有一种特别适合抽取灵魂的东西。去杀死那里的联盟士兵，他们身上或许有我们需要的材料。$B$B把死者的护甲给我带来。如果找不到联盟的人，那里元素生物身上或许会有。', '冬拥湖的邪咒师弗尔金要你转至冰川瀑布，从联盟玩家那里收集10套灌魔的联盟护甲。', '噢，你弄回来我的东西的啦，老兄!', '你带回护甲了的吗，老兄?', '', '去找冬拥湖的邪咒师弗尔金。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13204, '奇怪的蘑菇', '一只奇形怪状的蘑菇状的真菌从一块散发着强烈异味、被软泥包裹的洞穴兽的肉上掉了下来。在检查这只蘑菇的时候，你被它散发出的恶臭熏得晕头转向。$B$B你不由得猜想，也许这是蛛魔们首选的某种美食？你决定找出这块有机物的真相，于是把它放在了包裹里。', '从安卡赫特的野蛮洞穴兽那里收集6只奇异的蘑菇，然后把它们交给纳尔苏深渊的拆解者基里克斯。', '你知道你带来的那玩意是什么吗，$C?$B$B你猎捕的那些蛮穴野兽，根本没有处理排泄物的方法。你该好好洗个手的…$B$B我很感谢你的点子，但是如果你要再弄那些玩意来的话，请和它们保持距离。', '这些是什么鬼东西?!', '', '去龙骨荒野找纳尔苏深渊的拆解者基里克斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13205, '削减军备', '相信我，$G小伙子:姑娘;，维库人的武器是非常致命的！$B$B我尝过他们武器的厉害，那简直是鬼斧神工。完美的设计，锋利的利刃——非常致命。$B$B如果你没有其它事可做的话，到他们的城堡里面去偷一些武器出来如何？或许我们可以从他们的武器设计中学到些什么。$B$B就算学不到什么东西，让他们少几把斧子用，总是好的。', '防御者墨尔顿要你进入乌特加德城堡，偷取5把维库武器。', '<摩丹压低声音。>$B$B瞧瞧它们一眼?不可思议。$B$B我期待那些原始人从此只能挥舞木棒和丢掷石头。$B$B别做白日梦了…', '你弄来些维库斧头了吗?', '', '去嚎风峡湾找瓦加德的防御者墨尔顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13206, '削减军备', '我们必须找出这些野人所用的武器中的秘密！$b$b如果你也曾亲眼看见他们是如何轻易地将我的同伴们砍倒，就会理解我的迫切心情了。如果你对我的话有所怀疑，可以自己去看看他们的熔炉。$b$b去搜索一下那个地方，尽量多收集一些武器回来，把它们拿给安希尔姆，让他研究一下。$b$b别让我们失望，$c。你多拿一把武器回来，我们在战场上就能少面对一个强敌。', '黑暗游侠玛尔拉要你从乌特加德城堡中偷出5把维库武器，并把它们交给复仇港的高级执行官安希尔姆。', '玛拉已经告诉我们维库武器的急迫性。我们会仔细检查这些玩意，看看有什么值得我们学习的地方。$B$B收下这个，作为麻烦你的补偿，$C。', '你从那里弄来了什么，$C?', '', '去嚎风峡湾找复仇港的高级执行官安希尔姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13207, '岩石大厅', '哎呀，能在这么个地方看到其它冒险者，真令我感到惊讶！正好，我需要一些人手来和我结伴探险。$B$B如果我对这些大厅的研究无误的话，我应该可以在这里获得非常重大的发现！$B$B尽管我不指望你能够保护我，但我也很欢迎你能一起跟去看看。你觉得怎么样，$c？愿意一起去吗？', '布莱恩·铜须希望你能与他结伴而行，揭开岩石大厅的秘密。', '未解的疑问永远都比答案多，嗯，$g小伙子:小女孩;?', '嗯哼，现在，我们能互相作伴也算是一件好事啦。', '', '去找岩石大厅的布莱恩·铜须。', '完成布莱恩的探索', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13211, '净化的火焰', '天灾军团利用阵亡的北伐军战士对付我们。他们将死者复活成食尸鬼和骷髅，或者将他们的残肢缝合成憎恶。必须阻止他们的这种恶行！$B$B阵亡的战士都是为了保护生者而牺牲的，他们都是英雄，不应该遭遇如此可怕的命运。而且我们也不忍心在战场上面对昔日的战友，与他们兵戎相见。请你带着这支火把转至缝合场，烧毁复生密室和憎恶装配台一带的尸体。', '黑色观察站的北伐军战士欧尔拉金·萨利斯要你使用欧尔拉金的火炬烧毁7具腐烂的尸体。', '<十字军欧拉金.山瑞斯严肃地听取了你的报告。>$B$B这并非他们应得的安息方式，但是聊胜于无，也对生者要来得好。谢谢你，$N。', '你处理掉天灾军受害者的躯体了吗?', '', '去冰冠冰川找黑色观察站的北伐军战士欧尔拉金·萨利斯。', '火化腐烂的尸体', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13212, '支离破碎', '北伐军战士欧尔拉金被劫持后，银色北伐军就没有指挥官可以负责对缝合场的总攻了。虽然所有的北伐军战士对我来说都是一样的，但是银色北伐军不会这么认为。$B$B我讨厌把时间浪费在这种事情上，可是眼下也别无选择了。我们这位英勇的北伐军战士可能已经被肢解，他的残肢多半是被送去制造憎恶了。请你到缝合场去，干掉那些臃肿的怪物，夺回欧尔拉金的遗体。', '夺回欧尔拉金的躯干、欧尔拉金的腿、欧尔拉金的左臂和欧尔拉金的右臂，将它们交给黑色观察站的黑暗骑士阿尔蕾。', '嗯哼，我想“找回”欧拉金是件好事，虽然我怀疑他的同袍会这么想。我们来看看有什么可以做的，好完成他的遗志，结束这一场鬼游戏，也搞定我们的任务。', '你找回了，呃，欧拉金的躯体吗?', '', '去冰冠冰川找黑色观察站的黑暗骑士阿尔蕾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13220, '重新组合欧尔拉金', '我们必须尽快将欧尔拉金拼接起来。幸运的是，天灾军团为我们提供了一处绝妙的缝合场所。$B$B缝合场的血肉巨人装配台附近有一座复生密室。去那里寻找一团缝合线以及博士的屠刀，然后将欧尔拉金的残肢放在密室中央的平台上进行缝合吧。', '找到一卷缝合线和博士的屠刀，带上它们进入复生密室，将欧尔拉金的残骸缝合起来，看看能不能让他复活。完成任务后返回黑色观察站，向黑暗骑士阿尔蕾复命。', '欧拉金应该为他自己感到庆幸。从未有人自天灾军团的魔掌中被救出来，从来没有。不会有任何人再救他一回了。这点我要他牢牢记着。', '你带回我们勇敢的十字军了吗?', '', '去冰冠冰川找黑色观察站的黑暗骑士阿尔蕾。', '复活北伐军战士欧尔拉金·萨利斯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13222, '保卫攻城车', '注意，$n！我们正准备开始攻打冬拥堡垒。那些部落的野兽以为自己可以像懦夫一样躲在城墙后面，而我不这么认为！我们要让那帮蠢货见识一下侏儒科技的威力，把他们的城墙轰至渣！$B$B不过呢，即便是最强大的攻城器械也不可能自己开到前线去。你的任务就是驾驶或者保护我们的某一辆攻城器械，直到它摧毁三座部落建筑物。', '冬拥湖的资深攻城技师雷格索要你驾驶或保护一辆攻城器械，摧毁3座部落建筑物。$B$B列兵军衔及更高军衔的玩家可以在地精车间中建造攻城器械。', '他们应该见识到地精工艺的威力了!', '没有时间好浪费了，你摧毁堡垒了吗?', '', '去找冬拥湖的资深攻城技师雷格索。', '保卫攻城车', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13223, '保卫攻城车', '联盟不可能守住那座堡垒太久。莫普可以砸穿城墙，但是莫普必须留在营地里。莫普希望干掉那些想要攻击部落攻城车辆的联盟。$B$B你，$N！就是你！你去替莫普上阵。保护三辆攻城车，直到它们摧毁联盟的建筑物。联盟不会想到你要去保护攻城车的，莫普真聪明！', '冬拥湖的莫普中尉要你驾驶或保护一辆攻城器械，摧毁3座联盟建筑物。$B$B拥有军衔的部落玩家可以在地精车间中建造攻城器械。', '很好很好。莫普希望他也能在那里帮上忙。', '你保护那攻城器械了吗?', '', '去找冬拥湖的莫普中尉。', '保卫部落攻城车', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13228, '破碎前线', '什么？战争？！那支部队是去执行侦察任务的！$B$B还有，联盟是怎么回事——你确定他说的是联盟？$B$B听我说，$n！我需要真相，现在就要知道！$B$B返回破碎前线，替我查明真相！去那里寻找幸存者，或者线索，随便你去找什么，总之给我查清楚！', '奥格瑞姆之锤的考尔姆·黑痕要你转至破碎前线，询问一名濒死的狂战士，然后向他汇报你收集到的情报。', '他们看到联盟攻击大门，而他们在门后反击…$B$B<沉默一会后，寇姆爆出一阵大笑。>$B$B那就是部落之道!若非他们，联盟的蛆虫们很可能已经占领大门了!$B$B他们的大胆坚守，为我们争取到了宝贵的时间。', '嗯哼，$N?$B$B你有什么新的讯息要给我?', '', '去冰冠冰川找奥格瑞姆之锤的掠天者考尔姆·黑痕。', '询问濒死的狂战士', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13230, '为我复仇！', '我听到……他们……$B$B那些联盟的伤兵……他们在辱骂我们……$B$B完成我们未竟的使命吧，$c。不要心软……不留活口。$B$B为了……部落……', '破碎前线上的一名濒死的狂战士要你杀死5名濒死的士兵。完成任务后返回奥格瑞姆之锤，向掠天者考尔姆·黑痕报到。', '容忍联盟的时代已经过去了，$N。$B$B他们已令人忍无可忍了!他们应该活在对部落的恐惧之中，直到他们不再污染这个世界!', '什么事，$C?', '', '去冰冠冰川找奥格瑞姆之锤的掠天者考尔姆·黑痕。', '杀死濒死的联盟士兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13231, '破碎前线', '什么？！这怎么可能！$B$B为了确保此次攻击行动的机密性，我们费了好大的一番工夫。部落究竟是怎么知道的？我们投入的资源……军队……全军复没？难以置信！$B$B冰冠冰川作战计划的关键在于抢在部落前面占领死亡之门。我们必须尽快恢复元气，准备发动下一次攻击。$B$B去战场上寻找幸存者，看看能不能收集到与这场惨剧有关的情报。$B$B$n，做好准备，我们要打一场双线作战的硬仗了……', '破天号的高级指挥官加斯汀·巴雷特要你转至破碎前线，询问一名濒死的士兵，然后向他汇报你收集到的情报。', '所以…这是惨败 - 一场完全的败仗。这该被刻骨铭心地记着。$B$B记下我的话，$C。部落一定要为此付出代价…他们将被杀得片甲不留!', '嗯，$N?$B$B你得知了什么?', '', '去冰冠冰川找破天号的高级指挥官加斯汀·巴雷特。', '询问濒死的士兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13232, '让我解脱吧！', '他们辱骂我们——虽然他们也奄奄一息地躺在地上……$B$B求求你……不要让他们的奚落成为我临死前听到的最后的声音……$B$B杀了我吧……让我摆脱折磨……回到圣光的怀抱吧。$B$B寻找我的同伴……也赐予他们同样的仁慈吧。$B$B不要给天灾军团留下任何可以复活的生命！$B$B求求你……', '破碎前线上的一名濒死的士兵要你杀死其它5名濒死的士兵。完成任务后返回破天号，向高级指挥官加斯汀·巴雷特报到。', '你做了件于情于义都十分困难的事，$C。但这是正确的。$B$B别让你的记忆一再地侵扰你。要化悲愤为力量!对真正该为此负责的人愤怒。$B$B部落必定要得到报应!', '怎么回事，$C?', '', '去冰冠冰川找破天号的高级指挥官加斯汀·巴雷特。', '杀死濒死的士兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13233, '决不留情！', '你还记得我撂下的狠话吧，我可以告诉你，这绝不是一时气愤讲出的大话。$B$B部落一次又一次地亵渎我们珍重的事物，肆意践踏圣光的尊严，我要让他们付出生命的代价！$B$B所有的部落。$B$B想象一下没有他们的世界，$n。联盟的孩子将拥有无忧无虑的生活，他们会永远铭记你的英勇事迹，感谢你为他们带来的幸福生活。$B$B去吧，让这美好的想象成为现实吧！', '破天号的高级指挥官加斯汀·巴雷特要你在冰冠冰川地区杀死15名部落玩家。', '做得好， $N!$B$B猎捕他们并给他们尝尝苦头!', '我相信你已让雪地染满敌人的鲜血了，$N。', '', '去冰冠冰川找破天号的高级指挥官加斯汀·巴雷特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13234, '血的代价！', '是时候了！$B$B这帮自以为是的联盟令我们忍无可忍！世界因为他们的存在而变得脆弱而绝望，是时候清理这些渣滓了。$B$B让我们为部落曾经蒙受的耻辱划上句号！让他们知道什么才是真正的恐惧！荣耀属于部落！$B$B就在这里，就在冰冠冰川，我们将要铲除所有联盟！$B$B去吧，$c。击溃他们的意志，终结他们的生命！', '掠天者考尔姆·黑痕要你在冰冠冰川地区杀死15名联盟玩家。', '你做得不错，$C。$B$B很快地，联盟会见你就跑而你的名字将会让部落骄傲!', '让那些联盟尝尝苦头了没，$C?', '', '去冰冠冰川找奥格瑞姆之锤的掠天者考尔姆·黑痕。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13235, '最强大的血肉巨人', '你在摧毁缝合场及消灭巫妖王爪牙的行动中表现得很好。现在，我们要做的就是击败缝合场里最可怕的怪物——那个名叫摩比乌斯的血肉巨人。$B$B这场战斗不轻松，不过暗影拱顶已经把玛格拉弗·塔卡尔和一些援军派到那里去了，你可以到缝合场最西端的制高点去找他。只要告诉他可以开始进攻了，他就会指挥他的部下投入战斗。', '与缝合场西端的玛格拉弗·塔卡尔交谈，然后参加对摩比乌斯的战斗。击败摩比乌斯之后，返回黑色观察站，向黑暗骑士阿尔蕾复命。', '随着巫妖王的血肉巨人斗士倒下，他应该也了解了，他其馀的鹰犬也都是不堪一击的。有你在我们阵中，我们将给巫妖王再上一课，关于恐惧真实意义的一课。', '你解决巫妖王引以为傲的血肉巨人了吗?', '', '去冰冠冰川找黑色观察站的黑暗骑士阿尔蕾。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13236, '召唤大军', '你可能觉得自己已经很强大了，足以横扫这些亡灵，驾驶你的战争机器轻易地击败它们。$B$B但是创造出这些亡灵生物的力量更为强大，与之相比，你的力量不值一提。$B$B我见过那位王子本人这样做过。我可以营造一个幻境，向你演示他是怎么做到这一点的……如果你愿意领略一下的话。', '第一军团前线营地的米斯希尔萨·阿奈尔要在幻境中向你演示巫妖王如何召唤一支由100个食尸鬼奴仆组成的部队。', '王子他真正的力量并非在于从尸首中唤起军队…那很容易。$B$B而是让与他并肩作战多次的战士成为尸首…他真正的力量，就是能不择手段完成需要完成的事。', '你明白了吗，$N?', '', '去冰冠冰川找失落希望之谷的米斯希尔萨·阿奈尔。', '召唤食尸鬼奴仆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13237, '知己知彼', '在你的指挥官将注意力转移到联盟与部落之间的冲突时，我仍然在高度关注着真正的敌人——巫妖王和他的仆从。$B$B要想攻陷冰冠堡垒，部落就必须首先占领每一座大门。$B$B就从第一座大门着手吧。返回破碎前线，向那里的天灾军团驻军发起挑战，寻找它们的弱点。$b$b我等你汇报消息，$c。', '奥格瑞姆之锤的库尔迪拉·织亡者要你转至破碎前线，杀死5名笨重的憎恶、5名邪恶通灵师和5名暗影专家。', '是吗，$C?$B$B没什么值得回报的?$B$B<寇尔提拉注意到溅在你衣服上的憎恶残骸并微笑。>$B$B我倒不这么认为……', '好啦，$r?$B$B你知道了些什么?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '杀死笨重的憎恶', '杀死邪恶通灵师', '杀死暗影专家', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13239, '爆炸油', '从哪里说起呢……好吧，作为首席技师，我有权阅读所有的情报——我有权。还记得上次你报告说在南边发现冰霜巨龙吗？我对此很感兴趣，而且我相信自己已经想出了对付它们的法子……现在，你只需要帮我干一些跑腿的工作。嗯嗯，首先你要用废旧护甲制作一个假人，再涂上这种液体，然后迅速找个掩体！$b$b……你人呢，$c？', '首席技师考伯克拉要你在破碎前线使用考伯克拉的爆炸油吸引3只霜巢天爪龙。$B$B你需要收集被丢弃的头盔、被丢弃的护甲和一堆白骨才能使用爆炸油，这些材料都可以在破碎前线找到。', '哇呼!我从这里就可以看见它们着了火乱窜!我取得了另一个成功，并且要开始量产这玩意以应付进攻了 - 当然，如果你有兴趣的话，这会多做些测试的…', '它成效如何?你有试它吗?你有照我说的做吗?$B$B嗯?有没有嘛?', '', '去冰冠冰川找奥格瑞姆之锤的首席技师考伯克拉。', '完成实验', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13240, '提迈尔的预言：离心构造体！', '你必须到飘浮在考达拉上空的魔环里去一趟，$N。$B$B我已经预见到，你必须去摧毁魔环里的离心构造体。我敢保证，如果你不先行消灭这些魔法生物，你和你的朋友们就难逃失败的命运。$B$B这就是我的预测，也是你必须做的事。', '根据达拉然的大法师提迈尔的预言，你必须去消灭10台离心构造体。', '<在你开口前，大法师便点了点头。>$B$B馀已明白。汝摧毁了傀儡，一如馀所见，并能前去与瓦罗斯.云行者决一死战。$B$B做得很好，$N!', '馀察觉你尚未摧毁所有的傀儡。', '', '去找晶歌森林的大法师提迈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13241, '提迈尔的预言：伊米亚狂战士！', '你离胜利只剩一步之遥了。伊米隆国王麾下的勇士们是你唯一的阻碍。$B$B你要深入嚎风峡湾的森林，进入那座名为乌特加德之巅的堡垒。你和你的伙伴必须消灭那些伊米亚狂战士，这对你们至关重要。$B$B如果这次行动失败了，那你们就死定了，$N！', '达拉然的大法师提迈尔要你去杀死7个伊米亚狂战士。', '如此甚好，$N。$B$B若非如此，汝与其王做生死斗时，残存狂战士将一拥而上。', '<大法师将手指压在太阳穴上，一副全神贯注的样子。>$B$B狂战士尚未死绝。留意馀之报警，$N。汝须了结此事!', '', '去找晶歌森林的大法师提迈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13242, '黑暗的骚动', '黑暗的力量在骚动，$N。一场只有时空之王才可能预见的悲剧发生了。很快，悲伤与仇恨将笼罩着你的同胞。战争迫在眉睫。$B$B红龙军团已经尽了最大的努力，接下来就要靠艾泽拉斯的凡人种族了。$B$B很遗憾，你的旅程将由这场悲剧开头。就在今天，一位父亲永远地失去了他心爱的孩子。你必须将这个悲伤的消息告诉他。找回小萨鲁法尔的战甲，将它交给萨鲁法尔吧。', '在战场上收集萨鲁法尔的战甲，然后转至北风苔原的战歌要塞，将它交给萨鲁法尔大王。', '<萨鲁法尔望向天际。>$B$B就像布洛克斯一样，我儿英勇殉难。不需要为他哀悼，$N。对于我们兽人，除了光荣战死外，没有更好的尽头，也没有更高的荣耀。$B$B谢谢你将我们的战甲带回。战甲将同他的火堆被置于纳格兰的先祖之地。$B$B现在我们必须将注意力放在更紧急的事情。', '<萨鲁法尔的表情扭曲起来。>$B$B我的爱子…我的力量…', '', '去北风苔原找战歌要塞的萨鲁法尔大王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13243, '提迈尔的预言：永恒密探！', '永永恒之龙已经威胁到了时间流。如果你再不介入的话，我们的历史就会变得一团糟！$B$B你必须进入时光之穴，介入净化斯坦索姆这段历史。$B$B光是尝试探索各种历史的可能性，已经让我头痛不已。但我可以肯定，你一定要去杀掉那些永恒密探。$B$B只有除掉那些破坏份子，我们才能保住真正的历史，防止现在和未来被篡改！', '根据达拉然的大法师提迈尔的预言，你必须去杀死4个永恒密探。', '吾辈当前皆已无恙。谢谢你。$B$B不幸地，由于其扰乱之故，恒龙将有几近无限之机会再次为非作歹。$B$B唯馀所能预见，汝将为阻挡其行动之中流砥柱，$N!', '光阴永为珍稀之资源，然而此刻尤甚，$N。请尽快除去恒龙密探于未成心腹大患之前。', '', '去找晶歌森林的大法师提迈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13244, '提迈尔的预言：泰坦神铁先锋！', '整个艾泽拉斯都处在危险之中。疯狂的神灵洛肯已经具备了毁灭世界的能力！$B$B在闪电大厅的大地了望塔里，那些泰坦神铁先锋正在有条不紊地执行着洛肯的疯狂计划，无数生灵即将成为他们的牺牲品。$B$B我已经预见到了，$N。你就是阻止这个疯狂计划的人！', '根据达拉然的大法师提迈尔的预言，你必须去杀死7个泰坦神铁先锋。', '吾辈皆欠汝一份人情，$N。$B$B若问馀有何确定之事，即为汝未曾令吾辈失望，也将不会令汝自己失望!', '馀实在无法洞见汝为何仍于此空谈，当汝尚未排除泰坦钢先锋之威胁之际。', '', '去找晶歌森林的大法师提迈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13245, '死亡证明：劫掠者因格瓦尔', '我要你去召集一支队伍，转至乌特加德城堡。你要去找到并杀死劫掠者因格瓦尔，否则他就会带领维库人的部队去攻击附近的联盟和部落城镇。$B$B解决他之后，把他的斧子拿来作为凭证。我并不是不相信你，只是小心谨慎一点总没错。', '达拉然的大法师兰达洛克要你将掠夺者的战斧交给他。$B$B该任务必须在英雄难度下完成。', '非常好。就将斧头倚着墙边放着。$B$B我确定，知道你除掉那野蛮人后，瓦尔加德和复仇台地今夜将可安眠。', '你拿到了斧头吗?因格瓦已经死了吗?', '', '去找达拉然的大法师兰达洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13246, '死亡证明：克莉斯塔萨', '你听说克莉斯塔萨的遭遇了吗？$B$B她帮助我们消灭了玛里苟斯的配偶，莎拉苟萨。为了报复，玛里苟斯抓住了她，让她成为自己的配偶，还将她冻在一块冰里。$B$B我们最近发现，玛里苟斯正在用魔法消磨她的意志，她已经快被逼疯了。$B$B$N，你必须趁她还没有完全转变，赶快转至考达拉的魔枢，去结束她的生命。$B$B虽然我感到非常难过，但你必须把她的心脏带回来作为凭证。', '达拉然的大法师兰达洛克要你将克莉斯塔萨的破碎之心交给他。$B$B该任务必须在英雄难度下完成。', '非常遗憾，但却是不能避免的。$B$B肯瑞托可以承受一头杰出的红龙栽在最强大的敌人手中。但是玛里苟斯在奥核战争中利用她来对付我们，却是毁灭性的灾难。$B$B我非常遗憾，我们必须了结她而非拯救她。', '若我们有其它救赎她的方法，我们就不会要求你给她个了结了。$B$B然而，我们了解玛里苟斯驾驭魔法的能力有多高。随着他对艾泽拉斯地脉的控制，在秘法方面的造诣已无人能出其右。', '', '去晶歌森林找绝望之林的大法师兰达洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13247, '死亡证明：魔网守护者埃雷苟斯', '魔枢之战愈演愈烈，我们必须想办法扭转局势！你愿意飞往战斗最激烈的地区吗，$N？$B$B魔网守护者埃雷苟斯守护着一条管道，玛里苟斯正是通过这条管道源源不断地汲取魔网中的能量。如果我们能杀了魔网守护者，就可以对敌人造成重创。$B$B请把他的魔网调谐器带回来给我，让我们好好研究一下。', '达拉然的大法师兰达洛克要你将魔网调谐器交给他。$B$B该任务必须在英雄难度下完成。', '谢谢你，$N。调谐器的检测应该能够提供我们更多有关玛里苟斯如何操弄地脉的内幕。$B$B倘若我们能够找出他的破绽，也许我们能够以其扭转战局。', '你处理掉地脉守护者了没，$C?$B$B我想不需要提醒你玛里苟斯意图禁止世界上所有的魔法使用，而且蓝龙军团将不择手段地杀掉任何是敌非友的魔法用户吧?', '', '去晶歌森林找绝望之林的大法师兰达洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13248, '死亡证明：伊米隆国王', '乌特加德之巅的伊米隆国王是巫妖王的支持者。单凭这一点，我们就该杀了这个维库人。$B$B如果让他吹响号角，将伊米亚、尤尔丁等部落的领袖都召集起来，维库人就会成为天灾军团中最强的一支部队！$B$B现在就看你的了，$N，你一定要阻止他。将他脖子上的坠饰带回来给我，以此证明伊米隆的威胁已经彻底解除了。', '达拉然的大法师兰达洛克要你将已故女王的饰物交给他。$B$B该任务必须在英雄难度下完成。', '<当你交付这块不小的首饰时，大法师肃然地点了点头。>$B$B该做的都做了。维库原本是个高贵的民族。只可惜在巫妖王的魔掌之下，也只有屈服一途。', '依米伦绝对不能一统维库帝国。倘若他势如破竹地返抵冰冠冰川，也许我们就大势已去了。', '', '去晶歌森林找绝望之林的大法师兰达洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13249, '死亡证明：先知萨隆亚', '达克萨隆要塞曾经是达卡莱王国最值得骄傲的堡垒。现在，那里只不过是巫妖王攻占祖达克、窃取巨魔诸神能量的基地。$B$B如果我们能杀死他们的首领——先知萨隆亚，或许就能切断天灾巨魔的后援。这至少能让祖达克的银色北伐军少一点麻烦。$B$B把先知的蒂基面具带回来给我，以此证明你已经把他干掉了。', '达拉然的大法师兰达洛克要你将先知的魔化蒂基面具交给他。$B$B该任务必须在英雄难度下完成。', '幸运地，现在他们已经群龙无首，对于在当地对抗天灾军团的战士们而言，达克萨隆要塞现在已经不再有如芒刺在背般构成威胁。$B$B<大法师低头看着你手上提基像。>$B$B提基像已经失去了魔力也好。我也没有概念应该如何来运用它，说不定甚至根本不该运用它。', '你跟预言者打过照面了?拿到提基像了吗?', '', '去晶歌森林找绝望之林的大法师兰达洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13250, '死亡证明：迦尔达拉', '祖达克的达卡莱先知们做出了一件不可思议的事：他们杀死了大部分神灵，吸取了他们的能量！阿卡里的高阶先知迦尔达拉是他们当中最危险的一个。$B$B迦尔达拉就躲藏在古达克里面，他吸取了阿卡里的大部分魔精，现在正准备和他的追随者们冲出那座城市。如果我们不立刻杀了他，就会被这股疯狂而不可思议的力量淹没！$B$B快一点，$N，去把阿卡里残馀的魔精给我带回来。', '达拉然的大法师兰达洛克要你将阿卡里的魔精残渣交给他。$B$B该任务必须在英雄难度下完成。', '谢谢你，$N。我将会安全地看守这些神只的菁华，直到有天可以交付给赞达拉部族。$B$B也许他们会有方法将其与阿卡里再次结合?', '你有带回魔精吗?$B$B见到另一个伟大巨魔国度的灭亡，实在令人不胜唏嘘。$B$B若非巫妖王的兴风作浪，巨魔们也不会落得这步田地，必须被迫忤逆他们的神只，并偷取他们的力量以防御天灾军团。', '', '去晶歌森林找绝望之林的大法师兰达洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13251, '死亡证明：玛尔加尼斯', '$N，一位青铜龙军团的朋友向我传达了一个很有价值的情报。$B$B被燃烧军团称为恐惧魔王的那种神秘生物，也就是魔族纳斯雷兹姆，关于他们生存的那个世界呢，人们知之甚少，而且可以说几乎都是无凭无据的传言。$B$B但玛尔加尼斯曾犯过一个致命的错误：他留下了一件来自他们世界的圣物！$B$B你要进入时光之穴，返回阿尔萨斯王子净化斯坦索姆的那个时刻，拿到那件圣物。', '达拉然的大法师兰达洛克要你将纳斯雷兹姆家园的圣物交给他。$B$B该任务必须在英雄难度下完成。', '妙不可言!我从没看过像这样的东西。我会看守它，直到交付给紫罗兰监狱为止。$B$B但若你能改变历史的进程。也许阿尔萨斯就可以…不，这只会导致更多的疯狂。$B$B当然时光守护者一定非常了解这些事情。', '我们应该好好利用玛尔加尼斯的错误。这样的机会可不是每天都有。$B$B如果我们能好好研究那件神器，我们一定会对纳斯雷兹姆有更深入的了解!', '', '去晶歌森林找绝望之林的大法师兰达洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13252, '死亡证明：塑铁者斯约尼尔', '我们对于所谓“血肉诅咒”的情况知之甚少，不过岩石大厅里保存着与之相关的信息。$B$B塑铁者斯约尼尔似乎相当了解这种诅咒。我们有充分的证据表明，他身上有着一块泰坦制造的信息圆盘，上面的信息足以解答我们的所有疑问。$B$B帮我把圆盘拿来，$N，这样我们就能对血肉诅咒进行研究了。', '达拉然的大法师兰达洛克要你将血肉诅咒圆盘交给他。$B$B该任务必须在英雄难度下完成。', '泰坦科技真迷人，不是吗?所有的资讯竟然都藏在这小小的圆盘里!$B$B我只希望我们能知道，怎么读取上面的资料。', '你带回圆盘了吗?', '', '去晶歌森林找绝望之林的大法师兰达洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13253, '死亡证明：洛肯', '闪电大厅的洛肯正在密谋毁灭我们的世界。还用得着我多说吗，$N？$B$B他对那位被囚禁在诺森德的上古之神言听计从。你和你的朋友必须立刻转至风暴峭壁！$B$B进入大地了望塔，与洛肯交战，阻止他的计划，不然一切就都完蛋了！把他的红宝石戒指带回来给我，这样我才能确信我们已经没有危险了。', '达拉然的大法师兰达洛克要你将天界红宝石戒指交给他。$B$B该任务必须在英雄难度下完成。', '<大法师朗达拉克如释重负地吐出了一口气。>$B$B坦白说，我很担心厄运会降临在你头上。这实在教人坐立难安，当其它人，比方说你，被迫应付这些每日每夜都威胁着世界，生死攸关的大事。$B$B现在，我们要怎么处理这枚巨大的戒指呢?', '我再复述一次，$N。这是意味我们已免于疯狂洛肯的威胁，还是毁灭的结局?', '', '去晶歌森林找绝望之林的大法师兰达洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13254, '死亡证明：阿努巴拉克', '天灾蛛魔对我们的部队是一个巨大的威胁。$B$B虽然我们飘浮在天空中时是很安全的，但是如果我们将落到地面上，就要担心那些亡灵蛛怪会从艾卓-尼鲁布钻出来攻击我们。$B$B如果能让它们陷入混乱，对大家都有好处。去杀死它们的前任国王，地穴领主阿努巴拉克。他也是巫妖王的得力助手之一。$B$B把阿努巴拉克的王冠带回来……它已经不再戴着那东西了。', '达拉然的大法师兰达洛克要你将阿努巴拉克的王冠交给他。$B$B该任务必须在英雄难度下完成。', '你等要经历何等的恐怖遭遇才能穿过上层城市。$B$B<朗达拉克瞥了一眼你手上黯淡无光的皇冠。>$B$B也许我们应该把它放到一旁，等那些奈幽虫族选出一位新王?', '我很高兴下去艾卓尼布鲁的是你而不是我。$B$B我不喜欢地下国度的族类。', '', '去晶歌森林找绝望之林的大法师兰达洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13255, '死亡证明：传令官沃拉兹', '安卡赫特的蛛怪通过挖掘地洞躲避天灾军团的入侵，结果挖得太深了，过于靠近诺森德地下的上古之神。$B$B被惊醒的上古之神派出了疯狂的怪物去攻击他们，这些蛛怪可真是进退两难。$B$B上古之神的部队首领——传令官沃拉兹是一种名为无面者的可怕生物。去杀了他，把他的萎缩大脑带回来。$B$B但在执行这个任务的时候，你一定要保持清醒。', '达拉然的大法师兰达洛克要你将无面者的萎缩大脑交给他。$B$B该任务必须在英雄难度下完成。', '<大法师小心翼翼地看着那颗脑子。>$B$B现在我在想，我实在不太确定靠它这么近有没有关系。你说它还活着?$B$B<他摇了摇头。>$B$B我们在城塞里有个安置它的地方。我会看守着它，直到我的学徒把它弄走。', '$N?你还清醒吗?', '', '去晶歌森林找绝望之林的大法师兰达洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13256, '死亡证明：塞安妮苟萨', '我们遭到了入侵！蓝龙军团已经传送进了紫罗兰监狱，正计划从那里冲进达拉然！$B$B有报告说，他们已经不小心释放了一些囚犯。不过就算他们是故意放出那些囚犯，我也不会感到意外的。$B$B$N，你能否迅速召集一支队伍赶到那里去？塞安妮苟萨是这些入侵者的首领，把她的徽记给我带回来！', '达拉然的大法师兰达洛克要你将塞安妮苟萨的徽记交给他。$B$B该任务必须在英雄难度下完成。', '危机已经解除而脱逃的犯人们都重新锒铛入狱。$B$B达拉然感谢你，$N!$B$B现在我得去找某人谈谈何故有人能轻易的突破城市的反传送护盾进入监狱里?!', '仔细想想，你曾经传送进某个监狱然后试着从里面攻出吗?监狱该是城市里面防守最严密的地方。$B$B我想蓝龙们的确是疯了!', '', '去晶歌森林找绝望之林的大法师兰达洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13261, '爆炸油', '啊哈！成功啦！我并不怀疑自己的发明，只是不确定具体的爆炸效果嘛——你瞧，你的眉毛完好无损，这点就很令我欣慰。只需让考尔姆看看冰霜巨龙被点燃的惨状，他就会把我提升到……呃……仅次于首席技师的职位！来吧，你再带上一瓶液体去破碎前线，我去找考尔姆来……$B$B好啦！出发！', '首席技师考伯克拉要你在破碎前线使用考伯克拉的爆炸油吸引3只霜巢天爪龙。$B$B你需要收集被丢弃的头盔、被丢弃的护甲和一堆白骨才能使用爆炸油，这些材料都可以在破碎前线找到。', '不是很好!$B$B寇姆老是推托他太忙，我今天好不容易把他拖上来看了一会，结果你把油用光了。现在他对我很不爽，而且不准我今天再出现在他面前…$B$B回去吧，我们再试试看!', '你烤熟那些龙了吗，$r?', '', '去冰冠冰川找奥格瑞姆之锤的首席技师考伯克拉。', '完成实验', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13264, '你的憎恶伙伴', '憎恶……$b$b可怕的敌人。我不止一次目睹它们迅速地扭转了战局。事实上，它们也可以成为有用的伙伴，这一点倒是鲜为人知。$B$B憎恶并不聪明。只要你了解制造憎恶的秘密，就可以对它们发出简单的指令。相信我，它们会毫不犹豫地执行你的命令。$B$B你很幸运，我恰好知晓其中的奥秘。$B$B对憎恶的残骸使用这个工具包，将其复活。接下来你就可以利用它对付驻守在死亡之门的天灾军团了。', '奥格瑞姆之锤的库尔迪拉·织亡者要你使用憎恶复活工具包制造一名复活的憎恶，然后利用它杀死15只冰寒食尸鬼、15只残忍的恶鬼和15名复活的联盟士兵。', '我能够看出你操纵憎恶的技术有不错的成长。$B$B努力点，我的朋友，很快的死亡之门就会属于部落。', '怎么了，$C?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '引爆冰寒食尸鬼', '引爆残忍的恶鬼', '引爆复活的联盟士兵', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13268, '布匹搜寻', '', '', '把你搜刮来的布料，做成些让你看来与众不同的玩意!', '你衣角的碎片告诉我你是一名裁缝师，而且可以轻易地学会我要教你的技术。$B$B北方的人型生物所穿着的衣服，可以很容易地转化成布料，只要你知道诀窍的话。$B$B只需要一点点的费用，我就会教你布料搜掠的技巧，如此一来，你就可以从诺森德的人型生物那儿搜刮一些布料来。', '', '', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13273, '追查诺甘农之核', '既然我们已经拿到了诺甘农之壳，现在就只需要寻找另一半钥匙了。幸运的是，我已经让探险者协会的伙计们四处查探，找到了诺甘农之核的所在之处。$B$B在创世者的图书馆东南方的远端，丹尼芬雷北面的斜坡上，有一处以我的名字命名的营地。探险者协会正在那里寻找另外一半钥匙。帮我把他们整理好的地图和信息带回来，我们应该可以找到另外一半钥匙。', '在布莱恩的营地寻找勘探员克罗娜的便笺和勘探员索雷的地图。', '被毁了?这是什么意思?营地被毁了?$B$B<布莱恩愤怒地握紧了拳头，>$B$B那些铁矮人会因此付出代价!但我们当前还束手无策，况且我们必须先把焦点放在完成钥匙上，一旦我踏进奥杜亚的大厅，我会要那些烂铁块和他们的老大对他们所做所为给个交代!', '你取回那些笔记了吗?', '', '使用布莱恩的通讯器联络布莱恩·铜须。$B$B如果你弄丢了联络器，你可以与格罗玛什坠毁点的莫塔哈·风魂重新要个新的。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13274, '诺甘农之核的守护者', '勘探员索雷的便笺中提到，诺甘农之核的看管者名叫亚申，它是米米尔制造出来的魔像。$B$B索雷还说亚申所在的地方被称为“洛肯的宝库”。$B$B洛肯，嗯？土灵提到过这个家伙。$B$B据说宝库就在被毁坏的探险者协会营地西南方，它的圆形入口就在俯瞰着上古寒冬山谷的某座山上。$B$B找到这个亚申，从他手里把诺甘农之核拿回来。如果你不得不动手的话，我一点也不会感到吃惊的。', '拿到诺甘农之核。', '这次错不了!钥匙就要到手了。现在我们要做的就是找出结合壳与核心的方法来组成钥匙。让我们来看看勘察员索林还说了些什么…', '勘察员索林是对的吗?你终究找到诺甘农之核了吗?', '', '使用布莱恩的通讯器联络布莱恩·铜须。$B$B如果你弄丢了联络器，你可以与格罗玛什坠毁点的莫塔哈·风魂重新要个新的。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13275, '藏匿行踪', '你不该碰它的。但你已经碰过了，他很快就会来找你。$B$B他一定会找到你，除非你能躲藏起来，不让他发现。$B$B如果你还想活下去，就去弄一些无面者的鲜血回来！', '米斯希尔萨·阿奈尔要你收集3份无面者之血。', '你还等什么?快擦在身子上!$B$B快呀!不然他就要看到你了!', '你拿到血了吗?', '', '去冰冠冰川找纳扎纳克：遗忘深渊的米斯希尔萨·阿奈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13276, '你的憎恶伙伴', '你知道该怎么做吧，$c。$B$B对憎恶的残骸使用这个工具包，制造一只听命于你的憎恶，然后命令它去攻击驻守在死亡之门的敌人。$B$B在我们对死亡之门发动攻击之前，你可以好好地熟悉一下这种战术。', '奥格瑞姆之锤的库尔迪拉·织亡者要你使用憎恶复活工具包制造一名复活的憎恶，然后利用它杀死15只冰寒食尸鬼、15只残忍的恶鬼和15名复活的联盟士兵。', '我能够看出你操纵憎恶的技术有不错的成长。$B$B努力点，我的朋友，很快的死亡之门就会属于部落。', '怎么了，$C?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '引爆冰寒食尸鬼', '引爆残忍的恶鬼', '引爆复活的联盟士兵', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13277, '对抗巨人', '尽管击败地面上的天灾士兵至关重要，但我们也不能疏忽了死亡之门的威胁。$B$B城墙上的血肉巨人可以投掷巨大的石块和冰块，对下面的部队造成毁灭性的伤害。$B$B集合一支队伍去干掉那些巨人。我们必须要对敌人有足够的了解。$B$B啊，对了……把它们的脊骨给我带回来。如果我没记错的话，那东西有一些特别的用处。', '奥格瑞姆之锤的库尔迪拉·织亡者要你转至莫德雷萨，从血肉巨人身上取回5根奇特的脊骨给他。', '非常好，这些看来是可行的样本，$B$B以彼之矛，攻彼之盾的时候到了…', '对抗巨人的进度顺利吗，$r?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13278, '污染者科普洛斯', '有报告指出死亡之门有一只非常强大的僵尸，$c。$B$B我们必须设法解除它带来的潜在威胁。如果你能亲自与它交手，应该可以了解到更多的有价值的情报。$B$B转至死亡之门西面的大厅，向这只怪物发起挑战，找出它的弱点。', '奥格瑞姆之锤的库尔迪拉·织亡者要你转至莫德雷萨，杀死污染者科普洛斯。', '做得好，$C。$B$B也许透过些适当地调查，我们便能发现他们如何让这样的生物来到世上。', '你找得到那僵尸吗，$C?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '杀死污染者科普洛斯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13279, '化学常识', '<库尔迪拉取过脊骨，把里面的脓液倒进瓶子里。>$B$B我们对血肉巨人的特性有一点点了解……$B$B它们的脊骨脓液可以以一种非常有趣的方式与瘟疫病菌溶合，将瘟疫转换成一种腐蚀剂。$B$B虽然说从高高的城墙上泼下腐蚀剂会让下面的士兵非常郁闷，但至少受害者不会变成天灾军团的爪牙。$B$B把这只瓶子里的东西倒进死亡之门西面大厅内的瘟疫之锅里去。', '奥格瑞姆之锤的库尔迪拉·织亡者希望你转至莫德雷萨，将脊骨脓液倒进那里的瘟疫之锅。', '你做的很好， $C。$B$B当我们的军队抵达并向碉堡进军时，我们已经胸有成竹能夺下死亡之门。', '你顺利地中和了一批瘟疫样本了吗，$C?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '中和瘟疫之锅', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13280, '占山为王', '瞧见伊米海姆西北方那座陡峭的山峰了么，你只要驾驶我的跳跃机器人尽快爬上山顶就行啦，$N！$B$B布拉斯·炸雷是个懦弱的坏蛋，他正在摆弄自己的破烂机器人呢，大概马上就要完工了吧。我们正在比赛，看谁能抢先占领那座山头！$B$B等你跳上去之后，将我们的军旗插到徽记堆里。让大家知道，联盟才是最棒的！我的工程学技术才是最棒的！', '伊米海姆的弗拉索·磨轮要你使用弗拉索的跳跃机器人，将联盟军旗插到山顶的徽记堆上。', '你办到了!你办到了!$B$B<芙芮索跳了起来并给了你一个大大的拥抱。>$B$B喔，你真是我最爱的$g英雄:女英雄;!$B$B你想你明天还会再来吗?', '等等…你还没插上战旗吗!$B$B还在等什么?', '', '去冰冠冰川找伊米海姆的弗拉索·磨轮。', '插下联盟军旗', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13281, '中和瘟疫', '没有我的帮助，你也可以中和敌人的瘟疫之锅了，$r。$B$B去消灭死亡之门一带的血肉巨人，用它们脊骨中的脓液中和瘟疫。$B$B你所打击的是敌军最重要的核心部分。这是一个重要的任务——对我们的事业而言生死攸关的任务。只要时间允许，就应该尽力去完成。$B$B记住，你可以在莫德雷萨找到血肉巨人和瘟疫之锅。', '奥格瑞姆之锤的库尔迪拉·织亡者希望你转至莫德雷萨，将脊骨脓液倒进那里的瘟疫之锅。$B$B你可以使用从起脓的血肉巨人身上收集而来的脊骨制造脓液。', '战争的号角响起时我们将又少一个瘟疫大锅要对付。$B$B你的指挥官会很高兴。', '您好，$C。$B$B我可以向上回报又一个瘟疫大锅失效了吗?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '中和瘟疫之锅', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13284, '地面突袭', '你好，$c。$B$B最近我们一直在对伊米海姆发动猛攻，但是这些维库人比我们之前遇到过的要凶残得多。每次部队试图向伊米海姆推进时都会遭到伏击，我们的人员损失非常惨重。$B$B如果你愿意参战，帮助我的小分队安全抵达伊米海姆的大门，我们会好好奖励你的。抵达大门之后，我们就会挖掘壕沟，等待后援部队。', '护送破天号部队抵达伊米海姆的门口。完成任务后返回伊米海姆东面的冰川边缘，向地面指挥官库普复命。', '请接受我的感谢。$B$B我承认这是个残忍的作战，但话说回来我们也别无选择－他们比起我们这一连串的突袭其实也丝毫不逊色，我们必须驱逐这些维库族才能进压冰冠冰川。$B$B我们应该还会需要更多的援助。请再借助你的力量并且在战场上证明你的价值。', '你让我那些弟兄安全抵达了吗?', '', '去冰冠冰川找失落希望之谷的地面指挥官库普。', '护送联盟部队前往伊米海姆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13287, '知己知彼', '像你这样拥有丰富作战经验的英雄必定了解这一点：没有什么途径比亲自与敌人交手更能摸清对方底细了。$B$B虽然你渴望获得攻占冰冠堡垒的荣耀，但是我们必须首先突破巫妖王的每一扇大门。所谓知己知彼，百战百胜……$B$B我要你返回破碎前线，与敌人交战。寻找他们的弱点，然后向我汇报详细的情况。', '破天号上的萨萨里安要你转至破碎前线，杀死5名笨重的憎恶、5名邪恶通灵师和5名暗影专家。', '是吗，$C?$B$B没什么值得回报的?$B$B<萨沙理安注意到溅在你衣服上的憎恶残骸并微笑。>$B$B我倒不这么认为…', '你回来了， $C…$B$B有任何事情可以报告吗?', '', '去冰冠冰川找破天号的萨萨里安。', '杀死笨重的憎恶', '杀死邪恶通灵师', '杀死暗影专家', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13288, '你的憎恶伙伴', '憎恶……$b$b可怕的敌人。我不止一次目睹它们迅速地扭转了战局。事实上，它们也可以成为有用的伙伴，这一点倒是鲜为人知。$B$B憎恶并不聪明。只要你了解制造憎恶的秘密，就可以对它们发出简单的指令。相信我，它们会毫不犹豫地执行你的命令。$B$B你很幸运，我恰好知晓其中的奥秘。$B$B对憎恶的残骸使用这个工具包，将其复活。接下来你就可以利用它对付驻守在死亡之门的天灾军团了。', '破天号上的萨萨里安要你使用憎恶复活工具包制造一名复活的憎恶，然后利用它杀死15只冰寒食尸鬼、15只残忍的恶鬼和15名复活的联盟士兵。', '如你所见，$C?聪明才智有时可以在看似势不可挡的敌军前反败为胜。', '如何，$r?$B$B你那些憎恶朋友们好用吗?', '', '去冰冠冰川找破天号的萨萨里安。', '引爆冰寒食尸鬼', '引爆残忍的恶鬼', '引爆复活的联盟士兵', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13289, '你的憎恶伙伴', '你知道该怎么做吧，$c。$B$B对憎恶的残骸使用这个工具包，制造一只听命于你的憎恶，然后命令它去攻击驻守在死亡之门的敌人。$B$B在我们对死亡之门再次发动攻击之前，你可以好好地熟悉一下这种战术。', '破天号上的萨萨里安要你使用憎恶复活工具包制造一名复活的憎恶，然后利用它杀死15只冰寒食尸鬼、15只残忍的恶鬼和15名复活的联盟士兵。', '如你所见，$C?聪明才智有时可以在看似势不可挡的敌军前反败为胜。', '如何，$r?$B$B你那些憎恶朋友们好用吗?', '', '去冰冠冰川找破天号的萨萨里安。', '引爆冰寒食尸鬼', '引爆残忍的恶鬼', '引爆复活的联盟士兵', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13291, '“借来”的技术', '好吧，我明白了。指挥官没时间关注我的小发现。这是他的损失！$B$B瞧，我设法从敌人那里“得到”了一批液体。尽管我讨厌改造下等的地精科技制品，不过这次就算破例啦。$B$B喏，拿着这份样本。我要你实地测试它的功效，便于让我通过逆向工程来重现它的制作流程。$b$b转至破碎前线，收集制造假人的材料，然后使用液体。', '破天号上的首席技师波尔维克要你在破碎前线使用偷来的液体。$B$B你需要收集被丢弃的头盔、被丢弃的护甲和一堆白骨才能召唤假人，这些材料都可以在破碎前线找到。', '好消息!$B$B我已经找出办法重制这些溶剂－称不上什么大成就，当然。$B$B我怀疑在我的有生之年，大概看不见有啥东西是哥布尔能做而地精在梦游的时候做不出来的东西!', '嗯，进行得如何了，$r?', '', '去冰冠冰川找破天号的首席技师波尔维克。', '完成实验', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13292, '偷来的解决方案', '嗯，嗯，再来一次怎么样？训练总是不嫌多的。$b$b我们已经找到了对付冰霜巨龙的法子。$b$b$r，继续削减它们的数量吧。你干掉的冰霜巨龙越多，我们在进攻冰冠堡垒时遇到的阻扰就越少。$B$B祝你好运。记得将没用完的液体带回来给我。', '破天号上的首席技师波尔维克要你在破碎前线使用偷来的液体。$B$B你需要收集被丢弃的头盔、被丢弃的护甲和一堆白骨才能召唤假人，这些材料都可以在破碎前线找到。', '好一场秀!太好了!杀龙已经变成你日常生活的琐事了!$B$B哪天你想再把他们数量减少一点时，记得回来找我。', '什么事，朋友？', '', '去冰冠冰川找破天号的首席技师波尔维克。', '杀死霜巢天爪龙', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13294, '对抗巨人', '尽管击败地面上的天灾士兵至关重要，但我们也不能疏忽了死亡之门的威胁。$B$B城墙上的血肉巨人可以投掷巨大的石块和冰块，对下面的部队造成毁灭性的伤害。$B$B集合一支队伍去干掉那些巨人。我们必须要对敌人有足够的了解。$B$B啊，对了……把它们的脊骨给我带回来。如果我没记错的话，那东西有一些特别的用处。', '破天号上的萨萨里安要你转至莫德雷萨，从起脓的血肉巨人身上取回5根起脓的脊骨给他。', '非常好，这些看来是可行的样本，$B$B以彼之矛，攻彼之盾的时候到了…', '对抗巨人的进度顺利吗，$r?', '', '去冰冠冰川找破天号的萨萨里安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13295, '化学常识', '<萨萨里安取过脊骨，把里面的脓液倒进瓶子里。>$B$B我们对血肉巨人的特性有一点点了解……$B$B它们的脊骨脓液可以以一种非常有趣的方式与瘟疫病菌溶合，将瘟疫转换成一种腐蚀剂。$B$B虽然说从高高的城墙上泼下腐蚀剂会让下面的士兵非常郁闷，但至少受害者不会变成天灾军团的爪牙。$B$B把这只瓶子里的东西倒进死亡之门西面大厅内的瘟疫之锅里去。', '破天号上的萨萨里安希望你转至莫德雷萨，将脊骨脓液倒进那里的瘟疫之锅。', '你做得很好，$C。$B$B当我们的军队抵达并向碉堡进军时，我们已经胸有成竹能夺下死亡之门。', '你顺利地中和了一批瘟疫样本了吗，$C?', '', '去冰冠冰川找破天号的萨萨里安。', '中和瘟疫之锅', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13297, '中和瘟疫', '没有我的帮助，你也可以中和敌人的瘟疫之锅了，$r。$B$B去消灭死亡之门一带的血肉巨人，用它们脊骨中的脓液中和瘟疫。$B$B你所打击的是敌军最重要的核心部分。这是一个重要的任务——对我们的事业而言生死攸关的任务。只要时间允许，就应该尽力去完成。$B$B记住，你可以在莫德雷萨找到血肉巨人和瘟疫之锅。', '破天号上的萨萨里安希望你转至莫德雷萨，将脊骨脓液倒进那里的瘟疫之锅。$B$B你可以使用从起脓的血肉巨人身上收集而来的脊骨制造脓液。', '战争的号角响起时我们将又少一个瘟疫大锅要对付。$B$B你的总督会感到相当高兴。', '您好，$C。$B$B我可以往上回报又让一个瘟疫大锅失灵了吗?', '', '去冰冠冰川找破天号的萨萨里安。', '中和瘟疫之锅', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13298, '污染者科普洛斯', '有报告指出死亡之门有一只非常强大的僵尸，$c。$B$B我们必须设法解除它带来的潜在威胁。如果你能亲自与它交手，应该可以了解到更多的有价值的情报。$B$B转至死亡之门西面的大厅，向这只怪物发起挑战，找出它的弱点。', '破天号上的萨萨里安要你转至莫德雷萨，杀死污染者科普洛斯。', '做得好，$C。$B$B也许透过些适当地调查，我们便能发现他们如何让这样的生物来到世上。', '你找得到那僵尸吗，$C?', '', '去冰冠冰川找破天号的萨萨里安。', '杀死污染者科普洛斯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13300, '萨隆邪铁的奴隶', '维库人将他们的俘虏送去位于冰冠冰川中心的伊米海姆，迫使他们进入那座城市的萨隆邪铁矿洞做苦工。巫妖王命令他们日夜不停地挖掘这种邪恶的矿石。$B$B我答应过弗丁大人，一定要将他们活着救出来。这就是我们眼下的任务。$B$B但是作为无畏远征军的使者，我不得不奉命待在这艘飞艇上。你能替我去救他们吗，$N？', '破天号上的虔诚的阿布萨兰要你去营救10名萨隆邪铁矿洞奴隶。', '什么他们被逼疯了?什么他们脑海里的声音?$B$B你脑海里的声音?!$B$B我要你先静下来把杂念从心中排去$g孩子:女孩l;。$B$B等明天你充分的休息以后，我们再试试把其馀的受害者从那地方救出来。', '我仍然未收到任何有关我\r\n的人民抵达银白先锋的消息。$B$B你确定你已经在依米海姆还给他们自由了吗?', '', '去找冰冠冰川破天号上的虔诚的阿布萨兰。', '营救萨隆邪铁矿洞奴隶', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13301, '地面突袭', '你好，$c。$B$B最近我们一直在对伊米海姆发动猛攻，但是这些维库人比我们之前遇到过的要凶残得多。每次部队试图向伊米海姆推进时都会遭到伏击，我们的人员损失非常惨重。$B$B如果你愿意参战，帮助我的小分队安全抵达伊米海姆的大门，我们会好好奖励你的。抵达大门之后，我们就会挖掘壕沟，等待后援部队。', '护送库卡隆部队抵达伊米海姆的大门。完成任务后返回伊米海姆北面的冰川边缘，向地面指挥官科特亚复命。', '请接受我的感谢。$B$B我承认这是个残忍的作战，但话说回来我们也别无选择－他们比起我们这一连串的突袭其实也丝毫不逊色，我们必须驱逐这些维库族才能进压冰冠冰川。$B$B我们应该还会需要更多的援助。请再借助你的力量并且在战场上证明你的价值。', '你让我那些弟兄安全抵达了吗?', '', '去冰冠冰川找轰炸场的地面指挥官库普。', '护送部落部队前往伊米海姆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13302, '萨隆邪铁的奴隶', '维库人将他们的俘虏送去位于冰冠冰川中心的伊米海姆，迫使他们进入那座城市的萨隆邪铁矿洞做苦工。巫妖王命令他们日夜不停地挖掘这种邪恶的矿石。$B$B我答应过弗丁大人，一定要将他们活着救出来。这就是我们眼下的任务。$B$B但是作为战歌远征军的使者，我不得不奉命待在这艘飞艇上。你能替我去救他们吗，$N？', '奥格瑞姆之锤的凯尔坦修士要你去营救10名萨隆邪铁矿洞奴隶。', '什么他们被逼疯了?什么他们脑海里的声音?$B$B你脑海里的声音?!$B$B我要你先静下来把杂念从心中排去$g孩子:女孩l;。$B$B等明天你充分的休息以后，我们再试试把其馀的受害者从那地方救出来。', '我仍然未收到任何有关我的人民抵达银白先锋的消息。$B$B你确定你已经在依米海姆还给他们自由了吗?', '', '去冰冠冰川找奥格瑞姆之锤的凯尔坦修士。', '营救萨隆邪铁矿洞奴隶', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13304, '战地维修', '天灾军团还没有从我们的这次攻势中缓过气来，$N。你顺利地完成了引爆任务，极大地鼓舞了大家的士气，我们要一鼓作气，继续战斗。$B$B位于我们下方的开阔山谷是一处战略要地。我们在失落希望之谷的东南角发现了一辆瘫痪的攻城车，似乎还可以使用。$B$B如果你能从食腐的恶鬼手里抢回丢失的零件，或许能让它重新运转起来。一辆攻城车就足以对敌人的地面单位造成重创了。', '奥格瑞姆之锤的库尔迪拉·织亡者从食腐的恶鬼身上收集5块攻城车零件，然后将它们带去失落希望之谷的损毁的攻城车旁。', '石毁车以前的状况比现在好的太多，不过总算整体结构没有受到永久性的伤害。 你取得的零件应该足以让它再次运转，至少暂时性地。', '那辆石毁车受损的情况不太乐观。', '', '去冰冠冰川的失落希望之谷找损毁的攻城车。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13305, '竭尽全力', '你要用这台机器去对付天灾军团？你这样是无法胜过他们的。$B$B你或许可以消灭几百个敌人……甚至几千个，但你无法取得胜利。这样不行。$B$B等你摆弄够了这台机器，可以到北边来找我。那里有一座旧军营。我会让你认识到，你要面对的是怎样的敌人。', '使用整修过的攻城车，在失落希望之谷里消灭150只腐朽的食尸鬼、20个霜颅大法师和2个白骨巨人。完成任务之后转至第一军团前线营地，与米斯希尔萨·阿奈尔谈一谈。', '懂了吗?你的确杀了不少，但你每杀一个，另一个马上就从土中爬起来。$B$B你还不了解你正面对什么，$N。让我告诉你。', '玩完了你的战争机器了吗?', '', '去冰冠冰川找失落希望之谷的米斯希尔萨·阿奈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13306, '构建路障', '一旦我们的部队开始动身穿越奥尔杜萨，他们就很容易遭到来自铁墙壁垒和广袤的冰川平原地区的攻击。$B$B我们没有时间和资源去建造防御工事，但可以搭建一些临时性的路障，抵御天灾军团的远程火力和突击，以保护我们的士兵。$B$B带着这只工具箱到奥尔杜萨西面的陨落英雄之谷去。按照我在那里做好的记号，用这只工具箱制造一些路障。', '奥格瑞姆之锤的库尔迪拉·织亡者要你使用路障搭设工具建造8处路障。', '<寇尔提拉简短地点了点头。>$B$B很好。虽称不上铜墙铁壁，但总比没有的好。但如果天灾军的指挥官还有点脑袋，那座门就仍然是个困扰。我们还是必须尽可能的占领周遭区域才行。', '路障都设立好了吗?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '建造路障', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13307, '溅血的旗帜', '天灾军团正在奥尔杜萨西面的陨落英雄之谷和冰冠冰川里搜寻死者，想要用他们来对付我们。天灾军团的军官已经复活了山谷中的一些死者，并赋予了他们可怕的力量和狂热的忠诚。天灾军团首领所携带的旗帜是这种力量的源泉，去杀死那些旗手，以此减少他们所控制的被转化英雄的数量。$B$B你必须帮我们除去这个障碍，并且在大部队开拔之前帮助我们削弱天灾军团的抵抗力度。', '奥格瑞姆之锤的库尔迪拉·织亡者要你去杀死5个天灾旗手、5个天灾转化者和20个被转化的英雄。', '你除掉了天灾执旗者与它们的爪牙?很好，我们的战备必须立刻重新进行。', '你杀掉执旗者并阻止它们一再尝试利用逝往的英魂来对付我们了吗?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13308, '思维诡计', '<你的脑海中响起了这个怪物的声音，它似乎在痛苦中挣扎，显得格外诡异。>$B$B$R，我需要你的帮助。和你那些被俘虏的朋友一样，我也被巫妖王手下的巨人给抓起来的。我从地下世界一路往上，想要调查从这座洞穴中传来的噪音，结果就被他们抓住并囚禁了起来。$B$B你愿意帮我吗？镣铐的钥匙就在矿洞中的工头身上。杀死他！$B$B<你感到一股压力冲击着你的思维，似乎这个怪物正在迫使你执行它的命令。>', '萨隆邪铁矿洞的黑暗低语者阿克希姆要你去找到工头的钥匙，帮它打开镣铐。', '<当你试图接近这生物，另一股兴奋，混夹着些许痛苦袭上你的内心。>$B$B好…很好!现在你知道我尝试着公平些，我将会依约地奖赏你。$B$B然后你便会自愿地交给我钥匙。', '我会大大地奖励你的侍奉。$B$B<暗语者投射一种令人放松的情绪到你心里。>$B$B你不会后悔释放我的。', '', '去冰冠冰川找萨隆邪铁矿洞的黑暗低语者阿克希姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13309, '空中突袭', '我已经选出了合适的士兵，准备将他们送进伊米海姆。你的任务就是保证他们的安全。$B$B维库人在围墙内设置了一些自动矛枪，已经打下我们好几架运兵机了。我们的工程师建造了一座压制炮台，可以让那些矛枪哑火。只要向矛枪周围扫射一通，炮弹产生的烟雾就可以挡住它的视线，阻塞它的机关。$B$B跳上这座炮台吧，保证我的士兵们都能安全着陆。', '伊米海姆北面冰川边缘的地面指挥官库普命令你使用破天号压制炮台，保证破天号运兵机安全降落并卸下所有部队。', '非常好，大兵。我们这很需要像你这样的人才－改天若行动尚未终止记得再过来一趟。', '你让我的弟兄们闯进去了没?', '', '去冰冠冰川找失落希望之谷的地面指挥官库普。', '破天号潜入者安全着陆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13310, '空中突袭', '正好有事情可以交给你这个废物去做，省得你整天游手好闲的。$B$B我们正准备将一队训练有素的士兵空投到伊米海姆去。但是维库人在围墙内设置了自动鱼叉炮，用于摧毁我们的运兵机。于是，我们请奥格瑞姆之锤的工程师建造了一座压制炮台。$B$B你要充当炮手，对维库人的鱼叉炮进行扫射，遮挡它们的视线，并摧毁它们的传动装置。你必须在确保运兵机完整的情况下让所有士兵都安全降落。', '伊米海姆北面冰川边缘的地面指挥官科特亚命令你使用库卡隆压制炮台，保证库卡隆运兵机安全降落并卸下所有部队。', '看来你还不是全然地没用，做得好。', '搞定了没?', '', '去冰冠冰川找轰炸场的地面指挥官库普。', '库卡隆潜入者安全着陆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13311, '恶魔套牌', '你现在已经收集到了恶魔套牌的所有卡片，一张新的卡片神秘地出现在你手中。卡面上描绘着一位占卜师，无论你把卡片转动到何种角度，占卜师似乎都在盯着你。$B$B你觉得似乎可以用这张卡片来联络某些人，或某些事物。', '使用恶魔套牌召唤一位暗月占卜师，并把套牌交给占卜师。', '暗月马戏团对这些塔罗牌很有兴趣，如果你收集到更多的卡片，不要犹豫，立刻呼唤我们。我们也有自己的商人，所以请让我提供一些东西，来与你交换这些卡片。', '看来你已集满全套的群魔套卡!恭喜!', '', '去找暗月占卜师。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13312, '铁墙壁垒', '铁墙壁垒位于奥尔杜萨的西面，俯瞰陨落英雄之谷。它可以全方位控制下方的开阔地区。如果不攻下铁墙壁垒，我们就没办法继续前进，但是邪恶的格姆克尔和他所率领的诅咒教派信徒控制着壁垒。$B$B如果你能削弱格姆克尔的力量，我们的部队在开进那一地区时就可以应付突发状况了。带上这枚扭曲符文，到铁墙壁垒的最深处去，在格姆克尔的宝珠附近使用它，把那个通灵师引出来。', '击败邪恶的格姆克尔，然后向奥格瑞姆之锤的库尔迪拉·织亡者复命。', '葛林克尔已经栽在你手上了?很好。少了他的妨碍，我们夺下壁垒的机会大大的提升了。', '你完成了你的任务了吗?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13314, '获取情报', '部落最近表现得很活跃，我讨厌这样。自从破碎前线的那次行动以后，他们已经开始变得越来越猖狂了。联盟必须阻止他们。$B$B他们在冰冠冰川的上空、奥尔杜萨和铁墙壁垒的西面有频繁的活动，斥候和传令兵骑着龙鹰进进出出，不断传递情报和命令。带上这把镖枪，用它去干掉那些奥格瑞姆之锤斥候。如果你也骑着飞行坐骑的话，这个任务应该更容易完成。', '从奥格瑞姆之锤斥候身上截获6份奥格瑞姆之锤急件，把它们交给破天号上的高级指挥官加斯汀·巴雷特。', '我们能有像你这样的高手真好，$N。要是我们有一队像你一样的$C，就能让部落瞧瞧我们的厉害。这些截获的信件能够帮助我们扳回一城，的确我们当前略居劣势，但论输赢还早的很!', '你成功拦截那些急件了吗?', '', '去冰冠冰川找破天号的高级指挥官加斯汀·巴雷特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13315, '预览', '事情有了一些进展。我们已经想到了一个很有希望成功的战术，可以让我们获得死亡之门的控制权。巨大的人员伤亡是不可避免的，但我们应该能够取得最终的胜利——只要那些你成天嚷嚷着要去收拾掉的部落不给我们造成什么麻烦的话。$B$B不管怎样，荒凉之门奥尔杜萨将是我们的下一个目标。飞去那里去熟悉一下地形，了解敌人的兵力部署。$B$B等你回来之后，我会交给你一些任务去办。', '破天号的萨萨里安希望你飞往荒凉之门，调查荒凉之门的南部、中部、北部和西北部。', '不错、很好，$C。$B$B现在你已经对我们的敌人有了初步的了解 ，准备作战的时候到了…', '荒寂之门侦查完毕了吗，$C?', '', '去冰冠冰川找破天号的萨萨里安。', '侦查奥尔杜萨南部', '侦查奥尔杜萨中部', '侦查奥尔杜萨北部', '侦查奥尔杜萨西北部');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13316, '科雷萨的守卫者', '科雷萨又被称为恐惧之门，它是挡在我们与冰冠堡垒之间的最后一道屏障。它位于铁墙壁垒的南方，要越过冰川和战火平原才能抵达。当我们的部队开进那里以后，他们可能会遭到严重减员，甚至更糟。$B$B我们一定要削弱科雷萨的防御力量，不然我们的部队只会在它的城墙上撞得头破血流。$B$B科雷萨的城头上布署着巫妖王手下最凶狠、最狂热的仆从。你要尽量消灭这些守卫，希望这么做能有点用。', '奥格瑞姆之锤的库尔迪拉·织亡者要你去杀死5个恐惧先驱和5个科雷萨守卫者。', '我希望你在寇普雷萨的战功是一个预兆。这下子我们进攻他的城堡时巫妖王恐怕不能再袖手旁观了。', '寇普雷萨的防御已经被你削弱了吗?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13318, '从天而“降”', '诅咒教派控制着荒凉之门，是吗？一点都不出我的意料。$B$B我们来跟他们玩一个小游戏吧。你之前已经注意到了，新来的教徒在荒凉之门的南端接受训练。他们之中的绝大部分人应该都持有一件特殊的物品——幻象宝珠。$B$B这种宝珠可以用来伪装诅咒教徒，使他们能够安全地自由行动，渗透或是完全伪装成敌人的模样。$B$B去干掉那些蠢货，从他们身上收集幻象宝珠，然后对黑暗压制者使用它。', '破天号上的萨萨里安希望你从奥尔杜萨的苦痛新兵身上夺取幻象宝珠，然后对那里的3名黑暗压制者使用。', '某些情况下，应该很好用，你说是吗?$B$B譬如让人看起来永远不会老…', '怎么了，$r?', '', '去冰冠冰川找破天号的萨萨里安。', '扔下黑暗压制者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13319, '指挥体系', '根据你的报告以及我对诅咒教派的认识，他们在荒凉之门一带的每座营地中都会有一个工头负责管理各项事务。$B$B虽然干掉他们的首领只会让他们暂时受挫，但至少这样可以拖延他们的工作进度，并让他们应接不暇。而且就当前来说，这也是一个足够有价值的成果了。$B$B去找到那些工头，消灭他们之后回来向我报告。', '破天号的萨萨里安要你转至荒凉之门奥尔杜萨，击败工头法埃迪斯、工头沙维尔、工头维拉恩和工头夏克尔。', '做得好，$r。但别太志得意满了。他们随时会派人取代这些监督者…', '怎么了，$C?', '', '去冰冠冰川找破天号的萨萨里安。', '杀死工头法埃迪斯', '杀死工头夏克尔', '杀死工头维拉恩', '杀死工头沙维尔');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13320, '无法复制', '我在这里都闻到了他们的大锅散发出的气味，不过锅里煮的并不是瘟疫病菌。$B$B所有宣誓为诅咒教派效力的人都必须饮下一种可以夺走他们的意愿、使他们永远效忠巫妖王的药剂。$B$B有人说，这种药剂中封存着那些受到残酷折磨、并被无情屠杀的生物的扭曲之魂，不过我从来就没能成功地复制过这种药水……$B$B从荒凉之门西北区域的三处大锅里各采集一些样本，装进这只瓶子里，然后把它交给首席技师波尔维克。', '破天号上的萨萨里安希望你转至荒凉之门奥尔杜萨，在那里的3处诅咒教徒的大锅中使用分离的药瓶，然后将其交给首席技师波尔维克。', '<首席工程师栓钳将瓶子内的液体倒入四水分子分析仪。>$B$B现在你所看到的情况只是单纯的分子聚合失败。', '什么好事说来听听，$r?', '', '去冰冠冰川找破天号的首席技师波尔维克。', '收集蓝色样本', '收集绿色样本', '收集黑色样本', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13321, '重新考验', '这法子应该有效！$B$B那些扭曲的诅咒教徒想要把别人的灵魂放进他们的饮料里？那么让我们来帮他们一把吧！$B$B把这东西喝下去——不用担心，我已经对它进行了稀释……现在它唯一的作用只是让在你干掉诅咒教徒时可以发现他们的精华。$B$B等你收集到一些精华之后，把那些充满扭曲灵魂怨念的沸腾魔质扔进他们的瘟疫之锅里。$B$B看看他们尝到自己的药剂之后会怎样！', '破天号上的首席技师波尔维克希望你把沸腾的魔质扔进奥尔杜萨的瘟疫之锅里。', '哇呼!$B$B这可给了他们点教训!', '如何，$C?$B$B世界又少了一个诅咒教徒吗?', '', '去冰冠冰川找破天号的首席技师波尔维克。', '投放沸腾的魔质', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13322, '重新考验', '那些扭曲的诅咒教徒想要把别人的灵魂放进他们的饮料里？那么让我们来帮他们一把吧！$B$B把这东西喝下去——不用担心，我已经对它进行了稀释……现在它唯一的作用只是让在你干掉诅咒教徒时可以发现他们的精华。$B$B等你收集到一些精华之后，把那些充满扭曲灵魂怨念的沸腾魔质扔进他们的瘟疫之锅里。$B$B看看他们尝到自己的药剂之后会怎样！', '破天号上的首席技师波尔维克希望你喝下稀释过的诅咒教徒滋补剂，杀死奥尔杜萨一带的任意诅咒教徒，从他们身上收集被污染的精华。然后将10份被污染的精华组合成沸腾的魔质，把它扔进奥尔杜萨的瘟疫之锅里。', '哇呼!$B$B这可给了他们点教训!', '如何，$C?$B$B世界又少了一个诅咒教徒吗?', '', '去冰冠冰川找破天号的首席技师波尔维克。', '投放沸腾的魔质', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13323, '从天而“降”', '看来那些新教徒的数量又增加了。你知道该怎么做吧……$B$B新来的教徒在荒凉之门的南端接受训练。他们之中的绝大部分人应该都持有一件特殊的物品——幻象宝珠。$B$B这种宝珠可以用来伪装诅咒教徒，使他们能够安全地自由行动，渗透或是完全伪装成敌人的模样。$B$B去干掉那些蠢货，从他们身上收集幻象宝珠，然后对黑暗压制者使用它。', '破天号上的萨萨里安希望你从奥尔杜萨的苦痛新兵身上夺取幻象宝珠，然后对那里的3名黑暗压制者使用。', '某些情况下，应该很好用，你说是吗?$B$B譬如让人看起来永远不会老…', '怎么了，$r?', '', '去冰冠冰川找破天号的萨萨里安。', '扔下黑暗压制者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13324, '暗月棱镜套牌', '你现在已经收集到了棱镜套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。', '当暗月马戏团来到镇上的时候，把棱镜套牌交给他们。', '现在你已经集满了整套\r\n棱光套卡。把它还给我们会让你和暗月马戏团之间创建永不断裂的联系。请允许我将一张更强大的暗月卡片回送给你做为酬谢你的一份薄礼。', '看来你已集满全套的棱光套卡!恭喜你!', '', '去找萨杜斯·帕雷教授。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13326, '暗月高尚套牌', '你现在已经收集到了高尚套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。', '当暗月马戏团来到镇上的时候，把高尚套牌交给他们。', '现在你已经集满了整套贵族套卡。把它还给我们会让你和暗月马戏团之间创建永不断裂的联系。请允许我将一张更强大的暗月卡片回送给你做为酬谢你的一份薄礼。', '看来你已集满全套的贵族套卡!恭喜你!', '', '去找萨杜斯·帕雷教授。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13328, '击破碎片', '巫妖王的手下在科雷萨的墙头安装了三种水晶，分别是绝望碎片、恐惧碎片和苦难碎片。一旦我们的部队抵达科雷萨城下，他就会使用这三种水晶进行攻击。$B$B如果让这些水晶完全发动，士兵们的精神就会被痛苦和恐惧压垮。这样一来，天灾军团就可以轻易消灭他们。$B$B去找到那些碎片，摧毁它们，把水晶给我带回来。我们不能让这些武器留在巫妖王手里！', '将破损的绝望碎片、破损的恐惧碎片和破损的苦难碎片交给奥格瑞姆之锤的库尔迪拉·织亡者。', '<寇尔提拉从你手中接过水晶碎片，口中念念有词。>$B$B我想我记得这些玩意…$B$B意志稍微不坚定的人们很容易就会被水晶之力影响，从而被一网打尽。你成功地阻止了这威胁。', '你已经击碎了巫妖王的新武器吗?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13330, '伊米亚之血', '那些博得巫妖王宠爱的维库人自称为伊米亚，他们居住在位于冰冠冰川中心的伊米海姆。在进攻冰冠堡垒之前，我们还有很多准备工作要做。眼下，我们的任务就是消灭这些所谓的巫妖王的“选民”。$B$B进入伊米海姆，杀死那些维库人。让他们明白，我们远比他们更强大。', '奥格瑞姆之锤的战争使者达沃斯·里赫要你进入伊米海姆，杀死20个维库人。', '看来，也不过如此，巫妖王马上就得尝尝同样的苦头。', '你完成了我交代的事了?', '', '去冰冠冰川找奥格瑞姆之锤的战争使者达沃斯·里赫。', '杀死伊米海姆维库人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13332, '构建路障', '一旦我们的部队开始动身穿越奥尔杜萨，他们就很容易遭到来自铁墙壁垒和广袤的冰川平原地区的攻击。$B$B我们没有时间和资源去建造防御工事，但可以搭建一些临时性的路障，抵御天灾军团的远程火力和突击，以保护我们的士兵。$B$B带着这只工具箱到奥尔杜萨西面的陨落英雄之谷去。按照我在那里做好的记号，用这只工具箱制造一些路障。', '破天号的萨萨里安要你使用路障搭设工具建造8处路障。', '<萨沙理安点了点头。>$B$B很好。虽称不上铜墙铁壁，但总比没有的好。但如果天灾军的指挥官还有点脑袋，那座门就仍然是个困扰。我们还是必须尽可能的占领周遭区域才行。', '路障都设立好了吗?', '', '去冰冠冰川找破天号的萨萨里安。', '建造路障', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13333, '抢夺急件', '不仅我们在努力，部落也在不断向铁墙壁垒和奥尔杜萨西面的冰冠冰川派出斥候。$B$B不能让部落通过这种方法领先我们。再带上这把镖枪，不要对那些奥格瑞姆之锤斥候手软！把你截获的急件都给我带回来。$B$B部落的损失就是我们的成果。', '从奥格瑞姆之锤斥候身上截获6份奥格瑞姆之锤急件，把它们交给破天号上的高级指挥官加斯汀·巴雷特。', '<提督接过信件。>$B$B这正是我们需要的。连部落也不会笨到盲目地进攻天灾军团。有了这些信件，我们将会有所准备。', '你拦截了那些急件了吗 ?', '', '去冰冠冰川找破天号的高级指挥官加斯汀·巴雷特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13334, '溅血的旗帜', '天灾军团正在奥尔杜萨西面的陨落英雄之谷和冰冠冰川里搜寻死者，想要用他们来对付我们。天灾军团的军官已经复活了山谷中的一些死者，并赋予了他们可怕的力量和狂热的忠诚。天灾军团首领所携带的旗帜是这种力量的源泉，去杀死那些旗手，以此减少他们所控制的被转化英雄的数量。$B$B你必须帮我们除去这个障碍，并且在大部队开拔之前帮助我们试探一下天灾军团的抵抗力度。', '破天号的萨萨里安要你去杀死5个天灾旗手、5个天灾转化者和20个被转化的英雄。', '你除掉了天灾执旗者与它们的爪牙?很好，我们的战备必须立刻重新进行。', '你杀掉执旗者并阻止它们一再尝试利用逝往的英魂来对付我们了吗?', '', '去冰冠冰川找破天号的萨萨里安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13335, '在恐惧之门前', '战火平原位于科雷萨的前方，铁墙堡垒的南方。巫妖王在这里布置了精锐部队以守卫冰冠堡垒。$B$B一队死亡骑士率领着大群的冰冠劫掠者守住了道路。我担心就算我们打倒了这些劫掠者，天灾军团也能复活它们，并把它们再次投入战场。$B$B我已经有了一个解决方案，不过尚不知道能否奏效。带着这瓶溶液，用它去溶解那些冰冠劫掠者的残骸。', '破天号的萨萨里安要你使用强酸溶解6具冰冠劫掠者的尸体。', '<萨沙理安听着你的测试成果。>$B$B所以这些酸液发挥了作用? 很好。当军队正面与劫夺者交锋时我们将会需要这些。', '你在劫夺者身上试过那些溶剂了?', '', '去冰冠冰川找破天号的萨萨里安。', '溶解冰冠劫掠者的残骸', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13337, '铁墙壁垒', '铁墙壁垒位于奥尔杜萨的西面，俯瞰陨落英雄之谷。它可以全方位控制下方的开阔地区。如果不攻下铁墙壁垒，我们就没办法继续前进，但是邪恶的格姆克尔和他所率领的诅咒教派信徒控制着壁垒。$B$B如果你能削弱格姆克尔的力量，我们的部队在开进那一地区时就可以应付突发状况了。带上这枚扭曲符文，到铁墙壁垒的最深处去，在格姆克尔的宝珠附近使用它，把那个通灵师引出来。', '击败邪恶的格姆克尔，然后向破天号的萨萨里安复命。', '葛林克尔已经栽在你手上了?很好。少了他的妨碍，我们夺下壁垒的机会大大的提升了。', '你完成了你的任务了吗?', '', '去冰冠冰川找破天号的萨萨里安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13339, '击破碎片', '巫妖王的手下在科雷萨的墙头安装了三种水晶，分别是绝望碎片、恐惧碎片和苦难碎片。一旦我们的部队抵达科雷萨城下，他就会使用这三种水晶进行攻击。$B$B如果让这些水晶完全发动，士兵们的精神就会被痛苦和恐惧压垮。这样一来，天灾军团就可以轻易消灭他们。$B$B去找到那些碎片，摧毁它们，把水晶给我带回来。我们不能让这些武器留在巫妖王手里！', '将破损的绝望碎片、破损的恐惧碎片和破损的苦难碎片交给破天号的萨萨里安。', '<萨沙理安从你手中接过水晶碎片，口中念念有词。>$B$B我想我记得这些玩意…$B$B意志稍微不坚定的人们很容易就会被水晶之力影响，从而被一网打尽。你成功地阻止了这威胁。', '你已经击碎了巫妖王的新武器吗?', '', '去冰冠冰川找破天号的萨萨里安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13342, '活动窃听器', '好吧，$g朋友:女士;，是时候给他们装个窃听器了。$B$B放松一点，我并不说要真的去装一个窃听器，不过大概也就是那么回事。$B$B在奥尔杜萨的北部区域，有许多诅咒教派的虚空召唤师带着恶魔爪牙游来荡去。用这根魔棒从那些被奴役的爪牙的尸体上吸取一些黑暗物质，然后使用诅咒教派的召唤水晶，召唤出我们的小间谍。$B$B除非它被发现，否则信使将一直作为我们的耳目，小心地观察敌人的行动。', '破天号上的萨萨里安希望你去收集5份黑暗物质，然后在奥尔杜萨召唤出一名黑暗信使。', '你做得很好，$C。$B$B信差已经回报了一些非常有价值的资讯。', '什么事 ，$C?', '', '去冰冠冰川找破天号的萨萨里安。', '召唤黑暗信使', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13343, '永恒之龙的秘密，再来一次', '你来了！呃，刚刚我是不是已经和你谈过了？$B$B<克罗米思考着时间流的可能性。>$B$B不管这些啦，永恒之龙正在追杀你！别紧张，不是现在的你。他们正在追踪过去的你，就在你保卫永恒沙漏的那个时间流里。你还记得这件事吧？$B$B那是过去的你，当然也是现在的你。哎呀，这不重要。你必须返回青铜巨龙圣地，抵御他们的攻击，保护你自己，当然还有保护永恒沙漏，不然你就会从历史上消失！', '龙眠神殿顶层的克罗米要你再次返回青铜巨龙圣地。$B$B进入圣地后，将永恒沙漏放在地上，和过去的你一起保护沙漏，令它免遭永恒之龙的破坏。', '喔我的老天，你成功了!我真担心。$B$B战斗中你似乎不断在时光里外进进出出!我几乎确信我们失去你了!$B$B但是现在你安然无恙，守护了你的过去、与你的现在。$B$B你真是个时光$g英雄:女杰;，$N!', '<克罗米以奇怪的眼光看着你。>我认识你吗?我从你身上感应到一种微妙的磁场，或者你被卡在时间的循环里。$B$B无论如何你最好赶快解决，否则你的存在岌岌可危。', '保护永恒沙漏免遭永恒之龙的破坏。', '去龙骨荒野找龙眠神殿的克罗米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13344, '活动窃听器', '教徒们已经发现了你上次召唤出来的信使，$r。$B$B虽然我们已经得到了大量的情报，但是能够监控诅咒教派的每一步行动对我们非常重要。$B$B转至奥尔杜萨，用这根魔棒从那些被奴役的爪牙的尸体上吸取一些黑暗物质，然后使用诅咒教派的召唤水晶，再帮我们召唤出一个黑暗信使。$B$B在黑暗信使被发现之前，它将一直作为我们的耳目，小心地观察敌人的行动。', '破天号上的萨萨里安希望你去收集5份黑暗物质，然后在奥尔杜萨召唤出一名黑暗信使。', '你做得很好，$C。$B$B信差已经回报了一些非常有价值的资讯。', '什么事 ，$C?', '', '去冰冠冰川找破天号的萨萨里安。', '召唤黑暗信使', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13345, '需要更多情报', '诅咒教派一直都是以喜欢制订庞大的计划但最终鲜有成功而声明狼藉，但我这次感觉有些不一样……$B$B也许是由于接近巫妖王，提高了他们的热情。不管怎样，它们似乎比以往任何时候都更有信心了。我们必须了解是什么让他们感到自信，并想办法夺走他们的自信！$B$B我相信关键就在他们的研究员身上。去搞清楚他们正在干些什么，然后向我报告具体的细节。', '破天号上的萨萨里安希望你从奥尔杜萨的诅咒教派研究员身上收集3页诅咒教派研究笔记，然后将它们组合成诅咒教派论文。', '的确，事态似乎有点严重…', '你找出他们所为何事了吗，$r?', '', '去冰冠冰川找破天号的萨萨里安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13346, '片刻不得安宁', '那些蠢货居然碰巧找到了可以对我们造成真正威胁的办法！$B$B这一教区的首领奥鲁麦斯在仪式中牺牲了自己，现在他的手下正在把能量导入他的灵魂中。$B$B如果让他继续这样不受干扰地吸收能量，他很快就会变成一个强大的对手。$B$B在他的大厅附近找到他的精华、徽记、节杖和长袍，将它们组合起来，然后在那里的水晶上面使用他的残骸。$B$B快一点，$r！在他变得更加强大之前消灭他！', '破天号上的萨萨里安希望你转至奥尔杜萨，杀死晋升者奥鲁麦斯。', '雅路麦斯被扎实地打败了，然而我却似乎还能感应到他的魂魄尚在某处盘旋…', '如何，朋友?你击败雅路麦斯了吗?', '', '去冰冠冰川找破天号的萨萨里安。', '击败晋升者奥鲁麦斯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13347, '浴火重生', '我们的命运在出生时就已注定。伯瓦尔之死虽然是一场悲剧，但这也是不可避免的。$B$B现在你所能做的，就是向英雄致敬，$N。从战场上把伯瓦尔的盾牌拿回来，将其交给你的国王。在你将盾牌交给瓦里安的时候，告诉他：“我们并没有失去一切。死去的英雄将会使我们变得更加团结，齐心协力将邪恶从这个世界中驱赶出去。”$B$B他一定不能失去信仰。去吧，$N。你的人民需要一个英雄，他们需要你。', '从天灾之门安加萨的战场上取回弗塔根之盾，把它交给暴风城要塞中的瓦里安·乌瑞恩国王。', '龙后是对的，$N。成败都还未定。我将成为这股从灰烬中重燃的力量，净化部落带给这世界的邪恶。我们兄弟姐妹的鲜血绝对不能白流。', '<乌瑞恩王拭去一滴眼泪。>$B$B<乌瑞恩王点了点头。>$B$B这都是我的错。', '', '去暴风城找暴风要塞的瓦里安·乌瑞恩国王。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13349, '冰霜巨龙的摇篮', '我们必须再接再厉，不能给天灾军团任何喘息的机会。$B$B辛达苟萨之墓坐落在失落希望之谷以东。巫妖王的维库人侍从正在密切地监督着诅咒教派在那里的工事。$B$B辛达苟萨之墓蕴含着强大的力量，很可能是蓝龙一族的集体墓地。诅咒教派利用蓝龙的骸骨，召唤可怕的霜巢之龙。$B$B我们要袭击那里，干扰他们培养冰霜巨龙的计划。你愿意接受这项任务吗，$N？', '奥格瑞姆之锤的库尔迪拉·织亡者要你转至辛达苟萨之墓，杀死5个巨龙复活者、8个诅咒教派腐蚀者和3个维库通灵领主。', '你做得很好，$N。你可能需要休息一下。你的脸色很 苍白。', '$N万岁。', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13350, '片刻不得安宁', '是奥鲁麦斯……他的力量又开始增强了，我能感觉到。现在他的手下正在把能量导入他的灵魂中。$B$B如果让他继续这样不受干扰地吸收能量，他很快就会变成一个强大的对手。$B$B回到奥尔杜萨的北部，在他的大厅中将他的精华、徽记、节杖和长袍组合起来，然后在那里的水晶上面使用他的残骸。$B$B快一点，$r！在他变得更加强大之前消灭他！', '破天号上的萨萨里安希望你转至奥尔杜萨，杀死晋升者奥鲁麦斯。', '雅路麦斯被扎实地打败了，然而我却似乎还能感应到他的魂魄尚在某处盘旋…', '如何，朋友?你击败雅路麦斯了吗?', '', '去冰冠冰川找破天号的萨萨里安。', '击败晋升者奥鲁麦斯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13351, '预览', '事情有了一些进展。我们已经想到了一个很有希望成功的战术，可以让我们获得死亡之门的控制权。巨大的人员伤亡是不可避免的，但我们应该能够取得最终的胜利——只要那些你成天嚷嚷着要去收拾掉的联盟不给我们造成什么麻烦的话。$B$B不管怎样，荒凉之门奥尔杜萨将是我们的下一个目标。飞去那里去熟悉一下地形，了解敌人的兵力部署。$B$B等你回来之后，我会交给你一些任务去办。', '奥格瑞姆之锤的库尔迪拉希望你飞往荒凉之门，调查荒凉之门的南部、中部、北部和西北部。', '不错、很好，$C。$B$B现在你已经对我们的敌人有了初步的了解 ，准备作战的时候到了…', '荒寂之门侦查完毕了吗，$C?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '侦查奥尔杜萨南部', '侦查奥尔杜萨中部', '侦查奥尔杜萨北部', '侦查奥尔杜萨西北部');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13352, '从天而“降”', '诅咒教派控制着荒凉之门，是吗？一点都不出我的意料。$B$B我们来跟他们玩一个小游戏吧。你之前已经注意到了，新来的教徒在荒凉之门的南端接受训练。他们之中的绝大部分人应该都持有一件特殊的物品——幻象宝珠。$B$B这种宝珠可以用来伪装诅咒教徒，使他们能够安全地自由行动，渗透或是完全伪装成敌人的模样。$B$B去干掉那些蠢货，从他们身上收集幻象宝珠，然后对黑暗压制者使用它。', '奥格瑞姆之锤的库尔迪拉希望你从奥尔杜萨的苦痛新兵身上夺取幻象宝珠，然后对那里的3名黑暗压制者使用。', '某些情况下，应该很好用，你说是吗?$B$B譬如让人看起来永远不会老…', '怎么了，$r?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '扔下黑暗压制者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13353, '从天而“降”', '看来那些新教徒的数量又增加了。你知道该怎么做吧……$B$B新来的教徒在荒凉之门的南端接受训练。他们之中的绝大部分人应该都持有一件特殊的物品——幻象宝珠。$B$B这种宝珠可以用来伪装诅咒教徒，使他们能够安全地自由行动，渗透或是完全伪装成敌人的模样。$B$B去干掉那些蠢货，从他们身上收集幻象宝珠，然后对黑暗压制者使用它。', '奥格瑞姆之锤的库尔迪拉希望你从奥尔杜萨的苦痛新兵身上夺取幻象宝珠，然后对那里的3名黑暗压制者使用。', '某些情况下，应该很好用，你说是吗?$B$B譬如让人看起来永远不会老…', '怎么了，$r?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '扔下黑暗压制者', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13354, '指挥体系', '根据你的报告以及我对诅咒教派的认识，他们在荒凉之门一带的每座营地中都会有一个工头负责管理各项事务。$B$B虽然干掉他们的首领只会让他们暂时受挫，但至少这样可以拖延他们的工作进度，并让他们应接不暇。而且就当前来说，这也是一个足够有价值的成果了。$B$B去找到那些工头，消灭他们之后回来向我报告。', '奥格瑞姆之锤的库尔迪拉要你转至荒凉之门奥尔杜萨，击败工头法埃迪斯、工头沙维尔、工头维拉恩和工头夏克尔。', '做得好，$r。但别太志得意满了。他们随时会派人取代这些监督者…', '怎么了，$C?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '杀死工头法埃迪斯', '杀死工头夏克尔', '杀死工头维拉恩', '杀死工头沙维尔');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13355, '不能复制', '我在这里都闻到了他们的大锅散发出的气味，不过锅里煮的并不是瘟疫病菌。$B$B所有宣誓为诅咒教派效力的人都必须饮下一种可以夺走他们的意愿、使他们永远效忠巫妖王的药剂。$B$B有人说，这种药剂中封存着那些受到残酷折磨、并被无情屠杀的生物的扭曲之魂，不过我从来就没能成功地复制过这种药水……$B$B从荒凉之门西北本地的三处大锅里各采集一些样本，装进这只瓶子里，然后把它交给首席技师考伯克拉。', '奥格瑞姆之锤的库尔迪拉希望你转至荒凉之门奥尔杜萨，在那里的3处诅咒教徒的大锅中使用分离的药瓶，然后将其交给首席技师考伯克拉。', '<铜爪将瓶内的液体蹈入他的分子分析仪。>$B$B啊…我知道这玩意!', '什么好事说来听听，$C?', '', '去冰冠冰川找奥格瑞姆之锤的首席技师考伯克拉。', '收集蓝色样本', '收集绿色样本', '收集黑色样本', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13357, '重新考验', '那些扭曲的诅咒教徒想要把别人的灵魂放进他们的饮料里？那么让我们来帮他们一把吧！$B$B把这东西喝下去——不用担心，我已经对它进行了稀释……现在它唯一的作用只是让在你干掉诅咒教徒时可以发现他们的精华。$B$B等你收集到一些精华之后，把那些充满扭曲灵魂怨念的沸腾魔质扔进他们的瘟疫之锅里。$B$B看看他们尝到自己的药剂之后会怎样！', '奥格瑞姆之锤的首席技师考伯克拉希望你把沸腾的魔质扔进奥尔杜萨的瘟疫之锅里。', '哇呼!$B$B这可给了他们点教训!', '如何?结果怎样?', '', '去冰冠冰川找奥格瑞姆之锤的首席技师考伯克拉。', '投放沸腾的魔质', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13358, '活动窃听器', '好吧，$g朋友:女士;，是时候给他们装个窃听器了。$B$B放松一点，我并不说要真的去装一个窃听器，不过大概也就是那么回事。$B$B在奥尔杜萨的北部本地，有许多诅咒教派的虚空召唤师带着恶魔爪牙游来荡去。用这根魔棒从那些被奴役的爪牙的尸体上吸取一些黑暗物质，然后使用诅咒教派的召唤水晶，召唤出我们的小间谍。$B$B除非它被发现，否则信使将一直作为我们的耳目，小心地观察敌人的行动。', '奥格瑞姆之锤的库尔迪拉希望你去收集5份黑暗物质，然后在奥尔杜萨召唤出一名黑暗信使。', '做得很好，我的朋友。$B$B就在我们的对谈期间，信差又进来回报信息了。', '什么事 ，$C?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '召唤黑暗信使', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13359, '巨龙的墓地', '曾经有一群蓝色的巨龙死在这里。现在，他的仆从正在逐个复活它们。$B$B他亲自复活了其中最大的一条龙。给我从雏龙身上弄一些骨灰下来，我会向你展示他是如何复活那条龙的。', '辛达苟萨之墓的米斯希尔萨·阿奈尔要你收集6份雏龙的骨灰。', '连最强大的龙族都必须响应他的召唤。像你这样脆弱的凡人要如何抵抗他?', '你取得骨尘了吗，$N?', '', '去冰冠冰川找辛达苟萨之墓的米斯希尔萨·阿奈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13361, '猎人与王子', '在王子成为国王之前，他经历过很多战斗……但其中只有一场战斗使他差点丢掉性命。$B$B那场战斗就发生在这里。等你看过我向你展示的场景以后，你就都明白了。$B$B从地上拣起一块染血的石头，然后你就可以看到当时的情景了。', '白骨之庭的米斯希尔萨·阿奈尔要你去寻找一块染血的石头，并目睹王子的命运。', '大战之后，王子了解唯一绑住他的就是身为一个人类…他还是有感觉…他还是会流血…他还有…一颗心。$B$B他成为国王以后的第一件事就是将自己摆脱这个。当我们第一次见面时他将他的心投入了深渊。而你，$N则是那刻起，第一个碰到的人。', '你了解了吗，$N?你了解了?', '', '去冰冠堡垒找白骨之庭的米斯希尔萨·阿奈尔。', '王子的命运', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13364, '提里奥的尝试', '就在今天早上，我的斥候报告说，有一队诅咒教派的教徒带着一样东西离开冰冠堡垒，转至黑暗大教堂了。$B$B现在我明白了，那恐怕就是阿尔萨斯的心脏……里面残留着他的最后一点尚未泯灭的人性。$B$B这是圣光的启示。只要这颗心脏仍然存在，阿尔萨斯·米奈希尔就有可能变回人类！$B$B我们到大教堂的入口处汇合吧。记得带一件教徒的兜帽来，我们要乔装混进去。', '北伐军之峰的提里奥·弗丁要你想办法获取一件诅咒教徒的兜帽，穿上它，然后转至冰冠堡垒西北方的黑暗大教堂入口处与他汇合。', '我并不把刚刚发生的事视为一个错误，$N…恰恰相反地。$B$B藉由一窥这个“心脏”，你让我确信了一件事。阿尔萨斯.米奈希尔已经不复存在了－这里，只剩下巫妖王。', '愿圣光与你同在，$N。', '', '去冰冠冰川找北伐军之峰的大领主提里奥·弗丁。', '', '提里奥的尝试', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13365, '活动窃听器', '教徒们已经发现了你上次召唤出来的信使，$r。$B$B虽然我们已经得到了大量的情报，但是能够监控诅咒教派的每一步行动对我们非常重要。$B$B转至奥尔杜萨，用这根魔棒从那些被奴役的爪牙的尸体上吸取一些黑暗物质，然后使用诅咒教派的召唤水晶，再帮我们召唤出一个黑暗信使。$B$B在黑暗信使被发现之前，它将一直作为我们的耳目，小心地观察敌人的行动。', '奥格瑞姆之锤的库尔迪拉希望你去收集5份黑暗物质，然后在奥尔杜萨召唤出一名黑暗信使。', '做得很好，我的朋友。$B$B就在我们的对谈期间，信差又进来回报信息了。', '什么事 ，$C?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '召唤黑暗信使', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13366, '需要更多情报', '诅咒教派一直都是以喜欢制订庞大的计划但最终鲜有成功而声明狼藉，但我这次感觉有些不一样……$B$B也许是由于接近巫妖王，提高了他们的热情。不管怎样，它们似乎比以往任何时候都更有信心了。我们必须了解是什么让他们感到自信，并想办法夺走他们的自信！$B$B我相信关键就在他们的研究员身上。去搞清楚他们正在干些什么，然后向我报告具体的细节。', '奥格瑞姆之锤的库尔迪拉希望你从奥尔杜萨的诅咒教派研究员身上收集3页诅咒教派研究笔记，然后将它们组合成诅咒教派论文。', '的确，事态似乎有点严重…', '你找出他们所为何事了吗，$C?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13367, '片刻不得安宁', '那些蠢货居然碰巧找到了可以对我们造成真正威胁的办法！$B$B这一教区的首领奥鲁麦斯在仪式中牺牲了自己，现在他的手下正在把能量导入他的灵魂中。$B$B如果让他继续这样不受干扰地吸收能量，他很快就会变成一个强大的对手。$B$B在他的大厅附近找到他的精华、徽记、节杖和长袍，将它们组合起来，然后在那里的水晶上面使用他的残骸。$B$B快一点，$r！在他变得更加强大之前消灭他！', '奥格瑞姆之锤的库尔迪拉希望转至奥尔杜萨，杀死晋升者奥鲁麦斯。', '雅路麦斯被扎实地打败了，然而我却似乎还能感应到他的魂魄尚在某处盘旋…', '如何，朋友?你击败雅路麦斯了吗?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '击败晋升者奥鲁麦斯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13368, '片刻不得安宁', '是奥鲁麦斯……他的力量又开始增强了，我能感觉到。现在他的手下正在把能量导入他的灵魂中。$B$B如果让他继续这样不受干扰地吸收能量，他很快就会变成一个强大的对手。$B$B回到奥尔杜萨的北部，在他的大厅中将他的精华、徽记、节杖和长袍组合起来，然后在那里的水晶上面使用他的残骸。$B$B快一点，$r！在他变得更加强大之前消灭他！', '奥格瑞姆之锤的库尔迪拉希望转至奥尔杜萨，杀死晋升者奥鲁麦斯。', '雅路麦斯被扎实地打败了，然而我却似乎还能感应到他的魂魄尚在某处盘旋…', '如何，朋友?你击败雅路麦斯了吗?', '', '去冰冠冰川找奥格瑞姆之锤的库尔迪拉·织亡者。', '击败晋升者奥鲁麦斯', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13372, '聚焦之虹的钥匙', '从萨菲隆的爪中掉下了一枚眼球形状的珠宝，里面发出了魔法能量的震荡，你可以听到并感觉到这种声音。对凡人的耳朵来说，这块石头发出的声音甚至可以说是令人感到痛楚难当的。$B$B如此重要的物品显然只能交给红龙女王阿莱克丝塔萨，生命的缚誓者。转至龙骨荒野的龙眠神殿去请求她的指点吧。', '转至龙骨荒野的龙眠神殿，将聚焦之虹的钥匙交给阿莱克丝塔萨，生命的缚誓者。', '这些虹膜之钥原属于最古老的一些蓝龙们看护着。也只有他们受到蓝龙之王玛里苟斯的信任。$B$B这就是我们一直等待着打击魔法之王的时机。$B$B<龙后简短地打量了你>$B$B你还不能使用这个钥匙来进入虹膜，但我想能分给你一点我的力量，让你足够将虹膜打开一点裂口。$B$B这足以引起玛里苟斯的注意了!', '$N，你接触过聚源虹膜之钥!在你身上吗?$B$B<龙后满是忧虑地望着她的伴侣，克拉苏斯。>$B$B然而你是如何得到的呢?噢，萨菲隆还保有着属于他的那块?', '', '去龙骨荒野找巨龙废土的阿莱克丝塔萨，生命的缚誓者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13373, '边缘科学的益处', '我在征用来的轰炸机上安装了绿外线设备，它可以在你进入敌占区执行任务时保护你！去向莉兹·拉齐维格要一架轰炸机，然后飞向轰炸场！$B$B我们会给你配备轰炸机、火箭和护盾。你要保持护盾处于激活状态，并用炸弹攻击轰炸场中的天灾军团。击中目标后立即回来，这里还有很路复用作等着你呢。', '边缘技师塔兹拉要你去杀死40个轰炸场步兵、80个轰炸场军官和15只石像鬼伏击者。', '哈，你成功了!喜不喜欢飞轰炸机呢?我希望你已经适应了，因为我手头上还有些任务要给你……', '你还没完成目标数，$N。是轰炸机不好驾驶吗?', '', '去冰冠冰川找荒凉之门奥尔杜萨的边缘技师塔兹拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13375, '英雄聚焦之虹的钥匙', '从萨菲隆的爪中掉下了一枚眼球形状的珠宝，里面发出了魔法能量的震荡，你可以听到并感觉到这种声音。对凡人的耳朵来说，这块石头发出的声音甚至可以说是令人感到痛楚难当的。$B$B如此重要的物品显然只能交给红龙女王阿莱克丝塔萨，生命的缚誓者。转至龙骨荒野的龙眠神殿去请求她的指点吧。', '转至龙骨荒野的龙眠神殿，将英雄聚焦之虹的钥匙交给阿莱克丝塔萨，生命的缚誓者。', '这些虹膜之钥原属于最古老的一些蓝龙们看护着。也只有他们受到蓝龙之王玛里苟斯的信任。$B$B这就是我们一直等待着打击魔法之王的时机。$B$B<龙后简短地打量了你>$B$B你还不能使用这个钥匙来进入虹膜，但我想能分给你一点我的力量，让你足够将虹膜打开一点裂口。$B$B这足以引起玛里苟斯的注意了!', '$N，你接触过聚源虹膜之钥!在你身上吗?$B$B<龙后满是忧虑地望着她的伴侣，克拉苏斯。>$B$B然而你是如何得到的呢?噢，萨菲隆还保有着属于他的那块?', '', '去龙骨荒野找巨龙废土的阿莱克丝塔萨，生命的缚誓者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13376, '长途轰炸：失落希望之谷！', '$N，战争还在继续。幸运的是，我们存储了充足的炸弹和火箭！新一轮的轰炸又要开始了——这次轰炸任务的航线很长，你要飞过轰炸场，进入失落希望之谷。再去领一架绿外线轰炸机，把那些天灾军团炸成碎片吧！', '边缘技师塔兹拉要你去杀死50个轰炸场步兵、20只石像鬼伏击者和12条霜巢斥候，并摧毁12架天灾战车。', '做得好，$N。你出去的时候，我听到其它的炮手谈起你…我真的认为你来空军会很有前途。', '你还在等什么?万事俱备就欠你这东风。', '', '去冰冠冰川找荒凉之门奥尔杜萨的边缘技师塔兹拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13380, '委以重任', '绿外线技术可以让我们在天灾军团的鼻子底下大摇大摆地行动！而且，我们把这种技术应用到了专门制造的轰炸机上……但不是为了隐藏它们，完全不是那么回事！我们用绿外线技术来保护它们！$B$B去向卡伦·诺尔要一架轰炸机，然后飞到轰炸场上空……用它的护盾和炮台保护自己，并使用投弹器攻击天灾军团。好好练习一下，然后再回来找我。我还有很多更重要的任务要交给你呢！', '吉普利·基罗赫斯要你去杀死40个轰炸场步兵、8个轰炸场军官和15只石像鬼伏击者。', '我从这儿都能听到爆炸声，$N。护盾的效果如何?轰炸机没事吧?$B$B我希望轰炸机没事，因为我这儿还有任务要给你……', '$N，我知道轰炸机不好开，但你得试着熟悉他们，赢得这场与天灾军团的拉锯战。', '', '去冰冠冰川找荒凉之门奥尔杜萨的吉普利·基罗赫斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13382, '长途轰炸：失落希望之谷', '战争还在继续！我有新指令要下达给你。这次轰炸任务的航线很长，你要飞过轰炸场，进入失落希望之谷——你准备好了之后，就去向卡伦领一架轰炸机，对那些天灾军团狂轰滥炸一番吧！', '吉普利·基罗赫斯要你去杀死50个轰炸场步兵、20只石像鬼伏击者和12条霜巢斥候，并摧毁12架天灾战车。', '欢迎回来，$N。进行的如何?刺激吗?现在你可以好好休息一下。但记得要回来!$B$B为了联盟!', '继续努力，$N。胜利不会从天上掉下来。', '', '去冰冠冰川找荒凉之门奥尔杜萨的吉普利·基罗赫斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13384, '永恒之眼的审判', '是时候使用聚焦之虹的钥匙了。$B$B虽然我很希望玛里苟斯能够悬崖勒马，但是当前看来这是不可能的事。局势相当严峻，其它守护巨龙一致认为应该击败织法者。$B$B<克拉苏斯的语调中带着一丝惊惶。>$B$B$N，请你进入永恒之眼，击败玛里苟斯，把魔法之心带回来。', '龙骨荒野龙眠神殿的克拉苏斯要你取回魔法之心。$B$B该任务必须在普通模式下的10人永恒之眼中完成。', '这是一个非常哀伤的日子，不仅对龙族是如此，对所有的艾泽拉斯生灵皆然。我们失去了其中一个最有想法、最有智慧与最古老的伙伴。现在魔法失去了它的守护者。$B$B让我们祈祷，来年之内这是个明智的决定，$N。然而，暴雨将至，而我们却失去了一个最强大的防御。', '只有玛里苟斯拥有魔法之心。这也是他最大的力量来源。', '', '去龙骨荒野找龙眠神殿的克拉苏斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13385, '英雄永恒之眼的审判', '是时候使用聚焦之虹的钥匙了。$B$B虽然我很希望玛里苟斯能够悬崖勒马，但是当前看来这是不可能的事。局势相当严峻，其它守护巨龙一致认为应该击败织法者。$B$B<克拉苏斯的语调中带着一丝惊惶。>$B$B$N，请你进入永恒之眼，击败玛里苟斯，把魔法之心带回来。', '龙骨荒野龙眠神殿的克拉苏斯要你取回魔法之心。$B$B该任务必须在英雄模式下的25人永恒之眼中完成。', '这是一个非常哀伤的日子，不仅对龙族是如此，对所有的艾泽拉斯生灵皆然。我们失去了其中一个最有想法、最有智慧与最古老的伙伴。现在魔法失去了它的守护者。$B$B让我们祈祷，来年之内这是个明智的决定，$N。然而，暴雨将至，而我们却失去了一个最强大的防御。', '只有玛里苟斯拥有魔法之心。这也是他最大的力量来源。', '', '去龙骨荒野找龙眠神殿的克拉苏斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13387, '保护现场', '萨隆邪铁炸弹已经安装完毕，$N。但是我们只有一次机会，千万别搞砸了。$B$B为了确保安全爆破，我们必须夺得这片本地的临时控制权。先去削减天灾士兵的数量吧。', '冰冠堡垒的肯达尔上尉要你去杀死10只笨重的恐尸。', '你就跟萨沙理安说的一样优秀。做的好!', '为了联盟!', '', '去冰冠冰川找冰冠堡垒的肯达尔上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13391, '藏匿行踪', '你不该碰它的。但你已经碰过了，他很快就会来找你。$B$B他一定会找到你，除非你能躲藏起来，不让他发现。$B$B如果你还想活下去，就去弄一些无面者的鲜血回来！', '米斯希尔萨·阿奈尔要你收集3份无面者之血。', '你还等什么?快擦在身子上!$B$B快呀!不然他就要看到你了!', '你拿到血了吗?', '', '去冰冠冰川找纳扎纳克：遗忘深渊的米斯希尔萨·阿奈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13393, '战地维修', '好吧，现在还不到庆功的时候。你顺利地完成了引爆任务，极大地鼓舞了部队的士气，我们要一鼓作气，继续战斗。$B$B士兵们在下面的旷野中发现了一架部落的大型攻城车，似乎还可以使用。恶鬼们好像正在拆卸它的零件。$B$B如果能将它重新组装起来，我们一定能重创山谷里的天灾军团。$B$B当然，你可以要面对为数众多的敌人，但是我对你有信心！', '破天号上的萨萨里安要你从食腐的恶鬼身上收集5块攻城车零件，然后将它们带去失落希望之谷的毁坏的攻城车旁。', '这台石毁车已经饱经风霜，不过总算整体结构没有受到永久性的伤害。你取得的零件应该足以让它再次运转，至少暂时性地。', '那辆石毁车受损的情况不太乐观。', '', '去冰冠冰川的失落希望之谷找毁坏的攻城车。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13394, '竭尽全力', '你要用这台机器去对付天灾军团？你这样是不能胜过他们的。$B$B你或许可以消灭几百个敌人……甚至几千个，但你不能取得胜利。这样不行。$B$B等你摆弄够了这台机器，可以到北边来找我。那里有一座旧军营。我会让你认识到，你要面对的是怎样的敌人。', '使用整修过的攻城车，在失落希望之谷里消灭150只腐朽的食尸鬼、20个霜颅大法师和2个白骨巨人。完成任务之后转至第一军团前线营地，与米斯希尔萨·阿奈尔谈一谈。', '懂了吗?你的确杀了不少，但你每杀一个，另一个马上就从土中爬起来。$B$B你还不了解你正面对什么，$N。让我告诉你。', '玩完了你的战争机器了吗?', '', '去冰冠冰川找失落希望之谷的米斯希尔萨·阿奈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13395, '召唤大军', '你可能觉得自己已经很强大了，足以横扫这些亡灵，驾驶你的战争机器轻易地击败它们。$B$B但是创造出这些亡灵生物的力量更为强大，与之相比，你的力量不值一提。$B$B我见过那位王子本人这样做过。我可以营造一个幻境，向你演示他是怎么做到这一点的……如果你愿意领略一下的话。', '第一军团前线营地的米斯希尔萨·阿奈尔要在幻境中向你演示巫妖王如何召唤一支由101个食尸鬼奴仆组成的部队。', '王子他真正的力量并非在于从尸首中唤起军队…那很容易。$B$B而是让与他并肩作战多次的战士成为尸首…他真正的力量，就是能不择手段完成需要完成的事。', '你明白了吗，$N?', '', '去冰冠冰川找失落希望之谷的米斯希尔萨·阿奈尔。', '召唤食尸鬼奴仆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13397, '辛达苟萨之墓', '你真是一颗耀眼的新星，$N。你瞧，我派别的士兵去执行任务时，他们成功的几率是对半开，而他们活着回来的几率……那可就更低了。$B$B但是你每次都能顺利地完成任务，就像侏儒制造的钟表一样精确！$B$B好啦，我还有一项任务要交给你。山谷东边就是辛达苟萨之墓，最近，诅咒教徒在那里的活动愈发猖獗起来，比如搞些复活冰霜巨龙之类的勾当。我要你去狠狠地教训他们一顿。$B$B我讨厌诅咒教徒。', '破天号上的萨萨里安要你转至辛达苟萨之墓，杀死5个巨龙复活者、8个诅咒教派腐蚀者和3个维库通灵领主。', '做得好，$N。你真让我们其它人逊色不少!', '$N，你回来了!', '', '去冰冠冰川找破天号的萨萨里安。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13398, '巨龙的墓地', '曾经有一群蓝色的巨龙死在这里。现在，他的仆从正在逐个复活它们。$B$B他亲自复活了其中最大的一条龙。给我从雏龙身上弄一些骨灰下来，我会向你展示他是如何复活那条龙的。', '辛达苟萨之墓的米斯希尔萨·阿奈尔要你收集6份雏龙的骨灰。', '连最强大的龙族都必须响应他的召唤。像你这样脆弱的凡人要如何抵抗他?', '你取得骨尘了吗，$N?', '', '去冰冠冰川找辛达苟萨之墓的米斯希尔萨·阿奈尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13400, '猎人与王子', '在王子成为国王之前，他经历过很多战斗……但其中只有一场战斗使他差点丢掉性命。$B$B那场战斗就发生在这里。等你看过我向你展示的场景以后，你就都明白了。$B$B从地上拣起一块染血的石头，然后你就可以看到当时的情景了。', '白骨之庭的米斯希尔萨·阿奈尔要你去寻找一块染血的石头，并目睹王子的命运。', '大战之后，王子了解唯一绑住他的就是身为\r\n一\r\n个人类…他还是有感觉…他还是会流血…他还有…一颗心。$B$B他成为国王以后的第一件事就是将自己摆脱这个。当我们第一次见面时他将他的心投入了深渊。而你，$N则是那刻起，第一个碰到的人。', '你了解了吗，$N?你了解了?', '', '去冰冠堡垒找白骨之庭的米斯希尔萨·阿奈尔。', '王子的命运', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13403, '提里奥的尝试', '就在今天早上，我的斥候报告说，有一队诅咒教派的教徒带着一样东西离开冰冠堡垒，转至黑暗大教堂了。$B$B现在我明白了，那恐怕就是阿尔萨斯的心脏……里面残留着他的最后一点尚未泯灭的人性。$B$B这是圣光的启示。只要这颗心脏仍然存在，阿尔萨斯·米奈希尔就有可能变回人类！$B$B我们到大教堂的入口处汇合吧。记得带一件教徒的兜帽来，我们要乔装混进去。', '北伐军之峰的提里奥·弗丁要你想办法获取一件诅咒教徒的兜帽，穿上它，然后转至冰冠堡垒西北方的黑暗大教堂入口处与他汇合。', '我并不把刚刚发生的事视为一个错误，$N…恰恰相反地。$B$B藉由一窥这个“心脏”，你让我确信了一件事。阿尔萨斯.米奈希尔已经不复存在了－这里，只剩下巫妖王。', '愿圣光与你同在，$N。', '', '去冰冠冰川找北伐军之峰的大领主提里奥·弗丁。', '', '提里奥的尝试', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13404, '短程行动：轰炸场', '这只是个小任务，目标是轰炸场一带，不过作为热身还是很不错的。你准备好了吗？', '吉普利·基罗赫斯要你去杀死50个轰炸场步兵、10个轰炸场军官和20只石像鬼伏击者。', '欢迎回来，$N。时间过的真快，不过相当激励人心，不是吗?现在休息一下。晚点等你有新任务时再回来。', '继续努力，$N。胜利不会从天上掉下来。', '', '去冰冠冰川找荒凉之门奥尔杜萨的吉普利·基罗赫斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13405, '战斗的召唤：远古海滩', '诺森德的战斗并不仅仅是对抗巫妖王的部队，我们还要与那些部落交锋。$B$B最近我们在远古海滩发现了一件强大的泰坦神器。你应该知道，我们矮人向来都是这类神器的保管者，因此我们也同样有资格获得这件新发现的神器。$B$B眼下，部落对这件神器表现出了极大的兴趣，他们很显然想要盗取神器，并用它来对付我们。联盟必须不惜一切代价阻止他们！', '在远古海滩战场中获得一场胜利，然后向任意联盟主城、冬拥湖、达拉然或沙塔斯城中的联盟准将复命。', '好极了，$N!在你的帮忙下远祖滩头完全纳入了联盟的控制下。', '你从前线带来了什么消息，$N?', '在远古海滩获胜', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13406, '短程行动：轰炸场', '准备接个规模轰炸任务来热热身吗？我现在就给你下命令，轰炸机也已经准备好了。', '边缘技师塔兹拉要你去杀死50个轰炸场步兵、10个轰炸场军官和20只石像鬼伏击者。', '哈，你成功了!我老远就听的到那些天灾碎片撞上山壁的破裂声。做得好。我还有任务要再给你……', '你还没完成目标数，$N。出发继续炸些什么去。', '', '去冰冠冰川找荒凉之门奥尔杜萨的边缘技师塔兹拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13407, '战斗的召唤：远古海滩', '虽然说我们开进诺森德是为了扫平天灾军团，但这并不代表我们应该对联盟不闻不问。$B$B探险者协会的矮人已经发现了一件强大的泰坦圣物的所在地，如果让联盟拿到它的话，我们就没好日子过了。$B$B去吧，$N，消灭我们的敌人。让他们明白，无论在哪里相遇，他们永远都是我们不共戴天的死敌。', '在远古海滩战场中获得一场胜利，然后向任意部落主城、冬拥湖、达拉然或沙塔斯城中的部落战争使者复命。', '你为我们带来了至高无上的荣耀，$N!联盟的弱者们一定被伟大的部落踩在脚下!', '你回来了!凯旋而归了吗，$N?', '在远古海滩获胜', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13408, '地狱火半岛的工事', '地狱火堡垒与我们的军队一直有着小规模的冲突与交战。当前，我们自己的领地大多守备稳固，但一直没能对他们发动真正的进攻。为了筹备进攻，我们要首先占领地狱火堡垒外围的战略要地。$B$B我们的斥候当前确定了三处互成犄角之势的工事，希望你能协助这三处的防守。占领所有工事之后回来向我报告。$B$B愿你能在接下来的战斗中有好运气，$N，毫无疑问，你得面对部落的威胁，他们也同样想占领这三处重要的工事。', '占领了望台、竞赛场和碎石岭，然后向地狱火半岛上荣耀堡内的委任官翠希·普罗维尔复命。', '干得好，$N。你的行动，对我们在地狱火半岛上的战事，有相当的助益。', '$N，一旦你已在夺取各个堡垒的行动中建功，回来向我回报!', '', '去地狱火半岛找荣耀堡的委任官翠希·普罗维尔。', '占领瞭望台', '占领竞赛场', '占领碎石岭', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13409, '地狱火半岛的工事', '在我们的故乡肆虐的所有地狱火堡垒邪兽人都必须要消灭干净！但要想攻击地狱火堡垒，我们必须首先占领堡垒外围的几处战略要地。$B$B巡逻队发现有三处工事正好适合我们的目的。但联盟竟与我们不谋而合，现在已经派出部队占领了那里！$B$B我要求你立刻阻止联盟的行动，并占领这些工事。协助我军占领工事之后，立刻回来向我报告。$B$B为了部落！', '占领了望台、竞赛场和碎石岭，然后向地狱火半岛上萨尔玛的传令官布莱肯·黑眼复命。', '干得好，$N。我几乎可以听见在那些堡垒中开展的战事。我真希望我在现场观看!', '协助占领各处堡垒后再来见我!', '', '去地狱火半岛找萨尔玛的传令官布莱肯·黑眼。', '占领瞭望台', '占领竞赛场', '占领碎石岭', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13410, '地狱火半岛的工事', '地狱火堡垒与我们的军队一直有着小规模的冲突与交战。当前，我们自己的领地大多守备稳固，但一直没能对他们发动真正的进攻。为了筹备进攻，我们要首先占领地狱火堡垒外围的战略要地。$B$B我们的斥候当前确定了三处互成犄角之势的工事，希望你能协助这三处的防守。占领所有工事之后回来向我报告。$B$B愿你能在接下来的战斗中有好运气，$N，毫无疑问，你得面对部落的威胁，他们也同样想占领这三处重要的工事。', '占领了望台、竞赛场和碎石岭，然后向地狱火半岛上荣耀堡内的委任官翠希·普罗维尔复命。', '干得好，$N。你的行动，对我们在地狱火半岛上的战事，有相当的助益。', '$N，一旦你已在夺取各个堡垒的行动中建功，回来向我回报!', '', '去地狱火半岛找荣耀堡的委任官翠希·普罗维尔。', '占领瞭望台', '占领竞赛场', '占领碎石岭', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13411, '地狱火半岛的工事', '在我们的故乡肆虐的所有地狱火堡垒邪兽人都必须要消灭干净！但要想攻击地狱火堡垒，我们必须首先占领堡垒外围的几处战略要地。$B$B巡逻队发现有三处工事正好适合我们的目的。但联盟竟与我们不谋而合，现在已经派出部队占领了那里！$B$B我要求你立刻阻止联盟的行动，并占领这些工事。协助我军占领工事之后，立刻回来向我报告。$B$B为了部落！', '占领了望台、竞赛场和碎石岭，然后向地狱火半岛上萨尔玛的传令官布莱肯·黑眼复命。', '干得好，$N。我几乎可以听见在那些堡垒中开展的战事。我真希望我在现场观看!', '协助占领各处堡垒后再来见我!', '', '去地狱火半岛找萨尔玛的传令官布莱肯·黑眼。', '占领瞭望台', '占领竞赛场', '占领碎石岭', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13413, '展翅高飞！', '凡人，你居然有勇气靠近玛里苟斯的巢穴？还是说你只是因为无知才闯进这里的？答案很快就可以揭晓了……$b$b我是一名经验丰富的训练师，专门为红龙军团训练优雅的幼龙。我来这里研究敌人的作战手段，并向我珍爱的宠物们传授有效的御敌手段，以便将来能对付蓝龙军团的主子。$b$b为了让你有机会证明自己的勇气和实力，我可以让你骑着我的幼龙去对付敌人的爪牙。$b$b只要你开口，就可以得到这个宝贵的机会……', '考达拉魔枢上层的科拉丝塔萨要你骑着她的幼龙杀死5名鳞誓精英。', '我注意到你今天的确有些长进，$C。某几个瞬间，你和龙彷佛合而为一了。$B$B我很欢迎你，在有空的时候，和我珍贵的宠物砥砺技术。', '是，$r?', '', '去北风苔原找魔枢的科拉丝塔萨。', '杀死鳞誓精英', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13414, '展翅高飞！', '我们又见面了，$r。我要承认，我对你越来越感兴趣了。$b$b如果我没猜错的话，你是来练习空战技巧的吧？$b$b像平时一样，我的宠物已经做好准备，随时可以去消灭敌人。$b$b只要你开口，就可以随意调遣它们。', '考达拉魔枢上层的科拉丝塔萨要你骑着她的幼龙杀死5名鳞誓精英。', '我注意到你今天的确有些长进，$C。某几个瞬间，你和龙彷佛合而为一了。$B$B我很欢迎你，在有空的时候，和我珍贵的宠物砥砺技术。', '是，$r?', '', '去北风苔原找魔枢的科拉丝塔萨。', '杀死鳞誓精英', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13415, '图书馆的控制台', '$N，诺甘农之壳近在咫尺，唾手可得。拿上创世者的圆盘转至图书馆的内部，你应该可以在那里找到一个用来激活圆盘的控制台。我想米米尔存储在那里的东西远比诺甘农之壳更多，甚至可能包括能让铁炉堡的工程师们忙上许多年的结构图！$B$B不管怎样，用圆盘来恢复诺甘农之壳。希望米米尔没有给我们设置什么棘手的障碍。', '拿着创世者的圆盘，转至创世者的图书馆内的控制台。', '<你将圆盘置入了控制台。忽然，面板上透出光芒，一阵计算机的仿真语音传了出来。>$B$B发明者圆盘已确认。欢迎回来，守护者弥米尔。', '控制台上出现了可以发明者圆盘引导的开关。', '', '去风暴峭壁的山底平原找创世者的图书馆控制台。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13416, '图书馆的控制台', '$N，诺甘农之壳近在咫尺，唾手可得。拿上创世者的圆盘转至图书馆的内部，你应该可以在那里找到一个用来激活圆盘的控制台。我想米米尔存储在那里的东西远比诺甘农之壳更多，甚至可能包括能让铁炉堡的工程师们忙上许多年的结构图！$B$B不管怎样，用圆盘来恢复诺甘农之壳。希望米米尔没有给我们设置什么棘手的障碍。', '拿着创世者的圆盘，转至创世者的图书馆内的控制台。', '<你将圆盘置入了控制台。忽然，面板上透出光芒，一阵计算机的仿真语音传了出来。>$B$B发明者圆盘已确认。欢迎回来，守护者弥米尔。', '控制台上出现了可以发明者圆盘引导的开关。', '', '去风暴峭壁的创世者的图书馆找创世者的图书馆控制台。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13422, '维持纪律', '你完成了别人做不到的壮举。但是你不能满足于眼前的荣耀。$B$B一定要向别人展示力量与责任的真谛。$B$B荒弃矿洞里那些不听话的苦工又该受到教训了。让他们明白……不听话的下场。', '布伦希尔达村的仲裁者格蕾塔要你进入荒弃矿洞，对6名筋疲力尽的维库人使用训诫之杖。', '你依然是我们效法的榜样。我们仰慕你，姐妹。', '千岁，我的姐妹。', '', '去风暴峭壁找布伦希尔达村的仲裁者格蕾塔。', '教训筋疲力尽的维库人', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13425, '消灭那些怪胎！', '向你的同胞展示力量还不够。你还去要和我们的敌人作战，好姐妹。$B$B瓦基里安叛徒仍然在培养瘟疫始祖幼龙，侮辱我们高贵的骑龙传统。$B$B请你去夺取她们身上的冰霜油膏，并用它冰冻那些讨厌的瘟疫龙蛋。', '布伦希尔达村的仲裁者格蕾塔要你转至瓦基里安，从瓦基里安候选者身上夺取冰霜油膏，并用冰霜油膏摧毁30枚瘟疫始祖龙卵。', '你在许多方面都出类拔萃。我们感谢你，姊妹。', '你摧毁那些染疫的蛋了吗?', '', '去风暴峭壁找布伦希尔达村的仲裁者格蕾塔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13427, '战斗的召唤：奥特兰克山谷', '事实上，我们在多线作战，$g小子:小姑娘;，而且我们不能把军队部署得太过分布，否则我们可能会全盘皆输！$b$b我们需要以天为单位来部署最关键的部队，今天，奥特兰克山谷的战斗最需要勇敢的士兵们！$b$b现在就出发吧，$N，去帮助雷矛远征军。我们不能就这么看着霜狼氏族逃脱他们应受的惩罚。', '在奥特兰克山谷战场中获得一场胜利，然后向任意联盟主城、达拉然、冬拥湖或沙塔斯城中的联盟准将复命。', '正是我想听到的!在奥特兰克山谷的胜利 - 既使只是暂时的 - 也对我们对抗部落的战略非常重要。', '告诉我，$N。你从前线带来了什么消息?', '在奥特兰克山谷获胜', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13428, '战斗的召唤：奥特兰克山谷', '我们就快要把雷矛入侵者从奥特兰克山谷赶走了，因此我们必须调动一切可能的增援力量来帮助霜狼氏族。$B$B一场决定性的胜利可以让我们腾出足够的资源在其它战场上消灭联盟的那些混蛋。$B$B出发吧，$N。听从霜狼氏族的号令，去赢得无上的荣耀吧！', '在奥特兰克山谷战场中获得一场胜利，然后向任意部落主城、达拉然、冬拥湖或沙塔斯城中的部落战争使者复命。', '再也没有比将入侵者从部落领土中驱逐更大的荣耀了。我们对你今日所援助我们军队的莫大勇气致敬。', '你回来了!你带来了胜利的消息吗?', '在奥特兰克山谷获胜', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13431, '卡达什圣杖', '将制作圣杖所需的元素徽记给我带回来！$B$B土灵徽记在屠龙者格鲁尔手中，他就躲在刀锋山的巢穴里。$B$B另一枚徽记是夜之魇的心脏，据说这只神秘的野兽居住在先知麦迪文的高塔内。$B$B迅速行动吧！', '将土灵徽记和灿烂徽记交给盘牙水库奴隶围栏的异教徒斯卡希斯。', '终于!$B$B挣脱了这些束缚，斗棍也重回我的身边，我就可以把那个深海女巫送回冰冷的深渊去…', '用这根重组过的斗棍，我将挣脱我的束缚并且返回毒蛇神殿向瓦许和她的爪牙报仇!', '', '去找奴隶围栏的异教徒斯卡希斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13432, '永恒水瓶', '伊利丹从永恒之井中取出了七瓶水。他将其中三瓶倒入海加尔山颠的湖泊中，由此形成了第二口永恒之井。岁月流逝，剩下的四瓶水已不知去向。$B$B黑暗之门打开后，我们得知伊利丹将两瓶水交给了他的副官凯尔萨斯和瓦丝琪。取回残馀的永恒之水，我们可以利用它打开通往近代或是远古时期的海加尔山的时光通道。我们必须维持海加尔圣战的事件不被改变。', '时光之穴的索莉多米要你从盘牙水库的瓦丝琪那里取回瓦丝琪的水瓶残馀，并从风暴要塞的凯尔萨斯·逐日者那里取回凯尔萨斯的水瓶残馀。', '即使是这么少量的永恒之井水也包含了不可思议的能量。\r\n\r\n我可以清楚的看到与海加尔相关的每个时空……第二个永恒之井的诞生，伊利丹的监禁，世界之树的附魔，还有……没错!海加尔山战役。\r\n\r\n我们必须加快脚步，时间线并不稳定。', '我要求你做的事几乎是不可能办到的，但我仍然希望你可以成功。全靠你了。', '', '去找塔纳利斯的索莉多米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13476, '无上的荣耀', '与联盟作战是为部落效劳的莫大荣耀！那些在各条战联机和联盟作战的士兵是我们最伟大的成员。我们要消灭我们的对手，而不是仅仅进行小规模的遭遇战，我们要打精心准备的大战。$B$B去每一条战联机消灭联盟吧！为了荣耀！为了部落！', '在每个战场上都取得1枚荣誉奖章，并将它们交给任意部落主城、沙塔斯、达拉然或冬拥湖的部落战争使者。', '你的试炼不会很轻松，但是你的勇气没有丧失，你的力量将会永存。和过去的辉煌告别吧，$C。没有人需要它们来证明自己的价值。向前进，$N。今天你将以英雄的姿态昂首向前!', '阿拉希到处流淌着战士的鲜血，奥特兰克的金属碰撞声不绝于耳。除非你从前线带回了消息，否则不要浪费我的时间!', '', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13478, '共同的努力', '我们并不是在独自与部落交战，$g小伙子:小姑娘;。$B$B如果我们可以取得胜利，那么我们就可以使用部落的资源来在其它的战场上对抗他们。反之，如果我们输掉了这场战争，那么在其它的战场上，部落将会占有优势。$B$B联盟需要更多你这种身经百战、意志坚定的老兵！$N，当你在所有战场上都与部落交战之后再回到我这里。', '在每个战场上都取得1枚荣誉奖章，并将它们交给任意联盟主城、沙塔斯、达拉然或冬拥湖的联盟准将。', '你没有让我失望，$N!你所学到的东西已经超越了奖章和表扬所能达到的范畴，它只有通过经验积累和在战场上的磨练才可以获得。$B$B你干得很好，$C。你是联盟真正的英雄!', '你做得怎么样了，$g小伙子:小姑娘;?', '', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13479, '寻蛋', '复活节，赞美生命和春天的庆典！朋友，我希望你喜欢找彩蛋这项娱乐活动，这样你就可以帮上我的忙了。$b$b我不知道那些德鲁伊在制造彩蛋时到底使用了哪些魔法，他们也不打算给我解释。你在收集彩蛋的时候能不能帮我保留一些蛋壳的碎片？蛋里面的东西你可以自己拿去，那些蛋才是我需要的研究样本。', '春季收集者要你去收集20块蛋壳碎片。', '太好了，太好了，谢谢你!我大概会需要更多的样本才能得到最终的结果，但你今天已经做得够好了。', '你拿到碎片了吗?', '', '去找春季收集者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13480, '寻蛋', '复活节，赞美生命和春天的庆典！朋友，我希望你喜欢找彩蛋这项娱乐活动，这样你就可以帮上我的忙了。$b$b我不知道那些德鲁伊在制造彩蛋时到底使用了哪些魔法，他们也不打算给我解释。你在收集彩蛋的时候能不能帮我保留一些蛋壳的碎片？蛋里面的东西你可以自己拿去，那些蛋才是我需要的研究样本。', '春季收藏者要你去收集20块蛋壳碎片。', '太好了，太好了，谢谢你!我大概会需要更多的样本才能得到最终的结果，但你今天已经做得够好了。', '你拿到碎片了吗?', '', '去找春季收藏者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13502, '巧克力甜又甜，全都装进彩蛋篮', '给你……拿着这只彩蛋篮，去寻找鲜艳的彩蛋吧。找到十块复活节巧克力以后，带着篮子回来找我。', '复活节小贩要你收集10块复活节巧克力，将它们和彩蛋篮一起带回来。', '干得好!喔，拜托…请保留篮子!$B$B记得，你总是可以带着更多的贵族花园巧克力回来交换额外的物品。', '你拿到10个贵族花园巧克力了吗?', '', '去找复活节小贩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13503, '巧克力甜又甜，全都装进彩蛋篮', '给你……拿着这只彩蛋篮，去寻找鲜艳的彩蛋吧。找到十块复活节巧克力以后，带着篮子回来找我。', '复活节商人要你收集10块复活节巧克力，将它们和彩蛋篮一起带回来。', '干得好!喔，拜托…请保留篮子!$B$B记得，你总是可以带着更多的贵族花园巧克力回来交换额外的物品。', '你拿到10个贵族花园巧克力了吗?', '', '去找复活节商人。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13538, '南部的塔楼', '冬拥河南边的三座塔楼正在从堡垒中吸取能量！$B$B去摧毁影目塔楼、火光塔楼或冬缘塔楼，然后回来向我报告。记住，只有攻城车辆可以对塔楼造成伤害，所以你要保护好我们的攻城车，别让部落把它们给拆了！', '摧毁影目塔楼、火光塔楼或冬缘塔楼，然后向冬拥湖的参谋官安布拉米斯复命。', '我从这里就可以听到爆炸声!太出色了 - 我们已经将能量重新导向泰坦圣物，让它强化我们的力量。', '你带来了南方的消息吗?', '', '去找冬拥湖的参谋官安布拉米斯。', '摧毁南部三座塔楼中的一座', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13539, '摧毁塔楼', '虽然联盟正在围攻我们的城门，但是一名真正的战略家所关注的永远不是眼前的局势，而是更长远的谋划。$B$B“攻其不备，出其不意。”$B$B$N，我要派你越过冬拥河，摧毁南部的塔楼。我们的术士报告说，那些塔楼正在吸取能量，而那些能量本应是我们用来增强自身部队战斗力的。$B$B摧毁一座塔楼，然后回来向我报告。', '摧毁影目塔楼、火光塔楼或冬缘塔楼，然后向冬拥湖的参谋官基尔拉斯复命。', '要杀光我们的敌人，我们的士兵必须要愤怒激昂，而击败敌人刚好能提供这些优势，一定要好好奖励他们。我希望这些能配得上你对部落的贡献。', '我对术士的嫌恶几乎快跟我对不死生物的憎恨差不多了。不过，他们在某些时候总还是派得上用场。', '', '去找冬拥湖的参谋官基尔拉斯。', '在冬拥湖南部摧毁一座塔楼', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13549, '拎尾巴', '除了达卡莱巨魔的古物之外，我还打算带一些祖达克地区的野生动物回到赞达拉去。我收集了一些雄性冰霜豹和冰爪熊，但是没有雌性怎么行呢？$B$B糟糕的是，我的猎人在一次不幸的事故中死亡了。也许你愿意替换他的位置？$B$B使用这支吹管催眠冰霜豹和冰爪熊，然后拎起它们的尾巴检查一下，如果是雌性的，就把它们带回这里。你可以在伦诺克、奎丝鲁恩和哈克娅的祭坛周围找到它们。', '希姆托加的记载者图基尼希望你对冰霜豹和冰爪熊使用麻醉飞镖，并给他带回三头雌性冰霜豹和三头雌性冰爪熊。', '很棒的样本。$N!这些动物在我归乡的路上一定会引起同伴们许多好奇的目光。', '不，这样不行。拜托你带着三只雌豹和三只雌熊回来，好让我带着它们踏上艰难的归乡之路。', '', '去祖达克找希姆托加的记载者图基尼。', '捕获雌性冰霜豹', '捕获雌性冰爪熊', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13556, '杜布拉金需要迅猛龙卵', '最近怎么样啊，朋友？你能不能帮我一个忙？拜基妮想要一些迅猛龙的蛋，用来献祭给杜布拉金。$B$B你以为我们为什么还没有被达卡莱巨魔给踏平？当然是因为杜布拉金的庇护和帮助！$B$B你可以去古达克地区的树木周围收集迅猛龙的蛋。有时候迅猛龙也会把蛋带在身上，好让它保持温暖。', '杜布拉金的哈瓦纳希望你去收集12枚古达克迅猛龙卵。', '一，二，三…嘿嘿，还真是多啊，老兄!这下我们可以高枕无忧一段时间啦!', '谁会想到伟大的杜布拉金要这么多的蛋?他又要拿它们做什么咧?', '', '去祖达克找杜布拉金的哈瓦纳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13559, '霍迪尔的供品', '', '', '霍迪尔之子接受你的献礼，小朋友。你在许多方面都证明了自己身为盟友的价值。', '当伟大的霍迪尔还与霜巨人同在时，任何普通的祭礼都配不上他。$B$B也许他已经不在了，但是我们还是保留了为他的力量与智慧献上祭礼的传统。如果你能够为这项传统出一份力，将会大大的提升你的名声，小$C。', '', '去找祖达克的李奥霍夫。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13592, '勇士的实战训练', '在锦标赛上，你可以和你的战友们一起练习技术，但是时刻都不要忘记，我们真正的敌人——天灾军团绝不会坐等灭亡。你不但要和队友切磋，还要在与敌人的战斗中磨砺自己的刀锋。$B$B到位于陨落英雄之谷西南和恐惧之门科雷萨以北的那个地区去。天灾军团正在那里复活死亡的英雄们，并将他们变成我们的敌人。击败那些天灾军团的爪牙，让我们的勇士得到安息，并在那里磨砺你的战斗技艺。', '银色比武场的马库斯·巴洛爵士要你消灭10名被转化的英雄。', '看来你刚热身完毕， $N. 在我们为了参赛而加紧练习时，别忘了天灾军团还在外头肆虐着。', '你有在对抗天灾军的战斗中自我磨练吗?', '', '去找冰冠冰川的马库斯·巴洛爵士。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13600, '珍贵的武器', '为什么我的运气总是烂到家了呢？$B$B下午就要进行比赛了，而我的剑却无影无踪了。$B$B一位吟游诗人告诉我，如果哪位旅人能给一位孤独的女士带去一朵冬水仙，就可以获得她的礼物。那些花只生长在铁墙大坝下游的浮冰上，就在晶歌森林的西北部，与冰冠冰川交界的地方。去摘些这种花，然后把花带到龙骨荒野东北部的达克玛尔湖去，就在该地区与祖达克、灰熊丘陵的交界处。', '将达克玛尔之剑交给银色比武场的雅克布·奥勒留斯元帅。', '<元帅从你手上接过德拉克玛之刃。>$B$B真是一把好剑，完美的平衡性。这一定能让我在下一场比赛好好发挥。', '吟游诗人的传说是真的吗?你拿到剑了没?', '', '去找冰冠冰川的雅克布·奥勒留斯元帅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13603, '冠军的利剑', '啊，说实话，光靠锋利的钢剑是不足以获得胜利的。其它参赛者用的都是附有魔法的武器，这对我非常不利，不过这也不是什么大问题。$B$B一个流传于灰熊丘陵的古老传说中提到，那里有位女士为了守护一把剑受到诅咒，变成了一只青蛙。现在她就住在灰木哨站东边的灰木湖岸上，和其它的湖蛙生活在一起。根据传说，唯一能够解除这道诅咒的方法，是有人自愿去亲吻她。不过呢，你要记得先在嘴唇上涂抹这种药膏，然后再去亲吻湖蛙，不然你的嘴上会长疣的。', '找到灰木之剑，把它交给银色比武场的雅克布·奥勒留斯元帅。', '所以传说是真的?有了这么一柄好剑，我一定能在联赛中好好发挥。非常感谢你，$N.', '你能拿到那柄剑吗?', '', '去找冰冠冰川的雅克布·奥勒留斯元帅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13604, '档案馆数据圆盘', '这张白金圆盘的表面惊人地光滑匀称，没有一丝的划痕和瑕疵。在这张圆盘的边缘，有一行符文刻成的字：“档案馆”。', '奥杜尔内部一定有什么装置可以读取这张圆盘中包含的信息。', '白金圆盘完美无缺地勘合进控制台中。它开始旋转而白色的光束扫过圆盘。', '当控制台的圆形插座打开时，能量在控制台中呼啸流窜。', '', '去找文件馆控制台。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13606, '弗蕾亚的徽记', '我想弗蕾亚的徽记可能是最难得到的一块。$B$B根据文件馆的数据，徽记与弗蕾亚身边的三位古树仆从密切关联，它们是明叶长老、铁枝长老和石树长老。一旦它们之中有任何一位受到伤害，徽记的完整性就不能保障了。$B$B然而，如果你们对这三位长老手下留情，弗蕾亚的力量就会变得更加强大。$B$B我又能说什么呢，$N，我们现在真是进退维谷。', '将弗蕾亚的徽记交给奥杜尔文件馆中的勘探员多尔伦。$B$B你可以向文件馆控制台查询如何获得弗蕾亚的徽记。', '干得漂亮，$N。我们离拯救艾泽拉斯又更近了一步!', '芙蕾雅的符印，$N?你拿到了吗?', '', '去找奥杜尔的勘探员多尔伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13609, '霍迪尔的徽记', '要拿到霍迪尔的徽记可不容易。你不但要击败霍迪尔，而且必须抢在他打碎装着徽记的箱子之前击败他！$B$B如果你想了解更多信息的话，可以去查查文件馆的控制台。那里面的知识比世界上所有的图书馆加在一起还要多！', '将霍迪尔的徽记交给奥杜尔文件馆中的勘探员多尔伦。$B$B你可以向文件馆控制台查询如何获得霍迪尔的徽记。', '你办到了!我不知道你怎么做到的，但你居然成功了!', '你达到符印了吗，$N?', '', '去找奥杜尔的勘探员多尔伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13610, '托里姆的徽记', '托里姆已经失去了自我，$N。一股黑暗的力量正在影响着他。$B$B某个邪恶的家伙假扮成他死去的妻子西芙，蒙蔽了他的心智。$B$B你要阻止那个冒牌货控制托里姆。如果托里姆被这股力量征服，我们就永远都不能找到他的徽记了！$B$B你要让他清醒过来，越快越好！$B$B和以往一样，文件馆的控制台会给你提供所有必要的消息……包括那些你不喜欢听到的消息。', '将托里姆的徽记交给奥杜尔文件馆中的勘探员多尔伦。$B$B你可以向文件馆控制台查询如何获得托里姆的徽记。', '你总是叫人叹为观止，$N。$B$B你跟我一定得在这一切结束之后好好喝一杯，知道吗?', '嗯，$N?你拿到了吗?', '', '去找奥杜尔的勘探员多尔伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13611, '米米尔隆的徽记', '米米尔隆是个聪明的家伙，他给自己的地盘装上了一套自毁设备。$B$B很不幸，如果你想要拿到徽记，就必须争分夺秒。如果你需要了解什么详细的数据，可以去文件馆控制台那里查询。', '将米米尔隆的徽记交给奥杜尔文件馆中的勘探员多尔伦。$B$B你可以向文件馆控制台查询如何获得米米尔隆的徽记。', '我把它交给你了，$N。我们的机会或许不大，但有你的帮助让我安心很多。', '你拿到符印了吗，$N?', '', '去找奥杜尔的勘探员多尔伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13614, '奥尔加隆', '你成功了，$N。把这些徽记拿到文件馆的控制台那里去，看看你能否进入天文台。$B$B你最好快一点，$g伙计:小丫头;，时间紧迫。', '将守护者的徽记带到奥杜尔的文件馆控制台前。', '准备确认。$B$B准许进入星穹浑天仪。请取出你的钥匙。', '控制台的亮光迅速地扫过玻璃的表面，似乎在等待某些输入。', '', '去找文件馆控制台。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13616, '冬之利刃', '那个天杀的死亡骑士，把我的剑给弄坏了！$B$B转至晶歌森林的南部，你可以在水晶裂痕的出口上方找到恒焰领主。杀死他，拿到他身上的恒焰灰烬。$B$B带着恒焰灰烬转至嚎风峡湾北部的冬息湖中心，解救一位被寒冰困在那里的女士。她守护着一把古代宝剑，能够解救她的人就可以获得那把宝剑作为奖励。$B$B证明你的能力，拿到她守护了许久的宝剑吧，$N。', '将冬之利刃交给银色比武场的雅克布·奥勒留斯元帅。', '这柄剑真是名不虚传。看来不需要修复我原有的那把剑了。凛冬之锋远远超过我的旧剑，我会继续使用它。我由衷地感谢你，$N.', '你赢得了我要找的剑吗?', '', '去找冰冠冰川的雅克布·奥勒留斯元帅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13625, '学习骑战', '锦标赛中的大部分项目都要求参赛者熟练掌握骑乘战斗的技巧。为了让大家熟悉一边驾驭坐骑一边战斗的方式，我们在赛场北部布置了一些训练用的假人。$B$B到大帐外面的兽栏中去，拿起你的长枪，跨上奎尔多雷战马吧。你可以熟悉一下骑乘战斗中能够使用的战术，然后击败三种不同种类的训练假人。', '使用刺击技能攻击一个近战目标5次，使用碎盾技能攻击2个脆弱的远程目标，使用冲锋技能攻击2个脆弱的冲锋目标，然后回到银色比武场，向斥候沙琳蒂亚复命。$B$B如果你丢失了长枪，可以在银色盟约大帐或者兽栏附近的长枪架上再拿一根。', '干得好，$N。对那些习惯于步兵战斗的人，骑乘战斗可是很难上手的。我相信你会继续精进你的技巧，应该不需要我多言。', '骑乘战斗练习得如何了?', '', '去找冰冠冰川的斥候沙琳蒂亚。', '对近战目标使用刺击', '对脆弱的远程目标使用碎盾', '对脆弱的冲锋目标使用冲锋', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13627, '砍木头', '过来一点。不不不，别太近。我们可不想引起什么不必要的怀疑，对吧？$B$B建造这座竞技场需要许多木材，我们的存货远远不够。但是我又没有义务花钱从灰熊丘陵运货过来。在晶歌森林的西边，符印巨树的附近有许多新长成的晶歌森林橡树。$B$B这些橡树做成的木板完全可以满足我们盖房子、搭手脚架的需要。带着这把斧子，去把那些小橡树砍倒并削成符合我们要求的木板吧。注意，不要让别人看到你！', '把12块做工粗糙的木板交给银色比武场的贝兹尔·布拉斯波。', '真是很棒的木材，而且价格也合理!更棒的是，那些身陷泥淖的银色北伐军根本不会知道。他们会得到他们珍贵的大竞技场，而我则会拿到提早完工的奖金。我想这应该是个双赢的局面吧。', '你把我们之前提到的『货物』给带来了吗?', '', '前往冰冠冰川，去找银色比武场的贝兹尔·布拉斯波。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13633, '西部荒野的黑骑士？', '最近有不少关于那个被称为“黑骑士”的选手的传闻，你肯定也听说了吧？据说凡是将要与他对阵竞技的骑士都会惨遭横死。$B$B当然了，我们手里还没有确切的证据，不过调查一下他的后台总不会错的。$B$B他自称来自西部荒野的库珀系列。你能不能到西部荒野的月溪镇去一趟，在镇子里的西部本地调查一下这个系列的住所？看看你能不能查出些什么线索。', '调查黑骑士的身世是否属实，然后回到银色比武场，向北伐军战士莱达拉汇报你的发现。', '所以你说黑骑士的说词全是假的?太可疑了。轻则说谎，重则谋杀。但是我们不能揭穿他，除非我们能找到他涉入这些谋杀的证据。$B$B别引起他的怀疑，$N。谨慎行事有助于我们进一步的调查。', '你有找到任何东西能证实黑骑士的故事吗?', '', '去冰冠冰川找黑色观察站的北伐军战士欧尔拉金·萨利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13634, '银松森林的黑骑士？', '最近有不少关于那个被称为“黑骑士”的选手的传闻，你肯定也听说了吧？据说凡是将要与他对阵竞技的骑士都会惨遭横死。$B$B当然了，我们手里还没有确切的证据，不过调查一下他的后台总不会错的。$B$B他自称出生于银松森林的瓦尔甘农场。这个小农场就坐落在洛丹米尔湖的西岸。你能否到农场去调查一下，看看他说的是不是实话？', '调查黑骑士的身世是否属实，然后回到银色比武场，向北伐军战士莱达拉汇报你的发现。', '所以你说黑骑士的说词全是假的?太可疑了。轻则说谎，重则谋杀。但是我们不能揭穿他，除非我们能找到他涉入这些谋杀的证据。$B$B别引起他的怀疑，$N。谨慎行事有助于我们进一步的调查。', '你有找到任何东西能证实黑骑士的故事吗?', '', '去冰冠冰川找黑色观察站的北伐军战士欧尔拉金·萨利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13641, '先知的水晶', '既然已经知道这个黑骑士一直在胡扯，那我们就必须查出他和那些骑士的死之间有什么牵连。$B$B我有一个办法，可以查出他们死亡的真相，不过我需要一种稀有的材料。我们必须弄到一块先知的水晶。这种水晶只有在晶歌森林的萨特身上才能找到。到晶歌森林中部的绝望之林去，在那里的暗夜向导废墟附近寻找自由的先知，把水晶给我带回来。', '将一块先知的水晶交给银色比武场的北伐军战士莱达拉。', '这颗就很够用了。现在只需要将圣光之力灌注其中，赋予它揭露真相的能力。', '你找到先知水晶了吗?', '', '去冰冠冰川找黑色观察站的北伐军战士欧尔拉金·萨利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13643, '死者讲述的故事', '这块水晶将揭开那三名选手的死亡真相。把它带到比赛场东边的墓地里去，并在温德尔·巴尔弗爵士、洛林·阳焰和康纳尔·铁拳的墓前使用它。$B$B如果他们真的是被谋杀的，那我们必须在黑骑士再次行动前抓住他的把柄。你要仔细观察水晶所展示的东西，$N，我们必须确证这些死亡不是巧合。', '在温德尔·巴尔弗爵士、洛林·阳焰和康纳尔·铁拳的坟墓前使用先知的水晶，查出他们死亡的真相，然后将结果报告给北伐军战士莱达拉。', '所以你说洛瑞安.日炎是死于中毒，而温德尔.贝尔弗爵士被活活烧死?真是可怕的死法，两个人都是。只有康欧.铁握是被刀剑所杀，而照你所说，那是胆小鬼的偷袭，他死于一场不光彩的战斗。$B$B这三个人原本都排定要和黑骑士打斗。这可不是巧合。现在，我们一定要找出方法来证明这是黑骑士所为。', '你去造访那些被杀害参赛者的墓地了吗?', '', '去冰冠冰川找黑色观察站的北伐军战士欧尔拉金·萨利斯。', '调查温德尔·巴尔弗爵士的死因', '调查洛林·阳焰的死因', '调查康纳尔·铁拳的死因', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13654, '怪异的侍从', '每天，黑骑士的侍从玛洛里克都会扛着斧子，大摇大摆地离开营地，转至晶歌森林。他必然是想让我们相信他是出去砍柴了，但每次他都只带回几根小树枝。$B$B他经常到暮色之镜西南方的废墟去。也许他的骑士领主的确是让他去办什么事情，但即使如此，他在那里待的时间也太长了些。$B$B想点什么办法吸引他的注意力，或者把他打昏，然后搜搜他身上的东西。如果他真的在打什么鬼主意，我们可不能蒙在鼓里。', '从一个骷髅伐木工身上取下一根大腿骨，用它打昏玛洛里克。在玛洛里克身上搜查一番，找到证据后向银色比武场的北伐军战士莱达拉报告。', '<十字军莱达菈带着一脸恶心和厌恶检查着袋子中的东西。>$B$B全在这里了，$N:杀死洛瑞安的毒药、一组小刀、火把和燃油。这里没有人该随身携带这种东西，而且也没有一个侍从会在没有骑士的命令下带着这些东西。我们找到凶手了，$N，但他为谁工作?', '侍从的举止有透露出什么线索吗?', '', '去冰冠冰川找黑色观察站的北伐军战士欧尔拉金·萨利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13662, '获得信任', '', '', '继续拿残油来!', '你已经达到了可以和兄弟会进行合作的层次了，$r。我们开始对你另眼相看。干得很不错!$B$B如果你希望能赢得我们更多的尊敬，那就听好了。$B$B我们可以通过在炽热助熔剂中添加黑铁残油的方式来进一步提炼它，到黑石深渊去收集黑铁残油吧。$B$B把你找到的所有黑铁残油都交给我!', '', '去找灼热峡谷的大铁匠博恩奈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13663, '黑骑士的命令', '我们必须调查清楚，是谁把这个黑骑士派到锦标赛上来的，杀死这些参赛者又会给他的主人带来什么好处。$B$B肯瑞托的代表愿意帮助我们调查这件事情，他为我们提供了一件必要的工具。$B$B拿着这条魔法缰绳，到比武场东侧的黑骑士营地去，用它控制黑骑士的狮鹫。缰绳上的魔法会强迫狮鹫把你带到它主人的家里去。调查那个地方，然后回来向我报告。', '使用魔法缰绳控制黑骑士的狮鹫，骑着它飞到目的地，然后找到被偷走的锦标赛邀请函和黑骑士的命令，并把它们带回银色比武场，交给北伐军战士莱达拉。', '<十字军莱达菈在阅读命令时脸色变得惨白。>$B$B这只代表了一件事，$N。黑骑士是一名诅咒神教的成员，他是由阿尔萨斯派来破坏联赛的!$B$B黑骑士是令人畏惧的竞技高手，你需要用尽全力才能对付他。等你成为一位勇士之后，回来找我，我们会想办法确保他会被击败伏法。', '你有何发现?', '', '去冰冠冰川找黑色观察站的北伐军战士欧尔拉金·萨利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13665, '总决赛', '总决赛是锦标赛中最重要的一场比赛。暴风城的人民非常崇拜他们的骑士，希望我们能在这场战斗中获胜。为了这个目标，我们要不断地与其它的勇士们比武练习，提升自己的战斗能力。$B$B我推荐你也参加。$B$B到大帐外面的兽栏中去，拿起你的长枪，骑上兽栏中的艾尔文战马，去挑战其它的勇士吧。联盟勇士的练习场就在我们的帐篷外面，他们在那里等待你的挑战。', '将三枚勇士的印记交给银色比武场的约瑟夫·霍雷上尉。$B$B如果你丢失了长枪，可以在银色盟约大帐或者兽栏附近的长枪架上再拿一根。', '干得好。和其他骁士对战是准备联赛的最佳方法。我知道你一定会让暴风城引以为傲的， $N.', '你完成了技击大赛的训练吗?', '', '去找冰冠冰川的约瑟夫·霍雷上尉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13666, '冠军的利剑', '有些冠军认为，诺森德出产的古代武器可以在比赛中给他们带来好运。我答应帮他们去寻找这些武器。$B$B一个流传于灰熊丘陵的古老传说中提到，那里有位女士为了守护一把剑受到诅咒，变成了一只青蛙。现在她就住在灰木哨站东边的灰木湖岸上，和其它的湖蛙生活在一起。根据传说，唯一能够解除这道诅咒的方法，是有人自愿去亲吻她。不过呢，你要记得先在嘴唇上涂抹这种药膏，然后再去亲吻湖蛙，不然你的嘴上会长疣的。', '找到灰木之剑，把它交给银色比武场的奥术师泰利斯。', '所以那个古老传说是真的?至少这把剑的质地是名不虚传。干得好，$N。能配上这把剑的勇士的确运气不错。', '你能拿到那柄剑吗?', '', '去找冰冠冰川的奥术师泰利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13669, '珍贵的武器', '我们的勇士对诺森德出产的古代武器都很有兴趣。$B$B一位吟游诗人告诉我，如果哪位旅人能给一位孤独的女士带去几朵冬水仙，就可以获得她的礼物。那些花只生长在铁墙大坝下游的浮冰上，就在晶歌森林的西北部，与冰冠冰川交界的地方。去摘些这种花，然后把花带到龙骨荒野东北部的达克玛尔湖去，就在该地区与祖达克、灰熊丘陵的交界处。', '将达克玛尔之剑交给银色比武场的的奥术师泰利斯。', '这把剑刃的精致的质量与平衡度是无可挑剔的。现在我知道为何联盟的勇士们如此渴求这些武器。', '吟游诗人的传说是真的吗?你拿到剑了没?', '', '去找冰冠冰川的奥术师泰利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13670, '冬之利刃', '铁炉堡总冠军的侍从给我讲了一个有趣的故事。$B$B转至晶歌森林的南部，你可以在水晶裂痕的出口上方找到恒焰领主。杀死他，拿到他身上的恒焰灰烬。$B$B带着恒焰灰烬转至嚎风峡湾北部的冬息湖中心，解救一位被寒冰困在那里的女士。她守护着一把古代宝剑，能够解救她的人就可以获得那把宝剑作为奖励。$B$B证明你的能力，拿到她守护了许久的宝剑吧，$N。', '将冬之利刃交给银色比武场的奥术师泰利斯。', '这把剑真的跟侍从说得一样好，但是他怎么知道这件事的?不管他了，它一定能让新的持有者大显神威。或许铁炉堡的大勇士正是适合的人。', '你赢得了那把剑吗?', '', '去找冰冠冰川的奥术师泰利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13671, '实战训练', '在锦标赛上，你可以和你的战友们一起练习技术，但是时刻都不要忘记，我们真正的敌人——天灾军团绝不会坐等灭亡。虽然你已经学会了骑乘作战的要领，也不要把这么多年来积累的战斗技巧都给抛到脑后去。我们需要你用实际行动证明，你可以充满荣誉与勇气地面对天灾军团，这样你才有资格参加我们的锦标赛。$B$B到冰冠冰川去，把你在那里遇到的所有天灾军团成员都给干掉。不过你要离轰炸场远一些，那里的敌人实在是太多了。', '银色比武场的阿瓦雷斯·迅击要你在冰冠冰川地区消灭8名天灾军团士兵。除了轰炸场之外，在冰冠冰川的任何地方遇到的天灾都可以。', '你已经证明自己是个合格的战士，$N，你也能成为其它吵着要替联盟而战的志士榜样。', '你有在对抗天灾军的战斗中自我磨练吗?', '', '去找冰冠冰川的阿瓦雷斯·迅击。', '消灭冰冠冰川的天灾士兵', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13672, '迎接挑战', '掌握了身为一名候选者所必备的技术之后，你就可以参加候选者的挑战了。在这场挑战中，我们会测验你骑乘战斗的能力，以此来判断你是否已经做好了成为一名勇士的准备。通过这场挑战之后，你就可以晋升为勇士，加入你所归属的主城的代表团了。$B$B当你准备好了之后，就来找我。', '将15枚候选者的徽记交给银色比武场的奥术师泰利斯，证明你已经准备好迎接候选者的挑战了。', '很好，让我安排一下。', '你想要接受志士的挑战吗?', '', '去找冰冠冰川的奥术师泰利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13673, '冠军的利剑', '有些冠军认为，诺森德出产的古代武器可以在比赛中给他们带来好运。我答应帮他们去寻找这些武器。$B$B一个流传于灰熊丘陵的古老传说中提到，那里有位女士为了守护一把剑受到诅咒，变成了一只青蛙。现在她就住在灰木哨站东边的灰木湖岸上，和其它的湖蛙生活在一起。根据传说，唯一能够解除这道诅咒的方法，是有人自愿去亲吻她。不过呢，你要记得先在嘴唇上涂抹这种药膏，然后再去亲吻湖蛙，不然你的嘴上会长疣的。', '找到灰木之剑，把它交给银色比武场的魔导师埃迪恩·炎谷。', '所以那个古老传说是真的?至少这把剑的质地是名不虚传。干得好，$N。能配上这把剑的勇士的确运气不错。', '你能拿到那柄剑吗?', '', '去冰冠冰川找银色比武场的魔导师埃迪恩·炎谷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13674, '珍贵的武器', '我们的勇士对诺森德出产的古代武器都很有兴趣。$B$B一位吟游诗人告诉我，如果哪位旅人能给一位孤独的女士带去一朵冬水仙，就可以获得她的礼物。那些花只生长在铁墙大坝下游的浮冰上，就在晶歌森林的西北部，与冰冠冰川交界的地方。去摘些这种花，然后把花带到龙骨荒野东北部的达克玛尔湖去，就在该地区与祖达克、灰熊丘陵的交界处。在一圈明灯中找到那位女士。你可以找她要一把珍贵的宝剑。', '将达克玛尔之剑交给银色比武场的魔导师埃迪恩·炎谷。', '这把剑刃的精致的质量与平衡度是无可挑剔的。现在我知道为何联盟的勇士们如此渴求这些武器。', '吟游诗人的传说是真的吗?你拿到剑了没?', '', '去冰冠冰川找银色比武场的魔导师埃迪恩·炎谷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13675, '冬之利刃', '有一位来自奥格瑞玛的勇士给我讲了一个有趣的故事。$B$B转至晶歌森林的南部，你可以在水晶裂痕的出口上方找到恒焰领主。杀死他，拿到他身上的恒焰灰烬。$B$B带着恒焰灰烬转至嚎风峡湾北部的冬息湖中心，解救一位被寒冰困在那里的女士。她守护着一把古代宝剑，能够解救她的人就可以获得那把宝剑作为奖励。$B$B证明你的能力，拿到她守护了许久的宝剑吧，$N。', '将冬之利刃交给银色比武场的魔导师埃迪恩·炎谷。', '这把剑真的跟骁士说得一样好，但是他怎么知道这件事的?不管他了，它一定能让新的持有者大显神威。或许奥格瑞玛的大勇士正是适合的人。', '你赢得了那把剑吗?', '', '去冰冠冰川找银色比武场的魔导师埃迪恩·炎谷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13678, '迎接挑战', '掌握了身为一名候选者所必备的技术之后，你就可以参加候选者的挑战了。在这场挑战中，我们会测验你骑乘战斗的能力，以此来判断你是否已经做好了成为一名勇士的准备。通过这场挑战之后，你就可以晋升为勇士，加入你所归属的主城的代表团了。$B$B当你准备好了之后，就来找我。', '将15枚候选者的徽记交给银色比武场的魔导师埃迪恩·炎谷，证明你已经准备好迎接候选者的挑战了。', '很好，让我安排一下。', '你想要接受志士的挑战吗?', '', '去冰冠冰川找银色比武场的魔导师埃迪恩·炎谷。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13679, '候选者的挑战', '作为一名候选者，你进行了非常刻苦的训练，$N。现在，你该去寻找与你势均力敌的对手来练习骑乘战斗的技术。$B$B拿起你的长枪，到大帐外面的兽栏中去，骑上奎尔多雷战马。$B$B转至比武场北部的候选者赛场，你可以在那里找到侍从大卫。他会询问你是否已经做好了战斗准备，并为你安排对手。$B$B祝你好运，$N。愿你的坐骑平稳而可靠，你的攻击准确而凶狠。', '和侍从大卫谈一谈，召唤你的对手。击败银色勇士之后回到银色比武场，向奥术师泰利斯复命。$B$B如果你丢失了长枪，可以在银色盟约大帐或者兽栏附近的长枪架上再拿一根。', '实至名归，$N。你已经击败了你的挑战者，赢得了晋级为骁士的资格。', '你面对了你的挑战吗?', '', '去找冰冠冰川的奥术师泰利斯。', '击败银色勇士', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13680, '候选者的挑战', '作为一名候选者，你进行了非常刻苦的训练，$N。现在，你该去寻找与你势均力敌的对手来练习骑乘战斗的技术。$B$B拿起你的长枪，到大帐外面的兽栏中去，骑上夺日者陆行鸟。$B$B转至比武场北部的候选者赛场，你可以在那里找到一个名叫侍从大卫的人类小孩子。他会询问你是否已经做好了战斗准备，并为你安排对手。$B$B祝你好运，$N。愿你的坐骑平稳而可靠，你的攻击准确而凶狠。', '和侍从大卫谈一谈，召唤你的对手。击败银色勇士之后回到银色比武场，向魔导师埃迪恩·炎谷复命。', '实至名归，$N。你已经击败了你的挑战者，赢得了晋级为骁士的资格。', '你面对了你的挑战吗?', '', '去冰冠冰川找银色比武场的魔导师埃迪恩·炎谷。', '击败银色勇士', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13681, '奥杜尔的石块', '我跟你说，收集石材的活儿简直是场噩梦！古代废墟里有那么多的石头，但那些满嘴圣光长圣光短的圣骑士非得一根筋地说那是什么“无价的圣物”。$B$B总之，坐在这里抱怨是没法凭空把房子盖起来的。风暴峭壁的山底平原和创世者的图书馆中到处都是坍塌的泰坦废墟。喏，带上我的……嗯……凿子，看看能不能把那些大石块弄小一点，折腾成我们能用的材料。', '将15块小石块交给银色比武场的波兹尔·布拉斯波。', '这样应该够了。别跟那些十字军瞎说你从哪里弄到这些石头。我肯定他们一定会很沮丧。但，你知道，反正泰坦又不会回来。我觉得这是物尽其用，拿得心安理得。做得漂亮，$N。', '你拿到那些石头了吗?', '', '转至冰冠冰川，去找银色比武场的波兹尔·布拉斯波。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13682, '空中的威胁', '在你找出诅咒教派的间谍以后，大领主提里奥·弗丁安排了双倍的卫兵。弗丁大人认为诅咒教派不会仅仅因为失去一个黑骑士就善罢甘休。$B$B根据天爪龙斥候的报告，有一支诅咒教派的部队正准备袭击我们，他们的首领是一条名叫冰喉的冰霜巨龙。如果不阻止他们的话，赛场就会受到攻击。斥候们说，冰喉就盘旋在我们的西南方向，铁墙大坝和奥尔杜萨交界的地方。', '银色比武场的纯洁者耶德瑞克要你消灭3名诅咒教派投弹手，并击败冰喉。', '$N，你和你的盟友帮助联赛免于毁灭性的攻击。虽然我们的天爪骑士非常英勇，但他们的人手几乎都用在维持联赛的地面安全，很难防范诅咒神教来自空中的攻击。银色北伐军和所有在此参与联赛的人都由衷地感谢你。', '你击败了诅咒神教的突袭队吗?', '', '转至冰冠冰川，去找银色比武场的纯洁者耶德瑞克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13697, '勇士之战', '在勇士的训练中，你将有机会和来自其它城市的各位勇士较量，以检验自己的作战技术。虽然勇士之间的战斗并非比赛的正式内容，但仍然可以从中学到许多有价值的东西——比如对手的战斗风格，还有他们的弱点。$B$B斗志高昂的勇士经常互相比试，为了荣耀和名望而战。$B$B多参加一些勇士的训练吧。等到你有足够的自信成为勇士中的佼佼者之后，就把你所获得的徽记拿来给我。', '将25枚勇士的徽记交给银色比武场的碎颅者莫克拉。', '令人印象深刻，骁士。我会尽快安排你的考验。', '你准备好要证明你身为骁士的技巧?', '', '去冰冠冰川找银色比武场的碎颅者莫克拉。', '', '', '', '');
