INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13756, '总决赛', '总决赛是锦标赛中最重要的一场比赛。埃索达的人民期待着我们能获得这场比赛的胜利。为了这个目标，我们要不断地与其它的勇士们比武练习，提升自己的战斗能力。$B$B我推荐你也参加。$B$B到大帐外面的兽栏中去，拿起你的长枪，骑上兽栏中的秘蓝岛雷象，去挑战其它的勇士吧。联盟勇士的练习场就在我们的帐篷外面，他们在那里等待你的挑战。', '将三枚勇士的印记交给银色比武场的兰妮。$B$B如果你丢失了长枪，可以在银色盟约大帐或者兽栏附近的长枪架上再拿一根。', '干得好。和其它骁士对战是准备联赛的最佳方法。我知道你一定会让我们引以为傲的，$N。', '你完成了技击大赛的训练吗?', '', '去找冰冠冰川的兰妮。', '', '', '', '');
