INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13760, '勇士的实战训练', '在锦标赛上，你可以和你的战友们一起练习技术，但是时刻都不要忘记，我们真正的敌人——天灾军团绝不会坐等灭亡。你不但要和队友切磋，还要在与敌人的战斗中磨砺自己的刀锋。$B$B到位于陨落英雄之谷西南和恐惧之门科雷萨以北的那个地区去。天灾军团正在那里复活死亡的英雄们，并将他们变成我们的敌人。击败那些天灾军团的爪牙，让我们的勇士得到安息，并在那里磨砺你的战斗技艺。', '银色比武场的伊蕾丝蒂亚·刃歌要你消灭10名被转化的英雄。', '看来你刚热身完毕，$N.在我们为了参赛而加紧练习时，别忘了天灾军团还在外头肆虐着。', '你有在对抗天灾军的战斗中自我磨练吗?', '', '去找冰冠冰川的伊蕾丝蒂亚·刃歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13761, '总决赛', '总决赛是锦标赛中最重要的一场比赛。达纳苏斯的人民期待着我们获得这场比赛的胜利。为了这个目标，我们要不断地与其它的勇士们比武练习，提升自己的战斗能力。$B$B我推荐你也参加。$B$B到大帐外面的兽栏中去，拿起你的长枪，骑上兽栏中的达纳苏斯雾刃豹，去挑战其它的勇士吧。联盟勇士的练习场就在我们的帐篷外面，他们在那里等待你的挑战。', '将三枚勇士的印记交给银色比武场的艾莱·觅星。$B$B如果你丢失了长枪，可以在银色盟约大帐或者兽栏附近的长枪架上再拿一根。', '干得好。和其它骁士对战是准备联赛的最佳方法。我知道你一定会让达纳苏斯引以为傲的，$N。', '你完成了技击大赛的训练吗?', '', '去找冰冠冰川的艾莱·觅星。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13762, '冠军的利剑', '听说联盟的冠军都在为他们的战士寻找古代的兵器，我们可不能让他们占这个便宜。$B$B一个流传于灰熊丘陵的古老传说中提到，那里有位女士为了守护一把剑受到诅咒，变成了一只青蛙。现在她就住在灰木哨站东边的灰木湖岸上，和其它的湖蛙生活在一起。根据传说，唯一能够解除这道诅咒的方法，是有人自愿去亲吻她。不过呢，你要记得先在嘴唇上涂抹这种药膏，然后再去亲吻湖蛙，不然你的嘴上会长疣的。', '找到灰木之剑，把它交给银色比武场的碎颅者莫克拉。', '所以传说是真的?这柄剑足以胜过所有联盟参赛者的配剑。', '你能拿到那柄剑吗?', '', '去冰冠冰川找银色比武场的碎颅者莫克拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13763, '珍贵的武器', '为什么我的运气总是烂到家了呢？$B$B下午就要进行比赛了，而我的剑却无影无踪了。$B$B一位吟游诗人告诉我，如果哪位旅人能给一位孤独的女士带去一朵冬水仙，就可以获得她的礼物。那些花只生长在铁墙大坝下游的浮冰上，就在晶歌森林的西北部，与冰冠冰川交界的地方。去摘些这种花，然后把花带到龙骨荒野东北部的达克玛尔湖去，就在该地区与祖达克、灰熊丘陵的交界处。', '将达克玛尔之剑交给银色比武场的碎颅者莫克拉。', '这一把绝佳的武器，足以帮助我在比赛中获胜。感谢你，$N。', '吟游诗人的传说是真的吗?你拿到剑了没?', '', '去冰冠冰川找银色比武场的碎颅者莫克拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13764, '冬之利刃', '那个天杀的死亡骑士，把我的剑给弄坏了！$B$B转至晶歌森林的南部，你可以在水晶裂痕的出口上方找到恒焰领主。杀死他，拿到他身上的恒焰灰烬。$B$B带着恒焰灰烬转至嚎风峡湾北部的冬息湖中心，解救一位被寒冰困在那里的女士。她守护着一把古代宝剑，能够解救她的人就可以获得那把宝剑作为奖励。$B$B证明你的能力，拿到她守护了许久的宝剑吧，$N。', '将冬之利刃交给银色比武场的碎颅者莫克拉。', '这柄剑真是名不虚传。看来不需要修复我原有的那把剑了。凛冬之锋远远超过我的旧剑，我会继续使用它。我由衷地感谢你，$N。', '你赢得了那把剑吗?', '', '去冰冠冰川找银色比武场的碎颅者莫克拉。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13765, '勇士的实战训练', '在锦标赛上，你可以和你的战友们一起练习技术，但是时刻都不要忘记，我们真正的敌人——天灾军团绝不会坐等灭亡。你不但要和队友切磋，还要在与敌人的战斗中磨砺自己的刀锋。$B$B到位于陨落英雄之谷西南和恐惧之门科雷萨以北的那个地区去。天灾军团正在那里复活死亡的英雄们，并将他们变成我们的敌人。击败那些天灾军团的爪牙，让我们的勇士得到安息，并在那里磨砺你的战斗技艺。', '银色比武场的埃基诺斯要你消灭10名被转化的英雄。', '一整天的训练没什么害处。很高兴看见你持续锻炼。', '你有在对抗天灾军的战斗中自我磨练吗?', '', '去冰冠冰川找银色比武场的埃基诺斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13767, '总决赛', '总决赛是锦标赛中最重要的一场比赛。胜利必然是来之不易的，但我们有必胜的信心。你必须严格训练你的坐骑，直到它和你融为一体。$B$B这可以帮助你保持战斗的活力。$B$B到大帐外面的兽栏中去，拿起你的长枪，骑上兽栏中的奥格瑞玛座狼，去挑战其它的勇士吧。部落勇士的练习场就在我们的帐篷外面，他们在那里等待你的挑战。', '将三枚勇士的印记交给银色比武场的茉拉·狼女。$B$B如果你丢失了长枪，可以在夺日者大帐或者兽栏附近的长枪架上再拿一根。', '和其他骁士彼此对战训练将能磨利你的爪子，锻炼你的战斗直觉。等到竞赛开始时，你将会做好准备。', '你完成了技击大赛的训练吗?', '', '去冰冠冰川找银色比武场的茉拉·狼女。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13768, '冠军的利剑', '听说联盟的冠军都在为他们的战士寻找古代的兵器，我们可不能让他们占这个便宜。$B$B一个流传于灰熊丘陵的古老传说中提到，那里有位女士为了守护一把剑受到诅咒，变成了一只青蛙。现在她就住在灰木哨站东边的灰木湖岸上，和其它的湖蛙生活在一起。根据传说，唯一能够解除这道诅咒的方法，是有人自愿去亲吻她。不过呢，你要记得先在嘴唇上涂抹这种药膏，然后再去亲吻湖蛙，不然你的嘴上会长疣的。', '找到灰木之剑，把它交给银色比武场的祖尔托。', '所以传说是真的?这柄剑足以胜过所有联盟参赛者的配剑。', '你能拿到那柄剑吗?', '', '去冰冠冰川找银色比武场的祖尔托。', '', '', '', '');
