INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13772, '总决赛', '总决赛是锦标赛中最重要的一场比赛。胜利必然是来之不易的，但我们有必胜的信心。你必须严格训练你的坐骑，直到它和你融为一体。$B$B这可以帮助你保持战斗的活力。$B$B到大帐外面的兽栏中去，拿起你的长枪，骑上兽栏中的暗矛迅猛龙，去挑战其它的勇士吧。部落勇士的练习场就在我们的帐篷外面，他们在那里等待你的挑战。', '将三枚勇士的印记交给银色比武场的加尔祖。$B$B如果你丢失了长枪，可以在夺日者大帐或者兽栏附近的长枪架上再拿一根。', '和其它骁士彼此对战训练是最快让你明白如何击败对手的方法。只要持续练习，你绝对能在竞赛中击败他们。', '你完成了技击大赛的训练吗?', '', '去冰冠冰川找银色比武场的加尔祖。', '', '', '', '');
