INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13860, '兵临城下', '在我们准备锦标赛的同时，银色北伐军也在准备对敌人的冰冠堡垒发动攻击。$B$B在冰冠冰川西南部的白骨之庭，几位勇敢的北伐军战士已经在恐惧之门科雷萨以南创建了先头营地。拿上你的长枪到营地去，骑上军马，击败巫妖王的仆从吧。$B$B你会遇到许多的白骨卫士步兵，不过你完全不用害怕。你的战马可以轻易地将它们踏平。', '银色比武场的马夫德雷奇要求你消灭15名白骨卫士步兵、10名白骨卫士斥候和3名白骨卫士军官。', '银色北伐军看到了我们的决心并且知道我们的战士将会看着这一切直到结束。', '你和白骨之廷的十字军并肩作战了吗?', '', '去冰冠冰川找银色比武场的马夫德雷奇。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13861, '堡垒外的战斗', '在我们为锦标赛做准备工作的时候，我们的兄弟已经准备向敌人的冰冠堡垒发动进攻了。$B$B在冰冠冰川西南部的白骨之庭，几位勇敢的十字军战士已经在恐惧之门科雷萨以南创建了先头营地。拿上你的长枪，骑上军马，到那座营地去击败巫妖王的仆从吧。$B$B你会遇到许多的白骨卫士步兵，不过你完全不用害怕。你的战马可以轻易地将它们踏平。', '银色比武场的纯洁者耶德瑞克要求你消灭3名白骨卫士指挥官。', '在对抗巫妖王的战斗中有你这样的$Cs和我们一起并肩作战激励了银色北伐军。', '你对抗白骨之廷的敌人了吗?', '', '转至冰冠冰川，去找银色比武场的纯洁者耶德瑞克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13862, '堡垒外的战斗', '在我们为锦标赛做准备工作的时候，我们的兄弟已经准备向敌人的冰冠堡垒发动进攻了。$B$B在冰冠冰川西南部的白骨之庭，几位勇敢的十字军战士已经在恐惧之门科雷萨以南创建了先头营地。拿上你的长枪到营地去，骑上银色军马，击败巫妖王的仆从吧。$B$B你会遇到许多的白骨卫士步兵，不过你完全不用害怕。你的战马可以轻易地将它们踏平。', '银色比武场的纯洁者耶德瑞克要求你消灭3名白骨卫士指挥官。', '在对抗巫妖王的战斗中有你这样的$Cs和我们一起并肩作战激励了银色北伐军。', '你对抗白骨之廷的敌人了吗?', '', '转至冰冠冰川，去找银色比武场的纯洁者耶德瑞克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13863, '堡垒外的战斗', '十字军的一部分成员正为锦标赛做准备工作，而另外一些十字军已经准备向敌人的冰冠堡垒发动进攻了。$B$B在冰冠冰川西南部的白骨之庭，几位勇敢的十字军战士已经在恐惧之门科雷萨以南创建了先头营地。拿起长枪，骑上战马，到营地去击败巫妖王的仆从吧。$B$B你会遇到许多的白骨卫士步兵，$N不过你完全不用害怕。你的战马可以轻易地将它们踏平。', '银色比武场的科罗克·斩亡者要求你消灭3名白骨卫士指挥官。', '无论在何处遇见天灾军，我们都使他们感到畏惧，此战也不例外。', '你对抗白骨之廷的敌人了吗?', '', '去找冰冠冰川的科罗克·斩亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13864, '堡垒外的战斗', '十字军的一部分成员正为锦标赛做准备工作，而另外一些十字军已经准备向敌人的冰冠堡垒发动进攻了。$B$B在冰冠冰川西南部的白骨之庭，几位勇敢的十字军战士已经在恐惧之门科雷萨以南创建了先头营地。拿起长枪，骑上战马，到营地去击败巫妖王的仆从吧。$B$B你会遇到许多的白骨卫士步兵，$N不过你完全不用害怕。你的战马可以轻易地将它们踏平。', '银色比武场的科罗克·斩亡者要求你消灭3名白骨卫士指挥官。', '无论在何处遇见天灾军，我们都使他们感到畏惧，此战也不例外。', '你对抗白骨之廷的敌人了吗?', '', '去找冰冠冰川的科罗克·斩亡者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13887, '毒皮暴掠龙蛋', '现在你对毒皮暴掠龙的毒素已经有了免疫力，可以安全地对付这种猛兽和它们的蛋了。毒皮暴掠龙极为凶猛。如果要驯化它们，就必须从它们刚出生时开始。$B$B如果你想要骑上一头毒皮暴掠龙，你就需要先找到一颗尚未孵化的毒皮暴掠龙蛋。在沼泽地各处分布着一些暴掠龙巢。你应该在那些巢里寻找颜色较浅的龙蛋。那些才是能孵化出毒皮暴掠龙的蛋。$B$B如果你能带给我几颗那种蛋。我会让你自己保留一颗，并指导你用它孵化出毒皮暴掠龙崽。', '把4枚毒皮暴掠龙蛋带给位于沼泽地东南的莫维克。', '做得好。老实说我有点讶异，你竟然能找到这么多颗蛋，因为每窝蛋的数量并不多。$B$B我会让你抚养一只刚孵出来的毒皮暴掠龙。它可不会客气的对你提出它的需求。', '你找到那些蛋了吗?', '', '去安戈洛环形山找沼泽地的莫维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13889, '饥饿的小龙', '这只毒皮暴掠龙幼崽用期待的眼神看着你，然后又在土地上画出了一些图案。$B$B这些图案都很粗糙，不过你还是能依稀从里面看出双帆龙，剑龙和翼手龙的形象。这只龙崽画完之后，又向你抬起了头，还露出了牙齿，做了一个咬的动作。$B$B你的毒皮暴掠龙幼崽一定是想要吃这些恐龙的肉了。你要在安戈洛环形山找到并猎杀这些双帆龙、剑龙和翼手龙，取得恐龙肉，喂饱你饥饿的龙崽。', '你的毒皮暴掠龙幼崽想要你喂它15片鲜嫩的恐龙肉。', '毒皮小暴掠龙似乎很满足你提供的大餐，但不知道何时它又会饿。', '毒皮小暴掠龙舔了舔嘴唇并将头偏向一边。', '', '去找毒皮暴掠幼龙。', '喂毒皮暴掠龙幼崽吃鲜嫩的恐龙肉。', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13903, '格里什幼虫', '这只毒皮暴掠龙幼崽用期待的眼神看着你，然后又在土地上画出了一些图案。$B$B这些图案所表现的似乎是一些大型昆虫，一些格里什异种蝎。龙崽画完以后，就用前臂指指图画，凭空猛咬了一口，又舔舔嘴唇。$B$B它一定是想让你去位于安戈洛环形山南部中心处的巨痕谷，在那里收集一些异种蝎肉。得到异种蝎肉之后，就用它来喂养你饥饿的龙崽吧。', '你的毒皮暴掠龙幼崽想要你喂它10块异种蝎肉。', '毒皮小暴掠龙对着你露齿微笑并开始休憩打盹。', '毒皮小暴掠龙歪着头看着你。', '', '去找毒皮暴掠幼龙。', '喂毒皮暴掠龙幼崽吃异种蝎肉。', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13904, '水煮、爆炒还是生吃？', '这只毒皮暴掠龙崽的肚皮发出“咕咕”的响声。它挥舞胳膊，引起了你的注意。然后它在土地上画出一些异种蝎，又在蝎子下面画了一些小的椭圆形。$B$B那一定是异种蝎的卵。你可以到位于塔纳利斯西部，靠近安戈洛环形山边界的腐化之巢去。那里可是一个收集异种蝎卵的好地方。', '你的毒皮暴掠龙幼崽想要你喂它12枚异种蝎卵。', '在吞完异种虫蛋大餐后，你的小暴掠龙舔了舔它的嘴唇。有一瞬间，你觉得它似乎对已经结束的用餐时间感到失望。', '毒皮小暴掠龙看着你。', '', '去找毒皮暴掠幼龙。', '喂毒皮暴掠龙幼崽吃异种蝎卵。', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13905, '炎鹏的羽毛', '这只幼崽一直在看着你，仿佛正在考虑你是否能明白它的意思。它在土地上用爪子画出两根羽毛的图案，然后又指了指绑在它臂肘和膝盖上的东西。$B$B它看上去并不饿，那么它要羽毛干什么？$B$B它一定是想用羽毛做装饰，就像你在其它暴掠龙身上见到过的那样。炎鹏身上的羽毛是所有羽毛之中最大的。这种猛禽生活在塔纳利斯西部，灌木谷的东北方。它们总喜欢聚集在巨大野兽的尸骨周围。', '你的毒皮暴掠龙幼崽想要你给它弄来5根炎鹏的羽毛。', '毒皮小暴掠龙收下这些羽毛，开始打量着它们，并且把羽毛装饰在它的臂环上。', '你的毒皮小暴掠龙期待地看着你。', '', '去找毒皮暴掠幼龙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13906, '飞速成长', '在你的悉心照料和喂养下，你的毒皮暴掠龙幼崽长大得很快。它的乳齿很快就会被成年暴掠龙的牙齿取代了。如果你注意保留你的龙崽在成长过程中脱落的牙齿，那么你就能明确地判断它在何时成长到了可以被训练成坐骑的程度。$B$B你的毒皮暴掠龙会让你知道它需要什么。所以，你要密切注意它的一举一动。等到它的全部乳齿都已脱落的时候，就带着它和制作龙鞍的材料回来见我。我会帮你完成其馀的事情。', '将20枚毒皮暴掠幼龙牙齿、你的毒皮暴掠龙幼崽，还有20块符文布、20块硬甲皮和80金币交给位于安戈洛环形山沼泽地东南的莫维克。', '看来你们一同成长，也没有害死对方。$B$B那么，事情都办妥了。我已经帮你把毒皮暴掠龙给训练好，它已经学会顺从你的哨音了。$B$B很少人能像你这么有毅力，愿意亲手饲养与照料一头毒皮暴掠龙，但你的努力非常值得。', '你有好好照顾那只迅猛龙吗?', '', '去安戈洛环形山找沼泽地的莫维克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13914, '炎鹏的羽毛', '这只幼崽一直在看着你，仿佛正在考虑你是否能明白它的意思。它在土地上用爪子画出两根羽毛的图案，然后又指了指绑在它臂肘和膝盖上的东西。$B$B它看上去并不饿，那么它要羽毛干什么？$B$B它一定是想用羽毛做装饰，就像你在其它暴掠龙身上见到过的那样。炎鹏身上的羽毛是所有羽毛之中最大的。这种猛禽生活在塔纳利斯西部，灌木谷的东北方。它们总喜欢聚集在巨大野兽的尸骨周围。', '你的毒皮暴掠龙幼崽想要你给它弄来5根炎鹏的羽毛。', '毒皮小暴掠龙收下这些羽毛，开始打量着它们，并且把羽毛装饰在它的臂环上。', '你的毒皮小暴掠龙期待地看着你。', '', '去找毒皮暴掠幼龙。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13915, '饥饿的小龙', '这只毒皮暴掠龙幼崽用期待的眼神看着你，然后又在土地上画出了一些图案。$B$B这些图案都很粗糙，不过你还是能依稀从里面看出双帆龙，剑龙和翼手龙的形象。这只龙崽画完之后，又向你抬起了头，还露出了牙齿，做了一个咬的动作。$B$B你的毒皮暴掠龙幼崽一定是想要吃这些恐龙的肉了。你要在安戈洛环形山找到并猎杀这些双帆龙、剑龙和翼手龙，取得恐龙肉，喂饱你饥饿的龙崽。', '你的毒皮暴掠龙幼崽想要你喂它15片鲜嫩的恐龙肉。', '毒皮小暴掠龙似乎很满足你提供的大餐，但不知道何时它又会饿。', '毒皮小暴掠龙舔了舔嘴唇并将头偏向一边。', '', '去找毒皮暴掠幼龙。', '喂毒皮暴掠龙幼崽吃鲜嫩的恐龙肉。', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13917, '格里什幼虫', '这只毒皮暴掠龙幼崽用期待的眼神看着你，然后又在土地上画出了一些图案。$B$B这些图案所表现的似乎是一些大型昆虫，一些格里什异种蝎。龙崽画完以后，就用前臂指指图画，凭空猛咬了一口，又舔舔嘴唇。$B$B它一定是想让你去位于安戈洛环形山南部中心处的巨痕谷，在那里收集一些异种蝎肉。得到异种蝎肉之后，就用它来喂养你饥饿的龙崽吧。', '你的毒皮暴掠龙幼崽想要你喂它10块异种蝎肉。', '毒皮小暴掠龙对着你露齿微笑并开始休憩打盹。', '毒皮小暴掠龙歪着头看着你。', '', '去找毒皮暴掠幼龙。', '喂毒皮暴掠龙幼崽吃异种蝎肉。', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13926, '神谕者孤儿鲁鲁', '孤儿们一直都很期待能有像你这样的朋友，$N。我非常高兴你能答应照顾他们其中的一个。$B$B带上这只哨子。有了它，你随时都能召唤受你照顾的孤儿。你不需要照顾他太久——大概也就是儿童周这段时间。$B$B好了，$N，请召唤你的孤儿吧。他一定会非常喜欢你的。你们一定会在诺森德各处渡过不少愉快的旅程。', '同孤儿监护员艾蕊娅交谈，然后使用神谕者孤儿哨召唤你要在儿童周照顾的孤儿。', '你会让我们远离小小狗人吗?太好了。我们开始喜欢上你了。坏心的小小狗人抢走了所有我们心爱的玩具。', '你照顾我们?', '', '去找神谕者孤儿。如果你的孤儿不在附近那么请使用你的神谕者孤儿哨。', '同孤儿监护员艾蕊娅交谈', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13927, '狼獾人孤儿科科', '孤儿们一直都很期待能有像你这样的朋友，$N。我非常高兴你能答应照顾他们其中的一个。$B$B带上这只哨子。有了它，你随时都能召唤受你照顾的孤儿。你不需要照顾他太久——大概也就是儿童周这段时间。$B$B好了，$N，请召唤你的孤儿吧。他一定会非常喜欢你的。你们一定会在诺森德各处渡过不少愉快的旅程。', '同孤儿监护员艾蕊娅交谈，然后使用狼獾人孤儿哨召唤你要在儿童周照顾的孤儿。', '你带恰嘎去打猎?能够离开那个不让恰嘎去打猎的坏心孤儿院老女士真是太好了。', '孤儿院女士说恰嘎跟你走。', '', '去找狼獾人孤儿。如果你的孤儿不在附近那么请使用你的狼獾人孤儿哨。', '同孤儿监护员艾蕊娅交谈', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13929, '史上最巨大的树！', '在大战爆发，我们离开自己的村庄之前，索乌塞和我们讲过历史上最巨大的树！$B$B索乌塞管那棵树叫灰喉堡。索乌塞告诉我们，它就在灰熊丘陵的中央。不，等等，这不是索乌塞说的。索乌塞说的是灰熊丘陵。肯定没错！那棵好大的树就在灰熊丘陵的中央。绝对没有错！$B$B你带我们去那里好不好？我们要好好看看那棵大树。索乌塞告诉我们，有许多大熊怪就住在那棵树里。也许我们还能看见他们呢。', '带着你的孤儿鲁鲁转至灰喉堡。当你进入到那棵大树的树干里时，如果他不在你身边，一定要召唤他过来。', '我们从不知道树可以长那么大!从不。也许诸神对这树有特别的计画?', '我们可以看大树吗?可以吗?', '带鲁鲁转至灰喉堡', '去找神谕者孤儿。如果你的孤儿不在附近那么请使用你的神谕者孤儿哨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13930, '熊怪的家园', '高阶萨满祭司拉克亚克总是向我们讲强大武士的故事。其中有些故事发生在很远的地方。有时候，他会讲巨大的熊怪为了保卫树城而英勇战斗的故事。$B$B也许你能带科科到那里去，去看看那些大树，还有那里的战场！高阶萨满祭司拉克亚克告诉科科，那座巨大的树城灰喉堡就矗立在灰熊丘陵的正中心。$B$B科科在遇到监护员之前从没有见过一座城市。但这座城市里没有战士，只有穿着紫袍子的人。科科想去看看真正的战士为了真正的城市作战的样子！', '带着你的孤儿科科转至灰喉堡。当你进入那棵巨树的树干时，如果他不在你身边，一定要召唤他过来。', '这是恰嘎心目中理想的城市。熊怪跟狂心者一样为了家园而奋战。孤儿院的女士告诉恰嘎不要和其它小孩打架，但恰嘎仍旧照打。', '恰嘎想去参观熊怪树。我们走吧。', '带科科去看灰喉堡', '去找狼獾人孤儿。如果你的孤儿不在附近那么请使用你的狼獾人孤儿哨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13931, '又一年，又一次纪念', '我们不仅供应美酒，还独家出售啤酒杯呢！瞧这些漂亮的杯子，非常具有纪念意义哦！这是一张礼品券。$B$B与美酒节营地背后的布利克斯谈一谈。他是个古怪的家伙，总是带着一副护目镜。他负责兑换礼品券，以及出售各类美酒。', '在美酒节营地背后的布利克斯·菲克维特处兑换礼品券。', '这是什么?酒杯兑换券?你喜欢喝酒吗?太棒了!我把酒杯给你以后，你就可以喝个痛快了!然后再多喝几杯。也许接着再多来几杯……跟着，重点来了，再回来找我。$B$B听着，我知道迟早你一定会再回来找我的。假如你想要兑换啤酒节奖品章的话，你就要回来找我。$B$B总而言之，这是你的酒杯，记得晚点再来和我谈谈。', '怎么啦宝贝?有东西要给我?', '', '去找杜隆塔尔的布利克斯·菲克维特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13932, '又是一年美酒飘香时。', '美酒节除了赛羊会外，还有一项传统，那就是饮酒狂欢！如果你有时间的话，就将这张礼品券交给贝尔比吧。她就在美酒节营地的后面。要是你看不见她，没关系，她一定会看见你的。$B$B无论如何，将礼品券交给她，你就能免费领到一只美酒节酒杯。她还出售各种美酒哦。', '在美酒节营地的贝尔比处兑换礼品券。', '噢，只是张酒杯兑换券…说不定你还花了一番力气才弄来。好吧，这是你今年的酒杯。$B$B不过我猜我应该还会常常再看到你。无论如何，要是想兑换啤酒节奖章，你找我就对了…$B$B或他找我…$B$B噢噢喔…或是他…', '怎么啦宝贝?有东西要给我?', '', '去找丹莫罗的贝尔比。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13933, '青铜巨龙圣地', '有时候，高阶神谕者索乌塞会讲一些关于一座巨龙祭坛的故事。那和雨水巨石可不一样。索乌塞告诉我们，也许我们能在那里看到我们自己，只不过不会像我们现在这样闪光光。索乌塞的意思是说，我们能在那里看到自己许多年以后的样子。$B$B你要带我们去那里？我们记得青铜巨龙圣地是在一个叫龙骨荒野的地方。索乌塞说，雨水巨石让他知道，那个圣地就在龙眠神殿的东北方，或者是暮冬要塞的西北方。我们现在出发吗？', '带上你的孤儿鲁鲁转至青铜巨龙圣地。如果当你到达那里的时候，他不在你身边，一定要召唤他过来。', '我们很开心你能带我们来这里，$N。我们一直很担心如果孤儿监护员发现我们在索拉查会怎么样。', '我们要去参观龙东西的祭坛吗?', '带着鲁鲁转至青铜巨龙圣地', '去找神谕者孤儿。如果你的孤儿不在附近那么请使用你的神谕者孤儿哨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13934, '青铜巨龙圣地', '当科科还是小孩子的时候，他经常会听长者们说起一个遥远的圣地。有时候，长者们会说，在青铜巨龙圣地能知道关于未来的一切事情。$B$B科科要告诉你，他要成为强大的战士。所以我们现在就要到那里去看看。青铜巨龙圣地就在龙骨荒野，在一个被称作龙眠神殿的东北方，一座被称为暮冬要塞的人类城镇的西北方。$B$B我们要到那里去，看看未来。我要让监护员知道，她是错的。科科是战士，不是傻瓜。', '带上你的孤儿科科转至青铜巨龙圣地。如果当你到达那里的时候，他不在你身边，一定要召唤他过来。', '我说得没错吧?“恰嘎告诉过你了。”这句话恰嘎永远说不烦。$B$B也许你会开始相信恰嘎说过的事，像是天空是多么的绿。', '恰嘎想去参观龙殿。', '带着科科转至青铜巨龙圣地', '去找狼獾人孤儿。如果你的孤儿不在附近那么请使用你的狼獾人孤儿哨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13937, '转至奇妙玩具店的旅行', '我们还有时间去下一站？我们听说达拉然有一间玩具店，但我们从来没有去过那里。监护员说，如果大家都要去那里的话，那里就会被挤爆了。也许我们可以去那里？只有我们？我们可以在那里得到一只规模纸飞艇吗？他们就会把那种小飞艇送到达拉然的奇妙玩具店去。我们一直都想要一只那样的小飞艇。也许你能给我们一只？', '在奇妙玩具店购买一只规模纸飞艇，然后把它掷给你的孤儿鲁鲁。', '真有趣!我们喜欢玩具屋。也许孤儿监护员改天能带我们去。我们会拜托她的。或许你也能跟她说一声?', '我们会去神奇玩具屋吗?', '', '去找神谕者孤儿。如果你的孤儿不在附近那么请使用你的神谕者孤儿哨。', '将小型纸飞艇掷给鲁鲁', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13938, '转至奇妙玩具店的旅行', '你还要带科科去另一个地方？监护员说达拉然有一个奇妙玩具店。但科科从没有去过那里。保姆说，如果有一个孤儿去了，她就必须带所有孤儿都去那里了。你能带科科去那里吗？$B$B科科看到过其它孩子玩折纸飞艇。科科听说那些飞艇都是从奇妙玩具店里飞出来的。也许你能在那里弄到一只折纸飞艇，然后和科科一起玩？', '在奇妙玩具店购买一只规模纸飞艇，再将小飞艇丢给你的孤儿科科。', '恰嘎喜欢玩纸飞艇。虽然没有像打猎一样好玩，但至少让我在孤儿院无聊时有事可做。', '到玩具店了吗?', '', '去找狼獾人孤儿。如果你的孤儿不在附近那么请使用你的狼獾人孤儿哨。', '将小型纸飞艇掷给科科', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13950, '伙伴！', '你要知道，孤儿们都是很孤独的。有时候，我们很想去别的地方看看，结交一些新的朋友。$B$B也许你能带我们去闯一闯？我们听说有一个叫冬鳞避难所的地方。那就在北风苔原里面。要去那里，我们应该向西北方前进，走到靠近考达拉岛边缘的地方。$B$B监护员说有一个勇敢的人也在那里养育着一群孤儿。他们一定也很孤单，一定也需要朋友。你愿意带我们去那里吗？', '带领你的孤儿鲁鲁前去拜访冬鳞避难所。当你到达那里的时候，如果他不在你身边，一定要召唤他过来。', '那真好玩!我们下次再来?我等不及要再次看到我们的新朋友了!', '你要带我们去冬鳍避居地?也许还能认识新朋友?', '带领鲁鲁参观冬鳞避难所。', '去找神谕者孤儿。如果你的孤儿不在附近那么请使用你的神谕者孤儿哨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13951, '伙伴！', '除了监护员照顾的小孩子，科科还想有别的朋友。也许我们能去一些别的地方？$B$B科科知道有一个部落居住在龙骨荒野。他们住的地方叫做飘雪林地。你知道吗？飘雪林地在莫亚基港口的北边和红玉巨龙圣地的南边。$B$B<提到海象人的时候，科科的脸上现出一副生气的表情。>$B$B你带科科去那里。去拜访那里的村子。也许我们能遇到新的狼獾人，让他们知道，狂心氏族有多厉害！', '带着你的孤儿科科转至飘雪林地。当你到达那里的时候，如果他不在你身边，一定要召唤他过来。', '恰嘎喜欢落雪林地的新朋友，或许下次有机会一起打猎。说不定我们能在海象人睡觉的时候把他们翻得肚子朝天。', '你现在能带恰嘎去落雪林地?', '带领科科参观飘雪林地。', '去找狼獾人孤儿。如果你的孤儿不在附近那么请使用你的狼獾人孤儿哨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13952, '死者的感激', '真高兴能再次见到朋友和亲人，不过也许我做得有些太夸张了……我已经吃光了他们为我准备的一切！$B$B能不能帮我一个忙，再给我拿来一些那种美味的悼念糕饼？我会非常感激你的……$B$B我想，那边的查普曼正在出售食谱。', '弄到悼念糕饼，并把它交给暴风城墓地的欢快的人类灵魂。$B$B你必须使用一朵橙菊，才能看到那个隐形的灵魂。', '喔，更多美味的亡者面包，感谢你!$B$B请收下这个当作回报…一点节日的小娱乐。', '你有亡者面包吗?', '', '去找艾尔文森林的欢快的人类灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13955, '红龙女王', '科科一直都很喜欢巨龙。科科一直都想有一条龙。但监护员不让科科这样做。不过她说了，你可以带科科去看看红龙女王。$B$B科科终于听监护员说了一句也有道理的话。你愿意带科科去龙骨荒野中心的龙眠神殿吗？我们一同飞到那座神庙顶上，去看看红龙女王。她一定非常非常巨大。这样她才能成为所有巨龙的女王。科科已经等不及想要见她了！', '带上你的孤儿科科去拜访阿莱克丝塔萨，生命的缚誓者，她就在龙眠神殿的顶端。如果当你到达那里的时候，他不在你身边，一定要召唤他过来。', '龙后长的跟恰嘎想的不一样，但恰嘎知道原因。如果她一直变成大龙，那会把访客压个稀巴烂!总有一天我要看看她的庐山真面目。', '我们要去看龙后了吗?', '带着科科去见阿莱克丝塔萨，生命的缚誓者', '去找狼獾人孤儿。如果你的孤儿不在附近那么请使用你的狼獾人孤儿哨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13956, '拜访一位造物主', '高阶神谕者索乌塞总是告诉我们，造物主如何建起圣地，而我们则让它们发光。但他从没有见过一位造物主。没有人见过造物主。不过，也许你能找到一位造物主？$B$B索乌塞告诉我们，造物主建造了一座界门，并把它安放在索拉查南部的正中心。索乌塞没有说它会通向哪里。但也许我们能借助它走到一位造物主的面前！带我们走进那道界门，让我们看看门的另一边到底有些什么吧，$N。', '带着你的孤儿鲁鲁转至塑造者之台的源生石像那里。当你到达那里的时候，如果他不在你身边，一定要召唤他过来。', '我们见到了一位伟大之神!可惜是在他的午睡时间，但我们了解。我们也喜欢打瞌睡!也许我们是跟诸神学到了如何打瞌睡，就像我们学到了圣坛及亮晶晶!$B$B我们可以在他醒来时再来拜访他吗?', '你知道如何找到一位伟大之神吗?我们以前从来没看过诸神。', '带鲁鲁去拜访源生石像', '去找神谕者孤儿。如果你的孤儿不在附近那么请使用你的神谕者孤儿哨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13959, '返回孤儿院', '我们和你一起渡过了一段最美好的时光$N。真希望你会是我们的$g爸爸:妈妈;。但你现在必须带我回达拉然的孤儿院里。$B$B也许你什么时候能再来看我们？我们喜欢去看冬鳞小鱼人和红龙女王。绝不会有人相信，我们竟然见到了造物主！$B$B我们会想念你的，$N。一定要给我们写信，我们也会给你写信的，好吗？', '将你的监护对象送回到达拉然孤儿院，把神谕者孤儿哨交给达拉然的孤儿监护员艾蕊娅。', '听起来小阿若过了一周的快乐时光。他在孤儿院时是极度的孤单并渴望交到一些新朋友。非常感谢你愿意看顾他。', '我们一定得回去吗?我们想要留在你身边。', '', '去找达拉然的孤儿监护员艾蕊娅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13960, '返回孤儿院', '你知道吗？你不是个坏人，$N。你带着科科去了许多有趣的地方。科科遇到了不少新朋友，还经历了一些其它孩子根本想象不到的事情。$B$B你与赫米特·奈辛瓦里和飘雪林地的小孩全都成了科科最好的朋友。也许你能把那本绿色山丘书带给科科？科科答应了要不时给你写一些东西，让你知道他的情况。也许，作为一个大舌头怪的孩子也是有些好处的。$B$B科科现在要回到孤儿监护员艾蕊娅那里去了，要回到紫色人的城市去了。', '将你的监护对象送回到达拉然孤儿院，把狼獾人孤儿哨交给达拉然的孤儿监护员艾蕊娅。', '感谢你这周愿意照顾恰嘎。我知道他很麻烦，但我认为多一点的个别照料及多一点朋友，他会改善很多。无疑的，他这几周内会一直念着那些和你一起经历的冒险故事。', '恰嘎不想走。恰嘎想和$N去看看更多诺森德的事物。', '', '去找达拉然的孤儿监护员艾蕊娅。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (13986, '受伤的同伴', '$c，相信你已经知道，这里的战斗相当艰苦。我们还能守住战线，但我们的战士已死伤惨重。$b$b我们的一个名叫奥伯妮·亮鬃的战士手臂上的伤口感染了。她被送回到雷霆崖进行急救。不过，她在混乱中把盾牌遗失在了这里。你能把这面盾牌连同我们的祝福一起给她带过去么？我们非常想念她的微笑。$b$b你可以在雷霆崖的长者高地那里找到她。', '将破旧的部族护盾交给奥伯妮·亮鬃。她就在雷霆崖里的长者高地。', '喔，我的盾!我想我暂时没办法用它了，但还是谢谢你。我讨厌只能没用的坐在这里而不能去前线出力，但我这条手臂就算上战场也帮不了任何人。$B$B请自己多保重。', '喔!你好。我想我应该没看过你;有什么可以为你效劳的吗?', '', '去找莫高雷的奥伯妮·亮鬃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14017, '黑骑士的命运', '那具尸体被异教徒们偷走了？他们只有可能把它运到一个地方－－亡语者岗哨，那就是他们在比武场西边山脊上的营地。$B$B无论异教徒们要做些什么，我们必须阻止他们的阴谋。看来，我听到的传闻是真的。那个臭名昭着的科勒博士一定也在那群异教徒中间施行他的邪术。你要找到一个能俯瞰那座异教徒营地的高地或祭坛，消灭那个家伙，寻找他的计划，并以你能做到的任何方法来阻止他的阴谋。', '在亡语者岗哨取得科勒博士的计划，然后返回银色比武场，去见北伐军战士莱达拉。', '医生不会有时间完成他的工作的，但他的计画已经开始执行。从你的报告中可以推知，巫妖王的仆人复生并活化了黑骑士，但我们还不知道骑士的主人是谁。感谢你发现了这个线索。我会告诉高阶十字军艾德拉你的发现并同时警告联赛的参与者。', '你知道他们对黑骑士的遗体做了什么了吗?', '', '去冰冠冰川找黑色观察站的北伐军战士欧尔拉金·萨利斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14023, '玉米馅料', '我们的玉米馅料是感恩节宴席的基石。这道菜肴一直都是暴风城的一道名菜。现在它更是在盛宴食谱中占据了举足轻重的位置。$B$B如果你已经是一名厨师，就去找感恩节商人，他会给你这道大餐的盛宴食谱，告诉你准备一份这样的假日大餐都需要哪些原料。如果你还不是一名厨师，那么现在就开始研习厨艺吧！$B$B做好玉米馅料之后，就把它交给那些桌子旁边的加斯帕·摩尔。', '制作5份玉米馅料，把它们交给加斯帕·摩尔，他就在暴风城大门外的宴会区。', '太好了。这正是我们需要的。在桌上堆满新鲜的食物已经变成了例行事项，不过还是值得这么做。', '我们需要更多美味的香料面包馅料。它们太受好评了。', '', '去艾尔文森林找闪金镇的加斯帕·摩尔。', '准备玉米馅料', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14024, '南瓜馅饼', '你做的玉米馅料闻起来真是香极了，但如果没有一块南瓜馅饼，那么感恩节就永远都不会完整。那是我们在暴风城最喜欢的另外一道菜。因为艾尔文南瓜只会生长在这里。$B$B如果你还不知道该如何制作南瓜馅饼，那么你现在就可以在你的盛宴食谱上找到这道菜的做法了。$B$B你是否愿意制作一些南瓜馅饼，并把它们交给铁炉堡外的爱德华·文斯洛？现在他的南瓜馅饼一定已经不够了。', '制作5份南瓜馅饼，将它们交给铁炉堡外宴会区的爱德华·文斯洛。', '南瓜派超受欢迎的。我从未见到矮人对蔬菜做的食物这么兴奋过。', '更多的南瓜派?来的正好。', '', '去丹莫罗找铁炉堡大门的爱德华·文斯洛。', '准备南瓜馅饼', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14028, '酸果蔓酱', '如果你还没有试过酸果蔓酱，那么你的人生肯定还不完整。它是用味道最清新的湿地酸果蔓制作的。如果你想要尝试自己制作酸果蔓酱，那就找感恩节商人吧。$B$B做这道菜的方法应该就在你的盛宴食谱中。$B$B如果你有空，能不能制作一些酸果蔓酱，并把它们送到暴风城外的加斯帕·摩尔那里去？我答应过他，会给他一些东西以作为你带过来的那些馅饼的交换。', '制作5份酸果蔓酱，并把它们送到暴风城外宴会区的加斯帕·摩尔那里去。', '说好要送来的蔓越莓酸甜酱终于到了。你不会相信这些庆祝者扫掉这些食物的速度有多快。', '我闻到了蔓越莓酸甜酱的味道罗?', '', '去艾尔文森林找闪金镇的加斯帕·摩尔。', '准备酸果蔓酱', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14030, '达纳苏斯的人都饿极了', '感谢你带来了酸果蔓酱。这里要做的烹调工作太多了，我几乎没有时间去想别的事情。而现在对我来说，最重要的一件事就是达纳苏斯的艾萨克·奥勒登几乎已经把一切物资都用光了。你愿意帮我们一个忙，给那里送去一些玉米馅料和南瓜馅饼吗？你可以那边的商人手中购得你所需要的一切原料。$B$B你可以在达纳苏斯入口附近的宴会区找到艾萨克·奥勒登。那里就在战士区的外面。', '将5份玉米馅料和5份南瓜馅饼送给达纳苏斯入口处附近的艾萨克·奥勒登。', '谢谢你带来的东西。这下子我可以安心了。$B$B既然你已经来了，那就试试你的手艺来做些糖煮甜薯吧。', '你是来参加旅人丰年祭餐会的吗?', '', '去达纳苏斯找战士区的艾萨克·奥勒登。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14033, '糖心甜土豆', '既然你在这里，也许你可以弄一些泰达希尔甜土豆来。它们可以被做成世界上最好吃的糖心甜土豆。$B$B如果你不相信我，就看看你的盛宴食谱，然后试着做出这道菜尝一尝吧。如果你能多做一些，你可以把它们交给暴风城外面宴会区的格雷戈里·塔波。糖心甜土豆是他最喜欢的菜品之一。不过，他好像没什么不喜欢的菜。', '制作5份糖心甜土豆，把它们交给暴风城外面宴会区的格雷戈里·塔波。', '啊，糖煮甜薯!我的最爱!是艾萨克.爱勒顿告诉你的吗?', '$N，很高兴再看到你。', '', '去艾尔文森林找闪金镇的格雷戈里·塔波。', '准备好糖心甜土豆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14035, '慢烤火鸡', '每一场感恩节盛宴都需要一个精彩的核心主题，我说的可不是丰收之角。盛宴的核心应该是令人垂涎欲滴的慢烤火鸡。$B$B你的盛宴食谱中已经有了这道菜的烹调配方，为什么不去猎捕一些野生火鸡，做出这道菜？艾尔文森林中到处都能找到火鸡，所以猎捕它们绝对不是困难的事。$B$B火鸡烤好之后，请把它们交给达纳苏斯大门旁边的艾萨克·奥勒登好吗？', '制作5份慢烤火鸡，将它们交给达纳苏斯大门旁边的艾萨克·奥勒登。', '这些火鸡烤的如此鲜美且刚好可以来喂饱这些饥饿的与会者。谢谢你，$N。你确实已精通于所有旅人丰年祭的传统佳肴了。', '什么风把你吹回达纳苏斯的，$N?', '', '去达纳苏斯找战士区的艾萨克·奥勒登。', '准备慢烤火鸡', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14037, '玉米馅料', '我们的玉米馅料是感恩节宴席的基石。这道菜肴的烹饪方法可以追溯到洛丹伦的美好时代。而现在，它已经在传统菜肴中占据了不可动摇的地位。$B$B如果你已经是一名厨师，就去找感恩节商人，他会给你这道大餐的盛宴食谱，告诉你准备一份这样的假日大餐都需要哪些原料。如果你还不是一名厨师，那么现在就开始研习厨艺吧！$B$B做好玉米馅料之后，就把它交给那些桌子旁边的威廉·穆林.', '制作5份玉米馅料，把它们交给威廉·穆林，他就在幽暗城上方庭院的宴会区里。', '把桌子堆的满满已经变成了例行事项。但如果你停下来并好好想想，为什么要费这么多劲来准备这么多我们吃不下的东西。$B$B<威廉叹了口气。>$B$B这就是传统。', '桌上需要更多美味的香料面包馅料。', '', '去提瑞斯法林地找洛丹伦废墟的威廉·穆林。', '准备玉米馅料', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14040, '南瓜馅饼', '你制作的玉米馅料已经成为了这次宴会的亮点。但如果没有南瓜馅饼，那任何感恩节都不会是完整的。就如同玉米馅料一样，南瓜馅饼也是我们的传统菜式之一。只有在我们这里才能收获到甘美的提瑞斯法南瓜。$B$B如果你还不知道该如何制作南瓜馅饼，那么你可以在你的盛宴食谱上找到制作它的配方。$B$B你愿意制作一些南瓜馅饼，并把它们带到奥格瑞玛外面的弗朗西斯·伊顿那里去吗？现在他急需更多的南瓜馅饼。', '制作5份南瓜馅饼，将它们交给奥格瑞玛外面宴会区的弗朗西斯·伊顿。', '南瓜派总是最快被吃完的。我想大家一定都跳过正餐而直接吃甜点。你尝过一片没?', '我们需要更多的南瓜派。', '', '去杜隆塔尔找野猪农场的弗朗西斯·伊顿。', '准备南瓜馅饼', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14041, '酸果蔓酱', '你试过酸果蔓酱吗？它是用最新鲜浓烈的南国之怒酸果蔓制作的。如果你想要亲手制作一些酸果蔓酱，那么你可以从感恩节商人的手中购买一些原料。$B$B而制作酸果蔓酱的配方已经记录在你的盛宴食谱里面了。$B$B如果你有空，能不能制作一些酸果蔓酱，并把它们送到雷霆崖西侧升降梯底层的多金·辽原那里去。', '制作5份酸果蔓酱，并把它们交给雷霆崖西侧升降梯底层的多金·辽原。', '啊，更多的蔓越莓酸甜酱!你不会相信这些庆祝者扫掉这些食物的速度有多快。', '旅人丰年祭好玩吗，$C?', '', '去找雷霆崖的多金·辽原。', '准备酸果蔓酱', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14043, '糖心甜土豆', '既然你在这里，也许你可以弄一些泰达希尔甜土豆来。它们可以被做成世界上最好吃的糖心甜土豆。那也是我在感恩节上非常喜爱的一道菜。$B$B如果你不相信我，就看看你的盛宴食谱，然后试着做出这道菜尝一尝吧。如果你要去奥格瑞玛，请将一些糖心甜土豆交给城外宴会区的弗朗西斯·伊顿。我一直在努力维持对那里的食品供应，但所有食品的消耗速度都太快了。', '制作5份糖心甜土豆，并将它们交给奥格瑞玛外面的弗朗西斯·伊顿。', '是杜金派你送糖煮甜薯来支持的?$B$B<法兰西斯微笑。>$B$B这也是他唯一能做的。谢谢你送这些来。', '欢迎回来，$N。', '', '去杜隆塔尔找野猪农场的弗朗西斯·伊顿。', '准备好糖心甜土豆', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14044, '幽暗城急需美食', '感谢你带来的糖心甜土豆。我要做的烹饪工作实在是太繁重了，让我几乎不能应付。现在，米尔斯又送信给我们说，他的玉米馅料和酸果蔓酱都差不多快用光了。你能为他提供一些这两种食物吗？这里的商人应该有你所需要的一切原料。$B$B你应该能在幽暗城上方废墟庭院的宴会区里找到米尔斯·斯坦迪什。', '将5份玉米馅料和5份酸果蔓酱交给幽暗城入口附近的米尔斯·斯坦迪什。', '谢谢你带来的东西。有些桌子上的盘子已经开始空了起来。', '很高兴再看到你。$N。', '', '去提瑞斯法林地找洛丹伦废墟的米尔斯·斯坦迪什。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14047, '慢烤火鸡', '每一场感恩节盛宴都需要一个精彩的核心主题。对于我们而言，这个主题就是慢火烤野生火鸡。我相信，没有任何菜肴能比它更适合成为一场宴会的主菜。$B$B你的盛宴食谱里已经有了制作这道菜的方法。为什么不去猎捕一些野生火鸡，把这道菜做出来？提瑞斯法林地到处都有野生火鸡，要找到它们绝对不是难事。$B$B把火鸡烤好之后，就请将它们交给奥格瑞玛城外的弗朗西斯·伊顿。', '制作5份慢烤火鸡，并将它们交给奥格瑞玛大门附近的弗朗西斯·伊顿。', '这些火鸡看起来真是棒。谢谢你，$N。你确实已精通于所有旅人丰年祭的传统佳肴了。', '什么风把你吹回奥格瑞玛的，$N?', '', '去杜隆塔尔找野猪农场的弗朗西斯·伊顿。', '准备慢烤火鸡', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14048, '火鸡还是缺', '从这次节日一开始，我就在毫不停歇地烹调菜肴。但我提供的食品还是不能满足大家的需要。你愿意帮我一把么？$B$B这里的火鸡供应量远远不够。所以，如果你能做一些慢烤火鸡，那你可是帮了我一个大忙。如果你愿意的话，你可以在艾尔文森林各地猎捕野生火鸡。同时感恩节商人会向你出售烹调这道菜所需要的一切材料。', '将20份慢烤火鸡交给铁炉堡外面的凯特琳·铁壶。', '这些就是我要的。谢谢，$N。你真是我的救星。', '你有设法去弄到那些火鸡吗?', '', '去找丹莫罗铁炉堡大门附近的凯特琳·铁壶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14051, '别忘了那馅料！', '在这些宴席桌上摆满美食实在是一个能累死人的工作！我在制作酸果蔓酱的时候还在盯着那些甜味土豆，又要保证那些馅饼不被烤糊。$B$B看样子，我已经把所有东西都准备好了。不，等等，我还忘了一样东西。玉米馅料！哦，不。我已经没有时间再去准备玉米馅料了。你愿意帮我一个忙吗？这并不难，你只需要在这里购买一些原料，就能制作出香喷喷的玉米馅料了。', '将20份玉米馅料交给凯特琳·铁壶。 他就在铁炉堡宴会区外面。', '感谢老天!没有香料面包馅料的话我根本不能款待餐会来宾。', '你能取得那些馅料吗?', '', '去找丹莫罗铁炉堡大门附近的找凯特琳·铁壶。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14053, '酸果蔓酱又吃完了？', '我的丈夫加斯帕需要更多的酸果蔓酱。而他现在还要保证宴会上能有足够的糖心甜土豆。你愿意帮我们一下么？如果你是一名厨师，你可以从铁炉堡城外的感恩节商人那里买到味道浓烈的湿地酸果蔓。$B$B如果你不想自己做菜，你也能请别人为你制作酸果蔓酱。', '将20份酸果蔓酱交给暴风城外宴会区的艾伦·摩尔。', '谢啦。这看起来很棒，而且你的动作比贾斯伯还要快上一些，不过别告诉他我这么说。', '你能取得蔓越莓酸甜酱吗?', '', '去艾尔文森林找闪金镇的艾伦·摩尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14054, '小菜一碟', '艾萨克一直在努力帮助庆祝节日的人们了解感恩节的传统，以及如何将我们在一年中这个时候收获的各种食才制作成美味佳肴。我竭尽全力让宴会桌上时刻摆满各种菜肴，但我们现在却少了一种艾萨克最喜欢的美食——南瓜馅饼。$B$B你愿意给我们弄一些南瓜馅饼来吗？如果你想亲手制作这种馅饼，那么你就需要在暴风城外面的感恩节商人那里购买成熟的艾尔文南瓜。', '将20份南瓜馅饼交给达纳苏斯大门附近宴会区的玛丽·奥勒登。', '这些真是太完美了。艾萨克和其它人都会爱上它们的!', '那些派进展如何?', '', '去达纳苏斯找战士区的玛丽·奥勒登。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14055, '她喜欢土豆', '我的妻子艾伦求我帮她为宴会准备餐点。但她一直都没有个准主意。一开始，她要我做南瓜馅饼，现在她又改变了主意，想要糖心甜土豆了。$B$B但我正在做南瓜馅饼。所以你也许能帮我弄一些甜土豆来。如果我们能把我妻子的需求全部满足，她一定会非常高兴的。$B$B如果你要自己烹制糖心甜土豆，你就要从达纳苏斯的感恩节商人那里购买你所需要的土豆。', '将20份糖心甜土豆交给暴风城外面宴会区的加斯帕·摩尔。', '这些真是太完美了。感谢你的帮忙，$N。看来这些菜肴都可以准时上桌，爱莲一定会很高兴的。', '你有糖煮甜薯吗?', '', '去艾尔文森林找闪金镇的加斯帕·摩尔。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14058, '她喜欢土豆', '罗贝塔·卡特请我为节日大餐准备糖心甜土豆。我很想帮她，但现在我又答应了宴会服务员，要帮她为客人们上菜。$B$B如果你能帮助我准备糖心甜土豆，那我一定会非常感激你的。因为如果我让她失望，她绝对不会饶了我。$B$B如果你要烹调糖心甜土豆，你就要从雷霆崖的感恩节商人那里购买原料。非常感谢你，$N。', '将20份糖心甜土豆交给幽暗城上方宴会区里的威廉·穆林。', '谢了，$N。现在，我能去帮忙女侍并信守对萝贝塔的承诺了。', '你有糖煮甜薯吗?', '', '去提瑞斯法林地找洛丹伦废墟的威廉·穆林。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14059, '酸果蔓酱又吃完了？', '真不明白，我们的酸果蔓酱怎么会消耗得那么快。有时候，我甚至怀疑他们背着我把酸果蔓酱都喂给憎恶了。你能帮我再做一些酸果蔓酱吗？如果你是一名厨师，你就能在奥格瑞玛城外的感恩节商人那里购买到你所需要的南国之怒酸果蔓。$B$B如果你不想做烹饪的工作，你也可以请求别人制作这种酸果蔓酱。', '将20份酸果蔓酱交给幽暗城庭院上方宴会区的罗贝塔·卡特。', '感谢你的帮忙，如果你弄清楚消失的酸甜酱事件的真相，请务必让我知道。', '你能取得蔓越莓酸甜酱吗?', '', '去提瑞斯法林地找洛丹伦废墟的罗贝塔·卡特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14060, '小菜一碟', '多金和拉哈一直在为感恩节而努力工作，我们要在这个节日里将我们在今年收获的所有食材都做成美味的大餐。我正在努力在所有餐桌上都摆满美食，但现在我们却没有足够的南瓜馅饼。$B$B你能为我们提供一些南瓜馅饼吗？如果你想自己做这种馅饼，你就需要从幽暗城外的感恩节商人那里购买提瑞斯法南瓜。', '将20份南瓜馅饼交给雷霆崖外宴会区的玛哈拉·金穗。', '这些真是太棒了!感谢你的帮忙，$N。', '那些派进展如何?', '', '去找莫高雷的玛哈拉·金穗。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14061, '火鸡还是缺', '从这次节日一开始，我就在毫不停歇地烹调菜肴。但我提供的食品还是不能满足大家的需要。你愿意帮我一把么？$B$B这里的火鸡供应量远远不够。所以，如果你能做一些慢烤火鸡，我会非常非常感激你的。如果你愿意的话，你可以在提瑞斯法林地各地猎捕野生火鸡。同时感恩节商人会向你出售烹调这道菜所需要的一切材料。', '将20份慢烤火鸡交给奥格瑞玛外面的昂丹尼。', '这些火鸡就是我要的。感谢你在我忙不过来的时候帮我一把。', '你火鸡猎得怎样?', '', '去杜隆塔尔找野猪农场的昂丹尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14062, '别忘了那馅料！', '在这些宴席桌上摆满美食实在是一个能累死人的工作！我在制作酸果蔓酱的时候还在盯着那些甜味土豆，又要保证那些馅饼不被烤糊。$B$B看样子，我已经把所有东西都准备好了。不，等等，我还忘了一样东西。玉米馅料！哦，不。我已经没有时间再去准备玉米馅料了。你愿意帮我一个忙吗？这并不难，你只需要在这里购买一些原料，就能制作出香喷喷的玉米馅料了。', '将20份玉米馅料交给奥格瑞玛外面的昂丹尼。', '来得正好!没有香料面包馅料的话我根本不能款待餐会来宾。', '你能取得那些馅料吗?', '', '去杜隆塔尔找野猪农场的昂丹尼。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14074, '一腿之力', '银色北伐军派遣了一艘装满美味肉食和其它给养品的快船前来比武场援助我们，但那艘船永远也不能到达了。我们的巡逻兵说曾发现那艘船遭到了克瓦迪尔的攻击。那些恐怖的维库人强盗已经在海上犯下了无数罪行。$B$B他们杀死了那艘船的船员，将船上的货物抢到了一座被称为洛斯加尔登陆点的岛上。如果你向北方眺望，你就能看到那座岛屿被笼罩在迷雾中的影子。你愿意帮助我们夺回那些被抢走的物资吗？如果没有那些陆行鸟腿作为我们的食物补充，我们很快就会饿肚子了。', '夺回10条被偷走的陆行鸟腿，交给银色比武场的纳莱丝·晨雪。', '这些腿看来有点损伤，但还可以吃。十字军知道我们取回了些船上的货物一定会很高兴的。', '你能取回失窃的补给品吗?', '', '去找冰冠冰川的纳莱丝·晨雪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14076, '勇士的早餐', '现在，演武场已经完成，银色北伐军请求我们帮忙照看那些将要和勇士们作战的怪兽。$B$B这其中，巨大冰虫的饲料也许是最奇怪的。如果喂它们吃同类的卵，他们就会变得更强大，而最优质的卵来自于深土冰虫。$B$B带上这只鼓，到风暴峭壁中心处的山底平原去，在那里的雪堆附近把鼓敲响，唤醒深土冰虫，然后消灭它们，并收集它们的卵鞘。', '取得4只冰虫的卵鞘，将它们交给银色比武场的萨雯妮娅·慧歌。', '做得好，$N。我现在就把这些卵囊拿去给银色北伐军。他们不得不承认在让大竞技场顺利运作这方面我们做得比夺日者好。', '你取回那些虫卵了吗?如果不再快点喂食，它们就会开始吃训练员了。', '', '去找冰冠冰川的萨雯妮娅·慧歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14077, '圣光的仁慈', '我听神官帕尔崔丝讲过了。我要告诉你，她的话让我深思良久。与十字军并肩战斗是不够的，我们必须担负起他们的任务。$B$B在北方海岸的洛斯加尔登陆点发生了一桩血案。克瓦迪尔海盗们攻入一处古老的海象人居民区，将那里的村民屠杀殆尽。带上这本书，在那些村民的尸体旁边诵读书中的悼文。这样能让他们的灵魂离开那座被迷雾环绕的岛屿，得到最后的安息。', '使用神官的祈祷书，为8位被屠戮的图亚里克村民举行追悼仪式，然后返回银色比武场，去见纳莱丝·晨雪。', '<娜拉希从你那接过祈祷书。>\r\n\r\n谢谢你。这本书是告解者帕尔璀丝的礼物。她会很荣幸的知道你用这本书让死者获得安息', '你安抚了被杀的托利克村民的灵魂了吗?', '', '去找冰冠冰川的纳莱丝·晨雪。', '为死者举行悼念仪式', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14079, '驰骋在艾尔文森林', '这本关于骑乘训练和坐骑购买的广告小册子是由兰达尔·亨特派发出来的。$B$B你可以在艾尔文森林的东谷伐木场找到他，那里就在暴风城向东大道的路旁。', '将这本小册子交还给艾尔文森林东谷伐木场的兰达尔·亨特。', '我们可以开始你的初级骑术训练了吗?', '啊，你收到了我的信?很好。', '', '去艾尔文森林找石碑湖的兰达尔·亨特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14080, '抗击侵略者', '那些恐怖的维库人强盗克瓦迪尔袭击我们的运输队，又对一座北方岛屿上的海象人居民进行了屠杀，并把那座岛重新命名为洛斯加尔登陆点。如果让他们在那里站稳脚跟，我们无疑会成为他们的下一个目标。$B$B北伐军为了抵抗天灾军团已经倾尽全力。而我们必须守住比武场。一直向北飞行，到达那座岛屿，消灭那里的克瓦迪尔，不要让他们将那里的一切尽数毁灭。', '银色比武场的纳莱丝·晨雪想让你消灭10名克瓦迪尔。', '当夺日者还在忙于磨亮他们的宝剑时，你的行动展现了我们是银色北伐军的最佳伙伴。', '你向科瓦迪尔展现绝不受他们威胁的决心了吗?', '', '去找冰冠冰川的纳莱丝·晨雪。', '消灭克瓦迪尔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14081, '驰骋在永歌森林', '这本关于骑乘训练和坐骑购买的广告小册子是由佩拉斯卡米派发出来的。$B$B你可以在苏伦的养殖场找到佩拉斯卡米。那里就在银月城的牧羊人之门东南方向。', '将这本小册子交还给银月城苏伦的养殖场的佩拉斯卡米。', '我们可以开始你的初级骑术训练了吗?', '啊，你收到了我的信?很好。', '', '去找永歌森林的佩拉斯卡米。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14082, '驰骋在埃索达', '这本关于骑乘训练和坐骑购买的广告小册子是由埃亚伦派发出来的。$B$B你可以在秘蓝岛转至埃索达的入口处找到埃亚伦。', '将这本小册子交给秘蓝岛上的埃亚伦。', '我们可以开始你的初级骑术训练了吗?', '啊，你收到了我的信?很好。', '', '去找秘蓝岛的埃亚伦。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14083, '驰骋在丹莫罗', '这本关于骑乘训练和坐骑购买的广告小册子是由奥萨姆·铁角派发出来的。$B$B你可以在丹莫罗的冻石农场找到奥萨姆。那里就在铁炉堡向东的大道旁边。', '将这本小册子交给丹莫罗冻石农场的奥萨姆·铁角。', '我们可以开始你的初级骑术训练了吗?', '啊，你收到了我的信?很好。', '', '去丹莫罗找冻石农场的奥萨姆·铁角。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14084, '驰骋在丹莫罗', '这本关于骑乘训练和坐骑购买的广告小册子是由宾吉·羽哨派发出来的。$B$B你可以在钢架补给站找到宾吉，那里就在丹莫罗的卡拉诺斯东北方。', '将这本小册子交给丹莫罗钢架补给站的宾吉·羽哨。', '我们可以开始你的初级骑术训练了吗?', '啊，你收到了我的信?很好。', '', '去丹莫罗找钢架补给站的宾吉·羽哨。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14085, '驰骋在达纳苏斯', '这本关于骑乘训练和坐骑购买的广告小册子是由贾萨姆派发出来的。$B$B你可以在达纳苏斯的塞纳里奥区找到贾萨姆。', '将这本小册子交给达纳苏斯塞纳里奥区的贾萨姆。', '我们可以开始你的初级骑术训练了吗?', '啊，你收到了我的信?很好。', '', '去达纳苏斯找贸易区的贾萨姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14086, '驰骋在奥格瑞玛', '这本关于骑乘训练和坐骑购买的广告小册子是由基尔达派发出来的。$B$B你可以在奥格瑞玛的荣誉谷找到基尔达。', '将这本小册子交给奥格瑞玛荣耀谷的基尔达。', '我们可以开始你的初级骑术训练了吗?', '啊，你收到了我的信?很好。', '', '去找艾萨拉的基尔达。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14087, '驰骋在莫高雷', '这本关于骑乘训练和坐骑购买的广告小册子是由卡尔·雷歌派发出来的。$B$B你可以在莫高雷的血蹄村找到卡尔·雷歌。', '将这本小册子交给莫高雷血蹄村的卡尔·雷歌。', '我们可以开始你的初级骑术训练了吗?', '啊，你收到了我的信?很好。', '', '去莫高雷找血蹄村的卡尔·雷歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14088, '驰骋在杜隆塔尔', '这本关于骑乘训练和坐骑购买的广告小册子是由克萨尔迪派发出来的。$B$B你可以在南杜隆塔尔的森金村找到克萨尔迪。', '将这本小册子交还给杜隆塔尔南面森金村的克萨尔迪。', '我们可以开始你的初级骑术训练了吗?', '啊，你收到了我的信?很好。', '', '去杜隆塔尔\r\n找暗矛海滩的克萨尔迪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14089, '驰骋在提瑞斯法林地', '这本关于骑乘训练和坐骑购买的广告小册子是由维尔玛·瓦纳姆派发出来的。$B$B你可以在提瑞斯法林地的布瑞尔找到他。', '将这本小册子交给提瑞斯法林地布瑞尔的维尔玛。', '我们可以开始你的初级骑术训练了吗?', '啊，你收到了我的信?很好。', '', '去提瑞斯法林地找布瑞尔的维尔玛·瓦纳姆。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14090, '戈莫克想要他的狗头人', '我的两名部下在抓捕猛犸人穿刺者戈莫克的行动中丧生了。而那头怪物还在四处横行。他连续几个小时高声嗥叫，只是因为它找不到他喜欢的那个狗头人。$B$B如果银色北伐军不想在演武场中使用这头怪物，我会亲手把它杀了。不过，现在我们也许应该先给它找些玩具。拿上这张网，到风暴峭壁东南方的加姆雷区去。那里就在K3的东北方。在那里抓住一些狗头人。圣光保佑，但愿你能找到那头怪物喜欢的狗头人。', '使用强化渔网抓住8个雪盲追随者，并把它们交给银色比武场的萨雯妮娅·慧歌。', '快把这些臭东西从我的眼前拿走并丢进笼子里，省得我心烦。我希望银色北伐军把照顾这些生物的差事丢给夺日者。他们长得太像了，应当能轻易的了解彼此。', '你捕捉到那些极地狗头人了吗?戈莫克的怒气丝毫未减', '', '去找冰冠冰川的萨雯妮娅·慧歌。', '', '捕捉雪盲追随者', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14092, '勇士的早餐', '现在，演武场已经完成，银色北伐军请求我们帮忙照看那些将要和勇士们作战的怪兽。$B$B这其中，巨大冰虫的饲料也许是最奇怪的。如果喂它们吃同族的卵，他们就会变得更强大，而最优质的卵来自于深土冰虫。$B$B带上这只鼓，到风暴峭壁中心处的山底平原去，在那里的雪堆附近把鼓敲响，鼓声会唤醒深土冰虫。消灭它们，并收集它们的卵鞘。然后再回到比武场来。', '取得4只冰虫的卵鞘，将它们交给银色比武场的泰罗斯·晨行者。', '我会让十字军知道当银色盟约还在枯坐时，你已经带回了一批新鲜的食物了。', '你取回那些虫卵了吗?没有喂食的蛰猛巨虫会变得很暴躁。', '', '去冰冠冰川找银色比武场的泰罗斯·晨行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14100, '大地之环的遗迹', '$N，你已经掌握了许多技能，能够自如地控制四大元素了。而你要努力去做的就是维持四大元素的平衡。只要经过不懈的联系，你就能只携带一枚圣物，而不必再携带全部四件图腾了。$B$B同奥格瑞玛智慧谷的戈图拉·林风谈谈，在那里继续磨砺你控制元素的技艺吧。', '将你的四大元素图腾交给奥格瑞玛的戈图拉·林风。', '啊，你已经专精于四种图腾了。你该为你优异的成功感到骄傲，年轻的$r，但这只是你旅程的开始。$B$B拿着，收下这个大地之环的礼物。带着这个圣物你就能拥有命令四种元素的能力。$B$B继续你的训练，朋友。我能在风中听到也能在大地的隆隆声中感觉到 - 这个世界的前方有重大的挑战。我们必须为最糟的情况做准备。', '嗯，是什么事让你向大地之环寻求协助?', '', '去找奥格瑞玛的戈图拉·林风。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14107, '阵亡者的命运', '银色北伐军正在冰冠冰川艰苦地与巫妖王作战。我们的敌人却图谋利用死者的力量攻击我们。$B$B那些灵魂在比武场西南方，奥尔杜萨和铁墙壁垒之间的陨落英雄之谷游荡。那里散布着被丢弃的灵魂水晶。收集那些灵魂水晶，用这件受到圣光祝福的圣物给予那些灵魂最终的安息。他们不应该再遭受折磨了。', '北伐军战士希瓦多恩希望你让6位死去英雄的灵魂得到安息。', '你帮了我们逝往的同志一个大忙并省去了我们还要在战场上再度面对他们的麻烦。随着我们对抗天灾军团战役的进展，我会想到自己的命运。$B$B如果我阵亡了，$N，我希望能有人能拉我一把，就像你今日对这些亡魂所做的一样。我不能去想象强迫我的弟兄一次又一次的杀死我是件多痛苦的事。', '你让那些阵亡英雄之灵获得安息了吗?', '', '去冰冠冰川找银色比武场的北伐军战士希瓦多恩。', '让死去英雄的灵魂得到祝福。', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14108, '猎捕海怪！', '夺日者和银色盟约向北方派遣了战船，去进攻洛斯加尔登陆点的克瓦迪尔人。但他们的战船在半路上遭遇了一群克瓦迪尔海盗。而更加糟糕的是，这群克瓦迪尔人竟然能召唤深藏在北海深处的海怪。你必须将那头海怪击退，并破坏克瓦迪尔人的召唤仪式，才有可能救下那些遇险的船员。$B$B北伐军战士，拿上这些利矛。会有一只银色角鹰兽带你到那里去。', '北伐军战士希瓦多恩想让你骑乘一头银色角鹰兽，向北海海怪投射6根烈焰长矛，并除掉3个克瓦迪尔深渊呼唤者。$B$B你可以在比武场的银色北伐军大帐外找到那头银色角鹰兽。', '十字军，你替那些水手争取到了逃生的时间。也许下次银色盟约和夺日者在冲向敌人前会先听从命令。', '你驱退海怪没?快点，十字军!我们没有多少时间。', '', '去冰冠冰川找银色比武场的北伐军战士希瓦多恩。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14111, '大地之环的遗迹', '$N，你已经掌握了许多技能，能够自如地控制四大元素了。而你要努力去做的就是维持四大元素的平衡。只要经过不懈的练习，你就能只携带一枚圣物，而不必再携带全部四件图腾了。$B$B同铁炉堡大熔炉附近的先知安努谈谈，在那里继续磨砺你控制元素的技艺吧。', '带着你的四件图腾去见铁炉堡的先知安努。', '我发现你已经专精于四种图腾了。你以自己的方法成为了元素之灵的朋友，但这只是你旅程的开始。$B$B拿着，收下这个大地之环的礼物。带着这个圣物你就能拥有命令四种元素的能力。$B$B你的训练必须继续!我感觉到这个世界未来仍会遭遇许多难关，若要克服它们，需要元素的力量作为我们的后盾。', '元素之灵在你的体内翻腾。是什么事让你向大地之环寻求协助?', '', '去铁炉堡找先知安努。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14112, '你们到底喂雪人吃什么？', '北伐军抓住了一头雪人，他们称那头雪人为冰吼。那头雪人将参与演武场的战斗。而我们的任务就是训练并喂养他。$B$B我推荐十字军应该把一些过剩的夺日者喂给雪人吃，但北伐军对此丝毫不感兴趣。这头怪兽喜欢鲨鱼肉。所以我希望你能够飞行到银锋号。它就漂浮在北方的那道海峡里。从那艘船上的桶中取得一些新鲜的鱼饵，然后把鱼饵撒进海中，把鲨鱼引出来。', '银色比武场的萨雯妮娅·慧歌想让你带给她3块北海鲨鱼肉。', '我很高兴我们终于解决了这件事。这不是这世界上最光荣的事，但在我们成为银色北伐军的伙伴时，我们承诺绝不抱怨的完成他们的要求。当然，相同的承诺不可能由夺日者的口中说出。', '我希望你有东西能喂冰嚎，要不然我真的得去带几个夺日者去他的牢笼。', '', '去冰冠冰川找银色比武场的萨雯妮娅·慧歌。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14136, '海上救援', '克瓦迪尔人在北方小岛洛斯加尔登陆点创建了营地。我们派遣了船长埃尔萨斯·炎鹰转至那一地区。但他的船却遇到了一群正在向比武场进军的克瓦迪尔海盗！现在炎鹰号正遭受到远多于他数倍的敌人进攻。赶快到那里去，让克瓦迪尔人知道，攻击夺日者是多么愚蠢的行为。$B$B炎鹰号就在破海者航道的西侧，也就是北方的洛斯加尔登陆点和比武场之间。', '银色比武场的身经百战的吉莱娜要你在炎鹰号上消灭8名克瓦迪尔狂暴者和3名克瓦迪尔持戟者。', '做得好，勇士。战斗仍未结束，但现在科瓦迪尔学到了我们绝不宽恕这种袭击。', '你成功守住火鹰号了吗?', '', '去冰冠冰川找银色比武场的身经百战的吉莱娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14140, '抗击侵略者', '那些恐怖的维库人强盗克瓦迪尔袭击我们的运输队，又对一座北方岛屿上的海象人居民进行了屠杀，并把那座岛重新命名为洛斯加尔登陆点。如果让他们在那里站稳脚跟，我们无疑会成为他们的下一个目标。$B$B北伐军为了抵抗天灾军团已经倾尽全力。而我们必须守住比武场。一直向北飞行，到达那座岛屿，消灭那里的克瓦迪尔，不要让他们将那里的一切尽数毁灭。', '银色比武场的身经百战的吉莱娜想让你消灭10名克瓦迪尔。', '你的行动展现了我们夺日者对银色北伐军而言是远比银色盟约还要好的同盟，而那是我们的荣幸。', '你向科瓦迪尔展现绝不让他们威胁到我们的决心了吗?', '', '去冰冠冰川找银色比武场的身经百战的吉莱娜。', '消灭克瓦迪尔', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14141, '戈莫克想要他的狗头人', '我的两名部下在抓捕猛犸人穿刺者戈莫克的行动中丧生了。而那头怪物还在四处横行。他连续几个小时高声嗥叫，只是因为它找不到他喜欢的那个狗头人。$B$B如果银色北伐军不想在演武场中使用这头怪物，我会亲手把它杀了。不过，现在我们也许应该先给它找些玩具。拿上这张网，到风暴峭壁东南方的加姆雷区去。那里就在K3的东北方。在那里抓住一些狗头人。圣光保佑，但愿你能找到那头怪物喜欢的狗头人。', '使用强化渔网抓住8个雪盲追随者，并把它们交给银色比武场的泰罗斯·晨行者。', '快把这些臭东西从我的眼前拿走并丢进笼子里，省得我心烦。我希望银色北伐军把照顾这些生物的差事丢给银色盟约。当冰冠堡垒的战斗开始后他们将会证明自己只是个外强中干的装饰品而只配做这种下贱的小事。', '你捕捉到那些极地狗头人了吗?戈莫克的怒气丝毫未减。', '', '去冰冠冰川找银色比武场的泰罗斯·晨行者。', '', '捕捉雪盲追随者', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14143, '一腿之力', '银色北伐军派遣了一艘装满美味肉食和其它给养品的快船前来比武场援助我们，但那艘船永远也不能到达了。我们的巡逻兵说曾发现那艘船遭到了克瓦迪尔的攻击。那些恐怖的维库人强盗已经在海上犯下了无数罪行。$B$B他们杀死了那艘船的船员，将船上的货物抢到了一座被称为洛斯加尔登陆点的岛上。如果你向北方眺望，你就能看到那座岛屿被笼罩在迷雾中的影子。你愿意帮助我们夺回那些被抢走的物资吗？如果没有那些陆行鸟腿作为我们的食物补充，我们很快就会饿肚子了。', '夺回10条被偷走的陆行鸟腿，交给银色比武场的身经百战的吉莱娜。', '这些腿看来有点损伤，但还可以吃。十字军知道我们成功取回部份货物一定会很高兴的。也许我们可以把这些已经吃一半的食物拿给银色盟约。那会让我心情愉快一整天。', '你能取回失窃的补给品吗。', '', '去冰冠冰川找银色比武场的身经百战的吉莱娜。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14144, '圣光的仁慈', '我听神官帕尔崔丝讲过了。我要告诉你，她的话让我深思良久。与十字军并肩战斗是不够的，我们必须担负起他们的任务。$B$B在北方海岸的洛斯加尔登陆点发生了一桩血案。克瓦迪尔海盗们攻入一处古老的海象人居民区，将那里的村民屠杀殆尽。带上这本书，在那些村民的尸体旁边诵读书中的悼文。这样能让他们的灵魂离开那座被迷雾环绕的岛屿，得到最后的安息。', '使用神官的祈祷书，为8位被屠戮的图亚里克村民举行追悼仪式，然后返回银色比武场，去见身经百战的吉莱娜。', '<吉拉纳从你那接过祈祷书。>$B$B谢谢你。我们并不是每件事都与十字军取得共识，但这些日子我向告解者帕尔璀丝学了很多。', '你安抚了被杀的托利克村民的灵魂了吗?', '', '去冰冠冰川找银色比武场的身经百战的吉莱娜。', '为死者举行悼念仪式', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14145, '你们到底喂雪人吃什么？', '北伐军抓住了一头雪人，他们称那头雪人为冰吼。那头雪人将参与演武场的战斗。而我们的任务就是训练并喂养他。$B$B我推荐十字军应该把一些银色盟约的成员喂给雪人吃，但北伐军对此丝毫不感兴趣。这头怪兽喜欢鲨鱼肉。所以我希望你能够飞行到血色黎明号。它就漂浮在北方的那道海峡里。从那艘船上的桶中取得一些新鲜的鱼饵，然后把鱼饵撒进海中，把鲨鱼引出来。', '银色比武场的泰罗斯·晨行者想让你带给她3块北海鲨鱼肉。', '我很高兴我们终于解决了这件事。这不是这世界上最光荣的事，但在我们成为银色北伐军的伙伴时，我们承诺绝不抱怨的完成他们的要求。当然，相同的承诺不可能由银色盟约的口中说出。', '我希望你有东西能喂冰嚎，要不然我真的得去带几个银色盟约成员去他的牢笼。', '', '去冰冠冰川找银色比武场的泰罗斯·晨行者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14152, '海上救援', '勇士，船长伊尔琳·浪巅和她的船被派往北方，去阻击洛斯加尔登陆点的克瓦迪尔人。但他们在半路上遭遇了一群正在向比武场进军的克瓦迪尔海盗。不幸的是，克瓦迪尔强盗的数量远远超过了浪巅号上的水手们。他的船就要落入克瓦迪尔人的手中了。$B$B我们需要你转至北方，在破海者航道找到浪巅号。破海者航道就在比武场和洛斯加尔登陆点之间。你应该能在海岸东侧看到那艘船。请一定帮助伊尔琳船长击退敌人的攻击。', '转至北海，消灭攻击浪巅号的8个克瓦迪尔狂暴者和3个克瓦迪尔持戟者。', '看来事情比我们一开始想象的还糟。但你仍旧做出了英勇的贡献并拯救了许多浪峰号船员的生命。', '你协助击退科瓦迪尔人的攻击了吗?', '', '去找冰冠冰川的纳莱丝·晨雪。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14160, '功勋状', '这张精致的羊皮纸上列出了$N在珠宝行业里取得的诸多成就。$b$b你要将这份文件交给达拉然的提莫斯·琼斯，他一定会给你一份不错的酬劳。', '将功勋状交给达拉然的提莫斯·琼斯。', '这份功绩列表很棒，$N!你的成就将可换得可观的奖赏。', '你好，$N。你来这有什么事吗?', '', '去达拉然找卡蒂亚珠宝店的提莫斯·琼斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14163, '战斗的召唤：征服之岛', '当我们在冰冠冰川距离胜利越来越近的时候，部落的军队却给我们制造了越来越多的麻烦，让我们的战士在同巫妖王作战的同时不得不抽出力量来对付他们。$B$B现在，部落派遣了他们的精英卫士库卡隆来阻挡我们对征服之岛的进军。那座岛是一个非常重要的战略要地。$N，你的任务就是为联盟在那里取下胜利的果实！', '在征服之岛战场中获得一场胜利，然后向任意联盟主城、冬拥湖、达拉然或沙塔斯城中的联盟准将复命。', '只要有像你们这样人的协助，部落永远也不可能是我们部队的对手，$N。', '看到你真好，$N!你有从前线带来什么消息吗?', '征服之岛的胜利', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14164, '战斗的召唤：征服之岛', '我们很快就会在诺森德取得胜利……但我们必须在冰冠冰川取得一个立足点，用来为我们的部队提供后勤补给。$B$B征服之岛恰好是一个理想的地点。这里很容易进行防御，而且资源丰富。联盟也看中了这个地方，并派遣第七军团和我们争夺对这座岛屿的控制权。$B$B$N，赶快到那里去，不惜一切代价为部落夺取那个战略要地！', '在征服之岛战场中获得一场胜利，然后向任意部落主城、冬拥湖、达拉然或沙塔斯城中的部落战争使者复命。', '没有东西能够阻挡在我们和完全胜利之间。为了部落!', '联盟被赶出战场了吗?', '征服之岛的胜利', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14166, '死者的感激', '真高兴能再次见到朋友和亲人，不过也许我做得有些太夸张了……我已经吃光了他们为我准备的一切！$B$B能不能帮我一个忙，再给我拿来一些那种美味的悼念糕饼？我会非常感激你的……$B$B我想，那边的查普曼正在出售食谱。', '弄到悼念糕饼，并把它交给达拉然墓地的欢快的达拉然灵魂。$B$B你必须使用一朵橙菊，才能看到那个隐形的灵魂。', '喔，更多美味的亡者面包，感谢你!$B$B请收下这个当作回报…一点节日的小娱乐。', '你有亡者面包吗?', '', '去晶歌森林找达拉然的欢快的达拉然灵魂。', '', '', '', '');
