INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14175, '死者的感激', '真高兴能再次见到朋友和亲人，不过也许我做得有些太夸张了……我已经吃光了他们为我准备的一切！$B$B能不能帮我一个忙，再给我拿来一些那种美味的悼念糕饼？我会非常感激你的……$B$B我想，那边的查普曼正在出售食谱。', '弄到悼念糕饼，并把它交给奥格瑞玛墓地的欢快的兽人灵魂。$B$B你必须使用一朵橙菊，才能看到那个隐形的灵魂。', '喔，更多美味的亡者面包，感谢你!$B$B请收下这个当作回报…一点节日的小\r\n娱乐。', '你有亡者面包吗?', '', '去找杜隆塔尔的欢快的兽人灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14176, '死者的感激', '真高兴能再次见到朋友和亲人，不过也许我做得有些太夸张了……我已经吃光了他们为我准备的一切！$B$B能不能帮我一个忙，再给我拿来一些那种美味的悼念糕饼？我会非常感激你的……$B$B我想，那边的查普曼正在出售食谱。', '弄到悼念糕饼，并把它交给雷霆崖墓地的欢快的牛头人灵魂。$B$B你必须使用一朵橙菊，才能看到那个隐形的灵魂。', '喔，更多美味的亡者面包，感谢你!$B$B请收下这个当作回报…一点节日的小娱乐。', '你有亡者面包吗?', '', '去找雷霆崖的欢快的牛头人灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14177, '死者的感激', '真高兴能再次见到朋友和亲人，不过也许我做得有些太夸张了……我已经吃光了他们为我准备的一切！$B$B能不能帮我一个忙，再给我拿来一些那种美味的悼念糕饼？我会非常感激你的……$B$B我想，那边的查普曼正在出售食谱。', '弄到悼念糕饼，并把它交给奥格瑞玛墓地的欢快的巨魔灵魂。$B$B你必须使用一朵橙菊，才能看到那个隐形的灵魂。', '喔，更多美味的亡者面包，感谢你!$B$B请收下这个当作回报…一点节日的小娱乐。', '你有亡者面包吗?', '', '去找杜隆塔尔的欢快的巨魔灵魂。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14178, '战斗的召唤：阿拉希盆地', '$g小伙子:姑娘;，在多条战联机同时进行战争的关键在于我们不能让军力过于分布，否则我们就会面临全面溃败的风险。$B$B每一天，我们都要对关键的军力布置进行调整。今天我们必须派遣援军的地方是阿拉希盆地。$B$B赶快到那里去，并带着胜利的消息回来见我，$N决不能允许那些部落的恶徒占据那里本应属于我们的资源！', '在阿拉希盆地战场中获得一场胜利，然后向任意联盟主城、冬拥湖、达拉然或沙塔斯城中的联盟准将复命。', '好消息，$C!如果我们的战术持续运作成功，那么部落要不了多久就得全面撤退了。', '告诉我，$N。你从前线带来了什么消息?', '阿拉希盆地的胜利', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14179, '战斗的召唤：风暴之眼', '对抗部落的战斗是没有尽头的，$N。即使在外域，对于地盘的争夺和世代积累的仇恨同样引发了一场场战斗。$B$B现在，进入风暴之眼，为联盟夺取辉煌的胜利，就像我们在艾泽拉斯做的一样。', '在风暴之眼战场中获得一场胜利，然后向任意联盟主城、冬拥湖、达拉然或沙塔斯城中的联盟准将复命。', '我们只差一步就可以完全战胜部落了。我们不能让敌人占领这个世界或其它地方的任何据点。', '告诉我，$N。你从前线带来了什么消息?', '风暴之眼的胜利', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14180, '战斗的召唤：战歌峡谷', '银翼哨兵正在竭尽全力保卫战歌峡谷中的森林。我们必须援助他们，不只是因为我们热爱森林，更因为那片森林是守护联盟领土的天然屏障。$B$B现在我们比以往任何时候都更需要它们。所以我们必须立刻向那里派遣援军。否则灰谷森林很快就会被部落砍成荒芜地了！', '在战歌峡谷战场中获得一场胜利，然后向任意联盟主城、冬拥湖、达拉然或沙塔斯城中的联盟准将复命。', '干得漂亮，$N。我们不惜任何代价也要维持疆界的完整!', '你从前线带来了什么消息，$N?', '战歌峡谷的胜利', '去找联盟准将。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14181, '战斗的召唤：阿拉希盆地', '阿拉希盆地就要落进联盟的手里了。我们必须立刻向那里派出援军，否则我们在那里的一切努力都将前功尽弃。$B$B不要有任何迟误，$c，赶快到阿拉希盆地去，粉碎那里的敌人。胜利属于部落！', '在阿拉希盆地战场中获得一场胜利，然后向任意部落主城、冬拥湖、达拉然或沙塔斯城中的部落战争使者复命。', '你为部落带来了莫大的荣耀，$N。你今日的胜利将可确保明日无数的胜利!', '你回来了。你带来了胜利的消息吗?', '阿拉希盆地的胜利', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14182, '战斗的召唤：风暴之眼', '我们要在所有地方将敌人击溃，无论是在艾泽拉斯还是外域。$B$B绝不能允许联盟在风暴之眼取得优势。我们要在今天打败他们……等到明天，一切都太迟了！', '在风暴之眼战场中获得一场胜利，然后向任意部落主城、冬拥湖、达拉然或沙塔斯城中的部落战争使者复命。', '你将荣耀带给了我们大家，$N。我们一定会让敌人知道无论我们在何处发现他们都将会战斗到底。', '你回来了!你带来了胜利的消息吗?', '风暴之眼的胜利', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14183, '战斗的召唤：战歌峡谷', '联盟真是一群阴险的敌人，$N。他们竟然以保卫灰谷森林的名义入侵了我们在贫瘠之地的领土。$B$B今天，我们要将敌人彻底从我们的土地上赶走。赶快到战歌峡谷去，夺回本应属于我们的东西！', '在战歌峡谷的战场上赢得一场竞赛，然后去见任意部落主城、冬拥湖、达拉然或者沙塔斯的部落战争使者。', '部落欠你一次人情，$N。你让你的族人以你勇敢防卫我们的大陆为荣。', '你回来了!你带来了胜利的消息吗?', '战歌峡谷的胜利', '去找部落战争使者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14199, '死亡证明：黑骑士', '我的同事大法师提迈尔要求我给你一个重要的警告。你很快就将参与冰冠冰川中银色演武场的冠军的试炼。所以你必须时刻警惕一个可怕的敌人。我们只知道他是黑骑士。$B$B如果你能带来他的灵魂碎片，肯瑞托就会知道这个可怕的敌人已经被除掉了。但如果你失败了，那么你将要付出的很可能是生命的代价。', '达拉然的大法师兰达洛克希望你能带给他一片黑骑士的灵魂碎片。$B$B这个任务只能在英雄难度中完成。', '很高兴看到你征服了整个试炼。你已经成为实至名归的一名勇士了，不光是银色北伐军，在肯瑞托的眼中亦是如此。$B$B我们只希望你已对那位恶徒做出了最后一击，并且从此不会再见到他。', '黑骑士是否毫无预警的出现，正如泰弥亚所预见的一般吗?', '', '去晶歌森林找达拉然的大法师兰达洛克。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14203, '被浸透的配方', '看起来，这张被水浸透的纸上应该是记录着一种烈性酒的酿造配方。也许达拉然“再来一杯”的店主会对这个感兴趣……', '将被浸透的配方交给达拉然城中的克莉丝蒂·斯多克顿。', '真是了不起的发现，$N。我不能让你将它卖给别人，所以我会开出很高的价钱。', '正如我所说的，美酒只配识货的人。', '', '去冰冠冰川找铁墙大坝的克莉丝蒂·斯多克顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14350, '红衣信使', '我们不能直接攻击血色十字军的指挥官，他们身边的防御力量太强大了。不过，抓住猫的办法并不只一个。如果没有了军队，他们也就没有了作恶的力量。$B$B亡灵哨兵们一直在搜索那些十字军在斯坦索姆外围进行活动的情报。每天都有一份报告从他们的指挥中心被送往提尔之手。$r,那些报告就是我们取胜的关键！找到红衣信使，取得那份报告。将它交给纳萨诺斯。', '返回东瘟疫之地，找到并杀死红衣信使，拿到大十字军的命令。$B$B把命令交给纳萨诺斯·凋零者，并等待进一步的指示。', '<纳萨诺斯大笑了起来。>$B$B太好了!我终于等到了一个可以消灭血色十字军神谕者的机会!', '如果你成功了，那你也许可以就此赢得我的尊敬，$C。', '', '去东瘟疫之地找玛瑞斯农场的纳萨诺斯·凋零者。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14356, '毁灭的力量……', '仔细听着， $c。$b$b也许你还不知道，奥格瑞玛现在有了麻烦。在怒焰裂谷深处，一个名为燃刃的阴影议会氏族正在做着各种邪恶的事情。他们主要由兽人组成，我不相信那些连话都说不清楚的粗笨家伙能够妥善利用宝贵的知识。所以你要到那里去，把他们解决掉。$b$b他们应该有两本书。不能让那两本书继续留在燃刃氏族的手里，也不能让它们落尽被遗忘者的手中。你要把它们直接交给我。', '将《暗影法术研究》和《扭曲虚空的魔法》这两本书交给幽暗城的布拉贡·血拳。', '好极了，$C。你在为黑暗女王效力的过程中表现得很出色。你的坚定不移和雄心壮志将极大地帮助黑暗女王实现她的目标。下次再来我这儿吧，也许我会布置其它的任务给你，帮助黑暗女王取代巫妖王，并彻底瓦解天灾军团。', '我还有好几百个任务要执行，$C。你取到书了吗?', '', '去幽暗城找皇家区的布拉贡·血拳。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (14409, '谨慎的回访', '占用你一点时间，$c。$b$b世事无常。我们又一次被迫离开了埃雷萨拉斯废墟，走入外面的世界。我是来研究这座城市的，我不想走远，但是也许你会对这个差事感兴趣。$b$b我的同事准备转至达纳苏斯去找那里的高阶祭司谈谈，希望能借此与他们达成共识。带上这本日记去找神殿中的莫丹特·永影。这东西也许会对他的外交任务有帮助。', '将达罗斯的日记带给身处达纳苏斯的莫丹特·永影。', '噢，这是达洛斯的笔迹。他总是不放过每个进度的小细节。日志中所记载的内容可以协助我们解释当前的情况。$B$B感谢你帮我带来了这个东西，$r。也许当他们了解我们毫无恶意的时候，我们会再次见面。', '看来我可以跟你谈谈。有什么事吗?', '', '去达纳苏斯找月神殿的大法师莫丹特·永影。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24428, '诡秘的事件', '你完成了绝对不可能的任务——黑龙公主的尸体就躺在你的脚边。取下她的头颅，将这颗龙首交给黑爪加尔德斯。', '将奥妮克希亚的头颅交给黑爪加尔德斯。他就在已宰的羔羊旅店的地下室里。', '什么?你是从哪弄到手的?她不是…算了，我想这并不重要。你应当为此获得一些奖赏，这点无庸置疑。', '以诺兹多姆之牙的名义!', '', '去找暴风城的黑爪加尔德斯。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24429, '诡秘的事件', '你完成了绝对不可能的任务——黑龙公主的尸体就躺在你的脚边。取下她的头颅，将这颗龙首交给尼尔鲁·火刃。', '将奥妮克希亚的头颅交给尼尔鲁·火刃。他就在暗影裂口里。', '你带来的头颅是属于…。不，我想我还是别想太多。你的英勇行径应当获得奖赏，这点无庸置疑。', '你带来的该不会是…?!', '', '去找奥格瑞玛的尼尔鲁·火刃。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24431, '被浸透的配方', '看起来，这张被水浸透的纸上应该是记录着一种烈性酒的酿造配方。也许达拉然“再来一杯”的店主会对这个感兴趣……', '将被浸透的配方交给达拉然城中的克莉丝蒂·斯多克顿。', '真是了不起的发现，$N。我不能让你将它卖给别人，所以我会开出很高的价钱。', '正如我所说的，美酒只配识货的人。', '', '去达拉然找再来一杯的克莉丝蒂·斯多克顿。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24442, '克瓦迪尔的进攻计划', '你仔细查看这份缴获的进攻计划，在其中发现了东部王国和卡利姆多的地图。所有大型居民点都在这些地图上被逐一列出。阅读过计划中写明的命令，你了解到克瓦迪尔的将领们策划了一系列毁灭性的袭击行动。$B$B根据这些命令，克瓦迪尔军队将在唤雾者伊戈瓦尔“向迷雾之心征询过意见”之后开始行动。也许你能够阻截从唤雾者洞穴中送出的预兆信息，以此延迟克瓦迪尔的进攻。唤雾者洞穴就在洛斯加尔登陆点的西侧。完成阻截行动之后，你还应该将此事告知裁决者玛蕾尔·图哈特。', '取得迷雾之心，将它和克瓦迪尔进攻计划一同交给银色比武场的裁决者玛蕾尔·图哈特。', '<玛瑞尔收下了攻击计画与预兆水晶，仔细地查看两者。>$B$B干得好，$N，幸亏你的行动早了他们一步。我相信少了这样东西不能拖延多久，但你已经争取到宝贵的时间，让我们得以先行警告部落与联盟的领袖，留意即将逼近的攻击。', '你发现了什么呢，$N?', '', '去冰冠冰川找银色比武场的裁决者玛蕾尔·图哈特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24629, '完美的香水', '$c，看上去你是个能干的家伙。我们来一次双赢的合作如何？$B$B皇冠公司希望将我们最新的节日主题产品小样提供给尽可能多的潜在客户。如果你能帮助我们推广我们的心血之作，也许你能得到一些非常精彩的皇冠公司产品！$B$B朋友，花些力气，我们提供令你满意的报酬，如何？', '用皇冠古龙水瓶向10个人喷洒古龙水。', '干的太好了，$N！人们将蜂拥而至抢购香水，他们也会对之前的试用样品感到惊喜的。$B$B这也是在帮我们摆脱困境。', '香水可不会自动喷，你懂的。$B$B继续吧！', '', '去找任意主城的皇冠公司公关专员。', '发放样品', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24635, '一滴优雅的古龙水', '看起来，你是个颇有事业心的$c。我们做一笔小交易如何？$B$B皇冠公司希望将我们最新的节日主题产品小样提供给尽可能多的潜在客户。如果你能帮助我们推广我们的心血之作，也许你能得到一些非常精彩的皇冠公司产品！$B$B朋友，花些力气，我们提供令你满意的报酬，如何？', '用皇冠古龙水瓶向10个人喷洒古龙水。', '干的太好了，$N！人们将蜂拥而至抢购香水，他们也会对之前的试用样品感到惊喜的。$B$B这也是在帮我们摆脱困境。', '香水可不会自动喷，你懂的。$B$B继续吧！', '', '去找任意主城的皇冠公司公关专员。', '发放样品', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24636, '糖果闪电战', '我知道你在找活干，$c。我们一起可以赚点小钱，你意下如何？$B$B皇冠要向城里的每一位潜在的客户推销我们最新的节日主题的产品样品。如果你能帮我们，我们会送你一些珍贵的皇冠商品的！$B$B我出钱，你出力，怎么样，朋友？', '将皇冠巧克力样品抛掷给10个人。', '干的太好了，$N！人们将蜂拥而至抢购巧克力，他们也会对之前的试用样品感到惊喜的。$B$B这也是在帮我们做促销啊。', '你懂的，巧克力可不会自动分给人们的。$B$B你需要继续工作！', '', '去找任意主城的皇冠公司公关专员。', '发放样品', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24638, '粉碎皇冠药剂公司', '这账本上提到了多处地点，我需要你前去调查并采取相应的行动，伙计。不能再拖下去了。$b$b这是我要你调查的一处地点：就在奥格瑞玛大门外，西面！他们肯定不会干什么好事。到那儿去解决掉他们。$b$b噢，对了，如果你发现了某些危险的大玩意儿需要当场销毁的话，就朝它丢这个炸弹。', '消灭5个皇冠仆从，并使用滑栓的氪金炸弹摧毁在杜隆塔尔的奥格瑞玛大门西方的一台药剂车。然后返回奥格瑞玛，去见侦探斯奈普·滑栓。', '孩子，干的不错啊，这是你应得的。嗯，你明天要是有空还来啊，我这还有别的活儿给你~', '你教他们如何做人了吗？', '', '转至奥格瑞玛，去找力量谷的侦探斯奈普·滑栓。', '摧毁药剂车', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24645, '粉碎皇冠药剂公司', '这账本上提到了多处地点，我需要你前去调查并采取相应的行动，伙计。不能再拖下去了。$b$b这是我要你调查的一处地点：就在银松森林的安伯米尔外面！他们肯定不会干什么好事。到那儿去解决掉他们。$b$b噢，对了，如果你发现了某些危险的大玩意儿需要当场销毁的话，就朝它丢这个炸弹。', '消灭5个皇冠暴徒，并使用滑栓的氪金炸弹摧毁银松森林中安伯米尔外面的一台药剂车。然后返回奥格瑞玛，去见侦探斯奈普·滑栓。', '孩子，干的不错啊，这是你应得的。嗯，你明天要是有空还来啊，我这还有别的活儿给你~', '你教他们如何做人了吗？', '', '转至奥格瑞玛，去找力量谷的侦探斯奈普·滑栓。', '摧毁药剂车', '', '', '');
