INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24803, '卡鲁亚克钓鱼大赛', '', '', '别傻站着！把鱼给我，我会宣布你是获胜者！', '卡鲁亚克通过每周举办大赛一直在延续钓鱼的传统。$B$B奖杯会颁给第一个钓到黑鳍鲨的人，这家伙将会成为北方最出名的钓手……额，至少出名几天吧。$B$B黑鳍鲨最喜欢吃侏儒亚口鱼了，所以通常情况就是你总钓到侏儒亚口鱼而不是黑鳍鲨。', '', '去找荆棘谷的老克莱沃特。', '', '', '', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24806, '祝下次好运', '', '', '嗯，很高兴你去尝试了$R。我不想让你感到你的努力白费，所以我这有点东西要给你。', '今天我们已经是赢家了，年轻的$N。当然，如果你能带给我一条鲨鱼，让我亲眼看到把它放生，我会给你一些东西的。', '', '去找荆棘谷的老克莱沃特。', '', '', '', '');
