INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24849, '热力跟踪', '我最好从头开始说。起初是爱情，$N。那是我一眼就看中的一个地精。$B$B在一起度過甜蜜的一週之後，史尼佛說他收到了一大筆錢，並且要帶我去南海度個長假!你相信嗎? $B$B不管怎么说，他让我收拾好行李，自己去银行、拍卖行和理发店跑趟差，但他再没回来过！我开始意识到他就是个大骗子！', '在暴风城的会计室、拍卖行和理发店寻找斯内维尔·拉斯罗凯特。', '他只告诉我的就是卷款离开此地。然后他就抛弃我了，难道不是吗？$B$B哦，$N，真是傻子才会爱上他，但我又能怎么办？他太迷人了！', '你是谁？', '', '去找暴风城的玛丽恩·桑顿。', '搜索暴风城会计室', '搜索暴风城拍卖行', '搜索暴风城理发店', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24851, '热力跟踪', '我最好从头开始说。起初是爱情，$N。那是我一眼就看中的一个地精。$B$B我们共度了一个星期的美好时光，斯内维尔说他弄到了一大笔钱，打算和我一起去南海度个长假！你能相信吗？$B$B不管怎么说，他让我收拾好行李，自己去银行、拍卖行和理发店跑趟差，但他再没回来过！我开始意识到他就是个大骗子！', '在奥格瑞玛的银行、拍卖行和理发店寻找斯内维尔·拉斯罗凯特。', '他只告诉我的就是卷款离开此地。然后他就抛弃我了，难道不是吗？$B$B哦，$N，真是傻子才会爱上他，但我又能怎么办？他太迷人了！', '你是谁？', '', '去找奥格瑞玛的洛卡。', '已搜索奥格瑞玛的银行', '已搜索奥格瑞玛的拍卖行', '已搜索奥格瑞玛的理发店', '');
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (24857, '纳拉其营地的危机', '在仔细查看了地图之后，你意识到刺背野猪人的酋长正计划着对纳拉其营地展开进一步攻击。$b$b鹰风酋长必须马上得知这个消息。', '将刺背野猪人的进攻计划交给纳拉其营地的鹰风酋长。', '这是非常关键的警报！有了这个情报我们可以召集血蹄村的兄弟来阻击这次进攻。你救了很多$r， $N。', '你一脸紧张，$N。有什么消息吗？', '', '去莫高雷找纳拉其营地的鹰风酋长。', '', '', '', '');
